--
-- TOC entry 5745 (class 1255 OID 119001)
-- Name: add_chips(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_chips(p_user_id uuid, p_amount numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- SECURITY: Validate caller is adding to their own account
    IF p_user_id != auth.uid() THEN
        RAISE EXCEPTION 'Unauthorized: can only add chips to your own account';
    END IF;

    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'Amount must be positive';
    END IF;

    INSERT INTO wallets (user_id, wallet_type, balance)
    VALUES (p_user_id, 'PLAYER', p_amount)
    ON CONFLICT (user_id, wallet_type) 
    DO UPDATE SET balance = wallets.balance + p_amount, updated_at = NOW();
END;
$$;


ALTER FUNCTION public.add_chips(p_user_id uuid, p_amount numeric) OWNER TO postgres;

