--
-- TOC entry 4190 (class 1255 OID 5902813)
-- Name: auto_connect_to_dan_bekavac(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auto_connect_to_dan_bekavac() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  dan_id UUID := '47965354-0e56-43ef-931c-ddaab82af765';
BEGIN
  IF NEW.id = dan_id THEN
    RETURN NEW;
  END IF;

  -- A certification fixture is not a friend (2026-09-05, updated 2026-10-12).
  IF EXISTS (
    SELECT 1 FROM auth.users u
     WHERE u.id = NEW.id 
       AND (u.email LIKE '%.invalid' OR u.email LIKE '%@smarter.poker.local' OR u.email LIKE '%@audit.smarter.poker')
  ) 
  OR NEW.email LIKE '%.invalid' 
  OR NEW.email LIKE '%@smarter.poker.local'
  OR NEW.email LIKE '%@audit.smarter.poker'
  OR NEW.username LIKE 'PostDeploy%' 
  OR NEW.username LIKE 'crest_cert_%'
  OR NEW.username ILIKE 'trivia_%' 
  OR NEW.username LIKE 'Cert%'
  OR NEW.username IN ('tester123', 'testuser123', 'tester_vip_2', 'codex-productio') THEN
    RETURN NEW;
  END IF;

  PERFORM set_config('app.suppress_friend_notifications', 'true', true);

  INSERT INTO public.friendships (user_id, friend_id, status)
  VALUES (NEW.id, dan_id, 'accepted')
  ON CONFLICT (user_id, friend_id) DO NOTHING;

  INSERT INTO public.friendships (user_id, friend_id, status)
  VALUES (dan_id, NEW.id, 'accepted')
  ON CONFLICT (user_id, friend_id) DO NOTHING;

  INSERT INTO public.social_follows (follower_id, following_id)
  VALUES (NEW.id, dan_id)
  ON CONFLICT (follower_id, following_id) DO NOTHING;

  PERFORM set_config('app.suppress_friend_notifications', 'false', true);

  RETURN NEW;
END;
$$;


