--
-- TOC entry 8350 (class 1255 OID 22358286)
-- Name: buy_streak_freeze(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.buy_streak_freeze(p_user_id uuid, p_cost integer, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF p_request_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'a streak freeze request id is required'
    );
  END IF;

  IF v_uid IS NULL AND public.fn_caller_is_engine() THEN
    v_uid := p_user_id;
  END IF;
  IF v_uid IS NULL OR p_user_id IS NULL OR p_user_id <> v_uid THEN
    RETURN public.buy_streak_freeze_serialized_body(
      p_user_id,
      p_cost,
      p_request_id
    );
  END IF;

  PERFORM public.fn_lock_daily_mission_user(v_uid);
  RETURN public.buy_streak_freeze_serialized_body(
    p_user_id,
    p_cost,
    p_request_id
  );
END;
$$;


ALTER FUNCTION public.buy_streak_freeze(p_user_id uuid, p_cost integer, p_request_id uuid) OWNER TO postgres;

--
-- TOC entry 3971 (class 1255 OID 17733480)
-- Name: buy_streak_freeze_serialized_body(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.buy_streak_freeze_serialized_body(p_user_id uuid, p_cost integer, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  FREEZE_COST constant integer := 5000;
  MAX_FREEZES constant integer := 3;
  v_uid uuid := auth.uid();
  v_state public.challenge_streak_state%ROWTYPE;
  v_deduct jsonb;
  v_after integer;
  v_reference_id text;
  v_balance integer;
BEGIN
  IF v_uid IS NULL AND public.fn_caller_is_engine() THEN v_uid := p_user_id; END IF;
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authenticated');
  END IF;
  IF p_user_id IS NULL OR p_user_id <> v_uid THEN
    RETURN jsonb_build_object('success', false, 'error', 'cannot buy a freeze for another player');
  END IF;
  IF p_cost IS DISTINCT FROM FREEZE_COST THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'streak freeze price changed; refresh and try again',
      'expectedCost', FREEZE_COST);
  END IF;

  v_reference_id := CASE WHEN p_request_id IS NULL THEN NULL
    ELSE 'streak_freeze:' || v_uid::text || ':' || p_request_id::text END;

  INSERT INTO public.challenge_streak_state (user_id) VALUES (v_uid)
  ON CONFLICT (user_id) DO NOTHING;
  SELECT * INTO v_state FROM public.challenge_streak_state
   WHERE user_id = v_uid FOR UPDATE;

  -- The diamond receipt is committed atomically with the inventory increment.
  -- A retry must observe it before any mutable refusal, especially at 3/3.
  IF v_reference_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.diamond_transactions
     WHERE user_id = v_uid AND reference_id = v_reference_id
  ) THEN
    SELECT COALESCE(diamonds, 0)::integer INTO v_balance FROM public.profiles WHERE id = v_uid;
    RETURN jsonb_build_object(
      'success', true, 'alreadyPurchased', true,
      'freezesAvailable', v_state.freezes_available,
      'diamondsSpent', 0, 'diamondBalance', COALESCE(v_balance, 0));
  END IF;

  IF v_state.freezes_available >= MAX_FREEZES THEN
    SELECT COALESCE(diamonds, 0)::integer INTO v_balance FROM public.profiles WHERE id = v_uid;
    RETURN jsonb_build_object(
      'success', false,
      'error', 'You already hold the maximum of ' || MAX_FREEZES || ' streak freezes',
      'freezesAvailable', v_state.freezes_available,
      'diamondBalance', COALESCE(v_balance, 0));
  END IF;

  v_deduct := public.deduct_diamonds(
    p_user_id := v_uid, p_amount := FREEZE_COST,
    p_description := 'Streak freeze', p_transaction_type := 'streak_freeze',
    p_source := 'streak_freeze',
    p_metadata := jsonb_build_object('freezes_before', v_state.freezes_available),
    p_reference_id := v_reference_id, p_cooldown_seconds := 0
  );
  IF COALESCE((v_deduct->>'success')::boolean, false) = false THEN
    RETURN jsonb_build_object(
      'success', false, 'error', COALESCE(v_deduct->>'error', 'not enough diamonds'),
      'diamondBalance', COALESCE((v_deduct->>'balance')::integer, 0));
  END IF;
  IF COALESCE((v_deduct->>'idempotent')::boolean, false) THEN
    RETURN jsonb_build_object(
      'success', true, 'alreadyPurchased', true,
      'freezesAvailable', v_state.freezes_available,
      'diamondsSpent', 0,
      'diamondBalance', COALESCE((v_deduct->>'balance')::integer, 0));
  END IF;

  UPDATE public.challenge_streak_state
     SET freezes_available = freezes_available + 1, updated_at = now()
   WHERE user_id = v_uid RETURNING freezes_available INTO v_after;
  RETURN jsonb_build_object(
    'success', true, 'alreadyPurchased', false,
    'freezesAvailable', v_after, 'diamondsSpent', FREEZE_COST,
    'diamondBalance', COALESCE((v_deduct->>'balance')::integer, 0));
END;
$$;


ALTER FUNCTION public.buy_streak_freeze_serialized_body(p_user_id uuid, p_cost integer, p_request_id uuid) OWNER TO postgres;

--
-- TOC entry 7364 (class 1255 OID 95129752)
-- Name: ca_append_hand_fact_revision(uuid, uuid, text, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_append_hand_fact_revision(p_hand_id uuid, p_user_id uuid, p_kind text, p_patch jsonb, p_source_reference text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_fact public.ca_hand_facts%ROWTYPE;
  v_prior jsonb;
  v_result jsonb;
  v_hash text;
  v_existing public.ca_hand_fact_revisions%ROWTYPE;
BEGIN
  IF current_user NOT IN ('postgres','service_role') THEN
    RAISE EXCEPTION 'ca_append_hand_fact_revision is service only' USING ERRCODE='42501';
  END IF;
  IF p_idempotency_key IS NULL OR p_kind NOT IN ('correction','void','refund')
     OR length(btrim(COALESCE(p_source_reference,''))) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'hand fact revision refused (invalid_identity)';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'ca-hand-fact-revision:'||p_idempotency_key::text,0));
  SELECT * INTO v_existing FROM public.ca_hand_fact_revisions
   WHERE idempotency_key=p_idempotency_key;
  IF FOUND THEN
    v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
      'hand_id',p_hand_id,'user_id',p_user_id,'kind',p_kind,'patch',p_patch,
      'source_reference',p_source_reference)::text,'UTF8'),'sha256'),'hex');
    IF v_existing.source_hash IS DISTINCT FROM v_hash THEN
      RAISE EXCEPTION 'hand fact revision refused (idempotency_conflict)';
    END IF;
    RETURN jsonb_build_object('ok',true,'replay',true,'revision_id',v_existing.id);
  END IF;

  SELECT * INTO v_fact FROM public.ca_hand_facts
   WHERE hand_id=p_hand_id AND user_id=p_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'hand fact revision refused (fact_unavailable)'; END IF;
  v_prior:=to_jsonb(v_fact);
  IF p_kind='void' THEN
    IF p_patch IS NOT NULL AND p_patch <> '{}'::jsonb THEN
      RAISE EXCEPTION 'hand fact revision refused (void_has_patch)';
    END IF;
    v_result:=NULL;
  ELSE
    IF jsonb_typeof(p_patch) IS DISTINCT FROM 'object' OR p_patch='{}'::jsonb
       OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_patch) k
                   WHERE k NOT IN ('invested','returned','net','net_bb','rake_paid',
                                   'ev_returned','ev_net','ev_net_bb'))
       OR EXISTS (SELECT 1 FROM jsonb_each(p_patch) e WHERE jsonb_typeof(e.value)<>'number') THEN
      RAISE EXCEPTION 'hand fact revision refused (invalid_patch)';
    END IF;
    v_result:=v_prior||p_patch;
    IF (v_result->>'invested')::numeric<0 OR (v_result->>'returned')::numeric<0
       OR (v_result->>'rake_paid')::numeric<0 OR (v_result->>'big_blind')::numeric<=0
       OR abs((v_result->>'net')::numeric -
              ((v_result->>'returned')::numeric-(v_result->>'invested')::numeric))>0.005
       OR abs((v_result->>'net_bb')::numeric -
              ((v_result->>'net')::numeric/(v_result->>'big_blind')::numeric))>0.005 THEN
      RAISE EXCEPTION 'hand fact revision refused (money_invariant)';
    END IF;
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'hand_id',p_hand_id,'user_id',p_user_id,'kind',p_kind,'patch',p_patch,
    'source_reference',p_source_reference)::text,'UTF8'),'sha256'),'hex');
  INSERT INTO public.ca_hand_fact_revisions
    (idempotency_key,hand_id,user_id,kind,source_reference,patch,prior_fact,resulting_fact,source_hash)
  VALUES(p_idempotency_key,p_hand_id,p_user_id,p_kind,p_source_reference,p_patch,
         v_prior,v_result,v_hash);

  IF p_kind='void' THEN
    DELETE FROM public.ca_hand_transfers
     WHERE hand_id=p_hand_id AND (winner_id=p_user_id OR loser_id=p_user_id);
    DELETE FROM public.ca_hand_facts WHERE hand_id=p_hand_id AND user_id=p_user_id;
    DELETE FROM public.ca_hand_player_stat WHERE hand_id=p_hand_id AND user_id=p_user_id;
    DELETE FROM public.ca_hand_player_idx WHERE hand_id=p_hand_id AND user_id=p_user_id;
  ELSE
    UPDATE public.ca_hand_facts SET
      invested=(v_result->>'invested')::numeric,
      returned=(v_result->>'returned')::numeric,
      net=(v_result->>'net')::numeric,
      net_bb=(v_result->>'net_bb')::numeric,
      rake_paid=(v_result->>'rake_paid')::numeric,
      ev_returned=CASE WHEN v_result->'ev_returned'='null'::jsonb THEN NULL ELSE (v_result->>'ev_returned')::numeric END,
      ev_net=(v_result->>'ev_net')::numeric,
      ev_net_bb=(v_result->>'ev_net_bb')::numeric,
      source_hash=v_hash
    WHERE hand_id=p_hand_id AND user_id=p_user_id;
    UPDATE public.ca_hand_player_stat SET
      won_amt=(v_result->>'returned')::numeric,
      profit=(v_result->>'net')::numeric,
      is_winner=((v_result->>'net')::numeric>0)
    WHERE hand_id=p_hand_id AND user_id=p_user_id;
    -- Transfers are attribution, not authoritative money. A correction/refund
    -- cannot safely reconstruct side-pot ownership, so remove affected rows
    -- instead of presenting stale opponent flow as exact.
    DELETE FROM public.ca_hand_transfers
     WHERE hand_id=p_hand_id AND (winner_id=p_user_id OR loser_id=p_user_id);
  END IF;
  RETURN jsonb_build_object('ok',true,'replay',false,'source_hash',v_hash,
    'kind',p_kind,'hand_id',p_hand_id,'user_id',p_user_id);
END
$$;


ALTER FUNCTION public.ca_append_hand_fact_revision(p_hand_id uuid, p_user_id uuid, p_kind text, p_patch jsonb, p_source_reference text, p_idempotency_key uuid) OWNER TO postgres;

--
-- TOC entry 7179 (class 1255 OID 93130306)
-- Name: ca_assert_player_stats_club(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_assert_player_stats_club(p_user uuid, p_club_id uuid, p_asset text DEFAULT 'chips'::text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.ca_assert_self(p_user);
  IF p_club_id IS NULL THEN
    RAISE EXCEPTION 'club is required' USING ERRCODE = '22023';
  END IF;
  IF p_asset IS NULL OR p_asset NOT IN ('chips', 'diamonds') THEN
    RAISE EXCEPTION 'unknown stats asset: %', p_asset USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.club_members m
    JOIN public.clubs c ON c.id = m.club_id
    WHERE m.club_id = p_club_id
      AND m.user_id = p_user
      AND m.status IN ('active', 'approved')
      AND coalesce(c.lifecycle_status, 'active') <> 'retired'
      AND coalesce(c.asset, 'chips') = p_asset
  ) THEN
    RAISE EXCEPTION 'not authorized for stats club' USING ERRCODE = '42501';
  END IF;
END;
$$;


