-- TOC entry 9556 (class 1255 OID 14772625)
-- Name: ca_assert_self(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_assert_self(p_user uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF coalesce(auth.role(), '') = 'service_role' THEN
    RETURN;
  END IF;
  IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_user THEN
    RAISE EXCEPTION 'forbidden: this data is readable only by its owner'
      USING ERRCODE = '42501';
  END IF;
END $$;


