-- TOC entry 4689 (class 1255 OID 116024280)
-- Name: ca_club_chip_ledger(uuid, integer, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_chip_ledger(p_club_id uuid, p_limit integer DEFAULT 25, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_include_hand_rows boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payload jsonb;
BEGIN
  v_payload := public.ca_club_chip_ledger_core_20261006(
    p_club_id,
    p_limit,
    p_before,
    p_include_hand_rows
  );
  IF jsonb_typeof(v_payload) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'club chip ledger core returned a malformed payload';
  END IF;
  RETURN v_payload || jsonb_build_object(
    'contract', 'ca_club_chip_ledger.v2',
    'contract_version', 2,
    'club_id', p_club_id,
    'requested_limit', p_limit,
    'requested_before', p_before,
    'requested_include_hand_rows', p_include_hand_rows
  );
END;
$$;


