-- TOC entry 44520 (class 0 OID 0)
-- Dependencies: 4689
-- Name: FUNCTION ca_club_chip_ledger(p_club_id uuid, p_limit integer, p_before timestamp with time zone, p_include_hand_rows boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_chip_ledger(p_club_id uuid, p_limit integer, p_before timestamp with time zone, p_include_hand_rows boolean) IS 'Club chip-ledger v2. Returns an exact contract, club and page request receipt around immutable movements, including an empty row set.';


--
-- TOC entry 8827 (class 1255 OID 20927926)
-- Name: ca_club_chip_ledger_core_20261006(uuid, integer, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_chip_ledger_core_20261006(p_club_id uuid, p_limit integer DEFAULT 25, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_include_hand_rows boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit integer := GREATEST(LEAST(coalesce(p_limit, 25), 100), 1);
  v jsonb;
BEGIN
  IF NOT ca_can_view_club_finances(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  WITH page AS (
    SELECT l.id, l.performed_by, l.from_type, l.from_entity_id, l.from_label,
           l.to_type, l.to_entity_id, l.to_label, l.amount, l.category,
           l.description, l.created_at, l.club_id, l.union_id, l.table_id,
           l.tournament_id, l.status
      FROM chip_ledger l
     WHERE l.club_id = p_club_id
       AND (p_before IS NULL OR l.created_at < p_before)
       AND (coalesce(p_include_hand_rows, false)
            OR l.category NOT IN ('rake', 'bbj_contribution'))
     ORDER BY l.created_at DESC
     LIMIT v_limit + 1
  )
  SELECT jsonb_build_object(
    'rows', coalesce((
      SELECT jsonb_agg(to_jsonb(p) ORDER BY p.created_at DESC)
      FROM (SELECT * FROM page ORDER BY created_at DESC LIMIT v_limit) p
    ), '[]'::jsonb),
    'has_more', (SELECT count(*) FROM page) > v_limit,
    'next_before', (SELECT min(p.created_at) FROM (SELECT * FROM page ORDER BY created_at DESC LIMIT v_limit) p),
    'hand_rows_included', coalesce(p_include_hand_rows, false),
    'generated_at', now()
  ) INTO v;

  RETURN v;
END;
$$;


