COMMENT ON FUNCTION public.ca_club_dashboard_stats(p_club_id uuid) IS 'Club dashboard metric cards and 14-day series, read from the per-hand rollup in one pass. seated_now counts distinct people since 2026-09-04 (it counted seat rows before). Membership-gated by ca_can_view_club.';


--
-- TOC entry 4282 (class 1255 OID 18109380)
-- Name: ca_club_data_export_cancel(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_data_export_cancel(p_export_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_deleted integer := 0;
BEGIN
  IF v_user IS NULL OR p_export_id IS NULL THEN
    RETURN false;
  END IF;

  DELETE FROM public.ca_club_data_exports cancelled_job
   USING (
     SELECT owned_job.id
       FROM public.ca_club_data_exports owned_job
      WHERE owned_job.id = p_export_id
        AND owned_job.user_id = v_user
      FOR UPDATE SKIP LOCKED
   ) owned
   WHERE cancelled_job.id = owned.id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  -- Anyone's stranded expired job: bounded and non-blocking.
  PERFORM public.ca_prune_expired_club_data_exports(2000);

  RETURN v_deleted = 1;
END;
$$;


