--
-- TOC entry 8093 (class 1255 OID 116024279)
-- Name: ca_club_financials(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_financials(p_club_id uuid, p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payload jsonb;
BEGIN
  v_payload := public.ca_club_financials_core_20261006(p_club_id, p_start, p_end);
  IF jsonb_typeof(v_payload) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'club financials core returned a malformed payload';
  END IF;
  RETURN v_payload || jsonb_build_object(
    'contract', 'ca_club_financials.v2',
    'contract_version', 2,
    'club_id', p_club_id,
    'requested_start', p_start,
    'requested_end', p_end
  );
END;
$$;


