CREATE FUNCTION public.ca_club_game_page(p_club_id uuid, p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_game text DEFAULT 'ALL'::text, p_stakes text DEFAULT 'ALL'::text, p_search text DEFAULT NULL::text, p_sort text DEFAULT 'recent'::text, p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payload jsonb;
BEGIN
  v_payload := public.ca_club_game_page_core_20261006(
    p_club_id,
    p_start,
    p_end,
    p_game,
    p_stakes,
    p_search,
    p_sort,
    p_cursor,
    p_limit
  );
  IF jsonb_typeof(v_payload) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'club game page core returned a malformed payload';
  END IF;
  RETURN v_payload || jsonb_build_object(
    'contract', 'ca_club_game_page.v2',
    'contract_version', 2,
    'club_id', p_club_id,
    'requested_start', p_start,
    'requested_end', p_end,
    'requested_game', p_game,
    'requested_stakes', p_stakes,
    'requested_search', p_search,
    'requested_sort', p_sort,
    'requested_cursor', p_cursor,
    'requested_limit', p_limit
  );
END;
$$;


