--
-- TOC entry 3895 (class 1255 OID 218980469)
-- Name: ca_club_member_upline_chain(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_member_upline_chain(p_club_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_access text := public.ca_club_roster_access(p_club_id, p_user_id);
  v_owner  uuid;
  v_out    jsonb;
BEGIN
  IF v_access IS NULL OR v_access NOT IN ('staff', 'downline', 'service') THEN
    RETURN NULL;
  END IF;

  SELECT c.owner_id INTO v_owner FROM public.clubs c WHERE c.id = p_club_id;

  WITH RECURSIVE chain AS (
    SELECT first_agent.agent_id AS uid, 1 AS depth,
           ARRAY[p_user_id, first_agent.agent_id] AS path
      FROM (
        SELECT cm.agent_id
          FROM public.club_members cm
         WHERE cm.club_id = p_club_id AND cm.user_id = p_user_id
           AND coalesce(cm.status, 'approved') IN ('active', 'approved')
         ORDER BY public.fn_club_role_rank(cm.role) DESC, cm.joined_at ASC
         LIMIT 1
      ) first_agent
     WHERE first_agent.agent_id IS NOT NULL AND first_agent.agent_id <> p_user_id
    UNION ALL
    SELECT nxt.agent_id, c.depth + 1, c.path || nxt.agent_id
      FROM chain c
      CROSS JOIN LATERAL (
        SELECT cm.agent_id
          FROM public.club_members cm
         WHERE cm.club_id = p_club_id AND cm.user_id = c.uid
           AND coalesce(cm.status, 'approved') IN ('active', 'approved')
         ORDER BY public.fn_club_role_rank(cm.role) DESC, cm.joined_at ASC
         LIMIT 1
      ) nxt
     WHERE nxt.agent_id IS NOT NULL
       AND c.uid IS DISTINCT FROM v_owner          -- the owner is the top; stop there
       AND nxt.agent_id IS DISTINCT FROM v_owner   -- never print the owner above an agent
       AND NOT nxt.agent_id = ANY (c.path)
       AND c.depth < 20
  ),
  levels AS (
    SELECT c.uid, c.depth, true AS assigned FROM chain c
    UNION ALL
    -- No agent: the player sits directly under the club owner.
    SELECT v_owner, 1, false
     WHERE v_owner IS NOT NULL AND v_owner <> p_user_id
       AND NOT EXISTS (SELECT 1 FROM chain)
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'depth', l.depth,
           'user_id', l.uid,
           'name', coalesce(nullif(btrim(u.alias), ''),
                            nullif(btrim(public.fn_arena_name(u.alias, u.username, u.display_name, u.first_name, u.last_name, u.full_name)), ''),
                            u.username),
           'player_number', u.player_number,
           'role', coalesce(r.role, CASE WHEN l.uid = v_owner THEN 'owner' END),
           'assigned', l.assigned
         ) ORDER BY l.depth), '[]'::jsonb)
    INTO v_out
    FROM levels l
    JOIN public.profiles u ON u.id = l.uid AND u.status IS DISTINCT FROM 'deleted'
    LEFT JOIN LATERAL (
      SELECT cm.role
        FROM public.club_members cm
       WHERE cm.club_id = p_club_id AND cm.user_id = l.uid
         AND coalesce(cm.status, 'approved') IN ('active', 'approved')
       ORDER BY public.fn_club_role_rank(cm.role) DESC, cm.joined_at ASC
       LIMIT 1
    ) r ON true;

  RETURN v_out;
END;
$$;


ALTER FUNCTION public.ca_club_member_upline_chain(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 8058 (class 1255 OID 181178762)
-- Name: ca_club_member_win_loss(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_member_win_loss(p_club_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_access text := public.ca_club_roster_access(p_club_id, p_user_id);
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_week date := date_trunc('week', v_today)::date;
  v_month date := date_trunc('month', v_today)::date;
  v_earliest date;
  v_cash_today numeric; v_cash_week numeric; v_cash_month numeric; v_cash_all numeric;
  v_mtt_today numeric; v_mtt_week numeric; v_mtt_month numeric; v_mtt_all numeric;
BEGIN
  IF v_access IS NULL OR v_access NOT IN ('staff', 'downline', 'service') THEN
    RETURN NULL;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.club_member_daily_facts_state WHERE singleton AND initialized)
  THEN RAISE EXCEPTION 'Member daily facts are not initialized'; END IF;

  -- A week that started last month reaches back past the 1st.
  v_earliest := least(v_week, v_month);

  SELECT coalesce(sum(f.net) FILTER (WHERE f.played_on = v_today), 0),
         coalesce(sum(f.net) FILTER (WHERE f.played_on >= v_week), 0),
         coalesce(sum(f.net) FILTER (WHERE f.played_on >= v_month), 0)
    INTO v_cash_today, v_cash_week, v_cash_month
    FROM public.ca_member_record_daily_facts(p_club_id,p_user_id,v_earliest,v_today) f
   WHERE f.club_id = p_club_id AND f.user_id = p_user_id
     AND NOT f.is_mtt
     AND f.played_on >= v_earliest AND f.played_on <= v_today;

  SELECT coalesce(sum(t.net) FILTER(WHERE NOT t.is_mtt), 0) INTO v_cash_all
    FROM (SELECT 1) anchor
    LEFT JOIN public.ca_member_record_daily_facts(p_club_id,p_user_id,NULL,NULL) t
      ON t.club_id = p_club_id AND t.user_id = p_user_id;

  v_mtt_today := public.ca_club_member_tournament_money(
    p_club_id, p_user_id, v_today::timestamp AT TIME ZONE 'UTC', NULL);
  v_mtt_week := public.ca_club_member_tournament_money(
    p_club_id, p_user_id, v_week::timestamp AT TIME ZONE 'UTC', NULL);
  v_mtt_month := public.ca_club_member_tournament_money(
    p_club_id, p_user_id, v_month::timestamp AT TIME ZONE 'UTC', NULL);
  v_mtt_all := public.ca_club_member_tournament_money(p_club_id, p_user_id, NULL, NULL);

  RETURN jsonb_build_object(
    'as_of', v_today,
    'week_from', v_week,
    'month_from', v_month,
    'today', jsonb_build_object('cash', round(v_cash_today, 2), 'mtt', round(v_mtt_today, 2),
                                'net', round(v_cash_today + v_mtt_today, 2)),
    'week', jsonb_build_object('cash', round(v_cash_week, 2), 'mtt', round(v_mtt_week, 2),
                               'net', round(v_cash_week + v_mtt_week, 2)),
    'month', jsonb_build_object('cash', round(v_cash_month, 2), 'mtt', round(v_mtt_month, 2),
                                'net', round(v_cash_month + v_mtt_month, 2)),
    'overall', jsonb_build_object('cash', round(v_cash_all, 2), 'mtt', round(v_mtt_all, 2),
                                  'net', round(v_cash_all + v_mtt_all, 2))
  );
END;
$$;


ALTER FUNCTION public.ca_club_member_win_loss(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 3674 (class 1255 OID 14229365)
-- Name: ca_club_members(uuid, text, timestamp with time zone, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_members(p_club_id uuid, p_search text DEFAULT NULL::text, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_sort text DEFAULT 'hands'::text, p_role text DEFAULT NULL::text) RETURNS TABLE(user_id uuid, display_name text, avatar_url text, is_horse boolean, is_online boolean, role text, status text, joined_at timestamp with time zone, last_active timestamp with time zone, chip_balance numeric, hands_played bigint, profit numeric, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_search   text := nullif(btrim(coalesce(p_search, '')), '');
  v_role     text := nullif(btrim(coalesce(p_role, '')), '');
  v_sort     text := lower(coalesce(p_sort, 'hands'));
  v_may_see  boolean := public.fn_can_see_horse_flag(p_club_id);
  v_actor    uuid := auth.uid();
  v_service  boolean := coalesce(auth.role(), 'service_role') = 'service_role';
  v_all      boolean := false;
  v_agent    boolean := false;
  v_cutoff   timestamptz := public.fn_ca_launch_accounting_cutoff('club', p_club_id);
  v_from_day date := CASE WHEN p_since IS NULL THEN NULL ELSE (p_since AT TIME ZONE 'UTC')::date END;
  v_from_ts  timestamptz;
BEGIN
  IF NOT ca_can_view_club(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;
  v_from_ts := CASE WHEN v_from_day IS NULL THEN NULL ELSE v_from_day::timestamp AT TIME ZONE 'UTC' END;

  -- MONEY IS A PER-ROW DECISION (2026-10-19). The same rule as
  -- ca_club_roster_access(p_club_id, target) IN ('staff','downline','service'),
  -- evaluated once per call instead of once per row: platform admin, union
  -- overseer and exact-club owner/co_owner/admin see every row; an exact-club
  -- agent sees themself and their active downline; everyone else sees identity
  -- and presence only. Balance, hands, Win/Loss and last active are NULL, and
  -- sorting by them cannot rank rows the viewer may not see.
  IF v_service THEN
    v_all := true;
  ELSIF v_actor IS NOT NULL THEN
    v_all := EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = v_actor AND coalesce(p.is_admin, false))
      OR coalesce(public.fn_is_union_overseer(p_club_id, v_actor), false)
      OR EXISTS (SELECT 1 FROM public.club_members a
                  WHERE a.user_id = v_actor AND a.club_id = p_club_id
                    AND a.role IN ('owner', 'co_owner', 'admin')
                    AND coalesce(a.status, 'approved') IN ('active', 'approved'));
    IF NOT v_all THEN
      v_agent := EXISTS (SELECT 1 FROM public.club_members a
                          WHERE a.user_id = v_actor AND a.club_id = p_club_id
                            AND a.role IN ('super_agent', 'agent', 'sub_agent')
                            AND coalesce(a.status, 'approved') IN ('active', 'approved'));
    END IF;
  END IF;

  RETURN QUERY
  WITH RECURSIVE edges AS MATERIALIZED (
    SELECT cm.agent_id AS parent, cm.user_id AS child
      FROM public.club_members cm
     WHERE v_agent AND cm.club_id = p_club_id AND cm.agent_id IS NOT NULL
       AND cm.agent_id <> cm.user_id
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
  ), tree AS (
    SELECT e.child, 1 AS depth FROM edges e WHERE e.parent = v_actor
    UNION ALL
    SELECT e.child, t.depth + 1 FROM tree t JOIN edges e ON e.parent = t.child WHERE t.depth < 20
  ), downline AS MATERIALIZED (
    SELECT DISTINCT t.child AS uid FROM tree t
    UNION SELECT v_actor WHERE v_agent
  ), seated AS MATERIALIZED (
    -- Union tables file their seats under the member's club (ts.club_id), not
    -- the table's own club; count both, as ca_club_roster_rows does.
    SELECT DISTINCT live.uid
      FROM (
        SELECT ts.user_id AS uid
          FROM public.table_seats ts JOIN public.tables t ON t.id = ts.table_id
         WHERE ts.left_at IS NULL AND ts.user_id IS NOT NULL
           AND ts.club_id = p_club_id AND t.status IN ('waiting', 'running')
        UNION
        SELECT ts.user_id
          FROM public.tables t JOIN public.table_seats ts ON ts.table_id = t.id
         WHERE ts.left_at IS NULL AND ts.user_id IS NOT NULL
           AND t.club_id = p_club_id AND t.status IN ('waiting', 'running')
      ) live
  ), roster AS MATERIALIZED (
    SELECT DISTINCT ON (cm.user_id)
           cm.user_id AS uid,
           coalesce(cm.role, 'member') AS m_role,
           coalesce(cm.status, 'approved') AS m_status,
           coalesce(cm.joined_at, cm.created_at) AS m_joined,
           cm.chip_balance::numeric AS m_chip,
           cm.last_active_at AS m_last_active_at,
           coalesce(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name), cm.display_name, 'Player') AS m_name,
           pr.avatar_url AS m_avatar,
           (v_may_see AND coalesce(pr.is_horse, false)) AS m_horse,
           (s.uid IS NOT NULL
            OR (coalesce(pr.is_online, false) AND pr.last_seen > now() - interval '5 minutes')) AS m_online,
           greatest(pr.last_login, pr.last_seen, cm.last_active_at) AS m_last_active,
           (v_all OR d.uid IS NOT NULL) AS sensitive
      FROM public.club_members cm
      LEFT JOIN public.profiles pr ON pr.id = cm.user_id
      LEFT JOIN seated s ON s.uid = cm.user_id
      LEFT JOIN downline d ON d.uid = cm.user_id
     WHERE cm.club_id = p_club_id
       AND (NOT v_agent OR d.uid IS NOT NULL)
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
       AND pr.status IS DISTINCT FROM 'deleted'
       AND (v_search IS NULL
            OR coalesce(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name), cm.display_name, '') ILIKE '%' || v_search || '%')
       AND (v_role IS NULL OR coalesce(cm.role, 'member') = v_role)
     ORDER BY cm.user_id, public.fn_club_role_rank(cm.role) DESC, cm.joined_at ASC
  ), facts AS MATERIALIZED (
    -- Funded-club daily facts, as ca_club_roster_rows and the member record read them.
    SELECT f.user_id AS uid,
           sum(f.hands)::bigint AS hands,
           coalesce(sum(f.net) FILTER (WHERE NOT f.is_mtt), 0) AS cash_net
      FROM public.member_record_daily_facts f
      JOIN roster r ON r.uid = f.user_id AND r.sensitive
     WHERE f.club_id = p_club_id
       AND f.accounting_cutoff IS NOT DISTINCT FROM v_cutoff
       AND (v_from_day IS NULL OR f.played_on >= v_from_day)
     GROUP BY f.user_id
  ), mtt_all AS MATERIALIZED (
    -- Only a Win/Loss ranking needs every visible row's tournament money; it
    -- reads ca_club_member_tournament_money itself, so the figure is the one
    -- the member record shows. Any other sort prices only the page below.
    SELECT r.uid, public.ca_club_member_tournament_money(p_club_id, r.uid, v_from_ts, NULL) AS net
      FROM roster r
     WHERE v_sort = 'profit' AND r.sensitive
  ), shaped AS MATERIALIZED (
    SELECT r.*,
           CASE WHEN r.sensitive THEN coalesce(fa.hands, 0) END AS v_hands,
           CASE WHEN r.sensitive THEN coalesce(fa.cash_net, 0) END AS v_cash,
           CASE WHEN r.sensitive THEN round(coalesce(fa.cash_net, 0) + coalesce(m.net, 0), 2) END AS v_rank_profit
      FROM roster r
      LEFT JOIN facts fa ON fa.uid = r.uid
      LEFT JOIN mtt_all m ON m.uid = r.uid
  ), counted AS (SELECT count(*) AS n FROM shaped),
  ordered AS MATERIALIZED (
    SELECT x.*,
           row_number() OVER (ORDER BY
             CASE WHEN v_sort = 'profit' THEN x.v_rank_profit END DESC NULLS LAST,
             CASE WHEN v_sort = 'hands'  THEN x.v_hands END DESC NULLS LAST,
             CASE WHEN v_sort = 'joined' THEN x.m_joined END DESC NULLS LAST,
             CASE WHEN v_sort = 'last_active' THEN CASE WHEN x.sensitive THEN x.m_last_active END END DESC NULLS LAST,
             CASE WHEN v_sort = 'name'   THEN lower(x.m_name) END ASC NULLS LAST,
             x.m_joined DESC NULLS LAST,
             x.uid) AS rn
      FROM shaped x
  ), page AS MATERIALIZED (
    SELECT o.* FROM ordered o
     WHERE o.rn >  greatest(coalesce(p_offset, 0), 0)
       AND o.rn <= greatest(coalesce(p_offset, 0), 0) + least(greatest(coalesce(p_limit, 50), 1), 200)
  )
  SELECT
    pg.uid, pg.m_name, pg.m_avatar, pg.m_horse, pg.m_online, pg.m_role, pg.m_status, pg.m_joined,
    CASE WHEN pg.sensitive THEN pg.m_last_active END,
    CASE WHEN pg.sensitive THEN coalesce(pg.m_chip, 0) END,
    pg.v_hands::bigint,
    CASE WHEN NOT pg.sensitive THEN NULL
         WHEN v_sort = 'profit' THEN pg.v_rank_profit
         ELSE round(pg.v_cash + public.ca_club_member_tournament_money(p_club_id, pg.uid, v_from_ts, NULL), 2)
    END,
    c.n
  FROM page pg
  CROSS JOIN counted c
  ORDER BY pg.rn;
END;
$$;


ALTER FUNCTION public.ca_club_members(p_club_id uuid, p_search text, p_since timestamp with time zone, p_limit integer, p_offset integer, p_sort text, p_role text) OWNER TO postgres;

--
-- TOC entry 6409 (class 1255 OID 17734132)
-- Name: ca_club_members_export(uuid, text, text, text, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_members_export(p_club_id uuid, p_search text DEFAULT ''::text, p_filter text DEFAULT 'all'::text, p_sort text DEFAULT 'hierarchy'::text, p_user_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_scope uuid[] := public.fn_club_scope_ids(p_club_id);
  v_service boolean := coalesce(auth.role(), 'service_role') = 'service_role';
  v_platform_admin boolean := false;
  v_union_staff boolean := false;
  v_staff boolean := false;
  v_actor_role text := 'service_role';
  v_search text := lower(left(btrim(coalesce(p_search, '')), 120));
  v_filter text := lower(coalesce(nullif(btrim(p_filter), ''), 'all'));
  v_sort text := lower(coalesce(nullif(btrim(p_sort), ''), 'hierarchy'));
  v_rows jsonb;
  v_count int := 0;
  v_audit_id uuid;
BEGIN
  IF v_filter NOT IN ('all', 'mine', 'seated', 'online', 'agents', 'admins',
    'inactive_30', 'inactive_60', 'inactive_90', 'high_fees') THEN v_filter := 'all'; END IF;
  IF v_sort NOT IN ('newest', 'oldest', 'hierarchy', 'activity', 'name', 'downlines', 'wallet', 'fees') THEN v_sort := 'hierarchy'; END IF;
  IF coalesce(array_length(p_user_ids, 1), 0) > 5000 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Select No More Than 5,000 Players Per Export';
  END IF;

  IF v_scope IS NULL OR array_length(v_scope, 1) IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Club Not Found');
  END IF;

  IF NOT v_service AND v_actor IS NOT NULL THEN
    SELECT coalesce(p.is_admin, false) INTO v_platform_admin
      FROM public.profiles p WHERE p.id = v_actor;
    v_union_staff := coalesce(public.fn_is_union_overseer(p_club_id, v_actor), false);
    SELECT cm.role INTO v_actor_role
      FROM public.club_members cm
     WHERE cm.user_id = v_actor AND cm.club_id = p_club_id
       AND cm.role IN ('owner', 'co_owner', 'admin')
       AND coalesce(cm.status, 'approved') IN ('active', 'approved')
     ORDER BY public.fn_club_role_rank(cm.role) DESC LIMIT 1;
    v_staff := v_platform_admin OR v_union_staff OR v_actor_role IS NOT NULL;
  ELSE
    v_staff := v_service;
  END IF;

  IF NOT v_staff THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Roster Export Requires Club Staff Access';
  END IF;
  IF v_actor IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Roster Export Requires An Auditable Actor';
  END IF;

  IF v_actor_role IS NULL THEN
    v_actor_role := CASE
      WHEN v_platform_admin THEN 'platform_admin'
      WHEN v_union_staff THEN 'union_admin'
      ELSE 'system'
    END;
  END IF;

  WITH rows AS MATERIALIZED (
    SELECT r.*,
           CASE WHEN r.joined_at IS NULL THEN 1e30::numeric
                WHEN v_sort = 'newest' THEN -extract(epoch FROM r.joined_at)
                ELSE extract(epoch FROM r.joined_at) END AS joined_sort,
           lower(r.alias) AS sort_name,
           CASE WHEN r.is_seated THEN 2 WHEN r.is_online THEN 1 ELSE 0 END AS presence_rank,
           coalesce(extract(epoch FROM r.last_login), 0)::numeric AS activity_epoch,
           coalesce(r.player_wallet, 0) + coalesce(r.agent_wallet, 0) AS wallet_total
      FROM public.ca_club_roster_rows(p_club_id) r
     WHERE r.can_view_financials
       AND (p_user_ids IS NULL OR r.user_id = ANY(p_user_ids))
       AND (
         v_search = '' OR position(v_search in lower(r.alias)) > 0
         OR position(v_search in lower(r.username)) > 0
         OR position(v_search in lower(coalesce(r.player_number, ''))) > 0
         OR position(v_search in lower(coalesce(r.home_club_name, ''))) > 0
         OR position(v_search in lower(coalesce(r.upline_name, ''))) > 0
       )
       AND CASE v_filter
         WHEN 'mine' THEN r.in_viewer_downline
         WHEN 'seated' THEN r.is_seated
         WHEN 'online' THEN r.is_online
         WHEN 'agents' THEN r.role IN ('super_agent', 'agent', 'sub_agent')
         WHEN 'admins' THEN r.role IN ('owner', 'co_owner', 'admin')
         WHEN 'inactive_30' THEN r.last_login IS NOT NULL AND r.last_login < now() - interval '30 days'
         WHEN 'inactive_60' THEN r.last_login IS NOT NULL AND r.last_login < now() - interval '60 days'
         WHEN 'inactive_90' THEN r.last_login IS NOT NULL AND r.last_login < now() - interval '90 days'
         WHEN 'high_fees' THEN coalesce(r.total_fees, 0) >= 100
         ELSE true END
  ), ordered AS (
    SELECT r.* FROM rows r
     ORDER BY
       CASE WHEN v_sort IN ('newest', 'oldest') THEN r.joined_sort END ASC,
       CASE WHEN v_sort IN ('newest', 'oldest') THEN r.user_id END ASC,
       CASE WHEN v_sort = 'hierarchy' THEN r.role_rank END DESC,
       CASE WHEN v_sort = 'hierarchy' THEN coalesce(r.downline_total, 0) END DESC,
       CASE WHEN v_sort = 'activity' THEN r.presence_rank END DESC,
       CASE WHEN v_sort = 'activity' THEN r.activity_epoch END DESC,
       CASE WHEN v_sort = 'name' THEN r.sort_name END ASC,
       CASE WHEN v_sort = 'downlines' THEN coalesce(r.downline_total, 0) END DESC,
       CASE WHEN v_sort = 'wallet' THEN r.wallet_total END DESC,
       CASE WHEN v_sort = 'fees' THEN coalesce(r.total_fees, 0) END DESC,
       r.sort_name ASC, r.user_id ASC
  )
  SELECT coalesce(jsonb_agg(
           to_jsonb(o) - ARRAY['joined_sort', 'sort_name', 'presence_rank', 'activity_epoch', 'wallet_total',
                                  'can_view_financials', 'can_view_notes', 'in_viewer_downline']::text[]
         ), '[]'::jsonb), count(*)::int
    INTO v_rows, v_count
    FROM ordered o;

  INSERT INTO public.audit_trail (
    actor_id, actor_role, action, target_type, target_id, club_id,
    after_state, reason
  ) VALUES (
    v_actor, v_actor_role,
    'export_club_roster', 'club', p_club_id, p_club_id,
    jsonb_build_object(
      'row_count', v_count,
      'selected_only', p_user_ids IS NOT NULL,
      'selected_count', coalesce(array_length(p_user_ids, 1), 0),
      'filter', v_filter,
      'sort', v_sort,
      'search_used', v_search <> ''
    ),
    'Authorized Club Roster Export'
  ) RETURNING id INTO v_audit_id;

  RETURN jsonb_build_object(
    'success', true,
    'rows', v_rows,
    'row_count', v_count,
    'audit_id', v_audit_id
  );
END;
$$;


ALTER FUNCTION public.ca_club_members_export(p_club_id uuid, p_search text, p_filter text, p_sort text, p_user_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 44558 (class 0 OID 0)
-- Dependencies: 6409
-- Name: FUNCTION ca_club_members_export(p_club_id uuid, p_search text, p_filter text, p_sort text, p_user_ids uuid[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_members_export(p_club_id uuid, p_search text, p_filter text, p_sort text, p_user_ids uuid[]) IS 'Staff-only full or selected roster export. Every successful export writes an audit_trail row without storing the search text.';


--
-- TOC entry 8661 (class 1255 OID 15966185)
-- Name: ca_club_members_overview(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_members_overview(p_club_id uuid) RETURNS TABLE(user_id uuid, home_club_id uuid, home_club_name text, player_number text, alias text, username text, display_name text, avatar_url text, role text, role_rank integer, is_online boolean, is_seated boolean, chip_balance numeric, player_wallet numeric, agent_wallet numeric, promo_wallet numeric, total_fees numeric, downline_fees numeric, total_hands bigint, downline_direct integer, downline_total integer, upline_user_id uuid, upline_name text, joined_at timestamp with time zone, last_login timestamp with time zone, nickname text, remark text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT r.user_id, r.home_club_id, r.home_club_name, r.player_number,
         r.alias, r.username, r.display_name, r.avatar_url, r.role, r.role_rank,
         r.is_online, r.is_seated, r.chip_balance, r.player_wallet,
         r.agent_wallet, r.promo_wallet, r.total_fees, r.downline_fees,
         r.total_hands, r.downline_direct, r.downline_total, r.upline_user_id,
         r.upline_name, r.joined_at, r.last_login, r.nickname, r.remark
    FROM public.ca_club_roster_rows(p_club_id) r
   ORDER BY r.role_rank DESC, coalesce(r.downline_total, 0) DESC, lower(r.alias), r.user_id;
$$;


ALTER FUNCTION public.ca_club_members_overview(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 9504 (class 1255 OID 17734128)
-- Name: ca_club_members_page(uuid, text, text, text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_members_page(p_club_id uuid, p_search text DEFAULT ''::text, p_filter text DEFAULT 'all'::text, p_sort text DEFAULT 'hierarchy'::text, p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 80) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_search text := lower(left(btrim(coalesce(p_search, '')), 120));
  v_filter text := lower(coalesce(nullif(btrim(p_filter), ''), 'all'));
  v_sort text := lower(coalesce(nullif(btrim(p_sort), ''), 'hierarchy'));
  v_limit int := greatest(20, least(coalesce(p_limit, 80), 200));
  v_cursor jsonb := p_cursor;
  v_out jsonb;
BEGIN
  IF v_filter NOT IN (
    'all', 'mine', 'seated', 'online', 'agents', 'admins',
    'inactive_30', 'inactive_60', 'inactive_90', 'high_fees'
  ) THEN
    v_filter := 'all';
  END IF;
  IF v_sort NOT IN ('newest', 'oldest', 'hierarchy', 'activity', 'name', 'downlines', 'wallet', 'fees') THEN
    v_sort := 'hierarchy';
  END IF;

  -- A cursor belongs to one viewer, club and normalized query. A token from
  -- another tab or saved view restarts safely instead of skipping rows.
  IF v_cursor IS NOT NULL AND (
    coalesce(v_cursor->>'v', '') <> '2'
    OR coalesce(v_cursor->>'club', '') <> p_club_id::text
    OR coalesce(v_cursor->>'actor', '') <> coalesce(v_actor::text, 'service')
    OR coalesce(v_cursor->>'search', '') <> md5(v_search)
    OR coalesce(v_cursor->>'filter', '') <> v_filter
    OR coalesce(v_cursor->>'sort', '') <> v_sort
  ) THEN
    v_cursor := NULL;
  END IF;

  -- A cursor is an opaque server token, but it still crosses a hostile client
  -- boundary. Treat malformed numeric components as an expired cursor instead
  -- of letting a text-to-number cast turn the whole roster into a 500.
  IF v_cursor IS NOT NULL AND (
    (v_cursor ? 'rank' AND coalesce(v_cursor->>'rank', '') !~ '^-?[0-9]+$')
    OR (v_cursor ? 'downlines' AND coalesce(v_cursor->>'downlines', '') !~ '^-?[0-9]+$')
    OR (v_cursor ? 'presence' AND coalesce(v_cursor->>'presence', '') !~ '^-?[0-9]+$')
    OR (v_cursor ? 'activity' AND coalesce(v_cursor->>'activity', '') !~ '^-?[0-9]+([.][0-9]+)?$')
    OR (v_cursor ? 'metric' AND coalesce(v_cursor->>'metric', '') !~ '^-?[0-9]+([.][0-9]+)?$')
  ) THEN
    v_cursor := NULL;
  END IF;

  WITH rows AS MATERIALIZED (
    SELECT r.*,
           CASE WHEN r.joined_at IS NULL THEN 1e30::numeric
                WHEN v_sort = 'newest' THEN -extract(epoch FROM r.joined_at)
                ELSE extract(epoch FROM r.joined_at) END AS joined_sort,
           lower(r.alias) AS sort_name,
           CASE WHEN r.is_seated THEN 2 WHEN r.is_online THEN 1 ELSE 0 END AS presence_rank,
           coalesce(extract(epoch FROM r.last_login), 0)::numeric AS activity_epoch,
           coalesce(r.player_wallet, 0) + coalesce(r.agent_wallet, 0) AS wallet_total
      FROM public.ca_club_roster_rows(p_club_id) r
     WHERE (
       v_search = ''
       OR position(v_search in lower(r.alias)) > 0
       OR position(v_search in lower(r.username)) > 0
       OR position(v_search in lower(coalesce(r.player_number, ''))) > 0
       OR position(v_search in lower(coalesce(r.home_club_name, ''))) > 0
       OR position(v_search in lower(coalesce(r.upline_name, ''))) > 0
     )
       AND CASE v_filter
         WHEN 'mine' THEN r.in_viewer_downline
         WHEN 'seated' THEN r.is_seated
         WHEN 'online' THEN r.is_online
         WHEN 'agents' THEN r.role IN ('super_agent', 'agent', 'sub_agent')
         WHEN 'admins' THEN r.role IN ('owner', 'co_owner', 'admin')
         WHEN 'inactive_30' THEN r.last_login IS NOT NULL AND r.last_login < now() - interval '30 days'
         WHEN 'inactive_60' THEN r.last_login IS NOT NULL AND r.last_login < now() - interval '60 days'
         WHEN 'inactive_90' THEN r.last_login IS NOT NULL AND r.last_login < now() - interval '90 days'
         WHEN 'high_fees' THEN coalesce(r.total_fees, 0) >= 100
         ELSE true
       END
  ), eligible AS MATERIALIZED (
    SELECT r.*
      FROM rows r
     WHERE v_cursor IS NULL OR CASE v_sort
       WHEN 'newest' THEN
         (r.joined_sort, r.user_id::text) >
         (coalesce((v_cursor->>'metric')::numeric, 0), coalesce(v_cursor->>'id', ''))
       WHEN 'oldest' THEN
         (r.joined_sort, r.user_id::text) >
         (coalesce((v_cursor->>'metric')::numeric, 0), coalesce(v_cursor->>'id', ''))
       WHEN 'name' THEN
         (r.sort_name, r.user_id::text) >
         (coalesce(v_cursor->>'name', ''), coalesce(v_cursor->>'id', ''))
       WHEN 'activity' THEN
         r.presence_rank < coalesce((v_cursor->>'presence')::int, 0)
         OR (r.presence_rank = coalesce((v_cursor->>'presence')::int, 0)
             AND r.activity_epoch < coalesce((v_cursor->>'activity')::numeric, 0))
         OR (r.presence_rank = coalesce((v_cursor->>'presence')::int, 0)
             AND r.activity_epoch = coalesce((v_cursor->>'activity')::numeric, 0)
             AND r.user_id::text > coalesce(v_cursor->>'id', ''))
       WHEN 'downlines' THEN
         coalesce(r.downline_total, 0) < coalesce((v_cursor->>'metric')::numeric, 0)
         OR (coalesce(r.downline_total, 0) = coalesce((v_cursor->>'metric')::numeric, 0)
             AND r.user_id::text > coalesce(v_cursor->>'id', ''))
       WHEN 'wallet' THEN
         r.wallet_total < coalesce((v_cursor->>'metric')::numeric, 0)
         OR (r.wallet_total = coalesce((v_cursor->>'metric')::numeric, 0)
             AND r.user_id::text > coalesce(v_cursor->>'id', ''))
       WHEN 'fees' THEN
         coalesce(r.total_fees, 0) < coalesce((v_cursor->>'metric')::numeric, 0)
         OR (coalesce(r.total_fees, 0) = coalesce((v_cursor->>'metric')::numeric, 0)
             AND r.user_id::text > coalesce(v_cursor->>'id', ''))
       ELSE
         r.role_rank < coalesce((v_cursor->>'rank')::int, 0)
         OR (r.role_rank = coalesce((v_cursor->>'rank')::int, 0)
             AND coalesce(r.downline_total, 0) < coalesce((v_cursor->>'downlines')::int, 0))
         OR (r.role_rank = coalesce((v_cursor->>'rank')::int, 0)
             AND coalesce(r.downline_total, 0) = coalesce((v_cursor->>'downlines')::int, 0)
             AND r.sort_name > coalesce(v_cursor->>'name', ''))
         OR (r.role_rank = coalesce((v_cursor->>'rank')::int, 0)
             AND coalesce(r.downline_total, 0) = coalesce((v_cursor->>'downlines')::int, 0)
             AND r.sort_name = coalesce(v_cursor->>'name', '')
             AND r.user_id::text > coalesce(v_cursor->>'id', ''))
       END
  ), ordered AS MATERIALIZED (
    SELECT e.*,
           row_number() OVER (
             ORDER BY
               CASE WHEN v_sort IN ('newest', 'oldest') THEN e.joined_sort END ASC,
               CASE WHEN v_sort = 'hierarchy' THEN e.role_rank END DESC,
               CASE WHEN v_sort = 'hierarchy' THEN coalesce(e.downline_total, 0) END DESC,
               CASE WHEN v_sort = 'hierarchy' THEN e.sort_name END ASC,
               CASE WHEN v_sort = 'activity' THEN e.presence_rank END DESC,
               CASE WHEN v_sort = 'activity' THEN e.activity_epoch END DESC,
               CASE WHEN v_sort = 'name' THEN e.sort_name END ASC,
               CASE WHEN v_sort = 'downlines' THEN coalesce(e.downline_total, 0) END DESC,
               CASE WHEN v_sort = 'wallet' THEN e.wallet_total END DESC,
               CASE WHEN v_sort = 'fees' THEN coalesce(e.total_fees, 0) END DESC,
               e.user_id ASC
           ) AS rn
      FROM eligible e
     ORDER BY
       CASE WHEN v_sort IN ('newest', 'oldest') THEN e.joined_sort END ASC,
               CASE WHEN v_sort = 'hierarchy' THEN e.role_rank END DESC,
       CASE WHEN v_sort = 'hierarchy' THEN coalesce(e.downline_total, 0) END DESC,
       CASE WHEN v_sort = 'hierarchy' THEN e.sort_name END ASC,
       CASE WHEN v_sort = 'activity' THEN e.presence_rank END DESC,
       CASE WHEN v_sort = 'activity' THEN e.activity_epoch END DESC,
       CASE WHEN v_sort = 'name' THEN e.sort_name END ASC,
       CASE WHEN v_sort = 'downlines' THEN coalesce(e.downline_total, 0) END DESC,
       CASE WHEN v_sort = 'wallet' THEN e.wallet_total END DESC,
       CASE WHEN v_sort = 'fees' THEN coalesce(e.total_fees, 0) END DESC,
       e.user_id ASC
     LIMIT v_limit + 1
  ), visible AS MATERIALIZED (
    SELECT * FROM ordered WHERE rn <= v_limit
  ), last_row AS (
    SELECT * FROM visible ORDER BY rn DESC LIMIT 1
  )
  SELECT jsonb_build_object(
    'items', coalesce((
      SELECT jsonb_agg(
        to_jsonb(v) - ARRAY['joined_sort', 'sort_name', 'presence_rank', 'activity_epoch', 'wallet_total', 'rn']::text[]
        ORDER BY v.rn
      ) FROM visible v
    ), '[]'::jsonb),
    'next_cursor', CASE WHEN (SELECT count(*) FROM ordered) > v_limit THEN (
      SELECT jsonb_build_object(
        'v', 2,
        'club', p_club_id,
        'actor', coalesce(v_actor::text, 'service'),
        'search', md5(v_search),
        'filter', v_filter,
        'sort', v_sort,
        'id', l.user_id,
        'name', l.sort_name,
        'rank', l.role_rank,
        'downlines', coalesce(l.downline_total, 0),
        'presence', l.presence_rank,
        'activity', l.activity_epoch,
        'metric', CASE WHEN v_sort IN ('newest', 'oldest') THEN to_jsonb(l.joined_sort::text) ELSE to_jsonb(CASE v_sort
          WHEN 'wallet' THEN l.wallet_total
          WHEN 'fees' THEN coalesce(l.total_fees, 0)
          WHEN 'downlines' THEN coalesce(l.downline_total, 0)
          ELSE 0 END) END
      ) FROM last_row l
    ) ELSE NULL END,
    'has_more', (SELECT count(*) FROM ordered) > v_limit,
    'filtered_total', (SELECT count(*) FROM rows),
    'query', jsonb_build_object('filter', v_filter, 'sort', v_sort)
  ) INTO v_out;

  RETURN coalesce(v_out, jsonb_build_object(
    'items', '[]'::jsonb,
    'next_cursor', NULL,
    'has_more', false,
    'filtered_total', 0,
    'query', jsonb_build_object('filter', v_filter, 'sort', v_sort)
  ));
END;
$_$;


