--
-- TOC entry 7754 (class 1255 OID 181178766)
-- Name: ca_club_members_win_loss(uuid, uuid[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_members_win_loss(p_club_id uuid, p_user_ids uuid[], p_period text DEFAULT 'overall'::text) RETURNS TABLE(user_id uuid, cash numeric, mtt numeric, net numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_period text := lower(btrim(coalesce(p_period, 'overall')));
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_from date;
BEGIN
  IF v_period NOT IN ('today', 'week', 'month', 'overall') THEN
    RAISE EXCEPTION 'Invalid win loss period' USING ERRCODE = '22023';
  END IF;
  IF coalesce(cardinality(p_user_ids), 0) > 100 THEN
    RAISE EXCEPTION 'At most 100 members per call' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.club_member_daily_facts_state WHERE singleton AND initialized)
  THEN RAISE EXCEPTION 'Member daily facts are not initialized'; END IF;

  v_from := CASE v_period
    WHEN 'today' THEN v_today
    WHEN 'week' THEN date_trunc('week', v_today)::date
    WHEN 'month' THEN date_trunc('month', v_today)::date
    ELSE NULL END;

  RETURN QUERY
  WITH asked AS (
    SELECT DISTINCT u AS uid FROM unnest(coalesce(p_user_ids, ARRAY[]::uuid[])) u WHERE u IS NOT NULL
  ), allowed AS (
    SELECT a.uid FROM asked a
     WHERE public.ca_club_roster_access(p_club_id, a.uid) IN ('staff', 'downline', 'service')
  ), cash AS (
    SELECT al.uid,
           CASE WHEN v_from IS NULL THEN
             (SELECT coalesce(sum(t.net) FILTER(WHERE NOT t.is_mtt), 0) FROM (SELECT 1) anchor
                LEFT JOIN public.ca_member_record_daily_facts(p_club_id,al.uid,NULL,NULL) t
                  ON t.club_id = p_club_id AND t.user_id = al.uid)
           ELSE
             (SELECT coalesce(sum(f.net), 0) FROM public.ca_member_record_daily_facts(p_club_id,al.uid,v_from,v_today) f
               WHERE f.club_id = p_club_id AND f.user_id = al.uid AND NOT f.is_mtt
                 AND f.played_on >= v_from AND f.played_on <= v_today)
           END AS cash_net
      FROM allowed al
  )
  SELECT c.uid,
         round(c.cash_net, 2),
         round(m.mtt_net, 2),
         round(c.cash_net + m.mtt_net, 2)
    FROM cash c
    CROSS JOIN LATERAL (
      SELECT public.ca_club_member_tournament_money(
        p_club_id, c.uid,
        CASE WHEN v_from IS NULL THEN NULL ELSE v_from::timestamp AT TIME ZONE 'UTC' END,
        NULL) AS mtt_net
    ) m;
END;
$$;


ALTER FUNCTION public.ca_club_members_win_loss(p_club_id uuid, p_user_ids uuid[], p_period text) OWNER TO postgres;

--
-- TOC entry 5015 (class 1255 OID 15310614)
-- Name: ca_club_my_downline(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_my_downline(p_club_id uuid) RETURNS TABLE(agent_id uuid, path uuid[], depth integer, username text, full_name text, avatar_url text, total_members integer, direct_members integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH RECURSIVE
  user_roles AS (
    SELECT user_id, role FROM club_members WHERE club_id = p_club_id
  ),
  tree AS (
    SELECT cm.user_id, ARRAY[cm.user_id] AS path, 1 AS depth
    FROM club_members cm
    WHERE cm.club_id = p_club_id AND cm.user_id = auth.uid() AND cm.status = 'active'
    UNION ALL
    -- CYCLE SAFETY (2026-08-24). UNION ALL never dedupes, so a cycle in the
    -- agent graph recursed until the statement timeout. Not hypothetical:
    -- club_members.agent_id holds two two-node cycles right now, and running
    -- this walk against one blew past a 4s timeout even with a 2000-row cap.
    -- Every call by an agent at or below such a cycle burned the caller's whole
    -- 8s budget and returned nothing. `path` was already accumulated for
    -- display, so using it as the visited-set costs nothing.
    SELECT cm.user_id, t.path || cm.user_id, t.depth + 1
    FROM club_members cm
    JOIN tree t ON cm.agent_id = t.user_id
    WHERE cm.club_id = p_club_id AND cm.status = 'active'
      AND NOT (cm.user_id = ANY (t.path))
      AND t.depth < 64
  )
  SELECT t.user_id AS agent_id, t.path, t.depth,
         p.username, coalesce(nullif(btrim(p.display_name), ''), p.username) AS full_name, p.avatar_url,
         (SELECT count(*)::int - 1 FROM tree sub WHERE sub.path @> ARRAY[t.user_id]) AS total_members,
         (SELECT count(*)::int FROM club_members child
           WHERE child.agent_id = t.user_id AND child.club_id = p_club_id
             AND child.status = 'active') AS direct_members
  FROM tree t
  JOIN profiles p ON p.id = t.user_id
  JOIN user_roles ur ON ur.user_id = t.user_id
  WHERE ur.role IN ('owner', 'co_owner', 'admin', 'agent', 'super_agent')
  ORDER BY t.path;
$$;


ALTER FUNCTION public.ca_club_my_downline(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 3449 (class 1255 OID 19865141)
-- Name: ca_club_operations_overview(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_operations_overview(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role              text;
  v_platform          boolean;
  v_internal          boolean;
  v_staff             boolean;
  v_finance           boolean;
  v_control           boolean;
  v_name              text;
  v_slug              text;
  v_treasury          numeric;
  v_locked            boolean;
  v_members           bigint;
  v_pending           bigint;
  v_new7              bigint;
  v_member_chips      numeric;
  v_online            bigint;
  v_seated            bigint;
  v_live_tables       bigint;
  v_running_tables    bigint;
  v_waiting_tables    bigint;
  v_reg_tourneys      bigint;
  v_run_tourneys      bigint;
  v_hands_today       bigint := 0;
  v_rake_today        numeric := 0;
  v_reports           bigint;
  v_disputes          bigint;
  v_disputes_aged     bigint;
  v_blacklist         bigint;
  v_blacklist_expired bigint;
  v_chip_requests     bigint;
  v_cashouts          bigint;
  v_credit            bigint;
  v_invoices          bigint;
  v_invoices_overdue  bigint;
  v_tickets           bigint;
  v_flags             bigint;
  v_alerts            jsonb := '[]'::jsonb;
  v_kpis              jsonb;
BEGIN
  IF p_club_id IS NULL THEN
    RAISE EXCEPTION 'a club id is required' USING ERRCODE = '22004';
  END IF;

  SELECT c.name, c.slug, coalesce(c.chip_treasury, 0), coalesce(c.settlement_locked, false)
    INTO v_name, v_slug, v_treasury, v_locked
    FROM clubs c
   WHERE c.id = p_club_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'club not found' USING ERRCODE = 'P0002';
  END IF;

  v_internal := session_user IN ('postgres', 'supabase_admin')
             OR coalesce(auth.role(), '') = 'service_role';
  v_platform := coalesce(fn_is_platform_admin(), false);
  v_role     := coalesce(fn_club_bank_role(p_club_id), '');

  v_staff := v_internal OR v_platform
             OR v_role IN ('owner', 'co_owner', 'admin');

  IF NOT v_staff THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  v_finance := v_internal OR v_platform
               OR v_role IN ('owner', 'co_owner', 'admin');
  v_control := v_internal OR v_platform
               OR v_role IN ('owner', 'co_owner', 'admin');

  SELECT count(DISTINCT cm.user_id) FILTER (
           WHERE coalesce(cm.status, 'approved') IN ('active', 'approved')
             AND NOT EXISTS (SELECT 1 FROM profiles pr WHERE pr.id = cm.user_id AND pr.status = 'deleted')),
         count(*) FILTER (WHERE cm.status = 'pending'),
         count(DISTINCT cm.user_id) FILTER (
           WHERE cm.created_at > now() - interval '7 days'
             AND coalesce(cm.status, 'approved') IN ('active', 'approved')
             AND NOT EXISTS (SELECT 1 FROM profiles pr WHERE pr.id = cm.user_id AND pr.status = 'deleted')),
         coalesce(sum(cm.chip_balance) FILTER (
           WHERE coalesce(cm.status, 'active') NOT IN ('banned', 'suspended')), 0)
    INTO v_members, v_pending, v_new7, v_member_chips
    FROM club_members cm
   WHERE cm.club_id = p_club_id;

  SELECT count(*) FILTER (WHERE t.status IN ('running', 'waiting', 'active')),
         count(*) FILTER (WHERE t.status = 'running'),
         count(*) FILTER (WHERE t.status = 'waiting')
    INTO v_live_tables, v_running_tables, v_waiting_tables
    FROM tables t
   WHERE t.club_id = p_club_id;

  SELECT count(DISTINCT ts.user_id)
    INTO v_seated
    FROM table_seats ts
    JOIN tables t ON t.id = ts.table_id
   WHERE (t.club_id = p_club_id OR ts.club_id = p_club_id)
     AND ts.left_at IS NULL
     AND ts.user_id IS NOT NULL
     AND t.status IN ('running', 'waiting')
     AND EXISTS (SELECT 1 FROM club_members cm
                  WHERE cm.club_id = p_club_id AND cm.user_id = ts.user_id
                    AND coalesce(cm.status, 'approved') IN ('active', 'approved'))
     AND NOT EXISTS (SELECT 1 FROM profiles pr WHERE pr.id = ts.user_id AND pr.status = 'deleted');

  SELECT count(*)
    INTO v_online
    FROM (
      SELECT ts.user_id
        FROM table_seats ts
        JOIN tables t ON t.id = ts.table_id
       WHERE (t.club_id = p_club_id OR ts.club_id = p_club_id)
         AND ts.left_at IS NULL AND ts.user_id IS NOT NULL
         AND t.status IN ('running', 'waiting')
         AND EXISTS (SELECT 1 FROM club_members cm
                      WHERE cm.club_id = p_club_id AND cm.user_id = ts.user_id
                        AND coalesce(cm.status, 'approved') IN ('active', 'approved'))
         AND NOT EXISTS (SELECT 1 FROM profiles pr WHERE pr.id = ts.user_id AND pr.status = 'deleted')
      UNION
      SELECT cm.user_id
        FROM club_members cm
       WHERE cm.club_id = p_club_id
         AND coalesce(cm.status, 'approved') IN ('active', 'approved')
         AND NOT EXISTS (SELECT 1 FROM profiles pr WHERE pr.id = cm.user_id AND pr.status = 'deleted')
         AND EXISTS (SELECT 1 FROM public.profiles pp WHERE pp.id = cm.user_id AND coalesce(pp.is_online, false) AND pp.last_seen > now() - interval '5 minutes')
    ) x;

  SELECT count(*) FILTER (WHERE tr.status = 'REGISTERING'),
         count(*) FILTER (WHERE tr.status IN ('RUNNING', 'COMPLETING'))
    INTO v_reg_tourneys, v_run_tourneys
    FROM tournaments tr
   WHERE tr.club_id = p_club_id
     AND tr.status IN ('REGISTERING', 'RUNNING', 'COMPLETING');

  SELECT coalesce((
           SELECT d.hands FROM club_hand_daily d
            WHERE d.club_id = p_club_id
              AND d.stat_date = (now() AT TIME ZONE 'UTC')::date), 0),
         coalesce((
           SELECT d.rake FROM ca_club_rake_daily d
            WHERE d.club_id = p_club_id
              AND d.stat_date = (now() AT TIME ZONE 'UTC')::date), 0)
    INTO v_hands_today, v_rake_today;

  SELECT count(*)
    INTO v_reports
    FROM user_reports r
   WHERE coalesce(r.status, 'pending') = 'pending'
     AND EXISTS (SELECT 1 FROM club_members m
                  WHERE m.club_id = p_club_id AND m.user_id = r.reported_user_id);

  SELECT count(*), count(*) FILTER (WHERE d.created_at < now() - interval '72 hours')
    INTO v_disputes, v_disputes_aged
    FROM disputes d
   WHERE d.club_id = p_club_id
     AND coalesce(d.status, 'open') IN ('open', 'under_review', 'escalated');

  SELECT count(*) FILTER (WHERE b.expires_at IS NULL OR b.expires_at > now()),
         count(*) FILTER (WHERE b.expires_at IS NOT NULL AND b.expires_at <= now())
    INTO v_blacklist, v_blacklist_expired
    FROM blacklists b
   WHERE b.club_id = p_club_id;

  SELECT count(*)
    INTO v_chip_requests
    FROM chip_requests q
   WHERE q.club_id = p_club_id AND coalesce(q.status, 'pending') = 'pending';

  SELECT count(*)
    INTO v_cashouts
    FROM cashout_requests q
   WHERE q.club_id = p_club_id
     AND q.completed_at IS NULL
     AND q.cancelled_at IS NULL
     AND coalesce(q.status, 'pending') NOT IN ('completed', 'cancelled', 'rejected', 'failed');

  SELECT count(*)
    INTO v_credit
    FROM credit_requests q
   WHERE q.club_id = p_club_id AND coalesce(q.status, 'pending') = 'pending';

  SELECT count(*), count(*) FILTER (WHERE i.due_at IS NOT NULL AND i.due_at < now())
    INTO v_invoices, v_invoices_overdue
    FROM settlement_invoices i
   WHERE i.club_id = p_club_id
     AND coalesce(i.status, 'generated') NOT IN ('paid', 'settled', 'cancelled', 'void');

  SELECT count(*)
    INTO v_tickets
    FROM tournament_tickets tk
   WHERE tk.club_id = p_club_id
     AND tk.redeemed_at IS NULL
     AND tk.cancelled_at IS NULL
     AND coalesce(tk.status, 'issued') NOT IN ('redeemed', 'cancelled', 'expired');

  SELECT count(*)
    INTO v_flags
    FROM anti_cheat_flags f
   WHERE coalesce(f.status, 'open') = 'open'
     AND (f.club_id = p_club_id OR
          (f.club_id IS NULL AND EXISTS (
             SELECT 1 FROM club_members cm
              WHERE cm.club_id = p_club_id AND cm.user_id = f.player_id)));

  IF v_finance AND v_invoices_overdue > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'invoices-overdue', 'severity', 'critical', 'tool', 'settlement',
      'title', 'Invoices Past Due', 'count', v_invoices_overdue));
  END IF;

  IF v_disputes_aged > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'disputes-aged', 'severity', 'critical', 'tool', 'disputes',
      'title', 'Disputes Past Seventy Two Hours', 'count', v_disputes_aged));
  ELSIF v_disputes > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'disputes-open', 'severity', 'warning', 'tool', 'disputes',
      'title', 'Disputes Open', 'count', v_disputes));
  END IF;

  IF v_chip_requests > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'chip-requests', 'severity', 'warning', 'tool', 'cashier',
      'title', 'Chip Requests Waiting', 'count', v_chip_requests));
  END IF;

  IF v_cashouts > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'cashouts', 'severity', 'warning', 'tool', 'cashier',
      'title', 'Cash Out Requests Waiting', 'count', v_cashouts));
  END IF;

  IF v_credit > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'credit-requests', 'severity', 'warning', 'tool', 'cashier',
      'title', 'Credit Requests Waiting', 'count', v_credit));
  END IF;

  IF v_pending > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'join-requests', 'severity', 'warning', 'tool', 'players',
      'title', 'Membership Requests Waiting', 'count', v_pending));
  END IF;

  IF v_reports > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'reports-open', 'severity', 'warning', 'tool', 'reports',
      'title', 'Player Reports To Review', 'count', v_reports));
  END IF;

  IF v_flags > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'anti-cheat-flags', 'severity', 'warning', 'tool', 'anti-cheat',
      'title', 'Integrity Flags Open', 'count', v_flags));
  END IF;

  IF v_finance AND v_treasury <= 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'club-bank-empty', 'severity', 'warning', 'tool', 'cashier',
      'title', 'The Club Bank Is Empty', 'count', 0));
  END IF;

  IF v_locked THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'settlement-locked', 'severity', 'info', 'tool', 'settlement',
      'title', 'Settlement Is Locked', 'count', 0));
  END IF;

  IF v_blacklist_expired > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'blacklist-expired', 'severity', 'info', 'tool', 'blacklist',
      'title', 'Expired Exclusions To Clear', 'count', v_blacklist_expired));
  END IF;

  v_kpis := jsonb_build_object(
    'members', v_members,
    'members_pending', v_pending,
    'members_new_7d', v_new7,
    'online_now', v_online,
    'seated_now', v_seated,
    'live_tables', v_live_tables,
    'running_tables', v_running_tables,
    'waiting_tables', v_waiting_tables,
    'tournaments_registering', v_reg_tourneys,
    'tournaments_running', v_run_tourneys,
    'hands_today', v_hands_today);

  IF v_finance THEN
    v_kpis := v_kpis || jsonb_build_object(
      'rake_today', v_rake_today,
      'club_bank', v_treasury,
      'member_chips', v_member_chips);
  END IF;

  RETURN jsonb_build_object(
    'generated_at', now(),
    'club', jsonb_build_object('id', p_club_id, 'name', v_name, 'slug', v_slug),
    'viewer', jsonb_build_object(
      'role', nullif(v_role, ''),
      'is_platform_staff', v_platform,
      'can_view_finance', v_finance,
      'can_control_club', v_control),
    'kpis', v_kpis,
    'counts', jsonb_build_object(
      'members', v_members,
      'members_pending', v_pending,
      'reports_open', v_reports,
      'disputes_open', v_disputes,
      'disputes_aged', v_disputes_aged,
      'blacklist_active', v_blacklist,
      'blacklist_expired', v_blacklist_expired,
      'chip_requests_pending', v_chip_requests,
      'cashouts_pending', v_cashouts,
      'credit_requests_pending', v_credit,
      'invoices_open', CASE WHEN v_finance THEN v_invoices ELSE NULL END,
      'invoices_overdue', CASE WHEN v_finance THEN v_invoices_overdue ELSE NULL END,
      'tickets_outstanding', v_tickets,
      'anti_cheat_flags_open', v_flags),
    'alerts', v_alerts,
    'settlement_locked', v_locked);
END;
$$;


ALTER FUNCTION public.ca_club_operations_overview(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 44567 (class 0 OID 0)
-- Dependencies: 3449
-- Name: FUNCTION ca_club_operations_overview(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_club_operations_overview(p_club_id uuid) IS 'One staff-gated read behind the club operations workspace: live floor, roster, and every queue that is waiting for a person, with the alert severity and the registry tool id each queue belongs to. Finance figures are returned only to the finance roles. Horses are counted like every other player.';


--
-- TOC entry 6054 (class 1255 OID 16485090)
-- Name: ca_club_overlay_pnl(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_overlay_pnl(p_club_id uuid, p_days integer DEFAULT 14) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v jsonb;
  v_from date := (now() AT TIME ZONE 'UTC')::date - (greatest(least(coalesce(p_days,14), 90), 1) - 1);
BEGIN
  IF NOT ca_can_view_club(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'club_id', p_club_id,
    'range_days', greatest(least(coalesce(p_days,14), 90), 1),
    'totals', (
      SELECT jsonb_build_object(
        'events', coalesce(count(*), 0),
        'funded', round(coalesce(sum(o.amount), 0), 2),
        'bank', coalesce(max(o.bank_type),
                         (SELECT CASE WHEN c.union_id IS NULL THEN 'club' ELSE 'union' END
                            FROM clubs c WHERE c.id = p_club_id)))
      FROM tournament_guarantee_overlays o
      WHERE o.club_id = p_club_id AND o.funded_at >= v_from::timestamptz
    ),
    'events', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
               'tournament_id', o.tournament_id,
               'name', coalesce(t.name, 'Unknown'),
               'overlay', o.amount,
               'pool_before', o.pool_before,
               'pool_after', o.pool_after,
               'bank', o.bank_type,
               'at', o.funded_at)
             ORDER BY o.funded_at DESC)
      FROM tournament_guarantee_overlays o
      LEFT JOIN tournaments t ON t.id = o.tournament_id
      WHERE o.club_id = p_club_id AND o.funded_at >= v_from::timestamptz
    ), '[]'::jsonb),
    'generated_at', now()
  ) INTO v;

  RETURN v;
END;
$$;


ALTER FUNCTION public.ca_club_overlay_pnl(p_club_id uuid, p_days integer) OWNER TO postgres;

--
-- TOC entry 5927 (class 1255 OID 14619501)
-- Name: ca_club_player_breakdown(uuid, date, date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_player_breakdown(p_club_id uuid, p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today date:=(now() AT TIME ZONE 'UTC')::date;
  v_end date:=LEAST(COALESCE(p_end,v_today),v_today);
  v_start date:=COALESCE(p_start,v_end-13);
  v_lim int:=GREATEST(LEAST(COALESCE(p_limit,100),500),1);
  v_union uuid; v_out jsonb;
BEGIN
  IF NOT public.ca_can_view_whole_club_report(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE='42501'; END IF;
  IF v_start<v_end-92 THEN v_start:=v_end-92; END IF;
  IF v_start>v_end THEN v_start:=v_end; END IF;
  SELECT uc.union_id INTO v_union FROM public.union_clubs uc WHERE uc.club_id = ANY (public.fn_ca_club_data_clubs(p_club_id)) LIMIT 1;
  WITH att_club AS MATERIALIZED (
    SELECT DISTINCT cm.user_id FROM public.club_members cm WHERE cm.club_id = ANY (public.fn_ca_club_data_clubs(p_club_id))
  ), record AS MATERIALIZED (
    -- Hands and cash results exactly as the Member record files them: the
    -- funded club, UTC days, this club's launch accounting cutoff.
    SELECT f.user_id,SUM(f.net) FILTER (WHERE NOT f.is_mtt) cash_net,SUM(f.hands)::bigint hands
      FROM public.member_record_daily_facts f
     WHERE f.club_id = ANY (public.fn_ca_club_data_clubs(p_club_id))
       AND f.accounting_cutoff IS NOT DISTINCT FROM public.fn_ca_launch_accounting_cutoff('club',f.club_id)
       AND f.played_on BETWEEN v_start AND v_end
     GROUP BY f.user_id
  ), tournament_pnl AS (
    SELECT d.user_id,SUM(d.tournament_net) tournament_net
      FROM public.ca_club_player_daily d
     WHERE d.club_id = ANY (public.fn_ca_club_data_clubs(p_club_id)) AND d.stat_date BETWEEN v_start AND v_end
     GROUP BY d.user_id
  ), wallet_pnl AS (
    SELECT COALESCE(r.user_id,t.user_id) user_id,r.cash_net,t.tournament_net
      FROM record r FULL JOIN tournament_pnl t ON t.user_id=r.user_id
  ), rake AS (
    -- Fees exactly as the Member record counts them: cash and tournament
    -- fees filed to this club, from the fee counting start.
    SELECT t.user_id,sum(t.total_fees) rake
      FROM unnest(public.fn_ca_club_data_clubs(p_club_id)) cc(id) CROSS JOIN LATERAL public.ca_club_member_fee_totals(cc.id,v_start,v_end) t GROUP BY t.user_id
  ), hands AS (
    SELECT r.user_id,r.hands FROM record r
  ), merged AS MATERIALIZED (
    SELECT a.user_id,round(COALESCE(w.cash_net,0),2) cash_net,
      round(COALESCE(w.tournament_net,0),2) tournament_net,
      round(COALESCE(w.cash_net,0)+COALESCE(w.tournament_net,0),2) net,
      round(COALESCE(r.rake,0),2) rake,COALESCE(h.hands,0) hands
      FROM att_club a LEFT JOIN wallet_pnl w ON w.user_id=a.user_id
      LEFT JOIN rake r ON r.user_id=a.user_id LEFT JOIN hands h ON h.user_id=a.user_id
      WHERE (COALESCE(w.cash_net,0)<>0 OR COALESCE(w.tournament_net,0)<>0
         OR COALESCE(r.rake,0)<>0 OR COALESCE(h.hands,0)<>0)
        AND NOT EXISTS (SELECT 1 FROM public.profiles dp
                         WHERE dp.id = a.user_id AND dp.status = 'deleted')
  )
  SELECT jsonb_build_object('range',jsonb_build_object('start',v_start,'end',v_end,'days',(v_end-v_start)+1),
    'rake_complete_through',v_end,
    'totals',(SELECT jsonb_build_object('players',count(*),'net',round(COALESCE(SUM(net),0),2),
      'rake',round(COALESCE(SUM(rake),0),2),'hands',COALESCE(SUM(hands),0)) FROM merged),
    'players',COALESCE((SELECT jsonb_agg(jsonb_build_object('user_id',q.user_id,
      'username',COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name),pr.username,'Player'),'avatar_url',pr.avatar_url,
      'is_horse',(public.fn_can_see_horse_flag(p_club_id) AND COALESCE(pr.is_horse,false)),'net',q.net,'cash_net',q.cash_net,
      'tournament_net',q.tournament_net,'rake',q.rake,'hands',q.hands) ORDER BY q.net DESC)
      FROM (SELECT * FROM merged ORDER BY net DESC LIMIT v_lim) q
      LEFT JOIN public.profiles pr ON pr.id=q.user_id),'[]'::jsonb),
    'player_count',(SELECT count(*) FROM merged),'generated_at',now()) INTO v_out;
  RETURN v_out;
END;
$$;


ALTER FUNCTION public.ca_club_player_breakdown(p_club_id uuid, p_start date, p_end date, p_limit integer) OWNER TO postgres;

--
-- TOC entry 5849 (class 1255 OID 18109377)
-- Name: ca_club_player_export_start(uuid, date, date, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_player_export_start(p_club_id uuid, p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_sort text DEFAULT 'winners'::text, p_request_id uuid DEFAULT gen_random_uuid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '120s'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_end date := LEAST(COALESCE(p_end,v_today),v_today);
  v_start date := COALESCE(p_start,v_end-13);
  v_sort text := LOWER(COALESCE(NULLIF(p_sort,''),'winners'));
  v_request uuid := COALESCE(p_request_id,gen_random_uuid());
  v_union uuid;
  v_export_id uuid;
  v_total integer;
BEGIN
  IF v_user IS NULL OR NOT public.ca_can_view_whole_club_report(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE='42501';
  END IF;
  IF v_start < v_end-92 THEN v_start := v_end-92; END IF;
  IF v_start > v_end THEN v_start := v_end; END IF;
  IF v_sort NOT IN ('winners','losers','rake','hands') THEN v_sort := 'winners'; END IF;
  SELECT uc.union_id INTO v_union FROM public.union_clubs uc
   WHERE uc.club_id=p_club_id LIMIT 1;

  IF NOT pg_try_advisory_xact_lock(
    hashtextextended('ca-club-data-export-user:' || v_user::text, 0)
  ) THEN
    RAISE EXCEPTION 'Another Club Data export is already being prepared.'
      USING ERRCODE = '55000';
  END IF;
  -- Expiry is owned by the doors: the caller's own slot below, then the bounded prune at the end of this call.
  SELECT id,total_rows INTO v_export_id,v_total
    FROM public.ca_club_data_exports
   WHERE user_id = v_user AND request_id = v_request AND status = 'ready'
     AND expires_at >= now() AND kind = 'players';
  -- A request id replays only a job of this door's own kind. The same id
  -- held by a live job of another kind is a different request: refused,
  -- never replayed as this kind and never rebuilt over it.
  IF v_export_id IS NULL AND EXISTS (
    SELECT 1
      FROM public.ca_club_data_exports other_kind
     WHERE other_kind.user_id = v_user
       AND other_kind.request_id = v_request
       AND other_kind.kind <> 'players'
       AND other_kind.expires_at >= now()
  ) THEN
    RAISE EXCEPTION 'Club Data request id was already used for different inputs'
      USING ERRCODE = '22023';
  END IF;
  IF v_export_id IS NOT NULL THEN
    RETURN jsonb_build_object('export_id',v_export_id,'total_rows',v_total,'status','ready');
  END IF;
  -- The expired job owned by the caller is reclaimed first, and never behind
  -- the shared prune's try-lock: an owner whose previous export lost its
  -- cleanup must not be locked out of the next one. Bounded to one export
  -- (50,000 rows exceeds anything a door can prepare); SKIP LOCKED so a
  -- prune retiring the same parent from another session is never waited on.
  DELETE FROM public.ca_club_data_export_rows own_row
   USING (
     SELECT stale_row.export_id, stale_row.ordinal
       FROM public.ca_club_data_export_rows stale_row
       JOIN public.ca_club_data_exports expired_slot
         ON expired_slot.id = stale_row.export_id
      WHERE expired_slot.user_id = v_user
        AND expired_slot.expires_at < now()
      ORDER BY stale_row.export_id, stale_row.ordinal
      LIMIT 50000
      FOR UPDATE OF stale_row SKIP LOCKED
   ) doomed
   WHERE own_row.export_id = doomed.export_id
     AND own_row.ordinal = doomed.ordinal;

  DELETE FROM public.ca_club_data_exports expired_slot
   USING (
     SELECT reclaimable.id
       FROM public.ca_club_data_exports reclaimable
      WHERE reclaimable.user_id = v_user
        AND reclaimable.expires_at < now()
      FOR UPDATE SKIP LOCKED
   ) reclaimed
   WHERE expired_slot.id = reclaimed.id
     AND NOT EXISTS (
       SELECT 1
         FROM public.ca_club_data_export_rows export_row
        WHERE export_row.export_id = expired_slot.id
     );

  IF EXISTS (
    SELECT 1
      FROM public.ca_club_data_exports active_slot
     WHERE active_slot.user_id = v_user
  ) THEN
    RAISE EXCEPTION 'Another Club Data export is already being prepared, downloaded, or cleaned up.'
      USING ERRCODE = '55000';
  END IF;
  INSERT INTO public.ca_club_data_exports(user_id,club_id,request_id,kind)
  VALUES(v_user,p_club_id,v_request,'players') RETURNING id INTO v_export_id;

  WITH att_club AS MATERIALIZED (
    SELECT DISTINCT cm.user_id FROM public.club_members cm WHERE cm.club_id=p_club_id
  ), record AS MATERIALIZED (
    -- Hands and cash results exactly as the Member record files them: the
    -- funded club, UTC days, this club's launch accounting cutoff.
    SELECT f.user_id,SUM(f.net) FILTER (WHERE NOT f.is_mtt) cash_net,SUM(f.hands)::bigint hands
      FROM public.member_record_daily_facts f
     WHERE f.club_id=p_club_id
       AND f.accounting_cutoff IS NOT DISTINCT FROM public.fn_ca_launch_accounting_cutoff('club',p_club_id)
       AND f.played_on BETWEEN v_start AND v_end
     GROUP BY f.user_id
  ), tournament_pnl AS (
    SELECT d.user_id,SUM(d.tournament_net) tournament_net
      FROM public.ca_club_player_daily d
     WHERE d.club_id=p_club_id AND d.stat_date BETWEEN v_start AND v_end
     GROUP BY d.user_id
  ), wallet_pnl AS (
    SELECT COALESCE(r.user_id,t.user_id) user_id,r.cash_net,t.tournament_net
      FROM record r FULL JOIN tournament_pnl t ON t.user_id=r.user_id
  ), rake AS (
    -- Fees exactly as the Member record counts them: cash and tournament
    -- fees filed to this club, from the fee counting start.
    SELECT t.user_id,t.total_fees rake
      FROM public.ca_club_member_fee_totals(p_club_id,v_start,v_end) t
  ), hands AS (
    SELECT r.user_id,r.hands FROM record r
  ), merged AS MATERIALIZED (
    SELECT a.user_id,COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name),pr.username,'Player') username,
           pr.avatar_url,(public.fn_can_see_horse_flag(p_club_id) AND COALESCE(pr.is_horse,false)) is_horse,
           round(COALESCE(w.cash_net,0),2) cash_net,
           round(COALESCE(w.tournament_net,0),2) tournament_net,
           round(COALESCE(w.cash_net,0)+COALESCE(w.tournament_net,0),2) net,
           round(COALESCE(r.rake,0),2) rake,COALESCE(h.hands,0) hands
      FROM att_club a LEFT JOIN wallet_pnl w ON w.user_id=a.user_id
      LEFT JOIN rake r ON r.user_id=a.user_id LEFT JOIN hands h ON h.user_id=a.user_id
      LEFT JOIN public.profiles pr ON pr.id=a.user_id
     WHERE (COALESCE(w.cash_net,0)<>0 OR COALESCE(w.tournament_net,0)<>0
        OR COALESCE(r.rake,0)<>0 OR COALESCE(h.hands,0)<>0)
        AND NOT EXISTS (SELECT 1 FROM public.profiles dp
                         WHERE dp.id = a.user_id AND dp.status = 'deleted')
  ), scored AS (
    SELECT m.*,CASE v_sort WHEN 'losers' THEN -m.net WHEN 'rake' THEN m.rake
                           WHEN 'hands' THEN m.hands::numeric ELSE m.net END sort_value
      FROM merged m
  ), ordered AS (
    SELECT row_number() OVER (ORDER BY sort_value DESC,user_id::text DESC)::integer ordinal,
           jsonb_build_object(
             'user_id',user_id,'username',username,'avatar_url',avatar_url,
             'is_horse',is_horse,'net',net,'cash_net',cash_net,
             'tournament_net',tournament_net,'rake',rake,'hands',hands
           ) payload
      FROM scored
  )
  INSERT INTO public.ca_club_data_export_rows(export_id,ordinal,payload)
  SELECT v_export_id,ordinal,payload FROM ordered;

  GET DIAGNOSTICS v_total = ROW_COUNT;
  UPDATE public.ca_club_data_exports
     SET total_rows=v_total,status='ready'
   WHERE id=v_export_id;

  -- Somebody else's stranded expired job, if any: bounded, non-blocking,
  -- and last, so the row locks it takes are held only until this commit.
  PERFORM public.ca_prune_expired_club_data_exports(2000);
  RETURN jsonb_build_object('export_id',v_export_id,'total_rows',v_total,'status','ready');
END;
$$;


ALTER FUNCTION public.ca_club_player_export_start(p_club_id uuid, p_start date, p_end date, p_sort text, p_request_id uuid) OWNER TO postgres;

--
-- TOC entry 7385 (class 1255 OID 153039711)
-- Name: ca_club_player_history(uuid, uuid, text, date, date, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_club_player_history(p_club_id uuid, p_target_user_id uuid DEFAULT NULL::uuid, p_kind text DEFAULT 'all'::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '6s'
    AS $$
DECLARE
  v_actor uuid := auth.uid(); v_scope uuid[]; v_allowed uuid[];
  v_cursor_at timestamptz; v_cursor_id uuid; v_rows jsonb; v_more boolean;
  v_last jsonb;
BEGIN
  IF v_actor IS NULL OR p_club_id IS NULL THEN
    RAISE EXCEPTION 'History Access Denied' USING ERRCODE = '42501';
  END IF;
  v_scope := public.fn_club_scope_ids(p_club_id);
  IF v_scope IS NULL OR cardinality(v_scope) = 0 THEN
    RAISE EXCEPTION 'History Access Denied' USING ERRCODE = '42501';
  END IF;
  SELECT array_agg(c.id) INTO v_allowed FROM public.clubs c
   WHERE c.id=ANY(v_scope) AND public.ca_player_history_can_read(c.id);
  IF v_allowed IS NULL OR cardinality(v_allowed)=0 THEN
    RAISE EXCEPTION 'History Access Denied' USING ERRCODE='42501';
  END IF;
  IF p_kind IS NULL OR p_kind NOT IN ('all','roles','status','notes','exports')
     OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50
     OR (p_from IS NOT NULL AND p_to IS NOT NULL AND p_from>p_to)
     OR (p_target_user_id IS NOT NULL AND p_kind='exports') THEN
    RAISE EXCEPTION 'Invalid History Query' USING ERRCODE='22023';
  END IF;
  IF p_cursor IS NOT NULL THEN
    IF jsonb_typeof(p_cursor)<>'object' OR NOT(p_cursor ? 'created_at' AND p_cursor ? 'id')
       OR jsonb_typeof(p_cursor->'created_at')<>'string' OR jsonb_typeof(p_cursor->'id')<>'string' THEN
      RAISE EXCEPTION 'Invalid History Cursor' USING ERRCODE='22023';
    END IF;
    BEGIN
      v_cursor_at := (p_cursor->>'created_at')::timestamptz;
      v_cursor_id := (p_cursor->>'id')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'Invalid History Cursor' USING ERRCODE='22023';
    END;
    IF v_cursor_at IS NULL OR v_cursor_id IS NULL OR NOT isfinite(v_cursor_at) THEN
      RAISE EXCEPTION 'Invalid History Cursor' USING ERRCODE='22023';
    END IF;
  END IF;
  WITH candidates AS MATERIALIZED (
    SELECT a.*, CASE
      WHEN a.action IN ('role_change','set_member_role') THEN 'roles'
      WHEN a.action IN ('banned','unban_member','member_status_change','set_member_status','kick_member','member_left','depart_club_member') THEN 'status'
      WHEN a.action='update_member_notes' THEN 'notes'
      WHEN a.action='export_club_roster' THEN 'exports' END AS kind
    FROM public.audit_trail a
    WHERE a.club_id=ANY(v_allowed)
      AND ((a.target_type IN ('member','club_member','membership') AND a.action IN (
        'role_change','set_member_role','banned','unban_member','member_status_change','set_member_status','kick_member','member_left','depart_club_member'))
        OR (a.target_type='club_member' AND a.action='update_member_notes')
        OR (p_target_user_id IS NULL AND a.target_type='club' AND a.target_id=a.club_id AND a.action='export_club_roster'))
      AND (p_target_user_id IS NULL OR a.target_id=p_target_user_id)
      AND (p_from IS NULL OR a.created_at >= (p_from::timestamp AT TIME ZONE 'UTC'))
      AND (p_to IS NULL OR a.created_at < ((p_to+1)::timestamp AT TIME ZONE 'UTC'))
      AND (v_cursor_at IS NULL OR (a.created_at,a.id)<(v_cursor_at,v_cursor_id))
      AND (p_kind='all' OR
        (p_kind='roles' AND a.action IN ('role_change','set_member_role')) OR
        (p_kind='status' AND a.action IN ('banned','unban_member','member_status_change','set_member_status','kick_member','member_left','depart_club_member')) OR
        (p_kind='notes' AND a.action='update_member_notes') OR
        (p_kind='exports' AND a.action='export_club_roster'))
    ORDER BY a.created_at DESC,a.id DESC LIMIT p_limit+1
  ), projected AS (
    SELECT c.created_at,c.id,jsonb_build_object(
      'id',c.id,'created_at',c.created_at,'club_id',c.club_id,
      'target_user_id',CASE WHEN c.target_type IN ('member','club_member','membership') THEN c.target_id ELSE NULL END,
      'actor_id',c.actor_id,'actor_name',NULLIF(trim(p.alias),''),'actor_role',c.actor_role,'action',c.action,'kind',c.kind,
      'before',CASE c.kind
        WHEN 'roles' THEN jsonb_build_object('role',c.before_state->'role')
        WHEN 'status' THEN jsonb_build_object('status',c.before_state->'status')
        WHEN 'notes' THEN jsonb_build_object('nickname_present',c.before_state->'nickname_present','remark_present',c.before_state->'remark_present','nickname_length',c.before_state->'nickname_length','remark_length',c.before_state->'remark_length')
        ELSE '{}'::jsonb END,
      'after',CASE c.kind
        WHEN 'roles' THEN jsonb_build_object('role',c.after_state->'role')
        WHEN 'status' THEN jsonb_build_object('status',c.after_state->'status')
        WHEN 'notes' THEN jsonb_build_object('nickname_present',c.after_state->'nickname_present','remark_present',c.after_state->'remark_present','nickname_length',c.after_state->'nickname_length','remark_length',c.after_state->'remark_length')
        WHEN 'exports' THEN jsonb_build_object('row_count',c.after_state->'row_count','selected_only',c.after_state->'selected_only','selected_count',c.after_state->'selected_count','filter',c.after_state->'filter','sort',c.after_state->'sort','search_used',c.after_state->'search_used') END
    ) AS row FROM candidates c LEFT JOIN public.profiles p ON p.id=c.actor_id
    ORDER BY c.created_at DESC,c.id DESC LIMIT p_limit
  )
  SELECT coalesce(jsonb_agg(row ORDER BY created_at DESC,id DESC),'[]'::jsonb),
    (SELECT count(*)>p_limit FROM candidates) INTO v_rows,v_more FROM projected;
  v_last := v_rows->(jsonb_array_length(v_rows)-1);
  RETURN jsonb_build_object('club_id',p_club_id,'scope_club_ids',to_jsonb(v_allowed),'rows',v_rows,'has_more',v_more,'next_cursor',CASE WHEN v_more THEN
    jsonb_build_object('created_at',v_last->'created_at','id',v_last->'id') ELSE NULL END);
END $$;


