--
-- TOC entry 6153 (class 1255 OID 14248198)
-- Name: ca_drain_club_rebuild(uuid, integer, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_drain_club_rebuild(p_club_id uuid, p_max_seconds integer DEFAULT 120, p_chunk integer DEFAULT 3000, p_since timestamp with time zone DEFAULT (now() - '90 days'::interval)) RETURNS TABLE(tables_touched integer, tables_completed integer, hands_processed bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '600s'
    AS $$
DECLARE
  v_deadline timestamptz := clock_timestamp() + make_interval(secs => greatest(coalesce(p_max_seconds, 120), 5));
  r          record;
  c          record;
  v_touched  integer := 0;
  v_done     integer := 0;
  v_hands    bigint  := 0;
BEGIN
  FOR r IN
    SELECT t.id
    FROM tables t
    JOIN LATERAL (
      SELECT max(hh.created_at) AS last_hand
      FROM hand_history hh
      WHERE hh.table_id = t.id AND hh.created_at >= p_since
    ) lh ON lh.last_hand IS NOT NULL
    LEFT JOIN club_stats_rebuild_log l ON l.table_id = t.id
    WHERE t.club_id = p_club_id
      AND coalesce(l.complete, false) = false
    ORDER BY lh.last_hand DESC
  LOOP
    EXIT WHEN clock_timestamp() >= v_deadline;
    v_touched := v_touched + 1;
    LOOP
      EXIT WHEN clock_timestamp() >= v_deadline;
      BEGIN
        SELECT * INTO c FROM ca_rebuild_table_chunk(r.id, p_chunk);
      EXCEPTION WHEN OTHERS THEN
        -- Never let one bad table stall the drain; it keeps its cursor and
        -- will be retried on the next run.
        RAISE WARNING 'chunk failed for table %: %', r.id, SQLERRM;
        EXIT;
      END;
      v_hands := v_hands + coalesce(c.hands_processed, 0);
      IF c.complete THEN
        v_done := v_done + 1;
        EXIT;
      END IF;
    END LOOP;
  END LOOP;

  tables_touched := v_touched;
  tables_completed := v_done;
  hands_processed := v_hands;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.ca_drain_club_rebuild(p_club_id uuid, p_max_seconds integer, p_chunk integer, p_since timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 3634 (class 1255 OID 101769712)
-- Name: ca_financial_admin_revenue_series(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_financial_admin_revenue_series(p_club_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_end date := (now() AT TIME ZONE 'UTC')::date - 1;
  v_from date;
  v_result jsonb;
BEGIN
  IF p_days IS NULL OR p_days < 1 OR p_days > 90 THEN
    RAISE EXCEPTION 'p_days must be between 1 and 90'
      USING ERRCODE = '22023';
  END IF;
  v_from := v_end - (p_days - 1);

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  IF p_club_id IS NULL THEN
    IF NOT COALESCE(public.fn_is_platform_admin(), false) THEN
      RAISE EXCEPTION 'platform staff required for platform revenue'
        USING ERRCODE = '42501';
    END IF;
  ELSIF NOT public.ca_can_view_club_finances(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  WITH days AS (
    SELECT g.day::date AS stat_date
      FROM generate_series(v_from, v_end, interval '1 day') AS g(day)
  ), cash AS (
    SELECT d.stat_date, sum(d.rake) AS cash_rake
      FROM public.ca_club_rake_daily d
     WHERE d.stat_date BETWEEN v_from AND v_end
       AND (p_club_id IS NULL OR d.club_id = p_club_id)
     GROUP BY d.stat_date
  ), tournaments AS (
    SELECT d.stat_date, sum(d.fee) AS tournament_fees
      FROM public.ca_club_tournament_daily d
     WHERE d.stat_date BETWEEN v_from AND v_end
       AND (p_club_id IS NULL OR d.club_id = p_club_id)
     GROUP BY d.stat_date
  ), daily AS (
    SELECT days.stat_date,
           COALESCE(cash.cash_rake, 0) AS cash_rake,
           COALESCE(tournaments.tournament_fees, 0) AS tournament_fees,
           COALESCE(cash.cash_rake, 0) + COALESCE(tournaments.tournament_fees, 0) AS revenue
      FROM days
      LEFT JOIN cash USING (stat_date)
      LEFT JOIN tournaments USING (stat_date)
  )
  SELECT jsonb_build_object(
    'contract', 'ca_financial_admin_revenue_series_v1',
    'basis', 'cash_rake_plus_tournament_fees',
    'includes_live_day', false,
    'scope', CASE WHEN p_club_id IS NULL THEN 'platform' ELSE 'club' END,
    'club_id', p_club_id,
    'range_days', p_days,
    'range_start', v_from,
    'range_end', v_end,
    'daily', jsonb_agg(
      jsonb_build_object(
        'd', daily.stat_date,
        'cash_rake', daily.cash_rake,
        'tournament_fees', daily.tournament_fees,
        'revenue', daily.revenue
      ) ORDER BY daily.stat_date
    ),
    'period_total', round(sum(daily.revenue), 2),
    'data_updated_at', (
      SELECT max(source.updated_at)
        FROM (
          SELECT max(d.updated_at) AS updated_at
            FROM public.ca_club_rake_daily d
           WHERE d.stat_date BETWEEN v_from AND v_end
             AND (p_club_id IS NULL OR d.club_id = p_club_id)
          UNION ALL
          SELECT max(d.updated_at) AS updated_at
            FROM public.ca_club_tournament_daily d
           WHERE d.stat_date BETWEEN v_from AND v_end
             AND (p_club_id IS NULL OR d.club_id = p_club_id)
        ) source
    ),
    'generated_at', now()
  )
    INTO v_result
    FROM daily;

  RETURN v_result;
END;
$$;


