--

CREATE FUNCTION public.ca_member_record_daily_facts(p_club uuid, p_user uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS SETOF public.club_member_daily_facts
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
