--
-- TOC entry 7989 (class 1255 OID 95129709)
-- Name: ca_own_hand_history_by_club(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_own_hand_history_by_club(p_club_id uuid, p_table_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(hand jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE v_user uuid := auth.uid();
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'ca_own_hand_history_by_club requires authentication' USING ERRCODE='42501';
  END IF;
  IF p_club_id IS NULL THEN
    RAISE EXCEPTION 'ca_own_hand_history_by_club requires a club' USING ERRCODE='22023';
  END IF;
  IF COALESCE((public.fn_poker_arena_context(p_club_id::text)->>'member')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'not authorized for hand-history club' USING ERRCODE='42501';
  END IF;

  RETURN QUERY
  SELECT jsonb_build_object(
      'id',h.id,
      'created_at',h.created_at,
      'started_at',h.started_at,
      'table_id',h.table_id,
      'hand_number',h.hand_number,
      'pot_size',h.pot_size,
      'community_cards',h.community_cards,
      'community_cards2',h.community_cards2,
      'community_cards3',h.community_cards3,
      'rit_boards',h.rit_boards,
      'players',h.players,
      'actions',h.actions,
      'winners',h.winners,
      'winners_by_board',h.winners_by_board,
      'game_variant',h.game_variant,
      'small_blind',h.small_blind,
      'big_blind',h.big_blind,
      'rake_amount',h.rake_amount,
      'bbj_amount',h.bbj_amount,
      'button_seat',h.button_seat,
      -- This is the same participant-visible showdown-only field selected by
      -- the prior query; private folded cards remain only in own fact rows.
      'hole_cards',h.hole_cards,
      'showdown',h.showdown,
      'pots',h.pots,
      'bomb_pot',h.bomb_pot,
      'kill_pot',h.kill_pot
    ) AS hand
    FROM public.hand_history h
   WHERE (p_table_id IS NULL OR h.table_id=p_table_id)
     AND EXISTS (
       SELECT 1
         FROM public.ca_hand_facts f
        WHERE f.hand_id=h.id
          AND f.user_id=v_user
          AND f.club_id=p_club_id
     )
   ORDER BY h.hand_number DESC
   LIMIT LEAST(GREATEST(COALESCE(p_limit,50),1),200)
  OFFSET LEAST(GREATEST(COALESCE(p_offset,0),0),1000000);
END
$$;


ALTER FUNCTION public.ca_own_hand_history_by_club(p_club_id uuid, p_table_id uuid, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- TOC entry 4590 (class 1255 OID 95131564)
-- Name: ca_player_cash_opportunity_stats(uuid, integer, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_cash_opportunity_stats(p_user uuid, p_days integer DEFAULT 30, p_tz text DEFAULT 'UTC'::text, p_asset text DEFAULT 'chips'::text, p_club uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_days integer := CASE WHEN p_days IS NULL THEN NULL ELSE least(greatest(p_days,1),3650) END;
  v_from timestamptz;
  v_to timestamptz;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL OR p_user IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'stats access refused' USING ERRCODE='42501';
  END IF;
  IF p_asset NOT IN ('chips','diamonds') THEN RAISE EXCEPTION 'invalid asset'; END IF;
  IF p_club IS NOT NULL THEN
    PERFORM public.ca_assert_player_stats_club(p_user,p_club,p_asset);
  END IF;
  SELECT b.from_at,b.to_at INTO v_from,v_to
    FROM public.ca_stats_calendar_bounds(v_days,p_tz,now()) b;
  SELECT jsonb_build_object(
    'contract_version',2,'coverage',jsonb_build_object(
      'source','ca_hand_facts','from',v_from,'club_id',p_club,
      'exact_hands',count(*) FILTER (WHERE three_bet_opportunity IS NOT NULL),
      'unavailable_hands',count(*) FILTER (WHERE three_bet_opportunity IS NULL)),
    'opportunities',jsonb_build_object(
      'three_bet',jsonb_build_object('opportunities',count(*) FILTER(WHERE three_bet_opportunity),'actions',count(*) FILTER(WHERE three_bet_opportunity AND three_bet)),
      'four_bet',jsonb_build_object('opportunities',count(*) FILTER(WHERE four_bet_opportunity),'actions',count(*) FILTER(WHERE four_bet_opportunity AND four_bet)),
      'steal',jsonb_build_object('opportunities',count(*) FILTER(WHERE steal_opportunity),'actions',count(*) FILTER(WHERE steal_opportunity AND stole)),
      'squeeze',jsonb_build_object('opportunities',count(*) FILTER(WHERE squeeze_opportunity),'actions',count(*) FILTER(WHERE squeeze_opportunity AND squeezed)),
      'blind_defense',jsonb_build_object('opportunities',count(*) FILTER(WHERE blind_defense_opportunity),'actions',count(*) FILTER(WHERE blind_defense_opportunity AND defended_blind)),
      'cbet_flop',jsonb_build_object('opportunities',count(*) FILTER(WHERE cbet_flop_opportunity),'actions',count(*) FILTER(WHERE cbet_flop_opportunity AND cbet_flop)),
      'barrel_turn',jsonb_build_object('opportunities',count(*) FILTER(WHERE barrel_turn_opportunity),'actions',count(*) FILTER(WHERE barrel_turn_opportunity AND barreled_turn)),
      'barrel_river',jsonb_build_object('opportunities',count(*) FILTER(WHERE barrel_river_opportunity),'actions',count(*) FILTER(WHERE barrel_river_opportunity AND barreled_river)),
      'check_raise',jsonb_build_object('opportunities',count(*) FILTER(WHERE check_raise_opportunity),'actions',count(*) FILTER(WHERE check_raise_opportunity AND check_raised)),
      'donk',jsonb_build_object('opportunities',count(*) FILTER(WHERE donk_opportunity),'actions',count(*) FILTER(WHERE donk_opportunity AND donk_bet)),
      'probe',jsonb_build_object('opportunities',count(*) FILTER(WHERE probe_opportunity),'actions',count(*) FILTER(WHERE probe_opportunity AND probe_bet))),
    'actions_by_street',jsonb_build_object(
      'preflop',jsonb_build_object('aggressive',coalesce(sum(aggressive_actions_preflop),0),'passive',coalesce(sum(passive_actions_preflop),0)),
      'flop',jsonb_build_object('aggressive',coalesce(sum(aggressive_actions_flop),0),'passive',coalesce(sum(passive_actions_flop),0)),
      'turn',jsonb_build_object('aggressive',coalesce(sum(aggressive_actions_turn),0),'passive',coalesce(sum(passive_actions_turn),0)),
      'river',jsonb_build_object('aggressive',coalesce(sum(aggressive_actions_river),0),'passive',coalesce(sum(passive_actions_river),0))),
    'context',jsonb_build_object(
      'in_position_hands',count(*) FILTER(WHERE hero_in_position),
      'position_measured_hands',count(hero_in_position),
      'average_effective_stack_bb',avg(effective_stack_bb_at_deal)))
  INTO v_result
  FROM public.ca_hand_facts f
  LEFT JOIN public.clubs c ON c.id=f.club_id
  WHERE f.user_id=p_user
    AND (v_from IS NULL OR f.played_at>=v_from)
    AND (v_to IS NULL OR f.played_at<v_to)
    AND f.tournament_id IS NULL
    AND (p_club IS NULL OR f.club_id=p_club)
    AND coalesce(c.lifecycle_status,'active')<>'retired'
    AND coalesce(c.asset,'chips')=p_asset;
  RETURN v_result;
END
$$;


ALTER FUNCTION public.ca_player_cash_opportunity_stats(p_user uuid, p_days integer, p_tz text, p_asset text, p_club uuid) OWNER TO postgres;

--
-- TOC entry 8778 (class 1255 OID 72767712)
-- Name: ca_player_class_hands(uuid, text, text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_class_hands(p_user uuid, p_hand_class text, p_position text DEFAULT NULL::text, p_variant text DEFAULT NULL::text, p_days integer DEFAULT NULL::integer, p_limit integer DEFAULT 20, p_asset text DEFAULT 'chips'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_cap    int := least(greatest(coalesce(p_limit, 20), 1), 100);
BEGIN
  PERFORM public.ca_assert_self(p_user);
  IF p_asset IS NULL OR p_asset NOT IN ('chips', 'diamonds') THEN
    RAISE EXCEPTION 'unknown stats asset: %', p_asset USING ERRCODE = '22023';
  END IF;

  IF p_hand_class IS NULL OR btrim(p_hand_class) = '' THEN
    RETURN jsonb_build_object('hands', '[]'::jsonb, 'hand_class', NULL);
  END IF;

  SELECT jsonb_build_object(
    'hand_class', p_hand_class,
    'hands', coalesce((
      SELECT jsonb_agg(h ORDER BY (h->>'played_at') DESC)
      FROM (
        SELECT jsonb_build_object(
          'hand_id',    f.hand_id,
          'played_at',  f.played_at,
          'position',   f.position,
          'net',        round(f.net, 2),
          'net_bb',     round(f.net_bb, 2),
          'big_blind',  f.big_blind,
          'variant',    f.game_variant,
          'was_all_in', f.was_all_in,
          'showdown',   f.went_to_showdown,
          'won',        (f.net > 0),
          'hole_cards', f.hole_cards
        ) AS h
        FROM public.ca_hand_facts f
        WHERE f.user_id = p_user
          AND coalesce(f.club_id IN (SELECT c.id FROM public.clubs c WHERE c.asset = 'diamonds'), false) = (p_asset = 'diamonds')
          AND f.hand_class = p_hand_class
          AND (p_position IS NULL OR f.position = p_position)
          AND (p_variant  IS NULL OR f.game_variant = p_variant)
          AND (p_days     IS NULL OR f.played_at >= now() - make_interval(days => p_days))
        ORDER BY f.played_at DESC
        LIMIT v_cap
      ) sub
    ), '[]'::jsonb),
    'generated_at', now()
  ) INTO v_result;

  RETURN v_result;
END $$;


ALTER FUNCTION public.ca_player_class_hands(p_user uuid, p_hand_class text, p_position text, p_variant text, p_days integer, p_limit integer, p_asset text) OWNER TO postgres;

--
-- TOC entry 8233 (class 1255 OID 93130409)
-- Name: ca_player_class_hands_by_club(uuid, text, text, text, integer, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_class_hands_by_club(p_user uuid, p_hand_class text, p_position text DEFAULT NULL::text, p_variant text DEFAULT NULL::text, p_days integer DEFAULT NULL::integer, p_limit integer DEFAULT 20, p_asset text DEFAULT 'chips'::text, p_club_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_cap integer:=least(greatest(coalesce(p_limit,20),1),100);
BEGIN
  -- funded_stats_scope: historical funding, original caller gates.
  PERFORM public.ca_assert_player_stats_club(p_user,p_club_id,p_asset);
  IF p_hand_class IS NULL OR btrim(p_hand_class)='' THEN
    RETURN jsonb_build_object('contract_version',2,
      'scope',jsonb_build_object('target_user_id',p_user,'club_id',p_club_id,'asset',p_asset,
        'range_days',CASE WHEN p_days IS NULL THEN NULL ELSE least(greatest(p_days,1),3650) END,'visibility','owner'),
      'hands','[]'::jsonb,'hand_class',NULL,'generated_at',now());
  END IF;
  RETURN jsonb_build_object('contract_version',2,
    'scope',jsonb_build_object('target_user_id',p_user,'club_id',p_club_id,'asset',p_asset,
      'range_days',CASE WHEN p_days IS NULL THEN NULL ELSE least(greatest(p_days,1),3650) END,'visibility','owner'),
    'hand_class',p_hand_class,'hands',coalesce((SELECT jsonb_agg(h ORDER BY played_at DESC)
    FROM (SELECT f.played_at,jsonb_build_object('hand_id',f.hand_id,'played_at',f.played_at,
      'position',f.position,'net',round(f.net,2),'net_bb',round(f.net_bb,2),
      'big_blind',f.big_blind,'variant',f.game_variant,'was_all_in',f.was_all_in,
      'showdown',f.went_to_showdown,'won',f.net>0,'hole_cards',f.hole_cards) h
      FROM (
 WITH receipts AS MATERIALIZED (
  SELECT DISTINCT ON(table_id,account_entity_id,seat_joined_at)
   table_id,account_entity_id,seat_joined_at,funding_club_id
  FROM public.cash_participant_funding_receipts
  WHERE account_entity_id=p_user AND operation_kind='buyin'
  ORDER BY table_id,account_entity_id,seat_joined_at,recorded_at DESC,id DESC
 ), funding AS MATERIALIZED (
  SELECT *,lead(seat_joined_at) OVER(PARTITION BY table_id,account_entity_id ORDER BY seat_joined_at) until_at
  FROM receipts
 )
 SELECT fact.*,coalesce(x.funding_club_id,tp.club_id,ra.club_id,fact.club_id) funded_club
 FROM public.ca_hand_facts fact
 LEFT JOIN funding x ON fact.tournament_id IS NULL AND x.table_id=fact.table_id
  AND fact.played_at>=x.seat_joined_at AND (x.until_at IS NULL OR fact.played_at<x.until_at)
 LEFT JOIN public.tournament_players tp ON tp.tournament_id=fact.tournament_id AND tp.user_id=fact.user_id
 LEFT JOIN public.rake_attributions ra ON x.funding_club_id IS NULL AND tp.club_id IS NULL
  AND ra.hand_id=fact.hand_id AND ra.player_id=fact.user_id
 WHERE fact.user_id=p_user
 ) f WHERE f.user_id=p_user AND f.funded_club=p_club_id
        AND f.hand_class=p_hand_class AND (p_position IS NULL OR f.position=p_position)
        AND (p_variant IS NULL OR f.game_variant=p_variant)
        AND (p_days IS NULL OR f.played_at>=now()-make_interval(days=>least(greatest(p_days,1),3650)))
      ORDER BY f.played_at DESC LIMIT v_cap) q),'[]'::jsonb),'generated_at',now());
END;$$;


ALTER FUNCTION public.ca_player_class_hands_by_club(p_user uuid, p_hand_class text, p_position text, p_variant text, p_days integer, p_limit integer, p_asset text, p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 7513 (class 1255 OID 72767706)
-- Name: ca_player_ev_curve(uuid, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_ev_curve(p_user uuid, p_days integer DEFAULT NULL::integer, p_limit integer DEFAULT 5000, p_asset text DEFAULT 'chips'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_cap    int := least(greatest(coalesce(p_limit, 5000), 100), 20000);
BEGIN
  PERFORM public.ca_assert_self(p_user);
  IF p_asset IS NULL OR p_asset NOT IN ('chips', 'diamonds') THEN
    RAISE EXCEPTION 'unknown stats asset: %', p_asset USING ERRCODE = '22023';
  END IF;

  WITH picked AS MATERIALIZED (
    SELECT f.played_at, f.net_bb, f.ev_net_bb, f.was_all_in, f.all_in_equity
    FROM public.ca_hand_facts f
    WHERE f.user_id = p_user
      AND coalesce(f.club_id IN (SELECT c.id FROM public.clubs c WHERE c.asset = 'diamonds'), false) = (p_asset = 'diamonds')
      AND f.went_to_showdown = true
      AND f.game_variant NOT IN ('mtt', 'sit_and_go')
      AND (p_days IS NULL OR f.played_at >= now() - make_interval(days => p_days))
    ORDER BY f.played_at DESC
    LIMIT v_cap
  ),
  accum AS MATERIALIZED (
    SELECT
      row_number() OVER w AS i,
      played_at AS at,
      net_bb,
      ev_net_bb,
      sum(net_bb) OVER w AS cum_net_bb,
      sum(ev_net_bb) OVER w AS cum_ev_net_bb,
      sum(net_bb - ev_net_bb) OVER w AS luck_bb,
      -- CARRY was_all_in THROUGH (2026-08-24). `agg` counts
      -- `FILTER (WHERE was_all_in = true)` but selects FROM accum, and accum
      -- projected only played_at, net_bb, ev_net_bb and the running sums - it
      -- dropped was_all_in on the floor. So every single call raised
      -- 42703 column "was_all_in" does not exist: the EV curve was broken 100%
      -- of the time, for every player, not merely wrong at an edge.
      was_all_in
    FROM picked
    WINDOW w AS (ORDER BY played_at ASC)
  ),
  agg AS MATERIALIZED (
    SELECT
      count(*) AS hands,
      count(*) FILTER (WHERE was_all_in = true) AS all_in_hands,
      sum(net_bb) AS net_bb,
      sum(ev_net_bb) AS ev_net_bb,
      sum(net_bb - ev_net_bb) AS luck_bb,
      max(net_bb - ev_net_bb) AS biggest_suckout,
      min(net_bb - ev_net_bb) AS biggest_beat,
      CASE WHEN count(*) = 0 THEN 0
           ELSE (sum(net_bb - ev_net_bb) / count(*)) * 100 END AS luck_bb_per_100,
      (count(*) = v_cap) AS capped
    FROM accum
  )
  SELECT jsonb_build_object(
    'points', coalesce((
      SELECT jsonb_agg(x) FROM (
        SELECT i, at, net_bb, ev_net_bb, cum_net_bb, cum_ev_net_bb
        FROM accum
      ) x
    ), '[]'::jsonb),
    'summary', (
      SELECT jsonb_build_object(
        'hands', hands,
        'all_in_hands', all_in_hands,
        'net_bb', round(coalesce(net_bb, 0), 2),
        'ev_net_bb', round(coalesce(ev_net_bb, 0), 2),
        'luck_bb', round(coalesce(luck_bb, 0), 2),
        'luck_bb_per_100', round(coalesce(luck_bb_per_100, 0), 2),
        'biggest_suckout', round(coalesce(biggest_suckout, 0), 2),
        'biggest_beat', round(coalesce(biggest_beat, 0), 2),
        'capped', capped
      )
      FROM agg
    ),
    'generated_at', now()
  ) INTO v_result;

  RETURN v_result;
END $$;


ALTER FUNCTION public.ca_player_ev_curve(p_user uuid, p_days integer, p_limit integer, p_asset text) OWNER TO postgres;

--
-- TOC entry 8810 (class 1255 OID 93130392)
-- Name: ca_player_ev_curve_by_club(uuid, integer, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_ev_curve_by_club(p_user uuid, p_days integer DEFAULT NULL::integer, p_limit integer DEFAULT 5000, p_asset text DEFAULT 'chips'::text, p_club_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_cap integer := least(greatest(coalesce(p_limit, 5000), 100), 20000);
BEGIN
  -- funded_stats_scope: historical funding, original caller gates.
  PERFORM public.ca_assert_player_stats_club(p_user, p_club_id, p_asset);
  RETURN (WITH picked AS MATERIALIZED (
    SELECT f.played_at, f.net_bb, f.ev_net_bb, f.was_all_in
    FROM (
 WITH receipts AS MATERIALIZED (
  SELECT DISTINCT ON(table_id,account_entity_id,seat_joined_at)
   table_id,account_entity_id,seat_joined_at,funding_club_id
  FROM public.cash_participant_funding_receipts
  WHERE account_entity_id=p_user AND operation_kind='buyin'
  ORDER BY table_id,account_entity_id,seat_joined_at,recorded_at DESC,id DESC
 ), funding AS MATERIALIZED (
  SELECT *,lead(seat_joined_at) OVER(PARTITION BY table_id,account_entity_id ORDER BY seat_joined_at) until_at
  FROM receipts
 )
 SELECT fact.*,coalesce(x.funding_club_id,tp.club_id,ra.club_id,fact.club_id) funded_club
 FROM public.ca_hand_facts fact
 LEFT JOIN funding x ON fact.tournament_id IS NULL AND x.table_id=fact.table_id
  AND fact.played_at>=x.seat_joined_at AND (x.until_at IS NULL OR fact.played_at<x.until_at)
 LEFT JOIN public.tournament_players tp ON tp.tournament_id=fact.tournament_id AND tp.user_id=fact.user_id
 LEFT JOIN public.rake_attributions ra ON x.funding_club_id IS NULL AND tp.club_id IS NULL
  AND ra.hand_id=fact.hand_id AND ra.player_id=fact.user_id
 WHERE fact.user_id=p_user
 ) f WHERE f.user_id=p_user AND f.funded_club=p_club_id
      AND f.went_to_showdown AND f.game_variant NOT IN ('mtt','sit_and_go')
      AND (p_days IS NULL OR f.played_at >= now()-make_interval(days=>least(greatest(p_days,1),3650)))
    ORDER BY f.played_at DESC LIMIT v_cap
  ), a AS (
    SELECT row_number() OVER w i, played_at at, net_bb, ev_net_bb,
      sum(net_bb) OVER w cum_net_bb, sum(ev_net_bb) OVER w cum_ev_net_bb,
      was_all_in FROM picked WINDOW w AS (ORDER BY played_at)
  ), s AS (
    SELECT count(*) hands, count(*) FILTER (WHERE was_all_in) all_in_hands,
      coalesce(sum(net_bb),0) net_bb, coalesce(sum(ev_net_bb),0) ev_net_bb,
      coalesce(sum(net_bb-ev_net_bb),0) luck_bb,
      coalesce(max(net_bb-ev_net_bb),0) biggest_suckout,
      coalesce(min(net_bb-ev_net_bb),0) biggest_beat FROM a
  ) SELECT jsonb_build_object('contract_version',2,
    'scope',jsonb_build_object('target_user_id',p_user,'club_id',p_club_id,'asset',p_asset,
      'range_days',CASE WHEN p_days IS NULL THEN NULL ELSE least(greatest(p_days,1),3650) END,'visibility','owner'),
    'points',coalesce((SELECT jsonb_agg(jsonb_build_object(
      'i',i,'at',at,'net_bb',net_bb,'ev_net_bb',ev_net_bb,
      'cum_net_bb',cum_net_bb,'cum_ev_net_bb',cum_ev_net_bb) ORDER BY i) FROM a),'[]'::jsonb),
    'summary',(SELECT jsonb_build_object('hands',hands,'all_in_hands',all_in_hands,
      'net_bb',round(net_bb,2),'ev_net_bb',round(ev_net_bb,2),'luck_bb',round(luck_bb,2),
      'luck_bb_per_100',CASE WHEN hands>0 THEN round(luck_bb/hands*100,2) ELSE 0 END,
      'biggest_suckout',round(biggest_suckout,2),'biggest_beat',round(biggest_beat,2),
      'capped',hands=v_cap) FROM s),'generated_at',now()));
END;$$;


