CREATE FUNCTION public.ca_player_hand_grid_by_club(p_user uuid, p_position text DEFAULT NULL::text, p_variant text DEFAULT NULL::text, p_days integer DEFAULT NULL::integer, p_asset text DEFAULT 'chips'::text, p_club_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
