      'classes_seen',(SELECT count(*) FROM g)),
    'filters',jsonb_build_object('position',p_position,'variant',p_variant,
      'days',CASE WHEN p_days IS NULL THEN NULL ELSE least(greatest(p_days,1),3650) END),
    'generated_at',now()));
