-- Name: FUNCTION ca_player_hands_v2(p_user uuid, p_mode text, p_limit integer, p_asset text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_player_hands_v2(p_user uuid, p_mode text, p_limit integer, p_asset text) IS 'Owner-only notable-hand evidence in one asset. Returns contract v2 request scope and a bounded all-clubs hand list; hole cards remain the owner''s own only.';


--
-- TOC entry 4690 (class 1255 OID 93130419)
-- Name: ca_player_hands_v2_by_club(uuid, text, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_hands_v2_by_club(p_user uuid, p_mode text DEFAULT 'recent'::text, p_limit integer DEFAULT 25, p_asset text DEFAULT 'chips'::text, p_club_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c_window constant integer := 750;
  v_limit integer := least(greatest(coalesce(p_limit,25),1),100);
  v_mode text := lower(coalesce(p_mode,'recent'));
BEGIN
  -- funded_stats_scope: historical funding, original caller gates.
  PERFORM public.ca_assert_player_stats_club(p_user,p_club_id,p_asset);
  IF v_mode NOT IN ('recent','biggest_won','biggest_lost') THEN
    v_mode := 'recent';
  END IF;
  RETURN (WITH mine AS MATERIALIZED (
    SELECT f.hand_id id, f.played_at, f.game_variant variant, f.big_blind,
      f.tournament_id IS NOT NULL is_tournament, nullif(f.position,'UNK') position,
      round(coalesce(h.pot_size,0)::numeric,2) pot_size,
      round(f.returned,2) won, round(f.net,2) profit, f.net>0 is_winner,
      f.players_dealt players, coalesce(h.board,to_jsonb(h.community_cards)) board,
      f.hole_cards
    FROM (
 WITH receipts AS MATERIALIZED (
  SELECT DISTINCT ON(table_id,account_entity_id,seat_joined_at)
   table_id,account_entity_id,seat_joined_at,funding_club_id
  FROM public.cash_participant_funding_receipts
  WHERE account_entity_id=p_user AND operation_kind='buyin'
  ORDER BY table_id,account_entity_id,seat_joined_at,recorded_at DESC,id DESC
 ), funding AS MATERIALIZED (
  SELECT *,lead(seat_joined_at) OVER(PARTITION BY table_id,account_entity_id ORDER BY seat_joined_at) until_at
  FROM receipts
 )
 SELECT fact.*,coalesce(x.funding_club_id,tp.club_id,ra.club_id,fact.club_id) funded_club
 FROM public.ca_hand_facts fact
 LEFT JOIN funding x ON fact.tournament_id IS NULL AND x.table_id=fact.table_id
  AND fact.played_at>=x.seat_joined_at AND (x.until_at IS NULL OR fact.played_at<x.until_at)
 LEFT JOIN public.tournament_players tp ON tp.tournament_id=fact.tournament_id AND tp.user_id=fact.user_id
 LEFT JOIN public.rake_attributions ra ON x.funding_club_id IS NULL AND tp.club_id IS NULL
  AND ra.hand_id=fact.hand_id AND ra.player_id=fact.user_id
 WHERE fact.user_id=p_user
 ) f
    LEFT JOIN public.hand_history h ON h.id=f.hand_id
    WHERE f.user_id=p_user AND f.funded_club=p_club_id
      AND (v_mode='recent' OR f.tournament_id IS NULL)
    ORDER BY f.played_at DESC
    LIMIT CASE WHEN v_mode='recent' THEN v_limit ELSE c_window END
  ), ranked AS (
    SELECT * FROM mine
    ORDER BY CASE WHEN v_mode='biggest_won' THEN profit END DESC NULLS LAST,
      CASE WHEN v_mode='biggest_lost' THEN profit END ASC NULLS LAST,
      CASE WHEN v_mode='recent' THEN played_at END DESC NULLS LAST
    LIMIT v_limit
  ) SELECT jsonb_build_object('contract_version',2,
    'scope',jsonb_build_object('target_user_id',p_user,'club_id',p_club_id,'asset',p_asset,'visibility','owner'),
    'hands',coalesce(jsonb_agg(to_jsonb(r)
    ORDER BY CASE WHEN v_mode='biggest_won' THEN profit END DESC NULLS LAST,
      CASE WHEN v_mode='biggest_lost' THEN profit END ASC NULLS LAST,
      CASE WHEN v_mode='recent' THEN played_at END DESC NULLS LAST), '[]'::jsonb),
    'generated_at',now())
    FROM ranked r);
END;$$;


ALTER FUNCTION public.ca_player_hands_v2_by_club(p_user uuid, p_mode text, p_limit integer, p_asset text, p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 5860 (class 1255 OID 153039692)
-- Name: ca_player_history_can_read(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_history_can_read(p_club_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT p_club_id IS NOT NULL AND auth.uid() IS NOT NULL AND (
    EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.is_admin IS TRUE)
    OR EXISTS (SELECT 1 FROM public.clubs c WHERE c.id=p_club_id AND c.owner_id=auth.uid())
    OR EXISTS (SELECT 1 FROM public.club_members cm WHERE cm.club_id=p_club_id
      AND cm.user_id=auth.uid() AND cm.role IN ('owner','co_owner','admin')
      AND cm.status IN ('active','approved'))
    OR public.fn_is_union_overseer(p_club_id,auth.uid())
    OR public.fn_union_oversees_club(p_club_id,auth.uid())
  );
$$;


ALTER FUNCTION public.ca_player_history_can_read(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 5660 (class 1255 OID 72767715)
-- Name: ca_player_nemesis(uuid, integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_nemesis(p_user uuid, p_days integer DEFAULT NULL::integer, p_min_hands integer DEFAULT 25, p_limit integer DEFAULT 10, p_asset text DEFAULT 'chips'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  PERFORM public.ca_assert_self(p_user);
  IF p_asset IS NULL OR p_asset NOT IN ('chips', 'diamonds') THEN
    RAISE EXCEPTION 'unknown stats asset: %', p_asset USING ERRCODE = '22023';
  END IF;

  WITH flows AS MATERIALIZED (
    SELECT t.loser_id  AS opponent_id,  t.amount AS delta
    FROM public.ca_hand_transfers t
    WHERE t.winner_id = p_user
      AND coalesce(t.club_id IN (SELECT c.id FROM public.clubs c WHERE c.asset = 'diamonds'), false) = (p_asset = 'diamonds')
      AND (p_days IS NULL OR t.played_at >= now() - make_interval(days => p_days))
    UNION ALL
    SELECT t.winner_id AS opponent_id, -t.amount AS delta
    FROM public.ca_hand_transfers t
    WHERE t.loser_id = p_user
      AND coalesce(t.club_id IN (SELECT c.id FROM public.clubs c WHERE c.asset = 'diamonds'), false) = (p_asset = 'diamonds')
      AND (p_days IS NULL OR t.played_at >= now() - make_interval(days => p_days))
  ),
  netted AS MATERIALIZED (
    SELECT opponent_id, sum(delta) AS net_chips
    FROM flows
    GROUP BY opponent_id
  ),
  shared AS MATERIALIZED (
    SELECT o.opponent_id, count(*) AS hands_together, max(f.played_at) AS last_played_at
    FROM public.ca_hand_facts f
    CROSS JOIN LATERAL unnest(coalesce(f.opponent_ids, '{}'::uuid[])) AS o(opponent_id)
    WHERE f.user_id = p_user
      AND coalesce(f.club_id IN (SELECT c.id FROM public.clubs c WHERE c.asset = 'diamonds'), false) = (p_asset = 'diamonds')
      AND (p_days IS NULL OR f.played_at >= now() - make_interval(days => p_days))
    GROUP BY o.opponent_id
  ),
  joined AS MATERIALIZED (
    SELECT
      n.opponent_id,
      n.net_chips,
      coalesce(s.hands_together, 0) AS hands_together,
      s.last_played_at,
      pr.username,
      pr.avatar_url
    FROM netted n
    LEFT JOIN shared s   ON s.opponent_id = n.opponent_id
    LEFT JOIN public.profiles pr ON pr.id = n.opponent_id
    WHERE coalesce(s.hands_together, 0) >= p_min_hands
  )
  SELECT jsonb_build_object(
    'nemesis', (
      SELECT jsonb_build_object(
        'opponent_id', opponent_id, 'username', username, 'avatar_url', avatar_url,
        'net_chips', round(net_chips, 2), 'hands_together', hands_together,
        'last_played_at', last_played_at)
      FROM joined WHERE net_chips < 0 ORDER BY net_chips ASC LIMIT 1
    ),
    'target', (
      SELECT jsonb_build_object(
        'opponent_id', opponent_id, 'username', username, 'avatar_url', avatar_url,
        'net_chips', round(net_chips, 2), 'hands_together', hands_together,
        'last_played_at', last_played_at)
      FROM joined WHERE net_chips > 0 ORDER BY net_chips DESC LIMIT 1
    ),
    'worst', coalesce((
      SELECT jsonb_agg(x) FROM (
        SELECT opponent_id, username, avatar_url, round(net_chips, 2) AS net_chips,
               hands_together, last_played_at
        FROM joined WHERE net_chips < 0 ORDER BY net_chips ASC LIMIT p_limit
      ) x), '[]'::jsonb),
    'best', coalesce((
      SELECT jsonb_agg(x) FROM (
        SELECT opponent_id, username, avatar_url, round(net_chips, 2) AS net_chips,
               hands_together, last_played_at
        FROM joined WHERE net_chips > 0 ORDER BY net_chips DESC LIMIT p_limit
      ) x), '[]'::jsonb),
    'min_hands', p_min_hands,
    'opponents_qualified', (SELECT count(*) FROM joined),
    'generated_at', now()
  ) INTO v_result;

  RETURN v_result;
END $$;


ALTER FUNCTION public.ca_player_nemesis(p_user uuid, p_days integer, p_min_hands integer, p_limit integer, p_asset text) OWNER TO postgres;

--
-- TOC entry 6825 (class 1255 OID 93130415)
-- Name: ca_player_nemesis_by_club(uuid, integer, integer, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_nemesis_by_club(p_user uuid, p_days integer DEFAULT NULL::integer, p_min_hands integer DEFAULT 25, p_limit integer DEFAULT 10, p_asset text DEFAULT 'chips'::text, p_club_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET statement_timeout TO '20s'
    SET work_mem TO '64MB'
    SET enable_indexscan TO 'off'
    SET search_path TO 'public'
    AS $$
BEGIN
  -- funded_stats_scope: historical funding, original caller gates.
  PERFORM public.ca_assert_player_stats_club(p_user,p_club_id,p_asset);
  RETURN (WITH funded_stats_scope AS MATERIALIZED (SELECT hand_id,user_id,played_at,opponent_ids,funded_club FROM (
 WITH receipts AS MATERIALIZED (
  SELECT DISTINCT ON(table_id,account_entity_id,seat_joined_at)
   table_id,account_entity_id,seat_joined_at,funding_club_id
  FROM public.cash_participant_funding_receipts
  WHERE account_entity_id=p_user AND operation_kind='buyin'
  ORDER BY table_id,account_entity_id,seat_joined_at,recorded_at DESC,id DESC
 ), funding AS MATERIALIZED (
  SELECT *,lead(seat_joined_at) OVER(PARTITION BY table_id,account_entity_id ORDER BY seat_joined_at) until_at
  FROM receipts
 )
 SELECT fact.*,coalesce(x.funding_club_id,tp.club_id,ra.club_id,fact.club_id) funded_club
 FROM public.ca_hand_facts fact
 LEFT JOIN funding x ON fact.tournament_id IS NULL AND x.table_id=fact.table_id
  AND fact.played_at>=x.seat_joined_at AND (x.until_at IS NULL OR fact.played_at<x.until_at)
 LEFT JOIN public.tournament_players tp ON tp.tournament_id=fact.tournament_id AND tp.user_id=fact.user_id
 LEFT JOIN public.rake_attributions ra ON x.funding_club_id IS NULL AND tp.club_id IS NULL
  AND ra.hand_id=fact.hand_id AND ra.player_id=fact.user_id
 WHERE fact.user_id=p_user
 ) resolved), flows AS (
    SELECT loser_id opponent_id,amount delta FROM public.ca_hand_transfers ht LEFT JOIN funded_stats_scope hf ON hf.hand_id=ht.hand_id
      WHERE winner_id=p_user AND coalesce(hf.funded_club,ht.club_id)=p_club_id AND (p_days IS NULL OR ht.played_at>=now()-make_interval(days=>least(greatest(p_days,1),3650)))
    UNION ALL SELECT winner_id,-amount FROM public.ca_hand_transfers ht LEFT JOIN funded_stats_scope hf ON hf.hand_id=ht.hand_id
      WHERE loser_id=p_user AND coalesce(hf.funded_club,ht.club_id)=p_club_id AND (p_days IS NULL OR ht.played_at>=now()-make_interval(days=>least(greatest(p_days,1),3650)))
  ), netted AS (SELECT opponent_id,sum(delta) net_chips FROM flows GROUP BY opponent_id),
  shared AS (SELECT o.opponent_id,count(*) hands_together,max(f.played_at) last_played_at
    FROM funded_stats_scope f CROSS JOIN LATERAL unnest(coalesce(f.opponent_ids,'{}'::uuid[])) o(opponent_id)
    WHERE f.user_id=p_user AND f.funded_club=p_club_id
      AND (p_days IS NULL OR f.played_at>=now()-make_interval(days=>least(greatest(p_days,1),3650))) GROUP BY o.opponent_id),
  j AS (SELECT n.opponent_id,n.net_chips,s.hands_together,s.last_played_at,p.username,p.avatar_url
    FROM netted n JOIN shared s USING(opponent_id) LEFT JOIN public.profiles p ON p.id=n.opponent_id
    WHERE s.hands_together>=p_min_hands)
  SELECT jsonb_build_object('contract_version',2,
    'scope',jsonb_build_object('target_user_id',p_user,'club_id',p_club_id,'asset',p_asset,
      'range_days',CASE WHEN p_days IS NULL THEN NULL ELSE least(greatest(p_days,1),3650) END,'visibility','owner'),
    'nemesis',(SELECT to_jsonb(x) FROM (SELECT * FROM j WHERE net_chips<0 ORDER BY net_chips LIMIT 1)x),
    'target',(SELECT to_jsonb(x) FROM (SELECT * FROM j WHERE net_chips>0 ORDER BY net_chips DESC LIMIT 1)x),
    'worst',coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM j WHERE net_chips<0 ORDER BY net_chips LIMIT p_limit)x),'[]'::jsonb),
    'best',coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM j WHERE net_chips>0 ORDER BY net_chips DESC LIMIT p_limit)x),'[]'::jsonb),
    'min_hands',p_min_hands,'opponents_qualified',(SELECT count(*) FROM j),'generated_at',now()));
END;$$;


ALTER FUNCTION public.ca_player_nemesis_by_club(p_user uuid, p_days integer, p_min_hands integer, p_limit integer, p_asset text, p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 8136 (class 1255 OID 72767714)
-- Name: ca_player_rake_stats(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_rake_stats(p_user uuid DEFAULT NULL::uuid, p_days integer DEFAULT NULL::integer, p_asset text DEFAULT 'chips'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_since timestamptz;
  v_hands bigint := 0;
  v_raked_hands bigint := 0;
  v_rake numeric := 0;
  v_bb numeric := 0;
  v_first timestamptz;
  v_last timestamptz;
BEGIN
  IF p_asset IS NULL OR p_asset NOT IN ('chips', 'diamonds') THEN
    RAISE EXCEPTION 'unknown stats asset: %', p_asset USING ERRCODE = '22023';
  END IF;
  IF public.fn_caller_is_engine() THEN
    v_uid := coalesce(p_user, auth.uid());
  ELSE
    v_uid := auth.uid();
  END IF;
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object(
      'hands', 0, 'raked_hands', 0, 'rake_paid', 0,
      'rake_per_100', 0, 'rake_in_bb', 0, 'days', p_days
    );
  END IF;

  v_since := CASE WHEN p_days IS NULL THEN '-infinity'::timestamptz
                  ELSE now() - make_interval(days => greatest(p_days, 1)) END;

  SELECT count(*),
         count(*) FILTER (WHERE coalesce(f.rake_paid, 0) > 0),
         coalesce(sum(f.rake_paid), 0),
         coalesce(sum(CASE WHEN f.big_blind > 0 THEN f.rake_paid / f.big_blind ELSE 0 END), 0),
         min(f.played_at),
         max(f.played_at)
  INTO v_hands, v_raked_hands, v_rake, v_bb, v_first, v_last
  FROM public.ca_hand_facts f
  WHERE f.user_id = v_uid
    AND f.played_at >= v_since
    AND f.tournament_id IS NULL
    AND coalesce(f.club_id IN (SELECT c.id FROM public.clubs c WHERE c.asset = 'diamonds'), false) = (p_asset = 'diamonds');

  RETURN jsonb_build_object(
    'hands', v_hands,
    'raked_hands', v_raked_hands,
    'rake_paid', round(v_rake, 2),
    'rake_per_100', CASE WHEN v_hands > 0 THEN round(v_rake * 100.0 / v_hands, 2) ELSE 0 END,
    'rake_in_bb', round(v_bb, 2),
    'bb_per_100', CASE WHEN v_hands > 0 THEN round(v_bb * 100.0 / v_hands, 2) ELSE 0 END,
    'avg_rake_per_raked_hand',
      CASE WHEN v_raked_hands > 0 THEN round(v_rake / v_raked_hands, 4) ELSE 0 END,
    'first_hand_at', v_first,
    'last_hand_at', v_last,
    'days', p_days
  );
END;
$$;


ALTER FUNCTION public.ca_player_rake_stats(p_user uuid, p_days integer, p_asset text) OWNER TO postgres;

--
-- TOC entry 8577 (class 1255 OID 93130410)
-- Name: ca_player_rake_stats_by_club(uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_rake_stats_by_club(p_user uuid DEFAULT NULL::uuid, p_days integer DEFAULT NULL::integer, p_asset text DEFAULT 'chips'::text, p_club_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid:=coalesce(p_user,auth.uid()); v_hands bigint; v_raked bigint;
  v_rake numeric; v_bb numeric; v_first timestamptz; v_last timestamptz;
BEGIN
  -- funded_stats_scope: historical funding, original caller gates.
  PERFORM public.ca_assert_player_stats_club(v_uid,p_club_id,p_asset);
  SELECT count(*),count(*) FILTER(WHERE coalesce(rake_paid,0)>0),coalesce(sum(rake_paid),0),
    coalesce(sum(CASE WHEN big_blind>0 THEN rake_paid/big_blind ELSE 0 END),0),
    min(played_at),max(played_at) INTO v_hands,v_raked,v_rake,v_bb,v_first,v_last
  FROM (
 WITH receipts AS MATERIALIZED (
  SELECT DISTINCT ON(table_id,account_entity_id,seat_joined_at)
   table_id,account_entity_id,seat_joined_at,funding_club_id
  FROM public.cash_participant_funding_receipts
  WHERE account_entity_id=v_uid AND operation_kind='buyin'
  ORDER BY table_id,account_entity_id,seat_joined_at,recorded_at DESC,id DESC
 ), funding AS MATERIALIZED (
  SELECT *,lead(seat_joined_at) OVER(PARTITION BY table_id,account_entity_id ORDER BY seat_joined_at) until_at
  FROM receipts
 )
 SELECT fact.*,coalesce(x.funding_club_id,tp.club_id,ra.club_id,fact.club_id) funded_club
 FROM public.ca_hand_facts fact
 LEFT JOIN funding x ON fact.tournament_id IS NULL AND x.table_id=fact.table_id
  AND fact.played_at>=x.seat_joined_at AND (x.until_at IS NULL OR fact.played_at<x.until_at)
 LEFT JOIN public.tournament_players tp ON tp.tournament_id=fact.tournament_id AND tp.user_id=fact.user_id
 LEFT JOIN public.rake_attributions ra ON x.funding_club_id IS NULL AND tp.club_id IS NULL
  AND ra.hand_id=fact.hand_id AND ra.player_id=fact.user_id
 WHERE fact.user_id=v_uid
 ) funded_stats_scope WHERE user_id=v_uid AND funded_club=p_club_id AND tournament_id IS NULL
    AND (p_days IS NULL OR played_at>=now()-make_interval(days=>least(greatest(p_days,1),3650)));
  RETURN jsonb_build_object('contract_version',2,
    'scope',jsonb_build_object('target_user_id',v_uid,'club_id',p_club_id,'asset',p_asset,
      'range_days',CASE WHEN p_days IS NULL THEN NULL ELSE least(greatest(p_days,1),3650) END,'visibility','owner'),
    'hands',v_hands,'raked_hands',v_raked,'rake_paid',round(v_rake,2),
    'rake_per_100',CASE WHEN v_hands>0 THEN round(v_rake*100/v_hands,2) ELSE 0 END,
    'rake_in_bb',round(v_bb,2),'bb_per_100',CASE WHEN v_hands>0 THEN round(v_bb*100/v_hands,2) ELSE 0 END,
    'avg_rake_per_raked_hand',CASE WHEN v_raked>0 THEN round(v_rake/v_raked,4) ELSE 0 END,
    'first_hand_at',v_first,'last_hand_at',v_last,'days',
      CASE WHEN p_days IS NULL THEN NULL ELSE least(greatest(p_days,1),3650) END);
END;$$;


ALTER FUNCTION public.ca_player_rake_stats_by_club(p_user uuid, p_days integer, p_asset text, p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 8616 (class 1255 OID 95132387)
-- Name: ca_player_stats_cash_sessions(uuid, uuid, integer, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_stats_cash_sessions(p_user uuid, p_club_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT NULL::integer, p_tz text DEFAULT 'UTC'::text, p_asset text DEFAULT 'chips'::text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_days integer;
  v_tz text;
  v_from timestamptz;
  v_to timestamptz;
  v_limit integer := least(greatest(coalesce(p_limit,100),1),250);
  v_total integer;
  v_exact integer;
  v_partial integer;
  v_rows jsonb;
BEGIN
  PERFORM public.ca_assert_self(p_user);
  IF p_asset IS NULL OR p_asset NOT IN ('chips','diamonds') THEN
    RAISE EXCEPTION 'unknown stats asset: %',p_asset USING ERRCODE='22023';
  END IF;
  IF p_club_id IS NOT NULL THEN
    PERFORM public.ca_assert_player_stats_club(p_user,p_club_id,p_asset);
  END IF;
  SELECT range_days,range_tz,from_at,to_at INTO v_days,v_tz,v_from,v_to
    FROM public.ca_stats_calendar_bounds(p_days,p_tz,now());

  WITH eligible AS MATERIALIZED (
    SELECT c.id
      FROM public.club_members m JOIN public.clubs c ON c.id=m.club_id
     WHERE m.user_id=p_user AND m.status IN ('active','approved')
       AND coalesce(c.lifecycle_status,'active')<>'retired'
       AND coalesce(c.asset,'chips')=p_asset
       AND (p_club_id IS NULL OR c.id=p_club_id)
  ), scoped AS MATERIALIZED (
    SELECT s.*
      FROM public.cash_player_session s JOIN eligible e ON e.id=s.club_id
     WHERE s.player_id=p_user
       AND (v_from IS NULL OR coalesce(s.closed_at,'infinity'::timestamptz)>v_from)
       AND (v_to IS NULL OR s.opened_at<v_to)
  ) SELECT count(*)::integer,
      count(*) FILTER (WHERE financial_capture_status='exact')::integer,
      count(*) FILTER (WHERE financial_capture_status IN ('partial','legacy_unavailable'))::integer
    INTO v_total,v_exact,v_partial FROM scoped;

  WITH eligible AS MATERIALIZED (
    SELECT c.id
      FROM public.club_members m JOIN public.clubs c ON c.id=m.club_id
     WHERE m.user_id=p_user AND m.status IN ('active','approved')
       AND coalesce(c.lifecycle_status,'active')<>'retired'
       AND coalesce(c.asset,'chips')=p_asset
       AND (p_club_id IS NULL OR c.id=p_club_id)
  ), scoped AS MATERIALIZED (
    SELECT s.*
      FROM public.cash_player_session s JOIN eligible e ON e.id=s.club_id
     WHERE s.player_id=p_user
       AND (v_from IS NULL OR coalesce(s.closed_at,'infinity'::timestamptz)>v_from)
       AND (v_to IS NULL OR s.opened_at<v_to)
     ORDER BY s.opened_at DESC,s.id DESC LIMIT v_limit
  ), measured AS (
    SELECT s.*,
      (SELECT count(*)::integer FROM public.cash_player_session o
        WHERE o.player_id=s.player_id AND o.id<>s.id AND o.club_id=s.club_id
          AND ((s.cluster_id IS NOT NULL AND o.cluster_id=s.cluster_id)
               OR (s.cluster_id IS NULL AND o.cluster_id IS NULL AND o.table_id=s.table_id))
          AND tstzrange(o.opened_at,coalesce(o.closed_at,'infinity'),'[)') &&
              tstzrange(s.opened_at,coalesce(s.closed_at,'infinity'),'[)')) overlap_count,
      (SELECT count(*)::integer FROM public.ca_hand_facts f
         LEFT JOIN public.tables ft ON ft.id=f.table_id
        WHERE f.user_id=s.player_id AND f.club_id=s.club_id AND f.tournament_id IS NULL
          AND f.played_at>=s.opened_at AND f.played_at<coalesce(s.closed_at,'infinity')
          AND ((s.cluster_id IS NOT NULL AND ft.cluster_id=s.cluster_id)
               OR (s.cluster_id IS NULL AND f.table_id=s.table_id))) fact_hands,
      (SELECT coalesce(sum(f.net),0) FROM public.ca_hand_facts f
         LEFT JOIN public.tables ft ON ft.id=f.table_id
        WHERE f.user_id=s.player_id AND f.club_id=s.club_id AND f.tournament_id IS NULL
          AND f.played_at>=s.opened_at AND f.played_at<coalesce(s.closed_at,'infinity')
          AND ((s.cluster_id IS NOT NULL AND ft.cluster_id=s.cluster_id)
               OR (s.cluster_id IS NULL AND f.table_id=s.table_id))) fact_net
      FROM scoped s
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'session_id',id,'club_id',club_id,'table_id',table_id,'cluster_id',cluster_id,
    'variant',variant,'small_blind',sb,'big_blind',bb,
    'opened_at',opened_at,'closed_at',closed_at,'closed_reason',closed_reason,
    'duration_seconds',CASE WHEN closed_at IS NULL THEN NULL ELSE greatest(extract(epoch from closed_at-opened_at)::bigint,0) END,
    'buyin_and_rebuys',baseline,
    'final_cashout',CASE WHEN financial_capture_status='exact' THEN final_stack ELSE NULL END,
    'session_result',CASE WHEN financial_capture_status='exact' THEN final_stack-baseline ELSE NULL END,
    'capture_status',financial_capture_status,
    'capture_reason',CASE financial_capture_status WHEN 'open' THEN 'session_open' WHEN 'partial' THEN 'close_stack_unavailable' WHEN 'legacy_unavailable' THEN 'legacy_session_predates_exact_capture' ELSE NULL END,
    'hand_count',CASE WHEN overlap_count=0 THEN fact_hands ELSE NULL END,
    'hand_net',CASE WHEN overlap_count=0 THEN fact_net ELSE NULL END,
    'hand_evidence_status',CASE WHEN overlap_count>0 THEN 'overlap_unavailable' ELSE 'exact_facts' END,
    'overlap',overlap_count>0,'overlap_count',overlap_count,
    'evidence',jsonb_build_object('kind','cash_session','session_id',id)
  ) ORDER BY opened_at DESC,id DESC),'[]'::jsonb) INTO v_rows FROM measured;

  RETURN jsonb_build_object(
    'contract_version',2,
    'scope',jsonb_build_object('target_user_id',p_user,'club_id',p_club_id,'asset',p_asset,
      'range_days',v_days,'range_tz',v_tz,'from',v_from,'to',v_to,'visibility','owner'),
    'coverage',jsonb_build_object('source','cash_player_session+ca_hand_facts',
      'total_sessions',v_total,'returned_sessions',jsonb_array_length(v_rows),
      'capped',v_total>v_limit,
      'exact_sessions',v_exact,
      'legacy_or_partial_sessions',v_partial),
    'sessions',v_rows,'generated_at',now());
END;
$$;


ALTER FUNCTION public.ca_player_stats_cash_sessions(p_user uuid, p_club_id uuid, p_days integer, p_tz text, p_asset text, p_limit integer) OWNER TO postgres;

--
-- TOC entry 4361 (class 1255 OID 93130421)
-- Name: ca_player_stats_club_comparison(uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_stats_club_comparison(p_user uuid, p_days integer DEFAULT NULL::integer, p_asset text DEFAULT 'chips'::text, p_tz text DEFAULT 'UTC'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET statement_timeout TO '20s'
    SET work_mem TO '64MB'
    SET enable_indexscan TO 'off'
    SET search_path TO 'public'
    AS $$
DECLARE
  v_days integer := CASE WHEN p_days IS NULL THEN NULL ELSE least(greatest(p_days,1),3650) END;
  v_tz text := CASE WHEN EXISTS (SELECT 1 FROM pg_timezone_names WHERE name=p_tz) THEN p_tz ELSE 'UTC' END;
  v_from timestamptz := CASE WHEN v_days IS NULL THEN NULL ELSE
    (((now() AT TIME ZONE v_tz)::date-(v_days-1))::timestamp AT TIME ZONE v_tz) END;
  v_to timestamptz := CASE WHEN v_days IS NULL THEN NULL ELSE
    ((((now() AT TIME ZONE v_tz)::date+1)::timestamp) AT TIME ZONE v_tz) END;
BEGIN
  -- funded_stats_scope: historical funding, original caller gates.
  PERFORM public.ca_assert_self(p_user);
  IF p_asset IS NULL OR p_asset NOT IN ('chips','diamonds') THEN
    RAISE EXCEPTION 'unknown stats asset: %', p_asset USING ERRCODE='22023';
  END IF;
  RETURN (WITH memberships AS MATERIALIZED (
    SELECT DISTINCT c.id club_id, c.name club_name
    FROM public.club_members m JOIN public.clubs c ON c.id=m.club_id
    WHERE m.user_id=p_user AND m.status IN ('active','approved')
      AND coalesce(c.lifecycle_status,'active')<>'retired'
      AND coalesce(c.asset,'chips')=p_asset
  ), cash AS (
    SELECT f.funded_club AS club_id, count(*)::integer total_hands,
      count(*) FILTER (WHERE f.tournament_id IS NULL)::integer cash_hands,
      coalesce(sum(f.net) FILTER (WHERE f.tournament_id IS NULL),0) profit,
      coalesce(sum(f.net_bb) FILTER (WHERE f.tournament_id IS NULL),0) net_bb,
      count(*) FILTER (WHERE f.vpip)::integer vpip_hands,
      count(*) FILTER (WHERE f.pfr)::integer pfr_hands,
      coalesce(sum(f.rake_paid) FILTER (WHERE f.tournament_id IS NULL),0) rake_paid,
      max(f.played_at) last_played_at, min(f.played_at) first_played_at
    FROM (
 WITH receipts AS MATERIALIZED (
  SELECT DISTINCT ON(table_id,account_entity_id,seat_joined_at)
   table_id,account_entity_id,seat_joined_at,funding_club_id
  FROM public.cash_participant_funding_receipts
  WHERE account_entity_id=p_user AND operation_kind='buyin'
  ORDER BY table_id,account_entity_id,seat_joined_at,recorded_at DESC,id DESC
 ), funding AS MATERIALIZED (
  SELECT *,lead(seat_joined_at) OVER(PARTITION BY table_id,account_entity_id ORDER BY seat_joined_at) until_at
  FROM receipts
 )
 SELECT fact.*,coalesce(x.funding_club_id,tp.club_id,ra.club_id,fact.club_id) funded_club
 FROM public.ca_hand_facts fact
 LEFT JOIN funding x ON fact.tournament_id IS NULL AND x.table_id=fact.table_id
  AND fact.played_at>=x.seat_joined_at AND (x.until_at IS NULL OR fact.played_at<x.until_at)
 LEFT JOIN public.tournament_players tp ON tp.tournament_id=fact.tournament_id AND tp.user_id=fact.user_id
 LEFT JOIN public.rake_attributions ra ON x.funding_club_id IS NULL AND tp.club_id IS NULL
  AND ra.hand_id=fact.hand_id AND ra.player_id=fact.user_id
 WHERE fact.user_id=p_user
 ) f JOIN memberships m ON m.club_id=f.funded_club
    WHERE f.user_id=p_user
      AND (v_from IS NULL OR f.played_at>=v_from)
      AND (v_to IS NULL OR f.played_at<v_to)
    GROUP BY f.funded_club
  ), tourn AS (
    SELECT coalesce(tp.club_id,t.club_id) AS club_id, count(*)::integer tournament_entries,
      count(*) FILTER (WHERE coalesce(tp.prize,0)>0)::integer tournament_cashes,
      count(*) FILTER (WHERE tp.position=1 OR tp.status='winner')::integer tournament_wins,
      coalesce(sum(coalesce(tp.prize,0)+coalesce(tp.bounty_winnings,0)),0) tournament_winnings,
      max(t.ended_at) tournament_last_played_at
    FROM public.tournament_players tp JOIN public.tournaments t ON t.id=tp.tournament_id
    JOIN memberships m ON m.club_id=coalesce(tp.club_id,t.club_id)
    WHERE tp.user_id=p_user
      AND upper(coalesce(t.status,''))='COMPLETED'
      AND t.ended_at IS NOT NULL
      AND (v_from IS NULL OR t.ended_at>=v_from)
      AND (v_to IS NULL OR t.ended_at<v_to)
    GROUP BY coalesce(tp.club_id,t.club_id)
  ), rows AS (
    SELECT m.club_id,m.club_name,coalesce(c.total_hands,0) hands,
      coalesce(c.cash_hands,0) cash_hands,
      round(coalesce(c.profit,0),2) profit,
      coalesce(round(c.net_bb/nullif(c.cash_hands,0)*100,2),0) bb_per_100,
      coalesce(round(c.vpip_hands::numeric/nullif(c.total_hands,0),4),0) vpip,
      coalesce(round(c.pfr_hands::numeric/nullif(c.total_hands,0),4),0) pfr,
      NULL::numeric hours,
      round(coalesce(c.rake_paid,0),2) rake,
      coalesce(t.tournament_entries,0) tournament_entries,
      coalesce(t.tournament_cashes,0) tournament_cashes,
      coalesce(t.tournament_wins,0) tournament_wins,
      round(coalesce(t.tournament_winnings,0),2) tournament_winnings,
      greatest(c.last_played_at,t.tournament_last_played_at) last_played_at,
      c.first_played_at,
      coalesce(c.vpip_hands,0) vpip_numerator,
      coalesce(c.pfr_hands,0) pfr_numerator,
      coalesce(c.total_hands,0) dealt_denominator,
      coalesce(c.net_bb,0) net_bb_numerator
    FROM memberships m LEFT JOIN cash c USING(club_id) LEFT JOIN tourn t USING(club_id)
  ), totals AS (
    SELECT coalesce(sum(hands),0) hands,coalesce(sum(cash_hands),0) cash_hands,
      round(coalesce(sum(profit),0),2) profit,
      round(coalesce(sum(rake),0),2) rake,coalesce(sum(tournament_entries),0) tournament_entries,
      coalesce(sum(tournament_cashes),0) tournament_cashes,
      coalesce(sum(tournament_wins),0) tournament_wins,
      round(coalesce(sum(tournament_winnings),0),2) tournament_winnings,
      coalesce(sum(vpip_numerator),0) vpip_numerator,
      coalesce(sum(pfr_numerator),0) pfr_numerator,
      coalesce(sum(dealt_denominator),0) dealt_denominator,
      coalesce(sum(net_bb_numerator),0) net_bb_numerator,max(last_played_at) last_played_at
    FROM rows
  ) SELECT jsonb_build_object('contract_version',2,
    'scope',jsonb_build_object('target_user_id',p_user,'asset',p_asset,'range_days',v_days,
      'range_tz',v_tz,'visibility','owner'),
    'quality',jsonb_build_object('cash_money_source','exact_settlement','cash_money_exact',true,
      'historical_club_breakdown_available',false,'club_breakdown_source','ca_hand_facts',
      'hours_available',false,'three_bet_percent_available',false,
      'tournament_money_exact',false,
      'all_clubs_contract_conservation_comparable',false,
      'all_clubs_contract_conservation_reason','existing All Clubs includes pre-fact rollup history without club identity'),
    'rows',coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY club_name,club_id) FROM rows r),'[]'::jsonb),
    'totals',(SELECT to_jsonb(t)||jsonb_build_object(
      'bb_per_100',coalesce(round(net_bb_numerator/nullif(cash_hands,0)*100,2),0),
      'vpip',coalesce(round(vpip_numerator::numeric/nullif(dealt_denominator,0),4),0),
      'pfr',coalesce(round(pfr_numerator::numeric/nullif(dealt_denominator,0),4),0),
      'hours',NULL) FROM totals t),
    'generated_at',now()));
END;$$;


ALTER FUNCTION public.ca_player_stats_club_comparison(p_user uuid, p_days integer, p_asset text, p_tz text) OWNER TO postgres;

--
-- TOC entry 4416 (class 1255 OID 95131614)
-- Name: ca_player_stats_financial_report(uuid, uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_stats_financial_report(p_user uuid, p_club_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT NULL::integer, p_tz text DEFAULT 'UTC'::text, p_asset text DEFAULT 'chips'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_days integer; v_tz text; v_from timestamptz; v_to timestamptz;
BEGIN
  PERFORM public.ca_assert_self(p_user);
  IF p_asset NOT IN ('chips','diamonds') THEN RAISE EXCEPTION 'unknown stats asset' USING ERRCODE='22023'; END IF;
  IF p_club_id IS NOT NULL THEN PERFORM public.ca_assert_player_stats_club(p_user,p_club_id,p_asset); END IF;
  SELECT b.range_days,b.range_tz,b.from_at,b.to_at INTO v_days,v_tz,v_from,v_to
    FROM public.ca_stats_calendar_bounds(p_days,p_tz) b;
  RETURN (WITH eligible AS MATERIALIZED (
    SELECT DISTINCT c.id FROM public.club_members m JOIN public.clubs c ON c.id=m.club_id
    WHERE m.user_id=p_user AND m.status IN ('active','approved')
      AND coalesce(c.lifecycle_status,'active')<>'retired' AND coalesce(c.asset,'chips')=p_asset
      AND (p_club_id IS NULL OR c.id=p_club_id)
  ), tx AS MATERIALIZED (
    SELECT w.id,w.created_at,w.related_entity_id tournament_id,t.club_id,w.type,w.category,
      round(w.amount,2) amount,w.balance_after,w.description
    FROM public.wallet_transactions w JOIN public.tournaments t ON t.id=w.related_entity_id
    JOIN eligible e ON e.id=t.club_id
    WHERE w.user_id=p_user AND p_asset='chips'
      AND lower(w.category) IN ('tournament_buyin','rebuy','addon','refund','tournament_refund',
        'tournament_prize','tournament_winnings','tournament_cashout','bounty','ticket_issue',
        'ticket_redeem','correction','reversal','prize_reversal')
      AND (v_from IS NULL OR w.created_at>=v_from) AND (v_to IS NULL OR w.created_at<v_to)
  ), categories AS (
    SELECT lower(category) category,lower(type) direction,count(*)::integer entries,round(sum(amount),2) amount
    FROM tx GROUP BY 1,2
  ), tournament_totals AS (
    SELECT count(*)::integer journal_rows,
      round(coalesce(sum(amount) FILTER(WHERE lower(type)='debit'),0),2) debits,
      round(coalesce(sum(amount) FILTER(WHERE lower(type)='credit'),0),2) credits,
      round(coalesce(sum(CASE WHEN lower(type)='credit' THEN amount
        WHEN lower(type)='debit' THEN -amount ELSE 0 END),0),2) net
    FROM tx
  ), periods AS MATERIALIZED (
    SELECT r.id,r.club_id,r.period_start,r.period_end,r.rake_generated,r.rakeback_rate,
      coalesce(r.rakeback_amount,r.rakeback_earned,0) amount,r.status,r.paid_at,
      r.deferred_reason,r.deferred_at,r.defer_count
    FROM public.rakeback_periods r JOIN eligible e ON e.id=r.club_id
    WHERE r.user_id=p_user AND p_asset='chips'
      AND (v_from IS NULL OR r.period_end>=v_from) AND (v_to IS NULL OR r.period_start<v_to)
  ), payouts AS MATERIALIZED (
    SELECT p.id,p.rakeback_period_id,p.club_id,p.payout_amount,p.currency,p.status,p.paid_at,
      p.wallet_transaction_id,p.failure_reason,p.created_at,
      coalesce((SELECT jsonb_agg(jsonb_build_object('wallet_transaction_id',t.wallet_transaction_id,'amount',t.amount)ORDER BY t.payer_kind,t.payer_entity_id)
       FROM public.accounting_rakeback_payer_transfers t WHERE t.payout_id=p.id AND t.period_id=p.rakeback_period_id),'[]'::jsonb) AS wallet_transactions
    FROM public.rakeback_period_payouts p JOIN eligible e ON e.id=p.club_id
    WHERE p.user_id=p_user AND p_asset='chips'
      AND (v_from IS NULL OR coalesce(p.paid_at,p.created_at)>=v_from)
      AND (v_to IS NULL OR coalesce(p.paid_at,p.created_at)<v_to)
  ) SELECT jsonb_build_object('contract_version',2,'scope',jsonb_build_object(
      'target_user_id',p_user,'club_id',p_club_id,'asset',p_asset,'range_days',v_days,
      'range_tz',v_tz,'visibility','owner'),'generated_at',now(),
    'availability',jsonb_build_object(
      'tournament_wallet',p_asset='chips','rakeback',p_asset='chips',
      'bankroll_ledger',false,'bankroll_reason','no_club_scoped_authoritative_player_balance_series',
      'cash_sessions',false,'cash_sessions_reason','session_identity_has_no_final_stack_or_hand_foreign_key'),
    'tournament_wallet',jsonb_build_object('source','wallet_transactions',
      'totals',(SELECT to_jsonb(tournament_totals) FROM tournament_totals),
      'categories',coalesce((SELECT jsonb_agg(to_jsonb(c) ORDER BY category,direction) FROM categories c),'[]'::jsonb),
      'entries',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY created_at DESC,id DESC) FROM
        (SELECT * FROM tx ORDER BY created_at DESC,id DESC LIMIT 250) x),'[]'::jsonb),
      'capped',(SELECT count(*)>250 FROM tx)),
    'rakeback',jsonb_build_object('source','rakeback_periods+rakeback_period_payouts',
      'pending_amount',coalesce((SELECT round(sum(amount),2) FROM periods WHERE status='pending'),0),
      'paid_amount',coalesce((SELECT round(sum(payout_amount),2) FROM payouts WHERE status='paid'),0),
      'periods',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY period_end DESC,id DESC) FROM periods p),'[]'::jsonb),
      'payout_receipts',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY coalesce(paid_at,created_at) DESC,id DESC) FROM payouts p),'[]'::jsonb)),
    'bankroll',jsonb_build_object('available',false,'series','[]'::jsonb),
    'cash_sessions',jsonb_build_object('available',false,'sessions','[]'::jsonb)));
END;$$;


ALTER FUNCTION public.ca_player_stats_financial_report(p_user uuid, p_club_id uuid, p_days integer, p_tz text, p_asset text) OWNER TO postgres;

--
-- TOC entry 44654 (class 0 OID 0)
-- Dependencies: 4416
-- Name: FUNCTION ca_player_stats_financial_report(p_user uuid, p_club_id uuid, p_days integer, p_tz text, p_asset text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_player_stats_financial_report(p_user uuid, p_club_id uuid, p_days integer, p_tz text, p_asset text) IS 'Owner-only financial report. Tournament wallet entries and rakeback receipts are authoritative. Club-scoped bankroll history and cashier sessions remain explicitly unavailable because no durable source carries the required identity and closing balance.';


--
-- TOC entry 5104 (class 1255 OID 72767702)
-- Name: ca_player_stats_full(uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_stats_full(p_user uuid, p_days integer DEFAULT NULL::integer, p_tz text DEFAULT 'UTC'::text, p_asset text DEFAULT 'chips'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c_cap constant int := 750;
  v_since timestamptz := CASE WHEN p_days IS NULL OR p_days <= 0
                              THEN NULL ELSE now() - make_interval(days => p_days) END;
  v_life_hands bigint := 0;
  v_life_first timestamptz;
  v_life_last  timestamptz;
  -- The player's zone for DAY buckets (phase 3). The analysis window itself
  -- is rolling (now() minus p_days), so it never needed a zone; the daily
  -- series and the "which days" wording did, and were UTC days for everyone.
  v_tz text := 'UTC';
BEGIN
  IF p_asset IS NULL OR p_asset NOT IN ('chips', 'diamonds') THEN
    RAISE EXCEPTION 'unknown stats asset: %', p_asset USING ERRCODE = '22023';
  END IF;
  -- An unknown zone name falls back to UTC rather than failing the page.
  BEGIN
    IF p_tz IS NOT NULL AND length(p_tz) BETWEEN 1 AND 64 THEN
      PERFORM now() AT TIME ZONE p_tz;
      v_tz := p_tz;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_tz := 'UTC';
  END;
  SELECT coalesce(sum(hands),0)::bigint,min(first_hand_at),max(last_hand_at)
  INTO v_life_hands,v_life_first,v_life_last FROM (
   SELECT count(*)::bigint hands,min(created_at) first_hand_at,max(created_at) last_hand_at
   FROM public.ca_hand_player_idx WHERE user_id=p_user AND asset=p_asset
   UNION ALL
   SELECT hands,first_hand_at,last_hand_at FROM smarter_private.hand_index_retention_totals
   WHERE user_id=p_user AND asset=p_asset
  ) recorded_lifetime;

RETURN (
WITH scored AS MATERIALIZED (
  -- The most recent c_cap rows for this player, whoever wrote them (the
  -- hand_history trigger, live, or the forward roll behind it). Where the
  -- engine wrote an exact settlement row (ca_hand_facts) the money columns
  -- come from it; the reconstruction is the fallback, and `exact` says which.
  SELECT s.created_at, s.is_cash, s.tournament_id, s.game_variant, s.big_blind,
         s.seat_position AS position,
         coalesce(x.returned, s.won_amt) AS won_amt,
         s.is_winner,
         coalesce(x.invested, s.invested_actions + s.my_blind) AS invested,
         s.aggro_cnt, s.call_cnt, s.vpip, s.pfr, s.three_bet,
         s.three_bet_opp, s.faced_three_bet, s.folded_to_three_bet, s.cbet_opp,
         s.cbet_made, s.showdown, s.hand_secs,
         coalesce(x.net, s.profit) AS profit,
         (x.hand_id IS NOT NULL) AS exact
  FROM ca_hand_player_stat s
  LEFT JOIN ca_hand_facts x ON x.hand_id = s.hand_id AND x.user_id = s.user_id
  WHERE s.user_id = p_user
    AND s.asset = p_asset
    AND (v_since IS NULL OR s.created_at >= v_since)
  ORDER BY s.created_at DESC
  LIMIT c_cap
),
totals AS (
  SELECT
    count(*)::int AS hands,
    count(*) FILTER (WHERE is_cash)::int AS cash_hands,
    count(*) FILTER (WHERE is_cash AND exact)::int AS exact_cash_hands,
    count(*) FILTER (WHERE NOT is_cash)::int AS tourney_hands,
    count(DISTINCT tournament_id) FILTER (WHERE NOT is_cash)::int AS tournaments_with_hands,
    count(*) FILTER (WHERE is_winner)::int AS hands_won,
    count(*) FILTER (WHERE vpip)::int AS vpip_hands,
    count(*) FILTER (WHERE pfr)::int AS pfr_hands,
    count(*) FILTER (WHERE three_bet)::int AS three_bet_hands,
    count(*) FILTER (WHERE three_bet_opp)::int AS three_bet_opps,
    count(*) FILTER (WHERE faced_three_bet)::int AS faced_three_bet_hands,
    count(*) FILTER (WHERE folded_to_three_bet)::int AS folded_to_three_bet_hands,
    count(*) FILTER (WHERE cbet_opp)::int AS cbet_opps,
    count(*) FILTER (WHERE cbet_made)::int AS cbet_made_hands,
    coalesce(sum(aggro_cnt), 0)::int AS aggro_actions,
    coalesce(sum(call_cnt), 0)::int AS call_actions,
    count(*) FILTER (WHERE showdown)::int AS showdowns,
    count(*) FILTER (WHERE showdown AND is_winner)::int AS showdowns_won,
    coalesce(sum(profit) FILTER (WHERE is_cash), 0) AS cash_profit,
    coalesce(sum(won_amt) FILTER (WHERE is_cash), 0) AS cash_won,
    coalesce(sum(invested) FILTER (WHERE is_cash), 0) AS cash_invested,
    coalesce(max(won_amt) FILTER (WHERE is_cash), 0) AS biggest_pot_won,
    coalesce(min(profit) FILTER (WHERE is_cash), 0) AS biggest_hand_loss,
    coalesce(sum(profit / NULLIF(big_blind, 0)) FILTER (WHERE is_cash), 0) AS cash_bb_profit,
    coalesce(sum(hand_secs), 0) AS total_secs,
    min(created_at) AS first_hand_at,
    max(created_at) AS last_hand_at
  FROM scored
),
daily AS (
  SELECT date(created_at AT TIME ZONE v_tz) AS d, count(*)::int AS hands,
         round(coalesce(sum(profit), 0), 2) AS profit
  FROM scored WHERE is_cash AND created_at >= now() - interval '90 days'
  GROUP BY 1 ORDER BY 1
),
sess_marked AS (
  SELECT *, CASE WHEN created_at - lag(created_at) OVER (ORDER BY created_at) > interval '45 minutes'
                 OR lag(created_at) OVER (ORDER BY created_at) IS NULL
            THEN 1 ELSE 0 END AS new_sess
  FROM scored WHERE is_cash
),
sess_grouped AS (
  SELECT *, sum(new_sess) OVER (ORDER BY created_at) AS sess_no FROM sess_marked
),
sessions_agg AS (
  SELECT sess_no, min(created_at) AS started, max(created_at) AS ended,
         count(*)::int AS hands,
         round(coalesce(sum(profit), 0), 2) AS profit,
         round(coalesce(sum(invested), 0), 2) AS invested
  FROM sess_grouped GROUP BY sess_no ORDER BY sess_no DESC LIMIT 50
),
positions AS (
  SELECT position, count(*)::int AS hands_played,
         count(*) FILTER (WHERE vpip)::int AS vpip_count,
         count(*) FILTER (WHERE pfr)::int AS pfr_count,
         count(*) FILTER (WHERE three_bet)::int AS three_bet_count,
         count(*) FILTER (WHERE three_bet_opp)::int AS three_bet_opps,
         count(*) FILTER (WHERE is_winner)::int AS hands_won,
         round(coalesce(sum(profit) FILTER (WHERE is_cash), 0), 2) AS total_profit,
         CASE WHEN count(*) FILTER (WHERE is_cash) > 0
              THEN round(coalesce(sum(profit / NULLIF(big_blind, 0)) FILTER (WHERE is_cash), 0)
                   / count(*) FILTER (WHERE is_cash) * 100, 2)
              ELSE 0 END AS bb100
  FROM scored WHERE position <> 'UNK' GROUP BY position
),
stakes AS (
  SELECT big_blind, count(*)::int AS hands,
         count(*) FILTER (WHERE is_winner)::int AS hands_won,
         round(coalesce(sum(profit), 0), 2) AS profit,
         CASE WHEN count(*) > 0
              THEN round(coalesce(sum(profit / NULLIF(big_blind, 0)), 0) / count(*) * 100, 2)
              ELSE 0 END AS bb100
  FROM scored WHERE is_cash AND big_blind > 0
  GROUP BY big_blind ORDER BY big_blind DESC
),
variants AS (
  SELECT game_variant, count(*)::int AS hands,
         count(*) FILTER (WHERE is_winner)::int AS hands_won,
         round(coalesce(sum(profit) FILTER (WHERE is_cash), 0), 2) AS profit,
         CASE WHEN count(*) FILTER (WHERE is_cash) > 0
              THEN round(coalesce(sum(profit / NULLIF(big_blind, 0)) FILTER (WHERE is_cash), 0)
                   / count(*) FILTER (WHERE is_cash) * 100, 2)
              ELSE 0 END AS bb100
  FROM scored GROUP BY game_variant ORDER BY count(*) DESC
),
-- The tournament block honours the analysis window like everything else on
-- the page. It used to be lifetime under a "7 Days" label.
tourn_rows AS (
  SELECT tp.*, t.buy_in_amount, t.buy_in_fee, t.rebuy_cost, t.addon_cost,
         t.name, t.start_time, t.variant, t.is_mystery_bounty
  FROM tournament_players tp
  LEFT JOIN tournaments t ON t.id = tp.tournament_id
  WHERE tp.user_id = p_user
    AND coalesce(t.club_id IN (SELECT c.id FROM public.clubs c WHERE c.asset = 'diamonds'), false) = (p_asset = 'diamonds')
    AND (v_since IS NULL OR coalesce(t.start_time, tp.registered_at, now()) >= v_since)
),
tourn AS (
  SELECT count(*)::int AS entries,
         count(*) FILTER (WHERE coalesce(tp.prize, 0) > 0)::int AS cashes,
         count(*) FILTER (WHERE tp.position = 1 OR tp.status = 'winner')::int AS wins,
         min(tp.position) FILTER (WHERE tp.position IS NOT NULL) AS best_finish,
         coalesce(sum(coalesce(tp.buy_in_amount, 0) + coalesce(tp.buy_in_fee, 0)
           + coalesce(tp.rebuys, 0) * coalesce(tp.rebuy_cost, 0)
           + CASE WHEN tp.add_on THEN coalesce(tp.addon_cost, 0) ELSE 0 END), 0) AS total_buyins,
         coalesce(sum(coalesce(tp.prize, 0) + coalesce(tp.bounty_winnings, 0)), 0) AS total_winnings,
         coalesce(sum(coalesce(tp.prize, 0)), 0) AS total_prizes,
         coalesce(sum(coalesce(tp.bounty_winnings, 0)), 0) AS total_bounty_winnings,
         coalesce(sum(coalesce(tp.bounties_collected, 0)), 0)::int AS total_bounties
  FROM tourn_rows tp
),
tourn_recent AS (
  SELECT tp.tournament_id, tp.name, tp.start_time, tp.variant,
         coalesce(tp.is_mystery_bounty, false) AS is_mystery_bounty,
         tp.position AS finish_rank, tp.status,
         coalesce(tp.prize, 0) AS prize,
         coalesce(tp.bounty_winnings, 0) AS bounty_winnings,
         coalesce(tp.bounties_collected, 0)::int AS bounties,
         coalesce(tp.prize, 0) + coalesce(tp.bounty_winnings, 0) AS total_won,
         coalesce(tp.buy_in_amount, 0) + coalesce(tp.buy_in_fee, 0)
           + coalesce(tp.rebuys, 0) * coalesce(tp.rebuy_cost, 0)
           + CASE WHEN tp.add_on THEN coalesce(tp.addon_cost, 0) ELSE 0 END AS buyin
  FROM tourn_rows tp
  WHERE tp.tournament_id IS NOT NULL
  ORDER BY tp.start_time DESC NULLS LAST LIMIT 25
)
SELECT jsonb_build_object(
  'generated_at', now(),
  'window_days', p_days,
  'window_tz', v_tz,
  'lifetime', jsonb_build_object(
    'hands', v_life_hands,
    'first_hand_at', v_life_first,
    'last_hand_at', v_life_last,
    'indexed_complete', (SELECT backfill_complete FROM ca_hand_player_idx_state WHERE id),
    'source', 'active_index_and_retention_totals',
    'historical_complete', false,
    'retention_capture_started_at', (SELECT started_at FROM smarter_private.hand_index_retention_coverage WHERE singleton)
  ),
  'user_id', p_user,
  'asset', p_asset,
  'overall', (SELECT jsonb_build_object(
    'total_hands', hands,
    'cash_hands', cash_hands,
    'exact_cash_hands', exact_cash_hands,
    'tourney_hands', tourney_hands,
    'tournaments_with_hands', tournaments_with_hands,
    'hands_won', hands_won,
    'hands_lost', hands - hands_won,
    'vpip', CASE WHEN hands > 0 THEN round(vpip_hands::numeric / hands, 4) ELSE 0 END,
    'pfr', CASE WHEN hands > 0 THEN round(pfr_hands::numeric / hands, 4) ELSE 0 END,
    'three_bet_percent', CASE WHEN three_bet_opps > 0
        THEN round(three_bet_hands::numeric / three_bet_opps, 4) ELSE 0 END,
    'fold_to_three_bet', CASE WHEN faced_three_bet_hands > 0
        THEN round(folded_to_three_bet_hands::numeric / faced_three_bet_hands, 4) ELSE 0 END,
    'cbet_flop', CASE WHEN cbet_opps > 0
        THEN round(cbet_made_hands::numeric / cbet_opps, 4) ELSE 0 END,
    'aggression_factor', CASE WHEN call_actions > 0
        THEN round(aggro_actions::numeric / call_actions, 2) ELSE aggro_actions END,
    'showdowns_total', showdowns,
    'showdowns_won', showdowns_won,
    'wtsd', CASE WHEN hands > 0 THEN round(showdowns::numeric / hands, 4) ELSE 0 END,
    'total_profit', round(cash_profit, 2),
    'total_winnings', round(cash_won, 2),
    'total_invested', round(cash_invested, 2),
    'biggest_pot_won', round(biggest_pot_won, 2),
    'biggest_hand_loss', round(biggest_hand_loss, 2),
    'bb_per_100', CASE WHEN cash_hands > 0
        THEN round(cash_bb_profit / cash_hands * 100, 2) ELSE 0 END,
    'hours_played', round(total_secs / 3600.0, 2),
    'hand_cap', c_cap,
    'hands_capped', (hands >= c_cap),
    'first_hand_at', first_hand_at,
    'last_hand_at', last_hand_at
  ) FROM totals),
  'daily', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'date', d, 'hands', hands, 'profit', profit) ORDER BY d) FROM daily), '[]'::jsonb),
  'sessions', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'id', sess_no, 'date', started, 'ended', ended,
      'duration_minutes', GREATEST(1, round(EXTRACT(epoch FROM (ended - started)) / 60)::int),
      'hands_played', hands, 'buy_in', invested,
      'cash_out', round(invested + profit, 2),
      'profit_loss', profit) ORDER BY sess_no DESC) FROM sessions_agg), '[]'::jsonb),
  'positions', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'position', position, 'hands_played', hands_played, 'vpip_count', vpip_count,
      'pfr_count', pfr_count, 'three_bet_count', three_bet_count,
      'three_bet_opps', three_bet_opps,
      'hands_won', hands_won, 'total_profit', total_profit,
      'bb100', bb100)) FROM positions), '[]'::jsonb),
  'variants', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'variant', game_variant, 'hands', hands, 'hands_won', hands_won,
      'profit', profit, 'bb100', bb100)) FROM variants), '[]'::jsonb),
  'stakes', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'big_blind', big_blind, 'hands', hands, 'hands_won', hands_won,
      'profit', profit, 'bb100', bb100) ORDER BY big_blind DESC) FROM stakes), '[]'::jsonb),
  'tournaments', (SELECT jsonb_build_object(
      'entries', entries, 'cashes', cashes, 'wins', wins, 'best_finish', best_finish,
      'itm_percent', CASE WHEN entries > 0 THEN round(cashes::numeric / entries, 4) ELSE 0 END,
      'total_buyins', round(total_buyins, 2),
      'total_winnings', round(total_winnings, 2),
      'total_prizes', round(total_prizes, 2),
      'total_bounty_winnings', round(total_bounty_winnings, 2),
      'total_bounties', total_bounties,
      'net_profit', round(total_winnings - total_buyins, 2),
      'roi', CASE WHEN total_buyins > 0
          THEN round((total_winnings - total_buyins) / total_buyins, 4) ELSE 0 END
  ) FROM tourn),
  'recent_tournaments', coalesce((SELECT jsonb_agg(jsonb_build_object(
      'tournament_id', tournament_id,
      'name', name, 'start_time', start_time, 'variant', variant,
      'is_mystery_bounty', is_mystery_bounty,
      'finish_rank', finish_rank, 'status', status,
      'prize', prize,
      'bounty_winnings', bounty_winnings,
      'bounties', bounties,
      'total_won', total_won,
      'buyin', buyin) ORDER BY start_time DESC NULLS LAST) FROM tourn_recent), '[]'::jsonb)
)
);
END;
$$;


ALTER FUNCTION public.ca_player_stats_full(p_user uuid, p_days integer, p_tz text, p_asset text) OWNER TO postgres;

--
-- TOC entry 44656 (class 0 OID 0)
-- Dependencies: 5104
-- Name: FUNCTION ca_player_stats_full(p_user uuid, p_days integer, p_tz text, p_asset text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_player_stats_full(p_user uuid, p_days integer, p_tz text, p_asset text) IS 'The stats payload for one player in one asset (p_asset, chips or diamonds, default chips): the most recent 750 stat rows of that asset (exact settlement overlaid), lifetime index counts of that asset, daily series in p_tz (IANA; unknown names fall back to UTC), cash sessions (a new session starts after a 45-minute gap between the player''s cash hands; session profit is the sum of its hands'' settlements), positions, stakes, variants, and tournaments of that asset in the rolling window. Service role only; the browser reaches it through ca_player_stats_overview_v2.';


--
-- TOC entry 7069 (class 1255 OID 95132603)
-- Name: ca_player_stats_hand_evidence(uuid, uuid, text, text, text, numeric, timestamp with time zone, timestamp with time zone, text, boolean, boolean, boolean, boolean, text, boolean, text, uuid, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_stats_hand_evidence(p_user uuid, p_club_id uuid DEFAULT NULL::uuid, p_asset text DEFAULT 'chips'::text, p_variant text DEFAULT NULL::text, p_position text DEFAULT NULL::text, p_big_blind numeric DEFAULT NULL::numeric, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_outcome text DEFAULT NULL::text, p_showdown boolean DEFAULT NULL::boolean, p_all_in boolean DEFAULT NULL::boolean, p_big_pots boolean DEFAULT NULL::boolean, p_noted boolean DEFAULT NULL::boolean, p_hand_class text DEFAULT NULL::text, p_tournament boolean DEFAULT NULL::boolean, p_cash_metric text DEFAULT NULL::text, p_cash_session_id uuid DEFAULT NULL::uuid, p_cursor_played_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_hand_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_session public.cash_player_session%ROWTYPE;
  v_session_asset text;
  v_overlap integer;
  v_limit integer := least(greatest(coalesce(p_limit,25),1),100);
  v_cash_metric text := lower(nullif(btrim(p_cash_metric),''));
BEGIN
  -- funded_stats_scope: historical funding, original caller gates.
  PERFORM public.ca_assert_self(p_user);
  IF p_asset IS NULL OR p_asset NOT IN ('chips','diamonds') THEN
    RAISE EXCEPTION 'unknown stats asset: %',p_asset USING ERRCODE='22023';
  END IF;
  IF p_cash_session_id IS NULL THEN
    RETURN public.ca_player_stats_hand_evidence_base(
      p_user,p_club_id,p_asset,p_variant,p_position,p_big_blind,p_from,p_to,
      p_outcome,p_showdown,p_all_in,p_big_pots,p_noted,p_hand_class,p_tournament,
      v_cash_metric,p_cursor_played_at,p_cursor_hand_id,p_limit);
  END IF;
  IF (p_cursor_played_at IS NULL) <> (p_cursor_hand_id IS NULL) THEN
    RAISE EXCEPTION 'session evidence cursor requires played_at and hand_id together'
      USING ERRCODE='22023';
  END IF;
  IF v_cash_metric IS NOT NULL AND v_cash_metric NOT IN (
    'three_bet','four_bet','steal','squeeze','blind_defense','cbet_flop',
    'barrel_turn','barrel_river','check_raise','donk','probe'
  ) THEN
    RAISE EXCEPTION 'unknown cash evidence metric: %',p_cash_metric USING ERRCODE='22023';
  END IF;
  SELECT s.* INTO v_session
    FROM public.cash_player_session s
    JOIN public.clubs c ON c.id=s.club_id
    JOIN public.club_members m ON m.club_id=c.id AND m.user_id=p_user
   WHERE s.id=p_cash_session_id AND s.player_id=p_user
     AND m.status IN ('active','approved')
     AND coalesce(c.lifecycle_status,'active')<>'retired'
     AND coalesce(c.asset,'chips')=p_asset
     AND (p_club_id IS NULL OR s.club_id=p_club_id);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'cash session evidence refused' USING ERRCODE='42501';
  END IF;
  SELECT coalesce(c.asset,'chips') INTO v_session_asset
    FROM public.clubs c WHERE c.id=v_session.club_id;
  SELECT count(*)::integer INTO v_overlap
    FROM public.cash_player_session o
   WHERE o.player_id=p_user AND o.id<>v_session.id
     AND o.club_id=v_session.club_id
     AND ((v_session.cluster_id IS NOT NULL AND o.cluster_id=v_session.cluster_id)
          OR (v_session.cluster_id IS NULL AND o.cluster_id IS NULL
              AND o.table_id=v_session.table_id))
     AND tstzrange(o.opened_at,coalesce(o.closed_at,'infinity'),'[)') &&
         tstzrange(v_session.opened_at,coalesce(v_session.closed_at,'infinity'),'[)');
  IF v_overlap>0 THEN
    RETURN jsonb_build_object('contract_version',3,'hands','[]'::jsonb,'has_more',false,
      'next_cursor',NULL,'evidence_status','overlap_unavailable',
      'scope',jsonb_build_object('target_user_id',p_user,'cash_session_id',v_session.id,
        'club_id',v_session.club_id,'asset',v_session_asset,'visibility','owner'),'generated_at',now());
  END IF;

  RETURN (WITH filtered AS MATERIALIZED (
    SELECT f.hand_id,f.played_at,f.funded_club AS club_id,f.table_id,f.net,f.net_bb,f.game_variant,
      v_cash_metric cash_metric,
      CASE v_cash_metric
        WHEN 'three_bet' THEN f.three_bet WHEN 'four_bet' THEN f.four_bet
        WHEN 'steal' THEN f.stole WHEN 'squeeze' THEN f.squeezed
        WHEN 'blind_defense' THEN f.defended_blind WHEN 'cbet_flop' THEN f.cbet_flop
        WHEN 'barrel_turn' THEN f.barreled_turn WHEN 'barrel_river' THEN f.barreled_river
        WHEN 'check_raise' THEN f.check_raised WHEN 'donk' THEN f.donk_bet
        WHEN 'probe' THEN f.probe_bet ELSE NULL END cash_metric_action
      FROM (
 WITH receipts AS MATERIALIZED (
  SELECT DISTINCT ON(table_id,account_entity_id,seat_joined_at)
   table_id,account_entity_id,seat_joined_at,funding_club_id
  FROM public.cash_participant_funding_receipts
  WHERE account_entity_id=p_user AND operation_kind='buyin'
  ORDER BY table_id,account_entity_id,seat_joined_at,recorded_at DESC,id DESC
 ), funding AS MATERIALIZED (
  SELECT *,lead(seat_joined_at) OVER(PARTITION BY table_id,account_entity_id ORDER BY seat_joined_at) until_at
  FROM receipts
 )
 SELECT fact.*,coalesce(x.funding_club_id,tp.club_id,ra.club_id,fact.club_id) funded_club
 FROM public.ca_hand_facts fact
 LEFT JOIN funding x ON fact.tournament_id IS NULL AND x.table_id=fact.table_id
  AND fact.played_at>=x.seat_joined_at AND (x.until_at IS NULL OR fact.played_at<x.until_at)
 LEFT JOIN public.tournament_players tp ON tp.tournament_id=fact.tournament_id AND tp.user_id=fact.user_id
 LEFT JOIN public.rake_attributions ra ON x.funding_club_id IS NULL AND tp.club_id IS NULL
  AND ra.hand_id=fact.hand_id AND ra.player_id=fact.user_id
 WHERE fact.user_id=p_user
 ) f LEFT JOIN public.tables t ON t.id=f.table_id
     WHERE f.user_id=p_user AND f.funded_club=v_session.club_id AND f.tournament_id IS NULL
       AND f.played_at>=v_session.opened_at
       AND f.played_at<coalesce(v_session.closed_at,'infinity')
       AND ((v_session.cluster_id IS NOT NULL AND t.cluster_id=v_session.cluster_id)
            OR (v_session.cluster_id IS NULL AND f.table_id=v_session.table_id))
       AND (v_cash_metric IS NULL OR CASE v_cash_metric
          WHEN 'three_bet' THEN f.three_bet_opportunity
          WHEN 'four_bet' THEN f.four_bet_opportunity
          WHEN 'steal' THEN f.steal_opportunity
          WHEN 'squeeze' THEN f.squeeze_opportunity
          WHEN 'blind_defense' THEN f.blind_defense_opportunity
          WHEN 'cbet_flop' THEN f.cbet_flop_opportunity
          WHEN 'barrel_turn' THEN f.barrel_turn_opportunity
          WHEN 'barrel_river' THEN f.barrel_river_opportunity
          WHEN 'check_raise' THEN f.check_raise_opportunity
          WHEN 'donk' THEN f.donk_opportunity
          WHEN 'probe' THEN f.probe_opportunity ELSE false END IS TRUE)
       AND (p_cursor_played_at IS NULL OR
         (f.played_at,f.hand_id)<(p_cursor_played_at,p_cursor_hand_id))
     ORDER BY f.played_at DESC,f.hand_id DESC LIMIT v_limit+1
  ), page AS (SELECT * FROM filtered ORDER BY played_at DESC,hand_id DESC LIMIT v_limit),
  last_row AS (SELECT played_at,hand_id FROM page ORDER BY played_at,hand_id LIMIT 1)
  SELECT jsonb_build_object('contract_version',3,
    'hands',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY played_at DESC,hand_id DESC) FROM page p),'[]'::jsonb),
    'has_more',(SELECT count(*)>v_limit FROM filtered),
    'next_cursor',CASE WHEN (SELECT count(*)>v_limit FROM filtered) THEN
      (SELECT jsonb_build_object('played_at',played_at,'hand_id',hand_id) FROM last_row) ELSE NULL END,
    'evidence_status','exact_session','scope',jsonb_build_object('target_user_id',p_user,
      'cash_session_id',v_session.id,'club_id',v_session.club_id,'asset',v_session_asset,
      'cash_metric',v_cash_metric,'visibility','owner'),'generated_at',now()));
END;
$$;


ALTER FUNCTION public.ca_player_stats_hand_evidence(p_user uuid, p_club_id uuid, p_asset text, p_variant text, p_position text, p_big_blind numeric, p_from timestamp with time zone, p_to timestamp with time zone, p_outcome text, p_showdown boolean, p_all_in boolean, p_big_pots boolean, p_noted boolean, p_hand_class text, p_tournament boolean, p_cash_metric text, p_cash_session_id uuid, p_cursor_played_at timestamp with time zone, p_cursor_hand_id uuid, p_limit integer) OWNER TO postgres;

--
-- TOC entry 3543 (class 1255 OID 95131565)
-- Name: ca_player_stats_hand_evidence_base(uuid, uuid, text, text, text, numeric, timestamp with time zone, timestamp with time zone, text, boolean, boolean, boolean, boolean, text, boolean, text, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_stats_hand_evidence_base(p_user uuid, p_club_id uuid DEFAULT NULL::uuid, p_asset text DEFAULT 'chips'::text, p_variant text DEFAULT NULL::text, p_position text DEFAULT NULL::text, p_big_blind numeric DEFAULT NULL::numeric, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_outcome text DEFAULT NULL::text, p_showdown boolean DEFAULT NULL::boolean, p_all_in boolean DEFAULT NULL::boolean, p_big_pots boolean DEFAULT NULL::boolean, p_noted boolean DEFAULT NULL::boolean, p_hand_class text DEFAULT NULL::text, p_tournament boolean DEFAULT NULL::boolean, p_cash_metric text DEFAULT NULL::text, p_cursor_played_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_hand_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit integer := least(greatest(coalesce(p_limit,25),1),100);
  v_variant text := lower(nullif(btrim(p_variant),''));
  v_position text := upper(nullif(btrim(p_position),''));
  v_outcome text := lower(nullif(btrim(p_outcome),''));
  v_cash_metric text := lower(nullif(btrim(p_cash_metric),''));
BEGIN
  -- funded_stats_scope: historical funding, original caller gates.
  IF auth.uid() IS NULL OR p_user IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'stats access refused' USING ERRCODE='42501';
  END IF;
  IF p_asset IS NULL OR p_asset NOT IN ('chips','diamonds') THEN
    RAISE EXCEPTION 'unknown stats asset: %',p_asset USING ERRCODE='22023';
  END IF;
  IF p_club_id IS NOT NULL THEN
    PERFORM public.ca_assert_player_stats_club(p_user,p_club_id,p_asset);
  END IF;
  IF v_outcome IS NOT NULL AND v_outcome NOT IN ('won','lost') THEN
    RAISE EXCEPTION 'unknown evidence outcome: %',p_outcome USING ERRCODE='22023';
  END IF;
  IF v_cash_metric IS NOT NULL AND v_cash_metric NOT IN (
    'three_bet','four_bet','steal','squeeze','blind_defense','cbet_flop',
    'barrel_turn','barrel_river','check_raise','donk','probe'
  ) THEN
    RAISE EXCEPTION 'unknown cash evidence metric: %',p_cash_metric USING ERRCODE='22023';
  END IF;
  IF (p_cursor_played_at IS NULL) <> (p_cursor_hand_id IS NULL) THEN
    RAISE EXCEPTION 'evidence cursor requires played_at and hand_id together' USING ERRCODE='22023';
  END IF;
  IF p_from IS NOT NULL AND p_to IS NOT NULL AND p_from >= p_to THEN
    RAISE EXCEPTION 'evidence range must be increasing' USING ERRCODE='22023';
  END IF;

  RETURN (WITH filtered AS MATERIALIZED (
    SELECT f.hand_id,f.played_at,f.funded_club AS club_id,f.table_id,f.tournament_id,
      f.game_variant,f.big_blind,f.position,f.players_dealt,f.hand_class,
      f.invested,f.returned,f.net,f.net_bb,f.rake_paid,f.vpip,f.pfr,
      f.three_bet,f.faced_three_bet,f.folded_to_three_bet,
      f.had_cbet_flop_opp,f.cbet_flop,f.saw_flop,f.went_to_showdown,
      f.won_at_showdown,f.aggressive_actions,f.passive_actions,f.was_all_in,
      f.ev_net_bb,f.hole_cards own_hole_cards,h.pot_size,
      v_cash_metric cash_metric,
      CASE v_cash_metric
        WHEN 'three_bet' THEN f.three_bet WHEN 'four_bet' THEN f.four_bet
        WHEN 'steal' THEN f.stole WHEN 'squeeze' THEN f.squeezed
        WHEN 'blind_defense' THEN f.defended_blind WHEN 'cbet_flop' THEN f.cbet_flop
        WHEN 'barrel_turn' THEN f.barreled_turn WHEN 'barrel_river' THEN f.barreled_river
        WHEN 'check_raise' THEN f.check_raised WHEN 'donk' THEN f.donk_bet
        WHEN 'probe' THEN f.probe_bet ELSE NULL END cash_metric_action
    FROM (
 WITH receipts AS MATERIALIZED (
  SELECT DISTINCT ON(table_id,account_entity_id,seat_joined_at)
   table_id,account_entity_id,seat_joined_at,funding_club_id
  FROM public.cash_participant_funding_receipts
  WHERE account_entity_id=p_user AND operation_kind='buyin'
  ORDER BY table_id,account_entity_id,seat_joined_at,recorded_at DESC,id DESC
 ), funding AS MATERIALIZED (
  SELECT *,lead(seat_joined_at) OVER(PARTITION BY table_id,account_entity_id ORDER BY seat_joined_at) until_at
  FROM receipts
 )
 SELECT fact.*,coalesce(x.funding_club_id,tp.club_id,ra.club_id,fact.club_id) funded_club
 FROM public.ca_hand_facts fact
 LEFT JOIN funding x ON fact.tournament_id IS NULL AND x.table_id=fact.table_id
  AND fact.played_at>=x.seat_joined_at AND (x.until_at IS NULL OR fact.played_at<x.until_at)
 LEFT JOIN public.tournament_players tp ON tp.tournament_id=fact.tournament_id AND tp.user_id=fact.user_id
 LEFT JOIN public.rake_attributions ra ON x.funding_club_id IS NULL AND tp.club_id IS NULL
  AND ra.hand_id=fact.hand_id AND ra.player_id=fact.user_id
 WHERE fact.user_id=p_user
 ) f
    JOIN public.clubs c ON c.id=f.funded_club
    LEFT JOIN public.hand_history h ON h.id=f.hand_id
    WHERE f.user_id=p_user
      AND coalesce(c.asset,'chips')=p_asset
      AND (p_club_id IS NULL OR f.funded_club=p_club_id)
      AND (v_variant IS NULL OR lower(f.game_variant)=CASE
        WHEN v_variant IN ('holdem','texasholdem') THEN 'nlh'
        WHEN v_variant IN ('omaha','plo') THEN 'plo4' ELSE v_variant END)
      AND (v_position IS NULL OR upper(f.position)=v_position)
      AND (p_big_blind IS NULL OR f.big_blind=p_big_blind)
      AND (p_from IS NULL OR f.played_at>=p_from)
      AND (p_to IS NULL OR f.played_at<p_to)
      AND (v_outcome IS NULL OR (v_outcome='won' AND f.net>0) OR (v_outcome='lost' AND f.net<0))
      AND (p_showdown IS NULL OR f.went_to_showdown=p_showdown)
      AND (p_all_in IS NULL OR f.was_all_in=p_all_in)
      AND (p_big_pots IS NULL OR NOT p_big_pots OR
        (h.pot_size IS NOT NULL AND f.big_blind>0 AND h.pot_size>=f.big_blind*100))
      AND (p_noted IS NULL OR NOT p_noted OR EXISTS (
        SELECT 1 FROM public.ca_hand_notes n WHERE n.user_id=p_user AND n.hand_id=f.hand_id))
      AND (p_hand_class IS NULL OR f.hand_class=p_hand_class)
      AND (p_tournament IS NULL OR (f.tournament_id IS NOT NULL)=p_tournament)
      AND (v_cash_metric IS NULL OR (
        f.tournament_id IS NULL AND CASE v_cash_metric
          WHEN 'three_bet' THEN f.three_bet_opportunity
          WHEN 'four_bet' THEN f.four_bet_opportunity
          WHEN 'steal' THEN f.steal_opportunity
          WHEN 'squeeze' THEN f.squeeze_opportunity
          WHEN 'blind_defense' THEN f.blind_defense_opportunity
          WHEN 'cbet_flop' THEN f.cbet_flop_opportunity
          WHEN 'barrel_turn' THEN f.barrel_turn_opportunity
          WHEN 'barrel_river' THEN f.barrel_river_opportunity
          WHEN 'check_raise' THEN f.check_raise_opportunity
          WHEN 'donk' THEN f.donk_opportunity
          WHEN 'probe' THEN f.probe_opportunity ELSE false END IS TRUE))
      AND (p_cursor_played_at IS NULL OR (f.played_at,f.hand_id)<(p_cursor_played_at,p_cursor_hand_id))
    ORDER BY f.played_at DESC,f.hand_id DESC
    LIMIT v_limit+1
  ), numbered AS (
    SELECT filtered.*,row_number() OVER (ORDER BY played_at DESC,hand_id DESC) rn FROM filtered
  ), page AS (
    SELECT * FROM numbered WHERE rn<=v_limit
  ), last_row AS (
    SELECT played_at,hand_id FROM page ORDER BY played_at,hand_id LIMIT 1
  ) SELECT jsonb_build_object(
    'contract_version',3,
    'hands',coalesce((SELECT jsonb_agg(to_jsonb(p)-'rn' ORDER BY played_at DESC,hand_id DESC) FROM page p),'[]'::jsonb),
    'has_more',(SELECT count(*)>v_limit FROM filtered),
    'next_cursor',CASE WHEN (SELECT count(*)>v_limit FROM filtered) THEN
      (SELECT jsonb_build_object('played_at',played_at,'hand_id',hand_id) FROM last_row) ELSE NULL END,
    'scope',jsonb_build_object('target_user_id',p_user,'club_id',p_club_id,'asset',p_asset,
      'from_inclusive',p_from,'to_exclusive',p_to,'cash_metric',v_cash_metric),
    'generated_at',now()));
END;$$;


ALTER FUNCTION public.ca_player_stats_hand_evidence_base(p_user uuid, p_club_id uuid, p_asset text, p_variant text, p_position text, p_big_blind numeric, p_from timestamp with time zone, p_to timestamp with time zone, p_outcome text, p_showdown boolean, p_all_in boolean, p_big_pots boolean, p_noted boolean, p_hand_class text, p_tournament boolean, p_cash_metric text, p_cursor_played_at timestamp with time zone, p_cursor_hand_id uuid, p_limit integer) OWNER TO postgres;

--
-- TOC entry 4621 (class 1255 OID 72767701)
-- Name: ca_player_stats_overview_v2(uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_stats_overview_v2(p_user uuid, p_days integer DEFAULT NULL::integer, p_tz text DEFAULT 'UTC'::text, p_asset text DEFAULT 'chips'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_days integer; v_tz text; v_from timestamptz; v_to timestamptz;
  v_base jsonb; v_overall jsonb; v_daily jsonb; v_tournaments jsonb; v_recent jsonb;
  v_analysis jsonb;
  v_total integer; v_cash integer; v_tourney integer; v_won integer;
  v_vpip integer; v_pfr integer; v_profit numeric; v_returned numeric;
  v_invested numeric; v_net_bb numeric; v_biggest numeric; v_loss numeric;
  v_first timestamptz; v_last timestamptz; v_exact_cash integer;
BEGIN
  PERFORM public.ca_assert_self(p_user);
  IF p_asset IS NULL OR p_asset NOT IN ('chips','diamonds') THEN
    RAISE EXCEPTION 'unknown stats asset: %',p_asset USING ERRCODE='22023';
  END IF;
  SELECT b.range_days,b.range_tz,b.from_at,b.to_at
    INTO v_days,v_tz,v_from,v_to FROM public.ca_stats_calendar_bounds(p_days,p_tz) b;
  v_base := public.ca_player_stats_full(p_user,v_days,v_tz,p_asset);

  WITH source_rows AS MATERIALIZED (
    SELECT s.hand_id,s.created_at,s.is_cash,s.tournament_id,s.is_winner,s.vpip,s.pfr,
      coalesce(f.net,s.profit) net,coalesce(f.returned,s.won_amt) returned,
      coalesce(f.invested,s.invested_actions+s.my_blind) invested,
      coalesce(f.net_bb,s.profit/nullif(s.big_blind,0)) net_bb,(f.hand_id IS NOT NULL) exact
    FROM public.ca_hand_player_stat s
    LEFT JOIN public.ca_hand_facts f ON f.hand_id=s.hand_id AND f.user_id=s.user_id
    WHERE s.user_id=p_user AND s.asset=p_asset
      AND (v_from IS NULL OR s.created_at>=v_from) AND (v_to IS NULL OR s.created_at<v_to)
    UNION ALL
    SELECT f.hand_id,f.played_at,(f.tournament_id IS NULL),f.tournament_id,(f.net>0),f.vpip,f.pfr,
      f.net,f.returned,f.invested,f.net_bb,true
    FROM public.ca_hand_facts f JOIN public.clubs c ON c.id=f.club_id
    WHERE f.user_id=p_user AND coalesce(c.asset,'chips')=p_asset
      AND (v_from IS NULL OR f.played_at>=v_from) AND (v_to IS NULL OR f.played_at<v_to)
      AND NOT EXISTS (SELECT 1 FROM public.ca_hand_player_stat s WHERE s.user_id=f.user_id AND s.hand_id=f.hand_id)
  )
  SELECT count(*)::integer,count(*) FILTER(WHERE is_cash)::integer,
    count(*) FILTER(WHERE NOT is_cash)::integer,count(*) FILTER(WHERE is_winner)::integer,
    count(*) FILTER(WHERE vpip)::integer,count(*) FILTER(WHERE pfr)::integer,
    coalesce(sum(net) FILTER(WHERE is_cash),0),coalesce(sum(returned) FILTER(WHERE is_cash),0),
    coalesce(sum(invested) FILTER(WHERE is_cash),0),coalesce(sum(net_bb) FILTER(WHERE is_cash),0),
    coalesce(max(returned) FILTER(WHERE is_cash),0),coalesce(min(net) FILTER(WHERE is_cash),0),
    min(created_at),max(created_at),count(*) FILTER(WHERE is_cash AND exact)::integer
  INTO v_total,v_cash,v_tourney,v_won,v_vpip,v_pfr,v_profit,v_returned,
    v_invested,v_net_bb,v_biggest,v_loss,v_first,v_last,v_exact_cash FROM source_rows;

  v_overall := coalesce(v_base->'overall','{}'::jsonb)||jsonb_build_object(
    'total_hands',v_total,'cash_hands',v_cash,'exact_cash_hands',v_exact_cash,
    'tourney_hands',v_tourney,'hands_won',v_won,'hands_lost',v_total-v_won,
    'vpip',coalesce(round(v_vpip::numeric/nullif(v_total,0),4),0),
    'pfr',coalesce(round(v_pfr::numeric/nullif(v_total,0),4),0),
    'total_profit',round(v_profit,2),'total_winnings',round(v_returned,2),
    'total_invested',round(v_invested,2),'biggest_pot_won',round(v_biggest,2),
    'biggest_hand_loss',round(v_loss,2),
    'bb_per_100',coalesce(round(v_net_bb/nullif(v_cash,0)*100,2),0),
    'hands_capped',false,'first_hand_at',v_first,'last_hand_at',v_last);
  SELECT coalesce(jsonb_agg(jsonb_build_object('date',d,'hands',hands,'profit',profit) ORDER BY d),'[]'::jsonb)
  INTO v_daily FROM (WITH source_rows AS (
    SELECT s.hand_id,s.created_at,coalesce(f.net,s.profit) net
    FROM public.ca_hand_player_stat s
    LEFT JOIN public.ca_hand_facts f ON f.hand_id=s.hand_id AND f.user_id=s.user_id
    WHERE s.user_id=p_user AND s.is_cash AND s.asset=p_asset
      AND (v_from IS NULL OR s.created_at>=v_from) AND (v_to IS NULL OR s.created_at<v_to)
    UNION ALL
    SELECT f.hand_id,f.played_at,f.net FROM public.ca_hand_facts f JOIN public.clubs c ON c.id=f.club_id
    WHERE f.user_id=p_user AND f.tournament_id IS NULL AND coalesce(c.asset,'chips')=p_asset
      AND (v_from IS NULL OR f.played_at>=v_from) AND (v_to IS NULL OR f.played_at<v_to)
      AND NOT EXISTS (SELECT 1 FROM public.ca_hand_player_stat s WHERE s.user_id=f.user_id AND s.hand_id=f.hand_id)
  ) SELECT date(created_at AT TIME ZONE v_tz) d,count(*)::integer hands,round(sum(net),2) profit
    FROM source_rows GROUP BY 1) x;
  WITH tr AS MATERIALIZED (
    SELECT tp.*,t.name,t.start_time,t.ended_at,t.variant,t.buy_in_amount,t.buy_in_fee,
      t.rebuy_cost,t.addon_cost,t.is_mystery_bounty
    FROM public.tournament_players tp JOIN public.tournaments t ON t.id=tp.tournament_id
    JOIN public.clubs c ON c.id=t.club_id
    WHERE tp.user_id=p_user AND coalesce(c.asset,'chips')=p_asset
      AND upper(coalesce(t.status,''))='COMPLETED' AND t.ended_at IS NOT NULL
      AND (v_from IS NULL OR t.ended_at>=v_from) AND (v_to IS NULL OR t.ended_at<v_to)
  ), totals AS (
    SELECT count(*)::integer entries,count(*) FILTER(WHERE coalesce(prize,0)>0)::integer cashes,
      count(*) FILTER(WHERE position=1 OR status='winner')::integer wins,
      min(position) FILTER(WHERE position IS NOT NULL) best_finish,
      coalesce(sum(coalesce(buy_in_amount,0)+coalesce(buy_in_fee,0)+coalesce(rebuys,0)*coalesce(rebuy_cost,0)+CASE WHEN add_on THEN coalesce(addon_cost,0) ELSE 0 END),0) buyins,
      coalesce(sum(coalesce(prize,0)),0) prizes,coalesce(sum(coalesce(bounty_winnings,0)),0) bounties
    FROM tr
  ) SELECT jsonb_build_object('entries',entries,'cashes',cashes,'wins',wins,'best_finish',best_finish,
      'itm_percent',coalesce(round(cashes::numeric/nullif(entries,0),4),0),'total_buyins',round(buyins,2),
      'total_winnings',round(prizes+bounties,2),'total_prizes',round(prizes,2),
      'total_bounty_winnings',round(bounties,2),'net_profit',round(prizes+bounties-buyins,2),
      'roi',coalesce(round((prizes+bounties-buyins)/nullif(buyins,0),4),0))
    INTO v_tournaments FROM totals;
  WITH tr AS (
    SELECT tp.tournament_id,t.name,t.start_time,t.ended_at,t.variant,
      coalesce(t.is_mystery_bounty,false) is_mystery_bounty,tp.position,tp.status,
      coalesce(tp.prize,0) prize,coalesce(tp.bounty_winnings,0) bounty_winnings,
      coalesce(tp.bounties_collected,0) bounties,
      coalesce(tp.prize,0)+coalesce(tp.bounty_winnings,0) total_won,
      coalesce(t.buy_in_amount,0)+coalesce(t.buy_in_fee,0)
        +coalesce(tp.rebuys,0)*coalesce(t.rebuy_cost,0)
        +CASE WHEN tp.add_on THEN coalesce(t.addon_cost,0) ELSE 0 END buyin
    FROM public.tournament_players tp JOIN public.tournaments t ON t.id=tp.tournament_id
    JOIN public.clubs c ON c.id=t.club_id
    WHERE tp.user_id=p_user AND coalesce(c.asset,'chips')=p_asset
      AND upper(coalesce(t.status,''))='COMPLETED' AND t.ended_at IS NOT NULL
      AND (v_from IS NULL OR t.ended_at>=v_from) AND (v_to IS NULL OR t.ended_at<v_to)
    ORDER BY t.ended_at DESC LIMIT 25
  ) SELECT coalesce(jsonb_agg(to_jsonb(tr) ORDER BY ended_at DESC),'[]'::jsonb) INTO v_recent FROM tr;
  -- The legacy full RPC uses a rolling clock cutoff. Rebuild every capped
  -- analysis section from the same validated calendar population as the
  -- headline so one range label never describes two different windows.
  WITH source_rows AS MATERIALIZED (
    SELECT s.hand_id,s.created_at,s.is_cash,s.game_variant,s.big_blind,s.seat_position position,
      s.is_winner,s.vpip,s.pfr,coalesce(f.net,s.profit) net,
      coalesce(f.invested,s.invested_actions+s.my_blind) invested,
      coalesce(f.net_bb,s.profit/nullif(s.big_blind,0)) net_bb
    FROM public.ca_hand_player_stat s LEFT JOIN public.ca_hand_facts f ON f.hand_id=s.hand_id AND f.user_id=s.user_id
    WHERE s.user_id=p_user AND s.asset=p_asset
      AND (v_from IS NULL OR s.created_at>=v_from) AND (v_to IS NULL OR s.created_at<v_to)
    UNION ALL
    SELECT f.hand_id,f.played_at,(f.tournament_id IS NULL),f.game_variant,f.big_blind,f.position,
      (f.net>0),f.vpip,f.pfr,f.net,f.invested,f.net_bb
    FROM public.ca_hand_facts f JOIN public.clubs c ON c.id=f.club_id
    WHERE f.user_id=p_user AND coalesce(c.asset,'chips')=p_asset
      AND (v_from IS NULL OR f.played_at>=v_from) AND (v_to IS NULL OR f.played_at<v_to)
      AND NOT EXISTS (SELECT 1 FROM public.ca_hand_player_stat s WHERE s.user_id=f.user_id AND s.hand_id=f.hand_id)
  ), scored AS MATERIALIZED (SELECT * FROM source_rows ORDER BY created_at DESC LIMIT 750),
  positions AS (SELECT position,count(*)::integer hands_played,count(*) FILTER(WHERE vpip)::integer vpip_count,
    count(*) FILTER(WHERE pfr)::integer pfr_count,count(*) FILTER(WHERE is_winner)::integer hands_won,
    round(coalesce(sum(net) FILTER(WHERE is_cash),0),2) total_profit,
    coalesce(round(sum(net_bb) FILTER(WHERE is_cash)/nullif(count(*) FILTER(WHERE is_cash),0)*100,2),0) bb100
    FROM scored GROUP BY position),
  variants AS (SELECT game_variant variant,count(*)::integer hands,count(*) FILTER(WHERE is_winner)::integer hands_won,
    round(coalesce(sum(net) FILTER(WHERE is_cash),0),2) profit,
    coalesce(round(sum(net_bb) FILTER(WHERE is_cash)/nullif(count(*) FILTER(WHERE is_cash),0)*100,2),0) bb100
    FROM scored GROUP BY game_variant),
  stakes AS (SELECT big_blind,count(*)::integer hands,count(*) FILTER(WHERE is_winner)::integer hands_won,
    round(sum(net),2) profit,coalesce(round(sum(net_bb)/nullif(count(*),0)*100,2),0) bb100
    FROM scored WHERE is_cash AND big_blind>0 GROUP BY big_blind),
  marked AS (SELECT *,CASE WHEN created_at-lag(created_at) OVER(ORDER BY created_at)>interval '45 minutes'
    OR lag(created_at) OVER(ORDER BY created_at) IS NULL THEN 1 ELSE 0 END new_session FROM scored WHERE is_cash),
  grouped AS (SELECT *,sum(new_session) OVER(ORDER BY created_at) session_no FROM marked),
  sessions AS (SELECT session_no,min(created_at) started,max(created_at) ended,count(*)::integer hands,
    round(sum(net),2) profit,round(sum(invested),2) invested FROM grouped GROUP BY session_no ORDER BY session_no DESC LIMIT 50)
  SELECT jsonb_build_object(
    'positions',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY position) FROM positions p),'[]'::jsonb),
    'variants',coalesce((SELECT jsonb_agg(to_jsonb(v) ORDER BY hands DESC) FROM variants v),'[]'::jsonb),
    'stakes',coalesce((SELECT jsonb_agg(to_jsonb(s) ORDER BY big_blind DESC) FROM stakes s),'[]'::jsonb),
    'sessions',coalesce((SELECT jsonb_agg(jsonb_build_object('id',session_no,'date',started,'ended',ended,
      'duration_minutes',greatest(1,round(extract(epoch FROM (ended-started))/60)::integer),
      'hands_played',hands,'buy_in',invested,'cash_out',round(invested+profit,2),'profit_loss',profit)
      ORDER BY session_no DESC) FROM sessions),'[]'::jsonb)) INTO v_analysis;
  RETURN v_base||jsonb_build_object('contract_version',2,'generated_at',now(),'window_days',v_days,
    'window_tz',v_tz,'scope',jsonb_build_object('target_user_id',p_user,'club_id',NULL,
      'asset',p_asset,'range_days',v_days,'range_tz',v_tz,'visibility','owner'),
    'overall',v_overall,'daily',v_daily,'positions',v_analysis->'positions',
    'variants',v_analysis->'variants','stakes',v_analysis->'stakes','sessions',v_analysis->'sessions',
    'tournaments',v_tournaments,'recent_tournaments',v_recent,
    'coverage',coalesce(v_base->'coverage','{}'::jsonb)||jsonb_build_object(
      'analysis_hand_cap',750,'analysis_sample_hands',least(v_total,750),
      'analysis_hands_capped',v_total>750),
    'quality',coalesce(v_base->'quality','{}'::jsonb)||jsonb_build_object(
      'cash_money_source',CASE WHEN v_cash=0 OR v_exact_cash=v_cash THEN 'exact_settlement'
        WHEN v_exact_cash=0 THEN 'reconstructed_actions' ELSE 'mixed' END,
      'cash_money_exact',(v_cash=0 OR v_exact_cash=v_cash),'exact_cash_hands',v_exact_cash,
      'advanced_facts_source','ca_hand_player_stat'));
END;$$;


ALTER FUNCTION public.ca_player_stats_overview_v2(p_user uuid, p_days integer, p_tz text, p_asset text) OWNER TO postgres;

--
-- TOC entry 44660 (class 0 OID 0)
-- Dependencies: 4621
-- Name: FUNCTION ca_player_stats_overview_v2(p_user uuid, p_days integer, p_tz text, p_asset text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_player_stats_overview_v2(p_user uuid, p_days integer, p_tz text, p_asset text) IS 'The browser''s door to the stats payload: asserts auth.uid() = p_user, wraps ca_player_stats_full(p_user, p_days, p_tz, p_asset) and stamps the contract (scope, including the asset, quality, coverage). p_tz is the player''s IANA zone for day buckets; p_asset is chips (the default) or diamonds, and a chip figure and a Diamond figure are never summed.';


--
-- TOC entry 5101 (class 1255 OID 93130375)
-- Name: ca_player_stats_overview_v2_by_club(uuid, integer, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_stats_overview_v2_by_club(p_user uuid, p_days integer DEFAULT NULL::integer, p_tz text DEFAULT 'UTC'::text, p_asset text DEFAULT 'chips'::text, p_club_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET statement_timeout TO '20s'
    SET work_mem TO '64MB'
    SET enable_indexscan TO 'off'
    SET search_path TO 'public'
    AS $$
DECLARE
  c_analysis_cap constant integer := 750;
  v_days integer := CASE WHEN p_days IS NULL THEN NULL ELSE least(greatest(p_days, 1), 3650) END;
  v_tz text := CASE WHEN EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = p_tz) THEN p_tz ELSE 'UTC' END;
  v_from timestamptz := CASE WHEN v_days IS NULL THEN NULL ELSE
    (((now() AT TIME ZONE v_tz)::date - (v_days - 1))::timestamp AT TIME ZONE v_tz) END;
  v_to timestamptz := CASE WHEN v_days IS NULL THEN NULL ELSE
    ((((now() AT TIME ZONE v_tz)::date + 1)::timestamp) AT TIME ZONE v_tz) END;
  v_first timestamptz;
  v_last timestamptz;
  v_lifetime integer;
BEGIN
  -- funded_stats_scope: historical funding, original caller gates.
  PERFORM public.ca_assert_player_stats_club(p_user, p_club_id, p_asset);



  RETURN (
    WITH funded_stats_scope AS MATERIALIZED (SELECT user_id,played_at,tournament_id,game_variant,big_blind,position,invested,returned,net,net_bb,vpip,pfr,three_bet,faced_three_bet,folded_to_three_bet,had_cbet_flop_opp,cbet_flop,saw_flop,went_to_showdown,won_at_showdown,aggressive_actions,passive_actions,funded_club FROM (
 WITH receipts AS MATERIALIZED (
  SELECT DISTINCT ON(table_id,account_entity_id,seat_joined_at)
   table_id,account_entity_id,seat_joined_at,funding_club_id
  FROM public.cash_participant_funding_receipts
  WHERE account_entity_id=p_user AND operation_kind='buyin'
  ORDER BY table_id,account_entity_id,seat_joined_at,recorded_at DESC,id DESC
 ), funding AS MATERIALIZED (
  SELECT *,lead(seat_joined_at) OVER(PARTITION BY table_id,account_entity_id ORDER BY seat_joined_at) until_at
  FROM receipts
 )
 SELECT fact.*,coalesce(x.funding_club_id,tp.club_id,ra.club_id,fact.club_id) funded_club
 FROM public.ca_hand_facts fact
 LEFT JOIN funding x ON fact.tournament_id IS NULL AND x.table_id=fact.table_id
  AND fact.played_at>=x.seat_joined_at AND (x.until_at IS NULL OR fact.played_at<x.until_at)
 LEFT JOIN public.tournament_players tp ON tp.tournament_id=fact.tournament_id AND tp.user_id=fact.user_id
 LEFT JOIN public.rake_attributions ra ON x.funding_club_id IS NULL AND tp.club_id IS NULL
  AND ra.hand_id=fact.hand_id AND ra.player_id=fact.user_id
 WHERE fact.user_id=p_user
 ) resolved), coverage_totals AS (SELECT count(*)::integer total,min(played_at) first_at,max(played_at) last_at FROM funded_stats_scope WHERE funded_club=p_club_id), filtered AS MATERIALIZED (
      SELECT f.*
      FROM funded_stats_scope f
      WHERE f.user_id = p_user
        AND f.funded_club = p_club_id
        AND (v_from IS NULL OR f.played_at >= v_from)
        AND (v_to IS NULL OR f.played_at < v_to)
    ), scored AS MATERIALIZED (
      SELECT * FROM filtered ORDER BY played_at DESC LIMIT c_analysis_cap
    ), totals AS (
      SELECT count(*)::integer hands,
        count(*) FILTER (WHERE tournament_id IS NULL)::integer cash_hands,
        count(*) FILTER (WHERE tournament_id IS NOT NULL)::integer tourney_hands,
        count(DISTINCT tournament_id) FILTER (WHERE tournament_id IS NOT NULL)::integer tournaments_with_hands,
        count(*) FILTER (WHERE net > 0)::integer hands_won,
        count(*) FILTER (WHERE vpip)::integer vpip_hands,
        count(*) FILTER (WHERE pfr)::integer pfr_hands,
        count(*) FILTER (WHERE three_bet)::integer three_bet_hands,
        count(*) FILTER (WHERE faced_three_bet)::integer faced_three_bet_hands,
        count(*) FILTER (WHERE folded_to_three_bet)::integer folded_to_three_bet_hands,
        count(*) FILTER (WHERE had_cbet_flop_opp)::integer cbet_opps,
        count(*) FILTER (WHERE cbet_flop)::integer cbet_hands,
        coalesce(sum(aggressive_actions), 0)::integer aggro,
        coalesce(sum(passive_actions), 0)::integer passive,
        count(*) FILTER (WHERE saw_flop)::integer saw_flop_hands,
        count(*) FILTER (WHERE went_to_showdown)::integer showdowns,
        count(*) FILTER (WHERE won_at_showdown)::integer showdowns_won,
        coalesce(sum(net) FILTER (WHERE tournament_id IS NULL), 0) cash_profit,
        coalesce(sum(returned) FILTER (WHERE tournament_id IS NULL), 0) cash_won,
        coalesce(sum(invested) FILTER (WHERE tournament_id IS NULL), 0) cash_invested,
        coalesce(max(returned) FILTER (WHERE tournament_id IS NULL), 0) biggest_pot,
        coalesce(min(net) FILTER (WHERE tournament_id IS NULL), 0) biggest_loss,
        coalesce(sum(net_bb) FILTER (WHERE tournament_id IS NULL), 0) cash_net_bb,
        min(played_at) first_hand_at, max(played_at) last_hand_at
      FROM filtered
    ), analysis_sample AS (
      SELECT count(*)::integer hands FROM scored
    ), daily AS (
      SELECT date(played_at AT TIME ZONE v_tz) d, count(*)::integer hands,
             round(sum(net), 2) profit
      FROM filtered WHERE tournament_id IS NULL GROUP BY 1 ORDER BY 1
    ), positions AS (
      SELECT position, count(*)::integer hands_played,
        count(*) FILTER (WHERE vpip)::integer vpip_count,
        count(*) FILTER (WHERE pfr)::integer pfr_count,
        count(*) FILTER (WHERE three_bet)::integer three_bet_count,
        count(*) FILTER (WHERE net > 0)::integer hands_won,
        round(coalesce(sum(net) FILTER (WHERE tournament_id IS NULL), 0), 2) total_profit,
        round(coalesce(sum(net_bb) FILTER (WHERE tournament_id IS NULL), 0)
          / nullif(count(*) FILTER (WHERE tournament_id IS NULL), 0) * 100, 2) bb100
      FROM scored GROUP BY position
    ), variants AS (
      SELECT game_variant, count(*)::integer hands,
        count(*) FILTER (WHERE net > 0)::integer hands_won,
        round(coalesce(sum(net) FILTER (WHERE tournament_id IS NULL), 0), 2) profit,
        round(coalesce(sum(net_bb) FILTER (WHERE tournament_id IS NULL), 0)
          / nullif(count(*) FILTER (WHERE tournament_id IS NULL), 0) * 100, 2) bb100
      FROM scored GROUP BY game_variant
    ), stakes AS (
      SELECT big_blind, count(*)::integer hands,
        count(*) FILTER (WHERE net > 0)::integer hands_won,
        round(sum(net), 2) profit,
        round(sum(net_bb) / nullif(count(*), 0) * 100, 2) bb100
      FROM scored WHERE tournament_id IS NULL AND big_blind > 0 GROUP BY big_blind
    ), tournament_rows AS (
      SELECT tp.*, t.name, t.start_time, t.ended_at, t.variant, t.buy_in_amount, t.buy_in_fee,
             t.rebuy_cost, t.addon_cost, t.is_mystery_bounty
      FROM public.tournament_players tp
      JOIN public.tournaments t ON t.id = tp.tournament_id
      WHERE tp.user_id = p_user AND coalesce(tp.club_id,t.club_id) = p_club_id
        AND upper(coalesce(t.status, '')) = 'COMPLETED'
        AND t.ended_at IS NOT NULL
        AND (v_from IS NULL OR t.ended_at >= v_from)
        AND (v_to IS NULL OR t.ended_at < v_to)
    ), tournament_totals AS (
      SELECT count(*)::integer entries,
        count(*) FILTER (WHERE coalesce(prize, 0) > 0)::integer cashes,
        count(*) FILTER (WHERE position = 1 OR status = 'winner')::integer wins,
        min(position) FILTER (WHERE position IS NOT NULL) best_finish,
        coalesce(sum(coalesce(buy_in_amount, 0) + coalesce(buy_in_fee, 0)
          + coalesce(rebuys, 0) * coalesce(rebuy_cost, 0)
          + CASE WHEN add_on THEN coalesce(addon_cost, 0) ELSE 0 END), 0) total_buyins,
        coalesce(sum(coalesce(prize, 0)), 0) total_prizes,
        coalesce(sum(coalesce(bounty_winnings, 0)), 0) total_bounty_winnings,
        coalesce(sum(coalesce(bounties_collected, 0)), 0)::integer total_bounties
