--
-- TOC entry 8790 (class 1255 OID 72767700)
-- Name: ca_player_stats_pulse(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_stats_pulse(p_user uuid, p_asset text DEFAULT 'chips'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_newest_hand timestamptz;
  v_tourn text;
BEGIN
  PERFORM public.ca_assert_self(p_user);
  IF p_asset IS NULL OR p_asset NOT IN ('chips', 'diamonds') THEN
    RAISE EXCEPTION 'unknown stats asset: %', p_asset USING ERRCODE = '22023';
  END IF;

  -- idx_ca_hand_player_idx_user_time (user_id, created_at DESC): one probe.
  SELECT max(created_at) INTO v_newest_hand
  FROM public.ca_hand_player_idx WHERE user_id = p_user AND asset = p_asset;

  -- idx_tourn_players_user: a player's rows number in the hundreds at most.
  -- Any finish, prize, bounty or new entry changes the fingerprint.
  SELECT md5(coalesce(string_agg(
           id::text || ':' || coalesce(status, '') || ':' || coalesce(position::text, '')
             || ':' || coalesce(prize::text, '') || ':' || coalesce(bounty_winnings::text, '')
             || ':' || coalesce(eliminated_at::text, ''),
           '|' ORDER BY id), ''))
    INTO v_tourn
  FROM public.tournament_players WHERE user_id = p_user;

  RETURN jsonb_build_object(
    'newest_hand_at', v_newest_hand,
    'tournaments', v_tourn,
    'pulse', coalesce(v_newest_hand::text, '') || '#' || coalesce(v_tourn, '')
  );
END;
$$;


ALTER FUNCTION public.ca_player_stats_pulse(p_user uuid, p_asset text) OWNER TO postgres;

--
-- TOC entry 44664 (class 0 OID 0)
-- Dependencies: 8790
-- Name: FUNCTION ca_player_stats_pulse(p_user uuid, p_asset text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ca_player_stats_pulse(p_user uuid, p_asset text) IS 'The stats page''s heartbeat: the newest hand of one asset (p_asset, default chips) in the player''s own index and a fingerprint of their tournament rows, as one string. The page polls it while visible and refetches when it changes. Owner only (ca_assert_self). Replaces the Realtime subscription on ca_hand_player_idx, which left the publication on 2026-09-04.';


--
-- TOC entry 9493 (class 1255 OID 93130414)
-- Name: ca_player_stats_pulse_by_club(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_player_stats_pulse_by_club(p_user uuid, p_asset text DEFAULT 'chips'::text, p_club_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_hand timestamptz; v_tourn text;
BEGIN
  -- funded_stats_scope: historical funding, original caller gates.
  PERFORM public.ca_assert_player_stats_club(p_user,p_club_id,p_asset);
  SELECT played_at INTO v_hand FROM (
 WITH receipts AS MATERIALIZED (
  SELECT DISTINCT ON(table_id,account_entity_id,seat_joined_at)
   table_id,account_entity_id,seat_joined_at,funding_club_id
  FROM public.cash_participant_funding_receipts
  WHERE account_entity_id=p_user AND operation_kind='buyin'
  ORDER BY table_id,account_entity_id,seat_joined_at,recorded_at DESC,id DESC
 ), funding AS MATERIALIZED (
  SELECT *,lead(seat_joined_at) OVER(PARTITION BY table_id,account_entity_id ORDER BY seat_joined_at) until_at
  FROM receipts
 )
 SELECT fact.*,coalesce(x.funding_club_id,tp.club_id,ra.club_id,fact.club_id) funded_club
 FROM public.ca_hand_facts fact
 LEFT JOIN funding x ON fact.tournament_id IS NULL AND x.table_id=fact.table_id
  AND fact.played_at>=x.seat_joined_at AND (x.until_at IS NULL OR fact.played_at<x.until_at)
 LEFT JOIN public.tournament_players tp ON tp.tournament_id=fact.tournament_id AND tp.user_id=fact.user_id
 LEFT JOIN public.rake_attributions ra ON x.funding_club_id IS NULL AND tp.club_id IS NULL
  AND ra.hand_id=fact.hand_id AND ra.player_id=fact.user_id
 WHERE fact.user_id=p_user
 ) funded_stats_scope
    WHERE user_id=p_user AND funded_club=p_club_id ORDER BY played_at DESC LIMIT 1;
  SELECT md5(coalesce(string_agg(tp.id::text||':'||coalesce(tp.status,'')||':'||
    coalesce(tp.position::text,'')||':'||coalesce(tp.prize::text,'')||':'||
    coalesce(tp.bounty_winnings::text,''),'|' ORDER BY tp.id),'')) INTO v_tourn
  FROM public.tournament_players tp JOIN public.tournaments t ON t.id=tp.tournament_id
  WHERE tp.user_id=p_user AND coalesce(tp.club_id,t.club_id)=p_club_id;
  RETURN jsonb_build_object('contract_version',2,
    'scope',jsonb_build_object('target_user_id',p_user,'club_id',p_club_id,'asset',p_asset,'visibility','owner'),
    'newest_hand_at',v_hand,'tournaments',v_tourn,
    'pulse',coalesce(v_hand::text,'')||'#'||coalesce(v_tourn,''));
END;$$;


