--
-- TOC entry 5681 (class 1255 OID 93130364)
-- Name: ca_stats_calendar_bounds(integer, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ca_stats_calendar_bounds(p_days integer DEFAULT NULL::integer, p_tz text DEFAULT 'UTC'::text, p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(range_days integer, range_tz text, from_at timestamp with time zone, to_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_days integer := CASE WHEN p_days IS NULL THEN NULL ELSE least(greatest(p_days,1),3650) END;
  v_tz text := CASE WHEN EXISTS (SELECT 1 FROM pg_timezone_names WHERE name=p_tz) THEN p_tz ELSE 'UTC' END;
BEGIN
  RETURN QUERY SELECT v_days, v_tz,
    CASE WHEN v_days IS NULL THEN NULL ELSE
      (((p_now AT TIME ZONE v_tz)::date-(v_days-1))::timestamp AT TIME ZONE v_tz) END,
    CASE WHEN v_days IS NULL THEN NULL ELSE
      ((((p_now AT TIME ZONE v_tz)::date+1)::timestamp) AT TIME ZONE v_tz) END;
END;
$$;


