    CONSTRAINT chk_membership_tier CHECK ((membership_tier = ANY (ARRAY['standard'::text, 'gold'::text, 'platinum'::text, 'vip'::text, 'daily'::text, 'weekly'::text, 'monthly'::text, 'yearly'::text])))
