--
-- TOC entry 5182 (class 1255 OID 4631822)
-- Name: complete_home_game(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_home_game(p_game_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_game    RECORD;
    v_group   RECORD;
    v_attended int;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;

    SELECT * INTO v_game FROM commander_home_games WHERE id = p_game_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;

    IF v_game.status = 'completed' THEN
        RAISE EXCEPTION 'ALREADY_COMPLETED';
    END IF;
    IF v_game.status = 'cancelled' THEN
        RAISE EXCEPTION 'CANNOT_COMPLETE_CANCELLED';
    END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_game.group_id;

    IF v_game.host_id <> p_caller_user_id 
       AND v_group.owner_id <> p_caller_user_id
       AND NOT EXISTS (
           SELECT 1 FROM commander_home_members 
            WHERE group_id = v_game.group_id 
              AND user_id = p_caller_user_id
              AND role = 'admin' AND status = 'approved')
    THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED';
    END IF;

    -- Flip to completed
    UPDATE commander_home_games
       SET status = 'completed', updated_at = NOW()
     WHERE id = p_game_id;

    -- Bump group's games_hosted
    UPDATE commander_home_groups
       SET games_hosted = COALESCE(games_hosted, 0) + 1
     WHERE id = v_game.group_id;

    -- Mark flakes: yes RSVPs that weren't checked in
    UPDATE commander_home_rsvps
       SET flaked = true
     WHERE game_id = p_game_id 
       AND response = 'yes' 
       AND checked_in_at IS NULL;

    -- Increment games_attended for checked-in members
    UPDATE commander_home_members m
       SET games_attended = COALESCE(m.games_attended, 0) + 1,
           last_attended  = NOW()
      FROM commander_home_rsvps r
     WHERE r.game_id = p_game_id
       AND r.user_id = m.user_id
       AND m.group_id = v_game.group_id
       AND r.checked_in_at IS NOT NULL;

    SELECT COUNT(*) INTO v_attended FROM commander_home_rsvps
     WHERE game_id = p_game_id AND checked_in_at IS NOT NULL;

    -- Audit
    INSERT INTO commander_home_audit_log (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (v_game.group_id, p_caller_user_id, 'game', p_game_id, 'completed',
            jsonb_build_object('attended', v_attended));

    RETURN jsonb_build_object(
        'success', true,
        'game_id', p_game_id,
        'attended_count', v_attended,
        'flaked_count', (SELECT COUNT(*) FROM commander_home_rsvps 
                          WHERE game_id = p_game_id AND flaked = true)
    );
END;
$$;


ALTER FUNCTION public.complete_home_game(p_game_id uuid, p_caller_user_id uuid) OWNER TO postgres;

--
-- TOC entry 7416 (class 1255 OID 153157915)
-- Name: complete_owned_native_upload(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_owned_native_upload(p_post_id uuid, p_author_id uuid, p_source_url text, p_output_url text, p_thumbnail_url text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE p public.social_posts%ROWTYPE; source_path text; output_path text; thumbnail_path text; chosen_thumbnail text; mirrors integer;
BEGIN
 SELECT * INTO p FROM public.social_posts WHERE id=p_post_id FOR UPDATE;
 IF NOT FOUND OR p.author_id IS DISTINCT FROM p_author_id OR p.is_deleted IS DISTINCT FROM false
   OR p.moderation_state='taken_down' OR p.taken_down_at IS NOT NULL
   OR p.playback_type IS DISTINCT FROM 'native' OR p.rights_status IS DISTINCT FROM 'user_authorized'
   OR p.metadata->>'native_reels_worker' IS DISTINCT FROM 'sp-transcode'
   OR p.transcode_status IS DISTINCT FROM 'running' OR p.original_media_url IS DISTINCT FROM p_source_url
   OR p.media_urls->>0 IS DISTINCT FROM p_source_url THEN
   RAISE EXCEPTION 'Native publish source is no longer authorized' USING ERRCODE='42501'; END IF;
 IF p_source_url IS NULL OR p_output_url IS NULL OR p_source_url=p_output_url
   OR p_source_url NOT LIKE 'https://kuklfnapbkmacvwxktbh.supabase.co/storage/v1/object/public/social-media/%'
   OR p_output_url NOT LIKE 'https://kuklfnapbkmacvwxktbh.supabase.co/storage/v1/object/public/social-media/%'
   OR p_source_url ~ '[?%#\\[:cntrl:]]' OR p_output_url ~ '[?%#\\[:cntrl:]]' THEN
   RAISE EXCEPTION 'Native publish URLs are not trusted' USING ERRCODE='22023'; END IF;
 source_path=substring(p_source_url from length('https://kuklfnapbkmacvwxktbh.supabase.co/storage/v1/object/public/social-media/')+1);
 output_path=substring(p_output_url from length('https://kuklfnapbkmacvwxktbh.supabase.co/storage/v1/object/public/social-media/')+1);
 IF source_path !~ ('^(videos|reels)/'||p_author_id::text||'/[^/]+$')
   OR output_path !~ ('^videos/'||p_author_id::text||'/native-'||p_post_id::text||'-[0-9a-f-]{36}\.mp4$')
   OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='social-media' AND name=source_path)
   OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='social-media' AND name=output_path) THEN
   RAISE EXCEPTION 'Native publish object is missing or not owned' USING ERRCODE='22023'; END IF;
 IF p_thumbnail_url IS NOT NULL THEN
  IF p_thumbnail_url NOT LIKE 'https://kuklfnapbkmacvwxktbh.supabase.co/storage/v1/object/public/social-media/%'
    OR p_thumbnail_url ~ '[?%#\\[:cntrl:]]' THEN RAISE EXCEPTION 'Native thumbnail URL not trusted' USING ERRCODE='22023'; END IF;
  thumbnail_path=substring(p_thumbnail_url from length('https://kuklfnapbkmacvwxktbh.supabase.co/storage/v1/object/public/social-media/')+1);
  IF thumbnail_path IS DISTINCT FROM regexp_replace(output_path,'\.mp4$','.jpg')
    OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='social-media' AND name=thumbnail_path) THEN
    RAISE EXCEPTION 'Native thumbnail object missing or not owned' USING ERRCODE='22023'; END IF;
 END IF;
 chosen_thumbnail=COALESCE(NULLIF(p.thumbnail_url,''),p_thumbnail_url);
 UPDATE public.social_posts SET media_urls=jsonb_set(media_urls,'{0}',to_jsonb(p_output_url)),
   transcode_status='done',transcode_error=NULL,thumbnail_url=chosen_thumbnail WHERE id=p.id;
 UPDATE public.social_reels SET video_url=p_output_url,thumbnail_url=COALESCE(NULLIF(thumbnail_url,''),chosen_thumbnail) WHERE source_post_id=p.id AND author_id=p.author_id
   AND playback_type='native' AND rights_status='user_authorized' AND is_deleted=false AND video_url=p_source_url AND media_status='ready'
   AND moderation_state IS DISTINCT FROM 'taken_down' AND taken_down_at IS NULL;
 GET DIAGNOSTICS mirrors=ROW_COUNT;
 RETURN jsonb_build_object('completed',true,'postId',p.id,'mirrors',mirrors);
END $_$;


ALTER FUNCTION public.complete_owned_native_upload(p_post_id uuid, p_author_id uuid, p_source_url text, p_output_url text, p_thumbnail_url text) OWNER TO postgres;

--
-- TOC entry 3824 (class 1255 OID 22469045)
-- Name: complete_rights_cleared_youtube_transcode(text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_rights_cleared_youtube_transcode(p_job_id text, p_claim_token uuid, p_worker_id text, p_output_url text, p_thumbnail_url text DEFAULT NULL::text) RETURNS TABLE(transcode_job_id text, social_reel_id uuid, social_post_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_job public.video_transcode_jobs%ROWTYPE;
  v_reel public.social_reels%ROWTYPE;
  v_post public.social_posts%ROWTYPE;
  v_youtube_id text;
  v_native_enabled boolean := false;
  v_job_found boolean := false;
  v_output_url text := split_part(split_part(btrim(COALESCE(p_output_url, '')), '?', 1), '#', 1);
BEGIN
  IF COALESCE(auth.role()::text, '') <> 'service_role' THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'complete_rights_cleared_youtube_transcode requires the service role';
  END IF;

  IF p_job_id IS NULL
     OR btrim(p_job_id) !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     OR p_claim_token IS NULL
     OR btrim(COALESCE(p_worker_id, '')) = ''
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'job, claim token, and worker identity are required';
  END IF;

  SELECT j.*
  INTO v_job
  FROM public.video_transcode_jobs j
  WHERE j.id = p_job_id
  FOR UPDATE;
  v_job_found := FOUND;

  -- A response may be lost after COMMIT. Replaying the same immutable claim and
  -- output is a successful acknowledgement, never a second publication. This
  -- check deliberately precedes the kill switch so a completed write remains
  -- acknowledgeable after an emergency shutdown.
  IF v_job_found
     AND v_job.status = 'completed'
     AND v_job.claim_token IS NOT DISTINCT FROM p_claim_token
     AND v_job.worker_id IS NOT DISTINCT FROM p_worker_id
     AND split_part(split_part(COALESCE(v_job.output_url, ''), '?', 1), '#', 1)
       IS NOT DISTINCT FROM v_output_url
  THEN
    SELECT r.*
    INTO v_reel
    FROM public.social_reels r
    WHERE r.id = v_job.reel_id;

    IF FOUND
       AND v_reel.source_post_id IS NOT NULL
       AND v_reel.video_url IS NOT DISTINCT FROM v_output_url
       AND v_reel.playback_type = 'native'
       AND v_reel.source_type = 'native'
       AND v_reel.media_status = 'ready'
       AND public.fn_is_user_video_storage_url(v_output_url, v_reel.author_id)
    THEN
      SELECT p.*
      INTO v_post
      FROM public.social_posts p
      WHERE p.id = v_reel.source_post_id;

      IF FOUND
         AND NULLIF(v_post.media_urls ->> 0, '') IS NOT DISTINCT FROM v_output_url
         AND v_post.playback_type = 'native'
      THEN
        RETURN QUERY SELECT v_job.id, v_reel.id, v_post.id;
        RETURN;
      END IF;
    END IF;

    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'completed transcode acknowledgement does not match current publication state';
  END IF;

  SELECT c.enabled
  INTO v_native_enabled
  FROM public.video_reels_pipeline_controls c
  WHERE c.control_key = 'youtube_native_transcode'
  FOR SHARE;

  IF NOT COALESCE(v_native_enabled, false) THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000',
      MESSAGE = 'YouTube native transcode publication is disabled';
  END IF;

  IF NOT v_job_found
     OR v_job.status <> 'processing'
     OR v_job.claim_token IS DISTINCT FROM p_claim_token
     OR v_job.worker_id IS DISTINCT FROM p_worker_id
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000',
      MESSAGE = 'transcode claim is no longer current';
  END IF;

  SELECT r.*
  INTO v_reel
  FROM public.social_reels r
  WHERE r.id = v_job.reel_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '23503',
      MESSAGE = 'claimed transcode Reel does not exist';
  END IF;

  v_youtube_id := public.fn_extract_youtube_video_id(v_job.youtube_url);
  IF v_youtube_id IS NULL
     OR public.fn_extract_youtube_video_id(v_job.source_url) IS DISTINCT FROM v_youtube_id
     OR public.fn_extract_youtube_video_id(v_reel.video_url) IS DISTINCT FROM v_youtube_id
     OR public.fn_extract_youtube_video_id(v_reel.original_youtube_url) IS DISTINCT FROM v_youtube_id
     OR v_job.canonical_asset_key IS DISTINCT FROM 'youtube:' || v_youtube_id
     OR v_reel.youtube_video_id IS DISTINCT FROM v_youtube_id
     OR v_reel.canonical_asset_key IS DISTINCT FROM 'youtube:' || v_youtube_id
     OR v_job.user_id IS DISTINCT FROM v_reel.author_id
     OR v_job.source_type IS DISTINCT FROM 'youtube'
     OR v_reel.source_type IS DISTINCT FROM 'youtube'
     OR v_job.rights_status NOT IN ('owned', 'licensed')
     OR v_reel.rights_status IS DISTINCT FROM v_job.rights_status
     OR v_job.origin_type IS DISTINCT FROM v_reel.origin_type
     OR v_job.source_asset_id IS DISTINCT FROM v_reel.source_asset_id
     OR v_reel.native_processing_requested IS DISTINCT FROM true
     OR COALESCE(v_reel.is_deleted, false)
     OR v_reel.source_post_id IS NULL
     OR v_reel.origin_type = 'video_library'
     OR v_reel.source_type = 'video_library'
     OR NOT public.fn_has_fresh_public_youtube_verification(v_youtube_id)
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'current Reel does not match the claimed rights-cleared YouTube source';
  END IF;

  IF NOT public.fn_is_user_video_storage_url(v_output_url, v_reel.author_id) THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'native output must be an existing video in the Reel author namespace';
  END IF;

  SELECT p.*
  INTO v_post
  FROM public.social_posts p
  WHERE p.id = v_reel.source_post_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_post.author_id IS DISTINCT FROM v_reel.author_id
     OR v_post.content_type IS DISTINCT FROM 'video'
     OR COALESCE(v_post.is_deleted, false)
     OR v_post.canonical_asset_key IS DISTINCT FROM v_reel.canonical_asset_key
     OR v_post.rights_status IS DISTINCT FROM v_reel.rights_status
     OR public.fn_extract_youtube_video_id(NULLIF(v_post.media_urls ->> 0, ''))
        IS DISTINCT FROM v_youtube_id
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'linked post does not match the claimed rights-cleared Reel';
  END IF;

  -- Retire the exact claim before changing the Reel's processing request.
  -- This remains atomic with the publication below, while ensuring the
  -- authorization-revocation trigger cannot cancel the completion itself.
  UPDATE public.video_transcode_jobs j
  SET status = 'completed',
      completed_at = now(),
      output_url = v_output_url,
      error_message = NULL,
      heartbeat_at = now(),
      locked_at = NULL
  WHERE j.id = v_job.id
    AND j.status = 'processing'
    AND j.claim_token = p_claim_token
    AND j.worker_id = p_worker_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000',
      MESSAGE = 'transcode claim changed before completion';
  END IF;

  PERFORM set_config(
    'app.youtube_native_completion_job_id',
    v_job.id,
    true
  );

  UPDATE public.social_reels r
  SET video_url = v_output_url,
      thumbnail_url = COALESCE(NULLIF(btrim(p_thumbnail_url), ''), r.thumbnail_url),
      source_type = 'native',
      playback_type = 'native',
      media_status = 'ready',
      native_processing_requested = false
  WHERE r.id = v_reel.id;

  UPDATE public.social_posts p
  SET media_urls = CASE
        WHEN jsonb_typeof(p.media_urls) = 'array'
          AND jsonb_array_length(p.media_urls) > 0
        THEN jsonb_set(p.media_urls, '{0}', to_jsonb(v_output_url), false)
        ELSE jsonb_build_array(v_output_url)
      END,
      -- The locked job/Reel/post lineage above is authoritative. Normalize
      -- legacy or stale provenance instead of letting a mismatched historical
      -- original_media_url make the guarded native transition impossible.
      original_media_url =
        'https://www.youtube.com/watch?v=' || v_youtube_id,
      thumbnail_url = COALESCE(NULLIF(btrim(p_thumbnail_url), ''), p.thumbnail_url),
      playback_type = 'native'
  WHERE p.id = v_post.id;

  RETURN QUERY SELECT v_job.id, v_reel.id, v_post.id;
END
$_$;


ALTER FUNCTION public.complete_rights_cleared_youtube_transcode(p_job_id text, p_claim_token uuid, p_worker_id text, p_output_url text, p_thumbnail_url text) OWNER TO postgres;

