--
-- TOC entry 8855 (class 1255 OID 2001909)
-- Name: credit_agent_commission(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.credit_agent_commission(p_agent_id uuid, p_amount numeric, p_description text DEFAULT 'Agent commission'::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    UPDATE wallets SET balance = balance + p_amount, updated_at = NOW() WHERE user_id = p_agent_id AND wallet_type = 'BUSINESS';
    IF NOT FOUND THEN INSERT INTO wallets (user_id, wallet_type, balance, locked_balance, created_at, updated_at) VALUES (p_agent_id, 'BUSINESS', p_amount, 0, NOW(), NOW()); END IF;
    INSERT INTO wallet_transactions (user_id, wallet_type, amount, type, category, description, created_at) VALUES (p_agent_id, 'BUSINESS', p_amount, 'credit', 'commission', p_description, NOW());
END;
$$;


