--
-- TOC entry 3420 (class 1255 OID 2406448)
-- Name: decrement_post_count(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.decrement_post_count(p_post_id uuid, p_field text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  _allowed_fields text[] := ARRAY[
    'like_count', 'comment_count', 'share_count', 'view_count'
  ];
BEGIN
  IF COALESCE(auth.role(), 'service_role') <> 'service_role' THEN
    RAISE EXCEPTION 'decrement_post_count: a count is not a browser''s to take down' USING ERRCODE = '42501';
  END IF;
  IF NOT (p_field = ANY(_allowed_fields)) THEN
    RAISE EXCEPTION 'decrement_post_count: invalid field %', p_field;
  END IF;

  EXECUTE format(
    'UPDATE public.social_posts SET %I = GREATEST(COALESCE(%I, 0) - 1, 0) WHERE id = $1',
    p_field, p_field
  ) USING p_post_id;
END;
$_$;


