--
-- TOC entry 6364 (class 1255 OID 223069525)
-- Name: detect_multi_account_v2(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.detect_multi_account_v2(p_since timestamp with time zone, p_until timestamp with time zone DEFAULT now()) RETURNS TABLE(user_a uuid, user_b uuid, shared_ips integer, same_table boolean, severity text, ips text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    AS $_$
  with raw as (
    select a.user_id, a.ip_address as ip, a.details->>'table_id' as table_id,
           floor(extract(epoch from a.created_at) / 10800)::bigint as bucket
    from public.action_audit_logs a
    where a.created_at >= p_since and a.created_at < p_until
      and a.ip_address is not null
      and a.user_id is not null
      and a.ip_address ~ '^[0-9]{1,3}(\.[0-9]{1,3}){3}$'
    group by 1, 2, 3, 4
  ), ips_ok as (
    select d.ip from (select distinct ip from raw) d
    where not exists (select 1 from public.anti_cheat_shared_ip_ranges r where d.ip::inet <<= r.cidr)
  ), eligible as (
    select u.user_id from (select distinct user_id from raw) u
    where not public.fn_anti_cheat_never_flag(u.user_id)
      and not exists (select 1 from public.anti_cheat_exemptions x
                      where x.player_id = u.user_id and x.flag_type = 'multi_account')
  ), ev as (
    select r.* from raw r join ips_ok using (ip) join eligible using (user_id)
  ), ipn as (
    select ip from ev group by ip having count(distinct user_id) between 2 and 5
  ), ui as (
    select distinct e.user_id, e.ip from ev e join ipn using (ip)
  ), ip_pairs as (
    select a.user_id as ua, b.user_id as ub, count(*)::int as n_ips, array_agg(a.ip) as ip_list
    from ui a join ui b on a.ip = b.ip and a.user_id < b.user_id
    group by 1, 2
  ), tab as (
    select distinct e.user_id, e.ip, e.table_id, e.bucket
    from ev e join ipn using (ip) where e.table_id is not null
  ), table_pairs as (
    select distinct a.user_id as ua, b.user_id as ub
    from tab a join tab b
      on a.ip = b.ip and a.table_id = b.table_id and a.user_id < b.user_id
     and b.bucket between a.bucket - 1 and a.bucket + 1
  )
  select p.ua, p.ub, p.n_ips, (t.ua is not null),
         case when t.ua is not null then 'high' else 'medium' end, p.ip_list
  from ip_pairs p left join table_pairs t on t.ua = p.ua and t.ub = p.ub
  where t.ua is not null or p.n_ips >= 2;
$_$;


ALTER FUNCTION public.detect_multi_account_v2(p_since timestamp with time zone, p_until timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 8127 (class 1255 OID 8926741)
-- Name: detect_suspicious_plays(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.detect_suspicious_plays(p_club_id uuid, p_limit integer DEFAULT 500) RETURNS TABLE(hand_id uuid, player_id uuid, hand_rank text, pot_total numeric, completed_at timestamp with time zone, severity text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_caller uuid := (SELECT auth.uid());
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM clubs c WHERE c.id = p_club_id AND (
      c.owner_id = v_caller
      OR EXISTS (SELECT 1 FROM club_members cm WHERE cm.club_id = c.id AND cm.user_id = v_caller
                   AND cm.role IN ('owner','co_owner','admin')))
  ) THEN
    RAISE EXCEPTION 'not authorized for this club';
  END IF;

  RETURN QUERY
  SELECT hh.id,
         NULLIF(w.value->>'userId', '')::uuid,
         COALESCE(w.value->'hand'->>'name', 'Unknown'),
         hh.pot_size,
         COALESCE(hh.ended_at, hh.created_at),
         CASE WHEN hh.pot_size >= 100 * NULLIF(hh.big_blind, 0) THEN 'high'
              WHEN hh.pot_size >= 60 * NULLIF(hh.big_blind, 0) THEN 'medium'
              ELSE 'low' END
    FROM hand_history hh
    JOIN tables t ON t.id = hh.table_id AND t.club_id = p_club_id
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(hh.winners, '[]'::jsonb)) w
   WHERE hh.created_at > now() - interval '30 days'
     AND hh.big_blind > 0
     AND hh.pot_size >= 40 * hh.big_blind
   ORDER BY hh.pot_size / NULLIF(hh.big_blind, 0) DESC, hh.created_at DESC
   LIMIT p_limit;
END;
$$;


