-- TOC entry 9228 (class 1255 OID 9256773)
-- Name: expire_lapsed_vip(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.expire_lapsed_vip() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_count integer := 0;
BEGIN
    UPDATE public.profiles
       SET is_vip     = false,
           vip_tier   = NULL,
           updated_at = now()
     WHERE is_vip = true
       AND vip_expires_at IS NOT NULL
       AND vip_expires_at < now()
       AND COALESCE(vip_tier, '') <> 'lifetime';

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


