--
-- TOC entry 8890 (class 1255 OID 82475054)
-- Name: expire_lifetime_vip_diamond_lots(integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.expire_lifetime_vip_diamond_lots(p_limit integer DEFAULT 1000, p_as_of timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user uuid;
  v_result jsonb;
  v_users integer := 0;
  v_expired integer := 0;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    RETURN jsonb_build_object('success', false, 'error', 'service_role_required');
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 5000 OR p_as_of IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
  END IF;

  FOR v_user IN
    SELECT user_id
      FROM public.lifetime_vip_diamond_lots
     WHERE status = 'active'
       AND remaining_amount > 0
       AND expires_at <= p_as_of
     GROUP BY user_id
     ORDER BY min(expires_at), user_id
     LIMIT p_limit
  LOOP
    v_result := public.expire_lifetime_vip_diamond_lots_for_user(v_user, p_as_of);
    IF COALESCE((v_result ->> 'success')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'Lifetime VIP Diamond expiry failed for %: %',
        v_user, COALESCE(v_result ->> 'error', 'unknown_error');
    END IF;
    v_users := v_users + 1;
    v_expired := v_expired + COALESCE((v_result ->> 'expired')::integer, 0);
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'users', v_users,
    'expired', v_expired
  );
END;
$$;


ALTER FUNCTION public.expire_lifetime_vip_diamond_lots(p_limit integer, p_as_of timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 3376 (class 1255 OID 82475048)
-- Name: expire_lifetime_vip_diamond_lots_for_user(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.expire_lifetime_vip_diamond_lots_for_user(p_user_id uuid, p_as_of timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_lot public.lifetime_vip_diamond_lots%ROWTYPE;
  v_burn_result jsonb;
  v_tx uuid;
  v_expired integer := 0;
BEGIN
  IF p_user_id IS NULL OR p_as_of IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
  END IF;

  -- The profile lock serializes expiry against every canonical wallet writer.
  PERFORM 1 FROM public.profiles WHERE id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'profile_not_found');
  END IF;

  FOR v_lot IN
    SELECT *
      FROM public.lifetime_vip_diamond_lots
     WHERE user_id = p_user_id
       AND status = 'active'
       AND remaining_amount > 0
       AND expires_at <= p_as_of
     ORDER BY expires_at, issued_at, id
     FOR UPDATE
  LOOP
    v_burn_result := public.fn_ca_burn(
      'diamonds',
      'player',
      p_user_id,
      v_lot.remaining_amount,
      'Expired Lifetime VIP Monthly Diamonds',
      'lifetime-vip-expiry:' || v_lot.id::text,
      'promotional'
    );
    IF COALESCE((v_burn_result ->> 'ok')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'Lifetime VIP Diamond expiry burn refused: %',
        COALESCE(v_burn_result ->> 'reason', 'unknown_error');
    END IF;

    SELECT id INTO v_tx
      FROM public.diamond_transactions
     WHERE user_id = p_user_id
       AND reference_id = 'lifetime-vip-expiry:' || v_lot.id::text
     LIMIT 1;
    IF v_tx IS NULL THEN
      RAISE EXCEPTION 'Lifetime VIP Diamond expiry has no journal receipt';
    END IF;

    UPDATE public.lifetime_vip_diamond_lots
       SET expired_amount = expired_amount + remaining_amount,
           remaining_amount = 0,
           status = 'expired',
           expiry_transaction_id = v_tx,
           updated_at = now()
     WHERE id = v_lot.id;
    v_expired := v_expired + v_lot.remaining_amount;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'user_id', p_user_id,
    'expired', v_expired
  );
END;
$$;


ALTER FUNCTION public.expire_lifetime_vip_diamond_lots_for_user(p_user_id uuid, p_as_of timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 4059 (class 1255 OID 1702760)
-- Name: expire_old_buyin_requests(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.expire_old_buyin_requests() RETURNS integer
    LANGUAGE sql
    SET search_path TO 'public', 'extensions'
    AS $$
  WITH expired AS (
    UPDATE buyin_requests
    SET status = 'expired'
    WHERE status = 'pending' AND expires_at < NOW()
    RETURNING id
  )
  SELECT count(*)::integer FROM expired;
$$;


