--
-- TOC entry 7958 (class 1255 OID 69714867)
-- Name: fn_a_closed_account_cannot_rewrite_itself(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_a_closed_account_cannot_rewrite_itself() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NOT DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'ACCOUNT_CLOSED: this account was closed and cannot be changed'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


