COMMENT ON FUNCTION public.fn_a_closed_account_cannot_rewrite_itself() IS 'BEFORE UPDATE on profiles, only for rows whose status is deleted: refuses the change when it is made with the closed account''s own token (auth.uid() = the row). Closing an account does not end access tokens already issued; this keeps the scrubbed profile scrubbed.';


--
-- TOC entry 3340 (class 1255 OID 121417)
-- Name: fn_accept_friend_request(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_accept_friend_request(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_sender UUID;
    v_recipient UUID;
BEGIN
    SELECT sender_id, recipient_id INTO v_sender, v_recipient
    FROM friend_requests WHERE id = p_request_id;
    
    UPDATE friend_requests SET status = 'accepted', updated_at = NOW() WHERE id = p_request_id;
    
    INSERT INTO friendships (user_id, friend_id) VALUES (v_sender, v_recipient);
    INSERT INTO friendships (user_id, friend_id) VALUES (v_recipient, v_sender);
END;
$$;


ALTER FUNCTION public.fn_accept_friend_request(p_request_id uuid) OWNER TO postgres;

--
-- TOC entry 6726 (class 1255 OID 31380582)
-- Name: fn_accounting_agent_clubs(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_accounting_agent_clubs(p_agent_user_id uuid, p_club_id uuid) RETURNS uuid[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE result uuid[]; actor uuid:=auth.uid(); engine boolean:=public.fn_caller_is_engine();
BEGIN
 IF p_agent_user_id IS NULL THEN RAISE EXCEPTION 'no_agent_context' USING ERRCODE='22023'; END IF;
 SELECT array_agg(DISTINCT a.club_id ORDER BY a.club_id) INTO result FROM public.agents a
  WHERE a.user_id=p_agent_user_id AND (p_club_id IS NULL OR a.club_id=p_club_id)
   AND (engine OR (actor IS NOT NULL AND (actor=p_agent_user_id OR public.fn_is_club_admin_uid(a.club_id) OR public.fn_union_oversees_club(a.club_id,actor))));
 IF COALESCE(cardinality(result),0)=0 THEN RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;
 RETURN result;
END $$;


ALTER FUNCTION public.fn_accounting_agent_clubs(p_agent_user_id uuid, p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 5221 (class 1255 OID 31440935)
-- Name: fn_accounting_agent_terms_at(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_accounting_agent_terms_at(p_club_id uuid, p_user_id uuid, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE identities text[]; identity_key text; v jsonb; result jsonb; active_count int:=0;
BEGIN
 -- Service-only EXECUTE ACL also permits private source-owner triggers.
 IF p_club_id IS NULL OR p_user_id IS NULL OR p_at IS NULL OR NOT isfinite(p_at) OR p_at>transaction_timestamp()
 THEN RAISE EXCEPTION 'invalid_accounting_terms_request' USING ERRCODE='22023'; END IF;
 -- Find candidate identities from history, then resolve each identity at the
 -- earning time. A later move/deletion closes the old identity; filtering the
 -- history by club before selecting its latest event would resurrect that row.
 SELECT array_agg(DISTINCT h.entity_key) INTO identities FROM public.accounting_agreement_history h
  WHERE h.entity_type='agents' AND h.club_id=p_club_id AND h.subject_user_id=p_user_id AND h.observed_at<=p_at AND (h.transaction_id=txid_current_if_assigned() OR NOT EXISTS(
   SELECT 1 FROM public.accounting_agreement_history later
   WHERE later.transaction_id=h.transaction_id AND later.observed_at>p_at));
 IF identities IS NULL THEN RAISE EXCEPTION 'accounting_terms_not_observed' USING ERRCODE='55000'; END IF;
 FOREACH identity_key IN ARRAY identities LOOP
  v:=public.fn_accounting_terms_at('agents',identity_key,p_at);
  IF v->'terms'->>'club_id'=p_club_id::text AND v->'terms'->>'user_id'=p_user_id::text
     AND v->'terms'->>'status'='active' THEN
   active_count:=active_count+1; result:=v;
  END IF;
 END LOOP;
 IF active_count=0 THEN RAISE EXCEPTION 'accounting_terms_not_active' USING ERRCODE='55000'; END IF;
 IF active_count>1 THEN RAISE EXCEPTION 'accounting_terms_ambiguous' USING ERRCODE='55000'; END IF;
 RETURN result;
END $$;


ALTER FUNCTION public.fn_accounting_agent_terms_at(p_club_id uuid, p_user_id uuid, p_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 5076 (class 1255 OID 31387295)
-- Name: fn_accounting_agreement_capture(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_accounting_agreement_capture() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE b jsonb; a jsonb; identity_row jsonb; identity_key text; moved boolean;
BEGIN
 b:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE public.fn_accounting_agreement_terms(TG_TABLE_NAME,to_jsonb(OLD)) END;
 a:=CASE WHEN TG_OP='DELETE' THEN NULL ELSE public.fn_accounting_agreement_terms(TG_TABLE_NAME,to_jsonb(NEW)) END;
 IF b IS NOT DISTINCT FROM a THEN RETURN COALESCE(NEW,OLD); END IF;
 identity_row:=COALESCE(b,a);
 identity_key:=CASE WHEN TG_TABLE_NAME='club_members' THEN identity_row->>'club_id'||':'||(identity_row->>'user_id') ELSE identity_row->>'id' END;
 moved:=TG_OP='UPDATE' AND (b->>'id' IS DISTINCT FROM a->>'id'
   OR b->>'club_id' IS DISTINCT FROM a->>'club_id' OR b->>'user_id' IS DISTINCT FROM a->>'user_id');
 INSERT INTO public.accounting_agreement_history(entity_type,entity_key,club_id,subject_user_id,event_type,actor_id,before_terms,after_terms)
 VALUES(TG_TABLE_NAME,identity_key,(identity_row->>'club_id')::uuid,(identity_row->>'user_id')::uuid,TG_OP,auth.uid(),b,CASE WHEN moved THEN NULL ELSE a END);
 -- A moved identity closes its original key and establishes the new key too.
 -- Both changes are observed in this transaction; neither is backdated.
 IF moved THEN
   identity_key:=CASE WHEN TG_TABLE_NAME='club_members' THEN a->>'club_id'||':'||(a->>'user_id') ELSE a->>'id' END;
   INSERT INTO public.accounting_agreement_history(entity_type,entity_key,club_id,subject_user_id,event_type,actor_id,before_terms,after_terms)
   VALUES(TG_TABLE_NAME,identity_key,(a->>'club_id')::uuid,(a->>'user_id')::uuid,'UPDATE',auth.uid(),NULL,a);
 END IF;
 RETURN COALESCE(NEW,OLD);
END $$;


ALTER FUNCTION public.fn_accounting_agreement_capture() OWNER TO postgres;

