-- TOC entry 7493 (class 1255 OID 78621764)
-- Name: fn_accounting_commit_horizon(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_accounting_commit_horizon() RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE oldest timestamptz; stamp timestamptz;
BEGIN
 IF NOT pg_catalog.pg_has_role(current_user,'pg_read_all_stats','MEMBER') THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_prepared_xacts) THEN RETURN NULL; END IF;
 stamp:=clock_timestamp();
 SELECT min(a.xact_start) INTO oldest FROM pg_catalog.pg_stat_activity a WHERE a.xact_start IS NOT NULL;
 RETURN least(stamp,COALESCE(oldest,stamp))-interval '2 minutes';
END $$;


ALTER FUNCTION public.fn_accounting_commit_horizon() OWNER TO postgres;

--
-- TOC entry 5303 (class 1255 OID 31371458)
-- Name: fn_accounting_conversation_audience_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_accounting_conversation_audience_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' AND EXISTS(SELECT 1 FROM public.accounting_conversations c WHERE c.conversation_id=OLD.conversation_id)
   AND (TG_OP='DELETE' OR NEW.conversation_id IS DISTINCT FROM OLD.conversation_id OR NEW.user_id IS DISTINCT FROM OLD.user_id)
 THEN RAISE EXCEPTION 'accounting_conversation_audience_is_immutable' USING ERRCODE='23514'; END IF;
 IF TG_OP<>'DELETE' AND EXISTS(SELECT 1 FROM public.accounting_conversations c WHERE c.conversation_id=NEW.conversation_id
    AND NEW.user_id<>ALL(ARRAY[c.sender_id,c.recipient_id]))
 THEN RAISE EXCEPTION 'accounting_conversation_audience_is_immutable' USING ERRCODE='23514'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_accounting_conversation_audience_guard() OWNER TO postgres;

