   RETURN QUERY SELECT m.id::uuid FROM unnest(string_to_array(NULLIF(split_part(current_setting('app.accounting_week_clubs_memo',true),'=',2),''),',')) WITH ORDINALITY m(id,n) ORDER BY m.n;
   RETURN;
  END IF;
