--
-- TOC entry 3419 (class 1255 OID 31380583)
-- Name: fn_agent_roster_report(uuid, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_roster_report(p_agent_user_id uuid, p_since timestamp with time zone, p_until timestamp with time zone, p_club_id uuid) RETURNS TABLE(player_id uuid, username text, club_id uuid, club_name text, buyins numeric, cashouts numeric, net_result numeric, rake_generated numeric, agent_commission numeric, chip_balance numeric, credit_used numeric, currently_seated boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE actor_agent uuid:=COALESCE(p_agent_user_id,auth.uid()); scopes uuid[];
 since_at timestamptz:=COALESCE(p_since,public.fn_union_week_start(now())); until_at timestamptz:=COALESCE(p_until,now());
BEGIN
 scopes:=public.fn_accounting_agent_clubs(actor_agent,p_club_id);
 IF NOT isfinite(since_at) OR NOT isfinite(until_at) OR since_at>=until_at OR until_at>now()
 THEN RAISE EXCEPTION 'invalid_statement_period' USING ERRCODE='22023'; END IF;
 RETURN QUERY
 WITH RECURSIVE hierarchy AS (
   SELECT a.id,a.user_id,a.club_id FROM public.agents a WHERE a.user_id=actor_agent AND a.club_id=ANY(scopes)
   UNION -- Set semantics terminate cycles and prevent duplicate paths from multiplying money.
   SELECT a.id,a.user_id,a.club_id FROM public.agents a JOIN hierarchy h ON a.parent_agent_id=h.id AND a.club_id=h.club_id
 ), roster AS (
   SELECT DISTINCT m.user_id,m.club_id,m.chip_balance,m.credit_used FROM public.club_members m
    JOIN hierarchy h ON h.user_id=m.agent_id AND h.club_id=m.club_id
 ), flows AS (
   SELECT r.user_id,r.club_id,
    sum(CASE WHEN l.from_type='player_wallet' AND l.from_entity_id=r.user_id AND l.to_type='table_stack' THEN l.amount ELSE 0 END) AS buyins,
    sum(CASE WHEN l.to_type='player_wallet' AND l.to_entity_id=r.user_id AND l.from_type='table_stack' THEN l.amount ELSE 0 END) AS cashouts
   FROM roster r JOIN public.chip_ledger l ON l.club_id=r.club_id AND
    ((l.from_entity_id=r.user_id AND l.from_type='player_wallet' AND l.to_type='table_stack') OR
     (l.to_entity_id=r.user_id AND l.to_type='player_wallet' AND l.from_type='table_stack'))
   WHERE l.status='posted' AND l.created_at>=since_at AND l.created_at<until_at GROUP BY r.user_id,r.club_id
 ), rake AS (
   SELECT ra.player_id,ra.club_id,sum(ra.rake_amount) AS amount FROM public.rake_attributions ra
    JOIN roster r ON r.user_id=ra.player_id AND r.club_id=ra.club_id
   WHERE ra.created_at>=since_at AND ra.created_at<until_at AND ra.club_id=ANY(scopes)
   GROUP BY ra.player_id,ra.club_id
 )
 SELECT r.user_id,p.username,r.club_id,c.name,COALESCE(f.buyins,0),COALESCE(f.cashouts,0),
  COALESCE(f.cashouts,0)-COALESCE(f.buyins,0),round(COALESCE(rk.amount,0),2),
  NULL::numeric, -- The legacy commission journal has no source player. Never repeat a club total on every player.
  r.chip_balance,r.credit_used,
  EXISTS(SELECT 1 FROM public.table_seats s WHERE s.user_id=r.user_id AND s.club_id=r.club_id AND s.left_at IS NULL)
 FROM roster r LEFT JOIN public.profiles p ON p.id=r.user_id LEFT JOIN public.clubs c ON c.id=r.club_id
 LEFT JOIN flows f ON f.user_id=r.user_id AND f.club_id=r.club_id
 LEFT JOIN rake rk ON rk.player_id=r.user_id AND rk.club_id=r.club_id
 ORDER BY 8 DESC NULLS LAST,r.club_id,r.user_id;
END $$;


ALTER FUNCTION public.fn_agent_roster_report(p_agent_user_id uuid, p_since timestamp with time zone, p_until timestamp with time zone, p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 9231 (class 1255 OID 167660131)
-- Name: fn_agent_set_player_rakeback(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_set_player_rakeback(p_club_id uuid, p_rate numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_agent public.agents%ROWTYPE;
  v_role text;
  v_old numeric;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication required');
  END IF;
  IF p_club_id IS NULL OR p_rate IS NULL OR p_rate::text IN ('NaN','Infinity','-Infinity') THEN
    RETURN jsonb_build_object('success', false, 'error', 'a club and a rate are required');
  END IF;

  SELECT cm.role INTO v_role
    FROM public.club_members cm
   WHERE cm.club_id = p_club_id AND cm.user_id = v_caller
     AND coalesce(cm.status, 'approved') IN ('active', 'approved');
  IF v_role IS NULL OR v_role NOT IN ('super_agent', 'agent', 'sub_agent') THEN
    RETURN jsonb_build_object('success', false, 'error', 'only an agent sets the rakeback their players receive');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:' || p_club_id::text, 0));
  SELECT * INTO v_agent FROM public.agents
   WHERE club_id = p_club_id AND user_id = v_caller AND status = 'active'
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'no active agent agreement in this club');
  END IF;

  IF p_rate < 0 OR p_rate > 0.50 THEN
    RETURN jsonb_build_object('success', false, 'error', 'player rakeback must be between 0 and 50 percent');
  END IF;
  IF p_rate > v_agent.commission_rate THEN
    RETURN jsonb_build_object('success', false,
      'error', 'player rakeback cannot exceed your own rate of '
               || trim(to_char(v_agent.commission_rate * 100, 'FM990.00')) || ' percent',
      'max_rate', v_agent.commission_rate);
  END IF;

  v_old := v_agent.player_rakeback_rate;
  IF v_old IS DISTINCT FROM p_rate THEN
    UPDATE public.agents
       SET player_rakeback_rate = p_rate, updated_at = now()
     WHERE id = v_agent.id;

    INSERT INTO public.audit_trail (actor_id, actor_role, action, target_type, target_id,
                                    club_id, before_state, after_state, reason)
    VALUES (v_caller, v_role, 'set_player_rakeback', 'agent', v_caller, p_club_id,
            jsonb_build_object('player_rakeback_rate', v_old),
            jsonb_build_object('player_rakeback_rate', p_rate),
            'Agent set the rakeback their players receive');
  END IF;

  RETURN jsonb_build_object('success', true, 'club_id', p_club_id,
    'player_rakeback_rate', p_rate, 'max_rate', v_agent.commission_rate);
END;
$$;


ALTER FUNCTION public.fn_agent_set_player_rakeback(p_club_id uuid, p_rate numeric) OWNER TO postgres;

--
-- TOC entry 45096 (class 0 OID 0)
-- Dependencies: 9231
-- Name: FUNCTION fn_agent_set_player_rakeback(p_club_id uuid, p_rate numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_agent_set_player_rakeback(p_club_id uuid, p_rate numeric) IS 'An agent sets the rakeback their own players receive (Dan, 2026-10-15): 0 to the lesser of 50% and their own commission. Records the change in audit_trail; accounting_agreement_history captures it through the agents trigger.';


--
-- TOC entry 5757 (class 1255 OID 18281184)
-- Name: fn_agent_unsettled_commission(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_agent_unsettled_commission(p_club_id uuid, p_user_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_club_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'fn_agent_unsettled_commission needs a club and a user'
      USING ERRCODE = '22023';
  END IF;

  IF NOT public.fn_agent_may_read_commission(p_club_id, p_user_id) THEN
    -- Not a zero. A zero is indistinguishable from "owes nothing", and this
    -- caller is not entitled to know which of the two it is.
    RAISE EXCEPTION 'not authorized to read that member''s commission'
      USING ERRCODE = '42501';
  END IF;

  RETURN (
    SELECT COALESCE(SUM(ac.amount), 0)::numeric
      FROM public.agent_commissions ac
     WHERE ac.club_id = p_club_id
       AND ac.user_id = p_user_id
       AND ac.settled_at IS NULL
       AND public.fn_ca_launch_accounting_accepts(ac.club_id,ac.created_at)
       AND NOT EXISTS (SELECT 1 FROM public.agent_commission_settlements s
                        WHERE s.club_id = ac.club_id AND s.user_id = ac.user_id
                          AND ac.created_at >= s.period_start AND ac.created_at < s.period_end));
END
$$;


ALTER FUNCTION public.fn_agent_unsettled_commission(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 45098 (class 0 OID 0)
-- Dependencies: 5757
-- Name: FUNCTION fn_agent_unsettled_commission(p_club_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_agent_unsettled_commission(p_club_id uuid, p_user_id uuid) IS 'What a club still owes one member, from agent_commissions. Guarded by fn_agent_may_read_commission: self, club admin+, agent ancestor, or service role. Raises 42501 otherwise - never a zero, which would be a lie.';


