-- Name: fn_anti_cheat_is_staff(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_anti_cheat_is_staff(p_player uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.profiles p
    where p.id = p_player
      and (coalesce(p.is_admin,false)
           or lower(coalesce(p.role,'')) in ('admin','god','super_admin','superadmin','owner','staff'))
  );
$$;


ALTER FUNCTION public.fn_anti_cheat_is_staff(p_player uuid) OWNER TO postgres;

