-- TOC entry 4229 (class 1255 OID 223069515)
-- Name: fn_anti_cheat_never_flag(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_anti_cheat_never_flag(p_player uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.fn_anti_cheat_is_staff(p_player)
      or exists (select 1 from public.profiles p where p.id = p_player and p.username ilike 'PostDeploy%');
$$;


