--
-- TOC entry 7357 (class 1255 OID 20020669)
-- Name: fn_apply_club_ladder(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_apply_club_ladder(p_club_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_members integer;
  v_level   smallint;
  v_admins integer; v_supers integer; v_agents integer;
  v_units numeric; v_units_up integer; v_hlevel integer; v_cursor integer;
BEGIN
  IF p_club_id IS NULL THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.clubs WHERE id = p_club_id) THEN RETURN; END IF;

  SELECT public.fn_get_club_realtime_member_count(p_club_id) INTO v_members;
  v_level := public.fn_club_level_for_members(v_members::integer);

  SELECT count(*) FILTER (WHERE role IN ('admin','manager')),
         count(*) FILTER (WHERE role = 'super_agent'),
         count(*) FILTER (WHERE role IN ('agent','sub_agent'))
    INTO v_admins, v_supers, v_agents
    FROM public.club_members
   WHERE club_id = p_club_id
     AND (status IS NULL OR status IN ('active','approved'));
  v_units := (v_admins * 1.00) + (v_supers * 1.00) + (v_agents * 0.25);
  v_units_up := CEIL(v_units);
  v_hlevel := 1;
  FOR v_cursor IN 1..50 LOOP
    IF v_units_up >= ROUND(2 * POWER(1.086, v_cursor - 1)) THEN v_hlevel := v_cursor; ELSE EXIT; END IF;
  END LOOP;

  UPDATE public.clubs SET
    member_count               = v_members,
    level                      = v_level,
    player_level               = v_level,
    player_threshold_current   = public.fn_club_level_min_members(v_level),
    player_threshold_next      = public.fn_club_level_min_members(v_level + 1),
    admin_count                = v_admins,
    super_agent_count          = v_supers,
    agent_count                = v_agents,
    hierarchy_units            = v_units,
    hierarchy_units_rounded_up = v_units_up,
    hierarchy_level            = v_hlevel,
    hierarchy_threshold_current = ROUND(2 * POWER(1.086, v_hlevel - 1)),
    hierarchy_threshold_next    = ROUND(2 * POWER(1.086, LEAST(v_hlevel, 49))),
    updated_at                 = now()
  WHERE id = p_club_id
    AND (member_count IS DISTINCT FROM v_members
      OR level IS DISTINCT FROM v_level
      OR player_level IS DISTINCT FROM v_level
      OR admin_count IS DISTINCT FROM v_admins
      OR super_agent_count IS DISTINCT FROM v_supers
      OR agent_count IS DISTINCT FROM v_agents
      OR player_threshold_current IS DISTINCT FROM public.fn_club_level_min_members(v_level)
      OR player_threshold_next IS DISTINCT FROM public.fn_club_level_min_members(v_level + 1));
END;
$$;


ALTER FUNCTION public.fn_apply_club_ladder(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 7164 (class 1255 OID 83808653)
-- Name: fn_apply_club_welcome_economics(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_apply_club_welcome_economics(p_club_id uuid, p_actor uuid, p_operation_id uuid, p_economics jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bbj numeric:=round((p_economics->>'bbj_seed')::numeric,2);
  v_spin_seed numeric:=round((p_economics->>'spin_seed')::numeric,2);
  v_spin jsonb; v_bbj_id uuid; v_bbj_after numeric;
  v_program_version integer; v_publish jsonb;
BEGIN
  IF p_economics->>'diamond_spins_status' IS DISTINCT FROM 'owner_acceptance_required'
     OR v_bbj<>100 OR (p_economics->>'bbj_enabled')::boolean IS NOT TRUE
     OR (p_economics->>'spins_enabled')::boolean IS NOT TRUE
     OR (p_economics->>'spin_max_stake')::numeric<>1
     OR v_spin_seed<>GREATEST(100::numeric,public.fn_spin_required_seed(1))
     OR p_economics->>'leaderboard_mode' IS DISTINCT FROM 'display_only'
     OR (p_economics->>'leaderboard_seed')::numeric<>0
     OR (p_economics->>'promo_enabled')::boolean IS NOT FALSE THEN
    RAISE EXCEPTION 'WELCOME_ECONOMICS_CONFIG_INVALID' USING ERRCODE='23514';
  END IF;
  IF EXISTS(SELECT 1 FROM public.bbj_pools WHERE club_id=p_club_id) THEN
    RAISE EXCEPTION 'WELCOME_BBJ_POOL_ALREADY_EXISTS' USING ERRCODE='55000';
  END IF;
  PERFORM set_config('app.ledger_category','club_opening_allocation',true);
  PERFORM set_config('app.ledger_counterparty','opening_setup',true);
  PERFORM set_config('app.ledger_counterparty_entity',p_club_id::text,true);
  PERFORM set_config('app.ledger_idempotency_key','club-welcome:'||p_operation_id::text||':bbj',true);
  UPDATE public.clubs SET chip_treasury=chip_treasury-v_bbj,bbj_enabled=true,
    bbj_rake_enabled=true,updated_at=now() WHERE id=p_club_id AND chip_treasury>=v_bbj;
  IF NOT FOUND THEN RAISE EXCEPTION 'WELCOME_CLUB_BANK_CANNOT_FUND_BBJ' USING ERRCODE='P0403'; END IF;
  INSERT INTO public.bbj_pools(club_id,main_balance,backup_balance,promo_balance,pool_amount,status)
  VALUES(p_club_id,v_bbj,0,0,0,'active') RETURNING id,main_balance INTO v_bbj_id,v_bbj_after;
  v_spin:=public.fn_spin_activate(p_club_id,v_spin_seed,1,'chip_treasury',p_actor);
  IF COALESCE((v_spin->>'ok')::boolean,false) IS NOT TRUE THEN
    RAISE EXCEPTION 'WELCOME_SPIN_ACTIVATION_REFUSED: %',COALESCE(v_spin->>'reason','unknown');
  END IF;
  UPDATE public.clubs SET spins_enabled=true,spins_preseed_amount=v_spin_seed,
    spins_wallet_funding='CHIP_TREASURY',updated_at=now() WHERE id=p_club_id;
  SELECT COALESCE(max(version),0) INTO v_program_version
    FROM public.leaderboard_reward_program_versions WHERE club_id=p_club_id;
  v_publish:=public.fn_publish_leaderboard_reward_program(p_club_id,false,'profit',
    '[]'::jsonb,'[]'::jsonb,'balanced',v_program_version,p_operation_id,false);
  RETURN jsonb_build_object('bbj_enabled',true,'bbj_seed',v_bbj,'bbj_pool_id',v_bbj_id,
    'bbj_balance',v_bbj_after,'spins_enabled',true,'spin_max_stake',1,
    'spin_seed',v_spin_seed,'spin',v_spin,'leaderboard_mode','display_only',
    'leaderboard_seed',0,'leaderboard',v_publish,'promo_enabled',false,
    'diamond_spins_status','owner_acceptance_required');
END $$;


