    CONSTRAINT video_enrichment_records_quality_score_check CHECK (((quality_score IS NULL) OR ((quality_score >= (0)::numeric) AND (quality_score <= (100)::numeric)))),
    CONSTRAINT video_enrichment_records_source_quality_score_check CHECK (((source_quality_score IS NULL) OR ((source_quality_score >= (0)::numeric) AND (source_quality_score <= (100)::numeric)))),
    CONSTRAINT video_enrichment_records_transcript_status_check CHECK ((transcript_status = ANY (ARRAY['pending'::text, 'available'::text, 'unavailable'::text, 'failed'::text]))),
    CONSTRAINT video_enrichment_records_version_check CHECK ((version > 0)),
    CONSTRAINT video_enrichment_records_workflow_state_check CHECK ((workflow_state = ANY (ARRAY['discovered'::text, 'validated'::text, 'enriched'::text, 'candidate'::text, 'approved'::text, 'rejected'::text, 'published'::text])))
