--
-- TOC entry 3436 (class 1255 OID 21988583)
-- Name: fn_audit_fleet_drop_identity(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_fleet_drop_identity(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  v_net numeric; v_rake numeric; v_bbj numeric; v_hands bigint;
  v_residual numeric; v_resid_bb100 numeric; v_raw_bb100 numeric;
begin
  select coalesce(sum(net_bb),0), coalesce(sum(rake_bb),0), coalesce(sum(bbj_bb),0), coalesce(sum(hands),0)
    into v_net, v_rake, v_bbj, v_hands
    from horse_daily_nets where day = p_day and format in ('cash','hu_cash');
  if v_hands < 10000 then
    -- Too little play for the identity to mean anything; say so rather than
    -- report a number nobody should act on.
    return v;
  end if;

  v_residual := v_net + v_rake + v_bbj;
  v_resid_bb100 := round(v_residual / v_hands * 100, 2);
  v_raw_bb100 := round(v_net / v_hands * 100, 2);

  -- THE FREE DIAGNOSIS. rake_bb landed on 2026-09-05 and bbj_bb on
  -- 2026-09-06; a day where one is flowing and the other is flat zero names
  -- the missing half without reading a second table.
  if v_rake <> 0 and v_bbj = 0 then
    v := v || jsonb_build_object('severity','warn','category','schema','code','drop_half_missing',
      'title','The rake is attributed and the jackpot drop is not - ' || v_resid_bb100 || ' bb/100 unexplained',
      'evidence', jsonb_build_object('day', p_day, 'hands', v_hands, 'rake_bb', round(v_rake,0),
                                     'bbj_bb', round(v_bbj,0), 'residual_bb100', v_resid_bb100),
      'recommendation','horse_daily_nets.bbj_bb is written by HorseHandReview.accumulateHorseNets from ServerTableEngineSettlement''s bbjAmount, allocated by allocateWeightedShareCents exactly as rake_bb is. A zero here means the engine is serving a build from before that shipped, or bbjAmount is not reaching logHandHistory. Until it flows, the regression rule is judging the jackpot drop as a leak.');
  end if;

  if abs(v_resid_bb100) > 5 then
    v := v || jsonb_build_object('severity','warn','category','logic','code','fleet_residual_unexplained',
      'title','The fleet is ' || v_resid_bb100 || ' bb/100 after the whole drop, and it plays itself',
      'evidence', jsonb_build_object('day', p_day, 'hands', v_hands, 'net_bb', round(v_net,0),
                                     'rake_bb', round(v_rake,0), 'bbj_bb', round(v_bbj,0),
                                     'raw_bb100', v_raw_bb100, 'residual_bb100', v_resid_bb100),
      'recommendation','A closed system nets to zero minus the drop, so a residual this size is a drop nobody attributed, chips leaving to human players (hand_history.has_human - there were 29 human hands in 143,795 on 2026-09-05), or a settlement path that does not balance. Find it before letting the regression rule judge anyone: it reads the whole residual as a leak.');
  else
    v := v || jsonb_build_object('severity','info','category','logic','code','fleet_drop_identity_holds',
      'title','The fleet nets to ' || v_resid_bb100 || ' bb/100 once the rake and the jackpot are counted',
      'evidence', jsonb_build_object('day', p_day, 'hands', v_hands, 'net_bb', round(v_net,0),
                                     'rake_bb', round(v_rake,0), 'bbj_bb', round(v_bbj,0),
                                     'raw_bb100', v_raw_bb100, 'residual_bb100', v_resid_bb100),
      'recommendation','This is the fleet''s true result, and the raw ' || v_raw_bb100 || ' bb/100 on the same day is the house take rather than a leak. Nothing may tune on the raw number.');
  end if;

  return v;
end $$;


ALTER FUNCTION public.fn_audit_fleet_drop_identity(p_day date) OWNER TO postgres;

--
-- TOC entry 9337 (class 1255 OID 16715206)
-- Name: fn_audit_fleet_health(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_fleet_health(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  v_fleet int;
  v_played int;
  v_idle int;
  v_over int;
  v_over_max int;
  v_ghosts int;
  v_ghost_max_min numeric;
  v_decided_unfinished int;
  v_decided_max_min numeric;
  v_open_seats int;
  v_seat_total int;
  v_seat_filled int;
  v_avail_horses int;
begin
  select count(*) into v_fleet from profiles
    where is_horse = true
      and coalesce(horse_status, 'available') <> 'disabled';
  select count(distinct horse_user_id) into v_played
    from horse_daily_nets where day = p_day;
  v_idle := greatest(0, v_fleet - v_played);

  if v_fleet > 0 and v_idle::numeric / v_fleet > 0.20 then
    v := v || jsonb_build_object(
      'severity', case when v_idle::numeric / v_fleet > 0.40 then 'critical' else 'warn' end,
      'category','logic','code','fleet_idle_share',
      'title', v_idle || ' of ' || v_fleet || ' horses dealt no hands',
      'evidence', jsonb_build_object('fleet', v_fleet, 'played', v_played, 'idle', v_idle),
      'recommendation','Activity windows legitimately idle ~40% at any instant, but across a WHOLE day nearly every horse should deal. Check HorseFleetManager seeding cycles and the overlay guard candidate pools.');
  end if;

  select count(*), coalesce(max(l), 0) into v_over, v_over_max
    from (select fn_concurrent_game_load(id) l from profiles where is_horse = true) q
   where l > 4;
  if v_over > 5 then
    v := v || jsonb_build_object(
      'severity', case when v_over > 25 then 'critical' else 'warn' end,
      'category','logic','code','fleet_over_cap',
      'title', v_over || ' horses are above the four-game cap (max ' || v_over_max || ')',
      'evidence', jsonb_build_object('over_cap', v_over, 'max_load', v_over_max),
      'recommendation','trg_enforce_four_table_limit and trg_enforce_booking_game_cap hold this at write time with an advisory lock, so a few are expected from tournament STATUS transitions that retroactively count a booking. Many means a write path is bypassing the triggers - find it.');
  end if;

  select count(*), coalesce(max(extract(epoch from (now() - ts.joined_at))/60), 0)
    into v_ghosts, v_ghost_max_min
    from table_seats ts
    join tables t on t.id = ts.table_id
    join tournaments tr on tr.id = t.tournament_id
    join tournament_players tp
      on tp.tournament_id = t.tournament_id and tp.user_id = ts.user_id
   where ts.left_at is null
     and tr.status = 'RUNNING'
     and tp.status = 'playing'
     and coalesce(ts.stack, 0) <= 0
     and ts.joined_at < now() - interval '10 minutes';

  -- DECIDED SINCE THE LAST HAND, NOT SINCE THE START (2026-09-28). The age a
  -- reader needs is how long a decided event has waited, which starts at its
  -- final hand. idx_hand_history_tournament_created serves each lookup.
  select count(*),
         coalesce(max(extract(epoch from (now() - coalesce(d.last_hand, d.started_at)))/60), 0)
    into v_decided_unfinished, v_decided_max_min
    from (
      select tr.id, tr.started_at,
             (select max(h.created_at) from hand_history h
               where h.tournament_id = tr.id) as last_hand
        from tournaments tr
       where tr.status = 'RUNNING'
         and tr.started_at < now() - interval '5 minutes'
         and (select count(*) from tournament_players tp
               where tp.tournament_id = tr.id
                 and tp.status = 'playing'
                 and coalesce(tp.chips, 0) > 0) <= 1
    ) d;

  if v_ghosts > 0 or v_decided_unfinished > 0 then
    v := v || jsonb_build_object(
      'severity', case when v_decided_unfinished > 5 or v_ghosts > 10 then 'critical' else 'warn' end,
      'category','logic','code','bust_sweep_lag',
      'title', v_ghosts || ' busted entrants still hold seats, and ' ||
               v_decided_unfinished || ' running tournament(s) are already decided but unpaid',
      'evidence', jsonb_build_object(
        'ghost_seats', v_ghosts,
        'oldest_seat_tenure_minutes', round(v_ghost_max_min),
        'decided_unfinished', v_decided_unfinished,
        'oldest_decided_minutes', round(v_decided_max_min),
        'measured_at', now(),
        'metric_note', 'oldest_decided_minutes is measured from the decided tournament''s LAST HAND (its start time only when it dealt none) - how long a winner has been waiting. Before 2026-09-28 it was measured from started_at and read as days. oldest_seat_tenure_minutes is how long the player has been SEATED, not how long the bust has gone unswept - there is no bust timestamp in the schema. Escalation uses decided_unfinished, which is unambiguous.'),
      'recommendation','Decided tournaments are waiting for the finish path. Read the engine log before assuming capacity: on 2026-09-28 the seat-first finish sweep was refused 262 times in 20 minutes by fn_f06_assert_drained_manager_custody with F06_DRAINED_CUSTODY_EVENT_CHANGED (the event had left RUNNING by the time the sweep asked), while decided events took ~40 minutes to complete. On 2026-09-02 the cause was a starved event loop (2,621 elimination_sweep_overrunning in 5.5 hours). Do not change the bust predicate, the zero-chip guard or the lock thresholds; each of those is guarding a documented money incident.');
  end if;

  select count(*) into v_avail_horses from profiles
    where is_horse = true
      and coalesce(horse_status, 'available') <> 'disabled';
  select coalesce(sum(t.max_players), 0), coalesce(sum(coalesce(s.n, 0)), 0),
         coalesce(sum(t.max_players) - sum(coalesce(s.n, 0)), 0)
    into v_seat_total, v_seat_filled, v_open_seats
    from tables t
    left join (select table_id, count(*) n from table_seats where left_at is null group by 1) s
      on s.table_id = t.id
   where t.tournament_id is null and t.status in ('running','waiting');
  if v_seat_total > 0 and v_open_seats::numeric / v_seat_total > 0.45 then
    v := v || jsonb_build_object(
      'severity','warn','category','logic','code','fleet_seat_starvation',
      'title', v_open_seats || ' of ' || v_seat_total || ' cash seats are empty (' ||
        round(100.0 * v_seat_filled / nullif(v_seat_total, 0), 1) || '% full)',
      'evidence', jsonb_build_object('open_seats', v_open_seats, 'seats', v_seat_total,
        'filled', v_seat_filled,
        'pct_full', round(100.0 * v_seat_filled / nullif(v_seat_total, 0), 1),
        'available_horses', v_avail_horses),
      'recommendation','Some open seats are deliberate (V14 table occupancy keeps the lobby lopsided and human-looking). This many means the seeder is not keeping up - check HorseFleetManager seeding cycles and the horse candidate pool.');
  end if;

  return v;
end
$$;


ALTER FUNCTION public.fn_audit_fleet_health(p_day date) OWNER TO postgres;

--
-- TOC entry 8552 (class 1255 OID 21864698)
-- Name: fn_audit_frequency_leaks(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_frequency_leaks(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  r record;
  v_studied int;
  v_play_days int;
  v_hands bigint;
  v_floored bigint;
  v_share numeric;
begin
  select count(distinct day) into v_play_days
    from horse_daily_play where day > p_day - 7 and day <= p_day;
  if v_play_days = 0 then
    return v;
  end if;

  -- How much of the window the bands are structurally blind to.
  select coalesce(sum(hands), 0),
         coalesce(sum(hands) filter (where floored), 0)
    into v_hands, v_floored
    from horse_daily_play
   where day > p_day - 7 and day <= p_day and format in ('cash', 'hu_cash');
  v_share := case when v_hands > 0 then round(v_floored::numeric / v_hands, 3) else 0 end;
  if v_floored > 0 then
    v := v || jsonb_build_object(
      'severity', case when v_share >= 0.40 then 'warn' else 'info' end,
      'category', 'logic', 'code', 'frequency_floored_share',
      'title', (v_share * 100)::int || '% of cash hands were played at a VPIP-floored table',
      'evidence', jsonb_build_object('hands', v_hands, 'floored_hands', v_floored, 'share', v_share),
      'recommendation', case when v_share >= 0.40
        then 'The winning-player bands now judge a minority of the fleet''s cash play, and horses may stop reaching the 1,000-hand gate. A floored table REQUIRES loose play (10.5, HorseLogic.vpipFloorMul), so its frequencies cannot be scored against the bands - the answer is fewer floored tables or a floored-table band of its own, not scoring them together.'
        else 'Floored tables require loose play and are excluded from the bands and from the self-tuner by design (see the_floor_is_not_a_leak). This line exists so the exclusion stays visible.' end);
  end if;

  select count(*) into v_studied from fn_horse_frequency_leaks(p_day - 7);
  if v_studied = 0 then
    v := v || jsonb_build_object('severity','info','category','logic','code','frequency_sample_thin',
      'title','No horse has 1,000 unfloored cash hands in the frequency window yet',
      'evidence', jsonb_build_object('play_days', v_play_days, 'floored_share', v_share),
      'recommendation','horse_daily_play is young, or too much of the play is floored. The frequency detectors report from the day a horse crosses 1,000 hands at tables where it was free to fold.');
    return v;
  end if;

  for r in
    select leak, count(*) as horses
      from fn_horse_frequency_leaks(p_day - 7), lateral unnest(leaks) leak
     group by leak
     order by 2 desc
  loop
    if r.horses::numeric / v_studied >= 0.33 then
      v := v || jsonb_build_object('severity','critical','category','gto','code','frequency_leak_fleetwide',
        'title', r.leak || ': ' || r.horses || ' of ' || v_studied || ' studied horses',
        'evidence', jsonb_build_object('leak', r.leak, 'horses', r.horses, 'studied', v_studied,
                                       'share', round(r.horses::numeric / v_studied, 3)),
        'recommendation','A third of the fleet shares this frequency, so it is a threshold in the brain rather than a personality. Find the bar: VPIP and PFR are HorsePreflop open/defend bars, fold-to-3-bet is the facing-raise bar, WWSF and AF are the postflop bluff and value gates. Do not tune dials against it - the dials are already trying and losing.');
    else
      v := v || jsonb_build_object('severity','info','category','gto','code','frequency_leak',
        'title', r.leak || ': ' || r.horses || ' of ' || v_studied || ' studied horses',
        'evidence', jsonb_build_object('leak', r.leak, 'horses', r.horses, 'studied', v_studied,
                                       'share', round(r.horses::numeric / v_studied, 3)),
        'recommendation','Individual horses outside a winning band. The self-tuner moves these dials nightly on the same bands; this line is how to see whether it is working.');
    end if;
  end loop;
  return v;
end $$;


ALTER FUNCTION public.fn_audit_frequency_leaks(p_day date) OWNER TO postgres;

--
-- TOC entry 6446 (class 1255 OID 24647912)
-- Name: fn_audit_gto_v31_certified(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_gto_v31_certified(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb := '[]'::jsonb;
  v_dataset public.gto_v31_datasets%ROWTYPE;
  v_latest jsonb;
BEGIN
  SELECT * INTO v_dataset FROM public.gto_v31_datasets WHERE state='active' LIMIT 1;
  IF NOT FOUND THEN
    SELECT jsonb_build_object(
      'dataset_key',d.dataset_key,'state',d.state,'quality_status',d.quality_status,
      'source_rows',d.source_rows,'train_source_rows',d.train_source_rows,
      'holdout_source_rows',d.holdout_source_rows,'invalid_rows',d.invalid_rows,
      'runtime_cells',(SELECT count(*) FROM public.gto_v31_runtime_cells c
        WHERE c.dataset_id=d.dataset_id),
      'declared_cells',jsonb_array_length(d.declared_coverage),
      'coverage',d.coverage,'heldout_metrics',d.heldout_metrics,
      'input_approval_status',b.approval_status,
      'evaluation_receipts',(SELECT count(*) FROM public.gto_v31_release_evaluations e
        WHERE e.dataset_id=d.dataset_id),
      'passing_release_receipts',(SELECT count(*) FROM public.gto_v31_release_evaluations e
        WHERE e.dataset_id=d.dataset_id AND e.verdict IN ('pass','win','tie')),
      'created_at',d.created_at,'sealed_at',d.sealed_at,'candidate_at',d.candidate_at
    ) INTO v_latest
      FROM public.gto_v31_datasets d
      JOIN public.gto_v31_input_bundles b ON b.input_bundle_id=d.input_bundle_id
     ORDER BY d.created_at DESC LIMIT 1;
    RETURN jsonb_build_array(jsonb_build_object(
      'severity','critical','category','gto','code','certified_v31_missing',
      'title','No certified V31 solver dataset is active',
      'evidence',jsonb_build_object('day',p_day,'latest_dataset',v_latest),
      'recommendation','Keep the legacy response inference labeled derived. Restore both solver hosts, generate sealed source rows, pass held-out, paired replay and league gates, then promote exactly one dataset.'
    ));
  END IF;
  IF v_dataset.invalid_rows <> 0 OR v_dataset.quality_status <> 'validated'
     OR v_dataset.dataset_checksum IS NULL OR v_dataset.source_artifact_checksum IS NULL THEN
    v_result := v_result || jsonb_build_object(
      'severity','critical','category','gto','code','certified_v31_invalid',
      'title','The active V31 dataset is not fully sealed',
      'evidence',jsonb_build_object('dataset',v_dataset.dataset_key,'invalid_rows',v_dataset.invalid_rows,'quality',v_dataset.quality_status),
      'recommendation','Retire the dataset and fall back. An active cell may never be served without complete source and dataset checksums.'
    );
  ELSE
    v_result := v_result || jsonb_build_object(
      'severity','info','category','gto','code','certified_v31_active',
      'title','Certified V31 dataset is active',
      'evidence',jsonb_build_object('dataset',v_dataset.dataset_key,'checksum',v_dataset.dataset_checksum,'coverage',v_dataset.coverage,'heldout',v_dataset.heldout_metrics),
      'recommendation','Continue daily decision-level agreement and worker-liveness checks.'
    );
  END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_audit_gto_v31_certified(p_day date) OWNER TO postgres;

--
-- TOC entry 4460 (class 1255 OID 18580106)
-- Name: fn_audit_layer_drift(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_layer_drift(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_findings jsonb := '[]'::jsonb;
  v_decides bigint;
  v_already text[];
  r record;
  /*
   * FALLBACK COUNTERS: SILENCE IS THE GOAL, BUT NOT ALWAYS THE CAUSE
   * Some counters name the DEGRADED path, not a layer: icm_legacy is the flat
   * heuristic used only when TournamentBrainContext arrives without stacks or
   * payouts (icm_real takes over the moment it has them), icm_warming is a
   * context that has not arrived yet, gto_depth_fallback and gto_miss_* are
   * the solver store having no cell for the spot. Zero fires on a big day is
   * the INTENDED direction for all of them, so their silence is info rather
   * than a warning - the six-day icm_legacy migration to icm_real reached
   * exactly zero on 2026-09-04 and this function used to report it as a layer
   * that "was executing and is not any more".
   *
   * What this function CANNOT tell (2026-09-12) is WHY one went quiet. The
   * primary genuinely covering every spot, and the whole lane being retired by
   * a deploy, produce an identical zero here. On 2026-09-11 all three
   * gto_miss_* counters read zero and were reported as "the primary path
   * covered every spot" while their primary, v31_gto_open, had itself been
   * removed from the source by PR #3849 and the certified store it was
   * repointed at was empty. So the title now states only what was counted and
   * the recommendation names both causes. A fallback that starts firing AGAIN
   * is caught by the ratio checks in fn_audit_data_receipts, not here.
   */
  v_fallback_exact constant text[] := array['icm_legacy', 'icm_warming', 'gto_depth_fallback'];
  v_fallback_prefix constant text[] := array['gto_miss_'];
  v_is_fallback boolean;
  /*
   * RETIRED AND OUTCOME COUNTERS ARE NOT LAYERS (2026-10-16)
   * On 2026-10-15 this loop raised about 110 layer_went_silent warns and none
   * was a layer that stopped executing. They were (a) reason codes RENAMED or
   * RETIRED with the code that fired them - the Phase 12 pack's pre-round-3
   * reasons (phase12_*reason_variant_*, *_preflop_*, *_split_*, *_low_only_*,
   * now round3_*), the earlier PLO packs' heads_up_big_blind_three_bet,
   * v44_declined_governor, and the packs' wall-clock *_reason_work_budget that
   * the 2026-10-16 policy bundle retires - and (b) reason, refusal and
   * failure counters (phase13_*reason_insufficient_joint_samples,
   * *_capacity_unavailable, *_unavailable_utility_*) and population counters
   * (phase8_objective_*), whose zero is a shift inside a lane or in the table
   * mix. Section 2 already stopped judging (b) as layers on 2026-10-05; the
   * lane itself is still judged by its own *_fired / *_eligible counters.
   *
   * (a) is read from horse_data_ledger: the engine registers a retired key as
   * kind 'receipt', cadence 'legacy_unused' (HorseDataLedger.ts,
   * RETIRED_RECEIPTS), and its silence is the retirement - one info line
   * lists them. (b) is classified by the same patterns as section 2 and
   * reported as one info line naming the counters, never one warn each.
   */
  v_retired_quiet text[] := '{}';
  v_outcome_quiet text[] := '{}';
  v_outcome_quiet_fires bigint := 0;
begin
  select coalesce(sum(fires), 0) into v_decides
    from horse_brain_telemetry where day = p_day and feature = 'decide';

  if v_decides < 1000 then
    return v_findings;
  end if;

  select coalesce(array_agg(f->'evidence'->>'feature'), '{}')
    into v_already
    from jsonb_array_elements(fn_audit_layer_silence(p_day)) f
   where f->>'code' = 'layer_silent';

  -- 1. A layer that was firing and stopped.
  for r in
    with hist as (
      select feature,
             count(*) filter (where day < p_day and fires > 0) as prior_days,
             coalesce(max(fires) filter (where day = p_day), 0) as today,
             coalesce(sum(fires) filter (where day < p_day), 0) as prior_fires,
             max(day) filter (where day < p_day and fires > 0) as last_fired
        from horse_brain_telemetry
       where day between p_day - 7 and p_day and feature <> 'decide'
       group by feature
    )
    select * from hist
     where prior_days >= 2 and today = 0 and not (feature = any(v_already))
     order by prior_fires desc
  loop
    if exists (
      select 1 from horse_data_ledger l
       where l.kind = 'receipt' and l.cadence = 'legacy_unused'
         and split_part(l.key, ':', 2) = r.feature
    ) then
      v_retired_quiet := v_retired_quiet || r.feature;
      continue;
    end if;
    v_is_fallback := r.feature = any(v_fallback_exact)
      or exists (select 1 from unnest(v_fallback_prefix) p where left(r.feature, length(p)) = p);
    if v_is_fallback then
      v_findings := v_findings || jsonb_build_object(
        'severity', 'info',
        'category', 'logic',
        'code', 'fallback_went_quiet',
        'title', 'Fallback ' || r.feature || ' fired ' || r.prior_fires ||
                 ' times in the previous week and ZERO on ' || p_day,
        'evidence', jsonb_build_object(
          'feature', r.feature,
          'prior_days_active', r.prior_days,
          'prior_fires', r.prior_fires,
          'last_fired', r.last_fired,
          'decide_fires', v_decides,
          'cause_not_determined', true
        ),
        'recommendation',
          'This counter names a degraded path (the legacy ICM heuristic, a ' ||
          'warming context, a solver-store miss), so zero is the intended ' ||
          'direction and this is not a warning. It does NOT by itself mean the ' ||
          'primary path covered every spot - this check cannot tell that from ' ||
          'the whole lane having been retired by a deploy, and the two look ' ||
          'identical here. Separate them in one step: if the fallback primary ' ||
          'is still firing today the coverage reading is the right one; if the ' ||
          'primary also read zero, or its feature name no longer appears in ' ||
          'server/src, the lane was retired and this counter should be deleted ' ||
          'with it. Measured 2026-09-11: all three gto_miss_* counters reached ' ||
          'zero because PR #3849 removed their primary v31_gto_open on ' ||
          '2026-09-08 and repointed the read path at a certified store that ' ||
          'holds no rows - which is the opposite of coverage. If it starts ' ||
          'firing again the receipts audit will say so.'
      );
      continue;
    end if;
    if r.feature ~ '^decide(_|$)'
      or r.feature ~ '^phase[0-9]+_(variant|format|objective)_'
      or r.feature ~ '_seen$'
      or r.feature ~ '(_reason_|unavailable|_skip_|_miss_|^v44_declined_)' then
      v_outcome_quiet := v_outcome_quiet || r.feature;
      v_outcome_quiet_fires := v_outcome_quiet_fires + r.prior_fires;
      continue;
    end if;
    v_findings := v_findings || jsonb_build_object(
      'severity', 'warn',
      'category', 'logic',
      'code', 'layer_went_silent',
      'title', 'Layer ' || r.feature || ' fired ' || r.prior_fires ||
               ' times in the previous week and ZERO on ' || p_day,
      'evidence', jsonb_build_object(
        'feature', r.feature,
        'prior_days_active', r.prior_days,
        'prior_fires', r.prior_fires,
        'last_fired', r.last_fired,
        'decide_fires', v_decides
      ),
      'recommendation',
        'This layer was executing and is not any more. Trace the gate: a flag ' ||
        'default, an upstream condition that can no longer be true, or a newer ' ||
        'layer returning before it. A retired layer is a valid answer - if the ' ||
        'feature name no longer exists in the source it is not a regression, ' ||
        'and this finding should be answered by deleting the counter.'
    );
  end loop;

  if cardinality(v_retired_quiet) > 0 then
    v_findings := v_findings || jsonb_build_object(
      'severity', 'info',
      'category', 'logic',
      'code', 'retired_counters_quiet',
      'title', cardinality(v_retired_quiet) || ' retired counter(s) fired in the previous week and ZERO on ' || p_day,
      'evidence', jsonb_build_object('features', to_jsonb(v_retired_quiet), 'decide_fires', v_decides),
      'recommendation',
        'Each is registered in horse_data_ledger as a retired receipt (HorseDataLedger.ts ' ||
        'RETIRED_RECEIPTS): the code that fired it was renamed or removed, so zero is the ' ||
        'retirement. If one fires again, the ledger row is wrong and should be removed.'
    );
  end if;
  if cardinality(v_outcome_quiet) > 0 then
    v_findings := v_findings || jsonb_build_object(
      'severity', 'info',
      'category', 'logic',
      'code', 'outcome_counters_quiet',
      'title', cardinality(v_outcome_quiet) || ' reason, refusal or population counter(s) fired in the previous week and ZERO on ' || p_day,
      'evidence', jsonb_build_object(
        'features', to_jsonb(v_outcome_quiet[1:60]),
        'feature_count', cardinality(v_outcome_quiet),
        'prior_fires', v_outcome_quiet_fires,
        'decide_fires', v_decides),
      'recommendation',
        'A reason, refusal or failure counter names WHY a lane took a path, and a population ' ||
        'counter is the table mix; zero is a shift inside a lane (fewer refusals is usually ' ||
        'good news) or a mix change, not a layer that stopped. The lanes are judged by their ' ||
        'own *_fired / *_eligible counters. A reason that was renamed or retired belongs in ' ||
        'horse_data_ledger as a retired receipt (HorseDataLedger.ts RETIRED_RECEIPTS).'
    );
  end if;

  -- 2. A layer that collapsed without going silent - REPORTED ON THE DAY OF
  --    THE STEP ONLY (2026-09-04), AND MEASURED AGAINST ITS OWN POPULATION
  --    (2026-09-28).
  --
  --    Until 2026-09-28 every layer's rate was fires per 1,000 FLEET decisions.
  --    That divides out fleet volume but not table MIX: when the fleet swung
  --    toward tournaments on 2026-09-27 (decide_tournament 1.72M -> 2.22M) every
  --    FLH, PKO, spin and cash counter "collapsed" at once - 113 warns - while
  --    phase12_flh_fired / phase13_variant_flh was 98.5%, higher than the day
  --    before. The same flood is what let a real V15 decay (v15_nut_status per
  --    Omaha decision 4.5% -> 3.3%) pass unflagged.
  --
  --    Each layer is now divided by the population it can fire on:
  --      * population counters (decide_*, phaseN_variant_/format_/objective_*,
  --        *_seen) are the mix itself, not layers - never judged here;
  --      * phaseN_<variant>_*       -> phaseN_variant_<variant> (else phase13's);
  --      * phase13_* and *_utility_cash, vpip_floor_* -> cash decisions
  --        (decide - decide_tournament; phase13_utility_cash equals it exactly);
  --      * phase13 tournament hand-offs, icm_*           -> decide_tournament;
  --      * bounty layers            -> PKO + mystery-bounty decisions;
  --      * spin layers              -> phase8_format_spin;
  --      * v15_*                    -> decide_omaha; v17_short_deck -> decide_short_deck;
  --      * v43_tempo_read, v16_reads_tell -> cash decisions (2026-10-05);
  --      * reason / refusal / miss counters and named fallbacks are a lane's
  --        outcome breakdown, never judged as layers (2026-10-05);
  --      * other phaseN_*           -> phaseN_seen; everything else -> decide.
  --    And a layer whose own population fell at least as far as it did is not
  --    collapsing, whatever its rate says. Replayed on 2026-09-27 this leaves
  --    10 of 113 warns.
  for r in
    with tel as (
      select day, feature, sum(fires)::numeric as fires
        from horse_brain_telemetry
       where day between p_day - 7 and p_day
       group by day, feature
    ),
    tot as (
      select day,
             max(fires) filter (where feature = 'decide') as decide,
             coalesce(max(fires) filter (where feature = 'decide_tournament'), 0) as tourn,
             coalesce(sum(fires) filter (where feature in ('phase7_objective_pko',
                                                           'phase7_objective_mystery_bounty')), 0) as bounty
        from tel
       group by day
      having max(fires) filter (where feature = 'decide') > 1000
    ),
    keyed as (
      select distinct feature,
        case
          when feature ~ '^decide(_|$)'
            or feature ~ '^phase[0-9]+_(variant|format|objective)_'
            or feature ~ '_seen$' then null
          -- 2026-10-05: REASON counters are a breakdown of a lane's outcomes,
          -- not layers. Every phaseN decision notes exactly one *_reason_*,
          -- the V44 second look notes one v44_declined_* per refusal, and
          -- *_unavailable* / *_skip_* / *_miss_* name why a path was not
          -- taken. A drop in one is a shift inside the lane (fewer refusals
          -- is usually good news); the lane itself is judged on its own
          -- *_fired / *_eligible / v44_second_look counters, which stay here.
          -- Replayed over 2026-09-28..10-05 this leaves 5 of 73 warns, every
          -- one of them a real layer. The fallbacks this function already
          -- names as intended-to-fall are excluded for the same reason.
          when feature ~ '(_reason_|unavailable|_skip_|_miss_|^v44_declined_)'
            or feature = any(v_fallback_exact) then null
          -- 2026-10-05: both reads need a river bettor with a showdown
          -- history, a cash-table read. Per fleet decide they swung 5x with
          -- the tournament share (v43 0.39-2.15 per 1,000); per cash decision
          -- they held (v43 1.86-3.29, v16_reads_tell 6.5-11.5), 09-24..10-05.
          when feature in ('v43_tempo_read', 'v16_reads_tell') then '#cash'
          when feature ~ '^phase13_(unavailable_utility_context|utility_phase7)' then 'decide_tournament'
          when feature ~ '(utility_cash$|^vpip_floor_)' then '#cash'
          when feature ilike '%bounty%' then '#bounty'
          when feature ~ '^icm_' then 'decide_tournament'
          when feature ~ 'spin' then 'phase8_format_spin'
          when feature ~ '^v15_' then 'decide_omaha'
          when feature = 'v17_short_deck' then 'decide_short_deck'
          when feature ~ '^phase[0-9]+_(flh|flo8|nlh|plo4|plo5|plo6|plo8|pineapple|short_deck)_' then
            regexp_replace(feature,
              '^(phase[0-9]+)_(flh|flo8|nlh|plo4|plo5|plo6|plo8|pineapple|short_deck)_.*$',
              '\1_variant_\2')
          when feature ~ '^phase13_' then '#cash'
          when feature ~ '^phase[0-9]+_' then regexp_replace(feature, '^(phase[0-9]+)_.*$', '\1_seen')
          else 'decide'
        end as den_key
        from tel
       where feature <> 'decide'
    ),
    den as (
      select k.feature, x.day, k.den_key,
             case k.den_key
               when '#cash'   then x.decide - x.tourn
               when '#bounty' then x.bounty
               when 'decide'  then x.decide
               else coalesce(
                 (select d.fires from tel d where d.day = x.day and d.feature = k.den_key),
                 case when k.den_key ~ '^phase[0-9]+_variant_' then
                   (select d.fires from tel d
                     where d.day = x.day
                       and d.feature = regexp_replace(k.den_key, '^phase[0-9]+_', 'phase13_'))
                 end)
             end as den
        from keyed k
        cross join tot x
       where k.den_key is not null
    ),
    rate as (
      select t.feature, t.day, t.fires, d.den, d.den_key,
             (t.fires * 1000) / d.den as rate
        from tel t
        join den d using (feature, day)
       where d.den > 1000
    ),
    cur  as (select feature, rate as cur_rate,  fires as cur_fires,  den as cur_den, den_key
               from rate where day = p_day),
    prev as (select feature, rate as prev_rate, fires as prev_fires, den as prev_den
               from rate where day = p_day - 1),
    base as (
      select feature,
             (percentile_cont(0.5) within group (order by rate))::numeric as med_rate,
             count(*) as n_days,
             sum(fires) as prior_fires
        from rate where day < p_day group by feature
    )
    select c.feature, c.cur_rate, c.cur_fires, c.cur_den, c.den_key,
           b.med_rate, b.n_days, b.prior_fires,
           p.prev_rate, p.prev_fires, p.prev_den
      from cur c
      join base b using (feature)
      left join prev p using (feature)
     where b.n_days >= 3
       and b.prior_fires >= 5000
       and b.med_rate > 0
       and c.cur_rate < b.med_rate * 0.40
       -- THE STEP MUST BE NEW. If yesterday was already below the line, this
       -- is the same step reported again - the median simply has not rolled
       -- past it yet. Reporting it daily for a week is what buried three real
       -- criticals under three false ones on 2026-09-01.
       and (p.prev_rate is null or p.prev_rate >= b.med_rate * 0.40)
       -- AND IT MUST ACTUALLY HAVE FALLEN. icm_legacy went 441 -> 641 fires
       -- and v16_unblocker 2,428 -> 2,512 on the day they were both reported
       -- as collapsing. A layer whose raw count rose is not collapsing today,
       -- whatever a median that straddles a deploy says.
       and (p.prev_fires is null or c.cur_fires < p.prev_fires)
       -- AND ITS OWN POPULATION MUST NOT HAVE FALLEN AS FAR (2026-09-28). A
       -- layer that kept pace with the tables it can fire on is not broken.
       and not (p.prev_den is not null and p.prev_fires > 0
                and c.cur_den / p.prev_den <= c.cur_fires / p.prev_fires)
     order by (1 - c.cur_rate / b.med_rate) desc
  loop
    v_findings := v_findings || jsonb_build_object(
      'severity', 'warn',
      'category', 'logic',
      'code', 'layer_fire_collapse',
      'title', 'Layer ' || r.feature || ' fell to ' ||
               round(100 * (1 - r.cur_rate / r.med_rate)) || '% below its usual rate',
      'evidence', jsonb_build_object(
        'feature', r.feature,
        'denominator', r.den_key,
        'denominator_today', r.cur_den,
        'denominator_yesterday', r.prev_den,
        'rate_per_1k_today', round(r.cur_rate, 2),
        'rate_per_1k_yesterday', round(coalesce(r.prev_rate, 0), 2),
        'rate_per_1k_median', round(r.med_rate, 2),
        'pct_drop', round(100 * (1 - r.cur_rate / r.med_rate)),
        'fires_today', r.cur_fires,
        'fires_yesterday', coalesce(r.prev_fires, 0),
        'prior_fires', r.prior_fires,
        'baseline_days', r.n_days,
        'step_day', p_day
      ),
      'recommendation',
        'Reported ONLY on the day the step happened, and measured per 1,000 of ' ||
        'the layer''s OWN population (the ''denominator'' in the evidence), so ' ||
        'a shift in table mix is already divided out. Still worth confirming ' ||
        'rather than assuming: a SUPERSEDED layer legitimately declining ' ||
        '(icm_legacy as icm_real took over), a newer layer that RETURNS EARLY ' ||
        'displacing the ones below it (V32 did exactly that to v16_reads_tell ' ||
        'and v16_unblocker on 2026-08-31), and - where the denominator is a ' ||
        'whole variant - a cash/tournament split inside that variant, which ' ||
        'telemetry cannot yet separate. The remaining explanation is a broken gate.'
    );
  end loop;

  return v_findings;
end
$_$;


ALTER FUNCTION public.fn_audit_layer_drift(p_day date) OWNER TO postgres;

--
-- TOC entry 4533 (class 1255 OID 16184911)
-- Name: fn_audit_layer_silence(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_layer_silence(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_findings jsonb := '[]'::jsonb;
  v_decides bigint;
  v_straddle_stage int;
  feat record;
begin
  select coalesce(sum(fires), 0) into v_decides
  from horse_brain_telemetry where day = p_day and feature = 'decide';

  if v_decides < 1000 then
    return jsonb_build_array(jsonb_build_object(
      'severity','critical','category','schema','code','telemetry_dark',
      'title','Brain telemetry recorded ' || v_decides || ' decisions for ' || p_day,
      'evidence', jsonb_build_object('decide_fires', v_decides),
      'recommendation','Either BrainTelemetryFlush is not running, the deploy predates telemetry, or the fleet was down. Nothing about layer health can be known for this day.'
    ));
  end if;

  -- THE STAGE FOR THE STRADDLE LANE (Ruling R2). Counted, not assumed: a
  -- layer with no stage cannot fire, and that is not the brain's fault.
  select count(*) into v_straddle_stage
  from tables
  where straddle_enabled
    and tournament_id is null
    and status in ('running','waiting');

  for feat in
    select * from (values
      ('preflop_v7',          'critical','the V7 preflop engine - every preflop decision should route through it'),
      ('v15_nut_status',      'critical','V15 Omaha nut awareness - fires on every made flush/straight in PLO'),
      ('banded_mc_omaha',     'critical','Omaha banded equity (the reservoir sampler feeds this path)'),
      ('banded_mc_nlh',       'critical','NLH banded equity'),
      ('icm_real',            'warn','V16 real ICM - tournament decisions with stacks+payouts in context'),
      ('v16_hu_overlay',      'warn','V16 heads-up overlay - any two-handed postflop pot'),
      ('v15_eq_capped',       'warn','V15 equity cap - dominated hands facing aggression'),
      ('v16_reads_cbet',      'warn','deep-read c-bet scaling - needs 10+ observed c-bet opportunities'),
      ('v16_sizecond_bigbet', 'warn','size-conditioned sampling - a 20bb+ bet on the newest street'),
      ('v16_reads_f3b',       'warn','deep-read fold-to-3-bet scaling of the bluff 3-bet mix'),
      ('v16_reads_tell',      'warn','big-river-bet sizing tell - WAS DEAD until the 2026-08-27 scale fix; zero here means the repair did not take'),
      ('v17_pos_behind',      'warn','V17 positional pressure - 0 or 2+ live players behind in a bluff-band spot'),
      ('v17_river_probe',     'warn','V17 river delayed probe - checked-through turn into a short-handed river'),
      ('v17_catch_block',     'warn','V17 call-side blocker - WAS DEAD until the 2026-08-27 scale fix; zero here means the repair did not take'),
      ('v17_short_deck',      'warn','V17 short-deck overlay - every short-deck postflop decision'),
      ('v18_straddle',        'warn','V18 straddle fix - straddled pots re-read as unopened (straddle tables only)'),
      ('v18_self_image',      'warn','V18 self-image - a horse''s own recent line moving its bluff volume'),
      ('v18_exploit_size',    'warn','V18 exploit-sized river value raises'),
      ('v19_overbet_polarity','warn','overbet polarity respect - unreachable before the scale fix'),
      ('v19_river_bigbet_cap','warn','V15 river big-bet equity cap - unreachable before the scale fix')
    ) as t(feature, severity, why)
  loop
    if not exists (
      select 1 from horse_brain_telemetry
      where day = p_day and feature = feat.feature and fires > 0
    ) then
      if feat.feature = 'v18_straddle' and v_straddle_stage = 0 then
        -- RETIRED, NOT SILENT. Ruling R2 took the stage away on purpose.
        v_findings := v_findings || jsonb_build_object(
          'severity','note','category','logic','code','layer_retired',
          'title','Deployed layer v18_straddle has no stage to fire on',
          'evidence', jsonb_build_object(
            'feature','v18_straddle','decide_fires', v_decides,
            'live_straddle_tables', 0,
            'ruling','R2 retired the straddle lane on cash games. fn_cash_apply_ruleset forces straddle_enabled = false on every cash table each tick; pinned by TheTablesOpenAndCloseThemselves.law.test.ts and LeaguePmAndStraddle.test.ts.'),
          'recommendation','Nothing to fix. The code is deployed and correct; the stage was removed deliberately. This turns back into a warn on its own the day a live cash table carries straddle_enabled again - do not "wire up" the flag to silence it, and do not delete the layer.'
        );
      elsif feat.feature = 'v17_river_probe' then
        -- DEFAULT OFF, NOT SILENT. HorseLogic gates the river probe on
        -- opts.v17RiverProbe === true; it has been opt-in since 2026-10-16.
        v_findings := v_findings || jsonb_build_object(
          'severity','note','category','logic','code','layer_default_off',
          'title','Opt-in layer v17_river_probe did not fire (default OFF since 2026-10-16)',
          'evidence', jsonb_build_object(
            'feature','v17_river_probe','decide_fires', v_decides,
            'flag','v17RiverProbe','default','off',
            'ruling','v17_river_probe measured -0.11 +/- 0.04 bb/100 pooled over the 8 runs to 2026-10-16 and -0.02 +/- 0.03 over all 32 runs since 2026-09-15: never positive; HorseLogic gates the probe on opts.v17RiverProbe === true.'),
          'recommendation','Nothing to fix. Zero fires is the default-off flag working. Do not turn the flag on to silence this; flip it only on a pooled-SIGNIFICANT positive league result.'
        );
      elsif feat.feature = 'v16_hu_overlay' then
        -- DEFAULT OFF, NOT SILENT. HorseLogic gates the overlay on
        -- opts.v16Hu === true; it has been opt-in since 2026-10-05.
        v_findings := v_findings || jsonb_build_object(
          'severity','note','category','logic','code','layer_default_off',
          'title','Opt-in layer v16_hu_overlay did not fire (default OFF since 2026-10-05)',
          'evidence', jsonb_build_object(
            'feature','v16_hu_overlay','decide_fires', v_decides,
            'flag','v16Hu','default','off',
            'ruling','hu_v16_overlay measured -0.26 +/- 0.10 bb/100 pooled over 31 nightly runs (z -2.6); HorseLogic gates the overlay on opts.v16Hu === true.'),
          'recommendation','Nothing to fix. Zero fires is the default-off flag working. Do not turn the flag on to silence this; flip it only on a pooled-SIGNIFICANT positive league result.'
        );
      else
        v_findings := v_findings || jsonb_build_object(
          'severity', feat.severity,'category','logic','code','layer_silent',
          'title','Deployed layer ' || feat.feature || ' fired ZERO times',
          'evidence', jsonb_build_object('feature', feat.feature,'decide_fires', v_decides,'expectation', feat.why),
          'recommendation','The code is deployed but never executes at live tables. Find the gate that turned it off - flag defaults, wiring, an upstream condition that can no longer be true, or a threshold on the wrong scale.'
        );
      end if;
    end if;
  end loop;

  return v_findings;
end $$;


ALTER FUNCTION public.fn_audit_layer_silence(p_day date) OWNER TO postgres;

