--
-- TOC entry 6801 (class 1255 OID 16458231)
-- Name: fn_audit_league_coverage(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_league_coverage(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_findings jsonb := '[]'::jsonb;
  v_recent int;
  v_stale text[];
  v_inert text[];
begin
  select count(distinct matchup) into v_recent
  from horse_league_results where run_date > p_day - 7;

  -- Seen in the last 45 days, absent from the last 7.
  with stale as (
    select distinct matchup m from horse_league_results where run_date > p_day - 45
    except
    select distinct matchup from horse_league_results where run_date > p_day - 7
  ),
  -- THE LAST THING EACH ONE MEASURED. An exactly-zero result with an
  -- exactly-zero standard error over a full matchup is not a dead heat: it is
  -- two arms that played byte-identical poker, which is the signature of a flag
  -- that no longer reaches a decision. Those get PULLED from the card on
  -- purpose (HorseLeague.ts carries the reasoning for v16_ratio_rescale,
  -- v18_exploit_size and v31_gto_suit_aware), so reporting them as a starved
  -- budget sends the next agent to tune MAX_RUN_MS for no reason.
  last_run as (
    select distinct on (r.matchup) r.matchup, r.bb100, r.stderr
      from horse_league_results r
      join stale on stale.m = r.matchup
     order by r.matchup, r.run_date desc
  )
  select coalesce(array_agg(matchup order by matchup) filter (where not (bb100 = 0 and stderr = 0)), '{}'),
         coalesce(array_agg(matchup order by matchup) filter (where bb100 = 0 and stderr = 0), '{}')
    into v_stale, v_inert
    from last_run;

  if array_length(v_stale, 1) > 0 then
    v_findings := v_findings || jsonb_build_object(
      'severity', 'warn',
      'category', 'gto',
      'code', 'league_card_starved',
      'title', array_length(v_stale, 1) || ' league matchup(s) unmeasured for 7+ days',
      'evidence', jsonb_build_object('stale_matchups', to_jsonb(v_stale), 'measured_last_7d', v_recent),
      'recommendation', 'The nightly budget is not reaching these matchups even with daily rotation. Their layers are unmeasured - reduce PAIRS_PER_MATCHUP, raise MAX_RUN_MS, or trim the card. A layer nobody measures is a layer nobody can defend. Each of these produced a REAL measurement before it stopped, so the budget is the thing to look at; matchups whose last result was 0.00 +/- 0.00 are reported separately as inert.'
    );
  end if;

  if array_length(v_inert, 1) > 0 then
    v_findings := v_findings || jsonb_build_object(
      'severity', 'note',
      'category', 'gto',
      'code', 'league_matchup_inert',
      'title', array_length(v_inert, 1) || ' league matchup(s) stopped running after measuring exactly nothing',
      'evidence', jsonb_build_object('inert_matchups', to_jsonb(v_inert), 'measured_last_7d', v_recent,
                                     'signature', '0.00 bb/100 with 0.00 stderr on the last recorded run'),
      'recommendation', 'Probably not a defect and definitely not a budget problem: the last run of each returned 0.00 bb/100 with 0.00 stderr, which over a full matchup means the two arms played byte-identical poker rather than dead even. A flag that no longer reaches a decision is the usual cause, and the fix is to take the matchup off the card - which is what HorseLeague.ts already did, with the reasoning, for v16_ratio_rescale (dead by precedence under V38), v18_exploit_size (impossible by construction: a mirror matchup cannot produce an exploitable opponent) and v31_gto_suit_aware (too rare to resolve at any affordable sample). Confirm the matchup is commented out on the card and leave it; if it is still ON the card and reporting 0.00 +/- 0.00, that is the defect - the flag is not reaching code.'
    );
  end if;

  if exists (
    select 1 from horse_league_results
    where run_date = (select max(run_date) from horse_league_results where run_date <= p_day + 1)
    group by run_date having count(*) < 6
  ) then
    v_findings := v_findings || jsonb_build_object(
      'severity', 'info',
      'category', 'gto',
      'code', 'league_run_partial',
      'title', 'The latest league run completed fewer than 6 matchups',
      'evidence', jsonb_build_object(
        'run_date', (select max(run_date) from horse_league_results where run_date <= p_day + 1),
        'matchups', (select count(*) from horse_league_results
                     where run_date = (select max(run_date) from horse_league_results where run_date <= p_day + 1))
      ),
      'recommendation', 'Expected with a large card and a fixed budget - the rotation covers the rest over following nights. Only a concern if the same matchups keep leading every night.'
    );
  end if;

  return v_findings;
end
$$;


ALTER FUNCTION public.fn_audit_league_coverage(p_day date) OWNER TO postgres;

--
-- TOC entry 6272 (class 1255 OID 16469078)
-- Name: fn_audit_league_pooled_findings(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_league_pooled_findings(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v jsonb := '[]'::jsonb; r record;
begin
  for r in select * from fn_league_pooled(p_day, 7) loop
    if r.verdict = 'SIGNIFICANT' and r.bb100 < 0 then
      if r.matchup in ('hu_v16_overlay', 'v16_hu_overlay_6max', 'v17_river_probe',
                       'shortdeck_v23', 'v32_facing_defense') then
        -- Arm A runs a DEFAULT-OFF flag ON (v16Hu since 2026-10-05,
        -- v17RiverProbe, v23ShortDeck and v32FacingDefense since 2026-10-16).
        -- A significant negative confirms the default; it is not a defect in
        -- the shipped brain.
        v := v || jsonb_build_object(
          'severity', 'info', 'category', 'gto', 'code', 'default_off_flag_confirmed_negative',
          'title', 'Pooled over ' || r.runs || ' run(s): ' || r.matchup || ' (default-off '
                   || case r.matchup
                        when 'v17_river_probe' then 'v17RiverProbe'
                        when 'shortdeck_v23' then 'v23ShortDeck'
                        when 'v32_facing_defense' then 'v32FacingDefense'
                        else 'v16Hu' end
                   || ' arm) is NEGATIVE at ' || r.bb100 || ' bb/100',
          'evidence', jsonb_build_object('matchup', r.matchup, 'bb100', r.bb100, 'stderr', r.stderr,
                                         'runs', r.runs, 'hands', r.hands, 'newest_run', r.newest_run),
          'recommendation', 'Hypothesis failed as expected; the flag stays default OFF. Nothing to ablate.'
        );
      else
        v := v || jsonb_build_object(
          'severity', 'critical', 'category', 'gto', 'code', 'league_layer_negative_pooled',
          'title', 'Pooled over ' || r.runs || ' run(s): ' || r.matchup || ' resolves NEGATIVE at ' || r.bb100 || ' bb/100',
          'evidence', jsonb_build_object('matchup', r.matchup, 'bb100', r.bb100, 'stderr', r.stderr,
                                         'runs', r.runs, 'hands', r.hands, 'newest_run', r.newest_run),
          'recommendation', 'This layer is measurably losing money across every night it was measured. Ablate it properly before tuning anything else - and check whether a recent change to it caused the flip.'
        );
      end if;
    end if;
    if r.verdict = 'SIGNIFICANT' and r.bb100 > 0 and r.matchup = 'v17_river_probe' then
      v := v || jsonb_build_object(
        'severity', 'info', 'category', 'gto', 'code', 'flagged_experiment_earned_its_keep',
        'title', 'v17_river_probe is pooled-SIGNIFICANT positive (' || r.bb100 || ' bb/100 over ' || r.runs || ' runs)',
        'evidence', jsonb_build_object('bb100', r.bb100, 'stderr', r.stderr, 'runs', r.runs),
        'recommendation', 'The default-OFF river probe has earned its default back. Ship a PR flipping v17RiverProbe to default ON, citing these runs.'
      );
    end if;
    if r.verdict = 'SIGNIFICANT' and r.bb100 > 0
       and r.matchup in ('shortdeck_v23', 'v32_facing_defense') then
      v := v || jsonb_build_object(
        'severity', 'info', 'category', 'gto', 'code', 'flagged_experiment_earned_its_keep',
        'title', r.matchup || ' is pooled-SIGNIFICANT positive (' || r.bb100 || ' bb/100 over ' || r.runs || ' runs)',
        'evidence', jsonb_build_object('bb100', r.bb100, 'stderr', r.stderr, 'runs', r.runs),
        'recommendation', 'The default-OFF layer has earned its default back. Ship a PR flipping '
                          || case when r.matchup = 'shortdeck_v23' then 'v23ShortDeck' else 'v32FacingDefense' end
                          || ' to default ON, citing these runs.'
      );
    end if;
    if r.verdict = 'SIGNIFICANT' and r.bb100 > 0 and r.matchup = 'v16_ratio_rescale' then
      v := v || jsonb_build_object(
        'severity', 'info', 'category', 'gto', 'code', 'flagged_experiment_earned_its_keep',
        'title', 'v16_ratio_rescale is pooled-SIGNIFICANT positive (' || r.bb100 || ' bb/100 over ' || r.runs || ' runs)',
        'evidence', jsonb_build_object('bb100', r.bb100, 'stderr', r.stderr, 'runs', r.runs),
        'recommendation', 'The default-OFF experiment has earned its default. Ship a PR flipping v16Ratio to default ON, citing these runs.'
      );
    end if;
  end loop;
  return v;
end $$;


ALTER FUNCTION public.fn_audit_league_pooled_findings(p_day date) OWNER TO postgres;

--
-- TOC entry 6557 (class 1255 OID 18543117)
-- Name: fn_audit_nightly_job_health(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_nightly_job_health(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_findings jsonb := '[]'::jsonb;
  r record;
  v_rows bigint;
  v_last_league date;
  v_gap int;
  v_matchups bigint;
  v_league_ran boolean;
begin
  for r in
    select j.job, j.claimed_at, j.claimed_by
      from horse_job_runs j
     where j.run_date = p_day
       and j.job in ('league', 'league_pm', 'self_tuner')
     order by j.job
  loop
    -- Execution receipts began on 2026-09-14. Earlier nights keep their
    -- historical liveness check; old audit rows are not retroactive receipts.
    if r.job = 'self_tuner' and p_day >= date '2026-09-14' then
      if not exists(select 1 from public.horse_tuner_study_completions c where c.run_date=p_day) then
        select count(*) into v_rows from public.horse_self_tune_log where run_date=p_day;
        v_findings := v_findings || jsonb_build_object(
          'severity','critical','category','schema','code','nightly_job_incomplete',
          'title','self_tuner claimed ' || p_day || ' without completing its study',
          'evidence',jsonb_build_object('job',r.job,'run_date',p_day,
            'claimed_at',r.claimed_at,'claimed_by',r.claimed_by,
            'individual_audit_rows',v_rows,'completion_receipts',0),
          'recommendation','Resume unfinished horses using their atomic daily receipts. Individual audit rows do not certify the captured eligible cohort.');
      end if;
      continue;
    end if;
    if r.job in ('league', 'league_pm') then
      -- A refusal row is not evidence the card ran: it is written before the
      -- first hand is dealt and would mask a night that produced nothing.
      select count(*) into v_rows
        from horse_league_results
       where run_date = p_day and status <> 'refused';
    else
      select count(*) into v_rows from horse_self_tune_log where run_date = p_day;
    end if;

    if v_rows = 0 then
      v_findings := v_findings || jsonb_build_object(
        'severity', 'critical',
        'category', 'schema',
        'code', 'nightly_job_lost',
        'title', r.job || ' claimed ' || p_day || ' and produced nothing',
        'evidence', jsonb_build_object(
          'job', r.job,
          'run_date', p_day,
          'claimed_at', r.claimed_at,
          'claimed_by', r.claimed_by,
          'evidence_rows', 0
        ),
        'recommendation',
          'The job took the lock and died before writing a row - an engine ' ||
          'restart inside the run is the usual cause, and server/** merges ' ||
          'deploy automatically. Check the container logs for that window. ' ||
          'Any conclusion drawn from this job for this date is unsupported: ' ||
          'do not quote it.'
      );
    end if;
  end loop;

  select max(run_date) into v_last_league from horse_league_results where status <> 'refused';
  if v_last_league is null then
    v_findings := v_findings || jsonb_build_object(
      'severity', 'critical',
      'category', 'schema',
      'code', 'league_card_empty',
      'title', 'horse_league_results has no rows at all',
      'evidence', jsonb_build_object('as_of', p_day),
      'recommendation',
        'No layer has ever been measured. Every strategy verdict is opinion ' ||
        'until the league runs.'
    );
  else
    v_gap := p_day - v_last_league;
    if v_gap >= 1 then
      select count(*) into v_matchups
        from horse_league_results where run_date = v_last_league and status <> 'refused';
      v_findings := v_findings || jsonb_build_object(
        'severity', case when v_gap >= 2 then 'critical' else 'warn' end,
        'category', 'schema',
        'code', 'league_card_stale',
        'title', 'The newest league measurement is ' || v_gap || ' day(s) before ' || p_day,
        'evidence', jsonb_build_object(
          'last_run_date', v_last_league,
          'days_stale', v_gap,
          'matchups_in_last_run', v_matchups
        ),
        'recommendation',
          'Layer verdicts are being read off a card this many days old. ' ||
          'Significance rules assume independent runs, so a single surviving ' ||
          'run cannot satisfy any three-run promotion gate. Fix the runner ' ||
          'before tuning anything on this card. (v16_ratio_rescale is no ' ||
          'longer an example of such a gate: it left the card on 2026-09-05 ' ||
          'and now reports as status = refused. Read that row - it carries ' ||
          'the reason and what would change the verdict.)'
      );
    end if;
  end if;

  -- An INERT matchup dealt real hands and learned nothing: a harness fault.
  for r in
    select matchup, hands, refusal_reason
      from horse_league_results
     where run_date = p_day
       and hands > 0
       and (status = 'inert' or (bb100 = 0 and stderr = 0))
     order by matchup
  loop
    v_findings := v_findings || jsonb_build_object(
      'severity', 'warn',
      'category', 'logic',
      'code', 'league_matchup_inert',
      'title', r.matchup || ' returned exactly zero over ' || r.hands || ' hands',
      'evidence', jsonb_build_object('matchup', r.matchup, 'hands', r.hands,
                                     'reason', r.refusal_reason),
      'recommendation',
        'Both arms played identically. Confirm the b-side flag still gates ' ||
        'live code; if it does not, the layer is unreachable or the flag is ' ||
        'dead and the matchup should be retired or repointed. Retire it into ' ||
        'UNMEASURABLE_MATCHUPS so it keeps reporting - never by deleting the ' ||
        'entry, which makes it invisible to this finding.'
    );
  end loop;

  -- A REFUSED matchup dealt nothing on purpose. This is the state that used
  -- to be unrepresentable, and therefore unarguable.
  for r in
    select matchup, refusal_reason
      from horse_league_results
     where run_date = p_day and status = 'refused'
     order by matchup
  loop
    v_findings := v_findings || jsonb_build_object(
      'severity', 'info',
      'category', 'gto',
      'code', 'league_matchup_refused',
      'title', r.matchup || ' is deliberately not measured',
      'evidence', jsonb_build_object('matchup', r.matchup, 'reason', r.refusal_reason),
      'recommendation',
        'Not a gap in the card - a recorded judgement that self-play cannot ' ||
        'answer this question at a sample the league can afford. The reason ' ||
        'states what would change that. Decide FROM this row; the absence of ' ||
        'a measurement is not evidence either way, and a flag that no longer ' ||
        'reaches code cannot satisfy a promotion gate however long it waits.'
    );
  end loop;

  -- Once refused, it must keep saying so. Silence here is the original bug.
  select exists(select 1 from horse_league_results where run_date = p_day)
    into v_league_ran;
  if v_league_ran then
    for r in
      select distinct h.matchup
        from horse_league_results h
       where h.status = 'refused'
         and h.run_date >= p_day - 7
         and h.run_date < p_day
         and not exists (select 1 from horse_league_results t
                          where t.matchup = h.matchup and t.run_date = p_day)
       order by 1
    loop
      v_findings := v_findings || jsonb_build_object(
        'severity', 'warn',
        'category', 'schema',
        'code', 'league_refusal_went_silent',
        'title', r.matchup || ' was refused within the last week and said nothing on ' || p_day,
        'evidence', jsonb_build_object('matchup', r.matchup, 'run_date', p_day),
        'recommendation',
          'The league ran but wrote no refusal row for this matchup, so it is ' ||
          'invisible again - the exact failure the refusal rows exist to ' ||
          'prevent. Either it went back on the card (then it should have a ' ||
          'measurement) or writeRefusedMatchups stopped running.'
      );
    end loop;
  end if;

  return v_findings;
end
$$;


ALTER FUNCTION public.fn_audit_nightly_job_health(p_day date) OWNER TO postgres;

--
-- TOC entry 3533 (class 1255 OID 16474862)
-- Name: fn_audit_overlays(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_overlays(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v jsonb := '[]'::jsonb; r record; total numeric := 0; n int := 0;
begin
  for r in
    select t.name, t.guaranteed_prize gtd, t.buy_in_amount bi,
           e.entries cur,
           (t.guaranteed_prize - greatest(e.entries * t.buy_in_amount, 0)) short
    from tournaments t
    cross join lateral (
      select count(*)::int as entries
      from public.tournament_players p
      where p.tournament_id = t.id
    ) e
    where t.guaranteed_prize > 0 and t.buy_in_amount > 0
      and t.started_at >= p_day and t.started_at < p_day + 1
      and (t.guaranteed_prize - greatest(e.entries * t.buy_in_amount, 0)) > 0
    order by 5 desc limit 10
  loop
    total := total + r.short; n := n + 1;
    v := v || jsonb_build_object(
      'severity', case when r.short >= 200 then 'critical' else 'warn' end,
      'category', 'logic', 'code', 'tournament_overlay',
      'title', r.name || ' started with a ' || round(r.short, 2) || ' overlay',
      'evidence', jsonb_build_object('guarantee', r.gtd, 'buy_in', r.bi,
                                     'entries', r.cur, 'shortfall', r.short),
      'recommendation', 'The overlay guard did not fill this event before it started. Check HorseOverlayGuard logs for that window: it may have been starved of eligible horses (events/both lane, under the four-table cap) or the event may have started sooner than the guard cycle.'
    );
  end loop;
  if n > 0 then
    v := v || jsonb_build_object(
      'severity', 'info', 'category', 'logic', 'code', 'overlay_total',
      'title', 'Club covered ' || round(total, 2) || ' in overlays across ' || n || ' event(s)',
      'evidence', jsonb_build_object('events', n, 'total_overlay', round(total, 2)),
      'recommendation', 'Total is the money the guarantee cost beyond what entries funded.'
    );
  end if;
  return v;
end $$;


ALTER FUNCTION public.fn_audit_overlays(p_day date) OWNER TO postgres;

--
-- TOC entry 7495 (class 1255 OID 13095794)
-- Name: fn_audit_privileged_grants(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_privileged_grants() RETURNS TABLE(severity text, function_name text, arguments text, security_definer boolean, remedy text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    CASE
      WHEN pg_get_function_result(p.oid) = 'trigger' THEN 'LOW'
      WHEN p.prosecdef THEN 'CRITICAL'
      ELSE 'MEDIUM'
    END::text AS severity,
    p.proname::text,
    pg_get_function_identity_arguments(p.oid)::text,
    p.prosecdef,
    CASE
      WHEN pg_get_function_result(p.oid) = 'trigger'
        THEN 'Trigger function; anon cannot meaningfully invoke it. Tidy up when convenient.'
      WHEN p.prosecdef
        THEN 'SECURITY DEFINER bypasses RLS and anon can call it. REVOKE EXECUTE ... FROM PUBLIC, anon NOW.'
      ELSE 'anon can call it; RLS on the underlying tables is the only thing stopping a write. REVOKE for defence in depth.'
    END::text
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public'
    AND p.prokind = 'f'
    AND has_function_privilege('anon', p.oid, 'EXECUTE')
    AND p.proname !~ '^st_'
    AND p.proname <> 'fn_audit_privileged_grants'
    AND (
         p.proname ~* '(mint_|_mint|chip|wallet|promo|cashout|diamond|rake|bounty|settle|payout|clawback|purchase|treasury|jackpot|bbj)'
      OR p.proname ~* '^(credit|debit|transfer|distribute|deduct|atomic|admin)_'
      OR p.proname ~* '(promote_member|transfer_club_ownership|remove_player)'
    )
  ORDER BY
    CASE WHEN pg_get_function_result(p.oid)='trigger' THEN 3
         WHEN p.prosecdef THEN 1 ELSE 2 END,
    p.proname;
$$;


ALTER FUNCTION public.fn_audit_privileged_grants() OWNER TO postgres;

