COMMENT ON FUNCTION public.fn_audit_privileged_grants() IS 'INVARIANT: money/privileged functions must not be anon-executable. CRITICAL (SECURITY DEFINER + anon) must always be 0 -- gate CI on it. MEDIUM = anon but RLS-protected. LOW = trigger functions. New functions inherit EXECUTE for PUBLIC, so every privileged CREATE FUNCTION needs a paired REVOKE ... FROM PUBLIC, anon in the SAME migration.';


--
-- TOC entry 5271 (class 1255 OID 18546487)
-- Name: fn_audit_river_aggression_ev(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_river_aggression_ev(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  r record;
  v_ranked int := 0;
begin
  for r in
    select * from fn_horse_tag_ev(p_day - 6)
     where mirrored and hands >= 200
     order by bb_per_hand asc
  loop
    v_ranked := v_ranked + 1;
    if r.bb_per_hand < 0 then
      v := v || jsonb_build_object('severity', case when r.net_bb < -20000 then 'warn' else 'info' end,
        'category','gto','code','tag_ev_negative',
        'title', r.situation || ' is losing ' || r.bb_per_hand || 'bb per hand over ' || r.hands || ' hands',
        'evidence', jsonb_build_object('situation', r.situation, 'hands', r.hands,
                                       'won_hands', r.won_hands, 'net_bb', r.net_bb,
                                       'bb_per_hand', r.bb_per_hand, 'win_rate', r.win_rate),
        'recommendation','Both outcomes of this situation are counted, so this is EV and not a damage total. A negative number here is a real leak and a cap is worth testing: flag it, add a league matchup, and do not claim an improvement without significance.');
    end if;
  end loop;

  if v_ranked = 0 then
    v := v || jsonb_build_object('severity','info','category','schema','code','tag_ev_unavailable',
      'title','No mirrored situation has 200 hands in the seven-day window',
      'evidence', jsonb_build_object('day', p_day),
      'recommendation','horse_review_rollup.leak_net_bb is written by fn_hhr_rollup_add on every review insert. If counts exist and nets do not, the rollup is running a build from before 2026-09-06.');
  else
    v := v || jsonb_build_object('severity','info','category','gto','code','tag_ev_ranked',
      'title', v_ranked || ' mirrored situations ranked by EV over seven days',
      'evidence', jsonb_build_object('situations', v_ranked, 'since', p_day - 6),
      'recommendation','Ranked by bb per hand across BOTH outcomes, which is the only honest ranking: a loss-only total ranks situations by how often they occur in big pots. The fold family has no winning mirror and is deliberately excluded - a folded hand never wins, so its total is the fold, not a leak.');
  end if;

  return v;
end $$;


ALTER FUNCTION public.fn_audit_river_aggression_ev(p_day date) OWNER TO postgres;

--
-- TOC entry 4720 (class 1255 OID 21809839)
-- Name: fn_audit_seat_clock(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_seat_clock(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  v_seated int;
  v_touched int;
  v_decides bigint;
begin
  select count(*) filter (where state = 'seated'),
         count(*) filter (where state = 'seated' and last_action_at >= now() - interval '2 hours')
    into v_seated, v_touched
    from ca_horse_fleet_state;
  select coalesce(sum(fires), 0) into v_decides
    from horse_brain_telemetry where day = p_day and feature = 'decide';
  if v_seated >= 50 and v_decides >= 100000 and v_touched = 0 then
    v := v || jsonb_build_object('severity','critical','category','schema','code','seat_clock_dead',
      'title', v_seated || ' seated horses and none has a last_action_at in the last two hours, against ' || v_decides || ' decisions on ' || p_day,
      'evidence', jsonb_build_object('seated', v_seated, 'touched_2h', v_touched, 'decides', v_decides),
      'recommendation','fn_ca_fleet_seat_touch is not being called (HorseHandReview.touchHorseSeats, HORSE_SEAT_TOUCH_ENABLED) or the fleet upsert is overwriting it again (fn_ca_fleet_state_upsert must coalesce last_action_at). The panel cannot tell a playing horse from a stuck one without it.');
  end if;

  -- 2026-09-06: a breather that never ends holds a seat the horse will never
  -- act from, which is the same question this step exists to ask.
  v := v || fn_audit_breather_returns(p_day);
  return v;
end $$;


ALTER FUNCTION public.fn_audit_seat_clock(p_day date) OWNER TO postgres;

--
-- TOC entry 9265 (class 1255 OID 21869206)
-- Name: fn_audit_solver_agreement(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_solver_agreement(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v jsonb:='[]'::jsonb;
  r record;
  prev numeric;
  v_details integer;
  v_checksum text;
  v_chart_seen boolean:=false;
  v_v31_seen boolean:=false;
  v_v31_required boolean;
  v_code text;
  v_scope text;
  v_active_dataset_id uuid;
  v_active_dataset_checksum text;
  v_v31_contexts integer;
  v_v31_context_min integer;
  v_v31_context_max integer;
  v_v31_dataset_count integer;
  v_v31_dataset_id text;
  v_v31_dataset_checksum text;
BEGIN
  SELECT dataset_id,dataset_checksum INTO v_active_dataset_id,v_active_dataset_checksum
    FROM public.gto_v31_datasets WHERE state='active' LIMIT 1;
  v_v31_required:=FOUND;
  FOR r IN
    SELECT * FROM public.horse_solver_agreement
     WHERE reference IN ('gto_charts','gto_v31_certified')
       AND run_date=p_day
     ORDER BY reference
  LOOP
    v_v31_contexts:=NULL;
    v_v31_dataset_count:=NULL;
    v_v31_dataset_id:=NULL;
    v_v31_dataset_checksum:=NULL;
    v_v31_context_min:=NULL;
    v_v31_context_max:=NULL;
    v_chart_seen:=v_chart_seen OR r.reference='gto_charts';
    v_v31_seen:=v_v31_seen OR r.reference='gto_v31_certified';
    IF r.reference='gto_charts' THEN
      SELECT count(*),CASE WHEN count(*)>0 THEN public.fn_gto_v31_json_checksum(jsonb_agg(
          to_jsonb(d)-ARRAY['run_date','reference','created_at']::text[] ORDER BY d.state_key)) END
        INTO v_details,v_checksum FROM public.horse_solver_agreement_decisions d
       WHERE d.run_date=r.run_date AND d.reference=r.reference;
      v_scope:='preflop chart agreement';
    ELSE
      SELECT count(*),CASE WHEN count(*)>0 THEN public.fn_gto_v31_json_checksum(jsonb_agg(
          to_jsonb(d)-ARRAY['run_date','reference','created_at']::text[] ORDER BY d.state_key)) END,
          count(DISTINCT d.game_family||'|'||d.utility_context),
          count(DISTINCT concat_ws('|',d.source_seal->>'dataset_id',
            d.source_seal->>'dataset_checksum')),
          min(d.source_seal->>'dataset_id'),min(d.source_seal->>'dataset_checksum')
        INTO v_details,v_checksum,v_v31_contexts,v_v31_dataset_count,
          v_v31_dataset_id,v_v31_dataset_checksum
        FROM public.horse_solver_agreement_v31_decisions d
       WHERE d.run_date=r.run_date AND d.reference=r.reference;
      SELECT min(context_rows),max(context_rows)
        INTO v_v31_context_min,v_v31_context_max
        FROM (
          SELECT count(*)::integer AS context_rows
            FROM public.horse_solver_agreement_v31_decisions d
           WHERE d.run_date=r.run_date AND d.reference=r.reference
           GROUP BY d.game_family,d.utility_context
        ) context_counts;
      v_scope:='certified V31 execution agreement';
    END IF;
    SELECT agreement INTO prev FROM public.horse_solver_agreement
     WHERE reference=r.reference AND run_date<r.run_date ORDER BY run_date DESC LIMIT 1;

    IF r.reference='gto_v31_certified' AND v_v31_required AND
       (v_v31_dataset_count<>1
        OR v_v31_dataset_id IS DISTINCT FROM v_active_dataset_id::text
        OR v_v31_dataset_checksum IS DISTINCT FROM v_active_dataset_checksum) THEN
      v:=v||jsonb_build_object('severity','critical','category','gto',
        'code','solver_agreement_v31_stale_dataset',
        'title','Certified V31 agreement is not bound to the current active dataset',
        'evidence',jsonb_build_object('run_date',r.run_date,
          'receipt_dataset_id',v_v31_dataset_id,
          'receipt_dataset_checksum',v_v31_dataset_checksum,
          'receipt_dataset_count',v_v31_dataset_count,
          'active_dataset_id',v_active_dataset_id,
          'active_dataset_checksum',v_active_dataset_checksum),
        'recommendation','Re-run HorseLeague.agreement.v31 against the currently active in-memory corpus; a retired corpus cannot prove current execution.');
    END IF;
    IF r.reference='gto_v31_certified' AND COALESCE(v_v31_contexts,0)<>9 THEN
      v:=v||jsonb_build_object('severity','critical','category','gto',
        'code','solver_agreement_v31_missing_scenarios',
        'title','Certified V31 agreement did not execute all nine required family and utility contexts',
        'evidence',jsonb_build_object('run_date',r.run_date,
          'scenario_contexts',COALESCE(v_v31_contexts,0),'required_contexts',9),
        'recommendation','Inspect the active-cell gates for the missing scenario and reject partial V31 agreement evidence.');
    END IF;
    IF r.reference='gto_v31_certified' AND v_v31_contexts=9
       AND v_v31_context_max-v_v31_context_min>1 THEN
      v:=v||jsonb_build_object('severity','critical','category','gto',
        'code','solver_agreement_v31_imbalanced_scenarios',
        'title','Certified V31 agreement over-sampled some required contexts',
        'evidence',jsonb_build_object('run_date',r.run_date,
          'scenario_contexts',v_v31_contexts,'minimum_context_spots',v_v31_context_min,
          'maximum_context_spots',v_v31_context_max),
        'recommendation','Re-run the balanced nine-context V31 probe; no context may exceed another by more than one spot.');
    END IF;

    IF r.eligible_spots<>r.reconciled_spots OR r.reconciled_spots<>v_details
       OR r.decision_checksum IS NULL OR r.decision_checksum IS DISTINCT FROM v_checksum THEN
      v:=v||jsonb_build_object('severity','critical','category','gto',
        'code','solver_agreement_unreconciled','title',v_scope||' decisions do not reconcile',
        'evidence',jsonb_build_object('run_date',r.run_date,'reference',r.reference,
          'eligible',r.eligible_spots,'reconciled',r.reconciled_spots,
          'decision_rows',v_details,'checksum',r.decision_checksum),
        'recommendation','Re-run the exact agreement probe through fn_horse_solver_agreement_add; never use a summary-only score as release evidence.');
    ELSIF r.spots<50 THEN
      v_code:=CASE WHEN r.reference='gto_v31_certified' THEN 'solver_agreement_v31_thin' ELSE 'solver_agreement_thin' END;
      v:=v||jsonb_build_object('severity','warn','category','gto','code',v_code,
        'title',v_scope||' probed only '||r.spots||' spots on '||r.run_date,
        'evidence',jsonb_build_object('spots',r.spots,'reference',r.reference),
        'recommendation','Inspect the immutable decision receipts and active in-memory reference coverage; thin coverage is not evidence of improvement.');
    ELSIF prev IS NOT NULL AND r.agreement<prev-0.03 THEN
      v_code:=CASE WHEN r.reference='gto_v31_certified' THEN 'solver_agreement_v31_dropped' ELSE 'solver_agreement_dropped' END;
      v:=v||jsonb_build_object('severity','critical','category','gto','code',v_code,
        'title',v_scope||' fell to '||round(r.agreement,3)||' from '||round(prev,3),
        'evidence',jsonb_build_object('agreement',r.agreement,'previous',prev,
          'spots',r.spots,'pure_misses',r.pure_misses,'reference',r.reference,
          'checksum',r.decision_checksum),
        'recommendation','Diff the engine deploy and inspect the persisted pure-miss and execution-mismatch decisions before changing strategy.');
    ELSE
      v_code:=CASE WHEN r.reference='gto_v31_certified' THEN 'solver_agreement_v31' ELSE 'solver_agreement' END;
      v:=v||jsonb_build_object('severity','info','category','gto','code',v_code,
        'title',v_scope||' '||round(r.agreement,3)||' over '||r.spots||' reconciled spots',
        'evidence',jsonb_build_object('agreement',r.agreement,'previous',prev,
          'spots',r.spots,'pure_misses',r.pure_misses,'reference',r.reference,
          'action_regret_bb',r.action_regret_bb,
          'regret_eligible_spots',r.regret_eligible_spots,'checksum',r.decision_checksum),
        'recommendation','Use immutable decision receipts for diagnosis. Agreement is execution/reference evidence, not exploitability.');
    END IF;
  END LOOP;
  IF NOT v_chart_seen THEN
    v:=v||jsonb_build_object('severity','critical','category','gto',
      'code','solver_agreement_missing','title','No chart solver agreement row for the target day',
      'evidence',jsonb_build_object('day',p_day,'reference','gto_charts'),
      'recommendation','HorseLeague writes this before the matchup card. Check HorseLeague.agreement and the chart loader.');
  END IF;
  IF v_v31_required AND NOT v_v31_seen THEN
    v:=v||jsonb_build_object('severity','critical','category','gto',
      'code','solver_agreement_v31_missing',
      'title','An active certified V31 corpus has no agreement receipt for the target day',
      'evidence',jsonb_build_object('day',p_day,'reference','gto_v31_certified'),
      'recommendation','Check HorseLeague.agreement.v31 and the active-cell loader; do not infer V31 execution from chart agreement.');
  END IF;
  RETURN v;
END;
$$;


ALTER FUNCTION public.fn_audit_solver_agreement(p_day date) OWNER TO postgres;

--
-- TOC entry 3771 (class 1255 OID 24648381)
-- Name: fn_audit_solver_pipeline_liveness(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_solver_pipeline_liveness(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_findings jsonb := '[]'::jsonb;
  v_machine text;
  v_worker public.solver_worker_liveness%ROWTYPE;
  v_compact public.solver_compact_liveness%ROWTYPE;
  v_peer public.solver_worker_liveness%ROWTYPE;
  v_progress bigint;
  v_workers_healthy boolean := true;
  v_provenance_matches boolean := true;
BEGIN
  -- 2026-09-27 (CLAUDE.md 10.86 rule 1): a pipeline that was never commissioned
  -- is not a pipeline that stopped. Both heartbeat tables are append-only and
  -- nothing prunes them, so empty means never -- not "not lately". While no
  -- input bundle has ever been approved and neither table has ever held a row,
  -- there is no process to restart and no host to reach, and the three critical
  -- "missing" findings below would name an outage that has not happened.
  IF NOT EXISTS (SELECT 1 FROM public.gto_v31_input_bundles
                  WHERE approval_status = 'approved')
     AND NOT EXISTS (SELECT 1 FROM public.solver_worker_heartbeats)
     AND NOT EXISTS (SELECT 1 FROM public.solver_compact_heartbeats) THEN
    RETURN jsonb_build_array(jsonb_build_object(
      'severity','note','category','gto',
      'code','solver_pipeline_not_commissioned',
      'title','Certified V31 solver pipeline has never been commissioned - no approved input bundle, and M1, M2 and the compactor have never sent one heartbeat',
      'evidence',jsonb_build_object(
        'day',p_day,
        'approved_input_bundles',0,
        'worker_heartbeats_ever',0,
        'compact_heartbeats_ever',0,
        'v31_datasets',(SELECT count(*) FROM public.gto_v31_datasets),
        'v31_source_artifacts',(SELECT count(*) FROM public.gto_v31_source_artifacts),
        'v31_runtime_cells',(SELECT count(*) FROM public.gto_v31_runtime_cells),
        'heartbeat_tables_are_append_only',true,
        'human_gate','ca_gto_v31_approve_input_bundle'),
      'recommendation',
        'This is a standing fact, not an outage, and no software change can clear '||
        'it. The pipeline has produced nothing because it was never started, and '||
        'it cannot be started from this repository. Phase 4 needs, in order: '||
        '(1) a horse administrator reviews one immutable NLH input package and '||
        'approves it through ca_gto_v31_approve_input_bundle; (2) a licensed '||
        'PioSOLVER console executable installed on two genuinely independent '||
        'Windows hosts designated M1 and M2; (3) three independently generated '||
        '32-byte HMAC secrets installed by name - '||
        'HORSE_SOLVER_V31_M1_HMAC_SECRET, HORSE_SOLVER_V31_M2_HMAC_SECRET and '||
        'HORSE_SOLVER_V31_COMPACTOR_HMAC_SECRET on the World Hub gateway, and '||
        'each host its own value as HORSE_SOLVER_V31_HMAC_SECRET. The exact '||
        'sequence is World Hub '||
        '.agent/handoffs/2026-09-09-horse-v31-licensed-corpus-activation.md. '||
        'Until then V30 remains the live policy path and is unaffected: the '||
        'certified store being empty is the fail-closed design working, not a '||
        'regression. The moment a bundle is approved or any heartbeat arrives, '||
        'this check reverts to reporting missing, stale, failed and stalled '||
        'hosts as critical.'));
  END IF;

  -- 2026-10-16: A PARKED PIPELINE IS ONE FINDING, NOT THREE. When both hosts
  -- report worker_state 'completed' (they finished the run they were given),
  -- neither has sent a heartbeat since, and the compactor stopped within an
  -- hour of the last worker, nothing crashed: a run ended and the hosts were
  -- switched off. That is one standing fact. Reported as two stale-worker
  -- criticals plus a compactor critical, it read as an outage every day
  -- (2026-10-07 pilot, 48 source rows, 8 cells). fn_audit_gto_v31_certified
  -- still raises certified_v31_missing (critical) while nothing is certified.
  IF EXISTS (SELECT 1 FROM public.solver_worker_liveness WHERE machine_id='M1'
              AND worker_state='completed' AND received_at < now()-interval '15 minutes')
     AND EXISTS (SELECT 1 FROM public.solver_worker_liveness WHERE machine_id='M2'
              AND worker_state='completed' AND received_at < now()-interval '15 minutes')
     AND EXISTS (SELECT 1 FROM public.solver_compact_liveness c WHERE c.singleton
              AND c.received_at < now()-interval '20 minutes'
              AND c.received_at <= (SELECT max(w.received_at) FROM public.solver_worker_liveness w
                                     WHERE w.machine_id IN ('M1','M2')) + interval '1 hour') THEN
    SELECT * INTO v_worker FROM public.solver_worker_liveness WHERE machine_id='M1';
    SELECT * INTO v_peer FROM public.solver_worker_liveness WHERE machine_id='M2';
    SELECT * INTO v_compact FROM public.solver_compact_liveness WHERE singleton;
    RETURN jsonb_build_array(jsonb_build_object(
      'severity','warn','category','gto','code','solver_pipeline_parked',
      'title','V31 solver pipeline is parked: M1 and M2 finished their last run and have been off since '
              || greatest(v_worker.received_at, v_peer.received_at)::date,
      'evidence',jsonb_build_object(
        'day',p_day,
        'M1',jsonb_build_object('state',v_worker.worker_state,'last_heartbeat',v_worker.received_at,'rows_done',v_worker.rows_done),
        'M2',jsonb_build_object('state',v_peer.worker_state,'last_heartbeat',v_peer.received_at,'rows_done',v_peer.rows_done),
        'compactor',jsonb_build_object('state',v_compact.compact_state,'last_heartbeat',v_compact.received_at,
          'source_rows',v_compact.source_rows,'cells',v_compact.cells,'invalid_rows',v_compact.invalid_rows,
          'error',v_compact.error_detail,'dataset',v_compact.dataset_key)),
      'recommendation','Nothing crashed and nothing in this repository can clear it. The last run ended and the licensed PioSOLVER hosts were switched off. '||
        'Producing a certified V31 dataset needs M1 and M2 powered on and linked and a full run (not a pilot) started; '||
        'the compactor then certifies it only when Phase 4 coverage is complete. Until then V30 stays the live policy path. '||
        'The moment either host sends a heartbeat this check goes back to reporting stale, failed and stalled hosts as critical.'));
  END IF;

  FOREACH v_machine IN ARRAY ARRAY['M1','M2'] LOOP
    SELECT * INTO v_worker FROM public.solver_worker_liveness WHERE machine_id=v_machine;
    IF NOT FOUND THEN
      v_workers_healthy := false;
      v_findings := v_findings || jsonb_build_object('severity','critical','category','gto',
        'code','solver_worker_missing','title','Solver host '||v_machine||' has no heartbeat',
        'evidence',jsonb_build_object('machine_id',v_machine,'day',p_day),
        'recommendation','Start the checksum-pinned supervised worker on '||v_machine||' and confirm fn_solver_worker_heartbeat is accepted.');
      CONTINUE;
    END IF;
    IF v_worker.received_at < now()-interval '15 minutes' THEN
      v_workers_healthy := false;
      v_findings := v_findings || jsonb_build_object('severity','critical','category','gto',
        'code','solver_worker_stale','title','Solver host '||v_machine||' heartbeat is stale',
        'evidence',jsonb_build_object('machine_id',v_machine,'last_heartbeat',v_worker.received_at,
          'state',v_worker.worker_state,'phase',v_worker.phase_id,'rows_done',v_worker.rows_done),
        'recommendation','Restore the supervised worker. A stale host cannot satisfy the two-machine provenance gate.');
    ELSIF v_worker.worker_state='failed' OR v_worker.invalid_rows>0 THEN
      v_workers_healthy := false;
      v_findings := v_findings || jsonb_build_object('severity','critical','category','gto',
        'code','solver_worker_failed','title','Solver host '||v_machine||' reports failure or invalid rows',
        'evidence',jsonb_build_object('machine_id',v_machine,'state',v_worker.worker_state,
          'invalid_rows',v_worker.invalid_rows,'error',v_worker.error_detail),
        'recommendation','Quarantine the run; correct the solver/export contract and restart from a new run id.');
    ELSIF v_worker.worker_state IN ('solving','harvesting','compacting')
       AND v_worker.run_started_at < now() - (CASE WHEN v_worker.worker_state='solving'
         THEN interval '2 hours' ELSE interval '15 minutes' END) THEN
      SELECT COALESCE(max(rows_done)-min(rows_done),0) INTO v_progress
        FROM public.solver_worker_heartbeats
       WHERE machine_id=v_machine AND run_id=v_worker.run_id
         AND received_at>=now()-(CASE WHEN v_worker.worker_state='solving'
           THEN interval '2 hours' ELSE interval '15 minutes' END);
      IF v_progress=0 THEN
        v_workers_healthy := false;
        v_findings := v_findings || jsonb_build_object('severity','critical','category','gto',
          'code','solver_worker_stalled','title','Solver host '||v_machine||' made no progress inside its phase ceiling',
          'evidence',jsonb_build_object('machine_id',v_machine,'state',v_worker.worker_state,
            'phase',v_worker.phase_id,'rows_done',v_worker.rows_done,'rows_per_hour',v_worker.rows_per_hour),
          'recommendation','Inspect the Pio UPI process and worker log. Solves have a two-hour ceiling; harvest and compaction have a 15-minute ceiling. A fresh heartbeat with frozen counters is not progress.');
      END IF;
    END IF;
  END LOOP;

  SELECT * INTO v_worker FROM public.solver_worker_liveness WHERE machine_id='M1';
  SELECT * INTO v_peer FROM public.solver_worker_liveness WHERE machine_id='M2';
  IF v_worker.machine_id IS NOT NULL AND v_peer.machine_id IS NOT NULL AND (
    v_worker.pipeline_commit<>v_peer.pipeline_commit OR
    v_worker.pipeline_bundle_checksum<>v_peer.pipeline_bundle_checksum OR
    v_worker.manifest_version<>v_peer.manifest_version OR
    v_worker.manifest_checksum<>v_peer.manifest_checksum OR
    v_worker.solver_binary_checksum<>v_peer.solver_binary_checksum OR
    v_worker.range_bundle_checksum<>v_peer.range_bundle_checksum OR
    v_worker.source_combo_order_checksum<>v_peer.source_combo_order_checksum
  ) THEN
    v_provenance_matches := false;
    v_findings := v_findings || jsonb_build_object('severity','critical','category','gto',
      'code','solver_worker_provenance_split','title','M1 and M2 are not running identical approved inputs',
      'evidence',jsonb_build_object('M1',jsonb_build_object('commit',v_worker.pipeline_commit,
        'manifest',v_worker.manifest_checksum,'binary',v_worker.solver_binary_checksum),
        'M2',jsonb_build_object('commit',v_peer.pipeline_commit,'manifest',v_peer.manifest_checksum,
        'binary',v_peer.solver_binary_checksum)),
      'recommendation','Stop both workers and redeploy one protected commit, manifest, binary and range bundle to both hosts.');
  END IF;

  SELECT * INTO v_compact FROM public.solver_compact_liveness WHERE singleton;
  IF NOT FOUND THEN
    v_findings := v_findings || jsonb_build_object('severity','critical','category','gto',
      'code','solver_compactor_missing','title','Certified V31 compactor has no heartbeat',
      'evidence',jsonb_build_object('day',p_day),
      'recommendation','Start the pinned compact builder. Solver rows are not runtime policy until source receipts and held-out gates produce a certified candidate.');
  ELSIF v_compact.received_at<now()-interval '20 minutes' OR v_compact.compact_state='failed'
     OR v_compact.invalid_rows>0 OR COALESCE(v_compact.compact_lag_seconds,0)>21600 THEN
    v_findings := v_findings || jsonb_build_object('severity','critical','category','gto',
      'code','solver_compactor_unhealthy','title','Certified V31 compact build is stale, failed, invalid, or over six hours behind',
      'evidence',jsonb_build_object('last_heartbeat',v_compact.received_at,'state',v_compact.compact_state,
        'invalid_rows',v_compact.invalid_rows,'lag_seconds',v_compact.compact_lag_seconds,
        'source_rows',v_compact.source_rows,'receipt_rows',v_compact.receipt_rows,'cells',v_compact.cells,
        'error',v_compact.error_detail),
      'recommendation','Repair the compact builder and source reconciliation. Keep the candidate inactive until invalid rows are zero and lag recovers.');
  ELSIF v_workers_healthy AND v_provenance_matches THEN
    v_findings := v_findings || jsonb_build_object('severity','info','category','gto',
      'code','solver_pipeline_live','title','Both solver-host slots and the V31 compactor are instrumented',
      'evidence',jsonb_build_object('M1_at',v_worker.received_at,'M2_at',v_peer.received_at,
        'compact_at',v_compact.received_at,'compact_lag_seconds',v_compact.compact_lag_seconds,
        'dataset',v_compact.dataset_key),
      'recommendation','Continue monitoring independent host progress, checksums, invalid rows and compact lag.');
  END IF;
  RETURN v_findings;
END;
$$;


ALTER FUNCTION public.fn_audit_solver_pipeline_liveness(p_day date) OWNER TO postgres;

--
-- TOC entry 7340 (class 1255 OID 18644597)
-- Name: fn_audit_supply_breaches(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_supply_breaches(p_day date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_findings jsonb := '[]'::jsonb;
  v_n int;
  v_sum numeric;
  v_oldest timestamptz;
  v_newest timestamptz;
  v_worst numeric;
begin
  select count(*), coalesce(sum(unexplained), 0), min(taken_at), max(taken_at),
         coalesce(max(abs(unexplained)), 0)
    into v_n, v_sum, v_oldest, v_newest, v_worst
    from fn_ca_unacknowledged_supply_breaches();

  if v_n = 0 then
    return v_findings;
  end if;

  v_findings := v_findings || jsonb_build_object(
    'severity', 'critical',
    'category', 'schema',
    'code', 'supply_breach_unacknowledged',
    'title', v_n || ' chip-supply breach(es) have never been explained, netting '
             || round(v_sum, 2) || ' chips',
    'evidence', jsonb_build_object(
      'breaches', v_n,
      'net_unexplained', round(v_sum, 2),
      'largest_single', round(v_worst, 2),
      'oldest', v_oldest,
      'newest', v_newest,
      'rows', (select coalesce(jsonb_agg(jsonb_build_object(
                        'taken_at', b.taken_at,
                        'unexplained', b.unexplained,
                        'age_hours', b.age_hours) order by b.taken_at desc), '[]'::jsonb)
                 from fn_ca_unacknowledged_supply_breaches() b)
    ),
    'recommendation',
      'The deploy gate only sums a TRAILING FOUR HOURS, so each of these went '
      || 'green on its own within four hours of happening and has been invisible '
      || 'since. This finding does not expire. Either explain each one with an '
      || 'INSERT into ca_supply_breach_ack (snapshot_id, acknowledged_by, reason), '
      || 'which is a deliberate written act and the audit trail for chips that '
      || 'could not be accounted for, or treat it as a live money-integrity '
      || 'incident. If these are the gap already baselined by '
      || 'baseline_the_unledgered_gap on 2026-08-27, say so in the reason - do '
      || 'not assume it, because nothing in the data says it.'
  );

  return v_findings;
end
$$;


ALTER FUNCTION public.fn_audit_supply_breaches(p_day date) OWNER TO postgres;

--
-- TOC entry 7645 (class 1255 OID 21809822)
-- Name: fn_audit_tag_consumers(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_tag_consumers(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  r record;
  v_registry int;
begin
  select count(*) into v_registry from horse_data_ledger where kind = 'tag';
  if v_registry = 0 then
    v := v || jsonb_build_object('severity','warn','category','schema','code','tag_registry_missing',
      'title','horse_data_ledger has no tag rows - the engine has not synced TAG_CONSUMERS',
      'evidence', jsonb_build_object('rows', 0),
      'recommendation','HorseDataLedgerSync writes the tag registry at boot. Until the engine restarts on a build that carries TAG_CONSUMERS, tag_unread cannot be judged.');
    return v;
  end if;
  for r in
    with week as (
      select k as tag, sum((leak_counts->>k)::bigint) as n
        from horse_review_rollup, lateral jsonb_object_keys(leak_counts) k
       where day > p_day - 7 and day <= p_day
       group by k
    )
    select w.tag, w.n,
           l.consumer,
           case when w.tag like '%\_won' escape '\' then substr(w.tag, 1, length(w.tag) - 4) end as base
      from week w
      left join horse_data_ledger l on l.kind = 'tag' and l.key = 'tag:' || w.tag
     where w.n >= 100
     order by w.n desc
  loop
    if r.consumer is null and r.base is not null then
      continue;
    end if;
    if r.consumer is null then
      v := v || jsonb_build_object('severity','warn','category','logic','code','tag_unread',
        'title','Leak tag ' || r.tag || ' (' || r.n || ' rows this week) has no ledger row',
        'evidence', jsonb_build_object('tag', r.tag, 'rows_7d', r.n),
        'recommendation','A detector emits this tag and HorseDataLedger.TAG_CONSUMERS does not know it. EveryTagHasAConsumer.law.test.ts should have failed; if the engine is older than the tag, redeploy. Register it with the code that reads it, or as measurement with the reason.');
    elsif r.consumer = 'measurement' and r.n >= 1000 then
      v := v || jsonb_build_object('severity','info','category','logic','code','tag_measurement_only',
        'title','Leak tag ' || r.tag || ' (' || r.n || ' rows this week) is measurement only',
        'evidence', jsonb_build_object('tag', r.tag, 'rows_7d', r.n, 'reason', (select note from horse_data_ledger where kind = 'tag' and key = 'tag:' || r.tag)),
        'recommendation','Registered as read by nobody, with a reason. Volume this high is worth a decision: wire a consumer with a receipt, or keep the reason current.');
    end if;
  end loop;
  return v;
end $$;


ALTER FUNCTION public.fn_audit_tag_consumers(p_day date) OWNER TO postgres;

--
-- TOC entry 8024 (class 1255 OID 21786701)
-- Name: fn_audit_tournament_results(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_audit_tournament_results(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb := '[]'::jsonb;
  r record;
  v_completed int;
  v_rows int;
begin
  select count(*) into v_completed from tournaments
   where status = 'COMPLETED' and ended_at >= p_day and ended_at < p_day + 1;
  select count(*) into v_rows from horse_tournament_daily where day = p_day;
  if v_completed >= 20 and v_rows = 0 then
    v := v || jsonb_build_object('severity','critical','category','schema','code','tournament_results_missing',
      'title', v_completed || ' tournaments completed on ' || p_day || ' and the horse scoreboard has no rows',
      'evidence', jsonb_build_object('completed', v_completed, 'scoreboard_rows', v_rows),
      'recommendation','fn_horse_tournament_daily_compile did not run or found no horse entries. It is called from fn_run_horse_daily_audit; check the audit ran and tournament_players.position is being written at completion.');
    return v;
  end if;
  for r in
    select tournament_type,
           sum(entries) as entries,
           sum(invested) as invested,
           sum(won) as won,
           case when sum(invested) > 0 then round(100 * (sum(won) - sum(invested)) / sum(invested), 1) end as roi_pct,
           case when sum(entries) > 0 then round(100.0 * sum(itm_entries) / sum(entries), 1) end as itm_pct
      from horse_tournament_daily
     where day > p_day - 7 and day <= p_day
     group by 1
  loop
    if r.entries >= 2000 and r.roi_pct is not null and r.roi_pct < -15 then
      v := v || jsonb_build_object('severity','warn','category','gto','code','tournament_roi_negative',
        'title', r.tournament_type || ' ROI ' || r.roi_pct || '% over ' || r.entries || ' entries (7 days)',
        'evidence', jsonb_build_object('tournament_type', r.tournament_type, 'entries', r.entries, 'invested', round(r.invested), 'won', round(r.won), 'roi_pct', r.roi_pct, 'itm_pct', r.itm_pct),
        'recommendation','The fleet plays itself, so a type''s pooled ROI is minus the fee and any overlay; compare against -fee%. A type far below that is a format the brain plays badly: read the tournament-format tags for it (fn_horse_tournament_leaks) before touching the ICM dials.');
    else
      v := v || jsonb_build_object('severity','info','category','gto','code','tournament_results',
        'title', r.tournament_type || ' ROI ' || coalesce(r.roi_pct::text, 'n/a') || '%, ITM ' || coalesce(r.itm_pct::text, 'n/a') || '% over ' || r.entries || ' entries (7 days)',
        'evidence', jsonb_build_object('tournament_type', r.tournament_type, 'entries', r.entries, 'invested', round(r.invested), 'won', round(r.won), 'roi_pct', r.roi_pct, 'itm_pct', r.itm_pct),
        'recommendation','The tournament lane scoreboard. Not a finding; the number Dan asked for.');
    end if;
  end loop;
  return v;
end $$;


