--
-- TOC entry 5122 (class 1255 OID 18652225)
-- Name: fn_backpay_unfinalised_bounty_pools(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_backpay_unfinalised_bounty_pools(p_apply boolean DEFAULT false, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  r record; v_res jsonb;
  v_events integer := 0; v_paid numeric := 0;
  v_orphan integer := 0; v_orphan_chips numeric := 0; v_alerts integer := 0;
  v_refused integer := 0; v_refused_chips numeric := 0;
  v_state text; v_msg text;
BEGIN
  PERFORM public.fn_ca_lock_settlement_lane_global();
  FOR r IN
    WITH scanned AS (
      SELECT t.id, t.name, t.club_id, t.ended_at,
             round(COALESCE(t.bounty_pool, 0), 2) AS pool,
             COALESCE((SELECT round(sum(w.amount), 2)
                         FROM public.wallet_transactions w
                        WHERE w.related_entity_id = t.id
                          AND w.type = 'credit'
                          AND w.category = 'bounty'), 0) AS wallet_bounty,
             (SELECT tp.user_id FROM public.tournament_players tp
               WHERE tp.tournament_id = t.id AND tp.status = 'winner'
               LIMIT 1) AS champion
        FROM public.tournaments t
       WHERE t.status = 'COMPLETED'
         AND COALESCE(t.bounty_pool, 0) > 0
    )
    SELECT * FROM scanned
     -- the unpaid test is part of the SCAN now, so the limit below caps how
     -- much work one run does instead of how far back it can look
     WHERE wallet_bounty + 0.01 < pool
     -- oldest debt first: a pool that has been owed longest is settled first,
     -- and can never be pushed out of reach by newer events completing
     ORDER BY ended_at ASC NULLS LAST
     LIMIT GREATEST(p_limit, 1)
  LOOP
    IF r.champion IS NULL THEN
      v_orphan := v_orphan + 1;
      v_orphan_chips := v_orphan_chips + (r.pool - r.wallet_bounty);
      PERFORM public.fn_raise_server_financial_alert(
        'warning', 'fn_backpay_unfinalised_bounty_pools',
        format('%s holds %s chips of unpaid bounty pool and has no champion recorded, so there is nobody to settle it to',
               COALESCE(r.name, r.id::text), round(r.pool - r.wallet_bounty, 2)),
        jsonb_build_object('kind','no_champion','tournament_id',r.id,
          'club_id',r.club_id,'bounty_pool',r.pool,'paid',r.wallet_bounty,
          'retained',round(r.pool - r.wallet_bounty, 2),
          'detail','no money was moved; a residual with no recipient is a question, not a payment'),
        r.id::text);
      v_alerts := v_alerts + 1;
      CONTINUE;
    END IF;

    IF p_apply THEN
      -- ONE POOL AT A TIME (2026-09-07). fn_finalize_bounty_pool RAISES when
      -- the one payer refuses (escrow_short and friends). That refusal is
      -- right and the payer has already raised its own critical alert; what
      -- must not happen is the refusal aborting THIS run and leaving every
      -- pool behind it unpaid. The block below is a savepoint: the refused
      -- pool's partial work rolls back, the rest of the run continues.
      BEGIN
        v_res := public.fn_finalize_bounty_pool(r.id, r.champion);
        IF COALESCE((v_res->>'ok')::boolean, false) THEN
          v_paid := v_paid + COALESCE((v_res->>'residual')::numeric, 0);
        END IF;
        v_events := v_events + 1;
      EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
        v_refused := v_refused + 1;
        v_refused_chips := v_refused_chips + (r.pool - r.wallet_bounty);
        PERFORM public.fn_raise_server_financial_alert(
          'critical', 'fn_backpay_unfinalised_bounty_pools',
          format('%s: bounty residual of %s chips could not be settled to the champion (%s); the sweep moved on to the next pool',
                 COALESCE(r.name, r.id::text), round(r.pool - r.wallet_bounty, 2), left(v_msg, 300)),
          jsonb_build_object('kind','refused','tournament_id',r.id,'club_id',r.club_id,
            'bounty_pool',r.pool,'paid',r.wallet_bounty,
            'residual',round(r.pool - r.wallet_bounty, 2),
            'sqlstate',v_state,'error',left(v_msg, 500),
            'detail','no money was moved for this pool; every pool behind it was still attempted'),
          'refused:' || r.id::text);
        v_alerts := v_alerts + 1;
      END;
    ELSE
      v_paid := v_paid + (r.pool - r.wallet_bounty);
      v_events := v_events + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'applied', p_apply,
    'events_settled', v_events, 'chips_settled', round(v_paid, 2),
    'events_refused', v_refused, 'chips_refused', round(v_refused_chips, 2),
    'events_without_a_champion', v_orphan,
    'chips_without_a_champion', round(v_orphan_chips, 2),
    'alerts_raised', v_alerts);
END;
$$;


ALTER FUNCTION public.fn_backpay_unfinalised_bounty_pools(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- TOC entry 45232 (class 0 OID 0)
-- Dependencies: 5122
-- Name: FUNCTION fn_backpay_unfinalised_bounty_pools(p_apply boolean, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_backpay_unfinalised_bounty_pools(p_apply boolean, p_limit integer) IS 'Hourly sweep (ca-bounty-backpay-hourly): settles every completed tournament whose bounty pool is still owed to its champion, oldest first, through fn_finalize_bounty_pool. A pool the one payer refuses is reported (once per tournament) and skipped so the pools behind it are still paid.';


--
-- TOC entry 4155 (class 1255 OID 55307349)
-- Name: fn_bag_tournament_stage(uuid, uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bag_tournament_stage(p_tournament_id uuid, p_lease_generation uuid, p_stage_no integer, p_watermarks jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_stage public.tournament_stages%ROWTYPE;
  v_next public.tournament_stages%ROWTYPE;
  v_plan public.tournament_stage_plans%ROWTYPE;
  v_receipt public.tournament_stage_transitions%ROWTYPE;
  v_key text;
  v_tables uuid[];
  v_supplied_count integer;
  v_bad jsonb;
  v_players integer;
  v_seats integer;
  v_total numeric;
  v_bounty numeric;
  v_break jsonb;
  v_facts jsonb;
  v_rows integer;
BEGIN
  IF NOT public.fn_capability_available('tournament.multi_day.single_flight') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'capability_unavailable');
  END IF;
  IF p_tournament_id IS NULL OR p_lease_generation IS NULL OR p_stage_no IS NULL
     OR p_watermarks IS NULL OR jsonb_typeof(p_watermarks) <> 'array' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_request');
  END IF;

  -- A lost response is answered from the receipt, even after the lease went.
  v_key := 'bag:' || p_tournament_id::text || ':' || p_stage_no::text;
  SELECT * INTO v_receipt FROM public.tournament_stage_transitions WHERE idempotency_key = v_key;
  IF FOUND THEN
    RETURN v_receipt.facts || jsonb_build_object('ok', true, 'replay', true, 'bag_id', v_receipt.id);
  END IF;

  PERFORM pg_advisory_xact_lock_shared(530090, 1);
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'platform_frozen');
  END IF;
  IF NOT public.fn_multi_day_lease_is_current(p_tournament_id, p_lease_generation) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'lease_lost');
  END IF;
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id, NULL);
  SELECT * INTO v_t FROM public.tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found');
  END IF;
  -- Re-read under the row lock: a concurrent bag may have committed first.
  SELECT * INTO v_receipt FROM public.tournament_stage_transitions WHERE idempotency_key = v_key;
  IF FOUND THEN
    RETURN v_receipt.facts || jsonb_build_object('ok', true, 'replay', true, 'bag_id', v_receipt.id);
  END IF;
  IF v_t.status IS DISTINCT FROM 'RUNNING' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_running', 'status', v_t.status);
  END IF;
  SELECT * INTO v_plan FROM public.tournament_stage_plans WHERE tournament_id = p_tournament_id;
  SELECT * INTO v_stage FROM public.tournament_stages
   WHERE tournament_id = p_tournament_id AND stage_no = p_stage_no FOR UPDATE;
  IF NOT FOUND OR v_stage.state IS DISTINCT FROM 'day_ending' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'stage_not_day_ending', 'stage_state', v_stage.state);
  END IF;
  SELECT * INTO v_next FROM public.tournament_stages
   WHERE tournament_id = p_tournament_id AND stage_no = p_stage_no + 1 FOR UPDATE;
  IF NOT FOUND OR v_next.state IS DISTINCT FROM 'planned' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'next_stage_not_planned');
  END IF;

  -- Parent, roster, tables, seats: the lock order of terminal settlement.
  PERFORM 1 FROM public.tournament_players p
   WHERE p.tournament_id = p_tournament_id ORDER BY p.id FOR UPDATE;
  SELECT COALESCE(array_agg(x.id ORDER BY x.id), '{}') INTO v_tables
    FROM (SELECT tb.id FROM public.tables tb
           WHERE tb.tournament_id = p_tournament_id
             AND NOT COALESCE(tb.is_deleted, false)
             AND lower(COALESCE(tb.status::text, '')) NOT IN ('closed','deleted','completed','cancelled','finished')
           ORDER BY tb.id FOR UPDATE) x;
  PERFORM 1 FROM public.table_seats s JOIN public.tables tb ON tb.id = s.table_id
   WHERE tb.tournament_id = p_tournament_id AND s.left_at IS NULL
   ORDER BY s.id FOR UPDATE OF s;

  -- (a) no cards in the air anywhere in the event.
  IF EXISTS (SELECT 1 FROM public.hand_state_snapshots h JOIN public.tables tb ON tb.id = h.table_id
              WHERE tb.tournament_id = p_tournament_id AND NOT h.is_complete) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'hand_in_flight');
  END IF;

  -- (b) the watermark: exactly the open tables, each at its last accepted hand.
  SELECT count(*) INTO v_supplied_count FROM jsonb_array_elements(p_watermarks);
  IF v_supplied_count <> cardinality(v_tables)
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_watermarks) e
                 WHERE jsonb_typeof(e) <> 'object'
                    OR NOT (e ? 'table_id') OR NOT (e ? 'last_hand_number')
                    OR jsonb_typeof(e -> 'last_hand_number') NOT IN ('number', 'null'))
     OR (SELECT count(DISTINCT e ->> 'table_id') FROM jsonb_array_elements(p_watermarks) e) <> cardinality(v_tables)
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_watermarks) e
                 WHERE NOT ((e ->> 'table_id') = ANY (SELECT unnest(v_tables)::text))) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'watermark_tables_mismatch', 'open_tables', to_jsonb(v_tables));
  END IF;
  SELECT jsonb_agg(jsonb_build_object('table_id', w.table_id, 'supplied', w.supplied, 'accepted', w.accepted))
    INTO v_bad
    FROM (SELECT (e ->> 'table_id')::uuid AS table_id,
                 CASE WHEN jsonb_typeof(e -> 'last_hand_number') = 'null' THEN NULL
                      ELSE (e ->> 'last_hand_number')::numeric END AS supplied,
                 (SELECT max(c.hand_number) FROM public.hand_atomic_commits c
                   WHERE c.table_id = (e ->> 'table_id')::uuid) AS accepted
            FROM jsonb_array_elements(p_watermarks) e) w
   WHERE w.supplied IS DISTINCT FROM w.accepted;
  IF v_bad IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'watermark_mismatch', 'tables', v_bad);
  END IF;

  -- (c) the live seats and the playing roster are the same people.
  IF EXISTS (SELECT 1 FROM public.tournament_players p
              WHERE p.tournament_id = p_tournament_id AND p.status::text = 'registered') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unseated_registrant');
  END IF;
  SELECT count(*) INTO v_players FROM public.tournament_players p
   WHERE p.tournament_id = p_tournament_id AND p.status::text = 'playing';
  SELECT count(*), COALESCE(sum(s.stack), 0) INTO v_seats, v_total
    FROM public.table_seats s JOIN public.tables tb ON tb.id = s.table_id
   WHERE tb.tournament_id = p_tournament_id AND s.left_at IS NULL;
  IF v_players <> v_seats
     OR EXISTS (SELECT 1 FROM public.table_seats s JOIN public.tables tb ON tb.id = s.table_id
                 WHERE tb.tournament_id = p_tournament_id AND s.left_at IS NULL
                   AND (NOT (s.table_id = ANY (v_tables))
                        OR NOT EXISTS (SELECT 1 FROM public.tournament_players p
                                        WHERE p.tournament_id = p_tournament_id AND p.user_id = s.user_id
                                          AND p.status::text = 'playing')))
     OR (SELECT count(DISTINCT s.user_id) FROM public.table_seats s JOIN public.tables tb ON tb.id = s.table_id
          WHERE tb.tournament_id = p_tournament_id AND s.left_at IS NULL) <> v_seats THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'roster_seat_mismatch', 'playing', v_players, 'live_seats', v_seats);
  END IF;
  IF v_seats < 2 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'field_decided', 'live_seats', v_seats);
  END IF;
  IF EXISTS (SELECT 1 FROM public.table_seats s JOIN public.tables tb ON tb.id = s.table_id
              WHERE tb.tournament_id = p_tournament_id AND s.left_at IS NULL
                AND (s.stack IS NULL OR s.stack <= 0 OR s.stack <> trunc(s.stack))) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'stack_invalid');
  END IF;

  -- (d) every stack equals the last accepted hand that dealt its player.
  SELECT jsonb_agg(jsonb_build_object('user_id', s.user_id, 'felt', s.stack, 'accepted', w.written,
                                      'hand_number', w.hand_number))
    INTO v_bad
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id = s.table_id
    CROSS JOIN LATERAL (
      SELECT (c.stack_result -> 'written' ->> s.user_id::text)::numeric AS written, c.hand_number
        FROM public.hand_atomic_commits c JOIN public.tables tc ON tc.id = c.table_id
       WHERE tc.tournament_id = p_tournament_id
         AND c.stack_result -> 'written' ? s.user_id::text
       ORDER BY c.hand_number DESC LIMIT 1) w
   WHERE tb.tournament_id = p_tournament_id AND s.left_at IS NULL
     AND w.written IS DISTINCT FROM s.stack;
  IF v_bad IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'felt_differs_from_accepted_hand', 'seats', v_bad);
  END IF;

  SELECT COALESCE(sum(COALESCE(p.current_bounty, 0)), 0) INTO v_bounty
    FROM public.tournament_players p
   WHERE p.tournament_id = p_tournament_id AND p.status::text = 'playing';
  v_break := jsonb_build_object('on_break', COALESCE(v_t.on_break, false),
    'break_started_at', v_t.break_started_at, 'break_ends_at', v_t.break_ends_at,
    'addon_period_ends_at', v_t.addon_period_ends_at);

  -- ---- write: every stack moves seat -> bag exactly once ----
  PERFORM set_config('app.multi_day_stage_writer', p_tournament_id::text, true);
  PERFORM set_config('app.multi_day_stage_custody', p_tournament_id::text, true);

  v_facts := jsonb_build_object('stage_no', p_stage_no, 'next_stage_no', p_stage_no + 1,
    'players', v_seats, 'total_chips', v_total, 'bounty_total', v_bounty,
    'level_index', v_t.current_level, 'next_level_index', v_t.current_level + 1,
    'next_stage_start_utc', v_next.scheduled_start_utc, 'time_zone', v_plan.time_zone,
    'tables_closed', cardinality(v_tables), 'watermarks', p_watermarks,
    'lease_generation', p_lease_generation);
  INSERT INTO public.tournament_stage_transitions
    (tournament_id, stage_no, kind, idempotency_key, lease_generation, facts)
  VALUES (p_tournament_id, p_stage_no, 'bag', v_key, p_lease_generation, v_facts)
  RETURNING * INTO v_receipt;

  INSERT INTO public.tournament_stage_clock_snapshots
    (tournament_id, stage_no, bag_id, rule_version, level_index, small_blind, big_blind, ante,
     blind_level_state, remaining_level_ms, next_level_index, break_state, next_stage_no,
     next_stage_start_utc, next_stage_zone)
  VALUES (p_tournament_id, p_stage_no, v_receipt.id, v_plan.rule_version, v_t.current_level,
          (v_t.blind_level_state ->> 'small_blind')::numeric, (v_t.blind_level_state ->> 'big_blind')::numeric,
          (v_t.blind_level_state ->> 'ante')::numeric, v_t.blind_level_state,
          0, v_t.current_level + 1, v_break, p_stage_no + 1, v_next.scheduled_start_utc, v_plan.time_zone);

  INSERT INTO public.tournament_stage_bag_watermarks
    (tournament_id, stage_no, table_id, bag_id, last_hand_number, last_hand_id, seat_count, seat_stack_sum)
  SELECT p_tournament_id, p_stage_no, tb.id, v_receipt.id, c.hand_number, c.hand_id,
         (SELECT count(*) FROM public.table_seats s WHERE s.table_id = tb.id AND s.left_at IS NULL),
         (SELECT COALESCE(sum(s.stack), 0) FROM public.table_seats s WHERE s.table_id = tb.id AND s.left_at IS NULL)
    FROM unnest(v_tables) AS tb(id)
    LEFT JOIN LATERAL (SELECT c2.hand_number, c2.hand_id FROM public.hand_atomic_commits c2
                        WHERE c2.table_id = tb.id ORDER BY c2.hand_number DESC LIMIT 1) c ON true;

  INSERT INTO public.tournament_stage_bags
    (tournament_id, stage_no, bag_id, registration_id, user_id, stack, bounty_head,
     source_table_id, source_seat_id, source_seat_number, seat_club_id, seat_horse_id, watermark_hand_number)
  SELECT p_tournament_id, p_stage_no, v_receipt.id, p.id, p.user_id, s.stack, COALESCE(p.current_bounty, 0),
         s.table_id, s.id, s.seat_number, s.club_id, s.horse_id,
         (SELECT max(c.hand_number) FROM public.hand_atomic_commits c JOIN public.tables tc ON tc.id = c.table_id
           WHERE tc.tournament_id = p_tournament_id AND c.stack_result -> 'written' ? s.user_id::text)
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id = s.table_id
    JOIN public.tournament_players p ON p.tournament_id = p_tournament_id AND p.user_id = s.user_id
   WHERE tb.tournament_id = p_tournament_id AND s.left_at IS NULL;

  INSERT INTO public.tournament_qualification_entitlements
    (tournament_id, user_id, source_stage_no, source_registration_id, source_bag_row_id,
     stack, bounty_head, target_stage_no)
  SELECT b.tournament_id, b.user_id, b.stage_no, b.registration_id, b.id, b.stack, b.bounty_head, b.stage_no + 1
    FROM public.tournament_stage_bags b
   WHERE b.bag_id = v_receipt.id;

  UPDATE public.tournament_players p
     SET chips = b.stack::integer, table_id = NULL, seat_number = NULL
    FROM public.tournament_stage_bags b
   WHERE b.bag_id = v_receipt.id AND p.id = b.registration_id;

  UPDATE public.table_seats s
     SET stack = 0, left_at = clock_timestamp()
    FROM public.tournament_stage_bags b
   WHERE b.bag_id = v_receipt.id AND s.id = b.source_seat_id AND s.left_at IS NULL;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> v_seats THEN
    RAISE EXCEPTION 'MULTI_DAY_BAG_SEAT_COUNT_CHANGED: % vacated, % expected', v_rows, v_seats USING ERRCODE = '55000';
  END IF;

  UPDATE public.tables tb
     SET status = 'closed', current_players = 0, updated_at = now()
   WHERE tb.id = ANY (v_tables);

  PERFORM set_config('app.atomic_stage_bag', p_tournament_id::text || ':' || v_receipt.id::text, true);
  UPDATE public.tournaments
     SET status = 'BAGGED',
         on_break = false,
         break_started_at = CASE WHEN COALESCE(v_t.on_break, false) THEN NULL ELSE break_started_at END,
         break_ends_at = CASE WHEN COALESCE(v_t.on_break, false) THEN NULL ELSE break_ends_at END
   WHERE id = p_tournament_id;
  PERFORM set_config('app.atomic_stage_bag', '', true);

  UPDATE public.tournament_stages
     SET state = 'bagged', state_changed_at = clock_timestamp()
   WHERE tournament_id = p_tournament_id AND stage_no = p_stage_no;
  UPDATE public.tournament_stages
     SET state = 'scheduled', state_changed_at = clock_timestamp()
   WHERE tournament_id = p_tournament_id AND stage_no = p_stage_no + 1;

  -- ---- conservation, before commit ----
  IF (SELECT count(*) FROM public.tournament_stage_bags WHERE bag_id = v_receipt.id) <> v_seats
     OR (SELECT COALESCE(sum(stack), 0) FROM public.tournament_stage_bags WHERE bag_id = v_receipt.id) <> v_total
     OR (SELECT COALESCE(sum(e.stack), 0) FROM public.tournament_qualification_entitlements e
          JOIN public.tournament_stage_bags b ON b.id = e.source_bag_row_id WHERE b.bag_id = v_receipt.id) <> v_total
     OR (SELECT COALESCE(sum(p.chips), 0) FROM public.tournament_players p
          WHERE p.tournament_id = p_tournament_id AND p.status::text = 'playing') <> v_total
     OR EXISTS (SELECT 1 FROM public.table_seats s JOIN public.tables tb ON tb.id = s.table_id
                 WHERE tb.tournament_id = p_tournament_id AND s.left_at IS NULL)
     OR (SELECT status FROM public.tournaments WHERE id = p_tournament_id) IS DISTINCT FROM 'BAGGED' THEN
    RAISE EXCEPTION 'MULTI_DAY_BAG_CONSERVATION_FAILED' USING ERRCODE = '55000';
  END IF;

  PERFORM set_config('app.multi_day_stage_custody', '', true);
  PERFORM set_config('app.multi_day_stage_writer', '', true);
  RETURN v_facts || jsonb_build_object('ok', true, 'replay', false, 'bag_id', v_receipt.id);
END
$$;


ALTER FUNCTION public.fn_bag_tournament_stage(p_tournament_id uuid, p_lease_generation uuid, p_stage_no integer, p_watermarks jsonb) OWNER TO postgres;

--
-- TOC entry 5119 (class 1255 OID 89815708)
-- Name: fn_bank_standalone_week_rake(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bank_standalone_week_rake(p_club_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_name text;
  v_cash numeric;
  v_fees numeric;
  v_total numeric;
  v_key text;
  v_res jsonb;
  v_cat text := COALESCE(current_setting('app.ledger_category', true), '');
  v_cp text := COALESCE(current_setting('app.ledger_counterparty', true), '');
  v_cpe text := COALESCE(current_setting('app.ledger_counterparty_entity', true), '');
  v_idem text := COALESCE(current_setting('app.ledger_idempotency_key', true), '');
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'not_authorised' USING ERRCODE = '42501';
  END IF;
  IF p_club_id IS NULL OR p_period_start IS NULL OR p_period_end IS NULL
     OR p_period_start <> public.fn_union_week_start(p_period_start)
     OR p_period_end <> public.fn_union_week_start(p_period_start + interval '8 days')
     OR p_period_end > public.fn_union_week_start(clock_timestamp()) THEN
    RAISE EXCEPTION 'standalone_rake_bank_invalid_week' USING ERRCODE = '22023';
  END IF;
  SELECT c.name INTO v_name FROM public.clubs c
   WHERE c.id = p_club_id AND c.is_union IS NOT TRUE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'standalone_rake_bank_unknown_club' USING ERRCODE = '22023';
  END IF;

  -- Cash: the standalone bank receipt every retired cash rake leg carries.
  SELECT COALESCE(sum(b.amount), 0) INTO v_cash
    FROM public.accounting_cash_bank_receipts b
   WHERE b.union_id IS NULL AND b.club_id = p_club_id
     AND b.club_ledger_id IS NOT NULL
     AND b.banked_at >= p_period_start AND b.banked_at < p_period_end;
  -- Tournament fees: the settlement row of every standalone fee retirement.
  SELECT COALESCE(sum(s.amount), 0) INTO v_fees
    FROM public.tournament_rake_settlements s
   WHERE s.destination = 'chip_retirement:' || p_club_id::text
     AND s.settled_at >= p_period_start AND s.settled_at < p_period_end;
  v_total := v_cash + v_fees;
  IF v_total <= 0 THEN
    RETURN jsonb_build_object('ok', true, 'amount', 0, 'club_id', p_club_id,
      'period_start', p_period_start, 'period_end', p_period_end);
  END IF;

  v_key := 'standalone-rake-bank:' || p_club_id::text || ':'
    || to_char(p_period_start AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') || '..'
    || to_char(p_period_end AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
  v_res := public.fn_ca_fund_club(
    p_club_id, v_total,
    'Weekly bank of the standalone rake ' || COALESCE(v_name, p_club_id::text)
      || ' retired in the week ' || to_char(p_period_start AT TIME ZONE 'UTC', 'YYYY-MM-DD')
      || '..' || to_char(p_period_end AT TIME ZONE 'UTC', 'YYYY-MM-DD')
      || ' (cash ' || v_cash::text || ', tournament fees ' || v_fees::text
      || '); standalone rake belongs to the club treasury (CLUB-MONEY-LEDGERS-CANONICAL)',
    v_key);
  PERFORM set_config('app.ledger_category', v_cat, true);
  PERFORM set_config('app.ledger_counterparty', v_cp, true);
  PERFORM set_config('app.ledger_counterparty_entity', v_cpe, true);
  PERFORM set_config('app.ledger_idempotency_key', v_idem, true);
  IF v_res->>'ok' IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'standalone_rake_bank_refused' USING DETAIL = v_res::text;
  END IF;
  RETURN v_res || jsonb_build_object('cash_rake', v_cash, 'tournament_fees', v_fees,
    'period_start', p_period_start, 'period_end', p_period_end);
END;
$$;


ALTER FUNCTION public.fn_bank_standalone_week_rake(p_club_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 5237 (class 1255 OID 9729850)
-- Name: fn_batch_active_player_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_batch_active_player_counts(p_club_ids uuid[]) RETURNS TABLE(club_id uuid, active_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with live as (
    select
      ts.user_id,
      -- ONE club per seated player. This is the whole fix.
      coalesce(ts.club_id, t.club_id) as at_club,
      t.union_id                      as at_union
    from table_seats ts
    join tables t
      on t.id = ts.table_id
     and lower(coalesce(t.status, '')) not in ('closed', 'completed', 'cancelled', 'finished')
    where ts.left_at is null
      and coalesce(ts.is_away, false) = false
  )
  select
    c.id as club_id,
    count(distinct l.user_id) as active_count
  from clubs c
  join live l
    on case
         when coalesce(c.is_union, false)
           -- Union: its own tables, plus every member club's tables.
           then l.at_union = c.id
                or l.at_club = c.id
                or l.at_club in (select mc.id from clubs mc where mc.union_id = c.id)
           -- Club: only the players actually representing it right now.
           else l.at_club = c.id
       end
  where c.id = any(p_club_ids)
  group by c.id;
$$;


ALTER FUNCTION public.fn_batch_active_player_counts(p_club_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 6821 (class 1255 OID 2423082)
-- Name: fn_batch_club_member_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_batch_club_member_counts(p_club_ids uuid[]) RETURNS TABLE(club_id uuid, member_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT cm.club_id,
         (COUNT(*)
          + COALESCE((SELECT b.boost FROM public.club_display_member_boost b
                       WHERE b.club_id = cm.club_id), 0))::bigint AS member_count
  FROM club_members cm
  WHERE cm.club_id = ANY(p_club_ids)
    AND (cm.status IS NULL OR cm.status IN ('active', 'approved'))
  GROUP BY cm.club_id;
$$;


ALTER FUNCTION public.fn_batch_club_member_counts(p_club_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 45237 (class 0 OID 0)
-- Dependencies: 6821
-- Name: FUNCTION fn_batch_club_member_counts(p_club_ids uuid[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_batch_club_member_counts(p_club_ids uuid[]) IS 'Live member counts for club cards. SECURITY DEFINER on purpose: under RLS a plain player could only count their own row and saw "1" on every club (2026-08-23). The same counts are already public via clubs.member_count.';


--
-- TOC entry 4303 (class 1255 OID 26940677)
-- Name: fn_batch_club_realtime_active_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_batch_club_realtime_active_counts(p_club_ids uuid[]) RETURNS TABLE(club_id uuid, active_count bigint, cash_count bigint, event_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  WITH requested AS (
    SELECT DISTINCT r.club_id FROM unnest(p_club_ids) r(club_id)
  ),
  seated AS (
    -- Every live seat held by a member of the requested club on that club's
    -- floor: the club's own tables, or its union's tables. A member club of a
    -- union plays on tables stamped with the UNION's id (2026-09-03).
    SELECT requested.club_id,
           ts.user_id,
           (t.tournament_id IS NULL) AS at_cash
      FROM requested
      JOIN public.clubs cl ON cl.id = requested.club_id
      JOIN public.club_members cm ON cm.club_id = requested.club_id
       AND (cm.status IS NULL OR cm.status IN ('active', 'approved'))
      JOIN public.table_seats ts ON ts.user_id = cm.user_id
       AND ts.left_at IS NULL AND COALESCE(ts.is_away, false) = false
      JOIN public.tables t ON t.id = ts.table_id
       AND (t.club_id = requested.club_id
            OR (cl.union_id IS NOT NULL AND t.union_id = cl.union_id))
       AND lower(COALESCE(t.status, '')) NOT IN ('closed','completed','cancelled','finished')
  )
  SELECT requested.club_id,
         count(DISTINCT s.user_id)::bigint AS active_count,
         count(DISTINCT s.user_id) FILTER (WHERE s.at_cash)::bigint AS cash_count,
         count(DISTINCT s.user_id) FILTER (WHERE NOT s.at_cash)::bigint AS event_count
    FROM requested
    LEFT JOIN seated s ON s.club_id = requested.club_id
   GROUP BY requested.club_id;
$$;


ALTER FUNCTION public.fn_batch_club_realtime_active_counts(p_club_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 45239 (class 0 OID 0)
