--

COMMENT ON FUNCTION public.fn_batch_club_realtime_active_counts(p_club_ids uuid[]) IS 'Per requested club: DISTINCT members holding a live seat on the club''s floor (own tables plus its union''s), split into cash_count (cash tables) and event_count (tournament, Spin, SNG tables). One row per requested club, zero included.';


--
-- TOC entry 5419 (class 1255 OID 18277542)
-- Name: fn_batch_club_realtime_member_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_batch_club_realtime_member_counts(p_club_ids uuid[]) RETURNS TABLE(club_id uuid, member_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT requested.club_id,
         (count(cm.user_id)
          + COALESCE((SELECT b.boost FROM public.club_display_member_boost b
                       WHERE b.club_id = requested.club_id), 0))::bigint
    FROM unnest(p_club_ids) requested(club_id)
    LEFT JOIN public.club_members cm ON cm.club_id = requested.club_id
      AND (cm.status IS NULL OR cm.status IN ('active', 'approved'))
   GROUP BY requested.club_id;
$$;


ALTER FUNCTION public.fn_batch_club_realtime_member_counts(p_club_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 5414 (class 1255 OID 26940678)
-- Name: fn_batch_union_realtime_active_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_batch_union_realtime_active_counts(p_union_ids uuid[]) RETURNS TABLE(union_id uuid, active_count bigint, cash_count bigint, event_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  WITH requested AS (
    SELECT DISTINCT r.union_id FROM unnest(p_union_ids) r(union_id)
  ),
  floor_tables AS (
    -- The union's floor: tables stamped with the union's id, the union's own
    -- club row's tables, and every member club's own tables.
    SELECT requested.union_id, t.id AS table_id, (t.tournament_id IS NULL) AS at_cash
      FROM requested
      JOIN public.tables t
        ON (t.union_id = requested.union_id
            OR t.club_id = requested.union_id
            OR t.club_id IN (SELECT uc.club_id FROM public.union_clubs uc
                              WHERE uc.union_id = requested.union_id))
     WHERE lower(COALESCE(t.status, '')) NOT IN ('closed','completed','cancelled','finished')
  ),
  seated AS (
    SELECT f.union_id, ts.user_id, f.at_cash
      FROM floor_tables f
      JOIN public.table_seats ts ON ts.table_id = f.table_id
       AND ts.left_at IS NULL AND COALESCE(ts.is_away, false) = false
  )
  SELECT requested.union_id,
         count(DISTINCT s.user_id)::bigint AS active_count,
         count(DISTINCT s.user_id) FILTER (WHERE s.at_cash)::bigint AS cash_count,
         count(DISTINCT s.user_id) FILTER (WHERE NOT s.at_cash)::bigint AS event_count
    FROM requested
    LEFT JOIN seated s ON s.union_id = requested.union_id
   GROUP BY requested.union_id;
$$;


ALTER FUNCTION public.fn_batch_union_realtime_active_counts(p_union_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 45242 (class 0 OID 0)
-- Dependencies: 5414
-- Name: FUNCTION fn_batch_union_realtime_active_counts(p_union_ids uuid[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_batch_union_realtime_active_counts(p_union_ids uuid[]) IS 'Per requested union: DISTINCT players holding a live seat on the union''s floor (its tables, its own club row''s tables, every member club''s own tables), split into cash_count and event_count. Distinct, never a sum over member clubs: a player in two member clubs is one active player. One row per requested union, zero included.';


--
-- TOC entry 5144 (class 1255 OID 18277545)
-- Name: fn_batch_union_realtime_member_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_batch_union_realtime_member_counts(p_union_ids uuid[]) RETURNS TABLE(union_id uuid, member_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  -- One person is one member, however many of the union's clubs they belong
  -- to (2026-10-18), plus the display boost of each member club.
  SELECT requested.union_id,
         ((SELECT count(DISTINCT cm.user_id)
             FROM public.union_clubs uc
             JOIN public.club_members cm ON cm.club_id = uc.club_id
              AND (cm.status IS NULL OR cm.status IN ('active', 'approved'))
            WHERE uc.union_id = requested.union_id)
          + COALESCE((SELECT sum(b.boost)
                        FROM public.union_clubs uc
                        JOIN public.club_display_member_boost b ON b.club_id = uc.club_id
                       WHERE uc.union_id = requested.union_id), 0))::bigint
    FROM (SELECT DISTINCT r.union_id FROM unnest(p_union_ids) r(union_id)) requested;
$$;


ALTER FUNCTION public.fn_batch_union_realtime_member_counts(p_union_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 8713 (class 1255 OID 20969144)
-- Name: fn_bbj_allocate(numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_allocate(p_amount numeric, p_main_balance numeric) RETURNS TABLE(main_portion numeric, backup_portion numeric, promo_portion numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pol public.ca_bbj_policy%ROWTYPE;
  v_rm numeric; v_rb numeric; v_amt numeric := round(COALESCE(p_amount, 0), 2);
BEGIN
  SELECT * INTO v_pol FROM public.ca_bbj_policy WHERE id = 1;
  IF COALESCE(p_main_balance, 0) >= v_pol.pivot_threshold THEN
    v_rm := v_pol.pivot_main; v_rb := v_pol.pivot_backup;
  ELSE
    v_rm := v_pol.standard_main; v_rb := v_pol.standard_backup;
  END IF;
  main_portion   := round(v_amt * v_rm, 2);
  backup_portion := round(v_amt * v_rb, 2);
  -- Promo takes the remainder, so the three always re-sum to the drop.
  promo_portion  := round(v_amt - main_portion - backup_portion, 2);
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.fn_bbj_allocate(p_amount numeric, p_main_balance numeric) OWNER TO postgres;

--
-- TOC entry 8366 (class 1255 OID 20979033)
-- Name: fn_bbj_allocate(numeric, numeric, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_allocate(p_amount numeric, p_main_balance numeric, p_pool_id uuid) RETURNS TABLE(main_portion numeric, backup_portion numeric, promo_portion numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pol public.ca_bbj_policy%ROWTYPE;
  v_rm numeric; v_rb numeric; v_amt numeric := round(COALESCE(p_amount, 0), 2);
  v_state public.ca_bbj_alloc_state%ROWTYPE;
  v_exact_m numeric; v_exact_b numeric;
BEGIN
  SELECT * INTO v_pol FROM public.ca_bbj_policy WHERE id = 1;
  IF COALESCE(p_main_balance, 0) >= v_pol.pivot_threshold THEN
    v_rm := v_pol.pivot_main; v_rb := v_pol.pivot_backup;
  ELSE
    v_rm := v_pol.standard_main; v_rb := v_pol.standard_backup;
  END IF;

  IF p_pool_id IS NULL THEN
    main_portion   := round(v_amt * v_rm, 2);
    backup_portion := round(v_amt * v_rb, 2);
    promo_portion  := round(v_amt - main_portion - backup_portion, 2);
    RETURN NEXT;
    RETURN;
  END IF;

  INSERT INTO public.ca_bbj_alloc_state (pool_id) VALUES (p_pool_id) ON CONFLICT (pool_id) DO NOTHING;
  SELECT * INTO v_state FROM public.ca_bbj_alloc_state WHERE pool_id = p_pool_id FOR UPDATE;

  v_exact_m := v_amt * v_rm + v_state.main_residue;
  v_exact_b := v_amt * v_rb + v_state.backup_residue;
  main_portion   := round(v_exact_m, 2);
  backup_portion := round(v_exact_b, 2);
  -- A bank cannot be asked for more than the drop, nor less than nothing.
  main_portion   := LEAST(GREATEST(main_portion, 0), v_amt);
  backup_portion := LEAST(GREATEST(backup_portion, 0), v_amt - main_portion);
  promo_portion  := round(v_amt - main_portion - backup_portion, 2);

  UPDATE public.ca_bbj_alloc_state
     SET main_residue   = round(v_exact_m - main_portion, 6),
         backup_residue = round(v_exact_b - backup_portion, 6),
         updated_at     = now()
   WHERE pool_id = p_pool_id;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.fn_bbj_allocate(p_amount numeric, p_main_balance numeric, p_pool_id uuid) OWNER TO postgres;

--
-- TOC entry 8653 (class 1255 OID 28339485)
-- Name: fn_bbj_allocation_policy(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_allocation_policy() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  -- These are the allocator's public rates, not pool balances or diagnostics.
  -- Service transport has no user subject; a player must have a real subject.
  SELECT jsonb_build_object(
    'pivot_threshold',p.pivot_threshold,
    'standard_main',p.standard_main,
    'standard_backup',p.standard_backup,
    'standard_promo',round(1-p.standard_main-p.standard_backup,4),
    'pivot_main',p.pivot_main,
    'pivot_backup',p.pivot_backup,
    'pivot_promo',round(1-p.pivot_main-p.pivot_backup,4))
  FROM public.ca_bbj_policy p
  WHERE p.id=1 AND (auth.role()='service_role' OR auth.uid() IS NOT NULL);
$$;


ALTER FUNCTION public.fn_bbj_allocation_policy() OWNER TO postgres;

--
-- TOC entry 45247 (class 0 OID 0)
-- Dependencies: 8653
-- Name: FUNCTION fn_bbj_allocation_policy(); Type: COMMENT; Schema: public; Owner: postgres
