COMMENT ON FUNCTION public.fn_bbj_allocation_policy() IS 'Authenticated players and service requests read the allocator public rule rates from row1. Promo remains the derived remainder; no balances, account data or operator diagnostic is exposed. A role without an account subject returns no policy.';


--
-- TOC entry 7846 (class 1255 OID 28519689)
-- Name: fn_bbj_analytics(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_analytics(p_pool_id uuid) RETURNS TABLE(main_balance numeric, backup_balance numeric, promo_balance numeric, contributions_24h numeric, contributions_7d numeric, contributions_30d numeric, hands_24h bigint, hands_7d bigint, total_contributed_all_time numeric, hit_count bigint, total_paid_all_time numeric, biggest_hit numeric, last_hit_at timestamp with time zone, avg_days_between_hits numeric, days_since_last_hit numeric, net_pool_position numeric, mini_enabled boolean, mini_hit_count bigint, mini_paid_all_time numeric, mini_hits_30d bigint, mini_paid_30d numeric, mini_last_hit_at timestamp with time zone, mini_reserve_floor numeric, mini_parked numeric, mini_available numeric, hands_30d bigint, main_hit_count bigint, main_paid_all_time numeric, main_avg_days_between_hits numeric, main_last_hit_at timestamp with time zone, main_days_since_last_hit numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club_id uuid;
  v_union_id uuid;
  v_allowed boolean := false;
BEGIN
  SELECT bp.club_id, bp.union_id INTO v_club_id, v_union_id
  FROM public.bbj_pools bp WHERE bp.id = p_pool_id;

  IF v_club_id IS NULL AND v_union_id IS NULL THEN
    RAISE EXCEPTION 'BBJ pool not found';
  END IF;

  IF v_club_id IS NOT NULL THEN
    v_allowed := public.fn_is_club_admin_uid(v_club_id);
  ELSE
    SELECT EXISTS (
      SELECT 1 FROM public.clubs c
      WHERE c.union_id = v_union_id
        AND public.fn_is_club_admin_uid(c.id)
    ) INTO v_allowed;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Not authorized: club admin role required for this jackpot pool';
  END IF;

  RETURN QUERY
  WITH pool AS (
    SELECT bp.main_balance, bp.backup_balance, bp.promo_balance,
           COALESCE(bp.mini_reserve_floor, 0) AS reserve_floor
    FROM public.bbj_pools bp WHERE bp.id = p_pool_id
  ),
  contrib AS (
    SELECT
      COALESCE(SUM(amount) FILTER (WHERE created_at > now() - interval '24 hours'), 0) AS c24,
      COALESCE(SUM(amount) FILTER (WHERE created_at > now() - interval '7 days'), 0) AS c7,
      COALESCE(SUM(amount) FILTER (WHERE created_at > now() - interval '30 days'), 0) AS c30,
      COUNT(*) FILTER (WHERE created_at > now() - interval '24 hours') AS h24,
      COUNT(*) FILTER (WHERE created_at > now() - interval '7 days') AS h7,
      COUNT(*) FILTER (WHERE created_at > now() - interval '30 days') AS h30,
      COALESCE(SUM(amount), 0) AS call_time
    FROM public.ca_launch_bbj_reporting_contributions WHERE pool_id = p_pool_id
  ),
  hits AS (
    SELECT
      COUNT(*) AS n,
      COALESCE(SUM(total_payout), 0) AS paid,
      COALESCE(MAX(total_payout), 0) AS biggest,
      MAX(awarded_at) AS last_at,
      MIN(awarded_at) AS first_at
    FROM public.ca_launch_bbj_reporting_winners WHERE pool_id = p_pool_id
  ),
  main_only AS (
    SELECT
      COUNT(*) AS n,
      COALESCE(SUM(total_payout), 0) AS paid,
      MAX(awarded_at) AS last_at,
      MIN(awarded_at) AS first_at
    FROM public.ca_launch_bbj_reporting_winners
    WHERE pool_id = p_pool_id AND COALESCE(kind, 'main') = 'main'
  ),
  mini AS (
    SELECT
      COUNT(*) AS n,
      COALESCE(SUM(total_payout), 0) AS paid,
      COUNT(*) FILTER (WHERE awarded_at > now() - interval '30 days') AS n30,
      COALESCE(SUM(total_payout) FILTER (WHERE awarded_at > now() - interval '30 days'), 0) AS paid30,
      MAX(awarded_at) AS last_at
    FROM public.ca_launch_bbj_reporting_winners WHERE pool_id = p_pool_id AND kind = 'mini'
  ),
  parked AS (
    SELECT public.fn_bbj_parked_reserve(p_pool_id, 'backup') AS amt
  )
  SELECT
    p.main_balance,
    p.backup_balance,
    p.promo_balance,
    c.c24, c.c7, c.c30,
    c.h24, c.h7,
    c.call_time,
    h.n, h.paid, h.biggest, h.last_at,
    CASE WHEN h.n > 1
      THEN ROUND(EXTRACT(EPOCH FROM (h.last_at - h.first_at)) / 86400.0 / (h.n - 1), 2)
      ELSE NULL END,
    CASE WHEN h.last_at IS NOT NULL
      THEN ROUND(EXTRACT(EPOCH FROM (now() - h.last_at)) / 86400.0, 2)
      ELSE NULL END,
    ROUND(c.call_time - h.paid, 2),
    EXISTS (SELECT 1 FROM public.bbj_mini_tiers t WHERE t.enabled),
    m.n, m.paid, m.n30, m.paid30, m.last_at,
    p.reserve_floor,
    pk.amt,
    GREATEST(0, COALESCE(p.backup_balance, 0) - pk.amt - p.reserve_floor),
    c.h30,
    mo.n,
    mo.paid,
    CASE WHEN mo.n > 1
      THEN ROUND(EXTRACT(EPOCH FROM (mo.last_at - mo.first_at)) / 86400.0 / (mo.n - 1), 2)
      ELSE NULL END,
    mo.last_at,
    CASE WHEN mo.last_at IS NOT NULL
      THEN ROUND(EXTRACT(EPOCH FROM (now() - mo.last_at)) / 86400.0, 2)
      ELSE NULL END
  FROM pool p, contrib c, hits h, mini m, main_only mo, parked pk;
END;
$$;


ALTER FUNCTION public.fn_bbj_analytics(p_pool_id uuid) OWNER TO postgres;

--
-- TOC entry 45249 (class 0 OID 0)
-- Dependencies: 7846
-- Name: FUNCTION fn_bbj_analytics(p_pool_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_bbj_analytics(p_pool_id uuid) IS 'Jackpot health for one pool, for a club admin of that pool or of any club in its union. Computes from the authoritative ledgers (bbj_contributions + bbj_winners), never the legacy pool counters. hit_count / avg_days_between_hits / last_hit_at count BOTH jackpots and are kept that way so no existing reader''s number moves; main_* and mini_* give each jackpot its own cadence. Blending them told one club its jackpot hit every 0.2 days when the main jackpot''s own interval was 1.15.';


--
-- TOC entry 6915 (class 1255 OID 28438326)
-- Name: fn_bbj_arm_drill(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_arm_drill(p_table_id uuid, p_note text DEFAULT NULL::text, p_kind text DEFAULT 'main'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ceiling  constant numeric := 1000.00;
  v_club     uuid;
  v_variant  text;
  v_bb       numeric;
  v_pool     record;
  v_is_union boolean;
  v_arm      uuid;
  v_kind     text := lower(coalesce(p_kind, 'main'));
  v_mini     record;
  v_tier     record;
  v_parked   numeric;
  v_headroom numeric;
  v_armed    numeric;
  v_bank     text;
BEGIN
  IF NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_platform_admin');
  END IF;

  IF v_kind NOT IN ('main', 'mini') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unknown_drill_kind', 'kind', p_kind);
  END IF;

  SELECT t.club_id, t.game_variant, t.big_blind INTO v_club, v_variant, v_bb
    FROM public.tables t WHERE t.id = p_table_id;
  IF v_club IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found_or_has_no_club');
  END IF;

  /* ASKED AS SOON AS THE TABLE IS KNOWN. It used to be the LAST check, so an
     operator with an open arm was told the pool was above the ceiling and went
     to chase a balance when the real fix was to fire or clear the arm they
     already had. A refusal that names the wrong cause is worse than a slow one. */
  IF EXISTS (SELECT 1 FROM public.bbj_drill_arms a
              WHERE a.table_id = p_table_id AND a.fired_at IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_armed');
  END IF;

  SELECT p.pool_id, p.main_balance INTO v_pool
    FROM public.fn_bbj_pool_for_club(v_club) p LIMIT 1;
  IF v_pool.pool_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'club_has_no_jackpot_pool');
  END IF;

  SELECT (bp.union_id IS NOT NULL) INTO v_is_union
    FROM public.bbj_pools bp WHERE bp.id = v_pool.pool_id;
  IF v_is_union THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'union_pool_is_never_a_drill_target',
                              'pool_id', v_pool.pool_id);
  END IF;

  IF v_kind = 'main' THEN
    v_bank  := 'main';
    v_armed := COALESCE(v_pool.main_balance, 0);

    IF v_armed > v_ceiling THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'pool_above_drill_ceiling',
                                'balance', v_armed, 'ceiling', v_ceiling);
    END IF;

    IF v_armed <= 0 THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'pool_is_empty_nothing_to_pay',
                                'pool_id', v_pool.pool_id);
    END IF;
  ELSE
    v_bank := 'backup';

    /* A VARIANT THE JACKPOT DOES NOT COVER GETS NO MINI. A mini drill bypasses
       detectMiniBBJHit entirely, so this is the only place it can be asked. */
    IF NOT EXISTS (
      SELECT 1 FROM public.bbj_qualifying_hands q
       WHERE q.variant = lower(COALESCE(v_variant, 'nlh'))
         AND COALESCE(q.eligible, false)
         AND q.hand_rank IS NOT NULL
    ) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'variant_is_not_eligible_for_the_jackpot',
                                'variant', v_variant);
    END IF;

    SELECT bp.mini_enabled, bp.backup_balance, bp.mini_reserve_floor
      INTO v_mini
      FROM public.bbj_pools bp WHERE bp.id = v_pool.pool_id;
    v_armed := COALESCE(v_mini.backup_balance, 0);

    IF NOT COALESCE(v_mini.mini_enabled, false) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'mini_is_off_for_this_pool',
                                'pool_id', v_pool.pool_id);
    END IF;

    /* THIS TABLE'S TIER, not the largest. The ladder is already in SQL. */
    SELECT st.id AS tier_id, mt.amount, mt.enabled
      INTO v_tier
      FROM public.bbj_stakes_tiers st
      JOIN public.bbj_mini_tiers mt ON mt.tier_id = st.id
     WHERE COALESCE(v_bb, 0) >= st.min_bb AND COALESCE(v_bb, 0) <= st.max_bb
     LIMIT 1;

    IF v_tier.tier_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'no_stakes_tier_for_this_big_blind',
                                'big_blind', v_bb);
    END IF;

    IF NOT COALESCE(v_tier.enabled, false) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'mini_disabled_for_this_tier',
                                'tier_id', v_tier.tier_id);
    END IF;

    /* THE PAYOUT'S OWN ARITHMETIC, including the parked reserve. */
    v_parked   := COALESCE(public.fn_bbj_parked_reserve(v_pool.pool_id, 'backup'), 0);
    v_headroom := v_armed - v_parked - COALESCE(v_tier.amount, 0);

    IF v_headroom < COALESCE(v_mini.mini_reserve_floor, 0) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'reserve_cannot_cover_a_mini_payout',
                                'backup_balance', v_armed,
                                'parked', v_parked,
                                'tier_id', v_tier.tier_id,
                                'tier_amount', v_tier.amount,
                                'reserve_floor', v_mini.mini_reserve_floor);
    END IF;
  END IF;

  /* THE BANK THIS ARM IS ARMED AGAINST. */
  INSERT INTO public.bbj_drill_arms
    (table_id, club_id, pool_id, pool_balance_at_arm, note, armed_by, kind)
  VALUES (p_table_id, v_club, v_pool.pool_id, v_armed, p_note, auth.uid(), v_kind)
  RETURNING id INTO v_arm;

  INSERT INTO public.financial_alerts (severity, source, message, context)
  VALUES ('info', 'fn_bbj_arm_drill',
          'A Bad Beat Jackpot ' || upper(v_kind) || ' DRILL was armed on table ' || p_table_id ||
          '. The next showdown there will be treated as a ' || v_kind ||
          ' jackpot hit and will pay real chips out of the ' || v_bank ||
          ' bank of pool ' || v_pool.pool_id || ' (balance ' || v_armed ||
          '). This is a drill, not a real bad beat.',
          jsonb_build_object('armId', v_arm, 'tableId', p_table_id, 'clubId', v_club,
                             'poolId', v_pool.pool_id, 'bank', v_bank, 'balance', v_armed,
                             'kind', v_kind, 'tierId', v_tier.tier_id, 'note', p_note));

  RETURN jsonb_build_object('ok', true, 'armId', v_arm, 'tableId', p_table_id,
                            'poolId', v_pool.pool_id, 'bank', v_bank, 'balance', v_armed,
                            'kind', v_kind, 'tierId', v_tier.tier_id);
END;
$$;


