-- Name: FUNCTION fn_bbj_my_contribution(p_pool_id uuid, p_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_bbj_my_contribution(p_pool_id uuid, p_days integer) IS 'A player''s honest attributed share of jackpot fees (fee * their pot share), for auth.uid() only. Replaces the dead player_id-based card that always read 0.';


--
-- TOC entry 8373 (class 1255 OID 28481125)
-- Name: fn_bbj_near_miss_summary(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_near_miss_summary(p_pool_id uuid, p_days integer DEFAULT 30) RETURNS TABLE(kind text, reason text, refusals bigint, last_at timestamp with time zone, biggest_pot numeric, example text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club_id  uuid;
  v_union_id uuid;
  v_allowed  boolean := false;
  v_days     integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authorized: the near-miss log is operator telemetry';
  END IF;

  v_days := LEAST(365, GREATEST(1, COALESCE(p_days, 30)));

  SELECT bp.club_id, bp.union_id INTO v_club_id, v_union_id
    FROM public.bbj_pools bp WHERE bp.id = p_pool_id;

  IF v_club_id IS NULL AND v_union_id IS NULL THEN
    RAISE EXCEPTION 'BBJ pool not found';
  END IF;

  IF public.fn_is_platform_admin() THEN
    v_allowed := true;
  ELSIF v_club_id IS NOT NULL THEN
    v_allowed := public.fn_is_club_admin_uid(v_club_id);
  ELSE
    SELECT EXISTS (
      SELECT 1 FROM public.clubs c
       WHERE c.union_id = v_union_id
         AND public.fn_is_club_admin_uid(c.id)
    ) INTO v_allowed;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Not authorized: club admin role required for this jackpot pool';
  END IF;

  RETURN QUERY
  WITH scoped AS (
    SELECT nm.*
      FROM public.bbj_near_misses nm
     WHERE nm.at > now() - make_interval(days => v_days)
       AND (
             (v_club_id IS NOT NULL AND nm.club_id = v_club_id)
          OR (v_union_id IS NOT NULL AND nm.club_id IN (
                SELECT c.id FROM public.clubs c WHERE c.union_id = v_union_id))
           )
  ),
  classified AS (
    SELECT
      /* THE COALESCE IS THE FIX. The column is nullable; a null reason used to
         come back as a null and the panel called .startsWith() on it. */
      COALESCE(s.reason, 'unspecified') AS reason,
      CASE
        WHEN s.reason LIKE 'mini\_refused:%' THEN 'mini_refused'
        WHEN s.reason LIKE 'mini\_%'         THEN 'mini'
        ELSE 'main'
      END AS kind,
      s.at,
      s.pot_size,
      s.message
    FROM scoped s
  )
  SELECT
    c.kind,
    c.reason,
    COUNT(*)::bigint,
    MAX(c.at),
    COALESCE(MAX(c.pot_size), 0),
    (ARRAY_AGG(c.message ORDER BY c.at DESC) FILTER (WHERE c.message IS NOT NULL))[1]
  FROM classified c
  GROUP BY c.kind, c.reason
  ORDER BY (c.kind = 'mini_refused') DESC, COUNT(*) DESC, c.reason;
END;
$$;


ALTER FUNCTION public.fn_bbj_near_miss_summary(p_pool_id uuid, p_days integer) OWNER TO postgres;

--
-- TOC entry 45276 (class 0 OID 0)
-- Dependencies: 8373
-- Name: FUNCTION fn_bbj_near_miss_summary(p_pool_id uuid, p_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_bbj_near_miss_summary(p_pool_id uuid, p_days integer) IS 'Why the jackpot did not pay: the near-miss log grouped by the gate that refused, for one pool, over a window of 1-365 days. For a club admin of that pool (or of any club in its union) and for a platform admin - the caller is read from auth.uid() at this function''s own surface. `kind` separates main from mini, and both from mini_refused, which is a hand that qualified and was turned away rather than one that never qualified. A null reason is reported as ''unspecified'' rather than passed on as a null. Moves no money and gates nothing.';


--
-- TOC entry 3394 (class 1255 OID 22715689)
-- Name: fn_bbj_notify_thresholds(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bbj_notify_thresholds() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_t              record;
  v_pool_id        uuid;
  v_balance        numeric;
  v_members        integer;
  v_crossings      integer := 0;
  v_notified       integer := 0;
  v_failed         integer := 0;
  v_crossing_id    uuid;
BEGIN
  FOR v_t IN
    SELECT th.id, th.club_id, th.amount, th.label
      FROM public.bbj_notify_thresholds th
     WHERE th.enabled
     ORDER BY th.club_id, th.amount
  LOOP
    v_pool_id := NULL;
    v_balance := NULL;
    SELECT p.pool_id, p.main_balance INTO v_pool_id, v_balance
      FROM public.fn_bbj_pool_for_club(v_t.club_id) p
     LIMIT 1;

    CONTINUE WHEN v_pool_id IS NULL;
    CONTINUE WHEN COALESCE(v_balance, 0) < v_t.amount;

    IF EXISTS (
      SELECT 1
        FROM public.bbj_threshold_crossings c
        LEFT JOIN public.bbj_pools bp ON bp.id = v_pool_id
       WHERE c.threshold_id = v_t.id
         AND c.crossed_at > COALESCE(bp.last_hit_at, '-infinity'::timestamptz)
    ) THEN
      CONTINUE;
    END IF;

    BEGIN
      INSERT INTO public.bbj_threshold_crossings
        (threshold_id, club_id, pool_id, threshold_amount, balance_at_cross)
      VALUES (v_t.id, v_t.club_id, v_pool_id, v_t.amount, v_balance)
      RETURNING id INTO v_crossing_id;

      /* EVERY ACTIVE MEMBER, HORSES INCLUDED (CLAUDE.md 10.5), IN USER_ID
         ORDER. The order is not cosmetic: each row takes a FOR KEY SHARE lock
         on its profile through the notifications FK, and an arbitrary order
         deadlocked against live traffic on the first probe. */
      WITH ordered AS (
        SELECT cm.user_id, c.name AS club_name
          FROM public.club_members cm
          JOIN public.clubs c ON c.id = cm.club_id
         WHERE cm.club_id = v_t.club_id
           AND cm.status = 'active'
         ORDER BY cm.user_id
      ), told AS (
        INSERT INTO public.notifications (user_id, type, title, message, metadata, read)
        SELECT o.user_id,
               'bonus',
               'The Bad Beat Jackpot Just Passed ' || trim(to_char(v_t.amount, 'FM999,999,999.00')) || ' Chips',
               'The jackpot at ' || COALESCE(o.club_name, 'your club') || ' is now ' ||
                 trim(to_char(v_balance, 'FM999,999,999.00')) ||
                 ' Chips. Every raked hand adds to it, and it pays the table when it hits.',
               jsonb_build_object(
                 'clubId', v_t.club_id,
                 'poolId', v_pool_id,
                 'threshold', v_t.amount,
                 'balance', v_balance,
                 'crossingId', v_crossing_id,
                 'label', v_t.label
               ),
               false
          FROM ordered o
        RETURNING 1
      )
      SELECT count(*) INTO v_members FROM told;

      UPDATE public.bbj_threshold_crossings
         SET notified_count = COALESCE(v_members, 0)
       WHERE id = v_crossing_id;

      v_crossings := v_crossings + 1;
      v_notified  := v_notified + COALESCE(v_members, 0);
    EXCEPTION WHEN OTHERS THEN
      /* The crossing row rolls back with the fan-out, so the threshold stays
         ARMED and the next run tries again. Recording a crossing that told
         nobody would silence this club's jackpot for good. */
      v_failed := v_failed + 1;
      RAISE WARNING '[bbj-threshold] club % threshold % could not be announced: % (%). It stays armed.',
        v_t.club_id, v_t.amount, SQLERRM, SQLSTATE;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'crossings', v_crossings,
    'notified', v_notified,
    'failed', v_failed
  );
END $$;


