--
-- TOC entry 3996 (class 1255 OID 24465374)
-- Name: fn_begin_tournament_launch_before_lease_generation(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_begin_tournament_launch_before_lease_generation(p_tournament_id uuid, p_launch_id uuid, p_started_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_existing public.tournament_launch_receipts%ROWTYPE;
  v_status text;
  v_tournament_started_at timestamptz;
  v_requested_started_at timestamptz := COALESCE(p_started_at, transaction_timestamp());
  v_cohort uuid[];
BEGIN
  IF public.fn_ca_launch_tournament_start_refused(p_tournament_id) THEN
    RETURN jsonb_build_object('ok',false,'reason','operator_floor_parked');
  END IF;
  PERFORM pg_advisory_xact_lock_shared(530090, 1);

  IF p_tournament_id IS NULL OR p_launch_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_launch_request');
  END IF;

  SELECT * INTO v_existing
    FROM public.tournament_launch_receipts r
   WHERE r.tournament_id = p_tournament_id
   FOR UPDATE;
  IF FOUND THEN
    IF p_started_at IS NOT NULL
       AND v_existing.launch_id = p_launch_id
       AND v_existing.started_at IS DISTINCT FROM p_started_at THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'launch_request_mismatch');
    END IF;
    SELECT t.status, t.started_at INTO v_status, v_tournament_started_at
      FROM public.tournaments t
     WHERE t.id = p_tournament_id
     FOR UPDATE;
    IF NOT FOUND
       OR (v_existing.completed_at IS NULL AND v_status <> 'REGISTERING')
       OR (v_existing.completed_at IS NOT NULL
           AND (v_status <> 'RUNNING'
                OR v_tournament_started_at IS DISTINCT FROM v_existing.started_at)) THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'launch_receipt_state_mismatch');
    END IF;
    RETURN jsonb_build_object(
      'ok', true,
      'claimed', true,
      'launch_id', v_existing.launch_id,
      'replay', true,
      'started_at', v_existing.started_at,
      'completed', v_existing.completed_at IS NOT NULL,
      'status', v_status,
      'launch_player_ids', to_jsonb(v_existing.launch_player_ids)
    );
  END IF;

  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'platform_frozen');
  END IF;

  SELECT t.status, t.started_at INTO v_status, v_tournament_started_at
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found');
  END IF;
  IF v_status <> 'REGISTERING' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'launch_status_changed',
      'status', v_status
    );
  END IF;
  IF v_tournament_started_at IS NOT NULL
     AND v_tournament_started_at IS DISTINCT FROM v_requested_started_at THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'launch_started_at_mismatch');
  END IF;

  INSERT INTO public.tournament_launch_receipts (
    tournament_id, launch_id, started_at, launch_player_ids
  ) VALUES (
    p_tournament_id, p_launch_id, v_requested_started_at,
    CASE WHEN public.fn_ca_tournament_recorded_format(p_tournament_id) IN ('mtt-v1','mtt-v2')
      THEN ARRAY(SELECT p.id FROM public.tournament_players p
        WHERE p.tournament_id=p_tournament_id AND p.status IN ('registered','playing')
        ORDER BY p.id)
      ELSE NULL END
  ) RETURNING launch_player_ids INTO v_cohort;

  RETURN jsonb_build_object(
    'ok', true,
    'claimed', true,
    'launch_id', p_launch_id,
    'replay', false,
    'started_at', v_requested_started_at,
    'completed', false,
    'launch_player_ids', to_jsonb(v_cohort)
  );
END;
$$;


ALTER FUNCTION public.fn_begin_tournament_launch_before_lease_generation(p_tournament_id uuid, p_launch_id uuid, p_started_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 3587 (class 1255 OID 25596505)
-- Name: fn_bind_cash_seat_move_occupancy(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bind_cash_seat_move_occupancy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE original record;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.player_id,NEW.game_id,NEW.from_table_id,NEW.to_table_id,NEW.reason,
         NEW.source_occupancy_id,NEW.source_seat_number) IS DISTINCT FROM
     ROW(OLD.player_id,OLD.game_id,OLD.from_table_id,OLD.to_table_id,OLD.reason,
         OLD.source_occupancy_id,OLD.source_seat_number) THEN
   RAISE EXCEPTION 'SEAT_MOVE_IDENTITY_IMMUTABLE' USING ERRCODE='23514';
  END IF;
 ELSE
  SELECT s.occupancy_id,s.seat_number INTO original
   FROM public.table_seats s JOIN public.tables t ON t.id=s.table_id
   WHERE s.user_id=NEW.player_id AND s.table_id=NEW.from_table_id AND s.left_at IS NULL
     AND t.cluster_id=NEW.game_id AND t.tournament_id IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'SEAT_MOVE_ORIGINAL_OCCUPANCY_REQUIRED' USING ERRCODE='23514'; END IF;
  IF (NEW.source_occupancy_id IS NOT NULL AND NEW.source_occupancy_id<>original.occupancy_id)
    OR (NEW.source_seat_number IS NOT NULL AND NEW.source_seat_number<>original.seat_number) THEN
   RAISE EXCEPTION 'SEAT_MOVE_ORIGINAL_OCCUPANCY_MISMATCH' USING ERRCODE='23514';
  END IF;
  NEW.source_occupancy_id:=original.occupancy_id;
  NEW.source_seat_number:=original.seat_number;
 END IF;
 RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_bind_cash_seat_move_occupancy() OWNER TO postgres;

