--
-- TOC entry 4263 (class 1255 OID 31451251)
-- Name: fn_bounty_candidate_completion_status_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bounty_candidate_completion_status_v1(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  t public.tournaments%ROWTYPE;
  c public.tournament_knockout_candidates%ROWTYPE;
  accepted jsonb; claimants jsonb; identity jsonb;
BEGIN
  SELECT * INTO t FROM public.tournaments WHERE id=p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  IF NOT (coalesce(t.is_bounty,false) OR coalesce(t.is_pko,false)
          OR coalesce(t.is_mystery_bounty,false)) THEN
    RETURN jsonb_build_object('ok',true,'reason','not_a_bounty_tournament');
  END IF;
  -- LIMIT selects one refusal witness, never a partial successful scan.
  -- NOT FOUND proves the database anti-join found no uncovered generation in
  -- the complete event. Workflow labels and current heads prove no payment.
  SELECT candidate.* INTO c FROM public.tournament_knockout_candidates candidate
   WHERE candidate.tournament_id=p_tournament_id
     AND NOT EXISTS (
       SELECT 1 FROM public.tournament_bounty_obligations obligation
        WHERE obligation.tournament_id=candidate.tournament_id
          AND obligation.eliminated_user_id=candidate.eliminated_user_id
          AND obligation.table_id=candidate.table_id
          AND obligation.hand_id=candidate.hand_id
          AND obligation.hand_number=candidate.hand_number
          AND obligation.seat_joined_at=candidate.seat_joined_at)
   ORDER BY candidate.hand_number,candidate.eliminated_user_id,candidate.id
   LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',true,'reason','all_candidate_generations_recorded');
  END IF;
  identity:=jsonb_build_object('candidate_id',c.id,'tournament_id',c.tournament_id,
    'eliminated_user_id',c.eliminated_user_id,'table_id',c.table_id,
    'hand_id',c.hand_id,'hand_number',c.hand_number,'seat_joined_at',c.seat_joined_at);
  accepted:=public.fn_pko_candidate_accepted_scope_v1(p_tournament_id,c.id);
  IF accepted->>'ok' IS DISTINCT FROM 'true' THEN
    RETURN identity||jsonb_build_object('ok',false,
      'reason','bounty_candidate_evidence_unknown','evidence',accepted);
  END IF;
  BEGIN
    claimants:=public.fn_exact_tournament_knockout_claimants(
      p_tournament_id,c.hand_id,c.eliminated_user_id);
  EXCEPTION WHEN invalid_parameter_value OR invalid_text_representation
                 OR numeric_value_out_of_range THEN
    RETURN identity||jsonb_build_object('ok',false,
      'reason','bounty_candidate_evidence_unknown','detail','claimant_evidence_malformed');
  END;
  IF jsonb_typeof(claimants) IS DISTINCT FROM 'array' THEN
    RETURN identity||jsonb_build_object('ok',false,
      'reason','bounty_candidate_evidence_unknown','detail','claimants_unproven');
  END IF;
  IF jsonb_array_length(claimants)=0 THEN
    RETURN identity||jsonb_build_object('ok',false,
      'reason','bounty_candidate_evidence_unknown','detail','claimants_unproven');
  END IF;
  RETURN identity||jsonb_build_object('ok',false,
    'reason','unclaimed_bounty_candidate','claimants',claimants);
END;
$$;


ALTER FUNCTION public.fn_bounty_candidate_completion_status_v1(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 5473 (class 1255 OID 24464230)
-- Name: fn_bounty_obligation_has_complete_marker(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_bounty_obligation_has_complete_marker(p_obligation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- DIAMOND PHASE 9: the expected split is taken at the event's unit
  -- (fn_ca_tournament_unit_cents: a cent for a chip event, so every
  -- expression below is what it was; a whole Diamond for a Diamond event).
  -- A mystery chest splits into unit-floored equal shares with the remainder
  -- to the first claimant by user id; a regular or PKO head splits into
  -- unit-floored equal shares with the remainder to the last claimant, and a
  -- PKO cash half is the unit-floored half of the share.
  SELECT COALESCE((
    SELECT CASE WHEN o.mode='mystery_chest' THEN
      EXISTS (
        SELECT 1 FROM public.tournament_bounty_awards a
         WHERE a.bounty_obligation_id=o.id AND a.status='completed'
           AND (SELECT COALESCE(sum(r.amount_cents),0)
                  FROM public.tournament_bounty_award_recipients r
                 WHERE r.award_id=a.id AND r.paid_at IS NOT NULL)=a.amount_cents
           AND NOT EXISTS (
             SELECT 1
               FROM (
                 SELECT claimant_id,ordinal,claimant_count,
                        CASE WHEN u.unit = 1 THEN
                          floor(a.amount_cents / claimant_count)
                            + CASE WHEN ordinal <= mod(a.amount_cents,claimant_count)
                                   THEN 1 ELSE 0 END
                        ELSE
                          public.fn_ca_unit_floor_cents(floor(a.amount_cents / claimant_count)::bigint, u.unit)
                            + CASE WHEN ordinal = 1
                                   THEN a.amount_cents
                                        - public.fn_ca_unit_floor_cents(floor(a.amount_cents / claimant_count)::bigint, u.unit) * claimant_count
                                   ELSE 0 END
                        END AS expected_cents
                   FROM (
                     SELECT (c->>'user_id')::uuid AS claimant_id,
                            row_number() OVER (ORDER BY c->>'user_id') AS ordinal,
                            count(*) OVER () AS claimant_count
                       FROM jsonb_array_elements(o.claimants) c
                   ) ordered_claimants
                   CROSS JOIN (SELECT public.fn_ca_tournament_unit_cents(o.tournament_id) AS unit) u
               ) expected
              WHERE NOT EXISTS (
                SELECT 1 FROM public.tournament_bounty_award_recipients r
                 WHERE r.award_id=a.id AND r.user_id=expected.claimant_id
                   AND r.amount_cents=expected.expected_cents
                   AND r.paid_at IS NOT NULL
              )
           )
           AND NOT EXISTS (
             SELECT 1 FROM public.tournament_bounty_award_recipients r
              WHERE r.award_id=a.id
                AND (r.paid_at IS NULL OR NOT EXISTS (
                  SELECT 1 FROM jsonb_array_elements(o.claimants) c
                   WHERE (c->>'user_id')::uuid=r.user_id
                ))
           )
      )
    ELSE
      NOT EXISTS (
        SELECT 1
          FROM (
            SELECT claimant_id, ordinal, claimant_count, u.unit,
                   CASE WHEN ordinal < claimant_count
                        THEN public.fn_ca_unit_floor_cents(floor(head_cents / claimant_count)::bigint, u.unit)
                        ELSE head_cents
                             - public.fn_ca_unit_floor_cents(floor(head_cents / claimant_count)::bigint, u.unit) * (claimant_count - 1)
                   END AS expected_cents
              FROM (
                SELECT (c->>'user_id')::uuid AS claimant_id,
                       row_number() OVER (ORDER BY c->>'user_id') AS ordinal,
                       count(*) OVER () AS claimant_count,
                       round(o.head_amount * 100)::bigint AS head_cents
                  FROM jsonb_array_elements(o.claimants) c
              ) ordered_claimants
              CROSS JOIN (SELECT public.fn_ca_tournament_unit_cents(o.tournament_id) AS unit) u
          ) expected
         WHERE expected.expected_cents > 0
           AND NOT EXISTS (
           SELECT 1 FROM public.tournament_bounties b
            WHERE b.bounty_obligation_id=o.id
              AND b.collector_player_id=expected.claimant_id
              AND round(b.bounty_amount * 100)::bigint=expected.expected_cents
              AND round(COALESCE(b.added_to_collector_bounty,0) * 100)::bigint=
                    CASE WHEN o.mode='pko'
                         THEN expected.expected_cents
                              - public.fn_ca_unit_floor_cents(floor(expected.expected_cents/2.0)::bigint, expected.unit)
                         ELSE 0 END
              AND round((b.bounty_amount-COALESCE(b.added_to_collector_bounty,0))*100)::bigint=
                    CASE WHEN o.mode='pko'
                         THEN public.fn_ca_unit_floor_cents(floor(expected.expected_cents/2.0)::bigint, expected.unit)
                         ELSE expected.expected_cents END
         )
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.tournament_bounties b
         WHERE b.bounty_obligation_id=o.id
           AND NOT EXISTS (
             SELECT 1 FROM jsonb_array_elements(o.claimants) c
              WHERE (c->>'user_id')::uuid=b.collector_player_id
           )
      )
      AND round(COALESCE((
        SELECT sum(b.bounty_amount) FROM public.tournament_bounties b
         WHERE b.bounty_obligation_id=o.id
      ),0),2)=round(o.head_amount,2)
    END
      FROM public.tournament_bounty_obligations o
     WHERE o.id=p_obligation_id
  ),false);
$$;


ALTER FUNCTION public.fn_bounty_obligation_has_complete_marker(p_obligation_id uuid) OWNER TO postgres;

--
-- TOC entry 5468 (class 1255 OID 16184909)
-- Name: fn_brain_telemetry_add(date, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_brain_telemetry_add(p_day date, p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r jsonb; n int := 0;
begin
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then return 0; end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    continue when r->>'feature' is null or length(r->>'feature') = 0 or length(r->>'feature') > 64;
    insert into horse_brain_telemetry as t (day, feature, fires)
    values (p_day, r->>'feature', coalesce((r->>'fires')::bigint, 0))
    on conflict (day, feature) do update set
      fires = t.fires + excluded.fires,
      updated_at = now();
    n := n + 1;
  end loop;
  return n;
end $$;


ALTER FUNCTION public.fn_brain_telemetry_add(p_day date, p_rows jsonb) OWNER TO postgres;

