COMMENT ON FUNCTION public.fn_ca_arena_diamonds() IS 'Diamonds held inside the Diamond Arena (the platform club''s member wallets). The trial balance names them apart from player wallets so a deposit does not read as a disappearance.';


--
-- TOC entry 8785 (class 1255 OID 24121986)
-- Name: fn_ca_arena_seat_is_same_asset(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_arena_seat_is_same_asset() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_club_asset text; v_arena uuid;
BEGIN
  BEGIN
    SELECT s.club_id INTO v_arena FROM public.ca_arena_settings s WHERE s.id = 1;
    IF v_arena IS NULL THEN RETURN NULL; END IF;   -- no arena yet: nothing to be inconsistent with
    SELECT c.asset INTO v_club_asset
      FROM public.tables t JOIN public.clubs c ON c.id = t.club_id
     WHERE t.id = NEW.table_id;
    IF v_club_asset IS NULL THEN RETURN NULL; END IF;
    -- The only asymmetry that can exist today: a seat at an arena (diamond) table funded from a
    -- chip club wallet, or the reverse. Both are a reporting error before they are a money one.
    IF (v_club_asset = 'diamonds') <> ((SELECT t.club_id FROM public.tables t WHERE t.id = NEW.table_id) = v_arena) THEN
      -- Flipping DR15 escalates what this files; it never refuses the seat, because a guard
      -- that can refuse a seat can strand a player mid-hand. The mode is READ here so the rule
      -- has a consumer and a flip means something (CLAUDE.md 10.86).
      PERFORM public.fn_ca_diamond_incident('DR15:cross_asset_seat',
        CASE WHEN public.fn_ca_diamond_rule_mode('DR15:cross_asset_seat') = 'refuse'
             THEN 'critical' ELSE 'warning' END, NEW.user_id, NEW.stack,
        'fn_ca_arena_seat_is_same_asset',
        jsonb_build_object('table_id', NEW.table_id, 'club_asset', v_club_asset, 'arena_club', v_arena));
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;  -- a seat is never refused by a reporting guard
  END;
  RETURN NULL;
END $$;


ALTER FUNCTION public.fn_ca_arena_seat_is_same_asset() OWNER TO postgres;

--
-- TOC entry 45368 (class 0 OID 0)
-- Dependencies: 8785
-- Name: FUNCTION fn_ca_arena_seat_is_same_asset(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_arena_seat_is_same_asset() IS 'Reports a seat whose funding asset disagrees with its club (DR15). It NEVER refuses a seat; flipping DR15 to refuse escalates the incident to critical instead.';


--
-- TOC entry 6756 (class 1255 OID 137567702)
-- Name: fn_ca_assert_emergency_path(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_assert_emergency_path(p_path text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE active boolean;
BEGIN
 IF p_path IS NULL OR p_path NOT IN('tournament_registration','positive_issuance','cashout')
 THEN RAISE EXCEPTION 'unknown_emergency_path' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('ca-emergency-stop:'||p_path,0));
 SELECT stopped INTO active FROM public.ca_emergency_stops WHERE path=p_path FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'emergency_stop_authority_missing' USING ERRCODE='55000'; END IF;
 IF active THEN RAISE EXCEPTION 'emergency_path_stopped:%',p_path USING ERRCODE='P0410'; END IF;
END $$;


ALTER FUNCTION public.fn_ca_assert_emergency_path(p_path text) OWNER TO postgres;

--
-- TOC entry 6127 (class 1255 OID 137652311)
-- Name: fn_ca_assert_player_action(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_assert_player_action(p_user_id uuid, p_scope text, p_source text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE v_enforced boolean; v_restriction public.ca_player_restrictions;
BEGIN
  IF p_user_id IS NULL THEN RETURN; END IF;
  IF p_scope NOT IN ('account','cash','tournaments','transfers','social') THEN
    RAISE EXCEPTION 'unknown_player_restriction_scope' USING ERRCODE='22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_user_id::text,731));
  SELECT restrictions_enforced INTO v_enforced FROM public.ca_operator_policy WHERE id=true FOR SHARE;
  SELECT * INTO v_restriction FROM public.ca_player_restrictions
    WHERE user_id=p_user_id AND status='active'
      AND (expires_at IS NULL OR expires_at > statement_timestamp())
      AND scope IN ('account',p_scope) ORDER BY applied_at,id LIMIT 1;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_enforced IS TRUE THEN
    RAISE EXCEPTION 'PLAYER_RESTRICTED: %',p_scope USING ERRCODE='42501';
  END IF;
  INSERT INTO public.ca_restriction_observations
    (user_id,scope,restriction_id,table_name,op,would_refuse,detail)
    VALUES(p_user_id,p_scope,v_restriction.id,p_source,'ACTION',true,
      jsonb_build_object('reason_code',v_restriction.reason_code,'restriction_scope',v_restriction.scope));
EXCEPTION WHEN insufficient_privilege THEN RAISE;
  WHEN OTHERS THEN
    -- Preserve PHASE4-CONTRACTS section 0: restriction lookup failures fail open.
    -- Session authentication and financial stops have separate fail-closed owners.
    RETURN;
END $$;


ALTER FUNCTION public.fn_ca_assert_player_action(p_user_id uuid, p_scope text, p_source text) OWNER TO postgres;

--
-- TOC entry 4070 (class 1255 OID 71708377)
-- Name: fn_ca_assert_satellite_asset(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_assert_satellite_asset(p_satellite_id uuid, p_target_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_source boolean; v_target boolean;
BEGIN
  IF p_satellite_id IS NULL OR p_target_id IS NULL THEN
    RAISE EXCEPTION 'a satellite asset check requires the satellite and its target' USING ERRCODE='22004';
  END IF;
  v_source := public.fn_poker_diamond_tournament(p_satellite_id);
  v_target := public.fn_poker_diamond_tournament(p_target_id);
  IF v_source AND NOT v_target THEN
    RAISE EXCEPTION 'diamond_satellite_cannot_seat_a_chip_target: satellite % target %',
      p_satellite_id, p_target_id USING ERRCODE='22023';
  ELSIF v_target AND NOT v_source THEN
    RAISE EXCEPTION 'chip_satellite_cannot_seat_a_diamond_target: satellite % target %',
      p_satellite_id, p_target_id USING ERRCODE='22023';
  END IF;
  RETURN v_source;
END $$;


ALTER FUNCTION public.fn_ca_assert_satellite_asset(p_satellite_id uuid, p_target_id uuid) OWNER TO postgres;

--
-- TOC entry 3662 (class 1255 OID 35302705)
-- Name: fn_ca_assert_satellite_cohort_standings(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_assert_satellite_cohort_standings(p_tournament_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE h public.tournament_satellite_settlements%ROWTYPE; n integer;
BEGIN
 SELECT * INTO STRICT h FROM public.tournament_satellite_settlements WHERE tournament_id=p_tournament_id;
 n:=cardinality(h.qualifier_ids);
 IF h.receipt_version<>3 OR h.winner_id IS NOT NULL OR n IS NULL OR n<1
    OR n>h.ticket_award_count OR h.qualifier_ids IS DISTINCT FROM
       (SELECT array_agg(DISTINCT u ORDER BY u) FROM unnest(h.qualifier_ids) u)
    OR (SELECT to_jsonb(t)->>'format_contract' FROM public.tournaments t WHERE id=p_tournament_id)
       IS DISTINCT FROM 'mtt-v2'
    OR (SELECT count(*) FROM public.tournament_players WHERE tournament_id=p_tournament_id)<>h.field_size
    OR EXISTS(SELECT 1 FROM unnest(h.qualifier_ids) u WHERE NOT EXISTS(
       SELECT 1 FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament_id
        AND tp.user_id=u AND tp.status='winner' AND tp.position IS NULL
        AND tp.elimination_sequence IS NULL AND tp.eliminated_at IS NULL AND tp.chips>0))
    OR EXISTS(SELECT 1 FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament_id
      AND NOT(tp.user_id=ANY(h.qualifier_ids))
      AND (tp.status IS DISTINCT FROM 'eliminated' OR tp.elimination_sequence IS NULL
           OR tp.position IS NULL OR tp.position<=n OR tp.position>h.field_size))
    OR (SELECT count(DISTINCT position) FROM public.tournament_players WHERE tournament_id=p_tournament_id)<>h.field_size-n
    OR (SELECT count(DISTINCT elimination_sequence) FROM public.tournament_players WHERE tournament_id=p_tournament_id)<>h.field_size-n
    OR EXISTS(SELECT 1 FROM (SELECT position,n+row_number() OVER(ORDER BY COALESCE(public.fn_ca_tournament_bust_at(tournament_id, user_id), eliminated_at) DESC NULLS LAST, elimination_sequence DESC) expected
        FROM public.tournament_players WHERE tournament_id=p_tournament_id AND status='eliminated') r
       WHERE r.position<>r.expected) THEN
  RAISE EXCEPTION 'satellite cohort has no exact unranked survivors and causal eliminated standings' USING ERRCODE='P0404';
 END IF;
END $$;


ALTER FUNCTION public.fn_ca_assert_satellite_cohort_standings(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 6985 (class 1255 OID 27744812)
-- Name: fn_ca_assert_tournament_chip_grant(uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_assert_tournament_chip_grant(p_tournament_id uuid, p_user_id uuid, p_seat_id uuid, p_new_stack numeric, p_source text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_felt numeric;
  v_own numeric;
  v_supply numeric;
  v_after numeric;
BEGIN
  IF p_tournament_id IS NULL OR p_new_stack IS NULL THEN
    RAISE EXCEPTION 'tournament chip grant assertion needs a tournament and a stack'
      USING ERRCODE='22023';
  END IF;
  IF p_new_stack::text IN ('NaN','Infinity','-Infinity') OR p_new_stack<0 THEN
    RAISE EXCEPTION 'TOURNAMENT_CHIP_GRANT_INVALID: % proposed stack %',
      COALESCE(p_source,'grant'),p_new_stack
      USING ERRCODE='22023';
  END IF;

  v_supply:=public.fn_ca_tournament_chip_supply(p_tournament_id);
  v_felt:=public.fn_ca_tournament_felt_total(p_tournament_id);
  SELECT COALESCE(ts.stack,0) INTO v_own
    FROM public.table_seats ts
   WHERE ts.id=p_seat_id AND ts.left_at IS NULL;
  v_after:=v_felt-COALESCE(v_own,0)+p_new_stack;

  IF v_after>v_felt AND v_after>v_supply THEN
    RAISE EXCEPTION
      'TOURNAMENT_CHIP_GRANT_WOULD_MINT: % for player % would leave % chips on the felt in tournament % against % ever bought in (felt now %, this seat holds %) - Aborting So No Charge Is Made',
      COALESCE(p_source,'grant'),p_user_id,v_after,p_tournament_id,v_supply,
      v_felt,COALESCE(v_own,0)
      USING ERRCODE='55000';
  END IF;
END;
$$;


ALTER FUNCTION public.fn_ca_assert_tournament_chip_grant(p_tournament_id uuid, p_user_id uuid, p_seat_id uuid, p_new_stack numeric, p_source text) OWNER TO postgres;

--
-- TOC entry 6001 (class 1255 OID 25678442)
-- Name: fn_ca_assign_tournament_player_seat_locked(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_assign_tournament_player_seat_locked(p_tournament_id uuid, p_user_id uuid, p_table_id uuid, p_seat_number integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_tp public.tournament_players%ROWTYPE;
  v_table public.tables%ROWTYPE;
  v_live public.table_seats%ROWTYPE;
  v_destination public.table_seats%ROWTYPE;
  v_live_count integer;
  v_stack numeric;
  v_felt_stack numeric;
  v_live_total numeric;
  v_own_live numeric;
  v_cap_chips numeric;
  v_cap integer;
  v_seat_id uuid;
  v_current_players integer;
  v_rows integer;
  v_assigned_at timestamptz;
  v_expected_club_id uuid;
  v_expected_horse_id uuid;
  -- Fresh tournament-seat defaults. A rebuy that keeps its live chair keeps
  -- its own persisted bank; only a newly inserted/revived occupant starts the
  -- same 30-second/four-use state as a physical INSERT.
  v_time_bank_uses integer:=4;
  v_time_bank_seconds integer:=30;
  v_previous_money_path text:=current_setting('app.money_path',true);
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL OR p_table_id IS NULL
     OR p_seat_number IS NULL OR p_seat_number NOT BETWEEN 1 AND 10 THEN
    RAISE EXCEPTION 'tournament, player, table and legal seat are required'
      USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id;
  IF upper(COALESCE(v_t.status::text,'')) NOT IN ('REGISTERING','RUNNING') THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','tournament_not_assignable',
      'status',upper(COALESCE(v_t.status::text,'')));
  END IF;
  v_cap:=public.fn_ca_tournament_seat_cap(p_tournament_id);

  -- Lock the beneficiary and every roster row claiming the requested
  -- coordinate before any table/seat row. This matches terminal settlement's
  -- tournament -> roster -> tables -> seats child order.
  PERFORM tp.id
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND (tp.user_id=p_user_id
       OR (tp.table_id=p_table_id AND tp.seat_number=p_seat_number))
   ORDER BY tp.id
   FOR UPDATE;

  SELECT * INTO v_tp FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','player_not_registered');
  END IF;
  IF v_tp.status::text NOT IN ('registered','playing') THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','player_not_assignable','status',v_tp.status::text);
  END IF;

  IF v_tp.status::text='registered' THEN
    v_stack:=COALESCE(v_t.starting_chips,0)
             +GREATEST(COALESCE(v_tp.chips,0),0);
  ELSE
    /* THE FELT IS THE BANK ON A MOVE (2026-09-10). This took the new
       seat's stack from tournament_players.chips, a MIRROR, rather than
       from the seat the player is leaving. In the ordinary case the two
       agree - measured 1,540 of 1,541 live tournament seats. When they
       do not, this statement silently minted or destroyed the gap.
       Night Owl Special b84f312f: the engine's own hands show 256,000 +
       128,000 = 384,000 at 18:01, exactly the 48 x 8,000 bought in; a
       move at 22:34:25 wrote 448,000 over a felt of 256,000 and the
       tournament has held 64,000 chips nobody bought ever since.
       The seat is where the engine settles every hand, so the seat is
       the witness; the mirror is a projection. Read the felt first and
       fall back to the mirror only when the player holds no live seat. */
    SELECT ts.stack INTO v_felt_stack
      FROM public.table_seats ts
      JOIN public.tables tb ON tb.id=ts.table_id
     WHERE tb.tournament_id=p_tournament_id
       AND ts.user_id=p_user_id
       AND ts.left_at IS NULL
     ORDER BY ts.joined_at DESC, ts.id
     LIMIT 1;
    v_stack:=COALESCE(v_felt_stack,COALESCE(v_tp.chips,0));
  END IF;

  /* A SEAT ASSIGNMENT NEVER MINTS TOURNAMENT CHIPS (2026-09-10).
     Whatever corrupts an input, this gate makes the class impossible:
     an assignment may move chips between chairs but may never RAISE the
     tournament's live total above what was bought in. A normal move
     cannot trip it - the player's own live seat is subtracted before
     v_stack is added back, so the total is unchanged. It fires only when
     seating a player would ADD chips beyond the cap. An existing overage
     is tolerated (history) and refused only from growing (the future),
     the same shape as this estate's NOT VALID constraints. */
  IF v_tp.status::text<>'registered' THEN
    SELECT COALESCE(sum(ts.stack),0) INTO v_live_total
      FROM public.table_seats ts JOIN public.tables tb ON tb.id=ts.table_id
     WHERE tb.tournament_id=p_tournament_id AND ts.left_at IS NULL;
    SELECT COALESCE(sum(ts.stack),0) INTO v_own_live
      FROM public.table_seats ts JOIN public.tables tb ON tb.id=ts.table_id
     WHERE tb.tournament_id=p_tournament_id AND ts.user_id=p_user_id
       AND ts.left_at IS NULL;
    SELECT (count(*)*COALESCE(v_t.starting_chips,0))
           +(COALESCE(sum(tp2.rebuys),0)*COALESCE(v_t.rebuy_chips,0))
           +(count(*) FILTER (WHERE tp2.add_on)*COALESCE(v_t.addon_chips,0))
      INTO v_cap_chips
      FROM public.tournament_players tp2
     WHERE tp2.tournament_id=p_tournament_id;
    IF (v_live_total-v_own_live+v_stack)>v_live_total
       AND (v_live_total-v_own_live+v_stack)>v_cap_chips
       -- Only the private original-purchase transaction may transfer a
       -- proved, unconsumed off-felt stack. This is not a cap increase:
       -- ordinary callers, later transactions and other coordinates retain
       -- the same conservation refusal. The deferred receipt must complete.
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_paid_stack_custody_receipts r
          WHERE r.transaction_id=pg_current_xact_id() AND r.state='reserved'
            AND r.tournament_id=p_tournament_id AND r.user_id=p_user_id
            AND r.destination_table_id=p_table_id AND r.destination_seat_number=p_seat_number
            AND r.grant_chips=v_stack AND r.live_chips_before=v_live_total
            AND r.funded_supply=v_cap_chips AND v_own_live=0
            AND v_tp.status='playing' AND v_tp.table_id IS NULL AND v_tp.seat_number IS NULL
            AND v_tp.rebuy_prompt_until IS NULL
            AND EXISTS(SELECT 1 FROM public.tournament_knockout_candidates c
              WHERE c.id=r.candidate_id AND c.state='rebought' AND c.resolved_at IS NOT NULL
                AND c.tournament_id=p_tournament_id AND c.eliminated_user_id=p_user_id)
       ) THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','tournament_chip_conservation',
        'live_total',v_live_total,'own_live',v_own_live,
        'proposed_stack',v_stack,'bought_in_cap',v_cap_chips);
    END IF;
  END IF;
  IF v_stack::text IN ('NaN','Infinity','-Infinity')
     OR v_stack<=0 OR v_stack<>trunc(v_stack)
     OR v_stack>2147483647 THEN
    RETURN jsonb_build_object('ok',false,'reason','player_stack_invalid');
  END IF;

  SELECT * INTO v_table FROM public.tables tb
   WHERE tb.id=p_table_id
   FOR UPDATE;
  IF NOT FOUND OR v_table.tournament_id IS DISTINCT FROM p_tournament_id THEN
    RETURN jsonb_build_object('ok',false,'reason','table_tournament_mismatch');
  END IF;
  IF lower(COALESCE(v_table.status::text,'')) NOT IN
       ('waiting','running','active')
     OR COALESCE(v_table.is_deleted,false)
     OR p_seat_number>LEAST(
          v_cap,GREATEST(2,COALESCE(NULLIF(v_table.max_players,0),v_cap))) THEN
    RETURN jsonb_build_object('ok',false,'reason','table_not_assignable');
  END IF;

  -- A physical row is reusable, but none of its former occupant's identity or
  -- per-session state is. Resolve every derived value while the tournament,
  -- roster and table rows are locked, then write the same complete shape for a
  -- new row and a revived row. Passing the old club_id through the seat stamp
  -- trigger would make it the preferred club and could attribute this entry to
  -- the departed occupant.
  v_expected_club_id:=public.fn_seat_club_for_user(
    p_user_id,p_table_id,v_tp.club_id);
  SELECT CASE WHEN COALESCE(p.is_horse,false) THEN p.id ELSE NULL END
    INTO v_expected_horse_id
    FROM public.profiles p
   WHERE p.id=p_user_id;

  PERFORM s.id
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.user_id=p_user_id AND s.left_at IS NULL
   ORDER BY s.id
   FOR UPDATE OF s;
  SELECT count(*)::integer INTO v_live_count
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.user_id=p_user_id AND s.left_at IS NULL;
  IF v_live_count>1 THEN
    RAISE EXCEPTION 'tournament player already owns multiple live seats'
      USING ERRCODE='P0404';
  END IF;
  IF v_live_count=1 THEN
    SELECT s.* INTO v_live
      FROM public.table_seats s
      JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id
       AND s.user_id=p_user_id AND s.left_at IS NULL
     FOR UPDATE OF s;
    IF v_live.table_id IS DISTINCT FROM p_table_id
       OR v_live.seat_number IS DISTINCT FROM p_seat_number THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','player_already_seated_elsewhere',
        'table_id',v_live.table_id,'seat_number',v_live.seat_number);
    END IF;
    SELECT count(*)::integer INTO v_current_players
      FROM public.table_seats s
     WHERE s.table_id=p_table_id AND s.left_at IS NULL;
    IF v_live.stack IS DISTINCT FROM v_stack
       OR v_tp.status::text<>'playing'
       OR v_tp.chips IS DISTINCT FROM v_stack::integer
       OR v_tp.table_id IS DISTINCT FROM p_table_id
       OR v_tp.seat_number IS DISTINCT FROM p_seat_number
       OR v_table.current_players IS DISTINCT FROM v_current_players
       OR v_live.joined_at IS NULL THEN
      RAISE EXCEPTION 'existing tournament assignment is not an exact receipt'
        USING ERRCODE='P0404';
    END IF;
    RETURN jsonb_build_object(
      'ok',true,'replayed',true,'tournament_id',p_tournament_id,
      'user_id',p_user_id,'table_id',p_table_id,
      'seat_id',v_live.id,'seat_number',p_seat_number,'stack',v_stack,
      'current_players',v_current_players,'assigned_at',v_live.joined_at);
  END IF;

  SELECT * INTO v_destination FROM public.table_seats s
   WHERE s.table_id=p_table_id AND s.seat_number=p_seat_number
   FOR UPDATE;
  IF FOUND AND v_destination.left_at IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','seat_taken');
  END IF;

  -- A departed occupant can still carry a stale roster coordinate. Correct
  -- that link inside this assignment transaction; never overwrite a live
  -- seat or leave two active roster rows claiming one chair.
  UPDATE public.tournament_players tp
     SET table_id=NULL,seat_number=NULL
   WHERE tp.tournament_id=p_tournament_id
     AND tp.user_id<>p_user_id
     AND tp.table_id=p_table_id AND tp.seat_number=p_seat_number;

  v_assigned_at:=clock_timestamp();
  PERFORM set_config(
    'app.money_path','fn_assign_tournament_player_seat_atomic',true);
  BEGIN
    IF v_destination.id IS NULL THEN
      INSERT INTO public.table_seats(
        table_id,user_id,player_id,member_id,seat_number,stack,status,
        joined_at,left_at,is_sitting_out,is_away,leave_pending,
        scheduled_leave_hands,horse_id,auto_rebuy,time_bank_remaining,
        time_bank_uses_remaining,club_id,sit_out_at,entry_hold,
        entry_post_agreed)
      VALUES(
        p_table_id,p_user_id,NULL,NULL,p_seat_number,v_stack,'active',
        v_assigned_at,NULL,false,false,false,NULL,v_expected_horse_id,false,
        v_time_bank_seconds,v_time_bank_uses,v_expected_club_id,NULL,NULL,
        false)
      RETURNING id INTO v_seat_id;
    ELSE
      UPDATE public.table_seats s
         SET user_id=p_user_id,player_id=NULL,member_id=NULL,stack=v_stack,
             status='active',joined_at=v_assigned_at,left_at=NULL,
             is_sitting_out=false,is_away=false,leave_pending=false,
             sit_out_at=NULL,scheduled_leave_hands=NULL,
             horse_id=v_expected_horse_id,entry_hold=NULL,
             entry_post_agreed=false,auto_rebuy=false,
             time_bank_remaining=v_time_bank_seconds,
             time_bank_uses_remaining=v_time_bank_uses,
             club_id=v_expected_club_id
       WHERE s.id=v_destination.id AND s.left_at IS NOT NULL
       RETURNING id INTO v_seat_id;
      IF v_seat_id IS NULL THEN
        RAISE EXCEPTION 'vacated tournament seat changed during assignment'
          USING ERRCODE='55000';
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'app.money_path',COALESCE(v_previous_money_path,''),true);
    RAISE;
  END;
  PERFORM set_config(
    'app.money_path',COALESCE(v_previous_money_path,''),true);

  UPDATE public.tournament_players tp
     SET status='playing',chips=v_stack::integer,
         table_id=p_table_id,seat_number=p_seat_number
   WHERE tp.id=v_tp.id AND tp.status::text IN ('registered','playing');
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'tournament roster changed during seat assignment'
      USING ERRCODE='55000';
  END IF;

  SELECT count(*)::integer INTO v_current_players
    FROM public.table_seats s
   WHERE s.table_id=p_table_id AND s.left_at IS NULL;
  UPDATE public.tables tb
     SET current_players=v_current_players,updated_at=now()
   WHERE tb.id=p_table_id;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'tournament table vanished during seat assignment'
      USING ERRCODE='55000';
  END IF;

  IF (SELECT count(*) FROM public.table_seats s
      JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id
       AND s.user_id=p_user_id AND s.left_at IS NULL)<>1
     OR NOT EXISTS(
       SELECT 1 FROM public.table_seats s
        WHERE s.id=v_seat_id AND s.table_id=p_table_id
          AND s.user_id=p_user_id AND s.seat_number=p_seat_number
          AND s.left_at IS NULL AND s.stack=v_stack
          AND s.player_id IS NULL AND s.member_id IS NULL
          AND s.horse_id IS NOT DISTINCT FROM v_expected_horse_id
          AND s.club_id IS NOT DISTINCT FROM v_expected_club_id
          AND s.time_bank_remaining=v_time_bank_seconds
          AND s.time_bank_uses_remaining=v_time_bank_uses
          AND NOT COALESCE(s.is_sitting_out,false)
          AND NOT COALESCE(s.is_away,false)
          AND NOT COALESCE(s.leave_pending,false)
          AND NOT COALESCE(s.auto_rebuy,false)
          AND s.sit_out_at IS NULL
          AND s.scheduled_leave_hands IS NULL
          AND s.entry_hold IS NULL
          AND NOT s.entry_post_agreed)
     OR NOT EXISTS(
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.id=v_tp.id AND tp.status::text='playing'
          AND tp.chips=v_stack::integer AND tp.table_id=p_table_id
          AND tp.seat_number=p_seat_number)
     OR NOT EXISTS(
       SELECT 1 FROM public.tables tb
        WHERE tb.id=p_table_id AND tb.tournament_id=p_tournament_id
          AND tb.current_players=v_current_players) THEN
    RAISE EXCEPTION 'atomic tournament seat assignment final proof is not exact'
      USING ERRCODE='P0404';
  END IF;

  RETURN jsonb_build_object(
    'ok',true,'replayed',false,'tournament_id',p_tournament_id,
    'user_id',p_user_id,'table_id',p_table_id,'seat_id',v_seat_id,
    'seat_number',p_seat_number,'stack',v_stack,
    'current_players',v_current_players,'assigned_at',v_assigned_at);
END;
$$;


ALTER FUNCTION public.fn_ca_assign_tournament_player_seat_locked(p_tournament_id uuid, p_user_id uuid, p_table_id uuid, p_seat_number integer) OWNER TO postgres;

--
-- TOC entry 5155 (class 1255 OID 23878193)
-- Name: fn_ca_attested_day_is_restated(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_attested_day_is_restated() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
  v_reason text := NULLIF(current_setting('app.ledger_maintenance', true), '');
  r record;
  v_res jsonb;
BEGIN
  IF v_reason IS NULL THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'DELETE' THEN
    FOR r IN
      SELECT DISTINCT o.created_at::date AS day
        FROM old_rows o
        JOIN public.ca_ledger_day_manifests m ON m.day = o.created_at::date
       ORDER BY 1
    LOOP
      v_res := public.fn_ca_ledger_day_manifest(r.day, 'maintenance:' || v_reason);
      IF COALESCE((v_res->>'tampered')::boolean, false) THEN
        RAISE EXCEPTION 'the manifest for % could not be restated after maintenance "%": %', r.day, v_reason, v_res
          USING ERRCODE = 'P0403';
      END IF;
    END LOOP;
  ELSE
    FOR r IN
      SELECT DISTINCT d.day
        FROM (SELECT created_at::date AS day FROM old_rows
              UNION
              SELECT created_at::date FROM new_rows) d
        JOIN public.ca_ledger_day_manifests m ON m.day = d.day
       ORDER BY 1
    LOOP
      v_res := public.fn_ca_ledger_day_manifest(r.day, 'maintenance:' || v_reason);
      IF COALESCE((v_res->>'tampered')::boolean, false) THEN
        RAISE EXCEPTION 'the manifest for % could not be restated after maintenance "%": %', r.day, v_reason, v_res
          USING ERRCODE = 'P0403';
      END IF;
    END LOOP;
  END IF;

  RETURN NULL;
END $$;


ALTER FUNCTION public.fn_ca_attested_day_is_restated() OWNER TO postgres;

--
-- TOC entry 9463 (class 1255 OID 20097071)
-- Name: fn_ca_attribute_union_rake(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_attribute_union_rake(p_hours integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_since timestamptz := now() - make_interval(hours => GREATEST(1, LEAST(COALESCE(p_hours, 3), 168)));
  v_rows int := 0; v_attributed int := 0; v_unattributed int := 0;
  v_records int := 0;
BEGIN
  IF COALESCE(auth.role(), 'service_role') <> 'service_role' THEN
    RAISE EXCEPTION 'service_role only' USING ERRCODE = '42501';
  END IF;

  /* the hands: rake at a table owned by a union's house club (tables.club_id
     = the union's id), in the window, either never attributed or still
     carrying an unattributed player under six hours old */
  CREATE TEMP TABLE _ura_hands ON COMMIT DROP AS
  SELECT r.id AS rake_record_id, r.hand_id, r.table_id, r.club_id AS union_id,
         r.created_at AS played_at, r.rake_amount, r.player_contributions
    FROM public.rake_records r
   WHERE r.is_tournament IS NOT TRUE
     AND r.rake_amount > 0
     AND r.created_at >= v_since
     AND r.player_contributions IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.unions u WHERE u.id = r.club_id)
     AND (NOT EXISTS (SELECT 1 FROM public.ca_union_rake_attribution a WHERE a.rake_record_id = r.id)
          OR EXISTS (SELECT 1 FROM public.ca_union_rake_attribution a
                      WHERE a.rake_record_id = r.id AND a.club_id IS NULL
                        AND a.attempts < 6 AND r.created_at >= now() - interval '6 hours'));
  SELECT count(*) INTO v_records FROM _ura_hands;

  CREATE TEMP TABLE _ura_contrib ON COMMIT DROP AS
  SELECT h.rake_record_id, h.hand_id, h.table_id, h.union_id, h.played_at, h.rake_amount,
         (x.key)::uuid AS user_id, (x.value)::numeric AS contrib,
         sum((x.value)::numeric) OVER (PARTITION BY h.rake_record_id) AS total
    FROM _ura_hands h, jsonb_each_text(h.player_contributions) x
   WHERE (x.value)::numeric > 0;

  /* the seat covering the hand's instant: same table first, else the
     player's latest seat that covers it */
  CREATE TEMP TABLE _ura_attr ON COMMIT DROP AS
  SELECT c.rake_record_id, c.user_id, c.union_id, c.table_id, c.hand_id, c.played_at,
         COALESCE(
           (SELECT s.club_id FROM public.table_seats s
             WHERE s.table_id = c.table_id AND s.user_id = c.user_id
               AND s.joined_at <= c.played_at
               AND COALESCE(s.left_at, 'infinity'::timestamptz) >= c.played_at - interval '2 minutes'
               AND s.club_id IS NOT NULL
             ORDER BY s.joined_at DESC LIMIT 1),
           (SELECT s.club_id FROM public.table_seats s
             WHERE s.user_id = c.user_id
               AND s.joined_at <= c.played_at
               AND COALESCE(s.left_at, 'infinity'::timestamptz) >= c.played_at - interval '2 minutes'
               AND s.club_id IS NOT NULL
             ORDER BY s.joined_at DESC LIMIT 1),
           /* the seat row itself may be gone (a table torn down deletes its
              seats): the club the player last sat through in the past week
              is the club they play through */
           (SELECT s.club_id FROM public.table_seats s
             WHERE s.user_id = c.user_id
               AND s.joined_at <= c.played_at
               AND s.joined_at >= c.played_at - interval '7 days'
               AND s.club_id IS NOT NULL
             ORDER BY s.joined_at DESC LIMIT 1)
         ) AS club_id,
         round(c.rake_amount * c.contrib / NULLIF(c.total, 0), 4) AS rake_share
    FROM _ura_contrib c;

  INSERT INTO public.ca_union_rake_attribution AS a
        (rake_record_id, user_id, union_id, table_id, hand_id, played_at, club_id, rake_share, attempts, attributed_at)
  SELECT rake_record_id, user_id, union_id, table_id, hand_id, played_at, club_id, COALESCE(rake_share, 0), 1, now()
    FROM _ura_attr
  ON CONFLICT (rake_record_id, user_id) DO UPDATE
     SET club_id       = COALESCE(EXCLUDED.club_id, a.club_id),
         rake_share    = EXCLUDED.rake_share,
         attempts      = a.attempts + 1,
         attributed_at = now();
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  SELECT count(*) FILTER (WHERE club_id IS NOT NULL), count(*) FILTER (WHERE club_id IS NULL)
    INTO v_attributed, v_unattributed
    FROM _ura_attr;

  RETURN jsonb_build_object('since', v_since, 'records', v_records, 'rows', v_rows,
                            'attributed', v_attributed, 'unattributed', v_unattributed);
END $$;


ALTER FUNCTION public.fn_ca_attribute_union_rake(p_hours integer) OWNER TO postgres;

--
-- TOC entry 7243 (class 1255 OID 18765296)
-- Name: fn_ca_audit_diamond_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_audit_diamond_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_old integer; v_new integer := COALESCE(NEW.diamonds, 0); v_delta integer;
  v_stack text; v_writer text; v_path text; v_journaled boolean := false;
  v_cert boolean; v_fixture boolean; v_sanctioned boolean; v_refuse boolean := false;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.diamonds IS NOT DISTINCT FROM OLD.diamonds THEN RETURN NEW; END IF;
    v_old := COALESCE(OLD.diamonds, 0);
  ELSE
    IF v_new = 0 THEN RETURN NEW; END IF;
    v_old := 0;
  END IF;
  v_delta := v_new - v_old;

  BEGIN
    GET DIAGNOSTICS v_stack = PG_CONTEXT;
    SELECT (regexp_match(t.ln, 'function (?:public\.)?([A-Za-z0-9_]+)\('))[1] INTO v_writer
      FROM regexp_split_to_table(COALESCE(v_stack, ''), E'\n') WITH ORDINALITY AS t(ln, ord)
     WHERE t.ln ~ 'function (?:public\.)?[A-Za-z0-9_]+\('
       AND (regexp_match(t.ln, 'function (?:public\.)?([A-Za-z0-9_]+)\('))[1] <> 'fn_ca_audit_diamond_change'
     ORDER BY t.ord LIMIT 1;

    v_path := NULLIF(btrim(COALESCE(current_setting('app.money_path', true), '')), '');
    v_journaled := EXISTS (SELECT 1 FROM public.diamond_transactions dt
                            WHERE dt.user_id = NEW.id AND dt.created_at >= now() - interval '2 seconds');
    v_cert    := public.fn_ca_is_cert_account(NEW.id);
    v_fixture := public.fn_ca_is_fixture_account(NEW.id);

    -- DR6. Every writer here journals in the same transaction; most of them AFTER the balance
    -- write, which is why v_journaled is false at trigger time for a correct credit (2026-09-07
    -- review D4-D6). Gate by name, and by prefix for the daily-challenge family whose body name
    -- has drifted twice.
    v_sanctioned :=
         COALESCE(v_writer, '') IN ('add_diamonds_to_balance', 'deduct_diamonds', 'fn_ca_mint', 'fn_ca_burn',
                                    'send_wallet_diamond_transfer', 'send_stream_gift', 'handle_new_user',
                                    'fn_ca_diamond_born_with_balance', 'award_diamonds_v2',
                                    'fn_purchase_time_banks_v2', 'reconcile_diamond_purchase_refund',
                                    'fn_diamond_purchase_refund', 'fn_ca_journal_profile_deletion')
      OR COALESCE(v_writer, '') LIKE 'claim_daily_challenge%'
      OR COALESCE(v_path, '') IN ('add_diamonds_to_balance', 'deduct_diamonds', 'fn_ca_mint', 'fn_ca_burn',
                                  'send_wallet_diamond_transfer', 'send_stream_gift',
                                  'claim_daily_challenge', 'claim_daily_challenges');

    INSERT INTO public.ca_diamond_balance_audit
      (user_id, old_diamonds, new_diamonds, delta, is_cert, db_role, app_name, journaled, writer, money_path)
    VALUES (NEW.id, v_old, v_new, v_delta, v_cert, current_user,
            COALESCE(current_setting('application_name', true), ''), v_journaled, v_writer, v_path);

    IF v_delta <> 0 AND NOT v_journaled AND NOT v_sanctioned THEN
      -- DR6 (DIAMOND-RULINGS 17): once flipped, an unsanctioned balance write on a player
      -- account is refused; fixtures are never refused, only filed at info.
      v_refuse := NOT v_fixture
                  AND public.fn_ca_diamond_rule_mode('DR6:balance_changed_without_journal') = 'refuse';
      PERFORM public.fn_ca_diamond_incident(
        CASE WHEN v_fixture THEN 'DR6:fixture_harness_unjournaled' ELSE 'DR6:balance_changed_without_journal' END,
        CASE WHEN v_fixture THEN 'info' ELSE 'warning' END,
        NEW.id, v_delta, COALESCE(v_writer, v_path, '(no function frame)'),
        jsonb_build_object('money_path', v_path, 'is_cert', v_cert, 'is_fixture', v_fixture, 'tg_op', TG_OP,
                           'writer', v_writer, 'old_diamonds', v_old, 'new_diamonds', v_new,
                           'db_role', current_user,
                           'app_name', COALESCE(current_setting('application_name', true), ''),
                           'journaled_at_trigger_time', v_journaled, 'sanctioned_money_path', v_sanctioned));
    END IF;
  EXCEPTION WHEN OTHERS THEN
    BEGIN
      INSERT INTO public.ca_ledger_write_failures (user_id, delta, sqlstate, message)
      VALUES (NEW.id, v_delta, SQLSTATE, 'diamond audit insert failed: ' || SQLERRM);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END;
  IF v_refuse THEN
    RAISE EXCEPTION 'DR6: profiles.diamonds may only change through a sanctioned money path (writer %, delta %)',
      COALESCE(v_writer, v_path, '(no function frame)'), v_delta
      USING ERRCODE = 'P0406', HINT = 'Use add_diamonds_to_balance, deduct_diamonds, fn_ca_mint or fn_ca_burn.';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_ca_audit_diamond_change() OWNER TO postgres;

--
-- TOC entry 45378 (class 0 OID 0)
-- Dependencies: 7243
-- Name: FUNCTION fn_ca_audit_diamond_change(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_audit_diamond_change() IS 'DR6 log-only. Appends to ca_diamond_balance_audit on every INSERT or change of profiles.diamonds, naming the writer from PG_CONTEXT and the declared app.money_path, and files DR6:balance_changed_without_journal when a non-zero delta comes from a writer that is not one of the eight sanctioned money paths. It refuses nothing and it cannot fail a diamond movement: every failure lands in ca_ledger_write_failures.';


--
-- TOC entry 6490 (class 1255 OID 137567692)
-- Name: fn_ca_authorize_funded_return(text, uuid, text, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_authorize_funded_return(p_owner text, p_source uuid, p_asset text, p_user uuid, p_amount numeric, p_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE row_data jsonb; source_reference text; total numeric; historical numeric:=0; already numeric;
 debit_id uuid; exact_debits integer; debit_amount numeric; prior public.ca_emergency_refund_provenance%ROWTYPE;
BEGIN
 IF p_owner NOT IN('shop','merch','commerce','campaign','pvp','vip_card') OR p_asset NOT IN('chips','diamonds')
  OR p_source IS NULL OR p_user IS NULL OR p_amount IS NULL OR p_amount<=0 OR p_amount<>round(p_amount,2)
  OR length(COALESCE(p_key,'')) NOT BETWEEN 1 AND 400 THEN RAISE EXCEPTION 'invalid_funded_return' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('ca-funded-return:'||p_owner||':'||p_source::text,0));
 SELECT * INTO prior FROM public.ca_emergency_refund_provenance WHERE asset=p_asset AND refund_key=p_key AND user_id=p_user FOR UPDATE;
 IF FOUND THEN
  IF prior.source_owner IS DISTINCT FROM p_owner OR prior.source_id IS DISTINCT FROM p_source OR prior.amount IS DISTINCT FROM p_amount
  THEN RAISE EXCEPTION 'funded_return_identity_changed' USING ERRCODE='22023'; END IF;
  RETURN;
 END IF;
 CASE p_owner
 WHEN 'shop' THEN
  SELECT to_jsonb(p) INTO row_data FROM public.club_shop_purchases p WHERE id=p_source FOR UPDATE;
  IF row_data->>'buyer_id' IS DISTINCT FROM p_user::text OR row_data->>'currency' IS DISTINCT FROM p_asset
   OR row_data->>'refunded_at' IS NOT NULL OR p_key IS DISTINCT FROM 'ca-shop-refund-'||p_source::text
  THEN RAISE EXCEPTION 'shop_return_identity_unproved' USING ERRCODE='P0404'; END IF;
  total:=(row_data->>'price_paid')::numeric;source_reference:=row_data->>'charge_reference';
 WHEN 'merch' THEN
  SELECT to_jsonb(p) INTO row_data FROM public.merchandise_orders p WHERE id=p_source FOR UPDATE;
  IF p_asset<>'diamonds' OR row_data->>'user_id' IS DISTINCT FROM p_user::text OR row_data->>'payment_method'<>'diamonds'
  THEN RAISE EXCEPTION 'merch_return_identity_unproved' USING ERRCODE='P0404'; END IF;
  total:=(row_data->>'diamonds_spent')::numeric;historical:=COALESCE((row_data->>'refunded_diamonds')::numeric,0);source_reference:=row_data->>'purchase_reference';
 WHEN 'commerce' THEN
  SELECT to_jsonb(p) INTO row_data FROM public.ca_commerce_purchases p WHERE id=p_source FOR UPDATE;
  IF p_asset<>'diamonds' OR row_data->>'payer_id' IS DISTINCT FROM p_user::text OR p_key NOT LIKE 'ca-commerce-refund:%'
  THEN RAISE EXCEPTION 'commerce_return_identity_unproved' USING ERRCODE='P0404'; END IF;
  total:=(row_data->>'net')::numeric;debit_id:=(row_data->>'diamond_tx_id')::uuid;
  SELECT COALESCE(sum(gross),0) INTO historical FROM public.ca_commerce_refunds WHERE purchase_id=p_source;
 WHEN 'campaign' THEN
  SELECT to_jsonb(p) INTO row_data FROM public.ad_campaign p WHERE id=p_source FOR UPDATE;
  IF p_asset<>'diamonds' OR row_data->>'submitted_by' IS DISTINCT FROM p_user::text OR p_key IS DISTINCT FROM 'adcamp-refund:'||p_source::text
  THEN RAISE EXCEPTION 'campaign_return_identity_unproved' USING ERRCODE='P0404'; END IF;
  total:=(row_data->>'diamonds_charged')::numeric;historical:=COALESCE((row_data->>'diamonds_refunded')::numeric,0);source_reference:='adcamp:'||p_source::text;
 WHEN 'pvp' THEN
  SELECT to_jsonb(p) INTO row_data FROM public.trivia_pvp_matches p WHERE id=p_source FOR UPDATE;
  IF p_asset<>'diamonds' OR p_user::text NOT IN(row_data->>'player1_id',row_data->>'player2_id')
   OR p_key NOT IN('pvp_match_win_'||p_source::text,'pvp_refund_'||p_source::text||'_'||p_user::text,'pvp_tie_refund_'||p_source::text||'_'||p_user::text)
  THEN RAISE EXCEPTION 'pvp_return_identity_unproved' USING ERRCODE='P0404'; END IF;
  source_reference:='pvp_stake_'||p_source::text||'_'||p_user::text;
  total:=(row_data->>'stake_amount')::numeric;
  IF p_key='pvp_match_win_'||p_source::text THEN
   SELECT count(*)::integer,COALESCE(sum(-amount),0),min(id::text)::uuid INTO exact_debits,debit_amount,debit_id FROM public.diamond_transactions
    WHERE (user_id=(row_data->>'player1_id')::uuid AND reference_id='pvp_stake_'||p_source::text||'_'||(row_data->>'player1_id')
     OR user_id=(row_data->>'player2_id')::uuid AND reference_id='pvp_stake_'||p_source::text||'_'||(row_data->>'player2_id')) AND amount=-total;
   IF exact_debits<>2 OR debit_amount<>2*total THEN RAISE EXCEPTION 'pvp_pot_original_debits_unproved' USING ERRCODE='P0404'; END IF;
   total:=2*total;
  END IF;
  SELECT COALESCE(sum(amount),0) INTO historical FROM public.diamond_transactions WHERE user_id=p_user AND amount>0
   AND reference_id IN('pvp_match_win_'||p_source::text,'pvp_refund_'||p_source::text||'_'||p_user::text,'pvp_tie_refund_'||p_source::text||'_'||p_user::text);
 WHEN 'vip_card' THEN
  SELECT to_jsonb(p) INTO row_data FROM public.diamond_purchases p WHERE id=p_source FOR UPDATE;
  IF p_asset<>'diamonds' OR row_data->>'user_id' IS DISTINCT FROM p_user::text OR p_key IS DISTINCT FROM 'card-redemption-refund:'||p_source::text
   OR row_data->'metadata'->'redemption_intent'->>'kind' IS DISTINCT FROM 'vip_daily'
  THEN RAISE EXCEPTION 'vip_return_identity_unproved' USING ERRCODE='P0404'; END IF;
  total:=150;source_reference:='card-redemption:'||p_source::text;
 END CASE;
 IF row_data IS NULL OR total IS NULL OR total<=0 THEN RAISE EXCEPTION 'funded_return_liability_missing' USING ERRCODE='P0404'; END IF;
 IF p_asset='diamonds' AND NOT(p_owner='pvp' AND p_key='pvp_match_win_'||p_source::text) THEN
  SELECT count(*)::integer,min(id::text)::uuid INTO exact_debits,debit_id FROM public.diamond_transactions
   WHERE user_id=p_user AND amount=-total AND (id=debit_id OR reference_id=source_reference);
 ELSIF p_asset='chips' THEN
  SELECT count(*)::integer,min(id::text)::uuid INTO exact_debits,debit_id FROM public.chip_ledger
   WHERE from_type='player_wallet' AND from_entity_id=p_user AND amount=total AND idempotency_key=source_reference
    AND to_type=ANY(public.fn_ca_noncirculating_chip_stores());
 END IF;
 IF exact_debits<>1 AND NOT(p_owner='pvp' AND exact_debits=2 AND p_key='pvp_match_win_'||p_source::text) OR debit_id IS NULL
 THEN RAISE EXCEPTION 'funded_return_original_debit_unproved' USING ERRCODE='P0404'; END IF;
 SELECT COALESCE(sum(amount),0) INTO already FROM public.ca_emergency_refund_provenance
  WHERE source_owner=p_owner AND source_id=p_source AND asset=p_asset;
 IF p_owner='pvp' THEN
  IF p_amount+already>2*(row_data->>'stake_amount')::numeric THEN RAISE EXCEPTION 'funded_return_exceeds_original_pot' USING ERRCODE='P0404'; END IF;
  SELECT COALESCE(sum(amount),0) INTO already FROM public.ca_emergency_refund_provenance
   WHERE source_owner=p_owner AND source_id=p_source AND asset=p_asset AND user_id=p_user;
 END IF;
 IF p_amount>total-GREATEST(COALESCE(historical,0),already) THEN RAISE EXCEPTION 'funded_return_exceeds_original_debit' USING ERRCODE='P0404'; END IF;
 INSERT INTO public.ca_emergency_refund_provenance(asset,refund_key,source_owner,source_id,user_id,original_debit_id,amount,state)
 VALUES(p_asset,p_key,p_owner,p_source,p_user,debit_id,p_amount,'planned');
END $$;


ALTER FUNCTION public.fn_ca_authorize_funded_return(p_owner text, p_source uuid, p_asset text, p_user uuid, p_amount numeric, p_key text) OWNER TO postgres;

--
-- TOC entry 5627 (class 1255 OID 18110862)
-- Name: fn_ca_auto_reconcile_tick(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_auto_reconcile_tick() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  inc RECORD; repaired int := 0; v_clean boolean; v_res text; v_uid uuid; v_n int;
BEGIN
  FOR inc IN
    SELECT * FROM public.ca_drift_incidents
     WHERE status IN ('open','acknowledged','reconciling')
       AND auto_repair_status IN ('pending','running')
     ORDER BY detected_at
     LIMIT 25
  LOOP
    v_clean := false; v_res := NULL;

    BEGIN
      IF inc.classification IN ('incorrect_rake','bbj_error') THEN
        -- the rake/BBJ audit covers both invariants; both redrives are
        -- idempotent, so run both regardless of which word won the classifier
        PERFORM public.fn_redrive_unbanked_rake(100);
        PERFORM public.fn_bbj_repair_unbanked(24, 200);
        v_res := 'ran fn_redrive_unbanked_rake(100) + fn_bbj_repair_unbanked(24,200)';
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_res := 'redrive failed: ' || SQLERRM;
    END;

    IF inc.source LIKE '%winner_prize_credit%' AND (inc.metadata ? 'user_id') THEN
      BEGIN
        v_uid := (inc.metadata->>'user_id')::uuid;
        SELECT EXISTS (
          SELECT 1 FROM wallet_transactions wt
           WHERE wt.user_id = v_uid AND wt.type = 'credit'
             AND wt.description LIKE 'Tournament payout reconciliation%'
             AND wt.created_at > inc.detected_at) INTO v_clean;
        IF v_clean THEN
          v_res := COALESCE(v_res || '; ', '') ||
            'payout reconciler credit verified in wallet_transactions after detection';
        END IF;
      EXCEPTION WHEN OTHERS THEN v_clean := false;
      END;
    ELSIF inc.source = 'financial_alerts:fn_rake_bbj_audit' THEN
      -- clean when no unbanked BBJ drops and no unbanked raked hands remain
      -- in the audit's 2-hour window
      SELECT count(*) INTO v_n
        FROM rake_records rr
       WHERE rr.hand_id IS NOT NULL
         AND rr.created_at > now() - interval '2 hours'
         AND rr.created_at < now() - interval '5 minutes'
         AND ((COALESCE(rr.bbj_contribution,0) > 0 AND NOT EXISTS
                (SELECT 1 FROM bbj_contributions bc WHERE bc.hand_id = rr.hand_id))
           OR (rr.rake_amount > 0 AND NOT EXISTS
                (SELECT 1 FROM rake_distribution_legs l WHERE l.leg_key = rr.hand_id)));
      v_clean := (v_n = 0);
      IF v_clean THEN
        v_res := COALESCE(v_res || '; ', '') || 'zero unbanked fees remain in the 2h audit window';
      END IF;
    ELSIF inc.entity_type = 'seat_stack_exit' AND (inc.metadata ? 'exit_id') THEN
      SELECT NOT EXISTS (
        SELECT 1 FROM public.fn_unaccounted_seat_exits('7 days'::interval) u
         WHERE u.id = (inc.metadata->>'exit_id')::bigint) INTO v_clean;
    ELSIF inc.entity_type = 'settlement_idempotency_keys' AND inc.table_id IS NOT NULL THEN
      SELECT NOT EXISTS (
        SELECT 1 FROM settlement_idempotency_keys k
         WHERE k.table_id = inc.table_id AND k.hand_id = inc.hand_id
           AND k.status = 'in_flight') INTO v_clean;
    ELSIF inc.entity_type = 'union_pnl_settlements' AND inc.entity_id IS NOT NULL THEN
      SELECT NOT EXISTS (
        SELECT 1 FROM union_pnl_settlements s
         WHERE s.id = inc.entity_id AND s.status = 'in_progress') INTO v_clean;
    ELSIF inc.entity_type = 'frozen_wallets_pool' THEN
      SELECT (SELECT COALESCE(SUM(balance),0) FROM public.wallets)
             = (SELECT frozen_total FROM public.ca_frozen_pool_baseline
                 WHERE pool = 'public.wallets') INTO v_clean;
    ELSIF inc.source = 'fn_ca_quick_reconcile:negative_balance' THEN
      v_clean := NOT EXISTS (
        SELECT 1 WHERE
          (inc.entity_type='club_treasury' AND EXISTS
            (SELECT 1 FROM clubs WHERE id = inc.entity_id AND COALESCE(chip_treasury,0) < 0))
          OR (inc.entity_type='player_wallet' AND EXISTS
            (SELECT 1 FROM club_members WHERE user_id = inc.entity_id
              AND club_id = inc.club_id
              AND COALESCE(chip_balance,0) < -COALESCE(credit_limit,0))));
    END IF;

    IF v_clean THEN
      UPDATE public.ca_drift_incidents
         SET status = 'resolved', resolved_at = now(),
             auto_repair_status = 'repaired',
             resolution = COALESCE(v_res || '; ', '') || 'source measurement re-verified clean',
             root_cause = COALESCE(root_cause,
               'Transient drift: the source measurement re-verified clean after an idempotent re-drive; no persistent code defect observed in this occurrence.'),
             -- THE LAW, SATISFIED ON ITS OWN TERMS (2026-09-01): the evidence
             -- the reconciler actually gathered IS the correction reference.
             correction_ref = COALESCE(correction_ref,
               'verified: ' || COALESCE(v_res, 'source measurement re-verified clean'))
       WHERE id = inc.id;
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (inc.id, 'repair_action',
              jsonb_build_object('action', COALESCE(v_res,'reverify'), 'result', 'clean -> resolved'));
      PERFORM public.fn_ca_incident_notify(inc.id, 'notified',
        '✅ Auto-reconciled: ' || inc.classification, false);
      repaired := repaired + 1;
    ELSIF v_res IS NOT NULL THEN
      UPDATE public.ca_drift_incidents SET auto_repair_status = 'running' WHERE id = inc.id;
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (inc.id, 'repair_action', jsonb_build_object('action', v_res, 'result', 'pending re-check'));
    ELSIF inc.auto_repair_status = 'pending'
          AND now() - inc.detected_at > interval '10 minutes' THEN
      UPDATE public.ca_drift_incidents SET auto_repair_status = 'manual_needed' WHERE id = inc.id;
      INSERT INTO public.ca_incident_events (incident_id, kind, detail)
      VALUES (inc.id, 'repair_action',
              jsonb_build_object('action', 'none applicable', 'result', 'manual_needed'));
    END IF;
  END LOOP;
  RETURN repaired;
END $$;


ALTER FUNCTION public.fn_ca_auto_reconcile_tick() OWNER TO postgres;

--
-- TOC entry 3722 (class 1255 OID 18108466)
-- Name: fn_ca_autoledger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_autoledger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  spec text; col text; acct text;
  o jsonb; nn jsonb;
  d numeric; oldv numeric; newv numeric;
  cat text; cp text; cpid uuid; cplbl text;
  v_club uuid; v_union uuid; v_entity uuid; v_guc_club uuid;
  actor uuid;
  v_st text; v_msg text;
BEGIN
  IF current_setting('app.ledger_autoskip_' || TG_TABLE_NAME, true) = '1' THEN
    RETURN NEW;
  END IF;

  o  := CASE WHEN TG_OP = 'INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;
  nn := to_jsonb(NEW);

  cat := COALESCE(NULLIF(current_setting('app.ledger_category', true), ''), 'adjustment');
  cp  := COALESCE(NULLIF(current_setting('app.ledger_counterparty', true), ''), 'settlement_suspense');
  BEGIN
    cpid := NULLIF(current_setting('app.ledger_counterparty_entity', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN cpid := NULL;
  END;
  /* THE COUNTERPARTY NAMES ITS COLUMN (2026-10-04). A union wallet holds six
     balances and a promo bank lives on three kinds of owner, so the side this
     trigger writes for a declared union_wallet or promo_wallet counterparty
     carries the column the caller declared on app.ledger_counterparty_label.
     A label that cannot belong to the declared counterparty is not written:
     a stale declaration never names the wrong account. */
  cplbl := NULLIF(current_setting('app.ledger_counterparty_label', true), '');
  cplbl := CASE
    WHEN cp = 'union_wallet' AND cplbl LIKE 'union_wallets.%' THEN cplbl
    WHEN cp = 'promo_wallet' AND cplbl IN ('clubs.promo_balance', 'agents.promo_wallet_balance',
                                           'union_wallets.promo_wallet') THEN cplbl
    ELSE NULL END;
  actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);

  /* THE JOURNAL LEG NAMES THE CLUB THE MONEY LANDED IN (2026-09-20).
     union_wallets and unions are the only autoledgered tables with no
     club_id column - `nn ? 'club_id'` is key EXISTENCE, so a table
     that has the column takes the arm above even when it is NULL. Before
     today every leg journalled from those two was written club-less, and
     fn_chip_drift_since_baseline filters movements on club_id IS NOT
     NULL while counting the balance they explain, so correctly paid
     union-hosted prizes were reported as member drift.
     A payer that knows the club declares it on
     app.ledger_autoledger_club_id, transaction-scoped, and clears it
     beside the autoskips. It is deliberately NOT app.ledger_club_id:
     that name is taken and decides which club a WALLET credit is paid
     into (atomic_credit_wallet_and_log, atomic_deduct_wallet_and_log,
     log_wallet_transaction), so borrowing it would let a rakeback
     close's club leak onto a union leg and would move real money when
     cleared. Read through an exception guard exactly as cpid is above:
     a malformed value must never abort a chip movement. */
  BEGIN
    v_guc_club := NULLIF(current_setting('app.ledger_autoledger_club_id', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN v_guc_club := NULL;
  END;
  v_club := CASE
    WHEN TG_TABLE_NAME = 'clubs' THEN (nn->>'id')::uuid
    WHEN nn ? 'club_id' THEN NULLIF(nn->>'club_id','')::uuid
    ELSE v_guc_club END;
  v_union := CASE
    WHEN TG_TABLE_NAME = 'unions' THEN (nn->>'id')::uuid
    WHEN nn ? 'union_id' THEN NULLIF(nn->>'union_id','')::uuid
    ELSE NULL END;
  v_entity := CASE
    WHEN TG_TABLE_NAME = 'agents' THEN NULLIF(nn->>'user_id','')::uuid
    WHEN TG_TABLE_NAME = 'club_members' THEN NULLIF(nn->>'user_id','')::uuid
    ELSE COALESCE(NULLIF(nn->>'id','')::uuid, v_club, v_union) END;

  FOR i IN 0 .. TG_NARGS - 1 LOOP
    spec := TG_ARGV[i];
    col  := split_part(spec, '=', 1);
    acct := split_part(spec, '=', 2);
    oldv := COALESCE(NULLIF(o->>col,'')::numeric, 0);
    newv := COALESCE(NULLIF(nn->>col,'')::numeric, 0);
    d := round(newv - oldv, 2);
    CONTINUE WHEN d = 0;
    /* THE AUTOLEDGER NEVER JOURNALS AN ACCOUNT TO ITSELF (2026-10-15). A leg
       whose counterparty is this very account, unlabelled, is from and to the
       same account (2026-10-06 15:42 KF player to three club treasuries;
       2026-09-17 16:39/16:41 treasury to promo). It nets to zero in every
       tally, so it is not written. A bbj_pool, a union_wallet and a promo bank
       off a club hold more than one column under one key, and their bare
       self-legs are the only record of which column moved: kept. */
    CONTINUE WHEN cp = acct AND cpid IS NOT DISTINCT FROM v_entity AND cplbl IS NULL
              AND acct NOT IN ('bbj_pool', 'union_wallet')
              AND (acct <> 'promo_wallet' OR TG_TABLE_NAME = 'clubs');

    BEGIN
      INSERT INTO public.chip_ledger
        (performed_by, from_type, from_entity_id, from_label,
         to_type, to_entity_id, to_label,
         amount, category, club_id, union_id, description,
         pre_from_balance, post_from_balance, pre_to_balance, post_to_balance)
      VALUES (actor,
        CASE WHEN d > 0 THEN cp   ELSE acct END,
        CASE WHEN d > 0 THEN cpid ELSE v_entity END,
        CASE WHEN d > 0 THEN cplbl ELSE TG_TABLE_NAME || '.' || col END,
        CASE WHEN d > 0 THEN acct ELSE cp END,
        CASE WHEN d > 0 THEN v_entity ELSE cpid END,
        CASE WHEN d > 0 THEN TG_TABLE_NAME || '.' || col ELSE cplbl END,
        abs(d), cat, v_club, v_union,
        'auto-ledgered ' || TG_TABLE_NAME || '.' || col || ' delta ' || d::text,
        CASE WHEN d < 0 THEN oldv END, CASE WHEN d < 0 THEN newv END,
        CASE WHEN d > 0 THEN oldv END, CASE WHEN d > 0 THEN newv END);
    EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;
  END LOOP;

  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_autoledger() OWNER TO postgres;

--
-- TOC entry 4048 (class 1255 OID 18300106)
-- Name: fn_ca_autoledger_delete(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_autoledger_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  spec text; col text; acct text;
  o jsonb; oldv numeric;
  v_club uuid; v_union uuid; v_entity uuid; actor uuid;
  v_st text; v_msg text;
BEGIN
  IF current_setting('app.ledger_autoskip_' || TG_TABLE_NAME, true) = '1' THEN
    RETURN OLD;
  END IF;

  o := to_jsonb(OLD);
  actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);
  v_club := CASE
    WHEN TG_TABLE_NAME = 'clubs' THEN (o->>'id')::uuid
    WHEN o ? 'club_id' THEN NULLIF(o->>'club_id','')::uuid
    ELSE NULL END;
  v_union := CASE
    WHEN TG_TABLE_NAME = 'unions' THEN (o->>'id')::uuid
    WHEN o ? 'union_id' THEN NULLIF(o->>'union_id','')::uuid
    ELSE NULL END;
  v_entity := CASE
    WHEN TG_TABLE_NAME IN ('agents','club_members') THEN NULLIF(o->>'user_id','')::uuid
    ELSE COALESCE(NULLIF(o->>'id','')::uuid, v_club, v_union) END;

  FOR i IN 0 .. TG_NARGS - 1 LOOP
    spec := TG_ARGV[i];
    col  := split_part(spec, '=', 1);
    acct := split_part(spec, '=', 2);
    oldv := round(COALESCE(NULLIF(o->>col,'')::numeric, 0), 2);
    CONTINUE WHEN oldv = 0;

    BEGIN
      INSERT INTO public.chip_ledger
        (performed_by, from_type, from_entity_id, from_label,
         to_type, to_entity_id, to_label,
         amount, category, club_id, union_id, description,
         pre_from_balance, post_from_balance)
      VALUES (actor,
        acct, v_entity, TG_TABLE_NAME || '.' || col,
        'chip_retirement', NULL, NULL,
        abs(oldv), CASE WHEN oldv > 0 THEN 'burn' ELSE 'correction' END,
        v_club, v_union,
        'auto-ledgered ' || TG_TABLE_NAME || '.' || col || ' balance ' || oldv::text
          || ' retired on row delete',
        oldv, 0);
    EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;
  END LOOP;

  RETURN OLD;
END $$;


ALTER FUNCTION public.fn_ca_autoledger_delete() OWNER TO postgres;

--
-- TOC entry 7893 (class 1255 OID 18777846)
-- Name: fn_ca_backpay_guarantee_shortfalls(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_backpay_guarantee_shortfalls(p_apply boolean DEFAULT false, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  t record;
  v_short numeric; v_union uuid; v_bank numeric; v_from text; v_actor uuid;
  v_events int := 0; v_chips numeric := 0; v_distributed numeric := 0;
  v_skipped jsonb := '[]'::jsonb; v_rec jsonb;
BEGIN
  SELECT performed_by INTO v_actor
    FROM public.chip_ledger
   WHERE category = 'overlay' AND performed_by IS NOT NULL
   ORDER BY created_at DESC LIMIT 1;
  IF v_actor IS NULL THEN
    SELECT id INTO v_actor FROM public.profiles WHERE role = 'god' ORDER BY created_at LIMIT 1;
  END IF;
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no operator account to attribute the back-payment to');
  END IF;

  FOR t IN
    WITH candidates AS (
      SELECT tt.id, tt.name, tt.club_id, tt.guaranteed_prize, tt.prize_pool, tt.ended_at,
             COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
                        WHERE w.related_entity_id = tt.id AND w.type='credit'
                          AND w.category IN ('prize','bounty')),0) AS paid_all,
             (SELECT count(*) FROM public.tournament_players tp
               WHERE tp.tournament_id = tt.id) AS players
        FROM public.tournaments tt
       WHERE tt.status = 'COMPLETED'
         AND COALESCE(tt.tournament_type,'') = 'MTT'
         AND COALESCE(tt.variant,'') NOT IN ('satellite','spin')
         AND COALESCE(tt.guaranteed_prize,0) > 0
    )
    SELECT * FROM candidates
     WHERE paid_all < guaranteed_prize - 0.01
     ORDER BY ended_at
     LIMIT GREATEST(p_limit,1)
  LOOP
    v_short := round(t.guaranteed_prize - t.paid_all, 2);

    IF t.players = 0 THEN
      v_skipped := v_skipped || jsonb_build_object('tournament', t.name, 'why', 'no finishers recorded');
      CONTINUE;
    END IF;

    v_events := v_events + 1;
    v_chips  := v_chips + v_short;

    IF NOT p_apply THEN CONTINUE; END IF;

    SELECT union_id INTO v_union FROM public.clubs WHERE id = t.club_id;
    v_from := 'union_bank'; v_bank := NULL;
    IF v_union IS NOT NULL THEN
      SELECT chip_balance INTO v_bank FROM public.union_wallets
       WHERE union_id = v_union FOR UPDATE;
    END IF;
    IF v_union IS NULL OR COALESCE(v_bank,0) < v_short THEN
      SELECT chip_treasury INTO v_bank FROM public.clubs WHERE id = t.club_id FOR UPDATE;
      v_from := 'club_treasury';
    END IF;
    IF COALESCE(v_bank,0) < v_short THEN
      v_skipped := v_skipped || jsonb_build_object('tournament', t.name,
                     'why', 'bank short', 'needed', v_short, 'bank', COALESCE(v_bank,0));
      v_events := v_events - 1; v_chips := v_chips - v_short;
      CONTINUE;
    END IF;

    IF v_from = 'union_bank' THEN
      PERFORM set_config('app.ledger_autoskip_union_wallets', '1', true);
      UPDATE public.union_wallets SET chip_balance = chip_balance - v_short
       WHERE union_id = v_union;
      PERFORM set_config('app.ledger_autoskip_union_wallets', '0', true);
    ELSE
      PERFORM set_config('app.ledger_autoskip_clubs', '1', true);
      UPDATE public.clubs SET chip_treasury = chip_treasury - v_short WHERE id = t.club_id;
      PERFORM set_config('app.ledger_autoskip_clubs', '0', true);
    END IF;

    -- The pool must show the overlay before the reconciler reads it: expected
    -- is pool x structure, so raising the pool IS what makes each place's
    -- entitlement come out at the guaranteed level.
    UPDATE public.tournaments
       SET prize_pool = round(GREATEST(COALESCE(prize_pool,0), t.guaranteed_prize), 2)
     WHERE id = t.id;

    INSERT INTO public.chip_ledger
      (amount, category, from_type, from_entity_id, to_type, to_entity_id,
       club_id, status, performed_by, description, idempotency_key, metadata)
    VALUES (v_short, 'overlay',
            CASE WHEN v_from='union_bank' THEN 'union_bank' ELSE 'club_treasury' END,
            CASE WHEN v_from='union_bank' THEN v_union ELSE t.club_id END,
            'prize_liability', t.id, t.club_id, 'posted', v_actor,
            format('Guarantee shortfall back-payment from the main bank: %s was %s short of its %s guarantee - players had been paid %s',
                   t.name, v_short, round(t.guaranteed_prize,2), round(t.paid_all,2)),
            'guarantee-backpay:' || t.id::text,
            jsonb_build_object('tournament_id', t.id, 'shortfall', v_short,
                               'guarantee', t.guaranteed_prize, 'already_paid', t.paid_all,
                               'distributed_by', 'fn_tournament_payout_reconcile',
                               'money_path', 'fn_settle_tournament_obligation'))
    ON CONFLICT DO NOTHING;

    -- DISTRIBUTION IS NOT THIS FUNCTION'S JOB. The reconciler owns the
    -- structure, tops up each place to its entitlement through
    -- fn_settle_tournament_obligation (Lane A3, 2026-09-02), which writes the
    -- tournament_payouts rows and never claws back.
    v_rec := public.fn_tournament_payout_reconcile(t.id, true);
    v_distributed := v_distributed + COALESCE((v_rec->>'total_settled')::numeric, (v_rec->>'total_top_up')::numeric, 0);
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'applied', p_apply,
                            'events', v_events, 'funded', round(v_chips,2),
                            'distributed', round(v_distributed,2), 'skipped', v_skipped,
                            'money_path', 'fn_settle_tournament_obligation');
END;
$$;


ALTER FUNCTION public.fn_ca_backpay_guarantee_shortfalls(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- TOC entry 6866 (class 1255 OID 18201235)
-- Name: fn_ca_balance_asof(text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_balance_asof(p_type text, p_entity uuid, p_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record;
BEGIN
  SELECT * INTO r FROM (
    SELECT l.id, l.created_at, l.post_from_balance AS balance, 'from' AS side
      FROM public.chip_ledger l
     WHERE l.from_type = p_type AND l.from_entity_id = p_entity
       AND l.created_at <= p_at AND l.post_from_balance IS NOT NULL
     ORDER BY l.created_at DESC LIMIT 1
  ) f
  UNION ALL
  SELECT * FROM (
    SELECT l.id, l.created_at, l.post_to_balance AS balance, 'to' AS side
      FROM public.chip_ledger l
     WHERE l.to_type = p_type AND l.to_entity_id = p_entity
       AND l.created_at <= p_at AND l.post_to_balance IS NOT NULL
     ORDER BY l.created_at DESC LIMIT 1
  ) t
  ORDER BY created_at DESC LIMIT 1;

  IF r.id IS NULL THEN
    RETURN jsonb_build_object('found', false, 'account_type', p_type, 'entity_id', p_entity,
      'as_of', p_at, 'note', 'no ledger row with a recorded balance at or before this time');
  END IF;
  RETURN jsonb_build_object('found', true, 'account_type', p_type, 'entity_id', p_entity,
    'as_of', p_at, 'balance', r.balance, 'recorded_at', r.created_at,
    'ledger_row', r.id, 'side', r.side);
END $$;


ALTER FUNCTION public.fn_ca_balance_asof(p_type text, p_entity uuid, p_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 4378 (class 1255 OID 18284491)
-- Name: fn_ca_balance_asof_admin(text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_balance_asof_admin(p_entity_type text, p_entity_id uuid, p_asof timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_service boolean := COALESCE(auth.role(), '') = 'service_role';
  v_global boolean;
BEGIN
  IF NOT public.fn_ca_can_view_drift_console() THEN
    RAISE EXCEPTION 'drift console reviewer required' USING ERRCODE = '42501';
  END IF;

  v_global := v_service
    OR COALESCE(public.fn_is_platform_admin(), false)
    OR EXISTS (
      SELECT 1
        FROM public.ca_incident_recipients r
       WHERE r.user_id = v_uid
         AND r.active
         AND r.scope IN ('platform', 'financial_ops', 'technical')
    );
  IF NOT v_global THEN RETURN NULL; END IF;
  RETURN public.fn_ca_balance_asof(p_entity_type, p_entity_id, p_asof);
END
$$;


ALTER FUNCTION public.fn_ca_balance_asof_admin(p_entity_type text, p_entity_id uuid, p_asof timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 9237 (class 1255 OID 83551271)
-- Name: fn_ca_balance_has_its_ledger_row(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_balance_has_its_ledger_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_ver text := NULLIF(current_setting('ca.ledger_tally_ver', true), '');
  v_checked text := NULLIF(current_setting('ca.ledger_tally_checked', true), '');
  v_mode text;
  t jsonb;
  r record;
  v_b numeric; v_l numeric;
  v_s numeric; v_moved text; v_moved_abs numeric;
BEGIN
  /* Deferred to commit. Every queued event re-enters here, so the tally is
     verified once per version: when nothing has been added since the last
     verification this is one setting read and out. A deferred trigger that
     writes money after us bumps the version and queues its own event, which
     verifies again, so the last word is always on the complete tally. */
  IF v_ver IS NULL OR v_ver = v_checked THEN
    RETURN NULL;
  END IF;

  t := COALESCE(NULLIF(current_setting('ca.ledger_tally', true), '')::jsonb, '{}'::jsonb);

  FOR r IN SELECT key, value FROM jsonb_each(t) LOOP
    v_b := round(COALESCE((r.value ->> 'b')::numeric, 0), 2);
    v_l := round(COALESCE((r.value ->> 'l')::numeric, 0), 2);
    IF v_b = v_l THEN
      CONTINUE;
    END IF;

    /* 2026-10-02: each store is judged by its own mode
       (ca_ledger_invariant_store_mode, keyed by the account-key prefix), so a
       store still being measured records a finding while a proven store
       refuses. A store with no row falls back to the one global row. */
    v_mode := COALESCE(
      (SELECT sm.mode FROM public.ca_ledger_invariant_store_mode sm WHERE sm.store = split_part(r.key, ':', 1)),
      (SELECT m.mode FROM public.ca_ledger_invariant_mode m LIMIT 1),
      'refuse');

    IF v_mode = 'refuse' THEN
      /* 20261002135708: the refusal rolls this transaction back, so it is
         recorded first on the recorder's own connection, which commits on
         its own. The recorder never raises and never changes the refusal. */
      BEGIN
        PERFORM public.fn_ca_ledger_refusal_record(jsonb_build_object(
          'kind',          'balance_moved_without_its_ledger_row',
          'account_key',   r.key,
          'store',         split_part(r.key, ':', 1),
          'balance_delta', v_b,
          'ledger_net',    v_l,
          'mode',          v_mode,
          'first_writer',  left(COALESCE(r.value ->> 'q', '(unknown statement)'), 1000),
          'message',       format('REFUSED: balance_moved_without_its_ledger_row account=%s balance_delta=%s ledger_net=%s', r.key, v_b, v_l)));
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
      RAISE EXCEPTION 'REFUSED: balance_moved_without_its_ledger_row account=% balance_delta=% ledger_net=%',
        r.key, v_b, v_l
        USING ERRCODE = '23514',
              DETAIL  = CASE
                          WHEN v_l = 0 THEN 'the balance column moved and no chip_ledger leg in this transaction accounts for it'
                          WHEN v_b = 0 THEN 'a chip_ledger leg names this account and its balance column did not move in this transaction'
                          ELSE 'the balance column and the chip_ledger legs in this transaction disagree on how much moved'
                        END || '; first written in this transaction by: ' || COALESCE(r.value ->> 'q', '(unknown statement)'),
              HINT    = 'Every chip movement is written by its door as balance + leg in one transaction. If the door stood the autoledger down (app.ledger_autoskip_<table>), its own leg must equal the delta and name the same user, club, union, pool, table, tournament or ticket float. Nothing is corrected here; the transaction is refused whole.';
    END IF;

    INSERT INTO public.ca_ledger_invariant_findings
      (txid, account_key, balance_delta, ledger_net, mode, actor_service, db_role, statement)
    VALUES
      (pg_current_xact_id(), r.key, v_b, v_l, v_mode,
       current_setting('application_name', true), current_user,
       COALESCE(r.value ->> 'q', left(current_query(), 300)))
    ON CONFLICT (txid, account_key) DO UPDATE
      SET balance_delta = EXCLUDED.balance_delta,
          ledger_net    = EXCLUDED.ledger_net,
          found_at      = EXCLUDED.found_at,
          statement     = EXCLUDED.statement;
    RAISE WARNING 'OBSERVED: balance_moved_without_its_ledger_row account=% balance_delta=% ledger_net=% (store mode observe; this transaction would be refused)',
      r.key, v_b, v_l;
  END LOOP;

  /* NO BALANCE MOVES AGAINST SETTLEMENT SUSPENSE (2026-10-02). Every store
     above can balance and the chips still come from nowhere: a journal
     trigger whose writer declared no counterparty posts the store's leg
     against settlement_suspense, which holds no balance and is outside the
     supply count. A transaction that wrote a suspense leg may not move any
     covered balance. A journal-only suspense correction moves none. */
  v_s := round(COALESCE((t -> 'settlement_suspense' ->> 's')::numeric, 0), 2);
  IF v_s <> 0 THEN
    SELECT string_agg(e.key || ' ' || round((e.value ->> 'b')::numeric, 2)::text, ', ' ORDER BY e.key),
           sum(abs(round((e.value ->> 'b')::numeric, 2)))
      INTO v_moved, v_moved_abs
      FROM jsonb_each(t) e
     WHERE e.key <> 'settlement_suspense'
       AND round(COALESCE((e.value ->> 'b')::numeric, 0), 2) <> 0;

    IF v_moved IS NOT NULL THEN
      v_mode := COALESCE(
        (SELECT sm.mode FROM public.ca_ledger_invariant_store_mode sm WHERE sm.store = 'settlement_suspense'),
        (SELECT m.mode FROM public.ca_ledger_invariant_mode m LIMIT 1),
        'refuse');

      IF v_mode = 'refuse' THEN
        /* 20261002135708: recorded first, outside the rollback. */
        BEGIN
          PERFORM public.fn_ca_ledger_refusal_record(jsonb_build_object(
            'kind',          'balance_moved_against_settlement_suspense',
            'account_key',   'settlement_suspense',
            'store',         'settlement_suspense',
            'balance_delta', v_moved_abs,
            'ledger_net',    v_s,
            'mode',          v_mode,
            'moved',         left(v_moved, 2000),
            'first_writer',  left(COALESCE(t -> 'settlement_suspense' ->> 'q', '(unknown statement)'), 1000),
            'message',       format('REFUSED: balance_moved_against_settlement_suspense suspense_legs=%s moved=%s', v_s, left(v_moved, 1500))));
        EXCEPTION WHEN OTHERS THEN
          NULL;
        END;
        RAISE EXCEPTION 'REFUSED: balance_moved_against_settlement_suspense suspense_legs=% moved=%',
          v_s, v_moved
          USING ERRCODE = '23514',
                DETAIL  = 'this transaction wrote a chip_ledger leg against settlement_suspense, which holds no balance and is outside the supply count, and moved a covered chip balance; the suspense leg was first written by: '
                          || COALESCE(t -> 'settlement_suspense' ->> 'q', '(unknown statement)'),
                HINT    = 'A door names where its chips come from and go to: app.ledger_counterparty (+ app.ledger_counterparty_entity) before the balance write, or app.ledger_autoskip_<table> and its own leg. An undeclared journal trigger falls to settlement_suspense, and that is what is refused here. A journal-only correction that moves no balance is not affected.';
      END IF;

      INSERT INTO public.ca_ledger_invariant_findings
        (txid, account_key, balance_delta, ledger_net, mode, actor_service, db_role, statement)
      VALUES
        (pg_current_xact_id(), 'settlement_suspense', v_moved_abs, v_s, v_mode,
         current_setting('application_name', true), current_user,
         left(COALESCE(t -> 'settlement_suspense' ->> 'q', left(current_query(), 300)) || ' | moved: ' || v_moved, 1000))
      ON CONFLICT (txid, account_key) DO UPDATE
        SET balance_delta = EXCLUDED.balance_delta,
            ledger_net    = EXCLUDED.ledger_net,
            found_at      = EXCLUDED.found_at,
            statement     = EXCLUDED.statement;
      RAISE WARNING 'OBSERVED: balance_moved_against_settlement_suspense suspense_legs=% moved=% (mode observe; this transaction would be refused)',
        v_s, v_moved;
    END IF;
  END IF;

  PERFORM set_config('ca.ledger_tally_checked', v_ver, true);
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_balance_has_its_ledger_row() OWNER TO postgres;

--
-- TOC entry 8173 (class 1255 OID 57415992)
-- Name: fn_ca_balance_table_fingerprint(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_balance_table_fingerprint() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  /* Order-independent content hash of every balance-bearing row. Compared
     inside ONE repeatable-read snapshot, equality means this transaction wrote
     no balance anywhere. */
  SELECT jsonb_build_object(
    'club_members',        (SELECT jsonb_build_array(count(*), sum(hashtextextended(t::text, 0)::numeric)) FROM public.club_members t),
    'clubs',               (SELECT jsonb_build_array(count(*), sum(hashtextextended(t::text, 0)::numeric)) FROM public.clubs t),
    'club_wallets',        (SELECT jsonb_build_array(count(*), sum(hashtextextended(t::text, 0)::numeric)) FROM public.club_wallets t),
    'union_wallets',       (SELECT jsonb_build_array(count(*), sum(hashtextextended(t::text, 0)::numeric)) FROM public.union_wallets t),
    'agents',              (SELECT jsonb_build_array(count(*), sum(hashtextextended(t::text, 0)::numeric)) FROM public.agents t),
    'bbj_pools',           (SELECT jsonb_build_array(count(*), sum(hashtextextended(t::text, 0)::numeric)) FROM public.bbj_pools t),
    'spin_bonus_pools',    (SELECT jsonb_build_array(count(*), sum(hashtextextended(t::text, 0)::numeric)) FROM public.spin_bonus_pools t),
    'tournaments',         (SELECT jsonb_build_array(count(*), sum(hashtextextended(t::text, 0)::numeric)) FROM public.tournaments t),
    'tournament_escrow',   (SELECT jsonb_build_array(count(*), sum(hashtextextended(t::text, 0)::numeric)) FROM public.tournament_escrow t),
    'table_seats',         (SELECT jsonb_build_array(count(*), sum(hashtextextended(t::text, 0)::numeric)) FROM public.table_seats t),
    'chip_escrow',         (SELECT jsonb_build_array(count(*), sum(hashtextextended(t::text, 0)::numeric)) FROM public.chip_escrow t),
    'chip_escrow_holds',   (SELECT jsonb_build_array(count(*), sum(hashtextextended(t::text, 0)::numeric)) FROM public.chip_escrow_holds t),
    'wallets',             (SELECT jsonb_build_array(count(*), sum(hashtextextended(t::text, 0)::numeric)) FROM public.wallets t),
    'tournament_tickets',  (SELECT jsonb_build_array(count(*), sum(hashtextextended(t::text, 0)::numeric)) FROM public.tournament_tickets t),
    'club_opening_setups', (SELECT jsonb_build_array(count(*), sum(hashtextextended(t::text, 0)::numeric)) FROM public.club_opening_setups t))
$$;


ALTER FUNCTION public.fn_ca_balance_table_fingerprint() OWNER TO postgres;

--
-- TOC entry 4999 (class 1255 OID 20091287)
-- Name: fn_ca_ban_club_player(uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ban_club_player(p_club_id uuid, p_user_id uuid, p_reason text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller    uuid := auth.uid();
  v_role      text;
  v_agent     uuid;
  v_chips     numeric;
  v_credit    numeric;
  v_seats     integer;
  v_blacklist uuid;
  v_re_ban    boolean := false;
BEGIN
  IF NOT fn_ca_can_manage_agents(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_player');
  END IF;

  -- Banning the person who holds the club is how a club loses its owner.
  IF EXISTS (SELECT 1 FROM clubs c WHERE c.id = p_club_id AND c.owner_id = p_user_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'cannot_ban_the_owner');
  END IF;

  SELECT cm.role,
         cm.agent_id,
         coalesce(cm.chip_balance, 0) + coalesce(cm.held_chips, 0)
           + coalesce(cm.locked_chips, 0) + coalesce(cm.promo_balance, 0),
         coalesce(cm.credit_used, 0)
    INTO v_role, v_agent, v_chips, v_credit
    FROM club_members cm
   WHERE cm.club_id = p_club_id AND cm.user_id = p_user_id;

  IF v_role IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_member_of_this_club');
  END IF;

  IF v_role IN ('owner', 'co_owner', 'admin') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'cannot_ban_club_staff');
  END IF;

  -- An existing exclusion for this pair is replaced rather than duplicated.
  -- Written as a lookup and a branch rather than ON CONFLICT because the
  -- unique index here is partial (permanent rows only), so a timed ban does
  -- not match the arbiter and the two cases are clearer spelled out. A re-ban
  -- is the same ban and files no second audit event.
  SELECT b.id INTO v_blacklist
    FROM blacklists b
   WHERE b.club_id = p_club_id AND b.user_id = p_user_id
   LIMIT 1;

  v_re_ban := v_blacklist IS NOT NULL;

  IF v_re_ban THEN
    UPDATE blacklists b
       SET reason = coalesce(nullif(btrim(coalesce(p_reason, '')), ''), b.reason),
           banned_by = v_caller,
           banned_at = now(),
           expires_at = p_expires_at
     WHERE b.id = v_blacklist;
  ELSE
    INSERT INTO blacklists (club_id, user_id, reason, banned_by, banned_at, expires_at)
    VALUES (p_club_id, p_user_id,
            nullif(btrim(coalesce(p_reason, '')), ''),
            v_caller, now(), p_expires_at)
    RETURNING id INTO v_blacklist;
  END IF;

  -- What the operator now has to deal with, said plainly rather than left for
  -- them to discover: an excluded player who is still sitting, and whatever
  -- the membership row is still holding.
  SELECT count(*)::integer INTO v_seats
    FROM table_seats ts
    JOIN tables t ON t.id = ts.table_id
   WHERE t.club_id = p_club_id
     AND ts.user_id = p_user_id
     AND ts.left_at IS NULL;

  RETURN jsonb_build_object(
    'ok', true,
    'blacklist_id', v_blacklist,
    'was_already_excluded', v_re_ban,
    'expires_at', p_expires_at,
    'was_role', v_role,
    'had_agent', v_agent,
    'chips_held', v_chips,
    'credit_used', v_credit,
    'live_seats', coalesce(v_seats, 0));
END;
$$;


ALTER FUNCTION public.fn_ca_ban_club_player(p_club_id uuid, p_user_id uuid, p_reason text, p_expires_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 8597 (class 1255 OID 18219703)
-- Name: fn_ca_banned_copy_characters(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_banned_copy_characters() RETURNS TABLE(kind text, object_name text, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  WITH lines AS (
    SELECT p.proname, p.oid::regprocedure::text AS sig, l
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    CROSS JOIN LATERAL unnest(string_to_array(p.prosrc, E'\n')) AS l
    WHERE n.nspname = 'public'
      AND p.prokind = 'f'
      -- The checker is allowed to hold the characters it checks for. Same
      -- exemption check-ui-text.mjs keeps for titleCase.ts and popupStyle.ts:
      -- without this the function reports ITSELF forever and never passes.
      AND p.proname <> 'fn_ca_banned_copy_characters'
  )
  SELECT 'dash'::text, sig, left(trim(l), 200)
  FROM lines
  WHERE l ~ '[‒–—―]'
  UNION ALL
  SELECT 'emoji'::text, sig, left(trim(l), 200)
  FROM lines
  -- The pictograph planes, plus the four BMP characters this product actually
  -- uses AS emoji. Arrows and check/cross glyphs are deliberately NOT here:
  -- the first version of this gate matched them and reported '->' inside a
  -- HINT and '* NEW:' in a comment, which is how a gate earns its own deletion.
  WHERE l ~ '[\U0001F000-\U0001FAFF✨⭐✅❌]'
    -- Operator dashboards and admin alerts, exempted in the open: glyphs as
    -- status columns and severity flags for staff, not copy on a page. A NAME
    -- LIST rather than a pattern, because a pattern quietly grows to cover
    -- whatever somebody names next.
    AND proname NOT IN (
      'fn_ca_incident_action',
      'fn_ca_incident_escalation_tick',
      'fn_ca_incident_notify',
      'fn_ca_raise_drift_incident',
      'fn_ca_auto_reconcile_tick',
      'fn_ca_burnin_gate_tick',
      'fn_ca_daily_attestation',
      'fn_submit_bug_report_to_admin',
      'verify_home_games_health_core',
      'verify_home_games_health_addendum'
    )
  ORDER BY 1, 2, 3;
$$;


ALTER FUNCTION public.fn_ca_banned_copy_characters() OWNER TO postgres;

--
-- TOC entry 45390 (class 0 OID 0)
-- Dependencies: 8597
-- Name: FUNCTION fn_ca_banned_copy_characters(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_banned_copy_characters() IS 'Every line of every public function that breaks one of Dan''s two character bans: a dash character (banned 2026-08-20) or an emoji in player-facing copy (design-guidelines.md rule 1). Empty is the only passing result. Read by scripts/ci/check-db-copy.mjs. Operator dashboards are exempted by name, in the function body.';


--
-- TOC entry 7896 (class 1255 OID 38568706)
-- Name: fn_ca_begin_legacy_fee_resolution(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_begin_legacy_fee_resolution(p_tournament_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE o public.accounting_tournament_fee_custody_obligations%ROWTYPE;plan jsonb;raw record;
BEGIN
 SELECT * INTO o FROM public.accounting_tournament_fee_custody_obligations WHERE tournament_id=p_tournament_id;
 IF NOT FOUND OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_custody_resolutions WHERE tournament_id=p_tournament_id) THEN RETURN; END IF;
 PERFORM public.fn_ca_lock_settlement_lane_global();
 PERFORM 1 FROM public.tournaments WHERE id=p_tournament_id FOR NO KEY UPDATE;
 PERFORM 1 FROM public.tournament_escrow WHERE tournament_id=p_tournament_id FOR UPDATE;
 PERFORM public.fn_ca_tournament_terminal_receipt(p_tournament_id,NULL);
 INSERT INTO public.accounting_tournament_fee_custody_capture_admissions
  (tournament_id,obligation_id,source_fingerprint,amount)
 VALUES(p_tournament_id,o.id,o.source_fingerprint,o.amount);
 FOR raw IN SELECT r.id FROM public.rake_records r WHERE r.tournament_id=p_tournament_id
  AND r.is_tournament AND r.rake_amount>0
  AND NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches b WHERE b.rake_record_id=r.id)
  ORDER BY r.id LOOP
  PERFORM public.fn_ca_capture_tournament_fee_from_recorded_evidence(raw.id);
 END LOOP;
 plan:=public.fn_accounting_tournament_fee_net_plan(p_tournament_id);
 IF plan->>'status' IS DISTINCT FROM 'proven' OR plan->>'source_fingerprint' IS DISTINCT FROM o.source_fingerprint
  OR (plan->>'net_fee')::numeric IS DISTINCT FROM o.amount
  OR jsonb_array_length(plan->'active_source_ids')<1
  OR (public.fn_ca_sep8_spin_original_fee_proof(p_tournament_id) IS NOT NULL AND jsonb_array_length(plan->'active_source_ids')<>3)
 THEN RAISE EXCEPTION 'original fee continuation requires exact canonical attribution proof' USING ERRCODE='P0404'; END IF;
 INSERT INTO public.accounting_tournament_fee_custody_resolutions
  (tournament_id,obligation_id,amount,source_fingerprint,original_plan)
 VALUES(p_tournament_id,o.id,o.amount,o.source_fingerprint,plan);
END $$;


ALTER FUNCTION public.fn_ca_begin_legacy_fee_resolution(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 5366 (class 1255 OID 30772711)
-- Name: fn_ca_blind_contract_number(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_blind_contract_number(p_value jsonb) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE v numeric; t text:=p_value #>> '{}';
BEGIN
  IF jsonb_typeof(p_value) NOT IN ('number','string') OR t !~ '^[0-9]+([.][0-9]+)?$' THEN RETURN NULL; END IF;
  v:=t::numeric;
  IF v>9007199254740991 THEN RETURN NULL; END IF;
  RETURN v;
END;
$_$;


