COMMENT ON FUNCTION public.fn_ca_bomb_pot_catchup(p_club_id uuid, p_days integer) IS 'Seals any finished day in the window that has no marker yet, newest first, at most forty per call. Called by fn_club_bomb_pot_report so the rollup needs no scheduler.';


--
-- TOC entry 9082 (class 1255 OID 21213909)
-- Name: fn_ca_bomb_pot_rollup_day(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_bomb_pot_rollup_day(p_club_id uuid, p_day date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    SET work_mem TO '64MB'
    SET enable_indexscan TO 'off'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
DECLARE
  v_rows  integer := 0;
  v_hands bigint  := 0;
BEGIN
  IF p_club_id IS NULL OR p_day IS NULL THEN
    RETURN 0;
  END IF;

  -- A day is finished fifteen minutes after it ends, never before. See the
  -- header: bomb_pot_award_units can land a moment late and a sealed day is
  -- not recomputed.
  IF ((p_day+1)::timestamp AT TIME ZONE 'UTC') > now() - interval '15 minutes' THEN
    RETURN 0;
  END IF;

  -- Closed-day publication is a single, immutable state transition.
  PERFORM pg_advisory_xact_lock(hashtextextended('ca-bomb-day:'||p_club_id::text||':'||(p_day-DATE '2000-01-01')::text,0));
  SELECT c.rows_written INTO v_rows FROM public.ca_club_bomb_pot_complete c
   WHERE c.club_id=p_club_id AND c.day=p_day;
  IF FOUND THEN RETURN COALESCE(v_rows,0); END IF;

  DELETE FROM public.ca_club_bomb_pot_daily d
   WHERE d.club_id = p_club_id AND d.day = p_day;

  WITH bomb_candidates AS MATERIALIZED (
    SELECT h.id,h.table_id,h.bomb_pot,h.created_at,h.pot_size,h.rake_amount,h.players
      FROM public.hand_history h
     WHERE h.bomb_pot IS NOT NULL
       AND h.created_at >= (p_day::timestamp AT TIME ZONE 'UTC')
       AND h.created_at < ((p_day+1)::timestamp AT TIME ZONE 'UTC')
  ), bomb_hands AS (
    SELECT h.id,
           h.table_id,
           h.bomb_pot ->> 'trigger_reason'                       AS trigger_reason,
           (h.bomb_pot ->> 'board_count')::int                   AS board_count,
           h.bomb_pot ->> 'variant'                              AS variant,
           COALESCE((h.bomb_pot ->> 'ante_amount')::numeric, 0)  AS ante_amount,
           COALESCE(h.pot_size, 0)                               AS pot_size,
           COALESCE(h.rake_amount, 0)                            AS rake_amount,
           COALESCE(jsonb_array_length(h.players), 0)            AS seats
      FROM bomb_candidates h
      CROSS JOIN LATERAL (
        SELECT t.id FROM public.tables t
         WHERE t.id=h.table_id AND t.club_id=p_club_id OFFSET 0
      ) hosted
  ), per_hand_units AS (
    SELECT a.hand_history_id,
           count(DISTINCT a.user_id) AS distinct_winners
      FROM public.bomb_pot_award_units a
      JOIN bomb_hands b ON b.id = a.hand_history_id
     GROUP BY a.hand_history_id
  ), grouped AS (
    SELECT b.table_id, b.trigger_reason, b.board_count, b.variant,
           count(*)::bigint                                              AS hands,
           SUM(b.seats)::numeric                                         AS seats_sum,
           SUM(b.pot_size)                                               AS pot_sum,
           SUM(b.rake_amount)                                            AS rake_sum,
           SUM(b.ante_amount * b.seats)                                  AS ante_sum,
           count(*) FILTER (WHERE u.distinct_winners = 1)::bigint        AS scoops,
           count(*) FILTER (WHERE u.distinct_winners > 1)::bigint        AS splits,
           count(*) FILTER (WHERE u.hand_history_id IS NULL)::bigint     AS unrecorded
      FROM bomb_hands b
      LEFT JOIN per_hand_units u ON u.hand_history_id = b.id
     GROUP BY b.table_id, b.trigger_reason, b.board_count, b.variant
  )
  INSERT INTO public.ca_club_bomb_pot_daily
    (club_id, day, table_id, trigger_reason, board_count, variant,
     hands, seats_sum, pot_sum, rake_sum, ante_sum, scoops, splits, unrecorded)
  SELECT p_club_id, p_day, g.table_id, g.trigger_reason, g.board_count, g.variant,
         g.hands, g.seats_sum, g.pot_sum, g.rake_sum, g.ante_sum,
         g.scoops, g.splits, g.unrecorded
    FROM grouped g;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  SELECT COALESCE(SUM(d.hands), 0) INTO v_hands
    FROM public.ca_club_bomb_pot_daily d
   WHERE d.club_id = p_club_id AND d.day = p_day;

  -- The marker is written even when the day held no bomb pots. A day with
  -- none is a FACT, and without the marker it would be re-scanned live for
  -- ever and read as "not yet known" rather than "none".
  INSERT INTO public.ca_club_bomb_pot_complete (club_id, day, rows_written, hands_read, computed_at)
  VALUES (p_club_id, p_day, v_rows, v_hands, now())
  ON CONFLICT (club_id, day) DO UPDATE
    SET rows_written = EXCLUDED.rows_written,
        hands_read   = EXCLUDED.hands_read,
        computed_at  = EXCLUDED.computed_at;

  RETURN v_rows;
END;
$$;


ALTER FUNCTION public.fn_ca_bomb_pot_rollup_day(p_club_id uuid, p_day date) OWNER TO postgres;

--
-- TOC entry 45399 (class 0 OID 0)
-- Dependencies: 9082
-- Name: FUNCTION fn_ca_bomb_pot_rollup_day(p_club_id uuid, p_day date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_bomb_pot_rollup_day(p_club_id uuid, p_day date) IS 'Seals one finished day of one club into ca_club_bomb_pot_daily. Refuses a day less than fifteen minutes old, because a sealed day is never recomputed and an award unit can land late.';


--
-- TOC entry 8899 (class 1255 OID 120665460)
-- Name: fn_ca_bound_outside_snapshots(interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_bound_outside_snapshots(p_max_age interval DEFAULT '00:05:00'::interval) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    SET statement_timeout TO '20s'
    AS $$
DECLARE
  r record;
  v_action text;
  v_signalled boolean;
  v_acted jsonb := '[]'::jsonb;
BEGIN
  /* A LONG OUTSIDE SNAPSHOT DOES NOT STALL THE TABLES (2026-10-06). A
     snapshot held for 32 minutes by an export pinned the xmin horizon and
     stalled every tournament table's hand settlement. Outside sessions that
     log in as postgres (or a member of it, or supabase_read_only_user) may
     hold a snapshot for at most
     p_max_age; pg_cron and the migration appliers are exempt. */
  IF p_max_age IS NULL OR p_max_age < interval '1 second' OR p_max_age > interval '30 minutes' THEN
    RAISE EXCEPTION 'CA_SNAPSHOT_BOUND_OUT_OF_RANGE: %', p_max_age USING ERRCODE = '22023';
  END IF;

  FOR r IN
    SELECT a.pid,
           a.usename::text AS role_name,
           coalesce(a.application_name, '') AS app,
           a.client_addr,
           a.backend_start,
           a.xact_start,
           clock_timestamp() - a.xact_start AS held,
           a.state,
           left(coalesce(a.query, ''), 160) AS query_head
      FROM pg_stat_activity a
      JOIN pg_roles ro ON ro.oid = a.usesysid
     WHERE a.backend_type = 'client backend'
       AND a.pid <> pg_backend_pid()
       AND a.xact_start IS NOT NULL
       AND a.xact_start < clock_timestamp() - p_max_age
       AND (a.backend_xmin IS NOT NULL OR a.backend_xid IS NOT NULL)
       AND NOT ro.rolsuper
       AND (pg_has_role(ro.oid, 'postgres', 'MEMBER') OR ro.rolname = 'supabase_read_only_user')
       AND coalesce(a.application_name, '') NOT IN ('pg_cron', 'mgmt-api', 'apply-recorded-migration')
       AND coalesce(a.application_name, '') NOT LIKE 'antigravity-sql-push:%'
     ORDER BY a.xact_start, a.pid
  LOOP
    v_action := CASE WHEN r.state LIKE 'idle in transaction%' THEN 'terminate' ELSE 'cancel' END;
    v_signalled := CASE WHEN v_action = 'terminate' THEN pg_terminate_backend(r.pid)
                        ELSE pg_cancel_backend(r.pid) END;
    INSERT INTO smarter_private.ca_long_snapshot_cancellations
      (pid, role_name, application_name, client_addr, backend_start, xact_start, held, state, action, signalled, query_head)
    VALUES
      (r.pid, r.role_name, r.app, r.client_addr, r.backend_start, r.xact_start, r.held, r.state, v_action, v_signalled, r.query_head);
    RAISE LOG 'CA_OUTSIDE_SNAPSHOT_BOUNDED: % pid % (role %, application "%") held a snapshot for % (bound %)',
      v_action, r.pid, r.role_name, r.app, r.held, p_max_age;
    v_acted := v_acted || jsonb_build_object('pid', r.pid, 'application_name', r.app, 'action', v_action,
                                             'signalled', v_signalled, 'held', r.held::text);
  END LOOP;

  RETURN jsonb_build_object('bound', p_max_age::text, 'acted', jsonb_array_length(v_acted), 'sessions', v_acted);
END
$$;


ALTER FUNCTION public.fn_ca_bound_outside_snapshots(p_max_age interval) OWNER TO postgres;

--
-- TOC entry 45401 (class 0 OID 0)
-- Dependencies: 8899
-- Name: FUNCTION fn_ca_bound_outside_snapshots(p_max_age interval); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_bound_outside_snapshots(p_max_age interval) IS 'Cancels (or, when idle in transaction, terminates) a non-superuser postgres-member or supabase_read_only_user client session other than pg_cron and the migration appliers (mgmt-api, apply-recorded-migration, antigravity-sql-push:*) whose snapshot is older than p_max_age, and records it in smarter_private.ca_long_snapshot_cancellations (20261006170925 a_long_outside_snapshot_does_not_stall_the_tables).';


--
-- TOC entry 7484 (class 1255 OID 218977725)
-- Name: fn_ca_bounty_mtt_rebuys_until_registration_closes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_bounty_mtt_rebuys_until_registration_closes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_total numeric;
BEGIN
  IF NOT (COALESCE(NEW.is_bounty, false) OR COALESCE(NEW.is_pko, false)
          OR COALESCE(NEW.is_mystery_bounty, false)) THEN
    RETURN NEW;
  END IF;
  IF upper(COALESCE(NEW.tournament_type, 'MTT')) <> 'MTT'
     OR lower(COALESCE(NEW.variant, '')) = 'satellite'
     OR NEW.satellite_target_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  -- A game that has started keeps the contract it started with.
  IF upper(COALESCE(NEW.status, 'REGISTERING')) NOT IN ('REGISTERING', 'ANNOUNCED') THEN
    RETURN NEW;
  END IF;
  v_total := COALESCE(NEW.buy_in_amount, 0) + COALESCE(NEW.buy_in_fee, 0);
  -- A freeroll keeps its Free Buy rules (fn_freerolls_are_free_buy).
  IF v_total <= 0 THEN
    RETURN NEW;
  END IF;

  NEW.is_rebuy := true;
  NEW.is_reentry := true;
  IF COALESCE(NEW.rebuy_cost, 0) <= 0 THEN
    NEW.rebuy_cost := v_total;
  END IF;
  IF COALESCE(NEW.rebuy_chips, 0) <= 0 THEN
    NEW.rebuy_chips := COALESCE(NULLIF(NEW.starting_chips, 0), 10000);
  END IF;
  IF COALESCE(NEW.late_reg_levels, 0) > 0 THEN
    NEW.rebuy_levels := NEW.late_reg_levels;
  ELSIF COALESCE(NEW.rebuy_levels, 0) <= 0 THEN
    NEW.rebuy_levels := 6;
  END IF;
  IF COALESCE(NEW.max_rebuys, 0) <= 0 THEN
    NEW.max_rebuys := NULL;
  END IF;
  IF COALESCE(NEW.max_reentries, 0) <= 0 THEN
    NEW.max_reentries := NULL;
  END IF;
  RETURN NEW;
END;
$$;


