COMMENT ON FUNCTION public.fn_ca_break_window_ddl_guard() IS 'Event trigger: refuses non-temporary DDL from migration sessions inside [:50,:03). The exact no-op mgmt-api schema_migrations bootstrap is admitted only under an authenticated durable stopped-engine Stage-B freeze; all actual migration DDL still requires its own recorded SET LOCAL reason.';


--
-- TOC entry 5892 (class 1255 OID 26815591)
-- Name: fn_ca_break_window_governs(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_break_window_governs(p_session_role text, p_application text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT coalesce(p_application, '') <> 'pg_cron'
     AND EXISTS (
           SELECT 1
             FROM pg_catalog.pg_roles r
            WHERE r.rolname = p_session_role
              AND NOT r.rolsuper
              AND pg_catalog.pg_has_role(r.oid, 'postgres', 'MEMBER')
         );
$$;


