COMMENT ON FUNCTION public.fn_ca_burn(p_asset text, p_source text, p_target_id uuid, p_amount numeric, p_reason text, p_op_id text, p_class text) IS 'Retirement, the mirror of fn_ca_mint. Chips from a club treasury or union bank; diamonds from a player wallet or from ca_diamond_house. Refuses below zero on every account. p_class is stamped on the diamond journal row beside counterparty = ''retired''. service_role, or admin / god, only.';


--
-- TOC entry 7509 (class 1255 OID 18225537)
-- Name: fn_ca_burnin_gate_tick(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_burnin_gate_tick() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_gate jsonb; v_pass boolean; v_prev boolean; v_failing text[];
  v_tracker record; v_uid uuid;
BEGIN
  /* THE ACTIVITY READING COMES FIRST (2026-10-12). Postgres reads
     pg_stat_activity once per transaction and holds it. Reading it here,
     before the next statement takes the gate's snapshot, means the gate's
     settlement horizon names every transaction that could still commit a
     row the gate has not seen. */
  PERFORM count(*) FROM pg_catalog.pg_stat_activity;
  v_gate := public.fn_ca_midway_burnin_gate(24);
  v_pass := COALESCE((v_gate->>'pass')::boolean, false);
  SELECT COALESCE(array_agg(k), '{}') INTO v_failing
    FROM jsonb_each(v_gate->'checks') e(k, v) WHERE (v->'pass')::boolean = false;
  SELECT pass INTO v_prev FROM public.ca_gate_runs ORDER BY run_at DESC LIMIT 1;
  INSERT INTO public.ca_gate_runs (pass, window_hours, failing, result)
  VALUES (v_pass, 24, v_failing, v_gate);

  -- red -> green: the one push worth sending
  IF v_pass AND (v_prev IS DISTINCT FROM true) THEN
    FOR v_uid IN SELECT user_id FROM public.ca_incident_recipients WHERE active AND scope='platform' LOOP
      PERFORM public.fn_raise_notification(v_uid, 'financial_attestation',
        '🟢 Midway burn-in gate is GREEN',
        'All 12 acceptance checks passed over the last 24 hours. Per the zero-drift directive, Midway/Shark/JAQK may reopen normal tables.',
        '/hub/club-arena/financial-incidents',
        jsonb_build_object('gate', 'green'));
    END LOOP;
  END IF;

  -- blocked-mint tracker auto-verify: a full day of zero attempts after the
  -- engine fix = verified. Resolve the tracker and say so, once.
  FOR v_tracker IN
    SELECT i.id FROM public.ca_drift_incidents i
    WHERE i.dedupe_key LIKE 'tourney-cashout-blocked:%' AND i.status <> 'resolved'
      AND i.detected_at < now() - interval '24 hours'
      AND NOT EXISTS (SELECT 1 FROM public.ca_incident_events e
                       WHERE e.incident_id = i.id AND e.at > now() - interval '24 hours'
                         AND e.kind IN ('created','notified'))
  LOOP
    PERFORM public.fn_ca_incident_action(v_tracker.id, 'resolve',
      'Auto-verified: 24 hours with zero blocked tournament-cashout attempts - the engine exit path is confirmed fixed.',
      NULL, 'engine exit path fix verified by 24h of silence at the guard',
      'verified: 24h with zero blocked tournament-cashout attempts at the guard');
    FOR v_uid IN SELECT user_id FROM public.ca_incident_recipients WHERE active AND scope='platform' LOOP
      PERFORM public.fn_raise_notification(v_uid, 'financial_attestation',
        '✅ Engine tournament-exit fix verified',
        'The mint guard has seen zero blocked cashout attempts for a full day. The engine-side bug behind the tournament-cashout mint is confirmed fixed.',
        '/hub/club-arena/financial-incidents', '{}'::jsonb);
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('pass', v_pass, 'failing', v_failing);
END $$;


ALTER FUNCTION public.fn_ca_burnin_gate_tick() OWNER TO postgres;

--
-- TOC entry 9149 (class 1255 OID 223387203)
-- Name: fn_ca_bust_backlog_page(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_bust_backlog_page(p_minutes integer DEFAULT 4) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_raised integer := 0;
  v_closed integer := 0;
  v_stalled integer := 0;
BEGIN
  DROP TABLE IF EXISTS _ca_bust_backlog;
  CREATE TEMP TABLE _ca_bust_backlog ON COMMIT DROP AS
    SELECT * FROM public.fn_ca_bust_backlog_stalled(GREATEST(p_minutes, 1));
  SELECT count(*) INTO v_stalled FROM _ca_bust_backlog;

  INSERT INTO public.financial_alerts (severity, source, message, context)
  SELECT 'critical',
         'fn_ca_bust_backlog_page',
         b.message || ' The engine hands a stalled bust stage to a fresh generation '
           || 'after two minutes; this page means that did not cure it.',
         jsonb_build_object(
           'checked_at', now(),
           'threshold_minutes', GREATEST(p_minutes, 1),
           'tournament_id', b.tournament_id,
           'tournament_name', b.tournament_name,
           'backlog', b.backlog,
           'oldest_minutes', b.oldest_mins,
           'last_hand_at', b.last_hand_at)
    FROM _ca_bust_backlog b
   WHERE NOT EXISTS (
     SELECT 1 FROM public.financial_alerts fa
      WHERE fa.source = 'fn_ca_bust_backlog_page'
        AND NOT fa.resolved
        AND fa.context->>'tournament_id' = b.tournament_id::text);
  GET DIAGNOSTICS v_raised = ROW_COUNT;

  UPDATE public.financial_alerts fa
     SET resolved = true,
         resolved_at = now(),
         resolution = 'Auto-closed by fn_ca_bust_backlog_page: bust backlog recorded; no bust has waited past the threshold.'
   WHERE fa.source = 'fn_ca_bust_backlog_page'
     AND NOT fa.resolved
     AND NOT EXISTS (
       SELECT 1 FROM _ca_bust_backlog b WHERE b.tournament_id::text = fa.context->>'tournament_id');
  GET DIAGNOSTICS v_closed = ROW_COUNT;

  DROP TABLE IF EXISTS _ca_bust_backlog;
  RETURN jsonb_build_object('stalled', v_stalled, 'raised', v_raised, 'closed', v_closed);
END
$$;


ALTER FUNCTION public.fn_ca_bust_backlog_page(p_minutes integer) OWNER TO postgres;

--
-- TOC entry 3784 (class 1255 OID 64159509)
-- Name: fn_ca_bust_backlog_stalled(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_bust_backlog_stalled(p_minutes integer DEFAULT 20) RETURNS TABLE(tournament_id uuid, tournament_name text, variant text, backlog bigint, oldest_mins numeric, last_hand_at timestamp with time zone, minutes_no_hand numeric, message text)
    LANGUAGE sql STABLE
    AS $$
  WITH latest AS (
    SELECT DISTINCT ON (c.tournament_id, c.eliminated_user_id)
           c.tournament_id, c.eliminated_user_id, c.state, c.resolved_at, c.created_at
      FROM public.tournament_knockout_candidates c
      JOIN public.tournaments t ON t.id = c.tournament_id AND t.status = 'RUNNING'
     ORDER BY c.tournament_id, c.eliminated_user_id, c.hand_number DESC, c.id DESC
  ), b AS (
    SELECT l.tournament_id, count(*) AS backlog, min(l.created_at) AS oldest
      FROM latest l
     WHERE l.state = 'pending' AND l.resolved_at IS NULL
       AND l.created_at < now() - make_interval(mins => GREATEST(p_minutes, 1))
     GROUP BY l.tournament_id
  )
  SELECT b.tournament_id, t.name, t.variant, b.backlog,
         round((extract(epoch FROM (now() - b.oldest)) / 60.0)::numeric, 1),
         h.last_hand_at,
         round((extract(epoch FROM (now() - h.last_hand_at)) / 60.0)::numeric, 1),
         b.backlog || ' busted player(s) in "' || t.name || '" have been waiting to be '
           || 'recorded for more than ' || round((extract(epoch FROM (now() - b.oldest)) / 60.0)::numeric, 1)
           || ' minute(s). Until each is recorded out, its chair still reads '
           || 'playing at zero chips, so smarter_private.f06_movement_prior '
           || 'refuses the table''s movement proof (F06_MOVEMENT_ELIMINATION_UNPROVEN) '
           || 'and no table of this event can break.'
    FROM b
    JOIN public.tournaments t ON t.id = b.tournament_id
    LEFT JOIN LATERAL (
      SELECT max(hh.created_at) AS last_hand_at
        FROM public.hand_history hh
        JOIN public.tables tb ON tb.id = hh.table_id
       WHERE tb.tournament_id = b.tournament_id) h ON true
   ORDER BY b.backlog DESC
$$;


ALTER FUNCTION public.fn_ca_bust_backlog_stalled(p_minutes integer) OWNER TO postgres;

--
-- TOC entry 4100 (class 1255 OID 18996923)
-- Name: fn_ca_caller_is_management(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_caller_is_management() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_ok  boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN true;
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.ca_incident_recipients r WHERE r.user_id = v_uid AND r.active
    UNION ALL
    SELECT 1 FROM public.club_members cm WHERE cm.user_id = v_uid AND cm.role = 'owner'
    UNION ALL
    SELECT 1 FROM public.unions u WHERE u.owner_id = v_uid
    UNION ALL
    SELECT 1 FROM public.profiles p WHERE p.id = v_uid AND p.role IN ('admin','god')
  ) INTO v_ok;
  RETURN COALESCE(v_ok, false);
END $$;


