--
-- TOC entry 9568 (class 1255 OID 24421230)
-- Name: fn_ca_capture_closing_position(text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_capture_closing_position(p_note text DEFAULT NULL::text, p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ref    uuid := gen_random_uuid();
  v_epoch  record;
  v_rows   integer := 0;
  v_total  numeric := 0;
  v_by     jsonb;
BEGIN
  IF COALESCE(NULLIF(auth.role(), ''), session_user) NOT IN ('service_role', 'postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'closing-position capture is operator-only';
  END IF;

  SELECT id, name INTO v_epoch
    FROM public.ca_financial_epochs WHERE is_current LIMIT 1;
  IF v_epoch.id IS NULL THEN
    RAISE EXCEPTION 'no current epoch - ca_financial_epochs has no is_current row';
  END IF;

  IF NOT p_dry_run AND NOT public.fn_platform_frozen() THEN
    RAISE EXCEPTION
      'closing-position capture refused: the platform is not frozen. Capture inside the :55 maintenance break, or pass p_dry_run => true to rehearse.'
      USING ERRCODE = '55006';
  END IF;

  CREATE TEMP TABLE _closing (
    account_type text, column_name text, entity_id uuid, club_id uuid, balance numeric
  ) ON COMMIT DROP;

  INSERT INTO _closing
  SELECT 'player_wallet', 'club_members.chip_balance', cm.user_id, cm.club_id, round(COALESCE(cm.chip_balance,0),2)
    FROM public.club_members cm WHERE COALESCE(cm.chip_balance,0) <> 0;

  INSERT INTO _closing
  SELECT 'member_promo', 'club_members.promo_balance', cm.user_id, cm.club_id, round(COALESCE(cm.promo_balance,0),2)
    FROM public.club_members cm WHERE COALESCE(cm.promo_balance,0) <> 0;

  INSERT INTO _closing
  SELECT 'table_stack', 'table_seats.stack', ts.user_id, ts.club_id, round(COALESCE(ts.stack,0),2)
    FROM public.table_seats ts
   WHERE ts.left_at IS NULL AND COALESCE(ts.stack,0) <> 0
     AND NOT EXISTS (SELECT 1 FROM public.tables t WHERE t.id = ts.table_id AND t.tournament_id IS NOT NULL);

  INSERT INTO _closing
  SELECT 'club_treasury', 'clubs.chip_treasury', NULL, c.id, round(COALESCE(c.chip_treasury,0),2)
    FROM public.clubs c WHERE COALESCE(c.chip_treasury,0) <> 0;
  INSERT INTO _closing
  SELECT 'club_pool', 'clubs.chip_pool', NULL, c.id, round(COALESCE(c.chip_pool,0),2)
    FROM public.clubs c WHERE COALESCE(c.chip_pool,0) <> 0;
  INSERT INTO _closing
  SELECT 'club_promo', 'clubs.promo_balance', NULL, c.id, round(COALESCE(c.promo_balance,0),2)
    FROM public.clubs c WHERE COALESCE(c.promo_balance,0) <> 0;
  INSERT INTO _closing
  SELECT 'club_insurance', 'clubs.insurance_balance', NULL, c.id, round(COALESCE(c.insurance_balance,0),2)
    FROM public.clubs c WHERE COALESCE(c.insurance_balance,0) <> 0;

  INSERT INTO _closing
  SELECT 'club_wallet', 'club_wallets.chip_balance', NULL, cw.club_id, round(COALESCE(cw.chip_balance,0),2)
    FROM public.club_wallets cw WHERE COALESCE(cw.chip_balance,0) <> 0;

  INSERT INTO _closing
  SELECT 'union_wallet', 'union_wallets.' || col, NULL, uw.union_id, round(bal,2)
    FROM public.union_wallets uw,
         LATERAL (VALUES
           ('chip_balance', COALESCE(uw.chip_balance,0)),
           ('rake_wallet', COALESCE(uw.rake_wallet,0)),
           ('bbj_wallet', COALESCE(uw.bbj_wallet,0)),
           ('promo_wallet', COALESCE(uw.promo_wallet,0)),
           ('insurance_wallet', COALESCE(uw.insurance_wallet,0)),
           ('spin_reserve_wallet', COALESCE(uw.spin_reserve_wallet,0))
         ) AS v(col, bal)
   WHERE bal <> 0;

  INSERT INTO _closing
  SELECT 'agent_wallet', 'agents.agent_wallet_balance', a.user_id, a.club_id, round(COALESCE(a.agent_wallet_balance,0),2)
    FROM public.agents a WHERE COALESCE(a.agent_wallet_balance,0) <> 0;
  INSERT INTO _closing
  SELECT 'agent_promo', 'agents.promo_wallet_balance', a.user_id, a.club_id, round(COALESCE(a.promo_wallet_balance,0),2)
    FROM public.agents a WHERE COALESCE(a.promo_wallet_balance,0) <> 0;
  INSERT INTO _closing
  SELECT 'agent_player_wallet', 'agents.player_wallet_balance', a.user_id, a.club_id, round(COALESCE(a.player_wallet_balance,0),2)
    FROM public.agents a WHERE COALESCE(a.player_wallet_balance,0) <> 0;

  INSERT INTO _closing
  SELECT 'bbj_pool', 'bbj_pools.' || col, b.union_id, b.club_id, round(bal,2)
    FROM public.bbj_pools b,
         LATERAL (VALUES
           ('main_balance', COALESCE(b.main_balance,0)),
           ('backup_balance', COALESCE(b.backup_balance,0)),
           ('promo_balance', COALESCE(b.promo_balance,0))
         ) AS v(col, bal)
   WHERE bal <> 0;

  INSERT INTO _closing
  SELECT 'spin_reserve', 'spin_bonus_pools.balance', NULL, s.club_id, round(COALESCE(s.balance,0),2)
    FROM public.spin_bonus_pools s WHERE COALESCE(s.balance,0) <> 0;

  INSERT INTO _closing
  SELECT 'frozen_wallet_pool', 'wallets.balance', w.user_id, NULL, round(COALESCE(w.balance,0),2)
    FROM public.wallets w WHERE COALESCE(w.balance,0) <> 0;

  SELECT count(*), COALESCE(round(sum(balance),2),0) INTO v_rows, v_total FROM _closing;
  SELECT jsonb_object_agg(account_type, totals) INTO v_by
    FROM (SELECT account_type,
                 jsonb_build_object('accounts', count(*), 'total', round(sum(balance),2)) AS totals
            FROM _closing GROUP BY account_type) x;

  IF v_rows = 0 THEN
    RAISE EXCEPTION 'closing-position capture found no accounts at all - refusing to record an empty position';
  END IF;

  IF p_dry_run THEN
    RETURN jsonb_build_object('dry_run', true, 'written', false,
      'epoch', v_epoch.name, 'accounts', v_rows, 'total', v_total, 'by_class', v_by,
      'frozen_now', public.fn_platform_frozen(),
      'note', 'run with p_dry_run => false inside the :55 freeze to record it');
  END IF;

  INSERT INTO public.ca_epoch_closing_positions
    (capture_ref, epoch_id, epoch_name, account_type, column_name, entity_id, club_id, balance, note)
  SELECT v_ref, v_epoch.id, v_epoch.name, c.account_type, c.column_name, c.entity_id, c.club_id, c.balance, p_note
    FROM _closing c;

  RETURN jsonb_build_object('written', true, 'capture_ref', v_ref,
    'epoch', v_epoch.name, 'accounts', v_rows, 'total', v_total, 'by_class', v_by,
    'next', 'compare against fn_ca_supply_snapshot() before the reset, then keep it forever');
END;
$$;


ALTER FUNCTION public.fn_ca_capture_closing_position(p_note text, p_dry_run boolean) OWNER TO postgres;

--
-- TOC entry 45430 (class 0 OID 0)
-- Dependencies: 9568
-- Name: FUNCTION fn_ca_capture_closing_position(p_note text, p_dry_run boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_capture_closing_position(p_note text, p_dry_run boolean) IS 'Records what every account held the moment before an epoch reset - roadmap 9.8 step 1. Covers exactly the classes fn_ca_supply_snapshot reads, so the two agree by construction. A real capture refuses unless the platform is frozen; p_dry_run reads and returns the same totals without writing.';


--
-- TOC entry 9258 (class 1255 OID 19005887)
-- Name: fn_ca_capture_freeze_mark(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_capture_freeze_mark(p_kind text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_at timestamptz := clock_timestamp();
  v_local timestamp := v_at AT TIME ZONE 'America/Chicago';
  v_end timestamptz;
  m numeric; f numeric; t numeric; i integer := 0;
BEGIN
  IF p_kind NOT IN ('pre','post') OR p_kind IS NULL THEN
    RAISE EXCEPTION 'p_kind must be pre or post';
  END IF;
  -- UTC twins are observation opportunities, not two breaks. Refuse every
  -- other local instant, including the unused DST twin and old hourly calls.
  IF extract(hour FROM v_local) <> 4
     OR extract(minute FROM v_local) <> (CASE WHEN p_kind='pre' THEN 0 ELSE 5 END) THEN
    RETURN NULL;
  END IF;
  v_end := (date_trunc('day',v_local) + interval '4 hours 5 minutes') AT TIME ZONE 'America/Chicago';
  IF p_kind='pre' THEN
    -- Existing bounded observation wait. Missing freeze means missing evidence,
    -- never a snapshot of ordinary play disguised as a conserved freeze.
    WHILE NOT public.fn_platform_frozen() AND i < 25 LOOP
      PERFORM pg_sleep(1); i := i + 1;
    END LOOP;
    IF NOT public.fn_platform_frozen() THEN RETURN NULL; END IF;
  ELSIF NOT EXISTS (
    SELECT 1 FROM public.ca_freeze_circulation_marks
    WHERE window_hour=v_end AND kind='pre'
  ) THEN
    RETURN NULL;
  END IF;
  SELECT member_wallets,on_the_felt,total INTO m,f,t FROM public.fn_ca_circulation_total();
  INSERT INTO public.ca_freeze_circulation_marks(window_hour,kind,member_wallets,on_the_felt,total,mark_at)
  VALUES(v_end,p_kind,m,f,t,clock_timestamp())
  -- Repeated delivery must not replace the actual edge with later play.
  ON CONFLICT(window_hour,kind) DO NOTHING;
  RETURN v_end;
END $$;


ALTER FUNCTION public.fn_ca_capture_freeze_mark(p_kind text) OWNER TO postgres;

--
-- TOC entry 6483 (class 1255 OID 18201192)
-- Name: fn_ca_capture_hand_facts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_capture_hand_facts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF COALESCE(OLD.rake_amount, 0) > 0 OR COALESCE(OLD.bbj_amount, 0) > 0
     OR OLD.reported IS TRUE THEN
    INSERT INTO public.ca_hand_financial_facts
      (hand_id, table_id, tournament_id, hand_number, big_blind, pot_size,
       rake_amount, bbj_amount, winners, hand_created_at)
    VALUES (OLD.id, OLD.table_id, OLD.tournament_id, OLD.hand_number, OLD.big_blind,
            OLD.pot_size, OLD.rake_amount, OLD.bbj_amount, OLD.winners, OLD.created_at)
    ON CONFLICT (hand_id) DO NOTHING;
  END IF;
  RETURN OLD;
EXCEPTION WHEN OTHERS THEN
  -- never block a prune; count the miss
  BEGIN
    INSERT INTO public.ca_ledger_write_failures (source_table, message, sqlstate)
    VALUES ('ca_hand_financial_facts', left(SQLERRM, 500), SQLSTATE);
  EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN OLD;
END $$;


ALTER FUNCTION public.fn_ca_capture_hand_facts() OWNER TO postgres;

--
-- TOC entry 7023 (class 1255 OID 25581381)
-- Name: fn_ca_capture_satellite_seat_entitlement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_capture_satellite_seat_entitlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_h public.tournament_satellite_settlements%ROWTYPE;
  v_l public.chip_ledger%ROWTYPE;
  v_rows integer;
  v_prize numeric;
  v_bounty numeric;
  v_bucket text;
BEGIN
  IF NEW.delivery_kind IS DISTINCT FROM 'seat' THEN
    RETURN NULL;
  END IF;
  -- DIAMOND PHASE 9: a Diamond seat's refund entitlement is its target entry
  -- custody row - the Diamond refund authority returns it whole, as it
  -- returns a paid entry - so no chip entitlement is captured for it. The
  -- seat must carry its exact custody-to-custody evidence instead.
  IF public.fn_poker_diamond_tournament(NEW.tournament_id) THEN
    IF NEW.registration_id IS NULL OR NOT EXISTS (
         SELECT 1
           FROM public.poker_diamond_tournament_ledger li
           JOIN public.poker_diamond_custody c ON c.id = li.custody_id
          WHERE li.idempotency_key = 'poker-tournament-seat-in:' || NEW.idempotency_key
            AND li.kind = 'entry' AND li.user_id = NEW.user_id
            AND li.amount = NEW.amount AND li.registration_id = NEW.registration_id
            AND c.purpose = 'tournament_entry' AND c.user_id = NEW.user_id
            AND c.entry_key = 'entry:' || NEW.registration_id::text)
       OR NOT EXISTS (
         SELECT 1
           FROM public.poker_diamond_tournament_ledger lo
          WHERE lo.idempotency_key = 'poker-tournament-seat-out:' || NEW.idempotency_key
            AND lo.tournament_id = NEW.tournament_id AND lo.kind = 'prize'
            AND lo.user_id = NEW.user_id AND lo.amount = NEW.amount) THEN
      RAISE EXCEPTION
        'Diamond satellite seat award has no exact custody-to-custody evidence'
        USING ERRCODE = 'P0404';
    END IF;
    RETURN NULL;
  END IF;
  SELECT * INTO v_h FROM public.tournament_satellite_settlements h
   WHERE h.tournament_id=NEW.tournament_id;
  SELECT * INTO v_l FROM public.chip_ledger l
   WHERE l.idempotency_key=NEW.idempotency_key||':pool_transfer'
     AND l.from_type='prize_liability'
     AND l.from_entity_id=NEW.tournament_id
     AND l.to_type='prize_liability'
     AND l.to_entity_id=v_h.target_id
     AND l.amount=NEW.amount;
  IF v_h.tournament_id IS NULL OR v_l.id IS NULL OR v_l.club_id IS NULL
     OR NEW.registration_id IS NULL
     OR v_h.ticket_cost IS DISTINCT FROM NEW.amount
     OR v_h.ticket_cost IS DISTINCT FROM
          round(v_h.target_buy_in+v_h.target_fee,2) THEN
    RAISE EXCEPTION
      'satellite seat award has no exact target contract and pool-transfer source'
      USING ERRCODE = 'P0404';
  END IF;
  -- A BOUNTY SEAT IS REFUNDED BY ITS SPLIT (2026-10-16). Its leg books
  -- prize plus bounty as gross and the bounty on the bounty rail
  -- (entry_split_version 2), so its entitlement returns exactly those
  -- parts from the satellite_gross bucket. A plain seat is unchanged.
  IF v_l.metadata->>'entry_split_version' = '2' THEN
    v_prize := (v_l.metadata->>'entry_prize')::numeric;
    v_bounty := (v_l.metadata->>'entry_bounty')::numeric;
    v_bucket := 'satellite_gross';
    IF v_prize IS NULL OR v_bounty IS NULL
       OR v_prize < 0 OR v_bounty < 0
       OR round(v_prize + v_bounty, 2) IS DISTINCT FROM v_h.target_buy_in
       OR (v_l.metadata->>'entry_fee')::numeric IS DISTINCT FROM v_h.target_fee THEN
      RAISE EXCEPTION
        'satellite bounty seat transfer does not carry its exact target entry split'
        USING ERRCODE = 'P0404';
    END IF;
  ELSE
    v_prize := v_h.target_buy_in;
    v_bounty := 0;
    v_bucket := 'satellite_in';
  END IF;
  INSERT INTO public.tournament_refund_entitlements(
    tournament_id,user_id,entitlement_kind,charge_category,
    refund_wallet_club_id,gross,refund_prize,refund_bounty,refund_fee,
    source_ledger_id,registration_id,source_satellite_id,source_award_place,
    escrow_bucket,evidence_kind,created_at)
  VALUES(
    v_h.target_id,NEW.user_id,'satellite_seat','satellite_seat',
    v_l.club_id,NEW.amount,v_prize,v_bounty,v_h.target_fee,
    v_l.id,NEW.registration_id,NEW.tournament_id,NEW.place,
    v_bucket,'atomic_satellite_seat',transaction_timestamp())
  ON CONFLICT(source_ledger_id) DO NOTHING;
  SELECT count(*) INTO v_rows
    FROM public.tournament_refund_entitlements e
   WHERE e.source_ledger_id=v_l.id
     AND e.tournament_id=v_h.target_id AND e.user_id=NEW.user_id
     AND e.entitlement_kind='satellite_seat'
     AND e.charge_category='satellite_seat'
     AND e.refund_wallet_club_id=v_l.club_id
     AND e.gross=NEW.amount
     AND e.refund_prize=v_prize
     AND e.refund_bounty=v_bounty AND e.refund_fee=v_h.target_fee
     AND e.escrow_bucket=v_bucket
     AND e.registration_id=NEW.registration_id
     AND e.source_satellite_id=NEW.tournament_id
     AND e.source_award_place=NEW.place;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'satellite seat entitlement identity conflicts with its source'
      USING ERRCODE = 'P0404';
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_capture_satellite_seat_entitlement() OWNER TO postgres;

--
-- TOC entry 7231 (class 1255 OID 25581303)
-- Name: fn_ca_capture_tournament_charge_entitlement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_capture_tournament_charge_entitlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_split record;
  v_original_entitlement uuid;
BEGIN
  IF NEW.tournament_id IS NULL
     OR NEW.from_type IS DISTINCT FROM 'player_wallet'
     OR NEW.to_type IS DISTINCT FROM 'prize_liability'
     OR NEW.to_entity_id IS DISTINCT FROM NEW.tournament_id
     OR lower(COALESCE(NEW.category,'')) NOT IN (
          'tournament_buyin','rebuy','addon') THEN
    RETURN NULL;
  END IF;
  IF NEW.from_entity_id IS NULL OR NEW.club_id IS NULL THEN
    RAISE EXCEPTION 'tournament charge ledger omitted player or source club'
      USING ERRCODE = 'P0404';
  END IF;
  SELECT * INTO v_split FROM public.fn_ca_tournament_charge_split(
    NEW.tournament_id,NEW.category,NEW.amount);
  INSERT INTO public.tournament_refund_entitlements(
    tournament_id,user_id,entitlement_kind,charge_category,
    refund_wallet_club_id,gross,refund_prize,refund_bounty,refund_fee,
    source_ledger_id,registration_id,source_satellite_id,source_award_place,
    escrow_bucket,evidence_kind,created_at)
  VALUES(
    NEW.tournament_id,NEW.from_entity_id,'wallet_charge',lower(NEW.category),
    NEW.club_id,round(NEW.amount,2),v_split.refund_prize,
    v_split.refund_bounty,v_split.refund_fee,NEW.id,NULL,NULL,NULL,
    'wallet_gross','atomic_wallet_charge',transaction_timestamp()) RETURNING id INTO v_original_entitlement;
  PERFORM set_config('app.pnl_tournament_entitlement',v_original_entitlement::text,true);
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_capture_tournament_charge_entitlement() OWNER TO postgres;

--
-- TOC entry 9045 (class 1255 OID 35372459)
-- Name: fn_ca_capture_tournament_credit_ledger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_capture_tournament_credit_ledger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF NEW.tournament_id IS NOT NULL AND NEW.from_type='prize_liability'
    AND NEW.from_entity_id=NEW.tournament_id AND NEW.to_type='player_wallet'
    AND NEW.category IN ('tournament_prize','bounty','refund','tournament_refund') THEN
   PERFORM set_config('app.pnl_tournament_credit_ledger',NEW.id::text,true);
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION public.fn_ca_capture_tournament_credit_ledger() OWNER TO postgres;

--
-- TOC entry 3676 (class 1255 OID 36433053)
-- Name: fn_ca_capture_tournament_fee_from_recorded_evidence(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_capture_tournament_fee_from_recorded_evidence(p_rake_record_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  r public.rake_records%ROWTYPE; t record; e record; l record; tp record;
  item jsonb; row_plan record; cutoff timestamptz; manifest jsonb;
  contributors jsonb := '[]'; actual_union uuid; expected_kind text;
  expected_entitlement text; expected_category text; source_type text;
  uid uuid; reg uuid; count_rows int; reserve_id uuid; fingerprint text;
  total_weight numeric := 0; total_cents bigint; floor_total bigint;
  remainder_cents bigint; credit numeric; allocated numeric := 0;
  contract jsonb; new_id uuid; result_ids uuid[] := '{}';
  seen_players uuid[] := '{}'; seen_entitlements uuid[] := '{}';
  player uuid; club uuid; registration uuid; ledger_id uuid;
  entitlement_id uuid; charged_at timestamptz; weight numeric;
  refusal text; refusal_state text; owner_basis public.accounting_tournament_fee_owner_bases%ROWTYPE;
BEGIN
  SELECT * INTO r FROM public.rake_records WHERE id = p_rake_record_id FOR UPDATE;
  IF NOT FOUND OR r.is_tournament IS DISTINCT FROM true OR r.tournament_id IS NULL
   OR r.hand_id IS NOT NULL OR r.rake_amount IS NULL OR r.rake_amount <= 0
   OR r.rake_amount <> round(r.rake_amount, 2) OR r.rake_amount::text IN ('NaN','Infinity','-Infinity')
  THEN RAISE EXCEPTION 'positive_chip_tournament_fee_required' USING ERRCODE = '23514'; END IF;

  -- The producer's own lock, so this can never race a live capture.
  PERFORM pg_advisory_xact_lock(hashtextextended('accounting_tournament_fee:'||r.id::text, 0));

  -- ENTRY CONDITIONS, narrower than the producer's in every direction.
  SELECT starts_at INTO cutoff FROM public.accounting_tournament_fee_cutover WHERE singleton;
  IF cutoff IS NULL THEN
    RAISE EXCEPTION 'fee_cutover_missing' USING ERRCODE = '55000'; END IF;
  IF r.created_at >= cutoff THEN
    RAISE EXCEPTION 'tournament_fee_is_the_producers_to_capture' USING ERRCODE = '55000',
      HINT = 'This record was charged at or after the cutover. Its own transaction owned its capture.'; END IF;
  IF EXISTS (SELECT 1 FROM public.accounting_tournament_fee_batches WHERE rake_record_id = r.id) THEN
    RAISE EXCEPTION 'tournament_fee_already_has_a_batch' USING ERRCODE = '23505'; END IF;

  SELECT id, club_id, union_id, is_private, tournament_type, status INTO t
    FROM public.tournaments WHERE id = r.tournament_id FOR SHARE;
  IF NOT FOUND OR public.fn_poker_diamond_tournament(r.tournament_id) THEN
    RAISE EXCEPTION 'chip_tournament_fee_required' USING ERRCODE = '23514'; END IF;
  -- A settled event's books are closed. This may only complete a live one.
  IF upper(COALESCE(t.status::text,'')) NOT IN ('RUNNING','BREAK','REGISTERING','COMPLETING')
   AND NOT public.fn_ca_legacy_fee_capture_admitted(r.tournament_id) THEN
    RAISE EXCEPTION 'tournament_fee_event_is_not_live' USING ERRCODE = '55000'; END IF;

  actual_union := CASE WHEN t.is_private THEN NULL ELSE t.union_id END;
  fingerprint  := public.fn_accounting_tournament_fee_fingerprint(r);

  -- EVIDENCE ASSEMBLY, byte for byte the rule fn_stamp_accounting_tournament_fee uses.
  IF r.source = 'fn_spin_book_entry' THEN
    IF jsonb_typeof(r.player_contributions) IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(r.player_contributions)) <> 3 THEN
      RAISE EXCEPTION 'spin_fee_exact_paid_contributors_required' USING ERRCODE = '23514'; END IF;
    FOR item IN SELECT jsonb_build_object('player_id', key, 'weight', value)
                  FROM jsonb_each_text(r.player_contributions) ORDER BY key LOOP
      SELECT * INTO tp FROM public.tournament_players
       WHERE tournament_id = r.tournament_id AND user_id = (item->>'player_id')::uuid;
      IF NOT FOUND OR tp.club_id IS NULL THEN
        RAISE EXCEPTION 'spin_fee_entry_club_missing' USING ERRCODE = '23514'; END IF;
      SELECT count(*) INTO count_rows FROM public.tournament_refund_entitlements x
       WHERE x.tournament_id = r.tournament_id AND x.user_id = (item->>'player_id')::uuid
         AND x.entitlement_kind = 'wallet_charge' AND x.charge_category = 'tournament_buyin'
         AND x.created_at = tp.registered_at AND x.gross = (item->>'weight')::numeric;
      IF count_rows <> 1 THEN
        RAISE EXCEPTION 'spin_fee_exact_charge_ambiguous' USING ERRCODE = '23514'; END IF;
      SELECT * INTO e FROM public.tournament_refund_entitlements x
       WHERE x.tournament_id = r.tournament_id AND x.user_id = (item->>'player_id')::uuid
         AND x.entitlement_kind = 'wallet_charge' AND x.charge_category = 'tournament_buyin'
         AND x.created_at = tp.registered_at AND x.gross = (item->>'weight')::numeric;
      contributors := contributors || jsonb_build_array(jsonb_build_object(
        'player_id', e.user_id, 'club_id', e.refund_wallet_club_id, 'registration_id', tp.id,
        'charge_ledger_id', e.source_ledger_id, 'entitlement_id', e.id,
        'charged_at', e.created_at, 'weight', (item->>'weight')::numeric));
    END LOOP;
    SELECT count(*) INTO count_rows FROM public.spin_reserve_ledger s
     WHERE s.tournament_id = r.tournament_id AND s.kind = 'contribution';
    IF count_rows <> 1 THEN
      RAISE EXCEPTION 'spin_fee_exact_reserve_required' USING ERRCODE = '23514'; END IF;
    SELECT id INTO reserve_id FROM public.spin_reserve_ledger s
     WHERE s.tournament_id = r.tournament_id AND s.kind = 'contribution';
  ELSE
    IF NOT COALESCE(r.metadata->>'user_id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$', false) THEN
      RAISE EXCEPTION 'tournament_fee_exact_player_required' USING ERRCODE = '23514'; END IF;
    uid := (r.metadata->>'user_id')::uuid;
    expected_entitlement := CASE r.source
      WHEN 'fn_register_for_tournament' THEN 'wallet_charge'
      WHEN 'fn_register_horse_for_tournament' THEN 'wallet_charge'
      WHEN 'process_tournament_rebuy' THEN 'wallet_charge'
      WHEN 'fn_award_satellite_seat' THEN 'satellite_seat'
      WHEN 'fn_register_for_tournament_with_ticket' THEN 'tournament_ticket' END;
    expected_category := CASE WHEN r.source = 'process_tournament_rebuy' THEN 'rebuy' ELSE 'tournament_buyin' END;
    IF expected_entitlement IS NULL THEN
      RAISE EXCEPTION 'tournament_fee_source_unsupported' USING ERRCODE = '55000'; END IF;
    reg := NULLIF(r.metadata->>'registration_id','')::uuid;
    IF reg IS NULL AND r.source = 'process_tournament_rebuy' THEN
      SELECT id INTO reg FROM public.tournament_players
       WHERE tournament_id = r.tournament_id AND user_id = uid; END IF;
    IF reg IS NULL THEN
      RAISE EXCEPTION 'tournament_fee_exact_registration_required' USING ERRCODE = '23514'; END IF;
    SELECT count(*) INTO count_rows FROM public.tournament_refund_entitlements x
     WHERE x.tournament_id = r.tournament_id AND x.user_id = uid AND x.created_at = r.created_at
       AND x.refund_fee = r.rake_amount AND x.entitlement_kind = expected_entitlement
       AND (CASE WHEN expected_entitlement = 'wallet_charge' THEN x.charge_category = expected_category
                 ELSE x.registration_id = reg END);
    IF count_rows <> 1 THEN
      RAISE EXCEPTION 'tournament_fee_exact_charge_ambiguous' USING ERRCODE = '23514'; END IF;
    SELECT * INTO e FROM public.tournament_refund_entitlements x
     WHERE x.tournament_id = r.tournament_id AND x.user_id = uid AND x.created_at = r.created_at
       AND x.refund_fee = r.rake_amount AND x.entitlement_kind = expected_entitlement
       AND (CASE WHEN expected_entitlement = 'wallet_charge' THEN x.charge_category = expected_category
                 ELSE x.registration_id = reg END);
    contributors := jsonb_build_array(jsonb_build_object(
      'player_id', e.user_id,
      -- 2026-09-20. A satellite seat's contributor club is the
      -- REGISTRATION's club: the club whose member actually played, and the
      -- only club for which fn_accounting_earning_contract resolves (149/149
      -- against 88/149 for the host club). fn_award_satellite_seat wrote
      -- refund_wallet_club_id as the HOST club until the 2026-09-17 cutover;
      -- that is a refund DESTINATION, not an earning scope, and it is
      -- verified as one in the evidence loop below. After the cutover the
      -- two are equal, so this changes nothing for a post-cutover record.
      'club_id', CASE WHEN e.entitlement_kind = 'satellite_seat'
                      THEN (SELECT x.club_id FROM public.tournament_players x WHERE x.id = reg)
                      ELSE e.refund_wallet_club_id END,
      'registration_id', reg,
      'charge_ledger_id', e.source_ledger_id, 'entitlement_id', e.id,
      'charged_at', e.created_at, 'weight', r.rake_amount));
  END IF;

  manifest := jsonb_build_object('union_id', actual_union, 'game_type', lower(t.tournament_type),
    'contributors', contributors, 'spin_reserve_id', reserve_id);

  -- EVIDENCE VERIFICATION, every check fn_capture_accounting_tournament_fee makes.
  -- The two provenance rules it applies are the only ones deliberately absent:
  -- the record need not have been created in this transaction, and a
  -- contributor's charge need not follow the cutover. Nothing else is relaxed.
  expected_kind := CASE r.source
    WHEN 'fn_register_for_tournament' THEN 'tournament_entry_fee'
    WHEN 'fn_register_horse_for_tournament' THEN 'tournament_entry_fee'
    WHEN 'fn_award_satellite_seat' THEN 'satellite_seat_entry_fee'
    WHEN 'fn_register_for_tournament_with_ticket' THEN 'tournament_ticket_entry_fee'
    WHEN 'fn_spin_book_entry' THEN 'spin_rake'
    WHEN 'process_tournament_rebuy' THEN r.metadata->>'kind' END;
  IF expected_kind IS NULL OR r.metadata->>'kind' IS DISTINCT FROM expected_kind
   OR (r.source = 'process_tournament_rebuy' AND expected_kind NOT IN ('tournament_rebuy_fee','tournament_reentry_fee'))
  THEN RAISE EXCEPTION 'tournament_fee_source_unsupported' USING ERRCODE = '55000'; END IF;

  count_rows := jsonb_array_length(manifest->'contributors');
  IF (r.source = 'fn_spin_book_entry' AND count_rows <> 3)
   OR (r.source <> 'fn_spin_book_entry' AND count_rows <> 1) THEN
    RAISE EXCEPTION 'tournament_fee_contributor_count_invalid' USING ERRCODE = '23514'; END IF;

  FOR item IN SELECT value FROM jsonb_array_elements(manifest->'contributors') LOOP
    player := (item->>'player_id')::uuid; club := (item->>'club_id')::uuid;
    registration := (item->>'registration_id')::uuid; ledger_id := (item->>'charge_ledger_id')::uuid;
    entitlement_id := (item->>'entitlement_id')::uuid; charged_at := (item->>'charged_at')::timestamptz;
    weight := (item->>'weight')::numeric;
    IF player IS NULL OR club IS NULL OR registration IS NULL OR ledger_id IS NULL
     OR entitlement_id IS NULL OR charged_at IS NULL OR NOT isfinite(charged_at)
     OR charged_at > r.created_at
     OR weight IS NULL OR weight <= 0 OR weight <> round(weight,2)
     OR weight::text IN ('NaN','Infinity','-Infinity')
     OR player = ANY(seen_players) OR entitlement_id = ANY(seen_entitlements)
    THEN RAISE EXCEPTION 'tournament_fee_contributor_invalid' USING ERRCODE = '23514'; END IF;
    seen_players := array_append(seen_players, player);
    seen_entitlements := array_append(seen_entitlements, entitlement_id);

    SELECT * INTO e  FROM public.tournament_refund_entitlements WHERE id = entitlement_id;
    SELECT * INTO l  FROM public.chip_ledger WHERE id = ledger_id;
    SELECT * INTO tp FROM public.tournament_players WHERE id = registration;
    IF e.id IS NULL OR l.id IS NULL OR tp.id IS NULL
     OR e.tournament_id IS DISTINCT FROM r.tournament_id OR e.user_id IS DISTINCT FROM player
     OR (CASE WHEN e.entitlement_kind = 'satellite_seat'
              THEN e.refund_wallet_club_id IS DISTINCT FROM l.club_id
              ELSE e.refund_wallet_club_id IS DISTINCT FROM club END)
     OR e.source_ledger_id IS DISTINCT FROM ledger_id
     OR e.created_at IS DISTINCT FROM charged_at
     OR tp.tournament_id IS DISTINCT FROM r.tournament_id OR tp.user_id IS DISTINCT FROM player
     OR tp.club_id IS DISTINCT FROM club
     OR l.created_at IS DISTINCT FROM charged_at OR l.amount IS DISTINCT FROM e.gross
    THEN RAISE EXCEPTION 'tournament_fee_charge_evidence_mismatch' USING ERRCODE = '23514'; END IF;

    IF r.source = 'fn_spin_book_entry' THEN
      IF e.entitlement_kind IS DISTINCT FROM 'wallet_charge' OR e.charge_category IS DISTINCT FROM 'tournament_buyin'
       OR e.gross IS DISTINCT FROM weight OR l.from_type IS DISTINCT FROM 'player_wallet'
       OR l.from_entity_id IS DISTINCT FROM player OR l.to_type IS DISTINCT FROM 'prize_liability'
       OR l.to_entity_id IS DISTINCT FROM r.tournament_id OR l.club_id IS DISTINCT FROM club
       OR l.category IS DISTINCT FROM 'tournament_buyin'
       OR (r.player_contributions->>player::text)::numeric IS DISTINCT FROM weight
      THEN RAISE EXCEPTION 'spin_fee_charge_evidence_mismatch' USING ERRCODE = '23514'; END IF;
    ELSE
      IF e.refund_fee IS DISTINCT FROM r.rake_amount OR weight IS DISTINCT FROM r.rake_amount
       OR r.metadata->>'user_id' IS DISTINCT FROM player::text
      THEN RAISE EXCEPTION 'tournament_fee_amount_evidence_mismatch' USING ERRCODE = '23514'; END IF;
      IF r.source IN ('fn_register_for_tournament','fn_register_horse_for_tournament','process_tournament_rebuy') THEN
        source_type := CASE WHEN r.source = 'process_tournament_rebuy' THEN 'rebuy' ELSE 'tournament_buyin' END;
        IF e.entitlement_kind IS DISTINCT FROM 'wallet_charge' OR e.charge_category IS DISTINCT FROM source_type
         OR l.from_type IS DISTINCT FROM 'player_wallet' OR l.from_entity_id IS DISTINCT FROM player
         OR l.to_type IS DISTINCT FROM 'prize_liability' OR l.to_entity_id IS DISTINCT FROM r.tournament_id
         OR l.club_id IS DISTINCT FROM club OR l.category IS DISTINCT FROM source_type
         OR (r.source <> 'process_tournament_rebuy' AND r.metadata->>'registration_id' IS DISTINCT FROM registration::text)
        THEN RAISE EXCEPTION 'tournament_fee_wallet_evidence_mismatch' USING ERRCODE = '23514'; END IF;
      ELSIF r.source = 'fn_register_for_tournament_with_ticket' THEN
        IF e.entitlement_kind IS DISTINCT FROM 'tournament_ticket' OR e.registration_id IS DISTINCT FROM registration
         OR e.source_ticket_id IS NULL OR r.metadata->>'ticket_id' IS DISTINCT FROM e.source_ticket_id::text
         OR r.metadata->>'registration_id' IS DISTINCT FROM registration::text
         OR l.from_type IS DISTINCT FROM 'escrow' OR l.from_entity_id IS DISTINCT FROM e.source_ticket_id
         OR l.to_type IS DISTINCT FROM 'prize_liability' OR l.to_entity_id IS DISTINCT FROM r.tournament_id
         OR l.category IS DISTINCT FROM 'ticket_redeem'
        THEN RAISE EXCEPTION 'tournament_fee_ticket_evidence_mismatch' USING ERRCODE = '23514'; END IF;
      ELSE
        IF e.entitlement_kind IS DISTINCT FROM 'satellite_seat' OR e.registration_id IS DISTINCT FROM registration
         OR e.source_satellite_id IS NULL OR r.metadata->>'satellite_id' IS DISTINCT FROM e.source_satellite_id::text
         OR r.metadata->>'registration_id' IS DISTINCT FROM registration::text
         OR l.from_type IS DISTINCT FROM 'prize_liability' OR l.from_entity_id IS DISTINCT FROM e.source_satellite_id
         OR l.to_type IS DISTINCT FROM 'prize_liability' OR l.to_entity_id IS DISTINCT FROM r.tournament_id
         OR l.category IS DISTINCT FROM 'tournament_buyin'
        THEN RAISE EXCEPTION 'tournament_fee_satellite_evidence_mismatch' USING ERRCODE = '23514'; END IF;
      END IF;
    END IF;
    total_weight := total_weight + weight;
  END LOOP;

  IF r.source = 'fn_spin_book_entry' THEN
    IF (SELECT count(DISTINCT (x->>'weight')::numeric) FROM jsonb_array_elements(manifest->'contributors') x) <> 1
     OR NOT EXISTS (SELECT 1 FROM public.spin_reserve_ledger s
        WHERE s.id = (manifest->>'spin_reserve_id')::uuid AND s.tournament_id = r.tournament_id
          AND s.kind = 'contribution' AND s.seats = 3 AND s.house_rake = r.rake_amount
          AND s.amount = total_weight - r.rake_amount AND s.buy_in = total_weight/3)
    THEN RAISE EXCEPTION 'spin_fee_reserve_evidence_mismatch' USING ERRCODE = '23514'; END IF;
  END IF;

  -- ALLOCATION AND CONTRACT, the producer's arithmetic unchanged: largest
  -- remainder to whole cents, UUID order breaking exact fractional ties.
  total_cents := (r.rake_amount * 100)::bigint;
  SELECT sum(floor(total_cents * (x->>'weight')::numeric / total_weight)) INTO floor_total
    FROM jsonb_array_elements(manifest->'contributors') x;
  remainder_cents := total_cents - floor_total;

  INSERT INTO public.accounting_tournament_fee_batches
    (rake_record_id, tournament_id, source_fingerprint, rake_amount, source_manifest)
  VALUES (r.id, r.tournament_id, fingerprint, r.rake_amount,
    manifest || jsonb_build_object(
      'reconciled_at', transaction_timestamp(),
      'reconciled_by', 'fn_ca_reconcile_stranded_tournament_fee',
      'reconciliation_note', 'charged before the fee cutover; captured from its own recorded evidence'));

  FOR row_plan IN
    SELECT x, floor(total_cents * (x->>'weight')::numeric / total_weight)
      + CASE WHEN row_number() OVER (
          ORDER BY total_cents * (x->>'weight')::numeric / total_weight
            - floor(total_cents * (x->>'weight')::numeric / total_weight) DESC, x->>'player_id'
        ) <= remainder_cents THEN 1 ELSE 0 END AS cents
      FROM jsonb_array_elements(manifest->'contributors') x ORDER BY x->>'player_id'
  LOOP
    item := row_plan.x; credit := row_plan.cents / 100.0;
    BEGIN
      contract := public.fn_accounting_earning_contract((item->>'club_id')::uuid,
        (item->>'player_id')::uuid, credit, actual_union, (item->>'charged_at')::timestamptz);
    EXCEPTION WHEN SQLSTATE '55000' OR SQLSTATE '23514' THEN
      -- 2026-09-27 OWNER-AUTHORIZED BASIS. Only the refusal that says the
      -- agreement was never observed at the charge instant, and only inside
      -- the transaction that recorded this event's owner basis, prices the
      -- contributor through the SAME contract at the event's completion. A
      -- missing agreement at completion still refuses; nothing is guessed.
      GET STACKED DIAGNOSTICS refusal = MESSAGE_TEXT, refusal_state = RETURNED_SQLSTATE;
      SELECT * INTO owner_basis FROM public.accounting_tournament_fee_owner_bases b
       WHERE b.tournament_id = r.tournament_id AND b.transaction_id = txid_current();
      IF owner_basis.tournament_id IS NULL
       OR refusal NOT IN ('accounting_terms_not_observed','cash_commission_earning_club_not_observed') THEN
        RAISE EXCEPTION USING MESSAGE = refusal, ERRCODE = refusal_state; END IF;
      contract := public.fn_accounting_earning_contract((item->>'club_id')::uuid,
        (item->>'player_id')::uuid, credit, actual_union, owner_basis.completed_at)
        || jsonb_build_object('owner_basis', jsonb_build_object(
          'operation_id', owner_basis.operation_id, 'basis_kind', owner_basis.basis_kind,
          'terms_at', owner_basis.completed_at, 'original_terms_at', (item->>'charged_at')::timestamptz,
          'original_refusal', refusal, 'hosting_club_id', owner_basis.hosting_club_id));
    END;
    IF contract->>'player_id' IS DISTINCT FROM item->>'player_id'
     OR contract->>'club_id' IS DISTINCT FROM item->>'club_id'
     OR (contract->>'rake_credit')::numeric IS DISTINCT FROM credit
     OR NULLIF(contract->>'union_id','')::uuid IS DISTINCT FROM actual_union
     OR (contract->>'terms_at')::timestamptz IS DISTINCT FROM
        public.fn_accounting_tournament_source_terms_at(r.tournament_id,(item->>'charged_at')::timestamptz,contract)
    THEN RAISE EXCEPTION 'tournament_fee_contract_scope_mismatch' USING ERRCODE = '23514'; END IF;
    INSERT INTO public.accounting_tournament_fee_sources
      (rake_record_id, tournament_id, player_id, club_id, union_id, coordinator_union_id,
       game_type, registration_id, source_charge_ledger_id, source_entitlement_id,
       charged_at, rake_credit, contract)
    VALUES (r.id, r.tournament_id, (item->>'player_id')::uuid, (item->>'club_id')::uuid, actual_union,
      NULLIF(contract->>'coordinator_union_id','')::uuid, manifest->>'game_type',
      (item->>'registration_id')::uuid, (item->>'charge_ledger_id')::uuid,
      (item->>'entitlement_id')::uuid, (item->>'charged_at')::timestamptz, credit, contract)
    RETURNING id INTO new_id;
    result_ids := array_append(result_ids, new_id);
    allocated := allocated + credit;
  END LOOP;

  IF allocated IS DISTINCT FROM r.rake_amount THEN
    RAISE EXCEPTION 'tournament_fee_credit_not_conserved' USING ERRCODE = '23514'; END IF;

  -- The plan's own test, applied to this record before the caller moves on.
  IF EXISTS (SELECT 1 FROM public.rake_records q
               JOIN public.accounting_tournament_fee_batches b ON b.rake_record_id = q.id
              WHERE q.id = r.id
                AND (b.status IS DISTINCT FROM 'captured'
                  OR b.tournament_id IS DISTINCT FROM r.tournament_id
                  OR b.source_fingerprint IS DISTINCT FROM public.fn_accounting_tournament_fee_fingerprint(q)
                  OR b.rake_amount IS DISTINCT FROM q.rake_amount
                  OR b.rake_amount IS DISTINCT FROM (SELECT sum(s.rake_credit)
                       FROM public.accounting_tournament_fee_sources s WHERE s.rake_record_id = q.id)))
  THEN RAISE EXCEPTION 'tournament_fee_reconciled_batch_would_not_satisfy_the_plan' USING ERRCODE = '23514'; END IF;

  INSERT INTO public.ca_stranded_fee_reconciliations
    (rake_record_id, tournament_id, rake_amount, contributor_count, source_ids, charged_at, cutover_at)
  VALUES (r.id, r.tournament_id, r.rake_amount, array_length(result_ids,1), result_ids, r.created_at, cutoff);

  RETURN jsonb_build_object('accounting_version', 2, 'status', 'captured', 'reconciled', true,
    'rake_record_id', r.id, 'tournament_id', r.tournament_id, 'source_ids', result_ids,
    'rake_credit', allocated, 'payable', false);
END
$_$;


ALTER FUNCTION public.fn_ca_capture_tournament_fee_from_recorded_evidence(p_rake_record_id uuid) OWNER TO postgres;

--
-- TOC entry 45437 (class 0 OID 0)
-- Dependencies: 3676
-- Name: FUNCTION fn_ca_capture_tournament_fee_from_recorded_evidence(p_rake_record_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_capture_tournament_fee_from_recorded_evidence(p_rake_record_id uuid) IS 'Captures a tournament fee charged before the accounting cutover, from the evidence its own producer recorded. Every evidence rule fn_capture_accounting_tournament_fee applies is applied here, against the same rows, with the same cent arithmetic; only its two provenance rules are absent, because neither can be satisfied once the producing transaction has ended. In their place it requires the record to predate the cutover, to hold no batch, and its event to still be live. It writes attribution and never money.';


--
-- TOC entry 7256 (class 1255 OID 35372463)
-- Name: fn_ca_capture_tournament_obligation_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_capture_tournament_obligation_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_b jsonb;v_a jsonb;v_r jsonb;v_t jsonb;v_p jsonb;v_entries uuid[];v_credit uuid;v_refunds uuid[];
 v_key text;
BEGIN
 IF TG_OP<>'INSERT' THEN v_b:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN v_a:=to_jsonb(NEW); END IF;
 IF v_b IS NOT DISTINCT FROM v_a THEN RETURN NULL; END IF;
 v_r:=COALESCE(v_a,v_b);
 SELECT to_jsonb(t) INTO v_t FROM public.tournaments t WHERE id=(v_r->>'tournament_id')::uuid;
 SELECT to_jsonb(p) INTO v_p FROM public.tournament_players p
 WHERE tournament_id=(v_r->>'tournament_id')::uuid AND user_id=(v_r->>'user_id')::uuid;
 SELECT COALESCE(array_agg(id ORDER BY observed_at,id),'{}'::uuid[]) INTO v_entries
 FROM public.tournament_participant_funding_receipts WHERE registration_id=(v_p->>'id')::uuid;
 -- The existing cumulative owner names the exact original payment, never a time-window match.
 v_key:=NULLIF(current_setting('app.pnl_tournament_obligation_credit_key',true),'');
 IF TG_OP='UPDATE' AND NEW.amount_paid>OLD.amount_paid
    AND v_key='tourney:'||NEW.tournament_id::text||':obl:'||NEW.id::text||':'||(round(OLD.amount_paid*100))::bigint::text THEN
   SELECT id INTO v_credit FROM public.tournament_accounting_credit_receipts
   WHERE idempotency_key=v_key AND tournament_id=NEW.tournament_id
     AND user_id=NEW.user_id AND amount=NEW.amount_paid-OLD.amount_paid;
 END IF;
 SELECT COALESCE(array_agg(wallet_transaction_id ORDER BY wallet_transaction_id),'{}'::uuid[]) INTO v_refunds
 FROM public.tournament_refund_tranches WHERE obligation_id=(v_r->>'id')::uuid;
 INSERT INTO public.tournament_obligation_events(
 obligation_id,asset,tournament_id,user_id,operation,before_row,after_row,tournament_snapshot,
 registration_snapshot,entry_receipt_ids,credit_receipt_id,refund_tranche_ids)
 VALUES((v_r->>'id')::uuid,
 CASE WHEN v_t IS NULL THEN 'unknown' WHEN public.fn_ca_tournament_unit_cents((v_r->>'tournament_id')::uuid)=100 THEN 'diamonds' ELSE 'chips' END,
 (v_r->>'tournament_id')::uuid,(v_r->>'user_id')::uuid,TG_OP,
 v_b,v_a,COALESCE(v_t,jsonb_build_object('id',v_r->>'tournament_id','scope_unavailable',true)),v_p,v_entries,v_credit,v_refunds);
 RETURN NULL;
END $$;


