-- Name: fn_ca_cash_cutover_week_split_by(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_cash_cutover_week_split_by(p_starts_at timestamp with time zone) RETURNS TABLE(splits boolean, week_start timestamp with time zone, week_end timestamp with time zone, orphaned_hours numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT p_starts_at IS DISTINCT FROM w.s,
         w.s,
         ((w.s AT TIME ZONE 'America/Los_Angeles') + interval '7 days') AT TIME ZONE 'America/Los_Angeles',
         round((extract(epoch FROM (p_starts_at - w.s)) / 3600)::numeric, 2)
    FROM (SELECT public.fn_union_week_start(p_starts_at) AS s) w;
$$;


