--
-- TOC entry 45442 (class 0 OID 0)
-- Dependencies: 6377
-- Name: FUNCTION fn_ca_cash_cutover_week_split_by(p_starts_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_cash_cutover_week_split_by(p_starts_at timestamp with time zone) IS 'Whether a cash accrual cutover armed at this instant would split a union accounting week, and which week. A split week begins before the cutover, so fn_accounting_union_earned_plan refuses it as uncertified and every union control that reads the open week fails until the next week begins. Read by ca_cash_cutover_is_week_aligned before the cutover may be armed.';


--
-- TOC entry 7214 (class 1255 OID 152613295)
-- Name: fn_ca_cash_entry_need(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_cash_entry_need(p_user_id uuid, p_table_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_min numeric;
  v_max numeric;
  v_tournament uuid;
  v_need numeric;
BEGIN
  SELECT t.min_buy_in, t.max_buy_in, t.tournament_id
    INTO v_min, v_max, v_tournament
    FROM public.tables t WHERE t.id = p_table_id;
  IF NOT FOUND THEN
    RETURN 0;
  END IF;
  v_need := COALESCE(v_min, 0);
  IF v_tournament IS NULL AND p_user_id IS NOT NULL THEN
    v_need := GREATEST(v_need, COALESCE(public.fn_cash_rejoin_floor(p_user_id, p_table_id), 0));
  END IF;
  IF v_max IS NOT NULL AND v_max > 0 THEN
    v_need := LEAST(v_need, v_max);
  END IF;
  RETURN GREATEST(v_need, 0);
END
$$;


