--
-- TOC entry 8875 (class 1255 OID 152613292)
-- Name: fn_ca_cash_paying_club(uuid, uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_cash_paying_club(p_user_id uuid, p_table_id uuid, p_preferred_club uuid, p_amount numeric) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_union uuid;
  v_default uuid;
  v_balance numeric;
BEGIN
  IF p_user_id IS NULL OR p_table_id IS NULL OR p_amount IS NULL OR p_amount <= 0 THEN
    RETURN NULL;
  END IF;

  SELECT t.union_id INTO v_union
    FROM public.tables t
    JOIN public.clubs c ON c.id = t.club_id
   WHERE t.id = p_table_id
     AND t.tournament_id IS NULL
     AND c.asset IS DISTINCT FROM 'diamonds';
  IF v_union IS NULL THEN
    RETURN NULL;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.table_seats ts
      JOIN public.tables t2 ON t2.id = ts.table_id
     WHERE ts.user_id = p_user_id AND ts.left_at IS NULL AND ts.club_id IS NOT NULL
       AND t2.union_id = v_union
       AND lower(coalesce(t2.status, '')) NOT IN ('closed','completed','cancelled','finished')
  ) THEN
    RETURN NULL;
  END IF;

  v_default := public.fn_seat_club_for_user(p_user_id, p_table_id, p_preferred_club);
  IF v_default IS NOT NULL THEN
    SELECT m.chip_balance INTO v_balance
      FROM public.club_members m
     WHERE m.user_id = p_user_id AND m.club_id = v_default
       AND m.status IN ('active', 'approved');
    IF COALESCE(v_balance, 0) >= p_amount THEN
      RETURN NULL;
    END IF;
  END IF;

  RETURN public.fn_ca_union_wallet_that_can_pay(p_user_id, v_union, p_amount);
END
$$;


ALTER FUNCTION public.fn_ca_cash_paying_club(p_user_id uuid, p_table_id uuid, p_preferred_club uuid, p_amount numeric) OWNER TO postgres;

--
-- TOC entry 6481 (class 1255 OID 33274883)
-- Name: fn_ca_cash_pot_evidence_append_only(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_cash_pot_evidence_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_actual record; v_j jsonb; v_r record; v_position integer:=0; v_keys text[];
BEGIN
  IF TG_OP IN ('UPDATE','DELETE','TRUNCATE') THEN
    RAISE EXCEPTION 'cash_pot_check_evidence_is_immutable';
  END IF;
  IF TG_OP <> 'INSERT' OR TG_TABLE_SCHEMA <> 'public'
     OR TG_TABLE_NAME <> 'ca_cash_pot_check_evidence' THEN
    RAISE EXCEPTION 'cash_pot_check_evidence_guard_wrong_target';
  END IF;
  IF jsonb_typeof(NEW.anomalies) IS DISTINCT FROM 'array'
     OR jsonb_array_length(NEW.anomalies) NOT BETWEEN 1 AND 10000
     OR NEW.detail_bytes IS DISTINCT FROM octet_length(convert_to(NEW.anomalies::text,'UTF8'))
     OR NEW.header_bytes IS DISTINCT FROM octet_length(convert_to(NEW.summary::text,'UTF8'))
     OR NEW.detail_bytes+NEW.header_bytes>8388608 THEN
    RAISE EXCEPTION 'cash_pot_check_evidence_array_mismatch';
  END IF;
  FOR v_j IN SELECT value FROM jsonb_array_elements(NEW.anomalies) LOOP
    v_position:=v_position+1;
    IF jsonb_typeof(v_j) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'cash_pot_check_evidence_detail_mismatch';
    END IF;
    SELECT array_agg(k ORDER BY k) INTO v_keys FROM jsonb_object_keys(v_j) k;
    IF v_keys IS DISTINCT FROM ARRAY['absolute_residual','bbj','check_id','condition_kind','created_at','evidence_bytes','hand_id','hand_number','ordinal','pot','rake','recorded_awarded','signed_residual','table_id','winner_count','winner_state']::text[]
       OR jsonb_typeof(v_j->'check_id') IS DISTINCT FROM 'string'
       OR jsonb_typeof(v_j->'hand_id') IS DISTINCT FROM 'string'
       OR jsonb_typeof(v_j->'ordinal') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_j->'evidence_bytes') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_j->'winner_count') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_j->'condition_kind') IS DISTINCT FROM 'string'
       OR jsonb_typeof(v_j->'winner_state') IS DISTINCT FROM 'string'
       OR jsonb_typeof(v_j->'created_at') IS DISTINCT FROM 'string'
       OR jsonb_typeof(v_j->'table_id') NOT IN ('string','null')
       OR jsonb_typeof(v_j->'hand_number') NOT IN ('number','null')
       OR EXISTS(SELECT 1 FROM unnest(ARRAY['pot','rake','bbj','recorded_awarded','signed_residual','absolute_residual']) k
          WHERE jsonb_typeof(v_j->k)<>'number'
            AND NOT(jsonb_typeof(v_j->k)='string' AND v_j->>k IN ('NaN','Infinity','-Infinity'))) THEN
      RAISE EXCEPTION 'cash_pot_check_evidence_detail_mismatch';
    END IF;
    SELECT * INTO v_r FROM jsonb_to_record(v_j) AS d(
      check_id uuid,
      ordinal integer,
      condition_kind text,
      hand_id uuid,
      table_id uuid,
      hand_number integer,
      created_at timestamptz,
      pot numeric,
      rake numeric,
      bbj numeric,
      recorded_awarded numeric,
      winner_count integer,
      winner_state text,
      signed_residual numeric,
      absolute_residual numeric,
      evidence_bytes integer);
    IF v_r.check_id IS DISTINCT FROM NEW.check_id OR v_j->>'check_id' IS DISTINCT FROM NEW.check_id::text
       OR v_r.hand_id IS NULL OR v_j->>'hand_id' IS DISTINCT FROM v_r.hand_id::text
       OR v_r.ordinal IS DISTINCT FROM v_position OR v_r.created_at IS NULL
       OR v_r.winner_count IS NULL OR v_r.winner_count<0
       OR (v_r.pot>0) IS DISTINCT FROM true
       OR (v_r.winner_state<>'array' AND v_r.winner_count<>0)
       OR (v_r.winner_count=0 AND v_r.recorded_awarded<>0)
       OR v_r.winner_state NOT IN ('sql_null','json_null','array','object','string','number','boolean')
       OR v_r.evidence_bytes IS DISTINCT FROM octet_length(convert_to((v_j-'evidence_bytes')::text,'UTF8'))
       OR v_r.signed_residual IS DISTINCT FROM v_r.pot-v_r.rake-v_r.bbj-v_r.recorded_awarded
       OR v_r.absolute_residual IS DISTINCT FROM abs(v_r.signed_residual)
       OR (CASE WHEN v_r.condition_kind='pot_not_distributed'
            THEN v_r.winner_count>0 AND v_r.absolute_residual>0.01
            WHEN v_r.condition_kind='no_winner_recorded'
            THEN v_r.winner_count=0 AND v_r.pot-v_r.rake-v_r.bbj>0.01
            ELSE false END) IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'cash_pot_check_evidence_detail_mismatch';
    END IF;
  END LOOP;
  SELECT count(*) n,count(DISTINCT hand_id) distinct_hands,
         count(*) FILTER (WHERE condition_kind='pot_not_distributed') bad,
         COALESCE(round(sum(absolute_residual) FILTER (WHERE condition_kind='pot_not_distributed'),2),0) bad_chips,
         count(*) FILTER (WHERE condition_kind='no_winner_recorded') nowin,
         COALESCE(round(sum(pot-rake-bbj) FILTER (WHERE condition_kind='no_winner_recorded'),2),0) nowin_chips
    INTO v_actual FROM jsonb_to_recordset(NEW.anomalies) AS d(
      check_id uuid,
      ordinal integer,
      condition_kind text,
      hand_id uuid,
      table_id uuid,
      hand_number integer,
      created_at timestamptz,
      pot numeric,
      rake numeric,
      bbj numeric,
      recorded_awarded numeric,
      winner_count integer,
      winner_state text,
      signed_residual numeric,
      absolute_residual numeric,
      evidence_bytes integer);
  IF v_actual.n IS DISTINCT FROM NEW.anomaly_rows OR v_actual.distinct_hands IS DISTINCT FROM v_actual.n
     OR NEW.summary->>'check_id' IS DISTINCT FROM NEW.check_id::text
     OR NEW.summary->>'schema_version' IS DISTINCT FROM NEW.schema_version::text
     OR NEW.summary->>'source_contract' IS DISTINCT FROM NEW.source_contract
     OR (NEW.summary#>>'{result,ok}')::boolean IS DISTINCT FROM true
     OR (NEW.summary#>>'{result,hands_checked}')::bigint < v_actual.n
     OR (NEW.summary#>>'{result,hands_checked}') IS NULL
     OR (NEW.summary#>>'{result,pot_not_distributed}')::bigint IS DISTINCT FROM v_actual.bad
     OR (NEW.summary#>>'{result,pot_not_distributed_chips}')::numeric IS DISTINCT FROM v_actual.bad_chips
     OR (NEW.summary#>>'{result,no_winner_recorded}')::bigint IS DISTINCT FROM v_actual.nowin
     OR (NEW.summary#>>'{result,no_winner_recorded_chips}')::numeric IS DISTINCT FROM v_actual.nowin_chips
     OR (NEW.summary#>>'{result,conditions_alerted}')::integer IS DISTINCT FROM
       (CASE WHEN v_actual.bad>0 THEN 1 ELSE 0 END+CASE WHEN v_actual.nowin>0 THEN 1 ELSE 0 END) THEN
    RAISE EXCEPTION 'cash_pot_check_evidence_header_mismatch';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_ca_cash_pot_evidence_append_only() OWNER TO postgres;

--
-- TOC entry 8976 (class 1255 OID 166027192)
-- Name: fn_ca_cash_reporting_club(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_cash_reporting_club(p_union uuid, p_table_club uuid, p_user uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE((
    SELECT cm.club_id FROM public.club_members cm
      JOIN public.union_clubs uc ON uc.club_id = cm.club_id AND uc.union_id = p_union
     WHERE p_union IS NOT NULL AND p_user IS NOT NULL AND cm.user_id = p_user
     ORDER BY cm.joined_at ASC NULLS LAST, cm.club_id
     LIMIT 1), p_table_club);
$$;


ALTER FUNCTION public.fn_ca_cash_reporting_club(p_union uuid, p_table_club uuid, p_user uuid) OWNER TO postgres;

--
-- TOC entry 9558 (class 1255 OID 183809218)
-- Name: fn_ca_cash_seat_club(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_cash_seat_club(p_table uuid, p_user uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT s.club_id FROM public.table_seats s
      WHERE s.table_id = p_table AND s.user_id = p_user AND s.left_at IS NULL
        AND s.club_id IS NOT NULL LIMIT 1),
    (SELECT x.funding_club_id FROM public.cash_participant_funding_receipts x
      WHERE x.operation_kind = 'buyin' AND x.table_id = p_table AND x.account_entity_id = p_user
      ORDER BY x.seat_joined_at DESC NULLS LAST LIMIT 1));
$$;


ALTER FUNCTION public.fn_ca_cash_seat_club(p_table uuid, p_user uuid) OWNER TO postgres;

--
-- TOC entry 5100 (class 1255 OID 183809221)
-- Name: fn_ca_cash_table_reporting_club(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_cash_table_reporting_club(p_union uuid, p_table_club uuid, p_user uuid, p_table uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    CASE WHEN p_table IS NOT NULL AND p_user IS NOT NULL THEN public.fn_ca_cash_seat_club(p_table, p_user) END,
    public.fn_ca_cash_reporting_club(p_union, p_table_club, p_user));
$$;


ALTER FUNCTION public.fn_ca_cash_table_reporting_club(p_union uuid, p_table_club uuid, p_user uuid, p_table uuid) OWNER TO postgres;

--
-- TOC entry 5642 (class 1255 OID 152613302)
-- Name: fn_ca_cash_wallet_covers(uuid, uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_cash_wallet_covers(p_user_id uuid, p_table_id uuid, p_preferred_club uuid, p_amount numeric) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club uuid;
  v_balance numeric;
BEGIN
  IF p_user_id IS NULL OR p_table_id IS NULL OR p_amount IS NULL OR p_amount <= 0 THEN
    RETURN true;
  END IF;
  IF EXISTS (SELECT 1 FROM public.tables t JOIN public.clubs c ON c.id = t.club_id
              WHERE t.id = p_table_id AND c.asset = 'diamonds') THEN
    RETURN public.fn_poker_diamond_wallet_covers(p_user_id,p_table_id,p_amount);
  END IF;

  v_club := public.fn_seat_club_for_user(p_user_id, p_table_id, p_preferred_club);
  IF v_club IS NOT NULL THEN
    SELECT m.chip_balance INTO v_balance
      FROM public.club_members m
     WHERE m.user_id = p_user_id AND m.club_id = v_club
       AND m.status IN ('active', 'approved');
    IF COALESCE(v_balance, 0) >= p_amount THEN
      RETURN true;
    END IF;
  END IF;

  RETURN public.fn_ca_cash_paying_club(p_user_id, p_table_id, p_preferred_club, p_amount) IS NOT NULL;
END
$$;


ALTER FUNCTION public.fn_ca_cash_wallet_covers(p_user_id uuid, p_table_id uuid, p_preferred_club uuid, p_amount numeric) OWNER TO postgres;

--
-- TOC entry 9400 (class 1255 OID 167526522)
-- Name: fn_ca_cashier_ticket_target_in_club(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_cashier_ticket_target_in_club(p_tournament_id uuid, p_club_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  /* The scope the ticket finder already uses: the club's own event, or an
     event of a union this club belongs to (the host club of a union event is
     in its own union without a union_clubs row). */
  SELECT COALESCE((
    SELECT (t.union_id IS NULL AND t.club_id = p_club_id)
        OR (t.union_id IS NOT NULL
            AND (t.club_id = p_club_id OR EXISTS (
                  SELECT 1 FROM public.union_clubs uc
                   WHERE uc.union_id = t.union_id AND uc.club_id = p_club_id)))
      FROM public.tournaments t WHERE t.id = p_tournament_id), false);
$$;


ALTER FUNCTION public.fn_ca_cashier_ticket_target_in_club(p_tournament_id uuid, p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 7697 (class 1255 OID 167526521)
-- Name: fn_ca_cashier_ticket_target_state(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_cashier_ticket_target_state(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_split record;
  v_is_bounty boolean;
  v_late boolean := false;
  v_entries integer;
BEGIN
  /* The same gates the ticket and wallet entry doors apply, read without
     taking any lock of their own: open for entry (ANNOUNCED or REGISTERING,
     or RUNNING inside late registration), pool not finalized, not full, not a
     seat-first format, not a Diamond event, and a finite nonzero price. */
  SELECT * INTO v_t FROM public.tournaments t WHERE t.id = p_tournament_id;
  IF v_t.id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  IF public.fn_poker_diamond_tournament(v_t.id) THEN
    RETURN jsonb_build_object('ok',false,'reason','diamond_tournament');
  END IF;
  IF COALESCE(v_t.prize_pool_finalized,false) THEN
    RETURN jsonb_build_object('ok',false,'reason','registration_closed');
  END IF;
  IF v_t.status = 'RUNNING' THEN
    v_late := public.fn_tournament_late_registration_open(v_t.id);
    IF NOT v_late THEN
      RETURN jsonb_build_object('ok',false,'reason','registration_closed');
    END IF;
  ELSIF v_t.status NOT IN ('ANNOUNCED','REGISTERING') THEN
    RETURN jsonb_build_object('ok',false,'reason','registration_closed');
  END IF;
  IF lower(COALESCE(v_t.variant,'')) = 'spin'
     OR (v_t.max_players IS NOT NULL AND v_t.max_players > 0
         AND v_t.max_players <= 2) THEN
    IF NOT public.fn_ca_tournament_is_unlimited(v_t.id) THEN
      RETURN jsonb_build_object('ok',false,'reason','seat_first_variant');
    END IF;
  END IF;
  IF v_t.max_players IS NOT NULL AND v_t.max_players > 0 THEN
    SELECT count(*) INTO v_entries FROM public.tournament_players tp
     WHERE tp.tournament_id = v_t.id;
    IF GREATEST(COALESCE(v_t.current_players,0), v_entries) >= v_t.max_players
       AND NOT public.fn_ca_tournament_is_unlimited(v_t.id) THEN
      RETURN jsonb_build_object('ok',false,'reason','tournament_full');
    END IF;
  END IF;
  v_is_bounty := COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
              OR COALESCE(v_t.is_mystery_bounty,false);
  SELECT * INTO v_split FROM public.fn_tournament_entry_split(
    v_t.buy_in_amount, v_t.buy_in_fee, v_t.bounty_amount, v_is_bounty);
  IF v_split.charge IS NULL OR v_split.prize IS NULL
     OR v_split.bounty IS NULL OR v_split.rake IS NULL
     OR v_split.charge::text IN ('NaN','Infinity','-Infinity')
     OR v_split.prize < 0 OR v_split.bounty < 0 OR v_split.rake < 0
     OR v_split.charge IS DISTINCT FROM
          round(v_split.prize + v_split.bounty + v_split.rake, 2) THEN
    RETURN jsonb_build_object('ok',false,'reason','no_finite_ticket_contract');
  END IF;
  IF v_split.charge <= 0 THEN
    RETURN jsonb_build_object('ok',false,'reason','free_tournament');
  END IF;
  IF v_split.charge > 1e9 OR v_split.charge <> round(v_split.charge,2) THEN
    RETURN jsonb_build_object('ok',false,'reason','no_finite_ticket_contract');
  END IF;
  RETURN jsonb_build_object(
    'ok',true,'tournament_id',v_t.id,'name',v_t.name,
    'start_time',v_t.start_time,'status',v_t.status,
    'late_registration',v_late,
    'price',v_split.charge,'entry_prize',v_split.prize,
    'entry_bounty',v_split.bounty,'entry_fee',v_split.rake,
    'club_id',v_t.club_id,'union_id',v_t.union_id);
END;
$$;


