--
-- TOC entry 6784 (class 1255 OID 18104075)
-- Name: fn_ca_chip_ledger_enrich(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_chip_ledger_enrich() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_prev text;
BEGIN
  NEW.amount := round(NEW.amount, 2);
  NEW.created_at := COALESCE(NEW.created_at, now());

  NEW.epoch_id      := COALESCE(NEW.epoch_id, public.fn_ca_current_epoch());
  NEW.actor_service := COALESCE(NEW.actor_service,
                                current_setting('application_name', true));
  NEW.db_role       := COALESCE(NEW.db_role, current_user);
  NEW.correlation_id := COALESCE(NEW.correlation_id,
      NULLIF(current_setting('app.ledger_correlation', true), '')::uuid);
  NEW.settlement_id  := COALESCE(NEW.settlement_id,
      NULLIF(current_setting('app.ledger_settlement', true), ''));
  IF NEW.idempotency_key IS NULL THEN
    NEW.idempotency_key := NULLIF(current_setting('app.ledger_idempotency_key', true), '');
    IF NEW.idempotency_key IS NOT NULL THEN
      -- consume-once: the next row in this transaction must not inherit it
      PERFORM set_config('app.ledger_idempotency_key', '', true);
    END IF;
  END IF;

  /* PHASE 6.4 (2026-09-05): EVERY LEG NAMES ITS HAND OR ITS EVENT. The doors
     that know the hand say so on app.ledger_hand_id (the rake door and the
     BBJ drop, since today) or on a 'bbj:<hand>' settlement; the rake
     settlement is not read for it because it carries a random key when the
     hand is unknown, and a guessed hand is worse than none; a spin's reserve legs
     carry the spin on their prize_liability side. Read them here, once, so
     the hand and the event are columns a per-hand audit can index on rather
     than strings it has to parse. 231,211 legs a day; 29,617 named a hand
     and 50,359 an event before this. */
  IF NEW.hand_id IS NULL THEN
    NEW.hand_id := NULLIF(current_setting('app.ledger_hand_id', true), '')::uuid;
    IF NEW.hand_id IS NULL AND NEW.settlement_id ~ '^bbj:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      NEW.hand_id := split_part(NEW.settlement_id, ':', 2)::uuid;
    END IF;
  END IF;
  IF NEW.tournament_id IS NULL THEN
    NEW.tournament_id := NULLIF(current_setting('app.ledger_tournament_id', true), '')::uuid;
    /* PHASE 6 GATE (2026-09-05): a prize_liability side IS the event, on every
       category, not only the two spin ones. This is what the 6.4 measurement
       missed: 777 tournament rake settlements in three hours (the fee leaving
       an event to a union rake wallet or a club treasury) and every tournament
       add-on named nothing. Read against the rows first: all 777 from_entity_id
       values are real tournaments. The FROM side wins when both sides are
       prize_liability (a satellite seat's pool transfer, which already stamps
       the satellite itself). */
    IF NEW.tournament_id IS NULL THEN
      IF NEW.from_type = 'prize_liability' THEN NEW.tournament_id := NEW.from_entity_id;
      ELSIF NEW.to_type = 'prize_liability' THEN NEW.tournament_id := NEW.to_entity_id;
      END IF;
    END IF;
  END IF;
  /* PHASE 6 GATE: and a table_stack side IS the table. Every cash buy-in,
     add-on and cash-out carries the table on its felt side (231, 53 and 222
     of each measured in the same window, every one a real table row) and
     none of them carried table_id. A cash buy-in is not a hand; the table is
     the name it has. */
  IF NEW.table_id IS NULL THEN
    IF NEW.to_type = 'table_stack' THEN NEW.table_id := NEW.to_entity_id;
    ELSIF NEW.from_type = 'table_stack' THEN NEW.table_id := NEW.from_entity_id;
    END IF;
  END IF;

  -- Tamper evidence: monotone sequence + per-row content checksum. NOT chained
  -- through the previous row's hash at insert time - that would put a global
  -- serialization point (and deadlock surface) inside every money transaction,
  -- which the availability policy forbids. prev_hash is best-effort forensics.
  NEW.chain_seq := nextval('public.chip_ledger_chain_seq');
  SELECT row_hash INTO v_prev
    FROM public.chip_ledger
   WHERE chain_seq = NEW.chain_seq - 1;
  NEW.prev_hash := v_prev;
  NEW.row_hash := encode(extensions.digest(
      'v1'
      || '|' || NEW.chain_seq::text
      || '|' || COALESCE(NEW.epoch_id::text,'')
      || '|' || NEW.amount::text
      || '|' || NEW.from_type || ':' || COALESCE(NEW.from_entity_id::text,'')
      || '|' || NEW.to_type   || ':' || COALESCE(NEW.to_entity_id::text,'')
      || '|' || NEW.category
      || '|' || COALESCE(NEW.idempotency_key,'')
      || '|' || COALESCE(NEW.correlation_id::text,'')
      || '|' || NEW.created_at::text,
      'sha256'), 'hex');
  RETURN NEW;
END $_$;


ALTER FUNCTION public.fn_ca_chip_ledger_enrich() OWNER TO postgres;

--
-- TOC entry 6225 (class 1255 OID 23902707)
-- Name: fn_ca_chip_statement(text, uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_chip_statement(p_scope text DEFAULT 'player'::text, p_club_id uuid DEFAULT NULL::uuid, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller     uuid := auth.uid();
  v_entity     uuid;
  v_type       text;
  v_col        text;
  v_key        text;
  v_limit      int := GREATEST(LEAST(COALESCE(p_limit, 50), 200), 1);
  v_balance    numeric;
  v_clubs      jsonb := '[]'::jsonb;
  v_legs       jsonb;
  v_has_more   boolean;
  v_next       timestamptz;
  v_boundary_has_more boolean;
  v_snap_bal   numeric;
  v_snap_at    timestamptz;
  v_snap_cum   numeric;
  v_snap_base  boolean;
  v_in         numeric;
  v_out        numeric;
  v_since_legs bigint;
  v_expected   numeric;
  v_audit      jsonb;
  v_t0         timestamptz := clock_timestamp();
BEGIN
  IF v_caller IS NULL AND COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  IF p_scope = 'player' THEN
    IF v_caller IS NULL THEN
      RAISE EXCEPTION 'a player statement is the caller''s own; there is no other player to ask for' USING ERRCODE = '42501';
    END IF;
    v_entity := v_caller;              -- never a parameter: the statement is always your own
    v_type   := 'player_wallet';
    v_col    := 'club_members.chip_balance';
  ELSIF p_scope = 'club_treasury' THEN
    IF p_club_id IS NULL THEN
      RAISE EXCEPTION 'club_treasury needs p_club_id';
    END IF;
    IF public.ca_can_view_club_finances(p_club_id) IS NOT TRUE THEN
      RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
    END IF;
    v_entity := p_club_id;
    v_type   := 'club_treasury';
    v_col    := 'clubs.chip_treasury';
  ELSE
    RAISE EXCEPTION 'scope must be player or club_treasury';
  END IF;
  v_key := v_type || ':' || v_entity::text || ':' || v_col;

  -- A page opened before this upgrade may submit an already ambiguous cursor.
  -- A timestamp alone cannot show which same-timestamp legs that page displayed.
  IF p_before IS NOT NULL THEN
    SELECT count(*) > 1 INTO v_boundary_has_more FROM (
      (SELECT 1 FROM public.chip_ledger l
        WHERE l.to_entity_id=v_entity AND l.to_type=v_type
          AND l.created_at=p_before AND (p_club_id IS NULL OR l.club_id=p_club_id)
        LIMIT 2)
      UNION ALL
      (SELECT 1 FROM public.chip_ledger l
        WHERE l.from_entity_id=v_entity AND l.from_type=v_type
          AND l.created_at=p_before AND (p_club_id IS NULL OR l.club_id=p_club_id)
        LIMIT 2)
      LIMIT 2
    ) boundary_legs;
    IF v_boundary_has_more THEN
      RAISE EXCEPTION 'Statement pagination has been upgraded; refresh the page to continue.'
        USING ERRCODE='PST01';
    END IF;
  END IF;

  /* THE BALANCE NOW, through the same reader the nightly replay uses. */
  v_balance := public.fn_ca_account_balance(v_type, v_entity, NULL, v_col);

  IF p_scope = 'player' THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'club_id', m.club_id, 'club_name', c.name, 'balance', round(COALESCE(m.chip_balance, 0), 2))
             ORDER BY c.name), '[]'::jsonb)
      INTO v_clubs
      FROM public.club_members m
      JOIN public.clubs c ON c.id = m.club_id
     WHERE m.user_id = v_entity;
  END IF;

  /* THE PAGE. Both sides, newest first, from this account's point of view. */
  WITH mine AS (
    /* One index range per side - (to_entity_id, created_at DESC) and
       (from_entity_id, created_at DESC) both exist - each already limited,
       then merged. An OR across the two sides would be a bitmap of every leg
       the account ever had, which for a horse is tens of thousands. */
    (SELECT l.id, l.created_at, l.amount, l.category, l.description, l.club_id,
            l.table_id, l.tournament_id, l.hand_id, l.settlement_id,
            'in'::text AS direction, l.from_type AS counterparty_type,
            l.from_label AS counterparty_label, l.from_entity_id AS counterparty_id
       FROM public.chip_ledger l
      WHERE l.to_entity_id = v_entity AND l.to_type = v_type
        AND (p_club_id IS NULL OR l.club_id = p_club_id)
        AND (p_before IS NULL OR l.created_at < p_before)
      ORDER BY l.created_at DESC, l.id DESC
      LIMIT v_limit + 1)
    UNION ALL
    (SELECT l.id, l.created_at, l.amount, l.category, l.description, l.club_id,
            l.table_id, l.tournament_id, l.hand_id, l.settlement_id,
            'out'::text, l.to_type, l.to_label, l.to_entity_id
       FROM public.chip_ledger l
      WHERE l.from_entity_id = v_entity AND l.from_type = v_type
        AND (p_club_id IS NULL OR l.club_id = p_club_id)
        AND (p_before IS NULL OR l.created_at < p_before)
      ORDER BY l.created_at DESC, l.id DESC
      LIMIT v_limit + 1)
  ), page AS (
    SELECT * FROM mine ORDER BY created_at DESC, id DESC LIMIT v_limit
  )
  SELECT COALESCE((SELECT jsonb_agg(jsonb_build_object(
             'id', p.id, 'at', p.created_at, 'direction', p.direction, 'amount', round(p.amount, 2),
             'category', CASE WHEN p.category = 'horse_funding' THEN 'table_funding' ELSE p.category END,
             'description', CASE WHEN p.category = 'horse_funding' OR p.description ~* 'horse' THEN NULL
                                 ELSE p.description END,
             'counterparty_type', p.counterparty_type, 'counterparty_label', p.counterparty_label,
             'counterparty_id', p.counterparty_id,
             'club_id', p.club_id, 'table_id', p.table_id, 'tournament_id', p.tournament_id,
             'hand_id', p.hand_id, 'settlement_id', p.settlement_id)
             ORDER BY p.created_at DESC, p.id DESC) FROM page p), '[]'::jsonb),
         (SELECT count(*) FROM mine) > v_limit,   -- more than a page on either side, or both together
         (SELECT min(p.created_at) FROM page p),
         (SELECT count(*) FROM mine m WHERE m.created_at=(SELECT min(created_at) FROM page))
           > (SELECT count(*) FROM page p WHERE p.created_at=(SELECT min(created_at) FROM page))
    INTO v_legs, v_has_more, v_next, v_boundary_has_more;

  -- A cached client can only send a timestamp. Refuse an ambiguous boundary
  -- rather than acknowledging a page whose continuation skips ledger legs.
  IF v_boundary_has_more THEN
    RAISE EXCEPTION 'Statement pagination has been upgraded; refresh the page to continue.'
      USING ERRCODE='PST01';
  END IF;

  /* THE AUDIT. The last nightly reading of this account, and the journal
     since it. Balance-at-reading plus net-since equals balance-now, or it
     does not, and either way the player sees the same three numbers the
     platform's own control sees. */
  SELECT s.balance, s.taken_at, s.cum_unexplained, s.is_baseline
    INTO v_snap_bal, v_snap_at, v_snap_cum, v_snap_base
    FROM public.ca_account_snapshots s
   WHERE s.account_key = v_key
   ORDER BY s.taken_at DESC
   LIMIT 1;

  IF v_snap_at IS NULL THEN
    v_audit := jsonb_build_object(
      'status', 'no_reading_yet',
      'detail', 'this account has not yet been read by the nightly ledger replay (fn_ca_ledger_replay reads every account that moved in the last 26 hours, at 06:40 UTC). The legs above are complete; there is no reading to compare the balance against yet.',
      'balance_now', round(COALESCE(v_balance, 0), 2));
  ELSE
    SELECT COALESCE(sum(l.amount) FILTER (WHERE l.to_entity_id = v_entity AND l.to_type = v_type), 0),
           COALESCE(sum(l.amount) FILTER (WHERE l.from_entity_id = v_entity AND l.from_type = v_type), 0),
           count(*)
      INTO v_in, v_out, v_since_legs
      FROM public.chip_ledger l
     WHERE ((l.to_entity_id = v_entity AND l.to_type = v_type) OR (l.from_entity_id = v_entity AND l.from_type = v_type))
       AND l.created_at > v_snap_at;
    v_expected := round(v_snap_bal + v_in - v_out, 2);
    v_audit := jsonb_build_object(
      'status', CASE WHEN v_balance IS NULL THEN 'no_balance'
                     WHEN abs(round(v_balance, 2) - v_expected) < 0.005 THEN 'reconciles'
                     ELSE 'does_not_reconcile' END,
      'read_at', v_snap_at,
      'balance_at_reading', round(v_snap_bal, 2),
      'reading_is_baseline', COALESCE(v_snap_base, false),
      'cumulative_unexplained_at_reading', round(COALESCE(v_snap_cum, 0), 2),
      'in_since', round(v_in, 2),
      'out_since', round(v_out, 2),
      'legs_since', v_since_legs,
      'expected_now', v_expected,
      'balance_now', round(COALESCE(v_balance, 0), 2),
      'unexplained', CASE WHEN v_balance IS NULL THEN NULL ELSE round(round(v_balance, 2) - v_expected, 2) END,
      'detail', 'balance_at_reading + in_since - out_since = expected_now. The nightly replay (fn_ca_ledger_replay) makes this same comparison for every account and files an incident when it fails; a difference here that persists past the next 06:40 UTC reading is one the platform has also seen.');
  END IF;

  RETURN jsonb_build_object(
    'scope', p_scope,
    'entity_id', v_entity,
    'account', v_key,
    'club_filter', p_club_id,
    'balance_now', round(COALESCE(v_balance, 0), 2),
    'balance_exists', v_balance IS NOT NULL,
    'clubs', v_clubs,
    'legs', v_legs,
    'has_more', v_has_more,
    'next_before', v_next,
    'audit', v_audit,
    'generated_at', now(),
    'ms', round(extract(epoch from (clock_timestamp() - v_t0)) * 1000));
END $$;


ALTER FUNCTION public.fn_ca_chip_statement(p_scope text, p_club_id uuid, p_before timestamp with time zone, p_limit integer) OWNER TO postgres;

--
-- TOC entry 45459 (class 0 OID 0)
-- Dependencies: 6225
-- Name: FUNCTION fn_ca_chip_statement(p_scope text, p_club_id uuid, p_before timestamp with time zone, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_chip_statement(p_scope text, p_club_id uuid, p_before timestamp with time zone, p_limit integer) IS 'Phase 7 (roadmap 9.5). A chip statement a player - horse or human, identically - or a club operator can audit: balance now, a page of legs with direction and counterparty, and the comparison against the last nightly reading in ca_account_snapshots (balance_at_reading + in_since - out_since vs balance_now). scope=player is always the caller''s own wallet; scope=club_treasury is gated by ca_can_view_club_finances.';


--
-- TOC entry 5420 (class 1255 OID 31028413)
-- Name: fn_ca_chip_statement_page(text, uuid, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_chip_statement_page(p_scope text DEFAULT 'player'::text, p_club_id uuid DEFAULT NULL::uuid, p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller     uuid := auth.uid();
  v_entity     uuid;
  v_type       text;
  v_col        text;
  v_key        text;
  v_limit      int := GREATEST(LEAST(COALESCE(p_limit, 50), 200), 1);
  v_balance    numeric;
  v_clubs      jsonb := '[]'::jsonb;
  v_legs       jsonb;
  v_has_more   boolean;
  v_next       timestamptz;
  v_next_cursor jsonb;
  v_before timestamptz;
  v_before_id uuid;
  v_before_direction text;
  v_snap_bal   numeric;
  v_snap_at    timestamptz;
  v_snap_cum   numeric;
  v_snap_base  boolean;
  v_in         numeric;
  v_out        numeric;
  v_since_legs bigint;
  v_expected   numeric;
  v_audit      jsonb;
  v_t0         timestamptz := clock_timestamp();
BEGIN
  IF v_caller IS NULL AND COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  IF p_scope = 'player' THEN
    IF v_caller IS NULL THEN
      RAISE EXCEPTION 'a player statement is the caller''s own; there is no other player to ask for' USING ERRCODE = '42501';
    END IF;
    v_entity := v_caller;              -- never a parameter: the statement is always your own
    v_type   := 'player_wallet';
    v_col    := 'club_members.chip_balance';
  ELSIF p_scope = 'club_treasury' THEN
    IF p_club_id IS NULL THEN
      RAISE EXCEPTION 'club_treasury needs p_club_id';
    END IF;
    IF public.ca_can_view_club_finances(p_club_id) IS NOT TRUE THEN
      RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
    END IF;
    v_entity := p_club_id;
    v_type   := 'club_treasury';
    v_col    := 'clubs.chip_treasury';
  ELSE
    RAISE EXCEPTION 'scope must be player or club_treasury';
  END IF;
  v_key := v_type || ':' || v_entity::text || ':' || v_col;

  -- The cursor covers every ordering field and is bound to this account/filter.
  -- Timestamp-only pagination skipped siblings created by one transaction.
  IF p_cursor IS NOT NULL THEN
    IF jsonb_typeof(p_cursor) IS DISTINCT FROM 'object'
       OR NOT (p_cursor ?& ARRAY['at','id','direction','account','club_filter'])
       OR jsonb_typeof(p_cursor->'at') IS DISTINCT FROM 'string'
       OR jsonb_typeof(p_cursor->'id') IS DISTINCT FROM 'string'
       OR p_cursor->>'direction' NOT IN ('in','out')
       OR p_cursor->>'direction' IS NULL
       OR p_cursor->>'account' IS DISTINCT FROM v_key
       OR p_cursor->>'club_filter' IS DISTINCT FROM p_club_id::text THEN
      RAISE EXCEPTION 'statement cursor does not match this account and filter'
        USING ERRCODE='22023';
    END IF;
    v_before := (p_cursor->>'at')::timestamptz;
    v_before_id := (p_cursor->>'id')::uuid;
    v_before_direction := p_cursor->>'direction';
    IF NOT isfinite(v_before) THEN
      RAISE EXCEPTION 'statement cursor timestamp must be finite' USING ERRCODE='22023';
    END IF;
  END IF;


  /* THE BALANCE NOW, through the same reader the nightly replay uses. */
  v_balance := public.fn_ca_account_balance(v_type, v_entity, NULL, v_col);

  IF p_scope = 'player' THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'club_id', m.club_id, 'club_name', c.name, 'balance', round(COALESCE(m.chip_balance, 0), 2))
             ORDER BY c.name), '[]'::jsonb)
      INTO v_clubs
      FROM public.club_members m
      JOIN public.clubs c ON c.id = m.club_id
     WHERE m.user_id = v_entity;
  END IF;

  /* THE PAGE. Both sides, newest first, from this account's point of view. */
  WITH mine AS (
    /* One index range per side - (to_entity_id, created_at DESC) and
       (from_entity_id, created_at DESC) both exist - each already limited,
       then merged. An OR across the two sides would be a bitmap of every leg
       the account ever had, which for a horse is tens of thousands. */
    (SELECT l.id, l.created_at, l.amount, l.category, l.description, l.club_id,
            l.table_id, l.tournament_id, l.hand_id, l.settlement_id,
            'in'::text AS direction, l.from_type AS counterparty_type,
            l.from_label AS counterparty_label, l.from_entity_id AS counterparty_id
       FROM public.chip_ledger l
      WHERE l.to_entity_id = v_entity AND l.to_type = v_type
        AND (p_club_id IS NULL OR l.club_id = p_club_id)
        AND (v_before IS NULL OR l.created_at < v_before
          OR (l.created_at = v_before AND l.id < v_before_id)
          OR (l.created_at = v_before AND l.id = v_before_id
              AND 'in' > v_before_direction))
      ORDER BY l.created_at DESC, l.id DESC
      LIMIT v_limit + 1)
    UNION ALL
    (SELECT l.id, l.created_at, l.amount, l.category, l.description, l.club_id,
            l.table_id, l.tournament_id, l.hand_id, l.settlement_id,
            'out'::text, l.to_type, l.to_label, l.to_entity_id
       FROM public.chip_ledger l
      WHERE l.from_entity_id = v_entity AND l.from_type = v_type
        AND (p_club_id IS NULL OR l.club_id = p_club_id)
        AND (v_before IS NULL OR l.created_at < v_before
          OR (l.created_at = v_before AND l.id < v_before_id)
          OR (l.created_at = v_before AND l.id = v_before_id
              AND 'out' > v_before_direction))
      ORDER BY l.created_at DESC, l.id DESC
      LIMIT v_limit + 1)
  ), page AS (
    SELECT * FROM mine ORDER BY created_at DESC, id DESC, direction ASC LIMIT v_limit
  )
  SELECT COALESCE((SELECT jsonb_agg(jsonb_build_object(
             'id', p.id, 'at', p.created_at, 'direction', p.direction, 'amount', round(p.amount, 2),
             'category', CASE WHEN p.category = 'horse_funding' THEN 'table_funding' ELSE p.category END,
             'description', CASE WHEN p.category = 'horse_funding' OR p.description ~* 'horse' THEN NULL
                                 ELSE p.description END,
             'counterparty_type', p.counterparty_type, 'counterparty_label', p.counterparty_label,
             'counterparty_id', p.counterparty_id,
             'club_id', p.club_id, 'table_id', p.table_id, 'tournament_id', p.tournament_id,
             'hand_id', p.hand_id, 'settlement_id', p.settlement_id)
             ORDER BY p.created_at DESC, p.id DESC, p.direction ASC) FROM page p), '[]'::jsonb),
         (SELECT count(*) FROM mine) > v_limit,   -- more than a page on either side, or both together
         (SELECT min(p.created_at) FROM page p),
         (SELECT jsonb_build_object('at',p.created_at,'id',p.id,'direction',p.direction,
                   'account',v_key,'club_filter',p_club_id)
            FROM page p ORDER BY p.created_at ASC,p.id ASC,p.direction DESC LIMIT 1)
    INTO v_legs, v_has_more, v_next, v_next_cursor;

  /* THE AUDIT. The last nightly reading of this account, and the journal
     since it. Balance-at-reading plus net-since equals balance-now, or it
     does not, and either way the player sees the same three numbers the
     platform's own control sees. */
  SELECT s.balance, s.taken_at, s.cum_unexplained, s.is_baseline
    INTO v_snap_bal, v_snap_at, v_snap_cum, v_snap_base
    FROM public.ca_account_snapshots s
   WHERE s.account_key = v_key
   ORDER BY s.taken_at DESC
   LIMIT 1;

  IF v_snap_at IS NULL THEN
    v_audit := jsonb_build_object(
      'status', 'no_reading_yet',
      'detail', 'this account has not yet been read by the nightly ledger replay (fn_ca_ledger_replay reads every account that moved in the last 26 hours, at 06:40 UTC). The legs above are complete; there is no reading to compare the balance against yet.',
      'balance_now', round(COALESCE(v_balance, 0), 2));
  ELSE
    SELECT COALESCE(sum(l.amount) FILTER (WHERE l.to_entity_id = v_entity AND l.to_type = v_type), 0),
           COALESCE(sum(l.amount) FILTER (WHERE l.from_entity_id = v_entity AND l.from_type = v_type), 0),
           count(*)
      INTO v_in, v_out, v_since_legs
      FROM public.chip_ledger l
     WHERE ((l.to_entity_id = v_entity AND l.to_type = v_type) OR (l.from_entity_id = v_entity AND l.from_type = v_type))
       AND l.created_at > v_snap_at;
    v_expected := round(v_snap_bal + v_in - v_out, 2);
    v_audit := jsonb_build_object(
      'status', CASE WHEN v_balance IS NULL THEN 'no_balance'
                     WHEN abs(round(v_balance, 2) - v_expected) < 0.005 THEN 'reconciles'
                     ELSE 'does_not_reconcile' END,
      'read_at', v_snap_at,
      'balance_at_reading', round(v_snap_bal, 2),
      'reading_is_baseline', COALESCE(v_snap_base, false),
      'cumulative_unexplained_at_reading', round(COALESCE(v_snap_cum, 0), 2),
      'in_since', round(v_in, 2),
      'out_since', round(v_out, 2),
      'legs_since', v_since_legs,
      'expected_now', v_expected,
      'balance_now', round(COALESCE(v_balance, 0), 2),
      'unexplained', CASE WHEN v_balance IS NULL THEN NULL ELSE round(round(v_balance, 2) - v_expected, 2) END,
      'detail', 'balance_at_reading + in_since - out_since = expected_now. The nightly replay (fn_ca_ledger_replay) makes this same comparison for every account and files an incident when it fails; a difference here that persists past the next 06:40 UTC reading is one the platform has also seen.');
  END IF;

  RETURN jsonb_build_object(
    'scope', p_scope,
    'entity_id', v_entity,
    'account', v_key,
    'club_filter', p_club_id,
    'balance_now', round(COALESCE(v_balance, 0), 2),
    'balance_exists', v_balance IS NOT NULL,
    'clubs', v_clubs,
    'legs', v_legs,
    'has_more', v_has_more,
    'next_before', v_next,
    'next_cursor', CASE WHEN v_has_more THEN v_next_cursor ELSE NULL END,
    'audit', v_audit,
    'generated_at', now(),
    'ms', round(extract(epoch from (clock_timestamp() - v_t0)) * 1000));
END $$;


ALTER FUNCTION public.fn_ca_chip_statement_page(p_scope text, p_club_id uuid, p_cursor jsonb, p_limit integer) OWNER TO postgres;

--
-- TOC entry 8723 (class 1255 OID 27837352)
-- Name: fn_ca_chip_store_coverage_gaps(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_chip_store_coverage_gaps() RETURNS TABLE(store text, gap text, detail text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_allowed text[];
BEGIN
  /* The enumerated stores, read from the journal's own constraint, so the
     coverage list is checked against the real domain and not a copy of it. */
  SELECT array_agg(DISTINCT m[1]) INTO v_allowed
    FROM pg_constraint c,
         LATERAL regexp_matches(pg_get_constraintdef(c.oid), '''([a-z_]+)''::text', 'g') m
   WHERE c.conrelid = 'public.chip_ledger'::regclass
     AND c.conname IN ('chip_ledger_from_type_check','chip_ledger_to_type_check');

  RETURN QUERY
  SELECT a.s, 'undeclared'::text,
         ('the chip journal accepts ' || a.s || ' but ca_chip_store_coverage does not say whether the supply basis counts it')::text
    FROM unnest(v_allowed) a(s)
   WHERE NOT EXISTS (SELECT 1 FROM public.ca_chip_store_coverage g WHERE g.store = a.s);

  RETURN QUERY
  WITH recent_store_pairs AS MATERIALIZED (
    SELECT l.from_type, l.to_type, sum(l.amount) AS amount
      FROM public.chip_ledger l
     WHERE l.created_at > now() - interval '24 hours'
       -- Keep the original NULL-sensitive exclusion exactly.
       AND NOT (l.category = 'correction'
                AND l.metadata ->> 'posted_via' = 'fn_ca_post_correction')
     GROUP BY l.from_type, l.to_type
  )
  SELECT g.store, 'uncounted store moved'::text,
         ('the supply basis does not count ' || g.store || ' and it moved '
          || round(x.net, 2)::text || ' in the last 24h, so that movement reads as drift')::text
    FROM public.ca_chip_store_coverage g
    JOIN LATERAL (
      SELECT COALESCE(sum(l.amount) FILTER (WHERE l.to_type = g.store), 0)
           - COALESCE(sum(l.amount) FILTER (WHERE l.from_type = g.store), 0) AS net
        FROM recent_store_pairs l
    ) x ON true
   WHERE g.treatment = 'uncounted' AND x.net <> 0;
END;
$$;


ALTER FUNCTION public.fn_ca_chip_store_coverage_gaps() OWNER TO postgres;

--
-- TOC entry 7016 (class 1255 OID 27837353)
-- Name: fn_ca_chip_store_declared(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_chip_store_declared() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_missing text;
BEGIN
  SELECT s INTO v_missing FROM (VALUES (NEW.from_type), (NEW.to_type)) v(s)
   WHERE s IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.ca_chip_store_coverage g WHERE g.store = s)
   LIMIT 1;

  IF v_missing IS NOT NULL THEN
    RAISE EXCEPTION 'REFUSED: chip store % is not declared in ca_chip_store_coverage', v_missing
      USING ERRCODE = '23514',
            DETAIL  = 'A store the supply basis has never heard of would move chips out of the meter '
                   || 'silently, which is exactly the five supply incidents of 2026-09-11.',
            HINT    = 'Declare it first: INSERT INTO public.ca_chip_store_coverage (store, treatment, counted_by, notes) '
                   || 'VALUES (' || quote_literal(v_missing) || ', ''counted''|''noncirculating''|''uncounted'', '
                   || '<which fn_ca_supply_snapshot component holds it>, <why>). '
                   || 'If it is counted, add it to the basis in the same migration.';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_ca_chip_store_declared() OWNER TO postgres;

--
-- TOC entry 4210 (class 1255 OID 184269443)
-- Name: fn_ca_chip_wallet_day_seal(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_chip_wallet_day_seal(p_max_days integer DEFAULT 4) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_today date := (statement_timestamp() AT TIME ZONE 'UTC')::date;
  v_first date;
  v_day date;
  v_start timestamptz;
  v_end timestamptz;
  v_sha text;
  v_manifest_rows bigint;
  v_rows bigint;
  v_sealed date[] := '{}';
  v_withdrawn date[] := '{}';
  v_checked integer := 0;
  v_waiting text;
  r record;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('fn_ca_chip_wallet_day_seal')) THEN
    RETURN jsonb_build_object('ran', false, 'reason', 'another seal is running');
  END IF;

  -- 1. A seal whose day's manifest changed (restated after maintenance, or
  --    attested after a zero-row seal) no longer describes the journal.
  FOR r IN
    SELECT s.day FROM public.ca_chip_wallet_day_seals s
    LEFT JOIN public.ca_ledger_day_manifests m ON m.day = s.day
    WHERE s.manifest_sha256 IS DISTINCT FROM m.sha256
  LOOP
    DELETE FROM public.ca_chip_wallet_day_seals WHERE day = r.day;
    v_withdrawn := v_withdrawn || r.day;
  END LOOP;

  -- 2. Re-count each sealed day about once a day. A row that reached a sealed
  --    day afterwards changes its count, and the seal is withdrawn.
  FOR r IN
    SELECT s.day, s.ledger_rows FROM public.ca_chip_wallet_day_seals s
    WHERE s.checked_at < now() - interval '20 hours'
    ORDER BY s.checked_at, s.day
    LIMIT 12
  LOOP
    SELECT count(*) INTO v_rows FROM public.chip_ledger
     WHERE created_at >= (r.day::timestamp AT TIME ZONE 'UTC')
       AND created_at < ((r.day + 1)::timestamp AT TIME ZONE 'UTC');
    v_checked := v_checked + 1;
    IF v_rows <> r.ledger_rows THEN
      DELETE FROM public.ca_chip_wallet_day_seals WHERE day = r.day;
      v_withdrawn := v_withdrawn || r.day;
    ELSE
      UPDATE public.ca_chip_wallet_day_seals SET checked_at = now() WHERE day = r.day;
    END IF;
  END LOOP;

  -- 3. Seal finished days, oldest first, from the first day any baseline
  --    reads from the totals (the day after the earliest cutoff).
  SELECT min((taken_at AT TIME ZONE 'UTC')::date) + 1 INTO v_first
    FROM public.ca_chip_baseline WHERE taken_at IS NOT NULL;

  IF v_first IS NOT NULL THEN
    FOR v_day IN
      SELECT g.d::date FROM generate_series(v_first::timestamp, (v_today - 1)::timestamp, interval '1 day') g(d)
      WHERE NOT EXISTS (SELECT 1 FROM public.ca_chip_wallet_day_seals s WHERE s.day = g.d::date)
      ORDER BY 1
      LIMIT greatest(coalesce(p_max_days, 0), 0)
    LOOP
      v_start := v_day::timestamp AT TIME ZONE 'UTC';
      v_end := (v_day + 1)::timestamp AT TIME ZONE 'UTC';

      -- A client transaction that began before the day ended could still
      -- insert a row dated inside it. Wait for it rather than seal around it.
      IF EXISTS (SELECT 1 FROM pg_stat_activity a
                  WHERE a.pid <> pg_backend_pid() AND a.backend_type = 'client backend'
                    AND (a.state IS NULL OR a.xact_start < v_end))
         OR EXISTS (SELECT 1 FROM pg_prepared_xacts) THEN
        v_waiting := format('%s: a transaction that began before it ended is still open', v_day);
        EXIT;
      END IF;

      SELECT m.sha256, m.row_count INTO v_sha, v_manifest_rows
        FROM public.ca_ledger_day_manifests m WHERE m.day = v_day;
      SELECT count(*) INTO v_rows FROM public.chip_ledger
       WHERE created_at >= v_start AND created_at < v_end;

      IF v_sha IS NULL AND v_rows > 0 THEN
        v_waiting := format('%s: its ledger manifest has not been attested yet', v_day);
        EXIT;
      END IF;
      IF v_sha IS NOT NULL AND v_rows <> v_manifest_rows THEN
        v_waiting := format('%s: the journal holds %s rows and its manifest attests %s', v_day, v_rows, v_manifest_rows);
        EXIT;
      END IF;

      INSERT INTO public.ca_chip_wallet_day_seals (day, manifest_sha256, ledger_rows)
      VALUES (v_day, v_sha, v_rows);

      -- The same legs the report reads (club set, either side a player
      -- wallet, every status), grouped by side in one pass over the day.
      INSERT INTO public.ca_chip_wallet_day_totals (club_id, day, user_id, net)
      SELECT y.club_id, v_day, y.uid, sum(y.amt)
      FROM (
        SELECT x.club_id, coalesce(x.credit_user, x.debit_user) AS uid,
          CASE WHEN GROUPING(x.credit_user)=0 THEN sum(x.a) ELSE -sum(x.a) END AS amt
        FROM (
          SELECT l.club_id,
            CASE WHEN l.to_type='player_wallet' THEN l.to_entity_id END AS credit_user,
            CASE WHEN l.from_type='player_wallet' THEN l.from_entity_id END AS debit_user,
            l.amount AS a
          FROM public.chip_ledger l
          WHERE l.created_at >= v_start AND l.created_at < v_end
            AND l.club_id IS NOT NULL
            AND (l.to_type='player_wallet' OR l.from_type='player_wallet')
        ) x
        GROUP BY GROUPING SETS ((x.club_id, x.credit_user), (x.club_id, x.debit_user))
      ) y
      WHERE y.uid IS NOT NULL
      GROUP BY y.club_id, y.uid;

      v_sealed := v_sealed || v_day;
    END LOOP;
  END IF;

  RETURN jsonb_build_object('ran', true, 'sealed', to_jsonb(v_sealed),
    'withdrawn', to_jsonb(v_withdrawn), 'rechecked', v_checked, 'waiting', v_waiting);
END;
$$;


ALTER FUNCTION public.fn_ca_chip_wallet_day_seal(p_max_days integer) OWNER TO postgres;

--
-- TOC entry 8908 (class 1255 OID 25678448)
-- Name: fn_ca_choose_tournament_seat_locked(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_choose_tournament_seat_locked(p_tournament_id uuid, p_user_id uuid, p_preferred_table_id uuid DEFAULT NULL::uuid, p_preferred_seat_number integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_capacity jsonb;
  v_table_id uuid;
  v_tournament_cap integer;
  v_cap integer;
  v_seat_number integer;
  v_seat_id uuid;
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'tournament and player are required for seat selection'
      USING ERRCODE='22023';
  END IF;

  v_capacity:=public.fn_ensure_late_registration_capacity(
    p_tournament_id,0);
  IF COALESCE((v_capacity->>'ok')::boolean,false) IS NOT TRUE THEN
    RAISE EXCEPTION 'tournament capacity could not be established: %',
      COALESCE(v_capacity->>'reason','unknown') USING ERRCODE='55000';
  END IF;
  v_tournament_cap:=public.fn_ca_tournament_seat_cap(p_tournament_id);

  SELECT tb.id,
         LEAST(v_tournament_cap,
               GREATEST(2,COALESCE(NULLIF(tb.max_players,0),v_tournament_cap)))
    INTO v_table_id,v_cap
    FROM public.tables tb
   WHERE tb.tournament_id=p_tournament_id
     AND lower(COALESCE(tb.status,'')) IN ('running','waiting','active')
     AND NOT COALESCE(tb.is_deleted,false)
     AND EXISTS (
       SELECT 1
         FROM generate_series(
           1,LEAST(v_tournament_cap,
             GREATEST(2,COALESCE(NULLIF(tb.max_players,0),v_tournament_cap))))
           AS legal(seat_number)
        WHERE NOT EXISTS (
          SELECT 1 FROM public.table_seats occupied
           WHERE occupied.table_id=tb.id
             AND occupied.seat_number=legal.seat_number
             AND occupied.left_at IS NULL))
   ORDER BY (
       SELECT count(*)
         FROM generate_series(
           1,LEAST(v_tournament_cap,
             GREATEST(2,COALESCE(NULLIF(tb.max_players,0),v_tournament_cap))))
           AS legal(seat_number)
        WHERE NOT EXISTS (
          SELECT 1 FROM public.table_seats occupied
           WHERE occupied.table_id=tb.id
             AND occupied.seat_number=legal.seat_number
             AND occupied.left_at IS NULL)) DESC,
     (tb.id=p_preferred_table_id) DESC,
     tb.created_at,tb.id
   LIMIT 1
   FOR UPDATE OF tb;
  IF v_table_id IS NULL THEN
    RAISE EXCEPTION
      'TOURNAMENT_SEAT_CAPACITY_UNAVAILABLE: no legal chair exists for tournament %',
      p_tournament_id USING ERRCODE='55000';
  END IF;

  IF v_table_id=p_preferred_table_id
     AND p_preferred_seat_number BETWEEN 1 AND v_cap
     AND NOT EXISTS (
       SELECT 1 FROM public.table_seats occupied
        WHERE occupied.table_id=v_table_id
          AND occupied.seat_number=p_preferred_seat_number
          AND occupied.left_at IS NULL) THEN
    v_seat_number:=p_preferred_seat_number;
  ELSE
    SELECT legal.seat_number INTO v_seat_number
      FROM generate_series(1,v_cap) AS legal(seat_number)
     WHERE NOT EXISTS (
       SELECT 1 FROM public.table_seats occupied
        WHERE occupied.table_id=v_table_id
          AND occupied.seat_number=legal.seat_number
          AND occupied.left_at IS NULL)
     ORDER BY legal.seat_number
     LIMIT 1;
  END IF;
  IF v_seat_number IS NULL THEN
    RAISE EXCEPTION 'chosen tournament table lost its legal chair'
      USING ERRCODE='55000';
  END IF;

  SELECT s.id INTO v_seat_id
    FROM public.table_seats s
   WHERE s.table_id=v_table_id AND s.seat_number=v_seat_number
   FOR UPDATE;

  RETURN jsonb_build_object(
    'ok',true,'tournament_id',p_tournament_id,'user_id',p_user_id,
    'table_id',v_table_id,'seat_number',v_seat_number,
    'physical_seat_id',v_seat_id,'capacity',v_capacity);
END;
$$;


ALTER FUNCTION public.fn_ca_choose_tournament_seat_locked(p_tournament_id uuid, p_user_id uuid, p_preferred_table_id uuid, p_preferred_seat_number integer) OWNER TO postgres;

--
-- TOC entry 6649 (class 1255 OID 19005883)
-- Name: fn_ca_circulation_total(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_circulation_total() RETURNS TABLE(member_wallets numeric, on_the_felt numeric, total numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    COALESCE((SELECT sum(cm.chip_balance) FROM public.club_members cm
               /* DIAMOND PHASE 9: a Diamond membership is not a chip wallet.
                  Only a KNOWN diamonds club is excluded, so a membership whose
                  club row is missing stays counted exactly as before. */
               WHERE NOT EXISTS (SELECT 1 FROM public.clubs dc
                                  WHERE dc.id = cm.club_id AND dc.asset = 'diamonds')), 0)::numeric,
    COALESCE((SELECT sum(stack) FROM public.table_seats WHERE left_at IS NULL
               /* DIAMOND PHASE 9: a Diamond seat holds Diamonds. Counted in this
                  total it is added to chips and the hourly freeze mark's
                  conservation verdict compares the sum against a chip tolerance.
                  The Diamond is not lost: its custody row is inside
                  fn_ca_arena_diamonds(), which the Diamond identity closes on. */
               AND NOT EXISTS (SELECT 1 FROM public.tables dt
                                JOIN public.clubs dc ON dc.id = dt.club_id
                               WHERE dt.id = table_seats.table_id AND dc.asset = 'diamonds')), 0)::numeric,
    COALESCE((SELECT sum(cm.chip_balance) FROM public.club_members cm
               /* DIAMOND PHASE 9: a Diamond membership is not a chip wallet.
                  Only a KNOWN diamonds club is excluded, so a membership whose
                  club row is missing stays counted exactly as before. */
               WHERE NOT EXISTS (SELECT 1 FROM public.clubs dc
                                  WHERE dc.id = cm.club_id AND dc.asset = 'diamonds')), 0)::numeric
      + COALESCE((SELECT sum(stack) FROM public.table_seats WHERE left_at IS NULL
               /* DIAMOND PHASE 9: a Diamond seat holds Diamonds. Counted in this
                  total it is added to chips and the hourly freeze mark's
                  conservation verdict compares the sum against a chip tolerance.
                  The Diamond is not lost: its custody row is inside
                  fn_ca_arena_diamonds(), which the Diamond identity closes on. */
               AND NOT EXISTS (SELECT 1 FROM public.tables dt
                                JOIN public.clubs dc ON dc.id = dt.club_id
                               WHERE dt.id = table_seats.table_id AND dc.asset = 'diamonds')), 0)::numeric;
$$;


