COMMENT ON FUNCTION public.fn_ca_closing_position_summary(p_capture_ref uuid) IS 'Reads a captured closing position back, per class and in total. What the restore migration of the epoch reset contract step 3 is written from, and what the capture is compared against fn_ca_supply_snapshot() with before anybody trusts it.';


--
-- TOC entry 8635 (class 1255 OID 22297494)
-- Name: fn_ca_club_actor_role(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_actor_role(p_club_id uuid, p_user_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT m.role FROM public.club_members m
      WHERE m.club_id = p_club_id AND m.user_id = p_user_id
        AND m.role IN ('owner', 'co_owner', 'admin', 'super_agent', 'agent', 'sub_agent')
      ORDER BY CASE m.role
        WHEN 'owner' THEN 0 WHEN 'co_owner' THEN 1 WHEN 'admin' THEN 2
        WHEN 'super_agent' THEN 3 WHEN 'agent' THEN 4 ELSE 5 END
      LIMIT 1),
    (SELECT 'owner' FROM public.clubs c WHERE c.id = p_club_id AND c.owner_id = p_user_id),
    'player'
  );
$$;


ALTER FUNCTION public.fn_ca_club_actor_role(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 5061 (class 1255 OID 166027218)
-- Name: fn_ca_club_cash_felt(uuid, date, date, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_cash_felt(p_club_id uuid, p_start date, p_end date, p_game text DEFAULT 'ALL'::text, p_stakes text DEFAULT 'ALL'::text, p_search text DEFAULT NULL::text) RETURNS TABLE(table_id uuid, felt numeric, seated integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH f AS (
    SELECT UPPER(COALESCE(NULLIF(p_game,''),'ALL')) g,
           UPPER(COALESCE(NULLIF(p_stakes,''),'ALL')) s,
           NULLIF(btrim(COALESCE(p_search,'')),'') q
  )
  SELECT s.table_id, SUM(s.stack), COUNT(*)::int
    FROM public.table_seats s
    JOIN public.tables t ON t.id = s.table_id AND t.tournament_id IS NULL
    LEFT JOIN public.profiles pr ON pr.id = t.created_by
    CROSS JOIN f
   WHERE s.left_at IS NULL
     AND s.user_id IS NOT NULL
     AND COALESCE(s.status, 'active') <> 'left'
     AND COALESCE(s.stack, 0) > 0
     AND (s.joined_at AT TIME ZONE 'America/Chicago')::date BETWEEN p_start AND p_end
     AND COALESCE(s.club_id, public.fn_ca_cash_reporting_club(t.union_id, t.club_id, s.user_id)) = ANY (public.fn_ca_club_data_clubs(p_club_id))
     AND public.fn_ca_launch_accounting_accepts(COALESCE(s.club_id, public.fn_ca_cash_reporting_club(t.union_id, t.club_id, s.user_id)), s.joined_at) IS TRUE
     AND (f.g = 'ALL' OR f.g = CASE
           WHEN COALESCE(t.game_variant,'') ILIKE '%plo%' OR COALESCE(t.game_variant,'') ILIKE '%omaha%' THEN 'OMAHA'
           WHEN COALESCE(t.game_variant,'') ILIKE '%mixed%' OR COALESCE(t.game_mode,'') ILIKE '%mixed%' THEN 'MIXED'
           ELSE 'HOLDEM' END)
     AND (f.s = 'ALL' OR f.s = CASE
           WHEN COALESCE(t.big_blind,0) < 1 THEN 'MICRO'
           WHEN COALESCE(t.big_blind,0) < 5 THEN 'SMALL'
           WHEN COALESCE(t.big_blind,0) < 25 THEN 'MID' ELSE 'HIGH' END)
     AND (f.q IS NULL OR COALESCE(t.name,'Unnamed') ILIKE '%'||f.q||'%'
          OR t.id::text ILIKE '%'||f.q||'%' OR COALESCE(pr.username,'') ILIKE '%'||f.q||'%')
   GROUP BY s.table_id;
$$;


ALTER FUNCTION public.fn_ca_club_cash_felt(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text) OWNER TO postgres;

