CREATE FUNCTION public.fn_ca_club_data_fact_live_from() RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT s.live_from FROM public.ca_club_data_fact_state s WHERE s.id;
$$;


ALTER FUNCTION public.fn_ca_club_data_fact_live_from() OWNER TO postgres;

--
-- TOC entry 7503 (class 1255 OID 183809234)
-- Name: fn_ca_club_data_fact_put(uuid, date, text, uuid, uuid, numeric, numeric, numeric, numeric, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_data_fact_put(p_club uuid, p_day date, p_kind text, p_game uuid, p_user uuid, p_fee numeric, p_buyins numeric, p_cashouts numeric, p_winnings numeric, p_at timestamp with time zone) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  INSERT INTO public.ca_club_data_fact AS f
    (club_id, stat_date, kind, game_id, user_id, fee, buyins, cashouts, winnings, last_at)
  VALUES (p_club, p_day, p_kind, p_game,
          COALESCE(p_user, '00000000-0000-0000-0000-000000000000'::uuid),
          COALESCE(p_fee, 0), COALESCE(p_buyins, 0), COALESCE(p_cashouts, 0),
          COALESCE(p_winnings, 0), COALESCE(p_at, now()))
  ON CONFLICT (club_id, stat_date, game_id, user_id) DO UPDATE
     SET fee = f.fee + EXCLUDED.fee,
         buyins = f.buyins + EXCLUDED.buyins,
         cashouts = f.cashouts + EXCLUDED.cashouts,
         winnings = f.winnings + EXCLUDED.winnings,
         last_at = GREATEST(f.last_at, EXCLUDED.last_at);
  -- 20261022103651: the same event, keyed by its America/Chicago day, from the
  -- Chicago cutover on (the one-time load owns everything before it).
  INSERT INTO public.ca_club_data_fact_ct AS c
    (club_id, stat_date, kind, game_id, user_id, fee, buyins, cashouts, winnings, last_at)
  SELECT p_club, public.fn_ca_chicago_day(COALESCE(p_at, now())), p_kind, p_game,
         COALESCE(p_user, '00000000-0000-0000-0000-000000000000'::uuid),
         COALESCE(p_fee, 0), COALESCE(p_buyins, 0), COALESCE(p_cashouts, 0),
         COALESCE(p_winnings, 0), COALESCE(p_at, now())
   WHERE COALESCE(p_at, now()) >= public.fn_ca_club_data_ct_live_from()
  ON CONFLICT (club_id, stat_date, game_id, user_id, src) DO UPDATE
     SET fee = c.fee + EXCLUDED.fee,
         buyins = c.buyins + EXCLUDED.buyins,
         cashouts = c.cashouts + EXCLUDED.cashouts,
         winnings = c.winnings + EXCLUDED.winnings,
         last_at = GREATEST(c.last_at, EXCLUDED.last_at);
  INSERT INTO public.ca_club_data_game_ct AS g
    (club_id, stat_date, kind, game_id, fee, buyins, cashouts, winnings, last_at)
  SELECT p_club, public.fn_ca_chicago_day(COALESCE(p_at, now())), p_kind, p_game,
         COALESCE(p_fee, 0), COALESCE(p_buyins, 0), COALESCE(p_cashouts, 0),
         COALESCE(p_winnings, 0), COALESCE(p_at, now())
   WHERE COALESCE(p_at, now()) >= public.fn_ca_club_data_ct_live_from()
  ON CONFLICT (club_id, stat_date, game_id, src) DO UPDATE
     SET fee = g.fee + EXCLUDED.fee,
         buyins = g.buyins + EXCLUDED.buyins,
         cashouts = g.cashouts + EXCLUDED.cashouts,
         winnings = g.winnings + EXCLUDED.winnings,
         last_at = GREATEST(g.last_at, EXCLUDED.last_at);
$$;


ALTER FUNCTION public.fn_ca_club_data_fact_put(p_club uuid, p_day date, p_kind text, p_game uuid, p_user uuid, p_fee numeric, p_buyins numeric, p_cashouts numeric, p_winnings numeric, p_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 6778 (class 1255 OID 183809238)
-- Name: fn_ca_club_data_fact_seed(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_data_fact_seed(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_live timestamptz := public.fn_ca_club_data_fact_live_from();
  v_to timestamptz := LEAST(p_to, v_live);
  v_rows bigint := 0;
BEGIN
  IF p_from IS NULL OR p_to IS NULL OR v_to <= p_from THEN
    RAISE EXCEPTION 'seed needs a window that ends after it starts and before live_from (%)', v_live;
  END IF;
  IF now() < v_live + interval '1 minute' THEN
    RAISE EXCEPTION 'seed waits until a minute after live_from (%), so every row before it has committed', v_live;
  END IF;
  IF v_to - p_from > interval '1 day' THEN
    RAISE EXCEPTION 'seed one day or less at a time';
  END IF;
  IF EXISTS (SELECT 1 FROM public.ca_club_data_fact_seed_log l
              WHERE l.from_at < v_to AND l.to_at > p_from) THEN
    RAISE EXCEPTION 'this window overlaps one already seeded';
  END IF;

  WITH cash_c AS (
    SELECT r.id, r.table_id, r.rake_amount, r.created_at, t.union_id, t.club_id AS table_club,
           e.key::uuid AS uid, (CASE WHEN e.value ~ '^[0-9]+(\.[0-9]+)?$' THEN e.value::numeric ELSE 0 END) AS contrib
      FROM public.rake_records r
      JOIN public.tables t ON t.id = r.table_id AND t.tournament_id IS NULL
      CROSS JOIN LATERAL jsonb_each_text(CASE WHEN jsonb_typeof(r.player_contributions) = 'object'
                                              THEN r.player_contributions ELSE '{}'::jsonb END) e
     WHERE r.created_at >= p_from AND r.created_at < v_to
       AND r.rake_amount > 0 AND r.tournament_id IS NULL AND NOT COALESCE(r.is_tournament, false)
       AND e.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       AND (CASE WHEN e.value ~ '^[0-9]+(\.[0-9]+)?$' THEN e.value::numeric ELSE 0 END) > 0
  ), cash_s AS (
    SELECT c.*, SUM(c.contrib) OVER (PARTITION BY c.id) AS tot FROM cash_c c
  ), cash_rake AS (
    SELECT COALESCE(ra.club_id, rc.club, st.club,
                    public.fn_ca_cash_reporting_club(s.union_id, s.table_club, s.uid)) AS club_id,
           (s.created_at AT TIME ZONE 'UTC')::date AS stat_date, 'CASH'::text AS kind,
           s.table_id AS game_id, s.uid AS user_id,
           s.rake_amount * s.contrib / s.tot AS fee, 0::numeric AS buyins, 0::numeric AS cashouts,
           0::numeric AS winnings, s.created_at AS at
      FROM cash_s s
      LEFT JOIN public.rake_attributions ra ON ra.rake_record_id = s.id AND ra.player_id = s.uid
      LEFT JOIN LATERAL (
        SELECT x.funding_club_id AS club FROM public.cash_participant_funding_receipts x
         WHERE ra.club_id IS NULL AND x.operation_kind = 'buyin' AND x.table_id = s.table_id
           AND x.account_entity_id = s.uid AND x.seat_joined_at <= s.created_at
         ORDER BY x.seat_joined_at DESC LIMIT 1) rc ON true
      LEFT JOIN LATERAL (
        SELECT ts.club_id AS club FROM public.table_seats ts
         WHERE ra.club_id IS NULL AND rc.club IS NULL AND ts.table_id = s.table_id
           AND ts.user_id = s.uid AND ts.club_id IS NOT NULL AND ts.joined_at <= s.created_at
         ORDER BY ts.joined_at DESC LIMIT 1) st ON true
  ), cash_unnamed AS (
    SELECT t.club_id, (r.created_at AT TIME ZONE 'UTC')::date, 'CASH'::text, r.table_id,
           '00000000-0000-0000-0000-000000000000'::uuid, r.rake_amount, 0::numeric, 0::numeric,
           0::numeric, r.created_at
      FROM public.rake_records r
      JOIN public.tables t ON t.id = r.table_id AND t.tournament_id IS NULL
     WHERE r.created_at >= p_from AND r.created_at < v_to
       AND r.rake_amount > 0 AND r.tournament_id IS NULL AND NOT COALESCE(r.is_tournament, false)
       AND NOT EXISTS (
         SELECT 1 FROM jsonb_each_text(CASE WHEN jsonb_typeof(r.player_contributions) = 'object'
                                            THEN r.player_contributions ELSE '{}'::jsonb END) e
          WHERE e.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
            AND (CASE WHEN e.value ~ '^[0-9]+(\.[0-9]+)?$' THEN e.value::numeric ELSE 0 END) > 0)
  ), tour_named AS (
    SELECT COALESCE(tp.club_id, public.fn_ca_cash_reporting_club(tr.union_id, tr.club_id, (r.metadata->>'user_id')::uuid)),
           (r.created_at AT TIME ZONE 'UTC')::date, 'TOURNAMENT'::text, r.tournament_id,
           (r.metadata->>'user_id')::uuid, r.rake_amount, 0::numeric, 0::numeric, 0::numeric, r.created_at
      FROM public.rake_records r
      LEFT JOIN public.tournaments tr ON tr.id = r.tournament_id
      LEFT JOIN public.tournament_players tp
        ON tp.tournament_id = r.tournament_id AND tp.user_id::text = r.metadata->>'user_id'
     WHERE r.created_at >= p_from AND r.created_at < v_to AND r.is_tournament
       AND r.tournament_id IS NOT NULL AND r.rake_amount <> 0
       AND (r.metadata->>'user_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
  ), tour_split AS (
    SELECT COALESCE(tp.club_id, public.fn_ca_cash_reporting_club(tr.union_id, tr.club_id, tp.user_id)),
           (r.created_at AT TIME ZONE 'UTC')::date, 'TOURNAMENT'::text, r.tournament_id,
           tp.user_id, r.rake_amount / n.n, 0::numeric, 0::numeric, 0::numeric, r.created_at
      FROM public.rake_records r
      LEFT JOIN public.tournaments tr ON tr.id = r.tournament_id
      JOIN LATERAL (SELECT count(*)::numeric AS n FROM public.tournament_players x
                     WHERE x.tournament_id = r.tournament_id) n ON n.n > 0
      JOIN public.tournament_players tp ON tp.tournament_id = r.tournament_id
     WHERE r.created_at >= p_from AND r.created_at < v_to AND r.is_tournament
       AND r.tournament_id IS NOT NULL AND r.rake_amount <> 0
       AND NOT ((r.metadata->>'user_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$')
         IS TRUE
  ), wal AS (
    SELECT w.id, w.user_id, w.amount, w.type, w.created_at, w.table_id, w.related_entity_id,
           CASE WHEN w.table_id IS NOT NULL THEN 'CASH' ELSE 'TOURNAMENT' END AS kind
      FROM public.wallet_transactions w
     WHERE w.created_at >= p_from AND w.created_at < v_to
       AND ((w.table_id IS NOT NULL AND w.category IN ('buyin', 'cashout', 'addon', 'rebuy', 'refund'))
         OR (w.table_id IS NULL AND w.related_entity_id IS NOT NULL
             AND w.category IN ('tournament_buyin', 'prize', 'bounty', 'addon', 'rebuy', 'refund', 'prize_reversal')))
  ), wal_cash AS (
    SELECT COALESCE(public.fn_ca_ledger_leg_club(w.user_id, w.amount, w.type, w.created_at, w.table_id),
                    rc.club,
                    public.fn_ca_cash_reporting_club(t.union_id, t.club_id, w.user_id)),
           (w.created_at AT TIME ZONE 'UTC')::date, 'CASH'::text, w.table_id, w.user_id, 0::numeric,
           CASE WHEN w.type = 'debit' THEN w.amount ELSE 0 END,
           CASE WHEN w.type = 'credit' THEN w.amount ELSE 0 END,
           CASE WHEN w.type = 'credit' THEN w.amount WHEN w.type = 'debit' THEN -w.amount ELSE 0 END,
           w.created_at
      FROM wal w
      JOIN public.tables t ON t.id = w.table_id AND t.tournament_id IS NULL
      LEFT JOIN LATERAL (
        SELECT x.funding_club_id AS club FROM public.cash_participant_funding_receipts x
         WHERE x.operation_kind = 'buyin' AND x.table_id = w.table_id AND x.account_entity_id = w.user_id
           AND x.seat_joined_at <= w.created_at
         ORDER BY x.seat_joined_at DESC LIMIT 1) rc ON true
     WHERE w.kind = 'CASH'
  ), wal_tour AS (
    SELECT COALESCE(tp.club_id,
                    public.fn_ca_ledger_leg_club(w.user_id, w.amount, w.type, w.created_at, NULL),
                    public.fn_ca_cash_reporting_club(tr.union_id, tr.club_id, w.user_id)),
           (w.created_at AT TIME ZONE 'UTC')::date, 'TOURNAMENT'::text, w.related_entity_id, w.user_id,
           0::numeric,
           CASE WHEN w.type = 'debit' THEN w.amount ELSE 0 END,
           CASE WHEN w.type = 'credit' THEN w.amount ELSE 0 END,
           CASE WHEN w.type = 'credit' THEN w.amount WHEN w.type = 'debit' THEN -w.amount ELSE 0 END,
           w.created_at
      FROM wal w
      JOIN public.tournaments tr ON tr.id = w.related_entity_id
      LEFT JOIN public.tournament_players tp
        ON tp.tournament_id = w.related_entity_id AND tp.user_id = w.user_id
     WHERE w.kind = 'TOURNAMENT'
  ), all_facts (club_id, stat_date, kind, game_id, user_id, fee, buyins, cashouts, winnings, at) AS (
    SELECT * FROM cash_rake
    UNION ALL SELECT * FROM cash_unnamed
    UNION ALL SELECT * FROM tour_named
    UNION ALL SELECT * FROM tour_split
    UNION ALL SELECT * FROM wal_cash
    UNION ALL SELECT * FROM wal_tour
  ), accepted AS (
    SELECT a.* FROM all_facts a
     WHERE a.club_id IS NOT NULL AND a.user_id IS NOT NULL
       AND public.fn_ca_launch_accounting_accepts(a.club_id, a.at) IS TRUE
  ), grouped AS (
    SELECT club_id, stat_date, min(kind) AS kind, game_id, user_id,
           SUM(fee) AS fee, SUM(buyins) AS buyins, SUM(cashouts) AS cashouts,
           SUM(winnings) AS winnings, max(at) AS last_at
      FROM accepted GROUP BY club_id, stat_date, game_id, user_id
  ), put AS (
    INSERT INTO public.ca_club_data_fact AS f
      (club_id, stat_date, kind, game_id, user_id, fee, buyins, cashouts, winnings, last_at)
    SELECT club_id, stat_date, kind, game_id, user_id, fee, buyins, cashouts, winnings, last_at FROM grouped
    ON CONFLICT (club_id, stat_date, game_id, user_id) DO UPDATE
       SET fee = f.fee + EXCLUDED.fee,
           buyins = f.buyins + EXCLUDED.buyins,
           cashouts = f.cashouts + EXCLUDED.cashouts,
           winnings = f.winnings + EXCLUDED.winnings,
           last_at = GREATEST(f.last_at, EXCLUDED.last_at)
    RETURNING 1
  )
  SELECT count(*) INTO v_rows FROM put;

  INSERT INTO public.ca_club_data_fact_seed_log (from_at, to_at, rows_put) VALUES (p_from, v_to, v_rows);
  RETURN jsonb_build_object('from', p_from, 'to', v_to, 'rows', v_rows, 'live_from', v_live);
END;
$_$;


ALTER FUNCTION public.fn_ca_club_data_fact_seed(p_from timestamp with time zone, p_to timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 4118 (class 1255 OID 184451964)
-- Name: fn_ca_club_data_facts_from(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_data_facts_from() RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT (min(l.from_at) AT TIME ZONE 'UTC')::date FROM public.ca_club_data_fact_seed_log l),
    (SELECT (s.live_from AT TIME ZONE 'UTC')::date FROM public.ca_club_data_fact_state s WHERE s.id));
$$;


ALTER FUNCTION public.fn_ca_club_data_facts_from() OWNER TO postgres;

--
-- TOC entry 8354 (class 1255 OID 216937500)
-- Name: fn_ca_club_data_hand_count(uuid, date, date, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_data_hand_count(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 WITH eligible AS (
  SELECT DISTINCT d.table_id FROM public.ca_club_data_hands_ct d
   JOIN public.tables t ON t.id=d.table_id LEFT JOIN public.profiles pr ON pr.id=t.created_by
  WHERE d.club_id=ANY(public.fn_ca_club_data_clubs(p_club_id)) AND d.stat_date BETWEEN p_start AND p_end
    AND (p_game='ALL' OR p_game=CASE WHEN coalesce(t.game_variant,'') ILIKE '%plo%' OR coalesce(t.game_variant,'') ILIKE '%omaha%' THEN 'OMAHA' WHEN coalesce(t.game_variant,'') ILIKE '%mixed%' OR coalesce(t.game_mode,'') ILIKE '%mixed%' THEN 'MIXED' ELSE 'HOLDEM' END)
    AND (p_stakes='ALL' OR p_stakes=CASE WHEN coalesce(t.big_blind,0)<1 THEN 'MICRO' WHEN coalesce(t.big_blind,0)<5 THEN 'SMALL' WHEN coalesce(t.big_blind,0)<25 THEN 'MID' ELSE 'HIGH' END)
    AND (p_search IS NULL OR t.name ILIKE '%'||p_search||'%' OR t.id::text ILIKE '%'||p_search||'%' OR pr.username ILIKE '%'||p_search||'%')
 )
 SELECT CASE WHEN EXISTS(SELECT 1 FROM public.unions WHERE id=p_club_id) THEN
  (SELECT count(*) FROM public.rake_records r JOIN eligible e ON e.table_id=r.table_id
    WHERE r.created_at>=p_start::timestamp AT TIME ZONE 'America/Chicago' AND r.created_at<(p_end+1)::timestamp AT TIME ZONE 'America/Chicago'
      AND r.tournament_id IS NULL AND r.is_tournament IS NOT TRUE AND r.rake_amount>0)
 ELSE (SELECT coalesce(sum(d.hands),0)::bigint FROM public.ca_club_data_hands_ct d JOIN eligible e ON e.table_id=d.table_id
   WHERE d.club_id=p_club_id AND d.stat_date BETWEEN p_start AND p_end) END;
$$;


ALTER FUNCTION public.fn_ca_club_data_hand_count(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text) OWNER TO postgres;

--
-- TOC entry 7267 (class 1255 OID 221733839)
-- Name: fn_ca_club_data_hand_put(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_data_hand_put(p_club uuid, p_table uuid, p_at timestamp with time zone) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  INSERT INTO public.ca_club_data_hands_ct AS h (club_id, stat_date, table_id, hands)
  SELECT p_club, public.fn_ca_chicago_day(p_at), p_table, 1
   WHERE p_club IS NOT NULL AND p_table IS NOT NULL AND p_at >= public.fn_ca_club_data_ct_live_from()
  ON CONFLICT (club_id, stat_date, table_id, src) DO UPDATE SET hands = h.hands + 1;
$$;


ALTER FUNCTION public.fn_ca_club_data_hand_put(p_club uuid, p_table uuid, p_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 7750 (class 1255 OID 183809245)
-- Name: fn_ca_club_data_scope(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_data_scope(p_club_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT CASE
 WHEN session_user IN ('postgres','supabase_admin') OR coalesce(auth.role(),'')='service_role' THEN 'club'
 WHEN auth.uid() IS NULL THEN NULL
 WHEN EXISTS(SELECT 1 FROM public.unions u WHERE u.id=p_club_id)
   THEN CASE WHEN public.ca_can_oversee_union(p_club_id) THEN 'club' ELSE NULL END
 WHEN EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=p_club_id AND c.owner_id=auth.uid())
   OR EXISTS(SELECT 1 FROM public.profiles pr WHERE pr.id=auth.uid() AND coalesce(pr.is_admin,false)) THEN 'club'
 WHEN EXISTS(SELECT 1 FROM public.club_members cm WHERE cm.club_id=p_club_id AND cm.user_id=auth.uid()
   AND coalesce(cm.status,'active') NOT IN ('banned','suspended') AND cm.role IN ('owner','co_owner','admin')
   AND public.fn_cashier_member_is_active(cm.club_id,cm.user_id)) THEN 'club'
 WHEN EXISTS(SELECT 1 FROM public.club_members cm WHERE cm.club_id=p_club_id AND cm.user_id=auth.uid()
   AND coalesce(cm.status,'active') NOT IN ('banned','suspended') AND cm.role IN ('super_agent','agent','sub_agent')
   AND public.fn_cashier_member_is_active(cm.club_id,cm.user_id)) THEN 'downline'
 ELSE NULL END;
$$;


ALTER FUNCTION public.fn_ca_club_data_scope(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 8269 (class 1255 OID 18059492)
-- Name: fn_ca_club_game_rows(uuid, date, date, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_game_rows(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_out jsonb;
BEGIN
  IF UPPER(COALESCE(NULLIF(p_game,''),'ALL')) <> 'ALL'
     OR UPPER(COALESCE(NULLIF(p_stakes,''),'ALL')) <> 'ALL'
     OR NULLIF(btrim(COALESCE(p_search,'')),'') IS NOT NULL THEN
    RETURN public.fn_ca_club_game_rows_filtered(
      p_club_id,p_start,p_end,p_game,p_stakes,p_search,p_limit
    );
  END IF;

  EXECUTE $query$
    WITH recent_cash_ids AS MATERIALIZED (
      SELECT tb.id
        FROM public.tables tb
       WHERE EXISTS (
         SELECT 1 FROM public.club_table_daily d
          WHERE d.club_id = ANY (public.fn_ca_club_data_clubs($1)) AND d.table_id=tb.id
            AND d.stat_date BETWEEN $2 AND $3
       )
       ORDER BY tb.created_at DESC NULLS LAST,tb.id DESC
       LIMIT $4
    ), cash AS MATERIALIZED (
      SELECT tb.id,COALESCE(tb.name,'Unnamed') name,
             UPPER(COALESCE(tb.game_variant,'nlh')) variant,
             CASE WHEN COALESCE(tb.game_variant,'') ILIKE '%plo%'
                        OR COALESCE(tb.game_variant,'') ILIKE '%omaha%' THEN 'OMAHA'
                  WHEN COALESCE(tb.game_variant,'') ILIKE '%mixed%'
                        OR COALESCE(tb.game_mode,'') ILIKE '%mixed%' THEN 'MIXED'
                  ELSE 'HOLDEM' END game_class,
             CASE WHEN COALESCE(tb.big_blind,0)<1 THEN 'MICRO'
                  WHEN COALESCE(tb.big_blind,0)<5 THEN 'SMALL'
                  WHEN COALESCE(tb.big_blind,0)<25 THEN 'MID' ELSE 'HIGH' END stakes_tier,
             COALESCE(tb.small_blind,0) small_blind,
             COALESCE(tb.big_blind,0) big_blind,
             CASE WHEN COALESCE(tb.rake_percent,-1)>=0 THEN tb.rake_percent END rake_percent,
             tb.created_at started_at,tb.created_by,tb.status,
             sum(d.rake) fee,round(sum(d.net),2) winnings,
             sum(d.hands)::bigint hands,max(d.players)::integer players
        FROM recent_cash_ids r
        JOIN public.tables tb ON tb.id=r.id
        JOIN public.club_table_daily d ON d.club_id = ANY (public.fn_ca_club_data_clubs($1)) AND d.table_id=r.id
          AND d.stat_date BETWEEN $2 AND $3
       GROUP BY tb.id,tb.name,tb.game_variant,tb.game_mode,tb.big_blind,
                tb.small_blind,tb.rake_percent,tb.created_at,tb.created_by,tb.status
    ), recent_tournament_ids AS MATERIALIZED (
      SELECT tr.id
        FROM public.tournaments tr
       WHERE EXISTS (
         SELECT 1 FROM public.ca_club_tournament_daily d
          WHERE d.club_id = ANY (public.fn_ca_club_data_clubs($1)) AND d.tournament_id=tr.id
            AND d.stat_date BETWEEN $2 AND $3
       )
       /* start_time is NOT NULL: DESC is DESC NULLS LAST, and only DESC can walk
          idx_tournaments_start_time backward and stop (2026-10-01) */
       ORDER BY tr.start_time DESC,tr.id DESC
       LIMIT $4
    ), tournament_facts AS MATERIALIZED (
      SELECT r.id,sum(d.fee) fee,round(sum(d.winnings),2) winnings
        FROM recent_tournament_ids r
        JOIN public.ca_club_tournament_daily d
          ON d.club_id = ANY (public.fn_ca_club_data_clubs($1)) AND d.tournament_id=r.id
         AND d.stat_date BETWEEN $2 AND $3
       GROUP BY r.id
    ), tournament_players AS MATERIALIZED (
      SELECT r.id,count(DISTINCT p.user_id)::integer players
        FROM recent_tournament_ids r
        LEFT JOIN public.ca_club_tournament_player_daily p
          ON p.club_id = ANY (public.fn_ca_club_data_clubs($1)) AND p.tournament_id=r.id
         AND p.stat_date BETWEEN $2 AND $3
       GROUP BY r.id
    ), all_rows AS (
      SELECT 'CASH'::text kind,c.id::text id,c.name,c.variant,c.game_class,
             c.stakes_tier,c.small_blind,c.big_blind,c.rake_percent,c.started_at,
             c.created_by,c.status,c.fee,c.winnings,c.hands,c.players,
             COALESCE(pr.username,'') creator_name,pr.avatar_url creator_avatar
        FROM cash c LEFT JOIN public.profiles pr ON pr.id=c.created_by
      UNION ALL
      SELECT CASE WHEN tr.tournament_type='SPIN' THEN 'SPIN'
                  WHEN tr.tournament_type='SNG' THEN 'SNG' WHEN tr.tournament_type='MTT' THEN 'MTT' ELSE coalesce(tr.tournament_type,'TOURNAMENT') END,
             tr.id::text,COALESCE(tr.name,'Tournament'),
             UPPER(COALESCE(tr.variant,tr.game_type,'nlh')),
             CASE WHEN tr.tournament_type='SPIN' THEN 'SPIN' WHEN tr.tournament_type='SNG' THEN 'SNG' WHEN tr.tournament_type='MTT' THEN 'MTT' ELSE coalesce(tr.tournament_type,'TOURNAMENT') END,
             'NA',0::numeric,0::numeric,NULL::numeric,tr.start_time,NULL::uuid,
             tr.status,f.fee,f.winnings,0::bigint,COALESCE(tp.players,0),
             ''::text,NULL::text
        FROM tournament_facts f
        JOIN public.tournaments tr ON tr.id=f.id
        LEFT JOIN tournament_players tp ON tp.id=f.id
    ), bounded AS MATERIALIZED (
      SELECT * FROM all_rows r
       ORDER BY r.started_at DESC NULLS LAST,r.kind DESC,r.id DESC
       LIMIT $4
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'kind',q.kind,'id',q.id,'name',q.name,'variant',q.variant,
      'game_class',q.game_class,'stakes_tier',q.stakes_tier,
      'blinds',CASE WHEN q.big_blind>0 THEN
        trim(trailing '.' from trim(trailing '0' from q.small_blind::text))||'/'||
        trim(trailing '.' from trim(trailing '0' from q.big_blind::text)) END,
      'rake_percent',q.rake_percent,'started_at',q.started_at,'status',q.status,
      'creator_id',q.created_by,'creator_name',NULLIF(q.creator_name,''),
      'creator_avatar',q.creator_avatar,'fee',round(q.fee,2),'fee_exact',q.fee,'winnings',q.winnings,
      'hands',q.hands,'players',q.players)
      ORDER BY q.started_at DESC NULLS LAST,q.kind DESC,q.id DESC),'[]'::jsonb)
      FROM bounded q
  $query$ INTO v_out USING p_club_id,p_start,p_end,p_limit;
  RETURN v_out;
END;
$_$;


ALTER FUNCTION public.fn_ca_club_game_rows(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text, p_limit integer) OWNER TO postgres;

--
-- TOC entry 5335 (class 1255 OID 18001404)
-- Name: fn_ca_club_game_rows_filtered(uuid, date, date, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_game_rows_filtered(p_club_id uuid, p_start date, p_end date, p_game text, p_stakes text, p_search text, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_out jsonb;
BEGIN
  EXECUTE $query$
    WITH cash_players AS MATERIALIZED (SELECT z.game_id,count(DISTINCT z.user_id)::integer players FROM public.ca_club_data_fact z WHERE z.club_id=ANY(public.fn_ca_club_data_clubs($1)) AND z.stat_date BETWEEN $2 AND $3 AND z.kind='CASH' AND z.user_id<>'00000000-0000-0000-0000-000000000000'::uuid GROUP BY z.game_id), cash AS (
      SELECT c.table_id,SUM(c.rake) fee,SUM(c.net) winnings,SUM(c.hands) hands,
             coalesce(max(cp.players),0)::integer players FROM public.club_table_daily c LEFT JOIN cash_players cp ON cp.game_id=c.table_id
       WHERE c.club_id = ANY (public.fn_ca_club_data_clubs($1)) AND c.stat_date BETWEEN $2 AND $3 GROUP BY c.table_id
    ), tournament_facts AS (
      SELECT d.tournament_id,SUM(d.fee) fee,SUM(d.winnings) winnings
        FROM public.ca_club_tournament_daily d WHERE d.club_id = ANY (public.fn_ca_club_data_clubs($1))
         AND d.stat_date BETWEEN $2 AND $3 GROUP BY d.tournament_id
    ), all_rows AS (
      SELECT 'CASH'::text kind,t.id::text id,COALESCE(t.name,'Unnamed') name,
        UPPER(COALESCE(t.game_variant,'nlh')) variant,
        CASE WHEN COALESCE(t.game_variant,'') ILIKE '%plo%' OR COALESCE(t.game_variant,'') ILIKE '%omaha%' THEN 'OMAHA'
             WHEN COALESCE(t.game_variant,'') ILIKE '%mixed%' OR COALESCE(t.game_mode,'') ILIKE '%mixed%' THEN 'MIXED'
             ELSE 'HOLDEM' END game_class,
        CASE WHEN COALESCE(t.big_blind,0)<1 THEN 'MICRO'
             WHEN COALESCE(t.big_blind,0)<5 THEN 'SMALL'
             WHEN COALESCE(t.big_blind,0)<25 THEN 'MID' ELSE 'HIGH' END stakes_tier,
        COALESCE(t.small_blind,0) small_blind,COALESCE(t.big_blind,0) big_blind,
        CASE WHEN COALESCE(t.rake_percent,-1)>=0 THEN t.rake_percent END rake_percent,
        t.created_at started_at,t.created_by,t.status,c.fee fee,
        round(c.winnings,2) winnings,c.hands::bigint,c.players,
        COALESCE(pr.username,'') creator_name,pr.avatar_url creator_avatar
        FROM cash c JOIN public.tables t ON t.id=c.table_id
        LEFT JOIN public.profiles pr ON pr.id=t.created_by
      UNION ALL
      SELECT CASE WHEN tr.tournament_type='SPIN' THEN 'SPIN'
                  WHEN tr.tournament_type='SNG' THEN 'SNG' WHEN tr.tournament_type='MTT' THEN 'MTT' ELSE coalesce(tr.tournament_type,'TOURNAMENT') END,
        tr.id::text,COALESCE(tr.name,'Tournament'),UPPER(COALESCE(tr.variant,tr.game_type,'nlh')),
        CASE WHEN tr.tournament_type='SPIN' THEN 'SPIN' WHEN tr.tournament_type='SNG' THEN 'SNG' WHEN tr.tournament_type='MTT' THEN 'MTT' ELSE coalesce(tr.tournament_type,'TOURNAMENT') END,'NA',
        0::numeric,0::numeric,NULL::numeric,tr.start_time,NULL::uuid,tr.status,
        COALESCE(f.fee,0),round(COALESCE(f.winnings,0),2),0::bigint,0::integer,
        ''::text,NULL::text
        FROM tournament_facts f JOIN public.tournaments tr ON tr.id=f.tournament_id
    ), bounded AS MATERIALIZED (
      SELECT * FROM all_rows r
       WHERE (UPPER(COALESCE(NULLIF($4,''),'ALL'))='ALL' OR r.game_class=UPPER($4))
         AND (UPPER(COALESCE(NULLIF($5,''),'ALL'))='ALL' OR r.stakes_tier=UPPER($5))
         AND (NULLIF(btrim(COALESCE($6,'')),'') IS NULL
           OR r.name ILIKE '%'||btrim($6)||'%' OR r.id ILIKE '%'||btrim($6)||'%'
           OR r.creator_name ILIKE '%'||btrim($6)||'%')
       ORDER BY r.started_at DESC NULLS LAST,r.kind DESC,r.id DESC LIMIT $7
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'kind',q.kind,'id',q.id,'name',q.name,'variant',q.variant,
      'game_class',q.game_class,'stakes_tier',q.stakes_tier,
      'blinds',CASE WHEN q.big_blind>0 THEN
        trim(trailing '.' from trim(trailing '0' from q.small_blind::text))||'/'||
        trim(trailing '.' from trim(trailing '0' from q.big_blind::text)) END,
      'rake_percent',q.rake_percent,'started_at',q.started_at,'status',q.status,
      'creator_id',q.created_by,'creator_name',NULLIF(q.creator_name,''),
      'creator_avatar',q.creator_avatar,'fee',round(q.fee,2),'fee_exact',q.fee,'winnings',q.winnings,
      'hands',q.hands,'players',CASE WHEN q.kind='CASH' THEN q.players ELSE COALESCE((
        SELECT count(DISTINCT p.user_id)::integer FROM public.ca_club_tournament_player_daily p
         WHERE p.club_id = ANY (public.fn_ca_club_data_clubs($1)) AND p.tournament_id=q.id::uuid
           AND p.stat_date BETWEEN $2 AND $3),0) END)
      ORDER BY q.started_at DESC NULLS LAST,q.kind DESC,q.id DESC),'[]'::jsonb)
      FROM bounded q
  $query$ INTO v_out USING p_club_id,p_start,p_end,p_game,p_stakes,p_search,p_limit;
  RETURN v_out;
END;
$_$;


