             greatest(coalesce(c.players,0),coalesce(f.seated,0))::integer players
        FROM raw_cash c FULL JOIN felt f ON f.table_id=c.table_id
        LEFT JOIN union_hands uh ON uh.table_id=coalesce(c.table_id,f.table_id)
