--
-- TOC entry 4868 (class 1255 OID 165889103)
-- Name: fn_ca_club_member_tournament_fee_daily_apply(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_member_tournament_fee_daily_apply() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.ca_club_member_tournament_fee_daily AS d
         (club_id, user_id, day, fees, entries, updated_at)
  SELECT n.club_id, n.player_id, (n.charged_at AT TIME ZONE 'UTC')::date,
         sum(n.rake_credit), count(*)::bigint, now()
    FROM new_rows n
   WHERE n.club_id IS NOT NULL AND n.player_id IS NOT NULL
   GROUP BY 1, 2, 3
   ORDER BY 1, 2, 3
  ON CONFLICT (club_id, user_id, day) DO UPDATE
     SET fees = d.fees + EXCLUDED.fees,
         entries = d.entries + EXCLUDED.entries,
         updated_at = now();
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_club_member_tournament_fee_daily_apply() OWNER TO postgres;

--
-- TOC entry 6158 (class 1255 OID 20927880)
-- Name: fn_ca_club_rake_daily_apply(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_rake_daily_apply(p_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET max_parallel_workers_per_gather TO '0'
    AS $$
DECLARE v_n integer := 0;
BEGIN
  IF p_ids IS NULL OR cardinality(p_ids) = 0 THEN RETURN 0; END IF;
  INSERT INTO public.ca_club_rake_daily AS d
         (club_id, stat_date, hands, rake, bbj, pot, source_rows, updated_at)
  SELECT c.club_id, c.stat_date, c.hands, c.rake, c.bbj, c.pot, c.source_rows, now()
    FROM public.fn_ca_club_rake_daily_compute(now(), now(), p_ids) c
  ON CONFLICT (club_id, stat_date) DO UPDATE
     SET hands = d.hands + EXCLUDED.hands,
         rake = d.rake + EXCLUDED.rake,
         bbj = d.bbj + EXCLUDED.bbj,
         pot = d.pot + EXCLUDED.pot,
         source_rows = d.source_rows + EXCLUDED.source_rows,
         updated_at = now();
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


ALTER FUNCTION public.fn_ca_club_rake_daily_apply(p_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 9570 (class 1255 OID 20927874)
-- Name: fn_ca_club_rake_daily_compute(timestamp with time zone, timestamp with time zone, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_rake_daily_compute(p_from timestamp with time zone, p_to timestamp with time zone, p_ids uuid[]) RETURNS TABLE(club_id uuid, stat_date date, hands bigint, rake numeric, bbj numeric, pot numeric, source_rows bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  WITH src AS (
    SELECT r.id, r.table_id, r.club_id, r.created_at,
           coalesce(r.rake_amount, 0) AS rake, coalesce(r.bbj_contribution, 0) AS bbj,
           coalesce(r.pot_size, 0) AS pot, r.player_contributions
      FROM rake_records r
     WHERE p_ids IS NOT NULL AND r.id = ANY (p_ids)
       AND r.club_id IS NOT NULL AND NOT coalesce(r.is_tournament, false)
       AND public.fn_ca_launch_accounting_accepts(r.club_id,r.created_at)
    UNION ALL
    SELECT r.id, r.table_id, r.club_id, r.created_at,
           coalesce(r.rake_amount, 0), coalesce(r.bbj_contribution, 0),
           coalesce(r.pot_size, 0), r.player_contributions
      FROM rake_records r
     WHERE p_ids IS NULL AND r.created_at >= p_from AND r.created_at < p_to
       AND r.club_id IS NOT NULL AND NOT coalesce(r.is_tournament, false)
       AND public.fn_ca_launch_accounting_accepts(r.club_id,r.created_at)
  ),
  tbl AS (
    SELECT s.id, s.club_id AS table_club, (s.created_at AT TIME ZONE 'UTC')::date AS day,
           s.rake, s.bbj, s.pot, s.player_contributions, t.union_id, s.table_id, s.created_at
      FROM src s
      LEFT JOIN tables t ON t.id = s.table_id
     WHERE t.id IS NULL OR t.tournament_id IS NULL
  ),
  -- Only a union table needs its contributions read: a standalone table's
  -- rake has exactly one place to go. A key that is not a uuid or a value
  -- that is not a number is ignored, never raised: a reporting rollup must
  -- not fail a ledger write. A contribution of zero still counts the hand
  -- for that player's club, as club_table_daily counts it.
  contrib AS (
    SELECT b.id, b.union_id,
           CASE WHEN e.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                THEN e.key::uuid END AS uid,
           CASE WHEN e.value ~ '^-?[0-9]+(\.[0-9]+)?$' THEN e.value::numeric END AS contrib
      FROM tbl b
      CROSS JOIN LATERAL jsonb_each_text(
        CASE WHEN jsonb_typeof(b.player_contributions) = 'object'
             THEN b.player_contributions ELSE '{}'::jsonb END) e
     WHERE b.union_id IS NOT NULL
  ),
  attributed AS (
    SELECT c.id, c.contrib,
           -- The witness wins. Without it, use the funding or seat at the
           -- hand's time, never a later seat or buy-in at the same table.
           coalesce((SELECT ra.club_id FROM rake_attributions ra
                      WHERE ra.rake_record_id = c.id AND ra.player_id = c.uid AND ra.club_id IS NOT NULL
                      LIMIT 1),
                    (SELECT x.funding_club_id FROM public.cash_participant_funding_receipts x
                      WHERE x.operation_kind = 'buyin' AND x.table_id = b.table_id
                        AND x.account_entity_id = c.uid AND x.seat_joined_at <= b.created_at
                      ORDER BY x.seat_joined_at DESC LIMIT 1),
                    (SELECT ts.club_id FROM public.table_seats ts
                      WHERE ts.table_id = b.table_id AND ts.user_id = c.uid
                        AND ts.club_id IS NOT NULL AND ts.joined_at <= b.created_at
                      ORDER BY ts.joined_at DESC LIMIT 1),
                    (SELECT cm.club_id
                       FROM club_members cm
                       JOIN union_clubs uc ON uc.club_id = cm.club_id AND uc.union_id = c.union_id
                      WHERE cm.user_id = c.uid
                      ORDER BY cm.joined_at ASC NULLS LAST, cm.club_id
                      LIMIT 1),
                    b.table_club) AS club_id
      FROM contrib c JOIN tbl b ON b.id = c.id
     WHERE c.uid IS NOT NULL AND c.contrib IS NOT NULL AND c.contrib >= 0
  ),
  split AS (
    SELECT a.id, a.club_id, sum(a.contrib) AS contrib, count(*) AS src_rows
      FROM attributed a GROUP BY a.id, a.club_id
  ),
  split_total AS (
    SELECT s.id, sum(s.contrib) AS tot FROM split s GROUP BY s.id
  ),
  hand_rows AS (
    SELECT b.*, EXISTS (SELECT 1 FROM split_total st WHERE st.id = b.id AND st.tot > 0) AS has_split
      FROM tbl b
  ),
  parts AS (
    -- A union hand with a usable split: rake by contribution share, and one
    -- hand for every club that contributed.
    SELECT h.day, s.club_id, 1::bigint AS hands, h.rake * s.contrib / st.tot AS rake,
           0::numeric AS bbj, 0::numeric AS pot, s.src_rows
      FROM split s
      JOIN split_total st ON st.id = s.id AND st.tot > 0
      JOIN hand_rows h ON h.id = s.id
    UNION ALL
    -- The table's club: the drop and the pot volume of every hand it hosted,
    -- plus the whole hand when nothing could be attributed.
    SELECT h.day, h.table_club,
           CASE WHEN h.has_split THEN 0 ELSE 1 END,
           CASE WHEN h.has_split THEN 0 ELSE h.rake END,
           h.bbj, h.pot,
           CASE WHEN h.has_split THEN 0 ELSE 1 END
      FROM hand_rows h
  )
  SELECT p.club_id, p.day, sum(p.hands)::bigint, sum(p.rake), sum(p.bbj), sum(p.pot),
         sum(p.src_rows)::bigint
    FROM parts p
   GROUP BY p.club_id, p.day;
$_$;


ALTER FUNCTION public.fn_ca_club_rake_daily_compute(p_from timestamp with time zone, p_to timestamp with time zone, p_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 4505 (class 1255 OID 20952376)
-- Name: fn_ca_club_rake_daily_ledger_total(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_rake_daily_ledger_total(p_day date) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(SUM(r.rake_amount), 0)
    FROM rake_records r
   WHERE r.created_at >= (p_day::timestamp AT TIME ZONE 'UTC')
     AND r.created_at <  ((p_day + 1)::timestamp AT TIME ZONE 'UTC')
     AND r.club_id IS NOT NULL
     AND NOT COALESCE(r.is_tournament, false)
     AND EXISTS (SELECT 1 FROM tables t WHERE t.id = r.table_id AND t.tournament_id IS NULL);
$$;


ALTER FUNCTION public.fn_ca_club_rake_daily_ledger_total(p_day date) OWNER TO postgres;

--
-- TOC entry 3567 (class 1255 OID 20955785)
-- Name: fn_ca_club_rake_daily_rebuild(date, date, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_rake_daily_rebuild(p_start date, p_end date, p_include_today boolean DEFAULT false) RETURNS TABLE(stat_date date, clubs bigint, hands bigint, rake numeric, ledger_rake numeric, difference numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_n integer;
BEGIN
  IF NOT (session_user IN ('postgres', 'supabase_admin')
          OR coalesce(auth.role(), '') = 'service_role'
          OR coalesce(fn_is_platform_admin(), false)) THEN
    RAISE EXCEPTION 'rebuild is an operator action' USING ERRCODE = '42501';
  END IF;
  v_n := public.fn_ca_club_rake_daily_rebuild_range(p_start, p_end, p_include_today);
  RETURN QUERY
  SELECT r.stat_date, count(*)::bigint, coalesce(sum(r.hands), 0)::bigint,
         round(coalesce(sum(r.rake), 0), 4),
         round(public.fn_ca_club_rake_daily_ledger_total(r.stat_date), 4),
         round(public.fn_ca_club_rake_daily_ledger_total(r.stat_date)
               - coalesce(sum(r.rake), 0), 4)
    FROM public.ca_club_rake_daily r
   WHERE r.stat_date BETWEEN LEAST(p_start, p_end) AND GREATEST(p_start, p_end)
   GROUP BY r.stat_date ORDER BY r.stat_date;
END;
$$;


ALTER FUNCTION public.fn_ca_club_rake_daily_rebuild(p_start date, p_end date, p_include_today boolean) OWNER TO postgres;

--
-- TOC entry 6296 (class 1255 OID 20955784)
-- Name: fn_ca_club_rake_daily_rebuild_range(date, date, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_rake_daily_rebuild_range(p_start date, p_end date, p_include_today boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_last date := CASE WHEN coalesce(p_include_today, false) THEN v_today ELSE v_today - 1 END;
  v_s date := LEAST(coalesce(p_start, v_today), coalesce(p_end, v_today));
  v_e date := LEAST(GREATEST(coalesce(p_start, v_today), coalesce(p_end, v_today)), v_last);
  d date;
  v_days integer := 0;
BEGIN
  IF v_s > v_e THEN RETURN 0; END IF;
  FOR d IN SELECT gs::date FROM generate_series(v_s, v_e, interval '1 day') gs LOOP
    -- One pass. A complete day has no writer to race, so the recount is
    -- exact; the caller checks the result against the ledger and says so.
    -- Retrying was measured on a live day and never closed the gap: see the
    -- header.
    PERFORM pg_advisory_xact_lock(hashtextextended('ca_club_rake_daily:' || d::text, 42));
    DELETE FROM public.ca_club_rake_daily r WHERE r.stat_date = d;
    INSERT INTO public.ca_club_rake_daily AS x
           (club_id, stat_date, hands, rake, bbj, pot, source_rows, updated_at)
    SELECT c.club_id, c.stat_date, c.hands, c.rake, c.bbj, c.pot, c.source_rows, now()
      FROM public.fn_ca_club_rake_daily_compute(
             (d::timestamp AT TIME ZONE 'UTC'), ((d + 1)::timestamp AT TIME ZONE 'UTC'), NULL) c
    ON CONFLICT (club_id, stat_date) DO UPDATE
       SET hands = x.hands + EXCLUDED.hands,
           rake = x.rake + EXCLUDED.rake,
           bbj = x.bbj + EXCLUDED.bbj,
           pot = x.pot + EXCLUDED.pot,
           source_rows = x.source_rows + EXCLUDED.source_rows,
           updated_at = now();
    v_days := v_days + 1;
  END LOOP;
  RETURN v_days;
END;
$$;


ALTER FUNCTION public.fn_ca_club_rake_daily_rebuild_range(p_start date, p_end date, p_include_today boolean) OWNER TO postgres;

--
-- TOC entry 7521 (class 1255 OID 21365605)
-- Name: fn_ca_club_rake_daily_user_apply(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_rake_daily_user_apply(p_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO public.ca_club_rake_daily_user (club_id, day, user_id, rake_cents, hands, updated_at)
  SELECT ra.club_id,
         (ra.created_at AT TIME ZONE 'UTC')::date,
         ra.player_id,
         SUM(round(ra.rake_amount * 100))::bigint,
         count(*)::bigint,
         now()
    FROM public.rake_attributions ra
   WHERE ra.id = ANY (p_ids)
     AND ra.club_id IS NOT NULL
     AND ra.player_id IS NOT NULL
     AND ra.rake_amount > 0
     AND public.fn_ca_launch_accounting_accepts(ra.club_id,(SELECT rr.created_at FROM public.rake_records rr WHERE rr.id=ra.rake_record_id))
   GROUP BY 1, 2, 3
  ON CONFLICT (club_id, day, user_id) DO UPDATE
     SET rake_cents = public.ca_club_rake_daily_user.rake_cents + EXCLUDED.rake_cents,
         hands      = public.ca_club_rake_daily_user.hands + EXCLUDED.hands,
         updated_at = now();
END;
$$;


ALTER FUNCTION public.fn_ca_club_rake_daily_user_apply(p_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 5673 (class 1255 OID 21365607)
-- Name: fn_ca_club_rake_daily_user_rebuild_day(uuid, date, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_rake_daily_user_rebuild_day(p_club_id uuid, p_day date, p_user_id uuid DEFAULT NULL::uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_rows bigint := 0;
BEGIN
  IF p_club_id IS NULL OR p_day IS NULL THEN
    RETURN 0;
  END IF;

  DELETE FROM public.ca_club_rake_daily_user d
   WHERE d.club_id = p_club_id AND d.day = p_day
     AND (p_user_id IS NULL OR d.user_id = p_user_id);

  INSERT INTO public.ca_club_rake_daily_user (club_id, day, user_id, rake_cents, hands, updated_at)
  SELECT ra.club_id,
         p_day,
         ra.player_id,
         SUM(round(ra.rake_amount * 100))::bigint,
         count(*)::bigint,
         now()
    FROM public.rake_attributions ra
   WHERE ra.club_id = p_club_id
     AND ra.created_at >= p_day::timestamptz
     AND ra.created_at <  (p_day + 1)::timestamptz
     AND ra.player_id IS NOT NULL
     AND ra.rake_amount > 0
     AND public.fn_ca_launch_accounting_accepts(ra.club_id,(SELECT rr.created_at FROM public.rake_records rr WHERE rr.id=ra.rake_record_id))
     AND (p_user_id IS NULL OR ra.player_id = p_user_id)
   GROUP BY 1, 3;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows;
END;
$$;


ALTER FUNCTION public.fn_ca_club_rake_daily_user_rebuild_day(p_club_id uuid, p_day date, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 3829 (class 1255 OID 166027197)
-- Name: fn_ca_club_table_daily_add_rake(uuid, numeric, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_table_daily_add_rake(p_table uuid, p_rake numeric, p_at timestamp with time zone, p_contrib jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_union uuid; v_table_club uuid; v_tourn uuid; v_found boolean;
  v_day date := (p_at AT TIME ZONE 'UTC')::date;
  r record; v_new int;
BEGIN
  SELECT t.union_id, t.club_id, t.tournament_id, true
    INTO v_union, v_table_club, v_tourn, v_found
    FROM public.tables t WHERE t.id = p_table;
  IF v_found IS NOT TRUE OR v_tourn IS NOT NULL OR COALESCE(p_rake, 0) <= 0 THEN RETURN; END IF;

  FOR r IN
    WITH e AS (
      SELECT x.key AS uid,
             CASE WHEN x.value ~ '^-?[0-9]+(\.[0-9]+)?$' THEN x.value::numeric ELSE 0 END AS contrib
        FROM jsonb_each_text(CASE WHEN jsonb_typeof(p_contrib) = 'object' THEN p_contrib ELSE '{}'::jsonb END) x
       WHERE x.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    ), usable AS (
      SELECT EXISTS (SELECT 1 FROM e WHERE e.contrib > 0) AS ok
    ), rr AS (
      SELECT e.uid, e.contrib, SUM(e.contrib) OVER () AS tot FROM e, usable WHERE usable.ok
      UNION ALL
      SELECT NULL::text, 1::numeric, 1::numeric FROM usable WHERE NOT usable.ok
    )
    SELECT CASE WHEN rr.uid IS NULL THEN v_table_club
                ELSE public.fn_ca_cash_table_reporting_club(v_union, v_table_club, rr.uid::uuid, p_table) END AS club_id,
           SUM(p_rake * rr.contrib / rr.tot) AS rake,
           COUNT(*) AS src,
           array_agg(DISTINCT rr.uid) FILTER (WHERE rr.uid IS NOT NULL) AS uids
      FROM rr WHERE rr.tot > 0
     GROUP BY 1 ORDER BY 1
  LOOP
    CONTINUE WHEN r.club_id IS NULL;
    CONTINUE WHEN public.fn_ca_launch_accounting_accepts(r.club_id, p_at) IS NOT TRUE;
    v_new := 0;
    IF r.uids IS NOT NULL THEN
      WITH ins AS (
        INSERT INTO public.ca_club_table_player_daily (club_id, table_id, stat_date, user_id)
        SELECT r.club_id, p_table, v_day, u::uuid FROM unnest(r.uids) u
        ON CONFLICT DO NOTHING RETURNING 1)
      SELECT count(*) INTO v_new FROM ins;
    END IF;
    INSERT INTO public.club_table_daily AS d
      (club_id, table_id, stat_date, union_id, rake, hands, players,
       buyins, cashouts, net, source_rows, updated_at)
    VALUES (r.club_id, p_table, v_day, v_union, r.rake, 1, v_new, 0, 0, 0, r.src, now())
    ON CONFLICT (club_id, table_id, stat_date) DO UPDATE
       SET rake = d.rake + EXCLUDED.rake,
           hands = d.hands + 1,
           players = d.players + EXCLUDED.players,
           source_rows = d.source_rows + EXCLUDED.source_rows,
           union_id = COALESCE(d.union_id, EXCLUDED.union_id),
           updated_at = now();
  END LOOP;
END;
$_$;


ALTER FUNCTION public.fn_ca_club_table_daily_add_rake(p_table uuid, p_rake numeric, p_at timestamp with time zone, p_contrib jsonb) OWNER TO postgres;

--
-- TOC entry 8390 (class 1255 OID 181168556)
-- Name: fn_ca_club_user_reporting_scope(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_club_user_reporting_scope(p_club_id uuid, p_user_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text;
BEGIN
  IF p_user_id IS NULL OR p_club_id IS NULL THEN RETURN 'none'; END IF;
  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id AND coalesce(is_admin, false)) THEN
    RETURN 'club';
  END IF;
  IF EXISTS (SELECT 1 FROM public.clubs WHERE id = p_club_id AND owner_id = p_user_id) THEN
    RETURN 'club';
  END IF;
  SELECT cm.role INTO v_role FROM public.club_members cm
   WHERE cm.club_id = p_club_id AND cm.user_id = p_user_id
     AND coalesce(cm.status, 'approved') IN ('active', 'approved')
   LIMIT 1;
  IF v_role IN ('owner', 'co_owner', 'admin') THEN
    RETURN 'club';
  ELSIF v_role IN ('super_agent', 'agent', 'sub_agent') THEN
    RETURN 'downline';
  END IF;
  RETURN 'none';
END;
$$;


ALTER FUNCTION public.fn_ca_club_user_reporting_scope(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 6433 (class 1255 OID 20883155)
-- Name: fn_ca_collusion_detector_health(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_collusion_detector_health(p_cadence_minutes integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_cadence     int := greatest(coalesce(p_cadence_minutes, 30), 1);
  v_stale_after int := v_cadence * 3 * 60;
  s public.ca_collusion_scan_state;
  v_newest_finding timestamptz;
  v_since_success  numeric;
  v_behind         numeric;
  v_has_gap        boolean;
  v_process_stale  boolean;
  v_coverage_stale boolean;
  v_status         text;
begin
  select * into s from public.ca_collusion_scan_state limit 1;

  -- Indexed now (see section 5): this used to seq-scan 169,530 rows on
  -- every render of every integrity panel.
  select max(created_at) into v_newest_finding from public.collusion_tracking;

  if not found or s.last_success_at is null then
    -- NEVER RUN is its own answer. Collapsing it into stale tells an
    -- operator a brand-new detector is broken; collapsing it into live
    -- tells them a broken one is new. Every key the live branch returns
    -- is returned here too, as NULL, so a console cannot read a missing
    -- field as a zero.
    return jsonb_build_object(
      'ok', true, 'status', 'never_run', 'stale', true,
      'stale_after_seconds', v_stale_after,
      'cadence_minutes', v_cadence,
      'last_success_at', null,
      'seconds_since_success', null,
      'seconds_behind', null,
      'last_scanned_hands', null,
      'last_findings', null,
      'catching_up', null,
      'unscanned_from', s.unscanned_from,
      'unscanned_to', s.unscanned_to,
      'unscanned_note', s.unscanned_note,
      'has_unscanned_gap', s.unscanned_from is not null,
      'newest_finding_at', v_newest_finding);
  end if;

  v_since_success := extract(epoch from now() - s.last_success_at);
  v_behind        := extract(epoch from now() - s.last_window_end);
  v_has_gap       := s.unscanned_from is not null;

  -- TWO INDEPENDENT QUESTIONS. The process running is not the same as
  -- the coverage keeping up, and the old health only asked the first.
  v_process_stale  := v_since_success > v_stale_after;
  v_coverage_stale := v_behind > v_stale_after;

  v_status := case
                when v_process_stale  then 'stale'    -- it stopped running
                when v_coverage_stale then 'behind'   -- it runs, and loses ground
                else 'live'
              end;

  return jsonb_build_object(
    'ok', true,
    'status', v_status,
    -- A HOLE IN THE RECORD IS NOT HEALTH. While an unscanned gap is
    -- recorded, this never answers false, whatever the process is doing.
    'stale', v_process_stale or v_coverage_stale or v_has_gap,
    'stale_after_seconds', v_stale_after,
    'cadence_minutes', v_cadence,
    'last_success_at', s.last_success_at,
    'seconds_since_success', round(v_since_success),
    'seconds_behind', round(v_behind),
    'last_scanned_hands', s.last_scanned_hands,
    'last_findings', s.last_findings,
    'catching_up', s.last_budget_hit,
    'unscanned_from', s.unscanned_from,
    'unscanned_to', s.unscanned_to,
    'unscanned_note', s.unscanned_note,
    'has_unscanned_gap', v_has_gap,
    'newest_finding_at', v_newest_finding);
end;
$$;


ALTER FUNCTION public.fn_ca_collusion_detector_health(p_cadence_minutes integer) OWNER TO postgres;

--
-- TOC entry 4216 (class 1255 OID 18281895)
-- Name: fn_ca_collusion_scan(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_collusion_scan(p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_since timestamptz := now() - make_interval(days => GREATEST(p_days,1));
  r RECORD; v_flagged int := 0; v_scanned int := 0;
BEGIN
  FOR r IN
    WITH pairflow AS (
      SELECT LEAST(t.winner_id, t.loser_id)    AS ua,
             GREATEST(t.winner_id, t.loser_id) AS ub,
             count(*)                          AS hands_together,
             sum(t.amount)                     AS gross_flow,
             sum(CASE WHEN t.winner_id < t.loser_id THEN t.amount ELSE -t.amount END) AS net_to_ua
        FROM public.ca_hand_transfers t
       WHERE t.played_at > v_since
         AND t.winner_id IS NOT NULL AND t.loser_id IS NOT NULL
         AND t.amount > 0
       GROUP BY 1, 2
    )
    SELECT CASE WHEN net_to_ua >= 0 THEN ua ELSE ub END AS receiver,
           CASE WHEN net_to_ua >= 0 THEN ub ELSE ua END AS sender,
           hands_together, gross_flow, abs(net_to_ua) AS net_flow,
           round(abs(net_to_ua) / NULLIF(gross_flow, 0), 3) AS direction_ratio
      FROM pairflow
     WHERE hands_together >= 20
       AND abs(net_to_ua) >= 5000
       AND abs(net_to_ua) / NULLIF(gross_flow, 0) > 0.8
  LOOP
    v_scanned := v_scanned + 1;
    INSERT INTO public.ca_collusion_signals
      (window_days, user_a, user_b, hands_together, gross_flow, net_flow,
       direction_ratio, both_cert, detail)
    VALUES
      (p_days, r.receiver, r.sender, r.hands_together, r.gross_flow, r.net_flow,
       r.direction_ratio,
       public.fn_ca_is_cert_account(r.receiver) AND public.fn_ca_is_cert_account(r.sender),
       jsonb_build_object('since', v_since));
    v_flagged := v_flagged + 1;

    -- signal, never a page: info for cert pairs and moderate flows; warning
    -- (one push, per policy) only for a large real-account flow
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_collusion_scan', 'unknown',
      CASE WHEN r.net_flow >= 50000
              AND NOT (public.fn_ca_is_cert_account(r.receiver)
                       AND public.fn_ca_is_cert_account(r.sender))
           THEN 'warning' ELSE 'info' END,
      'collusion:' || r.receiver::text || ':' || r.sender::text || ':' || to_char(now(), 'IYYY-IW'),
      r.net_flow, NULL, NULL,
      'reporting', 'user', r.receiver, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'one-directional chip flow: ' || r.net_flow || ' chips over ' || r.hands_together
        || ' shared hands in ' || p_days || 'd (direction ratio ' || r.direction_ratio
        || ') - review the pair; no automatic action taken',
      true,
      jsonb_build_object('receiver', r.receiver, 'sender', r.sender,
                         'hands_together', r.hands_together,
                         'gross_flow', r.gross_flow, 'net_flow', r.net_flow,
                         'direction_ratio', r.direction_ratio));
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'window_days', p_days,
                            'pairs_flagged', v_flagged);
END $$;


ALTER FUNCTION public.fn_ca_collusion_scan(p_days integer) OWNER TO postgres;

--
-- TOC entry 9254 (class 1255 OID 20883154)
-- Name: fn_ca_collusion_scan_advance(timestamp with time zone, integer, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_collusion_scan_advance(p_window_end timestamp with time zone, p_scanned_hands integer, p_findings integer, p_duration_ms integer, p_budget_hit boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id     boolean;
  v_before timestamptz;
  v_after  timestamptz;
  v_rows   int;
begin
  -- The id comes back with the mark so the UPDATE can be keyed on it.
  -- FOR UPDATE serialises overlapping runs on this one row; the
  -- dispatcher's client timeout does not cancel the worker, so a slow run
  -- and the next cron fire overlap by design.
  select s.id, s.last_window_end into v_id, v_before
    from public.ca_collusion_scan_state s
   limit 1
     for update;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no_state_row');
  end if;

  v_after := least(greatest(coalesce(p_window_end, v_before), v_before), now());

  update public.ca_collusion_scan_state
     set last_window_end    = greatest(last_window_end, v_after),
         last_success_at    = now(),
         last_duration_ms   = p_duration_ms,
         last_scanned_hands = p_scanned_hands,
         last_findings      = p_findings,
         last_budget_hit    = coalesce(p_budget_hit, false),
         updated_at         = now()
   -- THE WHOLE FIX. The table is a singleton and this predicate selects
   -- exactly the row the SELECT above locked, so it changes nothing about
   -- what the statement does - and it is the difference between the
   -- function running and PostgREST refusing it with 21000 before a single
   -- row is touched. Never remove it as redundant. It is not redundant to
   -- safeupdate, which reads the statement, not the table.
   where id = v_id;
  get diagnostics v_rows = row_count;

  if v_rows = 0 then
    return jsonb_build_object('ok', false, 'reason', 'no_rows_updated');
  end if;

  return jsonb_build_object('ok', true, 'from', v_before, 'to', v_after,
                            'advanced_seconds',
                            round(extract(epoch from v_after - v_before)));
end;
$$;


ALTER FUNCTION public.fn_ca_collusion_scan_advance(p_window_end timestamp with time zone, p_scanned_hands integer, p_findings integer, p_duration_ms integer, p_budget_hit boolean) OWNER TO postgres;

--
-- TOC entry 7756 (class 1255 OID 20883153)
-- Name: fn_ca_collusion_scan_state(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_collusion_scan_state() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
           'ok', true,
           'last_window_end', s.last_window_end,
           'last_success_at', s.last_success_at,
           'last_duration_ms', s.last_duration_ms,
           'last_scanned_hands', s.last_scanned_hands,
           'last_findings', s.last_findings,
           'last_budget_hit', s.last_budget_hit,
           'unscanned_from', s.unscanned_from,
           'unscanned_to', s.unscanned_to,
           'seconds_since_success',
             case when s.last_success_at is null then null
                  else round(extract(epoch from now() - s.last_success_at)) end,
           'seconds_behind', round(extract(epoch from now() - s.last_window_end)))
    from public.ca_collusion_scan_state s
   limit 1;
$$;


ALTER FUNCTION public.fn_ca_collusion_scan_state() OWNER TO postgres;

--
-- TOC entry 7542 (class 1255 OID 54285543)
-- Name: fn_ca_commerce_activate_launch_cohort(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_activate_launch_cohort(p_effective_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_row record;
  v_enrolled integer := 0;
  v_created integer := 0;
  v_notified integer := 0;
  v_result jsonb;
  v_heartbeat timestamptz;
  v_owner uuid;
  v_name text;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'staff_required');
  END IF;
  IF p_effective_at < now() - interval '1 hour' THEN
    RETURN jsonb_build_object('success', false, 'error', 'cohort_must_be_prospective');
  END IF;
  -- Enrolment creates reminders and, later, renewals that only the engine's
  -- commerce consumer delivers and executes. Without a recent wake nobody
  -- owns them, so nobody is enrolled.
  SELECT consumer_heartbeat_at INTO v_heartbeat FROM public.ca_commerce_settings WHERE id = 1;
  IF v_heartbeat IS NULL OR v_heartbeat < now() - interval '10 minutes' THEN
    RETURN jsonb_build_object('success', false, 'error', 'consumer_not_running', 'consumer_heartbeat_at', v_heartbeat);
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('ca_commerce_launch_cohort', 0));
  UPDATE public.ca_commerce_settings SET launch_cohort_activated_at = COALESCE(launch_cohort_activated_at, p_effective_at), updated_at = now() WHERE id = 1;
  FOR v_row IN
    SELECT 'club'::text AS scope_kind, c.id AS scope_id, c.name AS scope_name FROM public.clubs c
     WHERE c.owner_id IS NOT NULL AND COALESCE(c.lifecycle_status, 'active') <> 'retired' AND COALESCE(c.is_platform, false) = false
    UNION ALL
    SELECT 'union', u.id, u.name FROM public.unions u WHERE u.owner_id IS NOT NULL
  LOOP
    v_result := public.fn_ca_commerce_activate_trial_impl(v_row.scope_kind, v_row.scope_id, v_actor, 'launch_cohort', p_effective_at);
    IF (v_result->>'enrolled')::boolean THEN
      v_enrolled := v_enrolled + 1;
      -- The owner learns what was enrolled, until when it is free, that
      -- nothing is charged without their authorization, and where to manage
      -- it, in the same transaction as the enrolment itself.
      v_owner := public.fn_ca_commerce_scope_owner(v_row.scope_kind, v_row.scope_id);
      v_name := COALESCE(NULLIF(btrim(v_row.scope_name), ''), CASE v_row.scope_kind WHEN 'club' THEN 'Your Club' ELSE 'Your Union' END);
      PERFORM public.fn_ca_commerce_notice(v_owner, 'launch-cohort:' || v_row.scope_kind || ':' || v_row.scope_id::text, 'club_commerce_launch',
        'Your Free Operating Month Is Ready',
        'Club Arena Operating Software For ' || replace(v_name, chr(8212), '-') || ' Is Free Until '
          || to_char((v_result->>'trial_end')::timestamptz AT TIME ZONE 'America/Chicago', 'Mon DD, YYYY HH12:MI AM')
          || ' Central. Nothing Is Charged Unless You Authorize A Purchase Or Renewal. Manage It In Club And Union Diamond Costs.',
        '/hub/club-arena/' || v_row.scope_kind || 's/' || v_row.scope_id::text || '/diamond-costs',
        jsonb_build_object('trial_id', v_result->>'trial_id', 'trial_start', v_result->>'trial_start', 'trial_end', v_result->>'trial_end',
                           'scope_kind', v_row.scope_kind, 'scope_id', v_row.scope_id));
      v_notified := v_notified + 1;
    END IF;
    IF (v_result->>'created')::boolean THEN v_created := v_created + 1; END IF;
  END LOOP;
  INSERT INTO public.ca_commerce_events (kind, actor_id, detail)
  VALUES ('launch_cohort_activated', v_actor, jsonb_build_object('effective_at', p_effective_at, 'scopes_enrolled', v_enrolled, 'trials_created', v_created,
          'owners_notified', v_notified, 'consumer_heartbeat_at', v_heartbeat));
  RETURN jsonb_build_object('success', true, 'effective_at', p_effective_at, 'scopes_enrolled', v_enrolled, 'trials_created', v_created,
    'notices_recorded', v_notified);
END $$;


ALTER FUNCTION public.fn_ca_commerce_activate_launch_cohort(p_effective_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 8967 (class 1255 OID 54285542)
-- Name: fn_ca_commerce_activate_trial(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_activate_trial(p_scope_kind text, p_scope_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication_required');
  END IF;
  IF public.fn_ca_commerce_scope_role(p_scope_kind, p_scope_id, v_actor) <> 'owner' THEN
    RETURN jsonb_build_object('success', false, 'error', 'owner_required');
  END IF;
  RETURN public.fn_ca_commerce_activate_trial_impl(p_scope_kind, p_scope_id, v_actor, 'new_operator', now());
END $$;


ALTER FUNCTION public.fn_ca_commerce_activate_trial(p_scope_kind text, p_scope_id uuid) OWNER TO postgres;

--
-- TOC entry 4804 (class 1255 OID 54285538)
-- Name: fn_ca_commerce_activate_trial_impl(text, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_activate_trial_impl(p_scope_kind text, p_scope_id uuid, p_actor uuid, p_cohort text, p_start timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_owner uuid;
  v_settings public.ca_commerce_settings;
  v_trial public.ca_commerce_trials;
  v_existing public.ca_commerce_trials;
  v_created boolean := false;
  v_enrolled boolean := false;
  v_reason text;
BEGIN
  IF p_scope_kind NOT IN ('club','union') OR p_scope_id IS NULL THEN
    RAISE EXCEPTION 'A Trial Needs A Club Or Union Scope';
  END IF;
  v_owner := public.fn_ca_commerce_scope_owner(p_scope_kind, p_scope_id);
  IF v_owner IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'scope_not_found');
  END IF;
  SELECT * INTO v_settings FROM public.ca_commerce_settings WHERE id = 1;

  -- Serialize per operator so a double activation returns one grant (D01).
  PERFORM pg_advisory_xact_lock(hashtextextended('ca_commerce_trial:' || v_owner::text, 0));

  SELECT * INTO v_existing FROM public.fn_ca_commerce_scope_trial(p_scope_kind, p_scope_id);
  IF v_existing.id IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'replay', true, 'trial_id', v_existing.id,
      'trial_start', v_existing.trial_start, 'trial_end', v_existing.trial_end, 'cohort', v_existing.cohort,
      'enrolled', false, 'created', false);
  END IF;

  SELECT * INTO v_trial FROM public.ca_commerce_trials WHERE operator_id = v_owner AND cohort IN ('new_operator','launch_cohort');
  IF v_trial.id IS NULL THEN
    INSERT INTO public.ca_commerce_trials (operator_id, trial_start, trial_end, policy_version, cohort, activated_by)
    VALUES (v_owner, p_start, p_start + make_interval(hours => v_settings.trial_hours), v_settings.policy_version, p_cohort, p_actor)
    RETURNING * INTO v_trial;
    v_created := true;
    v_reason := 'Initial Operating Trial For This Operator';
  ELSE
    -- A later scope of the same operator inherits the common end time (D47).
    v_reason := 'Scope Enrolled Under The Operator''s Existing Trial; End Time Unchanged';
  END IF;

  INSERT INTO public.ca_commerce_trial_scopes (trial_id, scope_kind, scope_id, enrolled_by, reason)
  VALUES (v_trial.id, p_scope_kind, p_scope_id, p_actor, v_reason);
  v_enrolled := true;
  -- The trial right itself: every included operating service, zero debit,
  -- no Mint movement, ending at the operator's common trial end. A post-trial
  -- renewal authorization attaches to this row (R2 section 4.6).
  INSERT INTO public.ca_commerce_entitlements (scope_kind, scope_id, sku, kind, starts_at, ends_at, source, trial_id, net_paid)
  VALUES (p_scope_kind, p_scope_id, NULL, 'trial_operating', v_trial.trial_start, v_trial.trial_end, 'trial', v_trial.id, 0);

  INSERT INTO public.ca_commerce_events (kind, actor_id, scope_kind, scope_id, reference_id, detail)
  VALUES ('trial_enrolled', p_actor, p_scope_kind, p_scope_id, v_trial.id,
          jsonb_build_object('created', v_created, 'cohort', p_cohort, 'trial_end', v_trial.trial_end, 'reason', v_reason));

  IF v_created THEN
    PERFORM public.fn_ca_commerce_notice(v_owner, 'trial-reminder-21:' || v_trial.id::text, 'club_commerce_trial_reminder',
      'Your Operating Trial Ends In 9 Days',
      'Your Free Operating Month Ends On ' || to_char(v_trial.trial_end AT TIME ZONE 'America/Chicago', 'Mon DD, YYYY HH12:MI AM') || ' Central. Review Diamond Prices Before Then.',
      '/hub/club-arena/' || p_scope_kind || 's/' || p_scope_id::text || '/diamond-costs',
      jsonb_build_object('trial_id', v_trial.id, 'trial_end', v_trial.trial_end), v_trial.trial_start + interval '21 days');
    PERFORM public.fn_ca_commerce_notice(v_owner, 'trial-reminder-27:' || v_trial.id::text, 'club_commerce_trial_reminder',
      'Your Operating Trial Ends In 3 Days',
      'Your Free Operating Month Ends On ' || to_char(v_trial.trial_end AT TIME ZONE 'America/Chicago', 'Mon DD, YYYY HH12:MI AM') || ' Central. Choose Your Capacity To Continue Without Interruption.',
      '/hub/club-arena/' || p_scope_kind || 's/' || p_scope_id::text || '/diamond-costs',
      jsonb_build_object('trial_id', v_trial.id, 'trial_end', v_trial.trial_end), v_trial.trial_start + interval '27 days');
  END IF;

  RETURN jsonb_build_object('success', true, 'replay', false, 'trial_id', v_trial.id,
    'trial_start', v_trial.trial_start, 'trial_end', v_trial.trial_end, 'cohort', v_trial.cohort,
    'enrolled', v_enrolled, 'created', v_created);
END $$;


ALTER FUNCTION public.fn_ca_commerce_activate_trial_impl(p_scope_kind text, p_scope_id uuid, p_actor uuid, p_cohort text, p_start timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 8014 (class 1255 OID 54285569)
-- Name: fn_ca_commerce_admission(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_admission(p_scope_kind text, p_scope_id uuid, p_action text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid;
BEGIN
  IF COALESCE(auth.role(), 'service_role') <> 'service_role' THEN
    v_uid := auth.uid();
    IF v_uid IS NULL OR p_scope_kind IS NULL OR p_scope_kind NOT IN ('club','union') OR p_scope_id IS NULL OR NOT (
         public.fn_ca_commerce_scope_role(p_scope_kind, p_scope_id, v_uid) <> 'none'
      OR (p_scope_kind = 'club' AND EXISTS (
            SELECT 1 FROM public.union_clubs uc JOIN public.unions u ON u.id = uc.union_id
             WHERE uc.club_id = p_scope_id
               AND (u.owner_id = v_uid OR EXISTS (SELECT 1 FROM public.union_admins a WHERE a.union_id = u.id AND a.user_id = v_uid))))
      OR public.fn_is_platform_admin()) THEN
      RETURN jsonb_build_object('error', 'access_denied');
    END IF;
  END IF;
  RETURN public.fn_ca_commerce_admission_decide(p_scope_kind, p_scope_id, p_action);
END $$;


ALTER FUNCTION public.fn_ca_commerce_admission(p_scope_kind text, p_scope_id uuid, p_action text) OWNER TO postgres;

--
-- TOC entry 9361 (class 1255 OID 55344606)
-- Name: fn_ca_commerce_admission_decide(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_admission_decide(p_scope_kind text, p_scope_id uuid, p_action text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_settings public.ca_commerce_settings;
  v_enforced boolean;
  v_in_trial boolean;
  v_ent public.ca_commerce_entitlements;
  v_kind text;
  v_allowed boolean;
  v_reason text;
  v_roster integer;
BEGIN
  SELECT * INTO v_settings FROM public.ca_commerce_settings WHERE id = 1;
  v_enforced := v_settings.admission_enforced_from IS NOT NULL AND v_settings.admission_enforced_from <= now();
  IF p_scope_kind = 'club' AND EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = p_scope_id AND COALESCE(c.is_platform, false)) THEN
    RETURN jsonb_build_object('allowed', true, 'would_allow', true, 'enforced', v_enforced, 'reason', 'platform_scope');
  END IF;
  v_in_trial := public.fn_ca_commerce_in_trial(p_scope_kind, p_scope_id);
  v_kind := CASE p_action
    WHEN 'approve_member' THEN 'capacity'
    WHEN 'join_member' THEN 'capacity'
    WHEN 'open_table' THEN 'capacity'
    WHEN 'create_tournament' THEN 'capacity'
    WHEN 'union_tools' THEN 'union_back_office'
    WHEN 'club_insurance' THEN 'club_insurance_module'
    WHEN 'union_insurance' THEN 'union_insurance_module'
    ELSE NULL END;
  IF v_kind IS NULL THEN
    RETURN jsonb_build_object('allowed', true, 'would_allow', true, 'enforced', v_enforced, 'reason', 'unpriced_action');
  END IF;
  SELECT * INTO v_ent FROM public.ca_commerce_entitlements e
   WHERE e.scope_kind = p_scope_kind AND e.scope_id = p_scope_id AND e.kind = v_kind AND e.state = 'effective'
     AND e.starts_at <= now() AND (e.ends_at IS NULL OR e.ends_at > now())
   ORDER BY e.ends_at DESC NULLS FIRST LIMIT 1;
  IF v_in_trial THEN
    v_allowed := true; v_reason := 'trial';
  ELSIF v_ent.id IS NULL THEN
    v_allowed := false; v_reason := 'no_effective_entitlement';
  ELSIF p_action IN ('approve_member', 'join_member') THEN
    v_roster := public.fn_ca_commerce_roster_count(p_scope_id);
    v_allowed := v_roster < v_ent.capacity;
    v_reason := CASE WHEN v_allowed THEN 'within_capacity' ELSE 'capacity_reached' END;
  ELSE
    v_allowed := true; v_reason := 'entitled';
  END IF;
  RETURN jsonb_build_object('allowed', v_allowed OR NOT v_enforced, 'would_allow', v_allowed, 'enforced', v_enforced,
    'reason', v_reason, 'entitlement_id', v_ent.id, 'capacity', v_ent.capacity, 'roster_count', v_roster, 'trial', v_in_trial);
END $$;


ALTER FUNCTION public.fn_ca_commerce_admission_decide(p_scope_kind text, p_scope_id uuid, p_action text) OWNER TO postgres;

--
-- TOC entry 4175 (class 1255 OID 55344607)
-- Name: fn_ca_commerce_admission_message(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_admission_message(p_action text, p_reason text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN p_action = 'approve_member' AND p_reason = 'capacity_reached'
      THEN 'This Club Has Reached Its Member Capacity. Upgrade Capacity To Approve New Members. Current Members Are Not Affected.'
    WHEN p_action = 'approve_member'
      THEN 'This Club Needs Active Operating Access To Approve New Members. Current Members Are Not Affected.'
    WHEN p_action = 'join_member' AND p_reason = 'capacity_reached'
      THEN 'This Club Is Full And Cannot Accept New Members Right Now. Please Contact The Club.'
    WHEN p_action = 'join_member'
      THEN 'This Club Cannot Accept New Members Right Now. Please Contact The Club.'
    WHEN p_action = 'open_table'
      THEN 'This Club Needs Active Operating Access To Open A New Table. Running Tables Are Not Affected.'
    WHEN p_action = 'create_tournament'
      THEN 'This Club Needs Active Operating Access To Create A New Tournament. Scheduled And Running Tournaments Are Not Affected.'
    WHEN p_action = 'club_insurance'
      THEN 'This Club Needs The Insurance Module To Offer Insurance On A New Table. Existing Insurance Offers Are Not Affected.'
    WHEN p_action = 'union_insurance'
      THEN 'This Union Needs The Insurance Module To Offer Insurance On A New Table. Existing Insurance Offers Are Not Affected.'
    WHEN p_action = 'union_tools'
      THEN 'This Union Needs Back Office Access To Use This Tool. Existing Settlement And Records Are Not Affected.'
    ELSE 'Operating Access Is Required For This New Action. Existing Games And Members Are Not Affected.'
  END
$$;


ALTER FUNCTION public.fn_ca_commerce_admission_message(p_action text, p_reason text) OWNER TO postgres;

--
-- TOC entry 9369 (class 1255 OID 55344609)
-- Name: fn_ca_commerce_admission_report(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_admission_report(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_days integer := LEAST(GREATEST(COALESCE(p_days, 30), 1), 90);
  v_since timestamptz;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'staff_required');
  END IF;
  v_since := now() - make_interval(days => v_days);
  RETURN jsonb_build_object(
    'success', true,
    'days', v_days,
    'since', v_since,
    'enforced_from', (SELECT s.admission_enforced_from FROM public.ca_commerce_settings s WHERE s.id = 1),
    'enforced', COALESCE((SELECT s.admission_enforced_from <= now() FROM public.ca_commerce_settings s WHERE s.id = 1), false),
    'doors', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'action', x.action, 'door', x.door, 'decisions', x.decisions, 'would_deny', x.would_deny,
               'refused', x.refused, 'undecided', x.undecided, 'scopes_would_deny', x.scopes_would_deny,
               'last_at', x.last_at)
             ORDER BY x.would_deny DESC, x.decisions DESC, x.action, x.door)
        FROM (SELECT d.action, d.door, count(*)::integer AS decisions,
                     count(*) FILTER (WHERE d.would_allow IS FALSE)::integer AS would_deny,
                     count(*) FILTER (WHERE NOT d.allowed)::integer AS refused,
                     count(*) FILTER (WHERE d.would_allow IS NULL)::integer AS undecided,
                     count(DISTINCT d.scope_id) FILTER (WHERE d.would_allow IS FALSE)::integer AS scopes_would_deny,
                     max(d.decided_at) AS last_at
                FROM public.ca_commerce_admission_decisions d
               WHERE d.decided_at >= v_since
               GROUP BY d.action, d.door) x), '[]'::jsonb),
    'scopes', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'scope_kind', y.scope_kind, 'scope_id', y.scope_id, 'would_deny', y.would_deny,
               'refused', y.refused, 'reasons', y.reasons, 'last_at', y.last_at)
             ORDER BY y.would_deny DESC, y.last_at DESC)
        FROM (SELECT d.scope_kind, d.scope_id,
                     count(*)::integer AS would_deny,
                     count(*) FILTER (WHERE NOT d.allowed)::integer AS refused,
                     to_jsonb(array_agg(DISTINCT d.reason ORDER BY d.reason)) AS reasons,
                     max(d.decided_at) AS last_at
                FROM public.ca_commerce_admission_decisions d
               WHERE d.decided_at >= v_since AND d.would_allow IS FALSE
               GROUP BY d.scope_kind, d.scope_id
               ORDER BY count(*) DESC, max(d.decided_at) DESC
               LIMIT 50) y), '[]'::jsonb));
END $$;


ALTER FUNCTION public.fn_ca_commerce_admission_report(p_days integer) OWNER TO postgres;

--
-- TOC entry 7589 (class 1255 OID 55344608)
-- Name: fn_ca_commerce_admit(text, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_admit(p_scope_kind text, p_scope_id uuid, p_action text, p_door text, p_subject_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_d jsonb;
  v_allowed boolean;
  v_id bigint;
  v_policy text;
BEGIN
  IF p_action IN ('approve_member', 'join_member') THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('ca_commerce_scope:' || p_scope_kind || ':' || p_scope_id::text, 0));
  END IF;
  BEGIN
    v_d := public.fn_ca_commerce_admission_decide(p_scope_kind, p_scope_id, p_action);
  EXCEPTION WHEN OTHERS THEN
    v_d := jsonb_build_object('allowed', true, 'would_allow', NULL, 'enforced', false, 'reason', 'decision_unavailable', 'sqlstate', SQLSTATE);
  END;
  v_allowed := COALESCE((v_d->>'allowed')::boolean, true);
  BEGIN
    SELECT s.policy_version INTO v_policy FROM public.ca_commerce_settings s WHERE s.id = 1;
    INSERT INTO public.ca_commerce_admission_decisions
      (scope_kind, scope_id, action, door, actor_id, subject_id, would_allow, enforced, allowed, reason, entitlement_id, policy_version)
    VALUES
      (p_scope_kind, p_scope_id, p_action, p_door, auth.uid(), p_subject_id, (v_d->>'would_allow')::boolean,
       COALESCE((v_d->>'enforced')::boolean, false), v_allowed, COALESCE(v_d->>'reason', 'unknown'),
       NULLIF(v_d->>'entitlement_id', '')::uuid, v_policy)
    RETURNING id INTO v_id;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'ca_commerce admission decision not recorded for % % % (%): %', p_door, p_scope_kind, p_scope_id, SQLSTATE, SQLERRM;
  END;
  RETURN v_d || jsonb_build_object('decision_id', v_id, 'door', p_door,
    'message', CASE WHEN v_allowed THEN NULL ELSE public.fn_ca_commerce_admission_message(p_action, v_d->>'reason') END);
END $$;


ALTER FUNCTION public.fn_ca_commerce_admit(p_scope_kind text, p_scope_id uuid, p_action text, p_door text, p_subject_id uuid) OWNER TO postgres;

--
-- TOC entry 4684 (class 1255 OID 54285535)
-- Name: fn_ca_commerce_allocate(integer[], integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_allocate(p_weights integer[], p_reduction integer) RETURNS integer[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_total bigint := 0;
  v_out integer[] := '{}';
  v_rem numeric[] := '{}';
  v_i integer;
  v_share numeric;
  v_floor integer;
  v_assigned bigint := 0;
  v_left integer;
  v_best integer;
  v_best_val numeric;
BEGIN
  IF p_reduction < 0 THEN RAISE EXCEPTION 'A Reduction Cannot Be Negative'; END IF;
  FOR v_i IN 1 .. COALESCE(array_length(p_weights, 1), 0) LOOP
    v_total := v_total + GREATEST(p_weights[v_i], 0);
  END LOOP;
  IF p_reduction > v_total THEN RAISE EXCEPTION 'A Reduction Cannot Exceed The Basket'; END IF;
  FOR v_i IN 1 .. COALESCE(array_length(p_weights, 1), 0) LOOP
    IF v_total = 0 THEN
      v_out := v_out || 0; v_rem := v_rem || 0::numeric;
    ELSE
      v_share := (p_reduction::numeric * GREATEST(p_weights[v_i], 0)::numeric) / v_total::numeric;
      v_floor := floor(v_share)::integer;
      v_out := v_out || v_floor;
      v_rem := v_rem || (v_share - v_floor);
      v_assigned := v_assigned + v_floor;
    END IF;
  END LOOP;
  v_left := p_reduction - v_assigned;
  WHILE v_left > 0 LOOP
    v_best := NULL; v_best_val := -1;
    FOR v_i IN 1 .. array_length(v_out, 1) LOOP
      IF v_rem[v_i] > v_best_val AND v_out[v_i] < p_weights[v_i] THEN
        v_best := v_i; v_best_val := v_rem[v_i];
      END IF;
    END LOOP;
    EXIT WHEN v_best IS NULL;
    v_out[v_best] := v_out[v_best] + 1;
    v_rem[v_best] := -1;
    v_left := v_left - 1;
  END LOOP;
  RETURN v_out;
END $$;


ALTER FUNCTION public.fn_ca_commerce_allocate(p_weights integer[], p_reduction integer) OWNER TO postgres;

