--
-- TOC entry 2822 (class 1259 OID 54285405)
-- Name: ca_commerce_renewal_mandates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ca_commerce_renewal_mandates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entitlement_id uuid NOT NULL,
    scope_kind text NOT NULL,
    scope_id uuid NOT NULL,
    payer_id uuid NOT NULL,
    sku text NOT NULL,
    quantity integer DEFAULT 1 NOT NULL,
    max_diamonds integer NOT NULL,
    state text DEFAULT 'authorized'::text NOT NULL,
    due_at timestamp with time zone NOT NULL,
    lease_token uuid,
    lease_until timestamp with time zone,
    attempts integer DEFAULT 0 NOT NULL,
    last_result jsonb,
    renewal_purchase_id uuid,
    accepted_by uuid NOT NULL,
    accepted_at timestamp with time zone DEFAULT now() NOT NULL,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sponsorship_id uuid,
    terms_version integer DEFAULT public.fn_ca_commerce_policy_version('renewal_terms'::text),
    ceiling_text_version integer DEFAULT public.fn_ca_commerce_policy_version('renewal_ceiling'::text),
    CONSTRAINT ca_commerce_renewal_mandates_max_diamonds_check CHECK ((max_diamonds >= 0)),
    CONSTRAINT ca_commerce_renewal_mandates_quantity_check CHECK ((quantity > 0)),
    CONSTRAINT ca_commerce_renewal_mandates_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['club'::text, 'union'::text]))),
    CONSTRAINT ca_commerce_renewal_mandates_state_check CHECK ((state = ANY (ARRAY['authorized'::text, 'cancelled'::text, 'needs_attention'::text, 'completed'::text])))
);


