--

CREATE TABLE public.ca_commerce_price_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sku text NOT NULL,
    version integer NOT NULL,
    diamonds integer NOT NULL,
    price_rule text DEFAULT 'flat'::text NOT NULL,
    cap_diamonds integer,
    status text DEFAULT 'draft'::text NOT NULL,
    effective_from timestamp with time zone,
    effective_to timestamp with time zone,
    price_authority text NOT NULL,
    comparison_verified boolean DEFAULT false NOT NULL,
    comparison_evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid,
    published_by uuid,
    published_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ca_commerce_price_versions_cap_diamonds_check CHECK (((cap_diamonds IS NULL) OR (cap_diamonds > 0))),
    CONSTRAINT ca_commerce_price_versions_check CHECK (((effective_to IS NULL) OR (effective_from IS NULL) OR (effective_to > effective_from))),
    CONSTRAINT ca_commerce_price_versions_check1 CHECK (((status <> 'published'::text) OR (effective_from IS NOT NULL))),
    CONSTRAINT ca_commerce_price_versions_diamonds_check CHECK (((diamonds >= 0) AND (diamonds <= 2147483647))),
    CONSTRAINT ca_commerce_price_versions_price_rule_check CHECK ((price_rule = ANY (ARRAY['flat'::text, 'per_unit'::text, 'per_unit_capped'::text]))),
    CONSTRAINT ca_commerce_price_versions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'validated'::text, 'published'::text, 'retired'::text]))),
    CONSTRAINT ca_commerce_price_versions_version_check CHECK ((version > 0))
);


