--
-- TOC entry 7540 (class 1255 OID 54285570)
-- Name: fn_ca_commerce_price_draft(text, integer, text, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_price_draft(p_sku text, p_diamonds integer, p_price_rule text, p_cap_diamonds integer, p_price_authority text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_version integer;
  v_id uuid;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'staff_required');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.ca_commerce_products WHERE sku = p_sku) THEN
    RETURN jsonb_build_object('success', false, 'error', 'unknown_sku');
  END IF;
  IF p_diamonds IS NULL OR p_diamonds < 0 OR p_diamonds > 2147483647 OR p_price_rule NOT IN ('flat','per_unit','per_unit_capped') OR length(COALESCE(p_price_authority, '')) < 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_price');
  END IF;
  -- Two staff drafting the same product at once must not collide on a version.
  PERFORM pg_advisory_xact_lock(hashtextextended('ca_commerce_price_draft:' || p_sku, 0));
  SELECT COALESCE(MAX(version), 0) + 1 INTO v_version FROM public.ca_commerce_price_versions WHERE sku = p_sku;
  INSERT INTO public.ca_commerce_price_versions (sku, version, diamonds, price_rule, cap_diamonds, status, price_authority, created_by)
  VALUES (p_sku, v_version, p_diamonds, p_price_rule, p_cap_diamonds, 'draft', p_price_authority, v_actor) RETURNING id INTO v_id;
  INSERT INTO public.ca_commerce_events (kind, actor_id, reference_id, detail) VALUES ('price_drafted', v_actor, v_id, jsonb_build_object('sku', p_sku, 'version', v_version, 'diamonds', p_diamonds));
  RETURN jsonb_build_object('success', true, 'price_version_id', v_id, 'version', v_version, 'status', 'draft');
END $$;


ALTER FUNCTION public.fn_ca_commerce_price_draft(p_sku text, p_diamonds integer, p_price_rule text, p_cap_diamonds integer, p_price_authority text) OWNER TO postgres;

--
-- TOC entry 4448 (class 1255 OID 54285571)
-- Name: fn_ca_commerce_price_publish(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_price_publish(p_price_version_id uuid, p_effective_from timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_v public.ca_commerce_price_versions;
  v_from timestamptz := COALESCE(p_effective_from, now());
  v_old public.ca_commerce_price_versions;
  v_m public.ca_commerce_renewal_mandates;
  v_old_gross integer;
  v_new_gross integer;
  v_title text;
  v_notified integer := 0;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'staff_required');
  END IF;
  -- A published price names its publisher (the version trigger refuses a
  -- NULL one); a service-role call carries no person, so say so in JSON.
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'publisher_required');
  END IF;
  SELECT * INTO v_v FROM public.ca_commerce_price_versions WHERE id = p_price_version_id FOR UPDATE;
  IF v_v.id IS NULL OR v_v.status <> 'validated' THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_validated');
  END IF;
  IF v_from < now() - interval '1 minute' THEN
    RETURN jsonb_build_object('success', false, 'error', 'price_changes_are_prospective');
  END IF;
  -- The price a standing renewal would pay today, read before it changes.
  SELECT * INTO v_old FROM public.ca_commerce_price_versions p
   WHERE p.sku = v_v.sku AND p.status = 'published' AND p.effective_from <= now() AND (p.effective_to IS NULL OR p.effective_to > now());
  -- The current published price retires at the new effective date; accepted
  -- purchases keep their price version (D74). A prospective publication
  -- leaves the current price published and in effect until v_from (no gap
  -- with no price); a published version that would only have started at or
  -- after v_from never takes effect and retires whole.
  UPDATE public.ca_commerce_price_versions
     SET status = CASE WHEN v_from <= now() OR effective_from >= v_from THEN 'retired' ELSE status END,
         effective_to = CASE WHEN effective_from >= v_from THEN effective_to ELSE v_from END
   WHERE sku = v_v.sku AND status = 'published' AND (effective_to IS NULL OR effective_to > v_from);
  UPDATE public.ca_commerce_price_versions SET status = 'published', effective_from = v_from, published_by = v_actor, published_at = now() WHERE id = v_v.id;
  INSERT INTO public.ca_commerce_events (kind, actor_id, reference_id, detail) VALUES ('price_published', v_actor, v_v.id, jsonb_build_object('sku', v_v.sku, 'version', v_v.version, 'effective_from', v_from));
  IF v_old.id IS NOT NULL THEN
    v_title := (SELECT p.title FROM public.ca_commerce_products p WHERE p.sku = v_v.sku);
    FOR v_m IN SELECT * FROM public.ca_commerce_renewal_mandates m WHERE m.sku = v_v.sku AND m.state = 'authorized' ORDER BY m.id LOOP
      v_old_gross := public.fn_ca_commerce_line_gross(v_old, v_m.quantity);
      v_new_gross := public.fn_ca_commerce_line_gross(v_v, v_m.quantity);
      CONTINUE WHEN v_new_gross <= v_old_gross;
      PERFORM public.fn_ca_commerce_notice(v_m.payer_id, 'price-change:' || v_v.id::text || ':' || v_m.id::text, 'club_commerce_price_change',
        'Price Change: ' || v_title,
        'The Price Of ' || v_title || ' Rises From ' || to_char(v_old_gross, 'FM999,999,999,990') || ' To ' || to_char(v_new_gross, 'FM999,999,999,990')
          || ' Diamonds On ' || to_char(v_from AT TIME ZONE 'America/Chicago', 'Mon DD, YYYY HH12:MI AM') || ' Central. Your Accepted Renewal Ceiling Is '
          || to_char(v_m.max_diamonds, 'FM999,999,999,990') || ' Diamonds, '
          || CASE WHEN v_new_gross > v_m.max_diamonds
                  THEN 'So Your Next Renewal Waits For Your Approval Instead Of Charging The Higher Price.'
                  ELSE 'So Renewals Continue At The New Price Unless You Cancel Or Lower Your Ceiling.' END,
        '/hub/club-arena/' || v_m.scope_kind || 's/' || v_m.scope_id::text || '/diamond-costs',
        jsonb_build_object('sku', v_v.sku, 'mandate_id', v_m.id, 'price_version_id', v_v.id, 'old_price', v_old_gross, 'new_price', v_new_gross,
                           'effective_from', v_from, 'max_diamonds', v_m.max_diamonds, 'above_ceiling', v_new_gross > v_m.max_diamonds));
      v_notified := v_notified + 1;
    END LOOP;
  END IF;
  RETURN jsonb_build_object('success', true, 'price_version_id', v_v.id, 'effective_from', v_from, 'price_change_notices', v_notified);
END $$;


ALTER FUNCTION public.fn_ca_commerce_price_publish(p_price_version_id uuid, p_effective_from timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 7146 (class 1255 OID 55343789)
-- Name: fn_ca_commerce_price_retire(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_price_retire(p_price_version_id uuid, p_effective_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_v public.ca_commerce_price_versions;
  v_to timestamptz := COALESCE(p_effective_to, now());
  v_supported boolean;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'staff_required');
  END IF;
  SELECT * INTO v_v FROM public.ca_commerce_price_versions WHERE id = p_price_version_id FOR UPDATE;
  IF v_v.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'price_version_not_found');
  END IF;
  IF v_v.status = 'retired' THEN
    RETURN jsonb_build_object('success', true, 'is_replay', true, 'price_version_id', v_v.id, 'status', 'retired', 'effective_to', v_v.effective_to);
  END IF;
  IF v_to < now() - interval '1 minute' THEN
    RETURN jsonb_build_object('success', false, 'error', 'retirement_is_prospective');
  END IF;
  IF v_v.status = 'published' THEN
    SELECT supported INTO v_supported FROM public.ca_commerce_products WHERE sku = v_v.sku;
    IF v_supported AND NOT EXISTS (
      SELECT 1 FROM public.ca_commerce_price_versions p
       WHERE p.sku = v_v.sku AND p.id <> v_v.id AND p.status = 'published' AND p.effective_to IS NULL
         AND p.effective_from <= GREATEST(v_to, v_v.effective_from)) THEN
      RETURN jsonb_build_object('success', false, 'error', 'supported_product_needs_a_price');
    END IF;
    IF v_to > now() AND v_to > v_v.effective_from THEN
      -- Still in effect until v_to, then no longer.
      UPDATE public.ca_commerce_price_versions SET effective_to = LEAST(COALESCE(effective_to, v_to), v_to) WHERE id = v_v.id RETURNING * INTO v_v;
    ELSE
      UPDATE public.ca_commerce_price_versions
         SET status = 'retired',
             effective_to = CASE WHEN v_v.effective_from < v_to THEN LEAST(COALESCE(effective_to, v_to), v_to) ELSE effective_to END
       WHERE id = v_v.id RETURNING * INTO v_v;
    END IF;
  ELSE
    UPDATE public.ca_commerce_price_versions SET status = 'retired' WHERE id = v_v.id RETURNING * INTO v_v;
  END IF;
  INSERT INTO public.ca_commerce_events (kind, actor_id, reference_id, detail)
  VALUES ('price_retired', v_actor, v_v.id, jsonb_build_object('sku', v_v.sku, 'version', v_v.version, 'status', v_v.status, 'effective_to', v_v.effective_to));
  RETURN jsonb_build_object('success', true, 'is_replay', false, 'price_version_id', v_v.id, 'status', v_v.status, 'effective_to', v_v.effective_to);
END $$;


ALTER FUNCTION public.fn_ca_commerce_price_retire(p_price_version_id uuid, p_effective_to timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 4706 (class 1255 OID 55343787)
-- Name: fn_ca_commerce_price_validate(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_price_validate(p_price_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_v public.ca_commerce_price_versions;
  v_product public.ca_commerce_products;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'staff_required');
  END IF;
  SELECT * INTO v_v FROM public.ca_commerce_price_versions WHERE id = p_price_version_id FOR UPDATE;
  IF v_v.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'price_version_not_found');
  END IF;
  IF v_v.status <> 'draft' THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_draft', 'status', v_v.status);
  END IF;
  SELECT * INTO v_product FROM public.ca_commerce_products WHERE sku = v_v.sku;
  -- Checks (R2 1.7, 7.3): a positive whole-diamond price (no free tier), a
  -- price rule that fits how the product is counted, a cap that is a real
  -- ceiling, and a term the catalog can sell.
  IF v_v.diamonds <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'zero_price_not_allowed');
  END IF;
  IF (v_product.quantity_unit = 'flat' AND v_v.price_rule <> 'flat')
     OR (v_product.quantity_unit = 'covered_club' AND v_v.price_rule NOT IN ('per_unit','per_unit_capped')) THEN
    RETURN jsonb_build_object('success', false, 'error', 'price_rule_does_not_fit_product', 'quantity_unit', v_product.quantity_unit, 'price_rule', v_v.price_rule);
  END IF;
  IF v_v.price_rule = 'per_unit_capped' AND v_v.cap_diamonds IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'cap_required');
  END IF;
  IF v_v.price_rule <> 'per_unit_capped' AND v_v.cap_diamonds IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'cap_not_allowed');
  END IF;
  IF v_v.price_rule = 'per_unit_capped' AND v_v.cap_diamonds < v_v.diamonds THEN
    RETURN jsonb_build_object('success', false, 'error', 'cap_below_unit_price');
  END IF;
  IF (v_product.term_kind = 'period' AND v_product.term_hours IS NULL)
     OR (v_product.term_kind = 'report_interval' AND v_product.report_days IS NULL) THEN
    RETURN jsonb_build_object('success', false, 'error', 'product_term_undefined');
  END IF;
  UPDATE public.ca_commerce_price_versions SET status = 'validated' WHERE id = v_v.id;
  INSERT INTO public.ca_commerce_events (kind, actor_id, reference_id, detail)
  VALUES ('price_validated', v_actor, v_v.id, jsonb_build_object('sku', v_v.sku, 'version', v_v.version, 'diamonds', v_v.diamonds, 'price_rule', v_v.price_rule));
  RETURN jsonb_build_object('success', true, 'price_version_id', v_v.id, 'version', v_v.version, 'status', 'validated');
END $$;


ALTER FUNCTION public.fn_ca_commerce_price_validate(p_price_version_id uuid) OWNER TO postgres;

--
-- TOC entry 7180 (class 1255 OID 54285232)
-- Name: fn_ca_commerce_price_version_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_price_version_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'A Price Version Is Never Deleted';
  END IF;
  IF OLD.status IN ('published','retired') AND (
       NEW.sku, NEW.version, NEW.diamonds, NEW.price_rule, NEW.cap_diamonds, NEW.effective_from,
       NEW.price_authority, NEW.published_by, NEW.published_at)
     IS DISTINCT FROM (
       OLD.sku, OLD.version, OLD.diamonds, OLD.price_rule, OLD.cap_diamonds, OLD.effective_from,
       OLD.price_authority, OLD.published_by, OLD.published_at) THEN
    RAISE EXCEPTION 'A Published Price Cannot Change In Place';
  END IF;
  IF (OLD.status = 'draft' AND NEW.status NOT IN ('draft','validated','retired'))
     OR (OLD.status = 'validated' AND NEW.status NOT IN ('validated','published','retired'))
     OR (OLD.status = 'published' AND NEW.status NOT IN ('published','retired'))
     OR (OLD.status = 'retired' AND NEW.status <> 'retired') THEN
    RAISE EXCEPTION 'Invalid Price Version Transition';
  END IF;
  IF OLD.status <> 'published' AND NEW.status = 'published' THEN
    IF NEW.published_by IS NULL OR NEW.published_at IS NULL OR NEW.effective_from IS NULL THEN
      RAISE EXCEPTION 'A Published Price Names Its Publisher And Effective Date';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.ca_commerce_price_versions p
       WHERE p.sku = NEW.sku AND p.id <> NEW.id AND p.status = 'published'
         AND tstzrange(p.effective_from, p.effective_to, '[)') && tstzrange(NEW.effective_from, NEW.effective_to, '[)')
    ) THEN
      RAISE EXCEPTION 'Two Published Prices Cannot Overlap For One Product';
    END IF;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_commerce_price_version_immutable() OWNER TO postgres;

--
-- TOC entry 8140 (class 1255 OID 55343793)
-- Name: fn_ca_commerce_price_versions(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_price_versions(p_sku text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'staff_required');
  END IF;
  RETURN jsonb_build_object('success', true, 'price_versions', COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
             'price_version_id', v.id, 'sku', v.sku, 'version', v.version, 'status', v.status,
             'diamonds', v.diamonds, 'price_rule', v.price_rule, 'cap_diamonds', v.cap_diamonds,
             'price_authority', v.price_authority, 'effective_from', v.effective_from, 'effective_to', v.effective_to,
             'created_by', v.created_by, 'published_by', v.published_by, 'published_at', v.published_at,
             'comparison_verified', v.comparison_verified, 'comparison_evidence', v.comparison_evidence,
             'in_effect', v.status = 'published' AND v.effective_from <= now() AND (v.effective_to IS NULL OR v.effective_to > now()),
             'created_at', v.created_at)
             ORDER BY v.created_at DESC, v.sku, v.version DESC)
      FROM public.ca_commerce_price_versions v
     WHERE p_sku IS NULL OR v.sku = p_sku), '[]'::jsonb));
END $$;


ALTER FUNCTION public.fn_ca_commerce_price_versions(p_sku text) OWNER TO postgres;

--
-- TOC entry 6349 (class 1255 OID 54285572)
-- Name: fn_ca_commerce_product_support(text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_product_support(p_sku text, p_supported boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_withdrawn integer := 0;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'staff_required');
  END IF;
  -- A product that sells a platform capability cannot be marked supported
  -- while the registry says the capability is unavailable (section 0b).
  IF p_supported IS TRUE AND EXISTS (
       SELECT 1 FROM public.ca_commerce_products p
        WHERE p.sku = p_sku AND p.platform_capability_id IS NOT NULL
          AND NOT public.fn_capability_available(p.platform_capability_id)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'capability_unavailable', 'sku', p_sku);
  END IF;
  UPDATE public.ca_commerce_products SET supported = p_supported WHERE sku = p_sku;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'unknown_sku'); END IF;
  IF p_supported IS NOT TRUE THEN
    UPDATE public.ca_commerce_quotes q SET status = 'withdrawn'
     WHERE q.status = 'open'
       AND EXISTS (SELECT 1 FROM jsonb_array_elements(q.lines) l WHERE l->>'sku' = p_sku);
    GET DIAGNOSTICS v_withdrawn = ROW_COUNT;
  END IF;
  INSERT INTO public.ca_commerce_events (kind, actor_id, detail) VALUES ('product_support_changed', v_actor,
    jsonb_build_object('sku', p_sku, 'supported', p_supported, 'quotes_withdrawn', v_withdrawn));
  RETURN jsonb_build_object('success', true, 'sku', p_sku, 'supported', p_supported, 'quotes_withdrawn', v_withdrawn);
END $$;


ALTER FUNCTION public.fn_ca_commerce_product_support(p_sku text, p_supported boolean) OWNER TO postgres;

--
-- TOC entry 6442 (class 1255 OID 54285556)
-- Name: fn_ca_commerce_purchase(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_purchase(p_quote_id uuid, p_request_key text, p_purchase_kind text DEFAULT 'purchase'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_detail text;
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication_required');
  END IF;
  IF p_purchase_kind NOT IN ('purchase','upgrade') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_purchase_kind');
  END IF;
  RETURN public.fn_ca_commerce_purchase_impl(v_actor, p_quote_id, p_request_key, p_purchase_kind);
EXCEPTION
  WHEN OTHERS THEN
    -- Every write above rolled back with this exception. Map the boundary's
    -- own refusals to readable copy; anything else stays a raised error.
    GET STACKED DIAGNOSTICS v_detail = PG_EXCEPTION_DETAIL;
    IF SQLERRM = 'CA_COMMERCE_INSUFFICIENT_DIAMONDS' THEN
      RETURN jsonb_build_object('success', false, 'error', 'insufficient_diamonds', 'balance', v_detail);
    END IF;
    IF SQLERRM LIKE 'CA_COMMERCE_%' THEN
      RETURN jsonb_build_object('success', false, 'error', lower(replace(SQLERRM, 'CA_COMMERCE_', '')), 'detail', v_detail);
    END IF;
    -- A canonical wallet reserve (unsettled Diamond Spin obligations, balance
    -- headroom) refused the debit: the purchase fails whole, the obligation
    -- stands (D07, D08).
    IF SQLSTATE = '23514' THEN
      RETURN jsonb_build_object('success', false, 'error', 'reserved_diamonds', 'detail', SQLERRM);
    END IF;
    RAISE;
END $$;


ALTER FUNCTION public.fn_ca_commerce_purchase(p_quote_id uuid, p_request_key text, p_purchase_kind text) OWNER TO postgres;

--
-- TOC entry 8811 (class 1255 OID 54285552)
-- Name: fn_ca_commerce_purchase_impl(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_purchase_impl(p_actor uuid, p_quote_id uuid, p_request_key text, p_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_settings public.ca_commerce_settings;
  v_quote public.ca_commerce_quotes;
  v_existing public.ca_commerce_purchases;
  v_purchase public.ca_commerce_purchases;
  v_purchase_id uuid := gen_random_uuid();
  v_request_hash text;
  v_now timestamptz := now();
  v_trial public.ca_commerce_trials;
  v_ctx text;
  v_line jsonb;
  v_lines jsonb := '[]'::jsonb;
  v_ent public.ca_commerce_entitlements;
  v_old public.ca_commerce_entitlements;
  v_before jsonb;
  v_after jsonb;
  v_expected_purchased integer;
  v_actual_purchased integer;
  v_available_purchased integer;
  v_balance integer;
  v_deduct jsonb;
  v_tx public.diamond_transactions;
  v_mint public.ca_mint_ledger;
  v_alloc jsonb := '[]'::jsonb;
  v_sponsorship public.ca_commerce_sponsorships;
  v_club_committed integer;
  v_ref text;
  v_owner uuid;
  v_mandate_id uuid;
  v_receipt_url text;
BEGIN
  IF p_request_key IS NULL OR length(p_request_key) < 8 OR length(p_request_key) > 200 THEN
    RETURN jsonb_build_object('success', false, 'error', 'request_key_required');
  END IF;
  v_request_hash := md5(COALESCE(p_quote_id::text, '') || ':' || p_kind);

  -- Barrier 1: request identity. Same key and payload replays the receipt;
  -- same key with a different payload refuses (D04, D05).
  SELECT * INTO v_existing FROM public.ca_commerce_purchases WHERE actor_id = p_actor AND request_key = p_request_key;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.request_hash <> v_request_hash THEN
      RETURN jsonb_build_object('success', false, 'error', 'request_key_reused');
    END IF;
    RETURN public.fn_ca_commerce_receipt_json(v_existing, true);
  END IF;

  SELECT * INTO v_quote FROM public.ca_commerce_quotes WHERE id = p_quote_id FOR UPDATE;
  IF v_quote.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'quote_not_found');
  END IF;
  IF v_quote.actor_id <> p_actor THEN
    RETURN jsonb_build_object('success', false, 'error', 'quote_belongs_to_another_actor');
  END IF;
  -- Barrier 2: quote consumption. A consumed quote returns its purchase only
  -- to the same actor and never charges again (D31).
  IF v_quote.status = 'consumed' THEN
    SELECT * INTO v_existing FROM public.ca_commerce_purchases WHERE id = v_quote.purchase_id;
    RETURN public.fn_ca_commerce_receipt_json(v_existing, true);
  END IF;
  IF v_quote.status <> 'open' OR v_quote.expires_at <= v_now THEN
    IF v_quote.status = 'open' THEN
      UPDATE public.ca_commerce_quotes SET status = 'expired' WHERE id = v_quote.id;
    END IF;
    RETURN jsonb_build_object('success', false, 'error', 'quote_expired', 'requote', true);
  END IF;
  -- The receipt names what was bought: an upgrade quote (its lines replace a
  -- right) is committed as an upgrade and nothing else is (renewals are the
  -- consumer's own kind). A mismatched kind is refused, never relabelled.
  IF p_kind IN ('purchase', 'upgrade')
     AND (p_kind = 'upgrade') IS DISTINCT FROM EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_quote.lines) l WHERE COALESCE(l->>'replaces_entitlement_id', '') <> '') THEN
    RETURN jsonb_build_object('success', false, 'error', 'purchase_kind_mismatch');
  END IF;

  SELECT * INTO v_settings FROM public.ca_commerce_settings WHERE id = 1;
  IF NOT v_settings.checkout_enabled THEN
    RETURN jsonb_build_object('success', false, 'error', 'checkout_disabled');
  END IF;

  -- Serialize every commerce writer for this scope (barrier 3; the overlap
  -- predicate below is only valid under this lock).
  PERFORM pg_advisory_xact_lock(hashtextextended('ca_commerce_scope:' || v_quote.scope_kind || ':' || v_quote.scope_id::text, 0));

  -- Recheck material context: owner, catalog, trial end and effective rights.
  v_owner := public.fn_ca_commerce_scope_owner(v_quote.scope_kind, v_quote.scope_id);
  SELECT * INTO v_trial FROM public.fn_ca_commerce_scope_trial(v_quote.scope_kind, v_quote.scope_id);
  v_ctx := md5(COALESCE(v_owner::text, '') || ':' || public.fn_ca_commerce_catalog_version()
              || ':' || COALESCE(v_trial.trial_end::text, '') || ':' || COALESCE((SELECT string_agg(e.id::text, ',' ORDER BY e.id) FROM public.ca_commerce_entitlements e WHERE e.scope_kind = v_quote.scope_kind AND e.scope_id = v_quote.scope_id AND e.state = 'effective' AND (e.ends_at IS NULL OR e.ends_at > v_now)), ''));
  IF v_ctx <> v_quote.context_hash THEN
    UPDATE public.ca_commerce_quotes SET status = 'withdrawn' WHERE id = v_quote.id;
    RETURN jsonb_build_object('success', false, 'error', 'context_changed', 'requote', true);
  END IF;
  IF v_quote.sponsorship_id IS NULL AND v_owner <> v_quote.payer_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'payer_no_longer_owner', 'requote', true);
  END IF;
  -- No operator-service debit before its paid period begins (R2 section
  -- 4.6): inside the trial the owner records a post-trial authorization
  -- instead, and the renewal consumer buys the first period at trial end.
  IF v_quote.net > 0 AND v_trial.id IS NOT NULL AND v_now >= v_trial.trial_start AND v_now < v_trial.trial_end THEN
    RETURN jsonb_build_object('success', false, 'error', 'trial_active_authorize_instead', 'trial_end', v_trial.trial_end);
  END IF;
  -- The canonical self-payer guard inside deduct_diamonds needs the payer's
  -- own session or the trusted service route. Say so before any write.
  IF v_quote.net > 0 AND COALESCE(auth.role(), '') <> 'service_role' AND auth.uid() IS DISTINCT FROM v_quote.payer_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'sponsor_route_required');
  END IF;

  -- Sponsorship budget under its row lock (D43, D44).
  IF v_quote.sponsorship_id IS NOT NULL THEN
    SELECT * INTO v_sponsorship FROM public.ca_commerce_sponsorships WHERE id = v_quote.sponsorship_id FOR UPDATE;
    IF v_sponsorship.state <> 'active' OR v_sponsorship.payer_id <> v_quote.payer_id
       OR v_sponsorship.effective_from > v_now OR (v_sponsorship.effective_to IS NOT NULL AND v_sponsorship.effective_to <= v_now)
       OR NOT EXISTS (SELECT 1 FROM public.union_clubs uc WHERE uc.club_id = v_quote.scope_id AND uc.union_id = v_sponsorship.union_id)
       OR (v_sponsorship.club_id IS NOT NULL AND v_sponsorship.club_id <> v_quote.scope_id) THEN
      RETURN jsonb_build_object('success', false, 'error', 'sponsorship_not_effective');
    END IF;
    IF v_sponsorship.committed + v_quote.net > v_sponsorship.total_budget THEN
      RETURN jsonb_build_object('success', false, 'error', 'sponsorship_budget_exceeded', 'remaining', v_sponsorship.total_budget - v_sponsorship.committed);
    END IF;
    IF v_sponsorship.per_club_budget IS NOT NULL THEN
      SELECT COALESCE(SUM(p.net), 0)::integer INTO v_club_committed FROM public.ca_commerce_purchases p
       WHERE p.sponsorship_id = v_sponsorship.id AND p.scope_id = v_quote.scope_id;
      IF v_club_committed + v_quote.net > v_sponsorship.per_club_budget THEN
        RETURN jsonb_build_object('success', false, 'error', 'sponsorship_club_budget_exceeded', 'remaining', v_sponsorship.per_club_budget - v_club_committed);
      END IF;
    END IF;
  END IF;

  -- Business identity: no overlapping effective right of the same kind
  -- except the one an upgrade replaces (D32).
  FOR v_line IN SELECT * FROM jsonb_array_elements(v_quote.lines) LOOP
    IF EXISTS (
      SELECT 1 FROM public.ca_commerce_entitlements e
       WHERE e.scope_kind = v_quote.scope_kind AND e.scope_id = v_quote.scope_id AND e.kind = v_line->>'kind'
         AND e.state = 'effective' AND e.ends_at IS NOT NULL
         AND e.id IS DISTINCT FROM NULLIF(v_line->>'replaces_entitlement_id', '')::uuid
         AND tstzrange(e.starts_at, e.ends_at, '[)') && tstzrange((v_line->>'starts_at')::timestamptz, (v_line->>'ends_at')::timestamptz, '[)')
    ) THEN
      UPDATE public.ca_commerce_quotes SET status = 'withdrawn' WHERE id = v_quote.id;
      RETURN jsonb_build_object('success', false, 'error', 'period_already_covered', 'requote', true);
    END IF;
  END LOOP;

  IF v_quote.net > 0 THEN
    v_ref := 'ca-commerce:' || v_purchase_id::text;
    -- The payer's wallet row is the lock every canonical writer takes first;
    -- holding it here makes the before/after lot snapshots this operation's
    -- own evidence (R2-A03) and places it after the scope and sponsorship
    -- locks in the documented order.
    PERFORM 1 FROM public.profiles p WHERE p.id = v_quote.payer_id FOR UPDATE;
    v_before := public.fn_ca_commerce_lot_snapshot(v_quote.payer_id);
    SELECT COALESCE(SUM((l->>'available')::bigint), 0)::integer INTO v_available_purchased FROM jsonb_array_elements(v_before) l;
    v_expected_purchased := LEAST(v_quote.net, GREATEST(v_available_purchased, 0));

    v_deduct := public.deduct_diamonds(v_quote.payer_id, v_quote.net,
      'Club And Union Diamond Costs: ' || v_quote.scope_kind || ' ' || v_quote.scope_id::text,
      'club_commerce', 'club_commerce',
      jsonb_build_object('purchase_id', v_purchase_id, 'quote_id', v_quote.id, 'scope_kind', v_quote.scope_kind, 'scope_id', v_quote.scope_id, 'kind', p_kind),
      v_ref, 0);
    IF NOT COALESCE((v_deduct->>'success')::boolean, false) THEN
      IF v_deduct->>'error' = 'Insufficient diamonds' THEN
        RAISE EXCEPTION 'CA_COMMERCE_INSUFFICIENT_DIAMONDS' USING DETAIL = COALESCE(v_deduct->>'balance', '0');
      END IF;
      RAISE EXCEPTION 'CA_COMMERCE_DEBIT_REFUSED' USING DETAIL = COALESCE(v_deduct->>'error', 'unknown');
    END IF;
    IF COALESCE((v_deduct->>'idempotent')::boolean, false) THEN
      RAISE EXCEPTION 'CA_COMMERCE_DEBIT_REFERENCE_REUSED' USING DETAIL = v_ref;
    END IF;

    -- Postcondition 1: the journal row for this operation, exact amount and class.
    SELECT * INTO v_tx FROM public.diamond_transactions t WHERE t.user_id = v_quote.payer_id AND t.reference_id = v_ref;
    IF v_tx.id IS NULL OR v_tx.amount <> -v_quote.net OR v_tx.issuance_class <> 'spend' OR v_tx.counterparty <> 'revenue:club_commerce' THEN
      RAISE EXCEPTION 'CA_COMMERCE_JOURNAL_UNPROVED' USING DETAIL = v_ref;
    END IF;
    -- Postcondition 2: the exact linked Mint retirement (R2-A04). The helper
    -- can swallow its own failure; the row is what counts.
    SELECT * INTO v_mint FROM public.ca_mint_ledger m WHERE m.diamond_tx_id = v_tx.id;
    IF v_mint.id IS NULL OR v_mint.action <> 'burn' OR v_mint.asset <> 'diamonds' OR v_mint.amount <> v_quote.net
       OR v_mint.holder_id IS DISTINCT FROM v_quote.payer_id THEN
      RAISE EXCEPTION 'CA_COMMERCE_REGISTER_UNPROVED' USING DETAIL = v_ref;
    END IF;
    -- Postcondition 3: persisted purchased-lot deltas equal the expected
    -- split (R2-A03). The helper's accumulator is not evidence.
    v_after := public.fn_ca_commerce_lot_snapshot(v_quote.payer_id);
    SELECT COALESCE(SUM((a->>'consumed')::bigint - (b->>'consumed')::bigint), 0)::integer,
           COALESCE(jsonb_agg(jsonb_build_object('lot_id', a->>'lot_id', 'consumed_delta', (a->>'consumed')::bigint - (b->>'consumed')::bigint)) FILTER (WHERE (a->>'consumed')::bigint <> (b->>'consumed')::bigint), '[]'::jsonb)
      INTO v_actual_purchased, v_alloc
      FROM jsonb_array_elements(v_after) a JOIN jsonb_array_elements(v_before) b ON a->>'lot_id' = b->>'lot_id';
    IF v_actual_purchased <> v_expected_purchased THEN
      RAISE EXCEPTION 'CA_COMMERCE_LOTS_UNPROVED' USING DETAIL = format('expected %s consumed %s', v_expected_purchased, v_actual_purchased);
    END IF;
    v_balance := (v_deduct->>'balance')::integer;

    IF v_quote.sponsorship_id IS NOT NULL THEN
      UPDATE public.ca_commerce_sponsorships SET committed = committed + v_quote.net WHERE id = v_quote.sponsorship_id;
    END IF;
  END IF;

  -- The receipt, written once with its proven accounting identities.
  INSERT INTO public.ca_commerce_purchases (id, quote_id, actor_id, payer_id, request_key, request_hash, scope_kind, scope_id, sponsorship_id, kind,
    gross, net, trial_waiver, lines, diamond_tx_id, mint_op_id, lot_allocation, catalog_version, policy_version)
  VALUES (v_purchase_id, v_quote.id, p_actor, v_quote.payer_id, p_request_key, v_request_hash, v_quote.scope_kind, v_quote.scope_id, v_quote.sponsorship_id, p_kind,
    v_quote.gross, v_quote.net, v_quote.trial_waiver, v_quote.lines, v_tx.id, v_mint.op_id, v_alloc, v_quote.catalog_version, v_settings.policy_version)
  RETURNING * INTO v_purchase;

  -- Rights.
  FOR v_line IN SELECT * FROM jsonb_array_elements(v_quote.lines) LOOP
    v_old := NULL;
    v_mandate_id := NULL;
    IF NULLIF(v_line->>'replaces_entitlement_id', '') IS NOT NULL THEN
      SELECT * INTO v_old FROM public.ca_commerce_entitlements WHERE id = (v_line->>'replaces_entitlement_id')::uuid FOR UPDATE;
      IF v_old.id IS NULL OR v_old.state <> 'effective' THEN
        RAISE EXCEPTION 'CA_COMMERCE_UPGRADE_TARGET_GONE';
      END IF;
    END IF;
    INSERT INTO public.ca_commerce_entitlements (scope_kind, scope_id, sku, kind, capacity, quantity, starts_at, ends_at, source, purchase_id, line_index, net_paid, value_basis, revision)
    VALUES (v_quote.scope_kind, v_quote.scope_id, v_line->>'sku', v_line->>'kind', NULLIF(v_line->>'capacity', '')::integer,
            COALESCE((v_line->>'quantity')::integer, 1), (v_line->>'starts_at')::timestamptz, (v_line->>'ends_at')::timestamptz,
            CASE WHEN v_quote.sponsorship_id IS NULL THEN 'purchase' ELSE 'sponsor' END, v_purchase.id, (v_line->>'index')::integer,
            (v_line->>'net')::integer, (v_line->>'net')::integer + (v_line->>'credit')::integer,
            CASE WHEN v_old.id IS NULL THEN 1 ELSE v_old.revision + 1 END)
    RETURNING * INTO v_ent;
    IF v_old.id IS NOT NULL THEN
      -- The replaced right ends at the quoted switch instant so the two
      -- periods abut exactly: no overlap, no gap, no double coverage.
      UPDATE public.ca_commerce_entitlements SET state = 'superseded', superseded_by = v_ent.id, ends_at = v_ent.starts_at, updated_at = v_now WHERE id = v_old.id;
      -- A mandate on the replaced right follows the replacement at the same ceiling.
      UPDATE public.ca_commerce_renewal_mandates SET entitlement_id = v_ent.id, sku = v_ent.sku, quantity = v_ent.quantity, due_at = v_ent.ends_at, updated_at = v_now
       WHERE entitlement_id = v_old.id AND state = 'authorized';
    END IF;
    IF v_quote.renewal_max_diamonds IS NOT NULL AND v_quote.sponsorship_id IS NULL
       AND NOT EXISTS (SELECT 1 FROM public.ca_commerce_renewal_mandates m WHERE m.entitlement_id = v_ent.id) THEN
      INSERT INTO public.ca_commerce_renewal_mandates (entitlement_id, scope_kind, scope_id, payer_id, sku, quantity, max_diamonds, due_at, accepted_by)
      VALUES (v_ent.id, v_quote.scope_kind, v_quote.scope_id, v_quote.payer_id, v_ent.sku, v_ent.quantity, v_quote.renewal_max_diamonds, v_ent.ends_at, p_actor)
      RETURNING id INTO v_mandate_id;
    END IF;
    v_lines := v_lines || (v_line || jsonb_build_object('entitlement_id', v_ent.id, 'mandate_id', v_mandate_id));
  END LOOP;

  UPDATE public.ca_commerce_quotes SET status = 'consumed', purchase_id = v_purchase.id WHERE id = v_quote.id;

  INSERT INTO public.ca_commerce_events (kind, actor_id, scope_kind, scope_id, reference_id, detail)
  VALUES ('purchase_committed', p_actor, v_quote.scope_kind, v_quote.scope_id, v_purchase.id,
          jsonb_build_object('net', v_quote.net, 'gross', v_quote.gross, 'kind', p_kind, 'payer_id', v_quote.payer_id, 'diamond_tx_id', v_purchase.diamond_tx_id));

  v_receipt_url := '/hub/club-arena/' || v_quote.scope_kind || 's/' || v_quote.scope_id::text || '/diamond-costs';
  PERFORM public.fn_ca_commerce_notice(v_quote.payer_id, 'receipt:' || v_purchase.id::text, 'club_commerce_receipt',
    'Diamond Receipt: ' || v_quote.net::text || ' Diamonds',
    CASE WHEN v_quote.net = 0 THEN 'No Diamonds Were Charged For This Order.' ELSE v_quote.net::text || ' Diamonds Were Charged For Club And Union Services.' END,
    v_receipt_url, jsonb_build_object('purchase_id', v_purchase.id, 'net', v_quote.net));

  RETURN public.fn_ca_commerce_receipt_json(v_purchase, false) || jsonb_build_object('lines', v_lines, 'balance_after', v_balance, 'balance_observed_at', v_now);
END $$;


ALTER FUNCTION public.fn_ca_commerce_purchase_impl(p_actor uuid, p_quote_id uuid, p_request_key text, p_kind text) OWNER TO postgres;

--
-- TOC entry 7683 (class 1255 OID 54285550)
-- Name: fn_ca_commerce_quote(text, uuid, jsonb, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_quote(p_scope_kind text, p_scope_id uuid, p_lines jsonb, p_sponsorship_id uuid DEFAULT NULL::uuid, p_renewal_max_diamonds integer DEFAULT NULL::integer, p_purchase_kind text DEFAULT 'purchase'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_role text;
  v_settings public.ca_commerce_settings;
  v_line jsonb;
  v_private public.ca_commerce_products;
  v_w public.ca_commerce_written_quotes;
  v_recent integer;
  v_result jsonb;
  v_owner uuid;
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication_required');
  END IF;
  IF p_purchase_kind NOT IN ('purchase','upgrade') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_purchase_kind');
  END IF;
  v_role := public.fn_ca_commerce_scope_role(p_scope_kind, p_scope_id, v_actor);
  IF p_sponsorship_id IS NULL THEN
    IF v_role <> 'owner' THEN
      RETURN jsonb_build_object('success', false, 'error', 'owner_required');
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.ca_commerce_sponsorships s WHERE s.id = p_sponsorship_id AND s.payer_id = v_actor) THEN
      RETURN jsonb_build_object('success', false, 'error', 'sponsor_payer_required');
    END IF;
  END IF;
  -- The catalog switch: while it is off, only staff can price anything.
  SELECT * INTO v_settings FROM public.ca_commerce_settings WHERE id = 1;
  IF NOT v_settings.catalog_visible AND NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'catalog_not_visible');
  END IF;
  -- A person prices at most 120 baskets in 10 minutes.
  SELECT count(*) INTO v_recent FROM public.ca_commerce_quotes q
   WHERE q.actor_id = v_actor AND q.created_at > now() - interval '10 minutes';
  IF v_recent >= 120 THEN
    RETURN jsonb_build_object('success', false, 'error', 'rate_limited', 'retry_after_seconds', 600);
  END IF;
  -- A written-quote offer is priced only for its own club, and only until it
  -- expires, unless that club already bought it (then it renews and upgrades
  -- like any capacity).
  IF jsonb_typeof(p_lines) = 'array' THEN
    FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
      SELECT * INTO v_private FROM public.ca_commerce_products p
       WHERE p.sku = v_line->>'sku' AND p.private_scope_id IS NOT NULL;
      IF v_private.sku IS NOT NULL THEN
        IF v_private.private_scope_kind <> p_scope_kind OR v_private.private_scope_id <> p_scope_id THEN
          RETURN jsonb_build_object('success', false, 'error', 'unknown_sku', 'sku', v_line->>'sku');
        END IF;
        SELECT * INTO v_w FROM public.ca_commerce_written_quotes WHERE id = v_private.written_quote_id;
        IF v_w.valid_until <= now() AND NOT EXISTS (
             SELECT 1 FROM public.ca_commerce_entitlements e
              WHERE e.scope_kind = p_scope_kind AND e.scope_id = p_scope_id AND e.sku = v_private.sku) THEN
          RETURN jsonb_build_object('success', false, 'error', 'written_quote_expired', 'sku', v_private.sku);
        END IF;
      END IF;
    END LOOP;
  END IF;
  v_result := public.fn_ca_commerce_quote_impl(v_actor, v_actor, p_scope_kind, p_scope_id, p_lines, p_sponsorship_id, p_renewal_max_diamonds, p_purchase_kind);
  -- The owner who has never had a free month is told before paying for it.
  IF COALESCE((v_result->>'success')::boolean, false) AND p_sponsorship_id IS NULL AND p_purchase_kind = 'purchase' THEN
    v_owner := public.fn_ca_commerce_scope_owner(p_scope_kind, p_scope_id);
    v_result := v_result || jsonb_build_object('free_month_available',
      (SELECT t.id FROM public.fn_ca_commerce_scope_trial(p_scope_kind, p_scope_id) t) IS NULL
      AND NOT EXISTS (SELECT 1 FROM public.ca_commerce_trials t WHERE t.operator_id = v_owner AND t.cohort IN ('new_operator','launch_cohort')));
  END IF;
  RETURN v_result;
END $$;


ALTER FUNCTION public.fn_ca_commerce_quote(p_scope_kind text, p_scope_id uuid, p_lines jsonb, p_sponsorship_id uuid, p_renewal_max_diamonds integer, p_purchase_kind text) OWNER TO postgres;

--
-- TOC entry 3487 (class 1255 OID 54285546)
-- Name: fn_ca_commerce_quote_impl(uuid, uuid, text, uuid, jsonb, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_quote_impl(p_actor uuid, p_payer uuid, p_scope_kind text, p_scope_id uuid, p_lines jsonb, p_sponsorship_id uuid, p_renewal_max integer, p_purchase_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_settings public.ca_commerce_settings;
  v_line jsonb;
  v_product public.ca_commerce_products;
  v_price public.ca_commerce_price_versions;
  v_quantity integer;
  v_gross integer;
  v_credit integer;
  v_starts timestamptz;
  v_ends timestamptz;
  v_out jsonb := '[]'::jsonb;
  v_weights integer[] := '{}';
  v_grosses integer[] := '{}';
  v_credits integer[] := '{}';
  v_waivers integer[];
  v_total_gross integer := 0;
  v_total_credit integer := 0;
  v_total_waiver integer := 0;
  v_in_trial boolean;
  v_trial public.ca_commerce_trials;
  v_replaces uuid;
  v_old public.ca_commerce_entitlements;
  v_quote public.ca_commerce_quotes;
  v_i integer := 0;
  v_ctx text;
  v_basket text;
  v_now timestamptz := now();
  v_line_count integer;
  v_seen_kinds text[] := '{}';
  v_roster integer;
  v_sponsorship public.ca_commerce_sponsorships;
  v_upgrade_seen boolean := false;
BEGIN
  IF p_scope_kind NOT IN ('club','union') OR p_scope_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_scope');
  END IF;
  IF jsonb_typeof(p_lines) <> 'array' THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_lines');
  END IF;
  v_line_count := jsonb_array_length(p_lines);
  IF v_line_count < 1 OR v_line_count > 12 THEN
    RETURN jsonb_build_object('success', false, 'error', 'basket_size');
  END IF;
  SELECT * INTO v_settings FROM public.ca_commerce_settings WHERE id = 1;
  IF NOT v_settings.checkout_enabled THEN
    RETURN jsonb_build_object('success', false, 'error', 'checkout_disabled');
  END IF;
  IF public.fn_ca_commerce_scope_owner(p_scope_kind, p_scope_id) IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'scope_not_found');
  END IF;
  IF p_sponsorship_id IS NOT NULL THEN
    SELECT * INTO v_sponsorship FROM public.ca_commerce_sponsorships WHERE id = p_sponsorship_id;
    IF v_sponsorship.id IS NULL OR v_sponsorship.state <> 'active' OR v_sponsorship.payer_id <> p_payer
       OR v_sponsorship.effective_from > v_now OR (v_sponsorship.effective_to IS NOT NULL AND v_sponsorship.effective_to <= v_now)
       OR p_scope_kind <> 'club' OR (v_sponsorship.club_id IS NOT NULL AND v_sponsorship.club_id <> p_scope_id)
       OR NOT EXISTS (SELECT 1 FROM public.union_clubs uc WHERE uc.club_id = p_scope_id AND uc.union_id = v_sponsorship.union_id) THEN
      RETURN jsonb_build_object('success', false, 'error', 'sponsorship_not_effective');
    END IF;
  END IF;

  SELECT * INTO v_trial FROM public.fn_ca_commerce_scope_trial(p_scope_kind, p_scope_id);
  v_in_trial := v_trial.id IS NOT NULL AND v_now >= v_trial.trial_start AND v_now < v_trial.trial_end;
  IF p_scope_kind = 'club' THEN v_roster := public.fn_ca_commerce_roster_count(p_scope_id); END IF;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    v_i := v_i + 1;
    v_old := NULL;
    SELECT * INTO v_product FROM public.ca_commerce_products WHERE sku = v_line->>'sku';
    IF v_product.sku IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'unknown_sku', 'line', v_i);
    END IF;
    IF NOT v_product.supported THEN
      RETURN jsonb_build_object('success', false, 'error', 'sku_not_available', 'sku', v_product.sku, 'line', v_i);
    END IF;
    -- A product that sells a platform capability is not sold while the
    -- registry says the capability is unavailable (20260924102040).
    IF v_product.platform_capability_id IS NOT NULL
       AND NOT public.fn_capability_available(v_product.platform_capability_id) THEN
      RETURN jsonb_build_object('success', false, 'error', 'sku_not_available', 'sku', v_product.sku, 'line', v_i,
        'capability', v_product.platform_capability_id);
    END IF;
    IF v_product.scope_kind <> p_scope_kind THEN
      RETURN jsonb_build_object('success', false, 'error', 'sku_scope_mismatch', 'sku', v_product.sku, 'line', v_i);
    END IF;
    IF v_product.kind = ANY (v_seen_kinds) THEN
      RETURN jsonb_build_object('success', false, 'error', 'duplicate_line', 'sku', v_product.sku, 'line', v_i);
    END IF;
    v_seen_kinds := v_seen_kinds || v_product.kind;
    SELECT * INTO v_price FROM public.ca_commerce_price_versions v
     WHERE v.sku = v_product.sku AND v.status = 'published' AND v.effective_from <= v_now AND (v.effective_to IS NULL OR v.effective_to > v_now);
    IF v_price.id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'no_published_price', 'sku', v_product.sku, 'line', v_i);
    END IF;

    -- A quantity must be a whole number; anything else is a refusal the page
    -- can name, never a raw cast error.
    IF v_line ? 'quantity' AND jsonb_typeof(v_line->'quantity') <> 'null'
       AND NOT (v_line->>'quantity') ~ '^[0-9]{1,6}$' THEN
      RETURN jsonb_build_object('success', false, 'error', 'quantity_out_of_range', 'sku', v_product.sku, 'line', v_i);
    END IF;
    v_quantity := COALESCE((v_line->>'quantity')::integer, 1);
    IF v_product.quantity_unit = 'flat' AND v_quantity <> 1 THEN
      RETURN jsonb_build_object('success', false, 'error', 'quantity_not_allowed', 'sku', v_product.sku, 'line', v_i);
    END IF;
    IF v_product.quantity_unit = 'covered_club' THEN
      IF v_quantity < 1 OR v_quantity > 500 THEN
        RETURN jsonb_build_object('success', false, 'error', 'quantity_out_of_range', 'sku', v_product.sku, 'line', v_i);
      END IF;
    END IF;
    IF v_product.term_kind <> 'period' THEN
      RETURN jsonb_build_object('success', false, 'error', 'term_not_supported_yet', 'sku', v_product.sku, 'line', v_i);
    END IF;

    v_gross := public.fn_ca_commerce_line_gross(v_price, v_quantity);
    v_credit := 0;
    v_replaces := NULL;

    -- Period placement: a renewal or first purchase begins at the later of
    -- now, the trial end and the end of the current effective right of the
    -- same kind. An upgrade replaces the current right from now and credits
    -- its unused whole-diamond remainder (R2 section 4.4).
    SELECT * INTO v_old FROM public.ca_commerce_entitlements e
     WHERE e.scope_kind = p_scope_kind AND e.scope_id = p_scope_id AND e.kind = v_product.kind
       AND e.state = 'effective' AND e.ends_at IS NOT NULL AND e.ends_at > v_now
     ORDER BY e.ends_at DESC LIMIT 1;

    IF p_purchase_kind = 'upgrade' THEN
      -- An upgrade amends the right in effect now, even when a later period
      -- of the same kind is already prepaid behind it.
      SELECT * INTO v_old FROM public.ca_commerce_entitlements e
       WHERE e.scope_kind = p_scope_kind AND e.scope_id = p_scope_id AND e.kind = v_product.kind
         AND e.state = 'effective' AND e.ends_at IS NOT NULL AND e.ends_at > v_now AND e.starts_at <= v_now
       ORDER BY e.ends_at DESC LIMIT 1;
      IF v_old.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'nothing_to_upgrade', 'sku', v_product.sku, 'line', v_i);
      END IF;
      IF v_old.sku = v_product.sku AND v_old.quantity = v_quantity THEN
        RETURN jsonb_build_object('success', false, 'error', 'same_capacity', 'sku', v_product.sku, 'line', v_i);
      END IF;
      IF (v_product.kind = 'capacity' AND v_product.capacity < v_old.capacity)
         OR (v_product.quantity_unit = 'covered_club' AND v_quantity < v_old.quantity) THEN
        RETURN jsonb_build_object('success', false, 'error', 'downgrade_applies_at_next_period', 'sku', v_product.sku, 'line', v_i);
      END IF;
      v_replaces := v_old.id;
      v_starts := v_now;
      v_ends := v_old.ends_at;
      -- Unused remainder of the actual net paid right, exact rational time,
      -- floored to whole diamonds so residues never manufacture value. Value
      -- already returned by a refund of that right is not credited again.
      v_credit := floor((GREATEST(v_old.value_basis - COALESCE((SELECT SUM(r.gross) FROM public.ca_commerce_refunds r
                          WHERE r.purchase_id = v_old.purchase_id AND r.line_index = v_old.line_index), 0), 0)::numeric
                         * extract(epoch FROM (v_old.ends_at - v_now))) / extract(epoch FROM (v_old.ends_at - v_old.starts_at)))::integer;
      -- The new line covers only the remaining time of a full term: the new
      -- list price prorated over the product's own term length, ceiling so a
      -- rounding residue is never free capacity.
      v_gross := ceil((v_gross::numeric * extract(epoch FROM (v_old.ends_at - v_now))) / (v_product.term_hours * 3600)::numeric)::integer;
      v_credit := LEAST(v_credit, v_gross);
      v_upgrade_seen := true;
    ELSE
      -- A first purchase starts now (or at the trial end while the trial is
      -- running). A renewal starts exactly where the current right ends, and
      -- a renewal inside the accepted lateness window keeps the period
      -- continuous (D51: no gap). Beyond that window a new period starts now.
      v_starts := v_now;
      IF v_in_trial THEN v_starts := v_trial.trial_end; END IF;
      -- Continuity is the renewal consumer's contract: an automatic renewal
      -- executed inside the accepted lateness window starts exactly where the
      -- trial or the previous period ended. A manual purchase after a lapse
      -- starts now; nobody pays for hours already gone.
      IF p_purchase_kind = 'renewal' AND v_trial.id IS NOT NULL AND v_trial.trial_end <= v_now
         AND v_trial.trial_end > v_now - make_interval(hours => v_settings.renewal_lateness_hours) THEN
        v_starts := v_trial.trial_end;
      END IF;
      IF v_old.id IS NOT NULL THEN v_starts := GREATEST(v_starts, v_old.ends_at); END IF;
      IF v_old.id IS NULL AND p_purchase_kind = 'renewal' THEN
        SELECT * INTO v_old FROM public.ca_commerce_entitlements e
         WHERE e.scope_kind = p_scope_kind AND e.scope_id = p_scope_id AND e.kind = v_product.kind
           AND e.state = 'effective' AND e.ends_at IS NOT NULL AND e.ends_at <= v_now
           AND e.ends_at > v_now - make_interval(hours => v_settings.renewal_lateness_hours)
         ORDER BY e.ends_at DESC LIMIT 1;
        IF v_old.id IS NOT NULL AND NOT v_in_trial THEN v_starts := v_old.ends_at; END IF;
        v_old := NULL;
      END IF;
      v_ends := v_starts + make_interval(hours => v_product.term_hours);
    END IF;

    IF v_product.kind = 'capacity' AND v_roster IS NOT NULL AND v_roster > v_product.capacity THEN
      RETURN jsonb_build_object('success', false, 'error', 'roster_exceeds_capacity', 'sku', v_product.sku, 'line', v_i,
        'roster_count', v_roster, 'capacity', v_product.capacity);
    END IF;

    v_grosses := v_grosses || v_gross;
    v_credits := v_credits || v_credit;
    v_weights := v_weights || (v_gross - v_credit);
    v_total_gross := v_total_gross + v_gross;
    v_total_credit := v_total_credit + v_credit;
    v_out := v_out || jsonb_build_object(
      'index', v_i - 1, 'sku', v_product.sku, 'kind', v_product.kind, 'title', v_product.title,
      'price_version_id', v_price.id, 'price_version', v_price.version, 'unit_diamonds', v_price.diamonds,
      'price_rule', v_price.price_rule, 'quantity', v_quantity, 'capacity', v_product.capacity,
      'term_hours', v_product.term_hours, 'starts_at', v_starts, 'ends_at', v_ends,
      'gross', v_gross, 'credit', v_credit, 'comparison_adjustment', 0, 'waiver', 0, 'net', v_gross - v_credit,
      'replaces_entitlement_id', v_replaces, 'included_note', v_product.included_note,
      'comparison_verified', v_price.comparison_verified);
  END LOOP;

  -- Trial waiver: under the recommended contract every included operating
  -- service is usable during the trial without a purchase (the admission
  -- policy answers 'trial'), and a paid period begins no earlier than the
  -- trial end. A purchase made inside the trial is therefore scheduled at
  -- the trial end with nothing waived; the waiver columns stay at zero and
  -- exist so a future waived line is recorded, never silently discounted.
  v_waivers := array_fill(0, ARRAY[v_line_count]);
  FOR v_i IN 1 .. v_line_count LOOP
    v_out := jsonb_set(v_out, ARRAY[(v_i - 1)::text, 'waiver'], to_jsonb(v_waivers[v_i]));
    v_out := jsonb_set(v_out, ARRAY[(v_i - 1)::text, 'net'], to_jsonb(v_grosses[v_i] - v_credits[v_i] - v_waivers[v_i]));
  END LOOP;

  v_basket := md5(p_scope_kind || ':' || p_scope_id::text || ':' || p_payer::text || ':' || COALESCE(p_sponsorship_id::text, '') || ':' || p_purchase_kind || ':' || v_out::text);
  v_ctx := md5(COALESCE(public.fn_ca_commerce_scope_owner(p_scope_kind, p_scope_id)::text, '') || ':' || public.fn_ca_commerce_catalog_version()
              || ':' || COALESCE(v_trial.trial_end::text, '') || ':' || COALESCE((SELECT string_agg(e.id::text, ',' ORDER BY e.id) FROM public.ca_commerce_entitlements e WHERE e.scope_kind = p_scope_kind AND e.scope_id = p_scope_id AND e.state = 'effective' AND (e.ends_at IS NULL OR e.ends_at > v_now)), ''));

  INSERT INTO public.ca_commerce_quotes (actor_id, payer_id, scope_kind, scope_id, sponsorship_id, lines, basket_hash, context_hash, catalog_version,
    gross, credits, comparison_adjustment, trial_waiver, net, trial_id, renewal_max_diamonds, expires_at)
  VALUES (p_actor, p_payer, p_scope_kind, p_scope_id, p_sponsorship_id, v_out, v_basket, v_ctx, public.fn_ca_commerce_catalog_version(),
    v_total_gross, v_total_credit, 0, v_total_waiver, v_total_gross - v_total_credit - v_total_waiver, v_trial.id, p_renewal_max, v_now + v_settings.quote_ttl)
  RETURNING * INTO v_quote;

  RETURN jsonb_build_object('success', true, 'quote_id', v_quote.id, 'expires_at', v_quote.expires_at,
    'catalog_version', v_quote.catalog_version, 'payer_id', p_payer, 'sponsorship_id', p_sponsorship_id,
    'purchase_kind', p_purchase_kind, 'lines', v_out,
    'gross', v_quote.gross, 'credits', v_quote.credits, 'comparison_adjustment', 0, 'trial_waiver', v_quote.trial_waiver, 'net', v_quote.net,
    'nominal_cents', v_quote.net, 'trial_active', v_in_trial, 'trial_end', v_trial.trial_end,
    'available_balance', (SELECT COALESCE(p.diamonds, 0) FROM public.profiles p WHERE p.id = p_payer),
    'renewal_max_diamonds', p_renewal_max);
END $_$;


ALTER FUNCTION public.fn_ca_commerce_quote_impl(p_actor uuid, p_payer uuid, p_scope_kind text, p_scope_id uuid, p_lines jsonb, p_sponsorship_id uuid, p_renewal_max integer, p_purchase_kind text) OWNER TO postgres;

--
-- TOC entry 2820 (class 1259 OID 54285317)
-- Name: ca_commerce_purchases; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ca_commerce_purchases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    quote_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    payer_id uuid NOT NULL,
    request_key text NOT NULL,
    request_hash text NOT NULL,
    scope_kind text NOT NULL,
    scope_id uuid NOT NULL,
    sponsorship_id uuid,
    kind text DEFAULT 'purchase'::text NOT NULL,
    gross integer NOT NULL,
    net integer NOT NULL,
    trial_waiver integer DEFAULT 0 NOT NULL,
    lines jsonb NOT NULL,
    diamond_tx_id uuid,
    mint_op_id text,
    lot_allocation jsonb DEFAULT '[]'::jsonb NOT NULL,
    catalog_version text NOT NULL,
    policy_version text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    terms_version integer DEFAULT public.fn_ca_commerce_policy_version('service_terms'::text),
    CONSTRAINT ca_commerce_purchases_check CHECK (((net = 0) = (diamond_tx_id IS NULL))),
    CONSTRAINT ca_commerce_purchases_gross_check CHECK ((gross >= 0)),
    CONSTRAINT ca_commerce_purchases_kind_check CHECK ((kind = ANY (ARRAY['purchase'::text, 'renewal'::text, 'upgrade'::text]))),
    CONSTRAINT ca_commerce_purchases_net_check CHECK ((net >= 0)),
    CONSTRAINT ca_commerce_purchases_request_key_check CHECK (((length(request_key) >= 8) AND (length(request_key) <= 200))),
    CONSTRAINT ca_commerce_purchases_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['club'::text, 'union'::text]))),
    CONSTRAINT ca_commerce_purchases_trial_waiver_check CHECK ((trial_waiver >= 0))
);


ALTER TABLE public.ca_commerce_purchases OWNER TO postgres;

--
-- TOC entry 5760 (class 1255 OID 54285551)
-- Name: fn_ca_commerce_receipt_json(public.ca_commerce_purchases, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_receipt_json(p_purchase public.ca_commerce_purchases, p_replay boolean) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'success', true,
    'purchase_id', p_purchase.id,
    'quote_id', p_purchase.quote_id,
    'is_replay', p_replay,
    'original_total_diamonds', p_purchase.net,
    'original_gross_diamonds', p_purchase.gross,
    'trial_waiver', p_purchase.trial_waiver,
    'charged_this_attempt', CASE WHEN p_replay THEN 0 ELSE p_purchase.net END,
    'payer_id', p_purchase.payer_id,
    'scope_kind', p_purchase.scope_kind, 'scope_id', p_purchase.scope_id,
    'sponsorship_id', p_purchase.sponsorship_id,
    'kind', p_purchase.kind,
    'diamond_tx_id', p_purchase.diamond_tx_id,
    'mint_op_id', p_purchase.mint_op_id,
    'catalog_version', p_purchase.catalog_version,
    'delivery_status', 'delivered',
    -- The present state of the rights this receipt granted (R2 3.3): a
    -- refunded or superseded right is never reported as still effective.
    'entitlement_status', COALESCE((SELECT CASE WHEN count(DISTINCT e.state) = 1 THEN min(e.state) ELSE 'mixed' END
                                      FROM public.ca_commerce_entitlements e WHERE e.purchase_id = p_purchase.id), 'effective'),
    'committed_at', p_purchase.created_at,
    'lines', p_purchase.lines
  )
$$;


ALTER FUNCTION public.fn_ca_commerce_receipt_json(p_purchase public.ca_commerce_purchases, p_replay boolean) OWNER TO postgres;

--
-- TOC entry 5903 (class 1255 OID 54285557)
-- Name: fn_ca_commerce_receipts(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_receipts(p_scope_kind text DEFAULT NULL::text, p_scope_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(jsonb_agg(public.fn_ca_commerce_receipt_json(p, true) || jsonb_build_object(
           'refunds', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', r.id, 'line_index', r.line_index, 'gross', r.gross,
                        'debt_settled', r.debt_settled, 'net_increase', r.net_increase, 'reason', r.reason, 'created_at', r.created_at))
                        FROM public.ca_commerce_refunds r WHERE r.purchase_id = p.id), '[]'::jsonb),
           'refund_requests', COALESCE((SELECT jsonb_agg(public.fn_ca_commerce_refund_request_json(q) ORDER BY q.created_at, q.id)
                        FROM public.ca_commerce_refund_requests q
                        WHERE q.purchase_id = p.id AND (q.payer_id = auth.uid() OR q.requested_by = auth.uid())), '[]'::jsonb),
           'rights', COALESCE((SELECT jsonb_agg(jsonb_build_object('entitlement_id', e.id, 'line_index', e.line_index, 'sku', e.sku,
                        'state', e.state, 'starts_at', e.starts_at, 'ends_at', e.ends_at,
                        'refundable', public.fn_ca_commerce_refundable(p.id, e.line_index),
                        'renewal', (SELECT jsonb_build_object('mandate_id', m.id, 'state', m.state, 'sku', m.sku, 'quantity', m.quantity,
                                       'max_diamonds', m.max_diamonds, 'due_at', m.due_at, 'sponsorship_id', m.sponsorship_id)
                                      FROM public.ca_commerce_renewal_mandates m WHERE m.entitlement_id = e.id AND m.payer_id = auth.uid()))
                        ORDER BY e.line_index, e.created_at)
                        FROM public.ca_commerce_entitlements e WHERE e.purchase_id = p.id), '[]'::jsonb))
           ORDER BY p.created_at DESC), '[]'::jsonb)
    FROM public.ca_commerce_purchases p
   WHERE (p.payer_id = auth.uid() OR p.actor_id = auth.uid())
     AND (p_scope_kind IS NULL OR (p.scope_kind = p_scope_kind AND p.scope_id = p_scope_id))
$$;


ALTER FUNCTION public.fn_ca_commerce_receipts(p_scope_kind text, p_scope_id uuid) OWNER TO postgres;

--
-- TOC entry 5120 (class 1255 OID 55344610)
-- Name: fn_ca_commerce_record_event_basis(text, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_record_event_basis(p_event_kind text, p_event_id uuid, p_scope_kind text, p_scope_id uuid, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_d jsonb;
BEGIN
  IF p_event_id IS NULL OR p_scope_id IS NULL THEN RETURN; END IF;
  v_d := public.fn_ca_commerce_admission_decide(p_scope_kind, p_scope_id, p_action);
  UPDATE public.accepted_event_operations a
     SET authorization_basis = jsonb_build_object(
           'operator_access', CASE WHEN COALESCE((v_d->>'enforced')::boolean, false) THEN 'commerce' ELSE 'commerce_shadow' END,
           'recorded_by', 'commerce_admission',
           'scope_kind', p_scope_kind,
           'scope_id', p_scope_id,
           'action', p_action,
           'would_allow', v_d->'would_allow',
           'reason', v_d->>'reason',
           'entitlement_id', v_d->'entitlement_id',
           'trial', COALESCE(v_d->'trial', 'false'::jsonb),
           'policy_version', (SELECT s.policy_version FROM public.ca_commerce_settings s WHERE s.id = 1),
           'accepted_basis', a.authorization_basis)
   WHERE a.event_kind = p_event_kind AND a.event_id = p_event_id
     AND a.authorization_basis->>'recorded_by' = 'acceptance_trigger';
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'ca_commerce event basis not recorded for % % (%): %', p_event_kind, p_event_id, SQLSTATE, SQLERRM;
END $$;


ALTER FUNCTION public.fn_ca_commerce_record_event_basis(p_event_kind text, p_event_id uuid, p_scope_kind text, p_scope_id uuid, p_action text) OWNER TO postgres;

--
-- TOC entry 3602 (class 1255 OID 54285567)
-- Name: fn_ca_commerce_refund(uuid, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_refund(p_purchase_id uuid, p_line_index integer, p_amount integer, p_reason text, p_request_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_p public.ca_commerce_purchases;
  v_line jsonb;
  v_line_net integer;
  v_returned integer;
  v_credited integer;
  v_existing public.ca_commerce_refunds;
  v_ref text;
  v_credit jsonb;
  v_tx public.diamond_transactions;
  v_mint public.ca_mint_ledger;
  v_refund public.ca_commerce_refunds;
  v_refund_id uuid;
  v_detail text;
  v_ent public.ca_commerce_entitlements;
  v_restore jsonb := '[]'::jsonb;
  v_left integer;
  v_lot record;
  v_take integer;
  v_debt integer;
  v_full boolean;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'staff_required');
  END IF;
  -- A refund credits the payer through add_diamonds_to_balance, and the
  -- profile wallet guard admits that write only from a service context or a
  -- named ledgered door. This door is not named there, so a staff member's
  -- browser session cannot complete a refund; say so in JSON before any
  -- work, instead of a raw 42501 from the guard mid-refund. Staff refunds go
  -- through a service-role route. Admitting this door in the guard is a
  -- permission change for the owner to make.
  -- The same test the guard applies, so this refuses exactly when it would.
  IF NOT public.fn_is_service_context() THEN
    RETURN jsonb_build_object('success', false, 'error', 'refund_requires_service_route');
  END IF;
  IF p_request_key IS NULL OR length(p_request_key) < 8 THEN
    RETURN jsonb_build_object('success', false, 'error', 'request_key_required');
  END IF;
  SELECT * INTO v_existing FROM public.ca_commerce_refunds WHERE request_key = p_request_key;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.purchase_id <> p_purchase_id OR v_existing.line_index <> p_line_index OR v_existing.gross <> p_amount THEN
      RETURN jsonb_build_object('success', false, 'error', 'request_key_reused');
    END IF;
    RETURN jsonb_build_object('success', true, 'is_replay', true, 'refund_id', v_existing.id, 'gross', v_existing.gross,
      'debt_settled', v_existing.debt_settled, 'net_increase', v_existing.net_increase, 'charged_this_attempt', 0);
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount_required');
  END IF;
  SELECT * INTO v_p FROM public.ca_commerce_purchases WHERE id = p_purchase_id;
  IF v_p.id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'purchase_not_found'); END IF;
  -- Serialize by original purchase (D40).
  PERFORM pg_advisory_xact_lock(hashtextextended('ca_commerce_refund:' || v_p.id::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('ca_commerce_scope:' || v_p.scope_kind || ':' || v_p.scope_id::text, 0));
  -- A concurrent request with the same key committed while this one waited
  -- for the lock: return its receipt instead of a key collision.
  SELECT * INTO v_existing FROM public.ca_commerce_refunds WHERE request_key = p_request_key;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.purchase_id <> p_purchase_id OR v_existing.line_index <> p_line_index OR v_existing.gross <> p_amount THEN
      RETURN jsonb_build_object('success', false, 'error', 'request_key_reused');
    END IF;
    RETURN jsonb_build_object('success', true, 'is_replay', true, 'refund_id', v_existing.id, 'gross', v_existing.gross,
      'debt_settled', v_existing.debt_settled, 'net_increase', v_existing.net_increase, 'charged_this_attempt', 0);
  END IF;
  v_line := (SELECT l FROM jsonb_array_elements(v_p.lines) l WHERE (l->>'index')::integer = p_line_index);
  IF v_line IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'line_not_found'); END IF;
  v_line_net := (v_line->>'net')::integer;
  SELECT COALESCE(SUM(r.gross), 0)::integer INTO v_returned FROM public.ca_commerce_refunds r WHERE r.purchase_id = v_p.id AND r.line_index = p_line_index;
  -- Unused value of this line already credited into an upgrade that
  -- replaced its right is spent: it cannot also come back as a refund (R2 6.4).
  SELECT COALESCE(SUM((l->>'credit')::integer), 0)::integer INTO v_credited
    FROM public.ca_commerce_entitlements e
    JOIN public.ca_commerce_entitlements n ON n.id = e.superseded_by
    JOIN public.ca_commerce_purchases u ON u.id = n.purchase_id
    CROSS JOIN LATERAL jsonb_array_elements(u.lines) l
   WHERE e.purchase_id = v_p.id AND e.line_index = p_line_index
     AND l->>'replaces_entitlement_id' = e.id::text;
  IF v_line_net = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'nothing_paid_on_this_line');
  END IF;
  IF p_amount > v_line_net - v_returned - v_credited THEN
    RETURN jsonb_build_object('success', false, 'error', 'exceeds_refundable', 'refundable', GREATEST(v_line_net - v_returned - v_credited, 0), 'credited_to_upgrade', v_credited);
  END IF;
  v_full := (v_returned + p_amount = v_line_net);
  v_refund_id := gen_random_uuid();
  v_ref := 'ca-commerce-refund:' || v_refund_id::text;
  -- The payer's wallet row first, as every canonical writer does.
  PERFORM 1 FROM public.profiles p WHERE p.id = v_p.payer_id FOR UPDATE;

  -- Exact-value door: 'refund' is in the multiplier exception list, is
  -- classified refund and registered as issuance by the existing origin rule.
  PERFORM public.fn_ca_authorize_funded_return('commerce',v_p.id,'diamonds',v_p.payer_id,p_amount,v_ref);
  v_credit := public.add_diamonds_to_balance(v_p.payer_id, p_amount, 'refund',
    'Club And Union Diamond Costs Refund: ' || left(p_reason, 120), v_ref);
  IF NOT COALESCE((v_credit->>'success')::boolean, false) THEN
    RAISE EXCEPTION 'CA_COMMERCE_REFUND_REFUSED' USING DETAIL = COALESCE(v_credit->>'error', 'unknown');
  END IF;
  IF COALESCE((v_credit->>'amount')::integer, -1) <> p_amount THEN
    RAISE EXCEPTION 'CA_COMMERCE_REFUND_NOT_EXACT' USING DETAIL = COALESCE(v_credit->>'amount', 'null');
  END IF;
  SELECT * INTO v_tx FROM public.diamond_transactions t WHERE t.user_id = v_p.payer_id AND t.reference_id = v_ref;
  IF v_tx.id IS NULL OR v_tx.amount <> p_amount OR v_tx.issuance_class <> 'refund' THEN
    RAISE EXCEPTION 'CA_COMMERCE_REFUND_JOURNAL_UNPROVED' USING DETAIL = v_ref;
  END IF;
  SELECT * INTO v_mint FROM public.ca_mint_ledger m WHERE m.diamond_tx_id = v_tx.id;
  IF v_mint.id IS NULL OR v_mint.action <> 'mint' OR v_mint.asset <> 'diamonds' OR v_mint.amount <> p_amount THEN
    RAISE EXCEPTION 'CA_COMMERCE_REFUND_REGISTER_UNPROVED' USING DETAIL = v_ref;
  END IF;
  v_debt := COALESCE((v_credit->>'debt_settled')::integer, 0);

  -- Restore operation-linked lot provenance, bounded by what this purchase
  -- consumed and by each lot's present consumed figure (D39, D65).
  v_left := p_amount;
  FOR v_lot IN SELECT (a->>'lot_id')::uuid AS lot_id, (a->>'consumed_delta')::integer AS delta FROM jsonb_array_elements(v_p.lot_allocation) a ORDER BY 1 LOOP
    EXIT WHEN v_left <= 0;
    SELECT LEAST(v_left, v_lot.delta - COALESCE((SELECT SUM((x->>'restored')::integer) FROM public.ca_commerce_refunds r, jsonb_array_elements(r.lot_restoration) x WHERE r.purchase_id = v_p.id AND x->>'lot_id' = v_lot.lot_id::text), 0), l.consumed)
      INTO v_take FROM public.diamond_purchase_lots l WHERE l.id = v_lot.lot_id FOR UPDATE;
    IF v_take IS NULL OR v_take <= 0 THEN CONTINUE; END IF;
    UPDATE public.diamond_purchase_lots SET consumed = consumed - v_take WHERE id = v_lot.lot_id;
    v_restore := v_restore || jsonb_build_object('lot_id', v_lot.lot_id, 'restored', v_take);
    v_left := v_left - v_take;
  END LOOP;

  INSERT INTO public.ca_commerce_refunds (id, purchase_id, line_index, request_key, requested_by, reason, payer_id, gross, debt_settled, net_increase, diamond_tx_id, mint_op_id, lot_restoration, revoked_entitlement)
  VALUES (v_refund_id, v_p.id, p_line_index, p_request_key, COALESCE(v_actor, v_p.payer_id), p_reason, v_p.payer_id, p_amount, v_debt, p_amount - v_debt, v_tx.id, v_mint.op_id, v_restore, v_full)
  RETURNING * INTO v_refund;

  IF v_full THEN
    UPDATE public.ca_commerce_entitlements SET state = 'revoked', updated_at = now() WHERE purchase_id = v_p.id AND line_index = p_line_index AND state = 'effective' RETURNING * INTO v_ent;
    UPDATE public.ca_commerce_renewal_mandates SET state = 'cancelled', cancelled_at = now(), updated_at = now() WHERE entitlement_id = v_ent.id AND state = 'authorized';
  END IF;
  IF v_p.sponsorship_id IS NOT NULL THEN
    UPDATE public.ca_commerce_sponsorships SET committed = GREATEST(committed - p_amount, 0) WHERE id = v_p.sponsorship_id;
  END IF;

  INSERT INTO public.ca_commerce_events (kind, actor_id, scope_kind, scope_id, reference_id, detail)
  VALUES ('refund_committed', v_actor, v_p.scope_kind, v_p.scope_id, v_refund.id, jsonb_build_object('purchase_id', v_p.id, 'line_index', p_line_index, 'gross', p_amount, 'debt_settled', v_debt, 'net_increase', p_amount - v_debt, 'full', v_full));
  PERFORM public.fn_ca_commerce_notice(v_p.payer_id, 'refund:' || v_refund.id::text, 'club_commerce_refund',
    'Refund: ' || p_amount::text || ' Diamonds',
    'Refund: ' || p_amount::text || ' Diamonds; Applied To Existing Debt: ' || v_debt::text || '; Added To Available Balance: ' || (p_amount - v_debt)::text || '.',
    '/hub/club-arena/' || v_p.scope_kind || 's/' || v_p.scope_id::text || '/diamond-costs', jsonb_build_object('refund_id', v_refund.id));

  RETURN jsonb_build_object('success', true, 'is_replay', false, 'refund_id', v_refund.id, 'gross', p_amount, 'debt_settled', v_debt,
    'net_increase', p_amount - v_debt, 'diamond_tx_id', v_tx.id, 'mint_op_id', v_mint.op_id, 'lot_restoration', v_restore, 'entitlement_revoked', v_full);
EXCEPTION
  WHEN OTHERS THEN
    -- Every write above rolled back, so nothing was credited and nothing is
    -- credited twice on a retry. A refund the wallet cannot receive yet
    -- (balance headroom, D64) is refused whole; the same request key can be
    -- retried once the wallet has room. The owed amount remains provable
    -- from the original receipt and the absence of a refund row.
    GET STACKED DIAGNOSTICS v_detail = PG_EXCEPTION_DETAIL;
    IF SQLERRM LIKE 'CA_COMMERCE_%' THEN
      RETURN jsonb_build_object('success', false, 'error', lower(replace(SQLERRM, 'CA_COMMERCE_', '')), 'detail', v_detail, 'retry_same_request_key', true);
    END IF;
    IF SQLSTATE = '23514' THEN
      RETURN jsonb_build_object('success', false, 'error', 'wallet_cannot_receive_yet', 'detail', SQLERRM, 'retry_same_request_key', true);
    END IF;
    RAISE;
END $$;


ALTER FUNCTION public.fn_ca_commerce_refund(p_purchase_id uuid, p_line_index integer, p_amount integer, p_reason text, p_request_key text) OWNER TO postgres;

--
-- TOC entry 3667 (class 1255 OID 55343772)
-- Name: fn_ca_commerce_refund_decide(uuid, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_refund_decide(p_request_id uuid, p_approve boolean, p_amount integer DEFAULT NULL::integer, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_r public.ca_commerce_refund_requests;
  v_amount integer;
  v_refundable integer;
  v_title text;
  v_url text;
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication_required');
  END IF;
  IF NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'staff_required');
  END IF;
  IF p_approve IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'decision_required');
  END IF;
  IF p_note IS NOT NULL AND length(p_note) > 2000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'note_too_long');
  END IF;
  SELECT * INTO v_r FROM public.ca_commerce_refund_requests WHERE id = p_request_id FOR UPDATE;
  IF v_r.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'request_not_found');
  END IF;
  IF v_r.requested_by = v_actor OR v_r.payer_id = v_actor THEN
    RETURN jsonb_build_object('success', false, 'error', 'cannot_decide_own_request');
  END IF;
  IF v_r.state <> 'requested' THEN
    IF (p_approve AND v_r.state IN ('approved','owed','refunded','failed')) OR (NOT p_approve AND v_r.state = 'declined') THEN
      RETURN jsonb_build_object('success', true, 'is_replay', true, 'request', public.fn_ca_commerce_refund_request_json(v_r));
    END IF;
    RETURN jsonb_build_object('success', false, 'error', 'already_decided', 'request', public.fn_ca_commerce_refund_request_json(v_r));
  END IF;
  v_title := COALESCE((SELECT l->>'title' FROM public.ca_commerce_purchases p, jsonb_array_elements(p.lines) l
                        WHERE p.id = v_r.purchase_id AND (l->>'index')::integer = v_r.line_index), 'This Service');
  v_url := '/hub/club-arena/' || v_r.scope_kind || 's/' || v_r.scope_id::text || '/diamond-costs';
  IF p_approve THEN
    v_amount := COALESCE(p_amount, v_r.policy_amount);
    IF v_amount IS NULL OR v_amount <= 0 THEN
      RETURN jsonb_build_object('success', false, 'error', 'amount_required');
    END IF;
    v_refundable := public.fn_ca_commerce_refundable(v_r.purchase_id, v_r.line_index);
    IF v_amount > v_refundable THEN
      RETURN jsonb_build_object('success', false, 'error', 'exceeds_refundable', 'refundable', v_refundable);
    END IF;
    UPDATE public.ca_commerce_refund_requests
       SET state = 'approved', approved_amount = v_amount, decided_by = v_actor, decided_at = now(), decision_note = NULLIF(btrim(p_note), ''), updated_at = now()
     WHERE id = v_r.id RETURNING * INTO v_r;
    PERFORM public.fn_ca_commerce_notice(v_r.payer_id, 'refund-decision:' || v_r.id::text, 'club_commerce_refund_decision',
      'Refund Approved',
      'Your Refund Of ' || to_char(v_amount, 'FM999,999,999,990') || ' Diamonds For ' || v_title || ' Was Approved And Is Being Returned To Your Diamond Balance.',
      v_url, jsonb_build_object('request_id', v_r.id, 'approved_amount', v_amount));
  ELSE
    IF p_note IS NULL OR length(btrim(p_note)) < 5 THEN
      RETURN jsonb_build_object('success', false, 'error', 'note_required');
    END IF;
    UPDATE public.ca_commerce_refund_requests
       SET state = 'declined', decided_by = v_actor, decided_at = now(), decision_note = btrim(p_note), updated_at = now()
     WHERE id = v_r.id RETURNING * INTO v_r;
    PERFORM public.fn_ca_commerce_notice(v_r.payer_id, 'refund-decision:' || v_r.id::text, 'club_commerce_refund_decision',
      'Refund Request Declined',
      'Your Refund Request For ' || v_title || ' Was Declined. Note From Platform Staff: '
        || initcap(rtrim(replace(btrim(p_note), chr(8212), '-'), '.')) || '.',
      v_url, jsonb_build_object('request_id', v_r.id));
  END IF;
  INSERT INTO public.ca_commerce_events (kind, actor_id, scope_kind, scope_id, reference_id, detail)
  VALUES ('refund_request_' || v_r.state, v_actor, v_r.scope_kind, v_r.scope_id, v_r.id,
          jsonb_build_object('purchase_id', v_r.purchase_id, 'line_index', v_r.line_index, 'approved_amount', v_r.approved_amount,
                             'policy_amount', v_r.policy_amount, 'note', v_r.decision_note));
  RETURN jsonb_build_object('success', true, 'is_replay', false, 'request', public.fn_ca_commerce_refund_request_json(v_r));
END $$;


ALTER FUNCTION public.fn_ca_commerce_refund_decide(p_request_id uuid, p_approve boolean, p_amount integer, p_note text) OWNER TO postgres;

--
-- TOC entry 6654 (class 1255 OID 55343768)
-- Name: fn_ca_commerce_refund_policy(uuid, integer, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_refund_policy(p_purchase_id uuid, p_line_index integer, p_reason text, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_p public.ca_commerce_purchases;
  v_line jsonb;
  v_net integer;
  v_refundable integer;
  v_ent public.ca_commerce_entitlements;
  v_unused integer := 0;
  v_period_days numeric;
  v_amount integer;
  v_detail jsonb;
BEGIN
  SELECT * INTO v_p FROM public.ca_commerce_purchases WHERE id = p_purchase_id;
  IF v_p.id IS NULL THEN RETURN jsonb_build_object('eligible', false, 'error', 'purchase_not_found'); END IF;
  v_line := (SELECT l FROM jsonb_array_elements(v_p.lines) l WHERE (l->>'index')::integer = p_line_index);
  IF v_line IS NULL THEN RETURN jsonb_build_object('eligible', false, 'error', 'line_not_found'); END IF;
  v_net := (v_line->>'net')::integer;
  -- (c) The free month is never charged: a waived or zero line has no principal.
  IF COALESCE(v_net, 0) = 0 THEN RETURN jsonb_build_object('eligible', false, 'error', 'nothing_paid_on_this_line'); END IF;
  v_refundable := public.fn_ca_commerce_refundable(p_purchase_id, p_line_index);
  IF v_refundable <= 0 THEN
    RETURN jsonb_build_object('eligible', false, 'error', 'nothing_left_to_refund', 'line_net', v_net);
  END IF;
  SELECT * INTO v_ent FROM public.ca_commerce_entitlements e
   WHERE e.purchase_id = p_purchase_id AND e.line_index = p_line_index ORDER BY e.created_at LIMIT 1;
  v_detail := jsonb_build_object('line_net', v_net, 'refundable', v_refundable, 'purchased_at', v_p.created_at,
    'right_state', v_ent.state, 'right_starts_at', v_ent.starts_at, 'right_ends_at', v_ent.ends_at,
    'right_started', v_ent.starts_at IS NOT NULL AND v_ent.starts_at <= p_at, 'sponsored', v_p.sponsorship_id IS NOT NULL);

  IF p_reason = 'purchase_in_error' THEN
    -- (a) In full within 24 hours, if no newer purchase replaced it. Whether
    -- any right was used is the staff member's finding; the request carries
    -- right_started so they can see it.
    IF p_at >= v_p.created_at + interval '24 hours' THEN
      RETURN jsonb_build_object('eligible', false, 'error', 'error_window_passed', 'purchased_at', v_p.created_at);
    END IF;
    IF v_ent.superseded_by IS NOT NULL OR v_ent.state = 'superseded' THEN
      RETURN jsonb_build_object('eligible', false, 'error', 'replaced_by_newer_purchase');
    END IF;
    RETURN jsonb_build_object('eligible', true, 'basis', 'error_full', 'amount', v_refundable) || v_detail;
  END IF;

  -- (b) The unused whole days of a paid period, pro rata to what this line
  -- paid, when the scope closed, the service was unavailable or staff find a
  -- platform defect. A superseded right ended at its upgrade: its value was
  -- credited forward and it has no unused days of its own.
  IF v_ent.id IS NULL OR v_ent.ends_at IS NULL THEN
    RETURN jsonb_build_object('eligible', false, 'error', 'not_a_period_right');
  END IF;
  v_period_days := extract(epoch FROM (v_ent.ends_at - v_ent.starts_at)) / 86400.0;
  IF v_ent.state = 'effective' AND v_ent.ends_at > p_at THEN
    v_unused := floor(extract(epoch FROM (v_ent.ends_at - GREATEST(p_at, v_ent.starts_at))) / 86400.0)::integer;
  END IF;
  v_amount := LEAST(floor(v_net::numeric * v_unused / v_period_days)::integer, v_refundable);
  IF v_amount <= 0 THEN
    RETURN jsonb_build_object('eligible', false, 'error', 'no_unused_whole_days', 'unused_days', v_unused);
  END IF;
  RETURN jsonb_build_object('eligible', true, 'basis', 'pro_rata_unused_days', 'amount', v_amount,
    'unused_days', v_unused, 'period_days', round(v_period_days, 4)) || v_detail;
END $$;


ALTER FUNCTION public.fn_ca_commerce_refund_policy(p_purchase_id uuid, p_line_index integer, p_reason text, p_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 4022 (class 1255 OID 55343773)
-- Name: fn_ca_commerce_refund_queue(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_refund_queue(p_state text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'staff_required');
  END IF;
  RETURN jsonb_build_object('success', true, 'requests', COALESCE((
    SELECT jsonb_agg(public.fn_ca_commerce_refund_request_json(q) ORDER BY q.created_at, q.id)
      FROM (SELECT * FROM public.ca_commerce_refund_requests r
             WHERE p_state IS NULL OR r.state = p_state
             ORDER BY r.created_at, r.id LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 100), 500))) q), '[]'::jsonb));
END $$;


ALTER FUNCTION public.fn_ca_commerce_refund_queue(p_state text, p_limit integer) OWNER TO postgres;

--
-- TOC entry 5372 (class 1255 OID 55343770)
-- Name: fn_ca_commerce_refund_request(uuid, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_refund_request(p_purchase_id uuid, p_line_index integer, p_reason text, p_request_key text, p_details text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_p public.ca_commerce_purchases;
  v_existing public.ca_commerce_refund_requests;
  v_open public.ca_commerce_refund_requests;
  v_policy public.ca_commerce_policies;
  v_calc jsonb;
  v_r public.ca_commerce_refund_requests;
  v_title text;
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication_required');
  END IF;
  IF p_request_key IS NULL OR length(p_request_key) < 8 OR length(p_request_key) > 200 THEN
    RETURN jsonb_build_object('success', false, 'error', 'request_key_required');
  END IF;
  IF p_reason IS NULL OR p_reason NOT IN ('purchase_in_error','scope_closed','service_unavailable','platform_defect') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_reason',
      'allowed', jsonb_build_array('purchase_in_error','scope_closed','service_unavailable','platform_defect'));
  END IF;
  IF p_details IS NOT NULL AND length(p_details) > 2000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'details_too_long');
  END IF;
  IF p_purchase_id IS NULL OR p_line_index IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'purchase_not_found');
  END IF;
  -- Request identity: same key and payload replays; same key, other payload refuses.
  SELECT * INTO v_existing FROM public.ca_commerce_refund_requests WHERE requested_by = v_actor AND request_key = p_request_key;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.purchase_id <> p_purchase_id OR v_existing.line_index <> p_line_index OR v_existing.reason_code <> p_reason THEN
      RETURN jsonb_build_object('success', false, 'error', 'request_key_reused');
    END IF;
    RETURN jsonb_build_object('success', true, 'is_replay', true, 'request', public.fn_ca_commerce_refund_request_json(v_existing));
  END IF;
  SELECT * INTO v_p FROM public.ca_commerce_purchases WHERE id = p_purchase_id;
  IF v_p.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'purchase_not_found');
  END IF;
  -- Only the diamonds' owner asks for them back; a refund returns to the
  -- original payer, never to whoever holds the scope now (R2 5.2).
  IF v_p.payer_id <> v_actor THEN
    RETURN jsonb_build_object('success', false, 'error', 'payer_required');
  END IF;
  -- The same lock the refund core takes for this purchase: a request cannot
  -- interleave with a refund of the same purchase being executed.
  PERFORM pg_advisory_xact_lock(hashtextextended('ca_commerce_refund:' || v_p.id::text, 0));
  SELECT * INTO v_existing FROM public.ca_commerce_refund_requests WHERE requested_by = v_actor AND request_key = p_request_key;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.purchase_id <> p_purchase_id OR v_existing.line_index <> p_line_index OR v_existing.reason_code <> p_reason THEN
      RETURN jsonb_build_object('success', false, 'error', 'request_key_reused');
    END IF;
    RETURN jsonb_build_object('success', true, 'is_replay', true, 'request', public.fn_ca_commerce_refund_request_json(v_existing));
  END IF;
  SELECT * INTO v_open FROM public.ca_commerce_refund_requests
   WHERE purchase_id = p_purchase_id AND line_index = p_line_index AND state IN ('requested','approved','owed');
  IF v_open.id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'request_already_open', 'request', public.fn_ca_commerce_refund_request_json(v_open));
  END IF;
  SELECT * INTO v_policy FROM public.ca_commerce_policies
   WHERE kind = 'refund' AND version = public.fn_ca_commerce_policy_version('refund');
  v_calc := public.fn_ca_commerce_refund_policy(p_purchase_id, p_line_index, p_reason, now());
  IF NOT COALESCE((v_calc->>'eligible')::boolean, false) THEN
    RETURN jsonb_build_object('success', false, 'error', v_calc->>'error', 'policy_version', v_policy.version) || (v_calc - 'eligible' - 'error');
  END IF;
  INSERT INTO public.ca_commerce_refund_requests (purchase_id, line_index, scope_kind, scope_id, payer_id, requested_by, request_key,
    reason_code, details, policy_id, policy_version, policy_basis, policy_amount, policy_detail)
  VALUES (v_p.id, p_line_index, v_p.scope_kind, v_p.scope_id, v_p.payer_id, v_actor, p_request_key,
    p_reason, NULLIF(btrim(p_details), ''), v_policy.id, v_policy.version, v_calc->>'basis', (v_calc->>'amount')::integer,
    v_calc - 'eligible' - 'basis' - 'amount')
  RETURNING * INTO v_r;
  INSERT INTO public.ca_commerce_events (kind, actor_id, scope_kind, scope_id, reference_id, detail)
  VALUES ('refund_requested', v_actor, v_r.scope_kind, v_r.scope_id, v_r.id,
          jsonb_build_object('purchase_id', v_r.purchase_id, 'line_index', v_r.line_index, 'reason_code', v_r.reason_code,
                             'policy_version', v_r.policy_version, 'policy_amount', v_r.policy_amount, 'basis', v_r.policy_basis));
  v_title := COALESCE((SELECT l->>'title' FROM jsonb_array_elements(v_p.lines) l WHERE (l->>'index')::integer = p_line_index), 'This Service');
  PERFORM public.fn_ca_commerce_notice(v_r.payer_id, 'refund-request:' || v_r.id::text, 'club_commerce_refund_request',
    'Refund Request Received',
    'Your Refund Request For ' || v_title || ' Is With Platform Staff. Under Refund Policy Version ' || v_r.policy_version::text
      || ' The Amount Is ' || to_char(v_r.policy_amount, 'FM999,999,999,990') || ' Diamonds.',
    '/hub/club-arena/' || v_r.scope_kind || 's/' || v_r.scope_id::text || '/diamond-costs',
    jsonb_build_object('request_id', v_r.id, 'purchase_id', v_r.purchase_id, 'policy_amount', v_r.policy_amount));
  RETURN jsonb_build_object('success', true, 'is_replay', false, 'request', public.fn_ca_commerce_refund_request_json(v_r));
END $$;


ALTER FUNCTION public.fn_ca_commerce_refund_request(p_purchase_id uuid, p_line_index integer, p_reason text, p_request_key text, p_details text) OWNER TO postgres;

--
-- TOC entry 2842 (class 1259 OID 55343689)
-- Name: ca_commerce_refund_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ca_commerce_refund_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    purchase_id uuid NOT NULL,
    line_index integer NOT NULL,
    scope_kind text NOT NULL,
    scope_id uuid NOT NULL,
    payer_id uuid NOT NULL,
    requested_by uuid NOT NULL,
    request_key text NOT NULL,
    reason_code text NOT NULL,
    details text,
    policy_id uuid NOT NULL,
    policy_version integer NOT NULL,
    policy_basis text NOT NULL,
    policy_amount integer NOT NULL,
    policy_detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    state text DEFAULT 'requested'::text NOT NULL,
    approved_amount integer,
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_note text,
    lease_token uuid,
    lease_until timestamp with time zone,
    attempts integer DEFAULT 0 NOT NULL,
    owed_reason text,
    last_error text,
    refund_id uuid,
    executed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ca_commerce_refund_requests_approved_amount_check CHECK (((approved_amount IS NULL) OR (approved_amount > 0))),
    CONSTRAINT ca_commerce_refund_requests_check CHECK (((state = ANY (ARRAY['approved'::text, 'owed'::text, 'refunded'::text, 'failed'::text])) = (approved_amount IS NOT NULL))),
    CONSTRAINT ca_commerce_refund_requests_check1 CHECK (((state = 'requested'::text) = (decided_at IS NULL))),
    CONSTRAINT ca_commerce_refund_requests_check2 CHECK (((state = 'refunded'::text) = (refund_id IS NOT NULL))),
    CONSTRAINT ca_commerce_refund_requests_check3 CHECK (((state <> 'owed'::text) OR (owed_reason IS NOT NULL))),
    CONSTRAINT ca_commerce_refund_requests_details_check CHECK (((details IS NULL) OR (length(details) <= 2000))),
    CONSTRAINT ca_commerce_refund_requests_line_index_check CHECK ((line_index >= 0)),
    CONSTRAINT ca_commerce_refund_requests_policy_amount_check CHECK ((policy_amount > 0)),
    CONSTRAINT ca_commerce_refund_requests_policy_basis_check CHECK ((policy_basis = ANY (ARRAY['error_full'::text, 'pro_rata_unused_days'::text]))),
    CONSTRAINT ca_commerce_refund_requests_reason_code_check CHECK ((reason_code = ANY (ARRAY['purchase_in_error'::text, 'scope_closed'::text, 'service_unavailable'::text, 'platform_defect'::text]))),
    CONSTRAINT ca_commerce_refund_requests_request_key_check CHECK (((length(request_key) >= 8) AND (length(request_key) <= 200))),
    CONSTRAINT ca_commerce_refund_requests_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['club'::text, 'union'::text]))),
    CONSTRAINT ca_commerce_refund_requests_state_check CHECK ((state = ANY (ARRAY['requested'::text, 'approved'::text, 'declined'::text, 'owed'::text, 'refunded'::text, 'failed'::text])))
);


ALTER TABLE public.ca_commerce_refund_requests OWNER TO postgres;

--
-- TOC entry 3683 (class 1255 OID 55343769)
-- Name: fn_ca_commerce_refund_request_json(public.ca_commerce_refund_requests); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_refund_request_json(p_r public.ca_commerce_refund_requests) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'request_id', p_r.id, 'purchase_id', p_r.purchase_id, 'line_index', p_r.line_index,
    'scope_kind', p_r.scope_kind, 'scope_id', p_r.scope_id, 'payer_id', p_r.payer_id, 'requested_by', p_r.requested_by,
    'reason_code', p_r.reason_code, 'details', p_r.details,
    'policy_version', p_r.policy_version, 'policy_basis', p_r.policy_basis, 'policy_amount', p_r.policy_amount, 'policy_detail', p_r.policy_detail,
    'state', p_r.state, 'approved_amount', p_r.approved_amount,
    'pending_amount', CASE WHEN p_r.state IN ('requested','approved','owed') THEN COALESCE(p_r.approved_amount, p_r.policy_amount) ELSE 0 END,
    'decided_at', p_r.decided_at, 'decision_note', p_r.decision_note,
    'owed_reason', p_r.owed_reason, 'last_error', p_r.last_error, 'attempts', p_r.attempts,
    'refund_id', p_r.refund_id, 'executed_at', p_r.executed_at,
    'created_at', p_r.created_at, 'updated_at', p_r.updated_at)
$$;


ALTER FUNCTION public.fn_ca_commerce_refund_request_json(p_r public.ca_commerce_refund_requests) OWNER TO postgres;

--
-- TOC entry 4768 (class 1255 OID 55343767)
-- Name: fn_ca_commerce_refundable(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_refundable(p_purchase_id uuid, p_line_index integer) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT GREATEST(
    COALESCE((SELECT (l->>'net')::integer FROM public.ca_commerce_purchases p, jsonb_array_elements(p.lines) l
               WHERE p.id = p_purchase_id AND (l->>'index')::integer = p_line_index), 0)
    - COALESCE((SELECT SUM(r.gross) FROM public.ca_commerce_refunds r WHERE r.purchase_id = p_purchase_id AND r.line_index = p_line_index), 0)
    - COALESCE((SELECT SUM((l->>'credit')::integer)
                  FROM public.ca_commerce_entitlements e
                  JOIN public.ca_commerce_entitlements n ON n.id = e.superseded_by
                  JOIN public.ca_commerce_purchases u ON u.id = n.purchase_id
                  CROSS JOIN LATERAL jsonb_array_elements(u.lines) l
                 WHERE e.purchase_id = p_purchase_id AND e.line_index = p_line_index
                   AND l->>'replaces_entitlement_id' = e.id::text), 0),
    0)::integer
$$;


ALTER FUNCTION public.fn_ca_commerce_refundable(p_purchase_id uuid, p_line_index integer) OWNER TO postgres;

--
-- TOC entry 6646 (class 1255 OID 54285529)
-- Name: fn_ca_commerce_roster_count(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_roster_count(p_club_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COUNT(DISTINCT m.user_id)::integer FROM public.club_members m
   WHERE m.club_id = p_club_id AND COALESCE(m.status, 'active') IN ('active','approved')
     AND COALESCE(m.membership_lifecycle_status, 'active') = 'active'
$$;


ALTER FUNCTION public.fn_ca_commerce_roster_count(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 7352 (class 1255 OID 54285527)
-- Name: fn_ca_commerce_scope_owner(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_scope_owner(p_scope_kind text, p_scope_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE p_scope_kind
    WHEN 'club' THEN (SELECT c.owner_id FROM public.clubs c WHERE c.id = p_scope_id)
    WHEN 'union' THEN (SELECT u.owner_id FROM public.unions u WHERE u.id = p_scope_id)
  END
$$;


ALTER FUNCTION public.fn_ca_commerce_scope_owner(p_scope_kind text, p_scope_id uuid) OWNER TO postgres;

--
-- TOC entry 4827 (class 1255 OID 54285528)
-- Name: fn_ca_commerce_scope_role(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_scope_role(p_scope_kind text, p_scope_id uuid, p_user_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_owner uuid;
BEGIN
  IF p_user_id IS NULL THEN RETURN 'none'; END IF;
  v_owner := public.fn_ca_commerce_scope_owner(p_scope_kind, p_scope_id);
  IF v_owner IS NULL THEN RETURN 'none'; END IF;
  IF v_owner = p_user_id THEN RETURN 'owner'; END IF;
  IF p_scope_kind = 'club' AND EXISTS (
       SELECT 1 FROM public.club_members m
        WHERE m.club_id = p_scope_id AND m.user_id = p_user_id
          AND COALESCE(m.status, 'active') IN ('active','approved') AND COALESCE(m.membership_lifecycle_status, 'active') = 'active'
          AND m.role IN ('owner','co_owner','admin')) THEN
    RETURN 'admin';
  END IF;
  IF p_scope_kind = 'union' AND EXISTS (
       SELECT 1 FROM public.union_admins a WHERE a.union_id = p_scope_id AND a.user_id = p_user_id) THEN
    RETURN 'admin';
  END IF;
  RETURN 'none';
END $$;


ALTER FUNCTION public.fn_ca_commerce_scope_role(p_scope_kind text, p_scope_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 6149 (class 1255 OID 54285545)
-- Name: fn_ca_commerce_scope_status(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_scope_status(p_scope_kind text, p_scope_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_role text;
  v_trial public.ca_commerce_trials;
  v_owner uuid;
  v_settings public.ca_commerce_settings;
  v_staff boolean;
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication_required');
  END IF;
  v_role := public.fn_ca_commerce_scope_role(p_scope_kind, p_scope_id, v_actor);
  v_staff := public.fn_is_platform_admin();
  IF v_role = 'none' AND NOT v_staff THEN
    RETURN jsonb_build_object('success', false, 'error', 'access_denied');
  END IF;
  v_owner := public.fn_ca_commerce_scope_owner(p_scope_kind, p_scope_id);
  SELECT * INTO v_trial FROM public.fn_ca_commerce_scope_trial(p_scope_kind, p_scope_id);
  SELECT * INTO v_settings FROM public.ca_commerce_settings WHERE id = 1;
  RETURN jsonb_build_object(
    'success', true,
    'server_time', now(),
    'role', v_role,
    'scope_kind', p_scope_kind, 'scope_id', p_scope_id,
    'owner_id', v_owner,
    'policy_version', v_settings.policy_version,
    'checkout_enabled', v_settings.checkout_enabled,
    'admission_enforced_from', v_settings.admission_enforced_from,
    'roster_count', CASE WHEN p_scope_kind = 'club' THEN public.fn_ca_commerce_roster_count(p_scope_id) END,
    'covered_club_count', CASE WHEN p_scope_kind = 'union' THEN public.fn_ca_commerce_covered_club_count(p_scope_id) END,
    -- The clubs this union covers, so a sponsor can see which need capacity
    -- and buy it for them (R2 section 5). Same membership rule as the count.
    'covered_clubs', CASE WHEN p_scope_kind = 'union' THEN COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'club_id', c.id, 'name', c.name,
        'roster_count', public.fn_ca_commerce_roster_count(c.id),
        'trial_active', public.fn_ca_commerce_in_trial('club', c.id),
        'capacity', (SELECT jsonb_build_object('entitlement_id', e.id, 'sku', e.sku, 'capacity', e.capacity, 'ends_at', e.ends_at, 'source', e.source,
                                               'renewal', (SELECT jsonb_build_object('mandate_id', m.id, 'state', m.state, 'max_diamonds', m.max_diamonds, 'due_at', m.due_at)
                                                             FROM public.ca_commerce_renewal_mandates m WHERE m.entitlement_id = e.id AND m.payer_id = v_actor))
                       FROM public.ca_commerce_entitlements e
                      WHERE e.scope_kind = 'club' AND e.scope_id = c.id AND e.kind = 'capacity' AND e.state = 'effective'
                        AND e.starts_at <= now() AND (e.ends_at IS NULL OR e.ends_at > now())
                      ORDER BY e.capacity DESC NULLS LAST, e.ends_at DESC NULLS FIRST LIMIT 1)
      ) ORDER BY c.name, c.id)
      FROM public.union_clubs uc JOIN public.clubs c ON c.id = uc.club_id
      WHERE uc.union_id = p_scope_id AND COALESCE(c.lifecycle_status, 'active') <> 'retired'), '[]'::jsonb) END,
    'trial', CASE WHEN v_trial.id IS NULL THEN NULL ELSE jsonb_build_object(
      'trial_id', v_trial.id, 'trial_start', v_trial.trial_start, 'trial_end', v_trial.trial_end,
      'cohort', v_trial.cohort, 'active', now() >= v_trial.trial_start AND now() < v_trial.trial_end) END,
    'entitlements', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', e.id, 'sku', e.sku, 'kind', e.kind, 'capacity', e.capacity, 'quantity', e.quantity,
        'starts_at', e.starts_at, 'ends_at', e.ends_at, 'source', e.source, 'purchase_id', e.purchase_id,
        'net_paid', e.net_paid, 'value_basis', e.value_basis, 'revision', e.revision,
        'active', now() >= e.starts_at AND (e.ends_at IS NULL OR now() < e.ends_at),
        'scheduled', now() < e.starts_at,
        'renewal', (SELECT jsonb_build_object('mandate_id', m.id, 'state', m.state, 'sku', m.sku, 'quantity', m.quantity, 'max_diamonds', m.max_diamonds,
                       'due_at', m.due_at, 'payer_id', m.payer_id, 'last_result', m.last_result,
                       'sponsorship_id', m.sponsorship_id, 'terms_version', m.terms_version, 'ceiling_text_version', m.ceiling_text_version,
                       'accepted_ceiling_text', CASE WHEN m.ceiling_text_version IS NULL THEN NULL ELSE public.fn_ca_commerce_ceiling_text(
                          m.ceiling_text_version, m.sku, m.quantity, m.max_diamonds, m.sponsorship_id IS NOT NULL) END)
                      FROM public.ca_commerce_renewal_mandates m WHERE m.entitlement_id = e.id)
      ) ORDER BY e.starts_at DESC)
      FROM public.ca_commerce_entitlements e
      WHERE e.scope_kind = p_scope_kind AND e.scope_id = p_scope_id AND e.state = 'effective'
        AND (e.ends_at IS NULL OR e.ends_at > now() - interval '30 days')
    ), '[]'::jsonb),
    'sponsorships', CASE WHEN p_scope_kind = 'union' THEN COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', s.id, 'club_id', s.club_id, 'payer_id', s.payer_id,
        'total_budget', s.total_budget, 'per_club_budget', s.per_club_budget, 'committed', s.committed,
        'effective_from', s.effective_from, 'effective_to', s.effective_to, 'state', s.state, 'revision', s.revision)
        ORDER BY s.created_at DESC)
      FROM public.ca_commerce_sponsorships s WHERE s.union_id = p_scope_id), '[]'::jsonb)
    ELSE COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', s.id, 'union_id', s.union_id, 'payer_id', s.payer_id,
        'remaining', s.total_budget - s.committed, 'per_club_budget', s.per_club_budget, 'effective_to', s.effective_to))
      FROM public.ca_commerce_sponsorships s
      JOIN public.union_clubs uc ON uc.club_id = p_scope_id AND uc.union_id = s.union_id
      WHERE s.state = 'active' AND (s.club_id IS NULL OR s.club_id = p_scope_id)
        AND s.effective_from <= now() AND (s.effective_to IS NULL OR s.effective_to > now())), '[]'::jsonb) END,
    'balance', CASE WHEN v_role = 'owner' THEN (SELECT COALESCE(p.diamonds, 0) FROM public.profiles p WHERE p.id = v_actor) END,
    -- The reader's own wallet, in three distinct figures (R2 5.5, 7.2):
    -- available is the canonical spendable balance; reserved is what open
    -- purchased lots hold for Diamond Arena custody; pending is refunds asked
    -- for, approved or owed and not yet in the balance. Never added together.
    'balance_breakdown', CASE WHEN v_role = 'owner' THEN jsonb_build_object(
      'available', (SELECT COALESCE(p.diamonds, 0) FROM public.profiles p WHERE p.id = v_actor),
      'reserved', (SELECT COALESCE(SUM(COALESCE(l.arena_reserved, 0)), 0)::bigint FROM public.diamond_purchase_lots l
                    WHERE l.user_id = v_actor AND l.frozen_at IS NULL),
      'pending_refunds', (SELECT COALESCE(SUM(COALESCE(q.approved_amount, q.policy_amount)), 0)::bigint FROM public.ca_commerce_refund_requests q
                           WHERE q.payer_id = v_actor AND q.state IN ('requested','approved','owed')),
      'pending_requested', (SELECT COALESCE(SUM(q.policy_amount), 0)::bigint FROM public.ca_commerce_refund_requests q
                             WHERE q.payer_id = v_actor AND q.state = 'requested'),
      'pending_approved', (SELECT COALESCE(SUM(q.approved_amount), 0)::bigint FROM public.ca_commerce_refund_requests q
                            WHERE q.payer_id = v_actor AND q.state = 'approved'),
      'owed_refunds', (SELECT COALESCE(SUM(q.approved_amount), 0)::bigint FROM public.ca_commerce_refund_requests q
                        WHERE q.payer_id = v_actor AND q.state = 'owed'),
      'observed_at', now()) END,
    'refund_requests', COALESCE((
      SELECT jsonb_agg(public.fn_ca_commerce_refund_request_json(q) ORDER BY q.created_at DESC, q.id)
        FROM public.ca_commerce_refund_requests q
       WHERE q.scope_kind = p_scope_kind AND q.scope_id = p_scope_id
         AND (v_staff OR q.payer_id = v_actor OR q.requested_by = v_actor)), '[]'::jsonb)
  );
END $$;


ALTER FUNCTION public.fn_ca_commerce_scope_status(p_scope_kind text, p_scope_id uuid) OWNER TO postgres;

