--
-- TOC entry 4989 (class 1255 OID 54285573)
-- Name: fn_ca_commerce_settings_set(boolean, boolean, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_settings_set(p_checkout_enabled boolean DEFAULT NULL::boolean, p_catalog_visible boolean DEFAULT NULL::boolean, p_admission_enforced_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_clear_admission boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_s public.ca_commerce_settings;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'staff_required');
  END IF;
  UPDATE public.ca_commerce_settings
     SET checkout_enabled = COALESCE(p_checkout_enabled, checkout_enabled),
         catalog_visible = COALESCE(p_catalog_visible, catalog_visible),
         admission_enforced_from = CASE WHEN p_clear_admission THEN NULL ELSE COALESCE(p_admission_enforced_from, admission_enforced_from) END,
         updated_at = now()
   WHERE id = 1 RETURNING * INTO v_s;
  INSERT INTO public.ca_commerce_events (kind, actor_id, detail) VALUES ('settings_changed', v_actor, to_jsonb(v_s));
  RETURN jsonb_build_object('success', true, 'checkout_enabled', v_s.checkout_enabled, 'catalog_visible', v_s.catalog_visible, 'admission_enforced_from', v_s.admission_enforced_from);
END $$;


ALTER FUNCTION public.fn_ca_commerce_settings_set(p_checkout_enabled boolean, p_catalog_visible boolean, p_admission_enforced_from timestamp with time zone, p_clear_admission boolean) OWNER TO postgres;

--
-- TOC entry 8186 (class 1255 OID 54285566)
-- Name: fn_ca_commerce_sponsorship_set(uuid, uuid, integer, integer, timestamp with time zone, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_sponsorship_set(p_union_id uuid, p_club_id uuid, p_total_budget integer, p_per_club_budget integer, p_effective_to timestamp with time zone, p_sponsorship_id uuid DEFAULT NULL::uuid, p_revoke boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_s public.ca_commerce_sponsorships;
BEGIN
  IF v_actor IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'authentication_required'); END IF;
  IF public.fn_ca_commerce_scope_role('union', p_union_id, v_actor) <> 'owner' THEN
    RETURN jsonb_build_object('success', false, 'error', 'union_owner_required');
  END IF;
  IF p_club_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.union_clubs uc WHERE uc.club_id = p_club_id AND uc.union_id = p_union_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'club_not_in_union');
  END IF;
  IF p_sponsorship_id IS NOT NULL THEN
    SELECT * INTO v_s FROM public.ca_commerce_sponsorships WHERE id = p_sponsorship_id AND union_id = p_union_id FOR UPDATE;
    IF v_s.id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'sponsorship_not_found'); END IF;
    IF p_revoke THEN
      UPDATE public.ca_commerce_sponsorships SET state = 'revoked', revoked_at = now(), revision = revision + 1 WHERE id = v_s.id RETURNING * INTO v_s;
    ELSE
      IF p_total_budget IS NULL OR p_total_budget < v_s.committed OR p_total_budget > 2147483647 THEN
        RETURN jsonb_build_object('success', false, 'error', 'budget_below_committed', 'committed', v_s.committed);
      END IF;
      UPDATE public.ca_commerce_sponsorships
         SET total_budget = p_total_budget, per_club_budget = p_per_club_budget, effective_to = p_effective_to, revision = revision + 1
       WHERE id = v_s.id RETURNING * INTO v_s;
    END IF;
  ELSE
    IF p_total_budget IS NULL OR p_total_budget <= 0 OR p_total_budget > 2147483647 THEN
      RETURN jsonb_build_object('success', false, 'error', 'budget_required');
    END IF;
    INSERT INTO public.ca_commerce_sponsorships (union_id, payer_id, club_id, total_budget, per_club_budget, effective_to, created_by)
    VALUES (p_union_id, v_actor, p_club_id, p_total_budget, p_per_club_budget, p_effective_to, v_actor)
    RETURNING * INTO v_s;
  END IF;
  INSERT INTO public.ca_commerce_events (kind, actor_id, scope_kind, scope_id, reference_id, detail)
  VALUES ('sponsorship_' || v_s.state, v_actor, 'union', p_union_id, v_s.id, jsonb_build_object('club_id', v_s.club_id, 'total_budget', v_s.total_budget, 'per_club_budget', v_s.per_club_budget, 'revision', v_s.revision));
  RETURN jsonb_build_object('success', true, 'sponsorship_id', v_s.id, 'state', v_s.state, 'total_budget', v_s.total_budget, 'committed', v_s.committed, 'revision', v_s.revision);
END $$;


ALTER FUNCTION public.fn_ca_commerce_sponsorship_set(p_union_id uuid, p_club_id uuid, p_total_budget integer, p_per_club_budget integer, p_effective_to timestamp with time zone, p_sponsorship_id uuid, p_revoke boolean) OWNER TO postgres;

--
-- TOC entry 9089 (class 1255 OID 55685351)
-- Name: fn_ca_commerce_trial_review_decide(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_commerce_trial_review_decide(p_review_id uuid, p_approve boolean, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_r public.ca_commerce_trial_reviews;
  v_settings public.ca_commerce_settings;
  v_trial public.ca_commerce_trials;
  v_note text := NULLIF(btrim(COALESCE(p_note, '')), '');
  v_url text;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'staff_required');
  END IF;
  IF p_approve IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'decision_required');
  END IF;
  IF v_note IS NOT NULL AND (length(v_note) > 2000 OR strpos(v_note, chr(8212)) > 0) THEN
    RETURN jsonb_build_object('success', false, 'error', 'note_too_long');
  END IF;
  IF NOT p_approve AND v_note IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'note_required');
  END IF;
  SELECT * INTO v_r FROM public.ca_commerce_trial_reviews WHERE id = p_review_id FOR UPDATE;
  IF v_r.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'trial_review_not_found');
  END IF;
  IF v_actor IS NOT NULL AND v_actor = v_r.operator_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'own_request');
  END IF;
  IF v_r.state <> 'requested' THEN
    RETURN jsonb_build_object('success', false, 'error', 'trial_review_already_decided', 'review', public.fn_ca_commerce_trial_review_json(v_r));
  END IF;
  v_url := '/hub/club-arena/' || v_r.scope_kind || 's/' || v_r.scope_id::text || '/diamond-costs';
  IF NOT p_approve THEN
    UPDATE public.ca_commerce_trial_reviews SET state = 'declined', decided_by = v_actor, decided_at = now(), staff_note = v_note
     WHERE id = v_r.id RETURNING * INTO v_r;
    INSERT INTO public.ca_commerce_events (kind, actor_id, scope_kind, scope_id, reference_id, detail)
    VALUES ('trial_review_declined', v_actor, v_r.scope_kind, v_r.scope_id, v_r.id, '{}'::jsonb);
    PERFORM public.fn_ca_commerce_notice(v_r.operator_id, 'trial-review-declined:' || v_r.id::text, 'club_commerce_trial_review',
      'Your Free Month Review Was Declined', 'Platform Staff Wrote: ' || v_note, v_url, jsonb_build_object('review_id', v_r.id), now());
    RETURN jsonb_build_object('success', true, 'review', public.fn_ca_commerce_trial_review_json(v_r));
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('ca_commerce_trial:' || v_r.operator_id::text, 0));
  SELECT * INTO v_settings FROM public.ca_commerce_settings WHERE id = 1;
  INSERT INTO public.ca_commerce_trials (operator_id, trial_start, trial_end, policy_version, cohort, activated_by, waiver_reason)
  VALUES (v_r.operator_id, now(), now() + make_interval(hours => v_settings.trial_hours), v_settings.policy_version, 'review_granted', v_actor,
          'Free Operating Month Granted On Review ' || v_r.id::text)
  RETURNING * INTO v_trial;
  INSERT INTO public.ca_commerce_trial_scopes (trial_id, scope_kind, scope_id, enrolled_by, reason)
  VALUES (v_trial.id, v_r.scope_kind, v_r.scope_id, v_actor, 'Free Month Granted On Review: A New Independent Operation')
  ON CONFLICT (scope_kind, scope_id) DO UPDATE
    SET trial_id = EXCLUDED.trial_id, enrolled_at = now(), enrolled_by = EXCLUDED.enrolled_by, reason = EXCLUDED.reason;
  INSERT INTO public.ca_commerce_entitlements (scope_kind, scope_id, sku, kind, starts_at, ends_at, source, trial_id, net_paid)
  VALUES (v_r.scope_kind, v_r.scope_id, NULL, 'trial_operating', v_trial.trial_start, v_trial.trial_end, 'trial', v_trial.id, 0);
  UPDATE public.ca_commerce_trial_reviews SET state = 'approved', decided_by = v_actor, decided_at = now(), staff_note = v_note, granted_trial_id = v_trial.id
   WHERE id = v_r.id RETURNING * INTO v_r;
  INSERT INTO public.ca_commerce_events (kind, actor_id, scope_kind, scope_id, reference_id, detail)
  VALUES ('trial_review_approved', v_actor, v_r.scope_kind, v_r.scope_id, v_r.id,
          jsonb_build_object('trial_id', v_trial.id, 'trial_end', v_trial.trial_end));
  PERFORM public.fn_ca_commerce_notice(v_r.operator_id, 'trial-review-approved:' || v_r.id::text, 'club_commerce_trial_review',
    'Your Free Month Was Approved',
    'Your Free Operating Month For This ' || initcap(v_r.scope_kind) || ' Ends On ' || to_char(v_trial.trial_end AT TIME ZONE 'America/Chicago', 'Mon DD, YYYY HH12:MI AM') || ' Central.',
    v_url, jsonb_build_object('review_id', v_r.id, 'trial_id', v_trial.id), now());
  PERFORM public.fn_ca_commerce_notice(v_r.operator_id, 'trial-reminder-21:' || v_trial.id::text, 'club_commerce_trial_reminder',
    'Your Operating Trial Ends In 9 Days',
    'Your Free Operating Month Ends On ' || to_char(v_trial.trial_end AT TIME ZONE 'America/Chicago', 'Mon DD, YYYY HH12:MI AM') || ' Central. Review Diamond Prices Before Then.',
    v_url, jsonb_build_object('trial_id', v_trial.id, 'trial_end', v_trial.trial_end), v_trial.trial_start + interval '21 days');
  PERFORM public.fn_ca_commerce_notice(v_r.operator_id, 'trial-reminder-27:' || v_trial.id::text, 'club_commerce_trial_reminder',
    'Your Operating Trial Ends In 3 Days',
    'Your Free Operating Month Ends On ' || to_char(v_trial.trial_end AT TIME ZONE 'America/Chicago', 'Mon DD, YYYY HH12:MI AM') || ' Central. Choose Your Capacity To Continue Without Interruption.',
    v_url, jsonb_build_object('trial_id', v_trial.id, 'trial_end', v_trial.trial_end), v_trial.trial_start + interval '27 days');
  RETURN jsonb_build_object('success', true, 'review', public.fn_ca_commerce_trial_review_json(v_r));
END $$;


ALTER FUNCTION public.fn_ca_commerce_trial_review_decide(p_review_id uuid, p_approve boolean, p_note text) OWNER TO postgres;

--
-- TOC entry 2847 (class 1259 OID 55685326)
-- Name: ca_commerce_trial_reviews; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ca_commerce_trial_reviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    scope_kind text NOT NULL,
    scope_id uuid NOT NULL,
    operator_id uuid NOT NULL,
    requested_by uuid NOT NULL,
    statement text NOT NULL,
    state text DEFAULT 'requested'::text NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    staff_note text,
    granted_trial_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ca_commerce_trial_reviews_check CHECK (((state = 'approved'::text) = (granted_trial_id IS NOT NULL))),
    CONSTRAINT ca_commerce_trial_reviews_check1 CHECK (((state <> 'declined'::text) OR (staff_note IS NOT NULL))),
    CONSTRAINT ca_commerce_trial_reviews_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['club'::text, 'union'::text]))),
    CONSTRAINT ca_commerce_trial_reviews_staff_note_check CHECK (((staff_note IS NULL) OR ((length(staff_note) <= 2000) AND (strpos(staff_note, chr(8212)) = 0)))),
    CONSTRAINT ca_commerce_trial_reviews_state_check CHECK ((state = ANY (ARRAY['requested'::text, 'approved'::text, 'declined'::text]))),
    CONSTRAINT ca_commerce_trial_reviews_statement_check CHECK ((((length(statement) >= 20) AND (length(statement) <= 2000)) AND (strpos(statement, chr(8212)) = 0)))
);


ALTER TABLE public.ca_commerce_trial_reviews OWNER TO postgres;

