--
-- TOC entry 3914 (class 1255 OID 18225028)
-- Name: fn_ca_cron_failure_watch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_cron_failure_watch() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; n integer := 0; v_is_guard boolean;
BEGIN
  FOR r IN
    -- ONE pass over a bounded window. cron.job_run_details is indexed only by
    -- runid, so a per-job "last 3 runs" lookup with no time bound is a full
    -- scan per active job. Here a single scan of the last 7 days ranks each
    -- job's finished runs newest first; the 24 hour counts and the last three
    -- finished runs both come from that one pass. A job that appears in the
    -- 24 hour window runs at least daily, so its last three finished runs fall
    -- inside 7 days.
    WITH runs AS (
      SELECT d.jobid, d.status, d.start_time, d.return_message,
             d.start_time > now() - interval '24 hours' AS in_day,
             CASE WHEN d.status IN ('failed', 'succeeded')
                  THEN row_number() OVER (PARTITION BY d.jobid, d.status IN ('failed', 'succeeded')
                                          ORDER BY d.start_time DESC)
             END AS finished_rank
        FROM cron.job_run_details d
       WHERE d.start_time > now() - interval '7 days'
    ),
    day AS (
      SELECT j.jobid, j.jobname,
             count(*) FILTER (WHERE x.in_day AND x.status = 'failed')    AS fails,
             count(*) FILTER (WHERE x.in_day AND x.status = 'succeeded') AS successes,
             max(x.start_time) FILTER (WHERE x.in_day AND x.status = 'succeeded') AS last_success,
             max(left(x.return_message, 200)) FILTER (WHERE x.in_day AND x.status = 'failed') AS sample_error,
             count(*) FILTER (WHERE x.finished_rank <= 3) AS finished,
             count(*) FILTER (WHERE x.finished_rank <= 3 AND x.status = 'failed') AS failed_in_a_row
        FROM cron.job j
        JOIN runs x ON x.jobid = j.jobid
       WHERE j.active
       GROUP BY j.jobid, j.jobname
      HAVING count(*) FILTER (WHERE x.in_day) > 0
    )
    SELECT day.*
      FROM day
     WHERE (day.finished = 3 AND day.failed_in_a_row = 3
            AND (day.last_success IS NULL OR day.last_success <= now() - interval '2 hours'))
        OR (day.fails >= 5 AND day.fails > day.successes)
     ORDER BY day.fails DESC, day.jobname
     LIMIT 20
  LOOP
    SELECT EXISTS (SELECT 1 FROM public.ca_guard_inventory g
                    WHERE g.kind = 'cron' AND g.object_a = r.jobname AND g.active)
      INTO v_is_guard;
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_cron_failure_watch', 'unknown',
      CASE WHEN v_is_guard THEN 'critical' ELSE 'warning' END,
      'cron-failing:' || r.jobname || ':' || CURRENT_DATE::text,
      0, NULL, NULL, 'reporting', 'cron.job_run_details',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'scheduled job ' || r.jobname || ' failed ' || r.fails || ' of '
        || (r.fails + r.successes) || ' runs in 24h (last '
        || r.failed_in_a_row || ' of its last 3 failed; last success '
        || COALESCE(r.last_success::text, 'none in 24h') || '). Last error: '
        || COALESCE(r.sample_error, '?'),
      NULL, jsonb_build_object('jobname', r.jobname, 'fails_24h', r.fails,
                               'successes_24h', r.successes,
                               'failed_in_a_row', r.failed_in_a_row,
                               'last_success', r.last_success));
    n := n + 1;
  END LOOP;

  /* 20261002135708: a ledger refusal the counter saw and no record reached
     becomes an explicit row and a critical incident here. Isolated, so it can
     never stop the cron watch above from reporting, and a failure of its own
     is itself a critical incident rather than a silent zero. */
  BEGIN
    n := n + public.fn_ca_ledger_invariant_refusal_watch();
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'ledger_invariant.refused', 'unknown', 'critical',
      'ledger-invariant-refusal-watch-failed',
      NULL, NULL, NULL, 'ledger', 'chip_store',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'fn_ca_ledger_invariant_refusal_watch failed, so a ledger refusal whose record was lost cannot be told from no refusal: ' || SQLERRM,
      NULL, NULL);
  END;
  RETURN n;
END $$;


ALTER FUNCTION public.fn_ca_cron_failure_watch() OWNER TO postgres;

--
-- TOC entry 4152 (class 1255 OID 42362783)
-- Name: fn_ca_cron_health(interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_cron_health(p_window interval DEFAULT '24:00:00'::interval) RETURNS TABLE(jobname text, schedule text, verdict text, runs bigint, failures bigint, successes bigint, last_run_at timestamp with time zone, last_error text, last_run_status text, last_error_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with j as (
    select jobid, jobname, schedule from cron.job where active
  ),
  w as (
    select r.jobid, r.status, r.return_message, r.start_time
      from cron.job_run_details r
     where r.start_time > now() - p_window
  ),
  agg as (
    select j.jobid, j.jobname, j.schedule,
           count(w.*)                                     as runs,
           count(*) filter (where w.status = 'failed')    as failures,
           count(*) filter (where w.status = 'succeeded') as successes,
           max(w.start_time)                              as last_run_at
      from j left join w on w.jobid = j.jobid
     group by j.jobid, j.jobname, j.schedule
  ),
  -- ONE run, whole. status and message cannot come from different runs
  -- because they are columns of the same row.
  last_finished as (
    select distinct on (w.jobid)
           w.jobid, w.status, w.return_message, w.start_time
      from w
     where w.status in ('succeeded', 'failed')
     order by w.jobid, w.start_time desc
  ),
  -- A SAMPLE OF ONE CANNOT SAY "NEVER SUCCEEDED" (2026-10-03). A job whose
  -- period is as long as p_window puts exactly one run in it, so a single
  -- failure would otherwise be reported as 'critical', the verdict the
  -- reader prints as "broken, not flaky". So the last three FINISHED runs of
  -- every job are ranked here - evidence the window could not hold - and the
  -- verdict below consults them for that one case.
  --
  -- Three is the smallest sample that separates "always fails" from "failed";
  -- it keeps a genuinely dead daily job critical within three days, and it is
  -- not widened to clear any particular job.
  --
  -- ONE RANKED PASS, NOT A SUBQUERY PER JOB. The first version of this asked
  -- `order by start_time desc limit 3` inside a correlated subquery over
  -- cron.job_run_details, once per sparse job. cron's run log carries NO
  -- INDEX AT ALL - every read of it is a sequential scan of 280,684 rows -
  -- so the correlated form re-scanned the whole log per job and took
  -- 27,665 ms against this function's previous 546 ms. It was measured only
  -- after it had already failed to apply. Ranking once and grouping is
  -- 698 ms total, +152 ms on the old function, and Postgres pushes the
  -- rn <= 3 filter into the window as a Run Condition so it stops early.
  -- Same verdicts either way: 65 ok, 55 warn, 1 critical, 3 idle both times.
  recent as (
    select d.jobid, d.status,
           row_number() over (partition by d.jobid order by d.start_time desc) as rn
      from cron.job_run_details d
     where d.status in ('succeeded', 'failed')
  ),
  lookback as (
    select k.jobid,
           count(*) filter (where k.status = 'succeeded') as successes_in_last_3
      from recent k
     where k.rn <= 3
     group by k.jobid
  ),
  -- The verdict is computed ONCE. It used to be written twice, in the select
  -- list and again in the ORDER BY, which is two copies free to drift.
  decided as (
    select a.jobid, a.jobname, a.schedule, a.runs, a.failures, a.successes,
           a.last_run_at,
           case
             -- Only FINISHED runs are evidence. pg_cron logs a row at START,
             -- so a job mid-flight has status 'running' and counts as neither.
             when a.failures + a.successes = 0 then 'idle'
             when a.successes = 0
                  and a.failures + a.successes = 1
                  and coalesce(b.successes_in_last_3, 0) > 0 then 'warn'
             when a.successes = 0              then 'critical'
             when a.failures  > 0              then 'warn'
             else 'ok'
           end as verdict
      from agg a
      left join lookback b on b.jobid = a.jobid
  )
  select d.jobname, d.schedule, d.verdict,
         d.runs, d.failures, d.successes, d.last_run_at,
         case when lf.status = 'failed'
              then left(lf.return_message, 200) end as last_error,
         lf.status                                  as last_run_status,
         case when lf.status = 'failed'
              then lf.start_time end                as last_error_at
    from decided d
    left join last_finished lf on lf.jobid = d.jobid
   order by
     case d.verdict
       when 'critical' then 0
       when 'warn'     then 1
       when 'ok'       then 2
       else 3
     end,
     d.failures desc,
     d.jobname;
$$;


ALTER FUNCTION public.fn_ca_cron_health(p_window interval) OWNER TO postgres;

--
-- TOC entry 45590 (class 0 OID 0)
-- Dependencies: 4152
-- Name: FUNCTION fn_ca_cron_health(p_window interval); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_cron_health(p_window interval) IS 'Cron health, one row per active job. last_run_status, last_error and last_error_at all come from the SAME most recent finished run. They used to come from different runs: last_error was max() over failure text, which is the lexicographically greatest message in the window, not the most recent, and it was printed beside an unrelated last_run_at. Do not reintroduce an aggregate over return_message.';


--
-- TOC entry 5150 (class 1255 OID 24087202)
-- Name: fn_ca_currency_meter(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_currency_meter() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_t0 timestamptz := clock_timestamp();
  v_out numeric; v_journal numeric; v_accounts int; v_drifted int; v_worst numeric; v_detail jsonb;
  v_res jsonb := '{}'::jsonb;
  v_rb_periods_paid numeric; v_rb_payout_rows numeric; v_rb_legs numeric; v_rb_pending numeric;
  v_rb_orphans int; v_rb_deletes int; v_rb_first_leg timestamptz;
BEGIN
  IF NOT (current_user IN ('postgres', 'supabase_admin') OR COALESCE(auth.role(), '') = 'service_role') THEN
    RAISE EXCEPTION 'fn_ca_currency_meter is service only' USING ERRCODE = '42501';
  END IF;

  /* VIP POINTS: every balance against the sum of its legs. Enforced. */
  WITH j AS (SELECT user_id, sum(points) AS journal, sum(points) FILTER (WHERE points > 0) AS earned FROM public.vip_points_ledger GROUP BY 1)
  SELECT COALESCE(sum(v.current_points), 0), COALESCE(sum(j.journal), 0), count(*),
         count(*) FILTER (WHERE COALESCE(j.journal, 0) <> COALESCE(v.current_points, 0) OR COALESCE(j.earned, 0) <> COALESCE(v.lifetime_points, 0)),
         COALESCE(max(abs(COALESCE(j.journal, 0) - COALESCE(v.current_points, 0))), 0),
         jsonb_build_object(
           'balance_without_journal', count(*) FILTER (WHERE j.user_id IS NULL),
           'journal_without_balance', count(*) FILTER (WHERE v.user_id IS NULL),
           'sample', COALESCE((SELECT jsonb_agg(jsonb_build_object('user_id', x.uid, 'balance', x.bal, 'journal', x.jr)) FROM (
              SELECT COALESCE(v2.user_id, j2.user_id) AS uid, v2.current_points AS bal, j2.journal AS jr
                FROM public.vip_points v2 FULL JOIN j j2 ON j2.user_id = v2.user_id
               WHERE COALESCE(j2.journal, 0) <> COALESCE(v2.current_points, 0) LIMIT 10) x), '[]'::jsonb))
    INTO v_out, v_journal, v_accounts, v_drifted, v_worst, v_detail
    FROM public.vip_points v FULL JOIN j ON j.user_id = v.user_id;
  INSERT INTO public.ca_currency_meter (currency, outstanding, journal_total, accounts, drifted, worst, enforced, detail)
  VALUES ('vip_points', v_out, v_journal, v_accounts, v_drifted, v_worst, true, v_detail);
  IF v_drifted > 0 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_currency_meter', 'ledger_imbalance', 'critical', 'currency-drift:vip_points',
      v_out - v_journal, v_journal, v_out, 'ledger', 'vip_points',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      v_drifted || ' VIP balance(s) disagree with their own ledger (worst ' || v_worst || ' points). '
        || 'zz_vip_points_move_only_with_a_leg and the append-only guard on vip_points_ledger make this '
        || 'impossible through the doors; seeing it means a guard was bypassed or dropped.',
      false, v_detail);
  END IF;
  v_res := v_res || jsonb_build_object('vip_points', jsonb_build_object('outstanding', v_out, 'journal', v_journal, 'accounts', v_accounts, 'drifted', v_drifted, 'worst', v_worst));

  /* AGENT COMMISSIONS: every rollup against the sum of its unsettled rows. Enforced.
     ONE RANGE PER UNCOVERED GAP, ONE CUTOFF PER CLUB (2026-10-15). This read
     used to aggregate the agent_commissions_unsettled view, which calls the
     SECURITY DEFINER fn_ca_launch_accounting_accepts once per ROW (a definer
     function is never inlined) and walks every settled_at IS NULL row ever
     written, including the ones a settlement period already covers (a claim
     records what it covered, 20260908033445; it does not stamp the row).
     21 million rows on 2026-10-14, two definer calls each: the nightly job
     hit its 600 s statement_timeout. The same answer is read here per
     (club, agent): the cutoff once per club, the complement of the agent's
     settlement periods as ranges, and one index-only range scan of
     agent_commissions_open_idx per uncovered range, so the read grows with
     what is owed, not with history. Row for row it is the view's predicate:
     settled_at IS NULL, no period with start <= created_at < end, and the
     launch cutoff exactly as fn_ca_launch_accounting_accepts applies it. */
  WITH RECURSIVE pairs AS (
    (SELECT a.club_id, a.user_id FROM public.agent_commissions a
      WHERE a.settled_at IS NULL ORDER BY a.club_id, a.user_id LIMIT 1)
    UNION ALL
    SELECT n.club_id, n.user_id
      FROM pairs p
      CROSS JOIN LATERAL (
        SELECT a.club_id, a.user_id FROM public.agent_commissions a
         WHERE a.settled_at IS NULL AND (a.club_id, a.user_id) > (p.club_id, p.user_id)
         ORDER BY a.club_id, a.user_id LIMIT 1) n
  ), cut AS MATERIALIZED (
    SELECT c.club_id, public.fn_ca_launch_accounting_cutoff('club', c.club_id) AS cutoff
      FROM (SELECT DISTINCT club_id FROM pairs) c
  ), iv AS MATERIALIZED (
    SELECT s.club_id, s.user_id, s.period_start, s.period_end
      FROM public.agent_commission_settlements s
      JOIN pairs p ON p.club_id = s.club_id AND p.user_id = s.user_id
     WHERE s.period_start < s.period_end
  ), gaps AS MATERIALIZED (
    SELECT l.club_id, l.user_id, l.lo,
           (SELECT min(i.period_start) FROM iv i
             WHERE i.club_id = l.club_id AND i.user_id = l.user_id AND i.period_start > l.lo) AS hi
      FROM (SELECT p.club_id, p.user_id, '-infinity'::timestamptz AS lo FROM pairs p
            UNION
            SELECT i.club_id, i.user_id, i.period_end FROM iv i) l
     WHERE NOT EXISTS (SELECT 1 FROM iv i
                        WHERE i.club_id = l.club_id AND i.user_id = l.user_id
                          AND l.lo >= i.period_start AND l.lo < i.period_end)
  ), legs AS (
    SELECT g.club_id, g.user_id, x.owed, x.n
      FROM gaps g
      JOIN cut k ON k.club_id = g.club_id
      CROSS JOIN LATERAL (
        SELECT sum(a.amount) AS owed, count(*) AS n FROM public.agent_commissions a
         WHERE a.club_id = g.club_id AND a.user_id = g.user_id AND a.settled_at IS NULL
           AND a.created_at >= CASE WHEN k.cutoff IS NULL THEN g.lo ELSE greatest(g.lo, k.cutoff) END
           AND a.created_at <= COALESCE(g.hi, 'infinity'::timestamptz)
           AND (g.hi IS NULL OR a.created_at < g.hi)
           AND (k.cutoff IS NULL OR isfinite(a.created_at))) x
    UNION ALL
    SELECT p.club_id, p.user_id, x.owed, x.n
      FROM pairs p
      JOIN cut k ON k.club_id = p.club_id AND k.cutoff IS NULL
      CROSS JOIN LATERAL (
        SELECT sum(a.amount) AS owed, count(*) AS n FROM public.agent_commissions a
         WHERE a.club_id = p.club_id AND a.user_id = p.user_id AND a.settled_at IS NULL
           AND a.created_at IS NULL) x
  ), u AS (
    SELECT club_id, user_id, sum(owed) AS owed FROM legs GROUP BY 1, 2 HAVING sum(n) > 0
  )
  SELECT COALESCE(sum(r.owed), 0), COALESCE(sum(u.owed), 0), count(*),
         count(*) FILTER (WHERE round(COALESCE(u.owed, 0), 2) <> round(COALESCE(r.owed, 0), 2)),
         COALESCE(max(abs(COALESCE(u.owed, 0) - COALESCE(r.owed, 0))), 0),
         jsonb_build_object(
           'journal_without_rollup', count(*) FILTER (WHERE r.club_id IS NULL),
           'rollup_without_journal', count(*) FILTER (WHERE u.club_id IS NULL))
    INTO v_out, v_journal, v_accounts, v_drifted, v_worst, v_detail
    FROM u FULL JOIN public.agent_commission_unsettled_rollup r ON r.club_id = u.club_id AND r.user_id = u.user_id;
  INSERT INTO public.ca_currency_meter (currency, outstanding, journal_total, accounts, drifted, worst, enforced, detail)
  VALUES ('agent_commissions', v_out, v_journal, v_accounts, v_drifted, v_worst, true, v_detail);
  IF v_drifted > 0 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_currency_meter', 'ledger_imbalance', 'critical', 'currency-drift:agent_commissions',
      v_out - v_journal, v_journal, v_out, 'ledger', 'agent_commissions',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      v_drifted || ' agent(s) whose unsettled rollup disagrees with their commission rows (worst ' || round(v_worst, 2) || '). '
        || 'The rollup is kept by statement triggers and the rows are append-only; seeing it means one of those was bypassed.',
      false, v_detail);
  END IF;
  v_res := v_res || jsonb_build_object('agent_commissions', jsonb_build_object('outstanding', v_out, 'journal', v_journal, 'accounts', v_accounts, 'drifted', v_drifted, 'worst', v_worst));

  /* RAKEBACK: three sources side by side. NOT enforced - the period row is a
     counter that accrues by design, and the payout path is another lane's. */
  SELECT COALESCE(sum(rakeback_amount) FILTER (WHERE status = 'paid'), 0),
         COALESCE(sum(rakeback_amount) FILTER (WHERE status <> 'paid'), 0)
    INTO v_rb_periods_paid, v_rb_pending FROM public.rakeback_periods;
  SELECT COALESCE(sum(payout_amount), 0) INTO v_rb_payout_rows FROM public.rakeback_period_payouts WHERE status = 'paid';
  SELECT COALESCE(sum(amount), 0), min(created_at) INTO v_rb_legs, v_rb_first_leg
    FROM public.chip_ledger WHERE category = 'rakeback' AND to_type = 'player_wallet';
  /* Only periods that closed AFTER the opening position. The block before
     it is recorded in ca_rakeback_baseline, reconciled to the cent, and does
     not need re-deriving every forty minutes. */
  SELECT count(*) INTO v_rb_orphans FROM public.rakeback_periods p
   WHERE p.status = 'paid' AND p.rakeback_amount > 0
     AND p.created_at > COALESCE((SELECT b.known_through FROM public.ca_rakeback_baseline b WHERE b.id = 1),
                                 '-infinity'::timestamptz)
     AND NOT EXISTS (SELECT 1 FROM public.rakeback_period_payouts pp WHERE pp.rakeback_period_id = p.id);
  SELECT count(*) INTO v_rb_deletes FROM public.ca_ledger_mutation_log
   WHERE source_table = 'rakeback_period_payouts' AND at > now() - interval '1 day';
  v_detail := jsonb_build_object(
    'periods_paid_total', v_rb_periods_paid, 'payout_rows_total', v_rb_payout_rows,
    'chip_legs_to_players_total', v_rb_legs, 'chip_journal_since', v_rb_first_leg,
    'paid_periods_without_payout_row', v_rb_orphans, 'payout_rows_deleted_24h', v_rb_deletes,
    'not_enforced_because', 'rakeback_periods accrues during the period by design and the payout path (fn_close_settlement_period) is another lane''s live rebuild as of 2026-09-07; the meter reads the three sources and names the gap');
  INSERT INTO public.ca_currency_meter (currency, outstanding, journal_total, accounts, drifted, worst, enforced, detail)
  VALUES ('rakeback', v_rb_pending, v_rb_payout_rows, 0,
          CASE WHEN round(v_rb_periods_paid, 2) <> round(v_rb_payout_rows, 2) THEN 1 ELSE 0 END,
          abs(v_rb_periods_paid - v_rb_payout_rows), false, v_detail);
  IF round(v_rb_periods_paid, 2)
       <> round(v_rb_payout_rows
                + COALESCE((SELECT b.known_orphan_amount + b.known_unpayable_amount
                              FROM public.ca_rakeback_baseline b WHERE b.id = 1), 0), 2)
     OR v_rb_orphans > 0 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_currency_meter', 'ledger_imbalance', 'warning', 'currency-drift:rakeback',
      v_rb_periods_paid - v_rb_payout_rows, v_rb_payout_rows, v_rb_periods_paid, 'ledger', 'rakeback_periods',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'rakeback_periods says ' || v_rb_periods_paid || ' paid; rakeback_period_payouts says ' || v_rb_payout_rows
        || '; chip_ledger legs to players say ' || v_rb_legs || ' since ' || COALESCE(v_rb_first_leg::text, 'never')
        || '. ' || v_rb_orphans || ' paid period(s) have no payout row. Not enforced by this meter; see detail.',
      false, v_detail);
  END IF;
  v_res := v_res || jsonb_build_object('rakeback', v_detail || jsonb_build_object('pending', v_rb_pending));

  RETURN v_res || jsonb_build_object('at', now(), 'ms', round(extract(epoch from (clock_timestamp() - v_t0)) * 1000));
END $$;


ALTER FUNCTION public.fn_ca_currency_meter() OWNER TO postgres;

--
-- TOC entry 45592 (class 0 OID 0)
-- Dependencies: 5150
-- Name: FUNCTION fn_ca_currency_meter(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_currency_meter() IS 'Nightly conservation meter for the currencies that are not chips. ENFORCED: vip_points against vip_points_ledger, and agent_commission_unsettled_rollup against unsettled agent_commissions - both hold by construction because the journals are append-only and the balance moves only with a leg, so a drift is a CRITICAL incident meaning a guard was bypassed or dropped. NOT ENFORCED, and deliberately: rakeback (three sources disagree by design while fn_close_settlement_period is another lane''s live rebuild; the row carries not_enforced_because and raises a WARNING with the numbers). NOT COVERED AT ALL: vip_points_carry, the fractional remainder between awards, which no guard watches; and the commission rollup is COMPARED here rather than guarded, its correctness resting on the statement triggers that maintain it. Cost is O(journal) - 10.2s at 5.75M VIP legs, growing ~306k/day against job 286''s 600s budget.';


