--
-- TOC entry 6899 (class 1255 OID 18201236)
-- Name: fn_ca_daily_attestation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_daily_attestation() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_open integer; v_critical integer; v_resolved integer; v_suspense numeric;
  v_failures integer; v_chain record; v_rows bigint; v_green boolean;
  v_title text; v_body text; v_uid uuid; v_sent integer := 0;
BEGIN
  SELECT count(*) FILTER (WHERE status <> 'resolved'),
         count(*) FILTER (WHERE status <> 'resolved' AND severity = 'critical'),
         count(*) FILTER (WHERE status = 'resolved' AND resolved_at > now() - interval '24 hours')
    INTO v_open, v_critical, v_resolved
    FROM public.ca_drift_incidents;
  SELECT COALESCE(sum(amount), 0) INTO v_suspense FROM public.chip_ledger
   WHERE (from_type='settlement_suspense' OR to_type='settlement_suspense')
     AND created_at > now() - interval '24 hours';
  SELECT count(*) INTO v_failures FROM public.ca_ledger_write_failures
   WHERE occurred_at > now() - interval '24 hours';
  SELECT * INTO v_chain FROM public.fn_ca_verify_ledger_chain(20000);
  SELECT count(*) INTO v_rows FROM public.chip_ledger WHERE created_at > now() - interval '24 hours';

  v_green := v_open = 0 AND v_failures = 0 AND COALESCE(v_chain.breaks, 0) = 0
             AND v_suspense < 50;
  v_title := CASE WHEN v_green THEN '✅ Chip integrity: all green'
                  ELSE '📋 Chip integrity: attention needed' END;
  v_body := v_rows || ' ledger rows / 24h. Open incidents: ' || v_open
    || ' (' || v_critical || ' critical). Resolved / 24h: ' || v_resolved
    || '. Unclassified flow: ' || round(v_suspense, 2)
    || '. Ledger write failures: ' || v_failures
    || '. Checksum verify: ' || COALESCE(v_chain.checked, 0) || ' rows, '
    || COALESCE(v_chain.breaks, 0) || ' breaks.';

  FOR v_uid IN
    SELECT DISTINCT user_id FROM public.ca_incident_recipients
     WHERE active AND scope = 'platform'
  LOOP
    PERFORM public.fn_raise_notification(v_uid, 'financial_attestation', v_title, v_body,
      '/hub/club-arena/financial-incidents',
      jsonb_build_object('green', v_green, 'open', v_open, 'critical', v_critical,
                         'suspense', round(v_suspense,2), 'chain_breaks', COALESCE(v_chain.breaks,0)));
    v_sent := v_sent + 1;
  END LOOP;

  RETURN jsonb_build_object('green', v_green, 'recipients', v_sent, 'open', v_open,
    'critical', v_critical, 'resolved_24h', v_resolved, 'suspense_24h', round(v_suspense,2),
    'write_failures_24h', v_failures, 'chain_checked', COALESCE(v_chain.checked,0),
    'chain_breaks', COALESCE(v_chain.breaks,0), 'ledger_rows_24h', v_rows);
END $$;


ALTER FUNCTION public.fn_ca_daily_attestation() OWNER TO postgres;

--
-- TOC entry 5920 (class 1255 OID 26943425)
-- Name: fn_ca_daily_bonus_boost_extra(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_daily_bonus_boost_extra(p_user_id uuid, p_base integer, p_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_boost  public.player_boosts;
  v_extra  integer;
  v_award  jsonb;
BEGIN
  -- Internal: EXECUTE is revoked from anon and authenticated, so only another
  -- definer (the Daily Missions claim, after it has paid the base) can reach
  -- it. The base amount is that caller's own figure; a browser never names it.
  IF p_user_id IS NULL OR COALESCE(p_base, 0) <= 0 THEN
    RETURN NULL;
  END IF;
  SELECT * INTO v_boost FROM public.player_boosts b
   WHERE b.user_id = p_user_id AND b.kind = 'mission_diamonds'
     AND b.starts_at <= now() AND b.ends_at > now()
   ORDER BY b.factor DESC, b.ends_at DESC
   LIMIT 1
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  v_extra := round(p_base * (v_boost.factor - 1.00))::integer;
  IF v_extra <= 0 THEN
    RETURN jsonb_build_object('boost_id', v_boost.id, 'factor', v_boost.factor, 'base', p_base,
                              'extra', 0, 'awarded', 0, 'ends_at', v_boost.ends_at);
  END IF;
  -- The extra goes through the diamond engine under its own action so it
  -- counts toward the player's 110/150 daily cap and 3,300/4,500 monthly
  -- cap, and files under club_arena_daily. award_diamonds_v2 writes nothing
  -- when it refuses, so a capped player simply gets no extra.
  v_award := public.award_diamonds_v2(
    p_user_id, 'daily_bonus_boost',
    'ca_daily_bonus:boost:' || p_user_id::text || ':' || COALESCE(p_reference, gen_random_uuid()::text),
    NULL,
    jsonb_build_object('_source', 'fn_ca_daily_bonus_boost_extra',
                       'bonus_diamonds', LEAST(125, v_extra),
                       'boost_id', v_boost.id, 'boost_factor', v_boost.factor,
                       'base', p_base, 'reference', p_reference));
  UPDATE public.player_boosts
     SET applications = applications + 1,
         applied_diamonds = applied_diamonds + COALESCE((v_award->>'awarded')::int, 0),
         last_applied_at = now()
   WHERE id = v_boost.id;
  RETURN jsonb_build_object(
    'boost_id', v_boost.id, 'factor', v_boost.factor, 'base', p_base,
    'extra', LEAST(125, v_extra),
    'awarded', COALESCE((v_award->>'awarded')::int, 0),
    'success', COALESCE((v_award->>'success')::boolean, false),
    'reason', v_award->>'reason',
    'capped', COALESCE((v_award->>'capped')::boolean, false),
    'balance_after', (v_award->>'balance_after')::int,
    'ends_at', v_boost.ends_at);
END;
$$;


ALTER FUNCTION public.fn_ca_daily_bonus_boost_extra(p_user_id uuid, p_base integer, p_reference text) OWNER TO postgres;

--
-- TOC entry 8271 (class 1255 OID 25694993)
-- Name: fn_ca_daily_bonus_budget_check(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_daily_bonus_budget_check(p_today date) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_today_total bigint;
  v_p95         numeric;
  v_days        integer;
BEGIN
  SELECT COALESCE(sum(awarded), 0) INTO v_today_total
    FROM public.diamond_user_daily_awards WHERE engine = 'club_arena_daily' AND day = p_today;
  SELECT count(*), percentile_cont(0.95) WITHIN GROUP (ORDER BY t.total)
    INTO v_days, v_p95
    FROM (SELECT day, sum(awarded) AS total FROM public.diamond_user_daily_awards
           WHERE engine = 'club_arena_daily' AND day >= p_today - 14 AND day < p_today
           GROUP BY day) t;
  IF v_days < 7 OR v_p95 IS NULL OR v_today_total <= v_p95 THEN RETURN; END IF;
  IF EXISTS (SELECT 1 FROM public.financial_alerts a
              WHERE a.source = 'fn_ca_daily_bonus_claim.budget_anomaly'
                AND a.context->>'bonus_date' = p_today::text) THEN
    RETURN;
  END IF;
  INSERT INTO public.financial_alerts (severity, source, message, context)
  VALUES ('warning', 'fn_ca_daily_bonus_claim.budget_anomaly',
          format('daily bonus paid %s diamonds today, above the 14-day p95 of %s', v_today_total, round(v_p95)),
          jsonb_build_object('bonus_date', p_today, 'today', v_today_total, 'p95', round(v_p95, 1), 'days', v_days));
END;
$$;


ALTER FUNCTION public.fn_ca_daily_bonus_budget_check(p_today date) OWNER TO postgres;

--
-- TOC entry 6973 (class 1255 OID 23955853)
-- Name: fn_ca_daily_bonus_calendar_history(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_daily_bonus_calendar_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.ca_daily_bonus_calendar_history (op, old_row, new_row)
  VALUES (TG_OP,
          CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) END,
          CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) END);
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


