--
-- TOC entry 9385 (class 1255 OID 23955918)
-- Name: fn_ca_daily_bonus_eligibility(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_daily_bonus_eligibility(p_user_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_user_id IS NULL THEN RETURN 'unauthenticated'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = p_user_id) THEN RETURN 'no_profile'; END IF;
  -- Horses are players (Diamond Accounting Standard D22). Fixtures are not.
  IF public.fn_ca_is_cert_account(p_user_id) OR public.fn_ca_is_fixture_account(p_user_id) THEN
    RETURN 'fixture';
  END IF;
  RETURN 'ok';
END;
$$;


ALTER FUNCTION public.fn_ca_daily_bonus_eligibility(p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 6581 (class 1255 OID 25687016)
-- Name: fn_ca_daily_bonus_mark_shown(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_daily_bonus_mark_shown() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid   uuid := auth.uid();
  v_today date := (now() AT TIME ZONE 'America/Chicago')::date;
  v_day   public.ca_daily_bonus_days;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_ca_daily_bonus_mark_shown requires an authenticated caller' USING ERRCODE = '28000';
  END IF;
  IF public.fn_ca_daily_bonus_eligibility(v_uid) <> 'ok' THEN
    RETURN jsonb_build_object('success', false, 'reason', public.fn_ca_daily_bonus_eligibility(v_uid));
  END IF;
  v_day := public.fn_ca_daily_bonus_open_day(v_uid, v_today);
  UPDATE public.ca_daily_bonus_days
     SET sheet_shown_at = COALESCE(sheet_shown_at, now())
   WHERE user_id = v_uid AND bonus_date = v_today
  RETURNING * INTO v_day;
  RETURN jsonb_build_object('success', true, 'today', v_today, 'shown_at', v_day.sheet_shown_at);
END;
$$;


ALTER FUNCTION public.fn_ca_daily_bonus_mark_shown() OWNER TO postgres;

