--
-- TOC entry 5839 (class 1255 OID 23955925)
-- Name: fn_ca_daily_bonus_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_daily_bonus_status() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid        uuid := auth.uid();
  v_elig       text;
  v_today      date := (now() AT TIME ZONE 'America/Chicago')::date;
  v_reset_at   timestamptz := ((now() AT TIME ZONE 'America/Chicago')::date + 1)::timestamp AT TIME ZONE 'America/Chicago';
  v_day        public.ca_daily_bonus_days;
  v_is_vip     boolean := false;
  v_caps       jsonb;
  v_tiles      jsonb;
  v_week       jsonb;
  v_next       jsonb;
  v_next_streak integer;
  v_next_cycle  integer;
  v_shield     jsonb;
  v_boost      jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_ca_daily_bonus_status requires an authenticated caller' USING ERRCODE = '28000';
  END IF;

  v_elig := public.fn_ca_daily_bonus_eligibility(v_uid);
  IF v_elig <> 'ok' THEN
    RETURN jsonb_build_object('eligible', false, 'reason', v_elig, 'today', v_today,
                              'reset_at', v_reset_at,
                              'seconds_to_reset', GREATEST(0, floor(extract(epoch FROM (v_reset_at - now())))::integer),
                              'shown_today', false,
                              'tiles', '[]'::jsonb);
  END IF;

  SELECT COALESCE(p.is_vip, false)
         AND (p.vip_tier = 'lifetime' OR p.vip_expires_at IS NULL OR p.vip_expires_at > now())
    INTO v_is_vip
    FROM public.profiles p WHERE p.id = v_uid;

  v_day  := public.fn_ca_daily_bonus_open_day(v_uid, v_today);
  v_caps := public.fn_ca_daily_bonus_caps(v_uid, v_is_vip);

  -- Today's tiles with their claim state. The mystery result stays hidden
  -- until it is claimed; the claim reveals it. A diamond tile the daily cap
  -- would trim is flagged so the sheet can say so before the tap.
  SELECT COALESCE(jsonb_agg(
           (t - 'mystery') || jsonb_build_object(
             'claimed', cl.id IS NOT NULL,
             'claimed_at', cl.created_at,
             'granted', cl.granted,
             'revealed', CASE WHEN cl.id IS NOT NULL THEN cl.result->'revealed' ELSE NULL END,
             'locked', (t->>'vip_only')::boolean AND NOT v_is_vip,
             'capped', cl.id IS NULL AND t->>'kind' = 'diamonds'
                       AND (t->>'diamonds')::int > (v_caps->>'daily_remaining')::int
           ) ORDER BY (t->>'slot')::int), '[]'::jsonb)
    INTO v_tiles
    FROM jsonb_array_elements(v_day.tiles) t
    LEFT JOIN public.ca_daily_bonus_claims cl
      ON cl.user_id = v_uid AND cl.bonus_date = v_today AND cl.slot = (t->>'slot')::int;

  SELECT jsonb_agg(jsonb_build_object(
    'day', d, 'streak', v_day.streak - v_day.cycle_day + d,
    'diamonds', CASE WHEN d = v_day.cycle_day THEN
      (SELECT sum((t->>'diamonds')::integer) FROM jsonb_array_elements(v_day.tiles) t
        WHERE t->>'kind'='diamonds' AND NOT (t->>'vip_only')::boolean) ELSE NULL END,
    'extras', 'Daily Rewards',
    'chest', d=v_day.cycle_day AND v_day.streak_day IS NOT NULL,
    'state', CASE WHEN d<v_day.cycle_day THEN 'done' WHEN d=v_day.cycle_day THEN 'today' ELSE 'upcoming' END
  ) ORDER BY d) INTO v_week FROM generate_series(1,7) d;

  v_next_streak := v_day.streak + 1;
  v_next_cycle  := ((v_next_streak - 1) % 7) + 1;
  v_next := public.fn_ca_daily_bonus_pick_tiles(v_uid, v_today + 1, v_next_streak, v_day.tiles);
  SELECT jsonb_agg(CASE WHEN (d->>'day')::integer<>v_day.cycle_day
      AND (d->>'streak')::integer>0 AND (d->>'streak')::integer % 10=0
    THEN d || jsonb_build_object('extras',concat_ws(', ',NULLIF(d->>'extras',''),'100 Diamond Bonus Spin'))
    ELSE d END ORDER BY (d->>'day')::integer) INTO v_week FROM jsonb_array_elements(v_week) d;

  -- PHASE 3. What the player holds: shields (unspent, unexpired credits) and
  -- a live Mission Boost, and whether a shield saved today's streak.
  SELECT jsonb_build_object(
           'held', COALESCE(sum(f.uses_remaining), 0),
           'expires_at', min(f.expires_at))
    INTO v_shield
    FROM public.feature_purchases f
   WHERE f.user_id = v_uid AND f.feature = 'streak_shield'
     AND f.uses_remaining > 0 AND (f.expires_at IS NULL OR f.expires_at > now());
  SELECT jsonb_build_object(
           'active', true, 'factor', b.factor, 'kind', b.kind,
           'ends_at', b.ends_at,
           'seconds_left', GREATEST(0, floor(extract(epoch FROM (b.ends_at - now())))::integer),
           'applied_diamonds', b.applied_diamonds)
    INTO v_boost
    FROM public.player_boosts b
   WHERE b.user_id = v_uid AND b.kind = 'mission_diamonds' AND b.starts_at <= now() AND b.ends_at > now()
   ORDER BY b.ends_at DESC LIMIT 1;

  RETURN jsonb_build_object(
    'eligible', true,
    'bonus_spin_every_days',10,
    'bonus_spin_entry_diamonds',100,
    'bonus_spins_held',(SELECT count(*) FROM public.diamond_bonus_spin_tickets WHERE user_id=v_uid AND redeemed_spin_id IS NULL),
    'today', v_today,
    'reset_at', v_reset_at,
    'seconds_to_reset', GREATEST(0, floor(extract(epoch FROM (v_reset_at - now())))::integer),
    'streak', v_day.streak,
    'cycle_day', v_day.cycle_day,
    'streak_day', v_day.streak_day,
    'multiplier', public.fn_get_streak_multiplier(v_day.streak),
    'is_vip', v_is_vip,
    'claimed_today', v_day.first_claimed_at IS NOT NULL,
    'shown_today', v_day.sheet_shown_at IS NOT NULL,
    'unclaimed', (SELECT count(*) FROM jsonb_array_elements(v_tiles) x
                   WHERE NOT (x->>'claimed')::boolean AND NOT (x->>'locked')::boolean),
    'tiles', v_tiles,
    'week', v_week,
    'tomorrow', v_next,
    'caps', v_caps,
    'cents_per_diamond', 1,
    'shield', COALESCE(v_shield, jsonb_build_object('held', 0, 'expires_at', NULL)),
    'streak_protected', COALESCE(v_day.streak_protected, false),
    'boost', COALESCE(v_boost, jsonb_build_object('active', false))
  );
END;
$$;


ALTER FUNCTION public.fn_ca_daily_bonus_status() OWNER TO postgres;

--
-- TOC entry 5213 (class 1255 OID 25694992)
-- Name: fn_ca_daily_bonus_velocity_check(date, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_daily_bonus_velocity_check(p_today date, p_claimed_from jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  c_device_users CONSTANT integer := 3;
  c_ip_users     CONSTANT integer := 6;
  v_device text := p_claimed_from->>'device_id';
  v_ip     text := p_claimed_from->>'ip_class';
  v_n      integer;
BEGIN
  IF v_device IS NOT NULL THEN
    SELECT count(DISTINCT user_id) INTO v_n FROM public.ca_daily_bonus_claims
     WHERE bonus_date = p_today AND claimed_from->>'device_id' = v_device;
    IF v_n >= c_device_users AND NOT EXISTS (
         SELECT 1 FROM public.financial_alerts a
          WHERE a.source = 'fn_ca_daily_bonus_claim.device_velocity'
            AND a.context->>'device_id' = v_device AND a.context->>'bonus_date' = p_today::text) THEN
      INSERT INTO public.financial_alerts (severity, source, message, context)
      VALUES ('warning', 'fn_ca_daily_bonus_claim.device_velocity',
              format('%s accounts claimed the daily bonus from one device today', v_n),
              jsonb_build_object('device_id', v_device, 'bonus_date', p_today, 'accounts', v_n,
                                 'users', (SELECT jsonb_agg(DISTINCT user_id) FROM public.ca_daily_bonus_claims
                                            WHERE bonus_date = p_today AND claimed_from->>'device_id' = v_device)));
    END IF;
  END IF;
  IF v_ip IS NOT NULL THEN
    SELECT count(DISTINCT user_id) INTO v_n FROM public.ca_daily_bonus_claims
     WHERE bonus_date = p_today AND claimed_from->>'ip_class' = v_ip;
    IF v_n >= c_ip_users AND NOT EXISTS (
         SELECT 1 FROM public.financial_alerts a
          WHERE a.source = 'fn_ca_daily_bonus_claim.ip_velocity'
            AND a.context->>'ip_class' = v_ip AND a.context->>'bonus_date' = p_today::text) THEN
      INSERT INTO public.financial_alerts (severity, source, message, context)
      VALUES ('warning', 'fn_ca_daily_bonus_claim.ip_velocity',
              format('%s accounts claimed the daily bonus from one network today', v_n),
              jsonb_build_object('ip_class', v_ip, 'bonus_date', p_today, 'accounts', v_n));
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION public.fn_ca_daily_bonus_velocity_check(p_today date, p_claimed_from jsonb) OWNER TO postgres;

--
-- TOC entry 8003 (class 1255 OID 26711881)
-- Name: fn_ca_declare_guard_redefinition(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_declare_guard_redefinition(p_proname text, p_ref text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hash text;
  v_def text;
BEGIN
  /* A DECLARED GUARD CHANGE IS RECORDED, NOT RAISED (2026-09-10).
     Call this from a migration that deliberately redefines a watched guard,
     in the SAME transaction as the redefinition, passing the migration name.
     It moves the baseline to the definition this transaction just produced,
     so fn_ca_guard_defs_watch has nothing to report. A change nobody declares
     still moves the hash away from the baseline and still raises. */
  IF COALESCE(btrim(p_ref), '') = '' THEN
    RAISE EXCEPTION 'a guard redefinition must name the migration that made it';
  END IF;
  IF NOT (p_proname = ANY (public.fn_ca_guard_watchlist())) THEN
    RAISE EXCEPTION 'fn_ca_declare_guard_redefinition called for %, which is not on the guard watchlist', p_proname;
  END IF;

  SELECT md5(string_agg(pg_get_functiondef(p.oid), '|' ORDER BY p.oid)),
         string_agg(pg_get_functiondef(p.oid), '|' ORDER BY p.oid)
    INTO v_hash, v_def
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public' AND p.proname = p_proname;

  IF v_hash IS NULL THEN
    RAISE EXCEPTION 'guard function % does not exist; a declaration cannot baseline an absent guard', p_proname;
  END IF;

  -- keep the text so any later notice still has something to diff against
  INSERT INTO public.ca_guard_def_history (proname, def_hash, def_text)
  VALUES (p_proname, v_hash, v_def)
  ON CONFLICT (proname, def_hash) DO NOTHING;

  INSERT INTO public.ca_guard_defs (proname, def_hash, declared_ref, declared_at)
  VALUES (p_proname, v_hash, p_ref, now())
  ON CONFLICT (proname) DO UPDATE
    SET def_hash = EXCLUDED.def_hash,
        declared_ref = EXCLUDED.declared_ref,
        declared_at = EXCLUDED.declared_at,
        updated_at = now();

  RETURN v_hash;
END;
$$;


ALTER FUNCTION public.fn_ca_declare_guard_redefinition(p_proname text, p_ref text) OWNER TO postgres;

--
-- TOC entry 6856 (class 1255 OID 18307931)
-- Name: fn_ca_declare_ledger(text, text, uuid, uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_declare_ledger(p_category text, p_counterparty text, p_counterparty_entity uuid DEFAULT NULL::uuid, p_settlement_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_autoskip_tables text[] DEFAULT NULL::text[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_t text;
BEGIN
  -- validate against the LIVE vocabulary so this can never lag a CHECK change
  IF p_category IS NULL OR NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conrelid = 'public.chip_ledger'::regclass
       AND conname = 'chip_ledger_category_check'
       AND pg_get_constraintdef(oid) LIKE '%''' || p_category || '''%') THEN
    RAISE EXCEPTION 'fn_ca_declare_ledger: category % is not in the ledger vocabulary - add it to chip_ledger_category_check FIRST, then declare it', p_category;
  END IF;
  IF p_counterparty IS NULL OR NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conrelid = 'public.chip_ledger'::regclass
       AND conname = 'chip_ledger_from_type_check'
       AND pg_get_constraintdef(oid) LIKE '%''' || p_counterparty || '''%') THEN
    RAISE EXCEPTION 'fn_ca_declare_ledger: counterparty % is not in the ledger vocabulary - add it to the from/to type CHECKs FIRST, then declare it', p_counterparty;
  END IF;

  PERFORM set_config('app.ledger_category', p_category, true);
  PERFORM set_config('app.ledger_counterparty', p_counterparty, true);
  PERFORM set_config('app.ledger_counterparty_entity',
                     COALESCE(p_counterparty_entity::text, ''), true);
  /* A COUNTERPARTY NAMES ITS COLUMN, AND A NEW DECLARATION FORGETS THE LAST
     ONE'S (2026-10-04). A union wallet holds six balances; the caller whose
     counterparty is one of them names it on app.ledger_counterparty_label
     after this call, and fn_ca_autoledger writes it on that side. */
  PERFORM set_config('app.ledger_counterparty_label', '', true);
  IF p_settlement_id IS NOT NULL THEN
    PERFORM set_config('app.ledger_settlement', p_settlement_id::text, true);
  END IF;
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM set_config('app.ledger_idempotency_key', p_idempotency_key, true);
  END IF;
  IF p_autoskip_tables IS NOT NULL THEN
    FOREACH v_t IN ARRAY p_autoskip_tables LOOP
      IF v_t !~ '^[a-z_]+$' THEN
        RAISE EXCEPTION 'fn_ca_declare_ledger: bad autoskip table name %', v_t;
      END IF;
      PERFORM set_config('app.ledger_autoskip_' || v_t, '1', true);
    END LOOP;
  END IF;
END $_$;


ALTER FUNCTION public.fn_ca_declare_ledger(p_category text, p_counterparty text, p_counterparty_entity uuid, p_settlement_id uuid, p_idempotency_key text, p_autoskip_tables text[]) OWNER TO postgres;

--
-- TOC entry 8587 (class 1255 OID 141333192)
-- Name: fn_ca_deleted_account_bank_return(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_deleted_account_bank_return(p_club uuid, p_user uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ SELECT public.fn_ca_deleted_wallet_bank_return(p_club,p_user,'wallets') $$;


ALTER FUNCTION public.fn_ca_deleted_account_bank_return(p_club uuid, p_user uuid) OWNER TO postgres;

--
-- TOC entry 8368 (class 1255 OID 177725838)
-- Name: fn_ca_deleted_account_leaves_every_club(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_deleted_account_leaves_every_club(p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET lock_timeout TO '4s'
    AS $$
DECLARE
  v_club uuid;
  v_ret jsonb;
  v_returned numeric := 0;
  v_rehomed integer := 0;
  v_reparented integer := 0;
  v_suspended integer := 0;
  v_departed integer := 0;
  v_n integer;
  r record;
  v_cursor uuid;
  v_target uuid;
  v_hops integer;
BEGIN
  IF p_user IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_user');
  END IF;
  PERFORM 1 FROM public.profiles p WHERE p.id = p_user AND p.status = 'deleted';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'account_not_deleted');
  END IF;

  -- Serialise with every cashier writer the way fn_close_account does: the
  -- hierarchy lock of each club involved, in one order.
  FOR v_club IN
    SELECT s.club_id FROM (
      SELECT m.club_id FROM public.club_members m
       WHERE m.user_id = p_user OR m.agent_id = p_user OR m.parent_agent_id = p_user
      UNION
      SELECT a.club_id FROM public.agents a WHERE a.user_id = p_user
    ) s
    JOIN public.clubs c ON c.id = s.club_id AND c.lifecycle_status = 'active'
    ORDER BY s.club_id
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:' || v_club::text, 0));
  END LOOP;

  -- (a) Free club chips go to the main bank through the recorded movement.
  -- On the deletion path zzzz_deleted_profile_bank_return has already done
  -- this; only a wallet still holding free chips is visited, so an empty one
  -- never takes its club's bank row lock a second time.
  FOR v_club IN
    SELECT s.club_id FROM (
      SELECT m.club_id FROM public.club_members m
       WHERE m.user_id = p_user
         AND coalesce(m.chip_balance, 0) - coalesce(m.held_chips, 0) - coalesce(m.locked_chips, 0) > 0
      UNION
      SELECT a.club_id FROM public.agents a
       WHERE a.user_id = p_user AND coalesce(a.agent_wallet_balance, 0) > 0
    ) s
    JOIN public.clubs c ON c.id = s.club_id
     AND c.lifecycle_status = 'active' AND c.asset = 'chips'
    ORDER BY s.club_id
  LOOP
    v_ret := public.fn_ca_deleted_wallet_bank_return(v_club, p_user, 'wallets');
    IF coalesce(v_ret ->> 'success', 'false') <> 'true' THEN
      RAISE EXCEPTION 'ACCOUNT_CUSTODY_UNSETTLED: bank_return %', v_ret USING ERRCODE = '23514';
    END IF;
    v_returned := v_returned + coalesce((v_ret ->> 'amount')::numeric, 0);
  END LOOP;

  -- (b) Nothing else may be stranded by the departure. Close Account refuses
  -- the same custody; any other deletion path is refused here, atomically.
  IF EXISTS (
    SELECT 1 FROM public.club_members m
      JOIN public.clubs c ON c.id = m.club_id AND c.lifecycle_status = 'active'
     WHERE m.user_id = p_user
       AND m.membership_lifecycle_status = 'active'
       AND abs(coalesce(m.chip_balance, 0)) + abs(coalesce(m.held_chips, 0))
         + abs(coalesce(m.locked_chips, 0)) + abs(coalesce(m.promo_balance, 0))
         + abs(coalesce(m.credit_used, 0)) + abs(coalesce(m.diamonds, 0)) <> 0
  ) THEN
    RAISE EXCEPTION 'ACCOUNT_CUSTODY_UNSETTLED: club_balance' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.agents a
      JOIN public.clubs c ON c.id = a.club_id AND c.lifecycle_status = 'active'
     WHERE a.user_id = p_user
       AND abs(coalesce(a.agent_wallet_balance, 0)) + abs(coalesce(a.promo_wallet_balance, 0))
         + abs(coalesce(a.credit_used, 0)) <> 0
  ) THEN
    RAISE EXCEPTION 'ACCOUNT_CUSTODY_UNSETTLED: agent_wallet' USING ERRCODE = '23514';
  END IF;

  -- (c) Live members under the deleted account move to the nearest live
  -- upline above it: a member that is not deleted, holds an active membership
  -- and is either an active agent or club staff. None found -> club direct.
  FOR r IN
    SELECT m.club_id, m.user_id, (m.agent_id = p_user) AS via_agent,
           (m.parent_agent_id = p_user) AS via_parent
      FROM public.club_members m
      JOIN public.clubs c ON c.id = m.club_id AND c.lifecycle_status = 'active'
     WHERE (m.agent_id = p_user OR m.parent_agent_id = p_user)
       AND m.user_id <> p_user
       AND m.membership_lifecycle_status = 'active'
       AND NOT EXISTS (SELECT 1 FROM public.profiles dp WHERE dp.id = m.user_id AND dp.status = 'deleted')
     ORDER BY m.club_id, m.user_id
  LOOP
    v_target := NULL;
    v_cursor := p_user;
    v_hops := 0;
    WHILE v_hops < 64 LOOP
      SELECT up.agent_id INTO v_cursor
        FROM public.club_members up
       WHERE up.club_id = r.club_id AND up.user_id = v_cursor;
      EXIT WHEN NOT FOUND OR v_cursor IS NULL OR v_cursor = r.user_id;
      IF NOT EXISTS (SELECT 1 FROM public.profiles dp WHERE dp.id = v_cursor AND dp.status = 'deleted')
         AND EXISTS (
           SELECT 1 FROM public.club_members live
            WHERE live.club_id = r.club_id AND live.user_id = v_cursor
              AND live.membership_lifecycle_status = 'active'
              AND coalesce(live.status, 'active') IN ('active', 'approved')
              AND (live.role IN ('owner', 'club_owner', 'co_owner', 'admin', 'club_admin')
                   OR EXISTS (SELECT 1 FROM public.agents la
                               WHERE la.club_id = r.club_id AND la.user_id = v_cursor
                                 AND la.status = 'active'))) THEN
        v_target := v_cursor;
        EXIT;
      END IF;
      v_hops := v_hops + 1;
    END LOOP;

    UPDATE public.club_members m
       SET agent_id = CASE WHEN r.via_agent THEN v_target ELSE m.agent_id END,
           parent_agent_id = CASE WHEN r.via_parent THEN v_target ELSE m.parent_agent_id END,
           updated_at = clock_timestamp()
     WHERE m.club_id = r.club_id AND m.user_id = r.user_id;
    v_rehomed := v_rehomed + 1;
  END LOOP;

  -- (d) Live agent rows under the deleted account's agent rows move to the
  -- nearest live agent row above it (active, not a sub-agent), else none.
  FOR r IN
    SELECT ch.id, ch.club_id, da.parent_agent_id AS start_parent
      FROM public.agents da
      JOIN public.clubs c ON c.id = da.club_id AND c.lifecycle_status = 'active'
      JOIN public.agents ch ON ch.parent_agent_id = da.id AND ch.club_id = da.club_id
     WHERE da.user_id = p_user
       AND ch.user_id <> p_user
       AND NOT EXISTS (SELECT 1 FROM public.profiles dp WHERE dp.id = ch.user_id AND dp.status = 'deleted')
     ORDER BY ch.club_id, ch.id
  LOOP
    v_target := NULL;
    v_cursor := r.start_parent;
    v_hops := 0;
    WHILE v_cursor IS NOT NULL AND v_hops < 64 LOOP
      IF EXISTS (
        SELECT 1 FROM public.agents pa
          JOIN public.profiles pp ON pp.id = pa.user_id
         WHERE pa.id = v_cursor AND pa.club_id = r.club_id
           AND pa.status = 'active' AND pa.role <> 'sub_agent'
           AND pp.status IS DISTINCT FROM 'deleted') THEN
        v_target := v_cursor;
        EXIT;
      END IF;
      SELECT pa.parent_agent_id INTO v_cursor
        FROM public.agents pa WHERE pa.id = v_cursor AND pa.club_id = r.club_id;
      IF NOT FOUND THEN v_cursor := NULL; END IF;
      v_hops := v_hops + 1;
    END LOOP;

    UPDATE public.agents a
       SET parent_agent_id = v_target, updated_at = clock_timestamp()
     WHERE a.id = r.id AND a.club_id = r.club_id;
    v_reparented := v_reparented + 1;
  END LOOP;

  -- (e) The deleted account holds no agent authority anywhere.
  UPDATE public.agents a
     SET status = 'suspended', updated_at = clock_timestamp()
    FROM public.clubs c
   WHERE c.id = a.club_id AND c.lifecycle_status = 'active'
     AND a.user_id = p_user AND a.status <> 'suspended';
  GET DIAGNOSTICS v_suspended = ROW_COUNT;

  -- (f) Depart every membership exactly as Close Account does. The row stays
  -- for the journals; it is no longer a member of anything.
  INSERT INTO public.audit_trail(
    actor_id, actor_role, action, target_type, target_id, club_id,
    before_state, after_state, reason
  )
  SELECT p_user, 'system', 'depart_club_member', 'membership', m.user_id, m.club_id,
         jsonb_build_object('user_id', m.user_id, 'role', m.role,
                            'status', m.status::text,
                            'membership_lifecycle_status', m.membership_lifecycle_status),
         jsonb_build_object('departed', true, 'is_active', false,
                            'membership_lifecycle_status', 'departed',
                            'user_id', m.user_id),
         'Account Deleted'
    FROM public.club_members m
    JOIN public.clubs c ON c.id = m.club_id
   WHERE m.user_id = p_user
     AND m.membership_lifecycle_status = 'active'
     AND c.lifecycle_status = 'active';

  PERFORM set_config('app.club_membership_lifecycle_write', 'depart', true);
  UPDATE public.club_members m
     SET status = CASE WHEN c.asset = 'diamonds' THEN m.status ELSE 'suspended' END,
         is_active = false,
         membership_lifecycle_status = 'departed',
         departed_at = clock_timestamp(),
         departed_by = p_user,
         departure_reason = 'Account Deleted',
         display_name = NULL,
         updated_at = clock_timestamp()
    FROM public.clubs c
   WHERE c.id = m.club_id
     AND m.user_id = p_user
     AND m.membership_lifecycle_status = 'active'
     AND c.lifecycle_status = 'active';
  GET DIAGNOSTICS v_departed = ROW_COUNT;
  PERFORM set_config('app.club_membership_lifecycle_write', '', true);

  RETURN jsonb_build_object(
    'success', true,
    'user_id', p_user,
    'returned_to_bank', v_returned,
    'downline_rehomed', v_rehomed,
    'agents_reparented', v_reparented,
    'agent_rows_suspended', v_suspended,
    'memberships_departed', v_departed
  );
END;
$$;


