--
-- TOC entry 5994 (class 1255 OID 72765960)
-- Name: fn_ca_diamond_incident_pages(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_incident_pages() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_episode bigint;
  v_found   text;
  v_state   text;
  v_msg     text;
BEGIN
  /* A CRITICAL DIAMOND ROW REACHES A PHONE (2026-09-29, Diamond Phase 10).
     Fired only for a critical row (the trigger's WHEN clause), after the row
     is written and inside the writer's own transaction, so a writer that
     rolls back takes its page with it.

     One drift incident per rule and episode, filed through the estate's own
     door, so the recipient registry, the notify ledger, the escalation tick
     and the push carry it exactly as they carry a chip finding. The key is
     diamond-rule:<rule>:<episode>. While the rule's incident is open, every
     new critical row of the rule has the same key and folds into it
     (occurrences, last_seen_at, a recurred event), so a condition the health
     watch re-files every hour pages once. The episode is one more than the
     rule's incidents already closed: after a person closes it, or the
     escalation tick ages it out, the next critical row is a new finding and
     pages again. A key stable for the life of the rule would page once in
     its life, because the notify ledger remembers every finding it has paged
     and never learns that one was closed. Two writers filing a rule's first
     row at once compute the same key and meet at the open-incident unique
     index, so they page once between them.

     The amount in doubt is the row's amount. The incident names no club,
     union, table or event, so it is a platform finding and the Midway scope
     keeps it. The row's own detail is nested in the metadata, never merged,
     for the same reason.

     Paging must never cost the row it pages for: every failure is recorded
     in ca_incident_file_failures and swallowed. */
  SELECT count(*) + 1 INTO v_episode
    FROM public.ca_drift_incidents d
   WHERE d.source = 'ca_diamond_incidents'
     AND d.status = 'resolved'
     AND d.metadata->>'rule' = NEW.rule;

  v_found := COALESCE(
    (SELECT string_agg(COALESCE(a->>'area', '?') || ': ' || COALESCE(a->>'detail', a::text), '; ')
       FROM jsonb_array_elements(CASE WHEN jsonb_typeof(NEW.detail->'detail') = 'array'
                                      THEN NEW.detail->'detail' ELSE '[]'::jsonb END) a),
    NULLIF(NEW.detail->>'note', ''),
    NULLIF(NEW.detail::text, '{}'),
    'no detail recorded');

  PERFORM public.fn_ca_raise_drift_incident(
    p_source          => 'ca_diamond_incidents',
    p_classification  => 'unknown',
    p_severity        => NEW.severity,
    p_dedupe_key      => 'diamond-rule:' || NEW.rule || ':' || v_episode::text,
    p_discrepancy     => NEW.amount,
    p_layer           => 'ledger',
    p_entity_type     => 'ca_diamond_incidents',
    p_suspected_cause => left('Diamond rule ' || NEW.rule || ' ('
                              || COALESCE(NEW.writer, 'unknown writer') || '): ' || v_found, 300),
    p_metadata        => jsonb_build_object(
                           'asset', 'diamonds',
                           'rule', NEW.rule,
                           'diamond_incident_id', NEW.id,
                           'writer', NEW.writer,
                           'user_id', NEW.user_id,
                           'occurred_at', NEW.occurred_at,
                           'detail', NEW.detail));
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
  BEGIN
    INSERT INTO public.ca_incident_file_failures
      (source, dedupe_key, classification, severity, discrepancy, sqlstate, message)
    VALUES ('ca_diamond_incidents', 'diamond-rule:' || COALESCE(NEW.rule, '?'), 'unknown',
            NEW.severity, NEW.amount, v_state,
            'a critical Diamond incident (ca_diamond_incidents ' || NEW.id || ') was not paged: ' || v_msg);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  RAISE WARNING 'fn_ca_diamond_incident_pages(%) failed: %', NEW.rule, v_msg;
  RETURN NULL;
END $$;


ALTER FUNCTION public.fn_ca_diamond_incident_pages() OWNER TO postgres;

--
-- TOC entry 5781 (class 1255 OID 72733089)
-- Name: fn_ca_diamond_incident_person_hold(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_incident_person_hold() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_setting('ca.diamond_incident_review', true) = 'person' THEN
    RETURN NEW;
  END IF;
  -- A resolution a person wrote stands: nothing but the review door re-opens,
  -- re-closes or rewrites it.
  IF OLD.resolved_by IS NOT NULL
     AND (NEW.resolved_at, NEW.resolved_by, NEW.resolution)
         IS DISTINCT FROM (OLD.resolved_at, OLD.resolved_by, OLD.resolution) THEN
    RETURN NULL;
  END IF;
  -- A row a person reopened is closed by a person.
  IF OLD.resolved_at IS NULL AND OLD.reopened_by IS NOT NULL AND NEW.resolved_at IS NOT NULL THEN
    RETURN NULL;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_diamond_incident_person_hold() OWNER TO postgres;

--
-- TOC entry 4510 (class 1255 OID 72733101)
-- Name: fn_ca_diamond_incident_resolve_family(text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_incident_resolve_family(p_family text, p_severity text, p_filed_before timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_family text := NULLIF(btrim(COALESCE(p_family, '')), '');
  v_note text := NULLIF(btrim(COALESCE(p_reason, '')), '');
  v_before timestamptz := LEAST(COALESCE(p_filed_before, now()), now());
  v_act uuid := gen_random_uuid();
  v_label text;
  v_held integer;
  v_resolved integer;
  v_by_rule jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication_required');
  END IF;
  IF NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'staff_required');
  END IF;
  IF NOT public.fn_caller_session_is_live() THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication_required');
  END IF;
  IF v_family IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'family_required');
  END IF;
  IF p_severity IS NOT NULL AND p_severity NOT IN ('info', 'warning', 'critical') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_severity');
  END IF;
  IF length(v_note) > 2000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'note_too_long');
  END IF;
  IF COALESCE(length(v_note), 0) < 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'reason_required');
  END IF;
  v_label := public.fn_ca_diamond_incident_actor_label(v_uid);

  SELECT count(*) INTO v_held
    FROM public.ca_diamond_incidents i
   WHERE (i.rule = v_family OR (strpos(v_family, ':') = 0 AND split_part(i.rule, ':', 1) = v_family))
     AND (p_severity IS NULL OR i.severity = p_severity)
     AND i.resolved_at IS NULL AND i.occurred_at <= v_before
     AND i.reopened_by IS NOT NULL;

  PERFORM set_config('ca.diamond_incident_review', 'person', true);
  WITH closed AS (
    UPDATE public.ca_diamond_incidents i
       SET resolved_at = now(), resolved_by = v_uid, resolution = v_note
     WHERE (i.rule = v_family OR (strpos(v_family, ':') = 0 AND split_part(i.rule, ':', 1) = v_family))
       AND (p_severity IS NULL OR i.severity = p_severity)
       AND i.resolved_at IS NULL AND i.occurred_at <= v_before
       AND i.reopened_by IS NULL
    RETURNING i.id, i.rule, i.severity
  ), logged AS (
    INSERT INTO public.ca_diamond_incident_events (incident_id, kind, actor, actor_label, detail)
    SELECT c.id, 'resolved', v_uid, v_label,
           jsonb_build_object('note', v_note, 'rule', c.rule, 'severity', c.severity, 'act', v_act,
                              'family', v_family, 'severity_filter', p_severity,
                              'filed_before', v_before)
      FROM closed c
    RETURNING incident_id
  )
  SELECT (SELECT count(*) FROM logged),
         COALESCE((SELECT jsonb_object_agg(g.rule, g.n)
                     FROM (SELECT c.rule, count(*) AS n FROM closed c GROUP BY c.rule) g), '{}'::jsonb)
    INTO v_resolved, v_by_rule;
  PERFORM set_config('ca.diamond_incident_review', '', true);

  IF v_resolved = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'nothing_to_resolve', 'skipped_reopened', v_held);
  END IF;
  RETURN jsonb_build_object('success', true, 'act_id', v_act, 'family', v_family,
    'severity', p_severity, 'filed_before', v_before, 'resolved', v_resolved,
    'skipped_reopened', v_held, 'by_rule', v_by_rule);
END $$;


ALTER FUNCTION public.fn_ca_diamond_incident_resolve_family(p_family text, p_severity text, p_filed_before timestamp with time zone, p_reason text) OWNER TO postgres;

--
-- TOC entry 6104 (class 1255 OID 72733099)
-- Name: fn_ca_diamond_incident_review(bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_incident_review(p_incident_id bigint, p_action text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_note text := NULLIF(btrim(COALESCE(p_note, '')), '');
  v_row public.ca_diamond_incidents;
  v_label text;
  v_event bigint;
  v_previous jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication_required');
  END IF;
  IF NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'staff_required');
  END IF;
  IF NOT public.fn_caller_session_is_live() THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication_required');
  END IF;
  IF p_action IS NULL OR p_action NOT IN ('acknowledge', 'comment', 'resolve', 'reopen') THEN
    RETURN jsonb_build_object('success', false, 'error', 'unknown_action');
  END IF;
  IF length(v_note) > 2000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'note_too_long');
  END IF;
  IF p_action = 'comment' AND v_note IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'note_required');
  END IF;
  IF p_action IN ('resolve', 'reopen') AND COALESCE(length(v_note), 0) < 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'reason_required');
  END IF;

  SELECT * INTO v_row FROM public.ca_diamond_incidents WHERE id = p_incident_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'incident_not_found');
  END IF;
  v_label := public.fn_ca_diamond_incident_actor_label(v_uid);

  IF p_action = 'acknowledge' THEN
    IF v_row.resolved_at IS NOT NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'already_resolved',
                                'incident', public.fn_ca_diamond_incident_json(v_row));
    END IF;
    IF v_row.acknowledged_at IS NOT NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'already_acknowledged',
                                'incident', public.fn_ca_diamond_incident_json(v_row));
    END IF;
    PERFORM set_config('ca.diamond_incident_review', 'person', true);
    UPDATE public.ca_diamond_incidents
       SET acknowledged_at = now(), acknowledged_by = v_uid
     WHERE id = p_incident_id
    RETURNING * INTO v_row;
    PERFORM set_config('ca.diamond_incident_review', '', true);
  ELSIF p_action = 'resolve' THEN
    IF v_row.resolved_at IS NOT NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'already_resolved',
                                'incident', public.fn_ca_diamond_incident_json(v_row));
    END IF;
    PERFORM set_config('ca.diamond_incident_review', 'person', true);
    UPDATE public.ca_diamond_incidents
       SET resolved_at = now(), resolved_by = v_uid, resolution = v_note
     WHERE id = p_incident_id
    RETURNING * INTO v_row;
    PERFORM set_config('ca.diamond_incident_review', '', true);
  ELSIF p_action = 'reopen' THEN
    IF v_row.resolved_at IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'not_resolved',
                                'incident', public.fn_ca_diamond_incident_json(v_row));
    END IF;
    v_previous := jsonb_build_object(
      'resolved_at', v_row.resolved_at, 'resolved_by', v_row.resolved_by,
      'resolution', v_row.resolution,
      'closed_by', public.fn_ca_diamond_incident_json(v_row) -> 'closed_by',
      'acknowledged_at', v_row.acknowledged_at, 'acknowledged_by', v_row.acknowledged_by);
    PERFORM set_config('ca.diamond_incident_review', 'person', true);
    UPDATE public.ca_diamond_incidents
       SET resolved_at = NULL, resolved_by = NULL, resolution = NULL,
           acknowledged_at = NULL, acknowledged_by = NULL,
           reopened_at = now(), reopened_by = v_uid
     WHERE id = p_incident_id
    RETURNING * INTO v_row;
    PERFORM set_config('ca.diamond_incident_review', '', true);
  END IF;

  INSERT INTO public.ca_diamond_incident_events (incident_id, kind, actor, actor_label, detail)
  VALUES (p_incident_id,
          CASE p_action WHEN 'acknowledge' THEN 'acknowledged' WHEN 'comment' THEN 'comment'
                        WHEN 'resolve' THEN 'resolved' ELSE 'reopened' END,
          v_uid, v_label,
          jsonb_build_object('note', v_note, 'rule', v_row.rule, 'severity', v_row.severity)
            || CASE WHEN v_previous IS NULL THEN '{}'::jsonb
                    ELSE jsonb_build_object('previous', v_previous) END)
  RETURNING id INTO v_event;

  RETURN jsonb_build_object('success', true, 'action', p_action, 'event_id', v_event,
                            'incident', public.fn_ca_diamond_incident_json(v_row));
END $$;


ALTER FUNCTION public.fn_ca_diamond_incident_review(p_incident_id bigint, p_action text, p_note text) OWNER TO postgres;

--
-- TOC entry 8438 (class 1255 OID 72733098)
-- Name: fn_ca_diamond_incident_trail(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_incident_trail(p_incident_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row public.ca_diamond_incidents;
  v_found boolean;
  v_events jsonb;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.fn_is_platform_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'staff_required');
  END IF;
  -- DIAMOND PHASE 11: a signed-out staff token moves nothing here either.
  IF NOT public.fn_caller_session_is_live() THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication_required');
  END IF;
  SELECT * INTO v_row FROM public.ca_diamond_incidents WHERE id = p_incident_id;
  v_found := FOUND;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', e.id, 'incident_id', e.incident_id, 'at', e.at, 'kind', e.kind,
           'actor', e.actor, 'actor_label', e.actor_label, 'detail', e.detail) ORDER BY e.at, e.id), '[]'::jsonb)
    INTO v_events
    FROM public.ca_diamond_incident_events e
   WHERE e.incident_id = p_incident_id;
  IF NOT v_found AND v_events = '[]'::jsonb THEN
    RETURN jsonb_build_object('success', false, 'error', 'incident_not_found');
  END IF;
  RETURN jsonb_build_object('success', true,
    'incident', CASE WHEN v_found THEN public.fn_ca_diamond_incident_json(v_row) END,
    'events', v_events);
END $$;


ALTER FUNCTION public.fn_ca_diamond_incident_trail(p_incident_id bigint) OWNER TO postgres;

--
-- TOC entry 6939 (class 1255 OID 23883895)
-- Name: fn_ca_diamond_journal_classifier(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_journal_classifier() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_type text := COALESCE(NEW.transaction_type, NEW.type, 'unknown');
  v_stack text; v_writer text; v_filled boolean := false;
BEGIN
  IF NEW.issuance_class IS NULL THEN
    v_filled := true;
    NEW.issuance_class := CASE
      WHEN v_type = 'purchase' THEN 'purchased'
      WHEN v_type = 'refund' OR right(v_type, 7) = '_refund' THEN 'refund'
      WHEN v_type IN ('transfer', 'diamond_gift_received', 'live_gift_received', 'diamond_received',
                      'diamond_gift_sent', 'live_gift_sent', 'spend_transfer') THEN 'transferred'
      WHEN v_type = 'adjustment' THEN 'admin'
      WHEN v_type = 'mint' THEN 'admin'
      WHEN v_type = 'burn' THEN 'deletion'
      WHEN v_type IN ('union_grant', 'signup_bonus') THEN 'promotional'
      WHEN COALESCE(NEW.amount, 0) < 0 THEN 'spend'
      WHEN EXISTS (SELECT 1 FROM public.diamond_reward_catalog c WHERE c.action_key = v_type)
           OR COALESCE(NEW.description, '') LIKE 'Diamond Rewards v2:%' THEN 'promotional'
      ELSE 'earned'
    END;
  END IF;
  IF NEW.counterparty IS NULL THEN
    v_filled := true;
    NEW.counterparty := CASE NEW.issuance_class
      WHEN 'purchased' THEN 'purchase_clearing'
      WHEN 'refund' THEN CASE WHEN v_type IN ('refund', 'stripe') THEN 'purchase_clearing' ELSE 'revenue:' || v_type END
      WHEN 'transferred' THEN 'player:' || COALESCE(NEW.metadata->>'recipient_id', NEW.metadata->>'sender_id', 'unknown')
      WHEN 'admin' THEN 'adjustment'
      WHEN 'deletion' THEN 'retired'
      WHEN 'spend' THEN 'revenue:' || v_type
      ELSE 'promo_budget:' || public.fn_ca_diamond_engine_of(NEW.type, NEW.transaction_type, NEW.source, NEW.description, NEW.reference_id)
    END;
  END IF;
  IF v_filled THEN
    BEGIN
      GET DIAGNOSTICS v_stack = PG_CONTEXT;
      SELECT (regexp_match(t.ln, 'function (?:public\.)?([A-Za-z0-9_]+)\('))[1] INTO v_writer
        FROM regexp_split_to_table(COALESCE(v_stack, ''), E'\n') WITH ORDINALITY AS t(ln, ord)
       WHERE t.ln ~ 'function (?:public\.)?[A-Za-z0-9_]+\('
         AND (regexp_match(t.ln, 'function (?:public\.)?([A-Za-z0-9_]+)\('))[1] <> 'fn_ca_diamond_journal_classifier'
       ORDER BY t.ord LIMIT 1;
      PERFORM public.fn_ca_diamond_incident(
        'DR12:journal_row_unclassified_by_writer', 'info', NEW.user_id, NEW.amount,
        COALESCE(v_writer, '(no function frame)'),
        jsonb_build_object('type', NEW.type, 'transaction_type', NEW.transaction_type,
                           'description', left(NEW.description, 120), 'reference_id', NEW.reference_id,
                           'classified_as', NEW.issuance_class, 'counterparty', NEW.counterparty,
                           'note', 'the writer left issuance_class or counterparty NULL; the classifier filled them. Fix the writer.'));
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_ca_diamond_journal_classifier() OWNER TO postgres;

--
-- TOC entry 45697 (class 0 OID 0)
-- Dependencies: 6939
-- Name: FUNCTION fn_ca_diamond_journal_classifier(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_journal_classifier() IS 'DR3 safety net: fills issuance_class and counterparty when a writer leaves them NULL and files DR12 naming the writer. Standard 3.3.';


--
-- TOC entry 8149 (class 1255 OID 27767151)
-- Name: fn_ca_diamond_journal_is_transfer(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_journal_is_transfer(p_type text, p_transaction_type text, p_source text, p_issuance_class text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  WITH v AS (
    SELECT lower(COALESCE(NULLIF(btrim(p_transaction_type), ''), NULLIF(btrim(p_type), ''), '')) AS kind,
           lower(COALESCE(NULLIF(btrim(p_issuance_class), ''), '')) AS class,
           lower(COALESCE(NULLIF(btrim(p_source), ''), '')) AS src
  )
  SELECT CASE
    -- The Mint's own doors register their own rows; the seed door writes its
    -- own 'seed:<id>' row. Neither is a transfer and neither may be judged as
    -- one. Same order, same reasons, as fn_ca_diamond_journal_origin.
    WHEN v.src = 'the_mint' THEN false
    WHEN v.kind = 'signup_bonus' OR v.src = 'handle_new_user' THEN false
    ELSE v.class = 'transferred'
      OR v.kind IN ('transfer', 'diamond_gift_sent', 'diamond_gift_received', 'diamond_received',
                    'live_gift_sent', 'live_gift_received', 'wallet_transfer',
                    'wallet_diamond_transfer', 'stream_gift', 'union_grant_transfer')
      OR v.kind LIKE '%gift%' OR v.kind LIKE '%transfer%'
  END
  FROM v;
$$;


ALTER FUNCTION public.fn_ca_diamond_journal_is_transfer(p_type text, p_transaction_type text, p_source text, p_issuance_class text) OWNER TO postgres;

--
-- TOC entry 45699 (class 0 OID 0)
-- Dependencies: 8149
-- Name: FUNCTION fn_ca_diamond_journal_is_transfer(p_type text, p_transaction_type text, p_source text, p_issuance_class text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_journal_is_transfer(p_type text, p_transaction_type text, p_source text, p_issuance_class text) IS 'Player to player: supply moves, none is created or retired. THE one definition, read by fn_ca_diamond_journal_origin (which skips the register for these rows) and by ab_ca_diamond_transfer_names_its_counterparty (which refuses one that names nobody). Two callers, one rule, so the rule that lets a row out of the register can never drift from the rule that demands it name the other side.';


--
-- TOC entry 5078 (class 1255 OID 21245592)
-- Name: fn_ca_diamond_journal_origin(text, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_journal_origin(p_type text, p_transaction_type text, p_source text, p_issuance_class text, p_amount numeric) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_kind  text := lower(COALESCE(NULLIF(btrim(p_transaction_type), ''), NULLIF(btrim(p_type), ''), ''));
  v_class text := lower(COALESCE(NULLIF(btrim(p_issuance_class), ''), ''));
  v_src   text := lower(COALESCE(NULLIF(btrim(p_source), ''), ''));
BEGIN
  IF p_amount IS NULL OR p_amount = 0 THEN RETURN NULL; END IF;
  -- The Mint's own doors register their own rows.
  IF v_src = 'the_mint' THEN RETURN NULL; END IF;
  -- SO DOES THE SEED DOOR. fn_ca_diamond_born_with_balance writes the
  -- 'seed:<id>' register row for the signup grant and then the journal row.
  -- Registering it here as well counts one movement twice (2026-09-05: 18
  -- duplicate pairs, 9,000 diamonds). Named writer, not a class: every OTHER
  -- promotional credit still registers here.
  IF v_kind = 'signup_bonus' OR v_src = 'handle_new_user' THEN RETURN NULL; END IF;
  -- ADDED 20260930055147. A JOURNAL ROW THAT ONLY WRITES DOWN SUPPLY THE
  -- REGISTER ALREADY COUNTED. The pre-2026-09-01 born-with-balance door moved
  -- profiles.diamonds and the register together and skipped the journal, so
  -- 220,985 diamonds sat in wallets that the journal could not explain while
  -- the register could. The backfill that writes those journal rows must not
  -- register them a second time: fn_ca_mint_supply('diamonds') already equals
  -- what players hold, and following these rows would break that identity by
  -- the exact amount of the backfill. Named source, not a class, for the same
  -- reason as the seed door above: every other admin credit still registers.
  IF v_src = 'journal_backfill' THEN RETURN NULL; END IF;
  -- Player to player: supply moves, none is created or retired.
  IF public.fn_ca_diamond_journal_is_transfer(p_type, p_transaction_type, p_source, p_issuance_class) THEN
    RETURN NULL;
  END IF;
  -- THE ARENA DOORS MOVE MONEY, THEY DO NOT ISSUE IT. A deposit takes diamonds out of
  -- profiles.diamonds and puts them in the platform club's member wallet; a withdrawal is the
  -- mirror. The player still owns them and the supply is unchanged, so the register must not
  -- follow either leg - the same treatment, for the same reason, as a player-to-player transfer
  -- above. Classified as 'spend' (deposit) and 'arena' (withdrawal), the register would have
  -- burned the float on the way in and minted it on the way out (2026-09-08).
  IF v_kind IN ('arena_deposit', 'arena_withdraw') THEN RETURN NULL; END IF;
  -- The deletion door writes its own register row.
  IF v_class = 'deletion' THEN RETURN NULL; END IF;
  -- A test fixture row is not supply the Mint issued.
  IF v_kind LIKE 'test%' THEN RETURN NULL; END IF;

  IF p_amount > 0 THEN
    IF v_class = 'purchased' OR v_kind IN ('purchase', 'stripe_purchase', 'diamond_purchase') THEN
      RETURN 'purchase';
    ELSIF v_class = 'refund' OR v_kind LIKE '%refund%' OR v_kind = 'diamond_refund' THEN
      RETURN 'refund';
    ELSIF v_class = 'promotional' OR v_kind IN ('union_grant', 'bonus', 'promo',
                                                 'promo_purchased', 'easter_egg', 'vip_daily',
                                                 'vip_stipend', 'vip_monthly') THEN
      RETURN 'promotion';
    ELSIF v_class = 'admin' OR v_kind IN ('adjustment', 'reconciliation', 'admin', 'admin_grant') THEN
      RETURN 'adjustment';
    -- 'arcade%' only. The 'arena' CLASS now belongs to the arena doors, which are handled
    -- as transfers above; leaving it here would have made a withdrawal mint.
    ELSIF v_kind LIKE 'arcade%' THEN
      RETURN 'arena';
    ELSE
      RETURN 'reward';
    END IF;
  ELSE
    IF v_kind IN ('chip_mint', 'chip_purchase', 'mint_chips', 'diamonds_to_chips') OR v_class = 'bridge' THEN
      RETURN 'bridge';
    ELSIF v_class = 'admin' OR v_kind IN ('adjustment', 'reconciliation', 'admin', 'chargeback', 'clawback') THEN
      RETURN 'adjustment';
    ELSE
      RETURN 'spend';
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION public.fn_ca_diamond_journal_origin(p_type text, p_transaction_type text, p_source text, p_issuance_class text, p_amount numeric) OWNER TO postgres;

--
-- TOC entry 6892 (class 1255 OID 24489122)
-- Name: fn_ca_diamond_offledger_float(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_offledger_float() RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v numeric;
BEGIN
  -- No arena at all: nothing is parked outside the player wallet, and 0 is the true answer.
  IF to_regprocedure('public.fn_ca_arena_diamonds()') IS NULL THEN
    RETURN 0;
  END IF;

  -- An arena exists, so its float is part of the supply and the books need the real number.
  -- If it cannot be read, RAISE. Returning 0 here would report a balanced set of books that had
  -- simply stopped counting one of the accounts (CLAUDE.md 10.86).
  EXECUTE 'SELECT public.fn_ca_arena_diamonds()' INTO v;
  IF v IS NULL THEN
    RAISE EXCEPTION 'the arena float is unreadable: fn_ca_arena_diamonds() exists and returned NULL. The books will not publish a balance they could not compute.';
  END IF;
  RETURN v;
END $$;


ALTER FUNCTION public.fn_ca_diamond_offledger_float() OWNER TO postgres;

--
-- TOC entry 45702 (class 0 OID 0)
-- Dependencies: 6892
-- Name: FUNCTION fn_ca_diamond_offledger_float(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_offledger_float() IS 'Diamonds a player owns that are not in profiles.diamonds - today the arena float. Returns 0 when no arena exists (the true answer) and RAISES when one exists but cannot be read (never 0, which would be a wrong balance that looks right). THE CONTRACT: whatever parks diamonds outside the player wallet provides public.fn_ca_arena_diamonds(); the books need no other change.';


--
-- TOC entry 3641 (class 1255 OID 24168083)
-- Name: fn_ca_diamond_player_spend(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_player_spend(p_from timestamp with time zone) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- What players spent PLAYING, decided by the register's own authority on what a movement is:
  --   'spend'  - a debit for something in the game (entries, stakes, features, time banks)
  --   'bridge' - diamonds converted into chips, which is a player spending them
  -- and NOT 'adjustment' (the house correcting its books), NOT 'refund' (money going back to a
  -- card), NOT NULL (transfers, the Mint's own doors, seeds and test rows, which move no value
  -- out of the player economy). Fixtures are not players.
  SELECT COALESCE(sum(-dt.amount), 0)::numeric
    FROM public.diamond_transactions dt
   WHERE dt.amount < 0
     AND dt.created_at >= p_from
     AND public.fn_ca_diamond_journal_origin(dt.type, dt.transaction_type, dt.source,
                                             dt.issuance_class, dt.amount) IN ('spend', 'bridge')
     AND NOT public.fn_ca_is_fixture_account(dt.user_id);
$$;


ALTER FUNCTION public.fn_ca_diamond_player_spend(p_from timestamp with time zone) OWNER TO postgres;

