--
-- TOC entry 4954 (class 1255 OID 206024909)
-- Name: fn_ca_diamond_rule_transition_lock(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_rule_transition_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_rule text;
BEGIN
  -- Insert and resolve share the same rule lock before touching drift state.
  -- A concurrent critical cannot be omitted by the last-source-row decision.
  FOR v_rule IN SELECT DISTINCT r FROM (VALUES (NEW.rule),
      (CASE WHEN TG_OP='UPDATE' THEN OLD.rule ELSE NEW.rule END)) keys(r) ORDER BY r LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('ca-diamond-rule:' || v_rule,0));
  END LOOP;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_diamond_rule_transition_lock() OWNER TO postgres;

--
-- TOC entry 8240 (class 1255 OID 71708383)
-- Name: fn_ca_diamond_satellite_target_accepts_new_feeder(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_satellite_target_accepts_new_feeder(p_target_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT COALESCE((SELECT t.format_contract IN ('mtt-v1','mtt-v2')
   AND t.is_bounty IS FALSE AND t.is_pko IS FALSE AND t.is_mystery_bounty IS FALSE
   AND t.is_premium_spin IS FALSE
   AND lower(btrim(COALESCE(t.variant,''))) NOT IN
     ('satellite','spin','bounty','progressive','progressive_bounty','pko','mystery','mystery_bounty')
   AND lower(btrim(COALESCE(t.tournament_type,''))) NOT IN
     ('satellite','spin','bounty','progressive','progressive_bounty','pko','mystery','mystery_bounty')
   AND t.satellite_target_id IS NULL AND t.satellite_target IS NULL
   AND public.fn_poker_diamond_tournament(t.id) IS TRUE
   FROM public.tournaments t WHERE t.id=p_target_id),false);
$$;


