--
-- TOC entry 6673 (class 1255 OID 19182959)
-- Name: fn_ca_diamond_trial_balance(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_trial_balance(p_since timestamp with time zone DEFAULT (now() - '01:15:00'::interval)) RETURNS TABLE(account text, balance_now numeric, balance_delta numeric, journal_net numeric, mint_net numeric, difference numeric, note text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c_foundation constant timestamptz := timestamptz '2026-09-03 00:07:00+00';
  v_since   timestamptz := COALESCE(p_since, now() - interval '75 minutes');
  s0        public.ca_diamond_snapshots%ROWTYPE;
  w0        timestamptz;
  v_players numeric; v_house numeric; v_reg numeric; v_reg_players numeric; v_reg_house numeric;
  v_fix numeric; v_reg_fix numeric; v_fix_n bigint;
  v_delta   numeric; v_jrn numeric; v_jrn_live numeric; v_jrn_archive numeric; v_mint numeric;
  v_diff    numeric; v_note text; v_n bigint; v_sub numeric; v_tmp numeric;
  v_house_ledger numeric;
  v_arena numeric; v_arena_fix numeric;
  v_tot_now numeric := 0; v_tot_delta numeric := 0; v_tot_jrn numeric := 0; v_tot_mint numeric := 0;
  r record;
BEGIN
  SELECT * INTO s0 FROM public.ca_diamond_snapshots WHERE taken_at >= v_since ORDER BY taken_at ASC LIMIT 1;
  -- A MISSED SNAPSHOT IS NOT AN UNKNOWN BALANCE, FOR ANY READER (2026-10-04). When the
  -- hourly snapshot did not land (2026-10-01 16:10 and 17:10, 2026-10-03 19:10) there is
  -- no snapshot inside the window, and every movement comparison below came back NULL.
  -- The comparisons are stock against stored stock, so the newest snapshot BEFORE the
  -- window answers the same question over a longer span, and the note names the snapshot
  -- it measured from. fn_ca_diamond_health has passed that snapshot in by hand since
  -- 2026-10-03; the hourly watch and the staff desk did not. No snapshot at all still
  -- reads unknown.
  IF s0.id IS NULL THEN
    SELECT * INTO s0 FROM public.ca_diamond_snapshots WHERE taken_at < v_since ORDER BY taken_at DESC LIMIT 1;
  END IF;
  w0 := COALESCE(s0.taken_at, v_since);

  -- ONE statement, ONE snapshot (2026-09-07 review fix 4), so a signup committing between two reads
  -- cannot show as a 500 break for one run.
  -- THE REGISTER IS READ ONCE, AND THE FIXTURE QUESTION IS ASKED ONCE PER HOLDER
  -- (2026-10-04): see fn_ca_diamond_snapshot. Three passes over the Diamond register,
  -- one of them calling fn_ca_is_fixture_account for every ledger row, are one pass
  -- netted per holder. Same rows, same sums, same SQL snapshot.
  WITH reg AS MATERIALIZED (
    SELECT m.holder_type, m.holder_id,
           SUM(CASE WHEN m.action = 'mint' THEN m.amount ELSE -m.amount END) AS net
      FROM public.ca_mint_ledger m
     WHERE m.asset = 'diamonds' AND m.holder_type IN ('player', 'house')
     GROUP BY m.holder_type, m.holder_id)
  SELECT (SELECT COALESCE(SUM(COALESCE(p.diamonds, 0)), 0)::numeric FROM public.profiles p),
         (SELECT COALESCE(SUM(p.diamonds), 0) FROM public.profiles p WHERE public.fn_ca_is_fixture_account(p.id)),
         (SELECT count(*) FROM public.profiles p WHERE public.fn_ca_is_fixture_account(p.id)),
         (SELECT COALESCE(balance, 0) FROM public.ca_diamond_house WHERE id = 1),
         (SELECT COALESCE(SUM(g.net), 0) FROM reg g WHERE g.holder_type = 'player'),
         (SELECT COALESCE(SUM(g.net), 0) FROM reg g WHERE g.holder_type = 'player' AND public.fn_ca_is_fixture_account(g.holder_id)),
         (SELECT COALESCE(SUM(g.net), 0) FROM reg g WHERE g.holder_type = 'house'),
         public.fn_ca_mint_supply('diamonds'), public.fn_ca_arena_diamonds(),
         ((SELECT COALESCE(sum(balance),0) FROM public.poker_diamond_custody WHERE public.fn_ca_is_fixture_account(user_id)) + (SELECT COALESCE(sum(pending_diamonds),0) FROM public.diamond_spin_days WHERE status='open' AND public.fn_ca_is_fixture_account(owner_id)))
    INTO v_players, v_fix, v_fix_n, v_house, v_reg_players, v_reg_fix, v_reg_house, v_reg, v_arena, v_arena_fix;
  v_house := COALESCE(v_house, 0);

  SELECT COALESCE(SUM(dt.amount), 0) INTO v_jrn_live FROM public.diamond_transactions dt WHERE dt.created_at >= w0 AND dt.created_at < now();
  SELECT COALESCE(SUM(a.amount), 0) INTO v_jrn_archive FROM public.ca_diamond_journal_archive a WHERE a.created_at >= w0 AND a.created_at < now();
  v_jrn := v_jrn_live + v_jrn_archive;

  -- player_diamonds: players without the fixture harness, on stored figures.
  IF s0.id IS NULL THEN
    v_delta := NULL; v_mint := NULL; v_diff := NULL;
    v_note := 'no diamond snapshot at or after the window start, so the delta is unknown';
  ELSIF s0.register_supply IS NOT NULL AND s0.fixture_diamonds IS NOT NULL THEN
    v_delta := (v_players - v_fix) - (s0.profile_diamonds - s0.fixture_diamonds);
    v_mint  := (v_reg_players - v_reg_fix) - (s0.register_supply - COALESCE(s0.register_fixture, 0));
    v_diff  := v_delta - v_mint + (v_arena - v_arena_fix - COALESCE(s0.arena_diamonds,0) + COALESCE(s0.arena_fixture_diamonds,0));
    v_note  := 'player balances (fixtures excluded) moved ' || v_delta || ' since the ' || to_char(s0.taken_at AT TIME ZONE 'UTC', 'HH24:MI')
            || ' UTC snapshot; the player register moved ' || v_mint || ' on the same stored figures (no window skew).'
            || ' journal_net over the window is ' || v_jrn || ' (live ' || v_jrn_live || ' + archived ' || v_jrn_archive
            || '), informative: the seed trigger and the Mint house branch write no journal row.';
  ELSIF s0.register_supply IS NOT NULL THEN
    v_delta := v_players - s0.profile_diamonds;
    v_mint  := v_reg_players - s0.register_supply;
    v_diff  := v_delta - v_mint + (v_arena - COALESCE(s0.arena_diamonds,0));
    v_note  := 'transitional: the window snapshot stored the register but not the fixture split, so this row includes the certification harness. journal_net ' || v_jrn || ' informative.';
  ELSE
    v_delta := v_players - s0.profile_diamonds;
    SELECT COALESCE(SUM(CASE WHEN ml.action = 'mint' THEN ml.amount ELSE -ml.amount END), 0) INTO v_mint
      FROM public.ca_mint_ledger ml WHERE ml.asset = 'diamonds' AND ml.holder_type = 'player' AND ml.created_at >= w0 AND ml.created_at < now();
    v_diff := v_delta - v_mint + (v_arena - COALESCE(s0.arena_diamonds,0));
    v_note := 'the window snapshot predates register_supply, so the register is windowed by created_at (boundary skew possible). journal_net ' || v_jrn || ' informative.';
  END IF;
  -- balance_now must be the SAME population balance_delta is measured on, or adding this row
  -- to fixture_accounts double counts the harness (found by the verification pass, 2026-09-08).
  DECLARE v_players_shown numeric := CASE
    WHEN s0.id IS NOT NULL AND s0.register_supply IS NOT NULL AND s0.fixture_diamonds IS NOT NULL
    THEN v_players - v_fix ELSE v_players END;
  BEGIN
    v_tot_now := v_tot_now + v_players_shown; v_tot_delta := v_tot_delta + COALESCE(v_delta, 0);
    v_tot_jrn := v_tot_jrn + v_jrn; v_tot_mint := v_tot_mint + COALESCE(v_mint, 0);
    RETURN QUERY SELECT 'player_diamonds'::text, v_players_shown, v_delta, v_jrn, v_mint, v_diff,
      (v_note || CASE WHEN v_players_shown <> v_players
                      THEN ' balance_now is players WITHOUT the harness (' || v_fix || ' shown on the fixture_accounts row), so the two rows add up.'
                      ELSE '' END)::text;
  END;

  -- fixture_accounts: the certification harness, measured the same way, reported apart.
  IF s0.id IS NOT NULL AND s0.fixture_diamonds IS NOT NULL THEN
    v_delta := v_fix - s0.fixture_diamonds;
    v_mint  := v_reg_fix - COALESCE(s0.register_fixture, 0);
    v_diff  := v_delta - v_mint + (v_arena_fix - COALESCE(s0.arena_fixture_diamonds,0));
    v_note  := format('%s fixture profiles hold %s. Their balances moved %s and their register moved %s; a non-zero difference is the harness writing profiles.diamonds directly (DR6 at info). Never a player, never a horse.', v_fix_n, v_fix, v_delta, v_mint);
  ELSE
    v_delta := NULL; v_mint := NULL; v_diff := NULL;
    v_note := format('%s fixture profiles hold %s diamonds (inside player_diamonds). No stored fixture figure at the window start yet.', v_fix_n, v_fix);
  END IF;
  RETURN QUERY SELECT 'fixture_accounts'::text, v_fix, v_delta, NULL::numeric, v_mint, v_diff, v_note;

  -- diamond_house
  SELECT COALESCE(SUM(delta), 0) INTO v_house_ledger FROM public.ca_diamond_house_ledger WHERE at >= w0 AND at < now();
  SELECT COALESCE(SUM(CASE WHEN ml.action = 'mint' THEN ml.amount ELSE -ml.amount END), 0) INTO v_mint
    FROM public.ca_mint_ledger ml WHERE ml.asset = 'diamonds' AND ml.holder_type = 'house' AND ml.created_at >= w0 AND ml.created_at < now();
  IF s0.id IS NOT NULL AND s0.house_balance IS NOT NULL THEN
    v_delta := v_house - s0.house_balance; v_diff := v_delta - v_house_ledger - v_mint;
    v_note := 'house moved ' || v_delta || '; the house ledger (rake, cuts, forfeits) explains ' || v_house_ledger || ' and the Mint explains ' || v_mint || '. DR14: what leaves a player and reaches no player lands here.';
  ELSE
    v_delta := NULL; v_diff := NULL;
    v_note := 'no stored house balance at the window start; ledger ' || v_house_ledger || ', mint ' || v_mint || ' shown.';
  END IF;
  v_tot_now := v_tot_now + v_house; v_tot_delta := v_tot_delta + COALESCE(v_delta, 0); v_tot_mint := v_tot_mint + COALESCE(v_mint, 0);
  RETURN QUERY SELECT 'diamond_house'::text, v_house, v_delta, v_house_ledger, v_mint, v_diff, v_note;

  -- arena_wallets: diamonds a player has deposited onto the platform club's felt. Still theirs,
  -- still in the supply, and in neither profiles nor the house - so the identity below has to
  -- count them or a deposit reads as a break (2026-09-08).
  -- Custody was read with balances and register above.
  IF s0.id IS NOT NULL AND s0.arena_diamonds IS NOT NULL THEN
    v_delta := v_arena - s0.arena_diamonds;
  ELSE
    v_delta := NULL;
  END IF;
  v_tot_now := v_tot_now + v_arena; v_tot_delta := v_tot_delta + COALESCE(v_delta, 0);
  RETURN QUERY SELECT 'arena_wallets'::text, v_arena, v_delta, NULL::numeric, NULL::numeric, NULL::numeric,
    ('diamonds on the Diamond Arena felt plus signed unsettled Diamond Spin custody. A custody deposit moves them out of '
     || 'profiles.diamonds without changing the supply, so they are counted here and in the register '
     || 'identity below. The Mint issues nothing for a deposit and retires nothing for a withdrawal.')::text;

  -- register: the identity over every holder (D9), read in the same snapshot as the balances.
  RETURN QUERY SELECT 'register'::text, v_reg, NULL::numeric, NULL::numeric, NULL::numeric, (v_players + v_house + v_arena) - v_reg,
    ('fn_ca_mint_supply(diamonds) over every holder is ' || v_reg || '; players + house + arena is ' || (v_players + v_house + v_arena)
     || '. Player holders net ' || v_reg_players || ' (fixtures ' || v_reg_fix || '), house holders net ' || v_reg_house
     || ', the rest is the acknowledged pre-standard baseline and its corrections (holder circulation). difference must be 0.')::text;

  -- diamond_debts
  EXECUTE 'SELECT COALESCE(SUM(amount), 0)::numeric FROM public.diamond_debts WHERE settled_at IS NULL' INTO v_sub;
  v_tot_now := v_tot_now + v_sub;
  RETURN QUERY SELECT 'diamond_debts'::text, v_sub, NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric,
    'unsettled chargeback receivable (DR1). A balance is never negative; the remainder lands here.'::text;

  -- promo_budgets_spent
  SELECT COALESCE(SUM(public.fn_ca_diamond_engine_spent(b.period, b.engine)), 0)::numeric, COALESCE(SUM(b.budget_diamonds), 0)::numeric, count(*) INTO v_sub, v_tmp, v_n
    FROM public.diamond_reward_budgets b;
  RETURN QUERY SELECT 'promo_budgets_spent'::text, v_sub, NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric,
    format('%s budget lines, %s budgeted, %s spent by players (fixture issuance excluded since 2026-09-07). A counter, not a balance.', v_n, v_tmp, v_sub);

  -- mirror_mismatch
  SELECT count(*) INTO v_n FROM public.profiles p
    LEFT JOIN public.user_diamonds ud ON ud.user_id = p.id
    LEFT JOIN public.user_diamond_balance udb ON udb.user_id = p.id
    LEFT JOIN public.diamond_wallets dw ON dw.user_id = p.id
   WHERE ud.user_id IS NULL OR udb.user_id IS NULL OR dw.user_id IS NULL
      OR ud.balance IS DISTINCT FROM GREATEST(COALESCE(p.diamonds,0),0)
      OR udb.balance IS DISTINCT FROM GREATEST(COALESCE(p.diamonds,0),0)::int
      OR dw.balance IS DISTINCT FROM GREATEST(COALESCE(p.diamonds,0),0)::int;
  RETURN QUERY SELECT 'mirror_mismatch'::text, v_n::numeric, NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric,
    'COUNT of profiles whose three mirrors disagree or are missing. The mirror trigger upserts all three legs on INSERT and UPDATE (2026-09-07); non-zero means a writer bypassed it.'::text;

  -- dead_stores
  v_sub := 0; v_note := '';
  FOR r IN SELECT * FROM (VALUES ('user_progress', 'diamonds'), ('bot_profiles', 'diamonds'), ('club_members', 'diamonds'),
                                 ('club_memberships', 'diamonds'), ('club_diamond_wallets', 'balance')) AS m(rel, col) LOOP
    BEGIN
      IF to_regclass('public.' || r.rel) IS NULL THEN v_note := v_note || r.rel || ': absent. ';
      ELSIF NOT EXISTS (SELECT 1 FROM information_schema.columns c
                         WHERE c.table_schema = 'public' AND c.table_name = r.rel AND c.column_name = r.col) THEN
        -- Dropped on purpose (20260908033824), which is not the same thing as a query that
        -- broke. This line exists to tell those two apart, so it has to say which one it is.
        v_note := v_note || format('%s.%s: dropped. ', r.rel, r.col);
      ELSE
        EXECUTE format('SELECT COALESCE(SUM(COALESCE(%I, 0)), 0)::numeric FROM public.%I', r.col, r.rel) INTO v_tmp;
        v_sub := v_sub + v_tmp; v_note := v_note || format('%s.%s = %s. ', r.rel, r.col, v_tmp);
      END IF;
    EXCEPTION WHEN OTHERS THEN v_note := v_note || r.rel || ': unreadable. ';
    END;
  END LOOP;
  RETURN QUERY SELECT 'dead_stores'::text, v_sub, NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric,
    (v_note || 'Outside the supply; the delete list, gated on seven days of zero writes (ca_diamond_dead_store_writes).')::text;

  -- suspense (DR12)
  SELECT COALESCE(SUM(dt.amount), 0), count(*) INTO v_sub, v_n FROM public.diamond_transactions dt
   WHERE dt.created_at >= GREATEST(w0, c_foundation) AND (dt.counterparty IS NULL OR dt.counterparty = 'unknown' OR dt.issuance_class IS NULL);
  RETURN QUERY SELECT 'suspense'::text, v_sub, NULL::numeric, v_sub, NULL::numeric, NULL::numeric,
    format('%s journal rows in the window name no counterparty or class. The journal classifier fills both on INSERT since 2026-09-07 and files DR12 naming the writer, so this must read zero.', v_n);

  -- total
  RETURN QUERY SELECT 'total'::text, v_tot_now, CASE WHEN s0.id IS NULL THEN NULL ELSE v_tot_delta END, v_tot_jrn, v_tot_mint,
    CASE WHEN s0.id IS NULL THEN NULL ELSE v_tot_delta - v_tot_mint END,
    'players + custody + house + unsettled debts. difference is player-and-house movement minus register movement (fixtures apart).'::text;
END $$;


ALTER FUNCTION public.fn_ca_diamond_trial_balance(p_since timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 45725 (class 0 OID 0)
-- Dependencies: 6673
-- Name: FUNCTION fn_ca_diamond_trial_balance(p_since timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_trial_balance(p_since timestamp with time zone) IS 'DR11: one row per diamond account with balance, delta, journal net, mint net and the difference. Reports; refuses nothing. Every account is guarded so a table another lane has not landed yields a row noted "table absent" rather than an error.';


--
-- TOC entry 8071 (class 1255 OID 19182965)
-- Name: fn_ca_diamond_trial_balance_watch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_trial_balance_watch() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  r record; v_since timestamptz := now() - interval '1 hour';
  v_filed integer := 0; v_rows integer := 0; v_broken text := '';
  v_clean text[] := ARRAY[]::text[]; v_suspense_zero boolean := false; v_resolved integer;
  v_state text; v_emsg text;
BEGIN
  FOR r IN SELECT * FROM public.fn_ca_diamond_trial_balance(v_since) LOOP
    v_rows := v_rows + 1;
    IF r.account IN ('player_diamonds', 'diamond_house', 'register') AND r.difference IS NOT NULL AND abs(r.difference) > 0 THEN
      -- Ruling 13 (docs/DIAMOND-RULINGS.md): a break over 1,000 diamonds in one hour is critical and
      -- pages; opening the diamond_issuance freeze stays a human act.
      PERFORM public.fn_ca_diamond_incident('DR11:trial_balance_break',
        CASE WHEN abs(r.difference) > 1000 THEN 'critical' ELSE 'warning' END, NULL, r.difference, r.account,
        jsonb_build_object('account', r.account, 'balance_now', r.balance_now, 'balance_delta', r.balance_delta,
                           'journal_net', r.journal_net, 'mint_net', r.mint_net, 'difference', r.difference,
                           'window_start', v_since, 'note', r.note));
      v_filed := v_filed + 1; v_broken := v_broken || r.account || ' ';
    END IF;
    -- An account that reads difference 0 on this tick has no open break: remember it. NULL is
    -- "could not be read" and clears nothing (CLAUDE.md 10.86).
    IF r.difference IS NOT NULL AND r.difference = 0 THEN
      v_clean := v_clean || r.account;
    END IF;
    IF r.account = 'fixture_accounts' AND r.difference IS NOT NULL AND abs(r.difference) > 0 THEN
      PERFORM public.fn_ca_diamond_incident('DR6:fixture_harness_unregistered_movement', 'info', NULL, r.difference,
        'fn_ca_diamond_trial_balance_watch',
        jsonb_build_object('balance_delta', r.balance_delta, 'mint_net', r.mint_net, 'window_start', v_since, 'note', r.note));
    END IF;
    IF r.account = 'suspense' AND COALESCE(r.balance_now, 0) <> 0 THEN
      PERFORM public.fn_ca_diamond_incident('DR12:suspense_nonzero', 'info', NULL, r.balance_now, 'fn_ca_diamond_trial_balance_watch',
        jsonb_build_object('suspense', r.balance_now, 'window_start', v_since, 'note', r.note));
      v_filed := v_filed + 1;
    END IF;
    IF r.account = 'suspense' AND r.balance_now IS NOT NULL AND r.balance_now = 0 THEN
      v_suspense_zero := true;
    END IF;
  END LOOP;

  /* A HOLLOW SUMMARY IS NOT A READING (2026-10-04). The release gate is read
     from this hourly series, so a row reporting zero accounts must not count
     as an hour that measured the books. reading_complete says which it was,
     and a pass that compared no reconciling account at all files its own
     named outcome below instead of leaving a row that looks like a reading.
     CLAUDE.md 10.86 rule 1: a report that vanished is not a report that read
     ok. */
  PERFORM public.fn_ca_diamond_incident('DR11:trial_balance_summary', 'info', NULL, NULL, 'fn_ca_diamond_trial_balance_watch',
    jsonb_build_object('accounts_reported', v_rows, 'incidents_filed', v_filed, 'accounts_broken', NULLIF(btrim(v_broken), ''),
                       'reading_complete', v_rows > 0,
                       'window_start', v_since, 'window_end', now()));
  IF v_rows = 0 THEN
    PERFORM public.fn_ca_diamond_incident('DR14:trial_balance_unreadable', 'warning', NULL, NULL,
      'fn_ca_diamond_trial_balance_watch',
      jsonb_build_object('reason', 'no_accounts_reported',
                         'message', 'the trial balance returned no rows, so no account was compared',
                         'accounts_reported', 0, 'window_start', v_since, 'tick_at', now()));
  END IF;

  -- A BREAK CANNOT OUTLIVE ITS CAUSE (2026-09-19). An open DR11:trial_balance_break row names its
  -- account; when that account read difference 0 on this tick the row is resolved with a note
  -- saying so. An open DR12:suspense_nonzero row is resolved when suspense read 0. Nothing is
  -- deleted here and no other rule is touched.
  UPDATE public.ca_diamond_incidents i
     SET resolved_at = now(),
         resolution = format('auto: account %s read difference 0 at %s', i.detail->>'account', now()::text)
   WHERE i.rule = 'DR11:trial_balance_break' AND i.resolved_at IS NULL
     AND i.detail->>'account' = ANY (v_clean);
  GET DIAGNOSTICS v_resolved = ROW_COUNT;
  IF v_resolved > 0 THEN
    RAISE NOTICE 'fn_ca_diamond_trial_balance_watch: resolved % DR11:trial_balance_break row(s) whose account reads 0', v_resolved;
  END IF;
  IF v_suspense_zero THEN
    UPDATE public.ca_diamond_incidents i
       SET resolved_at = now(),
           resolution = format('auto: suspense read 0 at %s', now()::text)
     WHERE i.rule = 'DR12:suspense_nonzero' AND i.resolved_at IS NULL;
    GET DIAGNOSTICS v_resolved = ROW_COUNT;
    IF v_resolved > 0 THEN
      RAISE NOTICE 'fn_ca_diamond_trial_balance_watch: resolved % DR12:suspense_nonzero row(s); suspense reads 0', v_resolved;
    END IF;
  END IF;

  UPDATE public.ca_diamond_incidents SET resolved_at = now()
   WHERE resolved_at IS NULL AND severity = 'info' AND occurred_at < now() - interval '7 days';
  DELETE FROM public.ca_diamond_incidents
   WHERE severity = 'info' AND resolved_at IS NOT NULL AND occurred_at < now() - interval '30 days';
  RETURN v_filed;
EXCEPTION WHEN OTHERS THEN
  /* A TICK THAT COULD NOT RUN HAS ITS OWN NAME (2026-10-04). This handler used
     to raise a warning into the Postgres log and return -1, filing nothing: the
     hour simply had no row, which is the silence CLAUDE.md 10.86 rule 1 forbids
     and the gap section 7 of the 2026-10-04 clean-day-series audit named. A
     pass that could not complete now files DR14, at warning, into the same
     table the clean series is read from, carrying its SQLSTATE and message.
     Warning, not critical: a measurement that did not happen is not a claim
     that the money is wrong. The escalation lives in fn_ca_diamond_health's
     'trial balance reading' area, which reads the age of this series and goes
     unknown once two consecutive ticks have produced nothing; its readers are
     fn_ca_diamond_health_watch at :35 and the staff desk health view
     (fn_ca_diamond_staff_books('health')). */
  GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_emsg = MESSAGE_TEXT;
  PERFORM public.fn_ca_diamond_incident('DR14:trial_balance_unreadable', 'warning', NULL, NULL,
    'fn_ca_diamond_trial_balance_watch',
    jsonb_build_object('reason', 'read_failed_' || v_state, 'message', v_emsg,
                       'accounts_reported', v_rows, 'window_start', v_since, 'tick_at', now()));
  RAISE WARNING 'fn_ca_diamond_trial_balance_watch failed (%): %', v_state, v_emsg;
  RETURN -1;
END $$;


ALTER FUNCTION public.fn_ca_diamond_trial_balance_watch() OWNER TO postgres;

--
-- TOC entry 45727 (class 0 OID 0)
-- Dependencies: 8071
-- Name: FUNCTION fn_ca_diamond_trial_balance_watch(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_trial_balance_watch() IS 'Hourly at minute 20. Files DR11:trial_balance_break (warning) per account with a non-zero difference, DR12:suspense_nonzero (info) when suspense is non-zero, and one DR11:trial_balance_summary (info) per run. Writes nothing but incidents and NEVER opens ca_payout_freeze: the threshold is Dan (standard 6.13) and an automatic opener is the mechanism that refuses a legitimate movement on a false alarm.';


--
-- TOC entry 7449 (class 1255 OID 24167147)
-- Name: fn_ca_diamond_unreachable_money(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_diamond_unreachable_money() RETURNS TABLE(finding text, object text, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- A money function nothing calls, and nothing grants to a client either: it can only ever run
  -- if a human types its name. That is how send_stream_gift sat unreachable for months.
  SELECT 'no_caller_and_no_client_grant'::text,
         p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')',
         'writes profiles.diamonds but no other function calls it and neither anon nor authenticated may execute it'::text
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public' AND p.prokind = 'f'
     AND p.prosrc ~* 'update\s+(public\.)?profiles[^;]*diamonds\s*='
     AND NOT EXISTS (
       SELECT 1 FROM pg_proc q JOIN pg_namespace m ON m.oid = q.pronamespace
        WHERE m.nspname = 'public' AND q.oid <> p.oid AND q.prosrc LIKE '%' || p.proname || '%')
     AND NOT EXISTS (
       SELECT 1 FROM aclexplode(p.proacl) a
        WHERE a.grantee IN ('anon'::regrole, 'authenticated'::regrole))

  UNION ALL

  -- A money function a browser CAN call, that the privileged-column guard would refuse. That is
  -- exactly what made send_stream_gift answer 42501 to every real player.
  SELECT 'client_reachable_but_guard_refuses'::text,
         p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')',
         'granted to authenticated and writes profiles.diamonds, but fn_guard_profile_privileged_columns does not name it'::text
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public' AND p.prokind = 'f'
     AND p.prosrc ~* 'update\s+(public\.)?profiles[^;]*diamonds\s*='
     AND EXISTS (SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee = 'authenticated'::regrole)
     AND NOT EXISTS (
       SELECT 1 FROM pg_proc g JOIN pg_namespace gn ON gn.oid = g.pronamespace
        WHERE gn.nspname = 'public' AND g.proname = 'fn_guard_profile_privileged_columns'
          AND g.prosrc LIKE '%' || p.proname || '[(]%')

  UNION ALL

  -- A rule row that reads as armed while nothing consults it (the DR15 shape).
  SELECT 'rule_with_no_consumer'::text, r.rule,
         'ca_diamond_rule_modes carries it, but no function calls fn_ca_diamond_rule_mode with this name'::text
    FROM public.ca_diamond_rule_modes r
   WHERE NOT EXISTS (
     SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = 'public'
        -- THE LITERAL CALL, not a body that merely mentions the two strings somewhere. The first
        -- version passed the rule its own migration had just inserted (D3, 2026-09-08).
        AND p.prosrc LIKE '%fn_ca_diamond_rule_mode(''' || r.rule || ''')%');
$$;


ALTER FUNCTION public.fn_ca_diamond_unreachable_money() OWNER TO postgres;

--
-- TOC entry 45729 (class 0 OID 0)
-- Dependencies: 7449
-- Name: FUNCTION fn_ca_diamond_unreachable_money(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_diamond_unreachable_money() IS 'Money paths that read as working while being unreachable: no caller, refused by the privileged-column guard, or a rule nothing consults. Four defects on 2026-09-08 were one of these three.';


--
-- TOC entry 5941 (class 1255 OID 19909969)
-- Name: fn_ca_dismiss_collusion_pair(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_dismiss_collusion_pair(p_club_id uuid, p_player_a uuid, p_player_b uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_updated integer;
BEGIN
  IF NOT fn_ca_can_review_integrity(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM table_seats ts JOIN tables t ON t.id = ts.table_id
     WHERE t.club_id = p_club_id AND ts.user_id = p_player_a
  ) OR NOT EXISTS (
    SELECT 1 FROM table_seats ts JOIN tables t ON t.id = ts.table_id
     WHERE t.club_id = p_club_id AND ts.user_id = p_player_b
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'pair_did_not_play_here', 'updated', 0);
  END IF;

  -- 'cleared', not 'dismissed'. The check constraint on this table allows
  -- open | reviewed | cleared | actioned, and the word this function used to
  -- write is in none of them.
  UPDATE collusion_tracking ct
     SET status = 'cleared',
         reviewed_by = auth.uid(),
         reviewed_at = now(),
         notes = nullif(btrim(coalesce(p_note, '')), ''),
         updated_at = now()
   WHERE ct.scan_date > current_date - 30
     AND coalesce(ct.status, 'open') = 'open'
     AND ((ct.player_a = p_player_a AND ct.player_b = p_player_b)
       OR (ct.player_a = p_player_b AND ct.player_b = p_player_a));

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN jsonb_build_object('ok', v_updated > 0, 'updated', v_updated);
END;
$$;


ALTER FUNCTION public.fn_ca_dismiss_collusion_pair(p_club_id uuid, p_player_a uuid, p_player_b uuid, p_note text) OWNER TO postgres;

--
-- TOC entry 4501 (class 1255 OID 64310637)
-- Name: fn_ca_dispose_superseded_hand_submissions(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_dispose_superseded_hand_submissions(p_table_id uuid, p_receipt_id uuid, p_reason text, p_limit integer DEFAULT 2000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE
  v_actor text := current_setting('app.smarter_data_actor', true);
  v_tour uuid;
  v_witness bigint;
  v_witness_at timestamptz;
  v_prior integer;
  v_blocked jsonb := '[]'::jsonb;
  v_bases jsonb := '[]'::jsonb;
  v_disposed integer := 0;
  v_candidates integer := 0;
  v_min bigint;
  v_max bigint;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role'
     OR v_actor IS NULL OR v_actor NOT IN ('service', 'tournament-manager', 'table-manager') THEN
    RAISE EXCEPTION 'HAND_DISPOSAL_SERVICE_REQUIRED' USING ERRCODE = '42501';
  END IF;
  IF p_table_id IS NULL OR p_receipt_id IS NULL OR length(btrim(COALESCE(p_reason, ''))) < 40 THEN
    RAISE EXCEPTION 'HAND_DISPOSAL_IDENTITY_REQUIRED' USING ERRCODE = '22023';
  END IF;
  IF public.fn_platform_frozen() THEN
    RAISE EXCEPTION 'PLATFORM_FROZEN: hand submission disposal refused' USING ERRCODE = '55000';
  END IF;

  SELECT count(*) INTO v_prior FROM smarter_private.hand_submission_disposals WHERE receipt_id = p_receipt_id;
  IF v_prior > 0 THEN
    RETURN jsonb_build_object('ok', true, 'replayed', true, 'receipt_id', p_receipt_id,
      'table_id', p_table_id, 'disposed', v_prior, 'credit', 0);
  END IF;

  -- The same lane every settlement of this table takes, and never queued: a
  -- disposal that has to wait for a live hand is a disposal that should not run.
  IF NOT pg_try_advisory_xact_lock(hashtextextended('hand:disposal:' || p_table_id::text, 0)) THEN
    RAISE EXCEPTION 'HAND_DISPOSAL_TABLE_BUSY' USING ERRCODE = '55P03';
  END IF;
  SELECT tournament_id INTO v_tour FROM public.tables WHERE id = p_table_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'HAND_DISPOSAL_TABLE_MISSING' USING ERRCODE = '55000'; END IF;
  PERFORM public.fn_ca_share_settlement_lane_for_table(p_table_id);

  -- THE WITNESS: the newest hand this table committed. Everything below it that
  -- never committed was dealt past, and its before-stacks were consumed.
  SELECT a.hand_number, a.committed_at INTO v_witness, v_witness_at
    FROM public.hand_atomic_commits a
   WHERE a.table_id = p_table_id
   ORDER BY a.hand_number DESC LIMIT 1;

  CREATE TEMP TABLE IF NOT EXISTS _hand_disposal_batch (
    submission_id uuid, hand_number bigint, retained_at timestamptz,
    lease_generation uuid, request_hash text, basis text, blocked text) ON COMMIT DROP;
  -- Scoped on purpose: the batch table is transaction-local (ON COMMIT DROP)
  -- and reused across the calls one batch makes, and a write states its scope.
  DELETE FROM _hand_disposal_batch WHERE true;

  INSERT INTO _hand_disposal_batch (submission_id, hand_number, retained_at, lease_generation, request_hash, basis, blocked)
  SELECT s.submission_id, s.hand_number, s.retained_at, s.lease_generation, s.request_hash,
         CASE
           WHEN v_witness IS NOT NULL AND s.hand_number < v_witness THEN 'superseded_by_later_commit'
           WHEN EXISTS (SELECT 1 FROM smarter_private.f06_hand_permits p
                         WHERE p.table_id = s.table_id AND p.hand_number = s.hand_number
                           AND p.state = 'accepted' AND p.evidence_id IS NOT NULL)
             THEN 'settled_under_accepted_permit'
           WHEN EXISTS (
                 SELECT 1 FROM jsonb_array_elements(s.request->'p_stacks') x
                  WHERE NOT EXISTS (
                    SELECT 1 FROM public.table_seats seat
                     WHERE seat.table_id = s.table_id AND seat.id = (x->>'seat_id')::uuid
                       AND seat.user_id = (x->>'user_id')::uuid
                       AND seat.joined_at = (x->>'seat_joined_at')::timestamptz
                       AND seat.left_at IS NULL
                       AND seat.stack = (x->>'stack_before')::numeric))
             THEN 'request_can_never_apply'
           ELSE NULL
         END,
         CASE
           WHEN EXISTS (SELECT 1 FROM public.hand_history hh
                         WHERE hh.table_id = s.table_id AND hh.hand_number = s.hand_number)
             THEN 'hand_history_exists'
           WHEN EXISTS (SELECT 1 FROM smarter_private.hand_submission_handoffs h
                         WHERE h.submission_id = s.submission_id)
             THEN 'successor_claim_spent'
           WHEN EXISTS (SELECT 1 FROM smarter_private.hand_submission_dispatch d
                         WHERE d.submission_id = s.submission_id)
             THEN 'handoff_dispatch_open'
           WHEN EXISTS (SELECT 1 FROM smarter_private.f06_hand_permits p
                         WHERE p.table_id = s.table_id AND p.hand_number = s.hand_number
                           AND p.state = 'reserved')
             THEN 'f06_permit_unresolved'
           WHEN (CASE WHEN v_tour IS NULL
                      THEN EXISTS (SELECT 1 FROM public.engine_table_leases l
                                    WHERE l.table_id = s.table_id AND l.lease_generation = s.lease_generation)
                      ELSE EXISTS (SELECT 1 FROM public.engine_tournament_leases l
                                    WHERE l.tournament_id = v_tour AND l.lease_generation = s.lease_generation)
                 END)
             THEN 'dealer_generation_still_leased'
           WHEN s.retained_at >= clock_timestamp() - interval '30 minutes'
             THEN 'retained_too_recently'
           ELSE NULL
         END
    FROM smarter_private.hand_submissions s
   WHERE s.table_id = p_table_id
     AND NOT EXISTS (SELECT 1 FROM public.hand_atomic_commits a
                      WHERE a.table_id = s.table_id AND a.hand_number = s.hand_number)
     AND NOT EXISTS (SELECT 1 FROM smarter_private.hand_submission_disposals dd
                      WHERE dd.table_id = s.table_id AND dd.hand_number = s.hand_number)
   ORDER BY s.hand_number
   LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 2000), 20000));

  SELECT count(*), min(hand_number), max(hand_number) INTO v_candidates, v_min, v_max
    FROM _hand_disposal_batch;
  IF v_candidates = 0 THEN
    RETURN jsonb_build_object('ok', true, 'receipt_id', p_receipt_id, 'table_id', p_table_id,
      'witness_hand_number', v_witness, 'candidates', 0, 'disposed', 0, 'blocked', '[]'::jsonb, 'credit', 0);
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('reason', COALESCE(b.blocked, 'still_applicable_leave_to_handoff'), 'hands', b.n)), '[]'::jsonb)
    INTO v_blocked
    FROM (SELECT blocked, count(*) n FROM _hand_disposal_batch
           WHERE blocked IS NOT NULL OR basis IS NULL
           GROUP BY blocked) b;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('basis', b.basis, 'hands', b.n)), '[]'::jsonb) INTO v_bases
    FROM (SELECT basis, count(*) n FROM _hand_disposal_batch
           WHERE blocked IS NULL AND basis IS NOT NULL GROUP BY basis) b;

  INSERT INTO smarter_private.hand_submission_disposals
    (table_id, hand_number, submission_id, receipt_id, witness_hand_number, reason, expected)
  SELECT p_table_id, b.hand_number, b.submission_id, p_receipt_id,
         CASE WHEN b.basis = 'superseded_by_later_commit' THEN v_witness ELSE b.hand_number END,
         p_reason,
         jsonb_build_object(
           'kind', b.basis,
           'table_id', p_table_id, 'tournament_id', v_tour,
           'hand_number', b.hand_number, 'submission_id', b.submission_id,
           'retained_at', b.retained_at, 'dealer_generation', b.lease_generation,
           'request_hash', b.request_hash,
           'witness_hand_number', v_witness, 'witness_committed_at', v_witness_at,
           'disposed_at', clock_timestamp(), 'actor', v_actor)
    FROM _hand_disposal_batch b
   WHERE b.blocked IS NULL AND b.basis IS NOT NULL;
  GET DIAGNOSTICS v_disposed = ROW_COUNT;

  IF public.fn_platform_frozen() THEN
    RAISE EXCEPTION 'PLATFORM_FROZEN: hand submission disposal refused' USING ERRCODE = '55000';
  END IF;

  RETURN jsonb_build_object('ok', true, 'receipt_id', p_receipt_id, 'table_id', p_table_id,
    'tournament_id', v_tour, 'witness_hand_number', v_witness, 'witness_committed_at', v_witness_at,
    'candidates', v_candidates, 'disposed', v_disposed, 'bases', v_bases, 'first_hand', v_min, 'last_hand', v_max,
    'blocked', v_blocked, 'credit', 0);
END
$$;


ALTER FUNCTION public.fn_ca_dispose_superseded_hand_submissions(p_table_id uuid, p_receipt_id uuid, p_reason text, p_limit integer) OWNER TO postgres;

--
-- TOC entry 45732 (class 0 OID 0)
-- Dependencies: 4501
-- Name: FUNCTION fn_ca_dispose_superseded_hand_submissions(p_table_id uuid, p_receipt_id uuid, p_reason text, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_dispose_superseded_hand_submissions(p_table_id uuid, p_receipt_id uuid, p_reason text, p_limit integer) IS 'Zero-credit, receipted disposal of a retained settlement request that can never be applied - the table committed a later hand, the hand settled under an accepted F06 permit whose record aged out, or a chair the request names is no longer there holding exactly what it names - proved from rows; leaves anything it cannot prove alone and reports it. 2026-09-28.';


--
-- TOC entry 6658 (class 1255 OID 25366002)
-- Name: fn_ca_drain_orphaned_post_commit_envelopes(interval, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_drain_orphaned_post_commit_envelopes(p_older_than interval DEFAULT '00:10:00'::interval, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE r record; v_seen int := 0; v_done int := 0; v_failed int := 0; v_res jsonb;
  BEGIN
    FOR r IN
      SELECT c.hand_id, c.table_id, c.hand_number, c.committed_at
        FROM public.hand_atomic_commits c
       WHERE c.post_commit_payload IS NOT NULL
         AND c.post_commit_completed_at IS NULL
         AND c.committed_at < now() - p_older_than
         /* the barrier is per table and in hand order: only drain a hand
            whose predecessors have all finished, or the applier will simply
            answer predecessor_pending and we will have learnt nothing */
         AND NOT EXISTS (
           SELECT 1 FROM public.hand_atomic_commits e
            WHERE e.table_id = c.table_id
              AND e.hand_number < c.hand_number
              AND e.post_commit_payload IS NOT NULL
              AND e.post_commit_completed_at IS NULL)
       ORDER BY c.committed_at
       LIMIT GREATEST(p_limit, 1)
    LOOP
      v_seen := v_seen + 1;
      BEGIN
        v_res := public.fn_ca_process_hand_post_commit_obligations(r.hand_id);
        IF COALESCE((v_res->>'ok')::boolean, false) THEN v_done := v_done + 1;
        ELSE v_failed := v_failed + 1; END IF;
      EXCEPTION WHEN OTHERS THEN
        v_failed := v_failed + 1;
      END;
    END LOOP;

    RETURN jsonb_build_object('ok', true, 'seen', v_seen, 'applied', v_done, 'failed', v_failed);
  END;
  $$;


ALTER FUNCTION public.fn_ca_drain_orphaned_post_commit_envelopes(p_older_than interval, p_limit integer) OWNER TO postgres;

--
-- TOC entry 7312 (class 1255 OID 64158617)
-- Name: fn_ca_drain_recorded_bust_backlog(uuid, uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_drain_recorded_bust_backlog(p_tournament_id uuid, p_receipt_id uuid, p_limit integer DEFAULT 25, p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'smarter_private', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_prior    smarter_private.ca_bust_backlog_drains;
  v_t        public.tournaments%ROWTYPE;
  v_lim      integer;
  v_deep     integer;
  v_taken    integer[];
  v_unplaced integer;
  v_playing  integer;
  v_queued   integer;
  v_backlog  integer;
  v_seed     integer;
  v_place    integer;
  v_up       integer;
  v_ceiling  integer;
  v_res      jsonb;
  v_done     integer := 0;
  v_first    integer;
  v_last     integer;
  v_stop     text := 'backlog_drained';
  v_recorded jsonb := '[]'::jsonb;
  r          record;
  v_out      jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'CA_BUST_DRAIN_SERVICE_REQUIRED' USING ERRCODE='42501'; END IF;
  IF p_tournament_id IS NULL OR p_receipt_id IS NULL THEN
    RAISE EXCEPTION 'CA_BUST_DRAIN_IDENTITY' USING ERRCODE='22023'; END IF;
  v_lim := LEAST(GREATEST(COALESCE(p_limit, 25), 1), 100);

  -- Replay is answered from the receipt, never re-run.
  SELECT * INTO v_prior FROM smarter_private.ca_bust_backlog_drains
   WHERE receipt_id = p_receipt_id;
  IF FOUND THEN
    IF (v_prior.tournament_id, v_prior.requested_limit, v_prior.dry_run)
       IS DISTINCT FROM (p_tournament_id, v_lim, COALESCE(p_dry_run,false)) THEN
      RAISE EXCEPTION 'CA_BUST_DRAIN_CHANGED_REPLAY' USING ERRCODE='22023'; END IF;
    RETURN v_prior.result;
  END IF;

  IF public.fn_platform_frozen() THEN
    RAISE EXCEPTION 'PLATFORM_FROZEN: bust backlog drain refused' USING ERRCODE='55000'; END IF;

  -- Same lane, same order, as the door this function drives.
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);

  SELECT * INTO v_t FROM public.tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND OR v_t.status <> 'RUNNING' THEN
    RAISE EXCEPTION 'CA_BUST_DRAIN_EVENT_CHANGED' USING ERRCODE='55000'; END IF;
  IF COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
     OR COALESCE(v_t.is_mystery_bounty,false) THEN
    -- A bounty head is settled by the outbox claim, in hand-number order.
    RAISE EXCEPTION 'CA_BUST_DRAIN_BOUNTY_EVENT' USING ERRCODE='55000'; END IF;

  -- The money rail. An unreadable payout ladder is UNKNOWN, not "nothing paid".
  BEGIN
    SELECT max((e->>'place')::int) INTO v_deep
      FROM jsonb_array_elements(v_t.payout_structure::jsonb) e;
  EXCEPTION WHEN OTHERS THEN
    v_deep := NULL;
  END;
  IF v_deep IS NULL OR v_deep < 1 THEN
    RAISE EXCEPTION 'CA_BUST_DRAIN_PAYOUT_LADDER_UNREADABLE' USING ERRCODE='55000'; END IF;

  SELECT COALESCE(array_agg(position),'{}') INTO v_taken
    FROM public.tournament_players
   WHERE tournament_id = p_tournament_id AND position IS NOT NULL;
  SELECT count(*) INTO v_unplaced FROM public.tournament_players
   WHERE tournament_id = p_tournament_id AND position IS NULL;
  SELECT count(*) INTO v_playing FROM public.tournament_players
   WHERE tournament_id = p_tournament_id AND status = 'playing';

  -- The generation the door will bind (latest by hand number, then id) and
  -- only when it is still `pending`: the same binding as bustOrder.ts.
  SELECT count(*) INTO v_backlog FROM (
    SELECT DISTINCT ON (c.eliminated_user_id) c.state, c.resolved_at
      FROM public.tournament_knockout_candidates c
     WHERE c.tournament_id = p_tournament_id
     ORDER BY c.eliminated_user_id, c.hand_number DESC, c.id DESC) q
   WHERE q.state = 'pending' AND q.resolved_at IS NULL;
  v_queued := LEAST(v_backlog, v_lim);

  IF v_queued = 0 THEN
    v_stop := 'nothing_queued';
  ELSE
    -- The engine's seed, unchanged: the number of players holding no place.
    v_seed := GREATEST(v_unplaced, v_playing, v_queued + 1);
    FOR r IN
      SELECT l.eliminated_user_id AS uid, l.hand_number, l.stack_before
        FROM (
          SELECT DISTINCT ON (c.eliminated_user_id) c.*
            FROM public.tournament_knockout_candidates c
           WHERE c.tournament_id = p_tournament_id
           ORDER BY c.eliminated_user_id, c.hand_number DESC, c.id DESC
        ) l
       WHERE l.state = 'pending' AND l.resolved_at IS NULL
       ORDER BY l.hand_number, l.stack_before, l.eliminated_user_id
       LIMIT v_lim
    LOOP
      v_place := v_seed;
      WHILE v_place >= 2 AND v_place = ANY(v_taken) LOOP v_place := v_place - 1; END LOOP;
      IF v_place < 2 THEN
        -- Ladder corrupt downward: take the lowest free place above the seed,
        -- exactly as the sweep does, rather than stranding the player.
        v_up := v_seed + 1;
        v_ceiling := v_seed + COALESCE(array_length(v_taken,1),0) + 2;
        WHILE v_up <= v_ceiling AND v_up = ANY(v_taken) LOOP v_up := v_up + 1; END LOOP;
        IF v_up > v_ceiling THEN v_stop := 'no_free_finishing_place'; EXIT; END IF;
        v_place := v_up;
      END IF;
      IF v_place <= v_deep THEN
        -- Priced places belong to the manager's ladder pool, not to a janitor.
        v_stop := 'place_in_the_money'; EXIT; END IF;

      IF COALESCE(p_dry_run,false) THEN
        v_res := jsonb_build_object('ok',true,'dry_run',true);
      ELSE
        v_res := public.fn_eliminate_tournament_player_atomic(
                   p_tournament_id, r.uid, v_place, 0::numeric, 0::numeric);
      END IF;
      IF COALESCE((v_res->>'ok')::boolean,false) IS NOT TRUE THEN
        -- The ladder this pass built is now stale; stop and let the next
        -- receipt rebuild it from persisted positions.
        v_stop := 'door_refused:'||COALESCE(v_res->>'reason','unnamed');
        EXIT;
      END IF;
      v_taken := v_taken || v_place;
      v_seed  := LEAST(v_seed, v_place) - 1;
      IF v_done = 0 THEN v_first := v_place; END IF;
      v_last  := v_place;
      v_done  := v_done + 1;
      v_recorded := v_recorded || jsonb_build_array(jsonb_build_object(
        'user_id', r.uid, 'hand_number', r.hand_number, 'place', v_place));
    END LOOP;
    IF v_done = v_queued AND v_stop = 'backlog_drained' THEN v_stop := 'batch_complete'; END IF;
  END IF;

  v_out := jsonb_build_object(
    'ok', true, 'tournament_id', p_tournament_id, 'receipt_id', p_receipt_id,
    'dry_run', COALESCE(p_dry_run,false), 'limit', v_lim,
    'queued', v_queued, 'recorded', v_done,
    'first_place', v_first, 'last_place', v_last,
    'deepest_paid_place', v_deep, 'stopped', v_stop,
    'remaining', GREATEST((SELECT count(*) FROM (
        SELECT DISTINCT ON (c.eliminated_user_id) c.state, c.resolved_at
          FROM public.tournament_knockout_candidates c
         WHERE c.tournament_id = p_tournament_id
         ORDER BY c.eliminated_user_id, c.hand_number DESC, c.id DESC) q
       WHERE q.state='pending' AND q.resolved_at IS NULL), 0),
    'places', v_recorded);

  INSERT INTO smarter_private.ca_bust_backlog_drains
    (receipt_id, tournament_id, requested_limit, dry_run, result)
  VALUES (p_receipt_id, p_tournament_id, v_lim, COALESCE(p_dry_run,false), v_out);

  RETURN v_out;
END
$$;


ALTER FUNCTION public.fn_ca_drain_recorded_bust_backlog(p_tournament_id uuid, p_receipt_id uuid, p_limit integer, p_dry_run boolean) OWNER TO postgres;

--
-- TOC entry 5930 (class 1255 OID 116465564)
-- Name: fn_ca_drift_incident_timeline_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_drift_incident_timeline_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.deadline_at < NEW.detected_at THEN
    RAISE EXCEPTION 'drift incident deadline cannot precede detection'
      USING ERRCODE='23514';
  END IF;
  IF NEW.resolved_at IS NOT NULL AND NEW.resolved_at < NEW.detected_at THEN
    RAISE EXCEPTION 'drift incident resolution cannot precede detection'
      USING ERRCODE='23514';
  END IF;
  IF (NEW.status = 'resolved') IS DISTINCT FROM (NEW.resolved_at IS NOT NULL) THEN
    RAISE EXCEPTION 'drift incident resolved status must match its resolution time'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_ca_drift_incident_timeline_guard() OWNER TO postgres;

--
-- TOC entry 3594 (class 1255 OID 18125274)
-- Name: fn_ca_drift_metrics(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_drift_metrics() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_service boolean := COALESCE(auth.role(), '') = 'service_role';
  v_platform boolean := v_service OR COALESCE(public.fn_is_platform_admin(), false);
  v_global boolean;
  v jsonb;
BEGIN
  IF NOT public.fn_ca_can_view_drift_console() THEN
    RAISE EXCEPTION 'drift console reviewer required' USING ERRCODE = '42501';
  END IF;

  v_global := v_platform OR EXISTS (
    SELECT 1
      FROM public.ca_incident_recipients r
     WHERE r.user_id = v_uid
       AND r.active
       AND r.scope IN ('platform', 'financial_ops', 'technical')
  );

  WITH visible AS MATERIALIZED (
    SELECT i.*
      FROM public.ca_drift_incidents i
     WHERE v_platform
        OR (v_uid IS NOT NULL
            AND v_uid = ANY (public.fn_ca_incident_recipient_ids(i, false)))
  )
  SELECT jsonb_build_object(
    'open_total', count(*) FILTER (WHERE status <> 'resolved'),
    'open_critical', count(*) FILTER (
      WHERE status <> 'resolved' AND severity = 'critical'
    ),
    'past_target', count(*) FILTER (WHERE status <> 'resolved' AND past_target),
    'auto_repairing', count(*) FILTER (
      WHERE status <> 'resolved' AND auto_repair_status = 'running'
    ),
    'resolved_today', count(*) FILTER (
      WHERE status = 'resolved' AND resolved_at > CURRENT_DATE
    ),
    'median_resolve_min', (
      SELECT round(percentile_cont(0.5) WITHIN GROUP (
        ORDER BY extract(epoch FROM (resolved_at - detected_at)) / 60
      )::numeric, 1)
        FROM visible
       WHERE status = 'resolved'
         AND resolved_at > now() - interval '7 days'
    ),
    'worst_open_drift', COALESCE(max(abs(discrepancy_amount)) FILTER (
      WHERE status <> 'resolved'
    ), 0)
  ) INTO v
    FROM visible;

  IF v_global THEN
    v := v || jsonb_build_object(
      'suspense_today', (
        SELECT COALESCE(sum(
          CASE WHEN to_type = 'settlement_suspense' THEN amount ELSE -amount END
        ), 0)
          FROM public.chip_ledger
         WHERE (from_type = 'settlement_suspense' OR to_type = 'settlement_suspense')
           AND created_at > CURRENT_DATE
      ),
      'suspense_today_gross', (
        SELECT COALESCE(sum(amount), 0)
          FROM public.chip_ledger
         WHERE (from_type = 'settlement_suspense' OR to_type = 'settlement_suspense')
           AND created_at > CURRENT_DATE
      ),
      'ledger_write_failures_24h', (
        SELECT count(*)
          FROM public.ca_ledger_write_failures
         WHERE occurred_at > now() - interval '24 hours'
      ),
      'supply_unexplained_last', (
        SELECT unexplained
          FROM public.ca_supply_snapshots
         ORDER BY taken_at DESC
         LIMIT 1
      ),
      'ledger_rows_today', (
        SELECT count(*)
          FROM public.chip_ledger
         WHERE created_at > CURRENT_DATE
      )
    );
  END IF;

  RETURN v;
END
$$;


ALTER FUNCTION public.fn_ca_drift_metrics() OWNER TO postgres;

--
-- TOC entry 8038 (class 1255 OID 18631429)
-- Name: fn_ca_duel_pairing_scan(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_duel_pairing_scan(p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_since timestamptz := now() - make_interval(days => GREATEST(p_days, 1));
  -- Calibrated on the live board 2026-09-01: of 10,134 duels in 7 days the
  -- most any pair met is 5 (6,454 met once, 1,106 twice, 222 three times,
  -- 40 four times, 7 five times). Eight is 60% above that maximum, and the
  -- win share must hold too - win share alone is worthless down there,
  -- because every pair that met once has a "100% win rate".
  v_min_meetings   constant int     := 8;
  v_min_win_share  constant numeric := 0.8;
  r RECORD; v_flagged int := 0;
BEGIN
  FOR r IN
    WITH duels AS (
      SELECT t.id, COALESCE(t.buy_in_amount, 0) AS buy_in
        FROM public.tournaments t
       WHERE t.max_players = 2
         AND t.status = 'COMPLETED'
         AND t.started_at > v_since
    ),
    met AS (
      SELECT LEAST(a.user_id, b.user_id)    AS ua,
             GREATEST(a.user_id, b.user_id) AS ub,
             CASE WHEN a.position = 1 THEN a.user_id ELSE b.user_id END AS winner,
             d.buy_in
        FROM duels d
        JOIN public.tournament_players a ON a.tournament_id = d.id
        JOIN public.tournament_players b ON b.tournament_id = d.id
                                        AND b.user_id > a.user_id
    ),
    pairflow AS (
      SELECT ua, ub,
             count(*)                            AS meetings,
             count(*) FILTER (WHERE winner = ua) AS wins_a,
             sum(buy_in)                         AS gross_flow,
             sum(CASE WHEN winner = ua THEN buy_in ELSE -buy_in END) AS net_to_ua
        FROM met
       GROUP BY 1, 2
    )
    SELECT CASE WHEN wins_a * 2 >= meetings THEN ua ELSE ub END AS receiver,
           CASE WHEN wins_a * 2 >= meetings THEN ub ELSE ua END AS sender,
           meetings,
           gross_flow,
           abs(net_to_ua) AS net_flow,
           round(GREATEST(wins_a, meetings - wins_a)::numeric / meetings, 3) AS win_share
      FROM pairflow
     WHERE meetings >= v_min_meetings
       AND GREATEST(wins_a, meetings - wins_a)::numeric / meetings >= v_min_win_share
  LOOP
    v_flagged := v_flagged + 1;

    INSERT INTO public.ca_collusion_signals
      (window_days, user_a, user_b, hands_together, gross_flow, net_flow,
       direction_ratio, both_cert, detail)
    VALUES
      (p_days, r.receiver, r.sender, r.meetings, r.gross_flow, r.net_flow,
       r.win_share,
       public.fn_ca_is_cert_account(r.receiver) AND public.fn_ca_is_cert_account(r.sender),
       jsonb_build_object(
         'signal', 'duel_repeat_pairing',
         'since', v_since,
         'note', 'hands_together is DUELS together for this detector, not hands; '
                 || 'direction_ratio is the winner share of those duels',
         'min_meetings', v_min_meetings,
         'min_win_share', v_min_win_share));

    PERFORM public.fn_ca_raise_drift_incident(
      p_source          => 'fn_ca_duel_pairing_scan',
      p_classification  => 'unknown',
      p_severity        => CASE
                             WHEN r.win_share >= 0.9
                              AND NOT (public.fn_ca_is_cert_account(r.receiver)
                                   AND public.fn_ca_is_cert_account(r.sender))
                             THEN 'warning' ELSE 'info' END,
      p_dedupe_key      => 'duelpair:' || r.receiver::text || ':' || r.sender::text
                           || ':' || to_char(now(), 'IYYY-IW'),
      p_discrepancy     => r.net_flow,
      p_expected        => NULL,
      p_actual          => NULL,
      p_layer           => 'reporting',
      p_entity_type     => 'user',
      p_entity_id       => r.receiver,
      p_club_id         => NULL,
      p_union_id        => NULL,
      p_table_id        => NULL,
      p_tournament_id   => NULL,
      p_hand_id         => NULL,
      p_settlement_id   => NULL,
      p_wallet_ids      => NULL,
      p_transaction_ids => NULL,
      p_suspected_cause => 'the same two accounts met heads-up ' || r.meetings
                           || ' times in ' || p_days || 'd and one side won '
                           || round(r.win_share * 100) || '% of them ('
                           || r.net_flow || ' chips net) - review the pair; '
                           || 'no automatic action taken',
      p_ledger_balanced => true,
      p_metadata        => jsonb_build_object(
                             'receiver', r.receiver, 'sender', r.sender,
                             'meetings', r.meetings, 'gross_flow', r.gross_flow,
                             'net_flow', r.net_flow, 'win_share', r.win_share));
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'window_days', p_days,
                            'min_meetings', v_min_meetings,
                            'min_win_share', v_min_win_share,
                            'pairs_flagged', v_flagged);
END $$;


ALTER FUNCTION public.fn_ca_duel_pairing_scan(p_days integer) OWNER TO postgres;

--
-- TOC entry 8292 (class 1255 OID 18540970)
-- Name: fn_ca_duplicate_structure_payout_check(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_duplicate_structure_payout_check(p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
DECLARE
  v_players int := 0;
  v_events int := 0;
  v_excess numeric := 0;
  v_sample jsonb;
  v_evidence jsonb;
  v_classes jsonb;
  v_records bigint;
  v_evidence_records bigint;
  v_evidence_groups bigint;
  v_context jsonb;
  v_since timestamptz := now() - make_interval(hours => GREATEST(p_hours, 1));
BEGIN
  -- Preserve the original positive-record population and insertion-time window.
  -- Neither paid_at nor a reserved replay key proves that money moved.
  WITH eligible AS MATERIALIZED (
    SELECT p.tournament_id,p.user_id,p.position,p.amount,p.created_at
    FROM public.tournament_payouts p
    WHERE p.source = 'structure' AND p.amount > 0 AND p.created_at > v_since
  ), positions AS (
    SELECT tournament_id,user_id,position,count(*) AS records
    FROM eligible GROUP BY tournament_id,user_id,position
  ), classes AS (
    SELECT tournament_id,user_id,
      count(*) FILTER (WHERE position > 0 AND records > 1) AS repeated_positive_places,
      COALESCE(sum(records) FILTER (WHERE position > 0 AND records > 1),0) AS repeated_positive_place_records,
      count(*) FILTER (WHERE position > 0) AS distinct_positive_places,
      COALESCE(sum(records) FILTER (WHERE position IS NULL OR position <= 0),0) AS unknown_or_invalid_place_records
    FROM positions GROUP BY tournament_id,user_id
  ), dup AS MATERIALIZED (
    SELECT p.tournament_id,p.user_id,count(*) AS rows_,sum(p.amount) AS paid,
           max(p.amount) AS largest,max(p.created_at) AS last_at
    FROM eligible p GROUP BY p.tournament_id,p.user_id HAVING count(*) > 1
  ), ranked AS MATERIALIZED (
    SELECT d.*,c.repeated_positive_places,c.repeated_positive_place_records,
      c.distinct_positive_places,c.unknown_or_invalid_place_records,
      row_number() OVER (ORDER BY d.paid-d.largest DESC,d.tournament_id,d.user_id) AS ordinal
    FROM dup d JOIN classes c USING (tournament_id,user_id)
  ), evidence AS MATERIALIZED (
    -- Restrict groups AND records before looking up reservation keys. The legacy
    -- sample remains complete; only this new evidence array is bounded.
    SELECT d.ordinal,p.*,w.key IS NOT NULL AS key_registered,
      w.user_id = p.user_id AS key_user_matches,
      w.amount = p.amount AS key_amount_matches,
      w.created_at AS key_created_at
    FROM (SELECT * FROM ranked ORDER BY ordinal LIMIT 30) d
    CROSS JOIN LATERAL (
      SELECT e.id,e.tournament_id,e.user_id,e.position,e.amount,e.source,
             e.created_at,e.paid_at,e.idempotency_key
      FROM public.tournament_payouts e
      WHERE e.tournament_id = d.tournament_id AND e.user_id = d.user_id
        AND e.source = 'structure' AND e.amount > 0 AND e.created_at > v_since
      ORDER BY e.created_at,e.id LIMIT 4
    ) p
    LEFT JOIN public.wallet_credit_idempotency w ON w.key = p.idempotency_key
  )
  SELECT count(*),count(DISTINCT tournament_id),COALESCE(sum(paid-largest),0),
    COALESCE(sum(rows_),0),
    COALESCE(jsonb_agg(jsonb_build_object(
      'tournament_id',tournament_id,'user_id',user_id,'rows',rows_,
      'paid',round(paid,2),'excess',round(paid-largest,2),'last_at',last_at,
      'same_positive_place_duplicate',repeated_positive_places > 0,
      'repeated_positive_places',repeated_positive_places,
      'repeated_positive_place_records',repeated_positive_place_records,
      'cross_positive_places',distinct_positive_places > 1,
      'distinct_positive_places',distinct_positive_places,
      'unknown_or_invalid_place_records',unknown_or_invalid_place_records,
      'evidence_records',CASE WHEN ordinal <= 30 THEN LEAST(rows_,4) ELSE 0 END,
      'evidence_records_omitted',rows_ - CASE WHEN ordinal <= 30 THEN LEAST(rows_,4) ELSE 0 END
    ) ORDER BY ordinal),'[]'::jsonb),
    jsonb_build_object(
      'groups_with_same_positive_place_duplicates',count(*) FILTER (WHERE repeated_positive_places > 0),
      'groups_with_cross_positive_places',count(*) FILTER (WHERE distinct_positive_places > 1),
      'groups_with_unknown_or_invalid_places',count(*) FILTER (WHERE unknown_or_invalid_place_records > 0),
      'classes_overlap',true),
    (SELECT count(*) FROM evidence),
    (SELECT count(DISTINCT ordinal) FROM evidence),
    (SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'payout_id',id,'tournament_id',tournament_id,'user_id',user_id,
      'position',position,'amount',amount,'source',source,'created_at',created_at,'paid_at',paid_at,
      'idempotency_key',left(idempotency_key,512),
      'key_characters',length(idempotency_key),
      'key_truncated',COALESCE(length(idempotency_key) > 512,false),
      'full_key_md5',md5(idempotency_key),
      'key_registered',key_registered,'key_user_matches',key_user_matches,
      'key_amount_matches',key_amount_matches,'key_created_at',key_created_at,
      'key_evidence',CASE
        WHEN idempotency_key IS NULL THEN 'no_payout_key'
        WHEN NOT key_registered THEN 'key_not_registered'
        WHEN (key_user_matches AND key_amount_matches) IS TRUE THEN 'registered_key_match'
        ELSE 'registered_key_mismatch_or_unknown' END
    ) ORDER BY ordinal,created_at,id),'[]'::jsonb) FROM evidence)
  INTO v_players,v_events,v_excess,v_records,v_sample,v_classes,
       v_evidence_records,v_evidence_groups,v_evidence
  FROM ranked;

  v_context := jsonb_build_object(
    'players',v_players,'tournaments',v_events,'excess',round(v_excess,2),
    'hours',GREATEST(p_hours,1),'sample',v_sample,
    'report_version',2,'measurement','positive_structure_payout_records',
    'window_column','created_at','window_start_exclusive',v_since,
    'nominal_record_discrepancy',round(v_excess,2),'payout_records',v_records,
    'payment_evidence','not_established_by_this_detector',
    'legacy_key_semantics',jsonb_build_object(
      'players_double_paid','tournament_user_groups_with_multiple_records',
      'sample.paid','sum_of_recorded_amounts',
      'excess','sum_of_recorded_amounts_minus_largest_record_per_group'),
    'classifications',v_classes,
    'record_evidence',v_evidence,
    'evidence_limits',jsonb_build_object('groups',30,'records_per_group',4,'key_characters',512),
    'evidence_groups',v_evidence_groups,'evidence_groups_omitted',v_players-v_evidence_groups,
    'evidence_records',v_evidence_records,'evidence_records_omitted',v_records-v_evidence_records,
    'key_evidence_semantics','reservation_only_not_proof_of_wallet_credit');

  IF v_players > 0 THEN
    INSERT INTO public.financial_alerts(severity,source,message,context)
    SELECT 'critical','fn_ca_duplicate_structure_payout_check',
      format('%s tournament/player group(s) across %s tournament(s) have multiple positive structure payout records inserted in the last %s hour(s); nominal record discrepancy %s. Payment and place lineage require investigation.',
        v_players,v_events,GREATEST(p_hours,1),round(v_excess,2)),v_context
    WHERE NOT EXISTS (
      SELECT 1 FROM public.financial_alerts fa
      WHERE fa.source = 'fn_ca_duplicate_structure_payout_check' AND fa.resolved IS NOT TRUE);
  END IF;
  RETURN v_context || jsonb_build_object('ok',true,'players_double_paid',v_players);
END;
$$;


ALTER FUNCTION public.fn_ca_duplicate_structure_payout_check(p_hours integer) OWNER TO postgres;

