--
-- TOC entry 5395 (class 1255 OID 25586920)
-- Name: fn_ca_eliminate_absent_tournament_players(integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_eliminate_absent_tournament_players(p_min_absent_minutes integer DEFAULT 10, p_limit integer DEFAULT 500, p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_dwell integer := GREATEST(COALESCE(p_min_absent_minutes, 10), 1);
  v_limit integer := GREATEST(COALESCE(p_limit, 500), 0);
  r record;
  v_considered integer := 0;
  v_eliminated integer := 0;
  v_refused_by_guard integer := 0;
  v_field_protected integer := 0;
  v_live_after integer;
  v_events jsonb := '[]'::jsonb;
  v_per_event jsonb := '{}'::jsonb;
  v_key text;
BEGIN
  FOR r IN
    SELECT p.tournament_id, p.user_id, t.name AS tournament_name,
           (SELECT max(s.left_at)
              FROM public.table_seats s
              JOIN public.tables tb ON tb.id = s.table_id
             WHERE tb.tournament_id = t.id AND s.user_id = p.user_id) AS lost_chair_at
      FROM public.tournaments t
      JOIN public.tournament_players p ON p.tournament_id = t.id
     WHERE t.status = 'RUNNING'
       AND p.status IN ('playing', 'registered')
       /* THE KNOCKOUT DOOR OWNS EVERY BUST A HAND TOOK (2026-09-10): a player
          whose latest knockout candidate is not 'rebought' was busted by an
          accepted hand and belongs to fn_eliminate_tournament_player_atomic.
          This sweep took 1,270 of them in seven hours, each without a
          finishing place, and the reprice proof then refused every event. */
       AND COALESCE((SELECT c.state FROM public.tournament_knockout_candidates c
                       WHERE c.tournament_id = t.id AND c.eliminated_user_id = p.user_id
                       ORDER BY c.hand_number DESC, c.id DESC LIMIT 1), 'rebought') = 'rebought'
       /* THE FELT DECIDES WHO BUSTED, NOT THE MIRROR (2026-09-10).
          Two clauses here read the wrong thing and between them this
          sweep has never been able to eliminate the players it exists
          for. Measured 2026-09-10: 68 seatless players across 18 RUNNING
          tournaments, 34 of which had been RUNNING for over six hours
          and cannot end while a roster row still says playing.
            1. COALESCE(p.chips,0) <= 0 trusts tournament_players.chips,
               a MIRROR. 39 of the 68 carry chips > 0 there - 151,500
               chips in total - while max(stack) across every seat they
               have ever held in the tournament is ZERO. They never held
               a chip on the felt. The sweep skipped exactly the rows
               whose mirror was wrong, which is why it has run every 15
               minutes, succeeded every time, and repaired none of them.
            2. NOT EXISTS (... stack > 0) tested EVERY seat row, live or
               vacated. A vacated seat keeps its stack for history, so a
               player who ever held chips was protected from elimination
               permanently.
          The felt is where the engine settles every hand. A player has
          busted when they hold NO live seat and the seat they last left
          held nothing. A player between tables mid-consolidation still
          has a non-zero last seat, so this cannot evict them - measured
          on Night Owl b84f312f, where one player was seatless for 59
          minutes holding 256,000 and is correctly untouched. */
       AND NOT EXISTS (
             SELECT 1 FROM public.table_seats s
               JOIN public.tables tb ON tb.id = s.table_id
              WHERE tb.tournament_id = t.id AND s.user_id = p.user_id
                AND s.left_at IS NULL)
       AND COALESCE((
             SELECT s.stack FROM public.table_seats s
               JOIN public.tables tb ON tb.id = s.table_id
              WHERE tb.tournament_id = t.id AND s.user_id = p.user_id
              ORDER BY s.left_at DESC NULLS FIRST, s.joined_at DESC
              LIMIT 1), 0) <= 0
     ORDER BY p.tournament_id, p.user_id
     LIMIT v_limit
  LOOP
    IF r.lost_chair_at IS NULL
       OR r.lost_chair_at > now() - make_interval(mins => v_dwell) THEN
      CONTINUE;
    END IF;
    v_considered := v_considered + 1;

    /* NEVER EMPTY A FIELD. Counted fresh for every row, because the rows
       before it in this same call have already changed the count. */
    SELECT count(*) - 1 INTO v_live_after
      FROM public.tournament_players tp
     WHERE tp.tournament_id = r.tournament_id
       AND tp.status IN ('playing', 'registered');
    IF v_live_after < 1 THEN
      v_field_protected := v_field_protected + 1;
      CONTINUE;
    END IF;

    IF p_dry_run THEN
      v_eliminated := v_eliminated + 1;
    ELSE
      /* eliminated_at is the moment the chair was lost, not the moment this
         sweep noticed. The finish normalizer ranks by that column, so a late
         stamp would hand a player who left at noon a better place than one who
         busted at midnight. position is deliberately left NULL: places are the
         normalizer's to assign from chronology at the finish. */
      UPDATE public.tournament_players tp
         SET status = 'eliminated',
             chips = 0,
             eliminated_at = r.lost_chair_at
       WHERE tp.tournament_id = r.tournament_id
         AND tp.user_id = r.user_id
         AND tp.status IN ('playing', 'registered');
      IF FOUND THEN
        v_eliminated := v_eliminated + 1;
      ELSE
        /* fn_refuse_zero_chip_field_elimination returns NULL rather than
           raising when every live player reads zero, so a dropped write is
           counted, not assumed. */
        v_refused_by_guard := v_refused_by_guard + 1;
        CONTINUE;
      END IF;
    END IF;

    v_key := r.tournament_id::text;
    v_per_event := jsonb_set(v_per_event, ARRAY[v_key],
      to_jsonb(COALESCE((v_per_event->>v_key)::integer, 0) + 1), true);
  END LOOP;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'tournament_id', k.key,
           'tournament_name', (SELECT t.name FROM public.tournaments t WHERE t.id = k.key::uuid),
           'players', k.value)), '[]'::jsonb)
    INTO v_events
    FROM jsonb_each(v_per_event) k;

  IF v_eliminated > 0 AND NOT p_dry_run THEN
    PERFORM public.fn_raise_server_financial_alert(
      'warning', 'fn_ca_eliminate_absent_tournament_players',
      v_eliminated || ' player(s) with no chips and no chair were recorded out of their event. '
        || 'Each had been off the felt for more than ' || v_dwell || ' minute(s) and no hand '
        || 'had taken their stack, so the knockout door could never have reached them. '
        || 'Their finishing places are left for the finish normalizer to derive from '
        || 'bust chronology.',
      jsonb_build_object('events', v_events, 'dwell_minutes', v_dwell,
                         'considered', v_considered,
                         'refused_by_zero_chip_guard', v_refused_by_guard,
                         'field_protected', v_field_protected),
      'absent-players:' || CURRENT_DATE::text);
  END IF;

  INSERT INTO public.ca_detector_runs (detector, detail)
  VALUES ('fn_ca_absent_tournament_players',
          jsonb_build_object('eliminated', v_eliminated, 'considered', v_considered,
                             'refused_by_zero_chip_guard', v_refused_by_guard,
                             'field_protected', v_field_protected,
                             'dry_run', p_dry_run, 'dwell_minutes', v_dwell));

  RETURN jsonb_build_object(
    'ok', true, 'dry_run', p_dry_run, 'dwell_minutes', v_dwell,
    'considered', v_considered, 'eliminated', v_eliminated,
    'refused_by_zero_chip_guard', v_refused_by_guard,
    'field_protected', v_field_protected, 'events', v_events);
END;
$$;


ALTER FUNCTION public.fn_ca_eliminate_absent_tournament_players(p_min_absent_minutes integer, p_limit integer, p_dry_run boolean) OWNER TO postgres;

--
-- TOC entry 45741 (class 0 OID 0)
-- Dependencies: 5395
-- Name: FUNCTION fn_ca_eliminate_absent_tournament_players(p_min_absent_minutes integer, p_limit integer, p_dry_run boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_eliminate_absent_tournament_players(p_min_absent_minutes integer, p_limit integer, p_dry_run boolean) IS 'Records out of the event every player who has held no chips and no chair for longer than the dwell time. The second door into elimination: it proves absence rather than a knockout, because no hand took these stacks and the knockout door can never reach them. Leaves position NULL for the finish normalizer and never empties a field.';


--
-- TOC entry 9344 (class 1255 OID 137567731)
-- Name: fn_ca_emergency_cashout_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_emergency_cashout_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF lower(COALESCE(NEW.status,'')) IN('pending','approved','completed','paid') THEN PERFORM public.fn_ca_assert_emergency_path('cashout'); END IF;
 ELSIF NEW.status IS DISTINCT FROM OLD.status AND lower(COALESCE(NEW.status,'')) IN('pending','approved','completed','paid')
  OR (NEW.completed_at IS NOT NULL AND OLD.completed_at IS NULL)
 THEN PERFORM public.fn_ca_assert_emergency_path('cashout'); END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_emergency_cashout_guard() OWNER TO postgres;

--
-- TOC entry 3355 (class 1255 OID 137567725)
-- Name: fn_ca_emergency_diamond_journal_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_emergency_diamond_journal_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE writer_stack text;
BEGIN
 IF NEW.amount>0 THEN
  UPDATE public.ca_emergency_refund_provenance SET journal_id=NEW.id,state='consumed'
   WHERE asset='diamonds' AND refund_key=NEW.reference_id AND user_id=NEW.user_id AND amount=NEW.amount AND state='planned';
  IF FOUND THEN RETURN NEW; END IF;
 END IF;
 IF NEW.amount>0 THEN
  -- Only the immutable, preflight-pinned original funded owners may bypass
  -- issuance. PG_CONTEXT is generated by PostgreSQL, not caller metadata.
  -- These owners atomically validate/debit their bank or counterparty before
  -- returning. Any owner failure rolls this credit back with its liability.
  GET DIAGNOSTICS writer_stack=PG_CONTEXT;
  IF writer_stack ~ E'(^|\\n)PL/pgSQL function (public\\.)?(fn_poker_diamond_release|fn_poker_diamond_tournament_pay|fn_poker_diamond_jackpot_pay|send_stream_gift|send_wallet_diamond_transfer|fn_diamond_game_pay_diamonds|fn_diamond_spin_settle_day|fn_wheel_diamond_cards_pick|fn_wheel_spin_core)\\([^\\n]*\\) line [0-9]+ at ' THEN RETURN NEW; END IF;
  PERFORM public.fn_ca_assert_emergency_path('positive_issuance');
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_emergency_diamond_journal_guard() OWNER TO postgres;

--
-- TOC entry 4704 (class 1255 OID 137567722)
-- Name: fn_ca_emergency_issuance_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_emergency_issuance_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE leg public.chip_ledger%ROWTYPE; parts text[]; week_start timestamptz; week_end timestamptz; retired numeric;
BEGIN
 -- The authoritative supply register covers every journal-origin issuer,
 -- bridge mint, opening grant and operator mint. A refund within circulating
 -- stores creates no mint row. A burn, correction or transfer is not issuance.
 IF NEW.asset='chips' AND NEW.action='mint' AND public.fn_ca_launch_is_retirement_reversal(NEW.chip_ledger_id) THEN RETURN NEW; END IF;
 IF NEW.asset IN('chips','diamonds') AND NEW.action='mint' AND NEW.amount>0 THEN
  IF EXISTS(SELECT 1 FROM public.ca_emergency_refund_provenance p WHERE p.asset=NEW.asset AND p.state='consumed'
   AND p.journal_id=COALESCE(NEW.chip_ledger_id,NEW.diamond_tx_id) AND p.amount=NEW.amount) THEN RETURN NEW; END IF;
  -- A standalone club is owed the rake it already retired. This existing
  -- bank restores an immutable week's receipts, rather than discretionary
  -- supply. Prove its exact key, journal direction and closed-week amount;
  -- neither a caller's reason nor an ambient setting can claim exemption.
  parts:=regexp_match(NEW.op_id,'^standalone-rake-bank:([0-9a-f-]{36}):([0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z)\.\.([0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z)$');
  IF NEW.asset='chips' AND parts IS NOT NULL AND parts[1]=NEW.holder_id::text AND NEW.holder_type='club' THEN
   SELECT * INTO leg FROM public.chip_ledger WHERE id=NEW.chip_ledger_id;
   week_start:=parts[2]::timestamptz; week_end:=parts[3]::timestamptz;
   IF leg.id IS NOT NULL AND leg.from_type='system_mint' AND leg.to_type='club_treasury'
    AND leg.to_entity_id=NEW.holder_id AND leg.amount=NEW.amount AND leg.idempotency_key=NEW.op_id AND leg.category='mint'
    AND week_start=public.fn_union_week_start(week_start) AND week_end=public.fn_union_week_start(week_start+interval '8 days')
    AND week_end<=public.fn_union_week_start(clock_timestamp())
    AND EXISTS(SELECT 1 FROM public.clubs WHERE id=NEW.holder_id AND is_union IS NOT TRUE) THEN
    SELECT COALESCE((SELECT sum(b.amount) FROM public.accounting_cash_bank_receipts b WHERE b.union_id IS NULL AND b.club_id=NEW.holder_id
     AND b.club_ledger_id IS NOT NULL AND b.banked_at>=week_start AND b.banked_at<week_end),0)
     +COALESCE((SELECT sum(s.amount) FROM public.tournament_rake_settlements s WHERE s.destination='chip_retirement:'||NEW.holder_id::text
      AND s.settled_at>=week_start AND s.settled_at<week_end),0) INTO retired;
    IF retired=NEW.amount THEN RETURN NEW; END IF;
   END IF;
  END IF;
  PERFORM public.fn_ca_assert_emergency_path('positive_issuance');
 END IF;
 RETURN NEW;
END $_$;


ALTER FUNCTION public.fn_ca_emergency_issuance_guard() OWNER TO postgres;

--
-- TOC entry 7099 (class 1255 OID 137567718)
-- Name: fn_ca_emergency_registration_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_emergency_registration_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  PERFORM public.fn_ca_assert_emergency_path('tournament_registration');
 ELSIF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
  OR COALESCE(NEW.rebuys,0)>COALESCE(OLD.rebuys,0) OR (NEW.add_on IS TRUE AND OLD.add_on IS DISTINCT FROM true)
  OR (upper(COALESCE(NEW.status::text,'')) IN('REGISTERED','REGISTRATION','ACTIVE') AND upper(COALESCE(OLD.status::text,'')) IN('ELIMINATED','UNREGISTERED','CANCELLED','REFUNDED'))
 THEN PERFORM public.fn_ca_assert_emergency_path('tournament_registration'); END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_emergency_registration_guard() OWNER TO postgres;

--
-- TOC entry 5592 (class 1255 OID 89799293)
-- Name: fn_ca_engine_live_minutes(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_engine_live_minutes(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  /* A FROZEN ENGINE MINUTE IS NOT A STUCK MINUTE (2026-10-03). Minutes in
     [p_from, p_to) during which the engine was NOT in a declared maintenance
     break. A break in progress counts for at most 20 minutes from its start
     (fn_platform_frozen never honours one longer than 15 from announcement).
     Undeclared downtime is live time. NULL in, NULL out. */
  WITH win AS (
    SELECT tstzrange(p_from, GREATEST(p_from, p_to), '[)') AS w
  ), frozen AS (
    SELECT tstzrange(b.break_started_at, b.break_ended_at, '[)') AS r
      FROM public.engine_maintenance_break_log b
     WHERE b.break_started_at < p_to
       AND b.break_ended_at > p_from
       AND b.break_ended_at > b.break_started_at
    UNION ALL
    SELECT tstzrange(o.started, LEAST(p_to, o.started + interval '20 minutes'), '[)')
      FROM (SELECT COALESCE(m.break_started_at, m.announced_at + interval '2 minutes') AS started
              FROM public.engine_maintenance_break m
             WHERE m.enforce_freeze) o
     WHERE o.started < p_to
  ), merged AS (
    SELECT range_agg(f.r * win.w) AS m
      FROM frozen f CROSS JOIN win
     WHERE NOT isempty(f.r * win.w)
  )
  SELECT CASE WHEN p_from IS NULL OR p_to IS NULL THEN NULL::numeric ELSE
         round(GREATEST(0::numeric,
               extract(epoch FROM (GREATEST(p_from, p_to) - p_from))
               - COALESCE((SELECT sum(extract(epoch FROM (upper(x) - lower(x))))
                             FROM merged, unnest(merged.m) x), 0)) / 60.0, 1) END
$$;


ALTER FUNCTION public.fn_ca_engine_live_minutes(p_from timestamp with time zone, p_to timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 8490 (class 1255 OID 137566471)
-- Name: fn_ca_engine_operator_claim_hourly(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_engine_operator_claim_hourly(p_announced_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
 IF current_setting('request.jwt.claim.role',true) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'engine_operator_forbidden' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(530093);
 SELECT id INTO v_id FROM public.ca_engine_operator_commands WHERE domain='maintenance' AND status='queued' AND announced_at<=p_announced_at ORDER BY announced_at LIMIT 1 FOR UPDATE;
 IF v_id IS NOT NULL THEN
  UPDATE public.ca_engine_operator_commands SET status='applying',announced_at=p_announced_at,updated_at=clock_timestamp() WHERE id=v_id;
 END IF;
 RETURN v_id;
END $$;


ALTER FUNCTION public.fn_ca_engine_operator_claim_hourly(p_announced_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 9516 (class 1255 OID 137566442)
-- Name: fn_ca_engine_operator_command(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_engine_operator_command(p_actor_id uuid, p_operation_id uuid, p_domain text, p_action text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v public.ca_engine_operator_commands; v_permissions jsonb; v_announcement timestamptz; v_before jsonb; v_close_targets uuid[];
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'engine_operator_forbidden' USING ERRCODE='42501'; END IF;
 v_permissions := public.fn_ca_operator_permissions(p_actor_id)->'permissions';
 IF jsonb_typeof(v_permissions) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'engine_operator_authority_unknown' USING ERRCODE='58000'; END IF;
 IF NOT coalesce(v_permissions ? CASE WHEN p_domain='floor' THEN 'clubs.write' ELSE 'settings.write' END,false) THEN RAISE EXCEPTION 'engine_operator_forbidden' USING ERRCODE='42501'; END IF;
 IF p_operation_id IS NULL OR p_reason IS NULL OR length(trim(p_reason)) NOT BETWEEN 10 AND 500 OR p_domain NOT IN ('floor','maintenance') THEN RAISE EXCEPTION 'invalid_operator_command'; END IF;
 PERFORM pg_advisory_xact_lock(530093);
 SELECT * INTO v FROM public.ca_engine_operator_commands WHERE id=p_operation_id FOR UPDATE;
 IF FOUND THEN
  IF v.actor_id<>p_actor_id OR v.domain<>p_domain THEN RAISE EXCEPTION 'operation_identity_conflict'; END IF;
  v_before:=to_jsonb(v);
  IF p_action IN ('cancel','end') AND p_domain='maintenance' THEN
   IF p_action='cancel' AND v.status='queued' AND clock_timestamp()<v.announced_at THEN
    UPDATE public.ca_engine_operator_commands SET status='cancelled',updated_at=clock_timestamp() WHERE id=v.id RETURNING * INTO v;
    PERFORM public.fn_log_admin_action(p_actor_id,'engine_operator.maintenance.cancel','engine_operator_command',v.id::text,jsonb_build_object('reason',p_reason),v_before,to_jsonb(v),NULL,NULL,v.id::text||':cancel');
   ELSIF p_action='cancel' AND v.status<>'cancelled' THEN RAISE EXCEPTION 'maintenance_already_applied';
   ELSIF p_action='end' AND v.status NOT IN ('applying','active','completed') THEN RAISE EXCEPTION 'maintenance_request_not_applied';
   ELSIF p_action='end' AND clock_timestamp()<v.announced_at+interval '7 minutes' THEN RAISE EXCEPTION 'maintenance_deadline_not_reached';
   ELSIF p_action='end' AND v.end_requested_at IS NULL THEN
    UPDATE public.ca_engine_operator_commands SET end_requested_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=v.id RETURNING * INTO v;
    PERFORM public.fn_log_admin_action(p_actor_id,'engine_operator.maintenance.end','engine_operator_command',v.id::text,jsonb_build_object('reason',p_reason),v_before,to_jsonb(v),NULL,NULL,v.id::text||':end');
   END IF;
  ELSIF v.action<>p_action OR v.reason<>p_reason THEN RAISE EXCEPTION 'operation_identity_conflict'; END IF;
  RETURN to_jsonb(v);
 END IF;
 IF p_domain='maintenance' AND p_action='start' THEN
  v_announcement:=date_trunc('hour',clock_timestamp())+interval '53 minutes';
  IF v_announcement<=clock_timestamp() THEN v_announcement:=v_announcement+interval '1 hour'; END IF;
  IF EXISTS(SELECT 1 FROM public.ca_engine_operator_commands WHERE domain='maintenance' AND status='queued') THEN RAISE EXCEPTION 'maintenance_request_already_queued'; END IF;
  INSERT INTO public.ca_engine_operator_commands(id,actor_id,domain,action,reason,status,announced_at,result,created_at,updated_at) VALUES(p_operation_id,p_actor_id,p_domain,p_action,p_reason,'queued',v_announcement,NULL,clock_timestamp(),clock_timestamp()) RETURNING * INTO v;
 ELSIF p_domain='floor' AND p_action IN ('pause','park','resume','close_cash') THEN
  IF p_action='close_cash' THEN
   -- Capture and lock the original full target set; never silently omit custody.
   SELECT coalesce(array_agg(t.id ORDER BY t.id),ARRAY[]::uuid[]) INTO v_close_targets
   FROM (SELECT id FROM public.tables st WHERE tournament_id IS NULL AND status IN ('running','active','waiting') AND (NOT EXISTS(SELECT 1 FROM public.ca_launch_operator_scopes m WHERE m.operation_id=p_operation_id) OR EXISTS(SELECT 1 FROM public.ca_launch_operator_scopes m WHERE m.operation_id=p_operation_id AND (st.club_id=ANY(m.club_ids) OR st.union_id=ANY(m.club_ids)))) ORDER BY id FOR UPDATE) t;
   IF EXISTS(SELECT 1 FROM public.tables WHERE id=ANY(v_close_targets) AND
      (is_deleted IS DISTINCT FROM false OR game_type IS DISTINCT FROM 'cash')) THEN
    RAISE EXCEPTION 'cash_floor_close_target_not_executable' USING ERRCODE='22023';
   END IF;
  END IF;
  INSERT INTO public.ca_engine_operator_commands(id,actor_id,domain,action,reason,status) VALUES(p_operation_id,p_actor_id,p_domain,p_action,p_reason,'accepted') RETURNING * INTO v;
  IF p_action='resume' THEN DELETE FROM public.ca_operator_floor_hold WHERE id=true;
  ELSIF p_action IN ('pause','park') THEN
   INSERT INTO public.ca_operator_floor_hold VALUES(true,p_operation_id,p_action,p_reason) ON CONFLICT(id) DO UPDATE SET operation_id=excluded.operation_id,mode=excluded.mode,reason=excluded.reason;
  ELSE
   IF EXISTS(SELECT 1 FROM public.ca_operator_table_closes WHERE status='pending') THEN RAISE EXCEPTION 'cash_floor_close_in_progress'; END IF;
   INSERT INTO public.ca_operator_table_closes(table_id,operation_id,actor_id,reason)
    SELECT id,p_operation_id,p_actor_id,p_reason FROM public.tables WHERE id=ANY(v_close_targets)
    ON CONFLICT(table_id) DO UPDATE SET operation_id=excluded.operation_id,actor_id=excluded.actor_id,reason=excluded.reason,status='pending' WHERE public.ca_operator_table_closes.status='closed';
   UPDATE public.ca_engine_operator_commands SET status=CASE WHEN EXISTS(SELECT 1 FROM public.ca_operator_table_closes WHERE operation_id=p_operation_id) THEN 'accepted' ELSE 'completed' END,result=jsonb_build_object('targetedTables',(SELECT count(*) FROM public.ca_operator_table_closes WHERE operation_id=p_operation_id),'scope','cash_tables_only') WHERE id=p_operation_id RETURNING * INTO v;
  END IF;
 ELSE RAISE EXCEPTION 'invalid_operator_command'; END IF;
 PERFORM public.fn_log_admin_action(p_actor_id,'engine_operator.'||p_domain||'.'||p_action,'engine_operator_command',v.id::text,jsonb_build_object('reason',p_reason,'operation_id',v.id),NULL,to_jsonb(v),NULL,NULL,v.id::text||':'||p_action);
 RETURN to_jsonb(v);
END $$;


ALTER FUNCTION public.fn_ca_engine_operator_command(p_actor_id uuid, p_operation_id uuid, p_domain text, p_action text, p_reason text) OWNER TO postgres;

--
-- TOC entry 4857 (class 1255 OID 137566464)
-- Name: fn_ca_engine_operator_observe(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_engine_operator_observe(p_operation_id uuid, p_status text, p_result jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'engine_operator_forbidden' USING ERRCODE='42501'; END IF;
 IF p_status NOT IN ('active','completed','accepted') THEN RAISE EXCEPTION 'invalid_operator_status'; END IF;
 UPDATE public.ca_engine_operator_commands SET status=p_status,result=p_result,updated_at=clock_timestamp()
 WHERE id=p_operation_id AND status<>'cancelled';
END $$;


