--
-- TOC entry 3551 (class 1255 OID 18305276)
-- Name: fn_ca_guard_watchlist(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_guard_watchlist() RETURNS text[]
    LANGUAGE sql STABLE
    AS $$
  SELECT ARRAY(
    SELECT DISTINCT x FROM unnest(ARRAY[
