-- TOC entry 4992 (class 1255 OID 28805423)
-- Name: fn_ca_knockout_door_stalled(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_knockout_door_stalled(p_stall_minutes integer DEFAULT 15) RETURNS TABLE(last_resolved_at timestamp with time zone, stalled_minutes numeric, pending_candidates bigint, pending_past_prompt bigint, oldest_expired_prompt_minutes numeric, detail text)
    LANGUAGE sql STABLE
    AS $$
  WITH k AS (
    SELECT max(resolved_at) AS last_resolved_at,
           count(*) FILTER (WHERE resolved_at IS NULL) AS pending,
           count(*) FILTER (WHERE resolved_at IS NULL
                              AND (rebuy_prompt_until IS NULL
                                   OR rebuy_prompt_until < now())) AS past_prompt,
           min(COALESCE(rebuy_prompt_until, created_at))
             FILTER (WHERE resolved_at IS NULL
                       AND (rebuy_prompt_until IS NULL
                            OR rebuy_prompt_until < now())) AS oldest_prompt
      FROM public.tournament_knockout_candidates c
     -- A CANDIDATE OF A FINISHED EVENT IS NOBODY WAITING (2026-10-15). A
     -- cancelled or completed event has no door left: its terminal authority
     -- refunded or paid its players. Counting its stale candidate kept this
     -- read firing for 25 days on one candidate of a tournament cancelled on
     -- 2026-09-27. Resolved rows still date the door; the status is read per
     -- pending row only, through the tournaments primary key.
     WHERE c.resolved_at IS NOT NULL
        OR upper(COALESCE((SELECT t.status FROM public.tournaments t
                            WHERE t.id = c.tournament_id), ''))
           NOT IN ('COMPLETED', 'CANCELLED', 'CANCELED')
  )
  SELECT k.last_resolved_at,
         round((extract(epoch FROM (now() - k.last_resolved_at)) / 60.0)::numeric, 1),
         k.pending, k.past_prompt,
         round((extract(epoch FROM (now() - k.oldest_prompt)) / 60.0)::numeric, 1),
         'the knockout door has not resolved a single candidate for '
           || round((extract(epoch FROM (now() - k.last_resolved_at)) / 60.0)::numeric, 1)
           || ' minute(s) while ' || k.past_prompt
           || ' candidate(s) are waiting with no open rebuy decision, '
           || 'the oldest for '
           || round((extract(epoch FROM (now() - k.oldest_prompt)) / 60.0)::numeric, 1)
           || ' minute(s). Healthy is a gap of 2.04s (p50) and 19.19s (p99): '
           || 'this is not a quiet door, it is a stopped one, and every player '
           || 'behind it is neither eliminated nor allowed to rebuy'
    FROM k
   WHERE k.past_prompt > 0
     AND (k.last_resolved_at IS NULL
          OR k.last_resolved_at < now() - make_interval(mins => GREATEST(p_stall_minutes, 1)))
$$;


ALTER FUNCTION public.fn_ca_knockout_door_stalled(p_stall_minutes integer) OWNER TO postgres;

--
-- TOC entry 45902 (class 0 OID 0)
-- Dependencies: 4992
-- Name: FUNCTION fn_ca_knockout_door_stalled(p_stall_minutes integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_knockout_door_stalled(p_stall_minutes integer) IS 'Critical when max(resolved_at) on tournament_knockout_candidates is older than the stall window WHILE pending candidates sit past their rebuy_prompt_until. Measured over 50,153 gaps in 7 days: p50 2.04s, p99 19.19s, p99.9 461.5s; only 19 gaps (0.038%) passed 15 minutes and every one was a stall. On 2026-09-12 this froze at 00:03:15 for 265.1 minutes.';


--
-- TOC entry 6048 (class 1255 OID 18540016)
-- Name: fn_ca_largest_remainder_cents(numeric, numeric[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_largest_remainder_cents(p_total_cents numeric, p_weights numeric[]) RETURNS numeric[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  WITH w AS (
    SELECT ord, GREATEST(COALESCE(weight, 0), 0) AS weight
      FROM unnest(p_weights) WITH ORDINALITY AS t(weight, ord)
  ), tot AS (
    SELECT NULLIF(sum(weight), 0) AS s FROM w
  ), base AS (
    SELECT w.ord,
           floor(p_total_cents * w.weight / tot.s)                                  AS c,
           (p_total_cents * w.weight / tot.s)
             - floor(p_total_cents * w.weight / tot.s)                              AS frac
      FROM w CROSS JOIN tot
     WHERE tot.s IS NOT NULL
  ), leftover AS (
    SELECT GREATEST(p_total_cents - COALESCE(sum(c), 0), 0) AS n FROM base
  ), ranked AS (
    SELECT ord, c, row_number() OVER (ORDER BY frac DESC, ord ASC) AS rk FROM base
  )
  SELECT COALESCE(
           array_agg(c + CASE WHEN rk <= (SELECT n FROM leftover) THEN 1 ELSE 0 END
                     ORDER BY ord),
           ARRAY[]::numeric[])
    FROM ranked;
$$;


ALTER FUNCTION public.fn_ca_largest_remainder_cents(p_total_cents numeric, p_weights numeric[]) OWNER TO postgres;

