--
-- TOC entry 3991 (class 1255 OID 159428450)
-- Name: fn_ca_launch_cash_close_resumed(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_launch_cash_close_resumed(p_table uuid, p_close uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.ca_launch_floor_resume_receipts r
 JOIN public.ca_operator_table_closes c ON c.table_id=r.table_id AND c.operation_id=r.close_operation_id AND c.actor_id=r.actor_id AND c.status='closed'
 JOIN public.ca_engine_operator_commands done ON done.id=r.resume_operation_id AND done.actor_id=r.actor_id AND done.domain='floor' AND done.action='resume'
 JOIN public.ca_launch_operator_scopes park ON park.operation_id=r.park_operation_id AND park.actor_id=r.actor_id
 JOIN public.ca_launch_operator_scopes resume ON resume.operation_id=r.resume_operation_id AND resume.actor_id=r.actor_id AND resume.club_ids=park.club_ids
 JOIN public.tables t ON t.id=r.table_id AND t.tournament_id IS NULL AND (t.club_id=ANY(park.club_ids) OR t.union_id=ANY(park.club_ids))
 WHERE r.table_id=p_table AND r.close_operation_id=p_close);
$$;


ALTER FUNCTION public.fn_ca_launch_cash_close_resumed(p_table uuid, p_close uuid) OWNER TO postgres;

--
-- TOC entry 5453 (class 1255 OID 159428060)
-- Name: fn_ca_launch_cashier_activate(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_launch_cashier_activate(p_operation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE o public.ca_launch_reset_operations%ROWTYPE; relation text; rows bigint:=0; n bigint;
BEGIN
 PERFORM public.fn_ca_launch_cashier_assert_drained(p_operation);
 SELECT * INTO o FROM public.ca_launch_reset_operations WHERE operation_id=p_operation;
 FOREACH relation IN ARRAY ARRAY['cashout_requests','chip_requests','credit_requests','cashier_rpc_operation_intents','accounting_cashier_events','cashier_operations'] LOOP
  EXECUTE format('INSERT INTO public.ca_launch_accounting_archives(operation_id,relation_name,row_key,before_image,row_sha256,captured_at) SELECT $1,%L,jsonb_build_array(to_jsonb(t)->%L)::text,to_jsonb(t),encode(sha256(convert_to(to_jsonb(t)::text,''UTF8'')),''hex''),$2 FROM public.%I t WHERE club_id=ANY($3)',relation,CASE WHEN relation='cashier_rpc_operation_intents' THEN 'operation_id' ELSE 'id' END,relation)
   USING p_operation,o.captured_at,o.scoped_club_ids;
  GET DIAGNOSTICS n=ROW_COUNT; rows:=rows+n;
 END LOOP;
 RETURN jsonb_build_object('operation_id',p_operation,'cashier_rows_archived',rows,'request_balances_mutated',false);
END $_$;


ALTER FUNCTION public.fn_ca_launch_cashier_activate(p_operation uuid) OWNER TO postgres;

--
-- TOC entry 4990 (class 1255 OID 159428058)
-- Name: fn_ca_launch_cashier_assert_drained(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_launch_cashier_assert_drained(p_operation uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE o public.ca_launch_reset_operations%ROWTYPE;
BEGIN
 IF public.fn_caller_is_engine() IS NOT TRUE OR public.fn_platform_frozen() IS NOT TRUE THEN
  RAISE EXCEPTION 'LAUNCH_CASHIER_REQUIRES_ENGINE_AND_FREEZE' USING ERRCODE='42501'; END IF;
 SELECT * INTO o FROM public.ca_launch_reset_operations WHERE operation_id=p_operation FOR UPDATE;
 IF NOT FOUND OR o.state NOT IN('captured','executed') THEN
  RAISE EXCEPTION 'LAUNCH_CASHIER_OPERATION_REQUIRED'; END IF;
 -- Never cancel a funded hold by changing its status. The original custody
 -- refund must finish before closing positions are captured.
 IF EXISTS(SELECT 1 FROM public.cashout_requests WHERE club_id=ANY(o.scoped_club_ids) AND status IN('pending','approved','cancelling','completing'))
 OR EXISTS(SELECT 1 FROM public.chip_requests WHERE club_id=ANY(o.scoped_club_ids) AND status='pending')
 OR EXISTS(SELECT 1 FROM public.credit_requests WHERE club_id=ANY(o.scoped_club_ids) AND status='pending')
 OR EXISTS(SELECT 1 FROM public.cashier_rpc_operation_intents WHERE club_id=ANY(o.scoped_club_ids) AND receipt IS NULL)
 OR EXISTS(SELECT 1 FROM public.chip_escrow e JOIN public.cashout_requests r ON r.id=e.cashout_request_id WHERE r.club_id=ANY(o.scoped_club_ids) AND e.released_at IS NULL)
 THEN RAISE EXCEPTION 'LAUNCH_CASHIER_ORIGINAL_REQUEST_DRAIN_REQUIRED' USING ERRCODE='55006'; END IF;
END $$;


ALTER FUNCTION public.fn_ca_launch_cashier_assert_drained(p_operation uuid) OWNER TO postgres;

--
-- TOC entry 8532 (class 1255 OID 159428048)
-- Name: fn_ca_launch_cashier_request_boundary(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_launch_cashier_request_boundary() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE cut timestamptz;
BEGIN
 cut:=public.fn_ca_launch_accounting_cutoff('club',NEW.club_id);
 IF cut IS NULL THEN RETURN NEW; END IF;
 -- A delayed or backdated request cannot create an old obligation after launch.
 IF TG_OP='INSERT' AND (NEW.created_at IS NULL OR NEW.created_at<cut) THEN
  RAISE EXCEPTION 'LAUNCH_PREVIOUS_CASHIER_REQUEST_IS_WAIVED' USING ERRCODE='55000';
 END IF;
 IF TG_OP='UPDATE' AND (OLD.created_at IS NULL OR OLD.created_at<cut)
   AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.club_id IS DISTINCT FROM OLD.club_id) THEN
  RAISE EXCEPTION 'LAUNCH_PREVIOUS_CASHIER_REQUEST_IS_WAIVED' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_launch_cashier_request_boundary() OWNER TO postgres;

--
-- TOC entry 7285 (class 1255 OID 159428061)
-- Name: fn_ca_launch_cashier_undo(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_launch_cashier_undo(p_operation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 PERFORM public.fn_ca_launch_cashier_assert_drained(p_operation);
 -- No source request, intent or custody row was mutated. Accounting undo
 -- deactivates the shared boundary; original completed receipts stay truthful.
 RETURN jsonb_build_object('operation_id',p_operation,'cashier_sources_unchanged',true);
END $$;


ALTER FUNCTION public.fn_ca_launch_cashier_undo(p_operation uuid) OWNER TO postgres;

--
-- TOC entry 6981 (class 1255 OID 159427953)
-- Name: fn_ca_launch_closing_leg_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_launch_closing_leg_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE p public.ca_launch_reset_positions%ROWTYPE;
BEGIN
 IF NEW.metadata->>'entry_kind' IS DISTINCT FROM 'launch_closing_position' THEN RETURN NEW; END IF;
 SELECT * INTO p FROM public.ca_launch_reset_positions WHERE closing_leg_id=NEW.id;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.ca_launch_reset_operations o
 WHERE o.operation_id=p.operation_id AND o.state='captured')
 OR NEW.idempotency_key IS DISTINCT FROM 'launch-closing:'||NEW.id::text
 OR NEW.category IS DISTINCT FROM 'adjustment'
 OR NEW.from_type IS DISTINCT FROM p.account_type OR NEW.to_type IS DISTINCT FROM p.account_type
 OR NEW.from_entity_id IS DISTINCT FROM p.entity_id OR NEW.to_entity_id IS DISTINCT FROM p.entity_id
 OR NEW.from_label IS DISTINCT FROM p.relation_name||'.'||p.column_name
 OR NEW.to_label IS DISTINCT FROM NEW.from_label
 OR NEW.amount IS DISTINCT FROM 0::numeric
 OR NEW.pre_from_balance IS DISTINCT FROM round(p.balance,2)
 OR NEW.post_from_balance IS DISTINCT FROM round(p.balance,2)
 OR NEW.pre_to_balance IS DISTINCT FROM round(p.balance,2)
 OR NEW.post_to_balance IS DISTINCT FROM round(p.balance,2)
 OR NEW.metadata->'exact_balance' IS DISTINCT FROM coalesce(to_jsonb(p.balance),'null'::jsonb)
 OR NEW.metadata->>'operation_id' IS DISTINCT FROM p.operation_id::text
 THEN RAISE EXCEPTION 'LAUNCH_CLOSING_LEG_HAS_NO_EXACT_POSITION' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_launch_closing_leg_guard() OWNER TO postgres;

--
-- TOC entry 8454 (class 1255 OID 166962462)
-- Name: fn_ca_launch_health(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_launch_health() RETURNS TABLE(area text, status text, detail jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v jsonb;
  v_status text;
  v_worst int := 0;
  v_rank constant jsonb := '{"green":0,"amber":1,"red":2,"unknown":2}';
  n_crit bigint; n_warn bigint; n_fail bigint; n_stuck bigint;
BEGIN
  -- 1. Open financial alerts. Every unresolved critical is red: it is either
  -- a live defect or an alert nobody has closed, and both block launch.
  SELECT count(*) FILTER (WHERE f.severity = 'critical'),
         count(*) FILTER (WHERE f.severity IS DISTINCT FROM 'critical')
    INTO n_crit, n_warn
    FROM public.financial_alerts f
   WHERE f.resolved IS NOT TRUE;
  SELECT COALESCE(jsonb_object_agg(x.source || ':' || x.severity, x.n), '{}'::jsonb) INTO v
    FROM (SELECT f.source, f.severity, count(*) AS n FROM public.financial_alerts f
           WHERE f.resolved IS NOT TRUE GROUP BY 1, 2) x;
  v_status := CASE WHEN n_crit > 0 THEN 'red' WHEN n_warn > 0 THEN 'amber' ELSE 'green' END;
  area := 'financial_alerts'; status := v_status;
  detail := jsonb_build_object('critical', n_crit, 'warning', n_warn, 'by_source', v);
  v_worst := GREATEST(v_worst, (v_rank->>status)::int); RETURN NEXT;

  -- 2. Hand settlement over the last hour.
  BEGIN
    SELECT s.failed, s.stuck, to_jsonb(s) INTO n_fail, n_stuck, v FROM public.fn_settlement_health(60) s;
    status := CASE WHEN n_fail > 0 OR n_stuck > 0 THEN 'red' ELSE 'green' END;
  EXCEPTION WHEN OTHERS THEN
    status := 'unknown'; v := jsonb_build_object('error', SQLERRM);
  END;
  area := 'hand_settlement'; detail := v;
  v_worst := GREATEST(v_worst, (v_rank->>status)::int); RETURN NEXT;

  -- 3. Weekly accounting closes. A scope still open more than 48 hours after
  -- its week ended is red; a close in progress inside that is amber.
  SELECT COALESCE(jsonb_agg(jsonb_build_object('scope_kind', r.scope_kind, 'scope_id', r.scope_id,
           'period_end', r.period_end, 'status', r.status, 'attempts', r.attempts,
           'last_visit', r.last_scheduler_visit_at) ORDER BY r.period_end), '[]'::jsonb),
         CASE WHEN bool_or(now() > r.period_end + interval '48 hours') THEN 'red'
              WHEN count(*) > 0 THEN 'amber' ELSE 'green' END
    INTO v, status
    FROM public.union_accounting_runs r
   WHERE r.status IS DISTINCT FROM 'complete'
     -- A week the owner moved below a settlement floor (20260920232523) is
     -- preserved history with its obligations recorded, not an open close.
     AND NOT EXISTS (SELECT 1 FROM public.union_settlement_floor u
                      WHERE r.scope_kind = 'union' AND u.union_id = r.scope_id
                        AND r.period_start < u.earliest_period_start)
     AND NOT EXISTS (SELECT 1 FROM public.club_settlement_floor c
                      WHERE r.scope_kind = 'club' AND c.club_id = r.scope_id
                        AND r.period_start < c.earliest_period_start);
  area := 'weekly_close'; detail := jsonb_build_object('open_scopes', v);
  v_worst := GREATEST(v_worst, (v_rank->>status)::int); RETURN NEXT;

  -- 4. Tournaments: a running event that has dealt no hand for 15 minutes
  -- while not on a break, or an event still registering 15 minutes after its
  -- start, is red.
  SELECT jsonb_build_object(
           'running_silent', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name))
              FROM public.tournaments t
             WHERE t.status = 'RUNNING' AND NOT COALESCE(t.on_break, false)
               AND t.started_at < now() - interval '15 minutes'
               AND NOT EXISTS (SELECT 1 FROM public.hand_history h
                                WHERE h.tournament_id = t.id
                                  AND h.created_at > now() - interval '15 minutes')), '[]'::jsonb),
           'start_overdue', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'start_time', t.start_time))
              FROM public.tournaments t
             WHERE t.status = 'REGISTERING' AND t.tournament_type IN ('MTT', 'SATELLITE') AND t.start_time < now() - interval '15 minutes'
               -- A PARKED FLOOR IS NOT AN OVERDUE START (20261015182553).
               AND NOT public.fn_ca_launch_health_tournament_held(t.club_id, t.union_id)), '[]'::jsonb),
           'held_by_operator', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'start_time', t.start_time))
              FROM public.tournaments t
             WHERE t.status = 'REGISTERING' AND t.tournament_type IN ('MTT', 'SATELLITE') AND t.start_time < now() - interval '15 minutes'
               AND public.fn_ca_launch_health_tournament_held(t.club_id, t.union_id)), '[]'::jsonb))
    INTO v;
  status := CASE WHEN jsonb_array_length(v->'running_silent') > 0
                   OR jsonb_array_length(v->'start_overdue') > 0 THEN 'red' ELSE 'green' END;
  IF COALESCE(public.fn_platform_frozen(), false) THEN
    status := 'green'; v := v || jsonb_build_object('note', 'platform frozen for the maintenance break');
  END IF;
  area := 'tournaments'; detail := v;
  v_worst := GREATEST(v_worst, (v_rank->>status)::int); RETURN NEXT;

  -- 5. Scheduled jobs over the last 24 hours.
  BEGIN
    SELECT COALESCE(jsonb_agg(jsonb_build_object('job', c.jobname, 'verdict', c.verdict,
             'last_error', left(c.last_error, 200)) ORDER BY c.jobname)
             FILTER (WHERE c.verdict IN ('critical', 'warn')), '[]'::jsonb),
           CASE WHEN bool_or(c.verdict = 'critical') THEN 'red'
                WHEN bool_or(c.verdict = 'warn') THEN 'amber' ELSE 'green' END
      INTO v, status
      FROM public.fn_ca_cron_health(interval '24 hours') c;
  EXCEPTION WHEN OTHERS THEN
    status := 'unknown'; v := jsonb_build_object('error', SQLERRM);
  END;
  area := 'scheduled_jobs'; detail := jsonb_build_object('not_ok', v);
  v_worst := GREATEST(v_worst, (v_rank->>status)::int); RETURN NEXT;

  -- 6. Overall: the worst of the above. "unknown" counts as red, because a
  -- reading that could not be taken is not a green one.
  area := 'launch';
  status := CASE v_worst WHEN 0 THEN 'green' WHEN 1 THEN 'amber' ELSE 'red' END;
  detail := jsonb_build_object('checked_at', now());
  RETURN NEXT;
END
$$;


