--
-- TOC entry 6627 (class 1255 OID 159428258)
-- Name: fn_ca_launch_reset_undo(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_launch_reset_undo(p_operation uuid, p_expected_closing_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET lock_timeout TO '4s'
    AS $$
DECLARE op public.ca_launch_reset_operations%ROWTYPE; pos public.ca_launch_reset_positions%ROWTYPE;
 mutation public.ca_launch_reset_mutations%ROWTYPE; c uuid; minted numeric; answer jsonb; original public.ca_mint_ledger%ROWTYPE;
 v_leg uuid; v_before numeric; v_after numeric; got numeric; predicate text; selected_rows bigint; pool public.bbj_pools%ROWTYPE; old_main numeric; difference numeric;
BEGIN
 PERFORM public.fn_ca_launch_reset_assert_drained();
 IF NOT pg_try_advisory_xact_lock(530090,1) OR NOT pg_try_advisory_xact_lock(hashtext('ca_launch_reset')) THEN RAISE EXCEPTION 'LAUNCH_RESET_ENTRY_GATE_BUSY' USING ERRCODE='55P03'; END IF;
 SELECT * INTO op FROM public.ca_launch_reset_operations WHERE operation_id=p_operation FOR UPDATE;
 IF NOT FOUND OR op.state<>'executed' OR op.closing_sha256 IS DISTINCT FROM p_expected_closing_sha256 THEN RAISE EXCEPTION 'LAUNCH_UNDO_NOT_EXACT_EXECUTION'; END IF;
 PERFORM 1 FROM public.clubs WHERE id=ANY(op.scoped_club_ids) ORDER BY id FOR UPDATE;
 IF (SELECT count(*) FROM public.club_members WHERE club_id=ANY(op.scoped_club_ids))<>(SELECT count(*) FROM public.ca_launch_reset_rows WHERE operation_id=p_operation AND relation_name='club_members') THEN RAISE EXCEPTION 'LAUNCH_UNDO_ROSTER_CHANGED'; END IF;
 IF EXISTS(SELECT 1 FROM public.ca_launch_reset_rows r LEFT JOIN public.club_members m ON m.club_id=(r.row_key->>'club_id')::uuid AND m.user_id=(r.row_key->>'user_id')::uuid LEFT JOIN public.profiles p ON p.id=m.user_id WHERE r.operation_id=p_operation AND r.relation_name='club_members' AND (p.id IS NULL OR to_jsonb(p.status) IS DISTINCT FROM r.raw_row->'launch_profile_status' OR to_jsonb(p.is_horse) IS DISTINCT FROM r.raw_row->'launch_is_horse')) THEN RAISE EXCEPTION 'LAUNCH_UNDO_IDENTITY_CHANGED'; END IF;
 -- A stale undo may never overwrite resumed play or a later deposit. Refuse
 -- before restoring any value when any captured post-position has moved.
 FOR mutation IN SELECT * FROM public.ca_launch_reset_mutations WHERE operation_id=p_operation ORDER BY relation_name,row_key::text,column_name LOOP
  predicate:=CASE WHEN mutation.relation_name='club_members' THEN format('club_id=%L::uuid AND user_id=%L::uuid',mutation.row_key->>'club_id',mutation.row_key->>'user_id') ELSE format('id=%L::uuid',mutation.row_key->>'id') END;
  EXECUTE format('SELECT %I FROM public.%I WHERE %s FOR UPDATE',mutation.column_name,mutation.relation_name,predicate) INTO got;
  GET DIAGNOSTICS selected_rows=ROW_COUNT;
  IF selected_rows<>1 OR got IS DISTINCT FROM mutation.after_value THEN RAISE EXCEPTION 'LAUNCH_UNDO_POST_POSITION_CHANGED: % %',mutation.relation_name,mutation.column_name; END IF;
 END LOOP;
 FOREACH c IN ARRAY op.scoped_club_ids LOOP
  SELECT coalesce(sum(amount),0) INTO minted FROM public.ca_mint_ledger WHERE op_id='launch-open:'||p_operation::text||':'||c::text AND asset='chips' AND action='mint';
  IF minted>0 THEN
   FOR pos IN SELECT p.* FROM public.ca_launch_reset_positions p JOIN public.ca_launch_reset_rows r USING(operation_id,relation_name,row_key) WHERE p.operation_id=p_operation AND p.relation_name='club_members' AND p.column_name='chip_balance' AND p.club_id=c AND r.raw_row->>'launch_is_horse'='true' AND r.raw_row->>'launch_profile_status' IS DISTINCT FROM 'deleted' ORDER BY p.row_key::text LOOP
    PERFORM public.fn_ca_launch_reset_wallet_move(p_operation,pos.relation_name,pos.row_key,pos.column_name,0,'undo-opening');
   END LOOP;
   answer:=public.fn_ca_burn('chips','club',c,minted,'Exact Undo Of This Launch Opening Mint','launch-undo-opening:'||p_operation::text||':'||c::text);
   IF answer->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'LAUNCH_UNDO_OPENING_BURN_REFUSED: %',answer; END IF;
  END IF;
  SELECT * INTO original FROM public.ca_mint_ledger WHERE op_id='launch-retire:'||p_operation::text||':'||c::text AND asset='chips' AND action='burn';
  IF FOUND THEN
   v_leg:=gen_random_uuid();
   INSERT INTO public.ca_launch_reset_retirement_reversals VALUES(p_operation,original.id,to_jsonb(original),v_leg,original.amount,c);
   SELECT chip_treasury INTO v_before FROM public.clubs WHERE id=c FOR UPDATE;
   PERFORM set_config('app.ledger_autoskip_clubs','1',true);
   UPDATE public.clubs SET chip_treasury=chip_treasury+original.amount WHERE id=c RETURNING chip_treasury INTO v_after;
   INSERT INTO public.chip_ledger(id,performed_by,from_type,to_type,to_entity_id,amount,category,club_id,description,idempotency_key,correlation_id,pre_to_balance,post_to_balance,metadata)
   VALUES(v_leg,op.performed_by,'chip_retirement','club_treasury',c,original.amount,'reversal',c,'Exact Restoration Of This Launch Retirement Receipt','launch-retirement-reversal:'||p_operation::text||':'||c::text,p_operation,v_before,v_after,jsonb_build_object('original_register_id',original.id));
   PERFORM set_config('app.ledger_autoskip_clubs','',true);
   -- Materialize the existing authoritative register now, so postconditions
   -- read it before deferred commit checks. Those checks still run normally.
   PERFORM public.fn_ca_register_issuance_leg(v_leg);
   IF NOT public.fn_ca_launch_is_retirement_reversal(v_leg) THEN RAISE EXCEPTION 'LAUNCH_UNDO_RETIREMENT_RECEIPT_UNPROVEN'; END IF;
  END IF;
  FOR pos IN SELECT * FROM public.ca_launch_reset_positions WHERE operation_id=p_operation AND club_id=c AND ((relation_name='club_members' AND column_name IN('chip_balance','promo_balance')) OR (relation_name='agents' AND column_name IN('agent_wallet_balance','promo_wallet_balance'))) ORDER BY relation_name,row_key::text,column_name LOOP
   IF pos.balance IS NOT NULL THEN PERFORM public.fn_ca_launch_reset_wallet_move(p_operation,pos.relation_name,pos.row_key,pos.column_name,pos.balance,'undo-retirement'); END IF;
  END LOOP;
 END LOOP;
 SELECT * INTO pool FROM public.bbj_pools WHERE id='f9806a7f-e7a2-47d2-a676-36336e3a5337' FOR UPDATE;
 SELECT balance INTO old_main FROM public.ca_launch_reset_positions WHERE operation_id=p_operation AND relation_name='bbj_pools' AND row_key=jsonb_build_object('id',pool.id) AND column_name='main_balance';
 IF old_main IS NULL THEN RAISE EXCEPTION 'LAUNCH_UNDO_BBJ_PREIMAGE_MISSING'; END IF;
 difference:=pool.main_balance-old_main;
 IF difference<>0 THEN
  PERFORM public.fn_ca_declare_ledger('treasury_transfer','union_bank',pool.union_id,NULL,'launch-bbj-undo:'||p_operation::text,ARRAY['union_wallets']);
  PERFORM set_config('app.ledger_correlation',p_operation::text,true);
  UPDATE public.bbj_pools SET main_balance=old_main WHERE id=pool.id;
  UPDATE public.union_wallets SET chip_balance=chip_balance+difference WHERE union_id=pool.union_id;
  PERFORM set_config('app.ledger_autoskip_union_wallets','',true);
 END IF;
 UPDATE public.agents a SET player_wallet_balance=(r.raw_row->>'player_wallet_balance')::numeric
 FROM public.ca_launch_reset_rows r WHERE r.operation_id=p_operation AND r.relation_name='agents' AND a.id=(r.row_key->>'id')::uuid;
 PERFORM public.fn_ca_launch_cashier_undo(p_operation);
 PERFORM public.fn_ca_launch_incident_undo(p_operation);
 PERFORM public.fn_ca_launch_accounting_undo(p_operation);
 -- Compare every financial pre-position after both owners restored their data.
 FOR pos IN SELECT * FROM public.ca_launch_reset_positions WHERE operation_id=p_operation AND relation_name IN('club_members','agents','clubs','club_wallets','union_wallets','bbj_pools') ORDER BY relation_name,row_key::text,column_name LOOP
  predicate:=CASE WHEN pos.relation_name='club_members' THEN format('club_id=%L::uuid AND user_id=%L::uuid',pos.row_key->>'club_id',pos.row_key->>'user_id') ELSE format('id=%L::uuid',pos.row_key->>'id') END;
  EXECUTE format('SELECT %I FROM public.%I WHERE %s',pos.column_name,pos.relation_name,predicate) INTO got;
  GET DIAGNOSTICS selected_rows=ROW_COUNT;
  IF selected_rows<>1 OR got IS DISTINCT FROM pos.balance THEN RAISE EXCEPTION 'LAUNCH_UNDO_DID_NOT_RESTORE_EXACT_POSITION: % %',pos.relation_name,pos.column_name; END IF;
 END LOOP;
 UPDATE public.ca_launch_reset_operations SET state='undone',undone_at=clock_timestamp() WHERE operation_id=p_operation;
 RETURN jsonb_build_object('operation_id',p_operation,'state','undone','closing_sha256',op.closing_sha256,'journals_retained',true);
END $$;


ALTER FUNCTION public.fn_ca_launch_reset_undo(p_operation uuid, p_expected_closing_sha256 text) OWNER TO postgres;

--
-- TOC entry 6639 (class 1255 OID 159428248)
-- Name: fn_ca_launch_reset_wallet_move(uuid, text, jsonb, text, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_launch_reset_wallet_move(p_operation uuid, p_relation text, p_key jsonb, p_column text, p_target numeric, p_direction text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE pos public.ca_launch_reset_positions%ROWTYPE; op public.ca_launch_reset_operations%ROWTYPE; bank numeric; value numeric; delta numeric; predicate text; key text; leg uuid;
BEGIN
 SELECT * INTO pos FROM public.ca_launch_reset_positions WHERE operation_id=p_operation AND relation_name=p_relation AND row_key=p_key AND column_name=p_column;
 IF NOT FOUND OR p_relation NOT IN('club_members','agents') OR p_column NOT IN('chip_balance','promo_balance','agent_wallet_balance','promo_wallet_balance') OR p_target IS NULL OR p_target<0 OR p_target<>round(p_target,2) THEN RAISE EXCEPTION 'LAUNCH_WALLET_MOVE_NOT_IN_CAPTURE'; END IF;
 SELECT * INTO op FROM public.ca_launch_reset_operations WHERE operation_id=p_operation;
 IF NOT FOUND OR auth.uid() IS DISTINCT FROM op.performed_by
 OR NOT ((p_direction IN('retire','opening') AND op.state='captured') OR (p_direction IN('undo-opening','undo-retirement') AND op.state='executed')) THEN RAISE EXCEPTION 'LAUNCH_WALLET_MOVE_WRONG_OWNER_PHASE'; END IF;
 IF (p_direction IN('retire','undo-opening') AND p_target<>0) OR (p_direction='undo-retirement' AND p_target IS DISTINCT FROM pos.balance) OR (p_direction IN('opening','undo-opening') AND NOT (p_relation='club_members' AND p_column='chip_balance' AND EXISTS(SELECT 1 FROM public.ca_launch_reset_rows r WHERE r.operation_id=p_operation AND r.relation_name=p_relation AND r.row_key=p_key AND r.raw_row->>'launch_is_horse'='true' AND r.raw_row->>'launch_profile_status' IS DISTINCT FROM 'deleted'))) OR (p_direction='opening' AND p_target<>10000) THEN RAISE EXCEPTION 'LAUNCH_WALLET_TARGET_IS_NOT_AUTHORIZED'; END IF;
 SELECT chip_treasury INTO bank FROM public.clubs WHERE id=pos.club_id FOR UPDATE;
 predicate:=CASE WHEN p_relation='club_members'  THEN format('club_id=%L::uuid AND user_id=%L::uuid',p_key->>'club_id',p_key->>'user_id') ELSE format('id=%L::uuid',p_key->>'id') END;
 EXECUTE format('SELECT %I FROM public.%I WHERE %s FOR UPDATE',p_column,p_relation,predicate) INTO value;
 IF value IS NULL THEN RAISE EXCEPTION 'LAUNCH_WALLET_VALUE_IS_NULL'; END IF;
 delta:=p_target-value;
 IF delta=0 THEN RETURN 0; END IF;
 key:='launch-wallet:'||p_operation::text||':'||p_direction||':'||p_relation||':'||p_key::text||':'||p_column;
 INSERT INTO public.ca_launch_reset_wallet_movements VALUES(p_operation,key,p_relation,p_key,p_column,pos.account_type,pos.entity_id,pos.club_id,value,p_target,bank,bank-delta,op.performed_by,p_direction);
 -- Original bank transfer contract: wallet journal writes the single leg;
 -- bank autoledger is stood down only for its matching other balance side.
 PERFORM public.fn_ca_declare_ledger(CASE WHEN delta>0 THEN 'club_bank_send' ELSE 'club_bank_claim' END,'club_treasury',pos.club_id,NULL,key,ARRAY['clubs']);
 PERFORM set_config('app.ledger_correlation',p_operation::text,true);
 PERFORM set_config('app.ledger_autoskip_'||p_relation,'',true);
 EXECUTE format('UPDATE public.%I SET %I=$1 WHERE %s',p_relation,p_column,predicate) USING p_target;
 UPDATE public.clubs SET chip_treasury=chip_treasury-delta WHERE id=pos.club_id;
 SELECT id INTO leg FROM public.chip_ledger WHERE idempotency_key=key;
 IF leg IS NULL OR NOT public.fn_ca_launch_is_internal_transfer(leg) THEN RAISE EXCEPTION 'LAUNCH_WALLET_TRANSFER_HAS_NO_EXACT_LEG'; END IF;
 PERFORM set_config('app.ledger_autoskip_clubs','',true);
 PERFORM public.fn_ca_launch_reset_check_prefix(p_operation,p_direction,key);
 RETURN -delta;
END $_$;


ALTER FUNCTION public.fn_ca_launch_reset_wallet_move(p_operation uuid, p_relation text, p_key jsonb, p_column text, p_target numeric, p_direction text) OWNER TO postgres;

--
-- TOC entry 8224 (class 1255 OID 159428491)
-- Name: fn_ca_launch_tournament_admission_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_launch_tournament_admission_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  IF public.fn_ca_launch_tournament_held(NEW.club_id,NEW.union_id) THEN RAISE EXCEPTION 'OPERATOR_FLOOR_PARKED: tournament creation' USING ERRCODE='55006'; END IF;
 ELSIF (NEW.club_id,NEW.union_id) IS DISTINCT FROM (OLD.club_id,OLD.union_id)
  AND public.fn_ca_launch_tournament_held(NEW.club_id,NEW.union_id) THEN
  RAISE EXCEPTION 'OPERATOR_FLOOR_PARKED: tournament scope admission' USING ERRCODE='55006';
 ELSIF ((OLD.started_at IS NULL AND NEW.started_at IS NOT NULL)
  OR (upper(COALESCE(NEW.status,'')) IN('RUNNING','BREAK','COMPLETING','COMPLETED') AND upper(COALESCE(OLD.status,'')) NOT IN('RUNNING','BREAK','COMPLETING','COMPLETED'))
  OR (COALESCE(OLD.spin_multiplier,0)<=0 AND COALESCE(NEW.spin_multiplier,0)>0))
  AND public.fn_ca_launch_tournament_start_refused(OLD.id) THEN
  RAISE EXCEPTION 'OPERATOR_FLOOR_PARKED: tournament start' USING ERRCODE='55006';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_launch_tournament_admission_guard() OWNER TO postgres;

--
-- TOC entry 5272 (class 1255 OID 159428482)
-- Name: fn_ca_launch_tournament_has_started(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_launch_tournament_has_started(p_tournament uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 RETURN EXISTS(SELECT 1 FROM public.tournaments t WHERE t.id=p_tournament
  AND (t.started_at IS NOT NULL OR upper(COALESCE(t.status,'')) IN('RUNNING','BREAK','COMPLETING','COMPLETED') OR COALESCE(t.spin_multiplier,0)>0))
  OR EXISTS(SELECT 1 FROM public.tournament_launch_receipts r WHERE r.tournament_id=p_tournament AND r.completed_at IS NOT NULL)
  OR EXISTS(SELECT 1 FROM public.spin_draw_receipts r WHERE r.tournament_id=p_tournament)
  OR EXISTS(SELECT 1 FROM public.spin_reserve_ledger r WHERE r.tournament_id=p_tournament AND r.kind='jackpot_draw')
  OR EXISTS(SELECT 1 FROM public.hand_history h WHERE h.tournament_id=p_tournament)
  OR EXISTS(SELECT 1 FROM public.tables t JOIN public.hand_history h ON h.table_id=t.id WHERE t.tournament_id=p_tournament);
END $$;


ALTER FUNCTION public.fn_ca_launch_tournament_has_started(p_tournament uuid) OWNER TO postgres;

--
-- TOC entry 9468 (class 1255 OID 159428477)
-- Name: fn_ca_launch_tournament_held(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_launch_tournament_held(p_club uuid, p_union uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 -- Original global admission lane precedes the operator floor on direct and nested routes.
 PERFORM pg_advisory_xact_lock_shared(530090,1);
 PERFORM pg_advisory_xact_lock_shared(530093);
 -- VOLATILE: read a fresh snapshot after a competing exclusive park committed.
 RETURN EXISTS(SELECT 1 FROM public.ca_operator_floor_hold h JOIN public.ca_launch_operator_scopes m ON m.operation_id=h.operation_id
  WHERE h.mode='park' AND (p_club=ANY(m.club_ids) OR p_union=ANY(m.club_ids)));
END $$;


ALTER FUNCTION public.fn_ca_launch_tournament_held(p_club uuid, p_union uuid) OWNER TO postgres;

--
-- TOC entry 4553 (class 1255 OID 159428487)
-- Name: fn_ca_launch_tournament_start_refused(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_launch_tournament_start_refused(p_tournament uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE t record;
BEGIN
 -- Original global admission lane precedes the operator floor on direct and nested routes.
 PERFORM pg_advisory_xact_lock_shared(530090,1);
 PERFORM pg_advisory_xact_lock_shared(530093);
 SELECT club_id,union_id INTO t FROM public.tournaments WHERE id=p_tournament;
 IF NOT FOUND THEN RETURN false; END IF;
 RETURN public.fn_ca_launch_tournament_held(t.club_id,t.union_id)
  AND public.fn_ca_launch_tournament_has_started(p_tournament) IS NOT TRUE;
END $$;


ALTER FUNCTION public.fn_ca_launch_tournament_start_refused(p_tournament uuid) OWNER TO postgres;

--
-- TOC entry 7878 (class 1255 OID 159428266)
-- Name: fn_ca_launch_velocity_receipt(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_launch_velocity_receipt(p_leg uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
SELECT EXISTS (
 SELECT 1 FROM public.chip_ledger l JOIN public.ca_mint_ledger m ON m.chip_ledger_id=l.id
 JOIN public.ca_launch_reset_operations o ON o.performed_by=l.performed_by
 WHERE l.id=p_leg AND l.status='posted' AND m.asset='chips' AND m.amount=l.amount
 AND m.holder_type='club' AND m.holder_id=ANY(o.scoped_club_ids)
 AND o.state IN('captured','executed','undone')
 AND (
 (m.action='mint' AND l.category='mint' AND l.from_type='issuance_reserve' AND l.to_type='club_treasury'
 AND l.to_entity_id=m.holder_id AND l.idempotency_key='mint:'||m.op_id
 AND public.fn_ca_launch_opening_authorized(m.op_id,'chips','club',m.holder_id,m.amount))
 OR (m.action='burn' AND l.category='burn' AND l.from_type='club_treasury' AND l.from_entity_id=m.holder_id
 AND l.to_type='chip_retirement' AND l.idempotency_key='burn:'||m.op_id
 AND m.op_id='launch-retire:'||o.operation_id::text||':'||m.holder_id::text
 AND m.amount=(SELECT sum(p.balance) FROM public.ca_launch_reset_positions p WHERE p.operation_id=o.operation_id AND p.club_id=m.holder_id
 AND ((p.relation_name='club_members' AND p.column_name IN('chip_balance','promo_balance')) OR (p.relation_name='agents' AND p.column_name IN('agent_wallet_balance','promo_wallet_balance')))))
 OR (m.action='burn' AND l.category='burn' AND l.from_type='club_treasury' AND l.from_entity_id=m.holder_id
 AND l.to_type='chip_retirement' AND l.idempotency_key='burn:'||m.op_id
 AND m.op_id='launch-undo-opening:'||o.operation_id::text||':'||m.holder_id::text
 AND o.state IN('executed','undone') AND EXISTS(SELECT 1 FROM public.ca_launch_reset_opening_authorizations a
 WHERE a.operation_id=o.operation_id AND a.club_id=m.holder_id AND a.amount=m.amount AND a.closing_sha256=o.closing_sha256))
 OR public.fn_ca_launch_is_retirement_reversal(l.id)
 ));
$$;


ALTER FUNCTION public.fn_ca_launch_velocity_receipt(p_leg uuid) OWNER TO postgres;

--
-- TOC entry 7730 (class 1255 OID 23878185)
-- Name: fn_ca_ledger_day_manifest(date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_day_manifest(p_day date DEFAULT (CURRENT_DATE - 1), p_restate_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE v_count bigint; v_net numeric; v_first bigint; v_last bigint; v_sha text; v_prior text; v_prior_rows bigint;
BEGIN
  /* One index range over idx_chip_ledger_created_at: the cost is this day's
     legs, not the journal's. A day is a UTC day (SET timezone above). */
  SELECT count(*), COALESCE(sum(amount), 0), min(chain_seq), max(chain_seq),
         encode(extensions.digest(
           COALESCE(string_agg(
             id::text || '|' || amount::text || '|' || from_type || ':' || COALESCE(from_entity_id::text,'') ||
             '>' || to_type || ':' || COALESCE(to_entity_id::text,'') || '|' || category || '|' ||
             extract(epoch from created_at)::text || '|' || COALESCE(row_hash,''),
             E'\n' ORDER BY created_at, id), ''), 'sha256'), 'hex')
    INTO v_count, v_net, v_first, v_last, v_sha
    FROM public.chip_ledger
   WHERE created_at >= p_day AND created_at < p_day + 1;

  SELECT sha256, row_count INTO v_prior, v_prior_rows
    FROM public.ca_ledger_day_manifests WHERE day = p_day;

  IF v_prior IS NULL THEN
    IF v_count = 0 THEN
      /* Nothing to attest and nothing attested: not a manifest, not an error. */
      RETURN jsonb_build_object('day', p_day, 'rows', 0, 'attested', false, 'tampered', false);
    END IF;
    INSERT INTO public.ca_ledger_day_manifests
      (day, row_count, first_seq, last_seq, net_amount, sha256, last_checked_at)
    VALUES (p_day, v_count, v_first, v_last, v_net, v_sha, now())
    ON CONFLICT (day) DO NOTHING;
    RETURN jsonb_build_object('day', p_day, 'rows', v_count, 'net', v_net,
      'first_seq', v_first, 'last_seq', v_last, 'sha256', v_sha, 'tampered', false, 'restated', false);
  END IF;

  IF v_prior = v_sha THEN
    /* Read and agreed: that is a verification, so say when it happened. */
    UPDATE public.ca_ledger_day_manifests SET last_checked_at = now() WHERE day = p_day;
    RETURN jsonb_build_object('day', p_day, 'rows', v_count, 'net', v_net,
      'first_seq', v_first, 'last_seq', v_last, 'sha256', v_sha, 'tampered', false, 'restated', false);
  END IF;

  /* The stored attestation and the journal disagree. */
  IF p_restate_reason IS NULL THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_ledger_day_manifest', 'unauthorized_adjustment', 'critical',
      'manifest-mismatch:' || p_day::text,
      0, NULL, NULL, 'ledger', 'ca_ledger_day_manifests',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'the recomputed ledger manifest for ' || p_day || ' no longer matches the stored one - historical rows changed',
      false, jsonb_build_object('day', p_day, 'stored', v_prior, 'recomputed', v_sha,
                                'stored_rows', v_prior_rows, 'actual_rows', v_count));
    RETURN jsonb_build_object('day', p_day, 'tampered', true, 'stored', v_prior, 'recomputed', v_sha,
                              'stored_rows', v_prior_rows, 'actual_rows', v_count);
  END IF;

  IF v_count = 0 THEN
    /* A day that was attested cannot become a day that never happened. The
       statement that would empty it is refused whole. */
    RAISE EXCEPTION
      'refusing to restate % to zero rows (it attested % rows): an attested day cannot be emptied. Reason offered: %',
      p_day, v_prior_rows, p_restate_reason
      USING ERRCODE = 'P0403';
  END IF;

  /* Open the guard for exactly this update, in this transaction only. The
     guard writes the restatement row itself, old value kept. */
  PERFORM set_config('app.manifest_restatement', p_restate_reason, true);
  UPDATE public.ca_ledger_day_manifests
     SET row_count = v_count, first_seq = v_first, last_seq = v_last,
         net_amount = v_net, sha256 = v_sha, last_checked_at = now()
   WHERE day = p_day;
  PERFORM set_config('app.manifest_restatement', '', true);

  RETURN jsonb_build_object('day', p_day, 'rows', v_count, 'net', v_net,
    'first_seq', v_first, 'last_seq', v_last, 'sha256', v_sha, 'tampered', false,
    'restated', true, 'old_sha256', v_prior, 'old_rows', v_prior_rows, 'reason', p_restate_reason);
END $$;


ALTER FUNCTION public.fn_ca_ledger_day_manifest(p_day date, p_restate_reason text) OWNER TO postgres;

--
-- TOC entry 7017 (class 1255 OID 23714401)
-- Name: fn_ca_ledger_day_manifest_backfill(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_day_manifest_backfill(p_since date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
  r      record;
  v_done int   := 0;
  v_days jsonb := '[]'::jsonb;
  v_res  jsonb;
BEGIN
  FOR r IN
    SELECT d.day
      FROM public.fn_ca_ledger_finished_days() d(day)
     WHERE (p_since IS NULL OR d.day >= p_since)
       AND NOT EXISTS (SELECT 1 FROM public.ca_ledger_day_manifests m WHERE m.day = d.day)
     ORDER BY d.day
  LOOP
    v_res  := public.fn_ca_ledger_day_manifest(r.day);
    v_done := v_done + 1;
    v_days := v_days || jsonb_build_object('day', r.day, 'rows', v_res->'rows');
  END LOOP;

  RETURN jsonb_build_object('attested', v_done, 'days', v_days,
                            'since', COALESCE(p_since::text, 'the whole journal'));
END $$;


ALTER FUNCTION public.fn_ca_ledger_day_manifest_backfill(p_since date) OWNER TO postgres;

--
-- TOC entry 45958 (class 0 OID 0)
-- Dependencies: 7017
-- Name: FUNCTION fn_ca_ledger_day_manifest_backfill(p_since date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_ledger_day_manifest_backfill(p_since date) IS 'Attests every finished day the journal has that carries no manifest, by calling fn_ca_ledger_day_manifest for each. Exists because that writer only ever examines CURRENT_DATE - 1, so 27 days of real money movement (2026-03-19..2026-08-29) were outside every guard until 2026-09-07. Composes no manifest of its own: there are exactly two places that know how to hash a day, and this is not one of them.';


--
-- TOC entry 5525 (class 1255 OID 23878197)
-- Name: fn_ca_ledger_day_manifest_verify_all(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_day_manifest_verify_all(p_budget_ms integer DEFAULT 60000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
  r            record;
  v_checked    int   := 0;
  v_drifted    int   := 0;
  v_unattested int   := 0;
  v_deferred   int   := 0;
  v_days       jsonb := '[]'::jsonb;
  v_missing    jsonb := '[]'::jsonb;
  v_t0         timestamptz := clock_timestamp();
  v_sha        text;
  v_count      bigint;
  v_oldest_age numeric;
  v_never      int;
BEGIN
  /* COVERAGE, every run. Which finished days have legs, and which of those
     carry no manifest. Loose index scan: proportional to days, not legs. */
  FOR r IN
    SELECT d.day
      FROM public.fn_ca_ledger_finished_days() d(day)
     WHERE NOT EXISTS (SELECT 1 FROM public.ca_ledger_day_manifests m WHERE m.day = d.day)
     ORDER BY d.day
  LOOP
    v_unattested := v_unattested + 1;
    v_missing := v_missing || jsonb_build_object('day', r.day);
  END LOOP;

  /* THE ROTATION. Least recently re-read first (never re-read first of all),
     until the budget is spent. Every manifest is a candidate, including one
     whose day has lost every row - that recomputes to the empty digest and is
     reported as drift with rows_present=false, the same failure #3463 named. */
  FOR r IN
    SELECT m.day, m.row_count AS stored_rows, m.sha256 AS stored_sha
      FROM public.ca_ledger_day_manifests m
     ORDER BY m.last_checked_at ASC NULLS FIRST, m.day ASC
  LOOP
    IF extract(epoch from (clock_timestamp() - v_t0)) * 1000 > p_budget_ms THEN
      v_deferred := v_deferred + 1;
      CONTINUE;
    END IF;

    /* The same expression fn_ca_ledger_day_manifest uses. If that one changes,
       this must change with it, or the pair will disagree about a journal
       neither has touched. */
    SELECT count(*),
           encode(extensions.digest(
             COALESCE(string_agg(
               id::text || '|' || amount::text || '|' || from_type || ':' || COALESCE(from_entity_id::text,'') ||
               '>' || to_type || ':' || COALESCE(to_entity_id::text,'') || '|' || category || '|' ||
               extract(epoch from created_at)::text || '|' || COALESCE(row_hash,''),
               E'\n' ORDER BY created_at, id), ''), 'sha256'), 'hex')
      INTO v_count, v_sha
      FROM public.chip_ledger
     WHERE created_at >= r.day AND created_at < r.day + 1;

    v_checked := v_checked + 1;
    UPDATE public.ca_ledger_day_manifests SET last_checked_at = now() WHERE day = r.day;

    IF v_sha IS DISTINCT FROM r.stored_sha THEN
      v_drifted := v_drifted + 1;
      v_days := v_days || jsonb_build_object(
        'day', r.day, 'stored_rows', r.stored_rows, 'actual_rows', v_count,
        'stored_sha', r.stored_sha, 'recomputed_sha', v_sha,
        'rows_present', v_count > 0);

      PERFORM public.fn_ca_raise_drift_incident(
        'fn_ca_ledger_day_manifest_verify_all', 'unauthorized_adjustment', 'critical',
        'manifest-mismatch:' || r.day::text,
        0, NULL, NULL, 'ledger', 'ca_ledger_day_manifests',
        NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
        'the ledger manifest for ' || r.day || ' no longer matches the journal: '
          || r.stored_rows || ' rows attested, ' || v_count || ' present. Sanctioned maintenance '
          || 'restates a manifest in its own transaction (zz_ca_attested_day_is_restated), so a mismatch '
          || 'here means the day changed some other way. Read ca_ledger_mutation_log for it first.',
        false,
        jsonb_build_object('day', r.day, 'stored_rows', r.stored_rows, 'actual_rows', v_count,
                           'stored', r.stored_sha, 'recomputed', v_sha));
    END IF;
  END LOOP;

  IF v_unattested > 0 THEN
    /* Not folded into `drifted`. They are different facts and a reader has to
       be able to tell them apart: drifted means a day changed, unattested
       means a day was never looked at. */
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_ledger_day_manifest_verify_all', 'unauthorized_adjustment', 'critical',
      'manifest-unattested-days',
      0, NULL, NULL, 'ledger', 'ca_ledger_day_manifests',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      v_unattested || ' day(s) of chip_ledger carry no manifest at all, so nothing is '
        || 'verifying them. fn_ca_ledger_day_manifest_backfill() attests every finished day '
        || 'the journal has, and the daily job calls it, so seeing this means that call did not '
        || 'run or could not write.',
      false, jsonb_build_object('unattested', v_unattested, 'days', v_missing));
  END IF;

  /* HOW WIDE THE MESH IS. The oldest re-read, in days, over every manifest -
     a manifest never re-read counts from the moment it was written. */
  SELECT max(extract(epoch from (now() - COALESCE(m.last_checked_at, m.created_at))) / 86400.0),
         count(*) FILTER (WHERE m.last_checked_at IS NULL)
    INTO v_oldest_age, v_never
    FROM public.ca_ledger_day_manifests m;

  IF COALESCE(v_oldest_age, 0) > 30 THEN
    /* Measured basis, 2026-09-07: the whole journal (35 days, 2.18M legs)
       re-reads inside the 60 s budget in about two nights. Thirty days is
       fifteen-fold headroom. When this fires the rotation can no longer cover
       the journal in a month, and the decision - a bigger budget or a longer
       rotation - is Dan's, made on this number. Warning, not critical: nothing
       has drifted, something has merely not been re-read lately. */
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_ledger_day_manifest_verify_all', 'unauthorized_adjustment', 'warning',
      'manifest-rotation-stale',
      0, NULL, NULL, 'ledger', 'ca_ledger_day_manifests',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      'the oldest ledger-day manifest was last re-read ' || round(v_oldest_age, 1)
        || ' days ago: the nightly budget of ' || p_budget_ms || ' ms no longer re-reads the whole '
        || 'journal inside 30 days. Raise the budget (cron.job ca-ledger-day-manifest) or accept a '
        || 'longer rotation; either is a decision, not a repair.',
      true, jsonb_build_object('oldest_check_age_days', round(v_oldest_age, 2),
                               'never_checked', v_never, 'budget_ms', p_budget_ms));
  END IF;

  RETURN jsonb_build_object(
    'checked', v_checked, 'drifted', v_drifted, 'days', v_days,
    /* The coverage travels WITH the answer. "0 drifted" on its own was the
       defect #3463 was written for; "checked N" on its own is the one this
       migration was written for. */
    'unattested', v_unattested, 'unattested_days', v_missing,
    'deferred', v_deferred,
    'oldest_check_age_days', round(COALESCE(v_oldest_age, 0), 2),
    'never_checked', v_never,
    'budget_ms', p_budget_ms,
    'ms', round(extract(epoch from (clock_timestamp() - v_t0)) * 1000));
END $$;


ALTER FUNCTION public.fn_ca_ledger_day_manifest_verify_all(p_budget_ms integer) OWNER TO postgres;

--
-- TOC entry 7635 (class 1255 OID 86549029)
-- Name: fn_ca_ledger_declaration_restore(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_declaration_restore(p_saved jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  r record;
BEGIN
  FOR r IN SELECT key, value FROM jsonb_each_text(COALESCE(p_saved, '{}'::jsonb)) LOOP
    IF r.key !~ '^app\.ledger_(category|counterparty|counterparty_entity|counterparty_label|autoskip_[a-z_]+)$' THEN
      RAISE EXCEPTION 'fn_ca_ledger_declaration_restore: % is not a ledger declaration setting', r.key;
    END IF;
    PERFORM set_config(r.key, COALESCE(r.value, ''), true);
  END LOOP;
END $_$;


ALTER FUNCTION public.fn_ca_ledger_declaration_restore(p_saved jsonb) OWNER TO postgres;

--
-- TOC entry 4221 (class 1255 OID 86549017)
-- Name: fn_ca_ledger_declaration_save(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_declaration_save(p_autoskip_tables text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  v jsonb;
  t text;
BEGIN
  v := jsonb_build_object(
    'app.ledger_category',            COALESCE(current_setting('app.ledger_category', true), ''),
    'app.ledger_counterparty',        COALESCE(current_setting('app.ledger_counterparty', true), ''),
    'app.ledger_counterparty_entity', COALESCE(current_setting('app.ledger_counterparty_entity', true), ''),
    'app.ledger_counterparty_label',  COALESCE(current_setting('app.ledger_counterparty_label', true), ''));
  IF p_autoskip_tables IS NOT NULL THEN
    FOREACH t IN ARRAY p_autoskip_tables LOOP
      IF t !~ '^[a-z_]+$' THEN
        RAISE EXCEPTION 'fn_ca_ledger_declaration_save: bad autoskip table name %', t;
      END IF;
      v := v || jsonb_build_object('app.ledger_autoskip_' || t,
                                   COALESCE(current_setting('app.ledger_autoskip_' || t, true), ''));
    END LOOP;
  END IF;
  RETURN v;
END $_$;


ALTER FUNCTION public.fn_ca_ledger_declaration_save(p_autoskip_tables text[]) OWNER TO postgres;

--
-- TOC entry 4924 (class 1255 OID 23878196)
-- Name: fn_ca_ledger_finished_days(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_finished_days() RETURNS SETOF date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
  WITH RECURSIVE d AS (
    SELECT (SELECT min(created_at) FROM public.chip_ledger)::date AS day
    UNION ALL
    SELECT (SELECT min(created_at) FROM public.chip_ledger
             WHERE created_at >= (d.day + 1)::timestamptz)::date
      FROM d WHERE d.day IS NOT NULL
  )
  SELECT day FROM d WHERE day IS NOT NULL AND day < CURRENT_DATE ORDER BY day
$$;


ALTER FUNCTION public.fn_ca_ledger_finished_days() OWNER TO postgres;

--
-- TOC entry 9068 (class 1255 OID 86560253)
-- Name: fn_ca_ledger_invariant_refusal_census(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_invariant_refusal_census() RETURNS TABLE(counted bigint, recorded bigint, unrecorded bigint, unraised bigint, last_refused_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  /* counted: refusals the counter saw (durable through every rollback).
     recorded: refusals whose own record arrived. unrecorded = counted -
     recorded: refusals known to have happened whose details never arrived.
     unraised: records with no incident yet. */
  WITH c AS (
    SELECT CASE WHEN s.is_called THEN s.last_value ELSE 0 END AS n
      FROM public.ca_ledger_invariant_refusal_counter s
  ), r AS (
    SELECT count(*) FILTER (WHERE kind <> 'unrecorded' AND counter_no IS NOT NULL) AS recorded,
           count(*) FILTER (WHERE kind <> 'unrecorded' AND incident_id IS NULL) AS unraised,
           max(refused_at) AS last_refused_at
      FROM public.ca_ledger_invariant_refusals
  )
  SELECT c.n, r.recorded, greatest(c.n - r.recorded, 0), r.unraised, r.last_refused_at
    FROM c, r;
$$;


ALTER FUNCTION public.fn_ca_ledger_invariant_refusal_census() OWNER TO postgres;

--
-- TOC entry 8147 (class 1255 OID 86560324)
-- Name: fn_ca_ledger_invariant_refusal_watch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_invariant_refusal_watch() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  st record;
  c record;
  v_n integer := 0;
  v_id bigint;
  g bigint;
BEGIN
  SELECT * INTO st FROM public.ca_ledger_invariant_refusal_watch_state WHERE id FOR UPDATE;
  SELECT * INTO c FROM public.fn_ca_ledger_invariant_refusal_census();

  /* A number counted before the PREVIOUS watch has had a whole interval for
     its record to arrive. One that still has none is a refusal whose details
     were lost: it becomes an explicit 'unrecorded' row, never a silent zero. */
  FOR g IN SELECT s FROM generate_series(st.checked_through + 1, st.counted_at_last_watch) s
            WHERE NOT EXISTS (SELECT 1 FROM public.ca_ledger_invariant_refusals x WHERE x.counter_no = s)
  LOOP
    v_id := NULL;
    INSERT INTO public.ca_ledger_invariant_refusals (counter_no, kind, message)
    VALUES (g, 'unrecorded',
            'the ledger invariant refused a transaction (counter ' || g || ') and its record never arrived; search the Postgres log for LEDGER_REFUSAL_UNRECORDED counter=' || g)
    ON CONFLICT (counter_no) DO NOTHING
    RETURNING id INTO v_id;
    IF v_id IS NOT NULL THEN
      PERFORM public.fn_ca_ledger_refusal_raise(v_id);
      v_n := v_n + 1;
    END IF;
  END LOOP;

  /* A record whose incident did not arrive (the separate remote statement
     failed) is raised here. */
  FOR v_id IN SELECT x.id FROM public.ca_ledger_invariant_refusals x
               WHERE x.incident_id IS NULL AND x.recorded_at < now() - interval '2 minutes'
               ORDER BY x.id LIMIT 200
  LOOP
    PERFORM public.fn_ca_ledger_refusal_raise(v_id);
    v_n := v_n + 1;
  END LOOP;

  UPDATE public.ca_ledger_invariant_refusal_watch_state
     SET checked_through = greatest(st.checked_through, st.counted_at_last_watch),
         counted_at_last_watch = c.counted,
         watched_at = now()
   WHERE id;
  RETURN v_n;
END;
$$;


ALTER FUNCTION public.fn_ca_ledger_invariant_refusal_watch() OWNER TO postgres;

--
-- TOC entry 5168 (class 1255 OID 183809212)
-- Name: fn_ca_ledger_leg_club(uuid, numeric, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_leg_club(p_user uuid, p_amount numeric, p_type text, p_at timestamp with time zone, p_table uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_club uuid;
BEGIN
  IF p_user IS NULL OR p_amount IS NULL OR p_at IS NULL THEN RETURN NULL; END IF;
  IF p_type = 'debit' THEN
    SELECT cl.club_id INTO v_club FROM public.chip_ledger cl
     WHERE cl.from_entity_id = p_user AND cl.created_at = p_at
       AND cl.from_type = 'player_wallet' AND cl.amount = p_amount AND cl.club_id IS NOT NULL
       AND (p_table IS NULL OR cl.table_id IS NULL OR cl.table_id = p_table)
     ORDER BY (cl.table_id IS NOT DISTINCT FROM p_table) DESC LIMIT 1;
  ELSIF p_type = 'credit' THEN
    SELECT cl.club_id INTO v_club FROM public.chip_ledger cl
     WHERE cl.to_entity_id = p_user AND cl.created_at = p_at
       AND cl.to_type = 'player_wallet' AND cl.amount = p_amount AND cl.club_id IS NOT NULL
       AND (p_table IS NULL OR cl.table_id IS NULL OR cl.table_id = p_table)
     ORDER BY (cl.table_id IS NOT DISTINCT FROM p_table) DESC LIMIT 1;
  END IF;
  RETURN v_club;
END;
$$;


ALTER FUNCTION public.fn_ca_ledger_leg_club(p_user uuid, p_amount numeric, p_type text, p_at timestamp with time zone, p_table uuid) OWNER TO postgres;

--
-- TOC entry 3884 (class 1255 OID 86560252)
-- Name: fn_ca_ledger_refusal_file(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_refusal_file(p_refusal jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_id bigint;
  v_no bigint := NULLIF(p_refusal ->> 'counter_no', '')::bigint;
BEGIN
  /* Runs on the recorder's own connection and commits on its own: this row
     outlives the refused transaction. A placeholder the watch wrote for the
     same counter number (kind unrecorded) is replaced by the late record. */
  INSERT INTO public.ca_ledger_invariant_refusals AS x
    (counter_no, kind, refused_at, txid, account_key, store, balance_delta,
     ledger_net, mode, rpc, db_role, session_role, application_name, jwt_role,
     jwt_sub, first_writer, query, backend_pid, message, moved)
  VALUES
    (v_no,
     p_refusal ->> 'kind',
     NULLIF(p_refusal ->> 'refused_at', '')::timestamptz,
     p_refusal ->> 'txid',
     p_refusal ->> 'account_key',
     p_refusal ->> 'store',
     NULLIF(p_refusal ->> 'balance_delta', '')::numeric,
     NULLIF(p_refusal ->> 'ledger_net', '')::numeric,
     p_refusal ->> 'mode',
     left(p_refusal ->> 'rpc', 200),
     p_refusal ->> 'db_role',
     p_refusal ->> 'session_role',
     p_refusal ->> 'application_name',
     p_refusal ->> 'jwt_role',
     p_refusal ->> 'jwt_sub',
     left(p_refusal ->> 'first_writer', 1000),
     left(p_refusal ->> 'query', 2000),
     NULLIF(p_refusal ->> 'backend_pid', '')::integer,
     left(p_refusal ->> 'message', 2000),
     left(p_refusal ->> 'moved', 2000))
  ON CONFLICT (counter_no) DO UPDATE
    SET kind = EXCLUDED.kind, refused_at = EXCLUDED.refused_at, recorded_at = now(),
        txid = EXCLUDED.txid, account_key = EXCLUDED.account_key, store = EXCLUDED.store,
        balance_delta = EXCLUDED.balance_delta, ledger_net = EXCLUDED.ledger_net,
        mode = EXCLUDED.mode, rpc = EXCLUDED.rpc, db_role = EXCLUDED.db_role,
        session_role = EXCLUDED.session_role, application_name = EXCLUDED.application_name,
        jwt_role = EXCLUDED.jwt_role, jwt_sub = EXCLUDED.jwt_sub,
        first_writer = EXCLUDED.first_writer, query = EXCLUDED.query,
        backend_pid = EXCLUDED.backend_pid, message = EXCLUDED.message,
        moved = EXCLUDED.moved, incident_id = NULL
    WHERE x.kind = 'unrecorded'
  RETURNING x.id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM public.ca_ledger_invariant_refusals WHERE counter_no = v_no;
  END IF;
  RETURN v_id;
END;
$$;


ALTER FUNCTION public.fn_ca_ledger_refusal_file(p_refusal jsonb) OWNER TO postgres;

--
-- TOC entry 4179 (class 1255 OID 86560258)
-- Name: fn_ca_ledger_refusal_raise(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_refusal_raise(p_id bigint) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  r public.ca_ledger_invariant_refusals%ROWTYPE;
  c record;
  v_incident uuid;
  v_key text;
BEGIN
  SELECT * INTO r FROM public.ca_ledger_invariant_refusals WHERE id = p_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  SELECT * INTO c FROM public.fn_ca_ledger_invariant_refusal_census();

  /* ONE INCIDENT PER BURST. A loop refusing the same account through the
     same function folds into the open incident (occurrences + 1); every
     refusal is still its own row in ca_ledger_invariant_refusals. */
  v_key := CASE WHEN r.kind = 'unrecorded'
                THEN 'ledger-invariant-refusal-unrecorded'
                ELSE 'ledger-invariant-refused:' || r.kind || ':' || COALESCE(r.rpc, 'unknown') || ':' || COALESCE(r.account_key, 'unknown')
           END;

  v_incident := public.fn_ca_raise_drift_incident(
    p_source          := 'ledger_invariant.refused',
    p_classification  := 'ledger_imbalance',
    p_severity        := 'critical',
    p_dedupe_key      := v_key,
    p_discrepancy     := round(COALESCE(r.balance_delta, 0) - COALESCE(r.ledger_net, 0), 2),
    p_expected        := r.ledger_net,
    p_actual          := r.balance_delta,
    p_layer           := 'ledger',
    p_entity_type     := 'chip_store',
    p_suspected_cause := CASE WHEN r.kind = 'unrecorded'
      THEN 'the ledger invariant refused a transaction and its record never arrived (counter ' || r.counter_no
           || '); the refusal is real, its details are only in the Postgres log under LEDGER_REFUSAL_UNRECORDED counter=' || r.counter_no
      ELSE left(COALESCE(r.message, r.kind), 400) || ' via ' || COALESCE(r.rpc, 'unknown')
           || ' (role ' || COALESCE(r.db_role, '?') || ', application ' || COALESCE(r.application_name, '?') || ')'
      END,
    p_metadata        := jsonb_build_object(
      'refusal_id', r.id, 'counter_no', r.counter_no, 'kind', r.kind,
      'function', r.rpc, 'account_key', r.account_key, 'store', r.store,
      'balance_delta', r.balance_delta, 'ledger_net', r.ledger_net, 'moved', r.moved,
      'db_role', r.db_role, 'application_name', r.application_name,
      'jwt_role', r.jwt_role, 'jwt_sub', r.jwt_sub, 'txid', r.txid,
      'refused_at', r.refused_at, 'first_writer', left(r.first_writer, 300),
      'census', jsonb_build_object('counted', c.counted, 'recorded', c.recorded,
                                   'unrecorded', c.unrecorded, 'unraised', c.unraised)));

  UPDATE public.ca_ledger_invariant_refusals SET incident_id = v_incident WHERE id = p_id;
  RETURN v_incident;
END;
$$;


ALTER FUNCTION public.fn_ca_ledger_refusal_raise(p_id bigint) OWNER TO postgres;

--
-- TOC entry 9444 (class 1255 OID 86560301)
-- Name: fn_ca_ledger_refusal_record(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_refusal_record(p_refusal jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_no      bigint;
  v_conn    text := 'ca_ledger_refusal_' || pg_backend_pid();
  v_info    text;
  v_id      bigint;
  v_claims  jsonb;
  v_path    text;
  v_q       text;
  v_src     text;
  v_payload jsonb;
BEGIN
  /* 1. COUNT IT FIRST. nextval survives the rollback that follows, so the
        refusal is counted even if nothing below works. */
  BEGIN
    v_no := nextval('public.ca_ledger_invariant_refusal_counter');
  EXCEPTION WHEN OTHERS THEN
    v_no := NULL;
  END;

  /* 2. Say who refused it. Inside SECURITY DEFINER current_user is the owner,
        so the caller is read from the role setting (PostgREST's SET ROLE),
        the session user, the JWT claims and the request path. */
  BEGIN
    v_path := NULLIF(current_setting('request.path', true), '');
    v_q := left(current_query(), 2000);
    /* The check is deferred to COMMIT, so for an explicit transaction the
       current statement is the COMMIT itself; the statement that first wrote
       the money (kept by the tally) then names the caller instead. */
    v_src := CASE WHEN v_q ~* '^\s*(commit|end)\y'
                  THEN COALESCE(NULLIF(p_refusal ->> 'first_writer', ''), v_q)
                  ELSE v_q END;
    BEGIN
      v_claims := NULLIF(current_setting('request.jwt.claims', true), '')::jsonb;
    EXCEPTION WHEN OTHERS THEN
      v_claims := NULL;
    END;
    v_payload := COALESCE(p_refusal, '{}'::jsonb) || jsonb_build_object(
      'counter_no',       v_no,
      'refused_at',       clock_timestamp(),
      'txid',             pg_current_xact_id()::text,
      'rpc',              COALESCE(
                            substring(v_path from '^/rpc/([A-Za-z0-9_]+)'),
                            CASE WHEN v_path IS NOT NULL
                                 THEN COALESCE(NULLIF(current_setting('request.method', true), ''), '?') || ' ' || v_path END,
                            substring(v_src from '(?i)(?:select|perform|call)\s+(?:\*\s+from\s+)?(?:"?[a-z_][a-z0-9_]*"?\.)?"?([a-z_][a-z0-9_]*)"?\s*\('),
                            (SELECT lower(regexp_replace(m[1], '\s+', ' ', 'g')) || ' ' || m[2]
                               FROM regexp_match(v_src, '(?i)^\s*(update|insert\s+into|delete\s+from)\s+([a-z0-9_."]+)') m),
                            'unknown'),
      'db_role',          COALESCE(NULLIF(current_setting('role', true), 'none'), session_user::text),
      'session_role',     session_user::text,
      'application_name', current_setting('application_name', true),
      'jwt_role',         v_claims ->> 'role',
      'jwt_sub',          v_claims ->> 'sub',
      'query',            v_q,
      'backend_pid',      pg_backend_pid());
  EXCEPTION WHEN OTHERS THEN
    v_payload := COALESCE(p_refusal, '{}'::jsonb) || jsonb_build_object('counter_no', v_no, 'refused_at', clock_timestamp());
  END;

  /* 3. WRITE IT WHERE THE ROLLBACK CANNOT REACH: the recorder's own
        connection, which commits each statement on its own. */
  BEGIN
    SELECT s.decrypted_secret INTO v_info
      FROM vault.decrypted_secrets s
     WHERE s.name = 'ca_ledger_refusal_recorder_conninfo'
     LIMIT 1;
    IF v_info IS NULL THEN
      RAISE WARNING 'LEDGER_REFUSAL_UNRECORDED counter=% reason=no recorder connection string in vault', v_no;
      RETURN false;
    END IF;

    IF v_conn = ANY (COALESCE(extensions.dblink_get_connections(), ARRAY[]::text[])) THEN
      PERFORM extensions.dblink_disconnect(v_conn);
    END IF;
    PERFORM extensions.dblink_connect(v_conn, v_info);

    SELECT t.id INTO v_id
      FROM extensions.dblink(v_conn, format('SELECT public.fn_ca_ledger_refusal_file(%L::jsonb)', v_payload::text)) AS t(id bigint);

    /* 4. The incident, in its own remote statement, after the record has
          committed: a slow board can cost the incident, never the record. */
    BEGIN
      PERFORM 1 FROM extensions.dblink(v_conn, format('SELECT public.fn_ca_ledger_refusal_raise(%s)', v_id)) AS t(incident uuid);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'LEDGER_REFUSAL_RECORDED_NOT_RAISED refusal=% counter=% reason=%', v_id, v_no, SQLERRM;
    END;

    PERFORM extensions.dblink_disconnect(v_conn);
    RETURN true;
  EXCEPTION WHEN OTHERS THEN
    BEGIN
      IF v_conn = ANY (COALESCE(extensions.dblink_get_connections(), ARRAY[]::text[])) THEN
        PERFORM extensions.dblink_disconnect(v_conn);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
    RAISE WARNING 'LEDGER_REFUSAL_UNRECORDED counter=% reason=%', v_no, SQLERRM;
    RETURN false;
  END;
END;
$$;


ALTER FUNCTION public.fn_ca_ledger_refusal_record(p_refusal jsonb) OWNER TO postgres;

--
-- TOC entry 4485 (class 1255 OID 21877736)
-- Name: fn_ca_ledger_replay(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_replay(p_limit integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '540s'
    AS $$
  DECLARE
    v_now timestamptz := clock_timestamp();
    v_read_at timestamptz;
    /* v4 (2026-09-10): THE JOURNAL WINDOW IS A SNAPSHOT, NOT A CLOCK. A leg
       whose transaction straddled the previous reading (created_at before the
       reading, committed after it) fell through the created_at window for
       ever and read as drift (-100 / +100 on 2026-09-10). Every reading now
       records the snapshot it read under; the next reading counts a leg iff it
       was not visible in that snapshot. Every account rebaselines once. */
    v_basis text := 'one-snapshot-v4';
    r record; w record;
    v_entities uuid[];
    v_checked int := 0; v_baselines int := 0; v_rebased int := 0;
    v_bad int := 0; v_unkeyable bigint := 0;
    v_this numeric; v_two numeric; v_cum numeric;
    v_worst numeric := 0; v_worst_key text; v_sample jsonb := '[]'::jsonb;
  BEGIN
    IF NOT (current_user IN ('postgres', 'supabase_admin') OR COALESCE(auth.role(), '') = 'service_role') THEN
      RAISE EXCEPTION 'fn_ca_ledger_replay is service only' USING ERRCODE = '42501';
    END IF;

    DROP TABLE IF EXISTS zz_replay_window;
    DROP TABLE IF EXISTS zz_replay_touched;
    DROP TABLE IF EXISTS zz_replay_prev;
    DROP TABLE IF EXISTS zz_replay_net;
    DROP TABLE IF EXISTS zz_replay_read;

    CREATE TEMP TABLE zz_replay_window ON COMMIT DROP AS
      SELECT a.* FROM public.fn_ca_leg_accounts(v_now - interval '26 hours', v_now) a;

    SELECT COALESCE(sum(zw.unkeyable), 0) INTO v_unkeyable FROM zz_replay_window zw WHERE zw.account_type = 'unkeyable';

    CREATE TEMP TABLE zz_replay_touched ON COMMIT DROP AS
      SELECT zw.* FROM zz_replay_window zw
       WHERE zw.account_type <> 'unkeyable'
       ORDER BY abs(zw.net) DESC
       LIMIT GREATEST(COALESCE(p_limit, 5000), 1);

    CREATE TEMP TABLE zz_replay_prev ON COMMIT DROP AS
      SELECT t.account_key, s.balance AS prev_balance, s.taken_at AS prev_at,
             s.unexplained AS prev_unexplained, s.cum_unexplained AS prev_cum,
             s.basis_version AS prev_basis, s.read_snapshot AS prev_snapshot
        FROM zz_replay_touched t
        LEFT JOIN LATERAL (
          SELECT x.balance, x.taken_at, x.unexplained, x.cum_unexplained, x.basis_version, x.read_snapshot
            FROM public.ca_account_snapshots x
           WHERE x.account_key = t.account_key ORDER BY x.taken_at DESC LIMIT 1
        ) s ON true;

    /* THE BALANCE, THE JOURNAL AND THE SNAPSHOT ARE READ IN ONE STATEMENT.
       read_snapshot is pg_current_snapshot() evaluated by that statement, so
       it is exactly the visibility horizon the balances were read under, and
       it becomes the next run's window. */
    CREATE TEMP TABLE zz_replay_read (
      account_key text, prev_at timestamptz, prev_snapshot text, expected numeric,
      now_bal numeric, read_at timestamptz, read_snapshot text
    ) ON COMMIT DROP;

    /* EACH WINDOW READS ONLY THE LEGS IT IS ASKED ABOUT (2026-10-03). Accounts
       are grouped by the reading they were last judged at, and each group's
       journal window runs from that reading to now, over the whole journal.
       On 2026-10-03 five groups last read between 09-23 and 09-30 asked for
       about 27 days of it - some 30 million leg sides - to explain 65 idle
       accounts: the run grew from 323 s to 627 s in five nights and was
       cancelled at its 600 s budget. A group now reads, through the entity index,
       only the legs of the owners it holds (and a union's wallet row ids,
       which its legs may carry). The felt is one account owned by no entity,
       so the group that holds it still reads the whole window; that group is
       the one read last night, the shortest window of all. */
    FOR w IN SELECT p.prev_at, p.prev_snapshot,
                    bool_or(t.account_type = 'table_stack') AS reads_the_felt,
                    array_agg(DISTINCT t.entity_id) AS owners
               FROM zz_replay_prev p
               JOIN zz_replay_touched t ON t.account_key = p.account_key
              WHERE p.prev_at IS NOT NULL AND p.prev_snapshot IS NOT NULL
              GROUP BY p.prev_at, p.prev_snapshot LOOP
      v_read_at := clock_timestamp();
      IF w.reads_the_felt THEN
        WITH legs AS MATERIALIZED (
          SELECT a.account_key, a.net
            FROM public.fn_ca_leg_accounts_since_snapshot(w.prev_at, w.prev_snapshot::pg_snapshot) a
           WHERE a.account_key IS NOT NULL
        )
        INSERT INTO zz_replay_read (account_key, prev_at, prev_snapshot, expected, now_bal, read_at, read_snapshot)
        SELECT t.account_key, w.prev_at, w.prev_snapshot, COALESCE(l.net, 0),
               public.fn_ca_account_balance(t.account_type, t.entity_id, t.club_id, t.column_name),
               v_read_at, pg_current_snapshot()::text
          FROM zz_replay_touched t
          JOIN zz_replay_prev p ON p.account_key = t.account_key AND p.prev_at = w.prev_at
                               AND p.prev_snapshot = w.prev_snapshot
          LEFT JOIN legs l ON l.account_key = t.account_key;
      ELSE
        v_entities := w.owners
          || ARRAY(SELECT uw.id FROM public.union_wallets uw WHERE uw.union_id = ANY (w.owners));
        WITH legs AS MATERIALIZED (
          SELECT a.account_key, a.net
            FROM public.fn_ca_leg_accounts_since_snapshot_for(w.prev_at, w.prev_snapshot::pg_snapshot, v_entities) a
           WHERE a.account_key IS NOT NULL
        )
        INSERT INTO zz_replay_read (account_key, prev_at, prev_snapshot, expected, now_bal, read_at, read_snapshot)
        SELECT t.account_key, w.prev_at, w.prev_snapshot, COALESCE(l.net, 0),
               public.fn_ca_account_balance(t.account_type, t.entity_id, t.club_id, t.column_name),
               v_read_at, pg_current_snapshot()::text
          FROM zz_replay_touched t
          JOIN zz_replay_prev p ON p.account_key = t.account_key AND p.prev_at = w.prev_at
                               AND p.prev_snapshot = w.prev_snapshot
          LEFT JOIN legs l ON l.account_key = t.account_key;
      END IF;
    END LOOP;

    /* An account nobody has read before, or one whose last reading holds no
       snapshot (every reading before v4), is recorded, not judged. */
    v_read_at := clock_timestamp();
    INSERT INTO public.ca_account_snapshots
      (account_key, account_type, entity_id, club_id, column_name, balance, taken_at, is_baseline, basis_version, note, read_snapshot, cum_unexplained)
    SELECT t.account_key, t.account_type, t.entity_id, t.club_id, t.column_name,
           b.bal, v_read_at, true, v_basis,
           CASE WHEN p.prev_at IS NULL THEN 'baseline: first reading of this account, not judged'
                ELSE format('rebaselined onto %s: the previous reading (%s) windowed the journal by created_at, and a leg that straddled that reading is the reader''s to miss, not the account''s',
                            v_basis, COALESCE(p.prev_basis, 'the unversioned reader')) END,
           pg_current_snapshot()::text,
           0
      FROM zz_replay_touched t
      JOIN zz_replay_prev p ON p.account_key = t.account_key AND (p.prev_at IS NULL OR p.prev_snapshot IS NULL)
      CROSS JOIN LATERAL (
        SELECT public.fn_ca_account_balance(t.account_type, t.entity_id, t.club_id, t.column_name) AS bal
      ) b
     WHERE b.bal IS NOT NULL;
    GET DIAGNOSTICS v_baselines = ROW_COUNT;

    v_read_at := clock_timestamp();
    FOR r IN
      SELECT t.*, p.prev_balance, p.prev_at, p.prev_unexplained, p.prev_cum, p.prev_basis,
             d.expected, d.now_bal, d.read_at, d.read_snapshot
        FROM zz_replay_touched t
        JOIN zz_replay_prev p ON p.account_key = t.account_key
        JOIN zz_replay_read d ON d.account_key = t.account_key AND d.prev_at = p.prev_at
    LOOP
      IF r.now_bal IS NULL THEN CONTINUE; END IF;

      /* A CHANGE OF BASIS IS NOT DRIFT. */
      IF COALESCE(r.prev_basis, '') <> v_basis THEN
        INSERT INTO public.ca_account_snapshots
          (account_key, account_type, entity_id, club_id, column_name, balance, taken_at,
           is_baseline, unexplained, cum_unexplained, basis_version, note, read_snapshot)
        VALUES (r.account_key, r.account_type, r.entity_id, r.club_id, r.column_name,
                r.now_bal, v_read_at, true, NULL, 0, v_basis,
                format('rebaselined onto %s: the previous reading (%s) windowed the journal by created_at, and a leg that straddled that reading is the reader''s to miss, not the account''s',
                       v_basis, COALESCE(r.prev_basis, 'the unversioned reader')),
                r.read_snapshot);
        v_rebased := v_rebased + 1;
        CONTINUE;
      END IF;

      v_checked := v_checked + 1;
      v_this := round((r.now_bal - r.prev_balance) - r.expected, 2);
      v_cum := round(v_this + COALESCE(r.prev_cum, 0), 2);
      v_two := CASE
                 WHEN abs(v_this) >= 100 THEN v_this
                 WHEN v_this <> 0 AND COALESCE(r.prev_unexplained, 0) <> 0
                      AND sign(v_this) = sign(r.prev_unexplained) THEN v_cum
                 ELSE 0
               END;

      INSERT INTO public.ca_account_snapshots
        (account_key, account_type, entity_id, club_id, column_name, balance, taken_at,
         is_baseline, unexplained, cum_unexplained, basis_version, note, read_snapshot)
      VALUES (r.account_key, r.account_type, r.entity_id, r.club_id, r.column_name,
              r.now_bal, v_read_at, false, v_this, v_cum, v_basis,
              format('moved %s, journal %s, unexplained %s this interval (cumulative %s, judged %s) since %s',
                     round(r.now_bal - r.prev_balance, 2), r.expected, v_this, v_cum, v_two, r.prev_at),
              r.read_snapshot);

      IF abs(v_two) > 0.005 THEN
        v_bad := v_bad + 1;
        IF abs(v_two) > abs(v_worst) THEN v_worst := v_two; v_worst_key := r.account_key; END IF;
        IF v_bad <= 20 THEN
          v_sample := v_sample || jsonb_build_object('account', r.account_key, 'moved', round(r.now_bal - r.prev_balance, 2),
                                                     'journal', r.expected, 'unexplained', v_this, 'cumulative', v_cum,
                                                     'since', r.prev_at);
        END IF;
        PERFORM public.fn_ca_raise_drift_incident(
          'fn_ca_ledger_replay', 'ledger_imbalance',
          CASE WHEN abs(v_two) >= 100 THEN 'critical' ELSE 'warning' END,
          'ledger-replay:' || r.account_key || ':' || to_char(v_now, 'YYYY-MM-DD'),
          v_two, r.expected, round(r.now_bal - r.prev_balance, 2),
          'ledger', r.account_type, r.entity_id, r.club_id, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
          format('%s moved %s between %s and now while the journal accounts for %s: %s unexplained this interval, %s over the last two. The journal window is the previous reading''s snapshot, so a leg is counted exactly when it committed after that reading.',
                 r.column_name, round(r.now_bal - r.prev_balance, 2), r.prev_at, r.expected, v_this, v_cum),
          false,
          jsonb_build_object('account_key', r.account_key, 'column', r.column_name,
                             'moved', round(r.now_bal - r.prev_balance, 2), 'journal', r.expected,
                             'unexplained', v_this, 'cumulative', v_cum, 'judged', v_two,
                             'previous_at', r.prev_at, 'basis_version', v_basis));
      END IF;
    END LOOP;

    /* WHAT THIS SNAPSHOT SAW (20261004135607). Under REPEATABLE READ every
       statement of this run reads the snapshot stored on its readings, so the
       legs this statement can see ARE the legs that reading saw. Only xids at
       or above the snapshot's xmin can be misjudged by pg_visible_in_snapshot
       (a subtransaction of a running transaction), and the next window only
       looks back to its previous reading minus 15 minutes. */
    IF current_setting('transaction_isolation') = 'repeatable read' THEN
      INSERT INTO public.ca_ledger_replay_readings (read_snapshot, read_at, committed_legs)
      SELECT pg_current_snapshot()::text, clock_timestamp(), COALESCE(array_agg(l.id ORDER BY l.id), '{}')
        FROM public.chip_ledger l
       WHERE l.created_at > v_now - interval '30 minutes'
         AND public.fn_ca_xid8(l.xmin) >= pg_snapshot_xmin(pg_current_snapshot())
      ON CONFLICT (read_snapshot) DO NOTHING;
    END IF;

    PERFORM public.fn_ca_kill_switch_trip('fn_ca_ledger_replay', v_worst,
      format('one account disagrees with the journal by %s (%s)', round(COALESCE(v_worst, 0), 2), COALESCE(v_worst_key, 'n/a')));

    RETURN jsonb_build_object('checked', v_checked, 'baselines', v_baselines, 'rebaselined', v_rebased,
                              'disagree', v_bad, 'worst', round(COALESCE(v_worst, 0), 2), 'worst_account', v_worst_key,
                              'unkeyable_legs', v_unkeyable, 'basis_version', v_basis,
                              'sample', v_sample, 'at', v_now);
  END;
  $$;


ALTER FUNCTION public.fn_ca_ledger_replay(p_limit integer) OWNER TO postgres;

--
-- TOC entry 45970 (class 0 OID 0)
-- Dependencies: 4485
-- Name: FUNCTION fn_ca_ledger_replay(p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_ledger_replay(p_limit integer) IS 'Chip standard Phase 7.1: checks that each account''s change between its own two most recent readings equals the journal''s net over the same interval. CALL IT IN A REPEATABLE READ TRANSACTION (the nightly job does): under READ COMMITTED a leg that commits between the window end and the balance read shows as a residue, which the two-interval rule then cancels on the next run.';


--
-- TOC entry 7200 (class 1255 OID 83551259)
-- Name: fn_ca_ledger_tally_add(text, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ledger_tally_add(p_key text, p_side text, p_delta numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  t jsonb;
  e jsonb;
  v numeric;
BEGIN
  /* The tally lives in a transaction-local setting, so it is undone with the
     transaction and with any subtransaction (a plpgsql EXCEPTION block) that
     rolls back the write it counted. A SET clause on a function restores only
     the variables it names at exit (measured on production 2026-10-01: a
     set_config(..., true) made inside a SET search_path function was still
     set after it returned), so pinning search_path here does not lose the
     tally. Every object is named by schema regardless. */
  IF p_key IS NULL OR p_delta IS NULL OR round(p_delta, 2) = 0 THEN
    RETURN;
  END IF;
  t := COALESCE(NULLIF(current_setting('ca.ledger_tally', true), '')::jsonb, '{}'::jsonb);
  e := COALESCE(t -> p_key, '{"b":0,"l":0}'::jsonb);
  IF NOT (e ? 'q') THEN
    -- The top-level statement that first touched this account in this
    -- transaction: the name of the door, for the refusal and the finding
    -- (CLAUDE.md 10.86: a refusal names its writer).
    e := e || jsonb_build_object('q', left(COALESCE(current_query(), ''), 300));
  END IF;
  v := round(COALESCE((e ->> p_side)::numeric, 0) + p_delta, 2);
  e := jsonb_set(e, ARRAY[p_side], to_jsonb(v), true);
  t := t || jsonb_build_object(p_key, e);
  PERFORM set_config('ca.ledger_tally', t::text, true);
  PERFORM set_config('ca.ledger_tally_ver',
                     (COALESCE(NULLIF(current_setting('ca.ledger_tally_ver', true), ''), '0')::bigint + 1)::text,
                     true);
END;
$$;


