--
-- TOC entry 8710 (class 1255 OID 38568704)
-- Name: fn_ca_legacy_fee_capture_admitted(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_legacy_fee_capture_admitted(p_tournament_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 -- The sole admission writer fully validates the terminal receipt while
 -- owning the event/escrow and settlement lanes. Only that same transaction
 -- can reuse it. Deferred constraints require its exact resolution and the
 -- full final terminal receipt before anything can commit.
 RETURN EXISTS(
  SELECT 1 FROM public.accounting_tournament_fee_custody_capture_admissions a
  JOIN public.accounting_tournament_fee_custody_obligations o
   ON o.tournament_id=a.tournament_id AND o.id=a.obligation_id
  JOIN public.tournament_terminal_settlements h ON h.tournament_id=a.tournament_id
  WHERE a.tournament_id=p_tournament_id AND a.transaction_id=txid_current()
   AND a.source_fingerprint=o.source_fingerprint AND a.amount=o.amount
   AND h.receipt_version=3 AND h.accounting_state='fee_custody_unresolved'
   AND h.rake_amount=o.amount
   AND NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_custody_resolutions r WHERE r.tournament_id=a.tournament_id)
   AND NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_recognitions r WHERE r.tournament_id=a.tournament_id)
 );
END $$;


ALTER FUNCTION public.fn_ca_legacy_fee_capture_admitted(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 8381 (class 1255 OID 38568716)
-- Name: fn_ca_legacy_fee_capture_requires_resolution(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_legacy_fee_capture_requires_resolution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_custody_resolutions r
  WHERE r.tournament_id=NEW.tournament_id AND r.obligation_id=NEW.obligation_id
   AND r.source_fingerprint=NEW.source_fingerprint AND r.amount=NEW.amount
   AND r.transaction_id=NEW.transaction_id AND r.transaction_id=txid_current())
 THEN RAISE EXCEPTION 'original fee capture cannot commit without its same-transaction resolution' USING ERRCODE='P0404'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION public.fn_ca_legacy_fee_capture_requires_resolution() OWNER TO postgres;

--
-- TOC entry 4373 (class 1255 OID 38568407)
-- Name: fn_ca_legacy_fee_custody_cohort(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_legacy_fee_custody_cohort(p_tournament_id uuid) RETURNS TABLE(amount numeric, source_fingerprint text, source_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT o.amount,o.source_fingerprint,jsonb_array_length(o.original_fees)
   FROM public.accounting_tournament_fee_custody_obligations o
  WHERE o.tournament_id=p_tournament_id
 UNION ALL
 SELECT a.fee,a.fp,a.n FROM public.tournaments t
  JOIN LATERAL (SELECT sum(r.rake_amount) AS fee,
     md5(COALESCE(string_agg(public.fn_accounting_tournament_fee_fingerprint(r),':' ORDER BY r.id),'')) AS fp,
     count(*)::int AS n,
     bool_and(r.created_at<k.starts_at) AS all_pre,
     bool_and(r.terminal_closed_at IS NULL) AS none_closed,
     bool_or(EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches b WHERE b.rake_record_id=r.id)) AS any_batched
    FROM public.rake_records r CROSS JOIN public.accounting_tournament_fee_cutover k
   WHERE r.tournament_id=t.id AND r.is_tournament AND k.singleton) a ON true
  WHERE t.id=p_tournament_id
    AND NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_custody_obligations o WHERE o.tournament_id=t.id)
    AND a.n>0 AND a.fee>0 AND a.fee=round(a.fee,2)
    AND a.all_pre AND a.none_closed AND NOT a.any_batched
    AND t.satellite_target_id IS NULL AND t.satellite_target IS NULL
    AND lower(COALESCE(t.variant,''))<>'satellite'
    AND NOT public.fn_poker_diamond_tournament(t.id)
    AND NOT EXISTS(SELECT 1 FROM public.tournament_rake_settlements x WHERE x.tournament_id=t.id)
    AND NOT EXISTS(SELECT 1 FROM public.tournament_terminal_settlements x WHERE x.tournament_id=t.id)
    AND NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_recognitions x WHERE x.tournament_id=t.id)
    AND NOT EXISTS(SELECT 1 FROM public.accounting_tournament_recognized_sources x WHERE x.tournament_id=t.id)
    AND EXISTS(SELECT 1 FROM public.tournament_escrow e WHERE e.tournament_id=t.id AND e.enforced
               AND e.fee_out=0 AND e.refund_fee=0 AND e.fee_balance=a.fee
               AND e.closed_at IS NULL AND e.terminal_closed_at IS NULL)
$$;


