--

COMMENT ON FUNCTION public.fn_ca_legacy_fee_custody_origin(p_tournament_id uuid) IS 'Original held fee of a legacy fee custody event (fn_ca_legacy_fee_custody_cohort over its obligation row); the engine verifies version 3 terminal receipts against it. Read-only. 20261002034540.';


--
-- TOC entry 3695 (class 1255 OID 38568461)
-- Name: fn_ca_legacy_fee_custody_requires_terminal(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_legacy_fee_custody_requires_terminal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.tournament_terminal_settlements h
  WHERE h.tournament_id=NEW.tournament_id AND h.accounting_state='fee_custody_unresolved'
   AND h.receipt_version=3 AND h.rake_amount=NEW.amount AND h.rake_settled_at IS NULL
   AND h.rake_attributed_at IS NULL AND h.escrow_closed_at IS NULL)
 THEN RAISE EXCEPTION 'fee custody cannot commit without its exact player terminal receipt' USING ERRCODE='P0404'; END IF;
 PERFORM public.fn_ca_tournament_terminal_receipt(NEW.tournament_id,NULL);
 RETURN NULL;
END $$;


