--
-- TOC entry 3632 (class 1255 OID 38568713)
-- Name: fn_ca_legacy_fee_resolution_requires_recognition(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_legacy_fee_resolution_requires_recognition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE receipt jsonb;h public.tournament_terminal_settlements%ROWTYPE;
BEGIN
 receipt:=public.fn_accounting_tournament_terminal_fee_receipt(NEW.tournament_id);
 SELECT * INTO h FROM public.tournament_terminal_settlements WHERE tournament_id=NEW.tournament_id;
 IF receipt->>'status' IS DISTINCT FROM 'recognized'
  OR receipt->>'source_fingerprint' IS DISTINCT FROM NEW.source_fingerprint
  OR (receipt->>'bank_amount')::numeric IS DISTINCT FROM NEW.amount
  OR (receipt->>'banked_at')::timestamptz IS DISTINCT FROM NEW.resolved_at
  OR NOT EXISTS(SELECT 1 FROM public.tournament_rake_settlements s WHERE s.tournament_id=NEW.tournament_id
   AND s.amount=NEW.amount AND s.settled_at=NEW.resolved_at AND s.attributed_at=NEW.resolved_at
   AND s.attributed_users>0 AND s.attribution_error IS NULL AND s.terminal_closed_at=h.completed_at)
  OR NOT EXISTS(SELECT 1 FROM public.tournament_escrow e WHERE e.tournament_id=NEW.tournament_id
   AND e.prize_balance=0 AND e.bounty_balance=0 AND e.fee_balance=0)
 THEN RAISE EXCEPTION 'fee continuation cannot commit without exact original attribution and bank proof' USING ERRCODE='P0404'; END IF;
 PERFORM public.fn_ca_tournament_terminal_receipt(NEW.tournament_id,NULL);
 RETURN NULL;
END $$;


ALTER FUNCTION public.fn_ca_legacy_fee_resolution_requires_recognition() OWNER TO postgres;

--
-- TOC entry 5219 (class 1255 OID 38568708)
-- Name: fn_ca_legacy_fee_resolution_write_is_exact(text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_legacy_fee_resolution_write_is_exact(p_table text, p_operation text, p_old jsonb, p_new jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t uuid:=NULLIF(p_new->>'tournament_id','')::uuid;r public.accounting_tournament_fee_custody_resolutions%ROWTYPE;
 o public.accounting_tournament_fee_custody_obligations%ROWTYPE;h public.tournament_terminal_settlements%ROWTYPE;
BEGIN
 -- The installed Union wallet autoledger identifies its source by the typed
 -- original prize liability and deliberately leaves tournament_id NULL.
 IF t IS NULL AND p_table='chip_ledger' AND p_operation='INSERT'
  AND p_new->>'from_type'='prize_liability'
  AND (public.fn_ca_sep8_spin_original_fee_proof(NULLIF(p_new->>'from_entity_id','')::uuid) IS NOT NULL
   OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_owner_bases ob
    WHERE ob.tournament_id=NULLIF(p_new->>'from_entity_id','')::uuid AND ob.transaction_id=txid_current())) THEN
  t:=NULLIF(p_new->>'from_entity_id','')::uuid;
 END IF;
 IF p_operation='DELETE' OR t IS NULL THEN RETURN false; END IF;
 SELECT * INTO r FROM public.accounting_tournament_fee_custody_resolutions WHERE tournament_id=t AND transaction_id=txid_current();
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT * INTO o FROM public.accounting_tournament_fee_custody_obligations WHERE id=r.obligation_id AND tournament_id=t;
 SELECT * INTO h FROM public.tournament_terminal_settlements WHERE tournament_id=t AND accounting_state='fee_custody_unresolved' AND receipt_version=3;
 IF o.id IS NULL OR h.tournament_id IS NULL OR r.amount IS DISTINCT FROM o.amount
  OR r.source_fingerprint IS DISTINCT FROM o.source_fingerprint
  OR r.original_plan IS DISTINCT FROM public.fn_accounting_tournament_fee_net_plan(t)
 THEN RETURN false; END IF;
 IF p_table='tournament_rake_settlements' THEN
  IF p_operation='INSERT' THEN
   RETURN (p_new->>'amount')::numeric=0 AND p_new->>'destination'='pending'
    AND p_new->>'settled_at' IS NULL AND p_new->>'attributed_at' IS NULL
    AND p_new->>'terminal_closed_at' IS NULL;
  END IF;
  RETURN p_operation='UPDATE' AND p_old->>'terminal_closed_at' IS NULL
   AND (p_old-ARRAY['amount','union_id','destination','settled_at','attributed_at','attributed_users','attribution_error'])
    IS NOT DISTINCT FROM (p_new-ARRAY['amount','union_id','destination','settled_at','attributed_at','attributed_users','attribution_error'])
   AND p_old->>'destination'='pending' AND (p_old->>'amount')::numeric=0
   AND (p_new->>'amount')::numeric=r.amount
   AND (p_new->>'settled_at')::timestamptz=r.resolved_at
   AND (p_new->>'attributed_at')::timestamptz=r.resolved_at
   AND (p_new->>'attributed_users')::integer>0
   AND p_new->>'attribution_error' IS NULL
   AND EXISTS(SELECT 1 FROM public.accounting_tournament_fee_recognitions q WHERE q.tournament_id=t
    AND q.status='recognized' AND q.net_rake=r.amount AND q.recognized_at=r.resolved_at
    AND q.source_fingerprint=r.source_fingerprint);
 ELSIF p_table='chip_ledger' THEN
  IF p_operation='INSERT' AND r.original_plan->>'union_id' IS NOT NULL
   AND (public.fn_ca_sep8_spin_original_fee_proof(t) IS NOT NULL
    OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_owner_bases ob WHERE ob.tournament_id=t
     AND ob.transaction_id=txid_current() AND ob.union_id=(r.original_plan->>'union_id')::uuid)) THEN
   RETURN p_new->>'from_type'='prize_liability' AND p_new->>'from_entity_id'=t::text
    AND (p_new->>'tournament_id' IS NULL OR p_new->>'tournament_id'=t::text)
    AND p_new->>'to_type'='union_wallet' AND p_new->>'to_label'='union_wallets.rake_wallet'
    AND p_new->>'union_id'=r.original_plan->>'union_id' AND p_new->>'category'='rake'
    AND (p_new->>'amount')::numeric=r.amount
    AND p_new->>'description'='auto-ledgered union_wallets.rake_wallet delta '||round(r.amount,2)::text
    AND p_new->>'from_label' IS NULL
    AND (p_new->>'club_id' IS NULL OR p_new->>'club_id'=(SELECT x.club_id::text FROM public.tournaments x WHERE x.id=t))
    AND p_new->>'table_id' IS NULL AND p_new->>'hand_id' IS NULL
    AND p_new->>'idempotency_key' IS NULL AND p_new->>'metadata' IS NULL
    AND p_new->>'pre_from_balance' IS NULL AND p_new->>'post_from_balance' IS NULL
    AND p_new->>'status'='posted' AND (p_new->>'created_at')::timestamptz=r.resolved_at
    AND (p_new->>'performed_by')::uuid=COALESCE(auth.uid(),'2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid)
    AND (p_new->>'pre_to_balance')::numeric>=0
    AND (p_new->>'post_to_balance')::numeric-(p_new->>'pre_to_balance')::numeric=r.amount
    AND EXISTS(SELECT 1 FROM public.union_wallets w WHERE w.id=(p_new->>'to_entity_id')::uuid
     AND w.union_id=(r.original_plan->>'union_id')::uuid
     AND w.rake_wallet=(p_new->>'post_to_balance')::numeric)
    AND EXISTS(SELECT 1 FROM public.tournament_rake_settlements s WHERE s.tournament_id=t
     AND s.destination='pending' AND s.amount=0 AND s.settled_at IS NULL)
    AND NOT EXISTS(SELECT 1 FROM public.chip_ledger l WHERE l.from_type='prize_liability'
     AND l.from_entity_id=t AND l.to_type='union_wallet'
     AND (l.union_id=(r.original_plan->>'union_id')::uuid OR l.to_entity_id=(p_new->>'to_entity_id')::uuid));
  END IF;
  RETURN p_operation='INSERT' AND p_new->>'from_type'='prize_liability'
   AND p_new->>'from_entity_id'=t::text AND p_new->>'to_type'='chip_retirement'
   AND p_new->>'to_entity_id' IS NULL AND p_new->>'category'='burn'
   AND (p_new->>'amount')::numeric=r.amount AND r.original_plan->>'union_id' IS NULL
   AND p_new->>'description'='Standalone tournament fee retired (fn_settle_tournament_rake)';
 ELSIF p_table='tournament_escrow' THEN
  RETURN p_operation='UPDATE' AND (p_old->>'terminal_closed_at')::timestamptz=h.completed_at
   AND (p_old-ARRAY['fee_out','fee_balance','updated_at']) IS NOT DISTINCT FROM
       (p_new-ARRAY['fee_out','fee_balance','updated_at'])
   AND (p_old->>'prize_balance')::numeric=0 AND (p_old->>'bounty_balance')::numeric=0
   AND EXISTS(SELECT 1 FROM public.accounting_tournament_fee_recognitions q WHERE q.tournament_id=t
    AND q.status='recognized' AND q.net_rake=r.amount AND q.recognized_at=r.resolved_at
    AND q.source_fingerprint=r.source_fingerprint)
   AND (((p_old->>'fee_out')::numeric=(o.escrow_snapshot->>'fee_out')::numeric
      AND (p_new->>'fee_out')::numeric=(p_old->>'fee_out')::numeric+r.amount
      AND (p_old->>'fee_balance')::numeric=r.amount AND (p_new->>'fee_balance')::numeric=r.amount)
    OR ((p_old->>'fee_out')::numeric=(o.escrow_snapshot->>'fee_out')::numeric+r.amount
      AND (p_new->>'fee_out')::numeric=(p_old->>'fee_out')::numeric
      AND (p_old->>'fee_balance')::numeric=r.amount AND (p_new->>'fee_balance')::numeric=0));
 END IF;
 RETURN false;
END $$;


ALTER FUNCTION public.fn_ca_legacy_fee_resolution_write_is_exact(p_table text, p_operation text, p_old jsonb, p_new jsonb) OWNER TO postgres;

--
-- TOC entry 7764 (class 1255 OID 27257238)
-- Name: fn_ca_legacy_period_maturity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_legacy_period_maturity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF NEW.status='paid' AND OLD.status IS DISTINCT FROM 'paid'
  AND (NEW.period_end+1)::timestamp AT TIME ZONE 'America/Los_Angeles' > statement_timestamp() THEN
  RAISE EXCEPTION 'Legacy period payment requires a closed earning period' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_legacy_period_maturity() OWNER TO postgres;

--
-- TOC entry 3404 (class 1255 OID 27257247)
-- Name: fn_ca_legacy_round3_wallet_receipt(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_legacy_round3_wallet_receipt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_period record; v_legacy numeric;
BEGIN
 IF NEW.category='rakeback' AND NEW.description='Round 3: agent -> player rakeback [club wallet]' THEN
  IF NEW.related_entity_id IS NULL OR NOT EXISTS(SELECT 1 FROM rakeback_period_payouts p
   JOIN rakeback_periods rp ON rp.id=p.rakeback_period_id
   WHERE p.id=NEW.related_entity_id AND p.user_id=NEW.user_id AND p.club_id=rp.club_id AND p.user_id=rp.user_id
    AND p.payout_amount=NEW.amount AND p.status='paid' AND p.wallet_transaction_id IS NULL AND rp.status='pending')
  THEN RAISE EXCEPTION 'Round3 requires the unique unpaid period receipt' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.category='rakeback' AND NEW.related_entity_id IS NOT NULL THEN
  SELECT rp.*,receipt.payout_amount AS receipt_amount,receipt.user_id AS receipt_user INTO v_period
  FROM rakeback_period_payouts receipt JOIN rakeback_periods rp ON rp.id=receipt.rakeback_period_id
  WHERE receipt.id=NEW.related_entity_id;
  IF FOUND AND (v_period.period_end+1)::timestamp AT TIME ZONE 'America/Los_Angeles' > statement_timestamp() THEN
   RAISE EXCEPTION 'Legacy period payment requires a closed earning period' USING ERRCODE='55000';
  END IF;

 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_legacy_round3_wallet_receipt() OWNER TO postgres;

--
-- TOC entry 5352 (class 1255 OID 48712253)
-- Name: fn_ca_legacy_spin_original_fee_proof(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_legacy_spin_original_fee_proof(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c record;r public.rake_records%ROWTYPE;t public.tournaments%ROWTYPE;
 v public.managed_game_contract_versions%ROWTYPE;tp record;e record;l record;s record;
 item record;n integer;gross numeric:=0;earliest timestamptz;rows jsonb:='[]';versions jsonb:='[]';
 reserve jsonb;game_union uuid;reserve_account uuid;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.tournaments zt
  WHERE zt.id=p_tournament_id AND lower(COALESCE(zt.variant,''))='spin'
    AND zt.tournament_type='SPIN' AND zt.is_private IS FALSE
    AND zt.satellite_target_id IS NULL AND zt.satellite_target IS NULL
    AND NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_custody_obligations zo
                    WHERE zo.tournament_id=p_tournament_id)
    AND EXISTS(SELECT 1 FROM public.fn_ca_legacy_fee_custody_cohort(p_tournament_id)))
 THEN RETURN NULL; END IF;
 SELECT * INTO c FROM public.fn_ca_legacy_fee_custody_cohort(p_tournament_id);
 SELECT count(*) INTO n FROM public.rake_records WHERE tournament_id=p_tournament_id AND is_tournament;
 SELECT * INTO r FROM public.rake_records WHERE tournament_id=p_tournament_id AND is_tournament;
 SELECT * INTO t FROM public.tournaments WHERE id=p_tournament_id;
 IF n<>1 OR c.source_count IS DISTINCT FROM 1 OR r.source IS DISTINCT FROM 'fn_spin_book_entry'
  OR r.rake_amount IS DISTINCT FROM c.amount OR md5(public.fn_accounting_tournament_fee_fingerprint(r)) IS DISTINCT FROM c.source_fingerprint
  OR r.created_at>='2026-09-17T18:24:02.831517Z'::timestamptz OR r.hand_id IS NOT NULL
  OR r.metadata->>'kind' IS DISTINCT FROM 'spin_rake' OR jsonb_typeof(r.player_contributions) IS DISTINCT FROM 'object'
  OR t.is_private IS DISTINCT FROM false OR t.variant IS DISTINCT FROM 'spin' OR t.tournament_type IS DISTINCT FROM 'SPIN'
  OR public.fn_poker_diamond_tournament(p_tournament_id)
 THEN RAISE EXCEPTION 'named Spin original aggregate identity missing' USING ERRCODE='P0404'; END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(r.player_contributions))<>3
  OR (SELECT count(*) FROM public.tournament_players WHERE tournament_id=p_tournament_id)<>3
  OR (SELECT count(DISTINCT value::numeric) FROM jsonb_each_text(r.player_contributions))<>1
 THEN RAISE EXCEPTION 'named Spin requires exactly three equal original paid contributors' USING ERRCODE='P0404'; END IF;
 FOR item IN SELECT key::uuid player_id,value::numeric weight FROM jsonb_each_text(r.player_contributions) ORDER BY key LOOP
  SELECT * INTO tp FROM public.tournament_players WHERE tournament_id=p_tournament_id AND user_id=item.player_id;
  SELECT count(*) INTO n FROM public.tournament_refund_entitlements x WHERE x.tournament_id=p_tournament_id
   AND x.user_id=item.player_id AND x.entitlement_kind='wallet_charge' AND x.charge_category='tournament_buyin'
   AND x.created_at=tp.registered_at AND x.gross=item.weight;
  IF n<>1 THEN RAISE EXCEPTION 'named Spin original paid entry ambiguous' USING ERRCODE='P0404'; END IF;
  SELECT * INTO e FROM public.tournament_refund_entitlements x WHERE x.tournament_id=p_tournament_id
   AND x.user_id=item.player_id AND x.entitlement_kind='wallet_charge' AND x.charge_category='tournament_buyin'
   AND x.created_at=tp.registered_at AND x.gross=item.weight;
  SELECT * INTO l FROM public.chip_ledger WHERE id=e.source_ledger_id;
  IF l.id IS NULL OR tp.club_id IS DISTINCT FROM e.refund_wallet_club_id OR l.created_at IS DISTINCT FROM e.created_at
   OR e.created_at>r.created_at OR l.amount IS DISTINCT FROM e.gross OR l.club_id IS DISTINCT FROM e.refund_wallet_club_id
   OR l.from_type IS DISTINCT FROM 'player_wallet' OR l.from_entity_id IS DISTINCT FROM item.player_id
   OR l.to_type IS DISTINCT FROM 'prize_liability' OR l.to_entity_id IS DISTINCT FROM p_tournament_id
   OR l.category IS DISTINCT FROM 'tournament_buyin' OR item.weight<=0
  THEN RAISE EXCEPTION 'named Spin original debit evidence disagrees' USING ERRCODE='P0404'; END IF;
  earliest:=least(earliest,e.created_at);gross:=gross+item.weight;
  rows:=rows||jsonb_build_array(jsonb_build_object('registration_id',tp.id,'player_id',item.player_id,
   'club_id',tp.club_id,'registered_at',tp.registered_at,'entitlement',to_jsonb(e)-'terminal_closed_at','ledger',to_jsonb(l)));
 END LOOP;
 SELECT count(*) INTO n FROM public.spin_reserve_ledger WHERE tournament_id=p_tournament_id AND kind='contribution';
 SELECT * INTO s FROM public.spin_reserve_ledger WHERE tournament_id=p_tournament_id AND kind='contribution';
 IF n<>1 OR s.seats IS DISTINCT FROM 3 OR s.house_rake IS DISTINCT FROM r.rake_amount
  OR s.amount IS DISTINCT FROM gross-r.rake_amount OR s.buy_in IS DISTINCT FROM gross/3
 THEN RAISE EXCEPTION 'named Spin original reserve contribution disagrees' USING ERRCODE='P0404'; END IF;
 reserve:=jsonb_build_object('contribution',to_jsonb(s)-'terminal_closed_at');
 SELECT count(*) INTO n FROM public.chip_ledger x WHERE x.tournament_id=p_tournament_id AND x.category='spin_entry';
 SELECT * INTO l FROM public.chip_ledger x WHERE x.tournament_id=p_tournament_id AND x.category='spin_entry';
 IF n<>1 OR l.amount IS DISTINCT FROM s.amount OR l.created_at IS DISTINCT FROM s.created_at
  OR l.club_id IS DISTINCT FROM s.club_id OR l.from_type IS DISTINCT FROM 'prize_liability'
  OR l.from_entity_id IS DISTINCT FROM p_tournament_id OR l.to_type IS DISTINCT FROM 'spin_reserve' OR l.to_entity_id IS NULL
 THEN RAISE EXCEPTION 'named Spin reserve contribution debit disagrees' USING ERRCODE='P0404'; END IF;
 reserve_account:=l.to_entity_id;reserve:=reserve||jsonb_build_object('contribution_ledger',to_jsonb(l));
 SELECT count(*) INTO n FROM public.spin_reserve_ledger WHERE tournament_id=p_tournament_id AND kind='jackpot_draw';
 SELECT * INTO s FROM public.spin_reserve_ledger WHERE tournament_id=p_tournament_id AND kind='jackpot_draw';
 IF n<>1 OR s.seats IS DISTINCT FROM 3 OR s.house_rake IS DISTINCT FROM r.rake_amount
  OR s.amount IS DISTINCT FROM -t.prize_pool OR s.buy_in IS DISTINCT FROM gross/3 OR s.amount>=0
 THEN RAISE EXCEPTION 'named Spin original prize draw disagrees' USING ERRCODE='P0404'; END IF;
 reserve:=reserve||jsonb_build_object('draw',to_jsonb(s)-'terminal_closed_at');
 SELECT count(*) INTO n FROM public.chip_ledger x WHERE x.tournament_id=p_tournament_id AND x.category='spin_prize';
 SELECT * INTO l FROM public.chip_ledger x WHERE x.tournament_id=p_tournament_id AND x.category='spin_prize';
 IF n<>1 OR l.amount IS DISTINCT FROM -s.amount OR l.created_at IS DISTINCT FROM s.created_at
  OR l.club_id IS DISTINCT FROM s.club_id OR l.from_type IS DISTINCT FROM 'spin_reserve'
  OR l.from_entity_id IS DISTINCT FROM reserve_account OR l.to_type IS DISTINCT FROM 'prize_liability'
  OR l.to_entity_id IS DISTINCT FROM p_tournament_id
 THEN RAISE EXCEPTION 'named Spin original prize draw credit disagrees' USING ERRCODE='P0404'; END IF;
 reserve:=reserve||jsonb_build_object('draw_ledger',to_jsonb(l));
 SELECT * INTO v FROM public.managed_game_contract_versions WHERE game_id=p_tournament_id AND game_kind='tournament' AND version=1;
 IF NOT FOUND OR v.published_at>earliest OR v.club_id IS DISTINCT FROM r.club_id
  OR v.club_id IS DISTINCT FROM t.club_id OR v.union_id IS DISTINCT FROM t.union_id
 THEN RAISE EXCEPTION 'named Spin original created scope missing' USING ERRCODE='P0404'; END IF;
 game_union:=v.union_id;
 FOR v IN SELECT * FROM public.managed_game_contract_versions WHERE game_id=p_tournament_id AND game_kind='tournament'
  AND published_at<=r.created_at ORDER BY version,id LOOP
  IF v.club_id IS DISTINCT FROM t.club_id OR v.union_id IS DISTINCT FROM game_union
   OR v.contract->>'id' IS DISTINCT FROM p_tournament_id::text OR v.contract->>'club_id' IS DISTINCT FROM v.club_id::text
   OR NULLIF(v.contract->>'union_id','')::uuid IS DISTINCT FROM game_union OR v.contract->'is_private' IS DISTINCT FROM 'false'::jsonb
   OR v.contract->>'variant' IS DISTINCT FROM 'spin' OR v.contract->>'tournament_type' IS DISTINCT FROM 'SPIN'
   OR (v.contract->>'buy_in_amount')::numeric IS DISTINCT FROM gross/3 OR (v.contract->>'max_players')::integer IS DISTINCT FROM 3
   OR v.contract_hash IS DISTINCT FROM public.fn_managed_game_contract_hash(v.contract)
  THEN RAISE EXCEPTION 'named Spin immutable economic scope disagrees' USING ERRCODE='P0404'; END IF;
  versions:=versions||jsonb_build_array(to_jsonb(v));
 END LOOP;
 RETURN jsonb_build_object('tournament_id',p_tournament_id,'raw_source_count',1,'recognized_contributors',3,
  'source_fingerprint',c.source_fingerprint,'fee',c.amount,'gross',gross,'contributors',rows,'reserve',reserve,'scope_versions',versions);
END $$;


ALTER FUNCTION public.fn_ca_legacy_spin_original_fee_proof(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 6051 (class 1255 OID 35049259)
-- Name: fn_ca_legacy_tournament_format(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_legacy_tournament_format(p_row jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
  SELECT CASE
    WHEN upper(p_row->>'tournament_type')='SPIN' AND lower(p_row->>'variant')='spin'
      AND p_row->>'max_players'='3'
      AND NULLIF(p_row->>'satellite_target_id','') IS NULL
      AND NULLIF(p_row->>'satellite_target','') IS NULL THEN 'spin-v1'
    WHEN upper(p_row->>'tournament_type')='SNG' AND lower(p_row->>'variant')='sng'
      AND CASE WHEN coalesce(p_row->>'max_players','')~'^[0-9]+$'
               THEN (p_row->>'max_players')::numeric>=2 ELSE false END
      AND NULLIF(p_row->>'satellite_target_id','') IS NULL
      AND NULLIF(p_row->>'satellite_target','') IS NULL THEN 'sng-v1'
    WHEN upper(p_row->>'tournament_type')='SATELLITE' AND lower(p_row->>'variant')='sng'
      AND p_row->>'max_players'='2' AND p_row->>'min_players'='2'
      AND p_row->>'table_size'='2'
      AND coalesce(NULLIF(p_row->>'satellite_target_id',''),NULLIF(p_row->>'satellite_target','')) IS NOT NULL
      AND (NULLIF(p_row->>'satellite_target_id','') IS NULL
           OR NULLIF(p_row->>'satellite_target','') IS NULL
           OR p_row->>'satellite_target_id'=p_row->>'satellite_target')
      THEN 'seat-first-satellite-v1'
    WHEN upper(p_row->>'tournament_type') IN ('MTT','XMTT')
      AND lower(p_row->>'variant') IN
        ('freezeout','rebuy','reentry','bounty','progressive_bounty','mystery_bounty','satellite','mtt')
      AND CASE WHEN coalesce(p_row->>'max_players','')~'^[0-9]+$'
               THEN (p_row->>'max_players')::numeric>2 ELSE false END THEN 'mtt-v1'
    ELSE NULL END
$_$;


ALTER FUNCTION public.fn_ca_legacy_tournament_format(p_row jsonb) OWNER TO postgres;

--
-- TOC entry 5556 (class 1255 OID 35049258)
-- Name: fn_ca_lock_mtt_admission_contract(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_lock_mtt_admission_contract() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_abi text;
BEGIN
  SELECT abi INTO v_abi FROM public.ca_mtt_admission_contract WHERE singleton FOR SHARE;
  IF NOT FOUND OR v_abi NOT IN ('legacy-capacity-v1','unlimited-mtt-v2') THEN
    RAISE EXCEPTION 'MTT_ADMISSION_CONTRACT_MISSING_OR_UNKNOWN' USING ERRCODE='55000';
  END IF;
  RETURN v_abi;
END $$;


ALTER FUNCTION public.fn_ca_lock_mtt_admission_contract() OWNER TO postgres;

--
-- TOC entry 8384 (class 1255 OID 94160920)
-- Name: fn_ca_lock_satellite_answer_lane(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_lock_satellite_answer_lane(p_satellite_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_held text := COALESCE(current_setting('ca.finish_lane_tournament', true), '');
  v_target_id uuid;
  v_first uuid;
  v_second uuid;
BEGIN
  IF v_held <> '' THEN
    -- Re-entry inside a finish transaction: everything below is held.
    PERFORM public.fn_ca_lock_settlement_lane_for_finish(NULL);
    RETURN;
  END IF;
  IF p_satellite_id IS NOT NULL THEN
    SELECT COALESCE(t.satellite_target_id, t.satellite_target)
      INTO v_target_id
      FROM public.tournaments t
     WHERE t.id = p_satellite_id;
  END IF;
  IF p_satellite_id IS NULL OR v_target_id IS NULL OR v_target_id = p_satellite_id THEN
    -- No target to scope to: the satellite finish lane decides, as it always did.
    PERFORM public.fn_ca_lock_settlement_lane_for_satellite_finish(p_satellite_id);
    RETURN;
  END IF;
  -- AN ANSWER WAITS ONLY FOR WHAT IT SHARES (2026-10-03). Both T keys in uuid
  -- order, the payer's order. The first comes with G shared and F shared from
  -- the finish helper's re-entry path (no bank scope is named, so no scope
  -- key): the satellite's payer and every sweep hold F exclusively and are
  -- still waited for and excluded, while ordinary finishes of other
  -- tournaments (F shared) no longer drain before an answer and queue behind
  -- it. Then the second T key exclusively. The payer, both tournaments'
  -- hands and rolling authorities, and a finish of the target are excluded
  -- exactly as before.
  IF p_satellite_id::text < v_target_id::text THEN
    v_first := p_satellite_id; v_second := v_target_id;
  ELSE
    v_first := v_target_id; v_second := p_satellite_id;
  END IF;
  PERFORM set_config('ca.finish_lane_scope', '', true);
  PERFORM set_config('ca.finish_lane_tournament', v_first::text, true);
  PERFORM public.fn_ca_lock_settlement_lane_for_finish(NULL);
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1:' || v_second::text, 0));
  -- Re-entry names the satellite, as the satellite finish lane does (the
  -- receipt readers re-enter through fn_ca_lock_settlement_lane_for_finish(NULL),
  -- which asks F shared and the held T key, both already held here).
  PERFORM set_config('ca.finish_lane_tournament', p_satellite_id::text, true);
END;
$$;


ALTER FUNCTION public.fn_ca_lock_satellite_answer_lane(p_satellite_id uuid) OWNER TO postgres;

--
-- TOC entry 9301 (class 1255 OID 33872274)
-- Name: fn_ca_lock_settlement_lane_for_finish(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_lock_settlement_lane_for_finish(p_tournament_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_held text := COALESCE(current_setting('ca.finish_lane_tournament', true), '');
  v_held_scope text := COALESCE(current_setting('ca.finish_lane_scope', true), '');
  -- Unknown until the row proves it is a plain tournament: the whole lane.
  v_satellite boolean := true;
  v_scope text;
BEGIN
  -- Re-entry: this transaction already holds a finish lane. Every key below
  -- is already held by this backend, so nothing waits; a second tournament
  -- is refused, a transaction never holds two tournaments' lanes. (Inside a
  -- satellite finish or a sweep, F is held exclusively by this backend, so F
  -- shared is granted at once and no scope key is named.)
  IF v_held <> '' THEN
    IF p_tournament_id IS NOT NULL AND v_held <> p_tournament_id::text THEN
      RAISE EXCEPTION 'finish lane is held for tournament %, refused for %',
        v_held, p_tournament_id USING ERRCODE = '55000';
    END IF;
    PERFORM pg_advisory_xact_lock_shared(
      hashtextextended('ca:tournament-terminal-settlement:v1', 0));
    PERFORM pg_advisory_xact_lock_shared(
      hashtextextended('ca:tournament-finish-lane:v1', 0));
    IF v_held_scope <> '' THEN
      PERFORM pg_advisory_xact_lock(
        hashtextextended('ca:tournament-finish-lane:v1:scope:' || v_held_scope, 0));
    END IF;
    PERFORM pg_advisory_xact_lock(
      hashtextextended('ca:tournament-terminal-settlement:v1:' || v_held, 0));
    RETURN;
  END IF;

  -- Resolve the tournament before any lock. variant, tournament_type and the
  -- satellite target are fixed for the life of the row, so reading them
  -- unlocked gives the answer reading them under the lane would. The bank
  -- scope is the host club's union, else the host club; the finish itself
  -- refuses (40001) if the club changes union before it holds the banks.
  IF p_tournament_id IS NOT NULL THEN
    SELECT (lower(COALESCE(t.variant::text, '')) = 'satellite'
            OR upper(COALESCE(t.tournament_type::text, '')) = 'SATELLITE'
            OR t.satellite_target_id IS NOT NULL
            OR t.satellite_target IS NOT NULL),
           COALESCE(c.union_id::text, t.club_id::text, '')
      INTO v_satellite, v_scope
      FROM public.tournaments t
      LEFT JOIN public.clubs c ON c.id = t.club_id
     WHERE t.id = p_tournament_id;
    IF NOT FOUND THEN
      v_satellite := true;
    END IF;
  END IF;

  -- A satellite finish writes the target tournament's rows, and an unknown
  -- tournament cannot be scoped: the whole lane, as it always was.
  IF v_satellite OR COALESCE(v_scope, '') = '' THEN
    PERFORM public.fn_ca_lock_settlement_lane_global();
    RETURN;
  END IF;

  -- G SHARED: waits for, and excludes, the rare global authorities (G
  -- exclusive) and nothing else.
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('ca:tournament-terminal-settlement:v1', 0));
  -- F SHARED: satellite finishes and sweeps hold F exclusively and still
  -- exclude every ordinary finish; ordinary finishes no longer exclude
  -- each other platform-wide.
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('ca:tournament-finish-lane:v1', 0));
  -- F(scope) EXCLUSIVE: one finish at a time per bank scope, so finishes
  -- that share a club wallet, union bank, club treasury or the players'
  -- wallets in those clubs keep the order they had under F exclusive.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-finish-lane:v1:scope:' || v_scope, 0));
  -- T(id) EXCLUSIVE: this tournament's hands (T shared) and rolling
  -- authorities (T exclusive) wait for the finish, and the proof-of-
  -- authority guards read it as this backend's authority over the rows.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1:' || p_tournament_id::text, 0));
  -- The rest of this transaction re-enters this lane through
  -- fn_ca_lock_settlement_lane_global; transaction-local, gone at commit.
  PERFORM set_config('ca.finish_lane_scope', v_scope, true);
  PERFORM set_config('ca.finish_lane_tournament', p_tournament_id::text, true);
END;
$$;


ALTER FUNCTION public.fn_ca_lock_settlement_lane_for_finish(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 7456 (class 1255 OID 34914685)
-- Name: fn_ca_lock_settlement_lane_for_satellite_finish(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_lock_settlement_lane_for_satellite_finish(p_satellite_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_held text := COALESCE(current_setting('ca.finish_lane_tournament', true), '');
  v_target_id uuid;
  v_first uuid;
  v_second uuid;
BEGIN
  IF v_held <> '' THEN
    -- Re-entry inside a finish transaction: everything below is held.
    PERFORM public.fn_ca_lock_settlement_lane_for_finish(NULL);
    RETURN;
  END IF;
  IF p_satellite_id IS NOT NULL THEN
    SELECT COALESCE(t.satellite_target_id, t.satellite_target)
      INTO v_target_id
      FROM public.tournaments t
     WHERE t.id = p_satellite_id;
  END IF;
  IF p_satellite_id IS NULL OR v_target_id IS NULL OR v_target_id = p_satellite_id THEN
    -- No target to scope to: the whole lane, as it always was.
    PERFORM public.fn_ca_lock_settlement_lane_global();
    RETURN;
  END IF;
  -- G shared, F exclusive (one finish at a time, satellite or not), then
  -- both T keys exclusively in uuid order. A rolling authority or hand of
  -- either tournament waits on its T; two satellites into one target are
  -- serialised by F; no other transaction holds two T keys at once.
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('ca:tournament-terminal-settlement:v1', 0));
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-finish-lane:v1', 0));
  IF p_satellite_id::text < v_target_id::text THEN
    v_first := p_satellite_id; v_second := v_target_id;
  ELSE
    v_first := v_target_id; v_second := p_satellite_id;
  END IF;
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1:' || v_first::text, 0));
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1:' || v_second::text, 0));
  -- Re-entry names the satellite; T(target) is held for the transaction's
  -- life regardless, which is what the target's guards read.
  PERFORM set_config('ca.finish_lane_tournament', p_satellite_id::text, true);
END;
$$;


ALTER FUNCTION public.fn_ca_lock_settlement_lane_for_satellite_finish(p_satellite_id uuid) OWNER TO postgres;

--
-- TOC entry 7428 (class 1255 OID 34914662)
-- Name: fn_ca_lock_settlement_lane_for_sweep_member(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_lock_settlement_lane_for_sweep_member(p_tournament_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_satellite boolean := true;
BEGIN
  IF p_tournament_id IS NULL THEN
    RAISE EXCEPTION 'a sweep member lane needs a tournament' USING ERRCODE = '22004';
  END IF;
  SELECT (lower(COALESCE(t.variant::text, '')) = 'satellite'
          OR upper(COALESCE(t.tournament_type::text, '')) = 'SATELLITE'
          OR t.satellite_target_id IS NOT NULL
          OR t.satellite_target IS NOT NULL)
    INTO v_satellite
    FROM public.tournaments t
   WHERE t.id = p_tournament_id;
  IF NOT FOUND OR v_satellite THEN
    -- A sweep already holds G shared for its earlier members; the global
    -- lane here would be an upgrade. Refuse instead: the callers sweep
    -- Spins, which are never satellites.
    RAISE EXCEPTION 'sweep member % is not a plain tournament', p_tournament_id
      USING ERRCODE = '55000';
  END IF;
  -- G shared, F exclusive (once per transaction; re-taking is free), then
  -- T(member) exclusive. Members are taken in the sweep's scan order, which
  -- every sweep shares, so two sweeps cannot take two members oppositely;
  -- no finish or rolling authority ever holds two tournaments' T keys.
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('ca:tournament-terminal-settlement:v1', 0));
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-finish-lane:v1', 0));
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1:' || p_tournament_id::text, 0));
  -- The member's own settlement calls re-enter this lane through the global
  -- helper; the name is replaced per member, never cleared mid-transaction.
  PERFORM set_config('ca.finish_lane_tournament', p_tournament_id::text, true);
END;
$$;


ALTER FUNCTION public.fn_ca_lock_settlement_lane_for_sweep_member(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 9137 (class 1255 OID 25904554)
-- Name: fn_ca_lock_settlement_lane_for_tournament(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id uuid, p_table_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tournament_id uuid := p_tournament_id;
BEGIN
  -- Resolve the tournament before any lock, so G's mode can depend on it.
  -- tables.tournament_id is fixed for the life of a table: reading it here
  -- gives the answer reading it under G did.
  IF v_tournament_id IS NULL AND p_table_id IS NOT NULL THEN
    SELECT tb.tournament_id INTO v_tournament_id
    FROM public.tables tb
    WHERE tb.id = p_table_id;
  END IF;

  IF v_tournament_id IS NULL THEN
    -- Nothing to scope to: the whole lane, as it always was - G exclusive,
    -- then B exclusive (the shape of fn_ca_lock_settlement_lane_global).
    PERFORM pg_advisory_xact_lock(
      hashtextextended('ca:tournament-terminal-settlement:v1', 0));
    PERFORM pg_advisory_xact_lock(
      hashtextextended('ca:hand-settlement-barrier:v1', 0));
    RETURN;
  END IF;

  -- G SHARED: waits for, and excludes, terminal authorities (G exclusive)
  -- and nothing else. Rolling authorities of different tournaments run side
  -- by side; the trigger guards take T(id) held exclusively as their proof.
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('ca:tournament-terminal-settlement:v1', 0));

  -- T(id) EXCLUSIVE: one rolling authority per tournament at a time, and
  -- this tournament's hand settlements (T(id) shared) wait for it.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1:' || v_tournament_id::text, 0));
END;
$$;


ALTER FUNCTION public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id uuid, p_table_id uuid) OWNER TO postgres;

--
-- TOC entry 45996 (class 0 OID 0)
-- Dependencies: 9137
-- Name: FUNCTION fn_ca_lock_settlement_lane_for_tournament(p_tournament_id uuid, p_table_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id uuid, p_table_id uuid) IS 'Rolling per-tournament money authorities: G exclusive, then T(tournament) exclusive. Excludes only that tournament''s hand settlements. Falls back to B when no tournament can be resolved.';


--
-- TOC entry 7378 (class 1255 OID 25904553)
-- Name: fn_ca_lock_settlement_lane_global(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_lock_settlement_lane_global() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Inside a non-satellite finish (2026-09-17) this transaction already
  -- holds that finish's lane: G shared, F exclusive, T(id) exclusive. The
  -- finish body and the settle functions still call this helper; re-enter
  -- the lane that is held instead of requesting G exclusively, which would
  -- be an upgrade of a shared hold (2026-09-10: no upgrades, they deadlock).
  IF COALESCE(current_setting('ca.finish_lane_tournament', true), '') <> '' THEN
    PERFORM public.fn_ca_lock_settlement_lane_for_finish(NULL);
    RETURN;
  END IF;
  -- G then B. Terminal / rare authorities: serialised against every other
  -- authority AND against every hand settlement, as on 2026-09-09.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:tournament-terminal-settlement:v1', 0));
  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:hand-settlement-barrier:v1', 0));
END;
$$;


ALTER FUNCTION public.fn_ca_lock_settlement_lane_global() OWNER TO postgres;

--
-- TOC entry 45998 (class 0 OID 0)
-- Dependencies: 7378
-- Name: FUNCTION fn_ca_lock_settlement_lane_global(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_lock_settlement_lane_global() IS 'Terminal/rare tournament money authorities: G (ca:tournament-terminal-settlement:v1) exclusive, then B (ca:hand-settlement-barrier:v1) exclusive. Excludes every hand settlement on the platform for the duration. See the 2026-09-10 lane migration.';


--
-- TOC entry 7772 (class 1255 OID 216883645)
-- Name: fn_ca_lock_structure_clock(jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_lock_structure_clock(p_structure jsonb, p_minutes integer) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(jsonb_agg(
    CASE
      WHEN jsonb_typeof(x) <> 'object' OR x->'isBreak' = 'true'::jsonb THEN x
      ELSE (x - 'duration' - 'duration_minutes') || jsonb_build_object('durationMinutes', p_minutes)
    END ORDER BY ord), '[]'::jsonb)
  FROM jsonb_array_elements(p_structure) WITH ORDINALITY AS e(x, ord);
$$;


ALTER FUNCTION public.fn_ca_lock_structure_clock(p_structure jsonb, p_minutes integer) OWNER TO postgres;

