--
-- TOC entry 3379 (class 1255 OID 77077750)
-- Name: fn_ca_mint_register_attribution(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_mint_register_attribution() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH w AS (SELECT * FROM public.fn_ca_mint_wallet_attribution(NULL))
  SELECT jsonb_build_object(
    'live_wallets',               (SELECT count(*) FROM w),
    'register_agrees',            (SELECT count(*) FROM w WHERE verdict = 'register_agrees'),
    'register_drifts',            (SELECT count(*) FROM w WHERE verdict = 'register_drifts'),
    'opening_stock_only',         (SELECT count(*) FROM w WHERE verdict = 'opening_stock_only'),
    'wallets_net_differs',        (SELECT count(*) FROM w WHERE held <> register_net),
    'unattributed_opening_stock', (SELECT COALESCE(sum(unattributed_opening_stock), 0) FROM w),
    'baseline_circulation_net',   (SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0)
                                     FROM public.ca_mint_ledger
                                    WHERE asset = 'diamonds' AND holder_type IN ('circulation', 'house')),
    'deleted_holder_residual',    (SELECT COALESCE(SUM(CASE WHEN m.action = 'mint' THEN m.amount ELSE -m.amount END), 0)
                                     FROM public.ca_mint_ledger m
                                    WHERE m.asset = 'diamonds' AND m.holder_type = 'player'
                                      AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = m.holder_id)),
    'global_identity_difference', (SELECT difference FROM public.fn_ca_diamond_register_vs_supply()),
    'read_at',                    now()
  );
$$;


ALTER FUNCTION public.fn_ca_mint_register_attribution() OWNER TO postgres;

--
-- TOC entry 46018 (class 0 OID 0)
-- Dependencies: 3379
-- Name: FUNCTION fn_ca_mint_register_attribution(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_mint_register_attribution() IS 'The per-wallet standing of the diamond register, in one read. Read only.

register_drifts is the number that matters and it is expected to be 0. It
counts wallets the register tracks whose balance chain does not end at what
the wallet holds, which is the only shape a genuine per-wallet fault can take.

wallets_net_differs is NOT a fault count. It counts wallets whose register NET
is short by their unattributed opening stock, which is by design. On
2026-09-30 it read 1,068 with register_drifts 0, and
unattributed_opening_stock (1,021,092) equalled baseline_circulation_net
(1,623,417) plus deleted_holder_residual (-602,325) to the diamond.

This function repairs nothing, pays nothing and is not scheduled. It is a read
(CLAUDE.md 10.11, 10.12).';


--
-- TOC entry 7464 (class 1255 OID 21202300)
-- Name: fn_ca_mint_register_vs_supply(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_mint_register_vs_supply() RETURNS TABLE(register_net numeric, register_net_at_meter numeric, meter_total numeric, meter_taken_at timestamp with time zone, difference numeric, unexplained_since_baseline numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH s AS (SELECT total, taken_at FROM public.ca_supply_snapshots ORDER BY taken_at DESC LIMIT 1),
       r AS (SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0) AS net FROM public.ca_mint_ledger WHERE asset = 'chips'),
       ra AS (SELECT COALESCE(SUM(CASE WHEN m.action = 'mint' THEN m.amount ELSE -m.amount END), 0) AS net
                FROM public.ca_mint_ledger m, s WHERE m.asset = 'chips' AND m.created_at <= s.taken_at),
       b AS (SELECT min(created_at) AS at FROM public.ca_mint_ledger WHERE op_id LIKE 'register-opening-baseline:%'),
       u AS (SELECT COALESCE(sum(unexplained), 0) AS drift FROM public.ca_supply_snapshots, b WHERE taken_at > b.at),
       -- A baseline correction re-sizes the register to a meter whose definition
       -- changed; it is neither issuance nor drift, so it is added back here.
       c AS (SELECT COALESCE(SUM(CASE WHEN m.action = 'mint' THEN -m.amount ELSE m.amount END), 0) AS corr
               FROM public.ca_mint_ledger m, s WHERE m.asset = 'chips' AND m.op_id LIKE 'register-opening-baseline-correction:%' AND m.created_at <= s.taken_at)
  SELECT round(r.net, 2), round(ra.net, 2), round(s.total, 2), s.taken_at, round(s.total - ra.net, 2), round(u.drift + c.corr, 2) FROM r, ra, s, u, c;
$$;


