--
-- TOC entry 5717 (class 1255 OID 18305266)
-- Name: fn_ca_mint_velocity_watch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_mint_velocity_watch() RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_mint numeric; v_burn numeric; v_grants bigint; v_grant_chips numeric;
        v_ops bigint; v_op_chips numeric; v_launch_count bigint; v_launch_mint numeric; v_launch_burn numeric;
BEGIN
  /* THE NEW-CLUB OPENING GRANT IS NEVER DRIFT (2026-09-23). Creating a
     standalone chip club mints its declared 100,000-chip opening bank
     (fn_seed_new_club_opening_bank declares it, fn_record_new_club_opening_bank
     registers it). This sum had no entity dimension, so three new clubs
     inside ten minutes filed a warning and eleven a critical, and
     fn_ca_is_midway_scope files a raise with no dimension into Midway's own
     incident flow. A grant is left out ONLY in its exact declared shape:
     the journal leg issuance_reserve (system_mint before 2026-09-03) ->
     club_treasury, category mint, posted, exactly 100,000, landing in the
     club it names, keyed 'club-opening-grant:<that club>', AND linked from
     the mint register row the grant's own trigger wrote for that club and
     that amount. Short of all of it, the leg is still counted. What is
     left out rides along as metadata on any raise this watch still makes;
     it never makes one.

     AN OPERATOR'S DECLARED FUNDING IS NOT A LOOP EITHER (2026-10-03). Both
     mint warnings of 2026-10-03 were deliberate, reviewed settlements: the
     standalone rake bank of Deep Stack Society (607,265.09, two closed weeks
     of rake retired at the hand and banked at the close) and the owner's
     funding of its overdue agent commission (560,017.06). Each was minted
     through fn_ca_fund_club under its own operation key, and the mint
     register row fn_ca_fund_club wrote for it - origin 'operator', op_id
     equal to the leg's idempotency_key, linked to that leg, the same amount,
     with a reason - is the declaration a person has to read anyway. Such a
     mint is left out and rides along as metadata, but only while there are
     at most three of them in the window: a loop through the declaring door
     is still a loop. An auto-registered row (origin 'journal', op_id
     'ledger:<leg>') declares nothing and is still counted. */
  SELECT COALESCE(sum(l.amount) FILTER (WHERE l.from_type IN ('system_mint','issuance_reserve')
                                          AND NOT g.declared_opening_grant
                                          AND NOT o.declared_operator_mint AND NOT x.launch_receipt), 0),
         COALESCE(sum(l.amount) FILTER (WHERE l.to_type   IN ('system_burn','chip_retirement') AND NOT x.launch_receipt), 0),
         count(*) FILTER (WHERE g.declared_opening_grant),
         COALESCE(sum(l.amount) FILTER (WHERE g.declared_opening_grant), 0),
         count(*) FILTER (WHERE o.declared_operator_mint),
         COALESCE(sum(l.amount) FILTER (WHERE o.declared_operator_mint), 0), count(*) FILTER(WHERE x.launch_receipt), COALESCE(sum(l.amount) FILTER(WHERE x.launch_receipt AND l.from_type IN('issuance_reserve','chip_retirement')),0), COALESCE(sum(l.amount) FILTER(WHERE x.launch_receipt AND l.to_type='chip_retirement'),0)
    INTO v_mint, v_burn, v_grants, v_grant_chips, v_ops, v_op_chips, v_launch_count, v_launch_mint, v_launch_burn
    FROM public.chip_ledger l CROSS JOIN LATERAL (SELECT public.fn_ca_launch_velocity_receipt(l.id) AS launch_receipt) x
    CROSS JOIN LATERAL (
      SELECT (l.category = 'mint'
          AND l.from_type IN ('issuance_reserve', 'system_mint')
          AND l.to_type = 'club_treasury'
          AND l.status = 'posted'
          AND l.amount = 100000
          AND l.to_entity_id = l.club_id
          AND l.idempotency_key = 'club-opening-grant:' || l.to_entity_id::text
          AND EXISTS (
            SELECT 1 FROM public.ca_mint_ledger m
             WHERE m.op_id = l.idempotency_key
               AND m.chip_ledger_id = l.id
               AND m.action = 'mint' AND m.asset = 'chips'
               AND m.holder_type = 'club' AND m.holder_id = l.to_entity_id
               AND m.amount = 100000)) IS TRUE AS declared_opening_grant
    ) g
    CROSS JOIN LATERAL (
      SELECT (l.category = 'mint'
          AND l.from_type IN ('issuance_reserve', 'system_mint')
          AND l.status = 'posted'
          AND l.idempotency_key IS NOT NULL
          AND EXISTS (
            SELECT 1 FROM public.ca_mint_ledger m
             WHERE m.op_id = l.idempotency_key
               AND m.chip_ledger_id = l.id
               AND m.origin = 'operator'
               AND m.performed_by_label = 'fn_ca_fund_club'
               AND m.action = 'mint' AND m.asset = 'chips'
               AND m.amount = l.amount
               AND COALESCE(btrim(m.reason), '') <> '')) IS TRUE AS declared_operator_mint
    ) o
   WHERE l.created_at > now() - interval '10 minutes';

  IF v_ops > 3 THEN
    v_mint := v_mint + v_op_chips;
  END IF;

  IF v_mint > 250000 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_mint_velocity_watch', 'ledger_imbalance',
      CASE WHEN v_mint > 1000000 THEN 'critical' ELSE 'warning' END,
      'mint-velocity:' || to_char(now(), 'YYYY-MM-DD-HH24'),
      v_mint, 250000, v_mint, 'ledger', 'chip_ledger',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      round(v_mint, 2) || ' chips minted in 10 minutes, declared new-club opening grants and up to three declared operator mints not counted - far above the expected trickle; if this is not a deliberate batch (an epoch reset), a mint loop is running',
      true, jsonb_build_object('mint_10m', round(v_mint,2), 'burn_10m', round(v_burn,2),
                               'opening_grants_10m', v_grants,
                               'opening_grant_chips_10m', round(v_grant_chips,2),
                               'operator_mints_10m', v_ops,
                               'operator_mint_chips_10m', round(v_op_chips,2),
                               'operator_mints_counted', v_ops > 3, 'declared_launch_receipts_10m',v_launch_count,'declared_launch_mint_or_restore_chips_10m',v_launch_mint,'declared_launch_burn_chips_10m',v_launch_burn));
  END IF;

  IF v_burn > 1000000 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_mint_velocity_watch', 'ledger_imbalance', 'warning',
      'burn-velocity:' || to_char(now(), 'YYYY-MM-DD-HH24'),
      v_burn, 1000000, v_burn, 'ledger', 'chip_ledger',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      round(v_burn, 2) || ' chips burned in 10 minutes - expected only during an epoch reset or a mass cleanup; verify the operation is deliberate',
      true, jsonb_build_object('mint_10m', round(v_mint,2), 'burn_10m', round(v_burn,2), 'declared_launch_receipts_10m',v_launch_count,'declared_launch_mint_or_restore_chips_10m',v_launch_mint,'declared_launch_burn_chips_10m',v_launch_burn));
  END IF;

  RETURN v_mint;
END $$;


ALTER FUNCTION public.fn_ca_mint_velocity_watch() OWNER TO postgres;

--
-- TOC entry 8132 (class 1255 OID 77077747)
-- Name: fn_ca_mint_wallet_attribution(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_mint_wallet_attribution(p_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(user_id uuid, held numeric, register_net numeric, unattributed_opening_stock numeric, register_chain_end numeric, journal_rows_since_last_register bigint, verdict text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH scope AS (
    SELECT p.id, COALESCE(p.diamonds, 0)::numeric AS held
      FROM public.profiles p
     WHERE p_user_id IS NULL OR p.id = p_user_id
  ),
  last_reg AS (
    SELECT m.holder_id, max(m.created_at) AS at
      FROM public.ca_mint_ledger m
     WHERE m.asset = 'diamonds' AND m.holder_type = 'player'
     GROUP BY m.holder_id
  ),
  net AS (
    SELECT m.holder_id,
           SUM(CASE WHEN m.action = 'mint' THEN m.amount ELSE -m.amount END) AS n
      FROM public.ca_mint_ledger m
     WHERE m.asset = 'diamonds' AND m.holder_type = 'player'
     GROUP BY m.holder_id
  ),
  pre AS (
    SELECT s.id, s.held, COALESCE(n.n, 0) AS register_net,
           (lr.holder_id IS NOT NULL) AS tracked, lr.at AS last_reg_at,
           -- CHANGED 20261007112751. The journal movement after the chain's
           -- last instant that the register does not follow BY DESIGN
           -- (fn_ca_diamond_journal_origin returns NULL: the arena doors,
           -- player-to-player transfers, journal backfills, the Mint's and the
           -- seed door's own rows). A buy-in after a wallet's last register
           -- row moved its balance and was never meant to move its chain.
           -- Computed only when the chain does not already end at holdings.
           CASE WHEN lr.holder_id IS NOT NULL
                 AND NOT EXISTS (SELECT 1 FROM public.ca_mint_ledger m
                                  WHERE m.asset = 'diamonds' AND m.holder_type = 'player'
                                    AND m.holder_id = s.id AND m.created_at = lr.at
                                    AND m.balance_after = s.held)
                THEN (SELECT COALESCE(SUM(t.amount), 0) FROM public.diamond_transactions t
                       WHERE t.user_id = s.id AND t.created_at > lr.at
                         -- CHANGED 20261007122947. A 'journal_backfill' row
                         -- writes down a movement that already happened (or,
                         -- for a correction, one that never moved the wallet);
                         -- it moved nothing now, so it carries nothing.
                         AND COALESCE(t.source, '') <> 'journal_backfill'
                         AND public.fn_ca_diamond_journal_origin(t.type, t.transaction_type, t.source,
                                                                 t.issuance_class, t.amount) IS NULL)
                ELSE 0 END AS carried
      FROM scope s
      LEFT JOIN last_reg lr ON lr.holder_id = s.id
      LEFT JOIN net n ON n.holder_id = s.id
  ),
  base AS (
    SELECT p.id, p.held, p.register_net, p.tracked, p.last_reg_at,
           -- The reading at the wallet's latest register instant that AGREES
           -- with holdings, if there is one. Several rows can share one
           -- created_at (one transaction claiming many rewards), so
           -- ORDER BY created_at DESC LIMIT 1 picks arbitrarily among them,
           -- and that is what made an earlier reading of this report 38 false
           -- drifts. Read the chain by value. CHANGED 20261007112751: the
           -- chain is carried forward over the unfollowed-by-design movement.
           (SELECT m.balance_after FROM public.ca_mint_ledger m
             WHERE m.asset = 'diamonds' AND m.holder_type = 'player' AND m.holder_id = p.id
               AND m.created_at = p.last_reg_at AND m.balance_after + p.carried = p.held LIMIT 1) AS agreeing_end
      FROM pre p
  )
  SELECT b.id,
         b.held,
         b.register_net,
         b.held - b.register_net,
         CASE WHEN NOT b.tracked THEN NULL
              ELSE COALESCE(b.agreeing_end,
                     (SELECT max(m.balance_after) FROM public.ca_mint_ledger m
                       WHERE m.asset = 'diamonds' AND m.holder_type = 'player'
                         AND m.holder_id = b.id AND m.created_at = b.last_reg_at)) END,
         -- Counted ONLY where it is diagnostic, which is a drifting wallet.
         -- Counting it for all 1,427 cost 5.1 of this read's 5.6 seconds and
         -- told nobody anything: a wallet whose chain already ends at its
         -- holdings has no unfollowed movement to find. NULL means not
         -- counted, not zero.
         CASE WHEN b.tracked AND b.agreeing_end IS NULL
              THEN (SELECT count(*) FROM public.diamond_transactions t
                     WHERE t.user_id = b.id AND t.created_at > b.last_reg_at) END,
         CASE WHEN NOT b.tracked THEN 'opening_stock_only'
              WHEN b.agreeing_end IS NOT NULL THEN 'register_agrees'
              ELSE 'register_drifts' END
    FROM base b;
$$;


ALTER FUNCTION public.fn_ca_mint_wallet_attribution(p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 46024 (class 0 OID 0)
-- Dependencies: 8132
-- Name: FUNCTION fn_ca_mint_wallet_attribution(p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_mint_wallet_attribution(p_user_id uuid) IS 'What the Mint register can and cannot say about ONE wallet. Read only.

register_net is SUM(mint) - SUM(burn) over that wallet''s own register rows. It
is NOT the wallet balance and was never meant to be: the pre-2026-09-03 supply
was acknowledged as one lump against the `circulation` holder
(baseline:diamonds:2026-09-03:v2) and deliberately never attributed per holder
(docs/DIAMOND-ACCOUNTING-STANDARD.md lane B, "backfill NOTHING"). The
difference held - register_net is therefore that wallet''s opening stock, which
is why on 2026-09-30 all 1,068 differing wallets held MORE than their register
net and not one held less.

register_chain_end is the per-wallet truth the register does carry, and it is
exact.

verdict is one of three, never two:
  register_agrees     the register tracks this wallet and its balance chain
                      ends exactly at what the wallet holds.
  register_drifts     the register tracks this wallet and its chain does NOT
                      end at holdings. This is the real fault: something moved
                      profiles.diamonds that the register did not follow. Read
                      journal_rows_since_last_register to see whether the
                      journal followed it either. That count is computed only
                      for a drifting wallet, because counting it for every
                      wallet cost 5.1 of this read''s 5.6 seconds and told
                      nobody anything; NULL there means not counted, not
                      zero.
  opening_stock_only  the register has never tracked this wallet. Its whole
                      balance predates the baseline. NOTHING IS CONCLUDED, and
                      this is not "balanced".';


--
-- TOC entry 3631 (class 1255 OID 19003896)
-- Name: fn_ca_money_path_log(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_money_path_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_path text;
  v_cat  text;
  v_mode text;
  v_exact_refund_token uuid;
BEGIN
  v_path := COALESCE(current_setting('app.money_path', true), '');
  IF v_path IN (
       'fn_settle_tournament_obligation',
       'fn_settle_satellite_tournament') THEN
    RETURN NEW;
  END IF;

  v_cat := lower(COALESCE(NEW.category, ''));

  -- The exact refund authority (fn_settle_tournament_refund_exact, the only
  -- payer of a tournament refund since 20260909165629) books an authorization
  -- row before its insert and stamps its token in app.ca_exact_refund_token;
  -- the escrow trigger consumes that row after this one fires. The credit is
  -- authorized when the row on the books names this tournament, this player
  -- and this amount. A token with no row is not an authority.
  IF v_cat = 'refund' THEN
    BEGIN
      v_exact_refund_token :=
        NULLIF(current_setting('app.ca_exact_refund_token', true), '')::uuid;
    EXCEPTION WHEN OTHERS THEN
      v_exact_refund_token := NULL;
    END;
    IF v_exact_refund_token IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.tournament_refund_authorizations a
       WHERE a.token = v_exact_refund_token
         AND a.tournament_id = NEW.related_entity_id
         AND a.user_id = NEW.user_id
         AND round(a.amount_paid_now, 2) = round(NEW.amount, 2)
    ) THEN
      RETURN NEW;
    END IF;
  END IF;

  -- The mode is data, so the way back is an UPDATE and not a deploy. A missing
  -- row means log: this guard never becomes stricter by accident.
  SELECT e.mode INTO v_mode FROM public.ca_money_path_enforcement e WHERE e.only_row;
  v_mode := COALESCE(v_mode, 'log');

  IF v_mode = 'refuse' THEN
    -- Nothing survives this raise, so the message carries the evidence: who
    -- wrote, from where, for how much, against which entity.
    RAISE EXCEPTION
      'R3: a % credit of % was written outside fn_settle_tournament_obligation (money_path=%, app=%, role=%, wallet_transactions.related_entity_id=%). Route it through fn_settle_tournament_obligation. To reopen the door: UPDATE public.ca_money_path_enforcement SET mode = ''log'';',
      COALESCE(NULLIF(v_cat, ''), '<none>'), NEW.amount, COALESCE(NULLIF(v_path, ''), '<none>'),
      COALESCE(NULLIF(current_setting('application_name', true), ''), '<none>'),
      session_user::text, NEW.related_entity_id
      USING ERRCODE = 'raise_exception';
  END IF;

  BEGIN
    INSERT INTO public.ca_money_path_violations
      (table_name, user_id, amount, category, description, related_entity_id,
       money_path, app_name, db_role)
    VALUES
      (TG_TABLE_NAME, NEW.user_id, NEW.amount, NEW.category, NEW.description,
       NEW.related_entity_id, NULLIF(v_path, ''),
       NULLIF(current_setting('application_name', true), ''),
       session_user::text);
  EXCEPTION WHEN OTHERS THEN
    -- The logger must never be the reason a credit fails.
    NULL;
  END;

  BEGIN
    -- Global scope (no entity dimension) so it files for every union; the
    -- tournament id travels in metadata only. INFO never pages.
    PERFORM public.fn_ca_raise_drift_incident(
      p_source         => 'r3_money_path_log',
      p_classification => 'unauthorized_adjustment',
      p_severity       => 'info',
      p_dedupe_key     => 'r3:' || v_cat || ':' || to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24'),
      p_discrepancy    => NEW.amount,
      p_layer          => 'settlement',
      p_entity_type    => 'wallet_transactions',
      p_entity_id      => NEW.id,
      p_suspected_cause => 'a tournament-category credit was written outside fn_settle_tournament_obligation (R3, log-only)',
      p_metadata       => jsonb_build_object('category', NEW.category, 'money_path', NULLIF(v_path, ''),
                            'related_entity_id', NEW.related_entity_id,
                            'app_name', NULLIF(current_setting('application_name', true), ''),
                            'session_user', session_user::text));
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_ca_money_path_log() OWNER TO postgres;

--
-- TOC entry 46026 (class 0 OID 0)
-- Dependencies: 3631
-- Name: FUNCTION fn_ca_money_path_log(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_money_path_log() IS 'R3: a tournament-category wallet credit is admitted when app.money_path names the obligation or satellite settlement authority, or when it is the exact refund authority''s credit (an app.ca_exact_refund_token whose tournament_refund_authorizations row names this tournament, player and amount). Otherwise logged, or refused when ca_money_path_enforcement.mode = refuse.';


--
-- TOC entry 5887 (class 1255 OID 27833512)
-- Name: fn_ca_money_rpc_balance_columns(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_money_rpc_balance_columns() RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT array_agg(DISTINCT c)
    FROM (
      SELECT (regexp_matches(pg_get_triggerdef(t.oid), '''([a-z_]+)=([a-z_]+)''', 'g'))[1] AS c
        FROM pg_trigger t
        JOIN pg_proc p ON p.oid = t.tgfoid
       WHERE NOT t.tgisinternal AND p.proname IN ('fn_ca_autoledger','fn_ca_autoledger_delete')
      UNION
      SELECT unnest(ARRAY['chip_balance','held_chips','locked_chips','credit_used',
                          'stack','balance','chips','prize','bounty_winnings'])
    ) s;
$$;


ALTER FUNCTION public.fn_ca_money_rpc_balance_columns() OWNER TO postgres;

