--
-- TOC entry 5848 (class 1255 OID 30772712)
-- Name: fn_ca_mtt_blind_contract(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_mtt_blind_contract(p_structure text, p_starting_chips integer) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  levels jsonb; r jsonb; i integer:=0; played integer:=0;
  sb numeric; bb numeric; ante numeric; mins numeric; secs numeric; opening numeric;
  previous_sb numeric:=-1; previous_bb numeric:=-1; speed text;
BEGIN
  IF p_starting_chips IS NULL OR p_starting_chips<=0 THEN
    RAISE EXCEPTION 'Invalid tournament blind structure: starting stack must be a positive whole number' USING ERRCODE='22023';
  END IF;
  BEGIN levels:=p_structure::jsonb;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'Invalid tournament blind structure: unreadable ladder' USING ERRCODE='22023';
  END;
  IF levels IS NULL OR jsonb_typeof(levels)<>'array' THEN
    RAISE EXCEPTION 'Invalid tournament blind structure: at least one playable level is required' USING ERRCODE='22023';
  END IF;
  IF jsonb_array_length(levels)=0 THEN
    RAISE EXCEPTION 'Invalid tournament blind structure: at least one playable level is required' USING ERRCODE='22023';
  END IF;
  FOR r IN SELECT value FROM jsonb_array_elements(levels) LOOP
    i:=i+1;
    IF jsonb_typeof(r)<>'object' THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % must be an object',i USING ERRCODE='22023';
    END IF;
    IF r ? 'isBreak' AND jsonb_typeof(r->'isBreak')<>'boolean' THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % has an invalid break flag',i USING ERRCODE='22023';
    END IF;
    mins:=public.fn_ca_blind_contract_number(COALESCE(NULLIF(r->'durationMinutes','null'::jsonb),r->'duration_minutes'));
    secs:=public.fn_ca_blind_contract_number(r->'duration');
    IF COALESCE(mins,0)<=0 AND COALESCE(secs,0)<=0 THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % needs a positive duration',i USING ERRCODE='22023';
    END IF;
    sb:=public.fn_ca_blind_contract_number(r->'smallBlind');
    bb:=public.fn_ca_blind_contract_number(r->'bigBlind');
    ante:=CASE WHEN r ? 'ante' THEN public.fn_ca_blind_contract_number(r->'ante') ELSE 0 END;
    IF sb IS NULL OR bb IS NULL OR ante IS NULL THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % has invalid blinds or ante',i USING ERRCODE='22023';
    END IF;
    IF r->'isBreak'='true'::jsonb THEN
      IF i=1 OR sb<>0 OR bb<>0 OR ante<>0 THEN
        RAISE EXCEPTION 'Invalid tournament blind structure: level % is not a valid break',i USING ERRCODE='22023';
      END IF;
      CONTINUE;
    END IF;
    IF bb<=0 OR sb>bb THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % needs a positive big blind at least as large as its small blind',i USING ERRCODE='22023';
    END IF;
    IF sb<previous_sb OR bb<previous_bb THEN
      RAISE EXCEPTION 'Invalid tournament blind structure: level % decreases the blinds',i USING ERRCODE='22023';
    END IF;
    IF played=0 THEN opening:=CASE WHEN mins>0 THEN mins ELSE secs/60 END; END IF;
    previous_sb:=sb; previous_bb:=bb; played:=played+1;
  END LOOP;
  IF played=0 THEN
    RAISE EXCEPTION 'Invalid tournament blind structure: at least one playable level is required' USING ERRCODE='22023';
  END IF;
  speed:=CASE WHEN opening<=2 THEN 'hyper_turbo' WHEN opening<=5 THEN 'turbo' WHEN opening>=12 THEN 'slow' ELSE 'standard' END;
  RETURN jsonb_build_object('blind_speed',speed,'is_turbo',speed IN ('turbo','hyper_turbo'));
END;
$$;


ALTER FUNCTION public.fn_ca_mtt_blind_contract(p_structure text, p_starting_chips integer) OWNER TO postgres;

--
-- TOC entry 4645 (class 1255 OID 191066648)
-- Name: fn_ca_mtt_late_registration_minutes(jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_mtt_late_registration_minutes(p_structure jsonb, p_levels integer) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r jsonb; idx integer:=0; mins numeric; secs numeric; duration_ms numeric;
 total_ms numeric:=0; last_ms numeric:=0; result numeric;
BEGIN
 IF p_levels IS NULL OR p_levels<0 THEN RAISE EXCEPTION 'Invalid tournament late-registration level count' USING ERRCODE='22023'; END IF;
 IF p_levels=0 THEN RETURN 0; END IF;
 IF p_structure IS NULL OR jsonb_typeof(p_structure)<>'array' THEN RAISE EXCEPTION 'Missing tournament late-registration clock' USING ERRCODE='22023'; END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p_structure) LOOP
  idx:=idx+1;
  IF r->'isBreak'='true'::jsonb THEN CONTINUE; END IF;
  mins:=public.fn_ca_blind_contract_number(COALESCE(NULLIF(r->'durationMinutes','null'::jsonb),r->'duration_minutes'));
  secs:=public.fn_ca_blind_contract_number(r->'duration');
  duration_ms:=CASE WHEN mins>0 THEN mins*60000 ELSE secs*1000 END;
  IF duration_ms IS NULL OR duration_ms<=0 THEN RAISE EXCEPTION 'Invalid tournament late-registration clock' USING ERRCODE='22023'; END IF;
  last_ms:=duration_ms;
  IF idx<=p_levels THEN total_ms:=total_ms+duration_ms; END IF;
 END LOOP;
 IF last_ms<=0 THEN RAISE EXCEPTION 'Missing tournament late-registration clock' USING ERRCODE='22023'; END IF;
 IF p_levels>idx THEN total_ms:=total_ms+(p_levels-idx)*last_ms; END IF;
 result:=ceil(total_ms/60000);
 IF result>2147483647 THEN RAISE EXCEPTION 'Tournament late-registration minutes exceed the database range' USING ERRCODE='22023'; END IF;
 RETURN result::integer;
END $$;


ALTER FUNCTION public.fn_ca_mtt_late_registration_minutes(p_structure jsonb, p_levels integer) OWNER TO postgres;

--
-- TOC entry 4222 (class 1255 OID 218010745)
-- Name: fn_ca_mtt_payout_depth_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_mtt_payout_depth_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_club_union uuid;
  v_asset text;
  v_is_mtt boolean;
  v_enforced boolean;
  v_depth numeric;
BEGIN
  -- Payout terms that are already committed never move.
  IF TG_OP = 'UPDATE' AND COALESCE(OLD.prize_pool_finalized, false) THEN
    NEW.payout_depth_percent := OLD.payout_depth_percent;
    RETURN NEW;
  END IF;

  v_is_mtt := upper(COALESCE(NEW.tournament_type,'')) = 'MTT'
          AND lower(COALESCE(NEW.variant,'')) NOT IN ('spin','sng','satellite')
          AND NEW.satellite_target_id IS NULL
          AND NOT COALESCE(NEW.is_premium_spin, false);
  IF NOT v_is_mtt THEN
    NEW.payout_depth_percent := NULL;
    RETURN NEW;
  END IF;

  SELECT c.union_id, c.asset INTO v_club_union, v_asset
    FROM public.clubs c WHERE c.id = NEW.club_id;
  v_enforced := NEW.union_id IS NOT NULL
             OR v_club_union IS NOT NULL
             OR v_asset = 'diamonds'
             OR NEW.club_id IS NULL
             OR COALESCE(NEW.is_xmtt, false)
             OR NEW.club_id = 'fade0000-0000-0000-0000-000000000001'::uuid;

  IF v_enforced THEN
    v_depth := 12.5;
  ELSE
    v_depth := COALESCE(
      CASE WHEN NEW.payout_depth_percent > 0 AND NEW.payout_depth_percent <= 100
           THEN NEW.payout_depth_percent END,
      CASE WHEN NEW.payout_percent IN (15, 20) THEN NEW.payout_percent::numeric END,
      12.5);
  END IF;

  -- Never produce a diff an UPDATE did not need (Diamond and lifecycle guards
  -- compare whole rows).
  IF TG_OP = 'UPDATE' AND OLD.payout_depth_percent IS NOT DISTINCT FROM v_depth THEN
    NEW.payout_depth_percent := OLD.payout_depth_percent;
  ELSE
    NEW.payout_depth_percent := v_depth;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_mtt_payout_depth_guard() OWNER TO postgres;

--
-- TOC entry 5304 (class 1255 OID 25752144)
-- Name: fn_ca_my_tournament_payments(uuid, uuid, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_my_tournament_payments(p_tournament_id uuid DEFAULT NULL::uuid, p_club_id uuid DEFAULT NULL::uuid, p_before_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_rows jsonb;
  v_last jsonb;
  v_has_more boolean;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 100 THEN
    RAISE EXCEPTION 'Payment page size must be between 1 and 100' USING ERRCODE = '22023';
  END IF;
  IF (p_before_created_at IS NULL) <> (p_before_id IS NULL) THEN
    RAISE EXCEPTION 'Both payment cursor fields are required' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(page) ORDER BY page.created_at DESC, page.id DESC), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT o.id, o.tournament_id, t.name AS tournament_name, t.club_id,
           o.kind, o.amount_owed, o.amount_paid, o.created_at, o.updated_at
    FROM public.tournament_obligations o
    JOIN public.tournaments t ON t.id = o.tournament_id
    WHERE o.user_id = v_user_id
      AND (p_tournament_id IS NULL OR o.tournament_id = p_tournament_id)
      AND (p_club_id IS NULL OR t.club_id = p_club_id)
      AND (p_before_created_at IS NULL
           OR (o.created_at, o.id) < (p_before_created_at, p_before_id))
    ORDER BY o.created_at DESC, o.id DESC
    LIMIT p_limit + 1
  ) page;

  v_has_more := jsonb_array_length(v_rows) > p_limit;
  IF v_has_more THEN
    v_rows := v_rows - p_limit;
    v_last := v_rows -> (p_limit - 1);
  END IF;

  RETURN jsonb_build_object(
    'user_id', v_user_id,
    'payments', v_rows,
    'has_more', v_has_more,
    'next_before_created_at', CASE WHEN v_has_more THEN v_last ->> 'created_at' END,
    'next_before_id', CASE WHEN v_has_more THEN v_last ->> 'id' END
  );
END;
$$;


ALTER FUNCTION public.fn_ca_my_tournament_payments(p_tournament_id uuid, p_club_id uuid, p_before_created_at timestamp with time zone, p_before_id uuid, p_limit integer) OWNER TO postgres;

