--
-- TOC entry 5578 (class 1255 OID 18996930)
-- Name: fn_ca_open_payout_freeze(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_open_payout_freeze(p_scope text, p_reason text, p_actor_label text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_scope text := lower(btrim(COALESCE(p_scope, '')));
  v_uid   uuid := auth.uid();
  v_label text := COALESCE(NULLIF(btrim(p_actor_label), ''),
                           NULLIF(current_setting('application_name', true), ''),
                           session_user::text);
  v_row   public.ca_payout_freeze%ROWTYPE;
BEGIN
  IF NOT public.fn_ca_caller_is_management() THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'not_management');
  END IF;
  IF v_scope NOT IN ('tournament_payouts', 'bbj_payouts', 'diamond_issuance',
                     'diamond_tournament_payouts') THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'unknown_scope');
  END IF;
  IF length(btrim(COALESCE(p_reason, ''))) < 10 THEN
    RETURN jsonb_build_object('ok', false, 'refused_reason', 'reason_too_short');
  END IF;

  SELECT * INTO v_row FROM public.ca_payout_freeze
   WHERE scope = v_scope AND cleared_at IS NULL
   FOR UPDATE;
  IF FOUND THEN
    RETURN jsonb_build_object('ok', true, 'already_open', true, 'freeze_id', v_row.id,
      'scope', v_row.scope, 'opened_at', v_row.opened_at, 'opened_by', v_row.opened_by,
      'opened_by_label', v_row.opened_by_label, 'reason', v_row.reason);
  END IF;

  INSERT INTO public.ca_payout_freeze (scope, reason, opened_by, opened_by_label)
  VALUES (v_scope, btrim(p_reason), v_uid, v_label)
  RETURNING * INTO v_row;

  PERFORM public.fn_raise_server_financial_alert(
    'warning', 'ca_payout_freeze',
    format('Payouts FROZEN on scope %s by %s: %s', v_scope, v_label, btrim(p_reason)),
    jsonb_build_object('freeze_id', v_row.id, 'scope', v_scope, 'opened_by', v_uid,
                       'opened_by_label', v_label, 'opened_at', v_row.opened_at),
    'freeze:' || v_row.id::text);

  RETURN jsonb_build_object('ok', true, 'already_open', false, 'freeze_id', v_row.id,
    'scope', v_row.scope, 'opened_at', v_row.opened_at, 'opened_by', v_uid,
    'opened_by_label', v_label, 'reason', v_row.reason);
END $$;


ALTER FUNCTION public.fn_ca_open_payout_freeze(p_scope text, p_reason text, p_actor_label text) OWNER TO postgres;

--
-- TOC entry 3908 (class 1255 OID 25985130)
-- Name: fn_ca_open_tournament_seat_exit_authority(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_open_tournament_seat_exit_authority(p_tournament_id uuid, p_operation text, p_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_token uuid:=gen_random_uuid();
BEGIN
  IF p_tournament_id IS NULL
     OR p_operation NOT IN (
       'unregister','cancel','satellite_finish','terminal_finish','move',
       'elimination') THEN
    RAISE EXCEPTION 'invalid tournament seat-exit authority scope'
      USING ERRCODE='22023';
  END IF;

  -- This tournament's lane (2026-09-10): G shared, T(id) exclusive. Every
  -- row below belongs to this one tournament. Re-entered free by a rolling
  -- caller; granted at once under a terminal caller (G and B exclusive).
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  PERFORM 1 FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist',p_tournament_id
      USING ERRCODE='P0002';
  END IF;

  -- Deterministic seat order matches hand settlement and terminal close.
  PERFORM s.id
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.left_at IS NULL
     AND (p_user_id IS NULL OR s.user_id=p_user_id)
   ORDER BY s.id
   FOR UPDATE OF s;

  INSERT INTO public.tournament_seat_exit_authorizations(
    token,seat_id,tournament_id,user_id,operation)
  SELECT v_token,s.id,p_tournament_id,s.user_id,p_operation
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.left_at IS NULL
     AND s.user_id IS NOT NULL
     AND (p_user_id IS NULL OR s.user_id=p_user_id)
   ORDER BY s.id;

  PERFORM set_config('app.tournament_seat_exit_token',v_token::text,true);
  PERFORM set_config('app.tournament_seat_exit_operation',p_operation,true);
  RETURN v_token;
END;
$$;


ALTER FUNCTION public.fn_ca_open_tournament_seat_exit_authority(p_tournament_id uuid, p_operation text, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 9147 (class 1255 OID 19670786)
-- Name: fn_ca_operator_audit_trail(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_audit_trail(p_target_type text, p_target_id text, p_limit integer, p_offset integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_limit  int := least(greatest(coalesce(p_limit, 50), 1), 500);
  v_offset int := greatest(coalesce(p_offset, 0), 0);
  v_total  bigint := 0;
  v_rows   jsonb := '[]'::jsonb;
begin
  select count(*) into v_total
  from public.admin_audit_log a
  where a.target_type = p_target_type
    and a.target_id = p_target_id;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc), '[]'::jsonb)
    into v_rows
  from (
    select a.id, a.admin_user_id, a.actor_role, a.action, a.target_type, a.target_id,
           a.details, a.before_state, a.after_state, a.ip_address, a.user_agent,
           a.request_id, a.created_at
    from public.admin_audit_log a
    where a.target_type = p_target_type
      and a.target_id = p_target_id
    order by a.created_at desc
    limit v_limit offset v_offset
  ) t;

  -- This function files NO audit row. It is a read with no actor in its
  -- signature, so the write it used to attempt passed a null actor and
  -- was refused every time. See the header. The route's write actions
  -- audit with the real actor through operatorAudit.js.

  return jsonb_build_object(
    'rows', v_rows,
    'total', v_total,
    'limit', v_limit,
    'offset', v_offset
  );
end
$$;


ALTER FUNCTION public.fn_ca_operator_audit_trail(p_target_type text, p_target_id text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- TOC entry 6278 (class 1255 OID 137568969)
-- Name: fn_ca_operator_cancel_tournament(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_cancel_tournament(p_tournament_id uuid, p_op_id uuid, p_reason text, p_actor_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '120s'
    AS $$
DECLARE permissions jsonb; event public.tournaments%ROWTYPE; prior public.ca_operator_tournament_operations%ROWTYPE;
 snapshot jsonb; amount numeric; asset text; approval jsonb; receipt jsonb; v_result jsonb; marked jsonb;
BEGIN
 IF p_tournament_id IS NULL OR p_op_id IS NULL OR p_actor_id IS NULL OR p_reason IS NULL
  OR length(btrim(p_reason)) NOT BETWEEN 10 AND 500 OR length(COALESCE(p_request_id,'')) NOT BETWEEN 1 AND 200
 THEN RAISE EXCEPTION 'invalid_tournament_operation' USING ERRCODE='22023'; END IF;
 permissions:=public.fn_ca_operator_permissions(p_actor_id)->'permissions';
 IF NOT COALESCE(permissions ?& ARRAY['console.read','clubs.write','money.write','money.read'],false)
 THEN RAISE EXCEPTION 'tournament_cancel_permission_denied' USING ERRCODE='42501'; END IF;
 -- Same global settlement lane as the existing cancellation/finish authorities.
 PERFORM public.fn_ca_lock_settlement_lane_global();
 PERFORM pg_advisory_xact_lock(hashtextextended('ca-tournament-op:'||p_op_id::text,0));
 SELECT * INTO prior FROM public.ca_operator_tournament_operations WHERE op_id=p_op_id FOR UPDATE;
 IF FOUND THEN
  IF prior.actor_id IS DISTINCT FROM p_actor_id OR prior.tournament_id IS DISTINCT FROM p_tournament_id OR prior.reason IS DISTINCT FROM btrim(p_reason)
  THEN RAISE EXCEPTION 'tournament_operation_conflict' USING ERRCODE='22023'; END IF;
  IF prior.state='completed' THEN
   -- Re-prove the same financial receipt. A stale success record cannot hide
   -- lost refund/custody evidence; no second settlement occurs on replay.
   receipt:=public.fn_ca_tournament_cancellation_receipt(p_tournament_id,NULL);
   IF receipt IS DISTINCT FROM prior.result->'receipt' THEN RAISE EXCEPTION 'cancellation_receipt_changed' USING ERRCODE='P0404'; END IF;
   RETURN prior.result||jsonb_build_object('replayed',true);
  END IF;
 END IF;
 SELECT * INTO event FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'tournament_not_found' USING ERRCODE='P0002'; END IF;
 -- Eligibility is still rechecked by atomic_cancel_tournament, including
 -- committed awards, launch receipts, draw receipts and hand history.
 IF event.started_at IS NOT NULL OR upper(COALESCE(event.status::text,'')) NOT IN('SCHEDULED','REGISTERING','UPCOMING','WAITING','PENDING')
 THEN RAISE EXCEPTION 'started_or_terminal_event_requires_resume_or_settle' USING ERRCODE='55000'; END IF;
 PERFORM 1 FROM public.tournament_players WHERE tournament_id=p_tournament_id ORDER BY user_id,id FOR UPDATE;
 snapshot:=jsonb_build_object('state',event.status,'started_at',event.started_at,
  'prize_pool',event.prize_pool,'bounty_pool',event.bounty_pool,'total_rake',event.total_rake,
  'roster',COALESCE((SELECT md5(jsonb_agg(to_jsonb(tp) ORDER BY tp.id)::text) FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament_id),'empty'));
 amount:=round(COALESCE(event.prize_pool,0)+COALESCE(event.bounty_pool,0)+COALESCE(event.total_rake,0),2);
 IF amount<0 OR amount::text IN('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'tournament_exposure_unverified' USING ERRCODE='P0404'; END IF;
 asset:=CASE WHEN public.fn_poker_diamond_tournament(p_tournament_id) THEN 'diamonds' ELSE 'chips' END;
 IF prior.op_id IS NOT NULL AND (prior.review_snapshot IS DISTINCT FROM snapshot OR prior.amount IS DISTINCT FROM amount OR prior.asset IS DISTINCT FROM asset)
 THEN RAISE EXCEPTION 'tournament_review_changed' USING ERRCODE='55000'; END IF;
 approval:=public.fn_ca_operator_request_approval('tournament_cancel',
  jsonb_build_object('tournament_id',p_tournament_id,'op_id',p_op_id,'reason',btrim(p_reason),'review_snapshot',snapshot),
  p_actor_id,amount,asset,'tournament',p_tournament_id::text,btrim(p_reason),p_op_id::text,p_request_id);
 IF approval->>'ok' IS DISTINCT FROM 'true' THEN
  RETURN jsonb_build_object('ok',false,'refused',true,'reason',COALESCE(approval->>'reason','approval_refused'),'approval',approval,'op_id',p_op_id,'tournament_id',p_tournament_id);
 END IF;
 IF prior.op_id IS NULL THEN
  INSERT INTO public.ca_operator_tournament_operations(op_id,tournament_id,actor_id,reason,review_snapshot,amount,asset,approval_id,state)
  VALUES(p_op_id,p_tournament_id,p_actor_id,btrim(p_reason),snapshot,amount,asset,(approval->>'approval_id')::uuid,'pending');
 END IF;
 IF approval->>'required'='true' THEN
  RETURN jsonb_build_object('ok',true,'pending',true,'op_id',p_op_id,'tournament_id',p_tournament_id,'approval_id',approval->>'approval_id','amount',amount,'asset',asset,'state','pending');
 END IF;
 IF approval->>'status' NOT IN('approved','auto_approved','executed') THEN RAISE EXCEPTION 'approval_status_unverified' USING ERRCODE='P0404'; END IF;
 receipt:=public.atomic_cancel_tournament(p_tournament_id,p_actor_id);
 IF receipt->>'ok' IS DISTINCT FROM 'true' OR receipt->>'fully_settled' IS DISTINCT FROM 'true' OR receipt->>'tournament_id' IS DISTINCT FROM p_tournament_id::text
 THEN RAISE EXCEPTION 'cancellation_receipt_unverified' USING ERRCODE='P0404'; END IF;
 v_result:=jsonb_build_object('ok',true,'pending',false,'op_id',p_op_id,'tournament_id',p_tournament_id,'approval_id',approval->>'approval_id','state','completed','receipt',receipt,'replayed',false);
 marked:=public.fn_ca_operator_mark_executed((approval->>'approval_id')::uuid,v_result,'executed');
 IF marked->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'cancellation_approval_close_refused' USING ERRCODE='P0404'; END IF;
 UPDATE public.ca_operator_tournament_operations SET state='completed',result=v_result,completed_at=transaction_timestamp() WHERE op_id=p_op_id;
 PERFORM public.fn_log_admin_action(p_actor_id,'tournament.cancel_refund','tournament',p_tournament_id::text,
  jsonb_build_object('op_id',p_op_id,'reason',btrim(p_reason),'approval_id',approval->>'approval_id'),snapshot,v_result,NULL,NULL,p_request_id);
 RETURN v_result;
END $$;


ALTER FUNCTION public.fn_ca_operator_cancel_tournament(p_tournament_id uuid, p_op_id uuid, p_reason text, p_actor_id uuid, p_request_id text) OWNER TO postgres;

--
-- TOC entry 7405 (class 1255 OID 19670784)
-- Name: fn_ca_operator_decide_approval(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_decide_approval(p_approval_id uuid, p_decision text, p_decided_by uuid, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row        public.ca_operator_approvals%rowtype;
  v_policy     public.ca_operator_policy%rowtype;
  v_permission text;
  v_decision   text;
  v_alone      boolean := false;
  v_self       boolean := false;
  v_withdraw   boolean := false;
  v_holds      boolean := false;
begin
  v_decision := lower(coalesce(p_decision, ''));
  if v_decision in ('approve', 'approved') then
    v_decision := 'approved';
  elsif v_decision in ('reject', 'rejected') then
    v_decision := 'rejected';
  else
    raise exception 'fn_ca_operator_decide_approval: decision must be approve or reject, got %', p_decision;
  end if;

  select * into v_row from public.ca_operator_approvals where id = p_approval_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'approval_not_found', 'reason', 'approval_not_found', 'approval_id', p_approval_id);
  end if;

  if v_row.status <> 'pending' then
    return jsonb_build_object('ok', false, 'error', 'already_decided', 'reason', 'already_decided', 'status', v_row.status, 'approval_id', p_approval_id);
  end if;

  -- An expired request is closed here rather than left to a sweeper, so
  -- the refusal and the state change cannot disagree.
  if v_row.expires_at is not null and v_row.expires_at <= now() then
    update public.ca_operator_approvals set status = 'expired' where id = p_approval_id;
    return jsonb_build_object('ok', false, 'error', 'expired', 'reason', 'expired', 'status', 'expired', 'approval_id', p_approval_id);
  end if;

  v_permission := case v_row.kind
                    when 'cashout' then 'cashier.write'
                    when 'fleet_policy' then 'fleet.write'
                    when 'sanction' then 'moderation.write'
                    else 'money.write'
                  end;

  -- THE PERMISSION CHECK (20260903140000, review finding M-2). It sits
  -- AFTER the not-found, already-decided and expired branches on purpose:
  -- a decision on a dead row should say the row is dead, not hide that
  -- behind an authorisation error the operator cannot act on. A
  -- withdrawal needs it too: the requester held it to raise the row.
  v_holds := coalesce(public.fn_ca_operator_permissions(p_decided_by) -> 'permissions', '[]'::jsonb)
             ? v_permission;

  if not coalesce(v_holds, false) then
    return jsonb_build_object(
      'ok', false,
      'error', 'permission_denied',
      'reason', 'permission_denied',
      'required_permission', v_permission,
      'status', v_row.status,
      'approval_id', p_approval_id
    );
  end if;

  select * into v_policy from public.ca_operator_policy where id limit 1;

  v_self := p_decided_by is not null and v_row.requested_by is not null and p_decided_by = v_row.requested_by;

  -- A WITHDRAWAL IS NOT A SELF APPROVAL (review finding L-12). The four
  -- eyes rule exists so nobody approves their own money move; it has
  -- nothing to say about the requester cancelling one. A reject by the
  -- requester of their own pending row goes through, ends `rejected`
  -- exactly as a second operator's refusal would, and is filed under its
  -- own action name so the trail can tell the two apart.
  v_withdraw := v_self and v_decision = 'rejected';

  if v_self and not v_withdraw then
    v_alone := not public.fn_ca_operator_has_second_approver(v_row.requested_by, v_permission);
    if not (v_alone and coalesce(v_policy.allow_self_approve_when_alone, true)) then
      return jsonb_build_object(
        'ok', false,
        'error', 'self_approval_refused',
        'reason', 'self_approval_refused',
        'status', v_row.status,
        'approval_id', p_approval_id
      );
    end if;
  end if;

  update public.ca_operator_approvals
    set status = v_decision,
        decided_by = p_decided_by,
        decided_at = now(),
        blocked_reason = case when v_self and v_alone then 'no_second_approver' else blocked_reason end,
        result = coalesce(result, '{}'::jsonb)
                 || jsonb_build_object(
                      'decision_note', p_note,
                      'self_approved_alone', v_self and v_alone,
                      'withdrawn', v_withdraw
                    )
  where id = p_approval_id
  returning * into v_row;

  begin
    perform public.fn_log_admin_action(
      p_admin_user_id := p_decided_by,
      p_action        := case when v_withdraw then 'operator.withdraw_approval' else 'operator.decide_approval' end,
      p_target_type   := coalesce(v_row.target_type, 'operator_approval'),
      p_target_id     := coalesce(v_row.target_id, p_approval_id::text),
      p_details       := jsonb_build_object(
                           'approval_id', p_approval_id,
                           'kind', v_row.kind,
                           'decision', v_decision,
                           'note', p_note,
                           'permission', v_permission,
                           'self_approved_alone', v_self and v_alone,
                           'alone_rule_applied', v_self and v_alone,
                           'withdrawn', v_withdraw
                         ),
      p_before_state  := jsonb_build_object('status', 'pending'),
      p_after_state   := jsonb_build_object('status', v_decision, 'decided_by', p_decided_by),
      p_ip_address    := null,
      p_user_agent    := null,
      p_request_id    := v_row.request_id
    );
  exception when others then
    raise notice 'fn_ca_operator_decide_approval audit failed: %', sqlerrm;
  end;

  return jsonb_build_object(
    'ok', true,
    'approval_id', p_approval_id,
    'status', v_decision,
    'self_approved_alone', v_self and v_alone,
    'withdrawn', v_withdraw
  );
end
$$;


ALTER FUNCTION public.fn_ca_operator_decide_approval(p_approval_id uuid, p_decision text, p_decided_by uuid, p_note text) OWNER TO postgres;

--
-- TOC entry 6190 (class 1255 OID 107910845)
-- Name: fn_ca_operator_decide_chip_request(uuid, text, uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_decide_chip_request(p_request_id uuid, p_action text, p_actor_id uuid, p_expected_op_id uuid, p_expected_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_req public.chip_requests%ROWTYPE;
  v_club_status text;
  v_fund jsonb;
  v_key text;
BEGIN
  IF p_request_id IS NULL OR p_actor_id IS NULL OR p_action NOT IN ('approve', 'deny') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_decision');
  END IF;

  SELECT * INTO v_req
    FROM public.chip_requests
   WHERE id = p_request_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;

  IF v_req.status <> 'pending' THEN
    IF v_req.responded_by = p_actor_id
       AND ((p_action = 'approve' AND v_req.status = 'approved')
         OR (p_action = 'deny' AND v_req.status = 'declined')) THEN
      RETURN jsonb_build_object('ok', true, 'status', v_req.status,
        'request_id', v_req.id, 'op_id', v_req.op_id, 'replayed', true);
    END IF;
    RETURN jsonb_build_object('ok', false, 'reason', 'already_decided',
      'status', v_req.status, 'request_id', v_req.id);
  END IF;

  IF v_req.op_id IS DISTINCT FROM p_expected_op_id
     OR v_req.amount IS DISTINCT FROM p_expected_amount THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'request_changed',
      'status', v_req.status, 'request_id', v_req.id);
  END IF;

  IF v_req.op_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'missing_idempotency_key');
  END IF;

  IF p_action = 'deny' THEN
    UPDATE public.chip_requests
       SET status = 'declined', responded_by = p_actor_id, responded_at = now()
     WHERE id = v_req.id;
    RETURN jsonb_build_object('ok', true, 'status', 'declined',
      'request_id', v_req.id, 'op_id', v_req.op_id, 'replayed', false);
  END IF;

  SELECT c.status INTO v_club_status
    FROM public.clubs c
   WHERE c.id = v_req.club_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'club_not_found',
      'status', v_req.status, 'request_id', v_req.id);
  END IF;
  IF v_club_status IS NULL OR v_club_status NOT IN ('active', 'suspended') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'club_terminal',
      'club_status', v_club_status, 'status', v_req.status,
      'request_id', v_req.id);
  END IF;

  v_key := 'chip-request-fund:' || v_req.op_id::text;
  v_fund := public.fn_ca_fund_club(
    v_req.club_id,
    v_req.amount,
    'Approved Stable Admin chip request ' || v_req.id::text,
    v_key
  );
  IF NOT COALESCE((v_fund ->> 'ok')::boolean, false) THEN
    RAISE EXCEPTION 'chip request funding refused: %', COALESCE(v_fund ->> 'reason', 'unknown');
  END IF;

  UPDATE public.chip_requests
     SET status = 'approved', responded_by = p_actor_id, responded_at = now()
   WHERE id = v_req.id;
  RETURN jsonb_build_object('ok', true, 'status', 'approved',
    'request_id', v_req.id, 'op_id', v_req.op_id,
    'replayed', COALESCE((v_fund ->> 'replayed')::boolean, false),
    'funding', v_fund);
END
$$;


ALTER FUNCTION public.fn_ca_operator_decide_chip_request(p_request_id uuid, p_action text, p_actor_id uuid, p_expected_op_id uuid, p_expected_amount numeric) OWNER TO postgres;

--
-- TOC entry 9065 (class 1255 OID 137555803)
-- Name: fn_ca_operator_export_request(uuid, uuid, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_export_request(p_actor uuid, p_op_id uuid, p_request_id text, p_surface text, p_permission text, p_filters jsonb, p_payload_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE j public.ca_operator_export_artifacts;
BEGIN
 IF p_actor IS NULL OR p_op_id IS NULL OR length(p_surface) NOT BETWEEN 1 AND 80 OR length(p_permission) NOT BETWEEN 1 AND 80 THEN RAISE EXCEPTION 'export_request_invalid'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('operator-export:'||p_op_id::text,0));
 SELECT * INTO j FROM public.ca_operator_export_artifacts WHERE op_id=p_op_id;
 IF FOUND THEN
  IF j.requester_id<>p_actor OR j.payload_sha256<>p_payload_sha256 THEN RAISE EXCEPTION 'export_operation_conflict'; END IF;
  RETURN to_jsonb(j)-'snapshot'-'object_path';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('operator-export-requester:'||p_actor::text,0));
 IF (SELECT count(*) FROM public.ca_operator_export_artifacts WHERE requester_id=p_actor AND state IN ('queued','running') AND expires_at>now())>=5 THEN RAISE EXCEPTION 'export_active_job_limit'; END IF;
 INSERT INTO public.ca_operator_export_artifacts(op_id,requester_id,request_id,surface,permission,filters,payload_sha256)
 VALUES(p_op_id,p_actor,p_request_id,p_surface,p_permission,p_filters,p_payload_sha256) RETURNING * INTO j;
 INSERT INTO public.ca_operator_export_artifact_events(job_id,actor_id,action,details) VALUES(j.id,p_actor,'requested',jsonb_build_object('request_id',p_request_id,'surface',p_surface,'filters',p_filters));
 INSERT INTO public.admin_audit_log(admin_user_id,actor_role,action,target_type,target_id,details,request_id)
 VALUES(p_actor,(SELECT role FROM public.profiles WHERE id=p_actor),'export.requested','operator_export',j.id::text,
 jsonb_build_object('op_id',p_op_id,'surface',p_surface,'filters',p_filters,'permission',p_permission),p_request_id);
 RETURN to_jsonb(j)-'snapshot'-'object_path';
END $$;


ALTER FUNCTION public.fn_ca_operator_export_request(p_actor uuid, p_op_id uuid, p_request_id text, p_surface text, p_permission text, p_filters jsonb, p_payload_sha256 text) OWNER TO postgres;

--
-- TOC entry 8880 (class 1255 OID 137555804)
-- Name: fn_ca_operator_export_transition(uuid, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_export_transition(p_id uuid, p_actor uuid, p_action text, p_lease uuid DEFAULT NULL::uuid, p_details jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE j public.ca_operator_export_artifacts;
BEGIN
 SELECT * INTO j FROM public.ca_operator_export_artifacts WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR j.requester_id IS DISTINCT FROM p_actor THEN RAISE EXCEPTION 'export_job_not_found'; END IF;
 IF p_action='cancel' THEN
  IF j.state<>'cancelled' THEN UPDATE public.ca_operator_export_artifacts SET state='cancelled',lease_id=NULL,lease_until=NULL,error_code=NULL,updated_at=now() WHERE id=j.id; END IF;
 ELSIF p_action='claim' THEN
  IF j.expires_at<=now() THEN RAISE EXCEPTION 'export_expired'; END IF;
  IF j.state NOT IN ('queued','failed','running') OR (j.state='running' AND j.lease_until>now()) THEN RETURN jsonb_build_object('claimed',false); END IF;
  IF p_lease IS NULL THEN RAISE EXCEPTION 'export_lease_required'; END IF;
  UPDATE public.ca_operator_export_artifacts SET state='running',lease_id=p_lease,lease_until=now()+interval '260 seconds',error_code=NULL,updated_at=now() WHERE id=j.id;
 ELSIF p_action='served' THEN
  IF j.state NOT IN ('ready','truncated') OR j.expires_at<=now() THEN RAISE EXCEPTION 'export_not_downloadable'; END IF;
 ELSIF p_action='purged' THEN
  IF j.state<>'cancelled' AND j.expires_at>now() THEN RAISE EXCEPTION 'export_purge_refused'; END IF;
 ELSIF p_action IN ('progress','capture','finish','fail') THEN
  IF j.state<>'running' OR j.lease_id IS DISTINCT FROM p_lease OR j.lease_until<=now() OR j.expires_at<=now() THEN RETURN jsonb_build_object('owned',false); END IF;
  IF p_action='progress' THEN
   UPDATE public.ca_operator_export_artifacts SET progress=(p_details->>'rows')::bigint,total=(p_details->>'total')::bigint,updated_at=now() WHERE id=j.id;
  ELSIF p_action='capture' THEN
   IF j.snapshot IS NOT NULL AND j.snapshot IS DISTINCT FROM p_details THEN RAISE EXCEPTION 'export_snapshot_immutable'; END IF;
   IF octet_length(p_details::text)>16777216 OR jsonb_typeof(p_details->'rows')<>'array' OR jsonb_array_length(p_details->'rows')>20000 THEN RAISE EXCEPTION 'export_capture_invalid'; END IF;
   UPDATE public.ca_operator_export_artifacts SET snapshot=p_details,progress=jsonb_array_length(p_details->'rows'),total=(p_details->>'total')::bigint,complete=(p_details->>'complete')::boolean,updated_at=now() WHERE id=j.id;
  ELSIF p_action='finish' THEN
   IF j.snapshot IS NULL OR p_details->>'object_path'<>j.requester_id::text||'/'||j.op_id::text||'.csv' THEN RAISE EXCEPTION 'export_artifact_invalid'; END IF;
   UPDATE public.ca_operator_export_artifacts SET state=CASE WHEN complete THEN 'ready' ELSE 'truncated' END,
    object_path=p_details->>'object_path',content_sha256=p_details->>'sha256',byte_size=(p_details->>'bytes')::bigint,lease_id=NULL,lease_until=NULL,updated_at=now() WHERE id=j.id;
  ELSE
   UPDATE public.ca_operator_export_artifacts SET state='failed',error_code=left(p_details->>'code',80),lease_id=NULL,lease_until=NULL,updated_at=now() WHERE id=j.id;
  END IF;
 ELSE RAISE EXCEPTION 'export_transition_invalid'; END IF;
 IF p_action<>'progress' THEN INSERT INTO public.ca_operator_export_artifact_events(job_id,actor_id,action,details) VALUES(j.id,p_actor,p_action,CASE WHEN p_action='capture' THEN p_details-'rows' ELSE p_details END); END IF;
 SELECT * INTO j FROM public.ca_operator_export_artifacts WHERE id=p_id;
 RETURN jsonb_build_object('owned',true,'claimed',p_action='claim','job',to_jsonb(j)-'snapshot'-'object_path');
END $$;


ALTER FUNCTION public.fn_ca_operator_export_transition(p_id uuid, p_actor uuid, p_action text, p_lease uuid, p_details jsonb) OWNER TO postgres;

--
-- TOC entry 5842 (class 1255 OID 137566468)
-- Name: fn_ca_operator_finish_cash_close(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_finish_cash_close(p_table_id uuid, p_operation_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'engine_operator_forbidden' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.tables WHERE id=p_table_id AND tournament_id IS NULL FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.ca_operator_table_closes WHERE table_id=p_table_id AND operation_id=p_operation_id AND status='pending') THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM public.table_seats WHERE table_id=p_table_id AND left_at IS NULL)
 OR EXISTS(SELECT 1 FROM public.hand_state_snapshots WHERE table_id=p_table_id AND is_complete=false) THEN RETURN false; END IF;
 UPDATE public.tables SET status='closed' WHERE id=p_table_id;
 UPDATE public.ca_operator_table_closes SET status='closed' WHERE table_id=p_table_id AND operation_id=p_operation_id;
 IF NOT EXISTS(SELECT 1 FROM public.ca_operator_table_closes WHERE operation_id=p_operation_id AND status='pending') THEN
  UPDATE public.ca_engine_operator_commands SET status='completed',updated_at=clock_timestamp() WHERE id=p_operation_id;
 END IF;
 RETURN true;
END $$;


ALTER FUNCTION public.fn_ca_operator_finish_cash_close(p_table_id uuid, p_operation_id uuid) OWNER TO postgres;

--
-- TOC entry 7924 (class 1255 OID 137566473)
-- Name: fn_ca_operator_floor_entry_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_floor_entry_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 -- Seat admission and floor commands share the original transaction edge.
 PERFORM pg_advisory_xact_lock_shared(530093);
 IF NEW.left_at IS NULL AND (TG_OP='INSERT' OR OLD.left_at IS NOT NULL OR NEW.occupancy_id IS DISTINCT FROM OLD.occupancy_id) AND
 (EXISTS(SELECT 1 FROM public.ca_operator_floor_hold h WHERE h.mode='park' AND (NOT EXISTS(SELECT 1 FROM public.ca_launch_operator_scopes m WHERE m.operation_id=h.operation_id) OR EXISTS(SELECT 1 FROM public.ca_launch_operator_scopes m JOIN public.tables st ON st.id=NEW.table_id WHERE m.operation_id=h.operation_id AND st.tournament_id IS NULL AND (st.club_id=ANY(m.club_ids) OR st.union_id=ANY(m.club_ids))))) OR EXISTS(SELECT 1 FROM public.ca_operator_table_closes c WHERE c.table_id=NEW.table_id AND public.fn_ca_launch_cash_close_resumed(c.table_id,c.operation_id) IS NOT TRUE)) THEN
  RAISE EXCEPTION 'OPERATOR_FLOOR_PARKED' USING ERRCODE='55006';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_operator_floor_entry_guard() OWNER TO postgres;

--
-- TOC entry 6215 (class 1255 OID 163196332)
-- Name: fn_ca_operator_floor_hold_lease(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_floor_hold_lease() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- A new hold, or a hold handed to another operation, starts a fresh lease.
  -- A renewal (same operation, later expires_at) passes through untouched.
  IF TG_OP = 'INSERT' OR NEW.operation_id IS DISTINCT FROM OLD.operation_id THEN
    NEW.held_since := clock_timestamp();
    NEW.expires_at := NEW.held_since + public.fn_ca_operator_floor_hold_ttl();
  ELSIF NEW.expires_at IS NULL OR NEW.expires_at > OLD.expires_at + public.fn_ca_operator_floor_hold_ttl() THEN
    -- Nobody extends a lease by more than one TTL in one write.
    NEW.expires_at := OLD.expires_at + public.fn_ca_operator_floor_hold_ttl();
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_operator_floor_hold_lease() OWNER TO postgres;

--
-- TOC entry 8187 (class 1255 OID 163196354)
-- Name: fn_ca_operator_floor_hold_open_alert(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_operator_floor_hold_open_alert(p_operation_id uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT fa.id FROM public.financial_alerts fa
   WHERE fa.source = 'fn_ca_operator_floor_hold_watchdog'
     AND NOT fa.resolved
     AND fa.context->>'operation_id' = p_operation_id::text
   ORDER BY fa.created_at, fa.id LIMIT 1
$$;


