--
-- TOC entry 4338 (class 1255 OID 18775741)
-- Name: fn_ca_orphaned_checks(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_orphaned_checks() RETURNS TABLE(proname text, args text, why text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  WITH sweep AS (
    SELECT COALESCE(
      (SELECT pg_get_functiondef(p.oid)
         FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname='public' AND p.proname='fn_ca_conservation_sweep'
        LIMIT 1), '') AS body
  ),
  candidates AS (
    SELECT p.oid AS oid, p.proname::text AS pn,
           pg_get_function_identity_arguments(p.oid) AS ar
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public'
       AND p.prokind = 'f'
       AND p.prorettype <> 'trigger'::regtype
       AND p.proname ~ '(conservation|_check$|_audit$|_watch$|integrity)'
       AND p.proname NOT LIKE '%selftest%'
       /* A DOOR IS NOT A CHECK. A function taking an actor, an op id, a
          case id or a request id is a write-side RPC with an audit trail -
          open a case, assign it, decide it, sanction. It matches on the
          word "integrity" in its name and on nothing else. */
       AND pg_get_function_identity_arguments(p.oid) !~ '(p_actor|p_op_id|p_case_id|p_request_id|p_value)'
  )
  SELECT c.pn, c.ar,
         'exists but nothing runs it: no cron entry, not called by fn_ca_conservation_sweep, and no exemption reason'
    FROM candidates c, sweep s
   WHERE NOT EXISTS (SELECT 1 FROM cron.job j WHERE j.command LIKE '%' || c.pn || '%')
     /* A CHECK ANOTHER FUNCTION CALLS IS RUN. The weekly cascade calls
        fn_union_settlement_conservation_assert between its rounds; nothing
        in cron names it, and it is not orphaned. */
     AND NOT EXISTS (SELECT 1 FROM pg_proc q JOIN pg_namespace qn ON qn.oid = q.pronamespace
                      WHERE qn.nspname = 'public' AND q.oid <> c.oid
                        AND q.prosrc LIKE '%' || c.pn || '%')
     AND position(c.pn IN s.body) = 0
     AND NOT EXISTS (SELECT 1 FROM public.ca_check_sweep_exemptions e WHERE e.proname = c.pn)
   ORDER BY 1;
$_$;


ALTER FUNCTION public.fn_ca_orphaned_checks() OWNER TO postgres;

--
-- TOC entry 3772 (class 1255 OID 18775742)
-- Name: fn_ca_orphaned_checks_watch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_orphaned_checks_watch() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_n int; v_rows jsonb;
BEGIN
  SELECT count(*), jsonb_agg(jsonb_build_object('fn', o.proname, 'args', o.args))
    INTO v_n, v_rows
    FROM public.fn_ca_orphaned_checks() o;

  IF COALESCE(v_n,0) > 0 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_orphaned_checks_watch', 'unknown', 'warning',
      'orphaned-checks:' || CURRENT_DATE::text,
      0, NULL, NULL, 'ledger', 'pg_proc',
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      v_n || ' integrity check function(s) exist that nothing ever runs. '
        || 'Schedule them, add them to fn_ca_conservation_sweep, or exempt them '
        || 'with a reason in ca_check_sweep_exemptions. A check nobody runs '
        || 'reads as a check finding nothing.',
      false, jsonb_build_object('orphans', v_rows));
  END IF;
  RETURN COALESCE(v_n,0);
END;
$$;


ALTER FUNCTION public.fn_ca_orphaned_checks_watch() OWNER TO postgres;

--
-- TOC entry 8668 (class 1255 OID 28805414)
-- Name: fn_ca_orphaned_running_tournaments(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_orphaned_running_tournaments(p_dwell_minutes integer DEFAULT 10) RETURNS TABLE(tournament_id uuid, tournament_name text, club_id uuid, condition text, lease_instance text, heartbeat_age_seconds numeric, running_minutes numeric, open_seats bigint, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT t.id, t.name, t.club_id,
         CASE WHEN l.tournament_id IS NULL THEN 'no_lease' ELSE 'lease_not_renewed' END,
         l.instance_id,
         round(extract(epoch FROM (now() - l.heartbeat_at))::numeric, 1),
         round((extract(epoch FROM (now() - COALESCE(t.started_at, t.created_at))) / 60.0)::numeric, 1),
         (SELECT count(*) FROM public.table_seats s
            JOIN public.tables tb ON tb.id = s.table_id
           WHERE tb.tournament_id = t.id AND s.left_at IS NULL),
         CASE WHEN l.tournament_id IS NULL THEN
           'RUNNING for '
             || round((extract(epoch FROM (now() - COALESCE(t.started_at, t.created_at))) / 60.0)::numeric, 1)
             || ' minute(s) with NO engine_tournament_leases row at all - no engine '
             || 'has claimed this event, so nobody is dealing it'
         ELSE
           'RUNNING and leased by ' || COALESCE(l.instance_id, '?')
             || ', but the lease has not been renewed for '
             || round((extract(epoch FROM (now() - l.heartbeat_at)) / 60.0)::numeric, 1)
             || ' minute(s). A held lease is not a live engine: the row looks '
             || 'healthy and the heartbeat is dead, which is how five hours of '
             || 'zero hands on 2026-09-12 went unremarked'
         END
    FROM public.tournaments t
    LEFT JOIN public.engine_tournament_leases l ON l.tournament_id = t.id
   WHERE t.status = 'RUNNING'
     AND COALESCE(t.started_at, t.created_at)
           < now() - make_interval(mins => GREATEST(p_dwell_minutes, 1))
     /* A FROZEN ENGINE MINUTE IS NOT A STUCK MINUTE (2026-10-03). A missing
        lease row is a moment between a manager stop and its successor's claim
        unless nobody has dealt the event either: no_lease needs no hand
        committed on any of its tables for the dwell in LIVE engine minutes,
        measured to clock_timestamp() because the sweep's now() is its start.
        2026-10-02 20:52: both events named were dealing hands that minute. */
     AND ((l.tournament_id IS NULL
           AND public.fn_ca_engine_live_minutes(
                 GREATEST(COALESCE(t.started_at, t.created_at),
                          (SELECT max(h.committed_at)
                             FROM public.tables tb
                             CROSS JOIN LATERAL (
                               SELECT hc.committed_at
                                 FROM public.hand_atomic_commits hc
                                WHERE hc.table_id = tb.id
                                ORDER BY hc.hand_number DESC
                                LIMIT 1) h
                            WHERE tb.tournament_id = t.id)),
                 clock_timestamp()) >= GREATEST(p_dwell_minutes, 1))
          OR (l.tournament_id IS NOT NULL AND l.heartbeat_at IS NULL)
          OR l.heartbeat_at < now() - make_interval(mins => GREATEST(p_dwell_minutes, 1)))
   ORDER BY 6 DESC NULLS FIRST
$$;


