--
-- TOC entry 3757 (class 1255 OID 92033305)
-- Name: fn_ca_owner_route_reader_silence(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_owner_route_reader_silence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  -- The newest timestamp any reader wrote into an investigation before this
  -- column existed (measured 2026-10-03). Never "now": an unread inbox must
  -- not look freshly read because the stamp is new.
  c_measured_last_read CONSTANT timestamptz := '2026-10-01 20:02:05+00';
  c_silence CONSTANT interval := interval '12 hours';
  c_title CONSTANT text := 'Production Alerts Has Stopped Reading';
  v_last timestamptz;
  v_waiting integer;
BEGIN
  SELECT GREATEST(c_measured_last_read, max(e.investigation_touched_at))
    INTO v_last
    FROM public.operational_alert_events e
   WHERE e.investigation_touched_at IS NOT NULL;
  v_last := COALESCE(v_last, c_measured_last_read);

  IF v_last > now() - c_silence THEN
    RETURN NULL;  -- somebody is reading; the route works as designed
  END IF;

  -- One page per silence. A later critical while the reader is still silent
  -- adds to the count the next reader sees, not to the owner's phone.
  IF EXISTS (SELECT 1 FROM public.notifications n
              WHERE n.user_id = NEW.recipient_user_id
                AND n.type = 'system'
                AND n.title = c_title
                AND n.created_at > v_last) THEN
    RETURN NULL;
  END IF;

  SELECT count(*) INTO v_waiting
    FROM public.operational_notification_destinations d
   WHERE d.recipient_user_id = NEW.recipient_user_id
     AND d.captured_at > v_last;

  PERFORM public.fn_raise_notification(
    NEW.recipient_user_id, 'system', c_title,
    format('Nothing in the Production Alerts inbox has been read since %s UTC, and %s owner alert(s) have arrived since. The latest: %s',
           to_char(v_last AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI'), v_waiting,
           left(COALESCE(NEW.original_notification->>'title', 'an owner alert'), 200)),
    '/hub/club-arena/financial-incidents',
    jsonb_build_object('source', 'owner-route-reader-silence',
                       'last_read_at', v_last,
                       'waiting', v_waiting,
                       'notification_id', NEW.notification_id));
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  -- The capture of the alert itself must never fail because of this page.
  RAISE WARNING 'fn_ca_owner_route_reader_silence failed for %: %', NEW.notification_id, SQLERRM;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_owner_route_reader_silence() OWNER TO postgres;

--
-- TOC entry 6360 (class 1255 OID 25717530)
-- Name: fn_ca_paid_spin_launch_entitlements(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_paid_spin_launch_entitlements(p_tournament_id uuid, p_user_ids uuid[]) RETURNS TABLE(user_id uuid, gross numeric, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET row_security TO 'off'
    SET statement_timeout TO '5s'
    AS $$
DECLARE
  v_actor text := NULLIF(
    pg_catalog.current_setting('app.smarter_data_actor', true),
    ''
  );
  v_context_tournament text := NULLIF(
    pg_catalog.current_setting('app.smarter_tournament_id', true),
    ''
  );
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role'
     OR v_actor IS DISTINCT FROM 'tournament-manager'
     OR v_context_tournament IS DISTINCT FROM p_tournament_id::text THEN
    RAISE EXCEPTION
      'paid Spin entitlement evidence requires the current tournament manager authority'
      USING ERRCODE = '28000';
  END IF;

  IF p_tournament_id IS NULL
     OR p_user_ids IS NULL
     OR pg_catalog.cardinality(p_user_ids) NOT BETWEEN 1 AND 3
     OR pg_catalog.array_position(p_user_ids, NULL::uuid) IS NOT NULL THEN
    RAISE EXCEPTION 'invalid paid Spin entitlement evidence identity'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT e.user_id, e.gross, e.created_at
    FROM public.tournament_refund_entitlements e
   WHERE e.tournament_id = p_tournament_id
     AND e.entitlement_kind = 'wallet_charge'
     AND e.charge_category = 'tournament_buyin'
     AND e.user_id = ANY(p_user_ids)
   ORDER BY e.user_id, e.created_at, e.id;
END;
$$;


