--
-- TOC entry 5964 (class 1255 OID 162957726)
-- Name: fn_ca_pay_closed_target_ticket_in_cash(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_pay_closed_target_ticket_in_cash(p_ticket_id uuid, p_source text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tk public.tournament_tickets%ROWTYPE;
  v_award public.tournament_satellite_awards%ROWTYPE;
  v_key text;
  v_source text := lower(btrim(COALESCE(p_source,'')));
  v_context jsonb;
  v_setting text;
  v_before numeric;
  v_after numeric;
  v_issue_leg uuid;
  v_ledger_id uuid;
  v_tx_id uuid;
  v_rows integer;
BEGIN
  /* A SATELLITE SEAT IS SEAT OR CASH (2026-10-12). Every direct satellite
     award is a seat_or_cash entitlement. fn_ca_settle_satellite_cohort pays a
     winner whose target is closed in cash at the finish; a winner at the
     four-table cap while the target is still open is held a noncash ticket
     for that one target instead. When that target closes before the ticket is
     used, the ticket can never admit anybody again, so its cash leg applies:
     the escrowed value goes to the holder's wallet in the ticket's own club,
     once, keyed by the ticket. Horses are players and are paid exactly so. */
  IF p_ticket_id IS NULL OR v_source='' THEN
    RAISE EXCEPTION 'closed target ticket cash needs a ticket and a source'
      USING ERRCODE='22004';
  END IF;
  SELECT * INTO v_tk FROM public.tournament_tickets tk
   WHERE tk.id=p_ticket_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_found',
      'ticket_id',p_ticket_id);
  END IF;
  v_key:='ticket:'||v_tk.id::text||':closed-target-cash';

  IF v_tk.status='redeemed' THEN
    SELECT l.id INTO v_ledger_id
      FROM public.chip_ledger_idem i JOIN public.chip_ledger l ON l.id=i.leg_id
     WHERE i.idempotency_key=v_key;
    IF v_ledger_id IS NOT NULL THEN
      RETURN jsonb_build_object('ok',true,'replayed',true,
        'ticket_id',v_tk.id,'ledger_id',v_ledger_id,'amount',v_tk.value);
    END IF;
    RETURN jsonb_build_object('ok',false,'reason','ticket_already_used',
      'ticket_id',v_tk.id);
  END IF;
  IF v_tk.status IS DISTINCT FROM 'issued' THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_issued',
      'ticket_id',v_tk.id);
  END IF;
  IF v_tk.redemption_mode IS DISTINCT FROM 'tournament_entry_only'
     OR v_tk.source_satellite_award_place IS NULL
     OR v_tk.source_refund_entitlement_id IS NOT NULL
     OR v_tk.source_tournament_id IS NULL
     OR v_tk.source_satellite_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason',
      'not_a_direct_satellite_ticket','ticket_id',v_tk.id);
  END IF;
  IF NOT public.fn_ca_satellite_ticket_target_is_closed(
           v_tk.source_tournament_id) THEN
    RETURN jsonb_build_object('ok',false,'reason','target_still_admits',
      'ticket_id',v_tk.id);
  END IF;

  -- The value being paid is exactly what the satellite escrowed for this
  -- award: the immutable award row and its one issue leg.
  SELECT * INTO v_award FROM public.tournament_satellite_awards a
   WHERE a.tournament_id=v_tk.source_satellite_id
     AND a.place=v_tk.source_satellite_award_place
     AND a.ticket_id=v_tk.id AND a.delivery_kind='ticket'
     AND a.user_id=v_tk.holder_id AND a.amount=v_tk.value;
  IF v_award.tournament_id IS NULL THEN
    RAISE EXCEPTION 'satellite ticket % has no exact award row',v_tk.id
      USING ERRCODE='P0404';
  END IF;
  SELECT l.id INTO v_issue_leg
    FROM public.chip_ledger_idem i JOIN public.chip_ledger l ON l.id=i.leg_id
   WHERE i.idempotency_key=v_award.idempotency_key||':ticket_escrow'
     AND l.from_type='prize_liability'
     AND l.from_entity_id=v_tk.source_satellite_id
     AND l.to_type='escrow' AND l.to_entity_id=v_tk.id
     AND l.amount=v_tk.value AND l.club_id=v_tk.club_id
     AND l.category='ticket_issue';
  IF v_issue_leg IS NULL THEN
    RAISE EXCEPTION 'satellite ticket % has no exact escrow issue leg',v_tk.id
      USING ERRCODE='P0404';
  END IF;

  SELECT m.chip_balance INTO v_before FROM public.club_members m
   WHERE m.club_id=v_tk.club_id AND m.user_id=v_tk.holder_id
     AND COALESCE(m.status,'active') IN ('active','approved')
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason',
      'holder_not_a_member_of_ticket_club','ticket_id',v_tk.id);
  END IF;
  v_before:=COALESCE(v_before,0);

  SELECT jsonb_object_agg(k,COALESCE(current_setting(k,true),''))
    INTO v_context
    FROM unnest(ARRAY[
      'app.ledger_category','app.ledger_counterparty',
      'app.ledger_counterparty_entity','app.ledger_counterparty_label',
      'app.ledger_tournament','app.ledger_idempotency_key',
      'app.ledger_autoskip_club_members',
      'app.ca_closed_target_ticket_cash']) settings(k);

  -- This door writes its own named leg, so the anonymous journal stands down.
  PERFORM set_config('app.ledger_tournament','',true);
  PERFORM public.fn_ca_declare_ledger(
    'ticket_redeem','escrow',v_tk.id,NULL,v_key,ARRAY['club_members']);
  INSERT INTO public.chip_ledger(
    performed_by,from_type,from_entity_id,from_label,
    to_type,to_entity_id,to_label,amount,category,club_id,tournament_id,
    idempotency_key,settlement_id,actor_service,description,metadata,
    pre_from_balance,post_from_balance,pre_to_balance,post_to_balance)
  VALUES(
    COALESCE(auth.uid(),'2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
    'escrow',v_tk.id,'satellite tournament entry ticket',
    'player_wallet',v_tk.holder_id,'player wallet',
    v_tk.value,'ticket_redeem',v_tk.club_id,NULL,
    v_key,'ticket-cash:'||v_tk.id::text,
    'fn_ca_pay_closed_target_ticket_in_cash',
    'Satellite seat paid in cash because its target no longer takes entries',
    jsonb_build_object(
      'kind','closed_target_ticket_cash','ticket_id',v_tk.id,
      'holder_id',v_tk.holder_id,
      'source_satellite_id',v_tk.source_satellite_id,
      'source_tournament_id',v_tk.source_tournament_id,
      'award_place',v_tk.source_satellite_award_place,
      'award_idempotency_key',v_award.idempotency_key,
      'issue_ledger_id',v_issue_leg,'source',v_source),
    v_tk.value,0,v_before,round(v_before+v_tk.value,2))
  RETURNING id INTO v_ledger_id;

  UPDATE public.club_members
     SET chip_balance=round(COALESCE(chip_balance,0)+v_tk.value,2),
         updated_at=now()
   WHERE club_id=v_tk.club_id AND user_id=v_tk.holder_id
     AND COALESCE(status,'active') IN ('active','approved')
   RETURNING chip_balance INTO v_after;
  IF v_after IS DISTINCT FROM round(v_before+v_tk.value,2) THEN
    RAISE EXCEPTION 'ticket % cash credit did not land exactly',v_tk.id
      USING ERRCODE='55000';
  END IF;

  PERFORM set_config('app.ca_closed_target_ticket_cash',v_tk.id::text,true);
  UPDATE public.tournament_tickets
     SET status='redeemed',redeemed_at=transaction_timestamp()
   WHERE id=v_tk.id AND status='issued';
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'ticket % changed while it was paid in cash',v_tk.id
      USING ERRCODE='55000';
  END IF;

  INSERT INTO public.chip_transactions(
    club_id,from_user_id,to_user_id,amount,transaction_type,notes,
    balance_after,metadata)
  VALUES(
    v_tk.club_id,NULL,v_tk.holder_id,v_tk.value,'tournament_ticket_redeem',
    'Satellite Seat Paid In Cash: Target Entry Closed',v_after,
    jsonb_build_object(
      'ticket_id',v_tk.id,'issuer_id',v_tk.issued_by,
      'holder_id',v_tk.holder_id,'escrow_action','release_to_holder',
      'reason','target_entry_closed',
      'source_tournament_id',v_tk.source_tournament_id,
      'source_satellite_id',v_tk.source_satellite_id,
      'source_award_place',v_tk.source_satellite_award_place,
      'ledger_id',v_ledger_id,'idempotency_key',v_key,
      'holder_balance_after',v_after))
  RETURNING id INTO v_tx_id;
  INSERT INTO public.wallet_transactions(
    user_id,wallet_type,type,amount,category,description,balance_after)
  VALUES(
    v_tk.holder_id,'PLAYER','credit',v_tk.value,'transfer',
    'Satellite Seat Paid In Cash: Target Entry Closed',v_after);

  FOR v_setting IN SELECT jsonb_object_keys(v_context) LOOP
    PERFORM set_config(v_setting,v_context->>v_setting,true);
  END LOOP;

  RETURN jsonb_build_object(
    'ok',true,'replayed',false,'ticket_id',v_tk.id,
    'holder_id',v_tk.holder_id,'club_id',v_tk.club_id,'amount',v_tk.value,
    'target_id',v_tk.source_tournament_id,
    'satellite_id',v_tk.source_satellite_id,
    'ledger_id',v_ledger_id,'transaction_id',v_tx_id,
    'balance_before',v_before,'balance_after',v_after);
END;
$$;


ALTER FUNCTION public.fn_ca_pay_closed_target_ticket_in_cash(p_ticket_id uuid, p_source text) OWNER TO postgres;

--
-- TOC entry 5323 (class 1255 OID 162957729)
-- Name: fn_ca_pay_closed_target_tickets_in_cash(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_pay_closed_target_tickets_in_cash(p_target_id uuid, p_source text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
  v_result jsonb;
  v_paid integer:=0;
  v_amount numeric:=0;
  v_unpaid jsonb:='[]'::jsonb;
BEGIN
  /* Runs in the transaction that closes the target, so a ticket that can no
     longer be used is paid at the moment it stops being usable. One ticket
     the door cannot pay never stops the target from closing: that ticket is
     named on a critical alert, in this same transaction, with the reason. */
  IF p_target_id IS NULL
     OR NOT public.fn_ca_satellite_ticket_target_is_closed(p_target_id) THEN
    RETURN jsonb_build_object('ok',true,'paid',0,'amount',0);
  END IF;
  FOR v_id IN
    SELECT tk.id FROM public.tournament_tickets tk
     WHERE tk.source_tournament_id=p_target_id
       AND tk.status='issued'
       AND tk.redemption_mode='tournament_entry_only'
       AND tk.source_satellite_award_place IS NOT NULL
       AND tk.source_refund_entitlement_id IS NULL
     ORDER BY tk.id
  LOOP
    BEGIN
      v_result:=public.fn_ca_pay_closed_target_ticket_in_cash(v_id,p_source);
    EXCEPTION WHEN OTHERS THEN
      v_result:=jsonb_build_object('ok',false,'reason','refused',
        'sqlstate',SQLSTATE,'message',SQLERRM,'ticket_id',v_id);
    END;
    IF COALESCE((v_result->>'ok')::boolean,false) THEN
      IF NOT COALESCE((v_result->>'replayed')::boolean,false) THEN
        v_paid:=v_paid+1;
        v_amount:=round(v_amount+(v_result->>'amount')::numeric,2);
      END IF;
    ELSE
      v_unpaid:=v_unpaid||jsonb_build_array(v_result);
      INSERT INTO public.financial_alerts(severity,source,message,context)
      VALUES('critical','fn_ca_pay_closed_target_tickets_in_cash',
        'A Satellite Ticket For A Closed Target Could Not Be Paid In Cash',
        jsonb_build_object('target_id',p_target_id,'ticket_id',v_id,
          'result',v_result));
    END IF;
  END LOOP;
  RETURN jsonb_build_object('ok',jsonb_array_length(v_unpaid)=0,
    'paid',v_paid,'amount',v_amount,'unpaid',v_unpaid);
END;
$$;


ALTER FUNCTION public.fn_ca_pay_closed_target_tickets_in_cash(p_target_id uuid, p_source text) OWNER TO postgres;

--
-- TOC entry 9293 (class 1255 OID 217357278)
-- Name: fn_ca_pay_tournament_finishers_now(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_pay_tournament_finishers_now(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t record;
  v_live integer;
  v_field integer;
  v_max_place integer;
  v_bubble_place integer;
  v_bubble_amount numeric := 0;
  v_rows jsonb;
  v_finalized boolean;
  v_ladder jsonb;
  v_row jsonb;
  v_bad_paid integer;
  v_mismatch integer;
  v_normalized integer := 0;
  v_paid jsonb := '[]'::jsonb;
  v_amount numeric;
  v_user uuid;
  v_place integer;
  v_result jsonb;
  v_ob public.tournament_obligations%ROWTYPE;
BEGIN
  IF p_tournament_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'skipped','no_tournament');
  END IF;

  -- The same rolling lane every place/bounty authority enters, then the row.
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  SELECT t.id, t.status, t.variant, t.tournament_type, t.satellite_target_id,
         t.satellite_target, t.prize_pool, t.prize_pool_finalized,
         t.bubble_protection, t.buy_in_amount
    INTO v_t FROM public.tournaments t
   WHERE t.id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'skipped','tournament_not_found');
  END IF;

  -- A live event whose pool is locked. Until late registration closes the
  -- field can still grow, so no place is final and none is paid; the
  -- finalization itself calls this again.
  IF upper(COALESCE(v_t.status,'')) <> 'RUNNING' THEN
    RETURN jsonb_build_object('ok',true,'skipped','not_running');
  END IF;
  v_finalized := COALESCE(v_t.prize_pool_finalized,false);
  IF NOT v_finalized THEN
    RETURN jsonb_build_object('ok',true,'skipped','pool_not_finalized');
  END IF;
  -- Satellites award seats to survivors; a deal has its own authority.
  IF lower(COALESCE(v_t.variant,'')) = 'satellite'
     OR upper(COALESCE(v_t.tournament_type,'')) = 'SATELLITE'
     OR v_t.satellite_target_id IS NOT NULL
     OR v_t.satellite_target IS NOT NULL THEN
    RETURN jsonb_build_object('ok',true,'skipped','satellite');
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_payouts p
              WHERE p.tournament_id = p_tournament_id
                AND lower(COALESCE(p.source,'')) = 'final_table_deal')
     OR EXISTS (SELECT 1 FROM public.tournament_obligations o
                 WHERE o.tournament_id = p_tournament_id
                   AND o.kind = 'final_table_deal')
     OR EXISTS (SELECT 1 FROM public.tournament_place_settlement_batches b
                 WHERE b.tournament_id = p_tournament_id) THEN
    RETURN jsonb_build_object('ok',true,'skipped','terminal_authority_owns_it');
  END IF;

  -- A bust that has happened but is not recorded yet (zero chips, still
  -- 'playing') may finish below someone already eliminated. Pay nobody until
  -- the door has recorded it; its own commit calls this again.
  IF EXISTS (SELECT 1 FROM public.tournament_players tp
              WHERE tp.tournament_id = p_tournament_id
                AND tp.status::text = 'playing'
                AND COALESCE(tp.chips,0) <= 0)
     OR EXISTS (SELECT 1 FROM public.tournament_players tp
                 WHERE tp.tournament_id = p_tournament_id
                   AND tp.status::text = 'registered') THEN
    RETURN jsonb_build_object('ok',true,'skipped','bust_not_recorded_yet');
  END IF;

  SELECT count(*) FILTER (WHERE tp.status::text IN ('playing','winner')),
         count(*)
    INTO v_live, v_field
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;
  IF v_live < 1 THEN
    -- The last survivor has crossed through 'eliminated'; the terminal
    -- settlement names the winner and pays the rest in the same transaction.
    RETURN jsonb_build_object('ok',true,'skipped','no_live_survivor');
  END IF;

  v_ladder := '{}'::jsonb;
  IF v_finalized THEN
    SELECT COALESCE(jsonb_object_agg(a.place::text, a.amount), '{}'::jsonb),
           max(a.place)
      INTO v_ladder, v_max_place
      FROM public.fn_ca_tournament_place_amounts(p_tournament_id) a;
    IF v_max_place IS NULL THEN
      RETURN jsonb_build_object('ok',true,'skipped','no_ladder');
    END IF;
    IF COALESCE(v_t.bubble_protection,false) AND v_field > v_max_place THEN
      v_bubble_place := v_max_place + 1;
      v_bubble_amount := round(v_t.buy_in_amount, 2);
    END IF;
  END IF;

  /* The finishing place of each eliminated player, by the rule the terminal
     settlement ranks with (fn_settle_tournament_places, 2026-09-11): busts
     are ordered by when they happened - the accepted hand's commit time plus
     one microsecond per smaller hand-start stack in that hand - then
     elimination_sequence, then id. While the event is live the place is the
     live field plus that rank, which is exactly the terminal's place once the
     field is down to its winner. */
  WITH busts AS (
    SELECT tp.id, tp.user_id, tp.position, tp.elimination_sequence,
           COALESCE((
             SELECT COALESCE(a.committed_at,
                             (SELECT min(g.created_at)
                                FROM public.tournament_knockout_candidates g
                               WHERE g.tournament_id = c.tournament_id
                                 AND g.table_id = c.table_id
                                 AND g.hand_number = c.hand_number
                                 AND g.hand_id = c.hand_id))
                    + (SELECT count(*)
                         FROM public.tournament_knockout_candidates s
                        WHERE s.tournament_id = c.tournament_id
                          AND s.table_id = c.table_id
                          AND s.hand_number = c.hand_number
                          AND s.hand_id = c.hand_id
                          AND (s.stack_before, s.eliminated_user_id)
                              < (c.stack_before, c.eliminated_user_id))::integer
                      * interval '1 microsecond'
               FROM (SELECT k.tournament_id, k.table_id, k.hand_number,
                            k.hand_id, k.stack_before, k.eliminated_user_id
                       FROM public.tournament_knockout_candidates k
                      WHERE k.tournament_id = tp.tournament_id
                        AND k.eliminated_user_id = tp.user_id
                        AND k.state = 'eliminated'
                      ORDER BY k.hand_number DESC, k.id DESC
                      LIMIT 1) c
               LEFT JOIN public.hand_atomic_commits a
                 ON a.table_id = c.table_id
                AND a.hand_number = c.hand_number
                AND a.hand_id = c.hand_id
           ), tp.eliminated_at) AS bust_at
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.status::text = 'eliminated'
  ),
  ranked AS (
    SELECT b.id, b.user_id, b.position, b.bust_at,
           v_live + row_number() OVER (
             ORDER BY b.bust_at DESC, b.elimination_sequence DESC, b.id ASC
           )::integer AS place
      FROM busts b
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id',r.id,'user_id',r.user_id,'position',r.position,'place',r.place,
           'unwitnessed',r.bust_at IS NULL,
           'evidence',(
             EXISTS (SELECT 1 FROM public.tournament_obligations o
                      WHERE o.tournament_id = p_tournament_id
                        AND o.kind IN ('place','bubble_protection')
                        AND o.user_id = r.user_id AND o.amount_paid > 0)
             OR EXISTS (SELECT 1 FROM public.tournament_payouts p
                         WHERE p.tournament_id = p_tournament_id
                           AND p.user_id = r.user_id
                           AND COALESCE(p.source,'') NOT IN
                             ('bounty','own_bounty','mystery_bounty',
                              'mystery_bounty_residual','bounty_residual',
                              'satellite_seat'))))
           ORDER BY r.place), '[]'::jsonb)
    INTO v_rows
    FROM ranked r;

  IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_rows) e
              WHERE (e->>'unwitnessed')::boolean) THEN
    RETURN jsonb_build_object('ok',true,'skipped','bust_time_unwitnessed');
  END IF;

  -- A paid place is never relabelled. If one no longer matches the rule,
  -- leave everything to the terminal settlement, which will say so.
  SELECT count(*) INTO v_bad_paid
    FROM jsonb_array_elements(v_rows) e
   WHERE (e->>'evidence')::boolean
     AND (e->>'position')::integer IS DISTINCT FROM (e->>'place')::integer;
  IF v_bad_paid > 0 THEN
    RETURN jsonb_build_object('ok',false,'skipped','paid_place_out_of_order',
                              'rows',v_bad_paid);
  END IF;

  /* Unpaid standings recorded against a smaller field (a bust during late
     registration) or in a different same-hand order are restamped with their
     true place now, exactly as the terminal settlement would restamp them,
     so the place paid now is the place they finish in. Clear first, then
     stamp, so the collision guard never sees two players on one place. */
  SELECT count(*) INTO v_mismatch
    FROM jsonb_array_elements(v_rows) e
   WHERE (e->>'position')::integer IS DISTINCT FROM (e->>'place')::integer;
  IF v_mismatch > 0 THEN
    UPDATE public.tournament_players tp
       SET position = NULL
      FROM jsonb_array_elements(v_rows) e
     WHERE tp.id = (e->>'id')::uuid
       AND tp.tournament_id = p_tournament_id
       AND (e->>'position')::integer IS DISTINCT FROM (e->>'place')::integer;
    UPDATE public.tournament_players tp
       SET position = (e->>'place')::integer
      FROM jsonb_array_elements(v_rows) e
     WHERE tp.id = (e->>'id')::uuid
       AND tp.tournament_id = p_tournament_id
       AND (e->>'position')::integer IS DISTINCT FROM (e->>'place')::integer;
    GET DIAGNOSTICS v_normalized = ROW_COUNT;
    IF v_normalized <> v_mismatch THEN
      RAISE EXCEPTION 'tournament % restamped % of % standings',
        p_tournament_id, v_normalized, v_mismatch USING ERRCODE = 'P0404';
    END IF;
  END IF;

  -- tournament_players.prize is the presentation cache of each standing. The
  -- engine stamps it from its provisional place; restate it from the locked
  -- ladder at the true place so a player sees what was actually paid.
  UPDATE public.tournament_players tp
     SET prize = CASE
           WHEN v_bubble_place IS NOT NULL AND (e->>'place')::integer = v_bubble_place
             THEN v_bubble_amount
           ELSE COALESCE((v_ladder->>(e->>'place'))::numeric, 0)
         END
    FROM jsonb_array_elements(v_rows) e
   WHERE tp.id = (e->>'id')::uuid
     AND tp.tournament_id = p_tournament_id
     AND tp.prize IS DISTINCT FROM CASE
           WHEN v_bubble_place IS NOT NULL AND (e->>'place')::integer = v_bubble_place
             THEN v_bubble_amount
           ELSE COALESCE((v_ladder->>(e->>'place'))::numeric, 0)
         END;

  /* THE PLACE IS TRUE FROM THE FIRST BUST AFTER THE FIELD IS FIXED
     (2026-10-21). This used to stop before the restamp until somebody was in
     the money, so every bust between late registration closing and the
     bubble kept the engine's provisional place (measured: a 222-entry event
     showed places 2 to 200 with 25 players left). The standings are now
     restamped on every bust once the pool is finalized, in the money or not. */
  -- Every eliminated finisher sits strictly below the live field. If the best
  -- of them is still outside the money there is nothing to pay yet.
  IF v_live + 1 > COALESCE(v_bubble_place, v_max_place) THEN
    RETURN jsonb_build_object('ok',true,'skipped','nobody_in_the_money_yet',
                              'restamped',v_normalized,'live',v_live,'paid_places',v_max_place);
  END IF;

  -- Pay every finisher in the money who is not fully paid, through the same
  -- idempotent obligation door the terminal settlement uses.
  FOR v_row IN
    SELECT e FROM jsonb_array_elements(v_rows) e
     WHERE (e->>'place')::integer <= COALESCE(v_bubble_place, v_max_place)
     ORDER BY (e->>'place')::integer DESC
  LOOP
    v_place := (v_row->>'place')::integer;
    v_user := (v_row->>'user_id')::uuid;
    IF v_bubble_place IS NOT NULL AND v_place = v_bubble_place THEN
      IF v_bubble_amount > 0 AND NOT EXISTS (
        SELECT 1 FROM public.tournament_obligations o
         WHERE o.tournament_id = p_tournament_id
           AND o.kind = 'bubble_protection'
           AND o.user_id = v_user
           AND o.amount_paid >= o.amount_owed AND o.amount_owed = v_bubble_amount) THEN
        v_result := public.fn_ca_settle_tournament_bubble_raw(
          p_tournament_id, v_user, v_bubble_amount);
        v_paid := v_paid || jsonb_build_object('place',v_place,'user_id',v_user,
          'amount',v_bubble_amount,'kind','bubble_protection');
      END IF;
      CONTINUE;
    END IF;
    v_amount := (v_ladder->>v_place::text)::numeric;
    IF v_amount IS NULL OR v_amount <= 0 THEN
      CONTINUE;
    END IF;
    v_ob := NULL;
    SELECT * INTO v_ob FROM public.tournament_obligations o
     WHERE o.tournament_id = p_tournament_id AND o.kind = 'place' AND o.place = v_place;
    IF v_ob.id IS NOT NULL AND v_ob.user_id = v_user
       AND v_ob.amount_owed = v_amount AND v_ob.amount_paid >= v_amount THEN
      CONTINUE;
    END IF;
    v_result := public.fn_ca_settle_tournament_place_raw(
      p_tournament_id, v_place, v_user, v_amount);
    v_paid := v_paid || jsonb_build_object('place',v_place,'user_id',v_user,
      'amount',v_amount,'kind','place');
  END LOOP;

  RETURN jsonb_build_object('ok',true,'paid',v_paid,'restamped',v_normalized,
                            'live',v_live,'paid_places',v_max_place);
END;
$$;


ALTER FUNCTION public.fn_ca_pay_tournament_finishers_now(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 8021 (class 1255 OID 25366563)
-- Name: fn_ca_payout_rows_without_money(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_payout_rows_without_money(p_days integer DEFAULT 30) RETURNS TABLE(tournament_id uuid, tournament_name text, player_id uuid, finish_position integer, source text, amount numeric, paid_at timestamp with time zone, idempotency_key text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $$
#variable_conflict use_column
DECLARE
  v_since timestamptz := now() - make_interval(days => GREATEST(COALESCE(p_days, 30), 1));
BEGIN
  /* THE WINDOW IS A VALUE WHEN THE QUERY IS PLANNED (2026-10-22). As a
     LANGUAGE sql SECURITY DEFINER function the window arrived as an unknown
     parameter, so the three days the conservation sweep asks for were read as
     every payout ever paid: a sequential scan of tournament_payouts (876k
     rows) and of wallet_credit_idempotency for its earliest row, 13-55 s.
     Planned with its value, the window reads idx_tournament_payouts_paid_money
     and the earliest row reads idx_wallet_credit_idempotency_created. Same
     query, same rows, same order. */
  RETURN QUERY
    SELECT p.tournament_id, t.name, p.user_id, p.position, p.source, p.amount, p.paid_at, p.idempotency_key
      FROM public.tournament_payouts p
      JOIN public.tournaments t ON t.id = p.tournament_id
     WHERE p.source IN ('structure', 'reconcile', 'overlay_backpay', 'spin_backpay',
                        'hu_shortfall', 'late_reg_adjustment', 'final_table_deal', 'bubble_protection')
       AND p.user_id IS NOT NULL
       AND p.amount > 0
       AND p.paid_at > v_since
       AND p.paid_at > (SELECT min(w0.created_at) FROM public.wallet_credit_idempotency w0)
       AND (p.idempotency_key IS NULL
            OR NOT EXISTS (SELECT 1 FROM public.wallet_credit_idempotency w
                            WHERE w.key = p.idempotency_key))
     ORDER BY p.paid_at DESC;
END
$$;


ALTER FUNCTION public.fn_ca_payout_rows_without_money(p_days integer) OWNER TO postgres;

--
-- TOC entry 6301 (class 1255 OID 218010742)
-- Name: fn_ca_payout_structure(integer, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_payout_structure(p_entrants integer, p_percent numeric) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_places int;
  v_pct    numeric;
  v_out    jsonb;
BEGIN
  v_pct := CASE WHEN p_percent > 0 AND p_percent <= 100 THEN p_percent ELSE 12.5 END;
  IF COALESCE(p_entrants,0) <= 0 THEN
    RETURN '[]'::jsonb;
  END IF;
  -- at least one place, never more places than players, rounded up
  v_places := GREATEST(1, LEAST(p_entrants, ceil(p_entrants * v_pct / 100.0)::int));

  WITH w AS (
    SELECT i AS place, 1.0 / power(i, 0.8) AS weight
      FROM generate_series(1, v_places) i
  ), n AS (
    SELECT place, 100.0 * weight / SUM(weight) OVER () AS exact FROM w
  ), f AS (
    SELECT place, floor(exact * 100) / 100 AS floored,
           (exact * 100) - floor(exact * 100) AS frac
      FROM n
  ), r AS (
    SELECT place, floored,
           row_number() OVER (ORDER BY frac DESC, place ASC) AS rk,
           round((100.0 - SUM(floored) OVER ()) * 100)::int AS cents_left
      FROM f
  )
  SELECT jsonb_agg(jsonb_build_object('place', place,
           'percentage', floored + CASE WHEN rk <= cents_left THEN 0.01 ELSE 0 END)
           ORDER BY place)
    INTO v_out FROM r;
  RETURN COALESCE(v_out, '[]'::jsonb);
END;
$$;


ALTER FUNCTION public.fn_ca_payout_structure(p_entrants integer, p_percent numeric) OWNER TO postgres;

--
-- TOC entry 46105 (class 0 OID 0)
-- Dependencies: 6301
-- Name: FUNCTION fn_ca_payout_structure(p_entrants integer, p_percent numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_payout_structure(p_entrants integer, p_percent numeric) IS 'Payout table for p_entrants paying the top p_percent of the field (any value in (0,100], default 12.5). Places = ceil(entrants * percent / 100), min 1, never more than the field. Weight 1/place^0.8, largest-remainder rounding to exactly 100.00.';


--
-- TOC entry 4589 (class 1255 OID 18204658)
-- Name: fn_ca_pgrst_reload_if_stale(interval, interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_pgrst_reload_if_stale(p_ddl_window interval DEFAULT '00:15:00'::interval, p_cooldown interval DEFAULT '00:05:00'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ddl      integer;
  v_last     timestamptz;
BEGIN
  SELECT count(*) INTO v_ddl
    FROM public.ca_ddl_events
   WHERE occurred_at > now() - p_ddl_window
     AND triggers_pgrst_reload;

  IF v_ddl = 0 THEN
    -- No DDL, so the cache cannot have gone stale. Reloading here would be the
    -- unconditional timer this deliberately is not.
    RETURN jsonb_build_object('sent', false, 'reason', 'no reload-triggering ddl in window', 'ddl_events', 0);
  END IF;

  SELECT max(sent_at) INTO v_last FROM public.ca_pgrst_reload_log;

  IF v_last IS NOT NULL AND v_last > now() - p_cooldown THEN
    RETURN jsonb_build_object('sent', false, 'reason', 'cooldown', 'ddl_events', v_ddl,
                              'last_sent_at', v_last);
  END IF;

  NOTIFY pgrst, 'reload schema';

  INSERT INTO public.ca_pgrst_reload_log (ddl_events, reason)
  VALUES (v_ddl, format('%s reload-triggering ddl event(s) in %s', v_ddl, p_ddl_window));

  RETURN jsonb_build_object('sent', true, 'ddl_events', v_ddl);
END;
$$;


ALTER FUNCTION public.fn_ca_pgrst_reload_if_stale(p_ddl_window interval, p_cooldown interval) OWNER TO postgres;

--
-- TOC entry 6547 (class 1255 OID 20582225)
-- Name: fn_ca_player_360(uuid, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_player_360(p_user_id uuid, p_money_visible boolean DEFAULT false, p_reveal_email boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_p       public.profiles;
  v_money   boolean := coalesce(p_money_visible, false);
  v_profile jsonb;
  v_rg      jsonb;
begin
  select * into v_p from public.profiles where id = p_user_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'player_not_found');
  end if;

  v_profile := jsonb_build_object(
    'id', v_p.id,
    'displayName', v_p.display_name,
    'username', v_p.username,
    'playerNumber', v_p.player_number,
    'avatarUrl', v_p.avatar_url,
    'country', v_p.country,
    'createdAt', v_p.created_at,
    'lastSeen', v_p.last_seen,
    'lastLogin', v_p.last_login,
    'emailVerified', v_p.email_verified,
    'phoneVerified', v_p.phone_verified,
    'isHorse', coalesce(v_p.is_horse, false),
    'role', v_p.role,
    'status', v_p.status,
    'totalHandsPlayed', v_p.total_hands_played);

  if p_reveal_email then
    v_profile := v_profile || jsonb_build_object('email', v_p.email);
  end if;
  if v_money then
    v_profile := v_profile || jsonb_build_object('diamonds', v_p.diamond_balance);
  end if;

  -- The four deposit and loss limits are CURRENCY. The exclusion
  -- timestamps and the reality-check interval are protection state, not
  -- money, and stay visible to anybody who can open the tab: an
  -- operator answering a self-exclusion question needs to see it.
  select jsonb_build_object(
           'user_id', rg.user_id,
           'session_time_limit_minutes', rg.session_time_limit_minutes,
           'reality_check_interval_minutes', rg.reality_check_interval_minutes,
           'self_excluded_until', rg.self_excluded_until,
           'cooling_off_until', rg.cooling_off_until,
           'limit_increase_available_at', rg.limit_increase_available_at,
           'updated_at', rg.updated_at,
           'daily_deposit_limit', case when v_money then rg.daily_deposit_limit end,
           'weekly_deposit_limit', case when v_money then rg.weekly_deposit_limit end,
           'monthly_deposit_limit', case when v_money then rg.monthly_deposit_limit end,
           'daily_loss_limit', case when v_money then rg.daily_loss_limit end)
    into v_rg
    from public.responsible_gaming_limits rg
   where rg.user_id = p_user_id;

  return jsonb_build_object(
    'ok', true,
    'moneyVisible', v_money,
    'emailRevealed', coalesce(p_reveal_email, false),
    'profile', v_profile,

    'restrictions', coalesce((
      select jsonb_agg(to_jsonb(r) order by r.applied_at desc, r.id)
        from public.ca_player_restrictions r where r.user_id = p_user_id), '[]'::jsonb),

    'notes', coalesce((
      select jsonb_agg(to_jsonb(n) order by n.pinned desc, n.created_at desc, n.id)
        from public.ca_operator_player_notes n
       where n.user_id = p_user_id and n.deleted_at is null), '[]'::jsonb),

    'tags', coalesce((
      select jsonb_agg(t.tag order by t.tag)
        from public.ca_operator_player_tags t where t.user_id = p_user_id), '[]'::jsonb),

    'clubs', coalesce((
      select jsonb_agg(jsonb_build_object(
               'clubId', cm.club_id,
               'clubName', c.name,
               'role', cm.role,
               'status', cm.status,
               'joinedAt', cm.joined_at,
               'lastActiveAt', cm.last_active_at,
               'handsPlayed', cm.hands_played,
               'chipBalance', case when v_money then cm.chip_balance else null end)
             order by cm.joined_at desc)
        from public.club_members cm
        left join public.clubs c on c.id = cm.club_id
       where cm.user_id = p_user_id), '[]'::jsonb),

    'playRecord', coalesce((
      select jsonb_agg(jsonb_build_object(
               'clubId', ps.club_id,
               'handsPlayed', ps.hands_played,
               'vpip', ps.vpip,
               'pfr', ps.pfr,
               'tournamentsPlayed', ps.tournaments_played,
               'tournamentsWon', ps.tournaments_won,
               'totalWinnings', case when v_money then ps.total_winnings else null end,
               'totalLosses', case when v_money then ps.total_losses else null end,
               'totalRake', case when v_money then ps.total_rake else null end))
        from public.player_stats ps where ps.user_id = p_user_id), '[]'::jsonb),

    'seats', coalesce((
      select jsonb_agg(jsonb_build_object(
               'tableId', ts.table_id, 'seatNumber', ts.seat_number,
               'joinedAt', ts.joined_at, 'clubId', ts.club_id,
               'stack', case when v_money then ts.stack else null end)
             order by ts.joined_at desc)
        from public.table_seats ts
       where ts.user_id = p_user_id and ts.left_at is null), '[]'::jsonb),

    'kycEvents', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', k.id, 'eventType', k.event_type, 'provider', k.provider,
               'previousStatus', k.previous_status, 'newStatus', k.new_status,
               'source', k.source, 'createdAt', k.created_at)
             order by k.created_at desc)
        from (select * from public.kyc_events
               where user_id = p_user_id order by created_at desc, id limit 50) k),
      '[]'::jsonb),

    'responsibleGaming', v_rg,

    'tickets', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', t.id, 'subject', t.subject, 'status', t.status,
               'priority', t.priority, 'assignedTo', t.assigned_to,
               'createdAt', t.created_at, 'resolvedAt', t.resolved_at)
             order by t.created_at desc)
        from (select * from public.live_help_tickets
               where user_id = p_user_id order by created_at desc, id limit 50) t),
      '[]'::jsonb),

    'reportsAgainst', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', ur.id, 'reason', ur.reason, 'status', ur.status,
               'createdAt', ur.created_at)
             order by ur.created_at desc)
        from (select * from public.user_reports
               where reported_user_id = p_user_id order by created_at desc, id limit 50) ur),
      '[]'::jsonb),

    'flags', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', f.id, 'flagType', f.flag_type, 'severity', f.severity,
               'status', f.status, 'flaggedAt', f.flagged_at)
             order by f.flagged_at desc)
        from (select * from public.anti_cheat_flags
               where player_id = p_user_id order by flagged_at desc, id limit 50) f),
      '[]'::jsonb),

    'auditRowCount', (
      select count(*) from public.admin_audit_log
       where target_id = p_user_id::text),

    'observationCount', (
      select count(*) from public.ca_restriction_observations
       where user_id = p_user_id)
  );
end;
$$;


