CREATE FUNCTION public.fn_ca_rake_by_club_v2(p_clubs uuid[], p_start date, p_end date, p_limit integer, p_offset integer DEFAULT 0, p_search text DEFAULT NULL::text, p_sort text DEFAULT 'rake'::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
