 SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM page p),'[]'::jsonb),'total',(SELECT count(*) FROM filtered),'total_direct',(SELECT round(coalesce(sum(fee),0),2) FROM listed),'total_commission',NULL);
