CREATE FUNCTION public.fn_ca_rake_felt_v2(p_clubs uuid[], p_start date, p_end date) RETURNS TABLE(table_id uuid, club_id uuid, stat_date date, felt numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
