--
-- TOC entry 9313 (class 1255 OID 28805426)
-- Name: fn_ca_rake_rollup_writer_silent(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_rake_rollup_writer_silent(p_max_silence_hours integer DEFAULT 26) RETURNS TABLE(union_id uuid, last_write_at timestamp with time zone, hours_since_last_write numeric, newest_day_rolled date, newest_complete_day date, missing_complete_days integer, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH clock AS (
    SELECT now() AS checked_at
  ), bounds AS (
    SELECT checked_at,
           (checked_at AT TIME ZONE 'UTC')::date AS utc_today,
           ((checked_at AT TIME ZONE 'UTC') - interval '65 minutes')::date - 1 AS newest_due_day
      FROM clock
  ), totals AS (
    SELECT d.union_id AS uid, max(d.computed_at) AS last_write, max(d.day) AS newest_day
      FROM public.union_rake_rollup_days d
     GROUP BY d.union_id
  ), m AS (
    SELECT t.*,
           (SELECT count(*)::int
              FROM generate_series((b.utc_today - 7)::timestamp,
                                   b.newest_due_day::timestamp,
                                   interval '1 day') g(day)
             WHERE NOT EXISTS (SELECT 1 FROM public.union_rake_rollup_days x
                                WHERE x.union_id = t.uid AND x.day = g.day::date)) AS missing_days
      FROM totals t CROSS JOIN bounds b
  )
  SELECT m.uid, m.last_write,
         round((extract(epoch FROM (b.checked_at - m.last_write)) / 3600.0)::numeric, 2),
         m.newest_day, b.utc_today - 1, m.missing_days,
         'union_rake_rollup_days has not been written for '
           || round((extract(epoch FROM (b.checked_at - m.last_write)) / 3600.0)::numeric, 2)
           || ' hour(s) and ' || m.missing_days
           || ' due UTC day(s) in the last 7 completed days carry no rollup row '
           || '(newest day rolled: ' || COALESCE(m.newest_day::text, 'never')
           || ', newest completed day: ' || (b.utc_today - 1)::text
           || ', newest due day: ' || b.newest_due_day::text
           || '). Yesterday is due at 01:05 UTC: the first scheduled writer starts '
           || 'at 00:55 and has a 600-second execution budget. Older missing days '
           || 'and the configured silence threshold are checked throughout this window.'
    FROM m CROSS JOIN bounds b
   WHERE m.last_write < b.checked_at - make_interval(hours => GREATEST(p_max_silence_hours, 1))
      OR m.missing_days > 0
   ORDER BY 3 DESC
$$;


ALTER FUNCTION public.fn_ca_rake_rollup_writer_silent(p_max_silence_hours integer) OWNER TO postgres;

--
-- TOC entry 46158 (class 0 OID 0)
-- Dependencies: 9313
-- Name: FUNCTION fn_ca_rake_rollup_writer_silent(p_max_silence_hours integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_rake_rollup_writer_silent(p_max_silence_hours integer) IS 'Writer-silence check for union_rake_rollup_days. 26h = 24h (the longest CORRECT silence, because the catch-up refuses an incomplete UTC day and only writes stale days) + 1h cron period + 1h margin. Second leg catches the real harm directly: a completed day in the last 7 with no rollup row, which is what 2026-09-09/10/11 were for 68 hours.';


--
-- TOC entry 4412 (class 1255 OID 19237195)
-- Name: fn_ca_rake_series(uuid[], date, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_rake_series(p_club_ids uuid[], p_start date, p_end date, p_bucket text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH b AS (
    SELECT CASE WHEN lower(COALESCE(p_bucket, 'day')) IN ('day', 'week', 'month')
                THEN lower(p_bucket) ELSE 'day' END AS unit
  ), rows AS (
    SELECT c.stat_date AS d, c.rake AS fee, c.net AS winnings
      FROM public.club_table_daily c
     WHERE c.club_id = ANY (p_club_ids) AND c.stat_date BETWEEN p_start AND p_end
    UNION ALL
    SELECT t.stat_date, t.fee, t.winnings
      FROM public.ca_club_tournament_daily t
     WHERE t.club_id = ANY (p_club_ids) AND t.stat_date BETWEEN p_start AND p_end
  ), grouped AS (
    SELECT date_trunc((SELECT unit FROM b), rows.d::timestamp)::date AS bucket,
           round(SUM(rows.fee), 2)      AS fee,
           round(SUM(rows.winnings), 2) AS winnings
      FROM rows GROUP BY 1
  )
  SELECT COALESCE(
    jsonb_agg(jsonb_build_object('bucket', bucket, 'fee', fee, 'winnings', winnings)
              ORDER BY bucket),
    '[]'::jsonb)
  FROM grouped;
$$;


ALTER FUNCTION public.fn_ca_rake_series(p_club_ids uuid[], p_start date, p_end date, p_bucket text) OWNER TO postgres;

