--
-- TOC entry 8996 (class 1255 OID 48791393)
-- Name: fn_ca_rakeback_payout_leg_is_documented(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_rakeback_payout_leg_is_documented() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  m        jsonb := COALESCE(NEW.metadata,'{}'::jsonb);
  v_period uuid; v_cert bigint; v_payout uuid;
  v_kind   text; v_scope uuid; v_start timestamptz; v_end timestamptz;
  v_docs   int;
  v_legacy_operation uuid;
BEGIN
  IF NEW.idempotency_key IS NULL OR btrim(NEW.idempotency_key)='' THEN
    RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
      DETAIL='chip_ledger '||NEW.id::text||' carries no idempotency key';
  END IF;
  IF m->>'routing_version' IS DISTINCT FROM '3' THEN
    RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
      DETAIL='chip_ledger '||NEW.id::text||' has no routed accounting identity';
  END IF;
  BEGIN
    v_period:=(m->>'period_id')::uuid;   v_cert :=(m->>'certificate_id')::bigint;
    v_payout:=(m->>'payout_id')::uuid;   v_kind :=m->>'accounting_scope_kind';
    v_scope :=(m->>'accounting_scope_id')::uuid;
    v_start :=(m->>'period_start')::timestamptz;
    v_end   :=(m->>'period_end')::timestamptz;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
      DETAIL='chip_ledger '||NEW.id::text||' has an unreadable routed accounting identity';
  END;
  IF v_period IS NULL OR v_cert IS NULL OR v_payout IS NULL OR v_kind IS NULL
     OR v_scope IS NULL OR v_start IS NULL OR v_end IS NULL THEN
    RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
      DETAIL='chip_ledger '||NEW.id::text||' is missing part of its period, certificate or payout identity';
  END IF;

  -- The settlement run a disputing player is shown the payment under.
  IF NOT EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r
    WHERE r.scope_kind=v_kind AND r.scope_id=v_scope AND r.period_start=v_start
      AND r.period_end=v_end AND r.round_no=3 AND r.routing_version=3)
    AND NOT EXISTS(SELECT 1 FROM public.accounting_rakeback_period_calculations c
      JOIN public.rakeback_period_payouts pp ON pp.id=v_payout AND pp.rakeback_period_id=c.period_id
      JOIN public.rakeback_periods rp ON rp.id=c.period_id
      WHERE NOT(m ? 'certificate_kind') AND c.id=v_cert AND c.accounting_version=2
       AND c.period_id=v_period AND c.club_id=NEW.club_id AND c.player_id=NEW.to_entity_id
       AND pp.club_id=c.club_id AND pp.user_id=c.player_id AND pp.status='paid' AND pp.payout_amount=c.rakeback_amount
       AND rp.status='paid' AND rp.club_id=c.club_id AND rp.user_id=c.player_id
       AND c.period_start=(v_start AT TIME ZONE 'America/Los_Angeles')::date
       AND c.period_end=(v_end AT TIME ZONE 'America/Los_Angeles')::date-1 AND c.period_end=c.period_start+6
       AND v_end<=now()-interval '5 minutes' AND v_start=public.fn_union_week_start(v_start)
       AND v_end=public.fn_union_week_start(v_start+interval '8 days')
       AND m->>'source_fingerprint'=c.source_fingerprint
       AND((v_kind='union' AND c.coordinator_union_id=v_scope)
         OR(v_kind='club' AND c.coordinator_union_id IS NULL AND c.club_id=v_scope))) THEN
    RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
      DETAIL='chip_ledger '||NEW.id::text||' names no routed settlement run';
  END IF;

  IF EXISTS(SELECT 1 FROM public.accounting_rakeback_period_calculations c WHERE c.id=v_cert AND c.payer_kind='split') THEN
    IF NOT smarter_private.split_rakeback_payout_complete(v_payout,v_cert)
      OR NOT EXISTS(SELECT 1 FROM public.accounting_rakeback_payer_transfers t WHERE t.payout_id=v_payout AND t.calculation_id=v_cert AND t.period_id=v_period AND t.ledger_id=NEW.id AND t.amount=NEW.amount)
    THEN RAISE EXCEPTION 'split_rakeback_payout_leg_undocumented' USING ERRCODE='23514'; END IF;
    RETURN NULL;
  END IF;

  IF NOT EXISTS(SELECT 1 FROM public.rakeback_period_payouts pp
    WHERE pp.id=v_payout AND pp.rakeback_period_id=v_period AND pp.club_id=NEW.club_id
      AND pp.user_id=NEW.to_entity_id AND pp.status='paid' AND pp.payout_amount=NEW.amount) THEN
    RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
      DETAIL='chip_ledger '||NEW.id::text||' names no matching paid rakeback period payout';
  END IF;

  IF m ? 'certificate_kind' THEN
    -- The only other certificate kind is the owner-authorized legacy one. It
    -- must name its operation, and the certificate must be that operation's.
    IF m->>'certificate_kind' IS DISTINCT FROM 'owner_legacy_v1' THEN
      RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
        DETAIL='chip_ledger '||NEW.id::text||' names an unknown certificate kind';
    END IF;
    BEGIN v_legacy_operation:=(m->>'legacy_operation_id')::uuid;
    EXCEPTION WHEN OTHERS THEN v_legacy_operation:=NULL; END;
    IF v_legacy_operation IS NULL OR NOT EXISTS(SELECT 1 FROM public.accounting_legacy_rakeback_certificates c
      JOIN public.accounting_owner_legacy_operations o ON o.operation_id=c.operation_id
      WHERE c.id=v_cert AND c.operation_id=v_legacy_operation AND c.period_id=v_period AND c.club_id=NEW.club_id
        AND c.player_id=NEW.to_entity_id AND c.rakeback_amount=NEW.amount
        AND o.period_start=v_start AND o.period_end=v_end) THEN
      RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
        DETAIL='chip_ledger '||NEW.id::text||' names no matching owner legacy certificate';
    END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM public.accounting_rakeback_period_calculations c
    WHERE c.id=v_cert AND c.period_id=v_period AND c.club_id=NEW.club_id
      AND c.player_id=NEW.to_entity_id AND c.rakeback_amount=NEW.amount) THEN
    RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
      DETAIL='chip_ledger '||NEW.id::text||' names no matching rakeback certificate';
  END IF;

  SELECT count(*) INTO v_docs FROM public.settlement_invoices i
   WHERE i.source_ledger_id=NEW.id AND i.status='paid' AND i.chips_transferred
     AND i.gross_amount=NEW.amount AND i.net_amount=NEW.amount;
  IF v_docs<>1 THEN
    RAISE EXCEPTION 'rakeback_payout_leg_undocumented' USING ERRCODE='23514',
      DETAIL='chip_ledger '||NEW.id::text||' has '||v_docs::text||' source-linked paid receipts, expected exactly 1';
  END IF;
  RETURN NULL;
END $$;


ALTER FUNCTION public.fn_ca_rakeback_payout_leg_is_documented() OWNER TO postgres;

--
-- TOC entry 46164 (class 0 OID 0)
-- Dependencies: 8996
-- Name: FUNCTION fn_ca_rakeback_payout_leg_is_documented(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_rakeback_payout_leg_is_documented() IS 'A posted rakeback leg into a player wallet must carry, in the same transaction, its routed accounting identity, the settlement run it was paid under, its paid payout row, the certificate it was computed from, and exactly one source-linked paid receipt. Deferred for the same reason zz_ca_issuance_leg_is_registered is deferred: the document and the run journal are written later in the same transaction. It requires a strict subset of what fn_settle_accounting_rakeback_stage already asserts, so the weekly authority cannot be refused by it. It does NOT require chip_ledger.settlement_id, which that authority does not populate on the payout leg.';


--
-- TOC entry 9191 (class 1255 OID 18637228)
-- Name: fn_ca_ratchet_watch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_ratchet_watch() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_row record; v_current integer; v_out jsonb := '[]'::jsonb; v_crit boolean;
BEGIN
  FOR v_row IN SELECT * FROM public.ca_ratchet_baselines ORDER BY ratchet LOOP
    IF v_row.ratchet = 'unledgered_insert_paths' THEN
      SELECT count(*)::int INTO v_current FROM public.fn_ca_unledgered_insert_paths();
    ELSIF v_row.ratchet = 'undeclared_money_paths' THEN
      SELECT count(*)::int INTO v_current FROM public.fn_ca_undeclared_money_paths();
    ELSIF v_row.ratchet = 'rake_law_violations_24h' THEN
      /* THE ONE KIND THIS RATCHET COUNTS, READ DIRECTLY (2026-10-03).
         fn_rake_law_violations computes nine finding kinds, including
         fn_effective_rake and fn_effective_bbj_drop for every flopped hand
         in the window; it is a SQL function with SET search_path, so it is
         never inlined and an outer WHERE kind IN (...) cannot prune it. Of
         the three kinds this ratchet counts, 'over_cap' and 'over_percent'
         are not kinds that function emits; the one that exists is
         no_flop_no_drop, whose rule there is: a non-tournament hand on a
         non-tournament table in (now()-2h, now()-5min) with no board
         (board_n = 0), no showdown, and rake + BBJ drop > 0.005, where BBJ
         is COALESCE(rake_records.bbj_contribution, hand_history.bbj_amount,
         0). This is that rule, row for row (rake_records.hand_id is unique;
         the clubs join it also carries is a left join on a key and cannot
         change a count). Measured on production 2026-10-03: the old call
         was cancelled at 300 s in 5 of 6 runs; this reads in 7.5 s. */
      SELECT count(*)::int INTO v_current
        FROM public.hand_history hh
        JOIN public.tables t ON t.id = hh.table_id
        LEFT JOIN public.rake_records rr ON rr.hand_id = hh.id
       WHERE hh.created_at > now() - '2 hours'::interval
         AND hh.created_at < now() - interval '5 minutes'
         AND t.tournament_id IS NULL
         AND hh.tournament_id IS NULL
         AND COALESCE(array_length(hh.community_cards, 1), 0)
               + COALESCE(array_length(hh.community_cards2, 1), 0) = 0
         AND hh.showdown IS NULL
         AND COALESCE(hh.rake_amount, 0)
               + COALESCE(rr.bbj_contribution, hh.bbj_amount, 0) > 0.005;
    ELSIF v_row.ratchet = 'reconciler_delete_unscoped' THEN
      SELECT public.fn_ca_reconciler_delete_unscoped() INTO v_current;
    ELSIF v_row.ratchet = 'completed_without_a_champion' THEN
      SELECT public.fn_ca_completed_without_a_champion() INTO v_current;
    ELSIF v_row.ratchet = 'prize_overpay_unexplained_10d' THEN
      SELECT public.fn_ca_prize_overpay_count() INTO v_current;
    ELSIF v_row.ratchet = 'rake_distributed_exceeds_collected_1h' THEN
      SELECT public.fn_ca_rake_distribution_mismatch_count() INTO v_current;
    ELSIF v_row.ratchet = 'tournament_underpaid_48h' THEN
      SELECT public.fn_ca_tournament_underpaid_count() INTO v_current;
    ELSE
      CONTINUE;
    END IF;

    v_crit := v_row.ratchet IN ('rake_law_violations_24h','reconciler_delete_unscoped',
                                'completed_without_a_champion','prize_overpay_unexplained_10d',
                                'rake_distributed_exceeds_collected_1h','tournament_underpaid_48h');

    IF v_current > v_row.baseline THEN
      PERFORM public.fn_ca_raise_drift_incident(
        p_source          => 'fn_ca_ratchet_watch',
        p_classification  => CASE v_row.ratchet
                               WHEN 'rake_law_violations_24h' THEN 'incorrect_rake'
                               WHEN 'rake_distributed_exceeds_collected_1h' THEN 'incorrect_rake'
                               WHEN 'reconciler_delete_unscoped' THEN 'reporting_mismatch'
                               WHEN 'tournament_underpaid_48h' THEN 'missing_payment'
                               WHEN 'completed_without_a_champion' THEN 'settlement_error'
                               WHEN 'prize_overpay_unexplained_10d' THEN 'settlement_error'
                               ELSE 'unauthorized_adjustment' END,
        p_severity        => CASE WHEN v_crit THEN 'critical' ELSE 'warning' END,
        p_dedupe_key      => 'ratchet:' || v_row.ratchet || ':above:' || v_row.baseline
                             || ':' || to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD'),
        p_discrepancy     => (v_current - v_row.baseline)::numeric,
        p_expected        => v_row.baseline::numeric,
        p_actual          => v_current::numeric,
        p_layer           => CASE v_row.ratchet
                               WHEN 'reconciler_delete_unscoped' THEN 'reporting'
                               WHEN 'undeclared_money_paths' THEN 'ledger'
                               WHEN 'unledgered_insert_paths' THEN 'ledger'
                               ELSE 'settlement' END,
        p_suspected_cause => CASE v_row.ratchet
          WHEN 'rake_law_violations_24h' THEN
            'Chips were raked that the rules did not owe the house, in the last 2 hours.'
          WHEN 'rake_distributed_exceeds_collected_1h' THEN
            'A larger share of raked hands is banking more rake than was taken from the pot.'
          WHEN 'reconciler_delete_unscoped' THEN
            'reconcile_ledger_nightly has lost its scoped DELETE and is again clearing '
            || 'ledger_reconcile_log rows it never wrote.'
          WHEN 'tournament_underpaid_48h' THEN
            'A tournament paid players LESS than it owed - GREATEST(prize_pool, '
            || 'guaranteed_prize). Every case found so far was a guarantee that was never '
            || 'topped up, so the advertised prize pool and the paid one differ. Read them '
            || 'with SELECT * FROM fn_ca_tournament_settlement_mismatch() WHERE kind=''underpaid''.'
          WHEN 'completed_without_a_champion' THEN
            'A tournament finished without anybody marked winner, so every settlement '
            || 'that reads status=winner is stuck.'
          WHEN 'prize_overpay_unexplained_10d' THEN
            'A tournament paid out more than its prize pool AND more than its guarantee, '
            || 'and it is neither a satellite nor a Spin.'
          ELSE
            'A new money path was added that does not declare its ledger counterparty.' END,
        p_ledger_balanced => true,
        p_metadata        => jsonb_build_object('ratchet', v_row.ratchet,
                                                'baseline', v_row.baseline,
                                                'current',  v_current));
    ELSIF v_current < v_row.baseline THEN
      UPDATE public.ca_ratchet_baselines
         SET baseline = v_current, tightened_at = now()
       WHERE ratchet = v_row.ratchet;
    END IF;

    v_out := v_out || jsonb_build_object('ratchet', v_row.ratchet,
                                         'baseline', v_row.baseline, 'current', v_current);
  END LOOP;

  INSERT INTO public.ca_detector_runs (detector, detail)
  VALUES ('fn_ca_ratchet_watch', jsonb_build_object('ratchets', v_out));

  RETURN jsonb_build_object('checked_at', now(), 'ratchets', v_out);
END;
$$;


ALTER FUNCTION public.fn_ca_ratchet_watch() OWNER TO postgres;

--
-- TOC entry 46166 (class 0 OID 0)
-- Dependencies: 9191
-- Name: FUNCTION fn_ca_ratchet_watch(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_ratchet_watch() IS 'Hourly. Raises a warning incident when a structural money-path ratchet regresses above its baseline, and tightens the baseline when it improves. Never blocks or disables anything.';


