--
-- TOC entry 5027 (class 1255 OID 218103502)
-- Name: fn_ca_refresh_provisional_payout_structure(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_refresh_provisional_payout_structure(p_tournament_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ladder jsonb;
  v_rows integer;
BEGIN
  v_ladder := public.fn_ca_provisional_payout_structure(p_tournament_id);
  IF v_ladder IS NULL OR jsonb_typeof(v_ladder) <> 'array' OR jsonb_array_length(v_ladder) = 0 THEN
    RETURN false;
  END IF;
  UPDATE public.tournaments t
     SET payout_structure = v_ladder::text
   WHERE t.id = p_tournament_id
     AND NOT COALESCE(t.prize_pool_finalized, false)
     AND public.fn_safe_jsonb_array(t.payout_structure::text) IS DISTINCT FROM v_ladder;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows = 1;
END;
$$;


ALTER FUNCTION public.fn_ca_refresh_provisional_payout_structure(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 3565 (class 1255 OID 25581583)
-- Name: fn_ca_refund_entitlement_commit_valid(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_refund_entitlement_commit_valid() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ent_count bigint;
  v_ent_amount numeric;
  v_wallet_count bigint;
  v_wallet_amount numeric;
  v_rows integer;
BEGIN
  IF NEW.entitlement_kind='wallet_charge' THEN
    SELECT count(*) INTO v_rows FROM public.chip_ledger l
     WHERE l.id=NEW.source_ledger_id
       AND l.tournament_id=NEW.tournament_id
       AND l.club_id=NEW.refund_wallet_club_id
       AND l.from_type='player_wallet' AND l.from_entity_id=NEW.user_id
       AND l.to_type='prize_liability'
       AND l.to_entity_id=NEW.tournament_id
       AND lower(l.category)=NEW.charge_category
       AND l.amount=NEW.gross;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'wallet charge entitlement lost its exact source ledger'
        USING ERRCODE = 'P0404';
    END IF;
    SELECT count(*),round(COALESCE(sum(e.gross),0),2)
      INTO v_ent_count,v_ent_amount
      FROM public.tournament_refund_entitlements e
     WHERE e.tournament_id=NEW.tournament_id AND e.user_id=NEW.user_id
       AND e.entitlement_kind='wallet_charge'
       AND e.charge_category=NEW.charge_category;
    SELECT count(*),round(COALESCE(sum(w.amount),0),2)
      INTO v_wallet_count,v_wallet_amount
      FROM public.wallet_transactions w
     WHERE w.related_entity_id=NEW.tournament_id AND w.user_id=NEW.user_id
       AND w.type='debit' AND lower(w.category)=NEW.charge_category;
    IF v_ent_count IS DISTINCT FROM v_wallet_count
       OR v_ent_amount IS DISTINCT FROM v_wallet_amount THEN
      RAISE EXCEPTION
        'wallet charge entitlement and reporting debit do not commit together'
        USING ERRCODE = 'P0404';
    END IF;
  ELSIF NEW.entitlement_kind='satellite_seat' THEN
    SELECT count(*) INTO v_rows FROM public.chip_ledger l
     WHERE l.id=NEW.source_ledger_id
       AND l.club_id=NEW.refund_wallet_club_id
       AND l.from_type='prize_liability'
       AND l.from_entity_id=NEW.source_satellite_id
       AND l.to_type='prize_liability'
       AND l.to_entity_id=NEW.tournament_id
       AND l.amount=NEW.gross
       AND l.metadata->>'user_id'=NEW.user_id::text
       AND l.metadata->>'registration_id'=NEW.registration_id::text;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'satellite seat entitlement lost its exact pool transfer'
        USING ERRCODE = 'P0404';
    END IF;
  ELSE
    SELECT count(*) INTO v_rows
      FROM public.chip_ledger l
      JOIN public.tournament_tickets tk ON tk.id=NEW.source_ticket_id
     WHERE l.id=NEW.source_ledger_id
       AND l.tournament_id=NEW.tournament_id
       AND l.club_id=NEW.refund_wallet_club_id
       AND l.from_type='escrow' AND l.from_entity_id=NEW.source_ticket_id
       AND l.to_type='prize_liability'
       AND l.to_entity_id=NEW.tournament_id
       AND l.category='ticket_redeem' AND l.amount=NEW.gross
       AND l.metadata->>'user_id'=NEW.user_id::text
       AND l.metadata->>'registration_id'=NEW.registration_id::text
       AND tk.holder_id=NEW.user_id
       AND tk.status='redeemed'
       AND tk.redemption_mode='tournament_entry_only'
       AND tk.value=NEW.gross
       AND tk.entry_prize=NEW.refund_prize
       AND tk.entry_bounty=NEW.refund_bounty
       AND tk.entry_fee=NEW.refund_fee
       AND tk.source_satellite_id=NEW.source_satellite_id;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION
        'tournament-ticket entitlement lost its exact admission transfer'
        USING ERRCODE = 'P0404';
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_ca_refund_entitlement_commit_valid() OWNER TO postgres;

--
-- TOC entry 4389 (class 1255 OID 166734761)
-- Name: fn_ca_refuse_replica_money_write(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_refuse_replica_money_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- Nested, not AND: an origin session (every real write) reads one setting
  -- and leaves; the cluster identity is read only in replica mode.
  IF current_setting('session_replication_role') <> 'replica' THEN
    RETURN NULL;
  END IF;
  IF public.fn_ca_is_protected_cluster() THEN
    RAISE EXCEPTION 'REFUSED: % on public.% under session_replication_role = replica',
      TG_OP, TG_TABLE_NAME
      USING ERRCODE = '42501',
            DETAIL  = 'Replica mode switches off every ordinary trigger on this table: the ledger tally, the commit-time ledger invariant, the seat exit log and the inventory observer. On 2026-10-06 15:33 UTC that is how 43 cash seats holding 14,081.45 chips were vacated with no cashout and no burn.',
            HINT    = 'Move chips through their door in an origin session. The door writes the balance and its chip_ledger leg in one transaction.';
  END IF;
  RETURN NULL;
END
$$;


ALTER FUNCTION public.fn_ca_refuse_replica_money_write() OWNER TO postgres;

