COMMENT ON FUNCTION public.fn_ca_refuse_replica_money_write() IS 'Statement-level ENABLE ALWAYS guard on every chip store: refuses writes made under session_replication_role = replica on a protected cluster (20261015105156).';


--
-- TOC entry 5488 (class 1255 OID 20582211)
-- Name: fn_ca_refuse_restricted_entry(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_refuse_restricted_entry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE v_scope text := coalesce(TG_ARGV[0],'account'); v_tourney uuid;
BEGIN
  IF TG_TABLE_NAME='table_seats' THEN
    SELECT tournament_id INTO v_tourney FROM public.tables WHERE id=NEW.table_id;
    v_scope := CASE WHEN v_tourney IS NULL THEN 'cash' ELSE 'tournaments' END;
  END IF;
  PERFORM public.fn_ca_assert_player_action(NEW.user_id,v_scope,TG_TABLE_NAME);
  RETURN NEW;
EXCEPTION WHEN insufficient_privilege THEN RAISE;
  WHEN OTHERS THEN RETURN NEW;
END $$;


