-- TOC entry 46202 (class 0 OID 0)
-- Dependencies: 8185
-- Name: FUNCTION fn_ca_release_unseatable_registrant_at_launch(p_tournament_id uuid, p_user_id uuid, p_launch_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_release_unseatable_registrant_at_launch(p_tournament_id uuid, p_user_id uuid, p_launch_id uuid, p_reason text) IS 'The one door a launch uses to release a registrant it cannot seat: service-only, requires the event''s incomplete launch receipt by launch_id, refuses a player holding a live seat, and settles the exact refund through fn_ca_unregister_tournament_player_exact under a deterministic (launch, player) request id.';


--
-- TOC entry 7690 (class 1255 OID 48791303)
-- Name: fn_ca_remeasure_entity(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_remeasure_entity(p_entity_type text, p_entity_id uuid) RETURNS TABLE(measurable boolean, ledger_balance numeric, stored_balance numeric, severity text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  /* THREE OUTCOMES, NEVER TWO (CLAUDE.md 10.86 rule 1). "I cannot measure
     this entity type" is its own answer and must never be dressed up as
     'ok' - that would silence a real critical - nor as 'critical', which
     is the bug this function exists to stop. */
  IF p_entity_type = 'club_treasury' AND p_entity_id IS NOT NULL THEN
    RETURN QUERY
      SELECT true, p.ledger_balance, p.stored_balance, p.severity
        FROM public.fn_ca_treasury_positions() p
       WHERE p.club_id = p_entity_id;

    IF FOUND THEN
      RETURN;
    END IF;

    -- Absent from the merged set means no stored treasury AND no flow since
    -- the cutover. That is a measurement of zero, not a failure to measure.
    RETURN QUERY SELECT true, 0::numeric, 0::numeric, 'ok'::text;
    RETURN;
  END IF;

  /* A DIAMOND RAKE FINDING IS MEASURED AGAIN (2026-10-09): on a Diamond cash
     table the rake law is the settler's recompute, so measure every hand of
     the last 48 hours the way fn_rake_law_violations does (recorded rake
     against the rake its receipt accepted). ledger_balance is the accepted
     rake, stored_balance the recorded rake. */
  IF p_entity_type = 'rake_law' AND p_entity_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.tables t JOIN public.clubs c ON c.id = t.club_id
                  WHERE t.id = p_entity_id AND t.tournament_id IS NULL AND c.asset = 'diamonds') THEN
    RETURN QUERY
      WITH hd AS (
        SELECT COALESCE(hh.rake_amount, 0) AS rake,
               (SELECT (r.receipt->>'rake')::numeric
                  FROM public.poker_diamond_hand_receipts r
                 WHERE r.table_id = hh.table_id AND r.hand_number = hh.hand_number) AS settled_rake
          FROM public.hand_history hh
         WHERE hh.table_id = p_entity_id
           AND hh.tournament_id IS NULL
           AND hh.created_at > now() - interval '48 hours'
           AND hh.created_at < now() - interval '5 minutes'
      )
      SELECT true,
             COALESCE(sum(hd.settled_rake), 0),
             COALESCE(sum(hd.rake), 0),
             CASE WHEN bool_or(hd.settled_rake IS DISTINCT FROM hd.rake
                               AND (hd.settled_rake IS NOT NULL OR hd.rake > 0.005))
                  THEN 'critical' ELSE 'ok' END
        FROM hd;
    RETURN;
  END IF;

  /* A CHIP RAKE FINDING IS MEASURED AGAIN (2026-10-16). On a chip cash table
     the rake law is fn_effective_rake and fn_effective_bbj_drop, priced with
     the number of players dealt in, so measure every flopped hand of the last
     36 hours (the escalator's lookback) exactly the way fn_rake_law_violations
     does. Without this branch every chip rake_law finding was "could not
     tell" and the hourly escalator re-filed it for 36 hours after the cause
     was fixed: the Lightning pilot's 2026-10-15 storm recurred every hour.
     ledger_balance is the rake and drop the law allows, stored_balance the
     rake and drop the hands recorded. A flopped hand with no dealt count is
     unreadable, and unreadable is a finding, never ok. */
  IF p_entity_type = 'rake_law' AND p_entity_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.tables t LEFT JOIN public.clubs c ON c.id = t.club_id
                  WHERE t.id = p_entity_id AND t.tournament_id IS NULL
                    AND COALESCE(c.asset = 'diamonds', false) = false) THEN
    RETURN QUERY
      WITH h AS (
        SELECT hh.pot_size AS pot,
               COALESCE(hh.rake_amount, 0) AS rake,
               COALESCE(rr.bbj_contribution, hh.bbj_amount, 0) AS bbj,
               t.small_blind AS sb, t.big_blind AS bb, t.club_id, t.id AS tid,
               t.max_players AS seats, hh.cash_rake_policy,
               lower(COALESCE(hh.game_variant, t.game_variant::text)) AS variant,
               GREATEST(rr.num_players, jsonb_array_length(CASE WHEN jsonb_typeof(hh.players) = 'array' THEN hh.players END)) AS dealt,
               CASE WHEN t.rake_percent >= 0 THEN t.rake_percent
                    WHEN c.default_rake_percent >= 0 THEN c.default_rake_percent END AS ov_pct,
               CASE WHEN t.rake_cap_bb >= 0 THEN t.rake_cap_bb
                    WHEN c.rake_cap >= 0 THEN c.rake_cap END AS ov_cap_bb
          FROM public.hand_history hh
          JOIN public.tables t ON t.id = hh.table_id
          LEFT JOIN public.clubs c ON c.id = t.club_id
          LEFT JOIN public.rake_records rr ON rr.hand_id = hh.id
         WHERE hh.table_id = p_entity_id
           AND hh.tournament_id IS NULL
           AND hh.created_at > now() - interval '36 hours'
           AND hh.created_at < now() - interval '5 minutes'
           AND COALESCE(array_length(hh.community_cards, 1), 0)
                 + COALESCE(array_length(hh.community_cards2, 1), 0) >= 3
      ), f AS (
        SELECT h.*, CASE WHEN h.cash_rake_policy IS NOT NULL AND h.dealt IS NOT NULL
                       THEN public.fn_cash_rake_from_snapshot(h.pot,h.dealt,true,h.cash_rake_policy)
                       ELSE e.rake END AS exp_rake
          FROM h
          LEFT JOIN LATERAL public.fn_effective_rake(h.bb, h.pot, h.dealt, true, h.sb, h.ov_pct, h.ov_cap_bb, h.seats) e
            ON h.dealt IS NOT NULL
      ), fb AS (
        SELECT f.*,
               CASE WHEN f.dealt IS NOT NULL
                    THEN public.fn_effective_bbj_drop(f.bb, f.dealt, true, f.club_id, f.tid, f.variant, f.sb, f.pot, f.rake)
               END AS exp_bbj
          FROM f
      )
      SELECT true,
             COALESCE(sum(fb.exp_rake + fb.exp_bbj), 0),
             COALESCE(sum(fb.rake + fb.bbj), 0),
             CASE WHEN bool_or(fb.dealt IS NULL
                               OR abs(fb.rake - fb.exp_rake) > 0.005
                               OR abs(fb.bbj - fb.exp_bbj) > 0.005)
                  THEN 'critical' ELSE 'ok' END
        FROM fb;
    RETURN;
  END IF;

  RETURN QUERY SELECT false, NULL::numeric, NULL::numeric, NULL::text;
END;
$$;


ALTER FUNCTION public.fn_ca_remeasure_entity(p_entity_type text, p_entity_id uuid) OWNER TO postgres;

--
-- TOC entry 46204 (class 0 OID 0)
-- Dependencies: 7690
-- Name: FUNCTION fn_ca_remeasure_entity(p_entity_type text, p_entity_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_remeasure_entity(p_entity_type text, p_entity_id uuid) IS 'Asks whether a stored ledger_reconcile_log finding is STILL true, right now. Returns measurable=false for entity types it cannot compute - callers must treat that as UNKNOWN and say so, never as ok. Read-only and STABLE. Extend it by teaching it an entity type, never by returning a guess.';


--
-- TOC entry 9212 (class 1255 OID 18304765)
-- Name: fn_ca_repair_write_failure(bigint, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_repair_write_failure(p_write_failure_id bigint, p_counterparty_type text DEFAULT 'settlement_suspense'::text, p_counterparty_entity uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  f RECORD;
  v_store text;
  v_res jsonb;
  v_inc uuid;
BEGIN
  SELECT * INTO f FROM public.ca_ledger_write_failures WHERE id = p_write_failure_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'write_failure_not_found');
  END IF;

  -- map the failed writer's table.column (kept in the message prefix) to the
  -- ledger account vocabulary; unknown shapes fall back to player/club stores
  v_store := CASE
    WHEN f.message LIKE '%clubs.chip_treasury%'            THEN 'club_treasury'
    WHEN f.message LIKE '%clubs.chip_pool%'                THEN 'club_treasury'
    WHEN f.message LIKE '%clubs.promo_balance%'            THEN 'promo_wallet'
    WHEN f.message LIKE '%club_members.chip_balance%'      THEN 'player_wallet'
    WHEN f.message LIKE '%club_members.promo_balance%'     THEN 'promo_wallet'
    WHEN f.message LIKE '%club_wallets.chip_balance%'      THEN 'club_wallet'
    WHEN f.message LIKE '%union_wallets.chip_balance%'     THEN 'union_bank'
    WHEN f.message LIKE '%union_wallets.%'                 THEN 'union_wallet'
    WHEN f.message LIKE '%agents.agent_wallet_balance%'    THEN 'agent_wallet'
    WHEN f.message LIKE '%agents.promo_wallet_balance%'    THEN 'promo_wallet'
    WHEN f.message LIKE '%bbj_pools.%'                     THEN 'bbj_pool'
    WHEN f.message LIKE '%spin_bonus_pools.%'              THEN 'spin_reserve'
    WHEN f.user_id IS NOT NULL                             THEN 'player_wallet'
    ELSE 'club_treasury' END;

  SELECT id INTO v_inc FROM public.ca_drift_incidents
   WHERE dedupe_key = 'qr:lwf:' || p_write_failure_id::text
   ORDER BY detected_at DESC LIMIT 1;

  v_res := public.fn_ca_post_correction(
    CASE WHEN f.delta >= 0 THEN p_counterparty_type ELSE v_store END,
    CASE WHEN f.delta >= 0 THEN p_counterparty_entity ELSE COALESCE(f.user_id, f.club_id) END,
    CASE WHEN f.delta >= 0 THEN v_store ELSE p_counterparty_type END,
    CASE WHEN f.delta >= 0 THEN COALESCE(f.user_id, f.club_id) ELSE p_counterparty_entity END,
    abs(round(f.delta, 2)),
    COALESCE(p_reason,
      'Compensating entry for swallowed journal row (ca_ledger_write_failures '
      || p_write_failure_id::text || '): ' || left(f.message, 300)),
    v_inc, p_write_failure_id, f.club_id, NULL,
    jsonb_build_object('repaired_via', 'fn_ca_repair_write_failure',
                       'store', v_store, 'original_delta', f.delta));

  IF (v_res->>'ok')::boolean AND v_inc IS NOT NULL THEN
    PERFORM public.fn_ca_incident_action(v_inc, 'resolve',
      'Compensating entry posted via fn_ca_repair_write_failure (chip_ledger '
        || (v_res->>'ledger_id') || ').',
      NULL,
      'Swallowed journal row restored; ledger completeness re-established.',
      'chip_ledger ' || (v_res->>'ledger_id'));
  END IF;

  RETURN v_res || jsonb_build_object('incident_id', v_inc, 'store', v_store);
END $$;


ALTER FUNCTION public.fn_ca_repair_write_failure(p_write_failure_id bigint, p_counterparty_type text, p_counterparty_entity uuid, p_reason text) OWNER TO postgres;

--
-- TOC entry 8825 (class 1255 OID 126675318)
-- Name: fn_ca_replay_terminal_receipts(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_replay_terminal_receipts(p_hours integer DEFAULT 24, p_limit integer DEFAULT 4000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '600s'
    SET lock_timeout TO '2s'
    AS $$
DECLARE
  t record; v jsonb; v_proved boolean;
  v_ok int := 0; v_refused int := 0; v_locked int := 0; v_raised int := 0; v_resolved int := 0;
  v_fail jsonb := '[]'::jsonb;
BEGIN
  FOR t IN
    SELECT tr.id, upper(coalesce(tr.tournament_type,'')) ttype, lower(coalesce(tr.variant,'')) variant,
           (SELECT tp.user_id FROM public.tournament_players tp WHERE tp.tournament_id=tr.id AND tp.status::text='winner' ORDER BY tp.position LIMIT 1) winner,
           (SELECT s.qualifier_ids FROM public.tournament_satellite_settlements s WHERE s.tournament_id=tr.id) qids,
           EXISTS (SELECT 1 FROM public.tournament_satellite_settlements s WHERE s.tournament_id=tr.id) sat_hdr
      FROM public.tournaments tr
     WHERE tr.status='COMPLETED'
       AND tr.ended_at > now() - make_interval(hours => GREATEST(COALESCE(p_hours,24),1))
       AND upper(coalesce(tr.tournament_type,'')) IN ('MTT','SPIN','SNG','SATELLITE')
     ORDER BY CASE WHEN upper(coalesce(tr.tournament_type,''))='SATELLITE' OR lower(coalesce(tr.variant,''))='satellite' THEN 0
                   WHEN upper(coalesce(tr.tournament_type,''))='MTT' THEN 1 ELSE 2 END,
              tr.ended_at DESC
     LIMIT GREATEST(COALESCE(p_limit,4000),1)
  LOOP
    BEGIN
      -- A REPLAYED RECEIPT KEEPS NONE OF ITS LOCKS (2026-10-19). Every receipt
      -- is a reader: it writes nothing, and takes the locks a live settlement
      -- would (a satellite's: the finish lane F exclusively, both tournaments'
      -- T keys, the target's tournaments and tournament_players rows). This
      -- whole run is ONE transaction, and a subtransaction that succeeds hands
      -- its locks to the transaction until the run commits, so each proved
      -- satellite kept a running target tournament and its seats locked for
      -- the rest of the run: engine hands on those tables waited up to 108 s
      -- (04:37 UTC, 2026-10-18 and 10-19). A proved receipt now ends in its
      -- own rolled-back subtransaction, which releases every lock it took
      -- (rows, advisory keys and its transaction-local lane setting) before
      -- the next receipt starts. It wrote nothing, so nothing else is undone;
      -- a refusal is caught exactly as before.
      v_proved := false;
      BEGIN
        IF t.sat_hdr THEN
          IF t.qids IS NOT NULL AND cardinality(t.qids) > 0 THEN
            v := public.fn_ca_satellite_cohort_receipt(t.id, t.qids);
          ELSE
            v := public.fn_ca_satellite_settlement_receipt(t.id, t.winner);
          END IF;
        ELSIF t.ttype='SATELLITE' OR t.variant='satellite' THEN
          RAISE EXCEPTION 'satellite % completed without a settlement header', t.id USING ERRCODE='P0404';
        ELSE
          v := public.fn_ca_tournament_terminal_receipt(t.id, t.winner);
        END IF;
        v_proved := true;
        RAISE EXCEPTION 'terminal receipt % proved; its locks are released', t.id USING ERRCODE='CAR01';
      EXCEPTION WHEN SQLSTATE 'CAR01' THEN
        IF NOT v_proved THEN RAISE; END IF;
      END;
      v_ok := v_ok + 1;
    EXCEPTION
      WHEN lock_not_available OR query_canceled THEN
        v_locked := v_locked + 1;
      WHEN OTHERS THEN
        v_refused := v_refused + 1;
        IF jsonb_array_length(v_fail) < 50 THEN
          v_fail := v_fail || jsonb_build_object('tournament_id', t.id, 'type', t.ttype, 'code', SQLSTATE, 'error', left(SQLERRM, 240));
        END IF;
    END;
  END LOOP;

  -- One open alert per distinct refusal text; the incident bridge keys on it.
  INSERT INTO public.financial_alerts (severity, source, message, context)
  SELECT 'critical', 'fn_ca_replay_terminal_receipts',
         format('A terminal receipt no longer proves on replay: %s tournament(s) completed in the last %s h refuse with "%s" (sample %s). A receipt that stops proving will freeze the next event that reaches the same state, so this is fixed in the receipt before it does.',
                g.n, GREATEST(COALESCE(p_hours,24),1), g.err, g.sample),
         jsonb_build_object('checked_at', now(), 'hours', GREATEST(COALESCE(p_hours,24),1), 'refusal', g.err, 'count', g.n, 'sample_tournament_id', g.sample, 'samples', g.ids)
    FROM (SELECT regexp_replace(f->>'error', '[0-9a-f-]{36}', '<id>', 'g') err, count(*) n, min(f->>'tournament_id') sample,
                 jsonb_agg(f->>'tournament_id') ids
            FROM jsonb_array_elements(v_fail) f GROUP BY 1) g
   WHERE NOT EXISTS (SELECT 1 FROM public.financial_alerts fa
                      WHERE fa.source='fn_ca_replay_terminal_receipts' AND NOT fa.resolved
                        AND fa.context->>'refusal' = g.err);
  GET DIAGNOSTICS v_raised = ROW_COUNT;

  -- A refusal that no longer reproduces closes itself.
  UPDATE public.financial_alerts fa
     SET resolved = true, resolved_at = now(),
         resolution = format('Re-measured by fn_ca_replay_terminal_receipts at %s: %s receipt(s) of the last %s h replayed, none refuses with this text any more.', now(), v_ok, GREATEST(COALESCE(p_hours,24),1))
   WHERE fa.source='fn_ca_replay_terminal_receipts' AND NOT fa.resolved
     AND v_refused = 0 AND v_ok > 0
     AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_fail) f
                      WHERE regexp_replace(f->>'error', '[0-9a-f-]{36}', '<id>', 'g') = fa.context->>'refusal');
  GET DIAGNOSTICS v_resolved = ROW_COUNT;

  RETURN jsonb_build_object('ok', true, 'checked_at', now(), 'hours', GREATEST(COALESCE(p_hours,24),1),
    'replayed', v_ok, 'refused', v_refused, 'skipped_locked', v_locked, 'raised', v_raised, 'resolved', v_resolved, 'failures', v_fail);
END;
$$;


ALTER FUNCTION public.fn_ca_replay_terminal_receipts(p_hours integer, p_limit integer) OWNER TO postgres;

--
-- TOC entry 4674 (class 1255 OID 184452040)
-- Name: fn_ca_reporting_rollups_from_facts(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_reporting_rollups_from_facts(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_from_day date := public.fn_ca_club_data_facts_from();
  v_lo timestamptz := (p_day::timestamp AT TIME ZONE 'UTC');
  v_hi timestamptz := ((p_day + 1)::timestamp AT TIME ZONE 'UTC');
  v_zero constant uuid := '00000000-0000-0000-0000-000000000000';
  v_tables bigint; v_players bigint; v_tournaments bigint;
BEGIN
  IF p_day IS NULL OR p_day > v_today OR v_from_day IS NULL OR p_day < v_from_day THEN
    RETURN jsonb_build_object('day', p_day, 'skipped', 'outside_club_data_facts', 'facts_from', v_from_day);
  END IF;
  IF now() < v_hi + interval '10 minutes' THEN
    PERFORM pg_advisory_xact_lock(918273645);
  END IF;

  DELETE FROM public.club_table_daily WHERE stat_date = p_day;
  DELETE FROM public.ca_club_table_player_daily WHERE stat_date = p_day;
  DELETE FROM public.ca_club_player_daily WHERE stat_date = p_day;
  DELETE FROM public.ca_club_tournament_daily WHERE stat_date = p_day;
  DELETE FROM public.ca_club_tournament_player_daily WHERE stat_date = p_day;

  WITH rr AS MATERIALIZED (
    SELECT r.id, r.table_id, r.created_at, t.union_id, t.club_id AS table_club,
           CASE WHEN jsonb_typeof(r.player_contributions) = 'object' THEN r.player_contributions ELSE '{}'::jsonb END AS pc
      FROM public.rake_records r
      JOIN public.tables t ON t.id = r.table_id AND t.tournament_id IS NULL
     WHERE r.created_at >= v_lo AND r.created_at < v_hi
       AND r.rake_amount > 0 AND r.tournament_id IS NULL AND NOT COALESCE(r.is_tournament, false)
  ), contrib AS (
    SELECT rr.id, rr.table_id, rr.created_at, rr.union_id, rr.table_club, e.key::uuid AS uid
      FROM rr CROSS JOIN LATERAL jsonb_each_text(rr.pc) e
     WHERE e.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       AND (CASE WHEN e.value ~ '^[0-9]+(\.[0-9]+)?$' THEN e.value::numeric ELSE 0 END) > 0
  ), clubbed AS (
    SELECT c.id, c.table_id,
           COALESCE(ra.club_id, rc.club, st.club,
                    public.fn_ca_cash_reporting_club(c.union_id, c.table_club, c.uid)) AS club_id,
           c.created_at
      FROM contrib c
      LEFT JOIN public.rake_attributions ra ON ra.rake_record_id = c.id AND ra.player_id = c.uid
      LEFT JOIN LATERAL (
        SELECT x.funding_club_id AS club FROM public.cash_participant_funding_receipts x
         WHERE ra.club_id IS NULL AND x.operation_kind = 'buyin' AND x.table_id = c.table_id
           AND x.account_entity_id = c.uid AND x.seat_joined_at <= c.created_at
         ORDER BY x.seat_joined_at DESC LIMIT 1) rc ON true
      LEFT JOIN LATERAL (
        SELECT ts.club_id AS club FROM public.table_seats ts
         WHERE ra.club_id IS NULL AND rc.club IS NULL AND ts.table_id = c.table_id
           AND ts.user_id = c.uid AND ts.club_id IS NOT NULL AND ts.joined_at <= c.created_at
         ORDER BY ts.joined_at DESC LIMIT 1) st ON true
  ), hands AS (
    SELECT h.club_id, h.table_id, SUM(h.hands)::int AS hands, SUM(h.src)::int AS src FROM (
      SELECT cl.club_id, cl.table_id, count(DISTINCT cl.id) AS hands, count(*) AS src
        FROM clubbed cl
       WHERE cl.club_id IS NOT NULL AND public.fn_ca_launch_accounting_accepts(cl.club_id, cl.created_at) IS TRUE
       GROUP BY 1, 2
      UNION ALL
      -- A raked hand that named nobody is the table's club's hand.
      SELECT rr.table_club, rr.table_id, count(*), count(*)
        FROM rr
       WHERE rr.table_club IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM contrib c WHERE c.id = rr.id)
       GROUP BY 1, 2) h
     GROUP BY 1, 2
  )
  INSERT INTO public.club_table_daily
    (club_id, table_id, stat_date, union_id, rake, hands, players, buyins, cashouts, net, source_rows, updated_at)
  SELECT f.club_id, f.game_id, p_day, t.union_id,
         SUM(f.fee), COALESCE(MAX(h.hands), 0),
         (count(DISTINCT f.user_id) FILTER (WHERE f.fee > 0 AND f.user_id <> v_zero))::int,
         round(SUM(f.buyins), 2), round(SUM(f.cashouts), 2), round(SUM(f.cashouts) - SUM(f.buyins), 2),
         COALESCE(MAX(h.src), 0), now()
    FROM public.ca_club_data_fact f
    JOIN public.tables t ON t.id = f.game_id
    LEFT JOIN hands h ON h.club_id = f.club_id AND h.table_id = f.game_id
   WHERE f.stat_date = p_day AND f.kind = 'CASH'
   GROUP BY f.club_id, f.game_id, t.union_id;
  GET DIAGNOSTICS v_tables = ROW_COUNT;

  INSERT INTO public.ca_club_table_player_daily (club_id, table_id, stat_date, user_id)
  SELECT DISTINCT f.club_id, f.game_id, p_day, f.user_id
    FROM public.ca_club_data_fact f
   WHERE f.stat_date = p_day AND f.kind = 'CASH' AND f.fee > 0 AND f.user_id <> v_zero
  ON CONFLICT DO NOTHING;

  INSERT INTO public.ca_club_player_daily (club_id, user_id, stat_date, cash_net, tournament_net, updated_at)
  SELECT f.club_id, f.user_id, p_day,
         COALESCE(SUM(f.winnings) FILTER (WHERE f.kind = 'CASH'), 0),
         COALESCE(SUM(f.winnings) FILTER (WHERE f.kind = 'TOURNAMENT'), 0), now()
    FROM public.ca_club_data_fact f
   WHERE f.stat_date = p_day AND f.user_id <> v_zero
   GROUP BY f.club_id, f.user_id
  HAVING bool_or(f.buyins <> 0 OR f.cashouts <> 0);
  GET DIAGNOSTICS v_players = ROW_COUNT;

  INSERT INTO public.ca_club_tournament_daily (club_id, tournament_id, stat_date, fee, winnings, updated_at)
  SELECT f.club_id, f.game_id, p_day, SUM(f.fee), SUM(f.winnings), now()
    FROM public.ca_club_data_fact f
   WHERE f.stat_date = p_day AND f.kind = 'TOURNAMENT'
   GROUP BY f.club_id, f.game_id;
  GET DIAGNOSTICS v_tournaments = ROW_COUNT;

  INSERT INTO public.ca_club_tournament_player_daily (club_id, tournament_id, user_id, stat_date, updated_at)
  SELECT DISTINCT f.club_id, f.game_id, f.user_id, p_day, now()
    FROM public.ca_club_data_fact f
   WHERE f.stat_date = p_day AND f.kind = 'TOURNAMENT' AND f.user_id <> v_zero
     AND (f.buyins <> 0 OR f.cashouts <> 0)
  ON CONFLICT DO NOTHING;

  RETURN jsonb_build_object('day', p_day, 'source', 'ca_club_data_fact', 'table_rows', v_tables,
                            'player_rows', v_players, 'tournament_rows', v_tournaments);
END;
$_$;


ALTER FUNCTION public.fn_ca_reporting_rollups_from_facts(p_day date) OWNER TO postgres;

--
-- TOC entry 9271 (class 1255 OID 27302050)
-- Name: fn_ca_reprice_unpaid_tournament_place(uuid, uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_reprice_unpaid_tournament_place(p_tournament_id uuid, p_user_id uuid, p_expected_prize numeric, p_new_prize numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tournament_status text;
  v_roster_id uuid;
  v_current_prize numeric;
  v_updated_prize numeric;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'tournament prize repricing requires service authority'
      USING ERRCODE='28000';
  END IF;
  IF p_tournament_id IS NULL OR p_user_id IS NULL
     OR p_expected_prize IS NULL OR p_new_prize IS NULL
     OR p_expected_prize::text IN ('NaN','Infinity','-Infinity')
     OR p_new_prize::text IN ('NaN','Infinity','-Infinity')
     OR p_expected_prize<0 OR p_new_prize<0
     OR p_expected_prize<>round(p_expected_prize,2)
     OR p_new_prize<>round(p_new_prize,2) THEN
    RAISE EXCEPTION 'tournament prize repricing requires finite nonnegative exact cents'
      USING ERRCODE='22023';
  END IF;

  -- HOTFIX EDIT (20260911090347): this tournament's settlement lane
  -- (G shared, T(id) exclusive) instead of the raw global key, as
  -- 20260910051125 did for fn_move_tournament_player. A reprice is one
  -- tournament's roster row: it must exclude that tournament's hands and any
  -- terminal authority, not every hand on the platform.
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  SELECT upper(COALESCE(t.status::text,'')) INTO v_tournament_status
    FROM public.tournaments t
   WHERE t.id=p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist',p_tournament_id
      USING ERRCODE='P0002';
  END IF;
  IF v_tournament_status<>'RUNNING' THEN
    RAISE EXCEPTION 'tournament prize repricing requires RUNNING status'
      USING ERRCODE='55000';
  END IF;

  SELECT tp.id,tp.prize::numeric INTO v_roster_id,v_current_prize
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament player does not exist'
      USING ERRCODE='P0002';
  END IF;

  IF EXISTS (SELECT 1 FROM public.tournament_place_settlement_batches b
              WHERE b.tournament_id=p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_satellite_settlement_batches b
                 WHERE b.tournament_id=p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_terminal_settlements h
                 WHERE h.tournament_id=p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_cancellation_receipts c
                 WHERE c.tournament_id=p_tournament_id)
     OR EXISTS (
       SELECT 1 FROM public.tournament_obligations o
        WHERE o.tournament_id=p_tournament_id
          AND o.kind IN (
            'place','bubble_protection','final_table_deal',
            'late_reg_adjustment'))
     OR EXISTS (
       SELECT 1 FROM public.tournament_payouts p
        WHERE p.tournament_id=p_tournament_id
          AND (p.source IN (
            'structure','reconcile','hu_shortfall','late_reg_adjustment',
            'clawback','spin_backpay','overlay_backpay','final_table_deal')
            OR public.fn_tournament_payout_key_is_place_evidence(
                 p.tournament_id,p.idempotency_key))) THEN
    RAISE EXCEPTION
      'tournament prize repricing is closed after prepared or paid terminal evidence'
      USING ERRCODE='55000';
  END IF;

  IF v_current_prize IS DISTINCT FROM p_expected_prize THEN
    RAISE EXCEPTION 'tournament prize changed from expected % to %',
      p_expected_prize,v_current_prize USING ERRCODE='55000';
  END IF;

  UPDATE public.tournament_players tp
     SET prize=p_new_prize
   WHERE tp.id=v_roster_id
     AND tp.tournament_id=p_tournament_id
     AND tp.user_id=p_user_id
     AND tp.prize IS NOT DISTINCT FROM p_expected_prize
  RETURNING tp.prize::numeric INTO v_updated_prize;
  IF NOT FOUND OR v_updated_prize IS DISTINCT FROM p_new_prize THEN
    RAISE EXCEPTION 'tournament prize compare-and-set lost its locked row'
      USING ERRCODE='55000';
  END IF;

  RETURN jsonb_build_object(
    'ok',true,'tournament_id',p_tournament_id,'user_id',p_user_id,
    'prize',v_updated_prize);
END;
$$;


ALTER FUNCTION public.fn_ca_reprice_unpaid_tournament_place(p_tournament_id uuid, p_user_id uuid, p_expected_prize numeric, p_new_prize numeric) OWNER TO postgres;

--
-- TOC entry 4750 (class 1255 OID 218010744)
-- Name: fn_ca_requested_payout_depth(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_requested_payout_depth(p_value text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE v numeric;
BEGIN
  IF p_value IS NULL OR btrim(p_value) !~ '^[0-9]+(\.[0-9]+)?$' THEN RETURN NULL; END IF;
  v := round(btrim(p_value)::numeric, 2);
  RETURN CASE WHEN v > 0 AND v <= 100 THEN v END;
END $_$;


ALTER FUNCTION public.fn_ca_requested_payout_depth(p_value text) OWNER TO postgres;

--
-- TOC entry 7100 (class 1255 OID 18626773)
-- Name: fn_ca_resolution_needs_a_cause(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_resolution_needs_a_cause() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cause text := btrim(coalesce(NEW.root_cause, ''));
  v_ref   text := btrim(coalesce(NEW.correction_ref, ''));
  -- COALESCE, not a bare comparison: a NULL closure_basis must read as "not
  -- aged out" (false), never as NULL, or both fences below silently pass.
  v_aged  boolean := COALESCE(NEW.closure_basis = 'aged_out_unverified', false);
  v_ok    boolean;
BEGIN
  IF NEW.status <> 'resolved' OR OLD.status = 'resolved' THEN
    RETURN NEW;
  END IF;

  IF length(v_cause) < 40 THEN
    RAISE EXCEPTION
      'An incident is not resolved until the cause is written down. Supply root_cause: what was actually wrong, in a sentence (at least 40 characters). Got %.',
      CASE WHEN v_cause = '' THEN 'nothing' ELSE '"' || v_cause || '"' END
      USING ERRCODE = 'P0404';
  END IF;

  -- 2026-09-01: the auto_repair_status='repaired' bypass is GONE. Any writer
  -- could set that flag in the same UPDATE that resolved, which made the law
  -- optional for exactly the actor it was written to govern (the same shape
  -- as the [allow-revert] token incident of 2026-08-31). The automated
  -- reconciler now writes 'verified: <evidence>' like every other resolver.
  --
  -- 2026-09-20: 'aged-out:' joins the list, FENCED OFF from 'verified:' in
  -- BOTH directions. Until today the escalation tick closed a silence-retired
  -- incident with correction_ref 'verified: not seen again for N hours', so an
  -- unread event stream and a re-measured all-clear were recorded with the
  -- same word in the same field - 43 rows carry that wording. Silence is
  -- "I could not tell" (law 10.86 rule 1). It gets its own prefix, and the two
  -- can no longer be mistaken for one another.
  v_ok := v_ref ~* '^(migration\s+\S|PR\s*#\d|chip_ledger\s+\S|correction:\S)'
       OR v_ref ~* '^(ruling:|verified:|no-change-needed:|aged-out:)\s*\S';

  IF NOT v_ok THEN
    RAISE EXCEPTION
      'An incident is not resolved until something stops it happening again. Supply correction_ref as one of: "migration <name>", "PR #<n>", "chip_ledger <id>", "correction:<key>", "ruling: <decision>", "verified: <evidence>", "aged-out: <what went quiet>", or "no-change-needed: <why>". Got %.',
      CASE WHEN v_ref = '' THEN 'nothing' ELSE '"' || v_ref || '"' END
      USING ERRCODE = 'P0404';
  END IF;

  IF v_aged AND v_ref !~* '^aged-out:\s*\S' THEN
    RAISE EXCEPTION
      'closure_basis is ''aged_out_unverified'', so correction_ref must begin "aged-out: ". An incident retired because its event stream went quiet was not verified, and must not be filed under any evidence prefix. Got %.',
      CASE WHEN v_ref = '' THEN 'nothing' ELSE '"' || v_ref || '"' END
      USING ERRCODE = 'P0404';
  END IF;

  IF NOT v_aged AND v_ref ~* '^aged-out:' THEN
    RAISE EXCEPTION
      'correction_ref begins "aged-out: " but closure_basis is %. Set closure_basis to ''aged_out_unverified'', or supply real evidence under one of the other prefixes.',
      COALESCE('''' || NEW.closure_basis || '''', 'not set')
      USING ERRCODE = 'P0404';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_ca_resolution_needs_a_cause() OWNER TO postgres;

--
-- TOC entry 46211 (class 0 OID 0)
-- Dependencies: 7100
-- Name: FUNCTION fn_ca_resolution_needs_a_cause(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_resolution_needs_a_cause() IS 'HARD LAW: an incident cannot enter resolved without a root cause of substance and a correction reference naming what prevents recurrence. On the table rather than in fn_ca_incident_action, because fn_ca_auto_reconcile_tick and raw SQL both bypass that function. Added 2026-09-01 at Dan''s instruction.';


--
-- TOC entry 6362 (class 1255 OID 25445462)
-- Name: fn_ca_resolve_cleared_incidents(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_resolve_cleared_incidents() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '120s'
    AS $$
DECLARE
  d          record;
  v_second   timestamptz;
  v_last     timestamptz;
  v_closed   int := 0;
  v_total    int := 0;
  v_out      jsonb := '[]'::jsonb;
  v_actor    uuid := '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid;
BEGIN
  /* WHAT MAY BE ON THIS LIST. Only a detector whose raise condition looks
     at the whole standing state, so that not raising a finding means the
     finding is gone. fn_ca_quick_reconcile is deliberately absent: it looks
     at a ten minute window, so its silence means the window moved on, not
     that anything was fixed, and auto-closing its criticals would bury real
     unanswered money.
     fn_ca_money_rpc_drift joined on 2026-09-11: it reads every row of
     pg_proc on every run, so a name it stops reporting is registered or
     gone. Before it recorded a run, a dropped function left an incident
     open forever.
     2026-09-20: these closures now stamp closure_basis='verified_remeasured'.
     THIS is the branch that earned the word "verified" - a detector ran twice
     and did not report the finding either time. The escalation tick's
     silence-based retirement is a different outcome and is recorded as
     'aged_out_unverified'; the two must never be read as the same thing. */
  FOR d IN SELECT unnest(ARRAY['fn_ca_conservation_sweep','fn_ca_ratchet_watch','fn_bbj_reconcile','fn_ca_money_rpc_drift']) AS detector
  LOOP
    SELECT ran_at INTO v_last
      FROM public.ca_detector_runs WHERE detector = d.detector
     ORDER BY ran_at DESC LIMIT 1;
    SELECT ran_at INTO v_second
      FROM public.ca_detector_runs WHERE detector = d.detector
     ORDER BY ran_at DESC OFFSET 1 LIMIT 1;

    IF v_second IS NULL THEN
      v_out := v_out || jsonb_build_object('detector', d.detector,
                 'closed', 0, 'why', 'fewer than two recorded runs so far');
      CONTINUE;
    END IF;

    UPDATE public.ca_drift_incidents i
       SET status         = 'resolved',
           closure_basis  = 'verified_remeasured',
           resolved_at    = now(),
           resolved_by    = v_actor,
           root_cause     = 'the measurement that raised this stopped reporting it: '
                         || d.detector || ' completed at ' || v_second::text
                         || ' and again at ' || v_last::text
                         || ' without raising it either time, so the condition it '
                         || 'found no longer holds. Closed by the same measurement '
                         || 'that opened it, never by assumption.',
           correction_ref = 'verified: ' || d.detector || ' ran twice without re-raising this, '
                         || 'most recently at ' || v_last::text,
           resolution     = 'no chips moved to close this. The detector re-measured and '
                         || 'found nothing; if the condition returns, the next run raises '
                         || 'it again with a fresh incident.'
     WHERE i.resolved_at IS NULL
       AND i.source LIKE d.detector || '%'
       AND i.created_at < v_second
       AND i.last_seen_at < v_second;
    GET DIAGNOSTICS v_closed = ROW_COUNT;
    v_total := v_total + v_closed;
    v_out := v_out || jsonb_build_object('detector', d.detector, 'closed', v_closed,
               'clean_since', v_second, 'last_run', v_last);
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'closed', v_total, 'detectors', v_out);
END;
$$;


ALTER FUNCTION public.fn_ca_resolve_cleared_incidents() OWNER TO postgres;

--
-- TOC entry 3618 (class 1255 OID 22297497)
-- Name: fn_ca_resolve_hand_flag(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_resolve_hand_flag(p_flag_id uuid, p_status text, p_operator_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid  uuid := auth.uid();
  v_flag public.ca_hand_flags%ROWTYPE;
  v_note text := NULLIF(btrim(COALESCE(p_operator_note, '')), '');
BEGIN
  IF p_status NOT IN ('open', 'under_review', 'resolved', 'dismissed') THEN
    RAISE EXCEPTION 'unknown status %', p_status USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_flag FROM public.ca_hand_flags WHERE id = p_flag_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such flag' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.fn_ca_is_club_staff(v_flag.club_id, v_uid) THEN
    RAISE EXCEPTION 'not an operator of this club' USING ERRCODE = '42501';
  END IF;

  IF p_status IN ('resolved', 'dismissed') AND v_note IS NULL THEN
    RAISE EXCEPTION 'closing a flag needs a note the player can read'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.ca_hand_flags
     SET status = p_status,
         operator_note = COALESCE(v_note, operator_note),
         reviewed_by = v_uid,
         reviewed_at = now(),
         updated_at = now()
   WHERE id = p_flag_id
   RETURNING * INTO v_flag;

  INSERT INTO public.audit_trail
    (actor_id, actor_role, action, target_type, target_id, club_id, reason, after_state)
  VALUES (
    v_uid,
    public.fn_ca_club_actor_role(v_flag.club_id, v_uid),
    'hand_flag_' || p_status,
    'hand_flag',
    p_flag_id,
    v_flag.club_id,
    v_note,
    jsonb_build_object(
      'hand_id', v_flag.hand_id,
      'hand_number', v_flag.hand_number,
      'status', v_flag.status
    )
  );

  RETURN to_jsonb(v_flag);
END;
$$;


ALTER FUNCTION public.fn_ca_resolve_hand_flag(p_flag_id uuid, p_status text, p_operator_note text) OWNER TO postgres;

--
-- TOC entry 8219 (class 1255 OID 224032664)
-- Name: fn_ca_resolve_landed_unreachable_hand_alerts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_resolve_landed_unreachable_hand_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  r record;
  n integer := 0;
BEGIN
  FOR r IN
    SELECT a.id, c.table_id, c.hand_number, c.committed_at, c.post_commit_completed_at
      FROM public.financial_alerts a
      JOIN public.hand_atomic_commits c
        ON c.table_id    = (a.context->>'table_id')::uuid
       AND c.hand_number = (a.context->>'hand_number')::bigint
     WHERE a.source = 'ServerTableEngine.authoritative_hand_unreachable'
       AND NOT COALESCE(a.resolved, false)
       AND a.context->>'table_id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       AND a.context->>'hand_number' ~ '^[0-9]{1,18}$'
       AND (c.post_commit_payload IS NULL OR c.post_commit_completed_at IS NOT NULL)
       AND EXISTS (SELECT 1 FROM public.hand_history h
                    WHERE h.table_id = c.table_id AND h.hand_number = c.hand_number)
     ORDER BY a.created_at
     LIMIT 200
     FOR UPDATE OF a SKIP LOCKED
  LOOP
    UPDATE public.ca_drift_incidents i
       SET root_cause = COALESCE(NULLIF(i.root_cause, ''), format(
             'Hand #%s on table %s could not be committed inside the engine''s 13 attempt budget because the database did not answer in time; that engine generation stopped with the hand behind its causal barrier and its successor committed the same hand.',
             r.hand_number, r.table_id)),
           correction_ref = COALESCE(NULLIF(i.correction_ref, ''), format(
             'verified: hand_atomic_commits row committed %s, post-commit complete, hand_history row present',
             r.committed_at)),
           closure_basis = COALESCE(i.closure_basis, 'verified_remeasured')
     WHERE i.status <> 'resolved'
       AND i.metadata->>'alert_id' = r.id::text;

    UPDATE public.financial_alerts
       SET resolved = true,
           resolved_at = now(),
           resolution = format(
             'verified: the successor engine committed hand #%s on table %s at %s; post-commit obligations complete%s; hand_history row present. No chips moved for closure.',
             r.hand_number, r.table_id, r.committed_at,
             COALESCE(' at ' || r.post_commit_completed_at::text, ' (none owed)'))
     WHERE id = r.id;
    n := n + 1;
  END LOOP;
  RETURN n;
END
$_$;


ALTER FUNCTION public.fn_ca_resolve_landed_unreachable_hand_alerts() OWNER TO postgres;

--
-- TOC entry 6882 (class 1255 OID 24465708)
-- Name: fn_ca_resolve_unbound_pending_addons(uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_resolve_unbound_pending_addons(p_table_id uuid, p_max_buy_in numeric, p_instance_id text, p_lease_generation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_holder text;
  v_generation uuid;
  v_protocol integer;
  v_heartbeat timestamptz;
  v_tournament_id uuid;
  v_addon public.table_pending_addons%ROWTYPE;
  v_resolution record;
  v_rows jsonb := '[]'::jsonb;
BEGIN
  IF p_table_id IS NULL
     OR p_max_buy_in IS NULL
     OR p_max_buy_in <= 0
     OR length(btrim(COALESCE(p_instance_id, ''))) = 0
     OR p_lease_generation IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_request');
  END IF;

  /* One lock vocabulary with the durable hand processor. Take it first on
     both paths so two pending-row consumers cannot form a reverse lock order
     through resolve_pending_addon's seat lock. */
  PERFORM pg_advisory_xact_lock(
    hashtextextended('hand-post-commit:' || p_table_id::text, 0)
  );

  SELECT l.instance_id, l.lease_generation, l.protocol_version, l.heartbeat_at
    INTO v_holder, v_generation, v_protocol, v_heartbeat
    FROM public.engine_table_leases l
   WHERE l.table_id = p_table_id
   FOR KEY SHARE;
  IF NOT FOUND
     OR v_protocol IS DISTINCT FROM 2
     OR v_holder IS DISTINCT FROM p_instance_id
     OR v_generation IS DISTINCT FROM p_lease_generation
     OR v_heartbeat < clock_timestamp() - make_interval(
          secs => public.fn_engine_lease_stale_seconds()
        ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'lease_lost',
      'lease_generation', v_generation
    );
  END IF;

  /* Exact hand settlement takes lease -> table as well. Holding this row
     through selection and delivery makes "not frozen" a stable statement. */
  SELECT t.tournament_id INTO v_tournament_id
    FROM public.tables t
   WHERE t.id = p_table_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;
  IF v_tournament_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'cash_table_required');
  END IF;

  FOR v_addon IN
    SELECT a.*
      FROM public.table_pending_addons a
     WHERE a.table_id = p_table_id
       AND a.resolved_at IS NULL
       AND NOT EXISTS (
         SELECT 1
           FROM public.hand_atomic_commits c
          WHERE c.table_id = p_table_id
            AND jsonb_typeof(
                  c.post_commit_payload #> '{pending_addons,ids}'
                ) = 'array'
            AND (c.post_commit_payload #> '{pending_addons,ids}') ? a.id::text
       )
     ORDER BY a.created_at, a.id
     FOR UPDATE
  LOOP
    SELECT * INTO STRICT v_resolution
      FROM public.resolve_pending_addon(v_addon.id, p_max_buy_in);
    v_rows := v_rows || jsonb_build_array(jsonb_build_object(
      'id', v_addon.id,
      'user_id', v_addon.user_id,
      'kind', COALESCE(v_addon.kind, 'addon'),
      'applied', COALESCE(v_resolution.applied, 0),
      'refunded', COALESCE(v_resolution.refunded, 0)
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'table_id', p_table_id,
    'lease_generation', p_lease_generation,
    'resolved', jsonb_array_length(v_rows),
    'rows', v_rows
  );
END;
$$;


ALTER FUNCTION public.fn_ca_resolve_unbound_pending_addons(p_table_id uuid, p_max_buy_in numeric, p_instance_id text, p_lease_generation uuid) OWNER TO postgres;

--
-- TOC entry 5002 (class 1255 OID 57415994)
-- Name: fn_ca_restate_must_be_zero_account(uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_restate_must_be_zero_account(p_operation_id uuid, p_account text, p_plan jsonb, p_authorization jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_receipt jsonb; v_before numeric; v_after numeric; v_plan_total numeric := 0;
  v_fp_before jsonb; v_fp_after jsonb; f jsonb; v_legs uuid[]; v_amount numeric;
  v_dir text; v_cp_type text; v_cp_entity uuid; v_n int; v_sum numeric; v_inc uuid;
  v_res jsonb; v_ledger uuid; v_reason text; v_posted int := 0; v_restated int := 0;
  v_findings jsonb := '[]'::jsonb; v_parent uuid; v_meta jsonb;
BEGIN
  IF p_operation_id IS NULL OR COALESCE(p_account, '') = '' THEN
    RAISE EXCEPTION 'operation id and account are required';
  END IF;
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'service_role_required' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('ca-journal-restatement:' || p_account, 0));

  -- A replay is answered from the receipt and posts nothing.
  SELECT to_jsonb(r) INTO v_receipt FROM public.ca_journal_restatements r
   WHERE r.operation_id = p_operation_id;
  IF FOUND THEN
    RETURN jsonb_build_object('ok', true, 'replayed', true, 'corrections_posted', 0,
                              'receipt', v_receipt);
  END IF;
  IF current_setting('transaction_isolation') NOT IN ('repeatable read', 'serializable') THEN
    RAISE EXCEPTION 'repeatable_read_required: the no-chips-move proof compares one snapshot with itself'
      USING ERRCODE = '25001';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.ca_ledger_accounts a
                  WHERE a.account_type = p_account AND a.must_be_zero) THEN
    RAISE EXCEPTION '% is not a must_be_zero account', p_account;
  END IF;
  IF COALESCE(p_authorization ->> 'by', '') = '' OR COALESCE(p_authorization ->> 'text', '') = ''
     OR COALESCE(p_authorization ->> 'on', '') !~ '^\d{4}-\d{2}-\d{2}$' THEN
    RAISE EXCEPTION 'an owner authorization {by, on, text} is required';
  END IF;
  IF jsonb_typeof(p_plan) <> 'array' OR jsonb_array_length(p_plan) = 0 THEN
    RAISE EXCEPTION 'the plan must be a non-empty array of findings';
  END IF;

  SELECT COALESCE(round(sum(CASE WHEN l.to_type = p_account THEN l.amount ELSE -l.amount END), 2), 0)
    INTO v_before
    FROM public.chip_ledger l
   WHERE (l.from_type = p_account) <> (l.to_type = p_account);
  v_fp_before := public.fn_ca_balance_table_fingerprint();

  FOR f IN SELECT value FROM jsonb_array_elements(p_plan) LOOP
    v_dir := f ->> 'direction';
    v_cp_type := f ->> 'counterparty_type';
    v_cp_entity := NULLIF(f ->> 'counterparty_entity', '')::uuid;
    v_amount := (f ->> 'amount')::numeric;
    v_reason := f ->> 'reason';
    SELECT array_agg(value::uuid) INTO v_legs FROM jsonb_array_elements_text(f -> 'legs');
    IF v_dir NOT IN ('out_of_account', 'into_account') OR v_amount IS NULL OR v_amount <= 0
       OR v_amount <> round(v_amount, 2) OR COALESCE(cardinality(v_legs), 0) = 0
       OR COALESCE(f ->> 'finding', '') = '' OR length(COALESCE(v_reason, '')) < 40 THEN
      RAISE EXCEPTION 'finding % is malformed', COALESCE(f ->> 'finding', '?');
    END IF;
    IF v_cp_type IS NULL OR v_cp_type = p_account
       OR NOT EXISTS (SELECT 1 FROM public.ca_chip_store_coverage g WHERE g.store = v_cp_type) THEN
      RAISE EXCEPTION 'finding %: counterparty % is not a declared chip store', f ->> 'finding', v_cp_type;
    END IF;
    -- Every named leg is a live leg on exactly one side of the account, named
    -- once, never restated before, and together they are the finding's amount.
    SELECT count(*), COALESCE(round(sum(CASE WHEN l.to_type = p_account THEN l.amount ELSE -l.amount END), 2), 0)
      INTO v_n, v_sum
      FROM public.chip_ledger l
     WHERE l.id = ANY (v_legs) AND (l.from_type = p_account) <> (l.to_type = p_account)
       AND l.status = 'posted';
    IF v_n <> cardinality(v_legs) OR v_n <> (SELECT count(DISTINCT x) FROM unnest(v_legs) x) THEN
      RAISE EXCEPTION 'finding %: % of % named legs are live % legs', f ->> 'finding', v_n, cardinality(v_legs), p_account;
    END IF;
    IF v_sum <> (CASE WHEN v_dir = 'out_of_account' THEN v_amount ELSE -v_amount END) THEN
      RAISE EXCEPTION 'finding %: legs net % into %, the finding says % %', f ->> 'finding', v_sum, p_account, v_dir, v_amount;
    END IF;
    IF EXISTS (SELECT 1 FROM public.ca_journal_restatement_legs k WHERE k.corrected_leg_id = ANY (v_legs)) THEN
      RAISE EXCEPTION 'finding %: a named leg was already restated', f ->> 'finding';
    END IF;

    v_meta := jsonb_build_object(
      'operation_id', p_operation_id, 'finding', f ->> 'finding',
      'restates_account', p_account, 'legs_restated', v_n,
      'legs_md5', (SELECT md5(string_agg(x::text, ',' ORDER BY x::text)) FROM unnest(v_legs) x),
      'real_counterparty', f ->> 'real_counterparty',
      'evidence', f ->> 'evidence',
      'owner_authorization', p_authorization,
      'leg_map', 'ca_journal_restatement_legs');

    -- The writer's linkage rule: one correction, one live incident.
    v_inc := public.fn_ca_raise_drift_incident(
      'fn_ca_restate_must_be_zero_account', 'historical_migration', 'info',
      'journal-restatement:' || p_operation_id::text || ':' || (f ->> 'finding'),
      v_amount, NULL, NULL, 'ledger', p_account,
      NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      v_reason, true, v_meta);
    IF v_inc IS NULL THEN
      RAISE EXCEPTION 'finding %: the incident filer did not file the linkage incident', f ->> 'finding';
    END IF;

    v_res := public.fn_ca_post_correction(
      CASE WHEN v_dir = 'out_of_account' THEN p_account ELSE v_cp_type END,
      CASE WHEN v_dir = 'out_of_account' THEN NULL ELSE v_cp_entity END,
      CASE WHEN v_dir = 'out_of_account' THEN v_cp_type ELSE p_account END,
      CASE WHEN v_dir = 'out_of_account' THEN v_cp_entity ELSE NULL END,
      v_amount, v_reason, v_inc, NULL, NULL, NULL, v_meta);
    IF COALESCE((v_res ->> 'ok')::boolean, false) IS NOT TRUE
       OR COALESCE((v_res ->> 'replayed')::boolean, true) THEN
      RAISE EXCEPTION 'finding %: the correction writer refused: %', f ->> 'finding', v_res;
    END IF;
    v_ledger := (v_res ->> 'ledger_id')::uuid;

    INSERT INTO public.ca_journal_restatement_legs (corrected_leg_id, operation_id, finding, correction_ledger_id, incident_id)
    SELECT x, p_operation_id, f ->> 'finding', v_ledger, v_inc FROM unnest(v_legs) x;

    UPDATE public.ca_drift_incidents
       SET status = 'resolved', resolved_at = now(), closure_basis = 'repair',
           root_cause = v_reason,
           resolution = format('Journal-only restatement posted by operation %s under the owner authorization of %s: chip_ledger %s restates %s leg(s) of %s against %s. No balance moved.',
                               p_operation_id, p_authorization ->> 'on', v_ledger, v_n, p_account, v_cp_type)
     WHERE id = v_inc AND status <> 'resolved';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'finding %: the linkage incident could not be closed', f ->> 'finding';
    END IF;

    v_plan_total := v_plan_total + CASE WHEN v_dir = 'out_of_account' THEN v_amount ELSE -v_amount END;
    v_posted := v_posted + 1;
    v_restated := v_restated + v_n;
    v_findings := v_findings || jsonb_build_array(jsonb_build_object(
      'finding', f ->> 'finding', 'direction', v_dir, 'counterparty_type', v_cp_type,
      'counterparty_entity', v_cp_entity, 'amount', v_amount, 'legs', v_n,
      'correction_ledger_id', v_ledger, 'incident_id', v_inc));
  END LOOP;

  IF v_plan_total <> v_before THEN
    RAISE EXCEPTION 'the plan restates % but % stands at %', v_plan_total, p_account, v_before;
  END IF;
  SELECT COALESCE(round(sum(CASE WHEN l.to_type = p_account THEN l.amount ELSE -l.amount END), 2), 0)
    INTO v_after
    FROM public.chip_ledger l
   WHERE (l.from_type = p_account) <> (l.to_type = p_account);
  IF v_after <> 0 THEN
    RAISE EXCEPTION '% reads % after the restatement, not 0.00', p_account, v_after;
  END IF;
  v_fp_after := public.fn_ca_balance_table_fingerprint();
  IF v_fp_after IS DISTINCT FROM v_fp_before THEN
    RAISE EXCEPTION 'a balance table changed inside the restatement; nothing is committed';
  END IF;

  -- The standing position was the owner's to decide; it is decided. The
  -- audited baseline is now zero, so any future movement is growth.
  UPDATE public.ca_must_be_zero_state
     SET baseline_balance = 0, baseline_at = now(), updated_at = now(),
         baseline_note = format('re-baselined to 0.00 by journal restatement %s (owner authorization %s, %s); the account stood at %s',
                                p_operation_id, p_authorization ->> 'by', p_authorization ->> 'on', v_before)
   WHERE account_type = p_account;

  SELECT id INTO v_parent FROM public.ca_drift_incidents
   WHERE dedupe_key = 'must-be-zero-balance:' || p_account AND status <> 'resolved';
  IF v_parent IS NOT NULL THEN
    INSERT INTO public.ca_incident_events (incident_id, kind, detail)
    VALUES (v_parent, 'repair_action', jsonb_build_object(
      'journal_restatement', p_operation_id, 'balance_before', v_before,
      'balance_after', v_after, 'corrections_posted', v_posted, 'legs_restated', v_restated,
      'note', 'the balance arm closes this on its next run by re-measuring the account'));
  END IF;

  INSERT INTO public.ca_journal_restatements
    (operation_id, account_type, owner_authorization, balance_before, balance_after, findings,
     legs_restated, corrections_posted, fingerprint_before, fingerprint_after)
  VALUES (p_operation_id, p_account, p_authorization, v_before, v_after, v_findings,
          v_restated, v_posted, v_fp_before, v_fp_after);

  RETURN jsonb_build_object('ok', true, 'replayed', false, 'operation_id', p_operation_id,
    'balance_before', v_before, 'balance_after', v_after, 'corrections_posted', v_posted,
    'legs_restated', v_restated, 'findings', v_findings,
    'balance_tables_identical', v_fp_after = v_fp_before, 'parent_incident', v_parent);
END $_$;


ALTER FUNCTION public.fn_ca_restate_must_be_zero_account(p_operation_id uuid, p_account text, p_plan jsonb, p_authorization jsonb) OWNER TO postgres;

--
-- TOC entry 8831 (class 1255 OID 57416002)
-- Name: fn_ca_restate_settlement_suspense_20260926(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_restate_settlement_suspense_20260926(p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c_operation constant uuid := 'f4a2c6d0-5e1b-4c7a-9d3e-26092026a0b1';
  v_plan jsonb := '[]'::jsonb; r record; v_expected jsonb; v_seen int := 0;
BEGIN
  IF p_operation_id IS DISTINCT FROM c_operation THEN
    RAISE EXCEPTION 'this restatement runs under operation % only', c_operation USING ERRCODE = '22023';
  END IF;
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'service_role_required' USING ERRCODE = '42501';
  END IF;
  IF EXISTS (SELECT 1 FROM public.ca_journal_restatements WHERE operation_id = p_operation_id) THEN
    RETURN public.fn_ca_restate_must_be_zero_account(p_operation_id, 'settlement_suspense', '[{}]'::jsonb, '{}'::jsonb);
  END IF;

  -- The audited findings, read 2026-09-26 from production: legs, net into
  -- suspense, md5 of the comma-joined sorted leg ids. The live journal must
  -- reproduce every one of them exactly or nothing is posted.
  v_expected := '{
    "L01": [416, "4160000.00", "f2892af3679ca77ab4bb35c665cfd5bc"],
    "L02": [3791, "214665.00", "04200e41728d0bb10b09528e180d4a19"],
    "L03": [626, "-41342.04", "ba0ef8859c39e1922be77eb9006f68f1"],
    "L04": [626, "39874.00", "f6e11176137473a47a16cf9ef8e5726d"],
    "L05": [12, "1269.00", "f974432ad6f5983e626c6f26fb194a1b"],
    "L06": [1, "246.82", "4a6d8db36315eb1663ff4acab9f81cbb"],
    "L07": [4, "108.00", "709e20c3c6e80265eb9513043d77a6c9"],
    "L08": [1, "10.00", "800f8343596b4fb5fb6e6648fe452969"],
    "L09": [1023, "-5162.49", "dd59c8017928fe706baca3e54c3564f5"],
    "L10": [27, "-70.75", "f5b308305df9642049a1a167ee3bd859"],
    "L11": [115, "-19.55", "1b1d1b7a89bc8120fccbb0d32e60fca3"],
    "L12": [2, "-119.53", "b8da231396f3af8dfef20a27b4ee176a"],
    "L13": [13, "3423.12", "862e51f3bca52d99ff14c21db751cff9"],
    "L14": [2, "-1977.10", "a15aa6bd42759d7bb67d81db95601a5e"],
    "L15": [2, "-200000.00", "6b1d929db4375ec31d6e0d3032946e9b"],
    "P0":  [8, "0.00", "275611753db15ae1a47bbb238fe4cbea"]
  }'::jsonb;

  FOR r IN
    WITH s AS (
      SELECT l.id, l.created_at, l.amount, l.category, l.from_type, l.to_type,
             l.from_entity_id, l.to_entity_id, l.actor_service,
             CASE WHEN l.to_type = 'settlement_suspense' THEN 1 ELSE -1 END AS dir
        FROM public.chip_ledger l
       WHERE (l.from_type = 'settlement_suspense') <> (l.to_type = 'settlement_suspense')
    ), rn AS (
      SELECT s.*, row_number() OVER (PARTITION BY s.created_at, s.amount, s.dir ORDER BY s.id) AS k FROM s
    ), u AS (
      -- A leg into suspense and a leg out of it at the same instant for the
      -- same amount are one transfer routed through the corridor.
      SELECT a.* FROM rn a
       WHERE NOT EXISTS (SELECT 1 FROM rn b WHERE b.created_at = a.created_at AND b.amount = a.amount
                                              AND b.dir = -a.dir AND b.k = a.k)
    ), c AS (
      SELECT u.*, CASE
        WHEN u.id IN ('a6292d04-16f1-4d75-abe0-aa6a07c68a49','fbe2551d-5cd8-48ae-9a15-1d0712b635a0',
                      'aa5f255d-c54d-4901-acc9-fb1516833edf','c043127d-1fd5-4970-8395-5663a7f760c6',
                      'ffefca1d-830e-45ae-b8fd-9dd35b732367','e7e41bf1-82bc-4bc0-8d08-36db24eda58d',
                      '6eb8b82e-363f-42cf-90cb-0bd324e9c3eb','8d576003-088a-4dc4-8ad8-682da73e4a54') THEN 'P0'
        WHEN u.category = 'adjustment' AND u.actor_service = 'mgmt-api'
         AND u.created_at IN ('2026-09-01 14:59:00.697293+00','2026-09-01 15:08:16.769253+00','2026-09-01 17:06:38.612054+00')
         AND u.dir = 1 THEN 'L13'
        WHEN u.category = 'adjustment' AND u.actor_service = 'mgmt-api'
         AND u.created_at IN ('2026-09-01 14:59:00.697293+00','2026-09-01 15:08:16.769253+00','2026-09-01 17:06:38.612054+00')
         AND u.dir = -1 THEN 'L14'
        WHEN u.category = 'adjustment' AND u.from_type = 'agent_wallet' AND u.dir = 1
         AND EXISTS (SELECT 1 FROM public.chip_ledger t
                      WHERE t.created_at = u.created_at AND t.category = 'adjustment'
                        AND t.from_type = 'table_stack' AND t.from_entity_id IS NULL
                        AND t.to_type = 'player_wallet' AND t.amount = u.amount) THEN 'L01'
        WHEN u.category = 'spin_prize' AND u.from_type = 'spin_reserve' AND u.dir = 1 THEN 'L02'
        WHEN u.category = 'adjustment' AND u.to_type = 'spin_reserve'
         AND u.to_entity_id = '2d968239-acdd-4a2c-99f2-a369ff37ae31' THEN 'L03'
        WHEN u.category = 'adjustment' AND u.from_type = 'spin_reserve'
         AND u.from_entity_id = '2d968239-acdd-4a2c-99f2-a369ff37ae31' THEN 'L04'
        WHEN u.category = 'adjustment' AND u.from_type = 'union_bank' AND u.dir = 1 THEN 'L05'
        WHEN u.id = '68be02a5-4080-47e7-b764-5ed66aeabca9' THEN 'L06'
        WHEN u.category = 'adjustment' AND u.from_type = 'player_wallet' AND u.dir = 1 THEN 'L07'
        WHEN u.id = 'f6130820-de88-4556-a702-4d123306981a' THEN 'L08'
        WHEN u.category = 'adjustment' AND u.to_type = 'union_wallet' AND u.dir = -1 THEN 'L09'
        WHEN u.category = 'adjustment' AND u.to_type = 'club_wallet' AND u.dir = -1 THEN 'L10'
        WHEN u.category = 'adjustment' AND u.to_type = 'bbj_pool' AND u.dir = -1 THEN 'L11'
        WHEN u.category = 'adjustment' AND u.to_type = 'player_wallet' AND u.dir = -1 THEN 'L12'
        WHEN u.id IN ('da015b72-7435-41eb-a0ad-ad47f584e584','e0ef00c2-6a90-4426-9e6a-ffcb17554e88') THEN 'L15'
      END AS finding
      FROM u
    )
    SELECT COALESCE(c.finding, 'UNCLASSIFIED') AS finding, count(*) AS legs,
           round(sum(c.dir * c.amount), 2) AS net,
           md5(string_agg(c.id::text, ',' ORDER BY c.id)) AS ids_md5,
           jsonb_agg(c.id ORDER BY c.id) AS ids
      FROM c GROUP BY 1 ORDER BY 1
  LOOP
    IF NOT (v_expected ? r.finding)
       OR (v_expected -> r.finding ->> 0)::int <> r.legs
       OR (v_expected -> r.finding ->> 1)::numeric <> r.net
       OR (v_expected -> r.finding ->> 2) <> r.ids_md5 THEN
      RAISE EXCEPTION 'the live journal no longer matches the audited finding %: % legs, net %, md5 %',
        r.finding, r.legs, r.net, r.ids_md5;
    END IF;
    v_seen := v_seen + 1;
    CONTINUE WHEN r.finding = 'P0';
    v_plan := v_plan || jsonb_build_array(jsonb_build_object(
      'finding', r.finding,
      'direction', CASE WHEN r.net > 0 THEN 'out_of_account' ELSE 'into_account' END,
      'counterparty_type', CASE r.finding WHEN 'L13' THEN 'chip_retirement'
                                          WHEN 'L14' THEN 'issuance_reserve'
                                          WHEN 'L15' THEN 'issuance_reserve'
                                          ELSE 'table_stack' END,
      'counterparty_entity', NULL,
      'amount', abs(r.net),
      'legs', r.ids,
      'real_counterparty', CASE r.finding
        WHEN 'L01' THEN 'the member wallets credited by 416 agent distributions (each leg''s same-instant table_stack(NULL) -> player_wallet twin)'
        WHEN 'L02' THEN 'the winners of 3,791 completed spins, paid through table_stack(NULL) -> player_wallet; prize_liability of a terminal tournament refuses new evidence'
        WHEN 'L03' THEN 'the buy-ins of pre-declaration spins, journaled player_wallet -> table_stack(NULL)'
        WHEN 'L04' THEN 'the winners of pre-declaration spins, paid through table_stack(NULL) -> player_wallet'
        WHEN 'L05' THEN 'the prize pools of twelve completed tournaments whose flows are journaled at table_stack(NULL)'
        WHEN 'L06' THEN 'duplicate-place overpays of six completed tournaments, already paid through table_stack(NULL)'
        WHEN 'L07' THEN 'the prize pools of four completed tournaments (terminal evidence), held at table_stack(NULL)'
        WHEN 'L08' THEN 'a 10.00 tournament buy-in whose event the write failure never named'
        WHEN 'L09' THEN 'the felt the union rake came off; the leg does not name the table'
        WHEN 'L10' THEN 'the felt the rake mirror counted; the leg does not name the table'
        WHEN 'L11' THEN 'the felt the jackpot contributions came off; the leg does not name the table'
        WHEN 'L12' THEN 'the felt two cash-outs left; the leg does not name the table'
        WHEN 'L13' THEN 'chips retired by the owner-ordered resets of 2026-09-01'
        WHEN 'L14' THEN 'chips issued by the owner-ordered opening baseline of 2026-09-01'
        WHEN 'L15' THEN 'the unjournaled 100,000.00 opening grants of two certification clubs, later retired' END,
      'evidence', 'fn_ca_restate_settlement_suspense_20260926 finding ' || r.finding,
      'reason', 'Journal-only restatement of settlement_suspense (owner authorization 2026-09-26, "Post correction legs to zero it"): '
        || r.legs || ' unpaired leg(s) of finding ' || r.finding || ' netting ' || r.net
        || ' into suspense are restated against their real counterparty. No chip moves.'));
  END LOOP;
  IF v_seen <> 16 THEN
    RAISE EXCEPTION 'expected 16 audited findings, the live journal shows %', v_seen;
  END IF;

  RETURN public.fn_ca_restate_must_be_zero_account(
    p_operation_id, 'settlement_suspense', v_plan,
    jsonb_build_object('by', 'Dan (owner)', 'on', '2026-09-26',
                       'text', 'Post correction legs to zero it',
                       'policy', 'owner policy 2.9'));
END $$;


ALTER FUNCTION public.fn_ca_restate_settlement_suspense_20260926(p_operation_id uuid) OWNER TO postgres;

