--
-- TOC entry 7339 (class 1255 OID 37193464)
-- Name: fn_ca_retain_hand_submission(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_retain_hand_submission(p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE s smarter_private.hand_submissions; h smarter_private.f06_hand_permits;
 d smarter_private.hand_submission_dispositions;
 tid uuid; hn bigint; sid uuid; instance text; generation uuid; tour uuid; locked_tour uuid;
 holder text; lease uuid; protocol integer; beat timestamptz; request_hash text;
BEGIN
 IF jsonb_typeof(p_request) IS DISTINCT FROM 'object'
 OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_request) k) IS DISTINCT FROM
 ARRAY['p_bbj','p_hand_number','p_hand_row','p_inflow','p_instance_id','p_lease_generation','p_post_commit_obligations','p_rake','p_ref','p_stacks','p_table_id','p_units']
 OR jsonb_typeof(p_request->'p_stacks') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_request->'p_hand_row') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_request->'p_post_commit_obligations') IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_request->'p_units') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'HAND_SUBMISSION_INVALID_REQUEST' USING ERRCODE='22023';
 END IF;
 tid:=(p_request->>'p_table_id')::uuid; hn:=(p_request->>'p_hand_number')::bigint;
 sid:=(p_request->'p_hand_row'->>'id')::uuid;
 instance:=p_request->>'p_instance_id'; generation:=(p_request->>'p_lease_generation')::uuid;
 IF tid IS NULL OR hn IS NULL OR hn<=0 OR sid IS NULL OR generation IS NULL OR length(btrim(COALESCE(instance,'')))=0
 OR (p_request->'p_hand_row'->>'table_id')::uuid IS DISTINCT FROM tid
 OR (p_request->'p_hand_row'->>'hand_number')::bigint IS DISTINCT FROM hn THEN
  RAISE EXCEPTION 'HAND_SUBMISSION_INVALID_IDENTITY' USING ERRCODE='22023';
 END IF;
 PERFORM public.fn_ca_share_settlement_lane_for_table(tid);
 PERFORM smarter_private.assert_retained_hand_submission(p_request);
 SELECT * INTO s FROM smarter_private.hand_submissions WHERE table_id=tid AND hand_number=hn;
 IF FOUND THEN
  RETURN jsonb_build_object('retained',true,'submission_id',s.submission_id,'request_hash',s.request_hash,'replay',true);
 END IF;
 SELECT * INTO h FROM smarter_private.f06_hand_permits WHERE table_id=tid AND hand_number=hn;
 IF FOUND THEN
  IF NOT pg_try_advisory_xact_lock(hashtextextended('f06:hand:'||h.permit_id::text,0)) THEN
   RAISE EXCEPTION 'F06_HAND_DISPATCH_BUSY' USING ERRCODE='55P03'; END IF;
  SELECT * INTO STRICT h FROM smarter_private.f06_hand_permits WHERE permit_id=h.permit_id;
  IF h.state NOT IN ('reserved','accepted') OR h.generation IS DISTINCT FROM generation THEN
   RAISE EXCEPTION 'HAND_SUBMISSION_PERMIT_FENCED' USING ERRCODE='55000'; END IF;
 END IF;
 SELECT tournament_id INTO tour FROM public.tables WHERE id=tid;
 IF NOT FOUND THEN RAISE EXCEPTION 'HAND_SUBMISSION_TABLE_MISSING' USING ERRCODE='55000'; END IF;
 IF tour IS NOT NULL AND (h.permit_id IS NULL OR h.tournament_id IS DISTINCT FROM tour) THEN
  RAISE EXCEPTION 'HAND_SUBMISSION_ORIGINAL_PERMIT_REQUIRED' USING ERRCODE='55000'; END IF;
 IF tour IS NULL THEN
  SELECT instance_id,lease_generation,protocol_version,heartbeat_at INTO holder,lease,protocol,beat
  FROM public.engine_table_leases WHERE table_id=tid FOR KEY SHARE;
 ELSE
  SELECT instance_id,lease_generation,protocol_version,heartbeat_at INTO holder,lease,protocol,beat
  FROM public.engine_tournament_leases WHERE tournament_id=tour FOR KEY SHARE;
 END IF;
 -- A LAPSED CASH LEASE STILL RETAINS ITS FINISHED HAND (2026-10-04). Retention
 -- moves no money: fn_ca_resume_hand_submission settles the request only under
 -- a successor's own fresh lease, after proving the original never settled it
 -- and that every chair, before-stack and hand number is unchanged. A cash
 -- original whose heartbeat went stale while its finished hand was in flight
 -- may therefore still retain it while the lease names its exact instance and
 -- generation. Taken, released or re-claimed still refuses. A tournament
 -- retention keeps the fresh-heartbeat requirement.
 IF holder IS DISTINCT FROM instance OR lease IS DISTINCT FROM generation OR protocol IS DISTINCT FROM 2
 OR beat IS NULL OR (tour IS NOT NULL
   AND beat<clock_timestamp()-make_interval(secs=>public.fn_engine_lease_stale_seconds())) THEN
  RAISE EXCEPTION 'HAND_SUBMISSION_LEASE_UNPROVEN' USING ERRCODE='55000'; END IF;
 IF tour IS NOT NULL THEN PERFORM 1 FROM public.tournaments WHERE id=tour FOR SHARE; END IF;
 SELECT tournament_id INTO locked_tour FROM public.tables WHERE id=tid FOR UPDATE;
 IF NOT FOUND OR locked_tour IS DISTINCT FROM tour THEN
  RAISE EXCEPTION 'HAND_SUBMISSION_SCOPE_CHANGED' USING ERRCODE='55000'; END IF;
 INSERT INTO smarter_private.hand_submission_dispositions(table_id,hand_number,permit_id,disposition,submission_id)
 VALUES(tid,hn,h.permit_id,'retained',sid) ON CONFLICT(table_id,hand_number) DO NOTHING;
 SELECT * INTO STRICT d FROM smarter_private.hand_submission_dispositions WHERE table_id=tid AND hand_number=hn;
 IF d.disposition<>'retained' OR d.submission_id IS DISTINCT FROM sid OR d.permit_id IS DISTINCT FROM h.permit_id THEN
  RAISE EXCEPTION 'HAND_SUBMISSION_PERMIT_DISPOSED' USING ERRCODE='55000'; END IF;
 request_hash:=encode(extensions.digest(convert_to(p_request::text,'UTF8'),'sha256'),'hex');
 INSERT INTO smarter_private.hand_submissions(submission_id,table_id,hand_number,instance_id,lease_generation,request,request_hash)
 VALUES(sid,tid,hn,instance,generation,p_request,request_hash);
 RETURN jsonb_build_object('retained',true,'submission_id',sid,'request_hash',request_hash,'replay',false);
END $$;


ALTER FUNCTION public.fn_ca_retain_hand_submission(p_request jsonb) OWNER TO postgres;

--
-- TOC entry 3943 (class 1255 OID 20169800)
-- Name: fn_ca_retire_certification_club(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_retire_certification_club(p_club_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club     public.clubs%ROWTYPE;
  v_reason   text := COALESCE(NULLIF(btrim(p_reason), ''), 'cert-cleanup');
  v_retired  numeric := 0;
  v_members  integer := 0;
  v_bad      integer := 0;
  v_tx       integer := 0;
  v_ev       integer := 0;
  v_protected uuid[] := ARRAY[
    'a0000000-0000-0000-0000-000000000001'::uuid,  -- Club JAQK
    'a41434bb-8d0c-400a-8f0d-e8b3d65afed4'::uuid,  -- SHARK CLUB
    '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid,  -- Deep Stack Society
    'fade0000-0000-0000-0000-000000000001'::uuid   -- Midway Union
  ];
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND current_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'service_role_only' USING ERRCODE = '42501';
  END IF;

  IF p_club_id = ANY (v_protected) THEN
    RETURN jsonb_build_object('success', false, 'error', 'that is a real Club Arena estate, not a fixture');
  END IF;

  SELECT * INTO v_club FROM public.clubs WHERE id = p_club_id FOR UPDATE;
  IF v_club.id IS NULL THEN
    RETURN jsonb_build_object('success', true, 'already_gone', true, 'club_id', p_club_id);
  END IF;

  IF v_club.name NOT LIKE 'Crest Cert %' AND v_club.name NOT LIKE 'Preset Crest Cert %' THEN
    RETURN jsonb_build_object('success', false, 'error', 'not a certification fixture by name',
                              'name', v_club.name);
  END IF;
  IF v_club.union_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'a fixture never belongs to a union');
  END IF;
  IF EXISTS (SELECT 1 FROM public.tables t WHERE t.club_id = p_club_id)
     OR EXISTS (SELECT 1 FROM public.tournaments t WHERE t.club_id = p_club_id)
     OR EXISTS (SELECT 1 FROM public.agents a WHERE a.club_id = p_club_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'this club has played: it is not a fixture');
  END IF;

  SELECT count(*) INTO v_members FROM public.club_members m WHERE m.club_id = p_club_id;
  SELECT count(*) INTO v_bad
    FROM public.club_members m
    LEFT JOIN auth.users u ON u.id = m.user_id
   WHERE m.club_id = p_club_id
     AND NOT (
       COALESCE(u.email, '') LIKE '%@smarter-poker.invalid'
       OR COALESCE(u.email, '') LIKE 'ca-customization-cert-postdeploy-%@example.invalid'
     );
  IF v_bad > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'a real member holds this club',
                              'non_cert_members', v_bad);
  END IF;
  IF EXISTS (SELECT 1 FROM public.club_members m
              WHERE m.club_id = p_club_id
                AND (COALESCE(m.chip_balance, 0) <> 0 OR COALESCE(m.promo_balance, 0) <> 0)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'a fixture member still holds chips');
  END IF;

  /* RETIRE THE CHIPS FIRST. chip_retirement is a non-circulating store, so the
     supply meter reads this as a burn and not as chips vanishing. */
  v_retired := round(COALESCE(v_club.chip_treasury, 0)
                   + COALESCE(v_club.chip_pool, 0)
                   + COALESCE(v_club.promo_balance, 0)
                   + COALESCE(v_club.insurance_balance, 0), 2);

  IF v_retired <> 0 THEN
    PERFORM public.fn_ca_declare_ledger('burn', 'chip_retirement', NULL, NULL,
                                        'cert-retire:' || p_club_id::text, NULL);
    UPDATE public.clubs
       SET chip_treasury     = 0,
           chip_pool         = 0,
           promo_balance     = 0,
           insurance_balance = 0,
           updated_at        = now()
     WHERE id = p_club_id;
    PERFORM set_config('app.ledger_category', '', true);
    PERFORM set_config('app.ledger_counterparty', '', true);
  END IF;

  /* Both append-only doors, opened by name and closed again below. */
  PERFORM set_config('app.ledger_maintenance', v_reason || ':' || p_club_id::text, true);
  PERFORM set_config('app.game_management_retention', 'on', true);

  /* Order matters. The journal rows go first (their club still exists, so the
     archive records a complete row). The members go next, while the club is
     still there for the event their removal emits. Then that event, and only
     then the club itself. */
  DELETE FROM public.chip_transactions WHERE club_id = p_club_id;
  GET DIAGNOSTICS v_tx = ROW_COUNT;

  DELETE FROM public.club_members WHERE club_id = p_club_id;

  DELETE FROM public.game_management_events WHERE club_id = p_club_id;
  GET DIAGNOSTICS v_ev = ROW_COUNT;

  DELETE FROM public.clubs WHERE id = p_club_id;

  PERFORM set_config('app.ledger_maintenance', '', true);
  PERFORM set_config('app.game_management_retention', '', true);

  RETURN jsonb_build_object('success', true, 'club_id', p_club_id, 'name', v_club.name,
                            'chips_retired', v_retired, 'members_removed', v_members,
                            'journal_rows_archived', v_tx, 'events_removed', v_ev);
END
$$;


ALTER FUNCTION public.fn_ca_retire_certification_club(p_club_id uuid, p_reason text) OWNER TO postgres;

--
-- TOC entry 46230 (class 0 OID 0)
-- Dependencies: 3943
-- Name: FUNCTION fn_ca_retire_certification_club(p_club_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_retire_certification_club(p_club_id uuid, p_reason text) IS 'Service-only certification cleanup. Accepts only guarded Crest Cert clubs whose members use the dedicated smarter-poker.invalid domain or the exact shared UI postdeploy fixture namespace.';


--
-- TOC entry 4947 (class 1255 OID 83832882)
-- Name: fn_ca_retire_welcome_certification_club(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_retire_welcome_certification_club(p_club_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_post_reset boolean;
  v_leases jsonb; v_origins jsonb; v_board jsonb; v_schedule jsonb;
  v_prepared jsonb; v_retired jsonb; v_child numeric:=0;
BEGIN
  SELECT EXISTS(SELECT 1 FROM public.club_welcome_reset_receipts r
    WHERE r.club_id=p_club_id AND COALESCE((r.result->>'ok')::boolean,false))
    INTO v_post_reset;
  IF v_post_reset THEN
    v_prepared:=public.fn_ca_prepare_post_reset_welcome_certification_fixture(p_club_id);
    IF NOT COALESCE((v_prepared->>'prepared')::boolean,false) THEN
      RAISE EXCEPTION 'POST_RESET_CERTIFICATION_PREPARATION_REFUSED: %',
        COALESCE(v_prepared->>'reason','unknown') USING ERRCODE='55000';
    END IF;
  ELSE
    v_leases:=public.fn_ca_prepare_unused_welcome_certification_board_leases(p_club_id);
    v_origins:=public.fn_ca_prepare_unused_welcome_certification_board_origins(p_club_id);
    v_board:=public.fn_ca_prepare_unused_welcome_certification_board_games(p_club_id);
    v_schedule:=public.fn_ca_prepare_unused_welcome_certification_schedule_spawns(p_club_id);
    v_prepared:=public.fn_ca_prepare_unused_welcome_certification_fixture(p_club_id);
    v_child:=COALESCE((v_prepared->>'child_chips_retired')::numeric,0);
  END IF;
  v_retired:=public.fn_ca_retire_certification_club(p_club_id,p_reason);
  IF COALESCE((v_prepared->>'prepared')::boolean,false)
     AND NOT COALESCE((v_retired->>'success')::boolean,false) THEN
    RAISE EXCEPTION 'WELCOME_CERTIFICATION_RETIREMENT_REFUSED: %',
      COALESCE(v_retired->>'error','unknown') USING ERRCODE='55000';
  END IF;
  IF COALESCE((v_retired->>'success')::boolean,false)
     AND NOT COALESCE((v_retired->>'already_gone')::boolean,false) THEN
    v_retired:=jsonb_set(v_retired,'{chips_retired}',
      to_jsonb(round(COALESCE((v_retired->>'chips_retired')::numeric,0)+v_child,2)),true);
    v_retired:=v_retired||jsonb_build_object('child_chips_retired',v_child,
      'cleanup_state',CASE WHEN v_post_reset THEN 'post_reset' ELSE 'pristine' END,
      'board_tournament_leases_removed',COALESCE((v_leases->>'tournament_leases_removed')::integer,0),
      'board_origins_removed',COALESCE((v_origins->>'origins_removed')::integer,0),
      'board_tournaments_removed',COALESCE((v_board->>'tournaments_removed')::integer,0),
      'board_tables_removed',COALESCE((v_board->>'tables_removed')::integer,0),
      'schedule_tournaments_removed',COALESCE((v_schedule->>'tournaments_removed')::integer,0),
      'schedule_tables_removed',COALESCE((v_schedule->>'tables_removed')::integer,0));
  END IF;
  RETURN v_retired;
END
$$;


ALTER FUNCTION public.fn_ca_retire_welcome_certification_club(p_club_id uuid, p_reason text) OWNER TO postgres;

--
-- TOC entry 8243 (class 1255 OID 18204887)
-- Name: fn_ca_retry_promo_accruals(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_retry_promo_accruals(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; v_res jsonb; v_ok int := 0; v_failed int := 0;
BEGIN
  FOR r IN SELECT * FROM public.ca_pending_promo_accruals
           WHERE resolved_at IS NULL ORDER BY created_at
           LIMIT GREATEST(COALESCE(p_limit,200),1)
  LOOP
    BEGIN
      v_res := public.promo_apply_playthrough(r.club_id, r.user_id, r.wagered);
      UPDATE public.ca_pending_promo_accruals
         SET resolved_at = now(), attempts = attempts + 1, last_attempt_at = now(),
             last_error = NULL
       WHERE id = r.id;
      v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.ca_pending_promo_accruals
         SET attempts = attempts + 1, last_attempt_at = now(), last_error = left(SQLERRM, 500)
       WHERE id = r.id;
      v_failed := v_failed + 1;
    END;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'redriven', v_ok, 'failed', v_failed);
END $$;


ALTER FUNCTION public.fn_ca_retry_promo_accruals(p_limit integer) OWNER TO postgres;

--
-- TOC entry 9091 (class 1255 OID 84217230)
-- Name: fn_ca_return_excess_start_overlay_locked(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_return_excess_start_overlay_locked(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  c_system_actor constant uuid := '2d1cd6c3-5700-4af9-a271-d4863fdab20d';
  v_t public.tournaments%ROWTYPE;
  v_key text;
  v_sources integer;
  v_from_type text;
  v_from_entity uuid;
  v_first_leg uuid;
  v_funded numeric;
  v_returned numeric;
  v_pool numeric;
  v_guarantee numeric;
  v_seat_guarantee numeric;
  v_target_id uuid;
  v_collected numeric;
  v_target numeric;
  v_excess numeric;
  v_before numeric;
  v_after numeric;
  v_ledger_id uuid;
BEGIN
  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id = p_tournament_id FOR UPDATE;
  IF NOT FOUND OR COALESCE(v_t.prize_pool_finalized, false) THEN
    RETURN NULL;  -- a finalized pool is never repriced
  END IF;
  /* 2026-10-06 (20261007000010): A DIAMOND GUARANTEE IS A FLOOR TOO. When the
     prize pool closes, a Diamond event's pool is brought to exactly
     max(guarantee, collected): overlay the entries collected since lock made
     unnecessary returns from the custody to the house, and any guarantee
     still uncovered is paid from its earmark. One function, the same one the
     lock uses; the unused earmark is released. */
  IF public.fn_poker_diamond_tournament(p_tournament_id) THEN
    v_excess := public.fn_poker_diamond_tournament_settle_overlay(p_tournament_id, 'finalize',
                  public.fn_poker_diamond_tournament_effective_guarantee(p_tournament_id));
    PERFORM public.fn_poker_diamond_guarantee_release(p_tournament_id, 'finalize');
    IF v_excess = 0 THEN RETURN NULL; END IF;
    UPDATE public.tournaments SET prize_pool = round(COALESCE(prize_pool, 0) + v_excess, 2)
     WHERE id = p_tournament_id;
    RETURN jsonb_build_object('asset', 'diamonds', 'bank_type', 'diamond_house',
      'overlay_delta', v_excess, 'amount', GREATEST(-v_excess, 0),
      'pool_before', round(COALESCE(v_t.prize_pool, 0), 2),
      'pool_after', round(COALESCE(v_t.prize_pool, 0) + v_excess, 2));
  END IF;
  v_key := 'tourney:' || p_tournament_id::text || ':guarantee_overlay_excess_return';
  IF EXISTS (SELECT 1 FROM public.chip_ledger l WHERE l.idempotency_key = v_key) THEN
    RETURN NULL;
  END IF;

  -- The start-time legs fn_ca_fund_overlay_on_lock wrote (the finalization
  -- leg carries its own idempotency key and cannot exist before finalizing).
  SELECT count(DISTINCT (l.from_type, l.from_entity_id)), min(l.from_type),
         (array_agg(l.from_entity_id ORDER BY l.created_at, l.id))[1],
         (array_agg(l.id ORDER BY l.created_at, l.id))[1],
         round(COALESCE(sum(l.amount), 0), 2)
    INTO v_sources, v_from_type, v_from_entity, v_first_leg, v_funded
    FROM public.chip_ledger l
   WHERE l.tournament_id = p_tournament_id
     AND l.category = 'overlay'
     AND l.to_type = 'prize_liability'
     AND l.to_entity_id = p_tournament_id
     AND l.from_type IN ('union_bank', 'club_treasury')
     AND l.idempotency_key IS DISTINCT FROM 'tourney:' || p_tournament_id::text || ':guarantee_overlay'
     AND COALESCE(l.description, '') NOT LIKE 'auto-ledgered%';
  IF COALESCE(v_funded, 0) <= 0 OR v_sources <> 1 THEN
    RETURN NULL;
  END IF;
  SELECT round(COALESCE(sum(r.amount), 0), 2) INTO v_returned
    FROM public.chip_ledger r
   WHERE r.tournament_id = p_tournament_id AND r.category = 'reversal'
     AND r.from_type = 'prize_liability' AND r.from_entity_id = p_tournament_id
     AND r.metadata->>'kind' = 'reviewed_void_overlay_return';
  v_funded := round(v_funded - v_returned, 2);
  IF v_funded <= 0 THEN RETURN NULL; END IF;

  v_pool := round(COALESCE(v_t.prize_pool, 0), 2);
  v_guarantee := round(COALESCE(v_t.guaranteed_prize, 0), 2);
  -- The same effective guarantee the lock trigger funded: a satellite's
  -- guaranteed seats are worth target buy-in + fee each.
  IF COALESCE(v_t.satellite_seats, 0) > 0
     AND (v_t.variant = 'satellite'
          OR upper(COALESCE(v_t.tournament_type, '')) = 'SATELLITE'
          OR v_t.satellite_target_id IS NOT NULL) THEN
    v_target_id := COALESCE(v_t.satellite_target_id, v_t.satellite_target);
    IF v_target_id IS NOT NULL THEN
      SELECT round((COALESCE(t2.buy_in_amount, 0) + COALESCE(t2.buy_in_fee, 0)) * v_t.satellite_seats, 2)
        INTO v_seat_guarantee FROM public.tournaments t2 WHERE t2.id = v_target_id;
      v_guarantee := GREATEST(v_guarantee, COALESCE(v_seat_guarantee, 0));
    END IF;
  END IF;

  v_collected := round(v_pool - v_funded, 2);
  v_target := GREATEST(v_guarantee, v_collected);
  v_excess := round(LEAST(v_funded, GREATEST(0, v_pool - v_target)), 2);
  IF v_excess <= 0 THEN RETURN NULL; END IF;

  -- Lock order of the finalization core: tournament, escrow, then the bank.
  PERFORM 1 FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id FOR UPDATE;
  IF v_from_type = 'union_bank' THEN
    SELECT round(COALESCE(chip_balance, 0), 2) INTO v_before FROM public.union_wallets
     WHERE union_id = v_from_entity FOR UPDATE;
    IF NOT FOUND THEN RETURN NULL; END IF;
    PERFORM set_config('app.ledger_autoskip_union_wallets', '1', true);
    UPDATE public.union_wallets SET chip_balance = chip_balance + v_excess, updated_at = now()
     WHERE union_id = v_from_entity RETURNING round(chip_balance, 2) INTO v_after;
    PERFORM set_config('app.ledger_autoskip_union_wallets', '0', true);
  ELSE
    SELECT round(COALESCE(chip_treasury, 0), 2) INTO v_before FROM public.clubs
     WHERE id = v_from_entity FOR UPDATE;
    IF NOT FOUND THEN RETURN NULL; END IF;
    PERFORM set_config('app.ledger_autoskip_clubs', '1', true);
    UPDATE public.clubs SET chip_treasury = COALESCE(chip_treasury, 0) + v_excess, updated_at = now()
     WHERE id = v_from_entity RETURNING round(chip_treasury, 2) INTO v_after;
    PERFORM set_config('app.ledger_autoskip_clubs', '0', true);
  END IF;
  IF v_after IS DISTINCT FROM round(v_before + v_excess, 2) THEN
    RAISE EXCEPTION 'excess overlay return did not credit its bank exactly'
      USING ERRCODE = '55000';
  END IF;

  INSERT INTO public.chip_ledger (
    performed_by, from_type, from_entity_id, to_type, to_entity_id,
    amount, category, club_id, tournament_id, description, idempotency_key, metadata)
  VALUES (
    c_system_actor, 'prize_liability', p_tournament_id, v_from_type, v_from_entity,
    v_excess, 'reversal', v_t.club_id, p_tournament_id,
    format('Guarantee overlay excess returned to its source: %s (%s) collected %s against its %s guarantee, so the %s start-time overlay needed only %s',
           COALESCE(v_t.name, 'tournament'), p_tournament_id, v_collected, v_guarantee,
           v_funded, round(v_funded - v_excess, 2)),
    v_key,
    jsonb_build_object('kind', 'reviewed_void_overlay_return',
      'reason', 'guarantee_overlay_excess_at_finalization',
      'original_overlay_ledger_id', v_first_leg, 'funded_overlay', v_funded,
      'collected', v_collected, 'guarantee', v_guarantee,
      'pool_before', v_pool, 'pool_after', round(v_pool - v_excess, 2),
      'source_balance_before', v_before, 'source_balance_after', v_after))
  RETURNING id INTO v_ledger_id;
  PERFORM public.fn_ca_escrow_apply(p_tournament_id, 'guarantee overlay excess return',
                                    p_overlay_in => -v_excess);

  UPDATE public.tournaments
     SET prize_pool = round(v_pool - v_excess, 2)
   WHERE id = p_tournament_id;

  RETURN jsonb_build_object('amount', v_excess, 'bank_type', v_from_type,
    'bank_entity_id', v_from_entity, 'funded_overlay', v_funded,
    'collected', v_collected, 'guarantee', v_guarantee,
    'pool_before', v_pool, 'pool_after', round(v_pool - v_excess, 2),
    'ledger_id', v_ledger_id);
END;
$$;


ALTER FUNCTION public.fn_ca_return_excess_start_overlay_locked(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 8005 (class 1255 OID 25581441)
-- Name: fn_ca_return_satellite_entitlement_as_ticket(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_return_satellite_entitlement_as_ticket(p_entitlement_id uuid, p_source text, p_description text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_e public.tournament_refund_entitlements%ROWTYPE;
  v_t public.tournaments%ROWTYPE;
  v_tournament_id uuid;
  v_ticket public.tournament_tickets%ROWTYPE;
  v_key text;
  v_before numeric;
  v_rows integer;
  v_ledger_id uuid;
  v_tx_id uuid;
BEGIN
  IF p_entitlement_id IS NULL OR p_source IS NULL
     OR length(btrim(p_source))=0 OR p_description IS NULL
     OR length(btrim(p_description))=0 THEN
    RAISE EXCEPTION 'satellite ticket return received an invalid contract'
      USING ERRCODE = '22003';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.ca_settle_sources s
     WHERE s.source=lower(btrim(p_source))) THEN
    RAISE EXCEPTION 'satellite ticket return source % is not an authority',p_source
      USING ERRCODE = '42501';
  END IF;
  SELECT e.tournament_id INTO v_tournament_id
    FROM public.tournament_refund_entitlements e
   WHERE e.id=p_entitlement_id;
  IF v_tournament_id IS NULL THEN
    RAISE EXCEPTION 'satellite refund entitlement % does not exist',p_entitlement_id
      USING ERRCODE = 'P0002';
  END IF;
  PERFORM public.fn_ca_lock_settlement_lane_global();
  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=v_tournament_id FOR UPDATE;
  SELECT * INTO v_e FROM public.tournament_refund_entitlements e
   WHERE e.id=p_entitlement_id FOR UPDATE;
  IF v_e.id IS NULL
     OR v_e.entitlement_kind NOT IN ('satellite_seat','tournament_ticket')
     OR v_e.tournament_id IS DISTINCT FROM v_t.id THEN
    RAISE EXCEPTION
      'entitlement % is not a satellite-funded tournament entry',p_entitlement_id
      USING ERRCODE = 'P0404';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tournament_refund_tranches tr
     WHERE tr.entitlement_id=v_e.id) THEN
    RAISE EXCEPTION 'satellite seat entitlement was incorrectly converted to chips'
      USING ERRCODE = 'P0404';
  END IF;
  SELECT * INTO v_ticket FROM public.tournament_tickets tk
   WHERE tk.source_refund_entitlement_id=v_e.id FOR UPDATE;
  IF FOUND THEN
    SELECT count(*),min(l.id::text)::uuid
      INTO v_rows,v_ledger_id FROM public.chip_ledger l
     WHERE l.idempotency_key='tourney:'||v_e.tournament_id::text
             ||':satellite-ticket-return:'||v_e.id::text
       AND l.from_type='prize_liability'
       AND l.from_entity_id=v_e.tournament_id
       AND l.to_type='escrow' AND l.to_entity_id=v_ticket.id
       AND l.club_id=v_e.refund_wallet_club_id AND l.amount=v_e.gross;
    IF v_rows<>1 OR v_ledger_id IS NULL
       OR (SELECT count(*) FROM public.chip_transactions ct
            WHERE ct.transaction_type='tournament_ticket_issue'
              AND ct.club_id=v_e.refund_wallet_club_id
              AND ct.from_user_id IS NULL AND ct.to_user_id=v_e.user_id
              AND ct.amount=v_e.gross
              AND ct.metadata->>'ticket_id'=v_ticket.id::text
              AND ct.metadata->>'entitlement_id'=v_e.id::text
              AND ct.metadata->>'ledger_id'=v_ledger_id::text) <> 1
       OR v_ticket.status NOT IN ('issued','redeemed')
       OR v_ticket.holder_id IS DISTINCT FROM v_e.user_id
       OR v_ticket.value IS DISTINCT FROM v_e.gross
       OR v_ticket.redemption_mode<>'tournament_entry_only'
       OR v_ticket.source_tournament_id IS DISTINCT FROM v_e.tournament_id
       OR v_ticket.source_satellite_id IS DISTINCT FROM v_e.source_satellite_id
       OR v_ticket.source_refund_entitlement_id IS DISTINCT FROM v_e.id
       OR v_ticket.entry_prize IS DISTINCT FROM v_e.refund_prize
       OR v_ticket.entry_bounty IS DISTINCT FROM v_e.refund_bounty
       OR v_ticket.entry_fee IS DISTINCT FROM v_e.refund_fee THEN
      RAISE EXCEPTION 'satellite ticket replay evidence is incomplete'
        USING ERRCODE = 'P0404';
    END IF;
    RETURN jsonb_build_object(
      'ok',true,'replayed',true,'ticket_id',v_ticket.id,
      'entitlement_id',v_e.id,'value',v_e.gross,
      'refund_prize',v_e.refund_prize,
      'refund_bounty',v_e.refund_bounty,'refund_fee',v_e.refund_fee,
      'refund_wallet_club_id',v_e.refund_wallet_club_id);
  END IF;

  PERFORM public.fn_ca_escrow_apply(
    v_e.tournament_id,'satellite ticket return escrow prelock');
  SELECT round(e.prize_balance+e.bounty_balance+e.fee_balance,2)
    INTO v_before FROM public.tournament_escrow e
   WHERE e.tournament_id=v_e.tournament_id FOR UPDATE;
  IF v_before IS NULL THEN
    RAISE EXCEPTION 'satellite ticket return has no enforced target escrow'
      USING ERRCODE = 'P0404';
  END IF;
  v_ticket.id:=gen_random_uuid();
  INSERT INTO public.tournament_tickets(
    id,club_id,issued_by,holder_id,value,status,note,
    redemption_mode,source_tournament_id,source_satellite_id,
    source_refund_entitlement_id,entry_prize,entry_bounty,entry_fee,created_at)
  VALUES(
    v_ticket.id,v_e.refund_wallet_club_id,
    '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid,
    v_e.user_id,v_e.gross,'issued',
    p_description,'tournament_entry_only',v_e.tournament_id,
    v_e.source_satellite_id,v_e.id,v_e.refund_prize,v_e.refund_bounty,
    v_e.refund_fee,transaction_timestamp())
  RETURNING * INTO v_ticket;
  v_key:='tourney:'||v_e.tournament_id::text
         ||':satellite-ticket-return:'||v_e.id::text;
  INSERT INTO public.chip_ledger(
    performed_by,from_type,from_entity_id,from_label,
    to_type,to_entity_id,to_label,amount,category,club_id,tournament_id,
    idempotency_key,settlement_id,actor_service,description,metadata,
    pre_from_balance,post_from_balance,pre_to_balance,post_to_balance)
  VALUES(
    COALESCE(auth.uid(),'2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
    'prize_liability',v_e.tournament_id,'tournaments escrow',
    'escrow',v_ticket.id,'satellite tournament entry ticket',
    v_e.gross,'ticket_issue',v_e.refund_wallet_club_id,v_e.tournament_id,
    v_key,'satellite-ticket:'||v_ticket.id::text,lower(btrim(p_source)),
    p_description,jsonb_build_object(
      'kind','tournament_entry_ticket_return','ticket_id',v_ticket.id,
      'entitlement_id',v_e.id,'user_id',v_e.user_id,
      'entitlement_kind',v_e.entitlement_kind,
      'source_satellite_id',v_e.source_satellite_id,
      'refund_prize',v_e.refund_prize,'refund_bounty',v_e.refund_bounty,
      'refund_fee',v_e.refund_fee),
    v_before,round(v_before-v_e.gross,2),0,v_e.gross)
  RETURNING id INTO v_ledger_id;
  INSERT INTO public.chip_transactions(
    club_id,from_user_id,to_user_id,amount,transaction_type,notes,
    balance_after,metadata)
  VALUES(
    v_e.refund_wallet_club_id,NULL,v_e.user_id,v_e.gross,
    'tournament_ticket_issue',p_description,NULL,jsonb_build_object(
      'ticket_id',v_ticket.id,'escrow_entity_id',v_ticket.id,
      'holder_id',v_e.user_id,'value',v_e.gross,
      'redemption_mode','tournament_entry_only',
      'source_tournament_id',v_e.tournament_id,
      'source_satellite_id',v_e.source_satellite_id,
      'entitlement_id',v_e.id,'entitlement_kind',v_e.entitlement_kind,
      'ledger_id',v_ledger_id,
      'idempotency_key',v_key))
  RETURNING id INTO v_tx_id;
  PERFORM public.fn_ca_escrow_apply_exact_refund(
    v_e.tournament_id,'satellite seat returned as tournament ticket',
    v_e.refund_prize,v_e.refund_bounty,v_e.refund_fee);
  RETURN jsonb_build_object(
    'ok',true,'replayed',false,'ticket_id',v_ticket.id,
    'entitlement_id',v_e.id,'value',v_e.gross,
    'refund_prize',v_e.refund_prize,
    'refund_bounty',v_e.refund_bounty,'refund_fee',v_e.refund_fee,
    'refund_wallet_club_id',v_e.refund_wallet_club_id,
    'ledger_id',v_ledger_id,'transaction_id',v_tx_id);
END;
$$;


ALTER FUNCTION public.fn_ca_return_satellite_entitlement_as_ticket(p_entitlement_id uuid, p_source text, p_description text) OWNER TO postgres;

--
-- TOC entry 4203 (class 1255 OID 18763335)
-- Name: fn_ca_return_unawarded_spin_draws(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_return_unawarded_spin_draws(p_apply boolean DEFAULT false, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    r record; v_n int := 0; v_chips numeric := 0; v_bal numeric; v_amt numeric;
    v_ids uuid[] := '{}';
  BEGIN
    FOR r IN
      SELECT l.tournament_id, l.club_id,
             round(sum(CASE WHEN l.kind = 'jackpot_draw'   THEN -l.amount ELSE 0 END), 2) AS drawn,
             round(sum(CASE WHEN l.kind = 'surplus_return' THEN  l.amount ELSE 0 END), 2) AS returned,
             round(COALESCE(max(e.prize_balance), 0), 2) AS escrow_left
        FROM public.spin_reserve_ledger l
        JOIN public.tournaments t ON t.id = l.tournament_id
        LEFT JOIN public.tournament_escrow e ON e.tournament_id = l.tournament_id
       WHERE t.status IN ('CANCELLED', 'CANCELED', 'COMPLETED')
         AND COALESCE(t.ended_at, l.created_at) < now() - interval '10 minutes'
         AND l.tournament_id IS NOT NULL
       GROUP BY l.tournament_id, l.club_id
      HAVING round(COALESCE(max(e.prize_balance), 0), 2) > 0
         AND round(sum(CASE WHEN l.kind = 'jackpot_draw' THEN -l.amount ELSE 0 END), 2)
           > round(sum(CASE WHEN l.kind = 'surplus_return' THEN l.amount ELSE 0 END), 2)
       ORDER BY 5 DESC
       LIMIT GREATEST(p_limit, 1)
    LOOP
      /* The escrow says what is left; the reserve ledger says what can be
         owed back. Return the smaller of the two and nothing more. */
      v_amt := round(LEAST(r.escrow_left, r.drawn - r.returned), 2);
      IF v_amt <= 0 THEN CONTINUE; END IF;

      v_n := v_n + 1;
      v_chips := v_chips + v_amt;
      v_ids := v_ids || r.tournament_id;

      IF p_apply THEN
        /* spin_entry is the category fn_ca_escrow_on_reserve_leg reads, so
           the escrow moves with the chips rather than beside them. */
        PERFORM set_config('app.ledger_category', 'spin_entry', true);
        PERFORM set_config('app.ledger_counterparty', 'prize_liability', true);
        PERFORM set_config('app.ledger_counterparty_entity', r.tournament_id::text, true);

        UPDATE public.spin_bonus_pools
           SET balance = balance + v_amt
         WHERE club_id = r.club_id
        RETURNING balance INTO v_bal;

        PERFORM set_config('app.ledger_category', '', true);
        PERFORM set_config('app.ledger_counterparty', '', true);
        PERFORM set_config('app.ledger_counterparty_entity', '', true);

        IF FOUND THEN
          INSERT INTO public.spin_reserve_ledger
            (club_id, tournament_id, kind, amount, balance_after, note)
          VALUES (r.club_id, r.tournament_id, 'surplus_return', v_amt, v_bal,
                  'the part of the jackpot draw this spin never spent, returned to the reserve');

          UPDATE public.tournament_escrow
             SET closed_at = now(),
                 close_note = 'unspent spin draw returned to the reserve by fn_ca_return_unawarded_spin_draws'
           WHERE tournament_id = r.tournament_id
             AND closed_at IS NULL
             AND abs(COALESCE(prize_balance, 0)) < 0.005
             AND abs(COALESCE(bounty_balance, 0)) < 0.005
             AND abs(COALESCE(fee_balance, 0)) < 0.005;
        END IF;
      END IF;
    END LOOP;

    RETURN jsonb_build_object('ok', true, 'applied', p_apply,
                              'spins', v_n, 'chips_returned', round(v_chips, 2),
                              'tournament_ids', to_jsonb(v_ids));
  END;
  $$;


ALTER FUNCTION public.fn_ca_return_unawarded_spin_draws(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- TOC entry 46236 (class 0 OID 0)
-- Dependencies: 4203
-- Name: FUNCTION fn_ca_return_unawarded_spin_draws(p_apply boolean, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_return_unawarded_spin_draws(p_apply boolean, p_limit integer) IS 'Returns the jackpot draw to the spin reserve for any CANCELLED spin that never credited a prize. Idempotent: acts only where draws exceed draw_returned.';


--
-- TOC entry 5495 (class 1255 OID 35302707)
-- Name: fn_ca_satellite_cohort_receipt(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_satellite_cohort_receipt(p_tournament_id uuid, p_observed_qualifier_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_accounting jsonb; v_deferred boolean := false;
  v_h public.tournament_satellite_settlements%ROWTYPE;
  v_source record;
  v_target record;
  v_source_escrow public.tournament_escrow%ROWTYPE;
  v_rake_settlement record;
  v_field_size integer;
  v_position_count integer;
  v_rows integer;
  v_expected_rows integer;
  v_amount numeric;
  v_rake numeric;
  v_awards jsonb := '[]'::jsonb;
  v_seats jsonb := '[]'::jsonb;
  v_remainder jsonb := NULL;
  v_source_table_ids uuid[];
  v_source_seat_ids uuid[];
  v_durable_released_ids uuid[];
  v_durable_released_count integer;
  v_diamond boolean := false;              -- DIAMOND PHASE 9
  v_entry_prize numeric;                   -- 2026-10-16: the target entry split
  v_entry_bounty numeric;                  -- 2026-10-16: the target entry split
BEGIN
  -- Browser receipt reads take the same outer locks as manager/finish reads.
  -- Acquire them before the header or any target row, never after a row lock.
  -- Reading an already committed receipt does not require an activated ABI.
  PERFORM public.fn_ca_lock_mtt_admission_contract();
  PERFORM public.fn_ca_lock_settlement_lane_for_satellite_finish(p_tournament_id);
  IF p_tournament_id IS NULL OR p_observed_qualifier_ids IS NULL THEN
    RAISE EXCEPTION 'satellite receipt requires tournament and observed qualifier ids'
      USING ERRCODE = '22004';
  END IF;

  SELECT * INTO v_h
    FROM public.tournament_satellite_settlements s
   WHERE s.tournament_id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'satellite % has no immutable settlement header',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF v_h.receipt_version IS DISTINCT FROM 3 OR v_h.winner_id IS NOT NULL
     OR v_h.qualifier_ids IS DISTINCT FROM p_observed_qualifier_ids THEN
    RAISE EXCEPTION 'satellite cohort receipt identity differs' USING ERRCODE='55000';
  END IF;

  v_diamond := public.fn_poker_diamond_tournament(p_tournament_id);  -- DIAMOND PHASE 9
  -- Target lifecycle state is intentionally absent from replay. A target may
  -- close after commit without changing what was already delivered.
  PERFORM 1 FROM public.tournaments t
   WHERE t.id IN (p_tournament_id, v_h.target_id)
   ORDER BY CASE WHEN t.id = v_h.target_id THEN 0 ELSE 1 END, t.id
   FOR UPDATE;
  SELECT t.id, t.status, t.variant, t.tournament_type,
         t.satellite_target_id, t.satellite_target, t.satellite_seats,
         t.prize_pool, t.prize_pool_finalized, t.ended_at,
         t.current_players, t.on_break, t.break_started_at, t.break_ends_at
    INTO v_source FROM public.tournaments t
   WHERE t.id = p_tournament_id;
  IF v_source.id IS NULL THEN
    RAISE EXCEPTION 'satellite % source row is missing',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF upper(COALESCE(v_source.status, '')) <> 'COMPLETED'
     OR COALESCE(v_source.prize_pool_finalized, false) IS NOT TRUE
     OR v_source.ended_at IS NULL
     OR v_source.ended_at IS DISTINCT FROM v_h.source_closed_at
     OR v_source.current_players IS DISTINCT FROM 0
     OR v_source.on_break IS DISTINCT FROM false
     OR v_source.break_started_at IS NOT NULL
     OR v_source.break_ends_at IS NOT NULL THEN
    RAISE EXCEPTION 'satellite % receipt is not attached to one completed close',
      p_tournament_id USING ERRCODE = '55000';
  END IF;
  IF lower(COALESCE(v_source.variant, '')) <> 'satellite'
     AND upper(COALESCE(v_source.tournament_type, '')) <> 'SATELLITE'
     AND v_source.satellite_target_id IS NULL
     AND v_source.satellite_target IS NULL THEN
    RAISE EXCEPTION 'tournament % no longer identifies as a satellite',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF v_source.satellite_target_id IS NOT NULL
     AND v_source.satellite_target IS NOT NULL
     AND v_source.satellite_target_id IS DISTINCT FROM v_source.satellite_target THEN
    RAISE EXCEPTION 'satellite % has conflicting target columns',
      p_tournament_id USING ERRCODE = '23514';
  END IF;
  IF COALESCE(v_source.satellite_target_id, v_source.satellite_target)
       IS DISTINCT FROM v_h.target_id
     OR v_source.prize_pool IS NULL
     OR v_source.prize_pool::text IN ('NaN','Infinity','-Infinity')
     OR round(v_source.prize_pool, 2) IS DISTINCT FROM v_h.pool
     OR COALESCE(v_source.satellite_seats, 0) IS DISTINCT FROM v_h.advertised_seats
     OR v_h.pool < v_h.advertised_seats * v_h.ticket_cost
     OR floor(v_h.pool / v_h.ticket_cost)::integer IS DISTINCT FROM v_h.ticket_award_count
     OR round(v_h.pool - v_h.ticket_award_count * v_h.ticket_cost, 2)
          IS DISTINCT FROM v_h.remainder THEN
    RAISE EXCEPTION 'satellite % immutable receipt disagrees with its locked contract',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT t.id,t.buy_in_amount,t.buy_in_fee,t.bounty_amount,t.is_bounty,
         t.is_pko,t.is_mystery_bounty,t.is_premium_spin,t.variant,
         t.tournament_type,t.club_id
    INTO v_target FROM public.tournaments t
   WHERE t.id = v_h.target_id
   FOR SHARE;
  -- A delivered seat or ticket into a bounty target carries the target's
  -- own entry split (2026-10-16). The economic columns are immutable after
  -- the first seat or ticket, so the split read now is the one booked.
  SELECT s.prize, s.bounty INTO v_entry_prize, v_entry_bounty
    FROM public.fn_tournament_entry_split(
      v_h.target_buy_in, v_h.target_fee, v_target.bounty_amount,
      COALESCE(v_target.is_bounty,false) OR COALESCE(v_target.is_pko,false)
        OR COALESCE(v_target.is_mystery_bounty,false)) s;
  IF v_target.id IS NULL
     OR v_h.target_was_missing IS DISTINCT FROM false
     OR v_h.target_contract_version IS NOT NULL
     OR ((v_h.seat_count > 0 OR v_h.entry_ticket_count > 0) AND (
          v_target.buy_in_amount IS DISTINCT FROM v_h.target_buy_in
       OR COALESCE(v_target.buy_in_fee,0) IS DISTINCT FROM v_h.target_fee
       OR v_entry_prize IS NULL OR v_entry_bounty IS NULL
       OR v_entry_prize < 0 OR v_entry_bounty < 0
       OR round(v_entry_prize + v_entry_bounty, 2)
            IS DISTINCT FROM v_h.target_buy_in
       OR (v_diamond AND v_entry_bounty <> 0)
       OR COALESCE(v_target.is_premium_spin,false)
       OR lower(COALESCE(v_target.variant,'')) = 'spin'
       OR upper(COALESCE(v_target.tournament_type,'')) = 'SPIN')) THEN
    RAISE EXCEPTION 'satellite % immutable receipt lost its locked target row',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  -- The header is the immutable settlement-time contract. Replay proves that
  -- exact value through its award, transfer and fee evidence. The terminal
  -- hardening migration also freezes the target's economic columns after its
  -- first actual seat, so cancellation and unregister use the same split.

  PERFORM 1 FROM public.tournament_players tp
   WHERE tp.tournament_id IN (p_tournament_id, v_h.target_id)
   ORDER BY tp.tournament_id, tp.id FOR SHARE;
  PERFORM public.fn_ca_assert_satellite_cohort_standings(p_tournament_id);

  -- A satellite is not terminal while its felt still owns live seats. The
  -- header freezes every source table and seat identity, plus the subset that
  -- this settlement itself released. Replay requires the exact same durable
  -- rows, every table closed at zero and no live seat left behind.
  PERFORM 1 FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id
   ORDER BY tb.id FOR UPDATE;
  PERFORM 1
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.tournament_id = p_tournament_id
   ORDER BY ts.table_id, ts.id FOR UPDATE OF ts;
  SELECT COALESCE(array_agg(tb.id ORDER BY tb.id), ARRAY[]::uuid[])
    INTO v_source_table_ids
    FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id;
  SELECT COALESCE(array_agg(ts.id ORDER BY ts.table_id, ts.id), ARRAY[]::uuid[])
    INTO v_source_seat_ids
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.tournament_id = p_tournament_id;
  SELECT COALESCE(array_agg(ts.id ORDER BY ts.table_id, ts.id), ARRAY[]::uuid[])
    INTO v_durable_released_ids
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.tournament_id = p_tournament_id
     AND ts.left_at IS NOT DISTINCT FROM v_h.settled_at
     AND ts.status IS NOT DISTINCT FROM 'left'
     AND ts.leave_pending IS FALSE
     AND ts.is_sitting_out IS FALSE
     AND ts.is_away IS FALSE
     AND ts.sit_out_at IS NULL
     AND ts.scheduled_leave_hands IS NULL;
  v_durable_released_count := cardinality(v_durable_released_ids);
  IF v_source_table_ids IS DISTINCT FROM v_h.source_table_ids
     OR cardinality(v_source_table_ids) IS DISTINCT FROM v_h.source_table_count
     OR v_source_seat_ids IS DISTINCT FROM v_h.source_seat_ids
     OR cardinality(v_source_seat_ids) IS DISTINCT FROM v_h.source_seat_count
     OR v_durable_released_ids IS DISTINCT FROM v_h.released_seat_ids
     OR v_durable_released_count IS DISTINCT FROM v_h.released_seat_count
     OR EXISTS (
       SELECT 1 FROM public.tables tb
        WHERE tb.tournament_id = p_tournament_id
          AND (lower(COALESCE(tb.status::text, '')) <> 'closed'
            OR lower(COALESCE(tb.lifecycle, '')) <> 'closed'
            OR tb.current_players IS DISTINCT FROM 0
            OR tb.terminal_closed_at IS DISTINCT FROM v_h.source_closed_at)
     ) OR EXISTS (
       SELECT 1
        FROM public.table_seats ts
         JOIN public.tables tb ON tb.id = ts.table_id
        WHERE tb.tournament_id = p_tournament_id
          AND (ts.left_at IS NULL
            OR ts.status IS DISTINCT FROM 'left'
            OR ts.leave_pending IS DISTINCT FROM false
            OR ts.is_sitting_out IS DISTINCT FROM false
            OR ts.is_away IS DISTINCT FROM false
            OR ts.sit_out_at IS NOT NULL
            OR ts.scheduled_leave_hands IS NOT NULL)
     ) THEN
    RAISE EXCEPTION
      'satellite % source table or seat closeout differs from its immutable receipt',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*) INTO v_rows
    FROM public.tournament_satellite_awards a
   WHERE a.tournament_id = p_tournament_id;
  IF v_rows <> v_h.ticket_award_count
     OR (SELECT count(*) FROM public.tournament_satellite_awards a
          WHERE a.tournament_id = p_tournament_id AND a.delivery_kind = 'seat')
          <> v_h.seat_count
     OR (SELECT count(*) FROM public.tournament_satellite_awards a
          WHERE a.tournament_id = p_tournament_id AND a.delivery_kind = 'cash')
          <> v_h.cash_ticket_count
     OR (SELECT count(*) FROM public.tournament_satellite_awards a
          WHERE a.tournament_id = p_tournament_id AND a.delivery_kind = 'ticket')
          <> v_h.entry_ticket_count
     OR EXISTS (
       SELECT 1
         FROM public.tournament_satellite_awards a
         JOIN public.tournament_players tp
           ON tp.tournament_id = p_tournament_id AND tp.user_id = a.user_id
        WHERE a.tournament_id = p_tournament_id
          AND (a.place > v_h.ticket_award_count
            OR tp.user_id IS NULL
            OR a.user_id IS DISTINCT FROM CASE WHEN a.place<=cardinality(v_h.qualifier_ids)
                 THEN v_h.qualifier_ids[a.place]
                 ELSE (SELECT x.user_id FROM public.tournament_players x WHERE x.tournament_id=p_tournament_id AND x.position=a.place) END
            OR a.amount IS DISTINCT FROM v_h.ticket_cost)
     ) OR EXISTS (
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.tournament_id = p_tournament_id
          AND (tp.user_id=ANY(v_h.qualifier_ids) OR tp.position BETWEEN cardinality(v_h.qualifier_ids)+1 AND v_h.ticket_award_count)
          AND NOT EXISTS (
            SELECT 1 FROM public.tournament_satellite_awards a
             WHERE a.tournament_id = p_tournament_id
               AND a.user_id = tp.user_id)
     ) THEN
    RAISE EXCEPTION 'satellite % has incomplete or non-contiguous award lines',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- Every line has one exact payout row. Cash lines additionally prove the
  -- wallet credit and closed obligation; seats prove the registration and
  -- source-to-target funding leg below.
  IF EXISTS (
    SELECT 1
      FROM public.tournament_satellite_awards a
      LEFT JOIN public.tournament_payouts p ON p.id = a.payout_id
     WHERE a.tournament_id = p_tournament_id
       AND (p.id IS NULL
         OR p.tournament_id IS DISTINCT FROM p_tournament_id
         OR p.user_id IS DISTINCT FROM a.user_id
         OR p."position" IS DISTINCT FROM (SELECT tp.position FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament_id AND tp.user_id=a.user_id)
         OR p.amount IS DISTINCT FROM a.amount
         OR p.source IS DISTINCT FROM a.payout_source
         OR p.idempotency_key IS DISTINCT FROM a.idempotency_key)
  ) THEN
    RAISE EXCEPTION 'satellite % award line has no exact payout evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.tournament_satellite_awards a
      LEFT JOIN public.tournament_obligations o ON o.id = a.obligation_id
      LEFT JOIN public.wallet_credit_idempotency k ON k.key = a.idempotency_key
     WHERE a.tournament_id = p_tournament_id
       AND a.delivery_kind = 'cash'
       AND (o.id IS NULL
         OR o.tournament_id IS DISTINCT FROM p_tournament_id
         OR o.kind IS DISTINCT FROM a.obligation_kind
         OR o.place IS DISTINCT FROM a.place
         OR o.user_id IS DISTINCT FROM a.user_id
         OR o.amount_owed IS DISTINCT FROM a.amount
         OR o.amount_paid IS DISTINCT FROM a.amount
         OR o.settled_at IS NULL
         OR k.key IS NULL
         OR k.user_id IS DISTINCT FROM a.user_id
         OR k.amount IS DISTINCT FROM a.amount)
  ) THEN
    RAISE EXCEPTION 'satellite % cash ticket has no exact wallet/debt evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- A cap-blocked full award remains the source pool's money but is held in a
  -- noncash, target-scoped ticket escrow. Prove the immutable award identity,
  -- exact issue journal and absence of a wallet credit on every replay.
  IF EXISTS (
    SELECT 1
      FROM public.tournament_satellite_awards a
      LEFT JOIN public.tournament_payouts p ON p.id=a.payout_id
      LEFT JOIN public.tournament_tickets tk ON tk.id=a.ticket_id
      LEFT JOIN public.chip_ledger l
        ON l.idempotency_key=a.idempotency_key||':ticket_escrow'
       AND l.to_type='escrow' AND l.to_entity_id=a.ticket_id
     WHERE a.tournament_id=p_tournament_id
       AND a.delivery_kind='ticket'
       AND (tk.id IS NULL
         OR tk.issued_by IS DISTINCT FROM
              '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid
         OR tk.holder_id IS DISTINCT FROM a.user_id
         OR tk.value IS DISTINCT FROM a.amount
         OR tk.status NOT IN ('issued','redeemed')
         OR tk.redemption_mode IS DISTINCT FROM 'tournament_entry_only'
         OR tk.source_tournament_id IS DISTINCT FROM v_h.target_id
         OR tk.source_satellite_id IS DISTINCT FROM p_tournament_id
         OR tk.source_refund_entitlement_id IS NOT NULL
         OR tk.source_satellite_award_place IS DISTINCT FROM a.place
         OR tk.entry_prize IS DISTINCT FROM v_entry_prize
         OR tk.entry_bounty IS DISTINCT FROM v_entry_bounty
         OR tk.entry_fee IS DISTINCT FROM v_h.target_fee
         OR p.metadata->>'delivery_kind' IS DISTINCT FROM 'ticket'
         OR p.metadata->>'ticket_id' IS DISTINCT FROM tk.id::text
         OR p.metadata->>'satellite_target_id' IS DISTINCT FROM v_h.target_id::text
         OR p.metadata->>'wallet_chips_credited' IS DISTINCT FROM '0'
         OR l.id IS NULL
         OR l.status IS DISTINCT FROM 'posted'
         OR l.from_type IS DISTINCT FROM 'prize_liability'
         OR l.from_entity_id IS DISTINCT FROM p_tournament_id
         OR l.to_type IS DISTINCT FROM 'escrow'
         OR l.to_entity_id IS DISTINCT FROM tk.id
         OR l.amount IS DISTINCT FROM a.amount
         OR l.category IS DISTINCT FROM 'ticket_issue'
         OR l.club_id IS DISTINCT FROM tk.club_id
         OR l.tournament_id IS DISTINCT FROM p_tournament_id
         OR l.settlement_id IS DISTINCT FROM
              'satellite-ticket:'||tk.id::text
         OR l.actor_service IS DISTINCT FROM 'fn_settle_satellite_tournament'
         OR l.pre_from_balance IS DISTINCT FROM
              round(v_h.pool-(a.place-1)*v_h.ticket_cost,2)
         OR l.post_from_balance IS DISTINCT FROM
              round(v_h.pool-a.place*v_h.ticket_cost,2)
         OR l.pre_to_balance IS DISTINCT FROM 0::numeric
         OR l.post_to_balance IS DISTINCT FROM a.amount
         OR l.metadata->>'kind' IS DISTINCT FROM
              'direct_satellite_entry_ticket'
         OR l.metadata->>'delivery_kind' IS DISTINCT FROM 'ticket'
         OR l.metadata->>'ticket_id' IS DISTINCT FROM tk.id::text
         OR l.metadata->>'payout_id' IS DISTINCT FROM a.payout_id::text
         OR l.metadata->>'satellite_id' IS DISTINCT FROM p_tournament_id::text
         OR l.metadata->>'satellite_target_id' IS DISTINCT FROM v_h.target_id::text
         OR l.metadata->>'user_id' IS DISTINCT FROM a.user_id::text
         OR l.metadata->>'award_slot' IS DISTINCT FROM a.place::text
         OR (l.metadata->>'entry_prize')::numeric IS DISTINCT FROM
              v_entry_prize
         OR (l.metadata->>'entry_bounty')::numeric IS DISTINCT FROM v_entry_bounty
         OR (l.metadata->>'entry_fee')::numeric IS DISTINCT FROM v_h.target_fee
         OR l.metadata->>'wallet_chips_credited' IS DISTINCT FROM '0'
         OR EXISTS (
           SELECT 1 FROM public.wallet_credit_idempotency wallet_key
            WHERE wallet_key.key=a.idempotency_key)
         OR (SELECT count(*)
               FROM public.chip_transactions issue_tx
              WHERE issue_tx.transaction_type='tournament_ticket_issue'
                AND issue_tx.club_id=tk.club_id
                AND issue_tx.from_user_id IS NULL
                AND issue_tx.to_user_id=a.user_id
                AND issue_tx.amount=a.amount
                AND issue_tx.metadata->>'ticket_id'=tk.id::text
                AND issue_tx.metadata->>'escrow_entity_id'=tk.id::text
                AND issue_tx.metadata->>'holder_id'=a.user_id::text
                AND (issue_tx.metadata->>'value')::numeric=a.amount
                AND issue_tx.metadata->>'redemption_mode'=
                      'tournament_entry_only'
                AND issue_tx.metadata->>'source_tournament_id'=
                      v_h.target_id::text
                AND issue_tx.metadata->>'source_satellite_id'=
                      p_tournament_id::text
                AND issue_tx.metadata->>'source_award_place'=a.place::text
                AND issue_tx.metadata->>'payout_id'=a.payout_id::text
                AND issue_tx.metadata->>'ledger_id'=l.id::text
                AND issue_tx.metadata->>'idempotency_key'=a.idempotency_key
                AND issue_tx.metadata->>'wallet_chips_credited'='0') <> 1)
  ) OR (SELECT count(*) FROM public.tournament_tickets tk
         WHERE tk.source_satellite_id=p_tournament_id
           AND tk.source_satellite_award_place IS NOT NULL)
       <> v_h.entry_ticket_count
    OR (SELECT count(*) FROM public.chip_ledger l
         WHERE l.from_type='prize_liability'
           AND l.from_entity_id=p_tournament_id
           AND l.category='ticket_issue'
           AND l.metadata->>'kind'='direct_satellite_entry_ticket')
       <> v_h.entry_ticket_count THEN
    RAISE EXCEPTION
      'satellite % direct ticket has no exact noncash escrow evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF v_h.seat_count > 0 AND v_target.id IS NULL THEN
    RAISE EXCEPTION 'satellite % delivered seats into a missing target',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  -- DIAMOND PHASE 9: a Diamond seat is proved by its Diamond evidence - the
  -- satellite's prize-bank row out, the target's funded entry row in with
  -- the target's own parts, and the entry custody row named for the
  -- registration - never by a chip transfer leg or a chip fee row, which a
  -- Diamond seat does not write.
  IF v_diamond AND (EXISTS (
    SELECT 1
      FROM public.tournament_satellite_awards a
      LEFT JOIN public.tournament_players target_player
        ON target_player.id = a.registration_id
      LEFT JOIN public.poker_diamond_tournament_ledger lo
        ON lo.idempotency_key = 'poker-tournament-seat-out:' || a.idempotency_key
      LEFT JOIN public.poker_diamond_tournament_ledger li
        ON li.idempotency_key = 'poker-tournament-seat-in:' || a.idempotency_key
      LEFT JOIN public.poker_diamond_custody c
        ON c.id = li.custody_id
     WHERE a.tournament_id = p_tournament_id
       AND a.delivery_kind = 'seat'
       AND (target_player.id IS NULL
         OR target_player.tournament_id IS DISTINCT FROM v_h.target_id
         OR target_player.user_id IS DISTINCT FROM a.user_id
         OR COALESCE(target_player.is_satellite_qualifier, false) IS NOT TRUE
         OR target_player.source_satellite_id IS DISTINCT FROM p_tournament_id
         OR lo.id IS NULL
         OR lo.tournament_id IS DISTINCT FROM p_tournament_id
         OR lo.kind IS DISTINCT FROM 'prize'
         OR lo.user_id IS DISTINCT FROM a.user_id
         OR lo.amount IS DISTINCT FROM v_h.ticket_cost
         OR li.id IS NULL
         OR li.tournament_id IS DISTINCT FROM v_h.target_id
         OR li.kind IS DISTINCT FROM 'entry'
         OR li.user_id IS DISTINCT FROM a.user_id
         OR li.amount IS DISTINCT FROM v_h.ticket_cost
         OR li.prize_part IS DISTINCT FROM v_h.target_buy_in
         OR li.bounty_part IS DISTINCT FROM 0
         OR li.fee_part IS DISTINCT FROM v_h.target_fee
         OR li.registration_id IS DISTINCT FROM a.registration_id
         OR li.wallet_journal_id IS DISTINCT FROM lo.wallet_journal_id
         OR c.id IS NULL
         OR c.user_id IS DISTINCT FROM a.user_id
         OR c.purpose IS DISTINCT FROM 'tournament_entry'
         OR c.target_id IS DISTINCT FROM v_h.target_id
         OR c.entry_key IS DISTINCT FROM 'entry:' || a.registration_id::text)
  ) OR EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = v_h.target_id
       AND tp.source_satellite_id = p_tournament_id
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_satellite_awards a
          WHERE a.tournament_id = p_tournament_id
            AND a.delivery_kind = 'seat' AND a.registration_id = tp.id)
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_tickets tk
          WHERE tk.source_satellite_id = p_tournament_id
            AND tk.holder_id = tp.user_id
            AND tk.source_tournament_id = tp.tournament_id
            AND tk.status = 'redeemed'
            AND tk.redeemed_at IS NOT NULL
            AND tk.source_satellite_award_place IS NOT NULL)
  ) OR (SELECT count(*) FROM public.poker_diamond_tournament_ledger lo
         WHERE lo.tournament_id = p_tournament_id
           AND lo.kind = 'prize'
           AND lo.idempotency_key LIKE 'poker-tournament-seat-out:tourney:'
                                       || p_tournament_id::text || ':seat:%')
       <> v_h.seat_count) THEN
    RAISE EXCEPTION 'satellite % has malformed or extra Diamond seat evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF NOT v_diamond AND (EXISTS (
    SELECT 1
      FROM public.tournament_satellite_awards a
      LEFT JOIN public.tournament_players target_player
        ON target_player.id = a.registration_id
      LEFT JOIN public.chip_ledger l
        ON l.idempotency_key = 'tourney:' || p_tournament_id::text
                               || ':seat:' || a.user_id::text || ':pool_transfer'
     WHERE a.tournament_id = p_tournament_id
       AND a.delivery_kind = 'seat'
       AND (target_player.id IS NULL
         OR target_player.tournament_id IS DISTINCT FROM v_h.target_id
           OR target_player.user_id IS DISTINCT FROM a.user_id
           OR COALESCE(target_player.is_satellite_qualifier, false) IS NOT TRUE
           OR target_player.source_satellite_id IS DISTINCT FROM p_tournament_id
         OR l.id IS NULL
         OR l.amount IS DISTINCT FROM v_h.ticket_cost
         OR l.from_type IS DISTINCT FROM 'prize_liability'
         OR l.from_entity_id IS DISTINCT FROM p_tournament_id
         OR l.to_type IS DISTINCT FROM 'prize_liability'
         OR l.to_entity_id IS DISTINCT FROM v_h.target_id
         OR l.category IS DISTINCT FROM 'tournament_buyin'
         OR l.metadata->>'registration_id' IS DISTINCT FROM a.registration_id::text
         -- A bounty seat's leg names its exact split; a plain seat's never does.
         OR l.metadata->>'entry_split_version' IS DISTINCT FROM
              (CASE WHEN v_entry_bounty > 0 THEN '2' END)
         OR (v_entry_bounty > 0 AND (
              (l.metadata->>'entry_prize')::numeric IS DISTINCT FROM v_entry_prize
           OR (l.metadata->>'entry_bounty')::numeric IS DISTINCT FROM v_entry_bounty
           OR (l.metadata->>'entry_fee')::numeric IS DISTINCT FROM v_h.target_fee)))
  ) OR EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = v_h.target_id
       AND tp.source_satellite_id = p_tournament_id
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_satellite_awards a
          WHERE a.tournament_id = p_tournament_id
            AND a.delivery_kind = 'seat' AND a.registration_id = tp.id)
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_tickets tk
          WHERE tk.source_satellite_id = p_tournament_id
            AND tk.holder_id = tp.user_id
            AND tk.source_tournament_id = tp.tournament_id
            AND tk.status = 'redeemed'
            AND tk.redeemed_at IS NOT NULL
            AND tk.source_satellite_award_place IS NOT NULL)
  ) OR (SELECT count(*) FROM public.chip_ledger l
         WHERE l.from_type = 'prize_liability'
           AND l.from_entity_id = p_tournament_id
           AND l.idempotency_key LIKE 'tourney:' || p_tournament_id::text
                                          || ':seat:%:pool_transfer')
       <> v_h.seat_count) THEN
    RAISE EXCEPTION 'satellite % has malformed or extra actual-seat evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*), round(COALESCE(sum(r.rake_amount), 0), 2)
    INTO v_rows, v_rake
    FROM public.rake_records r
   WHERE r.tournament_id = v_h.target_id
     AND r.is_tournament
     AND r.source = 'fn_award_satellite_seat'
     AND r.metadata->>'satellite_id' = p_tournament_id::text;
  IF NOT v_diamond AND (v_rows <> (CASE WHEN v_h.target_fee > 0 THEN v_h.seat_count ELSE 0 END)
     OR v_rake IS DISTINCT FROM round(v_h.seat_count * v_h.target_fee, 2)
     OR (SELECT count(DISTINCT r.metadata->>'registration_id')
           FROM public.rake_records r
          WHERE r.tournament_id = v_h.target_id
            AND r.is_tournament
            AND r.source = 'fn_award_satellite_seat'
            AND r.metadata->>'satellite_id' = p_tournament_id::text)
          <> (CASE WHEN v_h.target_fee > 0 THEN v_h.seat_count ELSE 0 END)
     OR EXISTS (
       SELECT 1 FROM public.rake_records r
        WHERE r.tournament_id = v_h.target_id
          AND r.is_tournament
          AND r.source = 'fn_award_satellite_seat'
          AND r.metadata->>'satellite_id' = p_tournament_id::text
          AND (r.rake_amount IS DISTINCT FROM v_h.target_fee
            OR r.pot_size IS DISTINCT FROM v_h.ticket_cost
            OR r.metadata->>'kind' IS DISTINCT FROM 'satellite_seat_entry_fee'
            OR NOT EXISTS (
              SELECT 1 FROM public.tournament_satellite_awards a
               WHERE a.tournament_id = p_tournament_id
                 AND a.delivery_kind = 'seat'
                 AND a.user_id::text = r.metadata->>'user_id'
                 AND a.registration_id::text = r.metadata->>'registration_id'))
     ) OR EXISTS (
       SELECT 1
         FROM public.tournament_satellite_awards a
        WHERE a.tournament_id = p_tournament_id
          AND a.delivery_kind = 'seat'
          AND v_h.target_fee > 0
          AND (SELECT count(*)
                 FROM public.rake_records r
                WHERE r.tournament_id = v_h.target_id
                  AND r.is_tournament
                  AND r.source = 'fn_award_satellite_seat'
                  AND r.metadata->>'kind' = 'satellite_seat_entry_fee'
                  AND r.metadata->>'satellite_id' = p_tournament_id::text
                  AND r.metadata->>'user_id' = a.user_id::text
                  AND r.metadata->>'registration_id' = a.registration_id::text
                  AND r.rake_amount = v_h.target_fee
                  AND r.pot_size = v_h.ticket_cost) <> 1
     )) THEN
    RAISE EXCEPTION 'satellite % has malformed target-entry evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*) INTO v_rows
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
     AND NOT (o.kind = 'refund' AND o.source = 'fn_unregister_from_tournament'
              AND o.settled_at IS NOT NULL AND o.amount_paid = o.amount_owed);
  IF v_rows <> (v_h.cash_ticket_count
                + CASE WHEN v_h.remainder > 0 THEN 1 ELSE 0 END) THEN
    RAISE EXCEPTION 'satellite % has missing or extra obligation evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF v_h.remainder > 0 THEN
    IF (SELECT count(*) FROM public.tournament_satellite_remainders r
         WHERE r.tournament_id = p_tournament_id) <> 1
       OR NOT EXISTS (
      SELECT 1
        FROM public.tournament_players bubble
        JOIN public.tournament_satellite_remainders r
          ON r.tournament_id = p_tournament_id
         AND r.user_id = bubble.user_id
         AND r.place = v_h.bubble_position
         AND r.amount = v_h.remainder
        JOIN public.tournament_payouts p
          ON p.id = r.payout_id
         AND p.tournament_id = p_tournament_id
         AND p.user_id = bubble.user_id
         AND p."position" IS NOT DISTINCT FROM r.payout_position
         AND p.amount = v_h.remainder
         AND p.source = r.payout_source
         AND p.idempotency_key = r.idempotency_key
        JOIN public.tournament_obligations o
          ON o.id = r.obligation_id
         AND o.tournament_id = p_tournament_id
         AND o.kind = r.obligation_kind
         AND o.place IS NOT DISTINCT FROM r.obligation_place
         AND o.user_id = bubble.user_id
         AND o.amount_owed = v_h.remainder
         AND o.amount_paid = v_h.remainder
         AND o.settled_at IS NOT NULL
        JOIN public.wallet_credit_idempotency k
          ON k.key = r.idempotency_key
         AND k.user_id = bubble.user_id
         AND k.amount = v_h.remainder
       WHERE bubble.tournament_id = p_tournament_id
         AND bubble.user_id = v_h.bubble_user_id
         AND bubble.position = v_h.bubble_position
         AND (
           (r.evidence_kind = 'atomic'
             AND r.payout_position IS NOT DISTINCT FROM r.place
             AND r.obligation_place IS NOT DISTINCT FROM r.place
             AND r.idempotency_key = 'tourney:' || p_tournament_id::text
                 || ':satellite_remainder:place:' || r.place::text)
           OR r.evidence_kind = 'legacy_20260908_682')
    ) THEN
      RAISE EXCEPTION 'satellite % has no exact single-bubble remainder payment',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
    v_remainder := jsonb_build_object(
      'user_id', v_h.bubble_user_id,
      'position', v_h.bubble_position,
      'amount', v_h.remainder);
  ELSIF EXISTS (SELECT 1 FROM public.tournament_satellite_remainders r
                 WHERE r.tournament_id = p_tournament_id)
     OR EXISTS (
       SELECT 1 FROM public.tournament_payouts p
        WHERE p.tournament_id = p_tournament_id
          AND p.source = 'satellite_remainder'
     ) THEN
    RAISE EXCEPTION 'satellite % has remainder evidence when remainder is zero',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  v_expected_rows := v_h.ticket_award_count
                     + CASE WHEN v_h.remainder > 0 THEN 1 ELSE 0 END;
  SELECT count(*), round(COALESCE(sum(p.amount), 0), 2)
    INTO v_rows, v_amount
    FROM public.tournament_payouts p
   WHERE p.tournament_id = p_tournament_id;
  IF v_rows <> v_expected_rows OR v_amount IS DISTINCT FROM v_h.pool THEN
    RAISE EXCEPTION
      'satellite % payout evidence has % rows / % chips, expected % / %',
      p_tournament_id, v_rows, v_amount, v_expected_rows, v_h.pool
      USING ERRCODE = 'P0404';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.prize IS DISTINCT FROM CASE
         WHEN EXISTS(SELECT 1 FROM public.tournament_satellite_awards a WHERE a.tournament_id=p_tournament_id AND a.user_id=tp.user_id) THEN v_h.ticket_cost
         WHEN v_h.remainder > 0 AND tp.position = v_h.bubble_position
           THEN v_h.remainder
         ELSE 0::numeric
       END
  ) THEN
    RAISE EXCEPTION 'satellite % prize cache disagrees with its receipt',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT * INTO v_source_escrow
    FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id
   FOR UPDATE;
  IF v_source_escrow.tournament_id IS NULL
     OR COALESCE(v_source_escrow.enforced, false) IS NOT TRUE
     OR v_source_escrow.prize_out IS DISTINCT FROM v_h.pool
     OR v_source_escrow.bounty_in IS DISTINCT FROM 0::numeric
     OR v_source_escrow.bounty_out IS DISTINCT FROM 0::numeric
     OR v_source_escrow.refund_bounty IS DISTINCT FROM 0::numeric
     OR v_source_escrow.reserve_out IS DISTINCT FROM 0::numeric
     OR v_source_escrow.reserve_in IS DISTINCT FROM 0::numeric
     OR v_source_escrow.prize_balance IS DISTINCT FROM 0::numeric
     OR v_source_escrow.bounty_balance IS DISTINCT FROM 0::numeric
     OR v_source_escrow.fee_balance IS DISTINCT FROM 0::numeric
     OR v_source_escrow.closed_at IS DISTINCT FROM v_h.source_escrow_closed_at
     OR v_source_escrow.close_note IS DISTINCT FROM v_h.source_escrow_close_note
     OR EXISTS (
       SELECT 1
         FROM unnest(ARRAY[
           'gross_in','fee_entries_in','satellite_fee_in','bounty_in',
           'overlay_in','satellite_in','prize_out','bounty_out','fee_out',
           'refund_prize','refund_bounty','refund_fee',
           'prize_balance','bounty_balance','fee_balance',
           'reserve_out','reserve_in'
         ]::text[]) AS component(name)
         CROSS JOIN LATERAL (
           SELECT (to_jsonb(v_source_escrow)->>component.name)::numeric AS amount
         ) AS persisted
        WHERE persisted.amount IS NULL
           OR CASE
                WHEN persisted.amount::text IN ('NaN','Infinity','-Infinity')
                  THEN true
                ELSE persisted.amount < 0
                  OR persisted.amount IS DISTINCT FROM round(persisted.amount,2)
              END
     ) THEN
    RAISE EXCEPTION 'satellite % did not close every escrow bank at zero',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT * INTO v_rake_settlement
    FROM public.tournament_rake_settlements s
   WHERE s.tournament_id = p_tournament_id;
  SELECT round(COALESCE(sum(r.rake_amount), 0), 2) INTO v_rake
    FROM public.rake_records r
   WHERE r.tournament_id = p_tournament_id AND r.is_tournament;
  IF v_diamond THEN
    -- DIAMOND PHASE 9: a Diamond satellite's fee is its fee bank, settled to
    -- the house, not a rake_records sum.
    SELECT e.fee_balance + e.fee_out INTO v_rake
      FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id) e;
  END IF;
  v_accounting:=public.fn_accounting_tournament_terminal_fee_receipt(p_tournament_id);
  v_deferred:=COALESCE(v_accounting->>'status'='banked_accrual_deferred',false);
  IF v_rake_settlement.tournament_id IS NULL
     OR v_rake_settlement.settled_at IS NULL
     OR v_rake_settlement.amount IS DISTINCT FROM v_rake
     OR (v_rake > 0 AND v_rake_settlement.attributed_at IS NULL AND NOT v_deferred) THEN
    RAISE EXCEPTION 'satellite % rake has no exact terminal settlement',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'user_id', a.user_id,
           'award_slot', a.place,
           'position', (SELECT tp.position FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament_id AND tp.user_id=a.user_id),
           'amount', a.amount,
           'delivery_kind', a.delivery_kind,
           'payout_id', a.payout_id,
           'registration_id', a.registration_id,
           'ticket_id', a.ticket_id)
         ORDER BY a.place), '[]'::jsonb)
    INTO v_awards
    FROM public.tournament_satellite_awards a
   WHERE a.tournament_id = p_tournament_id;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'user_id', a.user_id,
           'award_slot', a.place,
           'position', (SELECT tp.position FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament_id AND tp.user_id=a.user_id),
           'amount', a.amount,
           'registration_id', a.registration_id)
         ORDER BY a.place), '[]'::jsonb)
    INTO v_seats
    FROM public.tournament_satellite_awards a
   WHERE a.tournament_id = p_tournament_id
     AND a.delivery_kind = 'seat';

  RETURN jsonb_build_object(
    'ok', true,
    'fully_settled', true,
    'status', 'COMPLETED',
    'tournament_id', p_tournament_id,
    'target_id', v_h.target_id,
    'qualifier_ids', v_h.qualifier_ids,
    'field_size', v_h.field_size,
    'pool', v_h.pool,
    'ticket_cost', v_h.ticket_cost,
    'ticket_award_count', v_h.ticket_award_count,
    'seat_count', v_h.seat_count,
    'cash_ticket_count', v_h.cash_ticket_count,
    'entry_ticket_count', v_h.entry_ticket_count,
    'awards', v_awards,
    'seats', v_seats,
    'remainder', v_remainder,
    'source_table_count', v_h.source_table_count,
    'source_seat_count', v_h.source_seat_count,
    'released_seat_count', v_h.released_seat_count,
    'source_closeout', jsonb_build_object(
      'source_table_count', v_h.source_table_count,
      'source_table_ids', to_jsonb(v_h.source_table_ids),
      'source_seat_count', v_h.source_seat_count,
      'source_seat_ids', to_jsonb(v_h.source_seat_ids),
      'released_seat_count', v_h.released_seat_count,
      'released_seat_ids', to_jsonb(v_h.released_seat_ids),
      'closed_at', v_h.source_closed_at,
      'escrow_closed_at', v_h.source_escrow_closed_at,
      'escrow_close_note', v_h.source_escrow_close_note),
    'settled_at', v_h.settled_at,
    'receipt_version', v_h.receipt_version,
    'accounting',v_accounting);
END;
$$;


ALTER FUNCTION public.fn_ca_satellite_cohort_receipt(p_tournament_id uuid, p_observed_qualifier_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 7098 (class 1255 OID 25581439)
-- Name: fn_ca_satellite_entry_ticket_is_guarded(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_satellite_entry_ticket_is_guarded() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_token uuid := NULLIF(
    current_setting('app.ca_satellite_ticket_use_token',true),'')::uuid;
  v_cash_token uuid := NULLIF(
    current_setting('app.ca_closed_target_ticket_cash',true),'')::uuid;
  v_authorization public.tournament_ticket_admission_authorizations%ROWTYPE;
  v_rows integer;
BEGIN
  IF TG_OP='DELETE' AND OLD.redemption_mode='tournament_entry_only' THEN
    RAISE EXCEPTION 'tournament-entry tickets are durable financial evidence'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP='UPDATE' AND OLD.redemption_mode='tournament_entry_only' THEN
    IF ROW(NEW.id,NEW.club_id,NEW.issued_by,NEW.holder_id,NEW.value,NEW.note,
           NEW.redemption_mode,NEW.source_tournament_id,
           NEW.source_satellite_id,NEW.source_refund_entitlement_id,
           NEW.source_satellite_award_place,
           NEW.entry_prize,NEW.entry_bounty,NEW.entry_fee,NEW.created_at,
           NEW.cancelled_at)
       IS DISTINCT FROM
       ROW(OLD.id,OLD.club_id,OLD.issued_by,OLD.holder_id,OLD.value,OLD.note,
           OLD.redemption_mode,OLD.source_tournament_id,
           OLD.source_satellite_id,OLD.source_refund_entitlement_id,
           OLD.source_satellite_award_place,
           OLD.entry_prize,OLD.entry_bounty,OLD.entry_fee,OLD.created_at,
           OLD.cancelled_at) THEN
      RAISE EXCEPTION 'tournament-entry ticket identity and rails are immutable'
        USING ERRCODE = '55000';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      /* A SATELLITE SEAT IS SEAT OR CASH (2026-10-12). A direct satellite
         ticket whose one target can no longer admit it is paid to its holder
         in cash by fn_ca_pay_closed_target_ticket_in_cash, and only by it:
         the transition is accepted only when that door has already written
         the exact escrow-to-wallet leg under the ticket's own key in this
         transaction and named this ticket on its token. */
      IF OLD.status='issued' AND NEW.status='redeemed'
         AND v_cash_token IS NOT NULL AND v_cash_token=OLD.id
         AND OLD.redeemed_at IS NULL
         AND NEW.redeemed_at=transaction_timestamp()
         AND OLD.source_satellite_award_place IS NOT NULL
         AND OLD.source_refund_entitlement_id IS NULL
         AND public.fn_ca_satellite_ticket_target_is_closed(
               OLD.source_tournament_id)
         AND (SELECT count(*)
                FROM public.chip_ledger_idem i
                JOIN public.chip_ledger l ON l.id=i.leg_id
               WHERE i.idempotency_key=
                       'ticket:'||OLD.id::text||':closed-target-cash'
                 AND l.from_type='escrow' AND l.from_entity_id=OLD.id
                 AND l.to_type='player_wallet'
                 AND l.to_entity_id=OLD.holder_id
                 AND l.amount=OLD.value AND l.club_id=OLD.club_id
                 AND l.category='ticket_redeem'
                 AND l.tournament_id IS NULL)=1 THEN
        RETURN NEW;
      END IF;
      IF NOT (OLD.status='issued' AND NEW.status='redeemed'
              AND v_token IS NOT NULL
              AND OLD.redeemed_at IS NULL
              AND NEW.redeemed_at IS NOT NULL
              AND NEW.redeemed_at=transaction_timestamp()) THEN
        RAISE EXCEPTION
          'tournament-entry tickets can only be consumed by tournament admission'
          USING ERRCODE = '42501';
      END IF;
      SELECT * INTO v_authorization
        FROM public.tournament_ticket_admission_authorizations a
       WHERE a.token=v_token AND a.ticket_id=OLD.id
       FOR UPDATE;
      IF v_authorization.token IS NULL
         OR v_authorization.user_id IS DISTINCT FROM OLD.holder_id
         OR NOT EXISTS(
           SELECT 1 FROM public.tournament_players tp
            WHERE tp.id=v_authorization.registration_id
              AND tp.tournament_id=v_authorization.tournament_id
              AND tp.user_id=v_authorization.user_id
              AND tp.status::text IN ('registered','playing')) THEN
        RAISE EXCEPTION
          'tournament-entry ticket has no exact admission authorization'
          USING ERRCODE = '42501';
      END IF;
      DELETE FROM public.tournament_ticket_admission_authorizations a
       WHERE a.token=v_token AND a.ticket_id=OLD.id;
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      IF v_rows<>1 THEN
        RAISE EXCEPTION
          'tournament-entry ticket admission authorization was not consumed once'
          USING ERRCODE = 'P0404';
      END IF;
    END IF;
    IF NEW.status IS NOT DISTINCT FROM OLD.status
       AND NEW.redeemed_at IS DISTINCT FROM OLD.redeemed_at THEN
      RAISE EXCEPTION
        'tournament-entry ticket redemption time is immutable'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION public.fn_ca_satellite_entry_ticket_is_guarded() OWNER TO postgres;

--
-- TOC entry 6076 (class 1255 OID 25581639)
-- Name: fn_ca_satellite_settlement_receipt(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_satellite_settlement_receipt(p_tournament_id uuid, p_observed_winner_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_accounting jsonb; v_deferred boolean := false;
  v_h public.tournament_satellite_settlements%ROWTYPE;
  v_source record;
  v_target record;
  v_source_escrow public.tournament_escrow%ROWTYPE;
  v_rake_settlement record;
  v_field_size integer;
  v_position_count integer;
  v_rows integer;
  v_expected_rows integer;
  v_amount numeric;
  v_rake numeric;
  v_awards jsonb := '[]'::jsonb;
  v_seats jsonb := '[]'::jsonb;
  v_remainder jsonb := NULL;
  v_winner_amount numeric := 0;
  v_source_table_ids uuid[];
  v_source_seat_ids uuid[];
  v_durable_released_ids uuid[];
  v_durable_released_count integer;
  v_diamond boolean := false;              -- DIAMOND PHASE 9
  v_entry_prize numeric;                   -- 2026-10-16: the target entry split
  v_entry_bounty numeric;                  -- 2026-10-16: the target entry split
BEGIN
  IF p_tournament_id IS NULL OR p_observed_winner_id IS NULL THEN
    RAISE EXCEPTION 'satellite receipt requires tournament and observed winner ids'
      USING ERRCODE = '22004';
  END IF;

  SELECT * INTO v_h
    FROM public.tournament_satellite_settlements s
   WHERE s.tournament_id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'satellite % has no immutable settlement header',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF v_h.winner_id IS DISTINCT FROM p_observed_winner_id THEN
    RAISE EXCEPTION
      'satellite % receipt winner % differs from observed winner %',
      p_tournament_id, v_h.winner_id, p_observed_winner_id
      USING ERRCODE = '55000';
  END IF;
  IF v_h.receipt_version IS DISTINCT FROM 2 THEN
    RAISE EXCEPTION 'satellite % has unsupported receipt version %',
      p_tournament_id, v_h.receipt_version USING ERRCODE = 'P0404';
  END IF;

  v_diamond := public.fn_poker_diamond_tournament(p_tournament_id);  -- DIAMOND PHASE 9
  -- Target lifecycle state is intentionally absent from replay. A target may
  -- close after commit without changing what was already delivered.
  PERFORM 1 FROM public.tournaments t
   WHERE t.id IN (p_tournament_id, v_h.target_id)
   ORDER BY CASE WHEN t.id = v_h.target_id THEN 0 ELSE 1 END, t.id
   FOR UPDATE;
  SELECT t.id, t.status, t.variant, t.tournament_type,
         t.satellite_target_id, t.satellite_target, t.satellite_seats,
         t.prize_pool, t.prize_pool_finalized, t.ended_at,
         t.current_players, t.on_break, t.break_started_at, t.break_ends_at
    INTO v_source FROM public.tournaments t
   WHERE t.id = p_tournament_id;
  IF v_source.id IS NULL THEN
    RAISE EXCEPTION 'satellite % source row is missing',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF upper(COALESCE(v_source.status, '')) <> 'COMPLETED'
     OR COALESCE(v_source.prize_pool_finalized, false) IS NOT TRUE
     OR v_source.ended_at IS NULL
     OR v_source.ended_at IS DISTINCT FROM v_h.source_closed_at
     OR v_source.current_players IS DISTINCT FROM 0
     OR v_source.on_break IS DISTINCT FROM false
     OR v_source.break_started_at IS NOT NULL
     OR v_source.break_ends_at IS NOT NULL THEN
    RAISE EXCEPTION 'satellite % receipt is not attached to one completed close',
      p_tournament_id USING ERRCODE = '55000';
  END IF;
  IF lower(COALESCE(v_source.variant, '')) <> 'satellite'
     AND upper(COALESCE(v_source.tournament_type, '')) <> 'SATELLITE'
     AND v_source.satellite_target_id IS NULL
     AND v_source.satellite_target IS NULL THEN
    RAISE EXCEPTION 'tournament % no longer identifies as a satellite',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF v_source.satellite_target_id IS NOT NULL
     AND v_source.satellite_target IS NOT NULL
     AND v_source.satellite_target_id IS DISTINCT FROM v_source.satellite_target THEN
    RAISE EXCEPTION 'satellite % has conflicting target columns',
      p_tournament_id USING ERRCODE = '23514';
  END IF;
  IF COALESCE(v_source.satellite_target_id, v_source.satellite_target)
       IS DISTINCT FROM v_h.target_id
     OR v_source.prize_pool IS NULL
     OR v_source.prize_pool::text IN ('NaN','Infinity','-Infinity')
     OR round(v_source.prize_pool, 2) IS DISTINCT FROM v_h.pool
     OR COALESCE(v_source.satellite_seats, 0) IS DISTINCT FROM v_h.advertised_seats
     OR v_h.pool < v_h.advertised_seats * v_h.ticket_cost
     OR floor(v_h.pool / v_h.ticket_cost)::integer IS DISTINCT FROM v_h.ticket_award_count
     OR round(v_h.pool - v_h.ticket_award_count * v_h.ticket_cost, 2)
          IS DISTINCT FROM v_h.remainder THEN
    RAISE EXCEPTION 'satellite % immutable receipt disagrees with its locked contract',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT t.id,t.buy_in_amount,t.buy_in_fee,t.bounty_amount,t.is_bounty,
         t.is_pko,t.is_mystery_bounty,t.is_premium_spin,t.variant,
         t.tournament_type,t.club_id
    INTO v_target FROM public.tournaments t
   WHERE t.id = v_h.target_id
   FOR SHARE;
  -- A delivered seat or ticket into a bounty target carries the target's
  -- own entry split (2026-10-16). The economic columns are immutable after
  -- the first seat or ticket, so the split read now is the one booked.
  SELECT s.prize, s.bounty INTO v_entry_prize, v_entry_bounty
    FROM public.fn_tournament_entry_split(
      v_h.target_buy_in, v_h.target_fee, v_target.bounty_amount,
      COALESCE(v_target.is_bounty,false) OR COALESCE(v_target.is_pko,false)
        OR COALESCE(v_target.is_mystery_bounty,false)) s;
  IF v_target.id IS NULL
     OR v_h.target_was_missing IS DISTINCT FROM false
     OR v_h.target_contract_version IS NOT NULL
     OR ((v_h.seat_count > 0 OR v_h.entry_ticket_count > 0) AND (
          v_target.buy_in_amount IS DISTINCT FROM v_h.target_buy_in
       OR COALESCE(v_target.buy_in_fee,0) IS DISTINCT FROM v_h.target_fee
       OR v_entry_prize IS NULL OR v_entry_bounty IS NULL
       OR v_entry_prize < 0 OR v_entry_bounty < 0
       OR round(v_entry_prize + v_entry_bounty, 2)
            IS DISTINCT FROM v_h.target_buy_in
       OR (v_diamond AND v_entry_bounty <> 0)
       OR COALESCE(v_target.is_premium_spin,false)
       OR lower(COALESCE(v_target.variant,'')) = 'spin'
       OR upper(COALESCE(v_target.tournament_type,'')) = 'SPIN')) THEN
    RAISE EXCEPTION 'satellite % immutable receipt lost its locked target row',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  -- The header is the immutable settlement-time contract. Replay proves that
  -- exact value through its award, transfer and fee evidence. The terminal
  -- hardening migration also freezes the target's economic columns after its
  -- first actual seat, so cancellation and unregister use the same split.

  PERFORM 1 FROM public.tournament_players tp
   WHERE tp.tournament_id IN (p_tournament_id, v_h.target_id)
   ORDER BY tp.tournament_id, tp.id FOR SHARE;
  SELECT count(*), count(DISTINCT tp.position)
    INTO v_field_size, v_position_count
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;
  IF v_field_size <> v_h.field_size
     OR v_position_count <> v_h.field_size
     OR EXISTS (
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.tournament_id = p_tournament_id
          AND (tp.position IS NULL OR tp.position < 1 OR tp.position > v_h.field_size)
    ) OR NOT EXISTS (
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.tournament_id = p_tournament_id
          AND tp.user_id = v_h.winner_id
          AND tp.position = 1 AND tp.status::text = 'winner'
          AND tp.eliminated_at IS NULL
          AND tp.elimination_sequence IS NULL
     ) OR EXISTS (
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.tournament_id = p_tournament_id
          AND tp.position > 1
          AND tp.status::text IS DISTINCT FROM 'eliminated'
     ) THEN
    RAISE EXCEPTION 'satellite % receipt has no exact final standings',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- A satellite is not terminal while its felt still owns live seats. The
  -- header freezes every source table and seat identity, plus the subset that
  -- this settlement itself released. Replay requires the exact same durable
  -- rows, every table closed at zero and no live seat left behind.
  PERFORM 1 FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id
   ORDER BY tb.id FOR UPDATE;
  PERFORM 1
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.tournament_id = p_tournament_id
   ORDER BY ts.table_id, ts.id FOR UPDATE OF ts;
  SELECT COALESCE(array_agg(tb.id ORDER BY tb.id), ARRAY[]::uuid[])
    INTO v_source_table_ids
    FROM public.tables tb
   WHERE tb.tournament_id = p_tournament_id;
  SELECT COALESCE(array_agg(ts.id ORDER BY ts.table_id, ts.id), ARRAY[]::uuid[])
    INTO v_source_seat_ids
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.tournament_id = p_tournament_id;
  SELECT COALESCE(array_agg(ts.id ORDER BY ts.table_id, ts.id), ARRAY[]::uuid[])
    INTO v_durable_released_ids
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.tournament_id = p_tournament_id
     AND ts.left_at IS NOT DISTINCT FROM v_h.settled_at
     AND ts.status IS NOT DISTINCT FROM 'left'
     AND ts.leave_pending IS FALSE
     AND ts.is_sitting_out IS FALSE
     AND ts.is_away IS FALSE
     AND ts.sit_out_at IS NULL
     AND ts.scheduled_leave_hands IS NULL;
  v_durable_released_count := cardinality(v_durable_released_ids);
  IF v_source_table_ids IS DISTINCT FROM v_h.source_table_ids
     OR cardinality(v_source_table_ids) IS DISTINCT FROM v_h.source_table_count
     OR v_source_seat_ids IS DISTINCT FROM v_h.source_seat_ids
     OR cardinality(v_source_seat_ids) IS DISTINCT FROM v_h.source_seat_count
     OR v_durable_released_ids IS DISTINCT FROM v_h.released_seat_ids
     OR v_durable_released_count IS DISTINCT FROM v_h.released_seat_count
     OR EXISTS (
       SELECT 1 FROM public.tables tb
        WHERE tb.tournament_id = p_tournament_id
          AND (lower(COALESCE(tb.status::text, '')) <> 'closed'
            OR lower(COALESCE(tb.lifecycle, '')) <> 'closed'
            OR tb.current_players IS DISTINCT FROM 0
            OR tb.terminal_closed_at IS DISTINCT FROM v_h.source_closed_at)
     ) OR EXISTS (
       SELECT 1
        FROM public.table_seats ts
         JOIN public.tables tb ON tb.id = ts.table_id
        WHERE tb.tournament_id = p_tournament_id
          AND (ts.left_at IS NULL
            OR ts.status IS DISTINCT FROM 'left'
            OR ts.leave_pending IS DISTINCT FROM false
            OR ts.is_sitting_out IS DISTINCT FROM false
            OR ts.is_away IS DISTINCT FROM false
            OR ts.sit_out_at IS NOT NULL
            OR ts.scheduled_leave_hands IS NOT NULL)
     ) THEN
    RAISE EXCEPTION
      'satellite % source table or seat closeout differs from its immutable receipt',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*) INTO v_rows
    FROM public.tournament_satellite_awards a
   WHERE a.tournament_id = p_tournament_id;
  IF v_rows <> v_h.ticket_award_count
     OR (SELECT count(*) FROM public.tournament_satellite_awards a
          WHERE a.tournament_id = p_tournament_id AND a.delivery_kind = 'seat')
          <> v_h.seat_count
     OR (SELECT count(*) FROM public.tournament_satellite_awards a
          WHERE a.tournament_id = p_tournament_id AND a.delivery_kind = 'cash')
          <> v_h.cash_ticket_count
     OR (SELECT count(*) FROM public.tournament_satellite_awards a
          WHERE a.tournament_id = p_tournament_id AND a.delivery_kind = 'ticket')
          <> v_h.entry_ticket_count
     OR EXISTS (
       SELECT 1
         FROM public.tournament_satellite_awards a
         JOIN public.tournament_players tp
           ON tp.tournament_id = p_tournament_id AND tp.position = a.place
        WHERE a.tournament_id = p_tournament_id
          AND (a.place > v_h.ticket_award_count
            OR a.user_id IS DISTINCT FROM tp.user_id
            OR a.amount IS DISTINCT FROM v_h.ticket_cost)
     ) OR EXISTS (
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.tournament_id = p_tournament_id
          AND tp.position BETWEEN 1 AND v_h.ticket_award_count
          AND NOT EXISTS (
            SELECT 1 FROM public.tournament_satellite_awards a
             WHERE a.tournament_id = p_tournament_id
               AND a.place = tp.position AND a.user_id = tp.user_id)
     ) THEN
    RAISE EXCEPTION 'satellite % has incomplete or non-contiguous award lines',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- Every line has one exact payout row. Cash lines additionally prove the
  -- wallet credit and closed obligation; seats prove the registration and
  -- source-to-target funding leg below.
  IF EXISTS (
    SELECT 1
      FROM public.tournament_satellite_awards a
      LEFT JOIN public.tournament_payouts p ON p.id = a.payout_id
     WHERE a.tournament_id = p_tournament_id
       AND (p.id IS NULL
         OR p.tournament_id IS DISTINCT FROM p_tournament_id
         OR p.user_id IS DISTINCT FROM a.user_id
         OR p."position" IS DISTINCT FROM a.place
         OR p.amount IS DISTINCT FROM a.amount
         OR p.source IS DISTINCT FROM a.payout_source
         OR p.idempotency_key IS DISTINCT FROM a.idempotency_key)
  ) THEN
    RAISE EXCEPTION 'satellite % award line has no exact payout evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.tournament_satellite_awards a
      LEFT JOIN public.tournament_obligations o ON o.id = a.obligation_id
      LEFT JOIN public.wallet_credit_idempotency k ON k.key = a.idempotency_key
     WHERE a.tournament_id = p_tournament_id
       AND a.delivery_kind = 'cash'
       AND (o.id IS NULL
         OR o.tournament_id IS DISTINCT FROM p_tournament_id
         OR o.kind IS DISTINCT FROM a.obligation_kind
         OR o.place IS DISTINCT FROM a.place
         OR o.user_id IS DISTINCT FROM a.user_id
         OR o.amount_owed IS DISTINCT FROM a.amount
         OR o.amount_paid IS DISTINCT FROM a.amount
         OR o.settled_at IS NULL
         OR k.key IS NULL
         OR k.user_id IS DISTINCT FROM a.user_id
         OR k.amount IS DISTINCT FROM a.amount)
  ) THEN
    RAISE EXCEPTION 'satellite % cash ticket has no exact wallet/debt evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  -- A cap-blocked full award remains the source pool's money but is held in a
  -- noncash, target-scoped ticket escrow. Prove the immutable award identity,
  -- exact issue journal and absence of a wallet credit on every replay.
  IF EXISTS (
    SELECT 1
      FROM public.tournament_satellite_awards a
      LEFT JOIN public.tournament_payouts p ON p.id=a.payout_id
      LEFT JOIN public.tournament_tickets tk ON tk.id=a.ticket_id
      LEFT JOIN public.chip_ledger l
        ON l.idempotency_key=a.idempotency_key||':ticket_escrow'
       AND l.to_type='escrow' AND l.to_entity_id=a.ticket_id
     WHERE a.tournament_id=p_tournament_id
       AND a.delivery_kind='ticket'
       AND (tk.id IS NULL
         OR tk.issued_by IS DISTINCT FROM
              '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid
         OR tk.holder_id IS DISTINCT FROM a.user_id
         OR tk.value IS DISTINCT FROM a.amount
         OR tk.status NOT IN ('issued','redeemed')
         OR tk.redemption_mode IS DISTINCT FROM 'tournament_entry_only'
         OR tk.source_tournament_id IS DISTINCT FROM v_h.target_id
         OR tk.source_satellite_id IS DISTINCT FROM p_tournament_id
         OR tk.source_refund_entitlement_id IS NOT NULL
         OR tk.source_satellite_award_place IS DISTINCT FROM a.place
         OR tk.entry_prize IS DISTINCT FROM v_entry_prize
         OR tk.entry_bounty IS DISTINCT FROM v_entry_bounty
         OR tk.entry_fee IS DISTINCT FROM v_h.target_fee
         OR p.metadata->>'delivery_kind' IS DISTINCT FROM 'ticket'
         OR p.metadata->>'ticket_id' IS DISTINCT FROM tk.id::text
         OR p.metadata->>'satellite_target_id' IS DISTINCT FROM v_h.target_id::text
         OR p.metadata->>'wallet_chips_credited' IS DISTINCT FROM '0'
         OR l.id IS NULL
         OR l.status IS DISTINCT FROM 'posted'
         OR l.from_type IS DISTINCT FROM 'prize_liability'
         OR l.from_entity_id IS DISTINCT FROM p_tournament_id
         OR l.to_type IS DISTINCT FROM 'escrow'
         OR l.to_entity_id IS DISTINCT FROM tk.id
         OR l.amount IS DISTINCT FROM a.amount
         OR l.category IS DISTINCT FROM 'ticket_issue'
         OR l.club_id IS DISTINCT FROM tk.club_id
         OR l.tournament_id IS DISTINCT FROM p_tournament_id
         OR l.settlement_id IS DISTINCT FROM
              'satellite-ticket:'||tk.id::text
         OR l.actor_service IS DISTINCT FROM 'fn_settle_satellite_tournament'
         OR l.pre_from_balance IS DISTINCT FROM
              round(v_h.pool-(a.place-1)*v_h.ticket_cost,2)
         OR l.post_from_balance IS DISTINCT FROM
              round(v_h.pool-a.place*v_h.ticket_cost,2)
         OR l.pre_to_balance IS DISTINCT FROM 0::numeric
         OR l.post_to_balance IS DISTINCT FROM a.amount
         OR l.metadata->>'kind' IS DISTINCT FROM
              'direct_satellite_entry_ticket'
         OR l.metadata->>'delivery_kind' IS DISTINCT FROM 'ticket'
         OR l.metadata->>'ticket_id' IS DISTINCT FROM tk.id::text
         OR l.metadata->>'payout_id' IS DISTINCT FROM a.payout_id::text
         OR l.metadata->>'satellite_id' IS DISTINCT FROM p_tournament_id::text
         OR l.metadata->>'satellite_target_id' IS DISTINCT FROM v_h.target_id::text
         OR l.metadata->>'user_id' IS DISTINCT FROM a.user_id::text
         OR l.metadata->>'position' IS DISTINCT FROM a.place::text
         OR (l.metadata->>'entry_prize')::numeric IS DISTINCT FROM
              v_entry_prize
         OR (l.metadata->>'entry_bounty')::numeric IS DISTINCT FROM v_entry_bounty
         OR (l.metadata->>'entry_fee')::numeric IS DISTINCT FROM v_h.target_fee
         OR l.metadata->>'wallet_chips_credited' IS DISTINCT FROM '0'
         OR EXISTS (
           SELECT 1 FROM public.wallet_credit_idempotency wallet_key
            WHERE wallet_key.key=a.idempotency_key)
         OR (SELECT count(*)
               FROM public.chip_transactions issue_tx
              WHERE issue_tx.transaction_type='tournament_ticket_issue'
                AND issue_tx.club_id=tk.club_id
                AND issue_tx.from_user_id IS NULL
                AND issue_tx.to_user_id=a.user_id
                AND issue_tx.amount=a.amount
                AND issue_tx.metadata->>'ticket_id'=tk.id::text
                AND issue_tx.metadata->>'escrow_entity_id'=tk.id::text
                AND issue_tx.metadata->>'holder_id'=a.user_id::text
                AND (issue_tx.metadata->>'value')::numeric=a.amount
                AND issue_tx.metadata->>'redemption_mode'=
                      'tournament_entry_only'
                AND issue_tx.metadata->>'source_tournament_id'=
                      v_h.target_id::text
                AND issue_tx.metadata->>'source_satellite_id'=
                      p_tournament_id::text
                AND issue_tx.metadata->>'source_award_place'=a.place::text
                AND issue_tx.metadata->>'payout_id'=a.payout_id::text
                AND issue_tx.metadata->>'ledger_id'=l.id::text
                AND issue_tx.metadata->>'idempotency_key'=a.idempotency_key
                AND issue_tx.metadata->>'wallet_chips_credited'='0') <> 1)
  ) OR (SELECT count(*) FROM public.tournament_tickets tk
         WHERE tk.source_satellite_id=p_tournament_id
           AND tk.source_satellite_award_place IS NOT NULL)
       <> v_h.entry_ticket_count
    OR (SELECT count(*) FROM public.chip_ledger l
         WHERE l.from_type='prize_liability'
           AND l.from_entity_id=p_tournament_id
           AND l.category='ticket_issue'
           AND l.metadata->>'kind'='direct_satellite_entry_ticket')
       <> v_h.entry_ticket_count THEN
    RAISE EXCEPTION
      'satellite % direct ticket has no exact noncash escrow evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF v_h.seat_count > 0 AND v_target.id IS NULL THEN
    RAISE EXCEPTION 'satellite % delivered seats into a missing target',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  -- DIAMOND PHASE 9: a Diamond seat is proved by its Diamond evidence - the
  -- satellite's prize-bank row out, the target's funded entry row in with
  -- the target's own parts, and the entry custody row named for the
  -- registration - never by a chip transfer leg or a chip fee row, which a
  -- Diamond seat does not write.
  IF v_diamond AND (EXISTS (
    SELECT 1
      FROM public.tournament_satellite_awards a
      LEFT JOIN public.tournament_players target_player
        ON target_player.id = a.registration_id
      LEFT JOIN public.poker_diamond_tournament_ledger lo
        ON lo.idempotency_key = 'poker-tournament-seat-out:' || a.idempotency_key
      LEFT JOIN public.poker_diamond_tournament_ledger li
        ON li.idempotency_key = 'poker-tournament-seat-in:' || a.idempotency_key
      LEFT JOIN public.poker_diamond_custody c
        ON c.id = li.custody_id
     WHERE a.tournament_id = p_tournament_id
       AND a.delivery_kind = 'seat'
       AND (target_player.id IS NULL
         OR target_player.tournament_id IS DISTINCT FROM v_h.target_id
         OR target_player.user_id IS DISTINCT FROM a.user_id
         OR COALESCE(target_player.is_satellite_qualifier, false) IS NOT TRUE
         OR target_player.source_satellite_id IS DISTINCT FROM p_tournament_id
         OR lo.id IS NULL
         OR lo.tournament_id IS DISTINCT FROM p_tournament_id
         OR lo.kind IS DISTINCT FROM 'prize'
         OR lo.user_id IS DISTINCT FROM a.user_id
         OR lo.amount IS DISTINCT FROM v_h.ticket_cost
         OR li.id IS NULL
         OR li.tournament_id IS DISTINCT FROM v_h.target_id
         OR li.kind IS DISTINCT FROM 'entry'
         OR li.user_id IS DISTINCT FROM a.user_id
         OR li.amount IS DISTINCT FROM v_h.ticket_cost
         OR li.prize_part IS DISTINCT FROM v_h.target_buy_in
         OR li.bounty_part IS DISTINCT FROM 0
         OR li.fee_part IS DISTINCT FROM v_h.target_fee
         OR li.registration_id IS DISTINCT FROM a.registration_id
         OR li.wallet_journal_id IS DISTINCT FROM lo.wallet_journal_id
         OR c.id IS NULL
         OR c.user_id IS DISTINCT FROM a.user_id
         OR c.purpose IS DISTINCT FROM 'tournament_entry'
         OR c.target_id IS DISTINCT FROM v_h.target_id
         OR c.entry_key IS DISTINCT FROM 'entry:' || a.registration_id::text)
  ) OR EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = v_h.target_id
       AND tp.source_satellite_id = p_tournament_id
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_satellite_awards a
          WHERE a.tournament_id = p_tournament_id
            AND a.delivery_kind = 'seat' AND a.registration_id = tp.id)
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_tickets tk
          WHERE tk.source_satellite_id = p_tournament_id
            AND tk.holder_id = tp.user_id
            AND tk.source_tournament_id = tp.tournament_id
            AND tk.status = 'redeemed'
            AND tk.redeemed_at IS NOT NULL
            AND tk.source_satellite_award_place IS NOT NULL)
  ) OR (SELECT count(*) FROM public.poker_diamond_tournament_ledger lo
         WHERE lo.tournament_id = p_tournament_id
           AND lo.kind = 'prize'
           AND lo.idempotency_key LIKE 'poker-tournament-seat-out:tourney:'
                                       || p_tournament_id::text || ':seat:%')
       <> v_h.seat_count) THEN
    RAISE EXCEPTION 'satellite % has malformed or extra Diamond seat evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF NOT v_diamond AND (EXISTS (
    SELECT 1
      FROM public.tournament_satellite_awards a
      LEFT JOIN public.tournament_players target_player
        ON target_player.id = a.registration_id
      LEFT JOIN public.chip_ledger l
        ON l.idempotency_key = 'tourney:' || p_tournament_id::text
                               || ':seat:' || a.user_id::text || ':pool_transfer'
     WHERE a.tournament_id = p_tournament_id
       AND a.delivery_kind = 'seat'
       AND (target_player.id IS NULL
         OR target_player.tournament_id IS DISTINCT FROM v_h.target_id
           OR target_player.user_id IS DISTINCT FROM a.user_id
           OR COALESCE(target_player.is_satellite_qualifier, false) IS NOT TRUE
           OR target_player.source_satellite_id IS DISTINCT FROM p_tournament_id
         OR l.id IS NULL
         OR l.amount IS DISTINCT FROM v_h.ticket_cost
         OR l.from_type IS DISTINCT FROM 'prize_liability'
         OR l.from_entity_id IS DISTINCT FROM p_tournament_id
         OR l.to_type IS DISTINCT FROM 'prize_liability'
         OR l.to_entity_id IS DISTINCT FROM v_h.target_id
         OR l.category IS DISTINCT FROM 'tournament_buyin'
         OR l.metadata->>'registration_id' IS DISTINCT FROM a.registration_id::text
         -- A bounty seat's leg names its exact split; a plain seat's never does.
         OR l.metadata->>'entry_split_version' IS DISTINCT FROM
              (CASE WHEN v_entry_bounty > 0 THEN '2' END)
         OR (v_entry_bounty > 0 AND (
              (l.metadata->>'entry_prize')::numeric IS DISTINCT FROM v_entry_prize
           OR (l.metadata->>'entry_bounty')::numeric IS DISTINCT FROM v_entry_bounty
           OR (l.metadata->>'entry_fee')::numeric IS DISTINCT FROM v_h.target_fee)))
  ) OR EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = v_h.target_id
       AND tp.source_satellite_id = p_tournament_id
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_satellite_awards a
          WHERE a.tournament_id = p_tournament_id
            AND a.delivery_kind = 'seat' AND a.registration_id = tp.id)
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_tickets tk
          WHERE tk.source_satellite_id = p_tournament_id
            AND tk.holder_id = tp.user_id
            AND tk.source_tournament_id = tp.tournament_id
            AND tk.status = 'redeemed'
            AND tk.redeemed_at IS NOT NULL
            AND tk.source_satellite_award_place IS NOT NULL)
  ) OR (SELECT count(*) FROM public.chip_ledger l
         WHERE l.from_type = 'prize_liability'
           AND l.from_entity_id = p_tournament_id
           AND l.idempotency_key LIKE 'tourney:' || p_tournament_id::text
                                          || ':seat:%:pool_transfer')
       <> v_h.seat_count) THEN
    RAISE EXCEPTION 'satellite % has malformed or extra actual-seat evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*), round(COALESCE(sum(r.rake_amount), 0), 2)
    INTO v_rows, v_rake
    FROM public.rake_records r
   WHERE r.tournament_id = v_h.target_id
     AND r.is_tournament
     AND r.source = 'fn_award_satellite_seat'
     AND r.metadata->>'satellite_id' = p_tournament_id::text;
  IF NOT v_diamond AND (v_rows <> (CASE WHEN v_h.target_fee > 0 THEN v_h.seat_count ELSE 0 END)
     OR v_rake IS DISTINCT FROM round(v_h.seat_count * v_h.target_fee, 2)
     OR (SELECT count(DISTINCT r.metadata->>'registration_id')
           FROM public.rake_records r
          WHERE r.tournament_id = v_h.target_id
            AND r.is_tournament
            AND r.source = 'fn_award_satellite_seat'
            AND r.metadata->>'satellite_id' = p_tournament_id::text)
          <> (CASE WHEN v_h.target_fee > 0 THEN v_h.seat_count ELSE 0 END)
     OR EXISTS (
       SELECT 1 FROM public.rake_records r
        WHERE r.tournament_id = v_h.target_id
          AND r.is_tournament
          AND r.source = 'fn_award_satellite_seat'
          AND r.metadata->>'satellite_id' = p_tournament_id::text
          AND (r.rake_amount IS DISTINCT FROM v_h.target_fee
            OR r.pot_size IS DISTINCT FROM v_h.ticket_cost
            OR r.metadata->>'kind' IS DISTINCT FROM 'satellite_seat_entry_fee'
            OR NOT EXISTS (
              SELECT 1 FROM public.tournament_satellite_awards a
               WHERE a.tournament_id = p_tournament_id
                 AND a.delivery_kind = 'seat'
                 AND a.user_id::text = r.metadata->>'user_id'
                 AND a.registration_id::text = r.metadata->>'registration_id'))
     ) OR EXISTS (
       SELECT 1
         FROM public.tournament_satellite_awards a
        WHERE a.tournament_id = p_tournament_id
          AND a.delivery_kind = 'seat'
          AND v_h.target_fee > 0
          AND (SELECT count(*)
                 FROM public.rake_records r
                WHERE r.tournament_id = v_h.target_id
                  AND r.is_tournament
                  AND r.source = 'fn_award_satellite_seat'
                  AND r.metadata->>'kind' = 'satellite_seat_entry_fee'
                  AND r.metadata->>'satellite_id' = p_tournament_id::text
                  AND r.metadata->>'user_id' = a.user_id::text
                  AND r.metadata->>'registration_id' = a.registration_id::text
                  AND r.rake_amount = v_h.target_fee
                  AND r.pot_size = v_h.ticket_cost) <> 1
     )) THEN
    RAISE EXCEPTION 'satellite % has malformed target-entry evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT count(*) INTO v_rows
    FROM public.tournament_obligations o
   WHERE o.tournament_id = p_tournament_id
     AND NOT (o.kind = 'refund' AND o.source = 'fn_unregister_from_tournament'
              AND o.settled_at IS NOT NULL AND o.amount_paid = o.amount_owed);
  IF v_rows <> (v_h.cash_ticket_count
                + CASE WHEN v_h.remainder > 0 THEN 1 ELSE 0 END) THEN
    RAISE EXCEPTION 'satellite % has missing or extra obligation evidence',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  IF v_h.remainder > 0 THEN
    IF (SELECT count(*) FROM public.tournament_satellite_remainders r
         WHERE r.tournament_id = p_tournament_id) <> 1
       OR NOT EXISTS (
      SELECT 1
        FROM public.tournament_players bubble
        JOIN public.tournament_satellite_remainders r
          ON r.tournament_id = p_tournament_id
         AND r.user_id = bubble.user_id
         AND r.place = v_h.bubble_position
         AND r.amount = v_h.remainder
        JOIN public.tournament_payouts p
          ON p.id = r.payout_id
         AND p.tournament_id = p_tournament_id
         AND p.user_id = bubble.user_id
         AND p."position" IS NOT DISTINCT FROM r.payout_position
         AND p.amount = v_h.remainder
         AND p.source = r.payout_source
         AND p.idempotency_key = r.idempotency_key
        JOIN public.tournament_obligations o
          ON o.id = r.obligation_id
         AND o.tournament_id = p_tournament_id
         AND o.kind = r.obligation_kind
         AND o.place IS NOT DISTINCT FROM r.obligation_place
         AND o.user_id = bubble.user_id
         AND o.amount_owed = v_h.remainder
         AND o.amount_paid = v_h.remainder
         AND o.settled_at IS NOT NULL
        JOIN public.wallet_credit_idempotency k
          ON k.key = r.idempotency_key
         AND k.user_id = bubble.user_id
         AND k.amount = v_h.remainder
       WHERE bubble.tournament_id = p_tournament_id
         AND bubble.user_id = v_h.bubble_user_id
         AND bubble.position = v_h.bubble_position
         AND (
           (r.evidence_kind = 'atomic'
             AND r.payout_position IS NOT DISTINCT FROM r.place
             AND r.obligation_place IS NOT DISTINCT FROM r.place
             AND r.idempotency_key = 'tourney:' || p_tournament_id::text
                 || ':satellite_remainder:place:' || r.place::text)
           OR r.evidence_kind = 'legacy_20260908_682')
    ) THEN
      RAISE EXCEPTION 'satellite % has no exact single-bubble remainder payment',
        p_tournament_id USING ERRCODE = 'P0404';
    END IF;
    v_remainder := jsonb_build_object(
      'user_id', v_h.bubble_user_id,
      'position', v_h.bubble_position,
      'amount', v_h.remainder);
  ELSIF EXISTS (SELECT 1 FROM public.tournament_satellite_remainders r
                 WHERE r.tournament_id = p_tournament_id)
     OR EXISTS (
       SELECT 1 FROM public.tournament_payouts p
        WHERE p.tournament_id = p_tournament_id
          AND p.source = 'satellite_remainder'
     ) THEN
    RAISE EXCEPTION 'satellite % has remainder evidence when remainder is zero',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  v_expected_rows := v_h.ticket_award_count
                     + CASE WHEN v_h.remainder > 0 THEN 1 ELSE 0 END;
  SELECT count(*), round(COALESCE(sum(p.amount), 0), 2)
    INTO v_rows, v_amount
    FROM public.tournament_payouts p
   WHERE p.tournament_id = p_tournament_id;
  IF v_rows <> v_expected_rows OR v_amount IS DISTINCT FROM v_h.pool THEN
    RAISE EXCEPTION
      'satellite % payout evidence has % rows / % chips, expected % / %',
      p_tournament_id, v_rows, v_amount, v_expected_rows, v_h.pool
      USING ERRCODE = 'P0404';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.prize IS DISTINCT FROM CASE
         WHEN tp.position BETWEEN 1 AND v_h.ticket_award_count THEN v_h.ticket_cost
         WHEN v_h.remainder > 0 AND tp.position = v_h.bubble_position
           THEN v_h.remainder
         ELSE 0::numeric
       END
  ) THEN
    RAISE EXCEPTION 'satellite % prize cache disagrees with its receipt',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT * INTO v_source_escrow
    FROM public.tournament_escrow e
   WHERE e.tournament_id = p_tournament_id
   FOR UPDATE;
  IF v_source_escrow.tournament_id IS NULL
     OR COALESCE(v_source_escrow.enforced, false) IS NOT TRUE
     OR v_source_escrow.prize_out IS DISTINCT FROM v_h.pool
     OR v_source_escrow.bounty_in IS DISTINCT FROM 0::numeric
     OR v_source_escrow.bounty_out IS DISTINCT FROM 0::numeric
     OR v_source_escrow.refund_bounty IS DISTINCT FROM 0::numeric
     OR v_source_escrow.reserve_out IS DISTINCT FROM 0::numeric
     OR v_source_escrow.reserve_in IS DISTINCT FROM 0::numeric
     OR v_source_escrow.prize_balance IS DISTINCT FROM 0::numeric
     OR v_source_escrow.bounty_balance IS DISTINCT FROM 0::numeric
     OR v_source_escrow.fee_balance IS DISTINCT FROM 0::numeric
     OR v_source_escrow.closed_at IS DISTINCT FROM v_h.source_escrow_closed_at
     OR v_source_escrow.close_note IS DISTINCT FROM v_h.source_escrow_close_note
     OR EXISTS (
       SELECT 1
         FROM unnest(ARRAY[
           'gross_in','fee_entries_in','satellite_fee_in','bounty_in',
           'overlay_in','satellite_in','prize_out','bounty_out','fee_out',
           'refund_prize','refund_bounty','refund_fee',
           'prize_balance','bounty_balance','fee_balance',
           'reserve_out','reserve_in'
         ]::text[]) AS component(name)
         CROSS JOIN LATERAL (
           SELECT (to_jsonb(v_source_escrow)->>component.name)::numeric AS amount
         ) AS persisted
        WHERE persisted.amount IS NULL
           OR CASE
                WHEN persisted.amount::text IN ('NaN','Infinity','-Infinity')
                  THEN true
                ELSE persisted.amount < 0
                  OR persisted.amount IS DISTINCT FROM round(persisted.amount,2)
              END
     ) THEN
    RAISE EXCEPTION 'satellite % did not close every escrow bank at zero',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT * INTO v_rake_settlement
    FROM public.tournament_rake_settlements s
   WHERE s.tournament_id = p_tournament_id;
  SELECT round(COALESCE(sum(r.rake_amount), 0), 2) INTO v_rake
    FROM public.rake_records r
   WHERE r.tournament_id = p_tournament_id AND r.is_tournament;
  IF v_diamond THEN
    -- DIAMOND PHASE 9: a Diamond satellite's fee is its fee bank, settled to
    -- the house, not a rake_records sum.
    SELECT e.fee_balance + e.fee_out INTO v_rake
      FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id) e;
  END IF;
  v_accounting:=public.fn_accounting_tournament_terminal_fee_receipt(p_tournament_id);
  v_deferred:=COALESCE(v_accounting->>'status'='banked_accrual_deferred',false);
  IF v_rake_settlement.tournament_id IS NULL
     OR v_rake_settlement.settled_at IS NULL
     OR v_rake_settlement.amount IS DISTINCT FROM v_rake
     OR (v_rake > 0 AND v_rake_settlement.attributed_at IS NULL AND NOT v_deferred) THEN
    RAISE EXCEPTION 'satellite % rake has no exact terminal settlement',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'user_id', a.user_id,
           'position', a.place,
           'amount', a.amount,
           'delivery_kind', a.delivery_kind,
           'payout_id', a.payout_id,
           'registration_id', a.registration_id,
           'ticket_id', a.ticket_id)
         ORDER BY a.place), '[]'::jsonb)
    INTO v_awards
    FROM public.tournament_satellite_awards a
   WHERE a.tournament_id = p_tournament_id;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'user_id', a.user_id,
           'position', a.place,
           'amount', a.amount,
           'registration_id', a.registration_id)
         ORDER BY a.place), '[]'::jsonb)
    INTO v_seats
    FROM public.tournament_satellite_awards a
   WHERE a.tournament_id = p_tournament_id
     AND a.delivery_kind = 'seat';

  v_winner_amount := CASE WHEN v_h.ticket_award_count > 0
                          THEN v_h.ticket_cost ELSE v_h.remainder END;
  RETURN jsonb_build_object(
    'ok', true,
    'fully_settled', true,
    'status', 'COMPLETED',
    'tournament_id', p_tournament_id,
    'target_id', v_h.target_id,
    'winner_id', v_h.winner_id,
    'field_size', v_h.field_size,
    'pool', v_h.pool,
    'ticket_cost', v_h.ticket_cost,
    'ticket_award_count', v_h.ticket_award_count,
    'seat_count', v_h.seat_count,
    'cash_ticket_count', v_h.cash_ticket_count,
    'entry_ticket_count', v_h.entry_ticket_count,
    'awards', v_awards,
    'seats', v_seats,
    'remainder', v_remainder,
    'winner_amount', v_winner_amount,
    'source_table_count', v_h.source_table_count,
    'source_seat_count', v_h.source_seat_count,
    'released_seat_count', v_h.released_seat_count,
    'source_closeout', jsonb_build_object(
      'source_table_count', v_h.source_table_count,
      'source_table_ids', to_jsonb(v_h.source_table_ids),
      'source_seat_count', v_h.source_seat_count,
      'source_seat_ids', to_jsonb(v_h.source_seat_ids),
      'released_seat_count', v_h.released_seat_count,
      'released_seat_ids', to_jsonb(v_h.released_seat_ids),
      'closed_at', v_h.source_closed_at,
      'escrow_closed_at', v_h.source_escrow_closed_at,
      'escrow_close_note', v_h.source_escrow_close_note),
    'settled_at', v_h.settled_at,
    'receipt_version', v_h.receipt_version,
    'accounting',v_accounting);
END;
$$;


ALTER FUNCTION public.fn_ca_satellite_settlement_receipt(p_tournament_id uuid, p_observed_winner_id uuid) OWNER TO postgres;

--
-- TOC entry 4850 (class 1255 OID 35058885)
-- Name: fn_ca_satellite_target_accepts_new_feeder(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_satellite_target_accepts_new_feeder(p_target_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 -- A chip bounty, PKO or mystery-bounty MTT accepts a feeder (2026-10-16):
 -- its seat is booked exactly like a paid entry. Flags must be known; a
 -- Spin or a satellite is never a target.
 SELECT COALESCE((SELECT t.format_contract IN ('mtt-v1','mtt-v2')
   AND t.is_bounty IS NOT NULL AND t.is_pko IS NOT NULL AND t.is_mystery_bounty IS NOT NULL
   AND t.is_premium_spin IS FALSE
   AND lower(btrim(COALESCE(t.variant,''))) NOT IN ('satellite','spin')
   AND lower(btrim(COALESCE(t.tournament_type,''))) NOT IN ('satellite','spin')
   AND t.satellite_target_id IS NULL AND t.satellite_target IS NULL
   AND public.fn_poker_diamond_tournament(t.id) IS FALSE
   FROM public.tournaments t WHERE t.id=p_target_id),false);
$$;


ALTER FUNCTION public.fn_ca_satellite_target_accepts_new_feeder(p_target_id uuid) OWNER TO postgres;

--
-- TOC entry 9551 (class 1255 OID 162957718)
-- Name: fn_ca_satellite_ticket_target_is_closed(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_satellite_ticket_target_is_closed(p_target_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  /* A direct satellite ticket admits its holder to ONE target, and only while
     that target still takes entries. Once the target has finalized its pool,
     or is finishing, finished or cancelled, no door can ever admit the ticket
     again: the entry door refuses a finalized pool and every terminal state.
     Both facts only ever move one way, so a closed answer is permanent. */
  SELECT COALESCE((
    SELECT upper(COALESCE(t.status::text,'')) IN
             ('COMPLETING','COMPLETED','CANCELLED','CANCELED')
        OR COALESCE(t.prize_pool_finalized,false)
      FROM public.tournaments t
     WHERE t.id=p_target_id),false);
$$;


ALTER FUNCTION public.fn_ca_satellite_ticket_target_is_closed(p_target_id uuid) OWNER TO postgres;

--
-- TOC entry 7773 (class 1255 OID 151097579)
-- Name: fn_ca_schedule_config_keeps_chat(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_schedule_config_keeps_chat(p_config jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT jsonb_typeof(p_config) = 'object'
     AND lower(btrim(COALESCE(p_config ->> 'type', 'mtt'))) IN ('spin', 'sng', 'hu_sng', 'heads_up')
     AND NOT (
          btrim(CASE WHEN jsonb_typeof(p_config -> 'satellite_target_id') = 'string' THEN p_config ->> 'satellite_target_id' ELSE '' END) <> ''
       OR btrim(CASE WHEN jsonb_typeof(p_config -> 'satelliteTargetId') = 'string' THEN p_config ->> 'satelliteTargetId' ELSE '' END) <> ''
       OR EXISTS (
            SELECT 1
              FROM (VALUES (p_config -> 'satellite_target'), (p_config -> 'satelliteTarget')) AS t(v)
             WHERE (jsonb_typeof(t.v) = 'string' AND btrim(t.v #>> '{}') <> '')
                OR (jsonb_typeof(t.v) = 'object'
                    AND (btrim(CASE WHEN jsonb_typeof(t.v -> 'tournamentId') = 'string' THEN t.v ->> 'tournamentId' ELSE '' END) <> ''
                      OR btrim(CASE WHEN jsonb_typeof(t.v -> 'tournament_id') = 'string' THEN t.v ->> 'tournament_id' ELSE '' END) <> ''))))
$$;


ALTER FUNCTION public.fn_ca_schedule_config_keeps_chat(p_config jsonb) OWNER TO postgres;

--
-- TOC entry 9069 (class 1255 OID 224091054)
-- Name: fn_ca_schedule_level_clock_floor(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_schedule_level_clock_floor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_structure text; v_floor numeric;
BEGIN
 IF jsonb_typeof(NEW.config->'blindStructure')='array' THEN
  v_floor:=CASE WHEN coalesce((NEW.config->>'acceleratedMtt')::boolean,false) THEN 10
    WHEN upper(coalesce(NEW.config->>'blindPreset','STANDARD'))='STANDARD' THEN 8 ELSE 5 END;
  v_structure:=public.fn_ca_minimum_tournament_levels((NEW.config->'blindStructure')::text,v_floor);
  NEW.config:=jsonb_set(NEW.config,'{blindStructure}',v_structure::jsonb);
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_schedule_level_clock_floor() OWNER TO postgres;

--
-- TOC entry 9138 (class 1255 OID 23895113)
-- Name: fn_ca_second_writer_check(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_second_writer_check(p_calls jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  c            jsonb;
  v_fn         text;
  v_keys       text[];
  v_findings   jsonb := '[]'::jsonb;
  v_checked    int := 0;
  v_unchecked  int := 0;
  v_calls      int := 0;
  v_overloads  int;
  v_status     text;
  v_sr         boolean;
  v_role       text;
  v_sig_ok     boolean;
  v_live       text;
  v_writes     boolean;
  v_money      boolean;
  v_sev        text;
  v_kinds      jsonb := '{}'::jsonb;
BEGIN
  IF p_calls IS NULL OR jsonb_typeof(p_calls) <> 'array' THEN
    RAISE EXCEPTION 'fn_ca_second_writer_check wants a JSON array of {file, line, fn, keys}';
  END IF;

  FOR c IN SELECT * FROM jsonb_array_elements(p_calls) LOOP
    v_calls := v_calls + 1;
    v_fn := c->>'fn';
    IF v_fn IS NULL OR v_fn !~ '^[a-z_][a-z0-9_]*$' THEN
      v_findings := v_findings || jsonb_build_object('file', c->>'file', 'line', c->'line', 'fn', v_fn,
        'kind', 'unreadable_call', 'severity', 'error', 'money', true,
        'detail', 'the function name is not a plain identifier');
      CONTINUE;
    END IF;

    /* keys: null = the payload was not a literal object; the script could not
       read it, so this call is counted as UNCHECKED, never as fine. */
    IF c->'keys' IS NULL OR jsonb_typeof(c->'keys') <> 'array' THEN
      v_keys := NULL;
    ELSE
      SELECT array_agg(x) INTO v_keys FROM jsonb_array_elements_text(c->'keys') x;
      v_keys := COALESCE(v_keys, '{}'::text[]);
    END IF;
    /* Coverage is counted here, before any verdict, so a missing function is
       still a call that was checked and the totals always sum to `calls`. */
    IF v_keys IS NULL THEN v_unchecked := v_unchecked + 1; ELSE v_checked := v_checked + 1; END IF;

    /* WHICH ROLE THE ROUTE CALLS AS. A World Hub route that forwards the
       caller's token runs as authenticated and the door reads auth.uid();
       one holding the service key runs as service_role. Asking the wrong one
       reported a working money route as permission denied and never once
       asked whether the mint route's own grant was still there. Unknown is
       service_role, which is what every call was before. */
    v_role := c->>'role';
    IF v_role IS NULL OR v_role NOT IN ('service_role', 'authenticated') THEN
      v_role := 'service_role';
    END IF;

    SELECT count(*), bool_or(has_function_privilege(v_role, p.oid, 'EXECUTE')),
           string_agg('(' || COALESCE(array_to_string(p.proargnames[1:p.pronargs], ', '), '') || ')', ' | '),
           bool_or(
             (p.prosrc ~* 'UPDATE\s+(public\.)?(club_members|club_wallets|union_wallets|unions|table_seats|bbj_pools|clubs|agents|wallets|spin_bonus_pools|tournament_players)\y'
              OR p.prosrc ~* 'INSERT\s+INTO\s+(public\.)?(club_members|club_wallets|union_wallets|unions|bbj_pools|clubs|agents|wallets|spin_bonus_pools)\y'
              OR p.prosrc ~* 'EXECUTE\s+format\s*\(\s*''UPDATE')
             AND p.prosrc ~* '\y(chip_balance|held_chips|locked_chips|credit_used|credit_limit|stack|balance|chips|prize|bounty_winnings|promo_balance)\y')
      INTO v_overloads, v_sr, v_live, v_writes
      FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = v_fn;

    SELECT status INTO v_status FROM public.ca_money_rpc_registry WHERE proname = v_fn;

    /* A MONEY DOOR is one the register knows (any status) or one that writes
       balance columns. A function the register has never seen and that has
       no function body to read (missing) is judged by the register alone. */
    v_money := (v_status IS NOT NULL) OR COALESCE(v_writes, false);
    v_sev   := CASE WHEN v_money THEN 'error' ELSE 'warning' END;

    IF v_overloads = 0 THEN
      v_findings := v_findings || jsonb_build_object('file', c->>'file', 'line', c->'line', 'fn', v_fn,
        'kind', 'missing_function', 'severity', v_sev, 'money', v_money,
        'detail', 'no function of this name exists in public; the route gets PGRST202 on every call');
      CONTINUE;
    END IF;

    IF v_status = 'closed' THEN
      v_findings := v_findings || jsonb_build_object('file', c->>'file', 'line', c->'line', 'fn', v_fn,
        'kind', 'closed_door', 'severity', 'error', 'money', true,
        'detail', 'the register closed this door; the route still calls it. Refuse before writing, or remove the branch.');
    ELSIF NOT COALESCE(v_sr, false) THEN
      v_findings := v_findings || jsonb_build_object('file', c->>'file', 'line', c->'line', 'fn', v_fn,
        'kind', 'not_executable_by_' || v_role, 'severity', v_sev, 'money', v_money,
        'detail', v_role || ' cannot execute it; the route gets "permission denied" on every call');
    END IF;

    IF v_keys IS NOT NULL THEN
      /* PostgREST picks the overload whose NAMED parameters are exactly the
         keys sent, with every other parameter carrying a default. */
      SELECT bool_or(
               v_keys <@ COALESCE(p.proargnames[1:p.pronargs], '{}'::text[])
               AND NOT EXISTS (
                 SELECT 1 FROM unnest(COALESCE(p.proargnames[1:p.pronargs], '{}'::text[])) WITH ORDINALITY a(n, i)
                  WHERE NOT (a.n = ANY (v_keys))
                    AND a.i <= p.pronargs - p.pronargdefaults))
        INTO v_sig_ok
        FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = v_fn;
      IF NOT COALESCE(v_sig_ok, false) THEN
        v_findings := v_findings || jsonb_build_object('file', c->>'file', 'line', c->'line', 'fn', v_fn,
          'kind', 'signature_mismatch', 'severity', v_sev, 'money', v_money,
          'sent', to_jsonb(v_keys), 'live', v_live,
          'detail', 'no overload accepts exactly these parameter names; PostgREST answers PGRST202 and whatever the route does next is the only thing that runs');
      END IF;
    END IF;

    IF v_status IS NULL AND COALESCE(v_writes, false) THEN
      v_findings := v_findings || jsonb_build_object('file', c->>'file', 'line', c->'line', 'fn', v_fn,
        'kind', 'unregistered_writer', 'severity', 'warning', 'money', true,
        'detail', 'this function writes balance columns and is not in ca_money_rpc_registry: audit it, then register it');
    END IF;
  END LOOP;

  SELECT COALESCE(jsonb_object_agg(k, n), '{}'::jsonb) INTO v_kinds
    FROM (SELECT f->>'kind' AS k, count(*) AS n FROM jsonb_array_elements(v_findings) f GROUP BY 1) s;

  RETURN jsonb_build_object(
    'calls', v_calls,
    'checked', v_checked,
    'unchecked', v_unchecked,
    'errors', (SELECT count(*) FROM jsonb_array_elements(v_findings) f WHERE f->>'severity' = 'error'),
    'warnings', (SELECT count(*) FROM jsonb_array_elements(v_findings) f WHERE f->>'severity' = 'warning'),
    'kinds', v_kinds,
    'findings', v_findings,
    'registry', (SELECT jsonb_build_object('approved', count(*) FILTER (WHERE status = 'approved'),
                                           'closed', count(*) FILTER (WHERE status = 'closed'))
                   FROM public.ca_money_rpc_registry),
    'as_of', now());
END $_$;


ALTER FUNCTION public.fn_ca_second_writer_check(p_calls jsonb) OWNER TO postgres;

--
-- TOC entry 46245 (class 0 OID 0)
-- Dependencies: 9138
-- Name: FUNCTION fn_ca_second_writer_check(p_calls jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_second_writer_check(p_calls jsonb) IS 'Phase 7 (roadmap 9.6). Takes [{file,line,fn,keys}] as scanned from the World Hub''s pages/api/club-arena routes and answers whether each call agrees with pg_proc and ca_money_rpc_registry: missing, closed, not executable by service_role, parameter names no overload accepts, or an unregistered balance writer. The answer carries `unchecked` for calls whose payload could not be read.';


--
-- TOC entry 4057 (class 1255 OID 38570186)
-- Name: fn_ca_sep8_spin_original_fee_proof(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_sep8_spin_original_fee_proof(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE c record;r public.rake_records%ROWTYPE;t public.tournaments%ROWTYPE;
 v public.managed_game_contract_versions%ROWTYPE;tp record;e record;l record;s record;
 item record;n integer;gross numeric:=0;earliest timestamptz;rows jsonb:='[]';versions jsonb:='[]';
 reserve jsonb;game_union uuid;reserve_account uuid;
BEGIN
 IF p_tournament_id NOT IN (
 '199a71a9-f364-4e90-a3ba-3cdcfb7755bc'::uuid,'808ef798-0942-4ce0-9ae1-eeefaaf4b0a9',
 'b60c7add-6b38-4549-b091-601f64d118a0','e3f4e2ab-8397-43e8-8643-6cec3fff3a63',
 'f3f050f1-569e-4fb6-859f-86b6092e682e') THEN RETURN NULL; END IF;
 SELECT * INTO c FROM public.fn_ca_legacy_fee_custody_cohort(p_tournament_id);
 SELECT count(*) INTO n FROM public.rake_records WHERE tournament_id=p_tournament_id AND is_tournament;
 SELECT * INTO r FROM public.rake_records WHERE tournament_id=p_tournament_id AND is_tournament;
 SELECT * INTO t FROM public.tournaments WHERE id=p_tournament_id;
 IF n<>1 OR c.source_count IS DISTINCT FROM 1 OR r.source IS DISTINCT FROM 'fn_spin_book_entry'
  OR r.rake_amount IS DISTINCT FROM c.amount OR md5(public.fn_accounting_tournament_fee_fingerprint(r)) IS DISTINCT FROM c.source_fingerprint
  OR r.created_at>='2026-09-17T18:24:02.831517Z'::timestamptz OR r.hand_id IS NOT NULL
  OR r.metadata->>'kind' IS DISTINCT FROM 'spin_rake' OR jsonb_typeof(r.player_contributions) IS DISTINCT FROM 'object'
  OR t.is_private IS DISTINCT FROM false OR t.variant IS DISTINCT FROM 'spin' OR t.tournament_type IS DISTINCT FROM 'SPIN'
  OR public.fn_poker_diamond_tournament(p_tournament_id)
 THEN RAISE EXCEPTION 'named Spin original aggregate identity missing' USING ERRCODE='P0404'; END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(r.player_contributions))<>3
  OR (SELECT count(*) FROM public.tournament_players WHERE tournament_id=p_tournament_id)<>3
  OR (SELECT count(DISTINCT value::numeric) FROM jsonb_each_text(r.player_contributions))<>1
 THEN RAISE EXCEPTION 'named Spin requires exactly three equal original paid contributors' USING ERRCODE='P0404'; END IF;
 FOR item IN SELECT key::uuid player_id,value::numeric weight FROM jsonb_each_text(r.player_contributions) ORDER BY key LOOP
  SELECT * INTO tp FROM public.tournament_players WHERE tournament_id=p_tournament_id AND user_id=item.player_id;
  SELECT count(*) INTO n FROM public.tournament_refund_entitlements x WHERE x.tournament_id=p_tournament_id
   AND x.user_id=item.player_id AND x.entitlement_kind='wallet_charge' AND x.charge_category='tournament_buyin'
   AND x.created_at=tp.registered_at AND x.gross=item.weight;
  IF n<>1 THEN RAISE EXCEPTION 'named Spin original paid entry ambiguous' USING ERRCODE='P0404'; END IF;
  SELECT * INTO e FROM public.tournament_refund_entitlements x WHERE x.tournament_id=p_tournament_id
   AND x.user_id=item.player_id AND x.entitlement_kind='wallet_charge' AND x.charge_category='tournament_buyin'
   AND x.created_at=tp.registered_at AND x.gross=item.weight;
  SELECT * INTO l FROM public.chip_ledger WHERE id=e.source_ledger_id;
  IF l.id IS NULL OR tp.club_id IS DISTINCT FROM e.refund_wallet_club_id OR l.created_at IS DISTINCT FROM e.created_at
   OR e.created_at>r.created_at OR l.amount IS DISTINCT FROM e.gross OR l.club_id IS DISTINCT FROM e.refund_wallet_club_id
   OR l.from_type IS DISTINCT FROM 'player_wallet' OR l.from_entity_id IS DISTINCT FROM item.player_id
   OR l.to_type IS DISTINCT FROM 'prize_liability' OR l.to_entity_id IS DISTINCT FROM p_tournament_id
   OR l.category IS DISTINCT FROM 'tournament_buyin' OR item.weight<=0
  THEN RAISE EXCEPTION 'named Spin original debit evidence disagrees' USING ERRCODE='P0404'; END IF;
  earliest:=least(earliest,e.created_at);gross:=gross+item.weight;
  rows:=rows||jsonb_build_array(jsonb_build_object('registration_id',tp.id,'player_id',item.player_id,
   'club_id',tp.club_id,'registered_at',tp.registered_at,'entitlement',to_jsonb(e)-'terminal_closed_at','ledger',to_jsonb(l)));
 END LOOP;
 SELECT count(*) INTO n FROM public.spin_reserve_ledger WHERE tournament_id=p_tournament_id AND kind='contribution';
 SELECT * INTO s FROM public.spin_reserve_ledger WHERE tournament_id=p_tournament_id AND kind='contribution';
 IF n<>1 OR s.seats IS DISTINCT FROM 3 OR s.house_rake IS DISTINCT FROM r.rake_amount
  OR s.amount IS DISTINCT FROM gross-r.rake_amount OR s.buy_in IS DISTINCT FROM gross/3
 THEN RAISE EXCEPTION 'named Spin original reserve contribution disagrees' USING ERRCODE='P0404'; END IF;
 reserve:=jsonb_build_object('contribution',to_jsonb(s)-'terminal_closed_at');
 SELECT count(*) INTO n FROM public.chip_ledger x WHERE x.tournament_id=p_tournament_id AND x.category='spin_entry';
 SELECT * INTO l FROM public.chip_ledger x WHERE x.tournament_id=p_tournament_id AND x.category='spin_entry';
 IF n<>1 OR l.amount IS DISTINCT FROM s.amount OR l.created_at IS DISTINCT FROM s.created_at
  OR l.club_id IS DISTINCT FROM s.club_id OR l.from_type IS DISTINCT FROM 'prize_liability'
  OR l.from_entity_id IS DISTINCT FROM p_tournament_id OR l.to_type IS DISTINCT FROM 'spin_reserve' OR l.to_entity_id IS NULL
 THEN RAISE EXCEPTION 'named Spin reserve contribution debit disagrees' USING ERRCODE='P0404'; END IF;
 reserve_account:=l.to_entity_id;reserve:=reserve||jsonb_build_object('contribution_ledger',to_jsonb(l));
 SELECT count(*) INTO n FROM public.spin_reserve_ledger WHERE tournament_id=p_tournament_id AND kind='jackpot_draw';
 SELECT * INTO s FROM public.spin_reserve_ledger WHERE tournament_id=p_tournament_id AND kind='jackpot_draw';
 IF n<>1 OR s.seats IS DISTINCT FROM 3 OR s.house_rake IS DISTINCT FROM r.rake_amount
  OR s.amount IS DISTINCT FROM -t.prize_pool OR s.buy_in IS DISTINCT FROM gross/3 OR s.amount>=0
 THEN RAISE EXCEPTION 'named Spin original prize draw disagrees' USING ERRCODE='P0404'; END IF;
 reserve:=reserve||jsonb_build_object('draw',to_jsonb(s)-'terminal_closed_at');
 SELECT count(*) INTO n FROM public.chip_ledger x WHERE x.tournament_id=p_tournament_id AND x.category='spin_prize';
 SELECT * INTO l FROM public.chip_ledger x WHERE x.tournament_id=p_tournament_id AND x.category='spin_prize';
 IF n<>1 OR l.amount IS DISTINCT FROM -s.amount OR l.created_at IS DISTINCT FROM s.created_at
  OR l.club_id IS DISTINCT FROM s.club_id OR l.from_type IS DISTINCT FROM 'spin_reserve'
  OR l.from_entity_id IS DISTINCT FROM reserve_account OR l.to_type IS DISTINCT FROM 'prize_liability'
  OR l.to_entity_id IS DISTINCT FROM p_tournament_id
 THEN RAISE EXCEPTION 'named Spin original prize draw credit disagrees' USING ERRCODE='P0404'; END IF;
 reserve:=reserve||jsonb_build_object('draw_ledger',to_jsonb(l));
 SELECT * INTO v FROM public.managed_game_contract_versions WHERE game_id=p_tournament_id AND game_kind='tournament' AND version=1;
 IF NOT FOUND OR v.published_at>earliest OR v.club_id IS DISTINCT FROM r.club_id
  OR v.club_id IS DISTINCT FROM t.club_id OR v.union_id IS DISTINCT FROM t.union_id
 THEN RAISE EXCEPTION 'named Spin original created scope missing' USING ERRCODE='P0404'; END IF;
 game_union:=v.union_id;
 FOR v IN SELECT * FROM public.managed_game_contract_versions WHERE game_id=p_tournament_id AND game_kind='tournament'
  AND published_at<=r.created_at ORDER BY version,id LOOP
  IF v.club_id IS DISTINCT FROM t.club_id OR v.union_id IS DISTINCT FROM game_union
   OR v.contract->>'id' IS DISTINCT FROM p_tournament_id::text OR v.contract->>'club_id' IS DISTINCT FROM v.club_id::text
   OR NULLIF(v.contract->>'union_id','')::uuid IS DISTINCT FROM game_union OR v.contract->'is_private' IS DISTINCT FROM 'false'::jsonb
   OR v.contract->>'variant' IS DISTINCT FROM 'spin' OR v.contract->>'tournament_type' IS DISTINCT FROM 'SPIN'
   OR (v.contract->>'buy_in_amount')::numeric IS DISTINCT FROM gross/3 OR (v.contract->>'max_players')::integer IS DISTINCT FROM 3
   OR v.contract_hash IS DISTINCT FROM public.fn_managed_game_contract_hash(v.contract)
  THEN RAISE EXCEPTION 'named Spin immutable economic scope disagrees' USING ERRCODE='P0404'; END IF;
  versions:=versions||jsonb_build_array(to_jsonb(v));
 END LOOP;
 RETURN jsonb_build_object('tournament_id',p_tournament_id,'raw_source_count',1,'recognized_contributors',3,
  'source_fingerprint',c.source_fingerprint,'fee',c.amount,'gross',gross,'contributors',rows,'reserve',reserve,'scope_versions',versions);
END $$;


ALTER FUNCTION public.fn_ca_sep8_spin_original_fee_proof(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 6412 (class 1255 OID 137567711)
-- Name: fn_ca_set_emergency_stop(text, boolean, bigint, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_set_emergency_stop(p_path text, p_stopped boolean, p_expected_version bigint, p_reason text, p_op_id uuid, p_actor_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE required_permission text; permissions jsonb; prior public.ca_emergency_stop_operations%ROWTYPE;
 before_row public.ca_emergency_stops%ROWTYPE; result jsonb;
BEGIN
 required_permission:=CASE p_path WHEN 'tournament_registration' THEN 'settings.write' WHEN 'positive_issuance' THEN 'money.write' WHEN 'cashout' THEN 'cashier.write' END;
 IF required_permission IS NULL OR p_stopped IS NULL OR p_actor_id IS NULL OR p_op_id IS NULL OR p_expected_version IS NULL OR p_expected_version<0
  OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 10 AND 500 OR length(COALESCE(p_request_id,'')) NOT BETWEEN 1 AND 200
 THEN RAISE EXCEPTION 'invalid_stop_operation' USING ERRCODE='22023'; END IF;
 permissions:=public.fn_ca_operator_permissions(p_actor_id)->'permissions';
 IF NOT COALESCE(permissions ? required_permission,false) OR NOT COALESCE(permissions ? 'console.read',false)
 THEN RAISE EXCEPTION 'stop_permission_denied' USING ERRCODE='42501'; END IF;
 -- Operation lock first; a reused UUID may never change paths or actors.
 PERFORM pg_advisory_xact_lock(hashtextextended('ca-stop-op:'||p_op_id::text,0));
 SELECT * INTO prior FROM public.ca_emergency_stop_operations WHERE op_id=p_op_id;
 IF FOUND THEN
  IF prior.actor_id IS DISTINCT FROM p_actor_id OR prior.path IS DISTINCT FROM p_path OR prior.stopped IS DISTINCT FROM p_stopped
   OR prior.expected_version IS DISTINCT FROM p_expected_version OR prior.reason IS DISTINCT FROM btrim(p_reason)
  THEN RAISE EXCEPTION 'stop_operation_conflict' USING ERRCODE='22023'; END IF;
  RETURN prior.result||jsonb_build_object('replayed',true);
 END IF;
 -- Wait for all previously admitted transactions. Once this returns, no new
 -- operation can commit using an earlier observed open state.
 PERFORM pg_advisory_xact_lock(hashtextextended('ca-emergency-stop:'||p_path,0));
 SELECT * INTO before_row FROM public.ca_emergency_stops WHERE path=p_path FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'emergency_stop_authority_missing' USING ERRCODE='55000'; END IF;
 IF before_row.version IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION 'stop_version_changed' USING ERRCODE='55000'; END IF;
 UPDATE public.ca_emergency_stops SET stopped=p_stopped,version=version+1,reason=btrim(p_reason),actor_id=p_actor_id,updated_at=transaction_timestamp() WHERE path=p_path;
 result:=jsonb_build_object('ok',true,'op_id',p_op_id,'path',p_path,'stopped',p_stopped,'version',before_row.version+1,'replayed',false);
 INSERT INTO public.ca_emergency_stop_operations(op_id,actor_id,path,stopped,expected_version,version,reason,result)
 VALUES(p_op_id,p_actor_id,p_path,p_stopped,p_expected_version,before_row.version+1,btrim(p_reason),result);
 PERFORM public.fn_log_admin_action(p_actor_id,'platform.emergency_stop','emergency_stop',p_path,
  jsonb_build_object('op_id',p_op_id,'reason',btrim(p_reason),'permission',required_permission),
  to_jsonb(before_row),result,NULL,NULL,p_request_id);
 RETURN result;
END $$;


ALTER FUNCTION public.fn_ca_set_emergency_stop(p_path text, p_stopped boolean, p_expected_version bigint, p_reason text, p_op_id uuid, p_actor_id uuid, p_request_id text) OWNER TO postgres;

--
-- TOC entry 8777 (class 1255 OID 27166760)
-- Name: fn_ca_settle_bounty_rebuy_generation_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_settle_bounty_rebuy_generation_v1(p_tournament_id uuid, p_user_id uuid, p_candidate_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_player public.tournament_players%ROWTYPE;
  v_candidate public.tournament_knockout_candidates%ROWTYPE;
  v_obligation public.tournament_bounty_obligations%ROWTYPE;
  v_claim jsonb;
  v_result jsonb;
  v_reserve jsonb;
  v_award_id uuid;
  v_award_status text;
  v_chest_id uuid;
  v_seat_exit_token uuid;
  v_position integer;
  v_rows integer;
  v_head_after numeric;
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL OR p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'Bounty rebuy requires one exact knockout generation'
      USING ERRCODE='22023';
  END IF;

  -- process_tournament_rebuy owns the terminal root, maintenance gate,
  -- tournament seat-acquisition root, and atomic table key before entering.
  -- Reacquire the exact rows here so this private step remains independently
  -- fail-closed if its caller ever drifts.
  SELECT * INTO v_t
    FROM public.tournaments t
   WHERE t.id=p_tournament_id
   FOR UPDATE;
  IF NOT FOUND OR upper(COALESCE(v_t.status::text,''))<>'RUNNING'
     OR NOT (COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
             OR COALESCE(v_t.is_mystery_bounty,false)) THEN
    RAISE EXCEPTION 'Bounty rebuy generation is not claimable'
      USING ERRCODE='55000';
  END IF;

  SELECT * INTO v_player
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
   FOR UPDATE;
  IF NOT FOUND OR v_player.status::text NOT IN ('playing','eliminated')
     OR COALESCE(v_player.chips,0)<>0 OR COALESCE(v_player.prize,0)<>0 THEN
    RAISE EXCEPTION 'Only the exact unpaid zero-stack bounty entry may be replaced'
      USING ERRCODE='55000';
  END IF;

  PERFORM c.id
    FROM public.tournament_knockout_candidates c
   WHERE c.tournament_id=p_tournament_id
     AND c.eliminated_user_id=p_user_id
   ORDER BY c.hand_number,c.id
   FOR UPDATE;
  SELECT * INTO v_candidate
    FROM public.tournament_knockout_candidates c
   WHERE c.id=p_candidate_id
     AND c.tournament_id=p_tournament_id
     AND c.eliminated_user_id=p_user_id
   FOR UPDATE;
  IF NOT FOUND
     OR v_candidate.id IS DISTINCT FROM
          public.fn_ca_latest_committed_knockout_candidate(
            p_tournament_id,p_user_id)
     OR v_candidate.state NOT IN ('pending','eliminated') THEN
    RAISE EXCEPTION 'Bounty rebuy does not name the latest committed knockout generation'
      USING ERRCODE='P0404';
  END IF;

  SELECT * INTO v_obligation
    FROM public.tournament_bounty_obligations o
   WHERE o.tournament_id=p_tournament_id
     AND o.eliminated_user_id=p_user_id
     AND o.table_id=v_candidate.table_id
     AND o.hand_id=v_candidate.hand_id
     AND o.hand_number=v_candidate.hand_number
     AND o.seat_joined_at=v_candidate.seat_joined_at
   FOR UPDATE;

  IF NOT FOUND THEN
    -- A new obligation may be born here only for the still-open generation
    -- this purchase is replacing. An already-eliminated generation must carry
    -- its durable outbox; this path never reconstructs one from history.
    IF v_candidate.state<>'pending'
       OR v_player.status::text<>'playing'
       OR v_candidate.rebuy_prompt_until IS NULL
       OR v_candidate.rebuy_prompt_until<=clock_timestamp() THEN
      RAISE EXCEPTION 'Bounty rebuy cannot create a missing closed-generation obligation'
        USING ERRCODE='P0404';
    END IF;

    -- This is an entry-generation knockout, not a final tournament result.
    -- The existing outbox schema requires the field position observed at the
    -- status CAS; prize is exactly zero and the money core clears the temporary
    -- position again before the transaction can commit.
    SELECT GREATEST(2,count(*)::integer) INTO v_position
      FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id AND tp.status='playing';

    -- The exact claim also retires the zero-stack chair. Keep the permanent
    -- seat-exit guard intact by opening its one-use elimination capability in
    -- this same transaction and requiring the claim to consume it exactly.
    v_seat_exit_token:=public.fn_ca_open_tournament_seat_exit_authority(
      p_tournament_id,'elimination',p_user_id);
    BEGIN
      v_claim:=public.fn_claim_bounty_legacy_candidate_20260907(
        p_tournament_id,p_user_id,v_position,0,
        v_candidate.table_id,v_candidate.hand_id,v_candidate.hand_number,
        v_candidate.seat_joined_at,NULL,NULL,0,false);
      PERFORM public.fn_ca_close_tournament_seat_exit_authority(
        v_seat_exit_token,
        COALESCE((v_claim->>'ok')::boolean,false)
          AND COALESCE((v_claim->>'claimed')::boolean,false));
    EXCEPTION WHEN OTHERS THEN
      PERFORM public.fn_ca_close_tournament_seat_exit_authority(
        v_seat_exit_token,false);
      RAISE;
    END;
    IF COALESCE((v_claim->>'ok')::boolean,false) IS NOT TRUE
       OR COALESCE((v_claim->>'claimed')::boolean,false) IS NOT TRUE
       OR COALESCE(v_claim->>'obligation_id','')='' THEN
      RAISE EXCEPTION 'Atomic bounty rebuy claim refused: %',
        COALESCE(v_claim::text,'null') USING ERRCODE='P0404';
    END IF;

    SELECT * INTO v_obligation
      FROM public.tournament_bounty_obligations o
     WHERE o.id=(v_claim->>'obligation_id')::uuid
       AND o.tournament_id=p_tournament_id
       AND o.eliminated_user_id=p_user_id
       AND o.table_id=v_candidate.table_id
       AND o.hand_id=v_candidate.hand_id
       AND o.hand_number=v_candidate.hand_number
       AND o.seat_joined_at=v_candidate.seat_joined_at
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Atomic bounty rebuy claim returned no exact obligation'
        USING ERRCODE='P0404';
    END IF;
  END IF;

  IF v_obligation.state='settled' THEN
    IF NOT public.fn_bounty_obligation_has_complete_marker(v_obligation.id) THEN
      RAISE EXCEPTION 'Settled bounty rebuy obligation has no complete marker'
        USING ERRCODE='P0404';
    END IF;
  ELSIF v_obligation.mode='mystery_chest' THEN
    v_reserve:=public.fn_mystery_bounty_reserve(
      p_tournament_id,p_user_id,v_obligation.claimants,
      v_obligation.table_id,v_obligation.hand_id::text,
      md5('mb:'||v_obligation.id::text)::uuid,1);
    IF COALESCE((v_reserve->>'ok')::boolean,false) IS NOT TRUE
       OR COALESCE(v_reserve->>'obligation_id','')<>v_obligation.id::text
       OR COALESCE(v_reserve->>'recipients_verified','false')<>'true' THEN
      RAISE EXCEPTION 'Atomic mystery-bounty rebuy reserve refused: %',
        COALESCE(v_reserve::text,'null') USING ERRCODE='P0404';
    END IF;
    BEGIN
      v_award_id:=(v_reserve->>'award_id')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'Atomic mystery-bounty rebuy reserve returned no award id'
        USING ERRCODE='P0404';
    END;

    SELECT a.status,a.chest_id INTO v_award_status,v_chest_id
      FROM public.tournament_bounty_awards a
     WHERE a.id=v_award_id
       AND a.tournament_id=p_tournament_id
       AND a.eliminated_user_id=p_user_id
       AND a.bounty_obligation_id=v_obligation.id
     FOR UPDATE;
    IF NOT FOUND OR v_award_status NOT IN ('reserved','revealed','paid','completed') THEN
      RAISE EXCEPTION 'Atomic mystery-bounty rebuy award is not exact or payable'
        USING ERRCODE='P0404';
    END IF;

    -- The browser reveal RPC correctly trusts auth.uid(), so an authenticated
    -- busted player cannot impersonate the designated knocker. This owner-only
    -- purchase step performs the same two-row reveal transition under the
    -- already-held tournament lock before paying it immediately.
    IF v_award_status='reserved' THEN
      UPDATE public.tournament_bounty_awards a
         SET status='revealed',revealed_at=COALESCE(a.revealed_at,now())
       WHERE a.id=v_award_id AND a.status='reserved';
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      IF v_rows<>1 THEN
        RAISE EXCEPTION 'Atomic mystery-bounty rebuy award changed before reveal'
          USING ERRCODE='55000';
      END IF;
      UPDATE public.tournament_bounty_chests c
         SET status='revealed'
       WHERE c.id=v_chest_id AND c.status='reserved';
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      IF v_rows<>1 THEN
        RAISE EXCEPTION 'Atomic mystery-bounty rebuy chest changed before reveal'
          USING ERRCODE='55000';
      END IF;
    END IF;

    v_result:=public.fn_mystery_bounty_pay(v_award_id);
    IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE
       OR COALESCE((v_result->>'refused_recipients')::integer,0)<>0 THEN
      RAISE EXCEPTION 'Atomic mystery-bounty rebuy payment refused: %',
        COALESCE(v_result::text,'null') USING ERRCODE='P0404';
    END IF;
  ELSE
    v_result:=public.fn_collect_bounty_obligation(v_obligation.id);
    IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'Atomic bounty rebuy payment refused: %',
        COALESCE(v_result::text,'null') USING ERRCODE='P0404';
    END IF;
  END IF;

  SELECT * INTO v_obligation
    FROM public.tournament_bounty_obligations o
   WHERE o.id=v_obligation.id
   FOR UPDATE;
  IF NOT FOUND OR v_obligation.state<>'settled'
     OR NOT public.fn_bounty_obligation_has_complete_marker(v_obligation.id) THEN
    RAISE EXCEPTION 'Bounty rebuy old head did not produce its exact settled marker'
      USING ERRCODE='P0404';
  END IF;

  -- Fixed and PKO collection already clear the old head. Mystery payout owns a
  -- chest rather than current_bounty, so clear that same snapshotted generation
  -- here. A different nonzero head means the generation changed and must abort.
  SELECT tp.current_bounty INTO v_head_after
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
   FOR UPDATE;
  IF round(COALESCE(v_head_after,0),2)<>0
     AND round(COALESCE(v_head_after,0),2)<>round(v_obligation.head_amount,2) THEN
    RAISE EXCEPTION 'Bounty rebuy old head changed before retirement'
      USING ERRCODE='55000';
  END IF;
  UPDATE public.tournament_players tp
     SET current_bounty=0
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
     AND round(COALESCE(tp.current_bounty,0),2) IN
           (0,round(v_obligation.head_amount,2));
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 OR EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
       AND round(COALESCE(tp.current_bounty,0),2)<>0
  ) THEN
    RAISE EXCEPTION 'Bounty rebuy old head was not retired exactly once'
      USING ERRCODE='P0404';
  END IF;

  RETURN jsonb_build_object(
    'ok',true,'obligation_id',v_obligation.id,
    'mode',v_obligation.mode,'old_head',v_obligation.head_amount,
    'marker_verified',true,'old_head_cleared',true);
END;
$$;


ALTER FUNCTION public.fn_ca_settle_bounty_rebuy_generation_v1(p_tournament_id uuid, p_user_id uuid, p_candidate_id uuid) OWNER TO postgres;

--
-- TOC entry 9113 (class 1255 OID 167526548)
-- Name: fn_ca_settle_closed_cashier_entry_tickets(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_settle_closed_cashier_entry_tickets(p_target_id uuid, p_source text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bind public.tournament_ticket_entry_targets%ROWTYPE;
  v_tk public.tournament_tickets%ROWTYPE;
  v_context jsonb;
  v_setting text;
  v_after numeric;
  v_paid integer := 0;
  v_returned integer := 0;
  v_amount numeric := 0;
  v_unpaid jsonb := '[]'::jsonb;
BEGIN
  /* A cashier entry ticket admits its holder to ONE tournament, only while it
     still takes entries. In the transaction that finalizes, finishes or
     cancels it, every still-unused ticket for it is settled here, once: to the
     holder's wallet in the ticket's club (seat_or_cash, as a satellite seat
     whose target closed, 20261012054804), or, if the holder is no longer an
     active member, back to the issuer exactly as fn_cancel_tournament_ticket
     would. A ticket neither can receive is named on a critical alert and
     stays escrowed for the issuer to cancel. Horses are paid exactly so. */
  IF p_target_id IS NULL
     OR NOT public.fn_ca_satellite_ticket_target_is_closed(p_target_id) THEN
    RETURN jsonb_build_object('ok',true,'paid',0,'returned',0,'amount',0);
  END IF;
  FOR v_bind IN
    SELECT b.* FROM public.tournament_ticket_entry_targets b
      JOIN public.tournament_tickets tk ON tk.id = b.ticket_id
     WHERE b.tournament_id = p_target_id AND tk.status = 'issued'
     ORDER BY b.ticket_id
  LOOP
    BEGIN
      SELECT * INTO v_tk FROM public.tournament_tickets tk
       WHERE tk.id = v_bind.ticket_id FOR UPDATE;
      IF v_tk.status IS DISTINCT FROM 'issued' THEN
        CONTINUE;
      END IF;
      SELECT jsonb_object_agg(k,COALESCE(current_setting(k,true),'')) INTO v_context
        FROM unnest(ARRAY['app.ledger_category','app.ledger_counterparty',
                          'app.ledger_counterparty_entity','app.ledger_tournament']) settings(k);
      PERFORM set_config('app.ledger_tournament','',true);
      PERFORM set_config('app.ledger_counterparty','escrow',true);
      PERFORM set_config('app.ledger_counterparty_entity',v_tk.id::text,true);

      PERFORM set_config('app.ledger_category','ticket_redeem',true);
      v_after := NULL;
      UPDATE public.club_members
         SET chip_balance = COALESCE(chip_balance,0) + v_tk.value, updated_at = now()
       WHERE club_id = v_tk.club_id AND user_id = v_tk.holder_id
         AND COALESCE(status,'active') IN ('active','approved')
       RETURNING chip_balance INTO v_after;
      IF v_after IS NOT NULL THEN
        FOR v_setting IN SELECT jsonb_object_keys(v_context) LOOP
          PERFORM set_config(v_setting,v_context->>v_setting,true);
        END LOOP;
        UPDATE public.tournament_tickets
           SET status = 'redeemed', redeemed_at = now()
         WHERE id = v_tk.id AND status = 'issued';
        INSERT INTO public.chip_transactions(
          club_id,from_user_id,to_user_id,amount,transaction_type,notes,
          balance_after,metadata)
        VALUES(
          v_tk.club_id,NULL,v_tk.holder_id,v_tk.value,'tournament_ticket_redeem',
          'Tournament Ticket Paid In Cash: Entry Closed',v_after,
          jsonb_build_object(
            'ticket_id',v_tk.id,'issuer_id',v_tk.issued_by,'holder_id',v_tk.holder_id,
            'escrow_action','release_to_holder','reason','target_entry_closed',
            'target_tournament_id',p_target_id,'source',p_source,
            'holder_balance_after',v_after));
        INSERT INTO public.wallet_transactions(
          user_id,wallet_type,type,amount,category,description,balance_after)
        VALUES(
          v_tk.holder_id,'PLAYER','credit',v_tk.value,'transfer',
          'Tournament Ticket Paid In Cash: Entry Closed',v_after);
        v_paid := v_paid + 1;
        v_amount := round(v_amount + v_tk.value,2);
        CONTINUE;
      END IF;

      PERFORM set_config('app.ledger_category','escrow_release',true);
      UPDATE public.club_members
         SET chip_balance = COALESCE(chip_balance,0) + v_tk.value, updated_at = now()
       WHERE club_id = v_tk.club_id AND user_id = v_tk.issued_by
         AND COALESCE(status,'active') IN ('active','approved')
       RETURNING chip_balance INTO v_after;
      FOR v_setting IN SELECT jsonb_object_keys(v_context) LOOP
        PERFORM set_config(v_setting,v_context->>v_setting,true);
      END LOOP;
      IF v_after IS NULL THEN
        v_unpaid := v_unpaid || jsonb_build_array(jsonb_build_object(
          'ticket_id',v_tk.id,'reason','holder_and_issuer_not_active'));
        INSERT INTO public.financial_alerts(severity,source,message,context)
        VALUES('critical','fn_ca_settle_closed_cashier_entry_tickets',
          'A Cashier Tournament Ticket For A Closed Tournament Has No Active Holder Or Issuer',
          jsonb_build_object('target_id',p_target_id,'ticket_id',v_tk.id,
            'holder_id',v_tk.holder_id,'issuer_id',v_tk.issued_by,'value',v_tk.value));
        CONTINUE;
      END IF;
      UPDATE public.tournament_tickets
         SET status = 'cancelled', cancelled_at = now()
       WHERE id = v_tk.id AND status = 'issued';
      INSERT INTO public.chip_transactions(
        club_id,from_user_id,to_user_id,amount,transaction_type,notes,
        balance_after,metadata)
      VALUES(
        v_tk.club_id,NULL,v_tk.issued_by,v_tk.value,'tournament_ticket_cancel',
        'Tournament Ticket Returned: Entry Closed',v_after,
        jsonb_build_object(
          'ticket_id',v_tk.id,'issuer_id',v_tk.issued_by,'holder_id',v_tk.holder_id,
          'escrow_action','refund_to_issuer','reason','target_entry_closed_holder_left',
          'target_tournament_id',p_target_id,'source',p_source,
          'issuer_balance_after',v_after));
      v_returned := v_returned + 1;
      v_amount := round(v_amount + v_tk.value,2);
    EXCEPTION WHEN OTHERS THEN
      v_unpaid := v_unpaid || jsonb_build_array(jsonb_build_object(
        'ticket_id',v_bind.ticket_id,'reason','refused',
        'sqlstate',SQLSTATE,'message',SQLERRM));
      INSERT INTO public.financial_alerts(severity,source,message,context)
      VALUES('critical','fn_ca_settle_closed_cashier_entry_tickets',
        'A Cashier Tournament Ticket For A Closed Tournament Could Not Be Settled',
        jsonb_build_object('target_id',p_target_id,'ticket_id',v_bind.ticket_id,
          'sqlstate',SQLSTATE,'message',SQLERRM));
    END;
  END LOOP;
  RETURN jsonb_build_object('ok',jsonb_array_length(v_unpaid)=0,
    'paid',v_paid,'returned',v_returned,'amount',v_amount,'unpaid',v_unpaid);
END;
$$;


ALTER FUNCTION public.fn_ca_settle_closed_cashier_entry_tickets(p_target_id uuid, p_source text) OWNER TO postgres;

--
-- TOC entry 4128 (class 1255 OID 25131749)
-- Name: fn_ca_settle_final_table_deal_share_raw(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_settle_final_table_deal_share_raw(p_tournament_id uuid, p_user_id uuid, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL
     OR p_amount IS NULL
     OR p_amount::text IN ('NaN','Infinity','-Infinity')
     OR p_amount <= 0
     OR p_amount IS DISTINCT FROM round(p_amount, 2) THEN
    RAISE EXCEPTION 'raw final-table-deal settlement received invalid derived inputs'
      USING ERRCODE = '22023';
  END IF;

  v_result := public.fn_settle_tournament_obligation_before_atomic_batch_gate(
    p_tournament_id,
    'final_table_deal',
    NULL,
    p_user_id,
    p_amount,
    'final_table_deal',
    'Final Table Deal (Exact-Cent Chip Chop)',
    NULL
  );

  IF COALESCE((v_result->>'ok')::boolean, false) IS NOT TRUE
     OR COALESCE((v_result->>'fully_settled')::boolean, false) IS NOT TRUE
     OR (v_result->>'amount_owed')::numeric IS DISTINCT FROM p_amount
     OR (v_result->>'amount_paid')::numeric IS DISTINCT FROM p_amount
     OR COALESCE((v_result->>'remaining')::numeric, p_amount) <> 0 THEN
    RAISE EXCEPTION 'tournament % deal share for % did not settle in full: %',
      p_tournament_id, p_user_id, v_result USING ERRCODE = 'P0404';
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_ca_settle_final_table_deal_share_raw(p_tournament_id uuid, p_user_id uuid, p_amount numeric) OWNER TO postgres;

--
-- TOC entry 46251 (class 0 OID 0)
-- Dependencies: 4128
-- Name: FUNCTION fn_ca_settle_final_table_deal_share_raw(p_tournament_id uuid, p_user_id uuid, p_amount numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_settle_final_table_deal_share_raw(p_tournament_id uuid, p_user_id uuid, p_amount numeric) IS 'Owner-only final-table-deal obligation payer. The atomic deal door derives its inputs and any partial result raises.';


--
-- TOC entry 8766 (class 1255 OID 18204499)
-- Name: fn_ca_settle_hand_stacks(uuid, uuid, bigint, jsonb, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_settle_hand_stacks(p_table_id uuid, p_hand_id uuid, p_hand_number bigint DEFAULT NULL::bigint, p_deltas jsonb DEFAULT '[]'::jsonb, p_rake numeric DEFAULT 0, p_bbj numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_claimed integer; v_prior record; v_sum numeric := 0; v_n integer := 0;
  e jsonb; v_uid uuid; v_delta numeric; v_updated integer;
  v_ca_id uuid; v_err text; v_result jsonb;
BEGIN
  IF NOT (current_user IN ('postgres', 'service_role')) THEN
    RAISE EXCEPTION 'fn_ca_settle_hand_stacks is engine/service only';
  END IF;
  IF p_table_id IS NULL OR p_hand_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'missing_ids');
  END IF;
  IF jsonb_typeof(p_deltas) IS DISTINCT FROM 'array' OR jsonb_array_length(p_deltas) = 0 THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_deltas');
  END IF;

  -- claim (idempotent replay)
  INSERT INTO public.settlement_idempotency_keys
    (table_id, hand_id, status, attempt_count, first_attempt_at, last_attempt_at)
  VALUES (p_table_id, p_hand_id, 'in_flight', 1, now(), now())
  ON CONFLICT (table_id, hand_id) DO NOTHING;
  GET DIAGNOSTICS v_claimed = ROW_COUNT;
  IF v_claimed = 0 THEN
    SELECT status, result, last_attempt_at INTO v_prior
      FROM public.settlement_idempotency_keys
     WHERE table_id = p_table_id AND hand_id = p_hand_id FOR UPDATE;
    IF v_prior.status = 'succeeded' THEN
      RETURN COALESCE(v_prior.result, '{}'::jsonb) || jsonb_build_object('replay', true);
    ELSIF v_prior.status = 'in_flight' AND v_prior.last_attempt_at > now() - interval '5 minutes' THEN
      RETURN jsonb_build_object('success', false, 'reason', 'in_flight');
    ELSE
      UPDATE public.settlement_idempotency_keys
         SET status = 'in_flight', attempt_count = attempt_count + 1, last_attempt_at = now(), error = NULL
       WHERE table_id = p_table_id AND hand_id = p_hand_id;
    END IF;
  END IF;

  -- state machine
  INSERT INTO public.ca_settlements (settlement_type, external_ref, state, table_id, hand_id,
                                     idempotency_key)
  VALUES ('hand_stacks', p_table_id::text || ':' || p_hand_id::text, 'open', p_table_id, p_hand_id,
          'hand:' || p_table_id::text || ':' || p_hand_id::text)
  ON CONFLICT (settlement_type, external_ref) DO UPDATE
    SET state = CASE WHEN public.ca_settlements.state = 'failed' THEN 'open'
                     ELSE public.ca_settlements.state END,
        error_detail = NULL
  RETURNING id INTO v_ca_id;

  BEGIN
    UPDATE public.ca_settlements SET state='locked_for_calculation' WHERE id = v_ca_id AND state='open';

    -- validation: exact scale + conservation
    FOR e IN SELECT * FROM jsonb_array_elements(p_deltas) LOOP
      v_delta := round((e->>'delta')::numeric, 2);
      IF v_delta IS DISTINCT FROM (e->>'delta')::numeric THEN
        RAISE EXCEPTION 'delta for % is not exact 2dp: %', e->>'user_id', e->>'delta';
      END IF;
      v_sum := v_sum + v_delta;
      v_n := v_n + 1;
    END LOOP;
    IF round(v_sum + COALESCE(p_rake,0) + COALESCE(p_bbj,0), 2) <> 0 THEN
      RAISE EXCEPTION 'conservation violation: deltas %.2f + rake %.2f + bbj %.2f != 0',
        v_sum, COALESCE(p_rake,0), COALESCE(p_bbj,0);
    END IF;
    UPDATE public.ca_settlements SET state='calculated',
      totals = jsonb_build_object('players', v_n, 'net_deltas', v_sum,
                                  'rake', COALESCE(p_rake,0), 'bbj', COALESCE(p_bbj,0))
      WHERE id = v_ca_id AND state='locked_for_calculation';
    UPDATE public.ca_settlements SET state='validated' WHERE id = v_ca_id AND state='calculated';

    -- apply: all seats or none, no stack below zero, seats never deleted
    FOR e IN SELECT * FROM jsonb_array_elements(p_deltas) LOOP
      v_uid := (e->>'user_id')::uuid;
      v_delta := round((e->>'delta')::numeric, 2);
      CONTINUE WHEN v_delta = 0;
      UPDATE public.table_seats ts
         SET stack = round(ts.stack + v_delta, 2)
       WHERE ts.table_id = p_table_id AND ts.user_id = v_uid AND ts.left_at IS NULL
         AND round(ts.stack + v_delta, 2) >= 0;
      GET DIAGNOSTICS v_updated = ROW_COUNT;
      IF v_updated <> 1 THEN
        RAISE EXCEPTION 'seat write failed for % (delta %): seat missing, left, or stack would go negative',
          v_uid, v_delta;
      END IF;
    END LOOP;
    UPDATE public.ca_settlements SET state='ledger_posted' WHERE id = v_ca_id AND state='validated';
    UPDATE public.ca_settlements SET state='post_commit_verified' WHERE id = v_ca_id AND state='ledger_posted';

    v_result := jsonb_build_object('success', true, 'players', v_n,
      'table_id', p_table_id, 'hand_id', p_hand_id, 'hand_number', p_hand_number,
      'rake', COALESCE(p_rake,0), 'bbj', COALESCE(p_bbj,0));

    UPDATE public.settlement_idempotency_keys
       SET status='succeeded', result=v_result, completed_at=now(), last_attempt_at=now()
     WHERE table_id = p_table_id AND hand_id = p_hand_id;
    UPDATE public.ca_settlements SET state='final' WHERE id = v_ca_id AND state='post_commit_verified';

    RETURN v_result;

  EXCEPTION WHEN OTHERS THEN
    v_err := SQLERRM;  -- every stack write above is rolled back here
    UPDATE public.settlement_idempotency_keys
       SET status='failed', error=left(v_err, 500), last_attempt_at=now()
     WHERE table_id = p_table_id AND hand_id = p_hand_id;
    UPDATE public.ca_settlements SET state='failed', error_detail=left(v_err, 2000)
     WHERE id = v_ca_id;
    IF v_err LIKE 'conservation violation%' THEN
      PERFORM public.fn_ca_raise_drift_incident(
        'fn_ca_settle_hand_stacks', 'ledger_imbalance', 'warning',
        'hand-conservation:' || p_table_id::text,
        round(v_sum + COALESCE(p_rake,0) + COALESCE(p_bbj,0), 2), 0,
        round(v_sum + COALESCE(p_rake,0) + COALESCE(p_bbj,0), 2),
        'settlement', 'table_seats', p_hand_id, NULL, NULL, p_table_id, NULL, p_hand_id,
        v_ca_id::text, NULL, NULL,
        'engine submitted a hand whose stack deltas do not conserve: ' || left(v_err, 200),
        false, jsonb_build_object('hand_id', p_hand_id, 'hand_number', p_hand_number));
    END IF;
    RETURN jsonb_build_object('success', false, 'reason', 'rolled_back', 'error', v_err,
                              'table_id', p_table_id, 'hand_id', p_hand_id);
  END;
END $$;


ALTER FUNCTION public.fn_ca_settle_hand_stacks(p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_deltas jsonb, p_rake numeric, p_bbj numeric) OWNER TO postgres;

--
-- TOC entry 7058 (class 1255 OID 20595459)
-- Name: fn_ca_settle_hand_stacks_absolute(uuid, bigint, jsonb, numeric, numeric, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_settle_hand_stacks_absolute(p_table_id uuid, p_hand_number bigint, p_stacks jsonb DEFAULT '[]'::jsonb, p_rake numeric DEFAULT NULL::numeric, p_bbj numeric DEFAULT NULL::numeric, p_ref text DEFAULT NULL::text, p_inflow numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_request jsonb;
  v_canonical jsonb;
  v_hand uuid; v_claimed integer; v_prior record; v_ca_id uuid;
  e jsonb; v_uid uuid; v_new numeric; v_old numeric; v_before numeric; v_target numeric;
  v_delta_sum numeric := 0; v_expected numeric;
  v_n integer := 0; v_updated integer; v_err text; v_result jsonb;
  v_delta_mode boolean;
  -- Exact seat identity is the row id plus the join instant. A vacated row can
  -- be reused in place, so neither user_id, chair number, nor row id is enough.
  v_exact_seat_generation boolean;
  v_exact_seat_id uuid;
  v_exact_seat_joined_at timestamptz;
  v_exact_seat_left_at timestamptz;
  v_exact_seat_club uuid;
  v_exact_seat_found boolean;
  v_retired_cash_original jsonb;
  v_targets jsonb := '{}'::jsonb;      -- user_id -> stack to write
  v_rebased jsonb := '{}'::jsonb;      -- user_id -> db_before - engine_before (delta mode only)
  v_rebase_rows jsonb := '[]'::jsonb;  -- rows for ca_seat_stack_rebases
  v_rebase_count integer := 0;
  -- 2026-09-04 (verification sweep): a seat that LEFT during the hand
  v_departed jsonb := '[]'::jsonb;   -- [{user_id, delta, club_id}]
  v_dep record; v_dep_club uuid; v_dep_after numeric; v_dep_key text; v_dep_claimed integer;
  -- chip-std Lane F (2026-09-02): tournament conservation (absolute mode)
  v_tournament_id uuid;
  -- The hand result is also the durable final-stack boundary for a tournament.
  v_tournament_status text;
  v_payload_stack_count integer := 0;
  v_target_user_count integer := 0;
  v_tournament_player_count integer := 0;
  v_tournament_player_user_ids uuid[] := ARRAY[]::uuid[];
  v_tournament_player_chips jsonb := '[]'::jsonb;
  v_zero_stack_seat_count integer := 0;
  v_zero_stack_seat_ids uuid[] := ARRAY[]::uuid[];
  v_zero_stack_user_ids uuid[] := ARRAY[]::uuid[];
  v_zero_stack_seat_generations jsonb := '[]'::jsonb;
  v_zero_stack_vacated_at timestamptz;
  v_table_live_seat_count integer := 0;
  -- ONE SEAT WRITE PER HAND (2026-09-10): the accepted time-bank state the
  -- 12-argument door publishes for this exact table+hand, carried on the
  -- stack write so each seat row is written once per hand instead of twice.
  v_tb_env_text text;
  v_tb_env jsonb;
  v_tb_map jsonb;   -- lower(user_id) -> time-bank item, or NULL (stack-only write)
  v_tb jsonb;
  -- LIGHTNING PHASE 6 (20261001154813): {player: anchor table} for the
  -- anchors a Lightning settlement in THIS transaction names, '{}' otherwise.
  v_lightning_seats jsonb := '{}'::jsonb;
BEGIN
  IF EXISTS (SELECT 1 FROM public.tables t JOIN public.clubs c ON c.id=t.club_id
             WHERE t.id=p_table_id AND c.asset='diamonds' AND t.tournament_id IS NULL) THEN
    -- DIAMOND PHASE 8: a Diamond TOURNAMENT hand moves play units on the
    -- roster and the seat, exactly as a chip tournament hand does below.
    RETURN public.fn_poker_diamond_settle_cash_hand(
      p_table_id,p_hand_number,p_stacks,p_rake,p_bbj,p_ref,p_inflow);
  END IF;
  -- This implementation primitive is owner-only by ACL below. Do not inspect
  -- current_user inside a SECURITY DEFINER core: CREATE OR REPLACE preserves
  -- the production owner, so a valid call through the sole service wrapper
  -- may execute here as that owner rather than as postgres/service_role.
  IF p_table_id IS NULL OR p_hand_number IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'missing_ids');
  END IF;
  IF jsonb_typeof(p_stacks) IS DISTINCT FROM 'array' OR jsonb_array_length(p_stacks) = 0 THEN
    RETURN jsonb_build_object('success', false, 'reason', 'no_stacks');
  END IF;


  -- One participant, one delta. Duplicates previously passed the sum check
  -- twice but wrote a single target, allowing a non-conserving final balance.
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_stacks) x
              WHERE jsonb_typeof(x) IS DISTINCT FROM 'object'
                 OR jsonb_typeof(x->'user_id') IS DISTINCT FROM 'string'
                 OR jsonb_typeof(x->'stack') IS DISTINCT FROM 'number'
                 OR (x ? 'stack_before' AND jsonb_typeof(x->'stack_before') IS DISTINCT FROM 'number')) THEN
    RAISE EXCEPTION 'Invalid hand settlement participant' USING ERRCODE = '22023';
  END IF;

  -- Rolling expansion accepts either a wholly legacy roster or a wholly exact
  -- roster. One-sided and mixed generations can otherwise create a request
  -- whose hash says one thing while individual rows are selected another way.
  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_stacks) x
     WHERE (x ? 'seat_id') IS DISTINCT FROM (x ? 'seat_joined_at')
        OR CASE WHEN x ? 'seat_id'
                THEN jsonb_typeof(x->'seat_id') IS DISTINCT FROM 'string'
                  OR jsonb_typeof(x->'seat_joined_at') IS DISTINCT FROM 'string'
                ELSE false END
        OR CASE WHEN jsonb_typeof(x->'seat_id') = 'string'
                THEN (x->>'seat_id') !~*
                  '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                ELSE false END
        OR CASE WHEN jsonb_typeof(x->'seat_joined_at') = 'string'
                THEN NOT pg_input_is_valid(
                  x->>'seat_joined_at', 'timestamp with time zone'
                )
                ELSE false END
  ) THEN
    RAISE EXCEPTION 'Invalid hand settlement seat generation'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_stacks) x WHERE x ? 'seat_id')
     AND EXISTS (SELECT 1 FROM jsonb_array_elements(p_stacks) x WHERE NOT (x ? 'seat_id')) THEN
    RAISE EXCEPTION 'Mixed legacy and exact hand settlement seat generations'
      USING ERRCODE = '22023';
  END IF;
  SELECT COALESCE(bool_and(x ? 'seat_id' AND x ? 'seat_joined_at'), false)
    INTO v_exact_seat_generation
    FROM jsonb_array_elements(p_stacks) x;

  IF (SELECT count(*) <> count(DISTINCT (x->>'user_id')::uuid) FROM jsonb_array_elements(p_stacks) x) THEN
    RAISE EXCEPTION 'Duplicate hand settlement participant' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_stacks) x WHERE x ? 'stack_before')
     AND EXISTS (SELECT 1 FROM jsonb_array_elements(p_stacks) x WHERE NOT (x ? 'stack_before')) THEN
    RAISE EXCEPTION 'Mixed absolute and delta hand settlement' USING ERRCODE = '22023';
  END IF;
  SELECT jsonb_agg(jsonb_build_object('user_id', (x->>'user_id')::uuid,
      'stack', (x->>'stack')::numeric)
      || CASE WHEN x ? 'stack_before' THEN jsonb_build_object('stack_before', (x->>'stack_before')::numeric)
              ELSE '{}'::jsonb END
      || CASE WHEN v_exact_seat_generation THEN jsonb_build_object(
              'seat_id', (x->>'seat_id')::uuid,
              'seat_joined_at', x->>'seat_joined_at')
              ELSE '{}'::jsonb END
      ORDER BY (x->>'user_id')::uuid) INTO v_canonical
    FROM jsonb_array_elements(p_stacks) x;
  v_request := jsonb_build_object('stacks', v_canonical, 'rake', p_rake,
    'bbj', p_bbj, 'inflow', p_inflow);

  /* DELTA MODE (chip standard 2026-09-04): the engine says what each stack
     WAS when it dealt and what it IS now; the database applies the difference
     to whatever the row holds. Every element must carry stack_before, or the
     whole call is absolute - a mixed payload would silently erase on the
     seats that lacked it. */
  SELECT bool_and(x ? 'stack_before' AND jsonb_typeof(x -> 'stack_before') = 'number')
    INTO v_delta_mode
    FROM jsonb_array_elements(p_stacks) x;
  v_delta_mode := COALESCE(v_delta_mode, false);
  -- LIGHTNING PHASE 6 (20261001154813): THE ONE ADAPTER. A Lightning hand is
  -- recorded at its Cluster's front table while each anchor seat sits at its
  -- own table of the Cluster. fn_lightning_settle_hand names every anchor in
  -- lightning_settlement_marker for this transaction, and only the four
  -- exact-generation seat predicates below read the answer; for every
  -- physical hand it is '{}' and each still compares to p_table_id.
  v_lightning_seats := public.fn_lightning_settlement_seats(p_table_id, p_hand_number);
  IF v_lightning_seats <> '{}'::jsonb
     AND (NOT v_exact_seat_generation OR NOT v_delta_mode
          OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_canonical) x
                      WHERE NOT (v_lightning_seats ? (x->>'user_id')))) THEN
    RAISE EXCEPTION 'Lightning hand settlement must name every anchor by its exact seat generation in delta mode'
      USING ERRCODE = '22023';
  END IF;

  -- stable hand id from (table, hand number[, ref])
  v_hand := md5('ca-hand:' || p_table_id::text || ':' || p_hand_number::text
                || CASE WHEN p_ref IS NULL OR p_ref = '' THEN '' ELSE ':' || p_ref END)::uuid;

  INSERT INTO public.settlement_idempotency_keys
    (table_id, hand_id, status, attempt_count, first_attempt_at, last_attempt_at)
  VALUES (p_table_id, v_hand, 'in_flight', 1, now(), now())
  ON CONFLICT (table_id, hand_id) DO NOTHING;
  GET DIAGNOSTICS v_claimed = ROW_COUNT;
  IF v_claimed = 0 THEN
    SELECT status, result, last_attempt_at INTO v_prior
      FROM public.settlement_idempotency_keys
     WHERE table_id = p_table_id AND hand_id = v_hand FOR UPDATE;
    IF EXISTS(SELECT 1 FROM smarter_private.horse_settlement_key_certificates c WHERE c.table_id=p_table_id AND c.stack_hand_id=v_hand) AND v_prior.status IS DISTINCT FROM 'succeeded' THEN
      RAISE EXCEPTION 'HORSE_SETTLEMENT_COMPACT_STATUS_CONFLICT' USING ERRCODE='55000';
    END IF;
    IF v_prior.status = 'succeeded' THEN
      v_prior.result:=smarter_private.horse_settlement_original_result(p_table_id,v_hand,v_prior.result);
      -- Old receipts predate payload storage. New receipts bind the full request.
      IF v_prior.result ? 'request' AND v_prior.result->'request' IS DISTINCT FROM v_request THEN
        RAISE EXCEPTION 'Hand settlement identity belongs to a different payload' USING ERRCODE = '22023';
      END IF;
      RETURN COALESCE(v_prior.result, '{}'::jsonb) || jsonb_build_object('replay', true);
    ELSIF v_prior.status = 'in_flight' AND v_prior.last_attempt_at > now() - interval '5 minutes' THEN
      RETURN jsonb_build_object('success', false, 'reason', 'in_flight');
    ELSE
      UPDATE public.settlement_idempotency_keys
         SET status = 'in_flight', attempt_count = attempt_count + 1, last_attempt_at = now(), error = NULL
       WHERE table_id = p_table_id AND hand_id = v_hand;
    END IF;
  END IF;

  INSERT INTO public.ca_settlements (settlement_type, external_ref, state, table_id, hand_id, idempotency_key)
  VALUES ('hand_stacks', p_table_id::text || ':' || v_hand::text, 'open', p_table_id, v_hand,
          'hand:' || p_table_id::text || ':' || v_hand::text)
  ON CONFLICT (settlement_type, external_ref) DO UPDATE
    SET state = CASE WHEN public.ca_settlements.state = 'failed' THEN 'open'
                     ELSE public.ca_settlements.state END,
        error_detail = NULL
  RETURNING id INTO v_ca_id;

  BEGIN
    UPDATE public.ca_settlements SET state='locked_for_calculation' WHERE id = v_ca_id AND state='open';

    -- ONE LOCK ORDER WITH TERMINAL CLOSE (20260908): tournament,
    -- target tournament players by user_id/id, then target seats by id. The
    -- terminal authority takes the same order. A hand that waited behind a
    -- terminal commit sees COMPLETED and is refused before touching a seat.
    SELECT tb.tournament_id INTO v_tournament_id
      FROM public.tables tb WHERE tb.id = p_table_id;
    IF v_tournament_id IS NOT NULL THEN
      SELECT upper(COALESCE(t.status::text,'')) INTO v_tournament_status
        FROM public.tournaments t
       WHERE t.id = v_tournament_id
       FOR SHARE;
      IF NOT FOUND OR v_tournament_status <> 'RUNNING' THEN
        RAISE EXCEPTION
          'tournament % is not RUNNING at the durable hand boundary',
          v_tournament_id USING ERRCODE = '55000';
      END IF;
      SELECT count(*),count(DISTINCT (x.value->>'user_id')::uuid)
        INTO v_payload_stack_count,v_target_user_count
        FROM jsonb_array_elements(v_canonical) AS x(value);
      IF v_target_user_count <> v_payload_stack_count THEN
        RAISE EXCEPTION 'tournament hand % contains duplicate player stacks',
          p_hand_number USING ERRCODE = '22023';
      END IF;
      PERFORM 1
        FROM public.tournament_players tp
       WHERE tp.tournament_id = v_tournament_id
         AND tp.status::text = 'playing'
         AND tp.user_id IN (
           SELECT (x.value->>'user_id')::uuid
             FROM jsonb_array_elements(v_canonical) AS x(value))
       ORDER BY tp.user_id,tp.id
       FOR UPDATE;
      SELECT count(*) INTO v_tournament_player_count
        FROM public.tournament_players tp
       WHERE tp.tournament_id = v_tournament_id
         AND tp.status::text = 'playing'
         AND tp.user_id IN (
           SELECT (x.value->>'user_id')::uuid
             FROM jsonb_array_elements(v_canonical) AS x(value));
      IF v_tournament_player_count <> v_target_user_count THEN
        RAISE EXCEPTION
          'tournament % hand % does not map every stack to one playing player',
          v_tournament_id,p_hand_number USING ERRCODE = 'P0404';
      END IF;
      -- A zero-seat vacate fires the seat-first table count trigger. Own the
      -- table before the seats, matching terminal close, so that trigger only
      -- reacquires a row this transaction already holds.
      PERFORM 1 FROM public.tables tb
       WHERE tb.id = p_table_id AND tb.tournament_id = v_tournament_id
       FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'tournament table % changed while hand % was locking',
          p_table_id,p_hand_number USING ERRCODE = '40001';
      END IF;
    END IF;

    -- Acquire every live target seat once in durable row-id order before the
    -- original loop. The loop's individual SELECT FOR UPDATE calls then
    -- reacquire locks that this transaction already owns. v_canonical is also
    -- the immutable replay identity, so lock, write and receipt use one roster.
    PERFORM 1
      FROM public.table_seats ts
      JOIN (
        SELECT DISTINCT (x.value->>'user_id')::uuid AS user_id
          FROM jsonb_array_elements(v_canonical) AS x(value)
      ) target ON target.user_id = ts.user_id
     WHERE ts.table_id = p_table_id
       AND ts.left_at IS NULL
     ORDER BY ts.id
     FOR UPDATE OF ts;

    -- lock seats, compute deltas / targets
    FOR e IN SELECT * FROM jsonb_array_elements(v_canonical) LOOP
      v_uid := (e->>'user_id')::uuid;
      v_new := round((e->>'stack')::numeric, 2);
      IF v_new IS NULL OR v_new < 0 THEN
        RAISE EXCEPTION 'invalid stack for %: %', e->>'user_id', e->>'stack';
      END IF;
      v_exact_seat_id := NULL;
      v_exact_seat_joined_at := NULL;
      v_exact_seat_left_at := NULL;
      v_exact_seat_club := NULL;
      IF v_exact_seat_generation THEN
        v_exact_seat_id := (e->>'seat_id')::uuid;
        v_exact_seat_joined_at := (e->>'seat_joined_at')::timestamptz;
        SELECT ts.stack, ts.left_at, ts.club_id
          INTO v_old, v_exact_seat_left_at, v_exact_seat_club
          FROM public.table_seats ts
         WHERE ts.id = v_exact_seat_id
           AND ts.joined_at = v_exact_seat_joined_at
           AND ts.table_id = COALESCE((v_lightning_seats->>v_uid::text)::uuid, p_table_id)
           AND ts.user_id = v_uid
         FOR UPDATE;
      ELSE
        SELECT ts.stack INTO v_old FROM public.table_seats ts
         WHERE ts.table_id = p_table_id AND ts.user_id = v_uid AND ts.left_at IS NULL
         FOR UPDATE;
      END IF;
      v_exact_seat_found := FOUND;
      IF v_exact_seat_generation AND (NOT v_exact_seat_found OR v_exact_seat_left_at IS NOT NULL) THEN
        v_retired_cash_original:=smarter_private.retired_cash_original_stack(p_table_id,p_hand_number,v_uid,
          v_exact_seat_id,v_exact_seat_joined_at,(e->>'stack_before')::numeric,v_new);
        IF v_retired_cash_original IS NOT NULL THEN
          -- A transaction-owned original obligation, not a replacement chair.
          v_exact_seat_found:=true;
          v_exact_seat_left_at:=(v_retired_cash_original->>'left_at')::timestamptz;
          v_exact_seat_club:=(v_retired_cash_original->>'funding_club_id')::uuid;
        END IF;
      END IF;
      IF NOT v_exact_seat_found
         OR (v_exact_seat_generation AND v_exact_seat_left_at IS NOT NULL) THEN
        -- If the exact row id was reused in place, joined_at no longer matches.
        -- There is no historical row left to settle, so fail the hand whole.
        IF v_exact_seat_generation AND NOT v_exact_seat_found THEN
          RAISE EXCEPTION
            'exact seat generation missing or replaced for % - hand write rejected whole',
            v_uid;
        END IF;
        /* A SEAT THAT LEFT DURING THE HAND (2026-09-04, verification sweep).
           In delta mode the player's own delta is settled against the club
           wallet the seat cashed out to, keyed on hand + user, and the players
           still seated get their deltas as usual. Refusing the whole hand here
           left the winner unpaid in the database and the leaver refunded the
           bet they had put in the pot (the exit cashes out the seat's stack
           as it stood BEFORE the hand). Measured before this: 3 cash hands in
           the first 40 minutes of delta mode, each a mid-hand leave_pending
           cash-out raced by a stale settlement step. Absolute mode still
           refuses: with no stack_before there is no delta to settle. */
        /* CASH TABLES ONLY. Tournament chips are play chips: a seat that a
           table balance moved or an elimination removed mid-hand has no
           wallet to settle against, and settling it debited 230 real chips
           from a player on 2026-09-04 13:04 (reversed in 20260904131500).
           The tournament conservation gate in the engine and the tournament
           branch below own that case; here it is refused whole, as before. */
        IF v_delta_mode AND NOT EXISTS (SELECT 1 FROM public.tables tb WHERE tb.id = p_table_id AND tb.tournament_id IS NOT NULL) THEN
          v_before := round((e->>'stack_before')::numeric, 2);
          IF v_before IS NULL OR v_before < 0 THEN
            RAISE EXCEPTION 'invalid stack_before for %: %', e->>'user_id', e->>'stack_before';
          END IF;
          IF v_exact_seat_generation THEN
            -- Use the club captured on the exact departed generation. Looking
            -- up the latest departed row can cross a later rejoin or club move.
            v_dep_club := v_exact_seat_club;
          ELSE
            SELECT ts.club_id INTO v_dep_club FROM public.table_seats ts
             WHERE ts.table_id = p_table_id AND ts.user_id = v_uid AND ts.left_at IS NOT NULL
             ORDER BY ts.left_at DESC LIMIT 1;
          END IF;
          IF v_dep_club IS NULL AND NOT v_exact_seat_generation THEN
            SELECT t.club_id INTO v_dep_club FROM public.tables t WHERE t.id = p_table_id;
          END IF;
          /* SETTLING NOTHING NEEDS NO WALLET (2026-09-08). A seat that left
             having moved no chips has nothing to settle against a wallet, and
             the departed loop below already skips a zero delta. Demanding the
             wallet first refused whole hands over seats that owed nothing -
             hand 7903456, which nets to zero between two seated players, was
             refused because a third seat with a delta of 0.00 had gone. */
          IF round(v_new - v_before, 2) = 0 THEN
            v_n := v_n + 1;
            CONTINUE;
          END IF;
          IF v_dep_club IS NULL OR NOT EXISTS (SELECT 1 FROM public.club_members m WHERE m.user_id = v_uid AND m.club_id = v_dep_club) THEN
            RAISE EXCEPTION 'seat missing or left for % and no club wallet resolves for it - hand write rejected whole', v_uid;
          END IF;
          v_delta_sum := v_delta_sum + (v_new - v_before);
          v_departed := v_departed || jsonb_build_array(
            jsonb_build_object(
              'user_id', v_uid,
              'delta', round(v_new - v_before, 2),
              'club_id', v_dep_club
            ) || CASE WHEN v_exact_seat_generation THEN jsonb_build_object(
              'seat_id', v_exact_seat_id,
              'seat_joined_at', e->>'seat_joined_at'
            ) ELSE '{}'::jsonb END
          );
          v_n := v_n + 1;
          CONTINUE;
        END IF;
        RAISE EXCEPTION 'seat missing or left for % - hand write rejected whole', v_uid;
      END IF;
      v_old := COALESCE(v_old, 0);

      IF v_delta_mode THEN
        v_before := round((e->>'stack_before')::numeric, 2);
        IF v_before IS NULL OR v_before < 0 THEN
          RAISE EXCEPTION 'invalid stack_before for %: %', e->>'user_id', e->>'stack_before';
        END IF;
        v_target := round(v_old + (v_new - v_before), 2);
        IF v_target < 0 THEN
          RAISE EXCEPTION 'negative stack for % after applying delta % to the seat''s % (engine dealt from %) - hand write rejected whole',
            v_uid, round(v_new - v_before, 2), v_old, v_before;
        END IF;
        v_delta_sum := v_delta_sum + (v_new - v_before);
        IF round(v_old - v_before, 2) <> 0 THEN
          v_rebased := v_rebased || jsonb_build_object(v_uid::text, round(v_old - v_before, 2));
          v_rebase_rows := v_rebase_rows || jsonb_build_array(jsonb_build_object(
            'user_id', v_uid, 'engine_before', v_before, 'db_before', v_old,
            'engine_after', v_new, 'written', v_target));
          v_rebase_count := v_rebase_count + 1;
        END IF;
      ELSE
        v_target := v_new;
        v_delta_sum := v_delta_sum + (v_new - v_old);
      END IF;
      v_targets := v_targets || jsonb_build_object(v_uid::text, v_target);
      v_n := v_n + 1;
    END LOOP;

    UPDATE public.ca_settlements SET state='calculated',
      totals = jsonb_build_object('players', v_n, 'net_deltas', round(v_delta_sum,2),
                                  'rake', p_rake, 'bbj', p_bbj, 'inflow', p_inflow,
                                  'mode', CASE WHEN v_delta_mode THEN 'delta' ELSE 'absolute' END,
                                  'rebased', v_rebased, 'ref', p_ref, 'departed', v_departed)
      WHERE id = v_ca_id AND state='locked_for_calculation';

    SELECT tb.tournament_id INTO v_tournament_id FROM public.tables tb WHERE tb.id = p_table_id;

    IF v_delta_mode THEN
      /* THE IDENTITY, ON THE ENGINE'S OWN ARITHMETIC: what the seats gained
         is what arrived from a declared pool, less what left as rake and
         jackpot drop. Checked on every table, cash or tournament, on every
         write. A credit that landed on the row is outside the identity by
         construction - it is in v_old, not in the delta - so it is preserved
         rather than "explained". */
      v_expected := COALESCE(p_inflow, 0) - COALESCE(p_rake, 0) - COALESCE(p_bbj, 0);
      IF round(v_delta_sum - v_expected, 2) <> 0 THEN
        RAISE EXCEPTION 'conservation violation: stack deltas % != inflow % - rake % - bbj % (table % hand %) - write refused whole',
          round(v_delta_sum, 2), COALESCE(p_inflow, 0), COALESCE(p_rake, 0), COALESCE(p_bbj, 0),
          p_table_id, p_hand_number::text || COALESCE(':' || p_ref, '');
      END IF;
    ELSE
      -- ═══ TOURNAMENT CHIPS ARE CONSERVED HAND BY HAND (chip-std Lane F, 2026-09-02) ═══
      -- Absolute mode only. A tournament table has no rake and no BBJ drop,
      -- so the named seats must sum, after this write, to exactly what they
      -- summed to before it. A paid rebuy/re-entry/add-on commits its seat and
      -- roster under the accepted-hand table lock. The dealing loop reloads
      -- those authoritative rows before admitting the next hand. Therefore a
      -- non-zero delta is stale hand input, never permission to scan payment
      -- history and reconstruct chips. Refuse the whole hand at the boundary.
      IF v_tournament_id IS NOT NULL AND round(v_delta_sum, 2) <> 0 THEN
        RAISE EXCEPTION 'conservation violation (tournament %): stale accepted-hand stacks changed the table total by % across % seat(s) of table % hand % - paid seat/roster generations must be reloaded before dealing; write refused whole',
          v_tournament_id,round(v_delta_sum,2),v_n,p_table_id,p_hand_number;
      END IF;

      -- strict conservation only when rake is declared
      IF p_rake IS NOT NULL
         AND round(v_delta_sum + p_rake + COALESCE(p_bbj, 0), 2) <> 0 THEN
        RAISE EXCEPTION 'conservation violation: stack deltas %.2f + rake %.2f + bbj %.2f != 0',
          v_delta_sum, p_rake, COALESCE(p_bbj, 0);
      END IF;
    END IF;
    UPDATE public.ca_settlements SET state='validated' WHERE id = v_ca_id AND state='calculated';

    /* ONE SEAT WRITE PER HAND (2026-09-10). fn_ca_commit_hand_settlement (the
       12-argument door) validates the hand's time-bank obligations, publishes
       them in the transaction-local setting app.ca_hand_time_banks, and only
       then calls down to this core. When that envelope names this exact table
       and hand, the stack write below also sets the two time-bank columns,
       under the same seat guards, so the seat row is written once per hand
       instead of stack-then-time-bank (two full trigger passes plus the FK
       re-checks a second write of the same row costs). The door proves the
       resulting state before it counts it and still writes any seat this core
       did not carry. Any other caller leaves the setting unset and gets the
       unchanged stack-only write. Nothing here reaches the request hash,
       the receipt or the returned result. */
    v_tb_map := NULL;
    v_tb_env_text := current_setting('app.ca_hand_time_banks', true);
    IF v_tb_env_text IS NOT NULL AND v_tb_env_text <> ''
       AND pg_input_is_valid(v_tb_env_text, 'jsonb') THEN
      v_tb_env := v_tb_env_text::jsonb;
      IF jsonb_typeof(v_tb_env) = 'object'
         AND v_tb_env->>'table_id' = p_table_id::text
         AND v_tb_env->>'hand_number' = p_hand_number::text
         AND (v_tb_env->>'exact')::boolean IS NOT DISTINCT FROM v_exact_seat_generation
         AND jsonb_typeof(v_tb_env->'items') = 'array' THEN
        -- Every item well formed and one item per player, or no fold at all.
        SELECT CASE WHEN count(*) > 0
                     AND count(*) = count(*) FILTER (WHERE x.ok)
                     AND count(*) = count(DISTINCT x.uid)
                    THEN jsonb_object_agg(x.uid, x.item) END
          INTO v_tb_map
          FROM (
            SELECT i.value AS item,
                   COALESCE(lower(i.value->>'user_id'), '') AS uid,
                   jsonb_typeof(i.value) = 'object'
                   AND (i.value->>'user_id') ~*
                     '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                   AND CASE WHEN (i.value->>'uses_remaining') ~ '^[0-9]+$'
                            THEN (i.value->>'uses_remaining')::numeric <= 2147483647
                            ELSE false END
                   AND CASE WHEN (i.value->>'seconds_remaining') ~ '^[0-9]+$'
                            THEN (i.value->>'seconds_remaining')::numeric <= 2147483647
                            ELSE false END
                   AND (NOT v_exact_seat_generation OR (
                     (i.value->>'seat_id') ~*
                       '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                     AND pg_input_is_valid(i.value->>'seat_joined_at',
                                           'timestamp with time zone'))) AS ok
              FROM jsonb_array_elements(v_tb_env->'items') i
          ) x;
      END IF;
    END IF;

    FOR e IN SELECT * FROM jsonb_array_elements(v_canonical) LOOP
      v_uid := (e->>'user_id')::uuid;
      IF NOT (v_targets ? v_uid::text) THEN
        CONTINUE;  -- a departed seat: settled against the wallet below
      END IF;
      v_target := (v_targets->>(v_uid::text))::numeric;
      -- The time-bank item for this seat, only when it names this exact
      -- seat generation. Otherwise the write is stack-only, as before.
      v_tb := CASE WHEN v_tb_map IS NOT NULL THEN v_tb_map->(v_uid::text) END;
      IF v_tb IS NOT NULL AND v_exact_seat_generation
         AND ((v_tb->>'seat_id')::uuid IS DISTINCT FROM (e->>'seat_id')::uuid
              OR (v_tb->>'seat_joined_at')::timestamptz
                   IS DISTINCT FROM (e->>'seat_joined_at')::timestamptz) THEN
        v_tb := NULL;
      END IF;
      IF v_exact_seat_generation THEN
        IF v_tb IS NOT NULL THEN
          UPDATE public.table_seats ts
             SET stack = v_target,
                 time_bank_uses_remaining = (v_tb->>'uses_remaining')::integer,
                 time_bank_remaining = (v_tb->>'seconds_remaining')::integer
           WHERE ts.id = (e->>'seat_id')::uuid
             AND ts.joined_at = (e->>'seat_joined_at')::timestamptz
             AND ts.table_id = COALESCE((v_lightning_seats->>v_uid::text)::uuid, p_table_id)
             AND ts.user_id = v_uid
             AND ts.left_at IS NULL;
        ELSE
          UPDATE public.table_seats ts SET stack = v_target
           WHERE ts.id = (e->>'seat_id')::uuid
             AND ts.joined_at = (e->>'seat_joined_at')::timestamptz
             AND ts.table_id = COALESCE((v_lightning_seats->>v_uid::text)::uuid, p_table_id)
             AND ts.user_id = v_uid
             AND ts.left_at IS NULL;
        END IF;
      ELSE
        IF v_tb IS NOT NULL THEN
          UPDATE public.table_seats ts
             SET stack = v_target,
                 time_bank_uses_remaining = (v_tb->>'uses_remaining')::integer,
                 time_bank_remaining = (v_tb->>'seconds_remaining')::integer
           WHERE ts.table_id = p_table_id AND ts.user_id = v_uid AND ts.left_at IS NULL;
        ELSE
          UPDATE public.table_seats ts SET stack = v_target
           WHERE ts.table_id = p_table_id AND ts.user_id = v_uid AND ts.left_at IS NULL;
        END IF;
      END IF;
      GET DIAGNOSTICS v_updated = ROW_COUNT;
      IF v_updated <> 1 THEN
        /* aaa_skip_noop_update returns NULL for a row that would not change,
           and ROW_COUNT then reads 0. The seat was locked and found above, so
           a zero-row update whose seat already holds the target is the trigger
           doing its job, not a failed write. Before 2026-09-04 this rejected
           8,645 hands an hour - every hand in which one player's stack did not
           move - and each of those was persisted by the engine's unchecked
           per-seat fallback instead. */
        IF NOT EXISTS (
          SELECT 1
            FROM public.table_seats ts
           WHERE ts.table_id = COALESCE((v_lightning_seats->>v_uid::text)::uuid, p_table_id)
             AND ts.user_id = v_uid
             AND ts.stack = v_target
             AND (
               (v_exact_seat_generation
                 AND ts.id = (e->>'seat_id')::uuid
                 AND ts.joined_at = (e->>'seat_joined_at')::timestamptz
                 AND ts.left_at IS NULL)
               OR (NOT v_exact_seat_generation AND ts.left_at IS NULL)
             )
        ) THEN
          RAISE EXCEPTION 'seat write failed for % - hand write rejected whole', v_uid;
        END IF;
      END IF;
    END LOOP;

    -- A successful tournament hand has one durable stack source. Mirror the
    -- exact resulting/rebased live seat targets into the matching playing
    -- tournament_players rows while both sets are still locked. Any missing,
    -- duplicate or divergent row rejects the whole hand subtransaction.
    IF v_tournament_id IS NOT NULL THEN
      UPDATE public.tournament_players tp
         SET chips = target.stack
        FROM (
          SELECT x.key::uuid AS user_id,x.value::numeric AS stack
            FROM jsonb_each_text(v_targets) AS x(key,value)
        ) target
       WHERE tp.tournament_id = v_tournament_id
         AND tp.user_id = target.user_id
         AND tp.status::text = 'playing';

      SELECT count(*),
             COALESCE(array_agg(tp.user_id ORDER BY tp.user_id),ARRAY[]::uuid[]),
             COALESCE(jsonb_agg(jsonb_build_object(
               'user_id',tp.user_id,'chips',tp.chips)
               ORDER BY tp.user_id),'[]'::jsonb)
        INTO v_tournament_player_count,v_tournament_player_user_ids,
             v_tournament_player_chips
        FROM public.tournament_players tp
        JOIN jsonb_each_text(v_targets) target
          ON target.key::uuid = tp.user_id
       WHERE tp.tournament_id = v_tournament_id
         AND tp.status::text = 'playing';
      IF v_tournament_player_count <>
           (SELECT count(*) FROM jsonb_each(v_targets))
         OR EXISTS (
           SELECT 1
             FROM jsonb_each_text(v_targets) target
            WHERE NOT EXISTS (
              SELECT 1
                FROM public.tournament_players tp
                JOIN public.table_seats ts
                  ON ts.table_id = p_table_id
                 AND ts.user_id = tp.user_id
                 AND ts.left_at IS NULL
               WHERE tp.tournament_id = v_tournament_id
                 AND tp.status::text = 'playing'
                 AND tp.user_id = target.key::uuid
                 AND tp.chips IS NOT DISTINCT FROM target.value::numeric
                 AND ts.stack IS NOT DISTINCT FROM target.value::numeric)) THEN
        RAISE EXCEPTION
          'tournament % hand % did not durably sync every final seat stack',
          v_tournament_id,p_hand_number USING ERRCODE = 'P0404';
      END IF;

      -- A named zero-stack tournament seat is finished on the felt at this
      -- same durable hand boundary. Keep tournament_players playing with
      -- chips=0 so the rebuy/elimination state machine can decide its life,
      -- but release the physical seat now. This replaces the former
      -- PostgREST vacate followed by a compensating chips-zero write.
      SELECT count(*),
             COALESCE(array_agg(ts.id ORDER BY ts.id),ARRAY[]::uuid[]),
             COALESCE(array_agg(ts.user_id ORDER BY ts.user_id),ARRAY[]::uuid[]),
             COALESCE(jsonb_agg(jsonb_build_object(
               'seat_id',ts.id,
               'user_id',ts.user_id,
               'seat_number',ts.seat_number,
               'joined_at',ts.joined_at)
               ORDER BY ts.id),'[]'::jsonb)
        INTO v_zero_stack_seat_count,v_zero_stack_seat_ids,
             v_zero_stack_user_ids,v_zero_stack_seat_generations
        FROM public.table_seats ts
        JOIN jsonb_each_text(v_targets) target
          ON target.key::uuid = ts.user_id
       WHERE ts.table_id = p_table_id
         AND ts.left_at IS NULL
         AND ts.stack = 0
         AND ts.user_id IS NOT NULL
         AND ts.joined_at IS NOT NULL
         AND target.value::numeric = 0;
      IF v_zero_stack_seat_count <>
           (SELECT count(*) FROM jsonb_each_text(v_targets) target
             WHERE target.value::numeric = 0) THEN
        RAISE EXCEPTION
          'tournament % hand % cannot identify every named zero-stack seat',
          v_tournament_id,p_hand_number USING ERRCODE = 'P0404';
      END IF;

      IF v_zero_stack_seat_count > 0 THEN
        v_zero_stack_vacated_at := clock_timestamp();
        UPDATE public.table_seats ts
           SET left_at = v_zero_stack_vacated_at,
               status = 'left',
               leave_pending = false,
               is_sitting_out = false,
               is_away = false,
               sit_out_at = NULL,
               scheduled_leave_hands = NULL
         WHERE ts.id = ANY(v_zero_stack_seat_ids)
           AND ts.table_id = p_table_id
           AND ts.left_at IS NULL
           AND ts.stack = 0;
        GET DIAGNOSTICS v_updated = ROW_COUNT;
        IF v_updated <> v_zero_stack_seat_count
           OR EXISTS (
             SELECT 1
               FROM unnest(v_zero_stack_seat_ids) expected(id)
              WHERE NOT EXISTS (
                SELECT 1 FROM public.table_seats ts
                 WHERE ts.id = expected.id
                   AND ts.table_id = p_table_id
                   AND ts.stack = 0
                   AND ts.left_at = v_zero_stack_vacated_at
                   AND ts.status = 'left'
                   AND COALESCE(ts.leave_pending,false) IS FALSE
                   AND COALESCE(ts.is_sitting_out,false) IS FALSE
                   AND COALESCE(ts.is_away,false) IS FALSE
                   AND ts.sit_out_at IS NULL
                   AND ts.scheduled_leave_hands IS NULL))
           OR EXISTS (
             SELECT 1
               FROM public.table_seats ts
               JOIN jsonb_each_text(v_targets) target
                 ON target.key::uuid = ts.user_id
              WHERE ts.table_id = p_table_id
                AND ts.left_at IS NULL
                AND target.value::numeric = 0) THEN
          RAISE EXCEPTION
            'tournament % hand % did not atomically vacate every zero-stack seat',
            v_tournament_id,p_hand_number USING ERRCODE = 'P0404';
        END IF;
      END IF;

      SELECT count(*) INTO v_table_live_seat_count
        FROM public.table_seats ts
       WHERE ts.table_id = p_table_id AND ts.left_at IS NULL;
      UPDATE public.tables tb
         SET current_players = v_table_live_seat_count,
             updated_at = now()
       WHERE tb.id = p_table_id
         AND tb.current_players IS DISTINCT FROM v_table_live_seat_count;
      IF NOT EXISTS (
        SELECT 1 FROM public.tables tb
         WHERE tb.id = p_table_id
           AND tb.tournament_id = v_tournament_id
           AND tb.current_players = v_table_live_seat_count) THEN
        RAISE EXCEPTION
          'tournament % hand % did not persist its exact live-seat count',
          v_tournament_id,p_hand_number USING ERRCODE = 'P0404';
      END IF;
    END IF;

    /* THE LEAVER STILL OWES WHAT THEY BET, AND IS STILL OWED WHAT THEY WON.
       The exit credited the seat's pre-hand stack to the club wallet, so a
       negative delta is chips the wallet holds that the pot (and now the
       winner's seat) also holds: debit the wallet, counterparty the felt.
       A positive delta is a pot they won after leaving: credit it. Keyed on
       hand + user in wallet_credit_idempotency, so a retry of this hand
       settles nothing twice. A wallet that cannot cover the debit refuses
       the whole hand, with the numbers, rather than going negative. */
    FOR v_dep IN SELECT (d->>'user_id')::uuid AS user_id, (d->>'delta')::numeric AS delta, (d->>'club_id')::uuid AS club_id
                   FROM jsonb_array_elements(v_departed) d LOOP
      IF v_dep.delta = 0 THEN CONTINUE; END IF;
      v_dep_key := 'late_seat_settle:' || v_hand::text || ':' || v_dep.user_id::text;
      INSERT INTO public.wallet_credit_idempotency (key, user_id, amount)
      VALUES (v_dep_key, v_dep.user_id, v_dep.delta)
      ON CONFLICT (key) DO NOTHING;
      GET DIAGNOSTICS v_dep_claimed = ROW_COUNT;
      IF v_dep_claimed = 0 THEN CONTINUE; END IF;  -- already settled by an earlier attempt
      PERFORM public.fn_ca_declare_ledger('settlement', 'table_stack', p_table_id, v_ca_id, v_dep_key, NULL);
      UPDATE public.club_members m
         SET chip_balance = COALESCE(m.chip_balance, 0) + v_dep.delta, updated_at = now()
       WHERE m.user_id = v_dep.user_id AND m.club_id = v_dep.club_id
         AND COALESCE(m.chip_balance, 0) + v_dep.delta >= 0
       RETURNING m.chip_balance INTO v_dep_after;
      PERFORM set_config('app.ledger_category', '', true);
      PERFORM set_config('app.ledger_counterparty', '', true);
      PERFORM set_config('app.ledger_counterparty_entity', '', true);
      PERFORM set_config('app.ledger_idempotency_key', '', true);
      IF v_dep_after IS NULL THEN
        RAISE EXCEPTION 'seat missing or left for % and its club wallet cannot cover its delta of % - hand write rejected whole', v_dep.user_id, v_dep.delta;
      END IF;
      INSERT INTO public.chip_transactions (club_id, to_user_id, amount, transaction_type, notes, table_id, balance_after, metadata)
      VALUES (v_dep.club_id, v_dep.user_id, abs(v_dep.delta),
              CASE WHEN v_dep.delta < 0 THEN 'late_seat_debit' ELSE 'late_seat_credit' END,
              CASE WHEN v_dep.delta < 0
                   THEN format('Hand #%s settled after you left the table: %s chips you had bet are taken from the club wallet the seat cashed out to', p_hand_number, abs(v_dep.delta))
                   ELSE format('Hand #%s settled after you left the table: %s chips you won are credited to your club wallet', p_hand_number, v_dep.delta) END,
              p_table_id, v_dep_after, jsonb_build_object('hand_id', v_hand, 'key', v_dep_key, 'delta', v_dep.delta));
    END LOOP;
    UPDATE public.ca_settlements SET state='ledger_posted' WHERE id = v_ca_id AND state='validated';

    IF v_rebase_count > 0 THEN
      INSERT INTO public.ca_seat_stack_rebases
        (settlement_id, table_id, hand_id, hand_number, user_id, engine_before, db_before, engine_after, written)
      SELECT v_ca_id, p_table_id, v_hand, p_hand_number,
             (r->>'user_id')::uuid, (r->>'engine_before')::numeric, (r->>'db_before')::numeric,
             (r->>'engine_after')::numeric, (r->>'written')::numeric
        FROM jsonb_array_elements(v_rebase_rows) r;
    END IF;
    UPDATE public.ca_settlements SET state='post_commit_verified' WHERE id = v_ca_id AND state='ledger_posted';

    v_result := jsonb_build_object('success', true, 'players', v_n,
      'table_id', p_table_id, 'hand_id', v_hand, 'hand_number', p_hand_number,
      'net_deltas', round(v_delta_sum, 2), 'rake', p_rake, 'bbj', p_bbj, 'inflow', p_inflow,
      'mode', CASE WHEN v_delta_mode THEN 'delta' ELSE 'absolute' END,
      'rebased', v_rebased, 'written', v_targets, 'departed', v_departed,
      'conservation_checked', v_delta_mode OR p_rake IS NOT NULL,
      'tournament_id', v_tournament_id,
      'tournament_players_synced', v_tournament_id IS NOT NULL,
      'tournament_player_count', v_tournament_player_count,
      'tournament_player_user_ids', to_jsonb(v_tournament_player_user_ids),
      'tournament_player_chips', v_tournament_player_chips,
      'tournament_zero_stack_seats_vacated', v_tournament_id IS NOT NULL,
      'tournament_zero_stack_seat_count', v_zero_stack_seat_count,
      'tournament_zero_stack_seat_ids', to_jsonb(v_zero_stack_seat_ids),
      'tournament_zero_stack_user_ids', to_jsonb(v_zero_stack_user_ids),
      'tournament_zero_stack_seat_generations', v_zero_stack_seat_generations,
      'tournament_zero_stack_vacated_at', v_zero_stack_vacated_at,
      'tournament_table_live_seat_count', v_table_live_seat_count,
      'request', v_request);

    UPDATE public.settlement_idempotency_keys
       SET status='succeeded', result=v_result, completed_at=now(), last_attempt_at=now()
     WHERE table_id = p_table_id AND hand_id = v_hand;
    UPDATE public.ca_settlements SET state='final' WHERE id = v_ca_id AND state='post_commit_verified';
    UPDATE smarter_private.retired_cash_hand_custody SET state='consumed',settlement_id=v_ca_id
     WHERE table_id=p_table_id AND hand_number=p_hand_number AND state='held' AND transaction_id=txid_current();
    RETURN v_result;

  EXCEPTION WHEN OTHERS THEN
    v_err := SQLERRM;
    UPDATE public.settlement_idempotency_keys
       SET status='failed', error=left(v_err, 500), last_attempt_at=now()
     WHERE table_id = p_table_id AND hand_id = v_hand;
    UPDATE public.ca_settlements SET state='failed', error_detail=left(v_err, 2000) WHERE id = v_ca_id;
    IF v_err LIKE 'conservation violation%' OR v_err LIKE 'negative stack%' THEN
      PERFORM public.fn_ca_raise_drift_incident(
        'fn_ca_settle_hand_stacks_absolute', 'ledger_imbalance', 'warning',
        'hand-conservation:' || p_table_id::text,
        round(v_delta_sum + COALESCE(p_rake,0) + COALESCE(p_bbj,0) - COALESCE(p_inflow,0), 2), 0,
        round(v_delta_sum + COALESCE(p_rake,0) + COALESCE(p_bbj,0) - COALESCE(p_inflow,0), 2),
        'settlement', 'table_seats', v_hand, NULL, NULL, p_table_id, NULL, v_hand,
        v_ca_id::text, NULL, NULL,
        'engine submitted a hand whose stack deltas do not conserve: ' || left(v_err, 200),
        false, jsonb_build_object('hand_number', p_hand_number, 'ref', p_ref,
                                  'mode', CASE WHEN v_delta_mode THEN 'delta' ELSE 'absolute' END));
    END IF;
    RETURN jsonb_build_object('success', false, 'reason', 'rolled_back', 'error', v_err,
                              'sqlstate', SQLSTATE,
                              'table_id', p_table_id, 'hand_number', p_hand_number, 'ref', p_ref);
  END;
END $_$;


ALTER FUNCTION public.fn_ca_settle_hand_stacks_absolute(p_table_id uuid, p_hand_number bigint, p_stacks jsonb, p_rake numeric, p_bbj numeric, p_ref text, p_inflow numeric) OWNER TO postgres;

