--
-- TOC entry 9106 (class 1255 OID 25904555)
-- Name: fn_ca_share_settlement_lane_for_table(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_share_settlement_lane_for_table(p_table_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tournament_id uuid;
BEGIN
  -- Acquire G before B and T; source custody guards also need G.
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  -- B shared: yields to terminal authorities, concurrent with every other
  -- hand and with rolling authorities of OTHER tournaments.
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('ca:hand-settlement-barrier:v1', 0));

  IF p_table_id IS NULL THEN
    RETURN;
  END IF;

  SELECT tb.tournament_id INTO v_tournament_id
  FROM public.tables tb
  WHERE tb.id = p_table_id;

  IF v_tournament_id IS NOT NULL THEN
    -- T(id) shared: yields to this tournament's own rolling authorities.
    PERFORM pg_advisory_xact_lock_shared(
      hashtextextended('ca:tournament-terminal-settlement:v1:' || v_tournament_id::text, 0));
  END IF;
END;
$$;


ALTER FUNCTION public.fn_ca_share_settlement_lane_for_table(p_table_id uuid) OWNER TO postgres;

--
-- TOC entry 46264 (class 0 OID 0)
-- Dependencies: 9106
-- Name: FUNCTION fn_ca_share_settlement_lane_for_table(p_table_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_share_settlement_lane_for_table(p_table_id uuid) IS 'Accepted hand lane: G shared, B shared, then tournament T shared before financial row locks. G is held before source-custody guards run, so a terminal authority queued for G cannot make the accepted hand refuse while waiting for its B. Rolling authorities remain concurrent across tournaments.';


