-- TOC entry 5960 (class 1255 OID 61025178)
-- Name: fn_ca_stale_certification_accounts(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_stale_certification_accounts(p_before timestamp with time zone) RETURNS TABLE(id uuid, email text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '8s'
    AS $$
 SELECT p.id, p.email::text, p.created_at
 FROM public.profiles p
 WHERE p.email LIKE 'ca-customization-cert-postdeploy-%@example.invalid'
   AND p.created_at <= LEAST(p_before, now() - interval '40 minutes')
   AND NOT public.fn_ca_certification_identity_retired(p.id)
 ORDER BY p.created_at, p.id LIMIT 21
$$;


