--
-- TOC entry 5170 (class 1255 OID 93131677)
-- Name: fn_ca_stats_workspace_report_save(text, text, text, text, jsonb, jsonb, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_stats_workspace_report_save(p_idempotency_key text, p_title text, p_source_kind text, p_source_version text, p_body jsonb DEFAULT '{}'::jsonb, p_evidence jsonb DEFAULT '[]'::jsonb, p_club_id uuid DEFAULT NULL::uuid, p_range_days integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_id uuid;
  v_request_hash text;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE = '42501'; END IF;
  v_request_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'title', trim(p_title),
    'source_kind', p_source_kind,
    'source_version', trim(p_source_version),
    'body', coalesce(p_body, '{}'::jsonb),
    'evidence', coalesce(p_evidence, '[]'::jsonb),
    'club_id', p_club_id,
    'range_days', p_range_days
  )::text, 'UTF8'), 'sha256'), 'hex');
  INSERT INTO public.ca_stats_workspace_reports
    (user_id, idempotency_key, request_hash, title, source_kind, source_version, body, evidence, club_id, range_days)
  VALUES
    (v_user, trim(p_idempotency_key), v_request_hash, trim(p_title), p_source_kind, trim(p_source_version),
     coalesce(p_body, '{}'::jsonb), coalesce(p_evidence, '[]'::jsonb), p_club_id, p_range_days)
  ON CONFLICT (user_id, idempotency_key) DO UPDATE SET
    updated_at = ca_stats_workspace_reports.updated_at
  WHERE ca_stats_workspace_reports.request_hash = EXCLUDED.request_hash
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN
    RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE = '23505';
  END IF;
  RETURN v_id;
END;
$$;


ALTER FUNCTION public.fn_ca_stats_workspace_report_save(p_idempotency_key text, p_title text, p_source_kind text, p_source_version text, p_body jsonb, p_evidence jsonb, p_club_id uuid, p_range_days integer) OWNER TO postgres;

--
-- TOC entry 4012 (class 1255 OID 93131684)
-- Name: fn_ca_stats_workspace_study_add(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_stats_workspace_study_add(p_collection_id uuid, p_hand_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_user uuid := auth.uid();
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE = '42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.ca_stats_workspace_collections WHERE id = p_collection_id AND user_id = v_user)
  THEN RAISE EXCEPTION 'collection_not_owned' USING ERRCODE = '42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.ca_hand_facts WHERE hand_id = p_hand_id AND user_id = v_user)
     AND NOT EXISTS (SELECT 1 FROM public.ca_hand_notes WHERE hand_id = p_hand_id AND user_id = v_user)
  THEN RAISE EXCEPTION 'hand_not_owned' USING ERRCODE = '42501'; END IF;
  INSERT INTO public.ca_stats_workspace_collection_hands (user_id, collection_id, hand_id)
  VALUES (v_user, p_collection_id, p_hand_id)
  ON CONFLICT (collection_id, hand_id) DO NOTHING;
  RETURN true;
END;
$$;


ALTER FUNCTION public.fn_ca_stats_workspace_study_add(p_collection_id uuid, p_hand_id uuid) OWNER TO postgres;

--
-- TOC entry 6552 (class 1255 OID 28805425)
-- Name: fn_ca_stranded_completing_tournaments(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_stranded_completing_tournaments(p_dwell_minutes integer DEFAULT 15) RETURNS TABLE(tournament_id uuid, tournament_name text, club_id uuid, completing_minutes numeric, prize_pool numeric, prize_held numeric, players integer, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT t.id, t.name, t.club_id,
         round((extract(epoch FROM (now() - COALESCE(t.ended_at, t.updated_at))) / 60.0)::numeric, 1),
         round(COALESCE(t.prize_pool, 0), 2),
         round(COALESCE((SELECT e.prize_balance FROM public.tournament_escrow e
                          WHERE e.tournament_id = t.id), 0), 2),
         t.current_players,
         'status COMPLETING for '
           || round((extract(epoch FROM (now() - COALESCE(t.ended_at, t.updated_at))) / 60.0)::numeric, 1)
           || ' minute(s) with NO row in tournament_terminal_settlements. Every one '
           || 'of 15,869 healthy settlements was written in the same transaction '
           || 'that ended the event (settled_at - ended_at = 0.00s at p50, p95, p99 '
           || 'and max), so this event is not slow, it is refused - and the '
           || round(COALESCE((SELECT e.prize_balance FROM public.tournament_escrow e
                              WHERE e.tournament_id = t.id), 0), 2)
           || ' chips in its escrow are paid to nobody until somebody looks. This '
           || 'is the Breakfast Turbo shape, refused for three days with no alert'
    FROM public.tournaments t
   WHERE t.status = 'COMPLETING'
     AND COALESCE(t.ended_at, t.updated_at)
           < now() - make_interval(mins => GREATEST(p_dwell_minutes, 1))
     AND NOT EXISTS (SELECT 1 FROM public.tournament_terminal_settlements s
                      WHERE s.tournament_id = t.id)
   ORDER BY 4 DESC
$$;


ALTER FUNCTION public.fn_ca_stranded_completing_tournaments(p_dwell_minutes integer) OWNER TO postgres;

--
-- TOC entry 46279 (class 0 OID 0)
-- Dependencies: 6552
-- Name: FUNCTION fn_ca_stranded_completing_tournaments(p_dwell_minutes integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_stranded_completing_tournaments(p_dwell_minutes integer) IS 'A tournament stuck in COMPLETING with no tournament_terminal_settlements row. Measured healthy dwell in COMPLETING is 0.00s across 15,869 settlements (settled_at = completed_at = ended_at in every one), so any visible COMPLETING row has already committed without its settlement. Breakfast Turbo c1f15c30 sat here for three days with a 180.00 prize pool and raised no alert.';


