--
-- TOC entry 8864 (class 1255 OID 26587221)
-- Name: fn_ca_tournament_deal_review_result(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_deal_review_result(p_tournament_id uuid, p_actor_id uuid, p_review_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r public.tournament_deal_reviews%ROWTYPE; v_state text;
BEGIN
  SELECT * INTO r FROM public.tournament_deal_reviews
    WHERE tournament_id=p_tournament_id AND (p_review_id IS NULL OR id=p_review_id)
    ORDER BY requested_at DESC,id DESC LIMIT 1;
  v_state:=CASE WHEN r.id IS NULL THEN 'none'
    WHEN r.state IN ('requested','reviewing') AND r.expires_at<=clock_timestamp() THEN 'expired'
    ELSE r.state END;
  RETURN jsonb_build_object('ok',true,'actor_id',p_actor_id,'tournament_id',p_tournament_id,
    'review_id',r.id,'state',v_state,'expires_at',r.expires_at,
    'proposal_id',CASE WHEN v_state='reviewing' THEN r.proposal_id ELSE NULL END,
    'revision',CASE WHEN v_state='reviewing' THEN r.revision ELSE NULL END);
END;
$$;


ALTER FUNCTION public.fn_ca_tournament_deal_review_result(p_tournament_id uuid, p_actor_id uuid, p_review_id uuid) OWNER TO postgres;

--
-- TOC entry 5499 (class 1255 OID 26587203)
-- Name: fn_ca_tournament_deal_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_deal_snapshot(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
  t public.tournaments%ROWTYPE;
  v_live integer; v_field integer; v_chips numeric; v_max_place integer;
  v_pool bigint; v_fixed bigint; v_bubble bigint:=0; v_deal bigint;
  v_assigned bigint; v_shares jsonb; v_ladder jsonb; v_roster jsonb;
  v_seats jsonb; v_hands jsonb; v_paid jsonb; v_snapshot jsonb; v_review_id uuid;
BEGIN
  PERFORM public.fn_ca_lock_settlement_lane_global();
  SELECT * INTO t FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE;
  IF NOT FOUND OR t.status::text<>'RUNNING' OR t.final_table_deal_enabled IS NOT TRUE
     OR lower(COALESCE(t.variant::text,''))='satellite'
     OR upper(COALESCE(t.tournament_type::text,''))='SATELLITE'
     OR t.satellite_target_id IS NOT NULL OR t.satellite_target IS NOT NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','deal_not_ready');
  END IF;
  SELECT id INTO v_review_id FROM public.tournament_deal_reviews WHERE tournament_id=p_tournament_id
    AND state IN ('requested','reviewing') AND manager_lease_generation IS NOT NULL AND expires_at>clock_timestamp();
  IF v_review_id IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','review_not_ready'); END IF;
  IF t.prize_pool_finalized IS NOT TRUE OR t.prize_pool IS NULL
     OR t.prize_pool::text IN ('NaN','Infinity','-Infinity')
     OR t.prize_pool<=0 OR t.prize_pool<>round(t.prize_pool,2)
     OR t.guaranteed_prize::text IN ('NaN','Infinity','-Infinity')
     OR t.prize_pool<COALESCE(t.guaranteed_prize,0) THEN
    RETURN jsonb_build_object('ok',false,'reason','pool_not_finalized');
  END IF;
  PERFORM 1 FROM public.tournament_players WHERE tournament_id=p_tournament_id ORDER BY id FOR UPDATE;
  SELECT count(*),count(*) FILTER(WHERE status::text='playing' AND eliminated_at IS NULL),
    COALESCE(sum(chips) FILTER(WHERE status::text='playing' AND eliminated_at IS NULL),0)
    INTO v_field,v_live,v_chips FROM public.tournament_players WHERE tournament_id=p_tournament_id;
  IF v_live<2 OR v_live>COALESCE(t.table_size,0) OR t.table_size NOT BETWEEN 2 AND 10
     OR v_chips<=0 OR v_chips::text IN ('NaN','Infinity','-Infinity')
     OR EXISTS(SELECT 1 FROM public.tournament_players WHERE tournament_id=p_tournament_id
       AND status::text='playing' AND eliminated_at IS NULL
       AND (chips IS NULL OR chips<=0 OR chips::text IN ('NaN','Infinity','-Infinity'))) THEN
    RETURN jsonb_build_object('ok',false,'reason','deal_not_ready');
  END IF;
  IF EXISTS(SELECT 1 FROM public.tournament_players WHERE tournament_id=p_tournament_id AND
      ((status::text='playing' AND eliminated_at IS NULL AND (position IS NOT NULL OR elimination_sequence IS NOT NULL))
       OR (NOT(status::text='playing' AND eliminated_at IS NULL)
          AND(status::text<>'eliminated' OR eliminated_at IS NULL OR elimination_sequence IS NULL OR elimination_sequence<=0))))
     OR (SELECT count(DISTINCT elimination_sequence) FROM public.tournament_players
          WHERE tournament_id=p_tournament_id AND status::text='eliminated')<>v_field-v_live THEN
    RETURN jsonb_build_object('ok',false,'reason','standing_evidence_invalid');
  END IF;
  PERFORM 1 FROM public.tables WHERE tournament_id=p_tournament_id ORDER BY id FOR SHARE;
  PERFORM 1 FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
    WHERE tb.tournament_id=p_tournament_id ORDER BY s.id FOR SHARE OF s;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('seat_id',s.id,'table_id',s.table_id,
    'user_id',s.user_id,'seat_number',s.seat_number,'joined_at',s.joined_at,
    'stack',s.stack::text) ORDER BY s.id),'[]'::jsonb)
    INTO v_seats FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
    WHERE tb.tournament_id=p_tournament_id AND lower(tb.status::text) IN ('running','waiting')
      AND s.left_at IS NULL AND s.user_id IS NOT NULL;
  IF jsonb_array_length(v_seats)<>v_live
     OR (SELECT count(DISTINCT x->>'table_id') FROM jsonb_array_elements(v_seats)x)<>1
     OR (SELECT count(DISTINCT x->>'user_id') FROM jsonb_array_elements(v_seats)x)<>v_live
     OR EXISTS(SELECT 1 FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament_id
       AND tp.status::text='playing' AND tp.eliminated_at IS NULL
       AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_seats)x
         WHERE x->>'user_id'=tp.user_id::text AND (x->>'stack')::numeric=tp.chips)) THEN
    RETURN jsonb_build_object('ok',false,'reason','seat_snapshot_invalid');
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('place',a.place,'cents',round(a.amount*100)::bigint)
    ORDER BY a.place),'[]'::jsonb),max(a.place)
    INTO v_ladder,v_max_place FROM public.fn_ca_tournament_place_amounts(p_tournament_id)a;
  IF v_max_place IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','payout_plan_invalid'); END IF;
  SELECT COALESCE(sum((x->>'cents')::bigint),0)
    INTO v_fixed FROM jsonb_array_elements(v_ladder)x WHERE (x->>'place')::integer>v_live;
  IF COALESCE(t.bubble_protection,false) AND v_field>v_max_place AND v_max_place+1>v_live THEN
    IF t.buy_in_amount IS NULL OR t.buy_in_amount<=0 OR t.buy_in_amount<>round(t.buy_in_amount,2)
       OR t.buy_in_amount::text IN ('NaN','Infinity','-Infinity') THEN
      RETURN jsonb_build_object('ok',false,'reason','payout_plan_invalid');
    END IF;
    v_bubble:=round(t.buy_in_amount*100)::bigint;
  END IF;
  v_pool:=round(t.prize_pool*100)::bigint; v_deal:=v_pool-v_fixed-v_bubble;
  IF v_deal<=0 THEN RETURN jsonb_build_object('ok',false,'reason','payout_plan_invalid'); END IF;
  WITH ranked AS (
    SELECT user_id,chips,registered_at,row_number() OVER
      (ORDER BY chips DESC,registered_at ASC NULLS LAST,user_id ASC)::integer AS place
      FROM public.tournament_players WHERE tournament_id=p_tournament_id
        AND status::text='playing' AND eliminated_at IS NULL
  ), priced AS (
    SELECT *,floor(chips::numeric*v_deal::numeric/v_chips)::bigint AS cents FROM ranked
  )
  SELECT jsonb_agg(jsonb_build_object('user_id',user_id,'place',place,
    'chips',chips::text,'amount_cents',cents::text) ORDER BY place),sum(cents)
    INTO v_shares,v_assigned FROM priced;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_shares)x WHERE (x->>'amount_cents')::bigint<=0) THEN
    RETURN jsonb_build_object('ok',false,'reason','payout_plan_invalid');
  END IF;
  v_shares:=jsonb_set(v_shares,'{0,amount_cents}',
    to_jsonb(((v_shares->0->>'amount_cents')::bigint+v_deal-v_assigned)::text));
  SELECT jsonb_agg(jsonb_build_object('id',tp.id,'user_id',tp.user_id,'chips',tp.chips::text,
    'registered_at',tp.registered_at,'live',tp.status::text='playing' AND tp.eliminated_at IS NULL,
    'elimination_sequence',tp.elimination_sequence) ORDER BY tp.id)
    INTO v_roster FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament_id;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('table_id',q.table_id,'hand_number',q.hand_number::text)
    ORDER BY q.table_id),'[]'::jsonb) INTO v_hands
    FROM(SELECT h.table_id,max(h.hand_number)hand_number FROM public.hand_atomic_commits h
      JOIN public.tables tb ON tb.id=h.table_id WHERE tb.tournament_id=p_tournament_id GROUP BY h.table_id)q;
  SELECT COALESCE(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]'::jsonb) INTO v_paid
    FROM public.tournament_payouts p WHERE p.tournament_id=p_tournament_id AND p.source<>'final_table_deal';
  v_snapshot:=jsonb_build_object('tournament_id',p_tournament_id,'review_id',v_review_id,
    'club_id',t.club_id,'union_id',t.union_id,'is_private',t.is_private,'pool_cents',v_pool::text,
    'fixed_cents',v_fixed::text,'bubble_cents',v_bubble::text,'deal_cents',v_deal::text,
    'shares',v_shares,'ladder',v_ladder,'roster',v_roster,'seats',v_seats,'hands',v_hands,
    'paid',v_paid,'payout_structure',to_jsonb(t)->'payout_structure',
    'guaranteed_prize',t.guaranteed_prize::text,'bubble_protection',t.bubble_protection,
    'buy_in_amount',t.buy_in_amount::text,'table_size',t.table_size);
  RETURN jsonb_build_object('ok',true,'snapshot',v_snapshot,
    'revision',encode(digest(convert_to(v_snapshot::text,'UTF8'),'sha256'),'hex'));
END;
$$;


ALTER FUNCTION public.fn_ca_tournament_deal_snapshot(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 5147 (class 1255 OID 18519922)
-- Name: fn_ca_tournament_entry_gate(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_entry_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tclub uuid;
BEGIN
  -- Maintenance escape for deliberate service operations.
  IF current_setting('app.ca_entry_gate_skip', true) = '1' THEN
    RETURN NEW;
  END IF;
  SELECT t.club_id INTO v_tclub FROM public.tournaments t WHERE t.id = NEW.tournament_id;
  IF v_tclub IS NULL THEN
    RETURN NEW; -- clubless tournament: nothing to scope against
  END IF;
  IF NOT public.fn_ca_entry_scope_ok(NEW.user_id, v_tclub) THEN
    RAISE EXCEPTION 'tournament entry refused: player % has no club membership in the scope of tournament % (club/union %). Join a club in this union first.',
      NEW.user_id, NEW.tournament_id, v_tclub
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_ca_tournament_entry_gate() OWNER TO postgres;

--
-- TOC entry 6704 (class 1255 OID 30845000)
-- Name: fn_ca_tournament_escrow(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_escrow(p_tournament_id uuid) RETURNS TABLE(prize_in numeric, bounty_in numeric, fee_in numeric, overlay_in numeric, satellite_in numeric, prize_out numeric, bounty_out numeric, fee_out numeric, refund_out numeric, prize_balance numeric, bounty_balance numeric, fee_balance numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- DIAMOND PHASE 9: the chip shadow convention - prize_balance without a
  -- Spin's reserve legs, which the escrow row carries as reserve_in and
  -- reserve_out and fn_ca_escrow_balance_drift adds back.
  SELECT e.prize_in, e.bounty_in, e.fee_in, e.overlay_in, e.satellite_in, e.prize_out, e.bounty_out,
         e.fee_out, e.refund_out, e.prize_balance - r.spin_underwrite + r.spin_surplus,
         e.bounty_balance, e.fee_balance
    FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id) e
   CROSS JOIN LATERAL (
     SELECT COALESCE(sum(l.amount) FILTER (WHERE l.kind = 'spin_underwrite'), 0)::numeric AS spin_underwrite,
            COALESCE(sum(l.amount) FILTER (WHERE l.kind = 'spin_surplus'), 0)::numeric AS spin_surplus
       FROM public.poker_diamond_tournament_ledger l WHERE l.tournament_id = p_tournament_id) r
   WHERE public.fn_poker_diamond_tournament(p_tournament_id)
  UNION ALL
  SELECT * FROM public.fn_ca_tournament_escrow_chips(p_tournament_id)
   WHERE NOT public.fn_poker_diamond_tournament(p_tournament_id);
$$;


ALTER FUNCTION public.fn_ca_tournament_escrow(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 7284 (class 1255 OID 18998549)
-- Name: fn_ca_tournament_escrow_chips(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_escrow_chips(p_tournament_id uuid) RETURNS TABLE(prize_in numeric, bounty_in numeric, fee_in numeric, overlay_in numeric, satellite_in numeric, prize_out numeric, bounty_out numeric, fee_out numeric, refund_out numeric, prize_balance numeric, bounty_balance numeric, fee_balance numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH t AS (
  SELECT id,COALESCE(buy_in_amount,0) AS buy_in_amount,
         COALESCE(buy_in_fee,0) AS buy_in_fee,
         COALESCE(bounty_amount,0) AS bounty_amount,
         (COALESCE(is_bounty,false) OR COALESCE(is_pko,false)
          OR COALESCE(is_mystery_bounty,false)) AS is_b
    FROM public.tournaments WHERE id=p_tournament_id
), w AS (
  SELECT
    COALESCE(sum(amount) FILTER (WHERE type='debit'
      AND category IN ('tournament_buyin','rebuy','addon')),0) AS gross_in,
    COALESCE(sum(amount) FILTER (WHERE type='credit' AND category='prize'),0)
      - COALESCE(sum(amount) FILTER (WHERE type='debit'
          AND category IN ('prize','prize_reversal')),0) AS prize_out,
    COALESCE(sum(amount) FILTER (WHERE type='credit' AND category='bounty'),0)
      AS bounty_out,
    COALESCE(sum(amount) FILTER (WHERE type='credit'
      AND category IN ('refund','tournament_refund')),0) AS refund_out
  FROM public.wallet_transactions WHERE related_entity_id=p_tournament_id
), direct_bounty AS (
  SELECT round(COALESCE(sum(CASE
    WHEN NOT t.is_b OR lower(l.category)='addon' THEN 0
    WHEN lower(l.category)='tournament_buyin' THEN round(t.bounty_amount,2)
    ELSE public.fn_ca_unit_floor_cents(
      round(LEAST(
        GREATEST(0,round(t.bounty_amount,2)),
        round(l.amount,2)-public.fn_ca_recovery_fee_cents(
          round(round(l.amount,2)*100)::bigint,
          public.fn_ca_tournament_fee_ratio(t.buy_in_amount,t.buy_in_fee),
          public.fn_ca_tournament_unit_cents(p_tournament_id))::numeric/100
      )*100)::bigint,
      public.fn_ca_tournament_unit_cents(p_tournament_id))::numeric/100    END),0),2) AS amount
  FROM t JOIN public.chip_ledger l
    ON l.tournament_id=p_tournament_id
   AND l.from_type='player_wallet' AND l.to_type='prize_liability'
   AND l.to_entity_id=p_tournament_id
   AND lower(l.category) IN ('tournament_buyin','rebuy','addon')
), rr AS (
  SELECT
    COALESCE(sum(rake_amount),0) AS fee_in,
    COALESCE(sum(rake_amount) FILTER (
      WHERE source='fn_award_satellite_seat'),0) AS fee_sat,
    COALESCE(sum(rake_amount) FILTER (
      WHERE source='fn_award_satellite_seat'
        AND metadata->>'entry_split_version'='2'),0) AS fee_sat_split,
    COALESCE(sum(COALESCE(pot_size,0)-rake_amount) FILTER (
      WHERE source='fn_award_satellite_seat'),0) AS satellite_in
  FROM public.rake_records
  WHERE tournament_id=p_tournament_id AND is_tournament
    AND NOT (rake_amount<0 AND source IN (
      'atomic_cancel_tournament','fn_unregister_from_tournament'))
), ov AS (
  /* A REVIEWED VOID RETURNS ITS OVERLAY (2026-09-27). The void of a retired
     event (smarter_private.f06_void_retired_mixed_custody_event) sends the
     guarantee overlay back to its funder as one 'reversal' leg out of
     prize_liability, and takes it out of the maintained escrow. The shadow
     nets it too, or it reads the returned overlay as money still in the pool. */
  SELECT COALESCE(sum(a.amount),0) AS ledger_overlay,
         (SELECT COALESCE(sum(r.amount),0) FROM public.chip_ledger r
     WHERE r.tournament_id=p_tournament_id AND r.category='reversal'
       AND r.from_type='prize_liability' AND r.from_entity_id=p_tournament_id
       AND r.metadata->>'kind'='reviewed_void_overlay_return') AS returned
    FROM public.chip_ledger a
   WHERE a.to_entity_id=p_tournament_id
     AND a.to_type='prize_liability'
     AND (a.category='overlay' OR
       (a.category='correction' AND a.from_type IN ('union_bank','club_treasury')))
     AND NOT (COALESCE(a.description,'') LIKE 'auto-ledgered%'
       AND EXISTS (
         SELECT 1 FROM public.chip_ledger b
          WHERE b.to_entity_id=a.to_entity_id AND b.category='overlay'
            AND b.to_type='prize_liability' AND b.id<>a.id
            AND b.amount=a.amount
            AND COALESCE(b.description,'') NOT LIKE 'auto-ledgered%'
            AND abs(extract(epoch FROM (b.created_at-a.created_at)))<5))
), stl AS (
  SELECT COALESCE(sum(amount),0) AS moved,
    COALESCE(sum(amount) FILTER (
      WHERE metadata->>'entry_split_version'='2'),0) AS split_moved,
    COALESCE(sum((metadata->>'entry_fee')::numeric) FILTER (
      WHERE metadata->>'entry_split_version'='2'),0) AS split_fee,
    COALESCE(sum((metadata->>'entry_bounty')::numeric) FILTER (
      WHERE metadata->>'entry_split_version'='2'),0) AS split_bounty
  FROM public.chip_ledger
  WHERE to_entity_id=p_tournament_id AND to_type='prize_liability'
    AND idempotency_key LIKE 'tourney:%:seat:%:pool_transfer'
), tk AS (
  /* A TICKET ENTRY IS AN ENTRY (2026-09-10): a tournament-entry ticket
     redeemed into this event moves its value escrow -> prize_liability
     with no wallet debit and no pool transfer; the escrow triggers count
     it as an entry and so must the shadow. */
  SELECT COALESCE(sum(amount),0) AS ticket_in,
         COALESCE(sum((metadata->>'entry_bounty')::numeric),0) AS ticket_bounty
    FROM public.chip_ledger
   WHERE to_entity_id=p_tournament_id AND to_type='prize_liability'
     AND from_type='escrow' AND category='ticket_redeem'
), tgo AS (
  SELECT COALESCE(sum(amount),0) AS tgo_amount
    FROM public.tournament_guarantee_overlays
   WHERE tournament_id=p_tournament_id
), sat AS (
  SELECT COALESCE(sum(p.amount),0) AS funded_awards_out
    FROM public.tournament_payouts p
    LEFT JOIN public.tournament_satellite_awards a
      ON a.payout_id=p.id
     AND a.tournament_id=p.tournament_id
     AND a.delivery_kind='ticket'
   WHERE p.tournament_id=p_tournament_id
     AND (p.source='satellite_seat'
       OR (p.source='satellite_ticket' AND a.payout_id IS NOT NULL))
), fo AS (
  SELECT COALESCE(sum(amount),0) AS fee_out
    FROM public.tournament_rake_settlements
   WHERE tournament_id=p_tournament_id AND settled_at IS NOT NULL
), exact_refunds AS (
  SELECT COALESCE(sum(amount_paid_now),0) AS total,
         COALESCE(sum(refund_prize),0) AS prize,
         COALESCE(sum(refund_bounty),0) AS bounty,
         COALESCE(sum(refund_fee),0) AS fee
    FROM public.tournament_refund_tranches
   WHERE tournament_id=p_tournament_id
), calc AS (
  SELECT
    round(w.gross_in+stl.split_moved-stl.split_fee+tk.ticket_in,2) AS gross_in,
    round(rr.fee_in,2) AS fee_in,
    round(rr.fee_in-rr.fee_sat,2) AS fee_entries,
    round(direct_bounty.amount+stl.split_bounty+tk.ticket_bounty,2) AS bounty_in,
    round(CASE WHEN ov.ledger_overlay>0 THEN ov.ledger_overlay
      ELSE tgo.tgo_amount END-ov.returned,2) AS overlay_in,
    round(stl.moved-stl.split_moved-rr.fee_sat+rr.fee_sat_split,2)
      AS satellite_in,
    round(w.prize_out+sat.funded_awards_out,2) AS prize_out,
    round(w.bounty_out,2) AS bounty_out,
    round(fo.fee_out,2) AS fee_out,
    round(w.refund_out,2) AS refund_out,
    round(exact_refunds.total,2) AS exact_total,
    round(exact_refunds.prize,2) AS exact_prize,
    round(exact_refunds.bounty,2) AS exact_bounty,
    round(exact_refunds.fee,2) AS exact_fee
  FROM t,w,direct_bounty,rr,stl,ov,tk,tgo,sat,fo,exact_refunds
), split AS (
  SELECT c.*,round(c.gross_in-c.fee_entries-c.bounty_in,2) AS prize_in,
         round(c.refund_out-c.exact_total,2) AS legacy_refund
    FROM calc c
), apportioned AS (
  SELECT s.*,
    CASE WHEN (s.prize_in+s.satellite_in+s.bounty_in+s.fee_in)>0
      THEN round(s.legacy_refund*(s.prize_in+s.satellite_in)
        /(s.prize_in+s.satellite_in+s.bounty_in+s.fee_in),2)
      ELSE s.legacy_refund END AS legacy_prize,
    CASE WHEN (s.prize_in+s.satellite_in+s.bounty_in+s.fee_in)>0
      THEN round(s.legacy_refund*s.bounty_in
        /(s.prize_in+s.satellite_in+s.bounty_in+s.fee_in),2)
      ELSE 0 END AS legacy_bounty
  FROM split s
)
SELECT a.prize_in,a.bounty_in,a.fee_in,a.overlay_in,a.satellite_in,
       a.prize_out,a.bounty_out,a.fee_out,a.refund_out,
       round(a.prize_in+a.overlay_in+a.satellite_in-a.prize_out
         -a.legacy_prize-a.exact_prize,2) AS prize_balance,
       round(a.bounty_in-a.bounty_out-a.legacy_bounty-a.exact_bounty,2)
         AS bounty_balance,
       round(a.fee_in-a.fee_out
         -(a.legacy_refund-a.legacy_prize-a.legacy_bounty)-a.exact_fee,2)
         AS fee_balance
  FROM apportioned a;
$$;


