-- Name: fn_ca_tournament_purchase_fee_ratio(numeric, numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_purchase_fee_ratio(p_buy_in numeric, p_buy_in_fee numeric, p_unit_cents integer) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT CASE WHEN p_unit_cents=100 AND p_buy_in=0 AND p_buy_in_fee=0 THEN 0
 ELSE public.fn_ca_tournament_fee_ratio(p_buy_in,p_buy_in_fee) END;
$$;


