--
-- TOC entry 7747 (class 1255 OID 151097581)
-- Name: fn_ca_tournament_schedule_chat_default(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_schedule_chat_default() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  -- TOURNAMENT CHAT IS OFF BY DEFAULT (2026-10-11). The spawner writes
  -- ban_chat = asBool(config.banChat), so an MTT-family config that does not
  -- say is given banChat true here. A Spin or a Sit N Go config, and any
  -- config that says (true or false), is left exactly as written.
  IF jsonb_typeof(NEW.config) = 'object'
     AND COALESCE(NEW.config -> 'banChat', 'null'::jsonb) = 'null'::jsonb
     AND NOT public.fn_ca_schedule_config_keeps_chat(NEW.config) THEN
    NEW.config := jsonb_set(NEW.config, '{banChat}', 'true'::jsonb, true);
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_ca_tournament_schedule_chat_default() OWNER TO postgres;

--
-- TOC entry 7487 (class 1255 OID 25678441)
-- Name: fn_ca_tournament_seat_cap(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_tournament_seat_cap(p_tournament_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_variant text;
  v_format text;
  v_cap integer;
BEGIN
  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tournament not found' USING ERRCODE='P0002';
  END IF;
  v_variant:=lower(COALESCE(NULLIF(v_t.game_type,''),'nlh'));
  v_format:=public.fn_ca_tournament_recorded_format(p_tournament_id);
  v_cap:=CASE
    WHEN v_format='spin-v1'
      THEN 3
    WHEN v_format='seat-first-satellite-v1' THEN 2
    WHEN v_format='sng-v1'
      THEN LEAST(COALESCE(NULLIF(v_t.max_players,0),6),9)
    ELSE LEAST(COALESCE(NULLIF(v_t.table_size,0),9),10)
  END;
  v_cap:=LEAST(v_cap,CASE v_variant
    WHEN 'plo5' THEN 9
    WHEN 'plo6' THEN 7
    ELSE 10
  END);
  RETURN GREATEST(v_cap,2);
END;
$$;


ALTER FUNCTION public.fn_ca_tournament_seat_cap(p_tournament_id uuid) OWNER TO postgres;

