--
-- TOC entry 9280 (class 1255 OID 25444216)
-- Name: fn_ca_undeclared_leg_check(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_undeclared_leg_check(p_hours integer DEFAULT 24) RETURNS TABLE(account text, entity_id uuid, net_chips numeric, legs bigint, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH win AS (
    SELECT from_type, from_entity_id, to_type, to_entity_id, amount, from_label, to_label
      FROM public.chip_ledger
     WHERE created_at >= now() - make_interval(hours => GREATEST(COALESCE(p_hours, 24), 1))
       AND 'settlement_suspense' IN (from_type, to_type)
       -- a correction posted through fn_ca_post_correction IS the name
       AND NOT (category = 'correction'
                AND metadata ->> 'posted_via' = 'fn_ca_post_correction')
  ), sides AS (
    SELECT to_type AS account, to_entity_id AS entity_id, amount AS delta,
           COALESCE(from_label, to_label) AS src
      FROM win WHERE to_type <> 'settlement_suspense'
    UNION ALL
    SELECT from_type, from_entity_id, -amount, COALESCE(from_label, to_label)
      FROM win WHERE from_type <> 'settlement_suspense'
  )
  SELECT s.account, s.entity_id,
         round(sum(s.delta), 2) AS net_chips,
         count(*) AS legs,
         'chips reached this account through settlement_suspense and were never given a name: '
           || round(sum(s.delta), 2) || ' over ' || count(*) || ' leg(s)'
           || COALESCE(', written by ' || max(s.src), '')
           || '. A balance write declares its counterparty with fn_ca_declare_ledger, or '
           || 'stands its trigger down with app.ledger_autoskip_<table> when the caller '
           || 'writes the named leg itself.' AS detail
    FROM sides s
   GROUP BY 1, 2
  HAVING round(sum(s.delta), 2) <> 0
   ORDER BY abs(round(sum(s.delta), 2)) DESC
$$;


ALTER FUNCTION public.fn_ca_undeclared_leg_check(p_hours integer) OWNER TO postgres;

--
-- TOC entry 5551 (class 1255 OID 18558265)
-- Name: fn_ca_undeclared_money_paths(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_undeclared_money_paths() RETURNS TABLE(proname text, tbl text, col text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH watched AS (
    SELECT c.relname::text AS tbl,
           (regexp_matches(pg_get_triggerdef(t.oid), '''([a-z_]+)=([a-z_]+)''', 'g'))[1] AS col
      FROM pg_trigger t
      JOIN pg_class c ON c.oid = t.tgrelid
      JOIN pg_proc  p ON p.oid = t.tgfoid
     -- IN (...), not '=': a migration that reads pg_get_functiondef and holds
     -- an EXECUTE must not read as redefining the journal trigger it names
     -- (tests/a-declared-guard-change-is-recorded-not-raised.law.test.ts).
     WHERE NOT t.tgisinternal AND p.proname IN ('fn_ca_autoledger')
  ), fns AS (
    SELECT p.proname::text AS proname, p.prosrc,
           (p.prosrc ILIKE '%fn_ca_declare_ledger%'
            OR p.prosrc ILIKE '%app.ledger_counterparty%') AS declares,
           (p.prosrc ~* 'INSERT\s+INTO\s+(public\.)?chip_ledger\y') AS writes_own_leg
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public' AND p.prokind = 'f'
  )
  SELECT DISTINCT f.proname, w.tbl, w.col
    FROM fns f
    JOIN watched w
      -- statement-scoped: the column is ASSIGNED by an UPDATE of the table
      ON f.prosrc ~* ('UPDATE\s+(public\.)?' || w.tbl || '\y[^;]*?\ySET\y[^;]*?\y' || w.col || '\s*=')
   WHERE NOT f.declares
     -- the second contract: the table's journal stood down, the door's own leg written
     AND NOT (f.writes_own_leg AND f.prosrc ~* ('ledger_autoskip_' || w.tbl || '\y'))
     AND f.proname NOT IN ('fn_ca_autoledger', 'fn_ca_autoledger_delete',
                           'fn_ca_declare_ledger', 'fn_ca_undeclared_money_paths')
     -- 2026-09-12: a function AUDITED AS MOVING NO MONEY is not an undeclared
     -- money path. status='system' IS that audit, written into
     -- ca_money_rpc_registry by the ab_ca_money_rpc_registered event trigger
     -- before the function is allowed to exist.
     AND NOT EXISTS (SELECT 1 FROM public.ca_money_rpc_registry g
                      WHERE g.proname = f.proname AND g.status = 'system')
   ORDER BY 1, 2, 3
$$;


ALTER FUNCTION public.fn_ca_undeclared_money_paths() OWNER TO postgres;

--
-- TOC entry 46360 (class 0 OID 0)
-- Dependencies: 5551
-- Name: FUNCTION fn_ca_undeclared_money_paths(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_ca_undeclared_money_paths() IS 'Functions that move a balance fn_ca_autoledger watches without declaring the other side, so their movements land on settlement_suspense. TEXTUAL: it matches an UPDATE of a watched table anywhere in the body and a watched column anywhere in the body, so a function that only NAMES a balance column (an INSERT column list, a guard, a comment) scores without moving anything. A function registered status=''system'' in ca_money_rpc_registry has been audited as moving no money and is excluded. The count must only ever go down.';


--
-- TOC entry 8591 (class 1255 OID 224420031)
-- Name: fn_ca_union_join_removes_club_games(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_union_join_removes_club_games() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_blocking integer;
  v_tables jsonb;
  r record;
BEGIN
  IF NEW.club_id IS NULL OR NEW.club_id = NEW.union_id THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.club_id IS NOT DISTINCT FROM OLD.club_id
     AND NEW.union_id IS NOT DISTINCT FROM OLD.union_id THEN
    RETURN NEW;
  END IF;

  -- Club events that cannot be removed without moving players' money.
  SELECT count(*) INTO v_blocking
    FROM public.tournaments t
   WHERE (t.club_id = NEW.club_id
          OR t.schedule_id IN (SELECT s.id FROM public.tournament_schedules s WHERE s.club_id = NEW.club_id))
     AND upper(coalesce(t.status, '')) NOT IN ('COMPLETED','COMPLETING','CANCELLED','CANCELED','FAILED')
     AND (upper(coalesce(t.status, '')) IN ('RUNNING','STARTING','PAUSED','FINAL_TABLE','BREAK')
          OR EXISTS (SELECT 1 FROM public.tournament_players p WHERE p.tournament_id = t.id));
  IF v_blocking > 0 THEN
    RAISE EXCEPTION USING
      ERRCODE = 'check_violation',
      MESSAGE = 'This club still has tournaments with players and cannot join a union yet.',
      DETAIL  = format('%s club tournament(s) are running or have entrants.', v_blocking),
      HINT    = 'Every club cash game and tournament is removed before a club joins a union. Let them finish or cancel them first.';
  END IF;

  UPDATE public.tournament_schedules
     SET active = false
   WHERE club_id = NEW.club_id AND active;

  -- Every not-started club event goes through the one cancellation authority,
  -- which writes the immutable receipt (none of these has an entrant).
  FOR r IN
    SELECT t.id FROM public.tournaments t
     WHERE (t.club_id = NEW.club_id
            OR t.schedule_id IN (SELECT s.id FROM public.tournament_schedules s WHERE s.club_id = NEW.club_id))
       AND upper(coalesce(t.status, '')) NOT IN ('COMPLETED','COMPLETING','CANCELLED','CANCELED','FAILED')
     ORDER BY t.id
  LOOP
    BEGIN
      PERFORM set_config('app.managed_game_lifecycle', 'on', true);
      PERFORM public.atomic_cancel_tournament(r.id, NULL);
      PERFORM set_config('app.managed_game_lifecycle', '', true);
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION USING
        ERRCODE = 'check_violation',
        MESSAGE = 'A club tournament could not be removed, so the club cannot join a union yet.',
        DETAIL  = format('tournament %s: %s', r.id, SQLERRM),
        HINT    = 'Every club cash game and tournament is removed before a club joins a union. Cancel it first.';
    END;
  END LOOP;

  -- Closing tables marks them deleted: the sanctioned managed-game lifecycle
  -- door (fn_guard_managed_game_lifecycle), open for this step only.
  PERFORM set_config('app.managed_game_lifecycle', 'on', true);
  v_tables := public.fn_union_close_club_tables_for_join(NEW.club_id);
  IF NOT coalesce((v_tables->>'success')::boolean, false) THEN
    RAISE EXCEPTION 'Club cash games could not be closed before the union join: %', v_tables
      USING ERRCODE = 'check_violation';
  END IF;
  PERFORM set_config('app.managed_game_lifecycle', '', true);

  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_ca_union_join_removes_club_games() OWNER TO postgres;

--
-- TOC entry 4703 (class 1255 OID 224420021)
-- Name: fn_ca_union_member_schedule_cannot_spawn(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_union_member_schedule_cannot_spawn() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.schedule_id IS NOT NULL AND EXISTS (
       SELECT 1 FROM public.tournament_schedules s
         JOIN public.union_clubs uc ON uc.club_id = s.club_id AND uc.club_id <> uc.union_id
        WHERE s.id = NEW.schedule_id) THEN
    RAISE EXCEPTION USING
      ERRCODE = 'check_violation',
      MESSAGE = 'A club in a union cannot spawn events from its own schedule.';
  END IF;
  RETURN NEW;
END
$$;


