--
-- TOC entry 8427 (class 1255 OID 152613286)
-- Name: fn_ca_union_wallet_that_can_pay(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_union_wallet_that_can_pay(p_user_id uuid, p_union_id uuid, p_amount numeric) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT m.club_id
    FROM public.club_members m
   WHERE m.user_id = p_user_id
     AND m.status IN ('active', 'approved')
     AND p_union_id IS NOT NULL
     AND p_amount IS NOT NULL AND p_amount > 0
     AND COALESCE(m.chip_balance, 0) >= p_amount
     AND EXISTS (SELECT 1 FROM public.union_clubs uc
                  WHERE uc.club_id = m.club_id AND uc.union_id = p_union_id)
   ORDER BY m.chip_balance DESC, m.joined_at ASC NULLS LAST, m.club_id
   LIMIT 1
$$;


