--
-- TOC entry 5812 (class 1255 OID 28859213)
-- Name: fn_ca_unit_floor_cents(bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_unit_floor_cents(p_cents bigint, p_unit_cents integer DEFAULT 1) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN p_cents IS NULL THEN NULL
    WHEN p_cents <= 0 THEN 0
    ELSE (trunc(p_cents::numeric
                / (CASE WHEN p_unit_cents IS NOT NULL AND p_unit_cents >= 1
                        THEN p_unit_cents::numeric ELSE 1 END))
          * (CASE WHEN p_unit_cents IS NOT NULL AND p_unit_cents >= 1
                  THEN p_unit_cents::numeric ELSE 1 END))::bigint
  END;
$$;


