--
-- TOC entry 9220 (class 1255 OID 167526544)
-- Name: fn_ca_use_cashier_entry_ticket(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_use_cashier_entry_ticket(p_tournament_id uuid, p_ticket_id uuid, p_beneficiary_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := p_beneficiary_id;
  v_t public.tournaments%ROWTYPE;
  v_tk public.tournament_tickets%ROWTYPE;
  v_bind public.tournament_ticket_entry_targets%ROWTYPE;
  v_split record;
  v_is_bounty boolean;
  v_is_horse boolean;
  v_before numeric;
  v_after_credit numeric;
  v_after numeric;
  v_context jsonb;
  v_setting text;
  v_prev_paying text := current_setting('app.ca_entry_paying_club', true);
  v_result jsonb;
  v_reason text;
  v_registration uuid;
  v_receipt uuid;
BEGIN
  IF p_tournament_id IS NULL OR p_ticket_id IS NULL OR v_uid IS NULL THEN
    RAISE EXCEPTION 'tournament, ticket and beneficiary ids are required'
      USING ERRCODE = '22004';
  END IF;

  -- The satellite ticket door's lock order: settlement lane, the shared
  -- admission lock, the admission contract, the tournament, then the ticket.
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  PERFORM pg_advisory_xact_lock_shared(530090,1);
  PERFORM public.fn_ca_lock_mtt_admission_contract();
  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok',false,'reason','platform_frozen');
  END IF;
  SELECT * INTO v_t FROM public.tournaments t WHERE t.id = p_tournament_id FOR UPDATE;
  IF v_t.id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  SELECT * INTO v_tk FROM public.tournament_tickets tk WHERE tk.id = p_ticket_id FOR UPDATE;
  IF v_tk.id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_found');
  END IF;
  SELECT * INTO v_bind FROM public.tournament_ticket_entry_targets b
   WHERE b.ticket_id = v_tk.id;
  IF v_bind.ticket_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','not_a_cashier_entry_ticket');
  END IF;
  IF v_tk.holder_id IS DISTINCT FROM v_uid OR v_bind.holder_id IS DISTINCT FROM v_uid THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_owned');
  END IF;
  IF v_bind.tournament_id IS DISTINCT FROM p_tournament_id THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_for_another_tournament');
  END IF;
  IF v_tk.redemption_mode IS DISTINCT FROM 'wallet_chips'
     OR v_tk.club_id IS DISTINCT FROM v_bind.club_id
     OR v_tk.issued_by IS DISTINCT FROM v_bind.issued_by
     OR v_tk.value IS DISTINCT FROM v_bind.value THEN
    RAISE EXCEPTION 'cashier entry ticket % does not match its binding', v_tk.id
      USING ERRCODE = 'P0404';
  END IF;

  IF v_tk.status = 'redeemed' THEN
    -- An ambiguous-response retry: the entry already happened.
    SELECT ct.id INTO v_receipt FROM public.chip_transactions ct
     WHERE ct.transaction_type = 'tournament_ticket_redeem'
       AND ct.metadata->>'ticket_id' = v_tk.id::text
       AND ct.metadata->>'reason' = 'tournament_entry'
     LIMIT 1;
    SELECT tp.id INTO v_registration FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id AND tp.user_id = v_uid
     ORDER BY tp.registered_at DESC NULLS LAST LIMIT 1;
    IF v_receipt IS NOT NULL AND v_registration IS NOT NULL THEN
      RETURN jsonb_build_object('ok',true,'replayed',true,'ticket_id',v_tk.id,
        'registration_id',v_registration,'ticket_value',v_tk.value,
        'wallet_chips_credited',0);
    END IF;
    RETURN jsonb_build_object('ok',false,'reason','ticket_already_used');
  END IF;
  IF v_tk.status <> 'issued' THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_not_available');
  END IF;

  v_is_bounty := COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
              OR COALESCE(v_t.is_mystery_bounty,false);
  SELECT * INTO v_split FROM public.fn_tournament_entry_split(
    v_t.buy_in_amount, v_t.buy_in_fee, v_t.bounty_amount, v_is_bounty);
  IF v_split.charge IS DISTINCT FROM v_bind.value
     OR v_split.prize IS DISTINCT FROM v_bind.entry_prize
     OR v_split.bounty IS DISTINCT FROM v_bind.entry_bounty
     OR v_split.rake IS DISTINCT FROM v_bind.entry_fee THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_entry_contract_mismatch');
  END IF;
  IF public.fn_tournament_club_for_user(v_uid, p_tournament_id, v_tk.club_id)
       IS DISTINCT FROM v_tk.club_id THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_source_club_unavailable');
  END IF;

  SELECT COALESCE(p.is_horse,false) INTO v_is_horse FROM public.profiles p WHERE p.id = v_uid;
  v_is_horse := COALESCE(v_is_horse,false);
  IF NOT v_is_horse AND auth.uid() IS DISTINCT FROM v_uid THEN
    -- A person is entered only by their own session; a horse has no browser
    -- and is entered by the engine (CLAUDE.md 10.5, the input device).
    RAISE EXCEPTION 'a cashier entry ticket is used by its own holder'
      USING ERRCODE = '42501';
  END IF;

  SELECT m.chip_balance INTO v_before FROM public.club_members m
   WHERE m.club_id = v_tk.club_id AND m.user_id = v_uid
     AND COALESCE(m.status,'active') IN ('active','approved')
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','ticket_club_membership_inactive');
  END IF;
  v_before := COALESCE(v_before,0);

  BEGIN
    -- (a) Escrow -> the holder's wallet in the ticket's club, journaled and
    --     receipted exactly as fn_redeem_tournament_ticket does it.
    SELECT jsonb_object_agg(k,COALESCE(current_setting(k,true),'')) INTO v_context
      FROM unnest(ARRAY['app.ledger_category','app.ledger_counterparty',
                        'app.ledger_counterparty_entity','app.ledger_tournament']) settings(k);
    PERFORM set_config('app.ledger_tournament','',true);
    PERFORM set_config('app.ledger_category','ticket_redeem',true);
    PERFORM set_config('app.ledger_counterparty','escrow',true);
    PERFORM set_config('app.ledger_counterparty_entity',v_tk.id::text,true);
    UPDATE public.club_members
       SET chip_balance = COALESCE(chip_balance,0) + v_tk.value, updated_at = now()
     WHERE club_id = v_tk.club_id AND user_id = v_uid
       AND COALESCE(status,'active') IN ('active','approved')
     RETURNING chip_balance INTO v_after_credit;
    FOR v_setting IN SELECT jsonb_object_keys(v_context) LOOP
      PERFORM set_config(v_setting,v_context->>v_setting,true);
    END LOOP;
    IF v_after_credit IS DISTINCT FROM round(v_before + v_tk.value,2) THEN
      RAISE EXCEPTION 'cashier entry ticket % credit did not land exactly', v_tk.id
        USING ERRCODE = 'P0404';
    END IF;
    UPDATE public.tournament_tickets
       SET status = 'redeemed', redeemed_at = now()
     WHERE id = v_tk.id AND status = 'issued';
    INSERT INTO public.chip_transactions(
      club_id,from_user_id,to_user_id,amount,transaction_type,notes,
      balance_after,metadata)
    VALUES(
      v_tk.club_id,NULL,v_uid,v_tk.value,'tournament_ticket_redeem',
      'Tournament Ticket Used For Entry',v_after_credit,
      jsonb_build_object(
        'ticket_id',v_tk.id,'issuer_id',v_tk.issued_by,'holder_id',v_uid,
        'escrow_action','release_to_holder','reason','tournament_entry',
        'target_tournament_id',p_tournament_id,
        'holder_balance_after',v_after_credit))
    RETURNING id INTO v_receipt;
    INSERT INTO public.wallet_transactions(
      user_id,wallet_type,type,amount,category,description,balance_after)
    VALUES(
      v_uid,'PLAYER','credit',v_tk.value,'transfer',
      'Tournament Ticket Used For Entry',v_after_credit);

    -- (b) The ordinary entry door, paid from that same wallet.
    PERFORM set_config('app.ca_entry_paying_club',
      p_tournament_id::text||':'||v_uid::text||':'||v_tk.club_id::text, true);
    IF v_is_horse THEN
      v_result := public.fn_register_horse_for_tournament_before_atomic_lifecycle_gate(
        p_tournament_id, v_uid);
    ELSE
      v_result := public.fn_register_for_tournament_before_terminal_seat_gate(
        p_tournament_id, false);
    END IF;
    PERFORM set_config('app.ca_entry_paying_club', COALESCE(v_prev_paying,''), true);
    IF NOT COALESCE((v_result->>'ok')::boolean,false) THEN
      RAISE EXCEPTION USING ERRCODE = 'CT001',
        MESSAGE = COALESCE(NULLIF(v_result->>'reason',''),'registration_refused');
    END IF;

    -- (c) The wallet nets to zero exactly, in the ticket's club, or nothing
    --     happened.
    SELECT m.chip_balance INTO v_after FROM public.club_members m
     WHERE m.club_id = v_tk.club_id AND m.user_id = v_uid;
    SELECT tp.id INTO v_registration FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id AND tp.user_id = v_uid
       AND tp.id = (v_result->>'registration_id')::uuid;
    IF v_after IS DISTINCT FROM v_before OR v_registration IS NULL
       OR (v_result->>'cost')::numeric IS DISTINCT FROM v_tk.value THEN
      RAISE EXCEPTION 'cashier entry ticket % entry was not paid exactly from its own credit (% -> %)',
        v_tk.id, v_before, v_after USING ERRCODE = 'P0404';
    END IF;
  EXCEPTION WHEN SQLSTATE 'CT001' THEN
    v_reason := SQLERRM;
    PERFORM set_config('app.ca_entry_paying_club', COALESCE(v_prev_paying,''), true);
    RETURN jsonb_build_object('ok',false,'reason',v_reason,'ticket_id',v_tk.id);
  END;

  RETURN v_result || jsonb_build_object(
    'ok',true,'replayed',false,'ticket_id',v_tk.id,
    'registration_id',v_registration,'ticket_value',v_tk.value,
    'ticket_kind','cashier_entry_ticket','redeem_transaction_id',v_receipt,
    'wallet_chips_credited',0);
END;
$$;


ALTER FUNCTION public.fn_ca_use_cashier_entry_ticket(p_tournament_id uuid, p_ticket_id uuid, p_beneficiary_id uuid) OWNER TO postgres;

--
-- TOC entry 5643 (class 1255 OID 18104077)
-- Name: fn_ca_verify_ledger_chain(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_verify_ledger_chain(p_last_n bigint DEFAULT 50000) RETURNS TABLE(checked bigint, breaks bigint, first_break_seq bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r RECORD;
  v_checked bigint := 0;
  v_breaks  bigint := 0;
  v_first   bigint := NULL;
  v_calc text;
BEGIN
  FOR r IN
    SELECT * FROM (
      SELECT * FROM public.chip_ledger
       WHERE chain_seq IS NOT NULL
       ORDER BY chain_seq DESC
       LIMIT p_last_n) t
    ORDER BY chain_seq ASC
  LOOP
    v_checked := v_checked + 1;
    v_calc := encode(extensions.digest(
      'v1'
      || '|' || r.chain_seq::text
      || '|' || COALESCE(r.epoch_id::text,'')
      || '|' || r.amount::text
      || '|' || r.from_type || ':' || COALESCE(r.from_entity_id::text,'')
      || '|' || r.to_type   || ':' || COALESCE(r.to_entity_id::text,'')
      || '|' || r.category
      || '|' || COALESCE(r.idempotency_key,'')
      || '|' || COALESCE(r.correlation_id::text,'')
      || '|' || r.created_at::text,
      'sha256'), 'hex');
    IF v_calc IS DISTINCT FROM r.row_hash THEN
      v_breaks := v_breaks + 1;
      v_first := COALESCE(v_first, r.chain_seq);
    END IF;
  END LOOP;

  IF v_breaks > 0 THEN
    PERFORM public.fn_ca_raise_drift_incident(
      'fn_ca_verify_ledger_chain', 'unauthorized_adjustment', 'critical',
      'ledger-chain-break:' || COALESCE(v_first, 0)::text,
      0, NULL, NULL, 'ledger', 'chip_ledger', NULL, NULL, NULL, NULL, NULL,
      NULL, NULL, NULL, NULL,
      'checksum verification found ' || v_breaks || ' altered row(s) starting at seq ' || v_first,
      false, jsonb_build_object('breaks', v_breaks, 'first_break_seq', v_first));
  END IF;

  checked := v_checked; breaks := v_breaks; first_break_seq := v_first;
  RETURN NEXT;
END $$;


ALTER FUNCTION public.fn_ca_verify_ledger_chain(p_last_n bigint) OWNER TO postgres;

--
-- TOC entry 4686 (class 1255 OID 27155965)
-- Name: fn_ca_verify_terminal_final_deal_batch(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_verify_terminal_final_deal_batch(p_tournament_id uuid, p_require_terminal boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
 v_t public.tournaments%ROWTYPE;
 v_b public.tournament_final_table_deal_batches%ROWTYPE;
 v_e public.tournament_escrow%ROWTYPE;
 v_ob public.tournament_obligations%ROWTYPE;
 v_input jsonb; v_tail jsonb; v_ladder jsonb; v_expected jsonb;
 v_field integer; v_ladder_count integer; v_max_place integer;
 v_place_total numeric; v_deal_cents bigint; v_chips numeric;
 v_bubble numeric:=0; v_bubble_user uuid;
 v_line record; v_amount numeric; v_paid numeric; v_count integer;
 v_not_pool text[]:=ARRAY['satellite_seat','bounty','mystery_bounty',
  'bounty_residual','own_bounty','mystery_bounty_residual'];
BEGIN
 SELECT * INTO STRICT v_t FROM public.tournaments WHERE id=p_tournament_id;
 SELECT * INTO STRICT v_b FROM public.tournament_final_table_deal_batches
  WHERE tournament_id=p_tournament_id;
 IF v_b.contract_version<>2 OR v_b.settled_at IS NULL
  OR v_b.source IS DISTINCT FROM 'engine.fn_settle_tournament_final_table_deal'
  OR v_t.prize_pool_finalized IS DISTINCT FROM true
  OR v_t.prize_pool IS NULL OR v_t.prize_pool<=0
  OR v_t.prize_pool::text IN ('NaN','Infinity','-Infinity')
  OR v_t.prize_pool<>round(v_t.prize_pool,2)
  OR v_t.prize_pool<COALESCE(v_t.guaranteed_prize,0)
  OR lower(COALESCE(v_t.variant,''))='satellite'
  OR upper(COALESCE(v_t.tournament_type,''))='SATELLITE'
  OR v_t.satellite_target_id IS NOT NULL OR v_t.satellite_target IS NOT NULL
 THEN RAISE EXCEPTION 'canonical final deal is not a settled funded cash batch'; END IF;
 SELECT count(*) INTO v_field FROM public.tournament_players WHERE tournament_id=p_tournament_id;
 IF v_field<>v_b.field_count OR v_b.live_count>v_field
  OR v_b.live_count>v_t.table_size OR v_b.live_count<2
  OR (SELECT count(DISTINCT position) FROM public.tournament_players
   WHERE tournament_id=p_tournament_id)<>v_field
  OR (SELECT count(*) FROM public.tournament_players WHERE tournament_id=p_tournament_id
   AND status='winner' AND position=1 AND user_id=v_b.chip_leader
   AND eliminated_at IS NULL AND elimination_sequence IS NULL)<>1
  OR EXISTS(SELECT 1 FROM public.tournament_players WHERE tournament_id=p_tournament_id
   AND (position IS NULL OR position<1 OR position>v_field
    OR status NOT IN ('winner','eliminated')
    OR (position>1 AND (status<>'eliminated' OR eliminated_at IS NULL
     OR elimination_sequence IS NULL OR elimination_sequence<=0))
    OR (status='winner' AND position<>1)))
  OR (SELECT count(DISTINCT elimination_sequence) FROM public.tournament_players
   WHERE tournament_id=p_tournament_id AND status='eliminated')<>v_field-1
  OR EXISTS(SELECT 1 FROM (SELECT position,
   row_number() OVER(ORDER BY COALESCE(public.fn_ca_tournament_bust_at(tournament_id, user_id), eliminated_at) DESC NULLS LAST, elimination_sequence DESC,id)+1 expected
   FROM public.tournament_players WHERE tournament_id=p_tournament_id
    AND status='eliminated') q WHERE position<>expected)
 THEN RAISE EXCEPTION 'canonical final deal durable standings differ'; END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('user_id',tp.user_id,'club_id',tp.club_id,
  'chips',tp.chips,'registered_at',extract(epoch FROM tp.registered_at))
  ORDER BY tp.chips DESC,tp.registered_at ASC NULLS LAST,tp.user_id),'[]'::jsonb),
  sum(tp.chips)
 INTO v_input,v_chips FROM public.tournament_players tp
 WHERE tp.tournament_id=p_tournament_id AND tp.position<=v_b.live_count;
 IF v_input IS DISTINCT FROM v_b.live_input_snapshot
  OR md5(v_input::text) IS DISTINCT FROM v_b.live_input_fingerprint
  OR jsonb_array_length(v_input)<>v_b.live_count OR v_chips IS NULL OR v_chips<=0
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_input) x
   WHERE x->>'chips' IS NULL OR (x->>'chips')::numeric<0
    OR x->>'chips' IN ('NaN','Infinity','-Infinity'))
  OR (v_input->0->>'user_id')::uuid IS DISTINCT FROM v_b.chip_leader
  OR NOT EXISTS(SELECT 1 FROM public.tables WHERE id=v_b.deal_table_id
    AND tournament_id=p_tournament_id)
 THEN RAISE EXCEPTION 'canonical final deal immutable input differs'; END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',tp.id,'user_id',tp.user_id,
  'club_id',tp.club_id,'position',tp.position,'eliminated_at',extract(epoch FROM tp.eliminated_at),
  'elimination_sequence',tp.elimination_sequence) ORDER BY tp.position),'[]'::jsonb)
 INTO v_tail FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament_id
  AND tp.position>v_b.live_count;
 IF md5(v_tail::text) IS DISTINCT FROM v_b.prior_standings_fingerprint
 THEN RAISE EXCEPTION 'canonical final deal prior standings differ'; END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('place',a.place,'amount',a.amount)
  ORDER BY a.place),'[]'::jsonb),count(*),max(a.place),
  COALESCE(sum(a.amount) FILTER(WHERE a.place>v_b.live_count),0)
 INTO v_ladder,v_ladder_count,v_max_place,v_place_total
 FROM public.fn_ca_tournament_place_amounts(p_tournament_id) a;
 IF v_ladder_count=0 OR v_ladder_count<>v_b.structure_place_count
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_ladder) x
    WHERE (x->>'amount')::numeric<0
     OR (x->>'amount')::numeric<>round((x->>'amount')::numeric,2))
 THEN RAISE EXCEPTION 'canonical final deal structure differs'; END IF;
 IF v_t.bubble_protection AND v_max_place+1<=v_field AND v_max_place+1>v_b.live_count THEN
  v_bubble:=v_t.buy_in_amount;
  IF v_bubble IS NULL OR v_bubble<=0 OR v_bubble::text IN ('NaN','Infinity','-Infinity')
   OR v_bubble<>round(v_bubble,2) THEN RAISE EXCEPTION 'canonical final deal Bubble amount invalid'; END IF;
  SELECT user_id INTO STRICT v_bubble_user FROM public.tournament_players
   WHERE tournament_id=p_tournament_id AND position=v_max_place+1 AND status='eliminated';
 END IF;
 v_deal_cents:=round((v_t.prize_pool-v_place_total-v_bubble)*100)::bigint;
 IF v_deal_cents<=0 THEN RAISE EXCEPTION 'canonical final deal residual invalid'; END IF;
 WITH live AS (
  SELECT (x->>'user_id')::uuid user_id,(x->>'club_id')::uuid club_id,ord::integer place,
   floor((x->>'chips')::numeric*v_deal_cents/v_chips)::bigint cents
  FROM jsonb_array_elements(v_input) WITH ORDINALITY z(x,ord)
 ), all_lines AS (
  SELECT 'final_table_deal' kind,place,user_id,club_id,
   cents+CASE WHEN place=1 THEN v_deal_cents-(SELECT sum(cents) FROM live) ELSE 0 END cents
   FROM live
  UNION ALL
  SELECT 'place',(x->>'place')::integer,tp.user_id,tp.club_id,
   round((x->>'amount')::numeric*100)::bigint
  FROM jsonb_array_elements(v_ladder) x JOIN public.tournament_players tp
   ON tp.tournament_id=p_tournament_id AND tp.position=(x->>'place')::integer
  WHERE (x->>'place')::integer>v_b.live_count AND (x->>'amount')::numeric>0
 )
 SELECT COALESCE(jsonb_agg(jsonb_build_object('kind',kind,'place',place,
  'user_id',user_id,'club_id',club_id,'cents',cents) ORDER BY place),'[]'::jsonb)
 INTO v_expected FROM all_lines;
 IF v_b.plan IS DISTINCT FROM v_expected OR v_b.plan_fingerprint IS DISTINCT FROM md5(v_expected::text)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_expected) x WHERE (x->>'cents')::bigint<=0)
  OR v_b.place_amount IS DISTINCT FROM v_place_total
  OR v_b.deal_amount IS DISTINCT FROM v_deal_cents::numeric/100
  OR v_b.amount_owed IS DISTINCT FROM v_t.prize_pool-v_bubble
  OR v_b.deal_line_count<>v_b.live_count
  OR v_b.place_line_count<>jsonb_array_length(v_expected)-v_b.live_count
  OR v_b.escrow_prize_after IS DISTINCT FROM 0::numeric
  OR v_b.escrow_prize_before IS DISTINCT FROM v_b.amount_moved
  OR v_b.amount_moved<0 OR v_b.amount_moved>v_t.prize_pool
 THEN RAISE EXCEPTION 'canonical final deal plan or escrow proof differs'; END IF;
 FOR v_line IN SELECT (x->>'kind') kind,(x->>'place')::integer place,
  (x->>'user_id')::uuid user_id,(x->>'cents')::numeric/100 amount
  FROM jsonb_array_elements(v_expected) x
 LOOP
  SELECT * INTO STRICT v_ob FROM public.tournament_obligations o WHERE
   o.tournament_id=p_tournament_id AND o.kind=v_line.kind
   AND (CASE WHEN v_line.kind='place' THEN o.place=v_line.place
    ELSE o.place IS NULL AND o.user_id=v_line.user_id END);
  IF v_ob.user_id IS DISTINCT FROM v_line.user_id OR v_ob.amount_owed IS DISTINCT FROM v_line.amount
   OR v_ob.amount_paid IS DISTINCT FROM v_line.amount OR v_ob.settled_at IS NULL
   OR (v_line.kind='final_table_deal' AND (v_ob.source IS DISTINCT FROM 'final_table_deal'
    OR v_ob.adjustment_id IS NOT NULL))
  THEN RAISE EXCEPTION 'canonical final deal obligation differs at place %',v_line.place; END IF;
  SELECT COALESCE(sum(p.amount),0),count(*) INTO v_paid,v_count FROM public.tournament_payouts p
   WHERE p.tournament_id=p_tournament_id AND p.user_id=v_line.user_id
    AND (CASE WHEN v_line.kind='place' THEN p.position=v_line.place
      AND NOT(COALESCE(p.source,'')=ANY(v_not_pool)) AND p.source<>'final_table_deal'
     ELSE p.position IS NULL AND p.source='final_table_deal' END);
  IF v_paid IS DISTINCT FROM v_line.amount OR v_count<1
   OR (v_line.kind='final_table_deal' AND v_count<>1)
  THEN RAISE EXCEPTION 'canonical final deal payout differs at place %',v_line.place; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.tournament_obligations o
  WHERE o.tournament_id=p_tournament_id AND o.kind IN ('place','final_table_deal')
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_expected) x
    WHERE o.kind=x->>'kind' AND o.user_id=(x->>'user_id')::uuid
     AND (CASE WHEN o.kind='place' THEN o.place=(x->>'place')::integer ELSE o.place IS NULL END)))
 THEN RAISE EXCEPTION 'canonical final deal has uncontracted debt'; END IF;
 SELECT count(*) INTO v_count FROM public.tournament_obligations
  WHERE tournament_id=p_tournament_id AND kind='bubble_protection';
 IF v_bubble>0 THEN
  SELECT * INTO STRICT v_ob FROM public.tournament_obligations
   WHERE tournament_id=p_tournament_id AND kind='bubble_protection';
  IF v_count<>1 OR v_ob.place IS NOT NULL OR v_ob.user_id IS DISTINCT FROM v_bubble_user
   OR v_ob.amount_owed IS DISTINCT FROM v_bubble OR v_ob.amount_paid IS DISTINCT FROM v_bubble
   OR v_ob.settled_at IS NULL OR v_ob.source IS NULL
   OR v_ob.source NOT IN ('engine.eliminatePlayer','engine.atomicPlaceSettlement',
    'engine.fn_settle_tournament_places','engine.fn_settle_tournament_bubble_protection')
   OR v_b.bubble_contract_required IS DISTINCT FROM true
   OR v_b.bubble_obligation_id IS DISTINCT FROM v_ob.id
   OR v_b.bubble_user_id IS DISTINCT FROM v_bubble_user
   OR v_b.bubble_source IS DISTINCT FROM v_ob.source
   OR v_b.bubble_amount_owed IS DISTINCT FROM v_bubble
   OR v_b.bubble_amount_paid_before<0 OR v_b.bubble_amount_paid_before>v_bubble
   OR (SELECT COALESCE(sum(amount),0) FROM public.tournament_payouts
    WHERE tournament_id=p_tournament_id AND source='bubble_protection') IS DISTINCT FROM v_bubble
  THEN RAISE EXCEPTION 'canonical final deal Bubble proof differs'; END IF;
 ELSIF v_count<>0 OR v_b.bubble_contract_required IS DISTINCT FROM false
  OR v_b.bubble_obligation_id IS NOT NULL OR v_b.bubble_user_id IS NOT NULL
  OR v_b.bubble_source IS NOT NULL OR v_b.bubble_amount_owed<>0 OR v_b.bubble_amount_paid_before<>0
 THEN RAISE EXCEPTION 'canonical final deal has uncontracted Bubble'; END IF;
 IF EXISTS(SELECT 1 FROM public.tournament_payouts p WHERE p.tournament_id=p_tournament_id
  AND NOT(COALESCE(p.source,'')=ANY(v_not_pool)) AND
   (p.amount IS NULL OR p.amount<=0 OR p.amount::text IN ('NaN','Infinity','-Infinity')
    OR p.amount<>round(p.amount,2) OR p.idempotency_key IS NULL
    OR NOT EXISTS(SELECT 1 FROM public.wallet_credit_idempotency k WHERE
     k.key=p.idempotency_key AND k.user_id=p.user_id AND k.amount=p.amount)
    OR NOT(
     (p.source='bubble_protection' AND p.position IS NULL AND p.user_id=v_bubble_user AND v_bubble>0)
     OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_expected) x WHERE p.user_id=(x->>'user_id')::uuid
      AND CASE WHEN x->>'kind'='place' THEN p.position=(x->>'place')::integer
        AND p.source<>'final_table_deal' AND p.source<>'bubble_protection'
       ELSE p.position IS NULL AND p.source='final_table_deal' END))))
  OR (SELECT COALESCE(sum(p.amount),0) FROM public.tournament_payouts p
   WHERE p.tournament_id=p_tournament_id AND NOT(COALESCE(p.source,'')=ANY(v_not_pool)))
    IS DISTINCT FROM v_t.prize_pool
  OR EXISTS(SELECT 1 FROM public.tournament_players tp WHERE tp.tournament_id=p_tournament_id
   AND tp.prize IS DISTINCT FROM COALESCE((SELECT sum(p.amount) FROM public.tournament_payouts p
    WHERE p.tournament_id=p_tournament_id AND p.user_id=tp.user_id
     AND NOT(COALESCE(p.source,'')=ANY(v_not_pool))),0))
 THEN RAISE EXCEPTION 'canonical final deal wallet proof or cache differs'; END IF;
 -- Every obligation-scoped wallet credit must retain its exact payout witness.
 -- This also rejects an extra spent key hidden behind otherwise-correct totals.
 IF EXISTS(SELECT 1 FROM public.tournament_obligations o
  JOIN public.wallet_credit_idempotency k
   ON k.key LIKE 'tourney:'||p_tournament_id::text||':obl:'||o.id::text||':%'
  WHERE o.tournament_id=p_tournament_id AND o.kind IN ('place','final_table_deal','bubble_protection')
   AND NOT EXISTS(SELECT 1 FROM public.tournament_payouts p
    WHERE p.tournament_id=p_tournament_id AND p.idempotency_key=k.key
     AND p.user_id=k.user_id AND p.user_id=o.user_id AND p.amount=k.amount
     AND CASE WHEN o.kind='place' THEN p.position=o.place
       AND NOT(COALESCE(p.source,'')=ANY(v_not_pool))
       AND p.source NOT IN ('final_table_deal','bubble_protection')
      ELSE p.position IS NULL AND p.source=o.kind END))
 THEN RAISE EXCEPTION 'canonical final deal has an orphaned wallet credit'; END IF;
 SELECT * INTO STRICT v_e FROM public.tournament_escrow WHERE tournament_id=p_tournament_id;
 IF v_e.enforced IS DISTINCT FROM true OR v_e.prize_balance IS DISTINCT FROM 0::numeric
  OR (p_require_terminal AND (v_e.bounty_balance IS DISTINCT FROM 0::numeric
   OR v_e.fee_balance IS DISTINCT FROM 0::numeric OR v_e.closed_at IS NULL
   OR NOT EXISTS(SELECT 1 FROM public.tournament_finish_receipts f
    WHERE f.tournament_id=p_tournament_id AND f.finish_kind='final_table_deal'
     AND f.winner_user_id=v_b.chip_leader)
   OR EXISTS(SELECT 1 FROM public.table_seats s JOIN public.tables t ON t.id=s.table_id
    WHERE t.tournament_id=p_tournament_id AND (s.left_at IS NULL OR s.status IS DISTINCT FROM 'left'))))
 THEN RAISE EXCEPTION 'canonical final deal has open custody, seats or missing finish claim'; END IF;
 RETURN jsonb_build_object('ok',true,'contract_version',2,'plan_fingerprint',v_b.plan_fingerprint,
  'place_amount',v_place_total,'deal_amount',v_deal_cents::numeric/100,'bubble_amount',v_bubble,
  'chip_leader',v_b.chip_leader);
END;
$$;


ALTER FUNCTION public.fn_ca_verify_terminal_final_deal_batch(p_tournament_id uuid, p_require_terminal boolean) OWNER TO postgres;

--
-- TOC entry 7078 (class 1255 OID 18288941)
-- Name: fn_ca_weekly_revenue_digest(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_weekly_revenue_digest(p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_since timestamptz := now() - make_interval(days => GREATEST(p_days,1));
  v jsonb; v_msg text; r uuid;
BEGIN
  -- One statement/snapshot. Posted transfer volume is not revenue or spend.
  WITH legs AS MATERIALIZED (
    SELECT l.amount,l.category,l.from_type,l.to_type,l.from_entity_id,l.to_entity_id FROM public.chip_ledger l
    WHERE l.created_at > v_since AND l.created_at <= now() AND l.status='posted'
  ), totals AS (
    SELECT
      COALESCE(sum(amount) FILTER(WHERE category='rake' AND from_type='table_stack'),0) cash_rake,
      COALESCE(sum(amount) FILTER(WHERE category='rake' AND from_type='prize_liability'),0) tournament_rake,
      COALESCE(sum(amount) FILTER(WHERE category='rakeback' AND from_type='union_wallet' AND to_type='club_treasury'),0) club_rakeback,
      COALESCE(sum(amount) FILTER(WHERE category='rakeback' AND to_type='player_wallet'),0) player_rakeback,
      COALESCE(sum(amount) FILTER(WHERE category='rakeback'),0) rakeback_volume,
      COALESCE(sum(amount) FILTER(WHERE category='rakeback' AND
        ((from_type='union_wallet' AND to_type='club_treasury') OR to_type='player_wallet') IS NOT TRUE),0) other_rakeback,
      COALESCE(sum(amount) FILTER(WHERE from_type IN('system_mint','issuance_reserve')),0) minted,
      COALESCE(sum(amount) FILTER(WHERE to_type IN('system_burn','chip_retirement')),0) burned,
      COALESCE(sum(amount) FILTER(WHERE category IN('promo_send','promo','leaderboard_payout')
        AND to_type IN('player_wallet','table_stack')),0) player_promo,
      COALESCE(sum(amount) FILTER(WHERE category IN('promo_send','promo','leaderboard_payout')
        AND (to_type IN('player_wallet','table_stack')) IS NOT TRUE),0) promo_funding,
      COALESCE(sum(amount) FILTER(WHERE category='club_opening_allocation' AND from_type='club_treasury' AND to_type='opening_setup'),0) opening_setup,
      COALESCE(sum(amount) FILTER(WHERE category='club_opening_allocation' AND from_type='opening_setup' AND to_type IN('bbj_pool','spin_reserve')),0) opening_reserves,
      COALESCE(sum(amount) FILTER(WHERE category='bbj_contribution'),0) bbj,
      COALESCE(sum(amount) FILTER(WHERE from_type='settlement_suspense' OR to_type='settlement_suspense'),0) suspense,
      COALESCE(sum(amount) FILTER(WHERE (from_type='player_wallet' AND public.fn_ca_is_cert_account(from_entity_id))
        OR (to_type='player_wallet' AND public.fn_ca_is_cert_account(to_entity_id))),0) cert_flow
    FROM legs
  ), snapshots AS (
    SELECT count(*) observations,count(unexplained) comparable,
      count(*) FILTER(WHERE unexplained<>0) nonzero,
      count(DISTINCT basis_version) bases,
      sum(unexplained) signed_net,sum(abs(unexplained)) absolute_movement,
      max(abs(unexplained)) maximum_movement,min(taken_at) first_at,max(taken_at) last_at
    FROM public.ca_supply_snapshots WHERE taken_at>v_since AND taken_at<=now()
  )
  SELECT jsonb_build_object(
    'digest_version',2,'window_days',p_days,'since',v_since,'until',now(),
    'cash_rake',round(t.cash_rake,2),'tournament_and_spin_rake',round(t.tournament_rake,2),
    'rakeback_paid_to_clubs',round(t.club_rakeback,2),
    'rakeback_paid_to_players',round(t.player_rakeback,2),
    'rakeback_transfer_volume',round(t.rakeback_volume,2),
    'other_rakeback_transfers',round(t.other_rakeback,2),
    'minted',round(t.minted,2),'burned',round(t.burned,2),
    'promo_and_leaderboard_spend',round(t.player_promo,2),
    'promo_funding_transfers',round(t.promo_funding,2),
    'opening_setup_transfers',round(t.opening_setup,2),
    'opening_reserve_allocations',round(t.opening_reserves,2),
    'bbj_contributions',round(t.bbj,2),'suspense_flow',round(t.suspense,2),
    'cert_player_flow',round(t.cert_flow,2),
    'cert_flow_treatment','reported_separately_not_subtracted',
    'diamond_net',(SELECT round(COALESCE(sum(amount),0),2) FROM public.diamond_transactions
      WHERE created_at>v_since AND created_at<=now()),
    -- No observation is NULL, never a fabricated 0. Netting is not a verdict.
    'supply_unexplained_net',round(s.signed_net,2),
    'supply_absolute_unexplained',round(s.absolute_movement,2),
    'supply_maximum_unexplained',round(s.maximum_movement,2),
    'supply_snapshot_count',s.observations,'supply_comparable_count',s.comparable,
    'supply_nonzero_count',s.nonzero,'supply_first_at',s.first_at,'supply_last_at',s.last_at,
    'supply_status',CASE WHEN s.observations=0 THEN 'no_observations'
      WHEN s.comparable<>s.observations OR s.bases<>1 THEN 'basis_transition_or_incomplete'
      WHEN s.nonzero>0 THEN 'nonzero_observations' ELSE 'zero_observations_not_account_certification' END,
    'generated_at',now()
  ) INTO v FROM totals t CROSS JOIN snapshots s;

  v_msg := 'Cash Rake ' || (v->>'cash_rake')
    || ' | Tournament And Spin Rake ' || (v->>'tournament_and_spin_rake')
    || ' | Club Rakeback ' || (v->>'rakeback_paid_to_clubs')
    || ' | Player Rakeback ' || (v->>'rakeback_paid_to_players')
    || ' | Player Promo And Leaderboard ' || (v->>'promo_and_leaderboard_spend')
    || ' | Minted ' || (v->>'minted') || ' | Burned ' || (v->>'burned')
    || ' | BBJ Contributions ' || (v->>'bbj_contributions')
    || ' | Supply Status ' || (v->>'supply_status');

  FOR r IN SELECT user_id FROM ca_incident_recipients WHERE active
  LOOP
    INSERT INTO notifications (user_id, type, title, message, data)
    VALUES (r, 'financial_digest',
            'Weekly Revenue Digest (' || p_days || 'd)',
            left(v_msg, 500),
            jsonb_build_object('digest', v));
  END LOOP;

  RETURN v;
END $$;


ALTER FUNCTION public.fn_ca_weekly_revenue_digest(p_days integer) OWNER TO postgres;

--
-- TOC entry 5014 (class 1255 OID 218362672)
-- Name: fn_ca_writer_lock_sentinel(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_writer_lock_sentinel(p_max_xact_seconds integer DEFAULT 15) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    SET statement_timeout TO '4s'
    SET lock_timeout TO '1s'
    AS $$
DECLARE
  v_max  interval := make_interval(secs => GREATEST(COALESCE(p_max_xact_seconds, 15), 5));
  r      record;
  v_blk  integer;
  v_ok   boolean;
  v_n    integer := 0;
BEGIN
  FOR r IN
    SELECT DISTINCT ON (a.pid)
           a.pid, a.usename::text AS usename, a.application_name,
           l.mode, format('%I.%I', n.nspname, c.relname) AS rel,
           now() - a.xact_start AS age, NOT l.granted AS waiting,
           left(a.query, 500) AS query
      FROM pg_catalog.pg_locks l
      JOIN pg_catalog.pg_stat_activity a ON a.pid = l.pid
      JOIN pg_catalog.pg_class c ON c.oid = l.relation
      JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     WHERE l.locktype = 'relation'
       AND l.mode IN ('ShareLock','ShareRowExclusiveLock','ExclusiveLock','AccessExclusiveLock')
       AND n.nspname = 'public'
       AND c.relpersistence = 'p'
       AND a.backend_type = 'client backend'
       AND a.pid <> pg_backend_pid()
       AND a.usename IS DISTINCT FROM 'authenticator'
       AND a.xact_start < now() - v_max
     ORDER BY a.pid, (NOT l.granted) DESC, l.mode DESC
  LOOP
    SELECT count(*) INTO v_blk
      FROM pg_catalog.pg_stat_activity b
     WHERE b.wait_event_type = 'Lock'
       AND b.pid <> r.pid
       AND r.pid = ANY (pg_catalog.pg_blocking_pids(b.pid));

    CONTINUE WHEN NOT r.waiting AND v_blk = 0;

    BEGIN
      v_ok := pg_catalog.pg_cancel_backend(r.pid);
    EXCEPTION WHEN OTHERS THEN
      v_ok := false;
    END;

    INSERT INTO public.ca_writer_lock_sentinel_cancels
      (pid, usename, application_name, lock_mode, relation, xact_age, waiting, blocked, cancelled, query)
    VALUES (r.pid, r.usename, r.application_name, r.mode, r.rel, r.age, r.waiting, v_blk, COALESCE(v_ok, false), r.query);

    INSERT INTO public.financial_alerts (severity, source, message, context)
    VALUES ('warning', 'fn_ca_writer_lock_sentinel',
            format('A %s session (pid %s, %s, transaction open %s) was %s for %s on %s while %s live request(s) waited behind it. '
                   || 'A migration may not hold the live tables: apply it again outside the :50-:03 break, after its lock can be taken in one short try.',
                   COALESCE(NULLIF(r.application_name, ''), 'database'), r.pid, COALESCE(r.usename, '?'),
                   date_trunc('second', r.age),
                   CASE WHEN COALESCE(v_ok, false) THEN 'cancelled' ELSE 'NOT cancelled (signal refused)' END,
                   CASE WHEN r.waiting THEN 'queueing ' ELSE 'holding ' END || r.mode, r.rel, v_blk),
            jsonb_build_object('pid', r.pid, 'usename', r.usename, 'application_name', r.application_name,
                               'lock_mode', r.mode, 'relation', r.rel, 'xact_age_s', extract(epoch FROM r.age)::int,
                               'waiting', r.waiting, 'blocked', v_blk, 'cancelled', COALESCE(v_ok, false)));
    v_n := v_n + 1;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'checked_at', now(), 'cancelled', v_n);
END;
$$;


ALTER FUNCTION public.fn_ca_writer_lock_sentinel(p_max_xact_seconds integer) OWNER TO postgres;

--
-- TOC entry 5110 (class 1255 OID 26192566)
-- Name: fn_ca_xid8(xid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ca_xid8(p_xmin xid) RETURNS xid8
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  /* RESTORED AGAINST XMAX, NOT XMIN (2026-10-02, 20261002170824). Every
     tuple the calling statement can see has an xmin below its snapshot's
     xmax, so the epoch of xmax is the epoch of any xmin below its low 32
     bits, and the one before for any xmin above them (the counter wrapped
     since). Against xmin, every xid newer than the oldest running
     transaction came back as "the future" in epoch 0 and as one epoch too
     old after a wraparound. */
  WITH cur AS (
    SELECT pg_snapshot_xmax(pg_current_snapshot())::text::bigint AS cur64
  ), parts AS (
    SELECT cur64 >> 32 AS epoch, cur64 & 4294967295 AS cur32, p_xmin::text::bigint AS x FROM cur
  )
  SELECT CASE
           /* bootstrap / frozen sentinel: older than everything */
           WHEN x < 3 THEN x
           WHEN x < cur32 THEN (epoch << 32) + x
           /* at or past xmax with no earlier epoch: not yet visible, as it is */
           WHEN epoch = 0 THEN x
           ELSE ((epoch - 1) << 32) + x
         END::text::xid8
    FROM parts;
$$;


ALTER FUNCTION public.fn_ca_xid8(p_xmin xid) OWNER TO postgres;

--
-- TOC entry 5831 (class 1255 OID 34785382)
-- Name: fn_calculate_cash_rakeback_periods(uuid, date, date, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_calculate_cash_rakeback_periods(p_club_id uuid, p_period_start date, p_period_end date, p_user_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '300s'
    AS $$
DECLARE
 tournament_quality jsonb;v_from timestamptz; v_to timestamptz; cutover timestamptz; receipt jsonb;
 scope_union uuid; issue_count bigint; existing public.rakeback_periods%ROWTYPE;
 evidence_issues bigint; incomplete_issues bigint; drifted_issues bigint;
 certificate public.accounting_rakeback_period_calculations%ROWTYPE;
 player record; total_unrounded numeric; amount numeric; display_rate numeric;
 payer_kind text; payer_user uuid; coordinator_union uuid; allocations jsonb; plan jsonb;
 fingerprint text; period_id uuid; written integer:=0; confirmed integer:=0;
 digest_now text; evidence_cp public.accounting_rakeback_period_evidence_checkpoints%ROWTYPE; counts record;
 base_horizon timestamptz; next_horizon timestamptz; base_records bigint; base_evidence bigint; base_incomplete bigint; base_drifted bigint;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'accounting_period_not_authorised' USING ERRCODE='42501'; END IF;
 IF p_club_id IS NULL OR p_period_start IS NULL OR p_period_end IS NULL
    OR NOT isfinite(p_period_start) OR NOT isfinite(p_period_end)
    OR extract(isodow FROM p_period_start)<>1 OR p_period_end<>p_period_start+6
    OR (p_user_ids IS NOT NULL AND (cardinality(p_user_ids)>2000 OR array_position(p_user_ids,NULL) IS NOT NULL))
 THEN RAISE EXCEPTION 'invalid_accounting_period_request' USING ERRCODE='22023'; END IF;
 receipt:=jsonb_build_object('accounting_version',2,'club_id',p_club_id,'period_start',p_period_start,'period_end',p_period_end,'written',0,'status','blocked');
 v_from:=p_period_start::timestamp AT TIME ZONE 'America/Los_Angeles';
 v_to:=(p_period_end+1)::timestamp AT TIME ZONE 'America/Los_Angeles';
 v_from:=public.fn_ca_launch_accounting_start('club',p_club_id,v_from);
 SELECT starts_at INTO cutover FROM public.accounting_cash_accrual_cutover WHERE singleton;
 IF cutover IS NULL OR v_from<cutover THEN RETURN receipt||jsonb_build_object('reason','historical_week_before_observed_source_cutover'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('accounting_rakeback_period:'||p_club_id::text||':'||p_period_start::text,0));
 SELECT union_id INTO scope_union FROM public.clubs WHERE id=p_club_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'accounting_club_not_found' USING ERRCODE='22023'; END IF;
 IF p_user_ids IS NULL THEN
 -- Tournament fees are earned at terminal recognition. Open captured fees
 -- are excluded; deferred or missing terminal authority blocks its actual week.
 tournament_quality:=public.fn_accounting_tournament_week_quality(p_club_id,v_from,v_to);
 IF tournament_quality->>'status' IS DISTINCT FROM 'ready' THEN
  RETURN receipt||tournament_quality||jsonb_build_object('written',0);END IF;
 -- One pass over the week feeds all three source-evidence counts. They are
 -- TESTED below in the original order, so the reason a bad week reports is
 -- unchanged; only the number of times the week is read has.
 WITH week_records AS MATERIALIZED (
  SELECT r.id,r.hand_id,r.club_id,r.rake_amount,r.created_at
   FROM public.rake_records r
   WHERE r.created_at>=v_from AND r.created_at<v_to AND r.rake_amount>0
     AND r.is_tournament IS NOT TRUE AND r.tournament_id IS NULL
     -- fn_rake_record_is_ghost_twin returns false the moment hand_id is not
     -- null, so `hand_id IS NOT NULL OR NOT ghost_twin(...)` is the same
     -- predicate - but OR short-circuits, so a linked row never detoasts its
     -- metadata and never runs the function's EXISTS over
     -- idx_rake_records_table_id. 2,652 ms -> 348 ms for the week slice.
     AND (r.hand_id IS NOT NULL OR NOT public.fn_rake_record_is_ghost_twin(r.hand_id,r.table_id,r.metadata))
 ), club_attributions AS MATERIALIZED (
  -- Only this week's records reach the two counts that read this slice, so
  -- joining it to week_records is exact. Reading the club's whole history
  -- grew without bound (20260926042810).
  SELECT a.id,a.rake_record_id,a.hand_id,a.player_id,a.club_id,a.weighted_rake_credit
   FROM week_records w JOIN public.rake_attributions a ON a.rake_record_id=w.id
   WHERE a.club_id=p_club_id
 ), week_batches AS MATERIALIZED (
  SELECT b.rake_record_id,b.status FROM public.accounting_cash_accrual_batches b
   JOIN week_records w ON w.id=b.rake_record_id
 ), week_sources AS MATERIALIZED (
  -- A source can only be the PERFECT match the count below looks for if its
  -- club_id is this club and its earned_at is the record's created_at, which
  -- is inside the week by construction. Narrowing to the club-week slice
  -- therefore preserves every perfect match and every miss, and the existing
  -- accounting_cash_rake_sources_period index serves it directly instead of
  -- detoasting `contract` for the whole table.
  SELECT s.id,s.rake_record_id,s.player_id,s.club_id,s.earned_at,s.rake_credit,
   s.contract->>'attribution_id' AS c_attribution,s.contract->>'player_id' AS c_player,s.contract->>'club_id' AS c_club
   FROM public.accounting_cash_rake_sources s
   WHERE s.club_id=p_club_id AND s.earned_at>=v_from AND s.earned_at<v_to
 ), scoped_records AS (
  SELECT w.* FROM week_records w
   WHERE w.club_id=p_club_id
     OR EXISTS(SELECT 1 FROM club_attributions a WHERE a.rake_record_id=w.id)
     OR EXISTS(SELECT 1 FROM public.clubs house WHERE house.id=w.club_id AND house.is_union IS TRUE
        AND scope_union IS NOT NULL AND (house.union_id=scope_union OR house.id=scope_union))
 ), checks AS (
  SELECT r.id,r.hand_id,r.rake_amount,count(a.id) AS attribution_count,
    COALESCE(sum(a.weighted_rake_credit),0) AS attributed,
    count(a.id) FILTER(WHERE a.hand_id IS DISTINCT FROM r.hand_id OR a.club_id IS NULL
      OR a.player_id IS NULL OR a.weighted_rake_credit IS NULL OR a.weighted_rake_credit<0
      OR a.weighted_rake_credit<>round(a.weighted_rake_credit,2)
      -- NOT EXISTS(c WHERE id=a.club_id AND (P OR Q))
      --   = NOT EXISTS(c WHERE id=a.club_id AND P) AND NOT EXISTS(c WHERE id=a.club_id AND Q)
      OR (a.club_id NOT IN(SELECT c.id FROM public.clubs c WHERE c.is_union IS NOT TRUE)
       AND NOT EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=a.club_id AND c.is_union IS TRUE
        AND EXISTS(SELECT 1 FROM public.accounting_cash_rake_sources hs
          JOIN public.accounting_cash_accrual_batches hb ON hb.rake_record_id=hs.rake_record_id
          WHERE hs.rake_record_id=r.id AND hs.player_id=a.player_id AND hs.club_id=a.club_id
           AND hs.union_id=scope_union AND (c.id=hs.union_id OR c.union_id=hs.union_id)
           AND hs.earned_at=r.created_at AND hs.rake_credit=a.weighted_rake_credit AND hb.status='accrued'
           AND hs.contract->>'is_union_house'='true' AND hs.contract->>'attribution_id'=a.id::text
           AND hs.contract->>'club_id'=a.club_id::text AND hs.contract->>'player_id'=a.player_id::text
           AND hs.contract->>'union_id'=hs.union_id::text)))) AS invalid_count
   FROM scoped_records r LEFT JOIN public.rake_attributions a ON a.rake_record_id=r.id
   GROUP BY r.id,r.hand_id,r.rake_amount
 ), evidence AS (
  SELECT count(*) AS n FROM checks WHERE hand_id IS NULL OR attribution_count=0
   OR invalid_count>0 OR attributed<>rake_amount OR rake_amount<>round(rake_amount,2)
 ), incomplete AS (
  SELECT count(*) AS n FROM club_attributions a JOIN week_records r ON r.id=a.rake_record_id
   LEFT JOIN week_sources s ON s.rake_record_id=r.id AND s.player_id=a.player_id
   LEFT JOIN week_batches b ON b.rake_record_id=r.id
   WHERE s.id IS NULL OR b.status IS DISTINCT FROM 'accrued' OR s.club_id IS DISTINCT FROM a.club_id
     OR s.earned_at IS DISTINCT FROM r.created_at OR s.rake_credit IS DISTINCT FROM a.weighted_rake_credit
     OR s.c_attribution IS DISTINCT FROM a.id::text
     OR s.c_player IS DISTINCT FROM a.player_id::text OR s.c_club IS DISTINCT FROM a.club_id::text
 ), drifted AS (
  -- Bidirectional comparison also rejects an extra recorded source that no
  -- longer has an attribution. A matching subset is not a complete source set.
  SELECT count(*) AS n FROM public.accounting_cash_rake_sources s
   LEFT JOIN public.rake_records r ON r.id=s.rake_record_id
   LEFT JOIN public.rake_attributions a ON a.id=(s.contract->>'attribution_id')::uuid
   LEFT JOIN public.accounting_cash_accrual_batches b ON b.rake_record_id=s.rake_record_id
   WHERE s.club_id=p_club_id AND s.earned_at>=v_from AND s.earned_at<v_to
    AND (r.id IS NULL OR a.id IS NULL OR b.status IS DISTINCT FROM 'accrued'
     OR a.rake_record_id IS DISTINCT FROM s.rake_record_id OR a.hand_id IS DISTINCT FROM r.hand_id
     OR a.player_id IS DISTINCT FROM s.player_id OR a.club_id IS DISTINCT FROM s.club_id
     OR a.weighted_rake_credit IS DISTINCT FROM s.rake_credit OR s.earned_at IS DISTINCT FROM r.created_at
     OR r.is_tournament IS TRUE OR r.tournament_id IS NOT NULL
     OR NULLIF(s.contract->'union_id','null'::jsonb) IS DISTINCT FROM to_jsonb(s.union_id)
     OR NULLIF(s.contract->'coordinator_union_id','null'::jsonb) IS DISTINCT FROM to_jsonb(s.coordinator_union_id))
 )
 SELECT evidence.n,incomplete.n,drifted.n INTO evidence_issues,incomplete_issues,drifted_issues
   FROM evidence,incomplete,drifted;
 IF evidence_issues>0 THEN RETURN receipt||jsonb_build_object('reason','cash_earning_evidence_incomplete','source_count',evidence_issues); END IF;
 -- An old UTC or current-membership period remains an explicit conflict even
 -- when its numbers happen to match. Certificates establish the new writer.
 SELECT count(*) INTO issue_count FROM public.rakeback_periods rp
  WHERE rp.club_id=p_club_id AND rp.period_start<=p_period_end AND rp.period_end>=p_period_start AND public.fn_ca_launch_rakeback_period_waived(rp.id) IS NOT TRUE
    AND (rp.status<>'pending' OR rp.period_start<>p_period_start OR rp.period_end<>p_period_end
      OR NOT EXISTS(SELECT 1 FROM public.accounting_rakeback_period_calculations c WHERE c.period_id=rp.id));
 IF issue_count>0 THEN RETURN receipt||jsonb_build_object('reason','legacy_or_paid_period_requires_reconciliation','period_count',issue_count); END IF;
 IF incomplete_issues>0 THEN RETURN receipt||jsonb_build_object('reason','cash_source_receipts_incomplete','source_count',incomplete_issues); END IF;
 IF drifted_issues>0 THEN RETURN receipt||jsonb_build_object('reason','cash_source_receipts_drifted','source_count',drifted_issues); END IF;
 ELSE
 -- A PAGE READS ONLY THE EVIDENCE THAT CHANGED (20260930232349, re-derived from 20260927160709).
 -- The three week-level counts below are sums over the week's cash records.
 -- A record whose accrual batch exists is frozen: rake_records and
 -- rake_attributions refuse every change once it has one, and the batch and
 -- its sources are insert-only and written together. So its share of each
 -- count never changes while the clubs' union shape stays as it was. The
 -- checkpoint keeps those shares for every batch recorded before its horizon
 -- (a time no transaction still running had started by), and this page adds
 -- the batches recorded since and the records that have no batch yet, read in
 -- one snapshot. The totals are exactly the whole-week counts. The whole
 -- period call above keeps its own full verification.
 digest_now:=public.fn_accounting_clubs_scope_digest();
 SELECT * INTO evidence_cp FROM public.accounting_rakeback_period_evidence_checkpoints cp
  WHERE cp.club_id=p_club_id AND cp.period_start=p_period_start FOR UPDATE;
 IF FOUND AND evidence_cp.period_end=p_period_end AND evidence_cp.clubs_digest=digest_now THEN
  base_horizon:=evidence_cp.horizon;base_records:=evidence_cp.settled_records;
  base_evidence:=evidence_cp.settled_evidence;base_incomplete:=evidence_cp.settled_incomplete;base_drifted:=evidence_cp.settled_drifted;
 ELSE
  -- No checkpoint yet, or the union shape it was taken under has changed:
  -- start again from the week's first batch.
  base_horizon:='-infinity';base_records:=0;base_evidence:=0;base_incomplete:=0;base_drifted:=0;
 END IF;
 next_horizon:=public.fn_accounting_commit_horizon();
 IF next_horizon IS NULL OR next_horizon<base_horizon THEN next_horizon:=base_horizon; END IF;
 SELECT * INTO counts FROM public.fn_cash_period_evidence_since(p_club_id,v_from,v_to,scope_union,base_horizon,next_horizon);
 evidence_issues:=base_evidence+counts.o_evidence;
 incomplete_issues:=base_incomplete+counts.o_incomplete;
 drifted_issues:=base_drifted+counts.o_drifted;
 INSERT INTO public.accounting_rakeback_period_evidence_checkpoints AS cp(club_id,period_start,period_end,horizon,clubs_digest,
   settled_records,settled_evidence,settled_incomplete,settled_drifted)
  VALUES(p_club_id,p_period_start,p_period_end,next_horizon,digest_now,base_records+counts.o_settled_records,
   base_evidence+counts.o_settled_evidence,base_incomplete+counts.o_settled_incomplete,base_drifted+counts.o_settled_drifted)
  ON CONFLICT(club_id,period_start) DO UPDATE SET period_end=EXCLUDED.period_end,horizon=EXCLUDED.horizon,
   clubs_digest=EXCLUDED.clubs_digest,settled_records=EXCLUDED.settled_records,settled_evidence=EXCLUDED.settled_evidence,
   settled_incomplete=EXCLUDED.settled_incomplete,settled_drifted=EXCLUDED.settled_drifted,
   built_at=CASE WHEN base_horizon='-infinity'::timestamptz THEN clock_timestamp() ELSE cp.built_at END,
   advanced_at=clock_timestamp(),advances=cp.advances+1;
 -- Any of these refuses the page whatever the tournament gate says, so the
 -- gate is asked only when none does. Same reasons, counts and order as below.
 IF evidence_issues>0 THEN RETURN receipt||jsonb_build_object('reason','cash_earning_evidence_incomplete','source_count',evidence_issues); END IF;
 SELECT count(*) INTO issue_count FROM public.rakeback_periods rp
  WHERE rp.club_id=p_club_id AND rp.period_start<=p_period_end AND rp.period_end>=p_period_start AND public.fn_ca_launch_rakeback_period_waived(rp.id) IS NOT TRUE
    AND (rp.status<>'pending' OR rp.period_start<>p_period_start OR rp.period_end<>p_period_end
      OR NOT EXISTS(SELECT 1 FROM public.accounting_rakeback_period_calculations c WHERE c.period_id=rp.id));
 IF issue_count>0 THEN RETURN receipt||jsonb_build_object('reason','legacy_or_paid_period_requires_reconciliation','period_count',issue_count); END IF;
 IF incomplete_issues>0 THEN RETURN receipt||jsonb_build_object('reason','cash_source_receipts_incomplete','source_count',incomplete_issues); END IF;
 IF drifted_issues>0 THEN RETURN receipt||jsonb_build_object('reason','cash_source_receipts_drifted','source_count',drifted_issues); END IF;
 tournament_quality:=public.fn_accounting_tournament_week_quality(p_club_id,v_from,v_to);
 IF tournament_quality->>'status' IS DISTINCT FROM 'ready' THEN
  RETURN receipt||tournament_quality||jsonb_build_object('written',0);END IF;
 END IF;

 FOR player IN
  WITH receipts AS (
   SELECT s.source_type,s.source_id,s.rake_record_id,s.player_id,s.union_id,s.coordinator_union_id,s.earned_at,s.rake_credit,
    CASE WHEN s.source_type='tournament_fee_accrual' THEN public.fn_accounting_tournament_source_terms_at(fee.tournament_id,fee.charged_at,fee.contract) ELSE s.earned_at END AS agreement_at,
    s.contract->'membership'->'terms' AS member,s.contract->'tiers'->0 AS direct,
    (s.contract->'membership'->>'history_id')::bigint AS member_history_ref,
    sum(s.rake_credit) OVER(PARTITION BY s.player_id) AS total_rake
   FROM public.accounting_payable_earning_sources s
   -- A cash row has no fee row, and a NULL join key never enters the index.
   LEFT JOIN public.accounting_tournament_fee_sources fee
     ON fee.id=CASE WHEN s.source_type='tournament_fee_accrual' THEN s.source_id END
   WHERE s.club_id=p_club_id AND s.earned_at>=v_from AND s.earned_at<v_to
     AND (p_user_ids IS NULL OR s.player_id=ANY(p_user_ids))
  ), parsed AS (
   SELECT r.*,CASE WHEN ((r.member->>'player_rakeback_pct')::numeric=0.70 OR r.direct IS NULL) AND EXISTS(SELECT 1 FROM public.clubs owner_club WHERE owner_club.id=p_club_id AND owner_club.owner_id=NULLIF(r.member->>'agent_id','')::uuid) THEN NULL::uuid
     ELSE NULLIF(r.member->>'agent_id','')::uuid END AS member_agent,
    COALESCE((r.member->>'player_rakeback_pct')::numeric,0) AS deal,
    CASE WHEN NULLIF(r.member->>'agent_id','') IS NOT NULL
      THEN COALESCE((r.direct->'agreement'->'terms'->>'player_rakeback_rate')::numeric,0) ELSE 0 END AS offer,
    CASE WHEN NULLIF(r.member->>'agent_id','') IS NOT NULL THEN (r.direct->>'rate')::numeric END AS cap_rate,
    mh.id AS member_history_id,ah.id AS agent_history_id,
    mh.after_terms AS recorded_member,ah.after_terms AS recorded_agent
   FROM receipts r
   LEFT JOIN public.accounting_agreement_history mh ON mh.id=r.member_history_ref
    AND mh.entity_type='club_members' AND mh.entity_key=p_club_id::text||':'||r.player_id::text AND mh.observed_at<=r.agreement_at
   LEFT JOIN public.accounting_agreement_history ah ON ah.id=(r.direct->'agreement'->>'history_id')::bigint
    AND ah.entity_type='agents' AND ah.observed_at<=r.agreement_at
  ), rates AS (
   SELECT p.*,CASE WHEN COALESCE((p.member->>'player_rakeback_explicit')::boolean,false) OR p.deal>0 THEN p.deal WHEN p.member_agent IS NOT NULL THEN p.offer
    WHEN p.total_rake>=10000 THEN 0.30 WHEN p.total_rake>=2000 THEN 0.20
    WHEN p.total_rake>=500 THEN 0.15 WHEN p.total_rake>=100 THEN 0.10 ELSE 0.05 END AS base_rate
   FROM parsed p
  ), effective AS (
   SELECT r.*,CASE WHEN r.member_agent IS NULL AND r.deal=0.70 THEN r.deal WHEN r.cap_rate>0 THEN least(r.base_rate,greatest(r.cap_rate-0.10,0)) ELSE r.base_rate END AS applied_rate
   FROM rates r
  )
  SELECT e.player_id,max(e.total_rake) AS total_rake,sum(e.rake_credit*e.applied_rate) AS total_unrounded,
   count(*) FILTER(WHERE e.member_history_id IS NULL OR e.member IS DISTINCT FROM e.recorded_member
    OR e.member->>'club_id' IS DISTINCT FROM p_club_id::text OR e.member->>'user_id' IS DISTINCT FROM e.player_id::text
    OR COALESCE(e.member->>'status','') NOT IN('active','approved') OR e.member->>'is_active' IS DISTINCT FROM 'true') AS invalid_members,
   count(*) FILTER(WHERE e.member_agent IS NOT NULL AND (e.direct IS NULL OR e.agent_history_id IS NULL
    OR e.direct->'agreement'->'terms' IS DISTINCT FROM e.recorded_agent
    OR e.direct->>'user_id' IS DISTINCT FROM e.member_agent::text OR e.direct->>'depth' IS DISTINCT FROM '1'
    OR e.recorded_agent->>'club_id' IS DISTINCT FROM p_club_id::text OR e.recorded_agent->>'user_id' IS DISTINCT FROM e.member_agent::text
    OR e.recorded_agent->>'status' IS DISTINCT FROM 'active')) AS invalid_agents,
   count(*) FILTER(WHERE e.deal::text IN('NaN','Infinity','-Infinity') OR e.offer::text IN('NaN','Infinity','-Infinity')
    OR e.deal<0 OR e.deal>1 OR e.offer<0 OR e.offer>1
    OR (e.member_agent IS NOT NULL AND (e.cap_rate IS NULL OR e.cap_rate<0 OR e.cap_rate>1 OR e.cap_rate::text IN('NaN','Infinity','-Infinity')))) AS invalid_rates,
   count(DISTINCT COALESCE(e.member_agent::text,'club')) AS payer_count,
   count(DISTINCT COALESCE(e.coordinator_union_id::text,'standalone')) AS coordinator_count,
   min(e.member_agent::text)::uuid AS payer_user,
   min(e.coordinator_union_id::text)::uuid AS coordinator_union,
   jsonb_agg(jsonb_build_object('source_type',e.source_type,'source_id',e.source_id,'rake_record_id',e.rake_record_id,'union_id',e.union_id,
    'coordinator_union_id',e.coordinator_union_id,'rake_credit',e.rake_credit,'rate',e.applied_rate,
    'unrounded_rakeback',e.rake_credit*e.applied_rate,'earned_at',e.earned_at,'agreement_at',e.agreement_at,'membership_history_id',e.member_history_id,
    'agent_history_id',e.agent_history_id,'payer_kind',CASE WHEN e.member_agent IS NULL THEN 'club' ELSE 'agent' END,
    'payer_user_id',e.member_agent) ORDER BY e.earned_at,e.source_type,e.rake_record_id,e.source_id) AS allocations
  FROM effective e GROUP BY e.player_id ORDER BY e.player_id
 LOOP
  IF player.invalid_members>0 THEN RAISE EXCEPTION 'period_membership_contract_invalid' USING ERRCODE='55000'; END IF;
  IF player.invalid_agents>0 THEN RAISE EXCEPTION 'period_direct_agent_contract_invalid' USING ERRCODE='55000'; END IF;
  IF player.invalid_rates>0 THEN RAISE EXCEPTION 'period_observed_rate_invalid' USING ERRCODE='55000'; END IF;
  IF player.payer_count<1 THEN RAISE EXCEPTION 'historical_rakeback_payer_required' USING ERRCODE='55000'; END IF;
  IF player.coordinator_count<>1 THEN RAISE EXCEPTION 'multiple_recorded_coordinators_require_split_period' USING ERRCODE='55000'; END IF;
  total_unrounded:=player.total_unrounded;allocations:=player.allocations;payer_user:=CASE WHEN player.payer_count>1 THEN NULL ELSE player.payer_user END;coordinator_union:=player.coordinator_union;
  payer_kind:=CASE WHEN player.payer_count>1 THEN 'split' WHEN payer_user IS NULL THEN 'club' ELSE 'agent' END;
  amount:=round(total_unrounded,2);
  display_rate:=CASE WHEN player.total_rake>0 THEN round(total_unrounded/player.total_rake,4) ELSE 0 END;
  IF amount>player.total_rake OR amount<0 THEN RAISE EXCEPTION 'period_rakeback_not_conserved' USING ERRCODE='55000'; END IF;
  fingerprint:=md5(jsonb_build_object('allocations',allocations,'rake',player.total_rake,'amount',amount,'rate',display_rate)::text);
  plan:=jsonb_build_object('player_id',player.player_id,'rake_generated',player.total_rake,
   'rakeback_amount',amount,'display_rate',display_rate,'coordinator_union_id',coordinator_union,'payer_kind',payer_kind,'payer_user_id',payer_user,
   'source_fingerprint',fingerprint,'allocations',allocations);
  SELECT * INTO existing FROM public.rakeback_periods WHERE club_id=p_club_id AND user_id=(plan->>'player_id')::uuid
    AND period_start=p_period_start AND period_end=p_period_end FOR UPDATE;
  IF FOUND AND public.fn_ca_launch_rakeback_period_waived(existing.id) THEN
   period_id:=existing.id;
   UPDATE public.rakeback_periods SET status='pending',paid_at=NULL,deferred_reason=NULL,deferred_at=NULL,
    rake_generated=(plan->>'rake_generated')::numeric,total_rake_paid=(plan->>'rake_generated')::numeric,
    rakeback_rate=(plan->>'display_rate')::numeric,rakeback_earned=(plan->>'rakeback_amount')::numeric,rakeback_amount=(plan->>'rakeback_amount')::numeric
    WHERE id=period_id;
  ELSIF FOUND THEN
   SELECT * INTO certificate FROM public.accounting_rakeback_period_calculations cert WHERE cert.period_id=existing.id ORDER BY cert.id DESC LIMIT 1;
   IF NOT FOUND OR certificate.accounting_version<>2 OR certificate.club_id IS DISTINCT FROM p_club_id
    OR certificate.player_id IS DISTINCT FROM existing.user_id OR certificate.period_start IS DISTINCT FROM p_period_start
    OR certificate.period_end IS DISTINCT FROM p_period_end
    OR existing.status<>'pending' OR existing.rake_generated IS DISTINCT FROM certificate.rake_generated
    OR existing.total_rake_paid IS DISTINCT FROM certificate.rake_generated OR existing.rakeback_rate IS DISTINCT FROM certificate.display_rate
    OR existing.rakeback_earned IS DISTINCT FROM certificate.rakeback_amount OR existing.rakeback_amount IS DISTINCT FROM certificate.rakeback_amount
   THEN RAISE EXCEPTION 'certified_period_drift_requires_reconciliation' USING ERRCODE='55000'; END IF;
   period_id:=existing.id;
   IF certificate.source_fingerprint=plan->>'source_fingerprint' THEN PERFORM smarter_private.ensure_rakeback_payer_contracts(certificate.id); confirmed:=confirmed+1; CONTINUE; END IF;
   UPDATE public.rakeback_periods SET rake_generated=(plan->>'rake_generated')::numeric,total_rake_paid=(plan->>'rake_generated')::numeric,
    rakeback_rate=(plan->>'display_rate')::numeric,rakeback_earned=(plan->>'rakeback_amount')::numeric,rakeback_amount=(plan->>'rakeback_amount')::numeric
    WHERE id=period_id;
  ELSE
   INSERT INTO public.rakeback_periods(user_id,club_id,period_start,period_end,rake_generated,rakeback_rate,rakeback_earned,rakeback_amount,total_rake_paid,status)
    VALUES((plan->>'player_id')::uuid,p_club_id,p_period_start,p_period_end,(plan->>'rake_generated')::numeric,
     (plan->>'display_rate')::numeric,(plan->>'rakeback_amount')::numeric,(plan->>'rakeback_amount')::numeric,(plan->>'rake_generated')::numeric,'pending')
    RETURNING id INTO period_id;
  END IF;
  INSERT INTO public.accounting_rakeback_period_calculations(period_id,source_fingerprint,club_id,player_id,coordinator_union_id,period_start,period_end,
    rake_generated,rakeback_amount,display_rate,payer_kind,payer_user_id,source_allocations)
   VALUES(period_id,plan->>'source_fingerprint',p_club_id,(plan->>'player_id')::uuid,(plan->>'coordinator_union_id')::uuid,p_period_start,p_period_end,
    (plan->>'rake_generated')::numeric,(plan->>'rakeback_amount')::numeric,(plan->>'display_rate')::numeric,
    plan->>'payer_kind',(plan->>'payer_user_id')::uuid,plan->'allocations');
  written:=written+1;confirmed:=confirmed+1;
 END LOOP;
 RETURN receipt||jsonb_build_object('status','ready','written',written,'confirmed_players',confirmed);
EXCEPTION WHEN SQLSTATE '55000' THEN
 RETURN receipt||jsonb_build_object('reason',SQLERRM);
END $$;


