--
-- TOC entry 6714 (class 1255 OID 5352621)
-- Name: fn_can_view_post(uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_can_view_post(p_author_id uuid, p_audience_mode text, p_audience_list text[]) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_viewer uuid;
  v_mode text;
BEGIN
  v_viewer := auth.uid();
  v_mode := COALESCE(p_audience_mode, 'public');

  -- Author always sees their own posts.
  IF v_viewer IS NOT NULL AND v_viewer = p_author_id THEN
    RETURN TRUE;
  END IF;

  IF v_mode = 'public' THEN
    RETURN TRUE;
  END IF;

  -- All non-public modes require the viewer to be authenticated.
  IF v_viewer IS NULL THEN
    RETURN FALSE;
  END IF;

  IF v_mode = 'only_me' THEN
    RETURN FALSE; -- author already returned above
  END IF;

  IF v_mode = 'friends' THEN
    RETURN public.fn_are_friends(v_viewer, p_author_id);
  END IF;

  IF v_mode = 'friends_except' THEN
    -- audience_list holds excluded user ids
    RETURN public.fn_are_friends(v_viewer, p_author_id)
       AND NOT (v_viewer::text = ANY(COALESCE(p_audience_list, '{}'::text[])));
  END IF;

  IF v_mode IN ('specific', 'custom') THEN
    RETURN v_viewer::text = ANY(COALESCE(p_audience_list, '{}'::text[]));
  END IF;

  -- Unknown mode: fail closed.
  RETURN FALSE;
END;
$$;


ALTER FUNCTION public.fn_can_view_post(p_author_id uuid, p_audience_mode text, p_audience_list text[]) OWNER TO postgres;

--
-- TOC entry 3892 (class 1255 OID 25747005)
-- Name: fn_cancel_cash_seat_moves_on_table_close(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cancel_cash_seat_moves_on_table_close() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF (NEW.status = 'closed' AND OLD.status IS DISTINCT FROM 'closed')
     OR (NEW.seat_admission_key = 'closed' AND OLD.seat_admission_key IS DISTINCT FROM 'closed') THEN
    -- the moves that name this table, and the swap partners of those moves
    UPDATE public.cash_seat_moves m
       SET state = 'cancelled', note = 'table_closed'
     WHERE m.state = 'pending'
       AND (m.from_table_id = NEW.id OR m.to_table_id = NEW.id
            OR EXISTS (SELECT 1 FROM public.cash_seat_moves p
                        WHERE p.id = m.swap_move_id AND p.state = 'pending'
                          AND (p.from_table_id = NEW.id OR p.to_table_id = NEW.id)));
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_cancel_cash_seat_moves_on_table_close() OWNER TO postgres;

