--
-- TOC entry 4852 (class 1255 OID 34785502)
-- Name: fn_capture_accounting_tournament_fee(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_capture_accounting_tournament_fee(p_rake_record_id uuid, p_manifest jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
 r public.rake_records%ROWTYPE; t record; previous record; cutoff timestamptz;
 manifest jsonb; item jsonb; contributors jsonb:='[]'; contract jsonb;
 e record; l record; tp record; source_type text; expected_kind text;
 player uuid; club uuid; registration uuid; ledger_id uuid; entitlement_id uuid;
 actual_union uuid; charged_at timestamptz; weight numeric; total_weight numeric:=0;
 total_cents bigint; floor_total bigint; remainder_cents bigint; credit numeric;
 allocated numeric:=0; seen_players uuid[]:='{}'; seen_entitlements uuid[]:='{}';
 fingerprint text; result_ids uuid[]:='{}'; new_id uuid; n integer; row_plan record;
BEGIN
 -- Private EXECUTE grants are the boundary: this owner-only helper also runs
 -- inside a legitimate authenticated human's original charge transaction.
 SELECT * INTO r FROM public.rake_records WHERE id=p_rake_record_id FOR SHARE;
 IF NOT FOUND OR r.is_tournament IS DISTINCT FROM true OR r.tournament_id IS NULL
  OR r.hand_id IS NOT NULL OR r.rake_amount IS NULL OR r.rake_amount<=0
  OR r.rake_amount<>round(r.rake_amount,2) OR r.rake_amount::text IN('NaN','Infinity','-Infinity')
 THEN RAISE EXCEPTION 'positive_chip_tournament_fee_required' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('accounting_tournament_fee:'||r.id::text,0));
 fingerprint:=public.fn_accounting_tournament_fee_fingerprint(r);
 SELECT * INTO previous FROM public.accounting_tournament_fee_batches WHERE rake_record_id=r.id;
 IF FOUND THEN
  IF previous.source_fingerprint IS DISTINCT FROM fingerprint THEN
   RAISE EXCEPTION 'captured_tournament_fee_source_changed' USING ERRCODE='23514';
  END IF;
  SELECT array_agg(id ORDER BY player_id),count(*),sum(rake_credit)
   INTO result_ids,n,allocated FROM public.accounting_tournament_fee_sources WHERE rake_record_id=r.id;
  IF n=0 OR allocated IS DISTINCT FROM previous.rake_amount THEN
   RAISE EXCEPTION 'captured_tournament_fee_incomplete' USING ERRCODE='23514';
  END IF;
  RETURN jsonb_build_object('accounting_version',2,'status','captured','rake_record_id',r.id,
   'tournament_id',r.tournament_id,'source_ids',result_ids,'rake_credit',allocated,'replayed',true,'payable',false);
 END IF;
 SELECT starts_at INTO cutoff FROM public.accounting_tournament_fee_cutover WHERE singleton;
 IF cutoff IS NULL OR r.created_at<cutoff OR r.created_at IS DISTINCT FROM transaction_timestamp() THEN
  RAISE EXCEPTION 'tournament_fee_not_captured_by_original_producer' USING ERRCODE='55000';
 END IF;
 SELECT id,club_id,union_id,is_private,tournament_type INTO t FROM public.tournaments WHERE id=r.tournament_id FOR SHARE;
 IF NOT FOUND OR public.fn_poker_diamond_tournament(r.tournament_id) THEN
  RAISE EXCEPTION 'chip_tournament_fee_required' USING ERRCODE='23514';
 END IF;
 actual_union:=CASE WHEN t.is_private THEN NULL ELSE t.union_id END;
 manifest:=COALESCE(p_manifest,r.metadata->'accounting_fee_source');
 IF (p_manifest IS NULL AND r.metadata->>'accounting_source_version' IS DISTINCT FROM '2')
  OR jsonb_typeof(manifest) IS DISTINCT FROM 'object'
  OR NOT(manifest ? 'union_id')
  OR NULLIF(manifest->>'union_id','')::uuid IS DISTINCT FROM actual_union
  OR manifest->>'game_type' IS DISTINCT FROM lower(t.tournament_type)
  OR jsonb_typeof(manifest->'contributors') IS DISTINCT FROM 'array'
  OR jsonb_array_length(manifest->'contributors')=0
 THEN RAISE EXCEPTION 'tournament_fee_producer_manifest_required' USING ERRCODE='23514'; END IF;
 expected_kind:=CASE r.source
  WHEN 'fn_register_for_tournament' THEN 'tournament_entry_fee'
  WHEN 'fn_register_horse_for_tournament' THEN 'tournament_entry_fee'
  WHEN 'fn_award_satellite_seat' THEN 'satellite_seat_entry_fee'
  WHEN 'fn_register_for_tournament_with_ticket' THEN 'tournament_ticket_entry_fee'
  WHEN 'fn_spin_book_entry' THEN 'spin_rake'
  WHEN 'process_tournament_rebuy' THEN r.metadata->>'kind' END;
 IF expected_kind IS NULL OR r.metadata->>'kind' IS DISTINCT FROM expected_kind
  OR (r.source='process_tournament_rebuy' AND expected_kind NOT IN('tournament_rebuy_fee','tournament_reentry_fee'))
 THEN RAISE EXCEPTION 'tournament_fee_source_unsupported' USING ERRCODE='55000'; END IF;
 n:=jsonb_array_length(manifest->'contributors');
 IF (r.source='fn_spin_book_entry' AND n<>3) OR (r.source<>'fn_spin_book_entry' AND n<>1) THEN
  RAISE EXCEPTION 'tournament_fee_contributor_count_invalid' USING ERRCODE='23514';
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(manifest->'contributors') LOOP
  player:=(item->>'player_id')::uuid;club:=(item->>'club_id')::uuid;
  registration:=(item->>'registration_id')::uuid;ledger_id:=(item->>'charge_ledger_id')::uuid;
  entitlement_id:=(item->>'entitlement_id')::uuid;charged_at:=(item->>'charged_at')::timestamptz;
  weight:=(item->>'weight')::numeric;
  IF player IS NULL OR club IS NULL OR registration IS NULL OR ledger_id IS NULL OR entitlement_id IS NULL
   OR charged_at IS NULL OR NOT isfinite(charged_at) OR charged_at<cutoff OR charged_at>r.created_at
   OR weight IS NULL OR weight<=0 OR weight<>round(weight,2) OR weight::text IN('NaN','Infinity','-Infinity')
   OR player=ANY(seen_players) OR entitlement_id=ANY(seen_entitlements)
  THEN RAISE EXCEPTION 'tournament_fee_contributor_invalid' USING ERRCODE='23514'; END IF;
  seen_players:=array_append(seen_players,player);seen_entitlements:=array_append(seen_entitlements,entitlement_id);
  SELECT * INTO e FROM public.tournament_refund_entitlements WHERE id=entitlement_id;
  SELECT * INTO l FROM public.chip_ledger WHERE id=ledger_id;
  SELECT * INTO tp FROM public.tournament_players WHERE id=registration;
  IF e.id IS NULL OR l.id IS NULL OR tp.id IS NULL OR e.tournament_id IS DISTINCT FROM r.tournament_id
   OR e.user_id IS DISTINCT FROM player OR e.refund_wallet_club_id IS DISTINCT FROM club
   OR e.source_ledger_id IS DISTINCT FROM ledger_id OR e.created_at IS DISTINCT FROM charged_at
   OR tp.tournament_id IS DISTINCT FROM r.tournament_id OR tp.user_id IS DISTINCT FROM player OR tp.club_id IS DISTINCT FROM club
   OR l.created_at IS DISTINCT FROM charged_at OR l.amount IS DISTINCT FROM e.gross
  THEN RAISE EXCEPTION 'tournament_fee_charge_evidence_mismatch' USING ERRCODE='23514'; END IF;
  IF r.source='fn_spin_book_entry' THEN
   -- A Spin has one aggregate fee, three exact paid entries, and one immutable
   -- reserve contribution. Weights are paid entry amounts, never mutable rebuys.
   IF e.entitlement_kind IS DISTINCT FROM 'wallet_charge' OR e.charge_category IS DISTINCT FROM 'tournament_buyin'
    OR e.gross IS DISTINCT FROM weight OR l.from_type IS DISTINCT FROM 'player_wallet'
    OR l.from_entity_id IS DISTINCT FROM player OR l.to_type IS DISTINCT FROM 'prize_liability'
    OR l.to_entity_id IS DISTINCT FROM r.tournament_id OR l.club_id IS DISTINCT FROM club
    OR l.category IS DISTINCT FROM 'tournament_buyin'
    OR (r.player_contributions->>player::text)::numeric IS DISTINCT FROM weight
   THEN RAISE EXCEPTION 'spin_fee_charge_evidence_mismatch' USING ERRCODE='23514'; END IF;
  ELSE
   IF e.refund_fee IS DISTINCT FROM r.rake_amount OR weight IS DISTINCT FROM r.rake_amount
    OR r.metadata->>'user_id' IS DISTINCT FROM player::text
   THEN RAISE EXCEPTION 'tournament_fee_amount_evidence_mismatch' USING ERRCODE='23514'; END IF;
   IF r.source IN('fn_register_for_tournament','fn_register_horse_for_tournament','process_tournament_rebuy') THEN
    source_type:=CASE WHEN r.source='process_tournament_rebuy' THEN 'rebuy' ELSE 'tournament_buyin' END;
    IF e.entitlement_kind IS DISTINCT FROM 'wallet_charge' OR e.charge_category IS DISTINCT FROM source_type
     OR l.from_type IS DISTINCT FROM 'player_wallet' OR l.from_entity_id IS DISTINCT FROM player
     OR l.to_type IS DISTINCT FROM 'prize_liability' OR l.to_entity_id IS DISTINCT FROM r.tournament_id
     OR l.club_id IS DISTINCT FROM club OR l.category IS DISTINCT FROM source_type
     OR (r.source<>'process_tournament_rebuy' AND r.metadata->>'registration_id' IS DISTINCT FROM registration::text)
    THEN RAISE EXCEPTION 'tournament_fee_wallet_evidence_mismatch' USING ERRCODE='23514'; END IF;
   ELSIF r.source='fn_register_for_tournament_with_ticket' THEN
    IF e.entitlement_kind IS DISTINCT FROM 'tournament_ticket' OR e.registration_id IS DISTINCT FROM registration
     OR e.source_ticket_id IS NULL OR r.metadata->>'ticket_id' IS DISTINCT FROM e.source_ticket_id::text
     OR r.metadata->>'registration_id' IS DISTINCT FROM registration::text
     OR l.from_type IS DISTINCT FROM 'escrow' OR l.from_entity_id IS DISTINCT FROM e.source_ticket_id
     OR l.to_type IS DISTINCT FROM 'prize_liability' OR l.to_entity_id IS DISTINCT FROM r.tournament_id
     OR l.category IS DISTINCT FROM 'ticket_redeem'
    THEN RAISE EXCEPTION 'tournament_fee_ticket_evidence_mismatch' USING ERRCODE='23514'; END IF;
   ELSE
    IF e.entitlement_kind IS DISTINCT FROM 'satellite_seat' OR e.registration_id IS DISTINCT FROM registration
     OR e.source_satellite_id IS NULL OR r.metadata->>'satellite_id' IS DISTINCT FROM e.source_satellite_id::text
     OR r.metadata->>'registration_id' IS DISTINCT FROM registration::text
     OR l.from_type IS DISTINCT FROM 'prize_liability' OR l.from_entity_id IS DISTINCT FROM e.source_satellite_id
     OR l.to_type IS DISTINCT FROM 'prize_liability' OR l.to_entity_id IS DISTINCT FROM r.tournament_id
     OR l.category IS DISTINCT FROM 'tournament_buyin'
    THEN RAISE EXCEPTION 'tournament_fee_satellite_evidence_mismatch' USING ERRCODE='23514'; END IF;
   END IF;
  END IF;
  contributors:=contributors||jsonb_build_array(item);total_weight:=total_weight+weight;
 END LOOP;
 IF r.source='fn_spin_book_entry' THEN
  IF jsonb_typeof(r.player_contributions) IS DISTINCT FROM 'object'
   OR (SELECT count(*) FROM jsonb_object_keys(r.player_contributions))<>3
   OR (SELECT count(DISTINCT (x->>'weight')::numeric) FROM jsonb_array_elements(contributors)x)<>1
   OR NOT EXISTS(SELECT 1 FROM public.spin_reserve_ledger s
      WHERE s.id=(manifest->>'spin_reserve_id')::uuid AND s.tournament_id=r.tournament_id
       AND s.kind='contribution' AND s.seats=3 AND s.house_rake=r.rake_amount
       AND s.amount=total_weight-r.rake_amount AND s.buy_in=total_weight/3)
  THEN RAISE EXCEPTION 'spin_fee_reserve_evidence_mismatch' USING ERRCODE='23514'; END IF;
 END IF;
 total_cents:=(r.rake_amount*100)::bigint;
 SELECT sum(floor(total_cents*(x->>'weight')::numeric/total_weight)) INTO floor_total FROM jsonb_array_elements(contributors)x;
 remainder_cents:=total_cents-floor_total;
 INSERT INTO public.accounting_tournament_fee_batches(rake_record_id,tournament_id,source_fingerprint,rake_amount,source_manifest)
  VALUES(r.id,r.tournament_id,fingerprint,r.rake_amount,manifest);
 -- Largest remainder; UUID order breaks exact fractional ties reproducibly.
 FOR row_plan IN
  SELECT x, floor(total_cents*(x->>'weight')::numeric/total_weight)
    +CASE WHEN row_number() OVER(ORDER BY total_cents*(x->>'weight')::numeric/total_weight
       -floor(total_cents*(x->>'weight')::numeric/total_weight) DESC,x->>'player_id')<=remainder_cents THEN 1 ELSE 0 END cents
   FROM jsonb_array_elements(contributors)x ORDER BY x->>'player_id'
 LOOP
  item:=row_plan.x;credit:=row_plan.cents/100.0;
  contract:=public.fn_accounting_earning_contract((item->>'club_id')::uuid,(item->>'player_id')::uuid,
    credit,actual_union,(item->>'charged_at')::timestamptz);
  IF contract->>'player_id' IS DISTINCT FROM item->>'player_id' OR contract->>'club_id' IS DISTINCT FROM item->>'club_id'
   OR (contract->>'rake_credit')::numeric IS DISTINCT FROM credit
   OR NULLIF(contract->>'union_id','')::uuid IS DISTINCT FROM actual_union
   OR (contract->>'terms_at')::timestamptz IS DISTINCT FROM (item->>'charged_at')::timestamptz
  THEN RAISE EXCEPTION 'tournament_fee_contract_scope_mismatch' USING ERRCODE='23514'; END IF;
  INSERT INTO public.accounting_tournament_fee_sources(rake_record_id,tournament_id,player_id,club_id,union_id,
   coordinator_union_id,game_type,registration_id,source_charge_ledger_id,source_entitlement_id,charged_at,rake_credit,contract)
  VALUES(r.id,r.tournament_id,(item->>'player_id')::uuid,(item->>'club_id')::uuid,actual_union,
   NULLIF(contract->>'coordinator_union_id','')::uuid,manifest->>'game_type',(item->>'registration_id')::uuid,
   (item->>'charge_ledger_id')::uuid,(item->>'entitlement_id')::uuid,(item->>'charged_at')::timestamptz,credit,contract)
  RETURNING id INTO new_id;
  result_ids:=array_append(result_ids,new_id);allocated:=allocated+credit;
 END LOOP;
 IF allocated IS DISTINCT FROM r.rake_amount THEN RAISE EXCEPTION 'tournament_fee_credit_not_conserved' USING ERRCODE='23514'; END IF;
 RETURN jsonb_build_object('accounting_version',2,'status','captured','rake_record_id',r.id,
  'tournament_id',r.tournament_id,'source_ids',result_ids,'rake_credit',allocated,'replayed',false,'payable',false);
END $$;


ALTER FUNCTION public.fn_capture_accounting_tournament_fee(p_rake_record_id uuid, p_manifest jsonb) OWNER TO postgres;

--
-- TOC entry 4634 (class 1255 OID 171351900)
-- Name: fn_capture_club_messenger_admission(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_capture_club_messenger_admission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_active boolean; v_previous boolean:=false; v_assignment_changed boolean:=false;
BEGIN
 v_active:=NEW.is_active=true AND NEW.status IN ('active','approved') AND NEW.membership_lifecycle_status='active';
 IF TG_OP='UPDATE' THEN
  v_previous:=OLD.is_active=true AND OLD.status IN ('active','approved') AND OLD.membership_lifecycle_status='active';
  v_assignment_changed:=NEW.agent_id IS DISTINCT FROM OLD.agent_id;
 END IF;
 IF v_active AND (NOT v_previous OR v_assignment_changed) THEN
  INSERT INTO public.club_messenger_admissions(club_id,user_id,active) VALUES(NEW.club_id,NEW.user_id,true)
  ON CONFLICT(club_id,user_id) DO UPDATE SET generation=gen_random_uuid(),active=true,transaction_id=txid_current(),started_at=now();
 ELSIF NOT v_active THEN
  UPDATE public.club_messenger_admissions SET active=false WHERE club_id=NEW.club_id AND user_id=NEW.user_id;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_capture_club_messenger_admission() OWNER TO postgres;

--
-- TOC entry 4186 (class 1255 OID 4633266)
-- Name: fn_capture_home_weekly_snapshots(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_capture_home_weekly_snapshots() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_week_start date;
    v_captured   int := 0;
    v_group      RECORD;
    v_prev_snapshot RECORD;
BEGIN
    -- Monday of the current week
    v_week_start := date_trunc('week', CURRENT_DATE)::date;

    FOR v_group IN 
        SELECT * FROM commander_home_groups WHERE is_active = true
    LOOP
        SELECT * INTO v_prev_snapshot 
          FROM commander_home_group_weekly_snapshots
         WHERE group_id = v_group.id 
         ORDER BY week_start DESC LIMIT 1;

        INSERT INTO commander_home_group_weekly_snapshots (
            group_id, week_start,
            member_count, new_members,
            games_scheduled, games_completed, games_cancelled,
            total_rsvp_yes, total_checked_in, flake_count,
            post_count, view_count_delta, share_count_delta
        ) VALUES (
            v_group.id, v_week_start,
            COALESCE(v_group.member_count, 0),
            (SELECT COUNT(*) FROM commander_home_members 
              WHERE group_id = v_group.id AND created_at >= v_week_start - INTERVAL '7 days'),
            (SELECT COUNT(*) FROM commander_home_games 
              WHERE group_id = v_group.id AND created_at >= v_week_start - INTERVAL '7 days'),
            (SELECT COUNT(*) FROM commander_home_games 
              WHERE group_id = v_group.id AND status = 'completed' 
                AND updated_at >= v_week_start - INTERVAL '7 days'),
            (SELECT COUNT(*) FROM commander_home_games 
              WHERE group_id = v_group.id AND status = 'cancelled' 
                AND cancelled_at >= v_week_start - INTERVAL '7 days'),
            (SELECT COUNT(*) FROM commander_home_rsvps r 
              JOIN commander_home_games g ON g.id = r.game_id
              WHERE g.group_id = v_group.id AND r.response = 'yes'
                AND r.responded_at >= v_week_start - INTERVAL '7 days'),
            (SELECT COUNT(*) FROM commander_home_rsvps r 
              JOIN commander_home_games g ON g.id = r.game_id
              WHERE g.group_id = v_group.id AND r.checked_in_at >= v_week_start - INTERVAL '7 days'),
            (SELECT COUNT(*) FROM commander_home_rsvps r 
              JOIN commander_home_games g ON g.id = r.game_id
              WHERE g.group_id = v_group.id AND r.flaked = true
                AND r.updated_at >= v_week_start - INTERVAL '7 days'),
            (SELECT COUNT(*) FROM commander_home_posts 
              WHERE group_id = v_group.id AND created_at >= v_week_start - INTERVAL '7 days'),
            -- Deltas vs last snapshot
            GREATEST(0, COALESCE(v_group.view_count, 0) - COALESCE(v_prev_snapshot.view_count_delta, 0)),
            GREATEST(0, COALESCE(v_group.share_click_count, 0) - COALESCE(v_prev_snapshot.share_count_delta, 0))
        )
        ON CONFLICT (group_id, week_start) DO UPDATE SET
            member_count       = EXCLUDED.member_count,
            new_members        = EXCLUDED.new_members,
            games_scheduled    = EXCLUDED.games_scheduled,
            games_completed    = EXCLUDED.games_completed,
            games_cancelled    = EXCLUDED.games_cancelled,
            total_rsvp_yes     = EXCLUDED.total_rsvp_yes,
            total_checked_in   = EXCLUDED.total_checked_in,
            flake_count        = EXCLUDED.flake_count,
            post_count         = EXCLUDED.post_count,
            captured_at        = NOW();

        v_captured := v_captured + 1;
    END LOOP;

    RETURN jsonb_build_object('success', true, 'week_start', v_week_start, 'snapshots_captured', v_captured);
END;
$$;


ALTER FUNCTION public.fn_capture_home_weekly_snapshots() OWNER TO postgres;

--
-- TOC entry 4710 (class 1255 OID 18666912)
-- Name: fn_capture_managed_game_contract(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_capture_managed_game_contract() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_kind text := CASE TG_TABLE_NAME WHEN 'tables' THEN 'table' ELSE 'tournament' END;
  v_contract jsonb;
  v_hash text;
  v_last_hash text;
  v_version integer;
  v_sqlstate text;
  v_message text;
  v_dedupe text;
BEGIN
  IF v_kind = 'table' AND to_jsonb(NEW) -> 'tournament_id' <> 'null'::jsonb THEN
    RETURN NEW;
  END IF;

  v_contract := public.fn_managed_game_contract_document(v_kind, to_jsonb(NEW));

  -- ── NOTHING IN THE CONTRACT MOVED (2026-09-06) ───────────────────────────
  -- The engine and the cluster controller write `current_players`, `status`,
  -- `lifecycle`, `last_activity_at` and the lease columns thousands of times
  -- an hour, and every one of those is in the document's denylist. Comparing
  -- the documents is the same test the hash comparison below performs, minus
  -- the advisory lock and the indexed read - and it is derived from the
  -- document rather than from a second copy of the denylist, so it cannot
  -- drift the day a contract column is added.
  IF TG_OP = 'UPDATE'
     AND v_contract IS NOT DISTINCT FROM
         public.fn_managed_game_contract_document(v_kind, to_jsonb(OLD)) THEN
    RETURN NEW;
  END IF;

  -- ── THE CAPTURE CANNOT REFUSE THE WRITE IT DESCRIBES ─────────────────────
  BEGIN
    v_hash := public.fn_managed_game_contract_hash(v_contract);

    -- Updates of one physical row normally serialize already. This lock also
    -- protects repair/import paths that can publish the same logical game from
    -- separate statements before either has allocated its next version.
    PERFORM pg_advisory_xact_lock(hashtextextended(v_kind || ':' || NEW.id::text, 0));

    SELECT contract_hash, version
      INTO v_last_hash, v_version
      FROM public.managed_game_contract_versions
     WHERE game_kind = v_kind AND game_id = NEW.id
     ORDER BY version DESC
     LIMIT 1;

    IF v_last_hash IS NOT DISTINCT FROM v_hash THEN
      RETURN NEW;
    END IF;

    INSERT INTO public.managed_game_contract_versions (
      game_kind, game_id, club_id, union_id, version, contract,
      contract_hash, published_by, change_reason
    ) VALUES (
      v_kind, NEW.id, NEW.club_id, NEW.union_id, COALESCE(v_version, 0) + 1,
      v_contract, v_hash, auth.uid(),
      CASE
        WHEN TG_OP = 'INSERT' THEN 'created'
        WHEN auth.uid() IS NULL THEN 'system_revision'
        ELSE 'operator_revision'
      END
    );

    RETURN NEW;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
    v_dedupe := 'contract_capture:' || v_kind || ':' || coalesce(v_sqlstate, 'unknown');

    -- The handler must not be able to fail either. A detector that raises is
    -- the defect it was written to catch, one level up.
    BEGIN
      UPDATE public.ca_drift_incidents
         SET occurrences  = occurrences + 1,
             last_seen_at = now(),
             metadata     = metadata
                            || jsonb_build_object('last_game_id', NEW.id,
                                                  'message', v_message)
       WHERE source = 'managed_game_contract_capture'
         AND dedupe_key = v_dedupe
         AND status IN ('open', 'acknowledged', 'reconciling');
      IF NOT FOUND THEN
        -- `classification` and `layer` are CHECK-constrained enums, read off
        -- the live catalogue rather than guessed: 'contract_capture_failed'
        -- and 'schema' are in neither list, and writing them would have made
        -- this handler raise - the exact defect one level up.
        INSERT INTO public.ca_drift_incidents (
          source, dedupe_key, classification, severity, layer,
          club_id, union_id, entity_type, entity_id, suspected_cause, metadata
        ) VALUES (
          'managed_game_contract_capture', v_dedupe, 'unknown',
          'critical', 'projection',
          NEW.club_id, NEW.union_id, v_kind, NEW.id,
          'fn_capture_managed_game_contract raised ' || coalesce(v_sqlstate, '?') ||
            '. The game write SUCCEEDED; the contract version row is missing.',
          jsonb_build_object('sqlstate', v_sqlstate, 'message', v_message,
                             'game_kind', v_kind, 'first_game_id', NEW.id,
                             'tg_op', TG_OP)
        );
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL; -- the incident could not be filed; the WARNING below still speaks
    END;

    RAISE WARNING
      'managed game contract capture failed for % % (%): % - the % write was NOT refused; incident filed under source managed_game_contract_capture',
      v_kind, NEW.id, v_sqlstate, v_message, TG_TABLE_NAME;

    RETURN NEW;
  END;
END;
$$;


ALTER FUNCTION public.fn_capture_managed_game_contract() OWNER TO postgres;

--
-- TOC entry 46426 (class 0 OID 0)
-- Dependencies: 4710
-- Name: FUNCTION fn_capture_managed_game_contract(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_capture_managed_game_contract() IS 'Captures a managed-game contract version. NEVER raises: a failed capture files a ca_drift_incidents row under source managed_game_contract_capture and returns NEW, because an audit record must not be able to refuse the game write it describes (2026-09-06, after 683 refused cluster ticks in 65 minutes). Exits early when the contract document is unchanged, so the engine''s current_players/status churn costs no advisory lock.';


--
-- TOC entry 7770 (class 1255 OID 33305538)
-- Name: fn_capture_operational_source_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_capture_operational_source_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE k text;
BEGIN
  IF TG_TABLE_SCHEMA<>'public' OR TG_TABLE_NAME NOT IN ('engine_alerts','financial_alerts','ca_drift_incidents')
    OR TG_OP NOT IN ('INSERT','UPDATE') OR TG_WHEN<>'AFTER' OR TG_LEVEL<>'ROW'
    THEN RAISE EXCEPTION 'invalid operational source trigger binding'; END IF;
  k:=CASE TG_TABLE_NAME WHEN 'engine_alerts' THEN 'engine' WHEN 'financial_alerts' THEN 'financial' ELSE 'drift' END;
  IF TG_OP='UPDATE' AND to_jsonb(NEW)=to_jsonb(OLD) THEN RETURN NEW; END IF;
  IF k='engine' THEN
    IF TG_OP='UPDATE' THEN PERFORM operational_source_intake.record_strict(k,to_jsonb(OLD),'update_old'); END IF;
    PERFORM operational_source_intake.record_strict(k,to_jsonb(NEW),CASE WHEN TG_OP='INSERT' THEN 'insert' ELSE 'update_new' END);
  ELSE
    IF TG_OP='UPDATE' THEN PERFORM operational_source_intake.preserve(k,to_jsonb(OLD),'update_old'); END IF;
    PERFORM operational_source_intake.preserve(k,to_jsonb(NEW),CASE WHEN TG_OP='INSERT' THEN 'insert' ELSE 'update_new' END);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_capture_operational_source_event() OWNER TO postgres;

--
-- TOC entry 6043 (class 1255 OID 32671312)
-- Name: fn_capture_owner_notification_destination(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_capture_owner_notification_destination() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF public.fn_is_owner_operational_notification(NEW.user_id,NEW.type,NEW.title,NEW.data) THEN
    INSERT INTO public.operational_notification_destinations(notification_id,recipient_user_id,original_notification)
      VALUES(NEW.id,NEW.user_id,to_jsonb(NEW));
    PERFORM public.fn_try_record_owner_notification(NEW.id);
    -- Preserve the original row byte-for-byte, including _push. The DB mirror
    -- predicate below and gateway destination branch suppress personal sends.
    -- This also lets the existing administrative reader recover the same exact
    -- original if the first recorder attempt failed.
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_capture_owner_notification_destination() OWNER TO postgres;

--
-- TOC entry 5990 (class 1255 OID 32671321)
-- Name: fn_capture_owner_notification_history(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_capture_owner_notification_history(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    SET statement_timeout TO '8s'
    AS $$
DECLARE n public.notifications%ROWTYPE; d record; added integer:=0; recorded integer:=0;
BEGIN
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'expected bounded limit 1..200';
  END IF;
  FOR n IN SELECT x.* FROM public.notifications x
    WHERE x.user_id='47965354-0e56-43ef-931c-ddaab82af765'::uuid
      AND public.fn_is_owner_operational_notification(x.user_id,x.type,x.title,x.data)
      AND NOT EXISTS (SELECT 1 FROM public.operational_notification_destinations y WHERE y.notification_id=x.id)
    ORDER BY x.created_at,x.id LIMIT p_limit
  LOOP
    INSERT INTO public.operational_notification_destinations(notification_id,recipient_user_id,original_notification)
      VALUES(n.id,n.user_id,to_jsonb(n)) ON CONFLICT(notification_id) DO NOTHING;
    added:=added+1;
  END LOOP;
  FOR d IN SELECT notification_id FROM public.operational_notification_destinations
    WHERE inbox_event_id IS NULL
    ORDER BY last_attempt_at NULLS FIRST,captured_at,notification_id LIMIT p_limit
    FOR UPDATE SKIP LOCKED
  LOOP
    IF public.fn_try_record_owner_notification(d.notification_id) IS NOT NULL THEN recorded:=recorded+1; END IF;
  END LOOP;
  RETURN jsonb_build_object('candidates_seen',added,'inbox_receipts_recorded',recorded,
    'pending',EXISTS(SELECT 1 FROM public.operational_notification_destinations WHERE inbox_event_id IS NULL),
    'uncaptured',EXISTS(SELECT 1 FROM public.notifications x
      WHERE x.user_id='47965354-0e56-43ef-931c-ddaab82af765'::uuid
        AND public.fn_is_owner_operational_notification(x.user_id,x.type,x.title,x.data)
        AND NOT EXISTS(SELECT 1 FROM public.operational_notification_destinations captured WHERE captured.notification_id=x.id)));
END;
$$;


ALTER FUNCTION public.fn_capture_owner_notification_history(p_limit integer) OWNER TO postgres;

--
-- TOC entry 7765 (class 1255 OID 21337158)
-- Name: fn_card_slide_adoption(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_card_slide_adoption(p_days integer DEFAULT 7) RETURNS TABLE(days integer, users_with_setting_on bigint, users_with_setting_off bigint, active_users bigint, peels_started bigint, peels_committed bigint, peels_abandoned bigint, keyboard_opens bigint, commit_rate numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_days integer := LEAST(GREATEST(COALESCE(p_days, 7), 1), 90);
  v_caller uuid := auth.uid();
BEGIN
  -- Two statements, and both are load-bearing. There is no session -> there is
  -- no answer; and a session that is not a platform admin gets an empty result
  -- rather than an error, because an authenticated non-admin opening an admin
  -- panel is a UI state, not an incident.
  IF v_caller IS NULL THEN
    RETURN;
  END IF;
  IF NOT public.fn_is_platform_admin() THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH usage AS (
    SELECT
      COUNT(DISTINCT u.user_id) AS active_users,
      COALESCE(SUM(u.peels_started), 0) AS started,
      COALESCE(SUM(u.peels_committed), 0) AS committed,
      COALESCE(SUM(u.peels_abandoned), 0) AS abandoned,
      COALESCE(SUM(u.keyboard_opens), 0) AS keyboard
    FROM public.card_slide_usage u
    WHERE u.day >= (now() AT TIME ZONE 'utc')::date - v_days
  ),
  setting AS (
    SELECT
      COUNT(*) FILTER (WHERE s.card_slide) AS on_count,
      COUNT(*) FILTER (WHERE NOT s.card_slide) AS off_count
    FROM public.user_table_settings s
  )
  SELECT
    v_days,
    setting.on_count,
    setting.off_count,
    usage.active_users,
    usage.started,
    usage.committed,
    usage.abandoned,
    usage.keyboard,
    CASE WHEN usage.started > 0
      THEN ROUND((usage.committed::numeric / usage.started) * 100, 1)
      ELSE NULL
    END
  FROM usage, setting;
END $$;


ALTER FUNCTION public.fn_card_slide_adoption(p_days integer) OWNER TO postgres;

--
-- TOC entry 8482 (class 1255 OID 35348682)
-- Name: fn_cash_accept_hand_provenance(uuid, bigint, uuid, jsonb, numeric, numeric, numeric, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_accept_hand_provenance(p_table uuid, p_number bigint, p_hand uuid, p_stacks jsonb, p_rake numeric, p_bbj numeric, p_inflow numeric, p_hash text, p_request jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE m public.cash_hand_participant_manifests%ROWTYPE; x jsonb; y jsonb; v_id uuid;
 v_atomic jsonb; v_claim jsonb; v_settlement jsonb; v_stack_hand uuid;
 v_n integer; v_count integer; v_delta numeric:=0; v_people jsonb:='[]'; v_issues jsonb:='[]'; v_tournament uuid;
BEGIN
 IF p_request IS NULL OR p_request->'stacks' IS DISTINCT FROM p_stacks
  OR p_request->>'table_id' IS DISTINCT FROM p_table::text
  OR p_request->>'hand_number' IS DISTINCT FROM p_number::text
  OR encode(extensions.digest(convert_to(p_request::text,'UTF8'),'sha256'),'hex') IS DISTINCT FROM p_hash THEN
  RAISE EXCEPTION 'Original cash accepted request hash mismatch' USING ERRCODE='23514'; END IF;
 SELECT tournament_id INTO v_tournament FROM public.tables WHERE id=p_table;
 IF v_tournament IS NOT NULL THEN RETURN; END IF;
 -- DIAMOND PHASE 9, STEP 0: a Diamond hand is receipted by its own settler
 -- (poker_diamond_hand_receipts) and has no chip settlement claim to prove.
 IF EXISTS (SELECT 1 FROM public.tables t JOIN public.clubs c ON c.id=t.club_id
             WHERE t.id=p_table AND c.asset='diamonds') THEN RETURN; END IF;
 -- Keep original accounting proof independently of the seven-day game-history retention.
 SELECT to_jsonb(a) INTO STRICT v_atomic FROM public.hand_atomic_commits a
  WHERE a.table_id=p_table AND a.hand_number=p_number AND a.hand_id=p_hand AND a.payload_hash=p_hash;
 v_stack_hand:=(v_atomic->'stack_result'->>'hand_id')::uuid;
 SELECT to_jsonb(k) INTO STRICT v_claim FROM public.settlement_idempotency_keys k
  WHERE k.table_id=p_table AND k.hand_id=v_stack_hand AND k.status='succeeded'
   AND k.completed_at IS NOT NULL AND k.result=v_atomic->'stack_result';
 SELECT to_jsonb(c) INTO STRICT v_settlement FROM public.ca_settlements c
  WHERE c.table_id=p_table AND c.hand_id=v_stack_hand AND c.settlement_type='hand_stacks' AND c.state='final';
 SELECT count(DISTINCT value->>'funding_manifest_id'),count(*) FILTER(WHERE value->>'funding_manifest_id' IS NOT NULL)
 INTO v_n,v_count FROM jsonb_array_elements(p_stacks);
 IF v_count=0 THEN
  INSERT INTO public.cash_hand_provenance_receipts(table_id,hand_number,hand_id,payload_hash,accepted_request,atomic_receipt,stack_claim,stack_settlement,status,participants,
   signed_external_net,rake,bbj,all_players_included,funding_provenance_complete,issues)
  VALUES(p_table,p_number,p_hand,p_hash,p_request,v_atomic,v_claim,v_settlement,'uncertified',p_stacks,p_inflow,p_rake,p_bbj,false,false,
   '["original_dealt_manifest_missing"]');
  RETURN;
 END IF;
 IF v_n<>1 OR v_count<>jsonb_array_length(p_stacks) THEN
  RAISE EXCEPTION 'Incomplete or conflicting cash manifest references' USING ERRCODE='23514'; END IF;
 v_id:=(p_stacks->0->>'funding_manifest_id')::uuid;
 SELECT * INTO STRICT m FROM public.cash_hand_participant_manifests WHERE id=v_id AND table_id=p_table AND hand_number=p_number;
 IF jsonb_array_length(m.participants)<>jsonb_array_length(p_stacks) THEN
  RAISE EXCEPTION 'Cash manifest participant set mismatch' USING ERRCODE='23514'; END IF;
 IF (SELECT count(DISTINCT value->>'user_id') FROM jsonb_array_elements(p_stacks))<>jsonb_array_length(p_stacks) THEN
  RAISE EXCEPTION 'Duplicate cash manifest participant' USING ERRCODE='23514'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(m.participants) LOOP
  SELECT value INTO y FROM jsonb_array_elements(p_stacks) WHERE value->>'user_id'=x->>'user_id';
  IF y IS NULL OR y->>'seat_id' IS DISTINCT FROM x->>'seat_id'
   OR (y->>'seat_joined_at')::timestamptz IS DISTINCT FROM (x->>'seat_joined_at')::timestamptz
   OR y->>'occupancy_id' IS DISTINCT FROM x->>'occupancy_id'
   OR (y->>'stack_before')::numeric IS DISTINCT FROM (x->>'stack_before')::numeric
   OR jsonb_typeof(y->'stack') IS DISTINCT FROM 'number'
   OR (y->>'stack')::numeric<0 OR (y->>'stack')::numeric<>round((y->>'stack')::numeric,2)
   OR y->>'stack' IN ('NaN','Infinity','-Infinity') THEN
   RAISE EXCEPTION 'Cash manifest original participant mismatch' USING ERRCODE='23514'; END IF;
  v_delta:=v_delta+(y->>'stack')::numeric-(x->>'stack_before')::numeric;
  v_people:=v_people||jsonb_build_array(x||jsonb_build_object('stack_after',y->'stack',
   'poker_delta',(y->>'stack')::numeric-(x->>'stack_before')::numeric));
 END LOOP;
 IF coalesce(p_rake,0)::text IN ('NaN','Infinity','-Infinity')
  OR coalesce(p_bbj,0)::text IN ('NaN','Infinity','-Infinity')
  OR coalesce(p_inflow,0)::text IN ('NaN','Infinity','-Infinity')
  OR coalesce(p_rake,0)<>round(coalesce(p_rake,0),2)
  OR coalesce(p_bbj,0)<>round(coalesce(p_bbj,0),2)
  OR coalesce(p_inflow,0)<>round(coalesce(p_inflow,0),2)
  OR coalesce(p_rake,0)<0 OR coalesce(p_bbj,0)<0
  OR v_delta+coalesce(p_rake,0)+coalesce(p_bbj,0) IS DISTINCT FROM coalesce(p_inflow,0) THEN
  RAISE EXCEPTION 'Cash manifest signed conservation mismatch' USING ERRCODE='23514'; END IF;
 v_issues:=m.issues;
 -- A signed net is conserved, but external-bank linkage and commercial terms
 -- must still be proven separately. Captured funding is not whole-period PNL.
 IF coalesce(p_inflow,0)<>0 THEN v_issues:=v_issues||'"external_bank_receipt_not_certified"'::jsonb; END IF;
 INSERT INTO public.cash_hand_provenance_receipts(table_id,hand_number,hand_id,payload_hash,accepted_request,atomic_receipt,stack_claim,stack_settlement,manifest_id,status,
  game_scope,participants,signed_external_net,rake,bbj,all_players_included,funding_provenance_complete,issues)
 VALUES(p_table,p_number,p_hand,p_hash,p_request,v_atomic,v_claim,v_settlement,v_id,CASE WHEN jsonb_array_length(v_issues)=0 THEN 'captured' ELSE 'uncertified' END,
  m.game_scope,v_people,coalesce(p_inflow,0),coalesce(p_rake,0),coalesce(p_bbj,0),true,m.funding_provenance_complete,v_issues);
END $$;


ALTER FUNCTION public.fn_cash_accept_hand_provenance(p_table uuid, p_number bigint, p_hand uuid, p_stacks jsonb, p_rake numeric, p_bbj numeric, p_inflow numeric, p_hash text, p_request jsonb) OWNER TO postgres;

--
-- TOC entry 3580 (class 1255 OID 21224028)
-- Name: fn_cash_apply_ruleset(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_apply_ruleset(p_game_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g record; s jsonb; v_opts jsonb;
  v_ante text; v_ante_chips numeric; v_vpip integer; v_vpip_window integer;
  v_bomb_on boolean; v_bomb_trigger text; v_bomb_ante integer; v_bomb_boards integer;
  v_min_bb integer; v_max_bb integer;
  v_trigger_mode text; v_interval integer; v_action_secs integer;
  v_rit text; v_rit_mode text; v_rit_on boolean; v_sd boolean;
  v_n integer := 0;
  v_kill_mode text; v_kill_bb smallint;
BEGIN
  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id;
  IF NOT FOUND THEN RETURN 0; END IF;
  IF EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=g.club_id AND c.asset='diamonds') THEN
    RETURN public.fn_poker_diamond_project_cluster(g.id,NULL);
  END IF;
  s := g.ruleset_snapshot;
  IF s IS NULL THEN RETURN 0; END IF;

  -- The same mapping fn_cash_cluster_open_table applies at open. Kept in
  -- one place by construction: the opener's INSERT and this UPDATE must read
  -- the snapshot identically or a fresh table and a reconciled one disagree.
  v_opts := coalesce(s->'options', '{}'::jsonb);
  v_ante := coalesce(s->>'regular_ante', 'none');
  v_ante_chips := CASE v_ante WHEN 'sb' THEN g.sb WHEN 'bb' THEN g.bb ELSE 0 END;
  v_vpip := coalesce((s->>'vpip_floor')::integer, 0);
  v_vpip_window := coalesce((s->>'vpip_window')::integer, 10);
  v_bomb_on := coalesce((s->'bombs'->>'enabled')::boolean, false);
  v_bomb_trigger := s->'bombs'->>'trigger';
  v_bomb_ante := (s->'bombs'->>'ante_bb')::integer;
  v_bomb_boards := (s->'bombs'->>'boards')::integer;
  v_min_bb := coalesce((s->>'min_buyin_bb')::integer, 40);
  v_max_bb := coalesce((s->>'max_buyin_bb')::integer, 200);
  v_trigger_mode := CASE WHEN v_bomb_on AND v_bomb_trigger IN ('timed_10m', 'timed_15m', 'timed_20m') THEN 'timed'
                         WHEN v_bomb_on AND v_bomb_trigger = 'every_orbit' THEN 'once_per_orbit'
                         ELSE 'every_n_hands' END;
  v_interval := CASE WHEN NOT v_bomb_on THEN NULL
                     WHEN v_bomb_trigger = 'timed_10m' THEN 600
                     WHEN v_bomb_trigger = 'timed_15m' THEN 900
                     WHEN v_bomb_trigger = 'timed_20m' THEN 1200
                     ELSE NULL END;
  v_action_secs := LEAST(120, GREATEST(10, coalesce((v_opts->>'action_time_seconds')::integer, 15)));
  -- RUN IT N TIMES (2026-09-09, lane E audit): the opener projects the
  -- snapshot's run_it_n_times as run_it_mode + the three RIT booleans and
  -- this function never did, so the 42 tables adopted at the Gate 7 cutover
  -- kept the old form's answer - four tables of one game offering
  -- run-it-twice and the fifth not. The snapshot only ever says 'opt_in'
  -- today; the other spellings are mapped rather than defaulted so a future
  -- writer cannot land 'none' by accident.
  v_rit := lower(coalesce(s->>'run_it_n_times', 'opt_in'));
  v_rit_mode := CASE v_rit
                  WHEN 'opt_in' THEN 'player_choice'
                  WHEN 'player_choice' THEN 'player_choice'
                  WHEN 'mandatory_twice' THEN 'mandatory_twice'
                  WHEN 'mandatory_three' THEN 'mandatory_three'
                  ELSE 'none' END;
  v_rit_on := v_rit_mode <> 'none';
  -- 7-2 IS A HOLD'EM BOUNTY. The create path guards it ("AND v_v = 'nlh'");
  -- the projection guards it too so no other snapshot writer can put a
  -- seven-deuce bounty on an Omaha table.
  v_sd := coalesce((v_opts->>'seven_deuce_enabled')::boolean, false) AND g.variant = 'nlh';
  -- KILL POTS (kill-v1, 20260924034010). Exactly the opener's projection:
  -- 'off' whenever the kill would be refused at this game's tables, so a
  -- tick never fails on a kill setting and a demoted capability turns the
  -- whole game off together rather than one table at a time.
  v_kill_bb := CASE WHEN (s->'kill'->>'threshold_bb') IN ('8','10','12','15')
                    THEN (s->'kill'->>'threshold_bb')::smallint ELSE 10 END;
  v_kill_mode := lower(coalesce(s->'kill'->>'mode', 'off'));
  IF v_kill_mode NOT IN ('half', 'full') THEN
    v_kill_mode := 'off';
  ELSIF public.fn_kill_pot_configuration_refusal(v_kill_mode, g.variant, 'cash', NULL, v_bomb_on, g.bb, g.club_id) IS NOT NULL THEN
    v_kill_mode := 'off';
  ELSIF NOT public.fn_capability_available('cash.fixed_limit.kill_pots') THEN
    v_kill_mode := 'off';
  END IF;

  UPDATE public.tables t
     SET ante_enabled = v_ante_chips > 0,
         ante = v_ante_chips,
         ante_bb = CASE WHEN v_ante_chips > 0 THEN round(v_ante_chips / g.bb, 4) ELSE 0 END,
         big_blind_ante_enabled = (v_ante = 'bb'),
         nit_game = v_vpip > 0,
         career_percent_min = 0,
         maintain_percent_min = v_vpip,
         maintain_hands = v_vpip_window,
         bomb_pot_enabled = v_bomb_on,
         bomb_pot_trigger_mode = v_trigger_mode,
         bomb_pot_interval_seconds = v_interval,
         bomb_pot_frequency = 0,
         bomb_pot_ante_multiplier = coalesce(v_bomb_ante, 2),
         bomb_pot_board_count = coalesce(v_bomb_boards, 1),
         bomb_pot_double_board = coalesce(v_bomb_boards, 1) >= 2,
         bomb_pot_min_players = 2,
         min_buy_in = round(g.bb * v_min_bb, 2),
         max_buy_in = round(g.bb * v_max_bb, 2),
         -- THE CEILING IS THE GAME'S HANDEDNESS, BUT NEVER BELOW AN
         -- OCCUPIED CHAIR (2026-09-09). Two PLO5 Classic tables carried
         -- max_players 7 on a 6-handed game and one had a player in seat
         -- 7; the ceiling follows the seats down at the first tick AFTER
         -- that chair empties, so nobody is closed out of a seat.
         max_players = GREATEST(g.handedness,
                                coalesce((SELECT max(ts.seat_number) FROM public.table_seats ts
                                           WHERE ts.table_id = t.id AND ts.left_at IS NULL), 0)),
         stakes = public.fn_cash_stakes_label(g.sb, g.bb, g.variant),
         small_blind = g.sb, big_blind = g.bb, game_variant = g.variant,
         straddle_enabled = false, auto_utg_straddle = false, voluntary_straddle = false,
         run_it_mode = v_rit_mode,
         run_it_twice = v_rit_on,
         allow_run_it_twice = v_rit_on,
         run_it_twice_enabled = v_rit_on,
         is_private = coalesce((v_opts->>'is_private')::boolean, false),
         is_vip_only = coalesce((v_opts->>'is_vip_only')::boolean, false),
         is_anonymous = coalesce((v_opts->>'is_anonymous')::boolean, false),
         ban_chat = coalesce((v_opts->>'ban_chat')::boolean, false),
         insurance_enabled = coalesce((v_opts->>'insurance_enabled')::boolean, false),
         seven_deuce_enabled = v_sd,
         seven_deuce_amount = CASE WHEN v_sd THEN 2 ELSE 0 END,
         action_time_seconds = v_action_secs,
         kill_mode = v_kill_mode,
         kill_threshold_bb = v_kill_bb,
         updated_at = now()
   WHERE t.cluster_id = g.id
     AND t.lifecycle <> 'closed'
     AND coalesce(t.is_deleted, false) = false
     AND (
          t.ante_enabled IS DISTINCT FROM (v_ante_chips > 0)
       OR t.ante IS DISTINCT FROM v_ante_chips
       OR t.ante_bb IS DISTINCT FROM (CASE WHEN v_ante_chips > 0 THEN round(v_ante_chips / g.bb, 4) ELSE 0 END)
       OR t.big_blind_ante_enabled IS DISTINCT FROM (v_ante = 'bb')
       OR t.nit_game IS DISTINCT FROM (v_vpip > 0)
       OR t.maintain_percent_min IS DISTINCT FROM v_vpip
       OR t.maintain_hands IS DISTINCT FROM v_vpip_window
       OR t.bomb_pot_enabled IS DISTINCT FROM v_bomb_on
       OR t.bomb_pot_trigger_mode IS DISTINCT FROM v_trigger_mode
       OR t.bomb_pot_interval_seconds IS DISTINCT FROM v_interval
       OR t.bomb_pot_ante_multiplier IS DISTINCT FROM coalesce(v_bomb_ante, 2)
       OR t.bomb_pot_board_count IS DISTINCT FROM coalesce(v_bomb_boards, 1)
       OR t.bomb_pot_double_board IS DISTINCT FROM (coalesce(v_bomb_boards, 1) >= 2)
       OR t.bomb_pot_min_players IS DISTINCT FROM 2
       OR t.min_buy_in IS DISTINCT FROM round(g.bb * v_min_bb, 2)
       OR t.max_buy_in IS DISTINCT FROM round(g.bb * v_max_bb, 2)
       OR t.max_players IS DISTINCT FROM GREATEST(g.handedness,
                                coalesce((SELECT max(ts.seat_number) FROM public.table_seats ts
                                           WHERE ts.table_id = t.id AND ts.left_at IS NULL), 0))
       OR t.stakes IS DISTINCT FROM public.fn_cash_stakes_label(g.sb, g.bb, g.variant)
       OR t.small_blind IS DISTINCT FROM g.sb
       OR t.big_blind IS DISTINCT FROM g.bb
       OR t.game_variant IS DISTINCT FROM g.variant
       OR t.career_percent_min IS DISTINCT FROM 0
       OR coalesce(t.straddle_enabled, false) OR coalesce(t.auto_utg_straddle, false) OR coalesce(t.voluntary_straddle, false)
       OR t.run_it_mode IS DISTINCT FROM v_rit_mode
       OR t.run_it_twice IS DISTINCT FROM v_rit_on
       OR t.allow_run_it_twice IS DISTINCT FROM v_rit_on
       OR t.run_it_twice_enabled IS DISTINCT FROM v_rit_on
       OR t.is_private IS DISTINCT FROM coalesce((v_opts->>'is_private')::boolean, false)
       OR t.is_vip_only IS DISTINCT FROM coalesce((v_opts->>'is_vip_only')::boolean, false)
       OR t.is_anonymous IS DISTINCT FROM coalesce((v_opts->>'is_anonymous')::boolean, false)
       OR t.ban_chat IS DISTINCT FROM coalesce((v_opts->>'ban_chat')::boolean, false)
       OR t.insurance_enabled IS DISTINCT FROM coalesce((v_opts->>'insurance_enabled')::boolean, false)
       OR t.seven_deuce_enabled IS DISTINCT FROM v_sd
       OR t.seven_deuce_amount IS DISTINCT FROM (CASE WHEN v_sd THEN 2 ELSE 0 END)
       OR t.action_time_seconds IS DISTINCT FROM v_action_secs
       OR t.kill_mode IS DISTINCT FROM v_kill_mode
       OR t.kill_threshold_bb IS DISTINCT FROM v_kill_bb
     );
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN
    INSERT INTO public.cash_cluster_events (game_id, kind, payload)
    VALUES (g.id, 'ruleset_applied',
            jsonb_build_object('tables', v_n, 'vpip_floor', v_vpip, 'vpip_window', v_vpip_window,
                               'ante', v_ante, 'bombs', v_bomb_on, 'bomb_trigger', v_trigger_mode,
                               'rit', v_rit_mode, 'kill', v_kill_mode));
  END IF;
  RETURN v_n;
END;
$$;


ALTER FUNCTION public.fn_cash_apply_ruleset(p_game_id uuid) OWNER TO postgres;

--
-- TOC entry 4396 (class 1255 OID 35458029)
-- Name: fn_cash_atomic_original_matches(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_atomic_original_matches(p_original jsonb, p_live jsonb, p_request jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE mutable_keys text[]:=ARRAY['post_commit_payload','post_commit_request_hash','post_commit_payload_hash','post_commit_completed_at','post_commit_result'];
 payload jsonb; submitted jsonb; result jsonb; k text;
BEGIN
 IF jsonb_typeof(p_original) IS DISTINCT FROM 'object' OR jsonb_typeof(p_live) IS DISTINCT FROM 'object'
  OR (p_original-mutable_keys) IS DISTINCT FROM (p_live-mutable_keys) THEN RETURN false; END IF;
 -- The private inner core may have no outer obligations. Its original exact
 -- row remains admissible; the rest of the reader still proves all funding.
 IF p_live IS NOT DISTINCT FROM p_original THEN RETURN true; END IF;
 payload:=p_live->'post_commit_payload';
 IF jsonb_typeof(payload) IS DISTINCT FROM 'object' OR payload->>'version' IS DISTINCT FROM '1'
  OR encode(extensions.digest(convert_to(payload::text,'UTF8'),'sha256'),'hex') IS DISTINCT FROM p_live->>'post_commit_payload_hash'
  OR jsonb_typeof(payload->'accepted_hand_facts') IS DISTINCT FROM 'object'
  OR payload->'accepted_hand_facts' IS DISTINCT FROM p_request#>'{hand_row,_accepted_post_commit_facts}' THEN RETURN false; END IF;
 -- These are the only two fields the outer owner adds to the received
 -- obligation request. Reconstruct that exact request, then check its seal.
 submitted:=payload-'accepted_hand_facts';
 IF jsonb_typeof(submitted->'pending_addons')='object' THEN
  IF jsonb_typeof(submitted#>'{pending_addons,ids}') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
  submitted:=submitted#-'{pending_addons,ids}';
 END IF;
 IF encode(extensions.digest(convert_to(submitted::text,'UTF8'),'sha256'),'hex') IS DISTINCT FROM p_live->>'post_commit_request_hash' THEN RETURN false; END IF;
 FOREACH k IN ARRAY ARRAY['post_commit_payload','post_commit_request_hash','post_commit_payload_hash','post_commit_completed_at','post_commit_result'] LOOP
  IF NULLIF(p_original->k,'null'::jsonb) IS NOT NULL AND p_original->k IS DISTINCT FROM p_live->k THEN RETURN false; END IF;
 END LOOP;
 -- The original processor may subsequently record completion. It cannot
 -- replace monetary identity, the sealed request or the sealed payload.
 result:=NULLIF(p_live->'post_commit_result','null'::jsonb);
 IF (p_live->>'post_commit_completed_at' IS NULL) IS DISTINCT FROM (result IS NULL) THEN RETURN false; END IF;
 IF result IS NOT NULL AND (jsonb_typeof(result) IS DISTINCT FROM 'object' OR result->>'ok' IS DISTINCT FROM 'true'
   OR result->>'hand_id' IS DISTINCT FROM p_original->>'hand_id' OR result->>'hand_number' IS DISTINCT FROM p_original->>'hand_number'
   OR NOT isfinite((p_live->>'post_commit_completed_at')::timestamptz)
   OR (p_live->>'post_commit_completed_at')::timestamptz<(p_original->>'committed_at')::timestamptz) THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow THEN RETURN false;
END $$;


ALTER FUNCTION public.fn_cash_atomic_original_matches(p_original jsonb, p_live jsonb, p_request jsonb) OWNER TO postgres;

--
-- TOC entry 6779 (class 1255 OID 35348654)
-- Name: fn_cash_capture_hand_manifest(uuid, bigint, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_capture_hand_manifest(p_table_id uuid, p_hand_number bigint, p_participants jsonb, p_instance_id text, p_lease_generation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE t public.tables%ROWTYPE; h public.clubs%ROWTYPE; s public.table_seats%ROWTYPE;
 prior public.cash_hand_participant_manifests%ROWTYPE;
 x jsonb; v_users uuid[]:=ARRAY[]::uuid[]; v_occupancies uuid[]:=ARRAY[]::uuid[];
 v_roster jsonb:='[]'; v_request jsonb; v_scope jsonb; v_issues jsonb:='[]';
 v_lineage jsonb; v_funding jsonb; v_initial integer; v_accounts integer; v_id uuid; v_user uuid;
 v_seat uuid; v_occupancy uuid; v_join timestamptz; v_before numeric; v_complete boolean:=true;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'Engine authority required' USING ERRCODE='42501'; END IF;
 IF p_table_id IS NULL OR p_hand_number IS NULL OR p_hand_number<1000000
 OR jsonb_typeof(p_participants) IS DISTINCT FROM 'array' OR jsonb_array_length(p_participants)<2
 OR jsonb_array_length(p_participants)>10 OR p_instance_id IS NULL OR p_lease_generation IS NULL THEN
  RAISE EXCEPTION 'Invalid original cash manifest' USING ERRCODE='22023'; END IF;
 PERFORM 1 FROM public.engine_table_leases l WHERE l.table_id=p_table_id
  AND l.instance_id=p_instance_id AND l.lease_generation=p_lease_generation AND l.protocol_version=2
  AND l.heartbeat_at>=clock_timestamp()-make_interval(secs=>public.fn_engine_lease_stale_seconds()) FOR KEY SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Original cash manifest lease stale' USING ERRCODE='55000'; END IF;
 SELECT jsonb_agg(value ORDER BY value->>'user_id') INTO v_request FROM jsonb_array_elements(p_participants);
 SELECT * INTO prior FROM public.cash_hand_participant_manifests WHERE table_id=p_table_id AND hand_number=p_hand_number;
 IF FOUND THEN
  IF prior.request IS DISTINCT FROM v_request OR prior.lease_instance_id IS DISTINCT FROM p_instance_id
   OR prior.lease_generation IS DISTINCT FROM p_lease_generation THEN
   RAISE EXCEPTION 'Original cash manifest identity reused' USING ERRCODE='22023'; END IF;
  RETURN jsonb_build_object('version',1,'manifest_id',prior.id,'funding_provenance_complete',prior.funding_provenance_complete,'issues',prior.issues);
 END IF;
 SELECT * INTO STRICT t FROM public.tables WHERE id=p_table_id FOR SHARE;
 IF t.tournament_id IS NOT NULL THEN RAISE EXCEPTION 'Tournament chips are not cash provenance' USING ERRCODE='22023'; END IF;
 SELECT * INTO h FROM public.clubs WHERE id=t.club_id;
 v_scope:=jsonb_build_object('host_club_id',t.club_id,'game_union_id',CASE WHEN t.is_private THEN NULL ELSE t.union_id END,
  'is_private',t.is_private,'tournament_id',t.tournament_id,'asset',h.asset,'unit_scale',2);
 IF h.id IS NULL OR h.asset IS DISTINCT FROM 'chips' OR t.is_private IS NULL
  OR (NOT t.is_private AND t.union_id IS NULL) THEN
  v_issues:=v_issues||'"game_asset_or_union_scope_unproven"'::jsonb; v_complete:=false; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(v_request) LOOP
  v_user:=(x->>'user_id')::uuid; v_seat:=(x->>'seat_id')::uuid;
  v_occupancy:=(x->>'occupancy_id')::uuid; v_join:=(x->>'seat_joined_at')::timestamptz;
  v_before:=(x->>'stack_before')::numeric;
  IF v_user IS NULL OR v_seat IS NULL OR v_occupancy IS NULL OR v_join IS NULL
   OR NOT isfinite(v_join) OR v_user=ANY(v_users) OR v_occupancy=ANY(v_occupancies)
   OR jsonb_typeof(x->'is_horse') IS DISTINCT FROM 'boolean' OR jsonb_typeof(x->'stack_before') IS DISTINCT FROM 'number'
   OR v_before IS NULL OR v_before<0 OR v_before<>round(v_before,2)
   OR v_before::text IN ('NaN','Infinity','-Infinity') THEN
   RAISE EXCEPTION 'Invalid or duplicate cash participant' USING ERRCODE='22023'; END IF;
  v_users:=array_append(v_users,v_user); v_occupancies:=array_append(v_occupancies,v_occupancy);
  SELECT * INTO s FROM public.table_seats WHERE id=v_seat AND table_id=p_table_id AND user_id=v_user
   AND occupancy_id=v_occupancy AND joined_at=v_join AND left_at IS NULL FOR SHARE;
  IF NOT FOUND OR s.stack IS DISTINCT FROM v_before THEN
   v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','original_seat_or_starting_stack_unproven','user_id',v_user));
   v_complete:=false;
  END IF;
  v_lineage:=public.fn_cash_original_funding_lineage(v_user,p_table_id,v_seat,v_occupancy,v_join,clock_timestamp(),false);
  v_funding:=v_lineage->'funding_receipts';
  SELECT count(*) FILTER(WHERE f.operation_kind='buyin'),count(DISTINCT (f.funding_club_id,f.funding_union_id,f.asset))
   INTO v_initial,v_accounts FROM jsonb_array_elements(v_funding) ref
   JOIN public.cash_participant_funding_receipts f ON f.id=(ref->>'id')::uuid;
  IF v_lineage->'issues'<>'[]'::jsonb THEN
   v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','original_cash_move_lineage_unproven','user_id',v_user,'details',v_lineage->'issues'));
   v_complete:=false;
  END IF;
  IF v_initial<>1 OR v_accounts<>1 THEN
   v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason',CASE WHEN v_initial<>1 THEN 'original_admission_funding_missing' ELSE 'mixed_funding_account_ownership_unproven' END,'user_id',v_user));
   v_complete:=false;
  END IF;
  IF EXISTS(SELECT 1 FROM public.cash_participant_funding_receipts f
    LEFT JOIN public.cash_funding_application_receipts a ON a.funding_receipt_id=f.id
    WHERE f.id IN(SELECT (ref->>'id')::uuid FROM jsonb_array_elements(v_funding) ref) AND f.pending_addon_id IS NOT NULL
     AND (a.pending_addon_id IS NULL OR (a.applied>0 AND a.applied_occupancy_id IS DISTINCT FROM f.occupancy_id))) THEN
   v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','pending_funding_application_unproven','user_id',v_user));
   v_complete:=false;
  END IF;
  v_roster:=v_roster||jsonb_build_array(jsonb_build_object('user_id',v_user,'seat_id',v_seat,
   'seat_joined_at',x->>'seat_joined_at','occupancy_id',v_occupancy,'stack_before',v_before,
   'is_horse',(x->>'is_horse')::boolean,'funding_receipts',v_funding,'funding_lineage',v_lineage));
 END LOOP;
 INSERT INTO public.cash_hand_participant_manifests(table_id,hand_number,lease_instance_id,lease_generation,
  request,game_scope,participants,issues,funding_provenance_complete)
 VALUES(p_table_id,p_hand_number,p_instance_id,p_lease_generation,v_request,v_scope,v_roster,v_issues,v_complete)
 RETURNING id INTO v_id;
 RETURN jsonb_build_object('version',1,'manifest_id',v_id,'funding_provenance_complete',v_complete,'issues',v_issues);
END $$;


ALTER FUNCTION public.fn_cash_capture_hand_manifest(p_table_id uuid, p_hand_number bigint, p_participants jsonb, p_instance_id text, p_lease_generation uuid) OWNER TO postgres;

--
-- TOC entry 7778 (class 1255 OID 83676731)
-- Name: fn_cash_cluster_abort_pending_off(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_abort_pending_off(p_game_id uuid, p_request_id uuid, p_reason text DEFAULT 'population_rose_above_off_threshold'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g        record;
  v_conv   record;
  v_reason text := coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'unstated');
  v_entered integer := 0;
  s        record;
BEGIN
  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'aborted', false, 'reason', 'not_found');
  END IF;

  SELECT * INTO v_conv FROM public.cash_cluster_conversion
   WHERE cluster_id = g.id AND conversion_request_id = p_request_id;
  IF NOT FOUND THEN
    IF EXISTS (SELECT 1 FROM public.cash_cluster_conversion
                WHERE conversion_request_id = p_request_id) THEN
      RETURN jsonb_build_object('ok', false, 'aborted', false,
        'reason', 'request_id_belongs_to_another_cluster');
    END IF;
    RETURN jsonb_build_object('ok', false, 'aborted', false, 'reason', 'no_such_conversion');
  END IF;
  IF v_conv.to_mode IS DISTINCT FROM 'must_move' THEN
    RETURN jsonb_build_object('ok', false, 'aborted', false,
      'reason', 'not_a_pending_off_conversion', 'to_mode', v_conv.to_mode);
  END IF;
  IF v_conv.status = 'aborted' THEN
    RETURN jsonb_build_object('ok', true, 'aborted', true, 'reason', 'already_aborted',
      'conversion_id', v_conv.id, 'status', v_conv.status,
      'abort_reason', v_conv.abort_reason, 'cluster_mode', g.cluster_mode);
  END IF;
  IF v_conv.status <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'aborted', false,
      'reason', 'conversion_already_closed',
      'status', v_conv.status, 'epoch_after', v_conv.epoch_after,
      'cluster_mode', g.cluster_mode);
  END IF;
  IF g.cluster_mode IS DISTINCT FROM 'pending_off' THEN
    RETURN jsonb_build_object('ok', false, 'aborted', false, 'reason', 'wrong_state',
      'cluster_mode', g.cluster_mode);
  END IF;
  -- NEVER BACK INTO A POOL THAT HAS BEEN SWITCHED OFF. A drain begun because
  -- Lightning or the game was disabled finishes; it is not undone by a
  -- population that happens to be high.
  IF coalesce(g.lightning_enabled, false) = false OR g.enabled IS DISTINCT FROM true THEN
    RETURN jsonb_build_object('ok', false, 'aborted', false, 'reason', 'lightning_disabled',
      'cluster_mode', g.cluster_mode);
  END IF;

  UPDATE public.cash_games SET cluster_mode = 'lightning', updated_at = now()
   WHERE id = g.id;

  -- A CONVERSION LOCKS THE SEATS IT ENTERS (2026-10-09, Phase 12 load and
  -- chaos): the live seats FOR SHARE in seat-id order before the loop below
  -- reads them, so a departure racing the abort either finishes first or
  -- waits and then closes the session it sees; no pool session is ever
  -- opened on a seat that is leaving.
  PERFORM 1 FROM public.table_seats ts
   WHERE ts.left_at IS NULL
     AND ts.table_id IN (SELECT tb.id FROM public.tables tb WHERE tb.cluster_id = g.id)
   ORDER BY ts.id
     FOR SHARE;

  -- THE MODE CHANGES UNDER THE CLUSTER'S MODE LOCK (2026-10-15, Lightning
  -- Phase 12 load and chaos): EXCLUSIVE, after the seat FOR SHARE above and
  -- before the loop below reads who sat down. An arrival whose seat trigger
  -- read 'pending_off' first has committed when this returns and the loop
  -- enters it; one after waits for this commit and reads 'lightning'.
  PERFORM pg_advisory_xact_lock(
    pg_catalog.hashtextextended('lightning_cluster_mode:' || g.id::text, 0));

  -- WHOEVER SAT DOWN DURING THE DRAIN IS IN THE POOL NOW. The seat trigger
  -- enters a player only while the Cluster is 'lightning', so a player seated
  -- in pending_off would otherwise sit at a halted table in a Cluster that is
  -- a pool again. Same door, same predicate as the trigger.
  FOR s IN
    SELECT DISTINCT ON (ts.user_id) ts.id, ts.user_id
      FROM public.table_seats ts
      JOIN public.tables tb ON tb.id = ts.table_id
     WHERE tb.cluster_id = g.id AND ts.left_at IS NULL AND ts.user_id IS NOT NULL
       AND public.fn_lightning_anchor_is_live_eligible(ts.id, g.id, ts.user_id)
       AND NOT EXISTS (SELECT 1 FROM public.lightning_pool_session ps
                        WHERE ps.cluster_id = g.id AND ps.player_id = ts.user_id
                          AND ps.exited_at IS NULL)
     ORDER BY ts.user_id, ts.joined_at, ts.id
  LOOP
    IF public.fn_lightning_pool_enter(s.id, clock_timestamp()) IS NOT NULL THEN
      v_entered := v_entered + 1;
    END IF;
  END LOOP;

  UPDATE public.cash_cluster_conversion
     SET status = 'aborted', abort_reason = v_reason, closed_at = clock_timestamp()
   WHERE id = v_conv.id;

  INSERT INTO public.cash_cluster_events (game_id, kind, payload, request_id)
  VALUES (g.id, 'lightning_pending_off_aborted', jsonb_build_object(
    'conversion_id', v_conv.id, 'conversion_request_id', p_request_id,
    'abort_reason', v_reason, 'pool_sessions_entered', v_entered,
    'live_eligible', public.fn_cash_cluster_live_eligible(g.id)), p_request_id);

  RETURN jsonb_build_object('ok', true, 'aborted', true, 'reason', 'aborted',
    'conversion_id', v_conv.id, 'cluster_mode', 'lightning',
    'abort_reason', v_reason, 'pool_sessions_entered', v_entered);
END;
$$;


ALTER FUNCTION public.fn_cash_cluster_abort_pending_off(p_game_id uuid, p_request_id uuid, p_reason text) OWNER TO postgres;

--
-- TOC entry 46436 (class 0 OID 0)
-- Dependencies: 7778
-- Name: FUNCTION fn_cash_cluster_abort_pending_off(p_game_id uuid, p_request_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_abort_pending_off(p_game_id uuid, p_request_id uuid, p_reason text) IS 'Lightning Phase 7: PENDING_OFF -> LIGHTNING (refused while disabled). Aborts the conversion, enters players seated during the drain into the pool, emits lightning_pending_off_aborted.';


--
-- TOC entry 3455 (class 1255 OID 49231911)
-- Name: fn_cash_cluster_abort_pending_on(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_abort_pending_on(p_game_id uuid, p_request_id uuid, p_reason text DEFAULT 'population_fell_below_on_threshold'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  g        record;
  v_conv   record;
  v_resume integer;
  v_restored integer;
BEGIN
  -- Deliberately NOT gated on fn_platform_frozen(). A Cluster stuck in
  -- PENDING_ON with every table halted is exactly the state an operator needs
  -- to be able to leave during an incident, and the break is when incidents
  -- are handled. The asymmetry is the same one the verdict carries: entering
  -- Lightning is gated, leaving it never is.
  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'aborted', false, 'reason', 'not_found');
  END IF;

  SELECT * INTO v_conv FROM public.cash_cluster_conversion
   WHERE cluster_id = g.id AND conversion_request_id = p_request_id;
  IF NOT FOUND THEN
    -- Told apart from "that id is not yours", because a caller cannot fix a
    -- mistake nobody names. Both refuse; only one is the caller's own bug.
    IF EXISTS (SELECT 1 FROM public.cash_cluster_conversion
                WHERE conversion_request_id = p_request_id) THEN
      RETURN jsonb_build_object('ok', false, 'aborted', false,
        'reason', 'request_id_belongs_to_another_cluster');
    END IF;
    RETURN jsonb_build_object('ok', false, 'aborted', false, 'reason', 'no_such_conversion');
  END IF;

  -- THE MIRROR OF THE DEFECT begin_pending_on CARRIED. A retry of an abort
  -- that already succeeded was told ok: false, while the Cluster sat in
  -- exactly the state the caller had asked for and the conversion was closed
  -- exactly as requested. Same worker-timeout shape: abort, time out before
  -- reading the reply, retry, be told no, escalate or retry for ever. An
  -- idempotent operation that answers false on its second call is not
  -- idempotent in the only sense a caller cares about.
  IF v_conv.status = 'aborted' THEN
    RETURN jsonb_build_object('ok', true, 'aborted', true, 'reason', 'already_aborted',
      'conversion_id', v_conv.id, 'status', v_conv.status,
      'abort_reason', v_conv.abort_reason, 'cluster_mode', g.cluster_mode);
  END IF;
  IF v_conv.status <> 'pending' THEN
    -- Committed. Not abortable, and the reason is carried so a caller is not
    -- left reading a status string to find out why.
    RETURN jsonb_build_object('ok', false, 'aborted', false,
      'reason', 'conversion_already_closed',
      'status', v_conv.status, 'epoch_after', v_conv.epoch_after,
      'cluster_mode', g.cluster_mode);
  END IF;
  IF g.cluster_mode <> 'pending_on' THEN
    RETURN jsonb_build_object('ok', false, 'aborted', false, 'reason', 'wrong_state',
      'cluster_mode', g.cluster_mode);
  END IF;

  UPDATE public.cash_games SET cluster_mode = 'must_move', updated_at = now()
   WHERE id = g.id;

  -- Only OUR halt is lifted. A table halted for some other reason - a reason
  -- this vocabulary does not yet contain - is not a table this conversion
  -- stopped, and clearing it here would be a Lightning conversion silently
  -- restarting a table somebody else deliberately stopped.
  UPDATE public.tables
     SET dealing_halted_at = NULL, dealing_halted_reason = NULL
   WHERE cluster_id = g.id AND dealing_halted_reason = 'lightning_pending_on';
  GET DIAGNOSTICS v_resume = ROW_COUNT;

  -- AND THE SEAT MOVES COME BACK (2026-09-25). begin_pending_on cancelled
  -- every pending move of this Cluster and stamped the note below. Lifting the
  -- halt without giving them back leaves a player who spent their one seat
  -- change of the stay holding a cash_seat_change_requests row that says
  -- 'moved' against a cash_seat_moves row that says 'cancelled' - the tick
  -- re-plans its own moves on the next pass, but it will not re-plan that one.
  UPDATE public.cash_seat_moves m
     SET state = 'pending', resolved_at = NULL,
         note = nullif(btrim(regexp_replace(m.note, '( \| )?cancelled by lightning pending_on$', '')), '')
   WHERE m.game_id = g.id
     AND m.state = 'cancelled'
     AND m.note LIKE '%cancelled by lightning pending_on'
     -- BOUNDED TO THIS CONVERSION, WITHOUT A MAGIC CONSTANT. The begin
     -- cancels a fraction of a second BEFORE it writes its own row, so
     -- resolved_at is a hair EARLIER than v_conv.opened_at and a >= against it
     -- would match nothing. What separates our cancellations from an earlier
     -- conversion's on the same Cluster is the earlier conversion's own
     -- opened_at, and that is the tightest bound these two timestamps allow.
     AND m.resolved_at > coalesce((SELECT max(c2.opened_at) FROM public.cash_cluster_conversion c2
                                    WHERE c2.cluster_id = g.id AND c2.opened_at < v_conv.opened_at),
                                  '-infinity'::timestamptz)
     -- cash_seat_moves_one_pending_per_player is a UNIQUE index. A restore
     -- that violated it would raise out of an abort, and an abort that can
     -- raise is one that cannot recover anything.
     AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves x
                      WHERE x.player_id = m.player_id AND x.state = 'pending');
  GET DIAGNOSTICS v_restored = ROW_COUNT;

  UPDATE public.cash_cluster_conversion
     SET status = 'aborted', abort_reason = coalesce(nullif(btrim(p_reason), ''), 'unstated'),
         closed_at = clock_timestamp()
   WHERE id = v_conv.id;

  INSERT INTO public.cash_cluster_events (game_id, kind, payload)
  VALUES (g.id, 'lightning_pending_on_aborted', jsonb_build_object(
    'conversion_id', v_conv.id, 'conversion_request_id', p_request_id,
    'abort_reason', coalesce(nullif(btrim(p_reason), ''), 'unstated'),
    'tables_resumed', v_resume, 'seat_moves_restored', v_restored,
    'live_eligible', public.fn_cash_cluster_live_eligible(g.id)));

  RETURN jsonb_build_object('ok', true, 'aborted', true, 'reason', 'aborted',
    'conversion_id', v_conv.id, 'cluster_mode', 'must_move',
    -- commit_lightning returns THIS object for its two self-aborts, so without
    -- abort_reason here a caller that self-aborted could not tell a population
    -- that fell away from a player with no open cash session. Both live in the
    -- row and the event; neither reached the caller.
    'abort_reason', coalesce(nullif(btrim(p_reason), ''), 'unstated'),
    'tables_resumed', v_resume, 'seat_moves_restored', v_restored);
END;
$_$;


