COMMENT ON FUNCTION public.fn_cash_cluster_abort_pending_on(p_game_id uuid, p_request_id uuid, p_reason text) IS 'Step 11 and acceptance test F04: return a PENDING_ON Cluster to MUST_MOVE, lift the halt this conversion placed and only that halt, and close the conversion record with a reason. No Lightning player can be stranded here because PENDING_ON creates no pool session - the specification creates the Epoch and the sessions at step 13 and after, which is what makes an abort a two-column clear rather than an unwind. Not gated on the platform freeze, deliberately: leaving a half-converted state must always be possible.';


--
-- TOC entry 8540 (class 1255 OID 21943585)
-- Name: fn_cash_cluster_balance(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_balance(p_game_id uuid, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_census public.cash_cluster_census_row[];
  v_planned integer := 0;
  v_from uuid;
  v_to uuid;
  v_player uuid;
BEGIN
  -- LIGHTNING 2.0 PHASE 5. tick_all calls this after every tick, in the same
  -- transaction, whatever the tick returned - so standing the tick down does
  -- not stand this down. A Lightning Cluster would go on having a seat move
  -- planned every five seconds, between tables that are not dealing, for
  -- players the pool believes it owns. Zero moves planned, not an exception:
  -- this returns a count and the honest count is zero.
  IF EXISTS (SELECT 1 FROM public.cash_games cg
              WHERE cg.id = p_game_id AND cg.cluster_mode IS DISTINCT FROM 'must_move') THEN
    RETURN 0;
  END IF;
  v_census := public.fn_cash_cluster_census(p_game_id, p_now);

  -- THE POOL IS THE FEEDERS (2026-09-10). It used to be every live table
  -- except Main 1, so Main 2..N were in it - and step 2 of the tick holds
  -- every main FULL from the feeder. The balancer moved the newest arrival
  -- off a full main onto the feeder, step 2 moved the longest-seated feeder
  -- player straight back, and the same players went round every hand: 355
  -- exact round trips in one hour, two players moved 55 times each. Mains are
  -- step 2's, as source and as destination; this balances feeders among
  -- themselves and, with one feeder, does nothing.
  WITH pool AS (
    SELECT c.id,
           c.main_index,
           c.created_at,
           c.seated
             - (SELECT count(*) FROM public.cash_seat_moves m
                 WHERE m.from_table_id = c.id AND m.state = 'pending')
             + (SELECT count(*) FROM public.cash_seat_moves m
                 WHERE m.to_table_id = c.id AND m.state = 'pending') AS n,
           c.open_unreserved
             - (SELECT count(*) FROM public.cash_seat_moves m
                 WHERE m.to_table_id = c.id AND m.state = 'pending' AND m.swap_move_id IS NULL) AS room
      FROM unnest(v_census) c
     WHERE c.role = 'feeder'
       AND c.lifecycle = 'live'
       AND NOT c.breaking
  ),
  hi AS (
    SELECT * FROM pool ORDER BY n DESC, main_index DESC NULLS FIRST, created_at DESC LIMIT 1
  ),
  lo AS (
    SELECT * FROM pool WHERE room > 0
     ORDER BY n ASC, main_index ASC NULLS LAST, created_at ASC LIMIT 1
  ),
  pair AS (
    SELECT hi.id AS from_id, lo.id AS to_id
      FROM hi, lo
     WHERE hi.id <> lo.id
       AND hi.n - lo.n >= 2
       AND hi.n >= 3
       AND lo.n >= 1
  ),
  mover AS (
    SELECT p.from_id, p.to_id, ts.user_id
      FROM pair p
      JOIN public.table_seats ts ON ts.table_id = p.from_id AND ts.left_at IS NULL
     WHERE ts.user_id IS NOT NULL
       AND coalesce(ts.stack, 0) > 0
       AND coalesce(ts.leave_pending, false) = false
       AND NOT EXISTS (SELECT 1 FROM public.table_seats d
                        WHERE d.table_id = p.to_id AND d.user_id = ts.user_id AND d.left_at IS NULL)
       AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves m
                        WHERE m.player_id = ts.user_id AND m.state = 'pending')
       AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves m
                        WHERE m.player_id = ts.user_id AND m.state = 'cancelled'
                          AND coalesce(m.resolved_at, m.created_at) > p_now - interval '60 seconds')
     ORDER BY coalesce((SELECT r.joined_at FROM public.cash_game_roster r
                         WHERE r.game_id = p_game_id AND r.user_id = ts.user_id AND r.left_at IS NULL),
                       ts.joined_at) DESC,
              ts.joined_at DESC
     LIMIT 1
  ),
  ins AS (
    INSERT INTO public.cash_seat_moves (game_id, player_id, from_table_id, to_table_id, reason)
    SELECT p_game_id, m.user_id, m.from_id, m.to_id, 'balance' FROM mover m
    RETURNING player_id, from_table_id, to_table_id
  )
  SELECT count(*)::integer,
         (array_agg(i.from_table_id))[1],
         (array_agg(i.to_table_id))[1],
         (array_agg(i.player_id))[1]
    INTO v_planned, v_from, v_to, v_player
    FROM ins i;

  IF coalesce(v_planned, 0) > 0 THEN
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
    VALUES (p_game_id, v_to, 'move_planned',
            jsonb_build_object('player_id', v_player, 'from_table_id', v_from, 'reason', 'balance'));
  END IF;

  RETURN coalesce(v_planned, 0);
END;
$$;


ALTER FUNCTION public.fn_cash_cluster_balance(p_game_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 46440 (class 0 OID 0)
-- Dependencies: 8540
-- Name: FUNCTION fn_cash_cluster_balance(p_game_id uuid, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_balance(p_game_id uuid, p_now timestamp with time zone) IS 'Plans at most one balancing move between the must-move tables of one cash cluster, keeping them within one player of each other (Dan 2026-09-05). Main 1 is fed and never balanced. Called once per game per pass from fn_cash_clusters_tick_all, after the tick.';


--
-- TOC entry 6701 (class 1255 OID 83676726)
-- Name: fn_cash_cluster_begin_pending_off(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_begin_pending_off(p_game_id uuid, p_request_id uuid DEFAULT gen_random_uuid(), p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g          record;
  v_prior    record;
  v_state    jsonb;
  v_why      text;
  v_voided   integer := 0;
  v_inflight integer := 0;
  v_dwell    integer;
  v_chips    numeric;
  i          record;
BEGIN
  -- IDEMPOTENCY FIRST, as begin_pending_on asks it: a worker retrying a
  -- request that already succeeded is told so, and an id that names a
  -- conversion in the other direction is named as the caller's bug.
  SELECT * INTO v_prior FROM public.cash_cluster_conversion
   WHERE conversion_request_id = p_request_id AND cluster_id = p_game_id;
  IF FOUND THEN
    IF v_prior.to_mode IS DISTINCT FROM 'must_move' THEN
      RETURN jsonb_build_object('ok', false, 'pending', false,
        'reason', 'request_id_belongs_to_another_conversion',
        'conversion_id', v_prior.id, 'to_mode', v_prior.to_mode);
    END IF;
    RETURN jsonb_build_object(
      'ok', v_prior.status <> 'aborted',
      'pending', v_prior.status = 'pending',
      'reason', CASE v_prior.status
                  WHEN 'pending'   THEN 'already_known'
                  WHEN 'committed' THEN 'already_committed'
                  ELSE 'conversion_already_aborted' END,
      'conversion_id', v_prior.id, 'status', v_prior.status,
      'abort_reason', v_prior.abort_reason,
      'cluster_mode', (SELECT cluster_mode FROM public.cash_games WHERE id = p_game_id));
  END IF;
  IF EXISTS (SELECT 1 FROM public.cash_cluster_conversion
              WHERE conversion_request_id = p_request_id) THEN
    RETURN jsonb_build_object('ok', false, 'pending', false, 'reason', 'request_id_belongs_to_another_cluster');
  END IF;

  -- NOT GATED ON fn_platform_frozen(). Leaving Lightning must always be
  -- possible (the verdict's own asymmetry: entering is gated, leaving never
  -- is), and this call deals nothing and moves no chip. The commit, which
  -- lets the physical tables deal again, is gated.

  -- THE CLUSTER ROW FIRST, in the order the ON path and formation take it.
  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'pending', false, 'reason', 'not_found');
  END IF;

  -- ASKED AGAIN UNDER THE LOCK, for two callers sharing one request id.
  SELECT * INTO v_prior FROM public.cash_cluster_conversion
   WHERE conversion_request_id = p_request_id AND cluster_id = p_game_id;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'ok', v_prior.status <> 'aborted' AND v_prior.to_mode = 'must_move',
      'pending', v_prior.status = 'pending',
      'reason', CASE WHEN v_prior.to_mode IS DISTINCT FROM 'must_move' THEN 'request_id_belongs_to_another_conversion'
                     WHEN v_prior.status = 'pending' THEN 'already_known'
                     WHEN v_prior.status = 'committed' THEN 'already_committed'
                     ELSE 'conversion_already_aborted' END,
      'conversion_id', v_prior.id, 'status', v_prior.status,
      'abort_reason', v_prior.abort_reason, 'cluster_mode', g.cluster_mode);
  END IF;

  -- LIGHTNING PHASE 13 (20261009235505): the emergency drain ends through
  -- this path; a draining Cluster is admitted for the drain alone.
  IF g.cluster_mode IS DISTINCT FROM 'lightning'
     AND NOT (g.cluster_mode = 'draining' AND p_reason IS NOT DISTINCT FROM 'lightning_drain') THEN
    RETURN jsonb_build_object('ok', false,
      'pending', g.cluster_mode IN ('pending_on', 'pending_off'),
      'reason', 'wrong_state', 'cluster_mode', g.cluster_mode);
  END IF;

  -- LIGHTNING PHASE 7 REMEDIATION (20261007222717): AN OPEN CONVERSION IS AN
  -- ANSWER, NOT AN EXCEPTION - exactly as begin_pending_on now answers it.
  SELECT * INTO v_prior FROM public.cash_cluster_conversion
   WHERE cluster_id = g.id AND status = 'pending';
  IF FOUND THEN
    RETURN jsonb_build_object('ok', false, 'pending', true,
      'reason', 'conversion_already_open',
      'conversion_id', v_prior.id, 'conversion_request_id', v_prior.conversion_request_id,
      'to_mode', v_prior.to_mode, 'cluster_mode', g.cluster_mode);
  END IF;

  -- THE TRIGGER. The verdict is the one population reader the lobby and the
  -- ON path embed; a disabled Cluster drains whatever its population.
  v_state := public.fn_cash_cluster_lightning_state(g.id);
  v_why := CASE
    WHEN coalesce(g.lightning_enabled, false) = false THEN 'lightning_disabled'
    WHEN g.enabled IS DISTINCT FROM true THEN 'game_disabled'
    WHEN coalesce((v_state -> 'verdict' ->> 'would_turn_off')::boolean, false) THEN 'population_at_or_below_off_threshold'
    ELSE NULL END;
  IF v_why IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'pending', false, 'reason', 'threshold_not_reached',
      'verdict', v_state -> 'verdict', 'thresholds', v_state -> 'thresholds');
  END IF;

  -- LIGHTNING PHASE 7 REMEDIATION (20261007222717), TIGHTENED BY
  -- 20261008043021: THE OFF CONDITION MUST DWELL, AND THE DWELL IS A
  -- DURATION, NOT A COUNT OF CALLS. A population hovering at the OFF
  -- threshold used to open a conversion, void every reserved formation, and
  -- abort, on every oscillation; and a seat-change wake half a second after
  -- the first sighting used to open PENDING_OFF anyway, because any second
  -- call proceeded. The first sighting is recorded durably on the Cluster
  -- row this call already holds FOR UPDATE, and a drive pass that does not
  -- see the condition clears it; every later sighting is refused, with the
  -- STANDING first_seen_at, until the recorded sighting has stood for the
  -- configured pending_off_dwell_ms (default 10000; 0 keeps the two-sighting
  -- rule with no minimum duration). A disabled Cluster or game always drains
  -- at once: the dwell gates only the population trigger.
  IF v_why = 'population_at_or_below_off_threshold' THEN
    v_dwell := (public.fn_lightning_config_number(
                  CASE WHEN jsonb_typeof(g.ruleset_snapshot -> 'lightning') = 'object'
                       THEN g.ruleset_snapshot -> 'lightning' ELSE '{}'::jsonb END,
                  'pending_off_dwell_ms', 10000, 0, 3600000, true) ->> 'value')::integer;
    IF g.lightning_off_condition_since IS NULL THEN
      UPDATE public.cash_games
         SET lightning_off_condition_since = clock_timestamp(), updated_at = now()
       WHERE id = g.id;
      RETURN jsonb_build_object('ok', false, 'pending', false, 'reason', 'off_condition_dwell',
        'why', v_why, 'first_seen_at', clock_timestamp(), 'dwell_ms', v_dwell,
        'verdict', v_state -> 'verdict', 'thresholds', v_state -> 'thresholds');
    ELSIF clock_timestamp() < g.lightning_off_condition_since + make_interval(secs => v_dwell / 1000.0) THEN
      RETURN jsonb_build_object('ok', false, 'pending', false, 'reason', 'off_condition_dwell',
        'why', v_why, 'first_seen_at', g.lightning_off_condition_since, 'dwell_ms', v_dwell,
        'verdict', v_state -> 'verdict', 'thresholds', v_state -> 'thresholds');
    END IF;
  END IF;

  UPDATE public.cash_games
     SET cluster_mode = 'pending_off', lightning_off_condition_since = NULL, updated_at = now()
   WHERE id = g.id;

  -- THE DRAIN POLICY. Nothing new forms: fn_lightning_form_hand refuses every
  -- mode but 'lightning'. A formation that has not been dealt is void now,
  -- rather than when begin_dealing or the reaper finds it; nothing was dealt,
  -- so nothing is owed, and the AFTER trigger on lightning_instance hands its
  -- players back. A hand already dealing or settling is left to finish.
  FOR i IN
    SELECT li.id FROM public.lightning_instance li
     WHERE li.cluster_id = g.id AND li.state IN ('forming', 'reserved')
     ORDER BY li.id
     FOR UPDATE
  LOOP
    PERFORM public.fn_lightning_instance_abandon(i.id,
      'lightning pending_off: a hand not yet dealt is void; nothing was dealt and no chip moved',
      clock_timestamp());
    v_voided := v_voided + 1;
  END LOOP;

  SELECT count(*)::integer INTO v_inflight
    FROM public.lightning_instance li
   WHERE li.cluster_id = g.id AND li.state IN ('dealing', 'settling');

  SELECT coalesce(sum(ts.stack), 0) INTO v_chips
    FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.cluster_id = g.id AND ts.left_at IS NULL;

  INSERT INTO public.cash_cluster_conversion (
    cluster_id, conversion_request_id, from_mode, to_mode, trigger_population,
    on_threshold, off_threshold, epoch_before, chips_at_begin)
  VALUES (
    g.id, p_request_id, g.cluster_mode, 'must_move',
    coalesce((v_state -> 'verdict' ->> 'live_eligible')::integer, 0),
    coalesce((v_state -> 'thresholds' ->> 'on')::integer, 0),
    coalesce((v_state -> 'thresholds' ->> 'off')::integer, 0),
    g.cluster_epoch, v_chips)
  RETURNING * INTO v_prior;

  INSERT INTO public.cash_cluster_events (game_id, kind, payload, request_id)
  VALUES (g.id, 'lightning_pending_off', jsonb_build_object(
    'conversion_id', v_prior.id, 'conversion_request_id', p_request_id,
    'reason', v_why, 'note', nullif(btrim(coalesce(p_reason, '')), ''),
    'trigger_population', v_prior.trigger_population,
    'on_threshold', v_prior.on_threshold, 'off_threshold', v_prior.off_threshold,
    'epoch_before', g.cluster_epoch, 'lightning_enabled', g.lightning_enabled,
    'instances_voided', v_voided, 'hands_in_flight', v_inflight,
    'chips_at_begin', v_chips), p_request_id);

  RETURN jsonb_build_object('ok', true, 'pending', true, 'reason', 'pending_off',
    'why', v_why, 'conversion_id', v_prior.id, 'conversion_request_id', p_request_id,
    'cluster_mode', 'pending_off', 'trigger_population', v_prior.trigger_population,
    'instances_voided', v_voided, 'hands_in_flight', v_inflight,
    'thresholds', v_state -> 'thresholds');
END;
$$;


ALTER FUNCTION public.fn_cash_cluster_begin_pending_off(p_game_id uuid, p_request_id uuid, p_reason text) OWNER TO postgres;

--
-- TOC entry 46442 (class 0 OID 0)
-- Dependencies: 6701
-- Name: FUNCTION fn_cash_cluster_begin_pending_off(p_game_id uuid, p_request_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_begin_pending_off(p_game_id uuid, p_request_id uuid, p_reason text) IS 'Lightning Phase 7 (spec Phase 10): LIGHTNING -> PENDING_OFF when the live eligible population is at or below OFF, or Lightning or the game is disabled. Opens a lightning -> must_move cash_cluster_conversion, voids formations not yet dealt, emits lightning_pending_off. Idempotent on p_request_id. Moves no chip.';


--
-- TOC entry 8316 (class 1255 OID 49231905)
-- Name: fn_cash_cluster_begin_pending_on(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_begin_pending_on(p_game_id uuid, p_request_id uuid DEFAULT gen_random_uuid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g        record;
  v_state  jsonb;
  v_prior  record;
  v_halted integer;
  v_halted_total integer;
  v_cancel integer;
BEGIN
  -- IDEMPOTENCY IS ASKED FIRST, BEFORE THE FREEZE AND BEFORE THE LOCK. A
  -- worker retrying a request that already succeeded must be told so even
  -- during a break; answering 'platform_frozen' to a retry makes it keep
  -- retrying for the length of the window, which is the opposite of what the
  -- freeze is for. The read is cheap and does not queue behind a tick.
  --
  -- AND cluster_id = p_game_id IS NOT DECORATION. Without it, a request id
  -- belonging to Cluster A, replayed against Cluster B, answered
  -- {"ok": true, "status": "pending", "cluster_mode": "pending_on"} - about A -
  -- while B was never touched and stayed must_move. The caller was told a
  -- conversion was in progress on a Cluster that had none.
  SELECT * INTO v_prior FROM public.cash_cluster_conversion
   WHERE conversion_request_id = p_request_id AND cluster_id = p_game_id;
  IF FOUND THEN
    -- 'pending' IS THIS FUNCTION'S 'converted', AND IT EXISTS FOR THE SAME
    -- REASON. An earlier cut answered ok: true / already_known on ANY status,
    -- so a request id whose conversion had since been ABORTED was reported as
    -- one in flight, about a Cluster sitting back in must_move. The failure is
    -- a worker that times out before reading this reply, aborts, retries the
    -- same id, is told true, and then polls commit_lightning for ever - which
    -- answers conversion_already_closed every time, so that Cluster is never
    -- converted again under that id. commit_lightning grew a 'converted'
    -- boolean against exactly this class; its sibling had been left without
    -- one. The truth was always in the payload, but a caller should not have
    -- to parse a status string to learn whether ok means what it says.
    RETURN jsonb_build_object(
      'ok', v_prior.status <> 'aborted',
      'pending', v_prior.status = 'pending',
      'reason', CASE v_prior.status
                  WHEN 'pending'   THEN 'already_known'
                  WHEN 'committed' THEN 'already_committed'
                  ELSE 'conversion_already_aborted' END,
      'conversion_id', v_prior.id, 'status', v_prior.status,
      'abort_reason', v_prior.abort_reason,
      'cluster_mode', (SELECT cluster_mode FROM public.cash_games WHERE id = p_game_id));
  END IF;

  -- The same id against a DIFFERENT Cluster is a caller bug, not a retry, and
  -- it is named rather than silently opening a second conversion - which the
  -- unique index would refuse anyway, with an error nobody could read.
  IF EXISTS (SELECT 1 FROM public.cash_cluster_conversion
              WHERE conversion_request_id = p_request_id) THEN
    RETURN jsonb_build_object('ok', false, 'pending', false, 'reason', 'request_id_belongs_to_another_cluster');
  END IF;

  -- THE FREEZE IS TOTAL. server/src/maintenance/theFreezeIsTotal.law.test.ts
  -- forbids any path that seats, registers or moves chips during the break.
  -- A conversion moves no chips, but it stops every table in a Cluster from
  -- dealing, which is emphatically an engine-affecting act, and the break
  -- exists so that the engine is doing exactly one thing at a time.
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'pending', false, 'reason', 'platform_frozen');
  END IF;

  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'pending', false, 'reason', 'not_found');
  END IF;

  -- AND THE FREEZE IS ASKED AGAIN, NOW THAT THE LOCK IS HELD (2026-09-25).
  -- The pre-lock check above is what keeps a frozen platform from queueing
  -- behind a tick at all, and it stays. But this call can wait on that lock
  -- for as long as a tick holds it, and a break beginning inside that window
  -- was missed entirely - the Cluster was then halted, and its conversion
  -- opened, during the maintenance break the freeze exists to keep the engine
  -- out of.
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'pending', false, 'reason', 'platform_frozen');
  END IF;

  -- Step 2: verify current state = MUST_MOVE. A Cluster already in pending_on
  -- is not an error to the caller - it is the answer to "is a conversion in
  -- progress" - so it is reported as such rather than raised.
  -- ASK AGAIN, NOW THAT THE LOCK IS HELD. The pre-read above runs under READ
  -- COMMITTED on a snapshot taken before the lock, so two callers sharing a
  -- request id can both miss the row: the first inserts and commits, the
  -- second blocks on the lock, wakes, and would answer 'wrong_state' about the
  -- conversion IT asked for - in precisely the case the unique
  -- conversion_request_id exists to make idempotent. A worker told wrong_state
  -- retries; a worker told already_known stops.
  SELECT * INTO v_prior FROM public.cash_cluster_conversion
   WHERE conversion_request_id = p_request_id AND cluster_id = p_game_id;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'ok', v_prior.status <> 'aborted',
      'pending', v_prior.status = 'pending',
      'reason', CASE v_prior.status
                  WHEN 'pending'   THEN 'already_known'
                  WHEN 'committed' THEN 'already_committed'
                  ELSE 'conversion_already_aborted' END,
      'conversion_id', v_prior.id, 'status', v_prior.status,
      'abort_reason', v_prior.abort_reason,
      'cluster_mode', g.cluster_mode);
  END IF;

  IF g.cluster_mode <> 'must_move' THEN
    -- 'pending' IS READ OFF THE CLUSTER HERE, NOT OFF A RECORD THIS CALLER HAS
    -- NONE OF. A second caller arriving with a FRESH request id while a
    -- conversion is already in flight is refused - correctly, the lock and the
    -- partial unique index both say so - but it was being told pending: false
    -- about a Cluster sitting in pending_on with every table halted. That is
    -- the same record-versus-Cluster confusion commit_lightning's 'converted'
    -- was re-cut to avoid, and it contradicted this function's own comment
    -- four lines down, which says a Cluster already in pending_on "is the
    -- answer to 'is a conversion in progress'". ok stays false, because this
    -- caller's request did not open anything; pending says what is true of the
    -- Cluster.
    RETURN jsonb_build_object('ok', false,
      'pending', g.cluster_mode IN ('pending_on', 'pending_off'),
      'reason', 'wrong_state', 'cluster_mode', g.cluster_mode);
  END IF;

  -- LIGHTNING PHASE 7 REMEDIATION (20261007222717): AN OPEN CONVERSION IS AN
  -- ANSWER, NOT AN EXCEPTION. A pending conversion this request id does not
  -- name - an orphan an operator path left behind, or a caller bug - used to
  -- reach the INSERT below and die on the one-open-per-cluster unique index,
  -- which the tick's drive then recorded as lightning_drive_error every pass.
  -- It is named structurally instead, so the caller can see what blocks it.
  SELECT * INTO v_prior FROM public.cash_cluster_conversion
   WHERE cluster_id = g.id AND status = 'pending';
  IF FOUND THEN
    RETURN jsonb_build_object('ok', false, 'pending', true,
      'reason', 'conversion_already_open',
      'conversion_id', v_prior.id, 'conversion_request_id', v_prior.conversion_request_id,
      'to_mode', v_prior.to_mode, 'cluster_mode', g.cluster_mode);
  END IF;

  -- Steps 3 and 4. The verdict is the one reader the lobby already embeds, so
  -- the number that triggers a conversion is the same number a player was
  -- shown. It answers in pending_on as well as must_move, which is what makes
  -- step 10's re-ask possible at all - before 20260921142954 it did not, and
  -- this function would have aborted every conversion it ever started.
  v_state := public.fn_cash_cluster_lightning_state(g.id);
  IF NOT coalesce((v_state -> 'verdict' ->> 'would_turn_on')::boolean, false) THEN
    RETURN jsonb_build_object('ok', false, 'pending', false, 'reason', 'threshold_not_reached',
      'verdict', v_state -> 'verdict', 'thresholds', v_state -> 'thresholds');
  END IF;

  -- Step 5. NO EPOCH BUMP HERE. The specification creates the next Epoch at
  -- step 13, after the re-check, and that ordering is the whole reason an
  -- abort is cheap: an aborted conversion leaves the epoch where it was, so
  -- nothing that binds to an epoch - a pool session, an instance, a hand - can
  -- have been created against an epoch that then has to be unwound.
  UPDATE public.cash_games SET cluster_mode = 'pending_on', updated_at = now()
   WHERE id = g.id;

  -- Step 6, and the reason this file exists. Stop the tables dealing. Seats,
  -- stacks and sessions are not touched; a table already halted for some other
  -- reason is left as it is rather than overwritten.
  UPDATE public.tables
     SET dealing_halted_at = clock_timestamp(), dealing_halted_reason = 'lightning_pending_on'
   WHERE cluster_id = g.id
     AND dealing_halted_at IS NULL
     AND coalesce(is_deleted, false) = false
     AND coalesce(lifecycle, '') <> 'closed';
  GET DIAGNOSTICS v_halted = ROW_COUNT;
  -- tables_halted COUNTS TABLES THAT ARE HALTED (2026-09-25). The ROW_COUNT
  -- above is of an UPDATE carrying AND dealing_halted_at IS NULL, so it is the
  -- number of boards this call NEWLY stopped - which is not the number of
  -- boards that are stopped whenever one of them was already halted for some
  -- other reason, which this function deliberately leaves alone. Both numbers
  -- are now in the answer and in the event: the one whose name was wrong, and
  -- the one nobody had.
  SELECT count(*)::integer INTO v_halted_total FROM public.tables
   WHERE cluster_id = g.id
     AND coalesce(is_deleted, false) = false
     AND coalesce(lifecycle, '') <> 'closed'
     AND dealing_halted_at IS NOT NULL;

  -- The hole the engine cannot close. Its start-up wait loop - where a table
  -- below minPlayersToDeal() lives - never re-reads its table row, so it can
  -- neither see this halt set nor see it lifted, and it still runs
  -- executeIdleSeatMoves(). A move planned a second before PENDING_ON would
  -- otherwise execute mid-conversion and write table_seats. Cancelling is
  -- correct rather than merely convenient: the destination table is about to
  -- stop dealing, so the move has nowhere useful to land.
  UPDATE public.cash_seat_moves
     SET state = 'cancelled', resolved_at = clock_timestamp(),
         note = coalesce(note || ' | ', '') || 'cancelled by lightning pending_on'
   WHERE game_id = g.id AND state = 'pending';
  GET DIAGNOSTICS v_cancel = ROW_COUNT;

  INSERT INTO public.cash_cluster_conversion (
    cluster_id, conversion_request_id, from_mode, to_mode, trigger_population,
    on_threshold, off_threshold, epoch_before)
  VALUES (
    g.id, p_request_id, 'must_move', 'lightning',
    coalesce((v_state -> 'verdict' ->> 'live_eligible')::integer, 0),
    coalesce((v_state -> 'thresholds' ->> 'on')::integer, 0),
    coalesce((v_state -> 'thresholds' ->> 'off')::integer, 0),
    g.cluster_epoch)
  RETURNING * INTO v_prior;

  -- FORENSICS (2026-09-26): the chips on the Cluster's seats at the instant
  -- its tables were halted, beside the ones the commit will record.
  UPDATE public.cash_cluster_conversion cc
     SET chips_at_begin = (SELECT coalesce(sum(ts.stack), 0)
                             FROM public.table_seats ts
                             JOIN public.tables tb ON tb.id = ts.table_id
                            WHERE tb.cluster_id = g.id AND ts.left_at IS NULL)
   WHERE cc.id = v_prior.id;

  INSERT INTO public.cash_cluster_events (game_id, kind, payload)
  VALUES (g.id, 'lightning_pending_on', jsonb_build_object(
    'conversion_id', v_prior.id, 'conversion_request_id', p_request_id,
    'trigger_population', v_prior.trigger_population,
    'on_threshold', v_prior.on_threshold, 'off_threshold', v_prior.off_threshold,
    'epoch_before', g.cluster_epoch,
    'tables_halted', v_halted_total, 'tables_newly_halted', v_halted,
    'seat_moves_cancelled', v_cancel));

  RETURN jsonb_build_object('ok', true, 'pending', true, 'reason', 'pending_on',
    'conversion_id', v_prior.id, 'conversion_request_id', p_request_id,
    'cluster_mode', 'pending_on', 'tables_halted', v_halted_total,
    'tables_newly_halted', v_halted,
    'seat_moves_cancelled', v_cancel,
    'trigger_population', v_prior.trigger_population,
    'thresholds', v_state -> 'thresholds');
END;
$$;


ALTER FUNCTION public.fn_cash_cluster_begin_pending_on(p_game_id uuid, p_request_id uuid) OWNER TO postgres;

--
-- TOC entry 46444 (class 0 OID 0)
-- Dependencies: 8316
-- Name: FUNCTION fn_cash_cluster_begin_pending_on(p_game_id uuid, p_request_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_begin_pending_on(p_game_id uuid, p_request_id uuid) IS 'Steps 1 to 6 of the specification''s MUST-MOVE -> LIGHTNING sequence: lock the Cluster in the tick''s own lock order, verify MUST_MOVE, ask the verdict, stop if below the ON threshold, set PENDING_ON, halt dealing on every live table of the Cluster and cancel its pending seat moves. It converts nothing: no epoch moves and no pool session is created, because the specification creates the Epoch at step 13 after the re-check, which is what makes an abort cheap. Idempotent on conversion_request_id.';


--
-- TOC entry 6062 (class 1255 OID 21011671)
-- Name: fn_cash_cluster_census(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_census(p_game_id uuid, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS public.cash_cluster_census_row[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT coalesce(array_agg(
           (q.id, q.role, q.main_index, q.lifecycle, q.status, q.created_at, q.max_players,
            q.seated, q.reserved, GREATEST(0, q.max_players - q.seated - q.reserved),
            q.lifecycle = 'breaking')::public.cash_cluster_census_row
           ORDER BY q.created_at), '{}'::public.cash_cluster_census_row[])
    FROM (
      SELECT tb.id, tb.role, tb.main_index, tb.lifecycle, tb.status, tb.created_at,
             coalesce(tb.max_players, 9) AS max_players,
             (SELECT count(*) FROM public.table_seats ts WHERE ts.table_id = tb.id AND ts.left_at IS NULL)::integer AS seated,
             (SELECT count(*) FROM public.table_waitlist w
               WHERE w.table_id = tb.id AND w.status = 'notified' AND w.hold_expires_at > p_now)::integer AS reserved
        FROM public.tables tb
       WHERE tb.cluster_id = p_game_id AND coalesce(tb.is_deleted, false) = false
         AND coalesce(tb.lifecycle, '') <> 'closed'
    ) q;
$$;


ALTER FUNCTION public.fn_cash_cluster_census(p_game_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 3536 (class 1255 OID 49231912)
-- Name: fn_cash_cluster_commit_lightning(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_commit_lightning(p_game_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g          record;
  v_conv     record;
  v_state    jsonb;
  v_inflight integer;
  v_before   numeric;
  v_after    numeric;
  v_locked_seats uuid[];
  v_seated   integer;
  v_pool     integer;
  v_orphan   integer;
  v_stranded integer;
  v_epoch    integer;
  v_unobserved        integer;
  v_unobserved_tables jsonb;
  v_stragglers        integer;
BEGIN
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'converted', false, 'reason', 'platform_frozen');
  END IF;

  -- LIGHTNING PHASE 7 REMEDIATION (20261007222717): THE HAND BOUNDARY IS
  -- POLLED BEFORE THE LOCK. The tick asks this every pass while the member
  -- tables finish their hands, and the cheap not-ready answer does not need,
  -- and no longer takes, the Cluster row every formation, tick and conversion
  -- serialises on. The authoritative count below still runs under the lock.
  SELECT count(*)::integer INTO v_inflight
    FROM public.hand_state_snapshots h
    JOIN public.tables tb ON tb.id = h.table_id
   WHERE tb.cluster_id = p_game_id
     AND coalesce(tb.is_deleted, false) = false
     AND coalesce(tb.lifecycle, '') <> 'closed'
     AND h.is_complete = false
     AND h.updated_at > clock_timestamp() - interval '6 hours';
  IF v_inflight > 0 THEN
    RETURN jsonb_build_object('ok', false, 'converted', false, 'reason', 'hands_in_flight',
      'hands_in_flight', v_inflight);
  END IF;

  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'converted', false, 'reason', 'not_found');
  END IF;

  SELECT * INTO v_conv FROM public.cash_cluster_conversion
   WHERE cluster_id = g.id AND conversion_request_id = p_request_id;
  IF NOT FOUND THEN
    IF EXISTS (SELECT 1 FROM public.cash_cluster_conversion
                WHERE conversion_request_id = p_request_id) THEN
      RETURN jsonb_build_object('ok', false, 'converted', false,
        'reason', 'request_id_belongs_to_another_cluster');
    END IF;
    RETURN jsonb_build_object('ok', false, 'converted', false, 'reason', 'no_such_conversion');
  END IF;

  -- F13, the half a lock cannot give you. A retry of a request that already
  -- committed is answered with what happened, not refused: a worker that is
  -- told "no" retries, and a worker that is told "committed at epoch 3"
  -- stops.
  IF v_conv.status = 'committed' THEN
    -- converted IS READ OFF THE CLUSTER, NOT OFF THE RECORD. An earlier cut
    -- asserted converted: true from v_conv.status alone, before any test of
    -- the mode. The record says what this conversion DID; the mode says what
    -- the Cluster IS, and Phase 10's revert will make those two different by
    -- design - a Cluster back in must_move whose conversion row still says
    -- committed. Answering converted: true about it would be the same defect
    -- begin_pending_on carried: the truth in the payload and the boolean
    -- wrong. ok stays true because the request did succeed; converted says
    -- whether the Cluster is Lightning now.
    RETURN jsonb_build_object('ok', true,
      'converted', g.cluster_mode = 'lightning',
      'reason', 'already_committed',
      'conversion_id', v_conv.id, 'epoch_after', v_conv.epoch_after,
      'cluster_mode', g.cluster_mode);
  END IF;
  IF v_conv.status <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'converted', false,
      'reason', 'conversion_already_closed',
      'status', v_conv.status, 'abort_reason', v_conv.abort_reason,
      'cluster_mode', g.cluster_mode);
  END IF;
  IF g.cluster_mode <> 'pending_on' THEN
    RETURN jsonb_build_object('ok', false, 'converted', false, 'reason', 'wrong_state',
      'cluster_mode', g.cluster_mode);
  END IF;

  -- Step 9.
  SELECT count(*)::integer INTO v_inflight
    FROM public.hand_state_snapshots h
    JOIN public.tables tb ON tb.id = h.table_id
   WHERE tb.cluster_id = g.id
     -- THE SAME TABLE FILTERS THE REST OF THIS FILE CARRIES. Without them an
     -- abandoned ended_at IS NULL row on a CLOSED or soft-deleted table blocks
     -- the conversion for six hours and no operator can clear it, because
     -- nothing will ever end a hand at a table that is gone. That is the exact
     -- wedge the six-hour window was chosen to prevent, arriving by a
     -- different door.
     AND coalesce(tb.is_deleted, false) = false
     AND coalesce(tb.lifecycle, '') <> 'closed'
     AND h.is_complete = false
     AND h.updated_at > clock_timestamp() - interval '6 hours';
  IF v_inflight > 0 THEN
    RETURN jsonb_build_object('ok', false, 'converted', false, 'reason', 'hands_in_flight',
      'hands_in_flight', v_inflight);
  END IF;

  -- THE HALT IS A STOP ONLY ONCE THE ENGINE HAS SEEN IT (2026-09-26). A member
  -- table that is not halted at all is halted now; then every live member
  -- table an engine holds an unexpired lease on must have observed its halt.
  UPDATE public.tables tb
     SET dealing_halted_at = clock_timestamp(), dealing_halted_reason = 'lightning_pending_on'
   WHERE tb.cluster_id = g.id
     AND tb.dealing_halted_at IS NULL
     AND coalesce(tb.is_deleted, false) = false
     AND coalesce(tb.lifecycle, '') <> 'closed';
  GET DIAGNOSTICS v_stragglers = ROW_COUNT;

  SELECT count(*)::integer, coalesce(jsonb_agg(tb.id ORDER BY tb.id), '[]'::jsonb)
    INTO v_unobserved, v_unobserved_tables
    FROM public.tables tb
    JOIN public.engine_table_leases l ON l.table_id = tb.id
   WHERE tb.cluster_id = g.id
     AND coalesce(tb.is_deleted, false) = false
     AND coalesce(tb.lifecycle, '') <> 'closed'
     AND l.heartbeat_at >= clock_timestamp() - make_interval(secs => public.fn_engine_lease_stale_seconds())
     AND (tb.dealing_halted_at IS NULL
          OR tb.dealing_halt_observed_at IS NULL
          OR tb.dealing_halt_observed_at < tb.dealing_halted_at);
  IF v_unobserved > 0 OR v_stragglers > 0 THEN
    RETURN jsonb_build_object('ok', false, 'converted', false, 'reason', 'halt_not_observed',
      'tables_not_observed', v_unobserved, 'tables', v_unobserved_tables,
      'tables_newly_halted', v_stragglers);
  END IF;

  -- Steps 10 and 11.
  v_state := public.fn_cash_cluster_lightning_state(g.id);
  IF NOT coalesce((v_state -> 'verdict' ->> 'would_turn_on')::boolean, false) THEN
    -- 'converted' EXISTS BECAUSE 'ok' CANNOT CARRY THIS. A successful abort is
    -- ok: the function did exactly what it should. But a caller that branches
    -- on ok alone would read a self-abort as a conversion, so the one question
    -- a caller actually has - did this Cluster become Lightning - is answered
    -- by its own boolean rather than by reading a reason string.
    RETURN public.fn_cash_cluster_abort_pending_on(
      g.id, p_request_id, 'population_fell_below_on_threshold_at_boundary')
      || jsonb_build_object('ok', false, 'converted', false);
  END IF;

  -- A pool session MUST name a cash session; the column is NOT NULL, and the
  -- subordination is the point: "Entering/exiting Lightning does not create a
  -- new cash session." So a seated eligible player with no open Cluster
  -- session cannot enter the pool, and this refuses the whole conversion
  -- rather than converting around them - leaving an eligible player seated at
  -- a table that has stopped dealing, in a Cluster that believes it is a pool,
  -- is the stranding the specification forbids.
  --
  -- Measured before this was written: on the busiest live Cluster, all 34
  -- eligible players carry an open session with cluster_id set, and the estate
  -- has 174 open Cluster sessions against 169 live Cluster chairs. This is
  -- therefore a refusal that should never fire, which is exactly the kind that
  -- must be counted rather than assumed.
  -- PER PLAYER, NOT PER SEAT, AND ASKING THE INSERT'S OWN QUESTION. An earlier
  -- cut counted seat ROWS, so a player seated on two member boards whose only
  -- open session was scoped to one of them was counted an orphan against the
  -- other seat - and refused the whole Cluster's conversion while the INSERT
  -- would happily have found their session. Both now ask: does this PLAYER
  -- have an open session reachable from ANY of their seats in this Cluster.
  SELECT count(*)::integer INTO v_orphan FROM (
    SELECT ts.user_id
      FROM public.table_seats ts
      JOIN public.tables tb ON tb.id = ts.table_id
     WHERE tb.cluster_id = g.id AND coalesce(tb.is_deleted, false) = false
       AND coalesce(tb.lifecycle, '') <> 'closed'
       AND ts.left_at IS NULL AND ts.user_id IS NOT NULL
       AND coalesce(ts.is_sitting_out, false) = false
       AND coalesce(ts.leave_pending, false) = false
       AND coalesce(ts.stack, 0) > 0
     GROUP BY ts.user_id
    HAVING NOT EXISTS (
       SELECT 1 FROM public.cash_player_session s
        WHERE s.player_id = ts.user_id AND s.closed_at IS NULL
          AND (s.cluster_id = g.id
               OR s.scope_id IN (SELECT id FROM public.tables WHERE cluster_id = g.id)
               OR s.table_id IN (SELECT id FROM public.tables WHERE cluster_id = g.id)))
  ) o;
  IF v_orphan > 0 THEN
    RETURN public.fn_cash_cluster_abort_pending_on(
      g.id, p_request_id, format('%s eligible seated player(s) have no open cash session', v_orphan))
      || jsonb_build_object('ok', false, 'converted', false);
  END IF;

  -- A CONVERSION LOCKS THE SEATS IT ENTERS (2026-10-09, Phase 12 load and
  -- chaos): the live seats FOR SHARE in seat-id order, the order
  -- fn_cash_cluster_commit_must_move takes, before anything below reads
  -- them. A player standing up at this moment either finishes first (and is
  -- then no longer live here) or waits for this commit (and the seat
  -- trigger then closes the pool session it can now see). Without it the
  -- departing seat entered the pool after its own trigger had run, and the
  -- ghost session refused every later reversion. The chip total is taken
  -- over exactly the seats locked here (and any row this transaction wrote),
  -- so an arrival committing in between is not mistaken for moved money.
  SELECT coalesce(array_agg(x.id ORDER BY x.id), ARRAY[]::uuid[]) INTO v_locked_seats FROM (
    SELECT ts.id FROM public.table_seats ts
     WHERE ts.left_at IS NULL
       AND ts.table_id IN (SELECT tb.id FROM public.tables tb WHERE tb.cluster_id = g.id)
     ORDER BY ts.id
       FOR SHARE) x;

  -- THE MODE CHANGES UNDER THE CLUSTER'S MODE LOCK (2026-10-15, Lightning
  -- Phase 12 load and chaos): EXCLUSIVE, after the seat FOR SHARE above (a
  -- seat writer holds its row until its commit, where its deferred trigger
  -- asks for this lock SHARED; waiting for a seat while holding this would
  -- deadlock with it) and before anything below reads the seats into the
  -- pool. Every arrival whose seat trigger got in first has committed by the
  -- time this returns, and each statement below takes a fresh snapshot, so
  -- the pool INSERT enters it; every arrival after waits for this commit and
  -- reads 'lightning' itself. Nothing below takes a seat row lock.
  PERFORM pg_advisory_xact_lock(
    pg_catalog.hashtextextended('lightning_cluster_mode:' || g.id::text, 0));

  -- Step 12, first half.
  SELECT coalesce(sum(ts.stack), 0) INTO v_before
    FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.cluster_id = g.id AND ts.left_at IS NULL
     AND (ts.id = ANY (v_locked_seats) OR ts.xmin = pg_current_xact_id()::xid);

  -- Step 13. ca.epoch_reason is read by fn_cash_cluster_epoch_follows_its_game
  -- for cash_cluster_epoch.started_by; without it the row records 'unstated',
  -- and an epoch nobody can explain is an epoch nobody can audit.
  PERFORM set_config('ca.epoch_reason', 'lightning_on', true);
  -- The epoch writer records cluster_epoch_started with this request.
  PERFORM set_config('ca.request_id', p_request_id::text, true);
  v_epoch := g.cluster_epoch + 1;
  -- 20261008043021: A STALE DWELL SIGHTING DOES NOT SURVIVE RE-CONVERSION.
  -- A sighting recorded in a previous Lightning epoch would otherwise let the
  -- new epoch open PENDING_OFF on one observation.
  UPDATE public.cash_games
     SET cluster_mode = 'lightning', cluster_epoch = v_epoch, lightning_off_condition_since = NULL, updated_at = now()
   WHERE id = g.id;

  -- Steps 14 to 19. THE ONLY WRITE THAT CREATES ANYTHING FOR A PLAYER, AND IT
  -- POINTS AT WHAT THEY ALREADY HAD. cash_player_session_id is the player's
  -- EXISTING open session - not a new one. "A Lightning Pool Session is
  -- subordinate to the continuous Cash Player Session. Entering/exiting
  -- Lightning does not create a new cash session."
  --
  -- The eligibility predicate is fn_cash_cluster_live_eligible's seated half,
  -- restated here because that function returns a COUNT and this needs the
  -- SET. They must agree exactly: a player counted toward the threshold who
  -- did not enter the pool is a player the conversion left behind, and one who
  -- entered without being counted is a player who arrived from nowhere. The
  -- read-back asserts the two agree rather than trusting that they do.
  --
  -- NO is_horse ANYWHERE. Law 10.5: a horse counts exactly like a human, and
  -- is pinned twice in TheTablesOpenAndCloseThemselves.law.test.ts against the
  -- worklist and the balancer. A horse over the threshold enters the pool like
  -- anyone else.
  INSERT INTO public.lightning_pool_session (
    cluster_id, cluster_epoch, player_id, cash_player_session_id,
    state, entered_at, starting_stack, anchor_seat_id)
  SELECT DISTINCT ON (ts.user_id)
         g.id, v_epoch, ts.user_id,
         (SELECT s.id FROM public.cash_player_session s
           WHERE s.player_id = ts.user_id AND s.closed_at IS NULL
             AND (s.cluster_id = g.id
                  OR s.scope_id IN (SELECT id FROM public.tables WHERE cluster_id = g.id)
                  OR s.table_id IN (SELECT id FROM public.tables WHERE cluster_id = g.id))
           -- coalesce, NOT a bare boolean DESC. cash_player_session.cluster_id
           -- is a nullable added column, so for a session matched only by its
           -- table scope the key is NULL - and DESC implies NULLS FIRST, which
           -- put exactly the session this ORDER BY exists to deprioritise at
           -- the top. A player holding both an open cluster-scoped session and
           -- an open table-scoped one - a shape cash_player_session_one_open
           -- explicitly permits - got the wrong parent on their pool session.
           ORDER BY coalesce(s.cluster_id = g.id, false) DESC, s.opened_at DESC, s.id LIMIT 1),
         'active', clock_timestamp(), ts.stack, ts.id
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.cluster_id = g.id AND coalesce(tb.is_deleted, false) = false
     AND coalesce(tb.lifecycle, '') <> 'closed'
     AND ts.left_at IS NULL
     AND ts.user_id IS NOT NULL
     AND coalesce(ts.is_sitting_out, false) = false
     AND coalesce(ts.leave_pending, false) = false
     AND coalesce(ts.stack, 0) > 0
   ORDER BY ts.user_id, ts.joined_at, ts.id;
  GET DIAGNOSTICS v_pool = ROW_COUNT;

  -- pool_player_joined, one per player the conversion entered (2026-09-26).
  INSERT INTO public.cash_cluster_events (game_id, kind, payload, cluster_epoch, request_id)
  SELECT g.id, 'pool_player_joined', jsonb_build_object(
           'cluster_id', g.id, 'cluster_epoch', v_epoch, 'player_id', ps.player_id,
           'pool_session_id', ps.id, 'anchor_seat_id', ps.anchor_seat_id,
           'starting_stack', ps.starting_stack, 'cash_player_session_id', ps.cash_player_session_id,
           'via', 'fn_cash_cluster_commit_lightning', 'conversion_id', v_conv.id, 'at', ps.entered_at),
         v_epoch, p_request_id
    FROM public.lightning_pool_session ps
   WHERE ps.cluster_id = g.id AND ps.cluster_epoch = v_epoch AND ps.exited_at IS NULL
   ORDER BY ps.entered_at, ps.id;

  -- The halt is re-stamped rather than lifted. The tables are still not
  -- dealing, and now they are not dealing because the Cluster IS Lightning
  -- rather than because it is deciding - which is the difference Phase 10's
  -- revert will match on.
  --
  -- IT ALSO CATCHES A TABLE THAT ARRIVED AFTER step 6. An earlier cut matched
  -- only rows already carrying 'lightning_pending_on', so a table opened
  -- between PENDING_ON and here would have joined a Lightning Cluster and gone
  -- on dealing. The stood-down tick should make that unreachable; "should be
  -- unreachable" is the reason a guard is cheap, not the reason to omit it.
  UPDATE public.tables
     SET dealing_halted_at = coalesce(dealing_halted_at, clock_timestamp()),
         dealing_halted_reason = 'lightning'
   WHERE cluster_id = g.id
     AND coalesce(is_deleted, false) = false
     AND coalesce(lifecycle, '') <> 'closed'
     -- ONLY A HALT THIS CONVERSION PLACED, OR NO HALT AT ALL. `IS DISTINCT FROM
     -- 'lightning'` alone would rewrite a halt somebody else put there into
     -- one of ours, and Phase 10's revert - which matches on the reason -
     -- would then lift it. begin_pending_on already leaves a foreign halt
     -- alone and abort_pending_on already lifts only its own; this is the
     -- third of the three and it was the one that did not.
     AND (dealing_halted_at IS NULL OR dealing_halted_reason = 'lightning_pending_on');

  -- Step 12, second half. This cannot fail as written; it is here so that it
  -- starts failing the day somebody adds a write to table_seats above it.
  SELECT coalesce(sum(ts.stack), 0) INTO v_after
    FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.cluster_id = g.id AND ts.left_at IS NULL
     AND (ts.id = ANY (v_locked_seats) OR ts.xmin = pg_current_xact_id()::xid);
  IF v_after IS DISTINCT FROM v_before THEN
    RAISE EXCEPTION 'LIGHTNING_CONVERSION_MOVED_MONEY: cluster % chip total went from % to %, and a mode change is a seating transition, not an economic transaction',
      g.id, v_before, v_after USING ERRCODE = 'check_violation';
  END IF;

  SELECT count(DISTINCT ts.user_id)::integer INTO v_seated
    FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.cluster_id = g.id AND coalesce(tb.is_deleted, false) = false
     AND coalesce(tb.lifecycle, '') <> 'closed'
     AND ts.left_at IS NULL AND ts.user_id IS NOT NULL
     AND coalesce(ts.is_sitting_out, false) = false
     AND coalesce(ts.leave_pending, false) = false
     AND coalesce(ts.stack, 0) > 0;

  -- Nobody eligible may be left behind. This is the F15 half that a count
  -- cannot see: a Fast Fold storm at the threshold changes who is eligible,
  -- and the set that entered the pool must be the set that was counted.
  IF v_pool <> v_seated THEN
    RAISE EXCEPTION 'LIGHTNING_CONVERSION_LEFT_SOMEBODY_BEHIND: cluster % counted % eligible seated players and created % pool sessions',
      g.id, v_seated, v_pool USING ERRCODE = 'check_violation';
  END IF;

  -- AND THE ASSERTION THAT COUNTING CANNOT MAKE. v_pool and v_seated share a
  -- predicate, so a predicate that wrongly EXCLUDES a table makes both numbers
  -- smaller and they still agree - which is exactly how the nullable
  -- tables.lifecycle nearly stranded people here: the halt coalesced the NULL
  -- and the player-set queries did not, so a NULL-lifecycle table was stopped
  -- while its seated players were left out of the pool, at a table that was no
  -- longer dealing, in a Cluster that believed it owned them.
  --
  -- This asks the question from the OTHER side, over the tables this
  -- conversion actually halted, and it cannot be satisfied by a filter that
  -- narrows: if we stopped a table, every eligible player sitting at it must
  -- have somewhere to play.
  SELECT count(DISTINCT ts.user_id)::integer INTO v_stranded
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.cluster_id = g.id
     AND coalesce(tb.is_deleted, false) = false
     AND coalesce(tb.lifecycle, '') <> 'closed'
     AND tb.dealing_halted_at IS NOT NULL
     AND ts.left_at IS NULL AND ts.user_id IS NOT NULL
     AND coalesce(ts.is_sitting_out, false) = false
     AND coalesce(ts.leave_pending, false) = false
     AND coalesce(ts.stack, 0) > 0
     AND NOT EXISTS (SELECT 1 FROM public.lightning_pool_session s
                      WHERE s.cluster_id = g.id AND s.player_id = ts.user_id
                        AND s.cluster_epoch = v_epoch AND s.exited_at IS NULL);
  IF v_stranded > 0 THEN
    RAISE EXCEPTION 'LIGHTNING_CONVERSION_STRANDED_A_PLAYER: cluster % stopped a table with % eligible player(s) on it who have no pool session',
      g.id, v_stranded USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.cash_cluster_conversion
     SET status = 'committed', epoch_after = v_epoch, closed_at = clock_timestamp(),
         chips_at_commit = v_before
   WHERE id = v_conv.id;

  -- Step 22.
  INSERT INTO public.cash_cluster_events (game_id, kind, payload, request_id)
  VALUES (g.id, 'lightning_on', jsonb_build_object(
    'conversion_id', v_conv.id, 'conversion_request_id', p_request_id,
    'from_mode', 'must_move', 'to_mode', 'lightning',
    'trigger_population', coalesce((v_state -> 'verdict' ->> 'live_eligible')::integer, 0),
    'on_threshold', coalesce((v_state -> 'thresholds' ->> 'on')::integer, 0),
    'off_threshold', coalesce((v_state -> 'thresholds' ->> 'off')::integer, 0),
    'epoch_before', g.cluster_epoch, 'epoch_after', v_epoch,
    'pool_sessions', v_pool, 'chip_total', v_before), p_request_id);

  RETURN jsonb_build_object('ok', true, 'converted', true, 'reason', 'lightning',
    'conversion_id', v_conv.id, 'cluster_mode', 'lightning',
    'epoch_before', g.cluster_epoch, 'epoch_after', v_epoch,
    'pool_sessions', v_pool, 'chip_total', v_before,
    'trigger_population', coalesce((v_state -> 'verdict' ->> 'live_eligible')::integer, 0));
END;
$$;


ALTER FUNCTION public.fn_cash_cluster_commit_lightning(p_game_id uuid, p_request_id uuid) OWNER TO postgres;

--
-- TOC entry 46447 (class 0 OID 0)
-- Dependencies: 3536
-- Name: FUNCTION fn_cash_cluster_commit_lightning(p_game_id uuid, p_request_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_commit_lightning(p_game_id uuid, p_request_id uuid) IS 'Steps 9 to 22 of the MUST-MOVE -> LIGHTNING sequence, in one transaction under the Cluster row lock: wait for the conversion-safe hand boundary (defined here, because the specification names it once and never defines it: no hand_history row of this Cluster with ended_at NULL that started within six hours), re-ask the population and abort if it fell, bump the Epoch with a stated reason, create one Lightning Pool Session per eligible seated player pointing at the cash session they ALREADY had, re-stamp the halt and emit lightning_on. It writes no table_seats row at all, and asserts the chip total is unchanged and that every counted player entered the pool.';


--
-- TOC entry 3780 (class 1255 OID 83676739)
-- Name: fn_cash_cluster_commit_must_move(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_commit_must_move(p_game_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g            record;
  v_conv       record;
  v_state      jsonb;
  v_live       integer;
  v_off        integer;
  v_inflight   integer;
  v_before     text;
  v_after      text;
  v_chips      numeric;
  v_epoch      integer;
  v_sessions   integer := 0;
  v_players    jsonb := '[]'::jsonb;
  v_slots      integer := 0;
  v_expired    integer := 0;
  v_released   integer := 0;
  v_tables     integer := 0;
  v_halted     integer := 0;
  v_stranded   integer := 0;
  v_open       integer := 0;
  v_locked_seats    uuid[];
  v_locked_sessions uuid[];
  v_drained         boolean := false;
BEGIN
  -- GATED, because this is the step that lets the physical tables deal again.
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'reverted', false, 'ready', false, 'reason', 'platform_frozen');
  END IF;

  -- LIGHTNING PHASE 7 REMEDIATION (20261007222717): THE DRAIN IS POLLED
  -- BEFORE THE LOCK. The tick asks this every pass while the drain empties,
  -- and the cheap not-ready answer does not need, and no longer takes, the
  -- Cluster row every formation, tick and conversion serialises on. The
  -- authoritative count below still runs under the lock.
  SELECT count(*)::integer INTO v_inflight
    FROM public.lightning_instance li
   WHERE li.cluster_id = p_game_id AND li.state IN ('forming', 'reserved', 'dealing', 'settling');
  IF v_inflight > 0 THEN
    RETURN jsonb_build_object('ok', false, 'reverted', false, 'ready', false,
      'reason', 'instances_in_flight', 'instances_in_flight', v_inflight,
      'cluster_mode', (SELECT cluster_mode FROM public.cash_games WHERE id = p_game_id));
  END IF;

  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reverted', false, 'reason', 'not_found');
  END IF;

  SELECT * INTO v_conv FROM public.cash_cluster_conversion
   WHERE cluster_id = g.id AND conversion_request_id = p_request_id;
  IF NOT FOUND THEN
    IF EXISTS (SELECT 1 FROM public.cash_cluster_conversion
                WHERE conversion_request_id = p_request_id) THEN
      RETURN jsonb_build_object('ok', false, 'reverted', false,
        'reason', 'request_id_belongs_to_another_cluster');
    END IF;
    RETURN jsonb_build_object('ok', false, 'reverted', false, 'reason', 'no_such_conversion');
  END IF;
  IF v_conv.to_mode IS DISTINCT FROM 'must_move' THEN
    RETURN jsonb_build_object('ok', false, 'reverted', false,
      'reason', 'not_a_pending_off_conversion', 'to_mode', v_conv.to_mode);
  END IF;
  -- A RETRY OF A COMMITTED REVERSION is told what happened. reverted is read
  -- off the Cluster, as commit_lightning's converted is: the record says what
  -- this conversion did, the mode says what the Cluster is now.
  IF v_conv.status = 'committed' THEN
    RETURN jsonb_build_object('ok', true, 'reverted', g.cluster_mode = 'must_move',
      'reason', 'already_committed', 'conversion_id', v_conv.id,
      'epoch_after', v_conv.epoch_after, 'cluster_mode', g.cluster_mode);
  END IF;
  IF v_conv.status <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'reverted', false,
      'reason', 'conversion_already_closed', 'status', v_conv.status,
      'abort_reason', v_conv.abort_reason, 'cluster_mode', g.cluster_mode);
  END IF;
  IF g.cluster_mode IS DISTINCT FROM 'pending_off' THEN
    RETURN jsonb_build_object('ok', false, 'reverted', false, 'reason', 'wrong_state',
      'cluster_mode', g.cluster_mode);
  END IF;

  -- SPECIFICATION STEP 10. A population that rose back above OFF before the
  -- drain point cancels the reversion, while Lightning is still enabled.
  v_state := public.fn_cash_cluster_lightning_state(g.id);
  v_live  := coalesce((v_state -> 'verdict' ->> 'live_eligible')::integer, 0);
  v_off   := coalesce((v_state -> 'thresholds' ->> 'off')::integer, 0);
  IF coalesce(g.lightning_enabled, false) AND g.enabled IS NOT DISTINCT FROM true AND v_live > v_off THEN
    RETURN public.fn_cash_cluster_abort_pending_off(
      g.id, p_request_id, 'population_rose_above_off_threshold_before_the_drain_point')
      || jsonb_build_object('ok', false, 'reverted', false);
  END IF;

  -- THE DRAIN POINT. Not a raise: a structured not-ready answer the caller
  -- polls, exactly as commit_lightning answers hands_in_flight.
  SELECT count(*)::integer INTO v_inflight
    FROM public.lightning_instance li
   WHERE li.cluster_id = g.id AND li.state IN ('forming', 'reserved', 'dealing', 'settling');
  IF v_inflight > 0 THEN
    RETURN jsonb_build_object('ok', false, 'reverted', false, 'ready', false,
      'reason', 'instances_in_flight', 'instances_in_flight', v_inflight,
      'cluster_mode', g.cluster_mode);
  END IF;

  -- THE MONEY, AS EVERY COLUMN OF EVERY ROW. A sum is satisfied by two stacks
  -- that swapped; this is not. Seats of every member table, the Cluster's
  -- cash sessions (baseline, stay clock, rejoin window, join time), and its
  -- blind ledger (what is owed). This transition writes none of them.
  -- THE MONEY, AS EVERY COLUMN OF EVERY LIVE ROW, UNDER ROW LOCKS
  -- (20261007222717). The two digests used to run unlocked at READ COMMITTED
  -- over every historical row, so ordinary concurrent seat or session traffic
  -- committing between them - an engine is_sitting_out update, a departure
  -- request, a session evaluation - could trip the assertion as a false
  -- alarm, and its cost grew with the Cluster's whole history. The live rows
  -- are taken FOR SHARE first, in the estate's order: the Cluster row is
  -- already held FOR UPDATE, then the seats in seat-id order (as formation
  -- takes its anchors), then the open cash sessions, then the blind ledger.
  -- Both digests cover exactly those live rows; a row already dead cannot
  -- change under this transaction's locks and proves nothing about what this
  -- transition wrote.
  -- THE REVERSION COMPARES THE ROWS IT LOCKED (2026-10-09, Phase 12 load
  -- and chaos): the same locks in the same order, and the ids they took are
  -- kept, so both digests below cover exactly those rows (and any row this
  -- transaction wrote). A row lock cannot stop an INSERT: a player arriving
  -- during the drain whose seat and cash session committed between the two
  -- digests tripped LIGHTNING_REVERSION_MOVED_MONEY although nothing here
  -- moved (measured in the conversion storm, a false financial alarm).
  SELECT coalesce(array_agg(x.id ORDER BY x.id), ARRAY[]::uuid[]) INTO v_locked_seats FROM (
    SELECT ts.id FROM public.table_seats ts
     WHERE ts.left_at IS NULL
       AND ts.table_id IN (SELECT tb.id FROM public.tables tb WHERE tb.cluster_id = g.id)
     ORDER BY ts.id
       FOR SHARE) x;
  SELECT coalesce(array_agg(x.id ORDER BY x.id), ARRAY[]::uuid[]) INTO v_locked_sessions FROM (
    SELECT s.id FROM public.cash_player_session s
     WHERE s.cluster_id = g.id AND s.closed_at IS NULL
     ORDER BY s.id
       FOR SHARE) x;
  PERFORM 1 FROM public.lightning_blind_ledger bl
   WHERE bl.cluster_id = g.id
   ORDER BY bl.player_id
   FOR SHARE;
  -- THE MODE CHANGES UNDER THE CLUSTER'S MODE LOCK (2026-10-15, Lightning
  -- Phase 12 load and chaos): EXCLUSIVE, after the row locks above and
  -- before the pool is closed. An arrival whose seat trigger read
  -- 'lightning' first (the drain opens PENDING_OFF and reverts in one
  -- transaction) has committed its pool session when this returns, and the
  -- close below sees it; one after waits for this commit and reads
  -- 'must_move'. No pool session at the old epoch outlives the reversion.
  PERFORM pg_advisory_xact_lock(
    pg_catalog.hashtextextended('lightning_cluster_mode:' || g.id::text, 0));

  SELECT md5(coalesce(string_agg(x.r, '|' ORDER BY x.r), '')) INTO v_before FROM (
      SELECT 'ts:' || to_jsonb(ts)::text AS r
        FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
       WHERE tb.cluster_id = g.id AND ts.left_at IS NULL
         AND (ts.id = ANY (v_locked_seats) OR ts.xmin = pg_current_xact_id()::xid)
      UNION ALL
      SELECT 'cps:' || to_jsonb(s)::text FROM public.cash_player_session s
       WHERE s.cluster_id = g.id AND s.closed_at IS NULL
         AND (s.id = ANY (v_locked_sessions) OR s.xmin = pg_current_xact_id()::xid)
      UNION ALL
      SELECT 'bl:' || to_jsonb(bl)::text FROM public.lightning_blind_ledger bl WHERE bl.cluster_id = g.id
    ) x;
  SELECT coalesce(sum(ts.stack), 0) INTO v_chips
    FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.cluster_id = g.id AND ts.left_at IS NULL;

  -- EVERY OPEN POOL SESSION EXITS, ONE pool_player_left EACH. The cash
  -- session it is subordinate to stays open: leaving Lightning does not end
  -- the player's cash session, and the anchor seat they never left is where
  -- they now play.
  -- LIGHTNING PHASE 13 (20261009235505): AN EMERGENCY DRAIN SAYS SO. The
  -- sessions a drain releases exit 'lightning_drained', the ones a falling
  -- population releases 'lightning_off'; the transition is the same.
  v_drained := EXISTS (SELECT 1 FROM public.lightning_cluster_drain d
                        WHERE d.cluster_id = g.id AND d.completed_at IS NULL);
  WITH exited AS (
    UPDATE public.lightning_pool_session ps
       SET exited_at = GREATEST(clock_timestamp(), ps.entered_at),
           exit_reason = CASE WHEN v_drained THEN 'lightning_drained' ELSE 'lightning_off' END,
           state = 'closed',
           ending_stack = public.fn_lightning_pool_stack(ps.id),
           updated_at = clock_timestamp()
     WHERE ps.cluster_id = g.id AND ps.exited_at IS NULL
    RETURNING ps.id, ps.cluster_epoch, ps.player_id, ps.anchor_seat_id, ps.ending_stack, ps.exited_at
  ), logged AS (
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload, cluster_epoch, request_id)
    SELECT g.id, ts.table_id, 'pool_player_left', jsonb_build_object(
             'cluster_id', g.id, 'cluster_epoch', e.cluster_epoch, 'player_id', e.player_id,
             'pool_session_id', e.id, 'anchor_seat_id', e.anchor_seat_id, 'reason', CASE WHEN v_drained THEN 'lightning_drained' ELSE 'lightning_off' END,
             'ending_stack', e.ending_stack, 'seat_table_id', ts.table_id, 'seat_number', ts.seat_number,
             'conversion_id', v_conv.id, 'at', e.exited_at),
           e.cluster_epoch, p_request_id
      FROM exited e LEFT JOIN public.table_seats ts ON ts.id = e.anchor_seat_id
    RETURNING 1
  )
  SELECT (SELECT count(*)::integer FROM exited),
         (SELECT coalesce(jsonb_agg(e.player_id ORDER BY e.player_id), '[]'::jsonb) FROM exited e),
         (SELECT count(*)::integer FROM exited e
           WHERE NOT EXISTS (SELECT 1 FROM public.table_seats ts
                              WHERE ts.id = e.anchor_seat_id AND ts.left_at IS NULL
                                AND ts.user_id = e.player_id)),
         (SELECT count(*)::integer FROM logged)
    INTO v_sessions, v_players, v_stranded, v_open;
  IF v_open IS DISTINCT FROM v_sessions THEN
    RAISE EXCEPTION 'LIGHTNING_REVERSION_LOST_AN_EVENT: cluster % exited % pool session(s) and logged % pool_player_left',
      g.id, v_sessions, v_open USING ERRCODE = 'check_violation';
  END IF;
  -- A PLAYER THE POOL LETS GO HAS A SEAT TO PLAY AT. The seat trigger exits a
  -- session the moment its anchor is left, so this cannot fire as written; it
  -- is here so that it fires the day something breaks that.
  IF v_stranded > 0 THEN
    RAISE EXCEPTION 'LIGHTNING_REVERSION_STRANDED_A_PLAYER: cluster % released % pool player(s) whose anchor seat is not theirs and live',
      g.id, v_stranded USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.lightning_pool_slot sl
     SET closed_at = GREATEST(clock_timestamp(), sl.opened_at), close_reason = 'lightning_off',
         updated_at = clock_timestamp()
   WHERE sl.cluster_id = g.id AND sl.closed_at IS NULL;
  GET DIAGNOSTICS v_slots = ROW_COUNT;

  -- Only Lightning-specific transient state is wiped. A pending reservation
  -- cannot outlive its instance in practice; one that did is expired, not
  -- deleted, so the row still says what happened to it.
  UPDATE public.lightning_reservation r
     SET state = 'expired', resolved_at = clock_timestamp(), reason = coalesce(r.reason, 'lightning_off')
   WHERE r.cluster_id = g.id AND r.state = 'pending';
  GET DIAGNOSTICS v_expired = ROW_COUNT;
  UPDATE public.lightning_reservation r
     SET state = 'released', resolved_at = clock_timestamp(), reason = coalesce(r.reason, 'lightning_off')
   WHERE r.cluster_id = g.id AND r.state = 'committed';
  GET DIAGNOSTICS v_released = ROW_COUNT;

  -- THE NEXT EPOCH, IN must_move. ca.epoch_reason is what the epoch writer
  -- records as started_by.
  PERFORM set_config('ca.epoch_reason', 'lightning_off', true);
  PERFORM set_config('ca.request_id', p_request_id::text, true);
  v_epoch := g.cluster_epoch + 1;
  UPDATE public.cash_games
     SET cluster_mode = 'must_move', cluster_epoch = v_epoch, updated_at = now()
   WHERE id = g.id;

  -- THE TABLES DEAL AGAIN. Only a halt Lightning placed is lifted; a halt
  -- somebody else put on a member table is theirs to lift. The engine polls
  -- the halt between hands, so this is what restarts the physical game.
  -- The engine's acknowledgement of that halt goes with it, so the next
  -- PENDING_ON waits for a fresh observation of its own halt.
  IF g.enabled IS NOT DISTINCT FROM true THEN
    UPDATE public.tables tb
       SET dealing_halted_at = NULL, dealing_halted_reason = NULL, dealing_halt_observed_at = NULL
     WHERE tb.cluster_id = g.id AND tb.dealing_halted_reason IN ('lightning', 'lightning_pending_on');
    GET DIAGNOSTICS v_tables = ROW_COUNT;
  ELSE
    -- 20261007222717: THE GAME ITSELF IS DISABLED. A reversion is a seating
    -- transition, not a licence to deal: the member tables stay halted for
    -- the game-close path that owns a disabled game, and the result and the
    -- event both say so (halts_kept_game_disabled).
    v_tables := 0;
  END IF;
  SELECT count(*)::integer INTO v_halted
    FROM public.tables tb
   WHERE tb.cluster_id = g.id AND tb.dealing_halted_at IS NOT NULL
     AND coalesce(tb.is_deleted, false) = false AND coalesce(tb.lifecycle, '') <> 'closed';

  SELECT md5(coalesce(string_agg(x.r, '|' ORDER BY x.r), '')) INTO v_after FROM (
      SELECT 'ts:' || to_jsonb(ts)::text AS r
        FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
       WHERE tb.cluster_id = g.id AND ts.left_at IS NULL
         AND (ts.id = ANY (v_locked_seats) OR ts.xmin = pg_current_xact_id()::xid)
      UNION ALL
      SELECT 'cps:' || to_jsonb(s)::text FROM public.cash_player_session s
       WHERE s.cluster_id = g.id AND s.closed_at IS NULL
         AND (s.id = ANY (v_locked_sessions) OR s.xmin = pg_current_xact_id()::xid)
      UNION ALL
      SELECT 'bl:' || to_jsonb(bl)::text FROM public.lightning_blind_ledger bl WHERE bl.cluster_id = g.id
    ) x;
  IF v_after IS DISTINCT FROM v_before THEN
    RAISE EXCEPTION 'LIGHTNING_REVERSION_MOVED_MONEY: cluster % seats, cash sessions or blind ledger changed across the reversion (% -> %), and a mode change is a seating transition, not an economic transaction',
      g.id, v_before, v_after USING ERRCODE = 'check_violation';
  END IF;

  SELECT count(*)::integer INTO v_open
    FROM public.lightning_pool_session ps WHERE ps.cluster_id = g.id AND ps.exited_at IS NULL;
  IF v_open > 0 THEN
    RAISE EXCEPTION 'LIGHTNING_REVERSION_LEFT_A_POOL_SESSION_OPEN: cluster % still has % open pool session(s) in must_move',
      g.id, v_open USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.cash_cluster_conversion
     SET status = 'committed', epoch_after = v_epoch, closed_at = clock_timestamp(),
         chips_at_commit = v_chips
   WHERE id = v_conv.id;

  INSERT INTO public.cash_cluster_events (game_id, kind, payload, request_id)
  VALUES (g.id, 'lightning_off', jsonb_build_object(
    'conversion_id', v_conv.id, 'conversion_request_id', p_request_id,
    'from_mode', 'lightning', 'to_mode', 'must_move',
    'trigger_population', v_conv.trigger_population, 'population_at_commit', v_live,
    'on_threshold', v_conv.on_threshold, 'off_threshold', v_conv.off_threshold,
    'epoch_before', g.cluster_epoch, 'epoch_after', v_epoch,
    'pool_sessions_exited', v_sessions, 'players', v_players, 'slots_closed', v_slots,
    'reservations_expired', v_expired, 'reservations_released', v_released,
    'tables_released', v_tables, 'tables_still_halted', v_halted,
    'halts_kept_game_disabled', g.enabled IS DISTINCT FROM true,
    'chip_total', v_chips, 'money_md5', v_before, 'drained', v_drained), p_request_id);

  RETURN jsonb_build_object('ok', true, 'reverted', true, 'ready', true, 'reason', 'must_move',
    'conversion_id', v_conv.id, 'cluster_mode', 'must_move',
    'epoch_before', g.cluster_epoch, 'epoch_after', v_epoch,
    'pool_sessions_exited', v_sessions, 'slots_closed', v_slots,
    'reservations_expired', v_expired, 'reservations_released', v_released,
    'tables_released', v_tables, 'tables_still_halted', v_halted,
    'halts_kept_game_disabled', g.enabled IS DISTINCT FROM true,
    'chip_total', v_chips, 'population_at_commit', v_live, 'drained', v_drained);
END;
$$;


ALTER FUNCTION public.fn_cash_cluster_commit_must_move(p_game_id uuid, p_request_id uuid) OWNER TO postgres;

--
-- TOC entry 46449 (class 0 OID 0)
-- Dependencies: 3780
-- Name: FUNCTION fn_cash_cluster_commit_must_move(p_game_id uuid, p_request_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_commit_must_move(p_game_id uuid, p_request_id uuid) IS 'Lightning Phase 7: PENDING_OFF -> MUST_MOVE once no instance is live (else {ready:false, reason:instances_in_flight}). Exits every pool session (lightning_off), closes slots, expires reservations, opens the next epoch, lifts the Lightning halt, emits lightning_off and one pool_player_left per player. Writes no seat, cash session or blind ledger row, asserted by md5.';


--
-- TOC entry 8428 (class 1255 OID 48931352)
-- Name: fn_cash_cluster_epoch_follows_its_game(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_epoch_follows_its_game() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.cash_cluster_epoch (cluster_id, epoch, mode, started_by, started_at)
    VALUES (NEW.id, NEW.cluster_epoch, NEW.cluster_mode, 'genesis', NEW.created_at)
    ON CONFLICT (cluster_id, epoch) DO NOTHING;
    IF FOUND THEN
      -- SPECIFICATION EVENT cluster_epoch_started (2026-09-26): the genesis epoch.
      INSERT INTO public.cash_cluster_events (game_id, kind, payload, cluster_epoch, request_id)
      VALUES (NEW.id, 'cluster_epoch_started', jsonb_build_object(
        'cluster_id', NEW.id, 'cluster_epoch', NEW.cluster_epoch, 'previous_epoch', NULL,
        'mode', NEW.cluster_mode, 'started_by', 'genesis', 'at', clock_timestamp()),
        NEW.cluster_epoch, CASE WHEN current_setting('ca.request_id', true) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             THEN current_setting('ca.request_id', true)::uuid END);
    END IF;
    RETURN NULL;
  END IF;

  IF NEW.cluster_epoch IS DISTINCT FROM OLD.cluster_epoch THEN
    IF NEW.cluster_epoch < OLD.cluster_epoch THEN
      RAISE EXCEPTION 'CLUSTER_EPOCH_GOES_FORWARD: cluster % cannot move from epoch % back to %',
        NEW.id, OLD.cluster_epoch, NEW.cluster_epoch
        USING ERRCODE = 'check_violation';
    END IF;
    UPDATE public.cash_cluster_epoch
       SET ended_at = clock_timestamp()
     WHERE cluster_id = NEW.id AND ended_at IS NULL;
    INSERT INTO public.cash_cluster_epoch (cluster_id, epoch, mode, started_by)
    VALUES (NEW.id, NEW.cluster_epoch, NEW.cluster_mode,
            coalesce(nullif(current_setting('ca.epoch_reason', true), ''), 'unstated'));
    -- SPECIFICATION EVENT cluster_epoch_started (2026-09-26).
    INSERT INTO public.cash_cluster_events (game_id, kind, payload, cluster_epoch, request_id)
    VALUES (NEW.id, 'cluster_epoch_started', jsonb_build_object(
      'cluster_id', NEW.id, 'cluster_epoch', NEW.cluster_epoch, 'previous_epoch', OLD.cluster_epoch,
      'mode', NEW.cluster_mode,
      'started_by', coalesce(nullif(current_setting('ca.epoch_reason', true), ''), 'unstated'),
      'at', clock_timestamp()),
      NEW.cluster_epoch, CASE WHEN current_setting('ca.request_id', true) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             THEN current_setting('ca.request_id', true)::uuid END);
    RETURN NULL;
  END IF;

  IF NEW.cluster_mode IS DISTINCT FROM OLD.cluster_mode THEN
    UPDATE public.cash_cluster_epoch
       SET mode = NEW.cluster_mode
     WHERE cluster_id = NEW.id AND ended_at IS NULL;
  END IF;
  RETURN NULL;
END;
$_$;


ALTER FUNCTION public.fn_cash_cluster_epoch_follows_its_game() OWNER TO postgres;

--
-- TOC entry 46451 (class 0 OID 0)
