-- Name: FUNCTION fn_cash_cluster_epoch_follows_its_game(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_epoch_follows_its_game() IS 'Keeps public.cash_cluster_epoch true of public.cash_games without anyone having to remember: the genesis row on INSERT, a closed row and a new open one when cluster_epoch moves forward, and the open row''s mode when cluster_mode moves. 20260921025504 created the table, backfilled it once and declared the invariant in a proof, and nothing maintained it - so the first Cluster created after it had no epoch row and could never have written a Lightning row at all.';


--
-- TOC entry 6304 (class 1255 OID 48839823)
-- Name: fn_cash_cluster_event_takes_the_clusters_epoch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_event_takes_the_clusters_epoch() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_epoch integer;
BEGIN
  IF NEW.cluster_epoch IS DISTINCT FROM 0 THEN
    RETURN NEW;
  END IF;
  SELECT g.cluster_epoch INTO v_epoch FROM public.cash_games g WHERE g.id = NEW.game_id;
  IF v_epoch IS NOT NULL AND v_epoch <> 0 THEN
    NEW.cluster_epoch := v_epoch;
  END IF;
  RETURN NEW;
END;
$$;


