--

COMMENT ON FUNCTION public.fn_cash_cluster_event_takes_the_clusters_epoch() IS 'Fills cash_cluster_events.cluster_epoch from the event''s own cluster when the row arrives at the column default of 0 and the cluster has moved past 0. 33 insert sites across the estate name no epoch; without this each one files its event under a genesis epoch the cluster has left.';


--
-- TOC entry 9227 (class 1255 OID 48841736)
-- Name: fn_cash_cluster_front_table(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_front_table(p_game_id uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT coalesce(
    -- The Cluster's Main 1, on the index that already exists for it.
    (SELECT t.id FROM public.tables t
      WHERE t.cluster_id = p_game_id AND t.role = 'main' AND t.main_index = 1
        AND t.lifecycle <> 'closed' AND coalesce(t.is_deleted, false) = false
      ORDER BY t.created_at, t.id LIMIT 1),
    -- Otherwise its oldest live table that is not breaking. A breaking table
    -- refuses every player it is sent (TABLE_CLOSING), so it must not be what
    -- the controller keys its eligible-horse map on.
    (SELECT t.id FROM public.tables t
      WHERE t.cluster_id = p_game_id
        AND t.lifecycle NOT IN ('closed', 'breaking') AND coalesce(t.is_deleted, false) = false
      ORDER BY t.created_at, t.id LIMIT 1),
    -- And only if every table it has is breaking, the oldest of those: a game
    -- that still exists is better represented by a closing table than by
    -- nothing at all.
    (SELECT t.id FROM public.tables t
      WHERE t.cluster_id = p_game_id
        AND t.lifecycle <> 'closed' AND coalesce(t.is_deleted, false) = false
      ORDER BY t.created_at, t.id LIMIT 1));
$$;


ALTER FUNCTION public.fn_cash_cluster_front_table(p_game_id uuid) OWNER TO postgres;

--
-- TOC entry 46455 (class 0 OID 0)
-- Dependencies: 9227
-- Name: FUNCTION fn_cash_cluster_front_table(p_game_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_front_table(p_game_id uuid) IS 'The one table that stands for a Cluster: its live Main 1 when it has one, otherwise its oldest live table that is not breaking, otherwise its oldest breaking one. A Lightning-capable Cluster begins as a single feeder and has no Main 1 at all, and every reader that asked for role = main AND main_index = 1 answered NULL for it. Three coalesced lookups rather than one ORDER BY: the first keeps the index condition the old subselect had, and no boolean is sorted, so a row with role main and a NULL main_index cannot sort ahead of the real Main 1.';


--
-- TOC entry 9319 (class 1255 OID 83676750)
-- Name: fn_cash_cluster_lightning_drive(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_lightning_drive(p_game_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g        record;
  v_state  jsonb;
  v_conv   record;
  v_n      integer;
  v_live   integer;
  v_off    integer;
  v_on_ok  boolean;
  v_off_ok boolean;
  v_live_ok boolean;
  v_action text;
  v_res    jsonb;
  v_mode   text;
  v_sqlstate text;
  v_message  text;
  v_drain    jsonb;
BEGIN
  SELECT cg.id, cg.cluster_mode, cg.cluster_epoch, cg.lightning_enabled, cg.enabled, cg.must_move
    INTO g FROM public.cash_games cg WHERE cg.id = p_game_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;

  -- ONE CLUSTER'S FAILURE IS ITS OWN. Everything below runs in this block's
  -- sub-transaction: a lock wait past the pass's lock_timeout, or any error,
  -- rolls back only this Cluster's step and is answered as a row and an
  -- event, and the tick pass goes on to the next Cluster.
  BEGIN

  -- ONE READER. The verdict is fn_cash_cluster_live_eligible against the
  -- configured thresholds; the hysteresis is the gap between ON and OFF, and
  -- nothing here re-derives either number.
  v_state  := public.fn_cash_cluster_lightning_state(g.id);
  v_on_ok  := coalesce((v_state -> 'verdict' ->> 'would_turn_on')::boolean, false);
  v_off_ok := coalesce((v_state -> 'verdict' ->> 'would_turn_off')::boolean, false);
  v_live   := coalesce((v_state -> 'verdict' ->> 'live_eligible')::integer, 0);
  v_off    := coalesce((v_state -> 'thresholds' ->> 'off')::integer, 0);
  v_live_ok := coalesce(g.lightning_enabled, false) AND g.enabled IS NOT DISTINCT FROM true;

  SELECT * INTO v_conv FROM public.cash_cluster_conversion cc
   WHERE cc.cluster_id = g.id AND cc.status = 'pending';
  SELECT count(*)::integer INTO v_n FROM public.cash_cluster_conversion cc WHERE cc.cluster_id = g.id;

  IF g.cluster_mode = 'must_move' THEN
    IF v_on_ok AND coalesce(g.must_move, false) THEN
      v_action := 'begin_pending_on';
      -- THE REQUEST ID IS THE CLUSTER, ITS EPOCH, THE DIRECTION AND HOW MANY
      -- CONVERSIONS IT HAS HAD, so two passes racing here ask for the same
      -- conversion and the second is told already_known. An abort adds a row,
      -- so the next attempt gets a new id.
      v_res := public.fn_cash_cluster_begin_pending_on(g.id,
        md5(format('lightning-drive:%s:%s:lightning:%s', g.id, g.cluster_epoch, v_n))::uuid);
    ELSE
      v_action := 'hold';
    END IF;
  ELSIF g.cluster_mode = 'pending_on' THEN
    IF v_conv.id IS NULL THEN
      v_action := 'no_open_conversion';
    ELSIF NOT v_on_ok THEN
      v_action := 'abort_pending_on';
      v_res := public.fn_cash_cluster_abort_pending_on(g.id, v_conv.conversion_request_id,
        CASE WHEN coalesce(g.lightning_enabled, false) = false THEN 'lightning_disabled'
             WHEN g.enabled IS DISTINCT FROM true THEN 'game_disabled'
             ELSE 'population_fell_below_on_threshold' END);
    ELSE
      v_action := 'commit_lightning';
      v_res := public.fn_cash_cluster_commit_lightning(g.id, v_conv.conversion_request_id);
    END IF;
  ELSIF g.cluster_mode = 'lightning' THEN
    IF v_off_ok OR NOT v_live_ok THEN
      v_action := 'begin_pending_off';
      v_res := public.fn_cash_cluster_begin_pending_off(g.id,
        md5(format('lightning-drive:%s:%s:must_move:%s', g.id, g.cluster_epoch, v_n))::uuid,
        'fn_cash_cluster_lightning_drive');
    ELSE
      v_action := 'hold';
      -- 20261007222717: THE DWELL SIGHTING IS CONSECUTIVE-PASS STATE. A pass
      -- that does not see the OFF condition clears the first sighting, so an
      -- oscillating population never accumulates one.
      UPDATE public.cash_games cg SET lightning_off_condition_since = NULL
       WHERE cg.id = g.id AND cg.lightning_off_condition_since IS NOT NULL;
    END IF;
  ELSIF g.cluster_mode = 'pending_off' THEN
    IF v_conv.id IS NULL THEN
      v_action := 'no_open_conversion';
    ELSIF v_live_ok AND v_live > v_off THEN
      v_action := 'abort_pending_off';
      v_res := public.fn_cash_cluster_abort_pending_off(g.id, v_conv.conversion_request_id,
        'population_rose_above_off_threshold');
    ELSE
      v_action := 'commit_must_move';
      v_res := public.fn_cash_cluster_commit_must_move(g.id, v_conv.conversion_request_id);
    END IF;
  ELSIF g.cluster_mode = 'draining' THEN
    -- LIGHTNING PHASE 13 (20261009235505): the emergency drain's own mode;
    -- its step is the advance below.
    v_action := 'drain';
  ELSE
    v_action := 'mode_not_driven';
  END IF;

  -- LIGHTNING PHASE 13 (20261009235505): THE EMERGENCY DRAIN ADVANCES HERE,
  -- after the Cluster's own step (a pending_off committed, a pending_on
  -- aborted), so a drain whose reversion just landed closes in the same
  -- pass.
  IF EXISTS (SELECT 1 FROM public.lightning_cluster_drain d
              WHERE d.cluster_id = g.id AND d.completed_at IS NULL) THEN
    v_drain := public.fn_lightning_drain_advance(g.id);
  END IF;

  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
    INSERT INTO public.cash_cluster_events (game_id, kind, payload)
    VALUES (g.id, 'lightning_drive_error', jsonb_build_object(
      'cluster_id', g.id, 'mode', g.cluster_mode, 'action', v_action,
      'sqlstate', v_sqlstate, 'message', v_message, 'at', clock_timestamp()));
    RETURN jsonb_build_object('ok', false, 'cluster_id', g.id, 'action', v_action,
      'mode_before', g.cluster_mode,
      'error', jsonb_build_object('sqlstate', v_sqlstate, 'message', v_message));
  END;

  SELECT cg.cluster_mode INTO v_mode FROM public.cash_games cg WHERE cg.id = g.id;
  RETURN jsonb_build_object('ok', true, 'cluster_id', g.id, 'action', v_action,
    'mode_before', g.cluster_mode, 'cluster_mode', v_mode,
    'live_eligible', v_live, 'thresholds', v_state -> 'thresholds',
    'lightning_enabled', g.lightning_enabled)
    || CASE WHEN v_res IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('result', v_res) END
    || CASE WHEN v_drain IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('drain', v_drain) END;
END;
$$;


ALTER FUNCTION public.fn_cash_cluster_lightning_drive(p_game_id uuid) OWNER TO postgres;

--
-- TOC entry 46457 (class 0 OID 0)
-- Dependencies: 9319
-- Name: FUNCTION fn_cash_cluster_lightning_drive(p_game_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_lightning_drive(p_game_id uuid) IS 'Lightning Phase 7: the conversion state machine one fn_cash_clusters_tick_all pass runs per Cluster, with ON/OFF hysteresis from fn_cash_cluster_lightning_state and request ids derived from the Cluster, epoch, direction and conversion count.';


--
-- TOC entry 7309 (class 1255 OID 47568575)
-- Name: fn_cash_cluster_lightning_state(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_lightning_state(p_game_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g        record;
  v_live   integer;
  v_th     jsonb;
  v_open   integer;
  v_pool   integer;
  v_on     integer;
  v_off    integer;
BEGIN
  SELECT id, cluster_mode, cluster_epoch, lightning_enabled, must_move, enabled, handedness
    INTO g FROM public.cash_games WHERE id = p_game_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  v_live := public.fn_cash_cluster_live_eligible(g.id);
  v_th   := public.fn_cash_cluster_lightning_thresholds(g.id);
  v_on   := (v_th ->> 'on')::integer;
  v_off  := (v_th ->> 'off')::integer;

  SELECT count(*)::integer INTO v_open
    FROM public.cash_player_session s
   WHERE s.cluster_id = g.id AND s.closed_at IS NULL;

  -- AND THE ONE THAT IS EPOCH-SCOPED, BESIDE THE ONE THAT IS NOT (2026-09-25).
  -- v_open above counts cash sessions and carries NO epoch, and it cannot:
  -- cash_player_session has no cluster_epoch column, because "a Lightning Pool
  -- Session is subordinate to the continuous Cash Player Session. Entering/
  -- exiting Lightning does not create a new cash session." The cash session
  -- outlives the epoch on purpose. Reading that count beside cluster_epoch and
  -- beside a live_eligible that IS epoch-scoped invited exactly the wrong
  -- conclusion, so the epoch-scoped count now sits next to it and says so.
  SELECT count(*)::integer INTO v_pool
    FROM public.lightning_pool_session ps
   WHERE ps.cluster_id = g.id AND ps.cluster_epoch = g.cluster_epoch
     AND ps.exited_at IS NULL;

  RETURN jsonb_build_object(
    'game_id',               g.id,
    'cluster_mode',          g.cluster_mode,
    'cluster_epoch',         g.cluster_epoch,
    'lightning_enabled',     g.lightning_enabled,
    'must_move',             g.must_move,
    'enabled',               g.enabled,
    'handedness',            g.handedness,
    'open_cluster_sessions', v_open,
    'open_pool_sessions',    v_pool,
    'thresholds',            v_th,
    'verdict', jsonb_build_object(
      -- Trigger, MUST-MOVE -> LIGHTNING. pending_on is admitted because the
      -- specification re-asks this question there, at the conversion-safe hand
      -- boundary, to decide whether to commit or abort.
      'would_turn_on',
        g.lightning_enabled
        AND g.cluster_mode IN ('must_move', 'pending_on')
        -- g.enabled, not coalesce(g.enabled, false): cash_games.enabled is NOT
        -- NULL DEFAULT true, so the coalesce was dead cover, and this file's own
        -- header criticises the first cut for exactly that.
        AND g.enabled
        AND v_live >= v_on,
      -- Trigger, LIGHTNING -> MUST-MOVE. pending_off is admitted for the
      -- mirror reason: a population that recovers during the drain CANCELS it,
      -- and a verdict that cannot answer in pending_off cannot say so.
      --
      -- Not gated on enabled, deliberately and unlike the ON side: a disabled
      -- Cluster must not be allowed INTO Lightning and must always be allowed
      -- to drain OUT of it.
      'would_turn_off',
        g.cluster_mode IN ('lightning', 'pending_off')
        AND v_live <= v_off,
      'live_eligible', v_live,
      'to_on',  GREATEST(0, v_on - v_live),
      'to_off', GREATEST(0, v_live - v_off),
      -- No disconnect count reaches this path, so the number here is always
      -- the partial one. fn_cash_cluster_population says the same in its own
      -- answer; spec Phase 14 is what changes it.
      'confidence', 'partial'),
    -- LIGHTNING PHASE 13 (20261009235505): whether the pool takes new
    -- players (an operator can close it while seated players play on).
    'joins_enabled', public.fn_lightning_joins_enabled(g.id));
END;
$$;


