COMMENT ON FUNCTION public.fn_cash_cluster_lightning_state(p_game_id uuid) IS 'Everything one Cluster''s Lightning state consists of, in the one reader fn_cash_game_lobby already embeds. The verdict is descriptive - nothing here converts anything - and it answers in the PENDING states as well as the settled ones, because the specification re-asks both questions there and a verdict that could not answer would abort every conversion at its own safety re-check. plpgsql rather than sql: both children carry SET search_path and cannot be inlined, and the previous shape planned three levels on every call, which measured 3.6 ms of pure overhead on every lobby open.';


--
-- TOC entry 7429 (class 1255 OID 49010008)
-- Name: fn_cash_cluster_lightning_thresholds(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_lightning_thresholds(p_game_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE g record;
BEGIN
  SELECT id, handedness, ruleset_snapshot INTO g FROM public.cash_games WHERE id = p_game_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;
  RETURN public.fn_cash_cluster_lightning_thresholds_probe(g.ruleset_snapshot -> 'lightning', g.handedness)
         || jsonb_build_object('game_id', g.id,
              'lightning_allowed', public.fn_lightning_table_size_allowed(g.handedness))
         || CASE WHEN public.fn_lightning_table_size_allowed(g.handedness) THEN '{}'::jsonb
                 ELSE jsonb_build_object('reason', 'LIGHTNING_TABLE_SIZE_NOT_ALLOWED') END;
END;
$$;


ALTER FUNCTION public.fn_cash_cluster_lightning_thresholds(p_game_id uuid) OWNER TO postgres;

--
-- TOC entry 46461 (class 0 OID 0)
-- Dependencies: 7429
-- Name: FUNCTION fn_cash_cluster_lightning_thresholds(p_game_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_lightning_thresholds(p_game_id uuid) IS 'The ON and OFF population thresholds for one Cluster. A row read and a delegation to fn_cash_cluster_lightning_thresholds_probe, which carries the whole rule and the only copy of the four mandated numbers. It cannot raise on a badly typed configuration value; the first cut could, all the way up through fn_cash_game_lobby.';


--
-- TOC entry 6452 (class 1255 OID 49168518)
-- Name: fn_cash_cluster_lightning_thresholds_probe(jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_lightning_thresholds_probe(p_cfg jsonb, p_handedness integer) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_int_re constant text := '^-?[0-9]{1,9}(\.0+)?$';
  v_on      integer;
  v_off     integer;
  v_got_on  boolean := false;
  v_got_off boolean := false;
  v_source  text;
  -- WHICH CONFIGURED VALUES WERE THROWN AWAY, AND THEREFORE WHY THE ANSWER IS
  -- A DEFAULT. Without this a typo is indistinguishable from an empty config:
  -- {"on_threshold": 18.5} answers 18 and reports source 'default', which is
  -- true and useless, because it is also what {} answers. An operator who
  -- fat-fingers a threshold gets no signal at all that it was discarded. A
  -- hysteresis failure already had its own source value; a type failure did
  -- not. This is additive - it takes nothing away from the four sources - and
  -- it is the difference between a silent discard and a reportable one.
  v_rejected jsonb := '[]'::jsonb;
BEGIN
  -- THE MANDATED DEFAULTS, AND THE ONLY PLACE THEY ARE WRITTEN.
  -- Specification: 6-max ON 18 / OFF 12; 9-max and full ring ON 27 / OFF 18.
  -- handedness is the seats at one table. A handedness at or below zero is not
  -- a six-max game, it is a missing value, so it takes the full-ring default
  -- rather than silently landing in the smaller band.
  IF p_handedness IS NULL OR p_handedness <= 0 OR p_handedness > 6 THEN
    v_on := 27; v_off := 18;
  ELSE
    v_on := 18; v_off := 12;
  END IF;

  IF jsonb_typeof(p_cfg) = 'object' THEN
    IF jsonb_typeof(p_cfg -> 'on_threshold') = 'number'
       AND (p_cfg ->> 'on_threshold') ~ v_int_re THEN
      v_on := floor((p_cfg ->> 'on_threshold')::numeric)::integer; v_got_on := true;
    -- Present and unusable is reported. A JSON null is ABSENT, not a typo:
    -- "unset it" is a legitimate thing for a config writer to mean, and
    -- listing it as rejected would cry wolf on every deliberate clear.
    ELSIF p_cfg ? 'on_threshold' AND jsonb_typeof(p_cfg -> 'on_threshold') <> 'null' THEN
      v_rejected := v_rejected || to_jsonb('on_threshold'::text);
    END IF;
    IF jsonb_typeof(p_cfg -> 'off_threshold') = 'number'
       AND (p_cfg ->> 'off_threshold') ~ v_int_re THEN
      v_off := floor((p_cfg ->> 'off_threshold')::numeric)::integer; v_got_off := true;
    ELSIF p_cfg ? 'off_threshold' AND jsonb_typeof(p_cfg -> 'off_threshold') <> 'null' THEN
      v_rejected := v_rejected || to_jsonb('off_threshold'::text);
    END IF;
  END IF;

  -- source IS PER-FIELD NOW. The first cut reported 'ruleset' whenever either
  -- half came from configuration, so an operator who wrote {"on_threshold":
  -- "30", "off_threshold": 5} - a string and a number - was told 'ruleset' for
  -- a pair of 18 and 5, where the 18 was the band default and only the 5 was
  -- theirs. That pair passes the validity guard, so nothing else flagged it.
  v_source := CASE
    WHEN v_got_on AND v_got_off THEN 'ruleset'
    WHEN v_got_on OR  v_got_off THEN 'ruleset_partial'
    ELSE 'default' END;

  -- HYSTERESIS IS A RULE, NOT A CONVENTION. "The OFF threshold provides
  -- hysteresis and prevents rapid ON/OFF oscillation." An OFF at or above the
  -- ON would convert a Cluster every tick, forever, in both directions. A
  -- configuration that says so is refused and the defaults answer instead.
  -- The first cut also tested v_on IS NULL here; both are unconditionally
  -- assigned above and no branch can unset them, so that half was dead, and
  -- reading dead cover as live cover is part of how the blocker survived.
  IF v_on <= v_off OR v_off < 2 THEN
    IF p_handedness IS NULL OR p_handedness <= 0 OR p_handedness > 6 THEN
      v_on := 27; v_off := 18;
    ELSE
      v_on := 18; v_off := 12;
    END IF;
    v_source := 'default_after_invalid_config';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'handedness', p_handedness,
    'band', CASE WHEN p_handedness IS NOT NULL AND p_handedness > 0 AND p_handedness <= 6
                 THEN 'six_max' ELSE 'full_ring' END,
    'on', v_on,
    'off', v_off,
    'source', v_source,
    'rejected', v_rejected);
END;
$_$;


ALTER FUNCTION public.fn_cash_cluster_lightning_thresholds_probe(p_cfg jsonb, p_handedness integer) OWNER TO postgres;

--
-- TOC entry 46463 (class 0 OID 0)
-- Dependencies: 6452
-- Name: FUNCTION fn_cash_cluster_lightning_thresholds_probe(p_cfg jsonb, p_handedness integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_lightning_thresholds_probe(p_cfg jsonb, p_handedness integer) IS 'The ON/OFF threshold rule as a pure function of a configuration and a handedness, so it can be fuzzed with any shape at all without a Cluster to hang it on. It NEVER raises: the guard and the cast admit the same set, a whole-valued JSON number of at most nine digits, so 18.0 is accepted as 18 while 18.5, 1e300 and 2147483648 fall back to the mandated defaults. The first cut guarded with jsonb_typeof = number and cast with ::integer, which admit different sets, and the gap raised 22P02 all the way up through fn_cash_game_lobby - SECURITY DEFINER, granted to authenticated, polled every five seconds.';


--
-- TOC entry 6376 (class 1255 OID 49010010)
-- Name: fn_cash_cluster_live_eligible(uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_live_eligible(p_game_id uuid, p_now timestamp with time zone DEFAULT clock_timestamp(), p_disconnected integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- ONE count(DISTINCT) OVER THE UNION OF BOTH HALVES, not the sum of two
  -- counts. The halves are disjoint while a Cluster is cleanly in one regime,
  -- and they are NOT disjoint in the window a Phase 5 conversion opens - a
  -- player seated with chips whose pool session has already been created is in
  -- both relations at once, and that window is precisely when the threshold is
  -- being read. The guard is doubled on purpose: UNION deduplicates the rows
  -- and count(DISTINCT) deduplicates the count, and mutation testing showed
  -- that either alone still answers correctly on every board this estate can
  -- build. Neither is load-bearing by itself; together they make the double
  -- count unreachable by any single edit.
  --
  -- MEMBERSHIP IS coalesce(tb.lifecycle, '') <> 'closed' AND NOTHING ELSE
  -- (2026-09-21, Phase 5). It used to be `tb.status IN ('waiting', 'running',
  -- 'active') AND tb.lifecycle <> 'closed'`. Both columns are nullable -
  -- tables.status has a CHECK, but a CHECK that evaluates to NULL PASSES - so
  -- both comparisons yielded NULL rather than true and silently dropped the
  -- whole board. A Cluster with players on such a board was told it had not
  -- reached its threshold however many people were playing, and any conversion
  -- it did make recorded a trigger_population short of the truth. status is an
  -- engine-facing field that may be NULL, 'paused', or a value added next
  -- year; it must not decide who is in a Cluster.
  --
  -- p_now takes part in nothing here: neither half has a time predicate, and
  -- the parameter exists because the specification names the function
  -- getLiveEligiblePopulation(cluster, now) and a later category may need it.
  -- fn_cash_cluster_population DOES honour it, for the hold expiry.
  SELECT GREATEST(0,
      (SELECT count(DISTINCT u.player_id)::integer
         FROM (
           SELECT ts.user_id AS player_id
             FROM public.table_seats ts
             JOIN public.tables tb ON tb.id = ts.table_id
            WHERE tb.cluster_id = g.id AND coalesce(tb.is_deleted, false) = false
              AND coalesce(tb.lifecycle, '') <> 'closed'
              AND ts.left_at IS NULL
              AND ts.user_id IS NOT NULL
              AND coalesce(ts.is_sitting_out, false) = false
              AND coalesce(ts.leave_pending, false) = false
              AND coalesce(ts.stack, 0) > 0
           UNION
           SELECT s.player_id
             FROM public.lightning_pool_session s
            WHERE s.cluster_id = g.id AND s.cluster_epoch = g.cluster_epoch
              AND s.exited_at IS NULL
              AND s.state NOT IN ('joining', 'eligibility_check', 'sit_out', 'disconnected', 'leaving', 'closed')
              AND public.fn_lightning_anchor_is_live_eligible(s.anchor_seat_id, g.id, s.player_id)
         ) u)
    - GREATEST(0, coalesce(p_disconnected, 0)))
    FROM public.cash_games g
   WHERE g.id = p_game_id;
$$;


ALTER FUNCTION public.fn_cash_cluster_live_eligible(p_game_id uuid, p_now timestamp with time zone, p_disconnected integer) OWNER TO postgres;

--
-- TOC entry 46465 (class 0 OID 0)
-- Dependencies: 6376
-- Name: FUNCTION fn_cash_cluster_live_eligible(p_game_id uuid, p_now timestamp with time zone, p_disconnected integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_live_eligible(p_game_id uuid, p_now timestamp with time zone, p_disconnected integer) IS 'The one live eligible population predicate: how many PLAYERS Lightning could deal to in this Cluster right now. Not the board count - that question is "how many players are in this game", it counts a sitting-out, busted or leaving player because all three are in the game, and tests/one-definition-of-a-games-players.law.test.ts pins it across three readers. The table predicate here is fn_cash_cluster_census''s byte for byte; only the seat predicate is narrower. A horse counts exactly like a human (Law 10.5). Two statements, because fn_cash_game_lobby reaches this through fn_cash_cluster_lightning_state on every open; fn_cash_cluster_population adds the breakdown around this number rather than recomputing it.';


--
-- TOC entry 5682 (class 1255 OID 57693210)
-- Name: fn_cash_cluster_matcher_pass_prune(uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_matcher_pass_prune(p_cluster_id uuid, p_before timestamp with time zone, p_limit integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_n integer;
BEGIN
  IF p_cluster_id IS NULL OR p_before IS NULL OR coalesce(p_limit, 0) < 1 THEN
    RETURN 0;
  END IF;
  DELETE FROM public.cash_cluster_matcher_pass mp
   WHERE mp.request_id IN (SELECT o.request_id FROM public.cash_cluster_matcher_pass o
                            WHERE o.cluster_id = p_cluster_id AND o.started_at < p_before
                            ORDER BY o.started_at, o.request_id
                            LIMIT LEAST(p_limit, 10000));
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END
$$;


ALTER FUNCTION public.fn_cash_cluster_matcher_pass_prune(p_cluster_id uuid, p_before timestamp with time zone, p_limit integer) OWNER TO postgres;

