COMMENT ON FUNCTION public.fn_cash_cluster_matcher_pass_prune(p_cluster_id uuid, p_before timestamp with time zone, p_limit integer) IS 'Retention for cash_cluster_matcher_pass: deletes at most p_limit of one Cluster''s pass records older than p_before, oldest first. SECURITY DEFINER because service_role holds no DELETE on the table; executable by service_role only; called by fn_lightning_match_and_form whenever it records a pass.';


--
-- TOC entry 9338 (class 1255 OID 20961962)
-- Name: fn_cash_cluster_open_table(uuid, text, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_open_table(p_game_id uuid, p_role text, p_main_index integer, p_lifecycle text DEFAULT 'opening'::text, p_created_by uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g record; s jsonb; v_opts jsonb;
  v_ante text; v_ante_chips numeric; v_vpip integer; v_vpip_window integer;
  v_bomb_on boolean; v_bomb_trigger text; v_bomb_ante integer; v_bomb_boards integer;
  v_min_bb integer; v_max_bb integer; v_name text; v_table_id uuid; v_n integer;
  v_kill_mode text; v_kill_bb smallint;
BEGIN
  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND: %', p_game_id; END IF;
  IF p_role NOT IN ('main', 'feeder') THEN RAISE EXCEPTION 'ROLE_INVALID: %', p_role; END IF;
  IF p_role = 'main' AND (p_main_index IS NULL OR p_main_index < 1) THEN
    RAISE EXCEPTION 'MAIN_INDEX_INVALID: %', p_main_index;
  END IF;
  IF p_lifecycle NOT IN ('opening', 'live') THEN RAISE EXCEPTION 'LIFECYCLE_INVALID: %', p_lifecycle; END IF;

  s := g.ruleset_snapshot;
  v_opts := coalesce(s->'options', '{}'::jsonb);
  v_ante := coalesce(s->>'regular_ante', 'none');
  v_ante_chips := CASE v_ante WHEN 'sb' THEN g.sb WHEN 'bb' THEN g.bb ELSE 0 END;
  v_vpip := coalesce((s->>'vpip_floor')::integer, 0);
  v_vpip_window := coalesce((s->>'vpip_window')::integer, 10);
  v_bomb_on := coalesce((s->'bombs'->>'enabled')::boolean, false);
  v_bomb_trigger := s->'bombs'->>'trigger';
  v_bomb_ante := (s->'bombs'->>'ante_bb')::integer;
  v_bomb_boards := (s->'bombs'->>'boards')::integer;
  v_min_bb := coalesce((s->>'min_buyin_bb')::integer, 40);
  v_max_bb := coalesce((s->>'max_buyin_bb')::integer, 200);
  -- KILL POTS (kill-v1, 20260924034010). The game's snapshot carries
  -- {"kill":{"mode","threshold_bb"}}; fn_cash_apply_ruleset projects the
  -- same two values identically. 'off' whenever the kill would be refused
  -- at this table, so opening a table never fails on a kill setting.
  v_kill_bb := CASE WHEN (s->'kill'->>'threshold_bb') IN ('8','10','12','15')
                    THEN (s->'kill'->>'threshold_bb')::smallint ELSE 10 END;
  v_kill_mode := lower(coalesce(s->'kill'->>'mode', 'off'));
  IF v_kill_mode NOT IN ('half', 'full') THEN
    v_kill_mode := 'off';
  ELSIF public.fn_kill_pot_configuration_refusal(v_kill_mode, g.variant, 'cash', NULL, v_bomb_on, g.bb, g.club_id) IS NOT NULL THEN
    v_kill_mode := 'off';
  ELSIF NOT public.fn_capability_available('cash.fixed_limit.kill_pots') THEN
    v_kill_mode := 'off';
  END IF;

  -- "NLH 1/2 Classic" for Main 1, "NLH 1/2 Classic Main 2", "... Feeder".
  -- LIVE tables only. R3 reopens a closed cluster's one table with the
  -- closed row still present, so an all-time count made a reopened lone
  -- feeder "<game> Feeder" and the lone-feeder guard then stopped the ROLES
  -- step ever renaming it (2026-09-21 remediation).
  SELECT count(*) INTO v_n FROM public.tables WHERE cluster_id = p_game_id
     AND lifecycle <> 'closed' AND coalesce(is_deleted, false) = false;
  v_name := CASE
    WHEN p_role = 'main' AND p_main_index = 1 THEN g.name
    WHEN p_role = 'main' THEN left(g.name, 50) || ' Main ' || p_main_index
    -- the cluster's first table stands for the game, whatever its role
    WHEN v_n = 0 THEN g.name
    ELSE left(g.name, 50) || ' Feeder' END;

  INSERT INTO public.tables (
    club_id, union_id, name, game_type, game_variant, game_mode,
    small_blind, big_blind, stakes,
    max_players, min_buy_in, max_buy_in,
    ante_enabled, ante, ante_bb, big_blind_ante_enabled,
    nit_game, career_percent_min, maintain_percent_min, maintain_hands,
    bomb_pot_enabled, bomb_pot_trigger_mode, bomb_pot_interval_seconds, bomb_pot_frequency,
    bomb_pot_ante_multiplier, bomb_pot_board_count, bomb_pot_double_board, bomb_pot_min_players,
    straddle_enabled, auto_utg_straddle, voluntary_straddle,
    run_it_mode, run_it_twice, allow_run_it_twice, run_it_twice_enabled,
    rake_percent, rake_cap_bb,
    is_private, is_vip_only, is_anonymous, ban_chat, insurance_enabled,
    seven_deuce_enabled, seven_deuce_amount,
    action_time_seconds, auto_start_players,
    auto_extension, auto_restart, auto_create_table,
    status, current_players, created_by,
    cluster_id, role, main_index, lifecycle, opened_at, live_at,
    kill_mode, kill_threshold_bb
  ) VALUES (
    g.club_id, g.union_id, v_name, 'cash', g.variant, 'regular',
    g.sb, g.bb, public.fn_cash_stakes_label(g.sb, g.bb, g.variant),
    g.handedness, round(g.bb * v_min_bb, 2), round(g.bb * v_max_bb, 2),
    -- BIG BLIND ANTE (2026-09-05): 'bb' is the format, not just the size -
    -- the big blind posts one ante for the table. 'sb' is the classic ante,
    -- a small blind from every seat.
    v_ante_chips > 0, v_ante_chips, CASE WHEN v_ante_chips > 0 THEN round(v_ante_chips / g.bb, 4) ELSE 0 END,
    (v_ante = 'bb'),
    v_vpip > 0, 0, v_vpip, v_vpip_window,
    v_bomb_on,
    CASE WHEN v_bomb_on AND v_bomb_trigger IN ('timed_10m', 'timed_15m', 'timed_20m') THEN 'timed'
         WHEN v_bomb_on AND v_bomb_trigger = 'every_orbit' THEN 'once_per_orbit'
         ELSE 'every_n_hands' END,
    CASE WHEN NOT v_bomb_on THEN NULL
         WHEN v_bomb_trigger = 'timed_10m' THEN 600
         WHEN v_bomb_trigger = 'timed_15m' THEN 900
         WHEN v_bomb_trigger = 'timed_20m' THEN 1200
         ELSE NULL END,
    0,
    coalesce(v_bomb_ante, 2), coalesce(v_bomb_boards, 1), coalesce(v_bomb_boards, 1) >= 2, 2,
    false, false, false,
    'player_choice', true, true, true,
    -1, -1,
    coalesce((v_opts->>'is_private')::boolean, false), coalesce((v_opts->>'is_vip_only')::boolean, false),
    coalesce((v_opts->>'is_anonymous')::boolean, false), coalesce((v_opts->>'ban_chat')::boolean, false),
    coalesce((v_opts->>'insurance_enabled')::boolean, false),
    coalesce((v_opts->>'seven_deuce_enabled')::boolean, false),
    CASE WHEN coalesce((v_opts->>'seven_deuce_enabled')::boolean, false) THEN 2 ELSE 0 END,
    LEAST(120, GREATEST(10, coalesce((v_opts->>'action_time_seconds')::integer, 15))), 2,
    -- A cluster table's life is the controller's (Slice 6). A manual (R9)
    -- table's life is the host's. Neither uses the lifecycle-pass flags.
    false, false, false,
    'waiting', 0, coalesce(p_created_by, g.created_by),
    p_game_id, p_role, CASE WHEN p_role = 'main' THEN p_main_index END, p_lifecycle,
    clock_timestamp(), CASE WHEN p_lifecycle = 'live' THEN clock_timestamp() END,
    v_kill_mode, v_kill_bb
  ) RETURNING id INTO v_table_id;

  IF EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=g.club_id AND c.asset='diamonds') THEN
    PERFORM public.fn_poker_diamond_project_cluster(g.id,v_table_id);
  END IF;

  -- BORN HALTED IN A CLUSTER THAT IS NOT DEALING CASH (2026-09-26).
  IF g.cluster_mode IS DISTINCT FROM 'must_move' THEN
    UPDATE public.tables t
       SET dealing_halted_at = clock_timestamp(),
           dealing_halted_reason = CASE WHEN g.cluster_mode = 'pending_on'
                                        THEN 'lightning_pending_on' ELSE 'lightning' END
     WHERE t.id = v_table_id;
  END IF;

  INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
  VALUES (p_game_id, v_table_id, CASE WHEN p_role = 'feeder' THEN 'feeder_opened' ELSE 'main_opened' END,
          jsonb_build_object('role', p_role, 'main_index', p_main_index, 'lifecycle', p_lifecycle, 'name', v_name));
  RETURN v_table_id;
END;
$$;


ALTER FUNCTION public.fn_cash_cluster_open_table(p_game_id uuid, p_role text, p_main_index integer, p_lifecycle text, p_created_by uuid) OWNER TO postgres;

--
-- TOC entry 9476 (class 1255 OID 49010021)
-- Name: fn_cash_cluster_pool_health(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_pool_health(p_game_id uuid, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_pop    jsonb;
  v_th     jsonb;
  v_live   integer;
  v_slots  record;
BEGIN
  v_pop := public.fn_cash_cluster_population(p_game_id, p_now);
  IF coalesce((v_pop ->> 'ok')::boolean, false) = false THEN
    RETURN v_pop;
  END IF;
  v_th   := public.fn_cash_cluster_lightning_thresholds(p_game_id);
  v_live := (v_pop ->> 'live_eligible')::integer;

  SELECT count(*)::integer                                            AS open_slots,
         count(DISTINCT s.player_id)::integer                          AS players,
         coalesce(max(s.p95_wait_ms), 0)::integer                      AS p95_wait_ms,
         coalesce(max(s.p99_wait_ms), 0)::integer                      AS p99_wait_ms,
         coalesce(sum(s.hands), 0)::bigint                             AS hands,
         coalesce(sum(s.fast_folds), 0)::bigint                        AS fast_folds
    INTO v_slots
    FROM public.lightning_pool_slot s
    JOIN public.cash_games g ON g.id = s.cluster_id AND g.cluster_epoch = s.cluster_epoch
   WHERE s.cluster_id = p_game_id AND s.closed_at IS NULL;

  RETURN jsonb_build_object(
    'ok',            true,
    'game_id',       p_game_id,
    'as_of',         p_now,
    'regime',        v_pop ->> 'cluster_mode',
    'live_eligible', v_live,
    'thresholds',    v_th,
    'headroom', jsonb_build_object(
      'to_on',  GREATEST(0, (v_th ->> 'on')::integer  - v_live),
      'to_off', GREATEST(0, v_live - (v_th ->> 'off')::integer)),
    'seats', jsonb_build_object(
      'tables',    (v_pop ->> 'tables')::integer,
      'capacity',  (v_pop ->> 'capacity')::integer,
      'occupied',  (v_pop -> 'counted' ->> 'seated_total')::integer,
      'occupancy', CASE WHEN (v_pop ->> 'capacity')::integer > 0
                        THEN round(100.0 * (v_pop -> 'counted' ->> 'seated_total')::integer
                                         / (v_pop ->> 'capacity')::integer, 1)
                        ELSE NULL END),
    'pool', jsonb_build_object(
      'open_slots',  coalesce(v_slots.open_slots, 0),
      'players',     coalesce(v_slots.players, 0),
      'p95_wait_ms', coalesce(v_slots.p95_wait_ms, 0),
      'p99_wait_ms', coalesce(v_slots.p99_wait_ms, 0),
      'hands',       coalesce(v_slots.hands, 0),
      'fast_folds',  coalesce(v_slots.fast_folds, 0)),
    'population',  v_pop,
    'confidence',  v_pop ->> 'confidence');
END;
$$;


ALTER FUNCTION public.fn_cash_cluster_pool_health(p_game_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 46470 (class 0 OID 0)
-- Dependencies: 9476
-- Name: FUNCTION fn_cash_cluster_pool_health(p_game_id uuid, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_pool_health(p_game_id uuid, p_now timestamp with time zone) IS 'One Cluster''s liquidity in one shape, whichever regime it is in: the live eligible population, the thresholds, the headroom to each, seat occupancy, and - once there is a pool - the slot wait distribution and fold counters. A read rather than a stored series, because nothing consumes it yet and a series nothing reads is a series nothing constrains.';


--
-- TOC entry 7489 (class 1255 OID 49010017)
-- Name: fn_cash_cluster_population(uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_population(p_game_id uuid, p_now timestamp with time zone DEFAULT clock_timestamp(), p_disconnected integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g              record;
  v_seated       integer := 0;
  v_empty        integer := 0;
  v_eligible     integer := 0;
  v_main         integer := 0;
  v_feeder       integer := 0;
  v_no_role      integer := 0;
  v_sit_out      integer := 0;
  v_leaving      integer := 0;
  v_busted       integer := 0;
  v_horses       integer := 0;
  v_movers       integer := 0;
  v_reserved     integer := 0;
  v_waitlist     integer := 0;
  v_l_total      integer := 0;
  v_l_eligible   integer := 0;
  v_l_idle       integer := 0;
  v_l_instance   integer := 0;
  v_l_hand       integer := 0;
  v_both         integer := 0;
  v_tables       integer := 0;
  v_capacity     integer := 0;
  v_unknown      jsonb;
  v_confidence   text;
  v_disc         integer;
BEGIN
  SELECT id, handedness, cluster_mode, cluster_epoch, lightning_enabled INTO g
    FROM public.cash_games WHERE id = p_game_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;

  -- THE TABLES OF THE GAME. fn_cash_cluster_census's predicate, byte for byte.
  SELECT count(*)::integer, coalesce(sum(coalesce(tb.max_players, 9)), 0)::integer
    INTO v_tables, v_capacity
    FROM public.tables tb
   WHERE tb.cluster_id = g.id AND coalesce(tb.is_deleted, false) = false
     AND coalesce(tb.lifecycle, '') <> 'closed';

  SELECT
    count(*) FILTER (WHERE ts.user_id IS NOT NULL)::integer,
    count(*) FILTER (WHERE ts.user_id IS NULL)::integer,
    count(*) FILTER (WHERE tb.role = 'main'   AND ts.user_id IS NOT NULL)::integer,
    count(*) FILTER (WHERE tb.role = 'feeder' AND ts.user_id IS NOT NULL)::integer,
    count(*) FILTER (WHERE tb.role IS NULL    AND ts.user_id IS NOT NULL)::integer,
    count(*) FILTER (WHERE ts.user_id IS NOT NULL AND coalesce(ts.is_sitting_out, false))::integer,
    count(*) FILTER (WHERE ts.user_id IS NOT NULL AND coalesce(ts.leave_pending, false))::integer,
    count(*) FILTER (WHERE ts.user_id IS NOT NULL AND coalesce(ts.stack, 0) = 0)::integer,
    count(*) FILTER (WHERE ts.horse_id IS NOT NULL)::integer
    INTO v_seated, v_empty, v_main, v_feeder, v_no_role, v_sit_out, v_leaving, v_busted, v_horses
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.cluster_id = g.id AND coalesce(tb.is_deleted, false) = false
     AND coalesce(tb.lifecycle, '') <> 'closed'
     AND ts.left_at IS NULL;

  -- THE TWO HALVES, AND THE OVERLAP BETWEEN THEM. The scalar takes one
  -- count(DISTINCT) over their union; these are the halves separately. The
  -- identity is
  --
  --   GREATEST(0, seated_eligible + lightning_eligible - seated_and_pooled
  --                 - counted.disconnected)  =  live_eligible
  --
  -- and it holds in the conversion window as well as outside it. The
  -- disconnect term is not decoration: the three counted figures subtract
  -- nothing, while live_eligible does, so an identity written without it is
  -- true only on the p_disconnected IS NULL path - which is every path today
  -- and none of them from spec Phase 14 onward, which is exactly when it
  -- becomes load-bearing.
  SELECT count(DISTINCT ts.user_id)::integer INTO v_eligible
    FROM public.table_seats ts
    JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.cluster_id = g.id AND coalesce(tb.is_deleted, false) = false
     AND coalesce(tb.lifecycle, '') <> 'closed'
     AND ts.left_at IS NULL AND ts.user_id IS NOT NULL
     AND coalesce(ts.is_sitting_out, false) = false
     AND coalesce(ts.leave_pending, false) = false
     AND coalesce(ts.stack, 0) > 0;

  SELECT count(DISTINCT s.player_id)::integer INTO v_l_eligible
    FROM public.lightning_pool_session s
   WHERE s.cluster_id = g.id AND s.cluster_epoch = g.cluster_epoch
     AND s.exited_at IS NULL AND s.state = 'active'
     AND public.fn_lightning_anchor_is_live_eligible(s.anchor_seat_id, g.id, s.player_id);

  SELECT count(*)::integer INTO v_l_total
    FROM public.lightning_pool_session s
   WHERE s.cluster_id = g.id AND s.cluster_epoch = g.cluster_epoch AND s.exited_at IS NULL;

  SELECT count(DISTINCT s.player_id)::integer INTO v_both
    FROM public.lightning_pool_session s
   WHERE s.cluster_id = g.id AND s.cluster_epoch = g.cluster_epoch
     AND s.exited_at IS NULL AND s.state = 'active'
     AND public.fn_lightning_anchor_is_live_eligible(s.anchor_seat_id, g.id, s.player_id)
     AND EXISTS (
       SELECT 1 FROM public.table_seats ts
         JOIN public.tables tb ON tb.id = ts.table_id
        WHERE tb.cluster_id = g.id AND coalesce(tb.is_deleted, false) = false
          AND coalesce(tb.lifecycle, '') <> 'closed'
          AND ts.left_at IS NULL AND ts.user_id = s.player_id
          AND coalesce(ts.is_sitting_out, false) = false
          AND coalesce(ts.leave_pending, false) = false
          AND coalesce(ts.stack, 0) > 0);

  -- A move inside a Cluster is not a leave, so a pending mover is live. The
  -- count is reported because an operator watching a threshold wants to know
  -- how much of it is mid-flight.
  SELECT count(*)::integer INTO v_movers
    FROM public.cash_seat_moves m
   WHERE m.game_id = g.id AND m.state = 'pending';

  -- A reserved seat is a HOLD, not a player, and it is never added to the
  -- population. The census's table predicate again, so a stale hold on a
  -- closed or deleted table cannot inflate the figure an operator reads as
  -- "seats held on this game's tables".
  SELECT count(*)::integer INTO v_reserved
    FROM public.table_waitlist w
    JOIN public.tables tb ON tb.id = w.table_id
   WHERE tb.cluster_id = g.id AND coalesce(tb.is_deleted, false) = false
     AND coalesce(tb.lifecycle, '') <> 'closed'
     AND w.status = 'notified' AND w.hold_expires_at > p_now;

  -- "Waitlist-only does NOT count." Reported so headroom can be read honestly
  -- - a game three short of 18 with nine waiting is a different situation from
  -- one with none - and never added.
  SELECT count(*)::integer INTO v_waitlist
    FROM public.cash_game_waitlist w
   WHERE w.game_id = g.id AND w.status IN ('waiting', 'notified');

  -- THE LIGHTNING SHAPE. Per-hand state is DERIVED from the hold and the
  -- instance it names, never stored: 20260920235343 settled that, because one
  -- column cannot say that a multi-tabling player is in a hand at one table
  -- and idle at another.
  SELECT count(DISTINCT r.player_id)::integer INTO v_l_instance
    FROM public.lightning_reservation r
    JOIN public.lightning_instance i ON i.id = r.lightning_instance_id
    JOIN public.lightning_pool_session s
      ON s.player_id = r.player_id AND s.cluster_id = r.cluster_id
     AND s.cluster_epoch = r.cluster_epoch AND s.exited_at IS NULL AND s.state = 'active'
   WHERE r.cluster_id = g.id AND r.cluster_epoch = g.cluster_epoch
     AND r.state = 'committed'
     AND i.state IN ('forming', 'reserved', 'dealing', 'settling');

  SELECT count(DISTINCT hp.player_id)::integer INTO v_l_hand
    FROM public.lightning_hand_player hp
    JOIN public.lightning_hand h ON h.hand_id = hp.hand_id
    JOIN public.lightning_instance i ON i.id = h.lightning_instance_id
      AND i.state IN ('forming', 'reserved', 'dealing', 'settling')
   WHERE h.cluster_id = g.id AND h.cluster_epoch = g.cluster_epoch AND h.settled_at IS NULL;

  -- IDLE IS COUNTED, NOT SUBTRACTED. An earlier cut read
  -- GREATEST(0, eligible - in_instance), which subtracts a count of players
  -- holding a seat anywhere in the epoch from a count of ACTIVE pool sessions
  -- - two different populations - and hid the crossing under the floor. A
  -- player who is eligible and is not in an instance is idle, asked directly.
  SELECT count(DISTINCT s.player_id)::integer INTO v_l_idle
    FROM public.lightning_pool_session s
   WHERE s.cluster_id = g.id AND s.cluster_epoch = g.cluster_epoch
     AND s.exited_at IS NULL AND s.state = 'active'
     AND public.fn_lightning_anchor_is_live_eligible(s.anchor_seat_id, g.id, s.player_id)
     AND NOT EXISTS (
       SELECT 1 FROM public.lightning_reservation r
         JOIN public.lightning_instance i ON i.id = r.lightning_instance_id
        WHERE r.cluster_id = s.cluster_id AND r.cluster_epoch = s.cluster_epoch
          AND r.player_id = s.player_id AND r.state = 'committed'
          AND i.state IN ('forming', 'reserved', 'dealing', 'settling'));

  -- WHAT IS NOT KNOWN, NAMED. The engine may supply the disconnect count; when
  -- it does, it is subtracted and the answer says so. When it does not, the
  -- list is four long and confidence reads 'partial' - the honest answer at 18
  -- players with two silent clients is that this may be 18 or may be 16.
  IF p_disconnected IS NULL THEN
    v_disc := 0;
    v_unknown := jsonb_build_array('disconnected', 'expired_disconnect', 'ghost_bb', 'watching');
    v_confidence := 'partial';
  ELSE
    v_disc := GREATEST(0, p_disconnected);
    v_unknown := jsonb_build_array('ghost_bb', 'watching');
    v_confidence := 'engine';
  END IF;

  RETURN jsonb_build_object(
    'ok',             true,
    'game_id',        g.id,
    'handedness',     g.handedness,
    'cluster_mode',   g.cluster_mode,
    'cluster_epoch',  g.cluster_epoch,
    'as_of',          p_now,
    -- THE NUMBER, from the one predicate. Everything else explains it.
    'live_eligible',  public.fn_cash_cluster_live_eligible(g.id, p_now, p_disconnected),
    'counted', jsonb_build_object(
      'seated_total',          v_seated,
      'seated_main',           v_main,
      'seated_feeder',         v_feeder,
      'seated_no_role',        v_no_role,
      'seated_eligible',       v_eligible,
      'lightning_total',       v_l_total,
      'lightning_eligible',    v_l_eligible,
      'lightning_idle',        v_l_idle,
      'lightning_in_instance', v_l_instance,
      'lightning_in_hand',     v_l_hand,
      'seated_and_pooled',     v_both,
      'horses',                v_horses,
      'pending_movers',        v_movers,
      'disconnected',          v_disc),
    'excluded', jsonb_build_object(
      'sit_out',       v_sit_out,
      'leaving',       v_leaving,
      'busted',        v_busted,
      'empty_chairs',  v_empty,
      'reserved_seat', v_reserved,
      'waitlist_only', v_waitlist),
    -- These categories OVERLAP and do not sum to anything. Stated in the
    -- answer so a reader cannot mistake them for terms of an equation.
    'breakdown_is_not_arithmetic', true,
    'tables',     v_tables,
    'capacity',   v_capacity,
    'unknown',    v_unknown,
    'confidence', v_confidence);
END;
$$;


ALTER FUNCTION public.fn_cash_cluster_population(p_game_id uuid, p_now timestamp with time zone, p_disconnected integer) OWNER TO postgres;

--
-- TOC entry 46472 (class 0 OID 0)
-- Dependencies: 7489
-- Name: FUNCTION fn_cash_cluster_population(p_game_id uuid, p_now timestamp with time zone, p_disconnected integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_population(p_game_id uuid, p_now timestamp with time zone, p_disconnected integer) IS 'The live eligible population of a Cluster with its full breakdown. The NUMBER comes from fn_cash_cluster_live_eligible, which is the one predicate; everything else here exists to explain it. The categories deliberately overlap and do not sum: a seat that is sitting out with no chips is counted under both, an empty chair under neither, and seated_main plus seated_feeder can be short of seated_total because public.tables.role is nullable. Nine statements, which is why the lobby reads the scalar and not this.';


--
-- TOC entry 3538 (class 1255 OID 56821659)
-- Name: fn_cash_cluster_reap_stuck_conversions(interval, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_reap_stuck_conversions(p_max_age interval DEFAULT '00:15:00'::interval, p_now timestamp with time zone DEFAULT clock_timestamp(), p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  c         record;
  v_res     jsonb;
  v_aborted boolean;
  v_seen    integer := 0;
  v_reaped  integer := 0;
  v_skipped integer := 0;
  v_rows    jsonb   := '[]'::jsonb;
  v_failed  integer := 0;
  v_sqlstate text;
  v_msg     text;
  -- A caller asking for a one-second reaper is asking to abort conversions
  -- that are working. The floor is the shortest interval in which a hand
  -- boundary can plausibly still be arriving.
  v_age     interval := GREATEST(coalesce(p_max_age, interval '15 minutes'), interval '1 minute');
BEGIN
  -- DELIBERATELY NOT GATED ON fn_platform_frozen(), for the same reason
  -- fn_cash_cluster_abort_pending_on is not: leaving a half-converted Cluster
  -- must always be possible, and the break is when incidents are handled. Its
  -- caller short-circuits on the freeze before it gets here, which is a
  -- decision about the PASS rather than about this function - see the header.
  FOR c IN
    SELECT cc.id, cc.cluster_id, cc.conversion_request_id, cc.opened_at,
           cc.to_mode, g.cluster_mode
      FROM public.cash_cluster_conversion cc
      JOIN public.cash_games g ON g.id = cc.cluster_id
     WHERE cc.status = 'pending'
       AND cc.opened_at < p_now - v_age
     ORDER BY cc.opened_at, cc.id
     LIMIT GREATEST(1, coalesce(p_limit, 50))
  LOOP
    v_seen := v_seen + 1;

    -- LIGHTNING PHASE 7 (20261001222856): A STUCK PENDING_OFF. Its drain is a
    -- set of hands that never finished. Past the age every instance still not
    -- terminal is abandoned through the existing door (a void hand: nothing
    -- writes money before settlement, so no chip moves), and the reversion is
    -- committed through fn_cash_cluster_commit_must_move, whose own md5
    -- assertion is the proof. One Cluster's failure is a row and an event,
    -- and the queue behind it is still reaped.
    IF c.to_mode = 'must_move' AND c.cluster_mode = 'pending_off' THEN
      DECLARE
        v_inst     record;
        v_void     integer := 0;
        v_commit   jsonb;
        v_reverted boolean := false;
      BEGIN
        BEGIN
          FOR v_inst IN
            SELECT li.id FROM public.lightning_instance li
             WHERE li.cluster_id = c.cluster_id
               AND li.state IN ('forming', 'reserved', 'dealing', 'settling')
             ORDER BY li.id
          LOOP
            PERFORM public.fn_lightning_instance_abandon(v_inst.id,
              format('reaped: PENDING_OFF for %s, past the %s this estate allows a reversion to wait on a hand; the hand is void and no chip moved',
                     justify_interval(p_now - c.opened_at), v_age),
              clock_timestamp());
            v_void := v_void + 1;
          END LOOP;
          v_commit := public.fn_cash_cluster_commit_must_move(c.cluster_id, c.conversion_request_id);
          v_reverted := coalesce((v_commit ->> 'reverted')::boolean, false);
        EXCEPTION WHEN OTHERS THEN
          GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
          v_reverted := false;
          v_void := 0;
          v_failed := v_failed + 1;
          v_commit := jsonb_build_object('ok', false, 'reverted', false, 'reason', 'revert_failed',
                                         'sqlstate', v_sqlstate, 'message', v_msg);
          INSERT INTO public.cash_cluster_events (game_id, kind, payload)
          VALUES (c.cluster_id, 'lightning_pending_off_reap_failed', jsonb_build_object(
            'cluster_id', c.cluster_id, 'conversion_id', c.id,
            'conversion_request_id', c.conversion_request_id, 'opened_at', c.opened_at,
            'sqlstate', v_sqlstate, 'message', v_msg, 'at', clock_timestamp()));
        END;
        IF v_reverted THEN
          v_reaped := v_reaped + 1;
          INSERT INTO public.cash_cluster_events (game_id, kind, payload)
          VALUES (c.cluster_id, 'lightning_pending_off_reaped', jsonb_build_object(
            'conversion_id', c.id, 'conversion_request_id', c.conversion_request_id,
            'opened_at', c.opened_at,
            'stuck_for', justify_interval(p_now - c.opened_at)::text,
            'max_age', v_age::text,
            'instances_abandoned', v_void,
            'commit', v_commit,
            'pool_health', public.fn_cash_cluster_pool_health(c.cluster_id, p_now)));
        ELSE
          v_skipped := v_skipped + 1;
        END IF;
        v_rows := v_rows || jsonb_build_object(
          'conversion_id', c.id, 'cluster_id', c.cluster_id, 'direction', 'off',
          'reaped', v_reverted, 'instances_abandoned', v_void, 'answer', v_commit);
      END;
      CONTINUE;
    END IF;

    -- LIGHTNING PHASE 7 REMEDIATION (20261007222717): A PENDING CONVERSION
    -- WHOSE CLUSTER HAS MOVED ON IS AN ORPHAN, NOT A CURIOSITY. An operator
    -- path that changed the Cluster's mode around a pending conversion (the
    -- unfreeze, before this file closed them there) left a row the
    -- one-open-per-cluster index then enforced for ever: every later begin
    -- was refused, and this reaper skipped the row every pass. A pending
    -- conversion whose Cluster is not in that conversion's own pending mode
    -- is aborted here, with the mode that orphaned it as the reason.
    IF (c.to_mode = 'must_move' AND c.cluster_mode IS DISTINCT FROM 'pending_off')
       OR (c.to_mode = 'lightning' AND c.cluster_mode IS DISTINCT FROM 'pending_on') THEN
      UPDATE public.cash_cluster_conversion
         SET status = 'aborted',
             abort_reason = 'orphaned_by_' || coalesce(c.cluster_mode, 'unknown'),
             closed_at = clock_timestamp()
       WHERE id = c.id AND status = 'pending';
      IF FOUND THEN
        v_reaped := v_reaped + 1;
        INSERT INTO public.cash_cluster_events (game_id, kind, payload)
        VALUES (c.cluster_id, 'lightning_conversion_orphan_reaped', jsonb_build_object(
          'conversion_id', c.id, 'conversion_request_id', c.conversion_request_id,
          'opened_at', c.opened_at, 'to_mode', c.to_mode, 'cluster_mode', c.cluster_mode,
          'abort_reason', 'orphaned_by_' || coalesce(c.cluster_mode, 'unknown'),
          'stuck_for', justify_interval(p_now - c.opened_at)::text, 'at', clock_timestamp()));
        v_rows := v_rows || jsonb_build_object(
          'conversion_id', c.id, 'cluster_id', c.cluster_id, 'reaped', true,
          'reason', 'orphaned_by_' || coalesce(c.cluster_mode, 'unknown'),
          'to_mode', c.to_mode, 'cluster_mode', c.cluster_mode);
      ELSE
        v_skipped := v_skipped + 1;
        v_rows := v_rows || jsonb_build_object(
          'conversion_id', c.id, 'cluster_id', c.cluster_id, 'reaped', false,
          'reason', 'conversion_closed_while_reaping');
      END IF;
      CONTINUE;
    END IF;

    IF c.to_mode IS DISTINCT FROM 'lightning' OR c.cluster_mode IS DISTINCT FROM 'pending_on' THEN
      v_skipped := v_skipped + 1;
      v_rows := v_rows || jsonb_build_object(
        'conversion_id', c.id, 'cluster_id', c.cluster_id, 'reaped', false,
        'reason', 'not_a_pending_on_lightning_conversion',
        'to_mode', c.to_mode, 'cluster_mode', c.cluster_mode);
      CONTINUE;
    END IF;

    BEGIN
      v_res := public.fn_cash_cluster_abort_pending_on(
        c.cluster_id, c.conversion_request_id,
        format('reaped: PENDING_ON for %s, past the %s this estate allows a conversion to hold its tables',
               justify_interval(p_now - c.opened_at), v_age));
      v_aborted := coalesce((v_res ->> 'aborted')::boolean, false);
    EXCEPTION WHEN OTHERS THEN
      -- ONE CONVERSION'S FAILURE (2026-09-26): its abort is rolled back, the
      -- failure is a row, and the queue behind it is still reaped.
      GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
      v_aborted := false;
      v_failed := v_failed + 1;
      v_res := jsonb_build_object('ok', false, 'aborted', false, 'reason', 'abort_failed',
                                  'sqlstate', v_sqlstate, 'message', v_msg);
      INSERT INTO public.cash_cluster_events (game_id, kind, payload)
      VALUES (c.cluster_id, 'lightning_pending_on_reap_failed', jsonb_build_object(
        'cluster_id', c.cluster_id, 'conversion_id', c.id,
        'conversion_request_id', c.conversion_request_id, 'opened_at', c.opened_at,
        'sqlstate', v_sqlstate, 'message', v_msg, 'at', clock_timestamp()));
    END;

    IF v_aborted THEN
      v_reaped := v_reaped + 1;
      -- THE ONE CALLER fn_cash_cluster_pool_health HAS EVER HAD, and the
      -- moment it is worth paying for: an operator reading this event
      -- afterwards gets the Cluster's population, thresholds, headroom, seat
      -- occupancy and confidence as they stood when it was reaped, rather than
      -- having to reconstruct them from a database that has moved on.
      INSERT INTO public.cash_cluster_events (game_id, kind, payload)
      VALUES (c.cluster_id, 'lightning_pending_on_reaped', jsonb_build_object(
        'conversion_id', c.id, 'conversion_request_id', c.conversion_request_id,
        'opened_at', c.opened_at,
        'stuck_for', justify_interval(p_now - c.opened_at)::text,
        'max_age', v_age::text,
        'abort', v_res,
        'pool_health', public.fn_cash_cluster_pool_health(c.cluster_id, p_now)));
    ELSE
      v_skipped := v_skipped + 1;
    END IF;

    v_rows := v_rows || jsonb_build_object(
      'conversion_id', c.id, 'cluster_id', c.cluster_id,
      'reaped', v_aborted, 'answer', v_res);
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true, 'examined', v_seen, 'reaped', v_reaped, 'skipped', v_skipped,
    'failed', v_failed,
    'max_age', v_age::text, 'as_of', p_now, 'conversions', v_rows);
END;
$$;


ALTER FUNCTION public.fn_cash_cluster_reap_stuck_conversions(p_max_age interval, p_now timestamp with time zone, p_limit integer) OWNER TO postgres;

--
-- TOC entry 46474 (class 0 OID 0)
-- Dependencies: 3538
-- Name: FUNCTION fn_cash_cluster_reap_stuck_conversions(p_max_age interval, p_now timestamp with time zone, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_reap_stuck_conversions(p_max_age interval, p_now timestamp with time zone, p_limit integer) IS 'The recovery nothing had: a cash_cluster_conversion left pending for longer than p_max_age (fifteen minutes by default) is aborted and its halts lifted, so a Cluster whose commit_lightning raised - or whose caller stopped polling - cannot sit in PENDING_ON with every table stopped until a human notices. Reachable from fn_cash_clusters_tick_all, which keeps running precisely because the per-Cluster tick stands down in pending_on. Skips any pending conversion that is not a lightning conversion of a pending_on Cluster, so Phase 10''s drain is not touched. Not gated on the platform freeze, deliberately, exactly as the abort it calls is not.';


--
-- TOC entry 7827 (class 1255 OID 20962004)
-- Name: fn_cash_cluster_tick(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_tick(p_game_id uuid, p_eligible_horses integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g record; t record; r record;
  g_mode record;
  v_front uuid;
  v_census public.cash_cluster_census_row[];
  v_actions jsonb := '[]'::jsonb;
  v_now timestamptz := clock_timestamp();
  v_seated_total integer := 0;
  v_live_tables integer := 0;
  v_open_unreserved integer := 0;
  v_buyers integer;
  v_waiting integer;
  v_prev_feeder record;
  v_candidate record;
  v_floor integer;
  v_remaining_capacity integer;
  v_remaining_tables integer;
  v_main1 record;
  v_new_state text;
  v_moves integer := 0;
  v_n integer;
  v_idx integer;
  v_shortest uuid;
  v_table_cap integer;
  v_hands integer;
  v_orbit integer;
  v_window interval;
BEGIN
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'skipped', 'frozen');
  END IF;

  -- STAND DOWN BEFORE THE LOCK (2026-09-26). A plain read of the mode; a
  -- Cluster that is converting or converted is left without its row being
  -- taken, so the tick never holds a Lightning Cluster's row against a
  -- formation.
  SELECT cg.must_move, cg.cluster_mode, cg.cluster_epoch INTO g_mode
    FROM public.cash_games cg WHERE cg.id = p_game_id;
  IF FOUND AND g_mode.must_move AND g_mode.cluster_mode IS DISTINCT FROM 'must_move' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'lightning_cluster_stands_down',
      'cluster_mode', g_mode.cluster_mode, 'cluster_epoch', g_mode.cluster_epoch,
      'locked', false);
  END IF;

  /* A WAKE DOES NOT QUEUE BEHIND THE PASS (2026-10-03). Called by the pass
     (fn_cash_clusters_tick_all publishes ca.cluster_pass_deadline), the tick
     waits for its row as before, bounded by the pass's lock_timeout. Called
     alone, as the engine's per-game wake, it takes the row only if nobody
     holds it: a held row means the pass (or another wake) is ticking this
     game now, and the next pass ticks it again in five seconds. Waiting
     cost 27,682 wakes 8,486 s in 100 minutes (mean 307 ms, max 5.8 s),
     almost all of it behind the pass's transaction. */
  IF COALESCE(current_setting('ca.cluster_pass_deadline', true), '') = '' THEN
    SELECT * INTO g FROM public.cash_games WHERE id = p_game_id FOR UPDATE SKIP LOCKED;
    IF NOT FOUND THEN
      IF EXISTS (SELECT 1 FROM public.cash_games cg WHERE cg.id = p_game_id) THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'ticking_elsewhere', 'locked', false);
      END IF;
      RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
    END IF;
  ELSE
    SELECT * INTO g FROM public.cash_games WHERE id = p_game_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF;
  END IF;
  IF NOT g.must_move THEN RETURN jsonb_build_object('ok', false, 'reason', 'manual_game'); END IF;
  -- LIGHTNING 2.0 PHASE 5. must_move is the CAPABILITY - does this game use
  -- must-move seating at all - and cluster_mode is the STATE. A Cluster that
  -- is converting, or has converted, keeps the capability and changes the
  -- state, because Phase 10 reverts to must-move seating using these very
  -- rules and a Cluster that had turned the capability off would have nothing
  -- to turn back on. This function read the capability and never the state,
  -- so it would have gone on opening feeders, planning moves, balancing and
  -- reconciling Main 1 underneath a Lightning pool.
  IF g.cluster_mode IS DISTINCT FROM 'must_move' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'lightning_cluster_stands_down',
      'cluster_mode', g.cluster_mode, 'cluster_epoch', g.cluster_epoch);
  END IF;

  -- ── 1. RECONCILE ─────────────────────────────────────────────────────────
  -- AN EXPIRED MOVE SAYS WHAT IT WAS WAITING FOR (2026-09-07). Three
  -- different failures land here and the row could not tell them apart.
  -- A DEADLINE DOES NOT RUN WHILE THE PLATFORM IS PARKING (2026-09-09).
  -- fn_platform_frozen() (checked at the top of this function) is the :55-:00
  -- freeze. fn_entry_purchases_frozen() is WIDER: it is also true from :53,
  -- when the break is announced and the last hand is called, and through the
  -- post-thaw release boundary. fn_cash_seat_move_execute refuses on the wider
  -- one. So in that window the tick is awake and the executor cannot act, and
  -- expiring a move there blames the engine for a refusal the platform made
  -- (CLAUDE.md 10.86 rule 1). Measured: 38% of all expiries fell in the two
  -- five-minute buckets either side of :55.
  --
  -- So the deadline is held instead, forward to the three minutes
  -- fn_cash_seat_move_window guarantees as its floor. GREATEST never shortens
  -- a longer window. fn_thaw_platform then shifts what is still pending at
  -- :00, exactly as CLAUDE.md 13 rule 4 requires.
  IF public.fn_entry_purchases_frozen() THEN
    UPDATE public.cash_seat_moves m
       SET expires_at = GREATEST(m.expires_at, v_now + interval '3 minutes')
     WHERE m.game_id = g.id AND m.state = 'pending'
       AND m.expires_at <= v_now + interval '3 minutes';
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n > 0 THEN v_actions := v_actions || jsonb_build_object('moves_held_for_maintenance', v_n); END IF;
  ELSE
    UPDATE public.cash_seat_moves m SET state = 'expired',
           note = CASE
                    WHEN NOT EXISTS (SELECT 1 FROM public.table_seats ts
                                      WHERE ts.table_id = m.from_table_id
                                        AND ts.user_id = m.player_id AND ts.left_at IS NULL)
                      THEN 'player_left_before_boundary'
                    WHEN EXISTS (SELECT 1 FROM public.table_seats ts
                                  WHERE ts.table_id = m.from_table_id
                                    AND ts.user_id = m.player_id AND ts.left_at IS NULL
                                    AND coalesce(ts.stack, 0) = 0)
                      THEN 'player_busted_before_boundary'
                    ELSE 'engine_did_not_execute_before_expiry'
                  END
     WHERE m.game_id = g.id AND m.state = 'pending' AND m.expires_at <= v_now;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n > 0 THEN v_actions := v_actions || jsonb_build_object('moves_expired', v_n); END IF;
  END IF;

  -- THE SNAPSHOT IS THE RULE (Gate 5, 2026-09-05). Every open table of the
  -- game carries exactly the rules its snapshot says; a table that drifted
  -- (54 did, on the VPIP floor alone) is corrected here, every tick.
  v_n := public.fn_cash_apply_ruleset(g.id);
  IF v_n > 0 THEN v_actions := v_actions || jsonb_build_object('ruleset_applied', v_n); END IF;

  -- THE ROSTER AND THE SEAT-CHANGE LIST (Dan 2026-09-05). A roster row whose
  -- player holds no chair in the game and has no move planned is closed (the
  -- seat trigger closes most of them; this catches a chair that emptied
  -- while a move was pending and the move then died). A seat change whose
  -- move was cancelled or expired goes back on the list, at its old place;
  -- the back-off in the planner gives the refusal its minute.
  UPDATE public.cash_game_roster ro SET left_at = v_now
   WHERE ro.game_id = g.id AND ro.left_at IS NULL
     AND NOT EXISTS (SELECT 1 FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
                      WHERE ts.user_id = ro.user_id AND ts.left_at IS NULL AND tb.cluster_id = g.id AND tb.lifecycle <> 'closed')
     AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves mv WHERE mv.player_id = ro.user_id AND mv.game_id = g.id AND mv.state = 'pending');
  UPDATE public.cash_seat_change_requests rq SET status = 'cancelled', resolved_at = v_now, note = 'left_game'
   WHERE rq.game_id = g.id AND rq.status = 'requested'
     AND NOT EXISTS (SELECT 1 FROM public.cash_game_roster ro WHERE ro.game_id = g.id AND ro.user_id = rq.user_id AND ro.left_at IS NULL);
  -- THE REQUEST COMES BACK WHEREVER THEY ARE SITTING (2026-09-09). This
  -- asked whether the player was still in the table they REQUESTED FROM, so a
  -- request whose move died after a must-move or a break had already taken
  -- them elsewhere in the same game stayed 'moved' for ever, with the
  -- allowance spent and no change delivered. The player is asked for by GAME
  -- now, and the request is re-listed from the chair they are actually in, so
  -- the planner reads a from_table_id that is true.
  -- (a scalar subquery, not a LATERAL: Postgres refuses a lateral reference to
  --  the UPDATE target from the FROM list, 42P10. The EXISTS keeps the NOT NULL
  --  column honest - a player with no chair at all in the game is the roster
  --  trigger's case, not this one.)
  UPDATE public.cash_seat_change_requests rq
     SET status = 'requested', resolved_at = NULL, move_id = NULL, note = 'move_' || mv.state,
         from_table_id = (SELECT ts.table_id FROM public.table_seats ts
                            JOIN public.tables tb ON tb.id = ts.table_id
                           WHERE ts.user_id = rq.user_id AND ts.left_at IS NULL
                             AND tb.cluster_id = g.id AND tb.lifecycle <> 'closed'
                           ORDER BY ts.joined_at LIMIT 1)
    FROM public.cash_seat_moves mv
   WHERE rq.game_id = g.id AND rq.status = 'moved' AND rq.move_id = mv.id AND mv.state IN ('cancelled', 'expired')
     AND EXISTS (SELECT 1 FROM public.table_seats ts
                   JOIN public.tables tb ON tb.id = ts.table_id
                  WHERE ts.user_id = rq.user_id AND ts.left_at IS NULL
                    AND tb.cluster_id = g.id AND tb.lifecycle <> 'closed');

  -- THE GAME WAITLIST (Gate 4, 2026-09-05). A row whose player now holds a
  -- seat in the game is `seated`; a `notified` row (the join door told them
  -- a seat was open) that has not turned into a seat in three minutes is
  -- `expired` - their browser asks again if they are still there, and the
  -- OPEN rule stops counting a buyer who left.
  UPDATE public.cash_game_waitlist w SET status = 'seated', updated_at = v_now
   WHERE w.game_id = g.id AND w.status IN ('waiting', 'notified')
     AND EXISTS (SELECT 1 FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
                  WHERE ts.user_id = w.user_id AND ts.left_at IS NULL AND tb.cluster_id = g.id AND tb.lifecycle <> 'closed');
  UPDATE public.cash_game_waitlist w SET status = 'expired', updated_at = v_now
   WHERE w.game_id = g.id AND w.status = 'notified' AND w.updated_at < v_now - interval '3 minutes';

  -- Active seats cannot commit against a closed parent; no reopen repair is needed.

  -- Duplicate committed chairs are rejected by one_committed_seat_per_game_player.
  -- The cluster planner never pays away a chair outside its engine hand boundary.

  -- AN OPENING FEEDER NOBODY CAME TO (2026-09-05, window raised the same
  -- night). It was opened for two buyers; SIX minutes with nobody on it
  -- means they went elsewhere. It closes, the live feeder it was going to
  -- promote stays the feeder, and OPEN below waits two minutes before
  -- trying again.
  --
  -- WHY SIX AND NOT THREE. The buyers are horses, and the fleet that seats
  -- them reads the open-table list ONCE at the top of a cycle that takes 57
  -- to 118 seconds (HorseFleetManager: "Seeding cycle took 118s and 3 30s
  -- tick(s) were dropped while it ran"), on a 30-second tick. Three minutes
  -- is shorter than one worst-case cycle plus a full tick interval, so a
  -- feeder could be closed before the fleet's next cycle ever reached it -
  -- and the fleet then bought into the closed row and was refused
  -- TABLE_CLOSING. Measured 2026-09-05 20:45 CDT: 22 feeder_opened, 4
  -- feeder_live, 20 feeder_abandoned in one hour; NLH 0.05/0.10 Classic
  -- abandoned 11 in 90 minutes. 118s + 30s is 148s, so six minutes is that
  -- with a full cycle of margin on top. The two-minute rest after an abandon
  -- and the 60-second opening hold are unchanged.
  FOR t IN SELECT tb.id FROM public.tables tb
            WHERE tb.cluster_id = g.id AND tb.lifecycle = 'opening'
              AND coalesce(tb.is_deleted, false) = false
              AND coalesce(tb.opened_at, tb.created_at) < v_now - interval '6 minutes'
              AND NOT EXISTS (SELECT 1 FROM public.table_seats ts WHERE ts.table_id = tb.id AND ts.left_at IS NULL)
  LOOP
    UPDATE public.tables SET status = 'closed', lifecycle = 'closed', current_players = 0, updated_at = now()
     WHERE id = t.id;
    UPDATE public.tables SET promote_pending = false
     WHERE cluster_id = g.id AND role = 'feeder' AND promote_pending;
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind) VALUES (g.id, t.id, 'feeder_abandoned');
    v_actions := v_actions || jsonb_build_object('feeder_abandoned', t.id);
  END LOOP;

  -- A TABLE CLOSED BY STATUS BUT NOT BY LIFECYCLE (2026-09-05). Fifteen
  -- cluster tables carried status = 'closed' with lifecycle still 'live'
  -- (an operator's close-game action and the pre-controller close path
  -- write status only). The census reads status and drops them, the roles
  -- step reads lifecycle and still counts them, so a game could hold a
  -- Main 1 nobody could see and a feeder with nobody to feed. With no seat
  -- on it, the lifecycle follows the status; with a seat on it, the closed
  -- table sweep above has already put it back to breaking.
  UPDATE public.tables SET lifecycle = 'closed', current_players = 0, updated_at = now()
   WHERE cluster_id = g.id AND status = 'closed' AND lifecycle <> 'closed'
     AND coalesce(is_deleted, false) = false
     -- An enabled game's Main 1 is not followed down: R3 below repairs it in
     -- place (same id, same lobby links) instead of opening a replacement.
     AND NOT (g.enabled AND role = 'main' AND main_index = 1)
     AND NOT EXISTS (SELECT 1 FROM public.table_seats ts WHERE ts.table_id = public.tables.id AND ts.left_at IS NULL);
  -- AND THE SAME SPLIT IN THE OTHER DIRECTION (2026-09-09).
  -- The statement above repairs `status closed / lifecycle live`. The mirror -
  -- `lifecycle closed / status waiting` - had no repair at all, and it is the
  -- one that reaches a PLAYER: the lobby and every status-based read treat the
  -- table as joinable while fn_cash_apply_ruleset skips it as closed, so it can
  -- be sat at while carrying a ruleset nobody is reconciling. Measured
  -- 2026-09-09: 32 fleet tables in exactly that state, five of them still
  -- advertising an ante or a bomb pot their game had already dropped.
  -- Only EMPTY ones are followed down; a closed-lifecycle table with a seat on
  -- it is already sent back to `breaking` by the sweep further up, which is the
  -- path that walks it empty first.
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN
    INSERT INTO public.cash_cluster_events (game_id, kind, payload) VALUES (g.id, 'lifecycle_followed_status', jsonb_build_object('tables', v_n));
    v_actions := v_actions || jsonb_build_object('lifecycle_followed_status', v_n);
  END IF;

  UPDATE public.tables SET status = 'closed', current_players = 0, updated_at = now()
   WHERE cluster_id = g.id AND lifecycle = 'closed' AND status <> 'closed'
     AND coalesce(is_deleted, false) = false
     AND NOT EXISTS (SELECT 1 FROM public.table_seats ts WHERE ts.table_id = public.tables.id AND ts.left_at IS NULL);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN
    INSERT INTO public.cash_cluster_events (game_id, kind, payload)
      VALUES (g.id, 'status_followed_lifecycle', jsonb_build_object('tables', v_n));
    v_actions := v_actions || jsonb_build_object('status_followed_lifecycle', v_n);
  END IF;

  -- THE HEADCOUNT COLUMN IS THE SEATS (2026-09-05, 15:05). tables.current_players
  -- is what every per-table surface paints and the engine writes it only
  -- when it loads seats to deal; a table with one seated player and no
  -- engine said 0 (22 of them live). The seats are the truth; the column
  -- follows them here, every tick, for this game's open tables.
  UPDATE public.tables tb SET current_players = s.n
    FROM (SELECT tx.id, (SELECT count(*) FROM public.table_seats ts WHERE ts.table_id = tx.id AND ts.left_at IS NULL)::integer AS n
            FROM public.tables tx WHERE tx.cluster_id = g.id AND tx.lifecycle <> 'closed' AND coalesce(tx.is_deleted, false) = false) s
   WHERE tb.id = s.id AND tb.current_players IS DISTINCT FROM s.n;

  v_census := public.fn_cash_cluster_census(g.id, v_now);
  SELECT coalesce(sum(c.seated), 0), count(*) INTO v_seated_total, v_live_tables FROM unnest(v_census) c;

  -- R3: an enabled game always has Main 1 open. Anything that closed it
  -- (a stray close, the pre-controller lifecycle pass, a restart) is undone
  -- here rather than by a row flag.
  --
  -- THE LOOKUP READS THE LIVE BOARD, NOT THE OLDEST ROW (2026-09-05, 14:45).
  -- This used to select the oldest table ever numbered Main 1, closed or not.
  -- On NLH 0.05/0.10 Classic the original Main 1 was closed for good, so
  -- every tick found a closed row, took the "open a new one" branch, and
  -- opened a fresh Main 1: 3,000 tables in 148 minutes (08:01 to 10:29),
  -- every one of them then broken and renumbered by the steps below, 10,989
  -- moves planned to shuffle 43 players through them. Now: a Main 1 that is
  -- live or opening on a waiting/running table is the game's; a game with
  -- ANY live table but no such Main 1 leaves it to the ROLES step, which
  -- promotes the oldest live table (that is what Main 1 means, 1.3 s9.2);
  -- only a game with no live table at all opens one. The status-only repair
  -- (a live-lifecycle Main 1 whose status got set to closed) stays.
  SELECT * INTO v_main1 FROM public.tables
   WHERE cluster_id = g.id AND role = 'main' AND main_index = 1 AND coalesce(is_deleted, false) = false
     AND lifecycle IN ('live', 'opening')
   ORDER BY created_at LIMIT 1;
  IF g.enabled AND v_main1.id IS NOT NULL AND v_main1.status NOT IN ('waiting', 'running', 'active') THEN
    UPDATE public.tables SET status = 'waiting', lifecycle = 'live', current_players = 0, updated_at = now()
     WHERE id = v_main1.id;
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind) VALUES (g.id, v_main1.id, 'main1_reopened');
    v_actions := v_actions || jsonb_build_object('main1', 'reopened');
    v_census := public.fn_cash_cluster_census(g.id, v_now);
    SELECT coalesce(sum(c.seated), 0), count(*) INTO v_seated_total, v_live_tables FROM unnest(v_census) c;
  ELSIF g.enabled AND v_main1.id IS NULL
        AND NOT EXISTS (SELECT 1 FROM public.tables
                         WHERE cluster_id = g.id AND coalesce(is_deleted, false) = false
                           AND lifecycle IN ('live', 'opening', 'breaking') AND status IN ('waiting', 'running', 'active')) THEN
    IF coalesce(g.lightning_enabled, false) THEN
      PERFORM public.fn_cash_cluster_open_table(g.id, 'feeder', NULL, 'live', NULL);
      v_actions := v_actions || jsonb_build_object('feeder1', 'opened');
    ELSE
      PERFORM public.fn_cash_cluster_open_table(g.id, 'main', 1, 'live', NULL);
      v_actions := v_actions || jsonb_build_object('main1', 'opened');
    END IF;
    -- Recount after the repair; the rest of the tick sees the real board.
    v_census := public.fn_cash_cluster_census(g.id, v_now);
    SELECT coalesce(sum(c.seated), 0), count(*) INTO v_seated_total, v_live_tables FROM unnest(v_census) c;
  END IF;

  -- ── 2. MUST-MOVE (1.3 s9.5) ──────────────────────────────────────────────
  -- For every Main with an unreserved open seat, the longest-seated player on
  -- the feeder (or on a breaking table) is planned onto it, one per seat,
  -- one per player. The engine executes at the player's next hand boundary.
  FOR t IN SELECT * FROM unnest(v_census) c
            WHERE c.role = 'main' AND c.lifecycle = 'live' AND c.open_unreserved > 0
            ORDER BY c.main_index
  LOOP
    v_n := t.open_unreserved
         - (SELECT count(*) FROM public.cash_seat_moves m WHERE m.to_table_id = t.id AND m.state = 'pending' AND m.swap_move_id IS NULL);
    FOR r IN
      SELECT ts.user_id, ts.table_id
        FROM public.table_seats ts
        JOIN unnest(v_census) c ON c.id = ts.table_id
       WHERE ts.left_at IS NULL AND ts.user_id IS NOT NULL
         -- A Main 1 seat draws from the WHOLE list (every table but Main 1);
         -- a Main N seat draws from the feeder and any breaking table.
         AND (c.role = 'feeder' OR c.breaking OR (t.main_index = 1 AND c.id <> t.id))
         AND c.id <> t.id
         -- NOT WITH NOTHING, NOT WHILE LEAVING (2026-09-05): a busted seat is
         -- in its rebuy window, a leave_pending seat is on its way out.
         AND coalesce(ts.stack, 0) > 0
         AND coalesce(ts.leave_pending, false) = false
         -- Never onto a table they are already sitting at.
         AND NOT EXISTS (SELECT 1 FROM public.table_seats d WHERE d.table_id = t.id AND d.user_id = ts.user_id AND d.left_at IS NULL)
         AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves m WHERE m.player_id = ts.user_id AND m.state = 'pending')
         -- BACK-OFF (2026-09-05): a move the engine just refused (cancelled
         -- with a note) is not re-planned every 5 s; the refusal gets a minute.
         AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves m WHERE m.player_id = ts.user_id AND m.state = 'cancelled' AND coalesce(m.resolved_at, m.created_at) > v_now - interval '60 seconds')
       -- THE ORDER YOU JOINED THE GAME (Dan 2026-09-05): the roster's
       -- joined_at, which survives every move; the chair's own joined_at
       -- only for a chair that predates the roster.
       ORDER BY c.breaking DESC,
                coalesce((SELECT r2.joined_at FROM public.cash_game_roster r2
                           WHERE r2.game_id = g.id AND r2.user_id = ts.user_id AND r2.left_at IS NULL), ts.joined_at) ASC,
                ts.joined_at ASC
       LIMIT GREATEST(v_n, 0)
    LOOP
      INSERT INTO public.cash_seat_moves (game_id, player_id, from_table_id, to_table_id, reason)
      VALUES (g.id, r.user_id, r.table_id, t.id, 'must_move');
      v_moves := v_moves + 1;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
      VALUES (g.id, t.id, 'move_planned', jsonb_build_object('player_id', r.user_id, 'from_table_id', r.table_id, 'reason', 'must_move'));
    END LOOP;
  END LOOP;
  IF v_moves > 0 THEN v_actions := v_actions || jsonb_build_object('moves_planned', v_moves); END IF;

  -- ── 2b. SEAT CHANGES (Dan 2026-09-05) ────────────────────────────────────
  -- After Main seats are filled in must-move order and before a feeder is
  -- opened: a requested table change takes the next unreserved chair on a
  -- table that is not Main 1, oldest request first; two requests that would
  -- take each other's table are swapped.
  v_n := public.fn_cash_seat_change_plan(g.id, v_now);
  IF v_n > 0 THEN v_actions := v_actions || jsonb_build_object('seat_changes_planned', v_n); END IF;

  -- ── 3. OPEN (18.3) ───────────────────────────────────────────────────────
  SELECT coalesce(sum(c.open_unreserved), 0) INTO v_open_unreserved
    FROM unnest(v_census) c WHERE c.lifecycle IN ('live', 'opening') AND NOT c.breaking;
  SELECT count(*) INTO v_waiting FROM public.cash_game_waitlist w
   WHERE w.game_id = g.id AND w.status IN ('waiting', 'notified');
  v_buyers := v_waiting + GREATEST(coalesce(p_eligible_horses, 0), 0);
  -- (a CASE ... THEN inside an IF condition ends the condition early in
  --  PL/pgSQL, so the cap is computed first)
  v_table_cap := g.cap_mains + 1;
  IF g.allow_second_feeder THEN v_table_cap := v_table_cap + 1; END IF;

  IF g.enabled AND v_open_unreserved = 0 AND v_live_tables > 0
     AND NOT EXISTS (SELECT 1 FROM unnest(v_census) c WHERE c.lifecycle = 'opening')
     AND v_live_tables < v_table_cap
     -- Two minutes after a feeder was abandoned, not before.
     AND NOT EXISTS (SELECT 1 FROM public.cash_cluster_events e
                      WHERE e.game_id = g.id AND e.kind = 'feeder_abandoned' AND e.at > v_now - interval '2 minutes') THEN
    IF v_buyers >= 2 THEN
      UPDATE public.tables SET promote_pending = true
       WHERE cluster_id = g.id AND role = 'feeder' AND lifecycle = 'live';
      PERFORM public.fn_cash_cluster_open_table(g.id, 'feeder', NULL, 'opening', NULL);
      UPDATE public.cash_games SET opening_hold_since = NULL WHERE id = g.id;
      v_actions := v_actions || jsonb_build_object('feeder', 'opened', 'buyers', v_buyers);
    ELSIF v_buyers = 1 THEN
      -- One buyer holds for 60 s; the fleet's next cycle usually brings a
      -- partner. No ghost table.
      -- AN EXPIRED HOLD RESTS (2026-09-05): five minutes before the next.
      IF g.opening_hold_since IS NULL
         AND (g.opening_hold_rested_until IS NULL OR g.opening_hold_rested_until <= v_now) THEN
        UPDATE public.cash_games SET opening_hold_since = v_now WHERE id = g.id;
        INSERT INTO public.cash_cluster_events (game_id, kind) VALUES (g.id, 'table_opening_hold');
        v_actions := v_actions || jsonb_build_object('opening_hold', 'started');
      ELSIF g.opening_hold_since IS NOT NULL AND g.opening_hold_since < v_now - interval '60 seconds' THEN
        UPDATE public.cash_games SET opening_hold_since = NULL, opening_hold_rested_until = v_now + interval '5 minutes' WHERE id = g.id;
        INSERT INTO public.cash_cluster_events (game_id, kind) VALUES (g.id, 'table_opening_hold_expired');
        v_actions := v_actions || jsonb_build_object('opening_hold', 'expired');
      END IF;
    END IF;
  ELSIF g.opening_hold_since IS NOT NULL THEN
    UPDATE public.cash_games SET opening_hold_since = NULL WHERE id = g.id;
  END IF;

  -- ── 4. PROMOTE (18.3) ────────────────────────────────────────────────────
  -- An opening feeder with two seated is live. The feeder before it, marked
  -- promote_pending, becomes Main N+1.
  FOR t IN SELECT * FROM unnest(v_census) c WHERE c.lifecycle = 'opening' AND c.seated >= 2 LOOP
    UPDATE public.tables SET lifecycle = 'live', live_at = v_now WHERE id = t.id;
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind) VALUES (g.id, t.id, 'feeder_live');
    SELECT coalesce(max(main_index), 0) + 1 INTO v_idx FROM public.tables
     WHERE cluster_id = g.id AND role = 'main' AND lifecycle <> 'closed' AND coalesce(is_deleted, false) = false;
    FOR v_prev_feeder IN SELECT id, name FROM public.tables
                          WHERE cluster_id = g.id AND role = 'feeder' AND promote_pending AND id <> t.id
                            AND lifecycle = 'live' ORDER BY created_at
    LOOP
      UPDATE public.tables SET role = 'main', main_index = v_idx, promote_pending = false,
             name = left(g.name, 50) || ' Main ' || v_idx
       WHERE id = v_prev_feeder.id;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
      VALUES (g.id, v_prev_feeder.id, 'feeder_promoted_to_main', jsonb_build_object('main_index', v_idx));
      v_idx := v_idx + 1;
    END LOOP;
    v_actions := v_actions || jsonb_build_object('feeder_live', t.id);
  END LOOP;

  -- Refresh the census for the steps that read roles (the counts are the
  -- tick's own snapshot and stay).
  SELECT coalesce(array_agg(
           (tb.id, tb.role, tb.main_index, tb.lifecycle, c.status, c.created_at, c.max_players,
            c.seated, c.reserved, c.open_unreserved, c.breaking)::public.cash_cluster_census_row
           ORDER BY c.created_at), '{}'::public.cash_cluster_census_row[])
    INTO v_census
    FROM unnest(v_census) c JOIN public.tables tb ON tb.id = c.id;

  -- ── 5. BREAK (18.3) ──────────────────────────────────────────────────────
  -- Candidate: newest table first (feeder, then the highest main), never
  -- Main 1, never a table still opening. Condition: everyone fits in the
  -- rest at or above the floor. It breaks when that has held for the
  -- SHORTER of two completed orbits on the candidate or five minutes
  -- (OPORD 1.4 18.3). An orbit is one hand per seated player; a table
  -- with fewer than two seated deals no hands, so only the clock runs
  -- for it. Until 2026-09-05 only the clock ran for everyone, and a
  -- six-handed feeder that dealt twenty hands in four minutes with the
  -- whole game fitting elsewhere still sat there for the fifth.
  v_floor := CASE WHEN g.handedness <= 6 THEN 3 ELSE 4 END;
  -- EMPTY FIRST (2026-09-05, 14:50). An empty table has nobody to move and
  -- nothing to interrupt; it is the cheapest table to close and the one the
  -- lobby least wants to see. Then the newest.
  v_front := public.fn_cash_cluster_front_table(g.id);
  SELECT * INTO v_candidate FROM unnest(v_census) c
   WHERE c.id IS DISTINCT FROM v_front AND c.lifecycle = 'live'
   ORDER BY (c.seated = 0) DESC, (c.role = 'feeder') DESC, c.main_index DESC NULLS FIRST, c.created_at DESC LIMIT 1;

  IF NOT EXISTS (SELECT 1 FROM unnest(v_census) c WHERE c.breaking) AND v_candidate.id IS NOT NULL THEN
    SELECT coalesce(sum(c.max_players - c.reserved), 0), count(*) INTO v_remaining_capacity, v_remaining_tables
      FROM unnest(v_census) c WHERE c.id <> v_candidate.id AND c.lifecycle = 'live';
    -- THE FLOOR CLAUSE IS GONE (2026-09-05, 14:50). It read
    -- `seated_total >= floor x remaining_tables`: break only if the
    -- rest would average at or above the maintain floor afterwards. Breaking
    -- a table never makes the rest SHORTER, so the clause could only ever
    -- refuse the breaks that matter most: a game of 1 player on 4 tables
    -- (1 >= 3 x 3, never) kept all four for ever, and a game of 42 on 16
    -- (42 >= 4 x 15, never) never armed. Read live at 14:45: eligible_since
    -- NULL on every table of both. Dan's rule is "fewer tables, more players
    -- at each"; the floor is a target for the fleet to fill to, not a bar
    -- to consolidation. The STRICT fit stays (everyone fits AND the rest
    -- keeps a seat open, so the OPEN rule does not fire on the same board).
    IF v_remaining_tables >= 1
       AND v_seated_total < v_remaining_capacity THEN
      SELECT break_eligible_since INTO r FROM public.tables WHERE id = v_candidate.id;
      IF r.break_eligible_since IS NULL THEN
        UPDATE public.tables SET break_eligible_since = v_now WHERE id = v_candidate.id;
        v_actions := v_actions || jsonb_build_object('break_eligible', v_candidate.id);
      ELSE
        v_orbit := v_candidate.seated;
        v_hands := 0;
        IF v_orbit >= 2 THEN
          SELECT count(*) INTO v_hands FROM public.hand_history h
           WHERE h.table_id = v_candidate.id AND h.created_at >= r.break_eligible_since;
        END IF;
        -- A TABLE WITH NOBODY, OR ONE PLAYER, HAS NOTHING TO INTERRUPT
        -- (2026-09-05): no hand can be dealt there, so the five-minute
        -- window protects nobody. Sixty seconds is enough to let someone who
        -- is sitting down finish sitting down.
        -- (computed first: a CASE ... THEN inside an IF condition ends the
        --  condition early in PL/pgSQL, see the OPEN rule's cap above)
        v_window := CASE WHEN v_orbit <= 1 THEN interval '60 seconds' ELSE interval '5 minutes' END;
        IF r.break_eligible_since <= v_now - v_window
           OR (v_orbit >= 2 AND v_hands >= 2 * v_orbit) THEN
          UPDATE public.tables SET lifecycle = 'breaking', break_started_at = v_now, break_eligible_since = NULL
           WHERE id = v_candidate.id;
          SELECT coalesce(array_agg(
                   (c.id, c.role, c.main_index,
                    CASE WHEN c.id = v_candidate.id THEN 'breaking' ELSE c.lifecycle END,
                    c.status, c.created_at, c.max_players, c.seated, c.reserved, c.open_unreserved,
                    c.breaking OR c.id = v_candidate.id)::public.cash_cluster_census_row
                   ORDER BY c.created_at), '{}'::public.cash_cluster_census_row[])
            INTO v_census FROM unnest(v_census) c;
          INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
          VALUES (g.id, v_candidate.id, 'table_break_started',
                  jsonb_build_object('seated_total', v_seated_total, 'remaining_capacity', v_remaining_capacity,
                                     'eligible_since', r.break_eligible_since, 'hands_since_eligible', v_hands, 'orbit', v_orbit));
          v_actions := v_actions || jsonb_build_object('break_started', v_candidate.id,
                                                       'hands_since_eligible', v_hands, 'orbit', v_orbit);
        END IF;
      END IF;
    ELSE
      UPDATE public.tables SET break_eligible_since = NULL
       WHERE cluster_id = g.id AND break_eligible_since IS NOT NULL;
    END IF;
  ELSE
    UPDATE public.tables SET break_eligible_since = NULL
     WHERE cluster_id = g.id AND break_eligible_since IS NOT NULL;
  END IF;

  -- A breaking table: every seated player is planned onto the shortest live
  -- table with room (must-move already took the mains' open seats above;
  -- this covers what is left, feeder included). When the last chair is
  -- empty it closes.
  FOR t IN SELECT * FROM unnest(v_census) c WHERE c.breaking LOOP
    IF t.seated = 0 THEN
      UPDATE public.tables SET status = 'closed', lifecycle = 'closed', current_players = 0, updated_at = now()
       WHERE id = t.id;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind) VALUES (g.id, t.id, 'table_break_completed');
      SELECT coalesce(array_agg(c ORDER BY c.created_at), '{}'::public.cash_cluster_census_row[])
        INTO v_census FROM unnest(v_census) c WHERE c.id <> t.id;
      v_actions := v_actions || jsonb_build_object('closed', t.id);
      CONTINUE;
    END IF;
    -- Native committed ownership makes duplicate-chair cashout unnecessary.
    FOR r IN SELECT ts.user_id FROM public.table_seats ts
              WHERE ts.table_id = t.id AND ts.left_at IS NULL AND ts.user_id IS NOT NULL
                AND coalesce(ts.stack, 0) > 0
                AND coalesce(ts.leave_pending, false) = false
                AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves m WHERE m.player_id = ts.user_id AND m.state = 'pending')
                AND NOT EXISTS (SELECT 1 FROM public.cash_seat_moves m WHERE m.player_id = ts.user_id AND m.state = 'cancelled' AND coalesce(m.resolved_at, m.created_at) > v_now - interval '60 seconds')
              ORDER BY coalesce((SELECT r2.joined_at FROM public.cash_game_roster r2
                                  WHERE r2.game_id = g.id AND r2.user_id = ts.user_id AND r2.left_at IS NULL), ts.joined_at),
                       ts.joined_at
    LOOP
      SELECT c.id INTO v_shortest FROM unnest(v_census) c
       WHERE c.id <> t.id AND NOT c.breaking AND c.lifecycle IN ('live', 'opening')
         AND c.open_unreserved - (SELECT count(*) FROM public.cash_seat_moves m WHERE m.to_table_id = c.id AND m.state = 'pending' AND m.swap_move_id IS NULL) > 0
         AND NOT EXISTS (SELECT 1 FROM public.table_seats d WHERE d.table_id = c.id AND d.user_id = r.user_id AND d.left_at IS NULL)
       ORDER BY c.seated ASC, c.main_index ASC NULLS LAST LIMIT 1;
      EXIT WHEN v_shortest IS NULL;
      INSERT INTO public.cash_seat_moves (game_id, player_id, from_table_id, to_table_id, reason)
      VALUES (g.id, r.user_id, t.id, v_shortest, 'break');
      v_moves := v_moves + 1;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
      VALUES (g.id, v_shortest, 'move_planned', jsonb_build_object('player_id', r.user_id, 'from_table_id', t.id, 'reason', 'break'));
    END LOOP;
  END LOOP;

  -- ── 6. ROLES (1.3 s9.2) ──────────────────────────────────────────────────
  -- Oldest live table is Main 1; mains renumber by age; with no feeder left
  -- and two or more tables, the newest becomes the feeder.
  -- A GAME WITH A FEEDER AND NO MAIN (2026-09-05). Found live: Main 1 closed
  -- by status under a disabled game, five players still on its feeder, and
  -- nothing below promoted the feeder because this step only renumbers
  -- mains. Oldest live table is Main 1 (1.3 s9.2); if no main is live, the
  -- oldest live feeder becomes it, so the players on it have a Main to be
  -- on and the R3 repair does not open a second table beside them.
  IF NOT EXISTS (SELECT 1 FROM unnest(v_census) c WHERE c.lifecycle IN ('live', 'opening') AND c.role = 'main')
     AND EXISTS (SELECT 1 FROM unnest(v_census) c WHERE c.lifecycle = 'live' AND c.role = 'feeder')
     -- LIGHTNING 2.0 PHASE 3 (lone_feeder_is_the_cluster): a Lightning-
     -- capable Cluster's ONE table is a feeder, by specification. There is
     -- nothing for a Main to receive movers FROM while it is the only table,
     -- so the promotion loses nothing by waiting; the moment a second table
     -- opens this arm fires and ordinary must-move roles resume.
     AND NOT (coalesce(g.lightning_enabled, false)
              AND (SELECT count(*) FROM unnest(v_census) c WHERE c.lifecycle IN ('live', 'opening')) = 1) THEN
    SELECT * INTO t FROM unnest(v_census) c WHERE c.lifecycle = 'live' AND c.role = 'feeder' ORDER BY c.created_at LIMIT 1;
    UPDATE public.tables SET role = 'main', main_index = 1, promote_pending = false, name = g.name WHERE id = t.id;
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
    VALUES (g.id, t.id, 'feeder_promoted_to_main', jsonb_build_object('main_index', 1, 'reason', 'no_live_main'));
    SELECT coalesce(array_agg(
             (c.id, CASE WHEN c.id = t.id THEN 'main' ELSE c.role END, CASE WHEN c.id = t.id THEN 1 ELSE c.main_index END,
              c.lifecycle, c.status, c.created_at, c.max_players, c.seated, c.reserved, c.open_unreserved, c.breaking)::public.cash_cluster_census_row
             ORDER BY c.created_at), '{}'::public.cash_cluster_census_row[])
      INTO v_census FROM unnest(v_census) c;
    v_actions := v_actions || jsonb_build_object('feeder_became_main1', t.id);
  END IF;
  v_idx := 0;
  FOR t IN SELECT * FROM unnest(v_census) c WHERE c.lifecycle IN ('live', 'opening') AND c.role = 'main' ORDER BY c.created_at LOOP
    v_idx := v_idx + 1;
    IF t.main_index IS DISTINCT FROM v_idx THEN
      UPDATE public.tables SET main_index = v_idx,
             name = CASE WHEN v_idx = 1 THEN g.name ELSE left(g.name, 50) || ' Main ' || v_idx END
       WHERE id = t.id;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
      VALUES (g.id, t.id, 'main_renumbered', jsonb_build_object('from', t.main_index, 'to', v_idx));
    END IF;
  END LOOP;
  IF v_idx >= 2 AND NOT EXISTS (SELECT 1 FROM unnest(v_census) c WHERE c.role = 'feeder' AND c.lifecycle IN ('live', 'opening')) THEN
    SELECT * INTO t FROM unnest(v_census) c WHERE c.role = 'main' AND c.lifecycle = 'live' ORDER BY c.created_at DESC LIMIT 1;
    UPDATE public.tables SET role = 'feeder', main_index = NULL, promote_pending = false,
           name = left(g.name, 50) || ' Feeder'
     WHERE id = t.id;
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind) VALUES (g.id, t.id, 'main_demoted_to_feeder');
    v_actions := v_actions || jsonb_build_object('demoted', t.id);
  END IF;

  -- A BREAKING MAIN KEEPS A NUMBER A SURVIVOR IS RENUMBERED INTO (2026-09-09).
  -- The loop above walks live|opening mains only, so a BREAKING main holds its
  -- old index while the survivors renumber past it. The break candidate is
  -- chosen empty-first, so an empty Main 2 is taken ahead of a populated
  -- feeder and Main 3 is renumbered to 2 in the same pass: two tables carrying
  -- main_index 2, both named "... Main 2", until the break completes and
  -- fn_closed_cluster_main_releases_index nulls the closed one. Nothing
  -- refuses the duplicate - there is no unique index on
  -- (cluster_id, main_index) - and fn_cash_clusters_to_tick reads
  -- `main_index = 1 AND lifecycle <> 'closed'`, which a breaking table
  -- satisfies, so the controller's eligible-horse map can be keyed on a table
  -- that refuses every player it is sent.
  --
  -- So the breaking one moves above the live range, here, in the transaction
  -- that created the collision. After the demote block on purpose: v_idx is
  -- the live main count and a demoted table's main_index is NULL, so these
  -- numbers can collide with nothing. Seats, lifecycle and planned moves are
  -- untouched.
  FOR t IN SELECT * FROM unnest(v_census) c
            WHERE c.breaking AND c.role = 'main'
              AND c.main_index IS NOT NULL AND c.main_index <= v_idx
            ORDER BY c.main_index
  LOOP
    v_idx := v_idx + 1;
    UPDATE public.tables SET main_index = v_idx, name = left(g.name, 50) || ' Main ' || v_idx
     WHERE id = t.id;
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
    VALUES (g.id, t.id, 'main_renumbered',
            jsonb_build_object('from', t.main_index, 'to', v_idx,
                               'reason', 'breaking_main_released_a_live_index'));
    v_actions := v_actions || jsonb_build_object('breaking_main_renumbered', t.id);
  END LOOP;

  -- ── enabled = false (18.4): no seeding, no opening; empties close ─────────
  IF NOT g.enabled THEN
    FOR t IN SELECT * FROM unnest(v_census) c WHERE c.seated = 0 LOOP
      UPDATE public.tables SET status = 'closed', lifecycle = 'closed', current_players = 0, updated_at = now() WHERE id = t.id;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind) VALUES (g.id, t.id, 'table_closed_disabled');
      v_actions := v_actions || jsonb_build_object('closed_disabled', t.id);
    END LOOP;
  END IF;

  -- ── 7. WAKE / SLEEP (18.4) ───────────────────────────────────────────────
  v_new_state := CASE WHEN v_seated_total = 0 AND coalesce(p_eligible_horses, 0) = 0 THEN 'dormant' ELSE 'live' END;
  -- NOT gated on g.enabled (2026-09-07). `enabled` says whether this game
  -- may OPEN tables; it has nothing to do with whether `state` is true. Three
  -- games sat at 'live' with no tables and nobody in them for 38 hours
  -- because a disabled game could never be corrected, and once its last table
  -- closed fn_cash_clusters_to_tick stopped admitting it at all.
  IF g.state IS DISTINCT FROM v_new_state THEN
    UPDATE public.cash_games SET state = v_new_state, updated_at = now() WHERE id = g.id;
    INSERT INTO public.cash_cluster_events (game_id, kind, payload)
    VALUES (g.id, CASE WHEN v_new_state = 'live' THEN 'game_woken' ELSE 'game_dormant' END,
            jsonb_build_object('seated_total', v_seated_total, 'eligible_horses', p_eligible_horses));
    v_actions := v_actions || jsonb_build_object('state', v_new_state);
  END IF;

  UPDATE public.cash_games SET last_tick_at = v_now, last_tick_actions = v_actions WHERE id = g.id;

  RETURN jsonb_build_object('ok', true, 'game_id', g.id, 'seated_total', v_seated_total,
                            'tables', v_live_tables, 'buyers', v_buyers, 'actions', v_actions);
END;
$$;


ALTER FUNCTION public.fn_cash_cluster_tick(p_game_id uuid, p_eligible_horses integer) OWNER TO postgres;

--
-- TOC entry 9374 (class 1255 OID 57591170)
-- Name: fn_cash_cluster_unfreeze(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_cluster_unfreeze(p_game_id uuid, p_operator uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g            record;
  v_reason     text := btrim(coalesce(p_reason, ''));
  v_before     numeric;
  v_after      numeric;
  v_instances  integer := 0;
  v_sessions   integer := 0;
  v_slots      integer := 0;
  v_tables     integer := 0;
  v_convs      integer := 0;
  v_epoch      integer;
  i            record;
  r_exit       record;
BEGIN
  IF v_reason = '' THEN
    RETURN jsonb_build_object('ok', false, 'unfrozen', false, 'reason', 'reason_required');
  END IF;
  IF p_operator IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'unfrozen', false, 'reason', 'operator_required');
  END IF;

  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'unfrozen', false, 'reason', 'not_found');
  END IF;
  IF g.cluster_mode IS DISTINCT FROM 'frozen' THEN
    RETURN jsonb_build_object('ok', false, 'unfrozen', false, 'reason', 'not_frozen',
                              'cluster_mode', g.cluster_mode);
  END IF;

  SELECT coalesce(sum(ts.stack), 0) INTO v_before
    FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.cluster_id = g.id AND ts.left_at IS NULL;

  FOR i IN
    SELECT li.id FROM public.lightning_instance li
     WHERE li.cluster_id = g.id AND li.state IN ('forming', 'reserved', 'dealing', 'settling')
     ORDER BY li.id
     FOR UPDATE
  LOOP
    UPDATE public.lightning_instance li
       SET state = 'abandoned',
           abandon_reason = 'cluster unfrozen by operator ' || p_operator || ': ' || v_reason,
           completed_at = CASE WHEN li.started_at IS NOT NULL
                               THEN GREATEST(clock_timestamp(), li.started_at) ELSE li.completed_at END
     WHERE li.id = i.id;
    v_instances := v_instances + 1;
  END LOOP;

  UPDATE public.lightning_pool_slot sl
     SET closed_at = GREATEST(clock_timestamp(), sl.opened_at), close_reason = 'cluster_unfrozen',
         updated_at = clock_timestamp()
   WHERE sl.cluster_id = g.id AND sl.closed_at IS NULL;
  GET DIAGNOSTICS v_slots = ROW_COUNT;

  -- LIGHTNING PHASE 9 (20261008050805): EVERY EXIT PATH SAYS
  -- pool_player_left. The unfreeze exited its sessions silently; it now
  -- records one per session, in the anchor-seat trigger's own payload shape.
  FOR r_exit IN
    UPDATE public.lightning_pool_session ps
       SET exited_at = GREATEST(clock_timestamp(), ps.entered_at), exit_reason = 'cluster_unfrozen',
           state = 'closed', ending_stack = public.fn_lightning_pool_stack(ps.id), updated_at = clock_timestamp()
     WHERE ps.cluster_id = g.id AND ps.exited_at IS NULL
    RETURNING ps.id, ps.cluster_id, ps.cluster_epoch, ps.player_id, ps.anchor_seat_id, ps.ending_stack
  LOOP
    v_sessions := v_sessions + 1;
    INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload, cluster_epoch)
    VALUES (r_exit.cluster_id,
            (SELECT ts.table_id FROM public.table_seats ts WHERE ts.id = r_exit.anchor_seat_id),
            'pool_player_left', jsonb_build_object(
      'cluster_id', r_exit.cluster_id, 'cluster_epoch', r_exit.cluster_epoch,
      'player_id', r_exit.player_id, 'pool_session_id', r_exit.id,
      'anchor_seat_id', r_exit.anchor_seat_id, 'reason', 'cluster_unfrozen',
      'ending_stack', r_exit.ending_stack, 'at', clock_timestamp()), r_exit.cluster_epoch);
  END LOOP;

  -- LIGHTNING PHASE 7 REMEDIATION (20261007222717): AN UNFREEZE CLOSES THE
  -- CONVERSION IT WOULD OTHERWISE ORPHAN. A Cluster frozen out of pending_off
  -- or pending_on still holds its open cash_cluster_conversion row; left
  -- pending, the one-open-per-cluster index refuses every later begin for
  -- ever (the drive recorded that as lightning_drive_error on every pass) and
  -- the reaper answers not_a_pending_on_lightning_conversion. It is closed
  -- here as an abort, so the record says what happened to it.
  UPDATE public.cash_cluster_conversion
     SET status = 'aborted', abort_reason = 'cluster_unfrozen', closed_at = clock_timestamp()
   WHERE cluster_id = g.id AND status = 'pending';
  GET DIAGNOSTICS v_convs = ROW_COUNT;

  -- A NEW EPOCH IN must_move, so nothing formed at the frozen epoch can ever be
  -- mistaken for the Cluster's present.
  PERFORM set_config('ca.epoch_reason', 'unfrozen', true);
  v_epoch := g.cluster_epoch + 1;
  -- 20261008043021: A STALE DWELL SIGHTING DOES NOT SURVIVE AN UNFREEZE.
  -- Cleared beside the halt clearing above, in the same UPDATE that moves the
  -- mode, so the next Lightning epoch cannot open PENDING_OFF on a single
  -- observation against a sighting recorded before the freeze.
  UPDATE public.cash_games SET cluster_mode = 'must_move', cluster_epoch = v_epoch, lightning_off_condition_since = NULL, updated_at = now()
   WHERE id = g.id;

  UPDATE public.tables tb
     -- 20261007222717: the engine acknowledgement goes with the halt, exactly
     -- as fn_cash_cluster_commit_must_move lifts it, so the next PENDING_ON
     -- waits for a fresh observation of its own halt instead of reading a
     -- stale one.
     SET dealing_halted_at = NULL, dealing_halted_reason = NULL, dealing_halt_observed_at = NULL
   WHERE tb.cluster_id = g.id AND tb.dealing_halted_reason IN ('lightning', 'lightning_pending_on');
  GET DIAGNOSTICS v_tables = ROW_COUNT;

  SELECT coalesce(sum(ts.stack), 0) INTO v_after
    FROM public.table_seats ts JOIN public.tables tb ON tb.id = ts.table_id
   WHERE tb.cluster_id = g.id AND ts.left_at IS NULL;
  IF v_after IS DISTINCT FROM v_before THEN
    RAISE EXCEPTION 'LIGHTNING_UNFREEZE_MOVED_MONEY: cluster % chip total went from % to %', g.id, v_before, v_after
      USING ERRCODE = 'check_violation';
  END IF;

  INSERT INTO public.cash_cluster_events (game_id, kind, payload, cluster_epoch)
  VALUES (g.id, 'cluster_unfrozen', jsonb_build_object(
    'cluster_id', g.id, 'cluster_epoch', v_epoch, 'epoch_before', g.cluster_epoch,
    'from_mode', 'frozen', 'to_mode', 'must_move', 'operator', p_operator, 'reason', v_reason,
    'instances_abandoned', v_instances, 'pool_sessions_exited', v_sessions, 'slots_closed', v_slots,
    'conversions_aborted', v_convs,
    'tables_released', v_tables, 'chip_total', v_before, 'at', clock_timestamp()), v_epoch);

  RETURN jsonb_build_object('ok', true, 'unfrozen', true, 'cluster_id', g.id, 'cluster_mode', 'must_move',
                            'epoch_before', g.cluster_epoch, 'epoch_after', v_epoch,
                            'instances_abandoned', v_instances, 'pool_sessions_exited', v_sessions,
                            'slots_closed', v_slots, 'tables_released', v_tables,
                            'conversions_aborted', v_convs, 'chip_total', v_before);
END
$$;


ALTER FUNCTION public.fn_cash_cluster_unfreeze(p_game_id uuid, p_operator uuid, p_reason text) OWNER TO postgres;

--
-- TOC entry 46477 (class 0 OID 0)
-- Dependencies: 9374
-- Name: FUNCTION fn_cash_cluster_unfreeze(p_game_id uuid, p_operator uuid, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_cluster_unfreeze(p_game_id uuid, p_operator uuid, p_reason text) IS 'Operator recovery from cluster_mode frozen (set by fn_lightning_form_hand on an impossible state). Requires an operator id and a non-empty reason; only from frozen. Abandons every live instance, exits every open pool session and closes its slot, returns the Cluster to must_move at a new epoch, lifts every member table''s Lightning halt, and records cluster_unfrozen. Moves no chips (asserted). service_role only.';


--
-- TOC entry 7694 (class 1255 OID 21408575)
-- Name: fn_cash_clusters_tick_all(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_clusters_tick_all(p_eligible jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  w record;
  v_now timestamptz := clock_timestamp();
  v_games integer := 0;
  v_ticked integer := 0;
  v_errors integer := 0;
  v_rested integer := 0;
  v_balanced integer := 0;
  v_bal integer;
  v_eligible integer;
  v_res jsonb;
  v_results jsonb := '[]'::jsonb;
  v_rested_games jsonb := '[]'::jsonb;
  v_sqlstate text;
  v_message text;
  -- A PASS COMMITS WHAT IT DID (2026-09-06). See the header of migration
  -- 20260906150956. The engine's role has an 8-second statement_timeout, and
  -- a pass that crosses it is rolled back WHOLE: every game it ticked is
  -- un-ticked and the 8 seconds are gone. Measured 2026-09-06: mean 1,187 ms,
  -- max 7,993 ms, 9 whole-pass timeouts in three hours, while a pass over all
  -- 108 games in isolation is ~3.3 s (avg 25 ms a game, worst 675 ms) - the
  -- overrun is waiting, not work. So: the pass stops STARTING games at
  -- v_budget and hands the rest to the next pass (they are ordered oldest-
  -- ticked first, so nothing starves), and a single lock wait is bounded by
  -- v_lock_wait so one held row costs one game its tick, not the pass.
  v_budget interval := interval '5500 milliseconds';
  v_lock_wait text := '2000ms';
  v_deferred integer := 0;
  v_reaped jsonb := '{}'::jsonb;
  v_lightning_reaped jsonb := '{}'::jsonb;
  v_disconnects_reaped jsonb := '{}'::jsonb;
  v_lightning_synced jsonb := '[]'::jsonb;
  v_lightning_driven jsonb := '[]'::jsonb;
  lc record;
  v_deferred_games jsonb := '[]'::jsonb;
BEGIN
  -- Transaction-local, so it dies with the RPC. lock_timeout is checked at
  -- every lock acquisition, so unlike statement_timeout it can be set from
  -- inside the statement it governs. A game whose tick waits longer than this
  -- raises 55P03 inside its own sub-block below and becomes an error row.
  PERFORM set_config('lock_timeout', v_lock_wait, true);
  -- THE PASS'S DEADLINE, published for the Lightning slot sync (2026-09-26).
  PERFORM set_config('ca.cluster_pass_deadline', (v_now + v_budget)::text, true);

  -- THE FREEZE (CLAUDE.md 13): the same short-circuit the per-game tick has,
  -- taken once for the pass so a frozen platform costs one row read.
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'skipped', 'frozen',
                              'games', 0, 'ticked', 0, 'errors', 0, 'rested', 0,
                              'balanced', 0,
                              'results', '[]'::jsonb, 'rested_games', '[]'::jsonb);
  END IF;

  -- THE REAP (2026-09-25). A cash_cluster_conversion that has sat pending too
  -- long is aborted here, because the per-Cluster tick stands down in
  -- pending_on and so cannot reap itself. After the freeze short-circuit above,
  -- so a break still costs one row read; before the loop, so a Cluster reaped
  -- now is ticked now. In its own sub-block, because lock_timeout is 2000ms and
  -- a lock wait must cost the reap rather than the pass.
  BEGIN
    v_reaped := public.fn_cash_cluster_reap_stuck_conversions();
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
    v_reaped := jsonb_build_object('ok', false, 'sqlstate', v_sqlstate, 'message', v_message);
  END;

  -- LIGHTNING'S RECOVERY AND ITS POOL DOOR (2026-09-26). Until now nothing in
  -- the estate called either: no formation path reaped, and no player entering
  -- a Lightning pool was ever given a slot. The reap hands back the players of
  -- any instance - forming, reserved, dealing or settling - that nothing has
  -- vouched for past its deadline; the sync opens a slot for every pool
  -- session that has none and closes every slot whose session or epoch has
  -- gone. Clusters that are lightning, and any other Cluster still holding an
  -- open slot, because a Cluster reverted to must_move keeps slots at a dead
  -- epoch until something closes them. Neither converts anything.
  BEGIN
    v_lightning_reaped := public.fn_lightning_reap_formations();
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
    v_lightning_reaped := jsonb_build_object('ok', false, 'sqlstate', v_sqlstate, 'message', v_message);
  END;

  -- LIGHTNING PHASE 9 (20261008050805): THE DISCONNECT EXPIRY, beside the
  -- formation reap for the same reason - the per-Cluster drive stands down
  -- for players the engine withholds, so nothing else in the estate would
  -- ever exit a pool session nobody is coming back to. In its own sub-block,
  -- because lock_timeout is 2000ms and a lock wait must cost this reap
  -- rather than the pass; inside, each session is isolated again.
  BEGIN
    v_disconnects_reaped := public.fn_lightning_reap_expired_disconnects();
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
    v_disconnects_reaped := jsonb_build_object('ok', false, 'sqlstate', v_sqlstate, 'message', v_message);
  END;

  -- LIGHTNING PHASE 7 (20261001222856): THE CONVERSIONS ARE DRIVEN HERE.
  -- Every Cluster that may convert (lightning_enabled and a must-move game)
  -- or is in a Lightning mode, after both reaps so a buried instance is not
  -- waited on, and before the slot sync so a Cluster converted now is given
  -- its slots now. One step per Cluster per pass; each in its own sub-block
  -- inside the drive, so one Cluster's lock wait or failure costs that
  -- Cluster, not the pass.
  -- Production has lightning_enabled false on every game: this loop finds
  -- nothing there until a game is switched on.
  FOR lc IN
    SELECT cg.id FROM public.cash_games cg
     WHERE (coalesce(cg.lightning_enabled, false) AND coalesce(cg.must_move, false))
        OR cg.cluster_mode IN ('pending_on', 'lightning', 'pending_off', 'draining')
        -- LIGHTNING PHASE 13 (20261009235505): an emergency drain is driven
        -- until it closes.
        OR EXISTS (SELECT 1 FROM public.lightning_cluster_drain d
                    WHERE d.cluster_id = cg.id AND d.completed_at IS NULL)
     ORDER BY cg.id
  LOOP
    IF clock_timestamp() - v_now > v_budget THEN
      v_lightning_driven := v_lightning_driven || jsonb_build_object(
        'cluster_id', lc.id, 'deferred', true);
      CONTINUE;
    END IF;
    -- The drive isolates itself: a lock wait or a failure inside it is rolled
    -- back to its own sub-block and answered {ok: false, error}, so this loop
    -- needs no handler of its own.
    v_lightning_driven := v_lightning_driven || public.fn_cash_cluster_lightning_drive(lc.id);
  END LOOP;

  FOR lc IN
    SELECT cg.id FROM public.cash_games cg
     WHERE cg.cluster_mode = 'lightning'
        OR EXISTS (SELECT 1 FROM public.lightning_pool_slot sl
                    WHERE sl.cluster_id = cg.id AND sl.closed_at IS NULL)
     ORDER BY cg.id
  LOOP
    IF clock_timestamp() - v_now > v_budget THEN
      v_lightning_synced := v_lightning_synced || jsonb_build_object(
        'cluster_id', lc.id, 'deferred', true);
      CONTINUE;
    END IF;
    BEGIN
      v_lightning_synced := v_lightning_synced || jsonb_build_object(
        'cluster_id', lc.id, 'result', public.fn_lightning_pool_slots_sync(lc.id));
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      v_lightning_synced := v_lightning_synced || jsonb_build_object(
        'cluster_id', lc.id, 'error', jsonb_build_object('sqlstate', v_sqlstate, 'message', v_message));
    END;
  END LOOP;

  FOR w IN
    SELECT l.game_id, l.club_id, l.main1_table_id, l.state, l.enabled,
           g.last_tick_at,
           coalesce((p_eligible ->> (l.main1_table_id::text))::integer, 0) AS eligible,
           EXISTS (
             SELECT 1
               FROM public.tables t
               JOIN public.table_seats ts ON ts.table_id = t.id AND ts.left_at IS NULL
              WHERE t.cluster_id = l.game_id
                AND t.lifecycle <> 'closed'
           ) AS anyone_seated
      FROM public.fn_cash_clusters_to_tick() l
      JOIN public.cash_games g ON g.id = l.game_id
     -- Oldest-ticked first (2026-09-06; it was created_at). With a budget
     -- that can defer the tail of the list, creation order would defer the
     -- SAME games every pass. A game deferred now is the oldest next pass.
     ORDER BY g.last_tick_at NULLS FIRST, g.created_at
  LOOP
    v_games := v_games + 1;


    -- DUE? Live, disabled, occupied or wanted: every pass. Otherwise every 30 s.
    IF NOT (
         w.state = 'live'
      OR NOT w.enabled
      OR w.anyone_seated
      OR w.eligible > 0
      OR w.last_tick_at IS NULL
      OR w.last_tick_at < v_now - interval '30 seconds'
    ) THEN
      v_rested := v_rested + 1;
      -- A RESTED GAME STILL ANSWERS "WHO ARE YOU" (2026-09-05). The controller
      -- builds its per-game row map from what this pass returns, and a wake on
      -- a game absent from that map cannot read `enabled` or find Main 1 - so
      -- the 18.4 dealer wake was skipped for precisely the dormant game a wake
      -- is for. Identity only; no result, because it was not ticked.
      v_rested_games := v_rested_games || jsonb_build_object(
        'game_id', w.game_id,
        'main1_table_id', w.main1_table_id,
        'enabled', w.enabled,
        'state', w.state
      );
      CONTINUE;
    END IF;

    -- THE BUDGET. Checked after the rest test and before a game STARTS, so
    -- a resting game is still counted as rested and `deferred` means DUE but
    -- not started; a game already ticking finishes. Deferred games answer
    -- "who are you" exactly as rested games do, so the controller's row map
    -- still knows them and a wake finds Main 1. Their last_tick_at is
    -- untouched, which is what puts them first next pass.
    IF clock_timestamp() - v_now > v_budget THEN
      v_deferred := v_deferred + 1;
      v_deferred_games := v_deferred_games || jsonb_build_object(
        'game_id', w.game_id,
        'main1_table_id', w.main1_table_id,
        'enabled', w.enabled,
        'state', w.state
      );
      CONTINUE;
    END IF;

    v_eligible := w.eligible;
    BEGIN
      v_res := public.fn_cash_cluster_tick(w.game_id, v_eligible);
      v_ticked := v_ticked + 1;
      -- THE TABLES STAY WITHIN ONE PLAYER (Dan 2026-09-05). After the tick,
      -- never before it: the must-move step has just filled the main game's
      -- open seats from the list, and balancing against the board as it was
      -- BEFORE that would move players the tick was about to move anyway.
      v_bal := public.fn_cash_cluster_balance(w.game_id, v_now);
      v_balanced := v_balanced + coalesce(v_bal, 0);
      v_results := v_results || jsonb_build_object(
        'game_id', w.game_id,
        'main1_table_id', w.main1_table_id,
        'enabled', w.enabled,
        'state', w.state,
        'balanced', coalesce(v_bal, 0),
        'result', coalesce(v_res, '{}'::jsonb)
      );
    EXCEPTION WHEN OTHERS THEN
      -- The sub-block rolled this game's tick back; the pass goes on. The
      -- error is a row, not a log line, so the next agent can find it.
      GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      v_errors := v_errors + 1;
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload)
      VALUES (w.game_id, w.main1_table_id, 'controller_tick_error',
              jsonb_build_object('sqlstate', v_sqlstate, 'message', v_message,
                                 'eligible_horses', v_eligible));
      v_results := v_results || jsonb_build_object(
        'game_id', w.game_id,
        'main1_table_id', w.main1_table_id,
        'enabled', w.enabled,
        'state', w.state,
        'error', jsonb_build_object('sqlstate', v_sqlstate, 'message', v_message)
      );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'games', v_games,
    'reaped', v_reaped,
    'lightning_reaped', v_lightning_reaped,
    'disconnects_reaped', v_disconnects_reaped,
    'lightning_synced', v_lightning_synced,
    'lightning_driven', v_lightning_driven,
    'ticked', v_ticked,
    'errors', v_errors,
    'rested', v_rested,
    'deferred', v_deferred,
    'balanced', v_balanced,
    'elapsed_ms', round(extract(epoch from (clock_timestamp() - v_now)) * 1000),
    'results', v_results,
    -- Deferred games ride with the rested ones: identity rows, so the
    -- controller's map is complete without a new shape to parse.
    'rested_games', v_rested_games || v_deferred_games
  );
END;
$$;


ALTER FUNCTION public.fn_cash_clusters_tick_all(p_eligible jsonb) OWNER TO postgres;

--
-- TOC entry 46479 (class 0 OID 0)
-- Dependencies: 7694
-- Name: FUNCTION fn_cash_clusters_tick_all(p_eligible jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_clusters_tick_all(p_eligible jsonb) IS 'One cluster-controller pass in one call (OPORD 1.4 s18.2). p_eligible is {main1_table_id: eligible_horses}. Live, disabled, occupied or horse-wanted games tick every pass; a dormant empty game every 30 s. Per-game errors are caught and written to cash_cluster_events as controller_tick_error.';


--
-- TOC entry 9285 (class 1255 OID 20962011)
-- Name: fn_cash_clusters_to_tick(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_clusters_to_tick() RETURNS TABLE(game_id uuid, club_id uuid, main1_table_id uuid, state text, enabled boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT g.id, g.club_id,
         -- LIGHTNING 2.0 PHASE 3. This was a subselect for role = 'main' AND
         -- main_index = 1, which answers NULL for a Lightning-capable Cluster
         -- whose one table is a feeder. The ClusterController reads this column
         -- to count eligible horses and to decide whether an engine must exist,
         -- so a NULL here means the Cluster is created and then never ticks.
         -- The column keeps its name because eleven call sites in
         -- server/src/cluster/ClusterController.ts spell it.
         public.fn_cash_cluster_front_table(g.id),
         g.state, g.enabled
    FROM public.cash_games g
   WHERE g.must_move
     -- A DISABLED GAME IS ADMITTED ON EITHER LIVENESS FIELD (2026-09-09).
     -- This used to require status IN ('waiting','running','active') as well,
     -- and 20260906011113 removed the status half because a table stranded at
     -- lifecycle='live' / status='closed' was excluded from the repair written
     -- for it. The MIRROR of that stranding - lifecycle='closed' with
     -- status='waiting' - then fell into the same hole against the half that
     -- was left, and `status_followed_lifecycle` (which lives inside the tick)
     -- could never reach it. Two FLO8 0.50/1 games sat that way with
     -- last_tick_at NULL: never ticked once.
     -- So the question is asked of BOTH fields: any table that is non-terminal
     -- by either one is a table the tick has something to say about. One tick
     -- makes them agree and the game leaves this list again.
     AND (g.enabled OR EXISTS (SELECT 1 FROM public.tables t
                                WHERE t.cluster_id = g.id
                                  AND coalesce(t.is_deleted, false) = false
                                  AND (t.lifecycle <> 'closed'
                                       OR lower(coalesce(t.status, '')) NOT IN
                                            ('closed', 'completed', 'cancelled', 'finished'))))
   ORDER BY g.created_at;
$$;


ALTER FUNCTION public.fn_cash_clusters_to_tick() OWNER TO postgres;

--
-- TOC entry 7641 (class 1255 OID 34785114)
-- Name: fn_cash_earning_club(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_earning_club(p_hand_id uuid, p_table_id uuid, p_player_id uuid, p_source_club uuid, p_union_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE started timestamptz;clubs uuid[];
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_hand_id IS NULL OR p_table_id IS NULL OR p_player_id IS NULL OR p_source_club IS NULL THEN
  RAISE EXCEPTION 'cash_earning_identity_missing' USING ERRCODE='23514'; END IF;
 SELECT h.started_at INTO started FROM public.hand_history h WHERE h.id=p_hand_id AND h.table_id=p_table_id;
 -- Original off-chair custody exists only in the accepted native hand's
 -- transaction. Never derive ownership from today's replacement chair.
 IF started IS NOT NULL AND isfinite(started) AND started<=transaction_timestamp() THEN
  SELECT array_agg(DISTINCT r.funding_club_id) INTO clubs
  FROM smarter_private.retired_cash_hand_custody r
  JOIN smarter_private.retired_cash_hand_qualification q USING(submission_id)
  JOIN smarter_private.hand_submissions s USING(submission_id)
  JOIN smarter_private.hand_submission_handoffs h USING(submission_id)
  JOIN public.hand_atomic_commits a ON a.hand_id=r.submission_id
   AND a.table_id=r.table_id AND a.hand_number=r.hand_number
  WHERE r.submission_id=p_hand_id AND r.table_id=p_table_id AND r.user_id=p_player_id
   AND r.state='consumed' AND r.transaction_id=txid_current()
   AND h.transaction_id=r.transaction_id AND h.request_hash=r.request_hash
   AND s.request_hash=r.request_hash AND q.request_hash=r.request_hash
   AND r.accepted_time_bank=r.original_time_bank AND r.settlement_id IS NOT NULL
   AND (q.table_id,q.hand_number)=(r.table_id,r.hand_number)
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(q.expected->'participants') e
    WHERE (e#>>'{stack,user_id}')::uuid=r.user_id
     AND (e#>>'{stack,seat_id}')::uuid=r.seat_id
     AND (e#>>'{stack,occupancy_id}')::uuid=r.occupancy_id
     AND (e#>>'{stack,seat_joined_at}')::timestamptz=r.seat_joined_at
     AND (e#>>'{stack,stack_before}')::numeric=r.stack_before
     AND (e#>>'{stack,stack}')::numeric=r.stack_after
     AND (e->>'funding_club_id')::uuid=r.funding_club_id);
  IF cardinality(clubs)=1 AND clubs[1] IS NOT NULL
   AND EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=clubs[1]
    AND (c.is_union IS NOT TRUE OR (p_union_id IS NOT NULL AND (c.id=p_union_id OR c.union_id=p_union_id))))
  THEN RETURN clubs[1]; END IF;
 END IF;
 -- Funding must exist by the persisted actual hand start. The logical formed_at
 -- supplied by the engine can precede the transaction that opens its slot.
 -- A pooled Lightning hand is funded by its original pool/cash session,
 -- not a physical chair at the synthetic host table. Anchor seats can be
 -- elsewhere or already gone by settlement; their session is retained.
 IF EXISTS(SELECT 1 FROM public.lightning_hand h
   WHERE h.hand_history_id=p_hand_id AND h.host_table_id=p_table_id) THEN
  IF started IS NULL OR NOT isfinite(started) OR started>transaction_timestamp() THEN
   RAISE EXCEPTION 'cash_hand_start_not_recorded' USING ERRCODE='23514'; END IF;
  SELECT array_agg(DISTINCT cs.club_id) INTO clubs
   FROM public.lightning_hand h
   JOIN public.lightning_hand_player hp ON hp.hand_id=h.hand_id
    AND hp.player_id=p_player_id AND hp.cluster_id=h.cluster_id AND hp.cluster_epoch=h.cluster_epoch
   JOIN public.lightning_pool_slot sl ON sl.id=hp.pool_slot_id AND sl.player_id=hp.player_id
    AND sl.cluster_id=h.cluster_id AND sl.cluster_epoch=h.cluster_epoch
   JOIN public.lightning_pool_session ps ON ps.id=sl.pool_session_id AND ps.player_id=hp.player_id
    AND ps.cluster_id=h.cluster_id AND ps.cluster_epoch=h.cluster_epoch
   JOIN public.cash_player_session cs ON cs.id=ps.cash_player_session_id AND cs.player_id=hp.player_id
   WHERE h.hand_history_id=p_hand_id AND h.host_table_id=p_table_id
    AND h.formed_at<=started AND ps.entered_at<=started AND sl.opened_at<=started
    AND cs.opened_at<=started
    AND (ps.exited_at IS NULL OR ps.exited_at>started)
    AND (sl.closed_at IS NULL OR sl.closed_at>started)
    AND (cs.closed_at IS NULL OR cs.closed_at>started);
  IF cardinality(clubs)=1 AND clubs[1] IS NOT NULL
   AND EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=clubs[1]
    AND (c.is_union IS NOT TRUE OR (p_union_id IS NOT NULL AND (c.id=p_union_id OR c.union_id=p_union_id))))
  THEN RETURN clubs[1]; END IF;
  IF p_union_id IS NOT NULL THEN
   RAISE EXCEPTION 'cash_earning_seat_provenance_missing_or_ambiguous' USING ERRCODE='23514'; END IF;
  RETURN NULL;
 END IF;
 IF p_union_id IS NULL THEN
  -- Private games may admit a seat funded by another club. Preserve the
  -- actual club at the hand's start; the host only identifies the bank route.
  -- This reader runs before banking an already accepted hand. Unknown seat
  -- evidence must therefore stay NULL, not abort its bank obligation or invent
  -- host ownership. The existing source worker durably refuses that NULL or
  -- an unsupported cross-club liability after the exact bank receipt exists.
  IF started IS NULL OR NOT isfinite(started) OR started>transaction_timestamp() THEN RETURN NULL; END IF;
  SELECT array_agg(DISTINCT s.club_id) INTO clubs FROM public.table_seats s
   WHERE s.table_id=p_table_id AND s.user_id=p_player_id
    AND s.joined_at<=started AND (s.left_at IS NULL OR s.left_at>started);
  -- An overlapping unknown-club seat also makes the evidence ambiguous.
  IF cardinality(clubs) IS DISTINCT FROM 1 OR clubs[1] IS NULL
   OR NOT EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=clubs[1] AND c.is_union IS NOT TRUE)
  THEN RETURN NULL; END IF;
  RETURN clubs[1];
 END IF;
 -- Preserve the existing shared-union validation and failure contract.
 IF started IS NULL OR started>transaction_timestamp() THEN RAISE EXCEPTION 'cash_hand_start_not_recorded' USING ERRCODE='23514'; END IF;
 SELECT array_agg(DISTINCT s.club_id) INTO clubs FROM public.table_seats s
  WHERE s.table_id=p_table_id AND s.user_id=p_player_id AND s.club_id IS NOT NULL
   AND s.joined_at<=started AND (s.left_at IS NULL OR s.left_at>started);
 IF cardinality(clubs) IS DISTINCT FROM 1
  OR NOT EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=clubs[1]
   AND (c.is_union IS NOT TRUE OR c.id=p_union_id OR c.union_id=p_union_id))
 THEN RAISE EXCEPTION 'cash_earning_seat_provenance_missing_or_ambiguous' USING ERRCODE='23514'; END IF;
 RETURN clubs[1];
END $$;


ALTER FUNCTION public.fn_cash_earning_club(p_hand_id uuid, p_table_id uuid, p_player_id uuid, p_source_club uuid, p_union_id uuid) OWNER TO postgres;

--
-- TOC entry 3505 (class 1255 OID 20621966)
-- Name: fn_cash_effective_buyin(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_effective_buyin(p_table_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_min numeric; v_max numeric; v_bb numeric; v_floor numeric; v_eff numeric;
  v_barred_secs integer;
BEGIN
  SELECT t.min_buy_in, t.max_buy_in, t.big_blind INTO v_min, v_max, v_bb
    FROM public.tables t WHERE t.id = p_table_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;
  IF COALESCE(v_min, 0) <= 0 THEN v_min := COALESCE(v_bb, 0) * 40; END IF;
  IF COALESCE(v_max, 0) <= 0 THEN v_max := COALESCE(v_bb, 0) * 200; END IF;
  v_eff := v_min;
  IF v_uid IS NOT NULL THEN
    BEGIN
      v_floor := public.fn_cash_rejoin_floor(v_uid, p_table_id);
    EXCEPTION WHEN check_violation THEN
      IF SQLERRM LIKE 'VPIP_BARRED:%' THEN
        v_barred_secs := nullif(regexp_replace(SQLERRM, '^VPIP_BARRED:', ''), '')::integer;
      ELSE
        RAISE;
      END IF;
    END;
    IF v_floor IS NOT NULL THEN
      v_eff := GREATEST(v_min, v_floor);
      IF v_max > 0 THEN v_eff := LEAST(v_eff, v_max); END IF;
    END IF;
  END IF;
  RETURN jsonb_build_object('ok', true, 'min', v_eff, 'max', v_max,
                            'table_min', v_min, 'floor_applied', v_floor IS NOT NULL AND v_eff > v_min,
                            'barred_seconds', v_barred_secs);
END;
$$;


ALTER FUNCTION public.fn_cash_effective_buyin(p_table_id uuid) OWNER TO postgres;

--
-- TOC entry 7176 (class 1255 OID 21209327)
-- Name: fn_cash_game_barred_seconds(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_game_barred_seconds(p_game_id uuid, p_user_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT ceil(extract(epoch FROM (max(c.barred_until) - now())))::integer
    FROM public.cash_games g
    JOIN public.cash_rejoin_constraints c
      ON c.player_id = p_user_id AND c.club_id = g.club_id AND c.variant = g.variant
     AND c.sb = g.sb AND c.bb = g.bb AND c.barred_until > now()
   WHERE g.id = p_game_id
  HAVING max(c.barred_until) IS NOT NULL;
$$;


ALTER FUNCTION public.fn_cash_game_barred_seconds(p_game_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 7815 (class 1255 OID 207657704)
-- Name: fn_cash_game_category_key(uuid, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_game_category_key(p_club uuid, p_variant text, p_sb numeric, p_bb numeric) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN p_club = 'fade0000-0000-0000-0000-000000000001'::uuid
    AND p_variant IN ('nlh','plo4','plo5','plo6','plo8')
    AND p_sb = 0.50 AND p_bb = 1.00 THEN 'half_one'
    ELSE public.fn_cash_stake_band(p_bb) END;
$$;


