--
-- TOC entry 6834 (class 1255 OID 57591102)
-- Name: fn_cash_table_observe_dealing_halt(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_table_observe_dealing_halt(p_table_id uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_halted   timestamptz;
  v_observed timestamptz;
BEGIN
  SELECT t.dealing_halted_at, t.dealing_halt_observed_at
    INTO v_halted, v_observed
    FROM public.tables t WHERE t.id = p_table_id;
  IF NOT FOUND OR v_halted IS NULL THEN
    RETURN NULL;
  END IF;
  IF v_observed IS NOT NULL AND v_observed >= v_halted THEN
    RETURN v_observed;
  END IF;
  -- The halt is re-read by the UPDATE itself: a halt lifted between the read
  -- above and this write stamps nothing and answers NULL.
  UPDATE public.tables t
     SET dealing_halt_observed_at = clock_timestamp()
   WHERE t.id = p_table_id AND t.dealing_halted_at IS NOT NULL
  RETURNING t.dealing_halt_observed_at INTO v_observed;
  RETURN v_observed;
END
$$;


ALTER FUNCTION public.fn_cash_table_observe_dealing_halt(p_table_id uuid) OWNER TO postgres;

--
-- TOC entry 46544 (class 0 OID 0)
-- Dependencies: 6834
-- Name: FUNCTION fn_cash_table_observe_dealing_halt(p_table_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cash_table_observe_dealing_halt(p_table_id uuid) IS 'Called by the engine when its table is parked at the halt gate between hands. Stamps tables.dealing_halt_observed_at with clock_timestamp() if and only if the table is halted and this halt has not already been observed, and returns the stamp that stands (NULL when not halted). fn_cash_cluster_commit_lightning refuses (halt_not_observed) until every member table holding a live engine lease has dealing_halt_observed_at >= dealing_halted_at.';


--
-- TOC entry 3476 (class 1255 OID 20887837)
-- Name: fn_cash_template_defaults(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_template_defaults(p_template text, p_variant text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t text := lower(coalesce(p_template, 'classic'));
  v_v text := lower(coalesce(p_variant, 'nlh'));
  v_family text;
  v_seats integer; v_seats_locked boolean; v_seat_choices integer[];
  v_vpip integer; v_vpip_window integer;
BEGIN
  IF v_t NOT IN ('classic', 'action', 'madness') THEN
    RAISE EXCEPTION 'TEMPLATE_UNKNOWN: %', p_template;
  END IF;

  v_family := CASE
    WHEN v_v IN ('plo4','plo5','plo6','plo8','flo8') THEN 'plo'
    WHEN v_v = 'short_deck' THEN 'shortdeck'
    WHEN v_v = 'pineapple' THEN 'pineapple'
    ELSE 'holdem' END;

  IF v_family = 'plo' THEN
    v_seats := 6; v_seats_locked := true; v_seat_choices := ARRAY[6];
  ELSIF v_family = 'holdem' THEN
    IF v_t = 'classic' THEN v_seats := 9; v_seat_choices := ARRAY[9, 6];
    ELSE v_seats := 6; v_seat_choices := ARRAY[2,3,4,5,6,7,8,9]; END IF;
    v_seats_locked := false;
  ELSE
    v_seats := 6; v_seats_locked := false; v_seat_choices := ARRAY[2,3,4,5,6,7,8];
  END IF;

  -- VPIP floor per template (percent), FLAT ACROSS FAMILIES (Dan 2026-09-05).
  v_vpip := CASE v_t
    WHEN 'classic' THEN 0
    WHEN 'action'  THEN 30
    ELSE                50 END;
  v_vpip_window := 10;

  RETURN jsonb_build_object(
    'template', v_t,
    'variant', v_v,
    'family', v_family,
    'seats', v_seats,
    'seats_locked', v_seats_locked,
    'seat_choices', to_jsonb(v_seat_choices),
    'min_buyin_bb', CASE v_t WHEN 'classic' THEN 40 WHEN 'action' THEN 50 ELSE 100 END,
    'max_buyin_bb', 200,
    'regular_ante', CASE v_t WHEN 'classic' THEN 'none' WHEN 'action' THEN 'sb' ELSE 'bb' END,
    'vpip_floor', v_vpip,
    'vpip_window', v_vpip_window,
    'bombs', jsonb_build_object(
      'enabled', v_t <> 'classic',
      'trigger', CASE v_t WHEN 'action' THEN 'timed_20m' WHEN 'madness' THEN 'timed_10m' ELSE NULL END,
      'ante_bb', CASE v_t WHEN 'action' THEN 2 WHEN 'madness' THEN 3 ELSE NULL END,
      'boards', CASE WHEN v_t = 'classic' THEN NULL ELSE 2 END),
    'straddle', false,
    'stay_clock_min', 10,
    'rejoin_window_min', 120,
    'run_it_n_times', 'opt_in',
    'rake', 'existing'
  );
END;
$$;


ALTER FUNCTION public.fn_cash_template_defaults(p_template text, p_variant text) OWNER TO postgres;

--
-- TOC entry 7248 (class 1255 OID 21055681)
-- Name: fn_cash_vpip_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cash_vpip_status(p_table_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_on     boolean;
  v_min    integer;
  v_n      integer;
  v_game   uuid;
  v_joined timestamptz;
  v_since  timestamptz;
  v_hands  integer;
  v_vpip   numeric;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_signed_in');
  END IF;

  SELECT COALESCE(t.nit_game, false),
         GREATEST(COALESCE(t.maintain_percent_min, 0), 0),
         GREATEST(COALESCE(t.maintain_hands, 10), 1),
         t.cluster_id
    INTO v_on, v_min, v_n, v_game
    FROM public.tables t WHERE t.id = p_table_id LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;

  SELECT ts.joined_at INTO v_joined
    FROM public.table_seats ts
   WHERE ts.table_id = p_table_id AND ts.user_id = v_uid AND ts.left_at IS NULL
   ORDER BY ts.joined_at DESC NULLS LAST
   LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', true, 'seated', false,
      'nit_game', v_on, 'required', CASE WHEN v_on THEN v_min ELSE 0 END, 'window', v_n);
  END IF;

  -- The number the rule judges (fn_nit_check): the sitting in the GAME on a
  -- cluster table, the chair elsewhere (2026-09-09).
  v_since := v_joined;
  IF v_game IS NOT NULL THEN
    SELECT r.joined_at INTO v_since
      FROM public.cash_game_roster r
     WHERE r.game_id = v_game AND r.user_id = v_uid AND r.left_at IS NULL
     ORDER BY r.joined_at DESC
     LIMIT 1;
    IF NOT FOUND THEN v_since := v_joined; END IF;

    SELECT count(*)::int,
           CASE WHEN count(*) = 0 THEN NULL
                ELSE round(100.0 * avg(CASE WHEN f.vpip THEN 1 ELSE 0 END), 1) END
      INTO v_hands, v_vpip
      FROM public.ca_hand_facts f
     WHERE f.user_id = v_uid
       AND (v_since IS NULL OR f.played_at >= v_since)
       AND f.table_id IN (SELECT t2.id FROM public.tables t2 WHERE t2.cluster_id = v_game);
  ELSE
    SELECT count(*)::int,
           CASE WHEN count(*) = 0 THEN NULL
                ELSE round(100.0 * avg(CASE WHEN f.vpip THEN 1 ELSE 0 END), 1) END
      INTO v_hands, v_vpip
      FROM public.ca_hand_facts f
     WHERE f.table_id = p_table_id
       AND f.user_id = v_uid
       AND (v_since IS NULL OR f.played_at >= v_since);
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'seated', true,
    'nit_game', v_on,
    'required', CASE WHEN v_on THEN v_min ELSE 0 END,
    'window', v_n,
    'hands', v_hands,
    'vpip', v_vpip,
    'since', v_since);
END;
$$;


ALTER FUNCTION public.fn_cash_vpip_status(p_table_id uuid) OWNER TO postgres;

--
-- TOC entry 5037 (class 1255 OID 101732521)
-- Name: fn_cashier_agent_status_mutex(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_agent_status_mutex() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE'
     OR NEW.club_id IS DISTINCT FROM OLD.club_id
     OR NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'cashier-agent-authority:' || OLD.club_id || ':' || OLD.user_id, 0));
  END IF;
  IF TG_OP <> 'DELETE' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'cashier-agent-authority:' || NEW.club_id || ':' || NEW.user_id, 0));
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;


ALTER FUNCTION public.fn_cashier_agent_status_mutex() OWNER TO postgres;

--
-- TOC entry 5710 (class 1255 OID 101732520)
-- Name: fn_cashier_assert_active_actor(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_assert_active_actor(p_club uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_role text;
  v_status text;
BEGIN
  IF auth.role() = 'service_role' THEN RETURN; END IF;
  IF v_actor IS NULL OR p_club IS NULL THEN RETURN; END IF;
  IF EXISTS (SELECT 1 FROM public.clubs WHERE id = p_club AND owner_id = v_actor) THEN
    RETURN;
  END IF;

  SELECT role INTO v_role
    FROM public.club_members
   WHERE club_id = p_club
     AND user_id = v_actor
     AND coalesce(status, 'active') IN ('active', 'approved')
   LIMIT 1;

  IF v_role IN ('super_agent', 'agent', 'sub_agent') THEN
    -- Serialize against status changes without taking a row lock ahead of the
    -- retained money core's established wallet/club lock order. The matching
    -- agents trigger below takes this same mutex before status/update/delete.
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'cashier-agent-authority:' || p_club || ':' || v_actor, 0));
    SELECT a.status INTO v_status
      FROM public.agents a
     WHERE a.club_id = p_club AND a.user_id = v_actor;
    IF v_status IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION 'cashier_agent_inactive' USING ERRCODE = '42501';
    END IF;
  END IF;
END
$$;


ALTER FUNCTION public.fn_cashier_assert_active_actor(p_club uuid) OWNER TO postgres;

--
-- TOC entry 8783 (class 1255 OID 34785991)
-- Name: fn_cashier_assert_delivery(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_assert_delivery(p_event_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE e public.accounting_cashier_events%ROWTYPE;i public.settlement_invoices%ROWTYPE;
 d record;payload jsonb;actual_users uuid[];expected_body text;
BEGIN
 SELECT * INTO STRICT e FROM public.accounting_cashier_events WHERE id=p_event_id;
 payload:=public.fn_cashier_invoice_contract(e.invoice_id);
 SELECT * INTO STRICT i FROM public.settlement_invoices WHERE id=e.invoice_id;
 expected_body:=public.fn_cashier_document_body(e.id,i.invoice_number);
 SELECT array_agg(recipient_id ORDER BY recipient_id) INTO actual_users FROM public.accounting_invoice_deliveries WHERE invoice_id=e.invoice_id;
 IF actual_users IS DISTINCT FROM e.audience_user_ids OR i.invoice_number IS NULL
  OR i.message_sent IS DISTINCT FROM true OR i.message_sent_at IS NULL
 THEN RAISE EXCEPTION 'cashier_document_delivery_missing' USING ERRCODE='23514';END IF;
 FOR d IN SELECT a.*,m.conversation_id,m.sender_id,m.content,m.message_type,m.media_metadata,
   n.user_id AS notice_user,n.type AS notice_type,n.data AS notice_data,n.metadata AS notice_metadata,
   n.title AS notice_title,n.message AS notice_message,n.action_url AS notice_url
  FROM public.accounting_invoice_deliveries a LEFT JOIN public.social_messages m ON m.id=a.message_id
  LEFT JOIN public.notifications n ON n.id=a.notification_id WHERE a.invoice_id=e.invoice_id LOOP
  IF d.delivery_mode IS DISTINCT FROM 'immediate' OR d.sender_id IS DISTINCT FROM e.issuer_representative_id
   OR d.message_type IS DISTINCT FROM 'invoice' OR d.content IS DISTINCT FROM expected_body
   OR d.media_metadata->>'invoice_id' IS DISTINCT FROM e.invoice_id::text
   OR d.media_metadata->'cashier' IS DISTINCT FROM payload
   OR d.notice_user IS DISTINCT FROM d.recipient_id OR d.notice_type IS DISTINCT FROM 'accounting_invoice'
   OR d.notice_data->>'invoice_id' IS DISTINCT FROM e.invoice_id::text OR d.notice_data->'cashier' IS DISTINCT FROM payload
   OR d.notice_metadata IS DISTINCT FROM d.media_metadata OR d.notice_data IS DISTINCT FROM d.media_metadata
   OR d.media_metadata->>'invoice_type' IS DISTINCT FROM 'cashier_cashout' OR d.media_metadata->'amount' IS DISTINCT FROM to_jsonb(i.net_amount)
   OR d.notice_title IS DISTINCT FROM (CASE e.event_kind WHEN 'hold' THEN 'Chips Held · ' WHEN 'approval' THEN 'Cashout Approved · ' ELSE 'Chips Returned · ' END||i.invoice_number)
   OR d.notice_message IS DISTINCT FROM (CASE e.event_kind WHEN 'hold' THEN 'Chips Held: ' WHEN 'approval' THEN 'Cashout Approved: ' ELSE 'Chips Returned: ' END||to_char(abs(i.net_amount),'FM999,999,999,999,990.00')||' Chips')
   OR d.notice_url IS DISTINCT FROM '/hub/messenger?conversation='||d.conversation_id::text
   OR NOT EXISTS(SELECT 1 FROM public.accounting_conversations c WHERE c.conversation_id=d.conversation_id
      AND c.scope_id=e.club_id AND c.issuer_type='club' AND c.issuer_id=e.club_id
      AND c.sender_id=e.issuer_representative_id AND c.recipient_id=d.recipient_id)
   OR EXISTS(SELECT 1 FROM public.social_conversation_participants p WHERE p.conversation_id=d.conversation_id
      AND p.user_id<>ALL(ARRAY[e.issuer_representative_id,d.recipient_id]))
   OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants p WHERE p.conversation_id=d.conversation_id AND p.user_id=d.recipient_id)
   OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants p WHERE p.conversation_id=d.conversation_id AND p.user_id=e.issuer_representative_id)
  THEN RAISE EXCEPTION 'cashier_document_delivery_mismatch' USING ERRCODE='23514';END IF;
 END LOOP;
 RETURN payload;
END $$;


ALTER FUNCTION public.fn_cashier_assert_delivery(p_event_id uuid) OWNER TO postgres;

--
-- TOC entry 6945 (class 1255 OID 101732525)
