--
-- TOC entry 8833 (class 1255 OID 18012215)
-- Name: fn_cashier_batch_transfer(uuid, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_batch_transfer(p_club_id uuid, p_kind text, p_items jsonb, p_batch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_me uuid := auth.uid();
  v_item jsonb;
  v_result jsonb;
  v_results jsonb := '[]'::jsonb;
  v_user_id uuid;
  v_amount numeric;
  v_destination text;
  v_reason text;
  v_op_id uuid;
  v_ticket_key text;
  v_tournament_id uuid;
  v_seen uuid[] := '{}'::uuid[];
begin
  if v_me is null then
    return jsonb_build_object('success',false,'error','Not Authenticated');
  end if;
  if p_club_id is null or p_batch_id is null then
    return jsonb_build_object('success',false,'error','Club And Batch Retry Key Are Required');
  end if;
  if p_kind not in ('send','ticket') then
    return jsonb_build_object('success',false,'error','Choose Send Or Ticket');
  end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) < 1
     or jsonb_array_length(p_items) > 25 then
    return jsonb_build_object('success',false,'error','A Batch Must Contain Between 1 And 25 Recipients');
  end if;

  -- The selected source is validated before any item can move money.
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_items) item WHERE item ? 'source' AND coalesce(item->>'source','') NOT IN ('agent_wallet','club_bank','promo_wallet','club_promo_wallet','player_wallet')) THEN
    RETURN jsonb_build_object('success',false,'error','Unknown Source Wallet');
  END IF;
  -- Validate the complete envelope before the first item can move money.
  for v_item in select value from jsonb_array_elements(p_items)
  loop
    if jsonb_typeof(v_item) <> 'object'
       or coalesce(v_item->>'user_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      return jsonb_build_object('success',false,'error','Every Batch Item Needs A Valid Recipient And Amount');
    end if;
    -- 20261015132042: a tournament ticket is priced by its tournament, so its
    -- amount is optional; when sent it is the price the cashier saw.
    if p_kind='ticket' and v_item ? 'tournament_id'
       and jsonb_typeof(v_item->'tournament_id') <> 'null' then
      if coalesce(v_item->>'tournament_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        return jsonb_build_object('success',false,'error','Every Tournament Ticket Needs A Valid Tournament');
      end if;
      if v_item ? 'amount' and jsonb_typeof(v_item->'amount') <> 'null'
         and coalesce(v_item->>'amount','') !~ '^[0-9]+([.][0-9]+)?$' then
        return jsonb_build_object('success',false,'error','Every Batch Item Needs A Valid Recipient And Amount');
      end if;
    elsif coalesce(v_item->>'amount','') !~ '^[0-9]+([.][0-9]+)?$' then
      return jsonb_build_object('success',false,'error','Every Batch Item Needs A Valid Recipient And Amount');
    end if;
    v_user_id := (v_item->>'user_id')::uuid;
    v_amount := nullif(v_item->>'amount','')::numeric;
    if v_user_id = any(v_seen) then
      return jsonb_build_object('success',false,'error','A Recipient May Appear Only Once Per Batch');
    end if;
    v_seen := array_append(v_seen, v_user_id);
    if v_amount is not null
       and (v_amount <= 0 or v_amount > 1e9 or v_amount <> round(v_amount,2)) then
      return jsonb_build_object('success',false,'error','Every Amount Must Be Positive And Use Hundredths At Most');
    end if;
    if p_kind='send' and coalesce(v_item->>'op_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      return jsonb_build_object('success',false,'error','Every Send Needs Its Own Retry Key');
    end if;
    if p_kind='ticket' and nullif(btrim(coalesce(v_item->>'idempotency_key','')),'') is null then
      return jsonb_build_object('success',false,'error','Every Ticket Needs Its Own Retry Key');
    end if;
  end loop;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_user_id := (v_item->>'user_id')::uuid;
    v_amount := nullif(v_item->>'amount','')::numeric;
    v_tournament_id := case when p_kind='ticket' and jsonb_typeof(v_item->'tournament_id')='string'
                            then (v_item->>'tournament_id')::uuid end;
    begin
      if p_kind='send' then
        v_destination := coalesce(nullif(v_item->>'destination',''),'player_wallet');
        v_reason := nullif(v_item->>'reason','');
        v_op_id := (v_item->>'op_id')::uuid;
        CASE coalesce(v_item->>'source','agent_wallet')
          WHEN 'player_wallet' THEN v_result := public.fn_cashier_player_wallet_send(p_club_id,v_user_id,v_amount,v_destination,v_reason,v_op_id);
          WHEN 'club_bank' THEN v_result := public.fn_club_bank_send(p_club_id,v_user_id,v_amount,v_destination,v_reason,v_op_id);
          WHEN 'promo_wallet' THEN v_result := public.fn_promo_wallet_send(p_club_id,v_user_id,v_amount,case when v_destination='agent_wallet' then 'cashier_agent_wallet' when v_destination='promo_wallet' then 'cashier_promo_wallet' else v_destination end,v_reason,v_op_id);
          WHEN 'club_promo_wallet' THEN v_result := public.fn_club_promo_wallet_send(p_club_id,v_user_id,v_amount,case when v_destination='agent_wallet' then 'cashier_agent_wallet' when v_destination='promo_wallet' then 'cashier_promo_wallet' else v_destination end,v_reason,v_op_id);
          ELSE v_result := public.fn_agent_wallet_send(p_club_id,v_user_id,v_amount,v_destination,v_reason,v_op_id);
        END CASE;
      elsif v_tournament_id is not null then
        v_ticket_key := v_item->>'idempotency_key';
        v_result := public.fn_issue_tournament_entry_ticket(
          p_club_id,v_user_id,v_tournament_id,nullif(v_item->>'note',''),
          v_ticket_key,v_amount
        );
      else
        v_ticket_key := v_item->>'idempotency_key';
        v_result := public.fn_issue_tournament_ticket(
          p_club_id,v_user_id,v_amount,nullif(v_item->>'note',''),v_ticket_key
        );
      end if;
    exception when others then
      v_result := jsonb_build_object(
        'success',false,'error','Transfer Failed','error_code',sqlstate
      );
    end;
    v_results := v_results || jsonb_build_array(
      jsonb_build_object('user_id',v_user_id) || coalesce(v_result,'{}'::jsonb)
    );
  end loop;

  return jsonb_build_object(
    'success',true,
    'batch_id',p_batch_id,
    'results',v_results,
    'processed',jsonb_array_length(v_results)
  );
end
$_$;


ALTER FUNCTION public.fn_cashier_batch_transfer(p_club_id uuid, p_kind text, p_items jsonb, p_batch_id uuid) OWNER TO postgres;

--
-- TOC entry 46552 (class 0 OID 0)
-- Dependencies: 8833
-- Name: FUNCTION fn_cashier_batch_transfer(p_club_id uuid, p_kind text, p_items jsonb, p_batch_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cashier_batch_transfer(p_club_id uuid, p_kind text, p_items jsonb, p_batch_id uuid) IS 'Processes at most 25 idempotent cashier sends or tickets in one round trip and returns one explicit result per recipient.';


--
-- TOC entry 3710 (class 1255 OID 217197711)
-- Name: fn_cashier_browser_recovery_ack(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_browser_recovery_ack(p_actor_id uuid, p_club_id uuid, p_kind text, p_intent_key text, p_identity uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_deleted integer;
BEGIN
 IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_actor_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Cashier Recovery Account Does Not Match';END IF;
 DELETE FROM public.cashier_browser_recoveries WHERE actor_id=p_actor_id AND club_id=p_club_id AND kind=p_kind AND intent_key=p_intent_key AND identity=p_identity;
 GET DIAGNOSTICS v_deleted=ROW_COUNT;
 RETURN v_deleted=1;
END $$;


ALTER FUNCTION public.fn_cashier_browser_recovery_ack(p_actor_id uuid, p_club_id uuid, p_kind text, p_intent_key text, p_identity uuid) OWNER TO postgres;

--
-- TOC entry 9021 (class 1255 OID 217197704)
-- Name: fn_cashier_browser_recovery_canonical(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_browser_recovery_canonical(p_value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_result text;
BEGIN
 CASE jsonb_typeof(p_value)
 WHEN 'object' THEN
  SELECT '{'||coalesce(string_agg(to_jsonb(e.key)::text||':'||public.fn_cashier_browser_recovery_canonical(e.value),',' ORDER BY e.key COLLATE "C"),'')||'}'
  INTO v_result FROM jsonb_each(p_value) e;
 WHEN 'array' THEN
  SELECT '['||coalesce(string_agg(public.fn_cashier_browser_recovery_canonical(e.value),',' ORDER BY e.n),'')||']'
  INTO v_result FROM jsonb_array_elements(p_value) WITH ORDINALITY e(value,n);
 ELSE v_result:=p_value::text;
 END CASE;
 RETURN v_result;
END $$;


ALTER FUNCTION public.fn_cashier_browser_recovery_canonical(p_value jsonb) OWNER TO postgres;

--
-- TOC entry 4539 (class 1255 OID 217197709)
-- Name: fn_cashier_browser_recovery_read(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_browser_recovery_read(p_actor_id uuid, p_club_id uuid, p_kind text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_result jsonb;
BEGIN
 IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_actor_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Cashier Recovery Account Does Not Match';END IF;
 IF p_club_id IS NULL OR p_kind IS NULL OR p_kind NOT IN ('wallet','transfer') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid Cashier Recovery Scope';END IF;
 SELECT coalesce(jsonb_agg(envelope ORDER BY created_at,intent_key),'[]'::jsonb) INTO v_result
 FROM public.cashier_browser_recoveries WHERE actor_id=p_actor_id AND club_id=p_club_id AND kind=p_kind;
 RETURN v_result;
END $$;


ALTER FUNCTION public.fn_cashier_browser_recovery_read(p_actor_id uuid, p_club_id uuid, p_kind text) OWNER TO postgres;

--
-- TOC entry 8901 (class 1255 OID 217197708)
-- Name: fn_cashier_browser_recovery_reserve(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_browser_recovery_reserve(p_actor_id uuid, p_club_id uuid, p_kind text, p_intent_key text, p_envelope jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_result jsonb; v_identity uuid;
BEGIN
 IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_actor_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Cashier Recovery Account Does Not Match';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.club_members cm WHERE cm.club_id=p_club_id AND cm.user_id=p_actor_id AND coalesce(cm.status,'active') IN ('active','approved'))
 OR coalesce(public.fn_club_cashier_scope(p_club_id,p_actor_id),'none')='none' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Active Cashier Access Is Required';END IF;
 IF NOT public.fn_cashier_browser_recovery_valid(p_actor_id,p_club_id,p_kind,p_intent_key,p_envelope) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid Cashier Recovery Envelope';END IF;
 v_identity:=(p_envelope->>CASE WHEN p_kind='wallet' THEN 'operationId' ELSE 'submissionId' END)::uuid;
 -- The actor/club/kind/business key serializes simultaneous tabs. Adopt the
 -- first readable legacy identity or draft and return that exact envelope.
 INSERT INTO public.cashier_browser_recoveries AS held(actor_id,club_id,kind,intent_key,identity,envelope)
 VALUES(p_actor_id,p_club_id,p_kind,p_intent_key,v_identity,p_envelope)
 ON CONFLICT(actor_id,club_id,kind,intent_key) DO UPDATE SET envelope=held.envelope
 RETURNING envelope INTO v_result;
 RETURN v_result;
END $$;


ALTER FUNCTION public.fn_cashier_browser_recovery_reserve(p_actor_id uuid, p_club_id uuid, p_kind text, p_intent_key text, p_envelope jsonb) OWNER TO postgres;

--
-- TOC entry 6978 (class 1255 OID 217197710)
-- Name: fn_cashier_browser_recovery_update(uuid, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_browser_recovery_update(p_actor_id uuid, p_club_id uuid, p_kind text, p_intent_key text, p_identity uuid, p_envelope jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_original jsonb; v_identity uuid;
BEGIN
 IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_actor_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Cashier Recovery Account Does Not Match';END IF;
 SELECT envelope,identity INTO v_original,v_identity FROM public.cashier_browser_recoveries
 WHERE actor_id=p_actor_id AND club_id=p_club_id AND kind=p_kind AND intent_key=p_intent_key FOR UPDATE;
 IF NOT FOUND OR v_identity IS DISTINCT FROM p_identity THEN RETURN false;END IF;
 IF NOT public.fn_cashier_browser_recovery_valid(p_actor_id,p_club_id,p_kind,p_intent_key,p_envelope) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid Cashier Recovery Envelope';END IF;
 IF p_kind='wallet' THEN RETURN p_envelope=v_original;END IF;
 IF p_envelope-'failures' IS DISTINCT FROM v_original-'failures' THEN RETURN false;END IF;
 -- Compare against the CURRENT row under its lock. A stale tab can never
 -- reintroduce a target whose authoritative result another tab acknowledged.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_envelope->'failures') f
   WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_original->'failures') o WHERE o->>'userId'=f->>'userId')) THEN RETURN false;END IF;
 UPDATE public.cashier_browser_recoveries SET envelope=p_envelope
 WHERE actor_id=p_actor_id AND club_id=p_club_id AND kind=p_kind AND intent_key=p_intent_key AND identity=p_identity;
 RETURN true;
END $$;


ALTER FUNCTION public.fn_cashier_browser_recovery_update(p_actor_id uuid, p_club_id uuid, p_kind text, p_intent_key text, p_identity uuid, p_envelope jsonb) OWNER TO postgres;

--
-- TOC entry 3409 (class 1255 OID 217197705)
-- Name: fn_cashier_browser_recovery_valid(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_browser_recovery_valid(p_actor_id uuid, p_club_id uuid, p_kind text, p_intent_key text, p_envelope jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE v_identity text; v_targets jsonb; v_target text; v_failure jsonb; v_value jsonb; v_seen text[]:=ARRAY[]::text[];
 -- Operation identities accept every UUID shape; only the zero sentinel is invalid.
 v_uuid constant text:='^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
 v_entity constant text:='^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
BEGIN
 IF p_actor_id IS NULL OR p_club_id IS NULL OR p_actor_id='00000000-0000-0000-0000-000000000000'::uuid OR p_club_id='00000000-0000-0000-0000-000000000000'::uuid
 OR p_kind IS NULL OR p_kind NOT IN ('wallet','transfer') OR p_intent_key IS NULL OR length(p_intent_key)>160
 OR p_envelope IS NULL OR jsonb_typeof(p_envelope)<>'object' OR octet_length(p_envelope::text)>16777216
 OR p_envelope->'version' IS DISTINCT FROM '1'::jsonb
 OR p_envelope->>'userId' IS DISTINCT FROM p_actor_id::text OR p_envelope->>'clubId' IS DISTINCT FROM p_club_id::text
 OR jsonb_typeof(p_envelope->'createdAt') IS DISTINCT FROM 'number'
 OR (p_envelope->>'createdAt')::numeric<0 OR (p_envelope->>'createdAt')::numeric>1000000000000000 THEN RETURN false;END IF;
 IF p_kind='wallet' THEN
  IF p_envelope-ARRAY['version','userId','clubId','action','digest','operationId','createdAt']<>'{}'::jsonb
  OR p_envelope->>'action' IS NULL OR p_envelope->>'action' NOT IN ('fn_club_bank_send','fn_club_bank_claim_back','fn_agent_wallet_send','fn_agent_wallet_claim_back','fn_club_bank_reverse','fn_promo_wallet_send','fn_club_promo_wallet_send')
  OR coalesce(p_envelope->>'digest','')!~'^[0-9a-f]{64}$'
  OR p_intent_key IS DISTINCT FROM (p_envelope->>'action')||':'||(p_envelope->>'digest')
  OR coalesce(p_envelope->>'operationId','')!~*v_uuid OR p_envelope->>'operationId'='00000000-0000-0000-0000-000000000000' THEN RETURN false;END IF;
  RETURN true;
 END IF;
 IF p_intent_key!~'^[0-9a-f]{64}$'
 OR p_envelope-ARRAY['version','userId','clubId','kind','amount','targetIds','targetAmounts','failures','submissionId','opIds','destinations','source','ticketNote','tournamentId','createdAt']<>'{}'::jsonb
 OR coalesce(p_envelope->>'kind','') NOT IN ('send','ticket')
 OR coalesce(p_envelope->>'submissionId','')!~*v_uuid OR p_envelope->>'submissionId'='00000000-0000-0000-0000-000000000000'
 OR jsonb_typeof(p_envelope->'amount') IS DISTINCT FROM 'number'
 OR (p_envelope->>'amount')::numeric<=0 OR (p_envelope->>'amount')::numeric>1000000000
 OR (p_envelope->>'amount')::numeric<>round((p_envelope->>'amount')::numeric,2)
 OR jsonb_typeof(p_envelope->'targetIds') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_envelope->'failures') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_envelope->'opIds') IS DISTINCT FROM 'object' THEN RETURN false;END IF;
 v_targets:=p_envelope->'targetIds';
 IF jsonb_array_length(v_targets) NOT BETWEEN 1 AND 10000
 OR jsonb_array_length(p_envelope->'failures') NOT BETWEEN 1 AND jsonb_array_length(v_targets) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_targets) t WHERE jsonb_typeof(t)<>'string') THEN RETURN false;END IF;
 FOR v_target IN SELECT jsonb_array_elements_text(v_targets) LOOP
  IF v_target!~*v_entity OR v_target='00000000-0000-0000-0000-000000000000' OR v_target=ANY(v_seen) THEN RETURN false;END IF;
  v_seen:=array_append(v_seen,v_target);
  IF p_envelope->>'kind'='send' AND (coalesce(p_envelope->'opIds'->>v_target,'')!~*v_uuid OR p_envelope->'opIds'->>v_target='00000000-0000-0000-0000-000000000000') THEN RETURN false;END IF;
 END LOOP;
 FOR v_target,v_value IN SELECT key,value FROM jsonb_each(p_envelope->'opIds') LOOP
  IF NOT(v_targets? v_target) OR jsonb_typeof(v_value)<>'string' OR trim(both '"' FROM v_value::text)!~*v_uuid OR trim(both '"' FROM v_value::text)='00000000-0000-0000-0000-000000000000' THEN RETURN false;END IF;
 END LOOP;
 IF p_envelope?'source' AND coalesce(p_envelope->>'source','') NOT IN ('agent_wallet','club_bank','promo_wallet','club_promo_wallet','player_wallet') THEN RETURN false;END IF;
 IF p_envelope?'ticketNote' AND p_envelope->>'ticketNote' IS DISTINCT FROM 'Cashier Ticket' THEN RETURN false;END IF;
 IF p_envelope?'tournamentId' AND (p_envelope->>'kind'<>'ticket' OR coalesce(p_envelope->>'tournamentId','')!~*v_entity OR p_envelope->>'tournamentId'='00000000-0000-0000-0000-000000000000') THEN RETURN false;END IF;
 IF p_envelope?'targetAmounts' THEN
  IF jsonb_typeof(p_envelope->'targetAmounts') IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(p_envelope->'targetAmounts'))<>jsonb_array_length(v_targets) THEN RETURN false;END IF;
  FOR v_target,v_value IN SELECT key,value FROM jsonb_each(p_envelope->'targetAmounts') LOOP
   IF NOT(v_targets? v_target) OR jsonb_typeof(v_value)<>'number' OR v_value::text::numeric<=0 OR v_value::text::numeric>1000000000 OR v_value::text::numeric<>round(v_value::text::numeric,2) THEN RETURN false;END IF;
  END LOOP;
 END IF;
 IF p_envelope?'destinations' THEN
  IF jsonb_typeof(p_envelope->'destinations') IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(p_envelope->'destinations'))<>jsonb_array_length(v_targets) THEN RETURN false;END IF;
  FOR v_target,v_value IN SELECT key,value FROM jsonb_each(p_envelope->'destinations') LOOP
   IF NOT(v_targets? v_target) OR jsonb_typeof(v_value)<>'string' OR trim(both '"' FROM v_value::text) NOT IN ('agent_wallet','player_wallet','promo_wallet') THEN RETURN false;END IF;
  END LOOP;
 END IF;
 v_seen:=ARRAY[]::text[];
 FOR v_failure IN SELECT jsonb_array_elements(p_envelope->'failures') LOOP
  v_target:=v_failure->>'userId';
  IF jsonb_typeof(v_failure)<>'object' OR v_failure-ARRAY['userId','name','message']<>'{}'::jsonb
  OR v_target IS NULL OR NOT(v_targets? v_target) OR v_target=ANY(v_seen)
  OR jsonb_typeof(v_failure->'name') IS DISTINCT FROM 'string' OR length(v_failure->>'name') NOT BETWEEN 1 AND 200
  OR jsonb_typeof(v_failure->'message') IS DISTINCT FROM 'string' OR length(v_failure->>'message') NOT BETWEEN 1 AND 500 THEN RETURN false;END IF;
  v_seen:=array_append(v_seen,v_target);
 END LOOP;
 RETURN p_intent_key=encode(sha256(convert_to(public.fn_cashier_browser_recovery_canonical(p_envelope-ARRAY['submissionId','opIds','failures','createdAt']),'UTF8')),'hex');
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $_$;


ALTER FUNCTION public.fn_cashier_browser_recovery_valid(p_actor_id uuid, p_club_id uuid, p_kind text, p_intent_key text, p_envelope jsonb) OWNER TO postgres;

--
-- TOC entry 4890 (class 1255 OID 34786007)
-- Name: fn_cashier_cashout_transition(text, uuid, uuid, numeric, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_cashout_transition(p_action text, p_club_id uuid, p_cashout_id uuid, p_amount numeric, p_expected_actor_id uuid, p_op_id uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE actor uuid:=auth.uid();actual_role text;kind text;request_status text;v_release_type text;
 note text:=NULLIF(btrim(p_note),'');fingerprint jsonb;prior public.accounting_cashier_events%ROWTYPE;
 r public.cashout_requests%ROWTYPE;s public.chip_escrow%ROWTYPE;h public.accounting_cashier_events%ROWTYPE;
 e public.accounting_cashier_events%ROWTYPE;member public.club_members%ROWTYPE;agent public.agents%ROWTYPE;
 club public.clubs%ROWTYPE;wallet_before numeric;wallet_after numeric;agent_row_id uuid;assigned uuid;
 request_id uuid:=p_cashout_id;escrow_id uuid;event_id uuid:=gen_random_uuid();invoice_id uuid:=gen_random_uuid();tx_id uuid:=gen_random_uuid();leg_id uuid;
 at_time timestamptz:=transaction_timestamp();issue_time timestamptz;leg_count int;rows_written int;persisted numeric;
 tx_type text;tx_note text;tx_from uuid;tx_to uuid;audience uuid[];payload jsonb;result jsonb;wallet_user uuid;
 old_category text:=current_setting('app.ledger_category',true);old_cp text:=current_setting('app.ledger_counterparty',true);
 old_entity text:=current_setting('app.ledger_counterparty_entity',true);old_key text:=current_setting('app.ledger_idempotency_key',true);
 old_settlement text:=current_setting('app.ledger_settlement',true);old_tournament text:=current_setting('app.ledger_tournament',true);
 old_hand text:=current_setting('app.ledger_hand_id',true);old_tournament_id text:=current_setting('app.ledger_tournament_id',true);
BEGIN
  -- Serialize the existing agreement before any operation/hierarchy/row lock.
  -- Nested callers reacquire the same transaction lock; no new money path.
  IF p_club_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||p_club_id::text,0));
  END IF;

 IF p_action IS NULL OR p_action NOT IN('hold','approval','release','expiry_refund') OR p_club_id IS NULL OR p_op_id IS NULL
  OR (p_action='hold' AND p_cashout_id IS NOT NULL) OR (p_action<>'hold' AND p_cashout_id IS NULL)
 THEN RAISE EXCEPTION 'cashier_intent_incomplete' USING ERRCODE='22023';END IF;
 IF p_action='expiry_refund' THEN
  IF actor IS NOT NULL OR p_expected_actor_id IS NOT NULL
  THEN RAISE EXCEPTION 'cashier_system_actor_required' USING ERRCODE='42501';END IF;
 ELSE
  IF actor IS NULL OR actor IS DISTINCT FROM p_expected_actor_id
  THEN RAISE EXCEPTION 'cashier_account_changed' USING ERRCODE='42501';END IF;
 END IF;
 IF p_amount IS NULL OR p_amount::text IN('NaN','Infinity','-Infinity') OR p_amount<=0
    OR p_amount>1000000000 OR p_amount<>round(p_amount,2)
 THEN RAISE EXCEPTION 'cashier_invalid_amount' USING ERRCODE='22023';END IF;
 fingerprint:=jsonb_build_object('action',p_action,'actor',actor,'club_id',p_club_id,'cashout_id',p_cashout_id,
   'amount',round(p_amount,2)::text,'note',note);
 PERFORM pg_advisory_xact_lock(hashtextextended('cashout-op:'||COALESCE(actor::text,'system')||':'||p_op_id::text,0));
 -- Hierarchy first: never take a request or wallet row before this scope lock.
 PERFORM pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||p_club_id::text,0));
 SELECT * INTO club FROM public.clubs WHERE id=p_club_id FOR UPDATE;
 IF NOT FOUND OR club.owner_id IS NULL THEN RAISE EXCEPTION 'cashier_club_unavailable' USING ERRCODE='23514';END IF;
 SELECT * INTO prior FROM public.accounting_cashier_events WHERE actor_user_id IS NOT DISTINCT FROM actor AND op_id=p_op_id;
 IF FOUND THEN
  IF prior.operation_fingerprint IS DISTINCT FROM fingerprint
  THEN RAISE EXCEPTION 'cashier_operation_conflict' USING ERRCODE='22023';END IF;
  RETURN public.fn_cashier_operation_receipt(prior.id,true);
 END IF;
 -- Legacy chips alone cannot certify a canonical hold, delivery or replay.
 IF EXISTS(SELECT 1 FROM public.chip_transactions t WHERE t.metadata->>'op_id'=p_op_id::text
   AND t.transaction_type IN('cashout_request_escrow','cashout_approved','cashout_cancelled','cashout_denied','cashout_expired_refund')
   AND (t.from_user_id=actor OR t.to_user_id=actor OR (actor IS NULL AND t.transaction_type='cashout_expired_refund')))
 THEN RAISE EXCEPTION 'cashier_legacy_operation_unverified' USING ERRCODE='23514';END IF;
 IF current_setting('app.ledger_autoskip_club_members',true)='1' OR current_setting('app.ledger_autoskip_agents',true)='1'
 THEN RAISE EXCEPTION 'cashier_journal_is_suppressed' USING ERRCODE='23514';END IF;
 IF p_action='hold' THEN
  SELECT agent_id INTO assigned FROM public.club_members WHERE club_id=p_club_id AND user_id=actor;
  PERFORM public.fn_cashier_lock_authority(p_club_id,actor,actor,COALESCE(assigned,club.owner_id));
  SELECT * INTO member FROM public.club_members WHERE club_id=p_club_id AND user_id=actor FOR UPDATE;
  IF NOT FOUND OR COALESCE(member.status,'active') NOT IN('active','approved')
    OR member.role NOT IN('owner','co_owner','admin','super_agent','agent','sub_agent','player','member')
  THEN RAISE EXCEPTION 'cashier_player_wallet_unavailable' USING ERRCODE='42501';END IF;
  actual_role:=member.role;assigned:=COALESCE(member.agent_id,club.owner_id);
  IF assigned IS NULL OR assigned=actor OR public.fn_club_cashier_can_transact(p_club_id,assigned,actor) IS NOT TRUE
    OR COALESCE(public.fn_club_bank_role(p_club_id,assigned),'') NOT IN('owner','co_owner','admin','super_agent','agent','sub_agent')
  THEN RAISE EXCEPTION 'cashier_assigned_cashier_unavailable' USING ERRCODE='42501';END IF;
  IF EXISTS(SELECT 1 FROM public.cashout_requests WHERE club_id=p_club_id AND player_id=actor AND status='pending')
  THEN RAISE EXCEPTION 'cashier_pending_request_exists' USING ERRCODE='23514';END IF;
  request_id:=gen_random_uuid();escrow_id:=gen_random_uuid();kind:='hold';request_status:='pending';wallet_user:=actor;
  wallet_before:=member.chip_balance;
 ELSE
  SELECT * INTO r FROM public.cashout_requests WHERE id=p_cashout_id FOR UPDATE;
  IF NOT FOUND OR r.club_id IS DISTINCT FROM p_club_id OR r.amount IS DISTINCT FROM p_amount
  THEN RAISE EXCEPTION 'cashier_request_intent_mismatch' USING ERRCODE='22023';END IF;
  IF r.status IS DISTINCT FROM 'pending' THEN RAISE EXCEPTION 'cashier_request_already_terminal' USING ERRCODE='23514';END IF;
  SELECT * INTO s FROM public.chip_escrow WHERE cashout_request_id=r.id FOR UPDATE;
  IF NOT FOUND OR s.club_id IS DISTINCT FROM r.club_id OR s.player_id IS DISTINCT FROM r.player_id
    OR s.amount IS DISTINCT FROM r.amount OR s.table_id IS NOT NULL OR s.released_at IS NOT NULL OR s.release_type IS NOT NULL
    OR s.locked_at IS DISTINCT FROM r.created_at
  THEN RAISE EXCEPTION 'cashier_escrow_unverified' USING ERRCODE='23514';END IF;
  SELECT * INTO h FROM public.accounting_cashier_events WHERE cashout_id=r.id AND event_slot='hold';
  IF NOT FOUND THEN RAISE EXCEPTION 'cashier_legacy_hold_unverified' USING ERRCODE='23514';END IF;
  PERFORM public.fn_cashier_operation_receipt(h.id,true);
  escrow_id:=s.id;assigned:=r.agent_id;
  PERFORM public.fn_cashier_lock_authority(p_club_id,actor,r.player_id,assigned);
  IF p_action='expiry_refund' THEN kind:='expiry_refund';actual_role:='system';
  ELSIF p_action='release' AND actor=r.player_id THEN kind:='cancellation';
  ELSE
   actual_role:=public.fn_club_bank_role(p_club_id,actor);
   IF actor=r.player_id OR COALESCE(actual_role,'') NOT IN('owner','co_owner','admin','super_agent','agent','sub_agent')
      OR public.fn_club_cashier_can_transact(p_club_id,actor,r.player_id) IS NOT TRUE
   THEN RAISE EXCEPTION 'cashier_current_authority_required' USING ERRCODE='42501';END IF;
   kind:=CASE p_action WHEN 'approval' THEN 'approval' ELSE 'decline' END;
  END IF;
  request_status:=CASE kind WHEN 'approval' THEN 'approved' WHEN 'cancellation' THEN 'cancelled' WHEN 'decline' THEN 'rejected' ELSE 'expired' END;
  v_release_type:=CASE kind WHEN 'approval' THEN 'completed' ELSE request_status END;
  IF kind='approval' THEN
   agent_row_id:=public.fn_ensure_agent_row(p_club_id,actor,actual_role);
   SELECT * INTO agent FROM public.agents WHERE id=agent_row_id AND club_id=p_club_id AND user_id=actor FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'cashier_destination_wallet_unavailable' USING ERRCODE='23503';END IF;
   wallet_before:=agent.agent_wallet_balance;wallet_user:=actor;
  ELSE
   SELECT * INTO member FROM public.club_members WHERE club_id=p_club_id AND user_id=r.player_id FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'cashier_refund_wallet_missing' USING ERRCODE='23503';END IF;
   IF kind='cancellation' THEN
    actual_role:=member.role;
    IF actual_role IS NULL OR actual_role NOT IN('owner','co_owner','admin','super_agent','agent','sub_agent','player','member')
    THEN RAISE EXCEPTION 'cashier_player_role_unavailable' USING ERRCODE='42501';END IF;
   END IF;
   wallet_before:=member.chip_balance;wallet_user:=r.player_id;
  END IF;
 END IF;
 IF wallet_before IS NULL OR wallet_before<0 OR wallet_before::text IN('NaN','Infinity','-Infinity') OR wallet_before<>round(wallet_before,2)
   OR (kind='hold' AND wallet_before<p_amount)
 THEN RAISE EXCEPTION 'cashier_wallet_balance_unverified' USING ERRCODE='23514';END IF;
 wallet_after:=wallet_before+CASE WHEN kind='hold' THEN -p_amount ELSE p_amount END;
 -- Ambient unrelated ledger context must never contaminate this custody leg.
 PERFORM set_config('app.ledger_settlement','',true);PERFORM set_config('app.ledger_tournament','',true);
 PERFORM set_config('app.ledger_hand_id','',true);PERFORM set_config('app.ledger_tournament_id','',true);
 PERFORM public.fn_ca_declare_ledger(CASE WHEN kind='hold' THEN 'escrow_hold' ELSE 'escrow_release' END,
  'escrow',escrow_id,NULL,'cashout:'||request_id::text||CASE WHEN kind='hold' THEN ':hold' ELSE ':release' END,NULL);
 IF kind='approval' THEN
  UPDATE public.agents SET agent_wallet_balance=wallet_after,updated_at=at_time WHERE id=agent.id RETURNING agent_wallet_balance INTO persisted;
 ELSE
  UPDATE public.club_members SET chip_balance=wallet_after,updated_at=at_time WHERE club_id=member.club_id AND user_id=member.user_id RETURNING chip_balance INTO persisted;
 END IF;
 GET DIAGNOSTICS rows_written=ROW_COUNT;
 IF rows_written<>1 OR persisted IS DISTINCT FROM wallet_after THEN RAISE EXCEPTION 'cashier_wallet_write_missing' USING ERRCODE='23514';END IF;
 PERFORM set_config('app.ledger_category',COALESCE(old_category,''),true);PERFORM set_config('app.ledger_counterparty',COALESCE(old_cp,''),true);
 PERFORM set_config('app.ledger_counterparty_entity',COALESCE(old_entity,''),true);PERFORM set_config('app.ledger_idempotency_key',COALESCE(old_key,''),true);
 PERFORM set_config('app.ledger_settlement',COALESCE(old_settlement,''),true);PERFORM set_config('app.ledger_tournament',COALESCE(old_tournament,''),true);
 PERFORM set_config('app.ledger_hand_id',COALESCE(old_hand,''),true);PERFORM set_config('app.ledger_tournament_id',COALESCE(old_tournament_id,''),true);
 IF kind='hold' THEN
  INSERT INTO public.cashout_requests(id,club_id,player_id,agent_id,amount,status,player_note,created_at,updated_at)
   VALUES(request_id,p_club_id,actor,assigned,p_amount,'pending',note,at_time,at_time) RETURNING * INTO r;
  IF NOT FOUND THEN RAISE EXCEPTION 'cashier_request_write_missing' USING ERRCODE='23514';END IF;
  INSERT INTO public.chip_escrow(id,cashout_request_id,club_id,player_id,amount,locked_at)
   VALUES(escrow_id,request_id,p_club_id,actor,p_amount,at_time) RETURNING * INTO s;
  IF NOT FOUND THEN RAISE EXCEPTION 'cashier_escrow_write_missing' USING ERRCODE='23514';END IF;
 ELSE
  UPDATE public.chip_escrow SET released_at=at_time,release_type=v_release_type WHERE id=escrow_id RETURNING * INTO s;
  IF NOT FOUND THEN RAISE EXCEPTION 'cashier_escrow_write_missing' USING ERRCODE='23514';END IF;
  UPDATE public.cashout_requests SET status=request_status,
   agent_note=CASE WHEN kind IN('approval','decline') THEN note ELSE agent_note END,
   acknowledged_at=CASE WHEN kind IN('approval','decline') THEN at_time ELSE NULL END,
   completed_at=CASE WHEN kind='approval' THEN at_time ELSE NULL END,
   cancelled_at=CASE WHEN kind IN('cancellation','decline','expiry_refund') THEN at_time ELSE NULL END,updated_at=at_time
   WHERE id=request_id RETURNING * INTO r;
  IF NOT FOUND THEN RAISE EXCEPTION 'cashier_request_write_missing' USING ERRCODE='23514';END IF;
 END IF;
 SELECT count(*),(array_agg(id))[1] INTO leg_count,leg_id FROM public.chip_ledger
  WHERE idempotency_key='cashout:'||request_id::text||CASE WHEN kind='hold' THEN ':hold' ELSE ':release' END;
 IF leg_count<>1 THEN RAISE EXCEPTION 'cashier_physical_ledger_missing_or_duplicate' USING ERRCODE='23514';END IF;
 tx_type:=CASE kind WHEN 'hold' THEN 'cashout_request_escrow' WHEN 'approval' THEN 'cashout_approved'
   WHEN 'cancellation' THEN 'cashout_cancelled' WHEN 'decline' THEN 'cashout_denied' ELSE 'cashout_expired_refund' END;
 tx_note:=COALESCE(note,CASE kind WHEN 'hold' THEN 'Cash Out Requested. Chips Held In Escrow'
  WHEN 'approval' THEN 'Cash Out Approved. Escrow Released Into The Agent Wallet'
  WHEN 'cancellation' THEN 'Cash Out Cancelled. Escrow Returned To Player'
  WHEN 'decline' THEN 'Cash Out Declined. Escrow Returned To Player' ELSE 'Stale Cash Out Expired. Escrow Returned To Player' END);
 tx_from:=CASE WHEN kind IN('hold','approval') THEN r.player_id ELSE actor END;
 tx_to:=CASE kind WHEN 'hold' THEN assigned WHEN 'approval' THEN actor ELSE r.player_id END;
 INSERT INTO public.chip_transactions(id,club_id,from_user_id,to_user_id,amount,transaction_type,notes,related_cashout_id,metadata,balance_after,created_at)
  VALUES(tx_id,p_club_id,tx_from,tx_to,p_amount,tx_type,tx_note,request_id,
   jsonb_build_object('op_id',p_op_id,'cashier_document_version',1,'event_id',event_id,'assigned_agent_id',assigned,
     'actor_user_id',actor,'actor_role',actual_role),wallet_after,at_time);
 GET DIAGNOSTICS rows_written=ROW_COUNT;
 IF rows_written<>1 THEN RAISE EXCEPTION 'cashier_transaction_write_missing' USING ERRCODE='23514';END IF;
 SELECT array_agg(DISTINCT x ORDER BY x) INTO audience FROM unnest(ARRAY[club.owner_id,r.player_id,
   CASE WHEN kind IN('approval','decline') THEN actor ELSE assigned END]) x;
 IF cardinality(audience)<2 OR EXISTS(SELECT 1 FROM unnest(audience) x WHERE x IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=x))
 THEN RAISE EXCEPTION 'cashier_document_audience_unavailable' USING ERRCODE='23514';END IF;
 issue_time:=clock_timestamp();
 INSERT INTO public.accounting_cashier_events(id,contract_version,cashout_id,escrow_id,source_transaction_id,source_ledger_id,invoice_id,event_slot,event_kind,
  hold_event_id,hold_invoice_id,club_id,player_id,assigned_agent_id,actor_user_id,actor_role,ledger_actor_user_id,
  issuer_representative_id,issuer_name,player_name,audience_user_ids,op_id,operation_fingerprint,accepted_note,transaction_note,amount,
  ledger_from_type,ledger_from_entity_id,ledger_to_type,ledger_to_entity_id,wallet_owner_id,wallet_before,wallet_after,occurred_at,issued_at)
 VALUES(event_id,1,request_id,escrow_id,tx_id,leg_id,invoice_id,CASE WHEN kind='hold' THEN 'hold' ELSE 'terminal' END,kind,
  h.id,h.invoice_id,p_club_id,r.player_id,assigned,actor,actual_role,COALESCE(actor,'2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
  club.owner_id,COALESCE(NULLIF(btrim(club.name),''),'Club'),public.fn_notify_display_name(r.player_id),audience,p_op_id,fingerprint,note,tx_note,p_amount,
  CASE WHEN kind='hold' THEN 'player_wallet' ELSE 'escrow' END,CASE WHEN kind='hold' THEN r.player_id ELSE escrow_id END,
  CASE kind WHEN 'hold' THEN 'escrow' WHEN 'approval' THEN 'agent_wallet' ELSE 'player_wallet' END,
  CASE kind WHEN 'hold' THEN escrow_id WHEN 'approval' THEN actor ELSE r.player_id END,wallet_user,wallet_before,wallet_after,at_time,issue_time)
 RETURNING * INTO e;
 IF NOT FOUND THEN RAISE EXCEPTION 'cashier_event_write_missing' USING ERRCODE='23514';END IF;
 payload:=public.fn_cashier_event_payload(e);
 INSERT INTO public.settlement_invoices(id,club_id,invoice_type,from_entity_type,from_entity_id,to_entity_type,to_entity_id,
  gross_amount,net_amount,deductions,breakdown,status,chips_transferred,transferred_at,source_ledger_id,notes,created_at,updated_at)
 VALUES(invoice_id,p_club_id,'cashier_cashout','club',p_club_id::text,'player',r.player_id::text,p_amount,p_amount,0,
  jsonb_build_object('kind','cashier_cashout','cashier',payload),CASE WHEN kind='hold' THEN 'generated' ELSE 'paid' END,kind<>'hold',
  CASE WHEN kind='hold' THEN NULL ELSE at_time END,leg_id,'Recorded cashier chip custody event.',issue_time,issue_time);
 GET DIAGNOSTICS rows_written=ROW_COUNT;
 IF rows_written<>1 THEN RAISE EXCEPTION 'cashier_invoice_write_missing' USING ERRCODE='23514';END IF;
 -- Read stored rows after all triggers; RETURNING alone cannot establish survival.
 IF kind='approval' THEN SELECT agent_wallet_balance INTO persisted FROM public.agents WHERE id=agent.id AND club_id=p_club_id AND user_id=actor;
 ELSE SELECT chip_balance INTO persisted FROM public.club_members WHERE club_id=member.club_id AND user_id=member.user_id AND club_id=p_club_id AND user_id=wallet_user;END IF;
 IF NOT FOUND OR persisted IS DISTINCT FROM wallet_after THEN RAISE EXCEPTION 'cashier_wallet_write_changed' USING ERRCODE='23514';END IF;
 result:=public.fn_cashier_operation_receipt(event_id,false);
 RETURN result;
END $$;


ALTER FUNCTION public.fn_cashier_cashout_transition(p_action text, p_club_id uuid, p_cashout_id uuid, p_amount numeric, p_expected_actor_id uuid, p_op_id uuid, p_note text) OWNER TO postgres;

--
-- TOC entry 8797 (class 1255 OID 15312286)
-- Name: fn_cashier_claim_back(uuid, uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_claim_back(p_club_id uuid, p_from_user_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  /* RETIRED 2026-10-02 (20261002140203). A peer wallet move that named no
     counterparty. It required auth.uid() but EXECUTE was granted only to
     service_role (which has none), so no caller could reach it. The claim
     back is fn_club_bank_claim_back / fn_agent_wallet_claim_back. Nothing is
     moved here. */
  RETURN jsonb_build_object('success', false, 'error', 'fn_cashier_claim_back_retired',
    'message', 'Use the Club Bank claim back (fn_club_bank_claim_back) or the agent wallet claim back (fn_agent_wallet_claim_back)');
END;
$$;


ALTER FUNCTION public.fn_cashier_claim_back(p_club_id uuid, p_from_user_id uuid, p_amount numeric, p_reason text, p_idempotency_key text) OWNER TO postgres;

--
-- TOC entry 3766 (class 1255 OID 147398797)
-- Name: fn_cashier_conservation_report(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_conservation_report(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_report jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication Required' USING ERRCODE='42501';
  END IF;
  IF p_club_id IS NULL THEN
    RAISE EXCEPTION 'Club Required' USING ERRCODE='22023';
  END IF;
  IF EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND status='deleted')
    OR NOT public.fn_cashier_member_is_active(p_club_id,auth.uid())
    OR coalesce(public.fn_club_bank_role(p_club_id,auth.uid()),'')
      NOT IN ('owner','co_owner','admin') THEN
    RAISE EXCEPTION 'Active Club Finance Access Required' USING ERRCODE='42501';
  END IF;

  IF NOT EXISTS(SELECT 1 FROM public.clubs WHERE id=p_club_id AND asset='chips') THEN
    RAISE EXCEPTION 'Accounting Report Covers Chip Clubs Only' USING ERRCODE='22023';
  END IF;

  -- chip_ledger records booked movement, including correction/reversal legs.
  -- Its validated NOT NULL status contract admits only posted/correction/reversal.
  -- Read every leg; filtering only posted would omit real money and force heap
  -- reads instead of the existing covering player-wallet index.
  --
  -- The bank is read by its own entity: every leg into or out of this club's
  -- treasury, whatever club_id it is filed under. A bank leg's club_id names
  -- the wallet club of the other side (a commission this bank pays into the
  -- payee's wallet in another club is filed under that club), so it never
  -- selects bank movement. These are the legs fn_ca_treasury_positions and
  -- the nightly reconcile read, from idx_chip_ledger_treasury_in/_out.
  WITH club_origin AS MATERIALIZED (
    -- A club born after the original journal baseline has no pre-existing
    -- member wallets. Reconcile those wallets from zero against every leg
    -- since its creation; an unjournaled initial balance remains a mismatch.
    SELECT c.created_at AS taken_at FROM public.clubs c
    WHERE c.id=p_club_id AND c.created_at>=(SELECT min(b.taken_at) FROM public.ca_chip_baseline b)
      AND NOT EXISTS(SELECT 1 FROM public.ca_chip_baseline b WHERE b.club_id=p_club_id)
  ), report_cutoffs AS MATERIALIZED (
    SELECT DISTINCT taken_at FROM public.ca_chip_baseline WHERE club_id=p_club_id
    UNION ALL SELECT taken_at FROM club_origin
  ), bank AS MATERIALIZED (
    SELECT c.chip_treasury AS actual,b.opening_balance,b.taken_at,
      b.opening_balance
        + coalesce((SELECT sum(l.amount) FROM public.chip_ledger l
          WHERE l.to_type='club_treasury'
            AND l.to_entity_id=p_club_id AND l.created_at>=b.taken_at
           ),0)
        - coalesce((SELECT sum(l.amount) FROM public.chip_ledger l
          WHERE l.from_type='club_treasury'
            AND l.from_entity_id=p_club_id AND l.created_at>=b.taken_at
           ),0) AS expected
    FROM public.clubs c LEFT JOIN public.ca_treasury_baseline b ON b.club_id=c.id
    WHERE c.id=p_club_id
  ), baselines AS MATERIALIZED (
    SELECT user_id,opening_balance,taken_at FROM public.ca_chip_baseline WHERE club_id=p_club_id
    UNION ALL
    -- A member who joined after the club baseline was taken entered with no
    -- chips: every chip they have held since is a booked ledger leg. They are
    -- checked from zero at the club's existing cutoff, so no new scan is added.
    -- A balance written without a leg still surfaces as a mismatch.
    SELECT m.user_id,0::numeric,f.taken_at
    FROM public.club_members m
    CROSS JOIN (SELECT min(taken_at) AS taken_at FROM report_cutoffs) f
    WHERE m.club_id=p_club_id AND f.taken_at IS NOT NULL AND m.joined_at>=f.taken_at
      AND NOT EXISTS (SELECT 1 FROM public.ca_chip_baseline x
        WHERE x.club_id=p_club_id AND x.user_id=m.user_id)
  ), cutoffs AS MATERIALIZED (
    -- Late-member baselines reuse min(original taken_at), so they cannot add
    -- a cutoff. Read the same set from its analyzed table: the UNION-derived
    -- materialization otherwise estimates 200 cutoffs and batches a huge hash.
    SELECT taken_at FROM report_cutoffs
  ), spans AS MATERIALIZED (
    -- Each cutoff reads its own UTC day raw from the cutoff, then the run of
    -- consecutive SEALED days after it, then everything from the first day
    -- that is not sealed, raw. A seal counts only while it carries its day's
    -- current manifest hash: a restated or newly attested day is read raw
    -- again until it is sealed again. The three parts are disjoint and cover
    -- [cutoff, now) exactly, so the result is the full-journal result. A NULL
    -- cutoff yields NULL bounds and reads nothing, exactly as before.
    SELECT c.taken_at, f.first_day,
      coalesce((
        SELECT min(g.d)::date
        FROM generate_series(f.first_day::timestamp,
          (statement_timestamp() AT TIME ZONE 'UTC')::date::timestamp + interval '1 day',
          interval '1 day') g(d)
        WHERE NOT EXISTS (
          SELECT 1 FROM public.ca_chip_wallet_day_seals s
          LEFT JOIN public.ca_ledger_day_manifests m ON m.day=s.day
          WHERE s.day=g.d::date AND s.manifest_sha256 IS NOT DISTINCT FROM m.sha256)
      ), f.first_day) AS open_from
    FROM cutoffs c
    CROSS JOIN LATERAL (SELECT (c.taken_at AT TIME ZONE 'UTC')::date + 1 AS first_day) f
  ), ranges AS MATERIALIZED (
    SELECT taken_at, taken_at AS lo, (first_day::timestamp AT TIME ZONE 'UTC') AS hi FROM spans
    UNION ALL
    SELECT taken_at, (open_from::timestamp AT TIME ZONE 'UTC'), 'infinity'::timestamptz FROM spans
  ), legs AS MATERIALIZED (
    -- The raw parts are bounded index ranges over the club's covering
    -- player-wallet legs. Both wallet sides are grouped from one scan per
    -- range with grouping sets; a leg whose side is not a player wallet
    -- collapses into one NULL key. Sealed days add their stored per-member
    -- nets. Each position still uses its own baseline cutoff in the join below.
    SELECT r.taken_at, g.uid, g.amt
    FROM ranges r
    CROSS JOIN LATERAL (
      SELECT coalesce(x.credit_user,x.debit_user) AS uid,
        CASE WHEN GROUPING(x.credit_user)=0 THEN sum(x.a) ELSE -sum(x.a) END AS amt
      FROM (
        SELECT CASE WHEN l.to_type='player_wallet' THEN l.to_entity_id END AS credit_user,
          CASE WHEN l.from_type='player_wallet' THEN l.from_entity_id END AS debit_user,
          l.amount AS a
        FROM public.chip_ledger l
        WHERE l.club_id=p_club_id AND l.created_at>=r.lo AND l.created_at<r.hi
          AND (l.to_type='player_wallet' OR l.from_type='player_wallet')
      ) x
      GROUP BY GROUPING SETS ((x.credit_user),(x.debit_user))
    ) g
    UNION ALL
    -- One row per member per cutoff, however many days are sealed.
    SELECT s.taken_at, t.user_id, sum(t.net)
    FROM spans s
    JOIN public.ca_chip_wallet_day_totals t
      ON t.club_id=p_club_id AND t.day>=s.first_day AND t.day<s.open_from
    GROUP BY s.taken_at, t.user_id
  ), moves AS MATERIALIZED (
    SELECT b.user_id, sum(g.amt) AS net
    FROM baselines b
    JOIN legs g ON g.taken_at=b.taken_at AND g.uid=b.user_id
    GROUP BY b.user_id
  ), positions AS MATERIALIZED (
    SELECT coalesce(m.user_id,b.user_id) AS user_id,m.chip_balance AS actual,
      b.opening_balance,b.taken_at,b.opening_balance+coalesce(mv.net,0) AS expected
    FROM (SELECT user_id,chip_balance FROM public.club_members WHERE club_id=p_club_id) m
    FULL JOIN baselines b USING(user_id)
    LEFT JOIN moves mv ON mv.user_id=b.user_id
  ), classified AS (
    SELECT *,actual IS NOT NULL AND opening_balance IS NOT NULL
      AND taken_at IS NOT NULL AND taken_at<=statement_timestamp() AS covered
    FROM positions
  ), totals AS (
    SELECT count(*) AS positions,count(*) FILTER(WHERE covered) AS checked,
      count(*) FILTER(WHERE NOT covered) AS missing,
      count(*) FILTER(WHERE covered AND actual<>expected) AS mismatches,
      coalesce(sum(abs(actual-expected)) FILTER(WHERE covered),0) AS absolute_drift,
      coalesce(sum(actual-expected) FILTER(WHERE covered),0) AS net_drift,
      sum(actual) FILTER(WHERE covered) AS actual,sum(expected) FILTER(WHERE covered) AS expected
    FROM classified
  )
  SELECT jsonb_build_object(
    'schema_version',1,'club_id',p_club_id,'as_of',statement_timestamp(),
    'scope','bank_and_player_baselines',
    'bank',jsonb_build_object(
      'status',CASE WHEN b.actual IS NULL OR b.opening_balance IS NULL OR b.taken_at IS NULL
        OR b.taken_at>statement_timestamp() THEN 'incomplete'
        WHEN b.actual<>b.expected THEN 'attention' ELSE 'verified' END,
      'actual',b.actual::text,'expected',b.expected::text,
      'drift',CASE WHEN b.taken_at<=statement_timestamp() THEN (b.actual-b.expected)::text END,
      'baseline_at',b.taken_at),
    'players',jsonb_build_object(
      'status',CASE WHEN t.mismatches>0 THEN 'attention'
        WHEN t.missing>0 OR t.checked=0 THEN 'incomplete' ELSE 'verified' END,
      'positions',t.positions,'checked',t.checked,'missing',t.missing,'mismatches',t.mismatches,
      'actual',t.actual::text,'expected',t.expected::text,
      'net_drift',t.net_drift::text,'absolute_drift',t.absolute_drift::text)
      || CASE WHEN EXISTS(SELECT 1 FROM club_origin) THEN jsonb_build_object(
        'basis','journal_from_club_creation','origin_at',(SELECT taken_at FROM club_origin)) ELSE '{}'::jsonb END,
    'inventory',jsonb_build_object(
      'agent_wallets',(SELECT CASE WHEN count(*) FILTER(WHERE agent_wallet_balance IS NULL)>0
        THEN NULL ELSE coalesce(sum(agent_wallet_balance),0)::text END FROM public.agents WHERE club_id=p_club_id),
      'promo_wallets',(SELECT CASE WHEN count(*) FILTER(WHERE promo_wallet_balance IS NULL)>0
        THEN NULL ELSE coalesce(sum(promo_wallet_balance),0)::text END FROM public.agents WHERE club_id=p_club_id),
      'held_chips',(SELECT CASE WHEN count(*) FILTER(WHERE held_chips IS NULL)>0
        THEN NULL ELSE coalesce(sum(held_chips),0)::text END FROM public.club_members WHERE club_id=p_club_id),
      'cash_stacks',(SELECT CASE WHEN count(*) FILTER(WHERE s.stack IS NULL)>0
        THEN NULL ELSE coalesce(sum(s.stack),0)::text END FROM public.table_seats s
        JOIN public.tables t ON t.id=s.table_id WHERE t.club_id=p_club_id
          AND t.tournament_id IS NULL AND s.left_at IS NULL)
    )
  ) INTO v_report FROM bank b CROSS JOIN totals t;
  IF v_report IS NULL THEN
    RAISE EXCEPTION 'Club Not Found' USING ERRCODE='22023';
  END IF;
  RETURN v_report;
END;
$$;


