--
-- TOC entry 7012 (class 1255 OID 101732534)
-- Name: fn_cashier_exact_intent_begin(text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_exact_intent_begin(p_action text, p_club uuid, p_operation uuid, p_intent jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_existing public.cashier_rpc_operation_intents%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('state', 'return', 'response',
      jsonb_build_object('success', false, 'error', 'Not Authenticated'));
  END IF;
  IF p_operation IS NULL THEN
    RETURN jsonb_build_object('state', 'return', 'response',
      jsonb_build_object('success', false, 'error', 'A Retry Key Is Required'));
  END IF;

  -- Global ownership prevents two actors racing the same UUID through the
  -- legacy core's looser metadata replay lookup.
  PERFORM pg_advisory_xact_lock(hashtextextended('cashier-exact-intent:' || p_operation, 0));
  SELECT * INTO v_existing
    FROM public.cashier_rpc_operation_intents
   WHERE operation_id = p_operation
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.actor_user_id IS DISTINCT FROM v_actor
       OR v_existing.action IS DISTINCT FROM p_action
       OR v_existing.club_id IS DISTINCT FROM p_club
       OR v_existing.operation_intent IS DISTINCT FROM p_intent THEN
      RETURN jsonb_build_object('state', 'return', 'response',
        jsonb_build_object('success', false,
          'error', 'That Retry Key Belongs To A Different Cashier Request'));
    END IF;
    IF v_existing.receipt IS NOT NULL THEN
      RETURN jsonb_build_object('state', 'return', 'response',
        v_existing.receipt || jsonb_build_object('replayed', true));
    END IF;
    IF NOT public.fn_ca_launch_accounting_accepts(v_existing.club_id,v_existing.created_at) THEN
      RETURN jsonb_build_object('state','return','response',jsonb_build_object('success',false,'error','Prior Launch Cashier Request Was Waived'));
    END IF;
    RETURN jsonb_build_object('state', 'proceed');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.chip_transactions t
     WHERE t.metadata ->> 'op_id' = p_operation::text
  ) OR EXISTS (
    SELECT 1 FROM public.chip_requests r
     WHERE r.op_id = p_operation
  ) THEN
    RETURN jsonb_build_object('state', 'return', 'response',
      jsonb_build_object('success', false,
        'error', 'That Legacy Retry Key Cannot Be Verified; Reconcile It Before Retrying'));
  END IF;

  INSERT INTO public.cashier_rpc_operation_intents(
    operation_id, actor_user_id, action, club_id, operation_intent, intent_fingerprint
  ) VALUES (
    p_operation, v_actor, p_action, p_club, p_intent, md5(p_intent::text)
  );
  RETURN jsonb_build_object('state', 'proceed');
END
$$;


ALTER FUNCTION public.fn_cashier_exact_intent_begin(p_action text, p_club uuid, p_operation uuid, p_intent jsonb) OWNER TO postgres;

--
-- TOC entry 4984 (class 1255 OID 101732535)
-- Name: fn_cashier_exact_intent_finish(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_exact_intent_finish(p_operation uuid, p_receipt jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF coalesce((p_receipt ->> 'success')::boolean, false) THEN
    UPDATE public.cashier_rpc_operation_intents
       SET receipt = p_receipt, completed_at = clock_timestamp()
     WHERE operation_id = p_operation AND actor_user_id = auth.uid();
    IF NOT FOUND THEN
      RAISE EXCEPTION 'cashier_operation_owner_changed' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN p_receipt;
END
$$;


ALTER FUNCTION public.fn_cashier_exact_intent_finish(p_operation uuid, p_receipt jsonb) OWNER TO postgres;

--
-- TOC entry 8206 (class 1255 OID 34785988)
-- Name: fn_cashier_invoice_contract(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_invoice_contract(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE e public.accounting_cashier_events%ROWTYPE; i public.settlement_invoices%ROWTYPE;
 l public.chip_ledger%ROWTYPE;t public.chip_transactions%ROWTYPE;h public.accounting_cashier_events%ROWTYPE;
 payload jsonb;expected_type text;
BEGIN
 SELECT * INTO e FROM public.accounting_cashier_events WHERE invoice_id=p_invoice_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'cashier_document_event_missing' USING ERRCODE='23514';END IF;
 SELECT * INTO i FROM public.settlement_invoices WHERE id=p_invoice_id;
 SELECT * INTO l FROM public.chip_ledger WHERE id=e.source_ledger_id;
 SELECT * INTO t FROM public.chip_transactions WHERE id=e.source_transaction_id;
 payload:=public.fn_cashier_event_payload(e);
 expected_type:=CASE e.event_kind WHEN 'hold' THEN 'cashout_request_escrow' WHEN 'approval' THEN 'cashout_approved'
  WHEN 'cancellation' THEN 'cashout_cancelled' WHEN 'decline' THEN 'cashout_denied' ELSE 'cashout_expired_refund' END;
 IF i.id IS NULL OR i.invoice_type<>'cashier_cashout' OR i.club_id IS DISTINCT FROM e.club_id
  OR i.from_entity_type<>'club' OR i.from_entity_id IS DISTINCT FROM e.club_id::text
  OR i.to_entity_type<>'player' OR i.to_entity_id IS DISTINCT FROM e.player_id::text
  OR i.source_ledger_id IS DISTINCT FROM e.source_ledger_id OR i.gross_amount IS DISTINCT FROM e.amount
  OR i.net_amount IS DISTINCT FROM e.amount OR i.deductions IS DISTINCT FROM 0
  OR i.status IS DISTINCT FROM (CASE WHEN e.event_kind='hold' THEN 'generated' ELSE 'paid' END)
  OR i.chips_transferred IS DISTINCT FROM (e.event_kind<>'hold')
  OR i.transferred_at IS DISTINCT FROM (CASE WHEN e.event_kind='hold' THEN NULL::timestamptz ELSE e.occurred_at END)
  OR i.created_at IS DISTINCT FROM e.issued_at OR i.breakdown->'cashier' IS DISTINCT FROM payload
  OR l.id IS NULL OR l.status<>'posted' OR l.amount IS DISTINCT FROM e.amount OR l.club_id IS DISTINCT FROM e.club_id
  OR l.from_type IS DISTINCT FROM e.ledger_from_type OR l.from_entity_id IS DISTINCT FROM e.ledger_from_entity_id
  OR l.to_type IS DISTINCT FROM e.ledger_to_type OR l.to_entity_id IS DISTINCT FROM e.ledger_to_entity_id
  OR l.category IS DISTINCT FROM (CASE WHEN e.event_kind='hold' THEN 'escrow_hold' ELSE 'escrow_release' END)
  OR l.idempotency_key IS DISTINCT FROM 'cashout:'||e.cashout_id::text||(CASE WHEN e.event_kind='hold' THEN ':hold' ELSE ':release' END)
  OR l.table_id IS NOT NULL OR l.hand_id IS NOT NULL OR l.tournament_id IS NOT NULL OR l.settlement_id IS NOT NULL
  OR l.performed_by IS DISTINCT FROM e.ledger_actor_user_id OR l.created_at IS DISTINCT FROM e.occurred_at
  OR t.id IS NULL OR t.club_id IS DISTINCT FROM e.club_id OR t.amount IS DISTINCT FROM e.amount
  OR t.related_cashout_id IS DISTINCT FROM e.cashout_id OR t.transaction_type IS DISTINCT FROM expected_type
  OR t.metadata->>'op_id' IS DISTINCT FROM e.op_id::text OR t.metadata->>'cashier_document_version' IS DISTINCT FROM '1'
  OR t.metadata->>'event_id' IS DISTINCT FROM e.id::text
  OR t.metadata->>'actor_user_id' IS DISTINCT FROM e.actor_user_id::text OR t.metadata->>'actor_role' IS DISTINCT FROM e.actor_role
  OR t.metadata->>'assigned_agent_id' IS DISTINCT FROM e.assigned_agent_id::text OR t.table_id IS NOT NULL OR t.notes IS DISTINCT FROM e.transaction_note
  OR t.balance_after IS DISTINCT FROM e.wallet_after OR t.created_at IS DISTINCT FROM e.occurred_at
  OR e.wallet_before IS NULL OR e.wallet_after IS NULL
  OR e.wallet_before::text IN('NaN','Infinity','-Infinity') OR e.wallet_after::text IN('NaN','Infinity','-Infinity')
  OR e.wallet_after-e.wallet_before IS DISTINCT FROM (CASE WHEN e.event_kind='hold' THEN -e.amount ELSE e.amount END)
  OR NOT EXISTS(SELECT 1 FROM public.chip_ledger_idem k WHERE k.idempotency_key=l.idempotency_key AND k.leg_id=l.id)
 THEN RAISE EXCEPTION 'cashier_document_provenance_mismatch' USING ERRCODE='23514';END IF;
 IF e.event_kind IN('hold','cancellation') AND e.actor_user_id IS DISTINCT FROM e.player_id
  OR e.event_kind IN('approval','decline') AND (e.actor_user_id=e.player_id OR e.actor_role NOT IN('owner','co_owner','admin','super_agent','agent','sub_agent'))
  OR e.assigned_agent_id=e.player_id
 THEN RAISE EXCEPTION 'cashier_actor_provenance_mismatch' USING ERRCODE='23514';END IF;
 IF e.event_kind='hold' THEN
  IF e.actor_user_id IS DISTINCT FROM e.player_id OR e.ledger_from_type<>'player_wallet' OR e.ledger_from_entity_id<>e.player_id
   OR e.ledger_to_type<>'escrow' OR e.ledger_to_entity_id<>e.escrow_id OR e.wallet_owner_id<>e.player_id
   OR t.from_user_id IS DISTINCT FROM e.player_id OR t.to_user_id IS DISTINCT FROM e.assigned_agent_id
  THEN RAISE EXCEPTION 'cashier_hold_route_mismatch' USING ERRCODE='23514';END IF;
 ELSE
  SELECT * INTO h FROM public.accounting_cashier_events WHERE id=e.hold_event_id;
  IF h.event_kind IS DISTINCT FROM 'hold' OR h.cashout_id IS DISTINCT FROM e.cashout_id
   OR h.escrow_id IS DISTINCT FROM e.escrow_id OR h.invoice_id IS DISTINCT FROM e.hold_invoice_id
   OR h.amount IS DISTINCT FROM e.amount OR h.club_id IS DISTINCT FROM e.club_id OR h.player_id IS DISTINCT FROM e.player_id
   OR h.assigned_agent_id IS DISTINCT FROM e.assigned_agent_id
   OR e.ledger_from_type<>'escrow' OR e.ledger_from_entity_id<>e.escrow_id
   OR e.ledger_to_type IS DISTINCT FROM (CASE WHEN e.event_kind='approval' THEN 'agent_wallet' ELSE 'player_wallet' END)
   OR e.ledger_to_entity_id IS DISTINCT FROM (CASE WHEN e.event_kind='approval' THEN e.actor_user_id ELSE e.player_id END)
   OR e.wallet_owner_id IS DISTINCT FROM e.ledger_to_entity_id
   OR t.from_user_id IS DISTINCT FROM (CASE WHEN e.event_kind='approval' THEN e.player_id ELSE e.actor_user_id END)
   OR t.to_user_id IS DISTINCT FROM e.ledger_to_entity_id
  THEN RAISE EXCEPTION 'cashier_terminal_route_mismatch' USING ERRCODE='23514';END IF;
 END IF;
 RETURN payload;
END $$;


ALTER FUNCTION public.fn_cashier_invoice_contract(p_invoice_id uuid) OWNER TO postgres;

--
-- TOC entry 4741 (class 1255 OID 34786006)
-- Name: fn_cashier_lock_authority(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_lock_authority(p_club_id uuid, p_actor uuid, p_target uuid, p_assigned uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE before_ids uuid[];after_ids uuid[];
BEGIN
 WITH RECURSIVE chain AS (
  SELECT m.user_id,m.agent_id,0 depth FROM public.club_members m WHERE m.club_id=p_club_id AND m.user_id=ANY(ARRAY[p_actor,p_target,p_assigned])
  UNION ALL SELECT m.user_id,m.agent_id,c.depth+1 FROM chain c JOIN public.club_members m ON m.club_id=p_club_id AND m.user_id=c.agent_id WHERE c.depth<20
 ) SELECT array_agg(DISTINCT user_id ORDER BY user_id) INTO before_ids FROM chain;
 PERFORM m.user_id FROM public.club_members m WHERE m.club_id=p_club_id AND m.user_id=ANY(before_ids) ORDER BY m.user_id FOR UPDATE;
 WITH RECURSIVE chain AS (
  SELECT m.user_id,m.agent_id,0 depth FROM public.club_members m WHERE m.club_id=p_club_id AND m.user_id=ANY(ARRAY[p_actor,p_target,p_assigned])
  UNION ALL SELECT m.user_id,m.agent_id,c.depth+1 FROM chain c JOIN public.club_members m ON m.club_id=p_club_id AND m.user_id=c.agent_id WHERE c.depth<20
 ) SELECT array_agg(DISTINCT user_id ORDER BY user_id) INTO after_ids FROM chain;
 IF before_ids IS DISTINCT FROM after_ids THEN RAISE EXCEPTION 'cashier_authority_changed_during_lock' USING ERRCODE='55000';END IF;
END $$;


ALTER FUNCTION public.fn_cashier_lock_authority(p_club_id uuid, p_actor uuid, p_target uuid, p_assigned uuid) OWNER TO postgres;

--
-- TOC entry 9630 (class 1255 OID 101732489)
-- Name: fn_cashier_member_is_active(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_member_is_active(p_club uuid, p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT EXISTS (
  SELECT 1 FROM public.club_members m WHERE m.club_id=p_club AND m.user_id=p_user
   AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=m.user_id AND p.status='deleted')
   AND coalesce(m.status,'active') IN ('active','approved')
   AND (coalesce(m.role,'player') NOT IN ('super_agent','agent','sub_agent')
    OR EXISTS (SELECT 1 FROM public.agents a WHERE a.club_id=m.club_id
     AND a.user_id=m.user_id AND a.status='active'))
 )
$$;


ALTER FUNCTION public.fn_cashier_member_is_active(p_club uuid, p_user uuid) OWNER TO postgres;

--
-- TOC entry 3858 (class 1255 OID 101732537)
-- Name: fn_cashier_operation_intent_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_operation_intent_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_operation uuid;
  v_owner uuid;
  v_action text;
  v_expected_type text;
BEGIN
  IF NEW.metadata ->> 'op_id' IS NULL THEN RETURN NEW; END IF;
  BEGIN
    v_operation := (NEW.metadata ->> 'op_id')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN NEW;
  END;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'cashier-exact-intent:' || v_operation, 0));
  SELECT actor_user_id, action INTO v_owner, v_action
    FROM public.cashier_rpc_operation_intents
   WHERE operation_id = v_operation;
  IF NOT FOUND THEN RETURN NEW; END IF;

  v_expected_type := CASE v_action
    WHEN 'club_bank_send' THEN 'club_bank_send'
    WHEN 'club_bank_claim' THEN 'club_bank_claim'
    WHEN 'club_bank_reversal' THEN 'club_bank_reversal'
    WHEN 'admin_removal' THEN 'admin_removal'
    WHEN 'promo_wallet_send' THEN 'promo_wallet_send'
    WHEN 'club_promo_send' THEN 'club_promo_send'
    WHEN 'agent_wallet_send' THEN 'agent_wallet_send'
    WHEN 'cashier_player_send' THEN 'peer_transfer'
    WHEN 'agent_wallet_claim_back' THEN 'agent_wallet_claim_back'
  END;
  IF v_owner IS DISTINCT FROM auth.uid()
     OR v_expected_type IS NULL
     OR NEW.transaction_type IS DISTINCT FROM v_expected_type THEN
    RAISE EXCEPTION 'cashier_retry_key_reused_across_actions' USING ERRCODE = '23505';
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_cashier_operation_intent_guard() OWNER TO postgres;

--
-- TOC entry 5548 (class 1255 OID 101732529)
-- Name: fn_cashier_operation_mutex_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_operation_mutex_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_correlation text := nullif(current_setting('app.ledger_correlation', true), '');
BEGIN
  IF v_correlation ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'cashier-exact-intent:' || v_correlation::uuid, 0));
  END IF;
  RETURN NULL;
END
$_$;


ALTER FUNCTION public.fn_cashier_operation_mutex_guard() OWNER TO postgres;

--
-- TOC entry 8897 (class 1255 OID 34785998)
-- Name: fn_cashier_operation_receipt(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_operation_receipt(p_event_id uuid, p_replayed boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO,YMD'
    AS $$
DECLARE e public.accounting_cashier_events%ROWTYPE; terminal public.accounting_cashier_events%ROWTYPE;
 r public.cashout_requests%ROWTYPE;s public.chip_escrow%ROWTYPE;payload jsonb;expected_status text;expected_release text;
BEGIN
 SELECT * INTO STRICT e FROM public.accounting_cashier_events WHERE id=p_event_id;
 SELECT * INTO r FROM public.cashout_requests WHERE id=e.cashout_id FOR UPDATE;
 SELECT * INTO s FROM public.chip_escrow WHERE id=e.escrow_id FOR UPDATE;
 payload:=public.fn_cashier_assert_delivery(e.id);
 IF r.id IS NULL OR s.id IS NULL OR r.club_id IS DISTINCT FROM e.club_id OR r.player_id IS DISTINCT FROM e.player_id
   OR r.agent_id IS DISTINCT FROM e.assigned_agent_id OR r.amount IS DISTINCT FROM e.amount
   OR s.cashout_request_id IS DISTINCT FROM r.id OR s.player_id IS DISTINCT FROM e.player_id
   OR s.club_id IS DISTINCT FROM e.club_id OR s.amount IS DISTINCT FROM e.amount OR s.table_id IS NOT NULL
   OR r.created_at IS NULL OR r.updated_at IS NULL OR NOT isfinite(r.created_at) OR NOT isfinite(r.updated_at)
   OR s.locked_at IS DISTINCT FROM r.created_at
 THEN RAISE EXCEPTION 'cashier_request_receipt_mismatch' USING ERRCODE='23514';END IF;
 IF e.event_kind='hold' THEN
  IF r.created_at IS DISTINCT FROM e.occurred_at OR r.player_note IS DISTINCT FROM e.accepted_note
  THEN RAISE EXCEPTION 'cashier_hold_request_mismatch' USING ERRCODE='23514';END IF;
  IF r.status='pending' THEN
   IF s.released_at IS NOT NULL OR s.release_type IS NOT NULL OR r.acknowledged_at IS NOT NULL
      OR r.completed_at IS NOT NULL OR r.cancelled_at IS NOT NULL OR r.updated_at IS DISTINCT FROM e.occurred_at
      OR EXISTS(SELECT 1 FROM public.accounting_cashier_events x WHERE x.cashout_id=r.id AND x.event_slot='terminal')
   THEN RAISE EXCEPTION 'cashier_pending_request_mismatch' USING ERRCODE='23514';END IF;
  ELSE
   SELECT * INTO terminal FROM public.accounting_cashier_events WHERE cashout_id=r.id AND event_slot='terminal';
   IF NOT p_replayed OR terminal.id IS NULL OR terminal.hold_event_id IS DISTINCT FROM e.id
   THEN RAISE EXCEPTION 'cashier_terminal_receipt_missing' USING ERRCODE='23514';END IF;
   PERFORM public.fn_cashier_operation_receipt(terminal.id,true);
  END IF;
 ELSE
  expected_status:=CASE e.event_kind WHEN 'approval' THEN 'approved' WHEN 'cancellation' THEN 'cancelled'
    WHEN 'decline' THEN 'rejected' ELSE 'expired' END;
  expected_release:=CASE e.event_kind WHEN 'approval' THEN 'completed' ELSE expected_status END;
  IF r.status IS DISTINCT FROM expected_status OR s.release_type IS DISTINCT FROM expected_release
    OR s.released_at IS DISTINCT FROM e.occurred_at OR r.updated_at IS DISTINCT FROM e.occurred_at
    OR r.acknowledged_at IS DISTINCT FROM (CASE WHEN e.event_kind IN('approval','decline') THEN e.occurred_at ELSE NULL::timestamptz END)
    OR r.completed_at IS DISTINCT FROM (CASE WHEN e.event_kind='approval' THEN e.occurred_at ELSE NULL::timestamptz END)
    OR r.cancelled_at IS DISTINCT FROM (CASE WHEN e.event_kind IN('cancellation','decline','expiry_refund') THEN e.occurred_at ELSE NULL::timestamptz END)
    OR (e.event_kind IN('approval','decline') AND r.agent_note IS DISTINCT FROM e.accepted_note)
  THEN RAISE EXCEPTION 'cashier_terminal_request_mismatch' USING ERRCODE='23514';END IF;
  PERFORM public.fn_cashier_assert_delivery(e.hold_event_id);
 END IF;
 expected_status:=CASE e.event_kind WHEN 'hold' THEN 'pending' WHEN 'approval' THEN 'approved'
   WHEN 'cancellation' THEN 'cancelled' WHEN 'decline' THEN 'rejected' ELSE 'expired' END;
 RETURN payload||jsonb_build_object('success',true,'replayed',p_replayed,'op_id',e.op_id,
   'request_status',expected_status,'accepted_note',e.accepted_note,'actor_wallet_after',CASE WHEN e.event_kind IN('hold','approval','cancellation') THEN round(e.wallet_after,2)::text ELSE NULL END,
   'cashier',payload,'request',jsonb_build_object('id',r.id,'club_id',r.club_id,'player_id',r.player_id,'agent_id',r.agent_id,
    'amount',round(r.amount,2)::text,'status',r.status,'created_at',r.created_at,'updated_at',r.updated_at,
    'acknowledged_at',r.acknowledged_at,'completed_at',r.completed_at,'cancelled_at',r.cancelled_at,
    'player_note',r.player_note,'agent_note',r.agent_note));
END $$;


ALTER FUNCTION public.fn_cashier_operation_receipt(p_event_id uuid, p_replayed boolean) OWNER TO postgres;

--
-- TOC entry 7210 (class 1255 OID 171543495)
-- Name: fn_cashier_player_wallet_send(uuid, uuid, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_player_wallet_send(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text, p_reason text, p_op_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE actor uuid:=auth.uid(); actor_role text; target_role text; gate jsonb; result jsonb; before_balance numeric; after_balance numeric; target_after numeric; agent_id uuid; tx uuid; context jsonb; setting text;
BEGIN
 gate:=public.fn_cashier_exact_intent_begin('cashier_player_send',p_club_id,p_op_id,jsonb_build_object('actor',actor,'club',p_club_id,'action','cashier_player_send','target',p_to_user_id,'amount',p_amount,'destination',p_destination,'reason',p_reason));
 IF gate->>'state'='return' THEN RETURN gate->'response'; END IF;
 IF p_club_id IS NULL OR p_to_user_id IS NULL OR p_amount IS NULL OR p_amount<=0 OR p_amount>1e9 OR p_amount<>round(p_amount,2) THEN RETURN jsonb_build_object('success',false,'error','Enter A Valid Send Amount And Recipient'); END IF;
 IF p_destination IS NULL OR p_destination NOT IN ('player_wallet','agent_wallet','promo_wallet') THEN RETURN jsonb_build_object('success',false,'error','Unknown Destination Wallet'); END IF;
 IF actor=p_to_user_id AND p_destination='player_wallet' THEN RETURN jsonb_build_object('success',false,'error','Choose A Different Wallet'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||p_club_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||p_club_id::text,0));
 PERFORM 1 FROM public.clubs WHERE id=p_club_id FOR UPDATE;
 PERFORM 1 FROM public.club_members WHERE club_id=p_club_id AND user_id IN (actor,p_to_user_id) ORDER BY user_id FOR UPDATE;
 actor_role:=public.fn_club_bank_role(p_club_id);
 IF actor_role IS NULL OR actor_role NOT IN ('owner','co_owner','super_agent','agent','sub_agent') THEN RETURN jsonb_build_object('success',false,'error','Your Cashier Authority Is No Longer Active'); END IF;
 IF actor<>p_to_user_id AND NOT public.fn_club_cashier_can_transact(p_club_id,actor,p_to_user_id) THEN RETURN jsonb_build_object('success',false,'error','That Member Is Not In Your Downline'); END IF;
 SELECT role INTO target_role FROM public.club_members WHERE club_id=p_club_id AND user_id=p_to_user_id AND coalesce(status,'active') IN ('active','approved');
 IF target_role IS NULL THEN RETURN jsonb_build_object('success',false,'error','Recipient Is Not An Active Member Of This Club'); END IF;
 IF (p_destination='player_wallet' AND target_role='admin') OR (p_destination<>'player_wallet' AND target_role NOT IN ('owner','co_owner','admin','super_agent','agent','sub_agent')) THEN RETURN jsonb_build_object('success',false,'error','Recipient Does Not Hold That Wallet'); END IF;
 SELECT coalesce(chip_balance,0) INTO before_balance FROM public.club_members WHERE club_id=p_club_id AND user_id=actor;
 IF before_balance IS NULL OR before_balance<p_amount THEN RETURN jsonb_build_object('success',false,'error','Insufficient Player Wallet Balance'); END IF;
 SELECT jsonb_object_agg(k,coalesce(current_setting(k,true),'')) INTO context FROM unnest(ARRAY['app.ledger_category','app.ledger_counterparty','app.ledger_counterparty_entity','app.ledger_counterparty_label','app.ledger_correlation','app.ledger_idempotency_key','app.ledger_autoskip_agents','app.ledger_autoskip_club_members','app.ledger_tournament','app.ledger_settlement']) settings(k);
 PERFORM set_config('app.ledger_tournament','',true);
 PERFORM set_config('app.ledger_settlement','',true);
 PERFORM public.fn_ca_declare_ledger('transfer','player_wallet',actor,NULL,'cashier_player_send:'||p_op_id::text,ARRAY['club_members','agents']);
 PERFORM set_config('app.ledger_correlation',p_op_id::text,true);
 UPDATE public.club_members SET chip_balance=coalesce(chip_balance,0)-p_amount,updated_at=now() WHERE club_id=p_club_id AND user_id=actor RETURNING chip_balance INTO after_balance;
 IF p_destination='player_wallet' THEN
  UPDATE public.club_members SET chip_balance=coalesce(chip_balance,0)+p_amount,updated_at=now() WHERE club_id=p_club_id AND user_id=p_to_user_id RETURNING chip_balance INTO target_after;
 ELSE
  agent_id:=public.fn_ensure_agent_row(p_club_id,p_to_user_id,target_role);
  IF p_destination='agent_wallet' THEN UPDATE public.agents SET agent_wallet_balance=coalesce(agent_wallet_balance,0)+p_amount,updated_at=now() WHERE id=agent_id RETURNING agent_wallet_balance INTO target_after;
  ELSE UPDATE public.agents SET promo_wallet_balance=coalesce(promo_wallet_balance,0)+p_amount,updated_at=now() WHERE id=agent_id RETURNING promo_wallet_balance INTO target_after; END IF;
 END IF;
 IF target_after IS NULL THEN RAISE EXCEPTION 'Recipient Credit Landed Nowhere'; END IF;
 PERFORM set_config('app.ledger_idempotency_key','',true);
 IF NOT public.fn_ca_post_leg('transfer','player_wallet',actor,p_destination,p_to_user_id,p_amount,p_club_id,'cashier_player_send:'||p_op_id::text,'Cashier Send From Player Wallet') THEN RAISE EXCEPTION 'The Transfer Journal Was Not Written'; END IF;
 FOR setting IN SELECT jsonb_object_keys(context) LOOP PERFORM set_config(setting,context->>setting,true); END LOOP;
 INSERT INTO public.chip_transactions(club_id,from_user_id,to_user_id,amount,transaction_type,notes,metadata,balance_after) VALUES(p_club_id,actor,p_to_user_id,p_amount,'peer_transfer',coalesce(p_reason,'Cashier Send Out'),jsonb_build_object('op_id',p_op_id,'source','player_wallet','destination',p_destination,'player_wallet_after',after_balance,'recipient_balance_after',target_after),after_balance) RETURNING id INTO tx;
 result:=jsonb_build_object('success',true,'replayed',false,'transaction_id',tx,'amount',p_amount,'source','player_wallet','destination',p_destination,'player_wallet_after',after_balance,'recipient_balance_after',target_after);
 RETURN public.fn_cashier_exact_intent_finish(p_op_id,result);
END
$$;


ALTER FUNCTION public.fn_cashier_player_wallet_send(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_destination text, p_reason text, p_op_id uuid) OWNER TO postgres;

--
-- TOC entry 7882 (class 1255 OID 171543490)
-- Name: fn_cashier_recipient_wallet_balances(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_recipient_wallet_balances(p_club_id uuid, p_user_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE actor uuid:=auth.uid(); actor_role text;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'Not Authenticated' USING ERRCODE='42501'; END IF;
 actor_role:=public.fn_club_bank_role(p_club_id);
 IF actor_role IS NULL OR actor_role NOT IN ('owner','co_owner','admin','super_agent','agent','sub_agent') THEN RAISE EXCEPTION 'Cashier Access Is Required' USING ERRCODE='42501'; END IF;
 IF p_user_ids IS NULL OR cardinality(p_user_ids)>25 OR EXISTS(SELECT 1 FROM unnest(p_user_ids) u WHERE u IS NULL) THEN RAISE EXCEPTION 'Choose At Most 25 Recipients' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(p_user_ids) u WHERE u<>actor AND NOT public.fn_club_cashier_can_transact(p_club_id,actor,u)) THEN RAISE EXCEPTION 'That Member Is Not In Your Downline' USING ERRCODE='42501'; END IF;
 RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('user_id',cm.user_id,
  'player_wallet',CASE WHEN cm.role<>'admin' THEN coalesce(cm.chip_balance,0) END,
  'agent_wallet',CASE WHEN cm.role IN ('owner','co_owner','admin','super_agent','agent','sub_agent') THEN coalesce(a.agent_wallet_balance,0) END,
  'promo_wallet',CASE WHEN cm.role IN ('owner','co_owner','admin','super_agent','agent','sub_agent') THEN coalesce(a.promo_wallet_balance,0) END)), '[]'::jsonb)
  FROM public.club_members cm LEFT JOIN public.agents a ON a.club_id=cm.club_id AND a.user_id=cm.user_id
  WHERE cm.club_id=p_club_id AND cm.user_id=ANY(p_user_ids) AND coalesce(cm.status,'active') IN ('active','approved'));
END
$$;


ALTER FUNCTION public.fn_cashier_recipient_wallet_balances(p_club_id uuid, p_user_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 4115 (class 1255 OID 34786015)
-- Name: fn_cashier_reconciliation_inventory(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_reconciliation_inventory(p_after_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_ttl_hours integer DEFAULT 72) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
 IF p_limit IS NULL OR p_limit<1 OR p_limit>100 OR p_ttl_hours IS NULL OR p_ttl_hours<1 OR p_ttl_hours>8760
 THEN RAISE EXCEPTION 'cashier_inventory_bounds_invalid' USING ERRCODE='22023';END IF;
 WITH unsupported AS MATERIALIZED (
  SELECT r.*,r.amount IS NOT NULL AND r.amount::text NOT IN('NaN','Infinity','-Infinity') AND r.amount>0 AND r.amount=round(r.amount,2) AS amount_valid
  FROM public.cashout_requests r WHERE r.status='pending'
   AND NOT EXISTS(SELECT 1 FROM public.accounting_cashier_events e WHERE e.cashout_id=r.id)
 ), totals AS (
  SELECT count(*) total,count(*) FILTER(WHERE NOT amount_valid) invalid_amounts,
   COALESCE(sum(amount) FILTER(WHERE amount_valid),0) known_amount,
   count(*) FILTER(WHERE created_at IS NULL OR NOT isfinite(created_at)) invalid_times,
   count(*) FILTER(WHERE created_at<transaction_timestamp()-make_interval(hours=>p_ttl_hours)) due_count FROM unsupported
 ), page AS MATERIALIZED (
  SELECT u.* FROM unsupported u WHERE p_after_id IS NULL OR u.id>p_after_id ORDER BY u.id LIMIT p_limit
 ) SELECT jsonb_build_object('contract_version',1,'scope','unverified_pending_cashout_holds','adoption_supported',false,
   'unsupported_count',t.total,'valid_amount_sum',round(t.known_amount,2)::text,'invalid_amount_count',t.invalid_amounts,
   'invalid_created_at_count',t.invalid_times,'past_ttl_count',t.due_count,'captured_at',statement_timestamp(),
   'rows',COALESCE((SELECT jsonb_agg(jsonb_build_object('cashout_id',r.id,'club_id',r.club_id,'player_id',r.player_id,
      'assigned_agent_id',r.agent_id,'amount',r.amount::text,'amount_valid',r.amount_valid,'created_at',r.created_at,
      'escrow_id',(SELECT s.id FROM public.chip_escrow s WHERE s.cashout_request_id=r.id)) ORDER BY r.id) FROM page r),'[]'::jsonb),
   'next_cursor',CASE WHEN EXISTS(SELECT 1 FROM unsupported u WHERE u.id>(SELECT id FROM page ORDER BY id DESC LIMIT 1))
     THEN (SELECT id FROM page ORDER BY id DESC LIMIT 1) ELSE NULL END)
 INTO result FROM totals t;
 RETURN result;
END $$;


ALTER FUNCTION public.fn_cashier_reconciliation_inventory(p_after_id uuid, p_limit integer, p_ttl_hours integer) OWNER TO postgres;

--
-- TOC entry 4993 (class 1255 OID 146951656)
-- Name: fn_cashier_recovery_receipts(uuid, uuid[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_recovery_receipts(p_club_id uuid, p_operation_ids uuid[] DEFAULT '{}'::uuid[], p_ticket_keys text[] DEFAULT '{}'::text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_operations jsonb;
  v_tickets jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not Authenticated' USING ERRCODE='42501'; END IF;
  IF p_club_id IS NULL OR p_operation_ids IS NULL OR p_ticket_keys IS NULL
     OR cardinality(p_operation_ids) + cardinality(p_ticket_keys) > 25
     OR EXISTS (SELECT 1 FROM unnest(p_ticket_keys) k WHERE k IS NULL OR length(k)>300) THEN
    RAISE EXCEPTION 'Choose At Most 25 Original Requests' USING ERRCODE='22023';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'operation_id', i.operation_id, 'receipt', i.receipt,
    'intent', i.operation_intent)), '[]'::jsonb)
    INTO v_operations FROM public.cashier_rpc_operation_intents i
   WHERE i.operation_id=ANY(p_operation_ids) AND i.actor_user_id=v_actor
     AND i.club_id=p_club_id AND i.receipt IS NOT NULL;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'ticket_key', t.metadata->>'idempotency_key',
    'receipt', jsonb_build_object('success',true,'replayed',true,
      'ticket_id',t.metadata->>'ticket_id','transaction_id',t.id))), '[]'::jsonb)
    INTO v_tickets FROM public.chip_transactions t
   WHERE t.club_id=p_club_id AND t.from_user_id=v_actor
     AND t.metadata ? 'idempotency_key'
     AND (t.transaction_type='tournament_ticket_issue'
          OR (t.transaction_type='peer_transfer' AND t.notes ILIKE 'Tournament ticket issued%'))
     AND t.metadata->>'ticket_id' IS NOT NULL
     AND t.metadata->>'idempotency_key'=ANY(p_ticket_keys);
  RETURN jsonb_build_object('operations',v_operations,'tickets',v_tickets);
END
$$;


ALTER FUNCTION public.fn_cashier_recovery_receipts(p_club_id uuid, p_operation_ids uuid[], p_ticket_keys text[]) OWNER TO postgres;

