CREATE FUNCTION public.fn_cashier_send_chips(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  /* RETIRED 2026-10-02 (20261002140203). A peer wallet move that named no
     counterparty. It required auth.uid() but EXECUTE was granted only to
     service_role, so no caller could reach it. The send is fn_club_bank_send
     / fn_agent_wallet_send. Nothing is moved here. */
  RETURN jsonb_build_object('success', false, 'error', 'fn_cashier_send_chips_retired',
    'message', 'Use the Club Bank send (fn_club_bank_send) or the agent wallet send');
END;
$$;


ALTER FUNCTION public.fn_cashier_send_chips(p_club_id uuid, p_to_user_id uuid, p_amount numeric, p_reason text, p_idempotency_key text) OWNER TO postgres;

--
-- TOC entry 3341 (class 1255 OID 54141960)
-- Name: fn_cashier_statement_downline(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_statement_downline(p_club_id uuid, p_viewer uuid) RETURNS uuid[]
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH RECURSIVE downline AS (
    SELECT p_viewer AS user_id
    UNION
    SELECT edge.child
      FROM public.fn_club_active_cashier_edges(p_club_id) edge
      JOIN downline d ON edge.parent = d.user_id
  )
  SELECT array_agg(user_id ORDER BY user_id)
    FROM downline WHERE user_id IS NOT NULL
$$;


