--
-- TOC entry 9465 (class 1255 OID 54141995)
-- Name: fn_cashier_statement_export_cancel(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_statement_export_cancel(p_export_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_deleted integer := 0;
BEGIN
  IF v_user IS NULL OR p_export_id IS NULL THEN
    RETURN false;
  END IF;

  DELETE FROM public.ca_cashier_statement_exports cancelled_job
   USING (
     SELECT owned_job.id
       FROM public.ca_cashier_statement_exports owned_job
      WHERE owned_job.id = p_export_id
        AND owned_job.user_id = v_user
      FOR UPDATE SKIP LOCKED
   ) owned
   WHERE cancelled_job.id = owned.id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  PERFORM public.fn_cashier_statement_prune_expired();

  RETURN v_deleted = 1;
END;
$$;


