--
-- TOC entry 9114 (class 1255 OID 54141974)
-- Name: fn_cashier_statement_scope(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_statement_scope(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_viewer uuid := auth.uid();
  v_role text;
  v_scope text := 'none';
  v_ids uuid[];
  v_reason text;
BEGIN
  IF v_viewer IS NULL THEN
    v_reason := 'sign_in_required';
  ELSIF p_club_id IS NULL THEN
    v_reason := 'club_required';
  ELSE
    v_role := public.fn_club_bank_role(p_club_id, v_viewer);
    IF v_role IS NULL THEN
      v_reason := 'not_an_active_member';
    ELSIF v_role IN ('owner', 'co_owner', 'admin') THEN
      v_scope := 'all';
    ELSIF v_role IN ('super_agent', 'agent', 'sub_agent') THEN
      v_scope := 'downline';
      v_ids := public.fn_cashier_statement_downline(p_club_id, v_viewer);
    ELSE
      v_scope := 'self';
    END IF;
  END IF;
  RETURN jsonb_build_object(
    'authorized', v_scope <> 'none', 'reason', v_reason,
    'role', CASE WHEN v_scope <> 'none' THEN v_role END,
    'scope', v_scope, 'viewer', v_viewer,
    'fingerprint', md5(concat_ws('|', v_viewer::text, p_club_id::text,
      v_scope, array_to_string(v_ids, ',')))
  );
END
$$;


ALTER FUNCTION public.fn_cashier_statement_scope(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 46593 (class 0 OID 0)
-- Dependencies: 9114
-- Name: FUNCTION fn_cashier_statement_scope(p_club_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_cashier_statement_scope(p_club_id uuid) IS 'Cashier statement authorization, identical to fn_club_trade_ledger: owner/co_owner/admin/super_agent all, agent/sub_agent recursive downline, other active members self, otherwise none. The fingerprint changes with viewer, club, scope or downline.';


--
-- TOC entry 8059 (class 1255 OID 54141985)
-- Name: fn_cashier_statement_totals(uuid, timestamp with time zone, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashier_statement_totals(p_club_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_filters jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_viewer uuid := auth.uid();
  v_scope jsonb;
  v_filters jsonb;
  v_totals jsonb;
BEGIN
  v_scope := public.fn_cashier_statement_scope(p_club_id);
  IF NOT coalesce((v_scope ->> 'authorized')::boolean, false)
     OR v_viewer IS NULL
     OR (v_scope ->> 'viewer')::uuid IS DISTINCT FROM v_viewer THEN
    RETURN jsonb_build_object(
      'authorized', false,
      'reason', coalesce(v_scope ->> 'reason', 'not_authorized')
    );
  END IF;

  v_filters := public.fn_cashier_statement_filters(p_from, p_to, p_filters);

  -- Plain SUM / COUNT over the page's own predicates (the totals mode of
  -- the one row query): no ORDER BY, no LIMIT, no labels unless the
  -- counterparty text filter needs them. O(range), in its own call, so a
  -- timeout here (57014) never costs the page its rows.
  SELECT jsonb_build_object(
           'in', to_char(round(coalesce(sum(t.entry_amount) FILTER (WHERE t.entry_direction = 'in'), 0), 2), 'FM999999999999999990.00'),
           'out', to_char(round(coalesce(sum(t.entry_amount) FILTER (WHERE t.entry_direction = 'out'), 0), 2), 'FM999999999999999990.00'),
           'managed', to_char(round(coalesce(sum(t.entry_amount) FILTER (WHERE t.entry_direction = 'managed'), 0), 2), 'FM999999999999999990.00'),
           'count', coalesce(sum((t.entry ->> 'count')::bigint), 0))
    INTO v_totals
    FROM public.fn_cashier_statement_rows(
           p_club_id, v_viewer, v_scope ->> 'scope', p_from, p_to, v_filters,
           NULL, NULL, NULL, 0) t;

  RETURN jsonb_build_object(
    'authorized', true,
    'scope', v_scope ->> 'scope',
    'range', jsonb_build_object(
      'from', to_char(p_from AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'to', to_char(p_to AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),
    'filters', v_filters,
    'totals', v_totals,
    'generated_at', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
  );
END;
$$;


