--
-- TOC entry 4422 (class 1255 OID 25591073)
-- Name: fn_cashout_seat_occupancy(uuid, uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashout_seat_occupancy(p_user_id uuid, p_table_id uuid, p_seat_number integer, p_occupancy_id uuid, p_leave_mode text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_tournament uuid;
  v_seat record;
  v_previous public.seat_cashout_receipts%ROWTYPE;
  v_result jsonb;
  v_effective_mode text;
  v_previous_authority text;
BEGIN
  IF p_user_id IS NULL OR p_table_id IS NULL OR p_seat_number IS NULL
     OR p_occupancy_id IS NULL THEN
    RAISE EXCEPTION 'CASHOUT_OCCUPANCY_REQUIRED' USING ERRCODE = '22023';
  END IF;
  -- The engine owns the live-hand boundary. Knowing an occupancy UUID or
  -- owning the seat cannot authorize a direct browser cashout mid-hand.
  IF NOT coalesce(public.fn_caller_is_engine(),false) THEN
    RAISE EXCEPTION 'Engine authority required' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('table_cap:' || p_user_id::text,0));
  SELECT * INTO v_previous FROM public.seat_cashout_receipts
   WHERE occupancy_id = p_occupancy_id;
  IF FOUND THEN
    IF v_previous.user_id <> p_user_id OR v_previous.table_id <> p_table_id
       OR v_previous.seat_number <> p_seat_number THEN
      RAISE EXCEPTION 'CASHOUT_OCCUPANCY_SCOPE_MISMATCH' USING ERRCODE = '22023';
    END IF;
    RETURN v_previous.receipt;
  END IF;

  SELECT tournament_id INTO v_tournament FROM public.tables WHERE id=p_table_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'CASHOUT_TABLE_NOT_FOUND' USING ERRCODE = '22023';
  END IF;
  IF v_tournament IS NOT NULL THEN
    PERFORM 1 FROM public.tournaments WHERE id=v_tournament FOR NO KEY UPDATE;
  END IF;
  -- Diamond hands lock table -> wallet -> seat. Retain that order for exits.
  IF EXISTS(SELECT 1 FROM public.tables t JOIN public.clubs c ON c.id=t.club_id
            WHERE t.id=p_table_id AND c.asset='diamonds') THEN
    PERFORM 1 FROM public.tables WHERE id=p_table_id FOR UPDATE;
    PERFORM 1 FROM public.profiles WHERE id=p_user_id FOR UPDATE;
  END IF;
  SELECT id,seat_number,occupancy_id INTO v_seat FROM public.table_seats
   WHERE occupancy_id=p_occupancy_id AND table_id=p_table_id AND user_id=p_user_id
     AND seat_number=p_seat_number AND left_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'CASHOUT_STALE_OCCUPANCY' USING ERRCODE = '22023';
  END IF;

  -- This lock and the canonical function's locks are in the same transaction.
  -- A concurrent seat replacement cannot cross the identity check.
  v_effective_mode := p_leave_mode;
  -- A forced request survives restart and cannot leak onto a later occupancy.
  IF p_leave_mode IS DISTINCT FROM 'vpip_evicted' AND EXISTS (SELECT 1 FROM public.seat_departure_requests
    WHERE occupancy_id=p_occupancy_id AND user_id=p_user_id AND table_id=p_table_id
      AND seat_number=p_seat_number AND leave_mode='forced') THEN
    v_effective_mode := 'forced';
  END IF;
  -- Classification is derived from retained, occupancy-bound authority.
  -- Never inherit another operation's transaction-local admin marker.
  v_previous_authority := current_setting('app.cash_exit_authority',true);
  PERFORM set_config('app.cash_exit_authority',
    CASE WHEN v_effective_mode='forced' AND EXISTS(
      SELECT 1 FROM public.seat_admin_departure_authorizations
       WHERE occupancy_id=p_occupancy_id AND user_id=p_user_id
         AND table_id=p_table_id AND seat_number=p_seat_number)
    THEN 'club_admin' ELSE '' END,true);
  v_result := public.atomic_seat_cashout_locked(
    p_user_id,p_table_id,p_seat_number,v_effective_mode);
  PERFORM set_config('app.cash_exit_authority',coalesce(v_previous_authority,''),true);
  IF v_result->>'ok' IS DISTINCT FROM 'true'
     OR v_result->>'reason' IS NOT NULL
     OR (v_result->>'seat_number')::integer IS DISTINCT FROM p_seat_number
     OR v_result->>'idempotency_key' IS DISTINCT FROM 'cashout:occupancy:'||p_occupancy_id::text THEN
    RAISE EXCEPTION 'CASHOUT_UNCONFIRMED_OUTCOME' USING ERRCODE = '22023';
  END IF;
  -- The canonical transaction writes this receipt for every ingress.
  -- The wrapper owns request identity and replay, never a second receipt write.
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_cashout_seat_occupancy(p_user_id uuid, p_table_id uuid, p_seat_number integer, p_occupancy_id uuid, p_leave_mode text) OWNER TO postgres;

--
-- TOC entry 6139 (class 1255 OID 17762565)
-- Name: fn_cashout_seats_for_closing_table(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cashout_seats_for_closing_table(p_table_id uuid, p_reason text DEFAULT 'table closed'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tournament uuid;
BEGIN
  SELECT tournament_id INTO v_tournament FROM public.tables WHERE id=p_table_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'CASHOUT_TABLE_NOT_FOUND' USING ERRCODE='22023';
  END IF;
  IF v_tournament IS NOT NULL THEN
    RETURN jsonb_build_object('ok',true,'skipped','tournament_table');
  END IF;
  -- This read-only assertion is also reached from authorized administrator
  -- close RPCs. It must not require an engine JWT when it moves no money.
  IF EXISTS (SELECT 1 FROM public.table_seats WHERE table_id=p_table_id AND left_at IS NULL) THEN
    RAISE EXCEPTION 'CASH_TABLE_CLOSE_REQUIRES_ENGINE_DEPARTURES' USING ERRCODE='55000';
  END IF;
  RETURN jsonb_build_object('ok',true,'players_paid',0,
    'chips_returned',0,'reason_text',coalesce(p_reason,'table closed'));
END;
$$;


ALTER FUNCTION public.fn_cashout_seats_for_closing_table(p_table_id uuid, p_reason text) OWNER TO postgres;

--
-- TOC entry 4695 (class 1255 OID 24464218)
-- Name: fn_cast_tournament_deal_vote(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cast_tournament_deal_vote(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_inserted integer;
  v_wake_id bigint;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE='42501';
  END IF;
  PERFORM 1
    FROM public.tournaments t
   WHERE t.id=p_tournament_id
     AND t.status='RUNNING'
     AND coalesce(t.final_table_deal_enabled,false)
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','deal_vote_not_open');
  END IF;
  PERFORM 1
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND tp.user_id=v_user_id
     AND tp.status IN ('registered','playing')
     AND tp.eliminated_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','voter_not_alive');
  END IF;

  INSERT INTO public.tournament_deal_votes(tournament_id,user_id)
  VALUES (p_tournament_id,v_user_id)
  ON CONFLICT (tournament_id,user_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  -- Emit on exact replay too. This closes the rolling-deploy case where an old
  -- client inserted the vote directly but no durable wake accompanied it.
  v_wake_id := public.fn_emit_tournament_manager_wake(p_tournament_id,'deal_vote');
  RETURN jsonb_build_object(
    'ok',true,'voted',true,'already',v_inserted=0,'wake_id',v_wake_id);
END;
$$;


ALTER FUNCTION public.fn_cast_tournament_deal_vote(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 3955 (class 1255 OID 26587209)
-- Name: fn_cast_tournament_deal_vote(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cast_tournament_deal_vote(p_tournament_id uuid, p_proposal_id uuid, p_expected_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_state jsonb; p public.tournament_deal_proposals%ROWTYPE;
  v_inserted integer; v_wake bigint;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
  IF p_expected_actor_id IS NULL OR v_actor IS DISTINCT FROM p_expected_actor_id THEN
    RETURN jsonb_build_object('ok',false,'reason','actor_mismatch');
  END IF;
  IF NOT public.fn_ca_tournament_deal_proposals_active() THEN
    RETURN jsonb_build_object('ok',false,'reason','proposal_authority_not_active');
  END IF;
  -- Reject outsiders before acquiring the global terminal lock; membership
  -- is checked again against the locked proposal shares below.
  IF NOT EXISTS(SELECT 1 FROM public.tournament_players WHERE tournament_id=p_tournament_id
    AND user_id=v_actor AND status::text='playing' AND eliminated_at IS NULL) THEN
    RETURN jsonb_build_object('ok',false,'reason','voter_not_alive');
  END IF;
  v_state:=public.fn_ca_tournament_deal_snapshot(p_tournament_id);
  IF (v_state->>'ok')::boolean IS NOT TRUE THEN RETURN v_state; END IF;
  SELECT * INTO p FROM public.tournament_deal_proposals WHERE id=p_proposal_id AND tournament_id=p_tournament_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','proposal_not_found'); END IF;
  IF p.revision IS DISTINCT FROM v_state->>'revision' OR p.snapshot IS DISTINCT FROM v_state->'snapshot' THEN
    RETURN jsonb_build_object('ok',false,'reason','proposal_stale');
  END IF;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p.snapshot->'shares')x WHERE x->>'user_id'=v_actor::text) THEN
    RETURN jsonb_build_object('ok',false,'reason','voter_not_alive');
  END IF;
  INSERT INTO public.tournament_deal_proposal_consents(proposal_id,user_id) VALUES(p.id,v_actor)
    ON CONFLICT(proposal_id,user_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  INSERT INTO public.tournament_deal_votes(tournament_id,user_id) VALUES(p_tournament_id,v_actor)
    ON CONFLICT(tournament_id,user_id) DO NOTHING;
  v_wake:=public.fn_emit_tournament_manager_wake(p_tournament_id,'deal_vote');
  RETURN jsonb_build_object('ok',true,'actor_id',v_actor,'proposal_id',p.id,'revision',p.revision,
    'voted',true,'already',v_inserted=0,'wake_id',v_wake);
END;
$$;


ALTER FUNCTION public.fn_cast_tournament_deal_vote(p_tournament_id uuid, p_proposal_id uuid, p_expected_actor_id uuid) OWNER TO postgres;

--
-- TOC entry 6992 (class 1255 OID 24465291)
-- Name: fn_certify_tournament_finish(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_certify_tournament_finish(p_tournament_id uuid, p_winner_user_id uuid, p_source text DEFAULT 'engine'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_finish public.tournament_finish_receipts%ROWTYPE;
  v_ready jsonb;
BEGIN
  IF p_tournament_id IS NULL OR p_winner_user_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'certified',false,'reason','missing_ids');
  END IF;
  SELECT * INTO v_t FROM public.tournaments
   WHERE id = p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'certified',false,'reason','tournament_not_found');
  END IF;
  SELECT * INTO v_finish FROM public.tournament_finish_receipts
   WHERE tournament_id = p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'certified',false,
      'reason','finish_certificate_missing','status',v_t.status,'rows_updated',0);
  END IF;
  IF v_finish.winner_user_id IS DISTINCT FROM p_winner_user_id THEN
    RETURN jsonb_build_object('ok',false,'certified',false,
      'reason','canonical_winner_conflict','winner_user_id',v_finish.winner_user_id,
      'finish_kind',v_finish.finish_kind,'status',v_t.status,'rows_updated',0);
  END IF;
  IF v_t.status <> 'COMPLETED' THEN
    RETURN jsonb_build_object('ok',false,'certified',false,
      'reason','domain_settlement_required','winner_user_id',v_finish.winner_user_id,
      'finish_kind',v_finish.finish_kind,'status',v_t.status,'rows_updated',0,
      'already_completed',false);
  END IF;
  IF v_finish.certified_at IS NULL OR v_finish.completed_at IS NULL
     OR v_finish.evidence IS NULL THEN
    RETURN jsonb_build_object('ok',false,'certified',false,
      'reason','completed_without_certificate','winner_user_id',v_finish.winner_user_id,
      'finish_kind',v_finish.finish_kind,'status',v_t.status,'rows_updated',0,
      'already_completed',true);
  END IF;

  -- Re-read the proof as a defence against privileged post-completion drift.
  -- The atomic domain migrations freeze their plan, results and obligation
  -- ledger, so this is a pure verification pass and can never repair money.
  v_ready := public.fn_tournament_finish_readiness(p_tournament_id,p_winner_user_id);
  IF COALESCE((v_ready->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN jsonb_build_object('ok',false,'certified',false,
      'reason','certificate_evidence_no_longer_valid','winner_user_id',v_finish.winner_user_id,
      'finish_kind',v_finish.finish_kind,'status',v_t.status,'rows_updated',0,
      'already_completed',true,'evidence',v_ready);
  END IF;

  RETURN jsonb_build_object('ok',true,'certified',true,'reason',NULL,
    'status','COMPLETED','rows_updated',0,'already_completed',true,
    'winner_user_id',p_winner_user_id,'finish_kind',v_finish.finish_kind,
    'evidence',v_finish.evidence,
    'requested_by',COALESCE(NULLIF(btrim(p_source),''),'engine'));
END;
$$;


ALTER FUNCTION public.fn_certify_tournament_finish(p_tournament_id uuid, p_winner_user_id uuid, p_source text) OWNER TO postgres;

--
-- TOC entry 4938 (class 1255 OID 34785896)
-- Name: fn_change_push_subscription_ownership(uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_change_push_subscription_ownership(p_user_id uuid, p_subscription jsonb, p_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE endpoint_value text:=p_subscription->>'endpoint';
 transport_value text:=p_subscription->>'transport'; platform_value text:=p_subscription->>'platform';
 auth_value text:=p_subscription->>'auth'; key_value text:=p_subscription->>'p256dh';
 device_value text:=p_subscription->>'device_id'; replaces_value text:=p_subscription->>'replaces_endpoint';
 displaced uuid[]:='{}'; incumbent public.push_subscriptions%ROWTYPE;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_user_id IS NULL OR p_enabled IS NULL OR jsonb_typeof(p_subscription) IS DISTINCT FROM 'object'
    OR endpoint_value IS NULL OR length(endpoint_value)<1 OR length(endpoint_value)>4096
 THEN RAISE EXCEPTION 'invalid_push_subscription' USING ERRCODE='22023'; END IF;
 -- Enrollment is rare and bounded. One transaction lock also orders device
 -- replacement and logout, avoiding reversed endpoint/device lock ordering.
 PERFORM pg_advisory_xact_lock(hashtextextended('push_subscription_ownership:v1',0));
 IF p_enabled THEN
   IF transport_value IS NULL OR transport_value NOT IN('webpush','fcm')
      OR (platform_value IS NOT NULL AND platform_value NOT IN('web','ios','android'))
      OR (transport_value='webpush' AND (COALESCE(auth_value,'')='' OR COALESCE(key_value,'')=''))
      OR (device_value IS NOT NULL AND device_value !~ '^[A-Za-z0-9-]{8,64}$')
   THEN RAISE EXCEPTION 'invalid_push_subscription' USING ERRCODE='22023'; END IF;
   -- The caller already validates endpoint hosts, native token shape and key
   -- lengths. This service-only transaction repeats ownership proof while
   -- holding the same lock that protects retirement and replacement.
   FOR incumbent IN SELECT * FROM public.push_subscriptions
     WHERE endpoint=endpoint_value AND is_active AND user_id<>p_user_id ORDER BY id FOR UPDATE LOOP
     IF incumbent.transport IS DISTINCT FROM transport_value OR
        (transport_value='webpush' AND incumbent.auth IS DISTINCT FROM auth_value)
     THEN RAISE EXCEPTION 'push_subscription_possession_mismatch' USING ERRCODE='23514'; END IF;
     displaced:=array_append(displaced,incumbent.user_id);
   END LOOP;
   UPDATE public.push_subscriptions SET is_active=false,last_failure_reason='reassigned_to_other_user',updated_at=now()
     WHERE endpoint=endpoint_value AND is_active AND user_id<>p_user_id;
   IF device_value IS NOT NULL THEN
     UPDATE public.push_subscriptions SET is_active=false,last_failure_reason='superseded_same_device',updated_at=now()
       WHERE user_id=p_user_id AND device_id=device_value AND is_active AND endpoint<>endpoint_value;
   END IF;
   IF replaces_value IS NOT NULL AND replaces_value<>endpoint_value THEN
     UPDATE public.push_subscriptions SET is_active=false,last_failure_reason='superseded',updated_at=now()
       WHERE user_id=p_user_id AND endpoint=replaces_value AND is_active;
   END IF;
   INSERT INTO public.push_subscriptions(user_id,endpoint,p256dh,auth,transport,platform,user_agent,device_label,
     device_id,is_active,failure_count,last_failure_reason,updated_at)
   VALUES(p_user_id,endpoint_value,key_value,auth_value,transport_value,platform_value,
     left(p_subscription->>'user_agent',500),left(p_subscription->>'device_label',120),device_value,true,0,NULL,now())
   ON CONFLICT(user_id,endpoint) DO UPDATE SET p256dh=EXCLUDED.p256dh,auth=EXCLUDED.auth,transport=EXCLUDED.transport,
     platform=EXCLUDED.platform,user_agent=EXCLUDED.user_agent,device_label=EXCLUDED.device_label,
     device_id=EXCLUDED.device_id,is_active=true,failure_count=0,last_failure_reason=NULL,updated_at=EXCLUDED.updated_at;
   INSERT INTO public.notification_preferences(user_id,push_enabled,browser_push,updated_at)
     VALUES(p_user_id,true,true,now()) ON CONFLICT(user_id) DO UPDATE
     SET push_enabled=true,browser_push=true,updated_at=EXCLUDED.updated_at;
 ELSE
   UPDATE public.push_subscriptions SET is_active=false,updated_at=now()
     WHERE user_id=p_user_id AND endpoint=endpoint_value AND is_active;
   IF NOT EXISTS(SELECT 1 FROM public.push_subscriptions WHERE user_id=p_user_id AND is_active) THEN
     INSERT INTO public.notification_preferences(user_id,push_enabled,updated_at) VALUES(p_user_id,false,now())
       ON CONFLICT(user_id) DO UPDATE SET push_enabled=false,updated_at=EXCLUDED.updated_at;
   END IF;
 END IF;
 RETURN jsonb_build_object('schema_version',1,'success',true,'user_id',p_user_id,
   'endpoint',endpoint_value,'enabled',p_enabled,'displaced_user_ids',to_jsonb(displaced));
END $_$;


ALTER FUNCTION public.fn_change_push_subscription_ownership(p_user_id uuid, p_subscription jsonb, p_enabled boolean) OWNER TO postgres;

