COMMENT ON FUNCTION public.fn_chip_integrity_report() IS 'The five chip-integrity questions worth paging on, added 2026-08-26. Replaces reading 575 nightly criticals about a frozen table, which is what hid a 115-day ledger outage. Page on any critical row.';


--
-- TOC entry 3620 (class 1255 OID 14255294)
-- Name: fn_chip_ledger_split_report(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_chip_ledger_split_report() RETURNS TABLE(metric text, value numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH per_user AS (
    SELECT cm.user_id,
           SUM(cm.chip_balance)::numeric        AS club_chips,
           COALESCE(MAX(w.balance), 0)::numeric AS global_chips
      FROM club_members cm
      JOIN clubs c ON c.id = cm.club_id AND c.is_union = false
      LEFT JOIN wallets w
        ON w.user_id = cm.user_id AND w.wallet_type = 'PLAYER'
     WHERE cm.status IN ('approved','active')
     GROUP BY cm.user_id
  )
  SELECT 'users_total',            count(*)::numeric                                              FROM per_user
  UNION ALL
  SELECT 'bought_but_cannot_play', count(*) FILTER (WHERE club_chips > 0 AND global_chips = 0)::numeric FROM per_user
  UNION ALL
  SELECT 'won_but_cannot_cashout', count(*) FILTER (WHERE global_chips > 0 AND club_chips = 0)::numeric FROM per_user
  UNION ALL
  SELECT 'total_club_chips',       COALESCE(round(sum(club_chips)), 0)                            FROM per_user
  UNION ALL
  SELECT 'total_global_chips',     COALESCE(round(sum(global_chips)), 0)                          FROM per_user
  UNION ALL
  SELECT 'ledger_gap',             COALESCE(round(sum(global_chips) - sum(club_chips)), 0)        FROM per_user;
$$;


ALTER FUNCTION public.fn_chip_ledger_split_report() OWNER TO postgres;

--
-- TOC entry 4960 (class 1255 OID 31385427)
-- Name: fn_choice_act(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_choice_act(p_round_id uuid, p_action text, p_cell integer, p_expected_step integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE r public.diamond_choice_rounds; n integer; safe boolean; v_pay numeric:=0; v_cents numeric; v_floor numeric; v_roll numeric;
BEGIN
 IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Sign In To Play'); END IF;
 SELECT * INTO r FROM public.diamond_choice_rounds WHERE id=p_round_id AND user_id=auth.uid();
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','That Round Could Not Be Found'); END IF;
 -- Same config, pool, wallet, then round order as admission. The next state
 -- version is a compare-and-swap, so a delayed duplicate cannot reveal twice.
 PERFORM 1 FROM public.diamond_game_configs WHERE host_id=r.host_id AND game=r.game FOR UPDATE;
 PERFORM 1 FROM public.diamond_game_pools WHERE host_id=r.host_id AND game=r.game FOR UPDATE;
 PERFORM public.fn_diamond_game_cover_lock(r.host_id,r.host_kind);
 SELECT * INTO r FROM public.diamond_choice_rounds WHERE id=p_round_id FOR UPDATE;
 IF r.status<>'open' THEN RETURN public.fn_choice_result(r); END IF;
 n:=cardinality(r.picked);
 IF p_expected_step IS DISTINCT FROM n THEN RETURN public.fn_choice_result(r); END IF;
 IF public.fn_platform_frozen() THEN RETURN jsonb_build_object('ok',false,'error','The Platform Is In Its Maintenance Break'); END IF;
 IF p_action='pick' THEN
  IF p_cell IS NULL OR p_cell<0 OR p_cell>24 OR p_cell=ANY(r.picked) OR (r.game='crossing' AND p_cell<>n) THEN
   RETURN jsonb_build_object('ok',false,'error','Choose An Unopened Tile'); END IF;
  IF r.game='mines' THEN
   -- A round sealed under contract 4 deals its board here, around the first pick, so that pick is always a gem.
   IF n=0 AND r.payout_version>=4 AND cardinality(r.mine_cells)=0 THEN r.mine_cells:=public.fn_choice_board_v4(r.server_seed,r.client_seed,r.nonce,r.mode::integer,p_cell); END IF;
   safe:=NOT(p_cell=ANY(r.mine_cells));
  ELSIF r.payout_version=7 THEN safe:=public.fn_choice_road_coin_v7(r.server_seed,r.client_seed,r.nonce,n+1);
  ELSIF r.payout_version=6 THEN safe:=public.fn_choice_road_coin_v6(r.server_seed,r.client_seed,r.nonce,n+1);
  ELSIF r.payout_version=5 THEN safe:=(r.road_roll::numeric+1)<=public.fn_choice_road_probability_v5(r.prizes,n+1,r.minimum_payout_chips)*281474976710656;
  ELSE safe:=(r.road_roll::numeric+1)*(r.prizes[n+1]-r.minimum_payout_chips) <= (r.bet_chips*.8-r.minimum_payout_chips)*281474976710656; END IF;
  r.picked:=array_append(r.picked,p_cell); n:=n+1;
  IF NOT safe THEN r.status:='lost';
  ELSIF n=r.max_steps THEN r.status:='cashed'; END IF;
 ELSIF p_action='cashout' AND n>0 THEN r.status:='cashed';
 ELSE RETURN jsonb_build_object('ok',false,'error','Make Your First Move Before Cashing Out'); END IF;
 IF r.status='lost' THEN v_pay:=CASE WHEN r.payout_version IN (5,6,7) THEN public.fn_choice_loss_floor_v5(r.prizes,n-1,r.minimum_payout_chips) ELSE r.minimum_payout_chips END; END IF;
 IF r.status='cashed' THEN
  v_cents:=r.prizes[n]*100;
  v_floor:=floor(v_cents);
  -- An independent sealed draw rounds fractions only AFTER the stopping
  -- decision. Always rounding down would silently add another house edge.
  v_roll:=('x'||substr(encode(extensions.hmac(r.client_seed||':'||r.nonce||':rounding:'||n,r.server_seed,'sha256'),'hex'),1,12))::bit(48)::bigint;
  v_pay:=(v_floor+CASE WHEN (v_roll+1)<= (v_cents-v_floor)*281474976710656 THEN 1 ELSE 0 END)/100;
  IF v_pay>r.reserved_chips THEN RAISE EXCEPTION 'Prize Exceeds Its Reservation'; END IF;
 END IF;
 IF r.status<>'open' THEN
  IF v_pay>r.reserved_chips THEN RAISE EXCEPTION 'Prize Exceeds Its Reservation'; END IF;
  UPDATE public.diamond_game_pools SET reserved_chips=reserved_chips-r.reserved_chips,
   chips_paid=chips_paid+v_pay,updated_at=now() WHERE host_id=r.host_id AND game=r.game;
  IF v_pay>0 THEN
   PERFORM public.fn_diamond_game_pay_chips(r.game||'_prize',r.host_id,r.host_kind,r.club_id,r.user_id,v_pay,'choice-prize:'||r.id,
    'Diamond Game Prize',jsonb_build_object('game',r.game,'round_id',r.id,'host_id',r.host_id,'minimum_payout_chips',r.minimum_payout_chips,'result',r.status));
  END IF;
 END IF;
 UPDATE public.diamond_choice_rounds SET mine_cells=r.mine_cells,picked=r.picked,status=r.status,payout_chips=v_pay,
  settled_at=CASE WHEN r.status<>'open' THEN clock_timestamp() END WHERE id=r.id RETURNING * INTO r;
 RETURN public.fn_choice_result(r);
END $$;


ALTER FUNCTION public.fn_choice_act(p_round_id uuid, p_action text, p_cell integer, p_expected_step integer) OWNER TO postgres;

--
-- TOC entry 4721 (class 1255 OID 31385423)
-- Name: fn_choice_board(text, text, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_choice_board(p_server text, p_client text, p_nonce bigint, p_mines integer) RETURNS integer[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE cells integer[]:=ARRAY(SELECT generate_series(0,24)); i integer; j integer; temp integer; cursor integer:=0; v bigint; lim bigint; out integer[];
BEGIN
 IF p_mines NOT IN (5,6,10,15) THEN RAISE EXCEPTION 'Choose A Mine Count'; END IF;
 FOR i IN REVERSE 25..2 LOOP
  lim:=(4294967296::bigint/i)*i;
  LOOP
   v:=('x'||substr(encode(extensions.hmac(p_client||':'||p_nonce||':board:'||cursor,p_server,'sha256'),'hex'),1,8))::bit(32)::bigint;
   cursor:=cursor+1; EXIT WHEN v<lim;
  END LOOP;
  j:=(v%i)::integer+1; temp:=cells[i]; cells[i]:=cells[j]; cells[j]:=temp;
 END LOOP;
 SELECT array_agg(x ORDER BY x) INTO out FROM unnest(cells[1:p_mines]) x;
 RETURN out;
END $$;


ALTER FUNCTION public.fn_choice_board(p_server text, p_client text, p_nonce bigint, p_mines integer) OWNER TO postgres;

--
-- TOC entry 5151 (class 1255 OID 53111813)
-- Name: fn_choice_board_v4(text, text, bigint, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_choice_board_v4(p_server text, p_client text, p_nonce bigint, p_mines integer, p_first integer) RETURNS integer[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE cells integer[]; i integer; j integer; temp integer; cursor integer:=0; v bigint; lim bigint; out integer[];
BEGIN
 IF p_mines NOT IN (5,6,10,15) THEN RAISE EXCEPTION 'Choose A Mine Count'; END IF;
 IF p_first IS NULL OR p_first<0 OR p_first>24 THEN RAISE EXCEPTION 'Choose A First Tile'; END IF;
 cells:=ARRAY(SELECT x FROM generate_series(0,24) x WHERE x<>p_first ORDER BY x);
 FOR i IN REVERSE 24..2 LOOP
  lim:=(4294967296::bigint/i)*i;
  LOOP
   v:=('x'||substr(encode(extensions.hmac(p_client||':'||p_nonce||':board:'||p_first||':'||cursor,p_server,'sha256'),'hex'),1,8))::bit(32)::bigint;
   cursor:=cursor+1; EXIT WHEN v<lim;
  END LOOP;
  j:=(v%i)::integer+1; temp:=cells[i]; cells[i]:=cells[j]; cells[j]:=temp;
 END LOOP;
 SELECT array_agg(x ORDER BY x) INTO out FROM unnest(cells[1:p_mines]) x;
 RETURN out;
END $$;


ALTER FUNCTION public.fn_choice_board_v4(p_server text, p_client text, p_nonce bigint, p_mines integer, p_first integer) OWNER TO postgres;

--
-- TOC entry 8216 (class 1255 OID 31385420)
-- Name: fn_choice_choose(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_choice_choose(n integer, k integer) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE v numeric:=1; i integer;
BEGIN
 IF k<0 OR k>n THEN RETURN 0; END IF;
 FOR i IN 1..LEAST(k,n-k) LOOP v:=v*(n-i+1)/i; END LOOP;
 RETURN round(v);
END $$;


ALTER FUNCTION public.fn_choice_choose(n integer, k integer) OWNER TO postgres;

--
-- TOC entry 6858 (class 1255 OID 31385451)
-- Name: fn_choice_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_choice_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND OLD.status='open' THEN
  IF (to_jsonb(NEW)-ARRAY['picked','status','payout_chips','settled_at']) =
     (to_jsonb(OLD)-ARRAY['picked','status','payout_chips','settled_at']) THEN RETURN NEW; END IF;
  IF OLD.game='mines' AND OLD.payout_version>=4 AND OLD.mine_cells='{}' AND OLD.picked='{}' AND cardinality(NEW.picked)=1
   AND NEW.mine_cells=public.fn_choice_board_v4(OLD.server_seed,OLD.client_seed,OLD.nonce,OLD.mode::integer,NEW.picked[1])
   AND (to_jsonb(NEW)-ARRAY['picked','status','payout_chips','settled_at','mine_cells']) =
       (to_jsonb(OLD)-ARRAY['picked','status','payout_chips','settled_at','mine_cells']) THEN RETURN NEW; END IF;
 END IF;
 RAISE EXCEPTION 'A Sealed Game Round Cannot Be Rewritten';
END $$;


