--
-- TOC entry 6435 (class 1255 OID 45202015)
-- Name: fn_choice_prizes(text, text, numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_choice_prizes(p_game text, p_mode text, p_bet numeric, p_boost integer DEFAULT 1) RETURNS numeric[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE out numeric[]:='{}'; ladder integer[]; m integer; k integer; floor_chips numeric;
BEGIN
 floor_chips:=public.fn_diamond_bonus_minimum(p_bet,p_boost);
 IF p_game='crossing' THEN
  ladder:=public.fn_choice_ladder(p_mode);
  IF ladder IS NULL THEN RAISE EXCEPTION 'Choose A Road Difficulty'; END IF;
  FOR k IN 1..cardinality(ladder) LOOP out:=array_append(out,p_bet*ladder[k]/100); END LOOP;
 ELSIF p_game='mines' AND p_mode IN ('5','6','10','15') THEN
  m:=p_mode::integer;
  FOR k IN 1..25-m LOOP out:=array_append(out,floor_chips+(p_bet*0.8-floor_chips)*public.fn_choice_choose(25,k)/public.fn_choice_choose(25-m,k)); END LOOP;
 ELSE RAISE EXCEPTION 'Choose A Game Setting'; END IF;
 RETURN out;
END $$;


ALTER FUNCTION public.fn_choice_prizes(p_game text, p_mode text, p_bet numeric, p_boost integer) OWNER TO postgres;

--
-- TOC entry 3619 (class 1255 OID 53111814)
-- Name: fn_choice_prizes_v4(text, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_choice_prizes_v4(p_game text, p_mode text, p_bet numeric, p_floor numeric) RETURNS numeric[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE out numeric[]:='{}'; ladder integer[]; m integer; k integer;
BEGIN
 IF p_floor IS NULL OR p_floor<0 OR p_floor*5>=p_bet*4 THEN RAISE EXCEPTION 'The Floor Beats The Edge'; END IF;
 IF p_game='crossing' THEN
  ladder:=public.fn_choice_ladder_v4(p_mode);
  IF ladder IS NULL THEN RAISE EXCEPTION 'Choose A Road Difficulty'; END IF;
  FOR k IN 1..cardinality(ladder) LOOP out:=array_append(out,p_bet*ladder[k]/100); END LOOP;
 ELSIF p_game='mines' AND p_mode IN ('5','6','10','15') THEN
  m:=p_mode::integer;
  -- The first pick is safe, so P(survive k) = C(25-m-1,k-1)/C(24,k-1) and the first gem pays 0.80B.
  FOR k IN 1..25-m LOOP out:=array_append(out,p_floor+(p_bet*0.8-p_floor)*public.fn_choice_choose(24,k-1)/public.fn_choice_choose(24-m,k-1)); END LOOP;
 ELSE RAISE EXCEPTION 'Choose A Game Setting'; END IF;
 RETURN out;
END $$;


ALTER FUNCTION public.fn_choice_prizes_v4(p_game text, p_mode text, p_bet numeric, p_floor numeric) OWNER TO postgres;

--
-- TOC entry 3841 (class 1255 OID 138649777)
-- Name: fn_choice_prizes_v5(text, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_choice_prizes_v5(p_game text, p_mode text, p_bet numeric, p_floor numeric) RETURNS numeric[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE prizes numeric[]; n integer; m integer; loss numeric; previous numeric;
BEGIN
 IF p_game='crossing' THEN RETURN public.fn_choice_prizes_v4(p_game,p_mode,p_bet,p_floor); END IF;
 IF p_game IS DISTINCT FROM 'mines' OR p_mode IS DISTINCT FROM '6' OR p_bet<=0 OR p_floor<0 OR p_floor>=p_bet*.8 THEN RAISE EXCEPTION 'Invalid Choice Prize'; END IF;
 m:=p_mode::integer;prizes:=ARRAY[p_bet*.8];
 FOR n IN 1..24-m LOOP
  previous:=prizes[n];loss:=public.fn_choice_loss_floor_v5(prizes,n,p_floor);
  prizes:=array_append(prizes,(previous*(25-n)-loss*m)/(25-n-m));
 END LOOP;
 RETURN prizes;
END $$;


ALTER FUNCTION public.fn_choice_prizes_v5(p_game text, p_mode text, p_bet numeric, p_floor numeric) OWNER TO postgres;

--
-- TOC entry 4698 (class 1255 OID 152272782)
