CREATE TABLE public.diamond_choice_rounds (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    host_id uuid NOT NULL,
    host_kind text NOT NULL,
    club_id uuid NOT NULL,
    user_id uuid NOT NULL,
    game text NOT NULL,
    mode text NOT NULL,
    bet_diamonds integer NOT NULL,
    bet_chips numeric(14,2) NOT NULL,
    diamonds_per_chip integer NOT NULL,
    commit_id uuid NOT NULL,
    server_seed text NOT NULL,
    server_seed_hash text NOT NULL,
    client_seed text NOT NULL,
    nonce bigint NOT NULL,
    mine_cells integer[] DEFAULT '{}'::integer[] NOT NULL,
    road_roll bigint DEFAULT 0 NOT NULL,
    picked integer[] DEFAULT '{}'::integer[] NOT NULL,
    max_steps integer NOT NULL,
    prizes numeric[] NOT NULL,
    reserved_chips numeric(14,2) NOT NULL,
    is_fixture boolean DEFAULT false NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    payout_chips numeric(14,2) DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    settled_at timestamp with time zone,
    minimum_payout_chips numeric(14,2) DEFAULT 0 NOT NULL,
    payout_version integer,
    CONSTRAINT diamond_choice_rounds_bet_chips_check CHECK ((bet_chips > (0)::numeric)),
    CONSTRAINT diamond_choice_rounds_bet_diamonds_check CHECK ((bet_diamonds > 0)),
    CONSTRAINT diamond_choice_rounds_check CHECK (((minimum_payout_chips >= (0)::numeric) AND (minimum_payout_chips < bet_chips))),
    CONSTRAINT diamond_choice_rounds_game_check CHECK ((game = ANY (ARRAY['crossing'::text, 'mines'::text]))),
    CONSTRAINT diamond_choice_rounds_max_steps_check CHECK (((max_steps >= 1) AND (max_steps <= 20))),
    CONSTRAINT diamond_choice_rounds_payout_version_check CHECK ((payout_version >= 4)),
    CONSTRAINT diamond_choice_rounds_reserved_chips_check CHECK ((reserved_chips >= (0)::numeric)),
    CONSTRAINT diamond_choice_rounds_status_check CHECK ((status = ANY (ARRAY['open'::text, 'cashed'::text, 'lost'::text])))
);


