    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
 SELECT (ARRAY[p_bet*0.8]||public.fn_choice_road_prizes_v6(p_bet,p_floor))[1:20]
$$;


ALTER FUNCTION public.fn_choice_road_prizes_v7(p_bet numeric, p_floor numeric) OWNER TO postgres;

--
-- TOC entry 5368 (class 1255 OID 138649778)
-- Name: fn_choice_road_probability_v5(numeric[], integer, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_choice_road_probability_v5(p_prizes numeric[], p_steps integer, p_floor numeric) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE chance numeric:=1; n integer; loss numeric;
BEGIN
 FOR n IN 1..p_steps-1 LOOP
  loss:=public.fn_choice_loss_floor_v5(p_prizes,n,p_floor);
  chance:=chance*(p_prizes[n]-loss)/(p_prizes[n+1]-loss);
 END LOOP;
 RETURN chance;
END $$;


ALTER FUNCTION public.fn_choice_road_probability_v5(p_prizes numeric[], p_steps integer, p_floor numeric) OWNER TO postgres;

--
-- TOC entry 6491 (class 1255 OID 31385425)
-- Name: fn_choice_start(uuid, text, text, integer, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_choice_start(p_club_id uuid, p_game text, p_mode text, p_bet integer, p_commit_id uuid, p_client_seed text, p_max_steps integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE adm record; r public.diamond_choice_rounds; v_prizes numeric[]; cap integer; lim integer:=0; k integer;
 v_reserve numeric; v_bet jsonb; v_user uuid:=auth.uid(); v_id uuid:=gen_random_uuid(); v_cells integer[]:='{}'; v_floor numeric;
BEGIN
 IF v_user IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Sign In To Play'); END IF;
 IF p_game IS NULL OR p_game NOT IN ('crossing','mines') OR p_client_seed IS NULL OR length(p_client_seed) NOT BETWEEN 1 AND 64 THEN
  RETURN jsonb_build_object('ok',false,'error','Check Your Game Settings'); END IF;
 -- Serialize all requests for a ticket before either replay or admission. Changing
 -- any wager identity on a retry is a refusal, never a second debit.
 PERFORM pg_advisory_xact_lock(hashtextextended(p_commit_id::text, 94613));
 SELECT * INTO r FROM public.diamond_choice_rounds WHERE commit_id=p_commit_id;
 IF FOUND THEN
  IF r.user_id IS DISTINCT FROM v_user OR r.club_id IS DISTINCT FROM p_club_id OR r.game IS DISTINCT FROM p_game
   OR r.mode IS DISTINCT FROM p_mode OR r.bet_diamonds IS DISTINCT FROM p_bet OR r.client_seed IS DISTINCT FROM p_client_seed
   OR r.max_steps IS DISTINCT FROM p_max_steps THEN RETURN jsonb_build_object('ok',false,'error','That Ticket Belongs To Different Game Settings'); END IF;
  RETURN public.fn_choice_result(r);
 END IF;
 -- A new round names the one setting. A sealed round above keeps the mode it was dealt.
 IF p_mode IS DISTINCT FROM public.fn_choice_mode(p_game) THEN RETURN jsonb_build_object('ok',false,'error','This Game Has One Setting. Refresh Before You Play'); END IF;
 SELECT * INTO adm FROM public.fn_diamond_game_admit(p_game,p_club_id,p_commit_id,p_client_seed,p_bet);
 IF adm.err IS NOT NULL THEN RETURN adm.err; END IF;
 SELECT * INTO r FROM public.diamond_choice_rounds WHERE host_id=adm.o_host AND user_id=v_user AND game=p_game AND status='open';
 IF FOUND THEN RETURN jsonb_build_object('ok',false,'error','Resume Your Open Round First'); END IF;
 v_floor:=public.fn_diamond_bonus_floor(adm.o_bet_chips,COALESCE((public.fn_wheel_starting_award()).boost_multiplier,1),public.fn_diamond_game_paid_diamonds(p_bet),adm.o_rate);
 v_prizes:=public.fn_choice_prizes_v7(p_game,p_mode,adm.o_bet_chips,v_floor);
 cap:=public.fn_diamond_game_cap_cents(adm.o_cfg,adm.o_pool,adm.o_bank,adm.o_bet_chips,(adm.o_cfg).max_multiplier_cents);
 FOR k IN 1..cardinality(v_prizes) LOOP
  EXIT WHEN ceil(v_prizes[k]*100)/100 > adm.o_bet_chips*cap/100;
  lim:=k;
 END LOOP;
 IF p_max_steps IS NULL OR p_max_steps<1 OR p_max_steps>lim THEN
  RETURN jsonb_build_object('ok',false,'error','The Round Limit Changed. Refresh Before You Play'); END IF;
 v_prizes:=v_prizes[1:p_max_steps];
 v_reserve:=ceil(v_prizes[p_max_steps]*100)/100;
 -- The mines board is dealt at the first pick, from this sealed seed and that pick,
 -- so the first tile is always a gem. The road flips a sealed coin per street.
 v_bet:=public.fn_diamond_game_take_bet(v_user,p_bet,(adm.o_cfg).purchased_only,p_game||'_bet',
  public.fn_diamond_game_debit_text(p_game,p_bet),'choice:'||v_id,jsonb_build_object('round_id',v_id,'game',p_game,'host_id',adm.o_host,'club_id',p_club_id)||public.fn_diamond_game_debit_meta(p_bet),adm.o_owner,public.fn_diamond_game_debit_text(p_game,p_bet,true));
 IF COALESCE((v_bet->>'success')::boolean,false)=false THEN RETURN jsonb_build_object('ok',false,'error','The Bet Could Not Be Paid'); END IF;
 UPDATE public.diamond_game_pools SET rounds=rounds+1,intake_diamonds=intake_diamonds+public.fn_wheel_bonus_player_debit(p_bet),
  reserved_chips=reserved_chips+v_reserve,updated_at=now() WHERE host_id=adm.o_host AND game=p_game;
 UPDATE public.diamond_game_commits SET consumed_by=v_id WHERE id=p_commit_id;
 INSERT INTO public.diamond_choice_rounds(id,host_id,host_kind,club_id,user_id,game,mode,bet_diamonds,bet_chips,diamonds_per_chip,
  commit_id,server_seed,server_seed_hash,client_seed,nonce,mine_cells,road_roll,max_steps,prizes,reserved_chips,is_fixture,minimum_payout_chips,payout_version)
 VALUES(v_id,adm.o_host,adm.o_kind,p_club_id,v_user,p_game,p_mode,p_bet,adm.o_bet_chips,adm.o_rate,p_commit_id,
  (adm.o_commit).server_seed,(adm.o_commit).server_seed_hash,p_client_seed,adm.o_nonce,v_cells,0,p_max_steps,v_prizes,v_reserve,adm.o_fixture,v_floor,
  CASE WHEN p_game='crossing' THEN 7 ELSE 5 END) RETURNING * INTO r;
 RETURN public.fn_choice_result(r);
END $$;


ALTER FUNCTION public.fn_choice_start(p_club_id uuid, p_game text, p_mode text, p_bet integer, p_commit_id uuid, p_client_seed text, p_max_steps integer) OWNER TO postgres;

--
-- TOC entry 9259 (class 1255 OID 31385429)
-- Name: fn_choice_state(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_choice_state(p_club_id uuid, p_game text, p_mode text, p_bet integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE h record; cfg public.diamond_game_configs; pool public.diamond_game_pools; r public.diamond_choice_rounds;
 rate integer; prizes numeric[]:='{}'; cap integer; lim integer:=0; k integer; dia numeric:=0; member numeric;
 hist jsonb; opened jsonb; today integer; last_play timestamptz; wait_seconds integer:=0;
BEGIN
 IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Sign In To Play'); END IF;
 IF p_game IS NULL OR p_game NOT IN ('crossing','mines') THEN RETURN jsonb_build_object('ok',false,'error','Choose A Game'); END IF;
 SELECT * INTO h FROM public.fn_wheel_host(p_club_id);
 IF h.host_id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','That Club Could Not Be Found'); END IF;
 SELECT * INTO cfg FROM public.diamond_game_configs WHERE host_id=h.host_id AND game=p_game;
 SELECT * INTO pool FROM public.diamond_game_pools WHERE host_id=h.host_id AND game=p_game;
 rate:=public.fn_ca_bridge_rate();
 IF rate IS NULL OR rate<=0 THEN RETURN jsonb_build_object('ok',false,'error','The Bridge Rate Is Not Set'); END IF;
 IF cfg.host_id IS NOT NULL AND p_bet BETWEEN cfg.min_bet_diamonds AND cfg.max_bet_diamonds AND p_bet BETWEEN 25 AND 5000 THEN
  prizes:=public.fn_choice_prizes_v7(p_game,public.fn_choice_mode(p_game),p_bet::numeric/rate,public.fn_diamond_bonus_floor(p_bet::numeric/rate,1,p_bet,rate));
  cap:=public.fn_diamond_game_cap_cents(cfg,pool,public.fn_diamond_game_cover(h.host_id,h.host_kind),p_bet::numeric/rate,cfg.max_multiplier_cents);
  FOR k IN 1..cardinality(prizes) LOOP EXIT WHEN ceil(prizes[k]*100)/100>(p_bet::numeric/rate)*cap/100; lim:=k; END LOOP;
  prizes:=prizes[1:lim];
 END IF;
 SELECT COALESCE(diamonds,0) INTO dia FROM public.profiles WHERE id=auth.uid();
 IF cfg.purchased_only THEN dia:=LEAST(dia,public.fn_wheel_purchased_available(auth.uid())); END IF;
 SELECT chip_balance INTO member FROM public.club_members WHERE club_id=p_club_id AND user_id=auth.uid() AND COALESCE(status,'active') IN ('active','approved');
 SELECT * INTO r FROM public.diamond_choice_rounds WHERE host_id=h.host_id AND club_id=p_club_id AND user_id=auth.uid() AND game=p_game AND status='open';
 IF FOUND THEN opened:=public.fn_choice_result(r); END IF;
 SELECT COALESCE(jsonb_agg(public.fn_choice_result(x) ORDER BY x.created_at DESC),'[]') INTO hist FROM
  (SELECT * FROM public.diamond_choice_rounds WHERE host_id=h.host_id AND club_id=p_club_id AND user_id=auth.uid() AND game=p_game AND status<>'open' ORDER BY created_at DESC LIMIT 20) x;
 SELECT count(*)::integer,max(created_at) INTO today,last_play FROM public.diamond_choice_rounds WHERE host_id=h.host_id AND user_id=auth.uid() AND game=p_game AND (created_at AT TIME ZONE 'America/Chicago')::date=(now() AT TIME ZONE 'America/Chicago')::date;
 IF last_play IS NOT NULL THEN wait_seconds:=GREATEST(0,cfg.min_seconds_between_rounds-floor(extract(epoch FROM (now()-last_play)))::integer); END IF;
 RETURN jsonb_build_object('ok',true,'rounds_today',today,'daily_limit',COALESCE(cfg.max_rounds_per_player_per_day,0),'diamonds_today',public.fn_diamond_games_spent_today(h.host_id,auth.uid()),'seconds_until_next',wait_seconds,'available',COALESCE(cfg.enabled,false) AND public.fn_diamond_spins_owner_agreed(h.host_id,h.host_kind),'reason',CASE WHEN cfg.host_id IS NULL THEN 'Not Open Here Yet' END,
 'frozen',public.fn_platform_frozen() OR EXISTS(SELECT 1 FROM public.ca_payout_freeze WHERE scope=p_game AND cleared_at IS NULL),'diamonds',COALESCE(dia,0),'member_chips',COALESCE(member,0),'is_member',member IS NOT NULL,
 'diamonds_per_chip',rate,'bets',COALESCE(to_jsonb(cfg.bet_options),'[]'),'max_steps',lim,'prizes',to_jsonb(COALESCE(prizes,'{}'::numeric[])),
 'payout_version',CASE WHEN p_game='crossing' THEN 7 ELSE 5 END,'open_round',opened,'history',hist);
END $$;


ALTER FUNCTION public.fn_choice_state(p_club_id uuid, p_game text, p_mode text, p_bet integer) OWNER TO postgres;

--
-- TOC entry 6472 (class 1255 OID 24888620)
-- Name: fn_ci_check_constraints(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ci_check_constraints() RETURNS TABLE(table_name text, constraint_name text, definition text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT c.conrelid::regclass::text, c.conname::text, pg_get_constraintdef(c.oid)
  FROM pg_constraint c JOIN pg_namespace n ON n.oid = c.connamespace
  WHERE n.nspname = 'public' AND c.contype = 'c'
$$;


ALTER FUNCTION public.fn_ci_check_constraints() OWNER TO postgres;

--
-- TOC entry 7500 (class 1255 OID 28887664)
-- Name: fn_ci_money_trigger_recovery(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ci_money_trigger_recovery(p_versions text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
 IF p_versions IS NULL OR cardinality(p_versions)>64 OR EXISTS(SELECT 1 FROM unnest(p_versions) v WHERE v IS NULL OR v !~ '^[0-9]{14}$') THEN
 RAISE EXCEPTION 'invalid recovery versions' USING ERRCODE='22023'; END IF;
 RETURN jsonb_build_object('version',1,'observed_at',statement_timestamp(),
 'history',COALESCE((SELECT jsonb_agg(jsonb_build_object('version',h.version,'name',h.name,'statementCount',cardinality(h.statements),'sha256',encode(sha256(convert_to(array_to_string(h.statements,''),'UTF8')),'hex'))) FROM supabase_migrations.schema_migrations h WHERE h.version=ANY(p_versions)),'[]'::jsonb),
 'triggers',COALESCE((SELECT jsonb_agg(jsonb_build_object('table',c.relname,'trigger',t.tgname,'enabled',t.tgenabled,'definitionSha256',encode(sha256(convert_to(pg_get_triggerdef(t.oid),'UTF8')),'hex'),'functionSha256',encode(sha256(convert_to(pg_get_functiondef(t.tgfoid),'UTF8')),'hex'))) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal AND c.relname IN('table_seats','club_members','club_wallets','union_wallets','wallets','chip_ledger','tournaments','tournament_players','ca_settlements')),'[]'::jsonb),
 'declarations',COALESCE((SELECT jsonb_agg(jsonb_build_object('table',r.table_name,'trigger',r.trigger_name,'note',r.note)) FROM public.ca_declared_money_triggers r WHERE r.table_name IN('table_seats','club_members','club_wallets','union_wallets','wallets','chip_ledger','tournaments','tournament_players','ca_settlements')),'[]'::jsonb));
END $_$;


ALTER FUNCTION public.fn_ci_money_trigger_recovery(p_versions text[]) OWNER TO postgres;

--
-- TOC entry 7541 (class 1255 OID 28830089)
-- Name: fn_ci_smarter_private_manifest(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ci_smarter_private_manifest() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_namespace oid;
  v_result jsonb;
BEGIN
  SELECT n.oid INTO v_namespace
    FROM pg_catalog.pg_namespace AS n
   WHERE n.nspname = 'smarter_private';
  IF v_namespace IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '3F000',
      MESSAGE = 'smarter_private manifest unavailable: namespace does not exist';
  END IF;

  WITH relations AS (
    SELECT c.oid, pg_catalog.format('%I.%I', n.nspname, c.relname) AS identifier
      FROM pg_catalog.pg_class AS c
      JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace
     WHERE c.relnamespace = v_namespace
       AND c.relkind IN ('r', 'p', 'v', 'm', 'f')
  ), relation_columns AS (
    SELECT r.identifier,
      COALESCE((SELECT pg_catalog.jsonb_agg(a.attname ORDER BY a.attnum)
                  FROM pg_catalog.pg_attribute AS a
                 WHERE a.attrelid = r.oid AND a.attnum > 0 AND NOT a.attisdropped),
               '[]'::jsonb) AS names
      FROM relations AS r
  ), routines AS (
    SELECT DISTINCT pg_catalog.format('%I.%I', n.nspname, p.proname) AS identifier
      FROM pg_catalog.pg_proc AS p
      JOIN pg_catalog.pg_namespace AS n ON n.oid = p.pronamespace
     WHERE p.pronamespace = v_namespace
  )
  SELECT pg_catalog.jsonb_build_object(
    'version', 1,
    'schema', 'smarter_private',
    'complete', true,
    'tables', COALESCE((SELECT pg_catalog.jsonb_agg(r.identifier ORDER BY r.identifier COLLATE "C") FROM relations AS r), '[]'::jsonb),
    'functions', COALESCE((SELECT pg_catalog.jsonb_agg(f.identifier ORDER BY f.identifier COLLATE "C") FROM routines AS f), '[]'::jsonb),
    'columns', COALESCE((SELECT pg_catalog.jsonb_object_agg(c.identifier, c.names) FROM relation_columns AS c), '{}'::jsonb)
  ) INTO v_result;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_ci_smarter_private_manifest() OWNER TO postgres;

--
-- TOC entry 5485 (class 1255 OID 24464226)
-- Name: fn_claim_bounty_legacy_candidate_20260907(uuid, uuid, integer, numeric, uuid, uuid, bigint, timestamp with time zone, uuid, jsonb, numeric, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_bounty_legacy_candidate_20260907(p_tournament_id uuid, p_eliminated_user_id uuid, p_position integer, p_prize numeric, p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_seat_joined_at timestamp with time zone, p_knocker_user_id uuid, p_claimants jsonb, p_bubble_refund numeric DEFAULT 0, p_allow_existing_eliminated boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_player public.tournament_players%ROWTYPE;
  v_candidate public.tournament_knockout_candidates%ROWTYPE;
  v_atomic public.hand_atomic_commits%ROWTYPE;
  v_settlement_at timestamptz;
  v_settlement_hand_text text;
  v_settlement_hand_id uuid;
  v_mode text;
  v_claimants jsonb;
  v_input_claimants jsonb;
  v_knocker uuid;
  v_head numeric;
  v_hand_created_at timestamptz;
  v_position integer;
  v_prize numeric;
  v_claimed boolean := false;
  v_existing public.tournament_bounty_obligations%ROWTYPE;
  v_obligation_id uuid;
  v_activation_generation bigint := 0;
  v_pko_watermark bigint;
  v_bounty_blocked text := NULL;
  v_predecessors jsonb;
  v_activated_at timestamptz;
  v_bust_at timestamptz;
BEGIN
  IF p_tournament_id IS NULL OR p_eliminated_user_id IS NULL
     OR p_table_id IS NULL OR p_hand_id IS NULL OR p_hand_number IS NULL
     OR p_hand_number<1000000 OR p_seat_joined_at IS NULL
     OR p_bubble_refund IS NULL OR p_bubble_refund<0 THEN
    RETURN jsonb_build_object('ok',false,'reason','missing_identity');
  END IF;
  IF p_bubble_refund<>0 THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','bubble_refund_requires_finalized_batch');
  END IF;

  IF p_claimants IS NOT NULL THEN
    IF jsonb_typeof(p_claimants)<>'array' OR jsonb_array_length(p_claimants)=0
       OR EXISTS (
         SELECT 1 FROM jsonb_array_elements(p_claimants) e
          WHERE coalesce(e->>'user_id','')
                  !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             OR coalesce(e->>'weight','') !~ '^[0-9]+([.][0-9]+)?$'
             OR (e->>'weight')::numeric<=0
       ) THEN
      RETURN jsonb_build_object('ok',false,'reason','invalid_claimants');
    END IF;
    SELECT jsonb_agg(jsonb_build_object('user_id',user_id,'weight',1)
                     ORDER BY user_id::text)
      INTO v_input_claimants
      FROM (
        SELECT DISTINCT (e->>'user_id')::uuid AS user_id
          FROM jsonb_array_elements(p_claimants) e
      ) q;
  END IF;

  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;

  -- A hand triple is the immutable replay key. Two legitimate bounties may
  -- have the same player and seat_joined_at after a same-chair rebuy.
  SELECT * INTO v_existing
    FROM public.tournament_bounty_obligations o
   WHERE o.tournament_id=p_tournament_id
     AND o.table_id=p_table_id
     AND o.hand_id=p_hand_id
     AND o.hand_number=p_hand_number
     AND o.eliminated_user_id=p_eliminated_user_id
   FOR UPDATE;
  IF FOUND THEN
    IF v_existing.table_id IS DISTINCT FROM p_table_id
       OR v_existing.hand_id IS DISTINCT FROM p_hand_id
       OR v_existing.seat_joined_at IS DISTINCT FROM p_seat_joined_at
       OR v_existing.bubble_refund IS DISTINCT FROM round(p_bubble_refund,2)
       OR v_existing.position IS DISTINCT FROM p_position
       OR v_existing.prize IS DISTINCT FROM round(p_prize,2)
       OR (p_knocker_user_id IS NOT NULL AND NOT EXISTS (
             SELECT 1 FROM jsonb_array_elements(v_existing.claimants) c
              WHERE c->>'user_id'=p_knocker_user_id::text))
       OR (v_input_claimants IS NOT NULL
           AND v_existing.claimants IS DISTINCT FROM v_input_claimants) THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','obligation_identity_conflict');
    END IF;
    IF v_existing.state='settled'
       AND NOT public.fn_bounty_obligation_has_complete_marker(v_existing.id) THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','settled_marker_incomplete',
        'obligation_id',v_existing.id);
    END IF;
    RETURN jsonb_build_object(
      'ok',true,'already',true,'claimed',false,
      'mode',v_existing.mode,'state',v_existing.state,
      'activation_generation',v_existing.activation_generation,
      'obligation_id',v_existing.id);
  END IF;

  IF NOT (coalesce(v_t.is_bounty,false) OR coalesce(v_t.is_pko,false)
          OR coalesce(v_t.is_mystery_bounty,false)) THEN
    RETURN jsonb_build_object('ok',false,'reason','not_bounty_tournament');
  END IF;
  IF upper(coalesce(v_t.status,''))<>'RUNNING'
     AND NOT (p_allow_existing_eliminated
              AND upper(coalesce(v_t.status,''))='COMPLETING') THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','tournament_lifecycle_not_claimable',
      'status',v_t.status);
  END IF;

  SELECT * INTO v_player FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND tp.user_id=p_eliminated_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','player_not_found');
  END IF;
  IF coalesce(v_player.chips,0)>0 THEN
    RETURN jsonb_build_object('ok',false,'reason','player_has_chips');
  END IF;
  IF v_player.status<>'playing' THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','status_not_claimable','status',v_player.status);
  END IF;
  IF p_position IS NULL OR p_position<2 OR p_prize IS NULL OR p_prize<0 THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid_place_or_prize');
  END IF;
  v_position:=p_position;
  v_prize:=p_prize;

  SELECT a.* INTO v_atomic
    FROM public.hand_atomic_commits a
   WHERE a.table_id=p_table_id
     AND a.hand_number=p_hand_number
     AND a.hand_id=p_hand_id;
  IF NOT FOUND THEN
    IF EXISTS (
      SELECT 1 FROM public.hand_atomic_commits a
       WHERE a.table_id=p_table_id AND a.hand_number=p_hand_number
    ) THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','atomic_knockout_history_identity_conflict');
    END IF;
    RETURN jsonb_build_object(
      'ok',false,'reason','atomic_knockout_evidence_required');
  END IF;

  v_settlement_hand_text:=v_atomic.stack_result->>'hand_id';
  IF coalesce(v_settlement_hand_text,'')
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR v_atomic.stack_result->>'table_id'<>p_table_id::text
     OR coalesce(v_atomic.stack_result->>'hand_number','')
          !~ '^[0-9]+$'
     OR (v_atomic.stack_result->>'hand_number')::bigint<>p_hand_number
     OR coalesce(v_atomic.stack_result->'written'
                   ->>p_eliminated_user_id::text,'')
          !~ '^-?[0-9]+([.][0-9]+)?$'
     OR (v_atomic.stack_result->'written'
           ->>p_eliminated_user_id::text)::numeric<>0 THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','atomic_knockout_candidate_identity_conflict');
  END IF;
  v_settlement_hand_id:=v_settlement_hand_text::uuid;

  SELECT c.* INTO v_candidate
    FROM public.tournament_knockout_candidates c
   WHERE c.tournament_id=p_tournament_id
     AND c.table_id=p_table_id
     AND c.hand_number=p_hand_number
     AND c.hand_id=p_hand_id
     AND c.eliminated_user_id=p_eliminated_user_id;
  IF NOT FOUND
     OR v_candidate.seat_joined_at IS DISTINCT FROM p_seat_joined_at THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','atomic_knockout_candidate_identity_conflict');
  END IF;

  SELECT k.completed_at INTO v_settlement_at
    FROM public.settlement_idempotency_keys k
   WHERE k.table_id=p_table_id
     AND k.hand_id=v_settlement_hand_id
     AND k.status='succeeded'
     AND k.completed_at IS NOT NULL
     AND k.completed_at>=p_seat_joined_at
     AND coalesce(k.result->>'hand_number','') ~ '^[0-9]+$'
     AND (k.result->>'hand_number')::bigint=p_hand_number
     AND k.result->>'table_id'=p_table_id::text
     AND k.result->'written' ? p_eliminated_user_id::text
     AND coalesce(k.result->'written'->>p_eliminated_user_id::text,'')
           ~ '^-?[0-9]+([.][0-9]+)?$'
     AND (k.result->'written'->>p_eliminated_user_id::text)::numeric=0;
  IF v_settlement_at IS NULL THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','accepted_zero_settlement_not_found');
  END IF;

  SELECT h.created_at INTO v_hand_created_at
    FROM public.hand_history h
   WHERE h.id=p_hand_id
     AND h.table_id=p_table_id
     AND h.hand_number=p_hand_number
     AND h.hand_number>=1000000
     AND h.created_at>=v_settlement_at
     AND h.created_at>=p_seat_joined_at
     AND EXISTS (
       SELECT 1 FROM jsonb_array_elements(coalesce(h.players,'[]'::jsonb)) player
        WHERE coalesce(player->>'userId',player->>'user_id')=
                p_eliminated_user_id::text
          AND coalesce(player->>'stack','') ~ '^-?[0-9]+([.][0-9]+)?$'
          AND (player->>'stack')::numeric=0
     );
  IF v_hand_created_at IS NULL THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','exact_knockout_history_not_found');
  END IF;

  v_claimants:=public.fn_exact_tournament_knockout_claimants(
    p_tournament_id,p_hand_id,p_eliminated_user_id);
  IF v_claimants IS NULL OR jsonb_array_length(v_claimants)=0 THEN
    /* A PLACE IS NOT A BOUNTY (2026-09-10).
       fn_exact_tournament_knockout_claimants returns NULL when it cannot
       name the exact winner of the last pot the busted player was eligible
       for, and it is right to refuse to guess. That is a reason not to PAY
       a bounty. It is not a reason to withhold a finishing place from a
       player who provably busted - refusing here left 33 busts unrecorded
       across nine events and held their prize escrow for days. */
    v_bounty_blocked:='exact_pot_claimants_not_found';
    v_claimants:='[]'::jsonb;
  END IF;
  SELECT (e->>'user_id')::uuid INTO v_knocker
    FROM jsonb_array_elements(v_claimants) e
   ORDER BY e->>'user_id' LIMIT 1;
  IF v_bounty_blocked IS NULL AND p_knocker_user_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_claimants) e
        WHERE e->>'user_id'=p_knocker_user_id::text
     ) THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid_knocker');
  END IF;
  IF v_bounty_blocked IS NULL AND v_input_claimants IS NOT NULL
     AND v_input_claimants IS DISTINCT FROM v_claimants THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','claimants_do_not_match_exact_pot');
  END IF;

  /* A BUST BELONGS TO THE PHASE ITS HAND WAS PLAYED IN (2026-09-11).
     The stage at the moment a claim is RECORDED says nothing about when the
     bust happened: a claim backlog recorded 06:27 busts at 13:57 as chest
     knockouts and spent another event's chests on them. v_atomic is the exact,
     identity-verified hand_atomic_commits row of the claimed hand; the sealed
     activation receipt of the current generation is the other end. Earlier ->
     the pre-activation mode the bust would have had. Later -> a chest. No
     receipt -> refused, as before. Order not provable -> the place is
     recorded and no bounty is paid (A PLACE IS NOT A BOUNTY). */
  IF coalesce(v_t.is_mystery_bounty,false)
     AND coalesce(v_t.mystery_bounty_stage,'pending')<>'pending' THEN
    v_activation_generation:=coalesce(v_t.mystery_bounty_activation_generation,0);
    SELECT ar.activated_at INTO v_activated_at
      FROM public.tournament_mystery_activation_receipts ar
     WHERE ar.tournament_id=p_tournament_id
       AND ar.activation_generation=v_activation_generation;
    IF v_activation_generation<=0 OR v_activated_at IS NULL THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','mystery_activation_evidence_missing');
    END IF;
    IF v_atomic.committed_at IS NOT NULL
       AND v_atomic.committed_at>v_activated_at THEN
      v_mode:='mystery_chest';
    ELSE
      v_mode:=CASE WHEN coalesce(v_t.is_pko,false) THEN 'pko'
                   ELSE 'mystery_pre' END;
      v_activation_generation:=0;
      IF v_atomic.committed_at IS NULL
         OR v_atomic.committed_at>=v_activated_at THEN
        v_bounty_blocked:=COALESCE(v_bounty_blocked,
                                   'mystery_phase_of_bust_not_proven');
      END IF;
    END IF;
  ELSE
    v_mode:=CASE
      WHEN coalesce(v_t.is_pko,false) THEN 'pko'
      WHEN coalesce(v_t.is_mystery_bounty,false) THEN 'mystery_pre'
      ELSE 'regular'
    END;
    v_activation_generation:=0;
  END IF;

  /* NO BOUNTY BEFORE THE MONEY (Dan 2026-10-22). A chests-only mystery
     event pays nothing for a bust before its chests open: the bust is
     placed and the head stays in the pool for the chests. */
  IF v_mode='mystery_pre' AND EXISTS (
       SELECT 1 FROM public.tournaments tt
        WHERE tt.id=p_tournament_id
          AND COALESCE(tt.mystery_bounty_regular_pool_percent,50)=0) THEN
    v_bounty_blocked:='mystery_bounties_start_in_the_money';
  END IF;

  IF v_mode='pko' THEN
    v_predecessors:=public.fn_pko_claim_predecessor_status_v1(
      p_tournament_id,p_eliminated_user_id,p_table_id,p_hand_id,
      p_hand_number,p_seat_joined_at);
    IF v_predecessors->>'ok' IS DISTINCT FROM 'true' THEN
      RETURN jsonb_build_object('ok',false,'reason','pko_predecessor_not_ready',
                               'predecessor_proof',v_predecessors);
    END IF;
  END IF;

  IF v_mode='pko' THEN
    SELECT w.last_settled_hand_number INTO v_pko_watermark
      FROM public.tournament_pko_settlement_watermarks w
     WHERE w.tournament_id=p_tournament_id FOR UPDATE;
    IF v_pko_watermark IS NOT NULL AND p_hand_number<v_pko_watermark THEN
      v_predecessors:=public.fn_pko_watermark_admission_status_v1(
        p_tournament_id,p_eliminated_user_id,p_table_id,p_hand_id,
        p_hand_number,p_seat_joined_at,v_claimants);
      IF v_predecessors->>'ok' IS DISTINCT FROM 'true' THEN
        RETURN jsonb_build_object('ok',false,'reason','pko_order_unproven',
          'watermark_proof',v_predecessors);
      END IF;
    END IF;
  END IF;

  IF v_bounty_blocked IS NULL AND v_mode='pko' AND EXISTS (
    SELECT 1 FROM public.tournament_bounty_obligations prior
     WHERE prior.tournament_id=p_tournament_id
       AND prior.mode='pko' AND prior.state='pending'
       AND (prior.hand_number<p_hand_number
            OR (prior.hand_number=p_hand_number
                AND prior.eliminated_user_id::text<
                    p_eliminated_user_id::text))
       AND EXISTS (
         SELECT 1 FROM jsonb_array_elements(prior.claimants) c
          WHERE c->>'user_id'=p_eliminated_user_id::text
       )
  ) THEN
    RETURN jsonb_build_object('ok',false,'reason','pending_pko_predecessor');
  END IF;

  IF v_bounty_blocked IS NULL AND v_mode='pko' AND EXISTS (
    SELECT 1
      FROM public.hand_history h
      CROSS JOIN LATERAL
        jsonb_array_elements(coalesce(h.players,'[]'::jsonb)) hp
     WHERE h.id=p_hand_id
       AND coalesce(hp->>'userId',hp->>'user_id','')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND coalesce(hp->>'userId',hp->>'user_id')<>
             p_eliminated_user_id::text
       AND coalesce(hp->>'stack','') ~ '^-?[0-9]+([.][0-9]+)?$'
       AND (hp->>'stack')::numeric<=0
       AND public.fn_exact_tournament_knockout_claimants(
             p_tournament_id,h.id,
             coalesce(hp->>'userId',hp->>'user_id')::uuid)
             @> jsonb_build_array(jsonb_build_object(
                  'user_id',p_eliminated_user_id,'weight',1))
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_bounty_obligations predecessor
          WHERE predecessor.tournament_id=p_tournament_id
            AND predecessor.hand_number=p_hand_number
            AND predecessor.eliminated_user_id=
                coalesce(hp->>'userId',hp->>'user_id')::uuid
            AND predecessor.state='settled'
       )
  ) THEN
    RETURN jsonb_build_object('ok',false,'reason','same_hand_pko_predecessor');
  END IF;

  v_head:=coalesce(nullif(v_player.current_bounty,0),
                   nullif(v_t.bounty_amount,0));
  IF coalesce(v_head,0)<=0 THEN
    v_bounty_blocked:=COALESCE(v_bounty_blocked,'exact_head_value_not_found');
  END IF;

  /* A BUST IS RANKED BY WHEN IT HAPPENED (2026-09-11). eliminated_at was
     now(), the moment this claim was accepted, so a bust accepted late was
     stamped later than busts that came after it. It is now the time of the
     bust, by the rule the non-bounty door stamps and
     fn_settle_tournament_places ranks with: the commit time of the accepted
     hand this claim is bound to, plus one microsecond per earlier rank in
     that hand - smaller hand-start stack first, then user id. A bust whose
     hand cannot be read is refused, never stamped with the clock; so is a
     generation the player provably played on from - a posted rebuy leg
     after it AND a later hand of this event that deals the player in - since
     its hand is then not the bust and nothing here can say which one is. */
  SELECT a.committed_at
         + (SELECT count(*)
              FROM public.tournament_knockout_candidates s
             WHERE s.tournament_id=c.tournament_id
               AND s.table_id=c.table_id
               AND s.hand_number=c.hand_number
               AND s.hand_id=c.hand_id
               AND (s.stack_before,s.eliminated_user_id)
                   <(c.stack_before,c.eliminated_user_id))::integer
           * interval '1 microsecond'
    INTO v_bust_at
    FROM public.tournament_knockout_candidates c
    JOIN public.hand_atomic_commits a
      ON a.table_id=c.table_id
     AND a.hand_number=c.hand_number
     AND a.hand_id=c.hand_id
   WHERE c.id=v_candidate.id
     AND c.tournament_id=p_tournament_id
     AND c.eliminated_user_id=p_eliminated_user_id
     AND c.state='pending';
  IF v_bust_at IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','knockout_bust_time_unproven');
  END IF;
  IF EXISTS (
       SELECT 1 FROM public.chip_ledger l
        WHERE l.from_entity_id=p_eliminated_user_id
          AND l.tournament_id=p_tournament_id
          AND l.category='rebuy'
          AND l.from_type='player_wallet'
          AND l.to_type='prize_liability'
          AND l.status='posted'
          AND l.amount>0
          AND l.created_at>v_candidate.created_at)
     AND EXISTS (
       SELECT 1 FROM public.hand_history h
        WHERE h.tournament_id=p_tournament_id
          AND h.hand_number>p_hand_number
          AND (h.players @> jsonb_build_array(jsonb_build_object(
                 'userId',p_eliminated_user_id::text))
               OR h.players @> jsonb_build_array(jsonb_build_object(
                 'user_id',p_eliminated_user_id::text)))) THEN
    /* Nothing newer can bind this player, who stays 'playing' at zero
       chips, so this refusal would hold the event open for ever without a
       word. It is written where the money board reads - once: one open alert
       per player. */
    INSERT INTO public.financial_alerts(severity,source,message,context)
    SELECT 'critical','knockout_door.payout_blocked_by_unrecordable_bust',
      'A busted player cannot be recorded, so the tournament cannot finish: '
        ||'the only knockout generation left to record them by is one they '
        ||'rebought from and played on after, and no later bust was captured. '
        ||'Their place needs a ruling from their last hand.',
      jsonb_build_object('tournament_id',p_tournament_id,'user_id',p_eliminated_user_id,
        'reason','knockout_bust_time_unproven',
        'detail','played_on_after_a_rebuy','hand_number',p_hand_number)
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source='knockout_door.payout_blocked_by_unrecordable_bust'
          AND NOT fa.resolved
          AND fa.context->>'tournament_id'=p_tournament_id::text
          AND fa.context->>'user_id'=p_eliminated_user_id::text);
    RETURN jsonb_build_object('ok',false,'reason','knockout_bust_time_unproven',
                              'detail','played_on_after_a_rebuy');
  END IF;

  -- Only this validated claim can authorize its exact next roster write.
  -- No request setting or public API can mint this transaction-local proof.
  INSERT INTO smarter_private.f06_elimination_dispatch
    (xid,relation_name,row_id,candidate_id,old_record,new_record)
  SELECT txid_current(),'tournament_players',v_player.id,v_candidate.id,to_jsonb(v_player),
    to_jsonb(v_player)||jsonb_build_object('status','eliminated',
      'position',p_position,'prize',p_prize,'eliminated_at',v_bust_at)
  WHERE EXISTS(SELECT 1 FROM smarter_private.f06_operations o
    WHERE o.source_table_id=v_player.table_id
      AND o.state NOT IN ('acknowledged','withdrawn_before_manifest'));
  UPDATE public.tournament_players tp
     SET status='eliminated',position=p_position,prize=p_prize,
         eliminated_at=v_bust_at
   WHERE tp.tournament_id=p_tournament_id
     AND tp.user_id=p_eliminated_user_id
     AND tp.status='playing' AND tp.chips<=0;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'bounty elimination CAS missed after locked claim'
      USING ERRCODE='55000';
  END IF;

  DELETE FROM smarter_private.f06_elimination_dispatch
   WHERE xid=txid_current() AND candidate_id=v_candidate.id
     AND relation_name='tournament_players';
  v_claimed:=true;

  IF v_bounty_blocked IS NULL THEN
  INSERT INTO public.tournament_bounty_obligations(
    tournament_id,eliminated_user_id,table_id,hand_id,hand_number,
    settlement_completed_at,seat_joined_at,position,prize,bubble_refund,
    mode,activation_generation,head_amount,knocker_user_id,claimants,
    next_attempt_at)
  VALUES (
    p_tournament_id,p_eliminated_user_id,p_table_id,p_hand_id,p_hand_number,
    v_settlement_at,p_seat_joined_at,v_position,round(v_prize,2),0,
    v_mode,v_activation_generation,round(v_head,2),v_knocker,v_claimants,
    CASE WHEN v_mode='mystery_chest' THEN now()+interval '30 seconds'
         ELSE now() END)
  RETURNING id INTO v_obligation_id;
  ELSE
    /* The bust is recorded and placed above. The head could not be
       attributed, so no obligation is written: fn_tournament_has_unsettled_bounties
       only sees obligations that EXIST, so the event can finish, and the
       head stays in tournaments.bounty_pool for fn_finalize_bounty_pool to
       resolve as residual with its own completion receipt. This row is the
       record that it happened - severity `warning`, so
       fn_ca_financial_alert_to_incident (which promotes only `critical`)
       does not raise a board item per bust. A listed fact, not an alarm. */
    IF v_bounty_blocked IS DISTINCT FROM 'mystery_bounties_start_in_the_money' THEN
    INSERT INTO public.financial_alerts(severity,source,message,context)
    VALUES ('warning',
      'fn_claim_tournament_bounty_elimination.bounty_head_not_attributed',
      'A bust was recorded and placed, but its bounty head could not be '
        ||'attributed ('||v_bounty_blocked||'); the head stays in the '
        ||'bounty pool as residual.',
      jsonb_build_object('tournament_id',p_tournament_id,
        'eliminated_user_id',p_eliminated_user_id,'table_id',p_table_id,
        'hand_id',p_hand_id,'hand_number',p_hand_number,
        'position',v_position,'head_amount',round(coalesce(v_head,0),2),
        'mode',v_mode,'reason',v_bounty_blocked));
    END IF;
  END IF;

  -- Closing the exact already-zero seat belongs to the same proven bust.
  INSERT INTO smarter_private.f06_elimination_dispatch
    (xid,relation_name,row_id,candidate_id,old_record,new_record)
  SELECT txid_current(),'table_seats',s.id,v_candidate.id,to_jsonb(s),
    to_jsonb(s)||jsonb_build_object('left_at',now())
  FROM public.table_seats s
  JOIN public.tournament_knockout_candidates c ON c.id=v_candidate.id
  WHERE s.table_id=p_table_id AND s.user_id=p_eliminated_user_id AND s.left_at IS NULL
    AND s.stack=0 AND s.id=c.seat_id AND s.joined_at=c.seat_joined_at
    AND s.table_id=c.table_id AND s.user_id=c.eliminated_user_id
    AND EXISTS(SELECT 1 FROM smarter_private.f06_operations o
      WHERE o.source_table_id=s.table_id
        AND o.state NOT IN ('acknowledged','withdrawn_before_manifest'));
  UPDATE public.table_seats s
     SET left_at=coalesce(s.left_at,now())
   WHERE s.table_id=p_table_id AND s.user_id=p_eliminated_user_id
     AND s.joined_at=p_seat_joined_at AND s.left_at IS NULL;

  DELETE FROM smarter_private.f06_elimination_dispatch
   WHERE xid=txid_current() AND candidate_id=v_candidate.id
     AND relation_name='table_seats';
  UPDATE public.tables tb
     SET current_players=(
       SELECT count(*) FROM public.table_seats s
        WHERE s.table_id=p_table_id AND s.left_at IS NULL)
   WHERE tb.id=p_table_id;
  PERFORM public.fn_sync_seat_first_player_count(p_tournament_id);

  UPDATE public.tournament_bounty_obligations o
     SET state='settled',settled_at=now()
   WHERE o.id=v_obligation_id
     AND public.fn_bounty_obligation_has_complete_marker(o.id);

  RETURN jsonb_build_object(
    'ok',true,'already',false,'claimed',v_claimed,'mode',v_mode,
    'bounty_blocked',v_bounty_blocked,
    'state',(SELECT o.state FROM public.tournament_bounty_obligations o
              WHERE o.id=v_obligation_id),
    'activation_generation',v_activation_generation,'bubble_refund',0,
    'obligation_id',v_obligation_id);
END;
$_$;


ALTER FUNCTION public.fn_claim_bounty_legacy_candidate_20260907(p_tournament_id uuid, p_eliminated_user_id uuid, p_position integer, p_prize numeric, p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_seat_joined_at timestamp with time zone, p_knocker_user_id uuid, p_claimants jsonb, p_bubble_refund numeric, p_allow_existing_eliminated boolean) OWNER TO postgres;

--
-- TOC entry 9332 (class 1255 OID 215375901)
-- Name: fn_claim_club_entry_news(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_club_entry_news(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_entry jsonb;
  v_message text := '';
  v_posts jsonb := '[]'::jsonb;
  v_key text;
  v_post record;
  v_inserted integer;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;
  -- Match the announcement reader's membership boundary. Staff with a
  -- management grant may also enter through the club-management workspace.
  IF NOT EXISTS (SELECT 1 FROM public.club_members m
                 WHERE m.club_id = p_club_id AND m.user_id = v_uid)
     AND NOT COALESCE(public.fn_can_manage_club_message(p_club_id, v_uid), false) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
  END IF;
  -- Claims for one player/club must read and record in the same order.
  -- Otherwise an old snapshot can overwrite a newer content receipt.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'club-entry-news:' || v_uid::text || ':' || p_club_id::text, 0));
  v_entry := public.fn_get_club_entry_message(p_club_id);
  IF NOT COALESCE((v_entry->>'ok')::boolean, false) THEN RETURN v_entry; END IF;

  -- Unique receipts arbitrate concurrent tabs/devices. Only the INSERT
  -- winner returns each message. Neither a reread nor a date can reopen it.
  IF COALESCE((v_entry->>'should_show')::boolean, false) THEN
    v_key := md5(v_entry->>'message');
    INSERT INTO public.club_entry_news_receipts AS r(user_id, club_id, news_key, content_key)
    VALUES (v_uid, p_club_id, 'lobby', v_key)
    ON CONFLICT (user_id, club_id, news_key) DO UPDATE
      SET content_key = EXCLUDED.content_key, shown_at = now()
      WHERE r.content_key IS DISTINCT FROM EXCLUDED.content_key;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    IF v_inserted = 1 THEN v_message := btrim(v_entry->>'message'); END IF;
  END IF;

  FOR v_post IN
    SELECT a.id, a.title, a.content FROM public.club_announcements a
    WHERE a.club_id = p_club_id AND COALESCE(a.is_active, true)
      AND (a.expires_at IS NULL OR a.expires_at > now())
    ORDER BY a.is_pinned DESC, a.created_at DESC, a.id
    LIMIT 200
  LOOP
    -- Pins, ordering, unchanged saves and expiry edits are not new copy.
    -- A new announcement ID or changed title/body is new news.
    v_key := md5(jsonb_build_array(v_post.title, v_post.content)::text);
    INSERT INTO public.club_entry_news_receipts AS r(user_id, club_id, news_key, content_key)
    VALUES (v_uid, p_club_id, 'post:' || v_post.id::text, v_key)
    ON CONFLICT (user_id, club_id, news_key) DO UPDATE
      SET content_key = EXCLUDED.content_key, shown_at = now()
      WHERE r.content_key IS DISTINCT FROM EXCLUDED.content_key;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    IF v_inserted = 1 THEN
      v_posts := v_posts || jsonb_build_array(jsonb_build_object(
        'id', v_post.id, 'title', v_post.title, 'content', v_post.content));
    END IF;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'message', v_message,
    'revision', v_entry->'revision', 'should_show', v_message <> '',
    'announcements', v_posts);
END;
$$;


ALTER FUNCTION public.fn_claim_club_entry_news(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 4165 (class 1255 OID 24465301)
-- Name: fn_claim_engine_maintenance_break(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_engine_maintenance_break(p_expected_ownership_token uuid, p_new_ownership_token uuid, p_declared_by text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '35s'
    SET lock_timeout TO '32s'
    AS $$
DECLARE
  v_row public.engine_maintenance_break%ROWTYPE;
BEGIN
  IF p_expected_ownership_token IS NULL OR p_new_ownership_token IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'ownership_token_required');
  END IF;
  PERFORM pg_advisory_xact_lock(530090, 1);
  SELECT * INTO v_row
    FROM public.engine_maintenance_break b
   WHERE b.id = true
   FOR UPDATE;
  IF NOT FOUND OR v_row.ownership_token <> p_expected_ownership_token THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'ownership_changed');
  END IF;
  UPDATE public.engine_maintenance_break
     SET ownership_token = p_new_ownership_token,
         declared_by = p_declared_by,
         updated_at = clock_timestamp()
   WHERE id = true
     AND ownership_token = p_expected_ownership_token
  RETURNING * INTO v_row;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'ownership_changed');
  END IF;
  RETURN jsonb_build_object(
    'ok', true,
    'phase', v_row.phase,
    'announced_at', v_row.announced_at,
    'break_started_at', v_row.break_started_at,
    'break_ends_at', v_row.break_ends_at,
    'reason', v_row.reason,
    'ownership_token', v_row.ownership_token
  );
END;
$$;


ALTER FUNCTION public.fn_claim_engine_maintenance_break(p_expected_ownership_token uuid, p_new_ownership_token uuid, p_declared_by text) OWNER TO postgres;

--
-- TOC entry 8869 (class 1255 OID 24465320)
-- Name: fn_claim_entry_purchase_receipt(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_entry_purchase_receipt(p_key_domain text, p_idempotency_key text, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_request jsonb;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) = 0 THEN
    RETURN jsonb_build_object('claimed', true);
  END IF;

  INSERT INTO public.entry_purchase_idempotency_receipts
    (key_domain, idempotency_key, request)
  VALUES (p_key_domain, p_idempotency_key, p_request)
  ON CONFLICT (key_domain, idempotency_key) DO NOTHING
  RETURNING request, response INTO v_request, v_response;
  IF FOUND THEN
    RETURN jsonb_build_object('claimed', true);
  END IF;

  /* The unique-index wait above cannot observe an uncommitted placeholder.
     A committed placeholder without a response means some code violated the
     same-transaction contract, so it is corruption-not permission to rerun
     a money core. */
  SELECT r.request, r.response
    INTO STRICT v_request, v_response
    FROM public.entry_purchase_idempotency_receipts r
   WHERE r.key_domain = p_key_domain
     AND r.idempotency_key = p_idempotency_key;
  IF v_request IS DISTINCT FROM p_request THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_KEY_REUSED: % key is already bound to a different entry purchase',
      p_key_domain
      USING ERRCODE = '22023';
  END IF;
  IF v_response IS NULL THEN
    RAISE EXCEPTION
      'INCOMPLETE_IDEMPOTENCY_RECEIPT: % key was committed without its response',
      p_key_domain
      USING ERRCODE = '55000';
  END IF;
  RETURN jsonb_build_object('claimed', false, 'response', v_response);
END;
$$;


ALTER FUNCTION public.fn_claim_entry_purchase_receipt(p_key_domain text, p_idempotency_key text, p_request jsonb) OWNER TO postgres;

--
-- TOC entry 7234 (class 1255 OID 108293455)
-- Name: fn_claim_final_table_transition(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_final_table_transition(p_tournament_id uuid, p_ownership_token uuid) RETURNS TABLE(state text, ownership_token uuid, announced_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_format_contract text;
  v_triggered boolean;
  v_owner uuid;
  v_announced_at timestamptz;
BEGIN
  IF p_tournament_id IS NULL OR p_ownership_token IS NULL THEN
    RAISE EXCEPTION 'FINAL_TABLE_CLAIM_INVALID: tournament and ownership token are required'
      USING ERRCODE = '22023';
  END IF;

  SELECT t.format_contract, t.final_table_triggered
    INTO v_format_contract, v_triggered
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'FINAL_TABLE_CLAIM_NOT_FOUND: tournament % does not exist', p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;

  IF (v_format_contract IN ('mtt-v1', 'mtt-v2')) IS NOT TRUE THEN
    RAISE EXCEPTION 'FINAL_TABLE_CLAIM_FORMAT: % is not an unlimited MTT',
      coalesce(v_format_contract, '<unresolved>')
      USING ERRCODE = '23514';
  END IF;

  SELECT r.ownership_token, r.announced_at
    INTO v_owner, v_announced_at
    FROM public.tournament_final_table_transition_receipts r
   WHERE r.tournament_id = p_tournament_id;

  IF v_triggered IS TRUE THEN
    -- A legacy direct writer may win during deployment overlap. Give that
    -- historical transition a different owner so no new manager replays it.
    IF v_owner IS NULL THEN
      INSERT INTO public.tournament_final_table_transition_receipts (
        tournament_id,
        ownership_token
      ) VALUES (
        p_tournament_id,
        gen_random_uuid()
      )
      ON CONFLICT (tournament_id) DO NOTHING;

      SELECT r.ownership_token, r.announced_at
        INTO v_owner, v_announced_at
        FROM public.tournament_final_table_transition_receipts r
       WHERE r.tournament_id = p_tournament_id;
    END IF;
  ELSE
    INSERT INTO public.tournament_final_table_transition_receipts (
      tournament_id,
      ownership_token
    ) VALUES (
      p_tournament_id,
      p_ownership_token
    )
    ON CONFLICT (tournament_id) DO NOTHING;

    SELECT r.ownership_token, r.announced_at
      INTO v_owner, v_announced_at
      FROM public.tournament_final_table_transition_receipts r
     WHERE r.tournament_id = p_tournament_id;

    IF v_owner IS DISTINCT FROM p_ownership_token THEN
      RAISE EXCEPTION 'FINAL_TABLE_CLAIM_CORRUPT: an untriggered tournament already has another owner'
        USING ERRCODE = '55000';
    END IF;

    UPDATE public.tournaments
       SET final_table_triggered = true
     WHERE id = p_tournament_id
       AND final_table_triggered IS DISTINCT FROM true;
  END IF;

  INSERT INTO public.tournament_final_table_events (tournament_id)
  VALUES (p_tournament_id)
  ON CONFLICT (tournament_id) DO NOTHING;

  RETURN QUERY
  SELECT CASE
           WHEN v_owner = p_ownership_token AND v_announced_at IS NULL
             THEN 'announcement_owned'::text
           ELSE 'already_persisted'::text
         END,
         v_owner,
         v_announced_at;
END;
$$;


ALTER FUNCTION public.fn_claim_final_table_transition(p_tournament_id uuid, p_ownership_token uuid) OWNER TO postgres;

--
-- TOC entry 7134 (class 1255 OID 30231620)
-- Name: fn_claim_horse_adaptive_batch(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_claim_horse_adaptive_batch(p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    SET lock_timeout TO '2s'
    AS $$
DECLARE w public.horse_adaptive_journal_work%ROWTYPE;
BEGIN
  IF p_lease_token IS NULL THEN RAISE EXCEPTION 'ADAPTIVE_WORK_INVALID_LEASE'; END IF;
  WITH candidate AS (
    SELECT q.batch_key FROM public.horse_adaptive_journal_work q
    WHERE (q.state='queued' AND q.available_at<=clock_timestamp())
       OR (q.state='leased' AND q.lease_until<=clock_timestamp())
    ORDER BY q.available_at,q.created_at,q.batch_key LIMIT 1 FOR UPDATE SKIP LOCKED
  ) UPDATE public.horse_adaptive_journal_work q
      SET state='leased',lease_token=p_lease_token,lease_until=clock_timestamp()+interval '30 seconds',
          attempts=least(q.attempts+1,1000000)
      FROM candidate c WHERE q.batch_key=c.batch_key RETURNING q.* INTO w;
  IF NOT FOUND THEN RETURN jsonb_build_object('version',1,'status','idle'); END IF;
  RETURN jsonb_build_object('version',1,'status','claimed','batchKey',w.batch_key,
    'batchDigest',w.batch_digest,'observations',w.observations,'payload',w.payload,'leaseToken',w.lease_token);
END
$$;


