    CONSTRAINT video_reel_candidates_selection_kind_check CHECK ((selection_kind = ANY (ARRAY['validated_short'::text, 'chapter_highlight'::text, 'metadata_highlight'::text]))),
    CONSTRAINT video_reel_candidates_status_check CHECK ((status = ANY (ARRAY['generating'::text, 'proposed'::text, 'approved'::text, 'rejected'::text, 'rate_limited'::text, 'published'::text]))),
