--
-- TOC entry 3763 (class 1255 OID 24465302)
-- Name: fn_clear_engine_maintenance_break(text, timestamp with time zone, timestamp with time zone, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_clear_engine_maintenance_break(p_phase text, p_announced_at timestamp with time zone, p_break_started_at timestamp with time zone, p_break_ends_at timestamp with time zone, p_reason text, p_ownership_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '35s'
    SET lock_timeout TO '32s'
    AS $$
DECLARE
  v_deleted integer;
BEGIN
  IF p_ownership_token IS NULL THEN
    RAISE EXCEPTION 'MAINTENANCE_OWNERSHIP_REQUIRED: a break may only clear its own generation'
      USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(530090, 1);
  DELETE FROM public.engine_maintenance_break b
   WHERE b.id = true
     AND b.phase IS NOT DISTINCT FROM p_phase
     AND b.announced_at IS NOT DISTINCT FROM p_announced_at
     AND b.break_started_at IS NOT DISTINCT FROM p_break_started_at
     AND b.break_ends_at IS NOT DISTINCT FROM p_break_ends_at
     AND b.reason IS NOT DISTINCT FROM p_reason
     AND b.ownership_token = p_ownership_token;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted = 1;
END;
$$;


ALTER FUNCTION public.fn_clear_engine_maintenance_break(p_phase text, p_announced_at timestamp with time zone, p_break_started_at timestamp with time zone, p_break_ends_at timestamp with time zone, p_reason text, p_ownership_token uuid) OWNER TO postgres;

--
-- TOC entry 3542 (class 1255 OID 15266904)
-- Name: fn_clear_seats_on_game_end(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_clear_seats_on_game_end() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_table uuid;
BEGIN
  IF NEW.status IN ('COMPLETED', 'CANCELLED')
     AND COALESCE(OLD.status, '') IS DISTINCT FROM NEW.status THEN
    FOR v_table IN
      SELECT id FROM public.tables WHERE tournament_id = NEW.id
    LOOP
      -- Never reopen a table whose game is over: the recycler builds the next
      -- spin its own fresh table. What must not survive is the seat rows.
      PERFORM public.fn_clear_table_seats(v_table, false);
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_clear_seats_on_game_end() OWNER TO postgres;

--
-- TOC entry 8595 (class 1255 OID 14613995)
-- Name: fn_clear_sitout_on_turnover(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_clear_sitout_on_turnover() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  -- A different occupant never inherits the prior player's away state.
  IF NEW.user_id IS DISTINCT FROM OLD.user_id
     OR (NEW.left_at IS NOT NULL AND OLD.left_at IS NULL) THEN
    NEW.is_sitting_out := false;
    NEW.sit_out_at := NULL;
  ELSIF NEW.left_at IS NULL AND OLD.left_at IS NOT NULL
        AND NEW.is_sitting_out IS NOT DISTINCT FROM OLD.is_sitting_out THEN
    NEW.is_sitting_out := false;
    NEW.sit_out_at := NULL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_clear_sitout_on_turnover() OWNER TO postgres;

--
-- TOC entry 8836 (class 1255 OID 15266902)
-- Name: fn_clear_table_seats(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_clear_table_seats(p_table_id uuid, p_reopen boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cleared integer := 0;
  v_tournament uuid;
BEGIN
  SELECT tournament_id INTO v_tournament FROM public.tables WHERE id=p_table_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Table not found' USING ERRCODE='22023'; END IF;
  IF v_tournament IS NULL THEN
    RAISE EXCEPTION 'CASH_SEAT_CLEAR_REQUIRES_ENGINE_DEPARTURES' USING ERRCODE='55000';
  END IF;
  -- Only tournament cleanup reaches this point. Cash departures are engine-owned.
  PERFORM public.fn_cashout_seats_for_closing_table(p_table_id, 'seats cleared');

  UPDATE public.table_seats
     SET left_at = now(), is_sitting_out = false
   WHERE table_id = p_table_id AND left_at IS NULL;
  GET DIAGNOSTICS v_cleared = ROW_COUNT;

  UPDATE public.tables
     SET current_players = 0,
         status = CASE WHEN p_reopen AND status <> 'closed' THEN 'waiting' ELSE status END
   WHERE id = p_table_id;

  RETURN v_cleared;
END;
$$;


ALTER FUNCTION public.fn_clear_table_seats(p_table_id uuid, p_reopen boolean) OWNER TO postgres;

--
-- TOC entry 8516 (class 1255 OID 91640569)
-- Name: fn_client_error_health(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_client_error_health() RETURNS TABLE(client_errors_10m integer, client_error_users_10m integer, client_error_top_code_users_10m integer, client_error_top_code text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  WITH recent AS (
    SELECT code, user_id, occurrences
      FROM public.client_error_events
     WHERE received_at > now() - interval '10 minutes'
       AND NOT automated
  ), per_code AS (
    SELECT code, count(DISTINCT user_id)::integer AS users
      FROM recent GROUP BY code
  )
  SELECT coalesce((SELECT sum(occurrences) FROM recent), 0)::integer,
         (SELECT count(DISTINCT user_id) FROM recent)::integer,
         coalesce((SELECT max(users) FROM per_code), 0)::integer,
         (SELECT code FROM per_code ORDER BY users DESC, code LIMIT 1)
$$;


ALTER FUNCTION public.fn_client_error_health() OWNER TO postgres;

--
-- TOC entry 6875 (class 1255 OID 91640532)
-- Name: fn_client_error_scrub(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_client_error_scrub(p_text text, p_max integer) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  SELECT CASE WHEN p_text IS NULL THEN NULL ELSE left(
    regexp_replace(
      regexp_replace(
        regexp_replace(
          regexp_replace(
            regexp_replace(
              left(p_text, greatest(p_max, 0) + 256),
              '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}', '[email]', 'g'),
            'eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+(\.[A-Za-z0-9_-]*)?', '[jwt]', 'g'),
          '(bearer)\s+[A-Za-z0-9._~+/=-]+', '\1 [token]', 'gi'),
        '((access_token|refresh_token|id_token|token|apikey|api_key|password|passwd|secret|authorization|key)=)[^&\s"''\\]+',
        '\1[redacted]', 'gi'),
      '(?=[A-Za-z_+/=]*[0-9])[A-Za-z0-9_+/=]{32,}', '[token]', 'g'),
    greatest(p_max, 0)) END
$$;


ALTER FUNCTION public.fn_client_error_scrub(p_text text, p_max integer) OWNER TO postgres;

--
-- TOC entry 9190 (class 1255 OID 15919073)
-- Name: fn_clone_table_row(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_clone_table_row(p_source_id uuid, p_name text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_row jsonb;
  v_new uuid := gen_random_uuid();
  v_cols text;
BEGIN
  SELECT to_jsonb(t) INTO v_row FROM public.tables t WHERE t.id = p_source_id LIMIT 1;
  IF v_row IS NULL THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: %', p_source_id;
  END IF;

  -- Identity and live state do not carry over.
  v_row := v_row || jsonb_build_object(
    'id',              v_new,
    'is_template',     false,
    'status',          'waiting',
    'current_players', 0,
    'hands_dealt',     0,
    'avg_pot',         0,
    'live_state',      NULL,
    'is_deleted',      false,
    'created_at',      now(),
    'updated_at',      now(),
    -- BOMB POT LIVE STATE (2026-08-28). Engine-written, per-table, and NOT
    -- part of the template: a clone that inherited these would deal a bomb
    -- pot it never earned. The bomb CONFIG columns are untouched on purpose.
    'bomb_pot_sched_state',    NULL,
    'bomb_pot_next_due_at',    NULL,
    'bomb_pot_manual_pending', false
  );

  -- ── NOR DOES ITS PLACE IN THE GAME (2026-09-06) ──────────────────────────
  -- `cluster_id` stays (tables_cash_needs_a_game refuses an open cash table
  -- without one), but role / main_index / lifecycle and their timestamps are
  -- the answer to "which table of this game are you", and the clone is a NEW
  -- one. Copying them made a clone of Main 1 a second Main 1. It joins as an
  -- opening feeder, the shape the controller's OPEN rule creates and already
  -- knows how to promote, break or abandon.
  IF (v_row -> 'cluster_id') IS NOT NULL AND jsonb_typeof(v_row -> 'cluster_id') <> 'null' THEN
    v_row := v_row || jsonb_build_object(
      'role',                 'feeder',
      'main_index',           NULL,
      'lifecycle',            'opening',
      'opened_at',            now(),
      'live_at',              NULL,
      'break_started_at',     NULL,
      'break_eligible_since', NULL,
      'promote_pending',      false
    );
  END IF;

  IF p_name IS NOT NULL THEN
    v_row := v_row || jsonb_build_object('name', p_name);
  END IF;

  -- ── AND IT COULD NOT INSERT AT ALL (2026-09-06) ──────────────────────────
  -- This was `INSERT INTO public.tables SELECT * FROM jsonb_populate_record(
  -- NULL::public.tables, v_row)`, and `public.tables` has FOUR GENERATED
  -- columns - `min_buyin`, `max_buyin`, `min_buy_in_bb`, `max_buy_in_bb`, all
  -- derived from min/max_buy_in and big_blind. `SELECT *` names them, and
  -- Postgres refuses a non-DEFAULT value for a generated column:
  --
  --   428C9 cannot insert a non-DEFAULT value into column "min_buy_in_bb"
  --
  -- So every call has raised since those columns were added, and BOTH callers
  -- were broken: `fn_launch_table_from_template` (a live operator feature) and
  -- `fn_table_lifecycle_pass`'s AUTO CREATE arm - whose only handler is
  -- `EXCEPTION WHEN unique_violation`, which does not catch 428C9, so the
  -- whole pass aborted. Found by the rolled-back probe for this migration; the
  -- clone path has no test and no caller that reports, so nothing said so.
  --
  -- The column list is read from the catalogue rather than written down, so a
  -- FIFTH generated column cannot break it again the way the first four did.
  SELECT string_agg(quote_ident(c.column_name), ', ' ORDER BY c.ordinal_position)
    INTO v_cols
    FROM information_schema.columns c
   WHERE c.table_schema = 'public'
     AND c.table_name = 'tables'
     AND c.is_generated = 'NEVER'
     AND c.is_identity <> 'YES';

  EXECUTE format(
    'INSERT INTO public.tables (%s) SELECT %s FROM jsonb_populate_record(NULL::public.tables, $1)',
    v_cols, v_cols
  ) USING v_row;

  RETURN v_new;
END;
$_$;


ALTER FUNCTION public.fn_clone_table_row(p_source_id uuid, p_name text) OWNER TO postgres;

--
-- TOC entry 46707 (class 0 OID 0)
-- Dependencies: 9190
-- Name: FUNCTION fn_clone_table_row(p_source_id uuid, p_name text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_clone_table_row(p_source_id uuid, p_name text) IS 'Clones a table row. Identity, live state, bomb-pot live state AND the table''s place in its game (role/main_index/lifecycle) are reset: a clustered clone joins as an opening feeder, never as a second Main 1. Inserts by explicit column list read from the catalogue, because public.tables has generated columns that SELECT * cannot write (2026-09-06).';


--
-- TOC entry 3367 (class 1255 OID 69625473)
-- Name: fn_close_account(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_close_account(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET lock_timeout TO '5s'
    AS $$
DECLARE
  v_status text;
  v_club uuid;
  v_precheck jsonb;
  v_tombstone text;
  v_departed integer := 0;
  v_n integer;
  v_deleted jsonb := '{}'::jsonb;
  v_request_id uuid;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_user');
  END IF;

  SELECT p.status INTO v_status FROM public.profiles p WHERE p.id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'profile_not_found');
  END IF;
  IF v_status = 'deleted' THEN
    SELECT g.id INTO v_request_id
      FROM public.gdpr_deletion_requests g
     WHERE g.user_id = p_user_id AND g.status = 'anonymized'
     ORDER BY g.created_at DESC
     LIMIT 1;
    RETURN jsonb_build_object('ok', true, 'already_closed', true, 'request_id', v_request_id);
  END IF;

  -- Serialise with every cashier writer the way the club's departure path
  -- does: the hierarchy lock of each club (in one order), then the rows.
  FOR v_club IN
    SELECT DISTINCT cm.club_id FROM public.club_members cm
     WHERE cm.user_id = p_user_id
     ORDER BY cm.club_id
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:' || v_club::text, 0));
  END LOOP;
  PERFORM 1 FROM public.club_members cm
   WHERE cm.user_id = p_user_id
   ORDER BY cm.club_id
   FOR UPDATE;

  -- Money and authority first: the player settles, then closes.
  IF EXISTS (SELECT 1 FROM public.table_seats ts
              WHERE ts.user_id = p_user_id AND ts.left_at IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'seated');
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_players tp
               JOIN public.tournaments tr ON tr.id = tp.tournament_id
              WHERE tp.user_id = p_user_id
                AND tp.status IN ('registered', 'playing')
                AND tr.status NOT IN ('COMPLETED', 'CANCELLED')) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_entry');
  END IF;
  IF EXISTS (SELECT 1 FROM public.cashout_requests cr
              WHERE (cr.player_id = p_user_id OR cr.agent_id = p_user_id)
                AND (cr.status IN ('pending', 'cancelling', 'completing')
                  OR (cr.status = 'approved' AND cr.completed_at IS NULL))) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'pending_cashout');
  END IF;
  IF EXISTS (SELECT 1 FROM public.chip_escrow ce
              WHERE ce.player_id = p_user_id AND ce.released_at IS NULL)
     OR EXISTS (SELECT 1 FROM public.chip_escrow_holds h
                 WHERE h.user_id = p_user_id AND h.status = 'held') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'escrow');
  END IF;
  IF EXISTS (SELECT 1 FROM public.chip_requests r
              WHERE (r.requester_id = p_user_id OR r.approver_id = p_user_id)
                AND r.status = 'pending') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'chip_request');
  END IF;
  IF EXISTS (SELECT 1 FROM public.club_members cm
              WHERE cm.user_id = p_user_id
                AND abs(COALESCE(cm.chip_balance, 0)) + abs(COALESCE(cm.held_chips, 0))
                  + abs(COALESCE(cm.locked_chips, 0)) + abs(COALESCE(cm.promo_balance, 0))
                  + abs(COALESCE(cm.credit_used, 0)) + abs(COALESCE(cm.diamonds, 0)) <> 0) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'club_chips');
  END IF;
  IF EXISTS (SELECT 1 FROM public.wallets w
              WHERE w.user_id = p_user_id
                AND (COALESCE(w.balance, 0) <> 0 OR COALESCE(w.locked_balance, 0) <> 0)) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'wallet_balance');
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_tickets t
              WHERE t.holder_id = p_user_id AND t.status = 'issued') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'open_ticket');
  END IF;
  IF EXISTS (SELECT 1 FROM public.agents a WHERE a.user_id = p_user_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'club_agent');
  END IF;
  IF EXISTS (SELECT 1 FROM public.club_members cm
              WHERE cm.user_id <> p_user_id
                AND cm.membership_lifecycle_status = 'active'
                AND (cm.agent_id = p_user_id OR cm.parent_agent_id = p_user_id)) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'downline');
  END IF;
  IF EXISTS (SELECT 1 FROM public.clubs c
              WHERE c.owner_id = p_user_id AND c.lifecycle_status = 'active') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'club_owner');
  END IF;
  IF EXISTS (SELECT 1 FROM public.club_members cm
               JOIN public.clubs c ON c.id = cm.club_id
              WHERE cm.user_id = p_user_id
                AND cm.membership_lifecycle_status = 'active'
                AND c.lifecycle_status = 'active'
                AND cm.role IN ('owner', 'club_owner', 'co_owner', 'admin', 'club_admin')) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'club_staff');
  END IF;
  IF EXISTS (SELECT 1 FROM public.unions u WHERE u.owner_id = p_user_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'union_owner');
  END IF;
  v_precheck := public.fn_ca_gdpr_financial_precheck(p_user_id);
  IF NOT COALESCE((v_precheck ->> 'clear')::boolean, false) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'financial',
                              'blockers', v_precheck -> 'blockers');
  END IF;

  -- Leave every club the way the club's departure path does. The row stays.
  INSERT INTO public.audit_trail(
    actor_id, actor_role, action, target_type, target_id, club_id,
    before_state, after_state, reason
  )
  SELECT p_user_id, 'player', 'depart_club_member', 'membership', cm.user_id, cm.club_id,
         jsonb_build_object('user_id', cm.user_id, 'role', cm.role,
                            'status', cm.status::text,
                            'membership_lifecycle_status', cm.membership_lifecycle_status),
         jsonb_build_object('departed', true, 'is_active', false,
                            'membership_lifecycle_status', 'departed',
                            'user_id', cm.user_id),
         'Account Closed'
    FROM public.club_members cm
    JOIN public.clubs c ON c.id = cm.club_id
   WHERE cm.user_id = p_user_id
     AND cm.membership_lifecycle_status = 'active'
     AND c.lifecycle_status = 'active';

  PERFORM set_config('app.club_membership_lifecycle_write', 'depart', true);
  UPDATE public.club_members cm
     SET status = CASE WHEN c.asset = 'diamonds' THEN cm.status ELSE 'suspended' END,
         is_active = false,
         membership_lifecycle_status = 'departed',
         departed_at = clock_timestamp(),
         departed_by = p_user_id,
         departure_reason = 'Account Closed',
         display_name = NULL,
         updated_at = clock_timestamp()
    FROM public.clubs c
   WHERE c.id = cm.club_id
     AND cm.user_id = p_user_id
     AND cm.membership_lifecycle_status = 'active'
     AND c.lifecycle_status = 'active';
  GET DIAGNOSTICS v_departed = ROW_COUNT;
  -- A membership that had already ended keeps its history, not the name.
  UPDATE public.club_members cm
     SET display_name = NULL, updated_at = clock_timestamp()
    FROM public.clubs c
   WHERE c.id = cm.club_id
     AND cm.user_id = p_user_id
     AND cm.display_name IS NOT NULL
     AND c.lifecycle_status = 'active';
  PERFORM set_config('app.club_membership_lifecycle_write', '', true);

  -- The personal, non-financial rows go.
  DELETE FROM public.friendships f WHERE f.user_id = p_user_id OR f.friend_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_deleted := v_deleted || jsonb_build_object('friendships', v_n);
  DELETE FROM public.friend_requests fr WHERE fr.sender_id = p_user_id OR fr.recipient_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_deleted := v_deleted || jsonb_build_object('friend_requests', v_n);
  DELETE FROM public.user_sessions s WHERE s.user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_deleted := v_deleted || jsonb_build_object('user_sessions', v_n);
  DELETE FROM public.user_mfa_factors m WHERE m.user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_deleted := v_deleted || jsonb_build_object('user_mfa_factors', v_n);
  DELETE FROM public.push_subscriptions ps WHERE ps.user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_deleted := v_deleted || jsonb_build_object('push_subscriptions', v_n);
  DELETE FROM public.user_notification_preferences np WHERE np.user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_deleted := v_deleted || jsonb_build_object('user_notification_preferences', v_n);
  DELETE FROM public.notifications n
   WHERE n.user_id = p_user_id
     AND NOT EXISTS (SELECT 1 FROM public.accounting_invoice_deliveries d
                      WHERE d.notification_id = n.id)
     AND NOT EXISTS (SELECT 1 FROM public.push_outbox o
                      WHERE o.accounting_notification_id = n.id);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_deleted := v_deleted || jsonb_build_object('notifications', v_n);

  -- Their pictures go with them: the avatar record (a custom avatar's image
  -- link and the words that described them) and the profile editor's media
  -- library with its albums. The World Hub removes the files themselves
  -- through the Storage API once this has answered ok.
  DELETE FROM public.user_avatars ua WHERE ua.user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_deleted := v_deleted || jsonb_build_object('user_avatars', v_n);
  DELETE FROM public.user_media um WHERE um.user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_deleted := v_deleted || jsonb_build_object('user_media', v_n);
  DELETE FROM public.user_albums al WHERE al.user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_deleted := v_deleted || jsonb_build_object('user_albums', v_n);

  -- The person leaves the profile; the id stays for the journals.
  v_tombstone := 'deleted-' || left(replace(p_user_id::text, '-', ''), 12);
  UPDATE public.profiles SET
    username = v_tombstone,
    full_name = NULL, display_name = NULL, first_name = NULL, last_name = NULL,
    alias = NULL, status_text = NULL, bio = NULL,
    email = NULL, phone = NULL,
    city = NULL, state = NULL, country = NULL,
    home_casino = NULL, favorite_venue = NULL, home_poker_club = NULL,
    avatar_url = NULL, cover_photo_url = NULL, arena_avatar_url = NULL,
    website = NULL, twitter = NULL, instagram = NULL, tiktok = NULL,
    telegram = NULL, hendon_url = NULL,
    favorite_game = NULL, favorite_hand = NULL, favorite_hand_plo = NULL,
    favorite_hand_type = NULL,
    birthday = NULL, birth_year = NULL,
    notification_token = NULL, referral_code = NULL, player_tags = '{}',
    settings = '{}'::jsonb, preferences = '{}'::jsonb, app_settings = '{}'::jsonb,
    hub_preferences = '{}'::jsonb, friend_preferences = '{}'::jsonb,
    store_preferences = '{}'::jsonb, messenger_preferences = '{}'::jsonb,
    reels_preferences = '{}'::jsonb, poker_near_me_preferences = '{}'::jsonb,
    bankroll_preferences = '{}'::jsonb,
    memory_games_preferences = '{}'::jsonb, news_preferences = '{}'::jsonb,
    video_library_preferences = '{}'::jsonb,
    is_online = false, status = 'deleted', updated_at = now()
   WHERE id = p_user_id;

  UPDATE public.users SET
    username = v_tombstone, email = NULL, avatar_url = NULL, updated_at = now()
   WHERE id = p_user_id;

  INSERT INTO public.gdpr_deletion_requests (
    user_id, requested_by, reason, status, anonymized_at, summary
  ) VALUES (
    p_user_id, p_user_id, 'Closed by its owner (fn_close_account)', 'anonymized', now(),
    jsonb_build_object('user_id', p_user_id, 'departed_memberships', v_departed,
                       'deleted', v_deleted)
  )
  RETURNING id INTO v_request_id;

  RETURN jsonb_build_object('ok', true, 'already_closed', false,
                            'request_id', v_request_id,
                            'departed_memberships', v_departed);
END;
$$;


