--
-- TOC entry 9454 (class 1255 OID 116024278)
-- Name: fn_club_bomb_pot_report_v2(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_bomb_pot_report_v2(p_club_id uuid, p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    SET work_mem TO '64MB'
    SET enable_indexscan TO 'off'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
DECLARE
  v_days integer := LEAST(GREATEST(COALESCE(p_days, 30), 1), 365);
  v_window_start date := (now() AT TIME ZONE 'UTC')::date - (LEAST(GREATEST(COALESCE(p_days,30),1),365)-1);
  v_window_end date := (now() AT TIME ZONE 'UTC')::date;
  v_rows jsonb;
BEGIN
  SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.hands DESC), '[]'::jsonb)
    INTO v_rows
    FROM public.fn_club_bomb_pot_report(p_club_id, p_days) r;
  RETURN jsonb_build_object(
    'contract', 'fn_club_bomb_pot_report.v2',
    'contract_version', 2,
    'club_id', p_club_id,
    'requested_days', p_days,
    'window_days', v_days,
    'window_start', v_window_start,
    'window_end', v_window_end,
    'rows', v_rows,
    'generated_at', now()
  );
END;
$$;


