--
-- TOC entry 9022 (class 1255 OID 169309933)
-- Name: fn_club_invite_link(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_invite_link(p_club_id uuid, p_device_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_member record;
  v_club   record;
  v_code   text;
  v_alpha  constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  v_try    integer := 0;
  v_device text := NULLIF(left(btrim(COALESCE(p_device_id, '')), 128), '');
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000'; END IF;

  SELECT id, club_id, name, slug INTO v_club FROM public.clubs WHERE id = p_club_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'not_found', 'error', 'Club not found');
  END IF;

  SELECT status, role INTO v_member FROM public.club_members
   WHERE club_id = p_club_id AND user_id = v_uid;
  IF NOT FOUND OR v_member.status NOT IN ('active', 'approved', 'automatic') THEN
    RETURN jsonb_build_object('success', false, 'code', 'not_a_member',
                              'error', 'Only club members can invite players.');
  END IF;

  SELECT code INTO v_code FROM public.club_invite_links
   WHERE club_id = p_club_id AND inviter_id = v_uid;

  IF v_code IS NULL THEN
    LOOP
      v_try := v_try + 1;
      SELECT string_agg(substr(v_alpha, 1 + floor(random() * length(v_alpha))::int, 1), '')
        INTO v_code FROM generate_series(1, 7);
      BEGIN
        INSERT INTO public.club_invite_links (code, club_id, inviter_id, inviter_device_id)
        VALUES (v_code, p_club_id, v_uid, v_device);
        EXIT;
      EXCEPTION WHEN unique_violation THEN
        -- Either the random code was taken, or a concurrent call created this
        -- inviter's row first. Prefer the existing row.
        SELECT code INTO v_code FROM public.club_invite_links
         WHERE club_id = p_club_id AND inviter_id = v_uid;
        EXIT WHEN v_code IS NOT NULL;
        IF v_try >= 8 THEN RAISE EXCEPTION 'Could not allocate an invite code'; END IF;
      END;
    END LOOP;
  ELSIF v_device IS NOT NULL THEN
    UPDATE public.club_invite_links SET inviter_device_id = v_device
     WHERE code = v_code AND inviter_device_id IS DISTINCT FROM v_device;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'code', v_code,
    'short_path', '/i/' || v_code,
    'join_path', public.fn_club_invite_join_path(p_club_id, v_uid, v_code),
    'club', jsonb_build_object('id', v_club.id, 'club_id', v_club.club_id, 'name', v_club.name, 'slug', v_club.slug)
  );
END $$;


ALTER FUNCTION public.fn_club_invite_link(p_club_id uuid, p_device_id text) OWNER TO postgres;

--
-- TOC entry 5639 (class 1255 OID 169309939)
-- Name: fn_club_invite_mark_verified(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_invite_mark_verified(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_me        record;
  v_row       record;
  v_inv_phone text;
  v_my_phone  text;
  v_alias     text;
  v_club_name text;
  v_count     integer := 0;
BEGIN
  SELECT id, COALESCE(NULLIF(btrim(alias), ''), username) AS username, phone, phone_verified INTO v_me FROM public.profiles WHERE id = p_user_id;
  IF NOT FOUND OR v_me.phone_verified IS NOT TRUE THEN RETURN 0; END IF;

  v_my_phone := right(regexp_replace(COALESCE(v_me.phone, ''), '\D', '', 'g'), 10);
  v_alias := COALESCE(NULLIF(btrim(v_me.username), ''), 'A New Player');

  FOR v_row IN
    SELECT a.* FROM public.club_invite_attributions a
     WHERE a.user_id = p_user_id AND a.status = 'signed_up'
     FOR UPDATE
  LOOP
    SELECT right(regexp_replace(COALESCE(p.phone, ''), '\D', '', 'g'), 10)
      INTO v_inv_phone FROM public.profiles p WHERE p.id = v_row.inviter_id;

    IF length(v_my_phone) = 10 AND v_my_phone = v_inv_phone
       AND NOT public.fn_club_invite_is_exempt(p_user_id)
       AND NOT public.fn_club_invite_is_exempt(v_row.inviter_id) THEN
      UPDATE public.club_invite_attributions
         SET status = 'blocked', block_reason = 'same_phone'
       WHERE id = v_row.id;
      DELETE FROM public.referrals
       WHERE referee_id = p_user_id AND referrer_id = v_row.inviter_id AND status = 'pending';
      UPDATE public.profiles SET referred_by = NULL
       WHERE id = p_user_id AND referred_by = v_row.inviter_id;
      CONTINUE;
    END IF;

    UPDATE public.club_invite_attributions
       SET status = 'verified', verified_at = now()
     WHERE id = v_row.id;
    v_count := v_count + 1;

    IF v_row.fresh_signup THEN
      UPDATE public.referrals SET status = 'completed', completed_at = COALESCE(completed_at, now())
       WHERE referee_id = p_user_id AND referrer_id = v_row.inviter_id;
    END IF;

    SELECT name INTO v_club_name FROM public.clubs WHERE id = v_row.club_id;
    PERFORM public.fn_club_invite_notify(
      v_row.inviter_id, 'club_invite_verified',
      'Your Invite Verified Their Phone',
      v_alias || ' Verified Their Phone And Is Ready To Join ' || COALESCE(v_club_name, 'Your Club') || '.',
      '/hub/club-arena/clubs/' || v_row.club_id::text,
      jsonb_build_object('club_id', v_row.club_id, 'referee_id', p_user_id, 'code', v_row.code)
    );
  END LOOP;

  RETURN v_count;
END $$;


ALTER FUNCTION public.fn_club_invite_mark_verified(p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 6685 (class 1255 OID 169310146)
-- Name: fn_club_invite_my_stats(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_invite_my_stats(p_club_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'code', (SELECT code FROM public.club_invite_links WHERE club_id = p_club_id AND inviter_id = auth.uid()),
    'opened', COALESCE((SELECT click_count FROM public.club_invite_links WHERE club_id = p_club_id AND inviter_id = auth.uid()), 0),
    'signed_up', (SELECT count(*) FROM public.club_invite_attributions a
                   WHERE a.club_id = p_club_id AND a.inviter_id = auth.uid() AND a.fresh_signup AND a.status <> 'blocked'),
    'verified', (SELECT count(*) FROM public.club_invite_attributions a
                  WHERE a.club_id = p_club_id AND a.inviter_id = auth.uid() AND a.status IN ('verified','joined') AND a.verified_at IS NOT NULL),
    'joined', (SELECT count(*) FROM public.club_invite_attributions a
                WHERE a.club_id = p_club_id AND a.inviter_id = auth.uid() AND a.status = 'joined')
  ) WHERE auth.uid() IS NOT NULL;
$$;


ALTER FUNCTION public.fn_club_invite_my_stats(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 7557 (class 1255 OID 169309926)
-- Name: fn_club_invite_notify(uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_invite_notify(p_user_id uuid, p_type text, p_title text, p_message text, p_action_url text, p_data jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_data  jsonb := COALESCE(p_data, '{}'::jsonb);
  v_actor uuid;
BEGIN
  IF p_user_id IS NULL THEN RETURN; END IF;
  -- The invited player is the actor: the feed shows their avatar, and the
  -- push mirror collapses repeats from the same player into one device tag.
  BEGIN
    v_actor := NULLIF(v_data->>'referee_id', '')::uuid;
  EXCEPTION WHEN OTHERS THEN
    v_actor := NULL;
  END;
  -- A signup is not yet phone-verified, so it is a bell row only. Throwaway
  -- accounts cannot buzz an inviter's phone; the verified and joined notices,
  -- which a phone stands behind, still push.
  IF p_type = 'club_invite_signup' THEN
    v_data := v_data || jsonb_build_object('_push', 'suppressed_unverified');
  END IF;
  INSERT INTO public.notifications (user_id, actor_id, type, title, message, data, action_url, read, is_read)
  VALUES (p_user_id, v_actor, p_type, p_title, p_message, v_data, p_action_url, false, false);
EXCEPTION WHEN OTHERS THEN
  -- A notification is never allowed to undo a signup, a verification or a join.
  RAISE WARNING 'fn_club_invite_notify(%) failed: %', p_type, SQLERRM;
END $$;


ALTER FUNCTION public.fn_club_invite_notify(p_user_id uuid, p_type text, p_title text, p_message text, p_action_url text, p_data jsonb) OWNER TO postgres;

--
-- TOC entry 8474 (class 1255 OID 169310145)
-- Name: fn_club_invite_pending(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_invite_pending() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_row record;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('pending', false); END IF;

  SELECT a.club_id, a.inviter_id, a.code, a.status, c.name, c.slug, c.club_id AS club_number,
         COALESCE(c.logo_url, c.avatar_url) AS logo_url, COALESCE(NULLIF(btrim(p.alias), ''), p.username) AS inviter_alias
    INTO v_row
    FROM public.club_invite_attributions a
    JOIN public.clubs c ON c.id = a.club_id AND COALESCE(c.lifecycle_status, 'active') = 'active'
    LEFT JOIN public.profiles p ON p.id = a.inviter_id
   WHERE a.user_id = v_uid
     AND a.status IN ('signed_up', 'verified')
     AND a.claimed_at > now() - interval '30 days'
     -- Any membership row, whatever its status, means the join page has
     -- nothing to offer: a member is in, a pending one waits for the owner,
     -- and a refused one must not be sent back every session.
     AND NOT EXISTS (
       SELECT 1 FROM public.club_members cm
        WHERE cm.club_id = a.club_id AND cm.user_id = v_uid
     )
   ORDER BY a.claimed_at ASC
   LIMIT 1;

  IF NOT FOUND THEN RETURN jsonb_build_object('pending', false); END IF;

  RETURN jsonb_build_object(
    'pending', true,
    'status', v_row.status,
    'club', jsonb_build_object('id', v_row.club_id, 'club_id', v_row.club_number, 'slug', v_row.slug,
                               'name', v_row.name, 'logo_url', v_row.logo_url),
    'inviter_alias', COALESCE(NULLIF(btrim(v_row.inviter_alias), ''), 'A Club Member'),
    'join_path', public.fn_club_invite_join_path(v_row.club_id, v_row.inviter_id, v_row.code)
  );
END $$;


ALTER FUNCTION public.fn_club_invite_pending() OWNER TO postgres;

--
-- TOC entry 7015 (class 1255 OID 169309937)
-- Name: fn_club_invite_resolve(text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_invite_resolve(p_code text, p_count_click boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_uid      uuid := auth.uid();
  v_code     text := upper(btrim(COALESCE(p_code, '')));
  v_link     record;
  v_club     record;
  v_inviter  record;
  v_active   boolean;
  v_playing  integer;
BEGIN
  IF v_code !~ '^[A-HJ-NP-Z2-9]{7}$' THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  SELECT * INTO v_link FROM public.club_invite_links WHERE code = v_code;
  IF NOT FOUND THEN RETURN jsonb_build_object('found', false); END IF;

  SELECT id, club_id, slug, name, description, logo_url, avatar_url, member_count, lifecycle_status, asset
    INTO v_club FROM public.clubs WHERE id = v_link.club_id;
  IF NOT FOUND OR COALESCE(v_club.lifecycle_status, 'active') <> 'active' THEN
    RETURN jsonb_build_object('found', false, 'code', v_code, 'reason', 'club_unavailable');
  END IF;

  SELECT id, COALESCE(NULLIF(btrim(alias), ''), username) AS username, player_number INTO v_inviter FROM public.profiles WHERE id = v_link.inviter_id;

  SELECT EXISTS (
    SELECT 1 FROM public.club_members cm
     WHERE cm.club_id = v_link.club_id AND cm.user_id = v_link.inviter_id
       AND cm.status IN ('active', 'approved', 'automatic')
  ) INTO v_active;

  BEGIN
    v_playing := public.get_club_players_playing(v_club.club_id::text);
  EXCEPTION WHEN OTHERS THEN
    v_playing := NULL;
  END;

  -- Only the landing page's server request (service role, no auth.uid()) counts
  -- an open; it skips link-preview bots and repeat opens from the same browser.
  -- A signed-in caller can no longer inflate the count.
  IF p_count_click AND v_uid IS NULL THEN
    UPDATE public.club_invite_links
       SET click_count = click_count + 1, last_clicked_at = now()
     WHERE code = v_code;
  END IF;

  RETURN jsonb_build_object(
    'found', true,
    'code', v_code,
    'club', jsonb_build_object(
      'id', v_club.id, 'club_id', v_club.club_id, 'slug', v_club.slug, 'name', v_club.name,
      'description', v_club.description,
      'logo_url', COALESCE(v_club.logo_url, v_club.avatar_url),
      'member_count', COALESCE(v_club.member_count, 0),
      'players_playing', v_playing
    ),
    'inviter', jsonb_build_object(
      'alias', COALESCE(NULLIF(btrim(v_inviter.username), ''), 'A Club Member'),
      'player_number', v_inviter.player_number,
      'active', v_active
    ),
    'join_path', public.fn_club_invite_join_path(v_link.club_id, v_link.inviter_id, v_code),
    'expires_after_days', 30
  );
END $_$;


ALTER FUNCTION public.fn_club_invite_resolve(p_code text, p_count_click boolean) OWNER TO postgres;

--
-- TOC entry 3431 (class 1255 OID 14766772)
-- Name: fn_club_is_in_downline(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_is_in_downline(p_club_id uuid, p_upline_user_id uuid, p_member_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 WITH RECURSIVE chain(parent,depth,path) AS (
  SELECT m.agent_id,1,ARRAY[m.user_id] FROM public.club_members m
  WHERE m.club_id=p_club_id AND m.user_id=p_member_user_id AND m.agent_id IS NOT NULL
   AND p_upline_user_id IS NOT NULL AND p_member_user_id IS NOT NULL AND p_upline_user_id<>p_member_user_id
   AND public.fn_cashier_member_is_active(m.club_id,m.user_id)
  UNION ALL
  SELECT m.agent_id,c.depth+1,c.path||m.user_id FROM chain c
  JOIN public.club_members m ON m.club_id=p_club_id AND m.user_id=c.parent
  WHERE c.depth<20 AND m.agent_id IS NOT NULL AND NOT m.user_id=ANY(c.path)
   AND public.fn_cashier_member_is_active(m.club_id,m.user_id)
 ) SELECT EXISTS(SELECT 1 FROM chain WHERE parent=p_upline_user_id)
$$;


ALTER FUNCTION public.fn_club_is_in_downline(p_club_id uuid, p_upline_user_id uuid, p_member_user_id uuid) OWNER TO postgres;

--
-- TOC entry 4822 (class 1255 OID 18041735)
-- Name: fn_club_is_staff(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_is_staff(p_club_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.clubs c
     WHERE c.id = p_club_id
       AND c.owner_id = COALESCE(p_user_id, auth.uid())
  ) OR EXISTS (
    SELECT 1 FROM public.club_members cm
     WHERE cm.club_id = p_club_id
       AND cm.user_id = COALESCE(p_user_id, auth.uid())
       AND cm.role IN ('owner', 'co_owner', 'admin')
       AND COALESCE(cm.status, 'active') IN ('active', 'approved')
  );
$$;


