--
-- TOC entry 9195 (class 1255 OID 18044328)
-- Name: fn_club_members_staff_earn_no_rakeback(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_members_staff_earn_no_rakeback() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Dan 2026-08-31: "CO-OWNERS AND ADMINS GET NO RAKE BACK."
  -- player_rakeback_pct is the first branch of fn_player_rakeback_rate, so a
  -- non-zero value here is money. owner is deliberately not covered.
  NEW.player_rakeback_pct := 0;
  NEW.rakeback_rate       := 0;
  NEW.commission_rate     := 0;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_club_members_staff_earn_no_rakeback() OWNER TO postgres;

--
-- TOC entry 5988 (class 1255 OID 55243439)
-- Name: fn_club_members_status_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_members_status_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    -- fn_club_set_member_status sets this for the duration of its own UPDATE.
    IF COALESCE(current_setting('app.club_status_change', true), '') <> 'on'
       -- migrations, server jobs and SECURITY DEFINER server paths run as these
       AND current_user NOT IN ('postgres', 'supabase_admin', 'service_role') THEN
      RAISE EXCEPTION
        'club_members.status must be changed through fn_club_set_member_status (attempted % -> %, as %)',
        OLD.status, NEW.status, current_user
        USING ERRCODE = '42501',
              HINT = 'Staff suspend, ban and reinstate through fn_club_set_member_status. '
                     'A direct update would let a suspended member reinstate themselves.';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_club_members_status_guard() OWNER TO postgres;

