-- TOC entry 7933 (class 1255 OID 55215803)
-- Name: fn_club_membership_count(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_membership_count(p_user_id uuid, p_excluding_club uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT count(*)::integer
    FROM public.club_members cm
   WHERE cm.user_id = p_user_id
     AND cm.status::text IN ('active', 'approved')
     AND COALESCE(cm.membership_lifecycle_status::text, 'active') = 'active'
     AND (p_excluding_club IS NULL OR cm.club_id <> p_excluding_club)
$$;


