--
-- TOC entry 8213 (class 1255 OID 169293179)
-- Name: fn_club_notice_board(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_notice_board(p_actor uuid, p_club uuid, p_action text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
 v_role text; v_old public.club_notice_board; v_new public.club_notice_board;
 v_id uuid; v_before timestamptz; v_before_id uuid; v_rows jsonb; v_pins jsonb;
 v_status text; v_content text; v_pin boolean;
BEGIN
 SELECT role INTO v_role FROM public.club_members WHERE club_id=p_club AND user_id=p_actor
 AND is_active AND membership_lifecycle_status='active' AND status IN ('active','approved') FOR SHARE;
 IF v_role IS NULL THEN RAISE EXCEPTION 'Active Club Membership Required' USING ERRCODE='42501'; END IF;
 IF p_action='read' THEN
  IF (p_payload->>'before') IS NULL <> ((p_payload->>'beforeId') IS NULL) THEN
   RAISE EXCEPTION 'Both Cursor Fields Required' USING ERRCODE='22023'; END IF;
  v_before := (p_payload->>'before')::timestamptz; v_before_id := (p_payload->>'beforeId')::uuid;
  SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.created_at,n.id),'[]'::jsonb) INTO v_rows FROM (
   SELECT * FROM public.club_notice_board WHERE club_id=p_club AND NOT is_deleted
   AND (v_before IS NULL OR (created_at,id)<(v_before,v_before_id))
   ORDER BY created_at DESC,id DESC LIMIT 51
  ) n;
  SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.created_at,n.id),'[]'::jsonb) INTO v_pins FROM (
   SELECT * FROM public.club_notice_board WHERE club_id=p_club AND NOT is_deleted
   AND is_pinned AND status='pending_payout' ORDER BY created_at,id
  ) n;
  RETURN jsonb_build_object('rows',v_rows,'pinned',v_pins,'canManage',v_role IN ('owner','admin'));
 END IF;
 IF v_role NOT IN ('owner','admin') THEN RAISE EXCEPTION 'Club Admin Or Owner Required' USING ERRCODE='42501'; END IF;
 IF p_action NOT IN ('create','update','delete') OR p_action IS NULL THEN
 RAISE EXCEPTION 'Invalid Board Action' USING ERRCODE='22023'; END IF;
 -- Serialize club writes, including the bounded pinned panel.
 PERFORM 1 FROM public.clubs WHERE id=p_club FOR UPDATE;
 v_id := (p_payload->>'id')::uuid;
 IF v_id IS NULL THEN RAISE EXCEPTION 'Entry ID Required' USING ERRCODE='22023'; END IF;
 SELECT * INTO v_old FROM public.club_notice_board WHERE id=v_id FOR UPDATE;
 IF p_action='create' AND v_old.id IS NOT NULL THEN
  IF v_old.club_id=p_club AND v_old.author_id=p_actor AND v_old.version=1
   AND v_old.content=p_payload->>'content' AND v_old.status=p_payload->>'status'
   AND v_old.is_pinned=coalesce((p_payload->>'is_pinned')::boolean,false)
  THEN RETURN to_jsonb(v_old); END IF;
  RAISE EXCEPTION 'Entry Already Exists' USING ERRCODE='40001';
 END IF;
 IF p_action<>'create' THEN
  IF v_old.id IS NULL OR v_old.club_id<>p_club OR v_old.is_deleted THEN
   RAISE EXCEPTION 'Entry Unavailable' USING ERRCODE='P0002'; END IF;
  IF (p_payload->>'version')::bigint IS DISTINCT FROM v_old.version THEN
   RAISE EXCEPTION 'Entry Changed. Refresh And Try Again.' USING ERRCODE='40001'; END IF;
 END IF;
 IF p_action='delete' THEN
  UPDATE public.club_notice_board SET is_deleted=true,is_pinned=false,content='Removed',
   version=version+1,updated_at=clock_timestamp() WHERE id=v_id RETURNING * INTO v_new;
 ELSE
  v_content := btrim(coalesce(p_payload->>'content',v_old.content));
  v_status := coalesce(p_payload->>'status',v_old.status);
  v_pin := coalesce((p_payload->>'is_pinned')::boolean,v_old.is_pinned,false);
  IF v_content IS NULL OR char_length(v_content) NOT BETWEEN 1 AND 4000
   OR v_status IS NULL OR v_status NOT IN ('notice','pending_payout','paid') THEN
   RAISE EXCEPTION 'Invalid Board Entry' USING ERRCODE='22023'; END IF;
  IF v_status<>'pending_payout' THEN v_pin:=false; END IF;
  IF v_pin AND (SELECT count(*) FROM public.club_notice_board WHERE club_id=p_club
    AND is_pinned AND NOT is_deleted AND id<>v_id)>=20 THEN
   RAISE EXCEPTION 'Unpin A Request Before Pinning Another (Maximum 20)' USING ERRCODE='22023'; END IF;
  IF p_action='create' THEN
   INSERT INTO public.club_notice_board(id,club_id,author_id,content,status,is_pinned)
    VALUES(v_id,p_club,p_actor,v_content,v_status,v_pin) RETURNING * INTO v_new;
  ELSE
   UPDATE public.club_notice_board SET content=v_content,status=v_status,is_pinned=v_pin,
    version=version+1,updated_at=clock_timestamp() WHERE id=v_id RETURNING * INTO v_new;
  END IF;
 END IF;
 INSERT INTO public.club_notice_board_audit(notice_id,actor_id,action,before_row,after_row)
 VALUES(v_id,p_actor,p_action,CASE WHEN v_old.id IS NULL THEN NULL ELSE to_jsonb(v_old) END,to_jsonb(v_new));
 RETURN to_jsonb(v_new);
END $$;


ALTER FUNCTION public.fn_club_notice_board(p_actor uuid, p_club uuid, p_action text, p_payload jsonb) OWNER TO postgres;

--
-- TOC entry 6629 (class 1255 OID 54301163)
-- Name: fn_club_opening_checklist_complete(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_opening_checklist_complete(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_club public.clubs%ROWTYPE;
  v_row public.club_opening_checklists%ROWTYPE;
  v_skipped text[] := '{}'::text[];
  v_unfinished text[] := '{}'::text[];
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sign In To Finish The Opening Checklist' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_club FROM public.clubs c WHERE c.id=p_club_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Club Not Found' USING ERRCODE='P0002'; END IF;
  IF v_club.owner_id IS DISTINCT FROM v_uid THEN RAISE EXCEPTION 'Only The Club Owner Can Finish The Opening Checklist' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_row FROM public.club_opening_checklists k WHERE k.club_id=p_club_id FOR UPDATE;
  IF FOUND AND v_row.completed_at IS NOT NULL THEN
    RETURN jsonb_build_object('clubId',p_club_id,'completedAt',v_row.completed_at,'skippedTaskIds',to_jsonb(v_row.skipped_task_ids));
  END IF;
  IF NOT COALESCE(public.fn_club_opening_checklist_eligible(p_club_id),false) THEN RAISE EXCEPTION 'This Club Has No Opening Checklist' USING ERRCODE='55000'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.club_opening_setups s WHERE s.club_id=p_club_id) THEN RAISE EXCEPTION 'Complete The Opening Setup Wizard First' USING ERRCODE='55000'; END IF;
  v_skipped:=COALESCE(v_row.skipped_task_ids,'{}'::text[]);
  IF NOT('identity'=ANY(v_skipped)) AND NOT(
    (NULLIF(btrim(COALESCE(v_club.logo_url,'')),'') IS NOT NULL AND v_club.logo_url !~* '(^|/)club-logos/preset-[0-9]+[.](webp|png|jpe?g)([?#].*)?$')
    OR (NULLIF(btrim(COALESCE(v_club.avatar_url,'')),'') IS NOT NULL AND v_club.avatar_url !~* '(^|/)club-logos/preset-[0-9]+[.](webp|png|jpe?g)([?#].*)?$')
  ) THEN v_unfinished:=array_append(v_unfinished,'identity'); END IF;
  IF NOT('tagline'=ANY(v_skipped)) AND NULLIF(btrim(COALESCE(v_club.tagline,'')),'') IS NULL THEN v_unfinished:=array_append(v_unfinished,'tagline'); END IF;
  IF NOT('nlh'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tables t WHERE t.club_id=p_club_id AND lower(COALESCE(t.game_variant,'')) IN('nlh','short_deck','pineapple') AND lower(COALESCE(t.status,'')) NOT IN('deleted','archived')) THEN v_unfinished:=array_append(v_unfinished,'nlh'); END IF;
  IF NOT('plo'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tables t WHERE t.club_id=p_club_id AND lower(COALESCE(t.game_variant,'')) LIKE 'plo%' AND lower(COALESCE(t.status,'')) NOT IN('deleted','archived')) THEN v_unfinished:=array_append(v_unfinished,'plo'); END IF;
  IF NOT('limit'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tables t WHERE t.club_id=p_club_id AND (lower(COALESCE(t.game_variant,'')) IN('flh','flo8') OR lower(COALESCE(t.game_variant,'')) LIKE 'limit%') AND lower(COALESCE(t.status,'')) NOT IN('deleted','archived')) THEN v_unfinished:=array_append(v_unfinished,'limit'); END IF;
  IF NOT('mtt'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tournaments t WHERE t.club_id=p_club_id AND t.format_contract IN('mtt-v1','mtt-v2')) THEN v_unfinished:=array_append(v_unfinished,'mtt'); END IF;
  IF NOT('spin'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tournaments t WHERE t.club_id=p_club_id AND t.format_contract='spin-v1') THEN v_unfinished:=array_append(v_unfinished,'spin'); END IF;
  IF NOT('heads-up'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.tournaments t WHERE t.club_id=p_club_id AND t.format_contract='sng-v1') THEN v_unfinished:=array_append(v_unfinished,'heads-up'); END IF;
  IF NOT('first-player'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.club_members m WHERE m.club_id=p_club_id AND m.user_id IS DISTINCT FROM v_club.owner_id AND m.status::text IN('active','approved')) THEN v_unfinished:=array_append(v_unfinished,'first-player'); END IF;
  IF NOT('first-agent'=ANY(v_skipped)) AND NOT EXISTS(SELECT 1 FROM public.agents a WHERE a.club_id=p_club_id AND lower(COALESCE(a.status,'active'))<>'inactive') THEN v_unfinished:=array_append(v_unfinished,'first-agent'); END IF;
  IF cardinality(v_unfinished)>0 THEN RAISE EXCEPTION 'Finish Or Skip Every Opening Checklist Step: %',array_to_string(v_unfinished,', ') USING ERRCODE='55000'; END IF;
  INSERT INTO public.club_opening_checklists AS k(club_id,completed_at,completed_by) VALUES(p_club_id,now(),v_uid)
  ON CONFLICT(club_id) DO UPDATE SET completed_at=now(),completed_by=v_uid,updated_at=now() WHERE k.completed_at IS NULL;
  SELECT * INTO v_row FROM public.club_opening_checklists k WHERE k.club_id=p_club_id;
  RETURN jsonb_build_object('clubId',p_club_id,'completedAt',v_row.completed_at,'skippedTaskIds',to_jsonb(v_row.skipped_task_ids));
END
$_$;


