-- Name: fn_club_opening_checklist_eligible(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_opening_checklist_eligible(p_club_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT c.opening_checklist_started_at IS NOT NULL
     AND COALESCE(c.is_union, false) IS FALSE
     AND c.union_id IS NULL
     AND NOT EXISTS (SELECT 1 FROM public.union_clubs uc WHERE uc.club_id = c.id)
    FROM public.clubs c
   WHERE c.id = p_club_id
$$;


