--
-- TOC entry 4402 (class 1255 OID 54301162)
-- Name: fn_club_opening_checklist_skip(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_opening_checklist_skip(p_club_id uuid, p_task_id text, p_skipped boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_task text := btrim(COALESCE(p_task_id,''));
  v_row public.club_opening_checklists%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sign In To Change The Opening Checklist' USING ERRCODE='42501'; END IF;
  IF p_skipped IS NULL THEN RAISE EXCEPTION 'Say Whether The Step Is Skipped' USING ERRCODE='22023'; END IF;
  IF v_task='opening-setup' THEN RAISE EXCEPTION 'The Opening Setup Wizard Is Required And Cannot Be Skipped' USING ERRCODE='22023'; END IF;
  IF NOT (v_task=ANY(ARRAY['identity','tagline','nlh','plo','limit','mtt','spin','heads-up','first-player','first-agent']::text[])) THEN RAISE EXCEPTION 'That Is Not An Optional Opening Checklist Step' USING ERRCODE='22023'; END IF;
  SELECT c.owner_id INTO v_owner FROM public.clubs c WHERE c.id=p_club_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Club Not Found' USING ERRCODE='P0002'; END IF;
  IF v_owner IS DISTINCT FROM v_uid THEN RAISE EXCEPTION 'Only The Club Owner Can Change The Opening Checklist' USING ERRCODE='42501'; END IF;
  IF NOT COALESCE(public.fn_club_opening_checklist_eligible(p_club_id),false) THEN RAISE EXCEPTION 'This Club Has No Opening Checklist' USING ERRCODE='55000'; END IF;
  SELECT * INTO v_row FROM public.club_opening_checklists k WHERE k.club_id=p_club_id FOR UPDATE;
  IF FOUND AND v_row.completed_at IS NOT NULL THEN RAISE EXCEPTION 'The Opening Checklist Is Already Complete' USING ERRCODE='55000'; END IF;
  IF p_skipped THEN
    INSERT INTO public.club_opening_checklists AS k(club_id,skipped_task_ids)
    VALUES(p_club_id,ARRAY[v_task])
    ON CONFLICT(club_id) DO UPDATE SET skipped_task_ids=ARRAY(SELECT DISTINCT s FROM unnest(k.skipped_task_ids||ARRAY[v_task]) AS s ORDER BY s),updated_at=now()
    WHERE k.completed_at IS NULL AND NOT(v_task=ANY(k.skipped_task_ids));
  ELSE
    UPDATE public.club_opening_checklists k SET skipped_task_ids=array_remove(k.skipped_task_ids,v_task),updated_at=now()
    WHERE k.club_id=p_club_id AND k.completed_at IS NULL AND v_task=ANY(k.skipped_task_ids);
  END IF;
  SELECT * INTO v_row FROM public.club_opening_checklists k WHERE k.club_id=p_club_id;
  RETURN jsonb_build_object('clubId',p_club_id,'completedAt',v_row.completed_at,'skippedTaskIds',to_jsonb(COALESCE(v_row.skipped_task_ids,'{}'::text[])));
END
$$;


