--
-- TOC entry 6751 (class 1255 OID 14494083)
-- Name: fn_club_role(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_role(p_user_id uuid, p_club_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
           WHEN EXISTS (SELECT 1 FROM clubs c
                         WHERE c.id = p_club_id AND c.owner_id = p_user_id) THEN 'owner'
           ELSE (SELECT m.role FROM club_members m
                  WHERE m.user_id = p_user_id AND m.club_id = p_club_id
                  LIMIT 1)
         END;
$$;


ALTER FUNCTION public.fn_club_role(p_user_id uuid, p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 9246 (class 1255 OID 14766769)
-- Name: fn_club_role_rank(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_role_rank(p_role text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT CASE p_role
    WHEN 'owner'       THEN 100
    WHEN 'co_owner'    THEN 90
    WHEN 'admin'       THEN 80
    WHEN 'super_agent' THEN 60
    WHEN 'agent'       THEN 40
    WHEN 'sub_agent'   THEN 20
    WHEN 'player'      THEN 0
    ELSE -1
  END;
$$;


ALTER FUNCTION public.fn_club_role_rank(p_role text) OWNER TO postgres;

--
-- TOC entry 8794 (class 1255 OID 138044647)
-- Name: fn_club_roster_hand_totals_delete(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_roster_hand_totals_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.club_roster_hand_totals AS totals (club_id,user_id,fees,hands)
  SELECT club_id,user_id,sum(fee),sum(n)::bigint
  FROM (SELECT club_id,user_id,-rake_paid AS fee,(-1)::bigint AS n FROM old_facts) changes
  WHERE club_id IS NOT NULL
  GROUP BY club_id,user_id
  HAVING sum(fee) <> 0 OR sum(n) <> 0
  ORDER BY club_id,user_id
  ON CONFLICT (club_id,user_id) DO UPDATE
    SET fees = totals.fees + EXCLUDED.fees,
        hands = totals.hands + EXCLUDED.hands;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_club_roster_hand_totals_delete() OWNER TO postgres;

