--
-- TOC entry 6539 (class 1255 OID 14584168)
-- Name: fn_club_table_daily_catchup(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_table_daily_catchup(p_days integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_n int := GREATEST(LEAST(COALESCE(p_days, 3), 30), 1);
  d date;
  v_done jsonb := '[]'::jsonb;
  v_mark text;
  v_f text; v_h text; v_a text;
  v_lo timestamptz;
  v_hi timestamptz;
  v_ledger numeric;
  v_rollup numeric;
  v_reconciled jsonb := '[]'::jsonb;
  v_today_drift numeric;
BEGIN
  FOR d IN SELECT gs::date FROM generate_series(v_today - (v_n - 1), v_today, interval '1 day') gs LOOP
    /* A COMPLETE DAY IS REBUILT WHEN WHAT IT IS BUILT FROM HAS MOVED
       (2026-10-22). Yesterday was rebuilt on every run, 24 times a day,
       whether or not anything had changed, and before deciding that, every
       day in the window was recounted from its contribution keys even though
       the answer was ignored for yesterday and today: 100-200 s of every
       club-rake-rollup-catchup run, reading clubs, tables and the day's rake
       for minutes. A complete day is now rebuilt on the first run that sees
       it, whenever its facts, raked hands or rake attributions change (their
       count, sums and latest write are fingerprinted in
       club_table_daily_refresh_marks), and once more on the first run twelve
       hours after the day closed, so anything that settles late is read. Today
       is the triggers' and fn_club_table_daily_refresh_day skips it, exactly
       as before. */
    IF d >= v_today THEN
      PERFORM fn_club_table_daily_refresh_day(d);
      v_done := v_done || jsonb_build_array(jsonb_build_object('day', d, 'refreshed', true));
    ELSE
      v_lo := (d::timestamp AT TIME ZONE 'UTC');
      v_hi := ((d + 1)::timestamp AT TIME ZONE 'UTC');
      -- Three reads, each one index range (about 0.2 s apiece).
      SELECT concat_ws('|', count(*), sum(x.fee), sum(x.buyins), sum(x.cashouts),
                       sum(x.winnings), max(x.last_at))
        INTO v_f
        FROM ca_club_data_fact x
       WHERE x.club_id = ANY (ARRAY(SELECT k.id FROM clubs k)) AND x.stat_date = d;
      SELECT concat_ws('|', count(*), sum(r.rake_amount))
        INTO v_h
        FROM rake_records r
       WHERE r.created_at >= v_lo AND r.created_at < v_hi AND r.rake_amount > 0;
      SELECT concat_ws('|', count(*), sum(ra.rake_amount))
        INTO v_a
        FROM rake_attributions ra
       WHERE ra.club_id = ANY (ARRAY(SELECT k.id FROM clubs k))
         AND ra.created_at >= v_lo AND ra.created_at < v_hi;
      v_mark := md5(concat_ws('#', v_f, v_h, v_a));
      IF NOT EXISTS (SELECT 1 FROM club_table_daily_refresh_marks m
                      WHERE m.stat_date = d AND m.facts_fingerprint = v_mark
                        AND (m.refreshed_at >= v_hi + interval '12 hours'
                             OR now() < v_hi + interval '12 hours')) THEN
        PERFORM fn_club_table_daily_refresh_day(d);
        INSERT INTO club_table_daily_refresh_marks (stat_date, facts_fingerprint, refreshed_at)
        VALUES (d, v_mark, now())
        ON CONFLICT (stat_date) DO UPDATE
          SET facts_fingerprint = EXCLUDED.facts_fingerprint,
              refreshed_at = EXCLUDED.refreshed_at;
        v_done := v_done || jsonb_build_array(jsonb_build_object('day', d, 'refreshed', true));
      END IF;
    END IF;

    -- Rake is conserved across attribution, so a COMPLETE day's rollup total
    -- must equal the ledger's cash rake for that day. Today is excluded on
    -- purpose: the triggers are exact on a live day and a recount is not.
    IF d < v_today THEN
      v_ledger := public.fn_ca_club_rake_daily_ledger_total(d);
      SELECT COALESCE(SUM(x.rake), 0) INTO v_rollup
        FROM ca_club_rake_daily x WHERE x.stat_date = d;
      IF abs(v_ledger - v_rollup) > 0.005 THEN
        PERFORM fn_ca_club_rake_daily_rebuild_range(d, d, false);
        v_reconciled := v_reconciled || jsonb_build_array(jsonb_build_object(
          'day', d, 'ledger', v_ledger, 'rollup_was', v_rollup));
      END IF;
    END IF;
  END LOOP;

  -- Today is reported, never rewritten. A drift that survives the day is a
  -- trigger that stopped landing, and it will be recounted at midnight.
  v_today_drift := round(public.fn_ca_club_rake_daily_ledger_total(v_today)
                         - COALESCE((SELECT SUM(x.rake) FROM ca_club_rake_daily x
                                      WHERE x.stat_date = v_today), 0), 4);

  RETURN jsonb_build_object('success', true, 'days', v_done,
                            'rake_daily_rebuilt', v_reconciled,
                            'today_drift', v_today_drift);
END;
$$;


ALTER FUNCTION public.fn_club_table_daily_catchup(p_days integer) OWNER TO postgres;

--
-- TOC entry 5980 (class 1255 OID 14584167)
-- Name: fn_club_table_daily_refresh_day(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_table_daily_refresh_day(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today date := (now() AT TIME ZONE 'UTC')::date;
  v_from_day date := public.fn_ca_club_data_facts_from();
BEGIN
  IF p_day IS NULL OR p_day > v_today THEN
    RETURN jsonb_build_object('success', false, 'error', 'day_out_of_range');
  END IF;
  IF p_day = v_today THEN
    RETURN jsonb_build_object('success', true, 'day', p_day, 'skipped', 'live_day_is_kept_by_triggers');
  END IF;
  IF v_from_day IS NULL OR p_day < v_from_day THEN
    RETURN jsonb_build_object('success', true, 'day', p_day, 'skipped', 'before_club_data_facts');
  END IF;
  RETURN jsonb_build_object('success', true) || public.fn_ca_reporting_rollups_from_facts(p_day);
END;
$$;


ALTER FUNCTION public.fn_club_table_daily_refresh_day(p_day date) OWNER TO postgres;

--
-- TOC entry 8064 (class 1255 OID 14919415)
-- Name: fn_club_tournament_stats(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_tournament_stats(p_club_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE("userId" uuid, username text, avatar text, "tournamentsPlayed" integer, wins integer, "finalTables" integer, "itmFinishes" integer, "totalPrizes" numeric, roi numeric, "biggestWin" numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT
        tp.user_id,
        COALESCE(pr.username, tp.username)::text,
        pr.arena_avatar_url::text,
        COUNT(DISTINCT tp.tournament_id)::int,
        COUNT(*) FILTER (WHERE tp.position = 1)::int,
        COUNT(*) FILTER (WHERE tp.position IS NOT NULL AND tp.position <= 9)::int,
        COUNT(*) FILTER (WHERE COALESCE(tp.prize, 0) > 0)::int,
        COALESCE(SUM(tp.prize), 0)::numeric,
        (CASE
            WHEN SUM(COALESCE(t.buy_in_amount, 0) + COALESCE(t.buy_in_fee, 0)) > 0
            THEN ((COALESCE(SUM(tp.prize), 0)
                   - SUM(COALESCE(t.buy_in_amount, 0) + COALESCE(t.buy_in_fee, 0)))
                  / SUM(COALESCE(t.buy_in_amount, 0) + COALESCE(t.buy_in_fee, 0))) * 100.0
            ELSE 0
        END)::numeric,
        COALESCE(MAX(tp.prize), 0)::numeric
    FROM tournament_players tp
    JOIN tournaments t ON t.id = tp.tournament_id
    LEFT JOIN profiles pr ON pr.id = tp.user_id
    WHERE t.club_id = p_club_id
      AND tp.status IN ('eliminated', 'winner')
    GROUP BY tp.user_id, COALESCE(pr.username, tp.username), pr.arena_avatar_url
    -- user_id breaks ties: without it, two players on equal prizes can swap
    -- between pages and the same row appears twice while another never does.
    ORDER BY 8 DESC, tp.user_id
    LIMIT GREATEST(p_limit, 0)
    OFFSET GREATEST(p_offset, 0);
$$;


ALTER FUNCTION public.fn_club_tournament_stats(p_club_id uuid, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- TOC entry 46845 (class 0 OID 0)
-- Dependencies: 8064
-- Name: FUNCTION fn_club_tournament_stats(p_club_id uuid, p_limit integer, p_offset integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_club_tournament_stats(p_club_id uuid, p_limit integer, p_offset integer) IS 'Club tournament leaderboard aggregated server-side. Replaces a client-side aggregation that was capped at 10k raw rows, which every club exceeded. SECURITY INVOKER so the tournaments RLS policy still hides private tournaments.';


--
-- TOC entry 3788 (class 1255 OID 22319577)
-- Name: fn_club_trade_ledger(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_club_trade_ledger(p_club_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, created_at timestamp with time zone, transaction_type text, amount numeric, from_user_id uuid, to_user_id uuid, notes text, metadata jsonb, from_name text, to_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET lock_timeout TO '5s'
    AS $$
DECLARE
  v_viewer uuid := auth.uid();
  v_role text;
  -- Cashier exposes 250 rows and requests one sentinel row to decide whether
  -- another page exists. Preserve the established bounded RPC contract.
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 251);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
BEGIN
  IF v_viewer IS NULL OR p_club_id IS NULL THEN RETURN; END IF;
  v_role := public.fn_club_bank_role(p_club_id, v_viewer);
  IF v_role IS NULL THEN RETURN; END IF;

  IF v_role IN ('owner', 'co_owner', 'admin') THEN
    RETURN QUERY
    SELECT ct.id, ct.created_at,
           CASE WHEN ct.transaction_type = 'horse_treasury_funding' THEN 'club_bank_send' ELSE ct.transaction_type END,
           ct.amount,
           CASE WHEN ct.transaction_type = 'horse_treasury_funding' OR (ct.transaction_type = 'club_bank_send' AND v_viewer IS DISTINCT FROM ct.from_user_id AND v_viewer IS DISTINCT FROM ct.to_user_id) THEN NULL ELSE ct.from_user_id END,
           ct.to_user_id,
           CASE WHEN ct.transaction_type = 'horse_treasury_funding' OR ct.notes ~* 'horse'
                  OR (ct.transaction_type = 'club_bank_send' AND ct.notes = 'Club Bank Send') THEN NULL
                ELSE ct.notes END,
           CASE WHEN ct.transaction_type IN ('club_bank_send', 'horse_treasury_funding')
                THEN jsonb_build_object('destination', coalesce(ct.metadata ->> 'destination', 'player_wallet'))
                ELSE ct.metadata END,
           CASE WHEN pf.id IS NOT NULL AND NOT (ct.transaction_type = 'horse_treasury_funding' OR (ct.transaction_type = 'club_bank_send' AND v_viewer IS DISTINCT FROM ct.from_user_id AND v_viewer IS DISTINCT FROM ct.to_user_id))
                THEN public.fn_arena_name(pf.alias, pf.username, pf.display_name, pf.first_name, pf.last_name, pf.full_name) END,
           CASE WHEN pt.id IS NOT NULL THEN public.fn_arena_name(pt.alias, pt.username, pt.display_name, pt.first_name, pt.last_name, pt.full_name) END
      FROM public.chip_transactions ct
      LEFT JOIN public.profiles pf ON pf.id = ct.from_user_id
      LEFT JOIN public.profiles pt ON pt.id = ct.to_user_id
     WHERE ct.club_id = p_club_id
     ORDER BY ct.created_at DESC, ct.id DESC LIMIT v_limit OFFSET v_offset;
  ELSIF v_role IN ('super_agent', 'agent', 'sub_agent') THEN
    RETURN QUERY
    WITH RECURSIVE dl AS (
      SELECT v_viewer AS user_id
      UNION
      SELECT edge.child
        FROM public.fn_club_active_cashier_edges(p_club_id) edge
        JOIN dl ON edge.parent = dl.user_id
    )
    SELECT ct.id, ct.created_at,
           CASE WHEN ct.transaction_type = 'horse_treasury_funding' THEN 'club_bank_send' ELSE ct.transaction_type END,
           ct.amount,
           CASE WHEN ct.transaction_type = 'horse_treasury_funding' OR (ct.transaction_type = 'club_bank_send' AND v_viewer IS DISTINCT FROM ct.from_user_id AND v_viewer IS DISTINCT FROM ct.to_user_id) THEN NULL ELSE ct.from_user_id END,
           ct.to_user_id,
           CASE WHEN ct.transaction_type = 'horse_treasury_funding' OR ct.notes ~* 'horse'
                  OR (ct.transaction_type = 'club_bank_send' AND ct.notes = 'Club Bank Send') THEN NULL
                ELSE ct.notes END,
           CASE WHEN ct.transaction_type IN ('club_bank_send', 'horse_treasury_funding')
                THEN jsonb_build_object('destination', coalesce(ct.metadata ->> 'destination', 'player_wallet'))
                ELSE ct.metadata END,
           CASE WHEN pf.id IS NOT NULL AND NOT (ct.transaction_type = 'horse_treasury_funding' OR (ct.transaction_type = 'club_bank_send' AND v_viewer IS DISTINCT FROM ct.from_user_id AND v_viewer IS DISTINCT FROM ct.to_user_id))
                THEN public.fn_arena_name(pf.alias, pf.username, pf.display_name, pf.first_name, pf.last_name, pf.full_name) END,
           CASE WHEN pt.id IS NOT NULL THEN public.fn_arena_name(pt.alias, pt.username, pt.display_name, pt.first_name, pt.last_name, pt.full_name) END
      FROM public.chip_transactions ct
      LEFT JOIN public.profiles pf ON pf.id = ct.from_user_id
      LEFT JOIN public.profiles pt ON pt.id = ct.to_user_id
     WHERE ct.club_id = p_club_id
       AND (ct.from_user_id IN (SELECT user_id FROM dl)
         OR ct.to_user_id IN (SELECT user_id FROM dl))
     ORDER BY ct.created_at DESC, ct.id DESC LIMIT v_limit OFFSET v_offset;
  ELSE
    RETURN QUERY
    SELECT ct.id, ct.created_at,
           CASE WHEN ct.transaction_type = 'horse_treasury_funding' THEN 'club_bank_send' ELSE ct.transaction_type END,
           ct.amount,
           CASE WHEN ct.transaction_type = 'horse_treasury_funding' OR (ct.transaction_type = 'club_bank_send' AND v_viewer IS DISTINCT FROM ct.from_user_id AND v_viewer IS DISTINCT FROM ct.to_user_id) THEN NULL ELSE ct.from_user_id END,
           ct.to_user_id,
           CASE WHEN ct.transaction_type = 'horse_treasury_funding' OR ct.notes ~* 'horse'
                  OR (ct.transaction_type = 'club_bank_send' AND ct.notes = 'Club Bank Send') THEN NULL
                ELSE ct.notes END,
           CASE WHEN ct.transaction_type IN ('club_bank_send', 'horse_treasury_funding')
                THEN jsonb_build_object('destination', coalesce(ct.metadata ->> 'destination', 'player_wallet'))
                ELSE ct.metadata END,
           CASE WHEN pf.id IS NOT NULL AND NOT (ct.transaction_type = 'horse_treasury_funding' OR (ct.transaction_type = 'club_bank_send' AND v_viewer IS DISTINCT FROM ct.from_user_id AND v_viewer IS DISTINCT FROM ct.to_user_id))
                THEN public.fn_arena_name(pf.alias, pf.username, pf.display_name, pf.first_name, pf.last_name, pf.full_name) END,
           CASE WHEN pt.id IS NOT NULL THEN public.fn_arena_name(pt.alias, pt.username, pt.display_name, pt.first_name, pt.last_name, pt.full_name) END
      FROM public.chip_transactions ct
      LEFT JOIN public.profiles pf ON pf.id = ct.from_user_id
      LEFT JOIN public.profiles pt ON pt.id = ct.to_user_id
     WHERE ct.club_id = p_club_id
       AND (ct.from_user_id = v_viewer OR ct.to_user_id = v_viewer)
     ORDER BY ct.created_at DESC, ct.id DESC LIMIT v_limit OFFSET v_offset;
  END IF;
END
$$;


