-- Name: FUNCTION fn_community_overview(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_community_overview() IS 'Live readings for the Community Center (/community). Scoped to auth.uid(); takes no argument so a browser cannot ask about another account. Unread messages are deliberately absent - /messages leaves Club Arena for the World Hub messenger.';


--
-- TOC entry 4843 (class 1255 OID 21077643)
-- Name: fn_community_search(text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_community_search(p_query text, p_scope text DEFAULT 'all'::text, p_limit integer DEFAULT 12) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_query text := lower(regexp_replace(btrim(coalesce(p_query, '')), '\s+', ' ', 'g'));
  v_limit integer := least(greatest(coalesce(p_limit, 12), 1), 40);
  v_tokens text[];
  v_fuzzy boolean;
  v_clubs jsonb := '[]'::jsonb;
  v_tables jsonb := '[]'::jsonb;
  v_tournaments jsonb := '[]'::jsonb;
  v_club_total integer := 0;
  v_table_total integer := 0;
  v_tournament_total integer := 0;
  v_health jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_scope IS NULL OR p_scope NOT IN ('all', 'clubs', 'tables', 'tournaments') THEN
    RAISE EXCEPTION 'Invalid search scope' USING ERRCODE = '22023';
  END IF;
  IF length(v_query) > 64 THEN
    RAISE EXCEPTION 'Search must be 64 characters or fewer' USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(array_agg(t), '{}'::text[])
    INTO v_tokens
    FROM (
      SELECT t FROM unnest(string_to_array(v_query, ' ')) AS t
       WHERE t <> ''
       LIMIT 6
    ) s;
  v_fuzzy := length(v_query) >= 3;

  -- Index health is measured on every call. It is what "Live Indexes" shows.
  SELECT jsonb_build_object(
    'clubs', (SELECT count(*) FROM public.clubs c WHERE coalesce(c.status, 'active') = 'active'),
    'players', (
      SELECT count(*)
        FROM public.profiles p
        LEFT JOIN public.player_search_preferences sp ON sp.user_id = p.id
       WHERE coalesce(sp.discoverable, true)
    ),
    'tables', (
      SELECT count(*) FROM public.tables t
       WHERE t.is_deleted = false AND t.status <> 'closed' AND t.tournament_id IS NULL
    ),
    'tournaments', (
      SELECT count(*) FROM public.tournaments t
       WHERE t.status IN ('ANNOUNCED', 'REGISTERING', 'RUNNING')
    )
  ) INTO v_health;

  IF cardinality(v_tokens) = 0 THEN
    RETURN jsonb_build_object(
      'query', v_query, 'scope', p_scope, 'fuzzy', false, 'limit', v_limit,
      'clubs', v_clubs, 'tables', v_tables, 'tournaments', v_tournaments,
      'totals', jsonb_build_object('clubs', 0, 'tables', 0, 'tournaments', 0),
      'index_health', v_health
    );
  END IF;

  -- CLUBS (and unions: a union's lobby row lives in clubs with is_union)
  IF p_scope IN ('all', 'clubs') THEN
    WITH matched AS (
      SELECT c.*,
             public.fn_community_search_score(
               concat_ws(' ', c.name, c.slug, c.code, c.club_id::text, c.tagline),
               v_tokens, v_fuzzy
             ) AS score
        FROM public.clubs c
       WHERE coalesce(c.status, 'active') = 'active'
    ),
    ranked AS (
      SELECT m.*,
             row_number() OVER (
               ORDER BY m.score DESC, coalesce(m.is_union, false) DESC,
                        m.member_count DESC NULLS LAST, m.name
             ) AS ord
        FROM matched m
       WHERE m.score IS NOT NULL
    ),
    picked AS (
      SELECT r.*,
             CASE
               WHEN coalesce(r.is_union, false) THEN
                 (SELECT u.member_count FROM public.fn_batch_union_realtime_member_counts(ARRAY[r.id]) u)
               ELSE
                 (SELECT k.member_count FROM public.fn_batch_club_realtime_member_counts(ARRAY[r.id]) k)
             END AS live_member_count,
             (
               SELECT count(*)
                 FROM public.tables t
                WHERE t.is_deleted = false AND t.status <> 'closed' AND t.tournament_id IS NULL
                  AND coalesce(t.is_private, false) = false
                  AND (t.club_id = r.id
                       OR (coalesce(r.is_union, false)
                           AND t.club_id IN (SELECT uc.club_id FROM public.union_clubs uc WHERE uc.union_id = r.id)))
             ) AS live_table_count,
             (
               SELECT coalesce(sum(t.current_players), 0)
                 FROM public.tables t
                WHERE t.is_deleted = false AND t.status <> 'closed' AND t.tournament_id IS NULL
                  AND coalesce(t.is_private, false) = false
                  AND (t.club_id = r.id
                       OR (coalesce(r.is_union, false)
                           AND t.club_id IN (SELECT uc.club_id FROM public.union_clubs uc WHERE uc.union_id = r.id)))
             ) AS live_seated,
             (
               SELECT count(*) FROM public.tournaments tt
                WHERE tt.status IN ('ANNOUNCED', 'REGISTERING', 'RUNNING')
                  AND coalesce(tt.is_private, false) = false
                  AND (tt.club_id = r.id OR tt.union_id = r.id)
             ) AS live_tournament_count,
             (
               SELECT cm.status FROM public.club_members cm
                WHERE cm.club_id = r.id AND cm.user_id = v_uid
                LIMIT 1
             ) AS viewer_status,
             (SELECT pu.name FROM public.clubs pu WHERE pu.id = r.union_id AND pu.id <> r.id) AS union_name
        FROM ranked r
       WHERE r.ord <= v_limit
    )
    SELECT (SELECT count(*) FROM ranked)::integer,
           (SELECT coalesce(jsonb_agg(jsonb_build_object(
              'id', p.id,
              'slug', p.slug,
              'club_number', p.club_id,
              'name', p.name,
              'tagline', p.tagline,
              'description', p.description,
              'image_url', coalesce(nullif(p.logo_url, ''), nullif(p.avatar_url, ''), nullif(p.logo, '')),
              'card_image_url', nullif(p.card_image_url, ''),
              'is_union', coalesce(p.is_union, false),
              'union_id', p.union_id,
              'union_name', p.union_name,
              'member_count', coalesce(p.live_member_count, p.member_count, 0),
              'online_count', coalesce(p.online_count, 0),
              'table_count', p.live_table_count,
              'seated_count', p.live_seated,
              'tournament_count', p.live_tournament_count,
              'level', p.level,
              'is_public', coalesce(p.is_public, true),
              'requires_approval', coalesce(p.requires_approval, false),
              'viewer_status', p.viewer_status,
              'match_score', round(p.score::numeric, 3)
            ) ORDER BY p.ord), '[]'::jsonb) FROM picked p)
      INTO v_club_total, v_clubs;
  END IF;

  -- TABLES (cash / open ring games)
  IF p_scope IN ('all', 'tables') THEN
    WITH visible AS (
      SELECT t.id, t.name, t.game_variant, t.game_type, t.stakes, t.small_blind, t.big_blind,
             t.current_players, t.max_players, t.status, t.club_id, t.is_featured, t.label_as_new,
             t.hide_club_name, t.created_at,
             c.name AS club_name, c.slug AS club_slug, c.is_union AS club_is_union
        FROM public.tables t
        LEFT JOIN public.clubs c ON c.id = t.club_id
       WHERE t.is_deleted = false
         AND t.status <> 'closed'
         AND t.tournament_id IS NULL
         AND coalesce(t.is_template, false) = false
         AND (
           coalesce(t.is_private, false) = false
           OR t.club_id IS NULL
           OR public.is_club_member(t.club_id, v_uid)
           OR c.owner_id = v_uid
           OR public.fn_union_oversees_club(t.club_id, v_uid)
         )
    ),
    matched AS (
      SELECT v.*,
             coalesce(
               public.fn_community_search_score(
                 concat_ws(' ', v.name, v.game_variant, v.game_type, v.stakes), v_tokens, v_fuzzy),
               0.7 * public.fn_community_search_score(
                 concat_ws(' ', v.name, v.game_variant, v.game_type, v.stakes, v.club_name), v_tokens, v_fuzzy)
             ) AS score
        FROM visible v
    ),
    ranked AS (
      SELECT m.*,
             row_number() OVER (
               ORDER BY m.score DESC, m.current_players DESC NULLS LAST,
                        (m.status = 'running') DESC, m.name
             ) AS ord
        FROM matched m
       WHERE m.score IS NOT NULL
    )
    SELECT (SELECT count(*) FROM ranked)::integer,
           (SELECT coalesce(jsonb_agg(jsonb_build_object(
              'id', r.id,
              'name', r.name,
              'game_variant', r.game_variant,
              'game_type', r.game_type,
              'stakes', r.stakes,
              'small_blind', r.small_blind,
              'big_blind', r.big_blind,
              'current_players', coalesce(r.current_players, 0),
              'max_players', coalesce(r.max_players, 9),
              'status', r.status,
              'is_featured', coalesce(r.is_featured, false),
              'is_new', coalesce(r.label_as_new, false),
              'club_id', r.club_id,
              'club_name', CASE WHEN coalesce(r.hide_club_name, false) THEN NULL ELSE r.club_name END,
              'club_slug', r.club_slug,
              'club_is_union', coalesce(r.club_is_union, false),
              'match_score', round(r.score::numeric, 3)
            ) ORDER BY r.ord), '[]'::jsonb) FROM ranked r WHERE r.ord <= v_limit)
      INTO v_table_total, v_tables;
  END IF;

  -- TOURNAMENTS (announced, registering, running)
  IF p_scope IN ('all', 'tournaments') THEN
    WITH visible AS (
      SELECT t.id, t.name, t.status, t.tournament_type, t.variant, t.game_type,
             t.buy_in_amount, t.buy_in_fee, t.guaranteed_prize, t.prize_pool,
             t.current_players, t.max_players, t.format_contract, t.start_time, t.club_id, t.union_id,
             t.is_bounty, t.is_pko, t.is_mystery_bounty, t.is_turbo, t.hide_club_name,
             c.name AS club_name, c.slug AS club_slug
        FROM public.tournaments t
        LEFT JOIN public.clubs c ON c.id = t.club_id
       WHERE t.status IN ('ANNOUNCED', 'REGISTERING', 'RUNNING')
         AND (
           coalesce(t.is_private, false) = false
           OR t.club_id IS NULL
           OR public.is_club_member(t.club_id, v_uid)
           OR c.owner_id = v_uid
         )
    ),
    matched AS (
      SELECT v.*,
             coalesce(
               public.fn_community_search_score(
                 concat_ws(' ', v.name, v.variant, v.game_type, v.tournament_type), v_tokens, v_fuzzy),
               0.7 * public.fn_community_search_score(
                 concat_ws(' ', v.name, v.variant, v.game_type, v.tournament_type, v.club_name), v_tokens, v_fuzzy)
             ) AS score
        FROM visible v
    ),
    ranked AS (
      SELECT m.*,
             row_number() OVER (
               ORDER BY m.score DESC,
                        CASE m.status WHEN 'RUNNING' THEN 0 WHEN 'REGISTERING' THEN 1 ELSE 2 END,
                        m.start_time ASC NULLS LAST, m.name
             ) AS ord
        FROM matched m
       WHERE m.score IS NOT NULL
    )
    SELECT (SELECT count(*) FROM ranked)::integer,
           (SELECT coalesce(jsonb_agg(jsonb_build_object(
              'id', r.id,
              'name', r.name,
              'status', r.status,
              'tournament_type', r.tournament_type,
              'format_contract', r.format_contract,
              'variant', r.variant,
              'buy_in_amount', coalesce(r.buy_in_amount, 0),
              'buy_in_fee', coalesce(r.buy_in_fee, 0),
              'guaranteed_prize', coalesce(r.guaranteed_prize, 0),
              'prize_pool', coalesce(r.prize_pool, 0),
              'current_players', coalesce(r.current_players, 0),
              'max_players', r.max_players,
              'start_time', r.start_time,
              'is_bounty', coalesce(r.is_bounty, false) OR coalesce(r.is_pko, false) OR coalesce(r.is_mystery_bounty, false),
              'is_turbo', coalesce(r.is_turbo, false),
              'club_id', r.club_id,
              'club_name', CASE WHEN coalesce(r.hide_club_name, false) THEN NULL ELSE r.club_name END,
              'club_slug', r.club_slug,
              'is_registered', EXISTS (
                SELECT 1 FROM public.tournament_players tp
                 WHERE tp.tournament_id = r.id AND tp.user_id = v_uid
                   AND tp.status IN ('registered', 'playing')
              ),
              'match_score', round(r.score::numeric, 3)
            ) ORDER BY r.ord), '[]'::jsonb) FROM ranked r WHERE r.ord <= v_limit)
      INTO v_tournament_total, v_tournaments;
  END IF;

  RETURN jsonb_build_object(
    'query', v_query,
    'scope', p_scope,
    'fuzzy', v_fuzzy,
    'limit', v_limit,
    'clubs', v_clubs,
    'tables', v_tables,
    'tournaments', v_tournaments,
    'totals', jsonb_build_object(
      'clubs', v_club_total, 'tables', v_table_total, 'tournaments', v_tournament_total
    ),
    'index_health', v_health
  );
END;
$$;


ALTER FUNCTION public.fn_community_search(p_query text, p_scope text, p_limit integer) OWNER TO postgres;

--
-- TOC entry 46868 (class 0 OID 0)
-- Dependencies: 4843
-- Name: FUNCTION fn_community_search(p_query text, p_scope text, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_community_search(p_query text, p_scope text, p_limit integer) IS 'Club Arena /search: ranked trigram-fuzzy search over clubs (union-aware live member counts, resolved logos), open tables and live tournaments, plus per-index live health counts. Players come from fn_search_players.';


--
-- TOC entry 8495 (class 1255 OID 21077640)
-- Name: fn_community_search_score(text, text[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_community_search_score(p_hay text, p_tokens text[], p_fuzzy boolean) RETURNS real
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'extensions'
    AS $$
  WITH hay AS (
    SELECT lower(coalesce(p_hay, '')) AS h
  ),
  per AS (
    SELECT
      CASE
        WHEN position(t IN h) > 0 THEN
          CASE
            WHEN h = t THEN 1.0
            WHEN h LIKE t || '%' OR h LIKE '% ' || t || '%' THEN 0.95
            ELSE 0.85
          END
        WHEN p_fuzzy AND length(t) >= 3 AND word_similarity(t, h) >= 0.5 THEN
          0.4 + 0.4 * word_similarity(t, h)
        ELSE NULL
      END AS s
    FROM hay, unnest(coalesce(p_tokens, '{}'::text[])) AS t
  )
  SELECT CASE
           WHEN count(*) = 0 OR bool_or(s IS NULL) THEN NULL
           ELSE avg(s)::real
         END
    FROM per;
$$;


ALTER FUNCTION public.fn_community_search_score(p_hay text, p_tokens text[], p_fuzzy boolean) OWNER TO postgres;

--
-- TOC entry 46870 (class 0 OID 0)
-- Dependencies: 8495
-- Name: FUNCTION fn_community_search_score(p_hay text, p_tokens text[], p_fuzzy boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_community_search_score(p_hay text, p_tokens text[], p_fuzzy boolean) IS 'Community search matching rule. NULL = no match; otherwise 0..1 relevance. Every token must match (substring, or trigram word_similarity >= 0.5 when fuzzy).';


--
-- TOC entry 8698 (class 1255 OID 38569695)
-- Name: fn_complete_breakfast_original_witness(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_breakfast_original_witness(p_operation_id uuid, p_expected jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    SET statement_timeout TO '30s'
    SET lock_timeout TO '3s'
    AS $$
DECLARE
 t constant uuid:='f370585d-40ea-4085-bb8f-c7e8c74f3fb4';
 u constant uuid:='9ee591b7-2360-4ea8-ad3b-942ef829fbda';
 survivor constant uuid:='ae0bc48d-f98c-4b25-a9fa-e3522f986173';
 v_original jsonb; v_current jsonb; v_token uuid; v_result jsonb; v_reprice jsonb;
 v_receipt smarter_private.breakfast_original_witness%ROWTYPE;
 v_t public.tournaments%ROWTYPE; v_entry public.tournament_entry_close_receipts%ROWTYPE;
 v_structure jsonb; v_target jsonb; v_old_seats jsonb; v_old_snapshots jsonb;
BEGIN
 IF public.fn_caller_is_engine() IS DISTINCT FROM true THEN RAISE EXCEPTION 'service authority required' USING ERRCODE='28000'; END IF;
 IF p_operation_id IS NULL OR jsonb_typeof(p_expected) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'BREAKFAST_REQUEST_REQUIRED' USING ERRCODE='22023'; END IF;
 PERFORM public.fn_ca_lock_settlement_lane_for_finish(t);
 IF public.fn_platform_frozen() IS DISTINCT FROM false THEN RAISE EXCEPTION 'PLATFORM_FROZEN' USING ERRCODE='55000'; END IF;
 SELECT * INTO v_t FROM public.tournaments WHERE id=t FOR UPDATE;
 SELECT * INTO v_receipt FROM smarter_private.breakfast_original_witness WHERE tournament_id=t;
 IF FOUND THEN
  IF v_receipt.operation_id IS DISTINCT FROM p_operation_id OR v_receipt.expected IS DISTINCT FROM p_expected THEN
   RAISE EXCEPTION 'BREAKFAST_REPLAY_MISMATCH' USING ERRCODE='55000'; END IF;
  v_result:=public.fn_ca_tournament_terminal_receipt(t,survivor);
  IF (SELECT cash_receipt->'original_witness' FROM public.tournament_terminal_settlements WHERE tournament_id=t)
    IS DISTINCT FROM smarter_private.breakfast_standings_witness(t,survivor) THEN
   RAISE EXCEPTION 'BREAKFAST_TERMINAL_WITNESS_CHANGED' USING ERRCODE='P0404'; END IF;
  RETURN v_result;
 END IF;
 IF v_t.id IS NULL OR v_t.status<>'RUNNING' OR v_t.club_id<>'2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'
 OR v_t.prize_pool IS DISTINCT FROM 153::numeric OR v_t.total_rake IS DISTINCT FROM 17::numeric
 OR v_t.bounty_pool IS DISTINCT FROM 0::numeric OR v_t.current_players<>2
 OR v_t.prize_pool_finalized IS DISTINCT FROM true OR v_t.entry_contract_locked IS DISTINCT FROM true
 OR coalesce(v_t.is_bounty,false) OR coalesce(v_t.is_pko,false) OR coalesce(v_t.is_mystery_bounty,false)
 OR coalesce(v_t.bubble_protection,false) OR v_t.tournament_type IS DISTINCT FROM 'MTT'
 OR v_t.starting_chips IS DISTINCT FROM 12000 OR v_t.satellite_target_id IS NOT NULL THEN
  RAISE EXCEPTION 'BREAKFAST_EVENT_CHANGED' USING ERRCODE='55000'; END IF;
 -- The old snapshot manager is still present. Lock its actual current identity;
 -- expiry/heartbeat are liveness fields, never absence or historical authority.
 PERFORM 1 FROM public.engine_tournament_leases WHERE tournament_id=t FOR UPDATE;
 SELECT coalesce(jsonb_agg(to_jsonb(l)-ARRAY['heartbeat_at','acquired_at'] ORDER BY lease_generation),'[]') INTO v_current
 FROM public.engine_tournament_leases l WHERE tournament_id=t;
 IF v_current IS DISTINCT FROM p_expected->'manager' THEN RAISE EXCEPTION 'BREAKFAST_MANAGER_CHANGED' USING ERRCODE='55000'; END IF;
 PERFORM 1 FROM public.tournament_players WHERE tournament_id=t ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.tournament_obligations WHERE tournament_id=t ORDER BY kind,place,id FOR UPDATE;
 PERFORM 1 FROM public.tournament_payouts WHERE tournament_id=t ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.tables WHERE tournament_id=t ORDER BY id FOR UPDATE;
 PERFORM s.id FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id WHERE tb.tournament_id=t ORDER BY s.id FOR UPDATE OF s;
 SELECT * INTO v_entry FROM public.tournament_entry_close_receipts WHERE tournament_id=t FOR UPDATE;
 v_original:=smarter_private.breakfast_retained_case();
 IF smarter_private.breakfast_roster(t) IS DISTINCT FROM v_original->'roster'
 OR p_expected->'roster' IS DISTINCT FROM v_original->'roster'
 OR to_jsonb(v_entry) IS DISTINCT FROM v_original->'entry'
 OR to_jsonb(v_entry) IS DISTINCT FROM p_expected->'entry'
 OR public.fn_safe_jsonb_array(v_t.payout_structure::text) IS DISTINCT FROM v_entry.payout_structure_snapshot
 OR v_entry.reprice_completed_at IS NOT NULL THEN
  RAISE EXCEPTION 'BREAKFAST_ORIGINAL_ROSTER_OR_ENTRY_CHANGED' USING ERRCODE='55000'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY id),'[]') INTO v_current FROM public.tournament_payouts p WHERE tournament_id=t;
 IF v_current IS DISTINCT FROM v_original->'payouts' THEN RAISE EXCEPTION 'BREAKFAST_PAID_EVIDENCE_CHANGED' USING ERRCODE='55000'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY id),'[]') INTO v_current FROM public.tournament_obligations o WHERE tournament_id=t;
 IF v_current IS DISTINCT FROM v_original->'obligations' THEN RAISE EXCEPTION 'BREAKFAST_OBLIGATIONS_CHANGED' USING ERRCODE='55000'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(k) ORDER BY key),'[]') INTO v_current FROM public.wallet_credit_idempotency k WHERE key LIKE 'tourney:'||t||':%';
 IF v_current IS DISTINCT FROM v_original->'wallet_keys' THEN RAISE EXCEPTION 'BREAKFAST_CREDIT_EVIDENCE_CHANGED' USING ERRCODE='55000'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]') INTO v_current FROM public.rake_records r WHERE tournament_id=t;
 IF v_current IS DISTINCT FROM v_original->'fee_charges' THEN RAISE EXCEPTION 'BREAKFAST_FEE_CHARGE_CHANGED' USING ERRCODE='55000'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.id),'[]') INTO v_old_seats FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id WHERE tb.tournament_id=t;
 IF v_old_seats IS DISTINCT FROM v_original->'seats' OR v_old_seats IS DISTINCT FROM p_expected->'seats'
 OR (SELECT count(*) FROM public.tables WHERE tournament_id=t)<>4
 OR (SELECT count(*) FROM public.tables WHERE tournament_id=t AND status='running')<>1
 OR NOT EXISTS(SELECT 1 FROM public.tables WHERE id='dd835bad-d3c8-4984-ab2f-5ed52d1fb664' AND tournament_id=t AND status='running' AND f06_lifecycle=9657) THEN
  RAISE EXCEPTION 'BREAKFAST_PHYSICAL_ROSTER_CHANGED' USING ERRCODE='55000'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.id),'[]') INTO v_old_snapshots FROM public.hand_state_snapshots s
 WHERE NOT is_complete AND table_id IN(SELECT id FROM public.tables WHERE tournament_id=t);
 -- Three unchanged Sept8 snapshots belong to CLOSED tables. They remain
 -- unfinished historical evidence. This operation never completes/clears them.
 IF v_old_snapshots IS DISTINCT FROM v_original->'historical_snapshots'
 OR EXISTS(SELECT 1 FROM public.hand_state_snapshots s JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=t AND NOT s.is_complete AND tb.status<>'closed')
 OR EXISTS(SELECT 1 FROM public.engine_table_leases l JOIN public.tables tb ON tb.id=l.table_id WHERE tb.tournament_id=t)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_hand_permits WHERE tournament_id=t)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_operations WHERE tournament_id=t)
 OR EXISTS(SELECT 1 FROM public.tournament_knockout_candidates WHERE tournament_id=t)
 OR EXISTS(SELECT 1 FROM public.hand_atomic_commits a JOIN public.tables tb ON tb.id=a.table_id WHERE tb.tournament_id=t)
 OR EXISTS(SELECT 1 FROM public.hand_history WHERE tournament_id=t)
 OR EXISTS(SELECT 1 FROM public.tournament_terminal_settlements WHERE tournament_id=t)
 OR EXISTS(SELECT 1 FROM public.tournament_place_settlement_batches WHERE tournament_id=t)
 OR EXISTS(SELECT 1 FROM public.tournament_rake_settlements WHERE tournament_id=t) THEN
  RAISE EXCEPTION 'BREAKFAST_LATER_AUTHORITY_OR_HAND_STATE' USING ERRCODE='55000'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tournament_escrow e WHERE e.tournament_id=t
  AND e.gross_in=170 AND e.fee_entries_in=17 AND e.prize_out=99.88
  AND e.prize_balance=53.12 AND e.fee_balance=17 AND e.bounty_balance=0
  AND e.refund_prize=0 AND e.refund_fee=0 AND e.refund_bounty=0
  AND e.fee_out=0 AND e.bounty_out=0 AND e.reserve_in=0 AND e.reserve_out=0
  AND e.overlay_in=0 AND e.satellite_in=0 AND e.satellite_fee_in=0
  AND e.closed_at IS NULL) THEN
  RAISE EXCEPTION 'BREAKFAST_FUNDING_CHANGED' USING ERRCODE='55000'; END IF;
 SELECT public.fn_safe_jsonb_array((p.payout_structure->>'payout_structure')) INTO v_structure FROM public.tournament_payouts p WHERE tournament_id=t ORDER BY id LIMIT 1;
 IF v_structure IS DISTINCT FROM v_original->'original_structure'
 OR EXISTS(SELECT 1 FROM public.tournament_payouts p WHERE tournament_id=t AND public.fn_safe_jsonb_array(p.payout_structure->>'payout_structure') IS DISTINCT FROM v_structure) THEN
  RAISE EXCEPTION 'BREAKFAST_ORIGINAL_PAID_CONTRACT_CONFLICT' USING ERRCODE='P0404'; END IF;
 v_token:=public.fn_ca_open_tournament_seat_exit_authority(t,'elimination',u);
 UPDATE public.table_seats SET left_at=clock_timestamp(),status='left',active_game_scope=NULL,active_parent_key=NULL,
  leave_pending=false,is_sitting_out=false,is_away=false
 WHERE id='41cef73d-6c47-4241-a2da-9ed9572059ad' AND user_id=u AND left_at IS NULL AND stack=0;
 IF NOT FOUND THEN RAISE EXCEPTION 'BREAKFAST_ZERO_SEAT_EXIT_LOST' USING ERRCODE='55000'; END IF;
 UPDATE public.tournament_players SET status='eliminated',position=21,prize=0,eliminated_at=clock_timestamp(),table_id=NULL,seat_number=NULL
 WHERE id='e49fdaa8-3f02-44e3-9f40-59cfbb18f1b9' AND user_id=u AND status='playing' AND chips=0 AND position IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'BREAKFAST_ORIGINAL_RANK_LOST' USING ERRCODE='55000'; END IF;
 PERFORM public.fn_ca_close_tournament_seat_exit_authority(v_token,true);
 SELECT v INTO v_target FROM jsonb_array_elements(smarter_private.breakfast_roster(t)) v WHERE v->>'user_id'=u::text;
 INSERT INTO smarter_private.breakfast_original_witness(tournament_id,operation_id,expected,expected_hash,
 original_archive_sha256,original_line,original_observed_at,original_error,original_place,original_prize,target_postimage)
 VALUES(t,p_operation_id,p_expected,md5(p_expected::text),
 'bec825a59f7ced2063d2ddc7c5d1859c30bbd1412178fc6535e25700d525366f',164263,
 '2026-09-08T14:28:11.325815271Z','TOURNAMENT_SEAT_ROSTER_REQUIRED',21,0,v_target);
 UPDATE public.tournaments SET payout_structure=v_structure::text,current_players=1 WHERE id=t;
 UPDATE public.tournament_entry_close_receipts SET payout_structure_snapshot=v_structure,updated_at=clock_timestamp() WHERE tournament_id=t;
 v_reprice:=public.fn_complete_tournament_entry_reprice(t);
 IF (v_reprice->>'ok')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'BREAKFAST_REPRICE_REFUSED: %',v_reprice USING ERRCODE='P0404'; END IF;
 -- This unchanged authority derives its sole survivor, pays only the remaining
 -- 53.12, and preserves unresolved original fees through its explicit v3
 -- custody contract. Failure rolls back the new rank, contract, witness and
 -- every attempted payment together.
 v_result:=public.fn_complete_tournament_terminal(t,survivor,'places');
 IF (SELECT cash_receipt->'original_witness' FROM public.tournament_terminal_settlements WHERE tournament_id=t)
  IS DISTINCT FROM smarter_private.breakfast_standings_witness(t,survivor) THEN
  RAISE EXCEPTION 'BREAKFAST_TERMINAL_WITNESS_CHANGED' USING ERRCODE='P0404'; END IF;
 IF (v_result->>'ok')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'BREAKFAST_TERMINAL_REFUSED: %',v_result USING ERRCODE='P0404'; END IF;
 IF (SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.id),'[]') FROM public.hand_state_snapshots s WHERE NOT is_complete AND table_id IN(SELECT id FROM public.tables WHERE tournament_id=t)) IS DISTINCT FROM v_old_snapshots THEN
  RAISE EXCEPTION 'BREAKFAST_HISTORICAL_SNAPSHOT_CHANGED' USING ERRCODE='P0404'; END IF;
 RETURN v_result;
END $$;


ALTER FUNCTION public.fn_complete_breakfast_original_witness(p_operation_id uuid, p_expected jsonb) OWNER TO postgres;

--
-- TOC entry 7838 (class 1255 OID 1688186)
-- Name: fn_complete_cashout(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_cashout(p_cashout_id uuid, p_completed_by uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_cashout RECORD;
BEGIN
  SELECT * INTO v_cashout FROM cashout_requests WHERE id = p_cashout_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Not found'); END IF;
  IF v_cashout.status NOT IN ('pending', 'approved') THEN RETURN jsonb_build_object('success', false, 'error', 'Already ' || v_cashout.status); END IF;
  UPDATE cashout_requests SET status = 'completed', completed_at = NOW(), updated_at = NOW() WHERE id = p_cashout_id;
  RETURN jsonb_build_object('success', true, 'cashout_id', p_cashout_id, 'amount', v_cashout.amount, 'status', 'completed');
END;
$$;


ALTER FUNCTION public.fn_complete_cashout(p_cashout_id uuid, p_completed_by uuid) OWNER TO postgres;

--
-- TOC entry 6728 (class 1255 OID 54297333)
-- Name: fn_complete_club_opening_setup(uuid, uuid, text, numeric, numeric, boolean, numeric, boolean, numeric, numeric, boolean, text, text, text, numeric, boolean, text, numeric, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_club_opening_setup(p_club_id uuid, p_operation_id uuid, p_tagline text, p_rake_percent numeric, p_rake_cap_bb numeric, p_bbj_enabled boolean, p_bbj_seed numeric, p_spins_enabled boolean, p_spin_seed numeric, p_spin_max_stake numeric, p_promo_enabled boolean, p_promo_type text, p_promo_name text, p_promo_description text, p_promo_budget numeric, p_leaderboard_rewards_enabled boolean, p_leaderboard_metric text, p_leaderboard_prize_budget numeric, p_leaderboard_overlay_enabled boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_club public.clubs%ROWTYPE;
  v_existing public.club_opening_setups%ROWTYPE;
  v_rake numeric := round(COALESCE(p_rake_percent, -1), 2);
  v_cap numeric := round(COALESCE(p_rake_cap_bb, -1), 2);
  v_bbj_seed numeric := round(COALESCE(p_bbj_seed, 0), 2);
  v_spin_seed numeric := round(COALESCE(p_spin_seed, 0), 2);
  v_promo_budget numeric := round(COALESCE(p_promo_budget, 0), 2);
  v_leaderboard_budget numeric := round(COALESCE(p_leaderboard_prize_budget, 0), 2);
  v_spin_required numeric := 0;
  v_other_allocation numeric := 0;
  v_total_allocation numeric := 0;
  v_spin_result jsonb := '{}'::jsonb;
  v_pool_id uuid;
  v_bbj_after numeric := 0;
  v_promo_after numeric := 0;
  v_promotion_id uuid;
  v_leaderboard_result jsonb := '{}'::jsonb;
  v_program_version integer := 0;
  v_leaderboard_overlay boolean := COALESCE(p_leaderboard_rewards_enabled, false)
    AND COALESCE(p_leaderboard_overlay_enabled, false);
  v_bank_after numeric := 0;
  v_result jsonb;
  v_tagline text := left(regexp_replace(btrim(COALESCE(p_tagline, '')), '\s+', ' ', 'g'), 72);
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Authentication Required';
  END IF;
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'Operation ID Is Required';
  END IF;

  SELECT * INTO v_club FROM public.clubs WHERE id = p_club_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Club Not Found';
  END IF;

  -- ONLY THE OWNER CAN COMPLETE IT, AND EVERYONE ELSE IS REFUSED HERE
  -- (2026-09-23). Every setup publishes a leaderboard program, and
  -- publication accepts only the club's owner or co-owner. The
  -- platform-admin branch that used to pass this check could never commit:
  -- it activated Spins and debited the Club Bank, then the publish refused
  -- it with 42501 and rolled all of it back. A co-owner never passed here.
  -- The one actor who can complete the whole setup is the owner, so the
  -- owner is the rule, and the refusal comes before anything moves.
  IF v_club.owner_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Only The Club Owner Can Complete Opening Setup'
      USING ERRCODE = '42501';
  END IF;
  IF COALESCE(v_club.is_union, false) OR v_club.union_id IS NOT NULL THEN
    RAISE EXCEPTION 'Union-Owned Economics Must Be Configured By The Union Lead';
  END IF;

  IF char_length(v_tagline) < 3 THEN
    RAISE EXCEPTION 'Write A Custom Club Tag Line Before Completing Setup';
  END IF;
  IF v_tagline ILIKE '%all fish of all shapes and sizes are welcome%'
     AND v_club.club_id <> 25450 THEN
    RAISE EXCEPTION 'That Tag Line Belongs To Kings Club';
  END IF;

  SELECT * INTO v_existing
  FROM public.club_opening_setups
  WHERE club_id = p_club_id
  FOR UPDATE;

  IF FOUND THEN
    v_result := jsonb_build_object(
      'success', true,
      'already_completed', true,
      'club_id', p_club_id,
      'club_bank_after', v_club.chip_treasury,
      'completed_at', v_existing.completed_at,
      'operation_id', v_existing.last_operation_id
    );
    RETURN v_result;
  END IF;

  IF COALESCE(p_leaderboard_overlay_enabled, false) THEN
    RAISE EXCEPTION 'LEADERBOARD_PROMO_ONLY|Club Bank Overlay Is Not Allowed For Leaderboard Prizes'
      USING ERRCODE = '22023';
  END IF;

  IF v_rake <> -1 AND (v_rake < 0 OR v_rake > 100) THEN
    RAISE EXCEPTION 'Rake Must Use The House Schedule Or Be Between 0 And 100 Percent';
  END IF;
  IF v_cap <> -1 AND (v_cap < 0 OR v_cap IN ('NaN'::numeric,'Infinity'::numeric)) THEN
    RAISE EXCEPTION 'Rake Cap Must Use The House Schedule Or Be A Finite Nonnegative Number Of Big Blinds';
  END IF;

  IF p_bbj_enabled AND v_bbj_seed < 100 THEN
    RAISE EXCEPTION 'BBJ Requires A Minimum 100-Chip Seed';
  END IF;
  IF NOT p_bbj_enabled THEN
    v_bbj_seed := 0;
  END IF;

  IF p_spins_enabled THEN
    IF p_spin_max_stake NOT IN (1, 2, 3, 5, 10, 20, 50, 100) THEN
      RAISE EXCEPTION 'Spin Maximum Stake Is Not A Supported Board Stake';
    END IF;
    v_spin_required := public.fn_spin_required_seed(p_spin_max_stake);
    IF v_spin_seed < GREATEST(100, v_spin_required) THEN
      RAISE EXCEPTION 'Spin Seed Must Be At Least % Chips For The Selected Board',
        GREATEST(100, v_spin_required);
    END IF;
  ELSE
    v_spin_seed := 0;
  END IF;

  IF p_promo_enabled THEN
    IF p_promo_type NOT IN ('leaderboard', 'rake_race', 'milestone', 'mystery', 'high_hand') THEN
      RAISE EXCEPTION 'Promotion Type Is Not Supported';
    END IF;
    IF length(btrim(COALESCE(p_promo_name, ''))) < 3 THEN
      RAISE EXCEPTION 'Promotion Name Must Be At Least 3 Characters';
    END IF;
    IF v_promo_budget < 100 THEN
      RAISE EXCEPTION 'A New Promotion Requires A Minimum 100-Chip Budget';
    END IF;
  ELSE
    v_promo_budget := 0;
  END IF;

  IF p_leaderboard_metric NOT IN ('profit', 'hands_played', 'tournaments_won', 'roi') THEN
    RAISE EXCEPTION 'Leaderboard Metric Is Not Supported';
  END IF;
  IF p_leaderboard_rewards_enabled THEN
    IF v_leaderboard_budget < 100 THEN
      RAISE EXCEPTION 'A Prize Leaderboard Requires A Minimum 100-Chip Budget';
    END IF;
  ELSE
    v_leaderboard_budget := 0;
  END IF;

  v_other_allocation := v_bbj_seed + v_promo_budget + v_leaderboard_budget;
  v_total_allocation := v_other_allocation + v_spin_seed;
  IF COALESCE(v_club.chip_treasury, 0) < v_total_allocation THEN
    RAISE EXCEPTION 'Club Bank Has % Chips But Setup Requires %',
      COALESCE(v_club.chip_treasury, 0), v_total_allocation;
  END IF;

  -- Spin activation owns its wallet debit, reserve credit, repayment metadata,
  -- and reserve ledger. Calling it inside this function keeps all setup steps
  -- in the same database transaction.
  IF p_spins_enabled THEN
    v_spin_result := public.fn_spin_activate(
      p_club_id,
      v_spin_seed,
      p_spin_max_stake,
      'chip_treasury',
      v_actor
    );
    IF NOT COALESCE((v_spin_result ->> 'ok')::boolean, false) THEN
      RAISE EXCEPTION 'Spin Setup Failed: %', COALESCE(v_spin_result ->> 'reason', 'Unknown Reason');
    END IF;

    INSERT INTO public.club_opening_setup_funding
      (club_id, operation_id, destination, amount, balance_after, created_by)
    VALUES (
      p_club_id, p_operation_id, 'spin_reserve', v_spin_seed,
      COALESCE((v_spin_result ->> 'balance')::numeric, v_spin_seed), v_actor
    );
  END IF;

  PERFORM set_config('app.ledger_category', 'club_opening_allocation', true);
  PERFORM set_config('app.ledger_counterparty', 'opening_setup', true);
  PERFORM set_config('app.ledger_counterparty_entity', p_club_id::text, true);

  UPDATE public.clubs
  SET chip_treasury = COALESCE(chip_treasury, 0) - v_other_allocation,
      promo_balance = COALESCE(promo_balance, 0) + v_promo_budget + v_leaderboard_budget,
      tagline = v_tagline,
      default_rake_percent = v_rake,
      rake_cap = v_cap,
      bbj_enabled = p_bbj_enabled,
      bbj_rake_enabled = p_bbj_enabled,
      spins_enabled = p_spins_enabled,
      spins_preseed_amount = v_spin_seed,
      spins_wallet_funding = 'CHIP_TREASURY',
      updated_at = now()
  WHERE id = p_club_id
  RETURNING chip_treasury, promo_balance INTO v_bank_after, v_promo_after;

  IF p_bbj_enabled THEN
    SELECT pool.id INTO v_pool_id
    FROM public.bbj_pools pool
    WHERE pool.club_id = p_club_id AND pool.union_id IS NULL
    ORDER BY (pool.status = 'active') DESC, pool.created_at
    LIMIT 1
    FOR UPDATE;

    IF v_pool_id IS NULL THEN
      INSERT INTO public.bbj_pools
        (club_id, main_balance, backup_balance, promo_balance, pool_amount, status)
      VALUES (p_club_id, v_bbj_seed, 0, 0, 0, 'active')
      RETURNING id, main_balance INTO v_pool_id, v_bbj_after;
    ELSE
      UPDATE public.bbj_pools
      SET main_balance = main_balance + v_bbj_seed,
          status = 'active',
          updated_at = now()
      WHERE id = v_pool_id
      RETURNING main_balance INTO v_bbj_after;
    END IF;

    INSERT INTO public.club_opening_setup_funding
      (club_id, operation_id, destination, amount, balance_after, created_by)
    VALUES (p_club_id, p_operation_id, 'bbj_main', v_bbj_seed, v_bbj_after, v_actor);
  END IF;

  IF p_promo_enabled THEN
    INSERT INTO public.promotions (
      club_id, name, description, type, start_date, end_date, status,
      prize_pool, requirements, opt_in_required
    ) VALUES (
      p_club_id,
      left(btrim(p_promo_name), 80),
      left(btrim(COALESCE(p_promo_description, '')), 500),
      p_promo_type,
      now(),
      now() + interval '30 days',
      'active',
      v_promo_budget,
      'Created During Club Opening Setup',
      true
    ) RETURNING id INTO v_promotion_id;

    INSERT INTO public.club_opening_setup_funding
      (club_id, operation_id, destination, amount, balance_after, created_by)
    VALUES (p_club_id, p_operation_id, 'promo_wallet', v_promo_budget, v_promo_after, v_actor);
  END IF;

  -- New prize allocation is held in actual Promo; no new opening seed.
  INSERT INTO public.club_opening_setups (
    club_id, owner_id, rake_mode, rake_percent, rake_cap_bb,
    bbj_enabled, bbj_seeded_amount,
    spins_enabled, spin_seeded_amount, spin_max_stake,
    promo_enabled, promo_budget, promotion_id,
    leaderboard_rewards_enabled, leaderboard_metric, leaderboard_prize_budget,
    leaderboard_seed_remaining,
    last_operation_id
  ) VALUES (
    p_club_id, v_club.owner_id,
    CASE WHEN v_rake = -1 AND v_cap = -1 THEN 'house_schedule' ELSE 'custom' END,
    v_rake, v_cap,
    p_bbj_enabled, v_bbj_seed,
    p_spins_enabled, v_spin_seed, CASE WHEN p_spins_enabled THEN p_spin_max_stake ELSE 0 END,
    p_promo_enabled, v_promo_budget, v_promotion_id,
    p_leaderboard_rewards_enabled, p_leaderboard_metric, v_leaderboard_budget,
    0,
    p_operation_id
  );

  -- The program's current version, read under the club lock taken above.
  -- Publication locks this same club row, so nothing can publish between
  -- this read and the publish below. The hard-coded 0 this replaces refused
  -- (40001) every club that already had a program, even for Display Only.
  SELECT COALESCE(max(program.version), 0)
    INTO v_program_version
    FROM public.leaderboard_reward_program_versions program
   WHERE program.club_id = p_club_id;

  -- Leaderboards always receive an explicit program. Display-only is the
  -- safe launch default; a paid program publishes a balanced weekly
  -- top-three plan that sums exactly to the new actual Promo allocation.
  -- New Club Bank overlays are refused before allocations.
  v_leaderboard_result := public.fn_publish_leaderboard_reward_program(
    p_club_id,
    p_leaderboard_rewards_enabled,
    p_leaderboard_metric,
    CASE WHEN p_leaderboard_rewards_enabled THEN jsonb_build_array(
      jsonb_build_object('rank', 1, 'amount', round(v_leaderboard_budget * 0.50, 2)),
      jsonb_build_object('rank', 2, 'amount', round(v_leaderboard_budget * 0.30, 2)),
      jsonb_build_object('rank', 3, 'amount', v_leaderboard_budget
        - round(v_leaderboard_budget * 0.50, 2)
        - round(v_leaderboard_budget * 0.30, 2))
    ) ELSE '[]'::jsonb END,
    '[]'::jsonb,
    'balanced',
    v_program_version,
    p_operation_id,
    v_leaderboard_overlay
  );

  IF p_leaderboard_rewards_enabled THEN
    INSERT INTO public.club_opening_setup_funding
      (club_id, operation_id, destination, amount, balance_after, created_by)
    VALUES (
      p_club_id, p_operation_id, 'leaderboard_prizes',
      v_leaderboard_budget, v_promo_after, v_actor
    );
  END IF;


  v_result := jsonb_build_object(
    'success', true,
    'already_completed', false,
    'club_id', p_club_id,
    'club_bank_after', v_bank_after,
    'allocated', v_total_allocation,
    'bbj_seeded', v_bbj_seed,
    'spin_seeded', v_spin_seed,
    'promo_budget', v_promo_budget,
    'promotion_id', v_promotion_id,
    'leaderboard_rewards_enabled', p_leaderboard_rewards_enabled,
    'leaderboard_prize_budget', v_leaderboard_budget,
    'leaderboard_overlay_enabled', v_leaderboard_overlay,
    'leaderboard', v_leaderboard_result,
    'spin', v_spin_result,
    'operation_id', p_operation_id
  );
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_complete_club_opening_setup(p_club_id uuid, p_operation_id uuid, p_tagline text, p_rake_percent numeric, p_rake_cap_bb numeric, p_bbj_enabled boolean, p_bbj_seed numeric, p_spins_enabled boolean, p_spin_seed numeric, p_spin_max_stake numeric, p_promo_enabled boolean, p_promo_type text, p_promo_name text, p_promo_description text, p_promo_budget numeric, p_leaderboard_rewards_enabled boolean, p_leaderboard_metric text, p_leaderboard_prize_budget numeric, p_leaderboard_overlay_enabled boolean) OWNER TO postgres;

