--
-- TOC entry 8712 (class 1255 OID 30773882)
-- Name: fn_complete_horse_tuner_study(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_horse_tuner_study(p_payload text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    SET lock_timeout TO '2s'
    AS $_$
DECLARE r jsonb; day date; ids uuid[]; count_studied integer; digest text;
  previous public.horse_tuner_study_completions%ROWTYPE;
BEGIN
  IF p_payload IS NULL OR octet_length(p_payload)>100000 THEN
    RETURN jsonb_build_object('version',1,'status','unavailable','reason','invalid_request');
  END IF;
  BEGIN
    r:=p_payload::jsonb; day:=(r->>'runDate')::date;
    count_studied:=(r->>'studied')::integer;
    IF jsonb_typeof(r) IS DISTINCT FROM 'object'
      OR r->'version' IS DISTINCT FROM '1'::jsonb
      OR (r->>'runDate') IS DISTINCT FROM to_char(day,'YYYY-MM-DD')
      OR day IS NULL OR count_studied IS NULL
      OR coalesce(r->>'studied','') !~ '^(0|[1-9][0-9]*)$'
      OR count_studied NOT BETWEEN 0 AND 2048
      OR jsonb_typeof(r->'horseIds') IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'invalid request' USING ERRCODE='22023';
    END IF;
    IF jsonb_array_length(r->'horseIds')>2048 THEN
      RAISE EXCEPTION 'invalid request' USING ERRCODE='22023';
    END IF;
    SELECT coalesce(array_agg(x::uuid ORDER BY x::uuid),ARRAY[]::uuid[]) INTO ids
      FROM jsonb_array_elements_text(r->'horseIds') x;
    IF EXISTS(SELECT 1 FROM unnest(ids) u WHERE u IS NULL)
      OR cardinality(ids)<>(SELECT count(DISTINCT u) FROM unnest(ids) u)
      OR r->'horseIds' IS DISTINCT FROM to_jsonb(ids)
      OR count_studied<cardinality(ids)
      OR p_payload IS DISTINCT FROM format('{"version":1,"runDate":"%s","studied":%s,"horseIds":%s}',
        to_char(day,'YYYY-MM-DD'),count_studied,array_to_json(ids)::text) THEN
      RAISE EXCEPTION 'invalid request' USING ERRCODE='22023';
    END IF;
  EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format
    OR datetime_field_overflow OR numeric_value_out_of_range OR invalid_parameter_value THEN
    RETURN jsonb_build_object('version',1,'status','unavailable','reason','invalid_request');
  END;
  digest:=encode(sha256(convert_to(p_payload,'UTF8')),'hex');
  IF NOT pg_try_advisory_xact_lock(hashtextextended('horse-tuner-study:'||day::text,0)) THEN
    RETURN jsonb_build_object('version',1,'status','unavailable','reason','study_busy');
  END IF;
  SELECT * INTO previous FROM public.horse_tuner_study_completions c WHERE c.run_date=day;
  IF FOUND THEN
    IF previous.request_hash<>digest THEN
      RETURN jsonb_build_object('version',1,'status','unavailable','reason','study_conflict');
    END IF;
    RETURN jsonb_build_object('version',1,'status','recorded','runDate',to_char(day,'YYYY-MM-DD'),
      'requestHash',digest,'eligible',cardinality(ids),'replayed',true);
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.horse_tuner_study_rosters s
    WHERE s.run_date=day AND s.request_hash=digest) THEN
    RETURN jsonb_build_object('version',1,'status','unavailable','reason','study_roster_mismatch');
  END IF;
  -- Bind completion to the immutable receipt AND its original audit row,
  -- not merely the presence of some horse's log for this date.
  IF EXISTS(SELECT 1 FROM unnest(ids) horse
    WHERE NOT EXISTS(SELECT 1 FROM public.horse_tuner_write_receipts w
      JOIN public.horse_self_tune_log a ON a.id=w.audit_id
        AND a.horse_id=w.horse_id::text AND a.run_date=w.run_date
      WHERE w.horse_id=horse AND w.run_date=day)) THEN
    RETURN jsonb_build_object('version',1,'status','unavailable','reason','unfinished_horses');
  END IF;
  INSERT INTO public.horse_tuner_study_completions(run_date,request_hash,eligible_horses,studied)
    VALUES(day,digest,ids,count_studied);
  RETURN jsonb_build_object('version',1,'status','recorded','runDate',to_char(day,'YYYY-MM-DD'),
    'requestHash',digest,'eligible',cardinality(ids),'replayed',false);
END;
$_$;


ALTER FUNCTION public.fn_complete_horse_tuner_study(p_payload text) OWNER TO postgres;

--
-- TOC entry 8363 (class 1255 OID 5802123)
-- Name: fn_complete_media_upload(uuid, integer, integer, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_media_upload(p_media_id uuid, p_width integer DEFAULT NULL::integer, p_height integer DEFAULT NULL::integer, p_duration_seconds numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_role text;
  v_caller_uid uuid;
  v_owner uuid;
  v_rowcount integer := 0;
BEGIN
  IF p_media_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'media_id required');
  END IF;

  v_caller_role := COALESCE(current_setting('request.jwt.claims', true)::jsonb ->> 'role', '');
  v_caller_uid := auth.uid();

  SELECT uploader_id INTO v_owner FROM public.social_media WHERE id = p_media_id;
  IF v_owner IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'media not found');
  END IF;

  IF v_caller_role = 'authenticated' THEN
    IF v_caller_uid IS NULL OR v_owner <> v_caller_uid THEN
      RAISE WARNING 'fn_complete_media_upload: % is not owner of media %', v_caller_uid, p_media_id;
      RETURN jsonb_build_object('success', false, 'error', 'forbidden');
    END IF;
  ELSIF v_caller_role = 'anon' OR v_caller_role = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'unauthorized');
  END IF;

  UPDATE public.social_media
  SET
    width = COALESCE(p_width, width),
    height = COALESCE(p_height, height),
    duration_seconds = COALESCE(p_duration_seconds, duration_seconds)
  WHERE id = p_media_id;

  GET DIAGNOSTICS v_rowcount = ROW_COUNT;

  RETURN jsonb_build_object('success', v_rowcount > 0, 'media_id', p_media_id);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_complete_media_upload failed for media %: % %', p_media_id, SQLERRM, SQLSTATE;
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION public.fn_complete_media_upload(p_media_id uuid, p_width integer, p_height integer, p_duration_seconds numeric) OWNER TO postgres;

--
-- TOC entry 8614 (class 1255 OID 38571046)
-- Name: fn_complete_sep8_spin_original_standings(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_sep8_spin_original_standings(p_operation_id uuid, p_expected jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    SET statement_timeout TO '30s'
    SET lock_timeout TO '3s'
    AS $$
DECLARE t uuid; tab uuid; survivor uuid; original jsonb; actual jsonb; manager jsonb; result jsonb;
 r smarter_private.spin_original_standings%ROWTYPE; boundary bigint; funding jsonb;
BEGIN
 IF public.fn_caller_is_engine() IS DISTINCT FROM true THEN RAISE EXCEPTION 'service authority required' USING ERRCODE='28000'; END IF;
 IF p_operation_id IS NULL OR jsonb_typeof(p_expected) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'SPIN_ORIGINAL_REQUEST_REQUIRED' USING ERRCODE='22023'; END IF;
 t:=(p_expected->>'tournament_id')::uuid;
 original:=smarter_private.spin_original_retained_case(t);
 IF original IS NULL THEN RAISE EXCEPTION 'SPIN_ORIGINAL_EVENT_NOT_NAMED' USING ERRCODE='22023'; END IF;
 SELECT (v->>'user_id')::uuid INTO survivor FROM jsonb_array_elements(original->'roster') v WHERE v->>'status'='playing';
 tab:=(original->'tables'->0->>'id')::uuid;
 boundary:=(original->'candidates'->0->>'hand_number')::bigint;
 PERFORM public.fn_ca_lock_settlement_lane_for_finish(t);
 IF public.fn_platform_frozen() IS DISTINCT FROM false THEN RAISE EXCEPTION 'PLATFORM_FROZEN' USING ERRCODE='55000'; END IF;
 PERFORM 1 FROM public.tournaments WHERE id=t FOR UPDATE;
 SELECT * INTO r FROM smarter_private.spin_original_standings WHERE tournament_id=t;
 IF FOUND THEN
  IF r.operation_id IS DISTINCT FROM p_operation_id OR r.expected IS DISTINCT FROM p_expected THEN
   RAISE EXCEPTION 'SPIN_ORIGINAL_REPLAY_MISMATCH' USING ERRCODE='55000'; END IF;
  result:=public.fn_ca_tournament_terminal_receipt(t,survivor);
  IF (SELECT cash_receipt->'original_standings' FROM public.tournament_terminal_settlements WHERE tournament_id=t)
    IS DISTINCT FROM smarter_private.spin_original_standings_witness(t,survivor) THEN
   RAISE EXCEPTION 'SPIN_ORIGINAL_TERMINAL_WITNESS_CHANGED' USING ERRCODE='P0404'; END IF;
  RETURN result;
 END IF;
 PERFORM 1 FROM public.engine_tournament_leases WHERE tournament_id=t FOR UPDATE;
 SELECT to_jsonb(l)-ARRAY['heartbeat_at','acquired_at'] INTO manager FROM public.engine_tournament_leases l WHERE tournament_id=t;
 IF manager IS NULL OR manager->>'protocol_version'<>'2' OR manager->>'lease_generation' IS NULL
 OR p_expected IS DISTINCT FROM jsonb_build_object('tournament_id',t,'manager',manager,'snapshot',original) THEN
  RAISE EXCEPTION 'SPIN_ORIGINAL_EXPECTED_OR_MANAGER_CHANGED' USING ERRCODE='55000'; END IF;
 PERFORM 1 FROM public.tournament_players WHERE tournament_id=t ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.tournament_obligations WHERE tournament_id=t ORDER BY kind,place,id FOR UPDATE;
 PERFORM 1 FROM public.tournament_escrow WHERE tournament_id=t FOR UPDATE;
 PERFORM 1 FROM public.tournament_entry_close_receipts WHERE tournament_id=t FOR UPDATE;
 PERFORM 1 FROM public.tables WHERE tournament_id=t ORDER BY id FOR UPDATE;
 PERFORM s.id FROM public.table_seats s JOIN public.tables b ON b.id=s.table_id WHERE b.tournament_id=t ORDER BY s.id FOR UPDATE OF s;
 PERFORM 1 FROM public.tournament_knockout_candidates WHERE tournament_id=t ORDER BY id FOR SHARE;
 PERFORM a.hand_id FROM public.hand_atomic_commits a JOIN public.tables b ON b.id=a.table_id WHERE b.tournament_id=t AND a.hand_number>=boundary ORDER BY a.hand_id FOR SHARE OF a;
 PERFORM 1 FROM public.hand_history WHERE tournament_id=t AND hand_number>=boundary ORDER BY id FOR SHARE;
 PERFORM k.hand_id FROM public.settlement_idempotency_keys k JOIN public.tables b ON b.id=k.table_id WHERE b.tournament_id=t ORDER BY k.hand_id FOR SHARE OF k;
 PERFORM 1 FROM public.chip_ledger WHERE tournament_id=t OR from_entity_id=t OR to_entity_id=t ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.rake_records WHERE tournament_id=t ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.tournament_refund_entitlements WHERE tournament_id=t ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.spin_reserve_ledger WHERE tournament_id=t ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.managed_game_contract_versions WHERE game_id=t ORDER BY id FOR SHARE;
 actual:=smarter_private.spin_original_current_case(t);
 IF (actual #- '{tournament,level_started_at}' #- '{tournament,blind_level_state,index}')
 IS DISTINCT FROM (original #- '{tournament,level_started_at}' #- '{tournament,blind_level_state,index}') THEN RAISE EXCEPTION 'SPIN_ORIGINAL_PREIMAGE_CHANGED' USING ERRCODE='55000'; END IF;
 IF EXISTS(SELECT 1 FROM public.engine_table_leases WHERE table_id=tab)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_hand_permits WHERE tournament_id=t)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_operations WHERE tournament_id=t)
 OR EXISTS(SELECT 1 FROM public.hand_state_snapshots WHERE table_id=tab AND NOT is_complete)
 OR EXISTS(SELECT 1 FROM public.hand_private_state WHERE table_id=tab)
 OR EXISTS(SELECT 1 FROM public.tournament_place_settlement_batches WHERE tournament_id=t)
 OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_sources WHERE tournament_id=t)
 OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches WHERE tournament_id=t)
 OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_recognitions WHERE tournament_id=t)
 OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_custody_obligations WHERE tournament_id=t) THEN
  RAISE EXCEPTION 'SPIN_ORIGINAL_LATER_AUTHORITY' USING ERRCODE='55000'; END IF;
 -- Existing original charge/reserve/scope proof owns funding. Standings do not
 -- infer earning authority from a remaining fee balance.
 funding:=public.fn_ca_sep8_spin_original_fee_proof(t);
 IF (funding->>'recognized_contributors')::integer IS DISTINCT FROM 3
 OR (funding->>'fee')::numeric IS DISTINCT FROM (original->'escrow'->>'fee_balance')::numeric THEN
  RAISE EXCEPTION 'SPIN_ORIGINAL_FUNDING_CHANGED' USING ERRCODE='P0404'; END IF;
 INSERT INTO smarter_private.spin_original_standings(tournament_id,operation_id,winner_id,expected,expected_hash)
 VALUES(t,p_operation_id,survivor,p_expected,md5(p_expected::text));
 result:=public.fn_complete_tournament_terminal(t,survivor,'places');
 IF (result->>'ok')::boolean IS DISTINCT FROM true
 OR (SELECT cash_receipt->'original_standings' FROM public.tournament_terminal_settlements WHERE tournament_id=t)
   IS DISTINCT FROM smarter_private.spin_original_standings_witness(t,survivor) THEN
  RAISE EXCEPTION 'SPIN_ORIGINAL_TERMINAL_WITNESS_CHANGED' USING ERRCODE='P0404'; END IF;
 RETURN result;
END $$;


ALTER FUNCTION public.fn_complete_sep8_spin_original_standings(p_operation_id uuid, p_expected jsonb) OWNER TO postgres;

--
-- TOC entry 8623 (class 1255 OID 55307362)
-- Name: fn_complete_stage_resume(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_stage_resume(p_tournament_id uuid, p_resume_id uuid, p_lease_generation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_receipt public.tournament_stage_resume_receipts%ROWTYPE;
  v_done public.tournament_stage_transitions%ROWTYPE;
  v_count integer;
  v_total numeric;
  v_unseated integer;
  v_facts jsonb;
  v_started timestamptz;
BEGIN
  IF NOT public.fn_capability_available('tournament.multi_day.single_flight') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'capability_unavailable');
  END IF;
  IF p_tournament_id IS NULL OR p_resume_id IS NULL OR p_lease_generation IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_request');
  END IF;
  SELECT * INTO v_receipt FROM public.tournament_stage_resume_receipts
   WHERE tournament_id = p_tournament_id AND resume_id = p_resume_id;
  IF FOUND AND v_receipt.completed_at IS NOT NULL THEN
    SELECT * INTO v_done FROM public.tournament_stage_transitions
     WHERE idempotency_key = 'resume_complete:' || p_tournament_id::text || ':' || v_receipt.stage_no::text;
    RETURN v_done.facts || jsonb_build_object('ok', true, 'replay', true);
  END IF;

  IF NOT public.fn_multi_day_lease_is_current(p_tournament_id, p_lease_generation) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'lease_lost');
  END IF;
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id, NULL);
  SELECT * INTO v_t FROM public.tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found');
  END IF;
  SELECT * INTO v_receipt FROM public.tournament_stage_resume_receipts
   WHERE tournament_id = p_tournament_id AND resume_id = p_resume_id FOR UPDATE;
  IF NOT FOUND OR v_receipt.lease_generation IS DISTINCT FROM p_lease_generation THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'resume_receipt_mismatch');
  END IF;
  IF v_receipt.completed_at IS NOT NULL THEN
    SELECT * INTO v_done FROM public.tournament_stage_transitions
     WHERE idempotency_key = 'resume_complete:' || p_tournament_id::text || ':' || v_receipt.stage_no::text;
    RETURN v_done.facts || jsonb_build_object('ok', true, 'replay', true);
  END IF;
  IF v_t.status IS DISTINCT FROM 'BAGGED' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_bagged', 'status', v_t.status);
  END IF;
  IF (SELECT s.state FROM public.tournament_stages s
       WHERE s.tournament_id = p_tournament_id AND s.stage_no = v_receipt.stage_no FOR UPDATE)
     IS DISTINCT FROM 'resuming' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'stage_not_resuming');
  END IF;

  SELECT count(*), COALESCE(sum(e.stack), 0), count(*) FILTER (WHERE e.state <> 'consumed')
    INTO v_count, v_total, v_unseated
    FROM public.tournament_qualification_entitlements e
   WHERE e.tournament_id = p_tournament_id AND e.target_stage_no = v_receipt.stage_no;
  IF v_unseated > 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unseated_entitlements', 'unseated', v_unseated);
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_qualification_entitlements e
               LEFT JOIN public.table_seats s ON s.id = e.consumed_seat_id
               LEFT JOIN public.tournament_players p ON p.id = e.source_registration_id
              WHERE e.tournament_id = p_tournament_id AND e.target_stage_no = v_receipt.stage_no
                AND (s.id IS NULL OR s.left_at IS NOT NULL OR s.user_id IS DISTINCT FROM e.user_id
                     OR s.stack IS DISTINCT FROM e.stack OR s.table_id IS DISTINCT FROM e.consumed_table_id
                     OR p.status::text IS DISTINCT FROM 'playing' OR p.chips::numeric IS DISTINCT FROM e.stack
                     OR COALESCE(p.current_bounty, 0) IS DISTINCT FROM e.bounty_head
                     OR p.table_id IS DISTINCT FROM s.table_id OR p.seat_number IS DISTINCT FROM s.seat_number))
     OR (SELECT count(*) FROM public.table_seats s JOIN public.tables tb ON tb.id = s.table_id
          WHERE tb.tournament_id = p_tournament_id AND s.left_at IS NULL) <> v_count
     OR (SELECT COALESCE(sum(s.stack), 0) FROM public.table_seats s JOIN public.tables tb ON tb.id = s.table_id
          WHERE tb.tournament_id = p_tournament_id AND s.left_at IS NULL) <> v_total
     OR (SELECT COALESCE(sum(p.chips), 0) FROM public.tournament_players p
          WHERE p.tournament_id = p_tournament_id AND p.status::text = 'playing') <> v_total THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'seats_differ_from_entitlements');
  END IF;

  v_started := clock_timestamp();
  v_facts := jsonb_build_object('resume_id', p_resume_id, 'stage_no', v_receipt.stage_no,
    'status', 'RUNNING', 'players', v_count, 'total_chips', v_total,
    'current_level', (v_receipt.first_level ->> 'index')::integer,
    'level_started_at', v_started, 'level_duration_ms', (v_receipt.first_level ->> 'duration_ms')::bigint);

  -- Status first: both doors admit BAGGED -> RUNNING only while this receipt
  -- is still incomplete. The stage's first level starts now (its full
  -- duration remains), so the engine's derived clock needs no stored offset.
  PERFORM set_config('app.atomic_stage_resume', p_tournament_id::text || ':' || p_resume_id::text, true);
  UPDATE public.tournaments
     SET status = 'RUNNING', level_started_at = v_started, on_break = false
   WHERE id = p_tournament_id;
  PERFORM set_config('app.atomic_stage_resume', '', true);
  IF (SELECT status FROM public.tournaments WHERE id = p_tournament_id) IS DISTINCT FROM 'RUNNING' THEN
    RAISE EXCEPTION 'MULTI_DAY_RESUME_STATUS_NOT_ACKNOWLEDGED' USING ERRCODE = '55000';
  END IF;

  PERFORM set_config('app.multi_day_stage_writer', p_tournament_id::text, true);
  UPDATE public.tournament_stage_resume_receipts
     SET completed_at = v_started
   WHERE tournament_id = p_tournament_id AND stage_no = v_receipt.stage_no;
  INSERT INTO public.tournament_stage_transitions
    (tournament_id, stage_no, kind, idempotency_key, lease_generation, facts)
  VALUES (p_tournament_id, v_receipt.stage_no, 'resume_complete',
          'resume_complete:' || p_tournament_id::text || ':' || v_receipt.stage_no::text,
          p_lease_generation, v_facts);
  UPDATE public.tournament_stages
     SET state = 'running', state_changed_at = v_started
   WHERE tournament_id = p_tournament_id AND stage_no = v_receipt.stage_no;
  UPDATE public.tournament_stages
     SET state = 'closed', state_changed_at = v_started
   WHERE tournament_id = p_tournament_id AND stage_no = v_receipt.stage_no - 1;
  PERFORM set_config('app.multi_day_stage_writer', '', true);
  RETURN v_facts || jsonb_build_object('ok', true, 'replay', false);
END
$$;


ALTER FUNCTION public.fn_complete_stage_resume(p_tournament_id uuid, p_resume_id uuid, p_lease_generation uuid) OWNER TO postgres;

--
-- TOC entry 5425 (class 1255 OID 24464894)
-- Name: fn_complete_tournament_entry_reprice(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_tournament_entry_reprice(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_receipt public.tournament_entry_close_receipts%ROWTYPE;
  v_mismatch integer;
BEGIN
  -- Match the lock order used by close/finalize and the satellite entitlement
  -- workflow: tournament first, then its child receipt. Taking these in the
  -- opposite order lets a close replay (tournament -> receipt) deadlock a
  -- completion attempt (receipt -> tournament) exactly when recovery is trying
  -- to prove the durable obligation complete.
  SELECT * INTO v_t
    FROM public.tournaments t
   WHERE t.id=p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','not_found'); END IF;

  SELECT * INTO v_receipt
    FROM public.tournament_entry_close_receipts r
   WHERE r.tournament_id=p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','receipt_missing'); END IF;
  IF v_receipt.reprice_completed_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok',true,'already_completed',true,'mismatches',0);
  END IF;
  IF COALESCE(v_t.prize_pool_finalized,false) IS NOT TRUE
     OR round(COALESCE(v_t.prize_pool,0),2)<>round(v_receipt.final_prize_pool,2)
     OR public.fn_safe_jsonb_array(v_t.payout_structure::text)
        IS DISTINCT FROM v_receipt.payout_structure_snapshot THEN
    RETURN jsonb_build_object('ok',false,'reason','final_pool_or_structure_drifted');
  END IF;

  IF lower(COALESCE(v_t.variant,''))='satellite'
     OR upper(COALESCE(v_t.tournament_type,''))='SATELLITE'
     OR v_t.satellite_target_id IS NOT NULL
     OR v_t.satellite_target IS NOT NULL THEN
    -- Satellite closeout remains under its existing seat-award contract.
    SELECT count(*)::integer INTO v_mismatch
      FROM public.tournament_players tp
      CROSS JOIN LATERAL (
        SELECT public.fn_tournament_place_prize_exact(
          v_receipt.final_prize_pool,
          v_receipt.payout_structure_snapshot::text,
          tp.position,
          public.fn_ca_tournament_unit_cents(p_tournament_id)) AS expected
      ) entitlement
     WHERE tp.tournament_id=p_tournament_id
       AND tp.status='eliminated'
       AND (
         -- An eliminated row without its finishing place is unfinished causal
         -- work, not a zero-dollar entitlement. Letting it disappear from this
         -- proof would retire the close receipt before any later process can
         -- know which place must be repriced.
         tp.position IS NULL
         OR round(COALESCE(tp.prize,0),2) IS DISTINCT FROM round(entitlement.expected,2)
         OR (
           entitlement.expected>0
           AND (
             SELECT round(COALESCE(sum(p.amount),0),2)
               FROM public.tournament_payouts p
              WHERE p.tournament_id=p_tournament_id
                AND p.user_id=tp.user_id
                AND p.position=tp.position
                AND COALESCE(p.source,'')<>'satellite_seat'
           ) IS DISTINCT FROM round(entitlement.expected,2)
         )
       );
  ELSE
    -- Entry closure proves the cached result facts, not payment. Cash places
    -- are paid only by the terminal authority, so requiring a payout here
    -- leaves every positive unpaid finisher pending forever. Derive once with
    -- that same authority, including its final-field trim and Bubble reserve.
    WITH amounts AS MATERIALIZED (
      SELECT place,amount
        FROM public.fn_ca_tournament_place_amounts(p_tournament_id)
    )
    SELECT count(*)::integer INTO v_mismatch
      FROM public.tournament_players tp
      LEFT JOIN amounts a ON a.place=tp.position
     WHERE tp.tournament_id=p_tournament_id
       AND tp.status='eliminated'
       AND (tp.position IS NULL
            OR tp.prize IS DISTINCT FROM COALESCE(a.amount,0));
  END IF;
  IF v_mismatch>0 THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','reprice_incomplete','mismatches',v_mismatch);
  END IF;

  UPDATE public.tournament_entry_close_receipts
     SET reprice_completed_at=clock_timestamp(),updated_at=clock_timestamp()
   WHERE tournament_id=p_tournament_id;
  RETURN jsonb_build_object('ok',true,'completed',true,'mismatches',0);
END;
$$;


ALTER FUNCTION public.fn_complete_tournament_entry_reprice(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 5700 (class 1255 OID 24465453)
-- Name: fn_complete_tournament_launch_atomic(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_tournament_launch_atomic(p_tournament_id uuid, p_launch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_format text;
  v_protocol_version integer;
BEGIN
  SELECT l.protocol_version INTO v_protocol_version
    FROM public.engine_tournament_leases l
   WHERE l.tournament_id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND OR v_protocol_version >= 2 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'legacy_launch_protocol_closed');
  END IF;
  v_format := public.fn_ca_tournament_recorded_format(p_tournament_id);
  IF v_format='mtt-v2' THEN
    RETURN jsonb_build_object('ok',false,'reason','launch_format_argument_required','format_contract',v_format);
  END IF;

  RETURN (public.fn_complete_tournament_launch_before_lease_generation(
    p_tournament_id,
    p_launch_id
  )) || jsonb_build_object('format_contract',v_format);
END;
$$;


ALTER FUNCTION public.fn_complete_tournament_launch_atomic(p_tournament_id uuid, p_launch_id uuid) OWNER TO postgres;

--
-- TOC entry 8649 (class 1255 OID 24465465)
-- Name: fn_complete_tournament_launch_atomic(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_complete_tournament_launch_atomic(p_tournament_id uuid, p_launch_id uuid, p_lease_generation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_format text;
  v_current_generation uuid;
  v_protocol_version integer;
  v_heartbeat_at timestamptz;
  v_receipt_generation uuid;
  v_receipt_launch_id uuid;
  v_result jsonb;
BEGIN
  IF p_tournament_id IS NULL OR p_launch_id IS NULL OR p_lease_generation IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_launch_request');
  END IF;

  SELECT l.lease_generation, l.protocol_version, l.heartbeat_at
    INTO v_current_generation, v_protocol_version, v_heartbeat_at
    FROM public.engine_tournament_leases l
   WHERE l.tournament_id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND
     OR v_protocol_version IS DISTINCT FROM 2
     OR v_current_generation IS DISTINCT FROM p_lease_generation
     OR v_heartbeat_at < clock_timestamp() - interval '30 seconds' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'launch_lease_lost');
  END IF;

  SELECT r.launch_id, r.lease_generation
    INTO v_receipt_launch_id, v_receipt_generation
    FROM public.tournament_launch_receipts r
   WHERE r.tournament_id = p_tournament_id
   FOR UPDATE;
  IF NOT FOUND
     OR v_receipt_launch_id IS DISTINCT FROM p_launch_id
     OR v_receipt_generation IS DISTINCT FROM p_lease_generation THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'launch_receipt_mismatch');
  END IF;

  v_format := public.fn_ca_tournament_recorded_format(p_tournament_id);
  IF v_format='mtt-v2' THEN
    RETURN jsonb_build_object('ok',false,'reason','launch_format_argument_required','format_contract',v_format);
  END IF;

  v_result := public.fn_complete_tournament_launch_before_lease_generation(
    p_tournament_id,
    p_launch_id
  );
  RETURN v_result || jsonb_build_object('lease_generation', p_lease_generation,
    'format_contract', v_format);
END;
$$;


ALTER FUNCTION public.fn_complete_tournament_launch_atomic(p_tournament_id uuid, p_launch_id uuid, p_lease_generation uuid) OWNER TO postgres;

