--

CREATE TABLE public.video_source_masters (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    video_id uuid NOT NULL,
    rights_evidence_id uuid NOT NULL,
    storage_bucket text DEFAULT 'video-source-masters'::text NOT NULL,
    storage_path text NOT NULL,
    sha256 text NOT NULL,
    mime_type text NOT NULL,
    byte_size bigint NOT NULL,
    duration_seconds numeric(10,3) NOT NULL,
    width integer NOT NULL,
    height integer NOT NULL,
    status text DEFAULT 'ready'::text NOT NULL,
    uploaded_by uuid NOT NULL,
    verified_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT video_source_masters_byte_size_check CHECK (((byte_size >= 1024) AND (byte_size <= '5368709120'::bigint))),
    CONSTRAINT video_source_masters_duration_seconds_check CHECK (((duration_seconds > (0)::numeric) AND (duration_seconds <= (21600)::numeric))),
    CONSTRAINT video_source_masters_height_check CHECK (((height >= 16) AND (height <= 16384))),
    CONSTRAINT video_source_masters_mime_type_check CHECK ((mime_type = ANY (ARRAY['video/mp4'::text, 'video/quicktime'::text, 'video/webm'::text]))),
    CONSTRAINT video_source_masters_sha256_check CHECK ((sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT video_source_masters_status_check CHECK ((status = ANY (ARRAY['ready'::text, 'revoked'::text, 'deleted'::text]))),
    CONSTRAINT video_source_masters_storage_bucket_check CHECK ((storage_bucket = 'video-source-masters'::text)),
    CONSTRAINT video_source_masters_storage_path_check CHECK ((storage_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.source$'::text)),
    CONSTRAINT video_source_masters_version_check CHECK ((version > 0)),
    CONSTRAINT video_source_masters_width_check CHECK (((width >= 16) AND (width <= 16384)))
);


