-- TOC entry 6558 (class 1255 OID 15775919)
-- Name: fn_consume_rabbit_hunt(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_consume_rabbit_hunt(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'fn_consume_rabbit_hunt is engine-only';
  END IF;

  RETURN public.fn_consume_rabbit_hunt_v2(p_user_id, gen_random_uuid());
END;
$$;


ALTER FUNCTION public.fn_consume_rabbit_hunt(p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 4763 (class 1255 OID 23473202)
-- Name: fn_consume_rabbit_hunt_v2(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_consume_rabbit_hunt_v2(p_user_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_vip_monthly_cap CONSTANT int := 100;
  v_default_cost    CONSTANT int := 5;
  v_is_vip          boolean;
  v_is_lifetime     boolean;
  v_month           text := to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM');
  v_used            int;
  v_cost            int;
  v_row             record;
  v_deduct          jsonb;
  v_balance         integer;
  v_request_payload jsonb := jsonb_build_object(
    'feature', 'rabbit_hunt',
    'user_id', p_user_id
  );
  v_cached_kind     text;
  v_cached_payload  jsonb;
  v_cached_result   jsonb;
  v_result          jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'fn_consume_rabbit_hunt_v2 is engine-only';
  END IF;
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'User Id Required');
  END IF;
  IF p_request_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Secure Request Id Required');
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'digital_purchase_request:' || p_user_id::text || ':' || p_request_id::text,
      0
    )
  );

  SELECT r.purchase_kind, r.request_payload, r.result
    INTO v_cached_kind, v_cached_payload, v_cached_result
    FROM public.digital_purchase_receipts r
   WHERE r.user_id = p_user_id
     AND r.request_id = p_request_id;

  IF FOUND THEN
    IF v_cached_kind IS DISTINCT FROM 'rabbit_hunt'
       OR v_cached_payload IS DISTINCT FROM v_request_payload
    THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Request Id Already Used For Another Purchase',
        'code', 'REQUEST_ID_REUSED'
      );
    END IF;

    RETURN v_cached_result || jsonb_build_object(
      'diamonds_spent', 0,
      'original_diamonds_spent',
        COALESCE(
          (v_cached_result->>'original_diamonds_spent')::integer,
          (v_cached_result->>'diamonds_spent')::integer,
          0
        ),
      'idempotent', true,
      'consumed', false
    );
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('rabbit_hunt:' || p_user_id::text, 0));

  SELECT
    COALESCE(p.is_vip, false)
      AND (p.vip_tier = 'lifetime' OR p.vip_expires_at IS NULL OR p.vip_expires_at > now()),
    COALESCE(p.is_vip, false) AND p.vip_tier = 'lifetime'
    INTO v_is_vip, v_is_lifetime
    FROM public.profiles p
   WHERE p.id = p_user_id;

  IF v_is_vip IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unknown user');
  END IF;

  IF v_is_lifetime THEN
    INSERT INTO public.vip_feature_usage_monthly
      (user_id, feature, month, usage_count, updated_at)
    VALUES
      (p_user_id, 'rabbit_hunt', v_month, 1, now())
    ON CONFLICT (user_id, feature, month) DO UPDATE
       SET usage_count = public.vip_feature_usage_monthly.usage_count + 1,
           updated_at = now();

    v_result := jsonb_build_object(
      'success', true,
      'source', 'lifetime_vip',
      'unlimited', true,
      'vip_remaining', null,
      'diamonds_spent', 0,
      'idempotent', false,
      'consumed', true
    );
    INSERT INTO public.digital_purchase_receipts
      (user_id, request_id, purchase_kind, request_payload, result)
    VALUES
      (p_user_id, p_request_id, 'rabbit_hunt', v_request_payload, v_result);
    RETURN v_result;
  END IF;

  -- AN EXPIRING CREDIT IS SPENT BEFORE AN ALLOWANCE THAT RENEWS. A daily
  -- bonus credit lives seven days; the VIP allowance comes back on the
  -- first. Soonest to expire first.
  SELECT id, uses_remaining, source INTO v_row
    FROM public.feature_purchases
   WHERE user_id = p_user_id
     AND feature = 'rabbit_hunt'
     AND COALESCE(uses_remaining, 0) > 0
     AND expires_at IS NOT NULL
     AND expires_at > now()
   ORDER BY expires_at ASC, created_at ASC
   FOR UPDATE
   LIMIT 1;

  IF FOUND THEN
    UPDATE public.feature_purchases
       SET uses_remaining = uses_remaining - 1
     WHERE id = v_row.id;

    v_result := jsonb_build_object(
      'success', true,
      'source', 'purchased',
      'expiring', true,
      'credit_source', v_row.source,
      'uses_remaining', v_row.uses_remaining - 1,
      'diamonds_spent', 0,
      'idempotent', false,
      'consumed', true
    );
    INSERT INTO public.digital_purchase_receipts
      (user_id, request_id, purchase_kind, request_payload, result)
    VALUES
      (p_user_id, p_request_id, 'rabbit_hunt', v_request_payload, v_result);
    RETURN v_result;
  END IF;

  IF v_is_vip THEN
    SELECT COALESCE(SUM(usage_count), 0)::int INTO v_used
      FROM public.vip_feature_usage_monthly
     WHERE user_id = p_user_id
       AND feature = 'rabbit_hunt'
       AND month = v_month;

    IF v_used < v_vip_monthly_cap THEN
      INSERT INTO public.vip_feature_usage_monthly
        (user_id, feature, month, usage_count, updated_at)
      VALUES
        (p_user_id, 'rabbit_hunt', v_month, 1, now())
      ON CONFLICT (user_id, feature, month) DO UPDATE
         SET usage_count = public.vip_feature_usage_monthly.usage_count + 1,
             updated_at = now();

      v_result := jsonb_build_object(
        'success', true,
        'source', 'vip_monthly',
        'vip_used', v_used + 1,
        'vip_remaining', v_vip_monthly_cap - (v_used + 1),
        'diamonds_spent', 0,
        'idempotent', false,
        'consumed', true
      );
      INSERT INTO public.digital_purchase_receipts
        (user_id, request_id, purchase_kind, request_payload, result)
      VALUES
        (p_user_id, p_request_id, 'rabbit_hunt', v_request_payload, v_result);
      RETURN v_result;
    END IF;
  END IF;

  SELECT id, uses_remaining, source INTO v_row
    FROM public.feature_purchases
   WHERE user_id = p_user_id
     AND feature = 'rabbit_hunt'
     AND COALESCE(uses_remaining, 0) > 0
     AND (expires_at IS NULL OR expires_at > now())
   ORDER BY created_at
   FOR UPDATE
   LIMIT 1;

  IF FOUND THEN
    UPDATE public.feature_purchases
       SET uses_remaining = uses_remaining - 1
     WHERE id = v_row.id;

    v_result := jsonb_build_object(
      'success', true,
      'source', 'purchased',
      'credit_source', v_row.source,
      'uses_remaining', v_row.uses_remaining - 1,
      'diamonds_spent', 0,
      'idempotent', false,
      'consumed', true
    );
    INSERT INTO public.digital_purchase_receipts
      (user_id, request_id, purchase_kind, request_payload, result)
    VALUES
      (p_user_id, p_request_id, 'rabbit_hunt', v_request_payload, v_result);
    RETURN v_result;
  END IF;

  SELECT COALESCE(diamond_cost, v_default_cost) INTO v_cost
    FROM public.feature_pricing
   WHERE feature = 'rabbit_hunt'
   LIMIT 1;
  v_cost := COALESCE(v_cost, v_default_cost);

  IF v_cost < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Rabbit Hunt Pricing Is Invalid');
  END IF;

  IF v_cost > 0 THEN
    v_deduct := public.deduct_diamonds(
      p_user_id          => p_user_id,
      p_amount           => v_cost,
      p_description      => 'Rabbit Hunt',
      p_transaction_type => 'feature_purchase',
      p_source           => 'rabbit_hunt',
      p_reference_id     => 'rabbit_use_' || p_user_id::text || '_' || p_request_id::text
    );

    IF COALESCE((v_deduct->>'success')::boolean, false) IS NOT TRUE THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'insufficient_diamonds',
        'cost', v_cost,
        'diamonds_remaining', (v_deduct->>'balance')::numeric
      );
    END IF;

    IF COALESCE((v_deduct->>'idempotent')::boolean, false) THEN
      v_result := jsonb_build_object(
        'success', true,
        'source', 'diamonds',
        'diamonds_spent', 0,
        'original_diamonds_spent', v_cost,
        'diamonds_remaining', (v_deduct->>'balance')::numeric,
        'idempotent', true,
        'consumed', false
      );
      INSERT INTO public.digital_purchase_receipts
        (user_id, request_id, purchase_kind, request_payload, result)
      VALUES
        (p_user_id, p_request_id, 'rabbit_hunt', v_request_payload, v_result);
      RETURN v_result;
    END IF;
    v_balance := (v_deduct->>'balance')::integer;
  ELSE
    SELECT p.diamonds INTO v_balance
      FROM public.profiles p
     WHERE p.id = p_user_id;
  END IF;

  v_result := jsonb_build_object(
    'success', true,
    'source', 'diamonds',
    'diamonds_spent', v_cost,
    'diamonds_remaining', v_balance,
    'idempotent', false,
    'consumed', true
  );
  INSERT INTO public.digital_purchase_receipts
    (user_id, request_id, purchase_kind, request_payload, result)
  VALUES
    (p_user_id, p_request_id, 'rabbit_hunt', v_request_payload, v_result);
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_consume_rabbit_hunt_v2(p_user_id uuid, p_request_id uuid) OWNER TO postgres;

--
-- TOC entry 5564 (class 1255 OID 67021144)
-- Name: fn_consume_time_bank(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_consume_time_bank(p_user_id uuid, p_seconds integer, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_vip      boolean;
  v_is_lifetime boolean;
  v_month       text := to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM');
  v_used        int;
  v_from_vip    int := 0;
  v_remaining   int;
  v_uses_needed int;
  v_uses_taken  int := 0;
  v_expiring_taken int := 0;
  v_row         record;
  v_take        int;
  v_receipt     jsonb;
  v_result      jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'fn_consume_time_bank is engine-only';
  END IF;
  IF p_seconds IS NULL OR p_seconds <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'p_seconds must be positive');
  END IF;

  -- A REPLAY NEVER TOUCHES A BALANCE (2026-09-28). Checked before the
  -- advisory lock, before anything is read: an already-receipted request_id
  -- is answered from its own receipt, full stop.
  IF p_request_id IS NOT NULL THEN
    SELECT result INTO v_receipt
      FROM public.time_bank_consume_receipts
     WHERE request_id = p_request_id;
    IF FOUND THEN
      RETURN v_receipt || jsonb_build_object('idempotent_replay', true);
    END IF;
  END IF;

  -- A FENCED GENERATION ONLY READS ITS RECEIPT (2026-10-03). The request hook
  -- admits a fenced manager's re-ask of a lost debit under its own marker so
  -- the answer above can reach it; it never debits. No receipt: fenced.
  IF current_setting('app.smarter_data_actor', true) = 'fenced-manager-time-bank-receipt' THEN
    RAISE EXCEPTION 'TOURNAMENT_MANAGER_FENCED: lease generation is no longer current'
      USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('time_bank:' || p_user_id::text, 0));

  -- Re-check under the lock: a concurrent call with the same request_id for
  -- the same user (the retry this migration exists to make safe) serializes
  -- on the lock above and, once the first commits, is answered here instead
  -- of deducting a second time.
  IF p_request_id IS NOT NULL THEN
    SELECT result INTO v_receipt
      FROM public.time_bank_consume_receipts
     WHERE request_id = p_request_id;
    IF FOUND THEN
      RETURN v_receipt || jsonb_build_object('idempotent_replay', true);
    END IF;
  END IF;

  SELECT
    COALESCE(p.is_vip, false)
      AND (p.vip_tier = 'lifetime' OR p.vip_expires_at IS NULL OR p.vip_expires_at > now()),
    COALESCE(p.is_vip, false) AND p.vip_tier = 'lifetime'
    INTO v_is_vip, v_is_lifetime
    FROM public.profiles p
   WHERE p.id = p_user_id;

  IF v_is_vip IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unknown user');
  END IF;

  IF v_is_lifetime THEN
    INSERT INTO public.vip_feature_usage_monthly
      (user_id, feature, month, usage_count, updated_at)
    VALUES
      (p_user_id, 'time_bank_seconds', v_month, p_seconds, now())
    ON CONFLICT (user_id, feature, month) DO UPDATE
       SET usage_count = public.vip_feature_usage_monthly.usage_count + EXCLUDED.usage_count,
           updated_at = now();

    v_result := jsonb_build_object(
      'success', true,
      'source', 'lifetime_vip',
      'unlimited', true,
      'consumed_vip_seconds', p_seconds,
      'consumed_purchased_uses', 0,
      'shortfall_seconds', 0
    );
    IF p_request_id IS NOT NULL THEN
      INSERT INTO public.time_bank_consume_receipts (request_id, user_id, seconds, result)
      VALUES (p_request_id, p_user_id, p_seconds, v_result)
      ON CONFLICT (request_id) DO NOTHING;
    END IF;
    RETURN v_result;
  END IF;

  v_remaining := p_seconds;

  -- AN EXPIRING CREDIT IS SPENT BEFORE AN ALLOWANCE THAT RENEWS. A daily
  -- bonus credit lives seven days; the VIP allowance comes back on the
  -- first. One use is twenty seconds; soonest to expire first.
  v_uses_needed := CEIL(v_remaining / 20.0)::int;
  FOR v_row IN
    SELECT id, uses_remaining
      FROM public.feature_purchases
     WHERE user_id = p_user_id
       AND feature = 'time_bank_seconds'
       AND COALESCE(uses_remaining, 0) > 0
       AND expires_at IS NOT NULL
       AND expires_at > now()
     ORDER BY expires_at ASC, created_at ASC
     FOR UPDATE
  LOOP
    EXIT WHEN v_uses_needed <= 0;
    v_take := LEAST(v_row.uses_remaining, v_uses_needed);
    UPDATE public.feature_purchases
       SET uses_remaining = uses_remaining - v_take
     WHERE id = v_row.id;
    v_uses_taken := v_uses_taken + v_take;
    v_expiring_taken := v_expiring_taken + v_take;
    v_uses_needed := v_uses_needed - v_take;
  END LOOP;
  v_remaining := GREATEST(0, v_remaining - v_expiring_taken * 20);

  IF v_remaining > 0 AND v_is_vip THEN
    SELECT COALESCE(SUM(usage_count), 0)::int INTO v_used
      FROM public.vip_feature_usage_monthly
     WHERE user_id = p_user_id
       AND feature = 'time_bank_seconds'
       AND month = v_month;

    v_from_vip := LEAST(v_remaining, GREATEST(0, 120 - v_used));
    IF v_from_vip > 0 THEN
      INSERT INTO public.vip_feature_usage_monthly
        (user_id, feature, month, usage_count, updated_at)
      VALUES
        (p_user_id, 'time_bank_seconds', v_month, v_from_vip, now())
      ON CONFLICT (user_id, feature, month) DO UPDATE
         SET usage_count = public.vip_feature_usage_monthly.usage_count + EXCLUDED.usage_count,
             updated_at = now();
      v_remaining := v_remaining - v_from_vip;
    END IF;
  END IF;

  IF v_remaining > 0 THEN
    v_uses_needed := CEIL(v_remaining / 20.0)::int;
    FOR v_row IN
      SELECT id, uses_remaining
        FROM public.feature_purchases
       WHERE user_id = p_user_id
         AND feature = 'time_bank_seconds'
         AND COALESCE(uses_remaining, 0) > 0
         AND (expires_at IS NULL OR expires_at > now())
       ORDER BY created_at
       FOR UPDATE
    LOOP
      EXIT WHEN v_uses_needed <= 0;
      v_take := LEAST(v_row.uses_remaining, v_uses_needed);
      UPDATE public.feature_purchases
         SET uses_remaining = uses_remaining - v_take
       WHERE id = v_row.id;
      v_uses_taken := v_uses_taken + v_take;
      v_uses_needed := v_uses_needed - v_take;
    END LOOP;
    v_remaining := GREATEST(0, v_remaining - (v_uses_taken - v_expiring_taken) * 20);
  END IF;

  v_result := jsonb_build_object(
    'success', true,
    'consumed_vip_seconds', v_from_vip,
    'consumed_purchased_uses', v_uses_taken,
    'consumed_expiring_uses', v_expiring_taken,
    'shortfall_seconds', v_remaining
  );
  IF p_request_id IS NOT NULL THEN
    INSERT INTO public.time_bank_consume_receipts (request_id, user_id, seconds, result)
    VALUES (p_request_id, p_user_id, p_seconds, v_result)
    ON CONFLICT (request_id) DO NOTHING;
  END IF;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_consume_time_bank(p_user_id uuid, p_seconds integer, p_request_id uuid) OWNER TO postgres;

--
-- TOC entry 3960 (class 1255 OID 88482159)
-- Name: fn_count_content_engagement(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_count_content_engagement(p_content_id uuid, p_kind text, p_source text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  -- The counter's subject is the caller. Never a parameter.
  v_viewer  uuid := auth.uid();
  v_target  uuid;
  v_is_reel boolean := false;
  v_counted boolean;
BEGIN
  IF v_viewer IS NULL OR p_content_id IS NULL THEN
    RETURN false;
  END IF;
  IF p_kind IS NULL OR p_kind NOT IN ('view', 'share') THEN
    RAISE EXCEPTION 'fn_count_content_engagement: invalid kind %', p_kind USING ERRCODE = '22023';
  END IF;
  IF p_source IS NOT NULL AND p_source NOT IN ('posts', 'reels') THEN
    RAISE EXCEPTION 'fn_count_content_engagement: invalid source %', p_source USING ERRCODE = '22023';
  END IF;

  -- A reel id may be an alias of a canonical reel (social_reel_aliases), the
  -- same resolution increment_reel_count made.
  IF p_source IS DISTINCT FROM 'posts' THEN
    SELECT COALESCE(a.canonical_reel_id, p_content_id) INTO v_target
      FROM (SELECT 1) seed
      LEFT JOIN public.social_reel_aliases a ON a.alias_reel_id = p_content_id;
    v_is_reel := EXISTS (SELECT 1 FROM public.social_reels r WHERE r.id = v_target);
  END IF;
  IF NOT v_is_reel THEN
    IF p_source = 'reels' THEN
      RETURN false;
    END IF;
    v_target := p_content_id;
    IF NOT EXISTS (SELECT 1 FROM public.social_posts p WHERE p.id = v_target) THEN
      RETURN false;
    END IF;
  END IF;

  -- The receipt decides. A first view inserts; a repeat inside the day matches
  -- the conflict, fails the WHERE, and returns no row.
  INSERT INTO public.content_engagement_receipts AS r (content_id, viewer_id, kind)
  VALUES (v_target, v_viewer, p_kind)
  ON CONFLICT (content_id, viewer_id, kind) DO UPDATE
     SET counted_at = now(),
         times_counted = r.times_counted + 1
   WHERE r.counted_at < now() - interval '24 hours'
  RETURNING true INTO v_counted;

  IF v_counted IS NOT TRUE THEN
    RETURN false;
  END IF;

  IF v_is_reel THEN
    IF p_kind = 'view' THEN
      UPDATE public.social_reels SET view_count = COALESCE(view_count, 0) + 1 WHERE id = v_target;
    ELSE
      UPDATE public.social_reels SET share_count = COALESCE(share_count, 0) + 1 WHERE id = v_target;
    END IF;
  ELSE
    IF p_kind = 'view' THEN
      UPDATE public.social_posts SET view_count = COALESCE(view_count, 0) + 1 WHERE id = v_target;
    ELSE
      UPDATE public.social_posts SET share_count = COALESCE(share_count, 0) + 1 WHERE id = v_target;
    END IF;
  END IF;
  RETURN true;
END;
$$;


