--
-- TOC entry 3783 (class 1255 OID 34769567)
-- Name: fn_crash_cashout(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_crash_cashout(p_round_id uuid, p_multiplier_cents integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  r public.crash_rounds;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In To Play');
  END IF;
  IF p_multiplier_cents IS NULL OR p_multiplier_cents < 101 THEN
    RETURN jsonb_build_object('ok',false,'error','Cash Out Starts At 1.01x');
  END IF;
  SELECT * INTO r FROM public.crash_rounds WHERE id = p_round_id;
  IF r.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Round Could Not Be Found');
  END IF;
  IF r.user_id <> v_user AND COALESCE(auth.role(), '') <> 'service_role' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Round Belongs To Another Player');
  END IF;
  IF r.status <> 'open' THEN
    RETURN public.fn_crash_round_result(r);
  END IF;
  IF r.payout_version >= 5 AND p_multiplier_cents < 126 THEN
    RETURN jsonb_build_object('ok',false,'error','Cash Out Starts At 1.26x');
  END IF;
  IF r.payout_version >= 4 AND p_multiplier_cents < 111 THEN
    RETURN jsonb_build_object('ok',false,'error','Cash Out Starts At 1.11x');
  END IF;
  IF public.fn_platform_frozen() THEN
    -- The clock is frozen with the platform: the round waits, nothing is decided.
    RETURN public.fn_crash_round_result(r) || jsonb_build_object('frozen', true);
  END IF;
  -- The host lock serialises settlement with new rounds on the same pool.
  PERFORM 1 FROM public.diamond_game_configs WHERE host_id = r.host_id AND game = 'crash' FOR UPDATE;
  SELECT * INTO r FROM public.crash_rounds WHERE id = p_round_id FOR UPDATE;
  r := public.fn_crash_decide(r, true, 'player', p_multiplier_cents);
  RETURN public.fn_crash_round_result(r);
END $$;


ALTER FUNCTION public.fn_crash_cashout(p_round_id uuid, p_multiplier_cents integer) OWNER TO postgres;

--
-- TOC entry 4343 (class 1255 OID 41947491)
-- Name: fn_crash_config_limits(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_crash_config_limits() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NEW.game='crash' THEN
  -- 20.00x is the cap of every Diamond Crash flight, and every flight can reach
  -- it (Dan, 2026-10-12), so no setting raises or lowers it; and 0.08 is the
  -- fastest it may climb: 20x in about 37 seconds.
  NEW.max_multiplier_cents:=2000;
  NEW.growth_k:=least(NEW.growth_k,0.08);
 END IF;
 RETURN NEW;
END $$;


