-- TOC entry 5174 (class 1255 OID 4767523)
-- Name: fn_delete_message(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_delete_message(p_message_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_sender uuid;
BEGIN
    IF p_message_id IS NULL OR p_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing parameters');
    END IF;

    SELECT sender_id INTO v_sender FROM social_messages WHERE id = p_message_id;

    IF v_sender IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'message not found');
    END IF;

    IF v_sender <> p_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'only the sender can delete this message');
    END IF;

    UPDATE social_messages
       SET is_deleted = true,
           content = '[message deleted]',
           updated_at = NOW()
     WHERE id = p_message_id;

    RETURN jsonb_build_object('success', true, 'message_id', p_message_id);
END;
$$;


ALTER FUNCTION public.fn_delete_message(p_message_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 6132 (class 1255 OID 15021571)
-- Name: fn_delete_tournament_schedule(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_delete_tournament_schedule(p_schedule_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_s   record;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'not_authenticated');
  END IF;
  SELECT * INTO v_s FROM public.tournament_schedules WHERE id = p_schedule_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'schedule_not_found');
  END IF;
  IF NOT public.fn_can_manage_tournament_schedule(v_s.union_id, v_s.club_id, v_uid) THEN
    RETURN jsonb_build_object('error', 'not_authorised');
  END IF;
  UPDATE public.tournament_schedules
     SET active = false, updated_at = now()
   WHERE id = p_schedule_id;
  RETURN jsonb_build_object('ok', true, 'schedule_id', p_schedule_id);
END; $$;


ALTER FUNCTION public.fn_delete_tournament_schedule(p_schedule_id uuid) OWNER TO postgres;

--
-- TOC entry 7437 (class 1255 OID 4653882)
-- Name: fn_delete_user_gdpr(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_delete_user_gdpr(p_user_id uuid, p_requested_by uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_request_id uuid;
  v_req_role text;
  v_summary jsonb := '{}'::jsonb;
  v_counts jsonb := '{}'::jsonb;
  v_n int;
BEGIN
  IF p_user_id IS NULL OR p_requested_by IS NULL THEN
    RAISE EXCEPTION 'user_id and requested_by required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  SELECT role INTO v_req_role FROM public.profiles WHERE id = p_requested_by;
  IF p_user_id <> p_requested_by AND v_req_role NOT IN ('admin','superadmin','god') THEN
    RAISE EXCEPTION 'only the user or a platform admin may request GDPR deletion' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- ZERO-DRIFT phase 3: financial closure precheck - refuse to anonymize
  -- an account that still holds or is owed chips (blockers returned).
  IF NOT COALESCE((public.fn_ca_gdpr_financial_precheck(p_user_id)->>'clear')::boolean, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'financial_precheck_failed',
      'precheck', public.fn_ca_gdpr_financial_precheck(p_user_id));
  END IF;

  INSERT INTO public.gdpr_deletion_requests (user_id, requested_by, reason, status)
  VALUES (p_user_id, p_requested_by, p_reason, 'pending')
  RETURNING id INTO v_request_id;

  UPDATE public.chip_ledger                    SET performed_by = NULL WHERE performed_by = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('chip_ledger', v_n);
  UPDATE public.bus_event_log                  SET user_id = NULL WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('bus_event_log', v_n);
  UPDATE public.admin_audit_log                SET admin_user_id = NULL WHERE admin_user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('admin_audit_log', v_n);
  UPDATE public.club_arena_audit_logs          SET user_id = NULL WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('club_arena_audit_logs', v_n);
  UPDATE public.club_arena_messages            SET user_id = NULL WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('club_arena_messages', v_n);
  UPDATE public.club_chat                      SET user_id = NULL WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('club_chat', v_n);
  UPDATE public.table_chat                     SET user_id = NULL WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('table_chat', v_n);
  UPDATE public.tournament_players             SET user_id = NULL WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('tournament_players', v_n);
  UPDATE public.tournament_registrations       SET user_id = NULL WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('tournament_registrations', v_n);

  UPDATE public.arcade_duels SET player1_id = NULL WHERE player1_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('arcade_duels_player1', v_n);
  UPDATE public.arcade_duels SET player2_id = NULL WHERE player2_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('arcade_duels_player2', v_n);
  UPDATE public.arcade_duels SET winner_id  = NULL WHERE winner_id  = p_user_id;

  UPDATE public.social_post_comments           SET user_id = NULL WHERE user_id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('social_post_comments', v_n);

  UPDATE public.unions                         SET owner_id = NULL WHERE owner_id = p_user_id;
  UPDATE public.union_announcements            SET created_by = NULL WHERE created_by = p_user_id;
  UPDATE public.union_wallet_transactions      SET created_by = NULL WHERE created_by = p_user_id;
  UPDATE public.geeves_analytics               SET user_id = NULL WHERE user_id = p_user_id;
  UPDATE public.live_help_analytics            SET user_id = NULL WHERE user_id = p_user_id;
  UPDATE public.content_schedule               SET author_id = NULL WHERE author_id = p_user_id;
  UPDATE public.commander_buyin_transactions   SET player_id = NULL WHERE player_id = p_user_id;
  UPDATE public.commander_home_seats           SET user_id = NULL WHERE user_id = p_user_id;
  UPDATE public.commander_sessions             SET user_id = NULL WHERE user_id = p_user_id;
  UPDATE public.opponent_profiles              SET opponent_id = NULL WHERE opponent_id = p_user_id;
  UPDATE public.player_notes                   SET target_user_id = NULL WHERE target_user_id = p_user_id;
  UPDATE public.poy_leaderboard                SET player_id = NULL WHERE player_id = p_user_id;
  UPDATE public.arcade_jackpot                 SET last_winner_id = NULL WHERE last_winner_id = p_user_id;

  -- Anonymize the profiles row. BUG-10 fix: drop the bogus `metadata`
  -- column assignment (column does not exist) and also wipe the jsonb
  -- preference columns which can contain personalization data.
  UPDATE public.profiles
    SET
      display_name          = 'Deleted User',
      username              = 'deleted_' || substring(id::text, 1, 8),
      email                 = NULL,
      avatar_url            = NULL,
      bio                   = NULL,
      phone                 = NULL,
      preferences           = '{}'::jsonb,
      hub_preferences       = '{}'::jsonb,
      friend_preferences    = '{}'::jsonb,
      store_preferences     = '{}'::jsonb,
      messenger_preferences = '{}'::jsonb,
      reels_preferences     = '{}'::jsonb
  WHERE id = p_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('profiles_anonymized', v_n);

  v_summary := jsonb_build_object(
    'request_id', v_request_id,
    'user_id', p_user_id,
    'requested_by', p_requested_by,
    'anonymized_columns', v_counts
  );

  UPDATE public.gdpr_deletion_requests
    SET status = 'anonymized',
        anonymized_at = now(),
        summary = v_summary
  WHERE id = v_request_id;

  PERFORM public.fn_log_admin_action(
    p_admin_user_id := p_requested_by,
    p_action := 'user.gdpr_delete_anonymized',
    p_target_type := 'user',
    p_target_id := p_user_id::text,
    p_details := v_summary,
    p_before_state := NULL,
    p_after_state := NULL,
    p_ip_address := NULL,
    p_user_agent := NULL,
    p_request_id := v_request_id::text
  );

  RETURN v_summary;
EXCEPTION WHEN OTHERS THEN
  UPDATE public.gdpr_deletion_requests
    SET status = 'failed', error_detail = SQLERRM
  WHERE id = v_request_id;
  RAISE;
END;
$$;


ALTER FUNCTION public.fn_delete_user_gdpr(p_user_id uuid, p_requested_by uuid, p_reason text) OWNER TO postgres;

--
-- TOC entry 46985 (class 0 OID 0)
-- Dependencies: 7437
-- Name: FUNCTION fn_delete_user_gdpr(p_user_id uuid, p_requested_by uuid, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_delete_user_gdpr(p_user_id uuid, p_requested_by uuid, p_reason text) IS 'Phase 6.1.10 — GDPR right-to-erasure. Anonymizes audit/financial/public-schema rows that reference the target auth.users id. Caller must then invoke auth.admin.deleteUser(user_id) to cascade-delete remaining personal rows and remove the auth identity.';


--
-- TOC entry 3889 (class 1255 OID 144351800)
-- Name: fn_deleted_account_custody_settled(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_deleted_account_custody_settled() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_bank uuid;
BEGIN
  -- Profile UPDATE already owns its row. Never wait for the inverse user/wallet
  -- order held by a credit, buy-in or cashier operation: refuse atomically instead.
  IF NOT pg_try_advisory_xact_lock(hashtextextended('table_cap:' || OLD.id::text, 0)) THEN
    RAISE EXCEPTION 'ACCOUNT_CUSTODY_BUSY' USING ERRCODE = '55P03';
  END IF;
  -- Own the person's wallets first, without queueing. Once held, nobody can
  -- credit them, so what is free below is exactly what will be returned.
  PERFORM 1 FROM public.agents a WHERE a.user_id = OLD.id
    ORDER BY a.club_id FOR UPDATE NOWAIT;
  PERFORM 1 FROM public.club_members m WHERE m.user_id = OLD.id
    ORDER BY m.club_id FOR UPDATE NOWAIT;
  -- Then only the banks that will receive chips, still without queueing.
  -- An empty wallet never touches its club's bank.
  FOR v_bank IN
    SELECT c.id FROM public.clubs c
     WHERE c.asset = 'chips' AND c.lifecycle_status = 'active'
       AND (EXISTS (SELECT 1 FROM public.club_members m
                     WHERE m.club_id = c.id AND m.user_id = OLD.id
                       AND coalesce(m.chip_balance,0) - coalesce(m.held_chips,0) - coalesce(m.locked_chips,0) > 0)
            OR EXISTS (SELECT 1 FROM public.agents a
                        WHERE a.club_id = c.id AND a.user_id = OLD.id
                          AND coalesce(a.agent_wallet_balance,0) > 0))
     ORDER BY c.id
  LOOP
    PERFORM public.fn_ca_try_lock_bank(v_bank);
  END LOOP;

  IF EXISTS (SELECT 1 FROM public.table_seats s WHERE s.user_id = OLD.id AND s.left_at IS NULL) THEN
    RAISE EXCEPTION 'ACCOUNT_CUSTODY_UNSETTLED: seated' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_players p JOIN public.tournaments t ON t.id = p.tournament_id
    WHERE p.user_id = OLD.id AND p.status IN ('registered','playing')
      AND t.status NOT IN ('COMPLETED','CANCELLED')) THEN
    RAISE EXCEPTION 'ACCOUNT_CUSTODY_UNSETTLED: tournament_entry' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.cashout_requests r
    WHERE (r.player_id = OLD.id OR r.agent_id = OLD.id)
      AND (r.status IN ('pending','cancelling','completing')
        OR (r.status = 'approved' AND r.completed_at IS NULL))) THEN
    RAISE EXCEPTION 'ACCOUNT_CUSTODY_UNSETTLED: pending_cashout' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.chip_escrow e WHERE e.player_id = OLD.id AND e.released_at IS NULL)
    OR EXISTS (SELECT 1 FROM public.chip_escrow_holds h WHERE h.user_id = OLD.id AND h.status = 'held') THEN
    RAISE EXCEPTION 'ACCOUNT_CUSTODY_UNSETTLED: escrow' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.club_members m WHERE m.user_id = OLD.id
    AND (coalesce(m.held_chips,0) <> 0 OR coalesce(m.locked_chips,0) <> 0)) THEN
    RAISE EXCEPTION 'ACCOUNT_CUSTODY_UNSETTLED: held_chips' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_deleted_account_custody_settled() OWNER TO postgres;

--
-- TOC entry 46987 (class 0 OID 0)
-- Dependencies: 3889
-- Name: FUNCTION fn_deleted_account_custody_settled(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_deleted_account_custody_settled() IS 'Account deletion refuses unsettled table, tournament, cashout and held custody before status or bank-return writes. No waiting behind an inverse wallet lock.';


--
-- TOC entry 4040 (class 1255 OID 31371462)
-- Name: fn_deliver_accounting_invoice(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_deliver_accounting_invoice(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_variable
DECLARE inv public.settlement_invoices%ROWTYPE; sender uuid; issuer_name text; recipient_name text;
 issuer_kind text; issuer_id uuid; recipient_id uuid; scope_id uuid; page_id uuid; users uuid[]; issuer_users uuid[]; recipient_users uuid[];
 person uuid; conv uuid; msg uuid; note uuid; body text; meta jsonb; count_sent int:=0; n int; line record; cashier public.accounting_cashier_events%ROWTYPE; cashier_payload jsonb; correction public.accounting_correction_documents%ROWTYPE; correction_payload jsonb; credit_change public.accounting_credit_change_documents_v1%ROWTYPE; credit_operation public.accounting_credit_reduction_operations_v1%ROWTYPE; credit_payload jsonb;
BEGIN
 SELECT * INTO inv FROM public.settlement_invoices WHERE id=p_invoice_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'accounting_invoice_missing' USING ERRCODE='23514'; END IF;
 IF public.fn_accounting_correction_is_unverified(inv.id)
 THEN RAISE EXCEPTION 'historical_correction_document_unverified' USING ERRCODE='23514';END IF;
 IF inv.net_amount IS NULL OR inv.net_amount::text IN('NaN','Infinity','-Infinity') OR inv.net_amount<>round(inv.net_amount,2)
 THEN RAISE EXCEPTION 'invalid_invoice_amount' USING ERRCODE='23514'; END IF;
 -- Owner rule (2026-10-15): only cashout documents reach the messenger (the player's request
 -- reaches their agent, the approval reaches the player). Every other invoice is recorded in
 -- transaction history only and marked delivered so the weekly close is satisfied.
 IF inv.invoice_type IS DISTINCT FROM 'cashier_cashout' THEN
  IF inv.invoice_number IS NULL THEN
   UPDATE public.settlement_invoices SET invoice_number=public.fn_accounting_next_invoice_number() WHERE id=inv.id RETURNING invoice_number INTO inv.invoice_number;
  END IF;
  UPDATE public.settlement_invoices SET message_sent=true,message_sent_at=COALESCE(message_sent_at,now()) WHERE id=inv.id;
  RETURN jsonb_build_object('success',true,'invoice_id',inv.id,'delivered',0,'new_deliveries',0);
 END IF;
 issuer_kind:=inv.from_entity_type; issuer_id:=inv.from_entity_id::uuid; recipient_id:=inv.to_entity_id::uuid;
 scope_id:=COALESCE(inv.club_id,issuer_id);
 IF inv.invoice_type='credit_limit_change' THEN
  credit_payload:=public.fn_accounting_credit_change_contract_v1(inv.id);
  SELECT * INTO STRICT credit_change FROM public.accounting_credit_change_documents_v1 WHERE invoice_id=inv.id;
  SELECT * INTO STRICT credit_operation FROM public.accounting_credit_reduction_operations_v1 WHERE id=credit_change.operation_receipt_id;
  users:=credit_change.audience_user_ids;sender:=credit_operation.actor_user_id;
  issuer_kind:='club';issuer_id:=credit_operation.club_id;scope_id:=credit_operation.club_id;
  issuer_name:=credit_change.issuer_name;recipient_name:=credit_change.recipient_name;
 ELSIF inv.invoice_type='accounting_correction' THEN
  SELECT * INTO correction FROM public.accounting_correction_documents WHERE invoice_id=inv.id;
  IF NOT FOUND OR correction.club_id IS DISTINCT FROM inv.club_id OR correction.source_ledger_id IS DISTINCT FROM inv.source_ledger_id
   OR correction.amount IS DISTINCT FROM inv.net_amount OR inv.breakdown IS DISTINCT FROM jsonb_build_object('category','correction','correction',public.fn_accounting_correction_payload(correction))
   OR inv.status IS DISTINCT FROM 'generated' OR inv.chips_transferred IS DISTINCT FROM false OR inv.transferred_at IS NOT NULL OR inv.due_at IS NOT NULL
  THEN RAISE EXCEPTION 'correction_document_delivery_source_unverified' USING ERRCODE='23514';END IF;
  users:=correction.audience_user_ids;sender:=correction.issuer_representative_id;
  issuer_kind:=correction.issuer_type;issuer_id:=correction.issuer_id;scope_id:=correction.club_id;
  issuer_name:=correction.issuer_name;recipient_name:=correction.payee_name;correction_payload:=public.fn_accounting_correction_payload(correction);
 ELSIF inv.invoice_type='cashier_cashout' THEN
  SELECT * INTO cashier FROM public.accounting_cashier_events WHERE invoice_id=inv.id;
  IF NOT FOUND OR cashier.club_id IS DISTINCT FROM inv.club_id OR cashier.source_ledger_id IS DISTINCT FROM inv.source_ledger_id
    OR cashier.amount IS DISTINCT FROM inv.net_amount OR inv.breakdown->'cashier' IS DISTINCT FROM public.fn_cashier_event_payload(cashier)
  THEN RAISE EXCEPTION 'cashier_delivery_event_missing' USING ERRCODE='23514';END IF;
  users:=cashier.audience_user_ids;sender:=cashier.issuer_representative_id;
  issuer_kind:='club';issuer_id:=cashier.club_id;scope_id:=cashier.club_id;
  issuer_name:=cashier.issuer_name;recipient_name:=cashier.player_name;
  cashier_payload:=public.fn_cashier_event_payload(cashier);
 ELSE
 SELECT array_agg(user_id ORDER BY user_id) INTO issuer_users FROM public.fn_accounting_invoice_party_users(inv.from_entity_type,issuer_id);
 SELECT array_agg(user_id ORDER BY user_id) INTO recipient_users FROM public.fn_accounting_invoice_party_users(inv.to_entity_type,recipient_id);
 IF COALESCE(cardinality(issuer_users),0)=0 OR COALESCE(cardinality(recipient_users),0)=0
 THEN RAISE EXCEPTION 'accounting_invoice_recipient_missing' USING ERRCODE='23514'; END IF;
 SELECT array_agg(DISTINCT x ORDER BY x) INTO users FROM unnest(issuer_users||recipient_users) x;
 -- Club senders receive one weekly summary; individual payees still get their receipt immediately.
 IF inv.from_entity_type='club' AND inv.to_entity_type IN('agent','player')
    AND inv.source_ledger_id IS NOT NULL AND inv.breakdown->>'category' IN('rakeback','commission') THEN
   users:=recipient_users;
 END IF;
 IF inv.invoice_type IN('union_weekly_squareup','union_weekly_credit_note') THEN
   issuer_kind:='union';issuer_id:=(inv.breakdown->>'union_id')::uuid;
 END IF;
 sender:=CASE WHEN issuer_kind='club' THEN (SELECT owner_id FROM public.clubs WHERE id=issuer_id)
              WHEN issuer_kind='union' THEN (SELECT owner_id FROM public.unions WHERE id=issuer_id)
              ELSE issuer_id END;
 IF sender IS NULL OR NOT sender=ANY(issuer_users||recipient_users) THEN RAISE EXCEPTION 'accounting_invoice_sender_missing' USING ERRCODE='23514'; END IF;
 issuer_name:=CASE WHEN issuer_kind='club' THEN (SELECT name FROM public.clubs WHERE id=issuer_id)
                   WHEN issuer_kind='union' THEN (SELECT name FROM public.unions WHERE id=issuer_id)
                   ELSE (SELECT username FROM public.profiles WHERE id=issuer_id) END;
 recipient_name:=CASE WHEN inv.to_entity_type='club' THEN (SELECT name FROM public.clubs WHERE id=recipient_id)
                      WHEN inv.to_entity_type='union' THEN (SELECT name FROM public.unions WHERE id=recipient_id)
                      ELSE (SELECT username FROM public.profiles WHERE id=recipient_id) END;
 END IF;
 IF inv.invoice_number IS NULL THEN
   UPDATE public.settlement_invoices SET invoice_number=public.fn_accounting_next_invoice_number() WHERE id=inv.id RETURNING invoice_number INTO inv.invoice_number;
 END IF;
 IF inv.invoice_type IN('union_weekly_squareup','union_weekly_credit_note') THEN recipient_name:=(SELECT name FROM public.clubs WHERE id=inv.club_id); END IF;
 body:=CASE WHEN inv.invoice_type='club_weekly_accounting' THEN 'Weekly Club Statement ' ELSE 'Invoice ' END||inv.invoice_number||E'\nIssued By: '||COALESCE(issuer_name,inv.from_entity_type)||E'\nFor: '||COALESCE(recipient_name,inv.to_entity_type)
  ||E'\nDirection: '||initcap(inv.from_entity_type)||' To '||initcap(inv.to_entity_type)
  ||E'\nAmount: '||to_char(abs(inv.net_amount),'FM999,999,999,999,990.00')||' Chips'
  ||E'\nStatus: '||initcap(inv.status)
  ||CASE WHEN inv.chips_transferred THEN E'\nTransfer Recorded: '||COALESCE(inv.transferred_at,inv.created_at)::text ELSE '' END
  ||CASE WHEN inv.due_at IS NOT NULL THEN E'\nDue: '||to_char(inv.due_at AT TIME ZONE 'America/Chicago','YYYY-MM-DD HH24:MI')||' Chicago Time' ELSE '' END
  ||CASE WHEN inv.breakdown ? 'period_start' THEN E'\nPeriod: '||(inv.breakdown->>'period_start')||' To '||COALESCE(inv.breakdown->>'period_end','') ELSE '' END
  ||CASE WHEN inv.notes IS NOT NULL THEN E'\n'||inv.notes ELSE '' END;
 FOR line IN SELECT key,value FROM jsonb_each_text(COALESCE(inv.breakdown,'{}'))
   WHERE key IN('rake_generated','rakeback_due','union_fee_kept','players_won','settled_in_chips','eco_amount','presettled','rake_earned','union_rake_earned','private_rake_earned','private_rake_banked','total_rake_funding','rake_received','paid_super_agents','paid_agents','paid_sub_agents','paid_players','total_paid_by_club','retained_by_club','downstream_redistributed','downstream_paid_super_agents','downstream_paid_agents','downstream_paid_sub_agents','downstream_paid_players') ORDER BY key
 LOOP
   IF line.value IS NOT NULL THEN body:=body||E'\n'||initcap(replace(line.key,'_',' '))||': '||to_char(line.value::numeric,'FM999,999,999,999,990.00'); END IF;
 END LOOP;
 IF inv.invoice_type='credit_limit_change' THEN body:=public.fn_accounting_credit_change_body_v1(credit_change.id,inv.invoice_number);
 ELSIF inv.invoice_type='cashier_cashout' THEN body:=public.fn_cashier_document_body(cashier.id,inv.invoice_number);
 ELSIF inv.invoice_type='accounting_correction' THEN body:=public.fn_accounting_correction_document_body(correction.id,inv.invoice_number);END IF;
 meta:=jsonb_build_object('kind','accounting_invoice' ,'invoice_id',inv.id,'invoice_number',inv.invoice_number,
   'club_id',inv.club_id,'source_ledger_id',inv.source_ledger_id,'source_credit_invoice_id',inv.source_credit_invoice_id,
   'source_credit_payment_id',inv.source_credit_payment_id,'amount',inv.net_amount,'currency','CHIPS','conversationId',NULL,'status',inv.status,
   'invoice_type',inv.invoice_type,'from_entity_type',inv.from_entity_type,'from_entity_id',inv.from_entity_id,
   'to_entity_type',inv.to_entity_type,'to_entity_id',inv.to_entity_id,'lines',inv.breakdown-ARRAY['source_ledger_ids','private_bank_ledger_ids','standalone_bank_ledger_ids','standalone_bank_mint_ids']);
 IF inv.invoice_type='credit_limit_change' THEN meta:=meta||jsonb_build_object('credit_change',credit_payload);
 ELSIF inv.invoice_type='cashier_cashout' THEN meta:=meta||jsonb_build_object('cashier',cashier_payload);
 ELSIF inv.invoice_type='accounting_correction' THEN meta:=meta||jsonb_build_object('correction',correction_payload);END IF;
 SELECT id INTO page_id FROM public.social_pages WHERE linked_entity_id=scope_id::text AND linked_entity_type='club' ORDER BY id LIMIT 1;
 FOREACH person IN ARRAY users LOOP
   IF EXISTS(SELECT 1 FROM public.accounting_invoice_deliveries d WHERE d.invoice_id=inv.id AND d.recipient_id=person) THEN CONTINUE; END IF;
   -- One private accounting conversation per issuer, sender, scope and recipient.
   PERFORM pg_advisory_xact_lock(hashtextextended('accounting_conversation:'||scope_id::text||':'||issuer_id::text||':'||sender::text||':'||person::text,0));
   SELECT conversation_id INTO conv FROM public.accounting_conversations c
    WHERE c.scope_id=scope_id AND c.issuer_type=issuer_kind AND c.issuer_id=issuer_id AND c.sender_id=sender AND c.recipient_id=person;
   IF conv IS NULL THEN
     INSERT INTO public.social_conversations(is_group,group_name,context_entity_id,context_entity_type)
      VALUES(true,COALESCE(issuer_name,'Account')||' Accounting',page_id,CASE WHEN page_id IS NULL THEN NULL ELSE 'club' END) RETURNING id INTO conv;
     INSERT INTO public.social_conversation_participants(conversation_id,user_id,context_entity_id,context_entity_type)
      SELECT conv,x,page_id,CASE WHEN page_id IS NULL THEN NULL ELSE 'club' END FROM (SELECT DISTINCT unnest(ARRAY[sender,person]) AS x) members;
     INSERT INTO public.accounting_conversations(scope_id,issuer_type,issuer_id,sender_id,recipient_id,conversation_id)
      VALUES(scope_id,issuer_kind,issuer_id,sender,person,conv);
   END IF;
   -- Refuse a conversation whose audience changed instead of leaking invoices.
   IF EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id<>ALL(ARRAY[sender,person]))
      OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id=person)
      OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id=sender)
   THEN RAISE EXCEPTION 'accounting_conversation_audience_changed' USING ERRCODE='23514'; END IF;
   meta:=meta||jsonb_build_object('conversation_id',conv,'conversationId',conv);
   INSERT INTO public.social_messages(conversation_id,sender_id,content,message_type,media_metadata)
    VALUES(conv,sender,body,'invoice',meta) RETURNING id INTO msg;
   UPDATE public.social_conversations SET last_message_at=now(),last_message_preview=left(body,100),updated_at=now() WHERE id=conv;
   meta:=meta||jsonb_build_object('conversation_id',conv,'conversationId',conv);
   INSERT INTO public.notifications(user_id,type,title,message,data,read,action_url,metadata)
    VALUES(person,CASE WHEN inv.chips_transferred AND inv.invoice_type NOT IN('credit_limit_change','accounting_correction','cashier_cashout') THEN 'accounting_invoice_detail' ELSE 'accounting_invoice' END,CASE WHEN inv.invoice_type='credit_limit_change' THEN 'Credit Line Updated · ' WHEN inv.invoice_type='accounting_correction' THEN 'Correction Recorded · ' WHEN inv.invoice_type='cashier_cashout' THEN CASE cashier.event_kind WHEN 'hold' THEN 'Chips Held · ' WHEN 'approval' THEN 'Cashout Approved · ' ELSE 'Chips Returned · ' END WHEN inv.invoice_type='club_weekly_accounting' THEN 'Weekly Club Statement ' ELSE 'Invoice ' END||inv.invoice_number,
     CASE WHEN inv.invoice_type='credit_limit_change' THEN 'Credit capacity reduced: '||to_char(inv.net_amount,'FM999,999,999,999,990.00')||'. No payment due.'
      ELSE CASE WHEN inv.invoice_type='accounting_correction' THEN 'Correction Recorded: ' WHEN inv.invoice_type='cashier_cashout' THEN CASE cashier.event_kind WHEN 'hold' THEN 'Chips Held: ' WHEN 'approval' THEN 'Cashout Approved: ' ELSE 'Chips Returned: ' END WHEN inv.chips_transferred AND inv.breakdown->>'category'='rakeback' THEN 'Rakeback Transfer Recorded: ' WHEN inv.chips_transferred AND inv.breakdown->>'category'='commission' THEN 'Commission Transfer Recorded: ' WHEN inv.chips_transferred THEN 'Transfer Recorded: ' ELSE 'Invoice Issued: ' END||to_char(abs(inv.net_amount),'FM999,999,999,999,990.00')||' Chips' END,
     meta,(inv.chips_transferred AND inv.invoice_type NOT IN('credit_limit_change','accounting_correction','cashier_cashout')),'/hub/messenger?conversation='||conv::text,meta) RETURNING id INTO note;
   INSERT INTO public.accounting_invoice_deliveries(invoice_id,recipient_id,message_id,notification_id) VALUES(inv.id,person,msg,note);
   count_sent:=count_sent+1;
 END LOOP;
 SELECT count(*) INTO n FROM public.accounting_invoice_deliveries WHERE invoice_id=inv.id;
 UPDATE public.settlement_invoices SET message_sent=true,message_sent_at=COALESCE(message_sent_at,now()) WHERE id=inv.id;
 RETURN jsonb_build_object('success',true,'invoice_id',inv.id,'delivered',n,'new_deliveries',count_sent);
END $$;


ALTER FUNCTION public.fn_deliver_accounting_invoice(p_invoice_id uuid) OWNER TO postgres;

--
-- TOC entry 7700 (class 1255 OID 171351902)
-- Name: fn_deliver_club_messenger_welcome(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_deliver_club_messenger_welcome() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_member record; v_admission record; v_sender uuid; v_owner uuid; v_template record; v_result jsonb;
BEGIN
 SELECT * INTO v_member FROM public.club_members WHERE club_id=NEW.club_id AND user_id=NEW.user_id;
 IF NOT FOUND OR v_member.is_active IS NOT TRUE OR v_member.status NOT IN ('active','approved') OR v_member.membership_lifecycle_status<>'active' THEN RETURN NEW; END IF;
 SELECT * INTO v_admission FROM public.club_messenger_admissions WHERE club_id=NEW.club_id AND user_id=NEW.user_id AND active AND transaction_id=txid_current() FOR UPDATE;
 IF NOT FOUND OR EXISTS(SELECT 1 FROM public.club_messenger_welcome_deliveries WHERE generation=v_admission.generation) THEN RETURN NEW; END IF;
 SELECT owner_id INTO v_owner FROM public.clubs WHERE id=NEW.club_id;
 v_sender:=v_member.agent_id;
 IF v_sender IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.agents WHERE club_id=NEW.club_id AND user_id=v_sender AND status='active') THEN v_sender:=NULL; END IF;
 IF v_sender IS NULL OR public.fn_club_messenger_staff_role(NEW.club_id,v_sender) IS NULL THEN v_sender:=v_owner; END IF;
 IF v_sender IS NULL OR v_sender=NEW.user_id THEN RETURN NEW; END IF;
 SELECT * INTO v_template FROM public.club_messenger_welcome_templates WHERE club_id=NEW.club_id AND user_id=v_sender AND enabled FOR SHARE;
 IF NOT FOUND THEN RETURN NEW; END IF;
 v_result:=public.fn_send_club_welcome_text(NEW.club_id,NEW.user_id,v_sender,v_template.content,v_template.revision,'downline');
 IF v_result->>'status'='cancelled' THEN RETURN NEW; END IF;
 INSERT INTO public.club_messenger_welcome_deliveries(generation,club_id,recipient_id,sender_id,template_revision,conversation_id,message_id,status)
 VALUES(v_admission.generation,NEW.club_id,NEW.user_id,v_sender,v_template.revision,(v_result->>'conversation_id')::uuid,(v_result->>'message_id')::uuid,v_result->>'status');
 IF v_result->>'status'='sent' AND v_owner<>NEW.user_id THEN
  INSERT INTO public.club_messenger_owner_followups(generation,club_id,recipient_id,sender_id,content,template_revision,due_at)
  SELECT v_admission.generation,NEW.club_id,NEW.user_id,v_owner,t.content,t.revision,clock_timestamp()+interval '10 minutes'
  FROM public.club_messenger_owner_welcome_templates t WHERE t.club_id=NEW.club_id AND t.user_id=v_owner AND t.enabled
  ON CONFLICT(generation) DO NOTHING;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_deliver_club_messenger_welcome() OWNER TO postgres;

--
-- TOC entry 9464 (class 1255 OID 24465024)
-- Name: fn_deliver_satellite_ticket_exact(uuid, uuid, uuid, text, integer, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_deliver_satellite_ticket_exact(p_satellite_id uuid, p_target_id uuid, p_user_id uuid, p_username text, p_position integer, p_ticket_value numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_target public.tournaments%ROWTYPE;
  v_existing public.tournament_players%ROWTYPE;
  v_before_target_pool numeric;
  v_before_target_bounty numeric;
  v_split record;
  v_before_target_rake numeric;
  v_before_source_pool numeric;
  v_open boolean:=false;
  v_count integer;
  v_result jsonb;
  v_registration uuid;
  v_payout uuid;
  v_payout_meta jsonb;
  v_ledger_count integer;
  v_rake_count integer;
  v_target_buyin numeric;
  v_target_fee numeric;
  v_cash_reason text:='target_not_open';
BEGIN
  PERFORM public.fn_ca_lock_mtt_admission_contract();
  PERFORM public.fn_ca_lock_settlement_lane_global();
  SELECT * INTO v_target FROM public.tournaments
   WHERE id=p_target_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('delivery','cash','reason','target_missing'); END IF;
  SELECT count(*)::integer INTO v_count FROM public.tournament_players
   WHERE tournament_id=p_target_id;
  v_open:=CASE
    WHEN v_target.status IN ('ANNOUNCED','REGISTERING')
      THEN NOT COALESCE(v_target.prize_pool_finalized,false)
    WHEN v_target.status='RUNNING'
      THEN public.fn_tournament_late_registration_open(p_target_id)
    ELSE false END;
  v_open:=v_open AND (public.fn_ca_tournament_is_unlimited(p_target_id)
     OR v_target.max_players IS NULL OR v_count<v_target.max_players);
  IF round(GREATEST(COALESCE(v_target.buy_in_amount,0),0)
           +GREATEST(COALESCE(v_target.buy_in_fee,0),0),2)
       <>round(p_ticket_value,2) THEN
    -- The winner owns the frozen advertised value. Never call the historical
    -- seat RPC at a later, different target price: it would debit the source by
    -- today's price. Cash the frozen value instead.
    v_open:=false;
    v_cash_reason:='target_economics_changed';
  END IF;

  SELECT * INTO v_existing FROM public.tournament_players
   WHERE tournament_id=p_target_id AND user_id=p_user_id FOR UPDATE;
  IF FOUND THEN
    IF COALESCE(v_existing.is_satellite_qualifier,false)
       AND v_existing.source_satellite_id=p_satellite_id THEN
      SELECT count(*)::integer,(array_agg(po.id ORDER BY po.id))[1],
             (array_agg(po.metadata ORDER BY po.id))[1]
        INTO v_count,v_payout,v_payout_meta
        FROM public.tournament_payouts po
       WHERE po.tournament_id=p_satellite_id AND po.user_id=p_user_id
         AND po.position=p_position AND po.source='satellite_seat'
         AND round(po.amount,2)=round(p_ticket_value,2)
         AND po.metadata->>'registration_id'=v_existing.id::text;
      v_target_buyin:=CASE
        WHEN COALESCE(v_payout_meta->>'target_buy_in','')~'^[0-9]+([.][0-9]+)?$'
          THEN (v_payout_meta->>'target_buy_in')::numeric ELSE -1 END;
      v_target_fee:=CASE
        WHEN COALESCE(v_payout_meta->>'target_fee','')~'^[0-9]+([.][0-9]+)?$'
          THEN (v_payout_meta->>'target_fee')::numeric ELSE -1 END;
      SELECT count(*)::integer INTO v_ledger_count
        FROM public.chip_ledger l
       WHERE l.idempotency_key='tourney:'||p_satellite_id::text||':seat:'
                               ||p_user_id::text||':pool_transfer'
         AND l.from_type='prize_liability' AND l.from_entity_id=p_satellite_id
         AND l.to_type='prize_liability' AND l.to_entity_id=p_target_id
         AND round(l.amount,2)=round(p_ticket_value,2)
         AND l.metadata->>'registration_id'=v_existing.id::text
         AND CASE WHEN COALESCE(l.metadata->>'moved','')~'^[0-9]+([.][0-9]+)?$'
                  THEN round((l.metadata->>'moved')::numeric,2) ELSE -1 END
             =round(p_ticket_value,2)
         AND CASE WHEN COALESCE(l.metadata->>'unbacked','')~'^[0-9]+([.][0-9]+)?$'
                  THEN round((l.metadata->>'unbacked')::numeric,2) ELSE -1 END=0;
      SELECT count(*)::integer INTO v_rake_count
        FROM public.rake_records rr
       WHERE rr.tournament_id=p_target_id AND rr.source='fn_award_satellite_seat'
         AND rr.metadata->>'satellite_id'=p_satellite_id::text
         AND rr.metadata->>'user_id'=p_user_id::text
         AND rr.metadata->>'registration_id'=v_existing.id::text
         AND round(rr.rake_amount,2)=round(v_target_fee,2)
         AND round(COALESCE(rr.pot_size,0),2)=round(p_ticket_value,2);
      IF v_count<>1
         OR (CASE WHEN COALESCE(v_payout_meta->>'pool_transfer','')~'^[0-9]+([.][0-9]+)?$'
                 THEN round((v_payout_meta->>'pool_transfer')::numeric,2) ELSE -1 END)
            <>round(p_ticket_value,2)
         OR (CASE WHEN COALESCE(v_payout_meta->>'unbacked','')~'^[0-9]+([.][0-9]+)?$'
                 THEN round((v_payout_meta->>'unbacked')::numeric,2) ELSE -1 END)<>0
         OR round(v_target_buyin+v_target_fee,2)<>round(p_ticket_value,2)
         OR v_ledger_count<>1
         OR (v_target_fee>0 AND v_rake_count<>1)
         OR (v_target_fee=0 AND v_rake_count<>0) THEN
        RAISE EXCEPTION 'existing target seat has no exact fully-backed payout event'
          USING ERRCODE='check_violation';
      END IF;
      RETURN jsonb_build_object('delivery','seat','already',true,
        'registration_id',v_existing.id,'payout_id',v_payout);
    ELSIF COALESCE(v_existing.is_satellite_qualifier,false)
          AND v_existing.source_satellite_id IS NULL THEN
      RAISE EXCEPTION 'existing target satellite seat has ambiguous origin'
        USING ERRCODE='check_violation';
    ELSE
      RETURN jsonb_build_object('delivery','cash','reason','seat_already_held_elsewhere');
    END IF;
  END IF;
  -- A CAP IS NOT AN ECONOMIC FAILURE (2026-09-10). The four-table cap is
  -- enforced by trg_enforce_booking_game_cap on the target registration
  -- that fn_award_satellite_seat writes. Attempting the seat and letting
  -- that trigger raise turned one refused chair into a settlement that
  -- could never complete (satellite 9fee70de, 16 hours RUNNING). Take the
  -- same per-user lock the triggers take, read the same count the booking
  -- trigger will read for this target, and deliver the frozen value as
  -- cash - exactly as a closed or full target already does.
  IF v_open THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('table_cap:' || p_user_id::text, 0));
    IF public.fn_concurrent_game_load(p_user_id, NULL, NULL, p_target_id) >= 4 THEN
      v_open := false;
      v_cash_reason := 'four_table_cap';
    END IF;
  END IF;
  IF NOT v_open THEN
    RETURN jsonb_build_object('delivery','cash','reason',v_cash_reason);
  END IF;

  SELECT * INTO v_split FROM public.fn_tournament_entry_split(
    v_target.buy_in_amount,v_target.buy_in_fee,v_target.bounty_amount,
    COALESCE(v_target.is_bounty,false) OR COALESCE(v_target.is_pko,false) OR COALESCE(v_target.is_mystery_bounty,false));
  v_before_target_bounty:=round(COALESCE(v_target.bounty_pool,0),2);
  v_before_target_pool:=round(COALESCE(v_target.prize_pool,0),2);
  v_before_target_rake:=round(COALESCE(v_target.total_rake,0),2);
  SELECT round(COALESCE(t.prize_pool,0),2) INTO v_before_source_pool
    FROM public.tournaments t WHERE t.id=p_satellite_id FOR UPDATE;
  IF v_before_source_pool+0.005<round(p_ticket_value,2) THEN
    RAISE EXCEPTION 'satellite guarantee is not funded for its frozen ticket'
      USING ERRCODE='check_violation';
  END IF;

  v_result:=public.fn_award_satellite_seat(
    p_satellite_id,p_target_id,p_user_id,p_username,p_position);
  IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE
     OR COALESCE((v_result->>'awarded')::boolean,false) IS NOT TRUE
     OR COALESCE((v_result->>'pool_transfer')::numeric,-1)
          <>round(p_ticket_value,2)
     OR COALESCE((v_result->>'unbacked')::numeric,-1)<>0 THEN
    RAISE EXCEPTION 'exact target-seat award refused or wrote incomplete money: %',
      COALESCE(v_result::text,'null') USING ERRCODE='check_violation';
  END IF;
  v_registration:=(v_result->>'registration_id')::uuid;
  IF NOT EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.id=v_registration AND tp.tournament_id=p_target_id
       AND tp.user_id=p_user_id AND tp.source_satellite_id=p_satellite_id
       AND COALESCE(tp.is_satellite_qualifier,false)
  ) THEN
    RAISE EXCEPTION 'seat helper returned without the exact target registration'
      USING ERRCODE='check_violation';
  END IF;
  SELECT count(*)::integer,(array_agg(po.id ORDER BY po.id))[1] INTO v_count,v_payout
    FROM public.tournament_payouts po
   WHERE po.tournament_id=p_satellite_id AND po.user_id=p_user_id
     AND po.position=p_position AND po.source='satellite_seat'
     AND round(po.amount,2)=round(p_ticket_value,2)
     AND po.metadata->>'registration_id'=v_registration::text
     AND round(COALESCE((po.metadata->>'pool_transfer')::numeric,-1),2)
          =round(p_ticket_value,2)
     AND round(COALESCE((po.metadata->>'unbacked')::numeric,-1),2)=0;
  IF v_count<>1
     OR (SELECT round(COALESCE(t.prize_pool,0),2) FROM public.tournaments t
          WHERE t.id=p_target_id)
          <>v_before_target_pool+v_split.prize
     OR (SELECT round(COALESCE(t.bounty_pool,0),2) FROM public.tournaments t
          WHERE t.id=p_target_id) <>v_before_target_bounty+v_split.bounty
     OR (SELECT round(COALESCE(t.total_rake,0),2) FROM public.tournaments t
          WHERE t.id=p_target_id)
          <>v_before_target_rake+round(COALESCE(v_target.buy_in_fee,0),2)
     OR (SELECT round(COALESCE(t.prize_pool,0),2) FROM public.tournaments t
          WHERE t.id=p_satellite_id)
          <>v_before_source_pool-round(p_ticket_value,2) THEN
    RAISE EXCEPTION 'target seat, payout and pool transfer are not one exact event'
      USING ERRCODE='check_violation';
  END IF;
  RETURN jsonb_build_object('delivery','seat','already',false,
    'registration_id',v_registration,'payout_id',v_payout);
END;
$_$;


ALTER FUNCTION public.fn_deliver_satellite_ticket_exact(p_satellite_id uuid, p_target_id uuid, p_user_id uuid, p_username text, p_position integer, p_ticket_value numeric) OWNER TO postgres;

