-- Name: FUNCTION fn_deliver_satellite_ticket_exact(p_satellite_id uuid, p_target_id uuid, p_user_id uuid, p_username text, p_position integer, p_ticket_value numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_deliver_satellite_ticket_exact(p_satellite_id uuid, p_target_id uuid, p_user_id uuid, p_username text, p_position integer, p_ticket_value numeric) IS 'Rolling legacy satellite delivery helper. FOUR TABLE LIMIT and every other seat-award refusal abort atomically; cap-blocked full awards are noncash tickets only in fn_settle_satellite_tournament.';


--
-- TOC entry 9376 (class 1255 OID 9730505)
-- Name: fn_deliver_shop_purchase(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_deliver_shop_purchase() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_name text;
  v_cat text;
  v_stackable boolean;
  v_grant jsonb;
BEGIN
  SELECT name, category, COALESCE(stackable, false), grant_spec
    INTO v_name, v_cat, v_stackable, v_grant
    FROM public.club_shop_items
   WHERE id = NEW.item_id;

  INSERT INTO public.club_shop_inventory (
    user_id, club_id, item_id, purchase_id, item_name, category, price_paid,
    stackable_snapshot, grant_snapshot
  ) VALUES (
    NEW.buyer_id, NEW.club_id, NEW.item_id, NEW.id, v_name, v_cat,
    NEW.price_paid, COALESCE(v_stackable, false),
    COALESCE(NEW.grant_snapshot, v_grant)
  )
  ON CONFLICT (purchase_id) DO NOTHING;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_deliver_shop_purchase() OWNER TO postgres;

--
-- TOC entry 8290 (class 1255 OID 14252369)
-- Name: fn_deprecated_table_usage(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_deprecated_table_usage() RETURNS TABLE(table_name text, live_rows bigint, note text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; v_count bigint;
BEGIN
  FOR r IN SELECT d.table_name, d.replacement FROM deprecated_tables d LOOP
    EXECUTE format('SELECT count(*) FROM %I', r.table_name) INTO v_count;
    IF v_count > 0 THEN
      table_name := r.table_name; live_rows := v_count;
      note := 'Deprecated table still holds rows; replacement is ' || COALESCE(r.replacement, 'unknown');
      RETURN NEXT;
    END IF;
  END LOOP;
END $$;


ALTER FUNCTION public.fn_deprecated_table_usage() OWNER TO postgres;

--
-- TOC entry 6460 (class 1255 OID 14595749)
-- Name: fn_detect_double_dealing(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_detect_double_dealing(p_lookback_mins integer DEFAULT 30) RETURNS TABLE(table_id uuid, hand_a bigint, hand_b bigint, overlap_seconds numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH recent AS (
    SELECT h.table_id, h.hand_number, h.started_at, h.ended_at
    FROM public.hand_history h
    WHERE h.created_at > now() - make_interval(mins => GREATEST(p_lookback_mins, 1))
      AND h.started_at IS NOT NULL
      AND h.ended_at IS NOT NULL
  )
  SELECT a.table_id,
         a.hand_number AS hand_a,
         b.hand_number AS hand_b,
         round(EXTRACT(EPOCH FROM (LEAST(a.ended_at, b.ended_at) - GREATEST(a.started_at, b.started_at)))::numeric, 1)
  FROM recent a
  JOIN recent b
    ON b.table_id = a.table_id
   AND b.hand_number > a.hand_number
   AND a.started_at < b.ended_at
   AND b.started_at < a.ended_at
  WHERE EXTRACT(EPOCH FROM (LEAST(a.ended_at, b.ended_at) - GREATEST(a.started_at, b.started_at))) > 1
$$;


ALTER FUNCTION public.fn_detect_double_dealing(p_lookback_mins integer) OWNER TO postgres;

--
-- TOC entry 6079 (class 1255 OID 18534529)
-- Name: fn_detect_results_without_a_hand(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_detect_results_without_a_hand(p_since_days integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_retention integer;
  v_days      integer;
  v_since     timestamptz;
  v_flagged   integer := 0;
  v_alerts    integer := 0;
  v_chips     numeric := 0;
  v_parked    integer := 0;
  v_ids       uuid[] := ARRAY[]::uuid[];
  v_row       record;
BEGIN
  -- Never scan further back than the hand history is trusted to reach.
  SELECT COALESCE(horse_retention_days, 8) INTO v_retention
    FROM public.hand_history_retention_policy LIMIT 1;
  v_retention := GREATEST(COALESCE(v_retention, 8) - 1, 1);
  v_days := LEAST(GREATEST(COALESCE(p_since_days, v_retention), 1), v_retention);
  v_since := now() - make_interval(days => v_days);

  FOR v_row IN
    SELECT t.id,
           t.name,
           t.club_id,
           t.started_at,
           t.ended_at,
           EXTRACT(epoch FROM (t.ended_at - t.started_at))::integer AS secs,
           (SELECT count(*) FROM public.tournament_players tp
             WHERE tp.tournament_id = t.id)                          AS entrants,
           (SELECT count(*) FROM public.tournament_players tp
             WHERE tp.tournament_id = t.id AND tp.position IS NOT NULL) AS ranked,
           (SELECT COALESCE(sum(p.amount), 0) FROM public.tournament_payouts p
             WHERE p.tournament_id = t.id)                           AS paid
      FROM public.tournaments t
     WHERE t.status = 'COMPLETED'
       AND t.started_at IS NOT NULL
       AND t.started_at >= v_since
       AND NOT EXISTS (SELECT 1 FROM public.hand_history hh
                        WHERE hh.tournament_id = t.id)
       AND EXISTS (SELECT 1 FROM public.tournament_players tp
                    WHERE tp.tournament_id = t.id AND tp.position IS NOT NULL)
  LOOP
    v_flagged := v_flagged + 1;
    v_chips   := v_chips + COALESCE(v_row.paid, 0);
    v_ids     := v_ids || v_row.id;

    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT 'critical',
           'fn_detect_results_without_a_hand',
           format(
             'Tournament %s ranked %s of %s entrant(s) and paid %s chips, and not one hand was ever dealt in it',
             COALESCE(v_row.name, v_row.id::text), v_row.ranked, v_row.entrants,
             round(COALESCE(v_row.paid, 0), 2)),
           jsonb_build_object(
             'tournament_id',   v_row.id,
             'club_id',         v_row.club_id,
             'entrants',        v_row.entrants,
             'ranked',          v_row.ranked,
             'chips_paid',      round(COALESCE(v_row.paid, 0), 2),
             'started_at',      v_row.started_at,
             'ended_at',        v_row.ended_at,
             'seconds_to_end',  v_row.secs,
             'detail',          'no money was moved by this check; who is owed what on an event that never dealt is a human decision')
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source = 'fn_detect_results_without_a_hand'
          AND fa.resolved IS NOT TRUE
          AND fa.context->>'tournament_id' = v_row.id::text);
    IF FOUND THEN v_alerts := v_alerts + 1; END IF;
  END LOOP;

  -- Informational, never alerted: events the engine guard is holding back from
  -- exactly this fate. A number climbing here is the guard working, not a leak.
  SELECT count(*) INTO v_parked
    FROM public.tournaments t
   WHERE t.status = 'COMPLETING'
     AND t.started_at IS NOT NULL
     AND t.started_at >= v_since
     AND NOT EXISTS (SELECT 1 FROM public.hand_history hh
                      WHERE hh.tournament_id = t.id);

  RETURN jsonb_build_object(
    'ok',                true,
    'since_days',        v_days,
    'flagged',           v_flagged,
    'alerts_raised',     v_alerts,
    'chips_paid',        round(v_chips, 2),
    'parked_completing', v_parked,
    'tournament_ids',    to_jsonb(v_ids));
END;
$$;


ALTER FUNCTION public.fn_detect_results_without_a_hand(p_since_days integer) OWNER TO postgres;

--
-- TOC entry 46996 (class 0 OID 0)
-- Dependencies: 6079
-- Name: FUNCTION fn_detect_results_without_a_hand(p_since_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_detect_results_without_a_hand(p_since_days integer) IS 'Flags COMPLETED tournaments that carry finishing places while hand_history holds no hand for them: a result that no poker produced. Raises one deduped critical financial_alert per offender and moves no money. Bounded to the horse-only hand retention window, past which an empty history proves nothing.';


--
-- TOC entry 7223 (class 1255 OID 72706105)
-- Name: fn_diamond_arena_club(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_arena_club() RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- The one Diamond Arena, found the way the Diamond doors and
  -- fn_poker_arena_context find it. NULL unless there is exactly one: a count
  -- of the wrong club, or of one of two, is not the arena's count.
  SELECT CASE WHEN count(*) = 1 THEN (array_agg(c.id))[1] END
    FROM public.clubs c
   WHERE c.asset = 'diamonds'
     AND c.is_platform IS TRUE
     AND c.union_id IS NULL
     AND c.lifecycle_status IS DISTINCT FROM 'retired'
     AND EXISTS (SELECT 1 FROM public.ca_arena_settings s WHERE s.club_id = c.id);
$$;


ALTER FUNCTION public.fn_diamond_arena_club() OWNER TO postgres;

--
-- TOC entry 5797 (class 1255 OID 72706133)
-- Name: fn_diamond_arena_counts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_arena_counts() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_service boolean := coalesce(auth.role(), 'service_role') = 'service_role';
  v_arena uuid;
  v_members bigint;
  v_tables bigint;
  v_seated bigint;
  v_online bigint;
  v_witness boolean;
  v_unknown jsonb := '{}'::jsonb;
BEGIN
  IF v_uid IS NULL AND NOT v_service THEN
    RAISE EXCEPTION 'Authentication Required' USING ERRCODE = '28000';
  END IF;

  v_arena := public.fn_diamond_arena_club();
  IF v_arena IS NULL THEN
    RETURN jsonb_build_object(
      'members', NULL, 'online', NULL, 'seated', NULL, 'tables', NULL,
      'unknown', jsonb_build_object(
        'members', 'arena_not_identified', 'online', 'arena_not_identified',
        'seated', 'arena_not_identified', 'tables', 'arena_not_identified'),
      'as_of', now());
  END IF;

  -- Each figure is read on its own. A read that fails leaves that figure NULL
  -- with its reason and the other figures answering.
  BEGIN
    SELECT count(*) INTO v_members
      FROM public.profiles pr
     WHERE public.fn_diamond_arena_is_player(pr.id);
  EXCEPTION WHEN OTHERS THEN
    v_members := NULL;
    v_unknown := v_unknown || jsonb_build_object('members', 'read_failed_' || SQLSTATE);
  END;

  BEGIN
    SELECT count(*) INTO v_tables
      FROM public.fn_diamond_arena_open_tables(v_arena) AS o(id);
  EXCEPTION WHEN OTHERS THEN
    v_tables := NULL;
    v_unknown := v_unknown || jsonb_build_object('tables', 'read_failed_' || SQLSTATE);
  END;

  BEGIN
    SELECT count(*) INTO v_seated
      FROM public.fn_diamond_arena_seated_players(v_arena) AS s(user_id);
  EXCEPTION WHEN OTHERS THEN
    v_seated := NULL;
    v_unknown := v_unknown || jsonb_build_object('seated', 'read_failed_' || SQLSTATE);
  END;

  -- ONLINE: the players who are here right now by any of three live sources,
  -- none of which this function writes: a live Realtime table feed (a row in
  -- realtime.subscription, which Realtime keeps for every feed a signed-in
  -- page holds open and deletes when it closes), the messenger's presence,
  -- or a live seat at an open arena table. A number only while the sources
  -- can be seen working: the caller is online by definition, so if none of
  -- them shows the caller they are not seeing where players are, and any
  -- count they give is short by an unknown amount. Without a caller there is
  -- nobody to check them against.
  IF v_uid IS NULL THEN
    v_unknown := v_unknown || jsonb_build_object('online', 'no_caller_to_witness');
  ELSE
    BEGIN
      SELECT coalesce(bool_or(present.user_id = v_uid), false),
             count(*) FILTER (WHERE public.fn_diamond_arena_is_player(present.user_id))
        INTO v_witness, v_online
        FROM (
          SELECT CASE
                   WHEN rs.claims ->> 'sub' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                   THEN (rs.claims ->> 'sub')::uuid
                 END AS user_id
            FROM realtime.subscription rs
           WHERE rs.claims ->> 'role' = 'authenticated'
          UNION
          SELECT pr.id
            FROM public.profiles pr
           WHERE coalesce(pr.is_online, false) AND pr.last_seen > now() - interval '5 minutes'
          UNION
          SELECT s.user_id
            FROM public.fn_diamond_arena_seated_players(v_arena) AS s(user_id)
        ) present
       WHERE present.user_id IS NOT NULL;
      IF NOT v_witness THEN
        v_online := NULL;
        v_unknown := v_unknown || jsonb_build_object('online', 'presence_not_reported');
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_online := NULL;
      v_unknown := v_unknown || jsonb_build_object('online', 'read_failed_' || SQLSTATE);
    END;
  END IF;

  RETURN jsonb_build_object(
    'members', v_members,
    'online', v_online,
    'seated', v_seated,
    'tables', v_tables,
    'unknown', v_unknown,
    'as_of', now());
END;
$_$;


ALTER FUNCTION public.fn_diamond_arena_counts() OWNER TO postgres;

--
-- TOC entry 46999 (class 0 OID 0)
-- Dependencies: 5797
-- Name: FUNCTION fn_diamond_arena_counts(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_diamond_arena_counts() IS 'Diamond Arena members, online, seated and open tables. Each figure is a number or NULL when it cannot be told; unknown names the reason. Online counts the players with a live Realtime feed, the messenger''s presence or a live arena seat, and is NULL unless one of those shows the caller. Migrations 20260929214500_the_arena_counts_its_players and 20260930044500_the_arena_knows_who_is_here.';


--
-- TOC entry 4334 (class 1255 OID 72706106)
-- Name: fn_diamond_arena_is_player(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_arena_is_player(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- A profile whose sign-in is live and whose account is open, that is not a
  -- certification fixture. Horses are players and are not mentioned.
  SELECT EXISTS (
    SELECT 1
      FROM public.profiles pr
      JOIN auth.users u ON u.id = pr.id
     WHERE pr.id = p_user_id
       AND u.deleted_at IS NULL
       AND pr.status IS DISTINCT FROM 'deleted'
       AND NOT public.fn_ca_is_fixture_account(pr.id)
  );
$$;


ALTER FUNCTION public.fn_diamond_arena_is_player(p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 3573 (class 1255 OID 74448909)
-- Name: fn_diamond_arena_leaderboard_period(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_arena_leaderboard_period(p_period text DEFAULT 'weekly'::text, p_limit integer DEFAULT 10, p_offset integer DEFAULT 0) RETURNS TABLE(user_id uuid, hands_played numeric, total_winnings numeric, total_losses numeric, tournaments_won numeric, sum_big_blind numeric, rank_change integer, qualified boolean, rank integer, total_ranked integer, baseline_date date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_arena uuid := public.fn_diamond_arena_club();
  v_period_start date;
  v_start_at timestamptz;
  -- The chip board's "previous" standings are its snapshot dated yesterday,
  -- taken at 00:05 UTC: everything dealt before yesterday.
  v_prev_end date := (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')::date - 1;
  v_is_all_time boolean := p_period = 'all_time';
BEGIN
  -- The one calendar window every board uses; it refuses any other period.
  SELECT bounds.start_date, bounds.start_at INTO v_period_start, v_start_at
    FROM public.fn_leaderboard_period_window(p_period, 0) bounds;

  RETURN QUERY
  WITH days AS (
    SELECT d.user_id AS uid,
           sum(d.hands_dealt)::numeric AS d_hands,
           sum(d.total_winnings) AS d_win,
           sum(d.total_losses) AS d_loss,
           sum(d.sum_big_blind) AS d_bb,
           coalesce(sum(d.total_winnings) FILTER (WHERE d.stat_date < v_prev_end), 0) AS p_win,
           coalesce(sum(d.total_losses) FILTER (WHERE d.stat_date < v_prev_end), 0) AS p_loss
      FROM public.ca_diamond_player_day d
     WHERE v_is_all_time OR d.stat_date >= v_period_start
     GROUP BY d.user_id
  ),
  -- A tournament won in the window, by trg_tournament_completed_stats' rule,
  -- counted from the arena's own events.
  wins AS (
    SELECT tp.user_id AS uid, count(*)::numeric AS d_twon
      FROM public.tournaments t
      JOIN public.tournament_players tp ON tp.tournament_id = t.id
     WHERE t.club_id = v_arena
       AND t.status = 'COMPLETED'
       AND (tp.position = 1 OR tp.status = 'winner')
       AND tp.user_id IS NOT NULL
       AND (v_is_all_time OR t.ended_at >= v_start_at)
     GROUP BY tp.user_id
  ),
  cur AS (
    SELECT coalesce(dy.uid, w.uid) AS uid,
           coalesce(dy.d_hands, 0) AS d_hands,
           coalesce(dy.d_win, 0) AS d_win,
           coalesce(dy.d_loss, 0) AS d_loss,
           coalesce(w.d_twon, 0) AS d_twon,
           coalesce(dy.d_bb, 0) AS d_bb,
           -- No previous standing for a player who had not played by then,
           -- nor for a window that had not started by then (the chip board's
           -- missing snapshot row, and its v_prev_end <= v_baseline).
           (NOT EXISTS (SELECT 1 FROM public.ca_diamond_player_day x
                         WHERE x.user_id = coalesce(dy.uid, w.uid)
                           AND x.stat_date < v_prev_end)
            OR (NOT v_is_all_time AND v_prev_end <= v_period_start)) AS no_prev,
           coalesce(dy.p_win, 0) AS p_win,
           coalesce(dy.p_loss, 0) AS p_loss
      FROM days dy
      FULL JOIN wins w ON w.uid = dy.uid
     WHERE NOT public.fn_ca_is_fixture_account(coalesce(dy.uid, w.uid))
  ),
  scored AS (
    SELECT c.*,
           (c.d_win - c.d_loss) AS score,
           (CASE WHEN c.no_prev THEN NULL ELSE (c.p_win - c.p_loss) END) AS prev_score
      FROM cur c
  ),
  ranked AS (
    SELECT s.*,
           row_number() OVER (ORDER BY s.score DESC NULLS LAST, s.uid) AS rn_now,
           rank() OVER (ORDER BY s.score DESC NULLS LAST) AS rk_now,
           count(*) OVER () AS total_active,
           CASE WHEN s.prev_score IS NULL THEN NULL
                ELSE rank() OVER (ORDER BY s.prev_score DESC NULLS LAST) END AS rk_old
      FROM scored s
     WHERE NOT EXISTS (SELECT 1 FROM public.profiles dp WHERE dp.id = s.uid AND dp.status = 'deleted')
       AND (s.d_hands > 0 OR s.d_twon > 0 OR s.d_win <> 0 OR s.d_loss <> 0)
  )
  SELECT r.uid, r.d_hands, r.d_win, r.d_loss, r.d_twon, r.d_bb,
         COALESCE((r.rk_old - r.rk_now)::integer, 0),
         true,
         r.rk_now::integer, r.total_active::integer,
         (CASE WHEN v_is_all_time THEN NULL ELSE v_period_start END)
    FROM ranked r
   ORDER BY r.rn_now
   LIMIT p_limit OFFSET GREATEST(COALESCE(p_offset, 0), 0);
END;
$$;


