CREATE FUNCTION public.fn_diamond_arena_open_tables(p_club_id uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT t.id
    FROM public.tables t
   WHERE t.club_id = p_club_id
