--
-- TOC entry 6872 (class 1255 OID 53111735)
-- Name: fn_diamond_bonus_floor(numeric, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_bonus_floor(p_bet numeric, p_boost integer, p_paid_diamonds integer, p_rate integer) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
 SELECT LEAST(
  CASE WHEN p_boost=2 THEN GREATEST(ceil(p_bet*50)/100, ceil(p_paid_diamonds::numeric*100/p_rate)/100) ELSE ceil(p_bet*50)/100 END,
  (ceil(p_bet*80)-1)/100)
$$;


