--
-- TOC entry 8444 (class 1255 OID 31436312)
-- Name: fn_diamond_bonus_spin_ticket_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_bonus_spin_ticket_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE h record; m jsonb; c public.ca_daily_bonus_claims; s public.wheel_spins;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Bonus Spin Tickets Are Permanent Receipts'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO c FROM public.ca_daily_bonus_claims WHERE id=NEW.claim_id;
  IF c.id IS NULL OR c.user_id IS DISTINCT FROM NEW.user_id OR c.bonus_date IS DISTINCT FROM NEW.bonus_date
     OR c.slot<>7 OR c.granted->>'kind' IS DISTINCT FROM 'free_spin'
     OR c.granted->>'ticket_id' IS DISTINCT FROM NEW.id::text
     OR c.granted->>'funded_by' IS DISTINCT FROM 'mint'
     OR (c.granted->>'entry_diamonds')::integer IS DISTINCT FROM 100
     OR (c.granted->>'quantity')::integer IS DISTINCT FROM 1
     OR (c.result->>'streak')::integer IS DISTINCT FROM NEW.streak
     OR NEW.funded_at IS NOT NULL OR NEW.redeemed_at IS NOT NULL THEN
    RAISE EXCEPTION 'A Bonus Spin Requires Its Claimed Daily Reward';
  END IF;
  RETURN NEW;
 END IF;
 IF (NEW.id,NEW.user_id,NEW.claim_id,NEW.bonus_date,NEW.streak,NEW.entry_diamonds,NEW.created_at)
    IS DISTINCT FROM (OLD.id,OLD.user_id,OLD.claim_id,OLD.bonus_date,OLD.streak,OLD.entry_diamonds,OLD.created_at)
    OR OLD.redeemed_spin_id IS NOT NULL THEN
  RAISE EXCEPTION 'A Bonus Spin Receipt Cannot Be Rewritten';
 END IF;
 IF auth.uid() IS DISTINCT FROM OLD.user_id THEN RAISE EXCEPTION 'That Bonus Spin Belongs To Another Player' USING ERRCODE='42501'; END IF;
 IF OLD.funded_at IS NULL THEN
  IF NEW.funded_at IS NULL OR NEW.redeemed_spin_id IS NOT NULL THEN RAISE EXCEPTION 'Invalid Bonus Spin Funding Transition'; END IF;
  SELECT * INTO h FROM public.fn_wheel_host(NEW.club_id);
  IF h.host_id IS DISTINCT FROM NEW.host_id OR h.host_kind IS DISTINCT FROM NEW.host_kind
     OR public.fn_diamond_game_owner(h.host_id,h.host_kind) IS DISTINCT FROM NEW.owner_id
     OR NOT EXISTS(SELECT 1 FROM public.club_members WHERE club_id=NEW.club_id AND user_id=NEW.user_id AND COALESCE(status,'active') IN('active','approved'))
     OR NOT EXISTS(SELECT 1 FROM public.wheel_seed_commits WHERE id=NEW.commit_id AND user_id=NEW.user_id AND consumed_by IS NULL AND expires_at>=now()) THEN
    RAISE EXCEPTION 'Bonus Spin Funding Does Not Match Its Member And Host';
  END IF;
  NEW.mint_op_id := 'daily-bonus-spin:'||NEW.id::text;
  NEW.funded_at := transaction_timestamp();
  m := public.fn_ca_mint('diamonds','player',NEW.user_id,100,
        'Daily Bonus 100 Diamond Spin Entry For Claimed Ticket '||NEW.id::text,NEW.mint_op_id,'promotional');
  IF NOT COALESCE((m->>'ok')::boolean,false) OR (m->>'amount')::numeric IS DISTINCT FROM 100
     OR m->>'target_id' IS DISTINCT FROM NEW.user_id::text THEN
   RAISE EXCEPTION 'Daily Bonus Spin Funding Is Unavailable: %',COALESCE(m->>'reason','mint_refused') USING ERRCODE='PDS01';
  END IF;
 m:=public.deduct_diamonds(NEW.user_id,100,'Claimed Daily Bonus Spin Entry','daily_bonus_spin','diamond_game',
    jsonb_build_object('recipient_id',NEW.owner_id,'ticket_id',NEW.id),NEW.mint_op_id||':custody',0);
  IF COALESCE((m->>'success')::boolean,false) IS NOT TRUE THEN RAISE EXCEPTION 'Daily Spin Entry Transfer Failed'; END IF;
  PERFORM public.fn_diamond_spin_book(NEW.owner_id,NEW.club_id,NEW.host_id,NEW.host_kind,NEW.user_id,'mint_entry',100,
    NEW.mint_op_id||':intake','Mint Funded Claimed Daily Bonus Spin');
 ELSE
  IF (NEW.club_id,NEW.host_id,NEW.host_kind,NEW.owner_id,NEW.commit_id,NEW.client_seed,NEW.mint_op_id,NEW.funded_at)
     IS DISTINCT FROM (OLD.club_id,OLD.host_id,OLD.host_kind,OLD.owner_id,OLD.commit_id,OLD.client_seed,OLD.mint_op_id,OLD.funded_at)
     OR NEW.redeemed_spin_id IS NULL THEN RAISE EXCEPTION 'Bonus Spin Funding Cannot Be Changed'; END IF;
  SELECT * INTO s FROM public.wheel_spins WHERE id=NEW.redeemed_spin_id;
  IF s.id IS NULL OR s.bonus_ticket_id IS DISTINCT FROM NEW.id OR s.user_id IS DISTINCT FROM NEW.user_id
     OR s.club_id IS DISTINCT FROM NEW.club_id OR s.host_id IS DISTINCT FROM NEW.host_id
     OR s.commit_id IS DISTINCT FROM NEW.commit_id OR s.client_seed IS DISTINCT FROM NEW.client_seed
     OR s.is_welcome OR s.spin_price_diamonds<>100 OR s.diamond_accrual<>100 THEN
    RAISE EXCEPTION 'Bonus Spin Redemption Does Not Match Its Funded Entry';
  END IF;
  NEW.redeemed_at := transaction_timestamp();
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_diamond_bonus_spin_ticket_guard() OWNER TO postgres;

--
-- TOC entry 5139 (class 1255 OID 31385499)
-- Name: fn_diamond_bonus_start(uuid, text, integer, boolean, uuid, text, text, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_bonus_start(p_club_id uuid, p_game text, p_base_diamonds integer, p_double boolean, p_commit_id uuid, p_client_seed text, p_mode text DEFAULT NULL::text, p_denom integer DEFAULT NULL::integer, p_table_version integer DEFAULT NULL::integer, p_auto_cashout_cents integer DEFAULT NULL::integer, p_max_steps integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_user uuid:=auth.uid(); prior public.diamond_bonus_entries; wanted jsonb; v_host uuid; v_kind text;
 v_result jsonb; total integer; existing_crash public.crash_rounds; existing_choice public.diamond_choice_rounds; v_refusal jsonb;
BEGIN
 IF v_user IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Sign In To Play'); END IF;
 IF p_game IS NULL OR p_game NOT IN ('plinko','crash','crossing','mines') OR p_base_diamonds IS NULL OR
  p_base_diamonds NOT BETWEEN 25 AND 2500 OR p_double IS NULL OR p_commit_id IS NULL OR
  p_client_seed IS NULL OR length(p_client_seed) NOT BETWEEN 1 AND 64 THEN
  RETURN jsonb_build_object('ok',false,'error','Choose An Entry From 25 To 2,500 Diamonds'); END IF;
 total:=p_base_diamonds*CASE WHEN p_double THEN 2 ELSE 1 END;
 wanted:=jsonb_build_object('club',p_club_id,'game',p_game,'base',p_base_diamonds,'double',p_double,
  'seed',p_client_seed,'mode',p_mode,'denom',p_denom,'table',p_table_version,'auto',p_auto_cashout_cents,'steps',p_max_steps);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_commit_id::text,94613));
 SELECT * INTO prior FROM public.diamond_bonus_entries WHERE commit_id=p_commit_id;
 IF FOUND THEN
  IF prior.user_id IS DISTINCT FROM v_user OR prior.request IS DISTINCT FROM wanted THEN
   RETURN jsonb_build_object('ok',false,'error','This Ticket Belongs To Different Bonus Settings'); END IF;
  IF p_game='crash' THEN
   SELECT * INTO existing_crash FROM public.crash_rounds WHERE commit_id=p_commit_id;
   v_result:=public.fn_crash_round_result(existing_crash);
  ELSIF p_game IN ('crossing','mines') THEN
   SELECT * INTO existing_choice FROM public.diamond_choice_rounds WHERE commit_id=p_commit_id;
   v_result:=public.fn_choice_result(existing_choice);
  ELSE v_result:=prior.result; END IF;
  RETURN v_result||jsonb_build_object('bonus',jsonb_build_object('id',prior.id,'base_diamonds',prior.base_diamonds,'added_diamonds',prior.added_diamonds,'total_diamonds',prior.total_diamonds),'replayed',true);
 END IF;
 -- DOUBLE DIAMONDS IS RETIRED (Dan 2026-10-16). A round an older page opened
 -- with the add-on replays above; a new start that asks for it is refused
 -- here, before any entry is written, so nothing is charged.
 IF p_double THEN RETURN jsonb_build_object('ok',false,'error','Double Diamonds Is No Longer Offered. Refresh To Play Your Bonus.'); END IF;
 -- No entry carries this ticket, so nothing has been charged on it. A ticket
 -- that cannot open a round is refused here, before the entry whose foreign
 -- key would otherwise turn it into an exception the client cannot read.
 v_refusal:=public.fn_diamond_ticket_refusal(v_user,p_game,p_commit_id);
 IF v_refusal IS NOT NULL THEN RETURN v_refusal; END IF;
 SELECT host_id,host_kind INTO v_host,v_kind FROM public.fn_wheel_host(p_club_id);
 IF v_host IS NULL THEN RETURN jsonb_build_object('ok',false,'error','That Club Could Not Be Found'); END IF;
 -- A caught refusal rolls back the entry and every inner money leg together.
 BEGIN
  INSERT INTO public.diamond_bonus_entries(user_id,club_id,host_id,host_kind,game,commit_id,base_diamonds,added_diamonds,request,is_fixture)
   VALUES(v_user,p_club_id,v_host,v_kind,p_game,p_commit_id,p_base_diamonds,total-p_base_diamonds,wanted,
    public.fn_ca_is_fixture_account(v_user) OR public.fn_ca_is_cert_account(v_user)) RETURNING * INTO prior;
  IF p_game='plinko' THEN v_result:=public.fn_plinko_bonus_run(p_club_id,p_commit_id,p_client_seed,total,p_denom,p_table_version);
  ELSIF p_game='crash' THEN v_result:=public.fn_crash_start(p_club_id,p_commit_id,p_client_seed,total,p_auto_cashout_cents);
  ELSE v_result:=public.fn_choice_start(p_club_id,p_game,p_mode,total,p_commit_id,p_client_seed,p_max_steps); END IF;
  IF v_result->>'ok'='true' AND (COALESCE(v_result->>'commit_id',v_result#>>'{fairness,commit_id}') IS DISTINCT FROM p_commit_id::text OR v_result->>'club_id' IS DISTINCT FROM p_club_id::text OR (v_result->>'bet_diamonds')::integer IS DISTINCT FROM total) THEN
   RAISE EXCEPTION USING MESSAGE='Resume Your Existing Round First', ERRCODE='PDB01';
  END IF;
  IF v_result->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION USING MESSAGE=COALESCE(v_result->>'error','The Bonus Could Not Start'), ERRCODE='PDB01'; END IF;
  v_result:=v_result||jsonb_build_object('bonus',jsonb_build_object('id',prior.id,'base_diamonds',p_base_diamonds,'added_diamonds',total-p_base_diamonds,'total_diamonds',total));
  UPDATE public.diamond_bonus_entries SET result=v_result WHERE id=prior.id;
  RETURN v_result;
 EXCEPTION WHEN SQLSTATE 'PDB01' THEN RETURN jsonb_build_object('ok',false,'error',SQLERRM);
 END;
END $$;


ALTER FUNCTION public.fn_diamond_bonus_start(p_club_id uuid, p_game text, p_base_diamonds integer, p_double boolean, p_commit_id uuid, p_client_seed text, p_mode text, p_denom integer, p_table_version integer, p_auto_cashout_cents integer, p_max_steps integer) OWNER TO postgres;

--
-- TOC entry 9623 (class 1255 OID 31385508)
-- Name: fn_diamond_bonus_state(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_bonus_state(p_club_id uuid, p_game text, p_total integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE state jsonb; cfg public.diamond_game_configs; pool public.diamond_game_pools; h uuid; k text; cap integer; chips numeric;
BEGIN
 IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Sign In To Play'); END IF;
 IF p_game IS NULL OR p_game NOT IN ('plinko','crash') OR p_total IS NULL OR p_total NOT BETWEEN 25 AND 5000 THEN
  RETURN jsonb_build_object('ok',false,'error','Choose A Valid Bonus Entry'); END IF;
 state:=public.fn_diamond_game_state(p_club_id,p_game);
 IF state->>'ok' IS DISTINCT FROM 'true' OR state->>'available' IS DISTINCT FROM 'true' THEN RETURN state; END IF;
 SELECT host_id,host_kind INTO h,k FROM public.fn_wheel_host(p_club_id);
 SELECT * INTO cfg FROM public.diamond_game_configs WHERE host_id=h AND game=p_game;
 SELECT * INTO pool FROM public.diamond_game_pools WHERE host_id=h AND game=p_game;
 chips:=p_total::numeric/public.fn_ca_bridge_rate();
 cap:=public.fn_diamond_game_cap_cents(cfg,pool,public.fn_diamond_game_cover(h,k),chips,cfg.max_multiplier_cents);
 RETURN state||jsonb_build_object('bets',jsonb_build_array(jsonb_build_object('bet_diamonds',p_total,'bet_chips',chips,'cap_cents',cap,'playable',cap>=101)));
END $$;


ALTER FUNCTION public.fn_diamond_bonus_state(p_club_id uuid, p_game text, p_total integer) OWNER TO postgres;

--
-- TOC entry 5714 (class 1255 OID 31352611)
-- Name: fn_diamond_flow_by_kind(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_flow_by_kind(p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user uuid := COALESCE(p_user_id, auth.uid());
    v_role text := COALESCE(auth.jwt() ->> 'role', current_user);
    v_out  jsonb;
BEGIN
    IF v_user IS NULL THEN
        RAISE EXCEPTION 'authentication_required' USING ERRCODE = '42501';
    END IF;
    IF v_role <> 'service_role' AND v_user IS DISTINCT FROM auth.uid() THEN
        RAISE EXCEPTION 'diamond_flow_is_own_only' USING ERRCODE = '42501';
    END IF;

    WITH rows AS (
        SELECT t.amount::bigint AS amount, t.created_at, b.bucket, b.label
          FROM public.diamond_transactions t
          CROSS JOIN LATERAL public.fn_diamond_kind_bucket(t.type, t.transaction_type, t.source, t.amount::bigint) b
         WHERE t.user_id = v_user AND t.amount <> 0
    ),
    agg AS (
        SELECT bucket, label,
               (amount < 0) AS spent,
               SUM(ABS(amount))::bigint AS lifetime_amount,
               COUNT(*)::integer AS lifetime_count,
               COALESCE(SUM(ABS(amount)) FILTER (WHERE created_at >= now() - interval '30 days'), 0)::bigint AS last30_amount,
               COUNT(*) FILTER (WHERE created_at >= now() - interval '30 days')::integer AS last30_count
          FROM rows
         GROUP BY bucket, label, (amount < 0)
    )
    SELECT jsonb_build_object(
        'user_id', v_user,
        'spent', COALESCE((SELECT jsonb_agg(jsonb_build_object(
                    'bucket', bucket, 'label', label,
                    'lifetime', lifetime_amount, 'lifetime_count', lifetime_count,
                    'last30', last30_amount, 'last30_count', last30_count)
                  ORDER BY lifetime_amount DESC, bucket)
                  FROM agg WHERE spent), '[]'::jsonb),
        'earned', COALESCE((SELECT jsonb_agg(jsonb_build_object(
                    'bucket', bucket, 'label', label,
                    'lifetime', lifetime_amount, 'lifetime_count', lifetime_count,
                    'last30', last30_amount, 'last30_count', last30_count)
                  ORDER BY lifetime_amount DESC, bucket)
                  FROM agg WHERE NOT spent), '[]'::jsonb),
        'spent_total',   COALESCE((SELECT SUM(lifetime_amount) FROM agg WHERE spent), 0),
        'earned_total',  COALESCE((SELECT SUM(lifetime_amount) FROM agg WHERE NOT spent), 0),
        'spent_last30',  COALESCE((SELECT SUM(last30_amount) FROM agg WHERE spent), 0),
        'earned_last30', COALESCE((SELECT SUM(last30_amount) FROM agg WHERE NOT spent), 0),
        'read_at', now()
    ) INTO v_out;

    RETURN v_out;
END;
$$;


ALTER FUNCTION public.fn_diamond_flow_by_kind(p_user_id uuid) OWNER TO postgres;

