    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.diamond_game_config_history (host_id, game, changed_by, before, after)
  VALUES (NEW.host_id, NEW.game, COALESCE(NEW.updated_by, auth.uid()),
          CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) END, to_jsonb(NEW));
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_diamond_game_config_history() OWNER TO postgres;

--
-- TOC entry 8392 (class 1255 OID 27011145)
-- Name: fn_diamond_game_cover(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_cover(p_host uuid, p_kind text) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT GREATEST(public.fn_diamond_game_promo(p_host, p_kind), 0)
       + GREATEST(public.fn_diamond_game_bank(p_host, p_kind), 0);
$$;


ALTER FUNCTION public.fn_diamond_game_cover(p_host uuid, p_kind text) OWNER TO postgres;

--
-- TOC entry 9632 (class 1255 OID 27011146)
-- Name: fn_diamond_game_cover_lock(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_cover_lock(p_host uuid, p_kind text, OUT o_promo numeric, OUT o_bank numeric, OUT o_cover numeric) RETURNS record
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_kind = 'union' THEN
    INSERT INTO public.union_wallets (union_id, created_at, updated_at) VALUES (p_host, now(), now())
    ON CONFLICT (union_id) DO NOTHING;
    SELECT COALESCE(w.promo_wallet, 0), COALESCE(w.chip_balance, 0)
      INTO o_promo, o_bank
      FROM public.union_wallets w WHERE w.union_id = p_host FOR UPDATE;
  ELSE
    SELECT COALESCE(c.promo_balance, 0), COALESCE(c.chip_treasury, 0)
      INTO o_promo, o_bank
      FROM public.clubs c WHERE c.id = p_host FOR UPDATE;
  END IF;
  -- A wallet that has somehow gone negative covers nothing; it does not get to
  -- eat the other wallet's headroom on the way past.
  o_promo := GREATEST(COALESCE(o_promo, 0), 0);
  o_bank  := GREATEST(COALESCE(o_bank, 0), 0);
  o_cover := o_promo + o_bank;
END $$;


ALTER FUNCTION public.fn_diamond_game_cover_lock(p_host uuid, p_kind text, OUT o_promo numeric, OUT o_bank numeric, OUT o_cover numeric) OWNER TO postgres;

--
-- TOC entry 6219 (class 1255 OID 53111802)
-- Name: fn_diamond_game_debit_meta(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_debit_meta(p_stake integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE a public.wheel_bonus_awards;
BEGIN a:=public.fn_wheel_starting_award();
 IF a.id IS NULL THEN RETURN jsonb_build_object('add_on',false,'added_diamonds',0,'stake_diamonds',p_stake,'paid_diamonds',p_stake); END IF;
 RETURN jsonb_build_object('add_on',p_stake>a.base_diamonds,'added_diamonds',p_stake-a.base_diamonds,'stake_diamonds',p_stake,
  'base_diamonds',a.base_diamonds,'entry_diamonds',a.entry_diamonds,'paid_diamonds',a.entry_diamonds+(p_stake-a.base_diamonds),'award_id',a.id);
END $$;


ALTER FUNCTION public.fn_diamond_game_debit_meta(p_stake integer) OWNER TO postgres;

--
-- TOC entry 9512 (class 1255 OID 53111799)
-- Name: fn_diamond_game_debit_text(text, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_debit_text(p_game text, p_stake integer, p_intake boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE a public.wheel_bonus_awards; label text; debit integer;
BEGIN a:=public.fn_wheel_starting_award();
 label:=CASE p_game WHEN 'plinko' THEN 'Diamond Plinko' WHEN 'crash' THEN 'Diamond Crash' WHEN 'mines' THEN 'Diamond Mines' WHEN 'crossing' THEN 'Donkey Cross' ELSE 'Diamond Game' END;
 debit:=public.fn_wheel_bonus_player_debit(p_stake);
 IF a.id IS NULL THEN RETURN format('%s %s (%s Diamonds)',label,CASE WHEN p_intake THEN 'Intake' ELSE 'Bet' END,p_stake); END IF;
 RETURN format('%s Double Diamonds Add-On%s (%s Diamonds Of A %s Diamond Stake)',label,CASE WHEN p_intake THEN ' Intake' ELSE '' END,debit,p_stake);
END $$;


ALTER FUNCTION public.fn_diamond_game_debit_text(p_game text, p_stake integer, p_intake boolean) OWNER TO postgres;

--
-- TOC entry 7804 (class 1255 OID 25736043)
-- Name: fn_diamond_game_floor(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_floor(p_club_id uuid, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_host uuid;
  v_lim integer;
  v_wins jsonb;
  v_points jsonb;
  v_top jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In To See The Floor');
  END IF;
  SELECT h.host_id INTO v_host FROM public.fn_wheel_host(p_club_id) h;
  IF v_host IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Club Could Not Be Found');
  END IF;
  v_lim := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 50);

  WITH rounds AS (
    SELECT 'wheel'::text AS game, s.created_at AS at, s.user_id,
           s.outcome_kind::text AS kind, s.outcome_amount::numeric AS amount,
           s.prize_value_chips::numeric AS value_chips, NULL::integer AS multiplier_cents
      FROM public.wheel_spins s
     WHERE s.host_id = v_host AND s.outcome_kind::text NOT IN ('nothing', 'bonus', 'upgrade') AND NOT COALESCE(s.is_fixture, false)
    UNION ALL
    SELECT r.game,r.settled_at,r.user_id,'chips',r.payout_chips,r.payout_chips,r.multiplier_cents
    FROM public.diamond_game_round_book r WHERE r.host_id=v_host AND NOT r.is_fixture AND r.status='cashed' AND r.payout_chips>0
  ), recent AS (
    SELECT * FROM rounds ORDER BY at DESC LIMIT v_lim
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'game', r.game,
           'at', r.at,
           'kind', r.kind,
           'amount', r.amount,
           'value_chips', r.value_chips,
           'multiplier_cents', r.multiplier_cents,
           'name', COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name), 'Player'),
           'avatar', NULLIF(pr.arena_avatar_url, ''),
           'mine', r.user_id = auth.uid()
         ) ORDER BY r.at DESC), '[]'::jsonb)
    INTO v_wins
    FROM recent r
    LEFT JOIN public.profiles pr ON pr.id = r.user_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'crash_cents', x.crash_cents,
           'cashed', x.status = 'cashed',
           'at', x.settled_at
         ) ORDER BY x.settled_at DESC), '[]'::jsonb)
    INTO v_points
    FROM (SELECT c.crash_cents, c.status, c.settled_at
            FROM public.crash_rounds c
           WHERE c.host_id = v_host AND c.status <> 'open' AND NOT COALESCE(c.is_fixture, false)
           ORDER BY c.settled_at DESC
           LIMIT 20) x;

  -- the week's biggest: the same rounds, the last seven days, by what they paid
  WITH rounds AS (
    SELECT 'wheel'::text AS game, s.created_at AS at, s.user_id,
           s.outcome_kind::text AS kind, s.outcome_amount::numeric AS amount,
           s.prize_value_chips::numeric AS value_chips, NULL::integer AS multiplier_cents
      FROM public.wheel_spins s
     WHERE s.host_id = v_host AND s.outcome_kind::text NOT IN ('nothing', 'bonus', 'upgrade') AND NOT COALESCE(s.is_fixture, false)
       AND s.created_at >= now() - interval '7 days'
    UNION ALL
    SELECT r.game,r.settled_at,r.user_id,'chips',r.payout_chips,r.payout_chips,r.multiplier_cents
    FROM public.diamond_game_round_book r WHERE r.host_id=v_host AND NOT r.is_fixture AND r.status='cashed' AND r.payout_chips>0 AND r.settled_at>=now()-interval '7 days'
  ), biggest AS (
    SELECT * FROM rounds ORDER BY value_chips DESC, at DESC LIMIT 5
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'game', b.game,
           'at', b.at,
           'kind', b.kind,
           'amount', b.amount,
           'value_chips', b.value_chips,
           'multiplier_cents', b.multiplier_cents,
           'name', COALESCE(public.fn_arena_name(pr.alias, pr.username, pr.display_name, pr.first_name, pr.last_name, pr.full_name), 'Player'),
           'avatar', NULLIF(pr.arena_avatar_url, ''),
           'mine', b.user_id = auth.uid()
         ) ORDER BY b.value_chips DESC, b.at DESC), '[]'::jsonb)
    INTO v_top
    FROM biggest b
    LEFT JOIN public.profiles pr ON pr.id = b.user_id;

  RETURN jsonb_build_object('ok', true, 'host_id', v_host, 'wins', v_wins, 'crash_points', v_points,
                            'top_week', v_top);
END $$;


ALTER FUNCTION public.fn_diamond_game_floor(p_club_id uuid, p_limit integer) OWNER TO postgres;

--
-- TOC entry 8463 (class 1255 OID 27146680)
-- Name: fn_diamond_game_fund_promo(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_fund_promo(p_club_id uuid, p_amount numeric, p_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_user uuid := auth.uid();
  v_host uuid; v_kind text;
  v_lock record;
  v_promo_after numeric; v_bank_after numeric;
  v_key text;
  v_previous public.chip_ledger%ROWTYPE;
  v_source uuid;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In First');
  END IF;

  -- The caller's token is the whole of the replay guard, so it is checked
  -- before anything is locked. A key this function cannot trust is not an
  -- excuse to fall back on a generated one - that is the bug being fixed.
  IF p_key IS NULL OR p_key !~ '^[A-Za-z0-9_-]{8,64}$' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Request Could Not Be Identified. Try Again');
  END IF;
  v_key := 'diamond-games-fund:' || p_key;

  SELECT h.host_id, h.host_kind INTO v_host, v_kind FROM public.fn_wheel_host(p_club_id) h;
  IF v_host IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Club Could Not Be Found');
  END IF;
  IF NOT public.fn_wheel_can_operate(v_host, v_kind, v_user) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Only The Host''s Owners And Admins Move This Money');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Enter How Many Chips To Move');
  END IF;
  -- Both wallet-history tables hold whole cents. Refusing in words beats
  -- throwing a constraint violation at an operator who typed one digit too many.
  IF p_amount <> round(p_amount, 2) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Chips Move In Whole Cents');
  END IF;
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'The Platform Is In Its Maintenance Break. Try Again In A Few Minutes');
  END IF;

  -- This takes the host's wallet row FOR UPDATE, which is what makes the
  -- check-then-act below safe: a second press for the same host waits here.
  SELECT c.o_promo, c.o_bank, c.o_cover INTO v_lock FROM public.fn_diamond_game_cover_lock(v_host, v_kind) c;

  -- ── the replay guard ────────────────────────────────────────────────────
  -- Union bank legs identify the wallet ROW; club legs identify the club.
  IF v_kind = 'union' THEN
    SELECT id INTO v_source FROM public.union_wallets WHERE union_id = v_host;
  ELSE
    v_source := v_host;
  END IF;
  SELECT l.* INTO v_previous FROM public.chip_ledger l WHERE l.idempotency_key = v_key;
  IF FOUND THEN
    -- A token identifies one actor, host and amount, not any later request
    -- carrying the same text. Preserve the historical namespace so old keys
    -- still replay instead of funding a second time after this upgrade.
    IF v_previous.performed_by IS DISTINCT FROM v_user
       OR v_previous.from_entity_id IS DISTINCT FROM v_source
       OR v_previous.to_entity_id IS DISTINCT FROM v_host
       OR v_previous.from_type IS DISTINCT FROM (CASE WHEN v_kind = 'union' THEN 'union_bank' ELSE 'club_treasury' END)
       OR v_previous.to_type IS DISTINCT FROM 'promo_wallet'
       OR v_previous.category IS DISTINCT FROM 'treasury_transfer'
       OR v_previous.amount IS DISTINCT FROM p_amount THEN
      RETURN jsonb_build_object('ok', false, 'error',
        'That Request Key Was Already Used For Different Funding');
    END IF;
    RETURN jsonb_build_object('ok', true, 'replayed', true,
                              'promo_chips', v_lock.o_promo,
                              'bank_chips', v_lock.o_bank,
                              'cover_chips', GREATEST(v_lock.o_promo, 0) + GREATEST(v_lock.o_bank, 0));
  END IF;

  IF v_lock.o_bank < p_amount THEN
    RETURN jsonb_build_object('ok', false, 'error', 'The Bank Does Not Hold That Many Chips',
                              'bank_chips', v_lock.o_bank);
  END IF;

  -- treasury_transfer is the vocabulary's word for chips moving between a host's
  -- own wallets; the journal refuses a category it does not know, and inventing
  -- one here would mean widening chip_ledger_category_check for a button.
  PERFORM public.fn_ca_declare_ledger('treasury_transfer', 'promo_wallet', v_host, NULL, v_key, ARRAY[]::text[]);
  IF v_kind = 'union' THEN
    UPDATE public.union_wallets
       SET chip_balance = chip_balance - p_amount,
           promo_wallet = COALESCE(promo_wallet, 0) + p_amount,
           updated_at = now()
     WHERE union_id = v_host AND chip_balance >= p_amount
     RETURNING promo_wallet, chip_balance INTO v_promo_after, v_bank_after;
  ELSE
    UPDATE public.clubs
       SET chip_treasury = chip_treasury - p_amount,
           promo_balance = COALESCE(promo_balance, 0) + p_amount,
           updated_at = now()
     WHERE id = v_host AND chip_treasury >= p_amount
     RETURNING promo_balance, chip_treasury INTO v_promo_after, v_bank_after;
  END IF;
  IF v_promo_after IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'The Bank Does Not Hold That Many Chips');
  END IF;

  -- The replay guard above reads the journal, so a move that wrote no leg
  -- would be a move that can be made twice. Refuse rather than allow that.
  IF NOT EXISTS (SELECT 1 FROM public.chip_ledger l WHERE l.idempotency_key = v_key) THEN
    RAISE EXCEPTION 'fn_diamond_game_fund_promo: the move wrote no journal leg under %, so a replay could not be told apart from a first press', v_key;
  END IF;

  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_counterparty', '', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);
  PERFORM set_config('app.ledger_idempotency_key', '', true);

  -- ── the operator's own wallet history, whichever shape the host is ──────
  IF v_kind = 'union' THEN
    INSERT INTO public.union_wallet_transactions
      (union_id, club_id, wallet, direction, amount, balance_after, tx_type, notes, created_by)
    VALUES (v_host, NULL, 'promo_wallet', 'credit', p_amount, v_promo_after, 'treasury_transfer',
            'Moved Into The Promo Wallet For The Diamond Games', v_user);
  ELSE
    INSERT INTO public.club_wallet_transactions
      (club_id, type, amount, balance_after, actor_id, reason)
    VALUES (v_host, 'other', -p_amount, v_bank_after,  v_user,
            'Moved Into The Promo Wallet For The Diamond Games');
  END IF;

  RETURN jsonb_build_object('ok', true, 'replayed', false,
                            'promo_chips', v_promo_after, 'bank_chips', v_bank_after,
                            'cover_chips', GREATEST(v_promo_after, 0) + GREATEST(v_bank_after, 0));
END $_$;


ALTER FUNCTION public.fn_diamond_game_fund_promo(p_club_id uuid, p_amount numeric, p_key text) OWNER TO postgres;

--
-- TOC entry 5432 (class 1255 OID 24019157)
-- Name: fn_diamond_game_history(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_history(p_club_id uuid, p_game text, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_host uuid; v_out jsonb;
BEGIN
  SELECT h.host_id INTO v_host FROM public.fn_wheel_host(p_club_id) h;
  IF p_game = 'plinko' THEN
    SELECT COALESCE(jsonb_agg(public.fn_plinko_drop_result(d) ORDER BY d.created_at DESC), '[]'::jsonb) INTO v_out
      FROM (SELECT * FROM public.plinko_drops x WHERE x.user_id = auth.uid() AND x.host_id = v_host
             ORDER BY x.created_at DESC LIMIT LEAST(GREATEST(COALESCE(p_limit, 25), 1), 100)) d;
  ELSIF p_game = 'crash' THEN
    SELECT COALESCE(jsonb_agg(public.fn_crash_round_result(c) ORDER BY c.created_at DESC), '[]'::jsonb) INTO v_out
      FROM (SELECT * FROM public.crash_rounds x WHERE x.user_id = auth.uid() AND x.host_id = v_host AND x.status <> 'open'
             ORDER BY x.created_at DESC LIMIT LEAST(GREATEST(COALESCE(p_limit, 25), 1), 100)) c;
  ELSE
    v_out := '[]'::jsonb;
  END IF;
  RETURN v_out;
END $$;


ALTER FUNCTION public.fn_diamond_game_history(p_club_id uuid, p_game text, p_limit integer) OWNER TO postgres;

--
-- TOC entry 5433 (class 1255 OID 138649783)
-- Name: fn_diamond_game_lifetime(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_lifetime(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE host uuid; result jsonb;
BEGIN
 IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Sign In To See Game Averages'); END IF;
 SELECT h.host_id INTO host FROM public.fn_wheel_host(p_club_id) h;
 IF host IS NULL THEN RETURN jsonb_build_object('ok',false,'error','That Club Could Not Be Found'); END IF;
 WITH played AS (
  SELECT r.game, r.payout_chips/NULLIF(r.bet_chips,0) paid_return,
   cardinality(r.picked)-CASE WHEN r.status='lost' THEN 1 ELSE 0 END safe_steps,
   r.status='lost' lost, NULL::numeric crash_point
  FROM public.diamond_choice_rounds r WHERE r.host_id=host AND r.status<>'open' AND NOT r.is_fixture
  UNION ALL
  SELECT 'crash',c.payout_chips/NULLIF(c.bet_chips,0),NULL,c.status='crashed',c.crash_cents::numeric/100
  FROM public.crash_rounds c WHERE c.host_id=host AND c.status<>'open' AND NOT c.is_fixture
  UNION ALL
  SELECT 'plinko',(e.result->>'payout_chips')::numeric/NULLIF(e.total_diamonds::numeric/(e.result->>'diamonds_per_chip')::integer,0),NULL,false,NULL
  FROM public.diamond_bonus_entries e WHERE e.host_id=host AND e.game='plinko' AND e.result IS NOT NULL AND NOT e.is_fixture
  UNION ALL
  SELECT 'plinko',d.payout_chips/NULLIF(d.bet_chips,0),NULL,false,NULL
  FROM public.plinko_drops d WHERE d.host_id=host AND NOT d.is_fixture
  UNION ALL
  SELECT 'wheel',(CASE WHEN s.outcome_kind::text IN ('bonus','upgrade') THEN 0 ELSE s.prize_value_chips END)/NULLIF(s.spin_price_diamonds::numeric/s.diamonds_per_chip,0),NULL,false,NULL
  FROM public.wheel_spins s WHERE s.host_id=host AND NOT s.is_fixture
 ), totals AS (
  SELECT g.game,count(p.game) rounds,avg(p.paid_return) average_return,avg(p.safe_steps) average_safe_steps,
   count(p.game) FILTER (WHERE p.lost) losses,avg(p.safe_steps) FILTER (WHERE p.lost) average_before_loss,
   avg(p.crash_point) average_crash
  FROM unnest(ARRAY['wheel','mines','crossing','crash','plinko']) WITH ORDINALITY g(game,ordinal)
  LEFT JOIN played p ON p.game=g.game GROUP BY g.game,g.ordinal ORDER BY g.ordinal
 ) SELECT jsonb_agg(to_jsonb(t)) INTO result FROM totals t;
 RETURN jsonb_build_object('ok',true,'games',result);
END $$;


ALTER FUNCTION public.fn_diamond_game_lifetime(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 6243 (class 1255 OID 24019163)
-- Name: fn_diamond_game_metrics(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_metrics(p_club_id uuid, p_game text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_host uuid; v_kind text;
  cfg public.diamond_game_configs%ROWTYPE;
  pool public.diamond_game_pools%ROWTYPE;
  v_rate integer := public.fn_ca_bridge_rate();
  v_windows jsonb; v_bank numeric; v_open integer := 0;
  v_invariant_ok boolean;
BEGIN
  IF p_game IS NULL OR p_game NOT IN ('plinko', 'crash', 'crossing', 'mines') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Game Does Not Exist');
  END IF;
  SELECT h.host_id, h.host_kind INTO v_host, v_kind FROM public.fn_wheel_host(p_club_id) h;
  IF v_host IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'That Club Could Not Be Found'); END IF;
  IF NOT public.fn_wheel_can_operate(v_host, v_kind, v_user) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Only The Host Owner Or An Admin May Read These Metrics');
  END IF;
  SELECT * INTO cfg FROM public.diamond_game_configs WHERE host_id = v_host AND game = p_game;
  SELECT * INTO pool FROM public.diamond_game_pools WHERE host_id = v_host AND game = p_game;
  IF cfg.host_id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'configured', false, 'game', p_game, 'host_id', v_host, 'host_kind', v_kind);
  END IF;
  -- The bank behind the payouts is the host's PROMO WALLET (Dan 2026-09-10).
  v_bank := public.fn_diamond_game_cover(v_host, v_kind);

  SELECT count(*) INTO v_open FROM public.diamond_game_round_book WHERE host_id=v_host AND game=p_game AND status='open';
  -- A player's adaptive stopping target is not known on losing rounds. Report
  -- the settled books without inventing a variance or a drift verdict.
  SELECT jsonb_agg(jsonb_build_object('window',lbl,'rounds',n,'intake_chips',intake,'paid_chips',paid,
   'realized_rtp',CASE WHEN intake>0 THEN round(paid/intake,4) END,'z',NULL,'constrained',constrained,'drift',NULL) ORDER BY lbl)
   INTO v_windows FROM (
    SELECT lbl,count(r.id) n,COALESCE(sum(r.bet_chips),0) intake,COALESCE(sum(r.payout_chips),0) paid,
     count(r.id) FILTER(WHERE r.constrained) constrained
    FROM (VALUES('1h',interval '1 hour'),('24h',interval '24 hours'),('7d',interval '7 days')) win(lbl,span)
    LEFT JOIN public.diamond_game_round_book r ON r.host_id=v_host AND r.game=p_game AND NOT r.is_fixture
      AND r.status<>'open' AND r.created_at>=now()-win.span GROUP BY lbl) x;

  v_invariant_ok := pool.host_id IS NULL
                 OR (pool.chips_paid + pool.reserved_chips
                       <= round(pool.intake_diamonds::numeric / v_rate, 2) + cfg.exposure_allowance_chips);
  IF NOT v_invariant_ok THEN
    BEGIN
      PERFORM public.fn_ca_raise_drift_incident(
        p_source => p_game || '_invariant', p_classification => 'unauthorized_adjustment', p_severity => 'critical',
        p_dedupe_key => p_game || ':invariant:' || v_host::text,
        p_discrepancy => pool.chips_paid + pool.reserved_chips - round(pool.intake_diamonds::numeric / v_rate, 2) - cfg.exposure_allowance_chips,
        p_expected => round(pool.intake_diamonds::numeric / v_rate, 2) + cfg.exposure_allowance_chips, p_actual => pool.chips_paid + pool.reserved_chips,
        p_layer => 'settlement', p_entity_type => 'diamond_game_pool', p_entity_id => v_host,
        p_union_id => CASE WHEN v_kind = 'union' THEN v_host END,
        p_club_id => CASE WHEN v_kind = 'club' THEN v_host END,
        p_suspected_cause => 'Diamond ' || p_game || ' paid or reserved more chips than it took in plus the allowance; the per-round cap was bypassed',
        p_metadata => to_jsonb(pool));
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'owner_agreed', public.fn_diamond_spins_owner_agreed(v_host,v_kind), 'configured', true, 'game', p_game, 'host_id', v_host, 'host_kind', v_kind,
    'config', to_jsonb(cfg),
    'pool', to_jsonb(pool),
    'cover_chips', COALESCE(v_bank, 0),
    'promo_chips', public.fn_diamond_game_promo(v_host, v_kind),
    'bank_chips', public.fn_diamond_game_bank(v_host, v_kind),
    'open_rounds', v_open,
    'intake_chips', round(COALESCE(pool.intake_diamonds, 0)::numeric / v_rate, 2),
    'owner_id', public.fn_diamond_game_owner(v_host, v_kind),
    'owner_diamonds', (SELECT COALESCE(p.diamonds, 0) FROM public.profiles p WHERE p.id = public.fn_diamond_game_owner(v_host, v_kind)),
    'exposure_chips', COALESCE(pool.chips_paid, 0) + COALESCE(pool.reserved_chips, 0) - round(COALESCE(pool.intake_diamonds, 0)::numeric / v_rate, 2),
    'exposure_headroom_chips', cfg.exposure_allowance_chips - (COALESCE(pool.chips_paid, 0) + COALESCE(pool.reserved_chips, 0) - round(COALESCE(pool.intake_diamonds, 0)::numeric / v_rate, 2)),
    'realized_rtp_lifetime', CASE WHEN COALESCE(pool.intake_diamonds, 0) > 0
        THEN round(pool.chips_paid / (pool.intake_diamonds::numeric / v_rate), 4) END,
    'house_take_lifetime_chips', CASE WHEN pool.host_id IS NOT NULL
        THEN round(pool.intake_diamonds::numeric / v_rate - pool.chips_paid, 2) END,
    'constrained_rate', CASE WHEN COALESCE(pool.rounds, 0) > 0 THEN round(pool.constrained_rounds::numeric / pool.rounds, 4) END,
    'invariant_ok', v_invariant_ok,
    'windows', COALESCE(v_windows, '[]'::jsonb),
    'tables', CASE WHEN p_game = 'plinko' THEN
        (SELECT jsonb_agg(jsonb_build_object('version', t.version, 'name', t.name, 'spec_rtp', t.spec_rtp,
                                             'sd_chips', t.sd_chips, 'hit_rate', t.hit_rate, 'max_multiplier_cents', t.max_multiplier_cents,
                                             'activated_at', t.activated_at) ORDER BY t.version)
           FROM public.plinko_tables t) END);
END $$;


ALTER FUNCTION public.fn_diamond_game_metrics(p_club_id uuid, p_game text) OWNER TO postgres;

--
-- TOC entry 5566 (class 1255 OID 26989999)
-- Name: fn_diamond_game_owner(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_owner(p_host uuid, p_kind text) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE WHEN p_kind = 'union' THEN (SELECT u.owner_id FROM public.unions u WHERE u.id = p_host)
              ELSE (SELECT c.owner_id FROM public.clubs c WHERE c.id = p_host) END;
$$;


