--
-- TOC entry 7919 (class 1255 OID 53111790)
-- Name: fn_diamond_game_paid_diamonds(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_paid_diamonds(p_stake integer) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE a public.wheel_bonus_awards;
BEGIN a:=public.fn_wheel_starting_award();
 IF a.id IS NULL THEN RETURN p_stake; END IF;
 IF p_stake NOT IN(a.base_diamonds,a.base_diamonds+a.entry_diamonds) THEN RAISE EXCEPTION 'Invalid Award Budget'; END IF;
 RETURN a.entry_diamonds+(p_stake-a.base_diamonds);
END $$;


ALTER FUNCTION public.fn_diamond_game_paid_diamonds(p_stake integer) OWNER TO postgres;

--
-- TOC entry 3761 (class 1255 OID 27011147)
-- Name: fn_diamond_game_pay_chips(text, uuid, text, uuid, uuid, numeric, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_pay_chips(p_category text, p_host uuid, p_kind text, p_club uuid, p_user uuid, p_amount numeric, p_key text, p_note text, p_meta jsonb, OUT promo_after numeric, OUT bank_after numeric, OUT cover_after numeric, OUT member_after numeric, OUT from_promo numeric, OUT from_bank numeric) RETURNS record
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lock record;
BEGIN
  from_promo := 0;
  from_bank  := 0;
  IF COALESCE(p_amount, 0) <= 0 THEN
    SELECT c.o_promo, c.o_bank, c.o_cover INTO promo_after, bank_after, cover_after
      FROM public.fn_diamond_game_cover_lock(p_host, p_kind) c;
    SELECT COALESCE(m.chip_balance, 0) INTO member_after FROM public.club_members m
     WHERE m.club_id = p_club AND m.user_id = p_user LIMIT 1;
    RETURN;
  END IF;

  SELECT c.o_promo, c.o_bank, c.o_cover INTO v_lock FROM public.fn_diamond_game_cover_lock(p_host, p_kind) c;
  from_promo := LEAST(p_amount, v_lock.o_promo);
  from_bank  := p_amount - from_promo;
  IF from_bank > v_lock.o_bank THEN
    RAISE EXCEPTION 'diamond games: cover % is below the % payout of % after the gate passed',
      v_lock.o_cover, p_category, p_amount;
  END IF;

  promo_after := v_lock.o_promo;
  bank_after  := v_lock.o_bank;

  /* THE JOURNAL LEG NAMES THE CLUB THE PRIZE LANDED IN (2026-09-20).
     club_members is autoskipped below, so the leg fn_ca_autoledger
     actually journals is the HOST debit - and for a union host that is
     union_wallets, which has no club_id column. Every union-hosted prize
     was therefore journalled club-less, and fn_chip_drift_since_baseline
     filters movements on club_id IS NOT NULL while counting the balance
     they explain: 15 correctly paid prizes read as 175.58 of member
     drift. The prize lands in p_club. Say so.
     NOT app.ledger_club_id: that name decides which club a WALLET
     credit is paid into (atomic_credit_wallet_and_log) and is set and
     restored by the rakeback close. Clearing it here would move money. */
  PERFORM set_config('app.ledger_autoledger_club_id', COALESCE(p_club::text, ''), true);

  IF from_promo > 0 THEN
    PERFORM public.fn_ca_declare_ledger(p_category, 'player_wallet', p_user, NULL, p_key, ARRAY['club_members']);
    IF p_kind = 'union' THEN
      UPDATE public.union_wallets SET promo_wallet = COALESCE(promo_wallet, 0) - from_promo, updated_at = now()
       WHERE union_id = p_host AND COALESCE(promo_wallet, 0) >= from_promo
       RETURNING promo_wallet INTO promo_after;
    ELSE
      UPDATE public.clubs SET promo_balance = COALESCE(promo_balance, 0) - from_promo, updated_at = now()
       WHERE id = p_host AND COALESCE(promo_balance, 0) >= from_promo
       RETURNING promo_balance INTO promo_after;
    END IF;
    IF promo_after IS NULL THEN
      RAISE EXCEPTION 'diamond games: the promo wallet refused the % payout of %', p_category, from_promo;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.chip_ledger WHERE idempotency_key = p_key) THEN
      RAISE EXCEPTION 'diamond games: the promo wallet moved but no leg was journaled for %', p_key;
    END IF;
    UPDATE public.club_members SET chip_balance = COALESCE(chip_balance, 0) + from_promo, updated_at = now()
     WHERE club_id = p_club AND user_id = p_user
       AND COALESCE(status, 'active') IN ('active', 'approved')
     RETURNING chip_balance INTO member_after;
    IF member_after IS NULL THEN
      RAISE EXCEPTION 'diamond games: the % payout landed nowhere for % in club %', p_category, p_user, p_club;
    END IF;
  END IF;

  IF from_bank > 0 THEN
    -- THE BANK BACKS IT (Dan 2026-09-10). Its own key, so the split reads as two
    -- rows that add up to the prize rather than one row that hides where half of
    -- it came from.
    PERFORM public.fn_ca_declare_ledger(p_category, 'player_wallet', p_user, NULL, p_key || ':bank', ARRAY['club_members']);
    IF p_kind = 'union' THEN
      UPDATE public.union_wallets SET chip_balance = COALESCE(chip_balance, 0) - from_bank, updated_at = now()
       WHERE union_id = p_host AND COALESCE(chip_balance, 0) >= from_bank
       RETURNING chip_balance INTO bank_after;
    ELSE
      UPDATE public.clubs SET chip_treasury = COALESCE(chip_treasury, 0) - from_bank, updated_at = now()
       WHERE id = p_host AND COALESCE(chip_treasury, 0) >= from_bank
       RETURNING chip_treasury INTO bank_after;
    END IF;
    IF bank_after IS NULL THEN
      RAISE EXCEPTION 'diamond games: the host bank refused the % payout of %', p_category, from_bank;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.chip_ledger WHERE idempotency_key = p_key || ':bank') THEN
      RAISE EXCEPTION 'diamond games: the host bank moved but no leg was journaled for %', p_key || ':bank';
    END IF;
    UPDATE public.club_members SET chip_balance = COALESCE(chip_balance, 0) + from_bank, updated_at = now()
     WHERE club_id = p_club AND user_id = p_user
       AND COALESCE(status, 'active') IN ('active', 'approved')
     RETURNING chip_balance INTO member_after;
    IF member_after IS NULL THEN
      RAISE EXCEPTION 'diamond games: the % payout landed nowhere for % in club %', p_category, p_user, p_club;
    END IF;
  END IF;

  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_counterparty', '', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);
  PERFORM set_config('app.ledger_idempotency_key', '', true);
  PERFORM set_config('app.ledger_autoledger_club_id', '', true);
  -- The autoskip is transaction-scoped and fn_ca_declare_ledger only sets it.
  -- Cleared here so a later balance write in the same transaction is journaled:
  -- left set, the next write on this table would silently write no journal row.
  PERFORM set_config('app.ledger_autoskip_club_members', '', true);
  PERFORM set_config('app.ledger_autoskip_union_wallets', '', true);
  PERFORM set_config('app.ledger_autoskip_clubs', '', true);

  cover_after := GREATEST(promo_after, 0) + GREATEST(bank_after, 0);

  IF p_kind = 'union' THEN
    IF from_promo > 0 THEN
      INSERT INTO public.union_wallet_transactions
        (union_id, club_id, wallet, direction, amount, balance_after, tx_type, notes, created_by)
      VALUES (p_host, p_club, 'promo_wallet', 'debit', from_promo, promo_after, p_category, p_note, p_user);
    END IF;
    IF from_bank > 0 THEN
      INSERT INTO public.union_wallet_transactions
        (union_id, club_id, wallet, direction, amount, balance_after, tx_type, notes, created_by)
      VALUES (p_host, p_club, 'chip_balance', 'debit', from_bank, bank_after, p_category,
              p_note || ' (promo wallet was short, the bank covered it)', p_user);
    END IF;
  END IF;

  INSERT INTO public.chip_transactions (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
  VALUES (p_club, NULL, p_user, p_amount, p_category, p_note,
          COALESCE(p_meta, '{}'::jsonb) || jsonb_build_object('from_promo', from_promo, 'from_bank', from_bank),
          member_after);
END $$;


ALTER FUNCTION public.fn_diamond_game_pay_chips(p_category text, p_host uuid, p_kind text, p_club uuid, p_user uuid, p_amount numeric, p_key text, p_note text, p_meta jsonb, OUT promo_after numeric, OUT bank_after numeric, OUT cover_after numeric, OUT member_after numeric, OUT from_promo numeric, OUT from_bank numeric) OWNER TO postgres;

--
-- TOC entry 3424 (class 1255 OID 26990002)
-- Name: fn_diamond_game_pay_diamonds(uuid, uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_pay_diamonds(p_owner uuid, p_user uuid, p_amount integer, p_note text, p_reference text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_res jsonb;
BEGIN
  IF p_amount <= 0 THEN RETURN; END IF;
  IF p_owner IS NULL THEN
    RAISE EXCEPTION 'diamond games: no owner to pay the diamond prize %', p_reference;
  END IF;
  v_res := public.add_diamonds_to_balance(p_owner, -p_amount, 'transfer', p_note, p_reference || ':host', p_user);
  IF COALESCE((v_res->>'success')::boolean, false) = false THEN
    RAISE EXCEPTION 'diamond games: the host owner could not pay the diamond prize %: %', p_reference, v_res->>'error';
  END IF;
  v_res := public.add_diamonds_to_balance(p_user, p_amount, 'transfer', p_note, p_reference, p_owner);
  IF COALESCE((v_res->>'success')::boolean, false) = false THEN
    RAISE EXCEPTION 'diamond games: the diamond prize could not be credited %: %', p_reference, v_res->>'error';
  END IF;
END $$;


ALTER FUNCTION public.fn_diamond_game_pay_diamonds(p_owner uuid, p_user uuid, p_amount integer, p_note text, p_reference text) OWNER TO postgres;

--
-- TOC entry 3827 (class 1255 OID 27191619)
-- Name: fn_diamond_game_players(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_players(p_club_id uuid, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_host uuid; v_kind text;
  v_rate integer := public.fn_ca_bridge_rate();
  v_spin_cap integer; v_round_cap integer;
  v_rows jsonb; v_n integer := LEAST(GREATEST(COALESCE(p_limit, 25), 1), 200);
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In First');
  END IF;
  SELECT h.host_id, h.host_kind INTO v_host, v_kind FROM public.fn_wheel_host(p_club_id) h;
  IF v_host IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Club Could Not Be Found');
  END IF;
  IF NOT public.fn_wheel_can_operate(v_host, v_kind, v_user) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Only The Host''s Owners And Admins Read This');
  END IF;
  SELECT max_spins_per_player_per_day INTO v_spin_cap FROM public.wheel_configs WHERE host_id = v_host;
  SELECT max(max_rounds_per_player_per_day) INTO v_round_cap FROM public.diamond_game_configs WHERE host_id = v_host;

  WITH ev AS (
    -- The day the CAPS are counted on, so the console and the door agree about
    -- when the day turns.
    SELECT s.user_id, 'wheel'::text AS game, 1 AS spins, 0 AS rounds,
           CASE WHEN s.is_welcome THEN 0 ELSE s.spin_price_diamonds END::numeric AS spent_dia,
           CASE WHEN s.outcome_kind = 'chips' THEN COALESCE(s.outcome_amount, 0) ELSE 0 END AS won_chips,
           CASE WHEN s.outcome_kind = 'diamonds' THEN COALESCE(s.outcome_amount, 0) ELSE 0 END AS won_dia
      FROM public.wheel_spins s
     WHERE s.host_id = v_host AND NOT COALESCE(s.is_fixture, false)
       AND (s.created_at AT TIME ZONE 'America/Chicago')::date = (now() AT TIME ZONE 'America/Chicago')::date
    UNION ALL
    SELECT r.user_id,r.game,0,1,r.bet_diamonds::numeric,r.payout_chips,0 FROM public.diamond_game_round_book r
    WHERE r.host_id=v_host AND NOT r.is_fixture
    AND (r.created_at AT TIME ZONE 'America/Chicago')::date=(now() AT TIME ZONE 'America/Chicago')::date
  ), agg AS (
    SELECT user_id,
           sum(spins)::integer AS spins,
           sum(rounds)::integer AS rounds,
           sum(spent_dia) AS spent_dia,
           sum(won_chips) AS won_chips,
           sum(won_dia) AS won_dia
      FROM ev GROUP BY user_id
  )
  SELECT jsonb_agg(r ORDER BY (r->>'spent_diamonds')::numeric DESC) INTO v_rows
    FROM (
      SELECT jsonb_build_object(
               'user_id', a.user_id,
               'name', public.fn_player_display_name(a.user_id),
               'spins', a.spins,
               'rounds', a.rounds,
               'spins_cap', COALESCE(v_spin_cap, 0),
               'rounds_cap', COALESCE(v_round_cap, 0),
               'at_spin_cap', COALESCE(v_spin_cap, 0) > 0 AND a.spins >= v_spin_cap,
               'at_round_cap', EXISTS (SELECT 1 FROM ev e JOIN public.diamond_game_configs c ON c.host_id=v_host AND c.game=e.game WHERE e.user_id=a.user_id GROUP BY e.game,c.max_rounds_per_player_per_day HAVING count(*)>=c.max_rounds_per_player_per_day),
               'spent_diamonds', a.spent_dia,
               'spent_chips', round(a.spent_dia / v_rate, 2),
               'won_chips', round(a.won_chips, 2),
               'won_diamonds', a.won_dia,
               -- What the player is up or down, from the player's side.
               'net_chips', round(a.won_chips + a.won_dia / v_rate - a.spent_dia / v_rate, 2)) AS r
        FROM agg a
       ORDER BY a.spent_dia DESC
       LIMIT v_n
    ) t;

  RETURN jsonb_build_object('ok', true, 'host_id', v_host, 'host_kind', v_kind,
                            'diamonds_per_chip', v_rate,
                            'spins_cap', COALESCE(v_spin_cap, 0),
                            'rounds_cap', COALESCE(v_round_cap, 0),
                            'players', COALESCE(v_rows, '[]'::jsonb));
END $$;


ALTER FUNCTION public.fn_diamond_game_players(p_club_id uuid, p_limit integer) OWNER TO postgres;

--
-- TOC entry 4351 (class 1255 OID 27191610)
-- Name: fn_diamond_game_pnl(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_pnl(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_host uuid; v_kind text;
  v_rate integer := public.fn_ca_bridge_rate();
  v_windows jsonb;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In First');
  END IF;
  SELECT h.host_id, h.host_kind INTO v_host, v_kind FROM public.fn_wheel_host(p_club_id) h;
  IF v_host IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Club Could Not Be Found');
  END IF;
  IF NOT public.fn_wheel_can_operate(v_host, v_kind, v_user) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Only The Host''s Owners And Admins Read This');
  END IF;

  WITH ev AS (
    SELECT 'wheel'::text AS game, s.created_at AS at,
           CASE WHEN s.is_welcome THEN 0 ELSE s.spin_price_diamonds END::numeric AS intake_dia,
           CASE WHEN s.is_welcome THEN 0
                WHEN s.outcome_kind = 'chips' THEN COALESCE(s.outcome_amount, 0) ELSE 0 END AS chips_out,
           CASE WHEN s.is_welcome THEN 0
                WHEN s.outcome_kind = 'diamonds' THEN COALESCE(s.outcome_amount, 0) ELSE 0 END AS dia_out,
           CASE WHEN s.is_welcome THEN COALESCE(s.prize_value_chips, 0) ELSE 0 END AS welcome_chips
      FROM public.wheel_spins s
     WHERE s.host_id = v_host AND NOT COALESCE(s.is_fixture, false)
    UNION ALL
    SELECT r.game,r.created_at,r.bet_diamonds::numeric,r.payout_chips,0,0 FROM public.diamond_game_round_book r
    WHERE r.host_id=v_host AND NOT r.is_fixture AND r.status<>'open'
  ), w(lbl, ord, since) AS (
    VALUES ('24 Hours', 1, now() - interval '24 hours'),
           ('7 Days',   2, now() - interval '7 days'),
           ('30 Days',  3, now() - interval '30 days'),
           ('All Time', 4, '-infinity'::timestamptz)
  ), per_game AS (
    SELECT w.lbl, w.ord, ev.game,
           count(*)::integer AS rounds,
           sum(ev.intake_dia) AS intake_dia,
           sum(ev.chips_out) AS chips_out,
           sum(ev.dia_out) AS dia_out,
           sum(ev.welcome_chips) AS welcome_chips
      FROM w JOIN ev ON ev.at >= w.since
     GROUP BY w.lbl, w.ord, ev.game
  ), per_window AS (
    SELECT w.lbl, w.ord,
           COALESCE(count(ev.*), 0)::integer AS rounds,
           COALESCE(sum(ev.intake_dia), 0) AS intake_dia,
           COALESCE(sum(ev.chips_out), 0) AS chips_out,
           COALESCE(sum(ev.dia_out), 0) AS dia_out,
           COALESCE(sum(ev.welcome_chips), 0) AS welcome_chips
      FROM w LEFT JOIN ev ON ev.at >= w.since
     GROUP BY w.lbl, w.ord
  )
  SELECT jsonb_agg(
           jsonb_build_object(
             'window', p.lbl,
             'rounds', p.rounds,
             'intake_diamonds', p.intake_dia,
             'intake_chips', round(p.intake_dia / v_rate, 2),
             'chips_paid', round(p.chips_out, 2),
             'diamonds_paid', p.dia_out,
             'welcome_chips', round(p.welcome_chips, 2),
             'net_chips', round(p.intake_dia / v_rate - p.chips_out - p.dia_out / v_rate - p.welcome_chips, 2),
             'games', COALESCE((
                SELECT jsonb_agg(jsonb_build_object(
                         'game', g.game,
                         'rounds', g.rounds,
                         'intake_diamonds', g.intake_dia,
                         'chips_paid', round(g.chips_out, 2),
                         'diamonds_paid', g.dia_out,
                         'net_chips', round(g.intake_dia / v_rate - g.chips_out - g.dia_out / v_rate - g.welcome_chips, 2))
                       ORDER BY g.game)
                  FROM per_game g WHERE g.lbl = p.lbl), '[]'::jsonb))
           ORDER BY p.ord)
    INTO v_windows
    FROM per_window p;

  RETURN jsonb_build_object('ok', true, 'host_id', v_host, 'host_kind', v_kind,
                            'diamonds_per_chip', v_rate,
                            'windows', COALESCE(v_windows, '[]'::jsonb));
END $$;


ALTER FUNCTION public.fn_diamond_game_pnl(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 5152 (class 1255 OID 24019122)
-- Name: fn_diamond_game_prize_leg(text, uuid, text, uuid, uuid, numeric, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_prize_leg(p_game text, p_host uuid, p_kind text, p_club uuid, p_user uuid, p_amount numeric, p_key text, p_note text, p_meta jsonb, OUT bank_after numeric, OUT member_after numeric) RETURNS record
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pay record;
BEGIN
  IF COALESCE(p_amount, 0) <= 0 THEN
    RETURN;
  END IF;
  SELECT * INTO v_pay FROM public.fn_diamond_game_pay_chips(
    p_game || '_prize', p_host, p_kind, p_club, p_user, p_amount, p_key, p_note, p_meta);
  bank_after   := v_pay.cover_after;
  member_after := v_pay.member_after;
END $$;


ALTER FUNCTION public.fn_diamond_game_prize_leg(p_game text, p_host uuid, p_kind text, p_club uuid, p_user uuid, p_amount numeric, p_key text, p_note text, p_meta jsonb, OUT bank_after numeric, OUT member_after numeric) OWNER TO postgres;

--
-- TOC entry 7618 (class 1255 OID 26990001)
-- Name: fn_diamond_game_promo(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_promo(p_host uuid, p_kind text) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(CASE WHEN p_kind = 'union' THEN (SELECT w.promo_wallet FROM public.union_wallets w WHERE w.union_id = p_host)
                       ELSE (SELECT c.promo_balance FROM public.clubs c WHERE c.id = p_host) END, 0);
$$;


ALTER FUNCTION public.fn_diamond_game_promo(p_host uuid, p_kind text) OWNER TO postgres;

--
-- TOC entry 4630 (class 1255 OID 31385536)
-- Name: fn_diamond_game_quote_max(text, numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_quote_max(p_game text, p_bet numeric, p_cap integer) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE best numeric:=0; prize numeric;
BEGIN
 IF p_game='plinko' THEN
  SELECT COALESCE(max(p_bet*max_multiplier_cents/100),0) INTO best FROM public.plinko_tables WHERE activated_at IS NOT NULL AND max_multiplier_cents<=p_cap;
 ELSIF p_game='crash' THEN IF p_cap>=101 THEN best:=ceil(p_bet*p_cap)/100; END IF;
 ELSE
  -- The one setting this game deals (fn_choice_mode), never a retired one.
  FOREACH prize IN ARRAY public.fn_choice_prizes(p_game,public.fn_choice_mode(p_game),p_bet) LOOP
   IF ceil(prize*100)/100<=p_bet*p_cap/100 THEN best:=GREATEST(best,ceil(prize*100)/100); END IF;
  END LOOP;
 END IF;
 RETURN best;
END $$;


ALTER FUNCTION public.fn_diamond_game_quote_max(p_game text, p_bet numeric, p_cap integer) OWNER TO postgres;

--
-- TOC entry 8113 (class 1255 OID 31385453)
-- Name: fn_diamond_game_reserved_cover_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_reserved_cover_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE host uuid; cover numeric; old_cover numeric; held numeric;
BEGIN
 IF TG_TABLE_NAME='clubs' THEN
  host:=NEW.id; cover:=GREATEST(COALESCE(NEW.promo_balance,0),0)+GREATEST(COALESCE(NEW.chip_treasury,0),0);
  old_cover:=GREATEST(COALESCE(OLD.promo_balance,0),0)+GREATEST(COALESCE(OLD.chip_treasury,0),0);
 ELSE
  host:=NEW.union_id; cover:=GREATEST(COALESCE(NEW.promo_wallet,0),0)+GREATEST(COALESCE(NEW.chip_balance,0),0);
  old_cover:=GREATEST(COALESCE(OLD.promo_wallet,0),0)+GREATEST(COALESCE(OLD.chip_balance,0),0);
 END IF;
 IF cover>=old_cover THEN RETURN NEW; END IF;
 SELECT COALESCE(sum(reserved_chips),0) INTO held FROM public.diamond_game_pools WHERE host_id=host;
 IF cover<held THEN RAISE EXCEPTION 'These Chips Are Reserved For Open Game Rounds'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_diamond_game_reserved_cover_guard() OWNER TO postgres;

--
-- TOC entry 9636 (class 1255 OID 27191611)
-- Name: fn_diamond_game_room(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_room(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_host uuid; v_kind text;
  v_rate integer := public.fn_ca_bridge_rate();
  v_cover numeric; v_promo numeric; v_bank numeric;
  v_owner uuid; v_owner_dia numeric;
  cfg public.diamond_game_configs%ROWTYPE;
  pool public.diamond_game_pools%ROWTYPE;
  wcfg public.wheel_configs%ROWTYPE;
  v_games jsonb := '[]'::jsonb;
  v_g text; v_min_chips numeric; v_max_chips numeric;
  v_cap_max integer; v_cap_min integer; v_cap_free integer; v_state text;
  v_mult integer := 1; v_top_chip numeric := 0; v_top_dia numeric := 0;
  v_wheel jsonb;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In First');
  END IF;
  SELECT h.host_id, h.host_kind INTO v_host, v_kind FROM public.fn_wheel_host(p_club_id) h;
  IF v_host IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Club Could Not Be Found');
  END IF;
  IF NOT public.fn_wheel_can_operate(v_host, v_kind, v_user) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Only The Host''s Owners And Admins Read This');
  END IF;

  v_promo := public.fn_diamond_game_promo(v_host, v_kind);
  v_bank  := public.fn_diamond_game_bank(v_host, v_kind);
  v_cover := public.fn_diamond_game_cover(v_host, v_kind);
  v_owner := public.fn_diamond_game_owner(v_host, v_kind);
  SELECT COALESCE(p.diamonds, 0) INTO v_owner_dia FROM public.profiles p WHERE p.id = v_owner;

  FOREACH v_g IN ARRAY ARRAY['plinko', 'crash', 'crossing', 'mines'] LOOP
    SELECT * INTO cfg FROM public.diamond_game_configs WHERE host_id = v_host AND game = v_g;
    CONTINUE WHEN cfg.host_id IS NULL;
    SELECT * INTO pool FROM public.diamond_game_pools WHERE host_id = v_host AND game = v_g;
    v_max_chips := cfg.max_bet_diamonds::numeric / v_rate;
    v_min_chips := GREATEST(cfg.min_bet_diamonds, 1)::numeric / v_rate;
    -- The same function the door uses, so the console cannot say one thing
    -- while the game does another.
    v_cap_max := public.fn_diamond_game_cap_cents(cfg, pool, v_cover, v_max_chips, cfg.max_multiplier_cents);
    v_cap_min := public.fn_diamond_game_cap_cents(cfg, pool, v_cover, v_min_chips, cfg.max_multiplier_cents);
    -- TWO DIFFERENT CEILINGS, AND ONLY ONE OF THEM IS THE OPERATOR'S TO FIX.
    -- fn_diamond_game_cap_cents takes the LEAST of the configured ceiling, the
    -- intake headroom and the cover. Asking it again with a bank nothing could
    -- exhaust isolates the first two, so the console can say which is binding:
    --   the INTAKE headroom means the game has not taken enough in yet to risk
    --   a payout that size, which is the never-pay-more-than-taken-in law
    --   working exactly as intended and nothing to act on;
    --   the COVER means the promo wallet and the bank cannot carry the win,
    --   which is the operator's to fix and the only thing worth a warning.
    -- Reporting them as one number would tell an owner to move chips they do
    -- not need to move.
    v_cap_free := public.fn_diamond_game_cap_cents(cfg, pool, 1000000000000, v_max_chips, cfg.max_multiplier_cents);
    v_state := CASE
      WHEN NOT cfg.enabled OR NOT public.fn_diamond_spins_owner_agreed(v_host,v_kind) THEN 'closed'
      WHEN public.fn_diamond_game_quote_max(v_g,v_min_chips,v_cap_min)<=0 THEN 'stopped'
      WHEN v_cap_max < v_cap_free THEN 'thin'
      ELSE 'open' END;
    v_games := v_games || jsonb_build_object(
      'game', v_g,
      'enabled', cfg.enabled AND public.fn_diamond_spins_owner_agreed(v_host,v_kind),
      'state', v_state,
      'max_bet_diamonds', cfg.max_bet_diamonds,
      'max_win_chips', public.fn_diamond_game_quote_max(v_g,v_max_chips,v_cap_max),
      'intake_win_chips', public.fn_diamond_game_quote_max(v_g,v_max_chips,v_cap_free),
      'ceiling_win_chips', public.fn_diamond_game_quote_max(v_g,v_max_chips,cfg.max_multiplier_cents),
      'capped_by_cover', v_cap_max < v_cap_free,
      'capped_by_intake', v_cap_free < cfg.max_multiplier_cents,
      'reserved_chips', COALESCE(pool.reserved_chips, 0));
  END LOOP;

  SELECT * INTO wcfg FROM public.wheel_configs WHERE host_id = v_host;
  IF wcfg.host_id IS NOT NULL THEN
    SELECT COALESCE(wcfg.spin_price_diamonds / v.spin_price_diamonds, 1) INTO v_mult
      FROM public.wheel_segment_versions v WHERE v.version = wcfg.segment_version;
    v_mult := COALESCE(v_mult, 1);
    SELECT COALESCE(max(CASE WHEN g.kind = 'chips' THEN g.amount::numeric * v_mult ELSE 0 END), 0),
           COALESCE(max(CASE WHEN g.kind = 'diamonds' THEN g.amount::numeric * v_mult ELSE 0 END), 0)
      INTO v_top_chip, v_top_dia
      FROM public.wheel_segments g WHERE g.version = wcfg.segment_version;
    v_wheel := jsonb_build_object(
      'game', 'wheel',
      'enabled', wcfg.enabled,
      -- The wheel does not cap a multiplier; it locks the tiers it cannot pay.
      -- It can therefore go thin in a way no chip reading would show: on the
      -- OWNER'S diamonds, which is what its diamond prizes come out of.
      'state', CASE
        WHEN NOT wcfg.enabled THEN 'closed'
        WHEN v_cover < v_top_chip AND v_owner_dia < v_top_dia THEN 'stopped'
        WHEN v_cover < v_top_chip OR v_owner_dia < v_top_dia THEN 'thin'
        ELSE 'open' END,
      'top_chip_prize_chips', round(v_top_chip, 2),
      'top_diamond_prize_diamonds', v_top_dia,
      'chip_prize_covered', v_cover >= v_top_chip,
      'diamond_prize_covered', v_owner_dia >= v_top_dia,
      'spin_price_diamonds', wcfg.spin_price_diamonds);
    v_games := v_games || v_wheel;
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'host_id', v_host, 'host_kind', v_kind, 'diamonds_per_chip', v_rate,
    'cover_chips', round(v_cover, 2),
    'promo_chips', round(v_promo, 2),
    'bank_chips', round(v_bank, 2),
    'owner_diamonds', v_owner_dia,
    'games', v_games);
END $$;


ALTER FUNCTION public.fn_diamond_game_room(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 6612 (class 1255 OID 24019158)
-- Name: fn_diamond_game_set_config(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_set_config(p_club_id uuid, p_game text, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_host uuid; v_kind text;
  cfg public.diamond_game_configs%ROWTYPE;
  v_rate integer := public.fn_ca_bridge_rate();
  v_bad integer;
BEGIN
  IF v_user IS NULL AND COALESCE(auth.role(), '') <> 'service_role' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In First');
  END IF;
  IF p_game IS NULL OR p_game NOT IN ('plinko', 'crash', 'crossing', 'mines') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Game Does Not Exist');
  END IF;
  SELECT h.host_id, h.host_kind INTO v_host, v_kind FROM public.fn_wheel_host(p_club_id) h;
  IF v_host IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Club Could Not Be Found');
  END IF;
  IF NOT public.fn_wheel_can_operate(v_host, v_kind, v_user) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Only The Host Owner Or An Admin May Change This Game');
  END IF;

  SELECT * INTO cfg FROM public.diamond_game_configs WHERE host_id = v_host AND game = p_game FOR UPDATE;
  IF cfg.host_id IS NULL THEN
    INSERT INTO public.diamond_game_configs (host_id, game, host_kind, updated_by)
    VALUES (v_host, p_game, v_kind, v_user) RETURNING * INTO cfg;
    INSERT INTO public.diamond_game_pools (host_id, game) VALUES (v_host, p_game) ON CONFLICT (host_id, game) DO NOTHING;
  END IF;

  IF p_patch ? 'min_bet_diamonds' THEN cfg.min_bet_diamonds := (p_patch->>'min_bet_diamonds')::integer; END IF;
  IF p_patch ? 'max_bet_diamonds' THEN cfg.max_bet_diamonds := (p_patch->>'max_bet_diamonds')::integer; END IF;
  IF p_patch ? 'bet_options' THEN
    SELECT array_agg(x::integer ORDER BY x::integer) INTO cfg.bet_options FROM jsonb_array_elements_text(p_patch->'bet_options') x;
  END IF;
  IF p_patch ? 'exposure_allowance_chips' THEN cfg.exposure_allowance_chips := round((p_patch->>'exposure_allowance_chips')::numeric, 2); END IF;
  IF p_patch ? 'cap_fraction' THEN cfg.cap_fraction := round((p_patch->>'cap_fraction')::numeric, 3); END IF;
  IF p_patch ? 'max_multiplier_cents' THEN cfg.max_multiplier_cents := (p_patch->>'max_multiplier_cents')::integer; END IF;
  IF p_patch ? 'growth_k' THEN cfg.growth_k := round((p_patch->>'growth_k')::numeric, 4); END IF;
  IF p_patch ? 'purchased_only' THEN cfg.purchased_only := (p_patch->>'purchased_only')::boolean; END IF;
  IF p_patch ? 'allow_fixture_accounts' THEN cfg.allow_fixture_accounts := (p_patch->>'allow_fixture_accounts')::boolean; END IF;
  IF p_patch ? 'max_rounds_per_player_per_day' THEN cfg.max_rounds_per_player_per_day := (p_patch->>'max_rounds_per_player_per_day')::integer; END IF;
  IF p_patch ? 'min_seconds_between_rounds' THEN cfg.min_seconds_between_rounds := (p_patch->>'min_seconds_between_rounds')::integer; END IF;
  IF p_patch ? 'enabled' THEN cfg.enabled := (p_patch->>'enabled')::boolean; END IF;
  IF cfg.enabled AND NOT public.fn_diamond_spins_owner_agreed(v_host,v_kind) THEN RETURN jsonb_build_object('ok',false,'error','The Host Wallet Owner Must Accept Diamond Spins Before Play Opens'); END IF;

  IF cfg.min_bet_diamonds<>25 OR cfg.max_bet_diamonds<>5000 OR cfg.purchased_only THEN RETURN jsonb_build_object('ok',false,'error','Diamond Spins Use Earned Or Purchased Diamonds, With Entries From 25 To 2,500 And One Optional Double Down'); END IF;
  IF cfg.bet_options IS NULL OR array_length(cfg.bet_options, 1) IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'At Least One Bet Size Is Required');
  END IF;
  SELECT count(*) INTO v_bad FROM unnest(cfg.bet_options) b
   WHERE b < cfg.min_bet_diamonds OR b > cfg.max_bet_diamonds;
  IF v_bad > 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Every Bet Size Must Be Inside The Diamond Limits');
  END IF;
  IF cfg.enabled AND p_game = 'plinko' AND NOT EXISTS (
       SELECT 1 FROM public.plinko_tables t, public.fn_plinko_table_audit(t.version) a
        WHERE t.activated_at IS NOT NULL AND a.spec_rtp = 0.800000) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No Plinko Table Passes Its Payout Audit. The Game Cannot Be Enabled');
  END IF;

  UPDATE public.diamond_game_configs
     SET enabled = cfg.enabled, min_bet_diamonds = cfg.min_bet_diamonds, max_bet_diamonds = cfg.max_bet_diamonds,
         bet_options = cfg.bet_options, exposure_allowance_chips = cfg.exposure_allowance_chips,
         cap_fraction = cfg.cap_fraction, max_multiplier_cents = cfg.max_multiplier_cents, growth_k = cfg.growth_k,
         purchased_only = cfg.purchased_only, allow_fixture_accounts = cfg.allow_fixture_accounts,
         max_rounds_per_player_per_day = cfg.max_rounds_per_player_per_day,
         min_seconds_between_rounds = cfg.min_seconds_between_rounds,
         updated_at = now(), updated_by = v_user
   WHERE host_id = v_host AND game = p_game
   RETURNING * INTO cfg;
  RETURN jsonb_build_object('ok', true, 'config', to_jsonb(cfg));
END $$;


ALTER FUNCTION public.fn_diamond_game_set_config(p_club_id uuid, p_game text, p_patch jsonb) OWNER TO postgres;

--
-- TOC entry 4909 (class 1255 OID 24019128)
-- Name: fn_diamond_game_state(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_state(p_club_id uuid, p_game text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_host uuid; v_kind text;
  cfg public.diamond_game_configs%ROWTYPE;
  pool public.diamond_game_pools%ROWTYPE;
  v_rate integer := public.fn_ca_bridge_rate();
  v_bank numeric := 0;
  v_diamonds numeric := 0; v_purchased integer := 0; v_spendable integer := 0;
  v_today integer := 0; v_last timestamptz; v_wait integer := 0;
  v_member boolean := false; v_member_chips numeric;
  v_frozen boolean;
  v_bets jsonb; v_tables jsonb; v_open jsonb;
  r public.crash_rounds;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In To Play');
  END IF;
  IF p_game IS NULL OR p_game NOT IN ('plinko', 'crash', 'crossing', 'mines') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Game Does Not Exist');
  END IF;
  SELECT h.host_id, h.host_kind INTO v_host, v_kind FROM public.fn_wheel_host(p_club_id) h;
  IF v_host IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Club Could Not Be Found');
  END IF;
  SELECT * INTO cfg FROM public.diamond_game_configs WHERE host_id = v_host AND game = p_game;
  IF cfg.host_id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'available', false, 'reason', 'not_configured',
                              'game', p_game, 'host_id', v_host, 'host_kind', v_kind);
  END IF;

  -- Time settles what it has decided before anybody reads the headroom.
  IF p_game = 'crash' THEN
    PERFORM 1 FROM public.diamond_game_configs WHERE host_id = v_host AND game = 'crash' FOR UPDATE;
    PERFORM public.fn_crash_settle_decided(v_host);
    SELECT * INTO r FROM public.crash_rounds c WHERE c.host_id = v_host AND c.club_id=p_club_id AND c.user_id = v_user AND c.status = 'open'
     ORDER BY c.started_at DESC LIMIT 1;
    IF r.id IS NOT NULL THEN
      v_open := public.fn_crash_round_result(r);
    END IF;
  END IF;
  SELECT * INTO pool FROM public.diamond_game_pools WHERE host_id = v_host AND game = p_game;

  -- The bank a prize comes out of is the host's PROMO WALLET (Dan 2026-09-10).
  -- Cover: the promo wallet the payouts come out of first, and the host's own
  -- chip bank standing behind it (Dan 2026-09-10).
  v_bank := public.fn_diamond_game_cover(v_host, v_kind);

  -- Every bet option with the cap the pool can promise on it right now.
  SELECT jsonb_agg(jsonb_build_object(
           'bet_diamonds', b, 'bet_chips', round(b::numeric / v_rate, 2),
           'cap_cents', public.fn_diamond_game_cap_cents(cfg, pool, v_bank, b::numeric / v_rate, cfg.max_multiplier_cents),
           'playable', public.fn_diamond_game_cap_cents(cfg, pool, v_bank, b::numeric / v_rate, cfg.max_multiplier_cents) >= 101)
         ORDER BY b)
    INTO v_bets
    FROM unnest(cfg.bet_options) b
   WHERE b BETWEEN cfg.min_bet_diamonds AND cfg.max_bet_diamonds;

  IF p_game = 'plinko' THEN
    SELECT jsonb_agg(jsonb_build_object(
             'version', t.version, 'name', t.name, 'rows', t.board_rows,
             'multipliers_cents', to_jsonb(t.multipliers_cents),
             'max_multiplier_cents', t.max_multiplier_cents,
             'sd_chips', t.sd_chips)
           ORDER BY t.version)
      INTO v_tables
      FROM public.plinko_tables t WHERE t.activated_at IS NOT NULL;
  END IF;

  SELECT COALESCE(p.diamonds, 0) INTO v_diamonds FROM public.profiles p WHERE p.id = v_user;
  v_purchased := public.fn_wheel_purchased_available(v_user);
  v_spendable := CASE WHEN cfg.purchased_only THEN LEAST(v_diamonds, v_purchased)::integer ELSE v_diamonds::integer END;

  SELECT count(*)::integer,max(created_at) INTO v_today,v_last FROM public.diamond_game_round_book
   WHERE host_id=v_host AND user_id=v_user AND game=p_game
   AND (created_at AT TIME ZONE 'America/Chicago')::date=(now() AT TIME ZONE 'America/Chicago')::date;
  IF v_last IS NOT NULL THEN
    v_wait := GREATEST(0, cfg.min_seconds_between_rounds - floor(extract(epoch FROM (now() - v_last)))::integer);
  END IF;
  SELECT true, COALESCE(cm.chip_balance, 0) INTO v_member, v_member_chips
    FROM public.club_members cm
   WHERE cm.club_id = p_club_id AND cm.user_id = v_user
     AND COALESCE(cm.status, 'active') IN ('active', 'approved') LIMIT 1;
  v_frozen := public.fn_platform_frozen()
           OR EXISTS (SELECT 1 FROM public.ca_payout_freeze f WHERE f.scope = p_game AND f.cleared_at IS NULL);

  RETURN jsonb_build_object(
    'ok', true, 'available', cfg.enabled AND public.fn_diamond_spins_owner_agreed(v_host,v_kind), 'game', p_game, 'host_id', v_host, 'host_kind', v_kind, 'club_id', p_club_id,
    'config', jsonb_build_object(
      'diamonds_per_chip', v_rate, 'min_bet_diamonds', cfg.min_bet_diamonds, 'max_bet_diamonds', cfg.max_bet_diamonds,
      'exposure_allowance_chips', cfg.exposure_allowance_chips, 'cap_fraction', cfg.cap_fraction,
      'max_multiplier_cents', cfg.max_multiplier_cents, 'growth_k', cfg.growth_k, 'payout_version', CASE WHEN p_game = 'crash' THEN 5 END,
      'purchased_only', cfg.purchased_only, 'max_rounds_per_player_per_day', cfg.max_rounds_per_player_per_day,
      'min_seconds_between_rounds', cfg.min_seconds_between_rounds),
    'bets', COALESCE(v_bets, '[]'::jsonb),
    'tables', COALESCE(v_tables, '[]'::jsonb),
    'open_round', v_open,
    'pool', jsonb_build_object(
      'rounds', COALESCE(pool.rounds, 0), 'intake_diamonds', COALESCE(pool.intake_diamonds, 0),'wheel_allocated_diamonds',COALESCE(pool.wheel_allocated_diamonds,0),
      'chips_paid', COALESCE(pool.chips_paid, 0),
      'reserved_chips', COALESCE(pool.reserved_chips, 0),
      'intake_chips', round(COALESCE(pool.intake_diamonds, 0)::numeric / v_rate, 2),
      'promo_wallet_chips', public.fn_diamond_game_promo(v_host, v_kind),
      'bank_chips', public.fn_diamond_game_bank(v_host, v_kind),
      'cover_chips', v_bank,
      'headroom_chips', round((COALESCE(pool.intake_diamonds, 0)+COALESCE(pool.wheel_allocated_diamonds,0))::numeric / v_rate, 2) + cfg.exposure_allowance_chips - COALESCE(pool.chips_paid, 0) - COALESCE(pool.reserved_chips, 0),
      'realized_rtp', CASE WHEN COALESCE(pool.intake_diamonds, 0) > 0
                           THEN round(COALESCE(pool.chips_paid, 0) / (pool.intake_diamonds::numeric / v_rate), 4) END),
    'player', jsonb_build_object(
      'diamonds', v_diamonds, 'purchased_available', v_purchased, 'spendable', v_spendable,
      'rounds_today', v_today, 'seconds_until_next', v_wait,
      -- The same one figure the wheel shows, from the same helper.
      'diamonds_today', public.fn_diamond_games_spent_today(v_host, v_user),
      'is_member', COALESCE(v_member, false), 'member_chips', v_member_chips),
    'frozen', v_frozen);
END $$;


ALTER FUNCTION public.fn_diamond_game_state(p_club_id uuid, p_game text) OWNER TO postgres;

--
-- TOC entry 6589 (class 1255 OID 26990003)
-- Name: fn_diamond_game_take_bet(uuid, integer, boolean, text, text, text, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_game_take_bet(p_user uuid, p_bet integer, p_purchased_only boolean, p_type text, p_description text, p_reference text, p_meta jsonb, p_owner uuid, p_owner_note text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_deduct jsonb; v_credit jsonb; v_remaining integer; v_take integer; v_lot record;
BEGIN
  p_bet:=public.fn_wheel_bonus_player_debit(p_bet);
  IF p_bet=0 THEN RETURN jsonb_build_object('success',true,'funded_by_wheel',true); END IF;
  -- THE BET GOES TO THE HOST'S OWNER (Dan 2026-09-10: "all diamonds 'taken in' get
  -- credited to the union owners wallet, or the club owners wallet"). Two legs, one
  -- transaction, both transfers: the player's diamonds leave as a transfer to the owner
  -- (source diamond_game, the recipient in the metadata), and the owner's wallet takes
  -- them as a transfer. Nothing is retired and nothing is minted.
  IF p_owner IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'This Host Has No Owner Wallet To Pay');
  END IF;
  PERFORM 1 FROM public.profiles WHERE id IN(p_owner,p_user) ORDER BY id FOR UPDATE;
  v_deduct := public.deduct_diamonds(p_user, p_bet, p_description, p_type, 'diamond_game',
                p_meta || jsonb_build_object('recipient_id', p_owner, 'bet_type', p_type), p_reference, 0);
  IF COALESCE((v_deduct->>'success')::boolean, false) = false THEN
    RETURN v_deduct;
  END IF;
  IF COALESCE((v_deduct->>'idempotent')::boolean, false) THEN
    RETURN v_deduct;
  END IF;
  IF p_purchased_only THEN
    v_remaining := p_bet;
    FOR v_lot IN SELECT * FROM public.diamond_purchase_lots l
                  WHERE l.user_id = p_user AND l.frozen_at IS NULL
                    AND (l.issued - l.consumed - l.refunded) > 0
                  ORDER BY l.created_at, l.id FOR UPDATE LOOP
      EXIT WHEN v_remaining <= 0;
      v_take := LEAST(v_remaining, v_lot.issued - v_lot.consumed - v_lot.refunded);
      UPDATE public.diamond_purchase_lots SET consumed = consumed + v_take WHERE id = v_lot.id;
      v_remaining := v_remaining - v_take;
    END LOOP;
    IF v_remaining > 0 THEN
      RAISE EXCEPTION 'diamond games: purchased lots could not cover the bet (% short) after the availability check passed', v_remaining;
    END IF;
  END IF;
  v_credit := public.fn_diamond_spin_book(p_owner,(p_meta->>'club_id')::uuid,(p_meta->>'host_id')::uuid,
    (SELECT host_kind FROM public.fn_wheel_host((p_meta->>'club_id')::uuid)),p_user,'bonus',p_bet,p_reference||':intake',p_owner_note);
  IF COALESCE((v_credit->>'success')::boolean, false) = false THEN
    RAISE EXCEPTION 'diamond games: the bet could not be credited to the host owner (%): %', p_reference, v_credit->>'error';
  END IF;
  RETURN v_deduct || jsonb_build_object('owner_id', p_owner, 'owner_balance', v_credit->'new_balance');
END $$;


ALTER FUNCTION public.fn_diamond_game_take_bet(p_user uuid, p_bet integer, p_purchased_only boolean, p_type text, p_description text, p_reference text, p_meta jsonb, p_owner uuid, p_owner_note text) OWNER TO postgres;

--
-- TOC entry 3319 (class 1255 OID 26990020)
-- Name: fn_diamond_games_entry(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_games_entry(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_host uuid; v_kind text;
  v_rate integer := public.fn_ca_bridge_rate();
  v_wheel boolean := false; v_plinko boolean := false; v_crash boolean := false; v_crossing boolean := false; v_mines boolean := false; v_available boolean; v_bust boolean := false;
  v_price integer; v_min integer;
  v_diamonds numeric := 0; v_member boolean := false; v_member_chips numeric;
  v_free boolean := false; v_frozen boolean;
  v_day date := (now() AT TIME ZONE 'America/Chicago')::date;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In To Play');
  END IF;
  SELECT h.host_id, h.host_kind INTO v_host, v_kind FROM public.fn_wheel_host(p_club_id) h;
  IF v_host IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Club Could Not Be Found');
  END IF;

  IF v_rate IS NULL OR v_rate <= 0 THEN RETURN jsonb_build_object('ok',false,'error','The Bridge Rate Is Not Set'); END IF;
  SELECT COALESCE(w.enabled, false), w.spin_price_diamonds INTO v_wheel, v_price
    FROM public.wheel_configs w WHERE w.host_id = v_host;
  SELECT COALESCE(bool_or(c.enabled AND public.fn_diamond_spins_owner_agreed(v_host,v_kind) AND NOT EXISTS (SELECT 1 FROM public.ca_payout_freeze f WHERE f.scope=c.game AND f.cleared_at IS NULL) AND c.game = 'plinko'), false),
         COALESCE(bool_or(c.enabled AND public.fn_diamond_spins_owner_agreed(v_host,v_kind) AND NOT EXISTS (SELECT 1 FROM public.ca_payout_freeze f WHERE f.scope=c.game AND f.cleared_at IS NULL) AND c.game = 'crash'), false),
         COALESCE(bool_or(c.enabled AND public.fn_diamond_spins_owner_agreed(v_host,v_kind) AND NOT EXISTS (SELECT 1 FROM public.ca_payout_freeze f WHERE f.scope=c.game AND f.cleared_at IS NULL) AND c.game = 'crossing'), false),
         COALESCE(bool_or(c.enabled AND public.fn_diamond_spins_owner_agreed(v_host,v_kind) AND NOT EXISTS (SELECT 1 FROM public.ca_payout_freeze f WHERE f.scope=c.game AND f.cleared_at IS NULL) AND c.game = 'mines'), false),
         MIN(c.min_bet_diamonds) FILTER (WHERE c.enabled AND public.fn_diamond_spins_owner_agreed(v_host,v_kind))
    INTO v_plinko, v_crash, v_crossing, v_mines, v_min
    FROM public.diamond_game_configs c WHERE c.host_id = v_host AND c.game IN ('plinko', 'crash', 'crossing', 'mines');

  SELECT COALESCE(p.diamonds, 0) INTO v_diamonds FROM public.profiles p WHERE p.id = v_user;
  SELECT true, cm.chip_balance INTO v_member, v_member_chips
    FROM public.club_members cm
   WHERE cm.club_id = p_club_id AND cm.user_id = v_user
     AND COALESCE(cm.status, 'active') IN ('active', 'approved') LIMIT 1;

  -- THE WELCOME SPIN IS ONCE, EVER (Dan 2026-09-10), so the door asks whether
  -- this member has ever taken one here, not whether they took one today, and
  -- whether the host has budget left to give another away.
  IF v_wheel THEN
    -- THE SAME QUESTION THE DOOR ASKS (2026-09-11). This used to say the spin
    -- was ready whenever the budget exceeded what had been spent, which is not
    -- the rule: a welcome spin is the whole wheel or it is not offered, so the
    -- window has to cover the TOP PRIZE, not merely be non-empty. A player was
    -- being shown "Welcome Spin Ready" on four surfaces and then refused at the
    -- door. One helper answers it for all three callers now.
    SELECT COALESCE(w.welcome_spin_enabled, false)
       AND (SELECT r.o_open FROM public.fn_wheel_welcome_room(v_host) r)
       AND NOT EXISTS (SELECT 1 FROM public.wheel_spins s
                        WHERE s.host_id = v_host AND s.user_id = v_user AND s.is_welcome)
      INTO v_free FROM public.wheel_configs w WHERE w.host_id = v_host;
  END IF;
  v_frozen := public.fn_platform_frozen();

  v_available := (COALESCE(v_wheel,false) OR COALESCE(v_plinko,false) OR COALESCE(v_crash,false) OR COALESCE(v_crossing,false) OR COALESCE(v_mines,false)) AND COALESCE(v_member,false) AND NOT v_frozen;
  -- A zero stack during an active hand is not a bust. The lobby may offer
  -- this prompt only after the player has left all occupied seats.
  v_bust := v_available AND v_member_chips=0 AND v_diamonds>=25
    AND NOT EXISTS (SELECT 1 FROM public.table_seats s WHERE s.user_id=v_user AND s.left_at IS NULL);
  RETURN jsonb_build_object(
    'bust_prompt', COALESCE(v_bust,false),
    'ok', true,
    'host_id', v_host, 'host_kind', v_kind, 'club_id', p_club_id,
    'diamonds_per_chip', v_rate,
    'games', jsonb_build_object('wheel', COALESCE(v_wheel, false),
                                'plinko', COALESCE(v_plinko, false),
                                'crash', COALESCE(v_crash, false), 'crossing', COALESCE(v_crossing, false), 'mines', COALESCE(v_mines, false)),
    'open', COALESCE(v_wheel, false) OR COALESCE(v_plinko, false) OR COALESCE(v_crash, false) OR COALESCE(v_crossing, false) OR COALESCE(v_mines, false),
    'available', (COALESCE(v_wheel, false) OR COALESCE(v_plinko, false) OR COALESCE(v_crash, false) OR COALESCE(v_crossing, false) OR COALESCE(v_mines, false))
                 AND COALESCE(v_member, false) AND NOT v_frozen,
    'spin_price_diamonds', v_price,
    'min_bet_diamonds', v_min,
    'entry_diamonds', LEAST(COALESCE(v_price, 2147483647), COALESCE(v_min, 2147483647)),
    'diamonds', v_diamonds,
    'chips_from_diamonds', round(v_diamonds / v_rate, 2),
    'is_member', COALESCE(v_member, false),
    'member_chips', v_member_chips,
    'free_spin_ready', COALESCE(v_free, false),
    'welcome_spin_ready', COALESCE(v_free, false),
    'frozen', v_frozen);
END $$;


ALTER FUNCTION public.fn_diamond_games_entry(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 7441 (class 1255 OID 27202568)
-- Name: fn_diamond_games_spent_today(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_games_spent_today(p_host uuid, p_user uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE((
    SELECT sum(s.spin_price_diamonds)::numeric
      FROM public.wheel_spins s
     WHERE s.host_id = p_host AND s.user_id = p_user
       AND NOT COALESCE(s.is_welcome, false) AND s.bonus_ticket_id IS NULL
       AND (s.created_at AT TIME ZONE 'America/Chicago')::date
           = (now() AT TIME ZONE 'America/Chicago')::date), 0)
  + COALESCE((SELECT sum(r.bet_diamonds-COALESCE(a.base_diamonds,0))::numeric FROM public.diamond_game_round_book r LEFT JOIN public.wheel_bonus_awards a ON a.status='redeemed' AND COALESCE(a.result->>'id',a.result->>'round_id')=r.id::text
    WHERE r.host_id=p_host AND r.user_id=p_user
    AND (r.created_at AT TIME ZONE 'America/Chicago')::date=(now() AT TIME ZONE 'America/Chicago')::date),0);
$$;


ALTER FUNCTION public.fn_diamond_games_spent_today(p_host uuid, p_user uuid) OWNER TO postgres;

--
-- TOC entry 8272 (class 1255 OID 31352605)
-- Name: fn_diamond_kind_bucket(text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_kind_bucket(p_type text, p_transaction_type text, p_source text, p_amount bigint) RETURNS TABLE(kind text, bucket text, label text)
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    WITH resolved AS (
        SELECT LOWER(COALESCE(
            NULLIF(BTRIM(p_transaction_type), ''),
            CASE WHEN LOWER(COALESCE(p_type, '')) IN ('spend', 'earn', 'credit', 'debit')
                 THEN NULLIF(BTRIM(p_source), '') END,
            NULLIF(BTRIM(p_type), ''),
            ''
        )) AS k
    ),
    bucketed AS (
        SELECT k, CASE
            -- ── SPENT (amount < 0): exact kinds first ──────────────────────
            WHEN p_amount < 0 AND k IN ('arena_deposit', 'tournament_fee')                 THEN 'arena'
            WHEN p_amount < 0 AND k = 'cash_rake'                                          THEN 'arena_rake'
            WHEN p_amount < 0 AND k IN ('diamond_gift_sent', 'live_gift_sent')             THEN 'gifts_sent'
            WHEN p_amount < 0 AND k = 'transfer'                                           THEN 'transfers'
            WHEN p_amount < 0 AND k IN ('chip_purchase', 'chip_mint')                      THEN 'club_chips'
            WHEN p_amount < 0 AND k IN ('plinko_drop', 'crash_bet', 'wheel_spin', 'pvp_stake',
                                        'game_cost', 'arcade_entry', 'memory_game', 'trivia_entry',
                                        'trivia_arcade', 'trivia_lifeline', 'training_entry',
                                        'tournament_entry', 'daily_challenge_reroll',
                                        'diamond_game', 'daily_bonus_spin')                THEN 'games'
            WHEN p_amount < 0 AND k IN ('feature_purchase', 'feature_unlock', 'video_unlock',
                                        'streak_freeze', 'throwable_purchase', 'cosmetic_purchase',
                                        'card_slide_purchase', 'deduction')                THEN 'store'
            WHEN p_amount < 0 AND k IN ('refund', 'stripe_refund', 'chargeback', 'debt_settlement') THEN 'purchase_refunds'
            WHEN p_amount < 0 AND k IN ('adjustment', 'reconciliation', 'burn', 'admin', 'admin_grant',
                                        'seeded', 'bridge', 'house')                       THEN 'adjustments'
            -- ── SPENT: patterns second ─────────────────────────────────────
            WHEN p_amount < 0 AND k LIKE '%vip%'                                           THEN 'vip'
            WHEN p_amount < 0 AND k LIKE '%arena%'                                         THEN 'arena'
            WHEN p_amount < 0 AND k LIKE '%gift%'                                          THEN 'gifts_sent'
            WHEN p_amount < 0 AND k LIKE '%chip%'                                          THEN 'club_chips'
            WHEN p_amount < 0 AND (k LIKE '%refund%' OR k LIKE '%chargeback%' OR k LIKE '%debt%') THEN 'purchase_refunds'
            WHEN p_amount < 0 AND (k LIKE '%adjust%' OR k LIKE '%reconcil%' OR k LIKE '%burn%'
                                   OR k LIKE '%admin%')                                    THEN 'adjustments'
            WHEN p_amount < 0 AND (k LIKE '%purchase%' OR k LIKE '%unlock%' OR k LIKE '%feature%'
                                   OR k LIKE '%throwable%' OR k LIKE '%cosmetic%' OR k LIKE '%avatar%'
                                   OR k LIKE '%theme%' OR k LIKE '%video%' OR k LIKE '%freeze%'
                                   OR k LIKE '%slide%')                                    THEN 'store'
            WHEN p_amount < 0 AND (k LIKE '%bet%' OR k LIKE '%spin%' OR k LIKE '%stake%'
                                   OR k LIKE '%game%' OR k LIKE '%arcade%' OR k LIKE '%trivia%'
                                   OR k LIKE '%training%' OR k LIKE '%entry%' OR k LIKE '%reroll%') THEN 'games'
            WHEN p_amount < 0                                                              THEN 'other_spent'
            -- ── EARNED (amount > 0): exact kinds first ─────────────────────
            WHEN k IN ('arena_withdraw', 'arena')                                          THEN 'arena_cash_outs'
            WHEN k IN ('diamond_gift_received', 'live_gift_received')                      THEN 'gifts_received'
            WHEN k = 'transfer'                                                            THEN 'transfers'
            WHEN k IN ('union_grant', 'club_grant')                                        THEN 'grants'
            WHEN k IN ('diamond_purchase', 'purchase', 'purchased', 'stripe_purchase',
                       'store_purchase', 'purchase_clearing')                              THEN 'purchases'
            WHEN k IN ('daily_login', 'daily_bonus', 'daily_bonus_boost', 'daily_challenge_claim',
                       'daily_mission_milestone', 'daily_trivia_challenge', 'daily_trivia',
                       'streak_reward', 'streak_diamonds', 'challenge', 'achievement',
                       'hand_of_the_day', 'gto_chart_study', 'training_reward',
                       'training_level_complete', 'first_training_session', 'trivia_run',
                       'trivia_reward', 'trivia_daily_bonus',
                       'game_reward', 'reward_diamonds', 'bonus_diamonds', 'prize_diamonds') THEN 'rewards'
            WHEN k IN ('signup_bonus', 'bonus', 'promotional', 'promo', 'promo_code',
                       'promo_purchased', 'easter_egg', 'birthday', 'first_purchase',
                       'referral', 'referral_bonus', 'referral_qualified', 'referral_referee',
                       'referral_vip_conversion', 'welcome_spin',
                       -- A Mint grant is never a purchase (20261007112751): every
                       -- 'mint' journal row is a signup grant, a Lifetime VIP
                       -- monthly benefit or a horse bankroll. A purchase writes
                       -- 'purchase'.
                       'mint')                                                             THEN 'bonuses'
            WHEN k IN ('tournament_prize', 'pvp_win', 'pvp_prize', 'pvp_match_win', 'crash_win',
                       'plinko_win', 'trivia_pvp_match', 'wheel_prize', 'trivia_prize_wheel',
                       'diamond_game_prize')                                              THEN 'winnings'
            WHEN k IN ('vip_reward', 'vip_stipend', 'vip_daily', 'vip_monthly', 'vip_bonus') THEN 'vip_bonuses'
            WHEN k IN ('social_post', 'follow', 'reaction', 'comment', 'strategy_comment', 'share',
                       'share_content', 'profile_complete', 'profile_pic', 'video_watch',
                       'video_favorite', 'hendonmob_link', 'venue_review', 'email_verified',
                       'phone_verified')                                                   THEN 'social'
            WHEN k IN ('refund', 'pvp_refund', 'pvp_tie_refund', 'diamond_gift_refund', 'diamond_refund',
                       'tournament_cancel_refund', 'tournament_entry_refund')              THEN 'refunds'
            WHEN k IN ('adjustment', 'reconciliation', 'admin', 'admin_grant', 'seeded', 'bridge',
                       'house',
                       -- The settlement of the 46 cash_rake rows that moved no
                       -- wallet (20261007112808).
                       'cash_rake_correction')                                             THEN 'adjustments'
            -- ── EARNED: patterns second ────────────────────────────────────
            WHEN k LIKE '%refund%'                                                         THEN 'refunds'
            WHEN k LIKE '%adjust%' OR k LIKE '%reconcil%' OR k LIKE '%admin%'              THEN 'adjustments'
            WHEN k LIKE '%arena%'                                                          THEN 'arena_cash_outs'
            WHEN k LIKE '%gift%'                                                           THEN 'gifts_received'
            WHEN k LIKE '%grant%'                                                          THEN 'grants'
            WHEN k LIKE '%vip%'                                                            THEN 'vip_bonuses'
            WHEN k LIKE '%purchase%'                                                       THEN 'purchases'
            WHEN k LIKE '%prize%' OR k LIKE '%win%'                                        THEN 'winnings'
            WHEN k LIKE '%promo%' OR k LIKE '%referral%' OR k LIKE '%bonus%'               THEN 'bonuses'
            WHEN k LIKE '%daily%' OR k LIKE '%reward%' OR k LIKE '%challenge%'
                 OR k LIKE '%mission%' OR k LIKE '%streak%' OR k LIKE '%training%'
                 OR k LIKE '%trivia%'                                                      THEN 'rewards'
            WHEN k LIKE '%social%' OR k LIKE '%profile%' OR k LIKE '%video%'
                 OR k LIKE '%verified%' OR k LIKE '%share%' OR k LIKE '%comment%'          THEN 'social'
            ELSE 'other_earned'
        END AS bucket
        FROM resolved
    )
    SELECT k AS kind, bucket, CASE bucket
            WHEN 'arena'            THEN 'Diamond Arena Seats'
            WHEN 'arena_rake'       THEN 'Diamond Arena Rake'
            WHEN 'gifts_sent'       THEN 'Gifts To Friends'
            WHEN 'transfers'        THEN 'Transfers'
            WHEN 'vip'              THEN 'VIP Membership'
            WHEN 'club_chips'       THEN 'Club Chip Purchases'
            WHEN 'games'            THEN 'Games And Arcade'
            WHEN 'store'            THEN 'Store Items And Perks'
            WHEN 'purchase_refunds' THEN 'Refunded Purchases'
            WHEN 'adjustments'      THEN 'Adjustments'
            WHEN 'other_spent'      THEN 'Other'
            WHEN 'arena_cash_outs'  THEN 'Diamond Arena Cash-Outs'
            WHEN 'gifts_received'   THEN 'Gifts From Friends'
            WHEN 'grants'           THEN 'Union And Club Grants'
            WHEN 'purchases'        THEN 'Diamonds You Bought'
            WHEN 'rewards'          THEN 'Daily Rewards And Challenges'
            WHEN 'bonuses'          THEN 'Bonuses And Promotions'
            WHEN 'winnings'         THEN 'Prizes And Winnings'
            WHEN 'vip_bonuses'      THEN 'VIP Bonuses'
            WHEN 'social'           THEN 'Social And Community'
            WHEN 'refunds'          THEN 'Refunds'
            ELSE 'Other'
        END AS label
    FROM bucketed;
$$;


ALTER FUNCTION public.fn_diamond_kind_bucket(p_type text, p_transaction_type text, p_source text, p_amount bigint) OWNER TO postgres;

--
-- TOC entry 47064 (class 0 OID 0)
-- Dependencies: 8272
-- Name: FUNCTION fn_diamond_kind_bucket(p_type text, p_transaction_type text, p_source text, p_amount bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_diamond_kind_bucket(p_type text, p_transaction_type text, p_source text, p_amount bigint) IS 'Resolves a diamond_transactions row (type, transaction_type, source, amount) to its kind, a spend/earn bucket and a player-facing label. Every kind a writer can produce is named exactly (2026-09-14 inventory of 24 writers, the reward catalog and the Mint register; 2026-09-20 the Diamond Games: diamond_game, daily_bonus_spin, the transfer kind their payouts and host intakes carry, and the bare deduction kind the Diamond Spins perks - throwables, time bank, rabbit hunt - are charged under; 2026-10-07 mint is a bonus, never a purchase); patterns second, Other last, so no row vanishes. ONE place, so both wallets bucket identically. DIAMONDS ONLY: club_chips is a chip purchase in a member club; the Diamond Arena has no chips.';


--
-- TOC entry 5735 (class 1255 OID 46779342)
-- Name: fn_diamond_kind_row_label(text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_kind_row_label(p_kind text, p_amount bigint) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    WITH k AS (SELECT LOWER(COALESCE(BTRIM(p_kind), '')) AS k)
    SELECT COALESCE(CASE
        WHEN k.k = 'arena_deposit'                                           THEN 'Diamond Arena Buy-In'
        WHEN k.k = 'arena_withdraw'                                          THEN 'Diamond Arena Cash-Out'
        WHEN k.k = 'tournament_fee'                                          THEN 'Diamond Arena Tournament Fee'
        WHEN k.k = 'daily_challenge_claim'                                   THEN 'Daily Challenge Reward'
        WHEN k.k = 'daily_mission_milestone'                                 THEN 'Daily Missions Milestone'
        WHEN k.k = 'daily_challenge_reroll'                                  THEN 'Daily Challenge Reroll'
        WHEN k.k = 'daily_login'                                             THEN 'Daily Login Reward'
        WHEN k.k = 'daily_bonus'                                             THEN 'Daily Bonus'
        WHEN k.k = 'daily_bonus_boost'                                       THEN 'Daily Bonus Boost'
        WHEN k.k = 'daily_bonus_spin'                                        THEN 'Bonus Spin Ticket'
        WHEN k.k IN ('streak_reward', 'streak_diamonds')                     THEN 'Streak Reward'
        WHEN k.k = 'streak_freeze'                                           THEN 'Streak Freeze'
        WHEN k.k = 'signup_bonus'                                            THEN 'Welcome Bonus'
        WHEN k.k = 'bonus'                                                   THEN 'Bonus'
        WHEN k.k IN ('promotional', 'promo', 'promo_code', 'promo_purchased') THEN 'Promotion'
        WHEN k.k = 'easter_egg'                                              THEN 'Easter Egg'
        WHEN k.k = 'birthday'                                                THEN 'Birthday Bonus'
        WHEN k.k = 'first_purchase'                                          THEN 'First Purchase Bonus'
        WHEN k.k IN ('referral', 'referral_bonus', 'referral_qualified',
                     'referral_referee', 'referral_vip_conversion')          THEN 'Referral Bonus'
        WHEN k.k = 'union_grant'                                             THEN 'Union Grant'
        WHEN k.k = 'club_grant'                                              THEN 'Club Grant'
        WHEN k.k = 'diamond_gift_sent'                                       THEN 'Diamonds Sent To A Friend'
        WHEN k.k = 'diamond_gift_received'                                   THEN 'Diamonds Received From A Friend'
        WHEN k.k = 'diamond_gift_refund'                                     THEN 'Gift Refund'
        WHEN k.k = 'live_gift_sent'                                          THEN 'Live Gift Sent'
        WHEN k.k = 'live_gift_received'                                      THEN 'Live Gift Received'
        WHEN k.k = 'transfer'                                                THEN 'Transfer'
        WHEN k.k IN ('purchase', 'purchased', 'diamond_purchase',
                     'stripe_purchase', 'store_purchase', 'purchase_clearing') THEN 'Diamond Purchase'
        WHEN k.k = 'mint'                                                    THEN 'Diamonds Issued'
        WHEN k.k IN ('refund', 'stripe_refund')                              THEN 'Purchase Refund'
        WHEN k.k = 'chargeback'                                              THEN 'Chargeback'
        WHEN k.k = 'debt_settlement'                                         THEN 'Debt Settlement'
        WHEN k.k = 'chip_purchase'                                           THEN 'Club Chip Purchase'
        WHEN k.k = 'chip_mint'                                               THEN 'Club Chip Mint'
        WHEN k.k = 'plinko_drop'                                             THEN 'Plinko Drop'
        WHEN k.k = 'plinko_win'                                              THEN 'Plinko Prize'
        WHEN k.k = 'crash_bet'                                               THEN 'Crash Bet'
        WHEN k.k = 'crash_win'                                               THEN 'Crash Prize'
        WHEN k.k = 'wheel_spin'                                              THEN 'Wheel Spin'
        WHEN k.k = 'wheel_prize'                                             THEN 'Wheel Prize'
        WHEN k.k = 'diamond_game'                                            THEN 'Diamond Game Bet'
        WHEN k.k = 'diamond_game_prize'                                      THEN 'Diamond Game Prize'
        WHEN k.k = 'pvp_stake'                                               THEN 'PvP Stake'
        WHEN k.k IN ('pvp_win', 'pvp_prize', 'pvp_match_win')                THEN 'PvP Winnings'
        WHEN k.k IN ('pvp_refund', 'pvp_tie_refund')                         THEN 'PvP Refund'
        WHEN k.k IN ('game_cost', 'arcade_entry', 'memory_game')             THEN 'Game Entry'
        WHEN k.k = 'game_reward'                                             THEN 'Game Reward'
        WHEN k.k = 'trivia_entry'                                            THEN 'Trivia Entry'
        WHEN k.k = 'trivia_arcade'                                           THEN 'Trivia Arcade'
        WHEN k.k = 'trivia_lifeline'                                         THEN 'Trivia Lifeline'
        WHEN k.k IN ('trivia_run', 'trivia_reward', 'daily_trivia',
                     'daily_trivia_challenge', 'trivia_daily_bonus')         THEN 'Trivia Reward'
        WHEN k.k = 'trivia_prize_wheel'                                      THEN 'Trivia Prize Wheel'
        WHEN k.k = 'trivia_pvp_match'                                        THEN 'Trivia PvP Match'
        WHEN k.k = 'tournament_entry'                                        THEN 'Tournament Entry'
        WHEN k.k = 'tournament_prize'                                        THEN 'Tournament Prize'
        WHEN k.k IN ('tournament_cancel_refund', 'tournament_entry_refund')  THEN 'Tournament Refund'
        WHEN k.k = 'training_entry'                                          THEN 'Training Entry'
        WHEN k.k IN ('training_reward', 'training_level_complete',
                     'first_training_session')                               THEN 'Training Reward'
        WHEN k.k = 'gto_chart_study'                                         THEN 'GTO Chart Study Reward'
        WHEN k.k = 'hand_of_the_day'                                         THEN 'Hand Of The Day Reward'
        WHEN k.k = 'achievement'                                             THEN 'Achievement Reward'
        WHEN k.k = 'challenge'                                               THEN 'Challenge Reward'
        WHEN k.k IN ('feature_purchase', 'feature_unlock')                   THEN 'Store Purchase'
        WHEN k.k = 'video_unlock'                                            THEN 'Video Unlock'
        WHEN k.k = 'deduction'                                               THEN 'Store Perk'
        WHEN k.k = 'throwable_purchase'                                      THEN 'Throwables'
        WHEN k.k = 'cosmetic_purchase'                                       THEN 'Cosmetic Purchase'
        WHEN k.k = 'card_slide_purchase'                                     THEN 'Card Slide'
        WHEN k.k IN ('vip_purchase', 'vip_monthly', 'vip_subscription',
                     'vip_membership')                                       THEN 'VIP Membership'
        WHEN k.k IN ('vip_stipend', 'vip_daily', 'vip_reward', 'vip_bonus')  THEN 'VIP Bonus'
        WHEN k.k = 'social_post'                                             THEN 'Social Post Reward'
        WHEN k.k = 'follow'                                                  THEN 'Follow Reward'
        WHEN k.k = 'reaction'                                                THEN 'Reaction Reward'
        WHEN k.k IN ('comment', 'strategy_comment')                          THEN 'Comment Reward'
        WHEN k.k IN ('share', 'share_content')                               THEN 'Share Reward'
        WHEN k.k = 'profile_complete'                                        THEN 'Profile Complete Reward'
        WHEN k.k = 'profile_pic'                                             THEN 'Profile Picture Reward'
        WHEN k.k = 'video_watch'                                             THEN 'Video Watch Reward'
        WHEN k.k = 'video_favorite'                                          THEN 'Video Favorite Reward'
        WHEN k.k = 'hendonmob_link'                                          THEN 'Hendon Mob Link Reward'
        WHEN k.k = 'venue_review'                                            THEN 'Venue Review Reward'
        WHEN k.k = 'email_verified'                                          THEN 'Email Verified Reward'
        WHEN k.k = 'phone_verified'                                          THEN 'Phone Verified Reward'
        WHEN k.k IN ('adjustment', 'reconciliation', 'admin', 'admin_grant') THEN 'Balance Adjustment'
        WHEN k.k = 'burn'                                                    THEN 'Diamonds Retired'
        WHEN k.k = 'seeded'                                                  THEN 'Seeded Diamonds'
        WHEN k.k LIKE 'test%'                                                THEN 'Balance Adjustment'
        ELSE NULL
    END, (SELECT b.label FROM public.fn_diamond_kind_bucket(k.k, k.k, NULL, p_amount) b))
    FROM k;
$$;


ALTER FUNCTION public.fn_diamond_kind_row_label(p_kind text, p_amount bigint) OWNER TO postgres;

