--

COMMENT ON FUNCTION public.fn_diamond_kind_row_label(p_kind text, p_amount bigint) IS 'The player-facing row label for a diamond ledger kind ("Daily Challenge Reward", "Diamond Arena Buy-In"); falls back to the bucket label from fn_diamond_kind_bucket. Pure; Title Case at the source. The test kinds take Balance Adjustment, the label the platform already uses for a correction: "Test Entry" was operator copy on a player''s screen (2026-09-30). DIAMONDS ONLY.';


--
-- TOC entry 8179 (class 1255 OID 46779355)
-- Name: fn_diamond_ledger_line(text, text, text, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_ledger_line(p_type text, p_transaction_type text, p_source text, p_amount bigint, p_description text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
    WITH resolved AS (
        SELECT LOWER(COALESCE(
            NULLIF(BTRIM(p_transaction_type), ''),
            CASE WHEN LOWER(COALESCE(p_type, '')) IN ('spend', 'earn', 'credit', 'debit')
                 THEN NULLIF(BTRIM(p_source), '') END,
            NULLIF(BTRIM(p_type), ''),
            ''
        )) AS k,
        -- THE MINT IS INTERNAL (Dan, 2026-09-05, tests/the-mint-is-internal.law.test.ts).
        -- fn_ca_mint writes every description as 'The Mint: ' || reason, and that
        -- prefix reached 853 player screens as "The Mint: signup grant". The
        -- prefix is dropped here, in the one place that speaks to the player.
        regexp_replace(BTRIM(COALESCE(p_description, '')), '^the mint:\s*', '', 'i') AS d,
        BTRIM(COALESCE(p_description, '')) ~* '^the mint:' AS minted
    ),
    cleaned AS (
        SELECT k, d, minted,
            regexp_replace(
              regexp_replace(
                regexp_replace(
                  regexp_replace(
                    regexp_replace(
                      regexp_replace(
                        regexp_replace(
                          regexp_replace(
                            regexp_replace(d,
                              E'\\s*[\u2012\u2013\u2014\u2015]\\s*', ', ', 'g'),          -- em and en dashes: a comma clause
                            E'\\s*\U0001F48E', ' diamonds', 'g'),                        -- the diamond glyph is a word
                          E'[\U0001F000-\U0001FAFF\u2728\u2B50\u2705\u274C]', '', 'g'),    -- every other emoji goes
                        '(\d)(diamonds?)\M', '\1 \2', 'gi'),                              -- 10diamonds -> 10 diamonds
                      '\s*\[[0-9a-f-]{36}\]\s*$', '', 'i'),                               -- trailing [uuid] reference
                    '\s*\((?:match|table|game|seat|round)\s+[0-9a-f-]{36}\)', '', 'gi'),  -- (match <uuid>)
                  '\s+for\s+[0-9a-f-]{36}\M', '', 'gi'),                                  -- for <uuid>
                '\s{2,}', ' ', 'g'),
              '^[\s,.:;-]+|[\s,.:;-]+$', '', 'g') AS line
        FROM resolved
    )
    SELECT CASE
        WHEN d = ''
          OR k IN ('daily_challenge_claim', 'daily_mission_milestone')
          -- The cash rake sweep writes an operator sentence ("attributed to this
          -- player's contributions (from the arena to the house)"); its row label
          -- is "Diamond Arena Rake".
          OR k = 'cash_rake'
          -- An owner instruction quoted into a reason: "(Dan 2026-10-06 10:25 CT)".
          OR LOWER(d) ~ '\(dan \d{4}-\d{2}-\d{2}'
          OR LOWER(d) ~ '(audit|reconcil|retro-credit|orphaned|clawback|replay|bypass|cowork|make-good|certification|pipeline|verification|journaled|\mtest\M|phase\s?\d|drift|rollback|pre-fix|constraint|batch)'
          OR LOWER(d) ~ '^(challenge reward|diamond rewards v\d|diamond award|diamond deduction|deduct|training):'
          OR d ~ '^[a-z0-9_]+$'
          OR line ~ '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}'
          OR line = ''
        THEN public.fn_diamond_kind_row_label(k, p_amount)
        -- A Mint reason is written lower case ("signup grant"); the player reads it
        -- in Title Case. Only the Mint's own reasons are recased, nothing else.
        ELSE CASE WHEN minted AND line = LOWER(line) THEN INITCAP(line) ELSE line END
    END
    FROM cleaned;
$_$;


ALTER FUNCTION public.fn_diamond_ledger_line(p_type text, p_transaction_type text, p_source text, p_amount bigint, p_description text) OWNER TO postgres;

--
-- TOC entry 47068 (class 0 OID 0)
-- Dependencies: 8179
-- Name: FUNCTION fn_diamond_ledger_line(p_type text, p_transaction_type text, p_source text, p_amount bigint, p_description text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_diamond_ledger_line(p_type text, p_transaction_type text, p_source text, p_amount bigint, p_description text) IS 'The line a player reads for a diamond ledger row: the description when it is player copy, cleaned (dashes, glued units, emoji, uuids, the internal Mint prefix), else the row label for the kind. Operator notes, machine tails, the cash rake sweep sentence and test rows never reach a player. Pure. Casing is the surface''s (Title Case). DIAMONDS ONLY.';


--
-- TOC entry 3998 (class 1255 OID 30221744)
-- Name: fn_diamond_lifetime_totals(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_lifetime_totals(p_user_id uuid DEFAULT auth.uid()) RETURNS TABLE(lifetime_earned bigint, lifetime_spent bigint, credits bigint, debits bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user uuid := COALESCE(p_user_id, auth.uid());
    v_role text := COALESCE(auth.jwt() ->> 'role', current_user);
BEGIN
    -- The siblings' two refusals, word for word, with this function's own name.
    -- Never a zero for a question this function cannot answer (10.86).
    IF v_user IS NULL THEN
        RAISE EXCEPTION 'authentication_required' USING ERRCODE = '42501';
    END IF;
    IF v_role <> 'service_role' AND v_user IS DISTINCT FROM auth.uid() THEN
        RAISE EXCEPTION 'lifetime_totals_is_own_only' USING ERRCODE = '42501';
    END IF;

    RETURN QUERY
    SELECT
        COALESCE(SUM(CASE WHEN t.amount > 0 THEN t.amount END), 0)::bigint,
        COALESCE(SUM(CASE WHEN t.amount < 0 THEN -t.amount END), 0)::bigint,
        COUNT(*) FILTER (WHERE t.amount > 0)::bigint,
        COUNT(*) FILTER (WHERE t.amount < 0)::bigint
    FROM public.diamond_transactions t
    WHERE t.user_id = v_user;
END;
$$;


ALTER FUNCTION public.fn_diamond_lifetime_totals(p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 47070 (class 0 OID 0)
