--
-- TOC entry 9189 (class 1255 OID 53096798)
-- Name: fn_diamond_spin_profit_burn(bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_spin_profit_burn(p_net bigint, p_bps integer) RETURNS bigint
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN p_net>0 AND p_bps>0 THEN (p_net*p_bps)/10000 ELSE 0 END
$$;


ALTER FUNCTION public.fn_diamond_spin_profit_burn(p_net bigint, p_bps integer) OWNER TO postgres;

--
-- TOC entry 47084 (class 0 OID 0)
-- Dependencies: 9189
-- Name: FUNCTION fn_diamond_spin_profit_burn(p_net bigint, p_bps integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_diamond_spin_profit_burn(p_net bigint, p_bps integer) IS 'Whole diamonds burned from a settled Diamond Spins day: floor(net * bps / 10000) when the net is positive, else 0. Integer division floors, so the burn is never more than the rate.';


