--
-- TOC entry 4259 (class 1255 OID 166991011)
-- Name: fn_diamond_spins_hold_allowance_floor(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_spins_hold_allowance_floor() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
 -- Dan 2026-10-15: a spin is always funded to 2,500. The allowance can be set
 -- higher, never below what that takes.
 NEW.exposure_allowance_chips:=GREATEST(COALESCE(NEW.exposure_allowance_chips,0),public.fn_diamond_spins_allowance_floor());
 RETURN NEW;
END $$;


