--
-- TOC entry 9531 (class 1255 OID 31385443)
-- Name: fn_diamond_spins_owner_terms(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_spins_owner_terms(p_club_id uuid, p_agree boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE h uuid; k text; v_owner uuid; receipt public.diamond_spins_owner_consents; addendum public.diamond_spins_owner_consents;
 base_version constant text:='diamond-spins-2026-09-14-v1';
 addendum_version constant text:='diamond-spins-2026-09-21-v2';
 terms text:='I Authorize Diamond Spins For This Host. Player Diamond Entries Go To My Owner Diamond Wallet. Chip Prizes Use The BBJ-Funded Promo Wallet First, With The Union Main Bank Covering Any Shortfall, Or The Club Main Bank For A Standalone Club. My Owner Diamond Wallet Pays For Awarded Throwables, Time Banks, Rabbit Hunts, Eligible One-Day VIP Cards, And VIP Diamond Multiplier Rewards At Their Recorded Diamond Cost. A Reward Must Be Funded Before It Is Awarded.';
 addendum_text text:='Daily Settlement And Profit Burn Addendum, September 21, 2026. Player Diamond Entries And Double Down Add Ons Are Held In Daily Custody For This Host, And Diamond Prizes, Throwables, Time Banks And Rabbit Hunts Are Deducted From That Custody As They Are Awarded. Each Chicago Business Day Settles In One Wallet Transaction After Midnight. On A Day With A Positive Net, The Platform Burns '||(public.fn_diamond_spin_profit_burn_bps()/100)||'% Of The Net Diamonds, Rounded Down To Whole Diamonds, And Credits The Remaining '||(100-public.fn_diamond_spin_profit_burn_bps()/100)||'% To My Owner Diamond Wallet. A Day With Zero Or Negative Net Burns Nothing, And A Negative Net Is Paid From My Owner Diamond Wallet. The Burn Applies To Every Day Settled From The Date This Addendum Is Published, Whether Or Not I Have Acknowledged It. Where This Addendum Differs From The Agreement Above, This Addendum Applies.';
BEGIN
 IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Sign In First'); END IF;
 SELECT host_id,host_kind INTO h,k FROM public.fn_wheel_host(p_club_id);
 IF h IS NULL THEN RETURN jsonb_build_object('ok',false,'error','That Club Could Not Be Found'); END IF;
 v_owner:=public.fn_diamond_game_owner(h,k);
 IF v_owner IS NULL THEN RETURN jsonb_build_object('ok',false,'error','The Host Wallet Owner Is Not Set'); END IF;
 IF auth.uid() IS DISTINCT FROM v_owner AND NOT public.fn_wheel_can_operate(h,k,auth.uid()) THEN
  RETURN jsonb_build_object('ok',false,'error','Only This Host Can Read Its Agreement'); END IF;
 IF p_agree IS TRUE THEN
  IF auth.uid() IS DISTINCT FROM v_owner THEN
   RETURN jsonb_build_object('ok',false,'error','The Wallet Owner Must Accept This Agreement'); END IF;
  -- Both texts are shown together; a new host owner accepts both, an owner who
  -- already holds the base receipt acknowledges the addendum. Receipts are
  -- permanent, so an existing one is never rewritten.
  INSERT INTO public.diamond_spins_owner_consents(host_id,host_kind,owner_id,terms_version,terms_text)
   VALUES(h,k,v_owner,base_version,terms) ON CONFLICT DO NOTHING;
  INSERT INTO public.diamond_spins_owner_consents(host_id,host_kind,owner_id,terms_version,terms_text)
   VALUES(h,k,v_owner,addendum_version,addendum_text) ON CONFLICT DO NOTHING;
 END IF;
 SELECT * INTO receipt FROM public.diamond_spins_owner_consents c WHERE c.host_id=h
  AND c.owner_id=v_owner AND c.terms_version=base_version;
 SELECT * INTO addendum FROM public.diamond_spins_owner_consents c WHERE c.host_id=h
  AND c.owner_id=v_owner AND c.terms_version=addendum_version;
 RETURN jsonb_build_object('ok',true,'host_id',h,'host_kind',k,'is_owner',auth.uid()=v_owner,
  'accepted',receipt.host_id IS NOT NULL,'accepted_at',receipt.accepted_at,'terms',terms,
  'terms_version',base_version,
  'addendum',jsonb_build_object('version',addendum_version,'text',addendum_text,
   'accepted',addendum.host_id IS NOT NULL,'accepted_at',addendum.accepted_at,
   'profit_burn_bps',public.fn_diamond_spin_profit_burn_bps()),
  'acknowledged',receipt.host_id IS NOT NULL AND addendum.host_id IS NOT NULL);
END $$;


ALTER FUNCTION public.fn_diamond_spins_owner_terms(p_club_id uuid, p_agree boolean) OWNER TO postgres;

--
-- TOC entry 6143 (class 1255 OID 49319769)
-- Name: fn_diamond_ticket_refusal(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_ticket_refusal(p_user uuid, p_game text, p_commit_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE c public.diamond_game_commits;
BEGIN
  SELECT * INTO c FROM public.diamond_game_commits WHERE id = p_commit_id FOR KEY SHARE;
  IF c.id IS NULL OR c.user_id IS DISTINCT FROM p_user OR c.game IS DISTINCT FROM p_game OR c.consumed_by IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'ticket', 'gone', 'error', 'That Ticket Is Not Yours Or Was Already Used. A New One Is Being Dealt');
  END IF;
  IF c.expires_at < now() THEN
    RETURN jsonb_build_object('ok', false, 'ticket', 'gone', 'error', 'That Ticket Expired. A New One Is Being Dealt');
  END IF;
  RETURN NULL;
END $$;


ALTER FUNCTION public.fn_diamond_ticket_refusal(p_user uuid, p_game text, p_commit_id uuid) OWNER TO postgres;

--
-- TOC entry 5146 (class 1255 OID 30811438)
-- Name: fn_diamond_wallet_summary(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_diamond_wallet_summary(p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user       uuid := COALESCE(p_user_id, auth.uid());
    v_role       text := COALESCE(auth.jwt() ->> 'role', current_user);
    v_on_hand    bigint;
    v_collateral bigint;
    v_in_arena   bigint;
    v_seats      integer;
    v_entries    integer;
    v_arena      record;
    v_open       integer := 0;
    v_lifetime   record;
    -- SCALARS, NOT A RECORD (2026-09-30). v_cheapest was a plpgsql `record`,
    -- and a record only acquires a tuple structure when something assigns it.
    -- Gating the scan on cash_games_enabled meant the SELECT INTO no longer ran
    -- on a closed arena, so `v_cheapest.id IS NULL` in the answer raised
    -- 55000 "record v_cheapest is not assigned yet" for every caller. Scalars
    -- are NULL from the start, which is the state the closed arena has to
    -- report anyway.
    v_seat_id    uuid;
    v_seat_name  text;
    v_seat_sb    numeric;
    v_seat_bb    numeric;
    v_seat_min   numeric;
BEGIN
    IF v_user IS NULL THEN
        RAISE EXCEPTION 'authentication_required' USING ERRCODE = '42501';
    END IF;
    IF v_role <> 'service_role' AND v_user IS DISTINCT FROM auth.uid() THEN
        RAISE EXCEPTION 'wallet_summary_is_own_only' USING ERRCODE = '42501';
    END IF;

    SELECT COALESCE(diamonds, 0)::bigint INTO v_on_hand
      FROM public.profiles WHERE id = v_user;
    v_on_hand := COALESCE(v_on_hand, 0);

    SELECT COALESCE(SUM(GREATEST(issued - consumed - refunded - arena_reserved, 0)), 0)::bigint
      INTO v_collateral
      FROM public.diamond_purchase_lots WHERE user_id = v_user;

    SELECT COALESCE(SUM(balance), 0)::bigint,
           COUNT(*) FILTER (WHERE purpose = 'cash_seat')::integer,
           COUNT(*) FILTER (WHERE purpose = 'tournament_entry')::integer
      INTO v_in_arena, v_seats, v_entries
      FROM public.poker_diamond_custody
     WHERE user_id = v_user AND state <> 'released';

    SELECT c.id, c.name, c.slug, a.cash_games_enabled, a.tournaments_enabled
      INTO v_arena
      FROM public.ca_arena_settings a
      JOIN public.clubs c ON c.id = a.club_id
     WHERE a.id = 1 AND c.asset = 'diamonds' AND c.is_platform IS TRUE;

    -- THE PLATE MAY NOT CONTRADICT THE SWITCH (2026-09-30). These three fields
    -- used to be computed whatever cash_games_enabled said, so a closed arena
    -- still reported 17 open tables and a named 80-Diamond seat. The switch is
    -- the authority: it is what fn_poker_diamond_buyin and fn_poker_diamond_top_up
    -- enforce, and while it is false every one of those tables refuses a buy-in.
    -- Closed therefore means open_cash_tables 0, min_cash_buy_in NULL and
    -- cheapest_table NULL, and the scan does not run at all.
    IF v_arena.id IS NOT NULL AND COALESCE(v_arena.cash_games_enabled, false) THEN
        -- The cheapest seat a player could actually take: the same predicate
        -- fn_poker_diamond_buyin admits on, so this number is never a seat
        -- that function would refuse.
        SELECT t.id, t.name, t.small_blind, t.big_blind, t.min_buy_in,
               COUNT(*) OVER ()::integer
          INTO v_seat_id, v_seat_name, v_seat_sb, v_seat_bb, v_seat_min, v_open
          FROM public.tables t
         WHERE t.club_id = v_arena.id
           AND t.game_variant = 'nlh'
           AND t.tournament_id IS NULL
           AND t.cluster_id IS NULL
           AND NOT COALESCE(t.is_template, false)
           AND t.status IN ('waiting', 'running', 'playing', 'active')
           AND COALESCE(t.rake_percent, 0) = 0 AND COALESCE(t.bbj_percent, 0) = 0
           AND NOT COALESCE(t.insurance_enabled, false) AND NOT COALESCE(t.bomb_pot_enabled, false)
           AND NOT COALESCE(t.run_it_twice_enabled, false) AND NOT COALESCE(t.run_it_twice, false)
           AND NOT COALESCE(t.allow_run_it_twice, false) AND NOT COALESCE(t.straddle_enabled, false)
           AND NOT COALESCE(t.seven_deuce_enabled, false) AND NOT COALESCE(t.nit_game, false)
           AND NOT COALESCE(t.all_in_or_fold, false) AND NOT COALESCE(t.pineapple_holdem, false)
           AND NOT COALESCE(t.cap_enabled, false) AND NOT COALESCE(t.auto_utg_straddle, false)
           AND NOT COALESCE(t.voluntary_straddle, false)
           AND t.min_buy_in IS NOT NULL AND t.min_buy_in > 0
         ORDER BY t.min_buy_in ASC, t.big_blind ASC, t.name ASC
         LIMIT 1;
        -- No eligible table leaves v_open NULL, and a NULL count would be a
        -- figure nobody can read. Zero is the answer, and it is true.
        v_open := COALESCE(v_open, 0);
    END IF;

    SELECT * INTO v_lifetime FROM public.fn_diamond_lifetime_totals(v_user);

    RETURN jsonb_build_object(
        'user_id',        v_user,
        'on_hand',        v_on_hand,
        'collateral',     v_collateral,
        'sendable',       GREATEST(v_on_hand - v_collateral, 0),
        'in_arena',       v_in_arena,
        'arena_seats',    v_seats,
        'arena_entries',  v_entries,
        'arena', CASE WHEN v_arena.id IS NULL THEN NULL ELSE jsonb_build_object(
            'club_id',             v_arena.id,
            'name',                v_arena.name,
            'slug',                v_arena.slug,
            'cash_games_enabled',  COALESCE(v_arena.cash_games_enabled, false),
            'tournaments_enabled', COALESCE(v_arena.tournaments_enabled, false),
            'open_cash_tables',    v_open,
            'min_cash_buy_in',     CASE WHEN v_seat_id IS NULL THEN NULL
                                        ELSE v_seat_min::bigint END,
            'cheapest_table',      CASE WHEN v_seat_id IS NULL THEN NULL ELSE jsonb_build_object(
                'id',          v_seat_id,
                'name',        v_seat_name,
                'small_blind', v_seat_sb,
                'big_blind',   v_seat_bb
            ) END
        ) END,
        'lifetime_earned', COALESCE(v_lifetime.lifetime_earned, 0),
        'lifetime_spent',  COALESCE(v_lifetime.lifetime_spent, 0),
        'read_at',         now()
    );
END;
$$;


ALTER FUNCTION public.fn_diamond_wallet_summary(p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 47100 (class 0 OID 0)
-- Dependencies: 5146
-- Name: FUNCTION fn_diamond_wallet_summary(p_user_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_diamond_wallet_summary(p_user_id uuid) IS 'The diamond wallet in one read: on_hand, collateral (the transfer RPC''s own refusal expression), sendable, in_arena (open poker_diamond_custody) with seat/entry counts, the Diamond Arena club with its open flags, its cheapest eligible cash seat (fn_poker_diamond_buyin''s own table predicate) and open table count, and lifetime totals. The seat figures obey cash_games_enabled: a closed arena reports 0 open tables and no cheapest seat, because the buy-in doors refuse every one of them, and they are held in scalars so the skipped scan leaves no unassigned record. DIAMONDS ONLY: the Diamond Arena has no chips, ever. Own-user only unless service_role.';


--
-- TOC entry 6359 (class 1255 OID 122722)
-- Name: fn_discover_clubs(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_discover_clubs(p_search text DEFAULT NULL::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, name text, description text, avatar_url text, member_count integer, online_count integer, game_types text[], is_public boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        c.id,
        c.name,
        c.description,
        c.avatar_url,
        COALESCE(c.member_count, 0)::INTEGER as member_count,
        COALESCE(c.online_count, 0)::INTEGER as online_count,
        c.game_types,
        COALESCE(c.is_public, true) as is_public,
        c.created_at
    FROM clubs c
    WHERE c.is_public = true
    AND (p_search IS NULL OR c.name ILIKE '%' || p_search || '%')
    ORDER BY c.member_count DESC NULLS LAST
    LIMIT p_limit OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.fn_discover_clubs(p_search text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- TOC entry 7693 (class 1255 OID 31043796)
-- Name: fn_discover_horse_observation_requests(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_discover_horse_observation_requests() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    SET lock_timeout TO '2s'
    AS $_$
DECLARE e public.horse_observation_discovery_epochs%ROWTYPE;
  s public.horse_observation_discovery_segments%ROWTYPE;
  at_ms bigint:=floor(extract(epoch FROM statement_timestamp())*1000)::bigint;
  end_ms bigint; start_ms bigint; previous_end bigint; key text; width bigint;
  n integer; bytes bigint; bad boolean; missing boolean; actor_ids uuid[]; novel uuid[];
  source_hash text; actor_hash text; snapshot text; source_read_ms bigint; ack jsonb; v_actor uuid; request text;
  processed integer:=0; inserted integer; total integer; occupied integer; evidence_size integer;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtextextended('horse-discovery-step-v1',0)) THEN
    RETURN jsonb_build_object('version',1,'status','unavailable','reason','discovery_busy');
  END IF;
  SELECT * INTO e FROM public.horse_observation_discovery_epochs WHERE state='pending' FOR UPDATE;
  IF NOT FOUND THEN
    end_ms:=(at_ms/18000000)*18000000-60000; start_ms:=end_ms-21600000;
    SELECT through_ms INTO previous_end FROM public.horse_observation_discovery_epochs ORDER BY through_ms DESC LIMIT 1;
    SELECT count(*) INTO n FROM (SELECT 1 FROM public.horse_observation_discovery_epochs WHERE state='gap' LIMIT 129) q;
    IF previous_end IS NOT NULL AND end_ms<=previous_end THEN
      RETURN jsonb_build_object('version',1,'status','idle','retainedGaps',n);
    END IF;
    IF n>=128 THEN RETURN jsonb_build_object('version',1,'status','unavailable','reason','gap_budget_exceeded'); END IF;
    SELECT count(*) INTO n FROM (SELECT 1 FROM public.horse_observation_discovery_epochs LIMIT 513) q;
    IF n>=512 THEN RETURN jsonb_build_object('version',1,'status','unavailable','reason','retention_backlog'); END IF;
    key:=encode(sha256(convert_to(concat_ws('|','horse-discovery-v1',start_ms::text,end_ms::text),'UTF8')),'hex');
    INSERT INTO public.horse_observation_discovery_epochs(epoch_key,from_ms,through_ms,cursor_ms,slice_through_ms,previous_through_ms,skipped_epochs)
      VALUES(key,start_ms,end_ms,start_ms,end_ms,previous_end,
        CASE WHEN previous_end IS NULL THEN 0 ELSE greatest(0,(end_ms-previous_end)/18000000-1)::integer END)
      RETURNING * INTO e;
  END IF;
  IF e.available_at>clock_timestamp() THEN RETURN public.fn_horse_discovery_state(e.epoch_key,'deferred','backoff'); END IF;
  IF e.from_ms<at_ms-86400000 THEN
    UPDATE public.horse_observation_discovery_epochs SET state='gap',reason='source_expired',finished_at=clock_timestamp() WHERE epoch_key=e.epoch_key;
    RETURN public.fn_horse_discovery_state(e.epoch_key,'gap','source_expired');
  END IF;
  SELECT * INTO s FROM public.horse_observation_discovery_segments WHERE epoch_key=e.epoch_key AND from_ms=e.cursor_ms;
  IF NOT FOUND THEN
    IF e.segments>=2048 THEN
      UPDATE public.horse_observation_discovery_epochs SET state='gap',reason='segment_budget_exceeded',finished_at=clock_timestamp() WHERE epoch_key=e.epoch_key;
      RETURN public.fn_horse_discovery_state(e.epoch_key,'gap','segment_budget_exceeded');
    END IF;
    -- Refuse discovery pressure before a source read when acquisition is full.
    SELECT count(*) INTO occupied FROM (SELECT 1 FROM public.horse_observation_capture_work WHERE state NOT IN ('admitted','captured') AND (state<>'gap' OR (reason='source_budget_exceeded' AND coalesce(slice_through_ms,through_ms)-coalesce(cursor_ms,from_ms)>1)) LIMIT 257) q;
    IF occupied>=256 THEN
      UPDATE public.horse_observation_discovery_epochs SET available_at=clock_timestamp()+interval '30 seconds',reason='capture_queue_full' WHERE epoch_key=e.epoch_key;
      RETURN public.fn_horse_discovery_state(e.epoch_key,'deferred','capture_queue_full');
    END IF;
    -- One bounded statement binds source rows, atomic receipts and actors.
    -- Private roster fields never leave this query or enter its digest.
    WITH candidates AS MATERIALIZED (
      SELECT h.id,h.created_at,h.table_id,h.hand_number,h.players FROM public.hand_history h
      WHERE h.created_at>to_timestamp(e.cursor_ms::double precision/1000)
        AND h.created_at<=to_timestamp(e.slice_through_ms::double precision/1000) LIMIT 513
    ), measured AS MATERIALIZED (
      SELECT c.*,a.payload_hash,a.hand_id IS NULL AS missing_receipt,
        octet_length(c.players::text) roster_bytes,
        CASE WHEN jsonb_typeof(c.players)='array' THEN jsonb_array_length(c.players) NOT BETWEEN 1 AND 10 ELSE true END invalid_roster
      FROM candidates c LEFT JOIN public.hand_atomic_commits a ON a.hand_id=c.id AND a.table_id=c.table_id AND a.hand_number=c.hand_number
    ), totals AS MATERIALIZED (SELECT count(*) n,coalesce(sum(roster_bytes),0) bytes FROM measured), roster AS MATERIALIZED (
      SELECT m.id,p.value->>'userId' actor,
        jsonb_typeof(p.value) IS DISTINCT FROM 'object' OR coalesce(p.value->>'userId','') !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' invalid_actor
      FROM measured m CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN NOT m.invalid_roster AND m.roster_bytes<=1048576 AND (SELECT t.n<=512 AND t.bytes<=8388608 FROM totals t) THEN m.players ELSE '[]'::jsonb END) p
    ), valid_actors AS MATERIALIZED (
      SELECT DISTINCT actor::uuid actor FROM roster WHERE NOT invalid_actor
    ), manifest AS (
      SELECT m.id,m.created_at,m.table_id,m.hand_number,m.payload_hash,
        (SELECT jsonb_agg(r.actor ORDER BY r.actor) FROM roster r WHERE r.id=m.id AND NOT r.invalid_actor) actors
      FROM measured m
    ) SELECT count(*)::integer,coalesce(sum(roster_bytes),0),
      coalesce(bool_or(invalid_roster OR roster_bytes>1048576 OR hand_number<1000000),false) OR EXISTS(SELECT 1 FROM roster WHERE invalid_actor)
        OR EXISTS(SELECT 1 FROM roster GROUP BY id,actor HAVING count(*)>1),
      coalesce(bool_or(missing_receipt OR payload_hash IS NULL OR payload_hash !~ '^[a-f0-9]{64}$'),false),
      (SELECT coalesce(array_agg(actor ORDER BY actor),ARRAY[]::uuid[]) FROM valid_actors),
      encode(sha256(convert_to(jsonb_build_array('horse-discovery-source-v1',e.cursor_ms,e.slice_through_ms,(SELECT coalesce(jsonb_agg(jsonb_build_array(id,
        to_char(created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),table_id,hand_number,payload_hash,actors)
        ORDER BY created_at,id),'[]'::jsonb) FROM manifest))::text,'UTF8')),'hex'),pg_current_snapshot()::text,
      floor(extract(epoch FROM clock_timestamp())*1000)::bigint
      INTO n,bytes,bad,missing,actor_ids,source_hash,snapshot,source_read_ms FROM measured;
    IF n>512 OR bytes>8388608 THEN
      width:=e.slice_through_ms-e.cursor_ms;
      IF width<=1 THEN
        UPDATE public.horse_observation_discovery_epochs SET state='gap',reason='indivisible_source_budget',finished_at=clock_timestamp() WHERE epoch_key=e.epoch_key;
        RETURN public.fn_horse_discovery_state(e.epoch_key,'gap','indivisible_source_budget');
      END IF;
      UPDATE public.horse_observation_discovery_epochs SET slice_through_ms=e.cursor_ms+width/2,reason='source_budget_exceeded',failures=0 WHERE epoch_key=e.epoch_key;
      RETURN public.fn_horse_discovery_state(e.epoch_key,'refined','source_budget_exceeded');
    END IF;
    IF octet_length(snapshot)>8192 THEN
      UPDATE public.horse_observation_discovery_epochs SET available_at=clock_timestamp()+interval '30 seconds',reason='snapshot_budget_exceeded' WHERE epoch_key=e.epoch_key;
      RETURN public.fn_horse_discovery_state(e.epoch_key,'deferred','snapshot_budget_exceeded');
    END IF;
    IF bad OR missing THEN
      UPDATE public.horse_observation_discovery_epochs SET failures=least(6,failures+1),available_at=clock_timestamp()+make_interval(secs=>least(60,2^least(6,failures+1))::integer),
        reason=CASE WHEN missing THEN 'atomic_receipt_missing' ELSE 'invalid_roster' END WHERE epoch_key=e.epoch_key;
      RETURN public.fn_horse_discovery_state(e.epoch_key,'deferred',CASE WHEN missing THEN 'atomic_receipt_missing' ELSE 'invalid_roster' END);
    END IF;
    SELECT coalesce(array_agg(a ORDER BY a),ARRAY[]::uuid[]) INTO novel FROM unnest(actor_ids) a
      WHERE NOT EXISTS(SELECT 1 FROM public.horse_observation_discovery_members m WHERE m.epoch_key=e.epoch_key AND m.actor_id=a);
    IF e.actors+cardinality(novel)>8192 THEN
      UPDATE public.horse_observation_discovery_epochs SET state='gap',reason='actor_budget_exceeded',finished_at=clock_timestamp() WHERE epoch_key=e.epoch_key;
      RETURN public.fn_horse_discovery_state(e.epoch_key,'gap','actor_budget_exceeded');
    END IF;
    actor_hash:=encode(sha256(convert_to(to_jsonb(actor_ids)::text,'UTF8')),'hex');
    -- Conservative logical evidence budget: snapshot bytes, frozen novel UUIDs
    -- and 512 bytes fixed allowance per segment. This excludes PostgreSQL
    -- indexes/MVCC overhead; epoch/member counts bound those independently.
    evidence_size:=octet_length(snapshot)+cardinality(novel)*16+512;
    IF e.evidence_bytes+evidence_size>2097152 THEN
      UPDATE public.horse_observation_discovery_epochs SET state='gap',reason='evidence_budget_exceeded',finished_at=clock_timestamp() WHERE epoch_key=e.epoch_key;
      RETURN public.fn_horse_discovery_state(e.epoch_key,'gap','evidence_budget_exceeded');
    END IF;
    INSERT INTO public.horse_observation_discovery_segments(epoch_key,from_ms,through_ms,snapshot_id,read_at_ms,source_digest,hands,source_actors,actor_digest,novel_actors)
      VALUES(e.epoch_key,e.cursor_ms,e.slice_through_ms,snapshot,source_read_ms,source_hash,n,cardinality(actor_ids),actor_hash,novel) RETURNING * INTO s;
    UPDATE public.horse_observation_discovery_epochs SET segments=segments+1,evidence_bytes=evidence_bytes+evidence_size,failures=0,reason=NULL WHERE epoch_key=e.epoch_key;
    -- Source snapshot and actor admission are separate bounded steps.
    RETURN public.fn_horse_discovery_state(e.epoch_key,'source_recorded');
  END IF;
  -- Claim the same capacity reservation used by the canonical admission RPC.
  IF NOT pg_try_advisory_xact_lock(hashtextextended('horse-source-capacity-v1',0)) THEN
    RETURN public.fn_horse_discovery_state(e.epoch_key,'deferred','capacity_busy');
  END IF;
  SELECT count(*) INTO occupied FROM (SELECT 1 FROM public.horse_observation_capture_work WHERE state NOT IN ('admitted','captured') AND (state<>'gap' OR (reason='source_budget_exceeded' AND coalesce(slice_through_ms,through_ms)-coalesce(cursor_ms,from_ms)>1)) LIMIT 257) q;
  total:=s.admitted_actors;
  WHILE total<cardinality(s.novel_actors) AND processed<32 LOOP
    v_actor:=s.novel_actors[total+1];
    request:=encode(sha256(convert_to(concat_ws('|','horse-source-request-v1',v_actor::text,e.from_ms::text,e.through_ms::text),'UTF8')),'hex');
    IF occupied>=256 AND NOT EXISTS(SELECT 1 FROM public.horse_observation_capture_work WHERE request_key=request) THEN EXIT; END IF;
    ack:=public.fn_admit_horse_observation_capture(v_actor,e.from_ms,e.through_ms);
    IF ack->>'status' IS DISTINCT FROM 'durable' OR ack->>'requestKey' IS DISTINCT FROM request THEN
      RAISE EXCEPTION 'HORSE_DISCOVERY_ADMISSION_UNCONFIRMED';
    END IF;
    INSERT INTO public.horse_observation_discovery_members(epoch_key,actor_id,request_key,source_from_ms)
      VALUES(e.epoch_key,v_actor,request,s.from_ms) ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS inserted=ROW_COUNT;
    IF inserted=0 AND NOT EXISTS(SELECT 1 FROM public.horse_observation_discovery_members WHERE epoch_key=e.epoch_key AND actor_id=v_actor AND request_key=request) THEN
      RAISE EXCEPTION 'HORSE_DISCOVERY_MEMBER_CONFLICT';
    END IF;
    UPDATE public.horse_observation_discovery_epochs SET actors=actors+inserted WHERE epoch_key=e.epoch_key;
    total:=total+1;processed:=processed+1;
    -- Conservative capacity accounting; an exact pre-existing request may
    -- use no new slot, but this bound can only defer remaining admissions.
    occupied:=occupied+1;
  END LOOP;
  UPDATE public.horse_observation_discovery_segments SET admitted_actors=total WHERE epoch_key=e.epoch_key AND from_ms=s.from_ms;
  IF total<cardinality(s.novel_actors) THEN
    IF processed=0 THEN UPDATE public.horse_observation_discovery_epochs SET available_at=clock_timestamp()+interval '30 seconds',reason='capture_queue_full' WHERE epoch_key=e.epoch_key; END IF;
    RETURN public.fn_horse_discovery_state(e.epoch_key,CASE WHEN processed=0 THEN 'deferred' ELSE 'admitted' END,CASE WHEN processed=0 THEN 'capture_queue_full' ELSE NULL END);
  END IF;
  width:=s.through_ms-s.from_ms;
  UPDATE public.horse_observation_discovery_epochs SET cursor_ms=s.through_ms,slice_through_ms=least(through_ms,s.through_ms+width*2),
    state=CASE WHEN s.through_ms=through_ms THEN 'discovered' ELSE 'pending' END,
    finished_at=CASE WHEN s.through_ms=through_ms THEN clock_timestamp() ELSE NULL END,
    available_at=clock_timestamp(),failures=0,reason=NULL WHERE epoch_key=e.epoch_key;
  RETURN public.fn_horse_discovery_state(e.epoch_key,CASE WHEN s.through_ms=e.through_ms THEN 'discovered' ELSE 'advanced' END);
END;
$_$;


