--
-- TOC entry 4000 (class 1255 OID 20058010)
-- Name: fn_dismiss_club_message(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_dismiss_club_message(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid      uuid := auth.uid();
  v_revision bigint;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;

  -- The revision is read from the club, never accepted from the caller. A
  -- client that sent its own number could dismiss a revision that has not
  -- happened yet and silence every future message for that person.
  SELECT c.message_revision INTO v_revision
    FROM public.clubs c WHERE c.id = p_club_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'club_not_found');
  END IF;

  INSERT INTO public.club_message_dismissals AS d (user_id, club_id, dismissed_revision)
  VALUES (v_uid, p_club_id, COALESCE(v_revision, 0))
  ON CONFLICT (user_id, club_id) DO UPDATE
    -- GREATEST, not assignment: two tabs racing must not move a dismissal
    -- BACKWARDS and resurrect a message the person already retired.
    SET dismissed_revision = GREATEST(d.dismissed_revision, EXCLUDED.dismissed_revision),
        dismissed_at       = now();

  RETURN jsonb_build_object('ok', true, 'dismissed_revision', COALESCE(v_revision, 0));
END;
$$;


ALTER FUNCTION public.fn_dismiss_club_message(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 7314 (class 1255 OID 198172141)
-- Name: fn_dispatch_club_owner_welcomes(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_dispatch_club_owner_welcomes(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE r record; v_result jsonb; v_sent integer:=0; v_cancelled integer:=0; v_blocked integer:=0;
BEGIN
 FOR r IN SELECT * FROM public.club_messenger_owner_followups WHERE status='pending' AND due_at<=clock_timestamp()
  ORDER BY due_at,generation LIMIT greatest(1,least(coalesce(p_limit,200),1000)) FOR UPDATE SKIP LOCKED
 LOOP
  IF NOT EXISTS(SELECT 1 FROM public.club_messenger_admissions a WHERE a.club_id=r.club_id AND a.user_id=r.recipient_id AND a.generation=r.generation AND a.active)
   OR NOT EXISTS(SELECT 1 FROM public.clubs WHERE id=r.club_id AND owner_id=r.sender_id)
   OR NOT EXISTS(SELECT 1 FROM public.club_messenger_owner_welcome_templates WHERE club_id=r.club_id AND user_id=r.sender_id AND enabled)
   OR NOT EXISTS(SELECT 1 FROM public.club_messenger_welcome_deliveries d JOIN public.social_messages m ON m.id=d.message_id WHERE d.generation=r.generation AND d.status='sent' AND NOT coalesce(m.is_deleted,false)) THEN
   v_result:=jsonb_build_object('status','cancelled');
  ELSE
   v_result:=public.fn_send_club_welcome_text(r.club_id,r.recipient_id,r.sender_id,r.content,r.template_revision,'club_owner');
  END IF;
  UPDATE public.club_messenger_owner_followups SET status=v_result->>'status',conversation_id=(v_result->>'conversation_id')::uuid,message_id=(v_result->>'message_id')::uuid,completed_at=clock_timestamp() WHERE generation=r.generation;
  IF v_result->>'status'='sent' THEN v_sent:=v_sent+1; ELSIF v_result->>'status'='blocked' THEN v_blocked:=v_blocked+1; ELSE v_cancelled:=v_cancelled+1; END IF;
 END LOOP;
 RETURN jsonb_build_object('sent',v_sent,'blocked',v_blocked,'cancelled',v_cancelled);
END $$;


ALTER FUNCTION public.fn_dispatch_club_owner_welcomes(p_limit integer) OWNER TO postgres;

--
-- TOC entry 8331 (class 1255 OID 199442280)
-- Name: fn_dispatch_private_record_signal(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_dispatch_private_record_signal(p_topic text, p_payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE paid boolean;
BEGIN
 IF p_topic IS NULL OR NOT (
   p_topic ~ '^member-record:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   OR p_topic ~ '^club-roster:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 ) THEN RAISE EXCEPTION 'Invalid private record topic'; END IF;
 SELECT supabase_enabled INTO STRICT paid FROM public.ca_private_record_transport_state WHERE singleton;
 PERFORM pg_notify('ca_private_record_changes',jsonb_build_object('topic',p_topic,'event','record_changed')::text);
 IF paid THEN PERFORM realtime.send(p_payload,'record_changed',p_topic,true); END IF;
END $_$;


