CREATE FUNCTION public.fn_dispute_start_review_receipt_core_20261006(p_dispute_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club   uuid;
  v_status text;
BEGIN
  SELECT d.club_id, coalesce(d.status, 'open') INTO v_club, v_status
    FROM disputes d WHERE d.id = p_dispute_id FOR UPDATE;

