--
-- TOC entry 7959 (class 1255 OID 24092465)
-- Name: fn_expire_daily_challenge_rewards(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_expire_daily_challenge_rewards() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_n integer;
BEGIN
  IF COALESCE(auth.role(), 'service_role') <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  -- AN UNORDERED BULK UPDATE DEADLOCKS AGAINST THE PLAYER (2026-09-09).
  --
  -- This was a single bare UPDATE over the whole table. A bulk UPDATE takes its
  -- row locks in whatever order the plan happens to produce, and a player
  -- claiming or completing a challenge at the same moment takes ONE row - so
  -- the two can each hold what the other wants. `Cron Health` had this job at
  -- 1 failed / 1 runs, "these are broken, not flaky", with:
  --
  --     ERROR:  deadlock detected
  --
  -- Ordering by primary key gives every caller the same acquisition order,
  -- which is what makes a cycle impossible. SKIP LOCKED then does the rest: a
  -- row a player is holding RIGHT NOW is a row being claimed, and a claimed
  -- reward must not be expired out from under them. Skipping it is the correct
  -- outcome, not a compromise - if it is still unclaimed tomorrow the next run
  -- takes it, and the window is a 7-day one either way.
  WITH due AS (
    SELECT id
      FROM public.user_daily_challenges
     WHERE completed AND NOT claimed AND expired_at IS NULL
       AND completed_at < now() - interval '7 days'
     ORDER BY id
       FOR UPDATE SKIP LOCKED
  )
  UPDATE public.user_daily_challenges u
     SET expired_at = now()
    FROM due
   WHERE u.id = due.id;

  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $$;


ALTER FUNCTION public.fn_expire_daily_challenge_rewards() OWNER TO postgres;

--
-- TOC entry 3473 (class 1255 OID 13915199)
-- Name: fn_expire_stale_cashouts(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_expire_stale_cashouts(p_ttl_hours integer DEFAULT 72) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r record;n integer:=0;
BEGIN
 -- SECURITY DEFINER changes current_user; the invoking role and NULL user are
 -- still checked. Only this existing service entry can choose a system action.
 IF COALESCE(NULLIF(NULLIF(current_setting('role',true),''),'none'),session_user) NOT IN('service_role','postgres') OR auth.uid() IS NOT NULL
 THEN RAISE EXCEPTION 'cashier_expiry_service_required' USING ERRCODE='42501';END IF;
 IF p_ttl_hours IS NULL OR p_ttl_hours<1 OR p_ttl_hours>8760 THEN RAISE EXCEPTION 'cashier_invalid_expiry_hours' USING ERRCODE='22023';END IF;
 -- Bound one transaction to 100 canonical requests. Unsupported pre-cutover
 -- requests stay visible in the reconciliation inventory and cannot starve
 -- proven holds. Any anomaly in an admitted event still aborts this batch.
 FOR r IN SELECT c.id,c.club_id,c.amount,s.id AS escrow_id FROM public.cashout_requests c
   LEFT JOIN public.chip_escrow s ON s.cashout_request_id=c.id
   WHERE c.status='pending' AND EXISTS(SELECT 1 FROM public.accounting_cashier_events ce WHERE ce.cashout_id=c.id)
    AND (c.created_at<transaction_timestamp()-make_interval(hours=>p_ttl_hours) OR c.created_at IS NULL OR NOT isfinite(c.created_at))
   ORDER BY c.club_id,c.id LIMIT 100 LOOP
  IF r.escrow_id IS NULL THEN RAISE EXCEPTION 'cashier_escrow_unverified' USING ERRCODE='23514';END IF;
  PERFORM public.fn_cashier_cashout_transition('expiry_refund',r.club_id,r.id,r.amount,NULL,r.escrow_id,NULL);
  n:=n+1;
 END LOOP;
 RETURN n;
END $$;


ALTER FUNCTION public.fn_expire_stale_cashouts(p_ttl_hours integer) OWNER TO postgres;

