CREATE FUNCTION public.fn_f06_admit_mixed_manager_custody(p_tournament_id uuid, p_lease_generation uuid, p_transfer_id uuid, p_expected jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE prior smarter_private.f06_manager_custody_transfers; canonical jsonb; a smarter_private.f06_manager_custody_admissions; l jsonb;
BEGIN
 PERFORM smarter_private.f06_authority(p_tournament_id,p_lease_generation);
 PERFORM smarter_private.f06_try_lane(p_tournament_id);
 PERFORM smarter_private.f06_authority(p_tournament_id,p_lease_generation,false);
 SELECT * INTO prior FROM smarter_private.f06_manager_custody_transfers WHERE transfer_id=p_transfer_id FOR SHARE;
 IF NOT FOUND OR prior.tournament_id IS DISTINCT FROM p_tournament_id OR prior.successor_generation IS DISTINCT FROM p_lease_generation
 OR to_jsonb(prior) IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'F06_MIXED_SUCCESSOR_CHANGED'; END IF;
 SELECT * INTO a FROM smarter_private.f06_manager_custody_admissions WHERE transfer_id=p_transfer_id;
 IF FOUND THEN
 PERFORM smarter_private.f06_mixed_current_admission(p_tournament_id,p_lease_generation,p_transfer_id);
 ELSE
 canonical:=smarter_private.f06_mixed_custody_snapshot(p_tournament_id,prior.origin_generation,prior.local_proof);
 -- The only legal change before admission is an original's positive terminal
 -- disposition. The original bindings and all operation/seat vectors stay exact.
 IF canonical-ARRAY['originals','original_evidence','pending_original_tables','hand_dispatch'] IS DISTINCT FROM
 prior.canonical_proof-ARRAY['originals','original_evidence','pending_original_tables','hand_dispatch']
 OR (SELECT COALESCE(jsonb_agg(d ORDER BY n),'[]') FROM jsonb_array_elements(canonical->'hand_dispatch') WITH ORDINALITY x(d,n) WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(prior.local_proof->'engines') e WHERE e#>>'{permit,binding,permit_id}'=d->>'permit_id')) IS DISTINCT FROM
 (SELECT COALESCE(jsonb_agg(d ORDER BY n),'[]') FROM jsonb_array_elements(prior.canonical_proof->'hand_dispatch') WITH ORDINALITY x(d,n) WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(prior.local_proof->'engines') e WHERE e#>>'{permit,binding,permit_id}'=d->>'permit_id')) THEN RAISE EXCEPTION 'F06_MIXED_CANONICAL_CHANGED'; END IF;
 IF canonical->'pending_original_tables' IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION 'F06_MIXED_ORIGINAL_DISPOSITION_REQUIRED'; END IF;
 SELECT to_jsonb(e)-'heartbeat_at' INTO l FROM public.engine_tournament_leases e WHERE tournament_id=p_tournament_id;
 INSERT INTO smarter_private.f06_manager_custody_admissions(transfer_id,tournament_id,generation,lease_identity,terminal_proof)
 VALUES(p_transfer_id,p_tournament_id,p_lease_generation,l,canonical->'original_evidence') RETURNING * INTO a;
 END IF;
 RETURN jsonb_build_object('ok',true,'custody_only',true,'transfer_id',p_transfer_id,'tournament_id',p_tournament_id,
 'lease_generation',p_lease_generation,'receipt',to_jsonb(prior),'admission',to_jsonb(a));
END $$;


ALTER FUNCTION public.fn_f06_admit_mixed_manager_custody(p_tournament_id uuid, p_lease_generation uuid, p_transfer_id uuid, p_expected jsonb) OWNER TO postgres;

--
-- TOC entry 9368 (class 1255 OID 37679310)
-- Name: fn_f06_admit_parked_movement(uuid, uuid, uuid, bigint, uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_admit_parked_movement(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid, p_lifecycle bigint, p_break_id uuid, p_admission_id uuid, p_custody_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE o smarter_private.f06_operations; a smarter_private.f06_movement_admissions; prior smarter_private.f06_movement_admissions;
 users uuid[]; proof jsonb; claimed jsonb;
BEGIN
 PERFORM smarter_private.f06_authority(p_tournament_id,p_lease_generation);
 PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
 SELECT array_agg(user_id ORDER BY user_id) INTO users FROM public.tournament_players WHERE tournament_id=p_tournament_id AND table_id=p_table_id;
 PERFORM smarter_private.f06_prefix(p_tournament_id,p_lease_generation,COALESCE(users,'{}'),ARRAY[p_table_id]);
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=p_break_id FOR UPDATE;
 IF NOT FOUND OR (o.tournament_id,o.source_table_id,o.lifecycle) IS DISTINCT FROM(p_tournament_id,p_table_id,p_lifecycle)
 OR o.state NOT IN ('park_requested','begun') OR p_admission_id IS NULL OR p_custody_id IS NULL
 OR NOT EXISTS(SELECT 1 FROM public.tournaments WHERE id=p_tournament_id AND upper(status)='RUNNING')
 OR NOT EXISTS(SELECT 1 FROM public.tables WHERE id=p_table_id AND tournament_id=p_tournament_id AND f06_lifecycle=p_lifecycle AND lower(status)<>'closed' AND NOT COALESCE(is_deleted,false)) THEN
 RAISE EXCEPTION 'F06_MOVEMENT_OPERATION_CHANGED' USING ERRCODE='55000'; END IF;
 SELECT * INTO a FROM smarter_private.f06_movement_admissions WHERE admission_id=p_admission_id;
 IF FOUND THEN
 IF (a.tournament_id,a.lease_generation,a.table_id,a.lifecycle,a.break_id,a.custody_id) IS DISTINCT FROM
 (p_tournament_id,p_lease_generation,p_table_id,p_lifecycle,p_break_id,p_custody_id) THEN
 RAISE EXCEPTION 'F06_MOVEMENT_CHANGED_REPLAY' USING ERRCODE='22023'; END IF;
 IF a.requested_revision IS DISTINCT FROM p_expected_revision THEN
 RAISE EXCEPTION 'F06_MOVEMENT_CHANGED_REPLAY' USING ERRCODE='22023'; END IF;
 IF (a.custody_id,a.lease_generation,a.revision) IS DISTINCT FROM
 (o.custody_id,o.custody_generation,o.revision) THEN
 RAISE EXCEPTION 'F06_MOVEMENT_CUSTODY_CHANGED' USING ERRCODE='55000'; END IF;
 PERFORM smarter_private.f06_assert_movement(p_break_id);
 ELSE
 IF o.revision IS DISTINCT FROM p_expected_revision THEN RAISE EXCEPTION 'F06_MOVEMENT_CAS_CHANGED' USING ERRCODE='55000'; END IF;
 SELECT * INTO prior FROM smarter_private.f06_movement_admissions WHERE break_id=p_break_id AND custody_id=o.custody_id;
 IF FOUND THEN
 -- A successor may carry the same immutable original proof, not recapture a
 -- partial roster. Current lease authority replaces the old custody by CAS.
 proof:=prior.proof;
 ELSE
 IF NOT ((o.state='park_requested' AND o.manifest IS NULL) OR (o.state='begun' AND o.manifest IS NOT NULL)) THEN RAISE EXCEPTION 'F06_MOVEMENT_ORIGINAL_PROOF_MISSING' USING ERRCODE='55000'; END IF;
 -- A begun break that never took a proof takes one from durable receipts
 -- only (f06_movement_prior): moved members by their winner receipts, the
 -- rest by their live seats and registrations, bound to this break.
 proof:=smarter_private.f06_movement_prior(p_tournament_id,p_table_id);
 IF o.state='begun' AND proof#>>'{receipts,break_id}' IS DISTINCT FROM p_break_id::text THEN RAISE EXCEPTION 'F06_MOVEMENT_ORIGINAL_PROOF_MISSING' USING ERRCODE='55000'; END IF;
 END IF;
 claimed:=public.fn_f06_claim_custody(p_tournament_id,p_lease_generation,p_break_id,p_custody_id,p_expected_revision);
 IF claimed->'ok' IS DISTINCT FROM 'true'::jsonb OR claimed->>'custody_id' IS DISTINCT FROM p_custody_id::text
 OR claimed->>'custody_generation' IS DISTINCT FROM p_lease_generation::text THEN
 RAISE EXCEPTION 'F06_MOVEMENT_CAS_CHANGED' USING ERRCODE='55000'; END IF;
 INSERT INTO smarter_private.f06_movement_admissions(admission_id,tournament_id,lease_generation,table_id,lifecycle,break_id,custody_id,revision,requested_revision,proof,proof_hash)
 VALUES(p_admission_id,p_tournament_id,p_lease_generation,p_table_id,p_lifecycle,p_break_id,p_custody_id,(claimed->>'revision')::bigint,p_expected_revision,proof,
 encode(extensions.digest(convert_to(proof::text,'UTF8'),'sha256'),'hex')) RETURNING * INTO a;
 PERFORM smarter_private.f06_assert_movement(p_break_id);
 END IF;
 RETURN jsonb_build_object('ok',true,'mode','movement_only','admission_id',a.admission_id,'tournament_id',a.tournament_id,
 'lease_generation',a.lease_generation,'table_id',a.table_id,'lifecycle',a.lifecycle::text,'break_id',a.break_id,
 'custody_id',a.custody_id,'revision',a.revision::text,'proof_hash',a.proof_hash);
END $$;


ALTER FUNCTION public.fn_f06_admit_parked_movement(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid, p_lifecycle bigint, p_break_id uuid, p_admission_id uuid, p_custody_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- TOC entry 5039 (class 1255 OID 28811019)
-- Name: fn_f06_allocate_hand_number(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_allocate_hand_number(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE s jsonb;n bigint;floor_number bigint;
BEGIN
 s:=public.fn_f06_hand_number_state(p_tournament_id,p_lease_generation,p_table_id);
 IF s->>'ok' IS DISTINCT FROM 'true' THEN RETURN s; END IF;
 IF s->>'can_reserve' IS DISTINCT FROM 'true' THEN RETURN jsonb_build_object('ok',false,'reason',s->>'blocked_reason'); END IF;
 IF (s->>'used_hand_number_max')::bigint>=9007199254740991 THEN RETURN jsonb_build_object('ok',false,'reason','hand_number_unsafe'); END IF;
 floor_number:=GREATEST(1000000,(s->>'used_hand_number_max')::bigint+1);
 n:=smarter_private.f06_allocate_number_above(floor_number);
 RETURN jsonb_build_object('ok',true,'table_id',p_table_id,'lifecycle',s->>'lifecycle','hand_number',n::text,'hand_number_high_water',s->>'used_hand_number_max');
END $$;


ALTER FUNCTION public.fn_f06_allocate_hand_number(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid) OWNER TO postgres;

--
-- TOC entry 3555 (class 1255 OID 28810983)
-- Name: fn_f06_amend_attempt(uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_amend_attempt(p_tournament_id uuid, p_lease_generation uuid, p_break_id uuid, p_user_id uuid, p_expected_request_id uuid, p_amendment_id uuid, p_new_request_id uuid, p_destination_table_id uuid, p_destination_seat_number integer, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE a smarter_private.f06_attempts;o smarter_private.f06_operations;m smarter_private.f06_members;payload jsonb; prior smarter_private.f06_attempts;
BEGIN
 payload:=jsonb_build_object('break',p_break_id,'user',p_user_id,'predecessor',p_expected_request_id,'new',p_new_request_id,'destination',p_destination_table_id,'seat',p_destination_seat_number,'reason',p_reason);
 PERFORM smarter_private.f06_lock_break(p_tournament_id,p_lease_generation,p_break_id,p_destination_table_id);
 SELECT * INTO prior FROM smarter_private.f06_attempts WHERE amendment_id=p_amendment_id;
 IF FOUND THEN
 IF prior.amendment_payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'F06_CHANGED_AMENDMENT' USING ERRCODE='22023'; END IF;
 RETURN smarter_private.f06_state(p_break_id); END IF;
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=p_break_id;
 SELECT * INTO m FROM smarter_private.f06_members WHERE break_id=p_break_id AND user_id=p_user_id;
 SELECT * INTO a FROM smarter_private.f06_attempts WHERE request_id=p_expected_request_id AND break_id=p_break_id AND user_id=p_user_id;
 IF NOT FOUND OR p_amendment_id IS NULL OR p_new_request_id IS NULL OR p_new_request_id=p_expected_request_id OR length(btrim(COALESCE(p_reason,''))) NOT BETWEEN 1 AND 512 THEN
 RAISE EXCEPTION 'F06_INVALID_AMENDMENT' USING ERRCODE='22023'; END IF;
 IF a.state IN ('winner','fenced') THEN RETURN smarter_private.f06_state(p_break_id); END IF;
 IF o.state<>'begun' OR NOT EXISTS(SELECT 1 FROM public.tournaments WHERE id=p_tournament_id AND upper(status)='RUNNING') THEN
 RETURN jsonb_build_object('ok',false,'reason','terminal_handoff_required'); END IF;
 IF EXISTS(SELECT 1 FROM public.tournament_seat_move_receipts WHERE request_id IN(p_expected_request_id,p_new_request_id)) THEN
 RAISE EXCEPTION 'F06_UNBOUND_RECEIPT_CONFLICT' USING ERRCODE='55000'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.table_seats s JOIN public.tables t ON t.id=s.table_id
 WHERE s.id=m.source_seat_id AND s.occupancy_id=m.occupancy_id AND s.left_at IS NULL AND s.user_id=p_user_id AND s.table_id=o.source_table_id AND t.f06_lifecycle=o.lifecycle) THEN
 RAISE EXCEPTION 'F06_SOURCE_CHANGED' USING ERRCODE='55000'; END IF;
 PERFORM smarter_private.f06_validate_destination(p_tournament_id,o.source_table_id,p_destination_table_id,p_destination_seat_number);
 UPDATE smarter_private.f06_attempts SET state='fenced' WHERE request_id=p_expected_request_id;
 INSERT INTO smarter_private.f06_attempts(request_id,break_id,user_id,revision,predecessor,amendment_id,amendment_payload,destination_table_id,destination_seat_number,generation)
 VALUES(p_new_request_id,p_break_id,p_user_id,a.revision+1,p_expected_request_id,p_amendment_id,payload,p_destination_table_id,p_destination_seat_number,p_lease_generation);
 RETURN smarter_private.f06_state(p_break_id);
END $$;


ALTER FUNCTION public.fn_f06_amend_attempt(p_tournament_id uuid, p_lease_generation uuid, p_break_id uuid, p_user_id uuid, p_expected_request_id uuid, p_amendment_id uuid, p_new_request_id uuid, p_destination_table_id uuid, p_destination_seat_number integer, p_reason text) OWNER TO postgres;

--
-- TOC entry 4149 (class 1255 OID 37952243)
-- Name: fn_f06_assert_drained_manager_custody(uuid, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_assert_drained_manager_custody(p_tournament_id uuid, p_lease_generation uuid, p_origin_generation uuid, p_sources jsonb, p_expected jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE o smarter_private.f06_operations; l public.engine_tournament_leases;
 x jsonb; permit_row smarter_private.f06_hand_permits; u uuid; ids uuid[]; users uuid[]; terminal jsonb:='[]'; witness jsonb; prior jsonb; parks jsonb:='[]'; originals jsonb; pending jsonb; proof jsonb;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR p_tournament_id IS NULL
 OR jsonb_typeof(p_sources) IS DISTINCT FROM 'array' THEN
 RAISE EXCEPTION 'F06_DRAINED_CUSTODY_SERVICE_REQUIRED' USING ERRCODE='42501'; END IF;
 IF p_lease_generation IS NOT NULL THEN
 PERFORM smarter_private.f06_authority(p_tournament_id,p_lease_generation);
 ELSE
 IF p_origin_generation IS NULL OR jsonb_array_length(p_sources)=0 OR p_expected IS NOT NULL THEN
 RAISE EXCEPTION 'F06_DRAINED_CUSTODY_ORIGINAL_REQUIRED' USING ERRCODE='22023'; END IF;
 SELECT * INTO l FROM public.engine_tournament_leases WHERE tournament_id=p_tournament_id FOR KEY SHARE;
 IF FOUND AND (l.lease_generation IS DISTINCT FROM p_origin_generation OR l.protocol_version<>2
 OR l.heartbeat_at>=clock_timestamp()-interval '30 seconds') THEN
 RAISE EXCEPTION 'F06_DRAINED_CUSTODY_LEASE_CHANGED' USING ERRCODE='55000'; END IF;
 END IF;
 -- Same lease -> event lane order as the owning F06 request. This function
 -- never writes a lease even when the former row is absent.
 PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
 IF p_lease_generation IS NOT NULL THEN PERFORM smarter_private.f06_authority(p_tournament_id,p_lease_generation,false); END IF;
 -- Same sorted physical row order as f06_prefix, including the old-owner
 -- read-only branch where no current generation may be fabricated.
 IF p_lease_generation IS NULL THEN
 SELECT * INTO l FROM public.engine_tournament_leases WHERE tournament_id=p_tournament_id FOR KEY SHARE;
 IF FOUND AND (l.lease_generation IS DISTINCT FROM p_origin_generation OR l.protocol_version<>2
 OR l.heartbeat_at>=clock_timestamp()-interval '30 seconds') THEN
 RAISE EXCEPTION 'F06_DRAINED_CUSTODY_LEASE_CHANGED' USING ERRCODE='55000'; END IF;
 END IF;
 SELECT COALESCE(array_agg((value->>'table_id')::uuid ORDER BY value->>'table_id'),'{}') INTO ids FROM jsonb_array_elements(p_sources);
 SELECT COALESCE(array_agg(DISTINCT user_id ORDER BY user_id),'{}') INTO users FROM public.table_seats
 WHERE table_id=ANY(ids) AND user_id IS NOT NULL;
 FOREACH u IN ARRAY users LOOP PERFORM pg_advisory_xact_lock(hashtextextended('table_cap:'||u::text,0)); END LOOP;
 PERFORM 1 FROM public.tournaments WHERE id=p_tournament_id AND upper(status)='RUNNING' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'F06_DRAINED_CUSTODY_EVENT_CHANGED' USING ERRCODE='55000'; END IF;
 PERFORM 1 FROM public.tournament_players WHERE tournament_id=p_tournament_id AND user_id=ANY(users) ORDER BY user_id FOR UPDATE;
 PERFORM 1 FROM public.tables WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 PERFORM s.id FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
 WHERE tb.tournament_id=p_tournament_id AND (s.user_id=ANY(users) OR s.table_id=ANY(ids)) ORDER BY s.id FOR UPDATE OF s;
 IF (SELECT count(DISTINCT value->>'table_id') FROM jsonb_array_elements(p_sources))<>jsonb_array_length(p_sources)
 OR (SELECT count(DISTINCT value->>'break_id') FROM jsonb_array_elements(p_sources))<>jsonb_array_length(p_sources)
 OR (jsonb_array_length(p_sources)>0 AND p_origin_generation IS NULL) THEN
 RAISE EXCEPTION 'F06_DRAINED_CUSTODY_SOURCE_CHANGED' USING ERRCODE='22023'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(p_sources) ORDER BY value->>'table_id' LOOP
 PERFORM 1 FROM public.tables WHERE id=(x->>'table_id')::uuid AND tournament_id=p_tournament_id
 AND f06_lifecycle::text=x->>'lifecycle' AND lower(status)<>'closed' AND NOT COALESCE(is_deleted,false) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'F06_DRAINED_CUSTODY_SOURCE_CHANGED' USING ERRCODE='55000'; END IF;
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=(x->>'break_id')::uuid FOR SHARE;
 IF NOT FOUND OR (o.tournament_id,o.source_table_id,o.lifecycle,o.origin_generation)
 IS DISTINCT FROM (p_tournament_id,(x->>'table_id')::uuid,(x->>'lifecycle')::bigint,p_origin_generation)
 OR o.state<>'park_requested' OR o.revision<>0 OR o.manifest IS NOT NULL
 OR o.custody_id IS NOT NULL OR o.custody_generation IS NOT NULL OR o.close_receipt IS NOT NULL
 OR o.cleanup_kind IS NOT NULL OR o.abort_receipt_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM smarter_private.f06_members WHERE break_id=o.break_id)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_attempts WHERE break_id=o.break_id) THEN
 RAISE EXCEPTION 'F06_DRAINED_CUSTODY_NOT_PREMANIFEST' USING ERRCODE='55000'; END IF;
 -- The already-installed movement authority supplies the original completed
 -- source boundary, including its independent atomic and stack identities.
 prior:=smarter_private.f06_movement_prior(p_tournament_id,o.source_table_id);
 parks:=parks||jsonb_build_array(jsonb_build_object('park',to_jsonb(o),'prior',prior));
 END LOOP;
 SELECT COALESCE(jsonb_agg(to_jsonb(h) ORDER BY h.permit_id),'[]') INTO originals
 FROM smarter_private.f06_hand_permits h WHERE h.tournament_id=p_tournament_id AND h.state='reserved';
 SELECT COALESCE(jsonb_agg(id ORDER BY id),'[]') INTO pending FROM
 (SELECT DISTINCT h.table_id id FROM smarter_private.f06_hand_permits h
 WHERE h.tournament_id=p_tournament_id AND h.state='reserved') q;
 proof:=jsonb_build_object('parks',parks,'originals',originals);
 IF p_expected IS NOT NULL THEN
 IF jsonb_typeof(p_expected) IS DISTINCT FROM 'object' OR p_expected->'parks' IS DISTINCT FROM parks
 OR jsonb_typeof(p_expected->'originals') IS DISTINCT FROM 'array' THEN
 RAISE EXCEPTION 'F06_DRAINED_CUSTODY_CHANGED' USING ERRCODE='55000'; END IF;
 IF (SELECT count(DISTINCT value->>'permit_id') FROM jsonb_array_elements(p_expected->'originals'))<>jsonb_array_length(p_expected->'originals')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_expected->'originals') e WHERE e->>'state' IS DISTINCT FROM 'reserved' OR e->'evidence_id' IS DISTINCT FROM 'null'::jsonb) THEN
 RAISE EXCEPTION 'F06_DRAINED_CUSTODY_CAPTURE_INVALID' USING ERRCODE='22023'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(p_expected->'originals') LOOP
 SELECT * INTO permit_row FROM smarter_private.f06_hand_permits WHERE permit_id=(x->>'permit_id')::uuid FOR SHARE;
 IF NOT FOUND OR permit_row.tournament_id IS DISTINCT FROM p_tournament_id
 OR (to_jsonb(permit_row)-'state'-'evidence_id') IS DISTINCT FROM (x-'state'-'evidence_id') THEN
 RAISE EXCEPTION 'F06_DRAINED_CUSTODY_ORIGINAL_CHANGED' USING ERRCODE='55000'; END IF;
 IF to_jsonb(permit_row)=x THEN CONTINUE; END IF;
 witness:=NULL;
 IF permit_row.state='accepted' THEN
 SELECT jsonb_build_object('atomic',to_jsonb(a),'history_id',hh.id) INTO witness
 FROM public.hand_atomic_commits a JOIN public.hand_history hh ON hh.id=a.hand_id
 AND hh.table_id=a.table_id AND hh.hand_number=a.hand_number
 WHERE a.hand_id=permit_row.evidence_id AND a.table_id=permit_row.table_id AND a.hand_number=permit_row.hand_number
 AND a.post_commit_completed_at IS NOT NULL AND isfinite(a.post_commit_completed_at)
 AND a.post_commit_completed_at>=a.committed_at AND a.post_commit_result->'ok'='true'::jsonb
 AND a.post_commit_result->>'hand_id'=a.hand_id::text
 AND (a.post_commit_result->>'hand_number')::bigint=a.hand_number;
 ELSIF permit_row.state='never_started' THEN
 -- Only the immutable preparation receipt is supported here. A generic state
 -- or an old mutable park custody label cannot substitute for original proof.
 SELECT to_jsonb(c) INTO witness FROM smarter_private.f06_prepared_hand_cancellations c
 WHERE c.permit_id=permit_row.permit_id AND permit_row.evidence_id=permit_row.permit_id
 AND (c.tournament_id,c.generation,c.table_id,c.lifecycle,c.hand_number,c.custody_id)
 =(permit_row.tournament_id,permit_row.generation,permit_row.table_id,permit_row.lifecycle,permit_row.hand_number,permit_row.custody_id);
 ELSIF permit_row.state='aborted_unsettled' AND smarter_private.f06_generation_aborted(permit_row.tournament_id,permit_row.generation) THEN
 SELECT r.receipt INTO witness FROM (
 SELECT a.permit_id,a.receipt_id,a.tournament_id,a.generation,a.table_id,a.hand_number,a.expected,
 to_jsonb(a) receipt FROM smarter_private.f06_unsettled_hand_aborts a WHERE a.outcome='aborted_unsettled'
 UNION ALL
 SELECT a.permit_id,a.receipt_id,a.tournament_id,a.generation,a.table_id,a.hand_number,a.expected,
 jsonb_build_object('hand',to_jsonb(a),'receipt',to_jsonb(r)) FROM smarter_private.f06_generation_abort_hands a
 JOIN smarter_private.f06_generation_aborts r USING(receipt_id,tournament_id,generation) WHERE r.outcome='aborted_unsettled'
 UNION ALL
 SELECT a.permit_id,a.receipt_id,a.tournament_id,a.generation,a.table_id,a.hand_number,a.expected,
 jsonb_build_object('hand',to_jsonb(a),'receipt',to_jsonb(r)) FROM smarter_private.f06_mixed_abort_hands a
 JOIN smarter_private.f06_mixed_aborts r USING(receipt_id,tournament_id) WHERE r.outcome='aborted_unsettled') r
 WHERE (r.permit_id,r.receipt_id,r.tournament_id,r.generation,r.table_id,r.hand_number)
 =(permit_row.permit_id,permit_row.evidence_id,permit_row.tournament_id,permit_row.generation,permit_row.table_id,permit_row.hand_number)
 AND r.expected->'permit'=x;
 END IF;
 IF witness IS NULL OR EXISTS(SELECT 1 FROM smarter_private.f06_hand_dispatch WHERE permit_id=permit_row.permit_id) THEN
 RAISE EXCEPTION 'F06_DRAINED_CUSTODY_TERMINAL_EVIDENCE_REQUIRED' USING ERRCODE='55000'; END IF;
 terminal:=terminal||jsonb_build_array(jsonb_build_object('permit',to_jsonb(permit_row),'evidence',witness));
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(originals) h WHERE NOT EXISTS(
 SELECT 1 FROM jsonb_array_elements(p_expected->'originals') e WHERE e=h)) THEN
 RAISE EXCEPTION 'F06_DRAINED_CUSTODY_NEW_ORIGINAL' USING ERRCODE='55000'; END IF;
 proof:=p_expected;
 END IF;
 RETURN jsonb_build_object('ok',true,'tournament_id',p_tournament_id,'lease_generation',p_lease_generation,
 'recovery_required',jsonb_array_length(pending)>0,'pending_tables',pending,'proof',proof,'terminal_proof',terminal);
END $$;


ALTER FUNCTION public.fn_f06_assert_drained_manager_custody(p_tournament_id uuid, p_lease_generation uuid, p_origin_generation uuid, p_sources jsonb, p_expected jsonb) OWNER TO postgres;

--
-- TOC entry 3811 (class 1255 OID 48138821)
-- Name: fn_f06_attest_retired_manager_origin(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_attest_retired_manager_origin(p_receipt_id uuid, p_input jsonb, p_expected jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE t uuid:=(p_input->>'tournament_id')::uuid; g uuid:=(p_input->>'generation')::uuid;
 actual jsonb; prior smarter_private.f06_retired_manager_origins; observed timestamptz;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('app.smarter_data_actor',true) IS DISTINCT FROM 'service' THEN
 RAISE EXCEPTION 'F06_ABORT_SERVICE_REQUIRED' USING ERRCODE='42501'; END IF;
 IF p_receipt_id IS NULL OR p_receipt_id::text IS DISTINCT FROM smarter_private.f06_retired_origin_cohort(t)->>'receipt_id' THEN
 RAISE EXCEPTION 'F06_RETIRED_OPERATION_CHANGED'; END IF;
 PERFORM smarter_private.f06_retired_origin_lock(t);
 SELECT * INTO prior FROM smarter_private.f06_retired_manager_origins WHERE receipt_id=p_receipt_id;
 IF FOUND THEN
 -- A lost response reads its immutable outcome, even after hand disposition.
 IF (prior.tournament_id,prior.origin_generation,prior.physical_proof) IS DISTINCT FROM (t,g,p_input->'physical')
 OR (p_expected IS NOT NULL AND prior.canonical_proof IS DISTINCT FROM p_expected) THEN
 RAISE EXCEPTION 'F06_RETIRED_CHANGED_REPLAY'; END IF;
 RETURN jsonb_build_object('ok',true,'receipt',to_jsonb(prior),'canonical',prior.canonical_proof);
 END IF;
 observed:=(p_input#>>'{physical,observed_at}')::timestamptz;
 IF observed IS NULL OR NOT isfinite(observed) OR NOT (clock_timestamp()-observed BETWEEN interval '-30 seconds' AND interval '60 seconds') THEN
 RAISE EXCEPTION 'F06_RETIRED_PHYSICAL_PROOF_STALE'; END IF;
 actual:=smarter_private.f06_retired_origin_snapshot(p_input);
 IF p_expected IS NOT NULL THEN
 IF actual IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'F06_RETIRED_CANONICAL_CHANGED'; END IF;
 INSERT INTO smarter_private.f06_retired_manager_origins(receipt_id,tournament_id,origin_generation,physical_proof,canonical_proof)
 VALUES(p_receipt_id,t,g,p_input->'physical',actual) RETURNING * INTO prior;
 END IF;
 RETURN jsonb_build_object('ok',true,'canonical',actual,'receipt',CASE WHEN prior.receipt_id IS NULL THEN NULL ELSE to_jsonb(prior) END);
END $$;


ALTER FUNCTION public.fn_f06_attest_retired_manager_origin(p_receipt_id uuid, p_input jsonb, p_expected jsonb) OWNER TO postgres;

--
-- TOC entry 7196 (class 1255 OID 28810976)
-- Name: fn_f06_begin_break(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_begin_break(p_tournament_id uuid, p_lease_generation uuid, p_break_id uuid, p_members jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE o smarter_private.f06_operations; x record; norm jsonb; users uuid[];ids uuid[];
BEGIN
 IF jsonb_typeof(p_members) IS DISTINCT FROM 'array' OR jsonb_array_length(p_members) NOT BETWEEN 1 AND 10 THEN
 RAISE EXCEPTION 'F06_INVALID_MANIFEST' USING ERRCODE='22023'; END IF;
 SELECT jsonb_agg(value ORDER BY value->>'user_id') INTO norm FROM jsonb_array_elements(p_members);
 SELECT array_agg((value->>'user_id')::uuid),array_agg((value->>'destination_table_id')::uuid) INTO users,ids FROM jsonb_array_elements(norm);
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=p_break_id AND tournament_id=p_tournament_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'F06_UNKNOWN_BREAK' USING ERRCODE='22023'; END IF;
 PERFORM smarter_private.f06_prefix(p_tournament_id,p_lease_generation,users,array_append(ids,o.source_table_id));
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=p_break_id FOR UPDATE;
 IF o.manifest IS NOT NULL THEN
 IF o.manifest IS DISTINCT FROM norm THEN RAISE EXCEPTION 'F06_CHANGED_MANIFEST' USING ERRCODE='22023'; END IF;
 RETURN smarter_private.f06_state(p_break_id); END IF;
 IF EXISTS(SELECT 1 FROM smarter_private.f06_hand_permits WHERE table_id=o.source_table_id AND state='reserved') THEN
 RETURN jsonb_build_object('ok',false,'reason','park_not_drained'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tournaments WHERE id=p_tournament_id AND upper(status)='RUNNING') THEN
 RETURN jsonb_build_object('ok',false,'reason','terminal_handoff_required'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tables WHERE id=o.source_table_id AND f06_lifecycle=o.lifecycle AND lower(status)<>'closed' AND NOT COALESCE(is_deleted,false)) THEN
 RAISE EXCEPTION 'F06_SOURCE_LIFECYCLE' USING ERRCODE='55000'; END IF;
 IF (SELECT count(*) FROM public.table_seats WHERE table_id=o.source_table_id AND left_at IS NULL)<>jsonb_array_length(norm)
 OR (SELECT count(*) FROM public.tournament_players WHERE tournament_id=p_tournament_id AND table_id=o.source_table_id AND status IN ('playing','registered'))<>jsonb_array_length(norm)
 OR (SELECT count(DISTINCT member_user) FROM unnest(users) member_user)<>jsonb_array_length(norm) THEN
 RAISE EXCEPTION 'F06_WHOLE_ROSTER_REQUIRED' USING ERRCODE='22023'; END IF;
 FOR x IN SELECT * FROM jsonb_to_recordset(norm) AS m(user_id uuid,source_seat_id uuid,source_seat_number integer,occupancy_id uuid,request_id uuid,destination_table_id uuid,destination_seat_number integer) LOOP
 IF NOT EXISTS(SELECT 1 FROM public.table_seats s JOIN public.tournament_players p ON p.user_id=s.user_id AND p.table_id=s.table_id AND p.seat_number=s.seat_number
 WHERE s.id=x.source_seat_id AND s.table_id=o.source_table_id AND s.user_id=x.user_id AND s.seat_number=x.source_seat_number AND s.occupancy_id=x.occupancy_id
 AND s.left_at IS NULL AND s.stack>0 AND s.stack::text NOT IN ('NaN','Infinity','-Infinity') AND p.tournament_id=p_tournament_id AND p.status='playing' AND abs(s.stack-p.chips::numeric)<=0.5)
 OR EXISTS(SELECT 1 FROM public.tournament_seat_move_receipts WHERE request_id=x.request_id) THEN RAISE EXCEPTION 'F06_SOURCE_NOT_EXACT' USING ERRCODE='55000'; END IF;
 PERFORM smarter_private.f06_validate_destination(p_tournament_id,o.source_table_id,x.destination_table_id,x.destination_seat_number);
 INSERT INTO smarter_private.f06_members VALUES(p_break_id,x.user_id,x.source_seat_id,x.source_seat_number,x.occupancy_id);
 INSERT INTO smarter_private.f06_attempts(request_id,break_id,user_id,revision,destination_table_id,destination_seat_number,generation)
 VALUES(x.request_id,p_break_id,x.user_id,1,x.destination_table_id,x.destination_seat_number,p_lease_generation);
 END LOOP;
 IF EXISTS(SELECT 1 FROM smarter_private.f06_attempts WHERE break_id=p_break_id GROUP BY destination_table_id,destination_seat_number HAVING count(*)>1) THEN
 RAISE EXCEPTION 'F06_DUPLICATE_DESTINATION' USING ERRCODE='22023'; END IF;
 UPDATE smarter_private.f06_operations SET manifest=norm,state='begun' WHERE break_id=p_break_id;
 RETURN smarter_private.f06_state(p_break_id);
END $$;


ALTER FUNCTION public.fn_f06_begin_break(p_tournament_id uuid, p_lease_generation uuid, p_break_id uuid, p_members jsonb) OWNER TO postgres;

--
-- TOC entry 7755 (class 1255 OID 28810994)
-- Name: fn_f06_begin_hand(uuid, uuid, uuid, bigint, uuid, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_begin_hand(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid, p_lifecycle bigint, p_permit_id uuid, p_hand_number bigint, p_custody_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE h smarter_private.f06_hand_permits;
BEGIN
 /* A TABLE'S HAND DOES NOT WAIT FOR ITS SIBLING TABLES (2026-10-03): the
    tournament lane T(id) shared, then this table and its seats FOR
    UPDATE. See fn_ca_f06_share_table_lane. */
 PERFORM public.fn_ca_f06_share_table_lane(p_tournament_id,p_lease_generation,p_table_id);
 SELECT * INTO h FROM smarter_private.f06_hand_permits WHERE permit_id=p_permit_id;
 IF FOUND THEN
 IF (h.tournament_id,h.table_id,h.lifecycle,h.hand_number,h.custody_id,h.generation) IS DISTINCT FROM(p_tournament_id,p_table_id,p_lifecycle,p_hand_number,p_custody_id,p_lease_generation) THEN
 RAISE EXCEPTION 'F06_CHANGED_HAND_PERMIT' USING ERRCODE='22023'; END IF;
 RETURN to_jsonb(h)||jsonb_build_object('ok',h.state='reserved','lifecycle',h.lifecycle::text,'hand_number',h.hand_number::text); END IF;
 -- A permit its engine attested absent (fn_park_stopped_time_bank_custody, 2026-09-27)
 -- can never be begun afterwards: the absence was recorded under this same lane.
 IF EXISTS(SELECT 1 FROM smarter_private.f06_absent_permit_releases WHERE permit_id=p_permit_id) THEN
 RETURN jsonb_build_object('ok',false,'reason','permit_released_absent'); END IF;
 IF EXISTS(SELECT 1 FROM smarter_private.f06_operations WHERE source_table_id=p_table_id AND state NOT IN ('acknowledged','withdrawn_before_manifest')) THEN
 RETURN jsonb_build_object('ok',false,'reason','source_excluded'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tables tb JOIN public.tournaments t ON t.id=tb.tournament_id WHERE tb.id=p_table_id AND t.id=p_tournament_id AND upper(t.status)='RUNNING' AND tb.f06_lifecycle=p_lifecycle
 AND lower(tb.status)<>'closed' AND NOT COALESCE(tb.is_deleted,false)) THEN RAISE EXCEPTION 'F06_HAND_LIFECYCLE' USING ERRCODE='55000'; END IF;
 IF p_hand_number IS NULL OR p_hand_number<1 OR p_custody_id IS NULL THEN RAISE EXCEPTION 'F06_HAND_IDENTITY' USING ERRCODE='22023'; END IF;
 -- Hand numbers are permanently unique for the physical table, across every lifecycle.
 -- Exact permit replay above is lawful; a new permit cannot adopt historical evidence.
 IF EXISTS(SELECT 1 FROM smarter_private.f06_hand_permits WHERE table_id=p_table_id AND hand_number=p_hand_number)
 OR EXISTS(SELECT 1 FROM public.hand_atomic_commits WHERE table_id=p_table_id AND hand_number=p_hand_number)
 OR EXISTS(SELECT 1 FROM public.hand_history WHERE table_id=p_table_id AND hand_number=p_hand_number) THEN
 RETURN jsonb_build_object('ok',false,'reason','hand_number_already_used'); END IF;
 IF EXISTS(SELECT 1 FROM smarter_private.f06_hand_permits WHERE table_id=p_table_id AND state='reserved') THEN
 RETURN jsonb_build_object('ok',false,'reason','hand_permit_unresolved'); END IF;
 INSERT INTO smarter_private.f06_hand_permits(permit_id,tournament_id,table_id,lifecycle,hand_number,custody_id,generation)
 VALUES(p_permit_id,p_tournament_id,p_table_id,p_lifecycle,p_hand_number,p_custody_id,p_lease_generation) RETURNING * INTO h;
 RETURN to_jsonb(h)||jsonb_build_object('ok',true,'lifecycle',h.lifecycle::text,'hand_number',h.hand_number::text);
END $$;


ALTER FUNCTION public.fn_f06_begin_hand(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid, p_lifecycle bigint, p_permit_id uuid, p_hand_number bigint, p_custody_id uuid) OWNER TO postgres;

--
-- TOC entry 5218 (class 1255 OID 28837832)
-- Name: fn_f06_break_state(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_break_state(p_tournament_id uuid, p_lease_generation uuid, p_break_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
BEGIN
 PERFORM smarter_private.f06_lock_break(p_tournament_id,p_lease_generation,p_break_id);
 -- Winners are bound in the SAME transaction by the original receipt trigger.
 -- A legacy receipt without that provenance cannot be promoted here.
 IF EXISTS(SELECT 1 FROM smarter_private.f06_attempts a JOIN public.tournament_seat_move_receipts r USING(request_id) WHERE a.break_id=p_break_id AND a.state<>'winner') THEN
 RAISE EXCEPTION 'F06_UNBOUND_RECEIPT_CONFLICT' USING ERRCODE='55000'; END IF;
 RETURN smarter_private.f06_state(p_break_id);
END $$;


ALTER FUNCTION public.fn_f06_break_state(p_tournament_id uuid, p_lease_generation uuid, p_break_id uuid) OWNER TO postgres;

--
-- TOC entry 5309 (class 1255 OID 36418339)
-- Name: fn_f06_cancel_prepared_hand(uuid, uuid, uuid, bigint, uuid, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_cancel_prepared_hand(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid, p_lifecycle bigint, p_permit_id uuid, p_hand_number bigint, p_custody_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE h smarter_private.f06_hand_permits; r smarter_private.f06_prepared_hand_cancellations;
BEGIN
 IF p_tournament_id IS NULL OR p_lease_generation IS NULL OR p_table_id IS NULL
 OR p_lifecycle IS NULL OR p_permit_id IS NULL OR p_hand_number IS NULL
 OR p_hand_number<1 OR p_custody_id IS NULL THEN
 RAISE EXCEPTION 'F06_PREPARED_IDENTITY_REQUIRED' USING ERRCODE='22023'; END IF;
 -- Unchanged protocol-2 admission and canonical lease/lane/physical-row order.
 -- A successor lease cannot certify the original process's local non-actuation.
 PERFORM smarter_private.f06_prefix(p_tournament_id,p_lease_generation,'{}',ARRAY[p_table_id]);
 SELECT * INTO h FROM smarter_private.f06_hand_permits WHERE permit_id=p_permit_id FOR UPDATE;
 IF NOT FOUND OR (h.tournament_id,h.generation,h.table_id,h.lifecycle,h.hand_number,h.custody_id)
 IS DISTINCT FROM(p_tournament_id,p_lease_generation,p_table_id,p_lifecycle,p_hand_number,p_custody_id) THEN
 RAISE EXCEPTION 'F06_PREPARED_ORIGINAL_REQUIRED' USING ERRCODE='55000'; END IF;
 SELECT * INTO r FROM smarter_private.f06_prepared_hand_cancellations WHERE permit_id=p_permit_id;
 IF FOUND THEN
 IF (r.tournament_id,r.generation,r.table_id,r.lifecycle,r.hand_number,r.custody_id)
 IS DISTINCT FROM(p_tournament_id,p_lease_generation,p_table_id,p_lifecycle,p_hand_number,p_custody_id)
 OR h.state<>'never_started' OR h.evidence_id IS DISTINCT FROM p_permit_id THEN
 RAISE EXCEPTION 'F06_PREPARED_RECEIPT_CHANGED' USING ERRCODE='55000'; END IF;
 ELSE
 IF h.state<>'reserved' OR h.evidence_id IS NOT NULL THEN
 RAISE EXCEPTION 'F06_PREPARED_NOT_RESERVED' USING ERRCODE='55000'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tables tb JOIN public.tournaments t ON t.id=tb.tournament_id
 WHERE tb.id=p_table_id AND tb.tournament_id=p_tournament_id AND tb.f06_lifecycle=p_lifecycle
 AND upper(t.status)='RUNNING' AND lower(tb.status)<>'closed' AND NOT COALESCE(tb.is_deleted,false)) THEN
 RAISE EXCEPTION 'F06_HAND_LIFECYCLE' USING ERRCODE='55000'; END IF;
 -- Durable witnesses only REFUSE a claimed no-start; their absence cannot grant it.
 -- The active snapshot uses its maintained partial index. Completed snapshot
 -- history is not scanned or inferred absent: positive original-process start
 -- exclusion (not a successor reconstruction) is the authority for this receipt.
 IF EXISTS(SELECT 1 FROM smarter_private.f06_hand_dispatch WHERE permit_id=p_permit_id)
 OR EXISTS(SELECT 1 FROM public.hand_atomic_commits WHERE table_id=p_table_id AND hand_number=p_hand_number)
 OR EXISTS(SELECT 1 FROM public.hand_history WHERE table_id=p_table_id AND hand_number=p_hand_number)
 OR EXISTS(SELECT 1 FROM public.hand_state_snapshots WHERE table_id=p_table_id AND NOT is_complete AND hand_number=p_hand_number)
 OR EXISTS(SELECT 1 FROM public.hand_private_state WHERE table_id=p_table_id AND hand_number=p_hand_number)
 OR EXISTS(SELECT 1 FROM public.table_hole_cards WHERE table_id=p_table_id AND hand_number=p_hand_number) THEN
 RAISE EXCEPTION 'F06_PREPARED_START_EVIDENCE' USING ERRCODE='55000'; END IF;
 INSERT INTO smarter_private.f06_prepared_hand_cancellations
 (permit_id,tournament_id,generation,table_id,lifecycle,hand_number,custody_id)
 VALUES(p_permit_id,p_tournament_id,p_lease_generation,p_table_id,p_lifecycle,p_hand_number,p_custody_id);
 UPDATE smarter_private.f06_hand_permits SET state='never_started',evidence_id=p_permit_id
 WHERE permit_id=p_permit_id RETURNING * INTO h;
 END IF;
 RETURN to_jsonb(h)||jsonb_build_object('ok',true,'lifecycle',h.lifecycle::text,'hand_number',h.hand_number::text);
END $$;


ALTER FUNCTION public.fn_f06_cancel_prepared_hand(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid, p_lifecycle bigint, p_permit_id uuid, p_hand_number bigint, p_custody_id uuid) OWNER TO postgres;

--
-- TOC entry 8157 (class 1255 OID 28810986)
-- Name: fn_f06_claim_custody(uuid, uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_claim_custody(p_tournament_id uuid, p_lease_generation uuid, p_break_id uuid, p_custody_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE o smarter_private.f06_operations;
BEGIN
 PERFORM smarter_private.f06_lock_break(p_tournament_id,p_lease_generation,p_break_id);
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=p_break_id;
 IF o.custody_id=p_custody_id AND o.custody_generation=p_lease_generation THEN RETURN smarter_private.f06_state(p_break_id); END IF;
 IF o.revision IS DISTINCT FROM p_expected_revision OR o.state='acknowledged' THEN RETURN jsonb_build_object('ok',false,'reason','custody_revision_conflict'); END IF;
 IF p_custody_id IS NULL THEN RAISE EXCEPTION 'F06_CUSTODY_REQUIRED' USING ERRCODE='22023'; END IF;
 UPDATE smarter_private.f06_operations SET custody_id=p_custody_id,custody_generation=p_lease_generation,revision=revision+1 WHERE break_id=p_break_id;
 RETURN smarter_private.f06_state(p_break_id);
END $$;


ALTER FUNCTION public.fn_f06_claim_custody(p_tournament_id uuid, p_lease_generation uuid, p_break_id uuid, p_custody_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- TOC entry 7109 (class 1255 OID 65045505)
-- Name: fn_f06_close_abandoned_manager_transfer(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_close_abandoned_manager_transfer(p_tournament_id uuid, p_transfer_id uuid, p_receipt_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE
  v_actor text := current_setting('app.smarter_data_actor', true);
  v_has_admission boolean;
  t public.tournaments;
  xfer smarter_private.f06_manager_custody_transfers;
  a smarter_private.f06_manager_custody_admissions;
  c smarter_private.f06_manager_custody_completions;
  l public.engine_tournament_leases;
  operations jsonb;
  presence jsonb;
  v_basis text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' OR v_actor IS DISTINCT FROM 'service' THEN
    RAISE EXCEPTION 'F06_TRANSFER_CLOSE_SERVICE_REQUIRED' USING ERRCODE = '42501';
  END IF;
  IF p_tournament_id IS NULL OR p_transfer_id IS NULL OR p_receipt_id IS NULL
     OR length(btrim(COALESCE(p_reason, ''))) < 40 THEN
    RAISE EXCEPTION 'F06_TRANSFER_CLOSE_IDENTITY_REQUIRED' USING ERRCODE = '22023';
  END IF;
  IF public.fn_platform_frozen() THEN
    RAISE EXCEPTION 'PLATFORM_FROZEN: manager-transfer close refused' USING ERRCODE = '55000';
  END IF;

  PERFORM smarter_private.f06_try_lane(p_tournament_id);

  SELECT * INTO t FROM public.tournaments WHERE id = p_tournament_id FOR UPDATE;
  IF t.id IS NULL THEN
    RAISE EXCEPTION 'F06_TRANSFER_CLOSE_EVENT_MISSING' USING ERRCODE = '55000';
  END IF;

  SELECT * INTO xfer FROM smarter_private.f06_manager_custody_transfers
   WHERE transfer_id = p_transfer_id FOR SHARE;
  IF NOT FOUND OR xfer.tournament_id IS DISTINCT FROM p_tournament_id THEN
    RAISE EXCEPTION 'F06_TRANSFER_CLOSE_TRANSFER_CHANGED' USING ERRCODE = '55000';
  END IF;

  -- Idempotent replay: a transfer already completed, by this door or the
  -- ordinary one, is answered from its own stored receipt, never re-run.
  SELECT * INTO c FROM smarter_private.f06_manager_custody_completions WHERE transfer_id = p_transfer_id;
  IF FOUND THEN
    RETURN jsonb_build_object('ok', true, 'replayed', true, 'transfer_id', p_transfer_id,
      'tournament_id', p_tournament_id, 'basis', 'replayed', 'completion', to_jsonb(c));
  END IF;

  IF upper(t.status) IN ('COMPLETED', 'CANCELLED') THEN
    v_basis := 'event_terminal';
  ELSIF upper(t.status) = 'RUNNING' THEN
    SELECT * INTO l FROM public.engine_tournament_leases WHERE tournament_id = p_tournament_id FOR SHARE;
    IF FOUND THEN
      RAISE EXCEPTION 'F06_TRANSFER_CLOSE_EVENT_STILL_RUNNING' USING ERRCODE = '55000';
    END IF;
    IF EXISTS (SELECT 1 FROM smarter_private.f06_hand_permits WHERE tournament_id = p_tournament_id AND state = 'reserved')
       OR EXISTS (SELECT 1 FROM smarter_private.f06_operations WHERE tournament_id = p_tournament_id
                   AND state NOT IN ('acknowledged', 'withdrawn_before_manifest'))
    THEN
      RAISE EXCEPTION 'F06_TRANSFER_CLOSE_RECOVERY_INCOMPLETE' USING ERRCODE = '55000';
    END IF;
    IF EXISTS (SELECT 1 FROM smarter_private.f06_manager_custody_admissions a2 WHERE a2.transfer_id = p_transfer_id) THEN
      RAISE EXCEPTION 'F06_TRANSFER_CLOSE_ALREADY_ADMITTED' USING ERRCODE = '55000';
    END IF;
    v_basis := 'abandoned_unadmitted';
  ELSE
    RAISE EXCEPTION 'F06_TRANSFER_CLOSE_EVENT_STATUS_UNPROVEN' USING ERRCODE = '55000';
  END IF;

  SELECT * INTO a FROM smarter_private.f06_manager_custody_admissions WHERE transfer_id = p_transfer_id;
  v_has_admission := FOUND;
  IF v_has_admission AND (a.tournament_id, a.generation) IS DISTINCT FROM (p_tournament_id, xfer.successor_generation) THEN
    RAISE EXCEPTION 'F06_TRANSFER_CLOSE_ADMISSION_CHANGED' USING ERRCODE = '55000';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(o) ORDER BY o.break_id), '[]') INTO operations
    FROM smarter_private.f06_operations o WHERE o.tournament_id = p_tournament_id;

  presence := jsonb_build_object(
    'kind', 'f06_manager_transfer_administrative_closure',
    'basis', v_basis,
    'receipt_id', p_receipt_id,
    'reason', p_reason,
    'tournament_status', t.status,
    'tournament_ended_at', t.ended_at,
    'closed_at', clock_timestamp());

  IF public.fn_platform_frozen() THEN
    RAISE EXCEPTION 'PLATFORM_FROZEN: manager-transfer close refused' USING ERRCODE = '55000';
  END IF;

  INSERT INTO smarter_private.f06_manager_custody_completions
    (transfer_id, tournament_id, generation, admission, operation_receipts, presence_receipts)
  VALUES (p_transfer_id, p_tournament_id, xfer.successor_generation,
          CASE WHEN v_has_admission THEN to_jsonb(a) ELSE 'null'::jsonb END,
          operations, presence)
  RETURNING * INTO c;

  RETURN jsonb_build_object('ok', true, 'transfer_id', p_transfer_id, 'tournament_id', p_tournament_id,
    'basis', v_basis, 'completion', to_jsonb(c));
END
$$;


ALTER FUNCTION public.fn_f06_close_abandoned_manager_transfer(p_tournament_id uuid, p_transfer_id uuid, p_receipt_id uuid, p_reason text) OWNER TO postgres;

--
-- TOC entry 7368 (class 1255 OID 28810985)
-- Name: fn_f06_close_break(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_close_break(p_tournament_id uuid, p_lease_generation uuid, p_break_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE o smarter_private.f06_operations;v jsonb;
BEGIN
 PERFORM smarter_private.f06_lock_break(p_tournament_id,p_lease_generation,p_break_id);
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=p_break_id;
 IF o.state IN ('close_confirmed','acknowledged') THEN RETURN smarter_private.f06_state(p_break_id); END IF;
 IF o.state<>'begun' OR EXISTS(SELECT 1 FROM smarter_private.f06_attempts WHERE break_id=p_break_id AND state='active')
 OR EXISTS(SELECT 1 FROM smarter_private.f06_members m WHERE break_id=p_break_id AND NOT EXISTS(SELECT 1 FROM smarter_private.f06_attempts a WHERE a.break_id=m.break_id AND a.user_id=m.user_id AND a.state='winner')) THEN
 RETURN jsonb_build_object('ok',false,'reason','members_unresolved'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tables WHERE id=o.source_table_id AND f06_lifecycle=o.lifecycle) THEN RAISE EXCEPTION 'F06_LIFECYCLE_CHANGED' USING ERRCODE='55000'; END IF;
 v:=public.fn_close_empty_tournament_table(p_tournament_id,o.source_table_id,p_lease_generation);
 IF (v->>'ok')::boolean IS DISTINCT FROM true THEN RETURN v; END IF;
 UPDATE smarter_private.f06_operations SET state='close_confirmed',close_receipt=v WHERE break_id=p_break_id;
 RETURN smarter_private.f06_state(p_break_id);
END $$;


ALTER FUNCTION public.fn_f06_close_break(p_tournament_id uuid, p_lease_generation uuid, p_break_id uuid) OWNER TO postgres;

--
-- TOC entry 7212 (class 1255 OID 47519215)
-- Name: fn_f06_complete_mixed_manager_custody(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_complete_mixed_manager_custody(p_tournament_id uuid, p_lease_generation uuid, p_transfer_id uuid, p_expected jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE a jsonb; prior smarter_private.f06_manager_custody_transfers; c smarter_private.f06_manager_custody_completions; operations jsonb; x jsonb; ids uuid[]; users uuid[]; u uuid; presence_receipts jsonb;
BEGIN
 a:=smarter_private.f06_mixed_current_admission(p_tournament_id,p_lease_generation,p_transfer_id);
 PERFORM smarter_private.f06_try_lane(p_tournament_id);
 SELECT * INTO prior FROM smarter_private.f06_manager_custody_transfers WHERE transfer_id=p_transfer_id FOR SHARE;
 IF to_jsonb(prior) IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'F06_MIXED_COMPLETION_CHANGED'; END IF;
 SELECT * INTO c FROM smarter_private.f06_manager_custody_completions WHERE transfer_id=p_transfer_id;
 IF NOT FOUND THEN
 SELECT COALESCE(array_agg(id ORDER BY id),'{}') INTO ids FROM public.tables WHERE tournament_id=p_tournament_id;
 IF to_jsonb(ids) IS DISTINCT FROM (SELECT jsonb_agg(e->'id' ORDER BY e->>'id') FROM jsonb_array_elements(prior.canonical_proof->'tables') e)
 THEN RAISE EXCEPTION 'F06_MIXED_TABLE_SET_CHANGED'; END IF;
 SELECT COALESCE(array_agg(DISTINCT user_id ORDER BY user_id),'{}') INTO users FROM public.table_seats WHERE table_id=ANY(ids) AND user_id IS NOT NULL;
 FOREACH u IN ARRAY users LOOP IF NOT pg_try_advisory_xact_lock(hashtextextended('table_cap:'||u::text,0)) THEN RAISE EXCEPTION 'F06_RETRY_CANONICAL_LANE' USING ERRCODE='55P03'; END IF; END LOOP;
 PERFORM 1 FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE;
 PERFORM 1 FROM public.tournament_players WHERE tournament_id=p_tournament_id ORDER BY user_id FOR UPDATE;
 PERFORM 1 FROM public.tables WHERE tournament_id=p_tournament_id ORDER BY id FOR UPDATE;
 PERFORM s.id FROM public.table_seats s WHERE s.table_id=ANY(ids) ORDER BY s.id FOR UPDATE;
 PERFORM 1 FROM smarter_private.f06_operations WHERE tournament_id=p_tournament_id ORDER BY break_id FOR UPDATE;
 PERFORM 1 FROM smarter_private.f06_members WHERE break_id IN(SELECT break_id FROM smarter_private.f06_operations WHERE tournament_id=p_tournament_id) ORDER BY break_id,user_id FOR UPDATE;
 PERFORM 1 FROM smarter_private.f06_attempts WHERE break_id IN(SELECT break_id FROM smarter_private.f06_operations WHERE tournament_id=p_tournament_id) ORDER BY request_id FOR UPDATE;
 PERFORM 1 FROM public.tournament_seat_move_receipts WHERE tournament_id=p_tournament_id ORDER BY request_id FOR SHARE;
 IF EXISTS(SELECT 1 FROM smarter_private.f06_operations WHERE tournament_id=p_tournament_id AND state NOT IN('acknowledged','withdrawn_before_manifest'))
 OR EXISTS(SELECT 1 FROM smarter_private.f06_hand_permits WHERE tournament_id=p_tournament_id AND state='reserved')
 OR EXISTS(SELECT 1 FROM smarter_private.f06_dispatch d JOIN smarter_private.f06_attempts m USING(request_id) JOIN smarter_private.f06_operations o USING(break_id) WHERE o.tournament_id=p_tournament_id)
 THEN RAISE EXCEPTION 'F06_MIXED_RECOVERY_INCOMPLETE'; END IF;
 FOR x IN SELECT * FROM jsonb_array_elements(prior.canonical_proof->'operations') LOOP
 IF NOT EXISTS(SELECT 1 FROM smarter_private.f06_operations o WHERE o.break_id=(x->>'break_id')::uuid AND o.tournament_id=p_tournament_id
 AND o.source_table_id=(x->>'source_table_id')::uuid AND o.lifecycle=(x->>'lifecycle')::bigint AND
 (o.state='acknowledged' AND o.close_receipt IS NOT NULL OR o.state='withdrawn_before_manifest' AND EXISTS(SELECT 1 FROM smarter_private.f06_no_start_continuations n WHERE n.break_id=o.break_id))) THEN
 RAISE EXCEPTION 'F06_MIXED_ORIGINAL_OUTCOME_UNPROVEN'; END IF; END LOOP;
 FOR x IN SELECT * FROM jsonb_array_elements(prior.local_proof->'pending_moves') LOOP
 IF NOT EXISTS(SELECT 1 FROM smarter_private.f06_attempts a JOIN smarter_private.f06_operations o USING(break_id)
 WHERE o.tournament_id=p_tournament_id AND a.request_id=(x->>0)::uuid AND a.state IN('winner','fenced')
 AND EXISTS(SELECT 1 FROM smarter_private.f06_members m JOIN smarter_private.f06_attempts winner ON winner.break_id=m.break_id AND winner.user_id=m.user_id
 WHERE m.break_id=a.break_id AND m.user_id=a.user_id AND winner.state='winner' AND winner.receipt IS NOT NULL))
 THEN RAISE EXCEPTION 'F06_MIXED_PENDING_REQUEST_UNRESOLVED'; END IF;
 END LOOP;
 FOR x IN SELECT * FROM jsonb_array_elements(prior.local_proof->'parks') LOOP
 IF NOT EXISTS(SELECT 1 FROM smarter_private.f06_operations o WHERE o.tournament_id=p_tournament_id
 AND o.break_id=(x#>>'{1,breakId}')::uuid AND o.source_table_id=(x->>0)::uuid
 AND o.lifecycle=(x#>>'{1,lifecycle}')::bigint AND o.boundary_id=(x#>>'{1,boundaryId}')::uuid
 AND o.state IN('acknowledged','withdrawn_before_manifest')) THEN RAISE EXCEPTION 'F06_MIXED_PENDING_PARK_UNRESOLVED'; END IF;
 END LOOP;
 FOR x IN SELECT * FROM jsonb_array_elements(prior.local_proof->'custody_ids') LOOP
 IF NOT EXISTS(SELECT 1 FROM smarter_private.f06_operations o WHERE o.tournament_id=p_tournament_id
 AND o.break_id=(x->>0)::uuid AND o.custody_id=(x->>1)::uuid AND o.state='acknowledged')
 THEN RAISE EXCEPTION 'F06_MIXED_PENDING_CUSTODY_UNRESOLVED'; END IF;
 END LOOP;
 FOR x IN SELECT * FROM jsonb_array_elements(prior.local_proof->'cleanup_kinds') LOOP
 IF NOT EXISTS(SELECT 1 FROM smarter_private.f06_operations o WHERE o.tournament_id=p_tournament_id
 AND o.break_id=(x->>0)::uuid AND o.cleanup_kind=x->>1 AND o.state='acknowledged')
 THEN RAISE EXCEPTION 'F06_MIXED_PENDING_ACK_UNRESOLVED'; END IF;
 END LOOP;
 -- Pending begin input and first-send intents bind immutable original manifests.
 FOR x IN SELECT value FROM jsonb_array_elements(prior.local_proof->'begins')
 UNION ALL SELECT jsonb_build_array(split_part(intent_key,':',2),payload) FROM smarter_private.f06_manager_custody_intents
 WHERE transfer_id=p_transfer_id AND intent_key LIKE 'begin:%' LOOP
 IF NOT EXISTS(SELECT 1 FROM smarter_private.f06_operations o WHERE o.tournament_id=p_tournament_id AND o.break_id=(x->>0)::uuid
 AND o.manifest=(SELECT jsonb_agg(m ORDER BY m->>'user_id') FROM jsonb_array_elements(x->1) m) AND o.state='acknowledged')
 THEN RAISE EXCEPTION 'F06_MIXED_PENDING_BEGIN_UNRESOLVED'; END IF;
 END LOOP;
 FOR x IN SELECT value->1 FROM jsonb_array_elements(prior.local_proof->'amendments')
 UNION ALL SELECT payload FROM smarter_private.f06_manager_custody_intents WHERE transfer_id=p_transfer_id AND intent_key LIKE 'amend:%' LOOP
 IF NOT EXISTS(SELECT 1 FROM smarter_private.f06_attempts attempt WHERE attempt.break_id=(x->>'breakId')::uuid AND attempt.user_id=(x->>'userId')::uuid
 AND ((attempt.amendment_id=(x->>'amendmentId')::uuid AND attempt.request_id=(x->>'newRequestId')::uuid
 AND attempt.predecessor=(x->>'expectedRequestId')::uuid AND attempt.amendment_payload=jsonb_build_object('break',x->>'breakId','user',x->>'userId','predecessor',x->>'expectedRequestId','new',x->>'newRequestId','destination',x->>'destinationTableId','seat',(x->>'destinationSeatNumber')::integer,'reason',x->>'reason'))
 OR (attempt.request_id=(x->>'expectedRequestId')::uuid AND attempt.state IN('winner','fenced'))))
 THEN RAISE EXCEPTION 'F06_MIXED_PENDING_AMENDMENT_UNRESOLVED'; END IF;
 END LOOP;
 FOR x IN SELECT jsonb_build_array(split_part(intent_key,':',2),payload->>'custodyId') FROM smarter_private.f06_manager_custody_intents WHERE transfer_id=p_transfer_id AND intent_key LIKE 'custody:%' LOOP
 IF NOT EXISTS(SELECT 1 FROM smarter_private.f06_operations o WHERE o.tournament_id=p_tournament_id AND o.break_id=(x->>0)::uuid
 AND o.custody_id=(x->>1)::uuid AND o.state='acknowledged') THEN RAISE EXCEPTION 'F06_MIXED_PENDING_CUSTODY_UNRESOLVED'; END IF;
 END LOOP;
 SELECT COALESCE(jsonb_agg(to_jsonb(o) ORDER BY o.break_id),'[]') INTO operations FROM smarter_private.f06_operations o WHERE tournament_id=p_tournament_id;
 PERFORM 1 FROM public.engine_presence_parked WHERE table_id=ANY(ids) ORDER BY table_id FOR UPDATE;
 presence_receipts:=smarter_private.f06_mixed_adopt_presence(p_tournament_id,prior.local_proof);
 INSERT INTO smarter_private.f06_manager_custody_completions(transfer_id,tournament_id,generation,admission,operation_receipts,presence_receipts)
 VALUES(p_transfer_id,p_tournament_id,p_lease_generation,a,operations,presence_receipts) RETURNING * INTO c;
 END IF;
 RETURN jsonb_build_object('ok',true,'transfer_id',p_transfer_id,'tournament_id',p_tournament_id,'lease_generation',p_lease_generation,'completion',to_jsonb(c));
END $$;


ALTER FUNCTION public.fn_f06_complete_mixed_manager_custody(p_tournament_id uuid, p_lease_generation uuid, p_transfer_id uuid, p_expected jsonb) OWNER TO postgres;

--
-- TOC entry 3513 (class 1255 OID 37139755)
-- Name: fn_f06_continue_no_start_last_table(uuid, uuid, uuid, bigint, uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_continue_no_start_last_table(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid, p_lifecycle bigint, p_break_id uuid, p_park_custody_id uuid, p_park_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE h smarter_private.f06_hand_permits; o smarter_private.f06_operations;
 receipt smarter_private.f06_no_start_continuations; a public.hand_atomic_commits;
 history public.hand_history; users uuid[]; roster jsonb; prior jsonb;
BEGIN
 IF p_table_id IS NULL OR p_lifecycle IS NULL OR p_lifecycle<1 OR p_break_id IS NULL
 OR p_park_custody_id IS NULL OR p_park_revision IS NULL OR p_park_revision<1 THEN
 RAISE EXCEPTION 'F06_CONTINUATION_IDENTITY' USING ERRCODE='22023'; END IF;
 -- The authenticated current manager owns both original and successor calls.
 -- Its exact source dealer must have positively stopped/joined under registry
 -- custody. The durable original never-started witness is never reconstructed.
 SELECT array_agg(user_id ORDER BY user_id) INTO users FROM public.table_seats
 WHERE table_id=p_table_id AND left_at IS NULL;
 PERFORM smarter_private.f06_prefix(p_tournament_id,p_lease_generation,COALESCE(users,'{}'),ARRAY[p_table_id]);
 SELECT * INTO receipt FROM smarter_private.f06_no_start_continuations WHERE break_id=p_break_id;
 IF FOUND THEN
 IF (receipt.tournament_id,receipt.current_generation,receipt.table_id,receipt.lifecycle,
 (receipt.park->>'custody_id')::uuid,(receipt.park->>'revision')::bigint) IS DISTINCT FROM
 (p_tournament_id,p_lease_generation,p_table_id,p_lifecycle,p_park_custody_id,p_park_revision) THEN
 RAISE EXCEPTION 'F06_CONTINUATION_CHANGED_REPLAY' USING ERRCODE='22023'; END IF;
 ELSE
 IF public.fn_platform_frozen() THEN RAISE EXCEPTION 'PLATFORM_FROZEN: continuation refused' USING ERRCODE='55000'; END IF;
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=p_break_id FOR UPDATE;
 IF NOT FOUND OR (o.tournament_id,o.source_table_id,o.lifecycle,o.state,o.custody_id,o.revision)
 IS DISTINCT FROM (p_tournament_id,p_table_id,p_lifecycle,'park_requested'::text,p_park_custody_id,p_park_revision)
 OR o.custody_generation IS NULL
 -- A PARK THE ABANDONED-GENERATION DOOR LEFT (2026-09-27). The door closes a
 -- dead generation's never-started hand as never_started and leaves that
 -- generation's own pre-manifest park for the successor. On the event's last
 -- open table this continuation is the only exit. The park's custody may name
 -- a successor generation that has itself since died (41eb379e: 3871b71a
 -- claimed it at 16:25, then engine e6b9dc5d adopted the event as f798e8e0 and
 -- the park still names 3871b71a), so the caller is not required to be that
 -- generation. The caller is the event's LIVE lease holder (f06_prefix above
 -- fences every other generation), it is not the origin the door closed, and
 -- no other generation holds a lease; the door's receipt must name this park.
 OR (o.origin_generation IS DISTINCT FROM o.custody_generation
     AND NOT (p_lease_generation IS DISTINCT FROM o.origin_generation
              AND NOT EXISTS(SELECT 1 FROM public.engine_tournament_leases l
                              WHERE l.tournament_id=p_tournament_id
                                AND l.lease_generation IS DISTINCT FROM p_lease_generation)
              AND EXISTS(SELECT 1 FROM smarter_private.f06_generation_aborts g
                          WHERE g.tournament_id=p_tournament_id AND g.generation=o.origin_generation
                            AND g.outcome='aborted_unsettled'
                            AND g.expected->'foreign_parks_left' ? o.break_id::text)))
 OR o.manifest IS NOT NULL OR o.close_receipt IS NOT NULL OR o.cleanup_kind IS NOT NULL
 OR o.abort_receipt_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM smarter_private.f06_members WHERE break_id=o.break_id)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_attempts WHERE break_id=o.break_id)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_operations WHERE tournament_id=p_tournament_id
 AND break_id<>p_break_id AND state NOT IN ('acknowledged','withdrawn_before_manifest')) THEN
 RAISE EXCEPTION 'F06_CONTINUATION_EXACT_PREMANIFEST_PARK' USING ERRCODE='55000'; END IF;
 SELECT * INTO h FROM smarter_private.f06_hand_permits WHERE table_id=p_table_id
 ORDER BY hand_number DESC LIMIT 1 FOR UPDATE;
 IF NOT FOUND OR (h.tournament_id,h.lifecycle,h.generation,h.state) IS DISTINCT FROM
 (p_tournament_id,p_lifecycle,o.origin_generation,'never_started'::text)
 -- Its never-started witness is the original's own cancellation (evidence =
 -- the park's custody) or, for a park the door left, the door's receipt that
 -- names this permit as never started and this park as left.
 OR NOT (h.evidence_id IS NOT DISTINCT FROM o.custody_id
         OR (o.origin_generation IS DISTINCT FROM o.custody_generation
             AND EXISTS(SELECT 1 FROM smarter_private.f06_generation_aborts g
                         WHERE g.receipt_id=h.evidence_id AND g.tournament_id=p_tournament_id
                           AND g.generation=h.generation AND g.outcome='aborted_unsettled'
                           AND g.expected->'foreign_parks_left' ? o.break_id::text
                           AND EXISTS(SELECT 1 FROM jsonb_array_elements(g.expected->'never_started') ns
                                       WHERE ns#>>'{permit,permit_id}'=h.permit_id::text))))
 OR EXISTS(SELECT 1 FROM smarter_private.f06_hand_permits WHERE tournament_id=p_tournament_id AND state='reserved') THEN
 RAISE EXCEPTION 'F06_CONTINUATION_POSITIVE_ORIGINAL_REQUIRED' USING ERRCODE='55000'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('f06:hand:'||h.permit_id::text,0)) THEN
 RAISE EXCEPTION 'F06_HAND_DISPATCH_BUSY' USING ERRCODE='55P03'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tournaments WHERE id=p_tournament_id AND status='RUNNING'
 AND format_contract IN ('mtt-v1','mtt-v2','sng-v1','spin-v1'))
 OR (SELECT count(*) FROM public.tables WHERE tournament_id=p_tournament_id AND lower(status)<>'closed'
 AND NOT COALESCE(is_deleted,false))<>1
 OR NOT EXISTS(SELECT 1 FROM public.tables WHERE id=p_table_id AND tournament_id=p_tournament_id
 AND f06_lifecycle=p_lifecycle AND lower(status) IN ('waiting','running') AND NOT COALESCE(is_deleted,false)) THEN
 RAISE EXCEPTION 'F06_CONTINUATION_LAST_TABLE_REQUIRED' USING ERRCODE='55000'; END IF;
 -- The prefix's exclusive tournament lane serializes every real admission.
 -- Recheck the complete roster rather than trusting an earlier count or hint.
 IF EXISTS(SELECT 1 FROM public.table_seats s LEFT JOIN public.tournament_players p
 ON p.tournament_id=p_tournament_id AND p.user_id=s.user_id AND p.table_id=s.table_id
 AND p.seat_number=s.seat_number AND p.status='playing'
 WHERE s.table_id=p_table_id AND s.left_at IS NULL AND (p.id IS NULL OR s.occupancy_id IS NULL
 OR s.joined_at IS NULL OR s.terminal_closed_at IS NOT NULL OR s.stack IS DISTINCT FROM p.chips::numeric
 OR s.stack IS NULL OR s.stack<=0 OR s.stack::text IN ('NaN','Infinity','-Infinity')))
 OR EXISTS(SELECT 1 FROM public.tournament_players p WHERE p.tournament_id=p_tournament_id AND p.status='playing'
 AND NOT EXISTS(SELECT 1 FROM public.table_seats s WHERE s.table_id=p_table_id AND s.table_id=p.table_id
 AND s.user_id=p.user_id AND s.seat_number=p.seat_number AND s.left_at IS NULL)) THEN
 RAISE EXCEPTION 'F06_CONTINUATION_ROSTER_CHANGED' USING ERRCODE='55000'; END IF;
 SELECT jsonb_agg(jsonb_build_object('seat_id',s.id,'occupancy_id',s.occupancy_id,'registration_id',p.id,
 'user_id',s.user_id,'joined_at',s.joined_at,'table_id',s.table_id,'seat_number',s.seat_number,'stack',s.stack,'chips',p.chips) ORDER BY s.user_id)
 INTO roster FROM public.table_seats s JOIN public.tournament_players p
 ON p.tournament_id=p_tournament_id AND p.user_id=s.user_id AND p.table_id=s.table_id AND p.seat_number=s.seat_number AND p.status='playing'
 WHERE s.table_id=p_table_id AND s.left_at IS NULL;
 IF jsonb_array_length(roster) NOT BETWEEN 2 AND 10 OR roster IS NULL
 OR (SELECT count(DISTINCT x->>'user_id') FROM jsonb_array_elements(roster) x)<>jsonb_array_length(roster)
 OR EXISTS(SELECT 1 FROM public.hand_atomic_commits WHERE table_id=p_table_id AND hand_number>=h.hand_number)
 OR EXISTS(SELECT 1 FROM public.hand_history WHERE table_id=p_table_id AND hand_number>=h.hand_number)
 OR EXISTS(SELECT 1 FROM public.hand_private_state WHERE table_id=p_table_id AND hand_number>=h.hand_number)
 OR EXISTS(SELECT 1 FROM public.table_hole_cards WHERE table_id=p_table_id AND hand_number>=h.hand_number)
 OR EXISTS(SELECT 1 FROM public.hand_state_snapshots WHERE table_id=p_table_id AND NOT is_complete)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_hand_dispatch WHERE permit_id=h.permit_id) THEN
 RAISE EXCEPTION 'F06_CONTINUATION_STARTED_OR_ROSTER_CHANGED' USING ERRCODE='55000'; END IF;
 SELECT * INTO a FROM public.hand_atomic_commits WHERE table_id=p_table_id ORDER BY hand_number DESC LIMIT 1;
 IF NOT FOUND THEN
 -- A last table that never committed a hand has no prior boundary to prove
 -- its chairs against. Its boundary is its entries: the table never dealt,
 -- and every chair holds exactly the entry its registration was granted.
 prior:=smarter_private.f06_no_start_first_hand_stacks(h.permit_id,roster);
 ELSE
 SELECT * INTO history FROM public.hand_history WHERE id=a.hand_id AND table_id=p_table_id AND hand_number=a.hand_number;
 IF NOT FOUND THEN RAISE EXCEPTION 'F06_CONTINUATION_PRIOR_HISTORY_REQUIRED' USING ERRCODE='55000'; END IF;
 prior:=jsonb_build_object('hand_number',a.hand_number,'atomic_hand_id',a.hand_id,
 'stack_hand_id',a.stack_result->>'hand_id','atomic_hash',md5(to_jsonb(a)::text),'history_hash',md5(to_jsonb(history)::text),
 'payload_hash',a.payload_hash,'post_commit_payload_hash',a.post_commit_payload_hash,
 'post_commit_request_hash',a.post_commit_request_hash,'post_commit_completed_at',a.post_commit_completed_at);
 prior:=smarter_private.f06_no_start_prior_committed_stacks(h.permit_id,prior,roster);
 END IF;
 INSERT INTO smarter_private.f06_no_start_continuations
 (break_id,permit_id,tournament_id,table_id,lifecycle,hand_number,original_generation,current_generation,park,permit,roster,prior_committed)
 VALUES(o.break_id,h.permit_id,p_tournament_id,p_table_id,p_lifecycle,h.hand_number,h.generation,p_lease_generation,to_jsonb(o),to_jsonb(h),roster,prior)
 RETURNING * INTO receipt;
 -- The legacy column names the disposition receipt. The immutable hand outcome
 -- remains never_started; this is neither an abort nor a chip compensation.
 UPDATE smarter_private.f06_operations SET state='withdrawn_before_manifest',abort_receipt_id=receipt.receipt_id WHERE break_id=o.break_id;
 END IF;
 RETURN jsonb_build_object('ok',true,'state','continued_never_started','receipt_id',receipt.receipt_id,
 'tournament_id',receipt.tournament_id,'table_id',receipt.table_id,'lifecycle',receipt.lifecycle::text,
 'break_id',receipt.break_id,'park_custody_id',receipt.park->>'custody_id','park_revision',receipt.park->>'revision',
 'lease_generation',receipt.current_generation,'original_generation',receipt.original_generation,
 'permit_id',receipt.permit_id,'hand_number',receipt.hand_number::text,'credit',0);
END $$;


ALTER FUNCTION public.fn_f06_continue_no_start_last_table(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid, p_lifecycle bigint, p_break_id uuid, p_park_custody_id uuid, p_park_revision bigint) OWNER TO postgres;

--
-- TOC entry 8632 (class 1255 OID 28810988)
-- Name: fn_f06_discover_breaks(uuid, uuid, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_discover_breaks(p_tournament_id uuid, p_lease_generation uuid, p_expected_cursor_revision bigint, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE c smarter_private.f06_cursors;items jsonb;last_id bigint;wrapped boolean:=false;
BEGIN
 IF p_limit NOT BETWEEN 1 AND 32 OR p_limit IS NULL THEN RAISE EXCEPTION 'F06_PAGE_SIZE' USING ERRCODE='22023'; END IF;
 PERFORM smarter_private.f06_prefix(p_tournament_id,p_lease_generation,'{}','{}');
 INSERT INTO smarter_private.f06_cursors(tournament_id) VALUES(p_tournament_id) ON CONFLICT DO NOTHING;
 SELECT * INTO c FROM smarter_private.f06_cursors WHERE tournament_id=p_tournament_id FOR UPDATE;
 IF c.revision IS DISTINCT FROM p_expected_cursor_revision THEN RETURN jsonb_build_object('ok',false,'reason','cursor_revision_conflict','cursor_revision',c.revision::text,'wrapped',false,'operations','[]'::jsonb); END IF;
 IF NOT EXISTS(SELECT 1 FROM smarter_private.f06_operations WHERE tournament_id=p_tournament_id AND state NOT IN ('acknowledged','withdrawn_before_manifest') AND ordinal>c.ordinal) THEN c.ordinal:=0;wrapped:=true; END IF;
 SELECT jsonb_agg(smarter_private.f06_state(q.break_id) ORDER BY q.ordinal),max(q.ordinal) INTO items,last_id FROM
 (SELECT break_id,ordinal FROM smarter_private.f06_operations WHERE tournament_id=p_tournament_id AND state NOT IN ('acknowledged','withdrawn_before_manifest') AND ordinal>c.ordinal ORDER BY ordinal LIMIT p_limit) q;
 UPDATE smarter_private.f06_cursors SET ordinal=COALESCE(last_id,0),revision=revision+1 WHERE tournament_id=p_tournament_id;
 RETURN jsonb_build_object('ok',true,'reason',NULL,'cursor_revision',(c.revision+1)::text,'wrapped',wrapped,'operations',COALESCE(items,'[]'::jsonb));
END $$;


ALTER FUNCTION public.fn_f06_discover_breaks(p_tournament_id uuid, p_lease_generation uuid, p_expected_cursor_revision bigint, p_limit integer) OWNER TO postgres;

--
-- TOC entry 9639 (class 1255 OID 101271939)
-- Name: fn_f06_dispose_dead_origin_originals(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_dispose_dead_origin_originals(p_tournament_id uuid, p_lease_generation uuid, p_transfer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE
  xfer smarter_private.f06_manager_custody_transfers;
  r jsonb;
BEGIN
  -- The caller is the tournament manager holding a LIVE protocol-2 lease for
  -- this event at exactly the transfer's successor generation.
  PERFORM smarter_private.f06_authority(p_tournament_id, p_lease_generation);
  SELECT * INTO xfer FROM smarter_private.f06_manager_custody_transfers
   WHERE transfer_id = p_transfer_id;
  IF NOT FOUND OR xfer.tournament_id IS DISTINCT FROM p_tournament_id
     OR xfer.successor_generation IS DISTINCT FROM p_lease_generation THEN
    RAISE EXCEPTION 'F06_MIXED_SUCCESSOR_CHANGED' USING ERRCODE = '55000';
  END IF;
  r := smarter_private.f06_dispose_dead_origin(p_transfer_id);
  PERFORM smarter_private.f06_authority(p_tournament_id, p_lease_generation, false);
  RETURN r;
END
$$;


ALTER FUNCTION public.fn_f06_dispose_dead_origin_originals(p_tournament_id uuid, p_lease_generation uuid, p_transfer_id uuid) OWNER TO postgres;

--
-- TOC entry 8601 (class 1255 OID 47519222)
-- Name: fn_f06_find_mixed_manager_custody(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_find_mixed_manager_custody(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE receipt smarter_private.f06_manager_custody_transfers;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR p_tournament_id IS NULL THEN RAISE EXCEPTION 'F06_MIXED_SERVICE_REQUIRED' USING ERRCODE='42501'; END IF;
 IF (SELECT count(*) FROM smarter_private.f06_manager_custody_transfers WHERE tournament_id=p_tournament_id AND NOT EXISTS(SELECT 1 FROM smarter_private.f06_manager_custody_completions c WHERE c.transfer_id=f06_manager_custody_transfers.transfer_id))>1 THEN
 RAISE EXCEPTION 'F06_MIXED_TRANSFER_SELECTION_UNPROVEN'; END IF;
 SELECT * INTO receipt FROM smarter_private.f06_manager_custody_transfers WHERE tournament_id=p_tournament_id AND NOT EXISTS(SELECT 1 FROM smarter_private.f06_manager_custody_completions c WHERE c.transfer_id=f06_manager_custody_transfers.transfer_id);
 RETURN jsonb_build_object('ok',true,'tournament_id',p_tournament_id,'receipt',CASE WHEN FOUND THEN to_jsonb(receipt) ELSE NULL END);
END $$;


ALTER FUNCTION public.fn_f06_find_mixed_manager_custody(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 7711 (class 1255 OID 28810995)
-- Name: fn_f06_finish_hand(uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_finish_hand(p_tournament_id uuid, p_lease_generation uuid, p_permit_id uuid, p_outcome text, p_evidence_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE h smarter_private.f06_hand_permits;
BEGIN
 SELECT * INTO h FROM smarter_private.f06_hand_permits WHERE permit_id=p_permit_id AND tournament_id=p_tournament_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'F06_UNKNOWN_PERMIT' USING ERRCODE='22023'; END IF;
 /* A TABLE'S HAND DOES NOT WAIT FOR ITS SIBLING TABLES (2026-10-03). An
    accepted finish only records the committed hand of this table: the
    shared table lane. Every other outcome asserts that nothing started,
    which only the exclusive lane can prove, so it keeps f06_prefix. */
 IF p_outcome='accepted' THEN
 PERFORM public.fn_ca_f06_share_table_lane(p_tournament_id,p_lease_generation,h.table_id);
 ELSE
 PERFORM smarter_private.f06_prefix(p_tournament_id,p_lease_generation,'{}',ARRAY[h.table_id]);
 END IF;
 SELECT * INTO h FROM smarter_private.f06_hand_permits WHERE permit_id=p_permit_id FOR UPDATE;
 IF h.state<>'reserved' THEN
 IF h.state IS DISTINCT FROM p_outcome OR h.evidence_id IS DISTINCT FROM p_evidence_id THEN RAISE EXCEPTION 'F06_CHANGED_HAND_OUTCOME' USING ERRCODE='22023'; END IF;
 ELSE
 IF p_outcome='accepted' THEN
 IF NOT EXISTS(SELECT 1 FROM public.hand_atomic_commits c WHERE c.table_id=h.table_id AND c.hand_number=h.hand_number AND c.hand_id=p_evidence_id AND c.post_commit_completed_at IS NOT NULL) THEN
 RAISE EXCEPTION 'F06_HAND_EVIDENCE_REQUIRED' USING ERRCODE='55000'; END IF;
 ELSIF p_outcome='never_started' THEN
 -- Lease must have drained the exact original custody under its held both-map
 -- reservation before claiming this park's new custody receipt. A successor
 -- generation is not evidence that the original dealer never started.
 IF h.generation IS DISTINCT FROM p_lease_generation OR NOT EXISTS(SELECT 1 FROM smarter_private.f06_operations o
 WHERE o.source_table_id=h.table_id AND o.lifecycle=h.lifecycle AND o.state='park_requested' AND o.custody_id=p_evidence_id
 AND o.custody_generation=p_lease_generation AND o.revision>0)
 OR EXISTS(SELECT 1 FROM public.hand_atomic_commits WHERE table_id=h.table_id AND hand_number=h.hand_number)
 OR EXISTS(SELECT 1 FROM public.hand_history WHERE table_id=h.table_id AND hand_number=h.hand_number)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_hand_dispatch WHERE permit_id=p_permit_id) THEN
 RAISE EXCEPTION 'F06_EXACT_QUIESCENT_CUSTODY_REQUIRED' USING ERRCODE='55000'; END IF;
 ELSE RAISE EXCEPTION 'F06_HAND_OUTCOME' USING ERRCODE='22023'; END IF;
 UPDATE smarter_private.f06_hand_permits SET state=p_outcome,evidence_id=p_evidence_id WHERE permit_id=p_permit_id RETURNING * INTO h;
 END IF;
 RETURN to_jsonb(h)||jsonb_build_object('ok',true,'lifecycle',h.lifecycle::text,'hand_number',h.hand_number::text);
END $$;


ALTER FUNCTION public.fn_f06_finish_hand(p_tournament_id uuid, p_lease_generation uuid, p_permit_id uuid, p_outcome text, p_evidence_id uuid) OWNER TO postgres;

--
-- TOC entry 6800 (class 1255 OID 28811012)
-- Name: fn_f06_finish_original_no_start(uuid, uuid, uuid, bigint, uuid, bigint, uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_finish_original_no_start(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid, p_lifecycle bigint, p_permit_id uuid, p_hand_number bigint, p_original_custody_id uuid, p_break_id uuid, p_park_custody_id uuid, p_park_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE h smarter_private.f06_hand_permits; o smarter_private.f06_operations;
BEGIN
 IF p_table_id IS NULL OR p_lifecycle IS NULL OR p_permit_id IS NULL OR p_hand_number IS NULL
 OR p_hand_number<1 OR p_original_custody_id IS NULL OR p_break_id IS NULL
 OR p_park_custody_id IS NULL OR p_park_revision IS NULL OR p_park_revision<1 THEN
 RAISE EXCEPTION 'F06_ORIGINAL_DISPOSITION_IDENTITY' USING ERRCODE='22023'; END IF;
 -- Same prefix as BEGIN/finish: lease, tournament lane, physical table/seat rows.
 -- This serializes the absence decision against a late original BEGIN.
 PERFORM smarter_private.f06_prefix(p_tournament_id,p_lease_generation,'{}',ARRAY[p_table_id]);
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=p_break_id FOR UPDATE;
 IF NOT FOUND OR (o.tournament_id,o.source_table_id,o.lifecycle,o.origin_generation,o.state,
 o.custody_id,o.custody_generation,o.revision) IS DISTINCT FROM
 (p_tournament_id,p_table_id,p_lifecycle,p_lease_generation,'park_requested'::text,
 p_park_custody_id,p_lease_generation,p_park_revision) THEN
 RAISE EXCEPTION 'F06_EXACT_ORIGINAL_PARK_REQUIRED' USING ERRCODE='55000'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tables tb JOIN public.tournaments t ON t.id=tb.tournament_id
 WHERE tb.id=p_table_id AND tb.tournament_id=p_tournament_id AND tb.f06_lifecycle=p_lifecycle
 AND upper(t.status)='RUNNING' AND lower(tb.status)<>'closed' AND NOT COALESCE(tb.is_deleted,false)) THEN
 RAISE EXCEPTION 'F06_HAND_LIFECYCLE' USING ERRCODE='55000'; END IF;
 SELECT * INTO h FROM smarter_private.f06_hand_permits WHERE permit_id=p_permit_id FOR UPDATE;
 IF FOUND THEN
 IF (h.tournament_id,h.table_id,h.lifecycle,h.hand_number,h.custody_id,h.generation) IS DISTINCT FROM
 (p_tournament_id,p_table_id,p_lifecycle,p_hand_number,p_original_custody_id,p_lease_generation) THEN
 RAISE EXCEPTION 'F06_CHANGED_HAND_PERMIT' USING ERRCODE='22023'; END IF;
 -- Existing reserved or exact completed receipt uses the already accepted finisher.
 RETURN public.fn_f06_finish_hand(p_tournament_id,p_lease_generation,p_permit_id,'never_started',p_park_custody_id);
 END IF;
 IF EXISTS(SELECT 1 FROM smarter_private.f06_hand_permits WHERE table_id=p_table_id AND (hand_number=p_hand_number OR state='reserved'))
 OR EXISTS(SELECT 1 FROM public.hand_atomic_commits WHERE table_id=p_table_id AND hand_number=p_hand_number)
 OR EXISTS(SELECT 1 FROM public.hand_history WHERE table_id=p_table_id AND hand_number=p_hand_number)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_hand_dispatch WHERE permit_id=p_permit_id) THEN
 RAISE EXCEPTION 'F06_ORIGINAL_HAND_EVIDENCE_CONFLICT' USING ERRCODE='55000'; END IF;
 -- No new identity: persist the retained original tuple, not a replacement BEGIN.
 -- Permanent table/hand uniqueness and existing immutable terminal trigger apply.
 INSERT INTO smarter_private.f06_hand_permits
 (permit_id,tournament_id,table_id,lifecycle,hand_number,custody_id,generation,state,evidence_id)
 VALUES(p_permit_id,p_tournament_id,p_table_id,p_lifecycle,p_hand_number,p_original_custody_id,p_lease_generation,'never_started',p_park_custody_id)
 RETURNING * INTO h;
 RETURN to_jsonb(h)||jsonb_build_object('ok',true,'lifecycle',h.lifecycle::text,'hand_number',h.hand_number::text);
END $$;


ALTER FUNCTION public.fn_f06_finish_original_no_start(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid, p_lifecycle bigint, p_permit_id uuid, p_hand_number bigint, p_original_custody_id uuid, p_break_id uuid, p_park_custody_id uuid, p_park_revision bigint) OWNER TO postgres;

--
-- TOC entry 6025 (class 1255 OID 28810973)
-- Name: fn_f06_hand_number_state(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_hand_number_state(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE life bigint; used bigint; pending jsonb; blocked text;
BEGIN
 /* A TABLE'S HAND DOES NOT WAIT FOR ITS SIBLING TABLES (2026-10-03): the
    tournament lane T(id) shared, then this table and its seats FOR
    UPDATE. See fn_ca_f06_share_table_lane. */
 PERFORM public.fn_ca_f06_share_table_lane(p_tournament_id,p_lease_generation,p_table_id);
 SELECT tb.f06_lifecycle,CASE WHEN upper(t.status)<>'RUNNING' THEN 'tournament_not_running'
 WHEN lower(tb.status)='closed' OR COALESCE(tb.is_deleted,false) THEN 'table_closed' END INTO life,blocked
 FROM public.tables tb JOIN public.tournaments t ON t.id=tb.tournament_id
 WHERE tb.id=p_table_id AND tb.tournament_id=p_tournament_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','table_not_found'); END IF;
 SELECT GREATEST(0,
 COALESCE((SELECT max(hand_number) FROM smarter_private.f06_hand_permits WHERE table_id=p_table_id),0),
 COALESCE((SELECT max(hand_number) FROM public.hand_atomic_commits WHERE table_id=p_table_id),0),
 COALESCE((SELECT max(hand_number) FROM public.hand_history WHERE table_id=p_table_id),0)) INTO used;
 SELECT jsonb_build_object('permit_id',h.permit_id,'tournament_id',h.tournament_id,'table_id',h.table_id,
 'lifecycle',h.lifecycle::text,'hand_number',h.hand_number::text,'custody_id',h.custody_id,'generation',h.generation,'state',h.state)
 INTO pending FROM smarter_private.f06_hand_permits h WHERE h.table_id=p_table_id AND h.state='reserved';
 IF pending IS NOT NULL THEN blocked:='hand_permit_unresolved';
 ELSIF EXISTS(SELECT 1 FROM smarter_private.f06_operations WHERE source_table_id=p_table_id AND state NOT IN ('acknowledged','withdrawn_before_manifest')) THEN blocked:='source_excluded';
 ELSIF used=9223372036854775807 THEN blocked:='hand_number_exhausted'; END IF;
 RETURN jsonb_build_object('ok',true,'table_id',p_table_id,'lifecycle',life::text,
 'used_hand_number_max',used::text,'next_hand_number_candidate',CASE WHEN blocked IS NULL THEN (used+1)::text ELSE NULL END,
 'can_reserve',blocked IS NULL,'blocked_reason',blocked,'unresolved_permit',pending);
END $$;


ALTER FUNCTION public.fn_f06_hand_number_state(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid) OWNER TO postgres;

--
-- TOC entry 7506 (class 1255 OID 47519271)
