--
-- TOC entry 4223 (class 1255 OID 47519137)
-- Name: fn_f06_prepare_mixed_manager_custody(uuid, uuid, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_prepare_mixed_manager_custody(p_transfer_id uuid, p_tournament_id uuid, p_origin_generation uuid, p_successor_generation uuid, p_local jsonb, p_expected jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $_$
DECLARE retired_origin boolean:=false; l public.engine_tournament_leases; canonical jsonb; receipt jsonb; prior smarter_private.f06_manager_custody_transfers; checkpoint jsonb; maintenance jsonb; leader jsonb; instant timestamptz:=clock_timestamp();
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('app.smarter_data_actor',true) IS DISTINCT FROM 'service' THEN RAISE EXCEPTION 'F06_MIXED_SERVICE_REQUIRED' USING ERRCODE='42501'; END IF;
 IF p_transfer_id IS NULL OR p_tournament_id IS NULL OR p_origin_generation IS NULL OR p_successor_generation IS NULL
 OR p_origin_generation=p_successor_generation THEN RAISE EXCEPTION 'F06_MIXED_IDENTITY_REQUIRED'; END IF;
 -- Take the existing entry/maintenance lock before any lease row. The
 -- checkpoint is an assertion against locked authority, never a bypass GUC.
 IF NOT pg_try_advisory_xact_lock_shared(530090,1) THEN RAISE EXCEPTION 'F06_RETRY_MAINTENANCE_LANE' USING ERRCODE='55P03'; END IF;
 IF public.fn_platform_frozen() IS DISTINCT FROM false OR p_local ? 'release_checkpoint' THEN
 checkpoint:=p_local->'release_checkpoint';
 SELECT to_jsonb(b) INTO maintenance FROM public.engine_maintenance_break b WHERE to_jsonb(b)->'id'='true'::jsonb FOR SHARE;
 SELECT to_jsonb(e) INTO leader FROM public.engine_leader e WHERE id=true FOR SHARE;
 IF maintenance IS NULL OR leader IS NULL OR public.fn_platform_frozen() IS DISTINCT FROM true
 OR checkpoint IS NULL OR checkpoint->>'kind' IS DISTINCT FROM 'legacy_engine_checkpoint_8825_v1'
 OR checkpoint->>'source' IS DISTINCT FROM '8825af51817f379c4261658ca29ecc9d8d81932d'
 OR checkpoint->>'instance_id' IS DISTINCT FROM '1-3846b8bb'
 OR checkpoint->>'container_id' IS DISTINCT FROM 'c63b254ee71b76aa26f4d1394d96189963774310244b046bc91186e219ca3f66'
 OR checkpoint->>'process_id' IS DISTINCT FROM '1'
 OR COALESCE(checkpoint->>'run_id','') !~ '^[1-9][0-9]*(-[1-9][0-9]*)?$' OR COALESCE(checkpoint->>'control_sha','') !~ '^[0-9a-f]{40}$'
 OR checkpoint->>'phase' IS DISTINCT FROM 'counting_down'
 OR maintenance->>'phase' IS DISTINCT FROM checkpoint->>'phase'
 OR maintenance->>'declared_by' IS DISTINCT FROM '8825af51'
 OR (maintenance->>'ownership_token')::uuid IS DISTINCT FROM (checkpoint->>'ownership_token')::uuid
 OR (checkpoint->>'ownership_token')::uuid IS NULL
 OR (maintenance->>'announced_at')::timestamptz IS DISTINCT FROM (checkpoint->>'announced_at')::timestamptz
 OR (maintenance->>'break_started_at')::timestamptz IS DISTINCT FROM (checkpoint->>'break_started_at')::timestamptz
 OR (maintenance->>'break_ends_at')::timestamptz IS DISTINCT FROM (checkpoint->>'break_ends_at')::timestamptz
 OR maintenance->>'reason' IS DISTINCT FROM checkpoint->>'reason'
 OR (maintenance->>'announced_at')::timestamptz IS NULL
 OR (maintenance->>'break_started_at')::timestamptz IS NULL
 OR (maintenance->>'break_ends_at')::timestamptz IS NULL
 OR NOT isfinite((maintenance->>'announced_at')::timestamptz)
 OR NOT isfinite((maintenance->>'break_started_at')::timestamptz)
 OR NOT isfinite((maintenance->>'break_ends_at')::timestamptz)
 OR NOT (instant>=(maintenance->>'break_started_at')::timestamptz AND (maintenance->>'break_ends_at')::timestamptz-instant>=interval '245 seconds')
 OR leader->>'instance_id' IS DISTINCT FROM checkpoint->>'instance_id'
 OR leader->>'engine_version' IS DISTINCT FROM '8825af51'
 OR (leader->>'heartbeat_at')::timestamptz IS NULL
 OR NOT isfinite((leader->>'heartbeat_at')::timestamptz)
 OR NOT (instant-(leader->>'heartbeat_at')::timestamptz BETWEEN interval '-30 seconds' AND interval '60 seconds')
 THEN RAISE EXCEPTION 'F06_MIXED_FROZEN_CHECKPOINT_UNPROVEN' USING ERRCODE='55000'; END IF;
 END IF;
 PERFORM smarter_private.f06_retired_origin_lock(p_tournament_id);
 SELECT * INTO l FROM public.engine_tournament_leases WHERE tournament_id=p_tournament_id FOR UPDATE;
 IF NOT FOUND AND checkpoint IS NOT NULL AND EXISTS(SELECT 1 FROM smarter_private.f06_retired_manager_origins WHERE tournament_id=p_tournament_id AND origin_generation=p_origin_generation) THEN retired_origin:=true;
 ELSE
 IF NOT FOUND OR l.protocol_version<>2 OR l.lease_generation IS DISTINCT FROM p_origin_generation
 OR l.heartbeat_at IS NULL OR NOT isfinite(l.heartbeat_at)
 OR l.heartbeat_at>=clock_timestamp()-make_interval(secs=>public.fn_engine_lease_stale_seconds()) THEN RAISE EXCEPTION 'F06_MIXED_OLD_LEASE_CHANGED'; END IF;
 IF checkpoint IS NOT NULL AND (l.instance_id IS DISTINCT FROM checkpoint->>'instance_id' OR l.engine_version IS DISTINCT FROM left(checkpoint->>'source',8)) THEN RAISE EXCEPTION 'F06_MIXED_OLD_PROCESS_CHANGED'; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_local->'engines') e WHERE e#>'{bank_custody,stopped_capture}' IS NOT NULL) THEN
 IF retired_origin OR p_local#>>'{stopped_bank_owner,instance_id}' IS DISTINCT FROM l.instance_id
 OR p_local#>>'{stopped_bank_owner,version}' IS DISTINCT FROM l.engine_version
 THEN RAISE EXCEPTION 'F06_STOPPED_BANK_OWNER_CHANGED'; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_local->'engines') e WHERE e#>'{bank_custody,historical_loss}' IS NOT NULL) AND (NOT retired_origin OR checkpoint IS NULL) THEN
 RAISE EXCEPTION 'F06_HISTORICAL_LOSS_RETIRED_CHECKPOINT_REQUIRED'; END IF;
 canonical:=smarter_private.f06_mixed_custody_snapshot(p_tournament_id,p_origin_generation,p_local);
 IF retired_origin THEN PERFORM smarter_private.f06_retired_origin_transfer(p_tournament_id,p_origin_generation,p_local,canonical); END IF;
 SELECT * INTO prior FROM smarter_private.f06_manager_custody_transfers WHERE tournament_id=p_tournament_id AND origin_generation=p_origin_generation;
 IF FOUND AND (prior.transfer_id,prior.successor_generation,prior.local_proof,prior.canonical_proof) IS DISTINCT FROM
 (p_transfer_id,p_successor_generation,p_local,canonical) THEN RAISE EXCEPTION 'F06_MIXED_TRANSFER_CHANGED'; END IF;
 IF p_expected IS NOT NULL THEN
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_local->'engines') e WHERE e->>'lifecycle' IS NULL) THEN RAISE EXCEPTION 'F06_MIXED_PHYSICAL_LIFECYCLE_CHANGED'; END IF;
 IF p_expected IS DISTINCT FROM canonical THEN RAISE EXCEPTION 'F06_MIXED_CANONICAL_CHANGED'; END IF;
 IF prior.transfer_id IS NULL THEN
 INSERT INTO smarter_private.f06_manager_custody_transfers(transfer_id,tournament_id,origin_generation,successor_generation,local_proof,canonical_proof)
 VALUES(p_transfer_id,p_tournament_id,p_origin_generation,p_successor_generation,p_local,canonical) RETURNING * INTO prior;
 END IF;
 receipt:=to_jsonb(prior);
 END IF;
 RETURN jsonb_build_object('ok',true,'transfer_id',p_transfer_id,'tournament_id',p_tournament_id,
 'origin_generation',p_origin_generation,'successor_generation',p_successor_generation,'local',p_local,'canonical',canonical,'receipt',receipt);
END $_$;


ALTER FUNCTION public.fn_f06_prepare_mixed_manager_custody(p_transfer_id uuid, p_tournament_id uuid, p_origin_generation uuid, p_successor_generation uuid, p_local jsonb, p_expected jsonb) OWNER TO postgres;

--
-- TOC entry 3820 (class 1255 OID 28810974)
-- Name: fn_f06_request_park(uuid, uuid, uuid, uuid, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_request_park(p_tournament_id uuid, p_lease_generation uuid, p_break_id uuid, p_table_id uuid, p_lifecycle bigint, p_boundary_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE o smarter_private.f06_operations;
BEGIN
 PERFORM smarter_private.f06_prefix(p_tournament_id,p_lease_generation,'{}',ARRAY[p_table_id]);
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=p_break_id;
 IF FOUND THEN
 IF (o.tournament_id,o.source_table_id,o.lifecycle,o.boundary_id) IS DISTINCT FROM (p_tournament_id,p_table_id,p_lifecycle,p_boundary_id) THEN
 RAISE EXCEPTION 'F06_CHANGED_PARK_REPLAY' USING ERRCODE='22023'; END IF;
 RETURN smarter_private.f06_state(p_break_id); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tournaments WHERE id=p_tournament_id AND upper(status)='RUNNING') THEN
 RETURN jsonb_build_object('ok',false,'reason','tournament_not_running'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tables WHERE id=p_table_id AND tournament_id=p_tournament_id AND f06_lifecycle=p_lifecycle
 AND NOT COALESCE(is_deleted,false) AND lower(status)<>'closed') THEN RAISE EXCEPTION 'F06_SOURCE_LIFECYCLE' USING ERRCODE='55000'; END IF;
 INSERT INTO smarter_private.f06_operations(break_id,tournament_id,source_table_id,lifecycle,boundary_id,origin_generation)
 VALUES(p_break_id,p_tournament_id,p_table_id,p_lifecycle,p_boundary_id,p_lease_generation);
 RETURN smarter_private.f06_state(p_break_id);
END $$;


ALTER FUNCTION public.fn_f06_request_park(p_tournament_id uuid, p_lease_generation uuid, p_break_id uuid, p_table_id uuid, p_lifecycle bigint, p_boundary_id uuid) OWNER TO postgres;

--
-- TOC entry 7245 (class 1255 OID 28810972)
-- Name: fn_f06_table_state(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_table_state(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE v jsonb; recovery jsonb;
BEGIN
 PERFORM smarter_private.f06_authority(p_tournament_id,p_lease_generation);
 recovery:=public.fn_f06_hand_number_state(p_tournament_id,p_lease_generation,p_table_id);
 SELECT jsonb_build_object('ok',true,'table_id',t.id,'lifecycle',t.f06_lifecycle::text,'excluded',o.break_id IS NOT NULL,'break_id',o.break_id) INTO v
 FROM public.tables t LEFT JOIN smarter_private.f06_operations o ON o.source_table_id=t.id AND o.state NOT IN ('acknowledged','withdrawn_before_manifest')
 WHERE t.id=p_table_id AND t.tournament_id=p_tournament_id;
 IF v IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','table_not_found'); END IF;
 RETURN v||jsonb_build_object('hand_number_high_water',recovery->'used_hand_number_max',
 'unresolved_permits',CASE WHEN recovery->'unresolved_permit'='null'::jsonb THEN '[]'::jsonb ELSE jsonb_build_array(recovery->'unresolved_permit') END,
 'unresolved_overflow',false,'can_reserve',recovery->'can_reserve','blocked_reason',recovery->'blocked_reason');
END $$;


ALTER FUNCTION public.fn_f06_table_state(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid) OWNER TO postgres;

--
-- TOC entry 6578 (class 1255 OID 63899111)
-- Name: fn_f06_void_stranded_mixed_original(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_void_stranded_mixed_original(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE
  t uuid := p_tournament_id;
  xfer smarter_private.f06_manager_custody_transfers;
  event public.tournaments;
  h smarter_private.f06_hand_permits;
  snap public.hand_state_snapshots;
  b jsonb;
  reserved_ids uuid[];
  original_ids uuid[];
  tab_ids uuid[];
  users uuid[];
  u uuid;
  n integer;
  roster jsonb;
  hands jsonb := '[]'::jsonb;
  item jsonb;
  actual jsonb;
  v_receipt uuid;
  v_snap_ids uuid[] := ARRAY[]::uuid[];
  v_before jsonb;
  v_after jsonb;
  v_busts jsonb;
BEGIN
  IF t IS NULL THEN
    RAISE EXCEPTION 'F06_STRANDED_IDENTITY_REQUIRED' USING ERRCODE = '22023';
  END IF;
  IF public.fn_platform_frozen() THEN
    RAISE EXCEPTION 'PLATFORM_FROZEN: stranded mixed void refused' USING ERRCODE = '55000';
  END IF;

  -- The event's own lane, taken only when it is free (never queued).
  PERFORM smarter_private.f06_try_lane(t);

  -- Exactly one custody transfer is still open, and its successor was never
  -- admitted: nobody but the dead origin ever held the hands it reserved.
  SELECT c.* INTO xfer FROM smarter_private.f06_manager_custody_transfers c
   WHERE c.tournament_id = t
     AND NOT EXISTS (SELECT 1 FROM smarter_private.f06_manager_custody_completions d
                      WHERE d.transfer_id = c.transfer_id);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN
    RAISE EXCEPTION 'F06_STRANDED_TRANSFER_REQUIRED' USING ERRCODE = '55000';
  END IF;
  v_receipt := md5('f06:stranded-mixed-original:' || xfer.transfer_id::text)::uuid;
  IF EXISTS (SELECT 1 FROM smarter_private.f06_mixed_aborts WHERE receipt_id = v_receipt) THEN
    RETURN jsonb_build_object('ok', true, 'replayed', true, 'receipt_id', v_receipt,
                              'tournament_id', t, 'credit', 0);
  END IF;
  IF EXISTS (SELECT 1 FROM smarter_private.f06_manager_custody_admissions a
              WHERE a.transfer_id = xfer.transfer_id) THEN
    RAISE EXCEPTION 'F06_STRANDED_TRANSFER_ADMITTED' USING ERRCODE = '55000';
  END IF;
  IF smarter_private.f06_generation_aborted(t, xfer.origin_generation)
     OR smarter_private.f06_generation_aborted(t, xfer.successor_generation) THEN
    RAISE EXCEPTION 'F06_STRANDED_GENERATION_DISPOSED' USING ERRCODE = '55000';
  END IF;
  -- Nobody but the never-admitted successor may hold the event. The engine
  -- claims the successor generation and is refused admission until this
  -- receipt exists, so that holder has built nothing and can act on nothing
  -- (every F06 write needs the lane this transaction holds). Any other holder
  -- is retried, never raced.
  IF EXISTS (SELECT 1 FROM public.engine_tournament_leases
              WHERE tournament_id = t
                AND lease_generation IS DISTINCT FROM xfer.successor_generation) THEN
    RAISE EXCEPTION 'F06_STRANDED_EVENT_OWNED' USING ERRCODE = '55P03';
  END IF;

  -- The reserved set is exactly the transfer's original hands.
  SELECT array_agg(permit_id ORDER BY permit_id) INTO reserved_ids
    FROM smarter_private.f06_hand_permits WHERE tournament_id = t AND state = 'reserved';
  SELECT array_agg((e#>>'{permit,binding,permit_id}')::uuid ORDER BY (e#>>'{permit,binding,permit_id}')::uuid)
    INTO original_ids
    FROM jsonb_array_elements(xfer.local_proof->'engines') e
   WHERE e->'permit' IS DISTINCT FROM 'null'::jsonb;
  -- Every reserved hand is one of the transfer's originals. An original that
  -- is not reserved any more reached its own positive terminal disposition
  -- after the transfer was prepared (the one legal change before admission):
  -- it was accepted by the origin generation, with the exact committed hand
  -- the successor's snapshot reads as its witness. Only the reserved hands
  -- are voided; the committed one is left exactly as it settled.
  IF reserved_ids IS NULL OR original_ids IS NULL OR NOT (reserved_ids <@ original_ids)
     OR (SELECT count(*) FROM smarter_private.f06_hand_permits o
          WHERE o.permit_id = ANY (original_ids))
        -- An original whose permit never reached the database counts once its
        -- absence is recorded for the origin (20261004125152); it has no hand.
        + (SELECT count(*) FROM smarter_private.f06_absent_permit_releases r
            WHERE r.permit_id = ANY (original_ids) AND r.tournament_id = t
              AND r.generation = xfer.origin_generation
              AND NOT EXISTS (SELECT 1 FROM smarter_private.f06_hand_permits o
                               WHERE o.permit_id = r.permit_id)) <> cardinality(original_ids)
     OR EXISTS (
          SELECT 1 FROM smarter_private.f06_hand_permits o
           WHERE o.permit_id = ANY (original_ids) AND NOT (o.permit_id = ANY (reserved_ids))
             AND NOT (o.state = 'accepted' AND o.tournament_id = t
                      AND o.generation = xfer.origin_generation
                      AND EXISTS (SELECT 1 FROM public.hand_atomic_commits a
                                    JOIN public.hand_history hh ON hh.id = a.hand_id
                                     AND hh.table_id = a.table_id AND hh.hand_number = a.hand_number
                                   WHERE a.hand_id = o.evidence_id AND a.table_id = o.table_id
                                     AND a.hand_number = o.hand_number
                                     AND a.post_commit_completed_at IS NOT NULL))) THEN
    RAISE EXCEPTION 'F06_STRANDED_ORIGINALS_CHANGED' USING ERRCODE = '55000';
  END IF;
  FOREACH u IN ARRAY reserved_ids LOOP
    IF NOT pg_try_advisory_xact_lock(hashtextextended('f06:hand:' || u::text, 0)) THEN
      RAISE EXCEPTION 'F06_HAND_DISPATCH_BUSY' USING ERRCODE = '55P03';
    END IF;
  END LOOP;
  SELECT array_agg(DISTINCT table_id ORDER BY table_id) INTO tab_ids
    FROM smarter_private.f06_hand_permits WHERE permit_id = ANY (reserved_ids);
  SELECT array_agg(DISTINCT user_id ORDER BY user_id) INTO users
    FROM public.table_seats WHERE table_id = ANY (tab_ids) AND left_at IS NULL;
  IF users IS NOT NULL THEN
    FOREACH u IN ARRAY users LOOP
      IF NOT pg_try_advisory_xact_lock(hashtextextended('table_cap:' || u::text, 0)) THEN
        RAISE EXCEPTION 'F06_ABORT_RETRY_PLAYER_LANE' USING ERRCODE = '55P03';
      END IF;
    END LOOP;
  END IF;

  SELECT * INTO event FROM public.tournaments WHERE id = t FOR UPDATE;
  PERFORM 1 FROM public.tournament_players WHERE tournament_id = t ORDER BY user_id FOR UPDATE;
  PERFORM 1 FROM public.tables WHERE tournament_id = t ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.table_seats WHERE table_id = ANY (tab_ids) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM smarter_private.f06_hand_permits
   WHERE permit_id = ANY (reserved_ids) ORDER BY permit_id FOR UPDATE;
  PERFORM 1 FROM smarter_private.f06_operations WHERE tournament_id = t ORDER BY break_id FOR UPDATE;

  IF event.id IS NULL OR event.status IS DISTINCT FROM 'RUNNING'
     OR event.format_contract IS NULL
     OR event.format_contract NOT IN ('mtt-v1', 'mtt-v2', 'spin-v1', 'sng-v1') THEN
    RAISE EXCEPTION 'F06_STRANDED_EVENT_NOT_RUNNING' USING ERRCODE = '55000';
  END IF;
  -- No table break of any origin is open: nothing but the hands is in the air.
  IF EXISTS (SELECT 1 FROM smarter_private.f06_operations
              WHERE tournament_id = t AND state NOT IN ('acknowledged', 'withdrawn_before_manifest')) THEN
    RAISE EXCEPTION 'F06_STRANDED_PARK_OPEN' USING ERRCODE = '55000';
  END IF;

  -- Every chip and registration of the affected tables, before.
  SELECT jsonb_build_object(
           'seats', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', s.id, 'user_id', s.user_id,
                              'stack', s.stack, 'left_at', s.left_at) ORDER BY s.id), '[]'::jsonb)
                       FROM public.table_seats s WHERE s.table_id = ANY (tab_ids)),
           'registrations', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', p.id, 'status', p.status,
                              'chips', p.chips, 'table_id', p.table_id, 'seat_number', p.seat_number) ORDER BY p.id), '[]'::jsonb)
                       FROM public.tournament_players p WHERE p.tournament_id = t))
    INTO v_before;

  FOR h IN SELECT * FROM smarter_private.f06_hand_permits
            WHERE permit_id = ANY (reserved_ids) ORDER BY permit_id LOOP
    SELECT e#>'{permit,binding}' INTO b FROM jsonb_array_elements(xfer.local_proof->'engines') e
     WHERE e#>>'{permit,binding,permit_id}' = h.permit_id::text;
    IF h.generation IS DISTINCT FROM xfer.origin_generation OR h.evidence_id IS NOT NULL
       OR b->>'tournament_id' IS DISTINCT FROM t::text
       OR b->>'table_id' IS DISTINCT FROM h.table_id::text
       OR b->>'hand_number' IS DISTINCT FROM h.hand_number::text
       OR b->>'lifecycle' IS DISTINCT FROM h.lifecycle::text
       OR b->>'custody_id' IS DISTINCT FROM h.custody_id::text
       OR b->>'lease_generation' IS DISTINCT FROM h.generation::text
       OR NOT EXISTS (SELECT 1 FROM public.tables tb
                       WHERE tb.id = h.table_id AND tb.tournament_id = t
                         AND NOT COALESCE(tb.is_deleted, false)
                         AND lower(COALESCE(tb.status, '')) IN ('waiting', 'running')
                         AND tb.f06_lifecycle = h.lifecycle)
       OR EXISTS (SELECT 1 FROM smarter_private.f06_hand_permits q
                   WHERE q.table_id = h.table_id AND q.hand_number > h.hand_number) THEN
      RAISE EXCEPTION 'F06_STRANDED_PERMIT_CHANGED' USING ERRCODE = '55000';
    END IF;
    -- The hand never reached the platform: no commit, history, private state,
    -- dispatch, submission, disposition or recorded action.
    IF EXISTS (SELECT 1 FROM public.hand_atomic_commits c
                WHERE c.table_id = h.table_id AND c.hand_number >= h.hand_number)
       OR EXISTS (SELECT 1 FROM public.hand_history hh
                   WHERE hh.table_id = h.table_id AND hh.hand_number >= h.hand_number)
       OR EXISTS (SELECT 1 FROM public.hand_private_state hp
                   WHERE hp.table_id = h.table_id AND hp.hand_number >= h.hand_number)
       OR EXISTS (SELECT 1 FROM smarter_private.f06_hand_dispatch d WHERE d.permit_id = h.permit_id) THEN
      RAISE EXCEPTION 'F06_ABORT_COMMITTED_OR_DISPATCHED' USING ERRCODE = '55000';
    END IF;
    IF EXISTS (SELECT 1 FROM smarter_private.hand_submissions s
                WHERE s.table_id = h.table_id AND s.hand_number = h.hand_number)
       OR EXISTS (SELECT 1 FROM smarter_private.hand_submission_dispositions d
                   WHERE d.table_id = h.table_id AND d.hand_number = h.hand_number)
       OR EXISTS (SELECT 1 FROM public.hand_discards z
                   WHERE z.table_id = h.table_id AND z.hand_number = h.hand_number) THEN
      RAISE EXCEPTION 'F06_STRANDED_HAND_HAS_A_SUBMISSION' USING ERRCODE = '55000';
    END IF;

    -- Every live chair is one playing registration holding the same chips,
    -- and every playing registration at this table has its live chair.
    SELECT jsonb_agg(jsonb_build_object(
             'seat_id', s.id, 'occupancy_id', s.occupancy_id, 'user_id', s.user_id,
             'seat_number', s.seat_number, 'stack', s.stack,
             'registration_id', tp.id, 'chips', tp.chips) ORDER BY s.user_id)
      INTO roster
      FROM public.table_seats s
      LEFT JOIN public.tournament_players tp
        ON tp.tournament_id = t AND tp.user_id = s.user_id AND tp.table_id = s.table_id
       AND tp.seat_number = s.seat_number AND tp.status = 'playing'
     WHERE s.table_id = h.table_id AND s.left_at IS NULL;
    IF roster IS NULL
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(roster) r
                   WHERE r->>'registration_id' IS NULL OR r->>'stack' IS NULL
                      OR (r->>'stack')::numeric < 0
                      OR (r->>'stack')::numeric IS DISTINCT FROM (r->>'chips')::numeric)
       OR EXISTS (SELECT 1 FROM public.tournament_players tp
                   WHERE tp.tournament_id = t AND tp.table_id = h.table_id AND tp.status = 'playing'
                     AND NOT EXISTS (SELECT 1 FROM public.table_seats s
                                      WHERE s.table_id = h.table_id AND s.user_id = tp.user_id
                                        AND s.seat_number = tp.seat_number AND s.left_at IS NULL)
                     -- A bust whose elimination is still pending holds nothing
                     -- (the abandoned-generation door's ruling of 2026-09-26):
                     -- zero chips, and no chair it ever had in the event is
                     -- live or holds a chip. It was not dealt into this hand
                     -- either: the snapshot must name exactly the live chairs.
                     AND NOT (tp.chips = 0
                              AND NOT EXISTS (SELECT 1 FROM public.table_seats bs
                                                JOIN public.tables bt ON bt.id = bs.table_id
                                               WHERE bt.tournament_id = t AND bs.user_id = tp.user_id
                                                 AND (bs.left_at IS NULL OR bs.stack IS DISTINCT FROM 0)))) THEN
      RAISE EXCEPTION 'F06_STRANDED_ROSTER_CHANGED' USING ERRCODE = '55000';
    END IF;
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'registration_id', tp.id, 'user_id', tp.user_id,
             'seat_number', tp.seat_number, 'chips', tp.chips) ORDER BY tp.user_id), '[]'::jsonb)
      INTO v_busts
      FROM public.tournament_players tp
     WHERE tp.tournament_id = t AND tp.table_id = h.table_id AND tp.status = 'playing'
       AND NOT EXISTS (SELECT 1 FROM public.table_seats s
                        WHERE s.table_id = h.table_id AND s.user_id = tp.user_id
                          AND s.seat_number = tp.seat_number AND s.left_at IS NULL);

    -- One open preflop snapshot, and every chair still holds exactly what it
    -- held before the deal: its snapshot stack plus everything it put in. No
    -- blind, ante or bet of this hand ever left a durable chair.
    SELECT count(*) INTO n FROM public.hand_state_snapshots s
     WHERE s.table_id = h.table_id AND s.hand_number = h.hand_number;
    IF n <> 1 THEN
      RAISE EXCEPTION 'F06_STRANDED_SNAPSHOT_REQUIRED' USING ERRCODE = '55000';
    END IF;
    SELECT * INTO snap FROM public.hand_state_snapshots s
     WHERE s.table_id = h.table_id AND s.hand_number = h.hand_number FOR UPDATE;
    IF snap.is_complete IS DISTINCT FROM false
       OR snap.stage IS DISTINCT FROM 'preflop'
       OR snap.state_json->>'stage' IS DISTINCT FROM 'preflop'
       OR jsonb_typeof(snap.state_json->'players') IS DISTINCT FROM 'array'
       OR jsonb_array_length(snap.state_json->'players') NOT BETWEEN 2 AND 10
       OR jsonb_array_length(snap.state_json->'players') <> jsonb_array_length(roster)
       OR (SELECT count(DISTINCT x->>'user_id') FROM jsonb_array_elements(snap.state_json->'players') x)
            IS DISTINCT FROM jsonb_array_length(snap.state_json->'players')::bigint
       OR NOT COALESCE(pg_input_is_valid(snap.state_json->>'pot', 'numeric'), false)
       OR EXISTS (
            SELECT 1 FROM jsonb_array_elements(snap.state_json->'players') x
             WHERE NOT (CASE
               WHEN COALESCE(pg_input_is_valid(x->>'user_id', 'uuid'), false)
                AND COALESCE(pg_input_is_valid(x->>'seat', 'integer'), false)
                AND COALESCE(pg_input_is_valid(x->>'stack', 'numeric'), false)
                AND COALESCE(pg_input_is_valid(x->>'totalInvested', 'numeric'), false)
                AND COALESCE(pg_input_is_valid(COALESCE(x->>'deadInvested', '0'), 'numeric'), false)
               THEN
                 (x->>'stack')::numeric >= 0
                 AND (x->>'totalInvested')::numeric >= 0
                 AND COALESCE((x->>'deadInvested')::numeric, 0) BETWEEN 0 AND (x->>'totalInvested')::numeric
                 AND (x->>'stack')::numeric::text NOT IN ('NaN', 'Infinity', '-Infinity')
                 AND (x->>'totalInvested')::numeric::text NOT IN ('NaN', 'Infinity', '-Infinity')
                 AND EXISTS (SELECT 1 FROM jsonb_array_elements(roster) r
                              WHERE r->>'user_id' = x->>'user_id'
                                AND (r->>'seat_number')::integer = (x->>'seat')::integer
                                AND (r->>'stack')::numeric
                                      = (x->>'stack')::numeric + (x->>'totalInvested')::numeric)
               ELSE false END))
       OR (snap.state_json->>'pot')::numeric IS DISTINCT FROM
            (SELECT sum((x->>'totalInvested')::numeric)
               FROM jsonb_array_elements(snap.state_json->'players') x) THEN
      RAISE EXCEPTION 'F06_ABORT_SAVED_STACKS_CHANGED' USING ERRCODE = '55000';
    END IF;
    -- Every hole card went to a live chair of this table.
    IF EXISTS (SELECT 1 FROM public.table_hole_cards c
                WHERE c.table_id = h.table_id AND c.hand_number = h.hand_number
                  AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(roster) r
                                   WHERE r->>'user_id' = c.user_id::text)) THEN
      RAISE EXCEPTION 'F06_STRANDED_CARDS_CHANGED' USING ERRCODE = '55000';
    END IF;

    hands := hands || jsonb_build_array(jsonb_build_object(
      'permit', to_jsonb(h), 'ruling', 'misdeal_voided', 'shape', 'stranded_mixed_original',
      'snapshot_id', snap.id, 'snapshot_hash', md5(to_jsonb(snap)::text),
      'snapshot_created_at', snap.created_at, 'pot_returned_to_chairs', snap.state_json->'pot',
      'hole_cards', (SELECT count(*) FROM public.table_hole_cards c
                      WHERE c.table_id = h.table_id AND c.hand_number = h.hand_number),
      'binding', b, 'roster', roster, 'busts_pending_elimination', v_busts, 'break_id', NULL));
    v_snap_ids := v_snap_ids || snap.id;
  END LOOP;

  actual := jsonb_build_object(
    'kind', 'stranded_mixed_original', 'tournament_id', t, 'format_contract', event.format_contract,
    'transfer_id', xfer.transfer_id, 'origin_generation', xfer.origin_generation,
    'successor_generation', xfer.successor_generation, 'transfer_created_at', xfer.created_at,
    'hands', hands, 'credit', 0,
    'reason', 'The origin generation reserved and dealt these hands and died before any reached a commit; its successor can only be admitted once each has a terminal disposition, and only the origin could give one. Every chair already holds its pre-deal stack, so the hands are misdeals and nothing moves.');
  IF public.fn_platform_frozen() THEN
    RAISE EXCEPTION 'PLATFORM_FROZEN: stranded mixed void refused' USING ERRCODE = '55000';
  END IF;

  -- The receipt the mixed custody snapshot reads as the original's terminal
  -- disposition. Only the ORIGIN generation is disposed; the successor stays
  -- claimable, and is admitted by the engine exactly as designed.
  INSERT INTO smarter_private.f06_mixed_aborts (receipt_id, tournament_id, expected)
  VALUES (v_receipt, t, actual);
  INSERT INTO smarter_private.f06_mixed_abort_generations (tournament_id, generation, receipt_id)
  VALUES (t, xfer.origin_generation, v_receipt);
  FOR item IN SELECT value FROM jsonb_array_elements(hands) LOOP
    INSERT INTO smarter_private.f06_mixed_abort_hands
      (permit_id, receipt_id, tournament_id, generation, table_id, hand_number,
       snapshot_id, break_id, prior_hand_id, prior_abort_receipt_id, expected)
    VALUES ((item->'permit'->>'permit_id')::uuid, v_receipt, t, xfer.origin_generation,
            (item->'permit'->>'table_id')::uuid, (item->'permit'->>'hand_number')::bigint,
            (item->>'snapshot_id')::uuid, NULL, NULL, NULL, item);
  END LOOP;
  UPDATE smarter_private.f06_hand_permits SET state = 'aborted_unsettled', evidence_id = v_receipt
   WHERE permit_id = ANY (reserved_ids) AND state = 'reserved';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> cardinality(reserved_ids) THEN
    RAISE EXCEPTION 'F06_STRANDED_PERMIT_CLAIM_LOST' USING ERRCODE = '55000';
  END IF;
  UPDATE public.hand_state_snapshots SET is_complete = true
   WHERE id = ANY (v_snap_ids) AND NOT is_complete;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> cardinality(v_snap_ids) THEN
    RAISE EXCEPTION 'F06_STRANDED_SNAPSHOT_CLAIM_LOST' USING ERRCODE = '55000';
  END IF;

  -- After: nothing reserved, the origin disposed and the successor not, every
  -- original carries the evidence the successor's admission reads, and not
  -- one chip or registration moved.
  SELECT jsonb_build_object(
           'seats', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', s.id, 'user_id', s.user_id,
                              'stack', s.stack, 'left_at', s.left_at) ORDER BY s.id), '[]'::jsonb)
                       FROM public.table_seats s WHERE s.table_id = ANY (tab_ids)),
           'registrations', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', p.id, 'status', p.status,
                              'chips', p.chips, 'table_id', p.table_id, 'seat_number', p.seat_number) ORDER BY p.id), '[]'::jsonb)
                       FROM public.tournament_players p WHERE p.tournament_id = t))
    INTO v_after;
  IF v_after IS DISTINCT FROM v_before
     OR EXISTS (SELECT 1 FROM smarter_private.f06_hand_permits WHERE tournament_id = t AND state = 'reserved')
     OR NOT smarter_private.f06_generation_aborted(t, xfer.origin_generation)
     OR smarter_private.f06_generation_aborted(t, xfer.successor_generation)
     OR EXISTS (
          SELECT 1 FROM smarter_private.f06_hand_permits o
           WHERE o.permit_id = ANY (reserved_ids)
             AND NOT EXISTS (
               SELECT 1 FROM smarter_private.f06_mixed_abort_hands a
                 JOIN smarter_private.f06_mixed_aborts c USING (receipt_id, tournament_id)
                WHERE (a.permit_id, a.receipt_id, a.tournament_id, a.generation, a.table_id, a.hand_number)
                      = (o.permit_id, o.evidence_id, o.tournament_id, o.generation, o.table_id, o.hand_number)
                  AND o.state = 'aborted_unsettled' AND c.outcome = 'aborted_unsettled'
                  AND a.expected->'permit' = (to_jsonb(o) || jsonb_build_object('state', 'reserved', 'evidence_id', NULL)))) THEN
    RAISE EXCEPTION 'F06_STRANDED_POSTIMAGE_CHANGED' USING ERRCODE = '55000';
  END IF;

  RETURN jsonb_build_object('ok', true, 'outcome', 'aborted_unsettled', 'receipt_id', v_receipt,
    'tournament_id', t, 'transfer_id', xfer.transfer_id, 'origin_generation', xfer.origin_generation,
    'successor_generation', xfer.successor_generation, 'hands_voided', cardinality(reserved_ids),
    'credit', 0);
END
$$;


ALTER FUNCTION public.fn_f06_void_stranded_mixed_original(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 4893 (class 1255 OID 86565056)
-- Name: fn_f06_withdraw_unplaceable_park(uuid, uuid, uuid, bigint, uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_f06_withdraw_unplaceable_park(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid, p_lifecycle bigint, p_break_id uuid, p_park_custody_id uuid, p_park_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE h smarter_private.f06_hand_permits; o smarter_private.f06_operations;
 receipt smarter_private.f06_no_start_continuations; users uuid[]; roster jsonb; movement jsonb;
 free_seats bigint; destinations integer; unknown_capacity integer; unsealed bigint;
BEGIN
 IF p_tournament_id IS NULL OR p_lease_generation IS NULL OR p_table_id IS NULL OR p_lifecycle IS NULL OR p_lifecycle<1
 OR p_break_id IS NULL OR p_park_custody_id IS NULL OR p_park_revision IS NULL OR p_park_revision<1 THEN
 RAISE EXCEPTION 'F06_WITHDRAWAL_IDENTITY' USING ERRCODE='22023'; END IF;
 SELECT array_agg(user_id ORDER BY user_id) INTO users FROM public.table_seats
 WHERE table_id=p_table_id AND left_at IS NULL;
 -- The live lease holder's exclusive tournament lane, exactly as the
 -- last-table continuation takes it.
 PERFORM smarter_private.f06_prefix(p_tournament_id,p_lease_generation,COALESCE(users,'{}'),ARRAY[p_table_id]);
 SELECT * INTO receipt FROM smarter_private.f06_no_start_continuations WHERE break_id=p_break_id;
 IF FOUND THEN
 IF (receipt.tournament_id,receipt.current_generation,receipt.table_id,receipt.lifecycle,
 (receipt.park->>'custody_id')::uuid,(receipt.park->>'revision')::bigint,receipt.prior_committed->>'kind') IS DISTINCT FROM
 (p_tournament_id,p_lease_generation,p_table_id,p_lifecycle,p_park_custody_id,p_park_revision,'unplaceable_park_withdrawal'::text) THEN
 RAISE EXCEPTION 'F06_WITHDRAWAL_CHANGED_REPLAY' USING ERRCODE='22023'; END IF;
 ELSE
 IF public.fn_platform_frozen() THEN RAISE EXCEPTION 'PLATFORM_FROZEN: withdrawal refused' USING ERRCODE='55000'; END IF;
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=p_break_id FOR UPDATE;
 IF NOT FOUND OR (o.tournament_id,o.source_table_id,o.lifecycle,o.state,o.custody_id,o.revision)
 IS DISTINCT FROM (p_tournament_id,p_table_id,p_lifecycle,'park_requested'::text,p_park_custody_id,p_park_revision)
 -- Only the park's current custodian, which f06_prefix proved is the live
 -- lease holder, withdraws it.
 OR o.custody_generation IS DISTINCT FROM p_lease_generation
 OR o.manifest IS NOT NULL OR o.close_receipt IS NOT NULL OR o.cleanup_kind IS NOT NULL
 OR o.abort_receipt_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM smarter_private.f06_members WHERE break_id=o.break_id)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_attempts WHERE break_id=o.break_id) THEN
 RAISE EXCEPTION 'F06_WITHDRAWAL_EXACT_PREMANIFEST_PARK' USING ERRCODE='55000'; END IF;
 -- The table's latest hand permit is the positive witness that nothing is in
 -- flight. Either it was decided never_started (a terminal, immutable
 -- outcome) by the generation that parked it or the one that holds its
 -- custody now - a successor that re-claimed the park after an engine
 -- restart holds a new custody id, so the witness's evidence is not required
 -- to equal it - or it is accepted and its hand is sealed: committed
 -- atomically, post-commit completed, in hand_history. The second is the park
 -- whose next hand's permit was never written at all (2026-10-03, 79feebfc:
 -- a begin_hand cancelled by a statement timeout left the dealer's permit
 -- unknown, the zombie watchdog parked the table, and the database holds
 -- nothing after the last sealed hand). The park itself excludes the table
 -- from every later permit, so no hand can start behind either witness.
 SELECT * INTO h FROM smarter_private.f06_hand_permits WHERE table_id=p_table_id
 ORDER BY hand_number DESC LIMIT 1 FOR UPDATE;
 IF NOT FOUND OR (h.tournament_id,h.lifecycle) IS DISTINCT FROM (p_tournament_id,p_lifecycle)
 OR h.evidence_id IS NULL OR h.state NOT IN ('never_started','accepted')
 OR (h.state='never_started' AND h.generation IS DISTINCT FROM o.origin_generation
     AND h.generation IS DISTINCT FROM o.custody_generation)
 OR (h.state='accepted' AND NOT EXISTS(SELECT 1 FROM public.hand_atomic_commits c
     JOIN public.hand_history x ON x.id=c.hand_id AND x.table_id=c.table_id AND x.hand_number=c.hand_number
     WHERE c.table_id=p_table_id AND c.hand_number=h.hand_number AND c.post_commit_completed_at IS NOT NULL))
 -- One witness answers for one withdrawal; the receipt table keys on it.
 OR EXISTS(SELECT 1 FROM smarter_private.f06_no_start_continuations WHERE permit_id=h.permit_id)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_hand_permits WHERE table_id=p_table_id AND state='reserved') THEN
 RAISE EXCEPTION 'F06_WITHDRAWAL_POSITIVE_ORIGINAL_REQUIRED' USING ERRCODE='55000'; END IF;
 -- The first hand number that must have left no trace: the witness's own for
 -- a hand that never started, the next one after a sealed hand.
 unsealed:=CASE WHEN h.state='accepted' THEN h.hand_number+1 ELSE h.hand_number END;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('f06:hand:'||h.permit_id::text,0)) THEN
 RAISE EXCEPTION 'F06_HAND_DISPATCH_BUSY' USING ERRCODE='55P03'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tournaments WHERE id=p_tournament_id AND status='RUNNING'
 AND format_contract IN ('mtt-v1','mtt-v2','sng-v1','spin-v1'))
 OR NOT EXISTS(SELECT 1 FROM public.tables WHERE id=p_table_id AND tournament_id=p_tournament_id
 AND f06_lifecycle=p_lifecycle AND lower(status) IN ('waiting','running') AND NOT COALESCE(is_deleted,false)) THEN
 RAISE EXCEPTION 'F06_WITHDRAWAL_OPEN_SOURCE_REQUIRED' USING ERRCODE='55000'; END IF;
 -- The last open table has its own exit, the no-start continuation, for a
 -- never_started witness. That door cannot read a sealed-hand witness, so a
 -- last table parked over one is withdrawn here (2026-10-03: SNG 657e45b2,
 -- table bba21601, heads-up, parked with nothing after its sealed hand).
 IF h.state='never_started' AND (SELECT count(*) FROM public.tables WHERE tournament_id=p_tournament_id AND lower(status)<>'closed'
 AND NOT COALESCE(is_deleted,false))<2 THEN
 RAISE EXCEPTION 'F06_WITHDRAWAL_LAST_TABLE' USING ERRCODE='55000'; END IF;
 IF EXISTS(SELECT 1 FROM public.table_seats s LEFT JOIN public.tournament_players p
 ON p.tournament_id=p_tournament_id AND p.user_id=s.user_id AND p.table_id=s.table_id
 AND p.seat_number=s.seat_number AND p.status='playing'
 WHERE s.table_id=p_table_id AND s.left_at IS NULL AND (p.id IS NULL OR s.occupancy_id IS NULL
 OR s.joined_at IS NULL OR s.terminal_closed_at IS NOT NULL OR s.stack IS DISTINCT FROM p.chips::numeric
 OR s.stack IS NULL OR s.stack<=0 OR s.stack::text IN ('NaN','Infinity','-Infinity')))
 OR EXISTS(SELECT 1 FROM public.tournament_players p WHERE p.tournament_id=p_tournament_id AND p.table_id=p_table_id
 AND p.status IN ('playing','registered') AND NOT EXISTS(SELECT 1 FROM public.table_seats s WHERE s.table_id=p_table_id
 AND s.user_id=p.user_id AND s.seat_number=p.seat_number AND s.left_at IS NULL)) THEN
 RAISE EXCEPTION 'F06_WITHDRAWAL_ROSTER_CHANGED' USING ERRCODE='55000'; END IF;
 SELECT jsonb_agg(jsonb_build_object('seat_id',s.id,'occupancy_id',s.occupancy_id,'registration_id',p.id,
 'user_id',s.user_id,'joined_at',s.joined_at,'table_id',s.table_id,'seat_number',s.seat_number,'stack',s.stack,'chips',p.chips) ORDER BY s.user_id)
 INTO roster FROM public.table_seats s JOIN public.tournament_players p
 ON p.tournament_id=p_tournament_id AND p.user_id=s.user_id AND p.table_id=s.table_id AND p.seat_number=s.seat_number AND p.status='playing'
 WHERE s.table_id=p_table_id AND s.left_at IS NULL;
 IF roster IS NULL OR jsonb_array_length(roster) NOT BETWEEN 2 AND 10
 OR (SELECT count(DISTINCT x->>'user_id') FROM jsonb_array_elements(roster) x)<>jsonb_array_length(roster)
 OR EXISTS(SELECT 1 FROM public.hand_atomic_commits WHERE table_id=p_table_id AND hand_number>=unsealed)
 OR EXISTS(SELECT 1 FROM public.hand_history WHERE table_id=p_table_id AND hand_number>=unsealed)
 OR EXISTS(SELECT 1 FROM public.hand_private_state WHERE table_id=p_table_id AND hand_number>=unsealed)
 OR EXISTS(SELECT 1 FROM public.table_hole_cards WHERE table_id=p_table_id AND hand_number>=unsealed)
 OR EXISTS(SELECT 1 FROM public.hand_state_snapshots WHERE table_id=p_table_id AND NOT is_complete)
 OR (h.state='never_started' AND EXISTS(SELECT 1 FROM smarter_private.f06_hand_dispatch WHERE permit_id=h.permit_id)) THEN
 RAISE EXCEPTION 'F06_WITHDRAWAL_STARTED_OR_ROSTER_CHANGED' USING ERRCODE='55000'; END IF;
 -- The break cannot place this roster: the other open tables that hold
 -- players and are not themselves break sources have fewer free seats.
 SELECT count(*)::integer, COALESCE(sum(GREATEST(0,t.max_players-c.seated)),0),
 (count(*) FILTER (WHERE t.max_players IS NULL OR t.max_players<2))::integer
 INTO destinations, free_seats, unknown_capacity
 FROM public.tables t
 CROSS JOIN LATERAL (SELECT count(*)::integer AS seated FROM public.table_seats s
 WHERE s.table_id=t.id AND s.left_at IS NULL) c
 WHERE t.tournament_id=p_tournament_id AND t.id<>p_table_id
 AND lower(t.status) IN ('running','waiting','active') AND NOT COALESCE(t.is_deleted,false) AND c.seated>0
 AND NOT EXISTS(SELECT 1 FROM smarter_private.f06_operations x WHERE x.source_table_id=t.id
 AND x.state NOT IN ('acknowledged','withdrawn_before_manifest'));
 IF unknown_capacity>0 THEN RAISE EXCEPTION 'F06_WITHDRAWAL_CAPACITY_UNKNOWN' USING ERRCODE='55000'; END IF;
 IF free_seats>=jsonb_array_length(roster) THEN
 RAISE EXCEPTION 'F06_WITHDRAWAL_ROSTER_FITS' USING ERRCODE='55000'; END IF;
 -- The whole roster, proven exactly as any movement admission of this park
 -- proves it. Anything it cannot prove refuses here.
 movement:=smarter_private.f06_movement_prior(p_tournament_id,p_table_id);
 INSERT INTO smarter_private.f06_no_start_continuations
 (break_id,permit_id,tournament_id,table_id,lifecycle,hand_number,original_generation,current_generation,park,permit,roster,prior_committed)
 VALUES(o.break_id,h.permit_id,p_tournament_id,p_table_id,p_lifecycle,h.hand_number,o.origin_generation,p_lease_generation,to_jsonb(o),to_jsonb(h),roster,
 jsonb_build_object('kind','unplaceable_park_withdrawal','roster_size',jsonb_array_length(roster),
 'free_seats',free_seats,'destination_tables',destinations,'witness',h.state,'movement_prior',movement))
 RETURNING * INTO receipt;
 -- The receipt names the park's exact pre-image; f06_immutable_identity
 -- admits this one transition and makes it permanent.
 UPDATE smarter_private.f06_operations SET state='withdrawn_before_manifest',abort_receipt_id=receipt.receipt_id WHERE break_id=o.break_id;
 END IF;
 RETURN jsonb_build_object('ok',true,'state','withdrawn_unplaceable','receipt_id',receipt.receipt_id,
 'tournament_id',receipt.tournament_id,'table_id',receipt.table_id,'lifecycle',receipt.lifecycle::text,
 'break_id',receipt.break_id,'park_custody_id',receipt.park->>'custody_id','park_revision',receipt.park->>'revision',
 'lease_generation',receipt.current_generation,'original_generation',receipt.original_generation,
 'permit_id',receipt.permit_id,'hand_number',receipt.hand_number::text,
 'roster_size',(receipt.prior_committed->>'roster_size')::integer,'free_seats',(receipt.prior_committed->>'free_seats')::bigint,'credit',0);
END
$$;


ALTER FUNCTION public.fn_f06_withdraw_unplaceable_park(p_tournament_id uuid, p_lease_generation uuid, p_table_id uuid, p_lifecycle bigint, p_break_id uuid, p_park_custody_id uuid, p_park_revision bigint) OWNER TO postgres;

--
-- TOC entry 8145 (class 1255 OID 101363762)
-- Name: fn_fail_video_native_rendition(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fail_video_native_rendition(p_id uuid, p_worker text, p_claim_token uuid, p_code text) RETURNS public.video_native_renditions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE r public.video_native_renditions;
BEGIN
  IF coalesce(auth.role()::text,'')<>'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
  SELECT * INTO r FROM public.video_native_renditions WHERE id=p_id FOR UPDATE;
  IF r.status<>'processing' OR r.claimed_by IS DISTINCT FROM p_worker OR r.claim_token IS DISTINCT FROM p_claim_token OR p_code !~ '^[a-z0-9_]{3,80}$' THEN RAISE EXCEPTION 'native rendition failure custody mismatch'; END IF;
  UPDATE public.video_native_renditions SET status=CASE WHEN attempt_count>=5 THEN 'failed' ELSE 'queued' END,last_failure_code=p_code,next_attempt_at=CASE WHEN attempt_count>=5 THEN NULL ELSE now()+make_interval(mins=>least(60,power(2,attempt_count)::int)) END,claimed_by=NULL,claim_token=NULL,claimed_at=NULL,updated_at=now(),version=version+1 WHERE id=p_id RETURNING * INTO r; RETURN r;
END $_$;


ALTER FUNCTION public.fn_fail_video_native_rendition(p_id uuid, p_worker text, p_claim_token uuid, p_code text) OWNER TO postgres;

--
-- TOC entry 3548 (class 1255 OID 101363134)
-- Name: fn_fail_video_reel_candidate(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fail_video_reel_candidate(p_candidate_id uuid, p_worker text, p_failure_code text) RETURNS public.video_reel_candidates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v public.video_reel_candidates; attempts integer; code text;
BEGIN
  IF coalesce(auth.role()::text,'')<>'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
  SELECT * INTO v FROM public.video_reel_candidates WHERE id=p_candidate_id FOR UPDATE;
  IF v.id IS NULL OR v.status<>'generating' OR v.claimed_by IS DISTINCT FROM p_worker THEN RAISE EXCEPTION 'candidate custody mismatch'; END IF;
  code:=left(trim(both '_' FROM lower(regexp_replace(coalesce(p_failure_code,''),'[^a-zA-Z0-9_]+','_','g'))),120);
  IF code='' THEN code:='candidate_generation_failed'; END IF;
  attempts:=least(5,v.failure_count+1);
  UPDATE public.video_reel_candidates SET failure_count=attempts,last_failure_code=code,
    status=CASE WHEN attempts>=5 THEN 'rejected' ELSE 'generating' END,
    rejection_reason=CASE WHEN attempts>=5 THEN 'candidate_generation_failed:'||code ELSE rejection_reason END,
    rejected_at=CASE WHEN attempts>=5 THEN now() ELSE rejected_at END,
    claimed_by=NULL,claimed_at=NULL,
    next_attempt_at=CASE WHEN attempts>=5 THEN NULL ELSE now()+make_interval(secs=>least(3600,30*power(2,attempts-1))::integer) END,
    updated_at=now(),version=version+1 WHERE id=v.id RETURNING * INTO v;
  RETURN v;
END $$;


ALTER FUNCTION public.fn_fail_video_reel_candidate(p_candidate_id uuid, p_worker text, p_failure_code text) OWNER TO postgres;

--
-- TOC entry 9215 (class 1255 OID 16655137)
-- Name: fn_fee_is_accounted_for(text, uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fee_is_accounted_for(p_kind text, p_table_id uuid, p_hand_id uuid, p_hand_number bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    -- Cheapest check, and the one that is true most often.
    (p_hand_number > 0 AND EXISTS (
       SELECT 1 FROM public.pending_fee_distributions q
        WHERE q.table_id = p_table_id AND q.hand_number = p_hand_number
          AND q.kind = p_kind))
    OR CASE WHEN p_kind = 'rake' THEN
         (p_hand_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM public.rake_records r WHERE r.hand_id = p_hand_id))
         OR (p_hand_number > 0 AND EXISTS (
            SELECT 1 FROM public.rake_records r
             WHERE r.table_id = p_table_id AND r.global_hand_id = p_hand_number))
       ELSE
         (p_hand_number > 0 AND EXISTS (
            SELECT 1 FROM public.bbj_contributions b
             WHERE b.table_id = p_table_id AND b.hand_number = p_hand_number))
       END;
$$;


ALTER FUNCTION public.fn_fee_is_accounted_for(p_kind text, p_table_id uuid, p_hand_id uuid, p_hand_number bigint) OWNER TO postgres;

--
-- TOC entry 8543 (class 1255 OID 77390976)
-- Name: fn_feed_played_with(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_feed_played_with(p_viewer uuid, p_hands integer DEFAULT 200, p_cap integer DEFAULT 100) RETURNS TABLE(user_id uuid, shared_hands integer, last_seen timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH viewer_hands AS (
    SELECT v.hand_id
      FROM public.ca_hand_player_idx v
     WHERE v.user_id = p_viewer
     ORDER BY v.created_at DESC
     LIMIT GREATEST(COALESCE(p_hands, 200), 0)
  )
  SELECT o.user_id,
         count(*)::integer AS shared_hands,
         max(o.created_at) AS last_seen
    FROM viewer_hands vh
    JOIN public.ca_hand_player_idx o ON o.hand_id = vh.hand_id
   WHERE o.user_id <> p_viewer
   GROUP BY o.user_id
   ORDER BY max(o.created_at) DESC, o.user_id
   LIMIT GREATEST(COALESCE(p_cap, 100), 0)
$$;


ALTER FUNCTION public.fn_feed_played_with(p_viewer uuid, p_hands integer, p_cap integer) OWNER TO postgres;

