COMMENT ON FUNCTION public.fn_feed_played_with(p_viewer uuid, p_hands integer, p_cap integer) IS 'Service-role-only feed helper: the players who shared one of the last p_hands hands of the viewer (ca_hand_player_idx), with shared_hands and last_seen, newest first, at most p_cap rows. Horses and humans alike.';


--
-- TOC entry 9033 (class 1255 OID 83808663)
-- Name: fn_fence_welcome_package_schedule_spawn(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fence_welcome_package_schedule_spawn() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_retired timestamptz; v_active boolean;
BEGIN
  IF NEW.schedule_id IS NOT NULL THEN
    SELECT i.retired_at INTO v_retired FROM public.club_welcome_package_items i
     WHERE i.entity_kind='tournament_schedule' AND i.entity_id=NEW.schedule_id
     FOR KEY SHARE;
    IF FOUND THEN
      SELECT s.active INTO v_active FROM public.tournament_schedules s
       WHERE s.id=NEW.schedule_id FOR KEY SHARE;
      IF NOT FOUND OR v_retired IS NOT NULL OR v_active IS NOT TRUE THEN
        RAISE EXCEPTION 'WELCOME_PACKAGE_SCHEDULE_RETIRED' USING ERRCODE='55000';
      END IF;
    END IF;
  END IF;
  IF NEW.club_id IS NOT NULL
     AND upper(COALESCE(NEW.tournament_type::text,'')) IN('SPIN','SNG')
     AND EXISTS(SELECT 1 FROM public.club_welcome_package_receipts r WHERE r.club_id=NEW.club_id) THEN
    SELECT p.is_active INTO v_active FROM public.spin_bonus_pools p
     WHERE p.club_id=NEW.club_id FOR KEY SHARE;
    IF NOT FOUND OR v_active IS NOT TRUE THEN
      RAISE EXCEPTION 'WELCOME_PACKAGE_SPIN_BOARD_RETIRED' USING ERRCODE='55000';
    END IF;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_fence_welcome_package_schedule_spawn() OWNER TO postgres;

--
-- TOC entry 4031 (class 1255 OID 22493766)
-- Name: fn_filter_valid_user_video_storage_urls(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_filter_valid_user_video_storage_urls(p_candidates jsonb) RETURNS TABLE(playback_url text, author_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
  WITH bounded_input AS (
    SELECT CASE
      WHEN jsonb_typeof(COALESCE(p_candidates, '[]'::jsonb)) = 'array'
      THEN CASE
        WHEN jsonb_array_length(COALESCE(p_candidates, '[]'::jsonb)) <= 500
        THEN COALESCE(p_candidates, '[]'::jsonb)
        ELSE '[]'::jsonb
      END
      ELSE '[]'::jsonb
    END AS candidates
  ), parsed AS (
    SELECT candidate ->> 'playback_url' AS playback_url,
           CASE
             WHEN COALESCE(candidate ->> 'author_id', '') ~
               '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
             THEN (candidate ->> 'author_id')::uuid
             ELSE NULL
           END AS author_id
    FROM bounded_input
    CROSS JOIN LATERAL jsonb_array_elements(candidates) AS input(candidate)
    WHERE jsonb_typeof(candidate) = 'object'
  )
  SELECT DISTINCT parsed.playback_url, parsed.author_id
  FROM parsed
  WHERE parsed.playback_url IS NOT NULL
    AND parsed.author_id IS NOT NULL
    AND public.fn_is_user_video_storage_url(
      parsed.playback_url,
      parsed.author_id
    )
$_$;


