--
-- TOC entry 6136 (class 1255 OID 30231621)
-- Name: fn_finish_horse_adaptive_batch(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_finish_horse_adaptive_batch(p_batch_key text, p_lease_token uuid, p_outcome text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    SET lock_timeout TO '2s'
    AS $_$
DECLARE w public.horse_adaptive_journal_work%ROWTYPE;
BEGIN
  IF p_batch_key IS NULL OR p_batch_key !~ '^[a-f0-9]{64}$' OR p_lease_token IS NULL
     OR p_outcome IS NULL OR p_outcome NOT IN ('recorded','unknown','rejected') THEN
    RAISE EXCEPTION 'ADAPTIVE_WORK_INVALID_ACK';
  END IF;
  SELECT * INTO w FROM public.horse_adaptive_journal_work q WHERE q.batch_key=p_batch_key FOR UPDATE;
  IF NOT FOUND OR w.lease_token IS DISTINCT FROM p_lease_token THEN
    RETURN jsonb_build_object('version',1,'status','lease_lost','batchKey',p_batch_key);
  END IF;
  IF w.state='completed' AND p_outcome='recorded' THEN
    RETURN jsonb_build_object('version',1,'status','completed','batchKey',p_batch_key);
  END IF;
  IF w.state<>'leased' OR w.lease_until<=clock_timestamp() THEN
    RETURN jsonb_build_object('version',1,'status','lease_lost','batchKey',p_batch_key);
  END IF;
  IF p_outcome='recorded' THEN
    IF NOT EXISTS(SELECT 1 FROM public.horse_adaptive_observation_batches b
      WHERE b.batch_key=w.batch_key AND b.batch_digest=w.batch_digest
        AND b.observation_count=w.observations AND b.canonical_payload=w.payload) THEN
      RETURN jsonb_build_object('version',1,'status','receipt_unconfirmed','batchKey',p_batch_key);
    END IF;
    UPDATE public.horse_adaptive_journal_work q SET state='completed',payload=NULL,
      completed_at=clock_timestamp(),lease_until=NULL WHERE q.batch_key=p_batch_key;
    RETURN jsonb_build_object('version',1,'status','completed','batchKey',p_batch_key);
  ELSIF p_outcome='rejected' THEN
    UPDATE public.horse_adaptive_journal_work q SET state='quarantined',lease_token=NULL,lease_until=NULL
      WHERE q.batch_key=p_batch_key;
    RETURN jsonb_build_object('version',1,'status','quarantined','batchKey',p_batch_key);
  ELSE
    UPDATE public.horse_adaptive_journal_work q SET state='queued',lease_token=NULL,lease_until=NULL,
      available_at=clock_timestamp()+make_interval(secs=>least(60,power(2,least(w.attempts,6))::integer))
      WHERE q.batch_key=p_batch_key;
    RETURN jsonb_build_object('version',1,'status','deferred','batchKey',p_batch_key);
  END IF;
END
$_$;


ALTER FUNCTION public.fn_finish_horse_adaptive_batch(p_batch_key text, p_lease_token uuid, p_outcome text) OWNER TO postgres;

--
-- TOC entry 9200 (class 1255 OID 31381330)
-- Name: fn_finish_horse_journaled_model(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_finish_horse_journaled_model(p_lease_token uuid, p_report text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    SET lock_timeout TO '2s'
    AS $_$
DECLARE s public.horse_journaled_model_sweep%ROWTYPE; r jsonb; d text; n integer; evicted integer;
BEGIN
  IF p_lease_token IS NULL OR p_report IS NULL OR octet_length(p_report)>65536 THEN
    RAISE EXCEPTION 'MODEL_INVALID_REPORT'; END IF;
  r:=p_report::jsonb; d:=encode(sha256(convert_to(p_report,'UTF8')),'hex');
  SELECT * INTO s FROM public.horse_journaled_model_sweep WHERE singleton FOR UPDATE;
  IF s.completed_token=p_lease_token AND s.completed_digest=d THEN
    RETURN jsonb_build_object('version',1,'status','recorded','reportDigest',d); END IF;
  IF s.lease_token IS DISTINCT FROM p_lease_token OR s.lease_until<=statement_timestamp() THEN
    RETURN jsonb_build_object('version',1,'status','lease_lost'); END IF;
  IF jsonb_typeof(r) IS DISTINCT FROM 'object'
     OR r->>'version' IS DISTINCT FROM 'horse-journaled-model-report-v1'
     OR r->>'population' IS DISTINCT FROM 'journaled_qualified_observations'
     OR r->>'sourceCoverage' IS DISTINCT FROM 'not_established'
     OR r->'activationAuthorized' IS DISTINCT FROM 'false'::jsonb
     OR r->'causalEvEstablished' IS DISTINCT FROM 'false'::jsonb
     OR r->>'actorKey' IS DISTINCT FROM s.actor_key OR r->>'scopeKey' IS DISTINCT FROM s.scope_key
     OR r->'fromMs' IS DISTINCT FROM to_jsonb(s.from_ms) OR r->'toMs' IS DISTINCT FROM to_jsonb(s.to_ms)
     OR r->>'snapshotId' IS DISTINCT FROM s.snapshot_id OR r->>'evidenceDigest' IS DISTINCT FROM s.evidence_digest
     OR coalesce(r->>'sourceRelease','') !~ '^[a-f0-9]{40}$'
     OR r->>'priorPurpose' IS DISTINCT FROM 'unconditional_action_frequency_diagnostic'
     OR r->>'holdoutUse' IS DISTINCT FROM 'repeated_diagnostic_no_selection_correction'
     OR (r-ARRAY['version','sourceRelease','population','sourceCoverage','activationAuthorized','causalEvEstablished',
       'actorKey','scopeKey','fromMs','toMs','snapshotId','evidenceDigest','prior','priorPurpose','holdoutUse',
       'status','reason','observations','cohorts'])<>'{}'::jsonb THEN RAISE EXCEPTION 'MODEL_INVALID_REPORT'; END IF;
  IF s.population_status='snapshot' THEN
    IF r->>'status' IS DISTINCT FROM 'computed' OR jsonb_typeof(r->'cohorts') IS DISTINCT FROM 'array'
      THEN RAISE EXCEPTION 'MODEL_INVALID_REPORT'; END IF;
    IF jsonb_array_length(r->'cohorts')<>2 THEN RAISE EXCEPTION 'MODEL_INVALID_REPORT'; END IF;
  ELSE
    IF r->>'status' IS DISTINCT FROM 'refused' OR r->>'reason' IS DISTINCT FROM s.population_status
      OR r ? 'cohorts' THEN RAISE EXCEPTION 'MODEL_INVALID_REPORT'; END IF;
  END IF;
  -- Own diagnostic store only. Keep storage bounded without touching source
  -- retention, financial data or external owners. Expired records are not
  -- advertised as current models. This is a latest-report store, not history.
  DELETE FROM public.horse_journaled_opponent_models WHERE (actor_key,scope_key) IN (
    SELECT actor_key,scope_key FROM public.horse_journaled_opponent_models
    WHERE recorded_at<statement_timestamp()-interval '30 days' ORDER BY recorded_at LIMIT 25);
  IF NOT EXISTS(SELECT 1 FROM public.horse_journaled_opponent_models WHERE actor_key=s.actor_key AND scope_key=s.scope_key) THEN
    SELECT count(*) INTO n FROM (SELECT 1 FROM public.horse_journaled_opponent_models LIMIT 10000) q;
    IF n>=10000 THEN
      -- At the cap the oldest reports yield their slot, so a full store keeps
      -- turning over instead of refusing every new coordinate for good. The
      -- batch is bounded and amortises one eviction per admission; the row
      -- being admitted is absent by the enclosing test, so it is never a
      -- victim. Skipping locked candidates keeps concurrent finishes off each
      -- other's rows.
      WITH victim AS (
        SELECT m.actor_key,m.scope_key FROM public.horse_journaled_opponent_models m
        ORDER BY m.recorded_at,m.actor_key,m.scope_key LIMIT 25 FOR UPDATE SKIP LOCKED)
      DELETE FROM public.horse_journaled_opponent_models t USING victim v
        WHERE t.actor_key=v.actor_key AND t.scope_key=v.scope_key;
      GET DIAGNOSTICS evicted=ROW_COUNT;
      IF evicted=0 THEN
        UPDATE public.horse_journaled_model_sweep SET cursor_actor=s.actor_key,cursor_scope=s.scope_key,
          lease_token=NULL,lease_until=NULL,capacity_refusals=capacity_refusals+1,
          last_capacity_actor=s.actor_key,last_capacity_scope=s.scope_key WHERE singleton;
        RETURN jsonb_build_object('version',1,'status','capacity_full');
      END IF;
      UPDATE public.horse_journaled_model_sweep
        SET capacity_evictions=capacity_evictions+evicted WHERE singleton;
    END IF;
  END IF;
  INSERT INTO public.horse_journaled_opponent_models(actor_key,scope_key,report_digest,report_payload)
    VALUES(s.actor_key,s.scope_key,d,p_report)
    ON CONFLICT(actor_key,scope_key) DO UPDATE SET report_digest=excluded.report_digest,
      report_payload=excluded.report_payload,recorded_at=transaction_timestamp();
  UPDATE public.horse_journaled_model_sweep SET cursor_actor=s.actor_key,cursor_scope=s.scope_key,
    lease_token=NULL,lease_until=NULL,completed_token=p_lease_token,completed_digest=d WHERE singleton;
  RETURN jsonb_build_object('version',1,'status','recorded','reportDigest',d);
END $_$;


ALTER FUNCTION public.fn_finish_horse_journaled_model(p_lease_token uuid, p_report text) OWNER TO postgres;

--
-- TOC entry 7501 (class 1255 OID 153542079)
-- Name: fn_finish_horse_journaled_model_statistics(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_finish_horse_journaled_model_statistics(p_lease_token uuid, p_report text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    SET lock_timeout TO '2s'
    AS $_$
DECLARE s public.horse_journaled_model_sweep%ROWTYPE; r jsonb; d text; n integer; evicted integer;
BEGIN
  IF p_lease_token IS NULL OR p_report IS NULL OR octet_length(p_report)>65536 THEN
    RAISE EXCEPTION 'MODEL_INVALID_REPORT'; END IF;
  r:=p_report::jsonb; d:=encode(sha256(convert_to(p_report,'UTF8')),'hex');
  SELECT * INTO s FROM public.horse_journaled_model_sweep WHERE singleton FOR UPDATE;
  IF s.completed_token=p_lease_token AND s.completed_digest=d THEN
    RETURN jsonb_build_object('version',1,'status','recorded','reportDigest',d); END IF;
  IF s.lease_token IS DISTINCT FROM p_lease_token OR s.lease_until<=statement_timestamp() THEN
    RETURN jsonb_build_object('version',1,'status','lease_lost'); END IF;
  IF jsonb_typeof(r) IS DISTINCT FROM 'object'
     OR r->>'version' IS DISTINCT FROM 'horse-journaled-model-report-v2'
     OR r->>'population' IS DISTINCT FROM 'journaled_qualified_observations_and_disposed_statistics'
     OR r->>'sourceCoverage' IS DISTINCT FROM 'not_established'
     OR r->'activationAuthorized' IS DISTINCT FROM 'false'::jsonb
     OR r->'causalEvEstablished' IS DISTINCT FROM 'false'::jsonb
     OR r->>'actorKey' IS DISTINCT FROM s.actor_key OR r->>'scopeKey' IS DISTINCT FROM s.scope_key
     OR r->'fromMs' IS DISTINCT FROM to_jsonb(s.from_ms) OR r->'toMs' IS DISTINCT FROM to_jsonb(s.to_ms)
     OR r->>'snapshotId' IS DISTINCT FROM s.snapshot_id OR r->>'evidenceDigest' IS DISTINCT FROM s.evidence_digest
     OR coalesce(r->>'sourceRelease','') !~ '^[a-f0-9]{40}$'
     OR r->>'priorPurpose' IS DISTINCT FROM 'unconditional_action_frequency_diagnostic'
     OR r->>'holdoutUse' IS DISTINCT FROM 'repeated_diagnostic_no_selection_correction'
     OR (r-ARRAY['version','sourceRelease','population','sourceCoverage','activationAuthorized','causalEvEstablished',
       'actorKey','scopeKey','fromMs','toMs','snapshotId','evidenceDigest','prior','priorPurpose','holdoutUse',
       'status','reason','observations','cohorts'])<>'{}'::jsonb THEN RAISE EXCEPTION 'MODEL_INVALID_REPORT'; END IF;
  IF s.population_status='snapshot' THEN
    IF r->>'status' IS DISTINCT FROM 'computed' OR jsonb_typeof(r->'cohorts') IS DISTINCT FROM 'array'
      THEN RAISE EXCEPTION 'MODEL_INVALID_REPORT'; END IF;
    IF jsonb_array_length(r->'cohorts')<>2 THEN RAISE EXCEPTION 'MODEL_INVALID_REPORT'; END IF;
  ELSE
    IF r->>'status' IS DISTINCT FROM 'refused' OR r->>'reason' IS DISTINCT FROM s.population_status
      OR r ? 'cohorts' THEN RAISE EXCEPTION 'MODEL_INVALID_REPORT'; END IF;
  END IF;
  -- Own diagnostic store only. Keep storage bounded without touching source
  -- retention, financial data or external owners. Expired records are not
  -- advertised as current models. This is a latest-report store, not history.
  DELETE FROM public.horse_journaled_opponent_models WHERE (actor_key,scope_key) IN (
    SELECT actor_key,scope_key FROM public.horse_journaled_opponent_models
    WHERE recorded_at<statement_timestamp()-interval '30 days' ORDER BY recorded_at LIMIT 25);
  IF NOT EXISTS(SELECT 1 FROM public.horse_journaled_opponent_models WHERE actor_key=s.actor_key AND scope_key=s.scope_key) THEN
    SELECT count(*) INTO n FROM (SELECT 1 FROM public.horse_journaled_opponent_models LIMIT 10000) q;
    IF n>=10000 THEN
      -- At the cap the oldest reports yield their slot, so a full store keeps
      -- turning over instead of refusing every new coordinate for good. The
      -- batch is bounded and amortises one eviction per admission; the row
      -- being admitted is absent by the enclosing test, so it is never a
      -- victim. Skipping locked candidates keeps concurrent finishes off each
      -- other's rows.
      WITH victim AS (
        SELECT m.actor_key,m.scope_key FROM public.horse_journaled_opponent_models m
        ORDER BY m.recorded_at,m.actor_key,m.scope_key LIMIT 25 FOR UPDATE SKIP LOCKED)
      DELETE FROM public.horse_journaled_opponent_models t USING victim v
        WHERE t.actor_key=v.actor_key AND t.scope_key=v.scope_key;
      GET DIAGNOSTICS evicted=ROW_COUNT;
      IF evicted=0 THEN
        UPDATE public.horse_journaled_model_sweep SET cursor_actor=s.actor_key,cursor_scope=s.scope_key,
          lease_token=NULL,lease_until=NULL,capacity_refusals=capacity_refusals+1,
          last_capacity_actor=s.actor_key,last_capacity_scope=s.scope_key WHERE singleton;
        RETURN jsonb_build_object('version',1,'status','capacity_full');
      END IF;
      UPDATE public.horse_journaled_model_sweep
        SET capacity_evictions=capacity_evictions+evicted WHERE singleton;
    END IF;
  END IF;
  INSERT INTO public.horse_journaled_opponent_models(actor_key,scope_key,report_digest,report_payload)
    VALUES(s.actor_key,s.scope_key,d,p_report)
    ON CONFLICT(actor_key,scope_key) DO UPDATE SET report_digest=excluded.report_digest,
      report_payload=excluded.report_payload,recorded_at=transaction_timestamp();
  UPDATE public.horse_journaled_model_sweep SET cursor_actor=s.actor_key,cursor_scope=s.scope_key,
    lease_token=NULL,lease_until=NULL,completed_token=p_lease_token,completed_digest=d WHERE singleton;
  RETURN jsonb_build_object('version',1,'status','recorded','reportDigest',d);
END $_$;


ALTER FUNCTION public.fn_finish_horse_journaled_model_statistics(p_lease_token uuid, p_report text) OWNER TO postgres;

--
-- TOC entry 7004 (class 1255 OID 30812786)
-- Name: fn_finish_horse_observation_capture(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_finish_horse_observation_capture(p_request_key text, p_lease_token uuid, p_payload text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    SET lock_timeout TO '2s'
    AS $_$
DECLARE r public.horse_observation_capture_work%ROWTYPE; prior public.horse_observation_capture_receipts%ROWTYPE;
  b jsonb; queued jsonb; actor_key text; fingerprint text; v_reason text; first_ms bigint; last_ms bigint;
  next_ms bigint; n integer; total bigint; new_state text; ack jsonb;
BEGIN
  IF p_request_key IS NULL OR p_request_key !~ '^[a-f0-9]{64}$' OR p_lease_token IS NULL
     OR octet_length(p_payload)>16777216 THEN RAISE EXCEPTION 'HORSE_CAPTURE_INVALID_FINISH'; END IF;
  SELECT * INTO r FROM public.horse_observation_capture_work w WHERE w.request_key=p_request_key FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('version',1,'status','lease_lost','requestKey',p_request_key); END IF;
  IF p_payload IS NOT NULL THEN
    fingerprint:=encode(sha256(convert_to(p_payload,'UTF8')),'hex');
    SELECT * INTO prior FROM public.horse_observation_capture_receipts s
      WHERE s.request_key=p_request_key AND s.lease_token=p_lease_token;
    IF FOUND THEN
      IF prior.payload_digest IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'HORSE_CAPTURE_BATCH_CONFLICT'; END IF;
      RETURN prior.acknowledgment;
    END IF;
  END IF;
  IF r.lease_token IS DISTINCT FROM p_lease_token THEN
    RETURN jsonb_build_object('version',1,'status','lease_lost','requestKey',p_request_key);
  END IF;
  first_ms:=coalesce(r.cursor_ms,r.from_ms); last_ms:=coalesce(r.slice_through_ms,r.through_ms);
  IF p_payload IS NOT NULL THEN
    b:=p_payload::jsonb;
    actor_key:=encode(sha256(convert_to(format('["adaptive-actor-v1","%s"]',r.actor_id),'UTF8')),'hex');
    -- Exact pre-upgrade receipts remain replayable without another enqueue.
    IF r.state='admitted' AND r.segments=0 THEN
      IF r.batch_digest IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'HORSE_CAPTURE_BATCH_CONFLICT'; END IF;
      RETURN jsonb_build_object('version',1,'status','admitted','requestKey',p_request_key,
        'batchKey',r.batch_key,'batchDigest',r.batch_digest,'observations',r.observations);
    END IF;
    IF jsonb_typeof(b) IS DISTINCT FROM 'array' OR jsonb_array_length(b)<>8
      OR b->0 IS DISTINCT FROM '1'::jsonb OR b->>2 IS DISTINCT FROM actor_key
      OR b->>3 IS DISTINCT FROM first_ms::text OR b->>4 IS DISTINCT FROM last_ms::text THEN
      RAISE EXCEPTION 'HORSE_CAPTURE_SCOPE_MISMATCH';
    END IF;
  END IF;
  IF r.state<>'leased' OR r.lease_until<=clock_timestamp() THEN
    RETURN jsonb_build_object('version',1,'status','lease_lost','requestKey',p_request_key);
  END IF;
  IF p_payload IS NOT NULL THEN
    IF r.segments>=2048 THEN RAISE EXCEPTION 'HORSE_CAPTURE_SEGMENT_BUDGET'; END IF;
    queued:=public.fn_queue_horse_adaptive_batch(p_payload);
    IF queued->>'status'='durable' AND queued->>'batchDigest'=fingerprint
      AND queued->>'batchKey'=b->>1 AND (queued->>'observations')::integer=jsonb_array_length(b->7) THEN
      n:=r.segments+1; total:=r.captured_observations+(queued->>'observations')::integer;
      next_ms:=least(r.through_ms,last_ms+2*(last_ms-first_ms));
      new_state:=CASE WHEN last_ms<r.through_ms THEN 'queued' WHEN n=1 THEN 'admitted' ELSE 'captured' END;
      ack:=jsonb_build_object('version',1,'status',CASE WHEN new_state='queued' THEN 'continued' ELSE new_state END,
        'requestKey',p_request_key,'batchKey',queued->>'batchKey','batchDigest',fingerprint,'observations',queued->'observations',
        'sliceFromMs',first_ms,'sliceThroughMs',last_ms,'nextFromMs',last_ms,'nextThroughMs',next_ms,
        'segments',n,'capturedObservations',total);
      INSERT INTO public.horse_observation_capture_receipts(request_key,lease_token,from_ms,through_ms,payload_digest,acknowledgment)
        VALUES(p_request_key,p_lease_token,first_ms,last_ms,fingerprint,ack);
      UPDATE public.horse_observation_capture_work SET state=new_state,cursor_ms=last_ms,slice_through_ms=next_ms,
        segments=n,captured_observations=total,
        batch_key=CASE WHEN new_state='admitted' THEN queued->>'batchKey' ELSE NULL END,
        batch_digest=CASE WHEN new_state='admitted' THEN fingerprint ELSE NULL END,
        observations=CASE WHEN new_state='admitted' THEN (queued->>'observations')::integer ELSE NULL END,
        admitted_at=CASE WHEN new_state IN ('admitted','captured') THEN clock_timestamp() ELSE NULL END,
        lease_until=NULL,reason=NULL,available_at=clock_timestamp() WHERE request_key=p_request_key;
      RETURN ack;
    END IF;
    v_reason:=CASE WHEN queued->>'reason' IN ('queue_full','capacity_busy') THEN queued->>'reason' ELSE 'queue_unavailable' END;
  ELSE v_reason:=CASE WHEN p_reason IN ('source_budget_exceeded','invalid_source') THEN p_reason ELSE 'source_unavailable' END;
  END IF;
  IF v_reason='source_budget_exceeded' AND last_ms-first_ms>1 THEN
    next_ms:=first_ms+(last_ms-first_ms)/2;
    UPDATE public.horse_observation_capture_work SET state='queued',slice_through_ms=next_ms,lease_until=NULL,
      reason='source_budget_refined',available_at=clock_timestamp() WHERE request_key=p_request_key;
    RETURN jsonb_build_object('version',1,'status','refined','requestKey',p_request_key,
      'nextFromMs',first_ms,'nextThroughMs',next_ms);
  END IF;
  IF v_reason IN ('source_budget_exceeded','invalid_source') THEN
    UPDATE public.horse_observation_capture_work SET state='gap',reason=v_reason,lease_until=NULL WHERE request_key=p_request_key;
    RETURN jsonb_build_object('version',1,'status','gap','requestKey',p_request_key,'reason',v_reason);
  END IF;
  UPDATE public.horse_observation_capture_work SET state='queued',reason=v_reason,lease_until=NULL,
    available_at=clock_timestamp()+make_interval(secs=>least(60,power(2,least(r.attempts,6))::integer)) WHERE request_key=p_request_key;
  RETURN jsonb_build_object('version',1,'status','deferred','requestKey',p_request_key,'reason',v_reason);
END;
$_$;


ALTER FUNCTION public.fn_finish_horse_observation_capture(p_request_key text, p_lease_token uuid, p_payload text, p_reason text) OWNER TO postgres;

--
-- TOC entry 4297 (class 1255 OID 30908199)
-- Name: fn_finish_horse_observation_capture_witness(text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_finish_horse_observation_capture_witness(p_request_key text, p_lease_token uuid, p_payload text, p_reason text, p_source_witness text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    SET lock_timeout TO '2s'
    AS $_$
DECLARE w jsonb; b jsonb; r public.horse_observation_capture_work%ROWTYPE;
  prior public.horse_observation_capture_receipts%ROWTYPE;
  result jsonb; fingerprint text; source_fingerprint text; i integer;
BEGIN
  IF p_payload IS NULL THEN
    IF p_source_witness IS NOT NULL THEN RAISE EXCEPTION 'HORSE_SOURCE_WITNESS_WITHOUT_BATCH'; END IF;
    RETURN public.fn_finish_horse_observation_capture(p_request_key,p_lease_token,NULL,p_reason);
  END IF;
  IF p_request_key IS NULL OR p_request_key !~ '^[a-f0-9]{64}$' OR p_lease_token IS NULL
    OR octet_length(p_payload)>16777216 OR p_source_witness IS NULL
    OR octet_length(p_source_witness)>8192 THEN RAISE EXCEPTION 'HORSE_SOURCE_WITNESS_INVALID'; END IF;
  w:=p_source_witness::jsonb; b:=p_payload::jsonb;
  IF jsonb_typeof(w) IS DISTINCT FROM 'array' OR jsonb_array_length(w)<>11
    OR w->0 IS DISTINCT FROM '1'::jsonb OR w->>9 IS DISTINCT FROM 'retained_committed_roster_rows'
    OR w->>10 IS DISTINCT FROM 'atomic_hand_receipts'
    OR jsonb_typeof(b) IS DISTINCT FROM 'array' OR jsonb_array_length(b)<>8 OR b->0 IS DISTINCT FROM '1'::jsonb
    OR w->>1 IS DISTINCT FROM b->>2 OR w->>2 IS DISTINCT FROM b->>3 OR w->>3 IS DISTINCT FROM b->>4
    OR w->>8 IS DISTINCT FROM b->>5
    OR coalesce(w->>1,'') !~ '^[a-f0-9]{64}$' OR coalesce(w->>8,'') !~ '^[a-f0-9]{64}$'
    OR jsonb_typeof(w->5) IS DISTINCT FROM 'string'
    OR coalesce(w->>5,'') !~ '^[0-9]+:[0-9]+:([0-9]+(,[0-9]+)*)?$' THEN
    RAISE EXCEPTION 'HORSE_SOURCE_WITNESS_SCOPE_INVALID';
  END IF;
  FOREACH i IN ARRAY ARRAY[2,3,4,6,7] LOOP
    IF jsonb_typeof(w->i) IS DISTINCT FROM 'number' OR (w->>i) !~ '^(0|[1-9][0-9]*)$'
      OR (w->>i)::numeric>9007199254740991 THEN RAISE EXCEPTION 'HORSE_SOURCE_WITNESS_NUMBER_INVALID'; END IF;
  END LOOP;
  IF (w->>3)::bigint<=(w->>2)::bigint OR (w->>3)::bigint-(w->>2)::bigint>21600000
    OR (w->>4)::bigint<(w->>3)::bigint OR (w->>2)::bigint<(w->>4)::bigint-86400000
    OR (w->>6)::integer>512 OR (w->>7)::bigint>8388608 THEN RAISE EXCEPTION 'HORSE_SOURCE_WITNESS_BUDGET'; END IF;
  -- Check the actual PostgreSQL snapshot vocabulary as well as text bounds.
  PERFORM (w->>5)::pg_snapshot;
  fingerprint:=encode(sha256(convert_to(p_payload,'UTF8')),'hex');
  source_fingerprint:=encode(sha256(convert_to(p_source_witness,'UTF8')),'hex');
  SELECT * INTO r FROM public.horse_observation_capture_work WHERE request_key=p_request_key FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('version',1,'status','lease_lost','requestKey',p_request_key); END IF;
  SELECT * INTO prior FROM public.horse_observation_capture_receipts
    WHERE request_key=p_request_key AND lease_token=p_lease_token;
  IF FOUND THEN
    IF prior.payload_digest IS DISTINCT FROM fingerprint THEN RAISE EXCEPTION 'HORSE_CAPTURE_BATCH_CONFLICT'; END IF;
    IF prior.source_witness IS NULL THEN RAISE EXCEPTION 'HORSE_SOURCE_WITNESS_UNAVAILABLE'; END IF;
    IF prior.source_witness_digest IS DISTINCT FROM source_fingerprint
      OR prior.source_witness IS DISTINCT FROM p_source_witness THEN RAISE EXCEPTION 'HORSE_SOURCE_WITNESS_CONFLICT'; END IF;
    RETURN prior.acknowledgment;
  END IF;
  -- Dynamic clock checks apply only to a new write. Exact committed receipts
  -- remain replayable if the wall clock later moves backwards.
  IF (w->>4)::bigint>floor(extract(epoch FROM clock_timestamp())*1000)::bigint THEN
    RAISE EXCEPTION 'HORSE_SOURCE_WITNESS_FUTURE';
  END IF;
  result:=public.fn_finish_horse_observation_capture(p_request_key,p_lease_token,p_payload,p_reason);
  IF result->>'status' IN ('admitted','continued','captured') THEN
    -- A historical pre-slice admission is not evidence of this new source read.
    IF r.state<>'leased' OR r.lease_token IS DISTINCT FROM p_lease_token THEN
      RAISE EXCEPTION 'HORSE_SOURCE_WITNESS_UNAVAILABLE';
    END IF;
    result:=result||jsonb_build_object('sourceWitnessDigest',source_fingerprint);
    UPDATE public.horse_observation_capture_receipts
      SET source_witness=p_source_witness,source_witness_digest=source_fingerprint,acknowledgment=result
      WHERE request_key=p_request_key AND lease_token=p_lease_token
        AND payload_digest=fingerprint AND source_witness IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'HORSE_SOURCE_WITNESS_NOT_RECORDED'; END IF;
  END IF;
  RETURN result;
END;
$_$;


ALTER FUNCTION public.fn_finish_horse_observation_capture_witness(p_request_key text, p_lease_token uuid, p_payload text, p_reason text, p_source_witness text) OWNER TO postgres;

--
-- TOC entry 7343 (class 1255 OID 92756363)
-- Name: fn_finish_video_enrichment_job(uuid, text, boolean, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_finish_video_enrichment_job(p_job_id uuid, p_worker text, p_succeeded boolean, p_output jsonb DEFAULT '{}'::jsonb, p_failure_code text DEFAULT NULL::text, p_failure_detail text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_job public.video_enrichment_jobs; v_status text;
BEGIN
  IF coalesce(auth.role()::text,'') <> 'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_job FROM public.video_enrichment_jobs WHERE id=p_job_id FOR UPDATE;
  IF v_job.id IS NULL OR v_job.status <> 'running' OR v_job.locked_by IS DISTINCT FROM p_worker THEN RAISE EXCEPTION 'job custody mismatch'; END IF;
  v_status := CASE WHEN p_succeeded THEN 'succeeded' WHEN v_job.attempt_count >= v_job.max_attempts THEN 'dead_letter' ELSE 'retry' END;
  UPDATE public.video_enrichment_jobs SET status=v_status,output=CASE WHEN p_succeeded THEN coalesce(p_output,'{}') ELSE output END,
    failure_code=CASE WHEN p_succeeded THEN NULL ELSE left(coalesce(p_failure_code,'unknown'),120) END,
    failure_detail=CASE WHEN p_succeeded THEN NULL ELSE left(coalesce(p_failure_detail,''),1000) END,
    available_at=CASE WHEN v_status='retry' THEN now()+make_interval(secs => least(3600,30*(2^least(v_job.attempt_count,7)))) ELSE available_at END,
    completed_at=CASE WHEN v_status IN ('succeeded','dead_letter') THEN now() ELSE NULL END,
    locked_at=NULL,locked_by=NULL,updated_at=now() WHERE id=p_job_id;
  RETURN v_status;
END $$;


ALTER FUNCTION public.fn_finish_video_enrichment_job(p_job_id uuid, p_worker text, p_succeeded boolean, p_output jsonb, p_failure_code text, p_failure_detail text) OWNER TO postgres;

--
-- TOC entry 3923 (class 1255 OID 101363760)
-- Name: fn_finish_video_native_rendition(uuid, text, uuid, text, text, text, bigint, numeric, integer, integer, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_finish_video_native_rendition(p_id uuid, p_worker text, p_claim_token uuid, p_output_path text, p_poster_path text, p_sha256 text, p_bytes bigint, p_duration numeric, p_width integer, p_height integer, p_video_codec text, p_audio_codec text, p_validation jsonb) RETURNS public.video_native_renditions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE r public.video_native_renditions; lim public.video_native_studio_limits;
BEGIN
  IF coalesce(auth.role()::text,'')<>'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
  SELECT * INTO r FROM public.video_native_renditions WHERE id=p_id FOR UPDATE; SELECT * INTO lim FROM public.video_native_studio_limits WHERE singleton=true;
  IF r.status<>'processing' OR r.claimed_by IS DISTINCT FROM p_worker OR r.claim_token IS DISTINCT FROM p_claim_token THEN RAISE EXCEPTION 'native rendition custody mismatch'; END IF;
  IF p_output_path IS DISTINCT FROM format('%s/%s.mp4',r.candidate_id,r.id) OR p_poster_path IS DISTINCT FROM format('%s/%s.jpg',r.candidate_id,r.id) OR p_sha256 !~ '^[0-9a-f]{64}$' OR p_bytes NOT BETWEEN 1024 AND lim.max_output_bytes OR p_duration<=0 OR p_duration>180 OR p_width<>1080 OR p_height<>1920 OR p_video_codec<>'h264' OR p_audio_codec NOT IN ('aac','none') OR jsonb_typeof(p_validation)<>'object' THEN RAISE EXCEPTION 'native rendition output validation failed'; END IF;
  UPDATE public.video_native_renditions SET status='ready',output_bucket='video-reels-native',output_path=p_output_path,poster_path=p_poster_path,output_sha256=p_sha256,output_bytes=p_bytes,output_duration_seconds=p_duration,output_width=p_width,output_height=p_height,video_codec=p_video_codec,audio_codec=p_audio_codec,validation=p_validation,completed_at=now(),claimed_by=NULL,claim_token=NULL,claimed_at=NULL,next_attempt_at=NULL,last_failure_code=NULL,updated_at=now(),version=version+1 WHERE id=p_id RETURNING * INTO r; RETURN r;
END $_$;


