--
-- TOC entry 9202 (class 1255 OID 61102639)
-- Name: fn_fresh_public_youtube_verification_ids(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fresh_public_youtube_verification_ids(p_youtube_video_ids text[]) RETURNS TABLE(youtube_video_id text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
BEGIN
  IF COALESCE(auth.role()::text, '') <> 'service_role' THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'fn_fresh_public_youtube_verification_ids requires the service role';
  END IF;

  IF COALESCE(cardinality(p_youtube_video_ids), 0) > 1000 THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'at most 1000 YouTube video ids may be checked at once';
  END IF;

  RETURN QUERY
  SELECT DISTINCT candidate.video_id AS youtube_video_id
  FROM (
    SELECT btrim(candidate.raw_video_id) AS video_id
    FROM unnest(COALESCE(p_youtube_video_ids, ARRAY[]::text[]))
      AS candidate(raw_video_id)
  ) AS candidate
  WHERE candidate.video_id ~ '^[A-Za-z0-9_-]{11}$'
    AND public.fn_has_fresh_public_youtube_verification(candidate.video_id)
  ORDER BY candidate.video_id;
END
$_$;


ALTER FUNCTION public.fn_fresh_public_youtube_verification_ids(p_youtube_video_ids text[]) OWNER TO postgres;

--
-- TOC entry 3440 (class 1255 OID 13929517)
-- Name: fn_game_creation_access(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_game_creation_access(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user   uuid := auth.uid();
  v_own    uuid;
  v_member uuid;
  v_union  uuid;
  v_ok     boolean;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'union_id', NULL, 'reason', 'not_signed_in');
  END IF;
  IF p_club_id IS NULL OR NOT EXISTS (SELECT 1 FROM clubs c WHERE c.id = p_club_id) THEN
    RETURN jsonb_build_object('allowed', false, 'union_id', NULL, 'reason', 'unknown_club');
  END IF;

  SELECT own_union_id, member_union_id INTO v_own, v_member
    FROM fn_club_union_context(p_club_id);

  v_ok := fn_can_create_games(p_club_id, v_user);

  SELECT u.id INTO v_union FROM unions u WHERE u.id = COALESCE(v_own, v_member);

  RETURN jsonb_build_object(
    'allowed',  v_ok,
    'union_id', v_union,
    'reason',   CASE WHEN v_ok THEN 'ok'
                     WHEN v_member IS NOT NULL THEN 'union_only'
                     ELSE 'not_owner_or_admin' END
  );
END;
$$;


