--
-- TOC entry 4996 (class 1255 OID 8912025)
-- Name: fn_generate_all_credit_invoices(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_generate_all_credit_invoices(p_period_end timestamp with time zone DEFAULT date_trunc('week'::text, now())) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
 v_agent record; v_available numeric; v_res jsonb;
 v_generated int:=0; v_duplicate int:=0; v_skipped int:=0;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_period_end IS NULL OR NOT isfinite(p_period_end) OR p_period_end>now() THEN
   RAISE EXCEPTION 'invalid_period_end' USING ERRCODE='22023';
 END IF;
 FOR v_agent IN SELECT id,credit_used FROM public.agents
   WHERE NOT COALESCE(is_prepaid,false) AND credit_used>0 ORDER BY id FOR UPDATE
 LOOP
   IF v_agent.credit_used::text IN ('NaN','Infinity','-Infinity') OR v_agent.credit_used<>round(v_agent.credit_used,2) THEN
     RAISE EXCEPTION 'invalid_drawn_credit' USING ERRCODE='23514';
   END IF;
   IF EXISTS(SELECT 1 FROM public.credit_invoices WHERE agent_id=v_agent.id AND period_end=p_period_end) THEN
     v_duplicate:=v_duplicate+1; CONTINUE;
   END IF;
   SELECT v_agent.credit_used-COALESCE(sum(amount_remaining),0) INTO v_available
     FROM public.credit_invoices WHERE agent_id=v_agent.id AND status IN ('pending','partial','overdue','disputed');
   IF v_available<0 THEN RAISE EXCEPTION 'credit_debt_overinvoiced' USING ERRCODE='23514'; END IF;
   IF v_available=0 THEN v_skipped:=v_skipped+1; CONTINUE; END IF;
   v_res:=public.fn_generate_credit_invoice(v_agent.id,p_period_end-interval '7 days',p_period_end,v_available,p_period_end+interval '2 days');
   IF NOT COALESCE((v_res->>'success')::boolean,false) THEN
     RAISE EXCEPTION 'credit_invoice_generation_failed' USING ERRCODE='P0001',DETAIL=v_res::text;
   END IF;
   IF COALESCE((v_res->>'duplicate')::boolean,false) THEN v_duplicate:=v_duplicate+1;
   ELSE v_generated:=v_generated+1; END IF;
 END LOOP;
 RETURN jsonb_build_object('success',true,'generated',v_generated,'duplicate',v_duplicate,'failed',0,'skipped',v_skipped,'period_end',p_period_end);
END $$;


ALTER FUNCTION public.fn_generate_all_credit_invoices(p_period_end timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 3964 (class 1255 OID 8902921)
-- Name: fn_generate_credit_invoice(uuid, timestamp with time zone, timestamp with time zone, numeric, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_generate_credit_invoice(p_agent_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_debt_owed numeric, p_due_date timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
 v_agent public.agents%ROWTYPE;
 v_row public.credit_invoices%ROWTYPE;
 v_invoiced numeric;
 v_available numeric;
BEGIN
 IF p_agent_id IS NULL THEN RAISE EXCEPTION 'agent_required' USING ERRCODE='22023'; END IF;
 SELECT * INTO v_agent FROM public.agents WHERE id=p_agent_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'agent_not_found' USING ERRCODE='22023'; END IF;
 IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR
   (auth.uid()<>v_agent.user_id AND NOT public.fn_is_platform_admin()
    AND NOT public.fn_is_club_admin_uid(v_agent.club_id))) THEN
   RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501';
 END IF;
 IF p_period_start IS NULL OR p_period_end IS NULL OR p_due_date IS NULL
   OR NOT isfinite(p_period_start) OR NOT isfinite(p_period_end) OR NOT isfinite(p_due_date)
   OR p_period_start>=p_period_end OR p_period_end>now() OR p_due_date<p_period_end
   OR p_debt_owed IS NULL OR p_debt_owed::text IN ('NaN','Infinity','-Infinity')
   OR p_debt_owed<=0 OR p_debt_owed<>round(p_debt_owed,2) THEN
   RAISE EXCEPTION 'invalid_credit_invoice_terms' USING ERRCODE='22023';
 END IF;
 -- An issued document is immutable. Replay returns its original terms.
 SELECT * INTO v_row FROM public.credit_invoices WHERE agent_id=p_agent_id AND period_end=p_period_end;
 IF FOUND THEN RETURN jsonb_build_object('success',true,'duplicate',true,'invoice',to_jsonb(v_row)); END IF;
 IF COALESCE(v_agent.is_prepaid,false) THEN
   RETURN jsonb_build_object('success',false,'error','prepaid_agent');
 END IF;
 IF v_agent.credit_used IS NULL OR v_agent.credit_used::text IN ('NaN','Infinity','-Infinity')
   OR v_agent.credit_used<0 OR v_agent.credit_used<>round(v_agent.credit_used,2) THEN
   RAISE EXCEPTION 'invalid_drawn_credit' USING ERRCODE='23514';
 END IF;
 SELECT COALESCE(sum(amount_remaining),0) INTO v_invoiced FROM public.credit_invoices
   WHERE agent_id=p_agent_id AND status IN ('pending','partial','overdue','disputed');
 v_available:=v_agent.credit_used-v_invoiced;
 IF v_available<p_debt_owed THEN
   RETURN jsonb_build_object('success',false,'error','debt_already_invoiced_or_not_drawn',
     'credit_used',v_agent.credit_used,'already_invoiced',v_invoiced,'available',v_available);
 END IF;
 INSERT INTO public.credit_invoices(agent_id,period_start,period_end,debt_owed,amount_paid,amount_remaining,status,due_date)
 VALUES(p_agent_id,p_period_start,p_period_end,p_debt_owed,0,p_debt_owed,'pending',p_due_date)
 RETURNING * INTO v_row;
 RETURN jsonb_build_object('success',true,'duplicate',false,'invoice',to_jsonb(v_row));
END $$;


ALTER FUNCTION public.fn_generate_credit_invoice(p_agent_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_debt_owed numeric, p_due_date timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 6942 (class 1255 OID 4632587)
-- Name: fn_generate_recurring_home_games(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_generate_recurring_home_games() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group       RECORD;
    v_generated   int := 0;
    v_skipped     int := 0;
    v_target_date date;
    v_week        int;
    v_interval    interval;
    v_day_number  int;  -- 0=Sun..6=Sat
    v_weeks_max   int;
    v_new_game_id uuid;
BEGIN
    FOR v_group IN
        SELECT g.*, grp_sp.slug
          FROM commander_home_groups g
          LEFT JOIN social_pages grp_sp ON grp_sp.linked_entity_type='home_group' AND grp_sp.linked_entity_id=g.id::text
         WHERE g.is_active = true
           AND g.auto_generate_games = true
           AND g.frequency IN ('weekly','biweekly','monthly')
           AND g.typical_day IS NOT NULL
           AND g.typical_time IS NOT NULL
           AND g.last_activity_at > NOW() - INTERVAL '60 days'  -- skip dead groups
    LOOP
        -- Map typical_day text to day-number (0=Sunday..6=Saturday)
        v_day_number := CASE lower(v_group.typical_day)
            WHEN 'sunday' THEN 0 WHEN 'sun' THEN 0
            WHEN 'monday' THEN 1 WHEN 'mon' THEN 1
            WHEN 'tuesday' THEN 2 WHEN 'tue' THEN 2 WHEN 'tues' THEN 2
            WHEN 'wednesday' THEN 3 WHEN 'wed' THEN 3
            WHEN 'thursday' THEN 4 WHEN 'thu' THEN 4 WHEN 'thurs' THEN 4
            WHEN 'friday' THEN 5 WHEN 'fri' THEN 5
            WHEN 'saturday' THEN 6 WHEN 'sat' THEN 6
            ELSE NULL END;
        
        IF v_day_number IS NULL THEN 
            v_skipped := v_skipped + 1; 
            CONTINUE; 
        END IF;

        v_interval := CASE v_group.frequency
            WHEN 'weekly'   THEN INTERVAL '7 days'
            WHEN 'biweekly' THEN INTERVAL '14 days'
            WHEN 'monthly'  THEN INTERVAL '28 days'
            ELSE INTERVAL '7 days' END;

        v_weeks_max := COALESCE(v_group.auto_generate_weeks_ahead, 4);

        -- Find first target date: next occurrence of day_number starting tomorrow
        v_target_date := CURRENT_DATE + 1;
        WHILE EXTRACT(DOW FROM v_target_date)::int <> v_day_number LOOP
            v_target_date := v_target_date + 1;
        END LOOP;

        -- Generate for each cycle up to weeks_ahead
        FOR v_week IN 1..v_weeks_max LOOP
            -- Skip if a game already exists for this group on this date
            IF EXISTS (
                SELECT 1 FROM commander_home_games 
                 WHERE group_id = v_group.id 
                   AND scheduled_date = v_target_date
                   AND status NOT IN ('cancelled')
            ) THEN
                v_skipped := v_skipped + 1;
            ELSE
                INSERT INTO commander_home_games (
                    group_id, host_id, title, 
                    game_type, stakes, format,
                    buyin_min, buyin_max,
                    scheduled_date, start_time, 
                    max_players, 
                    status,
                    address_visible_to
                ) VALUES (
                    v_group.id, v_group.owner_id,
                    v_group.name || ' - ' || to_char(v_target_date, 'Mon DD'),
                    v_group.default_game_type, v_group.default_stakes, 'cash',
                    v_group.typical_buyin_min, v_group.typical_buyin_max,
                    v_target_date, v_group.typical_time,
                    COALESCE(v_group.max_players, 9),
                    'scheduled',
                    CASE WHEN v_group.is_private THEN 'members' ELSE 'rsvpd' END
                ) RETURNING id INTO v_new_game_id;

                INSERT INTO commander_home_audit_log (group_id, actor_id, target_type, target_id, action, metadata)
                VALUES (v_group.id, NULL, 'game', v_new_game_id, 'auto_generated',
                        jsonb_build_object('source','recurring_cron','scheduled_date', v_target_date,'week', v_week));

                v_generated := v_generated + 1;
            END IF;

            v_target_date := v_target_date + v_interval;
        END LOOP;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'generated', v_generated,
        'skipped', v_skipped,
        'run_at', NOW()
    );
END;
$$;


ALTER FUNCTION public.fn_generate_recurring_home_games() OWNER TO postgres;

--
-- TOC entry 9460 (class 1255 OID 31421955)
-- Name: fn_generate_scope_credit_invoices(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_generate_scope_credit_invoices(p_club_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE agent record; available numeric; result jsonb; generated int:=0; duplicate int:=0;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_club_id IS NULL OR p_from IS NULL OR p_to IS NULL OR NOT isfinite(p_from) OR NOT isfinite(p_to) OR p_from>=p_to OR p_to>now() THEN
  RAISE EXCEPTION 'invalid_credit_scope' USING ERRCODE='22023'; END IF;
 FOR agent IN SELECT a.id,a.credit_used FROM public.agents a WHERE a.club_id=p_club_id AND NOT COALESCE(a.is_prepaid,false) AND a.credit_used>0 ORDER BY a.id FOR UPDATE LOOP
  IF agent.credit_used::text IN('NaN','Infinity','-Infinity') OR agent.credit_used<>round(agent.credit_used,2) THEN
   RAISE EXCEPTION 'invalid_drawn_credit' USING ERRCODE='23514'; END IF;
  SELECT agent.credit_used-COALESCE(sum(amount_remaining),0) INTO available FROM public.credit_invoices
   WHERE agent_id=agent.id AND status IN('pending','partial','overdue','disputed');
  IF available<0 THEN RAISE EXCEPTION 'credit_debt_overinvoiced' USING ERRCODE='23514'; END IF;
  IF available=0 THEN CONTINUE; END IF;
  result:=public.fn_generate_credit_invoice(agent.id,p_from,p_to,available,p_to+interval '2 days');
  IF result->>'success' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'credit_invoice_generation_failed' USING DETAIL=result::text; END IF;
  IF result->>'duplicate'='true' THEN duplicate:=duplicate+1; ELSE generated:=generated+1; END IF;
 END LOOP;
 RETURN jsonb_build_object('success',true,'generated',generated,'duplicate',duplicate,'failed',0);
END $$;


ALTER FUNCTION public.fn_generate_scope_credit_invoices(p_club_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 7092 (class 1255 OID 4639419)
-- Name: fn_generate_venue_slug(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_generate_venue_slug(p_name text, p_city text DEFAULT NULL::text, p_state text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
DECLARE v_base text;
BEGIN
    -- Lowercase, strip non-alphanum (except space + hyphen), collapse whitespace/hyphens
    v_base := lower(COALESCE(p_name, ''));
    v_base := regexp_replace(v_base, '[''\u2019\u2018`]', '', 'g');                 -- apostrophes
    v_base := regexp_replace(v_base, '&', ' and ', 'g');                            -- ampersands
    v_base := regexp_replace(v_base, '[^a-z0-9]+', '-', 'g');                       -- anything else → hyphen
    v_base := regexp_replace(v_base, '^-+|-+$', '', 'g');                           -- trim leading/trailing hyphens
    v_base := regexp_replace(v_base, '-{2,}', '-', 'g');                            -- collapse multiple hyphens
    IF length(v_base) < 3 AND p_city IS NOT NULL THEN
        v_base := v_base || '-' || lower(regexp_replace(p_city, '[^a-z0-9]+', '-', 'g'));
        v_base := regexp_replace(v_base, '^-+|-+$', '', 'g');
    END IF;
    IF length(v_base) = 0 THEN v_base := 'poker-venue'; END IF;
    RETURN v_base;
END;
$_$;


ALTER FUNCTION public.fn_generate_venue_slug(p_name text, p_city text, p_state text) OWNER TO postgres;

