--
-- TOC entry 7255 (class 1255 OID 83808650)
-- Name: fn_get_club_welcome_package(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_club_welcome_package(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid:=auth.uid(); v_ent public.club_welcome_entitlements%ROWTYPE;
  v_receipt public.club_welcome_package_receipts%ROWTYPE;
  v_config jsonb:=public.fn_club_welcome_package_config('welcome-v1'); v_items jsonb:='[]'::jsonb;
BEGIN
  SELECT * INTO v_ent FROM public.club_welcome_entitlements e
   WHERE e.club_id=p_club_id AND e.owner_id=v_actor;
  IF v_actor IS NULL OR NOT FOUND THEN
    RETURN jsonb_build_object('ok',true,'club_id',p_club_id,'package_version','welcome-v1',
      'eligible',false,'status','not_eligible','reason','prospective_lifetime_first_club_only',
      'owner_acceptance_required',true,'items',v_items,'economics',v_config->'economics');
  END IF;
  SELECT * INTO v_receipt FROM public.club_welcome_package_receipts WHERE club_id=p_club_id;
  IF FOUND THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object('slot_key',i.slot_key,
      'entity_kind',i.entity_kind,'entity_id',i.entity_id,'initial_table_id',i.initial_table_id,
      'retired_at',i.retired_at) ORDER BY i.slot_key),'[]'::jsonb)
      INTO v_items FROM public.club_welcome_package_items i WHERE i.club_id=p_club_id;
  END IF;
  RETURN jsonb_build_object('ok',true,'club_id',p_club_id,'package_version','welcome-v1',
    'eligible',true,'status',CASE WHEN v_receipt.club_id IS NULL THEN 'ready'
      WHEN EXISTS(SELECT 1 FROM public.club_welcome_package_items i
                  WHERE i.club_id=p_club_id AND i.retired_at IS NOT NULL) THEN 'reset'
      ELSE 'provisioned' END,
    'owner_acceptance_required',true,'display_time_zone','UTC','display_time_label','7:00 PM UTC',
    'entitlement',jsonb_build_object('owner_id',v_ent.owner_id,'created_at',v_ent.created_at),
    'receipt',CASE WHEN v_receipt.club_id IS NULL THEN NULL ELSE jsonb_build_object(
      'operation_id',v_receipt.operation_id,'completed_at',v_receipt.completed_at,
      'result',v_receipt.result) END,'items',v_items,
    'economics',COALESCE(v_receipt.economics,v_config->'economics'));
END $$;


ALTER FUNCTION public.fn_get_club_welcome_package(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 5570 (class 1255 OID 83808664)
-- Name: fn_get_club_welcome_package_reset_impact(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_club_welcome_package_reset_impact(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid:=auth.uid(); v_owner uuid; v_cash uuid[]:='{}'; v_schedules uuid[]:='{}';
  v_tournaments uuid[]:='{}'; v_tables uuid[]:='{}'; v_economics boolean:=false;
  v_seats integer:=0; v_sessions integer:=0; v_waiting integer:=0; v_moves integer:=0;
  v_registered integer:=0; v_running integer:=0; v_executing integer:=0; v_hands integer:=0;
BEGIN
  SELECT owner_id INTO v_owner FROM public.clubs WHERE id=p_club_id;
  IF v_actor IS NULL OR v_owner IS DISTINCT FROM v_actor THEN
    RETURN jsonb_build_object('ok',true,'club_id',p_club_id,'package_version','welcome-v1',
      'authorized',false,'can_reset',false,'reason','owner_only',
      'cash_game_ids','[]'::jsonb,'tournament_ids','[]'::jsonb,'schedule_ids','[]'::jsonb,
      'blocking',jsonb_build_object('active_seats',0,'open_sessions',0,'waiting_players',0,
        'pending_moves',0,'registered_players',0,'running_tournaments',0,'executing_commands',0,'hand_history',0),
      'removable',jsonb_build_object('cash_games',0,'tournaments',0,'tables',0,'schedules',0));
  END IF;
  SELECT COALESCE(array_agg(entity_id),'{}') INTO v_cash FROM public.club_welcome_package_items
   WHERE club_id=p_club_id AND entity_kind='cash_game' AND retired_at IS NULL;
  SELECT COALESCE(array_agg(entity_id),'{}') INTO v_schedules FROM public.club_welcome_package_items
   WHERE club_id=p_club_id AND entity_kind='tournament_schedule' AND retired_at IS NULL;
  WITH package_schedule_tournaments AS (
    SELECT t.id FROM public.tournaments t
     WHERE t.club_id=p_club_id AND t.schedule_id=ANY(v_schedules)
    UNION
    SELECT t.id FROM public.tournament_schedule_spawns sp
    JOIN public.tournaments t ON t.id=sp.tournament_id
     WHERE sp.schedule_id=ANY(v_schedules) AND t.club_id=p_club_id
  ), expected(name,game_type,variant,tournament_type,buy_in_amount,buy_in_fee,seats,stack) AS (
    VALUES
      ('NLH Heads-Up 1','NLH','sng','SNG',0.95::numeric,0.05::numeric,2,1000),
      ('PLO4 Heads-Up 1','PLO4','sng','SNG',0.95::numeric,0.05::numeric,2,1000),
      ('NLH Heads-Up 1 Turbo','NLH','sng','SNG',0.95::numeric,0.05::numeric,2,300),
      ('PLO4 Heads-Up 1 Turbo','PLO4','sng','SNG',0.95::numeric,0.05::numeric,2,300),
      ('1 Chip Spin NLH','NLH','spin','SPIN',1::numeric,0::numeric,3,300),
      ('1 Chip Spin PLO4','PLO4','spin','SPIN',1::numeric,0::numeric,3,300),
      ('1 Chip Spin PLO5','PLO5','spin','SPIN',1::numeric,0::numeric,3,300),
      ('1 Chip Spin PLO6','PLO6','spin','SPIN',1::numeric,0::numeric,3,300),
      ('1 Chip Deep Stack Spin NLH','NLH','spin','SPIN',1::numeric,0::numeric,3,1000),
      ('1 Chip Deep Stack Spin PLO4','PLO4','spin','SPIN',1::numeric,0::numeric,3,1000),
      ('1 Chip Deep Stack Spin PLO5','PLO5','spin','SPIN',1::numeric,0::numeric,3,1000),
      ('1 Chip Deep Stack Spin PLO6','PLO6','spin','SPIN',1::numeric,0::numeric,3,1000)
  )
  SELECT COALESCE(array_agg(q.id ORDER BY q.id),'{}') INTO v_tournaments FROM (
    SELECT p.id FROM package_schedule_tournaments p
    UNION
    SELECT t.id FROM public.tournaments t JOIN expected e
      ON t.name=e.name AND upper(COALESCE(t.game_type,''))=e.game_type
     AND lower(COALESCE(t.variant,''))=e.variant
     AND upper(COALESCE(t.tournament_type::text,''))=e.tournament_type
     AND t.buy_in_amount=e.buy_in_amount AND t.buy_in_fee=e.buy_in_fee
     AND t.max_players=e.seats AND t.min_players=e.seats
     AND t.table_size=e.seats AND t.starting_chips=e.stack
     WHERE t.club_id=p_club_id AND t.union_id IS NULL AND t.schedule_id IS NULL
       AND t.restart_source_id IS NULL AND t.satellite_target_id IS NULL
       AND t.satellite_target IS NULL
    UNION
    SELECT t.id FROM public.tournaments t
     WHERE t.club_id=p_club_id AND t.union_id IS NULL
       AND upper(COALESCE(t.tournament_type::text,''))='SATELLITE'
       AND EXISTS(
         SELECT 1 FROM package_schedule_tournaments target
          WHERE target.id=t.satellite_target_id OR target.id=t.satellite_target
       )
  ) q;
  SELECT COALESCE(array_agg(id),'{}') INTO v_tables FROM public.tables
   WHERE cluster_id=ANY(v_cash) OR tournament_id=ANY(v_tournaments);
  SELECT count(*) INTO v_seats FROM public.table_seats WHERE table_id=ANY(v_tables) AND left_at IS NULL;
  SELECT count(*) INTO v_sessions FROM public.table_sessions
   WHERE table_id=ANY(v_tables) AND COALESCE(is_active,false) AND left_at IS NULL;
  SELECT (SELECT count(*) FROM public.table_waitlist WHERE table_id=ANY(v_tables) AND status IN('waiting','notified'))+
         (SELECT count(*) FROM public.cash_game_waitlist WHERE game_id=ANY(v_cash) AND status IN('waiting','notified'))
    INTO v_waiting;
  SELECT (SELECT count(*) FROM public.cash_seat_moves WHERE game_id=ANY(v_cash))+
         (SELECT count(*) FROM public.cash_seat_change_requests WHERE game_id=ANY(v_cash)) INTO v_moves;
  SELECT count(*) INTO v_registered FROM public.tournament_players WHERE tournament_id=ANY(v_tournaments);
  SELECT count(*) INTO v_running FROM public.tournaments WHERE id=ANY(v_tournaments) AND
    (started_at IS NOT NULL OR upper(COALESCE(status::text,'')) IN('RUNNING','BREAK','COMPLETING'));
  SELECT count(*) INTO v_executing FROM public.managed_game_schedules WHERE status='executing' AND
    ((game_kind='tournament' AND game_id=ANY(v_tournaments)) OR (game_kind='table' AND game_id=ANY(v_tables)));
  SELECT
    (SELECT count(*) FROM public.hand_history h
      WHERE h.tournament_id=ANY(v_tournaments)) +
    (SELECT count(*) FROM public.hand_history h
      WHERE h.table_id=ANY(v_tables)
        AND (h.tournament_id IS NULL OR h.tournament_id<>ALL(v_tournaments)))
    INTO v_hands;
  SELECT EXISTS(
    SELECT 1 FROM public.club_welcome_package_funding bf
    JOIN public.club_welcome_package_funding sf ON sf.club_id=bf.club_id AND sf.destination='spin_reserve'
    JOIN public.bbj_pools b ON b.club_id=bf.club_id AND b.union_id IS NULL
    JOIN public.spin_bonus_pools s ON s.club_id=bf.club_id
    WHERE bf.club_id=p_club_id AND bf.destination='bbj_main' AND bf.amount=100 AND sf.amount=200
      AND b.main_balance=100 AND COALESCE(b.backup_balance,0)=0 AND COALESCE(b.promo_balance,0)=0
      AND COALESCE(b.total_contributed,0)=0 AND COALESCE(b.total_paid_out,0)=0 AND COALESCE(b.hit_count,0)=0
      AND s.balance=200 AND s.seeded_amount=200
      AND NOT EXISTS(SELECT 1 FROM public.bbj_contributions WHERE pool_id=b.id)
      AND NOT EXISTS(SELECT 1 FROM public.bbj_payouts WHERE pool_id=b.id)
      AND NOT EXISTS(SELECT 1 FROM public.wallet_credit_idempotency i
        WHERE i.key LIKE 'bbjpromo:'||b.id::text||':%')
      AND NOT EXISTS(SELECT 1 FROM public.wheel_pools w WHERE w.host_id=p_club_id
        AND (w.spins<>0 OR w.intake_diamonds<>0 OR w.chips_minted<>0 OR w.chips_paid<>0 OR w.diamonds_paid<>0))
      AND NOT EXISTS(SELECT 1 FROM public.diamond_game_pools d WHERE d.host_id=p_club_id
        AND (d.rounds<>0 OR d.intake_diamonds<>0 OR d.chips_minted<>0 OR d.chips_paid<>0 OR d.reserved_chips<>0))
  ) INTO v_economics;
  IF NOT (WITH expected(name,game_type,variant,tournament_type,buy_in_amount,buy_in_fee,seats,stack) AS (
    VALUES
      ('NLH Heads-Up 1','NLH','sng','SNG',0.95::numeric,0.05::numeric,2,1000),
      ('PLO4 Heads-Up 1','PLO4','sng','SNG',0.95::numeric,0.05::numeric,2,1000),
      ('NLH Heads-Up 1 Turbo','NLH','sng','SNG',0.95::numeric,0.05::numeric,2,300),
      ('PLO4 Heads-Up 1 Turbo','PLO4','sng','SNG',0.95::numeric,0.05::numeric,2,300),
      ('1 Chip Spin NLH','NLH','spin','SPIN',1::numeric,0::numeric,3,300),
      ('1 Chip Spin PLO4','PLO4','spin','SPIN',1::numeric,0::numeric,3,300),
      ('1 Chip Spin PLO5','PLO5','spin','SPIN',1::numeric,0::numeric,3,300),
      ('1 Chip Spin PLO6','PLO6','spin','SPIN',1::numeric,0::numeric,3,300),
      ('1 Chip Deep Stack Spin NLH','NLH','spin','SPIN',1::numeric,0::numeric,3,1000),
      ('1 Chip Deep Stack Spin PLO4','PLO4','spin','SPIN',1::numeric,0::numeric,3,1000),
      ('1 Chip Deep Stack Spin PLO5','PLO5','spin','SPIN',1::numeric,0::numeric,3,1000),
      ('1 Chip Deep Stack Spin PLO6','PLO6','spin','SPIN',1::numeric,0::numeric,3,1000)
  ), candidates AS (
    SELECT e.name FROM public.tournaments t JOIN expected e
      ON t.name=e.name AND upper(COALESCE(t.game_type,''))=e.game_type
     AND lower(COALESCE(t.variant,''))=e.variant
     AND upper(COALESCE(t.tournament_type::text,''))=e.tournament_type
     AND t.buy_in_amount=e.buy_in_amount AND t.buy_in_fee=e.buy_in_fee
     AND t.max_players=e.seats AND t.min_players=e.seats
     AND t.table_size=e.seats AND t.starting_chips=e.stack
     WHERE t.club_id=p_club_id AND t.union_id IS NULL AND t.schedule_id IS NULL
       AND t.restart_source_id IS NULL AND t.satellite_target_id IS NULL
       AND t.satellite_target IS NULL
  ) SELECT count(*)=count(DISTINCT name) FROM candidates) THEN
    v_economics:=false;
  END IF;
  RETURN jsonb_build_object('ok',true,'club_id',p_club_id,'package_version','welcome-v1',
    'authorized',true,'can_reset',(v_seats+v_sessions+v_waiting+v_moves+v_registered+v_running+v_executing+v_hands)=0 AND v_economics,
    'reason',CASE WHEN (v_seats+v_sessions+v_waiting+v_moves+v_registered+v_running+v_executing+v_hands)>0 THEN 'package_resources_in_use'
                  WHEN NOT v_economics THEN 'package_economics_not_pristine' END,
    'cash_game_ids',to_jsonb(v_cash),'schedule_ids',to_jsonb(v_schedules),
    'tournament_ids',to_jsonb(v_tournaments),
    'blocking',jsonb_build_object('active_seats',v_seats,'open_sessions',v_sessions,
      'waiting_players',v_waiting,'pending_moves',v_moves,'registered_players',v_registered,
      'running_tournaments',v_running,'executing_commands',v_executing,'hand_history',v_hands,
      'economics_pristine',v_economics),
    'removable',jsonb_build_object('cash_games',cardinality(v_cash),'schedules',cardinality(v_schedules),
      'tournaments',cardinality(v_tournaments),'tables',cardinality(v_tables),'bbj_seed',100,'spin_seed',200));
END $$;


