--
-- TOC entry 8395 (class 1255 OID 82165300)
-- Name: fn_get_table_watch_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_table_watch_access(p_table_id uuid, p_target_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_table record;
  v_membership text;
  v_seated boolean := false;
  v_target_present boolean := true;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT t.id, t.club_id, t.tournament_id, t.restrict_observers, c.name AS club_name,
         c.club_id AS club_number, c.slug, c.requires_approval
    INTO v_table
    FROM public.tables t
    JOIN public.clubs c ON c.id = t.club_id
    LEFT JOIN public.tournaments tr
      ON tr.id = t.tournament_id AND tr.club_id = t.club_id
   WHERE t.id = p_table_id
     AND lower(coalesce(t.status::text, '')) IN ('waiting', 'running', 'active')
     AND coalesce(t.is_deleted, false) = false
     AND (
       t.tournament_id IS NULL
       OR (
         tr.id IS NOT NULL
         AND lower(coalesce(tr.status::text, '')) IN ('running', 'in_progress', 'active')
       )
     );

  IF NOT FOUND THEN
    RETURN jsonb_build_object('found', false, 'can_watch', false, 'action', 'unavailable');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.table_seats ts
     WHERE ts.table_id = p_table_id AND ts.user_id = v_uid AND ts.left_at IS NULL
  ) INTO v_seated;

  IF p_target_user_id IS NOT NULL THEN
    SELECT CASE
      WHEN v_table.tournament_id IS NULL THEN EXISTS (
        SELECT 1
          FROM public.table_seats ts
         WHERE ts.table_id = p_table_id
           AND ts.user_id = p_target_user_id
           AND ts.left_at IS NULL
      )
      ELSE EXISTS (
        SELECT 1
          FROM public.tournament_players tp
          JOIN public.tournaments tr
            ON tr.id = tp.tournament_id AND tr.club_id = v_table.club_id
         WHERE tp.user_id = p_target_user_id
           AND tp.table_id = p_table_id
           AND tp.tournament_id = v_table.tournament_id
           AND tp.status = 'playing'
           AND lower(coalesce(tr.status::text, '')) IN ('running', 'in_progress', 'active')
      )
    END INTO v_target_present;

    IF NOT v_target_present THEN
      RETURN jsonb_build_object('found', false, 'can_watch', false, 'action', 'unavailable');
    END IF;
  END IF;

  SELECT cm.status INTO v_membership
    FROM public.club_members cm
   WHERE cm.club_id = v_table.club_id AND cm.user_id = v_uid;

  RETURN jsonb_build_object(
    'found', true,
    'table_id', v_table.id,
    'club_uuid', v_table.club_id,
    'club_id', v_table.club_number,
    'club_slug', v_table.slug,
    'club_name', v_table.club_name,
    'membership_status', v_membership,
    'can_watch', v_seated OR coalesce(
      v_membership IN ('active', 'approved') AND NOT coalesce(v_table.restrict_observers, false),
      false
    ),
    'action', CASE
      WHEN v_seated THEN 'play'
      WHEN v_membership IN ('active', 'approved') AND coalesce(v_table.restrict_observers, false)
        THEN 'observers_restricted'
      WHEN v_membership IN ('active', 'approved') THEN 'watch'
      WHEN v_membership = 'pending' THEN 'pending'
      WHEN v_membership IN ('banned', 'suspended', 'rejected', 'left') THEN 'unavailable'
      WHEN coalesce(v_table.requires_approval, false) THEN 'request_join'
      ELSE 'join'
    END
  );
END;
$$;


ALTER FUNCTION public.fn_get_table_watch_access(p_table_id uuid, p_target_user_id uuid) OWNER TO postgres;

--
-- TOC entry 9046 (class 1255 OID 31346303)
-- Name: fn_get_ticker_feed(jsonb, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_ticker_feed(p_sources jsonb DEFAULT '{}'::jsonb, p_horizon_ms integer DEFAULT 900000, p_rail_club_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid      uuid := auth.uid();
  v_now      timestamptz := now();
  v_horizon  timestamptz;
  v_clubs    uuid[];
  v_out      jsonb := jsonb_build_object('ok', true);

  v_want_soon      boolean := (p_sources->'starting_soon')        = 'true'::jsonb;
  v_want_overlays  boolean := (p_sources->'overlays')             = 'true'::jsonb;
  v_want_closing   boolean := (p_sources->'registration_closing') = 'true'::jsonb;
  v_want_guarantee boolean := (p_sources->'guarantees')           = 'true'::jsonb;
  v_want_results   boolean := (p_sources->'winner_results')       = 'true'::jsonb;
  v_want_tables    boolean := (p_sources->'table_openings')       = 'true'::jsonb;
BEGIN
  v_want_soon      := COALESCE(v_want_soon, false);
  v_want_overlays  := COALESCE(v_want_overlays, false);
  v_want_closing   := COALESCE(v_want_closing, false);
  v_want_guarantee := COALESCE(v_want_guarantee, false);
  v_want_results   := COALESCE(v_want_results, false);
  v_want_tables    := COALESCE(v_want_tables, false);

  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;

  v_horizon := v_now + make_interval(secs => LEAST(GREATEST(COALESCE(p_horizon_ms, 0), 0), 3600000) / 1000.0);

  SELECT COALESCE(array_agg(cm.club_id), '{}')
    INTO v_clubs
  FROM public.club_members cm
  WHERE cm.user_id = v_uid
    AND cm.status IN ('active', 'approved');

  IF array_length(v_clubs, 1) IS NULL THEN
    RETURN v_out
      || jsonb_build_object('clubs', 0, 'upcoming', '[]'::jsonb, 'overlays', '[]'::jsonb,
                            'reg_closing', '[]'::jsonb, 'guarantees', '[]'::jsonb,
                            'results', '[]'::jsonb, 'table_openings', '[]'::jsonb);
  END IF;

  v_out := v_out || jsonb_build_object('clubs', array_length(v_clubs, 1));

  v_out := v_out || jsonb_build_object('upcoming', COALESCE((
    SELECT jsonb_agg(row_to_json(x)::jsonb ORDER BY x.start_time, x.id)
    FROM (
      SELECT t.id, t.name, t.start_time, t.club_id,
             t.buy_in_amount, t.buy_in_fee, t.current_players,
             EXISTS (
               SELECT 1 FROM public.tournament_players tp
               WHERE tp.tournament_id = t.id
                 AND tp.user_id = v_uid
                 AND tp.status IN ('registered', 'playing')
             ) AS is_registered,
             CASE WHEN p_rail_club_id IS NOT NULL AND t.club_id <> p_rail_club_id
                  THEN (SELECT c.name FROM public.clubs c WHERE c.id = t.club_id)
                  ELSE NULL END AS foreign_club_name
      FROM public.tournaments t
      WHERE v_want_soon
        AND t.club_id = ANY(v_clubs)
        AND t.tournament_type = 'MTT'
        AND t.status IN ('ANNOUNCED', 'REGISTERING')
        AND t.start_time > v_now
        AND t.start_time <= v_horizon
      ORDER BY t.start_time, t.id
      LIMIT 25
    ) x
  ), '[]'::jsonb));

  v_out := v_out || jsonb_build_object('overlays', COALESCE((
    SELECT jsonb_agg(row_to_json(x)::jsonb ORDER BY x.guaranteed_prize DESC, x.id)
    FROM (
      SELECT t.id, t.name, t.status, t.start_time, t.guaranteed_prize, t.prize_pool,
             t.current_players, t.buy_in_amount, t.late_reg_levels, t.late_reg_mins,
             t.started_at, t.current_level, t.max_players
      FROM public.tournaments t
      WHERE v_want_overlays
        AND t.club_id = ANY(v_clubs)
        AND t.tournament_type = 'MTT'
        AND t.guaranteed_prize > 0
        AND t.status IN ('RUNNING', 'IN_PROGRESS', 'LATE_REG', 'LATE_REGISTRATION')
      ORDER BY t.guaranteed_prize DESC, t.id
      LIMIT 25
    ) x
  ), '[]'::jsonb));

  v_out := v_out || jsonb_build_object('reg_closing', COALESCE((
    SELECT jsonb_agg(row_to_json(x)::jsonb ORDER BY x.id)
    FROM (
      SELECT t.id, t.name, t.status, t.start_time, t.started_at,
             t.late_reg_levels, t.late_reg_mins, t.current_level,
             t.blind_structure, t.level_started_at
      FROM public.tournaments t
      WHERE v_want_closing
        AND t.club_id = ANY(v_clubs)
        AND t.status IN ('RUNNING', 'LATE_REG', 'LATE_REGISTRATION')
        AND (
          ( COALESCE(t.late_reg_mins, 0) > 0
            AND COALESCE(t.started_at, t.start_time) + make_interval(mins => t.late_reg_mins) >  v_now
            AND COALESCE(t.started_at, t.start_time) + make_interval(mins => t.late_reg_mins) <= v_now + interval '5 minutes' )
          OR
          ( COALESCE(t.late_reg_levels, 0) > 0
            AND COALESCE(t.current_level, 0) < t.late_reg_levels
            AND t.level_started_at IS NOT NULL
            AND t.level_started_at > v_now - interval '12 hours' )
        )
      ORDER BY COALESCE(t.started_at, t.start_time) DESC, t.id
      LIMIT 25
    ) x
  ), '[]'::jsonb));

  v_out := v_out || jsonb_build_object('guarantees', COALESCE((
    SELECT jsonb_agg(row_to_json(x)::jsonb ORDER BY x.start_time, x.id)
    FROM (
      SELECT t.id, t.name, t.guaranteed_prize, t.current_players, t.start_time
      FROM public.tournaments t
      WHERE v_want_guarantee
        AND t.club_id = ANY(v_clubs)
        AND t.status IN ('ANNOUNCED', 'REGISTERING')
        AND t.guaranteed_prize > 0
        AND t.start_time > v_now
        AND t.start_time <= v_now + interval '2 hours'
      ORDER BY t.start_time, t.id
      LIMIT 25
    ) x
  ), '[]'::jsonb));

  v_out := v_out || jsonb_build_object('results', COALESCE((
    SELECT jsonb_agg(row_to_json(x)::jsonb ORDER BY x.ended_at DESC, x.id)
    FROM (
      SELECT t.id, t.name, t.prize_pool, t.ended_at
      FROM public.tournaments t
      WHERE v_want_results
        AND t.club_id = ANY(v_clubs)
        AND t.status = 'COMPLETED'
        AND t.ended_at > v_now - interval '10 minutes'
      ORDER BY t.ended_at DESC, t.id
      LIMIT 25
    ) x
  ), '[]'::jsonb));

  v_out := v_out || jsonb_build_object('table_openings', COALESCE((
    SELECT jsonb_agg(row_to_json(x)::jsonb ORDER BY x.created_at DESC, x.id)
    FROM (
      SELECT tb.id, tb.name, tb.game_variant, tb.created_at
      FROM public.tables tb
      WHERE v_want_tables
        AND tb.club_id = ANY(v_clubs)
        AND tb.tournament_id IS NULL
        AND tb.is_deleted = false
        AND tb.status IN ('waiting', 'running')
        AND tb.created_at > v_now - interval '10 minutes'
      ORDER BY tb.created_at DESC, tb.id
      LIMIT 10
    ) x
  ), '[]'::jsonb));

  RETURN v_out;
END;
$$;


ALTER FUNCTION public.fn_get_ticker_feed(p_sources jsonb, p_horizon_ms integer, p_rail_club_id uuid) OWNER TO postgres;

--
-- TOC entry 7568 (class 1255 OID 26587210)
-- Name: fn_get_tournament_deal_consensus(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_tournament_deal_consensus(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_state jsonb; p public.tournament_deal_proposals%ROWTYPE; v_voters jsonb; v_required integer;
  r public.tournament_deal_reviews%ROWTYPE; v_review_state text; v_identity jsonb;
BEGIN
  IF NOT public.fn_ca_tournament_deal_proposals_active() THEN
    RETURN jsonb_build_object('ok',false,'reason','proposal_authority_not_active');
  END IF;
  -- Expiry is observed only after any admitted terminal transaction resolves.
  PERFORM public.fn_ca_lock_settlement_lane_global();
  PERFORM 1 FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE;
  SELECT * INTO r FROM public.tournament_deal_reviews WHERE tournament_id=p_tournament_id
    ORDER BY requested_at DESC,id DESC LIMIT 1;
  v_review_state:=CASE WHEN r.id IS NULL THEN 'none'
    WHEN r.state IN ('requested','reviewing') AND r.expires_at<=clock_timestamp() THEN 'expired' ELSE r.state END;
  v_identity:=jsonb_build_object('ok',true,'review_id',r.id,'review_state',v_review_state,'review_expires_at',r.expires_at,
    'proposal_id',NULL,'revision',NULL,'voter_ids','[]'::jsonb,'required',0,'ready',false);
  IF v_review_state<>'reviewing' THEN RETURN v_identity; END IF;
  v_state:=public.fn_ca_tournament_deal_snapshot(p_tournament_id);
  SELECT * INTO r FROM public.tournament_deal_reviews WHERE id=r.id;
  IF r.state<>'reviewing' OR r.expires_at<=clock_timestamp() THEN
    RETURN v_identity||jsonb_build_object('review_state',CASE WHEN r.state='reviewing' THEN 'expired' ELSE r.state END);
  END IF;
  SELECT * INTO p FROM public.tournament_deal_proposals WHERE id=r.proposal_id;
  v_required:=jsonb_array_length(p.snapshot->'shares');
  SELECT COALESCE(jsonb_agg(c.user_id ORDER BY c.user_id),'[]'::jsonb) INTO v_voters
    FROM public.tournament_deal_proposal_consents c WHERE c.proposal_id=p.id
      AND EXISTS(SELECT 1 FROM jsonb_array_elements(p.snapshot->'shares')x WHERE x->>'user_id'=c.user_id::text);
  v_identity:=v_identity||jsonb_build_object('proposal_id',p.id,'revision',p.revision,'voter_ids',v_voters,'required',v_required);
  IF (v_state->>'ok')::boolean IS NOT TRUE OR p.snapshot IS DISTINCT FROM v_state->'snapshot'
    OR p.revision IS DISTINCT FROM v_state->>'revision' THEN
    RETURN v_identity||jsonb_build_object('reason','review_stale');
  END IF;
  RETURN v_identity||jsonb_build_object('ready',jsonb_array_length(v_voters)=v_required);
END;
$$;


ALTER FUNCTION public.fn_get_tournament_deal_consensus(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 6786 (class 1255 OID 26587208)
-- Name: fn_get_tournament_deal_proposal(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_get_tournament_deal_proposal(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_state jsonb; p public.tournament_deal_proposals%ROWTYPE; v_voters jsonb; r public.tournament_deal_reviews%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
  IF NOT public.fn_ca_tournament_deal_proposals_active() THEN
    RETURN jsonb_build_object('ok',false,'reason','proposal_authority_not_active');
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.tournament_players WHERE tournament_id=p_tournament_id
    AND user_id=v_actor AND status::text='playing' AND eliminated_at IS NULL) THEN
    RETURN jsonb_build_object('ok',false,'reason','voter_not_alive');
  END IF;
  v_state:=public.fn_ca_tournament_deal_snapshot(p_tournament_id);
  IF (v_state->>'ok')::boolean IS NOT TRUE THEN RETURN v_state; END IF;
  -- Membership can change while the snapshot waits for the terminal lock.
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_state->'snapshot'->'shares')x
    WHERE x->>'user_id'=v_actor::text) THEN
    RETURN jsonb_build_object('ok',false,'reason','voter_not_alive');
  END IF;
  SELECT * INTO r FROM public.tournament_deal_reviews WHERE id=(v_state->'snapshot'->>'review_id')::uuid AND state='reviewing';
  SELECT * INTO p FROM public.tournament_deal_proposals WHERE id=r.proposal_id AND tournament_id=p_tournament_id;
  IF p.id IS NULL OR p.snapshot IS DISTINCT FROM v_state->'snapshot' OR p.revision IS DISTINCT FROM v_state->>'revision' THEN
    RETURN jsonb_build_object('ok',false,'reason','review_stale');
  END IF;
  SELECT COALESCE(jsonb_agg(user_id ORDER BY user_id),'[]'::jsonb) INTO v_voters
    FROM public.tournament_deal_proposal_consents WHERE proposal_id=p.id;
  RETURN jsonb_build_object('ok',true,'actor_id',v_actor,'tournament_id',p_tournament_id,
    'proposal_id',p.id,'revision',p.revision,'state','ready','review_id',r.id,'expires_at',r.expires_at,'shares',p.snapshot->'shares',
    'pool_cents',p.snapshot->'pool_cents','deal_cents',p.snapshot->'deal_cents','voter_ids',v_voters);
END;
$$;


ALTER FUNCTION public.fn_get_tournament_deal_proposal(p_tournament_id uuid) OWNER TO postgres;

