-- Name: fn_gto_v31_feature_binding_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_gto_v31_feature_binding_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NEW.feature_contract_version IS DISTINCT FROM OLD.feature_contract_version OR NEW.policy_export_schema IS DISTINCT FROM OLD.policy_export_schema THEN RAISE EXCEPTION 'feature contract version is immutable'; END IF;
 RETURN NEW;
END; $$;


