-- TOC entry 5249 (class 1255 OID 118525462)
-- Name: fn_gto_v31_feature_key(integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_gto_v31_feature_key(p_combo integer, p_board text, p_version text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
BEGIN
 PERFORM public.fn_gto_v31_feature_identity(p_version);
 IF p_version='holdem-board-relative-v2' THEN RETURN public.fn_gto_v31_board_relative_key_v2(p_combo,p_board); END IF;
 RETURN public.fn_gto_v31_hand_key(p_combo,p_board);
END; $$;


