COMMENT ON FUNCTION public.fn_gto_v31_hand_key(p_combo_index integer, p_board text) IS 'Canonical two-hole-suit V31 hand key; NULL for duplicate boards, blocked combos, or malformed cards.';


--
-- TOC entry 6567 (class 1255 OID 25580954)
-- Name: fn_gto_v31_hand_key_valid(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_gto_v31_hand_key_valid(p_key text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_match text[];
  v_ranks constant text := 'AKQJT98765432';
  v_first text;
  v_second text;
  v_suitedness text;
  v_first_count integer;
  v_second_count integer;
BEGIN
  v_match := regexp_match(
    p_key,
    '^([AKQJT98765432])([AKQJT98765432])([so]?):([0-5])([0-5])$'
  );
  IF v_match IS NULL THEN RETURN false; END IF;
  v_first := v_match[1];
  v_second := v_match[2];
  v_suitedness := COALESCE(v_match[3],'');
  v_first_count := v_match[4]::integer;
  v_second_count := v_match[5]::integer;

  IF v_first = v_second THEN
    RETURN v_suitedness = ''
      AND v_first_count >= v_second_count
      AND v_first_count + v_second_count <= 5;
  END IF;
  RETURN COALESCE(
    v_suitedness IN ('s','o')
      AND position(v_first IN v_ranks) < position(v_second IN v_ranks)
      AND CASE v_suitedness
        WHEN 's' THEN v_first_count = v_second_count
        ELSE v_first_count + v_second_count <= 5
      END,
    false
  );
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$_$;


ALTER FUNCTION public.fn_gto_v31_hand_key_valid(p_key text) OWNER TO postgres;

--
-- TOC entry 9146 (class 1255 OID 25584943)
-- Name: fn_gto_v31_hand_key_valid(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_gto_v31_hand_key_valid(p_key text, p_street text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_match text[];
  v_board_cards integer;
  v_suitedness text;
  v_first_count integer;
  v_second_count integer;
BEGIN
  IF NOT public.fn_gto_v31_hand_key_valid(p_key) THEN RETURN false; END IF;
  v_board_cards := CASE p_street
    WHEN 'flop' THEN 3
    WHEN 'turn' THEN 4
    WHEN 'river' THEN 5
    ELSE NULL
  END;
  IF v_board_cards IS NULL THEN RETURN false; END IF;

  v_match := regexp_match(
    p_key,
    '^([AKQJT98765432])([AKQJT98765432])([so]?):([0-5])([0-5])$'
  );
  v_suitedness := COALESCE(v_match[3],'');
  v_first_count := v_match[4]::integer;
  v_second_count := v_match[5]::integer;
  IF v_suitedness = 's' THEN
    RETURN v_first_count <= v_board_cards;
  END IF;
  RETURN v_first_count + v_second_count <= v_board_cards;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$_$;


ALTER FUNCTION public.fn_gto_v31_hand_key_valid(p_key text, p_street text) OWNER TO postgres;

--
-- TOC entry 8535 (class 1255 OID 118525479)
-- Name: fn_gto_v31_hand_matrix_valid(jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_gto_v31_hand_matrix_valid(p_matrix jsonb, p_street text, p_version text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_key text;
BEGIN
  IF p_matrix IS NULL OR jsonb_typeof(p_matrix) <> 'object'
     OR NOT EXISTS (SELECT 1 FROM jsonb_object_keys(p_matrix)) THEN
    RETURN false;
  END IF;
  FOR v_key IN SELECT jsonb_object_keys(p_matrix) LOOP
    IF NOT public.fn_gto_v31_feature_key_valid(v_key,p_street,p_version) THEN RETURN false; END IF;
  END LOOP;
  RETURN true;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$$;


