--
-- TOC entry 8588 (class 1255 OID 25593647)
-- Name: fn_gto_v31_json_safe_integer(jsonb, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_gto_v31_json_safe_integer(p_value jsonb, p_min numeric, p_max numeric) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_value numeric;
BEGIN
  IF p_value IS NULL OR jsonb_typeof(p_value) <> 'number' THEN RETURN false; END IF;
  v_value := (p_value #>> '{}')::numeric;
  RETURN v_value = trunc(v_value) AND v_value BETWEEN p_min AND p_max;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$$;


