--
-- TOC entry 8574 (class 1255 OID 30772713)
-- Name: fn_guard_new_mtt_blind_contract(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_guard_new_mtt_blind_contract() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE contract jsonb;
BEGIN
  IF (TG_OP='INSERT' OR OLD.format_contract IN ('mtt-v1','mtt-v2'))
     AND public.fn_ca_new_tournament_is_unlimited(to_jsonb(NEW)) THEN
    IF TG_OP='UPDATE' AND OLD.format_contract IN ('mtt-v1','mtt-v2')
       AND NEW.blind_structure IS NOT DISTINCT FROM OLD.blind_structure
       AND NEW.starting_chips IS NOT DISTINCT FROM OLD.starting_chips THEN RETURN NEW; END IF;
    contract:=public.fn_ca_mtt_blind_contract(NEW.blind_structure,NEW.starting_chips);
    NEW.blind_speed:=contract->>'blind_speed';
    NEW.is_turbo:=(contract->>'is_turbo')::boolean;
    RETURN NEW;
  END IF;
  IF upper(COALESCE(NEW.tournament_type,''))<>'MTT'
     OR lower(COALESCE(NEW.variant,'')) IN ('spin','sng')
     OR COALESCE(NEW.max_players,0)<=2 THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND NEW.blind_structure IS NOT DISTINCT FROM OLD.blind_structure
     AND NEW.starting_chips IS NOT DISTINCT FROM OLD.starting_chips
     AND upper(COALESCE(OLD.tournament_type,''))='MTT'
     AND lower(COALESCE(OLD.variant,'')) NOT IN ('spin','sng')
     AND COALESCE(OLD.max_players,0)>2 THEN RETURN NEW; END IF;
  contract:=public.fn_ca_mtt_blind_contract(NEW.blind_structure,NEW.starting_chips);
  NEW.blind_speed:=contract->>'blind_speed';
  NEW.is_turbo:=(contract->>'is_turbo')::boolean;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_guard_new_mtt_blind_contract() OWNER TO postgres;

--
-- TOC entry 4139 (class 1255 OID 21930832)
-- Name: fn_guard_one_game_per_blind_category(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_guard_one_game_per_blind_category() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_existing text;
BEGIN
  IF NOT NEW.enabled OR NEW.template_name NOT IN ('action', 'madness') THEN RETURN NEW; END IF;
  SELECT g.name || ' (' || g.sb || '/' || g.bb || ')' INTO v_existing
  FROM public.cash_games g
  WHERE g.enabled AND g.id <> NEW.id AND g.club_id = NEW.club_id
    AND g.template_name = NEW.template_name AND g.variant = NEW.variant
    AND public.fn_cash_game_category_key(g.club_id,g.variant,g.sb,g.bb)
      = public.fn_cash_game_category_key(NEW.club_id,NEW.variant,NEW.sb,NEW.bb)
  LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RAISE EXCEPTION
      'ONE_GAME_PER_BLIND_CATEGORY: this club already runs % as its % % game. Close it before opening another.',
      v_existing, initcap(NEW.template_name), public.fn_cash_stake_band(NEW.bb)
      USING ERRCODE = 'unique_violation',
      HINT = 'One Action or Madness game per category; Midway NLH/PLO 0.50/1.00 has its own category.';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_guard_one_game_per_blind_category() OWNER TO postgres;

--
-- TOC entry 9450 (class 1255 OID 15765751)
-- Name: fn_guard_one_live_tournament_seat(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_guard_one_live_tournament_seat() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tournament_id uuid;
  v_other_table   uuid;
  v_other_seat    integer;
BEGIN
  IF NEW.left_at IS NOT NULL OR NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT t.tournament_id INTO v_tournament_id
  FROM public.tables t
  WHERE t.id = NEW.table_id;

  IF v_tournament_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT ts.table_id, ts.seat_number
    INTO v_other_table, v_other_seat
  FROM public.table_seats ts
  JOIN public.tables t2 ON t2.id = ts.table_id
  WHERE ts.left_at IS NULL
    AND ts.user_id = NEW.user_id
    AND t2.tournament_id = v_tournament_id
    AND ts.id IS DISTINCT FROM NEW.id
  LIMIT 1;

  IF v_other_table IS NOT NULL THEN
    RAISE EXCEPTION
      'player % already holds a live seat in tournament % (table %, seat %) - one live seat per tournament',
      NEW.user_id, v_tournament_id, v_other_table, v_other_seat
      USING ERRCODE = '23505';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_guard_one_live_tournament_seat() OWNER TO postgres;

--
-- TOC entry 9130 (class 1255 OID 9256739)
-- Name: fn_guard_profile_privileged_columns(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_guard_profile_privileged_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_changed text;
  v_stack text;
BEGIN
  IF public.fn_is_service_context() THEN RETURN NEW; END IF;

  GET DIAGNOSTICS v_stack = PG_CONTEXT;
  IF v_stack ~ 'function (public[.])?deduct_diamonds[(]'
     OR v_stack ~ 'function (public[.])?fn_union_send_to_member[(]'
     OR v_stack ~ 'function (public[.])?claim_daily_challenge[(]'
     OR v_stack ~ 'function (public[.])?claim_daily_challenges[(]'
     OR v_stack ~ 'function (public[.])?fn_ca_daily_bonus_claim[(]'
     OR v_stack ~ 'function (public[.])?fn_ca_daily_bonus_boost_extra[(]'
     OR v_stack ~ 'function (public[.])?fn_wheel_spin[(]'
     OR v_stack ~ 'function (public[.])?fn_wheel_free_spin[(]'
     OR v_stack ~ 'function (public[.])?fn_plinko_drop[(]'
     OR v_stack ~ 'function (public[.])?fn_crash_start[(]'
     OR v_stack ~ 'function (public[.])?fn_diamond_game_take_bet[(]'
     OR v_stack ~ 'function (public[.])?fn_wheel_spin_core[(]'
     OR v_stack ~ 'function (public[.])?fn_wheel_spin_v2[(]'
     OR v_stack ~ 'function (public[.])?fn_wheel_diamond_cards_pick[(]'
     OR v_stack ~ 'function (public[.])?fn_diamond_bonus_share_to_feed[(]'
     OR v_stack ~ 'function (public[.])?fn_ca_mint[(]'
     OR v_stack ~ 'function (public[.])?fn_ca_burn[(]'
     OR v_stack ~ 'function (public[.])?send_stream_gift[(]'
     -- DIAMOND PHASE 8: a tournament entry is custody; its charge and refund
     -- move the wallet from client doors.
     OR v_stack ~ 'function (public[.])?fn_poker_diamond_tournament_charge[(]'
     OR v_stack ~ 'function (public[.])?fn_poker_diamond_tournament_refund[(]'
     -- A Diamond bounty paid to the winner (also from a rebuy that settles the bust first).
     OR v_stack ~ 'function (public[.])?fn_poker_diamond_tournament_pay[(]'
     -- RULING 4 (amended 2026-09-08): the player-to-player wallet transfer. It runs under the
     -- sender's JWT, journals both legs and writes both wallets itself, and it is the one
     -- authenticated door for a transfer; unnamed here it answered 42501 to every player.
     OR v_stack ~ 'function (public[.])?send_wallet_diamond_transfer[(]'
     -- DIAMOND PHASE 11: a player's Diamond cash buy-in. atomic_table_buyin runs under the
     -- player's JWT and reaches the wallet only through fn_poker_diamond_buyin, whose one
     -- wallet write is fn_poker_diamond_reserve's journaled deposit; unnamed here, every
     -- client buy-in answered 42501 at that write.
     OR v_stack ~ 'function (public[.])?fn_poker_diamond_buyin[(]'
  THEN
    RETURN NEW;
  END IF;

  IF NEW.diamonds IS DISTINCT FROM OLD.diamonds THEN v_changed := 'diamonds';
  ELSIF NEW.diamond_balance IS DISTINCT FROM OLD.diamond_balance THEN v_changed := 'diamond_balance';
  ELSIF NEW.diamond_multiplier IS DISTINCT FROM OLD.diamond_multiplier THEN v_changed := 'diamond_multiplier';
  ELSIF NEW.is_vip IS DISTINCT FROM OLD.is_vip THEN v_changed := 'is_vip';
  ELSIF NEW.vip_tier IS DISTINCT FROM OLD.vip_tier THEN v_changed := 'vip_tier';
  ELSIF NEW.vip_expires_at IS DISTINCT FROM OLD.vip_expires_at THEN v_changed := 'vip_expires_at';
  END IF;

  IF v_changed IS NOT NULL THEN
    RAISE EXCEPTION
      'profiles.% is server-managed and cannot be modified by role %',
      v_changed, current_user
      USING ERRCODE = '42501',
            HINT = 'Use a server-authoritative, ledgered money RPC.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_guard_profile_privileged_columns() OWNER TO postgres;

--
-- TOC entry 7609 (class 1255 OID 111530994)
-- Name: fn_guard_profile_privileged_columns_on_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_guard_profile_privileged_columns_on_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_field text;
BEGIN
  -- SET ROLE survives nested SECURITY DEFINER calls; current_user does not.
  -- A browser request is judged even when a definer function carries it here.
  IF coalesce(current_setting('role', true), 'none') NOT IN ('anon', 'authenticated')
     AND public.fn_is_service_context() IS TRUE THEN
    RETURN NEW;
  END IF;

  IF coalesce(NEW.role, 'user') <> 'user' THEN v_field := 'role';
  ELSIF coalesce(NEW.is_admin, false) THEN v_field := 'is_admin';
  ELSIF coalesce(NEW.is_vip, false) THEN v_field := 'is_vip';
  ELSIF NEW.vip_tier IS NOT NULL THEN v_field := 'vip_tier';
  ELSIF NEW.vip_expires_at IS NOT NULL THEN v_field := 'vip_expires_at';
  ELSIF coalesce(NEW.diamonds, 0) <> 0 THEN v_field := 'diamonds';
  ELSIF coalesce(NEW.diamond_balance, 0) <> 0 THEN v_field := 'diamond_balance';
  ELSIF coalesce(NEW.diamond_multiplier, 1) <> 1 THEN v_field := 'diamond_multiplier';
  ELSIF coalesce(NEW.kyc_status, 'NONE') <> 'NONE' THEN v_field := 'kyc_status';
  ELSIF coalesce(NEW.age_verified, false) THEN v_field := 'age_verified';
  ELSIF coalesce(NEW.mfa_required, false) THEN v_field := 'mfa_required';
  ELSIF coalesce(NEW.email_verified, false) THEN v_field := 'email_verified';
  ELSIF coalesce(NEW.phone_verified, false) THEN v_field := 'phone_verified';
  END IF;

  IF v_field IS NOT NULL THEN
    RAISE EXCEPTION 'profiles.% is server-managed and cannot be set when a profile is created', v_field
      USING ERRCODE = '42501',
            HINT = 'A new profile starts as an ordinary player. Standing, verification and balances are set by the server.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_guard_profile_privileged_columns_on_insert() OWNER TO postgres;

