--
-- TOC entry 7852 (class 1255 OID 78765583)
-- Name: fn_hand_clip_claim(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hand_clip_claim() RETURNS public.hand_clip_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job public.hand_clip_jobs;
BEGIN
  IF COALESCE(auth.role()::text, '') <> 'service_role' THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'fn_hand_clip_claim requires the service role';
  END IF;

  -- A render that never finished is finalised, not retried: the function has
  -- a 300 s ceiling, so a rendering row older than 12 minutes is dead.
  UPDATE public.hand_clip_jobs
     SET state = 'failed',
         error = 'render_timeout',
         updated_at = now()
   WHERE state = 'rendering'
     AND claimed_at < now() - interval '12 minutes';

  SELECT * INTO v_job
    FROM public.hand_clip_jobs
   WHERE state = 'queued'
   ORDER BY created_at ASC, id ASC
   LIMIT 1
   FOR UPDATE SKIP LOCKED;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  UPDATE public.hand_clip_jobs
     SET state = 'rendering',
         claimed_at = now(),
         updated_at = now()
   WHERE id = v_job.id
  RETURNING * INTO v_job;

  RETURN v_job;
END
$$;


ALTER FUNCTION public.fn_hand_clip_claim() OWNER TO postgres;

--
-- TOC entry 47500 (class 0 OID 0)
-- Dependencies: 7852
-- Name: FUNCTION fn_hand_clip_claim(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_hand_clip_claim() IS 'Phase 9: finalises rendering rows older than 12 minutes as failed render_timeout, then claims the oldest queued row (FOR UPDATE SKIP LOCKED) as rendering and returns it; NULL when the queue is empty. Service role only.';


--
-- TOC entry 7348 (class 1255 OID 78765584)
-- Name: fn_hand_clip_finish(uuid, text, text, text, integer, integer, integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hand_clip_finish(p_job_id uuid, p_state text, p_video_url text, p_poster_url text, p_duration_ms integer, p_width integer, p_height integer, p_frames integer, p_render_ms integer, p_error text) RETURNS public.hand_clip_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_state text := lower(btrim(COALESCE(p_state, '')));
  v_job public.hand_clip_jobs;
BEGIN
  IF COALESCE(auth.role()::text, '') <> 'service_role' THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'fn_hand_clip_finish requires the service role';
  END IF;

  IF v_state NOT IN ('ready', 'failed') THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'a hand clip job finishes as ready or failed';
  END IF;

  SELECT * INTO v_job
    FROM public.hand_clip_jobs
   WHERE id = p_job_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0002',
      MESSAGE = 'hand clip job not found';
  END IF;

  IF v_job.state <> 'rendering' THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = format('only a rendering hand clip job can be finished (state %s)', v_job.state);
  END IF;

  IF v_state = 'ready' THEN
    IF NULLIF(btrim(COALESCE(p_video_url, '')), '') IS NULL
       OR NULLIF(btrim(COALESCE(p_poster_url, '')), '') IS NULL THEN
      RAISE EXCEPTION USING
        ERRCODE = '22023',
        MESSAGE = 'a ready hand clip carries a video URL and a poster URL';
    END IF;

    UPDATE public.hand_clip_jobs
       SET state = 'ready',
           video_url = btrim(p_video_url),
           poster_url = btrim(p_poster_url),
           duration_ms = p_duration_ms,
           width = p_width,
           height = p_height,
           frames = p_frames,
           render_ms = p_render_ms,
           error = NULL,
           rendered_at = now(),
           updated_at = now()
     WHERE id = v_job.id
    RETURNING * INTO v_job;
  ELSE
    UPDATE public.hand_clip_jobs
       SET state = 'failed',
           error = left(COALESCE(NULLIF(btrim(p_error), ''), 'render_failed'), 500),
           render_ms = p_render_ms,
           updated_at = now()
     WHERE id = v_job.id
    RETURNING * INTO v_job;
  END IF;

  RETURN v_job;
END
$$;


