--
-- TOC entry 4036 (class 1255 OID 120051074)
-- Name: fn_hhr_record_atomic(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hhr_record_atomic(p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET lock_timeout TO '5s'
    SET statement_timeout TO '15s'
    AS $_$
DECLARE
  -- Exactly the keys of HorseReviewRow (server/src/services/HorseHandReview.ts).
  c_keys constant text[] := ARRAY[
    'hand_id','table_id','tournament_id','club_id','played_at','game_variant',
    'format','big_blind','horse_user_id','seat','net_amount','net_bb',
    'pot_size','hole_cards','board','actions','leak_tags'];
  v_n            int;
  v_i            int;
  v_e            jsonb;
  v_missing      text[];
  v_extra        text[];
  v_first_hand   uuid;
  v_horses       uuid[] := ARRAY[]::uuid[];
  v_hand         uuid;
  v_horse        uuid;
  v_table        uuid;
  v_tournament   uuid;
  v_club         uuid;
  v_played       timestamptz;
  v_variant      text;
  v_format       text;
  v_bb           numeric;
  v_seat         int;
  v_net_amount   numeric;
  v_net_bb       numeric;
  v_pot          numeric;
  v_tags         text[];
  v_day          date;
  v_is_win       boolean;
  v_digest       text;
  v_existing     text;
  v_review_id    bigint;
  v_status       text;
  v_t            text;
  v_counts       jsonb;
  v_nets         jsonb;
  v_out          jsonb := '[]'::jsonb;
BEGIN
  -- ── shape of the payload ───────────────────────────────────────────────
  IF p_rows IS NULL OR pg_catalog.jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = 'hhr_payload_not_array: p_rows must be a JSON array of review rows';
  END IF;
  v_n := pg_catalog.jsonb_array_length(p_rows);
  IF v_n < 1 OR v_n > 10 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001',
      MESSAGE = pg_catalog.format('hhr_payload_size: expected 1..10 rows, got %s', v_n);
  END IF;

  -- ── validate EVERY row before anything is written ──────────────────────
  FOR v_i IN 0 .. v_n - 1 LOOP
    v_e := p_rows -> v_i;
    IF pg_catalog.jsonb_typeof(v_e) <> 'object' THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = pg_catalog.format('hhr_row_not_object: row %s', v_i);
    END IF;
    v_missing := ARRAY(SELECT k FROM pg_catalog.unnest(c_keys) AS u(k) WHERE NOT (v_e ? u.k));
    v_extra   := ARRAY(SELECT k FROM pg_catalog.jsonb_object_keys(v_e) AS o(k) WHERE o.k <> ALL (c_keys));
    IF pg_catalog.cardinality(v_missing) > 0 OR pg_catalog.cardinality(v_extra) > 0 THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = pg_catalog.format('hhr_row_keys: row %s missing %s unknown %s', v_i, v_missing, v_extra);
    END IF;

    -- JSON types. A non-finite JS number serialises as null, so a NaN or
    -- Infinity net_bb arrives as null and is refused here.
    IF pg_catalog.jsonb_typeof(v_e -> 'hand_id') <> 'string'
       OR pg_catalog.jsonb_typeof(v_e -> 'horse_user_id') <> 'string'
       OR pg_catalog.jsonb_typeof(v_e -> 'played_at') <> 'string'
       OR pg_catalog.jsonb_typeof(v_e -> 'game_variant') <> 'string'
       OR pg_catalog.jsonb_typeof(v_e -> 'format') <> 'string'
       OR pg_catalog.jsonb_typeof(v_e -> 'table_id') NOT IN ('string', 'null')
       OR pg_catalog.jsonb_typeof(v_e -> 'tournament_id') NOT IN ('string', 'null')
       OR pg_catalog.jsonb_typeof(v_e -> 'club_id') NOT IN ('string', 'null') THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = pg_catalog.format('hhr_invalid_type: row %s: id, time and label fields must be JSON strings', v_i);
    END IF;
    IF pg_catalog.jsonb_typeof(v_e -> 'big_blind') <> 'number'
       OR pg_catalog.jsonb_typeof(v_e -> 'net_amount') <> 'number'
       OR pg_catalog.jsonb_typeof(v_e -> 'net_bb') <> 'number'
       OR pg_catalog.jsonb_typeof(v_e -> 'seat') NOT IN ('number', 'null')
       OR pg_catalog.jsonb_typeof(v_e -> 'pot_size') NOT IN ('number', 'null') THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = pg_catalog.format('hhr_invalid_number: row %s: big_blind, net_amount and net_bb must be finite JSON numbers', v_i);
    END IF;
    IF pg_catalog.jsonb_typeof(v_e -> 'leak_tags') <> 'array'
       OR EXISTS (SELECT 1 FROM pg_catalog.jsonb_array_elements(v_e -> 'leak_tags') AS t(x)
                   WHERE pg_catalog.jsonb_typeof(t.x) <> 'string') THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = pg_catalog.format('hhr_invalid_leak_tags: row %s: leak_tags must be a JSON array of strings', v_i);
    END IF;
    -- played_at must carry its own offset, so its instant never depends on
    -- the calling session's TimeZone.
    IF (v_e ->> 'played_at') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}(:[0-9]{2}([.][0-9]+)?)?(Z|z|[+-][0-9]{2}(:?[0-9]{2})?)$' THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = pg_catalog.format('hhr_invalid_played_at: row %s: played_at must be an ISO timestamp with an explicit offset', v_i);
    END IF;

    -- Casts: a data error becomes a named refusal (nothing has been written).
    BEGIN
      v_hand       := (v_e ->> 'hand_id')::uuid;
      v_horse      := (v_e ->> 'horse_user_id')::uuid;
      v_table      := (v_e ->> 'table_id')::uuid;
      v_tournament := (v_e ->> 'tournament_id')::uuid;
      v_club       := (v_e ->> 'club_id')::uuid;
      v_played     := (v_e ->> 'played_at')::timestamptz;
      v_bb         := (v_e ->> 'big_blind')::numeric;
      v_net_amount := (v_e ->> 'net_amount')::numeric;
      v_net_bb     := (v_e ->> 'net_bb')::numeric;
      v_pot        := (v_e ->> 'pot_size')::numeric;
      v_seat       := (v_e ->> 'seat')::int;
    EXCEPTION WHEN data_exception THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = pg_catalog.format('hhr_invalid_value: row %s: %s', v_i, SQLERRM);
    END;

    IF NOT pg_catalog.isfinite(v_played) THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = pg_catalog.format('hhr_invalid_played_at: row %s: played_at must be finite', v_i);
    END IF;
    IF v_bb <= 0 THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = pg_catalog.format('hhr_invalid_big_blind: row %s: big_blind must be > 0', v_i);
    END IF;
    IF v_net_bb = 0 THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = pg_catalog.format('hhr_invalid_net_bb: row %s: |net_bb| must be > 0', v_i);
    END IF;
    IF pg_catalog.btrim(v_e ->> 'game_variant') = '' OR pg_catalog.btrim(v_e ->> 'format') = '' THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = pg_catalog.format('hhr_invalid_label: row %s: game_variant and format must be non-empty', v_i);
    END IF;

    IF v_i = 0 THEN
      v_first_hand := v_hand;
    ELSIF v_hand IS DISTINCT FROM v_first_hand THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = pg_catalog.format('hhr_mixed_hand: row %s carries hand %s, row 0 carries %s', v_i, v_hand, v_first_hand);
    END IF;
    -- uuid equality, so the same horse in two letter cases is one horse.
    IF v_horse = ANY (v_horses) THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001',
        MESSAGE = pg_catalog.format('hhr_duplicate_horse: horse %s appears more than once', v_horse);
    END IF;
    v_horses := v_horses || v_horse;
  END LOOP;

  v_hand := v_first_hand;

  -- ── publish, in canonical horse order (deterministic lock order) ──────
  FOR v_e IN
    SELECT x.e
      FROM pg_catalog.jsonb_array_elements(p_rows) AS x(e)
     ORDER BY (x.e ->> 'horse_user_id')::uuid
  LOOP
    v_horse      := (v_e ->> 'horse_user_id')::uuid;
    v_table      := (v_e ->> 'table_id')::uuid;
    v_tournament := (v_e ->> 'tournament_id')::uuid;
    v_club       := (v_e ->> 'club_id')::uuid;
    v_played     := (v_e ->> 'played_at')::timestamptz;
    v_variant    := v_e ->> 'game_variant';
    v_format     := v_e ->> 'format';
    v_bb         := (v_e ->> 'big_blind')::numeric;
    v_seat       := (v_e ->> 'seat')::int;
    v_net_amount := (v_e ->> 'net_amount')::numeric;
    v_net_bb     := (v_e ->> 'net_bb')::numeric;
    v_pot        := (v_e ->> 'pot_size')::numeric;
    v_tags       := ARRAY(
                      SELECT t.tag
                        FROM pg_catalog.jsonb_array_elements_text(v_e -> 'leak_tags') WITH ORDINALITY AS t(tag, ord)
                       ORDER BY t.ord);
    v_day        := (v_played AT TIME ZONE 'UTC')::date;
    v_is_win     := v_net_bb > 0;

    -- a. identity of the immutable review values, from the TYPED values.
    --    Evidence payloads (hole_cards, board, actions) are not part of it.
    v_digest := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
      pg_catalog.jsonb_build_object(
        'hand_id',       v_hand::text,
        'table_id',      v_table::text,
        'tournament_id', v_tournament::text,
        'club_id',       v_club::text,
        'played_at',     pg_catalog.to_char(v_played AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
        'game_variant',  v_variant,
        'format',        v_format,
        'big_blind',     pg_catalog.trim_scale(v_bb),
        'horse_user_id', v_horse::text,
        'seat',          v_seat,
        'net_amount',    pg_catalog.trim_scale(v_net_amount),
        'net_bb',        pg_catalog.trim_scale(v_net_bb),
        'pot_size',      pg_catalog.trim_scale(v_pot),
        'leak_tags',     pg_catalog.to_jsonb(v_tags)
      )::text, 'UTF8')), 'hex');

    -- b. an existing receipt decides it
    v_existing := NULL;
    SELECT r.identity_digest INTO v_existing
      FROM public.horse_hand_review_receipts r
     WHERE r.hand_id = v_hand AND r.horse_user_id = v_horse
     FOR UPDATE;

    IF v_existing IS NOT NULL THEN
      IF v_existing <> v_digest THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001',
          MESSAGE = pg_catalog.format('hhr_identity_conflict: hand %s horse %s was published with different immutable content', v_hand, v_horse);
      END IF;
      v_status := 'replayed';
    ELSE
      -- c. insert the review once
      v_review_id := NULL;
      INSERT INTO public.horse_hand_reviews (
        hand_id, table_id, tournament_id, club_id, played_at, game_variant,
        format, big_blind, horse_user_id, seat, net_amount, net_bb, pot_size,
        hole_cards, board, actions, leak_tags)
      VALUES (
        v_hand, v_table, v_tournament, v_club, v_played, v_variant,
        v_format, v_bb, v_horse, v_seat, v_net_amount, v_net_bb, v_pot,
        NULLIF(v_e -> 'hole_cards', 'null'::jsonb),
        NULLIF(v_e -> 'board', 'null'::jsonb),
        NULLIF(v_e -> 'actions', 'null'::jsonb),
        v_tags)
      ON CONFLICT (hand_id, horse_user_id) DO NOTHING
      RETURNING id INTO v_review_id;

      IF v_review_id IS NOT NULL THEN
        -- PUBLICATION HORIZON (20261008041150). This row is about to be
        -- applied for the first time. A hand played more than 30 days ago is
        -- refused instead: sp_prune_horse_hand_review_receipts may already have
        -- pruned its receipt (rollup_day over 32 UTC days old, review row gone),
        -- so applying it could count it twice. A receipt that still exists has
        -- answered above whatever the hand's age, and a legacy review row
        -- still answers historical_unknown below. Raising rolls back this
        -- review insert and every earlier row of the call.
        IF v_played < pg_catalog.now() - '30 days'::pg_catalog.interval THEN
          RAISE EXCEPTION USING ERRCODE = 'P0001',
            MESSAGE = pg_catalog.format('hhr_publication_expired: hand %s horse %s was played at %s, outside the 30-day publication horizon', v_hand, v_horse, v_played);
        END IF;
        INSERT INTO public.horse_hand_review_receipts (
          hand_id, horse_user_id, identity_digest, review_id, rollup_day, game_variant)
        VALUES (v_hand, v_horse, v_digest, v_review_id, v_day, v_variant);

        -- The rollup arithmetic of public.fn_hhr_rollup_add as installed by
        -- 20260906093726_every_tag_carries_its_own_ev, statement for
        -- statement, schema-qualified. A repeated tag is counted once per
        -- occurrence, exactly as the FOREACH there does.
        INSERT INTO public.horse_review_rollup AS r (
          horse_user_id, day, game_variant, big_wins, big_losses, sum_net_bb, leak_counts, leak_net_bb)
        VALUES (v_horse, v_day, v_variant,
                CASE WHEN v_is_win THEN 1 ELSE 0 END,
                CASE WHEN v_is_win THEN 0 ELSE 1 END,
                COALESCE(v_net_bb, 0), '{}'::jsonb, '{}'::jsonb)
        ON CONFLICT (horse_user_id, day, game_variant) DO UPDATE SET
          big_wins   = r.big_wins   + excluded.big_wins,
          big_losses = r.big_losses + excluded.big_losses,
          sum_net_bb = r.sum_net_bb + excluded.sum_net_bb,
          updated_at = pg_catalog.now();
        IF v_tags IS NOT NULL AND pg_catalog.array_length(v_tags, 1) > 0 THEN
          SELECT rr.leak_counts, rr.leak_net_bb INTO v_counts, v_nets
            FROM public.horse_review_rollup rr
           WHERE rr.horse_user_id = v_horse AND rr.day = v_day AND rr.game_variant = v_variant;
          FOREACH v_t IN ARRAY v_tags LOOP
            v_counts := pg_catalog.jsonb_set(v_counts, ARRAY[v_t],
                          pg_catalog.to_jsonb(COALESCE((v_counts ->> v_t)::int, 0) + 1));
            v_nets   := pg_catalog.jsonb_set(v_nets, ARRAY[v_t],
                          pg_catalog.to_jsonb(pg_catalog.round(
                            COALESCE((v_nets ->> v_t)::numeric, 0) + COALESCE(v_net_bb, 0), 2)));
          END LOOP;
          UPDATE public.horse_review_rollup rr
             SET leak_counts = v_counts, leak_net_bb = v_nets, updated_at = pg_catalog.now()
           WHERE rr.horse_user_id = v_horse AND rr.day = v_day AND rr.game_variant = v_variant;
        END IF;

        v_status := 'applied';
      ELSE
        -- A review row already exists. A concurrent atomic writer may have
        -- just committed it with its receipt: re-read in a new statement.
        v_existing := NULL;
        SELECT r.identity_digest INTO v_existing
          FROM public.horse_hand_review_receipts r
         WHERE r.hand_id = v_hand AND r.horse_user_id = v_horse
         FOR UPDATE;
        IF v_existing IS NOT NULL THEN
          IF v_existing <> v_digest THEN
            RAISE EXCEPTION USING ERRCODE = 'P0001',
              MESSAGE = pg_catalog.format('hhr_identity_conflict: hand %s horse %s was published with different immutable content', v_hand, v_horse);
          END IF;
          v_status := 'replayed';
        ELSE
          -- A legacy split-writer row: whether its rollup was applied is
          -- unknown. No arithmetic, no receipt, no marker.
          v_status := 'historical_unknown';
        END IF;
      END IF;
    END IF;

    v_out := v_out || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('horse_user_id', v_horse::text, 'status', v_status));
  END LOOP;

  RETURN pg_catalog.jsonb_build_object('version', 1, 'hand_id', v_hand::text, 'rows', v_out);
END
$_$;


ALTER FUNCTION public.fn_hhr_record_atomic(p_rows jsonb) OWNER TO postgres;

--
-- TOC entry 47536 (class 0 OID 0)
-- Dependencies: 4036
-- Name: FUNCTION fn_hhr_record_atomic(p_rows jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_hhr_record_atomic(p_rows jsonb) IS 'Atomic horse hand-review publication for one hand (1..10 horse rows carrying exactly the HorseReviewRow keys). One transaction: review row inserted once, horse_review_rollup arithmetic applied once (identical to fn_hhr_rollup_add), replay receipt kept. Returns {version:1, hand_id, rows:[{horse_user_id, status: applied|replayed|historical_unknown}]} in canonical horse order. Refuses with P0001 hhr_* on any invalid row or identity conflict, writing nothing; refuses hhr_publication_expired to apply a row played more than 30 days ago (its receipt may have been pruned). service_role only.';


--
-- TOC entry 7236 (class 1255 OID 16133987)
-- Name: fn_hhr_rollup_add(uuid, date, text, boolean, numeric, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_hhr_rollup_add(p_horse uuid, p_day date, p_variant text, p_is_win boolean, p_net_bb numeric, p_tags text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t text; counts jsonb; nets jsonb;
begin
  insert into horse_review_rollup as r (horse_user_id, day, game_variant, big_wins, big_losses, sum_net_bb, leak_counts, leak_net_bb)
  values (p_horse, p_day, p_variant,
          case when p_is_win then 1 else 0 end,
          case when p_is_win then 0 else 1 end,
          coalesce(p_net_bb, 0), '{}'::jsonb, '{}'::jsonb)
  on conflict (horse_user_id, day, game_variant) do update set
    big_wins   = r.big_wins   + excluded.big_wins,
    big_losses = r.big_losses + excluded.big_losses,
    sum_net_bb = r.sum_net_bb + excluded.sum_net_bb,
    updated_at = now();
  if p_tags is not null and array_length(p_tags, 1) > 0 then
    select leak_counts, leak_net_bb into counts, nets from horse_review_rollup
      where horse_user_id = p_horse and day = p_day and game_variant = p_variant;
    foreach t in array p_tags loop
      counts = jsonb_set(counts, array[t], to_jsonb(coalesce((counts->>t)::int, 0) + 1));
      -- The SAME hand's net against every tag it carries. A hand with three
      -- tags contributes its net to all three: each tag is a separate claim
      -- about that hand, and each is judged on the hands that carry it.
      nets = jsonb_set(nets, array[t],
               to_jsonb(round(coalesce((nets->>t)::numeric, 0) + coalesce(p_net_bb, 0), 2)));
    end loop;
    update horse_review_rollup set leak_counts = counts, leak_net_bb = nets, updated_at = now()
      where horse_user_id = p_horse and day = p_day and game_variant = p_variant;
  end if;
end $$;


ALTER FUNCTION public.fn_hhr_rollup_add(p_horse uuid, p_day date, p_variant text, p_is_win boolean, p_net_bb numeric, p_tags text[]) OWNER TO postgres;

--
-- TOC entry 8013 (class 1255 OID 4534130)
-- Name: fn_home_assign_seat(uuid, uuid, integer, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_home_assign_seat(p_caller uuid, p_game_id uuid, p_seat_number integer, p_user_id uuid DEFAULT NULL::uuid, p_player_name text DEFAULT NULL::text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_exists boolean;
BEGIN
    IF auth.role() IS DISTINCT FROM 'service_role'
       AND (auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_caller) THEN
        RETURN jsonb_build_object('success', false, 'error', 'unauthorized: caller identity mismatch');
    END IF;
    IF NOT fn_home_caller_is_game_staff(p_caller, p_game_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not authorized');
    END IF;
    IF p_seat_number IS NULL OR p_seat_number < 1 OR p_seat_number > 12 THEN
        RETURN jsonb_build_object('success', false, 'error', 'seat_number must be 1..12');
    END IF;
    IF p_user_id IS NULL AND (p_player_name IS NULL OR LENGTH(TRIM(p_player_name)) = 0) THEN
        RETURN jsonb_build_object('success', false, 'error', 'either user_id or player_name required');
    END IF;
    IF p_player_name IS NOT NULL AND LENGTH(p_player_name) > 60 THEN
        RETURN jsonb_build_object('success', false, 'error', 'player_name too long (max 60)');
    END IF;
    IF p_note IS NOT NULL AND LENGTH(p_note) > 500 THEN
        RETURN jsonb_build_object('success', false, 'error', 'note too long (max 500)');
    END IF;

    SELECT EXISTS (SELECT 1 FROM commander_home_seats
                    WHERE game_id = p_game_id AND seat_number = p_seat_number) INTO v_exists;
    IF NOT v_exists THEN
        INSERT INTO commander_home_seats (game_id, seat_number) VALUES (p_game_id, p_seat_number);
    END IF;

    IF p_user_id IS NOT NULL THEN
        UPDATE commander_home_seats
           SET user_id = NULL, player_name = NULL, status = 'empty',
               seated_at = NULL, away_since = NULL, note = NULL, updated_at = NOW()
         WHERE game_id = p_game_id AND user_id = p_user_id AND seat_number <> p_seat_number;
    END IF;

    UPDATE commander_home_seats
       SET user_id = p_user_id, player_name = p_player_name, status = 'seated',
           seated_at = COALESCE(seated_at, NOW()), away_since = NULL,
           note = p_note, updated_at = NOW()
     WHERE game_id = p_game_id AND seat_number = p_seat_number;

    RETURN jsonb_build_object('success', true, 'game_id', p_game_id, 'seat_number', p_seat_number);
END;
$$;


ALTER FUNCTION public.fn_home_assign_seat(p_caller uuid, p_game_id uuid, p_seat_number integer, p_user_id uuid, p_player_name text, p_note text) OWNER TO postgres;

--
-- TOC entry 9007 (class 1255 OID 14816682)
-- Name: fn_home_audit_privileged_write(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_home_audit_privileged_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_row      record;
  v_group    uuid;
  v_target   text := TG_ARGV[0];
  v_action   text := lower(TG_OP);
BEGIN
  v_row := COALESCE(NEW, OLD);

  BEGIN
    -- Seats reach their group through the game; the other two carry it.
    IF TG_TABLE_NAME = 'commander_home_seats' THEN
      SELECT g.group_id INTO v_group
        FROM commander_home_games g WHERE g.id = v_row.game_id;
    ELSE
      EXECUTE format('SELECT ($1).%I', 'group_id') INTO v_group USING v_row;
    END IF;

    INSERT INTO commander_home_audit_log
      (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (
      v_group,
      auth.uid(),
      v_target,
      v_row.id,
      v_target || '_' || v_action,
      CASE
        WHEN TG_OP = 'UPDATE' THEN jsonb_build_object(
          'before', to_jsonb(OLD) - 'updated_at',
          'after',  to_jsonb(NEW) - 'updated_at')
        WHEN TG_OP = 'DELETE' THEN jsonb_build_object('before', to_jsonb(OLD))
        ELSE jsonb_build_object('after', to_jsonb(NEW))
      END);
  EXCEPTION WHEN OTHERS THEN
    -- An audit that cannot be written must not stop a host seating a player.
    -- The failure is swallowed here and surfaced by the health check, which
    -- reports how many privileged tables carry this trigger.
    NULL;
  END;

  RETURN NULL;  -- AFTER trigger
END;
$_$;


ALTER FUNCTION public.fn_home_audit_privileged_write() OWNER TO postgres;

--
-- TOC entry 5105 (class 1255 OID 4916496)
-- Name: fn_home_auto_hide_on_report_threshold(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_home_auto_hide_on_report_threshold() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_trusted_writer boolean;
  v_threshold int;
  v_open_count int;
  v_author_id uuid;
  v_group_id uuid;
BEGIN
  IF TG_RELID <> 'public.commander_home_content_reports'::regclass
     OR TG_NAME <> 'trg_home_auto_hide_on_report_threshold'
     OR TG_OP <> 'INSERT' OR TG_WHEN <> 'AFTER' OR TG_LEVEL <> 'ROW' THEN
    RAISE EXCEPTION 'Report moderation requires its canonical INSERT trigger' USING ERRCODE='42501';
  END IF;
  -- Do not trust SECURITY DEFINER current_user or session_user alone.
  v_trusted_writer := current_setting('role',true)='service_role'
    OR (current_setting('role',true)='none' AND session_user='postgres');
  IF NOT v_trusted_writer AND (
      current_setting('role',true) IS DISTINCT FROM 'authenticated'
      OR auth.uid() IS NULL OR NEW.reporter_id IS DISTINCT FROM auth.uid()
      OR NEW.status IS DISTINCT FROM 'pending') THEN
    RAISE EXCEPTION 'Report actor must match the authenticated caller and pending state' USING ERRCODE='42501';
  END IF;
  IF TG_OP <> 'INSERT' OR NEW.status NOT IN ('pending','hidden_pending_review') THEN
    RETURN NEW;
  END IF;

  SELECT value::int INTO v_threshold FROM public.platform_policies
   WHERE key = 'home_games.moderation.auto_hide_threshold';
  IF v_threshold IS NULL THEN v_threshold := 3; END IF;

  SELECT COUNT(*) INTO v_open_count FROM public.commander_home_content_reports
   WHERE reported_type = NEW.reported_type AND reported_id = NEW.reported_id
     AND status IN ('pending','hidden_pending_review');

  IF v_open_count < v_threshold THEN RETURN NEW; END IF;

  -- Resolve group + author
  CASE NEW.reported_type
    WHEN 'post' THEN
      UPDATE public.commander_home_posts
         SET is_hidden = true, hidden_at = COALESCE(hidden_at, now()),
             hidden_reason = COALESCE(hidden_reason, 'auto_hide_threshold_reached')
       WHERE id = NEW.reported_id AND is_hidden = false
      RETURNING author_id, group_id INTO v_author_id, v_group_id;
    WHEN 'comment' THEN
      WITH updated AS (
        UPDATE public.commander_home_post_comments
           SET is_hidden = true, hidden_at = COALESCE(hidden_at, now()),
               hidden_reason = COALESCE(hidden_reason, 'auto_hide_threshold_reached')
         WHERE id = NEW.reported_id AND is_hidden = false
        RETURNING author_id, post_id)
      SELECT u.author_id, p.group_id INTO v_author_id, v_group_id
        FROM updated u JOIN public.commander_home_posts p ON p.id = u.post_id;
    WHEN 'review' THEN
      WITH updated AS (
        UPDATE public.commander_home_game_reviews
           SET is_hidden = true, hidden_at = COALESCE(hidden_at, now()),
               hidden_reason = COALESCE(hidden_reason, 'auto_hide_threshold_reached')
         WHERE id = NEW.reported_id AND is_hidden = false
        RETURNING reviewer_id, game_id)
      SELECT u.reviewer_id, g.group_id INTO v_author_id, v_group_id
        FROM updated u JOIN public.commander_home_games g ON g.id = u.game_id;
    ELSE RETURN NEW;
  END CASE;

  UPDATE public.commander_home_content_reports
     SET status = 'hidden_pending_review',
         content_hidden_at = COALESCE(content_hidden_at, now())
   WHERE reported_type = NEW.reported_type AND reported_id = NEW.reported_id
     AND status = 'pending';

  IF v_author_id IS NOT NULL THEN
    PERFORM public.fn_emit_home_notification(
      p_user_id => v_author_id, p_type => 'moderation_auto_hide',
      p_title => 'Your content was hidden pending review',
      p_message => 'Multiple users reported your ' || NEW.reported_type ||
                   '. It is temporarily hidden while a moderator reviews. ' ||
                   'If the reports are dismissed, it will be restored.',
      p_link => NULL,
      p_data => jsonb_build_object('reported_type', NEW.reported_type,
                                   'reported_id', NEW.reported_id),
      p_pref_column => NULL);
  END IF;

  -- ★ NEW: audit log - actor_id NULL = system action
  IF v_group_id IS NOT NULL THEN
    INSERT INTO public.commander_home_audit_log
      (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (
      v_group_id, NULL, NEW.reported_type, NEW.reported_id,
      'moderation.auto_hide_threshold',
      jsonb_build_object('threshold', v_threshold,
                         'open_reports', v_open_count,
                         'report_id', NEW.id));
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_home_auto_hide_on_report_threshold() OWNER TO postgres;

--
-- TOC entry 5918 (class 1255 OID 4534128)
-- Name: fn_home_caller_is_game_staff(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_home_caller_is_game_staff(p_caller uuid, p_game_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group_id uuid;
BEGIN
    IF p_caller IS NULL OR p_game_id IS NULL THEN RETURN false; END IF;

    SELECT g.group_id INTO v_group_id FROM commander_home_games g WHERE g.id = p_game_id;
    IF v_group_id IS NULL THEN RETURN false; END IF;

    IF EXISTS (SELECT 1 FROM commander_home_groups
               WHERE id = v_group_id AND owner_id = p_caller) THEN
        RETURN true;
    END IF;

    IF EXISTS (SELECT 1 FROM commander_home_members
               WHERE group_id = v_group_id
                 AND user_id = p_caller
                 AND status = 'approved'
                 AND role IN ('owner','admin')) THEN
        RETURN true;
    END IF;

    RETURN false;
END;
$$;


ALTER FUNCTION public.fn_home_caller_is_game_staff(p_caller uuid, p_game_id uuid) OWNER TO postgres;

--
-- TOC entry 5275 (class 1255 OID 4711646)
-- Name: fn_home_force_insert_origin_ts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_home_force_insert_origin_ts() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text := current_user;
BEGIN
  IF v_role IN ('postgres', 'supabase_admin', 'service_role',
                'supabase_auth_admin', 'supabase_storage_admin') THEN
    RETURN NEW;
  END IF;

  IF pg_trigger_depth() > 1 THEN
    RETURN NEW;
  END IF;

  -- Each branch resolves the correct column on the row type at compile time,
  -- bypassing the need for dynamic SQL / hstore. Unreachable branches are
  -- never parsed against the wrong row type because plpgsql defers record
  -- member resolution to first execution per call path.
  IF TG_TABLE_NAME = 'commander_home_rsvps' THEN
    NEW.responded_at := NOW();
  ELSIF TG_TABLE_NAME = 'commander_home_group_promotion_requests' THEN
    NEW.requested_at := NOW();
  ELSE
    NEW.created_at := NOW();
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_home_force_insert_origin_ts() OWNER TO postgres;

--
-- TOC entry 47543 (class 0 OID 0)
-- Dependencies: 5275
-- Name: FUNCTION fn_home_force_insert_origin_ts(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_home_force_insert_origin_ts() IS 'Pass 47 BK-3 v2: BEFORE INSERT pair for fn_home_protect_row_identity. Overwrites the origin-timestamp column with NOW() for non-service-role callers. Branches by TG_TABLE_NAME to resolve the right column per table (created_at by default, responded_at for RSVPs, requested_at for promotion_requests). Prevents INSERT-time chronology tamper (BK-3).';


--
-- TOC entry 4639 (class 1255 OID 4632038)
-- Name: fn_home_game_auto_complete(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_home_game_auto_complete() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_completed int := 0;
    v_game      RECORD;
BEGIN
    -- Flip to completed if: status in scheduled/confirmed AND 
    -- (scheduled_date + COALESCE(end_time, 3am_next_day) + 6h) < NOW()
    FOR v_game IN
        SELECT * FROM commander_home_games
         WHERE status IN ('scheduled','confirmed','in_progress')
           AND (
               scheduled_date + COALESCE(end_time, TIME '03:00') 
                 + INTERVAL '6 hours'
                 + CASE WHEN end_time IS NULL OR end_time < TIME '06:00' 
                        THEN INTERVAL '1 day' ELSE INTERVAL '0 day' END
               ) < NOW()
    LOOP
        -- Use SECURITY DEFINER path through direct UPDATE (skip the complete_home_game RPC 
        -- because it wants auth.uid(); this is cron context)
        UPDATE commander_home_games 
           SET status = 'completed', updated_at = NOW()
         WHERE id = v_game.id;

        -- Bump group's games_hosted
        UPDATE commander_home_groups 
           SET games_hosted = COALESCE(games_hosted, 0) + 1
         WHERE id = v_game.group_id;

        -- Mark flakes
        UPDATE commander_home_rsvps
           SET flaked = true
         WHERE game_id = v_game.id 
           AND response = 'yes' 
           AND checked_in_at IS NULL;

        -- Increment attended for checked-in members
        UPDATE commander_home_members m
           SET games_attended = COALESCE(m.games_attended, 0) + 1,
               last_attended  = NOW()
          FROM commander_home_rsvps r
         WHERE r.game_id = v_game.id AND r.user_id = m.user_id
           AND m.group_id = v_game.group_id AND r.checked_in_at IS NOT NULL;

        INSERT INTO commander_home_audit_log (group_id, actor_id, target_type, target_id, action, metadata)
        VALUES (v_game.group_id, NULL, 'game', v_game.id, 'auto_completed',
                jsonb_build_object('source', 'cron', 'scheduled_date', v_game.scheduled_date));

        v_completed := v_completed + 1;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'completed_count', v_completed,
        'run_at', NOW()
    );
END;
$$;


ALTER FUNCTION public.fn_home_game_auto_complete() OWNER TO postgres;

--
-- TOC entry 6696 (class 1255 OID 4632040)
-- Name: fn_home_game_recap_prompt(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_home_game_recap_prompt() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_sent int := 0;
    v_attendee RECORD;
    v_slug text;
BEGIN
    FOR v_attendee IN
        SELECT r.id AS rsvp_id, r.user_id, r.game_id,
               g.title, g.scheduled_date, g.group_id
          FROM commander_home_rsvps r
          JOIN commander_home_games g ON g.id = r.game_id
         WHERE r.checked_in_at IS NOT NULL
           AND r.review_prompt_sent_at IS NULL
           AND g.status = 'completed'
           AND g.updated_at < NOW() - INTERVAL '12 hours'
           AND g.updated_at > NOW() - INTERVAL '7 days'  -- don't backfill ancient games
           AND NOT EXISTS (
               SELECT 1 FROM commander_home_game_reviews rv
                WHERE rv.game_id = r.game_id AND rv.reviewer_id = r.user_id)
    LOOP
        SELECT sp.slug INTO v_slug FROM social_pages sp
         WHERE sp.linked_entity_type = 'home_group' AND sp.linked_entity_id = v_attendee.group_id::text LIMIT 1;

        PERFORM public.fn_emit_home_notification(
            v_attendee.user_id, 'home_game_review_prompt',
            'How was ' || COALESCE(v_attendee.title, 'the game') || '?',
            'Leave a quick review for the host.',
            '/hub/home-games/' || COALESCE(v_slug, v_attendee.group_id::text) || '/games/' || v_attendee.game_id::text,
            jsonb_build_object('game_id', v_attendee.game_id),
            'home_game_review_prompts'
        );

        UPDATE commander_home_rsvps 
           SET review_prompt_sent_at = NOW()
         WHERE id = v_attendee.rsvp_id;

        v_sent := v_sent + 1;
    END LOOP;

    RETURN jsonb_build_object('success', true, 'prompts_sent', v_sent, 'run_at', NOW());
END;
$$;


ALTER FUNCTION public.fn_home_game_recap_prompt() OWNER TO postgres;

