--
-- TOC entry 7316 (class 1255 OID 4632394)
-- Name: fn_home_group_refresh_search_vector(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_home_group_refresh_search_vector() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    NEW.search_vector := 
          setweight(to_tsvector('english', coalesce(NEW.name, '')), 'A')
       || setweight(to_tsvector('english', coalesce(NEW.tagline, '')), 'B')
       || setweight(to_tsvector('english', coalesce(NEW.city, '')), 'B')
       || setweight(to_tsvector('english', coalesce(NEW.state, '')), 'C')
       || setweight(to_tsvector('english', coalesce(NEW.description, '')), 'D')
       || setweight(to_tsvector('english', coalesce(array_to_string(NEW.tags, ' '), '')), 'B');
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_home_group_refresh_search_vector() OWNER TO postgres;

