-- Name: FUNCTION fn_home_is_group_staff(p_caller uuid, p_group_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_home_is_group_staff(p_caller uuid, p_group_id uuid) IS 'RLS helper: is p_caller staff (owner/admin/co_host) of p_group_id. MUST remain SECURITY DEFINER with row_security=off - it is called from 13 RLS policies and reads commander_home_members, which is itself RLS-protected. Reverting to SECURITY INVOKER silently breaks every staff check. See migration phase50_restore_secdef_on_home_rls_helpers.';


--
-- TOC entry 4692 (class 1255 OID 4534135)
-- Name: fn_home_list_seats(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_home_list_seats(p_game_id uuid) RETURNS TABLE(seat_number integer, status text, user_id uuid, username text, display_name text, avatar_url text, player_name text, seated_at timestamp with time zone, away_since timestamp with time zone, note text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group_id uuid;
    v_caller uuid := auth.uid();
BEGIN
    -- Service_role path: skip auth (server-side/cron/admin tooling)
    IF auth.role() = 'service_role' THEN
        RETURN QUERY
        SELECT s.seat_number, s.status, s.user_id, p.username,
               COALESCE(p.display_name, p.username) AS display_name,
               p.avatar_url, s.player_name, s.seated_at, s.away_since, s.note
          FROM commander_home_seats s
          LEFT JOIN profiles p ON p.id = s.user_id
         WHERE s.game_id = p_game_id
         ORDER BY s.seat_number;
        RETURN;
    END IF;

    -- Authenticated path: caller must be approved member of the group
    IF v_caller IS NULL THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;

    SELECT g.group_id INTO v_group_id
      FROM commander_home_games g WHERE g.id = p_game_id;
    IF v_group_id IS NULL THEN
        RAISE EXCEPTION 'GAME_NOT_FOUND';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM commander_home_members m
         WHERE m.group_id = v_group_id
           AND m.user_id  = v_caller
           AND m.status   = 'approved'
    ) THEN
        RAISE EXCEPTION 'NOT_A_GROUP_MEMBER';
    END IF;

    RETURN QUERY
    SELECT s.seat_number, s.status, s.user_id, p.username,
           COALESCE(p.display_name, p.username) AS display_name,
           p.avatar_url, s.player_name, s.seated_at, s.away_since, s.note
      FROM commander_home_seats s
      LEFT JOIN profiles p ON p.id = s.user_id
     WHERE s.game_id = p_game_id
     ORDER BY s.seat_number;
END;
$$;


ALTER FUNCTION public.fn_home_list_seats(p_game_id uuid) OWNER TO postgres;

