-- Name: FUNCTION fn_horse_adaptive_journal_snapshot(p_actor_key text, p_scope_key text, p_partition text, p_cohort text, p_from_ms bigint, p_to_ms bigint); Type: COMMENT; Schema: public; Owner: postgres
