--
-- TOC entry 6804 (class 1255 OID 120879972)
-- Name: fn_horse_commitment_selection_receipt(date, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_commitment_selection_receipt(p_day date, p_after_played_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_hand_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 8) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET statement_timeout TO '3s'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
  captured_at timestamptz:=statement_timestamp();
  d public.horse_commitment_audit_days%ROWTYPE;
  day_state jsonb:=NULL; passes jsonb; gaps jsonb:='[]'::jsonb; item jsonb; next_cursor jsonb:=NULL;
  r record; count_rows integer:=0; more boolean:=false; reasons text[]; result jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'hcsr_role_required' USING ERRCODE='42501';
  END IF;
  IF p_day IS NULL OR p_day<DATE '2000-01-01' OR p_day>=DATE '2100-01-01'
    OR p_day>=(captured_at AT TIME ZONE 'UTC')::date OR p_limit IS DISTINCT FROM 8
    OR num_nonnulls(p_after_played_at,p_after_hand_id)=1
    OR (p_after_played_at IS NOT NULL AND (NOT isfinite(p_after_played_at)
      OR (p_after_played_at AT TIME ZONE 'UTC')::date<>p_day)) THEN
    RAISE EXCEPTION 'hcsr_selection_request_invalid';
  END IF;
  SELECT * INTO d FROM public.horse_commitment_audit_days WHERE day=p_day;
  IF FOUND THEN
    day_state:=jsonb_build_object('pass',d.pass,
      'startedAt',to_char(d.started_at,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'lastBatchAt',to_char(d.last_batch_at,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'finishedAt',to_char(d.finished_at,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'cursor',CASE WHEN d.after_created_at IS NULL THEN NULL ELSE jsonb_build_object(
        'createdAt',to_char(d.after_created_at,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'handId',d.after_hand_id) END,
      'scannedHands',d.scanned_hands,'horseHands',d.horse_hands,'flaggedHorseHands',d.flagged_horse_hands,
      'unknownHorseHands',d.unknown_horse_hands,'handGaps',d.hand_gaps);
  END IF;
  -- Every receipt of the day, newest 32 at most, returned ascending.
  SELECT coalesce(jsonb_agg(x.item ORDER BY x.pass),'[]'::jsonb) INTO passes FROM (
    SELECT p.pass,jsonb_build_object('pass',p.pass,
      'windowStart',to_char(p.window_start,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'windowEnd',to_char(p.window_end,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'cutover',to_char(p.cutover,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'maxScannedCreatedAt',to_char(p.max_scanned_created_at,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'scannedHands',p.scanned_hands,'horseHands',p.horse_hands,'flaggedHorseHands',p.flagged_horse_hands,
      'unknownHorseHands',p.unknown_horse_hands,'handGaps',p.hand_gaps,
      'handsWithoutCommit',p.hands_without_commit,'missingSourceHands',p.missing_source_hands,
      'lateArrivalHands',p.late_arrival_hands,
      'finalCursor',CASE WHEN p.final_after_created_at IS NULL THEN NULL ELSE jsonb_build_object(
        'createdAt',to_char(p.final_after_created_at,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'handId',p.final_after_hand_id) END,
      'startedAt',to_char(p.started_at,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'finishedAt',to_char(p.finished_at,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'sourceCoverage',p.source_coverage,'identityBasis',p.identity_basis) AS item
    FROM public.horse_commitment_audit_passes p WHERE p.day=p_day ORDER BY p.pass DESC LIMIT 32) x;
  -- Gap-only hands: a gap row with no review row. Reviewed hands already
  -- carry their gaps on fn_horse_commitment_review_page.
  FOR r IN
    SELECT g.hand_id,g.played_at,
      CASE WHEN pg_column_size(g.reasons)<=8192 AND cardinality(g.reasons) BETWEEN 1 AND 32
        AND array_ndims(g.reasons)=1 THEN g.reasons END AS reasons,
      (SELECT h.table_id FROM public.hand_history h WHERE h.id=g.hand_id LIMIT 1) AS table_id
    FROM public.horse_commitment_audit_gaps g
    WHERE g.played_at>=p_day::timestamp AT TIME ZONE 'UTC' AND g.played_at<(p_day+1)::timestamp AT TIME ZONE 'UTC'
      AND (p_after_played_at IS NULL OR (g.played_at,g.hand_id)>(p_after_played_at,p_after_hand_id))
      AND NOT EXISTS (SELECT 1 FROM public.horse_commitment_reviews q WHERE q.hand_id=g.hand_id)
    ORDER BY g.played_at,g.hand_id LIMIT 9
  LOOP
    count_rows:=count_rows+1;
    IF count_rows=9 THEN more:=true; EXIT; END IF;
    reasons:=r.reasons;
    IF reasons IS NULL OR EXISTS(SELECT 1 FROM unnest(reasons) x WHERE x IS NULL OR x='' OR octet_length(x)>160) THEN
      reasons:=ARRAY['daily_gap_reasons_unavailable'];
    END IF;
    next_cursor:=jsonb_build_object('playedAt',to_char(r.played_at,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'handId',r.hand_id);
    item:=jsonb_build_object('handId',r.hand_id,'tableId',r.table_id,'playedAt',next_cursor->'playedAt','reasons',to_jsonb(reasons));
    -- JSON escaping can expand otherwise bounded text; bound before the wire.
    IF octet_length(item::text)>4096 THEN
      item:=jsonb_build_object('handId',r.hand_id,'tableId',r.table_id,'playedAt',next_cursor->'playedAt',
        'reasons',jsonb_build_array('daily_gap_reasons_unavailable'));
    END IF;
    gaps:=gaps||jsonb_build_array(item);
  END LOOP;
  result:=jsonb_build_object('version',1,'source','horse_commitment_selection_receipt','day',p_day,
    'readAt',to_char(captured_at,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'limit',8,
    'after',CASE WHEN p_after_played_at IS NULL THEN NULL ELSE jsonb_build_object(
      'playedAt',to_char(p_after_played_at,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'handId',p_after_hand_id) END,
    'dayState',day_state,'passes',passes,'gaps',gaps,'hasMore',more,'next',next_cursor,
    'sourceCoverage','not_established','identityBasis',public.fn_horse_commitment_identity_basis(p_day,NULL,NULL),
    'gtoVerified',false,'activationAllowed',false);
  IF octet_length(result::text)>65536 THEN
    RAISE EXCEPTION 'hcsr_receipt_exceeds_bounds';
  END IF;
  RETURN result;
END;
$$;


ALTER FUNCTION public.fn_horse_commitment_selection_receipt(p_day date, p_after_played_at timestamp with time zone, p_after_hand_id uuid, p_limit integer) OWNER TO postgres;

--
-- TOC entry 6829 (class 1255 OID 30208571)
-- Name: fn_horse_committed_observation_snapshot(uuid, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_committed_observation_snapshot(p_actor uuid, p_from_ms bigint, p_through_ms bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_at timestamptz := statement_timestamp();
  v_now_ms bigint := floor(extract(epoch FROM v_at) * 1000)::bigint;
  v_from timestamptz;
  v_through timestamptz;
  v_rows jsonb;
  v_count integer;
  v_actions bigint;
  v_bytes bigint;
  v_invalid boolean;
  v_missing_receipt boolean;
BEGIN
  -- Six-hour source windows within the latest day. The deployed horse-only
  -- prune has a one-day minimum; this does not promise historical retention
  -- or that actions in hands which have not committed are already visible.
  IF p_actor IS NULL OR p_from_ms IS NULL OR p_through_ms IS NULL
     OR p_from_ms < v_now_ms - 86400000 OR p_through_ms > v_now_ms
     OR p_through_ms <= p_from_ms OR p_through_ms - p_from_ms > 21600000 THEN
    RETURN jsonb_build_object('version',1,'status','unavailable','reason','invalid_window');
  END IF;
  v_from := to_timestamp(p_from_ms::double precision / 1000);
  v_through := to_timestamp(p_through_ms::double precision / 1000);

  -- 2026-10-22 (second pass): an overflowing window is refused before any
  -- history row is read. Each ca_hand_player_idx row is written from the
  -- hand's own roster with the hand's own created_at, so 513 index rows whose
  -- (created_at, id) still exist in hand_history prove more than 512 hands
  -- in this window. That answer comes from two indexes (the per-player time
  -- index and idx_hand_history_time_identity) instead of 513 random heap
  -- reads plus roster rechecks: 1.6-3.7 s -> well under 1 s on production.
  -- It can only refuse, never admit: a window under the budget still goes
  -- through the full roster-qualified read below, and a refusal only makes
  -- the capture worker refine to a smaller slice that is read exactly.
  SELECT count(*)::integer INTO v_count FROM (
    SELECT 1 FROM public.ca_hand_player_idx i
     WHERE i.user_id = p_actor AND i.created_at > v_from AND i.created_at <= v_through
       AND EXISTS (SELECT 1 FROM public.hand_history h
                    WHERE h.created_at = i.created_at AND h.id = i.hand_id)
     LIMIT 513) overflow;
  IF v_count > 512 THEN
    RETURN jsonb_build_object(
      'version',1,'status','unavailable','reason','hand_budget_exceeded',
      'actor',p_actor,'fromMs',p_from_ms,'throughMs',p_through_ms,
      'readAtMs',v_now_ms,'snapshotId',pg_current_snapshot()::text,
      'coverage','retained_committed_roster_rows','acceptance','atomic_hand_receipts',
      'handCount',v_count,'actionCount',NULL,'sourceBytes',NULL,'hands','[]'::jsonb);
  END IF;

  -- 2026-10-22: candidates are FOUND through the per-player time index and
  -- the pending projection outbox, and QUALIFIED by the canonical roster on
  -- the history row itself. The roster GIN alone cannot bound time: for a
  -- busy horse it matched ~38,000 hands across retention to keep 513, read
  -- ~37,000 random heap pages and held hand_history for up to 8 seconds.
  --
  -- Completeness in this one snapshot: a committed hand writes its history
  -- row and its hand_projection_outbox row in one transaction; the projector
  -- writes ca_hand_player_idx (same created_at) and deletes the outbox row in
  -- one transaction. So every visible hand is reachable through the outbox
  -- or through the index, never neither. A voided stat fact removes one
  -- index row while the roster keeps the player; those hands are re-added.
  -- The roster containment and window are rechecked on the history row, so
  -- the index can only narrow the search, never decide membership.
  WITH found AS MATERIALIZED (
    SELECT i.hand_id FROM public.ca_hand_player_idx i
     WHERE i.user_id = p_actor AND i.created_at > v_from AND i.created_at <= v_through
    UNION
    SELECT o.hand_id FROM public.hand_projection_outbox o
    UNION
    SELECT r.hand_id FROM public.ca_hand_fact_revisions r
     WHERE r.user_id = p_actor AND r.kind = 'void'
  ), candidates AS MATERIALIZED (
    -- One primary-key probe per found hand. The roster test is wrapped in
    -- IS TRUE so the planner cannot turn it back into the roster GIN scan
    -- this replaces. A 513th row proves overflow; it is never silently
    -- dropped. No action payload is read until the bounded set is known.
    SELECT h.id, h.created_at, h.table_id, h.hand_number
      FROM found f
     CROSS JOIN LATERAL (
       SELECT h.id, h.created_at, h.table_id, h.hand_number
         FROM public.hand_history h
        WHERE h.id = f.hand_id
          AND h.created_at > v_from
          AND h.created_at <= v_through
          AND (h.players @> jsonb_build_array(jsonb_build_object('userId',p_actor::text))) IS TRUE
     ) h
     LIMIT 513
  ), measured AS MATERIALIZED (
    SELECT c.id, c.created_at, c.table_id, c.hand_number, h.actions,
           a.payload_hash AS acceptance_hash,
           a.hand_id IS NULL AS missing_receipt,
           octet_length(h.actions::text) AS bytes,
           CASE WHEN jsonb_typeof(h.actions)='array'
                THEN jsonb_array_length(h.actions) ELSE 0 END AS action_count,
           CASE WHEN jsonb_typeof(h.actions)='array'
                THEN jsonb_array_length(h.actions) > 4096 ELSE true END AS invalid
      FROM candidates c
      JOIN public.hand_history h ON h.id = c.id
      LEFT JOIN public.hand_atomic_commits a
        ON a.hand_id=c.id AND a.table_id=c.table_id AND a.hand_number=c.hand_number
  ), totals AS (
    SELECT count(*)::integer AS n, coalesce(sum(bytes),0)::bigint AS bytes,
           coalesce(sum(action_count),0)::bigint AS actions,
           coalesce(bool_or(invalid OR bytes > 1048576),false) AS invalid,
           coalesce(bool_or(missing_receipt),false) AS missing_receipt
      FROM measured
  )
  SELECT t.n, t.bytes, t.invalid, t.missing_receipt, t.actions,
         CASE WHEN t.n <= 512 AND t.bytes <= 8388608 AND t.actions <= 20000 AND NOT t.invalid AND NOT t.missing_receipt THEN
           (SELECT coalesce(jsonb_agg(jsonb_build_object(
               'id',m.id,
               'acceptance',jsonb_build_object('kind','atomic_hand_receipt','tableId',m.table_id,
                 'handNumber',m.hand_number,'payloadHash',m.acceptance_hash),
               'createdAt',to_char(m.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
               -- Exclude showdown, hole cards, outcomes, names and arbitrary
               -- action fields before crossing the service boundary. Ordinals
               -- and non-betting entries stay intact for public-line replay.
               'actions',(SELECT coalesce(jsonb_agg(
                   CASE WHEN jsonb_typeof(a.value)='object' THEN
                     (SELECT coalesce(jsonb_object_agg(f.key,f.value),'{}'::jsonb)
                        FROM jsonb_each(a.value) f
                       WHERE f.key IN ('userId','action','stage','timestamp',
                                       'publicNode','origin','observationIdentity'))
                   ELSE a.value END ORDER BY a.ordinality),'[]'::jsonb)
                   FROM jsonb_array_elements(m.actions) WITH ORDINALITY a(value,ordinality))
             ) ORDER BY m.created_at,m.id),'[]'::jsonb) FROM measured m)
         ELSE '[]'::jsonb END
    INTO v_count,v_bytes,v_invalid,v_missing_receipt,v_actions,v_rows FROM totals t;

  RETURN jsonb_build_object(
    'version',1,
    'status',CASE WHEN v_count > 512 OR v_bytes > 8388608 OR v_actions > 20000 OR v_invalid OR v_missing_receipt
                  THEN 'unavailable' ELSE 'snapshot' END,
    'reason',CASE WHEN v_count > 512 THEN 'hand_budget_exceeded'
                  WHEN v_bytes > 8388608 THEN 'byte_budget_exceeded'
                  WHEN v_actions > 20000 THEN 'action_budget_exceeded'
                  WHEN v_invalid THEN 'invalid_or_oversized_hand'
                  WHEN v_missing_receipt THEN 'atomic_receipt_missing' ELSE NULL END,
    'actor',p_actor,'fromMs',p_from_ms,'throughMs',p_through_ms,
    'readAtMs',v_now_ms,'snapshotId',pg_current_snapshot()::text,
    'coverage','retained_committed_roster_rows','acceptance','atomic_hand_receipts',
    'handCount',v_count,'actionCount',v_actions,'sourceBytes',v_bytes,'hands',v_rows
  );
END
$$;


