--
-- TOC entry 5117 (class 1255 OID 22237563)
-- Name: fn_horse_tag_ev(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_tag_ev(p_since date) RETURNS TABLE(situation text, mirrored boolean, hands bigint, won_hands bigint, net_bb numeric, bb_per_hand numeric, win_rate numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with flat as (
    select k as tag,
           (r.leak_counts->>k)::bigint               as cnt,
           coalesce((r.leak_net_bb->>k)::numeric, 0) as net
      from horse_review_rollup r, lateral jsonb_object_keys(r.leak_counts) k
     where r.day >= p_since
  ),
  agg as (
    select tag, sum(cnt)::bigint as cnt, sum(net) as net from flat group by tag
  ),
  paired as (
    select
      case
        when a.tag like '%\_won'  then left(a.tag, length(a.tag) - 4)
        when a.tag like '%\_lost' then left(a.tag, length(a.tag) - 5)
        else a.tag
      end                        as situation,
      a.tag like '%\_won'        as is_won,
      a.cnt, a.net
    from agg a
  )
  select p.situation,
         -- The fold family cannot have a mirror. Everything else does, whether
         -- or not it won this week.
         p.situation not in ('big_bet_fold','big_fold_river','big_fold_early','bet_fold_line')
                                                              as mirrored,
         sum(p.cnt)::bigint                                    as hands,
         coalesce(sum(p.cnt) filter (where p.is_won), 0)::bigint as won_hands,
         round(sum(p.net), 1)                                  as net_bb,
         round(sum(p.net) / nullif(sum(p.cnt), 0), 2)          as bb_per_hand,
         round(coalesce(sum(p.cnt) filter (where p.is_won), 0)::numeric
               / nullif(sum(p.cnt), 0), 3)                     as win_rate
    from paired p
   group by p.situation
  having sum(p.cnt) >= 100
   order by 6 asc;
$$;


ALTER FUNCTION public.fn_horse_tag_ev(p_since date) OWNER TO postgres;

--
-- TOC entry 4112 (class 1255 OID 64270073)
-- Name: fn_horse_tag_ev_significance(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_tag_ev_significance(p_since date) RETURNS TABLE(situation text, hands bigint, bb_per_hand numeric, sd_est numeric, z numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with flat as (
    select k as tag, (r.leak_counts->>k)::bigint as cnt,
           coalesce((r.leak_net_bb->>k)::numeric, 0) as net
      from horse_review_rollup r, lateral jsonb_object_keys(r.leak_counts) k
     where r.day >= p_since),
  agg as (select tag, sum(cnt)::numeric cnt, sum(net)::numeric net from flat group by tag),
  p as (select case when tag like '%\_won'  then left(tag, length(tag) - 4)
                    when tag like '%\_lost' then left(tag, length(tag) - 5)
                    else tag end as situation,
               tag like '%\_won' as is_won, cnt, net from agg),
  s as (select situation,
               sum(cnt) filter (where is_won)     as wn, sum(net) filter (where is_won)     as wnet,
               sum(cnt) filter (where not is_won) as ln, sum(net) filter (where not is_won) as lnet
          from p group by situation),
  m as (select situation, (wn + ln) as n, (wnet + lnet) / (wn + ln) as mu,
               sqrt(greatest((wn * power(wnet / wn, 2) + ln * power(lnet / ln, 2)) / (wn + ln)
                             - power((wnet + lnet) / (wn + ln), 2), 0::numeric)) as sd
          from s where wn > 0 and ln > 0 and wn + ln >= 100)
  select situation, n::bigint, round(mu, 2), round(sd, 1),
         round(mu / nullif(sd / sqrt(n), 0), 2)
    from m;
$$;


