--
-- TOC entry 7140 (class 1255 OID 30773878)
-- Name: fn_horse_tuner_recorded_horses(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_tuner_recorded_horses(p_run_date date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE ids uuid[];
BEGIN
  IF p_run_date IS NULL THEN
    RETURN jsonb_build_object('version',1,'status','unavailable','reason','invalid_date');
  END IF;
  SELECT coalesce(array_agg(q.horse_id ORDER BY q.horse_id),ARRAY[]::uuid[]) INTO ids
    FROM (SELECT r.horse_id FROM public.horse_tuner_write_receipts r
      WHERE r.run_date=p_run_date ORDER BY r.horse_id LIMIT 2049) q;
  IF cardinality(ids)>2048 THEN
    RETURN jsonb_build_object('version',1,'status','unavailable','reason','horse_budget_exceeded');
  END IF;
  RETURN jsonb_build_object('version',1,'status','snapshot',
    'runDate',to_char(p_run_date,'YYYY-MM-DD'),'horseIds',to_jsonb(ids));
END;
$$;


ALTER FUNCTION public.fn_horse_tuner_recorded_horses(p_run_date date) OWNER TO postgres;

--
-- TOC entry 7952 (class 1255 OID 219112638)
-- Name: fn_horse_use_throwable(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_horse_use_throwable(p_horse_id uuid, p_throwable_id text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_horse_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unknown User');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles p WHERE p.id = p_horse_id AND p.is_horse IS TRUE
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not A Horse');
  END IF;

  -- auth.uid() reads these for the rest of THIS transaction only.
  PERFORM set_config('request.jwt.claim.sub', p_horse_id::text, true);
  PERFORM set_config(
    'request.jwt.claims',
    jsonb_build_object('sub', p_horse_id::text, 'role', 'authenticated')::text,
    true
  );

  RETURN public.fn_use_throwable_v2(p_throwable_id, p_request_id);
END;
$$;


