-- TOC entry 4883 (class 1255 OID 31416608)
-- Name: fn_issue_club_weekly_accounting(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_issue_club_weekly_accounting(p_union_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_variable
DECLARE previous_scope text;result jsonb;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501';END IF;
 previous_scope:=current_setting('app.accounting_validated_scope',true);
 IF previous_scope IS DISTINCT FROM 'union:'||p_union_id::text||':'||p_from::text||':'||p_to::text THEN
  IF current_setting('app.union_accounting_validated_period',true) IS DISTINCT FROM p_union_id::text||':'||p_from::text||':'||p_to::text
  THEN RAISE EXCEPTION 'weekly_statement_requires_validated_cascade' USING ERRCODE='23514';END IF;
  PERFORM set_config('app.accounting_validated_scope','union:'||p_union_id::text||':'||p_from::text||':'||p_to::text,true);
 END IF;
 result:=public.fn_issue_scope_weekly_accounting('union',p_union_id,p_from,p_to);
 PERFORM set_config('app.accounting_validated_scope',COALESCE(previous_scope,''),true);
 RETURN result;
END $$;


ALTER FUNCTION public.fn_issue_club_weekly_accounting(p_union_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 6580 (class 1255 OID 34785679)
-- Name: fn_issue_scope_weekly_accounting(text, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_issue_scope_weekly_accounting(p_scope_kind text, p_scope_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_variable
DECLARE scope record;club uuid;period public.settlement_periods%ROWTYPE;report jsonb;invoice uuid;issued int:=0;period_count int;clubs uuid[];delivery jsonb;expected_users int;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501';END IF;
 IF p_from IS NULL OR p_to IS NULL OR NOT isfinite(p_from) OR NOT isfinite(p_to)
  OR p_from IS DISTINCT FROM public.fn_union_week_start(p_from) OR p_to IS DISTINCT FROM public.fn_union_week_start(p_from+interval '8 days') OR p_to>now()
 THEN RAISE EXCEPTION 'weekly_statement_requires_closed_week' USING ERRCODE='22023';END IF;
 IF current_setting('app.accounting_validated_scope',true) IS DISTINCT FROM p_scope_kind||':'||p_scope_id::text||':'||p_from::text||':'||p_to::text
 THEN RAISE EXCEPTION 'weekly_statement_requires_validated_scope' USING ERRCODE='23514';END IF;
 SELECT * INTO scope FROM public.fn_resolve_accounting_routing_scope(p_scope_kind,p_scope_id,p_from,p_to);
 SELECT COALESCE(array_agg(x.club_id ORDER BY x.club_id),ARRAY[]::uuid[]) INTO clubs FROM (
  SELECT c.club_id FROM public.fn_accounting_week_clubs(scope.union_id,scope.standalone_club_id,p_from,p_to)c
  UNION SELECT s.club_id FROM public.accounting_payable_earning_sources s WHERE s.earned_at>=p_from AND s.earned_at<p_to
   AND (s.coordinator_union_id=scope.union_id OR (scope.standalone_club_id=s.club_id AND s.coordinator_union_id IS NULL)) AND s.club_id IS NULL
  UNION SELECT sp.club_id FROM public.settlement_periods sp WHERE sp.start_at=p_from AND sp.end_at=p_to AND sp.club_id IS NOT NULL
   AND (sp.union_id=scope.union_id OR (sp.club_id=scope.standalone_club_id AND sp.union_id IS NULL))
 )x WHERE x.club_id IS DISTINCT FROM scope.union_id;
 FOREACH club IN ARRAY clubs LOOP
  SELECT count(*) INTO period_count FROM public.settlement_periods sp WHERE sp.club_id=club AND sp.union_id IS NOT DISTINCT FROM scope.union_id AND sp.start_at=p_from AND sp.end_at=p_to;
  IF period_count<>1 THEN RAISE EXCEPTION 'weekly_statement_period_missing_or_duplicated' USING ERRCODE='23514',DETAIL=jsonb_build_object('club_id',club,'period_count',period_count)::text;END IF;
  SELECT * INTO period FROM public.settlement_periods sp WHERE sp.club_id=club AND sp.union_id IS NOT DISTINCT FROM scope.union_id AND sp.start_at=p_from AND sp.end_at=p_to FOR UPDATE;
  PERFORM pg_advisory_xact_lock(hashtextextended('club_weekly_invoice:'||period.id::text,0));
  SELECT i.id INTO invoice FROM public.settlement_invoices i WHERE i.period_id=period.id AND i.club_id=club AND i.invoice_type='club_weekly_accounting';
  IF invoice IS NULL THEN
   report:=public.fn_club_weekly_accounting_summary(period.id);
   IF report->>'ready_to_issue' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'club_weekly_statement_requires_reconciliation' USING ERRCODE='23514',DETAIL=report::text;END IF;
   report:=report||jsonb_build_object('status','complete');
   INSERT INTO public.settlement_invoices(club_id,period_id,invoice_type,from_entity_type,from_entity_id,to_entity_type,to_entity_id,gross_amount,net_amount,deductions,breakdown,status,notes)
   VALUES(club,period.id,'club_weekly_accounting','club',club::text,'club',club::text,(report->>'total_rake_funding')::numeric,(report->>'retained_by_club')::numeric,
    (report->>'total_paid_by_club')::numeric,report,'generated','Consolidated Weekly Club Accounting. The Net Movement Is Not An Additional Bill Or Transfer.') RETURNING id INTO invoice;
   issued:=issued+1;
  END IF;
  delivery:=public.fn_deliver_accounting_invoice(invoice);
  SELECT count(*) INTO expected_users FROM public.fn_accounting_party_users('club',club);
  IF delivery->>'success' IS DISTINCT FROM 'true' /* HISTORY-ONLY INVOICE (20261016143729) */ OR expected_users=0 OR (SELECT si.message_sent IS NOT TRUE FROM public.settlement_invoices si WHERE si.id=invoice)
   OR ((SELECT si.invoice_type FROM public.settlement_invoices si WHERE si.id=invoice) IS NOT DISTINCT FROM 'cashier_cashout' AND EXISTS(
   SELECT 1 FROM public.fn_accounting_party_users('club',club)u WHERE NOT EXISTS(SELECT 1 FROM public.accounting_invoice_deliveries d
    JOIN public.social_messages m ON m.id=d.message_id JOIN public.notifications n ON n.id=d.notification_id
    WHERE d.invoice_id=invoice AND d.recipient_id=u.user_id AND m.media_metadata->>'invoice_id'=invoice::text AND n.user_id=u.user_id
     AND m.message_type='invoice' AND n.metadata->>'invoice_id'=invoice::text)))
  THEN RAISE EXCEPTION 'club_weekly_statement_delivery_incomplete' USING ERRCODE='23514';END IF;
 END LOOP;
 RETURN jsonb_build_object('success',true,'scope_kind',p_scope_kind,'scope_id',p_scope_id,'period_start',p_from,'period_end',p_to,'clubs',cardinality(clubs),'issued',issued);
END $$;


ALTER FUNCTION public.fn_issue_scope_weekly_accounting(p_scope_kind text, p_scope_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 8190 (class 1255 OID 167526536)
-- Name: fn_issue_tournament_entry_ticket(uuid, uuid, uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_issue_tournament_entry_ticket(p_club_id uuid, p_holder_id uuid, p_tournament_id uuid, p_note text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_expected_price numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_me uuid := auth.uid();
  v_key text := nullif(btrim(coalesce(p_idempotency_key,'')),'');
  v_note text := nullif(btrim(coalesce(p_note,'')),'');
  v_bind public.tournament_ticket_entry_targets%ROWTYPE;
  v_state jsonb;
  v_price numeric;
  v_name text;
  v_ticket_note text;
  v_result jsonb;
  v_ticket public.tournament_tickets%ROWTYPE;
  v_ticket_id uuid;
  v_balance numeric;
BEGIN
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','Not Authenticated');
  END IF;
  IF v_key IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','A Retry Key Is Required For Every Ticket');
  END IF;
  IF p_club_id IS NULL OR p_holder_id IS NULL OR p_holder_id = v_me THEN
    RETURN jsonb_build_object('success',false,'error','Choose Another Active Member');
  END IF;
  IF p_tournament_id IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','Choose A Tournament');
  END IF;

  -- The core's own lock order: club hierarchy, then the retry key.
  PERFORM pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||p_club_id::text,0));
  PERFORM pg_advisory_xact_lock(hashtextextended('ticket:'||v_key,0));

  -- A replay returns the original, whatever the tournament's price is now.
  SELECT * INTO v_bind FROM public.tournament_ticket_entry_targets b
   WHERE b.idempotency_key = v_key;
  IF v_bind.ticket_id IS NOT NULL THEN
    IF v_bind.club_id IS DISTINCT FROM p_club_id
       OR v_bind.issued_by IS DISTINCT FROM v_me
       OR v_bind.holder_id IS DISTINCT FROM p_holder_id
       OR v_bind.tournament_id IS DISTINCT FROM p_tournament_id THEN
      RETURN jsonb_build_object('success',false,'error','That Retry Key Belongs To A Different Ticket');
    END IF;
    SELECT (ct.metadata->>'issuer_balance_after')::numeric INTO v_balance
      FROM public.chip_transactions ct
     WHERE ct.metadata->>'idempotency_key' = v_key
       AND ct.transaction_type = 'tournament_ticket_issue'
     LIMIT 1;
    RETURN jsonb_build_object('success',true,'replayed',true,
      'ticket_id',v_bind.ticket_id,'your_balance',v_balance,
      'tournament_id',v_bind.tournament_id,
      'tournament_name',(SELECT t.name FROM public.tournaments t WHERE t.id=v_bind.tournament_id),
      'price',v_bind.value,'entry_prize',v_bind.entry_prize,
      'entry_bounty',v_bind.entry_bounty,'entry_fee',v_bind.entry_fee);
  END IF;
  IF EXISTS (SELECT 1 FROM public.chip_transactions ct
              WHERE ct.metadata->>'idempotency_key' = v_key) THEN
    RETURN jsonb_build_object('success',false,'error','That Retry Key Is Already In Use');
  END IF;

  -- One unused ticket per player per tournament, decided under one lock so
  -- two cashiers cannot both send it.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'cashier-entry-ticket:'||p_tournament_id::text||':'||p_holder_id::text,0));

  /* Hold the tournament row still between reading its state and writing the
     binding, so a target that closes concurrently either closes first (and
     this door refuses) or closes after this commits (and its own closing
     transaction pays this ticket). A share lock for a few milliseconds. */
  PERFORM 1 FROM public.tournaments t WHERE t.id = p_tournament_id FOR SHARE;
  v_state := public.fn_ca_cashier_ticket_target_state(p_tournament_id);
  IF NOT COALESCE((v_state->>'ok')::boolean,false) THEN
    RETURN jsonb_build_object('success',false,'error',
      CASE v_state->>'reason'
        WHEN 'tournament_not_found' THEN 'Tournament Not Found'
        WHEN 'registration_closed' THEN 'Registration For That Tournament Is Closed'
        WHEN 'tournament_full' THEN 'That Tournament Is Full'
        WHEN 'seat_first_variant' THEN 'That Format Is Entered By Taking A Seat, Not By Ticket'
        WHEN 'free_tournament' THEN 'That Tournament Is Free To Enter'
        WHEN 'diamond_tournament' THEN 'Diamond Tournaments Do Not Take Chip Tickets'
        ELSE 'That Tournament Cannot Take A Ticket' END,
      'reason',v_state->>'reason');
  END IF;
  v_price := (v_state->>'price')::numeric;
  v_name := v_state->>'name';
  IF p_expected_price IS NOT NULL AND p_expected_price IS DISTINCT FROM v_price THEN
    RETURN jsonb_build_object('success',false,
      'error','The Ticket Price Changed, Review It And Send Again',
      'reason','price_changed','price',v_price);
  END IF;
  IF NOT public.fn_ca_cashier_ticket_target_in_club(p_tournament_id, p_club_id)
     OR public.fn_tournament_club_for_user(p_holder_id, p_tournament_id, p_club_id)
          IS DISTINCT FROM p_club_id THEN
    RETURN jsonb_build_object('success',false,
      'error','That Tournament Is Not Open To This Club','reason','not_visible_to_club');
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_players tp
              WHERE tp.tournament_id = p_tournament_id AND tp.user_id = p_holder_id) THEN
    RETURN jsonb_build_object('success',false,
      'error','That Player Is Already Registered For That Tournament','reason','already_registered');
  END IF;
  IF EXISTS (SELECT 1 FROM public.tournament_ticket_entry_targets b
               JOIN public.tournament_tickets tk ON tk.id = b.ticket_id
              WHERE b.tournament_id = p_tournament_id AND b.holder_id = p_holder_id
                AND tk.status = 'issued') THEN
    RETURN jsonb_build_object('success',false,
      'error','That Player Already Holds A Ticket For That Tournament','reason','already_holds_ticket');
  END IF;

  v_ticket_note := left('Entry Ticket: ' || COALESCE(NULLIF(btrim(v_name),''),'Tournament')
                        || COALESCE(' (' || v_note || ')',''), 300);

  -- The existing door: same authority and downline checks, same journal, same
  -- escrow, same receipt. It refuses with success=false and moves nothing.
  v_result := public.fn_issue_tournament_ticket_phase2_core_20260831(
    p_club_id, p_holder_id, v_price, v_ticket_note, v_key);
  IF NOT COALESCE((v_result->>'success')::boolean,false) THEN
    RETURN v_result;
  END IF;
  IF COALESCE((v_result->>'replayed')::boolean,false) THEN
    RAISE EXCEPTION 'cashier entry ticket key % replayed without a binding', v_key
      USING ERRCODE = 'P0404';
  END IF;
  v_ticket_id := (v_result->>'ticket_id')::uuid;
  SELECT * INTO v_ticket FROM public.tournament_tickets tk WHERE tk.id = v_ticket_id;
  IF v_ticket.id IS NULL OR v_ticket.status IS DISTINCT FROM 'issued'
     OR v_ticket.redemption_mode IS DISTINCT FROM 'wallet_chips'
     OR v_ticket.club_id IS DISTINCT FROM p_club_id
     OR v_ticket.issued_by IS DISTINCT FROM v_me
     OR v_ticket.holder_id IS DISTINCT FROM p_holder_id
     OR v_ticket.value IS DISTINCT FROM v_price THEN
    RAISE EXCEPTION 'cashier entry ticket % was not escrowed exactly', v_ticket_id
      USING ERRCODE = 'P0404';
  END IF;

  INSERT INTO public.tournament_ticket_entry_targets(
    ticket_id, tournament_id, club_id, issued_by, holder_id, value,
    entry_prize, entry_bounty, entry_fee, idempotency_key)
  VALUES (
    v_ticket_id, p_tournament_id, p_club_id, v_me, p_holder_id, v_price,
    (v_state->>'entry_prize')::numeric, (v_state->>'entry_bounty')::numeric,
    (v_state->>'entry_fee')::numeric, v_key);

  RETURN v_result || jsonb_build_object(
    'tournament_id',p_tournament_id,'tournament_name',v_name,
    'start_time',v_state->'start_time','price',v_price,
    'entry_prize',(v_state->>'entry_prize')::numeric,
    'entry_bounty',(v_state->>'entry_bounty')::numeric,
    'entry_fee',(v_state->>'entry_fee')::numeric);
END;
$$;


ALTER FUNCTION public.fn_issue_tournament_entry_ticket(p_club_id uuid, p_holder_id uuid, p_tournament_id uuid, p_note text, p_idempotency_key text, p_expected_price numeric) OWNER TO postgres;

