--
-- TOC entry 4470 (class 1255 OID 4652067)
-- Name: fn_kyc_start_inquiry(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_kyc_start_inquiry(p_user_id uuid, p_provider text DEFAULT 'stub'::text, p_jurisdiction_country text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inquiry_id TEXT;
  v_existing_status TEXT;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id is required';
  END IF;

  IF p_provider NOT IN ('persona','veriff','jumio','onfido','stub') THEN
    RAISE EXCEPTION 'Unknown KYC provider: %', p_provider;
  END IF;

  SELECT kyc_status INTO v_existing_status FROM public.profiles WHERE id = p_user_id;
  IF v_existing_status = 'APPROVED' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'already_approved',
      'kyc_status', v_existing_status
    );
  END IF;

  -- Generate inquiry ID (stub: prefix with provider name + timestamp)
  v_inquiry_id := p_provider || '_' || to_char(now(), 'YYYYMMDDHH24MISSMS') || '_' ||
                  substr(md5(p_user_id::text || now()::text), 1, 12);

  UPDATE public.profiles
     SET kyc_status           = 'PENDING',
         kyc_provider         = p_provider,
         kyc_inquiry_id       = v_inquiry_id,
         jurisdiction_country = COALESCE(p_jurisdiction_country, jurisdiction_country, country),
         kyc_rejection_reason = NULL,
         kyc_completed_at     = NULL
   WHERE id = p_user_id;

  INSERT INTO public.kyc_events (user_id, event_type, provider, inquiry_id,
                                 previous_status, new_status, source, payload)
  VALUES (p_user_id, 'inquiry_created', p_provider, v_inquiry_id,
          COALESCE(v_existing_status, 'NONE'), 'PENDING', 'user_action',
          jsonb_build_object('stub', p_provider = 'stub'));

  RETURN jsonb_build_object(
    'ok', true,
    'inquiry_id', v_inquiry_id,
    'provider', p_provider,
    'kyc_status', 'PENDING',
    -- Stub: in production, this URL is returned by the provider's API
    'inquiry_url', 'https://stub.kyc.local/inquiry/' || v_inquiry_id,
    'is_stub', p_provider = 'stub'
  );
END;
$$;


ALTER FUNCTION public.fn_kyc_start_inquiry(p_user_id uuid, p_provider text, p_jurisdiction_country text) OWNER TO postgres;

--
-- TOC entry 8555 (class 1255 OID 15856781)
-- Name: fn_launch_table_from_template(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_launch_table_from_template(p_template_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid  uuid := auth.uid();
  v_club uuid;
  v_new  uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'fn_launch_table_from_template requires an authenticated caller'
      USING ERRCODE = '28000';
  END IF;

  SELECT t.club_id INTO v_club FROM public.tables t
   WHERE t.id = p_template_id AND COALESCE(t.is_template, false) = true LIMIT 1;
  IF v_club IS NULL AND NOT EXISTS (
    SELECT 1 FROM public.tables t
     WHERE t.id = p_template_id AND COALESCE(t.is_template, false) = true) THEN
    RAISE EXCEPTION 'TEMPLATE_NOT_FOUND: % is not a table template', p_template_id;
  END IF;

  IF NOT (
    EXISTS (SELECT 1 FROM public.club_members cm
             WHERE cm.club_id = v_club AND cm.user_id = v_uid
               AND cm.role IN ('owner', 'co_owner', 'admin', 'manager', 'agent'))
    OR EXISTS (SELECT 1 FROM public.clubs c
                WHERE c.id = v_club AND c.owner_id = v_uid)
  ) THEN
    RAISE EXCEPTION 'NOT_CLUB_STAFF: only club staff may launch a table';
  END IF;

  v_new := public.fn_clone_table_row(p_template_id, NULL);
  UPDATE public.tables SET status = 'active', created_by = v_uid WHERE id = v_new;
  RETURN v_new;
END;
$$;


ALTER FUNCTION public.fn_launch_table_from_template(p_template_id uuid) OWNER TO postgres;

--
-- TOC entry 5904 (class 1255 OID 132618474)
-- Name: fn_leaderboard_complete_round_basis(uuid, text, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_leaderboard_complete_round_basis(p_club_id uuid, p_period text, p_start date, p_end date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_cutoff date;
  v_open public.leaderboard_complete_captures%ROWTYPE;
  v_close public.leaderboard_complete_captures%ROWTYPE;
  v_count bigint;
  v_hash text;
  v_rows jsonb;
  v_capture public.leaderboard_complete_captures%ROWTYPE;
BEGIN
  IF p_club_id IS NULL OR p_start IS NULL OR p_end IS NULL
     OR p_period NOT IN ('weekly', 'monthly') OR p_period IS NULL
     OR p_end > (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')::date
     OR (p_period = 'weekly' AND
         (extract(dow FROM p_start) <> 0 OR p_end <> p_start + 7))
     OR (p_period = 'monthly' AND
         (extract(day FROM p_start) <> 1 OR p_end <> (p_start + interval '1 month')::date)) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'LEADERBOARD_BASIS_WINDOW_INVALID';
  END IF;
  SELECT CASE p_period WHEN 'weekly' THEN weekly_v2_from ELSE monthly_v2_from END
    INTO v_cutoff FROM public.leaderboard_basis_rollout WHERE singleton;
  IF v_cutoff IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'LEADERBOARD_BASIS_ROLLOUT_MISSING';
  END IF;
  IF p_start < v_cutoff AND EXISTS (
    SELECT 1 FROM public.leaderboard_basis_existing_clubs WHERE club_id = p_club_id
  ) THEN
    -- Caller must run/freeze legacy semantics, not claim these inputs complete.
    RETURN jsonb_build_object('basis_version', 'legacy_v1', 'complete', false);
  END IF;

  SELECT * INTO v_open FROM public.leaderboard_complete_captures WHERE capture_date = p_start;
  SELECT * INTO v_close FROM public.leaderboard_complete_captures WHERE capture_date = p_end;
  IF v_open.capture_date IS NULL OR v_close.capture_date IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'LEADERBOARD_CAPTURE_UNAVAILABLE';
  END IF;
  -- Exact dates, never max(date)<=boundary. Validate the complete global domain:
  -- any club with zero rows is genuinely empty within the applied-stats capture.
  FOR v_capture IN SELECT * FROM public.leaderboard_complete_captures
    WHERE capture_date IN (p_start, p_end)
  LOOP
    SELECT count(*), md5(COALESCE(string_agg(
      (to_jsonb(c) - 'snapshot_date')::text, E'\n' ORDER BY c.club_id, c.user_id), ''))
    INTO v_count, v_hash FROM public.leaderboard_capture_counters c
    WHERE c.snapshot_date = v_capture.capture_date;
    IF NOT v_capture.complete OR v_count <> v_capture.row_count
       OR v_hash <> v_capture.counter_hash
       OR (v_capture.captured_at AT TIME ZONE 'UTC')::date <> v_capture.capture_date THEN
      RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'LEADERBOARD_CAPTURE_INVALID';
    END IF;
  END LOOP;

  -- Same closing roster and delta arithmetic as authoritative ranking. Individual
  -- absence in a proven complete opening capture is legitimate zero, not failure.
  -- Return raw deltas; no invented score/tie/qualification or previous-rank rule.
  SELECT COALESCE(jsonb_agg(to_jsonb(d) ORDER BY d.user_id), '[]'::jsonb) INTO v_rows
  FROM (
    SELECT closing.user_id,
      GREATEST(closing.hands_dealt - COALESCE(opening.hands_dealt, 0), 0)::numeric AS hands_played,
      closing.total_winnings - COALESCE(opening.total_winnings, 0) AS total_winnings,
      closing.total_losses - COALESCE(opening.total_losses, 0) AS total_losses,
      GREATEST(closing.tournaments_won - COALESCE(opening.tournaments_won, 0), 0)::numeric AS tournaments_won,
      GREATEST(closing.total_rake - COALESCE(opening.total_rake, 0), 0) AS total_rake,
      GREATEST(closing.sum_big_blind - COALESCE(opening.sum_big_blind, 0), 0) AS sum_big_blind
    FROM public.leaderboard_capture_counters closing
    LEFT JOIN public.leaderboard_capture_counters opening
      ON opening.snapshot_date = p_start AND opening.club_id = closing.club_id
      AND opening.user_id = closing.user_id
    WHERE closing.snapshot_date = p_end AND closing.club_id = p_club_id
  ) d;
  RETURN jsonb_build_object('basis_version', 'complete_capture_v2', 'complete', true,
    'source_contract', 'applied_player_stats_v1', 'club_id', p_club_id,
    'opening_date', p_start, 'closing_date', p_end,
    'opening_captured_at', v_open.captured_at, 'closing_captured_at', v_close.captured_at,
    'opening_hash', v_open.counter_hash, 'closing_hash', v_close.counter_hash,
    'rows', v_rows);
END;
$$;


ALTER FUNCTION public.fn_leaderboard_complete_round_basis(p_club_id uuid, p_period text, p_start date, p_end date) OWNER TO postgres;

--
-- TOC entry 8035 (class 1255 OID 21934823)
-- Name: fn_leaderboard_funding_summary(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_leaderboard_funding_summary(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_union_id uuid;
  v_owner_type text;
  v_balance numeric := 0;
  v_total numeric := 0;
  v_current numeric := 0;
  v_other numeric := 0;
  v_committed_clubs integer := 0;
  v_current_exists boolean := false;
  v_current_enabled boolean := false;
BEGIN
  v_union_id := public.fn_leaderboard_funding_union_id(p_club_id);
  v_owner_type := CASE WHEN v_union_id IS NULL THEN 'club' ELSE 'union' END;

  IF v_owner_type = 'union' THEN
    SELECT COALESCE(wallet.promo_wallet, 0)
      INTO v_balance
      FROM public.union_wallets wallet
     WHERE wallet.union_id = v_union_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Leaderboard Funding Union Has No Promo Wallet'
        USING ERRCODE = '55000';
    END IF;
  ELSE
    SELECT COALESCE(club.promo_balance, 0)
      INTO v_balance
      FROM public.clubs club
     WHERE club.id = p_club_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Club Not Found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  WITH latest AS MATERIALIZED (
    SELECT DISTINCT ON (program.club_id)
      program.club_id,
      program.rewards_enabled,
      program.weekly_prizes,
      program.monthly_prizes,
      program.funding_owner_type,
      program.funding_union_id
    FROM public.leaderboard_reward_program_versions program
    ORDER BY program.club_id, program.version DESC
  ), scoped AS (
    SELECT
      latest.club_id,
      latest.rewards_enabled,
      public.fn_leaderboard_program_commitment(
        latest.rewards_enabled,
        latest.weekly_prizes,
        latest.monthly_prizes
      ) AS commitment
    FROM latest
    WHERE (
      v_owner_type = 'union'
      AND latest.funding_owner_type = 'union'
      AND latest.funding_union_id = v_union_id
    ) OR (
      v_owner_type = 'club'
      AND latest.funding_owner_type = 'club'
      AND latest.club_id = p_club_id
    )
  )
  SELECT
    COALESCE(sum(scoped.commitment), 0),
    COALESCE(sum(scoped.commitment) FILTER (WHERE scoped.club_id = p_club_id), 0),
    count(*) FILTER (WHERE scoped.rewards_enabled),
    COALESCE(bool_or(scoped.club_id = p_club_id), false),
    COALESCE(bool_or(scoped.club_id = p_club_id AND scoped.rewards_enabled), false)
  INTO v_total, v_current, v_committed_clubs, v_current_exists, v_current_enabled
  FROM scoped;

  v_other := GREATEST(v_total - v_current, 0);
  RETURN jsonb_build_object(
    'funding_owner_type', v_owner_type,
    'funding_union_id', v_union_id,
    'wallet_balance', round(v_balance, 2),
    'committed_balance', round(v_total, 2),
    'current_program_commitment', round(v_current, 2),
    'other_program_commitments', round(v_other, 2),
    'publication_capacity', round(GREATEST(v_balance - v_other, 0), 2),
    'available_uncommitted_balance', round(GREATEST(v_balance - v_total, 0), 2),
    'committed_club_count', v_committed_clubs,
    'funding_status', CASE
      WHEN NOT v_current_exists THEN 'not_published'
      WHEN NOT v_current_enabled THEN 'disabled'
      WHEN v_balance >= v_total THEN 'funded'
      ELSE 'underfunded'
    END
  );
END;
$$;


ALTER FUNCTION public.fn_leaderboard_funding_summary(p_club_id uuid) OWNER TO postgres;

