-- TOC entry 8212 (class 1255 OID 21022472)
-- Name: fn_ledger_fires(date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ledger_fires(p_day date, p_key text) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(sum(t.fires), 0)::bigint
    from horse_brain_telemetry t
   where t.day = p_day
     and case when right(p_key, 1) = '*'
              then t.feature like replace(left(p_key, length(p_key) - 1), '_', '\_') || '%'
              else t.feature = p_key end;
$$;


