COMMENT ON FUNCTION public.fn_lightning_alert_sweep(p_now timestamp with time zone) IS 'Lightning Phase 12 (20261009144343): the Lightning operator alerting pass, every minute from cron job lightning-alert-sweep-1m (never inside fn_cash_clusters_tick_all). Over the Lightning estate it pages, through fn_raise_server_financial_alert source lightning_alerts with stable dedupe keys, a frozen Cluster with no open freeze alert, a conversion stuck past the reaper, drive errors, reaper failures, an integrity spike and a latency regression; it resolves its own state pages when a re-measure finds them gone; it runs fn_lightning_integrity_scan hourly for Clusters with integrity_telemetry; it prunes latency windows older than 30 days. Every check is isolated and reported in the answer; it never raises and never writes a Cluster''s state. service_role only.';


--
-- TOC entry 7877 (class 1255 OID 57591113)
-- Name: fn_lightning_anchor_is_live_eligible(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_anchor_is_live_eligible(p_seat_id uuid, p_cluster_id uuid, p_player_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM public.table_seats ts
      JOIN public.tables tb ON tb.id = ts.table_id
     WHERE ts.id = p_seat_id
       AND tb.cluster_id = p_cluster_id AND coalesce(tb.is_deleted, false) = false
       AND coalesce(tb.lifecycle, '') <> 'closed'
       AND ts.left_at IS NULL
       AND ts.user_id IS NOT NULL
       AND (p_player_id IS NULL OR ts.user_id = p_player_id)
       AND coalesce(ts.is_sitting_out, false) = false
       AND coalesce(ts.leave_pending, false) = false
       AND coalesce(ts.stack, 0) > 0);
$$;


