--
-- TOC entry 3701 (class 1255 OID 57591149)
-- Name: fn_lightning_blind_ledger_debt_since(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_blind_ledger_debt_since() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF coalesce(NEW.missed_bb_debt, 0) > 0 OR coalesce(NEW.missed_sb_debt, 0) > 0
     OR coalesce(NEW.bb_owed, 0) > 0 OR coalesce(NEW.sb_owed, 0) > 0 THEN
    IF TG_OP = 'UPDATE' AND OLD.debt_since IS NOT NULL THEN
      NEW.debt_since := OLD.debt_since;
    ELSE
      NEW.debt_since := coalesce(NEW.debt_since, clock_timestamp());
    END IF;
  ELSE
    NEW.debt_since := NULL;
  END IF;
  RETURN NEW;
END
$$;


