COMMENT ON FUNCTION public.fn_lightning_form_hand(p_cluster_id uuid, p_players uuid[], p_target_size smallint, p_max_size smallint, p_bb_player uuid, p_reservation_ttl interval, p_form_window interval, p_now timestamp with time zone, p_matcher_version text, p_request_id uuid, p_player_platforms jsonb) IS 'THE HAND FORMATION BARRIER, specification 503-517, steps 1 to 10 and the binding that makes step 13 legal, re-cut by 20260926023047. Takes a candidate set in the matcher''s order and the matcher''s own version, reaps its Cluster, locks the candidates'' slots FOR UPDATE and their pool sessions FOR SHARE before reading a stack, and either returns a fully formed hand - instance opened and bound, seats reserved, positions and blind roles assigned along the whole five-term P2 key, stack_before snapshotted, an immutable hand_id stamped with rules_version, matcher_version, blind_algorithm_version, lightning_version and rake_version, and the participant set latched - or returns formed:false having written nothing but a matcher_retry. Refusals of data and contention (lock_not_available, deadlock_detected, serialization_failure) are retries; query_canceled and any money moving during formation are not, and propagate. Steps 11 and 12, the shuffle and the deal, are the engine''s.';


--
-- TOC entry 8814 (class 1255 OID 170567981)
-- Name: fn_lightning_formation_sizes(integer, integer, integer, integer, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_formation_sizes(p_legal integer, p_min integer, p_target integer, p_max integer, p_oldest_idle timestamp with time zone, p_now timestamp with time zone) RETURNS integer[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_max integer := LEAST(GREATEST(coalesce(nullif(p_max,0),2),2),9);
  v_min integer := LEAST(GREATEST(coalesce(nullif(p_min,0),2),2),v_max);
  v_target integer := LEAST(GREATEST(coalesce(nullif(p_target,0),v_max),v_min),v_max);
BEGIN
  IF p_now - p_oldest_idle >= interval '3 seconds' THEN
    RETURN public.fn_lightning_group_sizes(p_legal,v_min,v_target,v_max);
  END IF;
  RETURN ARRAY(SELECT v_target FROM generate_series(1,GREATEST(coalesce(p_legal,0),0)/v_target));
END $$;


