--
-- TOC entry 6511 (class 1255 OID 57693178)
-- Name: fn_lightning_group_sizes(integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_group_sizes(p_legal integer, p_min integer, p_target integer, p_max integer) RETURNS integer[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_max    integer := LEAST(GREATEST(coalesce(p_max, 2), 2), 9);
  v_min    integer;
  v_target integer;
  v_n      integer := GREATEST(coalesce(p_legal, 0), 0);
  v_lo     integer;
  v_hi     integer;
  v_k      integer;
  v_best   numeric;
  v_d      numeric;
  v_seat   integer;
  v_q      integer;
  v_r      integer;
  k        integer;
  v_out    integer[] := ARRAY[]::integer[];
BEGIN
  v_min    := LEAST(GREATEST(coalesce(p_min, 2), 2), v_max);
  v_target := LEAST(GREATEST(coalesce(p_target, v_max), v_min), v_max);
  -- Fewer legal players than the smallest hand: no hand, never a lone seat.
  IF v_n < v_min THEN
    RETURN v_out;
  END IF;
  v_lo := ceil(v_n::numeric / v_max)::integer;   -- fewest groups that fit everyone under max
  v_hi := floor(v_n::numeric / v_min)::integer;  -- most groups that keep everyone at min or more
  IF v_lo <= v_hi THEN
    -- Everyone is seated. Among the feasible group counts, the one whose
    -- average size is closest to the target; a tie keeps the fewer groups
    -- (P6: no unnecessary instance).
    v_k := v_lo;
    v_best := abs(v_n::numeric / v_lo - v_target);
    FOR k IN v_lo + 1 .. v_hi LOOP
      v_d := abs(v_n::numeric / k - v_target);
      IF v_d < v_best THEN
        v_best := v_d;
        v_k := k;
      END IF;
    END LOOP;
    v_seat := v_n;
  ELSE
    -- No split seats everyone (a configured minimum above two can cause it):
    -- the most players that can be seated, in full groups.
    v_k := v_hi;
    v_seat := v_hi * v_max;
  END IF;
  v_q := v_seat / v_k;
  v_r := v_seat % v_k;
  FOR k IN 1 .. v_k LOOP
    v_out := v_out || (v_q + CASE WHEN k <= v_r THEN 1 ELSE 0 END);
  END LOOP;
  RETURN v_out;
END
$$;


ALTER FUNCTION public.fn_lightning_group_sizes(p_legal integer, p_min integer, p_target integer, p_max integer) OWNER TO postgres;

--
-- TOC entry 47856 (class 0 OID 0)
-- Dependencies: 6511
-- Name: FUNCTION fn_lightning_group_sizes(p_legal integer, p_min integer, p_target integer, p_max integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_lightning_group_sizes(p_legal integer, p_min integer, p_target integer, p_max integer) IS 'Matcher P1. Group sizes for a legal count: the fewest instances that seat everyone inside [min, max], choosing among feasible counts the average closest to the target, sizes within one of each other, larger first. Empty below the minimum; never a one-player group. When no split seats everyone, the most that can be seated, in full groups.';


--
-- TOC entry 3982 (class 1255 OID 56835307)
-- Name: fn_lightning_hand_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_hand_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'LIGHTNING_HAND_IS_NOT_DELETABLE: hand % was formed at % and is a fact; a hand that can be deleted is a participant set that can be substituted by deleting and re-forming it',
      OLD.hand_id, OLD.formed_at USING ERRCODE = 'check_violation';
  END IF;

  -- THE LATCH IS NOT A THING A HAND CAN BE BORN WITH (2026-09-26). This
  -- trigger used to fire on UPDATE and DELETE only, so "the latch may only be
  -- set over a set that is really there" was a rule about UPDATE: a hand
  -- INSERTed already locked at player_count 6 over no participant rows was
  -- accepted, could never be given a participant, and could be dealt. The
  -- latch goes on in barrier step 10's UPDATE, over rows that exist, or not at
  -- all. The versions are NOT NULL and CHECKed by the table, so they need
  -- nothing here on the way in.
  IF TG_OP = 'INSERT' THEN
    IF NEW.participants_locked_at IS NOT NULL OR NEW.player_count IS NOT NULL THEN
      RAISE EXCEPTION 'LIGHTNING_HAND_IS_BORN_UNLOCKED: hand % was inserted already carrying the latch (participants_locked_at %, player_count %), which is barrier step 10 performed before the participants it counts exist; a hand born locked can never be given the set it claims',
        NEW.hand_id, NEW.participants_locked_at, NEW.player_count USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.hand_id IS DISTINCT FROM OLD.hand_id
     OR NEW.cluster_id IS DISTINCT FROM OLD.cluster_id
     OR NEW.cluster_epoch IS DISTINCT FROM OLD.cluster_epoch
     OR NEW.lightning_instance_id IS DISTINCT FROM OLD.lightning_instance_id
     OR NEW.formed_at IS DISTINCT FROM OLD.formed_at THEN
    RAISE EXCEPTION 'LIGHTNING_HAND_IS_IMMUTABLE: hand % may not have its identity, Cluster, epoch, instance or formation time rewritten',
      OLD.hand_id USING ERRCODE = 'check_violation';
  END IF;

  -- THE VERSIONS THE HAND WAS FORMED UNDER ARE PART OF WHAT IT IS
  -- (2026-09-26). Specification 2137-2143; stamped at step 7 in the INSERT
  -- that creates the hand, so they are frozen from birth rather than from the
  -- latch - there is no moment at which rewriting one is formation.
  IF NEW.rules_version IS DISTINCT FROM OLD.rules_version
     OR NEW.matcher_version IS DISTINCT FROM OLD.matcher_version
     OR NEW.blind_algorithm_version IS DISTINCT FROM OLD.blind_algorithm_version
     OR NEW.lightning_version IS DISTINCT FROM OLD.lightning_version
     OR NEW.rake_version IS DISTINCT FROM OLD.rake_version
     -- and the request it was formed for (2026-09-26)
     OR NEW.request_id IS DISTINCT FROM OLD.request_id THEN
    RAISE EXCEPTION 'LIGHTNING_HAND_IS_IMMUTABLE: hand % was formed under rules %, matcher %, blind algorithm %, lightning % and rake %, and the versions it was formed under may not be rewritten',
      OLD.hand_id, OLD.rules_version, OLD.matcher_version, OLD.blind_algorithm_version,
      OLD.lightning_version, OLD.rake_version USING ERRCODE = 'check_violation';
  END IF;

  -- LIGHTNING PHASE 6 (20261001154813): THE NUMBER A HAND IS RECORDED UNDER
  -- AND THE RECEIPT IT SETTLED WITH ARE WRITTEN ONCE. A re-bound number is a
  -- second physical hand wearing this one's identity; a rewritten receipt is
  -- a settlement that can be answered two ways.
  IF OLD.hand_number IS NOT NULL
     AND ROW(NEW.hand_number, NEW.host_table_id) IS DISTINCT FROM ROW(OLD.hand_number, OLD.host_table_id) THEN
    RAISE EXCEPTION 'LIGHTNING_HAND_NUMBER_IS_WRITE_ONCE: hand % was bound to hand number % at host table % and may not be re-bound to % at %',
      OLD.hand_id, OLD.hand_number, OLD.host_table_id, NEW.hand_number, NEW.host_table_id USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.settled_at IS NOT NULL
     AND ROW(NEW.settled_at, NEW.settle_request_id, NEW.settle_request_hash, NEW.hand_history_id, NEW.settle_receipt)
         IS DISTINCT FROM ROW(OLD.settled_at, OLD.settle_request_id, OLD.settle_request_hash, OLD.hand_history_id, OLD.settle_receipt) THEN
    RAISE EXCEPTION 'LIGHTNING_HAND_IS_SETTLED: hand % settled at % as hand history % and its receipt may not be rewritten',
      OLD.hand_id, OLD.settled_at, OLD.hand_history_id USING ERRCODE = 'check_violation';
  END IF;

  -- THE LATCH IS ONE-WAY. Clearing it would unlock every rule in
  -- fn_lightning_hand_player_is_immutable in a single UPDATE, which is the one
  -- bypass that would make all four of them decorative.
  IF OLD.participants_locked_at IS NOT NULL
     AND NEW.participants_locked_at IS DISTINCT FROM OLD.participants_locked_at THEN
    RAISE EXCEPTION 'LIGHTNING_HAND_IS_IMMUTABLE: hand % locked its participant set at % and the latch may not be cleared or moved',
      OLD.hand_id, OLD.participants_locked_at USING ERRCODE = 'check_violation';
  END IF;

  IF OLD.participants_locked_at IS NOT NULL
     AND NEW.player_count IS DISTINCT FROM OLD.player_count THEN
    RAISE EXCEPTION 'LIGHTNING_HAND_IS_IMMUTABLE: hand % locked % participants and that count may not be rewritten',
      OLD.hand_id, OLD.player_count USING ERRCODE = 'check_violation';
  END IF;

  -- THE LATCH MAY ONLY BE SET OVER A SET THAT IS REALLY THERE. Without this a
  -- caller could lock a hand at a player_count that does not match the rows,
  -- and every later reader would believe a set of two was a set of six.
  IF OLD.participants_locked_at IS NULL AND NEW.participants_locked_at IS NOT NULL THEN
    IF NEW.player_count IS DISTINCT FROM
       (SELECT count(*)::smallint FROM public.lightning_hand_player hp WHERE hp.hand_id = NEW.hand_id) THEN
      RAISE EXCEPTION 'LIGHTNING_HAND_IS_IMMUTABLE: hand % was locked at player_count % over % participant row(s)',
        NEW.hand_id, NEW.player_count,
        (SELECT count(*) FROM public.lightning_hand_player hp WHERE hp.hand_id = NEW.hand_id)
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_lightning_hand_is_immutable() OWNER TO postgres;

--
-- TOC entry 5524 (class 1255 OID 56835306)
-- Name: fn_lightning_hand_player_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_hand_player_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_hand   uuid;
  v_locked timestamp with time zone;
BEGIN
  -- OLD is unassigned in a BEFORE INSERT trigger and reading it raises, so the
  -- hand is taken from the right record before anything else happens.
  IF TG_OP = 'DELETE' THEN v_hand := OLD.hand_id; ELSE v_hand := NEW.hand_id; END IF;

  -- THE HAND A ROW LEAVES IS ASKED TOO (2026-09-26). Judged by NEW alone, an
  -- UPDATE moving a participant OUT of a locked hand into an unlocked one was
  -- an edit to an unlocked hand, and passed. A row whose OLD hand is latched
  -- keeps its hand_id, whatever hand it is being moved to.
  IF TG_OP = 'UPDATE' AND NEW.hand_id IS DISTINCT FROM OLD.hand_id
     AND EXISTS (SELECT 1 FROM public.lightning_hand oh
                  WHERE oh.hand_id = OLD.hand_id AND oh.participants_locked_at IS NOT NULL) THEN
    RAISE EXCEPTION 'LIGHTNING_HAND_PLAYER_IS_IMMUTABLE: player % of locked hand % may not be moved to hand %; the participant set of a locked hand is fixed',
      OLD.player_id, OLD.hand_id, NEW.hand_id USING ERRCODE = 'check_violation';
  END IF;

  SELECT h.participants_locked_at INTO v_locked
    FROM public.lightning_hand h WHERE h.hand_id = v_hand;

  -- An unlocked hand is a hand the barrier is still assembling. Everything
  -- below is about what happens AFTER the barrier, which is exactly what the
  -- latch records.
  IF v_locked IS NULL THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    RAISE EXCEPTION 'LIGHTNING_NO_ADDITIONAL_PLAYER_INSERTION: hand % locked its participant set at %, and player % arrived for seat % afterwards',
      v_hand, v_locked, NEW.player_id, NEW.seat USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'LIGHTNING_NO_PARTICIPANT_SUBSTITUTION: hand % locked its participant set at %, and removing player % from seat % would substitute the set the hand was formed with',
      v_hand, v_locked, OLD.player_id, OLD.seat USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.player_id IS DISTINCT FROM OLD.player_id
     OR NEW.pool_slot_id IS DISTINCT FROM OLD.pool_slot_id THEN
    RAISE EXCEPTION 'LIGHTNING_NO_PARTICIPANT_SUBSTITUTION: hand % seat % was formed for player % in slot % and may not become player % in slot %',
      v_hand, OLD.seat, OLD.player_id, OLD.pool_slot_id, NEW.player_id, NEW.pool_slot_id
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.seat IS DISTINCT FROM OLD.seat THEN
    RAISE EXCEPTION 'LIGHTNING_NO_SILENT_SEAT_SWAP: hand % seated player % at seat % and may not move them to seat %',
      v_hand, OLD.player_id, OLD.seat, NEW.seat USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.position IS DISTINCT FROM OLD.position
     OR NEW.blind_role IS DISTINCT FROM OLD.blind_role THEN
    RAISE EXCEPTION 'LIGHTNING_NO_BLIND_REASSIGNMENT: hand % gave player % position %/blind role % at formation and may not reassign them to %/%',
      v_hand, OLD.player_id, OLD.position, OLD.blind_role, NEW.position, NEW.blind_role
      USING ERRCODE = 'check_violation';
  END IF;

  -- stack_before is the snapshot the blinds are posted against, and hand_id,
  -- cluster_id and cluster_epoch are the bindings barrier steps 7, 8 and 9
  -- made. Rewriting any of them after the fact is a different hand wearing
  -- this one's primary key.
  IF NEW.hand_id IS DISTINCT FROM OLD.hand_id
     OR NEW.cluster_id IS DISTINCT FROM OLD.cluster_id
     OR NEW.cluster_epoch IS DISTINCT FROM OLD.cluster_epoch
     OR NEW.stack_before IS DISTINCT FROM OLD.stack_before THEN
    RAISE EXCEPTION 'LIGHTNING_HAND_PLAYER_IS_IMMUTABLE: hand % player % may not have its hand, Cluster, epoch or stack_before rewritten after the formation barrier',
      v_hand, OLD.player_id USING ERRCODE = 'check_violation';
  END IF;

  -- LIGHTNING PHASE 6 (20261001154813): A FOLD IS FINAL, AND A SETTLED
  -- PARTICIPANT IS A RECEIPT. The fold and the chips committed at it decide
  -- what the next hand may deal the player, so they are written once; once
  -- the hand is settled its outcome columns are its record.
  IF OLD.folded_at IS NOT NULL
     AND ROW(NEW.fold_type, NEW.folded_at, NEW.committed_at_fold)
         IS DISTINCT FROM ROW(OLD.fold_type, OLD.folded_at, OLD.committed_at_fold) THEN
    RAISE EXCEPTION 'LIGHTNING_FOLD_IS_FINAL: player % folded (%) out of hand % at % and the fold may not be rewritten',
      OLD.player_id, OLD.fold_type, v_hand, OLD.folded_at USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM public.lightning_hand sh WHERE sh.hand_id = v_hand AND sh.settled_at IS NOT NULL)
     AND ROW(NEW.stack_after, NEW.net_result, NEW.fold_type, NEW.folded_at, NEW.committed_at_fold)
         IS DISTINCT FROM ROW(OLD.stack_after, OLD.net_result, OLD.fold_type, OLD.folded_at, OLD.committed_at_fold) THEN
    RAISE EXCEPTION 'LIGHTNING_HAND_PLAYER_IS_SETTLED: hand % is settled and player %''s outcome may not be rewritten',
      v_hand, OLD.player_id USING ERRCODE = 'check_violation';
  END IF;

  -- Everything not named above stays writable, and the two that matter are
  -- fold_type and stack_after: they are the hand being PLAYED, which is the
  -- reason it was formed. A barrier that froze them would freeze the game.
  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_lightning_hand_player_is_immutable() OWNER TO postgres;

--
-- TOC entry 9529 (class 1255 OID 123484638)
-- Name: fn_lightning_hand_player_records_its_wait(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_hand_player_records_its_wait() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_formed timestamptz;
  v_idle   timestamptz;
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- THE WAIT IS THE FORMATION'S TO STATE, never a caller's: from the moment
    -- the slot went idle (its last dealt hand released it, or it opened) to
    -- the moment this hand formed. The barrier inserts the hand row first.
    SELECT h.formed_at INTO v_formed FROM public.lightning_hand h WHERE h.hand_id = NEW.hand_id;
    SELECT sl.idle_since INTO v_idle FROM public.lightning_pool_slot sl WHERE sl.id = NEW.pool_slot_id;
    NEW.waited_ms := CASE WHEN v_formed IS NULL OR v_idle IS NULL THEN NULL
                          ELSE LEAST(GREATEST(round(extract(epoch FROM (v_formed - v_idle)) * 1000), 0),
                                     2147483647)::integer END;
    -- The showdown is the settlement's to state.
    NEW.showed := NULL;
    RETURN NEW;
  END IF;
  IF NEW.waited_ms IS DISTINCT FROM OLD.waited_ms THEN
    RAISE EXCEPTION 'LIGHTNING_WAIT_IS_FINAL: hand % player % waited % ms at formation and the wait may not be rewritten',
      OLD.hand_id, OLD.player_id, OLD.waited_ms USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.showed IS NOT NULL AND NEW.showed IS DISTINCT FROM OLD.showed THEN
    RAISE EXCEPTION 'LIGHTNING_SHOWDOWN_IS_FINAL: hand % player % showed % at settlement and it may not be rewritten',
      OLD.hand_id, OLD.player_id, OLD.showed USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_lightning_hand_player_records_its_wait() OWNER TO postgres;

--
-- TOC entry 47860 (class 0 OID 0)
-- Dependencies: 9529
-- Name: FUNCTION fn_lightning_hand_player_records_its_wait(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_lightning_hand_player_records_its_wait() IS 'Lightning Phase 8. Sets lightning_hand_player.waited_ms at formation from the slot''s idle_since to the hand''s formed_at; the wait, and a settled showdown, are final.';


--
-- TOC entry 5886 (class 1255 OID 125520344)
-- Name: fn_lightning_hand_replay_check(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_hand_replay_check(p_hand_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  h          record;
  li         record;
  v_defects  jsonb := '[]'::jsonb;
  v_n        integer;
  v_sum      numeric;
  v_rake     numeric;
  v_bbj      numeric;
  v_formed_e timestamp with time zone;
  v_settle_e timestamp with time zone;
  v_bad      jsonb;
BEGIN
  SELECT * INTO h FROM public.lightning_hand WHERE hand_id = p_hand_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'hand_id', p_hand_id,
      'defects', jsonb_build_array(jsonb_build_object('code', 'hand_not_found')));
  END IF;
  SELECT * INTO li FROM public.lightning_instance WHERE id = h.lightning_instance_id;

  -- A LIVE HAND IS NOT AUDITABLE YET: nothing is repaired and nothing is
  -- guessed; the caller comes back when it is terminal.
  IF h.settled_at IS NULL AND (li.state IS DISTINCT FROM 'abandoned') THEN
    RETURN jsonb_build_object('ok', false, 'hand_id', p_hand_id, 'settled', false,
      'defects', jsonb_build_array(jsonb_build_object('code', 'hand_not_terminal',
        'instance_state', li.state)));
  END IF;

  -- THE PARTICIPANT SET matches the locked count.
  SELECT count(*) INTO v_n FROM public.lightning_hand_player hp WHERE hp.hand_id = p_hand_id;
  IF v_n IS DISTINCT FROM h.player_count THEN
    v_defects := v_defects || jsonb_build_object('code', 'participant_count',
      'locked', h.player_count, 'found', v_n);
  END IF;

  -- THE SIX VERSIONS are present (spec VERSIONING).
  SELECT jsonb_agg(jsonb_build_object('code', 'version_missing', 'field', f.name))
    INTO v_bad
    FROM (VALUES ('rules_version', h.rules_version), ('matcher_version', h.matcher_version),
                 ('blind_algorithm_version', h.blind_algorithm_version),
                 ('lightning_version', h.lightning_version), ('rake_version', h.rake_version)) f(name, v)
   WHERE coalesce(btrim(f.v), '') = '';
  v_defects := v_defects || coalesce(v_bad, '[]'::jsonb);
  IF h.cluster_epoch IS NULL OR h.cluster_epoch < 0 THEN
    v_defects := v_defects || jsonb_build_object('code', 'version_missing', 'field', 'cluster_epoch');
  END IF;

  IF h.settled_at IS NOT NULL THEN
    -- STACK ARITHMETIC, per player: stack_before + net = stack_after.
    SELECT jsonb_agg(jsonb_build_object('code', 'stack_arithmetic', 'player_id', hp.player_id,
             'stack_before', hp.stack_before, 'net', hp.net_result, 'stack_after', hp.stack_after)
             ORDER BY hp.player_id)
      INTO v_bad
      FROM public.lightning_hand_player hp
     WHERE hp.hand_id = p_hand_id
       AND (hp.stack_after IS NULL OR hp.stack_before IS NULL
            OR round(hp.stack_before + hp.net_result, 2) IS DISTINCT FROM round(hp.stack_after, 2));
    v_defects := v_defects || coalesce(v_bad, '[]'::jsonb);

    -- CONSERVATION: the deltas sum to exactly minus the recorded rake and
    -- BBJ. Chips neither appear nor vanish unexplained.
    v_rake := coalesce((h.settle_receipt ->> 'rake')::numeric, 0);
    v_bbj  := coalesce((h.settle_receipt ->> 'bbj')::numeric, 0);
    SELECT round(coalesce(sum(hp.net_result), 0), 2) INTO v_sum
      FROM public.lightning_hand_player hp WHERE hp.hand_id = p_hand_id;
    IF v_sum + v_rake + v_bbj <> 0 THEN
      v_defects := v_defects || jsonb_build_object('code', 'conservation',
        'net_sum', v_sum, 'rake', v_rake, 'bbj', v_bbj);
    END IF;

    -- THE RECEIPT AGREES with the participant rows it was cut from.
    SELECT jsonb_agg(jsonb_build_object('code', 'receipt_disagrees', 'player_id', hp.player_id,
             'receipt_delta', h.settle_receipt -> 'deltas' -> hp.player_id::text,
             'net', hp.net_result) ORDER BY hp.player_id)
      INTO v_bad
      FROM public.lightning_hand_player hp
     WHERE hp.hand_id = p_hand_id
       AND (h.settle_receipt -> 'deltas' -> hp.player_id::text) IS DISTINCT FROM
           to_jsonb(round(hp.net_result, 2));
    v_defects := v_defects || coalesce(v_bad, '[]'::jsonb);
  END IF;

  -- THE EVENTS EXIST, IN ORDER: hand_created <= dealing <= hand_settled (or
  -- the instance_destroyed of an abandonment), in the timestamps and in the
  -- ledger.
  SELECT min(e.at) INTO v_formed_e FROM public.cash_cluster_events e
   WHERE e.game_id = h.cluster_id AND e.kind = 'hand_created'
     AND e.payload ->> 'hand_id' = p_hand_id::text;
  IF v_formed_e IS NULL THEN
    v_defects := v_defects || jsonb_build_object('code', 'event_missing', 'kind', 'hand_created');
  END IF;
  IF h.settled_at IS NOT NULL THEN
    SELECT min(e.at) INTO v_settle_e FROM public.cash_cluster_events e
     WHERE e.game_id = h.cluster_id AND e.kind = 'hand_settled'
       AND e.payload ->> 'hand_id' = p_hand_id::text;
    IF v_settle_e IS NULL THEN
      v_defects := v_defects || jsonb_build_object('code', 'event_missing', 'kind', 'hand_settled');
    END IF;
    IF h.formed_at > coalesce(li.started_at, h.formed_at)
       OR coalesce(li.started_at, h.formed_at) > h.settled_at
       OR coalesce(v_formed_e, h.formed_at) > coalesce(v_settle_e, h.settled_at) THEN
      v_defects := v_defects || jsonb_build_object('code', 'event_order',
        'formed_at', h.formed_at, 'dealing_at', li.started_at, 'settled_at', h.settled_at,
        'formed_event_at', v_formed_e, 'settled_event_at', v_settle_e);
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.cash_cluster_events e
                    WHERE e.game_id = h.cluster_id AND e.kind = 'instance_destroyed'
                      AND e.payload ->> 'instance_id' = h.lightning_instance_id::text) THEN
      v_defects := v_defects || jsonb_build_object('code', 'event_missing', 'kind', 'instance_destroyed');
    END IF;
    IF h.formed_at > coalesce(li.completed_at, h.formed_at) THEN
      v_defects := v_defects || jsonb_build_object('code', 'event_order',
        'formed_at', h.formed_at, 'abandoned_at', li.completed_at);
    END IF;
  END IF;

  RETURN jsonb_build_object('ok', v_defects = '[]'::jsonb, 'hand_id', p_hand_id,
    'cluster_id', h.cluster_id, 'cluster_epoch', h.cluster_epoch,
    'settled', h.settled_at IS NOT NULL, 'defects', v_defects);
END
$$;


ALTER FUNCTION public.fn_lightning_hand_replay_check(p_hand_id uuid) OWNER TO postgres;

--
-- TOC entry 47862 (class 0 OID 0)
-- Dependencies: 5886
-- Name: FUNCTION fn_lightning_hand_replay_check(p_hand_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_lightning_hand_replay_check(p_hand_id uuid) IS 'Lightning Phase 9 (spec Phase 15 / REPLAY ENGINE). The deterministic audit of one terminal hand from persisted state alone: participant count equals the locked count, stack_before + net = stack_after per player, the deltas conserve against the receipt''s rake and BBJ, the receipt agrees with the rows, the six versions are present, and the hand_created, dealing and hand_settled (or instance_destroyed) records exist in order. Returns {ok, defects}, one named defect per violated clause (hand_not_found, hand_not_terminal, participant_count, version_missing, stack_arithmetic, conservation, receipt_disagrees, event_missing, event_order). Read-only, never a repair; service_role only.';


--
-- TOC entry 5911 (class 1255 OID 178119207)
-- Name: fn_lightning_hand_template_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_hand_template_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_rules jsonb; v_template text; v_handedness integer;
BEGIN
 SELECT template_name,ruleset_snapshot,handedness INTO v_template,v_rules,v_handedness FROM public.cash_games WHERE id=NEW.cluster_id FOR SHARE;
 IF NOT public.fn_lightning_template_allowed(v_template,v_rules) THEN
  RAISE EXCEPTION 'LIGHTNING_TEMPLATE_NOT_ALLOWED: only Action and Madness may form Lightning hands'
   USING ERRCODE='23514',CONSTRAINT='lightning_hand_template_allowed';
 END IF;
 IF NOT public.fn_lightning_table_size_allowed(v_handedness) THEN
  RAISE EXCEPTION 'LIGHTNING_TABLE_SIZE_NOT_ALLOWED: only six-seat games may form Lightning hands'
   USING ERRCODE='23514',CONSTRAINT='lightning_hand_table_size_allowed';
 END IF;
 RETURN NEW;
END $$;


