--
-- TOC entry 3387 (class 1255 OID 56835330)
-- Name: fn_lightning_instance_abandon(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_instance_abandon(p_instance_id uuid, p_reason text, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  i        record;
  v_reason text := coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'abandoned_without_a_stated_reason');
BEGIN
  -- NOT gated on the freeze: see fn_lightning_reap_formations.
  SELECT li.id, li.state, li.started_at, li.hand_id
    INTO i FROM public.lightning_instance li WHERE li.id = p_instance_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'abandoned', false, 'reason', 'not_found');
  END IF;
  IF i.state IN ('complete', 'abandoned') THEN
    RETURN jsonb_build_object('ok', true, 'abandoned', false, 'reason', 'already_terminal',
                              'state', i.state);
  END IF;

  UPDATE public.lightning_instance li
     SET state = 'abandoned',
         abandon_reason = v_reason,
         -- lightning_instance_lifecycle_order forbids completed_at without
         -- started_at, so an instance abandoned before it ever dealt keeps a
         -- NULL completed_at. That is the schema's rule and not a choice made
         -- here; abandon_reason is what records that it ended.
         completed_at = CASE WHEN li.started_at IS NOT NULL THEN p_now ELSE li.completed_at END
   WHERE li.id = i.id;

  RETURN jsonb_build_object('ok', true, 'abandoned', true, 'instance_id', i.id,
                            'was', i.state, 'hand_id', i.hand_id, 'reason', v_reason);
END
$$;


ALTER FUNCTION public.fn_lightning_instance_abandon(p_instance_id uuid, p_reason text, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 4469 (class 1255 OID 56835331)
-- Name: fn_lightning_instance_begin_dealing(uuid, interval, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_instance_begin_dealing(p_instance_id uuid, p_deal_window interval DEFAULT '00:10:00'::interval, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  i          record;
  g          record;
  v_cluster  uuid;
  v_why      text;
  v_gone     text;
  -- THE DEADLINE IS JUDGED BY THE DATABASE'S CLOCK (2026-09-26), never by the
  -- caller's: an old p_now would make an expired formation look alive.
  v_now      timestamptz := clock_timestamp();
  h          record;
  v_players  integer;
  v_committed integer;
  v_window   interval := GREATEST(coalesce(p_deal_window, interval '10 minutes'), interval '30 seconds');
BEGIN
  -- BARRIER STEP 13, AND ONLY ITS PRECONDITION. What is on the far side of
  -- this door is steps 11 and 12 - the shuffle, using the engine's
  -- authoritative RNG, and the deal - and neither of those is or should be in
  -- this database.
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'dealing', false, 'reason', 'platform_frozen');
  END IF;

  -- THE CLUSTER ROW FIRST, FOR SHARE (2026-09-26), in the order formation
  -- takes it, so that nothing can convert, freeze or disable the Cluster
  -- between the checks below and the release into gameplay.
  SELECT li.cluster_id INTO v_cluster FROM public.lightning_instance li WHERE li.id = p_instance_id;
  SELECT cg.id, cg.cluster_mode, cg.lightning_enabled, cg.cluster_epoch
    INTO g FROM public.cash_games cg WHERE cg.id = v_cluster FOR SHARE;

  SELECT li.id, li.state, li.hand_id, li.cluster_id, li.cluster_epoch, li.deadline_at, li.created_at
    INTO i FROM public.lightning_instance li WHERE li.id = p_instance_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'dealing', false, 'reason', 'not_found');
  END IF;
  IF i.state IS DISTINCT FROM 'reserved' THEN
    RETURN jsonb_build_object('ok', false, 'dealing', false, 'reason', 'wrong_state', 'state', i.state);
  END IF;
  IF i.deadline_at <= v_now THEN
    RETURN jsonb_build_object('ok', false, 'dealing', false, 'reason', 'past_deadline',
                              'deadline_at', i.deadline_at);
  END IF;

  SELECT lh.hand_id, lh.participants_locked_at, lh.player_count
    INTO h FROM public.lightning_hand lh WHERE lh.hand_id = i.hand_id;
  IF NOT FOUND OR h.participants_locked_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'dealing', false, 'reason', 'participant_set_is_not_locked');
  END IF;

  SELECT count(*)::integer INTO v_players
    FROM public.lightning_hand_player hp WHERE hp.hand_id = h.hand_id;
  SELECT count(*)::integer INTO v_committed
    FROM public.lightning_reservation r
   WHERE r.lightning_instance_id = i.id AND r.state = 'committed';

  IF v_players IS DISTINCT FROM h.player_count
     OR v_committed IS DISTINCT FROM h.player_count THEN
    RETURN jsonb_build_object('ok', false, 'dealing', false, 'reason', 'participant_set_does_not_agree',
                              'player_count', h.player_count, 'players', v_players,
                              'committed_reservations', v_committed);
  END IF;

  -- EVERY COMMITTED RESERVATION SITS IN THE SEAT THE HAND GAVE IT. Counting
  -- agreement is satisfied by two sets of the same size holding different
  -- people, which is the substitution the whole barrier exists to prevent.
  IF EXISTS (
    SELECT 1 FROM public.lightning_reservation r
     WHERE r.lightning_instance_id = i.id AND r.state = 'committed'
       AND NOT EXISTS (SELECT 1 FROM public.lightning_hand_player hp
                        WHERE hp.hand_id = h.hand_id AND hp.player_id = r.player_id
                          AND hp.seat = r.seat_number)) THEN
    RETURN jsonb_build_object('ok', false, 'dealing', false, 'reason', 'reservations_do_not_match_the_seats');
  END IF;

  -- THE WORLD OUTSIDE THE INSTANCE (2026-09-26). Everything above asks the
  -- instance about itself. A hand is released into gameplay only while its
  -- Cluster is still a Lightning pool at the epoch it was formed in, and while
  -- every participant is still in that pool: an open pool session, an open
  -- slot, an anchor seat that is live eligible, and an open cash session. If
  -- not, the formation is void and is abandoned HERE, so its players are
  -- handed back now rather than when the reaper finds it.
  v_why := CASE
    WHEN g.id IS NULL THEN 'cluster_not_found'
    WHEN g.cluster_mode IS DISTINCT FROM 'lightning' THEN 'cluster_is_not_lightning'
    WHEN coalesce(g.lightning_enabled, false) = false THEN 'lightning_disabled'
    WHEN g.cluster_epoch IS DISTINCT FROM i.cluster_epoch
      OR NOT EXISTS (SELECT 1 FROM public.cash_cluster_epoch e
                      WHERE e.cluster_id = i.cluster_id AND e.epoch = i.cluster_epoch
                        AND e.ended_at IS NULL) THEN 'epoch_is_not_current'
    ELSE NULL END;
  IF v_why IS NULL THEN
    SELECT string_agg(hp.player_id::text, ',' ORDER BY hp.seat) INTO v_gone
      FROM public.lightning_hand_player hp
      JOIN public.lightning_pool_slot sl ON sl.id = hp.pool_slot_id
      JOIN public.lightning_pool_session ps ON ps.id = sl.pool_session_id
     WHERE hp.hand_id = h.hand_id
       AND (sl.closed_at IS NOT NULL
            OR ps.exited_at IS NOT NULL
            OR NOT public.fn_lightning_anchor_is_live_eligible(ps.anchor_seat_id, i.cluster_id, ps.player_id)
            OR NOT EXISTS (SELECT 1 FROM public.cash_player_session cps
                            WHERE cps.id = ps.cash_player_session_id AND cps.closed_at IS NULL));
    IF v_gone IS NOT NULL THEN
      v_why := 'participant_left_the_pool';
    END IF;
  END IF;
  IF v_why IS NOT NULL THEN
    PERFORM public.fn_lightning_instance_abandon(
      i.id, 'begin_dealing refused: ' || v_why || coalesce(' [' || v_gone || ']', ''), v_now);
    RETURN jsonb_build_object('ok', false, 'dealing', false, 'abandoned', true, 'reason', v_why,
                              'instance_id', i.id, 'hand_id', h.hand_id, 'players', v_gone,
                              'cluster_mode', g.cluster_mode);
  END IF;

  UPDATE public.lightning_instance li
     SET state = 'dealing', started_at = GREATEST(v_now, i.created_at),
         deadline_at = GREATEST(v_now, i.created_at) + v_window
   WHERE li.id = i.id;

  INSERT INTO public.cash_cluster_events (game_id, kind, payload, cluster_epoch)
  VALUES (i.cluster_id, 'instance_started', jsonb_build_object(
    'cluster_id', i.cluster_id, 'cluster_epoch', i.cluster_epoch, 'instance_id', i.id,
    'hand_id', h.hand_id, 'players', v_players,
    'deadline_at', GREATEST(v_now, i.created_at) + v_window, 'at', v_now), i.cluster_epoch);

  RETURN jsonb_build_object('ok', true, 'dealing', true, 'instance_id', i.id,
                            'hand_id', h.hand_id, 'players', v_players,
                            'cluster_id', i.cluster_id, 'cluster_epoch', i.cluster_epoch,
                            'deadline_at', GREATEST(v_now, i.created_at) + v_window);
END
$$;


ALTER FUNCTION public.fn_lightning_instance_begin_dealing(p_instance_id uuid, p_deal_window interval, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 7366 (class 1255 OID 56835308)
-- Name: fn_lightning_instance_is_disciplined(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_instance_is_disciplined() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g record;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.state IS DISTINCT FROM 'forming' THEN
      RAISE EXCEPTION 'LIGHTNING_INSTANCE_IS_BORN_FORMING: instance for Cluster % was inserted in state % rather than forming, so the formation barrier it is supposed to pass through has already been skipped',
        NEW.cluster_id, NEW.state USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.hand_id IS NOT NULL THEN
      RAISE EXCEPTION 'LIGHTNING_INSTANCE_IS_BORN_EMPTY: instance for Cluster % was inserted already carrying hand %, which is barrier step 8 performed before steps 1 to 7',
        NEW.cluster_id, NEW.hand_id USING ERRCODE = 'check_violation';
    END IF;

    SELECT id, cluster_mode, lightning_enabled, cluster_epoch
      INTO g FROM public.cash_games WHERE id = NEW.cluster_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'LIGHTNING_INSTANCE_HAS_NO_CLUSTER: instance names Cluster % which does not exist',
        NEW.cluster_id USING ERRCODE = 'foreign_key_violation';
    END IF;

    -- coalesce on lightning_enabled because the column is a nullable-shaped
    -- added boolean in the general case and `NOT x` over NULL is NULL, which
    -- an IF takes as false and which would admit exactly the Cluster this
    -- refuses.
    IF g.cluster_mode IS DISTINCT FROM 'lightning'
       OR coalesce(g.lightning_enabled, false) = false THEN
      RAISE EXCEPTION 'LIGHTNING_INSTANCE_CLUSTER_IS_NOT_LIGHTNING: Cluster % is in cluster_mode % with lightning_enabled %, and a hand formed for it would be dealt at tables that are still dealing cash',
        NEW.cluster_id, g.cluster_mode, coalesce(g.lightning_enabled, false)
        USING ERRCODE = 'check_violation';
    END IF;

    -- BARRIER STEP 9. The foreign key into cash_cluster_epoch proves the epoch
    -- EXISTED. It does not prove it is the epoch the Cluster is in now, and a
    -- conversion, a revert or a re-conversion moves that number under a
    -- matcher that read it a moment ago.
    IF NEW.cluster_epoch IS DISTINCT FROM g.cluster_epoch THEN
      RAISE EXCEPTION 'LIGHTNING_INSTANCE_EPOCH_IS_NOT_CURRENT: instance for Cluster % bound epoch % while the Cluster is at epoch %',
        NEW.cluster_id, NEW.cluster_epoch, g.cluster_epoch USING ERRCODE = 'check_violation';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.cash_cluster_epoch e
                    WHERE e.cluster_id = NEW.cluster_id AND e.epoch = NEW.cluster_epoch
                      AND e.ended_at IS NULL) THEN
      RAISE EXCEPTION 'LIGHTNING_INSTANCE_EPOCH_IS_NOT_CURRENT: epoch % of Cluster % has ended, or was never opened, so nothing may be formed inside it',
        NEW.cluster_epoch, NEW.cluster_id USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
  END IF;

  IF NEW.cluster_id IS DISTINCT FROM OLD.cluster_id
     OR NEW.cluster_epoch IS DISTINCT FROM OLD.cluster_epoch
     OR NEW.target_size IS DISTINCT FROM OLD.target_size
     OR NEW.max_size IS DISTINCT FROM OLD.max_size
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'LIGHTNING_INSTANCE_IS_IMMUTABLE: instance % may not have its Cluster, epoch, target size, max size or creation time rewritten',
      OLD.id USING ERRCODE = 'check_violation';
  END IF;

  -- hand_id IS WRITE-ONCE. Re-pointing an instance at a second hand is
  -- participant substitution performed one level up, where none of the
  -- lightning_hand_player rules can see it.
  IF OLD.hand_id IS NOT NULL AND NEW.hand_id IS DISTINCT FROM OLD.hand_id THEN
    RAISE EXCEPTION 'LIGHTNING_NO_PARTICIPANT_SUBSTITUTION: instance % is bound to hand % and may not be re-pointed at %',
      OLD.id, OLD.hand_id, NEW.hand_id USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.state IS DISTINCT FROM OLD.state THEN
    IF NOT ((OLD.state = 'forming'  AND NEW.state IN ('reserved', 'abandoned'))
         OR (OLD.state = 'reserved' AND NEW.state IN ('dealing', 'abandoned'))
         OR (OLD.state = 'dealing'  AND NEW.state IN ('settling', 'abandoned'))
         OR (OLD.state = 'settling' AND NEW.state IN ('complete', 'abandoned'))) THEN
      RAISE EXCEPTION 'LIGHTNING_INSTANCE_STATE_IS_NOT_REVERSIBLE: instance % may not go from % to %',
        OLD.id, OLD.state, NEW.state USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.state IN ('reserved', 'dealing', 'settling', 'complete') AND NEW.hand_id IS NULL THEN
      RAISE EXCEPTION 'LIGHTNING_INSTANCE_HAS_NO_HAND: instance % reached % with no hand bound, so barrier step 8 never happened',
        OLD.id, NEW.state USING ERRCODE = 'check_violation';
    END IF;

    -- BARRIER STEP 13'S PRECONDITION, stated where nothing can route around
    -- it: a hand is released into gameplay only once its participant set is
    -- locked. The shuffle and the deal are the engine's and are not in this
    -- database at all.
    IF NEW.state = 'dealing'
       AND NOT EXISTS (SELECT 1 FROM public.lightning_hand h
                        WHERE h.hand_id = NEW.hand_id AND h.participants_locked_at IS NOT NULL) THEN
      RAISE EXCEPTION 'LIGHTNING_INSTANCE_HAS_AN_UNLOCKED_HAND: instance % tried to begin dealing hand % whose participant set is not locked',
        OLD.id, NEW.hand_id USING ERRCODE = 'check_violation';
    END IF;

    -- A LOCKED HAND IS NOT ENOUGH (2026-09-26). The branch above asks only
    -- whether the latch is set, and a latch is a claim: a hand born locked at
    -- player_count 6 over no rows passed it and was dealt empty. A hand is
    -- released into gameplay only when its count, its participant rows and its
    -- instance's committed reservations are the same number. begin_dealing
    -- checks this too, and this is where it is true of every other road.
    IF NEW.state = 'dealing'
       AND EXISTS (SELECT 1 FROM public.lightning_hand h
                    WHERE h.hand_id = NEW.hand_id
                      AND (h.player_count IS NULL
                           OR h.player_count IS DISTINCT FROM
                              (SELECT count(*)::smallint FROM public.lightning_hand_player hp WHERE hp.hand_id = h.hand_id)
                           OR h.player_count IS DISTINCT FROM
                              (SELECT count(*)::smallint FROM public.lightning_reservation r
                                WHERE r.lightning_instance_id = NEW.id AND r.state = 'committed'))) THEN
      RAISE EXCEPTION 'LIGHTNING_INSTANCE_HAND_SET_DOES_NOT_AGREE: instance % tried to begin dealing hand % locked at player_count % over % participant row(s) and % committed reservation(s)',
        OLD.id, NEW.hand_id,
        (SELECT h.player_count FROM public.lightning_hand h WHERE h.hand_id = NEW.hand_id),
        (SELECT count(*) FROM public.lightning_hand_player hp WHERE hp.hand_id = NEW.hand_id),
        (SELECT count(*) FROM public.lightning_reservation r
          WHERE r.lightning_instance_id = NEW.id AND r.state = 'committed')
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_lightning_instance_is_disciplined() OWNER TO postgres;

--
-- TOC entry 7580 (class 1255 OID 57106171)
-- Name: fn_lightning_instance_keepalive(uuid, interval, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_instance_keepalive(p_instance_id uuid, p_extend interval DEFAULT '00:02:00'::interval, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  i          record;
  -- Never from the future, for the same reason the reaper never reaps by a
  -- clock that has not arrived: a deadline is a statement about real time.
  v_now      timestamp with time zone := LEAST(coalesce(p_now, clock_timestamp()), clock_timestamp());
  -- A heartbeat, not a lease: at least thirty seconds so that a keepalive is
  -- worth sending, at most fifteen minutes so that one leaked call cannot keep
  -- a dead engine's players out of the pool for an evening.
  v_extend   interval := LEAST(GREATEST(coalesce(p_extend, interval '2 minutes'), interval '30 seconds'),
                               interval '15 minutes');
  v_deadline timestamp with time zone;
BEGIN
  -- NOT GATED ON THE FREEZE. A hand already in flight when a maintenance break
  -- begins is allowed to finish - "allow already-started hands to resolve
  -- normally" - and refusing its heartbeat would have the reaper abandon it
  -- under a live engine, which is the one thing this function exists to stop.
  -- A covered deadline needs no mutation or custody. This answer linearizes
  -- at this MVCC read, just as any heartbeat answer may become obsolete after
  -- its transaction. It cannot extend a deadline or revive a terminal hand.
  SELECT li.id, li.state, li.deadline_at, li.hand_id
    INTO i FROM public.lightning_instance li WHERE li.id = p_instance_id;
  IF FOUND AND i.state IN ('dealing', 'settling')
     AND i.deadline_at > v_now AND i.deadline_at >= v_now + v_extend THEN
    RETURN jsonb_build_object('ok', true, 'alive', true, 'instance_id', i.id, 'hand_id', i.hand_id,
                              'state', i.state, 'deadline_at', i.deadline_at);
  END IF;

  -- All other paths retain exclusive custody and re-read the authoritative row.
  SELECT li.id, li.state, li.deadline_at, li.hand_id
    INTO i FROM public.lightning_instance li WHERE li.id = p_instance_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'alive', false, 'reason', 'not_found');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.lightning_instance li
                  WHERE li.id = i.id AND li.state IN ('dealing', 'settling')) THEN
    RETURN jsonb_build_object('ok', false, 'alive', false, 'reason', 'wrong_state', 'state', i.state);
  END IF;

  -- A HAND DECLARED DEAD STAYS DEAD. Past its deadline the reaper is entitled
  -- to it and may already hold it, so a late heartbeat is told so rather than
  -- being allowed to race the reaper for a hand whose players are about to be
  -- handed back.
  IF i.deadline_at <= v_now THEN
    RETURN jsonb_build_object('ok', false, 'alive', false, 'reason', 'past_deadline',
                              'deadline_at', i.deadline_at);
  END IF;

  -- FORWARD ONLY. A short keepalive never shortens a longer window that
  -- begin_dealing or an earlier keepalive granted.
  v_deadline := GREATEST(i.deadline_at, v_now + v_extend);
  UPDATE public.lightning_instance li SET deadline_at = v_deadline WHERE li.id = i.id;

  RETURN jsonb_build_object('ok', true, 'alive', true, 'instance_id', i.id, 'hand_id', i.hand_id,
                            'state', i.state, 'deadline_at', v_deadline);
END
$$;


ALTER FUNCTION public.fn_lightning_instance_keepalive(p_instance_id uuid, p_extend interval, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 47870 (class 0 OID 0)
-- Dependencies: 7580
-- Name: FUNCTION fn_lightning_instance_keepalive(p_instance_id uuid, p_extend interval, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_lightning_instance_keepalive(p_instance_id uuid, p_extend interval, p_now timestamp with time zone) IS 'The engine''s heartbeat for a hand in flight. Moves deadline_at of a dealing or settling instance forward to at least now plus p_extend (30 seconds to 15 minutes), never backwards, and refuses an instance already past its deadline: a hand the reaper is entitled to is not brought back by a late caller. Without a keepalive a dealing hand is reaped when the deal window begin_dealing set runs out; with one it is reaped only when the engine stops vouching for it. Not gated on the freeze, because a hand already in flight when a break begins is allowed to finish.';


--
-- TOC entry 4851 (class 1255 OID 56835328)
-- Name: fn_lightning_instance_open(uuid, smallint, smallint, interval, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_instance_open(p_cluster_id uuid, p_target_size smallint DEFAULT NULL::smallint, p_max_size smallint DEFAULT NULL::smallint, p_form_window interval DEFAULT '00:00:45'::interval, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g        record;
  v_target smallint;
  v_max    smallint;
  v_id     uuid;
  v_window interval := GREATEST(coalesce(p_form_window, interval '45 seconds'), interval '5 seconds');
BEGIN
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'opened', false, 'reason', 'platform_frozen');
  END IF;

  SELECT id, cluster_mode, lightning_enabled, cluster_epoch, handedness
    INTO g FROM public.cash_games WHERE id = p_cluster_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'opened', false, 'reason', 'not_found');
  END IF;
  IF g.cluster_mode IS DISTINCT FROM 'lightning' OR coalesce(g.lightning_enabled, false) = false THEN
    RETURN jsonb_build_object('ok', false, 'opened', false, 'reason', 'cluster_is_not_lightning',
                              'cluster_mode', g.cluster_mode);
  END IF;

  -- DECISION 2, THE SELF-HEALING HALF. The corpse of the last formation that
  -- died is buried by the next one that starts, in this transaction, before
  -- anything new is created. A Cluster that keeps dealing keeps itself clean
  -- with nothing scheduled anywhere; the estate-wide sweep is the third line
  -- of defence rather than the first.
  PERFORM public.fn_lightning_reap_formations(p_now, 200, g.id);

  v_target := coalesce(p_target_size, GREATEST(2, LEAST(6, coalesce(g.handedness, 6)))::smallint);
  v_max    := coalesce(p_max_size, GREATEST(v_target, LEAST(9, coalesce(g.handedness, 6))::smallint));
  IF v_max < v_target THEN v_max := v_target; END IF;
  IF v_target < 2 THEN v_target := 2; END IF;
  IF v_max > 9 THEN v_max := 9; END IF;

  INSERT INTO public.lightning_instance
    (cluster_id, cluster_epoch, state, target_size, max_size, created_at, deadline_at)
  VALUES (g.id, g.cluster_epoch, 'forming', v_target, v_max, p_now, p_now + v_window)
  RETURNING id INTO v_id;

  -- SPECIFICATION EVENT instance_created (2026-09-26).
  INSERT INTO public.cash_cluster_events (game_id, kind, payload, cluster_epoch)
  VALUES (g.id, 'instance_created', jsonb_build_object(
    'cluster_id', g.id, 'cluster_epoch', g.cluster_epoch, 'instance_id', v_id,
    'target_size', v_target, 'max_size', v_max, 'via', 'fn_lightning_instance_open',
    'deadline_at', p_now + v_window, 'at', p_now), g.cluster_epoch);

  RETURN jsonb_build_object('ok', true, 'opened', true, 'instance_id', v_id,
                            'cluster_id', g.id, 'cluster_epoch', g.cluster_epoch,
                            'target_size', v_target, 'max_size', v_max,
                            'deadline_at', p_now + v_window);
END
$$;


ALTER FUNCTION public.fn_lightning_instance_open(p_cluster_id uuid, p_target_size smallint, p_max_size smallint, p_form_window interval, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 6771 (class 1255 OID 56835310)
-- Name: fn_lightning_instance_releases_its_reservations(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_instance_releases_its_reservations() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_players uuid[];
BEGIN
  -- WHY THIS IS A TRIGGER AND NOT A LINE IN fn_lightning_instance_abandon.
  -- lightning_reservation_one_active_per_player makes a committed reservation
  -- a standing bar on that player being matched again. The bar has to come off
  -- on EVERY road into a terminal state - abandon, the reaper, and the
  -- settlement phase that has not been written yet - and a road that forgets
  -- would take a player out of the pool permanently with no row saying why.
  WITH released AS (
    UPDATE public.lightning_reservation r
       SET state = 'released',
           resolved_at = clock_timestamp(),
           reason = coalesce(r.reason, 'instance_' || NEW.state)
     WHERE r.lightning_instance_id = NEW.id
       AND r.state IN ('pending', 'committed')
    RETURNING r.player_id)
  SELECT coalesce(array_agg(released.player_id ORDER BY released.player_id), ARRAY[]::uuid[])
    INTO v_players FROM released;

  -- SPECIFICATION EVENTS (2026-09-26): how the instance ended, and who it
  -- gave back, in one row each.
  INSERT INTO public.cash_cluster_events (game_id, kind, payload, cluster_epoch)
  VALUES (NEW.cluster_id,
          CASE WHEN NEW.state = 'complete' THEN 'instance_completed' ELSE 'instance_destroyed' END,
          jsonb_build_object(
            'cluster_id', NEW.cluster_id, 'cluster_epoch', NEW.cluster_epoch,
            'instance_id', NEW.id, 'hand_id', NEW.hand_id,
            'from_state', OLD.state, 'to_state', NEW.state, 'reason', NEW.abandon_reason,
            'hand_voided', NEW.state = 'abandoned' AND OLD.state IN ('dealing', 'settling'),
            'players', to_jsonb(v_players), 'at', clock_timestamp()),
          NEW.cluster_epoch);
  IF cardinality(v_players) > 0 THEN
    INSERT INTO public.cash_cluster_events (game_id, kind, payload, cluster_epoch)
    VALUES (NEW.cluster_id, 'pool_player_released', jsonb_build_object(
      'cluster_id', NEW.cluster_id, 'cluster_epoch', NEW.cluster_epoch,
      'instance_id', NEW.id, 'hand_id', NEW.hand_id, 'players', to_jsonb(v_players),
      'reason', coalesce(NEW.abandon_reason, 'instance_' || NEW.state), 'at', clock_timestamp()),
      NEW.cluster_epoch);
  END IF;
  -- LIGHTNING PHASE 7 REMEDIATION (20261007222717): A HAND THAT NEVER DEALT
  -- GIVES BACK ITS BLIND CREDIT. fn_lightning_form_hand counts bb, sb and the
  -- positions into lightning_blind_ledger at formation; a formation voided
  -- before begin_dealing ever ran posted nothing, and a credit it kept made
  -- fn_lightning_blind_order skip its player for a blind they never paid -
  -- "never double-charge, never lose a blind", broken in the second half.
  -- Reversed here, on the one door every abandon path crosses (the drain's
  -- void, the reaper, begin_dealing's own refusal, the unfreeze), exactly
  -- once - this trigger fires only on the transition into a terminal state -
  -- and floored at zero. Formation touches no debt field, so none needs
  -- restoring. An instance that started dealing keeps its counts: its blinds
  -- were posted at the felt. No is_horse here: a horse's credit reverses
  -- exactly as a human's (Law 10.5).
  IF NEW.state = 'abandoned' AND NEW.started_at IS NULL AND NEW.hand_id IS NOT NULL THEN
    UPDATE public.lightning_blind_ledger bl
       SET bb_count   = GREATEST(bl.bb_count  - d.bb,  0),
           sb_count   = GREATEST(bl.sb_count  - d.sb,  0),
           btn_count  = GREATEST(bl.btn_count - d.btn, 0),
           utg_count  = GREATEST(bl.utg_count - d.utg, 0),
           hj_count   = GREATEST(bl.hj_count  - d.hj,  0),
           co_count   = GREATEST(bl.co_count  - d.co,  0),
           updated_at = clock_timestamp()
      FROM (SELECT hp.player_id,
                   (coalesce(hp.blind_role, 'none') = 'bb')::integer AS bb,
                   (coalesce(hp.blind_role, 'none') = 'sb')::integer AS sb,
                   (coalesce(hp."position", '') = 'btn')::integer AS btn,
                   (coalesce(hp."position", '') = 'utg')::integer AS utg,
                   (coalesce(hp."position", '') = 'hj')::integer  AS hj,
                   (coalesce(hp."position", '') = 'co')::integer  AS co
              FROM public.lightning_hand_player hp
             WHERE hp.hand_id = NEW.hand_id) d
     WHERE bl.cluster_id = NEW.cluster_id AND bl.player_id = d.player_id;
  END IF;
  RETURN NULL;
END
$$;


ALTER FUNCTION public.fn_lightning_instance_releases_its_reservations() OWNER TO postgres;

--
-- TOC entry 4174 (class 1255 OID 130340256)
-- Name: fn_lightning_integrity_report(uuid, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_integrity_report(p_cluster_id uuid, p_signals jsonb, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  c_max_players   constant integer := 500;
  c_max_pairs     constant integer := 200;
  c_lat_min_dec   constant integer := 50;
  c_lat_max_cv    constant numeric := 0.15;
  c_lat_min_fast  constant numeric := 0.6;
  c_tc_min_hands  constant integer := 20;
  c_tc_min_seq    constant integer := 30;
  c_tc_min_corr   constant numeric := 0.7;
  c_tc_min_follow constant numeric := 0.5;
  c_tc_corr_lb_z  constant numeric := 2.326;
  v_now      timestamptz := LEAST(coalesce(p_now, clock_timestamp()), clock_timestamp());
  v_from     timestamptz;
  v_to       timestamptz;
  v_ctx      jsonb := '{}'::jsonb;
  v_list     text;
  v_arr      jsonb;
  v_n        integer;
  v_read     jsonb := '{}'::jsonb;
  v_trunc    jsonb := '{}'::jsonb;
  e          jsonb;
  i          integer;
  v_k        text;
  v_v        numeric;
  v_c        numeric;
  v_lo       numeric;
  v_hi       numeric;
  v_ok       boolean;
  v_num      jsonb;
  v_p        uuid;
  v_o        uuid;
  v_type     text;
  v_score    integer;
  v_follow   numeric;
  v_rejected jsonb := '[]'::jsonb;
  v_clamped  jsonb := '[]'::jsonb;
  v_flagged  jsonb := jsonb_build_object('DECISION_LATENCY', 0, 'TIMING_CORRELATION', 0);
  v_ins      integer := 0;
  v_upd      integer := 0;
  v_same     integer := 0;
  v_new      boolean;
  v_id       bigint;
  c_agg_hours  constant integer := 24;
  c_keep_hours constant integer := 48;
  v_stored   integer := 0;
  v_pruned   integer := 0;
  a          record;
  v_cur      record;
  v_ev       jsonb;
  v_cv       numeric;
  v_fs       numeric;
  v_corr     numeric;
  v_peak     integer;
  v_corr_lb  numeric;
BEGIN
  IF p_cluster_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.cash_games cg WHERE cg.id = p_cluster_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'CLUSTER_NOT_FOUND');
  END IF;
  IF p_signals IS NULL OR jsonb_typeof(p_signals) IS DISTINCT FROM 'object' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'INVALID_SIGNALS');
  END IF;
  IF octet_length(p_signals::text) > 1048576 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'SIGNALS_TOO_LARGE');
  END IF;
  -- NO HIDDEN INFORMATION: a card, hole, deck or seed key anywhere refuses
  -- the whole report rather than being trimmed.
  IF EXISTS (SELECT 1 FROM jsonb_path_query(p_signals, 'strict $.**') q(v)
              CROSS JOIN LATERAL (SELECT jsonb_object_keys(q.v) AS k WHERE jsonb_typeof(q.v) = 'object') kk
             WHERE kk.k ~* '(card|hole|deck|seed)') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'evidence_carries_cards');
  END IF;
  IF jsonb_typeof(p_signals -> 'window_from') IS DISTINCT FROM 'string'
     OR jsonb_typeof(p_signals -> 'window_to') IS DISTINCT FROM 'string'
     OR NOT pg_input_is_valid(p_signals ->> 'window_from', 'timestamptz')
     OR NOT pg_input_is_valid(p_signals ->> 'window_to', 'timestamptz') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'INVALID_WINDOW');
  END IF;
  v_from := (p_signals ->> 'window_from')::timestamptz;
  v_to := (p_signals ->> 'window_to')::timestamptz;
  IF NOT isfinite(v_from) OR NOT isfinite(v_to) OR v_from >= v_to
     OR v_to - v_from > interval '7 days' OR v_to > v_now + interval '5 minutes' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'INVALID_WINDOW');
  END IF;
  FOREACH v_k IN ARRAY ARRAY['hands', 'decisions', 'fast_ms', 'dropped_players', 'dropped_pairs'] LOOP
    IF jsonb_typeof(p_signals -> v_k) = 'number' AND (p_signals ->> v_k)::numeric >= 0 THEN
      v_ctx := v_ctx || jsonb_build_object('window_' || v_k, LEAST((p_signals ->> v_k)::numeric, 1000000000));
    END IF;
  END LOOP;

  -- ONE REPORT OR SCAN OF A CLUSTER AT A TIME (the scan takes the same
  -- lock), so the extend-or-insert below sees every earlier window.
  PERFORM pg_advisory_xact_lock(hashtext('lightning-integrity:' || p_cluster_id::text));
  FOREACH v_list IN ARRAY ARRAY['players', 'pairs'] LOOP
    v_arr := p_signals -> v_list;
    IF v_arr IS NULL OR jsonb_typeof(v_arr) = 'null' THEN
      v_arr := '[]'::jsonb;
    ELSIF jsonb_typeof(v_arr) <> 'array' THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'INVALID_SIGNALS', 'list', v_list);
    END IF;
    v_n := LEAST(jsonb_array_length(v_arr), CASE v_list WHEN 'players' THEN c_max_players ELSE c_max_pairs END);
    v_read := v_read || jsonb_build_object(v_list, v_n);
    v_trunc := v_trunc || jsonb_build_object(v_list, jsonb_array_length(v_arr) - v_n);

    FOR i IN 0 .. v_n - 1 LOOP
      e := v_arr -> i;
      IF jsonb_typeof(e) IS DISTINCT FROM 'object' THEN
        v_rejected := v_rejected || jsonb_build_object('list', v_list, 'index', i, 'reason', 'not_an_object');
        CONTINUE;
      END IF;
      -- THE SUBJECT.
      IF v_list = 'players' THEN
        v_ok := jsonb_typeof(e -> 'player_id') = 'string' AND pg_input_is_valid(e ->> 'player_id', 'uuid');
        v_p := CASE WHEN v_ok THEN (e ->> 'player_id')::uuid END;
        v_o := NULL;
      ELSE
        v_ok := jsonb_typeof(e -> 'player_a') = 'string' AND pg_input_is_valid(e ->> 'player_a', 'uuid')
            AND jsonb_typeof(e -> 'player_b') = 'string' AND pg_input_is_valid(e ->> 'player_b', 'uuid');
        IF v_ok THEN
          v_p := LEAST((e ->> 'player_a')::uuid, (e ->> 'player_b')::uuid);
          v_o := GREATEST((e ->> 'player_a')::uuid, (e ->> 'player_b')::uuid);
          v_ok := v_p <> v_o;
        END IF;
      END IF;
      IF NOT v_ok THEN
        v_rejected := v_rejected || jsonb_build_object('list', v_list, 'index', i, 'reason', 'invalid_player');
        CONTINUE;
      END IF;
      IF NOT EXISTS (SELECT 1 FROM public.lightning_pool_session ps WHERE ps.cluster_id = p_cluster_id AND ps.player_id = v_p)
         OR (v_o IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.lightning_pool_session ps
                                              WHERE ps.cluster_id = p_cluster_id AND ps.player_id = v_o)) THEN
        v_rejected := v_rejected || jsonb_build_object('list', v_list, 'index', i, 'reason', 'unknown_player');
        CONTINUE;
      END IF;
      -- THE NUMBERS: only the named members are read, each a number or null,
      -- clamped to its range.
      v_num := '{}'::jsonb;
      v_ok := true;
      FOREACH v_k IN ARRAY CASE v_list
          WHEN 'players' THEN ARRAY['decisions', 'timeouts', 'p50_ms', 'p95_ms', 'mean_ms', 'stddev_ms', 'cv', 'fast_share']
          ELSE ARRAY['hands_together', 'sequential_actions', 'fast_follows', 'latency_corr', 'corr_n', 'corr_sx', 'corr_sy', 'corr_sxx', 'corr_syy', 'corr_sxy'] END LOOP
        CONTINUE WHEN NOT (e ? v_k) OR jsonb_typeof(e -> v_k) = 'null';
        IF jsonb_typeof(e -> v_k) <> 'number' THEN
          v_rejected := v_rejected || jsonb_build_object('list', v_list, 'index', i, 'reason', 'not_a_number', 'key', v_k);
          v_ok := false;
          EXIT;
        END IF;
        v_v := (e ->> v_k)::numeric;
        v_lo := CASE v_k WHEN 'latency_corr' THEN -1 ELSE 0 END;
        v_hi := CASE v_k WHEN 'latency_corr' THEN 1 WHEN 'fast_share' THEN 1 WHEN 'cv' THEN 1000 ELSE 1000000000 END;
        v_c := LEAST(GREATEST(v_v, v_lo), v_hi);
        IF v_c <> v_v THEN
          v_clamped := v_clamped || jsonb_build_object('list', v_list, 'index', i, 'key', v_k, 'given', e -> v_k, 'used', v_c);
        END IF;
        v_num := v_num || jsonb_build_object(v_k, v_c);
      END LOOP;
      CONTINUE WHEN NOT v_ok;

      -- THE ENGINE'S EVIDENCE IS JUDGED OVER A DAY (2026-10-09, Phase 11
      -- remediation). At the engine's five-minute window a pair shares one
      -- or two hands, so no single window ever reached a threshold. Every
      -- subject's validated numbers are KEPT per window (idempotent per
      -- Cluster, subject and window; a resend with other numbers replaces
      -- them) and the decision below is taken over the rolling 24 hours.
      INSERT INTO public.lightning_integrity_engine_window AS w
        (cluster_id, window_from, window_to, player_a, player_b, numbers)
      VALUES (p_cluster_id, v_from, v_to, v_p, v_o, v_num)
      ON CONFLICT (cluster_id, player_a, player_b, window_from, window_to)
      DO UPDATE SET numbers = EXCLUDED.numbers, received_at = clock_timestamp()
       WHERE w.numbers IS DISTINCT FROM EXCLUDED.numbers;
      v_stored := v_stored + 1;
    END LOOP;
  END LOOP;

  -- THE DECISION: for every subject of this window, its evidence of the last
  -- 24 hours. Counts are summed; fast_share, p50 and p95 are weighted by
  -- decisions; cv is the pooled cv of the windows that sent mean_ms and
  -- stddev_ms (else the decision-weighted cv); latency_corr is weighted by
  -- sequential actions. The thresholds are the ones a single window used.
  FOR a IN
    WITH subj AS (
      SELECT DISTINCT ew.player_a, ew.player_b FROM public.lightning_integrity_engine_window ew
       WHERE ew.cluster_id = p_cluster_id AND ew.window_from = v_from AND ew.window_to = v_to
    ), ev AS (
      SELECT ew.player_a, ew.player_b, ew.window_from, ew.window_to,
             (ew.numbers ->> 'decisions')::numeric AS dn, (ew.numbers ->> 'timeouts')::numeric AS tmo,
             (ew.numbers ->> 'p50_ms')::numeric AS p50, (ew.numbers ->> 'p95_ms')::numeric AS p95,
             (ew.numbers ->> 'mean_ms')::numeric AS mn, (ew.numbers ->> 'stddev_ms')::numeric AS sd,
             (ew.numbers ->> 'cv')::numeric AS cv, (ew.numbers ->> 'fast_share')::numeric AS fast,
             (ew.numbers ->> 'hands_together')::numeric AS ht, (ew.numbers ->> 'sequential_actions')::numeric AS seq,
             (ew.numbers ->> 'fast_follows')::numeric AS ff, (ew.numbers ->> 'latency_corr')::numeric AS cr,
             CASE WHEN ew.numbers ?& ARRAY['corr_n','corr_sx','corr_sy','corr_sxx','corr_syy','corr_sxy']
                       AND (ew.numbers ->> 'corr_n')::numeric > 0
                  THEN (ew.numbers ->> 'corr_n')::numeric END AS cn,
             (ew.numbers ->> 'corr_sx')::numeric AS csx, (ew.numbers ->> 'corr_sy')::numeric AS csy,
             (ew.numbers ->> 'corr_sxx')::numeric AS csxx, (ew.numbers ->> 'corr_syy')::numeric AS csyy,
             (ew.numbers ->> 'corr_sxy')::numeric AS csxy
        FROM subj s
        JOIN public.lightning_integrity_engine_window ew
          ON ew.cluster_id = p_cluster_id AND ew.player_a = s.player_a AND ew.player_b IS NOT DISTINCT FROM s.player_b
       WHERE ew.window_to > v_to - make_interval(hours => c_agg_hours) AND ew.window_to <= v_to
    )
    SELECT ev.player_a, ev.player_b, count(*)::integer AS windows,
           min(ev.window_from) AS w_from, max(ev.window_to) AS w_to,
           sum(ev.dn) AS decisions, sum(ev.tmo) AS timeouts,
           sum(ev.dn * ev.fast) / nullif(sum(ev.dn) FILTER (WHERE ev.fast IS NOT NULL), 0) AS fast_w,
           avg(ev.fast) AS fast_u,
           sum(ev.dn * ev.mn) FILTER (WHERE ev.sd IS NOT NULL)
             / nullif(sum(ev.dn) FILTER (WHERE ev.mn IS NOT NULL AND ev.sd IS NOT NULL), 0) AS mean_p,
           sum(ev.dn * (ev.sd * ev.sd + ev.mn * ev.mn))
             / nullif(sum(ev.dn) FILTER (WHERE ev.mn IS NOT NULL AND ev.sd IS NOT NULL), 0) AS m2_p,
           sum(ev.dn * ev.cv) / nullif(sum(ev.dn) FILTER (WHERE ev.cv IS NOT NULL), 0) AS cv_w,
           avg(ev.cv) AS cv_u,
           sum(ev.dn * ev.p50) / nullif(sum(ev.dn) FILTER (WHERE ev.p50 IS NOT NULL), 0) AS p50,
           sum(ev.dn * ev.p95) / nullif(sum(ev.dn) FILTER (WHERE ev.p95 IS NOT NULL), 0) AS p95,
           sum(ev.ht) AS hands_together, sum(ev.seq) AS sequential_actions, sum(ev.ff) AS fast_follows,
           sum(ev.cn) AS corr_n,
           sum(ev.csx) FILTER (WHERE ev.cn IS NOT NULL) AS corr_sx,
           sum(ev.csy) FILTER (WHERE ev.cn IS NOT NULL) AS corr_sy,
           sum(ev.csxx) FILTER (WHERE ev.cn IS NOT NULL) AS corr_sxx,
           sum(ev.csyy) FILTER (WHERE ev.cn IS NOT NULL) AS corr_syy,
           sum(ev.csxy) FILTER (WHERE ev.cn IS NOT NULL) AS corr_sxy
      FROM ev
     GROUP BY ev.player_a, ev.player_b
     ORDER BY ev.player_a, ev.player_b
  LOOP
    v_type := NULL;
    v_score := NULL;
    v_follow := NULL;
    IF a.player_b IS NULL THEN
      v_cv := CASE WHEN a.mean_p > 0 THEN round(sqrt(GREATEST(a.m2_p - a.mean_p * a.mean_p, 0)) / a.mean_p, 4)
                   ELSE round(coalesce(a.cv_w, a.cv_u), 4) END;
      v_fs := round(coalesce(a.fast_w, a.fast_u), 4);
      v_num := jsonb_strip_nulls(jsonb_build_object(
                 'decisions', a.decisions, 'timeouts', a.timeouts,
                 'p50_ms', round(a.p50, 1), 'p95_ms', round(a.p95, 1), 'mean_ms', round(a.mean_p, 1),
                 'stddev_ms', CASE WHEN a.mean_p > 0 THEN round(sqrt(GREATEST(a.m2_p - a.mean_p * a.mean_p, 0)), 1) END,
                 'cv', v_cv, 'fast_share', v_fs));
      IF coalesce(a.decisions, 0) >= c_lat_min_dec AND (v_cv <= c_lat_max_cv OR v_fs >= c_lat_min_fast) THEN
        v_type := 'DECISION_LATENCY';
        v_score := LEAST(100, GREATEST(
          CASE WHEN v_cv <= c_lat_max_cv THEN round(50 + 40 * (c_lat_max_cv - v_cv) / c_lat_max_cv) END,
          CASE WHEN v_fs >= c_lat_min_fast THEN round(40 + 50 * v_fs) END))::integer;
      END IF;
    ELSE
      -- Only paired completed hands can satisfy the correlation sample floor.
      -- Seconds-based additive moments preserve within- and between-window
      -- covariance. Legacy coefficients are retained as evidence, not pooled.
      v_corr := CASE WHEN a.corr_n >= c_tc_min_hands
                          AND a.corr_n*a.corr_sxx-a.corr_sx*a.corr_sx > 0
                          AND a.corr_n*a.corr_syy-a.corr_sy*a.corr_sy > 0
        THEN round(GREATEST(-1,LEAST(1,
          (a.corr_n*a.corr_sxy-a.corr_sx*a.corr_sy) /
          sqrt((a.corr_n*a.corr_sxx-a.corr_sx*a.corr_sx) *
               (a.corr_n*a.corr_syy-a.corr_sy*a.corr_sy)))),4) END;
      v_follow := CASE WHEN coalesce(a.sequential_actions, 0) > 0
                       THEN LEAST(coalesce(a.fast_follows, 0) / a.sequential_actions, 1) END;
      -- The correlation scores by its one-sided 99% Fisher-z lower confidence
      -- bound over the measured paired hands, so a short sample cannot reach
      -- high on r alone. Detection still tests r itself.
      v_corr_lb := CASE WHEN v_corr IS NOT NULL AND a.corr_n > 3
        THEN round((tanh(atanh(LEAST(GREATEST(v_corr::double precision, -0.999999), 0.999999))
                         - c_tc_corr_lb_z::double precision / sqrt((a.corr_n - 3)::double precision)))::numeric, 4) END;
      v_num := jsonb_strip_nulls(jsonb_build_object(
                 'hands_together', a.hands_together, 'sequential_actions', a.sequential_actions,
                 'fast_follows', a.fast_follows, 'latency_corr', v_corr, 'latency_corr_lower_bound_99', v_corr_lb,
                 'correlation_hands', coalesce(a.corr_n,0), 'correlation_method', 'pooled_paired_hand_moments',
                 'follow_share', round(v_follow, 4)));
      IF coalesce(a.hands_together, 0) >= c_tc_min_hands AND coalesce(a.sequential_actions, 0) >= c_tc_min_seq
         AND (v_corr >= c_tc_min_corr OR v_follow >= c_tc_min_follow) THEN
        v_type := 'TIMING_CORRELATION';
        v_score := LEAST(100, round(40 + 50 * GREATEST(coalesce(v_corr_lb, 0), coalesce(v_follow, 0))))::integer;
      END IF;
    END IF;
    CONTINUE WHEN v_type IS NULL;
    v_flagged := jsonb_set(v_flagged, ARRAY[v_type], to_jsonb((v_flagged ->> v_type)::integer + 1));
    v_ev := v_num || v_ctx || jsonb_build_object('source', 'engine', 'windows', a.windows,
              'aggregation_hours', c_agg_hours, 'latest_score', v_score,
              'latest_window_start', v_from, 'latest_window_end', v_to);

    -- ONE FINDING PER SUBJECT EXTENDS: the newest finding of the subject
    -- whose window meets the evidence's span. Its status is never touched.
    SELECT t.id, t.suspicion_score INTO v_cur
      FROM public.lightning_integrity_signal t
     WHERE t.cluster_id = p_cluster_id AND t.pattern_type = v_type AND t.player_a = a.player_a
       AND t.player_b IS NOT DISTINCT FROM a.player_b
       AND t.window_end >= a.w_from AND t.window_start <= a.w_to
     ORDER BY t.window_end DESC, t.id DESC
     LIMIT 1
       FOR UPDATE;
    IF NOT FOUND THEN
      v_id := NULL;
      INSERT INTO public.lightning_integrity_signal AS t
        (cluster_id, pattern_type, source, player_a, player_b, window_start, window_end,
         suspicion_score, severity, evidence)
      VALUES (p_cluster_id, v_type, 'engine', a.player_a, a.player_b, a.w_from, a.w_to, v_score,
              CASE WHEN v_score >= 70 THEN 'high' WHEN v_score >= 40 THEN 'medium' ELSE 'low' END, v_ev)
      ON CONFLICT (cluster_id, pattern_type, window_start, window_end, player_a, player_b) DO NOTHING
      RETURNING t.id INTO v_id;
      IF v_id IS NULL THEN
        v_same := v_same + 1;
      ELSE
        v_ins := v_ins + 1;
      END IF;
    ELSE
      v_peak := GREATEST(v_cur.suspicion_score::integer, v_score);
      UPDATE public.lightning_integrity_signal t
         SET window_start = LEAST(t.window_start, a.w_from), window_end = GREATEST(t.window_end, a.w_to),
             suspicion_score = v_peak,
             severity = CASE WHEN v_peak >= 70 THEN 'high' WHEN v_peak >= 40 THEN 'medium' ELSE 'low' END,
             evidence = v_ev, updated_at = now()
       WHERE t.id = v_cur.id
         AND (t.window_start, t.window_end, t.suspicion_score::integer, t.evidence)
             IS DISTINCT FROM (LEAST(t.window_start, a.w_from), GREATEST(t.window_end, a.w_to), v_peak, v_ev);
      IF FOUND THEN
        v_upd := v_upd + 1;
      ELSE
        v_same := v_same + 1;
      END IF;
    END IF;
  END LOOP;

  -- RETENTION: 48 hours of evidence, at most 5000 rows of this Cluster a call.
  DELETE FROM public.lightning_integrity_engine_window w
   WHERE w.id IN (SELECT x.id FROM public.lightning_integrity_engine_window x
                   WHERE x.cluster_id = p_cluster_id AND x.window_to < v_now - make_interval(hours => c_keep_hours)
                   ORDER BY x.window_to LIMIT 5000);
  GET DIAGNOSTICS v_pruned = ROW_COUNT;

  RETURN jsonb_build_object('ok', true,
                            'window_from', v_from, 'window_to', v_to,
                            'players_read', v_read -> 'players', 'pairs_read', v_read -> 'pairs',
                            'flagged', v_flagged,
                            'inserted', v_ins, 'updated', v_upd, 'unchanged', v_same,
                            'evidence_stored', v_stored, 'aggregation_hours', c_agg_hours,
                            'evidence_pruned', v_pruned,
                            'rejected', v_rejected,
                            'clamped', v_clamped,
                            'truncated', v_trunc,
                            'thresholds', jsonb_build_object(
                              'latency_min_decisions', c_lat_min_dec, 'latency_max_cv', c_lat_max_cv,
                              'latency_min_fast_share', c_lat_min_fast, 'timing_min_hands', c_tc_min_hands,
                              'timing_min_sequential', c_tc_min_seq, 'timing_min_corr', c_tc_min_corr,
                              'timing_min_follow_share', c_tc_min_follow,
                              'timing_corr_score_method', 'fisher_z_one_sided_99_lower_bound',
                              'timing_corr_score_z', c_tc_corr_lb_z));
END
$_$;


ALTER FUNCTION public.fn_lightning_integrity_report(p_cluster_id uuid, p_signals jsonb, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 47874 (class 0 OID 0)
-- Dependencies: 4174
-- Name: FUNCTION fn_lightning_integrity_report(p_cluster_id uuid, p_signals jsonb, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_lightning_integrity_report(p_cluster_id uuid, p_signals jsonb, p_now timestamp with time zone) IS 'Lightning Phase 11 (20261008161509): the engine reports its decision-timing aggregates for a window ({window_from, window_to, hands, decisions, fast_ms, dropped_players, dropped_pairs, players[<=500]{player_id, decisions, timeouts, p50_ms, p95_ms, mean_ms, stddev_ms, cv, fast_share}, pairs[<=200]{player_a, player_b, hands_together, sequential_actions, fast_follows, latency_corr}}); the database validates and clamps them and writes only the abnormal ones into lightning_integrity_signal (DECISION_LATENCY, TIMING_CORRELATION), idempotently per (Cluster, type, window, subject). Any card/hole/deck/seed key refuses the call. Telemetry only: no seating path reads it. service_role only.';


--
-- TOC entry 6052 (class 1255 OID 130340221)
-- Name: fn_lightning_integrity_scan(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_integrity_scan(p_cluster_id uuid DEFAULT NULL::uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  c_max_hands      constant integer := 20000;
  c_max_sessions   constant integer := 5000;
  c_max_clusters   constant integer := 50;
  c_max_signals    constant integer := 500;
  c_pair_min_hands constant integer := 30;
  c_pair_min_ratio constant numeric := 2.0;
  c_pair_stratum   constant interval := interval '10 minutes';
  c_flow_min_hands constant integer := 30;
  c_flow_min_z     constant numeric := 4.0;
  c_flow_min_gross_bb constant numeric := 50;
  c_long_max_score constant integer := 69;
  c_flow_min_dir   constant numeric := 0.8;
  c_flow_min_win   constant numeric := 0.8;
  c_join_window_s  constant integer := 10;
  c_join_min       constant integer := 3;
  c_long_hours     constant numeric := 12;
  c_link_min_hands constant integer := 5;
  v_now      timestamptz := clock_timestamp();
  v_to       timestamptz;
  v_from     timestamptz;
  v_clamped  boolean := false;
  v_cluster  uuid;
  v_hands    integer;
  v_sessions integer;
  v_scanned  integer := 0;
  v_hand_sum bigint := 0;
  v_budget   boolean := false;
  v_counts   jsonb := '{}'::jsonb;
  v_part     jsonb;
  v_mirrored integer := 0;
  v_n        integer;
  v_bb       numeric;
BEGIN
  v_to := LEAST(coalesce(p_to, date_trunc('hour', v_now)), v_now);
  v_from := coalesce(p_from, v_to - interval '24 hours');
  IF v_from >= v_to THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'INVALID_WINDOW', 'window_from', v_from, 'window_to', v_to);
  END IF;
  IF v_to - v_from > interval '7 days' THEN
    v_from := v_to - interval '7 days';
    v_clamped := true;
  END IF;

  FOR v_cluster IN
    SELECT x.cluster_id FROM (
      SELECT p_cluster_id AS cluster_id WHERE p_cluster_id IS NOT NULL
      UNION
      SELECT DISTINCT lh.cluster_id FROM public.lightning_hand lh
       WHERE p_cluster_id IS NULL AND lh.formed_at >= v_from AND lh.formed_at < v_to
    ) x ORDER BY x.cluster_id LIMIT c_max_clusters
  LOOP
    v_scanned := v_scanned + 1;
    -- FINDINGS EXTEND, NEVER DUPLICATE (2026-10-09, Phase 11 remediation).
    -- One scan or engine report of a Cluster at a time: overlapping runs
    -- (the sweep, an operator, a retry) wait for each other here, so the
    -- extend-or-insert below and the mirror's check see each other's rows.
    -- Clusters are taken in cluster_id order, so two scans cannot deadlock.
    PERFORM pg_advisory_xact_lock(hashtext('lightning-integrity:' || v_cluster::text));
    SELECT cg.bb INTO v_bb FROM public.cash_games cg WHERE cg.id = v_cluster;

    SELECT count(*) INTO v_hands FROM (
      SELECT 1 FROM public.lightning_hand lh
       WHERE lh.cluster_id = v_cluster AND lh.formed_at >= v_from AND lh.formed_at < v_to
         AND lh.settled_at IS NOT NULL
       LIMIT c_max_hands + 1) q;
    IF v_hands > c_max_hands THEN v_budget := true; v_hands := c_max_hands; END IF;
    v_hand_sum := v_hand_sum + v_hands;

    -- PAIR SIGNALS: one pass over the shared hands feeds four patterns.
    WITH h AS MATERIALIZED (
      SELECT lh.hand_id, lh.formed_at FROM public.lightning_hand lh
       WHERE lh.cluster_id = v_cluster AND lh.formed_at >= v_from AND lh.formed_at < v_to
         AND lh.settled_at IS NOT NULL
       ORDER BY lh.formed_at DESC, lh.hand_id
       LIMIT c_max_hands
    ), hp AS MATERIALIZED (
      SELECT p.hand_id, p.player_id, coalesce(p.net_result, 0) AS net, h.formed_at
        FROM public.lightning_hand_player p JOIN h ON h.hand_id = p.hand_id
    ), per AS (
      SELECT hp.player_id, count(*) AS hands FROM hp GROUP BY 1
    ), pairs AS MATERIALIZED (
      SELECT a.player_id AS pa, b.player_id AS pb,
             count(*) AS together,
             count(*) FILTER (WHERE sign(a.net) * sign(b.net) < 0) AS opposed,
             count(*) FILTER (WHERE a.net < 0 AND b.net > 0) AS b_won,
             coalesce(sum(LEAST(abs(a.net), abs(b.net))) FILTER (WHERE sign(a.net) * sign(b.net) < 0), 0) AS gross,
             coalesce(sum(CASE WHEN a.net < 0 AND b.net > 0 THEN LEAST(-a.net, b.net)
                               WHEN a.net > 0 AND b.net < 0 THEN -LEAST(a.net, -b.net)
                               ELSE 0 END), 0) AS net_to_b
        FROM hp a JOIN hp b ON b.hand_id = a.hand_id AND b.player_id > a.player_id
       GROUP BY 1, 2
    ), dealt AS MATERIALIZED (
      -- WHO COULD BE DEALT, AND WHEN (2026-10-19): presence is read from the
      -- hands the Cluster actually dealt, in ten-minute strata of the window.
      -- An open pool session is not presence: a busted, sitting-out or
      -- otherwise unplayable anchor keeps one and is dealt nothing. Counting
      -- those sessions made the pool look four times larger than the players
      -- who could be dealt during the 2026-10-17 busted-anchor stall, so
      -- every pair of the few playable players looked concentrated.
      SELECT hp.player_id, date_bin(c_pair_stratum, hp.formed_at, v_from) AS b, count(*) AS k
        FROM hp GROUP BY 1, 2
    ), stratum AS (
      SELECT date_bin(c_pair_stratum, h.formed_at, v_from) AS b, count(*) AS n FROM h GROUP BY 1
    ), ex AS (
      -- THE CO-PRESENCE EXPECTATION of a candidate pair: in every stratum
      -- where both were dealt, the hands they would share if each was dealt
      -- their own share of that stratum's hands independently of the other
      -- (A's hands x B's hands / the stratum's hands), summed.
      SELECT pr.pa, pr.pb, sum(x.k::numeric * y.k / st.n) AS expected,
             sum(x.k) AS hands_a_copresent, sum(y.k) AS hands_b_copresent
        FROM pairs pr
        JOIN dealt x ON x.player_id = pr.pa
        JOIN dealt y ON y.player_id = pr.pb AND y.b = x.b
        JOIN stratum st ON st.b = x.b
       WHERE pr.together >= c_pair_min_hands
       GROUP BY pr.pa, pr.pb
    ), scored AS (
      SELECT pr.*, pa_.hands AS hands_a, pb_.hands AS hands_b,
             coalesce(ex.expected, pa_.hands::numeric * pb_.hands::numeric / GREATEST(v_hands, 1)) AS expected,
             CASE WHEN ex.expected IS NOT NULL THEN 'dealt_presence_10m' ELSE 'whole_window' END AS expectation,
             ex.hands_a_copresent, ex.hands_b_copresent
        FROM pairs pr
        JOIN per pa_ ON pa_.player_id = pr.pa
        JOIN per pb_ ON pb_.player_id = pr.pb
        LEFT JOIN ex ON ex.pa = pr.pa AND ex.pb = pr.pb
    ), cand AS (
      SELECT 'PAIRING_CONCENTRATION'::text AS pattern, s.pa, s.pb,
             LEAST(100, GREATEST(0, round(50 + 25 * log(2, (s.together / GREATEST(s.expected, 0.000001)) / c_pair_min_ratio))))::integer AS score,
             jsonb_build_object('hands_together', s.together, 'hands_a', s.hands_a, 'hands_b', s.hands_b,
                                'hands_in_window', v_hands, 'expected_together', round(s.expected, 2),
                                'expectation', s.expectation,
                                'hands_a_while_b_present', s.hands_a_copresent,
                                'hands_b_while_a_present', s.hands_b_copresent,
                                'concentration_ratio', round(s.together / GREATEST(s.expected, 0.000001), 3),
                                'share_of_fewer', round(s.together::numeric / LEAST(s.hands_a, s.hands_b), 3),
                                'min_hands', c_pair_min_hands, 'min_ratio', c_pair_min_ratio) AS evidence
        FROM scored s
       WHERE s.together >= c_pair_min_hands
         AND s.together >= c_pair_min_ratio * s.expected
      UNION ALL
      SELECT 'CHIP_FLOW', s.pa, s.pb,
             LEAST(100, round(60 * abs(s.net_to_b) / s.gross + 0.8 * LEAST(s.opposed, 50)))::integer,
             jsonb_build_object('hands_together', s.together, 'opposed_hands', s.opposed,
                                'gross_flow', s.gross, 'net_flow', abs(s.net_to_b),
                                'direction_ratio', round(abs(s.net_to_b) / s.gross, 4),
                                'receiver_win_share', round(GREATEST(s.b_won, s.opposed - s.b_won)::numeric / s.opposed, 4),
                                'receiver', CASE WHEN s.net_to_b > 0 THEN s.pb ELSE s.pa END,
                                'sender', CASE WHEN s.net_to_b > 0 THEN s.pa ELSE s.pb END,
                                'min_opposed_hands', c_flow_min_hands, 'min_direction', c_flow_min_dir,
                                'min_win_share', c_flow_min_win,
                                'win_z', round((GREATEST(s.b_won, s.opposed - s.b_won) - s.opposed / 2.0) / sqrt(s.opposed / 4.0), 3),
                                'gross_bb', CASE WHEN coalesce(v_bb, 0) > 0 THEN round(s.gross / v_bb, 2) END,
                                'min_z', c_flow_min_z, 'min_gross_bb', c_flow_min_gross_bb)
        FROM scored s
       WHERE s.opposed >= c_flow_min_hands AND s.gross > 0
         AND abs(s.net_to_b) / s.gross >= c_flow_min_dir
         AND GREATEST(s.b_won, s.opposed - s.b_won)::numeric / s.opposed >= c_flow_min_win
         AND (GREATEST(s.b_won, s.opposed - s.b_won) - s.opposed / 2.0) / sqrt(s.opposed / 4.0) >= c_flow_min_z
         AND s.gross >= c_flow_min_gross_bb * coalesce(v_bb, 0)
      UNION ALL
      SELECT 'DEVICE_OVERLAP', s.pa, s.pb, 60,
             jsonb_build_object('hands_together', s.together, 'shared_ip_addresses', d.n,
                                'source', 'user_sessions', 'min_hands', c_link_min_hands)
        FROM scored s
        CROSS JOIN LATERAL (
          SELECT count(DISTINCT ua.ip_address) AS n
            FROM public.user_sessions ua
            JOIN public.user_sessions ub ON ub.ip_address = ua.ip_address
           WHERE ua.user_id = s.pa AND ub.user_id = s.pb AND ua.ip_address IS NOT NULL) d
       WHERE s.together >= c_link_min_hands AND d.n > 0
      UNION ALL
      SELECT 'ACCOUNT_RELATIONSHIP', s.pa, s.pb, 50,
             jsonb_build_object('hands_together', s.together, 'relationship', 'referral',
                                'referrer', CASE WHEN ra.referred_by = s.pb THEN s.pb ELSE s.pa END,
                                'referred', CASE WHEN ra.referred_by = s.pb THEN s.pa ELSE s.pb END,
                                'source', 'profiles.referred_by', 'min_hands', c_link_min_hands)
        FROM scored s
        LEFT JOIN public.profiles ra ON ra.id = s.pa
        LEFT JOIN public.profiles rb ON rb.id = s.pb
       WHERE s.together >= c_link_min_hands
         AND (ra.referred_by = s.pb OR rb.referred_by = s.pa)
    ), capped AS (
      SELECT cand.*, row_number() OVER (PARTITION BY cand.pattern ORDER BY cand.score DESC, cand.pa, cand.pb) AS rn
        FROM cand
    ), k AS (
      SELECT c.pattern, c.pa, c.pb, c.score,
             c.evidence || jsonb_build_object('latest_score', c.score, 'latest_window_start', v_from,
                                              'latest_window_end', v_to) AS evidence
        FROM capped c WHERE c.rn <= c_max_signals
    ), cur AS (
      -- THE SUBJECT'S FINDING: the newest row of the same Cluster, pattern
      -- and subject whose window meets this one. It is extended; its status
      -- (an operator's review) is never touched.
      SELECT DISTINCT ON (k.pattern, k.pa, k.pb) t.id, k.pattern, k.pa, k.pb
        FROM k JOIN public.lightning_integrity_signal t
          ON t.cluster_id = v_cluster AND t.pattern_type = k.pattern AND t.player_a = k.pa
         AND t.player_b IS NOT DISTINCT FROM k.pb
         AND t.window_end >= v_from AND t.window_start <= v_to
       ORDER BY k.pattern, k.pa, k.pb, t.window_end DESC, t.id DESC
    ), ext AS (
      UPDATE public.lightning_integrity_signal t
         SET window_start = LEAST(t.window_start, v_from),
             window_end = GREATEST(t.window_end, v_to),
             suspicion_score = GREATEST(t.suspicion_score, k.score),
             severity = CASE WHEN GREATEST(t.suspicion_score, k.score) >= 70 THEN 'high'
                             WHEN GREATEST(t.suspicion_score, k.score) >= 40 THEN 'medium' ELSE 'low' END,
             evidence = k.evidence, updated_at = now()
        FROM cur JOIN k ON k.pattern = cur.pattern AND k.pa = cur.pa AND k.pb IS NOT DISTINCT FROM cur.pb
       WHERE t.id = cur.id
         AND (t.window_start, t.window_end, t.suspicion_score::integer, t.evidence)
             IS DISTINCT FROM (LEAST(t.window_start, v_from), GREATEST(t.window_end, v_to),
                               GREATEST(t.suspicion_score::integer, k.score), k.evidence)
      RETURNING t.pattern_type
    ), ins AS (
      INSERT INTO public.lightning_integrity_signal AS t
        (cluster_id, pattern_type, source, player_a, player_b, window_start, window_end,
         suspicion_score, severity, evidence)
      SELECT v_cluster, k.pattern, 'scan', k.pa, k.pb, v_from, v_to, k.score,
             CASE WHEN k.score >= 70 THEN 'high' WHEN k.score >= 40 THEN 'medium' ELSE 'low' END,
             k.evidence
        FROM k
       WHERE NOT EXISTS (SELECT 1 FROM cur WHERE cur.pattern = k.pattern AND cur.pa = k.pa
                                             AND cur.pb IS NOT DISTINCT FROM k.pb)
      ON CONFLICT (cluster_id, pattern_type, window_start, window_end, player_a, player_b) DO NOTHING
      RETURNING t.pattern_type
    ), up AS (
      SELECT ext.pattern_type FROM ext UNION ALL SELECT ins.pattern_type FROM ins
    )
    SELECT coalesce(jsonb_object_agg(u.pattern_type, u.n), '{}'::jsonb) INTO v_part
      FROM (SELECT up.pattern_type, count(*) AS n FROM up GROUP BY 1) u;
    SELECT coalesce(jsonb_object_agg(k, coalesce((v_counts ->> k)::integer, 0) + coalesce((v_part ->> k)::integer, 0)), '{}'::jsonb)
      INTO v_counts
      FROM (SELECT jsonb_object_keys(v_counts) UNION SELECT jsonb_object_keys(v_part)) x(k);

    -- POOL SESSION SIGNALS.
    SELECT count(*) INTO v_sessions FROM (
      SELECT 1 FROM public.lightning_pool_session ps
       WHERE ps.cluster_id = v_cluster AND ps.entered_at >= v_from AND ps.entered_at < v_to
       LIMIT c_max_sessions + 1) q;
    IF v_sessions > c_max_sessions THEN v_budget := true; END IF;

    WITH s AS MATERIALIZED (
      SELECT ps.id, ps.player_id, ps.entered_at, ps.exited_at,
             -- ONLY WHAT THE PLAYER DID: an entry within the pattern's window
             -- of an epoch start (the conversion entering everyone, the
             -- unfreeze) is the system's; only Stop Playing and standing up
             -- from the anchor seat are the player's own exits.
             NOT EXISTS (SELECT 1 FROM public.cash_cluster_epoch ce
                          WHERE ce.cluster_id = ps.cluster_id
                            AND ce.started_at BETWEEN ps.entered_at - make_interval(secs => c_join_window_s)
                                                  AND ps.entered_at + make_interval(secs => c_join_window_s)) AS own_entry,
             coalesce(ps.exit_reason IN ('stop_playing', 'anchor_seat_left'), false) AS own_exit
        FROM public.lightning_pool_session ps
       WHERE ps.cluster_id = v_cluster AND ps.entered_at >= v_from AND ps.entered_at < v_to
       ORDER BY ps.entered_at DESC, ps.id
       LIMIT c_max_sessions
    ), per AS (
      SELECT s.player_id, count(*) AS sessions FROM s GROUP BY 1
    ), joint AS (
      SELECT a.player_id AS pa, b.player_id AS pb,
             count(DISTINCT a.id) AS joint_a, count(DISTINCT b.id) AS joint_b
        FROM s a
        JOIN s b ON b.player_id > a.player_id
                AND b.entered_at BETWEEN a.entered_at - make_interval(secs => c_join_window_s)
                                     AND a.entered_at + make_interval(secs => c_join_window_s)
                AND a.exited_at IS NOT NULL AND b.exited_at IS NOT NULL
                AND a.own_entry AND b.own_entry AND a.own_exit AND b.own_exit
                AND b.exited_at BETWEEN a.exited_at - make_interval(secs => c_join_window_s)
                                    AND a.exited_at + make_interval(secs => c_join_window_s)
       GROUP BY 1, 2
    ), cand AS (
      SELECT 'COORDINATED_JOIN_LEAVE'::text AS pattern, j.pa, j.pb,
             LEAST(100, 40 + 10 * LEAST(j.joint_a, j.joint_b))::integer AS score,
             jsonb_build_object('joint_sessions', LEAST(j.joint_a, j.joint_b),
                                'sessions_a', pa_.sessions, 'sessions_b', pb_.sessions,
                                'within_seconds', c_join_window_s, 'min_joint', c_join_min,
                                'player_initiated_only', true) AS evidence
        FROM joint j
        JOIN per pa_ ON pa_.player_id = j.pa
        JOIN per pb_ ON pb_.player_id = j.pb
       WHERE LEAST(j.joint_a, j.joint_b) >= c_join_min
         AND LEAST(j.joint_a, j.joint_b)::numeric / LEAST(pa_.sessions, pb_.sessions) >= 0.5
      UNION ALL
      SELECT 'SESSION_LENGTH', l.player_id, NULL::uuid,
             LEAST(c_long_max_score, round(50 + (l.hours - c_long_hours) * 10 / 3))::integer,
             jsonb_build_object('longest_session_hours', round(l.hours, 2), 'pool_session_id', l.id,
                                'still_open', l.open, 'min_hours', c_long_hours)
        FROM (
          SELECT DISTINCT ON (ps.player_id) ps.player_id, ps.id, ps.exited_at IS NULL AS open,
                 extract(epoch FROM (coalesce(ps.exited_at, v_to) - ps.entered_at)) / 3600 AS hours
            FROM (SELECT x.* FROM public.lightning_pool_session x
                   WHERE x.cluster_id = v_cluster
                     AND x.entered_at >= v_from - interval '7 days' AND x.entered_at < v_to
                     AND (x.exited_at IS NULL OR x.exited_at > v_from)
                     AND coalesce(x.exited_at, v_to) - x.entered_at >= c_long_hours * interval '1 hour'
                   ORDER BY x.entered_at DESC, x.id
                   LIMIT c_max_sessions) ps
           ORDER BY ps.player_id, coalesce(ps.exited_at, v_to) - ps.entered_at DESC, ps.id
        ) l
       WHERE l.hours >= c_long_hours
    ), capped AS (
      SELECT cand.*, row_number() OVER (PARTITION BY cand.pattern ORDER BY cand.score DESC, cand.pa, cand.pb) AS rn
        FROM cand
    ), k AS (
      SELECT c.pattern, c.pa, c.pb, c.score,
             c.evidence || jsonb_build_object('latest_score', c.score, 'latest_window_start', v_from,
                                              'latest_window_end', v_to) AS evidence
        FROM capped c WHERE c.rn <= c_max_signals
    ), cur AS (
      -- THE SUBJECT'S FINDING: the newest row of the same Cluster, pattern
      -- and subject whose window meets this one. It is extended; its status
      -- (an operator's review) is never touched.
      SELECT DISTINCT ON (k.pattern, k.pa, k.pb) t.id, k.pattern, k.pa, k.pb
        FROM k JOIN public.lightning_integrity_signal t
          ON t.cluster_id = v_cluster AND t.pattern_type = k.pattern AND t.player_a = k.pa
         AND t.player_b IS NOT DISTINCT FROM k.pb
         AND t.window_end >= v_from AND t.window_start <= v_to
       ORDER BY k.pattern, k.pa, k.pb, t.window_end DESC, t.id DESC
    ), ext AS (
      UPDATE public.lightning_integrity_signal t
         SET window_start = LEAST(t.window_start, v_from),
             window_end = GREATEST(t.window_end, v_to),
             suspicion_score = GREATEST(t.suspicion_score, k.score),
             severity = CASE WHEN GREATEST(t.suspicion_score, k.score) >= 70 THEN 'high'
                             WHEN GREATEST(t.suspicion_score, k.score) >= 40 THEN 'medium' ELSE 'low' END,
             evidence = k.evidence, updated_at = now()
        FROM cur JOIN k ON k.pattern = cur.pattern AND k.pa = cur.pa AND k.pb IS NOT DISTINCT FROM cur.pb
       WHERE t.id = cur.id
         AND (t.window_start, t.window_end, t.suspicion_score::integer, t.evidence)
             IS DISTINCT FROM (LEAST(t.window_start, v_from), GREATEST(t.window_end, v_to),
                               GREATEST(t.suspicion_score::integer, k.score), k.evidence)
      RETURNING t.pattern_type
    ), ins AS (
      INSERT INTO public.lightning_integrity_signal AS t
        (cluster_id, pattern_type, source, player_a, player_b, window_start, window_end,
         suspicion_score, severity, evidence)
      SELECT v_cluster, k.pattern, 'scan', k.pa, k.pb, v_from, v_to, k.score,
             CASE WHEN k.score >= 70 THEN 'high' WHEN k.score >= 40 THEN 'medium' ELSE 'low' END,
             k.evidence
        FROM k
       WHERE NOT EXISTS (SELECT 1 FROM cur WHERE cur.pattern = k.pattern AND cur.pa = k.pa
                                             AND cur.pb IS NOT DISTINCT FROM k.pb)
      ON CONFLICT (cluster_id, pattern_type, window_start, window_end, player_a, player_b) DO NOTHING
      RETURNING t.pattern_type
    ), up AS (
      SELECT ext.pattern_type FROM ext UNION ALL SELECT ins.pattern_type FROM ins
    )
    SELECT coalesce(jsonb_object_agg(u.pattern_type, u.n), '{}'::jsonb) INTO v_part
      FROM (SELECT up.pattern_type, count(*) AS n FROM up GROUP BY 1) u;
    SELECT coalesce(jsonb_object_agg(k, coalesce((v_counts ->> k)::integer, 0) + coalesce((v_part ->> k)::integer, 0)), '{}'::jsonb)
      INTO v_counts
      FROM (SELECT jsonb_object_keys(v_counts) UNION SELECT jsonb_object_keys(v_part)) x(k);

    -- THE EXISTING PAIR STORE: each CHIP_FLOW finding once, in the duel
    -- scan's convention, so it reaches the operator queue and case evidence.
    INSERT INTO public.ca_collusion_signals
      (window_days, user_a, user_b, hands_together, gross_flow, net_flow, direction_ratio, both_cert, detail)
    SELECT GREATEST(1, ceil(extract(epoch FROM (t.window_end - t.window_start)) / 86400))::integer,
           (t.evidence ->> 'receiver')::uuid, (t.evidence ->> 'sender')::uuid,
           (t.evidence ->> 'hands_together')::integer,
           (t.evidence ->> 'gross_flow')::numeric, (t.evidence ->> 'net_flow')::numeric,
           (t.evidence ->> 'direction_ratio')::numeric,
           public.fn_ca_is_cert_account((t.evidence ->> 'receiver')::uuid)
             AND public.fn_ca_is_cert_account((t.evidence ->> 'sender')::uuid),
           jsonb_build_object(
             'signal', 'lightning_chip_flow',
             'since', t.window_start,
             'until', t.window_end,
             'cluster_id', v_cluster,
             'lightning_signal_id', t.id,
             'lightning_key', v_cluster::text || ':' || t.player_a::text || ':' || t.player_b::text || ':' || t.id::text,
             'opposed_hands', (t.evidence ->> 'opposed_hands')::integer,
             'note', 'Lightning: hands_together is Lightning hands both played; gross_flow and net_flow '
                     || 'are chips between the pair over the hands they finished with opposite results; '
                     || 'direction_ratio is net over gross. Telemetry only - no automatic action taken')
      FROM public.lightning_integrity_signal t
     WHERE t.cluster_id = v_cluster AND t.pattern_type = 'CHIP_FLOW'
       AND t.window_start <= v_from AND t.window_end >= v_to
       AND NOT EXISTS (
         SELECT 1 FROM public.ca_collusion_signals x
          WHERE (x.detail ->> 'signal') = 'lightning_chip_flow'
            AND (x.detail ->> 'lightning_signal_id') = t.id::text)
    ON CONFLICT ((detail ->> 'lightning_signal_id')) WHERE ((detail ->> 'signal') = 'lightning_chip_flow') DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_mirrored := v_mirrored + v_n;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'window_from', v_from,
    'window_to', v_to,
    'window_clamped', v_clamped,
    'clusters_scanned', v_scanned,
    'hands_scanned', v_hand_sum,
    'budget_hit', v_budget,
    'written', v_counts,
    'chip_flow_mirrored', v_mirrored,
    'engine_reported', jsonb_build_array('DECISION_LATENCY', 'TIMING_CORRELATION'),
    'thresholds', jsonb_build_object(
      'pair_min_hands', c_pair_min_hands, 'pair_min_ratio', c_pair_min_ratio,
      'flow_min_opposed_hands', c_flow_min_hands, 'flow_min_direction', c_flow_min_dir,
      'flow_min_win_share', c_flow_min_win, 'join_window_seconds', c_join_window_s,
      'join_min_sessions', c_join_min, 'long_session_hours', c_long_hours,
      'link_min_hands', c_link_min_hands, 'max_hands', c_max_hands,
      'max_sessions', c_max_sessions, 'max_clusters', c_max_clusters,
      'flow_min_z', c_flow_min_z, 'flow_min_gross_bb', c_flow_min_gross_bb,
      'long_session_max_score', c_long_max_score, 'pairing_expectation', 'dealt_presence_10m',
      'join_leave_counts', 'player_initiated', 'findings', 'extend_per_subject'));
END
$$;


