COMMENT ON FUNCTION public.fn_lightning_operator_control(p_cluster_id uuid, p_action text, p_reason text, p_args jsonb) IS 'Lightning Phase 13 (20261009235505): THE LIGHTNING OPERATOR CONTROL DOOR - pause / resume, disable_joins / enable_joins, drain (the EMERGENCY DRAIN state machine), freeze (the existing freeze path) / unfreeze (platform admin, through fn_cash_cluster_unfreeze), enable_lightning / disable_lightning (a live Cluster drains), set / disable / enable / rollback matcher version, set_flag (the specification flags on existing gates). Gate: service_role, platform admin or club control (fn_lightning_operator_may_control). Reason required; idempotent by p_args.request_id; every change writes one operator_<action> event. Answers {ok, idempotent, action, cluster_id, request_id, before, after, event_id, detail} or {ok:false, code, reason}. authenticated and service_role, never anon.';


--
-- TOC entry 5765 (class 1255 OID 134141784)
-- Name: fn_lightning_operator_forensics(uuid, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_operator_forensics(p_cluster_id uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g      record;
  v_to   timestamptz;
  v_from timestamptz;
BEGIN
  SELECT cg.id, cg.club_id INTO g FROM public.cash_games cg WHERE cg.id = p_cluster_id;
  IF NOT public.fn_lightning_operator_may(g.club_id) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_AUTHORIZED', 'reason', 'NOT_AUTHORIZED');
  END IF;
  IF g.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'reason', 'NOT_FOUND');
  END IF;
  v_to := coalesce(p_to, clock_timestamp());
  v_from := coalesce(p_from, v_to - interval '1 hour');
  IF v_from >= v_to THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_WINDOW', 'reason', 'INVALID_WINDOW');
  END IF;
  RETURN public.fn_lightning_operator_redact(public.fn_lightning_cluster_forensics(g.id, v_from, v_to, p_limit));
END
$$;


