-- TOC entry 5829 (class 1255 OID 134141557)
-- Name: fn_lightning_operator_may(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_operator_may(p_club_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT coalesce(auth.role(), '') = 'service_role'
      OR (auth.uid() IS NOT NULL
          AND (coalesce(public.fn_is_platform_admin(), false)
               OR coalesce(public.fn_ca_can_review_integrity(p_club_id), false)));
$$;


