      OR (auth.uid() IS NOT NULL
          AND (coalesce(public.fn_is_platform_admin(), false)
               OR (p_club_id IS NOT NULL
                   AND coalesce(public.fn_ca_is_club_control(p_club_id, auth.uid()), false))));
