--
-- TOC entry 4911 (class 1255 OID 179923917)
-- Name: fn_lightning_pilot_assignment_set(boolean, uuid, text, uuid[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_pilot_assignment_set(p_active boolean, p_request_id uuid, p_manifest_sha256 text, p_player_ids uuid[], p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '15s'
    AS $$
DECLARE prior public.lightning_pilot_assignment_receipts%ROWTYPE; v_players uuid[]; v_result jsonb;
BEGIN
 IF auth.uid() IS DISTINCT FROM '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid OR public.fn_caller_session_is_live() IS DISTINCT FROM true THEN
 RAISE EXCEPTION 'pilot assignment not authorized' USING ERRCODE='42501'; END IF;
 IF p_active IS NULL OR p_request_id IS NULL OR p_manifest_sha256 IS DISTINCT FROM '121f80d2529012e532b4d3a702e2772cde9aa7778a82df26f5a02082d2b0ba8a' OR length(btrim(coalesce(p_reason,'')))<12 THEN
 RAISE EXCEPTION 'pilot assignment input mismatch' USING ERRCODE='22023'; END IF;
 SELECT array_agg(x ORDER BY x) INTO v_players FROM unnest(p_player_ids) x;
 IF cardinality(v_players) IS DISTINCT FROM 72 OR v_players IS DISTINCT FROM public.fn_lightning_pilot_assignment_players() THEN
 RAISE EXCEPTION 'pilot assignment participant manifest mismatch' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(176217,72);
 SELECT * INTO prior FROM public.lightning_pilot_assignment_receipts WHERE request_id=p_request_id;
 IF FOUND THEN
  IF prior.actor_id IS DISTINCT FROM auth.uid() OR prior.active IS DISTINCT FROM p_active OR prior.manifest_sha256 IS DISTINCT FROM p_manifest_sha256 OR prior.player_ids IS DISTINCT FROM v_players OR prior.reason IS DISTINCT FROM btrim(p_reason) THEN
   RAISE EXCEPTION 'pilot assignment request intent mismatch' USING ERRCODE='22023'; END IF;
  RETURN prior.receipt;
 END IF;
 IF p_active THEN
  IF NOT EXISTS(SELECT 1 FROM public.clubs WHERE id='e14bc9f7-736d-425f-8f2c-e78305ebac1d' AND owner_id=auth.uid() AND is_public=false)
  OR EXISTS(SELECT 1 FROM unnest(v_players) x LEFT JOIN public.profiles p ON p.id=x LEFT JOIN public.club_members cm ON cm.user_id=x AND cm.club_id='e14bc9f7-736d-425f-8f2c-e78305ebac1d' WHERE p.is_horse IS DISTINCT FROM true OR p.status IS DISTINCT FROM 'active' OR cm.status IS NULL OR cm.status NOT IN('active','approved') OR cm.user_id IS NULL)
  OR (SELECT count(*) FROM public.cash_games WHERE (id='56d5d6f0-23e9-41b0-b407-852aa1026c2a' AND template_name='action' AND ruleset_snapshot->>'template'='action' OR id='0cdc133d-ad23-4ace-bb85-312d0f221edd' AND template_name='madness' AND ruleset_snapshot->>'template'='madness') AND club_id='e14bc9f7-736d-425f-8f2c-e78305ebac1d')<>2 THEN
   RAISE EXCEPTION 'pilot assignment current scope changed' USING ERRCODE='55000'; END IF;
 END IF;
 UPDATE public.lightning_pilot_assignment SET active=p_active,last_request_id=p_request_id,updated_at=clock_timestamp()
 WHERE club_id='e14bc9f7-736d-425f-8f2c-e78305ebac1d';
 IF NOT FOUND THEN RAISE EXCEPTION 'pilot assignment state missing' USING ERRCODE='55000'; END IF;
 v_result:=public.fn_lightning_pilot_assignment_status()||jsonb_build_object('ok',true);
 INSERT INTO public.lightning_pilot_assignment_receipts(request_id,actor_id,active,manifest_sha256,player_ids,reason,receipt) VALUES(p_request_id,auth.uid(),p_active,p_manifest_sha256,v_players,btrim(p_reason),v_result);
 RETURN v_result;
END $$;


ALTER FUNCTION public.fn_lightning_pilot_assignment_set(p_active boolean, p_request_id uuid, p_manifest_sha256 text, p_player_ids uuid[], p_reason text) OWNER TO postgres;

--
-- TOC entry 9279 (class 1255 OID 179923886)
-- Name: fn_lightning_pilot_assignment_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_pilot_assignment_status() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF coalesce(auth.role(),'')<>'service_role' AND (auth.uid() IS DISTINCT FROM '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid OR public.fn_caller_session_is_live() IS DISTINCT FROM true) THEN
 RAISE EXCEPTION 'pilot assignment not authorized' USING ERRCODE='42501'; END IF;
 RETURN (SELECT jsonb_build_object('club_id',club_id,'active',active,'player_ids',player_ids,'manifest_sha256',manifest_sha256,'last_request_id',last_request_id,'updated_at',updated_at) FROM public.lightning_pilot_assignment);
END $$;


ALTER FUNCTION public.fn_lightning_pilot_assignment_status() OWNER TO postgres;

--
-- TOC entry 6817 (class 1255 OID 179923942)
-- Name: fn_lightning_pilot_withdraw_zero(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_pilot_withdraw_zero(p_tournament_id uuid, p_registration_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '20s'
    AS $$
DECLARE uid uuid:=auth.uid(); t public.tournaments%ROWTYPE; r public.tournament_players%ROWTYPE; c public.poker_diamond_custody%ROWTYPE; result jsonb; diamond boolean;
BEGIN
 IF uid IS NULL OR public.fn_caller_session_is_live() IS DISTINCT FROM true OR NOT(uid=ANY(public.fn_lightning_pilot_assignment_players())) THEN
 RAISE EXCEPTION 'pilot withdrawal not authorized' USING ERRCODE='42501'; END IF;
 IF p_tournament_id IS NULL OR p_registration_id IS NULL OR p_request_id IS NULL THEN
 RAISE EXCEPTION 'pilot withdrawal exact intent required' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock_shared(176217,72);
 IF NOT EXISTS(SELECT 1 FROM public.lightning_pilot_assignment WHERE active AND uid=ANY(player_ids)) THEN
 RAISE EXCEPTION 'pilot withdrawal assignment inactive' USING ERRCODE='55000'; END IF;
 PERFORM public.fn_ca_lock_mtt_admission_contract();
 PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
 SELECT * INTO t FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE;
 SELECT * INTO r FROM public.tournament_players WHERE tournament_id=p_tournament_id AND user_id=uid FOR UPDATE;
 IF r.id IS DISTINCT FROM p_registration_id OR r.status IS DISTINCT FROM 'registered' OR r.table_id IS NOT NULL OR r.seat_number IS NOT NULL THEN
 RAISE EXCEPTION 'pilot withdrawal registration identity changed' USING ERRCODE='55000'; END IF;
 IF t.id IS NULL OR t.status NOT IN('ANNOUNCED','REGISTERING') OR t.status IS NULL OR t.started_at IS NOT NULL OR t.start_time IS NULL OR clock_timestamp()>=t.start_time
 OR t.buy_in_amount IS DISTINCT FROM 0 OR t.buy_in_fee IS DISTINCT FROM 0 OR t.bounty_amount IS DISTINCT FROM 0 THEN
 RAISE EXCEPTION 'pilot withdrawal requires zero pre-start entry' USING ERRCODE='55000'; END IF;
 IF EXISTS(SELECT 1 FROM public.tables tb WHERE tb.tournament_id=p_tournament_id AND coalesce(tb.hands_dealt,0)<>0)
 OR EXISTS(SELECT 1 FROM public.hand_history h WHERE h.tournament_id=p_tournament_id)
 OR EXISTS(SELECT 1 FROM public.tables tb JOIN public.hand_history h ON h.table_id=tb.id WHERE tb.tournament_id=p_tournament_id)
 OR EXISTS(SELECT 1 FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id WHERE tb.tournament_id=p_tournament_id AND s.user_id=uid AND s.left_at IS NULL)
 OR EXISTS(SELECT 1 FROM public.wallet_transactions w WHERE w.user_id=uid AND w.related_entity_id=p_tournament_id AND w.type='debit' AND w.amount>0)
 OR EXISTS(SELECT 1 FROM public.chip_ledger l WHERE l.from_entity_id=uid AND l.tournament_id=p_tournament_id AND l.amount>0)
 OR EXISTS(SELECT 1 FROM public.tournament_participant_funding_receipts f WHERE f.user_id=uid AND f.tournament_id=p_tournament_id AND (f.amount IS DISTINCT FROM 0 OR f.registration_id IS DISTINCT FROM p_registration_id))
 OR EXISTS(SELECT 1 FROM public.tournament_refund_entitlements e WHERE e.user_id=uid AND e.tournament_id=p_tournament_id AND (e.registration_id IS DISTINCT FROM p_registration_id OR e.gross IS DISTINCT FROM 0 OR e.entitlement_kind IS DISTINCT FROM 'wallet_charge'))
 OR EXISTS(SELECT 1 FROM public.poker_diamond_tournament_ledger l WHERE l.user_id=uid AND l.tournament_id=p_tournament_id) THEN
 RAISE EXCEPTION 'pilot withdrawal existing obligation preserved' USING ERRCODE='55000'; END IF;
 diamond:=public.fn_poker_diamond_tournament(p_tournament_id);
 PERFORM 1 FROM public.poker_diamond_custody WHERE user_id=uid AND target_id=p_tournament_id AND purpose='tournament_entry' AND state<>'released' FOR UPDATE;
 IF diamond THEN
  IF (SELECT count(*) FROM public.poker_diamond_custody WHERE user_id=uid AND target_id=p_tournament_id AND purpose='tournament_entry' AND state<>'released')<>1 THEN
   RAISE EXCEPTION 'pilot withdrawal free custody missing' USING ERRCODE='55000'; END IF;
  SELECT * INTO c FROM public.poker_diamond_custody WHERE user_id=uid AND target_id=p_tournament_id AND purpose='tournament_entry' AND state<>'released';
  IF c.state IS DISTINCT FROM 'active' OR c.balance IS DISTINCT FROM 0 OR c.seat_id IS NOT NULL OR c.entry_key IS DISTINCT FROM 'entry:'||p_registration_id::text
  OR EXISTS(SELECT 1 FROM public.poker_diamond_tournament_ledger l WHERE l.custody_id=c.id) THEN
   RAISE EXCEPTION 'pilot withdrawal paid custody preserved' USING ERRCODE='55000'; END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM public.poker_diamond_custody WHERE user_id=uid AND target_id=p_tournament_id AND purpose='tournament_entry' AND state<>'released') THEN
   RAISE EXCEPTION 'pilot withdrawal unexpected custody' USING ERRCODE='55000'; END IF;
 END IF;
 -- Parent/registration locks remain held across the unchanged normal door.
 result:=public.fn_unregister_from_tournament(p_tournament_id,p_request_id);
 IF coalesce((result->>'ok')::boolean,false) IS NOT TRUE OR result->>'registration_id' IS DISTINCT FROM p_registration_id::text OR result->>'request_id' IS DISTINCT FROM p_request_id::text THEN
 RAISE EXCEPTION 'pilot withdrawal normal receipt changed' USING ERRCODE='P0404'; END IF;
 IF diamond THEN
  IF (result->>'refunded_diamonds')::numeric IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'pilot withdrawal nonzero refund' USING ERRCODE='P0404'; END IF;
 ELSE
  IF (result->>'refunded_chips')::numeric IS DISTINCT FROM 0 OR (result->>'returned_ticket_value')::numeric IS DISTINCT FROM 0 OR (result->>'fees_reversed')::numeric IS DISTINCT FROM 0 THEN
   RAISE EXCEPTION 'pilot withdrawal nonzero refund' USING ERRCODE='P0404'; END IF;
 END IF;
 RETURN result;
END $$;


ALTER FUNCTION public.fn_lightning_pilot_withdraw_zero(p_tournament_id uuid, p_registration_id uuid, p_request_id uuid) OWNER TO postgres;

--
-- TOC entry 8027 (class 1255 OID 179923935)
-- Name: fn_lightning_pilot_withdrawal_receipt(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_pilot_withdrawal_receipt(p_player_id uuid, p_tournament_id uuid, p_registration_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r jsonb;
BEGIN
 IF coalesce(auth.role(),'')<>'service_role' AND (auth.uid() IS DISTINCT FROM '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid OR public.fn_caller_session_is_live() IS DISTINCT FROM true) THEN
 RAISE EXCEPTION 'pilot assignment not authorized' USING ERRCODE='42501'; END IF;
 IF p_player_id IS NULL OR p_tournament_id IS NULL OR p_registration_id IS NULL OR p_request_id IS NULL OR NOT (p_player_id=ANY(public.fn_lightning_pilot_assignment_players())) THEN
 RAISE EXCEPTION 'pilot withdrawal receipt scope mismatch' USING ERRCODE='22023'; END IF;
 r:=public.fn_ca_tournament_unregistration_receipt(p_tournament_id,p_player_id,NULL,p_request_id);
 IF r IS NULL OR r->>'registration_id' IS DISTINCT FROM p_registration_id::text OR r->>'request_id' IS DISTINCT FROM p_request_id::text THEN RETURN NULL; END IF;
 RETURN r;
END $$;


ALTER FUNCTION public.fn_lightning_pilot_withdrawal_receipt(p_player_id uuid, p_tournament_id uuid, p_registration_id uuid, p_request_id uuid) OWNER TO postgres;

--
-- TOC entry 5163 (class 1255 OID 57591136)
-- Name: fn_lightning_player_in_hand(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_player_in_hand(p_player_id uuid, p_cluster_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM public.lightning_reservation r
      JOIN public.lightning_instance i ON i.id = r.lightning_instance_id
     WHERE r.cluster_id = p_cluster_id
       AND r.player_id = p_player_id
       AND r.state = 'committed'
       AND i.state IN ('forming', 'reserved', 'dealing', 'settling'));
$$;


ALTER FUNCTION public.fn_lightning_player_in_hand(p_player_id uuid, p_cluster_id uuid) OWNER TO postgres;

--
-- TOC entry 47928 (class 0 OID 0)
-- Dependencies: 5163
-- Name: FUNCTION fn_lightning_player_in_hand(p_player_id uuid, p_cluster_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_lightning_player_in_hand(p_player_id uuid, p_cluster_id uuid) IS 'True if and only if the player holds a committed reservation in the Cluster on an instance in forming, reserved, dealing or settling. The anchor guard refuses any change to that player''s anchor stack, departure or occupant while this is true, except by the settlement of that hand.';


--
-- TOC entry 4465 (class 1255 OID 123484676)
-- Name: fn_lightning_player_legality(uuid, timestamp with time zone, uuid[], jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_player_legality(p_cluster_id uuid, p_now timestamp with time zone, p_disconnected uuid[], p_player_platforms jsonb DEFAULT NULL::jsonb) RETURNS TABLE(player_id uuid, pool_session_id uuid, pool_slot_id uuid, legal boolean, reason_code text, detail jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- MATERIALIZED, twice: an inlined CTE substitutes its expressions into
  -- every reference, which would ask the configuration once per player and
  -- run the whole reason chain once per use of its answer.
  WITH g AS MATERIALIZED (
    SELECT cg.id AS cluster_id, cg.cluster_mode, coalesce(cg.lightning_enabled, false) AS enabled,
           cg.cluster_epoch,
           EXISTS (SELECT 1 FROM public.cash_cluster_epoch e
                    WHERE e.cluster_id = cg.id AND e.epoch = cg.cluster_epoch AND e.ended_at IS NULL) AS epoch_open,
           public.fn_platform_frozen() AS platform_frozen,
           -- THE SEAT DOOR'S GATE: fn_ca_refuse_restricted_entry refuses only
           -- when the operator policy enforces restrictions, and otherwise
           -- only observes. The matcher follows the door.
           coalesce((SELECT op.restrictions_enforced FROM public.ca_operator_policy op LIMIT 1), false) AS restrictions_enforced,
           public.fn_lightning_config(cg.id) AS lcfg
      FROM public.cash_games cg
     WHERE cg.id = p_cluster_id
  ), f AS (
    SELECT g.cluster_id, g.cluster_mode, g.enabled, g.cluster_epoch, g.epoch_open, g.platform_frozen,
           g.restrictions_enforced,
           -- LIGHTNING PHASE 8 (20261007212735), TIGHTENED BY 20261008043021:
           -- the caller names each player's platform; missing or anything
           -- else is the NARROWEST limit (mobile), so an unreported platform
           -- can never buy a wider limit than the client would enforce.
           CASE WHEN (p_player_platforms ->> ps.player_id::text) IN ('desktop', 'tablet', 'mobile')
                THEN p_player_platforms ->> ps.player_id::text ELSE 'mobile' END AS platform,
           coalesce(((g.lcfg -> 'multi_table_limit') ->> CASE WHEN (p_player_platforms ->> ps.player_id::text) IN ('desktop', 'tablet', 'mobile')
                                                    THEN p_player_platforms ->> ps.player_id::text ELSE 'mobile' END)::integer,
                    2) AS multi_table_limit,
           ps.player_id, ps.id AS pool_session_id, ps.state AS pool_state, ps.cluster_epoch AS pool_epoch,
           ps.anchor_seat_id,
           ps.stop_requested_at,
           -- LIGHTNING PHASE 13 (20261009235505): when the pool closed to
           -- newcomers, and when this session entered it.
           ps.entered_at AS pool_entered_at,
           CASE WHEN (g.lcfg ->> 'lightning_joins_enabled')::boolean IS FALSE
                THEN (g.lcfg ->> 'lightning_joins_disabled_at')::timestamptz END AS joins_closed_at,
           sl.id AS slot_id, sl.cluster_epoch AS slot_epoch, sl.pool_session_id AS slot_session_id,
           cps.id AS cash_session_id, cps.closed_at AS cash_session_closed_at,
           ts.id AS seat_id, ts.left_at AS seat_left_at, ts.user_id AS seat_user_id,
           coalesce(ts.is_sitting_out, false) AS seat_sitting_out,
           coalesce(ts.leave_pending, false) AS seat_leave_pending,
           tb.cluster_id AS seat_cluster_id, coalesce(tb.is_deleted, false) AS table_deleted,
           coalesce(tb.lifecycle, '') AS table_lifecycle
      FROM g
      JOIN public.lightning_pool_session ps
        ON ps.cluster_id = g.cluster_id AND ps.exited_at IS NULL
      LEFT JOIN public.lightning_pool_slot sl
        ON sl.cluster_id = ps.cluster_id AND sl.player_id = ps.player_id AND sl.closed_at IS NULL
      LEFT JOIN public.cash_player_session cps ON cps.id = ps.cash_player_session_id
      LEFT JOIN public.table_seats ts ON ts.id = ps.anchor_seat_id
      LEFT JOIN public.tables tb ON tb.id = ts.table_id
  ), c AS MATERIALIZED (
    SELECT f.*, CASE
        WHEN coalesce(f.cluster_mode, '') NOT IN ('lightning', 'frozen', 'paused') THEN 'CLUSTER_NOT_LIGHTNING'
        WHEN f.cluster_mode IN ('frozen', 'paused') THEN 'CLUSTER_FROZEN'
        WHEN NOT f.enabled THEN 'LIGHTNING_DISABLED'
        WHEN f.platform_frozen THEN 'PLATFORM_FROZEN'
        WHEN f.pool_epoch IS DISTINCT FROM f.cluster_epoch OR NOT f.epoch_open THEN 'WRONG_EPOCH'
        WHEN f.cash_session_id IS NULL OR f.cash_session_closed_at IS NOT NULL
             OR f.pool_state = 'closed' THEN 'SESSION_CLOSED'
        WHEN f.pool_state IN ('joining', 'eligibility_check') THEN 'POOL_SESSION_NOT_ACTIVE'
        WHEN f.pool_state = 'leaving' OR f.seat_leave_pending THEN 'CASHOUT_PENDING'
        WHEN f.seat_id IS NULL OR f.seat_left_at IS NOT NULL
             OR f.seat_user_id IS DISTINCT FROM f.player_id
             OR f.seat_cluster_id IS DISTINCT FROM f.cluster_id
             OR f.table_deleted OR f.table_lifecycle = 'closed' THEN 'ANCHOR_LEFT'
        WHEN f.pool_state = 'sit_out' OR f.seat_sitting_out THEN 'SITTING_OUT'
        WHEN coalesce(public.fn_lightning_pool_stack(f.pool_session_id), 0) <= 0 THEN 'NO_STACK'
        -- THE POPULATION'S PREDICATE HAS THE LAST WORD ON THE ANCHOR: anything
        -- it refuses that the four arms above did not name is still refused.
        WHEN NOT public.fn_lightning_anchor_is_live_eligible(f.anchor_seat_id, f.cluster_id, f.player_id) THEN 'ANCHOR_LEFT'
        WHEN f.restrictions_enforced AND public.fn_ca_player_restricted(f.player_id, 'cash') THEN 'RESTRICTED'
        WHEN (public.fn_rg_require_not_excluded(f.player_id) ->> 'ok')::boolean IS DISTINCT FROM true THEN 'RG_EXCLUDED'
        WHEN f.pool_state = 'disconnected'
             OR f.player_id = ANY (coalesce(p_disconnected, ARRAY[]::uuid[])) THEN 'DISCONNECTED'
        WHEN f.pool_state IS DISTINCT FROM 'active' THEN 'POOL_SESSION_NOT_ACTIVE'
        WHEN EXISTS (SELECT 1 FROM public.lightning_reservation r
                      WHERE r.cluster_id = f.cluster_id AND r.player_id = f.player_id
                        AND r.state IN ('pending', 'committed'))
             AND NOT public.fn_lightning_player_in_hand(f.player_id, f.cluster_id) THEN 'ALREADY_RESERVED'
        WHEN public.fn_lightning_player_in_hand(f.player_id, f.cluster_id) THEN 'IN_HAND'
        -- LIGHTNING PHASE 10 (20261008111425): a player who pressed Stop
        -- Playing is never matched into another hand. After the hand arms,
        -- so a stopper still playing reads IN_HAND until the hand lets go.
        -- LIGHTNING PHASE 13 (20261009235505): a session that entered after
        -- an operator closed joins is held; everyone already in plays on.
        WHEN f.joins_closed_at IS NOT NULL AND f.pool_entered_at >= f.joins_closed_at THEN 'LIGHTNING_JOINS_DISABLED'
        WHEN f.stop_requested_at IS NOT NULL THEN 'STOP_REQUESTED'
        WHEN f.slot_id IS NULL OR f.slot_epoch IS DISTINCT FROM f.cluster_epoch
             OR f.slot_session_id IS DISTINCT FROM f.pool_session_id THEN 'SLOT_NOT_OPEN'
        WHEN (SELECT count(DISTINCT r.cluster_id)
                FROM public.lightning_reservation r
                JOIN public.lightning_instance i ON i.id = r.lightning_instance_id
               WHERE r.player_id = f.player_id AND r.cluster_id <> f.cluster_id
                 AND r.state = 'committed'
                 AND i.state IN ('forming', 'reserved', 'dealing', 'settling')) >= f.multi_table_limit THEN 'MULTI_TABLE_LIMIT'
      END AS code
      FROM f
  )
  SELECT c.player_id, c.pool_session_id, c.slot_id,
         c.code IS NULL,
         c.code,
         jsonb_strip_nulls(jsonb_build_object(
           'cluster_mode', c.cluster_mode, 'cluster_epoch', c.cluster_epoch,
           'pool_epoch', c.pool_epoch, 'slot_epoch', c.slot_epoch, 'pool_state', c.pool_state,
           'anchor_seat_id', c.anchor_seat_id))
         || CASE c.code
              WHEN 'RG_EXCLUDED' THEN jsonb_build_object('responsible_gaming', public.fn_rg_require_not_excluded(c.player_id))
              WHEN 'RESTRICTED' THEN jsonb_build_object('restriction_scope', 'cash',
                'restriction_reason', (public.fn_ca_player_restriction_for(c.player_id, 'cash')).reason_code)
              WHEN 'MULTI_TABLE_LIMIT' THEN jsonb_build_object('multi_table_limit', c.multi_table_limit, 'platform', c.platform,
                'live_hands_elsewhere', (SELECT count(DISTINCT r.cluster_id)
                                           FROM public.lightning_reservation r
                                           JOIN public.lightning_instance i ON i.id = r.lightning_instance_id
                                          WHERE r.player_id = c.player_id AND r.cluster_id <> c.cluster_id
                                            AND r.state = 'committed'
                                            AND i.state IN ('forming', 'reserved', 'dealing', 'settling')))
              WHEN 'LIGHTNING_JOINS_DISABLED' THEN jsonb_build_object('joins_disabled_at', c.joins_closed_at)
              WHEN 'STOP_REQUESTED' THEN jsonb_build_object('stop_requested_at', c.stop_requested_at)
              WHEN 'DISCONNECTED' THEN jsonb_build_object('reported_disconnected',
                c.player_id = ANY (coalesce(p_disconnected, ARRAY[]::uuid[])))
              ELSE '{}'::jsonb
            END
    FROM c
   ORDER BY c.player_id;
$$;


