-- Name: FUNCTION fn_lightning_player_legality(p_cluster_id uuid, p_now timestamp with time zone, p_disconnected uuid[], p_player_platforms jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_lightning_player_legality(p_cluster_id uuid, p_now timestamp with time zone, p_disconnected uuid[], p_player_platforms jsonb) IS 'Matcher P0. One row per open Lightning pool session of the Cluster with exactly one first-failing reason_code from one ordered CASE (NULL when legal): CLUSTER_NOT_LIGHTNING, CLUSTER_FROZEN, LIGHTNING_DISABLED, PLATFORM_FROZEN, WRONG_EPOCH, SESSION_CLOSED, POOL_SESSION_NOT_ACTIVE, CASHOUT_PENDING, ANCHOR_LEFT, SITTING_OUT, NO_STACK, RESTRICTED, RG_EXCLUDED, DISCONNECTED, ALREADY_RESERVED, IN_HAND, SLOT_NOT_OPEN, MULTI_TABLE_LIMIT. Reuses fn_lightning_anchor_is_live_eligible, fn_lightning_pool_stack, fn_lightning_player_in_hand, fn_platform_frozen, fn_ca_player_restricted (gated by ca_operator_policy.restrictions_enforced as the seat door gates it) and fn_rg_require_not_excluded.';


--
-- TOC entry 4594 (class 1255 OID 82348937)
-- Name: fn_lightning_player_live_hand(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_player_live_hand(p_player_id uuid, p_cluster_id uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT x.hand
    FROM (SELECT coalesce(i.hand_id, i.id) AS hand, i.created_at, i.id
            FROM public.lightning_reservation r
            JOIN public.lightning_instance i ON i.id = r.lightning_instance_id
           WHERE r.cluster_id = p_cluster_id AND r.player_id = p_player_id AND r.state = 'committed'
             AND i.state IN ('forming', 'reserved', 'dealing', 'settling')
          UNION ALL
          SELECT i.hand_id, i.created_at, i.id
            FROM public.lightning_instance i
            JOIN public.lightning_hand_player hp ON hp.hand_id = i.hand_id AND hp.player_id = p_player_id
           WHERE i.cluster_id = p_cluster_id
             AND i.state IN ('forming', 'reserved', 'dealing', 'settling')) x
   ORDER BY x.created_at DESC, x.id
   LIMIT 1;
$$;


