--
-- TOC entry 47934 (class 0 OID 0)
-- Dependencies: 9049
-- Name: FUNCTION fn_lightning_pool_enter(p_seat_id uuid, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_lightning_pool_enter(p_seat_id uuid, p_now timestamp with time zone) IS 'Enters the player on an eligible seat of a lightning-mode Cluster into its pool at the current epoch: a pool session anchored to that seat (starting_stack = the seat stack, under the player''s existing open cash session) and its slot, recording pool_player_joined. Returns the player''s existing open pool session instead when there is one. NULL when the seat does not belong in the pool. Fired from the table_seats constraint triggers and callable by service_role.';


--
-- TOC entry 5340 (class 1255 OID 147112375)
-- Name: fn_lightning_pool_enter_seated(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_pool_enter_seated(p_cluster_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  s   record;
  v_n integer := 0;
BEGIN
  PERFORM 1 FROM public.table_seats ts
   WHERE ts.left_at IS NULL
     AND ts.table_id IN (SELECT tb.id FROM public.tables tb WHERE tb.cluster_id = p_cluster_id)
   ORDER BY ts.id
     FOR SHARE;
  FOR s IN
    SELECT DISTINCT ON (ts.user_id) ts.id, ts.user_id
      FROM public.table_seats ts
      JOIN public.tables tb ON tb.id = ts.table_id
     WHERE tb.cluster_id = p_cluster_id AND ts.left_at IS NULL AND ts.user_id IS NOT NULL
       AND public.fn_lightning_anchor_is_live_eligible(ts.id, p_cluster_id, ts.user_id)
       AND NOT EXISTS (SELECT 1 FROM public.lightning_pool_session ps
                        WHERE ps.cluster_id = p_cluster_id AND ps.player_id = ts.user_id
                          AND ps.exited_at IS NULL)
     ORDER BY ts.user_id, ts.joined_at, ts.id
  LOOP
    IF public.fn_lightning_pool_enter(s.id, clock_timestamp()) IS NOT NULL THEN
      v_n := v_n + 1;
    END IF;
  END LOOP;
  RETURN v_n;
END
$$;


