--
-- TOC entry 8497 (class 1255 OID 82348929)
-- Name: fn_lightning_pool_exposure(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_pool_exposure(p_player_id uuid, p_cluster_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
-- THE EXPOSURE READER KEEPS ITS PLAN (2026-10-09, Phase 12 load and chaos):
-- the same query and the same answer, in PL/pgSQL, whose statement plan is
-- cached for the session. As a SQL function with a pinned search_path it
-- could not be inlined and was planned again on every call (0.7 ms of
-- planning for 0.1 ms of execution), and legality calls it once per open
-- player on every pass.
BEGIN
  RETURN (
  SELECT coalesce(sum(coalesce(hp.committed_at_fold, hp.stack_before, 0)), 0)::numeric
    FROM public.lightning_instance i
    JOIN public.lightning_hand_player hp ON hp.hand_id = i.hand_id AND hp.player_id = p_player_id
   WHERE i.cluster_id = p_cluster_id
     AND i.state IN ('forming', 'reserved', 'dealing', 'settling')
     AND hp.folded_at IS NOT NULL
     AND hp.fold_type IN ('fast', 'normal'));
END
$$;


