--
-- TOC entry 8717 (class 1255 OID 57693107)
-- Name: fn_lightning_pool_slot_idle_since_starts_at_open(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_pool_slot_idle_since_starts_at_open() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- A column default cannot name another column, so the default is here: a
  -- slot is idle from the moment it opens unless its writer says later.
  NEW.idle_since := GREATEST(coalesce(NEW.idle_since, NEW.opened_at), NEW.opened_at);
  RETURN NEW;
END
$$;


