--
-- TOC entry 3798 (class 1255 OID 56835324)
-- Name: fn_lightning_pool_slot_open(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_pool_slot_open(p_pool_session_id uuid, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  ps      record;
  v_slot  uuid;
  v_closed integer := 0;
BEGIN
  IF public.fn_platform_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'opened', false, 'reason', 'platform_frozen');
  END IF;

  SELECT s.id, s.cluster_id, s.cluster_epoch, s.player_id, s.state, s.exited_at
    INTO ps FROM public.lightning_pool_session s WHERE s.id = p_pool_session_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'opened', false, 'reason', 'no_such_pool_session');
  END IF;
  IF ps.exited_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'opened', false, 'reason', 'pool_session_has_exited');
  END IF;

  -- IDEMPOTENT ON PURPOSE. This is called from a sync pass that may run twice
  -- in the same second, from two workers, during a deploy. An existing open
  -- slot is the right answer, not a unique violation.
  -- A SESSION FROM A DEAD EPOCH OPENS NOTHING (2026-09-26). The sync pass only
  -- offers sessions at the Cluster's current epoch, but this is callable on its
  -- own, and a slot at a dead epoch is one the barrier can never use and the
  -- one-open-per-player index will not let the player replace.
  IF ps.cluster_epoch IS DISTINCT FROM
     (SELECT g.cluster_epoch FROM public.cash_games g WHERE g.id = ps.cluster_id) THEN
    RETURN jsonb_build_object('ok', false, 'opened', false,
                              'reason', 'pool_session_epoch_is_not_current',
                              'pool_session_epoch', ps.cluster_epoch);
  END IF;

  -- IDEMPOTENT ON THE POOL SESSION (2026-09-26), not on the player. The read
  -- used to be keyed on (Cluster, player, open), so a player who left and came
  -- back - a new pool session - was answered already_open with the slot of the
  -- session that had exited, and one who survived an epoch bump with a slot
  -- at the dead epoch.
  SELECT sl.id INTO v_slot FROM public.lightning_pool_slot sl
   WHERE sl.cluster_id = ps.cluster_id AND sl.player_id = ps.player_id
     AND sl.closed_at IS NULL
     AND sl.pool_session_id = ps.id AND sl.cluster_epoch = ps.cluster_epoch;
  IF FOUND THEN
    RETURN jsonb_build_object('ok', true, 'opened', false, 'reason', 'already_open',
                              'pool_slot_id', v_slot);
  END IF;

  -- ANY OTHER OPEN SLOT OF THIS PLAYER IN THIS CLUSTER IS STALE, and is closed
  -- here, in this call, rather than left for a sync pass: it is bound to a
  -- session that has gone or an epoch that has ended, and while it stays open
  -- lightning_pool_slot_one_open_per_player refuses the slot this player
  -- actually needs. A hand in flight that sat in it is untouched - the hand
  -- names the slot by id, and the player's committed reservation still bars a
  -- second hand until that one ends.
  UPDATE public.lightning_pool_slot sl
     SET closed_at = GREATEST(p_now, sl.opened_at),
         close_reason = CASE WHEN sl.cluster_epoch IS DISTINCT FROM ps.cluster_epoch
                             THEN 'epoch_advanced' ELSE 'superseded_by_pool_session' END,
         updated_at = p_now
   WHERE sl.cluster_id = ps.cluster_id AND sl.player_id = ps.player_id
     AND sl.closed_at IS NULL;
  GET DIAGNOSTICS v_closed = ROW_COUNT;

  -- slot 1, ALWAYS, and the header says why: lightning_pool_slot.slot ranges
  -- 1..24 because the pool was designed for a player to hold several
  -- concurrent seats, and specification 725 forbids a player holding more than
  -- one active reservation in a session. The column keeps its range so that
  -- the day the specification changes, only an index moves.
  INSERT INTO public.lightning_pool_slot
    (pool_session_id, cluster_id, cluster_epoch, player_id, slot, opened_at, updated_at)
  VALUES (ps.id, ps.cluster_id, ps.cluster_epoch, ps.player_id, 1, p_now, p_now)
  RETURNING id INTO v_slot;

  RETURN jsonb_build_object('ok', true, 'opened', true, 'pool_slot_id', v_slot,
                            'player_id', ps.player_id, 'cluster_id', ps.cluster_id,
                            'cluster_epoch', ps.cluster_epoch,
                            'stale_slots_closed', v_closed);
END
$$;


ALTER FUNCTION public.fn_lightning_pool_slot_open(p_pool_session_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 7902 (class 1255 OID 56835325)
-- Name: fn_lightning_pool_slots_sync(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_pool_slots_sync(p_cluster_id uuid, p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g        record;
  s        record;
  v_closed integer := 0;
  v_opened integer := 0;
  v_frozen boolean := public.fn_platform_frozen();
  v_deferred boolean := false;
  v_deadline timestamptz := nullif(current_setting('ca.cluster_pass_deadline', true), '')::timestamptz;
BEGIN
  -- THE CLUSTER ROW FIRST, IN FORMATION'S OWN MODE, AND WITHOUT WAITING
  -- (2026-09-26). A Cluster whose row is held - a formation in flight - is
  -- skipped this pass and taken the next; the pass is never parked behind it.
  SELECT id, cluster_mode, lightning_enabled, cluster_epoch
    INTO g FROM public.cash_games WHERE id = p_cluster_id
     FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN
    IF EXISTS (SELECT 1 FROM public.cash_games WHERE id = p_cluster_id) THEN
      RETURN jsonb_build_object('ok', true, 'reason', 'cluster_busy', 'skipped', true,
                                'slots_closed', 0, 'slots_opened', 0);
    END IF;
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;

  -- THE CLOSING HALF IS NOT GATED ON THE FREEZE. A slot belonging to somebody
  -- who has left the pool, or to an epoch the Cluster is no longer in, is a
  -- standing claim on a player who is not there, and giving it back is
  -- recovery. Phase 5 makes the same distinction between commit and abort.
  UPDATE public.lightning_pool_slot sl
     SET closed_at = GREATEST(p_now, sl.opened_at),
         close_reason = CASE WHEN sl.cluster_epoch IS DISTINCT FROM g.cluster_epoch
                             THEN 'epoch_advanced' ELSE 'pool_session_exited' END,
         updated_at = p_now
   WHERE sl.cluster_id = g.id
     AND sl.closed_at IS NULL
     AND (sl.cluster_epoch IS DISTINCT FROM g.cluster_epoch
          OR EXISTS (SELECT 1 FROM public.lightning_pool_session ps
                      WHERE ps.id = sl.pool_session_id AND ps.exited_at IS NOT NULL));
  GET DIAGNOSTICS v_closed = ROW_COUNT;

  IF v_frozen THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'platform_frozen',
                              'slots_closed', v_closed, 'slots_opened', 0);
  END IF;

  IF g.cluster_mode IS DISTINCT FROM 'lightning' OR coalesce(g.lightning_enabled, false) = false THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'cluster_is_not_lightning',
                              'cluster_mode', g.cluster_mode,
                              'slots_closed', v_closed, 'slots_opened', 0);
  END IF;

  -- NO is_horse. Law 10.5: a horse enters the pool, takes a slot, is reserved
  -- and is dealt exactly as a human is, and P0's legality list has no carve-out
  -- for one.
  FOR s IN
    SELECT ps.id FROM public.lightning_pool_session ps
     WHERE ps.cluster_id = g.id AND ps.cluster_epoch = g.cluster_epoch
       AND ps.exited_at IS NULL AND ps.state = 'active'
       AND NOT EXISTS (SELECT 1 FROM public.lightning_pool_slot sl
                        WHERE sl.cluster_id = ps.cluster_id AND sl.player_id = ps.player_id
                          AND sl.closed_at IS NULL)
     ORDER BY ps.entered_at, ps.id
  LOOP
    -- THE PASS BUDGET (2026-09-26). fn_cash_clusters_tick_all sets
    -- ca.cluster_pass_deadline; past it, the rest of this Cluster's slots are
    -- left for the next pass rather than stretching this one.
    IF v_deadline IS NOT NULL AND clock_timestamp() > v_deadline THEN
      v_deferred := true;
      EXIT;
    END IF;
    IF coalesce((public.fn_lightning_pool_slot_open(s.id, p_now) ->> 'opened')::boolean, false) THEN
      v_opened := v_opened + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'reason', 'synced',
                            'cluster_epoch', g.cluster_epoch,
                            'slots_closed', v_closed, 'slots_opened', v_opened,
                            'deferred', v_deferred);
END
$$;


ALTER FUNCTION public.fn_lightning_pool_slots_sync(p_cluster_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 4327 (class 1255 OID 56835322)
-- Name: fn_lightning_pool_stack(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_pool_stack(p_pool_session_id uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN ts.id IS NULL
                OR ts.left_at IS NOT NULL
                OR ts.user_id IS DISTINCT FROM s.player_id THEN 0::numeric
              ELSE GREATEST(round(coalesce(ts.stack, 0), 2) - public.fn_lightning_pool_exposure(s.player_id, s.cluster_id), 0::numeric) END
    FROM public.lightning_pool_session s
    LEFT JOIN public.table_seats ts ON ts.id = s.anchor_seat_id
   WHERE s.id = p_pool_session_id;
$$;


ALTER FUNCTION public.fn_lightning_pool_stack(p_pool_session_id uuid) OWNER TO postgres;

--
-- TOC entry 47945 (class 0 OID 0)
-- Dependencies: 4327
-- Name: FUNCTION fn_lightning_pool_stack(p_pool_session_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_lightning_pool_stack(p_pool_session_id uuid) IS 'The stack of a pool session is the stack of its anchor seat: table_seats.stack, or 0 once the anchor has left or turned over. starting_stack is a snapshot and net_result a statistic; neither is read here. Formation snapshots this into lightning_hand_player.stack_before under a FOR SHARE lock on the anchor seat.';


--
-- TOC entry 7072 (class 1255 OID 123484739)
-- Name: fn_lightning_pool_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_pool_status(p_cluster_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid     uuid := auth.uid();
  v_service boolean := coalesce(auth.role(), '') = 'service_role';
  g         record;
  v_health  jsonb;
  v_cfg     jsonb;
  v_live    integer;
  v_status  text;
  v_ar_used  integer;
  v_ar_total numeric;
BEGIN
  IF p_cluster_id IS NULL OR (v_uid IS NULL AND NOT v_service) THEN
    RETURN NULL;
  END IF;
  -- THE LOBBY'S OWN RULE (policy cash_games_read): visible unless the
  -- ruleset marks it private, and a private Cluster to members of its club.
  SELECT cg.id, cg.cluster_mode, cg.enabled, cg.lightning_enabled INTO g
    FROM public.cash_games cg
   WHERE cg.id = p_cluster_id
     AND (v_service
          OR (NOT coalesce(((cg.ruleset_snapshot -> 'options') ->> 'is_private')::boolean, false)
              AND NOT EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = cg.club_id AND c.is_public = false))
          OR EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = cg.club_id AND c.owner_id = v_uid)
          OR EXISTS (SELECT 1 FROM public.club_members cm
                      WHERE cm.club_id = cg.club_id AND cm.user_id = v_uid
                        AND cm.status IN ('active', 'approved')));
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  v_health := public.fn_cash_cluster_pool_health(p_cluster_id, clock_timestamp());
  v_live := CASE WHEN coalesce((v_health ->> 'ok')::boolean, false)
                 THEN coalesce((v_health ->> 'live_eligible')::integer, 0) ELSE 0 END;
  v_cfg := public.fn_lightning_config(p_cluster_id);
  v_status := CASE
    WHEN g.cluster_mode = 'pending_off' THEN 'THIN'
    WHEN g.cluster_mode IS DISTINCT FROM 'lightning' THEN 'BUILDING'
    WHEN v_live >= (v_cfg ->> 'diversity_large_min')::integer THEN 'HOT'
    WHEN v_live >= (v_cfg ->> 'diversity_medium_min')::integer THEN 'ACTIVE'
    ELSE 'THIN' END;
  -- 20261008043021: THE CLIENT CONTRACT IS {players, status, joinable,
  -- multi_table_limit}. cluster_mode leaked frozen, paused and the pending
  -- states to players; the lobby-facing facts are whether the pool can be
  -- entered right now and the per-platform limits the entry door enforces.
  -- LIGHTNING PHASE 12 (20261009143757): THE AUTO-REBUY STATUS LINE. The
  -- client cannot read fn_lightning_config (service_role only, and it stays
  -- so); this door already reads it as its owner, so the settings come from
  -- there (its clamps, its validation) and the usage from the CALLER'S OWN
  -- open pool session in this Cluster, null without one.
  SELECT ps.auto_rebuys, ps.auto_rebuy_total INTO v_ar_used, v_ar_total
    FROM public.lightning_pool_session ps
   WHERE ps.cluster_id = g.id AND ps.player_id = v_uid AND ps.exited_at IS NULL
   ORDER BY ps.entered_at DESC, ps.id
   LIMIT 1;
  RETURN jsonb_build_object('players', v_live, 'status', v_status,
    'joinable', (g.cluster_mode = 'lightning' AND coalesce(g.lightning_enabled, false) AND g.enabled IS TRUE
                 AND coalesce((v_cfg ->> 'lightning_joins_enabled')::boolean, true)),
    -- LIGHTNING PHASE 13 (20261009235505): the pool closed to newcomers by an
    -- operator, and Lightning ending (an emergency drain in flight).
    'joins_enabled', coalesce((v_cfg ->> 'lightning_joins_enabled')::boolean, true),
    'draining', (g.cluster_mode = 'draining'
                 OR EXISTS (SELECT 1 FROM public.lightning_cluster_drain d
                             WHERE d.cluster_id = g.id AND d.completed_at IS NULL)),
    'multi_table_limit', v_cfg -> 'multi_table_limit',
    'auto_rebuy', jsonb_build_object(
      'enabled', v_cfg -> 'auto_rebuy_enabled',
      'trigger', v_cfg -> 'auto_rebuy_trigger',
      'threshold_bb', v_cfg -> 'auto_rebuy_threshold_bb',
      'threshold_pct', v_cfg -> 'auto_rebuy_threshold_pct',
      'target', v_cfg -> 'auto_rebuy_target',
      'max_count', v_cfg -> 'auto_rebuy_max_count',
      'session_cap', v_cfg -> 'auto_rebuy_session_cap',
      'used_count', to_jsonb(v_ar_used),
      'used_total', to_jsonb(v_ar_total)));
END
$$;


ALTER FUNCTION public.fn_lightning_pool_status(p_cluster_id uuid) OWNER TO postgres;

--
-- TOC entry 47947 (class 0 OID 0)
-- Dependencies: 7072
-- Name: FUNCTION fn_lightning_pool_status(p_cluster_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_lightning_pool_status(p_cluster_id uuid) IS 'Lightning Phase 8, contract tightened by 20261008043021, auto_rebuy added by 20261009143757. Player-facing pool status {players, status, joinable, multi_table_limit, auto_rebuy}: players is the live eligible count; status is lightning at or above the large diversity band HOT, at or above the medium band ACTIVE, below it or pending_off THIN, every other mode BUILDING; joinable is true only for an enabled Lightning Cluster in lightning mode; multi_table_limit is the configured {desktop, tablet, mobile} object the client entry door enforces; auto_rebuy is {enabled, trigger, threshold_bb, threshold_pct, target, max_count, session_cap} exactly as fn_lightning_config answers them plus {used_count, used_total} from the caller''s own open pool session in this Cluster (null without one). Never the raw cluster_mode. Visible to whoever the lobby policy cash_games_read shows the Cluster to.';


--
-- TOC entry 7498 (class 1255 OID 125520301)
-- Name: fn_lightning_presence_report(uuid, uuid[], uuid[], timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_presence_report(p_cluster_id uuid, p_disconnected uuid[], p_reconnected uuid[], p_now timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  g        record;
  v_now    timestamp with time zone;
  v_down   jsonb;
  v_up     jsonb;
BEGIN
  -- NEVER STAMP BY A CLOCK THAT HAS NOT ARRIVED: a future p_now would age the
  -- disconnect toward expiry before it happened (the reapers' rule).
  v_now := LEAST(coalesce(p_now, clock_timestamp()), clock_timestamp());

  SELECT cg.id, cg.cluster_epoch INTO g FROM public.cash_games cg WHERE cg.id = p_cluster_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found', 'cluster_id', p_cluster_id);
  END IF;

  -- THE DISCONNECTS. Only an unstamped open session changes, so the original
  -- stamp stands however often the engine repeats itself. Only 'active'
  -- becomes 'disconnected': sit_out, joining, eligibility_check and leaving
  -- keep their own state (P0 refuses each with its own reason already) and
  -- carry the stamp for the reaper and the record.
  WITH stamped AS (
    UPDATE public.lightning_pool_session s
       SET disconnected_at = coalesce(s.disconnected_at, v_now),
           state = CASE WHEN s.state = 'active' THEN 'disconnected' ELSE s.state END,
           updated_at = v_now
     WHERE s.cluster_id = g.id AND s.exited_at IS NULL
       AND s.disconnected_at IS NULL
       AND s.player_id = ANY (coalesce(p_disconnected, ARRAY[]::uuid[]))
       AND NOT (s.player_id = ANY (coalesce(p_reconnected, ARRAY[]::uuid[])))
    RETURNING s.id, s.player_id
  )
  SELECT jsonb_agg(jsonb_build_object('player_id', st.player_id, 'pool_session_id', st.id)
                   ORDER BY st.player_id)
    INTO v_down FROM stamped st;

  IF v_down IS NOT NULL THEN
    INSERT INTO public.cash_cluster_events (game_id, kind, payload, cluster_epoch)
    VALUES (g.id, 'player_disconnected', jsonb_build_object(
      'cluster_id', g.id, 'cluster_epoch', g.cluster_epoch,
      'players', v_down, 'at', v_now), g.cluster_epoch);
  END IF;

  -- THE RECONNECTS. Only a stamped open session changes; 'disconnected'
  -- returns to 'active', any other state keeps itself and just loses the
  -- stamp. An expired session is exited already and is NOT revived here: the
  -- player rejoins through the seat door like anybody else.
  WITH cleared AS (
    UPDATE public.lightning_pool_session s
       SET disconnected_at = NULL,
           state = CASE WHEN s.state = 'disconnected' THEN 'active' ELSE s.state END,
           updated_at = v_now
     WHERE s.cluster_id = g.id AND s.exited_at IS NULL
       AND s.disconnected_at IS NOT NULL
       AND s.player_id = ANY (coalesce(p_reconnected, ARRAY[]::uuid[]))
    RETURNING s.id, s.player_id
  )
  SELECT jsonb_agg(jsonb_build_object('player_id', cl.player_id, 'pool_session_id', cl.id)
                   ORDER BY cl.player_id)
    INTO v_up FROM cleared cl;

  IF v_up IS NOT NULL THEN
    INSERT INTO public.cash_cluster_events (game_id, kind, payload, cluster_epoch)
    VALUES (g.id, 'player_reconnected', jsonb_build_object(
      'cluster_id', g.id, 'cluster_epoch', g.cluster_epoch,
      'players', v_up, 'at', v_now), g.cluster_epoch);
  END IF;

  RETURN jsonb_build_object('ok', true, 'cluster_id', g.id, 'cluster_epoch', g.cluster_epoch,
    'disconnected', coalesce(v_down, '[]'::jsonb), 'reconnected', coalesce(v_up, '[]'::jsonb));
END
$$;


