-- Name: FUNCTION fn_lightning_quality_components(p_metrics jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_lightning_quality_components(p_metrics jsonb) IS 'Lightning Phase 11 (20261008161509): the six 0..1 components of the internal Lightning Quality Score, read from one side of a shadow comparison in the engine''s shape (wait_ms, formation_success_rate, bb_fairness, opponent_diversity, instance_occupancy, failure_rate); NULL where the input is absent. service_role only.';


--
-- TOC entry 8718 (class 1255 OID 130340133)
-- Name: fn_lightning_quality_score(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_quality_score(p_metrics jsonb, p_weights jsonb DEFAULT NULL::jsonb) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  w      jsonb := coalesce(p_weights, public.fn_lightning_config(NULL) -> 'quality_weights');
  c      jsonb := public.fn_lightning_quality_components(p_metrics);
  e      record;
  v_num  numeric := 0;
  v_den  numeric := 0;
  v_c    numeric;
  v_w    numeric;
BEGIN
  IF c IS NULL OR w IS NULL OR jsonb_typeof(w) IS DISTINCT FROM 'object' THEN
    RETURN NULL;
  END IF;
  FOR e IN SELECT x.key, x.value FROM jsonb_each(w) x LOOP
    CONTINUE WHEN jsonb_typeof(e.value) IS DISTINCT FROM 'number';
    v_w := (e.value #>> '{}')::numeric;
    CONTINUE WHEN v_w <= 0;
    v_c := (c ->> e.key)::numeric;
    CONTINUE WHEN v_c IS NULL;
    v_num := v_num + v_w * v_c;
    v_den := v_den + v_w;
  END LOOP;
  IF v_den = 0 THEN
    RETURN NULL;
  END IF;
  RETURN round(100 * v_num / v_den, 2);
END
$$;


