--

COMMENT ON FUNCTION public.fn_lightning_quality_score(p_metrics jsonb, p_weights jsonb) IS 'Lightning Phase 11 (20261008161509): the internal Lightning Quality Score, 0..100 - the weighted mean of the present fn_lightning_quality_components (next_hand_speed, formation_success, bb_fairness, opponent_diversity, instance_utilization, reliability), weights from fn_lightning_config quality_weights unless given. Compares matcher versions; never exposed to players. service_role only.';


--
-- TOC entry 4945 (class 1255 OID 125520319)
-- Name: fn_lightning_reap_expired_disconnects(uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_reap_expired_disconnects(p_cluster_id uuid DEFAULT NULL::uuid, p_now timestamp with time zone DEFAULT clock_timestamp(), p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  s          record;
  v_exited   integer := 0;
  v_rows     jsonb := '[]'::jsonb;
  v_skipped  jsonb := '[]'::jsonb;
  v_errors   jsonb := '[]'::jsonb;
  v_expired  jsonb;
  v_seat     record;
  v_stack    numeric;
  v_sqlstate text;
  v_message  text;
  c          record;
BEGIN
  -- NEVER REAP BY A CLOCK THAT HAS NOT ARRIVED (the formation reaper's rule):
  -- a future p_now would expire a disconnect that has not yet stood its time.
  p_now := LEAST(coalesce(p_now, clock_timestamp()), clock_timestamp());

  FOR s IN
    SELECT ps.id, ps.cluster_id, ps.cluster_epoch, ps.player_id, ps.anchor_seat_id,
           ps.disconnected_at, ps.stop_requested_at, cfg.timeout_ms, rg.refused AS rg_refused
      FROM public.lightning_pool_session ps
      JOIN LATERAL (SELECT (public.fn_lightning_config(ps.cluster_id) ->> 'disconnect_timeout_ms')::integer
                      AS timeout_ms) cfg ON true
      -- LIGHTNING PHASE 12 (20261009143757): RESPONSIBLE GAMING ENDS THE
      -- SESSION, NOT ONLY THE NEXT DEAL. The SAME helper every Lightning door
      -- consults (fn_rg_require_not_excluded: self-exclusion, cooling-off);
      -- the EXISTS on its own primary key only spares the call for a player
      -- with no limits row, whom the helper answers ok by construction.
      JOIN LATERAL (SELECT EXISTS (SELECT 1 FROM public.responsible_gaming_limits rgl
                                    WHERE rgl.user_id = ps.player_id)
                           AND (public.fn_rg_require_not_excluded(ps.player_id) ->> 'ok')::boolean IS DISTINCT FROM true
                      AS refused) rg ON true
     WHERE ps.exited_at IS NULL
       AND (p_cluster_id IS NULL OR ps.cluster_id = p_cluster_id)
       -- LIGHTNING PHASE 9 REMEDIATION (20261008142857), FINDING 6: A FROZEN
       -- CLUSTER IS EVIDENCE. cluster_mode 'frozen'
       -- (fn_lightning_settlement_freeze) marks a Cluster under forensic
       -- investigation, and its pool-session rows are not mutated here: not
       -- a timed-out disconnect, and not a standing Stop Playing request
       -- either - an idle stopper waits out the freeze (consistency beats
       -- speed). fn_cash_cluster_unfreeze owns the frozen Cluster's recovery
       -- and exits its sessions itself ('cluster_unfrozen'); a Cluster
       -- thawed any other way is reaped on the next pass. The formation
       -- reaper's "recovery during the break" doctrine covers buried
       -- instances, never session exits.
       AND NOT EXISTS (SELECT 1 FROM public.cash_games fz
                        WHERE fz.id = ps.cluster_id AND fz.cluster_mode = 'frozen')
       -- LIGHTNING PHASE 10 (20261008111425): the worklist is a disconnect
       -- past its timeout OR a standing Stop Playing request, which owes
       -- nobody a timeout - it exits the moment the hand lets go.
       AND ((ps.disconnected_at IS NOT NULL
             AND ps.disconnected_at + make_interval(secs => cfg.timeout_ms / 1000.0) <= p_now)
            OR ps.stop_requested_at IS NOT NULL
            -- LIGHTNING PHASE 12: a player responsible gaming refuses is
            -- finished like a stopper, the moment the hand lets go.
            OR rg.refused)
     ORDER BY coalesce(LEAST(coalesce(ps.disconnected_at, ps.stop_requested_at),
                             coalesce(ps.stop_requested_at, ps.disconnected_at)), ps.entered_at), ps.id
     -- FINDING 3 (20261008142857): an upper clamp too - one pass can never
     -- lock more than 2000 sessions however large p_limit comes in.
     LIMIT LEAST(GREATEST(1, coalesce(p_limit, 200)), 2000)
       FOR UPDATE OF ps SKIP LOCKED
  LOOP
    BEGIN
      -- RELEASE NOTHING IN-HAND. A player in a live hand - or holding any
      -- live reservation on the way into one - is never expired here: the
      -- hand's own clock, fold rules and settlement own them, and the
      -- formation reaper owns a reservation nothing vouches for. The next
      -- pass expires them once the hand lets go.
      IF public.fn_lightning_player_in_hand(s.player_id, s.cluster_id)
         OR EXISTS (SELECT 1 FROM public.lightning_reservation r
                     WHERE r.cluster_id = s.cluster_id AND r.player_id = s.player_id
                       AND r.state IN ('pending', 'committed')) THEN
        v_skipped := v_skipped || jsonb_build_object(
          'pool_session_id', s.id, 'cluster_id', s.cluster_id, 'player_id', s.player_id,
          'reason', 'in_hand_or_reserved');
        CONTINUE;
      END IF;

      UPDATE public.lightning_pool_session ps
         SET exited_at = GREATEST(p_now, ps.entered_at),
             exit_reason = CASE WHEN s.stop_requested_at IS NOT NULL THEN 'stop_playing'
                                WHEN s.rg_refused THEN 'rg_limit'
                                ELSE 'disconnect_expired' END,
             state = 'closed',
             ending_stack = public.fn_lightning_pool_stack(ps.id),
             updated_at = p_now
       WHERE ps.id = s.id AND ps.exited_at IS NULL
      RETURNING ps.ending_stack INTO v_stack;
      IF NOT FOUND THEN
        CONTINUE;
      END IF;

      UPDATE public.lightning_pool_slot sl
         SET closed_at = GREATEST(p_now, sl.opened_at),
             close_reason = 'pool_session_exited',
             updated_at = p_now
       WHERE sl.pool_session_id = s.id AND sl.closed_at IS NULL;

      SELECT ts.table_id INTO v_seat FROM public.table_seats ts WHERE ts.id = s.anchor_seat_id;

      -- EVERY EXIT PATH SAYS pool_player_left, this one included, in the
      -- anchor-seat trigger's own payload shape.
      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload, cluster_epoch)
      VALUES (s.cluster_id, v_seat.table_id, 'pool_player_left', jsonb_build_object(
        'cluster_id', s.cluster_id, 'cluster_epoch', s.cluster_epoch, 'player_id', s.player_id,
        'pool_session_id', s.id, 'anchor_seat_id', s.anchor_seat_id,
        'reason', CASE WHEN s.stop_requested_at IS NOT NULL THEN 'stop_playing'
                       WHEN s.rg_refused THEN 'rg_limit'
                       ELSE 'disconnect_expired' END,
        'ending_stack', v_stack, 'at', p_now), s.cluster_epoch);

      v_exited := v_exited + 1;
      v_rows := v_rows || jsonb_build_object(
        'pool_session_id', s.id, 'cluster_id', s.cluster_id, 'cluster_epoch', s.cluster_epoch,
        'player_id', s.player_id, 'disconnected_at', s.disconnected_at,
        'stopped', s.stop_requested_at IS NOT NULL,
        'rg_limit', s.stop_requested_at IS NULL AND coalesce(s.rg_refused, false),
        'timeout_ms', s.timeout_ms);
    EXCEPTION WHEN OTHERS THEN
      -- PER-ITEM ISOLATION: one session's failure is a row, not the reap's.
      GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      v_errors := v_errors || jsonb_build_object(
        'pool_session_id', s.id, 'cluster_id', s.cluster_id, 'player_id', s.player_id,
        'sqlstate', v_sqlstate, 'message', v_message);
    END;
  END LOOP;

  -- ONE player_expired EVENT PER CLUSTER PER CALL, carrying that Cluster's
  -- expired players, after the loop so an isolated failure cannot double it.
  FOR c IN
    SELECT (x ->> 'cluster_id')::uuid AS cluster_id,
           max((x ->> 'cluster_epoch')::integer) AS cluster_epoch,
           jsonb_agg(x - 'cluster_id' - 'cluster_epoch' - 'stopped' - 'rg_limit' ORDER BY x ->> 'player_id') AS players
      FROM jsonb_array_elements(v_rows) x
     -- A stopped session left of its own will is not an expired disconnect.
     WHERE (x ->> 'stopped')::boolean IS NOT TRUE
     -- Nor is a session responsible gaming ended (Phase 12).
       AND (x ->> 'rg_limit')::boolean IS NOT TRUE
     GROUP BY 1
  LOOP
    v_expired := c.players;
    INSERT INTO public.cash_cluster_events (game_id, kind, payload, cluster_epoch)
    VALUES (c.cluster_id, 'player_expired', jsonb_build_object(
      'cluster_id', c.cluster_id, 'cluster_epoch', c.cluster_epoch,
      'players', v_expired, 'at', p_now), c.cluster_epoch);
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'expired', v_exited,
    'rows', v_rows, 'skipped', v_skipped, 'errors', v_errors);
END
$$;


ALTER FUNCTION public.fn_lightning_reap_expired_disconnects(p_cluster_id uuid, p_now timestamp with time zone, p_limit integer) OWNER TO postgres;

--
-- TOC entry 47955 (class 0 OID 0)
-- Dependencies: 4945
-- Name: FUNCTION fn_lightning_reap_expired_disconnects(p_cluster_id uuid, p_now timestamp with time zone, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_lightning_reap_expired_disconnects(p_cluster_id uuid, p_now timestamp with time zone, p_limit integer) IS 'Lightning Phase 9 (spec Phase 14), widened by Phase 10 and Phase 12. Exits every open pool session that is (a) disconnected longer than its Cluster''s disconnect_timeout_ms (exit_reason disconnect_expired), (b) carrying a Stop Playing request (exit_reason stop_playing), or (c) refused by the responsible-gaming helper fn_rg_require_not_excluded, self-exclusion or cooling-off (exit_reason rg_limit), whose player is not in a live hand and holds no live reservation: state closed, slot closed, one pool_player_left per session (reason = the exit_reason) and one player_expired event per Cluster per call for (a) alone. Releases nothing in-hand, never touches the anchor seat or the cash session, skips frozen Clusters. Clock-guarded, bounded (2000), SKIP LOCKED, each session isolated in its own sub-block. Run by fn_cash_clusters_tick_all beside the formation reaper; service_role only.';


--
-- TOC entry 7657 (class 1255 OID 56835327)
-- Name: fn_lightning_reap_formations(timestamp with time zone, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_reap_formations(p_now timestamp with time zone DEFAULT clock_timestamp(), p_limit integer DEFAULT 200, p_cluster_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  i          record;
  v_expired  integer := 0;
  v_abandoned integer := 0;
  v_rows     jsonb := '[]'::jsonb;
BEGIN
  -- DELIBERATELY NOT GATED ON fn_platform_frozen(). Giving a player back a
  -- reservation they can no longer use, and burying an instance that will
  -- never form, are recovery, and the break is when incidents are handled.
  -- fn_cash_cluster_abort_pending_on and fn_cash_cluster_reap_stuck_conversions
  -- make the same choice for the same reason, and Phase 5's header records it.

  -- NEVER REAP BY A CLOCK THAT HAS NOT ARRIVED (2026-09-26). This now reaps
  -- dealing and settling hands, and a caller passing a future p_now would
  -- otherwise abandon a live hand by asserting that its deadline had passed.
  -- A past p_now only ever reaps less.
  p_now := LEAST(coalesce(p_now, clock_timestamp()), clock_timestamp());

  UPDATE public.lightning_reservation r
     SET state = 'expired',
         resolved_at = p_now,
         reason = coalesce(r.reason, 'expired_before_commit')
   WHERE r.state = 'pending'
     AND r.expires_at <= p_now
     AND (p_cluster_id IS NULL OR r.cluster_id = p_cluster_id);
  GET DIAGNOSTICS v_expired = ROW_COUNT;

  FOR i IN
    SELECT li.id, li.cluster_id, li.cluster_epoch, li.state, li.hand_id,
           li.created_at, li.deadline_at
      FROM public.lightning_instance li
     -- ALL FOUR LIVE STATES (2026-09-26). A dealing or settling instance used
     -- to be invisible here, and its committed reservations were a permanent
     -- bar on its players. Its deadline_at is the one begin_dealing or its
     -- last keepalive set, so past it means nothing is vouching for the hand.
     WHERE li.state IN ('forming', 'reserved', 'dealing', 'settling')
       AND li.deadline_at <= p_now
       AND (p_cluster_id IS NULL OR li.cluster_id = p_cluster_id)
     ORDER BY li.deadline_at, li.id
     LIMIT GREATEST(1, coalesce(p_limit, 200))
     FOR UPDATE SKIP LOCKED
  LOOP
    -- The AFTER trigger on lightning_instance is what hands the players back:
    -- see fn_lightning_instance_releases_its_reservations and DECISION 3.
    UPDATE public.lightning_instance li
       SET state = 'abandoned',
           -- A HAND THAT WAS BEING DEALT IS VOID (2026-09-26). Nothing writes
           -- money before settlement, so abandoning it moves no chips, and the
           -- reason says whose silence ended it.
           abandon_reason = CASE
             WHEN li.state IN ('dealing', 'settling') THEN
               format('reaped: %s since %s, past the deadline %s that begin_dealing or its last keepalive set, with nothing vouching for it since; the hand is void',
                      li.state, justify_interval(p_now - coalesce(li.started_at, li.created_at)), li.deadline_at)
             ELSE
               format('reaped: %s since %s, past the deadline this instance was born with',
                      li.state, justify_interval(p_now - li.created_at))
           END,
           -- lightning_instance_lifecycle_order wants completed_at on or after
           -- started_at; an instance that never dealt keeps a NULL, exactly as
           -- fn_lightning_instance_abandon leaves it.
           completed_at = CASE WHEN li.started_at IS NOT NULL
                               THEN GREATEST(p_now, li.started_at) ELSE li.completed_at END
     WHERE li.id = i.id;
    v_abandoned := v_abandoned + 1;
    v_rows := v_rows || jsonb_build_object('instance_id', i.id, 'cluster_id', i.cluster_id,
                                           'was', i.state, 'hand_id', i.hand_id,
                                           'deadline_at', i.deadline_at);
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'as_of', p_now,
                            'reservations_expired', v_expired,
                            'instances_abandoned', v_abandoned,
                            'instances', v_rows);
END
$$;


ALTER FUNCTION public.fn_lightning_reap_formations(p_now timestamp with time zone, p_limit integer, p_cluster_id uuid) OWNER TO postgres;

--
-- TOC entry 47957 (class 0 OID 0)
