-- Name: FUNCTION fn_lightning_reap_formations(p_now timestamp with time zone, p_limit integer, p_cluster_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_lightning_reap_formations(p_now timestamp with time zone, p_limit integer, p_cluster_id uuid) IS 'Expires pending reservations past expires_at and abandons forming, reserved, dealing and settling instances past deadline_at - for a dealing or settling hand, the deadline begin_dealing or its last fn_lightning_instance_keepalive set, so a hand is reaped only when nothing has vouched for it - releasing their reservations through trg_lightning_instance_releases_its_reservations. Never reaps by a clock that has not arrived: p_now is clamped to clock_timestamp(). Called by fn_lightning_form_hand for its own Cluster and by fn_cash_clusters_tick_all for the estate. Deliberately NOT gated on fn_platform_frozen(): giving a player back is recovery, and the break is when recovery happens.';


--
-- TOC entry 5873 (class 1255 OID 123484743)
-- Name: fn_lightning_recent_hands(integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lightning_recent_hands(p_limit integer DEFAULT 50, p_pool_session_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid   uuid := auth.uid();
  v_limit integer := LEAST(GREATEST(coalesce(p_limit, 50), 0), 50);
BEGIN
  IF v_uid IS NULL OR v_limit = 0 THEN
    RETURN '[]'::jsonb;
  END IF;
  -- A session filter names one of the caller's own sessions, or nothing.
  IF p_pool_session_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.lightning_pool_session ps
                      WHERE ps.id = p_pool_session_id AND ps.player_id = v_uid) THEN
    RETURN '[]'::jsonb;
  END IF;
  RETURN (
    SELECT coalesce(jsonb_agg(jsonb_build_object(
             'hand_id',         q.hand_id,
             'hand_history_id', q.hand_history_id,
             'hand_number',     q.hand_number,
             'played_at',       q.played_at,
             'cluster_id',      q.cluster_id,
             'small_blind',     q.small_blind,
             'big_blind',       q.big_blind,
             'position',        q.position,
             'stack_before',    q.stack_before,
             'stack_after',     q.stack_after,
             'net',             q.net,
             'pot',             q.pot,
             'fold_type',       q.fold_type,
             'showdown',        q.showdown,
             'result',          q.result)
             ORDER BY q.played_at DESC, q.hand_number DESC), '[]'::jsonb)
      FROM (
        SELECT lh.hand_id, lh.hand_history_id, lh.hand_number, lh.settled_at AS played_at, lh.cluster_id,
               coalesce(hh.small_blind, cg.sb) AS small_blind,
               coalesce(hh.big_blind, cg.bb) AS big_blind,
               hp.position, hp.stack_before, hp.stack_after, hp.net_result AS net,
               hh.pot_size AS pot, hp.fold_type, coalesce(hp.showed, false) AS showdown,
               CASE
                 WHEN hp.fold_type <> 'none' THEN 'folded'
                 -- 20261008043021: NO WINNERS RECORD, NO GUESSING FROM ITS
                 -- ABSENCE. With the hand_history row pruned (the retention
                 -- policy prunes horse-only hands) or its winners missing,
                 -- the result is the net alone: ahead won, behind lost,
                 -- level and not folded won (a walk or a returned blind is
                 -- not a split).
                 WHEN NOT w.available THEN CASE WHEN hp.net_result > 0 THEN 'won'
                                                WHEN hp.net_result < 0 THEN 'lost'
                                                ELSE 'won' END
                 WHEN w.mine AND w.shared THEN 'split'
                 WHEN w.mine THEN 'won'
                 WHEN hp.net_result > 0 THEN 'won'
                 WHEN hp.net_result = 0 AND NOT w.listed THEN 'split'
                 ELSE 'lost' END AS result
          FROM public.lightning_hand_player hp
          JOIN public.lightning_hand lh ON lh.hand_id = hp.hand_id
          JOIN public.lightning_pool_slot sl ON sl.id = hp.pool_slot_id
          JOIN public.cash_games cg ON cg.id = lh.cluster_id
          LEFT JOIN public.hand_history hh ON hh.id = lh.hand_history_id
          -- THE WINNERS THE ENGINE RECORDED: [{userId, amount, potIndex}].
          -- Shared when another player won a pot this player also won.
          -- 20261008043021: userId is compared case- and type-normalised
          -- (an engine row has carried uppercase and non-string ids), and
          -- `available` says whether a winners record exists at all.
          CROSS JOIN LATERAL (
            SELECT (CASE WHEN jsonb_typeof(hh.winners) = 'array'
                         THEN jsonb_array_length(hh.winners) > 0 ELSE false END) AS available,
                   coalesce(bool_or(x.uid = lower(hp.player_id::text)), false) AS mine,
                   coalesce(bool_or(x.uid = lower(hp.player_id::text) AND EXISTS (
                     SELECT 1 FROM jsonb_array_elements(
                              CASE WHEN jsonb_typeof(hh.winners) = 'array' THEN hh.winners ELSE '[]'::jsonb END) y
                      WHERE lower(btrim(y ->> 'userId')) IS DISTINCT FROM lower(hp.player_id::text)
                        AND coalesce(y ->> 'potIndex', '0') = x.pot)), false) AS shared,
                   count(*) > 0 AS listed
              FROM (SELECT lower(btrim(e ->> 'userId')) AS uid, coalesce(e ->> 'potIndex', '0') AS pot
                      FROM jsonb_array_elements(
                             CASE WHEN jsonb_typeof(hh.winners) = 'array' THEN hh.winners ELSE '[]'::jsonb END) e) x
          ) w
         WHERE hp.player_id = v_uid
           AND lh.settled_at IS NOT NULL
           AND (p_pool_session_id IS NULL OR sl.pool_session_id = p_pool_session_id)
         ORDER BY lh.settled_at DESC, lh.hand_number DESC
         LIMIT v_limit) q);
END
$$;


