--
-- TOC entry 9631 (class 1255 OID 4957564)
-- Name: fn_list_user_public_home_groups(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_list_user_public_home_groups(p_target_user_id uuid, p_limit integer DEFAULT 20) RETURNS TABLE(group_id uuid, group_name text, group_slug text, relationship text, city text, member_count integer, profile_photo_url text, created_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  p_limit := GREATEST(1, LEAST(COALESCE(p_limit, 20), 100));

  RETURN QUERY
  SELECT t.u_group_id, t.u_group_name, t.u_group_slug, t.u_relationship,
         t.u_city, t.u_member_count, t.u_profile_photo_url, t.u_created_at
  FROM (
    SELECT g.id                        AS u_group_id,
           g.name::text                AS u_group_name,
           sp.slug::text               AS u_group_slug,
           'owner'::text               AS u_relationship,
           g.city::text                AS u_city,
           g.member_count              AS u_member_count,
           g.profile_photo_url::text   AS u_profile_photo_url,
           g.created_at                AS u_created_at
      FROM public.commander_home_groups g
      LEFT JOIN public.social_pages sp
        ON sp.linked_entity_type='home_group' AND sp.linked_entity_id = g.id::text
     WHERE g.owner_id = p_target_user_id
       AND g.is_private = false
       AND COALESCE(g.is_active, true) = true
    UNION
    SELECT g.id, g.name::text, sp.slug::text, m.role::text,
           g.city::text, g.member_count, g.profile_photo_url::text, g.created_at
      FROM public.commander_home_members m
      JOIN public.commander_home_groups g ON g.id = m.group_id
      LEFT JOIN public.social_pages sp
        ON sp.linked_entity_type='home_group' AND sp.linked_entity_id = g.id::text
     WHERE m.user_id = p_target_user_id
       AND m.status = 'approved'
       AND m.role IN ('admin','co_host')
       AND g.owner_id <> p_target_user_id
       AND g.is_private = false
       AND COALESCE(g.is_active, true) = true
  ) t
  ORDER BY
    CASE t.u_relationship WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 ELSE 2 END,
    t.u_created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.fn_list_user_public_home_groups(p_target_user_id uuid, p_limit integer) OWNER TO postgres;

--
-- TOC entry 7511 (class 1255 OID 5692944)
-- Name: fn_live_streams_guard_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_live_streams_guard_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  is_end_user boolean := current_user = 'authenticated';
BEGIN
  -- broadcaster_id immutable for ALL callers
  IF NEW.broadcaster_id IS DISTINCT FROM OLD.broadcaster_id THEN
    RAISE EXCEPTION 'broadcaster_id is immutable'
      USING ERRCODE = '42501';
  END IF;

  -- Metric columns are SERVER-managed only (RPC path with SECURITY DEFINER
  -- runs as the function owner, not 'authenticated', so RPC writes pass).
  -- Direct end-user UPDATEs cannot touch these - they are the clout-fraud
  -- vectors (a broadcaster could otherwise set viewer_count = 1_000_000).
  IF is_end_user THEN
    IF NEW.viewer_count    IS DISTINCT FROM OLD.viewer_count    THEN
      RAISE EXCEPTION 'viewer_count is server-managed (use update_live_metrics RPC)'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.peak_viewers    IS DISTINCT FROM OLD.peak_viewers    THEN
      RAISE EXCEPTION 'peak_viewers is server-managed (use update_live_metrics RPC)'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.reaction_count  IS DISTINCT FROM OLD.reaction_count  THEN
      RAISE EXCEPTION 'reaction_count is server-managed'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- status, ended_at, started_at, livekit_room: ALLOWED from broadcaster.
  -- The RLS UPDATE policy already constrains these to broadcaster_id =
  -- auth.uid(), so a broadcaster can only mutate their own stream.

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_live_streams_guard_update() OWNER TO postgres;

--
-- TOC entry 48000 (class 0 OID 0)
-- Dependencies: 7511
-- Name: FUNCTION fn_live_streams_guard_update(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_live_streams_guard_update() IS 'Guards live_streams UPDATEs. broadcaster_id immutable for all callers. End-user authenticated role cannot mutate metric columns (viewer_count, peak_viewers, reaction_count) — those go through update_live_metrics RPC. status/ended_at/started_at/livekit_room remain broadcaster-writable for normal start/end flow.';


--
-- TOC entry 3764 (class 1255 OID 14330123)
-- Name: fn_live_table_count(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_live_table_count(p_club_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT count(*)::int
    FROM tables t
   WHERE t.tournament_id IS NULL
     AND t.is_deleted IS NOT TRUE
     AND t.status NOT IN ('closed', 'deleted')
     AND (
       -- the club's own games (private club games included)
       t.club_id = p_club_id
       -- plus the union's games, if this club belongs to one
       OR t.union_id = (SELECT uc.union_id FROM union_clubs uc
                         WHERE uc.club_id = p_club_id LIMIT 1)
       -- the union's own container row: its games are keyed by union_id
       OR t.union_id = p_club_id
     );
$$;


ALTER FUNCTION public.fn_live_table_count(p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 5158 (class 1255 OID 34785587)
-- Name: fn_lock_accounting_tournament_recognition_week(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lock_accounting_tournament_recognition_week(p_tournament_id uuid, p_recognized_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$DECLARE scope record;week_start timestamptz;week_end timestamptz;BEGIN
 week_start:=public.fn_union_week_start(p_recognized_at);
 week_end:=((week_start AT TIME ZONE 'America/Los_Angeles')+interval '7 days') AT TIME ZONE 'America/Los_Angeles';
 FOR scope IN
  WITH scopes AS (
   SELECT coordinator_union_id,club_id FROM public.accounting_tournament_fee_sources WHERE tournament_id=p_tournament_id
   UNION
   -- The actual bank also participates in the same close order. A legacy event
   -- may have no captured contributor; this names its game bank, never guesses
   -- a contributor's historical membership or commission agreement.
   SELECT f.union_id,t.club_id FROM public.tournaments t
    JOIN public.accounting_tournament_fee_sources f ON f.tournament_id=t.id WHERE t.id=p_tournament_id AND t.club_id IS NOT NULL
   UNION
   SELECT CASE WHEN t.is_private THEN NULL ELSE t.union_id END,t.club_id FROM public.tournaments t
    WHERE t.id=p_tournament_id AND t.club_id IS NOT NULL
     AND NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_sources f WHERE f.tournament_id=t.id)
  ) SELECT DISTINCT coordinator_union_id,club_id,
   CASE WHEN coordinator_union_id IS NULL THEN 'club-accounting:'||club_id::text ELSE 'union-accounting:'||coordinator_union_id::text END
    ||':'||extract(epoch FROM week_start)::text||':'||extract(epoch FROM week_end)::text lock_key
  FROM scopes ORDER BY lock_key
 LOOP
  -- Shared: recognition excludes the weekly close, never a sibling accrual.
  PERFORM pg_advisory_xact_lock_shared(hashtextextended(scope.lock_key,0));
  IF EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r WHERE r.period_start<=p_recognized_at AND r.period_end>p_recognized_at
   AND ((r.union_id IS NOT NULL AND r.union_id=scope.coordinator_union_id)
     OR (r.standalone_club_id IS NOT NULL AND scope.coordinator_union_id IS NULL AND r.standalone_club_id=scope.club_id))) THEN
   RAISE EXCEPTION 'tournament_accrual_closed_period_requires_adjustment' USING ERRCODE='23514'; END IF;
 END LOOP;
END$$;


ALTER FUNCTION public.fn_lock_accounting_tournament_recognition_week(p_tournament_id uuid, p_recognized_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 7575 (class 1255 OID 34785128)
-- Name: fn_lock_cash_bank_accounting_week(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lock_cash_bank_accounting_week(p_club_id uuid, p_game_union_id uuid, p_banked_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE coordinator uuid;memberships int;week_from timestamptz;week_to timestamptz;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_club_id IS NULL OR p_banked_at IS DISTINCT FROM transaction_timestamp() THEN
  RAISE EXCEPTION 'cash_bank_week_identity_invalid' USING ERRCODE='22023'; END IF;
 coordinator:=p_game_union_id;
 IF coordinator IS NULL THEN
  -- A private game's bank remains local. Its weekly coordinator is determined
  -- independently from the observed membership, matching the source contract.
  SELECT count(*),(array_agg((h.after_terms->>'union_id')::uuid))[1] INTO memberships,coordinator FROM (
   SELECT DISTINCT ON(entity_key) entity_key,after_terms FROM public.accounting_agreement_history
    WHERE entity_type='union_clubs' AND club_id=p_club_id AND observed_at<=p_banked_at
    ORDER BY entity_key,observed_at DESC,id DESC
  )h WHERE h.after_terms IS NOT NULL AND h.after_terms->>'club_id'=p_club_id::text;
  IF memberships>1 THEN RAISE EXCEPTION 'cash_bank_coordinator_ambiguous' USING ERRCODE='55000'; END IF;
 END IF;
 week_from:=public.fn_union_week_start(p_banked_at);week_to:=public.fn_union_week_start(week_from+interval '8 days');
 -- Shared: this guard only READS the closed-week tables. It excludes the
 -- weekly close, never a sibling bank.
 PERFORM pg_advisory_xact_lock_shared(hashtextextended(
  CASE WHEN coordinator IS NOT NULL THEN 'union-accounting:' ELSE 'club-accounting:' END
  ||COALESCE(coordinator,p_club_id)::text||':'||extract(epoch FROM week_from)::text||':'||extract(epoch FROM week_to)::text,0));
 IF EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r WHERE r.period_start=week_from AND r.period_end=week_to
   AND ((coordinator IS NOT NULL AND r.union_id=coordinator) OR (coordinator IS NULL AND r.standalone_club_id=p_club_id)))
  OR EXISTS(SELECT 1 FROM public.union_rakeback_log l WHERE l.union_id=coordinator AND l.period_start<=p_banked_at AND l.period_end>p_banked_at)
 THEN RAISE EXCEPTION 'cash_bank_closed_week_requires_adjustment' USING ERRCODE='55000'; END IF;
END $$;


ALTER FUNCTION public.fn_lock_cash_bank_accounting_week(p_club_id uuid, p_game_union_id uuid, p_banked_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 4192 (class 1255 OID 22358228)
-- Name: fn_lock_daily_mission_user(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_lock_daily_mission_user(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'A Daily Missions player is required';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('daily-missions-user:' || p_user_id::text, 0)
  );

  PERFORM 1
  FROM public.profiles
  WHERE id = p_user_id
  FOR NO KEY UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Daily Missions profile not found for player %', p_user_id;
  END IF;
END;
$$;


