--
-- TOC entry 9164 (class 1255 OID 18670459)
-- Name: fn_managed_game_command_hash(uuid, text, uuid, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_managed_game_command_hash(p_command_id uuid, p_kind text, p_game_id uuid, p_action text, p_expected_version integer, p_payload jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT encode(
    extensions.digest(
      convert_to(
        jsonb_build_object(
          'command_id', p_command_id,
          'kind', p_kind,
          'game_id', p_game_id,
          'action', p_action,
          'expected_version', p_expected_version,
          'payload', COALESCE(p_payload, '{}'::jsonb)
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  )
$$;


