--
-- TOC entry 4602 (class 1255 OID 4767522)
-- Name: fn_mark_messages_read(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mark_messages_read(p_conversation_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_count integer;
BEGIN
    IF p_conversation_id IS NULL OR p_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing parameters');
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM social_conversation_participants
         WHERE conversation_id = p_conversation_id AND user_id = p_user_id
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not a participant');
    END IF;

    WITH inserted AS (
        INSERT INTO social_message_reads (message_id, user_id, read_at)
        SELECT m.id, p_user_id, NOW()
          FROM social_messages m
         WHERE m.conversation_id = p_conversation_id
           AND m.sender_id <> p_user_id
           AND COALESCE(m.is_deleted, false) = false
           AND NOT EXISTS (
               SELECT 1 FROM social_message_reads r
                WHERE r.message_id = m.id AND r.user_id = p_user_id
           )
        ON CONFLICT (message_id, user_id) DO NOTHING
        RETURNING 1
    )
    SELECT COUNT(*) INTO v_count FROM inserted;

    UPDATE social_conversation_participants
       SET last_read_at = NOW()
     WHERE conversation_id = p_conversation_id
       AND user_id = p_user_id;

    RETURN jsonb_build_object('success', true, 'marked', v_count);
END;
$$;


ALTER FUNCTION public.fn_mark_messages_read(p_conversation_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 6757 (class 1255 OID 59805370)
-- Name: fn_mark_messages_read_through(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mark_messages_read_through(p_conversation_id uuid, p_user_id uuid, p_through_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_through timestamptz;
  v_count integer;
BEGIN
  IF p_conversation_id IS NULL OR p_user_id IS NULL OR p_through_message_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'missing parameters');
  END IF;
  -- Serialize receipts for one reader without locking other readers or sends.
  PERFORM 1 FROM social_conversation_participants
   WHERE conversation_id=p_conversation_id AND user_id=p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'not a participant');
  END IF;
  SELECT created_at INTO v_through FROM social_messages
   WHERE id=p_through_message_id AND conversation_id=p_conversation_id
     AND COALESCE(is_deleted, false)=false;
  IF v_through IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid read boundary');
  END IF;
  WITH inserted AS (
    INSERT INTO social_message_reads(message_id,user_id,read_at)
    SELECT m.id,p_user_id,NOW() FROM social_messages m
     WHERE m.conversation_id=p_conversation_id
       AND m.created_at<=v_through
       AND m.sender_id IS DISTINCT FROM p_user_id
       AND COALESCE(m.is_deleted,false)=false
    ON CONFLICT(message_id,user_id) DO NOTHING RETURNING 1
  ) SELECT COUNT(*) INTO v_count FROM inserted;
  UPDATE social_conversation_participants
     SET last_read_at=GREATEST(last_read_at,v_through)
   WHERE conversation_id=p_conversation_id AND user_id=p_user_id;
  RETURN jsonb_build_object('success',true,'marked',v_count,'readThrough',v_through);
END $$;


ALTER FUNCTION public.fn_mark_messages_read_through(p_conversation_id uuid, p_user_id uuid, p_through_message_id uuid) OWNER TO postgres;

