--
-- TOC entry 6060 (class 1255 OID 34785730)
-- Name: fn_mark_scope_accounting_settled(text, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mark_scope_accounting_settled(p_scope_kind text, p_scope_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE u_id uuid;c_id uuid;clubs uuid[];period public.settlement_periods%ROWTYPE;n int;club uuid;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_scope_kind IS NULL OR p_scope_kind NOT IN('union','club') OR p_scope_id IS NULL
  OR p_from IS NULL OR p_to IS NULL OR p_from IS DISTINCT FROM public.fn_union_week_start(p_from)
  OR p_to IS DISTINCT FROM public.fn_union_week_start(p_from+interval '8 days') THEN
  RAISE EXCEPTION 'invalid_accounting_settled_scope' USING ERRCODE='22023'; END IF;
 u_id:=CASE WHEN p_scope_kind='union' THEN p_scope_id END;c_id:=CASE WHEN p_scope_kind='club' THEN p_scope_id END;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_scope_kind||'-accounting:'||p_scope_id::text||':'||extract(epoch FROM p_from)::text||':'||extract(epoch FROM p_to)::text,0));
 SELECT COALESCE(array_agg(w.club_id),ARRAY[]::uuid[]) INTO clubs FROM public.fn_accounting_week_clubs(u_id,c_id,p_from,p_to)w;
 -- EVERY PERIOD THE WEEK OPENED IS SETTLED WITH IT (2026-10-03). The square-up
 -- issuer opens a period for the union's own club row (clubs.id = union id),
 -- which fn_accounting_week_clubs leaves out, so nothing ever settled it.
 IF u_id IS NOT NULL THEN
  SELECT clubs||COALESCE(array_agg(DISTINCT sp.club_id),ARRAY[]::uuid[]) INTO clubs
    FROM public.settlement_periods sp
   WHERE sp.union_id=u_id AND sp.start_at=p_from AND sp.end_at=p_to
     AND sp.club_id IS NOT NULL AND NOT (sp.club_id=ANY(clubs));
  clubs:=array_append(clubs,NULL::uuid);
 END IF;
 FOREACH club IN ARRAY clubs LOOP
  SELECT count(*) INTO n FROM public.settlement_periods sp WHERE sp.club_id IS NOT DISTINCT FROM club
    AND sp.union_id IS NOT DISTINCT FROM u_id AND sp.start_at=p_from AND sp.end_at=p_to;
  IF n>1 THEN RAISE EXCEPTION 'accounting_week_has_duplicate_periods' USING ERRCODE='55000'; END IF;
  SELECT * INTO period FROM public.settlement_periods sp WHERE sp.club_id IS NOT DISTINCT FROM club
    AND sp.union_id IS NOT DISTINCT FROM u_id AND sp.start_at=p_from AND sp.end_at=p_to FOR UPDATE;
  IF NOT FOUND THEN
   INSERT INTO public.settlement_periods(club_id,union_id,period_number,year,start_at,end_at,status,settled_at,settled_by)
    VALUES(club,u_id,extract(week FROM p_from AT TIME ZONE 'America/Los_Angeles')::int,
     extract(isoyear FROM p_from AT TIME ZONE 'America/Los_Angeles')::int,p_from,p_to,'settled',now(),auth.uid());
  ELSIF period.status IS NULL OR period.status NOT IN('open','processing','settled','closed') THEN
   RAISE EXCEPTION 'accounting_week_period_state_requires_reconciliation' USING ERRCODE='55000';
  ELSIF period.status NOT IN('settled','closed') THEN
   UPDATE public.settlement_periods SET status='settled',settled_at=now(),settled_by=auth.uid(),updated_at=now() WHERE id=period.id;
  END IF;
 END LOOP;
END $$;


ALTER FUNCTION public.fn_mark_scope_accounting_settled(p_scope_kind text, p_scope_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 8070 (class 1255 OID 17140072)
-- Name: fn_mark_table_setting_touched(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mark_table_setting_touched(p_columns text[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_uid   uuid := auth.uid();
  v_valid text[];
BEGIN
  IF v_uid IS NULL OR p_columns IS NULL OR array_length(p_columns, 1) IS NULL THEN
    RETURN;
  END IF;

  SELECT array_agg(DISTINCT c)
    INTO v_valid
    FROM unnest(p_columns) AS c
   WHERE c IN (
     SELECT a.attname::text
       FROM pg_attribute a
      WHERE a.attrelid = 'public.user_table_settings'::regclass
        AND a.attnum > 0
        AND NOT a.attisdropped
        AND a.attname NOT IN ('user_id', 'created_at', 'updated_at', 'settings_touched')
   );

  IF v_valid IS NULL THEN
    RETURN;
  END IF;

  UPDATE public.user_table_settings t
     SET settings_touched = (
           SELECT array_agg(DISTINCT e)
             FROM unnest(t.settings_touched || v_valid) AS e
         )
   WHERE t.user_id = v_uid;
END
$$;


ALTER FUNCTION public.fn_mark_table_setting_touched(p_columns text[]) OWNER TO postgres;

--
-- TOC entry 48032 (class 0 OID 0)
-- Dependencies: 8070
-- Name: FUNCTION fn_mark_table_setting_touched(p_columns text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_mark_table_setting_touched(p_columns text[]) IS 'Record that the signed-in user deliberately set these settings columns. Idempotent, whitelisted against the table catalog, and scoped to auth.uid(). Called after a successful per-key upsert from useTableSettings / useUserTableSettings.';


--
-- TOC entry 6534 (class 1255 OID 108293331)
-- Name: fn_mark_table_setting_touched(uuid, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mark_table_setting_touched(p_expected_user_id uuid, p_columns text[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_valid text[];
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF p_expected_user_id IS NULL OR p_expected_user_id IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'Authenticated account changed before settings were marked'
      USING ERRCODE = '42501';
  END IF;
  IF p_columns IS NULL OR array_length(p_columns, 1) IS NULL THEN
    RETURN;
  END IF;

  SELECT array_agg(DISTINCT requested.column_name)
    INTO v_valid
    FROM unnest(p_columns) AS requested(column_name)
   WHERE requested.column_name IN (
     SELECT attribute.attname::text
       FROM pg_attribute attribute
      WHERE attribute.attrelid = 'public.user_table_settings'::regclass
        AND attribute.attnum > 0
        AND NOT attribute.attisdropped
        AND attribute.attname NOT IN ('user_id', 'created_at', 'updated_at', 'settings_touched')
   );

  IF v_valid IS NULL THEN
    RETURN;
  END IF;

  UPDATE public.user_table_settings AS setting
     SET settings_touched = (
       SELECT array_agg(DISTINCT touched)
         FROM unnest(setting.settings_touched || v_valid) AS touched
     )
   WHERE setting.user_id = v_user_id;
END;
$$;


ALTER FUNCTION public.fn_mark_table_setting_touched(p_expected_user_id uuid, p_columns text[]) OWNER TO postgres;

