--
-- TOC entry 9597 (class 1255 OID 8902814)
-- Name: fn_member_leave_to_treasury(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_member_leave_to_treasury(p_club_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_role  text;
  v_chips numeric;
  v_after numeric;
  v_caller uuid := auth.uid();
  v_saved jsonb;
BEGIN
  IF p_club_id IS NULL OR p_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'club and user required');
  END IF;

  -- AUTHZ: service role, the member themselves, or a club treasury manager.
  IF v_caller IS NOT NULL
     AND v_caller <> p_user_id
     AND NOT public.fn_actor_can_manage_club_treasury(p_club_id) THEN
    RETURN jsonb_build_object('success', false,
      'error', 'not authorized to remove another member from this club');
  END IF;

  SELECT role, COALESCE(chip_balance, 0)
    INTO v_role, v_chips
  FROM club_members
  WHERE club_id = p_club_id AND user_id = p_user_id
  FOR UPDATE;

  IF v_role IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not a member');
  END IF;

  IF v_role = 'owner' THEN
    RETURN jsonb_build_object('success', false, 'error', 'owner must transfer ownership first');
  END IF;

  -- A SEATED MEMBER LEAVES THE TABLE BEFORE THE CLUB (launch audit
  -- 2026-10-05). table_seats.club_id is the club the seat was funded from. A
  -- membership deleted under a live seat leaves that stack with no wallet to
  -- cash out into, so the leave is refused here, for every caller.
  IF EXISTS (
    SELECT 1
      FROM public.table_seats ts
     WHERE ts.user_id = p_user_id
       AND ts.club_id = p_club_id
       AND ts.left_at IS NULL
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Leave Your Seat At The Table First');
  END IF;

  IF v_chips > 0 THEN
    /* THE WALLET PAYS THE TREASURY, BY NAME (2026-10-02, 20261002140203).
       This credited the treasury with no counterparty (a settlement_suspense
       leg) and then DELETEd the member row, which the delete journal booked
       as a burn of the same chips: the chips were counted out twice and in
       from nowhere once. The wallet is now emptied INTO the treasury under a
       declared club_treasury counterparty (one leg, player wallet -> club
       treasury), the treasury credit itself writes no second leg, and the
       row is deleted holding no chips. */
    v_saved := public.fn_ca_ledger_declaration_save(ARRAY['clubs']);
    PERFORM public.fn_ca_declare_ledger('treasury_transfer', 'club_treasury', p_club_id,
                                        NULL, NULL, ARRAY['clubs']);

    UPDATE club_members
       SET chip_balance = 0, updated_at = NOW()
     WHERE club_id = p_club_id AND user_id = p_user_id;

    UPDATE clubs
    SET chip_treasury = COALESCE(chip_treasury, 0) + v_chips,
        updated_at = NOW()
    WHERE id = p_club_id
    RETURNING chip_treasury INTO v_after;

    PERFORM public.fn_ca_ledger_declaration_restore(v_saved);

    IF v_after IS NULL THEN
      RAISE EXCEPTION 'club % not found while returning % chips from member %', p_club_id, v_chips, p_user_id;
    END IF;

    INSERT INTO chip_transactions (
      id, club_id, from_user_id, amount, transaction_type, notes, balance_after, created_at
    ) VALUES (
      gen_random_uuid(), p_club_id, p_user_id, v_chips,
      'leave_club_chip_return', 'Chips returned to treasury on club departure',
      v_after, NOW()
    );
  END IF;

  -- A MEMBER CAN LEAVE DEEP STACK SOCIETY (launch audit 2026-10-05). The
  -- club's delete guard refuses any club_members DELETE that has not declared
  -- itself. This door is authorized above and removes exactly one row, so it
  -- declares for that one statement and restores the setting after it.
  DECLARE
    v_teardown_before text := COALESCE(current_setting('app.deep_stack_teardown', true), '');
  BEGIN
    PERFORM set_config('app.deep_stack_teardown', 'on', true);
    DELETE FROM club_members WHERE club_id = p_club_id AND user_id = p_user_id;
    PERFORM set_config('app.deep_stack_teardown', v_teardown_before, true);
  END;

  RETURN jsonb_build_object('success', true, 'chips_returned', COALESCE(v_chips, 0));
END;
$$;


ALTER FUNCTION public.fn_member_leave_to_treasury(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 6526 (class 1255 OID 215230521)
-- Name: fn_member_rakeback_explicit_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_member_rakeback_explicit_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE changed boolean;
BEGIN
 IF TG_OP='INSERT' THEN
  changed:=coalesce(NEW.player_rakeback_pct,0)<>0 OR NEW.player_rakeback_explicit;
 ELSE
  changed:=NEW.player_rakeback_pct IS DISTINCT FROM OLD.player_rakeback_pct
    OR NEW.player_rakeback_explicit IS DISTINCT FROM OLD.player_rakeback_explicit;
 END IF;
 IF changed AND current_user NOT IN ('postgres','supabase_admin','service_role') THEN
  RAISE EXCEPTION 'Individual Rakeback Must Be Set Through Its Agreement RPC' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_member_rakeback_explicit_guard() OWNER TO postgres;

--
-- TOC entry 5763 (class 1255 OID 215230540)
-- Name: fn_member_rakeback_terms(uuid, uuid, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_member_rakeback_terms(p_club_id uuid, p_user_id uuid, p_role text, p_rate numeric DEFAULT NULL::numeric, p_expected_rate numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE actor uuid:=auth.uid(); actor_role text; member public.club_members%ROWTYPE;
 agreement public.agents%ROWTYPE; parent public.agents%ROWTYPE;
 current_rate numeric; maximum numeric; old_state jsonb; allowed boolean;
BEGIN
 IF actor IS NULL OR actor=p_user_id THEN
  RETURN jsonb_build_object('success',false,'error','You Cannot Edit Your Own Rakeback');
 END IF;
 IF p_rate IS NOT NULL AND (p_rate::text IN ('NaN','Infinity','-Infinity') OR p_rate<0 OR p_rate>0.70 OR p_rate<>round(p_rate,4)) THEN
  RETURN jsonb_build_object('success',false,'error','Invalid Rakeback Percentage');
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||p_club_id::text,0));
 SELECT role INTO actor_role FROM public.club_members
  WHERE club_id=p_club_id AND user_id=actor AND status IN ('active','approved') AND coalesce(is_active,true);
 SELECT * INTO member FROM public.club_members
  WHERE club_id=p_club_id AND user_id=p_user_id AND status IN ('active','approved') AND coalesce(is_active,true) FOR UPDATE;
 IF NOT FOUND OR member.role IS DISTINCT FROM p_role OR p_role NOT IN ('player','sub_agent','agent','super_agent') THEN
  RETURN jsonb_build_object('success',false,'error','Member Role Changed Or Is Not Eligible');
 END IF;
 allowed:=p_role=ANY(public.fn_club_grantable_roles(p_club_id,actor,p_user_id));
 IF p_role='player' AND actor_role IN ('super_agent','agent','sub_agent')
  AND public.fn_club_is_in_downline(p_club_id,actor,p_user_id) THEN allowed:=true; END IF;
 IF NOT COALESCE(allowed,false) THEN
  RETURN jsonb_build_object('success',false,'error','You Cannot Set This Member Rakeback');
 END IF;
 IF p_role='player' THEN
  SELECT * INTO parent FROM public.agents WHERE club_id=p_club_id AND user_id=member.agent_id AND status='active';
  IF NOT FOUND AND member.agent_id IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM public.clubs WHERE id=p_club_id AND owner_id=member.agent_id) THEN
   RETURN jsonb_build_object('success',false,'error','Player Upline Has No Active Agreement');
  END IF;
  maximum:=CASE WHEN EXISTS(SELECT 1 FROM public.clubs WHERE id=p_club_id AND owner_id=member.agent_id) THEN 0.70 WHEN FOUND THEN greatest(parent.commission_rate-0.10,0) ELSE 0.70 END;
  current_rate:=public.fn_player_rakeback_rate(p_user_id,p_club_id,0);
  old_state:=jsonb_build_object('player_rakeback_pct',member.player_rakeback_pct,'player_rakeback_explicit',member.player_rakeback_explicit);
 ELSE
  SELECT * INTO agreement FROM public.agents WHERE club_id=p_club_id AND user_id=p_user_id AND status='active' FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','No Active Agent Agreement'); END IF;
  SELECT * INTO parent FROM public.agents WHERE id=agreement.parent_agent_id AND club_id=p_club_id AND status='active';
  maximum:=CASE WHEN FOUND THEN least(0.70,parent.commission_rate) ELSE 0.70 END;
  current_rate:=agreement.commission_rate;
  old_state:=jsonb_build_object('commission_rate',current_rate);
 END IF;
 IF p_rate IS NOT NULL THEN
  IF p_expected_rate IS NULL OR current_rate IS DISTINCT FROM p_expected_rate THEN
   RETURN jsonb_build_object('success',false,'error','Rakeback Changed. Reload Terms Before Saving');
  END IF;
  IF p_rate>maximum OR (p_role='player' AND parent.id IS NOT NULL AND p_rate>greatest(parent.commission_rate-0.10,0) AND NOT(p_rate=0.70 AND EXISTS(SELECT 1 FROM public.clubs WHERE id=p_club_id AND owner_id=member.agent_id))) THEN RETURN jsonb_build_object('success',false,'error','Rakeback Exceeds The Upline Limit'); END IF;
  IF p_role='player' THEN
   UPDATE public.club_members SET player_rakeback_pct=p_rate,player_rakeback_explicit=true,updated_at=now()
    WHERE club_id=p_club_id AND user_id=p_user_id;
  ELSE
   IF p_rate<agreement.player_rakeback_rate THEN
    RETURN jsonb_build_object('success',false,'error','Agent Rate Cannot Fall Below Their Player Offer');
   END IF;
   IF EXISTS(SELECT 1 FROM public.agents WHERE parent_agent_id=agreement.id AND club_id=p_club_id AND commission_rate>p_rate) THEN
    RETURN jsonb_build_object('success',false,'error','Agent Rate Cannot Fall Below A Child Agreement');
   END IF;
   UPDATE public.agents SET commission_rate=p_rate,updated_at=now() WHERE id=agreement.id;
  END IF;
  INSERT INTO public.audit_trail(actor_id,actor_role,action,target_type,target_id,club_id,before_state,after_state,reason)
  VALUES(actor,coalesce(actor_role,'platform_admin'),'set_member_rakeback','club_member',p_user_id,p_club_id,old_state,
   jsonb_build_object('role',p_role,'rate',p_rate),'Individual Rakeback Agreement Updated');
  current_rate:=p_rate;
 END IF;
 RETURN jsonb_build_object('success',true,'club_id',p_club_id,'user_id',p_user_id,'role',p_role,'rate',current_rate,'max_rate',maximum);
END $$;


ALTER FUNCTION public.fn_member_rakeback_terms(p_club_id uuid, p_user_id uuid, p_role text, p_rate numeric, p_expected_rate numeric) OWNER TO postgres;

