--
-- TOC entry 8351 (class 1255 OID 171351912)
-- Name: fn_messenger_club_relationships(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_messenger_club_relationships(p_viewer uuid, p_peers uuid[]) RETURNS TABLE(peer_user_id uuid, club_id uuid, club_name text, role text, is_upline boolean, label text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
 WITH RECURSIVE mine AS (
  SELECT m.* FROM public.club_members m WHERE m.user_id=p_viewer AND m.is_active=true
   AND m.status IN ('active','approved') AND m.membership_lifecycle_status='active'
 ), chain AS (
  SELECT a.id,a.user_id,a.club_id,a.parent_agent_id,ARRAY[a.id] AS visited FROM public.agents a JOIN mine m ON m.club_id=a.club_id
   WHERE a.status='active' AND (a.user_id=m.agent_id OR a.id IN (SELECT s.parent_agent_id FROM public.agents s WHERE s.club_id=m.club_id AND s.user_id=p_viewer AND s.status='active'))
  UNION ALL
  SELECT a.id,a.user_id,a.club_id,a.parent_agent_id,ch.visited||a.id FROM chain ch JOIN public.agents a ON a.id=ch.parent_agent_id AND a.club_id=ch.club_id
   WHERE a.status='active' AND NOT a.id=ANY(ch.visited) AND cardinality(ch.visited)<16
 ), peers AS (
  SELECT DISTINCT m.user_id AS peer_user_id,c.id AS club_id,c.name AS club_name,
   CASE WHEN c.owner_id=m.user_id THEN 'owner' ELSE public.fn_club_messenger_staff_role(c.id,m.user_id) END AS role,
   EXISTS(SELECT 1 FROM chain ch WHERE ch.club_id=c.id AND ch.user_id=m.user_id) AS is_upline
  FROM mine me JOIN public.clubs c ON c.id=me.club_id JOIN public.club_members m ON m.club_id=c.id
  WHERE m.user_id=ANY(p_peers[1:100]) AND m.user_id<>p_viewer AND m.is_active=true
   AND m.status IN ('active','approved') AND m.membership_lifecycle_status='active'
 )
 SELECT peer_user_id,club_id,club_name,role,is_upline,
  CASE WHEN role='owner' THEN 'Owner Of '||club_name WHEN role='co_owner' THEN 'Co Owner Of '||club_name
  ELSE CASE WHEN is_upline THEN 'Your ' ELSE '' END||CASE role WHEN 'admin' THEN 'Admin' WHEN 'super_agent' THEN 'Super Agent' WHEN 'sub_agent' THEN 'Sub Agent' ELSE 'Agent' END||' In '||club_name END
 FROM peers WHERE role IS NOT NULL ORDER BY club_name,club_id,peer_user_id
$$;


ALTER FUNCTION public.fn_messenger_club_relationships(p_viewer uuid, p_peers uuid[]) OWNER TO postgres;

--
-- TOC entry 4113 (class 1255 OID 63221183)
-- Name: fn_messenger_continuity_allowed(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_messenger_continuity_allowed(p_user_id uuid, p_conversation_id uuid, p_lock boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_context uuid; v_club uuid; v_mapping record; v_visible boolean;
BEGIN
  IF p_user_id IS NULL OR p_conversation_id IS NULL THEN RETURN false; END IF;
  IF p_lock THEN
    SELECT context_entity_id INTO v_context FROM public.social_conversation_participants
      WHERE user_id=p_user_id AND conversation_id=p_conversation_id FOR SHARE;
  ELSE
    SELECT context_entity_id INTO v_context FROM public.social_conversation_participants
      WHERE user_id=p_user_id AND conversation_id=p_conversation_id;
  END IF;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.social_conversations c WHERE c.id=p_conversation_id
    AND (NOT COALESCE(c.is_request,false) OR c.request_sender_id=p_user_id)) THEN RETURN false; END IF;
  SELECT * INTO v_mapping FROM public.accounting_conversations WHERE conversation_id=p_conversation_id;
  IF FOUND THEN
    v_club:=v_mapping.scope_id;
    SELECT recipient_visible INTO v_visible FROM public.fn_messenger_private_accounting_threads(p_user_id,ARRAY[p_conversation_id]);
    IF NOT FOUND THEN RAISE EXCEPTION 'Private Conversation Authority Unavailable' USING ERRCODE='55000'; END IF;
    IF NOT ((v_mapping.recipient_id=p_user_id AND COALESCE(v_visible,false))
      OR (v_mapping.sender_id=p_user_id AND v_mapping.last_discussion_at IS NOT NULL)) THEN RETURN false; END IF;
  ELSIF v_context IS NOT NULL THEN
    SELECT linked_entity_id INTO v_club FROM public.social_pages WHERE id=v_context AND linked_entity_type='club';
    IF NOT FOUND THEN RETURN false; END IF;
  END IF;
  IF v_club IS NOT NULL THEN
    IF p_lock THEN
      PERFORM 1 FROM public.club_members WHERE user_id=p_user_id AND club_id=v_club
        AND is_active AND membership_lifecycle_status='active' AND status IN('active','approved') FOR SHARE;
    ELSE
      PERFORM 1 FROM public.club_members WHERE user_id=p_user_id AND club_id=v_club
        AND is_active AND membership_lifecycle_status='active' AND status IN('active','approved');
    END IF;
    IF NOT FOUND THEN RETURN false; END IF;
  END IF;
  RETURN true;
END $$;


ALTER FUNCTION public.fn_messenger_continuity_allowed(p_user_id uuid, p_conversation_id uuid, p_lock boolean) OWNER TO postgres;

--
-- TOC entry 8581 (class 1255 OID 63221190)
-- Name: fn_messenger_continuity_read(uuid, uuid[], timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_messenger_continuity_read(p_user_id uuid, p_conversation_ids uuid[], p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_allowed uuid[]; v_states jsonb; v_saved jsonb;
BEGIN
  IF p_user_id IS NULL OR p_conversation_ids IS NULL OR cardinality(p_conversation_ids)>100
    OR (p_before IS NULL)<>(p_before_id IS NULL) THEN RAISE EXCEPTION 'Invalid Continuity Request' USING ERRCODE='22023'; END IF;
  SELECT COALESCE(array_agg(id),'{}'::uuid[]) INTO v_allowed FROM unnest(p_conversation_ids) id
    WHERE public.fn_messenger_continuity_allowed(p_user_id,id);
  SELECT COALESCE(jsonb_object_agg(ids.id::text,public.fn_messenger_continuity_state(s)),'{}'::jsonb)
    INTO v_states FROM unnest(v_allowed) ids(id)
    LEFT JOIN public.messenger_conversation_state s ON s.user_id=p_user_id AND s.conversation_id=ids.id;
  SELECT COALESCE(jsonb_agg(to_jsonb(items) ORDER BY items."createdAt" DESC,items."messageId" DESC),'[]'::jsonb) INTO v_saved FROM (
    SELECT s.message_id AS "messageId",s.conversation_id AS "conversationId",s.revision,s.is_saved AS saved,s.created_at AS "createdAt"
    FROM public.messenger_saved_messages s WHERE s.user_id=p_user_id AND s.conversation_id=ANY(v_allowed) AND s.is_saved
      AND (p_before IS NULL OR (s.created_at,s.message_id)<(p_before,p_before_id))
      AND EXISTS(SELECT 1 FROM public.fn_messenger_continuity_visible(p_user_id,s.conversation_id) m WHERE m.id=s.message_id)
    ORDER BY s.created_at DESC,s.message_id DESC LIMIT 51
  ) items;
  RETURN jsonb_build_object('success',true,'states',v_states,'saved',v_saved);
END $$;


ALTER FUNCTION public.fn_messenger_continuity_read(p_user_id uuid, p_conversation_ids uuid[], p_before timestamp with time zone, p_before_id uuid) OWNER TO postgres;

--
-- TOC entry 2862 (class 1259 OID 63221002)
-- Name: messenger_conversation_state; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.messenger_conversation_state (
    user_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    draft_text text DEFAULT ''::text NOT NULL,
    draft_reply_to_id uuid,
    draft_revision bigint DEFAULT 0 NOT NULL,
    is_pinned boolean DEFAULT false NOT NULL,
    pin_revision bigint DEFAULT 0 NOT NULL,
    position_message_id uuid,
    position_offset integer DEFAULT 0 NOT NULL,
    position_revision bigint DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT messenger_conversation_state_draft_revision_check CHECK ((draft_revision >= 0)),
    CONSTRAINT messenger_conversation_state_draft_text_check CHECK ((length(draft_text) <= 2000)),
    CONSTRAINT messenger_conversation_state_pin_revision_check CHECK ((pin_revision >= 0)),
    CONSTRAINT messenger_conversation_state_position_offset_check CHECK (((position_offset >= '-100000'::integer) AND (position_offset <= 100000))),
    CONSTRAINT messenger_conversation_state_position_revision_check CHECK ((position_revision >= 0))
);


ALTER TABLE public.messenger_conversation_state OWNER TO postgres;

--
-- TOC entry 4744 (class 1255 OID 63221189)
-- Name: fn_messenger_continuity_state(public.messenger_conversation_state); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_messenger_continuity_state(p_row public.messenger_conversation_state) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT jsonb_build_object(
    'draft',jsonb_build_object('text',COALESCE(p_row.draft_text,''),'replyToId',p_row.draft_reply_to_id,'revision',COALESCE(p_row.draft_revision,0)),
    'pin',jsonb_build_object('value',COALESCE(p_row.is_pinned,false),'revision',COALESCE(p_row.pin_revision,0)),
    'position',jsonb_build_object('messageId',p_row.position_message_id,'offset',COALESCE(p_row.position_offset,0),'revision',COALESCE(p_row.position_revision,0)));
$$;


ALTER FUNCTION public.fn_messenger_continuity_state(p_row public.messenger_conversation_state) OWNER TO postgres;

--
-- TOC entry 8346 (class 1255 OID 63221187)
-- Name: fn_messenger_continuity_visible(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_messenger_continuity_visible(p_user_id uuid, p_conversation_id uuid) RETURNS TABLE(id uuid, created_at timestamp with time zone, sender_id uuid)
    LANGUAGE sql STABLE
    AS $$
  -- SECURITY INVOKER, fully qualified and intentionally no SET clause: this
  -- table expression must inline so anchor/cursor predicates reach indexes
  -- before the private per-message visibility checks. Only service may call.
  SELECT m.id,m.created_at,m.sender_id FROM public.social_messages m
  LEFT JOIN public.accounting_invoice_deliveries d ON d.message_id=m.id
  WHERE m.conversation_id=p_conversation_id AND NOT COALESCE(m.is_deleted,false)
    AND NOT EXISTS(SELECT 1 FROM public.messenger_hidden_messages hidden WHERE hidden.user_id=p_user_id AND hidden.message_id=m.id)
    AND COALESCE(d.delivery_mode,'immediate')<>'weekly_detail'
    AND (public.fn_messenger_message_visible_to(m.id,p_user_id)
      OR public.fn_accounting_correction_legacy_identity(m.id,p_user_id) IS NOT NULL);
$$;


ALTER FUNCTION public.fn_messenger_continuity_visible(p_user_id uuid, p_conversation_id uuid) OWNER TO postgres;

--
-- TOC entry 6674 (class 1255 OID 63221196)
-- Name: fn_messenger_continuity_window(uuid, uuid, text, uuid, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_messenger_continuity_window(p_user_id uuid, p_conversation_id uuid, p_mode text DEFAULT 'latest'::text, p_anchor uuid DEFAULT NULL::uuid, p_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_at_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_target record; v_newer record; v_oldest record; v_latest record; v_ids uuid[]; v_before_count integer;
  v_watermark timestamptz; v_first uuid; v_messages jsonb; v_saved jsonb; v_unavailable boolean:=false; v_older boolean; v_has_newer boolean;
BEGIN
  IF p_mode IS NULL OR p_mode NOT IN('latest','anchor','firstUnread','before','after') OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 200
    OR (p_mode='anchor' AND p_anchor IS NULL) OR (p_mode IN('before','after') AND p_at IS NULL)
    OR (p_mode='after' AND p_at_id IS NULL) THEN RAISE EXCEPTION 'Invalid Message Navigation' USING ERRCODE='22023'; END IF;
  IF NOT public.fn_messenger_continuity_allowed(p_user_id,p_conversation_id) THEN RAISE EXCEPTION 'Conversation Unavailable' USING ERRCODE='42501'; END IF;
  SELECT last_read_at INTO v_watermark FROM public.social_conversation_participants WHERE user_id=p_user_id AND conversation_id=p_conversation_id;
  SELECT NULL::uuid AS id,NULL::timestamptz AS created_at INTO v_target;
  SELECT id INTO v_first FROM public.fn_messenger_continuity_visible(p_user_id,p_conversation_id) m
    WHERE m.sender_id<>p_user_id AND (v_watermark IS NULL OR m.created_at>v_watermark) ORDER BY m.created_at,m.id LIMIT 1;
  IF p_mode IN('anchor','firstUnread') THEN
    SELECT * INTO v_target FROM public.fn_messenger_continuity_visible(p_user_id,p_conversation_id) WHERE id=CASE WHEN p_mode='anchor' THEN p_anchor ELSE v_first END;
    IF NOT FOUND THEN v_unavailable:=p_mode='anchor'; p_mode:='latest'; END IF;
  END IF;
  IF p_mode IN('anchor','firstUnread') THEN
    SELECT count(*) INTO v_before_count FROM (SELECT id FROM public.fn_messenger_continuity_visible(p_user_id,p_conversation_id) m
      WHERE (m.created_at,m.id)<=(v_target.created_at,v_target.id) ORDER BY m.created_at DESC,m.id DESC LIMIT (p_limit/2+1)) q;
    SELECT array_agg(id ORDER BY created_at,id) INTO v_ids FROM (
      SELECT * FROM public.fn_messenger_continuity_visible(p_user_id,p_conversation_id) m WHERE (m.created_at,m.id)>(v_target.created_at,v_target.id)
        ORDER BY m.created_at,m.id LIMIT (p_limit-v_before_count)) q;
    SELECT COALESCE(v_ids,'{}'::uuid[])||COALESCE(array_agg(id),'{}'::uuid[]) INTO v_ids FROM (
      SELECT * FROM public.fn_messenger_continuity_visible(p_user_id,p_conversation_id) m WHERE (m.created_at,m.id)<=(v_target.created_at,v_target.id)
        ORDER BY m.created_at DESC,m.id DESC LIMIT (p_limit-COALESCE(cardinality(v_ids),0))) q;
  ELSIF p_mode='after' THEN
    SELECT array_agg(id) INTO v_ids FROM (SELECT * FROM public.fn_messenger_continuity_visible(p_user_id,p_conversation_id) m
      WHERE (m.created_at,m.id)>(p_at,p_at_id) ORDER BY m.created_at,m.id LIMIT p_limit) q;
  ELSE
    SELECT array_agg(id) INTO v_ids FROM (SELECT * FROM public.fn_messenger_continuity_visible(p_user_id,p_conversation_id) m
      WHERE p_mode='latest' OR m.created_at<p_at OR (p_at_id IS NOT NULL AND m.created_at=p_at AND m.id<p_at_id)
      ORDER BY m.created_at DESC,m.id DESC LIMIT p_limit) q;
  END IF;
  IF COALESCE(cardinality(v_ids),0)=0 THEN
    SELECT EXISTS(SELECT 1 FROM public.fn_messenger_continuity_visible(p_user_id,p_conversation_id) m
      WHERE p_mode='after' AND (m.created_at,m.id)<=(p_at,p_at_id)) INTO v_older;
    SELECT EXISTS(SELECT 1 FROM public.fn_messenger_continuity_visible(p_user_id,p_conversation_id) m
      WHERE p_mode='before' AND (m.created_at>p_at OR (m.created_at=p_at AND (p_at_id IS NULL OR m.id>=p_at_id)))) INTO v_has_newer;
    RETURN jsonb_build_object('messages','[]'::jsonb,'savedItems','[]'::jsonb,'firstUnreadMessageId',v_first,'hasOlder',v_older,'hasNewer',v_has_newer,'anchorMessageId',NULL,'anchorUnavailable',v_unavailable);
  END IF;
  SELECT * INTO v_oldest FROM public.fn_messenger_continuity_visible(p_user_id,p_conversation_id) WHERE id=ANY(v_ids) ORDER BY created_at,id LIMIT 1;
  SELECT * INTO v_latest FROM public.fn_messenger_continuity_visible(p_user_id,p_conversation_id) WHERE id=ANY(v_ids) ORDER BY created_at DESC,id DESC LIMIT 1;
  SELECT * INTO v_newer FROM public.fn_messenger_continuity_visible(p_user_id,p_conversation_id) m WHERE (m.created_at,m.id)>(v_latest.created_at,v_latest.id) ORDER BY m.created_at,m.id LIMIT 1;
  v_has_newer:=FOUND;
  SELECT EXISTS(SELECT 1 FROM public.fn_messenger_continuity_visible(p_user_id,p_conversation_id) m WHERE (m.created_at,m.id)<(v_oldest.created_at,v_oldest.id)) INTO v_older;
  -- The first excluded newer tuple is an exact exclusive cursor, including
  -- timestamp ties. Private financial projection stays owned by its reader.
  SELECT COALESCE(jsonb_agg(to_jsonb(m) ORDER BY m.created_at DESC,m.id DESC),'[]'::jsonb) INTO v_messages
    FROM public.fn_messenger_private_message_page(p_user_id,p_conversation_id,v_newer.created_at,v_newer.id,cardinality(v_ids)) m;
  IF jsonb_array_length(v_messages)<>cardinality(v_ids) OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_messages) m WHERE NOT ((m->>'id')::uuid=ANY(v_ids))) THEN
    RAISE EXCEPTION 'Message Navigation Unavailable' USING ERRCODE='55000'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('messageId',ids.id,'conversationId',p_conversation_id,'saved',COALESCE(s.is_saved,false),'revision',COALESCE(s.revision,0))),'[]'::jsonb)
    INTO v_saved FROM unnest(v_ids) ids(id) LEFT JOIN public.messenger_saved_messages s ON s.user_id=p_user_id AND s.message_id=ids.id AND s.conversation_id=p_conversation_id;
  RETURN jsonb_build_object('messages',v_messages,'savedItems',v_saved,'firstUnreadMessageId',v_first,'hasOlder',v_older,'hasNewer',v_has_newer,
    'anchorMessageId',CASE WHEN p_mode IN('anchor','firstUnread') THEN v_target.id ELSE NULL END,'anchorUnavailable',v_unavailable);
END $$;


ALTER FUNCTION public.fn_messenger_continuity_window(p_user_id uuid, p_conversation_id uuid, p_mode text, p_anchor uuid, p_at timestamp with time zone, p_at_id uuid, p_limit integer) OWNER TO postgres;

--
-- TOC entry 7413 (class 1255 OID 63221191)
-- Name: fn_messenger_continuity_write(uuid, uuid, text, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_messenger_continuity_write(p_user_id uuid, p_conversation_id uuid, p_field text, p_expected_revision bigint, p_value jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE v_state public.messenger_conversation_state%ROWTYPE; v_saved public.messenger_saved_messages%ROWTYPE;
  v_current jsonb; v_revision bigint; v_message uuid; v_ok boolean; v_cleanup boolean;
BEGIN
  IF p_user_id IS NULL OR p_conversation_id IS NULL OR p_field IS NULL OR p_field NOT IN('draft','pin','position','saved')
    OR p_expected_revision IS NULL OR p_expected_revision<0 OR p_value IS NULL THEN
    RAISE EXCEPTION 'Invalid Continuity Request' USING ERRCODE='22023'; END IF;
  IF p_field='draft' THEN
    IF jsonb_typeof(p_value)<>'object' OR jsonb_typeof(p_value->'text') IS DISTINCT FROM 'string'
      OR length(p_value->>'text')>2000 OR (p_value-'text'-'replyToId')<>'{}'::jsonb THEN RAISE EXCEPTION 'Invalid Draft' USING ERRCODE='22023'; END IF;
    v_message:=(p_value->>'replyToId')::uuid;
    p_value:=jsonb_build_object('text',p_value->>'text','replyToId',v_message);
  ELSIF p_field='pin' THEN
    IF jsonb_typeof(p_value)<>'boolean' THEN RAISE EXCEPTION 'Invalid Pin' USING ERRCODE='22023'; END IF;
  ELSIF p_field='position' THEN
    IF jsonb_typeof(p_value)<>'object' OR jsonb_typeof(p_value->'offset') IS DISTINCT FROM 'number'
      OR (p_value->>'offset')!~'^-?[0-9]+$' OR (p_value->>'offset')::numeric NOT BETWEEN -100000 AND 100000
      OR (p_value-'messageId'-'offset')<>'{}'::jsonb THEN RAISE EXCEPTION 'Invalid Reading Position' USING ERRCODE='22023'; END IF;
    v_message:=(p_value->>'messageId')::uuid;
    p_value:=jsonb_build_object('messageId',v_message,'offset',(p_value->>'offset')::integer);
  ELSE
    IF jsonb_typeof(p_value)<>'object' OR jsonb_typeof(p_value->'saved') IS DISTINCT FROM 'boolean'
      OR (p_value-'messageId'-'saved')<>'{}'::jsonb THEN RAISE EXCEPTION 'Invalid Saved Message' USING ERRCODE='22023'; END IF;
    v_message:=(p_value->>'messageId')::uuid;
    IF v_message IS NULL THEN RAISE EXCEPTION 'Invalid Saved Message' USING ERRCODE='22023'; END IF;
    p_value:=jsonb_build_object('messageId',v_message,'saved',(p_value->>'saved')::boolean);
    v_cleanup:=NOT (p_value->>'saved')::boolean;
  END IF;
  -- Removing an already-owned save returns no content and requires no retained
  -- membership. It cannot create a record or probe another account's saves.
  IF COALESCE(v_cleanup,false) THEN
    SELECT * INTO v_saved FROM public.messenger_saved_messages WHERE user_id=p_user_id
      AND conversation_id=p_conversation_id AND message_id=v_message FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Saved Message Unavailable' USING ERRCODE='P0002'; END IF;
  ELSE
    IF NOT public.fn_messenger_continuity_allowed(p_user_id,p_conversation_id,true) THEN
      RAISE EXCEPTION 'Conversation Unavailable' USING ERRCODE='42501'; END IF;
    IF v_message IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.fn_messenger_continuity_visible(p_user_id,p_conversation_id) WHERE id=v_message) THEN
      RAISE EXCEPTION 'Message Unavailable' USING ERRCODE='P0002'; END IF;
  END IF;
  IF p_field='saved' THEN
    IF NOT COALESCE(v_cleanup,false) THEN
      INSERT INTO public.messenger_saved_messages(user_id,conversation_id,message_id) VALUES(p_user_id,p_conversation_id,v_message) ON CONFLICT DO NOTHING;
      SELECT * INTO STRICT v_saved FROM public.messenger_saved_messages WHERE user_id=p_user_id AND message_id=v_message FOR UPDATE;
      IF v_saved.conversation_id<>p_conversation_id THEN RAISE EXCEPTION 'Saved Message Unavailable' USING ERRCODE='P0002'; END IF;
    END IF;
    v_current:=jsonb_build_object('messageId',v_saved.message_id,'saved',v_saved.is_saved); v_revision:=v_saved.revision;
    v_ok:=v_current=p_value OR v_revision=p_expected_revision;
    IF v_ok AND v_current<>p_value THEN
      UPDATE public.messenger_saved_messages SET is_saved=(p_value->>'saved')::boolean,revision=revision+1
        WHERE user_id=p_user_id AND message_id=v_message RETURNING * INTO v_saved;
      v_current:=p_value; v_revision:=v_saved.revision;
    END IF;
    RETURN jsonb_build_object('success',v_ok,'field',p_field,'revision',v_revision,'value',v_current,
      'item',jsonb_build_object('messageId',v_message,'conversationId',p_conversation_id,'saved',v_saved.is_saved,'revision',v_revision));
  END IF;
  INSERT INTO public.messenger_conversation_state(user_id,conversation_id) VALUES(p_user_id,p_conversation_id) ON CONFLICT DO NOTHING;
  SELECT * INTO STRICT v_state FROM public.messenger_conversation_state WHERE user_id=p_user_id AND conversation_id=p_conversation_id FOR UPDATE;
  v_current:=public.fn_messenger_continuity_state(v_state)->p_field;
  v_revision:=(v_current->>'revision')::bigint;
  v_current:=CASE WHEN p_field='pin' THEN v_current->'value' ELSE v_current-'revision' END;
  v_ok:=v_current=p_value OR v_revision=p_expected_revision;
  IF v_ok AND v_current<>p_value THEN
    IF p_field='draft' THEN
      UPDATE public.messenger_conversation_state SET draft_text=p_value->>'text',draft_reply_to_id=v_message,draft_revision=draft_revision+1,updated_at=now()
        WHERE user_id=p_user_id AND conversation_id=p_conversation_id RETURNING * INTO v_state;
    ELSIF p_field='pin' THEN
      UPDATE public.messenger_conversation_state SET is_pinned=p_value::boolean,pin_revision=pin_revision+1,updated_at=now()
        WHERE user_id=p_user_id AND conversation_id=p_conversation_id RETURNING * INTO v_state;
    ELSE
      UPDATE public.messenger_conversation_state SET position_message_id=v_message,position_offset=(p_value->>'offset')::integer,position_revision=position_revision+1,updated_at=now()
        WHERE user_id=p_user_id AND conversation_id=p_conversation_id RETURNING * INTO v_state;
    END IF;
    v_revision:=v_revision+1; v_current:=p_value;
  END IF;
  RETURN jsonb_build_object('success',v_ok,'field',p_field,'revision',v_revision,'value',v_current,'state',public.fn_messenger_continuity_state(v_state));
END $_$;


ALTER FUNCTION public.fn_messenger_continuity_write(p_user_id uuid, p_conversation_id uuid, p_field text, p_expected_revision bigint, p_value jsonb) OWNER TO postgres;

--
-- TOC entry 9145 (class 1255 OID 14612202)
-- Name: fn_messenger_dispatch_scheduled(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_messenger_dispatch_scheduled(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lim   int := GREATEST(LEAST(COALESCE(p_limit, 200), 1000), 1);
  v_sent  int := 0;
  v_failed int := 0;
  r       record;
BEGIN
  FOR r IN
    SELECT s.id, s.conversation_id, s.sender_id, s.text, s.message_type, s.media_url
      FROM messenger_scheduled s
     WHERE s.status = 'pending'
       AND s.scheduled_at <= now()
     ORDER BY s.scheduled_at ASC
     LIMIT v_lim
     FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      -- the sender must still be in the conversation at send time
      IF NOT EXISTS (
        SELECT 1 FROM messenger_participants p
         WHERE p.conversation_id = r.conversation_id
           AND p.user_id = r.sender_id
      ) THEN
        UPDATE messenger_scheduled
           SET status = 'failed', updated_at = now()
         WHERE id = r.id;
        v_failed := v_failed + 1;
        CONTINUE;
      END IF;

      INSERT INTO messenger_messages
        (conversation_id, sender_id, text, message_type, media_url, status)
      VALUES
        (r.conversation_id, r.sender_id, r.text,
         COALESCE(NULLIF(r.message_type, ''), 'text'), r.media_url, 'sent');

      UPDATE messenger_conversations
         SET last_message_text = left(COALESCE(r.text, ''), 200),
             last_message_at   = now(),
             updated_at        = now()
       WHERE id = r.conversation_id;

      UPDATE messenger_scheduled
         SET status = 'sent', updated_at = now()
       WHERE id = r.id;

      v_sent := v_sent + 1;
    EXCEPTION WHEN OTHERS THEN
      -- one bad row must not stop the batch
      UPDATE messenger_scheduled
         SET status = 'failed', updated_at = now()
       WHERE id = r.id;
      v_failed := v_failed + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'sent', v_sent, 'failed', v_failed,
                            'ran_at', now());
END;
$$;


ALTER FUNCTION public.fn_messenger_dispatch_scheduled(p_limit integer) OWNER TO postgres;

--
-- TOC entry 5921 (class 1255 OID 137588382)
-- Name: fn_messenger_hide_message(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_messenger_hide_message(p_message_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_conversation uuid;
BEGIN
 IF NOT public.fn_caller_is_engine() OR p_user_id IS NULL OR p_message_id IS NULL THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 SELECT conversation_id INTO v_conversation FROM public.social_messages WHERE id=p_message_id;
 IF v_conversation IS NULL OR NOT public.fn_messenger_continuity_allowed(p_user_id,v_conversation) THEN RETURN jsonb_build_object('success',false); END IF;
 IF EXISTS(SELECT 1 FROM public.messenger_hidden_messages WHERE user_id=p_user_id AND message_id=p_message_id) THEN RETURN jsonb_build_object('success',true,'message_id',p_message_id); END IF;
 INSERT INTO public.messenger_hidden_messages(user_id,message_id)
 SELECT p_user_id,m.id FROM public.fn_messenger_continuity_visible(p_user_id,v_conversation) m WHERE m.id=p_message_id
 ON CONFLICT(user_id,message_id) DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM public.messenger_hidden_messages WHERE user_id=p_user_id AND message_id=p_message_id) THEN RETURN jsonb_build_object('success',false); END IF;
 RETURN jsonb_build_object('success',true,'message_id',p_message_id);
END $$;


ALTER FUNCTION public.fn_messenger_hide_message(p_message_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 5021 (class 1255 OID 34785878)
-- Name: fn_messenger_invoice_visible_to(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_messenger_invoice_visible_to(p_invoice_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF p_user_id IS NULL OR (NOT public.fn_caller_is_engine() AND auth.uid() IS DISTINCT FROM p_user_id)
 THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM public.settlement_invoices i WHERE i.id=p_invoice_id
   AND (i.invoice_type<>'credit_limit_change' OR EXISTS(
    SELECT 1 FROM public.accounting_credit_change_documents_v1 cd
    JOIN public.accounting_invoice_deliveries d ON d.invoice_id=cd.invoice_id
     AND d.recipient_id=p_user_id AND d.delivery_mode='immediate'
    WHERE cd.invoice_id=i.id AND p_user_id=ANY(cd.audience_user_ids)
     AND public.fn_accounting_credit_change_contract_v1(i.id) IS NOT NULL))
   AND NOT public.fn_accounting_correction_is_unverified(i.id)
   AND (i.invoice_type<>'accounting_correction' OR EXISTS(SELECT 1 FROM public.accounting_correction_documents cd JOIN public.accounting_invoice_deliveries d ON d.invoice_id=cd.invoice_id AND d.recipient_id=p_user_id AND d.delivery_mode='immediate' WHERE cd.invoice_id=i.id AND p_user_id=ANY(cd.audience_user_ids)))
   AND (i.invoice_type<>'cashier_cashout' OR EXISTS(SELECT 1 FROM public.accounting_cashier_events ce
     WHERE ce.invoice_id=i.id AND p_user_id=ANY(ce.audience_user_ids)))
   -- Addressed to a person: the sender, the ledger link and the category are
   -- not what makes it private, so they are not asked about any more.
   AND (i.to_entity_type NOT IN('agent','player')
     OR EXISTS(SELECT 1 FROM public.accounting_invoice_deliveries d
       WHERE d.invoice_id=i.id AND d.recipient_id=p_user_id AND d.delivery_mode='immediate')));
END $$;


ALTER FUNCTION public.fn_messenger_invoice_visible_to(p_invoice_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 7252 (class 1255 OID 31416613)
-- Name: fn_messenger_message_page(uuid, uuid, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_messenger_message_page(p_user_id uuid, p_conversation_id uuid, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, conversation_id uuid, sender_id uuid, content text, message_type text, media_metadata jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, is_deleted boolean, is_edited boolean, profiles jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF p_limit IS NULL OR p_limit<1 OR p_limit>200 OR (p_before_id IS NOT NULL AND p_before IS NULL) THEN
   RAISE EXCEPTION 'invalid_message_page' USING ERRCODE='22023'; END IF;
 IF (NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR auth.uid()<>p_user_id))
 OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants p WHERE p.user_id=p_user_id AND p.conversation_id=p_conversation_id) THEN
   RAISE EXCEPTION 'message_page_not_authorised' USING ERRCODE='42501'; END IF;
 RETURN QUERY SELECT m.id,m.conversation_id,m.sender_id,CASE WHEN legacy.identity IS NOT NULL THEN 'Correction receipt unavailable.' WHEN i.invoice_type='credit_limit_change' THEN 'This records a credit-capacity change. No chips were transferred and no payment is due.' ELSE m.content END,
   CASE WHEN m.message_type='invoice' AND i.id IS NULL THEN 'text' ELSE m.message_type END,
   (CASE WHEN legacy.identity IS NOT NULL THEN legacy.identity
 WHEN i.invoice_type='credit_limit_change' THEN jsonb_build_object(
  'kind','accounting_invoice','accounting_verified',true,'invoice_id',i.id,'invoice_type',i.invoice_type,
  'club_id',i.club_id,'source_ledger_id',NULL,'amount',round(i.net_amount,2)::text,
  'status','generated','chips_transferred',false,'due_at',NULL,'transferred_at',NULL,
  'cashier_verified',false,'correction_verified',false,'credit_change_verified',true,
  'credit_change',public.fn_accounting_credit_change_contract_v1(i.id)) ELSE
 ((COALESCE(m.media_metadata,'{}') #- '{lines,private_bank_ledger_ids}'::text[] #- '{lines,source_ledger_ids}'::text[] #- '{lines,standalone_bank_ledger_ids}'::text[] #- '{lines,standalone_bank_mint_ids}'::text[])-ARRAY['cashier','cashier_verified','correction','correction_verified','correction_unverified','invoice_identity_verified','credit_change','credit_change_verified'])
 ||CASE WHEN i.id IS NULL THEN jsonb_build_object('accounting_verified',false,'cashier_verified',false,'correction_verified',false,'credit_change_verified',false)
 ELSE jsonb_build_object('accounting_verified',true,'invoice_id',i.id,'issued_status',m.media_metadata->'status',
  'status',i.status,'chips_transferred',i.chips_transferred,'invoice_type',i.invoice_type,'source_ledger_id',i.source_ledger_id,'club_id',i.club_id,
  'cashier_verified',i.invoice_type='cashier_cashout','correction_verified',i.invoice_type='accounting_correction')
 ||CASE WHEN i.invoice_type='cashier_cashout' THEN jsonb_build_object('amount',round(i.net_amount,2)::text,'cashier',public.fn_cashier_invoice_contract(i.id))
 WHEN i.invoice_type='accounting_correction' THEN jsonb_build_object('amount',round(i.net_amount,2)::text,'due_at',i.due_at,'transferred_at',i.transferred_at,
  'union_id',(SELECT c.union_id FROM public.accounting_correction_documents c WHERE c.invoice_id=i.id),
  'correction',public.fn_accounting_correction_contract(i.id)) ELSE '{}'::jsonb END END END)
 ||CASE WHEN i.id IS NOT NULL THEN jsonb_build_object('conversation_id',m.conversation_id,'conversationId',m.conversation_id) ELSE '{}'::jsonb END,
   m.created_at,m.updated_at,m.is_deleted,m.is_edited,
   jsonb_build_object('id',pr.id,'username',pr.username,'avatar_url',pr.avatar_url,'is_vip',pr.is_vip)
 FROM public.social_messages m
 LEFT JOIN public.accounting_invoice_deliveries d ON d.message_id=m.id
 LEFT JOIN public.settlement_invoices i ON i.id=d.invoice_id
 LEFT JOIN LATERAL(SELECT public.fn_accounting_correction_legacy_identity(m.id,p_user_id) AS identity) legacy ON true
 LEFT JOIN public.profiles pr ON pr.id=m.sender_id
 WHERE m.conversation_id=p_conversation_id AND COALESCE(m.is_deleted,false)=false
    AND NOT EXISTS(SELECT 1 FROM public.messenger_hidden_messages hidden WHERE hidden.user_id=p_user_id AND hidden.message_id=m.id)
   AND COALESCE(d.delivery_mode,'immediate')<>'weekly_detail'
     AND (public.fn_messenger_message_visible_to(m.id,p_user_id) OR legacy.identity IS NOT NULL)
   AND (p_before IS NULL OR m.created_at<p_before OR (p_before_id IS NOT NULL AND m.created_at=p_before AND m.id<p_before_id))
 ORDER BY m.created_at DESC,m.id DESC LIMIT p_limit;
END $$;


ALTER FUNCTION public.fn_messenger_message_page(p_user_id uuid, p_conversation_id uuid, p_before timestamp with time zone, p_before_id uuid, p_limit integer) OWNER TO postgres;

--
-- TOC entry 8052 (class 1255 OID 34785879)
-- Name: fn_messenger_message_visible_to(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_messenger_message_visible_to(p_message_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF p_user_id IS NULL OR (NOT public.fn_caller_is_engine() AND auth.uid() IS DISTINCT FROM p_user_id)
 THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM public.social_messages m
   JOIN public.social_conversation_participants p ON p.conversation_id=m.conversation_id AND p.user_id=p_user_id
   LEFT JOIN public.accounting_invoice_deliveries d ON d.message_id=m.id
   WHERE m.id=p_message_id AND NOT COALESCE(m.is_deleted,false)
     AND COALESCE(d.delivery_mode,'immediate')<>'weekly_detail'
     AND (d.invoice_id IS NULL OR public.fn_messenger_invoice_visible_to(d.invoice_id,p_user_id)));
END $$;


ALTER FUNCTION public.fn_messenger_message_visible_to(p_message_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 4536 (class 1255 OID 34785880)
-- Name: fn_messenger_notification_visible_to(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_messenger_notification_visible_to(p_notification_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF p_user_id IS NULL OR (NOT public.fn_caller_is_engine() AND auth.uid() IS DISTINCT FROM p_user_id)
 THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM public.notifications n
   LEFT JOIN public.accounting_invoice_deliveries d ON d.notification_id=n.id
   WHERE n.id=p_notification_id AND n.user_id=p_user_id AND n.type IS DISTINCT FROM 'accounting_invoice_detail' AND COALESCE(n.data->>'_push','') <> 'ledger_only'
     AND COALESCE(d.delivery_mode,'immediate')<>'weekly_detail'
     AND (d.invoice_id IS NULL OR public.fn_messenger_invoice_visible_to(d.invoice_id,p_user_id)));
END $$;


