--
-- TOC entry 6724 (class 1255 OID 111652120)
-- Name: fn_messenger_private_invoice_attention(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_messenger_private_invoice_attention(p_user_id uuid, p_conversation_ids uuid[]) RETURNS TABLE(conversation_id uuid, requires_action boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_conversation_ids IS NULL OR cardinality(p_conversation_ids) = 0 OR cardinality(p_conversation_ids) > 100 THEN RAISE EXCEPTION 'Invalid Messenger invoice attention request' USING ERRCODE = '22023'; END IF;
  RETURN QUERY SELECT ac.conversation_id, COALESCE(bool_or(COALESCE(d.delivery_mode, 'immediate') <> 'weekly_detail' AND i.status IN ('pending', 'generated', 'overdue')), false) AS requires_action FROM public.accounting_conversations ac LEFT JOIN public.social_messages m ON m.conversation_id = ac.conversation_id LEFT JOIN public.accounting_invoice_deliveries d ON d.message_id = m.id AND d.recipient_id = p_user_id LEFT JOIN public.settlement_invoices i ON i.id = d.invoice_id WHERE ac.conversation_id = ANY(p_conversation_ids) AND ac.recipient_id = p_user_id AND EXISTS (SELECT 1 FROM public.club_members cm WHERE cm.club_id = ac.scope_id AND cm.user_id = p_user_id AND cm.is_active AND cm.membership_lifecycle_status = 'active' AND cm.status IN ('active', 'approved')) GROUP BY ac.conversation_id;
END
$$;


