--

CREATE FUNCTION public.fn_messenger_search_messages(p_user_id uuid, p_conversation_ids uuid[], p_query text, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, conversation_id uuid, sender_id uuid, content text, created_at timestamp with time zone, message_type text, media_metadata jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF p_limit IS NULL OR p_limit<1 OR p_limit>100 OR p_conversation_ids IS NULL OR
    cardinality(p_conversation_ids)>500 OR cardinality(p_conversation_ids)<1 OR
    p_query IS NULL OR length(btrim(p_query))<2 OR length(p_query)>500 THEN
   RAISE EXCEPTION 'invalid_message_search' USING ERRCODE='22023'; END IF;
 IF (NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR auth.uid()<>p_user_id)) OR
    EXISTS(SELECT 1 FROM unnest(p_conversation_ids) AS requested(conversation_id)
      WHERE NOT EXISTS(SELECT 1 FROM public.social_conversation_participants p
        WHERE p.user_id=p_user_id AND p.conversation_id=requested.conversation_id)) THEN
   RAISE EXCEPTION 'message_search_not_authorised' USING ERRCODE='42501'; END IF;
 RETURN QUERY SELECT m.id,m.conversation_id,m.sender_id,CASE WHEN legacy.identity IS NOT NULL THEN 'Correction receipt unavailable.' WHEN i.invoice_type='credit_limit_change' THEN 'This records a credit-capacity change. No chips were transferred and no payment is due.' ELSE m.content END,m.created_at,
   CASE WHEN m.message_type='invoice' AND i.id IS NULL THEN 'text' ELSE m.message_type END,
   (CASE WHEN legacy.identity IS NOT NULL THEN legacy.identity
 WHEN i.invoice_type='credit_limit_change' THEN jsonb_build_object(
  'kind','accounting_invoice','accounting_verified',true,'invoice_id',i.id,'invoice_type',i.invoice_type,
  'club_id',i.club_id,'source_ledger_id',NULL,'amount',round(i.net_amount,2)::text,
  'status','generated','chips_transferred',false,'due_at',NULL,'transferred_at',NULL,
  'cashier_verified',false,'correction_verified',false,'credit_change_verified',true,
  'credit_change',public.fn_accounting_credit_change_contract_v1(i.id)) ELSE
 ((COALESCE(m.media_metadata,'{}') #- '{lines,private_bank_ledger_ids}'::text[] #- '{lines,source_ledger_ids}'::text[] #- '{lines,standalone_bank_ledger_ids}'::text[] #- '{lines,standalone_bank_mint_ids}'::text[])-ARRAY['cashier','cashier_verified','correction','correction_verified','correction_unverified','invoice_identity_verified','credit_change','credit_change_verified'])
 ||CASE WHEN i.id IS NULL THEN jsonb_build_object('accounting_verified',false,'cashier_verified',false,'correction_verified',false,'credit_change_verified',false)
 ELSE jsonb_build_object('accounting_verified',true,'invoice_id',i.id,'issued_status',m.media_metadata->'status',
  'status',i.status,'chips_transferred',i.chips_transferred,'invoice_type',i.invoice_type,'source_ledger_id',i.source_ledger_id,'club_id',i.club_id,
  'cashier_verified',i.invoice_type='cashier_cashout','correction_verified',i.invoice_type='accounting_correction')
 ||CASE WHEN i.invoice_type='cashier_cashout' THEN jsonb_build_object('amount',round(i.net_amount,2)::text,'cashier',public.fn_cashier_invoice_contract(i.id))
 WHEN i.invoice_type='accounting_correction' THEN jsonb_build_object('amount',round(i.net_amount,2)::text,'due_at',i.due_at,'transferred_at',i.transferred_at,
  'union_id',(SELECT c.union_id FROM public.accounting_correction_documents c WHERE c.invoice_id=i.id),
  'correction',public.fn_accounting_correction_contract(i.id)) ELSE '{}'::jsonb END END END)
 ||CASE WHEN i.id IS NOT NULL THEN jsonb_build_object('conversation_id',m.conversation_id,'conversationId',m.conversation_id) ELSE '{}'::jsonb END
 FROM public.social_messages m
 LEFT JOIN public.accounting_invoice_deliveries d ON d.message_id=m.id
 LEFT JOIN public.settlement_invoices i ON i.id=d.invoice_id
 LEFT JOIN LATERAL(SELECT public.fn_accounting_correction_legacy_identity(m.id,p_user_id) AS identity) legacy ON true
 WHERE m.conversation_id=ANY(p_conversation_ids) AND COALESCE(m.is_deleted,false)=false
    AND NOT EXISTS(SELECT 1 FROM public.messenger_hidden_messages hidden WHERE hidden.user_id=p_user_id AND hidden.message_id=m.id)
   AND COALESCE(d.delivery_mode,'immediate')<>'weekly_detail'
     AND (public.fn_messenger_message_visible_to(m.id,p_user_id) OR legacy.identity IS NOT NULL)
   AND strpos(lower(CASE WHEN legacy.identity IS NOT NULL THEN 'Correction receipt unavailable.' WHEN i.invoice_type='credit_limit_change' THEN 'This records a credit-capacity change. No chips were transferred and no payment is due.' ELSE m.content END),lower(btrim(p_query)))>0
 ORDER BY m.created_at DESC,m.id DESC LIMIT p_limit;
END $$;


ALTER FUNCTION public.fn_messenger_search_messages(p_user_id uuid, p_conversation_ids uuid[], p_query text, p_limit integer) OWNER TO postgres;

--
-- TOC entry 6492 (class 1255 OID 63054985)
-- Name: fn_messenger_send_allowed(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_messenger_send_allowed(p_conversation_id uuid, p_sender_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT p_sender_id IS NOT NULL
    AND EXISTS (SELECT 1 FROM public.social_conversation_participants p
      WHERE p.conversation_id=p_conversation_id AND p.user_id=p_sender_id)
    AND NOT EXISTS (
      SELECT 1 FROM public.social_conversation_participants p
      JOIN public.messenger_blocked b ON
        (b.blocker_id=p_sender_id AND b.blocked_id=p.user_id)
        OR (b.blocked_id=p_sender_id AND b.blocker_id=p.user_id)
      WHERE p.conversation_id=p_conversation_id AND p.user_id<>p_sender_id
    );
$$;


ALTER FUNCTION public.fn_messenger_send_allowed(p_conversation_id uuid, p_sender_id uuid) OWNER TO postgres;

--
-- TOC entry 4119 (class 1255 OID 218291183)
-- Name: fn_midway_cash_rake_write_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_midway_cash_rake_write_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_union uuid; v_asset text;
BEGIN
  IF TG_TABLE_NAME='clubs' THEN
    IF NEW.asset='diamonds' THEN RETURN NEW; END IF;
    IF NEW.union_id='fade0000-0000-0000-0000-000000000001'::uuid
       OR NEW.id='fade0000-0000-0000-0000-000000000001'::uuid THEN
      NEW.rake_cap := CASE WHEN NEW.rake_cap > 2.5 THEN 2.5 ELSE NEW.rake_cap END;
      IF NEW.default_rake_percent > 10 THEN
        RAISE EXCEPTION 'Midway Cash Rake Is Limited To 10 Percent And 2.5 BB';
      END IF;
    END IF;
  ELSE
    IF NEW.tournament_id IS NOT NULL THEN RETURN NEW; END IF;
    SELECT c.union_id,c.asset INTO v_union,v_asset FROM public.clubs c WHERE c.id=NEW.club_id;
    IF v_asset='diamonds' THEN RETURN NEW; END IF;
    IF NEW.union_id='fade0000-0000-0000-0000-000000000001'::uuid
       OR v_union='fade0000-0000-0000-0000-000000000001'::uuid THEN
      NEW.rake_cap_bb := CASE WHEN NEW.rake_cap_bb > 2.5 THEN 2.5 ELSE NEW.rake_cap_bb END;
      IF NEW.rake_percent > 10 THEN
        RAISE EXCEPTION 'Midway Cash Rake Is Limited To 10 Percent And 2.5 BB';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_midway_cash_rake_write_guard() OWNER TO postgres;

--
-- TOC entry 4117 (class 1255 OID 174968964)
-- Name: fn_midway_weekly_horse_promo(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_midway_weekly_horse_promo(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
 v_midway constant uuid := 'fade0000-0000-0000-0000-000000000001';
 v_open numeric; v_budget numeric; v_cents bigint; v_n integer; v_i integer:=0;
 v_each bigint; v_extra bigint; v_amount numeric; v_paid numeric:=0; v_paid_n integer:=0;
 v_run uuid; v_op uuid; v_wallets jsonb; v_wallet jsonb; v_result jsonb; v_prior jsonb;
 v_saved jsonb; v_key text; v_note text;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'midway_promo_service_required' USING ERRCODE='42501'; END IF;
 IF p_from IS NULL OR p_to IS NULL
    OR p_from IS DISTINCT FROM public.fn_union_week_start(p_from)
    OR p_to IS DISTINCT FROM public.fn_union_week_start(p_from+interval '8 days')
    OR clock_timestamp()<public.fn_union_accounting_run_at(p_to)
    OR p_to<'2026-10-19 07:00:00+00'::timestamptz THEN
  RAISE EXCEPTION 'midway_promo_invalid_completed_week' USING ERRCODE='23514';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('midway-weekly-promo:'||extract(epoch FROM p_to)::text,0));
 SELECT result INTO v_prior FROM public.union_weekly_horse_promo_runs
  WHERE union_id=v_midway AND period_start=p_from AND period_end=p_to;
 IF FOUND THEN
  RETURN v_prior||jsonb_build_object('replayed',true);
 END IF;
 IF public.fn_platform_frozen() THEN RAISE EXCEPTION 'midway_promo_platform_frozen'; END IF;
 SELECT promo_wallet INTO v_open FROM public.union_wallets WHERE union_id=v_midway FOR UPDATE;
 IF v_open IS NULL OR v_open<0 THEN RAISE EXCEPTION 'midway_promo_wallet_invalid'; END IF;
 v_budget:=trunc(v_open/2,2); v_cents:=(v_budget*100)::bigint;
 -- Lock and snapshot each eligible CLUB wallet before calculating shares.
 -- No union-wide balance aggregate and no duplicate membership expansion.
 SELECT COALESCE(jsonb_agg(to_jsonb(w) ORDER BY w.club_id,w.user_id),'[]'::jsonb) INTO v_wallets FROM (
  SELECT m.club_id,m.user_id,m.chip_balance AS opening_balance
   FROM public.club_members m JOIN public.profiles p ON p.id=m.user_id
   JOIN public.clubs c ON c.id=m.club_id
   WHERE c.union_id=v_midway
    AND ((c.id=v_midway AND c.is_union IS TRUE) OR EXISTS(
      SELECT 1 FROM public.union_clubs uc WHERE uc.club_id=c.id AND uc.union_id=v_midway))
    AND p.is_horse IS TRUE
    AND p.horse_status IS DISTINCT FROM 'disabled'
    AND m.is_active IS TRUE AND m.status IN('active','approved')
    AND m.membership_lifecycle_status='active' AND m.chip_balance<10000
   ORDER BY m.club_id,m.user_id FOR UPDATE OF m FOR SHARE OF p,c
 )w;
 v_n:=jsonb_array_length(v_wallets); v_run:=gen_random_uuid();
 v_note:='Midway Weekly Promo Distribution: '||to_char(p_from AT TIME ZONE 'America/Los_Angeles','YYYY-MM-DD');
 INSERT INTO public.union_weekly_horse_promo_runs(id,union_id,period_start,period_end,opening_promo,budget,paid,eligible_wallets,paid_wallets,result)
 VALUES(v_run,v_midway,p_from,p_to,v_open,v_budget,0,v_n,0,'{}');
 -- Save/restore the caller's transaction-local ledger declaration.
 SELECT jsonb_object_agg(k,COALESCE(current_setting(k,true),'')) INTO v_saved FROM unnest(ARRAY[
  'app.ledger_category','app.ledger_counterparty','app.ledger_counterparty_entity',
  'app.ledger_settlement','app.ledger_idempotency_key','app.ledger_counterparty_label',
  'app.ledger_correlation','app.ledger_autoskip_union_wallets','app.ledger_autoskip_clubs'])k;
 -- A promo run owns its settlement identity, not the preceding rakeback round.
 PERFORM set_config('app.ledger_settlement',v_run::text,true);
 IF v_n>0 AND v_cents>0 THEN
  v_each:=v_cents/v_n; v_extra:=v_cents%v_n;
  FOR v_wallet IN SELECT value FROM jsonb_array_elements(v_wallets) LOOP
   v_i:=v_i+1; v_amount:=(v_each+CASE WHEN v_i<=v_extra THEN 1 ELSE 0 END)::numeric/100;
   IF v_amount=0 THEN CONTINUE; END IF;
   v_op:=md5('midway-weekly-promo:'||extract(epoch FROM p_to)::text||':'||(v_wallet->>'club_id')||':'||(v_wallet->>'user_id'))::uuid;
   v_result:=public.fn_promo_disburse('union',v_midway,'player',(v_wallet->>'user_id')::uuid,
    v_amount,v_note,(v_wallet->>'club_id')::uuid,v_op);
   IF v_result->>'success' IS DISTINCT FROM 'true' OR v_result->>'replayed'='true' THEN
    RAISE EXCEPTION 'midway_promo_disbursement_not_confirmed' USING DETAIL=v_result::text;
   END IF;
   INSERT INTO public.union_weekly_horse_promo_recipients(run_id,club_id,user_id,opening_balance,amount,balance_after,operation_id,transaction_id)
   VALUES(v_run,(v_wallet->>'club_id')::uuid,(v_wallet->>'user_id')::uuid,(v_wallet->>'opening_balance')::numeric,
    v_amount,(v_result->>'recipient_after')::numeric,v_op,(v_result->>'transaction_id')::uuid);
   v_paid:=v_paid+v_amount; v_paid_n:=v_paid_n+1;
  END LOOP;
 END IF;
 FOR v_key IN SELECT jsonb_object_keys(v_saved) LOOP PERFORM set_config(v_key,v_saved->>v_key,true); END LOOP;
 IF v_paid<>(CASE WHEN v_n>0 THEN v_budget ELSE 0 END)
    OR (SELECT promo_wallet FROM public.union_wallets WHERE union_id=v_midway)<>v_open-v_paid THEN
  RAISE EXCEPTION 'midway_promo_conservation_failed';
 END IF;
 v_result:=jsonb_build_object('success',true,'run_id',v_run,'opening_promo',v_open,'budget',v_budget,
  'paid',v_paid,'eligible_wallets',v_n,'paid_wallets',v_paid_n,'remaining_promo',v_open-v_paid,
  'eligibility','each_club_chip_balance_under_10000','reason',CASE WHEN v_n=0 THEN 'no_eligible_wallets' WHEN v_cents=0 THEN 'no_distributable_chips' ELSE 'paid' END);
 UPDATE public.union_weekly_horse_promo_runs SET paid=v_paid,paid_wallets=v_paid_n,result=v_result WHERE id=v_run;
 RETURN v_result||jsonb_build_object('replayed',false);
END $$;


ALTER FUNCTION public.fn_midway_weekly_horse_promo(p_from timestamp with time zone, p_to timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 4739 (class 1255 OID 174968970)
-- Name: fn_midway_weekly_horse_promo_close(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_midway_weekly_horse_promo_close() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_result jsonb;
BEGIN
 IF NEW.union_id IS DISTINCT FROM 'fade0000-0000-0000-0000-000000000001'::uuid
  OR NEW.standalone_club_id IS NOT NULL OR NEW.status IS DISTINCT FROM 'complete'
  OR NEW.period_end<'2026-10-19 07:00:00+00'::timestamptz THEN RETURN NEW; END IF;
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'midway_promo_service_required' USING ERRCODE='42501';END IF;
 IF NEW.result->>'success' IS DISTINCT FROM 'true' THEN
  RAISE EXCEPTION 'midway_promo_invalid_completed_week' USING ERRCODE='23514';END IF;
 -- Completion observes the weekly payment; it never starts a late payment
 -- from today's wallet for an old book whose scheduled step was not run.
 SELECT result INTO v_result FROM public.union_weekly_horse_promo_runs
  WHERE union_id=NEW.union_id AND period_start=NEW.period_start AND period_end=NEW.period_end;
 IF NOT FOUND THEN v_result:=jsonb_build_object('success',false,'pending',true,'period_end',NEW.period_end);END IF;
 NEW.result:=NEW.result||jsonb_build_object('weekly_horse_promo',v_result-'replayed');
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_midway_weekly_horse_promo_close() OWNER TO postgres;

--
-- TOC entry 7832 (class 1255 OID 174968971)
-- Name: fn_midway_weekly_horse_promo_due(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_midway_weekly_horse_promo_due(p_period_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_to timestamptz:=COALESCE(p_period_end,public.fn_union_week_start(clock_timestamp()));
 v_from timestamptz;v_result jsonb;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'midway_promo_service_required' USING ERRCODE='42501';END IF;
 IF v_to<'2026-10-19 07:00:00+00'::timestamptz OR clock_timestamp()<public.fn_union_accounting_run_at(v_to) THEN
  RETURN jsonb_build_object('success',true,'advanced',false,'reason','not_due');END IF;
 IF EXISTS(SELECT FROM public.union_weekly_horse_promo_runs WHERE union_id='fade0000-0000-0000-0000-000000000001' AND period_end=v_to) THEN
  RETURN jsonb_build_object('success',true,'advanced',false,'reason','already_paid');END IF;
 IF public.fn_platform_frozen() THEN
  RETURN jsonb_build_object('success',true,'advanced',false,'owns_tick',true,'reason','maintenance_window');END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('union-accounting-scheduler',0)) THEN
  RETURN jsonb_build_object('success',true,'advanced',false,'owns_tick',true,'reason','already_running');END IF;
 v_from:=public.fn_union_week_start(v_to-interval '1 day');
 v_result:=public.fn_midway_weekly_horse_promo(v_from,v_to);
 RETURN jsonb_build_object('success',true,'advanced',v_result->>'replayed' IS DISTINCT FROM 'true',
  'owns_tick',true,'weekly_horse_promo',v_result-'replayed');
END $$;


ALTER FUNCTION public.fn_midway_weekly_horse_promo_due(p_period_end timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 8280 (class 1255 OID 15964624)
-- Name: fn_mint_chips_from_diamonds(uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mint_chips_from_diamonds(p_club_id uuid, p_diamonds numeric, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_op_id uuid := coalesce(p_op_id, gen_random_uuid());
  v_prior record;
  v_diamonds numeric;
  v_chips numeric;
  v_rate integer;
  v_deduct jsonb;
  v_diamonds_after numeric;
  v_club record;
  v_is_union_minter boolean := false;
  v_pool_after numeric;
  v_union_bank_after numeric;
begin
  if v_actor is null then
    return jsonb_build_object('success', false, 'error', 'Not Authenticated');
  end if;
  if p_diamonds is null or p_diamonds <= 0 or p_diamonds <> floor(p_diamonds) then
    return jsonb_build_object('success', false, 'error', 'Diamonds Must Be A Positive Whole Number');
  end if;
  if p_diamonds > 1000000 then
    return jsonb_build_object('success', false, 'error', 'Maximum 1,000,000 Diamonds Per Mint');
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_club_id::text || ':' || v_op_id::text, 0));

  select amount, transaction_type, metadata, balance_after into v_prior
    from chip_transactions
   where transaction_type = 'mint'
     and club_id = p_club_id
     and metadata ->> 'op_id' = v_op_id::text
   limit 1;
  if found then
    return jsonb_build_object('success', true, 'replayed', true,
      'scope', v_prior.metadata ->> 'scope',
      'chips', v_prior.amount,
      'diamonds_spent', (v_prior.metadata ->> 'diamonds_spent')::numeric,
      'diamonds_after', (select coalesce(diamonds, 0) from profiles where id = v_actor),
      'club_pool_after', case when (v_prior.metadata ->> 'scope') = 'club'
                              then v_prior.balance_after end,
      'union_bank_after', case when (v_prior.metadata ->> 'scope') = 'union'
                               then v_prior.balance_after end);
  end if;

  v_diamonds := p_diamonds;
  -- THE RATE IS A ROW (Dan 2026-09-07: 1 diamond = $0.01, 1 chip = $1.00).
  -- Read from ca_bridge_rate; never a literal in this body again.
  v_rate := public.fn_ca_bridge_rate();
  if v_rate is null or v_rate <= 0 then
    return jsonb_build_object('success', false, 'error', 'The Bridge Rate Is Not Set');
  end if;
  v_chips := round(v_diamonds / v_rate, 2);
  if v_chips <= 0 or v_chips * v_rate <> v_diamonds then
    return jsonb_build_object('success', false,
      'error', format('Diamonds Must Convert To Whole Cents Of Chips At %s Diamonds Per Chip', v_rate));
  end if;

  select id, name, union_id, owner_id into v_club
    from clubs where id = p_club_id for update;
  if v_club.id is null then
    return jsonb_build_object('success', false, 'error', 'That Club Could Not Be Found');
  end if;

  if v_club.union_id is not null then
    if exists (select 1 from unions u where u.id = v_club.union_id and u.owner_id = v_actor)
       or exists (select 1 from union_admins ua where ua.union_id = v_club.union_id and ua.user_id = v_actor) then
      v_is_union_minter := true;
    end if;
    if not v_is_union_minter then
      return jsonb_build_object('success', false,
        'error', 'Chip Mint Is Revoked For Clubs In A Union. Chips Flow From The Union. Ask Your Union Owner');
    end if;

    v_deduct := deduct_diamonds(
      v_actor, v_diamonds::integer,
      'Chip Mint: ' || v_chips::text || ' chips minted to union bank',
      'chip_mint', 'chip_mint',
      jsonb_build_object('club_id', p_club_id, 'union_id', v_club.union_id,
                         'chips', v_chips, 'op_id', v_op_id, 'diamonds_per_chip', v_rate),
      null, 0);
    if coalesce((v_deduct->>'success')::boolean, false) = false then
      return jsonb_build_object('success', false,
        'error', coalesce(v_deduct->>'error', 'That Diamond Deduction Did Not Go Through'));
    end if;
    select coalesce(diamonds, 0) into v_diamonds_after from profiles where id = v_actor;

    /* THE MINT (chip standard 3.1, 2026-09-04): chips bought with diamonds
       are ISSUED. Declared issuance_reserve -> union_bank with the op id as
       the journal key; the register row follows from the leg (deferred
       trigger on chip_ledger). Undeclared, this landed in suspense and the
       register never saw it. */
    perform public.fn_ca_declare_ledger('mint', 'issuance_reserve', null, null,
                                        'diamond-mint:' || v_op_id::text, null);
    insert into union_wallets (union_id, chip_balance)
    values (v_club.union_id, v_chips)
    on conflict (union_id)
    do update set chip_balance = coalesce(union_wallets.chip_balance, 0) + v_chips,
                  updated_at = now();
    perform set_config('app.ledger_category', '', true);
    perform set_config('app.ledger_counterparty', '', true);
    perform set_config('app.ledger_idempotency_key', '', true);
    select chip_balance into v_union_bank_after
      from union_wallets where union_id = v_club.union_id;

    insert into chip_transactions (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
    values (p_club_id, v_actor, null, v_chips, 'mint',
            'Union Chip Mint: ' || v_chips::text || ' chips from ' || v_diamonds::text || ' diamonds at ' || v_rate::text || ' per chip',
            jsonb_build_object('op_id', v_op_id, 'scope', 'union',
                               'diamonds_spent', v_diamonds, 'union_id', v_club.union_id,
                               'diamonds_per_chip', v_rate),
            v_union_bank_after);

    return jsonb_build_object('success', true, 'replayed', false, 'scope', 'union',
      'chips', v_chips, 'diamonds_spent', v_diamonds, 'diamonds_per_chip', v_rate,
      'diamonds_after', v_diamonds_after, 'union_bank_after', v_union_bank_after);
  else
    -- STANDALONE CLUB: owner / co_owner / admin may mint into the club's pool.
    -- BOTH membership words (2026-08-27): status='active' alone refused the
    -- ~98% of production rows still carrying the pre-2026-07-22 'approved'.
    if not (v_club.owner_id = v_actor
            or exists (select 1 from club_members cm
                        where cm.club_id = p_club_id and cm.user_id = v_actor
                          and cm.role in ('owner', 'co_owner', 'admin')
                          and coalesce(cm.status, 'active') in ('active', 'approved'))) then
      return jsonb_build_object('success', false,
        'error', 'Only The Club Owner Or An Admin May Mint Chips');
    end if;

    v_deduct := deduct_diamonds(
      v_actor, v_diamonds::integer,
      'Chip Mint: ' || v_chips::text || ' chips minted to club bank',
      'chip_mint', 'chip_mint',
      jsonb_build_object('club_id', p_club_id, 'chips', v_chips, 'op_id', v_op_id,
                         'diamonds_per_chip', v_rate),
      null, 0);
    if coalesce((v_deduct->>'success')::boolean, false) = false then
      return jsonb_build_object('success', false,
        'error', coalesce(v_deduct->>'error', 'That Diamond Deduction Did Not Go Through'));
    end if;
    select coalesce(diamonds, 0) into v_diamonds_after from profiles where id = v_actor;

    /* THE MINT (chip standard 3.1, 2026-09-04): see the union branch. */
    perform public.fn_ca_declare_ledger('mint', 'issuance_reserve', null, null,
                                        'diamond-mint:' || v_op_id::text, null);
    update clubs set chip_treasury = coalesce(chip_treasury, 0) + v_chips, updated_at = now()
     where id = p_club_id
     returning chip_treasury into v_pool_after;
    perform set_config('app.ledger_category', '', true);
    perform set_config('app.ledger_counterparty', '', true);
    perform set_config('app.ledger_idempotency_key', '', true);

    insert into chip_transactions (club_id, from_user_id, to_user_id, amount, transaction_type, notes, metadata, balance_after)
    values (p_club_id, v_actor, null, v_chips, 'mint',
            'Chip Mint: ' || v_chips::text || ' chips from ' || v_diamonds::text || ' diamonds at ' || v_rate::text || ' per chip',
            jsonb_build_object('op_id', v_op_id, 'scope', 'club',
                               'diamonds_spent', v_diamonds, 'diamonds_per_chip', v_rate),
            v_pool_after);

    return jsonb_build_object('success', true, 'replayed', false, 'scope', 'club',
      'chips', v_chips, 'diamonds_spent', v_diamonds, 'diamonds_per_chip', v_rate,
      'diamonds_after', v_diamonds_after, 'club_pool_after', v_pool_after);
  end if;
end
$_$;


ALTER FUNCTION public.fn_mint_chips_from_diamonds(p_club_id uuid, p_diamonds numeric, p_op_id uuid) OWNER TO postgres;

--
-- TOC entry 5805 (class 1255 OID 18275128)
-- Name: fn_mint_club_chips(uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mint_club_chips(p_club_id uuid, p_amount numeric, p_reason text DEFAULT 'beta top-up'::text, p_op_id text DEFAULT NULL::text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_prior jsonb;
  v_res numeric;
begin
  /* ZERO-DRIFT phase 3/5: durable op-id claim with actor audit. Callers that
     pass a p_op_id get exactly-once semantics across retries; the claim row
     records who asked. Authorization itself lives in the core. */
  if p_op_id is null then
    return public.fn_mint_club_chips_zd3core(p_club_id, p_amount, p_reason);
  end if;

  select result into v_prior
    from public.ca_op_claims
   where op_id = p_op_id and fn_name = 'fn_mint_club_chips';
  if found and v_prior is not null then
    return (v_prior->>'value')::numeric;  -- replay: treasury after the original mint
  elsif found then
    delete from public.ca_op_claims
     where op_id = p_op_id and fn_name = 'fn_mint_club_chips';
  end if;

  insert into public.ca_op_claims (op_id, fn_name, claimed_by)
  values (p_op_id, 'fn_mint_club_chips', v_actor);

  v_res := public.fn_mint_club_chips_zd3core(p_club_id, p_amount, p_reason);

  update public.ca_op_claims
     set result = jsonb_build_object('value', v_res), finalized_at = now()
   where op_id = p_op_id and fn_name = 'fn_mint_club_chips';

  return v_res;
end $$;


ALTER FUNCTION public.fn_mint_club_chips(p_club_id uuid, p_amount numeric, p_reason text, p_op_id text) OWNER TO postgres;

--
-- TOC entry 8236 (class 1255 OID 18275126)
-- Name: fn_mint_club_chips_zd3core(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mint_club_chips_zd3core(p_club_id uuid, p_amount numeric, p_reason text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
    v_actor uuid := auth.uid();
    v_after numeric;
    v_union uuid;
    v_authorised boolean;
begin
    if p_amount is null or p_amount <= 0 then
        raise exception 'mint amount must be positive, got %', p_amount;
    end if;

    select union_id into v_union from clubs where id = p_club_id;
    if not found then
        raise exception 'mint failed: club % not found', p_club_id;
    end if;

    -- Dan 2026-08-22: only unions mint. A club that has joined a union has no
    -- mint of its own - chips are minted in the union and SENT to the club.
    if v_union is not null then
        raise exception 'Chip Mint Is Revoked For Clubs In A Union - Chips Are Minted In The Union And Sent To The Club. Ask Your Union Owner.';
    end if;

    if coalesce(auth.role(), '') <> 'service_role' then
        v_authorised := v_actor is not null and (
            exists (select 1 from clubs c where c.id = p_club_id and c.owner_id = v_actor)
            or exists (
                select 1 from club_members cm
                 where cm.club_id = p_club_id
                   and cm.user_id = v_actor
                   and cm.role in ('owner','co_owner','admin')
                   and cm.status in ('active','approved'))
        );
        if not v_authorised then
            raise exception 'not authorized to mint for this club';
        end if;
    end if;

    /* ZERO-DRIFT round 2 (2026-08-31): duplicate-mint suppression. An
       identical mint (club, amount, reason, actor) inside 20 seconds is a
       retry, not a second intent - return the current treasury unchanged.
       A deliberate second mint just needs a different reason or 20 seconds. */
    if exists (
        select 1 from chip_transactions ct
         where ct.club_id = p_club_id
           and ct.transaction_type = 'treasury_mint'
           and ct.amount = p_amount
           and ct.from_user_id is not distinct from v_actor
           and coalesce(ct.notes,'') = coalesce(p_reason,'')
           and ct.created_at > now() - interval '20 seconds') then
        select coalesce(chip_treasury, 0) into v_after from clubs where id = p_club_id;
        return v_after;
    end if;

    /* Authorized issuance journals against the issuance reserve. */
    perform set_config('app.ledger_category', 'mint', true);
    perform set_config('app.ledger_counterparty', 'issuance_reserve', true);
    perform set_config('app.ledger_counterparty_entity', '', true);

    update public.clubs
       set chip_treasury = coalesce(chip_treasury, 0) + p_amount
     where id = p_club_id
    returning chip_treasury into v_after;

    insert into public.chip_transactions
        (club_id, from_user_id, to_user_id, amount, transaction_type, notes, balance_after)
    values (p_club_id, v_actor, null, p_amount, 'treasury_mint', p_reason, v_after);

    return v_after;
end $$;


ALTER FUNCTION public.fn_mint_club_chips_zd3core(p_club_id uuid, p_amount numeric, p_reason text) OWNER TO postgres;

--
-- TOC entry 7465 (class 1255 OID 18965272)
-- Name: fn_mint_social_alias(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mint_social_alias(p_seed text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_w1 text[];
  v_w2 text[];
  v_base text;
  v_cand text;
  v_n integer := 0;
  v_h bigint;
BEGIN
  SELECT array_agg(w ORDER BY w) INTO v_w1
    FROM (SELECT DISTINCT (regexp_match(alias, '^([A-Z][a-z]+)'))[1] AS w
            FROM public.content_authors) s
   WHERE w IS NOT NULL;
  SELECT array_agg(w ORDER BY w) INTO v_w2
    FROM (SELECT DISTINCT (regexp_match(alias, '^[A-Z][a-z]+([A-Z][a-z]+)'))[1] AS w
            FROM public.content_authors) s
   WHERE w IS NOT NULL;

  IF v_w1 IS NULL OR v_w2 IS NULL
     OR COALESCE(array_length(v_w1, 1), 0) = 0
     OR COALESCE(array_length(v_w2, 1), 0) = 0 THEN
    RAISE EXCEPTION 'fn_mint_social_alias: no alias vocabulary to draw from';
  END IF;

  v_h := abs(hashtext(p_seed));

  LOOP
    v_base := v_w1[1 + ((v_h + v_n * 7919) % array_length(v_w1, 1))]
           || v_w2[1 + (((v_h / 17) + v_n * 104729) % array_length(v_w2, 1))];
    -- Pure handles first. Once fifty probes have all collided we are in a
    -- crowded corner of the space, so take the discriminator rather than
    -- probing forever: this is the safety net that 2026-09-01 did not have.
    v_cand := CASE WHEN v_n < 50 THEN v_base ELSE v_base || (v_n - 49)::text END;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.content_authors WHERE alias = v_cand);
    v_n := v_n + 1;
    IF v_n > 100000 THEN
      RAISE EXCEPTION 'fn_mint_social_alias: could not mint a free alias for %', p_seed;
    END IF;
  END LOOP;

  RETURN v_cand;
END;
$$;


ALTER FUNCTION public.fn_mint_social_alias(p_seed text) OWNER TO postgres;

--
-- TOC entry 48098 (class 0 OID 0)
-- Dependencies: 7465
-- Name: FUNCTION fn_mint_social_alias(p_seed text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_mint_social_alias(p_seed text) IS 'Mints a free content_authors.alias. Cannot exhaust: probes the full observed vocabulary then falls back to a numeric discriminator. Added 2026-09-02 after a 400-handle generator stranded 253 horses.';


--
-- TOC entry 7736 (class 1255 OID 14238799)
-- Name: fn_mirror_notification_to_push_outbox(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mirror_notification_to_push_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE notice public.notifications%ROWTYPE; receipt record; existing public.push_outbox%ROWTYPE;
 v_tag text;v_pending int;state text:='pending';reason text;
 c_max_pending CONSTANT int:=20;c_max_age CONSTANT interval:=interval '30 minutes';
 v_alert_state text;v_alert_error text;v_alert_constraint text;
BEGIN
 -- Delivery rows are inserted AFTER their notification. Wait until the whole
 -- transaction is ready to commit before granting the canonical exception.
 IF TG_NAME<>'trg_accounting_push_after_delivery' AND NEW.type='accounting_invoice' THEN RETURN NEW; END IF;
 SELECT * INTO notice FROM public.notifications WHERE id=NEW.id;
 IF NOT FOUND THEN RETURN NEW; END IF;
 SELECT d.invoice_id,d.recipient_id,d.delivery_mode,m.conversation_id,m.message_type,m.media_metadata,
  i.invoice_number,i.net_amount,i.invoice_type INTO receipt
 FROM public.accounting_invoice_deliveries d JOIN public.settlement_invoices i ON i.id=d.invoice_id
 JOIN public.social_messages m ON m.id=d.message_id WHERE d.notification_id=notice.id;
 IF FOUND THEN
  -- A real receipt foreign key, exact recipient and issued document are
  -- required. Arbitrary accounting-looking JSON cannot bypass normal caps.
  IF receipt.recipient_id IS DISTINCT FROM notice.user_id
   OR notice.data->>'invoice_id' IS DISTINCT FROM receipt.invoice_id::text
   OR notice.data->>'invoice_number' IS DISTINCT FROM receipt.invoice_number
   OR notice.data->'amount' IS DISTINCT FROM to_jsonb(receipt.net_amount)
   OR receipt.message_type IS DISTINCT FROM 'invoice'
   OR receipt.media_metadata->>'invoice_id' IS DISTINCT FROM receipt.invoice_id::text
   OR COALESCE(notice.data->>'conversation_id',notice.data->>'conversationId') IS DISTINCT FROM receipt.conversation_id::text
   OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants p WHERE p.conversation_id=receipt.conversation_id AND p.user_id=notice.user_id)
  THEN RAISE EXCEPTION 'accounting_push_receipt_provenance_invalid' USING ERRCODE='23514'; END IF;
  IF receipt.delivery_mode='weekly_detail' OR notice.type='accounting_invoice_detail' THEN
   state:='skipped';reason:='accounting_archived_detail';
  ELSIF notice.type IS DISTINCT FROM 'accounting_invoice' THEN
   RAISE EXCEPTION 'accounting_push_notification_type_invalid' USING ERRCODE='23514';
  ELSIF notice.data->>'_push' IS NOT NULL THEN
   state:='skipped';reason:='accounting_source_suppressed:'||(notice.data->>'_push');
  ELSIF notice.created_at<now()-c_max_age THEN
   state:='skipped';reason:='accounting_historical_notification';
  ELSIF notice.user_id='47965354-0e56-43ef-931c-ddaab82af765'::uuid THEN
   -- Same owner-operational recipient fn_is_owner_operational_notification()
   -- hard-codes (kept as a literal here, not a shared call, because that
   -- classifier also gates on p_type and would return false for
   -- 'accounting_invoice' -- this is not a second source of truth for WHO
   -- the owner is, only a second reference to the same fixed id). This is
   -- his issuer-side owner/union-owner copy of a receipt whose real payee is
   -- someone else; it must NOT be added to fn_is_owner_operational_
   -- notification's type list, or the capture trigger fires once per
   -- receipt (hundreds per settlement) instead of once per hour, and the
   -- non-accounting mirror predicate below would wrongly suppress it too.
   state:='skipped';reason:='owner_accounting_routed_to_production_alerts';
  END IF;
  SELECT * INTO existing FROM public.push_outbox WHERE accounting_notification_id=notice.id;
  IF FOUND THEN
   IF existing.recipient_user_id IS DISTINCT FROM notice.user_id OR existing.related_entity_id IS DISTINCT FROM notice.id
    OR existing.event IS DISTINCT FROM 'accounting_invoice' THEN RAISE EXCEPTION 'accounting_push_receipt_collision' USING ERRCODE='23514'; END IF;
   IF receipt.invoice_type IN('cashier_cashout','accounting_correction','credit_limit_change') AND ROW(existing.title,existing.body,existing.url,existing.tag) IS DISTINCT FROM
     ROW(left(notice.title,120),left(COALESCE(notice.message,notice.title),500),
       COALESCE(NULLIF(btrim(notice.link),''),NULLIF(btrim(notice.action_url),''),'/hub'),
       'accounting_invoice:'||receipt.conversation_id::text)
   THEN RAISE EXCEPTION 'cashier_push_content_mismatch' USING ERRCODE='23514';END IF;
   RETURN NEW;
  END IF;
  -- No exception swallowing here. The invoice, message, notification, linked
  -- transfer and durable outbox receipt commit together or all roll back.
  -- Normal dispatcher preference, quiet-hour, device and consent gates remain.
  INSERT INTO public.push_outbox(recipient_user_id,title,body,url,event,tag,status,failure_reason,related_entity_id,accounting_notification_id)
  VALUES(notice.user_id,left(notice.title,120),left(COALESCE(notice.message,notice.title),500),
   COALESCE(NULLIF(btrim(notice.link),''),NULLIF(btrim(notice.action_url),''),'/hub'),
   'accounting_invoice','accounting_invoice:'||receipt.conversation_id::text,state,reason,notice.id,notice.id);
  IF reason='owner_accounting_routed_to_production_alerts' THEN
   -- Informational only, coalesced to one row per UTC hour. Must never be
   -- able to roll back the invoice/message/notification/outbox insert above.
   BEGIN
    PERFORM public.fn_record_operational_alert('owner-accounting-notifications',
     'owner-accounting:'||to_char(date_trunc('hour',now() AT TIME ZONE 'UTC'),'YYYY-MM-DD"T"HH24'),
     'Accounting Documents Issued (Owner Copy)','info','info',
     jsonb_build_object('target_task_id','01a09b86-5ba8-7290-8657-1041f13dd3ca','first_notification_id',notice.id,'invoice_number',receipt.invoice_number,
      'invoice_type',receipt.invoice_type,'amount',receipt.net_amount,
      'conversation_id',receipt.conversation_id,
      'hour',to_char(date_trunc('hour',now() AT TIME ZONE 'UTC'),'YYYY-MM-DD"T"HH24')));
   EXCEPTION WHEN OTHERS THEN
    -- The store refused the hour's event (operational_alert_events refuses an
    -- unaddressed row under this source) or could not take it. A WARNING
    -- reaches nobody, so the fleet gets its own addressed row for the hour,
    -- from a nested block: that can fail too, and still never rolls back the
    -- document above or touches the receipt this branch already wrote.
    GET STACKED DIAGNOSTICS v_alert_state=RETURNED_SQLSTATE,v_alert_error=MESSAGE_TEXT,v_alert_constraint=CONSTRAINT_NAME;
    RAISE WARNING 'owner_accounting_alert_record_failed for notification %: %',notice.id,v_alert_error;
    BEGIN
     PERFORM public.fn_record_operational_alert('owner-accounting-notifications',
      'owner-accounting-unstored:'||to_char(date_trunc('hour',now() AT TIME ZONE 'UTC'),'YYYY-MM-DD"T"HH24'),
      'Owner Accounting Alert Not Stored','firing','warning',
      jsonb_build_object('target_task_id','01a09b86-5ba8-7290-8657-1041f13dd3ca','unstored_event_key',
       'owner-accounting:'||to_char(date_trunc('hour',now() AT TIME ZONE 'UTC'),'YYYY-MM-DD"T"HH24'),
       'first_notification_id',notice.id,'sqlstate',v_alert_state,'error',left(v_alert_error,1000),
       'constraint',NULLIF(v_alert_constraint,''),
       'hour',to_char(date_trunc('hour',now() AT TIME ZONE 'UTC'),'YYYY-MM-DD"T"HH24')));
    EXCEPTION WHEN OTHERS THEN
     RAISE WARNING 'owner_accounting_alert_unstored_record_failed for notification %: %',notice.id,SQLERRM;
    END;
   END;
  END IF;
  IF receipt.invoice_type IN('cashier_cashout','accounting_correction','credit_limit_change') AND NOT EXISTS(SELECT 1 FROM public.push_outbox o
    WHERE o.accounting_notification_id=notice.id AND o.related_entity_id=notice.id
      AND o.recipient_user_id=notice.user_id AND o.event='accounting_invoice'
      AND o.status=state AND o.failure_reason IS NOT DISTINCT FROM reason
      AND o.title=left(notice.title,120) AND o.body=left(COALESCE(notice.message,notice.title),500)
      AND o.url=COALESCE(NULLIF(btrim(notice.link),''),NULLIF(btrim(notice.action_url),''),'/hub')
      AND o.tag='accounting_invoice:'||receipt.conversation_id::text)
  THEN RAISE EXCEPTION 'cashier_push_receipt_missing' USING ERRCODE='23514';END IF;
  RETURN NEW;
 END IF;

 -- A reserved accounting label with no actual delivery link is invalid,
 -- including a caller that forces this constraint before the link is written.
 -- Fail the transaction rather than silently dropping its accounting push.
 IF notice.type='accounting_invoice' THEN
  RAISE EXCEPTION 'accounting_push_delivery_link_missing' USING ERRCODE='23514';
 END IF;
 IF notice.type='accounting_invoice_detail' THEN RETURN NEW; END IF;
 -- Existing non-accounting notification policy stays intact.
 IF notice.data IS NOT NULL AND notice.data->>'_push' IS NOT NULL THEN RETURN NEW; END IF;
 IF notice.user_id IS NULL OR notice.title IS NULL OR btrim(notice.title)='' THEN RETURN NEW; END IF;
 IF notice.created_at IS NOT NULL AND notice.created_at<now()-c_max_age THEN RETURN NEW; END IF;
 IF notice.type IN('waitlist_seat_open','waitlist_offer_expired','seat_available','waitlist_ready','table_ready') THEN
  v_tag:='seat_offer:'||COALESCE(NULLIF(btrim(COALESCE(notice.data->>'table_id','')),''),notice.id::text);
 ELSIF notice.type IN('system','daily_challenge','venue_alert','bonus','vip','live','poker_news','diamond','achievement') THEN
  v_tag:=notice.type||':'||notice.user_id::text;
 ELSE
  v_tag:=notice.type||':'||COALESCE(NULLIF(btrim(COALESCE(notice.data->>'conversationId','')),''),NULLIF(btrim(COALESCE(notice.data->>'conversation_id','')),''),notice.actor_id::text,notice.id::text);
 END IF;
 BEGIN
  SELECT count(*) INTO v_pending FROM public.push_outbox WHERE recipient_user_id=notice.user_id AND status IN('pending','processing');
  IF v_pending>=c_max_pending THEN RETURN NEW; END IF;
  INSERT INTO public.push_outbox(recipient_user_id,title,body,url,event,tag,status,related_entity_id)
   VALUES(notice.user_id,left(notice.title,120),left(COALESCE(notice.message,notice.title),500),COALESCE(NULLIF(btrim(notice.link),''),NULLIF(btrim(notice.action_url),''),'/hub'),notice.type,v_tag,'pending',notice.id);
 EXCEPTION WHEN OTHERS THEN RAISE WARNING 'mirror_notification_to_push_outbox failed for notification %: %',notice.id,SQLERRM;
 END;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_mirror_notification_to_push_outbox() OWNER TO postgres;

--
-- TOC entry 8731 (class 1255 OID 16186830)
-- Name: fn_mirror_profile_into_legacy_users(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mirror_profile_into_legacy_users() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  BEGIN
    INSERT INTO public.users (id, username, email, avatar_url, created_at, updated_at)
    VALUES (
      NEW.id,
      COALESCE(
        NULLIF(btrim(NEW.username), ''),
        NULLIF(split_part(COALESCE(NEW.email, ''), '@', 1), ''),
        'Player' || COALESCE(NEW.player_number, left(replace(NEW.id::text, '-', ''), 10))
      ),
      NULLIF(btrim(COALESCE(NEW.email, '')), ''),
      NULLIF(btrim(COALESCE(NEW.avatar_url, '')), ''),
      now(),
      now()
    )
    ON CONFLICT (id) DO NOTHING;
  EXCEPTION WHEN unique_violation THEN
    BEGIN
      INSERT INTO public.users (id, username, email, avatar_url, created_at, updated_at)
      VALUES (NEW.id, 'u_' || replace(NEW.id::text, '-', ''), NULL,
              NULLIF(btrim(COALESCE(NEW.avatar_url, '')), ''), now(), now())
      ON CONFLICT (id) DO NOTHING;
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO public.signup_errors (user_id, email, trigger_name, error_code, error_msg)
      VALUES (NEW.id, NEW.email, 'fn_mirror_profile_into_legacy_users', SQLSTATE, SQLERRM);
    END;
  WHEN OTHERS THEN
    BEGIN
      INSERT INTO public.signup_errors (user_id, email, trigger_name, error_code, error_msg)
      VALUES (NEW.id, NEW.email, 'fn_mirror_profile_into_legacy_users', SQLSTATE, SQLERRM);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_mirror_profile_into_legacy_users() OWNER TO postgres;

