--
-- TOC entry 7253 (class 1255 OID 28383149)
-- Name: fn_monitoring_health_snapshot(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_monitoring_health_snapshot(p_window_minutes integer DEFAULT 5) RETURNS TABLE(settlement_window_minutes integer, settlement_window_hands bigint, settlement_failed bigint, settlement_stuck bigint, settlement_failure_rate numeric, money_undeclared_triggers bigint, financial_alerts_unresolved bigint, financial_alerts_stale_critical bigint, financial_alerts_distinct_conditions bigint, cron_pg_runs bigint, cron_pg_failures bigint, cron_openclaw_stale bigint, cron_openclaw_worst_silence_minutes numeric, cron_jobs_skipping_all_work bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $_$
  WITH sh AS (
    SELECT * FROM public.fn_settlement_health(greatest(coalesce(p_window_minutes, 5), 1))
  ), fa AS (
    SELECT count(*) FILTER (WHERE NOT resolved) AS unresolved,
           count(*) FILTER (
             WHERE NOT resolved
               AND severity = 'critical'
               AND created_at < now() - interval '24 hours'
           ) AS stale_critical,
           count(DISTINCT source) FILTER (WHERE NOT resolved) AS distinct_conditions
      FROM public.financial_alerts
  ), pgc AS (
    SELECT count(*) AS runs,
           count(*) FILTER (WHERE status <> 'succeeded') AS failures
      FROM cron.job_run_details
     WHERE start_time > now() - interval '1 hour'
  ), oc AS (
    SELECT count(*) FILTER (WHERE is_stale) AS stale,
           coalesce(max(silent_minutes) FILTER (WHERE is_stale), 0) AS worst_silence_minutes
      FROM public.v_openclaw_job_staleness
  ), ut AS (
    SELECT count(*) AS n FROM public.fn_undeclared_money_triggers()
  ), runs AS MATERIALIZED (
    -- EVERY FINISHED RUN, NOT ONLY THE SUCCESSES (2026-10-15). A job whose
    -- latest run failed is not reporting success; reading only successes
    -- kept a job that now fails (pokernews-videos, 500 since 2026-09-30)
    -- counted for 30 days on its last skipped success. A run that reports
    -- held is a deliberate owner hold (an approval gate left off on
    -- purpose), not success while doing nothing, and is never counted.
    SELECT job_name, started_at, status, result,
           NOT (result ? 'skipped'
                AND jsonb_typeof(result -> 'skipped') = 'string'
                AND (result ->> 'skipped') !~ '^[0-9]+$') AS did_work
      FROM public.cron_execution_log
     WHERE started_at > now() - interval '30 days'
       AND status <> 'running'
       AND NOT EXISTS (
             SELECT 1 FROM public.ca_retired_cron_jobs r WHERE r.job_name = cron_execution_log.job_name
           )
  ), latest AS (
    SELECT DISTINCT ON (job_name) job_name, status, result
      FROM runs ORDER BY job_name, started_at DESC
  ), latest_real AS (
    SELECT job_name, max(started_at) AS at FROM runs WHERE did_work AND status = 'success' GROUP BY 1
  ), noop AS (
    SELECT count(*) AS n
      FROM latest l
      LEFT JOIN latest_real lr ON lr.job_name = l.job_name
     WHERE l.status = 'success'
       AND NOT (l.result ? 'held')
       AND l.result ? 'skipped'
       AND jsonb_typeof(l.result -> 'skipped') = 'string'
       AND (l.result ->> 'skipped') !~ '^[0-9]+$'
       AND (lr.at IS NULL OR lr.at < now() - interval '24 hours')
  )
  SELECT sh.window_minutes,
         sh.settled,
         sh.failed,
         sh.stuck,
         coalesce(sh.failure_rate, 0)::numeric,
         ut.n,
         fa.unresolved,
         fa.stale_critical,
         fa.distinct_conditions,
         pgc.runs,
         pgc.failures,
         oc.stale,
         oc.worst_silence_minutes::numeric,
         noop.n
    FROM sh, fa, pgc, oc, ut, noop;
$_$;


ALTER FUNCTION public.fn_monitoring_health_snapshot(p_window_minutes integer) OWNER TO postgres;

--
-- TOC entry 48107 (class 0 OID 0)
-- Dependencies: 7253
-- Name: FUNCTION fn_monitoring_health_snapshot(p_window_minutes integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_monitoring_health_snapshot(p_window_minutes integer) IS 'Every number behind the money, settlement and cron alert rules, in one read. Called once a minute by collect-monitoring-health.sh on engine-01, which publishes the result as a node_exporter textfile. Read-only. cron_jobs_skipping_all_work counts jobs whose most recent logged success carried a REASON for skipping (not a count) and which have done no real work in 24 hours.';


--
-- TOC entry 5195 (class 1255 OID 25985133)
-- Name: fn_move_tournament_player(uuid, uuid, uuid, uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_move_tournament_player(p_tournament_id uuid, p_user_id uuid, p_source_table_id uuid, p_destination_table_id uuid, p_destination_seat_number integer, p_request_id uuid, p_source_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_tp public.tournament_players%ROWTYPE;
  v_source public.table_seats%ROWTYPE;
  v_destination public.table_seats%ROWTYPE;
  v_destination_id uuid;
  v_token uuid;
  v_moved_at timestamptz;
  v_rows integer;
  v_live_count integer;
  v_result jsonb;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'fn_move_tournament_player requires service authority'
      USING ERRCODE='28000';
  END IF;
  IF p_tournament_id IS NULL OR p_user_id IS NULL
     OR p_source_table_id IS NULL OR p_destination_table_id IS NULL
     OR p_request_id IS NULL OR p_source_table_id=p_destination_table_id
     OR p_source_mode NOT IN ('live_source','closed_orphan')
     OR p_destination_seat_number NOT BETWEEN 1 AND 10 THEN
    RAISE EXCEPTION 'invalid tournament move identity' USING ERRCODE='22023';
  END IF;

  IF current_setting('app.smarter_data_actor',true)='tournament-manager' THEN
    PERFORM smarter_private.f06_authority(p_tournament_id,NULLIF(current_setting('app.smarter_tournament_lease_generation',true),'')::uuid);
  END IF;
  -- HOTFIX EDIT (b): G -> T via the 20260910035245 helper, not the raw global key.
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  PERFORM pg_advisory_xact_lock(
    hashtextextended('table_cap:'||p_user_id::text,0));

  v_result:=public.fn_ca_tournament_seat_move_receipt(p_request_id);
  IF v_result IS NOT NULL THEN
    IF (v_result->>'tournament_id')::uuid IS DISTINCT FROM p_tournament_id
       OR (v_result->>'user_id')::uuid IS DISTINCT FROM p_user_id
       OR (v_result->>'source_table_id')::uuid IS DISTINCT FROM p_source_table_id
       OR (v_result->>'destination_table_id')::uuid
            IS DISTINCT FROM p_destination_table_id
       OR v_result->>'source_mode' IS DISTINCT FROM p_source_mode
       OR (v_result->>'destination_seat_number')::integer
            IS DISTINCT FROM p_destination_seat_number THEN
      RAISE EXCEPTION 'tournament move request id belongs to another operation'
        USING ERRCODE='23505';
    END IF;
    RETURN v_result||jsonb_build_object('replayed',true);
  END IF;

  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist',p_tournament_id
      USING ERRCODE='P0002';
  END IF;
  IF upper(COALESCE(v_t.status,''))<>'RUNNING' THEN
    RAISE EXCEPTION 'tournament % is not RUNNING',p_tournament_id
      USING ERRCODE='55000';
  END IF;

  SELECT * INTO v_tp FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
   FOR UPDATE;
  IF NOT FOUND OR v_tp.status<>'playing'
     OR v_tp.table_id IS DISTINCT FROM p_source_table_id THEN
    RAISE EXCEPTION 'tournament move source roster is not exact'
      USING ERRCODE='P0404';
  END IF;

  PERFORM tb.id FROM public.tables tb
   WHERE tb.id IN (p_source_table_id,p_destination_table_id)
   ORDER BY tb.id FOR UPDATE;
  IF (SELECT count(*) FROM public.tables tb
       WHERE tb.id IN (p_source_table_id,p_destination_table_id)
         AND tb.tournament_id=p_tournament_id)<>2 THEN
    RAISE EXCEPTION 'tournament move tables do not share the event'
      USING ERRCODE='22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tables tb
     WHERE tb.id=p_destination_table_id
       AND (COALESCE(tb.is_deleted,false)
         OR lower(COALESCE(tb.status,''))='closed'
         OR p_destination_seat_number>COALESCE(tb.max_players,9))) THEN
    RAISE EXCEPTION 'tournament move destination is not open'
      USING ERRCODE='55000';
  END IF;
  IF p_source_mode='closed_orphan' AND NOT EXISTS (
    SELECT 1 FROM public.tables tb
     WHERE tb.id=p_source_table_id
       AND (COALESCE(tb.is_deleted,false)
         OR lower(COALESCE(tb.status,''))='closed')) THEN
    RAISE EXCEPTION 'closed-orphan move source is not closed'
      USING ERRCODE='55000';
  END IF;
  IF p_source_mode='live_source' AND EXISTS (
    SELECT 1 FROM public.tables tb
     WHERE tb.id=p_source_table_id
       AND (COALESCE(tb.is_deleted,false)
         OR lower(COALESCE(tb.status,''))='closed')) THEN
    RAISE EXCEPTION 'live-source move source is closed'
      USING ERRCODE='55000';
  END IF;

  PERFORM s.id
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
     AND s.left_at IS NULL
   ORDER BY s.id FOR UPDATE OF s;
  SELECT count(*) INTO v_live_count
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
     AND s.left_at IS NULL;
  IF v_live_count<>1 THEN
    RAISE EXCEPTION 'tournament move requires exactly one live source seat'
      USING ERRCODE='P0404';
  END IF;

  SELECT s.* INTO v_source FROM public.table_seats s
   WHERE s.table_id=p_source_table_id AND s.user_id=p_user_id
     AND s.left_at IS NULL FOR UPDATE;
  IF NOT FOUND OR v_source.seat_number IS DISTINCT FROM v_tp.seat_number
     OR v_source.stack IS NULL
     OR v_source.stack::text IN ('NaN','Infinity','-Infinity')
     OR v_source.stack<=0
     OR abs(v_source.stack-v_tp.chips::numeric)>0.5 THEN
    RAISE EXCEPTION 'tournament move source chips or coordinates are not exact'
      USING ERRCODE='P0404';
  END IF;

  SELECT s.* INTO v_destination FROM public.table_seats s
   WHERE s.table_id=p_destination_table_id
     AND s.seat_number=p_destination_seat_number FOR UPDATE;
  IF FOUND AND v_destination.left_at IS NULL THEN
    RAISE EXCEPTION 'tournament move destination seat is occupied'
      USING ERRCODE='23505';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id
       AND tp.user_id<>p_user_id
       AND tp.status IN ('registered','playing')
       AND tp.table_id=p_destination_table_id
       AND tp.seat_number=p_destination_seat_number) THEN
    RAISE EXCEPTION 'tournament move destination roster is occupied'
      USING ERRCODE='23505';
  END IF;

  PERFORM smarter_private.f06_move_guard(p_tournament_id,p_user_id,p_source_table_id,p_destination_table_id,p_destination_seat_number,p_request_id,p_source_mode,v_source.id,v_source.occupancy_id);
  v_token:=public.fn_ca_open_tournament_seat_exit_authority(
    p_tournament_id,'move',p_user_id);
  v_moved_at:=clock_timestamp();
  BEGIN
    UPDATE public.table_seats s
       SET stack=0,left_at=v_moved_at,status='left',leave_pending=false,
           is_sitting_out=false,is_away=false,sit_out_at=NULL,
           scheduled_leave_hands=NULL
     WHERE s.id=v_source.id AND s.left_at IS NULL
       AND s.stack=v_source.stack;
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows<>1 THEN
      RAISE EXCEPTION 'tournament move lost its locked source seat'
        USING ERRCODE='55000';
    END IF;

    IF v_destination.id IS NULL THEN
      INSERT INTO public.table_seats(
        table_id,seat_number,user_id,player_id,member_id,stack,
        is_sitting_out,is_away,joined_at,horse_id,scheduled_leave_hands,
        left_at,status,leave_pending,auto_rebuy,time_bank_remaining,
        time_bank_uses_remaining,sit_out_at,entry_hold,entry_post_agreed)
      VALUES(
        p_destination_table_id,p_destination_seat_number,p_user_id,
        v_source.player_id,v_source.member_id,v_source.stack,
        false,false,v_moved_at,v_source.horse_id,NULL,NULL,'active',false,
        v_source.auto_rebuy,v_source.time_bank_remaining,
        v_source.time_bank_uses_remaining,NULL,NULL,
        v_source.entry_post_agreed)
      RETURNING id INTO v_destination_id;
    ELSE
      UPDATE public.table_seats s
         SET user_id=p_user_id,player_id=v_source.player_id,
             member_id=v_source.member_id,stack=v_source.stack,
             is_sitting_out=false,is_away=false,joined_at=v_moved_at,
             horse_id=v_source.horse_id,scheduled_leave_hands=NULL,
             left_at=NULL,status='active',leave_pending=false,
             auto_rebuy=v_source.auto_rebuy,
             time_bank_remaining=v_source.time_bank_remaining,
             time_bank_uses_remaining=v_source.time_bank_uses_remaining,
             sit_out_at=NULL,entry_hold=NULL,
             entry_post_agreed=v_source.entry_post_agreed
       WHERE s.id=v_destination.id AND s.left_at IS NOT NULL
       RETURNING id INTO v_destination_id;
      IF v_destination_id IS NULL THEN
        RAISE EXCEPTION 'tournament move could not reuse destination seat'
          USING ERRCODE='55000';
      END IF;
    END IF;

    UPDATE public.tournament_players tp
       SET table_id=p_destination_table_id,
           seat_number=p_destination_seat_number
     WHERE tp.id=v_tp.id AND tp.status='playing'
       AND tp.table_id=p_source_table_id
       AND tp.seat_number=v_source.seat_number;
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows<>1 THEN
      RAISE EXCEPTION 'tournament move lost its locked roster row'
        USING ERRCODE='55000';
    END IF;

    UPDATE public.tables tb
       SET current_players=(
         SELECT count(*) FROM public.table_seats s
          WHERE s.table_id=tb.id AND s.left_at IS NULL),
           updated_at=now()
     WHERE tb.id IN (p_source_table_id,p_destination_table_id);

    IF (SELECT count(*) FROM public.table_seats s
        JOIN public.tables tb ON tb.id=s.table_id
       WHERE tb.tournament_id=p_tournament_id
         AND s.user_id=p_user_id AND s.left_at IS NULL)<>1
       OR NOT EXISTS (
         SELECT 1 FROM public.table_seats s
          WHERE s.id=v_destination_id
            AND s.table_id=p_destination_table_id
            AND s.seat_number=p_destination_seat_number
            AND s.user_id=p_user_id AND s.left_at IS NULL
            AND s.stack=v_source.stack)
       OR NOT EXISTS (
         SELECT 1 FROM public.table_seats s
          WHERE s.id=v_source.id AND s.left_at=v_moved_at AND s.stack=0)
       OR NOT EXISTS (
         SELECT 1 FROM public.tournament_players tp
          WHERE tp.id=v_tp.id AND tp.status='playing'
            AND tp.table_id=p_destination_table_id
            AND tp.seat_number=p_destination_seat_number) THEN
      RAISE EXCEPTION 'tournament move final proof is not exact'
        USING ERRCODE='P0404';
    END IF;

    INSERT INTO public.tournament_seat_move_receipts(
      request_id,tournament_id,user_id,source_table_id,destination_table_id,
      source_seat_id,destination_seat_id,source_seat_number,
      destination_seat_number,source_mode,stack,moved_at)
    VALUES(
      p_request_id,p_tournament_id,p_user_id,p_source_table_id,
      p_destination_table_id,v_source.id,v_destination_id,
      v_source.seat_number,p_destination_seat_number,p_source_mode,
      v_source.stack,v_moved_at);

    -- HOTFIX EDIT (a): the consuming guard trigger is not installed; rows are deleted, not counted.
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(v_token,false);
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.fn_ca_close_tournament_seat_exit_authority(v_token,false);
    RAISE;
  END;

  v_result:=public.fn_ca_tournament_seat_move_receipt(p_request_id);
  IF v_result IS NULL THEN
    RAISE EXCEPTION 'tournament move receipt did not persist'
      USING ERRCODE='P0404';
  END IF;
  RETURN v_result||jsonb_build_object('replayed',false);
END;
$$;


ALTER FUNCTION public.fn_move_tournament_player(p_tournament_id uuid, p_user_id uuid, p_source_table_id uuid, p_destination_table_id uuid, p_destination_seat_number integer, p_request_id uuid, p_source_mode text) OWNER TO postgres;

--
-- TOC entry 4620 (class 1255 OID 55307342)
-- Name: fn_multi_day_lease_is_current(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_multi_day_lease_is_current(p_tournament_id uuid, p_lease_generation uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM 1
    FROM public.engine_tournament_leases l
   WHERE l.tournament_id = p_tournament_id
     AND l.protocol_version = 2
     AND l.lease_generation = p_lease_generation
     AND l.heartbeat_at >= clock_timestamp() - interval '30 seconds'
     FOR KEY SHARE;
  RETURN FOUND;
END
$$;


ALTER FUNCTION public.fn_multi_day_lease_is_current(p_tournament_id uuid, p_lease_generation uuid) OWNER TO postgres;

--
-- TOC entry 4350 (class 1255 OID 55244116)
-- Name: fn_multi_day_stage_rows_are_rpc_owned(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_multi_day_stage_rows_are_rpc_owned() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_tournament uuid;
BEGIN
  IF TG_OP IN ('DELETE', 'TRUNCATE') THEN
    RAISE EXCEPTION 'MULTI_DAY_STAGE_RECORD_IS_PERMANENT: % on % refused', TG_OP, TG_TABLE_NAME
      USING ERRCODE = '55000';
  END IF;
  v_tournament := NEW.tournament_id;
  IF current_setting('app.multi_day_stage_writer', true) IS DISTINCT FROM v_tournament::text THEN
    RAISE EXCEPTION 'MULTI_DAY_STAGE_WRITER_REQUIRED: % on % belongs to the stage RPCs', TG_OP, TG_TABLE_NAME
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' THEN
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = 'tournament_stages' THEN
    IF (NEW.tournament_id, NEW.stage_no, NEW.kind, NEW.day_no, NEW.end_after_level)
       IS DISTINCT FROM (OLD.tournament_id, OLD.stage_no, OLD.kind, OLD.day_no, OLD.end_after_level)
       OR NEW.schedule_generation < OLD.schedule_generation THEN
      RAISE EXCEPTION 'MULTI_DAY_STAGE_STRUCTURE_IS_SEALED' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  ELSIF TG_TABLE_NAME = 'tournament_qualification_entitlements' THEN
    IF OLD.state = 'active' AND NEW.state = 'consumed'
       AND (NEW.id, NEW.tournament_id, NEW.user_id, NEW.source_stage_no, NEW.source_registration_id,
            NEW.source_bag_row_id, NEW.stack, NEW.bounty_head, NEW.target_stage_no, NEW.created_at)
           IS NOT DISTINCT FROM
           (OLD.id, OLD.tournament_id, OLD.user_id, OLD.source_stage_no, OLD.source_registration_id,
            OLD.source_bag_row_id, OLD.stack, OLD.bounty_head, OLD.target_stage_no, OLD.created_at) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'MULTI_DAY_ENTITLEMENT_IS_CONSUMED_ONCE' USING ERRCODE = '55000';
  ELSIF TG_TABLE_NAME = 'tournament_stage_resume_receipts' THEN
    IF (NEW.tournament_id, NEW.stage_no, NEW.resume_id, NEW.schedule_generation, NEW.first_level, NEW.claimed_at)
       IS DISTINCT FROM
       (OLD.tournament_id, OLD.stage_no, OLD.resume_id, OLD.schedule_generation, OLD.first_level, OLD.claimed_at)
       OR OLD.completed_at IS NOT NULL THEN
      RAISE EXCEPTION 'MULTI_DAY_RESUME_RECEIPT_IS_IMMUTABLE' USING ERRCODE = '55000';
    END IF;
    -- Exactly one of: completion, or a successor lease adopting it.
    IF (NEW.completed_at IS NOT NULL AND NEW.lease_generation = OLD.lease_generation)
       OR (NEW.completed_at IS NULL AND NEW.lease_generation IS DISTINCT FROM OLD.lease_generation) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'MULTI_DAY_RESUME_RECEIPT_IS_IMMUTABLE' USING ERRCODE = '55000';
  END IF;

  RAISE EXCEPTION 'MULTI_DAY_STAGE_RECEIPT_IS_APPEND_ONLY: UPDATE on % refused', TG_TABLE_NAME
    USING ERRCODE = '55000';
END
$$;


