-- TOC entry 5460 (class 1255 OID 69227599)
-- Name: fn_my_age_gate_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_my_age_gate_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_birthday date;
  v_age_verified boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;

  SELECT birthday, age_verified
    INTO v_birthday, v_age_verified
    FROM public.profiles
   WHERE id = v_uid;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'profile_not_found');
  END IF;

  -- The answer, and only the answer. The date itself never leaves here.
  RETURN jsonb_build_object(
    'ok', true,
    'verified', (v_birthday IS NOT NULL OR COALESCE(v_age_verified, false))
  );
END;
$$;


