-- Name: FUNCTION fn_my_cash_session_baseline(p_table_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_my_cash_session_baseline(p_table_id uuid) IS 'The caller''s own total bought in (buy-in plus landed add-ons, rebuys and Diamond top-ups) for their open cash session at one table, chips or Diamonds. Bound to auth.uid(); read-only.';


