--
-- TOC entry 7722 (class 1255 OID 78791153)
-- Name: fn_nit_career_check(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_nit_career_check(p_table_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_on            boolean;
  v_career_min    integer;
  v_maintain_n    integer;
  v_career_floor  integer;
  v_career_hands  integer;
  v_career_vpip   numeric;
BEGIN
  SELECT COALESCE(t.nit_game, false),
         GREATEST(COALESCE(t.career_percent_min, 0), 0),
         GREATEST(COALESCE(t.maintain_hands, 10), 1)
    INTO v_on, v_career_min, v_maintain_n
    FROM public.tables t WHERE t.id = p_table_id LIMIT 1;

  IF NOT COALESCE(v_on, false) THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'nit_game_off');
  END IF;

  -- CAREER
  IF v_career_min > 0 THEN
    v_career_floor := GREATEST(v_maintain_n * 10, 100);
    SELECT count(*)::int,
           CASE WHEN count(*) = 0 THEN NULL
                ELSE round(100.0 * avg(CASE WHEN f.vpip THEN 1 ELSE 0 END), 1) END
      INTO v_career_hands, v_career_vpip
      FROM public.ca_hand_facts f
     WHERE f.user_id = p_user_id;

    IF v_career_hands >= v_career_floor AND v_career_vpip < v_career_min THEN
      RETURN jsonb_build_object(
        'ok', false, 'reason', 'career_vpip',
        'vpip', v_career_vpip, 'required', v_career_min, 'hands', v_career_hands);
    END IF;
  END IF;

  RETURN jsonb_build_object('ok', true, 'reason', 'within_limits');
END;
$$;


ALTER FUNCTION public.fn_nit_career_check(p_table_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 5582 (class 1255 OID 15858674)
-- Name: fn_nit_check(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_nit_check(p_table_id uuid, p_user_id uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_on            boolean;
  v_career_min    integer;
  v_maintain_min  integer;
  v_maintain_n    integer;
  v_game          uuid;
  v_since         timestamptz;
  v_career_floor  integer;
  v_career_hands  integer;
  v_career_vpip   numeric;
  v_table_hands   integer;
  v_table_vpip    numeric;
BEGIN
  SELECT COALESCE(t.nit_game, false),
         GREATEST(COALESCE(t.career_percent_min, 0), 0),
         GREATEST(COALESCE(t.maintain_percent_min, 0), 0),
         GREATEST(COALESCE(t.maintain_hands, 10), 1),
         t.cluster_id
    INTO v_on, v_career_min, v_maintain_min, v_maintain_n, v_game
    FROM public.tables t WHERE t.id = p_table_id LIMIT 1;

  -- The toggle is the master switch. With NIT Game off the three numbers do
  -- nothing, which is what a switch labelled "Penalty for tight play" means
  -- and what makes the numbers safe to leave at their defaults.
  IF NOT COALESCE(v_on, false) THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'nit_game_off');
  END IF;

  -- CAREER
  IF v_career_min > 0 THEN
    v_career_floor := GREATEST(v_maintain_n * 10, 100);
    SELECT count(*)::int,
           CASE WHEN count(*) = 0 THEN NULL
                ELSE round(100.0 * avg(CASE WHEN f.vpip THEN 1 ELSE 0 END), 1) END
      INTO v_career_hands, v_career_vpip
      FROM public.ca_hand_facts f
     WHERE f.user_id = p_user_id;

    IF v_career_hands >= v_career_floor AND v_career_vpip < v_career_min THEN
      RETURN jsonb_build_object(
        'ok', false, 'reason', 'career_vpip',
        'vpip', v_career_vpip, 'required', v_career_min, 'hands', v_career_hands);
    END IF;
  END IF;

  -- MAINTAIN
  -- THE SITTING IN THE GAME, NOT THE CHAIR (2026-09-09, lane E audit). Dan:
  -- "IF ANYONE FALLS UNDER THE SET THRESHOLD FOR THE GAME AFTER 10 HANDS".
  -- A must-move game opens a fresh chair on every move, and judging "this
  -- table since this chair" restarted the window at zero each time - on
  -- Madness the median sitting at one table was six hands against a ten-hand
  -- window, so the floor could never judge a player the game kept moving.
  -- On a cluster table the sample is every fact row on any table of the game
  -- since the roster row's joined_at (a move does not close it; a leave
  -- does, so a player who rebuys after a break still starts a fresh count).
  -- A table outside a cluster keeps the per-table rule.
  IF v_maintain_min > 0 THEN
    v_since := p_since;
    IF v_game IS NOT NULL THEN
      SELECT r.joined_at INTO v_since
        FROM public.cash_game_roster r
       WHERE r.game_id = v_game AND r.user_id = p_user_id AND r.left_at IS NULL
       ORDER BY r.joined_at DESC
       LIMIT 1;
      IF NOT FOUND THEN v_since := p_since; END IF;

      SELECT count(*)::int,
             CASE WHEN count(*) = 0 THEN NULL
                  ELSE round(100.0 * avg(CASE WHEN f.vpip THEN 1 ELSE 0 END), 1) END
        INTO v_table_hands, v_table_vpip
        FROM public.ca_hand_facts f
       WHERE f.user_id = p_user_id
         AND (v_since IS NULL OR f.played_at >= v_since)
         AND f.table_id IN (SELECT t2.id FROM public.tables t2 WHERE t2.cluster_id = v_game);
    ELSE
      SELECT count(*)::int,
             CASE WHEN count(*) = 0 THEN NULL
                  ELSE round(100.0 * avg(CASE WHEN f.vpip THEN 1 ELSE 0 END), 1) END
        INTO v_table_hands, v_table_vpip
        FROM public.ca_hand_facts f
       WHERE f.table_id = p_table_id
         AND f.user_id = p_user_id
         AND (v_since IS NULL OR f.played_at >= v_since);
    END IF;

    IF v_table_hands >= v_maintain_n AND v_table_vpip < v_maintain_min THEN
      RETURN jsonb_build_object(
        'ok', false, 'reason', 'maintain_vpip',
        'vpip', v_table_vpip, 'required', v_maintain_min, 'hands', v_table_hands);
    END IF;
  END IF;

  RETURN jsonb_build_object('ok', true, 'reason', 'within_limits');
END;
$$;


ALTER FUNCTION public.fn_nit_check(p_table_id uuid, p_user_id uuid, p_since timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 48157 (class 0 OID 0)
-- Dependencies: 5582
-- Name: FUNCTION fn_nit_check(p_table_id uuid, p_user_id uuid, p_since timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_nit_check(p_table_id uuid, p_user_id uuid, p_since timestamp with time zone) IS 'The NIT game VPIP rule. On a cluster table the maintain window is the sitting in the GAME (every table of the cluster since cash_game_roster.joined_at), so a must-move cannot reset it (2026-09-09).';


--
-- TOC entry 5940 (class 1255 OID 15858678)
-- Name: fn_nit_evictions(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_nit_evictions(p_table_id uuid) RETURNS TABLE(user_id uuid, vpip numeric, required integer, hands integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  r record;
  v jsonb;
BEGIN
  FOR r IN
    SELECT ts.user_id AS uid, ts.joined_at
      FROM public.table_seats ts
      JOIN public.profiles p ON p.id = ts.user_id
     WHERE ts.table_id = p_table_id
       AND ts.left_at IS NULL
       -- HORSES ARE PLAYERS (Dan 2026-08-27). A horse-only predicate used to
       -- sit on this WHERE clause so the fleet could never be stood up by the
       -- maintain-VPIP rule. Same rules for everyone now; fn_nit_check's own
       -- sample floor spares a short sample, horses included.
  LOOP
    v := public.fn_nit_check(p_table_id, r.uid, r.joined_at);
    IF (v->>'ok')::boolean = false AND v->>'reason' = 'maintain_vpip' THEN
      user_id  := r.uid;
      vpip     := (v->>'vpip')::numeric;
      required := (v->>'required')::integer;
      hands    := (v->>'hands')::integer;
      RETURN NEXT;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION public.fn_nit_evictions(p_table_id uuid) OWNER TO postgres;

--
-- TOC entry 5132 (class 1255 OID 21055678)
-- Name: fn_nit_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_nit_status(p_table_id uuid) RETURNS TABLE(user_id uuid, hands integer, vpip numeric, required integer, window_hands integer, evict boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_on    boolean;
  v_min   integer;
  v_n     integer;
  v_game  uuid;
  v_since timestamptz;
  r       record;
BEGIN
  SELECT COALESCE(t.nit_game, false),
         GREATEST(COALESCE(t.maintain_percent_min, 0), 0),
         GREATEST(COALESCE(t.maintain_hands, 10), 1),
         t.cluster_id
    INTO v_on, v_min, v_n, v_game
    FROM public.tables t WHERE t.id = p_table_id LIMIT 1;
  IF NOT FOUND THEN RETURN; END IF;

  FOR r IN
    SELECT ts.user_id AS uid, ts.joined_at
      FROM public.table_seats ts
     WHERE ts.table_id = p_table_id
       AND ts.left_at IS NULL
  LOOP
    -- Same sample fn_nit_check judges: the sitting in the game on a cluster
    -- table, the chair elsewhere (2026-09-09).
    v_since := r.joined_at;
    IF v_game IS NOT NULL THEN
      SELECT cr.joined_at INTO v_since
        FROM public.cash_game_roster cr
       WHERE cr.game_id = v_game AND cr.user_id = r.uid AND cr.left_at IS NULL
       ORDER BY cr.joined_at DESC
       LIMIT 1;
      IF NOT FOUND THEN v_since := r.joined_at; END IF;

      SELECT count(*)::int,
             CASE WHEN count(*) = 0 THEN NULL
                  ELSE round(100.0 * avg(CASE WHEN f.vpip THEN 1 ELSE 0 END), 1) END
        INTO hands, vpip
        FROM public.ca_hand_facts f
       WHERE f.user_id = r.uid
         AND (v_since IS NULL OR f.played_at >= v_since)
         AND f.table_id IN (SELECT t2.id FROM public.tables t2 WHERE t2.cluster_id = v_game);
    ELSE
      SELECT count(*)::int,
             CASE WHEN count(*) = 0 THEN NULL
                  ELSE round(100.0 * avg(CASE WHEN f.vpip THEN 1 ELSE 0 END), 1) END
        INTO hands, vpip
        FROM public.ca_hand_facts f
       WHERE f.table_id = p_table_id
         AND f.user_id = r.uid
         AND (v_since IS NULL OR f.played_at >= v_since);
    END IF;
    user_id      := r.uid;
    required     := CASE WHEN v_on THEN v_min ELSE 0 END;
    window_hands := v_n;
    evict        := v_on AND v_min > 0 AND hands >= v_n AND vpip IS NOT NULL AND vpip < v_min;
    RETURN NEXT;
  END LOOP;
END;
$$;


