--
-- TOC entry 3965 (class 1255 OID 17458686)
-- Name: fn_notify_achievement_unlocked(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_achievement_unlocked() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_name     text;
  v_paid     text;
  v_diamonds integer := 0;
BEGIN
  -- Transition only: NULL -> non-NULL. On INSERT, OLD is NULL.
  IF NEW.unlocked_at IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.unlocked_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    SELECT d.name INTO v_name
      FROM public.training_achievement_definitions d
     WHERE d.id::text = NEW.achievement_id::text;

    -- fn_achievement_unlock_server writes '<achievement id>:<diamonds credited>'
    -- just before the row, for this transaction only. Nothing else sets it.
    v_paid := current_setting('ca.achievement_diamonds_awarded', true);
    IF v_paid LIKE NEW.achievement_id::text || ':%'
       AND split_part(v_paid, ':', 2) ~ '^[0-9]{1,9}$' THEN
      v_diamonds := split_part(v_paid, ':', 2)::integer;
    END IF;

    INSERT INTO public.notifications (user_id, type, title, message, data)
    VALUES (
      NEW.user_id,
      'achievement',
      'Achievement Unlocked',
      COALESCE(NULLIF(btrim(v_name), ''), NEW.achievement_id::text)
        || CASE WHEN v_diamonds > 0
                THEN ': +' || to_char(v_diamonds, 'FM999,999,999') || ' Diamonds'
                ELSE '' END,
      jsonb_build_object(
        'achievement_id', NEW.achievement_id,
        'achievement_name', COALESCE(NULLIF(btrim(v_name), ''), NEW.achievement_id::text),
        'diamonds_awarded', v_diamonds
      )
    );
  EXCEPTION WHEN OTHERS THEN
    -- A player earned the achievement. Failing to announce it must never undo
    -- it, and must never fail the write that earned it.
    RAISE WARNING 'fn_notify_achievement_unlocked failed for user % achievement %: %',
      NEW.user_id, NEW.achievement_id, SQLERRM;
  END;

  RETURN NEW;
END
$_$;


ALTER FUNCTION public.fn_notify_achievement_unlocked() OWNER TO postgres;

--
-- TOC entry 48172 (class 0 OID 0)
-- Dependencies: 3965
-- Name: FUNCTION fn_notify_achievement_unlocked(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_notify_achievement_unlocked() IS 'Raises the achievement-unlock notification server-side, on the NULL -> non-NULL transition of unlocked_at. Replaces the browser call to the retired pushNotificationService (issue #1498, ninth flow, missed because the call was split across lines). Carries no _push key, so the mirror trigger enqueues it and push-dispatch applies the consent gate. Never fails the write that earned the achievement. Added 2026-08-30.';


--
-- TOC entry 8273 (class 1255 OID 124506)
-- Name: fn_notify_agent_on_cashout(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_agent_on_cashout() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_player_name TEXT;
    v_club_name TEXT;
BEGIN
    -- Get player name
    SELECT display_name INTO v_player_name
    FROM profiles
    WHERE id = NEW.player_id;

    -- Get club name
    SELECT name INTO v_club_name
    FROM clubs
    WHERE id = NEW.club_id;

    -- Create notification for agent
    INSERT INTO notifications (user_id, type, title, message, data, created_at)
    VALUES (
        NEW.agent_id,
        'cashout_request',
        'Cashout Request',
        v_player_name || ' requested a cashout of ' || NEW.amount || ' chips in ' || v_club_name,
        jsonb_build_object(
            'cashout_id', NEW.id,
            'player_id', NEW.player_id,
            'club_id', NEW.club_id,
            'amount', NEW.amount
        ),
        NOW()
    );

    -- Create a club message notification for agent
    INSERT INTO messages (
        conversation_id,
        sender_id,
        receiver_id,
        content,
        is_read,
        created_at
    )
    SELECT 
        c.id,
        NEW.player_id,
        NEW.agent_id,
        'Cashout Request: ' || NEW.amount || ' Chips. Please Review In Your Agent Dashboard.',
        FALSE,
        NOW()
    FROM conversations c
    WHERE c.participant_ids @> ARRAY[NEW.player_id, NEW.agent_id]
      AND c.club_id = NEW.club_id
      AND c.category = 'club'
    LIMIT 1;

    RETURN NEW;
END;
$$;


