    v_group RECORD;
    v_slug  text;
    v_member RECORD;
    v_author_name text;
BEGIN
    IF NEW.post_type <> 'announcement' THEN RETURN NEW; END IF;
    IF COALESCE(NEW.is_published, true) = false THEN RETURN NEW; END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = NEW.group_id;
