--
-- TOC entry 8686 (class 1255 OID 5930358)
-- Name: fn_notify_interaction_share(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_interaction_share() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    sharer_name TEXT;
    original_author_id UUID;
    content_preview TEXT;
BEGIN
    IF NEW.interaction_type != 'share' THEN
        RETURN NEW;
    END IF;

    -- Check social_reels first
    SELECT author_id, LEFT(caption, 50) INTO original_author_id, content_preview
    FROM public.social_reels WHERE id = NEW.post_id;
    
    IF original_author_id IS NULL THEN
        SELECT author_id, LEFT(content, 50) INTO original_author_id, content_preview
        FROM public.social_posts WHERE id = NEW.post_id;
    END IF;

    -- Don't notify if user shares their own post or AI
    IF original_author_id IS NOT NULL AND original_author_id != NEW.user_id THEN
        IF EXISTS (SELECT 1 FROM public.content_authors WHERE profile_id = NEW.user_id AND is_active = true) THEN
            RETURN NEW;
        END IF;

        SELECT COALESCE(full_name, username, 'Someone') INTO sharer_name
        FROM public.profiles WHERE id = NEW.user_id;

        INSERT INTO public.notifications (user_id, actor_id, type, title, message, data)
        VALUES (
            original_author_id,
            NEW.user_id,
            'share',
            sharer_name,
            'shared your post',
            jsonb_build_object(
                'post_id', NEW.post_id,
                'actor_id', NEW.user_id,
                'actor_name', sharer_name
            )
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_notify_interaction_share() OWNER TO postgres;

--
-- TOC entry 9099 (class 1255 OID 29917)
-- Name: fn_notify_mention(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_mention() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  tagger_name text;
  trusted_writer boolean;
BEGIN
  IF TG_RELID <> 'public.mentions'::regclass OR TG_NAME <> 'trg_notify_mention'
     OR TG_OP <> 'INSERT' OR TG_WHEN <> 'AFTER' OR TG_LEVEL <> 'ROW' THEN
    RAISE EXCEPTION 'Mention notification requires its canonical INSERT trigger' USING ERRCODE='42501';
  END IF;
  -- current_user is the definer here; authorize against the original SQL role.
  trusted_writer := current_setting('role',true)='service_role'
    OR (current_setting('role',true)='none' AND session_user='postgres');
  IF NOT trusted_writer AND (
      current_setting('role',true) IS DISTINCT FROM 'authenticated'
      OR auth.uid() IS NULL OR NEW.mentioned_by_id IS DISTINCT FROM auth.uid()) THEN
    RAISE EXCEPTION 'Mention actor must match the authenticated caller' USING ERRCODE='42501';
  END IF;
  IF NEW.mentioned_user_id != NEW.mentioned_by_id THEN
    SELECT COALESCE(display_name,username,'Someone') INTO tagger_name
      FROM public.profiles WHERE id=NEW.mentioned_by_id;
    INSERT INTO public.notifications(user_id,type,title,message,data)
      VALUES(NEW.mentioned_user_id,'mention',tagger_name||' tagged you in a post','Tap to view',
        jsonb_build_object('post_id',NEW.post_id,'comment_id',NEW.comment_id,'tagger_id',NEW.mentioned_by_id));
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_notify_mention() OWNER TO postgres;

--
-- TOC entry 7155 (class 1255 OID 155895125)
-- Name: fn_notify_my_diamond_cash_session_recap(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_my_diamond_cash_session_recap(p_table_id uuid, p_occupancy_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r jsonb; v_id uuid; v_message text; v_hands text;
BEGIN
 r := public.fn_my_diamond_cash_session_recap(p_table_id,p_occupancy_id);
 IF r IS NULL OR r->>'status'<>'settled' THEN RETURN r; END IF;
 v_id := (r->>'custody_id')::uuid;
 v_hands := CASE WHEN r->'hands_played'='null'::jsonb THEN 'Hand Count Unavailable'
   ELSE format('Over %s Hands',r->>'hands_played') END;
 v_message := format('Session Ended. P/L: %s%s Diamonds. %s.',
   CASE WHEN (r->>'profit_loss')::numeric>=0 THEN '+' ELSE '' END,
   to_char((r->>'profit_loss')::numeric,'FM999,999,999,999,999,990'),v_hands);
 INSERT INTO public.notifications(id,user_id,type,title,message,metadata,read)
 VALUES(v_id,auth.uid(),'system','Session Complete',v_message,
   jsonb_build_object('tableId',p_table_id,'custodyId',v_id,'occupancyId',p_occupancy_id,
     'asset','diamonds','plDiamonds',r->'profit_loss','hands',r->'hands_played'),false)
 ON CONFLICT(id) DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM public.notifications n WHERE n.id=v_id AND n.user_id=auth.uid()
    AND n.metadata->>'custodyId'=v_id::text
    AND n.metadata->'plDiamonds'=r->'profit_loss'
    AND n.metadata->'hands'=r->'hands_played') THEN
   RAISE EXCEPTION 'recap_notification_identity_mismatch';
 END IF;
 RETURN r||jsonb_build_object('notification_id',v_id);
END $$;


ALTER FUNCTION public.fn_notify_my_diamond_cash_session_recap(p_table_id uuid, p_occupancy_id uuid) OWNER TO postgres;

--
-- TOC entry 8957 (class 1255 OID 31476)
-- Name: fn_notify_new_follow(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_new_follow() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    -- Don't notify for auto-follows from declined requests (separate notification)
    IF NEW.source = 'direct' THEN
        INSERT INTO public.notifications (
            user_id,
            actor_id,
            type,
            message,
            link
        ) VALUES (
            NEW.following_id,
            NEW.follower_id,
            'new_follow',
            'started following you',
            '/hub/user/' || NEW.follower_id
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_notify_new_follow() OWNER TO postgres;

--
-- TOC entry 5347 (class 1255 OID 29886)
-- Name: fn_notify_post_comment(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_post_comment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    commenter_name TEXT;
    post_author_id UUID;
    content_title TEXT;
BEGIN
    -- Check social_posts first (most common)
    SELECT author_id INTO post_author_id FROM public.social_posts WHERE id = NEW.post_id;

    -- Fall back to social_reels (for reel comments)
    IF post_author_id IS NULL THEN
        SELECT author_id, COALESCE(LEFT(caption, 40), 'your reel')
        INTO post_author_id, content_title
        FROM public.social_reels
        WHERE id = NEW.post_id;
    ELSE
        SELECT LEFT(COALESCE(content, 'your post'), 40) INTO content_title
        FROM public.social_posts WHERE id = NEW.post_id;
    END IF;

    IF post_author_id IS NOT NULL AND post_author_id != NEW.author_id THEN
        -- Skip notifications from AI horse bots
        IF EXISTS (SELECT 1 FROM public.content_authors WHERE profile_id = NEW.author_id AND is_active = true) THEN
            RETURN NEW;
        END IF;
        SELECT COALESCE(full_name, username, 'Someone') INTO commenter_name
        FROM public.profiles WHERE id = NEW.author_id;
        INSERT INTO public.notifications (user_id, actor_id, type, title, message, data)
        VALUES (
            post_author_id,
            NEW.author_id,
            'comment',
            commenter_name,
            'commented on your post',
            jsonb_build_object(
                'post_id', NEW.post_id,
                'comment_id', NEW.id,
                'actor_id', NEW.author_id,
                'actor_name', commenter_name
            )
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_notify_post_comment() OWNER TO postgres;

--
-- TOC entry 8332 (class 1255 OID 29884)
-- Name: fn_notify_post_like(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_post_like() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    liker_name TEXT;
    post_author_id UUID;
BEGIN
    IF NEW.interaction_type NOT IN ('like','love','haha','wow','sad','angry') THEN
        RETURN NEW;
    END IF;

    -- Check social_reels first, then social_posts
    SELECT author_id INTO post_author_id FROM public.social_reels WHERE id = NEW.post_id;
    IF post_author_id IS NULL THEN
        SELECT author_id INTO post_author_id FROM public.social_posts WHERE id = NEW.post_id;
    END IF;

    IF post_author_id IS NOT NULL AND post_author_id != NEW.user_id THEN
        -- Skip notifications from AI horse bots / content authors
        IF EXISTS (SELECT 1 FROM public.content_authors WHERE profile_id = NEW.user_id AND is_active = true) THEN
            RETURN NEW;
        END IF;
        SELECT COALESCE(full_name, username, 'Someone') INTO liker_name FROM public.profiles WHERE id = NEW.user_id;
        INSERT INTO public.notifications (user_id, actor_id, type, title, message, data)
        VALUES (
            post_author_id,
            NEW.user_id,
            'like',
            liker_name,
            'liked your post',
            jsonb_build_object('post_id', NEW.post_id, 'actor_id', NEW.user_id, 'actor_name', liker_name)
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_notify_post_like() OWNER TO postgres;

