COMMENT ON FUNCTION public.fn_notify_post_like() IS 'Updated 2026-05-12: sets actor_id column + actor_id/actor_name in data for feed enrichment.';


--
-- TOC entry 5989 (class 1255 OID 5920725)
-- Name: fn_notify_post_share(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_post_share() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    sharer_name TEXT;
    original_author_id UUID;
    post_preview TEXT;
BEGIN
    -- Only notify if this is a share (has shared_post_id)
    IF NEW.shared_post_id IS NULL THEN
        RETURN NEW;
    END IF;
    
    -- Get original post author
    SELECT author_id, LEFT(content, 50) INTO original_author_id, post_preview
    FROM public.social_posts WHERE id = NEW.shared_post_id;
    
    -- Don't notify if user shares their own post
    IF original_author_id = NEW.author_id THEN
        RETURN NEW;
    END IF;
    
    -- Get sharer's name
    SELECT COALESCE(full_name, username, 'Someone') INTO sharer_name
    FROM public.profiles WHERE id = NEW.author_id;
    
    -- Create notification with actor_id column set
    INSERT INTO public.notifications (user_id, actor_id, type, title, message, data)
    VALUES (
        original_author_id,
        NEW.author_id,
        'share',
        sharer_name,
        'shared your post',
        jsonb_build_object(
            'actor_id', NEW.author_id,
            'post_id', NEW.id,
            'original_post_id', NEW.shared_post_id,
            'actor_name', sharer_name
        )
    );
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_notify_post_share() OWNER TO postgres;

--
-- TOC entry 7077 (class 1255 OID 30222151)
-- Name: fn_notify_tournament_resumed(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_tournament_resumed(p_tournament_id uuid, p_reason text, p_exclude_user_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_name text;
  v_n integer := 0;
  r record;
BEGIN
  IF p_tournament_id IS NULL THEN RETURN 0; END IF;

  -- Only a RUNNING event resumes. A completed or cancelled one has nothing to
  -- come back to, and a replayed call after the finish must page nobody.
  SELECT COALESCE(NULLIF(btrim(t.name), ''), 'Your Tournament') INTO v_name
    FROM public.tournaments t
   WHERE t.id = p_tournament_id AND t.status = 'RUNNING';
  IF NOT FOUND THEN RETURN 0; END IF;

  FOR r IN
    SELECT tp.user_id
      FROM public.tournament_players tp
     WHERE tp.tournament_id = p_tournament_id
       AND tp.status IN ('registered', 'playing')
       AND NOT (tp.user_id = ANY (COALESCE(p_exclude_user_ids, '{}'::uuid[])))
       -- REACHABILITY, NEVER SPECIES (CLAUDE.md 10.5): the same predicate
       -- prepare_tournament_reminders uses. A player with a device is reached.
       AND EXISTS (SELECT 1 FROM public.push_subscriptions s
                    WHERE s.user_id = tp.user_id AND s.is_active)
  LOOP
    PERFORM public.fn_raise_notification(
      r.user_id,
      'tournament_resumed',
      'Your Tournament Has Resumed',
      v_name || ' Is Dealing Again. Tap To Return To Your Seat.',
      '/hub/club-arena/tournaments/' || p_tournament_id::text,
      jsonb_build_object(
        'tournamentId', p_tournament_id,
        'reason', COALESCE(p_reason, 'break'),
        'resumedAt', now()
      )
    );
    v_n := v_n + 1;
  END LOOP;

  RETURN v_n;
END $$;


ALTER FUNCTION public.fn_notify_tournament_resumed(p_tournament_id uuid, p_reason text, p_exclude_user_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 48200 (class 0 OID 0)
-- Dependencies: 7077
-- Name: FUNCTION fn_notify_tournament_resumed(p_tournament_id uuid, p_reason text, p_exclude_user_ids uuid[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_notify_tournament_resumed(p_tournament_id uuid, p_reason text, p_exclude_user_ids uuid[]) IS 'Called by the engine when a RUNNING tournament resumes after a maintenance or add-on break. Raises one tournament_resumed notification (-> push_outbox) for every registered/playing entrant with an active push subscription who is not in p_exclude_user_ids (the players with an open socket). Reachability decides, never species.';


--
-- TOC entry 8177 (class 1255 OID 159636753)
-- Name: fn_notify_video_library_channel_upload(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_video_library_channel_upload() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE sid uuid; follower record; claimed integer; source_name text; BEGIN
 -- The existing public view owns availability, moderation, takedowns and rights.
 IF NOT EXISTS(SELECT 1 FROM public.video_library_public_catalog WHERE youtube_video_id=NEW.youtube_video_id) THEN RETURN NEW; END IF;
 IF NEW.youtube_video_id = ANY(ARRAY['-rjQT0JOhGA','185vMNh9ECc','4441ee7htt0','524_3UypGkU','5wTToeCyu6I','9PrLmIWU0mU','CbXDixknmeM','fzNt4SdBGuQ','jdiDizWlIz0','JVJrPh0s1JQ','KQRZs6ytdWc','LA4z0Hi0Jf8','oINUSqHq_ck','OYgw9TiNqZY','pFbHkHhJO4Y','pIZW-gmcKio','slTxYV5S5n0','TXarmUgk02Q','RpU9bwH-2WI','FqiS7LaQSsg','vWVwhXeILoX','c0RqYhgRxH0','iDPJ3tHK6rA','D1lPQFCDRLg','bZqKGJz2HoE','fQ9Lklp6AuA','hA7c3HHFRUE','n0fHHMfvWck','GH5sEqf5p9Y','aVGVP7Oj8Jg','dbCLX6WbyJg','kiAPXh4jRHo']) THEN RETURN NEW; END IF;
 IF NEW.title IS NULL OR NEW.title !~ '[[:alnum:]]' OR NEW.title ~* '^(test(ing)?[[:space:].!,\-]*){1,4}$'
 OR (NEW.type IN ('cash','tournament') AND NEW.title ~* 'black[[:space:]]?jack|roulette|baccarat|\mcraps\M')
 OR (NEW.source_id='6bfb1441-98ed-41d6-929f-e147626dbffa' AND NEW.title !~* 'poker') THEN RETURN NEW; END IF;
 SELECT source_id INTO sid FROM public.video_library_channel_aliases WHERE source_key=NEW.source_id;
 IF sid IS NULL AND NEW.source_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
  SELECT id INTO sid FROM public.content_sources WHERE id=NEW.source_id::uuid AND kind='youtube_channel'
   AND provider='youtube' AND ingestion_mode='creator_uploads';
 END IF;
 IF sid IS NULL AND NEW.provider_channel_id IS NOT NULL THEN SELECT source_id INTO sid FROM public.video_library_channel_aliases WHERE source_key=NEW.provider_channel_id; END IF;
 IF sid IS NULL THEN RETURN NEW; END IF;
 SELECT name INTO source_name FROM public.content_sources WHERE id=sid;
 FOR follower IN SELECT * FROM public.video_library_channel_follows WHERE source_id=sid AND notifications_enabled
  AND created_at<=COALESCE(NEW.published_at,NEW.scraped_at) FOR SHARE
 LOOP
  INSERT INTO public.video_library_upload_notification_receipts(user_id,video_id,youtube_video_id,source_id) VALUES(follower.user_id,NEW.id,NEW.youtube_video_id,sid)
   ON CONFLICT(user_id,youtube_video_id) DO NOTHING;
  GET DIAGNOSTICS claimed=ROW_COUNT;
  IF claimed=1 THEN
   -- Deliberately unmarked: the installed DB notification producer bridge owns
   -- push routing, preferences, staleness, caps, and platform recipient policy.
   INSERT INTO public.notifications(user_id,type,title,message,link,action_url,data)
   VALUES(follower.user_id,'video_library_upload','New Video From '||source_name,'The Channel Published A New Verified Video.',
    '/hub/video-library/watch/'||NEW.youtube_video_id,'/hub/video-library/watch/'||NEW.youtube_video_id,
    jsonb_build_object('source_id',sid,'video_id',NEW.youtube_video_id,'channel_url','/hub/video-library/channels/'||sid::text));
  END IF;
 END LOOP;
 RETURN NEW;
END $_$;


ALTER FUNCTION public.fn_notify_video_library_channel_upload() OWNER TO postgres;

--
-- TOC entry 7899 (class 1255 OID 83808648)
-- Name: fn_offer_lifetime_first_club_welcome(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_offer_lifetime_first_club_welcome() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_owner uuid; v_claim public.club_owner_creation_history%ROWTYPE; v_result jsonb;
BEGIN
  PERFORM public.fn_club_membership_lock(NEW.user_id);
  SELECT owner_id INTO v_owner FROM public.clubs WHERE id=NEW.club_id;
  IF v_owner IS DISTINCT FROM NEW.user_id THEN
    RAISE EXCEPTION 'WELCOME_ENTITLEMENT_OWNER_MISMATCH' USING ERRCODE='23514';
  END IF;
  INSERT INTO public.club_owner_creation_history
    (owner_id,first_club_id,first_creation_request_id,welcome_eligible,provenance)
  VALUES(NEW.user_id,NEW.club_id,NEW.request_id,true,'prospective')
  ON CONFLICT(owner_id) DO NOTHING RETURNING * INTO v_claim;
  IF NOT FOUND OR v_claim.welcome_eligible IS NOT TRUE THEN RETURN NEW; END IF;
  INSERT INTO public.club_welcome_entitlements(club_id,owner_id,creation_request_id)
  VALUES(NEW.club_id,NEW.user_id,NEW.request_id);
  v_result:=public.fn_provision_first_club_welcome_package(NEW.club_id,NEW.request_id);
  IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE THEN
    RAISE EXCEPTION 'WELCOME_PACKAGE_ATOMIC_PROVISION_FAILED: %',COALESCE(v_result->>'reason','unknown');
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_offer_lifetime_first_club_welcome() OWNER TO postgres;

--
-- TOC entry 3731 (class 1255 OID 17389687)
-- Name: fn_offer_open_seat(uuid, interval, interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_offer_open_seat(p_table_id uuid, p_offer_ttl interval DEFAULT '00:01:00'::interval, p_entry_ttl interval DEFAULT '24:00:00'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tbl      record;
  v_next     record;
  v_notif_id uuid;
  v_expired  int := 0;
  v_cap      int := 1;
  v_selected boolean := false;
  v_game_id uuid;
  v_table_entry_id uuid;
  v_legacy_holds integer := 0;
BEGIN
  -- Share the actual seat admission key with cash-game joins and buy-ins.
  -- A busy table is left untouched; a caller may already hold sweep rows,
  -- so waiting for another claimant here can invert that caller's locks.
  IF p_table_id IS NOT NULL AND NOT pg_try_advisory_xact_lock(
       hashtextextended('table_seat:' || p_table_id::text, 0)) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_claim_busy');
  END IF;

  SELECT COALESCE(max_concurrent_holds, 1) INTO v_cap FROM public.waitlist_policy WHERE id;
  IF v_cap IS NULL THEN v_cap := 1; END IF;

  SELECT t.id, t.name, t.tournament_id, t.max_players, t.current_players
    INTO v_tbl
    FROM public.tables t
   WHERE t.id = p_table_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;

  IF v_tbl.tournament_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_table');
  END IF;

  -- The cached lobby count cannot authorize an exclusive chair offer.
  v_tbl.current_players := (SELECT count(*) FROM public.table_seats s
                            WHERE s.table_id=p_table_id AND s.left_at IS NULL);
  IF v_tbl.current_players >= COALESCE(v_tbl.max_players, 9) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_full');
  END IF;

  WITH dead AS (
    UPDATE public.table_waitlist
       SET status = 'expired'
     WHERE table_id = p_table_id
       AND status = 'notified'
       AND COALESCE(hold_expires_at, notified_at + p_offer_ttl) < now()
    RETURNING user_id
  )
  -- A lapsed hold is not a notification (Dan 2026-10-14).
  SELECT count(*) INTO v_expired FROM dead;

  UPDATE public.table_waitlist
     SET status = 'expired'
   WHERE table_id = p_table_id
     AND status = 'waiting'
     AND created_at < now() - p_entry_ttl;

  UPDATE public.table_waitlist w
     SET status = 'seated'
   WHERE w.table_id = p_table_id
     AND w.status = 'waiting'
     AND EXISTS (
       SELECT 1 FROM public.table_seats s
        WHERE s.table_id = p_table_id
          AND s.left_at IS NULL
          AND s.user_id = w.user_id
     );

  -- This same reader also reserves pending non-swap seat moves. Re-read it
  -- after expiry and under the common table key, just like the join door.
  -- Pre-column offers retain their original notified_at + TTL reservation.
  -- The shared reader counts explicit hold_expires_at values only.
  SELECT count(*) INTO v_legacy_holds FROM public.table_waitlist h
   WHERE h.table_id=p_table_id AND h.status='notified'
     AND h.hold_expires_at IS NULL AND h.notified_at+p_offer_ttl>now();
  IF COALESCE(public.fn_cash_game_open_seats(p_table_id),0) <= v_legacy_holds THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'open_seats_already_held', 'offers_expired', v_expired
    );
  END IF;

  -- THE HEAD OF THE QUEUE, LOCKED, AND NOT ALREADY HOLDING A SEAT ELSEWHERE.
  -- A hold is exclusive, so handing one player several at once takes seats
  -- away from everybody behind them. Skipping a capped player leaves their
  -- place in line untouched: they are passed over for THIS seat only.
  --
  -- 2026-08-31 (Dan, binding: horses are never skipped): the is_horse
  -- exclusion that used to sit in this predicate is GONE. Whoever is first in
  -- line is offered the seat. The JOIN to profiles stays: it is no longer read
  -- to exclude anyone, but dropping it would newly qualify waitlist rows whose
  -- user has no profile row at all.
  FOR v_next IN
  SELECT w.id, w.user_id, COALESCE(p.is_horse, false) AS is_horse
    FROM public.table_waitlist w
    JOIN public.profiles p ON p.id = w.user_id
   WHERE w.table_id = p_table_id
     AND w.status = 'waiting'
     AND (
       v_cap = 0
       OR (
         SELECT count(*) FROM public.table_waitlist h
          WHERE h.user_id = w.user_id
            AND h.status = 'notified'
            AND COALESCE(h.hold_expires_at, h.notified_at + p_offer_ttl) > now()
       ) < v_cap
     )
   ORDER BY w.created_at, w.id
     FOR UPDATE OF w SKIP LOCKED
  LOOP
    -- Queue-row locks on different tables do not serialize this player's
    -- offer allowance. A nonblocking claim preserves other queue members'
    -- progress without waiting while this transaction owns a table key.
    CONTINUE WHEN NOT pg_try_advisory_xact_lock(
      hashtextextended('waitlist_offer_user:' || v_next.user_id::text, 0));
    CONTINUE WHEN v_cap > 0 AND (
      SELECT count(*) FROM public.table_waitlist h
       WHERE h.user_id=v_next.user_id AND h.status='notified'
         AND COALESCE(h.hold_expires_at,h.notified_at+p_offer_ttl)>now()
    ) >= v_cap;
    -- NO CHAIR IS HELD FOR A PLAYER WHO CANNOT PAY FOR IT (Dan 2026-10-12).
    -- A player in line whose wallets cannot cover this table's minimum is
    -- passed over for THIS seat and keeps their place, exactly as a capped
    -- player is above; the same rule for every player in line (10.5).
    CONTINUE WHEN NOT public.fn_ca_cash_wallet_covers(
      v_next.user_id, p_table_id, NULL,
      public.fn_ca_cash_entry_need(v_next.user_id, p_table_id));
    v_selected := true;
    EXIT;
  END LOOP;


  -- A game queue is admitted by this same vacancy event, not by another
  -- Join Game click or a repair worker. Table-specific FIFO keeps its priority.
  IF NOT v_selected THEN
    SELECT g.id INTO v_game_id
      FROM public.tables t JOIN public.cash_games g ON g.id=t.cluster_id
     WHERE t.id=p_table_id AND g.enabled
       AND t.lifecycle IN ('live','opening') AND t.status IN ('waiting','running','active')
       AND NOT coalesce(t.is_deleted,false);
    IF v_game_id IS NOT NULL THEN
      UPDATE public.cash_game_waitlist SET status='expired',updated_at=now()
       WHERE game_id=v_game_id AND status='waiting' AND created_at<=now()-p_entry_ttl;
      FOR v_next IN
        SELECT w.id,w.user_id,coalesce(p.is_horse,false) AS is_horse
          FROM public.cash_game_waitlist w JOIN public.profiles p ON p.id=w.user_id
         WHERE w.game_id=v_game_id AND w.status='waiting'
           AND w.created_at > now()-p_entry_ttl
         ORDER BY w.created_at,w.id
      LOOP
        -- Lock one candidate at a time. A cursor that locks the entire list
        -- would hide later eligible buyers from a simultaneous vacancy.
        PERFORM 1 FROM public.cash_game_waitlist w
         WHERE w.id=v_next.id AND w.status='waiting' FOR UPDATE SKIP LOCKED;
        CONTINUE WHEN NOT FOUND;
        CONTINUE WHEN NOT pg_try_advisory_xact_lock(
          hashtextextended('waitlist_offer_user:' || v_next.user_id::text,0));
        CONTINUE WHEN EXISTS(
          SELECT 1 FROM public.table_seats s JOIN public.tables t ON t.id=s.table_id
           WHERE s.user_id=v_next.user_id AND s.left_at IS NULL AND t.cluster_id=v_game_id);
        CONTINUE WHEN EXISTS(
          SELECT 1 FROM public.table_waitlist h JOIN public.tables t ON t.id=h.table_id
           WHERE h.user_id=v_next.user_id AND h.status='notified'
             AND coalesce(h.hold_expires_at,h.notified_at+p_offer_ttl)>now()
             AND t.cluster_id=v_game_id);
        CONTINUE WHEN v_cap>0 AND (
          SELECT count(*) FROM public.table_waitlist h
           WHERE h.user_id=v_next.user_id AND h.status='notified'
             AND coalesce(h.hold_expires_at,h.notified_at+p_offer_ttl)>now())>=v_cap;
        CONTINUE WHEN public.fn_cash_game_barred_seconds(v_game_id,v_next.user_id) IS NOT NULL;
        CONTINUE WHEN EXISTS(
          SELECT 1 FROM public.cash_games g WHERE g.id=v_game_id
            AND (coalesce((g.ruleset_snapshot #>> '{options,is_private}')::boolean,false)
                 OR EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=g.club_id AND c.is_public=false))
            AND NOT EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=g.club_id AND c.owner_id=v_next.user_id)
            AND NOT EXISTS(SELECT 1 FROM public.club_members m WHERE m.club_id=g.club_id
                 AND m.user_id=v_next.user_id AND m.status IN ('active','approved')));
        CONTINUE WHEN NOT public.fn_ca_cash_wallet_covers(
          v_next.user_id,p_table_id,NULL,public.fn_ca_cash_entry_need(v_next.user_id,p_table_id));
        UPDATE public.cash_game_waitlist SET status='notified',updated_at=now()
         WHERE id=v_next.id AND status='waiting';
        INSERT INTO public.table_waitlist(table_id,user_id,position,status)
          VALUES(p_table_id,v_next.user_id,0,'waiting')
          ON CONFLICT (table_id,user_id) WHERE status IN ('waiting','notified')
          DO UPDATE SET status='waiting'
          RETURNING id INTO v_table_entry_id;
        v_next.id := v_table_entry_id;
        v_selected := true;
        EXIT;
      END LOOP;
    END IF;
  END IF;

  IF NOT v_selected THEN
    RETURN jsonb_build_object(
      'ok', false, 'reason', 'nobody_waiting', 'offers_expired', v_expired
    );
  END IF;

  UPDATE public.table_waitlist
     SET status = 'notified',
         notified_at = now(),
         hold_expires_at = now() + p_offer_ttl
   WHERE id = v_next.id;

  -- The notification row is written for every player alike, so the queue's
  -- audit trail is identical. Only the PUSH flag differs: a horse has no
  -- device to push to, which is the sanctioned identification-for-display use,
  -- and it reuses the `_push:skip` marker the expiry notification above
  -- already uses. It decides how a message is delivered, never whether a seat
  -- is offered.
  INSERT INTO public.notifications (user_id, type, title, message, data)
  VALUES (
    v_next.user_id,
    'waitlist_seat_open',
    'Seat Open',
    'A Seat Just Opened At ' || COALESCE(v_tbl.name, 'Your Waitlisted Table') ||
      '. It Is Held For You For 60 Seconds. Sit Down Now To Claim It.',
    CASE WHEN v_next.is_horse
         THEN jsonb_build_object('table_id', p_table_id, '_push', 'skip')
         ELSE jsonb_build_object('table_id', p_table_id)
    END
  )
  RETURNING id INTO v_notif_id;

  RETURN jsonb_build_object(
    'ok', true,
    'user_id', v_next.user_id,
    'table_name', v_tbl.name,
    'notification_id', v_notif_id,
    'hold_expires_in_seconds', EXTRACT(epoch FROM p_offer_ttl)::int,
    'offers_expired', v_expired
  );
END
$$;


