--
-- TOC entry 5713 (class 1255 OID 16458224)
-- Name: fn_owner_start_tournament_now(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_owner_start_tournament_now(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid  uuid := auth.uid();
  v_t    record;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;

  SELECT id, club_id, status, start_time, current_players, min_players
    INTO v_t
    FROM tournaments
   WHERE id = p_tournament_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found');
  END IF;

  IF NOT public.fn_can_create_games(v_t.club_id, v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorised');
  END IF;

  IF v_t.status NOT IN ('REGISTERING', 'ANNOUNCED') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_startable',
                              'status', v_t.status);
  END IF;

  IF v_t.start_time IS NOT NULL AND v_t.start_time <= now() THEN
    RETURN jsonb_build_object('ok', true, 'already_due', true,
                              'start_time', v_t.start_time);
  END IF;

  UPDATE tournaments
     SET start_time = now()
   WHERE id = p_tournament_id;

  RETURN jsonb_build_object(
    'ok', true,
    'already_due', false,
    'start_time', now(),
    'current_players', COALESCE(v_t.current_players, 0),
    'min_players', COALESCE(v_t.min_players, 3)
  );
END;
$$;


ALTER FUNCTION public.fn_owner_start_tournament_now(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 8580 (class 1255 OID 74584663)
-- Name: fn_p7_answer_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_p7_answer_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_author_id uuid;
  v_reveal_at timestamptz;
  v_revealed_at timestamptz;
  v_options jsonb;
BEGIN
  NEW.option := upper(btrim(COALESCE(NEW.option, '')));
  -- Graded and reward fields belong to the reveal, never to the answer insert.
  NEW.is_correct := NULL;
  NEW.reward_reference := NULL;
  NEW.reward_result := NULL;
  NEW.reward_transaction_id := NULL;
  NEW.created_at := now();

  -- The share lock makes a reveal that is running right now finish first.
  SELECT p.author_id, p.reveal_at, p.revealed_at, p.options
    INTO v_author_id, v_reveal_at, v_revealed_at, v_options
    FROM public.social_puzzles p
   WHERE p.id = NEW.puzzle_id
   FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'answer names a puzzle that does not exist',
      CONSTRAINT = 'p7_answer_puzzle_exists';
  END IF;

  IF v_revealed_at IS NOT NULL OR now() >= v_reveal_at THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'answers are closed for this puzzle',
      CONSTRAINT = 'p7_answers_closed';
  END IF;

  IF NEW.user_id IS NULL OR NEW.user_id = v_author_id THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'the puzzle author cannot answer their own puzzle',
      CONSTRAINT = 'p7_author_cannot_answer';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_options) o WHERE o ->> 'key' = NEW.option) THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'answer option must be one of the puzzle option keys',
      CONSTRAINT = 'p7_answer_option_known';
  END IF;

  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_p7_answer_guard() OWNER TO postgres;

