--

COMMENT ON FUNCTION public.fn_p7_publish_puzzle(p_author_id uuid, p_kind text, p_hand_id uuid, p_source_review_id bigint, p_game_variant text, p_board jsonb, p_prompt text, p_options jsonb, p_correct_option text, p_salt text, p_explanation text, p_proof jsonb, p_evaluator_version text, p_rewardable boolean, p_reveal_hours integer, p_metadata jsonb) IS 'Service-role-only atomic Phase 7 puzzle publisher: one social_posts row (prompt, metadata.publication_key p7:<kind>:<hand_id>, metadata.puzzle), one social_puzzles row and one social_puzzle_solutions row, or nothing. Returns {"status":"created"|"duplicate","puzzle_id","post_id"}.';


--
-- TOC entry 4609 (class 1255 OID 74584795)
-- Name: fn_p7_reveal_puzzle(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_p7_reveal_puzzle(p_puzzle_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_puzzle public.social_puzzles%ROWTYPE;
  v_solution public.social_puzzle_solutions%ROWTYPE;
  v_now timestamptz := now();
  v_live boolean;
  v_label text;
  v_comment text;
  v_tail text;
  v_comment_id uuid;
  v_answers integer := 0;
  v_correct integer := 0;
  v_paid integer := 0;
  v_refused jsonb := '{}'::jsonb;
  v_reason text;
  v_answer record;
  v_reference text;
  v_result jsonb;
  v_transaction_id uuid;
  v_profile_created_at timestamptz;
BEGIN
  IF COALESCE(auth.role()::text, '') <> 'service_role' THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'fn_p7_reveal_puzzle requires the service role';
  END IF;

  IF p_puzzle_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'fn_p7_reveal_puzzle requires a puzzle id';
  END IF;

  -- The row lock serializes reveals of one puzzle; the second caller sees revealed_at.
  SELECT * INTO v_puzzle
    FROM public.social_puzzles sp
   WHERE sp.id = p_puzzle_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = format('puzzle %s does not exist', p_puzzle_id);
  END IF;

  SELECT count(*)::integer,
         (count(*) FILTER (WHERE a.is_correct IS TRUE))::integer,
         (count(*) FILTER (WHERE a.reward_transaction_id IS NOT NULL))::integer
    INTO v_answers, v_correct, v_paid
    FROM public.social_puzzle_answers a
   WHERE a.puzzle_id = p_puzzle_id;

  IF v_puzzle.revealed_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'status', 'already_revealed',
      'puzzle_id', p_puzzle_id,
      'post_id', v_puzzle.post_id,
      'answers', v_answers, 'correct', v_correct, 'paid', v_paid,
      'refused', '{}'::jsonb
    );
  END IF;

  IF v_now < v_puzzle.reveal_at THEN
    RETURN jsonb_build_object(
      'status', 'not_due',
      'puzzle_id', p_puzzle_id,
      'post_id', v_puzzle.post_id,
      'reveal_at', v_puzzle.reveal_at,
      'answers', v_answers, 'correct', 0, 'paid', 0,
      'refused', '{}'::jsonb
    );
  END IF;

  SELECT * INTO v_solution
    FROM public.social_puzzle_solutions s
   WHERE s.puzzle_id = p_puzzle_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = format('puzzle %s has no solution row', p_puzzle_id),
      CONSTRAINT = 'p7_solution_exists';
  END IF;

  SELECT o ->> 'label' INTO v_label
    FROM jsonb_array_elements(v_puzzle.options) o
   WHERE o ->> 'key' = v_solution.correct_option;

  IF v_label IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = format('puzzle %s solution names an option the puzzle does not have', p_puzzle_id),
      CONSTRAINT = 'p7_solution_option_known';
  END IF;

  -- Fail closed on any tampering: the stored solution must match the public commitment.
  IF v_puzzle.answer_commitment
     <> encode(sha256(convert_to(v_puzzle.puzzle_key || ':' || v_solution.correct_option || ':' || v_solution.salt, 'UTF8')), 'hex') THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = format('puzzle %s solution does not match its answer commitment', p_puzzle_id),
      CONSTRAINT = 'p7_commitment_matches';
  END IF;

  -- Grade every answer first; a graded row is a fact whatever happens to the post.
  UPDATE public.social_puzzle_answers a
     SET is_correct = (a.option = v_solution.correct_option)
   WHERE a.puzzle_id = p_puzzle_id;

  SELECT count(*)::integer, (count(*) FILTER (WHERE a.is_correct IS TRUE))::integer
    INTO v_answers, v_correct
    FROM public.social_puzzle_answers a
   WHERE a.puzzle_id = p_puzzle_id;

  -- Liveness as the horses read it (HorseSocialEngine postLiveness).
  v_live := NULL;
  IF v_puzzle.post_id IS NOT NULL THEN
    SELECT (COALESCE(sp.is_deleted, false) = false
            AND sp.visibility = 'public'
            AND COALESCE(sp.is_flagged, false) = false)
      INTO v_live
      FROM public.social_posts sp
     WHERE sp.id = v_puzzle.post_id;
  END IF;

  IF v_live IS DISTINCT FROM true THEN
    UPDATE public.social_puzzles sp
       SET revealed_at = v_now,
           correct_option = v_solution.correct_option,
           explanation = v_solution.explanation,
           closed_reason = 'post_gone'
     WHERE sp.id = p_puzzle_id;

    RETURN jsonb_build_object(
      'status', 'closed_post_gone',
      'puzzle_id', p_puzzle_id,
      'post_id', v_puzzle.post_id,
      'answers', v_answers, 'correct', v_correct, 'paid', 0,
      'refused', CASE WHEN v_correct > 0 THEN jsonb_build_object('post_gone', v_correct) ELSE '{}'::jsonb END
    );
  END IF;

  -- The reveal comment: explanation, the answer, then the key that opens the commitment.
  v_tail := E'\n\n' || 'Answer ' || v_solution.correct_option || ': ' || v_label || '.'
            || E'\n' || 'answer key ' || v_solution.salt;
  v_comment := v_solution.explanation || v_tail;
  IF char_length(v_comment) > 500 THEN
    v_comment := rtrim(left(v_solution.explanation, 500 - char_length(v_tail))) || v_tail;
  END IF;

  INSERT INTO public.social_comments (post_id, author_id, content)
  VALUES (v_puzzle.post_id, v_puzzle.author_id, v_comment)
  RETURNING id INTO v_comment_id;

  -- Pay each correct answer once. The reference is unique in the ledger, so a
  -- retry of a committed payment is refused as 'duplicate' inside award_diamonds_v2.
  FOR v_answer IN
    SELECT a.id, a.user_id
      FROM public.social_puzzle_answers a
     WHERE a.puzzle_id = p_puzzle_id
       AND a.is_correct IS TRUE
     ORDER BY a.created_at ASC, a.id ASC
  LOOP
    v_reference := 'social_puzzle_' || v_answer.user_id::text || '_' || p_puzzle_id::text;
    v_transaction_id := NULL;

    IF v_puzzle.rewardable IS NOT TRUE THEN
      v_result := jsonb_build_object('success', false, 'awarded', 0, 'reason', 'not_rewardable', 'source', 'fn_p7_reveal_puzzle');
    ELSE
      SELECT pr.created_at INTO v_profile_created_at
        FROM public.profiles pr
       WHERE pr.id = v_answer.user_id;

      IF v_profile_created_at IS NULL THEN
        v_result := jsonb_build_object('success', false, 'awarded', 0, 'reason', 'profile_not_found', 'source', 'fn_p7_reveal_puzzle');
      ELSIF (v_now - v_profile_created_at) < interval '24 hours' THEN
        v_result := jsonb_build_object('success', false, 'awarded', 0, 'reason', 'account_too_new', 'source', 'fn_p7_reveal_puzzle');
      ELSE
        BEGIN
          v_result := public.award_diamonds_v2(
            v_answer.user_id,
            'social_post',
            v_reference,
            p_puzzle_id::text,
            jsonb_build_object('source', 'p7_puzzle_reveal', 'puzzle_id', p_puzzle_id, 'answer_id', v_answer.id)
          );
        EXCEPTION WHEN OTHERS THEN
          -- One refused ledger write must not hold every other answer hostage;
          -- the reason is stored on the row and reported, and nothing was paid.
          v_result := jsonb_build_object(
            'success', false, 'awarded', 0, 'reason', 'error',
            'sqlstate', SQLSTATE, 'message', left(SQLERRM, 200), 'source', 'fn_p7_reveal_puzzle');
        END;
      END IF;

      IF COALESCE((v_result ->> 'success')::boolean, false) THEN
        SELECT t.id INTO v_transaction_id
          FROM public.diamond_transactions t
         WHERE t.user_id = v_answer.user_id
           AND t.reference_id = v_reference
         ORDER BY t.created_at DESC
         LIMIT 1;
      END IF;
    END IF;

    UPDATE public.social_puzzle_answers a
       SET reward_reference = v_reference,
           reward_result = v_result,
           reward_transaction_id = v_transaction_id
     WHERE a.id = v_answer.id;

    IF v_transaction_id IS NOT NULL THEN
      v_paid := v_paid + 1;
    ELSE
      v_reason := CASE
        WHEN COALESCE((v_result ->> 'success')::boolean, false) THEN 'transaction_missing'
        ELSE COALESCE(NULLIF(btrim(v_result ->> 'reason'), ''), 'unknown')
      END;
      v_refused := jsonb_set(v_refused, ARRAY[v_reason], to_jsonb(COALESCE((v_refused ->> v_reason)::integer, 0) + 1), true);
    END IF;
  END LOOP;

  UPDATE public.social_puzzles sp
     SET revealed_at = v_now,
         correct_option = v_solution.correct_option,
         explanation = v_solution.explanation,
         closed_reason = 'revealed',
         reveal_comment_id = v_comment_id
   WHERE sp.id = p_puzzle_id;

  RETURN jsonb_build_object(
    'status', 'revealed',
    'puzzle_id', p_puzzle_id,
    'post_id', v_puzzle.post_id,
    'comment_id', v_comment_id,
    'answers', v_answers, 'correct', v_correct, 'paid', v_paid,
    'refused', v_refused
  );
END
$$;


ALTER FUNCTION public.fn_p7_reveal_puzzle(p_puzzle_id uuid) OWNER TO postgres;

--
-- TOC entry 48220 (class 0 OID 0)
-- Dependencies: 4609
-- Name: FUNCTION fn_p7_reveal_puzzle(p_puzzle_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_p7_reveal_puzzle(p_puzzle_id uuid) IS 'Service-role-only Phase 7 reveal: locks the puzzle, returns not_due / already_revealed / closed_post_gone without side effects beyond grading, otherwise writes the reveal comment as the horse, grades every answer, pays correct answers of rewardable puzzles once through award_diamonds_v2 (reference social_puzzle_<user>_<puzzle>) after the 24-hour profile-age gate, and sets revealed_at.';


--
-- TOC entry 5056 (class 1255 OID 78765585)
-- Name: fn_p9_publish_hand_clip(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_p9_publish_hand_clip(p_job_id uuid) RETURNS public.hand_clip_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job public.hand_clip_jobs;
  v_engine boolean;
  v_mode boolean;
  v_is_horse boolean;
  v_content text;
  v_variant text;
  v_big_blind numeric;
  v_pot numeric;
  v_bb_text text;
  v_pot_bb text;
  v_metadata jsonb;
  v_post_id uuid;
  v_reel_id uuid;
BEGIN
  IF COALESCE(auth.role()::text, '') <> 'service_role' THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'fn_p9_publish_hand_clip requires the service role';
  END IF;

  SELECT * INTO v_job
    FROM public.hand_clip_jobs
   WHERE id = p_job_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0002',
      MESSAGE = 'hand clip job not found';
  END IF;

  IF v_job.kind <> 'horse' THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'only a horse hand clip job is published by the fleet; a player posts a clip from their own session';
  END IF;

  IF v_job.state <> 'ready' THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = format('a hand clip job is published from ready only (state %s)', v_job.state);
  END IF;

  IF v_job.auto_publish IS NOT TRUE THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'this hand clip job is not marked for publication';
  END IF;

  IF v_job.social_post_id IS NOT NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'this hand clip job already carries a post';
  END IF;

  -- The two switches, read fail closed: an unreadable switch publishes
  -- nothing. Either off returns the row unchanged; the clip stays ready.
  SELECT s.engine_enabled INTO v_engine
    FROM public.content_settings s
   ORDER BY s.created_at ASC NULLS LAST
   LIMIT 1;

  SELECT m.enabled INTO v_mode
    FROM public.horse_post_modes m
   WHERE m.mode = 'hand_clip';

  IF v_engine IS DISTINCT FROM true OR v_mode IS DISTINCT FROM true THEN
    RETURN v_job;
  END IF;

  SELECT p.is_horse INTO v_is_horse
    FROM public.profiles p
   WHERE p.id = v_job.author_id;

  IF v_is_horse IS DISTINCT FROM true THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'hand clip publication requires a horse author';
  END IF;

  IF NULLIF(btrim(COALESCE(v_job.video_url, '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(v_job.poster_url, '')), '') IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'a ready hand clip carries a video URL and a poster URL';
  END IF;

  -- The post text: the route caption, or a plain line from the hand row
  -- (variant, blinds, pot in big blinds). Only numbers from the row and
  -- fixed words; never a name.
  v_content := btrim(COALESCE(v_job.caption, ''));
  IF v_content = '' THEN
    SELECT h.game_variant, h.big_blind, h.pot_size
      INTO v_variant, v_big_blind, v_pot
      FROM public.hand_history h
     WHERE h.id = v_job.hand_id;

    v_variant := NULLIF(btrim(replace(COALESCE(v_variant, ''), '_', ' ')), '');
    IF v_big_blind IS NOT NULL AND v_big_blind > 0 THEN
      v_bb_text := v_big_blind::text;
      IF v_bb_text LIKE '%.%' THEN
        v_bb_text := rtrim(rtrim(v_bb_text, '0'), '.');
      END IF;
      v_pot_bb := CASE WHEN v_pot IS NOT NULL THEN round(v_pot / v_big_blind, 1)::text ELSE NULL END;
      v_content := format('Hand clip: %s at %s big blinds.', COALESCE(v_variant, 'poker'), v_bb_text);
      IF v_pot_bb IS NOT NULL THEN
        v_content := v_content || format(' Pot %s BB.', v_pot_bb);
      END IF;
    ELSE
      v_content := format('Hand clip: %s.', COALESCE(v_variant, 'poker'));
    END IF;
  END IF;

  -- The Phase 6 output law, fail closed: no em dash, no en dash, no emoji,
  -- and the social_posts content check (2000 characters).
  IF v_content ~ '[\U00002013\U00002014]' THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'hand clip caption must not contain an em dash or an en dash';
  END IF;
  IF v_content ~ '[\U0001F000-\U0001FAFF\U00002600-\U000027BF\U0000FE0F]' THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'hand clip caption must not contain an emoji';
  END IF;
  IF char_length(v_content) = 0 OR char_length(v_content) > 2000 THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'hand clip caption must contain 1 to 2000 characters';
  END IF;

  v_metadata := jsonb_build_object(
    'scheduler', 'phase9',
    'hand_id', v_job.hand_id,
    'hand_clip_job_id', v_job.id,
    'style', v_job.style,
    'publication_contract', 'p9_hand_clip'
  );
  IF NULLIF(btrim(COALESCE(v_job.publication_key, '')), '') IS NOT NULL THEN
    v_metadata := v_metadata || jsonb_build_object('publication_key', btrim(v_job.publication_key));
  END IF;

  -- The same column list publish_user_video_reel inserts. The contract trigger
  -- keeps rights owned for the service role on a platform storage URL; the
  -- mirror trigger creates the reel; the topics rule keeps the hand facet.
  INSERT INTO public.social_posts (
    author_id,
    content,
    content_type,
    media_urls,
    visibility,
    audience_mode,
    thumbnail_url,
    metadata,
    topics,
    origin_type,
    playback_type,
    topic,
    rights_status,
    youtube_video_id,
    canonical_asset_key
  ) VALUES (
    v_job.author_id,
    v_content,
    'video',
    jsonb_build_array(v_job.video_url),
    'public',
    'public',
    v_job.poster_url,
    v_metadata,
    ARRAY['poker', 'hand']::text[],
    'horse',
    'native',
    'poker',
    'owned',
    NULL,
    'native:' || md5(v_job.video_url)
  )
  RETURNING id INTO v_post_id;

  SELECT r.id INTO v_reel_id
    FROM public.social_reels r
   WHERE r.source_post_id = v_post_id
   ORDER BY r.created_at ASC NULLS LAST, r.id ASC
   LIMIT 1;

  IF v_reel_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'hand clip publication did not create a linked reel';
  END IF;

  -- The deep link is publication state (publish_user_video_reel pattern).
  UPDATE public.social_posts p
     SET link_url = '/hub/reels?id=' || v_reel_id::text
   WHERE p.id = v_post_id;

  UPDATE public.hand_clip_jobs
     SET state = 'published',
         social_post_id = v_post_id,
         social_reel_id = v_reel_id,
         published_at = now(),
         updated_at = now()
   WHERE id = v_job.id
  RETURNING * INTO v_job;

  RETURN v_job;
END
$$;


ALTER FUNCTION public.fn_p9_publish_hand_clip(p_job_id uuid) OWNER TO postgres;

--
-- TOC entry 48222 (class 0 OID 0)
-- Dependencies: 5056
-- Name: FUNCTION fn_p9_publish_hand_clip(p_job_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_p9_publish_hand_clip(p_job_id uuid) IS 'Phase 9: publishes a ready, auto_publish horse hand clip job as one native video post (origin horse, rights owned, topic poker, topics poker and hand, thumbnail = poster) and records the post and the mirrored reel on the job. Returns the row unchanged when content_settings.engine_enabled or the hand_clip mode is off. Service role only.';


--
-- TOC entry 7081 (class 1255 OID 63160397)
-- Name: fn_park_stopped_time_bank_custody(uuid, uuid, uuid, bigint, text, jsonb, jsonb, text, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_park_stopped_time_bank_custody(p_table_id uuid, p_tournament_id uuid, p_generation uuid, p_hand_number bigint, p_parked_at text, p_disconnect_states jsonb, p_players jsonb, p_engine_instance text, p_unstarted_permit_id uuid DEFAULT NULL::uuid, p_unstarted_hand_number bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_parked_at timestamptz;
  v_existing public.engine_presence_parked;
  v_found boolean;
  v_hand jsonb;
  v_rows integer;
  v_attempt integer := 0;
  v_permit smarter_private.f06_hand_permits;
  v_released uuid := NULL;
  v_absent_lane boolean := false;
  v_absent smarter_private.f06_absent_permit_releases;
BEGIN
  /* The engine calls this at the process root, as the `service` actor. A
     manager's headers are exactly what the fence refuses once its lease is
     gone, and this record is not that manager's authority to exercise. */
  IF auth.role() IS DISTINCT FROM 'service_role'
     OR current_setting('app.smarter_data_actor', true) IS DISTINCT FROM 'service' THEN
    RAISE EXCEPTION 'STOPPED_CUSTODY_SERVICE_REQUIRED: stopped time-bank custody is written by the process, not by a manager'
      USING ERRCODE = '42501';
  END IF;
  IF p_table_id IS NULL OR p_tournament_id IS NULL
     OR p_hand_number IS NULL OR p_hand_number < 0
     OR jsonb_typeof(p_disconnect_states) IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_players) IS DISTINCT FROM 'object'
     OR COALESCE(btrim(p_engine_instance), '') = ''
     OR COALESCE(p_parked_at, '') = '' THEN
    RAISE EXCEPTION 'STOPPED_CUSTODY_INVALID: table, tournament, hand number, banks, presence, instance and time are all required'
      USING ERRCODE = '22023';
  END IF;
  /* The attestation is both halves or neither, and names a hand strictly
     above the custody: a permit at or below it is not "the next hand". */
  IF (p_unstarted_permit_id IS NULL) <> (p_unstarted_hand_number IS NULL)
     OR (p_unstarted_hand_number IS NOT NULL AND p_unstarted_hand_number <= p_hand_number) THEN
    RAISE EXCEPTION 'STOPPED_CUSTODY_INVALID: an unstarted permit is attested by id and by a hand number above the custody'
      USING ERRCODE = '22023';
  END IF;
  BEGIN
    v_parked_at := p_parked_at::timestamptz;
  EXCEPTION WHEN others THEN
    RAISE EXCEPTION 'STOPPED_CUSTODY_INVALID: parked_at is not a timestamp' USING ERRCODE = '22023';
  END;
  IF NOT isfinite(v_parked_at)
     OR abs(extract(epoch FROM (v_parked_at - clock_timestamp()))) > 900 THEN
    RAISE EXCEPTION 'STOPPED_CUSTODY_INVALID: parked_at is not now' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.tables t
                  WHERE t.id = p_table_id AND t.tournament_id = p_tournament_id) THEN
    RETURN jsonb_build_object('ok', false, 'refused', 'table_not_in_tournament',
                              'table_id', p_table_id);
  END IF;

  /* A PERMIT THAT NEVER REACHED THE DATABASE HOLDS NOTHING (2026-09-27).
     The engine attests the permit it holds in phase 'unknown' after its
     fn_f06_begin_hand call was lost (a timeout or a dropped reply): it
     cannot tell whether the begin committed. When no row carries that
     permit_id, the begin either never ran or is still running. Take the
     tournament's canonical lane - the one fn_f06_begin_hand holds through
     f06_prefix until it commits - BEFORE the retired-origin lock, so any
     begin still in flight has committed or aborted before this reads, and
     record the absence below under that lane so a begin that arrives later
     is refused (fn_f06_begin_hand reads f06_absent_permit_releases). */
  IF p_unstarted_permit_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM smarter_private.f06_hand_permits h
                      WHERE h.permit_id = p_unstarted_permit_id) THEN
    PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
    v_absent_lane := true;
  END IF;

  /* The transfer's prepare holds this lock while it reads this row into its
     CAS evidence. Never interleave with it; a busy lock is "not now". */
  /* A BUSY LOCK IS WAITED FOR, BRIEFLY (2026-09-26, 20260926145903).
     Every terminal engine of a tournament asks at the same :53 fan-out, and
     this lock is a try-lock, so siblings refused each other: 123
     custody_transfer_busy at 13:53Z. The engine asks again only at the next
     announcement, an hour later, and until then the table holds the restart
     certificate shut. The holder is one short transaction (this function, or
     the transfer's prepare), so ask again up to 40 times, 25 ms apart. The
     lock is still taken before anything is read or written, so the two never
     interleave; only the wait is new. */
  LOOP
    BEGIN
      PERFORM smarter_private.f06_retired_origin_lock(p_tournament_id);
      EXIT;
    EXCEPTION WHEN SQLSTATE '55P03' THEN
      v_attempt := v_attempt + 1;
      IF v_attempt >= 40 THEN
        RETURN jsonb_build_object('ok', false, 'refused', 'custody_transfer_busy',
                                  'table_id', p_table_id);
      END IF;
    END;
    PERFORM pg_sleep(0.025);
  END LOOP;

  SELECT * INTO v_existing
    FROM public.engine_presence_parked p
   WHERE p.table_id = p_table_id
     FOR UPDATE;
  v_found := FOUND;

  IF EXISTS (
    SELECT 1
      FROM smarter_private.f06_manager_custody_transfers x
     WHERE x.tournament_id = p_tournament_id
       AND x.local_proof -> 'engines'
             @> jsonb_build_array(jsonb_build_object('table_id', p_table_id::text))
       AND (x.origin_generation IS NOT DISTINCT FROM p_generation
            OR NOT EXISTS (SELECT 1 FROM smarter_private.f06_manager_custody_completions c
                            WHERE c.transfer_id = x.transfer_id))
  ) THEN
    RETURN jsonb_build_object('ok', false, 'refused', 'mixed_transfer_recorded',
                              'table_id', p_table_id);
  END IF;

  IF v_found THEN
    /* A SUPERSEDED MIXED ROW IS NOT THE SUCCESSOR'S CUSTODY (2026-09-28).
       An F06 mixed completion writes this row for the successor to adopt at
       the table's last hand; while nothing has been dealt after it, it is
       the only record of the moved banks and is never overwritten. Once
       hand_history holds a hand on this table above the row's hand number,
       and no higher than the custody being parked, an engine booted at the
       row's hand and dealt on: loadTimeBanksFromPark reads a snapshot only
       at the exact hand an engine boots at, so no process can ever read
       this row again, and the stopped custody is the only live record of
       those players' banks. Anything else - an unreadable hand number, a
       row at or above the custody, no dealt hand between them - still
       refuses. */
    IF v_existing.engine_instance = 'f06_mixed_custody' THEN
      v_hand := v_existing.time_bank_snapshot -> 'handNumber';
      IF jsonb_typeof(v_hand) IS DISTINCT FROM 'number'
         OR (v_hand::text)::numeric <> trunc((v_hand::text)::numeric)
         OR (v_hand::text)::numeric < 0
         OR (v_hand::text)::numeric >= p_hand_number THEN
        RETURN jsonb_build_object('ok', false, 'refused', 'mixed_custody_adopted',
                                  'table_id', p_table_id);
      END IF;
      IF NOT EXISTS (SELECT 1 FROM public.hand_history h
                      WHERE h.table_id = p_table_id
                        AND h.hand_number > (v_hand::text)::bigint
                        AND h.hand_number <= p_hand_number) THEN
        RETURN jsonb_build_object('ok', false, 'refused', 'mixed_custody_adopted',
                                  'table_id', p_table_id);
      END IF;
    END IF;
    IF v_existing.time_bank_snapshot IS NOT NULL
       AND v_existing.time_bank_snapshot <> 'null'::jsonb THEN
      v_hand := v_existing.time_bank_snapshot -> 'handNumber';
      IF jsonb_typeof(v_hand) IS DISTINCT FROM 'number'
         OR (v_hand::text)::numeric <> trunc((v_hand::text)::numeric) THEN
        RETURN jsonb_build_object('ok', false, 'refused', 'existing_park_unreadable',
                                  'table_id', p_table_id);
      END IF;
      IF (v_hand::text)::numeric > p_hand_number THEN
        RETURN jsonb_build_object('ok', false, 'refused', 'newer_park',
                                  'table_id', p_table_id,
                                  'existing_hand_number', v_hand);
      END IF;
    END IF;
  END IF;

  /* A NEVER-STARTED PERMIT DOES NOT HOLD THE BANK (2026-09-27). The engine
     that holds this custody attests the one permit it reserved above it and
     never started. Only the original process can say that (start is a local
     fence), and its own door is fenced with its lease; so it is recorded
     here, as the process, under the same refusals that door applies, and
     only for a generation that no longer holds the lease. A live manager is
     never second-guessed: it has fn_f06_cancel_prepared_hand. */
  IF p_unstarted_permit_id IS NOT NULL THEN
    SELECT * INTO v_permit
      FROM smarter_private.f06_hand_permits h
     WHERE h.permit_id = p_unstarted_permit_id
       FOR UPDATE;
    IF NOT FOUND THEN
      /* No row: the begin never committed. Only the attestation of the
         engine that holds the permit names it, and only when this call took
         the lane above (a row read before the lane may not be trusted). A
         replay of the recorded absence returns the same release. Every
         durable start witness for the attested hand number still refuses,
         and so does a permit of any other id at that number. */
      IF NOT v_absent_lane OR p_generation IS NULL THEN
        RETURN jsonb_build_object('ok', false, 'refused', 'unstarted_permit_not_this_engines',
                                  'table_id', p_table_id, 'permit_id', p_unstarted_permit_id);
      END IF;
      SELECT * INTO v_absent
        FROM smarter_private.f06_absent_permit_releases a
       WHERE a.permit_id = p_unstarted_permit_id;
      IF FOUND THEN
        IF (v_absent.table_id, v_absent.tournament_id, v_absent.generation, v_absent.hand_number)
           IS DISTINCT FROM (p_table_id, p_tournament_id, p_generation, p_unstarted_hand_number) THEN
          RETURN jsonb_build_object('ok', false, 'refused', 'unstarted_permit_not_this_engines',
                                    'table_id', p_table_id, 'permit_id', p_unstarted_permit_id);
        END IF;
      ELSE
        IF EXISTS (SELECT 1 FROM smarter_private.f06_hand_permits h
                    WHERE h.table_id = p_table_id AND h.hand_number = p_unstarted_hand_number)
           OR EXISTS (SELECT 1 FROM smarter_private.f06_hand_dispatch d WHERE d.permit_id = p_unstarted_permit_id)
           OR EXISTS (SELECT 1 FROM public.hand_atomic_commits h
                       WHERE h.table_id = p_table_id AND h.hand_number = p_unstarted_hand_number)
           OR EXISTS (SELECT 1 FROM public.hand_history h
                       WHERE h.table_id = p_table_id AND h.hand_number = p_unstarted_hand_number)
           OR EXISTS (SELECT 1 FROM public.hand_state_snapshots h
                       WHERE h.table_id = p_table_id AND h.hand_number = p_unstarted_hand_number)
           OR EXISTS (SELECT 1 FROM public.hand_private_state h
                       WHERE h.table_id = p_table_id AND h.hand_number = p_unstarted_hand_number)
           OR EXISTS (SELECT 1 FROM public.table_hole_cards h
                       WHERE h.table_id = p_table_id AND h.hand_number = p_unstarted_hand_number) THEN
          RETURN jsonb_build_object('ok', false, 'refused', 'hand_after_custody',
                                    'evidence', 'absent_permit_start_witness',
                                    'table_id', p_table_id, 'permit_id', p_unstarted_permit_id);
        END IF;
        INSERT INTO smarter_private.f06_absent_permit_releases
          (permit_id, tournament_id, generation, table_id, hand_number, custody_hand_number)
        VALUES
          (p_unstarted_permit_id, p_tournament_id, p_generation, p_table_id,
           p_unstarted_hand_number, p_hand_number);
      END IF;
      v_released := p_unstarted_permit_id;
    ELSIF v_permit.table_id IS DISTINCT FROM p_table_id
       OR v_permit.tournament_id IS DISTINCT FROM p_tournament_id
       OR v_permit.generation IS DISTINCT FROM p_generation
       OR v_permit.hand_number IS DISTINCT FROM p_unstarted_hand_number THEN
      RETURN jsonb_build_object('ok', false, 'refused', 'unstarted_permit_not_this_engines',
                                'table_id', p_table_id, 'permit_id', p_unstarted_permit_id);
    END IF;
    IF v_released IS NOT NULL THEN
      NULL; -- released above: the attested permit never reached the database
    ELSIF v_permit.state = 'never_started' THEN
      /* Already recorded (a receipt replayed, or the prepared cancellation
         landed after all): nothing to close, and nothing above the custody. */
      v_released := p_unstarted_permit_id;
    ELSE
      IF v_permit.state <> 'reserved' OR v_permit.evidence_id IS NOT NULL THEN
        RETURN jsonb_build_object('ok', false, 'refused', 'hand_after_custody',
                                  'evidence', 'f06_hand_permits',
                                  'permit_state', v_permit.state, 'table_id', p_table_id);
      END IF;
      IF EXISTS (SELECT 1 FROM public.engine_tournament_leases l
                  WHERE l.tournament_id = p_tournament_id
                    AND l.lease_generation = p_generation
                    AND l.heartbeat_at >= clock_timestamp()
                        - make_interval(secs => public.fn_engine_lease_stale_seconds())) THEN
        RETURN jsonb_build_object('ok', false, 'refused', 'unstarted_permit_generation_live',
                                  'table_id', p_table_id, 'permit_id', p_unstarted_permit_id);
      END IF;
      /* Durable witnesses only REFUSE a claimed no-start; their absence cannot
         grant it - the engine's attestation is the grant, exactly as in
         fn_f06_cancel_prepared_hand. */
      IF EXISTS (SELECT 1 FROM smarter_private.f06_hand_dispatch d WHERE d.permit_id = p_unstarted_permit_id)
         OR EXISTS (SELECT 1 FROM public.hand_atomic_commits h
                     WHERE h.table_id = p_table_id AND h.hand_number = p_unstarted_hand_number)
         OR EXISTS (SELECT 1 FROM public.hand_history h
                     WHERE h.table_id = p_table_id AND h.hand_number = p_unstarted_hand_number)
         OR EXISTS (SELECT 1 FROM public.hand_state_snapshots h
                     WHERE h.table_id = p_table_id AND NOT h.is_complete
                       AND h.hand_number = p_unstarted_hand_number)
         OR EXISTS (SELECT 1 FROM public.hand_private_state h
                     WHERE h.table_id = p_table_id AND h.hand_number = p_unstarted_hand_number)
         OR EXISTS (SELECT 1 FROM public.table_hole_cards h
                     WHERE h.table_id = p_table_id AND h.hand_number = p_unstarted_hand_number) THEN
        RETURN jsonb_build_object('ok', false, 'refused', 'hand_after_custody',
                                  'evidence', 'unstarted_permit_start_witness',
                                  'table_id', p_table_id, 'permit_id', p_unstarted_permit_id);
      END IF;
      INSERT INTO smarter_private.f06_prepared_hand_cancellations
        (permit_id, tournament_id, generation, table_id, lifecycle, hand_number, custody_id)
      VALUES
        (v_permit.permit_id, v_permit.tournament_id, v_permit.generation, v_permit.table_id,
         v_permit.lifecycle, v_permit.hand_number, v_permit.custody_id);
      UPDATE smarter_private.f06_hand_permits
         SET state = 'never_started', evidence_id = p_unstarted_permit_id
       WHERE permit_id = p_unstarted_permit_id AND state = 'reserved' AND evidence_id IS NULL;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows <> 1 THEN
        RAISE EXCEPTION 'STOPPED_CUSTODY_PERMIT_RACE: the reserved permit changed under its lock'
          USING ERRCODE = '55000';
      END IF;
      v_released := p_unstarted_permit_id;
    END IF;
  END IF;

  IF EXISTS (SELECT 1 FROM public.hand_history h
              WHERE h.table_id = p_table_id AND h.hand_number > p_hand_number) THEN
    RETURN jsonb_build_object('ok', false, 'refused', 'hand_after_custody',
                              'evidence', 'hand_history', 'table_id', p_table_id);
  END IF;
  IF EXISTS (SELECT 1 FROM public.hand_atomic_commits h
              WHERE h.table_id = p_table_id AND h.hand_number > p_hand_number) THEN
    RETURN jsonb_build_object('ok', false, 'refused', 'hand_after_custody',
                              'evidence', 'hand_atomic_commits', 'table_id', p_table_id);
  END IF;
  IF EXISTS (SELECT 1 FROM public.hand_state_snapshots h
              WHERE h.table_id = p_table_id AND h.hand_number > p_hand_number) THEN
    RETURN jsonb_build_object('ok', false, 'refused', 'hand_after_custody',
                              'evidence', 'hand_state_snapshots', 'table_id', p_table_id);
  END IF;
  /* A STOPPED ENGINE'S OWN RESERVED HAND IS NOT A HAND AFTER ITS CUSTODY
     (2026-09-27, 20260927142925, #5409). A reserved permit of the caller's
     own generation is not evidence of a later hand; a reserved permit of
     ANOTHER generation, and every accepted or aborted_unsettled permit,
     still refuses. Unchanged here. The attestation above goes one step
     further for the one permit the engine names: it is closed
     never_started with a receipt, so the successor never meets it as
     hand_permit_unresolved and this engine's preparation is resolved. */
  IF EXISTS (SELECT 1 FROM smarter_private.f06_hand_permits h
              WHERE h.table_id = p_table_id AND h.hand_number > p_hand_number
                AND h.state <> 'never_started'
                AND NOT (h.state = 'reserved'
                         AND p_generation IS NOT NULL
                         AND h.generation = p_generation)) THEN
    RETURN jsonb_build_object('ok', false, 'refused', 'hand_after_custody',
                              'evidence', 'f06_hand_permits', 'table_id', p_table_id);
  END IF;

  IF v_found THEN
    UPDATE public.engine_presence_parked
       SET disconnect_states = p_disconnect_states,
           parked_at = v_parked_at,
           engine_instance = p_engine_instance,
           time_bank_snapshot = jsonb_build_object(
             'version', 1, 'parkedAt', p_parked_at,
             'handNumber', p_hand_number, 'players', p_players)
     WHERE table_id = p_table_id;
  ELSE
    INSERT INTO public.engine_presence_parked
      (table_id, disconnect_states, parked_at, engine_instance, time_bank_snapshot)
    VALUES
      (p_table_id, p_disconnect_states, v_parked_at, p_engine_instance,
       jsonb_build_object('version', 1, 'parkedAt', p_parked_at,
                          'handNumber', p_hand_number, 'players', p_players))
    ON CONFLICT (table_id) DO NOTHING;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RETURN jsonb_build_object('ok', false, 'refused', 'concurrent_park',
                                'table_id', p_table_id);
    END IF;
  END IF;

  RETURN jsonb_build_object('ok', true, 'table_id', p_table_id,
                            'hand_number', p_hand_number, 'parked_at', p_parked_at,
                            'unstarted_permit_released', v_released);
END
$$;


ALTER FUNCTION public.fn_park_stopped_time_bank_custody(p_table_id uuid, p_tournament_id uuid, p_generation uuid, p_hand_number bigint, p_parked_at text, p_disconnect_states jsonb, p_players jsonb, p_engine_instance text, p_unstarted_permit_id uuid, p_unstarted_hand_number bigint) OWNER TO postgres;

--
