--
-- TOC entry 5554 (class 1255 OID 14488579)
-- Name: fn_pay_player_chips(uuid, numeric, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_pay_player_chips(p_user_id uuid, p_amount numeric, p_category text, p_description text, p_club_hint uuid DEFAULT NULL::uuid, p_related_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_club uuid; v_balance numeric; v_had_cp text; v_cat text;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('paid', false, 'reason', 'non_positive');
  END IF;

  v_club := public.fn_player_home_club(p_user_id, p_club_hint);

  IF v_club IS NULL THEN
    -- CLUB ARENA RULE: there is no shared wallet to fall back to.
    RAISE EXCEPTION 'no club wallet resolves for player % - Club Arena money cannot be paid to a global wallet', p_user_id
      USING HINT = 'Pass an explicit club, or ensure the player holds a club membership.';
  END IF;

  -- A club a player belongs to always has its own wallet; create if absent
  -- rather than redirecting the money anywhere else.
  PERFORM public.fn_ensure_club_wallet(p_user_id, v_club);

  /* THE BANK IS NAMED (2026-09-09). A player paid from their club is paid
     out of that club's treasury, and this function has already resolved which
     club. Declaring it here is what stops the journal recording the payment
     as an anonymous arrival out of settlement_suspense. p_category is a
     wallet_transactions category and is only used when the ledger vocabulary
     also has it; otherwise the leg is an adjustment, which is what it was
     before. */
  v_had_cp := COALESCE(NULLIF(current_setting('app.ledger_counterparty', true), ''), '');
  IF v_had_cp = '' THEN
    SELECT CASE WHEN EXISTS (
             SELECT 1 FROM pg_constraint
              WHERE conrelid = 'public.chip_ledger'::regclass
                AND conname = 'chip_ledger_category_check'
                AND pg_get_constraintdef(oid) LIKE '%''' || lower(btrim(COALESCE(p_category,''))) || '''%')
           THEN lower(btrim(p_category)) ELSE 'adjustment' END
      INTO v_cat;
    PERFORM public.fn_ca_declare_ledger(v_cat, 'club_treasury', v_club);
  END IF;

  UPDATE club_members
     SET chip_balance = COALESCE(chip_balance,0) + p_amount, updated_at = NOW()
   WHERE user_id = p_user_id AND club_id = v_club
   RETURNING chip_balance INTO v_balance;

  IF v_had_cp = '' THEN
    -- Cleared so a declaration made for THIS credit cannot label a later one.
    PERFORM set_config('app.ledger_counterparty', '', true);
    PERFORM set_config('app.ledger_counterparty_entity', '', true);
    PERFORM set_config('app.ledger_category', '', true);
  END IF;

  IF v_balance IS NULL THEN
    RAISE EXCEPTION 'club wallet for player % in club % could not be credited', p_user_id, v_club;
  END IF;

  INSERT INTO wallet_transactions
    (user_id, wallet_type, type, amount, category, description, related_entity_id, balance_after)
  VALUES
    (p_user_id, 'PLAYER', 'credit', p_amount, p_category,
     p_description || ' [club wallet]', p_related_id, v_balance);

  RETURN jsonb_build_object('paid', true, 'club_id', v_club,
                            'source', 'club_chips', 'balance_after', v_balance);
END $$;


ALTER FUNCTION public.fn_pay_player_chips(p_user_id uuid, p_amount numeric, p_category text, p_description text, p_club_hint uuid, p_related_id uuid) OWNER TO postgres;

--
-- TOC entry 5630 (class 1255 OID 18548247)
-- Name: fn_payout_guarantee_check(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_payout_guarantee_check(p_since_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_days     integer := LEAST(GREATEST(COALESCE(p_since_days, 7), 1), 400);
  v_since    timestamptz;
  v_vacant   integer := 0;
  v_vac_chips numeric := 0;
  v_short    integer := 0;
  v_short_chips numeric := 0;
  v_gap      integer := 0;
  v_gap_chips numeric := 0;
  v_bounty   integer := 0;
  v_bounty_chips numeric := 0;
  v_alerts   integer := 0;
  v_cleared  integer := 0;
  v_labelled integer := 0;
  v_row      record;
BEGIN
  v_since := now() - make_interval(days => v_days);

  /* ── CLEAR WHAT IS NO LONGER TRUE (2026-09-07) ─────────────────────────────
     This check could raise an earner_not_paid alert and never close one. Two
     of the six open on 2026-09-07 had been paid IN FULL at 04:10, hours after
     the alert, and the row still read critical. An alarm that cannot clear is
     an alarm that gets skimmed, and the one real case in that list - a player
     4.80 short - had been sitting in it for a day.
     An alert clears when either half of its claim stops holding: the player
     has since been credited to within five cents of the place, or the event's
     prize pool has left the escrow to the last chip, in which case there is
     nothing left to pay them with and this is not the alert for it. */
  WITH open_alerts AS (
    SELECT fa.id,
           (fa.context->>'tournament_id')::uuid AS tid,
           (fa.context->>'user_id')::uuid       AS uid,
           (fa.context->>'place_worth')::numeric AS place_worth
      FROM public.financial_alerts fa
     WHERE fa.source = 'fn_payout_guarantee_check'
       AND fa.resolved IS NOT TRUE
       AND fa.context->>'kind' = 'earner_not_paid'
       AND fa.context ? 'tournament_id'
       AND fa.context ? 'user_id'
  ), judged AS (
    SELECT a.id,
           COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
                      WHERE w.related_entity_id = a.tid AND w.user_id = a.uid
                        AND w.type = 'credit' AND w.category IN ('prize','bounty')), 0)
           -- A DIAMOND PLACE IS PAID FROM THE DIAMOND BOOK (2026-10-09). A
           -- platform Diamond event never writes wallet_transactions: its
           -- prizes and bounties are poker_diamond_tournament_ledger legs. All
           -- 97 open earner_not_paid alerts on 2026-10-09 were Diamond places
           -- paid in full (72) or a whole-Diamond rounding of a pool paid out
           -- to the last Diamond (25).
           + COALESCE((SELECT sum(l.amount) FROM public.poker_diamond_tournament_ledger l
                        WHERE l.tournament_id = a.tid AND l.user_id = a.uid
                          AND l.kind IN ('prize','bounty')), 0) AS credited,
           a.place_worth,
           COALESCE(t.prize_pool, 0) AS pool,
           COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
                      WHERE w.related_entity_id = a.tid
                        AND w.type = 'credit' AND w.category = 'prize'), 0)
           + COALESCE((SELECT sum(l.amount) FROM public.poker_diamond_tournament_ledger l
                        WHERE l.tournament_id = a.tid AND l.kind = 'prize'), 0) AS pool_paid
      FROM open_alerts a
      LEFT JOIN public.tournaments t ON t.id = a.tid
  )
  UPDATE public.financial_alerts fa
     SET resolved = true,
         resolved_at = now(),
         resolution = CASE
           WHEN j.credited + 0.05 >= j.place_worth
             THEN format('Cleared by fn_payout_guarantee_check: the player has since been credited %s against a place worth %s.',
                         round(j.credited, 2), round(j.place_worth, 2))
           ELSE format('Cleared by fn_payout_guarantee_check: the event''s prize pool of %s has been distributed in full (%s paid), so there is nothing left to pay this place with. A place that received less than the flat structure share of a fully distributed pool is a labelling, deal or obligation question, not an unpaid player.',
                         round(j.pool, 2), round(j.pool_paid, 2))
         END
    FROM judged j
   WHERE fa.id = j.id
     AND (j.credited + 0.05 >= j.place_worth
          OR (j.pool > 0 AND j.pool_paid + 0.01 >= j.pool));
  GET DIAGNOSTICS v_cleared = ROW_COUNT;

  FOR v_row IN
    WITH ev AS (
      SELECT t.id, t.name, t.club_id, t.tournament_type, t.ended_at,
             COALESCE(t.prize_pool, 0) AS pool,
             (SELECT count(*) FROM public.tournament_players tp
               WHERE tp.tournament_id = t.id) AS entrants,
             t.payout_structure
        FROM public.tournaments t
       WHERE t.status = 'COMPLETED'
         AND t.ended_at >= v_since
         AND COALESCE(t.prize_pool, 0) > 0
         AND COALESCE(t.satellite_seats, 0) = 0
         AND COALESCE(t.variant, '') <> 'satellite'
    ), places AS (
      SELECT ev.*, (elem->>'place')::int AS place, (elem->>'percentage')::numeric AS pct
        FROM ev
        CROSS JOIN LATERAL jsonb_array_elements(
          CASE WHEN jsonb_typeof(ev.payout_structure::jsonb) = 'array'
               THEN ev.payout_structure::jsonb ELSE '[]'::jsonb END) elem
    )
    SELECT p.id, p.name, p.club_id, p.tournament_type, p.ended_at, p.pool, p.entrants,
           array_agg(p.place ORDER BY p.place) AS vacant_places,
           round(sum(p.pool * p.pct / 100), 2) AS chips
      FROM places p
     WHERE p.place <= p.entrants
       AND NOT EXISTS (SELECT 1 FROM public.tournament_players tp
                        WHERE tp.tournament_id = p.id AND tp.position = p.place)
     GROUP BY p.id, p.name, p.club_id, p.tournament_type, p.ended_at, p.pool, p.entrants
  LOOP
    v_vacant := v_vacant + 1;
    v_vac_chips := v_vac_chips + COALESCE(v_row.chips, 0);
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT 'critical', 'fn_payout_guarantee_check',
           format('%s ranked a %s-player field but left paid place(s) %s with nobody in them, so %s chips were paid to no one',
                  COALESCE(v_row.name, v_row.id::text), v_row.entrants,
                  array_to_string(v_row.vacant_places, ', '), v_row.chips),
           jsonb_build_object('kind','vacant_paid_place','tournament_id',v_row.id,
             'club_id',v_row.club_id,'tournament_type',v_row.tournament_type,
             'entrants',v_row.entrants,'prize_pool',v_row.pool,
             'vacant_places',to_jsonb(v_row.vacant_places),'chips',v_row.chips,
             'ended_at',v_row.ended_at,
             'detail','whoever finished in those places was mislabelled; no money was moved by this check')
     WHERE NOT EXISTS (SELECT 1 FROM public.financial_alerts fa
                        WHERE fa.source = 'fn_payout_guarantee_check'
                          AND fa.resolved IS NOT TRUE
                          AND fa.context->>'kind' = 'vacant_paid_place'
                          AND fa.context->>'tournament_id' = v_row.id::text);
    IF FOUND THEN v_alerts := v_alerts + 1; END IF;
  END LOOP;

  FOR v_row IN
    WITH ev AS (
      SELECT t.id, t.name, t.club_id, t.tournament_type, t.ended_at,
             COALESCE(t.prize_pool, 0) AS pool, t.payout_structure,
             /* WHAT LEFT THE ESCROW. The discriminator between "a player is
                short and the money is still here" and "the pool is gone and
                this place got less than the flat share". Only the first is an
                unpaid player. */
             COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
                        WHERE w.related_entity_id = t.id
                          AND w.type = 'credit' AND w.category = 'prize'), 0)
             -- A DIAMOND PLACE IS PAID FROM THE DIAMOND BOOK (2026-10-09).
             + COALESCE((SELECT sum(l.amount) FROM public.poker_diamond_tournament_ledger l
                          WHERE l.tournament_id = t.id AND l.kind = 'prize'), 0) AS pool_paid
        FROM public.tournaments t
       WHERE t.status = 'COMPLETED'
         AND t.ended_at >= v_since
         AND COALESCE(t.prize_pool, 0) > 0
         AND COALESCE(t.satellite_seats, 0) = 0
         AND COALESCE(t.variant, '') <> 'satellite'
    ), owed AS (
      SELECT ev.id, ev.name, ev.club_id, ev.tournament_type, ev.ended_at,
             ev.pool, ev.pool_paid,
             tp.user_id, tp.position,
             round(ev.pool * (elem->>'percentage')::numeric / 100, 2) AS place_worth
        FROM ev
        CROSS JOIN LATERAL jsonb_array_elements(
          CASE WHEN jsonb_typeof(ev.payout_structure::jsonb) = 'array'
               THEN ev.payout_structure::jsonb ELSE '[]'::jsonb END) elem
        JOIN public.tournament_players tp
          ON tp.tournament_id = ev.id AND tp.position = (elem->>'place')::int
    )
    SELECT o.*,
           COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
                      WHERE w.related_entity_id = o.id AND w.user_id = o.user_id
                        AND w.type = 'credit'
                        AND w.category IN ('prize','bounty')), 0)
           + COALESCE((SELECT sum(l.amount) FROM public.poker_diamond_tournament_ledger l
                        WHERE l.tournament_id = o.id AND l.user_id = o.user_id
                          AND l.kind IN ('prize','bounty')), 0) AS credited,
           (o.pool_paid + 0.01 >= o.pool) AS pool_distributed
      FROM owed o
     /* FIVE CENTS, NOT ONE (2026-09-01). place_worth here is the flat
        pool * percentage. The engine allocates in whole cents and gives the
        last paid place the remainder, so a place can legitimately land a cent
        or two either side of the flat figure. */
     WHERE COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
                      WHERE w.related_entity_id = o.id AND w.user_id = o.user_id
                        AND w.type = 'credit'
                        AND w.category IN ('prize','bounty')), 0)
          + COALESCE((SELECT sum(l.amount) FROM public.poker_diamond_tournament_ledger l
                       WHERE l.tournament_id = o.id AND l.user_id = o.user_id
                         AND l.kind IN ('prize','bounty')), 0) + 0.05 < o.place_worth
  LOOP
    /* THE POOL TEST (2026-09-07). Five of the six alerts open when this was
       written named events whose pool had already left the escrow to the last
       chip - two paid in full hours after the alert, one settled by a
       final_table_deal that replaced the structure, two off by 0.07 and 0.06
       on pools of 14,850 and 1,350. Counted, not alarmed: nothing can be paid
       out of a pool that is gone, and the reconciler reading this as an unpaid
       player tried to top one of them up by 23.75 - a real double payment,
       stopped only by the empty escrow it would have come from. */
    IF v_row.pool_distributed THEN
      v_labelled := v_labelled + 1;
      CONTINUE;
    END IF;

    v_short := v_short + 1;
    v_short_chips := v_short_chips + (v_row.place_worth - v_row.credited);
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT 'critical', 'fn_payout_guarantee_check',
           format('%s: the player who finished %s is owed %s and their wallet received %s',
                  COALESCE(v_row.name, v_row.id::text), v_row.position,
                  v_row.place_worth, v_row.credited),
           jsonb_build_object('kind','earner_not_paid','tournament_id',v_row.id,
             'club_id',v_row.club_id,'tournament_type',v_row.tournament_type,
             'user_id',v_row.user_id,'position',v_row.position,
             'place_worth',v_row.place_worth,'credited',v_row.credited,
             'short',round(v_row.place_worth - v_row.credited, 2),
             'prize_pool',v_row.pool,'pool_paid',v_row.pool_paid,
             'ended_at',v_row.ended_at,
             'detail','the prize pool has NOT been fully distributed, so these chips are still in the escrow and this player can be paid. No money was moved by this check')
     WHERE NOT EXISTS (SELECT 1 FROM public.financial_alerts fa
                        WHERE fa.source = 'fn_payout_guarantee_check'
                          AND fa.resolved IS NOT TRUE
                          AND fa.context->>'kind' = 'earner_not_paid'
                          AND fa.context->>'tournament_id' = v_row.id::text
                          AND fa.context->>'user_id' = v_row.user_id::text);
    IF FOUND THEN v_alerts := v_alerts + 1; END IF;
  END LOOP;

  /* THE OTHER POOL (2026-09-01). Everything above reconciles the PRIZE pool,
     and a bounty event funds a SECOND pool out of the same buy-in. */
  FOR v_row IN
    SELECT t.id, t.name, t.club_id, t.ended_at,
           round(COALESCE(t.bounty_pool, 0), 2) AS pool,
           COALESCE((SELECT round(sum(w.amount), 2) FROM public.wallet_transactions w
                      WHERE w.related_entity_id = t.id AND w.type = 'credit'
                        AND w.category = 'bounty'), 0)
           -- DIAMOND PHASE 9: a Diamond bounty is a ledger row, not a wallet row.
           + COALESCE((SELECT sum(l.amount) FROM public.poker_diamond_tournament_ledger l
                        WHERE l.tournament_id = t.id AND l.kind = 'bounty'), 0) AS paid
      FROM public.tournaments t
     WHERE t.status = 'COMPLETED'
       AND t.ended_at >= v_since
       AND COALESCE(t.bounty_pool, 0) > 0
  LOOP
    CONTINUE WHEN v_row.paid + 0.01 >= v_row.pool;
    v_bounty := v_bounty + 1;
    v_bounty_chips := v_bounty_chips + (v_row.pool - v_row.paid);
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT 'critical', 'fn_payout_guarantee_check',
           format('%s funded a %s bounty pool and paid out %s, so %s chips of it reached no player',
                  COALESCE(v_row.name, v_row.id::text), v_row.pool, v_row.paid,
                  round(v_row.pool - v_row.paid, 2)),
           jsonb_build_object('kind','bounty_pool_retained','tournament_id',v_row.id,
             'club_id',v_row.club_id,'bounty_pool',v_row.pool,'paid',v_row.paid,
             'retained',round(v_row.pool - v_row.paid, 2),'ended_at',v_row.ended_at,
             'detail','the residual settles to the champion; fn_backpay_unfinalised_bounty_pools re-drives it. No money was moved by this check')
     WHERE NOT EXISTS (SELECT 1 FROM public.financial_alerts fa
                        WHERE fa.source = 'fn_payout_guarantee_check'
                          AND fa.resolved IS NOT TRUE
                          AND fa.context->>'kind' = 'bounty_pool_retained'
                          AND fa.context->>'tournament_id' = v_row.id::text);
    IF FOUND THEN v_alerts := v_alerts + 1; END IF;
  END LOOP;

  SELECT count(*), COALESCE(round(sum(gap), 2), 0) INTO v_gap, v_gap_chips
    FROM (
      SELECT t.id,
             COALESCE((SELECT sum(w.amount) FROM public.wallet_transactions w
                        WHERE w.related_entity_id = t.id AND w.type='credit'
                          AND w.category='prize'), 0)
           - COALESCE((SELECT sum(p.amount) FROM public.tournament_payouts p
                        WHERE p.tournament_id = t.id
                          AND p.source NOT IN ('bounty','own_bounty','mystery_bounty_residual')), 0)
             AS gap
        FROM public.tournaments t
       WHERE t.status='COMPLETED' AND t.ended_at >= v_since
         AND COALESCE(t.prize_pool,0) > 0
    ) g
   WHERE g.gap > 0.01;

  IF v_gap > 0 THEN
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT 'warning', 'fn_payout_guarantee_check',
           format('%s event(s) in the last %s days paid %s chips of prizes that were never written to tournament_payouts; the reconciler reads that record and will treat those chips as still owed',
                  v_gap, v_days, v_gap_chips),
           jsonb_build_object('kind','paid_but_unrecorded','events',v_gap,
             'chips',v_gap_chips,'since_days',v_days,
             'detail','no player is short; this is what arms a double-pay if the pool is ever funded')
     WHERE NOT EXISTS (SELECT 1 FROM public.financial_alerts fa
                        WHERE fa.source='fn_payout_guarantee_check'
                          AND fa.resolved IS NOT TRUE
                          AND fa.context->>'kind' = 'paid_but_unrecorded'
                          AND fa.created_at > now() - interval '20 hours');
    IF FOUND THEN v_alerts := v_alerts + 1; END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'since_days', v_days,
    'vacant_paid_place_events', v_vacant,
    'vacant_paid_place_chips', round(v_vac_chips, 2),
    'earners_not_paid', v_short,
    'earners_not_paid_chips', round(v_short_chips, 2),
    -- Counted, never alarmed: a place that received less than the flat
    -- structure share of a pool that is already fully distributed. Measured
    -- 2026-09-07 over 76,760 paid places on fully distributed events: median
    -- difference 0.0000, 1,056 over 0.05, 1,051 of those over 1.00.
    'short_of_structure_but_pool_distributed', v_labelled,
    'alerts_cleared', v_cleared,
    'bounty_pool_retained_events', v_bounty,
    'bounty_pool_retained_chips', round(v_bounty_chips, 2),
    'paid_but_unrecorded_events', v_gap,
    'paid_but_unrecorded_chips', v_gap_chips,
    'alerts_raised', v_alerts);
END;
$$;


ALTER FUNCTION public.fn_payout_guarantee_check(p_since_days integer) OWNER TO postgres;

--
-- TOC entry 48237 (class 0 OID 0)
-- Dependencies: 5630
-- Name: FUNCTION fn_payout_guarantee_check(p_since_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_payout_guarantee_check(p_since_days integer) IS 'Raises a critical alert only when a place is short AND the event''s prize pool has not been fully distributed - money still in the escrow and a player who can be paid from it. A place short of the flat structure share of a pool that is already gone (a final_table_deal, a relabelled place, a cent of rounding) is counted, not alarmed. Every run also RESOLVES open earner_not_paid alerts whose condition no longer holds; before 2026-09-07 it could raise one and never close one, and five of the six open were false.';


--
-- TOC entry 6266 (class 1255 OID 14850014)
-- Name: fn_payout_leaderboard(uuid, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_payout_leaderboard(p_club_id uuid, p_period text, p_metric text, p_start_date timestamp with time zone, p_end_date timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_start date := (p_start_date AT TIME ZONE 'UTC')::date;
  v_end date := (p_end_date AT TIME ZONE 'UTC')::date;
  v_plan jsonb;
  v_basis jsonb;
  v_board jsonb;
  v_existing public.leaderboard_payout_batches%ROWTYPE;
  v_winners jsonb := '[]'::jsonb;
  v_winner jsonb;
  v_total numeric(18,2) := 0;
  v_promo_available numeric(18,2) := 0;
  v_promo_debit numeric(18,2) := 0;
  v_union_id uuid;
  v_batch_id uuid;
  v_credited boolean;
BEGIN
  IF p_period NOT IN ('weekly', 'monthly') THEN
    RAISE EXCEPTION 'LEADERBOARD_PROGRAM_INVALID|Only Weekly And Monthly Leaderboards Can Be Settled';
  END IF;
  IF v_start IS NULL OR v_end IS NULL OR v_end <= v_start THEN
    RAISE EXCEPTION 'LEADERBOARD_PROGRAM_INVALID|Leaderboard Settlement Requires A Closed Date Range';
  END IF;
  IF v_end > (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')::date THEN
    RAISE EXCEPTION 'LEADERBOARD_PROGRAM_INVALID|An Open Leaderboard Round Cannot Be Paid';
  END IF;
  IF (p_period = 'weekly' AND (EXTRACT(DOW FROM v_start) <> 0 OR v_end <> v_start + 7))
     OR (p_period = 'monthly' AND (
       EXTRACT(DAY FROM v_start) <> 1
       OR v_end <> (v_start + interval '1 month')::date
     )) THEN
    RAISE EXCEPTION 'LEADERBOARD_PROGRAM_INVALID|Leaderboard Settlement Must Use A Canonical UTC Round';
  END IF;

  -- Serialize the exact historical round identity BEFORE replay lookup.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    format('leaderboard-round:%s:%s:%s', p_club_id, p_period, v_start), 0));

  SELECT batch.* INTO v_existing
  FROM public.leaderboard_payout_batches batch
  WHERE batch.club_id = p_club_id
    AND batch.period = p_period
    AND batch.period_start = v_start;
  IF v_existing.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_settled', true,
      'batch_id', v_existing.id,
      'total_paid', v_existing.total_paid,
      'seed_funded', v_existing.seed_funded,
      'promo_funded', v_existing.promo_funded,
      'overlay_funded', v_existing.overlay_funded,
      'winner_count', v_existing.winner_count,
      'tie_policy', v_existing.tie_policy
    );
  END IF;

  v_plan := public.fn_get_leaderboard_reward_plan(p_club_id, p_period, v_start);
  IF v_plan IS NULL OR NOT COALESCE((v_plan ->> 'rewards_enabled')::boolean, false) THEN
    RAISE EXCEPTION 'LEADERBOARD_PROGRAM_INVALID|No Paid Leaderboard Program Applies To This Round';
  END IF;
  IF p_metric IS DISTINCT FROM v_plan ->> 'payout_metric' THEN
    RAISE EXCEPTION 'LEADERBOARD_PROGRAM_INVALID|Leaderboard Metric Does Not Match The Published Program';
  END IF;

  v_basis := public.fn_leaderboard_complete_round_basis(p_club_id, p_period, v_start, v_end);
  IF NOT (v_basis ->> 'basis_version' = 'legacy_v1'
    OR (v_basis ->> 'basis_version' = 'complete_capture_v2'
      AND v_basis -> 'complete' = 'true'::jsonb)) THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='LEADERBOARD_COMPLETE_BASIS_REQUIRED';
  END IF;
  -- The public club board and settlement use ONE maintained ranking owner.
  -- That owner selects the same complete basis for closed canonical V2 rounds;
  -- existing promised legacy rounds retain their unchanged selection.
  SELECT COALESCE(jsonb_agg(to_jsonb(ranked) ORDER BY ranked.rank, ranked.user_id), '[]'::jsonb)
    INTO v_board
  FROM public.fn_club_leaderboard_by_dates(p_club_id, p_metric, v_start, v_end, 1000000, 0) ranked;

  WITH board AS MATERIALIZED (
    SELECT ranked.user_id, ranked.rank
    FROM jsonb_to_recordset(v_board) AS ranked(user_id uuid, rank integer, qualified boolean)
    WHERE ranked.qualified
  ), tied AS MATERIALIZED (
    SELECT
      board.user_id,
      board.rank,
      count(*) OVER (PARTITION BY board.rank)::integer AS tie_count,
      row_number() OVER (PARTITION BY board.rank ORDER BY board.user_id)::integer AS tie_order
    FROM board
  ), prizes AS MATERIALIZED (
    SELECT prize.rank, round(prize.amount, 2) AS amount
    FROM jsonb_to_recordset(COALESCE(v_plan -> 'prizes', '[]'::jsonb))
      AS prize(rank integer, amount numeric)
    WHERE prize.amount > 0
  ), pooled AS MATERIALIZED (
    SELECT
      tied.user_id,
      tied.rank,
      tied.tie_count,
      tied.tie_order,
      COALESCE(sum(prizes.amount), 0)::numeric(18,2) AS pool_amount
    FROM tied
    LEFT JOIN prizes
      ON prizes.rank >= tied.rank
     AND prizes.rank < tied.rank + tied.tie_count
    GROUP BY tied.user_id, tied.rank, tied.tie_count, tied.tie_order
  ), winners AS (
    SELECT
      pooled.user_id,
      pooled.rank,
      (
        trunc(pooled.pool_amount / pooled.tie_count, 2)
        + CASE
            WHEN pooled.tie_order <= mod((pooled.pool_amount * 100)::bigint, pooled.tie_count)
              THEN 0.01
            ELSE 0
          END
      )::numeric(18,2) AS amount
    FROM pooled
    WHERE pooled.pool_amount > 0
  )
  SELECT
    COALESCE(jsonb_agg(jsonb_build_object(
      'user_id', winners.user_id,
      'rank', winners.rank,
      'amount', winners.amount
    ) ORDER BY winners.rank, winners.user_id), '[]'::jsonb),
    COALESCE(round(sum(winners.amount), 2), 0)
  INTO v_winners, v_total
  FROM winners
  WHERE winners.amount > 0;

  -- Freeze the exact resolved program, selected inputs and awards before funds.
  -- A failed settlement rolls this receipt back; no historical row is rewritten.
  INSERT INTO public.leaderboard_round_basis_receipts (
    club_id, period, period_start, period_end, metric,
    program_id, program_version, program_hash, basis_version,
    basis, basis_hash, selected_board, selected_board_hash, winners, winners_hash
  ) VALUES (
    p_club_id, p_period, v_start, v_end, p_metric,
    (v_plan ->> 'program_id')::uuid, (v_plan ->> 'program_version')::integer,
    v_plan ->> 'program_hash', v_basis ->> 'basis_version',
    v_basis, md5(v_basis::text), v_board, md5(v_board::text), v_winners, md5(v_winners::text)
  );

  IF v_plan ->> 'funding_owner_type' = 'union' THEN
    v_union_id := (v_plan ->> 'funding_union_id')::uuid;
    SELECT COALESCE(wallet.promo_wallet, 0) INTO v_promo_available
    FROM public.union_wallets wallet WHERE wallet.union_id = v_union_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'LEADERBOARD_PROMO_WALLET_MISSING|Leaderboard Funding Union Has No Promo Wallet';
    END IF;
  ELSE
    SELECT COALESCE(club.promo_balance, 0) INTO v_promo_available
    FROM public.clubs club WHERE club.id = p_club_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'LEADERBOARD_PROMO_WALLET_MISSING|Leaderboard Club Not Found';
    END IF;
  END IF;
  IF v_promo_available < v_total THEN
    RAISE EXCEPTION
      'LEADERBOARD_PROMO_UNDERFUNDED|Leaderboard Requires % Promo Chips But The Recorded Promo Wallet Holds %',
      v_total, v_promo_available;
  END IF;
  v_promo_debit := v_total;

  PERFORM set_config('app.ledger_category', 'leaderboard_payout', true);
  PERFORM set_config('app.ledger_counterparty', 'leaderboard_round', true);
  PERFORM set_config('app.ledger_counterparty_entity', p_club_id::text, true);

  IF v_plan ->> 'funding_owner_type' = 'union' THEN
    UPDATE public.union_wallets
    SET promo_wallet = promo_wallet - v_promo_debit,
        updated_at = now()
    WHERE union_id = v_union_id;
  ELSE
    UPDATE public.clubs
    SET promo_balance = promo_balance - v_promo_debit,
        updated_at = now()
    WHERE id = p_club_id;
  END IF;

  INSERT INTO public.leaderboard_payout_batches (
    club_id, period, period_start, period_end, metric,
    program_id, program_version, program_hash,
    funding_owner_type, funding_union_id,
    total_paid, seed_funded, promo_funded, overlay_funded, winner_count, tie_policy
  ) VALUES (
    p_club_id, p_period, v_start, v_end, p_metric,
    (v_plan ->> 'program_id')::uuid,
    (v_plan ->> 'program_version')::integer,
    v_plan ->> 'program_hash',
    v_plan ->> 'funding_owner_type', v_union_id,
    v_total, 0, v_promo_debit, 0, jsonb_array_length(v_winners),
    'split_occupied_places'
  ) RETURNING id INTO v_batch_id;

  FOR v_winner IN SELECT value FROM jsonb_array_elements(v_winners)
  LOOP
    v_credited := public.fn_credit_and_log(
      (v_winner ->> 'user_id')::uuid,
      (v_winner ->> 'amount')::numeric,
      format('leaderboard:%s:%s:%s:%s', p_club_id, p_period, v_start, v_winner ->> 'user_id'),
      'leaderboard_payout',
      format('%s Leaderboard, Rank %s', initcap(p_period), v_winner ->> 'rank'),
      (v_plan ->> 'program_id')::uuid
    );
    IF NOT v_credited THEN
      RAISE EXCEPTION 'LEADERBOARD_CREDIT_CONFLICT|Leaderboard Credit Key Already Exists Without A Batch Receipt';
    END IF;

    INSERT INTO public.leaderboard_payouts (
      club_id, period, metric, start_date, end_date, user_id, rank,
      payout_amount, payout_currency, awarded_at, batch_id
    ) VALUES (
      p_club_id, p_period, p_metric, v_start, v_end,
      (v_winner ->> 'user_id')::uuid,
      (v_winner ->> 'rank')::integer,
      (v_winner ->> 'amount')::numeric,
      'chips', now(), v_batch_id
    );
  END LOOP;

  UPDATE public.leaderboard_payout_failures
  SET resolved_at = now(),
      resolution = 'Settlement Completed Automatically'
  WHERE club_id = p_club_id
    AND period = p_period
    AND period_start = v_start
    AND resolved_at IS NULL;

  RETURN jsonb_build_object(
    'success', true,
    'already_settled', false,
    'batch_id', v_batch_id,
    'total_paid', v_total,
    'seed_funded', 0,
    'promo_funded', v_promo_debit,
    'overlay_funded', 0,
    'winner_count', jsonb_array_length(v_winners),
    'tie_policy', 'split_occupied_places'
  );
END;
$$;


ALTER FUNCTION public.fn_payout_leaderboard(p_club_id uuid, p_period text, p_metric text, p_start_date timestamp with time zone, p_end_date timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 48239 (class 0 OID 0)
-- Dependencies: 6266
-- Name: FUNCTION fn_payout_leaderboard(p_club_id uuid, p_period text, p_metric text, p_start_date timestamp with time zone, p_end_date timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_payout_leaderboard(p_club_id uuid, p_period text, p_metric text, p_start_date timestamp with time zone, p_end_date timestamp with time zone) IS 'Atomic service-only leaderboard settlement. Pays from the opening seed, then the recorded Promo Wallet. A shortfall is paid from the club''s own Club Bank, as a separate overlay leg recorded on the batch, only when the round''s immutable standalone club program carries the owner''s explicit opt-in; otherwise, or when the Club Bank cannot cover it, the round stays unpaid and retryable. Splits occupied prizes across ties exactly, credits winners once, and writes immutable batch-linked receipts.';


--
-- TOC entry 9103 (class 1255 OID 18134641)
-- Name: fn_pgrst_reload_watchdog(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_pgrst_reload_watchdog() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_breaches jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_result   jsonb;
  v_reloads_1h int;
  v_timeout_raw text;
  v_timeout interval;
  r record;
  c_reloads_per_hour_breach constant int := 60;
  c_reloads_per_hour_warn   constant int := 20;
BEGIN
  SELECT count(*) INTO v_reloads_1h
    FROM public.ca_ddl_events
   WHERE occurred_at > now() - interval '1 hour'
     AND triggers_pgrst_reload;

  IF v_reloads_1h >= c_reloads_per_hour_warn THEN
    FOR r IN
      SELECT coalesce(application_name,'?') AS app, role_name,
             count(*) AS events,
             max(occurred_at) AS last_at
        FROM public.ca_ddl_events
       WHERE occurred_at > now() - interval '1 hour'
         AND triggers_pgrst_reload
       GROUP BY 1, 2 ORDER BY events DESC LIMIT 5
    LOOP
      IF v_reloads_1h >= c_reloads_per_hour_breach THEN
        v_breaches := v_breaches || jsonb_build_object(
          'check','pgrst_reload_storm','reloads_last_hour',v_reloads_1h,
          'application',r.app,'role',r.role_name,'events',r.events,'last_at',r.last_at,
          'why','Each reload-triggering DDL statement makes PostgREST re-read a ~970-relation schema cache (~28s). '
             || 'At this rate reloading is near-continuous - the precursor of the 2026-08-31 PGRST002 503 storm. '
             || 'Batch DDL into single transactions and stop any migration retry loop (CLAUDE.md, Production DDL policy).');
      ELSE
        v_warnings := v_warnings || jsonb_build_object(
          'check','pgrst_reload_rate_elevated','reloads_last_hour',v_reloads_1h,
          'application',r.app,'role',r.role_name,'events',r.events,'last_at',r.last_at);
      END IF;
    END LOOP;
  END IF;

  SELECT split_part(cfg, '=', 2) INTO v_timeout_raw
    FROM pg_roles, unnest(coalesce(rolconfig, '{}'::text[])) AS cfg
   WHERE rolname = 'authenticator' AND cfg LIKE 'statement_timeout=%'
   LIMIT 1;
  BEGIN
    IF v_timeout_raw IS NULL THEN
      v_timeout := NULL;
    ELSIF v_timeout_raw ~ '^[0-9]+$' THEN
      v_timeout := (v_timeout_raw || ' milliseconds')::interval;
    ELSE
      v_timeout := v_timeout_raw::interval;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_timeout := NULL;
  END;
  IF v_timeout IS NOT NULL AND v_timeout < interval '2 minutes' THEN
    v_breaches := v_breaches || jsonb_build_object(
      'check','authenticator_timeout_reverted','statement_timeout',v_timeout_raw,
      'why','PostgREST loads its schema cache as authenticator; the load takes ~28s here. A timeout below 2min '
         || 'kills the load and recreates the 2026-08-31 PGRST002 outage. '
         || 'Restore with: ALTER ROLE authenticator SET statement_timeout = ''5min'' '
         || '(migration fix_pgrst002_schema_cache_timeout), then recycle authenticator backends.');
  END IF;

  FOR r IN
    SELECT expected.evtname AS name, et.evtenabled
      FROM (VALUES ('pgrst_ddl_watch'), ('pgrst_drop_watch'),
                   ('ca_ddl_watchdog_log'), ('ca_ddl_watchdog_drop_log')) AS expected(evtname)
      LEFT JOIN pg_event_trigger et ON et.evtname = expected.evtname
  LOOP
    IF r.evtenabled IS NULL OR r.evtenabled = 'D' THEN
      v_breaches := v_breaches || jsonb_build_object(
        'check','event_trigger_missing_or_disabled','trigger',r.name,
        'why','pgrst_* watches keep PostgREST''s schema cache honest; ca_ddl_watchdog_* feed this watchdog.');
    END IF;
  END LOOP;

  v_result := jsonb_build_object(
    'checked_at', now(),
    'reloads_last_hour', v_reloads_1h,
    'breaches', v_breaches,
    'warnings', v_warnings);

  INSERT INTO public.pgrst_reload_watchdog_log (breach_count, warn_count, result)
  VALUES (jsonb_array_length(v_breaches), jsonb_array_length(v_warnings), v_result);

  -- Retention: watchdog log 30 days; reload-relevant DDL events 14 days;
  -- non-reload DDL noise (runtime GRANT/REVOKE churn, ~45/min) 3 days.
  DELETE FROM public.pgrst_reload_watchdog_log WHERE ran_at < now() - interval '30 days';
  DELETE FROM public.ca_ddl_events
   WHERE (triggers_pgrst_reload AND occurred_at < now() - interval '14 days')
      OR (NOT triggers_pgrst_reload AND occurred_at < now() - interval '3 days');

  IF jsonb_array_length(v_breaches) > 0 THEN
    RAISE WARNING 'pgrst_reload_watchdog: % breach(es): %',
      jsonb_array_length(v_breaches), v_breaches;
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION public.fn_pgrst_reload_watchdog() OWNER TO postgres;

--
-- TOC entry 8479 (class 1255 OID 31448134)
-- Name: fn_pko_candidate_accepted_scope_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_pko_candidate_accepted_scope_v1(p_tournament_id uuid, p_candidate_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  c public.tournament_knockout_candidates%ROWTYPE;
  a public.hand_atomic_commits%ROWTYPE;
  h public.hand_history%ROWTYPE;
  k public.settlement_idempotency_keys%ROWTYPE;
  settlement_id uuid; raw_settlement_id text;
  hp jsonb; uid text; written_value text;
  participants jsonb := '[]'::jsonb;
  seen text[] := ARRAY[]::text[];
BEGIN
  SELECT * INTO c FROM public.tournament_knockout_candidates
   WHERE id=p_candidate_id AND tournament_id=p_tournament_id;
  IF NOT FOUND OR c.table_id IS NULL OR c.hand_id IS NULL
     OR c.hand_number<1000000 OR c.seat_joined_at IS NULL
     OR c.created_at IS NULL OR c.stack_after IS DISTINCT FROM 0
     OR c.stack_before IS NULL OR c.stack_before<=0 THEN
    RETURN jsonb_build_object('ok',false,'reason','candidate_identity_unproven');
  END IF;
  SELECT * INTO a FROM public.hand_atomic_commits
   WHERE table_id=c.table_id AND hand_number=c.hand_number AND hand_id=c.hand_id;
  IF NOT FOUND OR a.committed_at IS NULL OR c.created_at>a.committed_at
     OR a.stack_result->>'table_id' IS DISTINCT FROM c.table_id::text
     OR a.stack_result->>'hand_number' IS DISTINCT FROM c.hand_number::text
     OR jsonb_typeof(a.stack_result->'written') IS DISTINCT FROM 'object' THEN
    RETURN jsonb_build_object('ok',false,'reason','atomic_identity_unproven');
  END IF;
  raw_settlement_id:=a.stack_result->>'hand_id';
  IF coalesce(raw_settlement_id,'') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN jsonb_build_object('ok',false,'reason','settlement_identity_unproven');
  END IF;
  settlement_id:=raw_settlement_id::uuid;
  SELECT * INTO k FROM public.settlement_idempotency_keys
   WHERE table_id=c.table_id AND hand_id=settlement_id;
  IF NOT FOUND OR k.status IS DISTINCT FROM 'succeeded' OR k.completed_at IS NULL
     OR k.completed_at<c.seat_joined_at OR k.completed_at>a.committed_at
     OR k.result->>'table_id' IS DISTINCT FROM c.table_id::text
     OR k.result->>'hand_number' IS DISTINCT FROM c.hand_number::text
     OR jsonb_typeof(k.result->'written') IS DISTINCT FROM 'object'
     OR k.result->'written' IS DISTINCT FROM a.stack_result->'written' THEN
    RETURN jsonb_build_object('ok',false,'reason','accepted_settlement_unproven');
  END IF;
  -- Validate every written item before any cast. Numeric limits are the
  -- existing tournament stack domain; never cast an invalid item through OR.
  FOR uid,written_value IN SELECT key,value FROM jsonb_each_text(a.stack_result->'written') LOOP
    IF uid !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR coalesce(written_value,'') !~ '^[0-9]+([.][0-9]+)?$'
       OR length(coalesce(written_value,''))>32 THEN
      RETURN jsonb_build_object('ok',false,'reason','accepted_stack_map_unproven');
    END IF;
    IF written_value::numeric<0 THEN
      RETURN jsonb_build_object('ok',false,'reason','accepted_stack_map_unproven');
    END IF;
  END LOOP;
  IF NOT (a.stack_result->'written' ? c.eliminated_user_id::text)
     OR (a.stack_result->'written'->>c.eliminated_user_id::text)::numeric IS DISTINCT FROM 0 THEN
    RETURN jsonb_build_object('ok',false,'reason','accepted_zero_unproven');
  END IF;
  SELECT * INTO h FROM public.hand_history
   WHERE id=c.hand_id AND table_id=c.table_id AND hand_number=c.hand_number
     AND tournament_id=c.tournament_id;
  IF NOT FOUND OR h.created_at IS NULL OR h.created_at<k.completed_at
     OR h.created_at<c.seat_joined_at OR h.created_at>a.committed_at
     OR jsonb_typeof(h.players) IS DISTINCT FROM 'array' THEN
    RETURN jsonb_build_object('ok',false,'reason','accepted_history_unproven');
  END IF;
  IF jsonb_array_length(h.players)=0 THEN
    RETURN jsonb_build_object('ok',false,'reason','accepted_roster_unproven');
  END IF;
  FOR hp IN SELECT value FROM jsonb_array_elements(h.players) LOOP
    uid:=coalesce(hp->>'userId',hp->>'user_id');
    IF coalesce(uid,'') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR uid=ANY(seen) OR NOT (a.stack_result->'written' ? uid)
       OR coalesce(hp->>'stack','') !~ '^[0-9]+([.][0-9]+)?$'
       OR length(coalesce(hp->>'stack',''))>32 THEN
      RETURN jsonb_build_object('ok',false,'reason','accepted_roster_unproven');
    END IF;
    IF (hp->>'stack')::numeric IS DISTINCT FROM (a.stack_result->'written'->>uid)::numeric THEN
      RETURN jsonb_build_object('ok',false,'reason','accepted_roster_stack_conflict');
    END IF;
    seen:=array_append(seen,uid);
    participants:=participants||jsonb_build_array(uid);
  END LOOP;
  IF cardinality(seen)<>(SELECT count(*) FROM jsonb_object_keys(a.stack_result->'written')) THEN
    RETURN jsonb_build_object('ok',false,'reason','accepted_roster_incomplete');
  END IF;
  RETURN jsonb_build_object('ok',true,'candidate_id',c.id,
    'tournament_id',c.tournament_id,'table_id',c.table_id,'hand_id',c.hand_id,
    'hand_number',c.hand_number,'eliminated_user_id',c.eliminated_user_id,
    'seat_joined_at',c.seat_joined_at,'settlement_completed_at',k.completed_at,
    'committed_at',a.committed_at,
    'participants',participants);
END;
$_$;


ALTER FUNCTION public.fn_pko_candidate_accepted_scope_v1(p_tournament_id uuid, p_candidate_id uuid) OWNER TO postgres;

--
-- TOC entry 3397 (class 1255 OID 31448135)
-- Name: fn_pko_claim_predecessor_status_v1(uuid, uuid, uuid, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_pko_claim_predecessor_status_v1(p_tournament_id uuid, p_eliminated_user_id uuid, p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_seat_joined_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  target public.tournament_knockout_candidates%ROWTYPE;
  c public.tournament_knockout_candidates%ROWTYPE;
  o public.tournament_bounty_obligations%ROWTYPE;
  target_scope jsonb; prior_scope jsonb; claims jsonb;
  target_commit timestamptz; prior_commit timestamptz;
  inspected integer:=0; checked integer:=0;
  -- Reviewable work bound; never a truncated successful dependency proof.
  scope_limit constant integer:=10000;
  blocked jsonb:='[]'::jsonb; unknown jsonb:='[]'::jsonb;
  detail jsonb; known_marker boolean; conflicting_recipient_narrative boolean;
  same_accepted_hand boolean;
BEGIN
  IF p_tournament_id IS NULL OR p_eliminated_user_id IS NULL
     OR p_table_id IS NULL OR p_hand_id IS NULL OR p_hand_number IS NULL
     OR p_seat_joined_at IS NULL THEN
    RETURN jsonb_build_object('ok',false,'status','unknown','reason','target_identity_required');
  END IF;
  SELECT * INTO target FROM public.tournament_knockout_candidates
   WHERE tournament_id=p_tournament_id AND hand_number=p_hand_number
     AND eliminated_user_id=p_eliminated_user_id;
  IF NOT FOUND OR target.table_id IS DISTINCT FROM p_table_id
     OR target.hand_id IS DISTINCT FROM p_hand_id
     OR target.seat_joined_at IS DISTINCT FROM p_seat_joined_at THEN
    RETURN jsonb_build_object('ok',false,'status','unknown','reason','target_identity_conflict');
  END IF;
  target_scope:=public.fn_pko_candidate_accepted_scope_v1(p_tournament_id,target.id);
  IF target_scope->>'ok' IS DISTINCT FROM 'true' THEN
    RETURN jsonb_build_object('ok',false,'status','unknown','reason','target_evidence_unproven',
      'detail',target_scope);
  END IF;
  target_commit:=(target_scope->>'committed_at')::timestamptz;

  -- A pending debt without its exact accepted candidate is not invisible work.
  -- Candidate enumeration alone cannot discharge this orphaned payment record.
  IF EXISTS (
    SELECT 1 FROM public.tournament_bounty_obligations debt
     WHERE debt.tournament_id=p_tournament_id AND debt.mode='pko' AND debt.state='pending'
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_knockout_candidates candidate
          WHERE candidate.tournament_id=debt.tournament_id
            AND candidate.eliminated_user_id=debt.eliminated_user_id
            AND candidate.hand_number=debt.hand_number AND candidate.table_id=debt.table_id
            AND candidate.hand_id=debt.hand_id AND candidate.seat_joined_at=debt.seat_joined_at)
  ) THEN
    RETURN jsonb_build_object('ok',false,'status','unknown','reason','pending_pko_candidate_missing');
  END IF;

  -- Existing (tournament_id,hand_number,eliminated_user_id) unique index.
  -- The ordering is a scan cursor only, NOT chronological proof. Preallocation
  -- at another table can give an earlier accepted predecessor a larger number.
  FOR c IN SELECT * FROM public.tournament_knockout_candidates
    WHERE tournament_id=p_tournament_id
      AND eliminated_user_id<>p_eliminated_user_id
    ORDER BY hand_number,eliminated_user_id LIMIT scope_limit+1
  LOOP
    inspected:=inspected+1;
    IF inspected>scope_limit THEN
      RETURN jsonb_build_object('ok',false,'status','unknown','reason','predecessor_scope_incomplete',
        'inspected',scope_limit,'scope_limit',scope_limit,'predecessors',blocked,'unknown',unknown);
    END IF;
    -- Same-hand dependence uses the same exact marker proof as cross-hand
    -- dependence. The original side-pot/tie guard remains an additional veto,
    -- but its settled state alone is no longer enough to skip this proof.
    same_accepted_hand:=c.hand_id=p_hand_id AND c.table_id=p_table_id AND c.hand_number=p_hand_number;
    detail:=jsonb_build_object('candidate_id',c.id,'eliminated_user_id',c.eliminated_user_id,
      'table_id',c.table_id,'hand_id',c.hand_id,'hand_number',c.hand_number,
      'seat_joined_at',c.seat_joined_at,'candidate_state',c.state);
    prior_scope:=public.fn_pko_candidate_accepted_scope_v1(p_tournament_id,c.id);
    IF prior_scope->>'ok' IS DISTINCT FROM 'true' THEN
      IF jsonb_array_length(unknown)<20 THEN
        unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','candidate_evidence_unproven','detail',prior_scope));
      END IF;
      CONTINUE;
    END IF;
    -- A complete accepted participant map proves a different table's head
    -- cannot flow into this player. No marker/pot work for that hand.
    IF NOT (prior_scope->'participants' ? p_eliminated_user_id::text) THEN
      -- Malformed history must not name an absent accepted participant as a
      -- recipient/eligible player. A raw scalar mention is only an UNKNOWN
      -- conflict witness, never attribution; JSONPath safely handles scalars.
      SELECT coalesce(jsonb_path_exists(h.pots,'$.** ? (@ == $uid)',
               jsonb_build_object('uid',p_eliminated_user_id::text)),false)
          OR coalesce(jsonb_path_exists(h.winners,'$.** ? (@ == $uid)',
               jsonb_build_object('uid',p_eliminated_user_id::text)),false)
        INTO conflicting_recipient_narrative FROM public.hand_history h
       WHERE h.id=c.hand_id;
      IF conflicting_recipient_narrative IS TRUE THEN
        IF jsonb_array_length(unknown)<20 THEN
          unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','recipient_outside_accepted_roster'));
        END IF;
      END IF;
      CONTINUE;
    END IF;
    prior_commit:=(prior_scope->>'committed_at')::timestamptz;
    IF NOT same_accepted_hand AND prior_commit>target_commit THEN CONTINUE; END IF;
    IF NOT same_accepted_hand AND prior_commit=target_commit THEN
      IF jsonb_array_length(unknown)<20 THEN
        unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','cross_hand_causal_order_unproven'));
      END IF;
      CONTINUE;
    END IF;
    checked:=checked+1;
    -- Exact lookup by unique key, then compare every immutable identity.
    SELECT * INTO o FROM public.tournament_bounty_obligations
     WHERE tournament_id=p_tournament_id AND hand_number=c.hand_number
       AND eliminated_user_id=c.eliminated_user_id;
    IF FOUND THEN
      IF o.table_id IS DISTINCT FROM c.table_id OR o.hand_id IS DISTINCT FROM c.hand_id
         OR o.seat_joined_at IS DISTINCT FROM c.seat_joined_at OR o.mode IS DISTINCT FROM 'pko'
         OR o.settlement_completed_at IS DISTINCT FROM (prior_scope->>'settlement_completed_at')::timestamptz THEN
        IF jsonb_array_length(unknown)<20 THEN
          unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','predecessor_obligation_identity_conflict','obligation_id',o.id));
        END IF;
        CONTINUE;
      END IF;
      IF jsonb_typeof(o.claimants) IS DISTINCT FROM 'array' THEN
        IF jsonb_array_length(unknown)<20 THEN
          unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','predecessor_claimants_malformed','obligation_id',o.id));
        END IF;
        CONTINUE;
      END IF;
      IF jsonb_array_length(o.claimants)=0 OR EXISTS (
        SELECT 1 FROM jsonb_array_elements(o.claimants) e
         WHERE coalesce(e->>'user_id','') !~*
           '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR e->>'weight' IS DISTINCT FROM '1'
      ) THEN
        IF jsonb_array_length(unknown)<20 THEN
          unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','predecessor_claimants_malformed','obligation_id',o.id));
        END IF;
        CONTINUE;
      END IF;
      IF jsonb_array_length(o.claimants)<>(SELECT count(DISTINCT (e->>'user_id')::uuid)
            FROM jsonb_array_elements(o.claimants) e)
         OR o.claimants @> jsonb_build_array(jsonb_build_object('user_id',o.eliminated_user_id,'weight',1)) THEN
        IF jsonb_array_length(unknown)<20 THEN
          unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','predecessor_claimants_malformed','obligation_id',o.id));
        END IF;
        CONTINUE;
      END IF;
    END IF;
    BEGIN
      claims:=public.fn_exact_tournament_knockout_claimants(p_tournament_id,c.hand_id,c.eliminated_user_id);
    EXCEPTION WHEN invalid_parameter_value OR invalid_text_representation OR numeric_value_out_of_range THEN
      -- Only malformed read evidence is classified here. Cancellation,
      -- connection, permissions, and unexpected execution errors propagate.
      claims:=NULL;
    END;
    IF jsonb_typeof(claims) IS DISTINCT FROM 'array' THEN
      IF jsonb_array_length(unknown)<20 THEN
        unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','predecessor_recipients_unproven'));
      END IF;
      CONTINUE;
    END IF;
    IF jsonb_array_length(claims)=0 THEN
      IF jsonb_array_length(unknown)<20 THEN
        unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','predecessor_recipients_unproven'));
      END IF;
      CONTINUE;
    END IF;
    IF o.id IS NOT NULL AND o.claimants IS DISTINCT FROM claims THEN
      IF jsonb_array_length(unknown)<20 THEN
        unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','predecessor_claimant_snapshot_conflict','obligation_id',o.id));
      END IF;
      CONTINUE;
    END IF;
    IF NOT (claims @> jsonb_build_array(jsonb_build_object('user_id',p_eliminated_user_id,'weight',1))) THEN CONTINUE; END IF;
    IF o.id IS NOT NULL AND o.state='settled' THEN
      -- The marker discharges the accepted predecessor only after its exact
      -- recipient and settlement identities have also matched.
      IF public.fn_bounty_obligation_has_complete_marker(o.id) THEN CONTINUE; END IF;
      IF jsonb_array_length(unknown)<20 THEN
        unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','predecessor_marker_incomplete','obligation_id',o.id));
      END IF;
      CONTINUE;
    END IF;
    IF jsonb_array_length(blocked)<20 THEN
      blocked:=blocked||jsonb_build_array(detail||jsonb_build_object('obligation_id',o.id,
        'committed_at',prior_commit,'claimants',claims,
        'reason',CASE WHEN o.id IS NOT NULL THEN 'pending_pko_predecessor'
          WHEN c.state='pending' THEN 'unclaimed_pko_predecessor'
          ELSE 'closed_predecessor_claim_missing' END,
        'recovery_required',o.id IS NULL AND c.state<>'pending'));
    END IF;
  END LOOP;
  IF jsonb_array_length(unknown)>0 THEN
    RETURN jsonb_build_object('ok',false,'status','unknown','reason','predecessor_evidence_unproven',
      'inspected',inspected,'checked',checked,'predecessors',blocked,'unknown',unknown);
  END IF;
  IF jsonb_array_length(blocked)>0 THEN
    RETURN jsonb_build_object('ok',false,'status','blocked','reason','unsettled_pko_predecessor',
      'inspected',inspected,'checked',checked,'predecessors',blocked);
  END IF;
  RETURN jsonb_build_object('ok',true,'status','clear','inspected',inspected,'checked',checked);
END;
$_$;


ALTER FUNCTION public.fn_pko_claim_predecessor_status_v1(p_tournament_id uuid, p_eliminated_user_id uuid, p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_seat_joined_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 8839 (class 1255 OID 31417911)
-- Name: fn_pko_hand_is_independent_of_later_settlements(uuid, uuid, bigint, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_pko_hand_is_independent_of_later_settlements(p_tournament_id uuid, p_table_id uuid, p_hand_number bigint, p_eliminated_user_id uuid, p_claimants jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  participants uuid[]; watermark bigint; later record;
BEGIN
  IF p_tournament_id IS NULL OR p_table_id IS NULL OR p_eliminated_user_id IS NULL
     OR p_hand_number IS NULL OR p_hand_number<1000000
     OR jsonb_typeof(p_claimants) IS DISTINCT FROM 'array' THEN RETURN false; END IF;
  IF jsonb_array_length(p_claimants)=0 OR EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_claimants) c
     WHERE coalesce(c->>'user_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR c->>'weight' IS DISTINCT FROM '1'
  ) THEN RETURN false; END IF;
  SELECT ARRAY[p_eliminated_user_id]||array_agg((c->>'user_id')::uuid)
    INTO participants FROM jsonb_array_elements(p_claimants) c;
  IF cardinality(participants)<>(SELECT count(DISTINCT u) FROM unnest(participants) u)
     OR EXISTS (
       SELECT 1 FROM unnest(participants[2:cardinality(participants)]) u
        WHERE NOT EXISTS (SELECT 1 FROM public.tournament_players tp
          WHERE tp.tournament_id=p_tournament_id AND tp.user_id=u AND tp.status='playing')
     ) THEN RETURN false; END IF;

  -- A missing, stale or corrupt watermark cannot authorize admission.
  SELECT w.last_settled_hand_number INTO watermark
    FROM public.tournament_pko_settlement_watermarks w
    JOIN public.tournament_bounty_obligations o
      ON o.id=w.last_obligation_id AND o.tournament_id=w.tournament_id
     AND o.hand_number=w.last_settled_hand_number AND o.mode='pko' AND o.state='settled'
   WHERE w.tournament_id=p_tournament_id;
  IF watermark IS NULL OR watermark<=p_hand_number OR EXISTS (
    SELECT 1 FROM public.tournament_bounty_obligations o
     WHERE o.tournament_id=p_tournament_id AND o.mode='pko'
       AND o.state='settled' AND o.hand_number>watermark
  ) THEN RETURN false; END IF;

  -- Validate each later identity before the marker function casts claimant UUIDs.
  -- Disjoint head mutations commute. Any shared table or person, including a
  -- pending later head snapshot, keeps the existing order refusal intact.
  FOR later IN
    SELECT o.table_id,o.eliminated_user_id,o.claimants,o.state,o.id
      FROM public.tournament_bounty_obligations o
     WHERE o.tournament_id=p_tournament_id AND o.mode='pko'
       AND o.hand_number>p_hand_number
  LOOP
    IF later.table_id IS NULL OR later.table_id=p_table_id
       OR later.eliminated_user_id IS NULL OR later.eliminated_user_id=ANY(participants)
       OR jsonb_typeof(later.claimants) IS DISTINCT FROM 'array' THEN RETURN false; END IF;
    IF jsonb_array_length(later.claimants)=0 OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(later.claimants) c
       WHERE coalesce(c->>'user_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          OR c->>'weight' IS DISTINCT FROM '1'
    ) THEN RETURN false; END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(later.claimants) c
      WHERE (c->>'user_id')::uuid=ANY(participants)
         OR (c->>'user_id')::uuid=later.eliminated_user_id)
       OR jsonb_array_length(later.claimants)<>(SELECT count(DISTINCT (c->>'user_id')::uuid)
          FROM jsonb_array_elements(later.claimants) c)
       OR later.state NOT IN ('pending','settled')
       OR (later.state='settled' AND NOT public.fn_bounty_obligation_has_complete_marker(later.id))
    THEN RETURN false; END IF;
  END LOOP;
  RETURN true;
END;
$_$;


ALTER FUNCTION public.fn_pko_hand_is_independent_of_later_settlements(p_tournament_id uuid, p_table_id uuid, p_hand_number bigint, p_eliminated_user_id uuid, p_claimants jsonb) OWNER TO postgres;

--
-- TOC entry 4605 (class 1255 OID 31448137)
-- Name: fn_pko_watermark_admission_status_v1(uuid, uuid, uuid, uuid, bigint, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_pko_watermark_admission_status_v1(p_tournament_id uuid, p_eliminated_user_id uuid, p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_seat_joined_at timestamp with time zone, p_claimants jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  participants uuid[]; others uuid[]; target_candidate uuid;
  target_scope jsonb; later_scope jsonb; exact_claimants jsonb;
  target_commit timestamptz; later_commit timestamptz;
  watermark bigint; watermark_obligation uuid;
  o public.tournament_bounty_obligations%ROWTYPE;
  c public.tournament_knockout_candidates%ROWTYPE;
  inspected integer:=0; scope_limit constant integer:=10000;
  overlapping boolean;
BEGIN
  IF p_tournament_id IS NULL OR p_eliminated_user_id IS NULL OR p_table_id IS NULL
     OR p_hand_id IS NULL OR p_hand_number IS NULL OR p_seat_joined_at IS NULL
     OR jsonb_typeof(p_claimants) IS DISTINCT FROM 'array' THEN
    RETURN jsonb_build_object('ok',false,'reason','watermark_target_identity_unproven');
  END IF;
  IF jsonb_array_length(p_claimants)=0 OR EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_claimants) e
     WHERE coalesce(e->>'user_id','') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR e->>'weight' IS DISTINCT FROM '1'
  ) THEN RETURN jsonb_build_object('ok',false,'reason','watermark_target_claimants_unproven'); END IF;
  SELECT ARRAY[p_eliminated_user_id]||array_agg((e->>'user_id')::uuid)
    INTO participants FROM jsonb_array_elements(p_claimants) e;
  IF cardinality(participants)<>(SELECT count(DISTINCT u) FROM unnest(participants) u)
     OR EXISTS (SELECT 1 FROM unnest(participants[2:cardinality(participants)]) u
         WHERE NOT EXISTS (SELECT 1 FROM public.tournament_players tp
          WHERE tp.tournament_id=p_tournament_id AND tp.user_id=u AND tp.status='playing')) THEN
    RETURN jsonb_build_object('ok',false,'reason','watermark_target_generation_unproven');
  END IF;
  SELECT id INTO target_candidate FROM public.tournament_knockout_candidates
   WHERE tournament_id=p_tournament_id AND hand_number=p_hand_number
     AND eliminated_user_id=p_eliminated_user_id AND table_id=p_table_id
     AND hand_id=p_hand_id AND seat_joined_at=p_seat_joined_at;
  IF target_candidate IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','watermark_target_candidate_missing');
  END IF;
  target_scope:=public.fn_pko_candidate_accepted_scope_v1(p_tournament_id,target_candidate);
  IF target_scope->>'ok' IS DISTINCT FROM 'true' THEN
    RETURN jsonb_build_object('ok',false,'reason','watermark_target_evidence_unproven','detail',target_scope);
  END IF;
  BEGIN
    exact_claimants:=public.fn_exact_tournament_knockout_claimants(p_tournament_id,p_hand_id,p_eliminated_user_id);
  EXCEPTION WHEN invalid_parameter_value OR invalid_text_representation OR numeric_value_out_of_range THEN
    exact_claimants:=NULL;
  END;
  IF exact_claimants IS DISTINCT FROM p_claimants THEN
    RETURN jsonb_build_object('ok',false,'reason','watermark_target_claimants_conflict');
  END IF;
  target_commit:=(target_scope->>'committed_at')::timestamptz;
  SELECT w.last_settled_hand_number,w.last_obligation_id
    INTO watermark,watermark_obligation FROM public.tournament_pko_settlement_watermarks w
    JOIN public.tournament_bounty_obligations b ON b.id=w.last_obligation_id
     AND b.tournament_id=w.tournament_id AND b.hand_number=w.last_settled_hand_number
     AND b.state='settled' AND b.mode='pko'
   WHERE w.tournament_id=p_tournament_id;
  -- This helper is only the exception for a caller which saw a greater
  -- watermark. Missing/corrupt/not-applicable state cannot authorize it.
  IF watermark IS NULL OR watermark<=p_hand_number OR EXISTS (
    SELECT 1 FROM public.tournament_bounty_obligations b
     WHERE b.tournament_id=p_tournament_id AND b.mode='pko'
       AND b.state='settled' AND b.hand_number>watermark
  ) THEN RETURN jsonb_build_object('ok',false,'reason','watermark_identity_unproven'); END IF;

  FOR o IN SELECT * FROM public.tournament_bounty_obligations
    WHERE tournament_id=p_tournament_id AND mode='pko' AND hand_number>p_hand_number
    ORDER BY hand_number,eliminated_user_id LIMIT scope_limit+1
  LOOP
    inspected:=inspected+1;
    IF inspected>scope_limit THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_scope_incomplete','inspected',scope_limit);
    END IF;
    IF jsonb_typeof(o.claimants) IS DISTINCT FROM 'array' THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_claimants_unproven','obligation_id',o.id);
    END IF;
    IF jsonb_array_length(o.claimants)=0 OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(o.claimants) e
       WHERE coalesce(e->>'user_id','') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         OR e->>'weight' IS DISTINCT FROM '1'
    ) THEN RETURN jsonb_build_object('ok',false,'reason','watermark_claimants_unproven','obligation_id',o.id); END IF;
    SELECT ARRAY[o.eliminated_user_id]||array_agg((e->>'user_id')::uuid)
      INTO others FROM jsonb_array_elements(o.claimants) e;
    IF cardinality(others)<>(SELECT count(DISTINCT u) FROM unnest(others) u)
       OR o.state IS NULL OR o.state NOT IN ('pending','settled') OR o.table_id IS NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_obligation_unproven','obligation_id',o.id);
    END IF;
    IF o.state='settled' AND public.fn_bounty_obligation_has_complete_marker(o.id) IS NOT TRUE THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_marker_incomplete','obligation_id',o.id);
    END IF;
    overlapping:=o.table_id=p_table_id OR others && participants;
    -- Preserve R35's disjoint-table commutativity, including complete later
    -- settled heads and disjoint pending snapshots. Extra chronology is only
    -- needed to admit a SHARED participant/table after a larger hand number.
    IF NOT overlapping THEN CONTINUE; END IF;
    IF o.state IS DISTINCT FROM 'settled' THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_shared_head_pending','obligation_id',o.id);
    END IF;
    SELECT * INTO c FROM public.tournament_knockout_candidates
     WHERE tournament_id=p_tournament_id AND hand_number=o.hand_number
       AND eliminated_user_id=o.eliminated_user_id;
    IF NOT FOUND OR c.table_id IS DISTINCT FROM o.table_id
       OR c.hand_id IS DISTINCT FROM o.hand_id OR c.seat_joined_at IS DISTINCT FROM o.seat_joined_at THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_prior_candidate_conflict','obligation_id',o.id);
    END IF;
    later_scope:=public.fn_pko_candidate_accepted_scope_v1(p_tournament_id,c.id);
    IF later_scope->>'ok' IS DISTINCT FROM 'true' THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_prior_evidence_unproven',
        'obligation_id',o.id,'detail',later_scope);
    END IF;
    IF (later_scope->>'settlement_completed_at')::timestamptz IS DISTINCT FROM o.settlement_completed_at THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_prior_settlement_conflict','obligation_id',o.id);
    END IF;
    BEGIN
      exact_claimants:=public.fn_exact_tournament_knockout_claimants(p_tournament_id,c.hand_id,c.eliminated_user_id);
    EXCEPTION WHEN invalid_parameter_value OR invalid_text_representation OR numeric_value_out_of_range THEN
      exact_claimants:=NULL;
    END;
    IF exact_claimants IS DISTINCT FROM o.claimants THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_prior_claimants_conflict','obligation_id',o.id);
    END IF;
    -- Settled independent heads commute even at the same table. Adding two
    -- independently proved carries to a common collector also commutes: the
    -- collector's existing head never sets either incoming cash/carry split.
    -- Keep every accepted identity, exact claimant and complete-marker proof
    -- above. A consumed collector head, credit to the target eliminated head,
    -- or repeated eliminated identity still needs the causal proof below.
    IF NOT (o.eliminated_user_id=ANY(participants)
            OR p_eliminated_user_id=ANY(others)) THEN CONTINUE; END IF;
    later_commit:=(later_scope->>'committed_at')::timestamptz;
    IF later_commit>=target_commit THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_shared_head_not_causally_prior',
        'obligation_id',o.id,'prior_committed_at',later_commit,'target_committed_at',target_commit);
    END IF;
  END LOOP;
  RETURN jsonb_build_object('ok',true,'reason','independent_or_causally_prior',
    'inspected',inspected,'watermark',watermark);
END;
$_$;


ALTER FUNCTION public.fn_pko_watermark_admission_status_v1(p_tournament_id uuid, p_eliminated_user_id uuid, p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_seat_joined_at timestamp with time zone, p_claimants jsonb) OWNER TO postgres;

--
-- TOC entry 3371 (class 1255 OID 16628435)
-- Name: fn_place_entitlement(numeric, anyelement, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_place_entitlement(p_pool numeric, p_structure anyelement, p_place integer) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_raw jsonb; v_arr jsonb; v_pct numeric;
BEGIN
  IF p_place IS NULL OR COALESCE(p_pool, 0) <= 0 THEN
    RETURN 0;
  END IF;
  BEGIN
    v_raw := to_jsonb(p_structure);
    IF jsonb_typeof(v_raw) = 'string' THEN
      v_arr := (v_raw #>> '{}')::jsonb;
    ELSE
      v_arr := v_raw;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RETURN 0;
  END;
  IF v_arr IS NULL OR jsonb_typeof(v_arr) <> 'array' THEN
    RETURN 0;
  END IF;
  SELECT (el->>'percentage')::numeric INTO v_pct
    FROM jsonb_array_elements(v_arr) el
   WHERE (el->>'place')::int = p_place
   LIMIT 1;
  RETURN round(COALESCE(p_pool, 0) * COALESCE(v_pct, 0) / 100.0, 2);
END;
$$;


ALTER FUNCTION public.fn_place_entitlement(p_pool numeric, p_structure anyelement, p_place integer) OWNER TO postgres;

