--
-- TOC entry 4480 (class 1255 OID 155890939)
-- Name: fn_poker_diamond_attach_cash_game(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_poker_diamond_attach_cash_game(p_table_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE t public.tables%ROWTYPE; existing public.cash_games%ROWTYPE; g uuid; projection jsonb; snap jsonb;
 keys constant text[]:=ARRAY['min_buy_in','max_buy_in','rake_percent','rake_cap_bb','bbj_percent',
 'insurance_enabled','seven_deuce_enabled','nit_game','all_in_or_fold','pineapple_holdem','cap_enabled',
 'run_it_twice','allow_run_it_twice','run_it_twice_enabled','run_it_mode',
 'straddle_enabled','auto_utg_straddle','voluntary_straddle','ante','ante_enabled','big_blind_ante_enabled',
 'bomb_pot_enabled','bomb_pot_variant','bomb_pot_ante_fixed','bomb_pot_ante_multiplier',
 'bomb_pot_board_count','bomb_pot_double_board','bomb_pot_trigger_mode','bomb_pot_frequency',
 'bomb_pot_interval_seconds','action_time_seconds'];
BEGIN
 SELECT tb.* INTO t FROM public.tables tb JOIN public.ca_arena_settings a ON a.id=1 AND a.club_id=tb.club_id
   JOIN public.clubs c ON c.id=a.club_id WHERE tb.id=p_table_id AND c.asset='diamonds'
   AND c.is_platform AND c.union_id IS NULL AND tb.union_id IS NULL FOR UPDATE OF tb;
 IF NOT FOUND OR t.cluster_id IS NOT NULL OR NOT public.fn_poker_diamond_plain_cash_table(t) THEN
  RAISE EXCEPTION 'diamond_cluster_attach_scope' USING ERRCODE='23514';
 END IF;
 SELECT jsonb_object_agg(k,to_jsonb(t)->k) INTO projection FROM unnest(keys) k;
 snap:=public.fn_cash_template_defaults('classic',t.game_variant)
   ||jsonb_build_object('asset','diamonds','diamond_table',projection,
     'seats',t.max_players,'sb',t.small_blind,'bb',t.big_blind,'table_mode','must_move',
     'min_buyin_bb',ceil(t.min_buy_in/t.big_blind),'max_buyin_bb',floor(t.max_buy_in/t.big_blind),
     'resolved_at',to_jsonb(clock_timestamp()));
 SELECT * INTO existing FROM public.cash_games WHERE club_id=t.club_id
   AND variant=t.game_variant AND sb=t.small_blind AND bb=t.big_blind
   AND template_name='classic' AND must_move AND enabled FOR UPDATE;
 IF FOUND THEN
  IF existing.handedness IS DISTINCT FROM t.max_players
    OR existing.ruleset_snapshot->'diamond_table' IS DISTINCT FROM projection THEN
   RAISE EXCEPTION 'diamond_cluster_existing_projection_mismatch' USING ERRCODE='23514';
  END IF;
  g:=existing.id;
 ELSE
 INSERT INTO public.cash_games(club_id,union_id,name,template_name,variant,sb,bb,
   handedness,ruleset_snapshot,enabled,state,must_move,lightning_enabled,cluster_mode,created_by)
 VALUES(t.club_id,NULL,t.name,'classic',t.game_variant,t.small_blind,t.big_blind,
   t.max_players,snap,true,CASE WHEN t.current_players>0 THEN 'live' ELSE 'dormant' END,
   true,false,'must_move',auth.uid()) RETURNING id INTO g;
 END IF;
 UPDATE public.tables SET cluster_id=g,role=CASE WHEN existing.id IS NULL THEN 'main' ELSE 'feeder' END,
   main_index=CASE WHEN existing.id IS NULL THEN 1 END,lifecycle='live',
   opened_at=coalesce(opened_at,created_at),live_at=coalesce(live_at,created_at),
   auto_extension=false,auto_restart=false,auto_create_table=false WHERE id=t.id;
 INSERT INTO public.cash_game_roster(game_id,user_id,joined_at)
 SELECT g,user_id,min(joined_at) FROM public.table_seats WHERE table_id=t.id AND left_at IS NULL GROUP BY user_id
 ON CONFLICT(game_id,user_id) WHERE left_at IS NULL DO NOTHING;
 INSERT INTO public.cash_cluster_events(game_id,table_id,kind,payload)
 VALUES(g,t.id,'game_created',jsonb_build_object('asset','diamonds','adopted',true,'preserved_table_id',t.id));
 PERFORM public.fn_poker_diamond_project_cluster(g,t.id);
 RETURN g;
END;
$$;


ALTER FUNCTION public.fn_poker_diamond_attach_cash_game(p_table_id uuid) OWNER TO postgres;

--
-- TOC entry 6251 (class 1255 OID 72776490)
-- Name: fn_poker_diamond_audit_tournament_created(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_poker_diamond_audit_tournament_created(p_result jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
  v_id := NULLIF(p_result ->> 'tournamentId', '')::uuid;
  IF v_id IS NULL OR NOT public.fn_poker_diamond_tournament(v_id) THEN
    RAISE EXCEPTION 'diamond_tournament_would_not_be_recognised' USING ERRCODE='23514';
  END IF;
  PERFORM public.fn_poker_diamond_staff_audit('diamond.tournament_create', 'diamond_tournament', v_id, NULL,
    (SELECT to_jsonb(t) FROM public.tournaments t WHERE t.id = v_id),
    jsonb_build_object('door', 'fn_poker_diamond_create_tournament', 'table_id', p_result -> 'table_id'));
  RETURN p_result;
END $$;


ALTER FUNCTION public.fn_poker_diamond_audit_tournament_created(p_result jsonb) OWNER TO postgres;

--
-- TOC entry 9416 (class 1255 OID 25957053)
-- Name: fn_poker_diamond_buyin(uuid, uuid, integer, numeric, boolean, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_poker_diamond_buyin(p_user_id uuid, p_table_id uuid, p_seat_number integer, p_amount numeric, p_auto_rebuy boolean, p_club_id uuid, p_idempotency_key uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
 v_t public.tables%ROWTYPE;
 v_game_id uuid;
 v_locked_game public.cash_games%ROWTYPE;
 v_seat_id uuid:=gen_random_uuid();
 v_custody jsonb;
 v_taken integer;
 v_holds integer;
BEGIN
 IF p_idempotency_key IS NULL OR p_user_id IS NULL OR p_table_id IS NULL
    OR p_seat_number IS NULL OR p_seat_number<1 OR p_auto_rebuy IS DISTINCT FROM false
    OR p_amount IS NULL OR p_amount NOT BETWEEN 1 AND 2147483647
    OR p_amount<>trunc(p_amount) THEN
   RAISE EXCEPTION 'invalid_diamond_cash_purchase' USING ERRCODE='22023';
 END IF;
 -- Staff pause/close and allocation lock game before table. Take the
 -- same lock before reserving money; a concurrent pause is observed here.
 SELECT t.cluster_id INTO v_game_id FROM public.tables t WHERE t.id=p_table_id;
 IF v_game_id IS NOT NULL THEN
   SELECT cg.* INTO v_locked_game FROM public.cash_games cg
     WHERE cg.id=v_game_id FOR UPDATE;
   IF NOT FOUND OR NOT coalesce(v_locked_game.enabled,false)
      OR v_locked_game.cluster_mode IS DISTINCT FROM 'must_move' THEN
     RAISE EXCEPTION 'GAME_CLOSED: this Diamond game is not taking new players' USING ERRCODE='23514';
   END IF;
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('table_cap:'||p_user_id,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('table_seat:'||p_table_id,0));
 SELECT t.* INTO v_t FROM public.tables t
   JOIN public.clubs c ON c.id=t.club_id
   JOIN public.ca_arena_settings a ON a.id=1 AND a.club_id=c.id
 WHERE t.id=p_table_id AND c.asset='diamonds' AND c.is_platform IS TRUE
   AND c.union_id IS NULL AND t.union_id IS NULL AND a.cash_games_enabled
 FOR UPDATE OF t;
 IF NOT FOUND THEN
   RAISE EXCEPTION 'diamond_cash_not_open' USING ERRCODE='55000';
 END IF;
 IF v_t.cluster_id IS DISTINCT FROM v_game_id THEN
   RAISE EXCEPTION 'diamond_cash_entry_scope_changed' USING ERRCODE='55000';
 END IF;
 IF v_t.cluster_id IS NOT NULL AND v_t.lifecycle NOT IN ('opening','live') THEN
   RAISE EXCEPTION 'TABLE_CLOSING: this Diamond table is not taking new players' USING ERRCODE='23514';
 END IF;
 IF NOT public.fn_poker_diamond_plain_cash_table(v_t) THEN
   RAISE EXCEPTION 'diamond_plain_cash_table_required' USING ERRCODE='23514';
 END IF;
 -- Match the shared engine load boundary before reserving any Diamonds.
 IF EXISTS(SELECT 1 FROM (VALUES(v_t.small_blind),(v_t.big_blind),
      (v_t.min_buy_in),(v_t.max_buy_in)) AS amount(value)
      WHERE value IS NULL OR value NOT BETWEEN 1 AND 2147483647
        OR value<>trunc(value))
    OR COALESCE(v_t.ante,0) NOT BETWEEN 0 AND 9007199254740991
    OR COALESCE(v_t.ante,0)<>trunc(COALESCE(v_t.ante,0)) THEN
   RAISE EXCEPTION 'diamond_cash_requires_whole_amounts' USING ERRCODE='23514';
 END IF;
 IF coalesce(v_t.bomb_pot_enabled,false) THEN
   IF coalesce(lower(v_t.bomb_pot_variant),'') NOT IN ('',v_t.game_variant) THEN
     RAISE EXCEPTION 'diamond_bomb_pot_requires_the_table_game' USING ERRCODE='23514';
   END IF;
   IF NOT EXISTS(SELECT 1 FROM (SELECT CASE
          WHEN coalesce(v_t.bomb_pot_ante_fixed,0)>0 THEN v_t.bomb_pot_ante_fixed
          ELSE v_t.big_blind*coalesce(v_t.bomb_pot_ante_multiplier,2) END AS a) x
        WHERE x.a IS NOT NULL AND x.a BETWEEN 1 AND 2147483647 AND x.a=trunc(x.a)) THEN
     RAISE EXCEPTION 'diamond_bomb_pot_requires_a_whole_ante' USING ERRCODE='23514';
   END IF;
 END IF;
 IF p_club_id IS NOT NULL AND p_club_id<>v_t.club_id THEN
   RAISE EXCEPTION 'diamond_purchase_arena_mismatch' USING ERRCODE='22023';
 END IF;
 IF v_t.max_players IS NULL OR p_seat_number>v_t.max_players THEN
   RAISE EXCEPTION 'TABLE_SIZE: invalid Diamond seat' USING ERRCODE='22023';
 END IF;
 IF EXISTS(SELECT 1 FROM public.blacklists WHERE user_id=p_user_id
     AND club_id=v_t.club_id AND (expires_at IS NULL OR expires_at>now())) THEN
   RAISE EXCEPTION 'Banned from this club' USING ERRCODE='42501';
 END IF;
 IF coalesce(v_t.is_vip_only,false) AND NOT EXISTS(
    SELECT 1 FROM public.profiles p WHERE p.id=p_user_id AND p.is_vip IS TRUE
      AND (p.vip_expires_at IS NULL OR p.vip_expires_at>now())) THEN
   RAISE EXCEPTION 'VIP_ONLY: this table requires VIP membership' USING ERRCODE='42501';
 END IF;
 IF EXISTS(SELECT 1 FROM public.table_seats WHERE table_id=p_table_id AND left_at IS NULL
           AND (user_id=p_user_id OR seat_number=p_seat_number)) THEN
   RAISE EXCEPTION 'Diamond seat or player is already seated' USING ERRCODE='23505';
 END IF;
 SELECT count(*) INTO v_taken FROM public.table_seats
   WHERE table_id=p_table_id AND left_at IS NULL;
 SELECT count(*) INTO v_holds FROM public.table_waitlist
   WHERE table_id=p_table_id AND status='notified' AND user_id<>p_user_id
     AND coalesce(hold_expires_at,notified_at+interval '60 seconds')>now();
 IF v_taken>=v_t.max_players OR v_taken+v_holds>=v_t.max_players THEN
   RAISE EXCEPTION 'SEAT_RESERVED: table capacity is taken or held' USING ERRCODE='55000';
 END IF;
 IF (SELECT count(*) FROM public.table_seats s JOIN public.tables t ON t.id=s.table_id
     WHERE s.user_id=p_user_id AND s.left_at IS NULL AND t.tournament_id IS NULL
       AND t.status NOT IN ('closed','deleted'))>=4 THEN
   RAISE EXCEPTION 'TABLE_CAP_REACHED: already seated at four cash tables' USING ERRCODE='55000';
 END IF;

 v_custody:=public.fn_poker_diamond_reserve(p_user_id,'cash_seat',p_table_id,
   'seat:'||v_seat_id,p_amount,p_idempotency_key);
 PERFORM set_config('app.money_path','atomic_table_buyin',true);
 DELETE FROM public.table_seats WHERE table_id=p_table_id
   AND seat_number=p_seat_number AND left_at IS NOT NULL;
 INSERT INTO public.table_seats(id,table_id,seat_number,user_id,stack,status,auto_rebuy,club_id)
   VALUES(v_seat_id,p_table_id,p_seat_number,p_user_id,p_amount,'active',false,v_t.club_id);
 -- The after-insert binder sees the final occupancy stamped by the shared trigger.
 IF NOT EXISTS(SELECT 1 FROM public.poker_diamond_custody c
     JOIN public.table_seats s ON s.id=c.seat_id AND s.joined_at=c.seat_joined_at
       AND s.occupancy_id=c.occupancy_id
     WHERE c.id=(v_custody->>'custody_id')::uuid AND c.state='active'
       AND s.id=v_seat_id AND s.left_at IS NULL AND s.stack=c.balance) THEN
   RAISE EXCEPTION 'diamond_seat_custody_binding_failed' USING ERRCODE='23514';
 END IF;
 UPDATE public.table_waitlist SET status='seated'
   WHERE table_id=p_table_id AND user_id=p_user_id AND status IN ('waiting','notified');
 UPDATE public.tables SET current_players=(
   SELECT count(*) FROM public.table_seats WHERE table_id=p_table_id AND left_at IS NULL)
   WHERE id=p_table_id;
END $$;


ALTER FUNCTION public.fn_poker_diamond_buyin(p_user_id uuid, p_table_id uuid, p_seat_number integer, p_amount numeric, p_auto_rebuy boolean, p_club_id uuid, p_idempotency_key uuid) OWNER TO postgres;

--
-- TOC entry 8259 (class 1255 OID 72776525)
-- Name: fn_poker_diamond_cancel_tournament(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_poker_diamond_cancel_tournament(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_t public.tournaments%ROWTYPE; v_receipt jsonb; v_replay boolean; v_audit uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE='28000';
  END IF;
  IF NOT public.fn_is_platform_admin() THEN
    RAISE EXCEPTION 'diamond_tournament_staff_only' USING ERRCODE='42501';
  END IF;
  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION 'diamond_staff_session_required' USING ERRCODE='28000';
  END IF;
  IF p_tournament_id IS NULL THEN
    RAISE EXCEPTION 'Tournament id is required' USING ERRCODE='22004';
  END IF;
  PERFORM public.fn_ca_lock_settlement_lane_global();
  SELECT t.* INTO v_t FROM public.tournaments t WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND OR NOT public.fn_poker_diamond_tournament(p_tournament_id) THEN
    RAISE EXCEPTION 'diamond_tournament_not_found' USING ERRCODE='P0002';
  END IF;
  v_replay := EXISTS (SELECT 1 FROM public.tournament_cancellation_receipts h WHERE h.tournament_id=p_tournament_id);
  PERFORM set_config('app.poker_diamond_staff_cancel', p_tournament_id::text, true);
  PERFORM set_config('app.managed_game_lifecycle', 'on', true);
  v_receipt := public.fn_poker_diamond_tournament_cancel(p_tournament_id, v_actor);
  PERFORM set_config('app.managed_game_lifecycle', '', true);
  PERFORM set_config('app.poker_diamond_staff_cancel', '', true);
  IF NOT v_replay THEN
    v_audit := public.fn_poker_diamond_staff_audit('diamond.tournament_cancel', 'diamond_tournament', p_tournament_id,
      to_jsonb(v_t), (SELECT to_jsonb(t) FROM public.tournaments t WHERE t.id=p_tournament_id),
      jsonb_build_object('door', 'fn_poker_diamond_cancel_tournament',
        'refunded_count', v_receipt->'refunded_count', 'total_refunded', v_receipt->'total_refunded',
        'fees_reversed', v_receipt->'fees_reversed', 'closed_table_count', v_receipt->'closed_table_count',
        'released_seat_count', v_receipt->'released_seat_count'));
  END IF;
  RETURN v_receipt || jsonb_build_object('audit_id', v_audit);
END $$;


ALTER FUNCTION public.fn_poker_diamond_cancel_tournament(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 7704 (class 1255 OID 28663350)
-- Name: fn_poker_diamond_cash_variant(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_poker_diamond_cash_variant(p_variant text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  /* NULL-SAFE ON PURPOSE. `NULL IN (...)` is NULL, not false, so without the
     first clause an unset `game_variant` made the whole plain-cash rule return
     NULL rather than false: a row that is neither admitted nor refused. Every
     caller today happens to treat unknown as refusal, which is exactly the
     kind of accident that holds until one of them writes `IF fn(...) = false`.
     An unset game is not a game. */
  SELECT p_variant IS NOT NULL
     AND p_variant IN ('nlh','plo4','plo5','plo6','plo8','pineapple','short_deck','flh','flo8');
$$;


ALTER FUNCTION public.fn_poker_diamond_cash_variant(p_variant text) OWNER TO postgres;

