--
-- TOC entry 5429 (class 1255 OID 155890947)
-- Name: fn_poker_diamond_move_custody(public.table_seats, public.table_seats, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_poker_diamond_move_custody(p_source public.table_seats, p_destination public.table_seats, p_game_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE c public.poker_diamond_custody%ROWTYPE; n integer;
BEGIN
 IF NOT coalesce(public.fn_caller_is_engine(),false) THEN
  RAISE EXCEPTION 'Engine authority required' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tables t JOIN public.clubs a ON a.id=t.club_id
   WHERE t.id=p_source.table_id AND a.asset='diamonds') THEN RETURN; END IF;
 IF p_source.user_id IS DISTINCT FROM p_destination.user_id
   OR p_source.stack IS DISTINCT FROM p_destination.stack
   OR p_source.occupancy_id=p_destination.occupancy_id
   OR NOT EXISTS(SELECT 1 FROM public.tables s JOIN public.tables d ON d.id=p_destination.table_id
      JOIN public.cash_games g ON g.id=p_game_id JOIN public.clubs a ON a.id=g.club_id
     WHERE s.id=p_source.table_id AND s.cluster_id=g.id AND d.cluster_id=g.id
       AND s.club_id=g.club_id AND d.club_id=g.club_id AND g.must_move
       AND a.asset='diamonds' AND a.is_platform AND a.union_id IS NULL
       AND s.union_id IS NULL AND d.union_id IS NULL AND g.union_id IS NULL
       AND s.tournament_id IS NULL AND d.tournament_id IS NULL)
 THEN RAISE EXCEPTION 'diamond_move_scope_mismatch' USING ERRCODE='23514'; END IF;
 SELECT * INTO c FROM public.poker_diamond_custody
 WHERE seat_id=p_source.id AND occupancy_id=p_source.occupancy_id
   AND seat_joined_at=p_source.joined_at AND user_id=p_source.user_id
   AND target_id=p_source.table_id AND arena_id=p_source.club_id
   AND purpose='cash_seat' AND state='active' AND balance=p_source.stack FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'diamond_move_custody_missing' USING ERRCODE='23514'; END IF;
 UPDATE public.poker_diamond_custody SET target_id=p_destination.table_id,
  seat_id=p_destination.id,seat_joined_at=p_destination.joined_at,
  occupancy_id=p_destination.occupancy_id WHERE id=c.id AND state='active';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION 'diamond_move_custody_not_retargeted' USING ERRCODE='23514'; END IF;
END;
$$;


ALTER FUNCTION public.fn_poker_diamond_move_custody(p_source public.table_seats, p_destination public.table_seats, p_game_id uuid) OWNER TO postgres;

--
-- TOC entry 8275 (class 1255 OID 28663354)
-- Name: fn_poker_diamond_open_cash_table(text, integer, integer, integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_poker_diamond_open_cash_table(p_name text, p_small_blind integer, p_big_blind integer, p_min_buy_in integer, p_max_buy_in integer, p_max_players integer DEFAULT 6, p_game_variant text DEFAULT 'nlh'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_arena uuid;
  v_table uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '28000';
  END IF;

  -- Platform staff only. The estate already has one answer to this question and
  -- it is fn_is_platform_admin(); never re-derive a role list.
  IF NOT public.fn_is_platform_admin() THEN
    RAISE EXCEPTION 'diamond_table_staff_only' USING ERRCODE = '42501';
  END IF;
  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION 'diamond_staff_session_required' USING ERRCODE = '28000';
  END IF;

  SELECT c.id INTO v_arena
  FROM public.clubs c
  WHERE c.asset = 'diamonds' AND c.is_platform = true AND c.union_id IS NULL
  LIMIT 1;

  IF v_arena IS NULL THEN
    RAISE EXCEPTION 'diamond_arena_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_small_blind IS NULL OR p_big_blind IS NULL
     OR p_min_buy_in IS NULL OR p_max_buy_in IS NULL
     OR p_small_blind <= 0 OR p_big_blind <= 0
     OR p_min_buy_in <= 0 OR p_max_buy_in <= 0
     OR p_small_blind > p_big_blind
     OR p_min_buy_in > p_max_buy_in
     OR p_big_blind > p_min_buy_in
     OR p_max_buy_in > 2147483647
  THEN
    RAISE EXCEPTION 'diamond_table_requires_whole_positive_stakes' USING ERRCODE = '22023';
  END IF;

  IF p_max_players IS NULL OR p_max_players < 2 OR p_max_players > 10 THEN
    RAISE EXCEPTION 'diamond_table_requires_a_real_seat_count' USING ERRCODE = '22023';
  END IF;

  -- The door names the game, and refuses one this arena does not deal rather
  -- than opening a table the engine would then refuse to load.
  IF p_game_variant IS NULL OR NOT public.fn_poker_diamond_cash_variant(p_game_variant) THEN
    RAISE EXCEPTION 'diamond_table_requires_a_supported_game' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.tables (
    club_id, union_id, tournament_id, cluster_id,
    name, game_type, game_variant, status, max_players,
    small_blind, big_blind, ante,
    min_buy_in, max_buy_in,
    rake_percent, rake_cap_bb, bbj_percent,
    is_template, insurance_enabled, bomb_pot_enabled,
    run_it_twice, allow_run_it_twice, run_it_twice_enabled,
    straddle_enabled, auto_utg_straddle, voluntary_straddle,
    seven_deuce_enabled, nit_game, all_in_or_fold, pineapple_holdem, cap_enabled,
    created_by
  ) VALUES (
    v_arena, NULL, NULL, NULL,
    coalesce(nullif(btrim(p_name), ''), 'Diamond Cash'), 'cash', p_game_variant,
    'waiting', p_max_players,
    p_small_blind, p_big_blind, 0,
    p_min_buy_in, p_max_buy_in,
    0, 0, 0,
    false, false, false,
    false, false, false,
    false, false, false,
    false, false, false, false, false,
    v_actor
  )
  RETURNING id INTO v_table;
  -- The first ladder adoption is performed only after the engine is live.
  -- Until then the existing staff door retains its unclustered safe shape.
  IF EXISTS(SELECT 1 FROM public.cash_games WHERE club_id=v_arena AND must_move) THEN
    PERFORM public.fn_poker_diamond_attach_cash_game(v_table);
  END IF;

  -- The row this door just wrote must be one the engine will admit. A door
  -- that can open a table nobody can sit at is worse than no door.
  IF NOT EXISTS (
    SELECT 1 FROM public.tables t
     WHERE t.id = v_table AND public.fn_poker_diamond_plain_cash_table(t)
  ) THEN
    RAISE EXCEPTION 'diamond_table_would_not_be_admitted' USING ERRCODE = '23514';
  END IF;

  -- DIAMOND PHASE 10: on the record - the operator on the row (created_by,
  -- above) and one audit row holding the table as it was opened.
  PERFORM public.fn_poker_diamond_staff_audit('diamond.table_open', 'diamond_table', v_table, NULL,
    (SELECT to_jsonb(t) FROM public.tables t WHERE t.id = v_table),
    jsonb_build_object('door', 'fn_poker_diamond_open_cash_table'));

  RETURN v_table;
END;
$$;


