--
-- TOC entry 4016 (class 1255 OID 155890931)
-- Name: fn_poker_diamond_project_cluster(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_poker_diamond_project_cluster(p_game_id uuid, p_table_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE g public.cash_games%ROWTYPE; cfg public.tables%ROWTYPE; n integer;
BEGIN
 SELECT cg.* INTO g FROM public.cash_games cg JOIN public.clubs c ON c.id=cg.club_id
 WHERE cg.id=p_game_id AND c.asset='diamonds' AND c.is_platform
   AND c.union_id IS NULL AND cg.union_id IS NULL AND cg.must_move
   AND NOT cg.lightning_enabled AND cg.cluster_mode IN ('must_move','paused') FOR UPDATE OF cg;
 IF NOT FOUND THEN RAISE EXCEPTION 'diamond_cluster_scope_required' USING ERRCODE='23514'; END IF;
 IF jsonb_typeof(g.ruleset_snapshot->'diamond_table') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'diamond_cluster_projection_required' USING ERRCODE='23514';
 END IF;
 cfg:=jsonb_populate_record(NULL::public.tables,g.ruleset_snapshot->'diamond_table');
 IF cfg.min_buy_in IS NULL OR cfg.max_buy_in IS NULL
   OR cfg.min_buy_in<g.bb OR cfg.max_buy_in<cfg.min_buy_in
   OR cfg.min_buy_in<>trunc(cfg.min_buy_in) OR cfg.max_buy_in<>trunc(cfg.max_buy_in)
   OR cfg.max_buy_in>2147483647 OR g.sb<>trunc(g.sb) OR g.bb<>trunc(g.bb)
   OR g.sb<=0 OR g.bb<g.sb OR g.handedness NOT BETWEEN 2 AND 9
   OR cfg.rake_percent IS DISTINCT FROM 0 OR cfg.rake_cap_bb IS DISTINCT FROM 0
   OR cfg.bbj_percent IS DISTINCT FROM 0 OR cfg.run_it_twice IS NULL
   OR cfg.allow_run_it_twice IS NULL OR coalesce(cfg.insurance_enabled,false)
   OR coalesce(cfg.seven_deuce_enabled,false) OR coalesce(cfg.nit_game,false)
   OR coalesce(cfg.all_in_or_fold,false) OR coalesce(cfg.pineapple_holdem,false)
   OR coalesce(cfg.cap_enabled,false)
   OR NOT public.fn_poker_diamond_cash_variant(g.variant)
   OR coalesce(cfg.ante,0)<0 OR coalesce(cfg.ante,0)<>trunc(coalesce(cfg.ante,0))
   OR (coalesce(cfg.bomb_pot_enabled,false) AND (
      lower(coalesce(cfg.bomb_pot_variant,'')) NOT IN ('',g.variant)
      OR coalesce(cfg.bomb_pot_ante_fixed,g.bb*coalesce(cfg.bomb_pot_ante_multiplier,2))<=0
      OR coalesce(cfg.bomb_pot_ante_fixed,g.bb*coalesce(cfg.bomb_pot_ante_multiplier,2))<>
         trunc(coalesce(cfg.bomb_pot_ante_fixed,g.bb*coalesce(cfg.bomb_pot_ante_multiplier,2)))
   )) THEN
  RAISE EXCEPTION 'diamond_cluster_projection_invalid' USING ERRCODE='23514';
 END IF;
 UPDATE public.tables t SET
  small_blind=g.sb,big_blind=g.bb,game_variant=g.variant,
  min_buy_in=cfg.min_buy_in,max_buy_in=cfg.max_buy_in,
  max_players=greatest(g.handedness,coalesce((SELECT max(s.seat_number)
    FROM public.table_seats s WHERE s.table_id=t.id AND s.left_at IS NULL),0)),
  rake_percent=0,rake_cap_bb=0,bbj_percent=0,
  insurance_enabled=false,seven_deuce_enabled=false,nit_game=false,
  all_in_or_fold=false,pineapple_holdem=false,cap_enabled=false,
  run_it_twice=cfg.run_it_twice,allow_run_it_twice=cfg.allow_run_it_twice,
  run_it_twice_enabled=coalesce(cfg.run_it_twice_enabled,false),run_it_mode=cfg.run_it_mode,
  straddle_enabled=coalesce(cfg.straddle_enabled,false),
  auto_utg_straddle=coalesce(cfg.auto_utg_straddle,false),voluntary_straddle=coalesce(cfg.voluntary_straddle,false),
  ante=coalesce(cfg.ante,0),ante_enabled=coalesce(cfg.ante_enabled,false),
  big_blind_ante_enabled=coalesce(cfg.big_blind_ante_enabled,false),
  bomb_pot_enabled=coalesce(cfg.bomb_pot_enabled,false),bomb_pot_variant=cfg.bomb_pot_variant,
  bomb_pot_ante_fixed=cfg.bomb_pot_ante_fixed,bomb_pot_ante_multiplier=cfg.bomb_pot_ante_multiplier,
  bomb_pot_board_count=cfg.bomb_pot_board_count,bomb_pot_double_board=cfg.bomb_pot_double_board,
  bomb_pot_trigger_mode=cfg.bomb_pot_trigger_mode,bomb_pot_frequency=cfg.bomb_pot_frequency,
  bomb_pot_interval_seconds=cfg.bomb_pot_interval_seconds,
  action_time_seconds=coalesce(cfg.action_time_seconds,15),
  auto_extension=false,auto_restart=false,auto_create_table=false
 WHERE t.cluster_id=g.id AND t.lifecycle<>'closed' AND NOT coalesce(t.is_deleted,false)
   AND (p_table_id IS NULL OR t.id=p_table_id)
   AND (t.small_blind IS DISTINCT FROM g.sb OR t.big_blind IS DISTINCT FROM g.bb
     OR t.game_variant IS DISTINCT FROM g.variant
     OR t.max_players IS DISTINCT FROM greatest(g.handedness,coalesce((SELECT max(s.seat_number)
       FROM public.table_seats s WHERE s.table_id=t.id AND s.left_at IS NULL),0))
     OR EXISTS(SELECT 1 FROM jsonb_each(g.ruleset_snapshot->'diamond_table') setting
       WHERE to_jsonb(t)->setting.key IS DISTINCT FROM setting.value));
 GET DIAGNOSTICS n=ROW_COUNT;
 IF EXISTS(SELECT 1 FROM public.tables t WHERE t.cluster_id=g.id
   AND t.lifecycle<>'closed' AND NOT coalesce(t.is_deleted,false)
   -- A table whose status is closed deals nothing, so it cannot break the
   -- plain-cash rule. An operator close leaves a cluster table status
   -- 'closed' with lifecycle 'live' until its resume, and counting it made
   -- this raise on every pass of the game for the whole park (2026-10-15,
   -- migration 20261015181551). It is judged again the moment it reopens.
   AND t.status IS DISTINCT FROM 'closed'
   AND NOT public.fn_poker_diamond_plain_cash_table(t)) THEN
  RAISE EXCEPTION 'diamond_cluster_table_not_admitted' USING ERRCODE='23514';
 END IF;
 RETURN n;
END;
$$;


ALTER FUNCTION public.fn_poker_diamond_project_cluster(p_game_id uuid, p_table_id uuid) OWNER TO postgres;

--
-- TOC entry 5247 (class 1255 OID 72110829)
-- Name: fn_poker_diamond_prove_played_spin_launch_recovery(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_poker_diamond_prove_played_spin_launch_recovery(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET row_security TO 'off'
    SET statement_timeout TO '10s'
    AS $$
-- The Diamond arm of fn_prove_played_spin_launch_recovery (Diamond Phase 9).
-- The chip rule, word for word, for the field, the felt, the vacated seat and
-- the hand; the money evidence read from the records a Diamond Spin keeps.
WITH contract AS (
  SELECT t.id,
         t.status::text AS status,
         lower(COALESCE(t.variant, '')) AS variant,
         upper(COALESCE(t.tournament_type, '')) AS tournament_type,
         t.max_players,
         t.buy_in_amount AS buy_in,
         t.starting_chips
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
     AND public.fn_poker_diamond_tournament(t.id)
), roster AS (
  SELECT count(*) AS roster_count,
         count(DISTINCT tp.user_id) AS roster_users,
         count(*) FILTER (WHERE tp.status = 'playing') AS active_players,
         count(*) FILTER (WHERE tp.status = 'playing' AND tp.chips > 0)
           AS positive_active_players,
         count(*) FILTER (WHERE tp.status = 'eliminated') AS eliminated_players,
         count(*) FILTER (WHERE tp.status NOT IN ('playing', 'eliminated')) AS other_players,
         count(*) FILTER (WHERE tp.chips IS NULL OR tp.chips < 0) AS invalid_stacks,
         count(*) FILTER (WHERE tp.status = 'eliminated' AND tp.chips = 0)
           AS zero_stack_eliminations,
         COALESCE(sum(tp.chips), 0) AS roster_chips,
         COALESCE(
           array_agg(tp.user_id ORDER BY tp.user_id)
             FILTER (WHERE tp.user_id IS NOT NULL),
           ARRAY[]::uuid[]
         ) AS original_player_ids,
         COALESCE(
           array_agg(tp.user_id ORDER BY tp.user_id)
             FILTER (WHERE tp.status = 'playing'),
           ARRAY[]::uuid[]
         ) AS active_player_ids
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
), entitlements AS (
  -- A Diamond entry's immutable record is its entry row in the Diamond
  -- tournament ledger, where a chip entry's is its refund entitlement.
  SELECT count(l.id) AS entitlement_count,
         count(DISTINCT l.user_id) AS entitlement_users,
         count(DISTINCT l.user_id) FILTER (
           WHERE EXISTS (
             SELECT 1
               FROM public.tournament_players tp
              WHERE tp.tournament_id = p_tournament_id
                AND tp.user_id = l.user_id
           )
         ) AS roster_entitlement_users,
         min(l.amount) AS min_gross,
         max(l.amount) AS max_gross,
         round(COALESCE(sum(l.amount), 0), 2) AS gross_total
    FROM public.poker_diamond_tournament_ledger l
   WHERE l.tournament_id = p_tournament_id
     AND l.kind = 'entry'
), payments AS (
  -- A Diamond entry is paid by the player's own reserve movement from the
  -- wallet into the event's custody, where a chip entry is paid by its wallet
  -- debit. Every entry custody the event ever held is read, released or not.
  SELECT count(m.request_id) AS payment_count,
         count(DISTINCT m.user_id) AS paid_users,
         count(DISTINCT m.user_id) FILTER (
           WHERE EXISTS (
             SELECT 1
               FROM public.tournament_players tp
              WHERE tp.tournament_id = p_tournament_id
                AND tp.user_id = m.user_id
           )
         ) AS roster_paid_users,
         min(m.amount) AS min_amount,
         max(m.amount) AS max_amount,
         round(COALESCE(sum(m.amount), 0), 2) AS payment_total
    FROM public.poker_diamond_custody c
    JOIN public.poker_diamond_movements m
      ON m.custody_id = c.id
     AND m.action = 'reserve'
     AND m.source_account = 'player:' || m.user_id::text
   WHERE c.purpose = 'tournament_entry'
     AND c.target_id = p_tournament_id
), charge_evidence AS (
  -- Each entry row names its player's own active entry custody for this
  -- event, keyed to its registration, and the reserve movement and wallet
  -- journal that paid it in, where a chip entitlement names its source
  -- ledger leg.
  SELECT count(l.id) AS source_charge_count,
         count(l.id) FILTER (
           WHERE c.user_id = l.user_id
             AND c.purpose = 'tournament_entry'
             AND c.target_id = l.tournament_id
             AND c.state = 'active'
             AND c.entry_key = 'entry:' || l.registration_id::text
             AND l.prize_part = l.amount
             AND l.bounty_part = 0
             AND l.fee_part = 0
             AND EXISTS (
               SELECT 1
                 FROM public.tournament_players tp
                WHERE tp.id = l.registration_id
                  AND tp.tournament_id = l.tournament_id
                  AND tp.user_id = l.user_id
             )
             AND EXISTS (
               SELECT 1
                 FROM public.poker_diamond_movements m
                WHERE m.custody_id = c.id
                  AND m.action = 'reserve'
                  AND m.user_id = l.user_id
                  AND m.source_account = 'player:' || l.user_id::text
                  AND m.amount = l.amount
                  AND m.wallet_journal_id = l.wallet_journal_id
             )
             AND EXISTS (
               SELECT 1
                 FROM public.diamond_transactions j
                WHERE j.id = l.wallet_journal_id
                  AND j.user_id = l.user_id
                  AND j.amount = -l.amount
             )
         ) AS exact_source_charges
    FROM public.poker_diamond_tournament_ledger l
    LEFT JOIN public.poker_diamond_custody c ON c.id = l.custody_id
   WHERE l.tournament_id = p_tournament_id
     AND l.kind = 'entry'
), draw_evidence AS (
  -- The one committed Diamond draw, where a chip Spin has its reserve
  -- contribution and its jackpot draw.
  SELECT count(r.tournament_id) AS draw_count,
         min(r.created_at) AS draw_created_at,
         min(CASE WHEN jsonb_typeof(r.entrants) = 'array'
                  THEN jsonb_array_length(r.entrants) END) AS draw_seats,
         min(CASE WHEN jsonb_typeof(r.receipt->'buy_in') = 'number'
                  THEN (r.receipt->>'buy_in')::numeric END) AS draw_buy_in,
         min(CASE WHEN jsonb_typeof(r.receipt->'multiplier') = 'number'
                  THEN (r.receipt->>'multiplier')::numeric END) AS draw_multiplier,
         min(CASE WHEN jsonb_typeof(r.receipt->'prize_pool') = 'number'
                  THEN (r.receipt->>'prize_pool')::numeric END) AS draw_pool
    FROM public.spin_draw_receipts r
   WHERE r.tournament_id = p_tournament_id
), draw_proof AS (
  -- The draw read back against the tournament row, its ledger legs and the
  -- source's register rows, where a chip Spin has its pool and journals.
  SELECT COALESCE(
           (public.fn_poker_diamond_spin_draw_proof(p_tournament_id, NULL)->>'ok')::boolean,
           false
         ) AS draw_proven
), table_evidence AS (
  SELECT count(t.id) AS table_count,
         count(t.id) FILTER (WHERE t.status IN ('running', 'waiting')) AS open_tables,
         (array_agg(t.id ORDER BY t.created_at, t.id)
           FILTER (WHERE t.status IN ('running', 'waiting')))[1] AS table_id,
         min(t.current_players) FILTER (WHERE t.status IN ('running', 'waiting'))
           AS current_players,
         min(t.max_players) FILTER (WHERE t.status IN ('running', 'waiting'))
           AS table_capacity
    FROM public.tables t
   WHERE t.tournament_id = p_tournament_id
), live_seats AS (
  SELECT count(s.id) AS live_seats,
         count(DISTINCT s.user_id) AS live_users,
         count(DISTINCT (s.table_id, s.seat_number)) AS live_coordinates,
         count(DISTINCT s.table_id) AS live_tables,
         count(s.id) FILTER (
           WHERE s.stack IS NULL
              OR s.stack::text IN ('NaN', 'Infinity', '-Infinity')
              OR s.stack < 0
         ) AS invalid_live_stacks,
         count(s.id) FILTER (WHERE s.stack > 0) AS positive_live_seats,
         count(s.id) FILTER (
           WHERE EXISTS (
             SELECT 1
               FROM public.tournament_players tp
              WHERE tp.tournament_id = p_tournament_id
                AND tp.user_id = s.user_id
                AND tp.status = 'playing'
                AND tp.table_id = s.table_id
                AND tp.seat_number = s.seat_number
                AND tp.chips IS NOT DISTINCT FROM s.stack
           )
         ) AS matching_active_seats,
         COALESCE(sum(s.stack), 0) AS seat_chips
    FROM public.table_seats s
    JOIN public.tables t ON t.id = s.table_id
   WHERE t.tournament_id = p_tournament_id
     AND s.left_at IS NULL
), vacated_seat AS (
  SELECT count(DISTINCT tp.user_id) AS vacated_eliminated_players
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND tp.status = 'eliminated'
     AND EXISTS (
       SELECT 1
         FROM public.table_seats s
         JOIN public.tables t ON t.id = s.table_id
        WHERE t.tournament_id = p_tournament_id
          AND s.user_id = tp.user_id
          AND s.left_at IS NOT NULL
     )
), hands AS (
  SELECT count(h.id) FILTER (WHERE h.created_at >= r.draw_created_at) AS hand_count
    FROM draw_evidence r
    LEFT JOIN public.hand_history h
      ON h.tournament_id = p_tournament_id
    LEFT JOIN public.tables t
      ON t.id = h.table_id
     AND t.tournament_id = p_tournament_id
   WHERE h.id IS NULL OR t.id IS NOT NULL
), escrow AS (
  -- The Diamond banks and the custody behind them hold exactly the drawn
  -- pool, where a chip Spin's escrow holds it.
  SELECT e.prize_balance,
         e.bounty_balance,
         e.fee_balance,
         public.fn_poker_diamond_tournament_custody(p_tournament_id) AS custody_total
    FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id) e
), facts AS (
  SELECT c.*,
         r.*,
         e.*,
         pay.*,
         charge.*,
         d.*,
         dp.*,
         te.*,
         ls.*,
         vs.*,
         h.*,
         esc.*,
         (c.starting_chips * 3)::numeric AS funding_floor
    FROM (SELECT 1) seed
    LEFT JOIN contract c ON true
    CROSS JOIN roster r
    CROSS JOIN entitlements e
    CROSS JOIN payments pay
    CROSS JOIN charge_evidence charge
    CROSS JOIN draw_evidence d
    CROSS JOIN draw_proof dp
    CROSS JOIN table_evidence te
    CROSS JOIN live_seats ls
    CROSS JOIN vacated_seat vs
    CROSS JOIN hands h
    CROSS JOIN escrow esc
), verdict AS (
  SELECT f.*,
         (f.id IS NOT NULL
          AND f.status = 'REGISTERING'
          AND (f.variant = 'spin' OR f.tournament_type = 'SPIN')
          AND f.variant <> 'sng'
          AND f.tournament_type <> 'SNG'
          AND f.max_players = 3
          AND f.buy_in IS NOT NULL
          AND f.buy_in::text NOT IN ('NaN', 'Infinity', '-Infinity')
          AND f.buy_in > 0
          AND f.starting_chips IS NOT NULL
          AND f.starting_chips > 0
          AND f.roster_count = 3
          AND f.roster_users = 3
          AND f.active_players = 2
          AND f.positive_active_players = 2
          AND f.eliminated_players = 1
          AND f.other_players = 0
          AND f.invalid_stacks = 0
          AND f.zero_stack_eliminations = 1
          AND f.roster_chips = f.funding_floor
          AND f.entitlement_count = 3
          AND f.entitlement_users = 3
          AND f.roster_entitlement_users = 3
          AND f.min_gross = f.buy_in
          AND f.max_gross = f.buy_in
          AND f.gross_total = round(f.buy_in * 3, 2)
          AND f.payment_count = 3
          AND f.paid_users = 3
          AND f.roster_paid_users = 3
          AND f.min_amount = f.buy_in
          AND f.max_amount = f.buy_in
          AND f.payment_total = round(f.buy_in * 3, 2)
          AND f.source_charge_count = 3
          AND f.exact_source_charges = 3
          AND f.draw_count = 1
          AND f.draw_proven
          AND f.draw_pool IS NOT NULL
          AND f.draw_pool = round(f.buy_in * f.draw_multiplier, 2)
          AND f.draw_buy_in = f.buy_in
          AND f.draw_seats = 3
          AND f.draw_multiplier > 0
          AND f.custody_total = f.draw_pool
          AND f.bounty_balance = 0
          AND f.fee_balance = 0
          AND f.prize_balance = f.draw_pool
          AND f.table_count = 1
          AND f.open_tables = 1
          AND f.current_players = 2
          AND f.table_capacity = 3
          AND f.live_seats = 2
          AND f.live_users = 2
          AND f.live_coordinates = 2
          AND f.live_tables = 1
          AND f.invalid_live_stacks = 0
          AND f.positive_live_seats = 2
          AND f.matching_active_seats = 2
          AND f.seat_chips = f.funding_floor
          AND f.seat_chips = f.roster_chips
          AND f.vacated_eliminated_players = 1
          AND f.hand_count >= 1) AS ok
    FROM facts f
)
SELECT CASE WHEN v.ok THEN
  jsonb_build_object(
    'ok', true,
    'recovery_mode', 'played_vacated_spin',
    'tournament_id', p_tournament_id,
    'original_field', 3,
    'active_field', 2,
    'eliminated_players', v.eliminated_players,
    'paid_users', v.paid_users,
    'entitlement_users', v.entitlement_users,
    'live_seats', v.live_seats,
    'hand_count', v.hand_count,
    'funding_floor', v.funding_floor,
    'roster_chips', v.roster_chips,
    'seat_chips', v.seat_chips,
    'original_player_ids', to_jsonb(v.original_player_ids),
    'active_player_ids', to_jsonb(v.active_player_ids)
  )
ELSE
  jsonb_build_object(
    'ok', false,
    'reason', 'played_spin_launch_recovery_unproven',
    'tournament_id', p_tournament_id
  )
END
  FROM verdict v;
$$;


ALTER FUNCTION public.fn_poker_diamond_prove_played_spin_launch_recovery(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 5462 (class 1255 OID 25277313)
-- Name: fn_poker_diamond_release(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_poker_diamond_release(p_custody_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_owner uuid;
  v_c public.poker_diamond_custody%ROWTYPE;
  v_prev public.poker_diamond_movements%ROWTYPE;
  v_request jsonb;
  v_credit jsonb;
  v_receipt jsonb;
  v_lot record;
  v_debt_journal uuid;
BEGIN
  IF p_custody_id IS NULL OR p_request_id IS NULL THEN
    RAISE EXCEPTION 'invalid_diamond_release' USING ERRCODE = '22023';
  END IF;

  SELECT user_id INTO v_owner
    FROM public.poker_diamond_custody
   WHERE id = p_custody_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'diamond_custody_not_found';
  END IF;

  -- The wallet always locks before its custody, exactly as reserve does.
  -- NO KEY UPDATE, not UPDATE (20261021234940): it still serializes every
  -- writer of this wallet (FOR UPDATE, NO KEY UPDATE and UPDATE all
  -- refuse it), and it no longer refuses the FOR KEY SHARE that a
  -- foreign-key check from a row pointing at this profile takes.
  PERFORM id FROM public.profiles WHERE id = v_owner FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile_not_found';
  END IF;
  SELECT * INTO v_c
    FROM public.poker_diamond_custody
   WHERE id = p_custody_id
   FOR UPDATE;

  v_request := jsonb_build_object(
    'action', 'release',
    'custody_id', p_custody_id,
    'user_id', v_owner
  );

  SELECT * INTO v_prev
    FROM public.poker_diamond_movements
   WHERE request_id = p_request_id;
  IF FOUND THEN
    IF v_prev.request <> v_request THEN
      RAISE EXCEPTION 'idempotency_payload_mismatch';
    END IF;
    RETURN v_prev.receipt;
  END IF;

  IF v_c.state = 'released' THEN
    RAISE EXCEPTION 'diamond_custody_already_released';
  END IF;
  -- A DIAMOND TOURNAMENT ENTRY GOES HOME ONLY THROUGH ITS REFUND AUTHORITY
  -- (Phase 8). fn_poker_diamond_tournament_refund names this row in a
  -- transaction-local setting for the one call it makes; any other caller,
  -- service role included, is refused. An entry in play is never releasable.
  IF v_c.purpose = 'tournament_entry'
     AND current_setting('app.poker_diamond_tournament_release', true) IS DISTINCT FROM p_custody_id::text THEN
    RAISE EXCEPTION 'diamond_tournament_entry_requires_refund_authority' USING ERRCODE = '42501';
  END IF;
  -- An ACTIVE tournament entry (activated by the entry door, as the seat
  -- guards P0810-P0812 require) is released whole by its refund authority;
  -- the settlement test below is the cash seat's and stays the cash seat's.
  IF v_c.state <> 'reserved' AND v_c.purpose <> 'tournament_entry' THEN
    IF v_c.state <> 'active' OR v_c.purpose <> 'cash_seat'
       OR v_c.occupancy_id IS NULL OR NOT EXISTS (
         SELECT 1 FROM public.table_seats s
          WHERE s.id=v_c.seat_id AND s.joined_at=v_c.seat_joined_at
            AND s.occupancy_id=v_c.occupancy_id AND s.user_id=v_c.user_id
            AND s.table_id=v_c.target_id AND s.left_at IS NOT NULL
            AND s.stack=v_c.balance) THEN
      RAISE EXCEPTION 'diamond_custody_requires_settlement';
    END IF;
  END IF;

  FOR v_lot IN
    SELECT l.id, r.amount-r.consumed AS amount
      FROM public.poker_diamond_lot_reservations r
      JOIN public.diamond_purchase_lots l ON l.id = r.lot_id
     WHERE r.custody_id = p_custody_id
       AND r.released_at IS NULL
     ORDER BY l.created_at, l.id
     FOR UPDATE OF l
  LOOP
    UPDATE public.diamond_purchase_lots
       SET arena_reserved = arena_reserved - v_lot.amount
     WHERE id = v_lot.id;
  END LOOP;

  UPDATE public.poker_diamond_lot_reservations
     SET released_at = now()
   WHERE custody_id = p_custody_id
     AND released_at IS NULL;

  IF v_c.balance > 0 THEN
  v_credit := public.add_diamonds_to_balance(
    v_owner,
    v_c.balance::integer,
    'arena_withdraw',
    'Released Poker Arena reservation',
    'poker-release:' || p_custody_id || ':' || p_request_id
  );
  IF (v_credit->>'success')::boolean IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'diamond_release_credit_failed:%', v_credit->>'error';
  END IF;

  ELSE
    SELECT jsonb_build_object('success',true,'new_balance',diamonds,
      'debt_settled',0,'transaction_id',NULL) INTO v_credit
      FROM public.profiles WHERE id=v_owner;
  END IF;

  IF COALESCE((v_credit->>'debt_settled')::bigint, 0) > 0 THEN
    SELECT id INTO v_debt_journal
      FROM public.diamond_transactions
     WHERE user_id = v_owner
       AND reference_id = 'debt-settlement:' || (v_credit->>'transaction_id')
       AND type = 'debt_settlement'
       AND amount = -(v_credit->>'debt_settled')::bigint;
    IF v_debt_journal IS NULL THEN
      RAISE EXCEPTION 'diamond_debt_journal_missing';
    END IF;

    PERFORM public.fn_ca_register_diamond_journal_row(v_debt_journal);
    IF NOT EXISTS (
      SELECT 1
        FROM public.ca_mint_ledger
       WHERE diamond_tx_id = v_debt_journal
         AND action = 'burn'
         AND asset = 'diamonds'
         AND holder_type = 'player'
         AND holder_id = v_owner
         AND amount = (v_credit->>'debt_settled')::bigint
    ) THEN
      RAISE EXCEPTION 'diamond_debt_retirement_missing';
    END IF;
  END IF;

  UPDATE public.poker_diamond_custody
     SET balance = 0,
         state = 'released',
         released_at = now()
   WHERE id = p_custody_id;

  v_receipt := jsonb_build_object(
    'success', true,
    'custody_id', p_custody_id,
    'request_id', p_request_id,
    'amount', v_c.balance,
    'available_balance', (v_credit->>'new_balance')::bigint,
    'custody_balance', 0,
    'debt_settled', (v_credit->>'debt_settled')::bigint,
    'journal_id', v_credit->>'transaction_id'
  );

  INSERT INTO public.poker_diamond_movements(
    request_id, custody_id, user_id, action, amount,
    source_account, destination_account, wallet_journal_id, request, receipt
  ) VALUES (
    p_request_id, p_custody_id, v_owner, 'release', v_c.balance,
    'arena_custody:' || p_custody_id, 'player:' || v_owner,
    (v_credit->>'transaction_id')::uuid, v_request, v_receipt
  );

  RETURN v_receipt;
END;
$$;


ALTER FUNCTION public.fn_poker_diamond_release(p_custody_id uuid, p_request_id uuid) OWNER TO postgres;

