--
-- TOC entry 6982 (class 1255 OID 91640571)
-- Name: fn_prune_client_error_events(interval, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_prune_client_error_events(p_keep interval DEFAULT '14 days'::interval, p_batch integer DEFAULT 20000) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_deleted integer;
BEGIN
  DELETE FROM public.client_error_events
   WHERE id IN (
     SELECT id FROM public.client_error_events
      WHERE received_at < now() - greatest(coalesce(p_keep, interval '14 days'), interval '1 day')
      ORDER BY received_at
      LIMIT least(greatest(coalesce(p_batch, 20000), 1), 50000));
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


