-- Name: FUNCTION fn_prune_horse_adaptive_journal(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_prune_horse_adaptive_journal() IS 'One bounded isolated-journal retention pass:100completed jobs,100unreferenced batches,1000expired facts. Minimum32-day retention and independent30-day observation guard. No claim of a fully drained backlog or source completeness.';


--
-- TOC entry 5344 (class 1255 OID 30812787)
-- Name: fn_prune_horse_observation_captures(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_prune_horse_observation_captures() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    SET lock_timeout TO '2s'
    AS $$
DECLARE n integer; slices integer; keys text[];
BEGIN
  SELECT array_agg(request_key) INTO keys FROM (
    SELECT w.request_key FROM public.horse_observation_capture_work w
      WHERE ((w.state IN ('admitted','captured') AND w.admitted_at<clock_timestamp()-interval '32 days')
        OR (w.state='gap' AND NOT (w.state<>'gap' OR (w.reason='source_budget_exceeded' AND coalesce(w.slice_through_ms,w.through_ms)-coalesce(w.cursor_ms,w.from_ms)>1)) AND w.created_at<clock_timestamp()-interval '32 days'))
      ORDER BY coalesce(w.admitted_at,w.created_at),w.request_key LIMIT 100 FOR UPDATE SKIP LOCKED
  ) bounded;
  WITH candidates AS (
    SELECT s.request_key,s.lease_token FROM public.horse_observation_capture_receipts s
      WHERE s.request_key=ANY(keys) LIMIT 1000 FOR UPDATE SKIP LOCKED
  ) DELETE FROM public.horse_observation_capture_receipts s USING candidates c
      WHERE s.request_key=c.request_key AND s.lease_token=c.lease_token;
  GET DIAGNOSTICS slices=ROW_COUNT;
  DELETE FROM public.horse_observation_capture_work w WHERE w.request_key=ANY(keys)
    AND NOT EXISTS(SELECT 1 FROM public.horse_observation_capture_receipts s WHERE s.request_key=w.request_key);
  GET DIAGNOSTICS n=ROW_COUNT;
  RETURN jsonb_build_object('version',1,'status','pruned','requests',n,'sliceReceipts',slices);
END;
$$;


ALTER FUNCTION public.fn_prune_horse_observation_captures() OWNER TO postgres;

--
-- TOC entry 4404 (class 1255 OID 31043804)
-- Name: fn_prune_horse_observation_discovery(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_prune_horse_observation_discovery() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    SET lock_timeout TO '2s'
    AS $$
DECLARE key text; members integer:=0; segments integer:=0; epochs integer:=0;
BEGIN
  SELECT epoch_key INTO key FROM public.horse_observation_discovery_epochs
    WHERE state='discovered' AND finished_at<clock_timestamp()-interval '32 days'
    ORDER BY finished_at,epoch_key LIMIT 1 FOR UPDATE SKIP LOCKED;
  IF FOUND THEN
    WITH doomed AS (SELECT ctid FROM public.horse_observation_discovery_members WHERE epoch_key=key ORDER BY actor_id LIMIT 512 FOR UPDATE SKIP LOCKED)
    DELETE FROM public.horse_observation_discovery_members WHERE ctid IN(SELECT ctid FROM doomed);
    GET DIAGNOSTICS members=ROW_COUNT;
    WITH doomed AS (SELECT ctid FROM public.horse_observation_discovery_segments WHERE epoch_key=key ORDER BY from_ms LIMIT 128 FOR UPDATE SKIP LOCKED)
    DELETE FROM public.horse_observation_discovery_segments WHERE ctid IN(SELECT ctid FROM doomed);
    GET DIAGNOSTICS segments=ROW_COUNT;
    IF NOT EXISTS(SELECT 1 FROM public.horse_observation_discovery_members WHERE epoch_key=key)
      AND NOT EXISTS(SELECT 1 FROM public.horse_observation_discovery_segments WHERE epoch_key=key) THEN
      DELETE FROM public.horse_observation_discovery_epochs WHERE epoch_key=key;epochs:=1;
    END IF;
  END IF;
  RETURN jsonb_build_object('version',1,'status','pruned','epochs',epochs,'members',members,'segments',segments);
END;
$$;


ALTER FUNCTION public.fn_prune_horse_observation_discovery() OWNER TO postgres;

--
-- TOC entry 8266 (class 1255 OID 18053619)
-- Name: fn_prune_index_usage_snapshots(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_prune_index_usage_snapshots(p_keep_days integer DEFAULT 60) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_deleted integer := 0;
  v_aged    integer := 0;
BEGIN
  WITH bounds AS (
    SELECT postmaster_start, min(taken_at) AS lo, max(taken_at) AS hi
      FROM public.index_usage_snapshots
     WHERE postmaster_start <> (SELECT max(postmaster_start) FROM public.index_usage_snapshots)
     GROUP BY postmaster_start
  )
  DELETE FROM public.index_usage_snapshots s
   USING bounds b
   WHERE s.postmaster_start = b.postmaster_start
     AND s.taken_at <> b.lo
     AND s.taken_at <> b.hi;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  DELETE FROM public.index_usage_snapshots
   WHERE taken_at < now() - make_interval(days => p_keep_days);
  GET DIAGNOSTICS v_aged = ROW_COUNT;

  RETURN v_deleted + v_aged;
END;
$$;


ALTER FUNCTION public.fn_prune_index_usage_snapshots(p_keep_days integer) OWNER TO postgres;

--
-- TOC entry 48489 (class 0 OID 0)
