-- TOC entry 48496 (class 0 OID 0)
-- Dependencies: 7063
-- Name: FUNCTION fn_publish_leaderboard_reward_program(p_club_id uuid, p_rewards_enabled boolean, p_metric text, p_weekly_prizes jsonb, p_monthly_prizes jsonb, p_suggestion_key text, p_expected_version integer, p_operation_id uuid, p_overlay_enabled boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_publish_leaderboard_reward_program(p_club_id uuid, p_rewards_enabled boolean, p_metric text, p_weekly_prizes jsonb, p_monthly_prizes jsonb, p_suggestion_key text, p_expected_version integer, p_operation_id uuid, p_overlay_enabled boolean) IS 'Service-only immutable leaderboard program publication. p_overlay_enabled (default false) is the owner''s explicit Club Bank overlay opt-in, allowed only on a paid standalone club program.';


--
-- TOC entry 5557 (class 1255 OID 192382878)
-- Name: fn_publish_member_record_context(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_publish_member_record_context() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE u uuid;
BEGIN
 IF TG_TABLE_NAME='clubs' THEN
   IF NEW.name IS NOT DISTINCT FROM OLD.name THEN RETURN NULL; END IF;
   FOR u IN SELECT DISTINCT user_id FROM public.club_members WHERE club_id=NEW.id LOOP
     PERFORM public.fn_publish_member_record_user(u);
   END LOOP;
 ELSE
   IF ROW(NEW.status,NEW.club_id,NEW.name,NEW.stakes,NEW.tournament_id,NEW.is_deleted) IS NOT DISTINCT FROM ROW(OLD.status,OLD.club_id,OLD.name,OLD.stakes,OLD.tournament_id,OLD.is_deleted) THEN RETURN NULL; END IF;
   FOR u IN SELECT DISTINCT user_id FROM public.table_seats WHERE table_id=NEW.id AND left_at IS NULL LOOP
     PERFORM public.fn_publish_member_record_user(u);
   END LOOP;
 END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION public.fn_publish_member_record_context() OWNER TO postgres;

--
-- TOC entry 5322 (class 1255 OID 190020564)
-- Name: fn_publish_member_record_facts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_publish_member_record_facts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE u uuid;
BEGIN
  IF TG_OP='INSERT' THEN
    FOR u IN SELECT DISTINCT user_id FROM new_facts LOOP PERFORM public.fn_publish_member_record_user(u); END LOOP;
  ELSIF TG_OP='DELETE' THEN
    FOR u IN SELECT DISTINCT user_id FROM old_facts LOOP PERFORM public.fn_publish_member_record_user(u); END LOOP;
  ELSE
    FOR u IN SELECT DISTINCT user_id FROM (
      (SELECT hand_id,user_id,club_id,table_id,tournament_id,played_at,game_variant,net,rake_paid,vpip,pfr,three_bet,faced_three_bet,folded_to_three_bet,cbet_flop,had_cbet_flop_opp FROM new_facts EXCEPT SELECT hand_id,user_id,club_id,table_id,tournament_id,played_at,game_variant,net,rake_paid,vpip,pfr,three_bet,faced_three_bet,folded_to_three_bet,cbet_flop,had_cbet_flop_opp FROM old_facts)
      UNION ALL
      (SELECT hand_id,user_id,club_id,table_id,tournament_id,played_at,game_variant,net,rake_paid,vpip,pfr,three_bet,faced_three_bet,folded_to_three_bet,cbet_flop,had_cbet_flop_opp FROM old_facts EXCEPT SELECT hand_id,user_id,club_id,table_id,tournament_id,played_at,game_variant,net,rake_paid,vpip,pfr,three_bet,faced_three_bet,folded_to_three_bet,cbet_flop,had_cbet_flop_opp FROM new_facts)
    ) changed LOOP PERFORM public.fn_publish_member_record_user(u); END LOOP;
  END IF;
  RETURN NULL;
END $$;


ALTER FUNCTION public.fn_publish_member_record_facts() OWNER TO postgres;

--
-- TOC entry 7024 (class 1255 OID 190020546)
-- Name: fn_publish_member_record_row(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_publish_member_record_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r jsonb; old_user uuid; new_user uuid; child uuid;
BEGIN
  IF TG_OP<>'INSERT' THEN
    r:=to_jsonb(OLD); old_user:=coalesce(r->>'user_id',r->>'player_id',r->>'id')::uuid;
    PERFORM public.fn_publish_member_record_user(old_user);
    PERFORM public.fn_publish_club_roster((r->>'club_id')::uuid);
    IF TG_TABLE_NAME='club_members' THEN
      BEGIN
        PERFORM public.fn_publish_member_record_topic('member-record:'||(r->>'club_id')||':'||old_user::text,'{}'::jsonb);
        PERFORM public.fn_publish_member_record_user((r->>'agent_id')::uuid);
      EXCEPTION WHEN OTHERS THEN RAISE WARNING 'Member removal signal failed: %',SQLERRM; END;
    END IF;
  END IF;
  IF TG_OP<>'DELETE' THEN
    r:=to_jsonb(NEW); new_user:=coalesce(r->>'user_id',r->>'player_id',r->>'id')::uuid;
    PERFORM public.fn_publish_club_roster((r->>'club_id')::uuid);
    IF new_user IS DISTINCT FROM old_user THEN PERFORM public.fn_publish_member_record_user(new_user); END IF;
  END IF;
  IF TG_TABLE_NAME='profiles' THEN
  IF TG_OP='UPDATE' THEN
  IF ROW(OLD.alias,OLD.username,OLD.display_name,OLD.status,OLD.first_name,OLD.last_name,OLD.full_name,OLD.player_number) IS DISTINCT FROM
    ROW(NEW.alias,NEW.username,NEW.display_name,NEW.status,NEW.first_name,NEW.last_name,NEW.full_name,NEW.player_number) THEN
    FOR child IN SELECT DISTINCT user_id FROM public.club_members WHERE agent_id=new_user LOOP
      PERFORM public.fn_publish_member_record_user(child);
    END LOOP;
  END IF;
  END IF;
  END IF;
  RETURN NULL;
END $$;


ALTER FUNCTION public.fn_publish_member_record_row() OWNER TO postgres;

--
-- TOC entry 4777 (class 1255 OID 199387869)
-- Name: fn_publish_member_record_topic(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_publish_member_record_topic(p_topic text, p_payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE sent jsonb:=coalesce(nullif(current_setting('ca.member_record_signaled_topics',true),''),'[]')::jsonb;
BEGIN
  IF p_topic IS NULL OR p_topic !~ '^member-record:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'Invalid member record topic';
  END IF;
  IF sent ? p_topic THEN RETURN; END IF;
  PERFORM public.fn_dispatch_private_record_signal(p_topic,p_payload);
  -- Only a successful send consumes the topic. SET LOCAL and the message both
  -- roll back at a savepoint or transaction boundary; future commits send again.
  PERFORM set_config('ca.member_record_signaled_topics',(sent||to_jsonb(p_topic))::text,true);
END $_$;


ALTER FUNCTION public.fn_publish_member_record_topic(p_topic text, p_payload jsonb) OWNER TO postgres;

--
-- TOC entry 6098 (class 1255 OID 190020571)
-- Name: fn_publish_member_record_transaction(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_publish_member_record_transaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE old_row jsonb; new_row jsonb; u uuid;
BEGIN
 IF TG_OP<>'INSERT' THEN old_row:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN new_row:=to_jsonb(NEW); END IF;
 IF TG_OP='UPDATE' AND old_row=new_row THEN RETURN NULL; END IF;
 FOR u IN SELECT DISTINCT x FROM unnest(ARRAY[
   (old_row->>'from_user_id')::uuid,(old_row->>'to_user_id')::uuid,
   (new_row->>'from_user_id')::uuid,(new_row->>'to_user_id')::uuid]) x WHERE x IS NOT NULL LOOP
   PERFORM public.fn_publish_member_record_user(u);
 END LOOP;
 RETURN NULL;
END $$;


ALTER FUNCTION public.fn_publish_member_record_transaction() OWNER TO postgres;

--
-- TOC entry 6907 (class 1255 OID 190020545)
-- Name: fn_publish_member_record_user(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_publish_member_record_user(p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE target record;
BEGIN
  FOR target IN
    WITH RECURSIVE owners AS (
      SELECT club_id,user_id,agent_id,ARRAY[user_id] path FROM public.club_members WHERE user_id=p_user
      UNION ALL
      SELECT m.club_id,m.user_id,m.agent_id,o.path||m.user_id
      FROM owners o JOIN public.club_members m ON m.club_id=o.club_id AND m.user_id=o.agent_id
      WHERE cardinality(o.path)<20 AND NOT m.user_id=ANY(o.path)
    ) SELECT DISTINCT club_id,user_id FROM owners
  LOOP
    PERFORM public.fn_publish_club_roster(target.club_id);
    BEGIN
      PERFORM public.fn_publish_member_record_topic(
        'member-record:'||target.club_id::text||':'||target.user_id::text,jsonb_build_object('user_id',p_user));
    EXCEPTION WHEN OTHERS THEN RAISE WARNING 'Member record signal failed: %',SQLERRM;
    END;
  END LOOP;
END $$;


ALTER FUNCTION public.fn_publish_member_record_user(p_user uuid) OWNER TO postgres;

--
-- TOC entry 3894 (class 1255 OID 153039708)
-- Name: fn_publish_player_history_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_publish_player_history_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.club_id IS NULL OR NOT (
    (NEW.target_type IN ('member','club_member','membership') AND NEW.action IN (
      'role_change','set_member_role','banned','unban_member','member_status_change',
      'set_member_status','kick_member','member_left','depart_club_member'))
    OR (NEW.target_type='club_member' AND NEW.action='update_member_notes')
    OR (NEW.target_type='club' AND NEW.target_id=NEW.club_id AND NEW.action='export_club_roster')
  ) THEN RETURN NEW; END IF;
  -- A failed broadcast must never roll back the underlying member/financial
  -- transaction. Explicit refresh after subscription recovery reads the journal.
  BEGIN
    PERFORM realtime.send(jsonb_build_object('club_id',NEW.club_id,
      'target_id',NEW.target_id,'action',NEW.action),
      'history_changed','player-history:'||NEW.club_id::text,true);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Player history signal delivery failed: %',SQLERRM;
  END;
  RETURN NEW;
END $$;


