--
-- TOC entry 6234 (class 1255 OID 30231619)
-- Name: fn_queue_horse_adaptive_batch(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_queue_horse_adaptive_batch(p_payload text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    SET lock_timeout TO '2s'
    AS $_$
DECLARE
  b jsonb; key text; fingerprint text; n integer; occupied integer; used_bytes bigint;
  prior public.horse_adaptive_journal_work%ROWTYPE;
  receipt public.horse_adaptive_observation_batches%ROWTYPE;
BEGIN
  IF p_payload IS NULL OR octet_length(p_payload)>16777216 THEN RAISE EXCEPTION 'ADAPTIVE_WORK_INVALID_BATCH'; END IF;
  b:=p_payload::jsonb;
  IF jsonb_typeof(b) IS DISTINCT FROM 'array' OR jsonb_array_length(b)<>8 THEN RAISE EXCEPTION 'ADAPTIVE_WORK_INVALID_BATCH'; END IF;
  IF b->0 IS DISTINCT FROM '1'::jsonb OR jsonb_typeof(b->1) IS DISTINCT FROM 'string'
     OR b->>1 !~ '^[a-f0-9]{64}$' OR jsonb_typeof(b->2) IS DISTINCT FROM 'string'
     OR b->>2 !~ '^[a-f0-9]{64}$' OR jsonb_typeof(b->3) IS DISTINCT FROM 'number'
     OR b->>3 !~ '^[0-9]{1,16}$' OR jsonb_typeof(b->4) IS DISTINCT FROM 'number'
     OR b->>4 !~ '^[0-9]{1,16}$' OR jsonb_typeof(b->5) IS DISTINCT FROM 'string'
     OR b->>5 !~ '^[a-f0-9]{64}$' OR jsonb_typeof(b->6) IS DISTINCT FROM 'array'
     OR jsonb_array_length(b->6)>64 OR jsonb_typeof(b->7) IS DISTINCT FROM 'array'
     OR jsonb_array_length(b->7)>20000 THEN RAISE EXCEPTION 'ADAPTIVE_WORK_INVALID_BATCH'; END IF;
  key:=b->>1;fingerprint:=encode(sha256(convert_to(p_payload,'UTF8')),'hex');n:=jsonb_array_length(b->7);
  IF (b->>4)::bigint<=(b->>3)::bigint OR (b->>4)::bigint-(b->>3)::bigint>21600000
     OR (b->>4)::bigint>9007199254740991
     OR key<>encode(sha256(convert_to(concat_ws('|','adaptive-journal-v1',b->>2,b->>5,b->>3,b->>4),'UTF8')),'hex')
     THEN RAISE EXCEPTION 'ADAPTIVE_WORK_INVALID_BATCH'; END IF;
  SELECT * INTO prior FROM public.horse_adaptive_journal_work w WHERE w.batch_key=key FOR UPDATE;
  IF FOUND THEN
    IF prior.batch_digest<>fingerprint THEN RETURN jsonb_build_object('version',1,'status','unavailable','reason','batch_conflict'); END IF;
    RETURN jsonb_build_object('version',1,'status','durable','batchKey',key,'batchDigest',fingerprint,'observations',n);
  END IF;
  SELECT * INTO receipt FROM public.horse_adaptive_observation_batches q WHERE q.batch_key=key;
  IF FOUND THEN
    IF receipt.batch_digest<>fingerprint THEN RETURN jsonb_build_object('version',1,'status','unavailable','reason','batch_conflict'); END IF;
    IF receipt.retention_compacted THEN RETURN jsonb_build_object('version',1,'status','unavailable','reason','retention_compacted'); END IF;
    IF receipt.canonical_payload IS NULL THEN RETURN jsonb_build_object('version',1,'status','unavailable','reason','legacy_batch_payload_unavailable'); END IF;
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->7) v WHERE EXISTS(SELECT 1 FROM smarter_private.horse_adaptive_disposal_certificates c WHERE c.hand_digest=encode(sha256(convert_to((v.value#>>'{}')::jsonb->>2,'UTF8')),'hex') AND c.retired_at IS NOT NULL)) THEN RETURN jsonb_build_object('version',1,'status','unavailable','reason','retention_compacted'); END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->7) v JOIN smarter_private.horse_adaptive_legacy_learning_purges p ON p.hand_digest=encode(sha256(convert_to((v.value#>>'{}')::jsonb->>2,'UTF8')),'hex')) THEN RETURN jsonb_build_object('version',1,'status','unavailable','reason','retention_compacted'); END IF;
  -- Try, never wait behind another capacity reservation. Existing jobs remain
  -- replayable even while the bounded new-work buffer is full.
  IF NOT pg_try_advisory_xact_lock(hashtextextended('horse-adaptive-work-capacity-v1',0)) THEN
    RETURN jsonb_build_object('version',1,'status','unavailable','reason','capacity_busy');
  END IF;
  -- Another enqueue may have committed after the first read but before this
  -- capacity reservation. Re-read its immutable receipt under the same key.
  SELECT * INTO prior FROM public.horse_adaptive_journal_work w WHERE w.batch_key=key FOR UPDATE;
  IF FOUND THEN
    IF prior.batch_digest<>fingerprint THEN RETURN jsonb_build_object('version',1,'status','unavailable','reason','batch_conflict'); END IF;
    RETURN jsonb_build_object('version',1,'status','durable','batchKey',key,'batchDigest',fingerprint,'observations',n);
  END IF;
  -- Only new work needs a live source window. Existing durable work above can
  -- always replay. Retention shares this capacity lock, so it cannot remove a
  -- receipt between admitting new work and persisting its payload.
  IF (b->>3)::bigint < floor(extract(epoch FROM clock_timestamp())*1000)::bigint-2592000000
     OR (b->>4)::bigint > floor(extract(epoch FROM clock_timestamp())*1000)::bigint THEN
    RETURN jsonb_build_object('version',1,'status','unavailable','reason','source_expired');
  END IF;
  SELECT count(*),coalesce(sum(octet_length(w.payload)),0) INTO occupied,used_bytes
    FROM public.horse_adaptive_journal_work w WHERE w.state<>'completed';
  IF occupied>=256 OR used_bytes+octet_length(p_payload)>67108864 THEN
    RETURN jsonb_build_object('version',1,'status','unavailable','reason','queue_full');
  END IF;
  INSERT INTO public.horse_adaptive_journal_work(batch_key,batch_digest,observations,payload)
    VALUES(key,fingerprint,n,p_payload);
  RETURN jsonb_build_object('version',1,'status','durable','batchKey',key,'batchDigest',fingerprint,'observations',n);
END
$_$;


ALTER FUNCTION public.fn_queue_horse_adaptive_batch(p_payload text) OWNER TO postgres;

--
-- TOC entry 3802 (class 1255 OID 101363758)
-- Name: fn_queue_video_native_rendition(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_queue_video_native_rendition(p_candidate_id uuid, p_actor_id uuid, p_settings jsonb) RETURNS public.video_native_renditions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE c public.video_reel_candidates; m public.video_source_masters; e public.video_rights_evidence; r public.video_native_renditions; s numeric; f numeric;
BEGIN
  IF coalesce(auth.role()::text,'')<>'service_role' THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
  SELECT * INTO c FROM public.video_reel_candidates WHERE id=p_candidate_id FOR UPDATE;
  IF c.id IS NULL OR c.status<>'approved' OR c.playback_mode<>'native_master' OR NOT c.native_clip_eligible OR c.rights_status NOT IN ('owned','licensed') THEN RAISE EXCEPTION 'approved rights-cleared native candidate required'; END IF;
  SELECT * INTO m FROM public.video_source_masters WHERE video_id=c.video_id AND status='ready' FOR SHARE;
  SELECT * INTO e FROM public.video_rights_evidence WHERE id=m.rights_evidence_id AND revoked_at IS NULL AND valid_from<=now() AND (valid_until IS NULL OR valid_until>now()) FOR SHARE;
  IF m.id IS NULL OR e.id IS NULL OR e.rights_status<>c.rights_status OR NOT e.permitted_uses @> ARRAY['native_clip']::text[] THEN RAISE EXCEPTION 'active matching source-master rights required'; END IF;
  s:=coalesce((p_settings->>'clip_start_seconds')::numeric,c.clip_start_seconds); f:=coalesce((p_settings->>'clip_end_seconds')::numeric,c.clip_end_seconds);
  IF s<0 OR f<=s OR f-s>180 OR f>m.duration_seconds THEN RAISE EXCEPTION 'studio clip boundaries are invalid'; END IF;
  IF coalesce(p_settings->>'crop_mode','vertical_focus') NOT IN ('vertical_focus','fit_blur','center_crop') OR coalesce((p_settings->>'focus_x')::numeric,50) NOT BETWEEN 0 AND 100 THEN RAISE EXCEPTION 'studio crop settings are invalid'; END IF;
  INSERT INTO public.video_native_renditions(candidate_id,master_id,settings,estimated_cost_cents)
  VALUES(c.id,m.id,p_settings||jsonb_build_object('clip_start_seconds',s,'clip_end_seconds',f),greatest(1,ceil(f-s)::int))
  ON CONFLICT(candidate_id) DO UPDATE SET master_id=excluded.master_id,settings=excluded.settings,status='queued',next_attempt_at=NULL,last_failure_code=NULL,updated_at=now(),version=video_native_renditions.version+1
  WHERE video_native_renditions.status IN ('failed','rejected') RETURNING * INTO r;
  IF r.id IS NULL THEN SELECT * INTO r FROM public.video_native_renditions WHERE candidate_id=c.id; END IF;
  RETURN r;
END $$;


ALTER FUNCTION public.fn_queue_video_native_rendition(p_candidate_id uuid, p_actor_id uuid, p_settings jsonb) OWNER TO postgres;

--
-- TOC entry 7850 (class 1255 OID 5237646)
-- Name: fn_queue_video_transcode(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_queue_video_transcode() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.content_type = 'video'
     AND (NEW.media_urls->>0) IS NOT NULL
     AND (
       (NEW.media_urls->>0) ILIKE '%.mov'
       OR (NEW.media_urls->>0) ILIKE '%.hevc'
       OR (NEW.media_urls->>0) ILIKE '%.heic'
       OR (NEW.media_urls->>0) ILIKE '%.mkv'
       OR (NEW.media_urls->>0) ILIKE '%.avi'
       OR (NEW.media_urls->>0) ILIKE '%.mp4'
       OR (NEW.media_urls->>0) ILIKE '%.m4v'
       OR (NEW.media_urls->>0) ILIKE '%.webm'
       OR (NEW.media_urls->>0) ILIKE '%/live-recordings/%'
     )
     -- Only queue when a thumbnail is actually missing: a client-supplied
     -- poster frame should not trigger a re-encode just for extraction.
     AND (NEW.thumbnail_url IS NULL OR NEW.thumbnail_url = '')
  THEN
    NEW.transcode_status := 'queued';
    NEW.original_media_url := (NEW.media_urls->>0);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_queue_video_transcode() OWNER TO postgres;

--
-- TOC entry 4969 (class 1255 OID 22468996)
-- Name: fn_queue_youtube_verification(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_queue_youtube_verification(p_video_id text, p_surface text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_video_id text := public.fn_extract_youtube_video_id(p_video_id);
  v_surface text := left(
    regexp_replace(
      COALESCE(NULLIF(btrim(p_surface), ''), 'youtube_publication'),
      '[[:cntrl:]]',
      '',
      'g'
    ),
    80
  );
BEGIN
  IF v_video_id IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO public.youtube_embed_failures AS existing (
    video_id,
    error_code,
    surface,
    hit_count,
    first_seen_at,
    last_seen_at,
    resolved,
    verification_status,
    last_verified_at
  ) VALUES (
    v_video_id,
    150,
    v_surface,
    0,
    now(),
    now(),
    true,
    'pending',
    NULL
  )
  ON CONFLICT ON CONSTRAINT youtube_embed_failures_video_id_key DO UPDATE
  SET surface = EXCLUDED.surface,
      last_seen_at = now(),
      resolved = true,
      verification_status = 'pending',
      last_verified_at = NULL
  WHERE NOT (
      existing.verification_status = 'confirmed'
      AND existing.resolved = false
    )
    AND NOT (
      existing.verification_status = 'resolved'
      AND existing.resolved = true
      AND existing.last_verified_at >= now() - interval '6 days'
      AND existing.last_verified_at <= now() + interval '5 minutes'
    );
END
$$;


ALTER FUNCTION public.fn_queue_youtube_verification(p_video_id text, p_surface text) OWNER TO postgres;

--
-- TOC entry 8054 (class 1255 OID 11399560)
-- Name: fn_raise_financial_alert(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_raise_financial_alert(p_severity text, p_source text, p_message text, p_context jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id       uuid;
  v_sev      text;
  v_uid      uuid := auth.uid();
  v_recent   integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required to raise a financial alert'
      USING ERRCODE = '28000';
  END IF;

  v_sev := lower(coalesce(p_severity, 'info'));
  IF v_sev NOT IN ('critical', 'warning', 'info') THEN
    v_sev := 'info';
  END IF;

  -- Flood guard: at most 30 alerts per reporter per minute. Returning NULL
  -- rather than raising keeps the caller's error path clean; the caller still
  -- escalates to its own error reporter when it gets no id back.
  SELECT count(*) INTO v_recent
    FROM public.financial_alerts
   WHERE created_at > now() - interval '1 minute'
     AND context ->> 'reported_by' = v_uid::text;
  IF v_recent >= 30 THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.financial_alerts (severity, source, message, context, resolved)
  VALUES (
    v_sev,
    left(coalesce(nullif(p_source, ''), 'unknown'), 200),
    left(coalesce(nullif(p_message, ''), '(no message)'), 4000),
    coalesce(p_context, '{}'::jsonb)
      || jsonb_build_object('reported_by', v_uid::text, 'channel', 'client_rpc'),
    false
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION public.fn_raise_financial_alert(p_severity text, p_source text, p_message text, p_context jsonb) OWNER TO postgres;

--
-- TOC entry 48526 (class 0 OID 0)
-- Dependencies: 8054
-- Name: FUNCTION fn_raise_financial_alert(p_severity text, p_source text, p_message text, p_context jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_raise_financial_alert(p_severity text, p_source text, p_message text, p_context jsonb) IS 'Audit M7: raise-only entry point for client financial alerts. financial_alerts RLS is service_role-only, so clients must route through this SECURITY DEFINER function. Throttled to 30 alerts/reporter/minute; returns NULL when throttled.';


--
-- TOC entry 4228 (class 1255 OID 17387845)
-- Name: fn_raise_notification(uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_raise_notification(p_user_id uuid, p_type text, p_title text, p_message text, p_link text DEFAULT NULL::text, p_data jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_title IS NULL OR btrim(p_title) = '' THEN RETURN; END IF;
  INSERT INTO public.notifications (user_id, type, title, message, link, data)
  VALUES (p_user_id, p_type, p_title, p_message, p_link, COALESCE(p_data, '{}'::jsonb));
END; $$;


