--
-- TOC entry 5022 (class 1255 OID 33305552)
-- Name: fn_read_operational_source_snapshot(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_read_operational_source_snapshot(p_inbox_event_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e public.operational_alert_events%ROWTYPE; k text;
BEGIN
  SELECT * INTO STRICT e FROM public.operational_alert_events WHERE id=p_inbox_event_id;
  k:=CASE WHEN e.source IN ('financial-alerts-backfill','financial-alerts-updates') THEN 'financial'
    WHEN e.source IN ('drift-incidents-backfill','drift-incidents-updates') THEN 'drift'
    WHEN e.source IN ('engine-alerts-backfill','engine-alerts-updates') THEN 'engine' END;
  IF k IS NULL THEN RAISE EXCEPTION 'not an operational source receipt'; END IF;
  RETURN operational_source_intake.receipt_row(e,k);
END;
$$;


ALTER FUNCTION public.fn_read_operational_source_snapshot(p_inbox_event_id bigint) OWNER TO postgres;

--
-- TOC entry 7282 (class 1255 OID 207613169)
-- Name: fn_reassign_club_members(uuid, uuid[], uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_reassign_club_members(p_club_id uuid, p_member_user_ids uuid[], p_agent_user_id uuid, p_op_id uuid, p_expected_agent_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_ids uuid[]; v_old record; v_parent uuid; v_rank integer; v_m record; v_count integer;
BEGIN
 IF NOT COALESCE(public.fn_can_manage_club_assignments(p_club_id),false) THEN
  RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501'; END IF;
 IF p_op_id IS NULL OR p_agent_user_id IS NULL OR p_club_id IS NULL THEN
  RAISE EXCEPTION 'assignment_identity_required' USING ERRCODE='22023'; END IF;
 v_ids:=ARRAY(SELECT DISTINCT x FROM unnest(p_member_user_ids) x WHERE x IS NOT NULL ORDER BY x);
 IF cardinality(v_ids)=0 OR cardinality(v_ids)>10000 THEN
  RAISE EXCEPTION 'select_between_1_and_10000_members' USING ERRCODE='22023'; END IF;
 -- Same agreement lock as role/rate changes, before any row locks.
 PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||p_club_id::text,0));
 SELECT * INTO v_old FROM public.club_assignment_operations WHERE id=p_op_id;
 IF FOUND THEN
  IF v_old.club_id<>p_club_id OR v_old.actor_id<>auth.uid()
    OR v_old.destination_user_id<>p_agent_user_id OR v_old.member_user_ids<>v_ids
    OR v_old.source_user_id IS DISTINCT FROM p_expected_agent_user_id THEN
   RAISE EXCEPTION 'assignment_operation_conflict' USING ERRCODE='22023'; END IF;
  RETURN jsonb_build_object('success',true,'replayed',true,'operation_id',p_op_id,'moved',cardinality(v_ids));
 END IF;
 SELECT a.id,public.fn_club_role_rank(m.role) INTO v_parent,v_rank
 FROM public.agents a JOIN public.club_members m ON m.club_id=a.club_id AND m.user_id=a.user_id
 WHERE a.club_id=p_club_id AND a.user_id=p_agent_user_id AND a.status='active'
 AND m.role IN ('owner','co_owner','admin','super_agent','agent','sub_agent')
 AND public.fn_cashier_member_is_active(m.club_id,m.user_id) FOR UPDATE OF a,m;
 IF v_parent IS NULL THEN RAISE EXCEPTION 'agent_not_active_in_club' USING ERRCODE='22023'; END IF;
 IF p_agent_user_id=ANY(v_ids) THEN RAISE EXCEPTION 'agent_cannot_report_to_itself' USING ERRCODE='22023'; END IF;
 SELECT count(*) INTO v_count FROM public.club_members m WHERE m.club_id=p_club_id
  AND m.user_id=ANY(v_ids) AND public.fn_cashier_member_is_active(m.club_id,m.user_id);
 IF v_count<>cardinality(v_ids) THEN RAISE EXCEPTION 'member_not_active_in_club' USING ERRCODE='22023'; END IF;
 FOR v_m IN SELECT * FROM public.club_members m WHERE m.club_id=p_club_id AND m.user_id=ANY(v_ids)
  ORDER BY m.user_id FOR UPDATE LOOP
  IF v_m.role NOT IN ('member','player','super_agent','agent','sub_agent') THEN
   RAISE EXCEPTION 'staff_cannot_be_assigned_as_downline' USING ERRCODE='22023'; END IF;
  IF p_expected_agent_user_id IS NOT NULL AND v_m.agent_id IS DISTINCT FROM p_expected_agent_user_id THEN
   RAISE EXCEPTION 'assignment_changed_reload_members' USING ERRCODE='P0001'; END IF;
  IF public.fn_club_is_in_downline(p_club_id,v_m.user_id,p_agent_user_id) THEN
   RAISE EXCEPTION 'would_create_cycle' USING ERRCODE='22023'; END IF;
  IF v_m.role IN ('super_agent','agent','sub_agent')
     AND public.fn_club_role_rank(v_m.role)>=v_rank THEN
   RAISE EXCEPTION 'upline_role_must_rank_above_downline' USING ERRCODE='22023'; END IF;
 END LOOP;
 UPDATE public.club_members SET agent_id=p_agent_user_id,updated_at=now()
 WHERE club_id=p_club_id AND user_id=ANY(v_ids);
 -- Both maintained hierarchy representations change in the same transaction.
 UPDATE public.agents SET parent_agent_id=v_parent,updated_at=now()
 WHERE club_id=p_club_id AND user_id=ANY(v_ids);
 UPDATE public.agents a SET total_players=(SELECT count(*) FROM public.club_members m
   WHERE m.club_id=p_club_id AND m.agent_id=a.user_id),updated_at=now() WHERE a.club_id=p_club_id;
 INSERT INTO public.club_assignment_operations(id,club_id,actor_id,destination_user_id,source_user_id,member_user_ids)
 VALUES(p_op_id,p_club_id,auth.uid(),p_agent_user_id,p_expected_agent_user_id,v_ids);
 INSERT INTO public.audit_trail(actor_id,actor_role,action,target_type,target_id,club_id,reason)
 VALUES(auth.uid(),COALESCE(public.fn_club_bank_role(p_club_id),'union_overseer'),
  'reassign_club_downline','club',p_club_id,p_club_id,jsonb_build_object('operation_id',p_op_id,
  'destination',p_agent_user_id,'source',p_expected_agent_user_id,'members',v_ids)::text);
 RETURN jsonb_build_object('success',true,'operation_id',p_op_id,'moved',cardinality(v_ids));
END $$;


ALTER FUNCTION public.fn_reassign_club_members(p_club_id uuid, p_member_user_ids uuid[], p_agent_user_id uuid, p_op_id uuid, p_expected_agent_user_id uuid) OWNER TO postgres;

--
-- TOC entry 6874 (class 1255 OID 20597571)
-- Name: fn_rebuild_agent_commission_rollup(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rebuild_agent_commission_rollup() RETURNS TABLE(pairs bigint, owed numeric, rows_behind bigint)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (session_user IN ('postgres', 'supabase_admin')
          OR coalesce(auth.role(), '') = 'service_role'
          OR coalesce(fn_is_platform_admin(), false)) THEN
    RAISE EXCEPTION 'rebuild is an operator action' USING ERRCODE = '42501';
  END IF;

  -- Nothing may write the ledger between the count and the commit.
  LOCK TABLE public.agent_commissions IN SHARE ROW EXCLUSIVE MODE;

  -- WHERE true: this is a full rebuild and it means every row, but PostgREST
  -- runs under safeupdate, which refuses an unqualified DELETE outright.
  DELETE FROM public.agent_commission_unsettled_rollup WHERE true;
  INSERT INTO public.agent_commission_unsettled_rollup
         (club_id, user_id, owed, rows_behind, oldest_unsettled, updated_at)
  SELECT ac.club_id, ac.user_id, sum(ac.amount), count(*), min(ac.created_at), now()
    FROM public.agent_commissions_unsettled ac
   WHERE ac.club_id IS NOT NULL AND ac.user_id IS NOT NULL
   GROUP BY ac.club_id, ac.user_id;

  RETURN QUERY
  SELECT count(*)::bigint, coalesce(sum(r.owed), 0), coalesce(sum(r.rows_behind), 0)::bigint
    FROM public.agent_commission_unsettled_rollup r;
END;
$$;


ALTER FUNCTION public.fn_rebuild_agent_commission_rollup() OWNER TO postgres;

--
-- TOC entry 4094 (class 1255 OID 20927898)
-- Name: fn_rebuild_ca_club_commission_daily(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rebuild_ca_club_commission_daily() RETURNS TABLE(club_days bigint, amount numeric, rows_counted bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (session_user IN ('postgres', 'supabase_admin')
          OR coalesce(auth.role(), '') = 'service_role'
          OR coalesce(fn_is_platform_admin(), false)) THEN
    RAISE EXCEPTION 'rebuild is an operator action' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('ca_club_commission_daily:rebuild', 42));
  DELETE FROM public.ca_club_commission_daily;
  INSERT INTO public.ca_club_commission_daily AS c
         (club_id, stat_date, amount, rows_counted, updated_at)
  SELECT ac.club_id, (ac.created_at AT TIME ZONE 'UTC')::date, sum(ac.amount), count(*), now()
    FROM agent_commissions ac
   WHERE ac.club_id IS NOT NULL
   GROUP BY ac.club_id, (ac.created_at AT TIME ZONE 'UTC')::date
  ON CONFLICT (club_id, stat_date) DO UPDATE
     SET amount       = c.amount + EXCLUDED.amount,
         rows_counted = c.rows_counted + EXCLUDED.rows_counted,
         updated_at   = now();
  RETURN QUERY
  SELECT count(*)::bigint, coalesce(sum(x.amount), 0), coalesce(sum(x.rows_counted), 0)::bigint
    FROM public.ca_club_commission_daily x;
END;
$$;


ALTER FUNCTION public.fn_rebuild_ca_club_commission_daily() OWNER TO postgres;

--
-- TOC entry 4615 (class 1255 OID 24464287)
-- Name: fn_receipt_mystery_activation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_receipt_mystery_activation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_chest_count integer;
  v_pool_cents bigint;
  v_receipt public.tournament_mystery_activation_receipts%ROWTYPE;
BEGIN
  IF NEW.mystery_bounty_stage='active'
     AND OLD.mystery_bounty_stage IS DISTINCT FROM 'active' THEN
    SELECT count(*)::integer,COALESCE(sum(c.amount_cents),0)::bigint
      INTO v_chest_count,v_pool_cents
      FROM public.tournament_bounty_chests c WHERE c.tournament_id=NEW.id;
    IF v_chest_count<=0 OR v_pool_cents<=0
       OR v_pool_cents IS DISTINCT FROM NEW.mystery_bounty_pool_cents THEN
      RAISE EXCEPTION 'mystery activation inventory is missing or does not match its sealed pool'
        USING ERRCODE='check_violation';
    END IF;
    INSERT INTO public.tournament_mystery_activation_receipts
      (tournament_id,activation_generation,activated_at,chest_count,pool_cents)
    VALUES (NEW.id,NEW.mystery_bounty_activation_generation,
            COALESCE(NEW.mystery_bounty_activated_at,now()),v_chest_count,v_pool_cents)
    ON CONFLICT (tournament_id,activation_generation) DO NOTHING;
    SELECT * INTO v_receipt FROM public.tournament_mystery_activation_receipts
     WHERE tournament_id=NEW.id
       AND activation_generation=NEW.mystery_bounty_activation_generation;
    IF NOT FOUND OR v_receipt.chest_count<>v_chest_count
       OR v_receipt.pool_cents<>v_pool_cents THEN
      RAISE EXCEPTION 'mystery activation receipt identity conflict'
        USING ERRCODE='check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_receipt_mystery_activation() OWNER TO postgres;

--
-- TOC entry 5255 (class 1255 OID 25706069)
-- Name: fn_receipted_tournament_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_receipted_tournament_is_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF upper(COALESCE(OLD.status::text,'')) IN
       ('COMPLETED','CANCELLED','CANCELED') THEN
    RAISE EXCEPTION 'terminal tournament % is immutable after closure',OLD.id
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_receipted_tournament_is_immutable() OWNER TO postgres;

