--
-- TOC entry 4584 (class 1255 OID 2686607)
-- Name: fn_recompute_union_level_on_club_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_recompute_union_level_on_club_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_union_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN v_union_id := OLD.union_id;
  ELSE                     v_union_id := NEW.union_id;
  END IF;
  BEGIN
    PERFORM public.recompute_union_levels(v_union_id);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_recompute_union_level_on_club_change failed for union=%: % (%)',
      v_union_id, SQLERRM, SQLSTATE;
  END;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


