--
-- TOC entry 4521 (class 1255 OID 14334607)
-- Name: fn_reconcile_club_member_daily_profit(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_reconcile_club_member_daily_profit(p_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cutover  date := DATE '2026-08-20';
  -- The first day every writer records each hand's own net
  -- (20260922144812). From it there is nothing to correct: the day is
  -- measured and logged, never rewritten.
  v_exact_from date := DATE '2026-09-23';
  v_club     uuid;
  v_check    jsonb;
  v_rows     integer;
  v_applied  integer := 0;
  v_skipped  integer := 0;
  v_total    integer := 0;
  v_report   jsonb := '[]'::jsonb;
BEGIN
  IF p_date IS NULL OR p_date >= CURRENT_DATE THEN
    RETURN jsonb_build_object('reconciled', false, 'reason', 'day_not_complete', 'date', p_date);
  END IF;
  IF p_date < v_cutover THEN
    RETURN jsonb_build_object('reconciled', false, 'reason', 'before_exact_ledger_cutover',
                              'date', p_date, 'cutover', v_cutover);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM player_stats_snapshots WHERE snapshot_date = p_date)
     OR NOT EXISTS (SELECT 1 FROM player_stats_snapshots WHERE snapshot_date = p_date + 1) THEN
    RETURN jsonb_build_object('reconciled', false, 'reason', 'missing_boundary_snapshot', 'date', p_date);
  END IF;

  FOR v_club IN
    SELECT DISTINCT club_id FROM club_member_daily_stats WHERE stat_date = p_date
  LOOP
    v_total := v_total + 1;
    v_check := public.fn_club_profit_conservation(v_club, p_date);
    v_rows  := 0;

    IF (v_check ->> 'conserves')::boolean AND p_date < v_exact_from THEN
      WITH exact AS (
        SELECT b.user_id,
               (a.total_winnings - b.total_winnings) - (a.total_losses - b.total_losses) AS profit
          FROM player_stats_snapshots b
          JOIN player_stats_snapshots a
            ON a.user_id = b.user_id AND a.club_id = b.club_id
           AND a.snapshot_date = p_date + 1
         WHERE b.snapshot_date = p_date AND b.club_id = v_club
      ),
      shares AS (
        SELECT s.club_id, s.user_id, s.table_id, e.profit AS exact_profit,
               GREATEST(COALESCE(s.hands_played, 0), 0) AS w,
               SUM(GREATEST(COALESCE(s.hands_played, 0), 0))
                 OVER (PARTITION BY s.club_id, s.user_id) AS w_total,
               COUNT(*)     OVER (PARTITION BY s.club_id, s.user_id) AS n_rows,
               ROW_NUMBER() OVER (PARTITION BY s.club_id, s.user_id ORDER BY s.table_id) AS rn
          FROM club_member_daily_stats s
          JOIN exact e ON e.user_id = s.user_id
         WHERE s.stat_date = p_date AND s.club_id = v_club
      ),
      alloc AS (
        SELECT club_id, user_id, table_id, exact_profit, rn, n_rows,
               CASE WHEN w_total > 0 THEN round(exact_profit * w / w_total, 2)
                    ELSE round(exact_profit / n_rows, 2) END AS share
          FROM shares
      ),
      fixed AS (
        SELECT a.*, a.exact_profit - SUM(a.share) OVER (PARTITION BY a.club_id, a.user_id) AS remainder
          FROM alloc a
      )
      UPDATE club_member_daily_stats s
         SET profit = f.share + CASE WHEN f.rn = f.n_rows THEN f.remainder ELSE 0 END,
             updated_at = now()
        FROM fixed f
       WHERE s.stat_date = p_date
         AND s.club_id = f.club_id AND s.user_id = f.user_id
         AND s.table_id IS NOT DISTINCT FROM f.table_id
         -- A ROW THAT IS ALREADY RIGHT IS NOT WRITTEN (2026-09-19).
         -- Postgres counts an unchanged row as updated, so without this the
         -- reconciler rewrote all 42,094 rows on every call: 2,820,298 row
         -- writes in one day for a correction that was finished by 00:15.
         -- IS DISTINCT FROM, not <>, so a NULL profit is still written.
         AND s.profit IS DISTINCT FROM (f.share + CASE WHEN f.rn = f.n_rows THEN f.remainder ELSE 0 END);

      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_applied := v_applied + 1;
    ELSE
      v_skipped := v_skipped + 1;
    END IF;

    INSERT INTO public.club_profit_reconcile_log
      (stat_date, club_id, exact_profit_sum, house_cut, exact_drift,
       dashboard_drift_before, tolerance, applied, reason, rows_updated)
    VALUES (p_date, v_club,
            (v_check ->> 'exact_profit_sum')::numeric,
            (v_check ->> 'house_cut')::numeric,
            (v_check ->> 'exact_drift')::numeric,
            (v_check ->> 'dashboard_drift')::numeric,
            (v_check ->> 'tolerance')::numeric,
            (v_check ->> 'conserves')::boolean AND p_date < v_exact_from,
            CASE WHEN p_date >= v_exact_from THEN 'exact_at_source'
                 WHEN (v_check ->> 'conserves')::boolean THEN 'conserves'
                 WHEN NOT (v_check ->> 'has_house_row')::boolean THEN 'no_house_cut_row'
                 ELSE 'fails_chip_conservation' END,
            v_rows);

    v_report := v_report || jsonb_build_array(v_check);
  END LOOP;

  RETURN jsonb_build_object(
    'reconciled', true, 'date', p_date,
    'clubs_seen', v_total, 'clubs_applied', v_applied, 'clubs_skipped', v_skipped,
    'detail', v_report
  );
END;
$$;


ALTER FUNCTION public.fn_reconcile_club_member_daily_profit(p_date date) OWNER TO postgres;

--
-- TOC entry 5893 (class 1255 OID 14498787)
-- Name: fn_reconcile_club_table_counts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_reconcile_club_table_counts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_fixed int;
begin
  with drifted as (
    select c.id, fn_live_table_count(c.id) AS truth
      from clubs c
     where c.table_count is distinct from fn_live_table_count(c.id)
  )
  update clubs c set table_count = d.truth
    from drifted d
   where c.id = d.id;
  get diagnostics v_fixed = row_count;
  return v_fixed;
end $$;


ALTER FUNCTION public.fn_reconcile_club_table_counts() OWNER TO postgres;

--
-- TOC entry 48584 (class 0 OID 0)
-- Dependencies: 5893
-- Name: FUNCTION fn_reconcile_club_table_counts(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_reconcile_club_table_counts() IS 'Nightly backstop for clubs.table_count. Before 2026-08-20 an always-firing trigger re-synced every count on every hand; removing that waste also removed an accidental reconciler, so drift became permanent. Returns the number of clubs corrected — a non-zero result means a drift source is still uncovered and is worth investigating, not just repairing.';


--
-- TOC entry 6683 (class 1255 OID 15310758)
-- Name: fn_reconcile_tournament_denormals(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_reconcile_tournament_denormals() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_roster int := 0;
  v_dupes  int := 0;
  v_counts int := 0;
BEGIN
  WITH live_seat AS (
    SELECT s.user_id, tb.tournament_id, s.table_id, s.seat_number,
           ROW_NUMBER() OVER (
             PARTITION BY tb.tournament_id, s.user_id ORDER BY s.joined_at DESC NULLS LAST
           ) AS rn
      FROM public.table_seats s
      JOIN public.tables tb ON tb.id = s.table_id
     WHERE s.left_at IS NULL AND tb.tournament_id IS NOT NULL
  ), upd AS (
    UPDATE public.tournament_players tp
       SET table_id = ls.table_id, seat_number = ls.seat_number
      FROM live_seat ls
     WHERE ls.rn = 1
       AND tp.tournament_id = ls.tournament_id
       AND tp.user_id = ls.user_id
       AND tp.status IN ('registered', 'playing')
       AND (tp.table_id IS DISTINCT FROM ls.table_id
         OR tp.seat_number IS DISTINCT FROM ls.seat_number)
    RETURNING 1
  ) SELECT count(*) INTO v_roster FROM upd;

  -- The stakes branch was here. zzzzzz_tables_stakes_follows_its_own_blinds
  -- owns public.tables.stakes on UPDATE and
  -- tournament_table_inherits_committed_blinds owns it on INSERT. Do not add
  -- a third writer: if this column ever drifts again, the trigger is what was
  -- bypassed, and a minutely UPDATE would only hide that.

  -- The duplicate-table branch was here. A seat-first game gets exactly one
  -- joinable table from fn_create_seat_first_game_atomic, under a per-event
  -- lock, so there is no duplicate to close. Its own seat-first test read
  -- every mtt-v2 event as seat-first (max_players is NULL by contract) and
  -- closed that event's launch tables while they were still being filled.
  -- Do not add it back: a second table on a seat-first game means the
  -- creation door was bypassed, and closing it a minute later would hide that.

  -- The player-count branch was here. The column is owned in the
  -- transaction that changes the field: fn_sync_tournament_current_players
  -- (pre-start, and every RUNNING bust or re-entry), the admission doors (a
  -- RUNNING admission) and fn_sync_seat_first_player_count (seat-first
  -- formats). A fourth writer a minute later is what made the count lag
  -- every bust and what overwrote every mtt-v2 field with one table.

  RETURN jsonb_build_object(
    'roster_rows_fixed',   v_roster,
    'stakes_rows_fixed',   0,
    'stakes_owner',        'zzzzzz_tables_stakes_follows_its_own_blinds',
    'empty_dupes_closed',  v_dupes,
    'empty_dupes_owner',   'fn_create_seat_first_game_atomic',
    'player_counts_fixed', v_counts,
    'player_counts_owner', 'fn_sync_tournament_current_players + fn_sync_seat_first_player_count'
  );
END;
$$;


ALTER FUNCTION public.fn_reconcile_tournament_denormals() OWNER TO postgres;

--
-- TOC entry 6261 (class 1255 OID 34785590)
-- Name: fn_record_accounting_tournament_cancellation(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_record_accounting_tournament_cancellation(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$DECLARE t record;raw record;reason text;result jsonb;BEGIN
 SELECT id,club_id,union_id,is_private INTO t FROM public.tournaments WHERE id=p_tournament_id;
 IF NOT FOUND OR public.fn_poker_diamond_tournament(p_tournament_id) THEN
  RAISE EXCEPTION 'chip_tournament_cancellation_required' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tournament_cancellation_receipts c WHERE c.tournament_id=p_tournament_id
   AND c.total_rake_after=0 AND c.fees_reversed=c.total_rake_before)
  OR (SELECT COALESCE(sum(rake_amount),0) FROM public.rake_records WHERE tournament_id=p_tournament_id AND is_tournament)<>0 THEN
  RAISE EXCEPTION 'tournament_cancellation_exact_zero_receipt_required' USING ERRCODE='23514'; END IF;
 -- A registration and cancellation can share one transaction. Its deferred
 -- capture hook has not fired yet; capture the original immutable charge now.
 -- This does not rewrite the raw fee sealed by the cancellation receipt.
 FOR raw IN SELECT r.id FROM public.rake_records r WHERE r.tournament_id=p_tournament_id AND r.is_tournament
  AND r.rake_amount>0 AND r.created_at=transaction_timestamp()
  AND NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches b WHERE b.rake_record_id=r.id) ORDER BY r.id LOOP
  PERFORM public.fn_stamp_accounting_tournament_fee(raw.id);
 END LOOP;
 BEGIN
  result:=public.fn_recognize_accounting_tournament_fees(p_tournament_id,transaction_timestamp(),t.club_id,NULL,NULL);
 EXCEPTION WHEN SQLSTATE '55000' THEN
  reason:=SQLERRM;
  IF reason NOT IN('tournament_fee_sources_require_reconciliation','accounting_terms_not_observed','accounting_terms_not_active','tournament_fee_not_captured_by_original_producer') THEN RAISE; END IF;
  result:=public.fn_defer_accounting_tournament_fees(p_tournament_id,transaction_timestamp(),t.club_id,
   CASE WHEN t.is_private THEN NULL ELSE t.union_id END,NULL,NULL,reason);
 END;
 RETURN result;
END$$;


ALTER FUNCTION public.fn_record_accounting_tournament_cancellation(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 6036 (class 1255 OID 21337157)
-- Name: fn_record_card_slide_usage(integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_record_card_slide_usage(p_started integer DEFAULT 0, p_committed integer DEFAULT 0, p_abandoned integer DEFAULT 0, p_keyboard integer DEFAULT 0) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_started integer := LEAST(GREATEST(COALESCE(p_started, 0), 0), 500);
  v_committed integer := LEAST(GREATEST(COALESCE(p_committed, 0), 0), 500);
  v_abandoned integer := LEAST(GREATEST(COALESCE(p_abandoned, 0), 0), 500);
  v_keyboard integer := LEAST(GREATEST(COALESCE(p_keyboard, 0), 0), 500);
BEGIN
  IF v_user IS NULL THEN
    RETURN;
  END IF;
  IF v_started + v_committed + v_abandoned + v_keyboard = 0 THEN
    RETURN;
  END IF;

  INSERT INTO public.card_slide_usage AS c (
    day, user_id, peels_started, peels_committed, peels_abandoned, keyboard_opens
  )
  VALUES (
    (now() AT TIME ZONE 'utc')::date, v_user, v_started, v_committed, v_abandoned, v_keyboard
  )
  ON CONFLICT (day, user_id) DO UPDATE SET
    peels_started = c.peels_started + EXCLUDED.peels_started,
    peels_committed = c.peels_committed + EXCLUDED.peels_committed,
    peels_abandoned = c.peels_abandoned + EXCLUDED.peels_abandoned,
    keyboard_opens = c.keyboard_opens + EXCLUDED.keyboard_opens,
    updated_at = now();
END $$;


