-- TOC entry 48589 (class 0 OID 0)
-- Dependencies: 5260
-- Name: FUNCTION fn_record_cashier_operation(p_club_id uuid, p_event text, p_operation text, p_duration_ms integer, p_item_count integer, p_page_number integer, p_success_count integer, p_failure_count integer, p_reason_code text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_record_cashier_operation(p_club_id uuid, p_event text, p_operation text, p_duration_ms integer, p_item_count integer, p_page_number integer, p_success_count integer, p_failure_count integer, p_reason_code text) IS 'Records one bounded Cashier SLO event for auth.uid() after validating active club cashier scope. The browser cannot choose user_id or sample_weight.';


--
-- TOC entry 6533 (class 1255 OID 83454225)
-- Name: fn_record_diamond_scene(text, text, boolean, integer, integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_record_diamond_scene(p_game text, p_device text, p_software boolean DEFAULT false, p_end_tier integer DEFAULT 0, p_frames integer DEFAULT 0, p_ms integer DEFAULT 0, p_slow integer DEFAULT 0, p_failure text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_frames integer := LEAST(GREATEST(COALESCE(p_frames, 0), 0), 500000);
  v_ms integer := LEAST(GREATEST(COALESCE(p_ms, 0), 0), 3600000);
  v_slow integer;
  v_tier smallint := LEAST(GREATEST(COALESCE(p_end_tier, 0), 0), 5)::smallint;
  v_failure text := NULLIF(p_failure, '');
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN;
  END IF;
  IF p_game IS NULL OR p_game NOT IN ('crash', 'plinko', 'crossing', 'wheel') THEN
    RETURN;
  END IF;
  IF p_device IS NULL OR p_device NOT IN ('app_ios', 'app_android', 'ios_web', 'android_web', 'desktop') THEN
    RETURN;
  END IF;
  IF v_failure IS NOT NULL AND v_failure NOT IN ('renderer', 'context_lost', 'stalled') THEN
    RETURN;
  END IF;
  v_slow := LEAST(GREATEST(COALESCE(p_slow, 0), 0), v_frames);
  IF v_failure IS NULL AND (v_frames = 0 OR v_ms = 0) THEN
    RETURN;
  END IF;

  INSERT INTO public.diamond_scene_daily AS d (
    day, game, device, software, end_tier, sessions, moving_frames, moving_ms, slow_frames,
    failed_renderer, failed_context_lost, failed_stalled
  )
  VALUES (
    (now() AT TIME ZONE 'utc')::date, p_game, p_device, COALESCE(p_software, false), v_tier,
    CASE WHEN v_failure IS NULL THEN 1 ELSE 0 END,
    CASE WHEN v_failure IS NULL THEN v_frames ELSE 0 END,
    CASE WHEN v_failure IS NULL THEN v_ms ELSE 0 END,
    CASE WHEN v_failure IS NULL THEN v_slow ELSE 0 END,
    CASE WHEN v_failure = 'renderer' THEN 1 ELSE 0 END,
    CASE WHEN v_failure = 'context_lost' THEN 1 ELSE 0 END,
    CASE WHEN v_failure = 'stalled' THEN 1 ELSE 0 END
  )
  ON CONFLICT (day, game, device, software, end_tier) DO UPDATE SET
    sessions = d.sessions + EXCLUDED.sessions,
    moving_frames = d.moving_frames + EXCLUDED.moving_frames,
    moving_ms = d.moving_ms + EXCLUDED.moving_ms,
    slow_frames = d.slow_frames + EXCLUDED.slow_frames,
    failed_renderer = d.failed_renderer + EXCLUDED.failed_renderer,
    failed_context_lost = d.failed_context_lost + EXCLUDED.failed_context_lost,
    failed_stalled = d.failed_stalled + EXCLUDED.failed_stalled,
    updated_at = now();
END $$;


ALTER FUNCTION public.fn_record_diamond_scene(p_game text, p_device text, p_software boolean, p_end_tier integer, p_frames integer, p_ms integer, p_slow integer, p_failure text) OWNER TO postgres;

--
-- TOC entry 8081 (class 1255 OID 30218833)
-- Name: fn_record_engine_alerts(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_record_engine_alerts(p_alerts jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  v_alert jsonb;
  v_event_id uuid;
  v_existing public.engine_alert_delivery_receipts%rowtype;
  v_id bigint;
  v_existing_row public.engine_alerts%rowtype;
  v_lock_key bigint;
  v_receipts jsonb := '[]'::jsonb;
begin
  if p_alerts is null or jsonb_typeof(p_alerts) <> 'array'
     or jsonb_array_length(p_alerts) > 200 or pg_column_size(p_alerts) > 262144 then
    raise exception using errcode = '22023', message = 'Malformed engine alert batch';
  end if;
  -- Validate every member before any insert. The whole function is atomic,
  -- including later cast errors or a producer-ID collision within this batch.
  for v_alert in select value from jsonb_array_elements(p_alerts) loop
    if jsonb_typeof(v_alert) <> 'object'
       or jsonb_typeof(v_alert->'labels') is distinct from 'object'
       or jsonb_typeof(v_alert->'labels'->'alertname') is distinct from 'string'
       or btrim(v_alert->'labels'->>'alertname') = ''
       or (v_alert->>'status') is null or (v_alert->>'status') not in ('firing', 'resolved') then
      raise exception using errcode = '22023', message = 'Malformed engine alert';
    end if;
    if (v_alert->'labels') ? 'engine_alert_event_id' and
       (jsonb_typeof(v_alert->'labels'->'engine_alert_event_id') is distinct from 'string'
        or (v_alert->'labels'->>'engine_alert_event_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then
      raise exception using errcode = '22023', message = 'Malformed engine event ID';
    end if;
  end loop;
  -- Lock in a consistent order for overlapping/reversed multi-alert batches.
  -- Serializing the missing-row case prevents concurrent retries from creating
  -- an orphan engine_alerts row before the unique receipt becomes visible.
  for v_lock_key in
    select distinct hashtextextended('engine-alert-event:' || (value->'labels'->>'engine_alert_event_id')::uuid::text, 0)
    from jsonb_array_elements(p_alerts)
    where (value->'labels') ? 'engine_alert_event_id'
    order by 1
  loop
    perform pg_advisory_xact_lock(v_lock_key);
  end loop;

  for v_alert in select value from jsonb_array_elements(p_alerts) loop
    v_event_id := (v_alert->'labels'->>'engine_alert_event_id')::uuid;
    if v_event_id is not null then
      select * into v_existing from public.engine_alert_delivery_receipts where event_id = v_event_id;
      if found then
        if v_existing.payload is distinct from v_alert then
          raise exception using errcode = '23505', message = 'Engine event ID already belongs to different payload';
        end if;
        -- An old producer receipt alone is not an inbox acknowledgement.
        select * into strict v_existing_row from public.engine_alerts
          where id = v_existing.engine_alert_id for update;
        perform operational_source_intake.record_engine(v_existing_row,'replay');
        v_receipts := v_receipts || jsonb_build_array(jsonb_build_object('id', v_existing.engine_alert_id, 'event_id', v_event_id));
        continue;
      end if;
    end if;

    insert into public.engine_alerts
      (fingerprint, alertname, severity, component, status, summary, description,
       labels, starts_at, ends_at, notified_via)
    values
      (coalesce(nullif(v_alert->>'fingerprint', ''), (v_alert->'labels'->>'alertname') || '-' || coalesce(v_alert->>'startsAt', '')),
       v_alert->'labels'->>'alertname', coalesce(nullif(v_alert->'labels'->>'severity', ''), 'unknown'),
       v_alert->'labels'->>'component', v_alert->>'status',
       v_alert->'annotations'->>'summary', v_alert->'annotations'->>'description',
       v_alert->'labels', nullif(v_alert->>'startsAt', '')::timestamptz,
       case when v_alert->>'endsAt' like '0001%' then null else nullif(v_alert->>'endsAt', '')::timestamptz end,
       array['codex-inbox']) returning id into v_id;
    if v_event_id is not null then
      insert into public.engine_alert_delivery_receipts(event_id, engine_alert_id, payload)
        values(v_event_id, v_id, v_alert);
    end if;
    v_receipts := v_receipts || jsonb_build_array(jsonb_build_object('id', v_id, 'event_id', v_event_id));
  end loop;
  return v_receipts;
end;
$_$;


ALTER FUNCTION public.fn_record_engine_alerts(p_alerts jsonb) OWNER TO postgres;

