--
-- TOC entry 9350 (class 1255 OID 30208872)
-- Name: fn_record_operational_alert(text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_record_operational_alert(p_source text, p_event_key text, p_alertname text, p_status text, p_severity text, p_payload jsonb) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_id bigint;
BEGIN
  -- A repeat delivery bumps the receipt. It never rewrites evidence, and it
  -- never changes a destination the row already names. The one thing it adds
  -- is the destination a row recorded before its writer addressed alerts:
  -- without it, a long-running alert first recorded unaddressed stays out of
  -- the owning lane for as long as it keeps firing.
  --
  -- AN INFORMATIONAL EVENT IS RECORDED INFORMATIONAL (2026-10-15). A row
  -- whose writer says status 'info' AND severity 'info' is a record, not an
  -- incident: the hourly "Accounting Documents Issued (Owner Copy)" summary
  -- (20260927143752) and the per-release receipts of a Post-Deploy episode
  -- (the episode's own firing row is the alert). It lands as 'informational',
  -- which the fleet does not triage, instead of 'new', which it must close by
  -- hand every hour. Everything else still lands 'new'.
  INSERT INTO public.operational_alert_events(source,event_key,alertname,status,severity,payload,investigation_status)
  VALUES(p_source,p_event_key,p_alertname,p_status,p_severity,p_payload,
         CASE WHEN p_status = 'info' AND p_severity = 'info' THEN 'informational' ELSE 'new' END)
  ON CONFLICT (source,event_key) DO UPDATE
  SET last_received_at=clock_timestamp(), delivery_count=operational_alert_events.delivery_count+1,
      payload=CASE
        WHEN jsonb_typeof(operational_alert_events.payload)='object'
         AND NOT (operational_alert_events.payload ? 'target_task_id')
         AND jsonb_typeof(EXCLUDED.payload->'target_task_id')='string'
        THEN operational_alert_events.payload
             || jsonb_build_object('target_task_id',EXCLUDED.payload->'target_task_id')
        ELSE operational_alert_events.payload END
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


ALTER FUNCTION public.fn_record_operational_alert(p_source text, p_event_key text, p_alertname text, p_status text, p_severity text, p_payload jsonb) OWNER TO postgres;

--
-- TOC entry 7529 (class 1255 OID 30208873)
-- Name: fn_record_operational_alerts(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_record_operational_alerts(p_events jsonb) RETURNS bigint[]
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_event jsonb; v_ids bigint[] := '{}';
BEGIN
  IF jsonb_typeof(p_events) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_events) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'expected 1 to 200 alert events';
  END IF;
  FOR v_event IN SELECT value FROM jsonb_array_elements(p_events) LOOP
    v_ids := array_append(v_ids, public.fn_record_operational_alert(
      v_event->>'source',v_event->>'event_key',v_event->>'alertname',
      v_event->>'status',v_event->>'severity',v_event->'payload'));
  END LOOP;
  RETURN v_ids;
END;
$$;


ALTER FUNCTION public.fn_record_operational_alerts(p_events jsonb) OWNER TO postgres;

--
-- TOC entry 5808 (class 1255 OID 31345050)
-- Name: fn_record_ticker_usage(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_record_ticker_usage(p_counts jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_source text;
  v_entry jsonb;
  v_shown int;
  v_opened int;
  v_dismissed int;
  v_written int := 0;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;
  IF p_counts IS NULL OR jsonb_typeof(p_counts) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_payload');
  END IF;

  FOR v_source, v_entry IN SELECT * FROM jsonb_each(p_counts) LOOP
    CONTINUE WHEN jsonb_typeof(v_entry) <> 'object';
    CONTINUE WHEN v_source NOT IN (
      'overlays', 'starting_soon', 'registration_closing', 'guarantees',
      'table_openings', 'winner_results', 'maintenance', 'custom_messages'
    );

    v_shown     := GREATEST(0, COALESCE((v_entry->>'shown')::int, 0));
    v_opened    := GREATEST(0, COALESCE((v_entry->>'opened')::int, 0));
    v_dismissed := GREATEST(0, COALESCE((v_entry->>'dismissed')::int, 0));
    CONTINUE WHEN v_shown + v_opened + v_dismissed = 0;

    INSERT INTO public.ca_ticker_usage_daily AS u
      (day, user_id, source, shown, opened, dismissed)
    VALUES
      ((now() AT TIME ZONE 'utc')::date, v_uid, v_source, v_shown, v_opened, v_dismissed)
    ON CONFLICT (day, user_id, source) DO UPDATE
      SET shown      = u.shown + EXCLUDED.shown,
          opened     = u.opened + EXCLUDED.opened,
          dismissed  = u.dismissed + EXCLUDED.dismissed,
          updated_at = now();
    v_written := v_written + 1;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'sources', v_written);
END;
$$;


ALTER FUNCTION public.fn_record_ticker_usage(p_counts jsonb) OWNER TO postgres;

--
-- TOC entry 5288 (class 1255 OID 4916621)
-- Name: fn_record_tos_acceptance(uuid, text, text, inet, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_record_tos_acceptance(p_caller_user_id uuid, p_policy_key text, p_policy_version text, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_expected_version text;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_caller_user_id THEN
    RAISE EXCEPTION 'UNAUTHORIZED';
  END IF;

  IF p_policy_key NOT IN (
    'home_games.tos',
    'home_games.privacy',
    'home_games.community_guidelines',
    'home_games.money_policy',
    'home_games.jurisdiction'
  ) THEN
    RAISE EXCEPTION 'INVALID_POLICY_KEY';
  END IF;

  -- Verify the version matches the CURRENT version the platform
  -- advertises (prevents clients from submitting stale versions).
  SELECT value INTO v_expected_version
    FROM public.platform_policies
   WHERE key = p_policy_key || '.version';
  IF v_expected_version IS NOT NULL AND v_expected_version <> p_policy_version THEN
    RAISE EXCEPTION 'STALE_POLICY_VERSION'
          USING HINT = 'current version is ' || v_expected_version;
  END IF;

  INSERT INTO public.user_tos_acceptances
    (user_id, policy_key, policy_version, ip_address, user_agent)
  VALUES
    (p_caller_user_id, p_policy_key, p_policy_version, p_ip_address, p_user_agent)
  ON CONFLICT (user_id, policy_key, policy_version) DO NOTHING
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'success',      true,
    'acceptance_id', v_id,
    'policy_key',    p_policy_key,
    'policy_version', p_policy_version
  );
END;
$$;


ALTER FUNCTION public.fn_record_tos_acceptance(p_caller_user_id uuid, p_policy_key text, p_policy_version text, p_ip_address inet, p_user_agent text) OWNER TO postgres;

--
-- TOC entry 3370 (class 1255 OID 66931343)
-- Name: fn_record_unconfirmed_time_bank_consume(uuid, uuid, integer, uuid, text, text, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_record_unconfirmed_time_bank_consume(p_attempt_id uuid, p_user_id uuid, p_seconds integer, p_table_id uuid, p_engine_instance text, p_reason text, p_tournament_id uuid DEFAULT NULL::uuid, p_hand_number bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE
  v_existing smarter_private.time_bank_consume_unconfirmed;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'fn_record_unconfirmed_time_bank_consume is engine-only';
  END IF;
  IF p_attempt_id IS NULL OR p_user_id IS NULL OR p_table_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'refused', 'incomplete_attestation');
  END IF;
  IF p_seconds IS NULL OR p_seconds <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'refused', 'seconds_not_positive');
  END IF;
  IF p_engine_instance IS NULL OR length(p_engine_instance) = 0
     OR p_reason IS NULL OR length(p_reason) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'refused', 'unnamed_attempt');
  END IF;

  /* The engine chose this id before it sent the debit, so the SAME unanswered
     debit recorded twice is one row, and a genuinely different debit cannot
     collide with it. A replay whose terms disagree is not this attempt and is
     refused rather than silently folded into it. */
  SELECT * INTO v_existing
    FROM smarter_private.time_bank_consume_unconfirmed t
   WHERE t.attempt_id = p_attempt_id;
  IF FOUND THEN
    IF (v_existing.user_id, v_existing.seconds, v_existing.table_id)
       IS DISTINCT FROM (p_user_id, p_seconds, p_table_id) THEN
      RETURN jsonb_build_object('ok', false, 'refused', 'attempt_terms_differ',
                                'attempt_id', p_attempt_id);
    END IF;
    RETURN jsonb_build_object('ok', true, 'attempt_id', p_attempt_id, 'replayed', true);
  END IF;

  INSERT INTO smarter_private.time_bank_consume_unconfirmed
    (attempt_id, user_id, seconds, table_id, tournament_id, hand_number,
     engine_instance, reason)
  VALUES
    (p_attempt_id, p_user_id, p_seconds, p_table_id, p_tournament_id, p_hand_number,
     left(p_engine_instance, 200), left(p_reason, 500))
  ON CONFLICT (attempt_id) DO NOTHING;

  RETURN jsonb_build_object('ok', true, 'attempt_id', p_attempt_id, 'replayed', false);
END
$$;


ALTER FUNCTION public.fn_record_unconfirmed_time_bank_consume(p_attempt_id uuid, p_user_id uuid, p_seconds integer, p_table_id uuid, p_engine_instance text, p_reason text, p_tournament_id uuid, p_hand_number bigint) OWNER TO postgres;

--
-- TOC entry 48605 (class 0 OID 0)
-- Dependencies: 3370
-- Name: FUNCTION fn_record_unconfirmed_time_bank_consume(p_attempt_id uuid, p_user_id uuid, p_seconds integer, p_table_id uuid, p_engine_instance text, p_reason text, p_tournament_id uuid, p_hand_number bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_record_unconfirmed_time_bank_consume(p_attempt_id uuid, p_user_id uuid, p_seconds integer, p_table_id uuid, p_engine_instance text, p_reason text, p_tournament_id uuid, p_hand_number bigint) IS 'Record one fn_consume_time_bank debit whose outcome the engine never learned, under the id the engine chose before it sent it. Exactly-once by that id; refuses a replay whose terms differ. Debits nothing and grants nothing: it makes an unknown durable so no engine has to hold it in memory forever. 2026-09-28.';


