--

CREATE TABLE public.video_source_ingestion_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    operation_id uuid NOT NULL,
    source_id uuid,
    source_name text NOT NULL,
    topic text NOT NULL,
    ingestion_mode text NOT NULL,
    status text NOT NULL,
    candidates integer DEFAULT 0 NOT NULL,
    qualified integer DEFAULT 0 NOT NULL,
    inserted integer DEFAULT 0 NOT NULL,
    duplicates integer DEFAULT 0 NOT NULL,
    rejected integer DEFAULT 0 NOT NULL,
    quota_units integer DEFAULT 0 NOT NULL,
    failure_code text,
    cursor_before jsonb DEFAULT '{}'::jsonb NOT NULL,
    cursor_after jsonb DEFAULT '{}'::jsonb NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT video_source_ingestion_runs_candidates_check CHECK ((candidates >= 0)),
    CONSTRAINT video_source_ingestion_runs_duplicates_check CHECK ((duplicates >= 0)),
    CONSTRAINT video_source_ingestion_runs_inserted_check CHECK ((inserted >= 0)),
    CONSTRAINT video_source_ingestion_runs_qualified_check CHECK ((qualified >= 0)),
    CONSTRAINT video_source_ingestion_runs_quota_units_check CHECK ((quota_units >= 0)),
    CONSTRAINT video_source_ingestion_runs_rejected_check CHECK ((rejected >= 0)),
    CONSTRAINT video_source_ingestion_runs_status_check CHECK ((status = ANY (ARRAY['running'::text, 'succeeded'::text, 'empty'::text, 'failed'::text, 'quota_stopped'::text]))),
    CONSTRAINT video_source_ingestion_runs_topic_check CHECK ((topic = ANY (ARRAY['poker'::text, 'casino_slots'::text, 'sports'::text])))
);


