--
-- TOC entry 4884 (class 1255 OID 91844345)
-- Name: fn_record_video_source_observation(uuid, uuid, text, integer, integer, integer, integer, integer, integer, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_record_video_source_observation(p_operation_id uuid, p_source_id uuid, p_status text, p_candidates integer, p_qualified integer, p_inserted integer, p_duplicates integer, p_rejected integer, p_quota_units integer, p_cursor_before jsonb, p_cursor_after jsonb, p_failure_code text DEFAULT NULL::text) RETURNS public.video_source_ingestion_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_source public.content_sources%ROWTYPE;
  v_run public.video_source_ingestion_runs%ROWTYPE;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required' USING ERRCODE = '42501';
  END IF;
  IF p_status NOT IN ('succeeded', 'empty', 'failed', 'quota_stopped') THEN
    RAISE EXCEPTION 'invalid terminal ingestion status';
  END IF;
  IF least(p_candidates, p_qualified, p_inserted, p_duplicates, p_rejected, p_quota_units) < 0 THEN
    RAISE EXCEPTION 'ingestion counts cannot be negative';
  END IF;

  SELECT * INTO v_run FROM public.video_source_ingestion_runs
  WHERE operation_id = p_operation_id;
  IF FOUND THEN RETURN v_run; END IF;

  SELECT * INTO v_source FROM public.content_sources WHERE id = p_source_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown content source'; END IF;

  INSERT INTO public.video_source_ingestion_runs (
    operation_id, source_id, source_name, topic, ingestion_mode, status,
    candidates, qualified, inserted, duplicates, rejected, quota_units,
    failure_code, cursor_before, cursor_after, completed_at
  ) VALUES (
    p_operation_id, v_source.id, v_source.name, v_source.ingest_topic,
    v_source.ingestion_mode, p_status, p_candidates, p_qualified, p_inserted,
    p_duplicates, p_rejected, p_quota_units, p_failure_code,
    coalesce(p_cursor_before, '{}'::jsonb), coalesce(p_cursor_after, '{}'::jsonb), now()
  )
  RETURNING * INTO v_run;

  UPDATE public.content_sources SET
    provider_cursor = CASE WHEN p_status IN ('succeeded', 'empty') THEN coalesce(p_cursor_after, provider_cursor) ELSE provider_cursor END,
    last_checked_at = now(),
    last_success_at = CASE WHEN p_status IN ('succeeded', 'empty') THEN now() ELSE last_success_at END,
    last_new_item_at = CASE WHEN p_status = 'succeeded' AND p_inserted > 0 THEN now() ELSE last_new_item_at END,
    last_empty_success_at = CASE WHEN p_status = 'empty' THEN now() ELSE last_empty_success_at END,
    last_failure_at = CASE WHEN p_status = 'failed' THEN now() ELSE last_failure_at END,
    last_failure_code = CASE WHEN p_status IN ('succeeded', 'empty') THEN NULL ELSE p_failure_code END,
    consecutive_failures = CASE WHEN p_status IN ('succeeded', 'empty') THEN 0 ELSE consecutive_failures + 1 END,
    last_candidate_count = p_candidates,
    last_qualified_count = p_qualified,
    quota_units_last_run = v_run.quota_units,
    clips_found = clips_found + p_inserted,
    last_scraped_at = now(),
    last_ok_at = CASE WHEN p_status IN ('succeeded', 'empty') THEN now() ELSE last_ok_at END,
    updated_at = now()
  WHERE id = p_source_id;

  RETURN v_run;
END;
$$;


ALTER FUNCTION public.fn_record_video_source_observation(p_operation_id uuid, p_source_id uuid, p_status text, p_candidates integer, p_qualified integer, p_inserted integer, p_duplicates integer, p_rejected integer, p_quota_units integer, p_cursor_before jsonb, p_cursor_after jsonb, p_failure_code text) OWNER TO postgres;

--
-- TOC entry 6880 (class 1255 OID 16084935)
-- Name: fn_redeem_club_invite_code(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_redeem_club_invite_code(p_club_id uuid, p_user_id uuid, p_referral_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_caller            uuid := auth.uid();
  v_code              text := btrim(coalesce(p_referral_code, ''));
  v_inviter           record;
  v_inviter_member    record;
  v_member            record;
  v_effective_agent   uuid;
  v_is_agent          boolean;
  v_agent_name        text;
  v_new_status        text;
  v_attr              record;
  v_inviter_settled   boolean;
  v_club_name         text;
  v_link_code         text;
  v_joiner_alias      text;
  v_code_inviter      uuid;
  v_prev_status       text;
  v_prev_agent        uuid;
  v_prev_invited      uuid;
  v_changed           boolean;
BEGIN
  -- ── Authorization ────────────────────────────────────────────────────────
  IF v_caller IS NOT NULL AND v_caller <> p_user_id THEN
    RETURN jsonb_build_object('success', false, 'code', 'not_your_membership',
                              'error', 'You can only redeem an invite for yourself.');
  END IF;

  IF v_code = '' THEN
    RETURN jsonb_build_object('success', false, 'code', 'empty_code',
                              'error', 'No referral code supplied.');
  END IF;

  -- ── KingFish's referral ID is his name (Dan, 2026-10-16) ─────────────────
  -- Player 1 is the only named referral ID on the platform; everyone else's
  -- is their player number. The name is matched case-insensitively and turned
  -- back into his player number here, so every check below (first link wins,
  -- self-referral, membership) runs exactly as it does for a number. Mirrors
  -- src/lib/referralId.ts.
  IF lower(v_code) = 'kingfish' THEN
    v_code := '1';
  END IF;

  -- ── 0. First link wins ───────────────────────────────────────────────────
  -- A player who arrived through an attributed invite belongs to THAT inviter,
  -- whatever ?ref= a later link carries.
  SELECT p.id INTO v_code_inviter
    FROM profiles p
   WHERE p.player_number = v_code
      OR (v_code ~ '^[0-9]+$' AND p.player_number ~ '^[0-9]+$'
          AND p.player_number::bigint = v_code::bigint)
      OR (v_code ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND p.id = v_code::uuid)
   LIMIT 1;

  -- An unjoined attribution lapses after 30 days, as it does everywhere else.
  DELETE FROM club_invite_attributions
   WHERE user_id = p_user_id AND club_id = p_club_id
     AND status IN ('signed_up', 'verified')
     AND claimed_at <= now() - interval '30 days';

  SELECT * INTO v_attr FROM club_invite_attributions
   WHERE user_id = p_user_id AND club_id = p_club_id
   FOR UPDATE;

  -- A self-referral block binds only the inviter it was raised against. A
  -- different inviter's code places the player normally.
  IF v_attr.id IS NOT NULL AND v_attr.status = 'blocked'
     AND v_code_inviter IS NOT NULL AND v_code_inviter <> v_attr.inviter_id THEN
    DELETE FROM club_invite_attributions WHERE id = v_attr.id;
    SELECT * INTO v_attr FROM club_invite_attributions
     WHERE user_id = p_user_id AND club_id = p_club_id;
  END IF;

  IF v_attr.id IS NOT NULL AND v_attr.status = 'blocked' THEN
    -- A refused self-referral neither admits nor places. The player keeps the
    -- membership exactly as fn_join_club made it (pending clubs stay pending
    -- for the owner).
    SELECT * INTO v_member FROM club_members WHERE club_id = p_club_id AND user_id = p_user_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'code', 'not_a_member',
                                'error', 'User is not a member of this club.');
    END IF;
    RETURN jsonb_build_object('success', true, 'status', v_member.status,
                              'agent_id', v_member.agent_id, 'referral_skipped', v_attr.block_reason);
  END IF;

  -- ── 1. Resolve the inviter ───────────────────────────────────────────────
  IF v_attr.id IS NOT NULL THEN
    SELECT p.id, p.username, p.player_number INTO v_inviter FROM profiles p WHERE p.id = v_attr.inviter_id;
  ELSE
    SELECT p.id, p.username, p.player_number INTO v_inviter FROM profiles p WHERE p.id = v_code_inviter;
  END IF;

  IF v_inviter.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'code', 'unknown_inviter',
                              'error', 'Invalid referral code.');
  END IF;

  IF v_inviter.id = p_user_id THEN
    RETURN jsonb_build_object('success', false, 'code', 'self_referral',
                              'error', 'You cannot invite yourself.');
  END IF;

  -- ── 2. Inviter standing ──────────────────────────────────────────────────
  -- An inviter who has left the club or been suspended no longer fails the
  -- join (Dan 2026-10-15): the player is routed to the club owner instead. Such
  -- an invite does not ADMIT on its own, though - the owner approves.
  SELECT * INTO v_inviter_member
    FROM club_members
   WHERE club_id = p_club_id AND user_id = v_inviter.id;

  v_inviter_settled := FOUND AND v_inviter_member.status IN ('active', 'approved', 'automatic');

  -- ── 3. Effective upline ──────────────────────────────────────────────────
  IF v_inviter_settled THEN
    SELECT true INTO v_is_agent
      FROM agents
     WHERE club_id = p_club_id AND user_id = v_inviter.id AND status = 'active';

    IF coalesce(v_is_agent, false) THEN
      v_effective_agent := v_inviter.id;
    ELSE
      v_effective_agent := v_inviter_member.agent_id;
    END IF;
  ELSE
    v_effective_agent := NULL;   -- directly under the club owner
  END IF;

  -- ── 4. The joining user must already have a membership row ───────────────
  SELECT * INTO v_member
    FROM club_members
   WHERE club_id = p_club_id AND user_id = p_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'code', 'not_a_member',
                              'error', 'User is not a member of this club.');
  END IF;

  IF v_member.status NOT IN ('active', 'approved', 'automatic', 'pending') THEN
    RETURN jsonb_build_object('success', false, 'code', 'membership_blocked',
                              'error', 'This membership cannot be activated.');
  END IF;

  -- ── 5. Attach and admit ──────────────────────────────────────────────────
  v_new_status := CASE WHEN v_member.status = 'pending' AND v_inviter_settled THEN 'active' ELSE v_member.status END;
  -- ca-commerce-admission: an invite admitting a PENDING member makes a NEW
  -- approved member (R2 4.3, D22). Shadow records and proceeds; enforced
  -- keeps the member pending for the owner instead.
  IF v_member.status = 'pending' AND v_new_status = 'active' THEN
    PERFORM public.fn_club_membership_lock(p_user_id);
    DECLARE
      v_ca_admission jsonb := public.fn_ca_commerce_admit('club', p_club_id, 'join_member', 'fn_redeem_club_invite_code', p_user_id);
    BEGIN
      IF NOT COALESCE((v_ca_admission->>'allowed')::boolean, true) THEN
        v_new_status := 'pending';
      END IF;
    END;
  END IF;

  v_prev_status := v_member.status;
  v_prev_agent  := v_member.agent_id;
  v_prev_invited := v_member.invited_by;

  UPDATE club_members
     SET agent_id   = coalesce(agent_id, v_effective_agent),
         invited_by = coalesce(invited_by, v_inviter.id),
         status     = v_new_status,
         updated_at = now()
   WHERE club_id = p_club_id AND user_id = p_user_id
  RETURNING * INTO v_member;

  -- ── 6. Re-derive the upline's player counts ──────────────────────────────
  IF v_member.agent_id IS NOT NULL THEN
    UPDATE agents
       SET total_players = (SELECT count(*) FROM club_members
                             WHERE agent_id = v_member.agent_id AND club_id = p_club_id),
           active_player_count = (SELECT count(*) FROM club_members
                                   WHERE agent_id = v_member.agent_id AND club_id = p_club_id
                                     AND status IN ('active', 'approved')),
           updated_at = now()
     WHERE club_id = p_club_id AND user_id = v_member.agent_id;
  END IF;

  -- ── 7. Record the join against the invite and tell the inviter ───────────
  -- Only a call that actually did something is a join: the first redemption
  -- of a join in progress (it sets invited_by on a member still pending or
  -- created within the hour), an admission of a pending member, or a
  -- placement of one who had no upline. A long-standing member redeeming a
  -- code for the first time is not a join. Re-running an invite for a settled
  -- member records nothing and notifies nobody. The first redemption counts
  -- even when nothing else moves: a member the owner must still approve, or
  -- one placed directly under an owner who has no upline above them.
  v_changed := (v_prev_invited IS NULL AND v_member.invited_by IS NOT NULL
                AND (v_prev_status = 'pending' OR v_member.created_at > now() - interval '1 hour'))
               OR (v_prev_status = 'pending' AND v_member.status <> 'pending')
               OR (v_prev_agent IS NULL AND v_member.agent_id IS NOT NULL)
               OR v_attr.id IS NOT NULL;
  SELECT code INTO v_link_code FROM club_invite_links
   WHERE club_id = p_club_id AND inviter_id = v_inviter.id;

  IF v_attr.id IS NOT NULL THEN
    UPDATE club_invite_attributions
       SET status = 'joined', joined_at = COALESCE(joined_at, now())
     WHERE id = v_attr.id AND status IN ('signed_up', 'verified');
  ELSIF v_changed THEN
    INSERT INTO club_invite_attributions (code, club_id, inviter_id, user_id, status, joined_at)
    VALUES (v_link_code, p_club_id, v_inviter.id, p_user_id, 'joined', now())
    ON CONFLICT (user_id, club_id) DO NOTHING;
  END IF;

  IF v_changed AND (v_attr.id IS NULL OR v_attr.status IN ('signed_up', 'verified')) THEN
    SELECT name INTO v_club_name FROM clubs WHERE id = p_club_id;
    SELECT COALESCE(NULLIF(btrim(alias), ''), NULLIF(btrim(username), ''), 'A New Player') INTO v_joiner_alias FROM profiles WHERE id = p_user_id;
    PERFORM public.fn_club_invite_notify(
      v_inviter.id, 'club_invite_joined',
      CASE WHEN v_member.status = 'pending' THEN 'Your Invite Requested To Join' ELSE 'Your Invite Joined The Club' END,
      COALESCE(v_joiner_alias, 'A New Player')
        || CASE WHEN v_member.status = 'pending' THEN ' Requested To Join ' ELSE ' Joined ' END
        || COALESCE(v_club_name, 'Your Club') || ' From Your Invite.',
      '/hub/club-arena/clubs/' || p_club_id::text,
      jsonb_build_object('club_id', p_club_id, 'referee_id', p_user_id, 'agent_id', v_member.agent_id)
    );
  END IF;

  SELECT username INTO v_agent_name FROM profiles WHERE id = v_member.agent_id;

  RETURN jsonb_build_object(
    'success',     true,
    'status',      v_member.status,
    'agent_id',    v_member.agent_id,
    'agent_name',  v_agent_name,
    'inviter_id',  v_inviter.id,
    'inviter_name', v_inviter.username,
    'routed_to_owner', NOT v_inviter_settled
  );
END;
$_$;


ALTER FUNCTION public.fn_redeem_club_invite_code(p_club_id uuid, p_user_id uuid, p_referral_code text) OWNER TO postgres;

--
-- TOC entry 48609 (class 0 OID 0)
-- Dependencies: 6880
-- Name: FUNCTION fn_redeem_club_invite_code(p_club_id uuid, p_user_id uuid, p_referral_code text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_redeem_club_invite_code(p_club_id uuid, p_user_id uuid, p_referral_code text) IS 'Redeems a club invite/referral code for the CALLING user: attaches the upline agent (the inviter if they are an active agent, otherwise the inviter''s own agent), records invited_by, and promotes a pending membership to active. Never overwrites an existing agent_id and never changes a settled status. Fixed 2026-08-26: the previous body compared text player_number to an integer and therefore raised 42883 on every call since it was written.';


--
-- TOC entry 5724 (class 1255 OID 9730507)
-- Name: fn_redeem_shop_item(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_redeem_shop_item(p_inventory_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.club_shop_inventory%ROWTYPE;
  v_spec jsonb;
  v_type text;
  v_qty integer;
  v_granted jsonb := jsonb_build_object('type', 'none');
BEGIN
  SELECT * INTO v_row FROM public.club_shop_inventory
   WHERE id = p_inventory_id FOR UPDATE;
  IF v_row.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_found');
  END IF;
  IF v_row.user_id <> auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
  END IF;
  IF v_row.status = 'redeemed' THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_redeemed');
  END IF;
  IF v_row.status = 'refunded' THEN
    RETURN jsonb_build_object('success', false, 'error', 'refunded');
  END IF;

  v_spec := COALESCE(v_row.grant_snapshot, '{}'::jsonb);
  v_type := COALESCE(v_spec->>'type', 'none');
  v_qty := GREATEST(1, LEAST(1000, COALESCE((v_spec->>'qty')::integer, 1)));

  IF v_type = 'time_bank' THEN
    INSERT INTO public.feature_purchases
      (user_id, feature, cost, usage_type, uses_remaining, expires_at)
    VALUES (v_row.user_id, 'time_bank_seconds', 0, 'per_use', v_qty, NULL);
    v_granted := jsonb_build_object('type', 'time_bank', 'uses', v_qty, 'seconds', v_qty * 20);
  ELSIF v_type = 'throwable' THEN
    INSERT INTO public.feature_purchases
      (user_id, feature, cost, usage_type, uses_remaining, expires_at)
    VALUES (v_row.user_id, 'throwable', 0, 'per_use', v_qty, NULL);
    v_granted := jsonb_build_object('type', 'throwable', 'uses', v_qty);
  ELSIF v_type = 'emote_pack' THEN
    INSERT INTO public.feature_purchases
      (user_id, feature, cost, usage_type, uses_remaining, expires_at)
    VALUES (v_row.user_id, 'emoji_pack', 0, 'permanent', NULL, NULL);
    v_granted := jsonb_build_object('type', 'emote_pack', 'permanent', true);
  ELSIF v_type = 'table_skin' THEN
    INSERT INTO public.feature_purchases
      (user_id, feature, cost, usage_type, uses_remaining, expires_at)
    VALUES (v_row.user_id, 'theme_unlock', 0, 'permanent', NULL, NULL);
    v_granted := jsonb_build_object('type', 'table_skin', 'permanent', true,
                                    'theme_id', v_spec->>'theme_id');
  ELSIF v_type = 'avatar' THEN
    INSERT INTO public.avatar_unlocks (user_id, avatar_id, unlock_method)
    VALUES (v_row.user_id, COALESCE(v_spec->>'avatar_id', v_row.item_id::text), 'club_shop')
    ON CONFLICT DO NOTHING;
    v_granted := jsonb_build_object(
      'type', 'avatar', 'avatar_id', COALESCE(v_spec->>'avatar_id', v_row.item_id::text)
    );
  END IF;

  UPDATE public.club_shop_inventory
     SET status = 'redeemed', redeemed_at = now()
   WHERE id = p_inventory_id;

  RETURN jsonb_build_object(
    'success', true, 'item_name', v_row.item_name, 'granted', v_granted
  );
END;
$$;


ALTER FUNCTION public.fn_redeem_shop_item(p_inventory_id uuid) OWNER TO postgres;

--
-- TOC entry 5655 (class 1255 OID 14763923)
-- Name: fn_redeem_tournament_ticket(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_redeem_tournament_ticket(p_ticket_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_me uuid:=auth.uid();
  v_t public.tournament_tickets%ROWTYPE;
  v_after numeric;
  v_context jsonb;
  v_setting text;
  v_receipt public.chip_transactions%ROWTYPE;
  v_issue public.chip_transactions%ROWTYPE;
  v_escrow_entity uuid;
BEGIN
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','Not Authenticated');
  END IF;
  IF p_ticket_id IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','Choose A Ticket');
  END IF;

  SELECT * INTO v_t FROM public.tournament_tickets
   WHERE id=p_ticket_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success',false,'error','Ticket Not Found');
  END IF;
  IF v_t.redemption_mode='tournament_entry_only' THEN
    RETURN jsonb_build_object(
      'success',false,
      'error','Tournament-Entry Tickets Can Only Be Used To Enter A Tournament');
  END IF;
  -- 20261015132042: a cashier ticket bound to one tournament is used by
  -- registering for it. If that tournament closes unused, the closing
  -- transaction pays its holder in cash.
  IF EXISTS (SELECT 1 FROM public.tournament_ticket_entry_targets b
              WHERE b.ticket_id=p_ticket_id) THEN
    RETURN jsonb_build_object(
      'success',false,
      'error','This Ticket Is Used By Registering For Its Tournament');
  END IF;
  IF v_t.holder_id IS DISTINCT FROM v_me THEN
    RETURN jsonb_build_object('success',false,'error','This Ticket Is Not Yours');
  END IF;
  IF v_t.status='redeemed' THEN
    SELECT * INTO v_receipt FROM public.chip_transactions
     WHERE transaction_type='tournament_ticket_redeem'
       AND metadata->>'ticket_id'=p_ticket_id::text LIMIT 1;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'success',true,'replayed',true,'value',v_t.value,
        'your_balance',(v_receipt.metadata->>'holder_balance_after')::numeric,
        'transaction_id',v_receipt.id);
    END IF;
  END IF;
  IF v_t.status<>'issued' THEN
    RETURN jsonb_build_object(
      'success',false,'error','Ticket Already '||initcap(v_t.status));
  END IF;

  SELECT * INTO v_issue FROM public.chip_transactions
   WHERE transaction_type='tournament_ticket_issue'
     AND metadata->>'ticket_id'=p_ticket_id::text LIMIT 1;
  IF FOUND AND v_issue.metadata ? 'escrow_entity_id' THEN
    IF v_issue.club_id IS DISTINCT FROM v_t.club_id
       OR v_issue.from_user_id IS DISTINCT FROM v_t.issued_by
       OR v_issue.to_user_id IS DISTINCT FROM v_t.holder_id
       OR v_issue.amount IS DISTINCT FROM v_t.value
       OR v_issue.metadata->>'escrow_entity_id'
            IS DISTINCT FROM p_ticket_id::text THEN
      RAISE EXCEPTION 'Ticket escrow receipt does not match its entitlement'
        USING ERRCODE='22023';
    END IF;
    v_escrow_entity:=p_ticket_id;
  END IF;
  SELECT jsonb_object_agg(k,COALESCE(current_setting(k,true),''))
    INTO v_context
    FROM unnest(ARRAY[
      'app.ledger_category','app.ledger_counterparty',
      'app.ledger_counterparty_entity','app.ledger_tournament']) settings(k);
  PERFORM set_config('app.ledger_tournament','',true);
  PERFORM set_config('app.ledger_category','ticket_redeem',true);
  PERFORM set_config('app.ledger_counterparty','escrow',true);
  PERFORM set_config(
    'app.ledger_counterparty_entity',COALESCE(v_escrow_entity::text,''),true);
  UPDATE public.club_members
     SET chip_balance=COALESCE(chip_balance,0)+v_t.value,updated_at=now()
   WHERE club_id=v_t.club_id AND user_id=v_me
     AND COALESCE(status,'active') IN ('active','approved')
   RETURNING chip_balance INTO v_after;
  FOR v_setting IN SELECT jsonb_object_keys(v_context) LOOP
    PERFORM set_config(v_setting,v_context->>v_setting,true);
  END LOOP;
  IF v_after IS NULL THEN
    RETURN jsonb_build_object(
      'success',false,'error','You Are No Longer A Member Of That Club');
  END IF;

  UPDATE public.tournament_tickets
     SET status='redeemed',redeemed_at=now()
   WHERE id=p_ticket_id;
  INSERT INTO public.chip_transactions(
    club_id,from_user_id,to_user_id,amount,transaction_type,notes,
    balance_after,metadata)
  VALUES(
    v_t.club_id,NULL,v_me,v_t.value,'tournament_ticket_redeem',
    'Tournament Ticket Redeemed: Escrow Released',v_after,
    jsonb_build_object(
      'ticket_id',p_ticket_id,'issuer_id',v_t.issued_by,
      'holder_id',v_t.holder_id,'escrow_action','release_to_holder',
      'holder_balance_after',v_after))
  RETURNING * INTO v_receipt;

  INSERT INTO public.wallet_transactions(
    user_id,wallet_type,type,amount,category,description,balance_after)
  VALUES(
    v_me,'PLAYER','credit',v_t.value,'transfer',
    'Tournament Ticket Redeemed: Escrow Released',v_after);

  RETURN jsonb_build_object(
    'success',true,'replayed',false,'value',v_t.value,
    'your_balance',v_after,'transaction_id',v_receipt.id);
END;
$$;


