--
-- TOC entry 3919 (class 1255 OID 102610402)
-- Name: fn_refresh_video_learning_search_document(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_refresh_video_learning_search_document(p_video_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE r public.video_enrichment_records; v public.video_library_videos;
  v_title text; v_concepts text; v_chapters text:=''; v_transcript text:='';
  v_version integer:=1; v_vector tsvector;
BEGIN
  IF coalesce(auth.role()::text,'')<>'service_role' AND pg_trigger_depth()=0 THEN RAISE EXCEPTION 'service role required' USING ERRCODE='42501'; END IF;
  SELECT * INTO v FROM public.video_library_videos WHERE id=p_video_id;
  IF v.id IS NULL OR NOT public.fn_is_video_library_asset_eligible(p_video_id) THEN
    DELETE FROM public.video_learning_search_documents WHERE video_id=p_video_id;
    RETURN false;
  END IF;
  SELECT * INTO r FROM public.video_enrichment_records WHERE video_id=p_video_id;
  v_title:=v.title;
  SELECT coalesce(string_agg(tag,' '),'') INTO v_concepts
  FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v.tags)='array' THEN v.tags ELSE '[]'::jsonb END) tag;
  IF r.video_id IS NOT NULL AND r.workflow_state IN ('approved','published') THEN
    v_title:=coalesce(nullif(r.editorial_title,''),v.title);
    v_concepts:=coalesce(array_to_string(r.concepts,' '),v_concepts);
    SELECT coalesce(string_agg(concat_ws(' ',c->>'title',c->>'label',c->>'summary'),' '),'') INTO v_chapters
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(r.chapters)='array' THEN r.chapters ELSE '[]'::jsonb END) c;
    v_transcript:=coalesce(r.transcript_text,'');
    v_version:=r.version;
  END IF;
  v_vector:=setweight(to_tsvector('english',coalesce(v_title,'')),'A')
    ||setweight(to_tsvector('english',coalesce(v.source_name,'')),'A')
    ||setweight(to_tsvector('english',coalesce(v_concepts,'')),'B')
    ||setweight(to_tsvector('english',coalesce(v_chapters,'')),'B')
    ||setweight(to_tsvector('english',coalesce(v_transcript,'')),'C');
  INSERT INTO public.video_learning_search_documents(video_id,title,creator_name,concepts_text,chapters_text,transcript_text,search_vector,editorial_version,published_at,indexed_at)
  VALUES(p_video_id,v_title,v.source_name,v_concepts,v_chapters,v_transcript,v_vector,v_version,v.published_at,now())
  ON CONFLICT(video_id) DO UPDATE SET title=excluded.title,creator_name=excluded.creator_name,
    concepts_text=excluded.concepts_text,chapters_text=excluded.chapters_text,transcript_text=excluded.transcript_text,
    search_vector=excluded.search_vector,editorial_version=excluded.editorial_version,published_at=excluded.published_at,
    embedding=CASE WHEN video_learning_search_documents.editorial_version=excluded.editorial_version THEN video_learning_search_documents.embedding ELSE NULL END,
    embedding_model=CASE WHEN video_learning_search_documents.editorial_version=excluded.editorial_version THEN video_learning_search_documents.embedding_model ELSE NULL END,
    embedding_updated_at=CASE WHEN video_learning_search_documents.editorial_version=excluded.editorial_version THEN video_learning_search_documents.embedding_updated_at ELSE NULL END,indexed_at=now();
  RETURN true;
END $$;


ALTER FUNCTION public.fn_refresh_video_learning_search_document(p_video_id uuid) OWNER TO postgres;

--
-- TOC entry 6976 (class 1255 OID 14247837)
-- Name: fn_refund_shop_purchase(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_refund_shop_purchase(p_club_id uuid, p_purchase_id uuid, p_actor_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_purchase public.club_shop_purchases;
  v_inv      public.club_shop_inventory;
  v_credit   jsonb;
  v_saved    jsonb;
BEGIN
  SELECT * INTO v_purchase FROM public.club_shop_purchases
   WHERE id = p_purchase_id AND club_id = p_club_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'purchase_not_found');
  END IF;
  IF v_purchase.refunded_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true, 'already_refunded', true, 'amount', v_purchase.price_paid
    );
  END IF;

  SELECT * INTO v_inv FROM public.club_shop_inventory
   WHERE purchase_id = p_purchase_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_delivered');
  END IF;
  IF v_inv.status = 'redeemed' OR v_inv.redeemed_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'already_redeemed',
      'detail', 'The purchased benefit was already delivered and cannot be revoked automatically.'
    );
  END IF;

  IF v_inv.status <> 'refunded' THEN
    UPDATE public.club_shop_inventory SET status = 'refunded' WHERE id = v_inv.id;
  END IF;

  PERFORM public.fn_ca_authorize_funded_return('shop',p_purchase_id,v_purchase.currency,v_purchase.buyer_id,v_purchase.price_paid,'ca-shop-refund-'||p_purchase_id::text);
  IF v_purchase.currency = 'diamonds' THEN
    v_credit := public.add_diamonds_to_balance(
      v_purchase.buyer_id, v_purchase.price_paid, 'refund',
      COALESCE(NULLIF(p_reason, ''), 'Club Shop Purchase Refund'),
      'ca-shop-refund-' || p_purchase_id::text
    );
    IF COALESCE((v_credit->>'success')::boolean, false) IS NOT TRUE
       AND COALESCE((v_credit->>'duplicate')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'diamond refund credit failed: %', COALESCE(v_credit->>'error', 'unknown');
    END IF;
  ELSE
    /* THE REFUND NAMES WHERE ITS CHIPS COME FROM (2026-10-02, 20261002165749).
       A chip purchase retired its price (chip_debit, no recipient), so the
       refund puts those chips back into circulation: issuance_reserve,
       category refund, under this purchase's own operation key. Undeclared,
       fn_credit_chips refuses by name. The caller's declaration is restored. */
    v_saved := public.fn_ca_ledger_declaration_save(NULL);
    PERFORM public.fn_ca_declare_ledger('refund', 'issuance_reserve', NULL, NULL,
      'ca-shop-refund-' || p_purchase_id::text, NULL);
    v_credit := public.fn_credit_chips(
      p_club_id, v_purchase.buyer_id, v_purchase.price_paid,
      COALESCE(NULLIF(p_reason, ''), 'Shop purchase refund'),
      jsonb_build_object(
        'transaction_type', 'refund', 'purchase_id', p_purchase_id,
        'refunded_by', p_actor_id
      )
    );
    IF COALESCE((v_credit->>'success')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'refund credit failed: %', COALESCE(v_credit->>'error', 'unknown');
    END IF;
    PERFORM public.fn_ca_ledger_declaration_restore(v_saved);
  END IF;

  UPDATE public.club_shop_purchases SET refunded_at = now() WHERE id = p_purchase_id;
  IF v_purchase.stock_claimed THEN
    UPDATE public.club_shop_items SET stock = stock + 1
     WHERE id = v_purchase.item_id AND club_id = p_club_id AND stock IS NOT NULL;
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'amount', v_purchase.price_paid, 'currency', v_purchase.currency,
    'buyer_id', v_purchase.buyer_id,
    'balance_after', COALESCE(v_credit->'new_balance', v_credit->'balance_after')
  );
END;
$$;


ALTER FUNCTION public.fn_refund_shop_purchase(p_club_id uuid, p_purchase_id uuid, p_actor_id uuid, p_reason text) OWNER TO postgres;

--
-- TOC entry 6713 (class 1255 OID 24464284)
-- Name: fn_refuse_completed_with_pending_bounties(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_refuse_completed_with_pending_bounties() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status = 'COMPLETED' AND OLD.status IS DISTINCT FROM 'COMPLETED'
     AND (COALESCE(NEW.is_bounty,false) OR COALESCE(NEW.is_pko,false)
          OR COALESCE(NEW.is_mystery_bounty,false)) THEN
    IF public.fn_tournament_has_unsettled_bounties(NEW.id) THEN
      RAISE EXCEPTION 'tournament % has pending bounty obligations', NEW.id
        USING ERRCODE='check_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.tournament_bounty_completion_receipts r
                    WHERE r.tournament_id=NEW.id AND r.pool_finalized_at IS NOT NULL) THEN
      RAISE EXCEPTION 'tournament % bounty pool has not been finalized', NEW.id
        USING ERRCODE='check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_refuse_completed_with_pending_bounties() OWNER TO postgres;

