ALTER FUNCTION public.fn_register_for_tournament_with_ticket(p_tournament_id uuid, p_ticket_id uuid) OWNER TO postgres;

--
-- TOC entry 5461 (class 1255 OID 25581606)
-- Name: fn_register_for_tournament_with_ticket_before_terminal_gate(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_register_for_tournament_with_ticket_before_terminal_gate(p_tournament_id uuid, p_ticket_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid:=auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION
      'fn_register_for_tournament_with_ticket requires an authenticated caller'
      USING ERRCODE='28000';
  END IF;
  -- 20261015132042: a cashier ticket bound to one tournament enters through
  -- its own door; every other ticket keeps the satellite admission core.
  IF EXISTS (SELECT 1 FROM public.tournament_ticket_entry_targets b
              WHERE b.ticket_id=p_ticket_id) THEN
    RETURN public.fn_ca_use_cashier_entry_ticket(
      p_tournament_id,p_ticket_id,v_uid);
  END IF;
  RETURN public.fn_ca_register_for_tournament_with_ticket_for(
    p_tournament_id,p_ticket_id,v_uid);
END;
$$;


