-- TOC entry 7082 (class 1255 OID 27874162)
-- Name: fn_register_horse_for_tournament_before_atomic_lifecycle_gate(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_register_horse_for_tournament_before_atomic_lifecycle_gate(p_tournament_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
