--
-- TOC entry 3911 (class 1255 OID 22338224)
-- Name: fn_reject_retired_solver_option_rpc_ddl(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_reject_retired_solver_option_rpc_ddl() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_command record;
    v_schema text;
    v_name text;
BEGIN
    FOR v_command IN SELECT * FROM pg_event_trigger_ddl_commands()
    LOOP
        IF lower(coalesce(v_command.object_type, '')) <> 'function' THEN
            CONTINUE;
        END IF;

        v_schema := NULL;
        v_name := NULL;
        SELECT n.nspname, p.proname
        INTO v_schema, v_name
        FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE p.oid = v_command.objid;

        IF v_schema = 'public'
           AND v_name IN (
               'fn_pio_options_from_solver',
               'fn_chart_options_from_memory'
           ) THEN
            RAISE EXCEPTION USING
                ERRCODE = '55000',
                MESSAGE = format(
                    'retired solver option RPC recreation blocked: public.%I',
                    v_name
                ),
                HINT = 'A reviewed forward migration must remove the tombstone guard before intentionally reusing this name.';
        END IF;
    END LOOP;
END;
$$;


