--
-- TOC entry 4506 (class 1255 OID 14618476)
-- Name: fn_release_seats_on_tournament_finish(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_release_seats_on_tournament_finish() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Only on the TRANSITION into a finished state. Firing on every update of an
  -- already-finished row would rewrite left_at timestamps that are correct.
  IF NEW.status IN ('COMPLETED','CANCELLED')
     AND (OLD.status IS DISTINCT FROM NEW.status) THEN

    UPDATE table_seats ts
       SET left_at = COALESCE(NEW.ended_at, now())
      FROM tables t
     WHERE ts.table_id = t.id
       AND t.tournament_id = NEW.id
       AND ts.left_at IS NULL;

  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_release_seats_on_tournament_finish() OWNER TO postgres;

--
-- TOC entry 48666 (class 0 OID 0)
-- Dependencies: 4506
-- Name: FUNCTION fn_release_seats_on_tournament_finish(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_release_seats_on_tournament_finish() IS 'Dan 2026-08-21: a finished tournament must not leave players seated. table_seats.left_at IS NULL is read as "still playing" by the multi-table tab rebuild, so a seat held at a finished event follows the player as a dead tab. Fires only on the transition into COMPLETED/CANCELLED.';


