--
-- TOC entry 9403 (class 1255 OID 16602949)
-- Name: fn_replace_licensed_poy_rankings(integer, jsonb, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_replace_licensed_poy_rankings(p_year integer, p_rows jsonb, p_source_url text, p_source_updated_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  inserted_count integer;
begin
  if (select auth.role()) <> 'service_role' then
    raise exception 'service role required';
  end if;
  if p_year < 2000 or p_year > extract(year from now())::integer + 1 then
    raise exception 'invalid ranking year';
  end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) < 1 or jsonb_array_length(p_rows) > 500 then
    raise exception 'ranking payload must contain 1..500 rows';
  end if;

  delete from public.poy_leaderboard where year = p_year;

  insert into public.poy_leaderboard (
    player_name, external_player_id, points, rank, year, source,
    source_url, source_updated_at, country, team, updated_at
  )
  select
    nullif(trim(row.player_name), ''),
    nullif(trim(row.external_player_id), ''),
    row.points,
    row.rank,
    p_year,
    'gpi_licensed_feed',
    p_source_url,
    p_source_updated_at,
    nullif(trim(row.country), ''),
    nullif(trim(row.team), ''),
    now()
  from jsonb_to_recordset(p_rows) as row(
    player_name text,
    external_player_id text,
    points numeric,
    rank integer,
    country text,
    team text
  )
  where row.player_name is not null
    and row.rank between 1 and 500
    and row.points >= 0;

  get diagnostics inserted_count = row_count;
  if inserted_count = 0 then
    raise exception 'ranking payload produced no valid rows';
  end if;
  return inserted_count;
end;
$$;


ALTER FUNCTION public.fn_replace_licensed_poy_rankings(p_year integer, p_rows jsonb, p_source_url text, p_source_updated_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 9333 (class 1255 OID 20589732)
-- Name: fn_replication_slot_metrics(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_replication_slot_metrics() RETURNS TABLE(slot_name text, slot_type text, active boolean, restart_lag_bytes bigint, flush_lag_bytes bigint, wal_position_bytes bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT
    s.slot_name::text,
    s.slot_type::text,
    s.active,
    CASE
      WHEN pg_is_in_recovery() OR s.restart_lsn IS NULL THEN NULL
      ELSE (pg_current_wal_lsn() - s.restart_lsn)::bigint
    END,
    CASE
      WHEN pg_is_in_recovery() OR s.confirmed_flush_lsn IS NULL THEN NULL
      ELSE (pg_current_wal_lsn() - s.confirmed_flush_lsn)::bigint
    END,
    CASE
      WHEN pg_is_in_recovery() THEN NULL
      ELSE (pg_current_wal_lsn() - '0/0'::pg_lsn)::bigint
    END
  FROM pg_replication_slots s
$$;


ALTER FUNCTION public.fn_replication_slot_metrics() OWNER TO postgres;

--
-- TOC entry 48684 (class 0 OID 0)
-- Dependencies: 9333
-- Name: FUNCTION fn_replication_slot_metrics(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_replication_slot_metrics() IS 'Replication slot lag in bytes, per slot, for the engine''s Prometheus gauges. Read-only; service_role only. NULL rather than 0 when the reading is unavailable (standby, or an inactive slot with no restart_lsn) - a lag of zero is the perfect score and must never be faked. See server/src/services/ReplicationMetrics.ts and infra/monitoring/alert-rules.yml.';


--
-- TOC entry 8857 (class 1255 OID 91640534)
-- Name: fn_report_client_errors(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_report_client_errors(p_events jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid      uuid := auth.uid();
  v_now      timestamptz := now();
  v_recent   integer;
  v_global   integer;
  v_budget   integer;
  v_headers  text;
  v_ua       text;
  v_accepted integer := 0;
BEGIN
  -- Best effort, never an error at the browser: a malformed call stores nothing.
  IF p_events IS NULL OR jsonb_typeof(p_events) <> 'array' THEN
    RETURN 0;
  END IF;
  IF octet_length(p_events::text) > 65536 THEN
    RETURN 0;
  END IF;

  -- Signed-in callers only (EXECUTE is not granted to anon; this is the
  -- belt to that brace, e.g. a service_role call with no user).
  IF v_uid IS NULL THEN
    RETURN 0;
  END IF;

  -- One reporter at a time, so count-then-insert cannot be raced past its cap.
  PERFORM pg_advisory_xact_lock(hashtextextended('client_error_events:' || v_uid::text, 0));

  SELECT count(*) INTO v_recent FROM (
    SELECT 1 FROM public.client_error_events
     WHERE user_id = v_uid AND received_at > v_now - interval '1 minute'
     LIMIT 60) s;
  v_budget := 60 - v_recent;
  IF v_budget <= 0 THEN
    RETURN 0;
  END IF;

  SELECT count(*) INTO v_global FROM (
    SELECT 1 FROM public.client_error_events
     WHERE received_at > v_now - interval '1 minute'
     LIMIT 300) s;
  v_budget := least(v_budget, 300 - v_global, 20);
  IF v_budget <= 0 THEN
    RETURN 0;
  END IF;

  -- The request's own User-Agent, not a client-supplied one.
  v_headers := current_setting('request.headers', true);
  IF v_headers IS NOT NULL AND pg_input_is_valid(v_headers, 'jsonb') THEN
    v_ua := v_headers::jsonb ->> 'user-agent';
  END IF;

  INSERT INTO public.client_error_events (
    occurred_at, user_id, automated, route, app_version, user_agent, code,
    error_name, message, stack, source, context, dedupe_key, occurrences)
  SELECT
    CASE WHEN jsonb_typeof(e -> 'at') = 'number'
         THEN to_timestamp(least(greatest((e ->> 'at')::double precision / 1000.0,
                                          extract(epoch FROM v_now - interval '1 day')),
                                 extract(epoch FROM v_now)))
         ELSE v_now END,
    v_uid,
    coalesce((e -> 'automated') = 'true'::jsonb, false),
    CASE WHEN jsonb_typeof(e -> 'route') = 'string'
         THEN public.fn_client_error_scrub(split_part(split_part(e ->> 'route', '?', 1), '#', 1), 200) END,
    CASE WHEN jsonb_typeof(e -> 'app_version') = 'string'
         THEN left(regexp_replace(e ->> 'app_version', '[^A-Za-z0-9._+-]', '', 'g'), 64) END,
    left(coalesce(v_ua, CASE WHEN jsonb_typeof(e -> 'user_agent') = 'string' THEN e ->> 'user_agent' END), 256),
    coalesce(nullif(left(regexp_replace(
      CASE WHEN jsonb_typeof(e -> 'code') = 'string' THEN e ->> 'code' ELSE '' END,
      '[^A-Za-z0-9_.:-]', '_', 'g'), 64), ''), 'UNKNOWN'),
    CASE WHEN jsonb_typeof(e -> 'name') = 'string'
         THEN nullif(left(regexp_replace(e ->> 'name', '[^A-Za-z0-9_.:-]', '_', 'g'), 64), '') END,
    CASE WHEN jsonb_typeof(e -> 'message') = 'string'
         THEN public.fn_client_error_scrub(e ->> 'message', 500) END,
    CASE WHEN jsonb_typeof(e -> 'stack') = 'string'
         THEN public.fn_client_error_scrub(e ->> 'stack', 2000) END,
    CASE WHEN jsonb_typeof(e -> 'source') = 'string'
         THEN nullif(left(regexp_replace(e ->> 'source', '[^A-Za-z0-9_.:/-]', '_', 'g'), 120), '') END,
    CASE
      WHEN jsonb_typeof(e -> 'context') <> 'object' OR e -> 'context' IS NULL THEN NULL
      WHEN octet_length((e -> 'context')::text) > 2048 THEN jsonb_build_object('truncated', true)
      ELSE (SELECT CASE WHEN pg_input_is_valid(s.t, 'jsonb') AND octet_length(s.t) <= 2048
                        THEN s.t::jsonb ELSE jsonb_build_object('truncated', true) END
              FROM (SELECT public.fn_client_error_scrub((e -> 'context')::text, 2048) AS t) s)
    END,
    CASE WHEN jsonb_typeof(e -> 'dedupe_key') = 'string'
         THEN nullif(left(regexp_replace(e ->> 'dedupe_key', '[^A-Za-z0-9_.:|-]', '', 'g'), 64), '') END,
    CASE WHEN jsonb_typeof(e -> 'occurrences') = 'number'
         THEN least(10000, greatest(1, floor((e ->> 'occurrences')::numeric)))::integer
         ELSE 1 END
  FROM (
    SELECT x.e
      FROM jsonb_array_elements(p_events) WITH ORDINALITY AS x(e, n)
     WHERE jsonb_typeof(x.e) = 'object'
     ORDER BY x.n
     LIMIT v_budget
  ) ev(e);

  GET DIAGNOSTICS v_accepted = ROW_COUNT;
  RETURN v_accepted;
END;
$$;


ALTER FUNCTION public.fn_report_client_errors(p_events jsonb) OWNER TO postgres;

--
-- TOC entry 48686 (class 0 OID 0)
-- Dependencies: 8857
-- Name: FUNCTION fn_report_client_errors(p_events jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_report_client_errors(p_events jsonb) IS 'Best-effort client error sink for signed-in players. user_id = auth.uid(); 60/min per user, 300/min total, 20 per call; scrubbed and size-capped. Returns rows kept; never raises at the caller for bad input or over-limit.';


--
-- TOC entry 4522 (class 1255 OID 25591762)
-- Name: fn_request_admin_seat_departure(uuid, uuid, integer, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_request_admin_seat_departure(p_user_id uuid, p_table_id uuid, p_seat_number integer, p_occupancy_id uuid, p_actor_id uuid, p_club_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
 v_result jsonb; v_authority public.seat_admin_departure_authorizations%ROWTYPE;
 v_inserted integer;
BEGIN
 IF NOT coalesce(public.fn_caller_is_engine(),false) THEN
  RAISE EXCEPTION 'Engine authority required' USING ERRCODE='42501';
 END IF;
 -- Actor and club come only from the HTTP authorization result, never body fields.
 IF p_actor_id IS NULL OR p_club_id IS NULL OR p_reason IS NULL
    OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000 THEN
  RAISE EXCEPTION 'ADMIN_DEPARTURE_AUTHORITY_REQUIRED' USING ERRCODE='22023';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.tables WHERE id=p_table_id AND club_id=p_club_id) THEN
  RAISE EXCEPTION 'ADMIN_DEPARTURE_CLUB_MISMATCH' USING ERRCODE='22023';
 END IF;
 -- This takes the shared user/parent/seat locks and validates exact occupancy.
 -- Any later audit failure rolls its flags and durable forced authority back.
 v_result := public.fn_request_seat_departure(
  p_user_id,p_table_id,p_seat_number,p_occupancy_id,'forced');
 INSERT INTO public.seat_admin_departure_authorizations
  (occupancy_id,user_id,table_id,seat_number,actor_id,club_id,reason)
 VALUES(p_occupancy_id,p_user_id,p_table_id,p_seat_number,p_actor_id,p_club_id,p_reason)
 ON CONFLICT(occupancy_id) DO NOTHING;
 GET DIAGNOSTICS v_inserted = ROW_COUNT;
 SELECT * INTO STRICT v_authority FROM public.seat_admin_departure_authorizations
  WHERE occupancy_id=p_occupancy_id;
 IF v_authority.user_id IS DISTINCT FROM p_user_id
    OR v_authority.table_id IS DISTINCT FROM p_table_id
    OR v_authority.seat_number IS DISTINCT FROM p_seat_number
    OR v_authority.club_id IS DISTINCT FROM p_club_id THEN
  RAISE EXCEPTION 'ADMIN_DEPARTURE_SCOPE_MISMATCH' USING ERRCODE='22023';
 END IF;
 IF v_inserted=1 THEN
  INSERT INTO public.anti_cheat_events
   (event_type,player_id,club_id,table_id,details,triggered_by)
  VALUES('player_kicked',p_user_id,p_club_id,p_table_id,
   jsonb_build_object('reason',v_authority.reason,'kicked_by',v_authority.actor_id,
    'source','engine_admin_kick','occupancy_id',p_occupancy_id,
    'state','departure_requested','cashout_confirmed',false),
   v_authority.actor_id::text);
 END IF;
 RETURN v_result || jsonb_build_object('admin_authorization',
  jsonb_build_object('occupancy_id',v_authority.occupancy_id,'actor_id',v_authority.actor_id,
   'club_id',v_authority.club_id,'reason',v_authority.reason));
END;
$$;


