--
-- TOC entry 9135 (class 1255 OID 101732580)
-- Name: fn_request_chips(uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_request_chips(p_club_id uuid, p_amount numeric, p_note text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_intent jsonb := jsonb_build_object(
    'actor', auth.uid(), 'club', p_club_id, 'action', 'chip_request',
    'amount', p_amount,
    'note', nullif(btrim(coalesce(p_note, '')), ''));
  v_gate jsonb; v_result jsonb;
BEGIN
  IF p_op_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'A Retry Key Is Required'); END IF;
  v_gate := public.fn_cashier_exact_intent_begin('chip_request', p_club_id, p_op_id, v_intent);
  IF v_gate ->> 'state' = 'return' THEN RETURN v_gate -> 'response'; END IF;
  v_result := public.fn_request_chips_core_20261004(p_club_id, p_amount, p_note, p_op_id);
  RETURN public.fn_cashier_exact_intent_finish(p_op_id, v_result);
END
$$;


ALTER FUNCTION public.fn_request_chips(p_club_id uuid, p_amount numeric, p_note text, p_op_id uuid) OWNER TO postgres;

--
-- TOC entry 6142 (class 1255 OID 17730967)
-- Name: fn_request_chips_core_20261004(uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_request_chips_core_20261004(p_club_id uuid, p_amount numeric, p_note text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_me uuid := auth.uid();
  v_agent uuid;
  v_open integer;
  v_prior public.chip_requests%rowtype;
  v_note text := NULLIF(BTRIM(COALESCE(p_note, '')), '');
  v_id uuid;
BEGIN
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not Authenticated');
  END IF;
  IF p_op_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'A Retry Key Is Required');
  END IF;
  IF p_club_id IS NULL OR p_amount IS NULL OR p_amount <= 0 OR p_amount > 1e9 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Enter A Valid Request Amount');
  END IF;
  IF p_amount <> ROUND(p_amount, 2) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Chips Move In Hundredths At Most');
  END IF;
  IF v_note IS NOT NULL AND length(v_note) > 500 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Request Note Is Too Long');
  END IF;

  -- One requester/club lock makes both replay and max-three authoritative
  -- under concurrent submissions.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('chip-request:' || p_club_id::text || ':' || v_me::text, 0)
  );

  SELECT *
    INTO v_prior
    FROM public.chip_requests
   WHERE club_id = p_club_id
     AND requester_id = v_me
     AND op_id = p_op_id;
  IF FOUND THEN
    IF v_prior.amount IS DISTINCT FROM p_amount OR v_prior.note IS DISTINCT FROM v_note THEN
      RETURN jsonb_build_object(
        'success', false, 'error', 'That Retry Key Belongs To A Different Request'
      );
    END IF;
    RETURN jsonb_build_object(
      'success', true, 'request_id', v_prior.id, 'replayed', true
    );
  END IF;

  SELECT cm.agent_id
    INTO v_agent
    FROM public.club_members cm
   WHERE cm.club_id = p_club_id
     AND cm.user_id = v_me
     AND COALESCE(cm.status::text, 'active') IN ('active', 'approved')
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'You Are Not An Active Member Of This Club'
    );
  END IF;

  IF v_agent IS NULL THEN
    SELECT owner_id INTO v_agent FROM public.clubs WHERE id = p_club_id;
  END IF;

  SELECT COUNT(*)
    INTO v_open
    FROM public.chip_requests
   WHERE club_id = p_club_id
     AND requester_id = v_me
     AND status = 'pending';
  IF v_open >= 3 THEN
    RETURN jsonb_build_object('success', false, 'error', 'You Already Have 3 Open Requests');
  END IF;

  INSERT INTO public.chip_requests (
    club_id, requester_id, approver_id, amount, note, op_id
  ) VALUES (
    p_club_id, v_me, v_agent, p_amount, v_note, p_op_id
  )
  RETURNING id INTO v_id;

  -- THE APPROVER IS TOLD, IN THIS TRANSACTION (launch audit 2026-10-05).
  -- A replay returned above, so a retry never notifies twice.
  IF v_agent IS NOT NULL AND v_agent <> v_me THEN
    PERFORM public.fn_raise_notification(
      v_agent,
      'chip_request',
      'Chip Request',
      public.fn_notify_display_name(v_me) || ' Requested '
        || btrim(to_char(p_amount, 'FM999,999,999,990.00')) || ' Chips',
      '/hub/club-arena/clubs/' || p_club_id::text || '/cashier',
      jsonb_build_object(
        'club_id', p_club_id,
        'request_id', v_id,
        'requester_id', v_me,
        'amount', p_amount
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'request_id', v_id, 'replayed', false
  );
END
$$;


ALTER FUNCTION public.fn_request_chips_core_20261004(p_club_id uuid, p_amount numeric, p_note text, p_op_id uuid) OWNER TO postgres;

--
-- TOC entry 7945 (class 1255 OID 16852424)
-- Name: fn_request_manual_bomb_pot(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_request_manual_bomb_pot(p_table_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_club uuid;
  v_enabled boolean;
  v_role text;
  v_is_owner boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;

  SELECT club_id, bomb_pot_enabled INTO v_club, v_enabled
  FROM public.tables WHERE id = p_table_id;

  IF v_club IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'table_not_found');
  END IF;
  IF v_enabled IS DISTINCT FROM true THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'bomb_pots_disabled');
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = v_club AND c.owner_id = v_uid)
    INTO v_is_owner;
  SELECT lower(cm.role) INTO v_role
  FROM public.club_members cm
  WHERE cm.club_id = v_club AND cm.user_id = v_uid
  LIMIT 1;

  IF NOT (v_is_owner OR v_role IN ('owner', 'co_owner', 'admin')) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorized');
  END IF;

  UPDATE public.tables SET bomb_pot_manual_pending = true WHERE id = p_table_id;
  INSERT INTO public.bomb_pot_manual_requests (table_id, club_id, requested_by)
  VALUES (p_table_id, v_club, v_uid);

  BEGIN
    PERFORM realtime.send(
      jsonb_build_object('table_id', p_table_id, 'requested_by', v_uid),
      'bomb_pot_manual_requested',
      'engine:bomb-requests',
      false
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_request_manual_bomb_pot: realtime.send failed: %', SQLERRM;
  END;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION public.fn_request_manual_bomb_pot(p_table_id uuid) OWNER TO postgres;

--
-- TOC entry 5813 (class 1255 OID 25591072)
-- Name: fn_request_seat_departure(uuid, uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_request_seat_departure(p_user_id uuid, p_table_id uuid, p_seat_number integer, p_occupancy_id uuid, p_leave_mode text DEFAULT 'voluntary'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE v_tournament uuid; v_mode text; v_seat_id uuid;
BEGIN
 IF NOT coalesce(public.fn_caller_is_engine(),false) THEN
  RAISE EXCEPTION 'Engine authority required' USING ERRCODE='42501';
 END IF;
 IF p_user_id IS NULL OR p_table_id IS NULL OR p_seat_number IS NULL OR
    p_occupancy_id IS NULL OR p_leave_mode IS NULL OR p_leave_mode NOT IN ('voluntary','forced') THEN
  RAISE EXCEPTION 'DEPARTURE_IDENTITY_OR_MODE_REQUIRED' USING ERRCODE='22023';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('table_cap:'||p_user_id::text,0));
 SELECT tournament_id INTO v_tournament FROM public.tables WHERE id=p_table_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'CASHOUT_TABLE_NOT_FOUND' USING ERRCODE='22023'; END IF;
 IF v_tournament IS NOT NULL THEN
  PERFORM 1 FROM public.tournaments WHERE id=v_tournament FOR NO KEY UPDATE;
 END IF;
 SELECT id INTO v_seat_id FROM public.table_seats
  WHERE occupancy_id=p_occupancy_id AND user_id=p_user_id AND table_id=p_table_id
   AND seat_number=p_seat_number AND left_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'CASHOUT_STALE_OCCUPANCY' USING ERRCODE='22023'; END IF;
 INSERT INTO public.seat_departure_requests(occupancy_id,user_id,table_id,seat_number,leave_mode)
  VALUES(p_occupancy_id,p_user_id,p_table_id,p_seat_number,p_leave_mode)
 ON CONFLICT(occupancy_id) DO UPDATE SET leave_mode =
  CASE WHEN seat_departure_requests.leave_mode='forced' THEN 'forced' ELSE EXCLUDED.leave_mode END
 WHERE seat_departure_requests.user_id=EXCLUDED.user_id
   AND seat_departure_requests.table_id=EXCLUDED.table_id
   AND seat_departure_requests.seat_number=EXCLUDED.seat_number
 RETURNING leave_mode INTO v_mode;
 IF NOT FOUND THEN RAISE EXCEPTION 'CASHOUT_OCCUPANCY_SCOPE_MISMATCH' USING ERRCODE='22023'; END IF;
 UPDATE public.table_seats SET status='sitting_out',is_sitting_out=true,
   leave_pending=CASE WHEN v_tournament IS NULL THEN true ELSE leave_pending END
  WHERE id=v_seat_id;
 RETURN jsonb_build_object('accepted',true,'occupancy_id',p_occupancy_id,
  'user_id',p_user_id,'table_id',p_table_id,'seat_number',p_seat_number,
  'leave_mode',v_mode,'tournament_table',v_tournament IS NOT NULL);
END;
$$;


ALTER FUNCTION public.fn_request_seat_departure(p_user_id uuid, p_table_id uuid, p_seat_number integer, p_occupancy_id uuid, p_leave_mode text) OWNER TO postgres;

--
-- TOC entry 9613 (class 1255 OID 26587223)
-- Name: fn_request_tournament_deal_review(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_request_tournament_deal_review(p_tournament_id uuid, p_expected_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_actor uuid:=auth.uid(); r public.tournament_deal_reviews%ROWTYPE; v_seconds integer; v_hand_revision text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
  IF p_expected_actor_id IS NULL OR v_actor IS DISTINCT FROM p_expected_actor_id THEN
    RETURN jsonb_build_object('ok',false,'reason','actor_mismatch');
  END IF;
  IF NOT public.fn_ca_tournament_deal_proposals_active() THEN
    RETURN jsonb_build_object('ok',false,'reason','proposal_authority_not_active');
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.tournament_players WHERE tournament_id=p_tournament_id
    AND user_id=v_actor AND status::text='playing' AND eliminated_at IS NULL) THEN
    RETURN jsonb_build_object('ok',false,'reason','voter_not_alive');
  END IF;
  PERFORM public.fn_ca_lock_settlement_lane_global();
  PERFORM 1 FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM public.tournament_players WHERE tournament_id=p_tournament_id
    AND user_id=v_actor AND status::text='playing' AND eliminated_at IS NULL) THEN
    RETURN jsonb_build_object('ok',false,'reason','voter_not_alive');
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.tournaments t WHERE t.id=p_tournament_id
    AND t.status::text='RUNNING' AND t.final_table_deal_enabled IS TRUE
    AND t.prize_pool_finalized IS TRUE AND lower(COALESCE(t.variant::text,''))<>'satellite'
    AND upper(COALESCE(t.tournament_type::text,''))<>'SATELLITE'
    AND t.satellite_target_id IS NULL AND t.satellite_target IS NULL
    AND (SELECT count(*) FROM public.tournament_players tp WHERE tp.tournament_id=t.id
      AND tp.status::text='playing' AND tp.eliminated_at IS NULL) BETWEEN 2 AND t.table_size) THEN
    RETURN jsonb_build_object('ok',false,'reason','deal_not_ready');
  END IF;
  UPDATE public.tournament_deal_reviews SET state='expired',closed_at=clock_timestamp()
    WHERE tournament_id=p_tournament_id AND state IN ('requested','reviewing') AND expires_at<=clock_timestamp();
  SELECT * INTO r FROM public.tournament_deal_reviews
    WHERE tournament_id=p_tournament_id AND state IN ('requested','reviewing');
  IF r.id IS NULL THEN
    v_hand_revision:=public.fn_ca_tournament_deal_hand_revision(p_tournament_id);
    IF EXISTS(SELECT 1 FROM public.tournament_deal_reviews old WHERE old.tournament_id=p_tournament_id
      AND COALESCE(old.consumed_hand_revision,old.requested_hand_revision)=v_hand_revision) THEN
      RETURN jsonb_build_object('ok',false,'reason','review_wait_for_next_hand');
    END IF;
    SELECT request_seconds INTO STRICT v_seconds FROM public.tournament_deal_review_policy WHERE singleton;
    INSERT INTO public.tournament_deal_reviews(tournament_id,requested_by,state,expires_at,requested_hand_revision)
      VALUES(p_tournament_id,v_actor,'requested',clock_timestamp()+make_interval(secs=>v_seconds),v_hand_revision) RETURNING * INTO r;
    PERFORM public.fn_emit_tournament_manager_wake(p_tournament_id,'deal_vote');
  END IF;
  RETURN public.fn_ca_tournament_deal_review_result(p_tournament_id,v_actor,r.id);
END;
$$;


ALTER FUNCTION public.fn_request_tournament_deal_review(p_tournament_id uuid, p_expected_actor_id uuid) OWNER TO postgres;

--
