-- Name: video_attribution_update_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.video_attribution_update_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    operation_id uuid NOT NULL,
    requester_user_id uuid NOT NULL,
    attribution_record_id uuid NOT NULL,
    proposed_creator_name text NOT NULL,
    proposed_attribution_url text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    review_reason text,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT video_attribution_update_request_proposed_attribution_url_check CHECK ((proposed_attribution_url ~ '^https://'::text)),
    CONSTRAINT video_attribution_update_requests_proposed_creator_name_check CHECK (((length(btrim(proposed_creator_name)) >= 2) AND (length(btrim(proposed_creator_name)) <= 160))),
    CONSTRAINT video_attribution_update_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'withdrawn'::text]))),
    CONSTRAINT video_attribution_update_requests_version_check CHECK ((version > 0))
);


