--
-- TOC entry 4591 (class 1255 OID 26587211)
-- Name: fn_require_exact_final_deal_proposal(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_require_exact_final_deal_proposal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_id uuid; v_revision text; v_state jsonb; p public.tournament_deal_proposals%ROWTYPE; v_share jsonb;
BEGIN
  IF TG_OP='UPDATE' THEN
    IF OLD.kind='final_table_deal' AND ROW(NEW.tournament_id,NEW.kind,NEW.user_id,NEW.place,NEW.amount_owed)
      IS DISTINCT FROM ROW(OLD.tournament_id,OLD.kind,OLD.user_id,OLD.place,OLD.amount_owed) THEN
      RAISE EXCEPTION 'approved final-deal obligation cannot change' USING ERRCODE='23514';
    END IF;
    IF NEW.kind IS NOT DISTINCT FROM OLD.kind THEN RETURN NEW; END IF;
  END IF;
  IF NEW.kind<>'final_table_deal' THEN RETURN NEW; END IF;
  v_id:=NULLIF(current_setting('app.tournament_deal_proposal_id',true),'')::uuid;
  v_revision:=NULLIF(current_setting('app.tournament_deal_proposal_revision',true),'');
  IF v_id IS NULL OR v_revision IS NULL THEN RAISE EXCEPTION 'exact deal proposal context required' USING ERRCODE='42501'; END IF;
  SELECT * INTO p FROM public.tournament_deal_proposals WHERE id=v_id AND tournament_id=NEW.tournament_id AND revision=v_revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'deal proposal identity mismatch' USING ERRCODE='23514'; END IF;
  v_state:=public.fn_ca_tournament_deal_snapshot(NEW.tournament_id);
  IF (v_state->>'ok')::boolean IS NOT TRUE OR p.snapshot IS DISTINCT FROM v_state->'snapshot'
     OR p.revision IS DISTINCT FROM v_state->>'revision' THEN
    RAISE EXCEPTION 'deal proposal is stale' USING ERRCODE='23514';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p.snapshot->'shares')x WHERE NOT EXISTS(
    SELECT 1 FROM public.tournament_deal_proposal_consents c WHERE c.proposal_id=p.id AND c.user_id=(x->>'user_id')::uuid)) THEN
    RAISE EXCEPTION 'deal proposal lacks unanimous exact consent' USING ERRCODE='23514';
  END IF;
  SELECT x INTO v_share FROM jsonb_array_elements(p.snapshot->'shares')x WHERE x->>'user_id'=NEW.user_id::text;
  IF v_share IS NULL OR NEW.place IS NOT NULL OR NEW.amount_owed IS DISTINCT FROM (v_share->>'amount_cents')::numeric/100
     OR NEW.amount_paid IS DISTINCT FROM 0::numeric THEN
    RAISE EXCEPTION 'deal obligation differs from approved recipient or amount' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_require_exact_final_deal_proposal() OWNER TO postgres;

--
-- TOC entry 6075 (class 1255 OID 18277560)
-- Name: fn_require_explicit_club_membership_source(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_require_explicit_club_membership_source() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_source text:=coalesce(current_setting('app.club_membership_source',true),''); admission jsonb;
BEGIN
 IF v_source='historical_rakeback_wallet' THEN
  admission:=smarter_private.historical_rakeback_wallet_admission(nullif(current_setting('app.historical_rakeback_period',true),'')::uuid,
   nullif(current_setting('app.historical_rakeback_certificate',true),'')::bigint,nullif(current_setting('app.historical_rakeback_start',true),'')::timestamptz,nullif(current_setting('app.historical_rakeback_end',true),'')::timestamptz);
  IF NEW.club_id IS DISTINCT FROM(admission->>'club_id')::uuid OR NEW.user_id IS DISTINCT FROM(admission->>'user_id')::uuid
  OR NEW.role IS DISTINCT FROM 'player' OR NEW.status IS DISTINCT FROM 'suspended' OR NEW.is_active IS DISTINCT FROM false
  OR NEW.membership_lifecycle_status IS DISTINCT FROM 'departed' OR NEW.departed_at IS NULL
  OR NEW.departure_reason IS DISTINCT FROM 'historical_rakeback:'||(admission->>'period_id')||':'||(admission->>'certificate_id')
  OR NEW.chip_balance IS DISTINCT FROM 0::numeric OR NEW.promo_balance IS DISTINCT FROM 0::numeric
  OR NEW.held_chips IS DISTINCT FROM 0::numeric OR NEW.locked_chips IS DISTINCT FROM 0
  OR NEW.credit_limit IS DISTINCT FROM 0::numeric OR NEW.credit_used IS DISTINCT FROM 0::numeric
  OR NEW.commission_rate IS DISTINCT FROM 0::numeric OR NEW.rakeback_rate IS DISTINCT FROM 0::numeric OR NEW.player_rakeback_pct IS DISTINCT FROM 0::numeric
  OR NEW.agent_id IS NOT NULL OR NEW.parent_agent_id IS NOT NULL
  THEN RAISE EXCEPTION 'historical_wallet_source_shape_refused' USING ERRCODE='42501'; END IF;
  RETURN NEW;
 END IF;
 IF v_source NOT IN('join_club','club_owner_create','union_owner_membership') THEN
  RAISE EXCEPTION 'MEMBERSHIP_REQUIRES_JOIN: Club Members Can Only Be Added Through Join A Club' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_require_explicit_club_membership_source() OWNER TO postgres;

