CREATE TABLE public.video_source_quota_usage (
    usage_date date NOT NULL,
    units_used integer DEFAULT 0 NOT NULL,
    daily_budget integer DEFAULT 9000 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT video_source_quota_usage_daily_budget_check CHECK (((daily_budget >= 100) AND (daily_budget <= 10000))),
    CONSTRAINT video_source_quota_usage_units_used_check CHECK ((units_used >= 0))
);


ALTER TABLE public.video_source_quota_usage OWNER TO postgres;

--
-- TOC entry 5285 (class 1255 OID 91844449)
-- Name: fn_reserve_video_source_quota(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_reserve_video_source_quota(p_units integer) RETURNS public.video_source_quota_usage
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_row public.video_source_quota_usage%ROWTYPE;
  v_today date := (now() AT TIME ZONE 'UTC')::date;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'service_role required' USING ERRCODE = '42501';
  END IF;
  IF p_units < 1 OR p_units > 100 THEN
    RAISE EXCEPTION 'quota reservation must be between 1 and 100 units';
  END IF;
  INSERT INTO public.video_source_quota_usage (usage_date, units_used)
  VALUES (v_today, p_units)
  ON CONFLICT (usage_date) DO UPDATE
    SET units_used = public.video_source_quota_usage.units_used + EXCLUDED.units_used,
        updated_at = now()
    WHERE public.video_source_quota_usage.units_used + EXCLUDED.units_used
      <= public.video_source_quota_usage.daily_budget
  RETURNING * INTO v_row;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'daily YouTube quota budget exhausted' USING ERRCODE = 'P0001';
  END IF;
  RETURN v_row;
END;
$$;


ALTER FUNCTION public.fn_reserve_video_source_quota(p_units integer) OWNER TO postgres;

--
-- TOC entry 7669 (class 1255 OID 5356560)
-- Name: fn_reset_broken_streak_multipliers(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_reset_broken_streak_multipliers() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_yesterday DATE := ((now() AT TIME ZONE 'America/Chicago') - INTERVAL '1 day')::DATE;
    v_count     INTEGER;
BEGIN
    WITH stale_users AS (
        SELECT p.id
        FROM public.profiles p
        WHERE COALESCE(p.diamond_multiplier, 1.00) > 1.00
          AND NOT EXISTS (
              SELECT 1 FROM public.share_events se
              WHERE se.user_id = p.id
                AND (se.created_at AT TIME ZONE 'America/Chicago')::DATE >= v_yesterday
          )
    )
    UPDATE public.profiles
    SET diamond_multiplier = 1.00,
        updated_at = now()
    WHERE id IN (SELECT id FROM stale_users);

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


ALTER FUNCTION public.fn_reset_broken_streak_multipliers() OWNER TO postgres;

--
-- TOC entry 7785 (class 1255 OID 34785435)
-- Name: fn_resolve_accounting_routing_scope(text, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_accounting_routing_scope(p_scope_kind text, p_scope_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) RETURNS TABLE(union_id uuid, standalone_club_id uuid, club_ids uuid[], scope_key text, lock_key text, routing_context text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501';END IF;
 IF p_scope_kind IS NULL OR p_scope_kind NOT IN('union','club') OR p_scope_id IS NULL
  OR (p_scope_kind='union' AND NOT EXISTS(SELECT 1 FROM public.unions u WHERE u.id=p_scope_id))
  OR (p_scope_kind='club' AND NOT EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=p_scope_id))
 THEN RAISE EXCEPTION 'invalid_accounting_routing_scope' USING ERRCODE='22023';END IF;
 union_id:=CASE WHEN p_scope_kind='union' THEN p_scope_id END;
 standalone_club_id:=CASE WHEN p_scope_kind='club' THEN p_scope_id END;
 -- Preserve union keys and the established coordinator lock exactly. Club keys
 -- have an explicit prefix so even identical UUID values can never collide.
 scope_key:=CASE WHEN p_scope_kind='union' THEN p_scope_id::text ELSE 'club:'||p_scope_id::text END;
 lock_key:=CASE WHEN p_scope_kind='union' THEN 'union-accounting:' ELSE 'club-accounting:' END||p_scope_id::text||':'||extract(epoch FROM p_period_start)::text||':'||extract(epoch FROM p_period_end)::text;
 routing_context:=scope_key||':'||p_period_start::text||':'||p_period_end::text;
 -- Acquire before reading source-club membership: a waiting close must see all
 -- earning sources committed by the previous lock holder. Accrual shares this key.
 PERFORM pg_advisory_xact_lock(hashtextextended(lock_key,0));
 IF p_scope_kind='union' THEN
  club_ids:=ARRAY(WITH RECURSIVE
cash_clubs(club_id) AS (
 (SELECT s.club_id FROM public.accounting_cash_rake_sources s WHERE s.club_id IS NOT NULL ORDER BY s.club_id LIMIT 1)
 UNION ALL
 SELECT n.club_id FROM cash_clubs c CROSS JOIN LATERAL
 (SELECT s.club_id FROM public.accounting_cash_rake_sources s WHERE s.club_id>c.club_id ORDER BY s.club_id LIMIT 1)n
),
fee_clubs(club_id) AS (
 (SELECT s.club_id FROM public.accounting_tournament_fee_sources s WHERE s.club_id IS NOT NULL ORDER BY s.club_id LIMIT 1)
 UNION ALL
 SELECT n.club_id FROM fee_clubs c CROSS JOIN LATERAL
 (SELECT s.club_id FROM public.accounting_tournament_fee_sources s WHERE s.club_id>c.club_id ORDER BY s.club_id LIMIT 1)n
),
accepted_cash AS MATERIALIZED (
 SELECT k.club_id FROM cash_clubs k CROSS JOIN LATERAL
 (SELECT true FROM public.accounting_payable_earning_sources rs WHERE rs.source_type='cash_rake_accrual'
 AND rs.club_id=k.club_id AND rs.coordinator_union_id=p_scope_id
 AND rs.earned_at>=p_period_start AND rs.earned_at<p_period_end LIMIT 1 OFFSET 0)w
 UNION ALL SELECT NULL::uuid WHERE EXISTS(SELECT FROM public.accounting_payable_earning_sources rs
 WHERE rs.source_type='cash_rake_accrual' AND rs.club_id IS NULL AND rs.coordinator_union_id=p_scope_id
 AND rs.earned_at>=p_period_start AND rs.earned_at<p_period_end)
),
fee_candidates AS MATERIALIZED (SELECT k.club_id FROM fee_clubs k WHERE NOT EXISTS
 (SELECT FROM accepted_cash c WHERE c.club_id IS NOT DISTINCT FROM k.club_id)),
accepted_fee AS (
 SELECT k.club_id FROM fee_candidates k CROSS JOIN LATERAL (
 SELECT true FROM public.accounting_tournament_fee_sources fee CROSS JOIN LATERAL (
 SELECT true FROM public.accounting_payable_earning_sources rs WHERE rs.source_type='tournament_fee_accrual'
 AND rs.source_id=fee.id AND rs.club_id=k.club_id AND rs.coordinator_union_id=p_scope_id
 AND rs.earned_at>=p_period_start AND rs.earned_at<p_period_end LIMIT 1 OFFSET 0)witness
 WHERE fee.club_id=k.club_id AND fee.coordinator_union_id=p_scope_id
 LIMIT 1 OFFSET 0)w
 UNION ALL SELECT NULL::uuid WHERE NOT EXISTS(SELECT FROM accepted_cash c WHERE c.club_id IS NULL)
 AND EXISTS(SELECT FROM public.accounting_payable_earning_sources rs
 WHERE rs.source_type='tournament_fee_accrual' AND rs.club_id IS NULL AND rs.coordinator_union_id=p_scope_id
 AND rs.earned_at>=p_period_start AND rs.earned_at<p_period_end)
)
SELECT uc.club_id FROM public.union_clubs uc WHERE uc.union_id=p_scope_id
 AND((isfinite(p_period_start) AND isfinite(p_period_end) AND p_period_end>p_period_start) IS NOT TRUE OR uc.joined_at IS NULL OR uc.joined_at<p_period_end)
 UNION SELECT ac.club_id FROM accepted_cash ac UNION SELECT af.club_id FROM accepted_fee af ORDER BY club_id);
 ELSE club_ids:=ARRAY[p_scope_id];END IF;
 RETURN NEXT;
END $$;


ALTER FUNCTION public.fn_resolve_accounting_routing_scope(p_scope_kind text, p_scope_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 8218 (class 1255 OID 30785326)
-- Name: fn_resolve_ads(text, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_ads(p_slot text, p_club_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 3, p_country text DEFAULT NULL::text) RETURNS TABLE(ad_id uuid, ad_key text, category text, headline text, body text, glyph text, target_url text, cta_label text, image_url text, placement_id uuid, advertiser_kind text, advertiser_name text, poster_url text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_user    uuid := auth.uid();
  v_vip     boolean := false;
  v_country text := case when p_country ~ '^[A-Za-z]{2}$' then upper(p_country) else null end;
begin
  if v_user is not null then
    select coalesce(p.is_vip, false) into v_vip from public.profiles p where p.id = v_user;
  end if;
  return query
  with resolved as (
    select c.id, c.ad_key, c.category, c.headline, c.body, c.glyph,
           replace(
             replace(
               coalesce(pl.target_url, c.target_url),
               '{clubId}',  coalesce(p_club_id::text, '{clubId}')
             ),
             '{club_id}', coalesce(p_club_id::text, '{club_id}')
           ) as target_url,
           c.cta_label,
           coalesce(pl.image_url, c.image_url) as image_url,
           pl.id as placement_id,
           coalesce(adv.kind, 'house')         as advertiser_kind,
           coalesce(adv.name, 'smarter.poker') as advertiser_name,
           coalesce(c.poster_url, pl.image_url, c.image_url) as poster_url,
           c.priority,
           c.weight,
           case
             when cam.id is null or cam.goal_impressions is null or cam.pacing <> 'even' then 0::numeric
             else (
               cam.goal_impressions * least(1.0, greatest(0.0,
                 extract(epoch from (now() - cam.starts_at))
                 / nullif(extract(epoch from (cam.ends_at - cam.starts_at)), 0)
               ))
               - coalesce((select count(*) from public.ad_event e2
                            where e2.ad_id = c.id and e2.event_type = 'impression'), 0)
             )::numeric
           end as pace_debt,
           c.created_at
      from public.ad_catalog c
      join public.ad_placement pl on pl.ad_id = c.id
      left join public.ad_advertiser adv on adv.id = c.advertiser_id
      left join public.ad_campaign  cam on cam.id = c.campaign_id
     where c.is_active
       and pl.is_active
       and pl.slot = p_slot
       and coalesce(pl.image_url, c.image_url) is not null
       and (adv.id is null or adv.status = 'active')
       and (c.starts_at is null or c.starts_at <= now())
       and (c.ends_at   is null or c.ends_at   >  now())
       and (pl.club_id is null or pl.club_id = p_club_id)
       -- A gated flight is shown only to a player known to be inside its
       -- list. Unknown location is not inside any list.
       and (cam.id is null or cam.countries is null
            or (v_country is not null and v_country = any(cam.countries)))
       and (
             pl.audience is null
          or pl.audience = 'all'
          or (pl.audience = 'vip'      and v_vip)
          or (pl.audience = 'non_vip'  and v_user is not null and not v_vip)
          or (pl.audience = 'new_player' and v_user is not null and exists (
                select 1 from public.profiles p
                 where p.id = v_user and p.created_at > now() - interval '7 days'))
          or (pl.audience = 'returning'  and v_user is not null and exists (
                select 1 from public.profiles p
                 where p.id = v_user and p.created_at <= now() - interval '7 days'))
       )
       and (
             pl.daily_cap is null
          or v_user is null
          or (select count(*) from public.ad_event e
               where e.user_id = v_user and e.ad_id = c.id
                 and e.slot = pl.slot
                 and e.event_type = 'impression'
                 and e.created_at > now() - interval '24 hours') < pl.daily_cap
       )
  )
  select r.id, r.ad_key, r.category, r.headline, r.body, r.glyph,
         r.target_url, r.cta_label, r.image_url,
         r.placement_id, r.advertiser_kind, r.advertiser_name,
         r.poster_url
    from resolved r
   where r.target_url is null or r.target_url not like '%{%'
   order by r.priority desc, r.pace_debt desc, random() ^ (1.0 / greatest(r.weight, 1)) desc
   limit greatest(0, least(p_limit, 10));
end;
$_$;


ALTER FUNCTION public.fn_resolve_ads(p_slot text, p_club_id uuid, p_limit integer, p_country text) OWNER TO postgres;

--
-- TOC entry 4800 (class 1255 OID 13528072)
-- Name: fn_resolve_bbj_pool(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_bbj_pool(p_table_id uuid, p_club_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_club uuid; v_union uuid; v_pool uuid; v_private boolean := false;
BEGIN
  SELECT t.club_id, t.union_id, COALESCE(t.is_private, false)
    INTO v_club, v_union, v_private
    FROM public.tables t WHERE t.id = p_table_id;
  v_club := COALESCE(v_club, p_club_id);

  -- UNION LAW: a private club game's BBJ never touches the union pool.
  IF v_private THEN
    v_union := NULL;
  ELSIF v_union IS NULL AND v_club IS NOT NULL THEN
    SELECT c.union_id INTO v_union FROM public.clubs c WHERE c.id = v_club;
  END IF;

  IF v_union IS NOT NULL THEN
    SELECT id INTO v_pool FROM public.bbj_pools
     WHERE club_id IS NULL AND union_id = v_union AND status = 'active';
    IF v_pool IS NULL THEN
      INSERT INTO public.bbj_pools (club_id, union_id, pool_amount, main_balance, backup_balance, promo_balance, hands_contributed, status)
      VALUES (NULL, v_union, 0, 0, 0, 0, 0, 'active')
      ON CONFLICT DO NOTHING;
      SELECT id INTO v_pool FROM public.bbj_pools
       WHERE club_id IS NULL AND union_id = v_union AND status = 'active';
    END IF;
  ELSIF v_club IS NOT NULL THEN
    SELECT id INTO v_pool FROM public.bbj_pools
     WHERE club_id = v_club AND status = 'active' ORDER BY created_at LIMIT 1;
    IF v_pool IS NULL THEN
      INSERT INTO public.bbj_pools (club_id, pool_amount, main_balance, backup_balance, promo_balance, hands_contributed, status)
      VALUES (v_club, 0, 0, 0, 0, 0, 'active')
      ON CONFLICT DO NOTHING;
      SELECT id INTO v_pool FROM public.bbj_pools
       WHERE club_id = v_club AND status = 'active' ORDER BY created_at LIMIT 1;
    END IF;
    IF v_pool IS NULL THEN
      -- Club pool exists but was retired when its balance was swept to the
      -- union. Revive it (at its current zero balance) for private-game BBJ.
      UPDATE public.bbj_pools SET status = 'active', updated_at = now()
       WHERE club_id = v_club
      RETURNING id INTO v_pool;
    END IF;
  ELSE
    RAISE EXCEPTION 'BBJ contribution with no resolvable club or union (table %)', p_table_id;
  END IF;

  RETURN v_pool;
END;
$$;


ALTER FUNCTION public.fn_resolve_bbj_pool(p_table_id uuid, p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 4932 (class 1255 OID 25985140)
-- Name: fn_resolve_committed_tournament_seat_move(uuid, uuid, uuid, uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_committed_tournament_seat_move(p_request_id uuid, p_tournament_id uuid, p_user_id uuid, p_source_table_id uuid, p_destination_table_id uuid, p_destination_seat_number integer, p_source_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  v_actor text:=NULLIF(current_setting('app.smarter_data_actor',true),'');
  v_result jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role'
     OR v_actor IS DISTINCT FROM 'service' THEN
    RAISE EXCEPTION 'committed tournament move receipt requires ordinary service authority'
      USING ERRCODE='28000';
  END IF;
  IF p_request_id IS NULL OR p_tournament_id IS NULL OR p_user_id IS NULL
     OR p_source_table_id IS NULL OR p_destination_table_id IS NULL
     OR p_source_table_id=p_destination_table_id
     OR p_destination_seat_number NOT BETWEEN 1 AND 10
     OR p_source_mode NOT IN ('live_source','closed_orphan') THEN
    RAISE EXCEPTION 'invalid committed tournament move receipt identity'
      USING ERRCODE='22023';
  END IF;

  -- The writer (fn_move_tournament_player) holds this tournament's lane -
  -- G shared, T(id) exclusive - from before its first receipt read through
  -- commit. G shared then T(id) SHARED waits for exactly that writer and for
  -- terminal authorities (2026-09-10; this was G exclusive, which made every
  -- authority and hand on the platform queue behind a read-only lookup).
  -- An absent receipt is deliberately not converted into proof that no write
  -- can still begin later.
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('ca:tournament-terminal-settlement:v1',0));
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('ca:tournament-terminal-settlement:v1:'||p_tournament_id::text,0));

  v_result:=public.fn_ca_tournament_seat_move_receipt(p_request_id);
  IF v_result IS NULL THEN
    RETURN NULL;
  END IF;
  IF (v_result->>'tournament_id')::uuid IS DISTINCT FROM p_tournament_id
     OR (v_result->>'user_id')::uuid IS DISTINCT FROM p_user_id
     OR (v_result->>'source_table_id')::uuid IS DISTINCT FROM p_source_table_id
     OR (v_result->>'destination_table_id')::uuid
          IS DISTINCT FROM p_destination_table_id
     OR (v_result->>'destination_seat_number')::integer
          IS DISTINCT FROM p_destination_seat_number
     OR v_result->>'source_mode' IS DISTINCT FROM p_source_mode THEN
    RAISE EXCEPTION 'tournament move request id belongs to another operation'
      USING ERRCODE='23505';
  END IF;
  RETURN v_result||jsonb_build_object('replayed',true);
END;
$$;


ALTER FUNCTION public.fn_resolve_committed_tournament_seat_move(p_request_id uuid, p_tournament_id uuid, p_user_id uuid, p_source_table_id uuid, p_destination_table_id uuid, p_destination_seat_number integer, p_source_mode text) OWNER TO postgres;

