--
-- TOC entry 5242 (class 1255 OID 19234810)
-- Name: fn_resolve_settled_financial_alerts(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_settled_financial_alerts(p_apply boolean DEFAULT false, p_limit integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_paid      integer := 0;
  v_overpaid  integer := 0;
  v_settled   integer := 0;
  v_released  integer := 0;
  v_paid_ids  uuid[] := '{}';
  v_over_ids  uuid[] := '{}';
  v_settled_ids uuid[] := '{}';
  v_rel_ids   uuid[] := '{}';
  v_ops       integer := 0;
  v_ops_ids   uuid[] := '{}';
  v_fin       integer := 0;
  v_fin_ids   uuid[] := '{}';
BEGIN
  -- ── CLASS 1: the player was accused of being unpaid and has since been paid.
  -- Proven per alert against wallet_transactions, not assumed from elapsed
  -- time. `short` is what the check said they were owed; `got` is what the
  -- prize path actually credited them for that same event.
  SELECT array_agg(id) INTO v_paid_ids FROM (
    SELECT a.id
      FROM public.financial_alerts a
     WHERE a.resolved IS NOT TRUE
       AND a.source = 'fn_payout_guarantee_check'
       AND a.context->>'kind' = 'earner_not_paid'
       AND a.context->>'user_id' IS NOT NULL
       AND a.context->>'tournament_id' IS NOT NULL
       AND COALESCE((
             SELECT sum(w.amount) FROM public.wallet_transactions w
              WHERE w.related_entity_id = (a.context->>'tournament_id')::uuid
                AND w.user_id           = (a.context->>'user_id')::uuid
                AND w.type = 'credit' AND w.category = 'prize'
           ), 0) >= COALESCE((a.context->>'short')::numeric, 0) - 0.01
     LIMIT p_limit
  ) s;
  v_paid := COALESCE(array_length(v_paid_ids, 1), 0);

  -- ── CLASS 2: every issue on the alert is an overpay, which 10.6 rule 3 says
  -- is absorbed and never clawed back. There is no action left to take, so
  -- "unresolved" is a false state. An alert carrying ANY other issue kind is
  -- deliberately left open.
  SELECT array_agg(id) INTO v_over_ids FROM (
    SELECT a.id
      FROM public.financial_alerts a
     WHERE a.resolved IS NOT TRUE
       AND a.source = 'fn_tournament_payout_reconcile'
       AND jsonb_typeof(a.context->'issues') = 'array'
       AND jsonb_array_length(a.context->'issues') > 0
       AND NOT EXISTS (
             SELECT 1 FROM jsonb_array_elements(a.context->'issues') i
              WHERE i->>'issue' IS DISTINCT FROM 'overpaid')
     LIMIT p_limit
  ) s;
  v_overpaid := COALESCE(array_length(v_over_ids, 1), 0);

  -- CLASS 3: the post-commit envelope this alert was raised about has since
  -- been applied. hand_atomic_commits.post_commit_completed_at is the durable
  -- proof; the alert is the memory of a moment when it was not yet set.
  SELECT COALESCE(array_agg(id), '{}') INTO v_settled_ids FROM (
    SELECT a.id
      FROM public.financial_alerts a
      JOIN public.hand_atomic_commits c ON c.hand_id = (a.context->>'hand_id')::uuid
     WHERE a.resolved IS NOT TRUE
       AND a.source IN ('ServerTableEngine.post_commit_obligations_pending',
                        'LightningHandHost.post_commit_obligations_pending')
       AND (a.source <> 'LightningHandHost.post_commit_obligations_pending' OR (
         c.table_id::text = a.context->>'table_id'
         AND to_jsonb(c.hand_number) = a.context->'hand_number'
         AND c.post_commit_request_hash ~ '^[0-9a-f]{64}$'
         AND c.post_commit_payload_hash ~ '^[0-9a-f]{64}$'
         AND c.post_commit_result->'ok' = 'true'::jsonb
         AND c.post_commit_result->>'hand_id' = c.hand_id::text
         AND c.post_commit_result->'hand_number' = to_jsonb(c.hand_number)))
       AND a.context->>'hand_id' IS NOT NULL
       AND c.post_commit_completed_at IS NOT NULL
     LIMIT p_limit
  ) s;
  v_settled := COALESCE(array_length(v_settled_ids, 1), 0);

  -- CLASS 4 / STAGE 1 (PARTIAL): only an exact original accepted hand with
  -- completed required obligations can resolve here. A later hand, client
  -- claim, text-only rollback or missing identity remains actionable. A true
  -- rollback needs no same-hand commit; this stage does not certify rollbacks.
  SELECT COALESCE(array_agg(id), '{}') INTO v_rel_ids FROM (
    SELECT a.id
      FROM public.financial_alerts a
      JOIN public.hand_atomic_commits c ON
        c.hand_id = CASE WHEN (a.context->'hand_request_identity_v1'->>'hand_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
          THEN (a.context->'hand_request_identity_v1'->>'hand_id')::uuid END
     WHERE a.resolved IS NOT TRUE
       AND a.source IN ('postHandTasks.hand_history_failed',
                        'ServerTableEngine.authoritative_hand_semantic_refusal')
       AND jsonb_typeof(a.context) = 'object'
       AND a.context->>'channel' = 'server_rpc'
       AND jsonb_typeof(a.context->'hand_request_identity_v1') = 'object'
       AND a.context->'hand_request_identity_v1'->'version' = '1'::jsonb
       AND a.context->'hand_request_identity_v1'->'post_commit_required' = 'true'::jsonb
       AND jsonb_typeof(a.context->'hand_request_identity_v1'->'table_id') = 'string'
       AND jsonb_typeof(a.context->'hand_request_identity_v1'->'hand_id') = 'string'
       AND jsonb_typeof(a.context->'hand_request_identity_v1'->'hand_number') = 'number'
       AND lower(a.context->>'table_id') = lower(a.context->'hand_request_identity_v1'->>'table_id')
       AND a.context->'hand_number' = a.context->'hand_request_identity_v1'->'hand_number'
       AND c.hand_id = CASE
         WHEN (a.context->'hand_request_identity_v1'->>'hand_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
         THEN (a.context->'hand_request_identity_v1'->>'hand_id')::uuid END
       AND c.table_id = CASE
         WHEN (a.context->'hand_request_identity_v1'->>'table_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
         THEN (a.context->'hand_request_identity_v1'->>'table_id')::uuid END
       AND c.hand_number = CASE
         WHEN (a.context->'hand_request_identity_v1'->>'hand_number') ~ '^[1-9][0-9]{6,15}$'
         THEN CASE WHEN (a.context->'hand_request_identity_v1'->>'hand_number')::bigint <= 9007199254740991
           THEN (a.context->'hand_request_identity_v1'->>'hand_number')::bigint END END
       AND c.payload_hash ~ '^[0-9a-f]{64}$'
       AND c.post_commit_request_hash ~ '^[0-9a-f]{64}$'
       AND c.post_commit_payload_hash ~ '^[0-9a-f]{64}$'
       AND jsonb_typeof(c.post_commit_payload) = 'object'
       AND c.post_commit_completed_at IS NOT NULL
       AND jsonb_typeof(c.post_commit_result) = 'object'
       AND c.post_commit_result->'ok' = 'true'::jsonb
       AND c.post_commit_result->>'hand_id' = c.hand_id::text
       AND c.post_commit_result->'hand_number' = to_jsonb(c.hand_number)
     ORDER BY a.created_at, a.id
     LIMIT p_limit
  ) s;
  v_released := COALESCE(array_length(v_rel_ids, 1), 0);

  -- CLASS 5: a tournament operational alarm whose condition has ended. A
  -- "table can't start" alarm is over when that table has committed a hand
  -- since the alarm, or is closed; a "tournament dark after rebuild" alarm is
  -- over when any of its tables has committed a hand since the alarm. Either
  -- is over when the tournament reached COMPLETED or CANCELLED. Money is not
  -- this class's evidence: a completed event's payout has its own alarm
  -- (class 1, fn_payout_guarantee_check), which this never touches.
  SELECT COALESCE(array_agg(id), '{}') INTO v_ops_ids FROM (
    SELECT a.id
      FROM public.financial_alerts a, public.tournaments t
     WHERE a.resolved IS NOT TRUE
       AND a.source IN ('Tournament.table_admission_failing',
                        'GameServer.tournament_dark_after_rebuild')
       AND t.id = CASE WHEN (a.context->>'tournament_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                       THEN (a.context->>'tournament_id')::uuid END
       AND (
             t.status IN ('COMPLETED', 'CANCELLED')
          OR (a.source = 'Tournament.table_admission_failing'
              AND EXISTS (
                    SELECT 1 FROM public.tables tb
                     WHERE tb.id = CASE WHEN (a.context->>'table_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                                        THEN (a.context->>'table_id')::uuid END
                       AND tb.tournament_id = t.id
                       AND (lower(tb.status) = 'closed'
                            OR EXISTS (SELECT 1 FROM public.hand_atomic_commits c
                                        WHERE c.table_id = tb.id
                                          AND c.committed_at > a.created_at))))
          OR (a.source = 'GameServer.tournament_dark_after_rebuild'
              AND EXISTS (
                    SELECT 1 FROM public.tables tb
                      JOIN public.hand_atomic_commits c ON c.table_id = tb.id
                     WHERE tb.tournament_id = t.id
                       AND c.committed_at > a.created_at))
           )
     ORDER BY a.created_at, a.id
     LIMIT p_limit
  ) s;
  v_ops := COALESCE(array_length(v_ops_ids, 1), 0);

  IF p_apply THEN
    -- The whole predicate again under UPDATE: a preview is not authority.
    WITH changed AS (
      UPDATE public.financial_alerts a
         SET resolved = true, resolved_at = now(),
             resolution = CASE
               WHEN t.status IN ('COMPLETED', 'CANCELLED')
                 THEN 'verified: tournament ' || t.id::text || ' reached ' || t.status
                   || COALESCE(' at ' || t.ended_at::text, '') || '; the alarm''s condition has ended.'
               WHEN a.source = 'Tournament.table_admission_failing'
                 THEN 'verified: table ' || (a.context->>'table_id')
                   || ' committed a hand or closed after this alarm; the table was admitted.'
               ELSE 'verified: tournament ' || t.id::text
                   || ' committed a hand after this alarm; it is dealing again.'
             END,
             context = COALESCE(a.context, '{}'::jsonb) || jsonb_build_object(
               'resolved_by_fn', 'fn_resolve_settled_financial_alerts',
               'resolved_on', now(),
               'tournament_status_at_resolution', t.status)
        FROM public.tournaments t
       WHERE a.id = ANY(v_ops_ids)
         AND a.resolved IS NOT TRUE
       AND a.source IN ('Tournament.table_admission_failing',
                        'GameServer.tournament_dark_after_rebuild')
       AND t.id = CASE WHEN (a.context->>'tournament_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                       THEN (a.context->>'tournament_id')::uuid END
       AND (
             t.status IN ('COMPLETED', 'CANCELLED')
          OR (a.source = 'Tournament.table_admission_failing'
              AND EXISTS (
                    SELECT 1 FROM public.tables tb
                     WHERE tb.id = CASE WHEN (a.context->>'table_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                                        THEN (a.context->>'table_id')::uuid END
                       AND tb.tournament_id = t.id
                       AND (lower(tb.status) = 'closed'
                            OR EXISTS (SELECT 1 FROM public.hand_atomic_commits c
                                        WHERE c.table_id = tb.id
                                          AND c.committed_at > a.created_at))))
          OR (a.source = 'GameServer.tournament_dark_after_rebuild'
              AND EXISTS (
                    SELECT 1 FROM public.tables tb
                      JOIN public.hand_atomic_commits c ON c.table_id = tb.id
                     WHERE tb.tournament_id = t.id
                       AND c.committed_at > a.created_at))
           )
      RETURNING a.id
    )
    SELECT COALESCE(array_agg(id), '{}') INTO v_ops_ids FROM changed;
    v_ops := COALESCE(array_length(v_ops_ids, 1), 0);
  END IF;

  -- CLASS 6: a proven finish refusal whose tournament has since finished. The
  -- engine retries a refused finish and, once it commits, the tournament is
  -- COMPLETED with its terminal receipt (a satellite: its settlement receipt)
  -- and its escrow closed at zero after the alarm was raised. That receipt is
  -- the end of the condition the alarm described. A refusal whose outcome is
  -- unknown, or a tournament in any other state, stays open.
  SELECT COALESCE(array_agg(id), '{}') INTO v_fin_ids FROM (
    SELECT a.id
      FROM public.financial_alerts a, public.tournaments t, public.tournament_escrow e
     WHERE a.resolved IS NOT TRUE
       AND a.source IN ('Tournament.atomic_finish_refused',
                        'Tournament.atomic_satellite_finish_refused')
       AND lower(COALESCE(a.context->>'proven_refusal', '')) IN ('true', 't', '1')
       AND t.id = CASE WHEN (a.context->>'tournament_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                       THEN (a.context->>'tournament_id')::uuid END
       AND t.status = 'COMPLETED'
       AND e.tournament_id = t.id
       AND e.terminal_closed_at IS NOT NULL
       AND e.terminal_closed_at >= a.created_at
       AND COALESCE(e.prize_balance, 0) = 0
       AND COALESCE(e.bounty_balance, 0) = 0
       AND CASE WHEN a.source = 'Tournament.atomic_satellite_finish_refused'
             THEN EXISTS (SELECT 1 FROM public.tournament_satellite_settlements s
                           WHERE s.tournament_id = t.id AND s.settled_at IS NOT NULL)
             ELSE EXISTS (SELECT 1 FROM public.tournament_terminal_settlements s
                           WHERE s.tournament_id = t.id)
           END
     ORDER BY a.created_at, a.id
     LIMIT p_limit
  ) s;
  v_fin := COALESCE(array_length(v_fin_ids, 1), 0);

  IF p_apply THEN
    WITH changed AS (
      UPDATE public.financial_alerts a
         SET resolved = true, resolved_at = now(),
             resolution = 'verified: tournament ' || t.id::text || ' COMPLETED after this refusal; '
               || CASE WHEN a.source = 'Tournament.atomic_satellite_finish_refused'
                       THEN 'its satellite settlement receipt is written'
                       ELSE 'its terminal receipt is written' END
               || ' and its escrow closed at zero at ' || e.terminal_closed_at::text
               || ', so the refused finish was retried and committed.',
             context = COALESCE(a.context, '{}'::jsonb) || jsonb_build_object(
               'resolved_by_fn', 'fn_resolve_settled_financial_alerts',
               'resolved_on', now())
        FROM public.tournaments t, public.tournament_escrow e
       WHERE a.id = ANY(v_fin_ids)
         AND a.resolved IS NOT TRUE
       AND a.source IN ('Tournament.atomic_finish_refused',
                        'Tournament.atomic_satellite_finish_refused')
       AND lower(COALESCE(a.context->>'proven_refusal', '')) IN ('true', 't', '1')
       AND t.id = CASE WHEN (a.context->>'tournament_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                       THEN (a.context->>'tournament_id')::uuid END
       AND t.status = 'COMPLETED'
       AND e.tournament_id = t.id
       AND e.terminal_closed_at IS NOT NULL
       AND e.terminal_closed_at >= a.created_at
       AND COALESCE(e.prize_balance, 0) = 0
       AND COALESCE(e.bounty_balance, 0) = 0
       AND CASE WHEN a.source = 'Tournament.atomic_satellite_finish_refused'
             THEN EXISTS (SELECT 1 FROM public.tournament_satellite_settlements s
                           WHERE s.tournament_id = t.id AND s.settled_at IS NOT NULL)
             ELSE EXISTS (SELECT 1 FROM public.tournament_terminal_settlements s
                           WHERE s.tournament_id = t.id)
           END
      RETURNING a.id
    )
    SELECT COALESCE(array_agg(id), '{}') INTO v_fin_ids FROM changed;
    v_fin := COALESCE(array_length(v_fin_ids, 1), 0);
  END IF;

  IF p_apply THEN
    UPDATE public.financial_alerts a
       SET resolved = true, resolved_at = now(),
           context = COALESCE(a.context, '{}'::jsonb) || jsonb_build_object(
             'resolution', 'the post-commit envelope for this hand has been applied; post_commit_completed_at is set',
             'resolved_by_fn', 'fn_resolve_settled_financial_alerts',
             'resolved_on', now())
     WHERE a.id = ANY(v_settled_ids);

    -- Repeat the complete guard under UPDATE: preview membership alone is not
    -- authority after a concurrent original-alert identity or status change.
    WITH changed AS (
      UPDATE public.financial_alerts a
         SET resolved = true, resolved_at = now(),
             resolution = 'Exact original hand ' || c.hand_id::text || ' at table ' || c.table_id::text || ' (#' || c.hand_number::text || ') was accepted; its required post-commit obligations completed at ' || c.post_commit_completed_at::text || '. This receipt does not diagnose the original failure cause.',
             context = COALESCE(a.context, '{}'::jsonb) || jsonb_build_object(
               'resolution', 'Exact original hand ' || c.hand_id::text || ' at table ' || c.table_id::text || ' (#' || c.hand_number::text || ') was accepted; its required post-commit obligations completed at ' || c.post_commit_completed_at::text || '. This receipt does not diagnose the original failure cause.',
               'resolved_by_fn', 'fn_resolve_settled_financial_alerts',
               'resolved_on', now(),
               'hand_outcome_resolution_v1', jsonb_build_object(
                 'version', 1, 'kind', 'exact_original_post_commit_complete',
                 'financial_alert_id', a.id,
                 'hand_id', c.hand_id, 'table_id', c.table_id,
                 'hand_number', c.hand_number, 'post_commit_required', true,
                 'commit_hash', c.payload_hash, 'committed_at', c.committed_at,
                 'post_commit_request_hash', c.post_commit_request_hash,
                 'post_commit_payload_hash', c.post_commit_payload_hash,
                 'post_commit_completed_at', c.post_commit_completed_at,
                 'completion_ok', true))
        FROM public.hand_atomic_commits c
       WHERE a.id = ANY(v_rel_ids)
         AND a.resolved IS NOT TRUE
       AND a.source IN ('postHandTasks.hand_history_failed',
                        'ServerTableEngine.authoritative_hand_semantic_refusal')
       AND jsonb_typeof(a.context) = 'object'
       AND a.context->>'channel' = 'server_rpc'
       AND jsonb_typeof(a.context->'hand_request_identity_v1') = 'object'
       AND a.context->'hand_request_identity_v1'->'version' = '1'::jsonb
       AND a.context->'hand_request_identity_v1'->'post_commit_required' = 'true'::jsonb
       AND jsonb_typeof(a.context->'hand_request_identity_v1'->'table_id') = 'string'
       AND jsonb_typeof(a.context->'hand_request_identity_v1'->'hand_id') = 'string'
       AND jsonb_typeof(a.context->'hand_request_identity_v1'->'hand_number') = 'number'
       AND lower(a.context->>'table_id') = lower(a.context->'hand_request_identity_v1'->>'table_id')
       AND a.context->'hand_number' = a.context->'hand_request_identity_v1'->'hand_number'
       AND c.hand_id = CASE
         WHEN (a.context->'hand_request_identity_v1'->>'hand_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
         THEN (a.context->'hand_request_identity_v1'->>'hand_id')::uuid END
       AND c.table_id = CASE
         WHEN (a.context->'hand_request_identity_v1'->>'table_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
         THEN (a.context->'hand_request_identity_v1'->>'table_id')::uuid END
       AND c.hand_number = CASE
         WHEN (a.context->'hand_request_identity_v1'->>'hand_number') ~ '^[1-9][0-9]{6,15}$'
         THEN CASE WHEN (a.context->'hand_request_identity_v1'->>'hand_number')::bigint <= 9007199254740991
           THEN (a.context->'hand_request_identity_v1'->>'hand_number')::bigint END END
       AND c.payload_hash ~ '^[0-9a-f]{64}$'
       AND c.post_commit_request_hash ~ '^[0-9a-f]{64}$'
       AND c.post_commit_payload_hash ~ '^[0-9a-f]{64}$'
       AND jsonb_typeof(c.post_commit_payload) = 'object'
       AND c.post_commit_completed_at IS NOT NULL
       AND jsonb_typeof(c.post_commit_result) = 'object'
       AND c.post_commit_result->'ok' = 'true'::jsonb
       AND c.post_commit_result->>'hand_id' = c.hand_id::text
       AND c.post_commit_result->'hand_number' = to_jsonb(c.hand_number)
      RETURNING a.id
    )
    SELECT COALESCE(array_agg(id), '{}') INTO v_rel_ids FROM changed;
    v_released := COALESCE(array_length(v_rel_ids, 1), 0);
  END IF;

  IF p_apply THEN
    UPDATE public.financial_alerts a
       SET resolved = true,
           resolved_at = now(),
           context = COALESCE(a.context, '{}'::jsonb) || jsonb_build_object(
             'resolution', 'settled after the alert was raised; the prize path credited this player for this event',
             'resolved_by_fn', 'fn_resolve_settled_financial_alerts',
             'resolved_on', now(),
             'credited', COALESCE((
               SELECT round(sum(w.amount), 2) FROM public.wallet_transactions w
                WHERE w.related_entity_id = (a.context->>'tournament_id')::uuid
                  AND w.user_id           = (a.context->>'user_id')::uuid
                  AND w.type = 'credit' AND w.category = 'prize'), 0))
     WHERE a.id = ANY(v_paid_ids);

    UPDATE public.financial_alerts a
       SET resolved = true,
           resolved_at = now(),
           context = COALESCE(a.context, '{}'::jsonb) || jsonb_build_object(
             'resolution', 'overpay only; absorbed by the house per CLAUDE.md 10.6 rule 3, never clawed back',
             'resolved_by_fn', 'fn_resolve_settled_financial_alerts',
             'resolved_on', now())
     WHERE a.id = ANY(v_over_ids);
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'applied', p_apply,
    'settled_after_alert', v_paid,
    'overpay_absorbed', v_overpaid,
    'post_commit_applied', v_settled,
    'refused_hand_released', v_released,
    'tournament_condition_ended', v_ops,
    'refused_finish_committed', v_fin,
    'total', v_paid + v_overpaid + v_settled + v_released + v_ops + v_fin,
    'still_unresolved', (SELECT count(*) FROM public.financial_alerts WHERE resolved IS NOT TRUE)
  );
END;
$_$;


ALTER FUNCTION public.fn_resolve_settled_financial_alerts(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- TOC entry 48729 (class 0 OID 0)
-- Dependencies: 5242
-- Name: FUNCTION fn_resolve_settled_financial_alerts(p_apply boolean, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_resolve_settled_financial_alerts(p_apply boolean, p_limit integer) IS 'Closes financial_alerts whose condition is provably no longer true: an accused-unpaid player the prize path has since credited, and reconciler alerts carrying only overpay (10.6 rule 3, never clawed back). Never resolves on age or guess. Added 2026-09-02 after 64 stale alerts nearly caused an 836.79 chip double-pay.';


--
-- TOC entry 7613 (class 1255 OID 20873564)
-- Name: fn_resolve_settled_prize_alerts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_settled_prize_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_closed integer := 0;
BEGIN
  WITH provable AS (
    SELECT a.id,
           tp.amount   AS paid_amount,
           tp.paid_at,
           tp.idempotency_key
    FROM public.financial_alerts a
    JOIN public.tournament_payouts tp
      ON tp.tournament_id = (a.context->>'tournament_id')::uuid
     AND tp.user_id       = (a.context->>'user_id')::uuid
    WHERE NOT a.resolved
      AND a.source = 'Tournament.winner_prize_credit_failed'
      AND a.context ? 'tournament_id'
      AND a.context ? 'user_id'
      AND a.context ? 'prize'
      AND tp.paid_at IS NOT NULL
      AND tp.amount = (a.context->>'prize')::numeric
  )
  UPDATE public.financial_alerts a
     SET resolved    = true,
         resolved_at = now(),
         resolution  = format(
           'auto-resolved 2026-09-04: the reconciler paid this. tournament_payouts records %s chips paid at %s under idempotency key %s. The alert was raised by the engine when its direct credit hit the statement timeout, BEFORE the reconciler ran; the assertion that the player was never paid was false when it was written.',
           p.paid_amount, p.paid_at, p.idempotency_key)
    FROM provable p
   WHERE a.id = p.id;

  GET DIAGNOSTICS v_closed = ROW_COUNT;
  RETURN v_closed;
END;
$$;


ALTER FUNCTION public.fn_resolve_settled_prize_alerts() OWNER TO postgres;

--
-- TOC entry 48731 (class 0 OID 0)
-- Dependencies: 7613
-- Name: FUNCTION fn_resolve_settled_prize_alerts(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_resolve_settled_prize_alerts() IS 'Closes Tournament.winner_prize_credit_failed alerts whose money provably landed - a tournament_payouts row for the same tournament and user, paid_at set, amount equal to the prize the alert named. Nothing else is auto-resolved. Measured 2026-09-04, the reconciler had already paid all five open instances, three of them within 9 seconds.';


--
-- TOC entry 3672 (class 1255 OID 24464867)
-- Name: fn_resolve_tournament_blinds(text, integer, text, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_tournament_blinds(p_blind_structure text, p_current_level integer, p_variant text, p_tournament_type text, p_total_chips numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_levels jsonb;
  v_len integer;
  v_index integer;
  v_level jsonb;
  v_last_index integer;
  v_last jsonb;
  v_is_spin boolean;
  v_continuation jsonb;
  v_float_round double precision;
  v_float_units double precision;
  v_float_integral double precision;
  v_float_bb double precision;
  v_float_sb double precision;
  v_tail_count integer;
  v_tail_first numeric;
  v_tail_last numeric;
  v_ratio numeric := 1.4;
  v_factor numeric;
  v_sb numeric;
  v_bb numeric;
  v_ante numeric;
  v_max_bb numeric;
  v_scale numeric;
  v_capped boolean := false;
  v_anchor_bb numeric;
  v_anchor_ante numeric;
  v_ante_ceiling numeric;
  v_anchor_sb numeric;
  v_sb_ceiling numeric;
BEGIN
  v_levels := public.fn_safe_jsonb_array(p_blind_structure);
  v_len := jsonb_array_length(v_levels);
  IF v_len=0 THEN
    RAISE EXCEPTION 'Tournament blind structure is missing' USING ERRCODE='55000';
  END IF;
  v_index := GREATEST(COALESCE(p_current_level,0),0);

  -- A persisted level is authoritative and is never chip-capped in the engine.
  IF v_index<v_len THEN
    v_level := v_levels->v_index;
    v_sb := COALESCE(
      CASE WHEN COALESCE(v_level->>'smallBlind','') ~ '^[0-9]+([.][0-9]+)?$'
           THEN (v_level->>'smallBlind')::numeric END,
      CASE WHEN COALESCE(v_level->>'small_blind','') ~ '^[0-9]+([.][0-9]+)?$'
           THEN (v_level->>'small_blind')::numeric END
    );
    v_bb := COALESCE(
      CASE WHEN COALESCE(v_level->>'bigBlind','') ~ '^[0-9]+([.][0-9]+)?$'
           THEN (v_level->>'bigBlind')::numeric END,
      CASE WHEN COALESCE(v_level->>'big_blind','') ~ '^[0-9]+([.][0-9]+)?$'
           THEN (v_level->>'big_blind')::numeric END
    );
    v_ante := COALESCE(
      CASE WHEN COALESCE(v_level->>'ante','') ~ '^[0-9]+([.][0-9]+)?$'
           THEN (v_level->>'ante')::numeric END,
      0
    );
    RETURN jsonb_build_object(
      'small_blind',v_sb,'big_blind',v_bb,'ante',v_ante,
      'level_index',v_index,'source','persisted','blind_capped',false
    );
  END IF;

  v_is_spin := lower(COALESCE(p_variant,''))='spin'
            OR upper(COALESCE(p_tournament_type,''))='SPIN';
  IF v_is_spin THEN
    -- A funded draw freezes its continuation rule. Presence with malformed
    -- values is an error, never permission to substitute a newer local rule.
    IF (v_levels->(v_len-1)) ? 'spinContinuation' THEN
      v_continuation := v_levels->(v_len-1)->'spinContinuation';
      IF jsonb_typeof(v_continuation) IS DISTINCT FROM 'object'
         OR jsonb_typeof(v_continuation->'version') IS DISTINCT FROM 'number'
         OR jsonb_typeof(v_continuation->'anchorLevel') IS DISTINCT FROM 'number'
         OR jsonb_typeof(v_continuation->'anchorBigBlind') IS DISTINCT FROM 'number'
         OR jsonb_typeof(v_continuation->'growth') IS DISTINCT FROM 'number'
         OR jsonb_typeof(v_continuation->'roundBigTo') IS DISTINCT FROM 'number' THEN
        RAISE EXCEPTION 'Spin blind continuation is missing its frozen formula'
          USING ERRCODE='55000';
      END IF;
      -- The booked engine formula consumes JavaScript Number values. Keep
      -- IEEE-754 arithmetic through power, division, both rounds and the
      -- final multiplication. Decimal numeric changes 100 * 1.15 / 10.
      BEGIN
        PERFORM (e.value #>> '{}')::double precision
          FROM jsonb_each(v_continuation) e
         WHERE e.key IN ('version','anchorLevel','anchorBigBlind','growth','roundBigTo');
        IF (v_continuation->>'version')::double precision<>1
           OR (v_continuation->>'anchorLevel')::double precision<=0
           OR floor((v_continuation->>'anchorLevel')::double precision)<>(v_continuation->>'anchorLevel')::double precision
           OR (v_continuation->>'anchorBigBlind')::double precision<=0
           OR (v_continuation->>'growth')::double precision<=1
           OR (v_continuation->>'roundBigTo')::double precision<=0 THEN
          RAISE EXCEPTION 'Spin blind continuation is missing its frozen formula' USING ERRCODE='55000';
        END IF;
        v_float_round := (v_continuation->>'roundBigTo')::double precision;
        v_float_units := ((v_continuation->>'anchorBigBlind')::double precision
          * power((v_continuation->>'growth')::double precision,
                  v_index::double precision+1-(v_continuation->>'anchorLevel')::double precision))
          / v_float_round;
        -- PostgreSQL round(float8) rounds ties to even. JavaScript rounds
        -- positive ties upward. Adding 0.5 first also changes near-half
        -- values, so compare the fractional part without shifting it.
        v_float_integral := floor(v_float_units);
        IF v_float_units-v_float_integral >= 0.5::double precision THEN
          v_float_integral := v_float_integral+1::double precision;
        END IF;
        v_float_bb := v_float_integral*v_float_round;
        v_float_units := v_float_bb/2::double precision;
        v_float_sb := floor(v_float_units);
        IF v_float_units-v_float_sb >= 0.5::double precision THEN
          v_float_sb := v_float_sb+1::double precision;
        END IF;
      EXCEPTION WHEN numeric_value_out_of_range THEN
        RAISE EXCEPTION 'Spin blind continuation is missing its finite frozen formula'
          USING ERRCODE='55000';
      END;
      IF v_float_bb <= 0 OR v_float_bb IN ('Infinity'::double precision,'-Infinity'::double precision,'NaN'::double precision)
         OR v_float_sb IN ('Infinity'::double precision,'-Infinity'::double precision,'NaN'::double precision) THEN
        RAISE EXCEPTION 'Spin blind continuation overflowed its stored formula'
          USING ERRCODE='55000';
      END IF;
      RETURN jsonb_build_object(
        'small_blind',v_float_sb,'big_blind',v_float_bb,'ante',0,
        'level_index',v_index,'source','spin_receipt_overflow','blind_capped',false
      );
    END IF;
    -- spinBlindsForLevel(index+1), including canonical values when a legacy
    -- persisted array is shorter than today's ten-row Spin ladder.
    v_bb := CASE v_index
      WHEN 0 THEN 20 WHEN 1 THEN 30 WHEN 2 THEN 40 WHEN 3 THEN 60
      WHEN 4 THEN 80 WHEN 5 THEN 100 WHEN 6 THEN 120 WHEN 7 THEN 150
      WHEN 8 THEN 180 WHEN 9 THEN 210
      ELSE round((210::numeric*power(1.4::numeric,v_index-9))/10)*10
    END;
    v_sb := round(v_bb/2);
    RETURN jsonb_build_object(
      'small_blind',v_sb,'big_blind',v_bb,'ante',0,
      'level_index',v_index,'source','spin_overflow','blind_capped',false
    );
  END IF;

  -- Ignore trailing break rows when choosing the overflow anchor.
  v_last_index := v_len-1;
  WHILE v_last_index>0
    AND lower(COALESCE(v_levels->v_last_index->>'isBreak','false'))='true'
  LOOP
    v_last_index := v_last_index-1;
  END LOOP;
  v_last := v_levels->v_last_index;

  -- Geometric mean of the last five positive advertised big-blind steps.
  WITH clean AS (
    SELECT e.ordinality::integer AS ord,
           COALESCE(
             CASE WHEN COALESCE(e.value->>'bigBlind','') ~ '^[0-9]+([.][0-9]+)?$'
                  THEN (e.value->>'bigBlind')::numeric END,
             CASE WHEN COALESCE(e.value->>'big_blind','') ~ '^[0-9]+([.][0-9]+)?$'
                  THEN (e.value->>'big_blind')::numeric END
           ) AS bb
      FROM jsonb_array_elements(v_levels) WITH ORDINALITY AS e(value,ordinality)
  ), tail AS (
    SELECT ord,bb FROM clean WHERE bb>0 ORDER BY ord DESC LIMIT 5
  )
  SELECT count(*)::integer,
         (array_agg(bb ORDER BY ord))[1],
         (array_agg(bb ORDER BY ord DESC))[1]
    INTO v_tail_count,v_tail_first,v_tail_last
    FROM tail;
  IF v_tail_count>=2 AND v_tail_first>0 AND v_tail_last>v_tail_first THEN
    v_ratio := power(v_tail_last/v_tail_first,1::numeric/(v_tail_count-1));
    IF v_ratio<=1 THEN v_ratio := 1.4; END IF;
  END IF;
  v_ratio := LEAST(1.6,GREATEST(1.15,v_ratio));
  v_factor := power(
    v_ratio,
    LEAST(GREATEST(1,v_index-v_len+1),40)
  );

  v_sb := LEAST(COALESCE(
    CASE WHEN COALESCE(v_last->>'smallBlind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'smallBlind')::numeric END,
    CASE WHEN COALESCE(v_last->>'small_blind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'small_blind')::numeric END,
    0
  )*v_factor,10000000);
  v_bb := LEAST(COALESCE(
    CASE WHEN COALESCE(v_last->>'bigBlind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'bigBlind')::numeric END,
    CASE WHEN COALESCE(v_last->>'big_blind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'big_blind')::numeric END,
    0
  )*v_factor,10000000);
  v_ante := LEAST(COALESCE(
    CASE WHEN COALESCE(v_last->>'ante','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'ante')::numeric END,
    0
  )*v_factor,10000000);

  -- Match capLevelToTournamentChips for generic overflow. The database wrapper
  -- supplies the exact durable chip issuance total; NULL means cap nothing.
  IF p_total_chips>0 THEN
    v_max_bb := p_total_chips/20;
    IF v_bb>v_max_bb AND v_max_bb>=2 THEN
      v_scale := v_max_bb/v_bb;
      v_bb := GREATEST(2,floor(v_bb*v_scale));
      v_sb := GREATEST(1,floor(v_sb*v_scale));
      v_ante := CASE WHEN v_ante>0 THEN GREATEST(1,floor(v_ante*v_scale)) ELSE 0 END;
      v_capped := true;
    END IF;
  END IF;

  /* A CAPPED LEVEL IS STILL A BLIND LEVEL (2026-09-09). Both ceilings above
     are applied to smallBlind, bigBlind and ante independently, so a deep
     overflow clamps all three to the same number and the level leaves here
     with SB = BB = ante. That is not a blind level: it makes
     fn_ensure_late_registration_capacity refuse the event a table for ever
     (v_sb>=v_bb), and the engine deals from this same answer. Enforce the
     invariant after the clamps instead of trusting it to survive them. */
  IF v_bb IS NULL OR v_bb < 2 THEN
    v_bb := 2;
    v_capped := true;
  END IF;
  IF v_sb IS NULL OR v_sb >= v_bb THEN
    v_sb := GREATEST(1, floor(v_bb / 2));
    v_capped := true;
  END IF;

  /* THE SMALL BLIND KEEPS ITS AUTHORED SHARE OF THE BIG BLIND (2026-09-21).
     The repair immediately above fires only on SB >= BB, which is the END of
     the distortion and not the whole of it. Between the level where the big
     blind reaches the 10,000,000 ceiling and the level where the small blind
     reaches it too, the big blind is pinned and the small blind is still
     growing underneath it: SB < BB throughout, nothing fires, and an authored
     1:2 walks up through 0.63 and 0.84 towards 1:1 while reporting
     blind_capped false. 528 published levels were sitting in that band on
     2026-09-21, 48 of them at 0.9762 of their big blind.

     The small blind's authored relationship to the big blind lives on the same
     anchor row this branch already grew both of them from, so read it there
     and hold the small blind to it - the ante ceiling below does exactly this
     with ante:bigBlind. This is a CEILING and never a floor: it can only lower
     a small blind, so no level becomes more expensive than it is today. An
     anchor authoring sb >= bb is left alone, because the repair above has
     already put the small blind at half the big blind and raising it back is
     not this ceiling's job. */
  v_anchor_sb := COALESCE(
    CASE WHEN COALESCE(v_last->>'smallBlind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'smallBlind')::numeric END,
    CASE WHEN COALESCE(v_last->>'small_blind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'small_blind')::numeric END,
    0
  );
  v_anchor_bb := COALESCE(
    CASE WHEN COALESCE(v_last->>'bigBlind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'bigBlind')::numeric END,
    CASE WHEN COALESCE(v_last->>'big_blind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'big_blind')::numeric END,
    0
  );
  IF v_sb > 0 AND v_anchor_bb > 0 AND v_anchor_sb > 0
     AND v_anchor_sb < v_anchor_bb THEN
    -- Multiply before dividing: the proportion itself is never materialised,
    -- so an anchor like 1500000/4000000 stays exact instead of losing its last
    -- digit to a rounded quotient.
    v_sb_ceiling := v_bb * v_anchor_sb / v_anchor_bb;
    -- Compared unrounded, assigned rounded: a level already sitting at its
    -- authored proportion is left alone rather than shaved by the floor.
    IF v_sb > v_sb_ceiling THEN
      v_sb := GREATEST(1, floor(v_sb_ceiling));
      v_capped := true;
    END IF;
  END IF;
  IF v_ante IS NULL OR v_ante < 0 THEN
    v_ante := 0;
  END IF;

  /* THE ANTE KEEPS ITS AUTHORED SHARE OF THE BIG BLIND (2026-09-20). The
     2026-09-09 repair above restored SB < BB after the two ceilings, but the
     ante left here still carrying whatever the 10,000,000 ceiling had
     saturated it to - on a deep overflow, the big blind itself. Two RUNNING
     events were dealing ante = BB on 2026-09-20.

     The ante's authored relationship to the big blind lives on the same
     anchor row this branch already grew SB and BB from, so read it there and
     hold the ante to it. This is a CEILING and never a floor: it can only
     lower an ante, so no level becomes more expensive than it is today. A
     structure that authors ante = BB (a big blind ante; AnteMath.ts counts
     two of them) has a proportion of 1 and is unchanged. A structure with no
     ante never reaches here with one. */
  v_anchor_bb := COALESCE(
    CASE WHEN COALESCE(v_last->>'bigBlind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'bigBlind')::numeric END,
    CASE WHEN COALESCE(v_last->>'big_blind','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'big_blind')::numeric END,
    0
  );
  v_anchor_ante := COALESCE(
    CASE WHEN COALESCE(v_last->>'ante','') ~ '^[0-9]+([.][0-9]+)?$'
         THEN (v_last->>'ante')::numeric END,
    0
  );
  IF v_ante > 0 THEN
    IF v_anchor_bb > 0 AND v_anchor_ante >= v_anchor_bb THEN
      -- A big blind ante authors ante = bigBlind. AnteMath.ts reads
      -- `ante >= bigBlind` as "this structure authored a TOTAL"; rounding the
      -- ante a fraction of a chip below a fractional big blind would flip that
      -- test and charge the table ante x seats instead. Hold it at the big
      -- blind exactly.
      v_ante_ceiling := v_bb;
    ELSIF v_anchor_bb > 0 AND v_anchor_ante > 0 THEN
      -- Multiply before dividing: the proportion itself is never materialised,
      -- so an anchor like 200000/1500000 stays exact instead of losing its
      -- last digit to a rounded quotient.
      v_ante_ceiling := v_bb * v_anchor_ante / v_anchor_bb;
    ELSE
      v_ante_ceiling := v_bb;
    END IF;
    -- Compared unrounded, assigned rounded: a level already sitting at its
    -- authored proportion is left alone rather than shaved by the floor.
    IF v_ante > v_ante_ceiling THEN
      v_ante := GREATEST(1, floor(v_ante_ceiling));
      v_capped := true;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'small_blind',v_sb,'big_blind',v_bb,'ante',v_ante,
    'level_index',v_index,'source','mtt_overflow',
    'overflow_ratio',v_ratio,'blind_capped',v_capped
  );
END;
$_$;


ALTER FUNCTION public.fn_resolve_tournament_blinds(p_blind_structure text, p_current_level integer, p_variant text, p_tournament_type text, p_total_chips numeric) OWNER TO postgres;

--
-- TOC entry 9133 (class 1255 OID 25706110)
-- Name: fn_resolve_tournament_terminal_outcome(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_tournament_terminal_outcome(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
DECLARE
  v_mode text := lower(btrim(COALESCE(p_settlement_mode,'')));
  v_t record;
  v_h public.tournament_terminal_settlements%ROWTYPE;
  v_receipt jsonb;
BEGIN
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  IF p_tournament_id IS NULL THEN
    RAISE EXCEPTION 'terminal outcome requires a tournament id'
      USING ERRCODE = '22004';
  END IF;
  IF v_mode NOT IN ('places','final_table_deal') THEN
    RAISE EXCEPTION 'unknown terminal outcome mode %',p_settlement_mode
      USING ERRCODE = '22023';
  END IF;
  SELECT t.* INTO v_t FROM public.tournaments t
   WHERE t.id = p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tournament % does not exist',p_tournament_id
      USING ERRCODE = 'P0002';
  END IF;
  IF lower(COALESCE(v_t.variant::text,'')) = 'satellite'
     OR upper(COALESCE(v_t.tournament_type::text,'')) = 'SATELLITE'
     OR v_t.satellite_target_id IS NOT NULL
     OR v_t.satellite_target IS NOT NULL THEN
    RAISE EXCEPTION 'tournament % is a satellite',p_tournament_id
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_h FROM public.tournament_terminal_settlements h
   WHERE h.tournament_id = p_tournament_id;
  IF FOUND THEN
    IF v_h.settlement_mode IS DISTINCT FROM v_mode
       OR (p_observed_winner_id IS NOT NULL
           AND v_h.winner_id IS DISTINCT FROM p_observed_winner_id) THEN
      RAISE EXCEPTION 'terminal outcome parameters disagree with stored receipt for %',
        p_tournament_id USING ERRCODE = '55000';
    END IF;
    v_receipt := public.fn_ca_tournament_terminal_receipt(
      p_tournament_id,p_observed_winner_id);
    RETURN jsonb_build_object(
      'ok',true,
      'terminal_committed',true,
      'definitively_not_committed',false,
      'status','COMPLETED',
      'mode',v_mode,
      'tournament_id',p_tournament_id,
      'receipt',v_receipt);
  END IF;

  IF upper(COALESCE(v_t.status::text,'')) = 'COMPLETED' THEN
    RAISE EXCEPTION 'completed tournament % has no atomic terminal receipt',
      p_tournament_id USING ERRCODE = 'P0404';
  END IF;
  IF upper(COALESCE(v_t.status::text,'')) NOT IN ('RUNNING','COMPLETING') THEN
    RAISE EXCEPTION 'tournament % has non-terminal-outcome status %',
      p_tournament_id,v_t.status USING ERRCODE = '55000';
  END IF;
  RETURN jsonb_build_object(
    'ok',true,
    'terminal_committed',false,
    'definitively_not_committed',true,
    'status',upper(v_t.status::text),
    'mode',v_mode,
    'tournament_id',p_tournament_id,
    'receipt','null'::jsonb);
END;
$$;


ALTER FUNCTION public.fn_resolve_tournament_terminal_outcome(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text) OWNER TO postgres;

--
-- TOC entry 48734 (class 0 OID 0)
-- Dependencies: 9133
-- Name: FUNCTION fn_resolve_tournament_terminal_outcome(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_resolve_tournament_terminal_outcome(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text) IS 'Service-only serialized transport-outcome resolver. It waits behind the global terminal transaction lock and returns either the verified committed receipt or definitive no-receipt RUNNING/COMPLETING state.';


--
-- TOC entry 4189 (class 1255 OID 26587217)
-- Name: fn_resolve_tournament_terminal_proposal_outcome(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_resolve_tournament_terminal_proposal_outcome(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text, p_proposal_id uuid, p_revision text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE p public.tournament_deal_proposals%ROWTYPE;
  e public.tournament_deal_proposal_executions%ROWTYPE; v_result jsonb; v_identity jsonb;
BEGIN
  PERFORM public.fn_ca_lock_settlement_lane_global();
  PERFORM 1 FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE;
  IF p_settlement_mode IS DISTINCT FROM 'final_table_deal' OR p_observed_winner_id IS NOT NULL
     OR p_proposal_id IS NULL OR p_revision IS NULL THEN
    RAISE EXCEPTION 'exact final-deal proposal request required' USING ERRCODE='22023';
  END IF;
  SELECT * INTO p FROM public.tournament_deal_proposals WHERE id=p_proposal_id
    AND tournament_id=p_tournament_id AND revision=p_revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'deal proposal request identity mismatch' USING ERRCODE='22023'; END IF;
  SELECT * INTO e FROM public.tournament_deal_proposal_executions WHERE tournament_id=p_tournament_id;
  IF FOUND AND (e.proposal_id IS DISTINCT FROM p.id OR e.revision IS DISTINCT FROM p.revision) THEN
    RAISE EXCEPTION 'different proposal owns the terminal receipt' USING ERRCODE='22023';
  END IF;
  v_result:=public.fn_resolve_tournament_terminal_outcome(p_tournament_id,p_observed_winner_id,p_settlement_mode);
  v_identity:=jsonb_build_object('proposal_id',p.id,'revision',p.revision);
  IF COALESCE((v_result->>'terminal_committed')::boolean,false) THEN
    IF e.proposal_id IS NULL THEN RAISE EXCEPTION 'terminal receipt lacks exact proposal proof' USING ERRCODE='23514'; END IF;
    RETURN jsonb_set(v_result||v_identity,'{receipt}',(v_result->'receipt')||v_identity);
  END IF;
  IF e.proposal_id IS NOT NULL THEN RAISE EXCEPTION 'proposal execution lacks its terminal receipt' USING ERRCODE='23514'; END IF;
  RETURN v_result||v_identity;
END;
$$;


ALTER FUNCTION public.fn_resolve_tournament_terminal_proposal_outcome(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text, p_proposal_id uuid, p_revision text) OWNER TO postgres;

--
-- TOC entry 7090 (class 1255 OID 14763921)
-- Name: fn_respond_chip_request(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_respond_chip_request(p_request_id uuid, p_action text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := auth.uid();
  v_req record;
  v_role text;
  v_send jsonb;
  v_op_id uuid;
  v_prior record;
begin
  if v_me is null then return jsonb_build_object('success', false, 'error', 'not authenticated'); end if;
  if p_action not in ('approve','decline','cancel') then
    return jsonb_build_object('success', false, 'error', 'invalid action');
  end if;

  select * into v_req from chip_requests where id = p_request_id for update;
  if not found then return jsonb_build_object('success', false, 'error', 'request not found'); end if;

  -- THE SAME KEY ON EVERY ATTEMPT BY THE SAME APPROVER. Derived from the
  -- request and the approver, so a retry after a lost response replays the
  -- original send instead of making a new one, and an approval another
  -- approver attempted and was refused (2026-10-09: the exact-intent gate binds
  -- a key to its first actor, so a request-only key left the request
  -- answerable by nobody else) never blocks this one. Money still moves once:
  -- the send and the status change commit together under the row lock above.
  v_op_id := md5('chip_request_approve:' || p_request_id::text || ':' || v_me::text)::uuid;

  if v_req.status <> 'pending' then
    -- A RETRY AFTER A LOST RESPONSE IS NOT A FAILURE. If this caller already
    -- answered this request, say what happened rather than reporting an error
    -- for work that succeeded.
    if v_req.responded_by = v_me then
      if v_req.status = 'approved' then
        -- Only claim a replay against a transaction actually written under
        -- this key. Approvals made before this migration used a random key,
        -- so nothing is found and the honest refusal below stands - re-sending
        -- them is the one outcome that would move money twice.
        select ct.id, ct.amount into v_prior
          from chip_transactions ct
         where ct.club_id = v_req.club_id
           and ct.from_user_id = v_me
           and ct.metadata ->> 'op_id' in (v_op_id::text,
                 md5('chip_request_approve:' || p_request_id::text)::uuid::text)
         limit 1;
        if found then
          return jsonb_build_object('success', true, 'status', 'approved',
                                    'replayed', true, 'transaction_id', v_prior.id,
                                    'amount', v_prior.amount);
        end if;
      else
        return jsonb_build_object('success', true, 'status', v_req.status,
                                  'replayed', true);
      end if;
    end if;
    return jsonb_build_object('success', false, 'error', 'request already ' || v_req.status);
  end if;

  if p_action = 'cancel' then
    if v_req.requester_id <> v_me then
      return jsonb_build_object('success', false, 'error', 'only the requester may cancel');
    end if;
    update chip_requests set status = 'cancelled', responded_by = v_me, responded_at = now()
     where id = p_request_id;
    return jsonb_build_object('success', true, 'status', 'cancelled');
  end if;

  v_role := public.fn_club_bank_role(v_req.club_id);
  if v_role is null or v_role not in ('owner','co_owner','admin','super_agent','agent','sub_agent') then
    return jsonb_build_object('success', false, 'error', 'you cannot answer chip requests here');
  end if;
  if v_role in ('super_agent','agent','sub_agent') and v_req.approver_id is distinct from v_me then
    return jsonb_build_object('success', false, 'error', 'this request is not addressed to you');
  end if;

  if p_action = 'decline' then
    update chip_requests set status = 'declined', responded_by = v_me, responded_at = now()
     where id = p_request_id;
    return jsonb_build_object('success', true, 'status', 'declined');
  end if;

  if v_me = v_req.requester_id then
    return jsonb_build_object('success', false, 'error', 'you cannot approve your own request');
  end if;

  -- Said before the send, so the operator is told WHY rather than reading a
  -- raw trigger message. The guard on chip_transactions is what actually
  -- enforces it; this is the sentence that reaches the screen.
  if public.fn_club_settlement_frozen(v_req.club_id) then
    return jsonb_build_object('success', false,
      'error', 'this club is squaring its books - approvals resume when the settlement freeze lifts');
  end if;

  v_send := public.fn_agent_wallet_send(
    v_req.club_id, v_req.requester_id, v_req.amount,
    'player_wallet', 'Chip Request Approved', v_op_id);
  if not coalesce((v_send ->> 'success')::boolean, false) then
    return jsonb_build_object('success', false,
      'error', coalesce(v_send ->> 'error', 'the send was refused'));
  end if;

  update chip_requests set status = 'approved', responded_by = v_me, responded_at = now()
   where id = p_request_id;

  return jsonb_build_object('success', true, 'status', 'approved',
                            'replayed', coalesce((v_send ->> 'replayed')::boolean, false),
                            'your_balance', (v_send ->> 'agent_wallet_after')::numeric,
                            'their_balance', (v_send ->> 'recipient_balance_after')::numeric);
end $$;


ALTER FUNCTION public.fn_respond_chip_request(p_request_id uuid, p_action text) OWNER TO postgres;

--
-- TOC entry 4841 (class 1255 OID 10798098)
-- Name: fn_respond_friend_challenge(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_respond_friend_challenge(p_challenge_id uuid, p_accept boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_row friend_challenges;
BEGIN
  SELECT * INTO v_row FROM friend_challenges WHERE id = p_challenge_id FOR UPDATE;
  IF v_row.id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;
  IF v_row.challengee_id <> auth.uid() THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
  END IF;
  IF v_row.status <> 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_responded');
  END IF;
  UPDATE friend_challenges
     SET status = CASE WHEN p_accept THEN 'active' ELSE 'declined' END
   WHERE id = p_challenge_id;
  RETURN jsonb_build_object('success', true, 'status', CASE WHEN p_accept THEN 'active' ELSE 'declined' END);
END; $$;


ALTER FUNCTION public.fn_respond_friend_challenge(p_challenge_id uuid, p_accept boolean) OWNER TO postgres;

--
-- TOC entry 5933 (class 1255 OID 34786292)
-- Name: fn_retire_agent_credit_reduction_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_retire_agent_credit_reduction_v1(p_expected_actor_id uuid, p_operation_id uuid, p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE prior jsonb;r public.accounting_credit_reduction_retirements_v1%ROWTYPE;
 surviving public.accounting_credit_reduction_retirements_v1%ROWTYPE;
BEGIN
 PERFORM public.fn_credit_reduction_lock_v1(p_expected_actor_id,p_operation_id,p_club_id);
 IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_expected_actor_id THEN
  RAISE EXCEPTION 'credit_reduction_actor_changed' USING ERRCODE='42501';END IF;
 prior:=public.fn_credit_reduction_observe_v1(p_expected_actor_id,p_operation_id,p_club_id);
 IF prior->>'state' IN('recorded','retired') THEN RETURN prior;END IF;
 IF prior->>'state' IS DISTINCT FROM 'absent' THEN
  RAISE EXCEPTION 'credit_reduction_evidence_conflict' USING ERRCODE='23514';END IF;
 r.id:=gen_random_uuid();r.contract_version:=1;r.actor_user_id:=p_expected_actor_id;
 r.operation_id:=p_operation_id;r.club_id:=p_club_id;r.retired_at:=clock_timestamp();
 INSERT INTO public.accounting_credit_reduction_retirements_v1 SELECT r.*;
 SELECT * INTO surviving FROM public.accounting_credit_reduction_retirements_v1 WHERE id=r.id;
 IF NOT FOUND OR to_jsonb(surviving) IS DISTINCT FROM to_jsonb(r) THEN
  RAISE EXCEPTION 'credit_reduction_retirement_write_unconfirmed' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM public.accounting_credit_reduction_operations_v1
  WHERE actor_user_id=p_expected_actor_id AND operation_id=p_operation_id) THEN
  RAISE EXCEPTION 'credit_reduction_evidence_conflict' USING ERRCODE='23514';END IF;
 RETURN prior||jsonb_build_object('state','retired','replayed',false,'retirement',public.fn_credit_reduction_retirement_payload_v1(r.id));
END $$;


ALTER FUNCTION public.fn_retire_agent_credit_reduction_v1(p_expected_actor_id uuid, p_operation_id uuid, p_club_id uuid) OWNER TO postgres;

