--
-- TOC entry 4838 (class 1255 OID 86944850)
-- Name: fn_retire_settled_club(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_retire_settled_club(p_club_id uuid, p_confirm_name text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET lock_timeout TO '15s'
    AS $$
DECLARE
  v_me uuid := auth.uid();
  v_club public.clubs%ROWTYPE;
  v_unwind jsonb;
  v_impact jsonb;
  v_result jsonb;
  v_operation_id uuid := gen_random_uuid();
  v_opening_tx_count bigint;
  v_opening_mint_count bigint;
  v_recipient uuid;
  v_opening_retired boolean := false;
BEGIN
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','Authentication Required');
  END IF;
  IF p_club_id IS NULL OR nullif(btrim(coalesce(p_confirm_name,'')),'') IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','Confirm The Club Name');
  END IF;
  IF length(coalesce(p_reason,'')) > 500 THEN
    RETURN jsonb_build_object('success',false,'error','Retirement Reason Is Too Long');
  END IF;

  -- Global settlement lane precedes every club/resource row lock.  The welcome
  -- unwind takes the same lane, so its nested call is re-entrant and cannot
  -- invert G -> club/resource ordering against another money authority.
  PERFORM public.fn_ca_lock_settlement_lane_global();
  PERFORM pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||p_club_id::text,0));
  SELECT * INTO v_club FROM public.clubs c WHERE c.id=p_club_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','Club Not Found'); END IF;
  IF v_club.owner_id IS DISTINCT FROM v_me THEN
    RETURN jsonb_build_object('success',false,'error','Only The Club Owner Can Retire This Club');
  END IF;
  IF btrim(p_confirm_name) IS DISTINCT FROM btrim(v_club.name) THEN
    RETURN jsonb_build_object('success',false,'error','The Club Name Confirmation Does Not Match');
  END IF;
  IF v_club.lifecycle_status='retired' THEN
    RETURN jsonb_build_object('success',true,'already_retired',true,'club_id',p_club_id,
      'retired_at',v_club.retired_at);
  END IF;

  PERFORM 1 FROM public.unions u WHERE u.id=p_club_id FOR UPDATE;
  PERFORM 1 FROM public.union_clubs uc
   WHERE uc.club_id=p_club_id OR uc.union_id=p_club_id ORDER BY uc.id FOR UPDATE;
  IF v_club.union_id IS NOT NULL
     OR coalesce((to_jsonb(v_club)->>'is_union')::boolean,false)
     OR EXISTS(SELECT 1 FROM public.unions u WHERE u.id=p_club_id)
     OR EXISTS(SELECT 1 FROM public.union_clubs uc
                WHERE uc.club_id=p_club_id OR uc.union_id=p_club_id) THEN
    RETURN jsonb_build_object('success',false,
      'error','Leave The Union Or Retire The Union Estate Through Union Administration First');
  END IF;

  -- This service-only helper performs its own exact no-play/economic proof and
  -- returns all opening BBJ/Spin principal to treasury.  Any refusal aborts the
  -- same transaction; no partial reset or retirement can commit.
  BEGIN
    v_unwind := public.fn_unwind_unused_first_club_welcome_package(p_club_id,v_operation_id);
  EXCEPTION WHEN SQLSTATE '55000' THEN
    RETURN jsonb_build_object('success',false,
      'error','This Club Has Welcome Games, Registrations Or Economics That Must Be Settled First',
      'welcome_unwind',jsonb_build_object('ok',false,'reason',SQLERRM));
  END;
  IF coalesce((v_unwind->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN jsonb_build_object('success',false,'error','The Welcome Package Is Not Safe To Unwind',
      'welcome_unwind',v_unwind);
  END IF;
  SELECT * INTO v_club FROM public.clubs c WHERE c.id=p_club_id FOR UPDATE;

  PERFORM 1 FROM public.cash_games WHERE club_id=p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.tournament_schedules WHERE club_id=p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.tournament_schedule_spawns sp
    JOIN public.tournament_schedules s ON s.id=sp.schedule_id
   WHERE s.club_id=p_club_id ORDER BY sp.id FOR UPDATE OF sp;
  PERFORM 1 FROM public.managed_game_schedules ms
   WHERE (ms.game_kind='table' AND EXISTS (
           SELECT 1 FROM public.tables t WHERE t.id=ms.game_id AND t.club_id=p_club_id))
      OR (ms.game_kind='tournament' AND EXISTS (
           SELECT 1 FROM public.tournaments t WHERE t.id=ms.game_id AND t.club_id=p_club_id))
   ORDER BY ms.schedule_id FOR UPDATE OF ms;

  v_impact := public.fn_club_retirement_impact(p_club_id);
  IF coalesce((v_impact->>'active_cash_games')::bigint,0)<>0
     OR coalesce((v_impact->>'active_tournament_schedules')::bigint,0)<>0
     OR coalesce((v_impact->>'pending_managed_commands')::bigint,0)<>0
     OR coalesce((v_impact->>'active_diamond_games')::bigint,0)<>0 THEN
    RETURN jsonb_build_object('success',false,
      'error','Disable Every Cash Game, Tournament Schedule, Diamond Game And Pending Game Command First',
      'impact',v_impact);
  END IF;

  -- Only the exact untouched new-club issuance is automatically retired.
  -- Every other estate still follows the original explicit settlement flow.
  IF coalesce((v_impact->>'wallet_chips')::numeric,0)=100000
     AND coalesce((v_impact->>'running_tables')::bigint,0)=0
     AND coalesce((v_impact->>'active_tournaments')::bigint,0)=0
     AND coalesce((v_impact->>'diamonds')::numeric,0)=0
     AND coalesce((v_impact->>'inventory_items')::bigint,0)=0
     AND coalesce((v_impact->>'open_obligations')::bigint,0)=0
     AND v_club.chip_treasury=100000
     AND coalesce(v_club.chip_pool,0)=0
     AND coalesce(v_club.promo_balance,0)=0
     AND coalesce(v_club.insurance_balance,0)=0 THEN
    SELECT count(*) INTO v_opening_tx_count
      FROM public.chip_transactions t
     WHERE t.club_id=p_club_id AND t.transaction_type='club_opening_grant'
       AND t.amount=100000 AND t.balance_after=100000
       AND t.metadata->>'mint_op_id'='club-opening-grant:'||p_club_id::text;
    SELECT count(*) INTO v_opening_mint_count
      FROM public.ca_mint_ledger m
     WHERE m.asset='chips' AND m.action='mint' AND m.holder_type='club'
       AND m.holder_id=p_club_id;
    IF v_opening_tx_count<>1 OR v_opening_mint_count<>1 OR NOT EXISTS (
      SELECT 1 FROM public.ca_mint_ledger m
       WHERE m.op_id='club-opening-grant:'||p_club_id::text
         AND m.asset='chips' AND m.action='mint' AND m.holder_type='club'
         AND m.holder_id=p_club_id AND m.amount=100000
         AND m.balance_before=0 AND m.balance_after=100000
    ) THEN
      RETURN jsonb_build_object('success',false,
        'error','The Club Bank Is Not The Exact Untouched Opening Grant','impact',v_impact);
    END IF;

    PERFORM public.fn_ca_declare_ledger('burn','chip_retirement',NULL,NULL,
      'club-owner-retire-opening:'||p_club_id::text,NULL);
    UPDATE public.clubs SET chip_treasury=0,updated_at=clock_timestamp()
     WHERE id=p_club_id AND chip_treasury=100000;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'CLUB_OPENING_GRANT_CHANGED_DURING_RETIREMENT' USING ERRCODE='55000';
    END IF;
    PERFORM set_config('app.ledger_category','',true);
    PERFORM set_config('app.ledger_counterparty','',true);
    v_club.chip_treasury := 0;
    v_opening_retired := true;
  END IF;

  -- The original retained-record authority rechecks every balance and
  -- obligation, writes the audit trail, and flips lifecycle atomically.
  v_result := public.fn_retire_settled_club_core_20260906(
    p_club_id,p_confirm_name,p_reason
  );

  -- The scope event written by the core becomes unreadable once creation
  -- authority closes.  Recipient events remain visible long enough for every
  -- signed-in member surface to invalidate immediately.
  IF coalesce((v_result->>'success')::boolean,false)
     AND coalesce((v_result->>'already_retired')::boolean,false) IS FALSE THEN
    FOR v_recipient IN
      SELECT v_club.owner_id
      UNION
      SELECT cm.user_id FROM public.club_members cm WHERE cm.club_id=p_club_id
    LOOP
      PERFORM public.fn_emit_game_management_event(
        'club_identity_changed',p_club_id,NULL,v_recipient,'club',p_club_id,NULL,
        jsonb_build_object('operation','retire','lifecycle_status','retired','records_retained',true)
      );
    END LOOP;
  END IF;
  RETURN v_result || jsonb_build_object(
    'welcome_unwind',v_unwind,
    'opening_grant_retired',v_opening_retired
  );
END
$$;


ALTER FUNCTION public.fn_retire_settled_club(p_club_id uuid, p_confirm_name text, p_reason text) OWNER TO postgres;

--
-- TOC entry 48742 (class 0 OID 0)
-- Dependencies: 4838
-- Name: FUNCTION fn_retire_settled_club(p_club_id uuid, p_confirm_name text, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_retire_settled_club(p_club_id uuid, p_confirm_name text, p_reason text) IS 'Owner-only retained-record retirement. Atomically unwinds an exact unused welcome package and exact untouched 100,000 opening grant, or requires the established fully settled estate. Never physically deletes a real club.';


--
-- TOC entry 8791 (class 1255 OID 22319508)
-- Name: fn_retire_settled_club_core_20260906(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_retire_settled_club_core_20260906(p_club_id uuid, p_confirm_name text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET lock_timeout TO '5s'
    AS $$
DECLARE
  v_me uuid := auth.uid();
  v_club public.clubs%ROWTYPE;
  v_impact jsonb;
  v_reason text;
  v_retired_at timestamptz;
BEGIN
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Authentication Required');
  END IF;
  IF p_club_id IS NULL OR nullif(btrim(coalesce(p_confirm_name, '')), '') IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Confirm The Club Name');
  END IF;
  IF length(coalesce(p_reason, '')) > 500 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Retirement Reason Is Too Long');
  END IF;
  v_reason := coalesce(nullif(btrim(p_reason), ''), 'Owner Requested Retirement');

  PERFORM pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:' || p_club_id::text, 0));
  SELECT * INTO v_club FROM public.clubs c WHERE c.id = p_club_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Club Not Found');
  END IF;
  IF v_club.owner_id IS DISTINCT FROM v_me THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only The Club Owner Can Retire This Club');
  END IF;
  IF btrim(p_confirm_name) IS DISTINCT FROM btrim(v_club.name) THEN
    RETURN jsonb_build_object('success', false, 'error', 'The Club Name Confirmation Does Not Match');
  END IF;

  -- Lost-response retry: still owner/name authorised, but no second audit/event.
  IF v_club.lifecycle_status = 'retired' THEN
    RETURN jsonb_build_object(
      'success', true, 'already_retired', true, 'club_id', p_club_id,
      'retired_at', v_club.retired_at
    );
  END IF;

  -- Canonical union resolution uses all three representations. Live estates
  -- have disagreed between the pointer and junction table before, so neither is
  -- accepted as a substitute for the others.
  PERFORM 1 FROM public.unions u WHERE u.id = p_club_id FOR UPDATE;
  PERFORM 1 FROM public.union_clubs uc
   WHERE uc.club_id = p_club_id OR uc.union_id = p_club_id
   ORDER BY uc.id FOR UPDATE;
  IF v_club.union_id IS NOT NULL
     OR coalesce((to_jsonb(v_club) ->> 'is_union')::boolean, false)
     OR EXISTS (SELECT 1 FROM public.unions u WHERE u.id = p_club_id)
     OR EXISTS (SELECT 1 FROM public.union_clubs uc
                 WHERE uc.club_id = p_club_id OR uc.union_id = p_club_id) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Leave The Union Or Retire The Union Estate Through Union Administration First'
    );
  END IF;

  -- Lock parents before their dependent rows, matching game registration/seat
  -- writer order. The club FOR UPDATE also makes a new FK child wait; after this
  -- transaction commits, the retired-row trigger refuses that waiting writer.
  PERFORM 1 FROM public.tables WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1
    FROM public.table_seats ts JOIN public.tables t ON t.id = ts.table_id
   WHERE t.club_id = p_club_id ORDER BY ts.id FOR UPDATE OF ts;
  PERFORM 1 FROM public.tournaments WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1
    FROM public.tournament_escrow te
    JOIN public.tournaments tr ON tr.id = te.tournament_id
   WHERE tr.club_id = p_club_id ORDER BY te.tournament_id FOR UPDATE OF te;
  PERFORM 1
    FROM public.tournament_players tp
    JOIN public.tournaments tr ON tr.id = tp.tournament_id
   WHERE tr.club_id = p_club_id ORDER BY tp.id FOR UPDATE OF tp;
  PERFORM 1 FROM public.club_members WHERE club_id = p_club_id ORDER BY user_id FOR UPDATE;
  PERFORM 1 FROM public.agents WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.club_wallets WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.club_diamond_wallets WHERE club_id = p_club_id FOR UPDATE;
  PERFORM 1 FROM public.bbj_pools WHERE club_id = p_club_id FOR UPDATE;
  PERFORM 1 FROM public.spin_bonus_pools WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.club_opening_setups WHERE club_id = p_club_id FOR UPDATE;
  PERFORM 1 FROM public.promo_vault_inventory
   WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.cashout_requests WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.chip_requests WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.chip_escrow_holds WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.tournament_tickets WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.settlement_periods WHERE club_id = p_club_id ORDER BY id FOR UPDATE;
  PERFORM 1
    FROM public.credit_invoices ci JOIN public.agents a ON a.id = ci.agent_id
   WHERE a.club_id = p_club_id ORDER BY ci.id FOR UPDATE OF ci;
  PERFORM 1
    FROM public.chip_escrow ce
    JOIN public.cashout_requests cr ON cr.id = ce.cashout_request_id
   WHERE cr.club_id = p_club_id ORDER BY ce.id FOR UPDATE OF ce;

  v_impact := public.fn_club_retirement_impact(p_club_id);
  IF coalesce((v_impact ->> 'running_tables')::bigint, 0) <> 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Close Every Running Table Before Retiring This Club', 'impact', v_impact);
  END IF;
  IF coalesce((v_impact ->> 'active_tournaments')::bigint, 0) <> 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Complete Or Cancel Every Tournament Before Retiring This Club', 'impact', v_impact);
  END IF;
  IF coalesce((v_impact ->> 'wallet_chips')::numeric, 0) <> 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Settle Every Club, Member, Agent, Pool, Seat, Escrow And Ticket Balance First', 'impact', v_impact);
  END IF;
  IF coalesce((v_impact ->> 'diamonds')::numeric, 0) <> 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Redeem Or Transfer Every Club And Member Diamond Balance First', 'impact', v_impact);
  END IF;
  IF coalesce((v_impact ->> 'inventory_items')::bigint, 0) <> 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Grant Or Resolve Every Promo Vault Inventory Item First', 'impact', v_impact);
  END IF;
  IF coalesce((v_impact ->> 'open_obligations')::bigint, 0) <> 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Resolve Every Open Game, Cashier, Credit And Settlement Obligation First', 'impact', v_impact);
  END IF;

  v_retired_at := clock_timestamp();
  PERFORM set_config('app.club_retirement_write', 'on', true);
  UPDATE public.clubs
     SET lifecycle_status = 'retired',
         retired_at = v_retired_at,
         retired_by = v_me,
         retirement_reason = v_reason,
         is_public = false,
         requires_approval = true,
         updated_at = v_retired_at
   WHERE id = p_club_id AND lifecycle_status = 'active';
  PERFORM set_config('app.club_retirement_write', '', true);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'club lifecycle changed during retirement' USING ERRCODE = '55000';
  END IF;

  INSERT INTO public.audit_trail(
    actor_id, actor_role, action, target_type, target_id, club_id,
    before_state, after_state, reason
  ) VALUES (
    v_me, 'owner', 'retire_club', 'club', p_club_id, p_club_id,
    jsonb_build_object(
      'lifecycle_status', v_club.lifecycle_status,
      'is_public', v_club.is_public,
      'requires_approval', v_club.requires_approval
    ),
    jsonb_build_object(
      'lifecycle_status', 'retired',
      'retired_at', v_retired_at,
      'records_retained', true,
      'is_public', false,
      'requires_approval', true
    ),
    v_reason
  );

  PERFORM public.fn_emit_game_management_event(
    'club_identity_changed', p_club_id, NULL, NULL, 'club', p_club_id, NULL,
    jsonb_build_object(
      'operation', 'retire', 'lifecycle_status', 'retired',
      'records_retained', true
    )
  );

  RETURN jsonb_build_object(
    'success', true, 'already_retired', false, 'club_id', p_club_id,
    'retired_at', v_retired_at, 'records_retained', true
  );
END
$$;


