--
-- TOC entry 4114 (class 1255 OID 15205809)
-- Name: fn_reveal_rabbit_hunt(uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_reveal_rabbit_hunt(p_table_id uuid, p_hand_number bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller   uuid := (SELECT auth.uid());
  v_offer    record;
  v_played   boolean := false;
  v_is_vip   boolean := false;
  v_used     integer := 0;
  v_month    text := to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM');
  v_free_cap constant integer := 100;
  v_price    integer;
  v_deduct   jsonb;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'authentication required');
  END IF;

  SELECT * INTO v_offer FROM public.rabbit_hunt_offers
   WHERE table_id = p_table_id AND hand_number = p_hand_number;
  IF v_offer.table_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'no rabbit hunt available for that hand');
  END IF;

  -- Already revealed this exact hand: free, and no second charge.
  IF EXISTS (SELECT 1 FROM public.rabbit_hunt_reveals r
              WHERE r.user_id = v_caller AND r.table_id = p_table_id
                AND r.hand_number = p_hand_number) THEN
    RETURN jsonb_build_object('success', true, 'charged', 0, 'already_revealed', true,
                              'cards', v_offer.cards, 'board_len', v_offer.board_len);
  END IF;

  -- You may only rabbit hunt a hand you were dealt into.
  SELECT EXISTS (
    SELECT 1 FROM public.hand_history h
     WHERE h.table_id = p_table_id AND h.hand_number = p_hand_number
       AND jsonb_typeof(h.players) = 'array'
       AND EXISTS (SELECT 1 FROM jsonb_array_elements(h.players) pl
                    WHERE pl->>'userId' = v_caller::text)
  ) INTO v_played;

  IF NOT v_played THEN
    -- Settlement may not have written hand_history yet; a live seat counts.
    SELECT EXISTS (
      SELECT 1 FROM public.table_seats s
       WHERE s.table_id = p_table_id AND s.user_id = v_caller
         AND (s.left_at IS NULL OR s.left_at > now() - interval '5 minutes')
    ) INTO v_played;
  END IF;

  IF NOT v_played THEN
    RETURN jsonb_build_object('success', false, 'error', 'you did not play that hand');
  END IF;

  -- An expired VIP is not a VIP.
  SELECT COALESCE(is_vip, false) AND (vip_expires_at IS NULL OR vip_expires_at > now())
    INTO v_is_vip FROM public.profiles WHERE id = v_caller;
  v_is_vip := COALESCE(v_is_vip, false);

  SELECT COALESCE(usage_count, 0) INTO v_used
    FROM public.vip_feature_usage_monthly
   WHERE user_id = v_caller AND feature = 'rabbit_hunt' AND month = v_month;
  v_used := COALESCE(v_used, 0);

  IF v_is_vip AND v_used < v_free_cap THEN
    PERFORM public.fn_increment_vip_usage(v_caller, 'rabbit_hunt');
    INSERT INTO public.rabbit_hunt_reveals (user_id, table_id, hand_number, charged)
    VALUES (v_caller, p_table_id, p_hand_number, 0);
    RETURN jsonb_build_object('success', true, 'charged', 0,
                              'free_remaining', v_free_cap - v_used - 1,
                              'cards', v_offer.cards, 'board_len', v_offer.board_len);
  END IF;

  SELECT diamond_cost INTO v_price FROM public.feature_pricing WHERE feature = 'rabbit_hunt';
  v_price := COALESCE(v_price, 1);

  -- Deterministic reference_id makes the charge idempotent per (hand, user).
  -- Cooldown explicitly 0: consecutive hands are legitimate, rapid hunts.
  v_deduct := public.deduct_diamonds(
    p_user_id          := v_caller,
    p_amount           := v_price,
    p_description      := 'Rabbit hunt',
    p_transaction_type := 'feature_purchase',
    p_source           := 'rabbit_hunt',
    p_metadata         := jsonb_build_object('table_id', p_table_id, 'hand_number', p_hand_number),
    p_reference_id     := 'rabbit_' || p_table_id::text || '_' || p_hand_number::text || '_' || v_caller::text,
    p_cooldown_seconds := 0
  );

  IF COALESCE((v_deduct->>'success')::boolean, false) = false THEN
    RETURN jsonb_build_object('success', false,
      'error', COALESCE(v_deduct->>'error', 'not enough diamonds'),
      'diamond_cost', v_price);
  END IF;

  PERFORM public.fn_increment_vip_usage(v_caller, 'rabbit_hunt');
  INSERT INTO public.rabbit_hunt_reveals (user_id, table_id, hand_number, charged)
  VALUES (v_caller, p_table_id, p_hand_number, v_price);

  RETURN jsonb_build_object('success', true, 'charged', v_price,
                            'cards', v_offer.cards, 'board_len', v_offer.board_len);
END
$$;


ALTER FUNCTION public.fn_reveal_rabbit_hunt(p_table_id uuid, p_hand_number bigint) OWNER TO postgres;

--
-- TOC entry 48749 (class 0 OID 0)
-- Dependencies: 4114
-- Name: FUNCTION fn_reveal_rabbit_hunt(p_table_id uuid, p_hand_number bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_reveal_rabbit_hunt(p_table_id uuid, p_hand_number bigint) IS 'Pays for and returns the rabbit-hunt cards for one hand. VIP: first 100 per calendar month free, then 1 diamond. Non-VIP: 1 diamond. Refuses if the caller did not play the hand. Charges at most once per (user, table, hand).';


--
-- TOC entry 9017 (class 1255 OID 19909951)
-- Name: fn_review_anti_cheat_flag(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_review_anti_cheat_flag(p_club_id uuid, p_flag_id uuid, p_status text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_updated integer;
BEGIN
  IF NOT fn_ca_can_review_integrity(p_club_id) THEN
    RAISE EXCEPTION 'not authorized for this club' USING ERRCODE = '42501';
  END IF;

  IF coalesce(p_status, '') NOT IN ('reviewed', 'dismissed', 'actioned') THEN
    RAISE EXCEPTION 'a flag can only be reviewed, dismissed or actioned'
      USING ERRCODE = '22023';
  END IF;

  UPDATE anti_cheat_flags f
     SET status = p_status,
         reviewed_by = auth.uid(),
         reviewed_at = now(),
         review_notes = nullif(btrim(coalesce(p_notes, '')), '')
   WHERE f.id = p_flag_id
     AND (
           f.club_id = p_club_id
           OR (f.club_id IS NULL AND EXISTS (
                 SELECT 1 FROM club_members cm
                  WHERE cm.club_id = p_club_id AND cm.user_id = f.player_id))
         );

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  -- Zero rows is a failure, not a quiet success. It is the exact shape the old
  -- client UPDATE hid.
  IF v_updated = 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'flag_not_in_this_club', 'updated', 0);
  END IF;

  INSERT INTO anti_cheat_events (club_id, player_id, event_type, details, triggered_by)
  SELECT p_club_id, f.player_id, 'flag_' || p_status,
         jsonb_build_object('flag_id', f.id, 'flag_type', f.flag_type,
                            'severity', f.severity, 'notes', f.review_notes),
         auth.uid()
    FROM anti_cheat_flags f
   WHERE f.id = p_flag_id;

  RETURN jsonb_build_object('ok', true, 'updated', v_updated, 'status', p_status);
END;
$$;


ALTER FUNCTION public.fn_review_anti_cheat_flag(p_club_id uuid, p_flag_id uuid, p_status text, p_notes text) OWNER TO postgres;

--
-- TOC entry 4371 (class 1255 OID 34785919)
-- Name: fn_review_credit_request(uuid, text, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_review_credit_request(p_request_id uuid, p_decision text, p_approved_amount numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text, p_expected_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
DECLARE actor uuid:=auth.uid(); scope_id uuid; request public.credit_requests%ROWTYPE;
 agent_ids uuid[]; amount numeric; notes text:=NULLIF(btrim(p_notes),''); result jsonb; old_context text;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'credit_request_authentication_required' USING ERRCODE='42501';END IF;
 IF p_expected_actor_id IS NULL OR p_expected_actor_id IS DISTINCT FROM actor THEN
  RAISE EXCEPTION 'credit_request_actor_changed' USING ERRCODE='42501';END IF;
 IF p_request_id IS NULL OR p_decision IS NULL OR p_decision NOT IN('approved','denied','cancelled')
 THEN RAISE EXCEPTION 'credit_request_invalid_decision' USING ERRCODE='22023';END IF;
 IF p_decision<>'approved' AND p_approved_amount IS NOT NULL
 THEN RAISE EXCEPTION 'credit_request_unexpected_approved_amount' USING ERRCODE='22023';END IF;
 SELECT club_id INTO scope_id FROM public.credit_requests WHERE id=p_request_id;
 IF scope_id IS NULL THEN RAISE EXCEPTION 'credit_request_missing' USING ERRCODE='22023';END IF;
 -- Same order as the canonical admin/role writers. Never hold a request row
 -- while waiting for a club agreement held by a competing financial update.
 PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||scope_id::text,0));
 SELECT * INTO request FROM public.credit_requests WHERE id=p_request_id AND club_id=scope_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'credit_request_scope_changed' USING ERRCODE='23514';END IF;
 IF p_decision='cancelled' THEN
  IF actor IS DISTINCT FROM request.requester_id THEN
   RAISE EXCEPTION 'credit_request_only_requester_can_cancel' USING ERRCODE='42501';END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=scope_id AND
    (c.owner_id=actor OR EXISTS(SELECT 1 FROM public.club_members m WHERE m.club_id=scope_id AND m.user_id=actor
       AND m.role IN('owner','co_owner','admin') AND m.status IN('active','approved'))))
  THEN RAISE EXCEPTION 'credit_request_manager_required' USING ERRCODE='42501';END IF;
 END IF;
 amount:=CASE WHEN p_decision='approved' THEN COALESCE(p_approved_amount,request.requested_amount) END;
 IF p_decision='approved' AND (amount IS NULL OR amount::text IN('NaN','Infinity','-Infinity')
   OR amount<=0 OR amount<>round(amount,2))
 THEN RAISE EXCEPTION 'credit_request_amount_must_be_positive_cents' USING ERRCODE='22023';END IF;
 -- The request row itself is the durable decision identity. A later limit
 -- change is never rolled back by a retry of this already-completed request.
 IF request.status IS DISTINCT FROM 'pending' THEN
  IF request.decision_authority_version IS DISTINCT FROM 1 THEN
   RAISE EXCEPTION 'credit_request_legacy_review_unverified' USING ERRCODE='23514';END IF;
  IF request.status=p_decision AND request.reviewed_by=actor AND request.reviewed_at IS NOT NULL
    AND request.approved_amount IS NOT DISTINCT FROM amount
    AND NULLIF(btrim(request.reviewer_notes),'') IS NOT DISTINCT FROM notes
  THEN RETURN jsonb_build_object('success',true,'replayed',true,'request',to_jsonb(request)||jsonb_build_object('requested_amount',request.requested_amount::text,'approved_amount',request.approved_amount::text));END IF;
  RAISE EXCEPTION 'credit_request_decision_conflict' USING ERRCODE='23514';
 END IF;
 IF p_decision='approved' THEN
  SELECT array_agg(a.id ORDER BY a.id) INTO agent_ids FROM public.agents a
   WHERE a.club_id=scope_id AND a.user_id=request.requester_id;
  IF cardinality(agent_ids) IS DISTINCT FROM 1 THEN
   RAISE EXCEPTION 'credit_request_agent_scope_missing_or_ambiguous' USING ERRCODE='23514';END IF;
  result:=public.fn_admin_update_agent(p_agent_id=>agent_ids[1],p_credit_limit=>amount,
   p_assigned_by=>actor,p_credit_reason=>COALESCE(notes,'Credit request approved: '||request.id::text));
  IF result->>'success' IS DISTINCT FROM 'true' OR result->>'agent_id' IS DISTINCT FROM agent_ids[1]::text
    OR result->>'club_id' IS DISTINCT FROM scope_id::text OR (result->>'credit_limit')::numeric IS DISTINCT FROM amount
  THEN RAISE EXCEPTION 'credit_request_credit_authority_refused' USING ERRCODE='23514',DETAIL=result::text;END IF;
 END IF;
 old_context:=current_setting('app.credit_request_decision',true);
 PERFORM set_config('app.credit_request_decision',request.id::text||':'||actor::text,true);
 UPDATE public.credit_requests SET status=p_decision,approved_amount=amount,reviewed_by=actor,
  reviewed_at=transaction_timestamp(),reviewer_notes=notes,decision_authority_version=1 WHERE id=request.id AND status='pending'
  RETURNING * INTO request;
 IF NOT FOUND THEN RAISE EXCEPTION 'credit_request_decision_lost' USING ERRCODE='23514';END IF;
 PERFORM set_config('app.credit_request_decision',COALESCE(old_context,''),true);
 RETURN jsonb_build_object('success',true,'replayed',false,'request',to_jsonb(request)||jsonb_build_object('requested_amount',request.requested_amount::text,'approved_amount',request.approved_amount::text));
END $$;


ALTER FUNCTION public.fn_review_credit_request(p_request_id uuid, p_decision text, p_approved_amount numeric, p_notes text, p_expected_actor_id uuid) OWNER TO postgres;

--
-- TOC entry 9593 (class 1255 OID 8950596)
-- Name: fn_review_join_request(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_review_join_request(p_club_id uuid, p_user_id uuid, p_approve boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_found boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NOT is_club_admin(p_club_id, v_uid) THEN
    RAISE EXCEPTION 'Not authorized to review join requests for this club';
  END IF;

  IF p_approve THEN
    -- ca-commerce-admission: approving a NEW member is a prospective owner
    -- action (R2 4.3, D22). Shadow records and proceeds; enforced refuses
    -- here, before the row changes. Existing members are never re-checked.
    IF EXISTS (SELECT 1 FROM public.club_members
                WHERE club_id = p_club_id AND user_id = p_user_id AND status = 'pending') THEN
      DECLARE
        v_ca_admission jsonb := public.fn_ca_commerce_admit('club', p_club_id, 'approve_member', 'fn_review_join_request', p_user_id);
      BEGIN
        IF NOT COALESCE((v_ca_admission->>'allowed')::boolean, true) THEN
          RETURN jsonb_build_object('success', false, 'error', v_ca_admission->>'message',
            'code', 'operating_access_required', 'reason', v_ca_admission->>'reason');
        END IF;
      END;
    END IF;
    UPDATE club_members
      SET status = 'active'
      WHERE club_id = p_club_id AND user_id = p_user_id AND status = 'pending';
    GET DIAGNOSTICS v_found = ROW_COUNT;
  ELSE
    DELETE FROM club_members
      WHERE club_id = p_club_id AND user_id = p_user_id AND status = 'pending';
    GET DIAGNOSTICS v_found = ROW_COUNT;
  END IF;

  IF NOT v_found THEN
    RETURN jsonb_build_object('success', false, 'error', 'No pending request found');
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION public.fn_review_join_request(p_club_id uuid, p_user_id uuid, p_approve boolean) OWNER TO postgres;

--
-- TOC entry 4352 (class 1255 OID 103569780)
-- Name: fn_review_video_attribution_update(uuid, integer, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_review_video_attribution_update(p_request_id uuid, p_expected_version integer, p_decision text, p_reason text, p_actor_id uuid) RETURNS public.video_attribution_update_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE r public.video_attribution_update_requests; a public.video_attribution_records;
BEGIN
  IF coalesce(auth.role()::text,'')<>'service_role' OR p_actor_id IS NULL OR p_decision NOT IN ('approved','rejected') OR nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'service role, actor, decision and reason required' USING ERRCODE='42501'; END IF;
  UPDATE public.video_attribution_update_requests SET status=p_decision,reviewed_by=p_actor_id,reviewed_at=now(),review_reason=left(btrim(p_reason),500),version=version+1,updated_at=now()
  WHERE id=p_request_id AND version=p_expected_version AND status='pending' RETURNING * INTO r;
  IF r.id IS NULL THEN RAISE EXCEPTION 'attribution request version or transition conflict'; END IF;
  SELECT * INTO a FROM public.video_attribution_records WHERE id=r.attribution_record_id FOR UPDATE;
  IF p_decision='approved' THEN
    UPDATE public.video_attribution_records SET creator_name=r.proposed_creator_name,attribution_url=r.proposed_attribution_url,status='active',verified_by=p_actor_id,verified_at=now(),updated_at=now(),version=version+1 WHERE id=a.id RETURNING * INTO a;
    UPDATE public.video_library_videos SET attribution_name=a.creator_name,attribution_url=a.attribution_url WHERE id=a.video_id;
    UPDATE public.social_posts SET attribution_name=a.creator_name,attribution_url=a.attribution_url WHERE canonical_asset_key=a.canonical_asset_key;
    UPDATE public.social_reels SET attribution_name=a.creator_name,attribution_url=a.attribution_url WHERE canonical_asset_key=a.canonical_asset_key;
  ELSE
    UPDATE public.video_attribution_records SET status='active',updated_at=now(),version=version+1 WHERE id=a.id;
  END IF;
  RETURN r;
END $$;


