    CONSTRAINT video_creator_submissions_attribution_name_check CHECK (((length(btrim(attribution_name)) >= 2) AND (length(btrim(attribution_name)) <= 160))),
    CONSTRAINT video_creator_submissions_attribution_url_check CHECK ((attribution_url ~ '^https://'::text)),
    CONSTRAINT video_creator_submissions_check CHECK (((((youtube_video_id IS NOT NULL))::integer + ((upload_ticket_id IS NOT NULL))::integer) = 1)),
    CONSTRAINT video_creator_submissions_check1 CHECK (((youtube_video_id IS NULL) OR ((youtube_video_id ~ '^[A-Za-z0-9_-]{11}$'::text) AND (canonical_asset_key = ('youtube:'::text || youtube_video_id))))),
    CONSTRAINT video_creator_submissions_check2 CHECK (((valid_until IS NULL) OR (valid_until > valid_from))),
    CONSTRAINT video_creator_submissions_check3 CHECK (((cardinality(proposed_permitted_uses) > 0) AND (cardinality(proposed_territories) > 0))),
    CONSTRAINT video_creator_submissions_check4 CHECK (((disclosure_kind <> ALL (ARRAY['sponsored'::text, 'promotional'::text])) OR ((length(btrim(sponsor_name)) >= 2) AND (length(btrim(sponsor_name)) <= 160)))),
    CONSTRAINT video_creator_submissions_disclosure_kind_check CHECK ((disclosure_kind = ANY (ARRAY['organic'::text, 'sponsored'::text, 'promotional'::text, 'generated'::text, 'community'::text]))),
    CONSTRAINT video_creator_submissions_proposed_rights_status_check CHECK ((proposed_rights_status = ANY (ARRAY['embed_only'::text, 'owned'::text, 'licensed'::text, 'user_authorized'::text]))),
    CONSTRAINT video_creator_submissions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending'::text, 'in_review'::text, 'approved'::text, 'rejected'::text, 'withdrawn'::text, 'taken_down'::text]))),
    CONSTRAINT video_creator_submissions_title_check CHECK (((length(btrim(title)) >= 3) AND (length(btrim(title)) <= 240))),
    CONSTRAINT video_creator_submissions_version_check CHECK ((version > 0))
);


