--
-- TOC entry 4957 (class 1255 OID 34785906)
-- Name: fn_rotate_push_subscription(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_rotate_push_subscription(p_user_id uuid, p_expected jsonb, p_replacement jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE source public.push_subscriptions%ROWTYPE; target public.push_subscriptions%ROWTYPE;
 old_endpoint text:=p_expected->>'endpoint'; new_endpoint text:=p_replacement->>'endpoint';
 revision text:=p_expected->>'rotation_revision'; retired_revision text;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_user_id IS NULL OR jsonb_typeof(p_expected) IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_replacement) IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_expected->'rotation_revision') IS DISTINCT FROM 'string'
    OR revision !~ '^[1-9][0-9]{0,18}$'
    OR COALESCE(p_expected->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    OR COALESCE(p_expected->>'device_id','') !~ '^[A-Za-z0-9-]{8,64}$'
    OR p_expected->>'transport' IS DISTINCT FROM 'webpush'
    OR COALESCE(length(old_endpoint),0) NOT BETWEEN 1 AND 4096
    OR COALESCE(length(new_endpoint),0) NOT BETWEEN 1 AND 4096
    OR old_endpoint=new_endpoint
    OR COALESCE(p_expected->>'p256dh','')='' OR COALESCE(p_expected->>'auth','')=''
    OR COALESCE(p_replacement->>'p256dh','')='' OR COALESCE(p_replacement->>'auth','')=''
 THEN RAISE EXCEPTION 'invalid_push_rotation' USING ERRCODE='22023'; END IF;
 -- Same lock/order as enrollment. The verified actor came from WH request
 -- authentication, never from an endpoint-owner lookup or request body.
 PERFORM pg_advisory_xact_lock(hashtextextended('push_subscription_ownership:v1',0));
 SELECT * INTO source FROM public.push_subscriptions WHERE id=(p_expected->>'id')::uuid FOR UPDATE;
 IF NOT FOUND OR NOT source.is_active OR source.user_id IS DISTINCT FROM p_user_id
    OR source.endpoint IS DISTINCT FROM old_endpoint OR source.transport IS DISTINCT FROM 'webpush'
    OR source.rotation_revision::text IS DISTINCT FROM revision
    OR source.p256dh IS DISTINCT FROM (p_expected->>'p256dh')
    OR source.auth IS DISTINCT FROM (p_expected->>'auth')
    OR source.device_id IS DISTINCT FROM (p_expected->>'device_id')
 THEN RAISE EXCEPTION 'push_rotation_conflict' USING ERRCODE='23514'; END IF;
 -- No ownership takeover, resurrection, same-device retirement or preferences
 -- changes belong to rotation. Foreground authenticated enrollment handles
 -- conflicts. Cross-account device collisions are refused, not assigned.
 IF EXISTS(SELECT 1 FROM public.push_subscriptions WHERE endpoint=new_endpoint)
    OR EXISTS(SELECT 1 FROM public.push_subscriptions WHERE device_id=source.device_id AND is_active AND id<>source.id)
 THEN RAISE EXCEPTION 'push_rotation_conflict' USING ERRCODE='23514'; END IF;
 UPDATE public.push_subscriptions SET is_active=false,last_failure_reason='rotated',updated_at=clock_timestamp()
   WHERE id=source.id RETURNING rotation_revision::text INTO retired_revision;
 IF retired_revision IS DISTINCT FROM (source.rotation_revision+1)::text THEN
   RAISE EXCEPTION 'push_rotation_write_unconfirmed' USING ERRCODE='23514';
 END IF;
 INSERT INTO public.push_subscriptions(user_id,endpoint,p256dh,auth,user_agent,device_label,
   device_id,transport,platform,is_active,failure_count,last_failure_reason,updated_at)
 VALUES(source.user_id,new_endpoint,p_replacement->>'p256dh',p_replacement->>'auth',source.user_agent,source.device_label,
   source.device_id,'webpush',source.platform,true,0,NULL,clock_timestamp()) RETURNING * INTO target;
 -- Re-read after triggers: a skipped/changed INSERT must not commit retirement.
 SELECT s.* INTO target FROM public.push_subscriptions s WHERE s.id=target.id;
 IF NOT FOUND OR target.id IS NULL OR target.id=source.id OR NOT target.is_active
    OR target.user_id IS DISTINCT FROM source.user_id OR target.endpoint IS DISTINCT FROM new_endpoint
    OR target.p256dh IS DISTINCT FROM (p_replacement->>'p256dh') OR target.auth IS DISTINCT FROM (p_replacement->>'auth')
    OR target.device_id IS DISTINCT FROM source.device_id OR target.device_label IS DISTINCT FROM source.device_label
    OR target.user_agent IS DISTINCT FROM source.user_agent OR target.platform IS DISTINCT FROM source.platform
    OR target.transport IS DISTINCT FROM 'webpush' OR target.rotation_revision IS DISTINCT FROM 1::bigint
    OR target.failure_count IS DISTINCT FROM 0 OR target.last_failure_reason IS NOT NULL
    OR NOT EXISTS(SELECT 1 FROM public.push_subscriptions s WHERE s.id=source.id AND NOT s.is_active
      AND s.rotation_revision::text=retired_revision AND s.last_failure_reason='rotated')
 THEN RAISE EXCEPTION 'push_rotation_write_unconfirmed' USING ERRCODE='23514'; END IF;
 RETURN jsonb_build_object('schema_version',1,'success',true,'user_id',source.user_id,
   'source_subscription_id',source.id,'source_revision',revision,'retired_revision',retired_revision,
   'subscription_id',target.id,'rotation_revision',target.rotation_revision::text,
   'old_endpoint',old_endpoint,'endpoint',target.endpoint,'device_id',target.device_id,'transport',target.transport);
END $_$;


ALTER FUNCTION public.fn_rotate_push_subscription(p_user_id uuid, p_expected jsonb, p_replacement jsonb) OWNER TO postgres;

--
-- TOC entry 9150 (class 1255 OID 18670718)
-- Name: fn_run_due_managed_game_schedules(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_run_due_managed_game_schedules(p_batch_size integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_schedule public.managed_game_schedules%ROWTYPE;
  v_result jsonb;
  v_processed integer := 0;
BEGIN
  IF auth.uid() IS NOT NULL AND COALESCE(auth.role(),'')<>'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE='42501';
  END IF;
  IF NOT pg_try_advisory_xact_lock(hashtext('run-due-managed-game-schedules')) THEN
    RETURN jsonb_build_object('ok',true,'processed',0,'overlap_skipped',true);
  END IF;
  FOR v_schedule IN
    SELECT * FROM public.managed_game_schedules
     WHERE status='scheduled' AND execute_at<=now()
     ORDER BY execute_at,schedule_id FOR UPDATE SKIP LOCKED
     LIMIT LEAST(100,GREATEST(1,COALESCE(p_batch_size,50)))
  LOOP
    UPDATE public.managed_game_schedules SET status='executing'
     WHERE schedule_id=v_schedule.schedule_id;
    PERFORM set_config(
      'request.jwt.claim.sub',v_schedule.actor_id::text,true);
    v_result := public.fn_execute_managed_game_command(
      v_schedule.command_id,v_schedule.game_kind,v_schedule.game_id,
      v_schedule.command_action,v_schedule.expected_version,'{}'::jsonb
    );
    UPDATE public.managed_game_schedules
       SET status=CASE WHEN COALESCE((v_result->>'ok')::boolean,false)
                       THEN 'succeeded' ELSE 'rejected' END,
           result=v_result,completed_at=now()
     WHERE schedule_id=v_schedule.schedule_id;
    v_processed:=v_processed+1;
  END LOOP;
  PERFORM set_config('request.jwt.claim.sub','',true);
  RETURN jsonb_build_object(
    'ok',true,'processed',v_processed,'overlap_skipped',false);
END;
$$;


ALTER FUNCTION public.fn_run_due_managed_game_schedules(p_batch_size integer) OWNER TO postgres;

--
-- TOC entry 5877 (class 1255 OID 16140511)
-- Name: fn_run_horse_daily_audit(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_run_horse_daily_audit(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    AS $$
declare
  v_stats jsonb;
  v_findings jsonb := '[]'::jsonb;
  r record;
  v_day_hands bigint;
  v_base_hands bigint;
  v_base_days int;
  v_big_pots bigint;
  c_min_baseline_days constant int := 3;
begin
  select jsonb_build_object(
    'flagged_hands', count(*),
    'big_wins', count(*) filter (where is_win),
    'big_losses', count(*) filter (where not is_win),
    'net_bb_sum', round(coalesce(sum(net_bb), 0), 1),
    'by_variant', coalesce((select jsonb_object_agg(game_variant, cnt) from (select game_variant, count(*) cnt from horse_hand_reviews where played_at >= p_day and played_at < p_day + 1 group by game_variant) v), '{}'::jsonb),
    'by_format', coalesce((select jsonb_object_agg(format, cnt) from (select format, count(*) cnt from horse_hand_reviews where played_at >= p_day and played_at < p_day + 1 group by format) v), '{}'::jsonb),
    'decides', (select coalesce(sum(fires),0) from horse_brain_telemetry where day = p_day and feature = 'decide'),
    'net_bb_all_hands', (select round(coalesce(sum(net_bb),0),1) from horse_daily_nets where day = p_day)
  ) into v_stats from horse_hand_reviews where played_at >= p_day and played_at < p_day + 1;

  select count(*) into v_day_hands
    from horse_hand_reviews where played_at >= p_day and played_at < p_day + 1;

  -- ── THE BASELINE COMES FROM THE ROLLUP (2026-09-05) ──
  -- The seven-day baseline and the thirty-day first-seen scan used to read
  -- horse_hand_reviews with a lateral unnest over leak_tags - every row's
  -- heap page, actions jsonb and all, for up to a month of rows. Warm that is
  -- a second; cold it was most of a 41.8s run measured on 2026-09-05 after
  -- the hand_history scan was already gone, against an 8s ceiling. The
  -- engine's 06:00 window is exactly when those pages are cold.
  -- horse_review_rollup is the same counts per horse/day/variant, written by
  -- fn_hhr_rollup_add on every review insert, a few thousand small rows for a
  -- week. Verified on the live data: first-seen days identical for all 22
  -- tags; seven-day hand counts and tag counts within 0.1% (the rollup add is
  -- fire-and-forget and loses a handful of rows), which moves a per-1k rate
  -- in the third decimal and no verdict. The DAY side stays on
  -- horse_hand_reviews, exact and hot.
  select coalesce(sum(big_wins + big_losses), 0), count(distinct day)
    into v_base_hands, v_base_days
    from horse_review_rollup where day >= p_day - 7 and day < p_day;

  if v_base_days >= c_min_baseline_days and v_day_hands > 0 and v_base_hands > 0 then
    for r in
      with day_tags as (
        select tag, count(*) cnt
          from horse_hand_reviews, lateral unnest(leak_tags) tag
         where played_at >= p_day and played_at < p_day + 1
         group by tag
      ),
      tag_first_seen as (
        select k as tag, min(day) as first_day
          from horse_review_rollup, lateral jsonb_object_keys(leak_counts) k
         where day >= p_day - 30 and day <= p_day
         group by k
      ),
      base_day_hands as (
        select day as d, sum(big_wins + big_losses)::bigint as hands
          from horse_review_rollup
         where day >= p_day - 7 and day < p_day
         group by 1
      ),
      base_tag_counts as (
        select k as tag, sum((leak_counts->>k)::bigint) as cnt
          from horse_review_rollup, lateral jsonb_object_keys(leak_counts) k
         where day >= p_day - 7 and day < p_day
         group by k
      ),
      base_per_tag as (
        select f.tag,
               coalesce(sum(b.hands), 0)::bigint as hands,
               count(b.d)::int                   as days
          from tag_first_seen f
          left join base_day_hands b on b.d >= f.first_day
         group by f.tag
      )
      select d.tag,
             d.cnt,
             (d.cnt::numeric * 1000) / v_day_hands as day_rate,
             case when p.hands > 0
                  then (coalesce(c.cnt, 0)::numeric * 1000) / p.hands
             end                                  as base_rate,
             coalesce(p.days, 0)                   as tag_base_days,
             coalesce(p.hands, 0)                  as tag_base_hands
        from day_tags d
        left join base_per_tag  p using (tag)
        left join base_tag_counts c using (tag)
       where d.cnt >= 20
    loop
      if r.tag_base_days < c_min_baseline_days then
        v_findings := v_findings || jsonb_build_object(
          'severity','info','category','logic','code','leak_tag_detector_new',
          'title','Leak tag ' || r.tag || ' is too new to baseline',
          'evidence', jsonb_build_object(
            'tag', r.tag,
            'count', r.cnt,
            'rate_per_1k', round(r.day_rate, 2),
            'tag_baseline_days', r.tag_base_days,
            'required_days', c_min_baseline_days,
            'day_hands', v_day_hands),
          'recommendation','This detector has not been running long enough for a spike to mean anything, so no comparison was made. Its first few days establish the baseline; judge it from the day it has ' || c_min_baseline_days || ' full prior days.');
      elsif r.base_rate is not null
            and (r.base_rate = 0 or r.day_rate > r.base_rate * 1.5) then
        declare
          /*
           * A RISE IS NOT A LEAK UNTIL THE MIRRORED EV SAYS SO (2026-09-14).
           * The count above is the LOSS side only. fn_horse_tag_ev pairs it
           * with its _won mirror over seven days, which is the ranking
           * fn_audit_river_aggression_ev already treats as the honest one. A
           * situation that is winning money did not regress because it
           * happened more often. Null means under 100 hands in the window, or
           * the fold family, which has no winning mirror by construction -
           * then the original warn stands, because nothing contradicted it.
           */
          v_situation text := case
            when r.tag like '%\_won'  then left(r.tag, length(r.tag) - 4)
            when r.tag like '%\_lost' then left(r.tag, length(r.tag) - 5)
            else r.tag
          end;
          v_ev_bb    numeric;
          v_ev_hands bigint;
          v_ev_win   numeric;
          v_ev_z     numeric;
          v_ev_sd    numeric;
        begin
          select e.bb_per_hand, e.hands, e.win_rate
            into v_ev_bb, v_ev_hands, v_ev_win
            from fn_horse_tag_ev(p_day - 6) e
           where e.situation = v_situation and e.mirrored
           limit 1;
          select s.z, s.sd_est into v_ev_z, v_ev_sd
            from fn_horse_tag_ev_significance(p_day - 6) s
           where s.situation = v_situation
           limit 1;

          if v_ev_bb is not null and v_ev_bb >= 0 then
            v_findings := v_findings || jsonb_build_object(
              'severity','info','category','gto','code','leak_tag_spike_positive_ev',
              'title','Leak tag ' || r.tag || ' rose, and its mirrored situation is WINNING ' || v_ev_bb || 'bb per hand',
              'evidence', jsonb_build_object(
                'tag', r.tag,
                'situation', v_situation,
                'count', r.cnt,
                'rate_per_1k', round(r.day_rate, 2),
                'baseline_rate_per_1k', round(r.base_rate, 2),
                'baseline_days', r.tag_base_days,
                'day_hands', v_day_hands,
                'baseline_hands', r.tag_base_hands,
                'mirrored_bb_per_hand', v_ev_bb,
                'mirrored_hands', v_ev_hands,
                'mirrored_win_rate', v_ev_win),
              'recommendation','Counted on the loss side alone this rose, which is what the spike threshold saw. Counted on BOTH sides over seven days it MAKES money, so the rise is the fleet reaching the spot more often, not the brain regressing into it. Do not tune away from it on this finding and do not open a league matchup for it. It becomes a real warning on its own the day fn_horse_tag_ev turns the situation negative.');
          elsif v_ev_bb is not null and v_ev_z is not null and v_ev_z > -3 then
            -- NEGATIVE IS NOT THE SAME AS LOSING (2026-09-27). See migration header.
            v_findings := v_findings || jsonb_build_object(
              'severity','info','category','gto','code','leak_tag_spike_unresolved',
              'title','Leak tag ' || r.tag || ' rose, but its mirrored EV (' || v_ev_bb || 'bb/hand, z ' || v_ev_z || ') is indistinguishable from zero',
              'evidence', jsonb_build_object(
                'tag', r.tag, 'situation', v_situation, 'count', r.cnt,
                'rate_per_1k', round(r.day_rate, 2), 'baseline_rate_per_1k', round(r.base_rate, 2),
                'mirrored_bb_per_hand', v_ev_bb, 'mirrored_hands', v_ev_hands,
                'mirrored_sd_est', v_ev_sd, 'mirrored_z', v_ev_z, 'z_gate', -3),
              'recommendation','The spot is arising more often, but seven days of both outcomes cannot tell it from breakeven. Do not tune on it and do not open a matchup for it. It becomes a warning the day its z falls to -3 or below.');
          else
            v_findings := v_findings || jsonb_build_object(
              'severity', case when r.base_rate = 0 or r.day_rate > r.base_rate * 2.5 then 'critical' else 'warn' end,
              'category','logic','code','leak_tag_spike',
              'title','Leak tag ' || r.tag || ' spiked',
              'evidence', jsonb_build_object(
                'tag', r.tag,
                'count', r.cnt,
                'rate_per_1k', round(r.day_rate, 2),
                'baseline_rate_per_1k', round(r.base_rate, 2),
                'baseline_days', r.tag_base_days,
                'day_hands', v_day_hands,
                'baseline_hands', r.tag_base_hands,
                'mirrored_bb_per_hand', v_ev_bb,
                'mirrored_hands', v_ev_hands),
              'recommendation','Rates are per 1,000 captured hands on both sides and the baseline counts only days this detector was live, so this is neither a volume artifact nor a new-detector artifact. mirrored_bb_per_hand is the seven-day EV across BOTH outcomes: negative confirms a real leak, and null means the situation has under 100 hands in the window or has no winning mirror (the fold family), so the rise is unexplained rather than confirmed. A spike after a deploy means the brain regressed on this pattern. Diff the day''s engine deploys against the tag definition and sample flagged hands carrying it.');
          end if;
        end;
      end if;
    end loop;
  else
    v_findings := v_findings || jsonb_build_object(
      'severity','info','category','logic','code','leak_tag_spike_baseline_thin',
      'title','Leak spike detection stood down - ' || v_base_days || ' day(s) of baseline',
      'evidence', jsonb_build_object('baseline_days', v_base_days, 'required_days', c_min_baseline_days,
                                     'day_hands', v_day_hands, 'baseline_hands', v_base_hands),
      'recommendation','Needs ' || c_min_baseline_days || ' distinct prior days of capture before a spike means anything. This is the detector declining to guess, not a finding.');
  end if;

  for r in select horse_user_id, round(sum(net_bb),1) net, count(*) n from horse_hand_reviews
    where played_at >= p_day and played_at < p_day + 1 group by horse_user_id having sum(net_bb) < least(-400, (select percentile_cont(0.1) within group (order by fleet_p10.s) from (select sum(net_bb) as s from horse_hand_reviews where played_at >= p_day and played_at < p_day + 1 group by horse_user_id) fleet_p10)) order by sum(net_bb) asc limit 10
  loop
    v_findings := v_findings || jsonb_build_object('severity', case when r.net < -800 then 'critical' else 'warn' end,
      'category','gto','code','horse_big_pot_bleed','title','Horse lost ' || abs(r.net) || 'bb across ' || r.n || ' flagged pots',
      'evidence', jsonb_build_object('horse_user_id',r.horse_user_id,'alias',(select coalesce(alias,display_name,username) from profiles where id=r.horse_user_id),'net_bb',r.net,'hands',r.n,
        'tags',(select coalesce(jsonb_object_agg(tag,cnt),'{}'::jsonb) from (select tag,count(*) cnt from horse_hand_reviews, lateral unnest(leak_tags) tag where horse_user_id=r.horse_user_id and played_at>=p_day and played_at<p_day+1 group by tag) t)),
      'recommendation','Review this horse''s flagged hands. Repeated identical tags mean a style/dial problem for the self-tuner; scattered tags with big losses can be variance - check the hand count first.');
  end loop;

  for r in select matchup, bb100, stderr, illegal_actions from horse_league_results
    where run_date = (select max(run_date) from horse_league_results where run_date <= p_day + 1)
  loop
    if r.bb100 < 0 and abs(r.bb100) > 2 * r.stderr then
      v_findings := v_findings || jsonb_build_object('severity','critical','category','gto','code','league_layer_negative',
        'title','League matchup ' || r.matchup || ' resolves NEGATIVE','evidence', jsonb_build_object('matchup',r.matchup,'bb100',r.bb100,'stderr',r.stderr),
        'recommendation','A strategy layer is measurably losing money in self-play. Ablate it properly before tuning anything else.');
    end if;
    if r.illegal_actions > 0 then
      v_findings := v_findings || jsonb_build_object('severity','critical','category','logic','code','league_illegal_actions',
        'title','League matchup ' || r.matchup || ' produced illegal actions','evidence', jsonb_build_object('matchup',r.matchup,'illegal_actions',r.illegal_actions),
        'recommendation','The brain emitted a sizing the engine rejects. This reaches live tables as silent check/fold degradation - find the exact branch.');
    end if;
  end loop;

  -- ── capture_coverage_gap (rewritten 2026-09-05) ──────────────────────────
  -- This step used to scan the WHOLE DAY of hand_history (681,878 rows on
  -- 2026-09-04: 700,896 buffers through idx_hand_history_created with a heap
  -- filter on pot_size, 89.9 seconds measured) to answer a question whose
  -- normal answer is "nothing to report". It was the entire reason the
  -- engine's nightly daily_audit could not finish: service_role runs at an
  -- 8s statement_timeout and the engine client aborts at 15s, and the SET
  -- statement_timeout '60s' on this function cannot re-arm a timer that was
  -- armed at statement start. Every other step here runs in under a second.
  --
  -- The question is "did a variant deal big pots today and write NO review
  -- rows". Both halves are cheap without hand_history: the variants dealt
  -- come from horse_daily_nets (written per horse-hand at settlement, one
  -- small row per horse/variant/day), the variants reviewed come from
  -- idx_hhr_played. Only for a variant that has nets rows and no reviews -
  -- the abnormal case the finding exists for - is hand_history probed, and
  -- then with LIMIT 50: fifty big pots are enough to raise the finding and
  -- the scan stops the moment it has them.
  for r in
    select n.game_variant
      from (select distinct game_variant from horse_daily_nets where day = p_day and hands > 0) n
     where not exists (select 1 from horse_hand_reviews rv
                        where rv.game_variant = n.game_variant
                          and rv.played_at >= p_day and rv.played_at < p_day + 1)
  loop
    select count(*) into v_big_pots from (
      select 1 from hand_history h
       where h.created_at >= p_day and h.created_at < p_day + 1
         and h.game_variant = r.game_variant
         and h.pot_size >= 40 * h.big_blind
       limit 50) probe;
    if v_big_pots >= 50 then
      v_findings := v_findings || jsonb_build_object('severity','critical','category','schema','code','capture_coverage_gap',
        'title','Variant ' || r.game_variant || ' dealt at least ' || v_big_pots || ' big pots but wrote zero review rows',
        'evidence', jsonb_build_object('game_variant',r.game_variant,'big_pot_hands',v_big_pots,'probe_limit',50),
        'recommendation','recordHorseHandReviews is not firing for this variant''s settlement path. Read the engine logs for HorseHandReview reportError entries.');
    end if;
  end loop;

  select count(*) into r from horse_hand_reviews where played_at >= p_day and played_at < p_day + 1 and (hole_cards is null or board is null);
  if (r.count) >= 25 then
    v_findings := v_findings || jsonb_build_object('severity','warn','category','schema','code','evidence_payload_missing',
      'title',(r.count) || ' review rows missing hole_cards or board','evidence', jsonb_build_object('rows',r.count),
      'recommendation','parseCards rejected the payload shape, or preflop-only pots legitimately have no board. Sample the rows.');
  end if;

  for r in select id, horse_user_id, net_bb, game_variant from horse_hand_reviews
    where played_at >= p_day and played_at < p_day + 1
      and abs(net_bb) > (case when tournament_id is not null then 1500 else 500 end)
      order by abs(net_bb) desc limit 5
  loop
    v_findings := v_findings || jsonb_build_object('severity','warn','category','schema','code','net_outlier',
      'title','Review row with |net| of ' || r.net_bb || 'bb','evidence', jsonb_build_object('review_id',r.id,'horse_user_id',r.horse_user_id,'net_bb',r.net_bb,'variant',r.game_variant),
      'recommendation','Legitimate only for very deep stacks. If the stake caps make this impossible, the contribution/winner inputs disagree.');
  end loop;

  select count(*) into r from horse_hand_reviews where played_at >= p_day and played_at < p_day + 1 and not is_win and leak_tags = '{}';
  if (r.count) >= 200 then
    v_findings := v_findings || jsonb_build_object('severity','info','category','logic','code','untagged_losses',
      'title',(r.count) || ' big losses carry no leak tag','evidence', jsonb_build_object('rows',r.count),
      'recommendation','Not every big loss is a mistake - but if manual review keeps finding the same untagged flaw, add a detector.');
  end if;

  v_findings := v_findings || fn_audit_layer_silence_and_coverage(p_day);
  v_findings := v_findings || fn_audit_fleet_health(p_day);
  -- 2026-09-01: a claimed-but-empty nightly job, a stale league card,
  -- and a matchup whose two arms are identical. See
  -- 20260901_audit_a_lost_nightly_job_is_loud.sql.
  v_findings := v_findings || fn_audit_nightly_job_health(p_day);
  -- 2026-09-27: the audit reports its own missing days. daily_audit claimed
  -- 2026-09-26 and wrote nothing, and no instrument said so.
  for r in
    select j.run_date, j.claimed_at, j.claimed_by
      from horse_job_runs j
     where j.job = 'daily_audit'
       and j.run_date between p_day - 2 and p_day - 1
       and not exists (select 1 from horse_daily_audit x where x.day = j.run_date)
  loop
    v_findings := v_findings || jsonb_build_object(
      'severity','critical','category','schema','code','daily_audit_lost',
      'title','daily_audit claimed ' || r.run_date || ' and never wrote its row',
      'evidence', jsonb_build_object('run_date', r.run_date, 'claimed_at', r.claimed_at, 'claimed_by', r.claimed_by),
      'recommendation','The engine calls this function as service_role, whose statement_timeout is 8s. Run select fn_run_horse_daily_audit(''' || r.run_date || '''::date) from a session with a longer timeout to recover the day, then find the step that outgrew 8s.');
  end loop;
  -- 2026-09-01: river aggression judged on EV across BOTH outcomes.
  v_findings := v_findings || fn_audit_river_aggression_ev(p_day);
  -- 2026-09-01: layers that stopped firing or collapsed, derived from
  -- what each layer has actually done - no hand-maintained watchlist.
  v_findings := v_findings || fn_audit_layer_drift(p_day);
  -- 2026-09-01: a conservation breach stays reported until a person
  -- explains it. The deploy gate forgets after four hours; this does not.
  v_findings := v_findings || fn_audit_supply_breaches(p_day);
  -- Phase 1 of the real-time build plan (2026-09-04): every ledger receipt
  -- judged against its expected share, every nightly source for freshness.
  v_findings := v_findings || fn_audit_data_receipts(p_day);
  -- 2026-09-05 hardening: the tag registry, the tuner, the seat clock.
  v_findings := v_findings || fn_audit_tag_consumers(p_day);
  v_findings := v_findings || fn_audit_tuner_health(p_day);
  v_findings := v_findings || fn_audit_seat_clock(p_day);
  -- 2026-09-06: a receipt can be zero because the behaviour is broken OR
  -- because the world never presents the spot. Those want opposite fixes.
  v_findings := v_findings || fn_audit_behaviour_has_a_stage(p_day);
  -- 2026-09-05 V49: the leaks a 20bb loss cannot see.
  v_findings := v_findings || fn_audit_frequency_leaks(p_day);
  -- 2026-09-05 V47: the absolute score the league cannot produce.
  v_findings := v_findings || fn_audit_solver_agreement(p_day);
  -- 2026-09-08 Phase 4: certified corpus and independent pipeline liveness.
  v_findings := v_findings || fn_audit_gto_v31_certified(p_day);
  v_findings := v_findings || fn_audit_solver_pipeline_liveness(p_day);
  -- 2026-09-05: the tournament lane scoreboard, compiled for the day then judged.
  perform fn_horse_tournament_daily_compile(p_day);
  v_findings := v_findings || fn_audit_tournament_results(p_day);

  insert into horse_daily_audit as a (day, generated_at, stats, findings)
  values (p_day, now(), coalesce(v_stats,'{}'::jsonb), v_findings)
  on conflict (day) do update set generated_at = now(), stats = excluded.stats, findings = excluded.findings;

  return jsonb_build_object('day', p_day, 'findings', jsonb_array_length(v_findings));
end
$$;


ALTER FUNCTION public.fn_run_horse_daily_audit(p_day date) OWNER TO postgres;

--
-- TOC entry 6220 (class 1255 OID 177073558)
-- Name: fn_run_horse_reference_agreement(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_run_horse_reference_agreement(p_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    SET statement_timeout TO '60s'
    AS $_$
DECLARE
  v_by_variant jsonb;
  v_divergence jsonb;
  v_outcomes jsonb;
  v_second jsonb;
  v_totals jsonb;
  v_findings jsonb;
  v_complete boolean := now() >= (p_day + 1)::timestamptz;
BEGIN
  IF p_day IS NULL OR p_day > current_date THEN
    RAISE EXCEPTION 'fn_run_horse_reference_agreement: day % is not a past or current UTC day', p_day;
  END IF;

  WITH a AS (
    SELECT m[1] AS variant, m[2] AS format, m[3] AS agreement, t.fires
    FROM public.horse_brain_telemetry t,
         LATERAL regexp_match(t.feature,
           '^phase15_reference_agreement_(.+)_(cash|tournament)_(exact|action|differ|unrecorded)$') m
    WHERE t.day = p_day AND t.feature LIKE 'phase15_reference_agreement_%' AND m IS NOT NULL
  ), g AS (
    SELECT variant, format,
           sum(fires) AS decisions,
           coalesce(sum(fires) FILTER (WHERE agreement = 'exact'), 0) AS exact,
           coalesce(sum(fires) FILTER (WHERE agreement = 'action'), 0) AS action_only,
           coalesce(sum(fires) FILTER (WHERE agreement = 'differ'), 0) AS differ,
           coalesce(sum(fires) FILTER (WHERE agreement = 'unrecorded'), 0) AS unrecorded
    FROM a GROUP BY variant, format
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'variant', variant, 'format', format, 'decisions', decisions,
           'exact', exact, 'action', action_only, 'differ', differ, 'unrecorded', unrecorded,
           'agreement', CASE WHEN decisions - unrecorded > 0
             THEN round(exact::numeric / (decisions - unrecorded), 6) END,
           'action_agreement', CASE WHEN decisions - unrecorded > 0
             THEN round((exact + action_only)::numeric / (decisions - unrecorded), 6) END)
         ORDER BY variant, format), '[]'::jsonb),
         jsonb_build_object(
           'decisions', coalesce(sum(decisions), 0),
           'exact', coalesce(sum(exact), 0),
           'action', coalesce(sum(action_only), 0),
           'differ', coalesce(sum(differ), 0),
           'unrecorded', coalesce(sum(unrecorded), 0),
           'agreement', CASE WHEN coalesce(sum(decisions - unrecorded), 0) > 0
             THEN round(sum(exact)::numeric / sum(decisions - unrecorded), 6) END)
    INTO v_by_variant, v_totals
  FROM g;

  SELECT coalesce(jsonb_agg(jsonb_build_object('variant', m[1], 'node', m[2], 'decisions', t.fires)
           ORDER BY m[1], t.fires DESC, m[2]), '[]'::jsonb)
    INTO v_divergence
  FROM public.horse_brain_telemetry t,
       LATERAL regexp_match(t.feature,
         '^phase15_reference_divergence_(.+)_(reference_legality|variant_policy|tournament_utility|tournament_continuation|variant_utility_guard|joint_policy|timing)$') m
  WHERE t.day = p_day AND t.feature LIKE 'phase15_reference_divergence_%' AND m IS NOT NULL;

  WITH o AS (
    SELECT m[1] AS variant, m[2] AS outcome, t.fires
    FROM public.horse_brain_telemetry t,
         LATERAL regexp_match(t.feature,
           '^phase15_policy_(.+)_(reference|disabled|computed|outside_domain|unavailable)$') m
    WHERE t.day = p_day AND t.feature LIKE 'phase15_policy_%' AND m IS NOT NULL
  ), v AS (
    SELECT variant, sum(fires) AS decisions,
           coalesce(sum(fires) FILTER (WHERE outcome = 'computed'), 0) AS computed,
           coalesce(sum(fires) FILTER (WHERE outcome = 'outside_domain'), 0) AS outside_domain,
           coalesce(sum(fires) FILTER (WHERE outcome = 'unavailable'), 0) AS unavailable,
           coalesce(sum(fires) FILTER (WHERE outcome = 'reference'), 0) AS reference,
           coalesce(sum(fires) FILTER (WHERE outcome = 'disabled'), 0) AS disabled
    FROM o GROUP BY variant
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'variant', variant, 'decisions', decisions, 'computed', computed,
           'outside_domain', outside_domain, 'unavailable', unavailable,
           'reference', reference, 'disabled', disabled,
           'outside_domain_share', round(outside_domain::numeric / decisions, 6),
           'unavailable_share', round(unavailable::numeric / decisions, 6))
         ORDER BY variant), '[]'::jsonb)
    INTO v_outcomes
  FROM v WHERE decisions > 0;

  SELECT coalesce(jsonb_object_agg(m[1], t.fires ORDER BY m[1]), '{}'::jsonb)
    INTO v_second
  FROM public.horse_brain_telemetry t,
       LATERAL regexp_match(t.feature, '^phase15_deep_execution_retired_([a-z_]+)$') m
  WHERE t.day = p_day AND t.feature LIKE 'phase15_deep_execution_retired_%' AND m IS NOT NULL;

  -- Findings against the trailing seven complete reports (only rows that were
  -- themselves complete). Each rule names its threshold:
  --   agreement_drop     a (variant, format) with >= 1,000 decisions whose exact
  --                      agreement fell more than 2 points below its trailing mean;
  --   unrecorded_graph   any decision without a sealed policy graph (baseline 0);
  --   ood_rise           a variant whose out-of-domain share rose more than 5
  --                      points above its trailing mean (>= 1,000 decisions);
  --   unavailable_rise   a variant whose unavailable share exceeds 1% and doubled
  --                      its trailing mean (>= 1,000 decisions);
  --   no_report_input    no reference-agreement counters at all for the day.
  WITH prev AS (
    SELECT r.day, r.by_variant, r.policy_outcomes
    FROM public.horse_reference_agreement_daily r
    WHERE r.day < p_day AND r.day >= p_day - 7 AND r.complete
  ), pv AS (
    SELECT e->>'variant' AS variant, e->>'format' AS format, avg((e->>'agreement')::numeric) AS agreement
    FROM prev, jsonb_array_elements(prev.by_variant) e
    WHERE (e->>'agreement') IS NOT NULL
    GROUP BY 1, 2
  ), po AS (
    SELECT e->>'variant' AS variant,
           avg((e->>'outside_domain_share')::numeric) AS ood,
           avg((e->>'unavailable_share')::numeric) AS unav
    FROM prev, jsonb_array_elements(prev.policy_outcomes) e
    GROUP BY 1
  ), f AS (
    SELECT jsonb_build_object('rule', 'agreement_drop', 'variant', c->>'variant', 'format', c->>'format',
             'agreement', (c->>'agreement')::numeric, 'trailing', round(pv.agreement, 6),
             'decisions', (c->>'decisions')::bigint) AS finding
    FROM jsonb_array_elements(v_by_variant) c
    JOIN pv ON pv.variant = c->>'variant' AND pv.format = c->>'format'
    WHERE (c->>'decisions')::bigint >= 1000 AND (c->>'agreement') IS NOT NULL
      AND (c->>'agreement')::numeric < pv.agreement - 0.02
    UNION ALL
    SELECT jsonb_build_object('rule', 'unrecorded_graph', 'variant', c->>'variant', 'format', c->>'format',
             'decisions', (c->>'unrecorded')::bigint)
    FROM jsonb_array_elements(v_by_variant) c
    WHERE (c->>'unrecorded')::bigint > 0
    UNION ALL
    SELECT jsonb_build_object('rule', 'ood_rise', 'variant', c->>'variant',
             'share', (c->>'outside_domain_share')::numeric, 'trailing', round(po.ood, 6),
             'decisions', (c->>'decisions')::bigint)
    FROM jsonb_array_elements(v_outcomes) c
    JOIN po ON po.variant = c->>'variant'
    WHERE (c->>'decisions')::bigint >= 1000
      AND (c->>'outside_domain_share')::numeric > po.ood + 0.05
    UNION ALL
    SELECT jsonb_build_object('rule', 'unavailable_rise', 'variant', c->>'variant',
             'share', (c->>'unavailable_share')::numeric, 'trailing', round(po.unav, 6),
             'decisions', (c->>'decisions')::bigint)
    FROM jsonb_array_elements(v_outcomes) c
    JOIN po ON po.variant = c->>'variant'
    WHERE (c->>'decisions')::bigint >= 1000
      AND (c->>'unavailable_share')::numeric > 0.01
      AND (c->>'unavailable_share')::numeric > 2 * po.unav
    UNION ALL
    SELECT jsonb_build_object('rule', 'no_report_input')
    WHERE (v_totals->>'decisions')::bigint = 0
  )
  SELECT coalesce(jsonb_agg(finding), '[]'::jsonb) INTO v_findings FROM f;

  INSERT INTO public.horse_reference_agreement_daily AS r
    (day, generated_at, complete, totals, by_variant, divergence, policy_outcomes, second_looks, findings)
  VALUES (p_day, now(), v_complete, v_totals, v_by_variant, v_divergence, v_outcomes, v_second, v_findings)
  ON CONFLICT (day) DO UPDATE SET
    generated_at = EXCLUDED.generated_at,
    complete = EXCLUDED.complete,
    totals = EXCLUDED.totals,
    by_variant = EXCLUDED.by_variant,
    divergence = EXCLUDED.divergence,
    policy_outcomes = EXCLUDED.policy_outcomes,
    second_looks = EXCLUDED.second_looks,
    findings = EXCLUDED.findings;

  RETURN jsonb_build_object('day', p_day, 'complete', v_complete,
    'decisions', v_totals->'decisions', 'findings', jsonb_array_length(v_findings));
END;
$_$;


