-- TOC entry 7052 (class 1255 OID 55242889)
-- Name: fn_schedule_time_zone_is_known(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_schedule_time_zone_is_known(p_zone text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  SELECT p_zone IS NULL
      OR ((p_zone IN ('UTC', 'GMT')
           OR p_zone ~ '^[A-Z][A-Za-z]+/[A-Za-z0-9_+-]+(/[A-Za-z0-9_+-]+)?$')
          AND EXISTS (SELECT 1 FROM pg_catalog.pg_timezone_names n WHERE n.name = p_zone))
$_$;


