-- TOC entry 48838 (class 0 OID 0)
-- Dependencies: 4940
-- Name: FUNCTION fn_seed_table_studio_preferences(p_expected_user_id uuid, p_favorites text[], p_loadouts jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

