--
-- TOC entry 5719 (class 1255 OID 198172131)
-- Name: fn_send_club_welcome_text(uuid, uuid, uuid, text, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_send_club_welcome_text(p_club uuid, p_recipient uuid, p_sender uuid, p_content text, p_revision bigint, p_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_conversation uuid; v_message uuid:=gen_random_uuid();
BEGIN
 IF p_sender=p_recipient OR public.fn_club_messenger_staff_role(p_club,p_sender) IS NULL OR NOT EXISTS(
  SELECT 1 FROM public.club_members WHERE club_id=p_club AND user_id=p_recipient AND is_active=true AND status IN ('active','approved') AND membership_lifecycle_status='active'
 ) THEN RETURN jsonb_build_object('status','cancelled'); END IF;
 BEGIN
  PERFORM public.fn_ca_assert_player_action(p_sender,'social','club_messenger_welcome');
  PERFORM public.fn_ca_assert_player_action(p_recipient,'social','club_messenger_welcome');
 EXCEPTION WHEN insufficient_privilege THEN RETURN jsonb_build_object('status','blocked'); END;
 IF EXISTS(SELECT 1 FROM public.messenger_blocked WHERE (blocker_id=p_sender AND blocked_id=p_recipient) OR (blocker_id=p_recipient AND blocked_id=p_sender)) THEN
  RETURN jsonb_build_object('status','blocked'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('club-welcome-pair:'||least(p_sender::text,p_recipient::text)||':'||greatest(p_sender::text,p_recipient::text),0));
 SELECT c.id INTO v_conversation FROM public.social_conversations c WHERE NOT c.is_group AND NOT c.is_request AND c.context_entity_id IS NULL
 AND EXISTS(SELECT 1 FROM public.social_conversation_participants p WHERE p.conversation_id=c.id AND p.user_id=p_sender AND p.context_entity_id IS NULL)
 AND EXISTS(SELECT 1 FROM public.social_conversation_participants p WHERE p.conversation_id=c.id AND p.user_id=p_recipient AND p.context_entity_id IS NULL)
 AND (SELECT count(*) FROM public.social_conversation_participants p WHERE p.conversation_id=c.id)=2 ORDER BY c.created_at,c.id LIMIT 1;
 IF v_conversation IS NULL THEN
  INSERT INTO public.social_conversations(is_group,is_request) VALUES(false,false) RETURNING id INTO v_conversation;
  INSERT INTO public.social_conversation_participants(conversation_id,user_id) VALUES(v_conversation,p_sender),(v_conversation,p_recipient);
 END IF;
 INSERT INTO public.social_messages(id,conversation_id,sender_id,content,message_type,media_metadata)
 VALUES(v_message,v_conversation,p_sender,p_content,'text',jsonb_build_object('club_welcome',true,'club_id',p_club,'template_revision',p_revision,'welcome_kind',p_kind));
 RETURN jsonb_build_object('status','sent','conversation_id',v_conversation,'message_id',v_message);
END $$;


ALTER FUNCTION public.fn_send_club_welcome_text(p_club uuid, p_recipient uuid, p_sender uuid, p_content text, p_revision bigint, p_kind text) OWNER TO postgres;

--
-- TOC entry 7616 (class 1255 OID 4632036)
-- Name: fn_send_home_game_reminders(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_send_home_game_reminders() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_6h_sent int := 0;
    v_1h_sent int := 0;
    v_rsvp    RECORD;
    v_slug    text;
BEGIN
    -- 6-hour reminders: games starting in ~5h45min to ~6h15min from now
    FOR v_rsvp IN
        SELECT 
            r.id AS rsvp_id, r.user_id, r.game_id,
            g.group_id, g.title AS game_title, g.scheduled_date, g.start_time, g.address,
            grp.name AS group_name
          FROM commander_home_rsvps r
          JOIN commander_home_games g ON g.id = r.game_id
          JOIN commander_home_groups grp ON grp.id = g.group_id
         WHERE r.response = 'yes'
           AND r.reminder_6h_sent_at IS NULL
           AND g.status IN ('scheduled','confirmed')
           -- scheduled_datetime between 5h45m and 6h15m from now
           AND (g.scheduled_date + COALESCE(g.start_time, TIME '19:00')) 
               BETWEEN NOW() + INTERVAL '5 hours 45 minutes'
                   AND NOW() + INTERVAL '6 hours 15 minutes'
    LOOP
        SELECT sp.slug INTO v_slug FROM social_pages sp
         WHERE sp.linked_entity_type = 'home_group' AND sp.linked_entity_id = v_rsvp.group_id::text
         LIMIT 1;

        PERFORM public.fn_emit_home_notification(
            v_rsvp.user_id,
            'home_game_reminder_6h',
            COALESCE(v_rsvp.game_title, v_rsvp.group_name) || ' - tonight in 6 hours',
            'See you at ' || COALESCE(v_rsvp.start_time::text, '') || 
                CASE WHEN v_rsvp.address IS NOT NULL 
                     THEN ' - ' || v_rsvp.address ELSE '' END,
            '/hub/home-games/' || COALESCE(v_slug, v_rsvp.group_id::text),
            jsonb_build_object('game_id', v_rsvp.game_id, 'window', '6h'),
            'home_game_reminders'
        );

        UPDATE commander_home_rsvps 
           SET reminder_6h_sent_at = NOW()
         WHERE id = v_rsvp.rsvp_id;

        v_6h_sent := v_6h_sent + 1;
    END LOOP;

    -- 1-hour reminders: games starting in ~45min to ~75min from now
    FOR v_rsvp IN
        SELECT 
            r.id AS rsvp_id, r.user_id, r.game_id,
            g.group_id, g.title AS game_title, g.scheduled_date, g.start_time, g.address,
            grp.name AS group_name
          FROM commander_home_rsvps r
          JOIN commander_home_games g ON g.id = r.game_id
          JOIN commander_home_groups grp ON grp.id = g.group_id
         WHERE r.response = 'yes'
           AND r.reminder_1h_sent_at IS NULL
           AND g.status IN ('scheduled','confirmed')
           AND (g.scheduled_date + COALESCE(g.start_time, TIME '19:00')) 
               BETWEEN NOW() + INTERVAL '45 minutes'
                   AND NOW() + INTERVAL '75 minutes'
    LOOP
        SELECT sp.slug INTO v_slug FROM social_pages sp
         WHERE sp.linked_entity_type = 'home_group' AND sp.linked_entity_id = v_rsvp.group_id::text
         LIMIT 1;

        PERFORM public.fn_emit_home_notification(
            v_rsvp.user_id,
            'home_game_reminder_1h',
            'Starting in 1 hour - ' || COALESCE(v_rsvp.game_title, v_rsvp.group_name),
            'Head out soon. ' || COALESCE(v_rsvp.start_time::text, 'tonight'),
            '/hub/home-games/' || COALESCE(v_slug, v_rsvp.group_id::text),
            jsonb_build_object('game_id', v_rsvp.game_id, 'window', '1h'),
            'home_game_reminders'
        );

        UPDATE commander_home_rsvps 
           SET reminder_1h_sent_at = NOW()
         WHERE id = v_rsvp.rsvp_id;

        v_1h_sent := v_1h_sent + 1;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'sent_6h', v_6h_sent,
        'sent_1h', v_1h_sent,
        'run_at', NOW()
    );
END;
$$;


ALTER FUNCTION public.fn_send_home_game_reminders() OWNER TO postgres;

--
-- TOC entry 7499 (class 1255 OID 4767520)
-- Name: fn_send_message(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_send_message(p_conversation_id uuid, p_sender_id uuid, p_content text, p_message_type text DEFAULT 'text'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_message_id uuid;
    v_is_participant boolean;
BEGIN
    -- Verify sender is a participant (belt-and-suspenders, send-message API already checks)
    SELECT EXISTS (
        SELECT 1 FROM public.social_conversation_participants
        WHERE conversation_id = p_conversation_id AND user_id = p_sender_id
    ) INTO v_is_participant;

    IF NOT v_is_participant THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_a_participant');
    END IF;

    -- Insert message with metadata
    INSERT INTO public.social_messages (
        conversation_id,
        sender_id,
        content,
        message_type,
        media_metadata
    ) VALUES (
        p_conversation_id,
        p_sender_id,
        p_content,
        COALESCE(NULLIF(p_message_type, ''), 'text'),
        CASE WHEN p_metadata = '{}'::jsonb OR p_metadata IS NULL THEN NULL ELSE p_metadata END
    )
    RETURNING id INTO v_message_id;

    -- Update conversation last message preview
    UPDATE public.social_conversations
    SET
        last_message_at      = now(),
        last_message_preview = CASE
            WHEN p_message_type = 'shared_post' THEN
                COALESCE((p_metadata->>'preview_title'), 'Shared Post')
            ELSE
                left(p_content, 100)
        END,
        updated_at = now()
    WHERE id = p_conversation_id;

    RETURN jsonb_build_object(
        'success',         true,
        'message_id',      v_message_id,
        'conversation_id', p_conversation_id
    );
END;
$$;


ALTER FUNCTION public.fn_send_message(p_conversation_id uuid, p_sender_id uuid, p_content text, p_message_type text, p_metadata jsonb) OWNER TO postgres;

--
-- TOC entry 3308 (class 1255 OID 63054995)
-- Name: fn_send_message_once(uuid, uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_send_message_once(p_conversation_id uuid, p_sender_id uuid, p_request_id uuid, p_content text, p_message_type text DEFAULT 'text'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_receipt public.messenger_send_requests%ROWTYPE;
  v_hash text;
  v_message_id uuid;
  v_type text := COALESCE(NULLIF(p_message_type,''),'text');
  v_metadata jsonb := COALESCE(p_metadata,'{}'::jsonb);
BEGIN
  IF p_sender_id IS NULL OR p_conversation_id IS NULL OR p_request_id IS NULL
     OR p_content IS NULL OR length(p_content)=0 OR length(p_content)>2000
     OR v_type NOT IN ('text','shared_post','gif','image','system')
     OR jsonb_typeof(v_metadata)<>'object' OR octet_length(v_metadata::text)>32768 THEN
    RAISE EXCEPTION 'Invalid Message Request' USING ERRCODE='22023';
  END IF;
  -- Keep sender participation through commit. Concurrent removal waits for
  -- this send, or wins first and the send fails without a message/receipt.
  PERFORM 1 FROM public.social_conversation_participants
    WHERE conversation_id=p_conversation_id AND user_id=p_sender_id FOR SHARE;
  IF NOT FOUND OR NOT public.fn_messenger_send_allowed(p_conversation_id,p_sender_id) THEN
    RAISE EXCEPTION 'Cannot Send To This Conversation' USING ERRCODE='42501';
  END IF;
  v_hash := encode(sha256(convert_to(jsonb_build_object(
    'conversation_id',p_conversation_id,'content',p_content,
    'message_type',v_type,'media_metadata',v_metadata)::text,'UTF8')),'hex');
  INSERT INTO public.messenger_send_requests(sender_id,request_id,conversation_id,payload_hash)
    VALUES(p_sender_id,p_request_id,p_conversation_id,v_hash)
    ON CONFLICT(sender_id,request_id) DO NOTHING;
  SELECT * INTO STRICT v_receipt FROM public.messenger_send_requests
    WHERE sender_id=p_sender_id AND request_id=p_request_id FOR UPDATE;
  IF v_receipt.payload_hash<>v_hash OR v_receipt.conversation_id<>p_conversation_id THEN
    RAISE EXCEPTION 'Message Request Conflicts With Previous Send' USING ERRCODE='23505';
  END IF;
  IF v_receipt.message_id IS NOT NULL THEN
    RETURN jsonb_build_object('success',true,'message_id',v_receipt.message_id,
      'conversation_id',p_conversation_id,'replayed',true);
  END IF;
  -- Same persisted content and preview behavior as the installed legacy send,
  -- with request_id on the original INSERT for Realtime-before-HTTP matching.
  INSERT INTO public.social_messages(conversation_id,sender_id,content,message_type,media_metadata,request_id)
    VALUES(p_conversation_id,p_sender_id,p_content,v_type,
      CASE WHEN v_metadata='{}'::jsonb THEN NULL ELSE v_metadata END,p_request_id)
    RETURNING id INTO v_message_id;
  UPDATE public.social_conversations SET last_message_at=now(),
    last_message_preview=CASE WHEN v_type='shared_post'
      THEN COALESCE(v_metadata->>'preview_title','Shared Post') ELSE left(p_content,100) END,
    updated_at=now() WHERE id=p_conversation_id;
  UPDATE public.messenger_send_requests SET message_id=v_message_id
    WHERE sender_id=p_sender_id AND request_id=p_request_id;
  RETURN jsonb_build_object('success',true,'message_id',v_message_id,
    'conversation_id',p_conversation_id,'replayed',false);
END;
$$;


ALTER FUNCTION public.fn_send_message_once(p_conversation_id uuid, p_sender_id uuid, p_request_id uuid, p_content text, p_message_type text, p_metadata jsonb) OWNER TO postgres;

--
-- TOC entry 5008 (class 1255 OID 24465298)
-- Name: fn_serialize_engine_maintenance_break_write(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_serialize_engine_maintenance_break_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  /* PostgreSQL takes ACCESS EXCLUSIVE before firing a TRUNCATE trigger. Waiting
     for the advisory boundary from there would invert the canonical order
     against an admitted entry that next reads this table. This singleton has
     no legitimate truncate path, so refuse immediately instead of deadlocking. */
  IF TG_OP = 'TRUNCATE' THEN
    RAISE EXCEPTION 'engine_maintenance_break may not be truncated'
      USING ERRCODE = '0A000';
  END IF;
  /* One exclusive writer boundary. The matching entry paths take this key in
     shared mode, so purchases stay concurrent with each other but can never
     straddle a maintenance-row commit. Transaction scope prevents a pooled
     connection from retaining the lock. */
  PERFORM pg_advisory_xact_lock(530090, 1);
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_serialize_engine_maintenance_break_write() OWNER TO postgres;

--
-- TOC entry 6730 (class 1255 OID 24465303)
-- Name: fn_serialize_entry_statement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_serialize_entry_statement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  /* This is a backstop for a direct/unwrapped INSERT. A canonical RPC already
     owns the shared lock before touching any rows. An unexpected outer caller
     may already own unrelated rows, so waiting behind a queued maintenance
     writer here could form a soft deadlock. Fail the whole statement
     immediately and transactionally instead; the caller may retry from its
     outer boundary. */
  IF NOT pg_try_advisory_xact_lock_shared(530090, 1) THEN
    RAISE EXCEPTION
      'ENTRY_BOUNDARY_BUSY: maintenance announcement owns the entry boundary'
      USING ERRCODE = '40001';
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_serialize_entry_statement() OWNER TO postgres;

--
-- TOC entry 9517 (class 1255 OID 4652069)
-- Name: fn_set_age_verified(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_set_age_verified(p_user_id uuid, p_jurisdiction_country text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id is required';
  END IF;

  UPDATE public.profiles
     SET age_verified = true,
         age_verified_at = COALESCE(age_verified_at, now()),
         jurisdiction_country = COALESCE(p_jurisdiction_country, jurisdiction_country, country)
   WHERE id = p_user_id;

  INSERT INTO public.kyc_events (user_id, event_type, source, payload)
  VALUES (p_user_id, 'age_gate_passed', 'user_action',
          jsonb_build_object('jurisdiction_country', p_jurisdiction_country));

  RETURN jsonb_build_object('ok', true, 'age_verified', true);
END;
$$;


ALTER FUNCTION public.fn_set_age_verified(p_user_id uuid, p_jurisdiction_country text) OWNER TO postgres;

--
-- TOC entry 8938 (class 1255 OID 55217110)
-- Name: fn_set_capability_readiness(text, text, text, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_set_capability_readiness(p_capability_id text, p_readiness text, p_rule_version text, p_expected_revision bigint, p_evidence jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor_role text;
  v_evidence jsonb := COALESCE(p_evidence, '{}'::jsonb);
  v_row public.platform_capabilities;
  v_from text;
BEGIN
  IF auth.role() = 'service_role' THEN
    v_actor_role := 'service_role';
  ELSIF public.fn_is_platform_admin() THEN
    v_actor_role := 'platform_admin';
  ELSE
    RAISE EXCEPTION 'CAPABILITY_WRITER_REQUIRES_SERVICE_ROLE_OR_PLATFORM_STAFF' USING ERRCODE = '42501';
  END IF;

  IF p_readiness IS NULL OR p_readiness NOT IN
       ('excluded','planned','implemented','tested','deployed','production_verified') THEN
    RAISE EXCEPTION 'CAPABILITY_READINESS_UNKNOWN: %', p_readiness USING ERRCODE = '22023';
  END IF;
  IF p_rule_version IS NULL OR btrim(p_rule_version) = '' THEN
    RAISE EXCEPTION 'CAPABILITY_RULE_VERSION_REQUIRED' USING ERRCODE = '22023';
  END IF;
  IF p_expected_revision IS NULL THEN
    RAISE EXCEPTION 'CAPABILITY_EXPECTED_REVISION_REQUIRED' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(v_evidence) <> 'object' THEN
    RAISE EXCEPTION 'CAPABILITY_EVIDENCE_MUST_BE_AN_OBJECT' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_row
    FROM public.platform_capabilities
   WHERE capability_id = p_capability_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'CAPABILITY_UNKNOWN: %', p_capability_id USING ERRCODE = 'P0002';
  END IF;

  -- Exclusion is an owner decision taken in a migration, not a readiness step.
  IF v_row.readiness = 'excluded' OR p_readiness = 'excluded' THEN
    RAISE EXCEPTION 'CAPABILITY_EXCLUSION_IS_AN_OWNER_DECISION: %', p_capability_id USING ERRCODE = '55000';
  END IF;

  -- Replay of the transition that produced the current row: same target, same
  -- expected revision, same evidence. Return it; record nothing twice.
  IF v_row.revision = p_expected_revision + 1
     AND v_row.readiness = p_readiness
     AND v_row.rule_version = p_rule_version
     AND v_row.readiness_evidence = v_evidence
     AND EXISTS (SELECT 1 FROM public.platform_capability_events e
                  WHERE e.capability_id = p_capability_id
                    AND e.revision = v_row.revision
                    AND e.to_readiness = p_readiness
                    AND e.rule_version = p_rule_version
                    AND e.evidence = v_evidence) THEN
    RETURN to_jsonb(v_row) || jsonb_build_object('event_recorded', false);
  END IF;

  IF v_row.revision <> p_expected_revision THEN
    RAISE EXCEPTION 'CAPABILITY_REVISION_STALE: % expected revision %, current %',
      p_capability_id, p_expected_revision, v_row.revision USING ERRCODE = '55000';
  END IF;

  IF p_readiness IN ('deployed','production_verified') AND v_evidence = '{}'::jsonb THEN
    RAISE EXCEPTION 'CAPABILITY_EVIDENCE_REQUIRED: % needs evidence to become %',
      p_capability_id, p_readiness USING ERRCODE = '22023';
  END IF;

  -- Asking for exactly what is already there is not a transition.
  IF v_row.readiness = p_readiness
     AND v_row.rule_version = p_rule_version
     AND v_row.readiness_evidence = v_evidence THEN
    RETURN to_jsonb(v_row) || jsonb_build_object('event_recorded', false);
  END IF;

  v_from := v_row.readiness;
  UPDATE public.platform_capabilities
     SET readiness = p_readiness,
         rule_version = p_rule_version,
         readiness_evidence = v_evidence,
         revision = revision + 1,
         updated_at = clock_timestamp()
   WHERE capability_id = p_capability_id
  RETURNING * INTO v_row;

  INSERT INTO public.platform_capability_events
    (capability_id, revision, from_readiness, to_readiness, rule_version, evidence, actor, actor_role)
  VALUES
    (p_capability_id, v_row.revision, v_from, p_readiness, p_rule_version, v_evidence, auth.uid(), v_actor_role);

  RETURN to_jsonb(v_row) || jsonb_build_object('event_recorded', true);
END
$$;


ALTER FUNCTION public.fn_set_capability_readiness(p_capability_id text, p_readiness text, p_rule_version text, p_expected_revision bigint, p_evidence jsonb) OWNER TO postgres;

--
-- TOC entry 8925 (class 1255 OID 55241576)
-- Name: fn_set_cash_game_kill_settings(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_set_cash_game_kill_settings(p_game_id uuid, p_kill_mode text, p_kill_threshold_bb integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_mode text := lower(btrim(p_kill_mode));
  g public.cash_games%ROWTYPE;
  v_refusal text;
  v_before jsonb;
  v_after jsonb;
  v_tables_before jsonb;
  v_applied integer;
  v_audited integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sign In To Change Kill Pots' USING ERRCODE = '28000';
  END IF;
  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION 'This Session Has Ended, Sign In Again' USING ERRCODE = '28000';
  END IF;
  IF v_mode IS NULL OR v_mode NOT IN ('off','half','full') THEN
    RAISE EXCEPTION 'Kill Mode Must Be Off, Half Or Full' USING ERRCODE = '22023';
  END IF;
  IF p_kill_threshold_bb IS NULL OR p_kill_threshold_bb NOT IN (8,10,12,15) THEN
    RAISE EXCEPTION 'Kill Threshold Must Be 8, 10, 12 Or 15 Big Blinds' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO g FROM public.cash_games WHERE id = p_game_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cash Game Not Found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.fn_can_create_games(g.club_id, v_uid) THEN
    RAISE EXCEPTION 'Only The Club Owner Or An Admin Can Change Kill Pots' USING ERRCODE = '42501';
  END IF;
  -- A game with no snapshot is projected by nothing (fn_cash_apply_ruleset
  -- returns at once for it). Writing {"kill":...} into it would make every
  -- OTHER rule of that game project from an empty snapshot, so it is refused.
  IF g.ruleset_snapshot IS NULL OR jsonb_typeof(g.ruleset_snapshot) <> 'object' THEN
    RAISE EXCEPTION 'This Cash Game Has No Ruleset To Change' USING ERRCODE = '22023';
  END IF;

  IF v_mode <> 'off' THEN
    IF NOT public.fn_capability_available('cash.fixed_limit.kill_pots') THEN
      RAISE EXCEPTION 'Kill Pots Are Not Available Yet' USING ERRCODE = '22023';
    END IF;
    v_refusal := public.fn_kill_pot_configuration_refusal(
      v_mode, g.variant, 'cash', NULL,
      coalesce((g.ruleset_snapshot->'bombs'->>'enabled')::boolean, false), g.bb, g.club_id);
    IF v_refusal IS NOT NULL THEN
      RAISE EXCEPTION '%', v_refusal USING ERRCODE = '22023';
    END IF;
  END IF;

  v_before := coalesce(g.ruleset_snapshot->'kill', '{"mode":"off","threshold_bb":10}'::jsonb);
  v_after := jsonb_build_object('mode', v_mode, 'threshold_bb', p_kill_threshold_bb);

  SELECT coalesce(jsonb_object_agg(t.id::text, jsonb_build_object(
           'kill_mode', t.kill_mode, 'kill_threshold_bb', t.kill_threshold_bb)), '{}'::jsonb)
    INTO v_tables_before
    FROM public.tables t
   WHERE t.cluster_id = g.id AND t.lifecycle <> 'closed' AND coalesce(t.is_deleted, false) = false;

  UPDATE public.cash_games
     SET ruleset_snapshot = ruleset_snapshot || jsonb_build_object('kill', v_after),
         updated_at = now()
   WHERE id = g.id;

  -- Through the one function allowed to map a snapshot onto a cluster.
  v_applied := public.fn_cash_apply_ruleset(g.id);

  INSERT INTO public.table_settings_changes (table_id, club_id, changed_by, before, after)
  SELECT t.id, coalesce(t.club_id, g.club_id), v_uid,
         v_tables_before->(t.id::text),
         jsonb_build_object('kill_mode', t.kill_mode, 'kill_threshold_bb', t.kill_threshold_bb)
    FROM public.tables t
   WHERE t.cluster_id = g.id AND t.lifecycle <> 'closed' AND coalesce(t.is_deleted, false) = false
     AND v_tables_before ? (t.id::text)
     AND (v_tables_before->(t.id::text)) IS DISTINCT FROM
         jsonb_build_object('kill_mode', t.kill_mode, 'kill_threshold_bb', t.kill_threshold_bb);
  GET DIAGNOSTICS v_audited = ROW_COUNT;

  IF v_before IS DISTINCT FROM v_after OR v_audited > 0 THEN
    INSERT INTO public.cash_cluster_events (game_id, kind, payload)
    VALUES (g.id, 'kill_settings_changed',
            jsonb_build_object('before', v_before, 'after', v_after, 'changed_by', v_uid,
                               'tables_changed', v_audited, 'rule_version', 'kill-v1'));
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'changed', v_before IS DISTINCT FROM v_after OR v_audited > 0,
    'game_id', g.id,
    'kill', v_after,
    'tables_applied', v_applied,
    'tables_changed', v_audited);
END
$$;


