--
-- TOC entry 7302 (class 1255 OID 104277268)
-- Name: fn_set_video_reels_pipeline_control(uuid, uuid, text, boolean, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_set_video_reels_pipeline_control(p_operation_id uuid, p_actor_id uuid, p_control_key text, p_enabled boolean, p_expected_updated_at timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  prior public.video_reels_control_events%ROWTYPE;
  current_control public.video_reels_pipeline_controls%ROWTYPE;
  updated_control public.video_reels_pipeline_controls%ROWTYPE;
BEGIN
  IF p_operation_id IS NULL OR p_actor_id IS NULL OR p_enabled IS NULL
     OR p_expected_updated_at IS NULL OR p_control_key IS NULL
     OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 1 AND 240 THEN
    RAISE EXCEPTION 'invalid pipeline control request';
  END IF;
  IF p_control_key NOT IN ('video_library_discovery','video_library_enrichment',
      'video_library_reel_creation','video_library_reel_publication','video_library_editorial_gate') THEN
    RAISE EXCEPTION 'pipeline control is not operator-adjustable';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_operation_id::text, 0));
  SELECT * INTO prior FROM public.video_reels_control_events WHERE operation_id=p_operation_id;
  IF FOUND THEN
    IF prior.actor_user_id<>p_actor_id OR prior.control_key<>p_control_key
       OR prior.enabled_after<>p_enabled OR prior.reason<>btrim(p_reason) THEN
      RAISE EXCEPTION 'operation replay payload mismatch';
    END IF;
    SELECT * INTO current_control FROM public.video_reels_pipeline_controls WHERE control_key=p_control_key;
    RETURN jsonb_build_object('replayed',true,'event',to_jsonb(prior),'control',to_jsonb(current_control));
  END IF;

  SELECT * INTO current_control FROM public.video_reels_pipeline_controls
  WHERE control_key=p_control_key FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'pipeline control is missing'; END IF;
  IF current_control.updated_at<>p_expected_updated_at THEN
    RAISE EXCEPTION 'pipeline control version conflict';
  END IF;
  IF current_control.enabled=p_enabled AND current_control.reason=btrim(p_reason) THEN
    RAISE EXCEPTION 'pipeline control already has this value';
  END IF;

  UPDATE public.video_reels_pipeline_controls
  SET enabled=p_enabled,reason=btrim(p_reason)
  WHERE control_key=p_control_key
  RETURNING * INTO updated_control;
  INSERT INTO public.video_reels_control_events(
    operation_id,actor_user_id,control_key,enabled_before,enabled_after,reason,control_updated_at
  ) VALUES (
    p_operation_id,p_actor_id,p_control_key,current_control.enabled,p_enabled,
    btrim(p_reason),updated_control.updated_at
  ) RETURNING * INTO prior;
  RETURN jsonb_build_object('replayed',false,'event',to_jsonb(prior),'control',to_jsonb(updated_control));
END
$$;


ALTER FUNCTION public.fn_set_video_reels_pipeline_control(p_operation_id uuid, p_actor_id uuid, p_control_key text, p_enabled boolean, p_expected_updated_at timestamp with time zone, p_reason text) OWNER TO postgres;

--
-- TOC entry 6522 (class 1255 OID 93233489)
-- Name: fn_settle_accounting_commission_advance(text, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_settle_accounting_commission_advance(p_scope_kind text, p_scope_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE w record; r record; sc record; began timestamptz; proved boolean:=false; v_kind text:='round2_'||p_scope_kind||'_window';
 stop_at timestamptz;
BEGIN
 IF COALESCE(current_setting('app.weekly_accounting_chunked',true),'')<>'on'
  OR NULLIF(current_setting('app.weekly_accounting_scope_deadline',true),'') IS NULL
  OR p_scope_kind NOT IN('union','club') OR p_scope_id IS NULL OR p_period_start IS NULL OR p_period_end IS NULL
  OR NOT isfinite(p_period_start) OR NOT isfinite(p_period_end) OR p_period_start>=p_period_end OR p_period_end>clock_timestamp() THEN
  RETURN NULL;
 END IF;
 began:=NULLIF(current_setting('app.weekly_accounting_scope_deadline',true),'')::timestamptz
  -COALESCE(NULLIF(current_setting('app.weekly_accounting_scope_budget',true),''),'8 minutes')::interval;
 -- THE STATEMENT'S OWN CLOCK (20261015181721): job 272 visits other scopes
 -- and prepares the book before this loop, so an attempt can reach it late
 -- in its 240 s statement. A window is never started less than a minute
 -- before the statement would be cancelled, which would roll back every
 -- window this attempt proved; the attempt commits what it has instead.
 stop_at:='infinity';
 IF current_setting('statement_timeout') NOT IN ('0','0ms') THEN
  stop_at:=statement_timestamp()+current_setting('statement_timeout')::interval-interval '60 seconds';
 END IF;
 DELETE FROM public.accounting_close_partials WHERE computed_at<clock_timestamp()-interval '8 days';
 -- The book's scope (and its week lock, which every accrual of the week
 -- shares), resolved once for every window.
 SELECT * INTO sc FROM public.fn_resolve_accounting_routing_scope(p_scope_kind,p_scope_id,p_period_start,p_period_end);
 FOR w IN SELECT * FROM public.fn_accounting_close_windows(p_period_start,p_period_end) ORDER BY 1 LOOP
  CONTINUE WHEN EXISTS(SELECT 1 FROM public.accounting_close_partials p WHERE p.kind=v_kind AND p.union_id=p_scope_id
   AND p.period_start=p_period_start AND p.period_end=p_period_end AND p.window_start=w.window_start AND p.window_end=w.window_end
   AND p.computed_at>=p_period_end AND p.computed_at>clock_timestamp()-public.fn_accounting_close_proof_lifetime());
  IF clock_timestamp()>stop_at OR (proved AND clock_timestamp()>began+interval '120 seconds') THEN RETURN false; END IF;
