-- Name: FUNCTION fn_settle_accounting_commission_advance(p_scope_kind text, p_scope_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_settle_accounting_commission_advance(p_scope_kind text, p_scope_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone) IS 'Chunked weekly close (20261003): proves the missing two-hour round-2 windows of a closed week, at least one per attempt and none started 120 s after the attempt began; true when all are proved, false when the attempt should stop, NULL outside a chunked close attempt.';


