-- TOC entry 6886 (class 1255 OID 61182499)
-- Name: fn_smarter_poker_pulse_cron_counts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_smarter_poker_pulse_cron_counts() RETURNS TABLE(cron_jobs_active bigint, cron_failures_24h numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '8s'
    AS $$
  SELECT
    (SELECT count(*) FROM cron.job j WHERE j.active
       AND (j.jobname LIKE 'home%' OR j.jobname LIKE 'pnm%')),
    (SELECT count(*)::numeric FROM cron.job j
       JOIN cron.job_run_details d ON d.jobid=j.jobid
       WHERE d.start_time > now()-interval '24 hours' AND d.status='failed');
$$;


