--
-- TOC entry 6641 (class 1255 OID 16221414)
-- Name: fn_snapshot_index_usage(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_snapshot_index_usage() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_n integer;
BEGIN
  INSERT INTO public.index_usage_snapshots
    (taken_at, postmaster_start, schemaname, relname, indexrelname, idx_scan, index_bytes)
  SELECT now(), pg_postmaster_start_time(), s.schemaname, s.relname, s.indexrelname,
         s.idx_scan, pg_relation_size(s.indexrelid)
    FROM pg_stat_user_indexes s
    JOIN pg_index i ON i.indexrelid = s.indexrelid
   WHERE s.schemaname = 'public'
     AND NOT i.indisunique      -- a unique index is a constraint, not a lookup aid
     AND NOT i.indisprimary
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


ALTER FUNCTION public.fn_snapshot_index_usage() OWNER TO postgres;

--
-- TOC entry 4976 (class 1255 OID 25609189)
-- Name: fn_snapshot_maintenance_thaw_targets(timestamp with time zone, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_snapshot_maintenance_thaw_targets(p_freeze_started timestamp with time zone, p_initial_seconds numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_counts jsonb := '{}'::jsonb;
  v_n integer;
BEGIN
  INSERT INTO public.engine_maintenance_thaw_targets(freeze_started_at, step, target_id)
  SELECT p_freeze_started, 'sit_out_at', s.id
    FROM public.table_seats s
   WHERE s.left_at IS NULL AND s.sit_out_at IS NOT NULL
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('sit_out_at', v_n);

  INSERT INTO public.engine_maintenance_thaw_targets(freeze_started_at, step, target_id)
  SELECT p_freeze_started, 'hold_expires_at', w.id
    FROM public.table_waitlist w
   WHERE w.hold_expires_at > p_freeze_started
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('hold_expires_at', v_n);

  INSERT INTO public.engine_maintenance_thaw_targets(freeze_started_at, step, target_id)
  SELECT p_freeze_started, 'addon_period_ends_at', t.id
    FROM public.tournaments t
   WHERE t.addon_period_ends_at > p_freeze_started
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('addon_period_ends_at', v_n);

  INSERT INTO public.engine_maintenance_thaw_targets(freeze_started_at, step, target_id)
  SELECT p_freeze_started, 'reversible_until', c.id
    FROM public.chip_transactions c
   WHERE c.reversible_until > p_freeze_started
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('reversible_until', v_n);

  INSERT INTO public.engine_maintenance_thaw_targets(freeze_started_at, step, target_id)
  SELECT p_freeze_started, 'reveal_deadline_at', a.id
    FROM public.tournament_bounty_awards a
   WHERE a.reveal_deadline_at > p_freeze_started
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('reveal_deadline_at', v_n);

  INSERT INTO public.engine_maintenance_thaw_targets(freeze_started_at, step, target_id)
  SELECT p_freeze_started, 'rebuy_prompt_until', p.id
    FROM public.tournament_players p
   WHERE p.rebuy_prompt_until > p_freeze_started
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('rebuy_prompt_until', v_n);

  INSERT INTO public.engine_maintenance_thaw_targets(freeze_started_at, step, target_id)
  SELECT p_freeze_started, 'bomb_pot_next_due_at', t.id
    FROM public.tables t
   WHERE t.bomb_pot_next_due_at IS NOT NULL
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('bomb_pot_next_due_at', v_n);

  INSERT INTO public.engine_maintenance_thaw_targets(freeze_started_at, step, target_id)
  SELECT p_freeze_started, 'cash_stay_last_tick_at', s.id
    FROM public.cash_player_session s
   WHERE s.closed_at IS NULL
     AND s.stay_running
     AND s.stay_last_tick_at <= p_freeze_started + make_interval(secs => p_initial_seconds)
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('cash_stay_last_tick_at', v_n);

  INSERT INTO public.engine_maintenance_thaw_targets(freeze_started_at, step, target_id)
  SELECT p_freeze_started, 'cash_rejoin_expires_at', r.id
    FROM public.cash_rejoin_constraints r
   WHERE r.expires_at > p_freeze_started
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('cash_rejoin_expires_at', v_n);

  INSERT INTO public.engine_maintenance_thaw_targets(freeze_started_at, step, target_id)
  SELECT p_freeze_started, 'cluster_break_eligible_since', t.id
    FROM public.tables t
   WHERE t.break_eligible_since IS NOT NULL
     AND t.break_eligible_since <= p_freeze_started + make_interval(secs => p_initial_seconds)
     AND t.cluster_id IS NOT NULL
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('cluster_break_eligible_since', v_n);

  INSERT INTO public.engine_maintenance_thaw_targets(freeze_started_at, step, target_id)
  SELECT p_freeze_started, 'cluster_move_expires_at', m.id
    FROM public.cash_seat_moves m
   WHERE m.state = 'pending' AND m.expires_at > p_freeze_started
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('cluster_move_expires_at', v_n);

  INSERT INTO public.engine_maintenance_thaw_targets(freeze_started_at, step, target_id)
  SELECT p_freeze_started, 'level_started_at', t.id
    FROM public.tournaments t
   WHERE t.status = 'RUNNING'
     AND COALESCE(t.on_break, false) = false
     AND t.level_started_at IS NOT NULL
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('level_started_at', v_n);

  INSERT INTO public.engine_maintenance_thaw_targets(freeze_started_at, step, target_id)
  SELECT p_freeze_started, 'reconnect_presence', p.table_id
    FROM public.engine_presence_parked p
   WHERE p.parked_at >= p_freeze_started - INTERVAL '20 minutes'
     AND p.parked_at <= p_freeze_started + make_interval(secs => p_initial_seconds)
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('reconnect_presence', v_n);

  INSERT INTO public.engine_maintenance_thaw_targets(freeze_started_at, step, target_id)
  SELECT p_freeze_started, 'reconnect_snapshots', s.id
    FROM public.hand_state_snapshots s
   WHERE s.is_complete = false
     AND s.updated_at >= p_freeze_started - INTERVAL '20 minutes'
     AND s.updated_at <= p_freeze_started + make_interval(secs => p_initial_seconds)
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('reconnect_snapshots', v_n);

  INSERT INTO public.engine_maintenance_thaw_targets(freeze_started_at, step, target_id)
  SELECT p_freeze_started, 'lightning_drain_deadline_at', d.id
    FROM public.lightning_cluster_drain d
   WHERE d.completed_at IS NULL AND d.deadline_at > p_freeze_started
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  v_counts := v_counts || jsonb_build_object('lightning_drain_deadline_at', v_n);

  UPDATE public.engine_maintenance_thaws t
     SET shifted = t.shifted || jsonb_build_object(
       '_targets_snapshotted', true,
       '_target_counts', v_counts
     )
   WHERE t.freeze_started_at = p_freeze_started;
  RETURN v_counts;
END;
$$;


ALTER FUNCTION public.fn_snapshot_maintenance_thaw_targets(p_freeze_started timestamp with time zone, p_initial_seconds numeric) OWNER TO postgres;

--
-- TOC entry 5413 (class 1255 OID 9731234)
-- Name: fn_snapshot_player_stats(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_snapshot_player_stats() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer;
  v_date date := CURRENT_DATE;
  v_new_capture boolean;
  v_capture_at timestamptz;
BEGIN
  -- Serializes the existing producer's concurrent calls without locking stats
  -- writers. Statement MVCC reads the applied projection atomically.
  PERFORM pg_advisory_xact_lock(hashtextextended('leaderboard-capture:' || v_date::text, 0));
  SELECT NOT EXISTS (
    SELECT 1 FROM public.leaderboard_complete_captures WHERE capture_date = v_date
  ) INTO v_new_capture;
  v_capture_at := clock_timestamp();
  -- Shared legacy semantics remain CURRENT_DATE in the caller's timezone.
  -- Ranking boundaries are UTC dates and the actual scheduled producer is GMT.
  -- A first capture whose caller date disagrees with its actual UTC capture day
  -- cannot prove that boundary. Refuse before ANY legacy/capture write, without
  -- silently changing session timezone or relabeling shared snapshot dates.
  -- Equivalent-date non-UTC callers remain supported. Repeated legacy upserts
  -- retain their existing date/return contract and never replace a capture.
  IF v_new_capture AND v_date <> (v_capture_at AT TIME ZONE 'UTC')::date THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'LEADERBOARD_CAPTURE_DATE_CONTRACT_MISMATCH';
  END IF;

  WITH applied AS MATERIALIZED (
    SELECT user_id, club_id,
      COALESCE(hands_played, 0) AS hands_played,
      COALESCE(hands_dealt, 0) AS hands_dealt,
      COALESCE(sum_big_blind, 0) AS sum_big_blind,
      COALESCE(total_winnings, 0) AS total_winnings,
      COALESCE(total_losses, 0) AS total_losses,
      COALESCE(total_rake, 0) AS total_rake,
      COALESCE(tournaments_played, 0) AS tournaments_played,
      COALESCE(tournaments_won, 0) AS tournaments_won
    FROM public.player_stats WHERE club_id IS NOT NULL
  ), legacy AS (
    INSERT INTO public.player_stats_snapshots
      (user_id, club_id, snapshot_date, hands_played, hands_dealt, sum_big_blind,
       total_winnings, total_losses, total_rake, tournaments_played, tournaments_won)
    SELECT user_id, club_id, v_date, hands_played, hands_dealt, sum_big_blind,
      total_winnings, total_losses, total_rake, tournaments_played, tournaments_won
    FROM applied
    ON CONFLICT (user_id, club_id, snapshot_date) DO UPDATE SET
      hands_played = EXCLUDED.hands_played, hands_dealt = EXCLUDED.hands_dealt,
      sum_big_blind = EXCLUDED.sum_big_blind,
      total_winnings = EXCLUDED.total_winnings, total_losses = EXCLUDED.total_losses,
      total_rake = EXCLUDED.total_rake, tournaments_played = EXCLUDED.tournaments_played,
      tournaments_won = EXCLUDED.tournaments_won
    RETURNING 1
  ), header AS (
    INSERT INTO public.leaderboard_complete_captures
      (capture_date, captured_at, capture_timezone, origin, source_contract,
       row_count, counter_hash, complete)
    SELECT v_date, v_capture_at, current_setting('TimeZone'),
      'fn_snapshot_player_stats', 'applied_player_stats_v1', count(*),
      md5(COALESCE(string_agg(to_jsonb(applied)::text, E'\n' ORDER BY club_id, user_id), '')), true
    FROM applied HAVING v_new_capture
    RETURNING capture_date
  ), immutable AS (
    INSERT INTO public.leaderboard_capture_counters
      (snapshot_date, user_id, club_id, hands_played, hands_dealt, sum_big_blind,
       total_winnings, total_losses, total_rake, tournaments_played, tournaments_won)
    SELECT header.capture_date, applied.* FROM applied CROSS JOIN header
    RETURNING 1
  )
  SELECT count(*)::integer INTO v_count FROM legacy;
  -- Same public return keys and legacy row count on repeated calls. Immutable
  -- copies are first-complete-capture only; later calls still update shared rows.
  RETURN jsonb_build_object('success', true, 'rows', v_count, 'date', v_date);
END;
$$;


ALTER FUNCTION public.fn_snapshot_player_stats() OWNER TO postgres;

--
-- TOC entry 5294 (class 1255 OID 14261223)
-- Name: fn_snapshot_player_stats_if_missing(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_snapshot_player_stats_if_missing() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_exists boolean; v_res jsonb;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM player_stats_snapshots WHERE snapshot_date = CURRENT_DATE
  ) INTO v_exists;

  IF v_exists THEN
    RETURN jsonb_build_object(
      'healed', false, 'reason', 'snapshot_already_present', 'date', CURRENT_DATE);
  END IF;

  v_res := fn_snapshot_player_stats();
  RETURN jsonb_build_object(
    'healed', true, 'date', CURRENT_DATE, 'capture', v_res);
END; $$;


ALTER FUNCTION public.fn_snapshot_player_stats_if_missing() OWNER TO postgres;

