COMMENT ON FUNCTION public.fn_spin_metrics(p_lag_window_minutes integer) IS 'One row of Spin telemetry for the engine scrape. seconds_since_last_start and open_boards exist because on 2026-09-01 every tournament INSERT failed for four hours and every other number here stayed green: they all measure the games that exist, and none could see that no game could be created.';


--
-- TOC entry 8848 (class 1255 OID 15203018)
-- Name: fn_spin_move_owner_wallet(uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_move_owner_wallet(p_owner_id uuid, p_owner_kind text, p_wallet text, p_delta numeric) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE v_after numeric;
BEGIN
  /* ZERO-DRIFT phase 6: declare the ledger identity of the spin margin flow.
     Positive delta = spin margin landing with the owner (rake, from the spin
     reserve); negative delta = the owner funding the spin pool (overlay). */
  /* NON-DESTRUCTIVE DECLARATION. A caller that has already said what
     this movement is knows more than this function does: fn_spin_settle_game
     declares treasury_transfer / club_treasury / <club> and autoskips clubs,
     because the seed return is ONE transfer represented by two balance-store
     updates. Overwriting that unconditionally is what wrote
     e23f4387-495a-4530-8b5d-eef334869ec3 -- spin_reserve -> spin_reserve with
     no destination entity, 2624.78 leaving the pool and arriving nowhere --
     and left Deep Stack Society reading +2,624.78 of treasury drift from
     2026-09-18. fn_ca_declare_ledger set_config's ALL THREE GUCs every call,
     including the counterparty entity, so the caller lost the entity too.
     The default below stays 'spin_reserve': this function moves the OWNER's
     wallet, whose counterparty genuinely is the spin reserve. */
  IF NULLIF(current_setting('app.ledger_counterparty', true), '') IS NULL THEN
    PERFORM public.fn_ca_declare_ledger(
      CASE WHEN p_delta >= 0 THEN 'rake' ELSE 'overlay' END, 'spin_reserve');
  END IF;

  IF p_owner_kind = 'union' THEN
    IF p_wallet NOT IN ('chip_balance','promo_wallet','rake_wallet','spin_reserve_wallet') THEN
      RAISE EXCEPTION 'unknown union wallet %', p_wallet;
    END IF;

    PERFORM set_config('app.uwt_selfjournal', '1', true);

    EXECUTE format(
      'UPDATE public.union_wallets SET %I = %I + $1, updated_at = now()
        WHERE union_id = $2 AND %I + $1 >= 0 RETURNING %I',
      p_wallet, p_wallet, p_wallet, p_wallet)
      INTO v_after USING p_delta, p_owner_id;

    IF v_after IS NOT NULL AND round(p_delta, 2) <> 0 THEN
      INSERT INTO public.union_wallet_transactions
        (union_id, wallet, direction, amount, balance_after, tx_type, notes)
      VALUES
        (p_owner_id, p_wallet,
         CASE WHEN p_delta > 0 THEN 'credit' ELSE 'debit' END,
         abs(round(p_delta, 2)), v_after,
         CASE WHEN p_delta > 0 THEN 'spin_seed_return' ELSE 'spin_pool_funding' END,
         CASE WHEN p_delta > 0
              THEN 'Spin reserve seed instalment returned to the union '
                || p_wallet || ' (fn_spin_move_owner_wallet)'
              ELSE 'Union ' || p_wallet || ' funded the spin reserve '
                || '(fn_spin_move_owner_wallet)' END);
    END IF;

    PERFORM set_config('app.uwt_selfjournal', '', true);
  ELSE
    IF p_wallet NOT IN ('chip_treasury','promo_balance') THEN
      RAISE EXCEPTION 'unknown club wallet %', p_wallet;
    END IF;
    EXECUTE format(
      'UPDATE public.clubs SET %I = COALESCE(%I,0) + $1
        WHERE id = $2 AND COALESCE(%I,0) + $1 >= 0 RETURNING %I',
      p_wallet, p_wallet, p_wallet, p_wallet)
      INTO v_after USING p_delta, p_owner_id;
  END IF;
  RETURN v_after;
END;
$_$;


