--
-- TOC entry 3644 (class 1255 OID 16625736)
-- Name: fn_spin_reap_stale_boards(integer, boolean, boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_reap_stale_boards(p_stale_mins integer DEFAULT 15, p_dry_run boolean DEFAULT true, p_include_unsold boolean DEFAULT true, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_mins      integer := GREATEST(COALESCE(p_stale_mins, 15), 1);
  v_limit     integer := GREATEST(COALESCE(p_limit, 100), 1);
  v_dry       boolean := COALESCE(p_dry_run, true);
  v_b         record;
  v_plan      jsonb := '[]'::jsonb;
  v_res       jsonb;
  v_partial   integer := 0;
  v_unsold    integer := 0;
  v_chips     numeric := 0;
  v_seats     integer := 0;
  v_cancelled integer := 0;
  v_refunded  numeric := 0;
  v_failed    integer := 0;
  v_skipped   integer := 0;
  v_still     text;
  v_now_seats integer;
BEGIN
  -- Two copies of this sweep racing each other would double-cancel. Don't.
  IF NOT pg_try_advisory_lock(hashtext('fn_spin_reap_stale_boards')) THEN
    RETURN jsonb_build_object('ok', true, 'skipped', 'another reap is already running');
  END IF;

  FOR v_b IN
    SELECT t.id, t.name, t.club_id, t.buy_in_amount,
           COALESCE(t.max_players, 3) AS max_players,
           t.created_at,
           (SELECT COUNT(*) FROM public.tournament_players tp
             WHERE tp.tournament_id = t.id) AS seats,
           (SELECT COALESCE(SUM(
                     CASE WHEN w.type = 'debit'
                           AND w.category IN ('tournament_buyin','rebuy','addon') THEN w.amount
                          WHEN w.type = 'credit' AND w.category = 'refund'        THEN -w.amount
                          ELSE 0 END), 0)
              FROM public.wallet_transactions w
             WHERE w.related_entity_id = t.id) AS committed_chips
      FROM public.tournaments t
     WHERE t.variant   = 'spin'
       AND t.status    = 'REGISTERING'
       AND t.started_at IS NULL
       AND t.created_at < now() - make_interval(mins => v_mins)
     ORDER BY t.created_at
     LIMIT v_limit
  LOOP
    CONTINUE WHEN v_b.seats >= v_b.max_players;                       -- full: about to launch
    CONTINUE WHEN v_b.seats = 0 AND NOT COALESCE(p_include_unsold, true);

    IF v_b.seats = 0 THEN v_unsold := v_unsold + 1;
                     ELSE v_partial := v_partial + 1; END IF;
    v_seats := v_seats + v_b.seats;
    v_chips := v_chips + v_b.committed_chips;

    v_plan := v_plan || jsonb_build_object(
                'tournament_id',    v_b.id,
                'name',             v_b.name,
                'club_id',          v_b.club_id,
                'buy_in',           v_b.buy_in_amount,
                'seats_sold',       v_b.seats,
                'seats_needed',     v_b.max_players,
                'committed_chips',  v_b.committed_chips,
                'age_mins',         round(extract(epoch FROM (now() - v_b.created_at)) / 60),
                'action',           CASE WHEN v_dry THEN 'would delegate to atomic_cancel_tournament'
                                         ELSE 'delegated to atomic_cancel_tournament' END);

    CONTINUE WHEN v_dry;

    -- Re-check under the cancel path's own lock window. A board that filled
    -- and launched since the scan must be left alone.
    SELECT t.status,
           (SELECT COUNT(*) FROM public.tournament_players tp WHERE tp.tournament_id = t.id)
      INTO v_still, v_now_seats
      FROM public.tournaments t
     WHERE t.id = v_b.id
       FOR UPDATE;

    IF v_still IS DISTINCT FROM 'REGISTERING' OR v_now_seats >= v_b.max_players THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    BEGIN
      -- The ONLY teardown path. This function never writes a wallet,
      -- tournament_players or balance row itself.
      v_res := public.atomic_cancel_tournament(v_b.id, NULL);
      IF COALESCE((v_res->>'success')::boolean, false) THEN
        v_cancelled := v_cancelled + 1;
        v_refunded  := v_refunded + COALESCE((v_res->>'total_refunded')::numeric, 0);
      ELSE
        v_failed := v_failed + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      INSERT INTO public.financial_alerts (severity, source, message, context)
      VALUES ('warning', 'fn_spin_reap_stale_boards',
              format('Could not tear down stale Spin board %s: %s',
                     COALESCE(v_b.name, v_b.id::text), SQLERRM),
              jsonb_build_object('tournament_id', v_b.id, 'club_id', v_b.club_id,
                                 'seats_sold', v_b.seats,
                                 'committed_chips', v_b.committed_chips,
                                 'sqlerrm', SQLERRM));
    END;
  END LOOP;

  PERFORM pg_advisory_unlock(hashtext('fn_spin_reap_stale_boards'));

  RETURN jsonb_build_object(
    'ok',                    true,
    'dry_run',               v_dry,
    'stale_mins',            v_mins,
    'include_unsold',        COALESCE(p_include_unsold, true),
    'candidates',            v_partial + v_unsold,
    'partially_sold_boards', v_partial,
    'unsold_boards',         v_unsold,
    'seats_affected',        v_seats,
    'committed_chips',       round(v_chips, 2),
    'cancelled',             v_cancelled,
    'chips_refunded',        round(v_refunded, 2),
    'skipped_raced',         v_skipped,
    'failed',                v_failed,
    'delegate',              'public.atomic_cancel_tournament(uuid, uuid)',
    'plan',                  v_plan);
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_advisory_unlock(hashtext('fn_spin_reap_stale_boards'));
  RAISE;
END;
$$;


ALTER FUNCTION public.fn_spin_reap_stale_boards(p_stale_mins integer, p_dry_run boolean, p_include_unsold boolean, p_limit integer) OWNER TO postgres;

--
-- TOC entry 49007 (class 0 OID 0)
-- Dependencies: 3644
-- Name: FUNCTION fn_spin_reap_stale_boards(p_stale_mins integer, p_dry_run boolean, p_include_unsold boolean, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_reap_stale_boards(p_stale_mins integer, p_dry_run boolean, p_include_unsold boolean, p_limit integer) IS 'Recurring reaper for Spin boards stuck in REGISTERING with committed buy-ins. Delegates every teardown and refund to atomic_cancel_tournament; writes no money itself. p_dry_run defaults TRUE so it is inert until a human flips it. No cron job is scheduled for it on purpose.';


--
-- TOC entry 6089 (class 1255 OID 15023055)
-- Name: fn_spin_repair_missing_multiplier(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_repair_missing_multiplier(p_lookback_mins integer DEFAULT 1440) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  -- MIRRORS server/src/config/spinSpec.ts SPIN_TIERS. Pinned by
  -- tests/config/spinNullMultiplierRepair.test.ts.
  v_tiers    numeric[] := ARRAY[2, 3, 4, 5, 10, 25, 50, 100];
  v_t        record;
  v_ratio    numeric;
  v_witness  numeric;
  v_use      numeric;
  v_source   text;
  v_overpaid numeric;
  v_hit      integer;
  v_fixed    integer := 0;
  v_flag     integer := 0;
  v_over     integer := 0;
  v_aged     integer := 0;
  v_raced    integer := 0;
BEGIN
  FOR v_t IN
    SELECT t.id, t.name, t.club_id, t.prize_pool, t.buy_in_amount,
           t.started_at, t.created_at, t.ended_at,
           d.multiplier AS witness, d.id AS witness_id,
           d.created_at AS witness_created_at,
           (COALESCE(t.started_at, t.created_at)
              <= now() - make_interval(mins => GREATEST(p_lookback_mins, 1))) AS outside_window
      FROM public.tournaments t
      LEFT JOIN LATERAL (
        SELECT l.id, l.multiplier, l.created_at
          FROM public.spin_reserve_ledger l
         WHERE l.tournament_id = t.id
           AND l.kind = 'jackpot_draw'
           AND COALESCE(l.multiplier, 0) > 0
         ORDER BY l.created_at ASC
         LIMIT 1) d ON true
     WHERE t.variant = 'spin'
       AND t.status IN ('RUNNING', 'COMPLETED')
       AND COALESCE(t.spin_multiplier, 0) <= 0
       -- A spin that never stamped a start is the spin MOST likely to have
       -- lost its draw. Gating on a bare started_at hid exactly the rows this
       -- function exists to repair, for four days.
       AND COALESCE(t.started_at, t.created_at) IS NOT NULL
       AND (
         COALESCE(t.started_at, t.created_at)
           > now() - make_interval(mins => GREATEST(p_lookback_mins, 1))
         -- AT ANY AGE when the reserve ledger already booked a draw: such a row
         -- is broken by definition and the window must not bound it.
         -- Self-draining, so it cannot become an unbounded scan.
         OR d.multiplier IS NOT NULL
       )
  LOOP
    v_witness := v_t.witness;
    IF v_t.outside_window THEN
      v_aged := v_aged + 1;
    END IF;

    v_ratio := NULL;
    IF COALESCE(v_t.buy_in_amount, 0) > 0 AND COALESCE(v_t.prize_pool, 0) > 0 THEN
      v_ratio := round(v_t.prize_pool / v_t.buy_in_amount, 4);
    END IF;

    -- Preserve booking-first selection. A reserve row records a booked
    -- multiplier; it can be written after play using an earlier reconstruction.
    -- Neither this row nor a pool ratio establishes the original random draw.
    IF v_witness IS NOT NULL AND v_witness = ANY (v_tiers) THEN
      v_use := v_witness; v_source := 'spin_reserve_ledger.jackpot_draw';
    ELSIF v_ratio IS NOT NULL AND v_ratio = ANY (v_tiers) THEN
      v_use := v_ratio;   v_source := 'prize_pool / buy_in_amount';
    ELSE
      v_use := NULL;      v_source := NULL;
    END IF;

    IF v_use IS NOT NULL THEN
      UPDATE public.tournaments
         SET spin_multiplier  = v_use,
             is_premium_spin  = (v_use >= 100)
       WHERE id = v_t.id
         AND COALESCE(spin_multiplier, 0) <= 0;
      -- A GUARDED UPDATE THAT MATCHES NOTHING IS NOT A REPAIR. Two crons drive
      -- this function under different advisory locks, so the row can be stamped
      -- between the SELECT and here. Counting that as a fix - and filing an
      -- alert for it - is a lie about work that another pass did.
      GET DIAGNOSTICS v_hit = ROW_COUNT;
      IF v_hit = 0 THEN
        v_raced := v_raced + 1;
        CONTINUE;
      END IF;
      v_fixed := v_fixed + 1;

      -- Keep the legacy arithmetic and field name for compatibility. This is
      -- recorded pool minus buy-in times the selected multiplier. No wallet
      -- or immutable RNG receipt is read here; payment and RNG remain unknown.
      v_overpaid := round(COALESCE(v_t.prize_pool, 0) - (v_use * COALESCE(v_t.buy_in_amount, 0)), 2);
      IF v_overpaid > 0 THEN
        v_over := v_over + 1;
      END IF;

      INSERT INTO public.financial_alerts (severity, source, message, context)
      VALUES (CASE WHEN v_overpaid > 0 THEN 'warning' ELSE 'info' END,
              'fn_spin_repair_missing_multiplier',
              CASE WHEN v_source = 'spin_reserve_ledger.jackpot_draw'
                   THEN 'Spin multiplier restored from a recorded reserve booking'
                   ELSE 'Spin multiplier reconstructed from the recorded prize-pool/buy-in ratio'
              END
              || '; original RNG not established by this repair'
              || CASE WHEN v_overpaid > 0
                      THEN '; recorded pool exceeds the selected multiplier amount by '
                           || v_overpaid || ' (payment not verified; no clawback)'
                      ELSE '' END
              || ': ' || COALESCE(v_t.name, v_t.id::text),
              jsonb_build_object('tournament_id', v_t.id, 'club_id', v_t.club_id,
                                 'buy_in', v_t.buy_in_amount, 'prize_pool', v_t.prize_pool,
                                 'reconstructed_multiplier', v_use,
                                 'reconstructed_from', v_source,
                                 'ledger_witness_multiplier', v_witness,
                                 'pool_ratio', v_ratio,
                                 'paid_over_drawn', v_overpaid,
                                 'clawed_back', false,
                                 'evidence_version', 1,
                                 'rng_evidence', 'not_established_by_this_repair',
                                 'payment_evidence', 'not_established_by_this_repair',
                                 'amount_basis', 'recorded_pool_minus_buy_in_times_selected_multiplier',
                                 'pool_minus_selected_multiplier_amount', v_overpaid,
                                 'reserve_booking_id', v_t.witness_id,
                                 'reserve_booking_created_at', v_t.witness_created_at,
                                 'reserve_booking_used', v_source = 'spin_reserve_ledger.jackpot_draw',
                                 'reserve_booking_timing', CASE
                                   WHEN v_t.witness_id IS NULL THEN 'not_observed'
                                   WHEN v_t.ended_at IS NOT NULL
                                     AND v_t.witness_created_at > v_t.ended_at
                                     THEN 'after_recorded_end'
                                   WHEN v_t.started_at IS NOT NULL
                                     AND v_t.witness_created_at > v_t.started_at
                                     THEN 'after_recorded_start'
                                   WHEN v_t.started_at IS NOT NULL
                                     THEN 'at_or_before_recorded_start'
                                   ELSE 'game_time_unknown' END,
                                 'ended_at', v_t.ended_at,
                                 'outside_lookback_window', v_t.outside_window,
                                 'started_at', v_t.started_at,
                                 'created_at', v_t.created_at));
    ELSE
      v_flag := v_flag + 1;
      INSERT INTO public.financial_alerts (severity, source, message, context)
      SELECT 'critical', 'fn_spin_repair_missing_multiplier',
             'Spin ran without a draw and the multiplier cannot be reconstructed: '
               || COALESCE(v_t.name, v_t.id::text),
             jsonb_build_object('tournament_id', v_t.id, 'club_id', v_t.club_id,
                                'buy_in', v_t.buy_in_amount, 'prize_pool', v_t.prize_pool,
                                'implied_ratio', v_ratio,
                                'ledger_witness_multiplier', v_witness,
                                'started_at', v_t.started_at, 'created_at', v_t.created_at,
                                'detail', 'needs a human decision; no multiplier was invented')
       WHERE NOT EXISTS (
         SELECT 1 FROM public.financial_alerts
          WHERE source = 'fn_spin_repair_missing_multiplier'
            AND resolved IS NOT TRUE
            AND context->>'tournament_id' = v_t.id::text);
    END IF;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'repaired', v_fixed,
                            'unreconstructable', v_flag,
                            'paid_over_drawn_count', v_over,
                            'repaired_outside_window', v_aged,
                            'lost_the_race', v_raced,
                            'lookback_mins', p_lookback_mins);
END;
$$;


ALTER FUNCTION public.fn_spin_repair_missing_multiplier(p_lookback_mins integer) OWNER TO postgres;

--
-- TOC entry 49009 (class 0 OID 0)
-- Dependencies: 6089
-- Name: FUNCTION fn_spin_repair_missing_multiplier(p_lookback_mins integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_repair_missing_multiplier(p_lookback_mins integer) IS 'Restores spin_multiplier on a spin that completed without stamping its draw. Reads the jackpot_draw row in spin_reserve_ledger first (the witness to the draw) and falls back to prize_pool/buy_in only when there is none. A spin with a booked draw and no stamp is in scope at ANY age - the lookback only bounds the ratio fallback. Never claws back a prize already paid.';


