--
-- TOC entry 8302 (class 1255 OID 16625358)
-- Name: fn_spin_unpaid_check(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_unpaid_check(p_since_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_since       timestamptz := now() - make_interval(days => GREATEST(COALESCE(p_since_days, 30), 1));
  v_unpaid      integer := 0;
  v_short       numeric := 0;
  v_over        integer := 0;
  v_over_amt    numeric := 0;
  v_nobody      integer := 0;
  v_ids         uuid[] := ARRAY[]::uuid[];
  v_shape       text;
  v_unranked    bigint;
  v_alerts      integer := 0;
  v_row         record;
BEGIN
  /* ONE READ OF THE VIEW, NOT TWO (2026-10-03). v_spin_unpaid_settlements
     aggregates spin_reserve_ledger, every prize/refund credit in
     wallet_transactions and - when a caller asks for seat_shape or
     unranked_seats - every tournament_players row, before the window can
     apply. The counters and the alert loop each read it whole, the loop with
     the seat aggregate; the job ran up to 117 s and was cancelled at 120 s in
     3 of 6 runs. Now one pass without the seat columns (the planner drops
     that join) yields every counter, the worst-first id list and the alert
     candidates, and the seat columns are read per alerted tournament, where
     tournament_id = $1 is pushed into every aggregate of the view. Same rows,
     same counters, same alerts, same dedupe. */
  FOR v_row IN
    SELECT v.tournament_id, v.club_id, v.name, v.prize_drawn, v.prize_credited,
           v.chips_short, v.verdict, v.buy_in_amount, v.spin_multiplier, v.drawn_at
      FROM public.v_spin_unpaid_settlements v
     WHERE COALESCE(v.drawn_at, v.started_at) >= v_since
     ORDER BY v.chips_short DESC
  LOOP
    IF v_row.verdict = 'nobody_paid' THEN v_nobody := v_nobody + 1; END IF;
    IF v_row.chips_short < 0 THEN
      v_over := v_over + 1;
      v_over_amt := v_over_amt - v_row.chips_short;
    END IF;
    CONTINUE WHEN v_row.chips_short IS NULL OR v_row.chips_short <= 0;
    v_unpaid := v_unpaid + 1;
    v_short := v_short + v_row.chips_short;
    v_ids := v_ids || v_row.tournament_id;

    SELECT s.seat_shape, s.unranked_seats INTO v_shape, v_unranked
      FROM public.v_spin_unpaid_settlements s
     WHERE s.tournament_id = v_row.tournament_id;

    -- One alert per offending tournament, never a duplicate while unresolved.
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT 'critical', 'fn_spin_unpaid_check',
           format('Spin drew %s from the reserve and credited %s to players: %s',
                  v_row.prize_drawn, v_row.prize_credited,
                  COALESCE(v_row.name, v_row.tournament_id::text)),
           jsonb_build_object('tournament_id', v_row.tournament_id,
                              'club_id',       v_row.club_id,
                              'prize_drawn',   v_row.prize_drawn,
                              'prize_credited',v_row.prize_credited,
                              'chips_short',   v_row.chips_short,
                              'verdict',       v_row.verdict,
                              'seat_shape',    v_shape,
                              'unranked_seats',v_unranked,
                              'buy_in',        v_row.buy_in_amount,
                              'multiplier',    v_row.spin_multiplier,
                              'drawn_at',      v_row.drawn_at,
                              'detail',        'no money was moved by this check; a human decides the payout')
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source = 'fn_spin_unpaid_check'
          AND fa.resolved IS NOT TRUE
          AND fa.context->>'tournament_id' = v_row.tournament_id::text);
    IF FOUND THEN v_alerts := v_alerts + 1; END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',                    true,
    'since_days',            GREATEST(COALESCE(p_since_days, 30), 1),
    'unpaid_count',          v_unpaid,
    'nobody_paid_count',     v_nobody,
    'chips_at_risk',         round(v_short, 2),
    'over_paid_count',       v_over,
    'chips_over_paid',       round(v_over_amt, 2),
    'alerts_raised',         v_alerts,
    'tournament_ids',        to_jsonb(v_ids));
END;
$_$;


