--
-- TOC entry 4492 (class 1255 OID 18222920)
-- Name: fn_spin_unpaid_settlements(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_spin_unpaid_settlements(p_since_hours integer DEFAULT 6) RETURNS TABLE(tournament_id uuid, chips_short numeric, verdict text, seats_at_first bigint, ended_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with candidates as (
    /* Cheap, indexed, and status-filtered BEFORE any per-row lookup. */
    select t.id, t.status, t.ended_at, t.buy_in_amount, t.spin_multiplier
    from public.tournaments t
    where t.variant = 'spin'
      and t.created_at > now() - (greatest(p_since_hours, 1) || ' hours')::interval
      and t.status not in ('RUNNING', 'REGISTERING')
  ),
  money as (
    /* One ledger lookup and one wallet lookup per candidate, both index-only. */
    select
      c.*,
      d.prize_drawn,
      d.drawn_at,
      coalesce(p.prize_credited, 0) as prize_credited
    from candidates c
    cross join lateral (
      select sum(-l.amount) as prize_drawn, max(l.created_at) as drawn_at
      from public.spin_reserve_ledger l
      where l.tournament_id = c.id and l.kind = 'jackpot_draw'
    ) d
    left join lateral (
      select sum(w.amount) as prize_credited
      from public.wallet_transactions w
      where w.related_entity_id = c.id and w.type = 'credit' and w.category = 'prize'
    ) p on true
    where d.prize_drawn is not null
  ),
  shortfall as (
    /* Everything that decides "is money missing" happens here, so the seat
       shape - the most expensive lookup of the three - is only paid for the
       handful of spins that are actually short. */
    select m.*, round(m.prize_drawn - m.prize_credited, 2) as short
    from money m
    where round(m.prize_drawn - m.prize_credited, 2) <> 0
      and (
        (m.status in ('COMPLETED', 'CANCELLED', 'CANCELED')
          and coalesce(m.ended_at, m.drawn_at) < now() - interval '10 minutes')
        or m.drawn_at < now() - interval '2 hours'
      )
      and not (
        m.prize_credited > m.prize_drawn
        and m.spin_multiplier is not null
        and m.prize_credited = round(m.buy_in_amount * m.spin_multiplier, 2)
      )
  )
  select
    f.id,
    f.short,
    case
      when f.prize_credited = 0 then 'nobody_paid'
      when f.prize_credited < f.prize_drawn then 'under_paid'
      else 'over_paid'
    end,
    s.seats_at_first,
    f.ended_at
  from shortfall f
  cross join lateral (
    select
      count(*) filter (where tp.position is null) as unranked_seats,
      count(*) filter (where tp.position = 1)     as seats_at_first
    from public.tournament_players tp
    where tp.tournament_id = f.id
  ) s
  where s.unranked_seats = 0
    and s.seats_at_first = 1;
$$;


ALTER FUNCTION public.fn_spin_unpaid_settlements(p_since_hours integer) OWNER TO postgres;

--
-- TOC entry 49034 (class 0 OID 0)
-- Dependencies: 4492
-- Name: FUNCTION fn_spin_unpaid_settlements(p_since_hours integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_spin_unpaid_settlements(p_since_hours integer) IS 'The ranked_but_unpaid rows of v_spin_unpaid_settlements, bounded to spins created in the last p_since_hours and staged so the seat lookup is paid only for spins that are actually short. Same predicate, same verdicts; the view stays the unbounded auditor for humans, this is what a repair running every ten minutes under an 8s statement timeout can afford.';


--
-- TOC entry 5565 (class 1255 OID 30785331)
-- Name: fn_sponsor_ad_submit(text, text, text, text, text, timestamp with time zone, integer, integer, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sponsor_ad_submit(p_slot text, p_headline text, p_image_url text, p_poster_url text, p_external_url text, p_starts_at timestamp with time zone, p_days integer, p_goal_impressions integer DEFAULT NULL::integer, p_pacing text DEFAULT 'even'::text, p_countries text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_user  uuid := auth.uid();
  v_adv   public.ad_advertiser%rowtype;
  v_rate  public.ad_rate_card%rowtype;
  v_id    uuid := gen_random_uuid();
  v_start timestamptz;
  v_end   timestamptz;
  v_folder text;
  v_quote integer;
  v_countries text[];
begin
  if v_user is null then
    return jsonb_build_object('ok', false, 'reason', 'not_signed_in');
  end if;
  select * into v_adv from public.ad_advertiser
   where kind = 'sponsor' and self_serve and owner_user_id = v_user;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no_advertiser');
  end if;
  if v_adv.status <> 'active' then
    return jsonb_build_object('ok', false, 'reason', 'advertiser_suspended');
  end if;
  if p_headline is null or length(btrim(p_headline)) not between 1 and 120 then
    return jsonb_build_object('ok', false, 'reason', 'bad_headline');
  end if;
  select * into v_rate from public.ad_rate_card where slot = p_slot;
  if not found or p_slot = 'table_between_hands' then
    return jsonb_build_object('ok', false, 'reason', 'unknown_slot');
  end if;
  if v_rate.sponsor_cents_per_day <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'surface_not_for_sale');
  end if;
  if p_days is null or p_days < 1 or p_days > 365 then
    return jsonb_build_object('ok', false, 'reason', 'bad_days');
  end if;
  v_folder := '/ad-creatives/sponsor/' || v_adv.id::text || '/';
  if p_image_url is null or p_image_url not like (v_folder || '%') then
    return jsonb_build_object('ok', false, 'reason', 'creative_not_in_your_folder');
  end if;
  if p_poster_url is null or p_poster_url not like (v_folder || '%') then
    return jsonb_build_object('ok', false, 'reason', 'poster_not_in_your_folder');
  end if;
  if p_external_url is null or p_external_url !~ '^https://[a-zA-Z0-9]'
     or length(p_external_url) not between 12 and 500
     or position(' ' in p_external_url) > 0
     or position(E'\n' in p_external_url) > 0 then
    return jsonb_build_object('ok', false, 'reason', 'destination_must_be_https');
  end if;
  if p_goal_impressions is not null and p_goal_impressions <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'bad_goal');
  end if;
  if p_pacing not in ('even', 'asap') then
    return jsonb_build_object('ok', false, 'reason', 'bad_pacing');
  end if;
  v_countries := public.fn_ad_countries_clean(p_countries);
  if v_countries is null and p_countries is not null and cardinality(p_countries) > 0 then
    return jsonb_build_object('ok', false, 'reason', 'bad_countries');
  end if;
  v_start := greatest(coalesce(p_starts_at, now()), now() - interval '10 minutes');
  v_end   := v_start + make_interval(days => p_days);
  v_quote := v_rate.sponsor_cents_per_day * p_days;
  insert into public.ad_campaign
    (id, advertiser_id, club_id, name, slot, status, scope, priority,
     starts_at, ends_at, days, image_url, poster_url, target_url, headline,
     diamonds_charged, submitted_by, external_url, pacing, goal_impressions, quoted_cents, countries)
  values
    (v_id, v_adv.id, null, left(v_adv.name, 80), p_slot, 'submitted', 'platform', 90,
     v_start, v_end, p_days, p_image_url, p_poster_url, '/', btrim(p_headline),
     0, v_user, p_external_url, p_pacing, p_goal_impressions, v_quote, v_countries);
  return jsonb_build_object('ok', true, 'campaign_id', v_id, 'advertiser_id', v_adv.id,
                            'starts_at', v_start, 'ends_at', v_end, 'quoted_cents', v_quote,
                            'countries', v_countries);
end;
$$;


ALTER FUNCTION public.fn_sponsor_ad_submit(p_slot text, p_headline text, p_image_url text, p_poster_url text, p_external_url text, p_starts_at timestamp with time zone, p_days integer, p_goal_impressions integer, p_pacing text, p_countries text[]) OWNER TO postgres;

--
-- TOC entry 9181 (class 1255 OID 30774266)
-- Name: fn_sponsor_advertiser_handoff(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sponsor_advertiser_handoff(p_advertiser_id uuid, p_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_adv   public.ad_advertiser%rowtype;
  v_owner uuid;
  v_email text := lower(btrim(coalesce(p_email, '')));
begin
  if not (coalesce(auth.role(), '') = 'service_role' or public.fn_is_platform_admin()) then
    return jsonb_build_object('ok', false, 'reason', 'not_platform_admin');
  end if;
  if v_email = '' or position('@' in v_email) = 0 then
    return jsonb_build_object('ok', false, 'reason', 'bad_email');
  end if;
  select * into v_adv from public.ad_advertiser where id = p_advertiser_id for update;
  if not found or v_adv.kind <> 'sponsor' then
    return jsonb_build_object('ok', false, 'reason', 'not_a_sponsor');
  end if;
  if v_adv.self_serve then
    return jsonb_build_object('ok', false, 'reason', 'already_handed_off');
  end if;
  select u.id into v_owner from auth.users u where lower(u.email) = v_email limit 1;
  if v_owner is null then
    return jsonb_build_object('ok', false, 'reason', 'no_account_with_that_email');
  end if;
  if exists (select 1 from public.ad_advertiser a
              where a.kind = 'sponsor' and a.self_serve and a.owner_user_id = v_owner) then
    return jsonb_build_object('ok', false, 'reason', 'account_already_has_a_sponsor');
  end if;
  update public.ad_advertiser
     set owner_user_id = v_owner,
         self_serve    = true,
         contact_email = coalesce(nullif(btrim(contact_email), ''), v_email),
         updated_at    = now()
   where id = p_advertiser_id;
  return jsonb_build_object('ok', true, 'advertiser_id', p_advertiser_id, 'owner_user_id', v_owner);
end;
$$;


ALTER FUNCTION public.fn_sponsor_advertiser_handoff(p_advertiser_id uuid, p_email text) OWNER TO postgres;

--
-- TOC entry 4523 (class 1255 OID 30774267)
-- Name: fn_sponsor_advertiser_list(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sponsor_advertiser_list() RETURNS TABLE(id uuid, name text, contact_email text, status text, self_serve boolean, owner_email text, flights bigint, unpaid_cents bigint, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select a.id, a.name, a.contact_email, a.status, a.self_serve,
         case when a.self_serve then u.email::text else null end as owner_email,
         (select count(*) from public.ad_campaign c where c.advertiser_id = a.id) as flights,
         (select coalesce(sum(c.quoted_cents), 0)
            from public.ad_campaign c
           where c.advertiser_id = a.id and c.status = 'approved' and c.paid_at is null) as unpaid_cents,
         a.created_at
    from public.ad_advertiser a
    left join auth.users u on u.id = a.owner_user_id
   where a.kind = 'sponsor'
     and (coalesce(auth.role(), '') = 'service_role' or public.fn_is_platform_admin())
   order by a.created_at desc
   limit 200;
$$;


ALTER FUNCTION public.fn_sponsor_advertiser_list() OWNER TO postgres;

