--
-- TOC entry 5156 (class 1255 OID 30287749)
-- Name: fn_sponsor_advertiser_upsert(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sponsor_advertiser_upsert(p_name text, p_contact_email text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  v_id   uuid;
  v_status text;
begin
  if v_user is null then
    return jsonb_build_object('ok', false, 'reason', 'not_signed_in');
  end if;
  if p_name is null or length(btrim(p_name)) not between 1 and 80 then
    return jsonb_build_object('ok', false, 'reason', 'bad_advertiser_name');
  end if;
  if p_contact_email is not null and (length(p_contact_email) > 200 or position('@' in p_contact_email) = 0) then
    return jsonb_build_object('ok', false, 'reason', 'bad_contact_email');
  end if;
  insert into public.ad_advertiser (kind, name, club_id, owner_user_id, contact_email, self_serve)
  values ('sponsor', btrim(p_name), null, v_user, p_contact_email, true)
  on conflict (owner_user_id) where kind = 'sponsor' and self_serve
  do update set name = excluded.name,
                contact_email = coalesce(excluded.contact_email, public.ad_advertiser.contact_email),
                updated_at = now()
  returning id, status into v_id, v_status;
  return jsonb_build_object('ok', true, 'advertiser_id', v_id, 'status', v_status);
end;
$$;


ALTER FUNCTION public.fn_sponsor_advertiser_upsert(p_name text, p_contact_email text) OWNER TO postgres;

--
-- TOC entry 4444 (class 1255 OID 30774250)
-- Name: fn_sponsor_campaign_bill(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sponsor_campaign_bill(p_campaign_id uuid, p_mark text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  v_c    public.ad_campaign%rowtype;
begin
  if not (coalesce(auth.role(), '') = 'service_role' or public.fn_is_platform_admin()) then
    return jsonb_build_object('ok', false, 'reason', 'not_platform_admin');
  end if;
  if p_mark not in ('invoiced', 'paid', 'none') then
    return jsonb_build_object('ok', false, 'reason', 'bad_mark');
  end if;
  select * into v_c from public.ad_campaign where id = p_campaign_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no_such_campaign');
  end if;
  if v_c.club_id is not null or v_c.quoted_cents is null then
    return jsonb_build_object('ok', false, 'reason', 'not_a_sponsor_flight');
  end if;
  if v_c.status <> 'approved' then
    return jsonb_build_object('ok', false, 'reason', 'not_approved');
  end if;
  update public.ad_campaign
     set invoiced_at = case p_mark
                         when 'none' then null
                         else coalesce(invoiced_at, now())
                       end,
         paid_at     = case p_mark
                         when 'paid' then coalesce(paid_at, now())
                         else null
                       end,
         billed_by   = v_user,
         updated_at  = now()
   where id = p_campaign_id;
  select * into v_c from public.ad_campaign where id = p_campaign_id;
  return jsonb_build_object('ok', true, 'campaign_id', v_c.id,
                            'invoiced_at', v_c.invoiced_at, 'paid_at', v_c.paid_at,
                            'quoted_cents', v_c.quoted_cents);
end;
$$;


ALTER FUNCTION public.fn_sponsor_campaign_bill(p_campaign_id uuid, p_mark text) OWNER TO postgres;

