CREATE FUNCTION public.fn_sponsor_campaign_create(p_advertiser_name text, p_headline text, p_slot text, p_image_url text, p_external_url text, p_starts_at timestamp with time zone, p_days integer, p_contact_email text DEFAULT NULL::text, p_goal_impressions integer DEFAULT NULL::integer, p_pacing text DEFAULT 'even'::text, p_poster_url text DEFAULT NULL::text, p_countries text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  v_adv  uuid;
  v_id   uuid := gen_random_uuid();
  v_end  timestamptz;
  v_start timestamptz;
  v_quote integer;
  v_countries text[];
begin
  if not (coalesce(auth.role(), '') = 'service_role' or public.fn_is_platform_admin()) then
    return jsonb_build_object('ok', false, 'reason', 'not_platform_admin');
  end if;
  if p_advertiser_name is null or length(btrim(p_advertiser_name)) not between 1 and 80 then
    return jsonb_build_object('ok', false, 'reason', 'bad_advertiser_name');
  end if;
  if p_headline is null or length(btrim(p_headline)) not between 1 and 120 then
    return jsonb_build_object('ok', false, 'reason', 'bad_headline');
  end if;
  select sponsor_cents_per_day into v_quote from public.ad_rate_card where slot = p_slot;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'unknown_slot');
  end if;
  if p_days is null or p_days < 1 or p_days > 365 then
    return jsonb_build_object('ok', false, 'reason', 'bad_days');
  end if;
  if p_image_url is null or p_image_url not like '/%' or p_image_url like '//%' then
    return jsonb_build_object('ok', false, 'reason', 'creative_not_same_origin');
  end if;
  if p_poster_url is not null and (p_poster_url not like '/%' or p_poster_url like '//%') then
    return jsonb_build_object('ok', false, 'reason', 'poster_not_same_origin');
  end if;
  if p_external_url is null or p_external_url !~ '^https://[a-zA-Z0-9]'
     or length(p_external_url) not between 12 and 500
     or position(' ' in p_external_url) > 0
     or position(E'\n' in p_external_url) > 0 then
    return jsonb_build_object('ok', false, 'reason', 'destination_must_be_https');
  end if;
  if p_pacing not in ('even', 'asap') then
    return jsonb_build_object('ok', false, 'reason', 'bad_pacing');
  end if;
  v_countries := public.fn_ad_countries_clean(p_countries);
  if v_countries is null and p_countries is not null and cardinality(p_countries) > 0 then
    return jsonb_build_object('ok', false, 'reason', 'bad_countries');
  end if;
  v_start := greatest(coalesce(p_starts_at, now()), now() - interval '10 minutes');
  v_end   := v_start + make_interval(days => p_days);
  v_quote := v_quote * p_days;
  insert into public.ad_advertiser (kind, name, club_id, owner_user_id, contact_email)
  values ('sponsor', left(btrim(p_advertiser_name), 80), null, v_user, p_contact_email)
  returning id into v_adv;
  insert into public.ad_campaign
    (id, advertiser_id, club_id, name, slot, status, scope, priority,
     starts_at, ends_at, days, image_url, poster_url, target_url, headline,
     diamonds_charged, submitted_by, external_url, pacing, goal_impressions, quoted_cents, countries)
  values
    (v_id, v_adv, null, left(btrim(p_advertiser_name), 80), p_slot, 'submitted', 'platform', 90,
     v_start, v_end, p_days, p_image_url, p_poster_url,
     '/', btrim(p_headline),
     0, v_user, p_external_url, p_pacing, p_goal_impressions, v_quote, v_countries);
  return jsonb_build_object('ok', true, 'campaign_id', v_id, 'advertiser_id', v_adv,
                            'starts_at', v_start, 'ends_at', v_end, 'quoted_cents', v_quote,
                            'countries', v_countries);
end;
$$;


ALTER FUNCTION public.fn_sponsor_campaign_create(p_advertiser_name text, p_headline text, p_slot text, p_image_url text, p_external_url text, p_starts_at timestamp with time zone, p_days integer, p_contact_email text, p_goal_impressions integer, p_pacing text, p_poster_url text, p_countries text[]) OWNER TO postgres;

--
-- TOC entry 5025 (class 1255 OID 30785339)
-- Name: fn_sponsor_campaign_list(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sponsor_campaign_list() RETURNS TABLE(id uuid, club_id uuid, club_name text, name text, slot text, status text, display_status text, scope text, starts_at timestamp with time zone, ends_at timestamp with time zone, days integer, image_url text, poster_url text, target_url text, external_url text, headline text, pacing text, goal_impressions integer, diamonds_charged integer, diamonds_refunded integer, submitted_by uuid, reviewed_at timestamp with time zone, review_note text, created_at timestamp with time zone, impressions bigint, viewable bigint, clicks bigint, viewers bigint, quoted_cents integer, invoiced_at timestamp with time zone, paid_at timestamp with time zone, countries text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select c.id, c.club_id, adv.name as club_name, c.name, c.slot, c.status,
         case
           when c.status <> 'approved' then c.status
           when now() < c.starts_at then 'scheduled'
           when now() >= c.ends_at  then 'finished'
           else 'live'
         end as display_status,
         c.scope, c.starts_at, c.ends_at, c.days,
         c.image_url, c.poster_url, c.target_url, c.external_url,
         c.headline, c.pacing, c.goal_impressions,
         c.diamonds_charged, c.diamonds_refunded,
         c.submitted_by, c.reviewed_at, c.review_note, c.created_at,
         coalesce(s.impressions, 0), coalesce(s.viewable, 0), coalesce(s.clicks, 0), coalesce(s.viewers, 0),
         c.quoted_cents, c.invoiced_at, c.paid_at, c.countries
    from public.ad_campaign c
    join public.ad_advertiser adv on adv.id = c.advertiser_id
    left join lateral (
      select count(*) filter (where e.event_type = 'impression') as impressions,
             count(*) filter (where e.event_type = 'viewable')   as viewable,
             count(*) filter (where e.event_type = 'click')      as clicks,
             count(distinct e.user_id) filter (where e.event_type = 'impression') as viewers
        from public.ad_event e
       where e.ad_id = c.ad_id
    ) s on true
   where adv.kind = 'sponsor' and adv.self_serve and adv.owner_user_id = auth.uid()
   order by c.created_at desc
   limit 200;
$$;


ALTER FUNCTION public.fn_sponsor_campaign_list() OWNER TO postgres;

--
-- TOC entry 8156 (class 1255 OID 11520488)
-- Name: fn_staff_pin_taken(text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_staff_pin_taken(p_venue_id text, p_pin text, p_exclude_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM public.commander_staff s
     WHERE s.venue_id::text = p_venue_id
       AND (p_exclude_id IS NULL OR s.id <> p_exclude_id)
       AND p_pin IS NOT NULL
       AND (
            (s.pin_hash IS NOT NULL AND s.pin_hash = extensions.crypt(p_pin, s.pin_hash))
         OR (s.pin_hash IS NULL     AND s.pin_code = p_pin)
       )
  );
$$;


ALTER FUNCTION public.fn_staff_pin_taken(p_venue_id text, p_pin text, p_exclude_id uuid) OWNER TO postgres;

--
-- TOC entry 5661 (class 1255 OID 24465539)
-- Name: fn_stage_a_bridge_legacy_capacity_receipt(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_stage_a_bridge_legacy_capacity_receipt(p_table_id uuid, p_tournament_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_headers jsonb;
  v_claims jsonb;
  v_request_role text;
  v_actor_marker text;
  v_method text;
  v_path text;
  v_wake_id bigint;
  v_stale_seconds constant integer := 30;
BEGIN
  IF p_table_id IS NULL OR p_tournament_id IS NULL THEN
    RETURN false;
  END IF;

  BEGIN
    v_headers := COALESCE(
      NULLIF(current_setting('request.headers', true), '')::jsonb,
      '{}'::jsonb
    );
    v_claims := COALESCE(
      NULLIF(current_setting('request.jwt.claims', true), '')::jsonb,
      '{}'::jsonb
    );
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION
      'DATA_ACTOR_INVALID: malformed legacy capacity request context'
      USING ERRCODE = '22023';
  END;

  v_request_role := btrim(COALESCE(auth.role(), ''));
  v_actor_marker := btrim(
    COALESCE(current_setting('app.smarter_data_actor', true), '')
  );
  v_method := upper(
    btrim(COALESCE(current_setting('request.method', true), ''))
  );
  v_path := lower(
    btrim(COALESCE(current_setting('request.path', true), ''), '/')
  );
  IF left(v_path, 8) = 'rest/v1/' THEN
    v_path := substr(v_path, 9);
  END IF;

  IF v_request_role <> 'service_role'
     OR btrim(COALESCE(v_claims ->> 'role', '')) <> 'service_role'
     OR btrim(COALESCE(v_headers ->> 'x-smarter-data-actor', '')) <> ''
     OR btrim(COALESCE(v_headers ->> 'x-smarter-data-protocol', '')) <> ''
     OR btrim(COALESCE(v_headers ->> 'x-smarter-tournament-id', '')) <> ''
     OR btrim(
          COALESCE(
            v_headers ->> 'x-smarter-tournament-lease-generation',
            ''
          )
        ) <> ''
     OR v_actor_marker NOT IN ('', 'legacy-unmarked')
     OR COALESCE(
          current_setting('app.smarter_manager_request_fenced', true),
          ''
        ) <> ''
     OR v_method <> 'POST'
     OR v_path <> 'tables' THEN
    RETURN false;
  END IF;

  /* This row lock is the rolling cutover handoff. Lease replacement and the
     Stage-B relation lock cannot cross the raw table INSERT transaction. */
  PERFORM 1
    FROM public.engine_tournament_leases l
   WHERE l.tournament_id = p_tournament_id
     AND l.protocol_version = 1
     AND l.heartbeat_at >=
         clock_timestamp() - make_interval(secs => v_stale_seconds)
   FOR SHARE;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  v_wake_id := public.fn_emit_tournament_manager_wake(
    p_tournament_id,
    'late_registration'
  );
  IF v_wake_id IS NULL THEN
    RETURN false;
  END IF;

  INSERT INTO public.tournament_capacity_table_receipts (
    table_id,
    tournament_id,
    manager_wake_id
  ) VALUES (
    p_table_id,
    p_tournament_id,
    v_wake_id
  );

  /* Match the canonical capacity function's level-triggered receipt rule:
     every still-unadmitted table points at the newest pending wake. */
  UPDATE public.tournament_capacity_table_receipts
     SET manager_wake_id = v_wake_id,
         updated_at = clock_timestamp()
   WHERE tournament_id = p_tournament_id
     AND manager_admitted_at IS NULL;

  RETURN true;
END;
$$;


ALTER FUNCTION public.fn_stage_a_bridge_legacy_capacity_receipt(p_table_id uuid, p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 9092 (class 1255 OID 34785507)
-- Name: fn_stamp_accounting_tournament_fee(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_stamp_accounting_tournament_fee(p_rake_record_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE r public.rake_records%ROWTYPE;t record;e record;tp record;item record;reserve_id uuid;
 manifest jsonb;contributors jsonb:='[]';game_union uuid;expected_entitlement text;
 expected_category text;uid uuid;reg uuid;count_rows int;cutoff timestamptz;legacy boolean:=false;
BEGIN
 SELECT * INTO r FROM public.rake_records WHERE id=p_rake_record_id FOR UPDATE;
 IF NOT FOUND OR NOT r.is_tournament OR r.rake_amount<=0 THEN
  RAISE EXCEPTION 'positive_chip_tournament_fee_required' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches WHERE rake_record_id=r.id) THEN
  IF EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches WHERE rake_record_id=r.id AND status='legacy_unverified') THEN
   RETURN jsonb_build_object('accounting_version',2,'status','legacy_unverified','rake_record_id',r.id,'payable',false);
  END IF;
  RETURN public.fn_capture_accounting_tournament_fee(r.id);
 END IF;
 SELECT starts_at INTO cutoff FROM public.accounting_tournament_fee_cutover WHERE singleton;
 IF r.created_at IS DISTINCT FROM transaction_timestamp() OR cutoff IS NULL OR r.created_at<cutoff THEN
  RAISE EXCEPTION 'tournament_fee_not_captured_by_original_producer' USING ERRCODE='55000'; END IF;
 SELECT id,club_id,union_id,is_private,tournament_type INTO t FROM public.tournaments WHERE id=r.tournament_id FOR SHARE;
 IF NOT FOUND OR public.fn_poker_diamond_tournament(r.tournament_id) THEN
  RAISE EXCEPTION 'chip_tournament_fee_required' USING ERRCODE='23514'; END IF;
 game_union:=CASE WHEN t.is_private THEN NULL ELSE t.union_id END;
 IF r.source='fn_spin_book_entry' THEN
  IF jsonb_typeof(r.player_contributions) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(r.player_contributions))<>3 THEN
   RAISE EXCEPTION 'spin_fee_exact_paid_contributors_required' USING ERRCODE='23514'; END IF;
  FOR item IN SELECT key::uuid player_id,value::numeric weight FROM jsonb_each_text(r.player_contributions) ORDER BY key LOOP
   SELECT * INTO tp FROM public.tournament_players WHERE tournament_id=r.tournament_id AND user_id=item.player_id;
   IF NOT FOUND OR tp.club_id IS NULL THEN RAISE EXCEPTION 'spin_fee_entry_club_missing' USING ERRCODE='23514'; END IF;
   SELECT count(*) INTO count_rows FROM public.tournament_refund_entitlements x
    WHERE x.tournament_id=r.tournament_id AND x.user_id=item.player_id AND x.entitlement_kind='wallet_charge'
     AND x.charge_category='tournament_buyin' AND x.created_at=tp.registered_at AND x.gross=item.weight;
   IF count_rows<>1 THEN RAISE EXCEPTION 'spin_fee_exact_charge_ambiguous' USING ERRCODE='23514'; END IF;
   SELECT * INTO e FROM public.tournament_refund_entitlements x
    WHERE x.tournament_id=r.tournament_id AND x.user_id=item.player_id AND x.entitlement_kind='wallet_charge'
     AND x.charge_category='tournament_buyin' AND x.created_at=tp.registered_at AND x.gross=item.weight;
   contributors:=contributors||jsonb_build_array(jsonb_build_object('player_id',e.user_id,'club_id',e.refund_wallet_club_id,
    'registration_id',tp.id,'charge_ledger_id',e.source_ledger_id,'entitlement_id',e.id,'charged_at',e.created_at,'weight',item.weight));
   legacy:=legacy OR e.created_at<cutoff;
  END LOOP;
  SELECT count(*) INTO count_rows FROM public.spin_reserve_ledger s WHERE s.tournament_id=r.tournament_id AND s.kind='contribution';
  IF count_rows<>1 THEN RAISE EXCEPTION 'spin_fee_exact_reserve_required' USING ERRCODE='23514'; END IF;
  SELECT id INTO reserve_id FROM public.spin_reserve_ledger s WHERE s.tournament_id=r.tournament_id AND s.kind='contribution';
 ELSE
  IF NOT COALESCE(r.metadata->>'user_id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$',false) THEN
   RAISE EXCEPTION 'tournament_fee_exact_player_required' USING ERRCODE='23514'; END IF;
  uid:=(r.metadata->>'user_id')::uuid;
  expected_entitlement:=CASE r.source WHEN 'fn_register_for_tournament' THEN 'wallet_charge'
   WHEN 'fn_register_horse_for_tournament' THEN 'wallet_charge' WHEN 'process_tournament_rebuy' THEN 'wallet_charge'
   WHEN 'fn_award_satellite_seat' THEN 'satellite_seat' WHEN 'fn_register_for_tournament_with_ticket' THEN 'tournament_ticket' END;
  expected_category:=CASE WHEN r.source='process_tournament_rebuy' THEN 'rebuy' ELSE 'tournament_buyin' END;
  IF expected_entitlement IS NULL THEN RAISE EXCEPTION 'tournament_fee_source_unsupported' USING ERRCODE='55000'; END IF;
  reg:=NULLIF(r.metadata->>'registration_id','')::uuid;
  IF reg IS NULL AND r.source='process_tournament_rebuy' THEN
   SELECT id INTO reg FROM public.tournament_players WHERE tournament_id=r.tournament_id AND user_id=uid;
  END IF;
  IF reg IS NULL THEN RAISE EXCEPTION 'tournament_fee_exact_registration_required' USING ERRCODE='23514'; END IF;
  SELECT count(*) INTO count_rows FROM public.tournament_refund_entitlements x
   WHERE x.tournament_id=r.tournament_id AND x.user_id=uid AND x.created_at=r.created_at AND x.refund_fee=r.rake_amount
    AND x.entitlement_kind=expected_entitlement
    AND (CASE WHEN expected_entitlement='wallet_charge' THEN x.charge_category=expected_category ELSE x.registration_id=reg END);
  IF count_rows<>1 THEN RAISE EXCEPTION 'tournament_fee_exact_charge_ambiguous' USING ERRCODE='23514'; END IF;
  SELECT * INTO e FROM public.tournament_refund_entitlements x
   WHERE x.tournament_id=r.tournament_id AND x.user_id=uid AND x.created_at=r.created_at AND x.refund_fee=r.rake_amount
    AND x.entitlement_kind=expected_entitlement
    AND (CASE WHEN expected_entitlement='wallet_charge' THEN x.charge_category=expected_category ELSE x.registration_id=reg END);
  contributors:=jsonb_build_array(jsonb_build_object('player_id',e.user_id,'club_id',e.refund_wallet_club_id,
   'registration_id',reg,'charge_ledger_id',e.source_ledger_id,'entitlement_id',e.id,'charged_at',e.created_at,'weight',r.rake_amount));
 END IF;
 IF legacy THEN
  INSERT INTO public.accounting_tournament_fee_batches(rake_record_id,tournament_id,source_fingerprint,rake_amount,status)
   VALUES(r.id,r.tournament_id,public.fn_accounting_tournament_fee_fingerprint(r),r.rake_amount,'legacy_unverified');
  RETURN jsonb_build_object('accounting_version',2,'status','legacy_unverified','rake_record_id',r.id,'payable',false);
 END IF;
 manifest:=jsonb_build_object('union_id',game_union,'game_type',lower(t.tournament_type),'contributors',contributors,'spin_reserve_id',reserve_id);
 -- Original tournament evidence may already be sealed by a satellite receipt.
 -- Capture its manifest on the accounting batch; never rewrite that raw row.
 BEGIN
  RETURN public.fn_capture_accounting_tournament_fee(r.id,manifest);
 EXCEPTION WHEN SQLSTATE '55000' THEN
  -- Missing observed agreement may not destroy a proved original fee charge.
  -- This subtransaction rolls back every contributor receipt before recording
  -- the entire batch as unavailable. No partial commission can become payable.
  IF SQLERRM NOT IN('accounting_terms_not_observed','accounting_terms_not_active') THEN RAISE; END IF;
  INSERT INTO public.accounting_tournament_fee_batches(rake_record_id,tournament_id,source_fingerprint,rake_amount,status,source_manifest)
   VALUES(r.id,r.tournament_id,public.fn_accounting_tournament_fee_fingerprint(r),r.rake_amount,'legacy_unverified',
    manifest||jsonb_build_object('capture_reason',SQLERRM));
  RETURN jsonb_build_object('accounting_version',2,'status','legacy_unverified','rake_record_id',r.id,'payable',false,'reason',SQLERRM);
 END;
END $_$;


ALTER FUNCTION public.fn_stamp_accounting_tournament_fee(p_rake_record_id uuid) OWNER TO postgres;

--
-- TOC entry 8767 (class 1255 OID 25592092)
-- Name: fn_stamp_active_seat_game_scope(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_stamp_active_seat_game_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.left_at IS NOT NULL THEN
    NEW.active_game_scope := NULL;
  ELSE
    SELECT t.seat_game_scope INTO NEW.active_game_scope FROM public.tables t WHERE t.id=NEW.table_id;
    IF NOT FOUND OR NEW.user_id IS NULL THEN
      RAISE EXCEPTION 'Active seat requires an existing table and player' USING ERRCODE='23514';
    END IF;
    IF NEW.active_game_scope IS NULL THEN
      -- A pre-migration empty table has no cached scope. Initialize only that
      -- parent, inside this admission transaction. Existing occupied tables
      -- never take this UPDATE path. Concurrent initialization is idempotent.
      UPDATE public.tables t SET seat_game_scope = CASE WHEN t.cluster_id IS NULL
        THEN 'table:'||t.id::text ELSE 'cluster:'||t.cluster_id::text END
      WHERE t.id=NEW.table_id AND t.seat_game_scope IS NULL;
      SELECT t.seat_game_scope INTO NEW.active_game_scope FROM public.tables t WHERE t.id=NEW.table_id;
      IF NEW.active_game_scope IS NULL THEN
        RAISE EXCEPTION 'Active seat parent scope initialization failed' USING ERRCODE='23514';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_stamp_active_seat_game_scope() OWNER TO postgres;

