--
-- TOC entry 8135 (class 1255 OID 198172153)
-- Name: fn_sync_club_staff_notice_group(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_club_staff_notice_group(p_club uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_conversation uuid; v_name text;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('club-staff-notice-group:'||p_club::text,0));
 SELECT name INTO v_name FROM public.clubs WHERE id=p_club;
 IF NOT FOUND THEN
  DELETE FROM public.social_conversation_participants WHERE conversation_id IN(SELECT conversation_id FROM public.club_messenger_staff_notice_groups WHERE club_id=p_club);
  RETURN;
 END IF;
 SELECT conversation_id INTO v_conversation FROM public.club_messenger_staff_notice_groups WHERE club_id=p_club;
 IF v_conversation IS NULL AND EXISTS(SELECT 1 FROM public.club_members m WHERE m.club_id=p_club AND public.fn_club_messenger_staff_role(p_club,m.user_id) IS NOT NULL) THEN
  INSERT INTO public.social_conversations(is_group,is_request,group_name) VALUES(true,false,v_name||' - Notice Board') RETURNING id INTO v_conversation;
  INSERT INTO public.club_messenger_staff_notice_groups(club_id,conversation_id) VALUES(p_club,v_conversation);
 END IF;
 IF v_conversation IS NULL THEN RETURN; END IF;
 DELETE FROM public.social_conversation_participants p WHERE p.conversation_id=v_conversation AND public.fn_club_messenger_staff_role(p_club,p.user_id) IS NULL;
 INSERT INTO public.social_conversation_participants(conversation_id,user_id)
 SELECT v_conversation,m.user_id FROM public.club_members m WHERE m.club_id=p_club AND public.fn_club_messenger_staff_role(p_club,m.user_id) IS NOT NULL
 AND NOT EXISTS(SELECT 1 FROM public.social_conversation_participants p WHERE p.conversation_id=v_conversation AND p.user_id=m.user_id);
END $$;


ALTER FUNCTION public.fn_sync_club_staff_notice_group(p_club uuid) OWNER TO postgres;

--
-- TOC entry 9435 (class 1255 OID 14330125)
-- Name: fn_sync_club_table_counts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_club_table_counts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_clubs uuid[];
  v_unions uuid[];
BEGIN
  -- Both sides, so a table MOVING between clubs or unions fixes the club it
  -- left as well as the one it joined.
  v_clubs := array_remove(ARRAY[
    CASE WHEN TG_OP <> 'DELETE' THEN NEW.club_id END,
    CASE WHEN TG_OP <> 'INSERT' THEN OLD.club_id END
  ], NULL);
  v_unions := array_remove(ARRAY[
    CASE WHEN TG_OP <> 'DELETE' THEN NEW.union_id END,
    CASE WHEN TG_OP <> 'INSERT' THEN OLD.union_id END
  ], NULL);

  -- A COUNT THAT HAS NOT CHANGED IS NOT A WRITE (2026-09-29).
  -- This fires on every status change of every table, and the engine cycles a
  -- live table between 'waiting' and 'running' all day. fn_live_table_count
  -- counts tables whose status is NOT IN ('closed','deleted'), so both of those
  -- statuses count and the total does not move: the UPDATE assigned the value
  -- the row already held. Measured 2026-09-29 04:10 UTC, all five clubs had
  -- stored = recomputed, so every one of those writes was a no-op, and there
  -- were 128,715 of them against ten live rows in eleven hours.
  -- A no-op UPDATE is not free. It writes a new version of the club settings
  -- row, runs the fifteen triggers that fire on clubs UPDATE - every lifecycle
  -- and treasury guard, the settings audit, the autoledger, four management
  -- event emitters - and takes an exclusive lock on that one row which is held
  -- until the writing transaction commits. The engine changes table status
  -- inside the hand loop, so that lock was held across the rest of the hand,
  -- and public.clubs was the most contended tuple behind Lock/transactionid.
  -- The recount itself stays: it is an index scan of ~255 buffers and it takes
  -- no lock on clubs. Only the write is conditional, and the column still ends
  -- every call holding exactly fn_live_table_count(id).
  -- Same law as the table_seats no-op suppressor shipped 2026-09-03.
  IF cardinality(v_clubs) > 0 THEN
    UPDATE clubs c
       SET table_count = v.n
      FROM (SELECT t.id, fn_live_table_count(t.id) AS n
              FROM clubs t WHERE t.id = ANY(v_clubs)) v
     WHERE c.id = v.id
       AND c.table_count IS DISTINCT FROM v.n;
  END IF;

  -- Every club that can see a touched union's tables (members + the union row).
  IF cardinality(v_unions) > 0 THEN
    UPDATE clubs c
       SET table_count = v.n
      FROM (SELECT t.id, fn_live_table_count(t.id) AS n
              FROM clubs t
             WHERE t.id = ANY(v_unions)
                OR t.id IN (SELECT club_id FROM union_clubs WHERE union_id = ANY(v_unions))) v
     WHERE c.id = v.id
       AND c.table_count IS DISTINCT FROM v.n;
  END IF;

  RETURN NULL;
END $$;


ALTER FUNCTION public.fn_sync_club_table_counts() OWNER TO postgres;

--
-- TOC entry 49089 (class 0 OID 0)
-- Dependencies: 9435
-- Name: FUNCTION fn_sync_club_table_counts(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_sync_club_table_counts() IS 'Recomputes clubs.table_count. Reached by three triggers on public.tables (ins/del/upd) and one on public.union_clubs. The UPDATE one carries an IS DISTINCT FROM guard: `AFTER UPDATE OF status` fires whenever status is in the SET list, and the engine writes status alongside current_players once per hand, which made this trigger 40% of all database time on 2026-08-20. Do not merge these back into one trigger. fn_reconcile_club_table_counts() is the nightly backstop for anything these miss.';


