--
-- TOC entry 8162 (class 1255 OID 6952774)
-- Name: fn_sync_share_streak_multiplier(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_share_streak_multiplier(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_today         DATE         := (now() AT TIME ZONE 'America/Chicago')::DATE;
    v_yesterday     DATE         := v_today - 1;
    v_streak_days   INTEGER      := 0;
    v_multiplier    DECIMAL(4,2) := 1.00;
    v_has_active    BOOLEAN      := false;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM public.share_events
        WHERE user_id = p_user_id
          AND (created_at AT TIME ZONE 'America/Chicago')::DATE >= v_yesterday
    ) INTO v_has_active;

    IF v_has_active THEN
        WITH daily_shares AS (
            SELECT date_trunc('day', created_at AT TIME ZONE 'America/Chicago')::DATE AS share_day
            FROM public.share_events
            WHERE user_id = p_user_id
            GROUP BY share_day
        ),
        numbered AS (
            SELECT
                share_day,
                share_day - (ROW_NUMBER() OVER (ORDER BY share_day DESC) * INTERVAL '1 day')::DATE AS grp
            FROM daily_shares
            WHERE share_day <= v_today
        ),
        current_streak AS (
            SELECT COUNT(*) AS streak_days
            FROM numbered
            WHERE grp = (
                SELECT grp FROM numbered
                WHERE share_day >= v_yesterday
                ORDER BY share_day DESC
                LIMIT 1
            )
        )
        SELECT streak_days INTO v_streak_days FROM current_streak;
    END IF;

    IF v_streak_days >= 30 THEN v_multiplier := 2.00;
    ELSIF v_streak_days >= 14 THEN v_multiplier := 1.75;
    ELSIF v_streak_days >= 7 THEN v_multiplier := 1.50;
    ELSIF v_streak_days >= 3 THEN v_multiplier := 1.20;
    ELSE v_multiplier := 1.00;
    END IF;

    UPDATE public.profiles
    SET diamond_multiplier = v_multiplier,
        updated_at = now()
    WHERE id = p_user_id
      AND COALESCE(diamond_multiplier, 1.00) != v_multiplier;
END;
$$;


ALTER FUNCTION public.fn_sync_share_streak_multiplier(p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 7382 (class 1255 OID 8911579)
-- Name: fn_sync_tournament_chips(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_tournament_chips(p_tournament_id uuid, p_updates jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  IF p_tournament_id IS NULL OR p_updates IS NULL OR jsonb_typeof(p_updates) <> 'array' THEN
    RETURN 0;
  END IF;

  /* ONE LOCK ORDER (20260906): lock the rows this call will write, in
     user_id order, before writing them. 247 deadlocks a day were two syncs of
     the same event reaching the same rows from opposite ends. See the header. */
  PERFORM 1
    FROM public.tournament_players tp
    JOIN jsonb_to_recordset(p_updates) AS u(user_id uuid, chips numeric)
      ON u.user_id = tp.user_id
   WHERE tp.tournament_id = p_tournament_id
     AND tp.status = 'playing'
     AND tp.chips IS DISTINCT FROM floor(GREATEST(u.chips, 0))::integer
   ORDER BY tp.user_id
   FOR UPDATE OF tp;

  UPDATE public.tournament_players tp
     SET chips = floor(GREATEST(u.chips, 0))::integer
  FROM jsonb_to_recordset(p_updates) AS u(user_id uuid, chips numeric)
  WHERE tp.tournament_id = p_tournament_id
    AND tp.user_id = u.user_id
    AND tp.status = 'playing'
    -- PERF 2026-08-25: skip rows whose chip count is already correct. Postgres
    -- does not elide a no-op UPDATE by itself, and every one of those wrote a
    -- heap tuple, a WAL record, index entries and a realtime decode for no
    -- change at all. IS DISTINCT FROM, not <>, so a NULL chips column still
    -- matches and gets written.
    AND tp.chips IS DISTINCT FROM floor(GREATEST(u.chips, 0))::integer;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


