--
-- TOC entry 3719 (class 1255 OID 15129322)
-- Name: fn_sync_tournament_current_players(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_tournament_current_players() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tid uuid;
  v_count integer;
BEGIN
  v_tid := COALESCE(NEW.tournament_id, OLD.tournament_id);
  IF v_tid IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT count(*) INTO v_count
  FROM public.tournament_players
  WHERE tournament_id = v_tid
    AND status IN ('registered', 'playing');

  UPDATE public.tournaments
     SET current_players = v_count
   WHERE id = v_tid
     AND status IN ('ANNOUNCED', 'REGISTERING')
     AND current_players IS DISTINCT FROM v_count;

  /* A RUNNING FIELD IS COUNTED BY THE BUST THAT SHRINKS IT (2026-09-22).
     The statement above is pre-start only, on purpose, and nothing else
     counted a RUNNING field: a bust left the count one too high until a
     minutely job (reconcile-tournament-denormals) rewrote it, and the
     registration door refuses a late entrant while the count and the roster
     disagree. A player moving into or out of the field is recounted here, in
     the transaction that moves them.

     Only a MEMBERSHIP change on UPDATE. An admission (INSERT) or a removal
     (DELETE) into a RUNNING field is counted by the door that performs it:
     the registration, horse and satellite-seat doors publish the new count
     themselves and require this trigger to leave a RUNNING count alone.

     Seat-first formats are skipped with the predicate their own owner uses
     (fn_sync_seat_first_player_count, live seats on the primary table), so
     the two writers partition the column and never write the same event.

     The tournaments row is already locked FOR UPDATE by this transaction:
     every membership change takes it first, in
     aa_tournament_player_launch_proof_lock. */
  IF TG_OP = 'UPDATE'
     AND NEW.tournament_id IS NOT DISTINCT FROM OLD.tournament_id
     AND (COALESCE(OLD.status, '') IN ('registered', 'playing'))
         IS DISTINCT FROM (COALESCE(NEW.status, '') IN ('registered', 'playing')) THEN
    UPDATE public.tournaments t
       SET current_players = v_count
     WHERE t.id = v_tid
       AND t.status = 'RUNNING'
       AND t.current_players IS DISTINCT FROM v_count
       AND NOT public.fn_ca_tournament_recorded_seat_first(t.id, true);
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.fn_sync_tournament_current_players() OWNER TO postgres;

--
-- TOC entry 49106 (class 0 OID 0)
-- Dependencies: 3719
-- Name: FUNCTION fn_sync_tournament_current_players(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_sync_tournament_current_players() IS 'Owner of tournaments.current_players for non-seat-first formats: recounts the roster on every pre-start change (20260823120000) and on every RUNNING membership change, a bust or a re-entry (20260922141704). A RUNNING admission is counted by the door that performs it. Seat-first formats belong to fn_sync_seat_first_player_count.';


--
-- TOC entry 8974 (class 1255 OID 24464222)
-- Name: fn_sync_tournament_live_seat_chips(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sync_tournament_live_seat_chips(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_updates jsonb;
  v_open_user_ids jsonb;
  v_ambiguous_user_ids jsonb;
  v_synced integer;
BEGIN
  WITH live AS (
    SELECT s.user_id,s.stack,s.joined_at
      FROM public.tables t
      JOIN public.table_seats s ON s.table_id=t.id AND s.left_at IS NULL
     WHERE t.tournament_id=p_tournament_id
  ), latest AS (
    SELECT user_id,max(joined_at) AS latest_joined_at FROM live GROUP BY user_id
  ), classified AS (
    SELECT l.user_id,m.latest_joined_at,
           count(*) FILTER (WHERE l.joined_at=m.latest_joined_at) AS latest_count,
           max(l.stack) FILTER (WHERE l.joined_at=m.latest_joined_at) AS latest_stack
      FROM live l JOIN latest m USING (user_id)
     GROUP BY l.user_id,m.latest_joined_at
  )
  SELECT COALESCE(jsonb_agg(DISTINCT user_id ORDER BY user_id),'[]'::jsonb),
         COALESCE(jsonb_agg(user_id ORDER BY user_id) FILTER (
           WHERE latest_joined_at IS NULL OR latest_count<>1),'[]'::jsonb),
         COALESCE(jsonb_agg(jsonb_build_object(
           'user_id',user_id,'chips',floor(GREATEST(COALESCE(latest_stack,0),0)))
           ORDER BY user_id) FILTER (
             WHERE latest_joined_at IS NOT NULL AND latest_count=1),'[]'::jsonb)
    INTO v_open_user_ids,v_ambiguous_user_ids,v_updates
    FROM classified;

  v_synced := public.fn_sync_tournament_chips(p_tournament_id,v_updates);
  RETURN jsonb_build_object('ok',true,'synced',COALESCE(v_synced,0),
    'open_user_ids',v_open_user_ids,'ambiguous_user_ids',v_ambiguous_user_ids);
END;
$$;


