--
-- TOC entry 9160 (class 1255 OID 57591159)
-- Name: fn_table_seats_lightning_anchor_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_table_seats_lightning_anchor_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ps     uuid;
  v_player uuid;
  v_cluster uuid;
  v_hand   uuid;
BEGIN
  -- A SEAT THAT ANCHORS AN OPEN POOL SESSION IS NOT DELETED (BEFORE DELETE,
  -- file D). There is no foreign key to hold the anchor, by design; this is
  -- what holds it. The buy-in's DELETE of a departed occupant's row is untouched:
  -- a departure exits the session at the commit that records it, so by the
  -- time anyone deletes that row it anchors nothing open.
  IF TG_OP = 'DELETE' THEN
    SELECT ps.id, ps.player_id, ps.cluster_id INTO v_ps, v_player, v_cluster
      FROM public.lightning_pool_session ps
     WHERE ps.anchor_seat_id = OLD.id AND ps.exited_at IS NULL;
    IF v_ps IS NULL THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'LIGHTNING_ANCHOR_SEAT_IS_IN_THE_POOL: seat % anchors open pool session % of player % in Cluster %; a seat can be deleted once the pool session it anchors has exited',
      OLD.id, v_ps, v_player, v_cluster USING ERRCODE = 'PLT01';
  END IF;

  SELECT ps.id, ps.player_id, ps.cluster_id INTO v_ps, v_player, v_cluster
    FROM public.lightning_pool_session ps
   WHERE ps.anchor_seat_id = OLD.id AND ps.exited_at IS NULL;
  IF v_ps IS NULL THEN
    RETURN NEW;
  END IF;
  -- LIGHTNING PHASE 6 (20261001154813): EVERY LIVE HAND THE PLAYER IS IN
  -- HOLDS THE ANCHOR, including one they folded out of. A fast or normal fold
  -- releases the reservation so they can be dealt again at once, but the
  -- chips they put in that pot leave the seat only through that hand's
  -- settlement.
  v_hand := public.fn_lightning_player_live_hand(v_player, v_cluster);
  IF v_hand IS NULL THEN
    RETURN NEW;
  END IF;

  -- THE ONE WRITER ALLOWED THROUGH is a Lightning settlement, recognised by a
  -- row of lightning_settlement_marker naming THIS seat for THIS transaction.
  -- Only fn_lightning_settle_hand, a SECURITY DEFINER function, can write that
  -- table (no role holds a privilege on it), and it removes its rows before it
  -- returns. A value any session can set is not an authority, and none is
  -- read here. A settlement moves the stack only: never the departure or the
  -- occupant.
  IF NEW.left_at IS NOT DISTINCT FROM OLD.left_at
     AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id
     AND EXISTS (SELECT 1 FROM public.lightning_settlement_marker m
                  WHERE m.txid = pg_current_xact_id_if_assigned()
                    AND m.seat_id = OLD.id) THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'LIGHTNING_HAND_IN_PROGRESS: seat % anchors pool session % of player % in Cluster %, who is in Lightning hand %; the anchor stack, departure and occupant change only by that hand''s settlement (stack % -> %, left_at % -> %)',
    OLD.id, v_ps, v_player, v_cluster, v_hand, OLD.stack, NEW.stack, OLD.left_at, NEW.left_at
    USING ERRCODE = 'PLT01';
END
$$;


ALTER FUNCTION public.fn_table_seats_lightning_anchor_guard() OWNER TO postgres;

--
-- TOC entry 49115 (class 0 OID 0)
-- Dependencies: 9160
-- Name: FUNCTION fn_table_seats_lightning_anchor_guard(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_table_seats_lightning_anchor_guard() IS 'BEFORE UPDATE on table_seats, only when stack, left_at or user_id changes: refuses with LIGHTNING_HAND_IN_PROGRESS (SQLSTATE PLT01) a change to a seat that anchors an open pool session whose player is in a live Lightning hand, unless ca.lightning_settlement_hand names that hand. BEFORE DELETE: refuses with LIGHTNING_ANCHOR_SEAT_IS_IN_THE_POOL (PLT01) the deletion of a seat that anchors an OPEN pool session. One index probe for every other seat.';


--
-- TOC entry 9051 (class 1255 OID 57591166)
-- Name: fn_table_seats_lightning_pool_follows_seat(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_table_seats_lightning_pool_follows_seat() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  ps      record;
  v_other uuid;
  v_now   timestamptz := clock_timestamp();
  v_lock_cluster uuid;
  v_old_table    uuid;
BEGIN
  -- A SEAT WAITS FOR THE MODE CHANGE IN FLIGHT (2026-10-15, Lightning Phase
  -- 12 load and chaos): the Cluster's mode lock, SHARED, before anything
  -- below reads the mode, the epoch or the pool. A conversion or reversion
  -- holds it EXCLUSIVE from just after its seat FOR SHARE to its commit, so
  -- this waits for one in flight and then reads what it committed; one that
  -- comes after waits for this commit and then sees this seat. Without it an
  -- arrival read 'pending_on', entered nothing, and the conversion that could
  -- not see the uncommitted seat left the player out of the pool for good.
  IF TG_OP = 'UPDATE' THEN v_old_table := OLD.table_id; END IF;
  FOR v_lock_cluster IN
    SELECT DISTINCT tb.cluster_id FROM public.tables tb
     WHERE tb.id IN (NEW.table_id, v_old_table) AND tb.cluster_id IS NOT NULL
     ORDER BY tb.cluster_id
  LOOP
    PERFORM pg_advisory_xact_lock_shared(
      pg_catalog.hashtextextended('lightning_cluster_mode:' || v_lock_cluster::text, 0));
  END LOOP;
  v_now := clock_timestamp();

  IF TG_OP = 'UPDATE'
     AND ((OLD.left_at IS NULL AND NEW.left_at IS NOT NULL)
          OR NEW.user_id IS DISTINCT FROM OLD.user_id) THEN
    FOR ps IN
      UPDATE public.lightning_pool_session s
         SET exited_at    = GREATEST(v_now, s.entered_at),
             exit_reason  = CASE WHEN NEW.user_id IS DISTINCT FROM OLD.user_id
                                 THEN 'anchor_seat_turned_over' ELSE 'anchor_seat_left' END,
             state        = 'closed',
             ending_stack = OLD.stack,
             updated_at   = v_now
       WHERE s.anchor_seat_id = OLD.id AND s.exited_at IS NULL
      RETURNING s.id, s.cluster_id, s.cluster_epoch, s.player_id, s.exit_reason, s.ending_stack
    LOOP
      UPDATE public.lightning_pool_slot sl
         SET closed_at = GREATEST(v_now, sl.opened_at),
             close_reason = 'pool_session_exited',
             updated_at = v_now
       WHERE sl.pool_session_id = ps.id AND sl.closed_at IS NULL;

      INSERT INTO public.cash_cluster_events (game_id, table_id, kind, payload, cluster_epoch)
      VALUES (ps.cluster_id, OLD.table_id, 'pool_player_left', jsonb_build_object(
        'cluster_id', ps.cluster_id, 'cluster_epoch', ps.cluster_epoch, 'player_id', ps.player_id,
        'pool_session_id', ps.id, 'anchor_seat_id', OLD.id, 'reason', ps.exit_reason,
        'ending_stack', ps.ending_stack, 'at', v_now), ps.cluster_epoch);

      SELECT ts.id INTO v_other
        FROM public.table_seats ts
        JOIN public.tables tb ON tb.id = ts.table_id
       WHERE tb.cluster_id = ps.cluster_id AND ts.user_id = ps.player_id AND ts.id <> OLD.id
         AND public.fn_lightning_anchor_is_live_eligible(ts.id, ps.cluster_id, ps.player_id)
       ORDER BY ts.joined_at, ts.id
       LIMIT 1;
      IF v_other IS NOT NULL THEN
        PERFORM public.fn_lightning_pool_enter(v_other, v_now);
      END IF;
    END LOOP;
  END IF;

  IF NEW.left_at IS NULL AND NEW.user_id IS NOT NULL
     AND coalesce(NEW.stack, 0) > 0
     AND coalesce(NEW.is_sitting_out, false) = false
     AND coalesce(NEW.leave_pending, false) = false
     AND EXISTS (SELECT 1 FROM public.tables tb
                   JOIN public.cash_games g ON g.id = tb.cluster_id
                  WHERE tb.id = NEW.table_id AND g.cluster_mode = 'lightning') THEN
    PERFORM public.fn_lightning_pool_enter(NEW.id, v_now);
  END IF;
  RETURN NULL;
END
$$;


