--
-- TOC entry 7686 (class 1255 OID 108293335)
-- Name: fn_table_studio_favorites_are_valid(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_table_studio_favorites_are_valid(p_favorites text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  SELECT cardinality(p_favorites) <= 100
     AND cardinality(p_favorites) = (
       SELECT count(DISTINCT item) FROM unnest(p_favorites) AS item
     )
     AND NOT EXISTS (
       SELECT 1
         FROM unnest(p_favorites) AS item
        WHERE item IS NULL
           OR item <> btrim(item)
           OR item !~ '^(themes|table|button|background|cards|decks):[A-Za-z0-9][A-Za-z0-9_-]{0,127}$'
     );
$_$;


