--
-- TOC entry 5098 (class 1255 OID 14538909)
-- Name: fn_tournament_chip_conservation_check(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_chip_conservation_check(p_tolerance_per_player numeric DEFAULT 1) RETURNS TABLE(tournament_id uuid, name text, players bigint, expected_chips numeric, actual_chips numeric, drift numeric, drift_per_player numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH calc AS (
    SELECT t.id,
           t.name,
           (SELECT count(*) FROM public.tournament_players tp
             WHERE tp.tournament_id = t.id) AS players,
           public.fn_ca_tournament_chip_supply(t.id)
             -- A starting stack owed to a registration that was never issued a
             -- chair is not on the felt because it was never issued, not
             -- because it was lost (2026-09-26, c7f21a83).
             - COALESCE(t.starting_chips, 0) * (
                 SELECT count(*) FROM public.tournament_players tp
                  WHERE tp.tournament_id = t.id
                    AND tp.status = 'registered'
                    AND COALESCE(tp.chips, 0) <= 0
                    AND COALESCE(tp.rebuys, 0) = 0
                    AND NOT COALESCE(tp.add_on, false)
                    AND NOT EXISTS (
                          SELECT 1 FROM public.table_seats s
                            JOIN public.tables tb ON tb.id = s.table_id
                           WHERE tb.tournament_id = t.id AND s.user_id = tp.user_id)
               ) AS expected_chips,
           public.fn_ca_tournament_felt_total(t.id)  AS actual_chips
      FROM public.tournaments t
     WHERE t.status = 'RUNNING'
  )
  SELECT c.id, c.name, c.players,
         round(c.expected_chips, 2),
         round(c.actual_chips, 2),
         round(c.actual_chips - c.expected_chips, 2),
         round((c.actual_chips - c.expected_chips) / NULLIF(c.players, 0), 3)
    FROM calc c
   WHERE c.players > 0
     AND abs(c.actual_chips - c.expected_chips)
         > (GREATEST(p_tolerance_per_player, 0) * c.players)
   ORDER BY abs(c.actual_chips - c.expected_chips) DESC;
$$;


ALTER FUNCTION public.fn_tournament_chip_conservation_check(p_tolerance_per_player numeric) OWNER TO postgres;

--
-- TOC entry 6971 (class 1255 OID 14476119)
-- Name: fn_tournament_club_for_user(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_club_for_user(p_user_id uuid, p_tournament_id uuid, p_preferred_club uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_union uuid; v_t_club uuid; v_club uuid;
  v_is_horse boolean := false; v_n int; v_idx int;
  v_paying text;
BEGIN
  SELECT t.union_id, t.club_id INTO v_union, v_t_club
    FROM tournaments t WHERE t.id = p_tournament_id;

  IF v_union IS NULL THEN
    RETURN v_t_club;                       -- standalone club tournament
  END IF;

  /* THE WALLET THAT CAN PAY IS THE WALLET THAT PAYS (2026-10-12). A player in
     several clubs of one union was charged by their OLDEST membership even
     when it held 4.50 and another of their clubs held 2,653.74, so every
     union event refused them "Insufficient Balance" with chips in the
     account. The registration doors (fn_register_for_tournament and
     fn_register_horse_for_tournament - the same door for a person and a
     horse, CLAUDE.md 10.5) now ask fn_ca_entry_paying_club for the member
     club that can cover the entry when the default one cannot, and declare it
     for THIS transaction only. The debit, the wallet log and the entry stamp
     all resolve through here inside that one transaction, so they name the
     same wallet. Keyed on tournament AND player: another player resolved in
     the same transaction is never steered by it. */
  IF p_preferred_club IS NULL THEN
    v_paying := NULLIF(current_setting('app.ca_entry_paying_club', true), '');
    IF v_paying IS NOT NULL
       AND split_part(v_paying, ':', 1) = p_tournament_id::text
       AND split_part(v_paying, ':', 2) = p_user_id::text THEN
      RETURN split_part(v_paying, ':', 3)::uuid;
    END IF;
  END IF;

  /* THE HOST CLUB IS IN ITS OWN UNION (2026-09-10). A tournament hosted BY a
     union has club_id = union_id, and that house club is never a row in
     union_clubs. The membership test below joined union_clubs, so the
     tournament's own club could never be the preferred club - a satellite
     winner who IS a member of the host club was resolved to some other club
     and the ticket award was refused for a club mismatch. Friday Night
     Feature Satellite Heads-Up sat RUNNING for 16 hours on that refusal. The
     host club counts as in the union without needing the row. */
  IF p_preferred_club IS NOT NULL
     AND EXISTS (SELECT 1 FROM club_members m
                 WHERE m.user_id = p_user_id AND m.club_id = p_preferred_club
                   AND m.status IN ('active','approved')
                   AND (m.club_id = v_t_club
                        OR EXISTS (SELECT 1 FROM union_clubs uc
                                    WHERE uc.club_id = m.club_id AND uc.union_id = v_union)))
  THEN
    RETURN p_preferred_club;
  END IF;

  /* AN ENTRY'S LATER MONEY USES THE WALLET THE ENTRY CAME FROM (2026-10-12).
     Once a player is on the roster, the club stamped on their entry is the
     wallet the buy-in left, so a rebuy, re-entry, add-on, refund or prize
     resolves to it rather than re-deriving "oldest membership". Before today
     the two only agreed because both were the oldest membership; an entry
     paid from the wallet that could pay (above) would otherwise have been
     refunded into a different club. */
  SELECT tp.club_id INTO v_club
    FROM tournament_players tp
   WHERE tp.tournament_id = p_tournament_id AND tp.user_id = p_user_id
     AND tp.club_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM club_members m
                  WHERE m.user_id = p_user_id AND m.club_id = tp.club_id
                    AND m.status IN ('active','approved'))
   LIMIT 1;
  IF v_club IS NOT NULL THEN
    RETURN v_club;
  END IF;

  SELECT COALESCE(p.is_horse, false) INTO v_is_horse FROM profiles p WHERE p.id = p_user_id;

  IF v_is_horse THEN
    -- Same stable home club a horse uses for cash play, so a horse's tournament
    -- and cash activity always belong to the same club.
    SELECT count(*) INTO v_n
      FROM club_members m
      JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
     WHERE m.user_id = p_user_id AND m.status IN ('active','approved');
    IF v_n > 1 THEN
      v_idx := (abs(hashtextextended(p_user_id::text, 0)) % v_n)::int;
      SELECT m.club_id INTO v_club
        FROM club_members m
        JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
       WHERE m.user_id = p_user_id AND m.status IN ('active','approved')
       ORDER BY m.club_id OFFSET v_idx LIMIT 1;
      IF v_club IS NOT NULL THEN RETURN v_club; END IF;
    END IF;
  END IF;

  SELECT m.club_id INTO v_club
    FROM club_members m
    JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
   WHERE m.user_id = p_user_id AND m.status IN ('active','approved')
   ORDER BY m.joined_at ASC NULLS LAST, m.club_id
   LIMIT 1;

  RETURN v_club;
END $$;


ALTER FUNCTION public.fn_tournament_club_for_user(p_user_id uuid, p_tournament_id uuid, p_preferred_club uuid) OWNER TO postgres;

--
-- TOC entry 8221 (class 1255 OID 55242284)
-- Name: fn_tournament_config_refusal(jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_config_refusal(p_config jsonb, p_surface text) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_schedule boolean;
  v_type     text;
  v_short    boolean;
  v_stack    numeric;
  v_start    timestamptz;
  v_target   jsonb;
  v_ok       boolean;
  v_total    numeric;
  v_level    jsonb;
  v_sb       numeric;
  v_bb       numeric;
  v_prev_sb  numeric;
  v_prev_bb  numeric;
  v_seen     boolean := false;
  v_variant  text;
  v_hole     int;
  v_deck     int;
  v_seats    numeric;
  v_rebuy    boolean;
  v_late     numeric;
  v_late_min numeric;
  v_buy_in   numeric;
BEGIN
  IF p_surface IS NULL OR p_surface NOT IN ('create', 'schedule') THEN
    RAISE EXCEPTION 'fn_tournament_config_refusal: unknown surface %', p_surface
      USING ERRCODE = '22023';
  END IF;
  IF p_config IS NULL OR jsonb_typeof(p_config) <> 'object' THEN
    RETURN 'invalid_configuration';
  END IF;
  v_schedule := p_surface = 'schedule';

  BEGIN
    v_type := lower(COALESCE(NULLIF(btrim(p_config->>'type'), ''), 'mtt'));
    IF v_schedule AND v_type IN ('hu_sng', 'heads_up') THEN v_type := 'sng'; END IF;
    v_short := v_type IN ('sng', 'spin');

    -- 1. Starting stack: a whole number above zero, for every format.
    v_stack := NULLIF(p_config->>'startingStack', '')::numeric;
    IF v_stack IS NOT NULL AND (v_stack <= 0 OR v_stack <> trunc(v_stack)) THEN
      RETURN 'starting_stack_must_be_positive';
    END IF;

    -- 2. A start in the past is refused, never silently moved. Five minutes of
    --    skew for a device clock that runs slow.
    IF NOT v_schedule THEN
      v_start := NULLIF(p_config->>'startTime', '')::timestamptz;
      IF v_start IS NOT NULL AND v_start < now() - interval '5 minutes' THEN
        RETURN 'start_time_in_past';
      END IF;
    END IF;

    -- 3. A satellite names the event its seats go into.
    IF v_type = 'satellite' THEN
      IF v_schedule THEN
        v_target := COALESCE(p_config->'satelliteTarget', p_config->'satellite_target');
        -- COALESCE: with no target object every jsonb_typeof test is NULL, and
        -- NOT NULL would wave the satellite through.
        v_ok := COALESCE(
                (jsonb_typeof(v_target) = 'string' AND btrim(v_target #>> '{}') <> '')
             OR (jsonb_typeof(v_target) = 'object'
                 AND COALESCE(NULLIF(v_target->>'tournamentId', ''), NULLIF(v_target->>'tournament_id', '')) IS NOT NULL),
                false)
             OR COALESCE(btrim(p_config->>'satelliteTargetId'), '') <> ''
             OR COALESCE(btrim(p_config->>'satellite_target_id'), '') <> ''
             OR COALESCE(btrim(p_config->>'satelliteTargetName'), '') <> '';
      ELSE
        v_ok := COALESCE(btrim(p_config->>'satelliteTargetId'), '') <> '';
      END IF;
      IF NOT v_ok THEN
        RETURN 'satellite_target_required';
      END IF;
    END IF;

    -- 4. Payouts add up to 100, within the governed creator's tolerance of 1.
    IF jsonb_typeof(p_config->'payoutStructure') = 'array'
       AND jsonb_array_length(p_config->'payoutStructure') > 0 THEN
      SELECT COALESCE(SUM((e->>'percentage')::numeric), 0) INTO v_total
        FROM jsonb_array_elements(p_config->'payoutStructure') e;
      IF abs(v_total - 100) > 1 THEN
        RETURN 'payouts_must_total_100';
      END IF;
    END IF;

    -- 5. A Sit And Go or Spin ladder: positive durations, blinds never fall.
    --    Break rows (a flag, or 0/0 blinds) do not take part. A new MTT ladder
    --    is held to the fuller contract by tournaments_new_mtt_blind_contract.
    IF v_short AND jsonb_typeof(p_config->'blindStructure') = 'array' THEN
      FOR v_level IN SELECT value FROM jsonb_array_elements(p_config->'blindStructure') LOOP
        IF jsonb_typeof(v_level) <> 'object' THEN
          RETURN 'invalid_configuration';
        END IF;
        IF NULLIF(v_level->>'durationMinutes', '') IS NOT NULL
           AND (v_level->>'durationMinutes')::numeric <= 0 THEN
          RETURN 'blind_level_duration_invalid';
        END IF;
        v_sb := NULLIF(v_level->>'smallBlind', '')::numeric;
        v_bb := NULLIF(v_level->>'bigBlind', '')::numeric;
        CONTINUE WHEN COALESCE(v_level->>'isBreak', '') = 'true' OR (v_sb = 0 AND v_bb = 0);
        IF v_seen AND (v_sb < v_prev_sb OR v_bb < v_prev_bb) THEN
          RETURN 'blind_structure_must_not_decrease';
        END IF;
        v_prev_sb := v_sb;
        v_prev_bb := v_bb;
        v_seen := true;
      END LOOP;
    END IF;

    -- 6. No more seats at a table than one deck can deal: the deck, less one
    --    board, over the hole cards each seat takes (VariantRules.maxSeatsFor).
    v_variant := lower(btrim(COALESCE(p_config->>'gameVariant', 'NLH')));
    v_hole := CASE
      WHEN v_variant IN ('plo4', 'plo8', 'flo8') THEN 4
      WHEN v_variant = 'plo5' THEN 5
      WHEN v_variant = 'plo6' THEN 6
      WHEN v_variant = 'pineapple' THEN 3
      ELSE 2 END;
    v_deck := CASE WHEN v_variant LIKE 'short%' THEN 36 ELSE 52 END;
    IF v_schedule AND v_type = 'spin' THEN
      v_seats := 3;
    ELSE
      v_seats := round(NULLIF(p_config->>'tableSize', '')::numeric);
      IF v_seats IS NULL THEN
        v_seats := CASE
          WHEN v_schedule AND v_short
            THEN COALESCE(round(NULLIF(p_config->>'maxPlayers', '')::numeric), 2)
          ELSE 9 END;
      END IF;
      v_seats := LEAST(10, GREATEST(2, v_seats));
    END IF;
    IF v_seats > (v_deck - 5) / v_hole THEN
      RETURN 'table_size_exceeds_deck';
    END IF;

    -- 7. A rebuy or re-entry needs a late registration window to be sold in.
    IF v_schedule THEN
      v_rebuy := COALESCE(p_config->>'isRebuy', '') = 'true'
              OR COALESCE(p_config->>'rebuy', '') = 'true'
              OR COALESCE(p_config->>'isReentry', '') = 'true'
              OR v_type IN ('rebuy', 'reentry', 'mtt_rebuy', 'mtt_reentry');
      v_late := CASE
        WHEN v_short THEN 0
        WHEN NOT (p_config ? 'lateRegistrationLevels') THEN 8
        ELSE COALESCE(NULLIF(p_config->>'lateRegistrationLevels', '')::numeric, 0) END;
      v_late_min := 0;
    ELSE
      v_rebuy := COALESCE((p_config->>'isRebuy')::boolean, false)
              OR COALESCE((p_config->>'isReentry')::boolean, false);
      v_late := CASE WHEN v_short THEN 0
        ELSE COALESCE(NULLIF(p_config->>'lateRegistrationLevels', '')::numeric, 0) END;
      v_late_min := COALESCE(NULLIF(p_config->>'lateRegistrationMinutes', '')::numeric, 0);
    END IF;
    v_buy_in := COALESCE(NULLIF(p_config->>'buyIn', '')::numeric, 0);
    IF v_rebuy
       AND NOT (v_buy_in = 0 AND NOT v_short)   -- a Free Buy event has its own levels
       AND v_late <= 0 AND v_late_min <= 0 THEN
      RETURN 'rebuy_requires_late_registration';
    END IF;
  EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range
      OR invalid_datetime_format OR datetime_field_overflow THEN
      RETURN 'invalid_configuration';
  END;

  RETURN NULL;
END;
$$;


