--
-- TOC entry 8079 (class 1255 OID 14515304)
-- Name: fn_tournament_payout_sweep(integer, boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_payout_sweep(p_days integer DEFAULT 2, p_apply boolean DEFAULT false, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '600s'
    AS $$
DECLARE
  r          record;
  v_res      jsonb;
  v_out      jsonb := '[]'::jsonb;
  v_n        int    := 0;
  v_topup    numeric := 0;
  v_matched  int    := 0;
  v_scanned  int    := 0;
  v_failed   int    := 0;
  v_fail_ids uuid[] := ARRAY[]::uuid[];
  v_first_err text;
  v_limit    int    := GREATEST(p_limit, 1);
  v_since    timestamptz := now() - make_interval(days => GREATEST(p_days, 1));
BEGIN
  SELECT count(*) INTO v_matched
    FROM tournaments t
   WHERE t.status = 'COMPLETED'
     AND COALESCE(t.ended_at, t.started_at, t.updated_at) > v_since
     AND COALESCE(t.prize_pool, 0) > 0
     AND NOT (COALESCE(t.variant, '') = 'satellite' OR UPPER(COALESCE(t.tournament_type, '')) = 'SATELLITE' OR t.satellite_target_id IS NOT NULL);

  FOR r IN
    SELECT t.id
      FROM tournaments t
     WHERE t.status = 'COMPLETED'
       AND COALESCE(t.ended_at, t.started_at, t.updated_at) > v_since
       AND COALESCE(t.prize_pool, 0) > 0
       AND NOT (COALESCE(t.variant, '') = 'satellite' OR UPPER(COALESCE(t.tournament_type, '')) = 'SATELLITE' OR t.satellite_target_id IS NOT NULL)
     ORDER BY COALESCE(t.ended_at, t.started_at, t.updated_at) DESC
     LIMIT v_limit
  LOOP
    v_scanned := v_scanned + 1;
    BEGIN
      v_res := fn_tournament_payout_reconcile(r.id, p_apply);
      IF COALESCE((v_res->>'clean')::boolean, true) = false THEN
        v_out   := v_out || v_res;
        v_n     := v_n + 1;
        v_topup := v_topup + COALESCE((v_res->>'total_top_up')::numeric, 0);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      IF v_first_err IS NULL THEN v_first_err := SQLERRM; END IF;
      IF array_length(v_fail_ids, 1) IS NULL OR array_length(v_fail_ids, 1) < 20 THEN
        v_fail_ids := v_fail_ids || r.id;
      END IF;
    END;
  END LOOP;

  IF v_failed > 0 THEN
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT 'warning',
           'fn_tournament_payout_sweep',
           format('Payout sweep could not reconcile %s of %s tournament(s) in this '
                  'pass; the rest were paid. First error: %s',
                  v_failed, v_scanned, COALESCE(v_first_err, 'unknown')),
           jsonb_build_object('failed', v_failed, 'scanned', v_scanned,
                              'first_error', v_first_err,
                              'sample_tournaments', to_jsonb(v_fail_ids))
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source = 'fn_tournament_payout_sweep'
          AND fa.resolved IS NOT TRUE);
  END IF;

  -- Truncation on an APPLYING pass, stated as what it is rather than as a
  -- conclusion this function is not in a position to draw. A narrow pass that
  -- truncates is normal when a deep pass backs it (RakebackSettlerService);
  -- the hourly pg_cron job has nothing behind it, so for that caller the
  -- unreached tail really is unreachable. This function cannot tell the two
  -- apart, so it reports and does not diagnose.
  IF p_apply AND v_matched > v_scanned THEN
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT 'warning',
           'fn_tournament_payout_sweep_truncated',
           format('An applying payout sweep examined %s of %s tournament(s) in its '
                  '%s-day window and stopped at its %s-row limit, leaving %s '
                  'unexamined. It orders newest-first, so those only get older: '
                  'they are reached only by a wider pass, if one is configured. '
                  'If this caller has no deeper pass behind it, raise the limit.',
                  v_scanned, v_matched, GREATEST(p_days, 1), v_limit,
                  v_matched - v_scanned),
           jsonb_build_object('scanned', v_scanned, 'matched', v_matched,
                              'days', GREATEST(p_days, 1), 'limit', v_limit,
                              'unexamined', v_matched - v_scanned)
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source = 'fn_tournament_payout_sweep_truncated'
          AND fa.resolved IS NOT TRUE);
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'days', p_days,
    'applied', p_apply,
    'tournaments_with_findings', v_n,
    'total_top_up', round(v_topup, 2),
    'findings', v_out,
    'candidates_matched', v_matched,
    'candidates_scanned', v_scanned,
    'truncated', v_matched > v_scanned,
    'window_column', 'coalesce(ended_at, started_at, updated_at)',
    'failed', v_failed,
    'failed_tournaments', to_jsonb(v_fail_ids),
    'first_error', v_first_err
  );
END;
$$;


ALTER FUNCTION public.fn_tournament_payout_sweep(p_days integer, p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- TOC entry 49193 (class 0 OID 0)
-- Dependencies: 8079
-- Name: FUNCTION fn_tournament_payout_sweep(p_days integer, p_apply boolean, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_tournament_payout_sweep(p_days integer, p_apply boolean, p_limit integer) IS 'Reconciles COMPLETED tournaments finished within p_days. The window is measured on coalesce(ended_at, started_at, updated_at) -- NOT updated_at, which is never maintained and holds row-creation time (2026-08-29). Returns candidates_matched/candidates_scanned/truncated so a limit that silently shrinks the window is visible to the caller.';


--
-- TOC entry 7207 (class 1255 OID 31487572)
-- Name: fn_tournament_payout_terms_committed_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_payout_terms_committed_v1(p_tournament_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.tournaments t
                  WHERE t.id=p_tournament_id AND t.prize_pool_finalized IS TRUE)
     OR EXISTS (SELECT 1 FROM public.tournament_entry_close_receipts r
                 WHERE r.tournament_id=p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_place_settlement_batches b
                 WHERE b.tournament_id=p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_satellite_settlement_batches b
                 WHERE b.tournament_id=p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_final_table_deal_batches b
                 WHERE b.tournament_id=p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_terminal_settlements h
                 WHERE h.tournament_id=p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_cancellation_receipts c
                 WHERE c.tournament_id=p_tournament_id)
     OR EXISTS (SELECT 1 FROM public.tournament_obligations o
                 WHERE o.tournament_id=p_tournament_id
                   AND o.kind IN ('place','bubble_protection','final_table_deal','late_reg_adjustment'))
     OR EXISTS (SELECT 1 FROM public.tournament_payouts p
                 WHERE p.tournament_id=p_tournament_id
                   AND (p.source IN ('structure','reconcile','hu_shortfall','late_reg_adjustment',
                         'clawback','spin_backpay','overlay_backpay','final_table_deal','bubble_protection')
                        OR public.fn_tournament_payout_key_is_place_evidence(
                             p.tournament_id,p.idempotency_key)));
$$;


