--
-- TOC entry 7652 (class 1255 OID 18003841)
-- Name: fn_tournament_prize_disbursement_audit(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_prize_disbursement_audit(p_hours integer DEFAULT 24) RETURNS TABLE(tournament_id uuid, name text, variant text, prize_pool numeric, disbursed numeric, acknowledged numeric, excess numeric, ended_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH t AS (
    SELECT x.id, x.name, x.variant,
           -- A Spin promises buy_in x multiplier, paid from the spin reserve;
           -- its prize_pool column is the buy-ins and is not what it owes.
           CASE WHEN x.variant = 'spin' AND COALESCE(x.spin_multiplier, 0) > 0
                THEN GREATEST(x.prize_pool::numeric,
                  round(COALESCE(x.buy_in_amount,0) * x.spin_multiplier, 2)
                  + CASE
                      WHEN e.overlay_in > 0 AND e.overlay_in < 'Infinity'::numeric
                       AND e.overlay_in = COALESCE((
                         SELECT sum(l.amount) FROM public.chip_ledger l
                          WHERE l.tournament_id = x.id
                            AND l.category = 'overlay'
                            AND l.to_type = 'prize_liability'
                            AND l.to_entity_id = x.id
                            AND l.from_type IN ('union_bank','club_treasury')
                            AND l.status = 'posted'
                            AND l.amount > 0 AND l.amount < 'Infinity'::numeric
                       ), 0)
                      THEN e.overlay_in ELSE 0
                    END)
                ELSE x.prize_pool::numeric END AS pool,
           x.ended_at
      FROM public.tournaments x
      LEFT JOIN public.tournament_escrow e ON e.tournament_id = x.id
     WHERE x.status = 'COMPLETED'
       AND x.ended_at > now() - make_interval(hours => GREATEST(COALESCE(p_hours,24),1))
       AND COALESCE(x.prize_pool,0) > 0
  ), paid AS (
    SELECT w.related_entity_id tid, round(sum(w.amount),2) amt
      FROM public.wallet_transactions w
      JOIN t ON t.id = w.related_entity_id
     WHERE w.type = 'credit' AND w.category = 'prize'
     GROUP BY 1
  )
  SELECT t.id, t.name, t.variant, t.pool,
         COALESCE(p.amt,0),
         COALESCE(b.amount,0),
         round(COALESCE(p.amt,0) - t.pool - COALESCE(b.amount,0), 2),
         t.ended_at
    FROM t
    LEFT JOIN paid p ON p.tid = t.id
    LEFT JOIN public.tournament_conservation_baseline b ON b.tournament_id = t.id
   WHERE round(COALESCE(p.amt,0) - t.pool - COALESCE(b.amount,0), 2) > 0.005;
$$;


ALTER FUNCTION public.fn_tournament_prize_disbursement_audit(p_hours integer) OWNER TO postgres;

--
-- TOC entry 9213 (class 1255 OID 57106537)
-- Name: fn_tournament_progress_metrics(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_progress_metrics(p_stalled_minutes integer DEFAULT 15, p_break_grace_minutes integer DEFAULT 10) RETURNS TABLE(stalled_running integer, overdue_breaks integer, progressing_running integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH bounds AS (
    SELECT statement_timestamp() - make_interval(mins =>
             LEAST(1440, GREATEST(1, COALESCE(p_stalled_minutes,15)))) AS hand_cutoff,
           statement_timestamp() - make_interval(mins =>
             LEAST(1440, GREATEST(1, COALESCE(p_break_grace_minutes,10)))) AS break_cutoff
  )
  SELECT
    count(*) FILTER (
      WHERE NOT COALESCE(t.on_break,false)
        -- A recently completed add-on is a legitimate interval without hands.
        AND COALESCE(t.addon_period_ends_at,'-infinity'::timestamptz) < b.hand_cutoff
        AND NOT EXISTS (
          SELECT 1 FROM public.hand_history h
           WHERE h.tournament_id=t.id AND h.created_at>b.hand_cutoff
        )
    )::integer,
    count(*) FILTER (
      WHERE COALESCE(t.on_break,false)
        -- A missing end timestamp is the pre-countdown state, not an unlimited
        -- exemption. Give it the normal five-minute break plus the grace.
        AND GREATEST(
          COALESCE(t.break_ends_at,
                   t.break_started_at + interval '5 minutes',
                   COALESCE(t.started_at,t.start_time,t.created_at) + interval '5 minutes'),
          COALESCE(t.addon_period_ends_at,'-infinity'::timestamptz)
        ) < b.break_cutoff
    )::integer,
    -- The denominator's other half (2026-09-26): the same eligible events
    -- that DID deal a hand in the window.
    count(*) FILTER (
      WHERE NOT COALESCE(t.on_break,false)
        AND COALESCE(t.addon_period_ends_at,'-infinity'::timestamptz) < b.hand_cutoff
        AND EXISTS (
          SELECT 1 FROM public.hand_history h
           WHERE h.tournament_id=t.id AND h.created_at>b.hand_cutoff
        )
    )::integer
  FROM public.tournaments t CROSS JOIN bounds b
  WHERE t.status='RUNNING'
    -- Immutable recorded format includes old numeric and new NULL MTTs.
    -- Historical seat-first satellites retain their own lifecycle.
    AND t.format_contract IN ('mtt-v1','mtt-v2')
    AND COALESCE(t.started_at,t.start_time,t.created_at)<b.hand_cutoff;
$$;


ALTER FUNCTION public.fn_tournament_progress_metrics(p_stalled_minutes integer, p_break_grace_minutes integer) OWNER TO postgres;

--
-- TOC entry 3310 (class 1255 OID 18266852)
-- Name: fn_tournament_rake_settlement_check(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_rake_settlement_check(p_grace_minutes integer DEFAULT 30, p_since_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_grace    integer := GREATEST(COALESCE(p_grace_minutes, 30), 1);
  v_days     integer := GREATEST(COALESCE(p_since_days, 7), 1);
  v_missing  integer := 0;
  v_owed     numeric := 0;
  v_oldest   timestamptz;
  v_ids      uuid[];
  v_verdict  text := 'pass';
  v_severity text;
  v_message  text;
  v_context  jsonb;
  v_alerts   integer := 0;
BEGIN
  WITH unsettled AS (
    SELECT t.id,
           t.ended_at,
           (SELECT COALESCE(sum(r.rake_amount), 0) FROM public.rake_records r
             WHERE r.tournament_id = t.id AND r.is_tournament) AS banked
      FROM public.tournaments t
     WHERE upper(COALESCE(t.status, '')) IN ('COMPLETED', 'CANCELLED', 'CANCELED')
       AND t.ended_at IS NOT NULL
       AND t.ended_at > now() - make_interval(days => v_days)
       AND t.ended_at < now() - make_interval(mins => v_grace)
       AND EXISTS (SELECT 1 FROM public.rake_records r
                    WHERE r.tournament_id = t.id AND r.is_tournament)
       AND NOT EXISTS (SELECT 1 FROM public.tournament_rake_settlements s
                        WHERE s.tournament_id = t.id AND s.settled_at IS NOT NULL)
       -- A fully refunded cancellation has no fee-bank movement to make.
       -- Its independent exact-zero accounting receipt is still mandatory.
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_cancellation_receipts c
         JOIN public.accounting_tournament_fee_recognitions a ON a.tournament_id=c.tournament_id
         WHERE c.tournament_id=t.id AND c.total_rake_after=0
           AND c.fees_reversed=c.total_rake_before AND a.net_rake=0
           AND a.status IN('cancelled','banked_accrual_deferred')
           AND public.fn_accounting_tournament_terminal_fee_receipt(t.id)->>'bank_receipt_kind'='none')
  )
  SELECT count(*),
         COALESCE(sum(banked), 0),
         min(ended_at),
         COALESCE((array_agg(id ORDER BY ended_at))[1:20], ARRAY[]::uuid[])
    INTO v_missing, v_owed, v_oldest, v_ids
    FROM unsettled;

  IF v_missing > 0 THEN
    v_verdict  := 'rake_never_settled';
    v_severity := CASE WHEN v_missing >= 5 OR v_owed >= 50 THEN 'critical' ELSE 'warning' END;
    v_message  := format(
      '%s terminal tournament(s) have fee evidence and no completed bank or exact-zero cancellation receipt after '
      '%s minutes; their net fee evidence totals %s. Oldest finished %s. ',
      v_missing, v_grace, round(v_owed, 2), v_oldest);
  END IF;

  v_context := jsonb_build_object(
    'grace_minutes',  v_grace,
    'window_days',    v_days,
    'missing_count',  v_missing,
    'rake_unpaid',    round(v_owed, 2),
    'oldest_ended_at', v_oldest,
    'sample_games',   to_jsonb(v_ids),
    'verdict',        v_verdict,
    'detail',         'the canonical tournament terminal authority owns fee banking and recognition; this detector only reports missing custody receipts. Deferred accrual remains blocked by weekly source-quality checks');

  IF v_severity IS NOT NULL THEN
    INSERT INTO public.financial_alerts (severity, source, message, context)
    SELECT v_severity, 'fn_tournament_rake_settlement_check', v_message, v_context
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source = 'fn_tournament_rake_settlement_check'
          AND fa.resolved IS NOT TRUE
          AND fa.context->>'verdict' = v_verdict);
    IF FOUND THEN v_alerts := 1; END IF;
  END IF;

  RETURN v_context || jsonb_build_object('ok', true, 'alerts_raised', v_alerts);
END;
$$;


ALTER FUNCTION public.fn_tournament_rake_settlement_check(p_grace_minutes integer, p_since_days integer) OWNER TO postgres;

--
-- TOC entry 8928 (class 1255 OID 55217128)
-- Name: fn_tournament_record_acceptance(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_record_acceptance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.accepted_event_operations
    (event_kind, event_id, parent_event_id, club_id, union_id, accepted_at, accepted_by,
     authorization_basis, capability_versions, concluded_at, conclusion)
  VALUES
    ('tournament', NEW.id, NEW.parent_tournament_id, NEW.club_id, NEW.union_id, now(), auth.uid(),
     '{"operator_access":"legacy_free","recorded_by":"acceptance_trigger"}'::jsonb,
     COALESCE((SELECT jsonb_object_agg(c.capability_id, c.rule_version)
                 FROM public.platform_capabilities c
                WHERE c.readiness IN ('deployed','production_verified')), '{}'::jsonb),
     CASE WHEN NEW.status IN ('COMPLETED','CANCELLED') THEN now() END,
     CASE NEW.status WHEN 'COMPLETED' THEN 'completed' WHEN 'CANCELLED' THEN 'cancelled' END)
  ON CONFLICT (event_kind, event_id) DO NOTHING;
  RETURN NULL;
END
$$;


ALTER FUNCTION public.fn_tournament_record_acceptance() OWNER TO postgres;

--
-- TOC entry 6324 (class 1255 OID 55217129)
