--
-- TOC entry 7237 (class 1255 OID 2054969)
-- Name: fn_tournament_register_counter(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_register_counter(p_tournament_id uuid, p_buy_in numeric) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_new_count INT;
  v_new_pool NUMERIC;
  v_max INT;
BEGIN
  UPDATE public.club_tournaments
  SET registered_count = registered_count + 1,
      prize_pool = COALESCE(prize_pool, 0) + p_buy_in
  WHERE id = p_tournament_id
  RETURNING registered_count, prize_pool, max_players
  INTO v_new_count, v_new_pool, v_max;

  IF v_new_count IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Tournament not found');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'registered_count', v_new_count,
    'prize_pool', v_new_pool,
    'max_players', v_max
  );
END;
$$;


ALTER FUNCTION public.fn_tournament_register_counter(p_tournament_id uuid, p_buy_in numeric) OWNER TO postgres;

--
-- TOC entry 5093 (class 1255 OID 175646097)
-- Name: fn_tournament_schedule_board_is_hard_coded(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_schedule_board_is_hard_coded() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF COALESCE(auth.role(), '') IN ('authenticated', 'anon')
     AND (
       (TG_OP <> 'INSERT' AND (OLD.config->>'type' = 'fixed_board' OR OLD.config ? 'fixedBoard'))
       OR (TG_OP <> 'DELETE' AND (NEW.config->>'type' = 'fixed_board' OR NEW.config ? 'fixedBoard'))
     ) THEN
    RAISE EXCEPTION 'This event is on the hard coded daily board. Its times are set by the engine and cannot be changed here.'
      USING ERRCODE = '42501';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


