--
-- TOC entry 7812 (class 1255 OID 55308010)
-- Name: fn_tournament_stage_view(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_stage_view(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    SET statement_timeout TO '10s'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_t public.tournaments%ROWTYPE;
  v_plan public.tournament_stage_plans%ROWTYPE;
  v_stages jsonb;
  v_current integer;
  v_current_state text;
  v_next jsonb;
  v_bag_stage integer;
  v_my_bag jsonb;
  v_my_seat jsonb;
  v_leaders jsonb;
  v_bagged_players integer;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;
  IF NOT public.fn_caller_session_is_live() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'session_revoked');
  END IF;
  IF p_tournament_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_request');
  END IF;

  SELECT * INTO v_t FROM public.tournaments WHERE id = p_tournament_id;
  -- The same visibility as the tournaments SELECT policy; an event the caller
  -- could not read answers exactly like one that does not exist.
  IF NOT FOUND
     OR NOT ((v_t.club_id IS NULL AND v_t.union_id IS NULL)
             OR COALESCE(public.fn_poker_can_read_games(COALESCE(v_t.union_id, v_t.club_id)), false)) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found');
  END IF;

  SELECT * INTO v_plan FROM public.tournament_stage_plans WHERE tournament_id = p_tournament_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'tournament_id', p_tournament_id,
      'status', v_t.status, 'plan', NULL);
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
           'stage_no', s.stage_no,
           'day_no', s.day_no,
           'end_after_level', s.end_after_level,
           'scheduled_start_utc', to_char(s.scheduled_start_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
           'schedule_generation', s.schedule_generation,
           'state', s.state) ORDER BY s.stage_no)
    INTO v_stages
    FROM public.tournament_stages s
   WHERE s.tournament_id = p_tournament_id;

  -- Where the event is: the latest stage that has played (running, ending or
  -- bagged); before the launch, stage 1.
  SELECT s.stage_no, s.state INTO v_current, v_current_state
    FROM public.tournament_stages s
   WHERE s.tournament_id = p_tournament_id
     AND s.state IN ('running', 'day_ending', 'bagged')
   ORDER BY s.stage_no DESC
   LIMIT 1;
  IF v_current IS NULL THEN
    SELECT s.stage_no, s.state INTO v_current, v_current_state
      FROM public.tournament_stages s
     WHERE s.tournament_id = p_tournament_id
     ORDER BY s.stage_no
     LIMIT 1;
  END IF;

  SELECT jsonb_build_object(
           'stage_no', s.stage_no,
           'day_no', s.day_no,
           'scheduled_start_utc', to_char(s.scheduled_start_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
           'time_zone', v_plan.time_zone,
           'schedule_generation', s.schedule_generation,
           'state', s.state)
    INTO v_next
    FROM public.tournament_stages s
   WHERE s.tournament_id = p_tournament_id
     AND s.stage_no > v_current
     AND s.state IN ('planned', 'scheduled', 'resuming')
     AND s.scheduled_start_utc IS NOT NULL
   ORDER BY s.stage_no
   LIMIT 1;

  -- The most recent bag, if any.
  SELECT max(b.stage_no) INTO v_bag_stage
    FROM public.tournament_stage_bags b
   WHERE b.tournament_id = p_tournament_id;

  IF v_bag_stage IS NOT NULL THEN
    -- The caller's own bag and nobody else's.
    SELECT jsonb_build_object(
             'stage_no', b.stage_no,
             'day_no', b.stage_no,
             'stack', b.stack,
             'bounty_head', b.bounty_head)
      INTO v_my_bag
      FROM public.tournament_stage_bags b
     WHERE b.tournament_id = p_tournament_id
       AND b.stage_no = v_bag_stage
       AND b.user_id = v_uid;

    SELECT count(*) INTO v_bagged_players
      FROM public.tournament_stage_bags b
     WHERE b.tournament_id = p_tournament_id AND b.stage_no = v_bag_stage;

    -- Post-bag chip leaders: display name and stack only.
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'rank', l.rank, 'display_name', l.display_name, 'stack', l.stack) ORDER BY l.rank), '[]'::jsonb)
      INTO v_leaders
      FROM (
        SELECT row_number() OVER (ORDER BY b.stack DESC, COALESCE(NULLIF(btrim(p.username), ''), 'Player'), b.id) AS rank,
               COALESCE(NULLIF(btrim(p.username), ''), 'Player') AS display_name,
               b.stack
          FROM public.tournament_stage_bags b
          LEFT JOIN public.tournament_players p ON p.id = b.registration_id
         WHERE b.tournament_id = p_tournament_id AND b.stage_no = v_bag_stage
         ORDER BY b.stack DESC, COALESCE(NULLIF(btrim(p.username), ''), 'Player'), b.id
         LIMIT 10) l;
  END IF;

  -- The caller's seat for the stage now running, once their entitlement for
  -- it has been seated: the chair they actually hold now.
  IF v_t.status = 'RUNNING' AND v_current_state IN ('running', 'day_ending') AND EXISTS (
       SELECT 1 FROM public.tournament_qualification_entitlements e
        WHERE e.tournament_id = p_tournament_id
          AND e.user_id = v_uid
          AND e.target_stage_no = v_current
          AND e.state = 'consumed') THEN
    SELECT jsonb_build_object(
             'stage_no', v_current,
             'day_no', v_current,
             'table_id', s.table_id,
             'table_name', tb.name,
             'seat_number', s.seat_number)
      INTO v_my_seat
      FROM public.table_seats s
      JOIN public.tables tb ON tb.id = s.table_id
     WHERE tb.tournament_id = p_tournament_id
       AND s.user_id = v_uid
       AND s.left_at IS NULL
     ORDER BY s.joined_at DESC NULLS LAST
     LIMIT 1;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'tournament_id', p_tournament_id,
    'status', v_t.status,
    'plan', jsonb_build_object(
      'rule_version', v_plan.rule_version,
      'time_zone', v_plan.time_zone,
      'stage_count', v_plan.stage_count),
    'stages', COALESCE(v_stages, '[]'::jsonb),
    'current_stage', jsonb_build_object('stage_no', v_current, 'day_no', v_current, 'state', v_current_state),
    'next_start', v_next,
    'bag', CASE WHEN v_bag_stage IS NULL THEN NULL
                ELSE jsonb_build_object('stage_no', v_bag_stage, 'day_no', v_bag_stage,
                                        'players', v_bagged_players) END,
    'my_bag', v_my_bag,
    'my_seat', v_my_seat,
    'chip_leaders', COALESCE(v_leaders, '[]'::jsonb));
END
$$;


ALTER FUNCTION public.fn_tournament_stage_view(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 7181 (class 1255 OID 30341951)
-- Name: fn_tournament_table_inherits_committed_blinds(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_table_inherits_committed_blinds() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_level integer; v_state jsonb;
BEGIN
  IF NEW.tournament_id IS NULL THEN RETURN NEW; END IF;
  SELECT current_level,blind_level_state INTO v_level,v_state
    FROM public.tournaments WHERE id=NEW.tournament_id FOR SHARE;
  IF v_state IS NULL THEN
    -- No committed level to inherit. The display string is still a function of
    -- this row's own blinds, so derive it rather than trusting the caller:
    -- that is what let 'undefined/undefined' and stale levels be stored, and
    -- what left a minutely cron UPDATE as the only thing holding the invariant
    -- for the 167,997 tournaments with no blind_level_state.
    IF NEW.small_blind IS NOT NULL AND NEW.big_blind IS NOT NULL THEN
      NEW.stakes := trim_scale(NEW.small_blind)::text||'/'||trim_scale(NEW.big_blind)::text;
    END IF;
    RETURN NEW;
  END IF;
  IF (v_state->>'index')::integer IS DISTINCT FROM v_level THEN
    RAISE EXCEPTION 'Tournament table cannot inherit an unconfirmed blind level';
  END IF;
  NEW.small_blind:=(v_state->>'small_blind')::numeric;
  NEW.big_blind:=(v_state->>'big_blind')::numeric;
  NEW.ante:=(v_state->>'ante')::numeric;
  NEW.stakes:=trim_scale(NEW.small_blind)::text||'/'||trim_scale(NEW.big_blind)::text;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_tournament_table_inherits_committed_blinds() OWNER TO postgres;

--
-- TOC entry 3613 (class 1255 OID 25705952)
-- Name: fn_tournament_table_terminal_close_is_irreversible(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_table_terminal_close_is_irreversible() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_new_status text;
  v_ended_at timestamptz;
  v_permit_consumed boolean := false;
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- Tournament tables remain durable by default.  The only exception is an
    -- exact one-shot permit created after the reserved certification helper's
    -- complete no-activity proof in this same transaction.
    IF OLD.tournament_id IS NOT NULL THEN
      DELETE FROM smarter_private.ca_welcome_certification_table_delete_permits p
       WHERE p.transaction_id=pg_current_xact_id()
         AND p.table_id=OLD.id
         AND p.tournament_id=OLD.tournament_id
         AND p.club_id=OLD.club_id
       RETURNING true INTO v_permit_consumed;
      IF NOT COALESCE(v_permit_consumed,false) THEN
        RAISE EXCEPTION 'tournament table % is durable and cannot be deleted',OLD.id
          USING ERRCODE = '55000';
      END IF;
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.terminal_closed_at IS NOT NULL THEN
      RAISE EXCEPTION 'new table % cannot supply a terminal marker',NEW.id
        USING ERRCODE = '55000';
    END IF;
    IF NEW.tournament_id IS NOT NULL THEN
      SELECT upper(COALESCE(t.status::text,'')) INTO v_new_status
        FROM public.tournaments t
       WHERE t.id = NEW.tournament_id
       FOR SHARE;
      IF v_new_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
        RAISE EXCEPTION 'cannot add table % to terminal tournament %',
          NEW.id,NEW.tournament_id USING ERRCODE = '55000';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'table identity % is immutable',OLD.id
      USING ERRCODE = '55000';
  END IF;

  IF NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
     AND (NEW.tournament_id IS NOT NULL OR OLD.tournament_id IS NOT NULL) THEN
    RAISE EXCEPTION 'table % tournament association is immutable',OLD.id
      USING ERRCODE = '55000';
  END IF;

  IF OLD.terminal_closed_at IS NOT NULL THEN
    IF NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
       OR NEW.terminal_closed_at IS DISTINCT FROM OLD.terminal_closed_at
       OR lower(COALESCE(NEW.status::text,'')) <> 'closed'
       OR lower(COALESCE(NEW.lifecycle,'')) <> 'closed'
       OR NEW.current_players IS DISTINCT FROM 0 THEN
      RAISE EXCEPTION 'terminal tournament table % cannot reopen or move',OLD.id
        USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.tournament_id IS NOT NULL THEN
    SELECT upper(COALESCE(t.status::text,'')),t.ended_at
      INTO v_new_status,v_ended_at
      FROM public.tournaments t WHERE t.id = NEW.tournament_id;
    IF v_new_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
      IF NEW.current_players IS DISTINCT FROM 0 THEN
        RAISE EXCEPTION 'table % cannot reopen terminal tournament %',
          NEW.id,NEW.tournament_id USING ERRCODE = '55000';
      END IF;
      NEW.status := 'closed';
      NEW.lifecycle := 'closed';
      NEW.terminal_closed_at := COALESCE(v_ended_at,transaction_timestamp());
    ELSIF NEW.terminal_closed_at IS NOT NULL THEN
      RAISE EXCEPTION 'live tournament table % cannot supply a terminal marker',NEW.id
        USING ERRCODE = '55000';
    END IF;
  ELSIF NEW.terminal_closed_at IS NOT NULL THEN
    RAISE EXCEPTION 'unscoped table % cannot supply a terminal marker',NEW.id
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_tournament_table_terminal_close_is_irreversible() OWNER TO postgres;

