--
-- TOC entry 7993 (class 1255 OID 4477812)
-- Name: fn_tournament_unregister_counter(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_tournament_unregister_counter(p_tournament_id uuid, p_buy_in numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  UPDATE tournaments
     SET current_players = GREATEST(COALESCE(current_players, 0) - 1, 0),
         prize_pool      = GREATEST(COALESCE(prize_pool, 0) - COALESCE(p_buy_in, 0), 0),
         updated_at      = NOW()
   WHERE id = p_tournament_id
   RETURNING COALESCE(current_players, 0) INTO v_count;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'tournament not found');
  END IF;

  RETURN jsonb_build_object('success', true, 'current_players', v_count);
END;
$$;


