--
-- TOC entry 9083 (class 1255 OID 25761339)
-- Name: fn_training_reward_award(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_reward_award(p_user_id uuid, p_action_key text, p_reference_id text, p_target_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF p_user_id IS NULL OR p_action_key IS NULL THEN RETURN; END IF;
    -- Fail closed on a user that does not exist, same as the social helper.
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id) THEN RETURN; END IF;
    PERFORM public.award_diamonds_v2(p_user_id, p_action_key, p_reference_id, p_target_id,
                                     jsonb_build_object('source','db_trigger'));
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[training-reward] % failed for user %: %', p_action_key, p_user_id, SQLERRM;
    RETURN;
END $$;


ALTER FUNCTION public.fn_training_reward_award(p_user_id uuid, p_action_key text, p_reference_id text, p_target_id text) OWNER TO postgres;

--
-- TOC entry 9158 (class 1255 OID 23317584)
-- Name: fn_training_session_cache_completion(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_session_cache_completion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
    v_question_id text;
    v_policy_checksum text;
    v_history jsonb := CASE WHEN jsonb_typeof(NEW.hand_history) = 'array'
        THEN NEW.hand_history ELSE '[]'::jsonb END;
BEGIN
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(v_history) AS entry(value)
        CROSS JOIN LATERAL (VALUES (coalesce(
            nullif(entry.value ->> 'questionId', ''),
            nullif(entry.value #>> '{handData,questionId}', '')
        ))) AS resolved(question_id)
        WHERE question_id IS NOT NULL
          AND coalesce(
              nullif(entry.value ->> 'policyChecksum', ''),
              nullif(entry.value #>> '{handData,policyChecksum}', ''),
              ''
          ) !~ '^[0-9a-f]{64}$'
    ) THEN
        RAISE EXCEPTION 'training_session_question_missing_policy_checksum';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(v_history) AS entry(value)
        CROSS JOIN LATERAL (VALUES (coalesce(
            nullif(entry.value ->> 'questionId', ''),
            nullif(entry.value #>> '{handData,questionId}', '')
        ))) AS resolved(question_id)
        WHERE question_id IS NOT NULL
        GROUP BY question_id
        HAVING count(DISTINCT nullif(coalesce(
            entry.value ->> 'policyChecksum',
            entry.value #>> '{handData,policyChecksum}'
        ), '')) > 1
    ) THEN
        RAISE EXCEPTION 'training_session_contains_conflicting_policy_checksums';
    END IF;

    FOR v_question_id, v_policy_checksum IN
        SELECT
            question_id,
            max(nullif(coalesce(
                entry.value ->> 'policyChecksum',
                entry.value #>> '{handData,policyChecksum}'
            ), '')) AS policy_checksum
        FROM jsonb_array_elements(v_history) AS entry(value)
        CROSS JOIN LATERAL (VALUES (coalesce(
            nullif(entry.value ->> 'questionId', ''),
            nullif(entry.value #>> '{handData,questionId}', '')
        ))) AS resolved(question_id)
        WHERE question_id IS NOT NULL
        GROUP BY question_id
    LOOP
        PERFORM public.fn_training_cache_record_event(
            'completed',
            'training-session:' || NEW.id::text || ':'
                || encode(extensions.digest(v_question_id, 'sha256'), 'hex'),
            v_question_id,
            NEW.user_id,
            NULL,
            jsonb_build_object(
                'sessionId', NEW.id,
                'gameId', NEW.game_id,
                'policyChecksum', v_policy_checksum
            ),
            coalesce(NEW.created_at, now()),
            v_policy_checksum
        );
    END LOOP;
    RETURN NEW;
END;
$_$;


ALTER FUNCTION public.fn_training_session_cache_completion() OWNER TO postgres;

