--
-- TOC entry 7230 (class 1255 OID 26851254)
-- Name: fn_training_solver_scope_transition_guard_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_solver_scope_transition_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_parent_count integer;
  v_child_count integer;
  v_target_count integer;
  v_lineage_valid boolean;
BEGIN
  IF NEW.admission_mode = 'held' AND NEW.partition_count IS NULL AND NEW.partition_index IS NULL
     AND ROW(NEW.machine_id, NEW.solver_version, NEW.solver_binary_checksum, NEW.pipeline_commit, NEW.manifest_version, NEW.manifest_checksum)
       IS NOT DISTINCT FROM ROW(OLD.machine_id, OLD.solver_version, OLD.solver_binary_checksum, OLD.pipeline_commit, OLD.manifest_version, OLD.manifest_checksum)
     AND NEW.machine_id = 'M1' AND NEW.solver_version = 'PioSOLVER-pro 3.8.0 (Sep 22 2025, 11:05:45)' AND NEW.solver_binary_checksum = 'e21ea7ad1dbc2a9d826c25ac264688f632dd461b92de2bc35a53f6b78bcf5ceb' AND NEW.manifest_version = '5'
     AND ((NEW.pipeline_commit = '1ccf3907cf3298e24609eb6fbd903023d91dbddf' AND NEW.manifest_checksum = 'b27ad1f3575e106d7d7f73bb4655e94398955a1275ae1fea9b3af7f574dbece8')
       OR (NEW.pipeline_commit = '002cb37bbd89df86f4cc054fcf370f794b14f413' AND NEW.manifest_checksum = '3115537d7169913cac08db6a40797af7b516e33d1e4faa8d51310704aaf58a25')) THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('training-solver-ingest-scope:M1', 0));
    RETURN NEW;
  END IF;
  IF OLD.admission_mode IS DISTINCT FROM 'held'
     OR NEW.machine_id IS DISTINCT FROM OLD.machine_id
     OR NEW.solver_version IS DISTINCT FROM OLD.solver_version
     OR NEW.solver_binary_checksum IS DISTINCT FROM OLD.solver_binary_checksum
     OR NEW.pipeline_commit IS DISTINCT FROM OLD.pipeline_commit
     OR NEW.manifest_version IS DISTINCT FROM OLD.manifest_version
     OR NEW.manifest_checksum IS DISTINCT FROM OLD.manifest_checksum
     OR NEW.admission_mode NOT IN ('backlog', 'bounded_canary') THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000', MESSAGE = 'TRAINING_SOLVER_INGEST_SCOPE_IMMUTABLE';
  END IF;

  -- Serialize activation per physical worker. M1 and M2 intentionally use
  -- independent advisory keys, so either machine may run while the other does.
  -- Both backlog and bounded-canary transitions take this lock; otherwise two
  -- concurrent held->active transactions could each miss the other.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'training-solver-ingest-scope:' || OLD.machine_id,
      0
    )
  );

  IF EXISTS (
    SELECT 1
    FROM public.training_solver_ingest_scopes other_scope
    JOIN public.training_solver_provenance_authority other_authority
      USING (
        machine_id, solver_version, solver_binary_checksum, pipeline_commit,
        manifest_version, manifest_checksum
      )
    WHERE other_scope.machine_id = OLD.machine_id
      AND other_scope.admission_mode IN ('backlog', 'bounded_canary')
      AND other_authority.retired_at IS NULL
      AND (
        other_scope.solver_version IS DISTINCT FROM OLD.solver_version
        OR other_scope.solver_binary_checksum IS DISTINCT FROM
          OLD.solver_binary_checksum
        OR other_scope.pipeline_commit IS DISTINCT FROM OLD.pipeline_commit
        OR other_scope.manifest_version IS DISTINCT FROM OLD.manifest_version
        OR other_scope.manifest_checksum IS DISTINCT FROM OLD.manifest_checksum
      )
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000',
      MESSAGE = 'TRAINING_SOLVER_MACHINE_INGEST_SCOPE_ALREADY_ACTIVE';
  END IF;

  SELECT count(*), count(*) FILTER (WHERE target.target_role = 'parent'),
         count(*) FILTER (WHERE target.target_role = 'child')
  INTO v_target_count, v_parent_count, v_child_count
  FROM public.training_solver_bounded_canary_targets target
  WHERE target.machine_id = OLD.machine_id
    AND target.solver_version = OLD.solver_version
    AND target.solver_binary_checksum = OLD.solver_binary_checksum
    AND target.pipeline_commit = OLD.pipeline_commit
    AND target.manifest_version = OLD.manifest_version
    AND target.manifest_checksum = OLD.manifest_checksum;

  IF (NEW.admission_mode = 'backlog' AND v_target_count <> 0)
     OR (NEW.admission_mode = 'bounded_canary'
         AND (v_target_count <> 2 OR v_parent_count <> 1 OR v_child_count <> 1)) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514', MESSAGE = 'TRAINING_SOLVER_INGEST_SCOPE_TARGET_SET_INVALID';
  END IF;
  IF NEW.admission_mode = 'bounded_canary' THEN
    SELECT
      left(child.scenario_hash, char_length('turn_' || parent.scenario_hash)) =
        'turn_' || parent.scenario_hash
      AND char_length(child.scenario_hash) =
        char_length('turn_' || parent.scenario_hash) + 2
      AND right(child.scenario_hash, 2) ~ '^[2-9TJQKA][cdhs]$'
      AND starts_with(child.node, parent.node || ':')
      AND child.hero_position = parent.hero_position
    INTO v_lineage_valid
    FROM public.training_solver_bounded_canary_targets parent
    JOIN public.training_solver_bounded_canary_targets child
      ON child.machine_id = parent.machine_id
     AND child.solver_version = parent.solver_version
     AND child.solver_binary_checksum = parent.solver_binary_checksum
     AND child.pipeline_commit = parent.pipeline_commit
     AND child.manifest_version = parent.manifest_version
     AND child.manifest_checksum = parent.manifest_checksum
     AND child.target_role = 'child'
    WHERE parent.machine_id = OLD.machine_id
      AND parent.solver_version = OLD.solver_version
      AND parent.solver_binary_checksum = OLD.solver_binary_checksum
      AND parent.pipeline_commit = OLD.pipeline_commit
      AND parent.manifest_version = OLD.manifest_version
      AND parent.manifest_checksum = OLD.manifest_checksum
      AND parent.target_role = 'parent';
    IF v_lineage_valid IS DISTINCT FROM true THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514', MESSAGE = 'TRAINING_SOLVER_CANARY_LINEAGE_INVALID';
    END IF;
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION public.fn_training_solver_scope_transition_guard_v1() OWNER TO postgres;

--
-- TOC entry 8539 (class 1255 OID 24588207)
-- Name: fn_training_streak_activity_immutable_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_streak_activity_immutable_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  -- PostgreSQL executes child-table DELETE triggers during an ON DELETE
  -- CASCADE. Account erasure is the sole legitimate delete path for this
  -- otherwise immutable authority ledger.
  IF TG_OP = 'DELETE' AND NOT EXISTS (
    SELECT 1 FROM auth.users users WHERE users.id = OLD.user_id
  ) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION USING
    ERRCODE = '23514',
    MESSAGE = 'TRAINING_STREAK_ACTIVITY_DAY_IMMUTABLE';
END;
$$;


ALTER FUNCTION public.fn_training_streak_activity_immutable_v1() OWNER TO postgres;

--
-- TOC entry 3337 (class 1255 OID 24588221)
-- Name: fn_training_streak_summary_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_streak_summary_v1(p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  WITH ordered_days AS (
    SELECT
      activity_date,
      activity_date
        - row_number() OVER (ORDER BY activity_date)::integer AS island_key
    FROM public.training_streak_activity_days
    WHERE user_id = p_user_id
  ), islands AS (
    SELECT
      min(activity_date) AS start_date,
      max(activity_date) AS last_date,
      count(*)::integer AS day_count
    FROM ordered_days
    GROUP BY island_key
  ), ranked AS (
    SELECT
      islands.*,
      max(day_count) OVER () AS longest_count,
      row_number() OVER (ORDER BY last_date DESC) AS recency_rank
    FROM islands
  )
  SELECT jsonb_build_object(
    'current', day_count,
    'longest', longest_count,
    'startDate', start_date,
    'lastDate', last_date
  )
  FROM ranked
  WHERE recency_rank = 1;
$$;


ALTER FUNCTION public.fn_training_streak_summary_v1(p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 5692 (class 1255 OID 23159396)
-- Name: fn_training_verified_leaderboard_rank_v2(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_verified_leaderboard_rank_v2(p_user_id uuid, p_period_type text, p_period_key text, p_dimension_type text, p_dimension_key text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH mine AS (
    SELECT *
    FROM public.training_verified_leaderboard
    WHERE user_id = p_user_id
      AND period_type = p_period_type
      AND period_key = p_period_key
      AND dimension_type = p_dimension_type
      AND dimension_key = p_dimension_key
  )
  SELECT jsonb_build_object(
    'myRank', (
      SELECT 1 + (
        SELECT count(*)
        FROM public.training_verified_leaderboard better
        WHERE better.period_type = mine.period_type
          AND better.period_key = mine.period_key
          AND better.dimension_type = mine.dimension_type
          AND better.dimension_key = mine.dimension_key
          AND (
            better.accuracy > mine.accuracy
            OR (
              better.accuracy = mine.accuracy
              AND better.questions_correct > mine.questions_correct
            )
            OR (
              better.accuracy = mine.accuracy
              AND better.questions_correct = mine.questions_correct
              AND better.user_id::text < mine.user_id::text
            )
          )
      )
      FROM mine
    ),
    'myEntry', (
      SELECT jsonb_build_object(
        'userId', mine.user_id,
        'accuracy', mine.accuracy,
        'sessionsCompleted', mine.sessions_completed,
        'questionsAnswered', mine.questions_answered,
        'questionsCorrect', mine.questions_correct,
        'gtowScoreAvg', mine.gtow_score_avg,
        'bestStreak', mine.best_streak
      )
      FROM mine
    )
  );
$$;


ALTER FUNCTION public.fn_training_verified_leaderboard_rank_v2(p_user_id uuid, p_period_type text, p_period_key text, p_dimension_type text, p_dimension_key text) OWNER TO postgres;

--
-- TOC entry 4949 (class 1255 OID 23159395)
-- Name: fn_training_verified_leaderboard_record_v2(uuid, text, text, text, integer, integer, boolean, integer, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_training_verified_leaderboard_record_v2(p_user_id uuid, p_game_id text, p_period_type text, p_period_key text, p_answered integer, p_correct integer, p_is_perfect boolean, p_best_streak integer DEFAULT NULL::integer, p_gtow_score numeric DEFAULT NULL::numeric, p_ev_loss numeric DEFAULT NULL::numeric) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  WITH normalized AS (
    SELECT
      lower(btrim(p_game_id)) AS game_id,
      CASE
        WHEN lower(btrim(p_game_id)) ~ '^mtt-[0-9]{3}$'
          OR lower(btrim(p_game_id)) IN ('tournament-prep', 'final-table-sim')
          THEN 'mtt'
        WHEN lower(btrim(p_game_id)) ~ '^cash-[0-9]{3}$' THEN 'cash'
        WHEN lower(btrim(p_game_id)) ~ '^spins-[0-9]{3}$' THEN 'spins'
        WHEN lower(btrim(p_game_id)) ~ '^psy-[0-9]{3}$' THEN 'psychology'
        WHEN lower(btrim(p_game_id)) ~ '^adv-[0-9]{3}$'
          OR lower(btrim(p_game_id)) IN (
            'quiz-gauntlet', 'hand-lab', 'bluff-catcher',
            'mixed-strategy-lab', 'study-group'
          ) THEN 'advanced'
        ELSE NULL
      END AS category
  ), dimensions AS (
    SELECT 'overall'::text AS dimension_type, 'overall'::text AS dimension_key,
      NULL::text AS game_id, NULL::text AS category
    FROM normalized
    UNION ALL
    SELECT 'game', game_id, game_id, NULL::text
    FROM normalized
    WHERE game_id IS NOT NULL AND game_id <> ''
    UNION ALL
    SELECT 'category', category, NULL::text, category
    FROM normalized
    WHERE category IS NOT NULL
  )
  INSERT INTO public.training_verified_leaderboard AS verified (
    user_id, period_type, period_key,
    dimension_type, dimension_key, game_id, category,
    sessions_completed, questions_answered, questions_correct,
    accuracy, perfect_rounds, best_streak,
    gtow_score_avg, gtow_score_sum, gtow_score_samples,
    ev_loss_total, score_scale, updated_at
  ) SELECT
    p_user_id, p_period_type, p_period_key,
    dimensions.dimension_type, dimensions.dimension_key,
    dimensions.game_id, dimensions.category,
    1, greatest(p_answered, 0), least(greatest(p_correct, 0), greatest(p_answered, 0)),
    CASE WHEN p_answered > 0
      THEN round((least(greatest(p_correct, 0), p_answered)::numeric / p_answered) * 100, 2)
      ELSE 0 END,
    CASE WHEN p_is_perfect THEN 1 ELSE 0 END,
    greatest(coalesce(p_best_streak, 0), 0),
    p_gtow_score, coalesce(p_gtow_score, 0),
    CASE WHEN p_gtow_score IS NULL THEN 0 ELSE 1 END,
    coalesce(p_ev_loss, 0), 2, now()
  FROM dimensions
  ON CONFLICT (user_id, period_type, period_key, dimension_type, dimension_key)
  DO UPDATE SET
    sessions_completed = verified.sessions_completed + 1,
    questions_answered = verified.questions_answered + greatest(p_answered, 0),
    questions_correct = verified.questions_correct
      + least(greatest(p_correct, 0), greatest(p_answered, 0)),
    accuracy = CASE
      WHEN verified.questions_answered + greatest(p_answered, 0) > 0 THEN round((
        (verified.questions_correct
          + least(greatest(p_correct, 0), greatest(p_answered, 0)))::numeric
        / (verified.questions_answered + greatest(p_answered, 0))
      ) * 100, 2)
      ELSE 0 END,
    perfect_rounds = verified.perfect_rounds
      + CASE WHEN p_is_perfect THEN 1 ELSE 0 END,
    best_streak = greatest(verified.best_streak, coalesce(p_best_streak, 0)),
    gtow_score_avg = CASE
      WHEN p_gtow_score IS NULL THEN verified.gtow_score_avg
      ELSE round((verified.gtow_score_sum + p_gtow_score)
        / (verified.gtow_score_samples + 1), 2)
      END,
    gtow_score_sum = verified.gtow_score_sum + coalesce(p_gtow_score, 0),
    gtow_score_samples = verified.gtow_score_samples
      + CASE WHEN p_gtow_score IS NULL THEN 0 ELSE 1 END,
    ev_loss_total = verified.ev_loss_total + coalesce(p_ev_loss, 0),
    score_scale = 2,
    updated_at = now();
$_$;


ALTER FUNCTION public.fn_training_verified_leaderboard_record_v2(p_user_id uuid, p_game_id text, p_period_type text, p_period_key text, p_answered integer, p_correct integer, p_is_perfect boolean, p_best_streak integer, p_gtow_score numeric, p_ev_loss numeric) OWNER TO postgres;

--
-- TOC entry 4148 (class 1255 OID 4477831)
-- Name: fn_transfer_chips(uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_transfer_chips(p_club_id uuid, p_from_user_id uuid, p_to_user_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_from_before numeric;
  v_to_before numeric;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;

  PERFORM set_config('app.ledger_category', 'transfer', true);
  PERFORM set_config('app.ledger_counterparty', 'player_wallet', true);

  SELECT COALESCE(chip_balance, 0) INTO v_from_before
  FROM club_members
  WHERE club_id = p_club_id AND user_id = p_from_user_id FOR UPDATE;

  IF v_from_before IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'sender is not a member of this club');
  END IF;

  IF v_from_before < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'insufficient chips', 'balance', v_from_before);
  END IF;

  UPDATE club_members
  SET chip_balance = chip_balance - p_amount, updated_at = NOW()
  WHERE club_id = p_club_id AND user_id = p_from_user_id;

  SELECT COALESCE(chip_balance, 0) INTO v_to_before
  FROM club_members
  WHERE club_id = p_club_id AND user_id = p_to_user_id FOR UPDATE;

  IF v_to_before IS NULL THEN
    INSERT INTO club_members (club_id, user_id, role, chip_balance, joined_at, created_at, updated_at, status, is_active)
    VALUES (p_club_id, p_to_user_id, 'player', p_amount, NOW(), NOW(), NOW(), 'active', true)
    ON CONFLICT (club_id, user_id) DO UPDATE
      SET chip_balance = COALESCE(club_members.chip_balance, 0) + EXCLUDED.chip_balance,
          updated_at = NOW();
  ELSE
    UPDATE club_members
    SET chip_balance = COALESCE(chip_balance, 0) + p_amount, updated_at = NOW()
    WHERE club_id = p_club_id AND user_id = p_to_user_id;
  END IF;

  INSERT INTO chip_transactions (
    id, club_id, from_user_id, to_user_id, amount,
    transaction_type, notes, balance_after, created_at
  ) VALUES (
    gen_random_uuid(), p_club_id, p_from_user_id, p_to_user_id, p_amount,
    'peer_transfer', COALESCE(p_reason, 'Peer chip transfer'),
    COALESCE(v_to_before, 0) + p_amount, NOW()
  );

  RETURN jsonb_build_object('success', true, 'amount', p_amount);
END;
$$;


ALTER FUNCTION public.fn_transfer_chips(p_club_id uuid, p_from_user_id uuid, p_to_user_id uuid, p_amount numeric, p_reason text) OWNER TO postgres;

