--
-- TOC entry 6551 (class 1255 OID 23758948)
-- Name: fn_union_age_invoices(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_age_invoices(p_union_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r            record;
  v_gate_open  boolean;
  v_d1 int; v_d2 int; v_d3 int;
  v_days       numeric;
  v_level_due  int;
  v_marked     int := 0;
  v_reminded   int := 0;
  v_escalated  int := 0;
  v_owed_total numeric := 0;
  v_union_name text;
  v_body       text;
  v_msg        jsonb;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_platform_admin())) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  v_gate_open := public.fn_union_setting(p_union_id, 'weekly_invoices_enabled', 1) = 1;
  v_d1 := COALESCE(public.fn_union_setting(p_union_id, 'dunning_days_1', 0), 0)::int;
  v_d2 := COALESCE(public.fn_union_setting(p_union_id, 'dunning_days_2', 3), 3)::int;
  v_d3 := COALESCE(public.fn_union_setting(p_union_id, 'dunning_days_3', 7), 7)::int;
  SELECT u.name INTO v_union_name FROM unions u WHERE u.id = p_union_id;

  FOR r IN
    SELECT si.id, si.invoice_number, si.club_id, si.due_at, si.status,
           si.reminders_sent, si.breakdown->>'club_name' AS club_name,
           public.fn_union_invoice_outstanding(si.id) AS outstanding
      FROM settlement_invoices si
     WHERE si.invoice_type = 'union_weekly_squareup'
       AND (si.breakdown->>'union_id')::uuid = p_union_id
       AND si.status IN ('generated','overdue')     -- never a disputed, paid or cancelled one
       AND si.from_entity_type = 'club'             -- only what the CLUB owes
       -- THE HOUSE DOES NOT DUN ITSELF (20261015093202). A club whose owner
       -- owns the union owes this off-ledger square-up to himself: no payment
       -- can ever be recorded against it, so it is a statement, not a
       -- receivable. It is never marked overdue, chased or escalated.
       AND NOT EXISTS (SELECT 1 FROM clubs c JOIN unions u ON u.id = p_union_id
                        WHERE c.id = si.club_id AND c.owner_id = u.owner_id)
       AND si.due_at IS NOT NULL
       AND si.due_at < now()
     ORDER BY si.due_at
  LOOP
    CONTINUE WHEN COALESCE(r.outstanding, 0) <= 0.005;   -- credited to zero is settled

    v_owed_total := v_owed_total + r.outstanding;
    v_days := round(EXTRACT(epoch FROM (now() - r.due_at)) / 86400.0, 2);

    IF r.status <> 'overdue' THEN
      UPDATE settlement_invoices
         SET status = 'overdue', overdue_at = COALESCE(overdue_at, now()), updated_at = now()
       WHERE id = r.id;
      v_marked := v_marked + 1;
    END IF;

    -- Which reminder is owed. One message per run, never a burst.
    v_level_due := CASE WHEN v_days >= v_d3 THEN 3
                        WHEN v_days >= v_d2 THEN 2
                        WHEN v_days >= v_d1 THEN 1
                        ELSE 0 END;

    IF v_gate_open AND v_level_due > COALESCE(r.reminders_sent, 0) THEN
      IF v_level_due >= 3 THEN
        -- Past the last reminder: a person is told, not the club again.
        IF NOT EXISTS (SELECT 1 FROM financial_alerts a
                        WHERE a.source = 'fn_union_age_invoices' AND NOT a.resolved
                          AND a.context->>'invoice_id' = r.id::text) THEN
          INSERT INTO financial_alerts (source, severity, message, context)
          VALUES ('fn_union_age_invoices', 'critical',
                  COALESCE(r.club_name,'A club') || ' has not settled statement '
                  || COALESCE(r.invoice_number, r.id::text) || ': '
                  || to_char(r.outstanding, 'FM999,999,999,990.00') || ' is '
                  || v_days || ' days past due.',
                  jsonb_build_object('invoice_id', r.id, 'invoice_number', r.invoice_number,
                                     'union_id', p_union_id, 'club_id', r.club_id,
                                     'outstanding', r.outstanding, 'days_past_due', v_days));
          v_escalated := v_escalated + 1;
        END IF;
      END IF;

      v_body :=
        COALESCE(v_union_name,'Union') || ' payment reminder' || E'\n'
        || 'Statement ' || COALESCE(r.invoice_number, r.id::text) || E'\n\n'
        || 'Amount outstanding  ' || to_char(r.outstanding, 'FM999,999,999,990.00') || E'\n'
        || 'Due                 ' || to_char(r.due_at, 'YYYY-MM-DD') || E'\n'
        || 'Days past due       ' || v_days || E'\n\n'
        || CASE WHEN v_level_due >= 3
                THEN 'This is the final reminder. The union has been notified.'
                ELSE 'Please settle this statement.' END
        || E'\n\n'
        || 'If you believe this statement is wrong, contest it rather than ignore it.';

      -- A REMINDER GOES WHERE ITS STATEMENT WENT (2026-10-03).
      v_msg := public.fn_union_remind_statement(
        r.id, v_body,
        jsonb_build_object('kind', 'union_payment_reminder',
                           'invoice_id', r.id, 'invoice_number', r.invoice_number,
                           'outstanding', r.outstanding, 'days_past_due', v_days,
                           'reminder_level', v_level_due));

      UPDATE settlement_invoices
         SET reminders_sent = v_level_due, last_reminder_at = now(), updated_at = now()
       WHERE id = r.id;
      v_reminded := v_reminded + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('union_id', p_union_id,
    'newly_overdue', v_marked, 'reminders_sent', v_reminded, 'escalated', v_escalated,
    'total_outstanding_past_due', round(v_owed_total, 2),
    'dunning_gated', NOT v_gate_open, 'ran_at', now());
END $$;


ALTER FUNCTION public.fn_union_age_invoices(p_union_id uuid) OWNER TO postgres;

--
-- TOC entry 49321 (class 0 OID 0)
-- Dependencies: 6551
-- Name: FUNCTION fn_union_age_invoices(p_union_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_union_age_invoices(p_union_id uuid) IS 'Marks a delivered, club-owed, uncredited statement overdue once due_at passes, and chases it at 0/3/7 days with one message per run, escalating to a critical alert past the last reminder. A disputed statement never ages. Reminders and overdue-driven suspension both respect the weekly_invoices_enabled gate. Runs hourly from fn_union_integrity_sweep_all.';


--
-- TOC entry 3515 (class 1255 OID 14489601)
-- Name: fn_union_agent_coverage(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_agent_coverage(p_union_id uuid DEFAULT 'fade0000-0000-0000-0000-000000000001'::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_required boolean;
  v_players bigint; v_players_with bigint;
  v_supers bigint; v_agents bigint; v_subs bigint;
  v_agents_linked bigint; v_subs_linked bigint;
  v_agents_with_subs bigint; v_out_of_band bigint;
  v_deals bigint; v_gap_breaches bigint;
BEGIN
  IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR ( NOT public.fn_is_union_overseer(p_union_id, auth.uid()))) THEN RAISE EXCEPTION 'not_authorised'; END IF;
  SELECT COALESCE((settings->>'require_agent_for_players')::boolean, false)
    INTO v_required FROM unions WHERE id = p_union_id;

  SELECT count(*) FILTER (WHERE m.role = 'player'),
         count(*) FILTER (WHERE m.role = 'player' AND m.agent_id IS NOT NULL)
    INTO v_players, v_players_with
    FROM club_members m
    JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = p_union_id;

  SELECT count(*) FILTER (WHERE a.role='super_agent'),
         count(*) FILTER (WHERE a.role='agent'),
         count(*) FILTER (WHERE a.role='sub_agent'),
         count(*) FILTER (WHERE a.role='agent'     AND a.parent_agent_id IS NOT NULL),
         count(*) FILTER (WHERE a.role='sub_agent' AND a.parent_agent_id IS NOT NULL)
    INTO v_supers, v_agents, v_subs, v_agents_linked, v_subs_linked
    FROM agents a
    JOIN union_clubs uc ON uc.club_id = a.club_id AND uc.union_id = p_union_id
   WHERE a.status = 'active';

  SELECT count(*) INTO v_agents_with_subs
    FROM agents a
    JOIN union_clubs uc ON uc.club_id = a.club_id AND uc.union_id = p_union_id
   WHERE a.status='active' AND a.role='agent'
     AND EXISTS (SELECT 1 FROM agents s WHERE s.parent_agent_id = a.id AND s.status='active');

  SELECT count(*) INTO v_out_of_band
    FROM agents a
    JOIN union_clubs uc ON uc.club_id = a.club_id AND uc.union_id = p_union_id
   WHERE a.status='active' AND a.commission_rate IS NOT NULL
     AND (CASE WHEN a.commission_rate > 1 THEN a.commission_rate/100.0 ELSE a.commission_rate END)
         NOT BETWEEN public.fn_union_setting(p_union_id,'min_agent_commission',0)
                 AND public.fn_union_setting(p_union_id,'max_agent_commission',1);

  SELECT count(*) FILTER (WHERE COALESCE(m.player_rakeback_pct,0) > 0),
         count(*) FILTER (WHERE COALESCE(m.player_rakeback_pct,0) > 0
                            AND m.player_rakeback_pct * 100 > floor((a.commission_rate*100) - 10))
    INTO v_deals, v_gap_breaches
    FROM club_members m
    JOIN union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = p_union_id
    JOIN agents a ON a.user_id = m.agent_id AND a.club_id = m.club_id AND a.status='active'
   WHERE m.role = 'player';

  RETURN jsonb_build_object(
    'require_agent_for_players', v_required,
    'players_total', v_players,
    'players_with_agent', v_players_with,
    'players_without_agent', v_players - v_players_with,
    'player_coverage_pct', CASE WHEN v_players > 0
                                THEN round(100.0*v_players_with/v_players, 1) ELSE 100 END,
    'super_agents', v_supers,
    'agents', v_agents,
    'sub_agents', v_subs,
    'agents_under_a_super_agent', v_agents_linked,
    'agents_orphaned', v_agents - v_agents_linked,
    'sub_agents_under_an_agent', v_subs_linked,
    'sub_agents_orphaned', v_subs - v_subs_linked,
    'agents_that_have_sub_agents', v_agents_with_subs,
    'commission_rates_out_of_policy', v_out_of_band,
    'player_rakeback_deals', v_deals,
    'player_rakeback_gap_breaches', v_gap_breaches,
    'policy_band', jsonb_build_object(
      'min', public.fn_union_setting(p_union_id,'min_agent_commission',0),
      'max', public.fn_union_setting(p_union_id,'max_agent_commission',1))
  );
END $$;


ALTER FUNCTION public.fn_union_agent_coverage(p_union_id uuid) OWNER TO postgres;

--
-- TOC entry 7836 (class 1255 OID 14487548)
-- Name: fn_union_agent_risk_report(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_agent_risk_report(p_union_id uuid DEFAULT 'fade0000-0000-0000-0000-000000000001'::uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(agent_user_id uuid, agent_name text, club_name text, role text, players integer, seated_now integer, rake_generated numeric, player_net numeric, commission_accrued numeric, credit_extended numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET jit TO 'off'
    AS $_$
DECLARE
  v_from timestamptz := COALESCE(p_since, public.fn_union_week_start(now()));
  v_today timestamptz := date_trunc('day', now());
  v_day_lo date;
  v_head_end timestamptz;
  v_tail_start timestamptz;
  v_clubs uuid[];
  v_comm_today timestamptz := date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
  v_comm_day_lo date;
  v_comm_head_end timestamptz;
BEGIN
  IF NOT public.fn_caller_is_engine()
     AND (auth.uid() IS NULL OR NOT public.fn_is_union_overseer(p_union_id, auth.uid())) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  SELECT COALESCE(array_agg(x.club_id), '{}'::uuid[])
    INTO v_clubs
    FROM (
      SELECT p_union_id AS club_id
      UNION
      SELECT uc.club_id FROM public.union_clubs uc WHERE uc.union_id = p_union_id
    ) x;

  v_day_lo := date_trunc('day', v_from)::date;
  IF date_trunc('day', v_from) < v_from THEN
    v_day_lo := v_day_lo + 1;
  END IF;
  v_head_end := LEAST(v_day_lo::timestamptz, v_today);
  v_tail_start := GREATEST(v_today, v_from);

  v_comm_day_lo := (v_from AT TIME ZONE 'UTC')::date;
  IF (v_comm_day_lo::timestamp AT TIME ZONE 'UTC')<v_from THEN
    v_comm_day_lo:=v_comm_day_lo+1;
  END IF;
  v_comm_head_end:=LEAST(v_comm_day_lo::timestamp AT TIME ZONE 'UTC',v_comm_today);

  RETURN QUERY
  WITH roster AS MATERIALIZED (
    SELECT m.agent_id AS agent_user_id,
           m.user_id AS player_id,
           m.club_id,
           m.joined_at,
           COALESCE(m.credit_used, 0) AS credit_used
      FROM public.club_members m
     WHERE m.club_id = ANY(v_clubs)
       AND m.agent_id IS NOT NULL
  ),
  rake_roster AS MATERIALIZED (
    SELECT DISTINCT ON (r.player_id)
           r.player_id, r.club_id
      FROM roster r
     ORDER BY r.player_id, (r.club_id = p_union_id),
              r.joined_at ASC NULLS LAST, r.club_id
  ),
  ok_days AS MATERIALIZED (
    SELECT rc.club_id, rc.day
      FROM public.club_rake_rollup_complete rc
     WHERE rc.club_id = ANY(v_clubs)
       AND rc.day >= v_day_lo
       AND rc.day < v_today::date
  ),
  gap_days AS MATERIALIZED (
    SELECT c.club_id, g::date AS day
      FROM unnest(v_clubs) c(club_id)
      CROSS JOIN generate_series(v_day_lo, v_today::date - 1, interval '1 day') g
     WHERE v_day_lo < v_today::date
       AND NOT EXISTS (
         SELECT 1 FROM ok_days o
          WHERE o.club_id = c.club_id AND o.day = g::date)
  ),
  gap_hand_records AS MATERIALIZED (
    SELECT r.id, r.rake_amount
      FROM gap_days gd
      CROSS JOIN LATERAL (
        SELECT rr.id, rr.rake_amount
          FROM public.rake_records rr
         WHERE v_from >= v_today - interval '7 days'
           AND rr.club_id = gd.club_id
           AND rr.created_at >= gd.day::timestamptz
           AND rr.created_at < (gd.day + 1)::timestamptz
           AND rr.hand_id IS NOT NULL
           AND rr.rake_amount > 0
           AND rr.player_contributions IS NOT NULL
         OFFSET 0
      ) r
  ),
  gap_hand_fallback_records AS MATERIALIZED (
    SELECT r.id, r.rake_amount, r.player_contributions
      FROM gap_hand_records x
      JOIN public.rake_records r ON r.id = x.id
     WHERE NOT EXISTS (
       SELECT 1
         FROM public.rake_attributions a
        WHERE a.rake_record_id = x.id
          AND a.eligible_contribution > 0)
  ),
  rollup_rake AS (
    SELECT rr.player_id, rr.club_id, SUM(d.rake_amount) AS amount
      FROM public.club_rake_daily_user d
      JOIN ok_days o ON o.club_id = d.club_id AND o.day = d.day
      JOIN rake_roster rr ON rr.player_id = d.user_id
     GROUP BY rr.player_id, rr.club_id
  ),
  edge_attribution_rake AS (
    SELECT rr.player_id, rr.club_id, SUM(a.rake_amount) AS amount
      FROM (
        SELECT ra.player_id, ra.rake_amount
          FROM public.rake_attributions ra
         WHERE v_from >= v_today - interval '7 days'
           AND ra.club_id = ANY(v_clubs)
           AND ra.created_at >= v_from
           AND ra.created_at < v_head_end
           AND ra.hand_id IS NOT NULL
           AND ra.rake_amount > 0
        UNION ALL
        SELECT ra.player_id, ra.rake_amount
          FROM public.rake_attributions ra
         WHERE ra.club_id = ANY(v_clubs)
           AND ra.created_at >= v_tail_start
           AND ra.hand_id IS NOT NULL
           AND ra.rake_amount > 0
      ) a
      JOIN rake_roster rr ON rr.player_id = a.player_id
     GROUP BY rr.player_id, rr.club_id
  ),
  raw_records AS MATERIALIZED (
    SELECT r.id, r.rake_amount, r.player_contributions
      FROM public.rake_records r
     WHERE v_from < v_today - interval '7 days'
       AND r.club_id = ANY(v_clubs)
       AND r.created_at >= v_from AND r.created_at < v_head_end
       AND r.rake_amount > 0 AND r.player_contributions IS NOT NULL
    UNION ALL
    SELECT r.id, r.rake_amount, r.player_contributions
      FROM public.rake_records r
     WHERE v_from >= v_today - interval '7 days'
       AND r.club_id = ANY(v_clubs)
       AND r.created_at >= v_from AND r.created_at < v_head_end
       AND r.hand_id IS NULL
       AND r.rake_amount > 0 AND r.player_contributions IS NOT NULL
    UNION ALL
    SELECT r.id, r.rake_amount, r.player_contributions
      FROM ok_days o
      JOIN public.rake_records r
        ON r.club_id = o.club_id
       AND r.created_at >= o.day::timestamptz
       AND r.created_at < (o.day + 1)::timestamptz
     WHERE r.hand_id IS NULL
       AND r.rake_amount > 0 AND r.player_contributions IS NOT NULL
    UNION ALL
    SELECT r.id, r.rake_amount, r.player_contributions
      FROM gap_days gd
      CROSS JOIN LATERAL (
        SELECT rr.id, rr.rake_amount, rr.player_contributions
          FROM public.rake_records rr
         WHERE v_from < v_today - interval '7 days'
           AND rr.club_id = gd.club_id
           AND rr.created_at >= gd.day::timestamptz
           AND rr.created_at < (gd.day + 1)::timestamptz
           AND rr.rake_amount > 0
           AND rr.player_contributions IS NOT NULL
         OFFSET 0
      ) r
    UNION ALL
    SELECT r.id, r.rake_amount, r.player_contributions
      FROM gap_days gd
      CROSS JOIN LATERAL (
        SELECT rr.id, rr.rake_amount, rr.player_contributions
          FROM public.rake_records rr
         WHERE v_from >= v_today - interval '7 days'
           AND rr.club_id = gd.club_id
           AND rr.created_at >= gd.day::timestamptz
           AND rr.created_at < (gd.day + 1)::timestamptz
           AND rr.hand_id IS NULL
           AND rr.rake_amount > 0
           AND rr.player_contributions IS NOT NULL
         OFFSET 0
      ) r
    UNION ALL
    SELECT r.id, r.rake_amount, r.player_contributions
      FROM gap_hand_fallback_records r
    UNION ALL
    SELECT r.id, r.rake_amount, r.player_contributions
      FROM public.rake_records r
     WHERE r.club_id = ANY(v_clubs)
       AND r.created_at >= v_tail_start
       AND r.hand_id IS NULL
       AND r.rake_amount > 0 AND r.player_contributions IS NOT NULL
    UNION ALL
    SELECT r.id, r.rake_amount, r.player_contributions
      FROM public.rake_records r
     WHERE r.club_id = ANY(v_clubs)
       AND r.created_at >= v_from
       AND r.rake_amount < 0 AND r.player_contributions IS NOT NULL
  ),
  raw_rake AS (
    SELECT rr.player_id, rr.club_id,
           SUM(x.rake_amount * split.contribution / NULLIF(split.total, 0)) AS amount
      FROM raw_records x
      CROSS JOIN LATERAL (
        SELECT (e.key)::uuid AS player_id,
               e.value::numeric AS contribution,
               SUM(e.value::numeric) OVER () AS total
          FROM jsonb_each_text(x.player_contributions) e(key, value)
         WHERE e.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
           AND e.value::numeric > 0
      ) split
      JOIN rake_roster rr ON rr.player_id = split.player_id
     WHERE split.total > 0
     GROUP BY rr.player_id, rr.club_id
  ),
  gap_hand_rake AS (
    SELECT rr.player_id, rr.club_id,
           SUM(x.rake_amount * split.eligible_contribution
               / NULLIF(split.total, 0)) AS amount
      FROM gap_hand_records x
      CROSS JOIN LATERAL (
        SELECT a.player_id,
               a.eligible_contribution,
               SUM(a.eligible_contribution) OVER (
                 PARTITION BY a.rake_record_id) AS total
          FROM public.rake_attributions a
         WHERE a.rake_record_id = x.id
           AND a.eligible_contribution > 0
      ) split
      JOIN rake_roster rr ON rr.player_id = split.player_id
     WHERE split.total > 0
     GROUP BY rr.player_id, rr.club_id
  ),
  rake AS (
    SELECT q.player_id, q.club_id, SUM(q.amount) AS rake_generated
      FROM (
        SELECT * FROM rollup_rake
        UNION ALL SELECT * FROM edge_attribution_rake
        UNION ALL SELECT * FROM raw_rake
        UNION ALL SELECT * FROM gap_hand_rake
      ) q
     GROUP BY q.player_id, q.club_id
  ),
  flows AS MATERIALIZED (
    SELECT p.player_id, p.club_id,
           COALESCE((
             SELECT SUM(l.amount)
               FROM public.chip_ledger l
              WHERE l.club_id = p.club_id
                AND l.to_entity_id = p.player_id
                AND l.created_at >= v_from
                AND l.status = 'posted'
                AND l.to_type = 'player_wallet'
                AND l.from_type = 'table_stack'
           ), 0) - COALESCE((
             SELECT SUM(l.amount)
               FROM public.chip_ledger l
              WHERE l.club_id = p.club_id
                AND l.from_entity_id = p.player_id
                AND l.created_at >= v_from
                AND l.status = 'posted'
                AND l.from_type = 'player_wallet'
                AND l.to_type = 'table_stack'
           ), 0) AS net
      FROM (SELECT DISTINCT r.player_id, r.club_id FROM roster r) p
  ),
  comm_pairs AS MATERIALIZED (
    SELECT DISTINCT r.agent_user_id, r.club_id FROM roster r
  ),
  comm_ok_days AS MATERIALIZED (
    SELECT c.club_id,g::date AS day
      FROM unnest(v_clubs)c(club_id)
      CROSS JOIN generate_series(v_comm_day_lo,(v_comm_today AT TIME ZONE 'UTC')::date-1,interval '1 day')g
      LEFT JOIN smarter_private.agent_commission_report_days m ON m.club_id=c.club_id AND m.day=g::date
      LEFT JOIN smarter_private.agent_commission_report_frontiers f ON f.club_id=c.club_id
     WHERE v_from>=v_comm_today-interval '7 days'
       AND v_comm_day_lo<(v_comm_today AT TIME ZONE 'UTC')::date
       AND (m.complete IS TRUE OR (m.club_id IS NULL AND g::date>=f.first_complete_day))
  ),
  comm_gap_days AS MATERIALIZED (
    SELECT c.club_id,g::date AS day
      FROM unnest(v_clubs)c(club_id)
      CROSS JOIN generate_series(v_comm_day_lo,(v_comm_today AT TIME ZONE 'UTC')::date-1,interval '1 day')g
     WHERE v_from>=v_comm_today-interval '7 days'
       AND v_comm_day_lo<(v_comm_today AT TIME ZONE 'UTC')::date
       AND NOT EXISTS(SELECT 1 FROM comm_ok_days m WHERE m.club_id=c.club_id AND m.day=g::date)
  ),
  comm AS MATERIALIZED (
    SELECT p.agent_user_id,p.club_id,COALESCE((
      SELECT SUM(x.amount) FROM (
        SELECT d.amount
          FROM smarter_private.agent_commission_report_daily d
          JOIN comm_ok_days m ON m.club_id=d.club_id AND m.day=d.day
         WHERE d.club_id=p.club_id AND d.user_id=p.agent_user_id
        UNION ALL
        SELECT ac.amount FROM public.agent_commissions ac
         WHERE ac.user_id = p.agent_user_id AND ac.club_id = p.club_id
           AND ac.created_at>=v_from AND ac.created_at<v_comm_head_end
        UNION ALL
        SELECT ac.amount FROM public.agent_commissions ac
         WHERE ac.user_id = p.agent_user_id AND ac.club_id = p.club_id
           AND ac.created_at>=GREATEST(v_comm_today,v_from)
        UNION ALL
        SELECT ac.amount FROM comm_gap_days gd CROSS JOIN LATERAL (
          SELECT a.amount FROM public.agent_commissions a
           WHERE a.user_id=p.agent_user_id AND a.club_id=p.club_id
             AND a.created_at>=(gd.day::timestamp AT TIME ZONE 'UTC')
             AND a.created_at<((gd.day+1)::timestamp AT TIME ZONE 'UTC')
          OFFSET 0
        )ac WHERE gd.club_id=p.club_id
        UNION ALL
        SELECT ac.amount FROM public.agent_commissions ac
         WHERE v_from<v_comm_today-interval '7 days'
           AND ac.user_id = p.agent_user_id AND ac.club_id = p.club_id
           AND ac.created_at>=v_comm_head_end AND ac.created_at<v_comm_today
      )x
    ),0) AS amt FROM comm_pairs p
  ),
  seated AS MATERIALIZED (
    SELECT s.user_id, s.club_id
      FROM public.table_seats s
      JOIN (SELECT DISTINCT r.player_id, r.club_id FROM roster r) p
        ON p.player_id = s.user_id AND p.club_id = s.club_id
     WHERE s.left_at IS NULL
     GROUP BY s.user_id, s.club_id
  )
  SELECT r.agent_user_id,
         pr.username,
         cl.name,
         COALESCE(a.role, 'agent'),
         COUNT(DISTINCT r.player_id)::int,
         COUNT(DISTINCT r.player_id) FILTER (WHERE st.user_id IS NOT NULL)::int,
         ROUND(COALESCE(SUM(rk.rake_generated), 0), 2),
         ROUND(COALESCE(SUM(fl.net), 0), 2),
         ROUND(COALESCE(MAX(cm.amt), 0), 2),
         ROUND(COALESCE(SUM(r.credit_used), 0), 2)
    FROM roster r
    LEFT JOIN public.profiles pr ON pr.id = r.agent_user_id
    LEFT JOIN public.clubs cl ON cl.id = r.club_id
    LEFT JOIN public.agents a ON a.user_id = r.agent_user_id AND a.club_id = r.club_id
    LEFT JOIN rake rk ON rk.player_id = r.player_id AND rk.club_id = r.club_id
    LEFT JOIN flows fl ON fl.player_id = r.player_id AND fl.club_id = r.club_id
    LEFT JOIN comm cm ON cm.agent_user_id = r.agent_user_id AND cm.club_id = r.club_id
    LEFT JOIN seated st ON st.user_id = r.player_id AND st.club_id = r.club_id
   GROUP BY r.agent_user_id, pr.username, cl.name, a.role
   ORDER BY 8 DESC NULLS LAST;
END
$_$;


