--
-- TOC entry 6041 (class 1255 OID 25409764)
-- Name: fn_union_close_unsettleable_period(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_close_unsettleable_period(p_period_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE v public.settlement_periods%ROWTYPE;
  BEGIN
    IF NOT (current_user IN ('postgres', 'supabase_admin') OR COALESCE(auth.role(), '') = 'service_role') THEN
      RAISE EXCEPTION 'fn_union_close_unsettleable_period is service only' USING ERRCODE = '42501';
    END IF;
    IF COALESCE(btrim(p_reason), '') = '' OR length(p_reason) < 60 THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'a_period_closed_without_settling_needs_a_real_reason');
    END IF;
    SELECT * INTO v FROM public.settlement_periods WHERE id = p_period_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'period_not_found'); END IF;
    IF v.status NOT IN ('open', 'processing') THEN
      RETURN jsonb_build_object('ok', true, 'already', v.status, 'changed', false);
    END IF;
    UPDATE public.settlement_periods
       SET status = 'closed',
           notes = COALESCE(notes || E'\n', '') || p_reason,
           updated_at = now()
     WHERE id = p_period_id;
    RETURN jsonb_build_object('ok', true, 'closed', p_period_id, 'was', v.status, 'changed', true);
  END $$;


ALTER FUNCTION public.fn_union_close_unsettleable_period(p_period_id uuid, p_reason text) OWNER TO postgres;

--
-- TOC entry 4541 (class 1255 OID 219528300)
-- Name: fn_union_club_bank_balances(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_club_bank_balances(p_union_id uuid) RETURNS TABLE(club_id uuid, club_bank numeric, club_promo numeric, pull_floor numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT (
    EXISTS (SELECT 1 FROM public.unions u WHERE u.id = p_union_id AND u.owner_id = v_uid)
    OR EXISTS (
      SELECT 1 FROM public.union_admins ua
       WHERE ua.union_id = p_union_id AND ua.user_id = v_uid AND ua.role = 'union_lead'
    )
  ) THEN
    RAISE EXCEPTION 'union lead access required' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT uc.club_id,
         round(COALESCE(c.chip_treasury, 0), 2),
         round(COALESCE(c.promo_balance, 0), 2),
         CASE WHEN EXISTS (
                SELECT 1 FROM public.chip_transactions t
                 WHERE t.club_id = uc.club_id AND t.transaction_type = 'club_opening_grant'
              ) THEN 100000::numeric ELSE 0::numeric END
    FROM public.union_clubs uc
    JOIN public.clubs c ON c.id = uc.club_id
   WHERE uc.union_id = p_union_id;
END
$$;


