--
-- TOC entry 8657 (class 1255 OID 14393040)
-- Name: fn_union_commingling_report(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_commingling_report(p_union_id uuid DEFAULT 'fade0000-0000-0000-0000-000000000001'::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_buyin_uses_club_wallet boolean;
  v_seats_total bigint; v_seats_stamped bigint;
  v_multi_club bigint; v_club_chips jsonb;
BEGIN
  v_buyin_uses_club_wallet := EXISTS (
    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname='public' AND p.proname='atomic_table_buyin'
       AND p.prosrc LIKE '%club_members%');

  SELECT count(*), count(*) FILTER (WHERE ts.club_id IS NOT NULL)
    INTO v_seats_total, v_seats_stamped
    FROM table_seats ts JOIN tables t ON t.id = ts.table_id
   WHERE ts.left_at IS NULL AND t.union_id = p_union_id;

  SELECT count(*) INTO v_multi_club FROM (
    SELECT cm.user_id
      FROM club_members cm
      JOIN union_clubs uc ON uc.club_id = cm.club_id AND uc.union_id = p_union_id
     GROUP BY cm.user_id HAVING count(DISTINCT cm.club_id) > 1) m;

  SELECT jsonb_object_agg(c.name, round(x.total))
    INTO v_club_chips
    FROM (SELECT cm.club_id, SUM(COALESCE(cm.chip_balance,0)) AS total
            FROM club_members cm
            JOIN union_clubs uc ON uc.club_id = cm.club_id AND uc.union_id = p_union_id
           GROUP BY cm.club_id) x
    JOIN clubs c ON c.id = x.club_id;

  RETURN jsonb_build_object(
    'buyin_debits_club_wallet', v_buyin_uses_club_wallet,
    'commingled', NOT v_buyin_uses_club_wallet,
    'active_union_seats', v_seats_total,
    'seats_with_club_provenance', v_seats_stamped,
    'players_in_multiple_clubs', v_multi_club,
    'club_chip_balances', v_club_chips,
    'note', CASE WHEN v_buyin_uses_club_wallet
                 THEN 'Buy-ins draw on the club wallet - provenance is real.'
                 ELSE 'Buy-ins still debit the single global player wallet, so club '
                      'wallets are commingled and rake attribution falls back to '
                      'first-joined. Club-scoped buy-in rollout required.' END
  );
END $$;


ALTER FUNCTION public.fn_union_commingling_report(p_union_id uuid) OWNER TO postgres;

--
-- TOC entry 7327 (class 1255 OID 14488389)
-- Name: fn_union_credit_risk_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_credit_risk_check() RETURNS TABLE(invariant text, severity text, offenders bigint, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 'union_club_no_terms', 'warning', count(*),
         'Member clubs with no union_club_terms row: no security deposit and '
         || 'no stop loss on file, so their losses are carried unsecured'
    FROM union_clubs uc
   WHERE NOT EXISTS (SELECT 1 FROM union_club_terms t
                      WHERE t.union_id = uc.union_id AND t.club_id = uc.club_id)
  HAVING count(*) > 0

  UNION ALL
  SELECT 'union_club_stop_loss_breached', 'critical', count(*),
         'Clubs past their weekly stop loss and still active: '
         || COALESCE(string_agg(x.club_name || ' (exposure ' || x.exposure || ' vs limit '
                                || x.stop_loss_limit || ')', '; '), '')
    FROM (
      SELECT e.club_name, e.exposure, e.stop_loss_limit
        FROM (SELECT DISTINCT t.union_id
                FROM union_club_terms t
               WHERE t.stop_loss_limit IS NOT NULL
                 AND t.status <> 'suspended') u
        CROSS JOIN LATERAL fn_union_club_exposure(u.union_id) e
       WHERE e.breached AND e.status <> 'suspended'
    ) x
  HAVING count(*) > 0

  UNION ALL
  SELECT 'union_eco_not_recorded', 'warning', count(*),
         'Unions with ECO enabled and no union_eco_ledger row for the settlement '
         || 'week that has CLOSED: that week''s win tax / loss rebate is not reproducible. '
         || 'The ledger is written at close, so the week in progress is not asked about'
    FROM unions un
   WHERE COALESCE((un.settings->>'eco_enabled')::boolean, false)
     AND NOT public.fn_ca_launch_accounting_waived('union',un.id,public.fn_union_week_start())
     AND EXISTS (SELECT 1 FROM union_clubs uc WHERE uc.union_id = un.id)
     AND NOT EXISTS (SELECT 1 FROM union_eco_ledger l
                      WHERE l.union_id = un.id
                        AND l.period_start >= fn_union_week_start() - interval '7 days')
     -- A WEEK'S ECO ROW IS WRITTEN AT ITS CLOSE, SO IT IS ASKED FOR ONCE THE
     -- CLOSE IS OWED (2026-10-05). Before the close's run time
     -- (fn_union_accounting_run_at), while an accounting_close_gates row holds
     -- the first attempt for a quiet hour, and while the close is running, the
     -- row cannot exist yet. On 2026-10-05 this filed two ledger_imbalance
     -- incidents at 07:52 for a close gated until 2026-10-06 13:00 by the
     -- coordinator decision of 2026-10-03. A close that is owed and has not
     -- written the row - past its run time, no gate holding it, nothing
     -- running - is still found, and so is a finished close without one.
     -- Migration 20261005113359.
     AND NOT (now() < fn_union_accounting_run_at(fn_union_week_start())
              OR EXISTS (SELECT 1 FROM accounting_close_gates g
                          WHERE g.scope_kind = 'union' AND g.scope_id = un.id
                            AND g.period_end = fn_union_week_start()
                            AND g.gate_until > now()
                            AND NOT EXISTS (SELECT 1 FROM union_accounting_runs r
                                             WHERE r.scope_kind = 'union' AND r.scope_id = un.id
                                               AND r.period_start = g.period_start
                                               AND r.period_end = g.period_end))
              OR EXISTS (SELECT 1 FROM union_accounting_runs q
                          WHERE q.scope_kind = 'union' AND q.scope_id = un.id
                            AND q.period_end = fn_union_week_start()
                            AND q.status = 'running'))
  HAVING count(*) > 0

  UNION ALL
  SELECT 'union_club_stakes_above_cap', 'warning', count(*),
         'Live tables above the club''s agreed stakes cap: '
         || COALESCE(string_agg(y.club_name || ' bb=' || y.big_blind
                                || ' cap=' || y.stakes_cap_bb, '; '), '')
    FROM (
      SELECT c.name AS club_name, tb.big_blind, t.stakes_cap_bb
        FROM union_club_terms t
        JOIN clubs c ON c.id = t.club_id
        JOIN tables tb ON tb.club_id = t.club_id
       WHERE t.stakes_cap_bb IS NOT NULL
         AND tb.big_blind > t.stakes_cap_bb
         AND COALESCE(tb.is_deleted, false) = false
         AND tb.status NOT IN ('closed','deleted')
    ) y
  HAVING count(*) > 0

  UNION ALL
  SELECT * FROM fn_anon_exposure_check();
$$;


ALTER FUNCTION public.fn_union_credit_risk_check() OWNER TO postgres;

--
-- TOC entry 8907 (class 1255 OID 18275138)
-- Name: fn_union_credit_wallet(uuid, text, numeric, text, uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_credit_wallet(p_union_id uuid, p_wallet text, p_amount numeric, p_tx_type text DEFAULT NULL::text, p_club_id uuid DEFAULT NULL::uuid, p_period_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid, p_op_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_prior jsonb;
  v_res jsonb;
BEGIN
  IF p_op_id IS NULL THEN
    RETURN public.fn_union_credit_wallet_zd3core(
      p_union_id, p_wallet, p_amount, p_tx_type, p_club_id, p_period_id, p_notes, p_created_by);
  END IF;

  SELECT result INTO v_prior
    FROM public.ca_op_claims
   WHERE op_id = p_op_id AND fn_name = 'fn_union_credit_wallet';
  IF FOUND AND v_prior IS NOT NULL THEN
    RETURN v_prior || jsonb_build_object('replayed', true, 'op_id', p_op_id);
  ELSIF FOUND THEN
    DELETE FROM public.ca_op_claims
     WHERE op_id = p_op_id AND fn_name = 'fn_union_credit_wallet';
  END IF;

  INSERT INTO public.ca_op_claims (op_id, fn_name)
  VALUES (p_op_id, 'fn_union_credit_wallet');

  v_res := public.fn_union_credit_wallet_zd3core(
    p_union_id, p_wallet, p_amount, p_tx_type, p_club_id, p_period_id, p_notes, p_created_by);

  IF COALESCE(v_res->>'success', '') = 'true' THEN
    UPDATE public.ca_op_claims
       SET result = v_res, finalized_at = now()
     WHERE op_id = p_op_id AND fn_name = 'fn_union_credit_wallet';
  ELSE
    DELETE FROM public.ca_op_claims
     WHERE op_id = p_op_id AND fn_name = 'fn_union_credit_wallet';
  END IF;

  RETURN v_res;
END;
$$;


ALTER FUNCTION public.fn_union_credit_wallet(p_union_id uuid, p_wallet text, p_amount numeric, p_tx_type text, p_club_id uuid, p_period_id uuid, p_notes text, p_created_by uuid, p_op_id text) OWNER TO postgres;

--
-- TOC entry 7829 (class 1255 OID 18275137)
-- Name: fn_union_credit_wallet_zd3core(uuid, text, numeric, text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_credit_wallet_zd3core(p_union_id uuid, p_wallet text, p_amount numeric, p_tx_type text, p_club_id uuid, p_period_id uuid, p_notes text, p_created_by uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_wallet_column text;
  v_before numeric;
  v_after numeric;
  v_sql text;
  v_cat text;
  v_cp text;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;

  v_wallet_column := CASE lower(p_wallet)
    WHEN 'chip' THEN 'chip_balance'
    WHEN 'chip_balance' THEN 'chip_balance'
    WHEN 'rake' THEN 'rake_wallet'
    WHEN 'rake_wallet' THEN 'rake_wallet'
    WHEN 'bbj' THEN 'bbj_wallet'
    WHEN 'bbj_wallet' THEN 'bbj_wallet'
    WHEN 'promo' THEN 'promo_wallet'
    WHEN 'promo_wallet' THEN 'promo_wallet'
    WHEN 'insurance' THEN 'insurance_wallet'
    WHEN 'insurance_wallet' THEN 'insurance_wallet'
    ELSE NULL
  END;

  IF v_wallet_column IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unknown wallet: ' || p_wallet);
  END IF;

  /* SAY WHERE THE CHIPS CAME FROM, OR DO NOT MOVE THEM (2026-10-02,
     20261002140203). The counterparty comes from the tx_type map. An
     unmapped tx_type used to declare nothing and fall to
     settlement_suspense, which the commit check now refuses; it is refused
     here instead, by name, before the wallet row is even touched. */
  SELECT category, counterparty INTO v_cat, v_cp
    FROM public.fn_ca_union_wallet_ledger_shape(p_tx_type);
  IF v_cp IS NULL THEN
    RAISE EXCEPTION 'fn_union_credit_wallet_unmapped_tx_type: %', COALESCE(p_tx_type, '(null)')
      USING ERRCODE = '23514',
            DETAIL  = 'a union wallet credit whose tx_type names no ledger counterparty would be journalled against settlement_suspense',
            HINT    = 'Map the tx_type in fn_ca_union_wallet_ledger_shape to the account the chips really come from, or credit the union through the door that moves the source in the same transaction.';
  END IF;

  -- Ensure wallet row exists
  INSERT INTO union_wallets (union_id, created_at, updated_at)
  VALUES (p_union_id, NOW(), NOW())
  ON CONFLICT (union_id) DO NOTHING;

  -- Read + lock before
  v_sql := format('SELECT COALESCE(%I,0) FROM union_wallets WHERE union_id = $1 FOR UPDATE', v_wallet_column);
  EXECUTE v_sql INTO v_before USING p_union_id;

  /* Declared immediately before the write and cleared immediately after, so
     it cannot leak onto an unrelated autoledger write later in the same
     transaction. */
  PERFORM public.fn_ca_declare_ledger(v_cat, v_cp);

  -- Update
  v_sql := format('UPDATE union_wallets SET %I = COALESCE(%I,0) + $1, updated_at = NOW() WHERE union_id = $2 RETURNING %I',
                  v_wallet_column, v_wallet_column, v_wallet_column);
  EXECUTE v_sql INTO v_after USING p_amount, p_union_id;

  PERFORM set_config('app.ledger_counterparty', '', true);
  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);

  -- Audit
  INSERT INTO union_wallet_transactions (
    id, union_id, wallet, direction, amount, balance_after,
    tx_type, club_id, period_id, notes, created_by, created_at
  ) VALUES (
    gen_random_uuid(), p_union_id, v_wallet_column, 'credit', p_amount, v_after,
    COALESCE(p_tx_type, 'credit'), p_club_id, p_period_id, p_notes, p_created_by, NOW()
  );

  RETURN jsonb_build_object(
    'success', true, 'amount', p_amount,
    'wallet', v_wallet_column,
    'balance_before', v_before, 'balance_after', v_after
  );
END;
$_$;


ALTER FUNCTION public.fn_union_credit_wallet_zd3core(p_union_id uuid, p_wallet text, p_amount numeric, p_tx_type text, p_club_id uuid, p_period_id uuid, p_notes text, p_created_by uuid) OWNER TO postgres;

--
-- TOC entry 6146 (class 1255 OID 18275146)
-- Name: fn_union_debit_wallet(uuid, text, numeric, text, uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_debit_wallet(p_union_id uuid, p_wallet text, p_amount numeric, p_tx_type text DEFAULT NULL::text, p_club_id uuid DEFAULT NULL::uuid, p_period_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid, p_op_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_prior jsonb;
  v_res jsonb;
BEGIN
  IF p_op_id IS NULL THEN
    RETURN public.fn_union_debit_wallet_zd3core(
      p_union_id, p_wallet, p_amount, p_tx_type, p_club_id, p_period_id, p_notes, p_created_by);
  END IF;

  SELECT result INTO v_prior
    FROM public.ca_op_claims
   WHERE op_id = p_op_id AND fn_name = 'fn_union_debit_wallet';
  IF FOUND AND v_prior IS NOT NULL THEN
    RETURN v_prior || jsonb_build_object('replayed', true, 'op_id', p_op_id);
  ELSIF FOUND THEN
    DELETE FROM public.ca_op_claims
     WHERE op_id = p_op_id AND fn_name = 'fn_union_debit_wallet';
  END IF;

  INSERT INTO public.ca_op_claims (op_id, fn_name)
  VALUES (p_op_id, 'fn_union_debit_wallet');

  v_res := public.fn_union_debit_wallet_zd3core(
    p_union_id, p_wallet, p_amount, p_tx_type, p_club_id, p_period_id, p_notes, p_created_by);

  IF COALESCE(v_res->>'success', '') = 'true' THEN
    UPDATE public.ca_op_claims
       SET result = v_res, finalized_at = now()
     WHERE op_id = p_op_id AND fn_name = 'fn_union_debit_wallet';
  ELSE
    DELETE FROM public.ca_op_claims
     WHERE op_id = p_op_id AND fn_name = 'fn_union_debit_wallet';
  END IF;

  RETURN v_res;
END;
$$;


ALTER FUNCTION public.fn_union_debit_wallet(p_union_id uuid, p_wallet text, p_amount numeric, p_tx_type text, p_club_id uuid, p_period_id uuid, p_notes text, p_created_by uuid, p_op_id text) OWNER TO postgres;

--
-- TOC entry 4762 (class 1255 OID 18275145)
-- Name: fn_union_debit_wallet_zd3core(uuid, text, numeric, text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_debit_wallet_zd3core(p_union_id uuid, p_wallet text, p_amount numeric, p_tx_type text, p_club_id uuid, p_period_id uuid, p_notes text, p_created_by uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_wallet_column text;
  v_before numeric;
  v_after numeric;
  v_sql text;
  v_cat text;
  v_cp text;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;

  v_wallet_column := CASE lower(p_wallet)
    WHEN 'chip' THEN 'chip_balance'
    WHEN 'chip_balance' THEN 'chip_balance'
    WHEN 'rake' THEN 'rake_wallet'
    WHEN 'rake_wallet' THEN 'rake_wallet'
    WHEN 'bbj' THEN 'bbj_wallet'
    WHEN 'bbj_wallet' THEN 'bbj_wallet'
    WHEN 'promo' THEN 'promo_wallet'
    WHEN 'promo_wallet' THEN 'promo_wallet'
    WHEN 'insurance' THEN 'insurance_wallet'
    WHEN 'insurance_wallet' THEN 'insurance_wallet'
    ELSE NULL
  END;

  IF v_wallet_column IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unknown wallet: ' || p_wallet);
  END IF;

  v_sql := format('SELECT COALESCE(%I,0) FROM union_wallets WHERE union_id = $1 FOR UPDATE', v_wallet_column);
  EXECUTE v_sql INTO v_before USING p_union_id;

  IF v_before IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'union wallet not found');
  END IF;

  IF v_before < p_amount THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'insufficient balance',
      'wallet', v_wallet_column, 'balance', v_before, 'requested', p_amount
    );
  END IF;

  SELECT category, counterparty INTO v_cat, v_cp
    FROM public.fn_ca_union_wallet_ledger_shape(p_tx_type);
  IF v_cp IS NOT NULL THEN
    PERFORM public.fn_ca_declare_ledger(v_cat, v_cp);
  END IF;

  v_sql := format('UPDATE union_wallets SET %I = %I - $1, updated_at = NOW() WHERE union_id = $2 RETURNING %I',
                  v_wallet_column, v_wallet_column, v_wallet_column);
  EXECUTE v_sql INTO v_after USING p_amount, p_union_id;

  IF v_cp IS NOT NULL THEN
    PERFORM set_config('app.ledger_counterparty', '', true);
    PERFORM set_config('app.ledger_category', '', true);
    PERFORM set_config('app.ledger_counterparty_entity', '', true);
  END IF;

  INSERT INTO union_wallet_transactions (
    id, union_id, wallet, direction, amount, balance_after,
    tx_type, club_id, period_id, notes, created_by, created_at
  ) VALUES (
    gen_random_uuid(), p_union_id, v_wallet_column, 'debit', p_amount, v_after,
    COALESCE(p_tx_type, 'debit'), p_club_id, p_period_id, p_notes, p_created_by, NOW()
  );

  RETURN jsonb_build_object(
    'success', true, 'amount', p_amount,
    'wallet', v_wallet_column,
    'balance_before', v_before, 'balance_after', v_after
  );
END;
$_$;


ALTER FUNCTION public.fn_union_debit_wallet_zd3core(p_union_id uuid, p_wallet text, p_amount numeric, p_tx_type text, p_club_id uuid, p_period_id uuid, p_notes text, p_created_by uuid) OWNER TO postgres;

--
-- TOC entry 6406 (class 1255 OID 8878828)
-- Name: fn_union_deposit_from_wallet(uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_deposit_from_wallet(p_union_id uuid, p_amount numeric, p_notes text DEFAULT NULL::text, p_op_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_lead boolean;
  v_balance numeric;
  v_after numeric;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not authenticated');
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'amount must be > 0');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM union_admins ua
     WHERE ua.union_id = p_union_id AND ua.user_id = v_uid AND ua.role = 'union_lead'
  ) OR EXISTS (
    SELECT 1 FROM unions u WHERE u.id = p_union_id AND u.owner_id = v_uid
  ) INTO v_is_lead;
  IF NOT v_is_lead THEN
    RETURN jsonb_build_object('success', false, 'error', 'union lead access required');
  END IF;

  SELECT balance INTO v_balance FROM wallets
   WHERE user_id = v_uid AND wallet_type = 'PLAYER' FOR UPDATE;
  IF v_balance IS NULL OR v_balance < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'insufficient wallet balance');
  END IF;
  UPDATE wallets SET balance = balance - p_amount, updated_at = NOW()
   WHERE user_id = v_uid AND wallet_type = 'PLAYER';

  INSERT INTO union_wallets (union_id, chip_balance)
  VALUES (p_union_id, p_amount)
  ON CONFLICT (union_id) DO UPDATE
    SET chip_balance = COALESCE(union_wallets.chip_balance, 0) + p_amount,
        updated_at = NOW()
  RETURNING chip_balance INTO v_after;

  INSERT INTO union_wallet_transactions (
    union_id, wallet, direction, amount, balance_after, tx_type, period_id, notes, created_by
  ) VALUES (
    p_union_id, 'chip_balance', 'credit', p_amount, v_after, 'owner_deposit',
    p_op_id, COALESCE(NULLIF(p_notes, ''), 'Union bank deposit from owner wallet'), v_uid
  );

  RETURN jsonb_build_object('success', true, 'amount', p_amount, 'union_balance', v_after);
EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('success', false, 'duplicate', true,
                            'error', 'operation already processed');
END;
$$;


ALTER FUNCTION public.fn_union_deposit_from_wallet(p_union_id uuid, p_amount numeric, p_notes text, p_op_id uuid) OWNER TO postgres;

--
-- TOC entry 9497 (class 1255 OID 23744327)
-- Name: fn_union_dispute_invoice(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_dispute_invoice(p_invoice_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inv       settlement_invoices%ROWTYPE;
  v_union_id  uuid;
  v_period    settlement_periods%ROWTYPE;
  v_caller    uuid := auth.uid();
  v_period_marked boolean := false;
BEGIN
  SELECT * INTO v_inv FROM settlement_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF v_inv.id IS NULL THEN
    RAISE EXCEPTION 'invoice not found';
  END IF;

  v_union_id := (v_inv.breakdown->>'union_id')::uuid;

  -- WHO IS CALLING, before anything that would describe the document.
  IF v_caller IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM clubs c WHERE c.id = v_inv.club_id AND c.owner_id = v_caller)
     AND NOT EXISTS (SELECT 1 FROM club_members cm
                      WHERE cm.club_id = v_inv.club_id AND cm.user_id = v_caller
                        AND cm.role IN ('owner','co_owner','admin')
                        AND COALESCE(cm.status,'active') NOT IN ('banned','suspended'))
     AND NOT EXISTS (SELECT 1 FROM unions u WHERE u.id = v_union_id AND u.owner_id = v_caller)
     AND NOT EXISTS (SELECT 1 FROM union_admins ua WHERE ua.union_id = v_union_id AND ua.user_id = v_caller)
     AND NOT COALESCE(public.fn_is_platform_admin(), false) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  IF COALESCE(btrim(p_reason), '') = '' THEN
    RAISE EXCEPTION 'a dispute must carry a reason';
  END IF;
  IF v_inv.invoice_type <> 'union_weekly_squareup' THEN
    RAISE EXCEPTION 'only a weekly square-up can be disputed, this is %', v_inv.invoice_type;
  END IF;
  IF v_inv.status = 'disputed' THEN
    RETURN jsonb_build_object('success', true, 'already_disputed', true,
                              'invoice', COALESCE(v_inv.invoice_number, v_inv.id::text));
  END IF;

  UPDATE settlement_invoices
     SET status = 'disputed',
         notes = COALESCE(notes, '') || E'\nDISPUTED ' || to_char(now(), 'YYYY-MM-DD HH24:MI')
                 || ': ' || p_reason,
         updated_at = now()
   WHERE id = p_invoice_id;

  SELECT * INTO v_period FROM settlement_periods WHERE id = v_inv.period_id;
  IF v_period.id IS NOT NULL AND v_period.status NOT IN ('closed', 'disputed') THEN
    UPDATE settlement_periods SET status = 'disputed', updated_at = now()
     WHERE id = v_inv.period_id;
    v_period_marked := true;
  END IF;

  INSERT INTO notifications (user_id, type, title, message, data, read)
  SELECT DISTINCT uid, 'union_invoice_disputed',
         'Statement ' || COALESCE(v_inv.invoice_number, '') || ' disputed',
         COALESCE((v_inv.breakdown->>'club_name'), 'A club')
           || ' has disputed statement ' || COALESCE(v_inv.invoice_number, v_inv.id::text)
           || ': ' || p_reason,
         jsonb_build_object('invoice_id', v_inv.id, 'invoice_number', v_inv.invoice_number,
                            'club_id', v_inv.club_id, 'union_id', v_union_id,
                            'reason', p_reason, 'source', 'club_arena'),
         false
    FROM (
      SELECT u.owner_id AS uid FROM unions u WHERE u.id = v_union_id AND u.owner_id IS NOT NULL
      UNION
      SELECT ua.user_id FROM union_admins ua WHERE ua.union_id = v_union_id
    ) x WHERE uid IS NOT NULL;

  RETURN jsonb_build_object(
    'success', true,
    'invoice', COALESCE(v_inv.invoice_number, v_inv.id::text),
    'invoice_id', v_inv.id,
    'period_marked_disputed', v_period_marked,
    'period_status', COALESCE(v_period.status, '(none)'),
    'note', CASE WHEN v_period.status = 'closed'
                 THEN 'The period is closed and was not reopened. Resolve with a credit note.'
                 ELSE 'The period is marked disputed and will not be closed until resolved.' END);
END $$;


ALTER FUNCTION public.fn_union_dispute_invoice(p_invoice_id uuid, p_reason text) OWNER TO postgres;

