--
-- TOC entry 3653 (class 1255 OID 14506071)
-- Name: fn_union_distribution_check(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_distribution_check(p_union_id uuid DEFAULT 'fade0000-0000-0000-0000-000000000001'::uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET jit TO 'off'
    AS $$
DECLARE
  v_from timestamptz := COALESCE(p_since, public.fn_union_week_start(now()));
  v_today_date date := (now() AT TIME ZONE 'UTC')::date;
  v_today_start timestamptz;
  v_rollup_from_date date;
  v_rollup_from_start timestamptz;
  v_head_end timestamptz;
  v_clubs uuid[];
  v_rake numeric;
  v_comm numeric;
  v_rb numeric;
BEGIN
  IF NOT public.fn_caller_is_engine()
     AND (auth.uid() IS NULL OR NOT public.fn_is_union_overseer(p_union_id, auth.uid())) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  SELECT COALESCE(array_agg(c.id), '{}'::uuid[])
    INTO v_clubs
    FROM public.clubs c
   WHERE c.union_id = p_union_id OR c.id = p_union_id;

  SELECT COALESCE(SUM(rr.rake_amount), 0)
    INTO v_rake
    FROM public.rake_records rr
   WHERE rr.club_id = ANY(v_clubs)
     AND rr.created_at >= v_from;

  v_today_start := (v_today_date::timestamp AT TIME ZONE 'UTC');
  v_rollup_from_date := (v_from AT TIME ZONE 'UTC')::date;
  v_rollup_from_start :=
    (v_rollup_from_date::timestamp AT TIME ZONE 'UTC');
  IF v_from > v_rollup_from_start THEN
    v_rollup_from_date := v_rollup_from_date + 1;
    v_rollup_from_start :=
      (v_rollup_from_date::timestamp AT TIME ZONE 'UTC');
  END IF;
  v_head_end := LEAST(v_rollup_from_start, v_today_start);

  -- Exact UTC edges stay on the immutable commission journal. Only complete
  -- UTC days are read from the trigger-maintained daily fact, and the tail is
  -- intentionally open-ended so future-dated evidence keeps its old meaning.
  SELECT COALESCE(SUM(part.amount), 0)
    INTO v_comm
    FROM (
      SELECT COALESCE(SUM(ac.amount), 0) AS amount
        FROM public.agent_commissions ac
       WHERE v_from < v_head_end
         AND ac.club_id = ANY(v_clubs)
         AND ac.created_at >= v_from
         AND ac.created_at < v_head_end
      UNION ALL
      SELECT COALESCE(SUM(cd.amount), 0)
        FROM public.ca_club_commission_daily cd
       WHERE cd.club_id = ANY(v_clubs)
         AND cd.stat_date >= v_rollup_from_date
         AND cd.stat_date < v_today_date
      UNION ALL
      SELECT COALESCE(SUM(ac.amount), 0)
        FROM public.agent_commissions ac
       WHERE ac.club_id = ANY(v_clubs)
         AND ac.created_at >= GREATEST(v_from, v_today_start)
    ) part;

  SELECT COALESCE(SUM(rp.rakeback_amount), 0)
    INTO v_rb
    FROM public.rakeback_periods rp
   WHERE rp.club_id = ANY(v_clubs)
     AND rp.period_start >= v_from::date;

  RETURN jsonb_build_object(
    'period_start', v_from,
    'rake_collected', ROUND(v_rake, 2),
    'agent_commissions', ROUND(v_comm, 2),
    'player_rakeback', ROUND(v_rb, 2),
    'total_distributed', ROUND(v_comm + v_rb, 2),
    'over_distributed_by', ROUND(GREATEST((v_comm + v_rb) - v_rake, 0), 2),
    'healthy', (v_comm + v_rb) <= v_rake * 1.001,
    'note', 'Player rakeback is funded from the agent''s commission, so '
            || 'commissions + rakeback must not exceed the rake collected.');
END
$$;


ALTER FUNCTION public.fn_union_distribution_check(p_union_id uuid, p_since timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 7759 (class 1255 OID 14589392)
-- Name: fn_union_eco_adjustment(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_eco_adjustment(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(club_id uuid, club_name text, players_won numeric, rake_generated numeric, cash_players_won numeric, cash_rake numeric, tournament_rake numeric, total_rake_generated numeric, club_commission_rate numeric, rake_earned numeric, eco_base numeric, eco_rate numeric, eco_amount numeric, direction text, union_net_eco numeric, eco_base_mode text, baseline_cash_exact boolean, include_horses boolean, eco_enabled boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE proof jsonb; terms jsonb;
BEGIN
 -- Preserve the existing disclosure authorization before reading evidence.
 IF auth.uid() IS NOT NULL
  AND NOT EXISTS(SELECT 1 FROM unions u WHERE u.id=p_union_id AND u.owner_id=auth.uid())
  AND NOT EXISTS(SELECT 1 FROM union_admins ua WHERE ua.union_id=p_union_id AND ua.user_id=auth.uid())
  AND NOT EXISTS(SELECT 1 FROM union_clubs uc JOIN club_members cm ON cm.club_id=uc.club_id
   WHERE uc.union_id=p_union_id AND cm.user_id=auth.uid() AND cm.role IN('owner','co_owner','admin','super_agent')) THEN
  RAISE EXCEPTION 'not authorized to read union reconciliation' USING ERRCODE='42501'; END IF;
 proof:=public.fn_union_pnl_qualified_clubs(p_union_id,p_start,p_end);
 terms:=proof#>'{eco_commercial_terms_evidence,segments,0,terms}';
 RETURN QUERY WITH rows AS(
  SELECT x,(x->>'club_id')::uuid id,(x->>'eco_amount')::numeric eco FROM jsonb_array_elements(proof->'clubs') x
 ), total AS(SELECT COALESCE(sum(-eco),0) amount FROM rows)
 SELECT r.id,c.name::text,(x->>'realized_net')::numeric+(x->>'stack_delta')::numeric,(x->>'rake_paid')::numeric,
  (x->>'cash_player_pnl')::numeric,(x->>'cash_rake')::numeric,(x->>'tournament_rake')::numeric,(x->>'rake_paid')::numeric,
  CASE WHEN (x->>'rake_paid')::numeric>0 THEN (x->>'rake_earned')::numeric/(x->>'rake_paid')::numeric ELSE NULL END,
  (x->>'rake_earned')::numeric,(x->>'eco_base')::numeric,(terms->>'eco_rate')::numeric,r.eco,
  CASE WHEN r.eco<0 THEN 'club pays union (profitable week)' WHEN r.eco>0 THEN 'union pays club (losing week)' ELSE 'square' END,
  total.amount,terms->>'eco_base_mode',true,true,(terms->>'eco_enabled')::boolean
 FROM rows r LEFT JOIN clubs c ON c.id=r.id CROSS JOIN total ORDER BY r.eco;
END $$;


