--
-- TOC entry 5086 (class 1255 OID 111012253)
-- Name: fn_union_online_count(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_online_count(p_union_id uuid) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT count(DISTINCT cm.user_id)
    FROM public.union_clubs uc
    JOIN public.club_members cm ON cm.club_id = uc.club_id
    LEFT JOIN public.profiles pr ON pr.id = cm.user_id
   WHERE auth.uid() IS NOT NULL
     AND uc.union_id = p_union_id
     AND coalesce(cm.status, 'active') IN ('active', 'approved', 'automatic')
     AND ((coalesce(pr.is_online, false) AND pr.last_seen > now() - interval '5 minutes')
       OR EXISTS (SELECT 1 FROM public.table_seats ts JOIN public.tables t ON t.id = ts.table_id
                   WHERE ts.user_id = cm.user_id AND ts.left_at IS NULL
                     AND t.status IN ('running', 'waiting', 'active')));
$$;


ALTER FUNCTION public.fn_union_online_count(p_union_id uuid) OWNER TO postgres;

--
-- TOC entry 3887 (class 1255 OID 14490193)
-- Name: fn_union_overload_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_overload_check() RETURNS TABLE(fn text, signatures bigint, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.proname::text, count(*),
         'money-path function has multiple signatures - callers may silently hit '
         || 'the stale one (this has already happened three times: buy-in, '
         || 'cascading commission, tournament register)'
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public'
     AND p.proname IN (
       'atomic_table_buyin','atomic_table_cashout','atomic_table_rebuy','atomic_table_addon',
       'atomic_tournament_register','atomic_tournament_unregister','process_tournament_rebuy',
       'calculate_cascading_commission','credit_agent_commission_from_rake',
       'atomic_distribute_rake','record_tournament_buyin_rake',
       'fn_pay_player_chips'
       -- atomic_pay_agent_settlement was here until phase 7 dropped it.
     )
   GROUP BY p.proname
  HAVING count(*) > 1;
$$;


ALTER FUNCTION public.fn_union_overload_check() OWNER TO postgres;

--
-- TOC entry 5394 (class 1255 OID 48917934)
-- Name: fn_union_overseer_of_record(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_overseer_of_record(p_union_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_union_id IS NOT NULL AND p_user_id IS NOT NULL AND (
       EXISTS (SELECT 1 FROM public.unions u WHERE u.id = p_union_id AND u.owner_id = p_user_id)
    OR EXISTS (SELECT 1 FROM public.union_admins a WHERE a.union_id = p_union_id AND a.user_id = p_user_id)
    OR EXISTS (SELECT 1 FROM public.clubs c
                WHERE c.id = p_union_id AND COALESCE(c.is_union, false) AND c.owner_id = p_user_id)
    OR EXISTS (SELECT 1 FROM public.club_members m
                WHERE m.club_id = p_union_id AND m.user_id = p_user_id
                  AND m.role IN ('owner','co_owner','admin')
                  AND m.status IN ('active','approved'))
  );
$$;


ALTER FUNCTION public.fn_union_overseer_of_record(p_union_id uuid, p_user_id uuid) OWNER TO postgres;

