--
-- TOC entry 6213 (class 1255 OID 14203614)
-- Name: fn_union_oversees_club(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_oversees_club(p_club_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_club_id IS NOT NULL AND p_user_id IS NOT NULL
     AND (public.fn_caller_is_engine() OR auth.uid() IS NOT DISTINCT FROM p_user_id)
     AND public.fn_union_overseer_of_record(
    COALESCE(
      (SELECT uc.union_id FROM public.union_clubs uc WHERE uc.club_id = p_club_id LIMIT 1),
      (SELECT c.union_id FROM public.clubs c WHERE c.id = p_club_id)
    ),
    p_user_id
  );
$$;


ALTER FUNCTION public.fn_union_oversees_club(p_club_id uuid, p_user_id uuid) OWNER TO postgres;

