--
-- TOC entry 8772 (class 1255 OID 153562122)
-- Name: fn_union_owner_holds_membership(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_owner_holds_membership(p_union_id uuid, p_club_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_owner uuid;
  v_is_union boolean;
  v_asset text;
  v_row public.club_members%ROWTYPE;
  v_exists boolean;
  v_prev_source text := COALESCE(current_setting('app.club_membership_source', true), '');
  v_prev_lifecycle text := COALESCE(current_setting('app.club_membership_lifecycle_write', true), '');
  v_result text;
BEGIN
  -- Serialize a join with ownership transfer before choosing the owner.
  -- Without this row lock, a transfer can miss an uncommitted club link and
  -- the join can still insert the previous owner's membership afterward.
  SELECT u.owner_id INTO v_owner FROM public.unions u WHERE u.id = p_union_id FOR SHARE;
  IF v_owner IS NULL THEN
    RETURN 'no_owner';
  END IF;

  SELECT COALESCE(c.is_union, false), c.asset INTO v_is_union, v_asset
    FROM public.clubs c WHERE c.id = p_club_id;
  IF NOT FOUND OR v_is_union OR p_club_id = p_union_id OR v_asset = 'diamonds' THEN
    RETURN 'not_a_member_club';
  END IF;

  -- The cap's own lock, then the row: the same order as Join A Club.
  PERFORM public.fn_club_membership_lock(v_owner);
  SELECT * INTO v_row FROM public.club_members cm
   WHERE cm.club_id = p_club_id AND cm.user_id = v_owner
   FOR UPDATE;
  v_exists := FOUND;

  IF v_exists THEN
    IF v_row.membership_lifecycle_status = 'active'
       AND COALESCE(v_row.status, 'active') IN ('active', 'approved')
       AND COALESCE(v_row.is_active, true) THEN
      RETURN 'kept';
    END IF;
    IF v_row.membership_lifecycle_status = 'active' AND v_row.status = 'banned' THEN
      RAISE EXCEPTION 'UNION_OWNER_BANNED_IN_CLUB: The Union Owner Is Banned In This Club, So It Cannot Join The Union'
        USING ERRCODE = 'check_violation',
              HINT = 'The club unbans the union owner first; a ban is never lifted silently.';
    END IF;
    IF v_row.membership_lifecycle_status = 'active' AND v_row.status = 'suspended' THEN
      RAISE EXCEPTION 'UNION_OWNER_SUSPENDED_IN_CLUB: The Union Owner Is Suspended In This Club, So It Cannot Join The Union'
        USING ERRCODE = 'check_violation',
              HINT = 'The club reinstates the union owner first; a suspension is never lifted silently.';
    END IF;
  END IF;

  PERFORM set_config('app.club_membership_source', 'union_owner_membership', true);
  PERFORM set_config('app.club_membership_lifecycle_write', 'rejoin', true);
  BEGIN
    IF v_exists THEN
      -- Pending, inactive or departed: activated, role kept, exactly as the
      -- ordinary rejoin (fn_join_club) keeps it.
      UPDATE public.club_members cm
         SET membership_lifecycle_status = 'active',
             status = 'active',
             is_active = true,
             departed_at = NULL,
             departed_by = NULL,
             departure_reason = NULL,
             updated_at = clock_timestamp()
       WHERE cm.club_id = p_club_id
         AND cm.user_id = v_owner;
      v_result := 'activated';
    ELSE
      INSERT INTO public.club_members (club_id, user_id, role, status, is_active, chip_balance)
      VALUES (p_club_id, v_owner, 'player', 'active', true, 0);
      v_result := 'inserted';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.club_membership_source', v_prev_source, true);
    PERFORM set_config('app.club_membership_lifecycle_write', v_prev_lifecycle, true);
    RAISE;
  END;
  PERFORM set_config('app.club_membership_source', v_prev_source, true);
  PERFORM set_config('app.club_membership_lifecycle_write', v_prev_lifecycle, true);
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.fn_union_owner_holds_membership(p_union_id uuid, p_club_id uuid) OWNER TO postgres;

--
-- TOC entry 7148 (class 1255 OID 153562128)
-- Name: fn_union_owner_membership_is_kept(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_owner_membership_is_kept() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- Only a change that ends or moves an ACTIVE membership matters; a role
    -- change, a balance or a reactivation is not a removal.
    IF NOT (OLD.membership_lifecycle_status = 'active'
            AND COALESCE(OLD.status, 'active') IN ('active', 'approved')
            AND COALESCE(OLD.is_active, true)) THEN
      RETURN NEW;
    END IF;
    IF NEW.club_id = OLD.club_id AND NEW.user_id = OLD.user_id
       AND NEW.membership_lifecycle_status = 'active'
       AND COALESCE(NEW.status, 'active') IN ('active', 'approved')
       AND COALESCE(NEW.is_active, true) THEN
      RETURN NEW;
    END IF;
  ELSIF NOT EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = OLD.club_id)
     OR NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = OLD.user_id) THEN
    -- The club or the person itself is being deleted (ON DELETE CASCADE).
    RETURN OLD;
  END IF;

  IF EXISTS (SELECT 1 FROM public.union_clubs uc
               JOIN public.unions u ON u.id = uc.union_id
              WHERE uc.club_id = OLD.club_id
                AND u.owner_id = OLD.user_id) THEN
    RAISE EXCEPTION 'UNION_OWNER_MEMBERSHIP_REQUIRED: The Union Owner Must Stay A Member Of Every Club In The Union'
      USING ERRCODE = 'check_violation',
            HINT = 'Take the club out of the union, or transfer the union, before this membership can end.';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION public.fn_union_owner_membership_is_kept() OWNER TO postgres;

--
-- TOC entry 4528 (class 1255 OID 14203632)
-- Name: fn_union_player_directory(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_player_directory(p_union_id uuid) RETURNS TABLE(user_id uuid, username text, display_name text, avatar_url text, club_id uuid, club_name text, member_role text, member_status text, joined_at timestamp with time zone, currently_seated boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.fn_is_union_overseer(p_union_id, auth.uid()) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  RETURN QUERY
  WITH union_scope AS (
    SELECT uc.club_id AS id FROM union_clubs uc WHERE uc.union_id = p_union_id
    UNION
    SELECT c.id FROM clubs c WHERE c.id = p_union_id AND COALESCE(c.is_union, false)
  )
  SELECT cm.user_id,
         pr.username,
         public.fn_arena_name(pr.alias, pr.username, pr.display_name,
                              pr.first_name, pr.last_name, pr.full_name),
         pr.avatar_url,
         cm.club_id,
         c.name,
         cm.role,
         cm.status,
         cm.joined_at,
         EXISTS (
           SELECT 1 FROM table_seats ts
             JOIN tables t ON t.id = ts.table_id
            WHERE ts.user_id = cm.user_id AND ts.left_at IS NULL
              AND t.union_id = p_union_id
         )
    FROM club_members cm
    JOIN union_scope us ON us.id = cm.club_id
    JOIN clubs c ON c.id = cm.club_id
    LEFT JOIN profiles pr ON pr.id = cm.user_id
   WHERE pr.status IS DISTINCT FROM 'deleted'
   ORDER BY c.name, pr.username NULLS LAST;
END $$;


ALTER FUNCTION public.fn_union_player_directory(p_union_id uuid) OWNER TO postgres;

--
-- TOC entry 6763 (class 1255 OID 14343173)
-- Name: fn_union_pnl_all_clubs(uuid, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_all_clubs(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_include_horses boolean DEFAULT true) RETURNS TABLE(club_id uuid, buyins numeric, cashouts numeric, realized_net numeric, winnings numeric, losses numeric, players integer, seated_stack numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE proof jsonb;
BEGIN
 IF p_include_horses IS DISTINCT FROM true THEN RAISE EXCEPTION 'complete_pnl_population_required' USING ERRCODE='22023'; END IF;
 proof:=public.fn_union_pnl_qualified_clubs(p_union_id,p_start,p_end);
 RETURN QUERY SELECT (x->>'club_id')::uuid,(x->>'buyins')::numeric,(x->>'cashouts')::numeric,(x->>'realized_net')::numeric,
  (x->>'winnings')::numeric,(x->>'losses')::numeric,(x->>'players')::integer,(x->>'seated_end')::numeric
 FROM jsonb_array_elements(proof->'clubs') x;
END $$;


ALTER FUNCTION public.fn_union_pnl_all_clubs(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_include_horses boolean) OWNER TO postgres;

