CREATE FUNCTION public.fn_union_pnl_cash_outcome_touch_row(p_table_id uuid, p_hand_number bigint, p_recognized_at timestamp with time zone, p_game_scope jsonb, p_evidence jsonb) RETURNS SETOF public.union_pnl_cash_outcome_touches
    LANGUAGE sql IMMUTABLE
