--

COMMENT ON FUNCTION public.fn_union_pnl_inventory_seal_advance(p_at timestamp with time zone, p_verify boolean) IS 'Split inventory seal (20261003): computes a closed week''s six-hour inventory layers (at least one per call, none started 90 s after the call began), then seals the week exactly as fn_union_pnl_inventory_checkpoint_seal; with verify, compares the assembled week with an already sealed checkpoint instead.';


--
-- TOC entry 6200 (class 1255 OID 94398863)
-- Name: fn_union_pnl_inventory_seal_in_progress(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_inventory_seal_in_progress() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
 -- A split seal of the current week's boundary has started and not finished.
 SELECT EXISTS(SELECT 1 FROM public.union_pnl_inventory_seal_layers l WHERE l.boundary=public.fn_union_week_start(now()))
   AND NOT EXISTS(SELECT 1 FROM public.union_pnl_inventory_checkpoints c WHERE c.boundary=public.fn_union_week_start(now()))
   OR EXISTS(SELECT 1 FROM public.union_pnl_inventory_seal_builds b
    WHERE b.boundary<=public.fn_union_week_start(now())
     AND NOT EXISTS(SELECT 1 FROM public.union_pnl_inventory_checkpoints c WHERE c.boundary=b.boundary))
$$;


