COMMENT ON FUNCTION public.fn_union_pnl_inventory_seal_in_progress() IS 'Split inventory seal (20261003): true while six-hour layers are staged for the current week''s boundary and its checkpoint is not sealed yet; job 272 then calls the close on every tick.';


--
-- TOC entry 3812 (class 1255 OID 154605432)
-- Name: fn_union_pnl_inventory_seal_write_page(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_inventory_seal_write_page(p_at timestamp with time zone, p_base timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_build public.union_pnl_inventory_seal_builds%ROWTYPE; v_n bigint;
 v_head record;v_rows bigint;v_issues bigint;v_max bigint;v_rows_md5 text;v_issues_md5 text;v_diff bigint;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('union-pnl-inventory-checkpoint',0));
 IF EXISTS(SELECT 1 FROM public.union_pnl_inventory_checkpoints WHERE boundary=p_at) THEN
  RAISE EXCEPTION 'inventory_build_boundary_already_published' USING ERRCODE='55000'; END IF;
 INSERT INTO public.union_pnl_inventory_seal_builds(boundary,base_boundary)
 VALUES(p_at,p_base) ON CONFLICT(boundary) DO NOTHING;
 SELECT * INTO STRICT v_build FROM public.union_pnl_inventory_seal_builds WHERE boundary=p_at;
 IF v_build.base_boundary IS DISTINCT FROM p_base THEN
  RAISE EXCEPTION 'inventory_build_base_changed' USING ERRCODE='55000'; END IF;
 -- Both cardinality and encoded volume are bounded before any logged row is written.
 -- No last-step copy: these private logged rows become the checkpoint's storage.
 DROP TABLE IF EXISTS pg_temp._inv_write_page;
 CREATE TEMP TABLE _inv_write_page ON COMMIT DROP AS
 WITH candidates AS MATERIALIZED (
  SELECT s.*,512+4*GREATEST(COALESCE(pg_column_size(s.o_after_row),0),COALESCE(octet_length(s.o_after_row::text),0))::bigint
   +octet_length(s.o_source_name)+COALESCE(octet_length(s.o_first_operation),0) cost
  FROM pg_temp.union_pnl_inventory_seal s
  WHERE (v_build.last_kind IS NULL OR (s.o_kind,s.o_source_name,s.o_row_id,s.o_event_id)>(v_build.last_kind,v_build.last_source,v_build.last_row,v_build.last_event))
  AND ((s.o_kind='row' AND NOT EXISTS(SELECT 1 FROM public.union_pnl_inventory_seal_build_rows b
    WHERE b.boundary=p_at AND b.source_name=s.o_source_name AND b.row_id=s.o_row_id))
   OR (s.o_kind='issue' AND NOT EXISTS(SELECT 1 FROM public.union_pnl_inventory_seal_build_issues b
    WHERE b.boundary=p_at AND b.source_name=s.o_source_name AND b.row_id=s.o_row_id AND b.event_id=s.o_event_id)))
  ORDER BY s.o_kind,s.o_source_name,s.o_row_id,s.o_event_id LIMIT 32768
 ), budgeted AS (
  SELECT c.*,sum(cost) OVER(ORDER BY o_kind,o_source_name,o_row_id,o_event_id ROWS UNBOUNDED PRECEDING) used
  FROM candidates c
 ) SELECT * FROM budgeted WHERE used<=33554432;
 SELECT count(*) INTO v_n FROM pg_temp._inv_write_page;
 IF v_n>0 THEN
  IF v_build.ready THEN RAISE EXCEPTION 'inventory_ready_build_has_missing_rows' USING ERRCODE='55000'; END IF;
  INSERT INTO public.union_pnl_inventory_seal_build_rows
   SELECT p_at,o_source_name,o_row_id,o_event_id,o_first_operation,o_after_row FROM pg_temp._inv_write_page WHERE o_kind='row';
  INSERT INTO public.union_pnl_inventory_seal_build_issues
   SELECT p_at,o_source_name,o_row_id,o_event_id FROM pg_temp._inv_write_page WHERE o_kind='issue';
  UPDATE public.union_pnl_inventory_seal_builds b SET last_kind=p.o_kind,last_source=p.o_source_name,last_row=p.o_row_id,last_event=p.o_event_id
   FROM (SELECT * FROM pg_temp._inv_write_page ORDER BY o_kind DESC,o_source_name DESC,o_row_id DESC,o_event_id DESC LIMIT 1) p
   WHERE b.boundary=p_at;
  -- Publication always uses a separate tick after the final write page committed.
  RETURN false;
 END IF;
 IF EXISTS(SELECT 1 FROM pg_temp.union_pnl_inventory_seal s
  WHERE (v_build.last_kind IS NULL OR (s.o_kind,s.o_source_name,s.o_row_id,s.o_event_id)>(v_build.last_kind,v_build.last_source,v_build.last_row,v_build.last_event))
   AND (
  (s.o_kind='row' AND NOT EXISTS(SELECT 1 FROM public.union_pnl_inventory_seal_build_rows b
    WHERE b.boundary=p_at AND b.source_name=s.o_source_name AND b.row_id=s.o_row_id))
   OR (s.o_kind='issue' AND NOT EXISTS(SELECT 1 FROM public.union_pnl_inventory_seal_build_issues b
    WHERE b.boundary=p_at AND b.source_name=s.o_source_name AND b.row_id=s.o_row_id AND b.event_id=s.o_event_id)))) THEN
  RAISE EXCEPTION 'inventory_build_row_exceeds_bounded_page' USING ERRCODE='54000'; END IF;
 -- Independently prove the durable set, BUCKET BY BUCKET (20261019151632).
 -- The 4.52M-row week of 2026-10-19 could not publish: one EXCEPT ALL of the
 -- whole cache against the whole build, both ways, ran past 290 s on
 -- production, past job 272's 240 s tick, so the publishing tick was
 -- cancelled every time. Each side is now read ONCE into per-bucket counts
 -- and hashes (one source, the first two hex digits of row_id, the same
 -- buckets the rows hash already uses), and the two bucket sets must be
 -- identical: a missing, extra, duplicated or changed row or issue changes its
 -- bucket's count or hash. The build's own buckets then give the rows hash that
 -- must equal the original assembly's, as before.
 DROP TABLE IF EXISTS pg_temp._inv_build_buckets;
 CREATE TEMP TABLE _inv_build_buckets ON COMMIT DROP AS
  SELECT 'row'::text k,source_name sn,left(row_id::text,2) b,count(*) n,max(latest_event_id) mx,
   md5(string_agg(concat_ws('|',source_name,row_id,latest_event_id,first_operation,COALESCE(after_row::text,'~')),E'\n'
    ORDER BY source_name,row_id,latest_event_id)) h
  FROM public.union_pnl_inventory_seal_build_rows WHERE boundary=p_at GROUP BY 2,3
  UNION ALL
  SELECT 'issue',source_name,left(row_id::text,2),count(*),NULL::bigint,
   md5(string_agg(concat_ws('|',source_name,row_id,event_id),E'\n' ORDER BY source_name,row_id,event_id))
  FROM public.union_pnl_inventory_seal_build_issues WHERE boundary=p_at GROUP BY 2,3;
 DROP TABLE IF EXISTS pg_temp._inv_cache_buckets;
 CREATE TEMP TABLE _inv_cache_buckets ON COMMIT DROP AS
  SELECT s.o_kind k,s.o_source_name sn,left(s.o_row_id::text,2) b,count(*) n,
   md5(string_agg(CASE WHEN s.o_kind='row'
     THEN concat_ws('|',s.o_source_name,s.o_row_id,s.o_event_id,s.o_first_operation,COALESCE(s.o_after_row::text,'~'))
     ELSE concat_ws('|',s.o_source_name,s.o_row_id,s.o_event_id) END,E'\n'
    ORDER BY s.o_source_name,s.o_row_id,s.o_event_id)) h
  FROM pg_temp.union_pnl_inventory_seal s GROUP BY 1,2,3;
 SELECT count(*) INTO v_diff FROM pg_temp._inv_build_buckets x FULL JOIN pg_temp._inv_cache_buckets c
  ON c.k=x.k AND c.sn=x.sn AND c.b=x.b
  WHERE x.k IS NULL OR c.k IS NULL OR x.n IS DISTINCT FROM c.n OR x.h IS DISTINCT FROM c.h
   OR c.k NOT IN ('row','issue');
 IF v_diff>0 THEN RAISE EXCEPTION 'inventory_build_disagrees_with_assembled_source' USING ERRCODE='55000'; END IF;
 -- Independently checksum the durable rows; a cache value alone cannot certify them.
 SELECT * INTO STRICT v_head FROM public.union_pnl_inventory_seal_snapshot_head WHERE boundary=p_at;
 SELECT COALESCE(sum(n),0),max(mx),md5(COALESCE(string_agg(h,E'\n' ORDER BY sn,b),''))
  INTO v_rows,v_max,v_rows_md5 FROM pg_temp._inv_build_buckets WHERE k='row';
 SELECT count(*),md5(COALESCE(string_agg(concat_ws('|',source_name,row_id,event_id),E'\n'
   ORDER BY source_name,row_id,event_id),''))
 INTO v_issues,v_issues_md5 FROM public.union_pnl_inventory_seal_build_issues WHERE boundary=p_at;
 IF (v_rows,v_issues,v_rows_md5,v_issues_md5,v_max)
  IS DISTINCT FROM (v_head.row_count,v_head.issue_count,v_head.rows_md5,v_head.issues_md5,v_head.max_event_id) THEN
  RAISE EXCEPTION 'inventory_build_checksum_disagrees_with_original_source' USING ERRCODE='55000'; END IF;

 IF NOT v_build.ready THEN UPDATE public.union_pnl_inventory_seal_builds SET ready=true WHERE boundary=p_at; END IF;
 RETURN true;
END $$;


ALTER FUNCTION public.fn_union_pnl_inventory_seal_write_page(p_at timestamp with time zone, p_base timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 4742 (class 1255 OID 154605453)
-- Name: fn_union_pnl_inventory_snapshot_restore(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_inventory_snapshot_restore(p_at timestamp with time zone, p_base timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE h public.union_pnl_inventory_seal_snapshot_head%ROWTYPE;
BEGIN
 SELECT * INTO h FROM public.union_pnl_inventory_seal_snapshot_head WHERE boundary=p_at;
 IF NOT FOUND THEN RETURN false; END IF;
 IF h.base_boundary IS DISTINCT FROM p_base THEN
  RAISE EXCEPTION 'inventory_snapshot_base_changed' USING ERRCODE='55000'; END IF;
 EXECUTE format('CREATE TEMP VIEW union_pnl_inventory_seal AS SELECT o_kind,o_source_name,o_row_id,o_event_id,o_first_operation,o_after_row FROM public.union_pnl_inventory_seal_snapshot WHERE boundary=%L::timestamptz',p_at);
 RETURN true;
END $$;


ALTER FUNCTION public.fn_union_pnl_inventory_snapshot_restore(p_at timestamp with time zone, p_base timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 4393 (class 1255 OID 154605455)
-- Name: fn_union_pnl_inventory_snapshot_save(timestamp with time zone, timestamp with time zone, bigint, bigint, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_inventory_snapshot_save(p_at timestamp with time zone, p_base timestamp with time zone, p_rows bigint, p_issues bigint, p_rows_md5 text, p_issues_md5 text, p_max bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 TRUNCATE public.union_pnl_inventory_seal_snapshot_head,public.union_pnl_inventory_seal_snapshot;
 INSERT INTO public.union_pnl_inventory_seal_snapshot
  SELECT p_at,s.* FROM pg_temp.union_pnl_inventory_seal s;
 INSERT INTO public.union_pnl_inventory_seal_snapshot_head VALUES(p_at,p_base,p_rows,p_issues,p_rows_md5,p_issues_md5,p_max);
 EXECUTE 'DROP TABLE pg_temp.union_pnl_inventory_seal';
 IF NOT public.fn_union_pnl_inventory_snapshot_restore(p_at,p_base) THEN
  RAISE EXCEPTION 'inventory_snapshot_readback_missing' USING ERRCODE='55000'; END IF;
END $$;


ALTER FUNCTION public.fn_union_pnl_inventory_snapshot_save(p_at timestamp with time zone, p_base timestamp with time zone, p_rows bigint, p_issues bigint, p_rows_md5 text, p_issues_md5 text, p_max bigint) OWNER TO postgres;

--
-- TOC entry 7869 (class 1255 OID 67041601)
-- Name: fn_union_pnl_inventory_state(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_inventory_state(p_base timestamp with time zone, p_at timestamp with time zone) RETURNS TABLE(o_kind text, o_source_name text, o_row_id uuid, o_event_id bigint, o_first_operation text, o_after_row jsonb)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    SET work_mem TO '64MB'
    SET enable_indexscan TO 'off'
    SET max_parallel_workers_per_gather TO '0'
    AS $$
BEGIN
 -- Plain index scans are off: measured on production 2026-09-28, a cold week
 -- range read through the boundary index one heap page at a time costs
 -- ~235us an event (7.8M events: ~30 min); the same range as a bitmap heap
 -- scan, pages in physical order, ~45us (~6 min), less in parallel.
 IF p_at IS NULL OR NOT isfinite(p_at) OR (p_base IS NOT NULL AND (NOT isfinite(p_base) OR p_base>p_at)) THEN
  RAISE EXCEPTION 'invalid_inventory_state_window' USING ERRCODE='22023'; END IF;
 RETURN QUERY
 WITH d AS MATERIALIZED (
  SELECT e.source_name sn,e.row_id rid,e.event_id eid,e.operation op,
   jsonb_hash_extended(e.before_row,0) b0,jsonb_hash_extended(e.before_row,1) b1,
   jsonb_hash_extended(e.after_row,0) a0,jsonb_hash_extended(e.after_row,1) a1
  FROM public.union_pnl_inventory_events e
  WHERE e.observed_at>=COALESCE(p_base,'-infinity'::timestamptz) AND e.observed_at<p_at
 ), b AS MATERIALIZED (
  SELECT r.source_name sn,r.row_id rid,r.latest_event_id eid,r.first_operation fop,r.after_row,
   jsonb_hash_extended(r.after_row,0) a0,jsonb_hash_extended(r.after_row,1) a1
  FROM public.union_pnl_inventory_published_rows r WHERE r.boundary=p_base
 ), t AS MATERIALIZED (
  SELECT d.sn,d.rid,min(d.eid) min_id,max(d.eid) max_id FROM d GROUP BY d.sn,d.rid
 ), x AS MATERIALIZED (
  -- A delta event ordered (by event_id) before the row's last pre-base event:
  -- that row's whole chain is re-read below instead of continued.
  SELECT t.sn,t.rid FROM t JOIN b ON b.sn=t.sn AND b.rid=t.rid WHERE t.min_id<b.eid
 ), w AS MATERIALIZED (
  SELECT d.sn,d.rid,d.eid,d.b0,d.b1,
   row_number() OVER p k,lag(d.a0) OVER p pa0,lag(d.a1) OVER p pa1,first_value(d.op) OVER p fop
  FROM d WHERE NOT EXISTS(SELECT 1 FROM x WHERE x.sn=d.sn AND x.rid=d.rid)
  WINDOW p AS (PARTITION BY d.sn,d.rid ORDER BY d.eid)
 ), tl AS MATERIALIZED (
  -- The latest row image of each continued row, fetched in one pass in
  -- physical order rather than one random heap read per row.
  SELECT e.event_id eid,e.after_row FROM public.union_pnl_inventory_events e
  WHERE e.event_id=ANY(ARRAY(SELECT t.max_id FROM t WHERE NOT EXISTS(SELECT 1 FROM x WHERE x.sn=t.sn AND x.rid=t.rid)))
 ), xh AS MATERIALIZED (
  -- LATERAL: always one identity-index read per interleaved row, never a join
  -- plan that scans the history.
  SELECT e.sn,e.rid,e.eid,e.before_row,e.after_row,
   row_number() OVER p k,row_number() OVER (PARTITION BY e.sn,e.rid ORDER BY e.eid DESC) latest,
   lag(e.after_row) OVER p prior_after,first_value(e.op) OVER p fop
  FROM x CROSS JOIN LATERAL (
   SELECT h.source_name sn,h.row_id rid,h.event_id eid,h.operation op,h.before_row,h.after_row
   FROM public.union_pnl_inventory_events h WHERE h.source_name=x.sn AND h.row_id=x.rid AND h.observed_at<p_at) e
  WINDOW p AS (PARTITION BY e.sn,e.rid ORDER BY e.eid)
 )
 SELECT 'row'::text,b.sn,b.rid,b.eid,b.fop,b.after_row FROM b
  WHERE NOT EXISTS(SELECT 1 FROM t WHERE t.sn=b.sn AND t.rid=b.rid)
 UNION ALL
 SELECT 'row',t.sn,t.rid,t.max_id,COALESCE(b.fop,w.fop),tl.after_row
  FROM t JOIN w ON w.sn=t.sn AND w.rid=t.rid AND w.k=1
  JOIN tl ON tl.eid=t.max_id
  LEFT JOIN b ON b.sn=t.sn AND b.rid=t.rid
 UNION ALL
 SELECT 'row',xh.sn,xh.rid,xh.eid,xh.fop,xh.after_row FROM xh WHERE xh.latest=1
 UNION ALL
 SELECT 'issue',i.source_name,i.row_id,i.event_id,NULL::text,NULL::jsonb FROM public.union_pnl_inventory_published_issues i
  WHERE i.boundary=p_base AND NOT EXISTS(SELECT 1 FROM x WHERE x.sn=i.source_name AND x.rid=i.row_id)
 UNION ALL
 SELECT 'issue',w.sn,w.rid,w.eid,NULL,NULL FROM w WHERE w.k>1 AND (w.pa0,w.pa1) IS DISTINCT FROM (w.b0,w.b1)
 UNION ALL
 SELECT 'issue',w.sn,w.rid,w.eid,NULL,NULL FROM w JOIN b ON b.sn=w.sn AND b.rid=w.rid
  WHERE w.k=1 AND (b.a0,b.a1) IS DISTINCT FROM (w.b0,w.b1)
 UNION ALL
 SELECT 'issue',xh.sn,xh.rid,xh.eid,NULL,NULL FROM xh WHERE xh.k>1 AND xh.prior_after IS DISTINCT FROM xh.before_row;
END $$;


ALTER FUNCTION public.fn_union_pnl_inventory_state(p_base timestamp with time zone, p_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 5987 (class 1255 OID 69681028)
-- Name: fn_union_pnl_inventory_touch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_inventory_touch() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 INSERT INTO public.union_pnl_inventory_touches(event_id,source_name,row_id,observed_at,transaction_id,frame_observed_at,operation,tournament_id,union_id)
 VALUES(NEW.event_id,NEW.source_name,NEW.row_id,NEW.observed_at,NEW.transaction_id,
  (SELECT b.observed_at FROM public.union_pnl_transaction_frames b WHERE b.transaction_id=NEW.transaction_id),NEW.operation,
  COALESCE(NEW.after_row,NEW.before_row)->>'tournament_id',COALESCE(NEW.after_row,NEW.before_row)->>'union_id')
 ON CONFLICT (event_id) DO NOTHING;
 RETURN NULL;
END $$;


ALTER FUNCTION public.fn_union_pnl_inventory_touch() OWNER TO postgres;

--
-- TOC entry 4276 (class 1255 OID 69166153)
-- Name: fn_union_pnl_linked_cash_outcomes(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_linked_cash_outcomes(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(table_id uuid, hand_number bigint, game_scope jsonb, evidence jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT r.table_id,r.hand_number,r.game_scope,r.evidence
 FROM public.union_pnl_cash_outcome_link_resolutions r
 JOIN public.union_pnl_cash_outcomes o ON o.table_id=r.table_id AND o.hand_number=r.hand_number
 WHERE r.game_scope->>'game_union_id'=p_union_id::text AND o.recognized_at>=p_start AND o.recognized_at<p_end
  AND r.hand_id=o.hand_id AND r.outcome_payload_hash=o.payload_hash AND r.outcome_evidence_md5=md5(o.evidence::text)
  AND r.proof_md5=md5(r.proof::text)
$$;


ALTER FUNCTION public.fn_union_pnl_linked_cash_outcomes(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 2877 (class 1259 OID 69024918)
-- Name: union_pnl_opening_registration_resolutions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.union_pnl_opening_registration_resolutions (
    boundary timestamp with time zone NOT NULL,
    registration_id uuid NOT NULL,
    tournament_id uuid NOT NULL,
    user_id uuid NOT NULL,
    union_id uuid NOT NULL,
    registration_row_md5 text NOT NULL,
    tournament_row_md5 text NOT NULL,
    owning_club_id uuid NOT NULL,
    asset text NOT NULL,
    entries integer NOT NULL,
    entry_amount numeric NOT NULL,
    returned numeric NOT NULL,
    deferred_amount numeric NOT NULL,
    resolution_kind text NOT NULL,
    proof jsonb NOT NULL,
    proof_md5 text NOT NULL,
    reason text NOT NULL,
    resolved_by text DEFAULT SESSION_USER NOT NULL,
    resolved_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT union_pnl_opening_registration_resol_registration_row_md5_check CHECK ((registration_row_md5 ~ '^[0-9a-f]{32}$'::text)),
    CONSTRAINT union_pnl_opening_registration_resolut_tournament_row_md5_check CHECK ((tournament_row_md5 ~ '^[0-9a-f]{32}$'::text)),
    CONSTRAINT union_pnl_opening_registration_resolution_resolution_kind_check CHECK ((resolution_kind = 'opening_registration_entry_from_chip_ledger'::text)),
    CONSTRAINT union_pnl_opening_registration_resolutions_asset_check CHECK ((asset = 'chips'::text)),
    CONSTRAINT union_pnl_opening_registration_resolutions_check CHECK ((deferred_amount = (entry_amount - returned))),
    CONSTRAINT union_pnl_opening_registration_resolutions_check1 CHECK ((proof_md5 = md5((proof)::text))),
    CONSTRAINT union_pnl_opening_registration_resolutions_check2 CHECK (((jsonb_typeof(proof) = 'object'::text) AND ((proof ->> 'status'::text) = 'proven'::text) AND ((proof ->> 'resolution_kind'::text) = resolution_kind) AND (((proof ->> 'boundary'::text))::timestamp with time zone = boundary) AND ((proof ->> 'registration_id'::text) = (registration_id)::text) AND ((proof ->> 'tournament_id'::text) = (tournament_id)::text) AND ((proof ->> 'user_id'::text) = (user_id)::text) AND ((proof ->> 'union_id'::text) = (union_id)::text) AND ((proof ->> 'registration_row_md5'::text) = registration_row_md5) AND ((proof ->> 'tournament_row_md5'::text) = tournament_row_md5) AND ((proof ->> 'owning_club_id'::text) = (owning_club_id)::text) AND ((proof ->> 'instrument'::text) = asset) AND (((proof ->> 'entries'::text))::integer = entries) AND (((proof ->> 'entry_amount'::text))::numeric = entry_amount) AND (((proof ->> 'returned'::text))::numeric = returned) AND (((proof ->> 'deferred_amount'::text))::numeric = deferred_amount))),
    CONSTRAINT union_pnl_opening_registration_resolutions_entries_check CHECK ((entries >= 1)),
    CONSTRAINT union_pnl_opening_registration_resolutions_entry_amount_check CHECK (((entry_amount >= (0)::numeric) AND (entry_amount = round(entry_amount, 2)))),
    CONSTRAINT union_pnl_opening_registration_resolutions_reason_check CHECK ((length(btrim(reason)) >= 20)),
    CONSTRAINT union_pnl_opening_registration_resolutions_returned_check CHECK (((returned >= (0)::numeric) AND (returned = round(returned, 2))))
);


ALTER TABLE public.union_pnl_opening_registration_resolutions OWNER TO postgres;

--
-- TOC entry 4894 (class 1255 OID 69024985)
-- Name: fn_union_pnl_opening_registration_resolution(uuid, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_opening_registration_resolution(p_union_id uuid, p_at timestamp with time zone, p_tournament jsonb, p_registration jsonb) RETURNS SETOF public.union_pnl_opening_registration_resolutions
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT r.* FROM public.union_pnl_opening_registration_resolutions r
 WHERE r.boundary=p_at AND r.registration_id::text=p_registration->>'id' AND r.union_id=p_union_id
  AND p_tournament->>'union_id'=p_union_id::text AND p_registration->>'tournament_id'=p_tournament->>'id'
  AND r.tournament_id::text=p_tournament->>'id' AND r.user_id::text=p_registration->>'user_id'
  AND r.registration_row_md5=md5(p_registration::text) AND r.tournament_row_md5=md5(p_tournament::text)
  AND r.proof_md5=md5(r.proof::text) AND r.proof->>'status'='proven'
$$;


ALTER FUNCTION public.fn_union_pnl_opening_registration_resolution(p_union_id uuid, p_at timestamp with time zone, p_tournament jsonb, p_registration jsonb) OWNER TO postgres;

--
-- TOC entry 3406 (class 1255 OID 35411305)
-- Name: fn_union_pnl_original_flow_evidence(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_original_flow_evidence(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(ledger_id uuid, club_id uuid, user_id uuid, buyins numeric, cashouts numeric, kind text, valid boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 WITH originals AS MATERIALIZED (
  SELECT q.*,q.ledger_snapshot l,(q.game_scope->>'tournament_id')::uuid tournament_id
  FROM public.union_pnl_original_flows q WHERE q.game_scope->>'game_union_id'=p_union_id::text
   AND q.recognized_at>=p_start AND q.recognized_at<p_end
 ), rf_original_keys AS MATERIALIZED (
  SELECT DISTINCT q.transaction_id,(q.l->>'table_id')::uuid table_id,
   (q.l->>'club_id')::uuid club_id,(q.l->>'to_entity_id')::uuid user_id,(q.l->>'amount')::numeric amount
  FROM originals q
  WHERE q.tournament_id IS NULL AND q.l->>'from_type'='table_stack'
   AND q.l->>'to_type'='player_wallet' AND q.l->>'category'='player_funding'
 ), rf_original_matches AS MATERIALIZED (
  SELECT k.transaction_id,k.table_id,k.club_id,k.user_id,k.amount,count(*) refunds,
   min(o.funding_club_id::text)::uuid club,min(o.user_id::text)::uuid player
  FROM rf_original_keys k
  JOIN public.cash_funding_application_receipts a ON a.transaction_id=k.transaction_id
   AND a.refunded>0 AND a.refunded=k.amount
  JOIN public.cash_participant_funding_receipts o ON o.id=a.funding_receipt_id
  WHERE a.pending_addon_id IS NOT DISTINCT FROM o.pending_addon_id AND a.original_occupancy_id=o.occupancy_id
   AND o.table_id=k.table_id AND o.account_type='player_wallet' AND o.account_entity_id=k.user_id
   AND o.funding_club_id=k.club_id AND o.user_id=k.user_id
  GROUP BY k.transaction_id,k.table_id,k.club_id,k.user_id,k.amount
 ), matched AS (
  SELECT q.*,f.id cash_funding_id,f.funding_club_id cash_club,f.user_id cash_user,f.amount cash_amount,
   e.id entry_id,e.funding_club_id entry_club,e.user_id entry_user,e.amount entry_amount,
   c.ledger_id credit_id,c.credited_club_id credit_club,c.user_id credit_user,c.amount credit_amount,
   ret.owners,ret.funding_club_id return_club,ret.user_id return_user,mv.moved_club,mv.moved_user,
   COALESCE(rf.refunds,0) refunds,rf.club refund_club,rf.player refund_user,te.refund_ent,te.refund_ent_user,te.refund_ent_club,late.n late_count,late.club late_club,late.player late_user,late.delta late_delta
  FROM originals q
  LEFT JOIN LATERAL (
   SELECT count(*) n,min(p.club_id::text)::uuid club,min(p.user_id::text)::uuid player,min(p.delta) delta
   FROM (SELECT q.ledger_id WHERE q.tournament_id IS NULL
    AND q.l->>'category'='settlement' AND q.l->>'idempotency_key' LIKE 'late_seat_settle:%' OFFSET 0) eligible
   CROSS JOIN LATERAL public.fn_union_pnl_prove_late_settlement(eligible.ledger_id) p
  ) late ON true
  -- One-time filter (20261001): a probe only for the flows that can match.
  LEFT JOIN LATERAL (SELECT f.* FROM public.cash_participant_funding_receipts f
   WHERE q.tournament_id IS NULL AND f.source_ledger_id=q.ledger_id OFFSET 0) f ON true
  LEFT JOIN LATERAL (SELECT e.* FROM public.tournament_participant_funding_receipts e
   WHERE q.tournament_id IS NOT NULL AND e.ledger_id=q.ledger_id AND e.asset='chips' AND q.tournament_id=e.tournament_id OFFSET 0) e ON true
  -- fn_union_pnl_tournament_returns(q.tournament_id,NULL,p_start,p_end) for
  -- this flow's ledger only: its two branches verbatim, keyed by the ledger.
  LEFT JOIN LATERAL (
   SELECT c.ledger_id,c.tournament_id,c.user_id,c.credited_club_id,c.amount
   FROM public.tournament_accounting_credit_receipts c
   JOIN public.union_pnl_transaction_frames b ON b.transaction_id=c.transaction_id
   WHERE q.tournament_id IS NOT NULL AND c.ledger_id=q.ledger_id AND c.tournament_id=q.tournament_id
    AND b.observed_at>=p_start AND b.observed_at<p_end
   UNION ALL
   SELECT t.credit_ledger_id,t.tournament_id,t.user_id,t.source_wallet_club_id,t.amount_paid_now
   FROM public.tournament_refund_tranches t
   JOIN public.tournament_participant_funding_receipts r ON r.entitlement_id=t.entitlement_id
   JOIN public.union_pnl_transaction_frames b ON b.transaction_id=t.transaction_id
   WHERE q.tournament_id IS NOT NULL AND t.credit_ledger_id=q.ledger_id AND t.tournament_id=q.tournament_id
    AND b.observed_at>=p_start AND b.observed_at<p_end
    AND NOT EXISTS(SELECT 1 FROM public.tournament_accounting_credit_receipts c2 WHERE c2.ledger_id=t.credit_ledger_id)
  ) c ON true
  LEFT JOIN LATERAL (
   SELECT count(DISTINCT (r.funding_club_id,r.user_id)) owners,min(r.funding_club_id::text)::uuid funding_club_id,min(r.user_id::text)::uuid user_id
   FROM public.cash_participant_funding_receipts r
   WHERE r.table_id=(q.l->>'table_id')::uuid AND r.operation_kind='buyin'
    AND q.tournament_id IS NULL AND q.l->>'from_type'='table_stack'
    AND r.account_type=q.l->>'to_type' AND r.account_entity_id=(q.l->>'to_entity_id')::uuid
    AND r.funding_club_id=(q.l->>'club_id')::uuid
    AND (EXISTS(SELECT 1 FROM public.union_pnl_inventory_events i WHERE i.transaction_id=q.transaction_id AND i.source_name='table_seats'
      AND COALESCE(i.after_row,i.before_row)->>'occupancy_id'=r.occupancy_id::text
      AND COALESCE(i.after_row,i.before_row)->>'table_id'=r.table_id::text)
     OR EXISTS(SELECT 1 FROM public.cash_funding_application_receipts a JOIN public.cash_participant_funding_receipts original ON original.id=a.funding_receipt_id
       WHERE a.transaction_id=q.transaction_id AND original.occupancy_id=r.occupancy_id AND a.refunded=(q.l->>'amount')::numeric))
  ) ret ON true
  -- A seat cashed out after it arrived by a table move holds chips whose
  -- original buy-in is on the source occupancy, not this one. The occupancy
  -- the cash-out vacated (its seat row in the same original transaction,
  -- carrying exactly the cashed-out stack) is traced through its move receipts
  -- by fn_cash_original_funding_lineage, the proof the boundaries and hands
  -- already use; the owner is its one original buy-in's club and player.
  LEFT JOIN LATERAL (
   SELECT CASE WHEN lin.v->'issues'='[]'::jsonb AND jsonb_array_length(lin.v->'moves')>0 AND own.receipts>0 AND own.buyins=1
     AND own.clubs=1 AND own.users=1 AND own.club::text=q.l->>'club_id' AND own.player::text=q.l->>'to_entity_id'
     THEN own.club END moved_club,
    CASE WHEN lin.v->'issues'='[]'::jsonb AND jsonb_array_length(lin.v->'moves')>0 AND own.receipts>0 AND own.buyins=1
     AND own.clubs=1 AND own.users=1 AND own.club::text=q.l->>'club_id' AND own.player::text=q.l->>'to_entity_id'
     THEN own.player END moved_user
   FROM (SELECT min(i.before_row::text)::jsonb seat,count(*) n FROM public.union_pnl_inventory_events i
     WHERE q.tournament_id IS NULL AND q.l->>'from_type'='table_stack' AND q.l->>'to_type'='player_wallet'
      AND ret.owners IS DISTINCT FROM 1
      AND i.transaction_id=q.transaction_id AND i.source_name='table_seats' AND i.before_row->>'table_id'=q.l->>'table_id'
      AND i.before_row->>'user_id'=q.l->>'to_entity_id' AND i.before_row->'left_at'='null'::jsonb
      AND i.after_row->>'left_at' IS NOT NULL) s
   CROSS JOIN LATERAL (SELECT public.fn_cash_original_funding_lineage((s.seat->>'user_id')::uuid,(s.seat->>'table_id')::uuid,(s.seat->>'id')::uuid,
     (s.seat->>'occupancy_id')::uuid,(s.seat->>'joined_at')::timestamptz,q.recognized_at,false) v) lin
   CROSS JOIN LATERAL (SELECT count(*) receipts,count(*) FILTER(WHERE r.operation_kind='buyin') buyins,count(DISTINCT r.funding_club_id) clubs,
     count(DISTINCT r.user_id) users,min(r.funding_club_id::text)::uuid club,min(r.user_id::text)::uuid player
    FROM jsonb_array_elements(lin.v->'funding_receipts') ref JOIN public.cash_participant_funding_receipts r ON r.id=(ref->>'id')::uuid) own
   WHERE q.tournament_id IS NULL AND q.l->>'from_type'='table_stack' AND q.l->>'to_type'='player_wallet' AND ret.owners IS DISTINCT FROM 1
    AND s.n=1 AND public.fn_pnl_evidence_cents(s.seat->'stack') IS NOT DISTINCT FROM (q.l->>'amount')::numeric
  ) mv ON true
  -- A pending add-on returned unapplied is a refund of this player's own
  -- escrowed chips. Its wallet credit can carry no refund category: it runs
  -- inside the hand's post-commit obligations, after atomic_distribute_rake
  -- has declared that transaction's ledger context, so the audit labels it
  -- player_funding under the rake settlement. The application receipt
  -- written in the same transaction proves it: exactly one refund of this
  -- amount from a funding receipt of this player, club and table.
  LEFT JOIN LATERAL (
   SELECT r.refunds,r.club,r.player FROM rf_original_matches r
   WHERE q.tournament_id IS NULL AND q.l->>'from_type'='table_stack'
    AND q.l->>'to_type'='player_wallet' AND q.l->>'category'='player_funding'
    AND r.transaction_id=q.transaction_id AND r.table_id=(q.l->>'table_id')::uuid
    AND r.club_id=(q.l->>'club_id')::uuid AND r.user_id=(q.l->>'to_entity_id')::uuid
    AND r.amount=(q.l->>'amount')::numeric
  ) rf ON true
  -- A seat won in a satellite and later refunded by the target tournament
  -- (cancelled, or the seat released) pays the seat's value back to the
  -- player's wallet from the target's prize liability. That seat was never a
  -- wallet-funded entry of the target, so no tournament credit receipt exists
  -- for it; its proof is the refund entitlement the payout is keyed by: same
  -- tournament, player, wallet club and gross, and the seat's owning club as
  -- resolved from its satellite registration.
  LEFT JOIN LATERAL (
   SELECT t.id refund_ent,t.user_id refund_ent_user,t.refund_wallet_club_id refund_ent_club
   FROM public.tournament_refund_entitlements t
   WHERE q.tournament_id IS NOT NULL AND t.tournament_id=q.tournament_id
    AND q.l->>'idempotency_key'='tourney:'||t.tournament_id::text||':refund-entitlement:'||t.id::text
    AND t.entitlement_kind IN('satellite_seat','wallet_charge','tournament_ticket') AND t.gross=(q.l->>'amount')::numeric
    AND t.user_id::text=q.l->>'to_entity_id' AND t.refund_wallet_club_id::text=q.l->>'club_id'
    AND q.l->>'from_type'='prize_liability' AND q.l->>'to_type'='player_wallet' AND q.l->>'category'='refund'
    AND CASE t.entitlement_kind
     WHEN 'satellite_seat' THEN public.fn_union_pnl_satellite_seat_owner(t.registration_id,NULL)=t.refund_wallet_club_id
     -- A pre-capture wallet entry refunded by cancellation (20261006154000):
     -- its entitlement's source ledger is the entry proven at the opening
     -- boundary of the refund's own week, for this exact registration, club
     -- and gross.
     WHEN 'wallet_charge' THEN t.source_ledger_id IS NOT NULL AND (SELECT count(*) FROM public.union_pnl_opening_registration_resolutions r
       WHERE r.boundary=public.fn_union_week_start(q.recognized_at) AND r.union_id=p_union_id AND r.tournament_id=t.tournament_id AND r.user_id=t.user_id
        AND r.owning_club_id=t.refund_wallet_club_id AND r.entries=1 AND r.entry_amount=t.gross AND r.returned=0
        AND r.proof_md5=md5(r.proof::text)
        AND r.proof->'entry_ledger' @> jsonb_build_array(jsonb_build_object('ledger_id',t.source_ledger_id::text)))=1
     WHEN 'tournament_ticket' THEN t.charge_category='tournament_ticket'
      AND t.evidence_kind='atomic_tournament_ticket' AND t.escrow_bucket='ticket_gross'
      AND q.l->>'from_entity_id'=t.tournament_id::text
      AND NOT EXISTS(SELECT 1 FROM public.tournament_tickets replacement WHERE replacement.source_refund_entitlement_id=t.id)
      AND (SELECT count(*) FROM public.tournament_refund_entitlements duplicate WHERE duplicate.source_ticket_id=t.source_ticket_id)=1
      AND (SELECT count(*) FROM public.tournament_refund_tranches tr
       WHERE tr.entitlement_id=t.id AND tr.credit_ledger_id=q.ledger_id AND tr.transaction_id=q.transaction_id
        AND tr.tournament_id=t.tournament_id AND tr.user_id=t.user_id AND tr.source_wallet_club_id=t.refund_wallet_club_id
        AND tr.idempotency_key=q.l->>'idempotency_key' AND tr.amount_paid_before=0 AND tr.amount_paid_now=t.gross
        AND tr.refund_prize=t.refund_prize AND tr.refund_bounty=t.refund_bounty AND tr.refund_fee=t.refund_fee)=1
      AND (SELECT count(*) FROM public.tournament_refund_tranches tr WHERE tr.entitlement_id=t.id)=1
      AND (SELECT count(*) FROM public.tournament_tickets tk
       JOIN public.chip_ledger admission ON admission.id=t.source_ledger_id
       JOIN public.tournament_satellite_awards a ON a.ticket_id=tk.id
       JOIN public.tournament_satellite_settlements h ON h.tournament_id=a.tournament_id
       JOIN public.tournament_payouts p ON p.id=a.payout_id
       JOIN public.chip_ledger issue ON issue.idempotency_key=a.idempotency_key||':ticket_escrow'
       WHERE tk.id=t.source_ticket_id AND tk.holder_id=t.user_id AND tk.club_id=t.refund_wallet_club_id
        AND tk.status='redeemed' AND tk.redemption_mode='tournament_entry_only' AND tk.cancelled_at IS NULL
        AND tk.value=t.gross AND tk.entry_prize=t.refund_prize AND tk.entry_bounty=t.refund_bounty AND tk.entry_fee=t.refund_fee
        AND t.gross=t.refund_prize+t.refund_bounty+t.refund_fee
        AND tk.source_tournament_id=t.tournament_id AND tk.source_satellite_id=t.source_satellite_id
        -- Only the original direct award is admitted here. A replacement
        -- ticket still requires its distinct original refund disposition.
        AND tk.source_refund_entitlement_id IS NULL
        AND a.tournament_id=tk.source_satellite_id AND a.place=tk.source_satellite_award_place
        AND a.user_id=t.user_id AND a.delivery_kind='ticket' AND a.amount=t.gross AND a.payout_source='satellite_ticket'
        AND p.tournament_id=a.tournament_id AND p.user_id=a.user_id AND p.amount=a.amount
        AND p.source=a.payout_source AND p.idempotency_key=a.idempotency_key
        AND (p.position=a.place OR h.receipt_version>=3)
        AND h.target_id=t.tournament_id AND h.ticket_cost=t.gross
        AND h.target_buy_in=tk.entry_prize+tk.entry_bounty AND h.target_fee=tk.entry_fee
        AND issue.status='posted' AND issue.category='ticket_issue' AND issue.amount=t.gross
        AND issue.club_id=tk.club_id AND issue.tournament_id=a.tournament_id
        AND issue.from_type='prize_liability' AND issue.from_entity_id=a.tournament_id
        AND issue.to_type='escrow' AND issue.to_entity_id=tk.id
        AND issue.metadata->>'kind'='direct_satellite_entry_ticket'
        AND issue.metadata->>'ticket_id'=tk.id::text AND issue.metadata->>'payout_id'=p.id::text
        AND issue.metadata->>'user_id'=t.user_id::text
        AND issue.metadata->>'satellite_target_id'=t.tournament_id::text
        AND COALESCE(issue.metadata->>'position',issue.metadata->>'award_slot')=a.place::text
        AND NOT EXISTS(SELECT 1 FROM public.wallet_credit_idempotency w WHERE w.key=a.idempotency_key)
        AND (SELECT count(*) FROM public.chip_transactions x
          WHERE x.transaction_type='tournament_ticket_issue' AND x.club_id=tk.club_id
           AND x.from_user_id IS NULL AND x.to_user_id=t.user_id AND x.amount=t.gross
           AND x.metadata->>'ticket_id'=tk.id::text AND x.metadata->>'ledger_id'=issue.id::text
           AND x.metadata->>'payout_id'=p.id::text AND x.metadata->>'idempotency_key'=a.idempotency_key
           AND x.metadata->>'source_tournament_id'=t.tournament_id::text
           AND x.metadata->>'source_satellite_id'=a.tournament_id::text
           AND x.metadata->>'source_award_place'=a.place::text)=1
        AND admission.status='posted' AND admission.category='ticket_redeem' AND admission.amount=t.gross
        AND admission.club_id=tk.club_id AND admission.tournament_id=t.tournament_id
        AND admission.from_type='escrow' AND admission.from_entity_id=tk.id
        AND admission.to_type='prize_liability' AND admission.to_entity_id=t.tournament_id
        AND admission.idempotency_key='ticket:'||tk.id::text||':tournament:'||t.tournament_id::text||':entry'
        AND admission.metadata->>'kind'='tournament_entry_ticket_admission'
        AND admission.metadata->>'ticket_id'=tk.id::text AND admission.metadata->>'user_id'=t.user_id::text
        AND admission.metadata->>'registration_id'=t.registration_id::text
        AND admission.metadata->>'source_tournament_id'=t.tournament_id::text
        AND admission.metadata->>'source_satellite_id'=t.source_satellite_id::text
        AND admission.metadata->'entry_prize'=to_jsonb(t.refund_prize)
        AND admission.metadata->'entry_bounty'=to_jsonb(t.refund_bounty)
        AND admission.metadata->'entry_fee'=to_jsonb(t.refund_fee))=1
     ELSE false END
  ) te ON true
 ), projected AS (
  SELECT *,CASE WHEN late_count=1 THEN 'cash_late_settlement' WHEN cash_funding_id IS NOT NULL THEN 'cash_funding' WHEN owners=1 OR moved_club IS NOT NULL OR refunds=1 THEN 'cash_return'
    WHEN entry_id IS NOT NULL THEN 'tournament_funding' WHEN credit_id IS NOT NULL OR refund_ent IS NOT NULL THEN 'tournament_return' ELSE 'unsupported' END k,
   COALESCE(late_club,cash_club,CASE WHEN moved_club IS NOT NULL THEN moved_club WHEN owners=1 THEN return_club ELSE refund_club END,entry_club,credit_club,refund_ent_club) owner_club,
   COALESCE(late_user,cash_user,CASE WHEN moved_club IS NOT NULL THEN moved_user WHEN owners=1 THEN return_user ELSE refund_user END,entry_user,credit_user,refund_ent_user) owner_user
  FROM matched
 ) SELECT ledger_id,owner_club,owner_user,
  CASE WHEN k='cash_late_settlement' AND late_delta<0 THEN -late_delta WHEN k IN('cash_funding','tournament_funding') THEN (l->>'amount')::numeric ELSE 0 END,
  CASE WHEN k='cash_late_settlement' AND late_delta>0 THEN late_delta WHEN k IN('cash_return','tournament_return') THEN (l->>'amount')::numeric ELSE 0 END,k,
  (l->>'status'='posted' AND public.fn_pnl_evidence_cents(l->'amount')>0 AND owner_club IS NOT NULL AND owner_user IS NOT NULL
   AND owner_club::text=l->>'club_id' AND game_scope->>'asset'='chips' AND game_scope->'unit_scale'='2'::jsonb
   AND CASE k
    WHEN 'cash_late_settlement' THEN late_count=1 AND abs(late_delta)=(l->>'amount')::numeric
    WHEN 'cash_funding' THEN cash_amount=(l->>'amount')::numeric AND l->>'to_type'='table_stack' AND l->>'category' IN('buyin','rebuy','addon','horse_funding')
    WHEN 'cash_return' THEN (owners=1 OR moved_club IS NOT NULL OR (refunds=1 AND l->>'category'='player_funding')) AND l->>'from_type'='table_stack' AND (l->>'category' IN('cashout','table_cashout','refund')
     OR (l->>'category'='player_funding' AND refunds=1 AND refund_club=owner_club AND refund_user=owner_user))
    WHEN 'tournament_funding' THEN entry_amount=(l->>'amount')::numeric AND l->>'to_type'='prize_liability' AND l->>'category' IN('tournament_buyin','rebuy','addon')
    WHEN 'tournament_return' THEN (credit_amount=(l->>'amount')::numeric OR (credit_id IS NULL AND refund_ent IS NOT NULL)) AND l->>'from_type'='prize_liability' AND l->>'category' IN('tournament_prize','prize','bounty','refund','tournament_refund')
    ELSE false END) IS TRUE
 FROM projected
 UNION ALL SELECT * FROM smarter_private.original_restoration_cash_returns(p_union_id,p_start,p_end)
 UNION ALL SELECT * FROM smarter_private.original_erased_cash_discharge_returns(p_union_id,p_start,p_end);
$$;


ALTER FUNCTION public.fn_union_pnl_original_flow_evidence(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 2761 (class 1259 OID 35411215)
-- Name: union_pnl_transaction_frames; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.union_pnl_transaction_frames (
    transaction_id xid8 NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    book_start timestamp with time zone NOT NULL,
    CONSTRAINT union_pnl_transaction_frames_observed_at_check CHECK (isfinite(observed_at))
);


ALTER TABLE public.union_pnl_transaction_frames OWNER TO postgres;

--
-- TOC entry 5826 (class 1255 OID 35411265)
-- Name: fn_union_pnl_original_frame(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_original_frame() RETURNS public.union_pnl_transaction_frames
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE frame public.union_pnl_transaction_frames; observed timestamptz; book timestamptz;
BEGIN
 SELECT * INTO frame FROM public.union_pnl_transaction_frames WHERE transaction_id=pg_current_xact_id();
 IF FOUND THEN RETURN frame; END IF;
 observed:=clock_timestamp(); book:=public.fn_union_week_start(observed);
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('union-pnl-inventory:'||extract(epoch FROM book)::bigint::text,0));
 observed:=clock_timestamp();
 IF public.fn_union_week_start(observed)<>book THEN
  book:=public.fn_union_week_start(observed);
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('union-pnl-inventory:'||extract(epoch FROM book)::bigint::text,0));
  observed:=clock_timestamp();
  IF public.fn_union_week_start(observed)<>book THEN RAISE EXCEPTION 'pnl_frame_clock_crossed_twice' USING ERRCODE='40001'; END IF;
 END IF;
 INSERT INTO public.union_pnl_transaction_frames VALUES(pg_current_xact_id(),observed,book) RETURNING * INTO frame;
 RETURN frame;
END $$;


ALTER FUNCTION public.fn_union_pnl_original_frame() OWNER TO postgres;

--
-- TOC entry 8570 (class 1255 OID 34785824)
-- Name: fn_union_pnl_posted_payment_evidence(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_posted_payment_evidence(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE c public.union_pnl_settlements%ROWTYPE; s public.ca_settlements%ROWTYPE;
 v_count int; v_expected int:=0; v_actual int; v_net numeric; v_collect numeric:=0; v_pay numeric:=0;
 v_club uuid; v_seen uuid[]:=ARRAY[]::uuid[]; x jsonb; v_legs jsonb:='[]'; v_ids jsonb; v_issues jsonb:='[]';
BEGIN
 IF p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end) OR p_end<=p_start THEN
  RAISE EXCEPTION 'invalid_pnl_evidence_period' USING ERRCODE='22023'; END IF;
 SELECT count(*) INTO v_count FROM public.union_pnl_settlements
  WHERE union_id=p_union_id AND period_start=p_start AND period_end=p_end AND status='settled';
 IF v_count<>1 THEN RETURN jsonb_build_object('status',CASE WHEN v_count=0 THEN 'not_posted' ELSE 'unverified' END,
  'settled_in_chips',false,'basis_certified',false,'reason','exact_settled_pnl_claim_missing_or_ambiguous','claim_count',v_count); END IF;
 SELECT * INTO c FROM public.union_pnl_settlements
  WHERE union_id=p_union_id AND period_start=p_start AND period_end=p_end AND status='settled';
 IF c.settled_at IS NULL OR NOT isfinite(c.settled_at) OR c.total_unpaid IS DISTINCT FROM 0
  OR public.fn_pnl_evidence_cents(to_jsonb(c.total_collected)) IS NULL OR c.total_collected<0
  OR public.fn_pnl_evidence_cents(to_jsonb(c.total_paid)) IS NULL OR c.total_paid<0
  OR jsonb_typeof(c.club_results) IS DISTINCT FROM 'array' THEN
  RETURN jsonb_build_object('status','unverified','settled_in_chips',false,'basis_certified',false,'claim_id',c.id,'reason','invalid_or_partial_pnl_claim'); END IF;
 SELECT count(*) INTO v_count FROM public.ca_settlements
  WHERE settlement_type='union_player_pnl' AND union_id=p_union_id
   AND idempotency_key='pnl:'||p_union_id::text||':'||extract(epoch FROM p_start)::bigint::text AND state='final';
 IF v_count<>1 THEN RETURN jsonb_build_object('status','unverified','settled_in_chips',false,'basis_certified',false,
  'claim_id',c.id,'reason','final_pnl_posting_receipt_missing_or_ambiguous'); END IF;
 SELECT * INTO s FROM public.ca_settlements WHERE settlement_type='union_player_pnl' AND union_id=p_union_id
  AND idempotency_key='pnl:'||p_union_id::text||':'||extract(epoch FROM p_start)::bigint::text AND state='final';
 FOR x IN SELECT value FROM jsonb_array_elements(c.club_results) LOOP
  BEGIN v_club:=(x->>'club_id')::uuid; EXCEPTION WHEN invalid_text_representation THEN v_club:=NULL; END;
  v_net:=public.fn_pnl_evidence_cents(x->'net');
  IF v_club IS NULL OR v_club=ANY(v_seen) OR v_net IS NULL THEN
   RETURN jsonb_build_object('status','unverified','settled_in_chips',false,'basis_certified',false,'claim_id',c.id,'reason','invalid_or_duplicate_club_obligation'); END IF;
  v_seen:=array_append(v_seen,v_club);
  IF v_net=0 THEN CONTINUE; END IF;
  v_expected:=v_expected+1; v_collect:=v_collect+greatest(-v_net,0); v_pay:=v_pay+greatest(v_net,0);
  SELECT count(*),COALESCE(jsonb_agg(l.id ORDER BY l.id),'[]') INTO v_count,v_ids
   FROM public.chip_ledger l JOIN public.settlement_invoices i ON i.source_ledger_id=l.id
   WHERE l.settlement_id=s.id::text AND l.club_id=v_club AND l.union_id=p_union_id
    AND l.category='pnl_settlement' AND l.status='posted' AND l.amount=abs(v_net)
    AND l.from_type=CASE WHEN v_net<0 THEN 'club_treasury' ELSE 'union_wallet' END
    AND l.from_entity_id=CASE WHEN v_net<0 THEN v_club ELSE p_union_id END
    AND l.to_type=CASE WHEN v_net<0 THEN 'union_wallet' ELSE 'club_treasury' END
    AND l.to_entity_id=CASE WHEN v_net<0 THEN p_union_id ELSE v_club END
    AND public.fn_pnl_evidence_cents(to_jsonb(CASE WHEN v_net<0 THEN l.pre_from_balance ELSE l.pre_to_balance END)) IS NOT NULL
    AND public.fn_pnl_evidence_cents(to_jsonb(CASE WHEN v_net<0 THEN l.post_from_balance ELSE l.post_to_balance END)) IS NOT NULL
    AND CASE WHEN v_net<0 THEN l.pre_from_balance ELSE l.pre_to_balance END>=0
    AND CASE WHEN v_net<0 THEN l.post_from_balance ELSE l.post_to_balance END>=0
    AND CASE WHEN v_net<0 THEN l.post_from_balance-l.pre_from_balance ELSE l.post_to_balance-l.pre_to_balance END=v_net
    AND i.club_id=v_club AND i.status='paid' AND i.chips_transferred AND i.message_sent
    AND i.from_entity_type=CASE WHEN v_net<0 THEN 'club' ELSE 'union' END
    AND i.from_entity_id=CASE WHEN v_net<0 THEN v_club ELSE p_union_id END::text
    AND i.to_entity_type=CASE WHEN v_net<0 THEN 'union' ELSE 'club' END
    AND i.to_entity_id=CASE WHEN v_net<0 THEN p_union_id ELSE v_club END::text
    AND i.gross_amount=abs(v_net) AND i.net_amount=abs(v_net) AND i.deductions=0;
  v_legs:=v_legs||jsonb_build_array(jsonb_build_object('club_id',v_club,'claimed_net',v_net,
   'verified_posted_net',CASE WHEN v_count=1 THEN v_net ELSE NULL END,'posted_receipt_count',v_count,'source_ledger_ids',v_ids));
  IF v_count<>1 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','club_posted_payment_receipt_missing_or_ambiguous','club_id',v_club)); END IF;
 END LOOP;
 SELECT count(*) INTO v_actual FROM public.chip_ledger WHERE settlement_id=s.id::text AND category='pnl_settlement';
 IF v_actual<>v_expected OR v_collect<>c.total_collected OR v_pay<>c.total_paid
  OR public.fn_pnl_evidence_cents(s.totals->'collected') IS DISTINCT FROM v_collect
  OR public.fn_pnl_evidence_cents(s.totals->'paid') IS DISTINCT FROM v_pay
  OR public.fn_pnl_evidence_cents(s.totals->'unpaid') IS DISTINCT FROM 0::numeric
 THEN v_issues:=v_issues||'"pnl_posting_totals_or_leg_count_mismatch"'::jsonb; END IF;
 RETURN jsonb_build_object('status',CASE WHEN jsonb_array_length(v_issues)=0 THEN 'verified' ELSE 'unverified' END,
  'settled_in_chips',jsonb_array_length(v_issues)=0 AND v_expected>0,'basis_certified',false,
  'claim_id',c.id,'posting_id',s.id,'no_chip_movement',v_expected=0,'clubs',v_legs,'issues',v_issues);
END $$;


ALTER FUNCTION public.fn_union_pnl_posted_payment_evidence(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 8418 (class 1255 OID 155269169)
-- Name: fn_union_pnl_posthand_escrow_participants(public.union_pnl_cash_outcomes); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_posthand_escrow_participants(o public.union_pnl_cash_outcomes) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE actual public.union_pnl_cash_outcomes; proof jsonb; projected jsonb;
BEGIN
 SELECT * INTO actual FROM public.union_pnl_cash_outcomes q WHERE q.table_id=o.table_id AND q.hand_number=o.hand_number;
 IF NOT FOUND OR to_jsonb(actual) IS DISTINCT FROM to_jsonb(o) THEN RAISE EXCEPTION 'posthand_escrow_projection_original_disagrees' USING ERRCODE='55000';END IF;
 IF smarter_private.posthand_escrow_certified_evidence(o.table_id,o.hand_number) IS NULL THEN RETURN o.evidence->'participants';END IF;
 proof:=public.fn_union_pnl_prove_posthand_escrow(o.table_id,o.hand_number);
 IF proof->>'status' IS DISTINCT FROM 'proven' THEN RETURN o.evidence->'participants';END IF;
 IF proof->>'table_id' IS DISTINCT FROM o.table_id::text OR proof->>'hand_number' IS DISTINCT FROM o.hand_number::text
  OR proof->>'hand_id' IS DISTINCT FROM o.hand_id::text OR proof->>'outcome_payload_hash' IS DISTINCT FROM o.payload_hash
  OR proof->>'outcome_evidence_md5' IS DISTINCT FROM md5(o.evidence::text)
  OR jsonb_array_length(proof->'participants')<>jsonb_array_length(o.evidence->'participants') THEN
  RAISE EXCEPTION 'posthand_escrow_projection_proof_disagrees' USING ERRCODE='55000';END IF;
 SELECT jsonb_agg(original.participant||jsonb_build_object('earning_club_id',p.participant->'earning_club_id','ownership_certified',true) ORDER BY original.n)
 INTO projected FROM jsonb_array_elements(o.evidence->'participants') WITH ORDINALITY original(participant,n)
 JOIN LATERAL jsonb_array_elements(proof->'participants') p(participant) ON p.participant->>'user_id'=original.participant->>'user_id'
  AND public.fn_pnl_evidence_cents(original.participant->'observed_stack_delta')=public.fn_pnl_evidence_cents(p.participant->'poker_delta');
 IF projected IS NULL OR jsonb_array_length(projected)<>jsonb_array_length(o.evidence->'participants') THEN
  RAISE EXCEPTION 'posthand_escrow_projection_original_roster_disagrees' USING ERRCODE='55000';END IF;
 RETURN projected;
END $$;


ALTER FUNCTION public.fn_union_pnl_posthand_escrow_participants(o public.union_pnl_cash_outcomes) OWNER TO postgres;

--
-- TOC entry 5209 (class 1255 OID 155269170)
