--

CREATE FUNCTION public.fn_union_pnl_posthand_escrow_touch(h public.union_pnl_cash_outcome_touches) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE o public.union_pnl_cash_outcomes;
