--
-- TOC entry 8681 (class 1255 OID 67041344)
-- Name: fn_union_pnl_resolve_blocked_cash_outcome(uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_resolve_blocked_cash_outcome(p_table_id uuid, p_hand_number bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_proof jsonb; v_prior public.union_pnl_cash_outcome_resolutions%ROWTYPE;
BEGIN
 IF p_table_id IS NULL OR p_hand_number IS NULL THEN RAISE EXCEPTION 'invalid_outcome_identity' USING ERRCODE='22023'; END IF;
 IF p_reason IS NULL OR length(btrim(p_reason))<20 THEN RAISE EXCEPTION 'resolution_reason_required' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('union_pnl_cash_outcome_resolution:'||p_table_id::text||':'||p_hand_number::text,0));
 SELECT * INTO v_prior FROM public.union_pnl_cash_outcome_resolutions WHERE table_id=p_table_id AND hand_number=p_hand_number;
 IF FOUND THEN
  RETURN jsonb_build_object('status','already_resolved','table_id',p_table_id,'hand_number',p_hand_number,
   'resolution_kind',v_prior.resolution_kind,'late_total',v_prior.proof->'late_total','resolved_at',v_prior.resolved_at);
 END IF;
 v_proof:=public.fn_union_pnl_prove_late_seat_credit(p_table_id,p_hand_number);
 IF v_proof->>'status' IS DISTINCT FROM 'proven' THEN RETURN v_proof; END IF;
 INSERT INTO public.union_pnl_cash_outcome_resolutions(table_id,hand_number,hand_id,outcome_payload_hash,outcome_evidence_md5,
  resolution_kind,proof,reason)
 VALUES(p_table_id,p_hand_number,(v_proof->>'hand_id')::uuid,v_proof->>'outcome_payload_hash',v_proof->>'outcome_evidence_md5',
  v_proof->>'resolution_kind',v_proof,btrim(p_reason));
 RETURN v_proof||jsonb_build_object('status','resolved');
END $$;


ALTER FUNCTION public.fn_union_pnl_resolve_blocked_cash_outcome(p_table_id uuid, p_hand_number bigint, p_reason text) OWNER TO postgres;

--
-- TOC entry 5041 (class 1255 OID 67041358)
-- Name: fn_union_pnl_resolve_blocked_cash_week(uuid, timestamp with time zone, timestamp with time zone, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_resolve_blocked_cash_week(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_reason text, p_apply boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE c record; v jsonb; v_blocked integer:=0; v_proven integer:=0; v_resolved integer:=0; v_already integer:=0;
 v_refused integer:=0; v_late numeric:=0; v_refusals jsonb:='[]';
BEGIN
 IF p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end)
  OR p_end<=p_start OR p_end-p_start>interval '8 days' THEN
  RAISE EXCEPTION 'invalid_resolution_period' USING ERRCODE='22023'; END IF;
 IF p_apply IS NOT FALSE AND (p_reason IS NULL OR length(btrim(p_reason))<20) THEN
  RAISE EXCEPTION 'resolution_reason_required' USING ERRCODE='22023'; END IF;
 -- Ascending hand order: a hand whose previous hand is itself resolvable is
 -- re-proved after that previous hand's receipt exists.
 FOR c IN SELECT o.table_id,o.hand_number,o.recognized_at FROM public.union_pnl_cash_outcomes o
  WHERE o.game_scope->>'game_union_id'=p_union_id::text AND o.recognized_at>=p_start AND o.recognized_at<p_end
   AND (o.evidence->>'status' IS DISTINCT FROM 'ready' OR o.evidence->'basis_certified' IS DISTINCT FROM 'true'::jsonb
    OR o.evidence->'all_players_included' IS DISTINCT FROM 'true'::jsonb OR o.evidence->'game_scope' IS DISTINCT FROM o.game_scope)
  ORDER BY o.hand_number LOOP
  v_blocked:=v_blocked+1;
  IF p_apply THEN
   v:=public.fn_union_pnl_resolve_blocked_cash_outcome(c.table_id,c.hand_number,p_reason);
  ELSIF EXISTS(SELECT 1 FROM public.union_pnl_cash_outcome_resolutions r WHERE r.table_id=c.table_id AND r.hand_number=c.hand_number) THEN
   v:=jsonb_build_object('status','already_resolved');
  ELSE
   v:=public.fn_union_pnl_prove_late_seat_credit(c.table_id,c.hand_number);
  END IF;
  CASE v->>'status'
   WHEN 'resolved' THEN v_resolved:=v_resolved+1; v_late:=v_late+(v->>'late_total')::numeric;
   WHEN 'proven' THEN v_proven:=v_proven+1; v_late:=v_late+(v->>'late_total')::numeric;
   WHEN 'already_resolved' THEN v_already:=v_already+1;
   ELSE v_refused:=v_refused+1;
    v_refusals:=v_refusals||jsonb_build_array(jsonb_build_object('table_id',c.table_id,'hand_number',c.hand_number,
     'recognized_at',c.recognized_at,'reason',v->>'reason'));
  END CASE;
 END LOOP;
 RETURN jsonb_build_object('union_id',p_union_id,'period_start',p_start,'period_end',p_end,'applied',p_apply IS NOT FALSE,
  'blocked_outcomes',v_blocked,'proven_not_written',v_proven,'resolved_now',v_resolved,'already_resolved',v_already,
  'refused',v_refused,'late_credit_total',v_late,'refusals',v_refusals);
END $$;


ALTER FUNCTION public.fn_union_pnl_resolve_blocked_cash_week(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_reason text, p_apply boolean) OWNER TO postgres;

--
-- TOC entry 4959 (class 1255 OID 69166195)
-- Name: fn_union_pnl_resolve_cash_outcome_links(timestamp with time zone, timestamp with time zone, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_resolve_cash_outcome_links(p_start timestamp with time zone, p_end timestamp with time zone, p_reason text, p_apply boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE c record; v_cand integer:=0; v_proven integer:=0; v_resolved integer:=0; v_already integer:=0; v_refused integer:=0;
 v_ready integer:=0; v_refusals jsonb:='{}'; v_unions jsonb:='{}'; v_key text; v_n integer;
BEGIN
 IF p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end) OR p_end<=p_start OR p_end-p_start>interval '8 days' THEN
  RAISE EXCEPTION 'invalid_resolution_period' USING ERRCODE='22023'; END IF;
 IF p_apply IS NOT FALSE AND (p_reason IS NULL OR length(btrim(p_reason))<20) THEN
  RAISE EXCEPTION 'resolution_reason_required' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('union_pnl_cash_outcome_link_resolution',0));
 FOR c IN SELECT * FROM public.fn_union_pnl_prove_cash_outcome_links(p_start,p_end) LOOP
  v_cand:=v_cand+1;
  IF c.proof->>'status'='proven' THEN
   IF c.proof#>>'{evidence,status}'='ready' THEN v_ready:=v_ready+1; END IF;
   v_key:=COALESCE(c.proof#>>'{game_scope,game_union_id}','no_union');
   v_unions:=v_unions||jsonb_build_object(v_key,jsonb_build_object('hands',COALESCE((v_unions#>>ARRAY[v_key,'hands'])::integer,0)+1,
    'accepted_rake',COALESCE((v_unions#>>ARRAY[v_key,'accepted_rake'])::numeric,0)+(c.proof#>>'{evidence,accepted_rake}')::numeric,
    'observed_delta_total',COALESCE((v_unions#>>ARRAY[v_key,'observed_delta_total'])::numeric,0)+(c.proof#>>'{evidence,observed_delta_total}')::numeric));
   IF EXISTS(SELECT 1 FROM public.union_pnl_cash_outcome_link_resolutions r WHERE r.table_id=c.table_id AND r.hand_number=c.hand_number) THEN
    v_already:=v_already+1;
   ELSIF p_apply THEN
    INSERT INTO public.union_pnl_cash_outcome_link_resolutions(table_id,hand_number,hand_id,outcome_payload_hash,outcome_evidence_md5,
     roster_source,manifest_id,game_scope,evidence,proof,proof_md5,reason)
    VALUES(c.table_id,c.hand_number,(c.proof->>'hand_id')::uuid,c.proof->>'outcome_payload_hash',c.proof->>'outcome_evidence_md5',
     c.proof->>'roster_source',(c.proof->>'manifest_id')::uuid,c.proof->'game_scope',c.proof->'evidence',c.proof,md5(c.proof::text),btrim(p_reason));
    v_resolved:=v_resolved+1;
   ELSE v_proven:=v_proven+1; END IF;
  ELSE
   v_refused:=v_refused+1; v_n:=COALESCE((v_refusals->>(c.proof->>'reason'))::integer,0)+1;
   v_refusals:=v_refusals||jsonb_build_object(c.proof->>'reason',v_n);
  END IF;
 END LOOP;
 RETURN jsonb_build_object('period_start',p_start,'period_end',p_end,'applied',p_apply IS NOT FALSE,'candidates',v_cand,
  'proven_not_written',v_proven,'resolved_now',v_resolved,'already_resolved',v_already,'refused',v_refused,'refusals',v_refusals,
  'evidence_ready',v_ready,'by_union',v_unions);
END $$;


ALTER FUNCTION public.fn_union_pnl_resolve_cash_outcome_links(p_start timestamp with time zone, p_end timestamp with time zone, p_reason text, p_apply boolean) OWNER TO postgres;

--
-- TOC entry 6912 (class 1255 OID 69025001)
-- Name: fn_union_pnl_resolve_opening_registrations(uuid, timestamp with time zone, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_resolve_opening_registrations(p_union_id uuid, p_at timestamp with time zone, p_reason text, p_apply boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE c record; v_cand integer:=0; v_proven integer:=0; v_resolved integer:=0; v_already integer:=0; v_refused integer:=0;
 v_entry numeric:=0; v_returned numeric:=0; v_deferred numeric:=0; v_refusals jsonb:='{}'; v_refused_amount numeric:=0; v_n integer;
BEGIN
 IF p_union_id IS NULL OR p_at IS NULL OR NOT isfinite(p_at) OR p_at<>public.fn_union_week_start(p_at) OR p_at>clock_timestamp() THEN
  RAISE EXCEPTION 'invalid_resolution_boundary' USING ERRCODE='22023'; END IF;
 IF p_apply IS NOT FALSE AND (p_reason IS NULL OR length(btrim(p_reason))<20) THEN
  RAISE EXCEPTION 'resolution_reason_required' USING ERRCODE='22023'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.union_pnl_inventory_checkpoints k WHERE k.boundary=p_at) THEN
  RAISE EXCEPTION 'boundary_checkpoint_missing' USING ERRCODE='55000'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('union_pnl_opening_registration_resolution:'||p_union_id::text||':'||p_at::text,0));
 FOR c IN SELECT * FROM public.fn_union_pnl_prove_opening_registrations(p_union_id,p_at) LOOP
  v_cand:=v_cand+1;
  IF c.proof->>'status'='proven' THEN
   IF EXISTS(SELECT 1 FROM public.union_pnl_opening_registration_resolutions r WHERE r.boundary=p_at AND r.registration_id=c.registration_id) THEN
    v_already:=v_already+1;
   ELSIF p_apply THEN
    INSERT INTO public.union_pnl_opening_registration_resolutions(boundary,registration_id,tournament_id,user_id,union_id,
     registration_row_md5,tournament_row_md5,owning_club_id,asset,entries,entry_amount,returned,deferred_amount,resolution_kind,proof,proof_md5,reason)
    VALUES(p_at,c.registration_id,c.tournament_id,(c.proof->>'user_id')::uuid,p_union_id,c.proof->>'registration_row_md5',c.proof->>'tournament_row_md5',
     (c.proof->>'owning_club_id')::uuid,c.proof->>'instrument',(c.proof->>'entries')::integer,(c.proof->>'entry_amount')::numeric,
     (c.proof->>'returned')::numeric,(c.proof->>'deferred_amount')::numeric,c.proof->>'resolution_kind',c.proof,md5(c.proof::text),btrim(p_reason));
    v_resolved:=v_resolved+1;
   ELSE
    v_proven:=v_proven+1;
   END IF;
   v_entry:=v_entry+(c.proof->>'entry_amount')::numeric; v_returned:=v_returned+(c.proof->>'returned')::numeric;
   v_deferred:=v_deferred+(c.proof->>'deferred_amount')::numeric;
  ELSE
   v_refused:=v_refused+1; v_refused_amount:=v_refused_amount+COALESCE((c.proof->>'entry_amount')::numeric,0);
   v_n:=COALESCE((v_refusals->>(c.proof->>'reason'))::integer,0)+1;
   v_refusals:=v_refusals||jsonb_build_object(c.proof->>'reason',v_n);
  END IF;
 END LOOP;
 RETURN jsonb_build_object('union_id',p_union_id,'boundary',p_at,'applied',p_apply IS NOT FALSE,'candidates',v_cand,
  'proven_not_written',v_proven,'resolved_now',v_resolved,'already_resolved',v_already,'refused',v_refused,
  'refusals',v_refusals,'refused_entry_amount',v_refused_amount,
  'entry_amount',v_entry,'returned',v_returned,'deferred_amount',v_deferred);
END $$;


ALTER FUNCTION public.fn_union_pnl_resolve_opening_registrations(p_union_id uuid, p_at timestamp with time zone, p_reason text, p_apply boolean) OWNER TO postgres;

--
-- TOC entry 4845 (class 1255 OID 154117383)
-- Name: fn_union_pnl_resolve_original_unchanged_stack(uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_resolve_original_unchanged_stack(p_table_id uuid, p_hand_number bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_proof jsonb; v_prior public.union_pnl_cash_outcome_resolutions%ROWTYPE;
BEGIN
 IF p_table_id IS NULL OR p_hand_number IS NULL OR p_hand_number<1 THEN RAISE EXCEPTION 'invalid_outcome_identity' USING ERRCODE='22023'; END IF;
 IF p_reason IS NULL OR length(btrim(p_reason))<20 THEN RAISE EXCEPTION 'resolution_reason_required' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('union_pnl_cash_outcome_resolution:'||p_table_id::text||':'||p_hand_number::text,0));
 SELECT * INTO v_prior FROM public.union_pnl_cash_outcome_resolutions WHERE table_id=p_table_id AND hand_number=p_hand_number;
 IF FOUND THEN
  IF NOT EXISTS(SELECT 1 FROM public.union_pnl_cash_outcomes o WHERE o.table_id=p_table_id AND o.hand_number=p_hand_number
     AND o.hand_id=v_prior.hand_id AND o.payload_hash=v_prior.outcome_payload_hash AND md5(o.evidence::text)=v_prior.outcome_evidence_md5)
   OR v_prior.resolution_kind IS DISTINCT FROM 'original_stack_unchanged_since_accepted_predecessor' THEN
   RETURN jsonb_build_object('status','refused','reason','existing_resolution_differs'); END IF;
  RETURN jsonb_build_object('status','already_resolved','table_id',p_table_id,'hand_number',p_hand_number,'resolved_at',v_prior.resolved_at);
 END IF;
 v_proof:=public.fn_union_pnl_prove_original_unchanged_stack(p_table_id,p_hand_number);
 IF v_proof->>'status' IS DISTINCT FROM 'proven' THEN RETURN v_proof; END IF;
 INSERT INTO public.union_pnl_cash_outcome_resolutions(table_id,hand_number,hand_id,outcome_payload_hash,outcome_evidence_md5,resolution_kind,proof,reason)
 VALUES(p_table_id,p_hand_number,(v_proof->>'hand_id')::uuid,v_proof->>'outcome_payload_hash',v_proof->>'outcome_evidence_md5',v_proof->>'resolution_kind',v_proof,btrim(p_reason));
 RETURN v_proof||jsonb_build_object('status','resolved');
END $$;


ALTER FUNCTION public.fn_union_pnl_resolve_original_unchanged_stack(p_table_id uuid, p_hand_number bigint, p_reason text) OWNER TO postgres;

--
-- TOC entry 6808 (class 1255 OID 69166002)
-- Name: fn_union_pnl_satellite_seat_owner(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_satellite_seat_owner(p_registration_id uuid, p_tournament_id uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 WITH reg AS (
  SELECT e.after_row r FROM public.union_pnl_inventory_events e
  WHERE e.source_name='tournament_players' AND e.row_id=p_registration_id ORDER BY e.event_id LIMIT 1
 ), who AS (
  SELECT (r->>'user_id')::uuid user_id,(r->>'source_satellite_id')::uuid satellite_id,(r->>'registered_at')::timestamptz registered_at,
   (r->>'tournament_id')::uuid target_id
  FROM reg WHERE (p_tournament_id IS NULL OR r->>'tournament_id'=p_tournament_id::text)
   AND r->>'source_satellite_id' IS NOT NULL AND r->>'user_id' IS NOT NULL AND r->>'tournament_id' IS NOT NULL
 ), award AS (
  SELECT a.tournament_id,a.user_id FROM who w
  JOIN public.tournament_satellite_awards a ON a.tournament_id=w.satellite_id AND a.user_id=w.user_id
  JOIN public.tournament_satellite_settlements s ON s.tournament_id=a.tournament_id AND s.target_id=w.target_id
  WHERE (a.delivery_kind='seat' AND a.registration_id=p_registration_id)
   OR (a.delivery_kind='ticket' AND a.registration_id IS NULL AND EXISTS(SELECT 1 FROM public.tournament_tickets t WHERE t.id=a.ticket_id
     AND t.holder_id=w.user_id AND t.source_satellite_id=w.satellite_id AND t.source_tournament_id=w.target_id
     AND t.status='redeemed' AND t.redemption_mode='tournament_entry_only' AND t.redeemed_at=w.registered_at))
 ), entry AS (
  SELECT count(*) n,count(DISTINCT r.funding_club_id) clubs,min(r.funding_club_id::text)::uuid club,
   count(*) FILTER(WHERE r.operation='entry') entries,
   count(*) FILTER(WHERE r.asset IS DISTINCT FROM 'chips' OR r.amount IS NULL OR r.amount<=0 OR r.funding_club_id IS NULL OR NOT EXISTS(
    SELECT 1 FROM (SELECT row.* FROM public.chip_ledger row WHERE row.id=r.ledger_id OFFSET 0) l WHERE l.status='posted' AND l.from_type='player_wallet' AND l.from_entity_id=r.user_id
     AND l.to_type='prize_liability' AND l.to_entity_id=r.tournament_id AND l.tournament_id=r.tournament_id AND l.amount=r.amount
     AND l.club_id=r.funding_club_id AND l.category IN ('tournament_buyin','rebuy','addon') AND l.row_hash IS NOT NULL)) bad
  FROM award a JOIN public.tournament_participant_funding_receipts r ON r.tournament_id=a.tournament_id AND r.user_id=a.user_id
 )
 SELECT CASE WHEN (SELECT count(*) FROM award)=1 AND e.n>0 AND e.entries>=1 AND e.clubs=1 AND e.bad=0 THEN e.club END FROM entry e
$$;


ALTER FUNCTION public.fn_union_pnl_satellite_seat_owner(p_registration_id uuid, p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 3880 (class 1255 OID 69681147)
-- Name: fn_union_pnl_touched_registrations(timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_touched_registrations(p_start timestamp with time zone, p_end timestamp with time zone, p_projected boolean) RETURNS TABLE(registration_id uuid, touched_tournament_id text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF p_projected THEN
  RETURN QUERY SELECT i.row_id,i.tournament_id FROM public.union_pnl_inventory_touches i
   WHERE i.source_name='tournament_players' AND i.frame_observed_at>=p_start AND i.frame_observed_at<p_end
    AND i.observed_at>=p_start AND i.observed_at<p_end;
 ELSE
  RETURN QUERY SELECT i.row_id,COALESCE(i.after_row,i.before_row)->>'tournament_id' FROM public.union_pnl_inventory_events i
   JOIN public.union_pnl_transaction_frames b ON b.transaction_id=i.transaction_id
   WHERE i.source_name='tournament_players' AND b.observed_at>=p_start AND b.observed_at<p_end
    AND i.observed_at>=p_start AND i.observed_at<p_end;
 END IF;
END $$;


ALTER FUNCTION public.fn_union_pnl_touched_registrations(p_start timestamp with time zone, p_end timestamp with time zone, p_projected boolean) OWNER TO postgres;

--
-- TOC entry 2757 (class 1259 OID 35372402)
-- Name: tournament_participant_funding_receipts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.tournament_participant_funding_receipts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    observed_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    registration_id uuid NOT NULL,
    tournament_id uuid NOT NULL,
    user_id uuid NOT NULL,
    operation text NOT NULL,
    purchase_key text,
    asset text NOT NULL,
    amount numeric NOT NULL,
    entitlement_id uuid,
    ledger_id uuid,
    wallet_transaction_id uuid,
    funding_club_id uuid,
    registration_snapshot jsonb NOT NULL,
    tournament_snapshot jsonb NOT NULL,
    entitlement_snapshot jsonb,
    ledger_snapshot jsonb,
    wallet_snapshot jsonb,
    custody_result jsonb,
    CONSTRAINT tournament_participant_funding_receipts_amount_check CHECK (((amount >= (0)::numeric) AND (amount = round(amount, 2)) AND ((amount)::text <> ALL (ARRAY['NaN'::text, 'Infinity'::text, '-Infinity'::text])))),
    CONSTRAINT tournament_participant_funding_receipts_asset_check CHECK ((asset = ANY (ARRAY['chips'::text, 'diamonds'::text]))),
    CONSTRAINT tournament_participant_funding_receipts_check CHECK ((((asset = 'chips'::text) AND (amount > (0)::numeric) AND (entitlement_id IS NOT NULL) AND (ledger_id IS NOT NULL) AND (wallet_transaction_id IS NOT NULL) AND (funding_club_id IS NOT NULL)) OR ((asset = 'chips'::text) AND (amount = (0)::numeric) AND (entitlement_id IS NULL) AND (ledger_id IS NULL)) OR ((asset = 'diamonds'::text) AND (entitlement_id IS NULL) AND (ledger_id IS NULL)))),
    CONSTRAINT tournament_participant_funding_receipts_operation_check CHECK ((operation = ANY (ARRAY['entry'::text, 'rebuy'::text, 'reentry'::text, 'addon'::text])))
);


ALTER TABLE public.tournament_participant_funding_receipts OWNER TO postgres;

--
-- TOC entry 4092 (class 1255 OID 35411298)
-- Name: fn_union_pnl_tournament_entry_club(public.tournament_participant_funding_receipts); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_tournament_entry_club(r public.tournament_participant_funding_receipts) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT CASE WHEN r.asset='chips' AND r.amount>0 THEN r.funding_club_id
  WHEN r.asset='chips' AND r.amount=0 AND r.ledger_id IS NULL AND r.entitlement_id IS NULL
   AND r.registration_snapshot->>'source_satellite_id' IS NULL
   AND r.registration_snapshot->'is_satellite_qualifier'='false'::jsonb
   THEN (r.registration_snapshot->>'club_id')::uuid END;
$$;


ALTER FUNCTION public.fn_union_pnl_tournament_entry_club(r public.tournament_participant_funding_receipts) OWNER TO postgres;

