--
-- TOC entry 8542 (class 1255 OID 69681156)
-- Name: fn_union_pnl_tournament_in_union(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_tournament_in_union(p_tournament_id text, p_union_id uuid, p_projected boolean) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
BEGIN
 IF p_projected THEN
  RETURN EXISTS(SELECT 1 FROM public.union_pnl_inventory_touches t WHERE t.source_name='tournaments'
   AND t.row_id=CASE WHEN p_tournament_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN p_tournament_id::uuid END
   AND t.row_id::text=p_tournament_id
   AND t.union_id=p_union_id::text);
 END IF;
 RETURN EXISTS(SELECT 1 FROM public.union_pnl_inventory_events t WHERE t.source_name='tournaments'
  AND t.row_id=CASE WHEN p_tournament_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN p_tournament_id::uuid END
  AND t.row_id::text=p_tournament_id
  AND COALESCE(t.after_row,t.before_row)->>'union_id'=p_union_id::text);
END $_$;


ALTER FUNCTION public.fn_union_pnl_tournament_in_union(p_tournament_id text, p_union_id uuid, p_projected boolean) OWNER TO postgres;

--
-- TOC entry 7927 (class 1255 OID 35411297)
-- Name: fn_union_pnl_tournament_returns(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_tournament_returns(p_tournament uuid DEFAULT NULL::uuid, p_registration uuid DEFAULT NULL::uuid, p_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(ledger_id uuid, tournament_id uuid, user_id uuid, credited_club_id uuid, amount numeric, transaction_id xid8, entry_receipt_ids uuid[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT c.ledger_id,c.tournament_id,c.user_id,c.credited_club_id,c.amount,c.transaction_id,c.entry_receipt_ids
 FROM public.tournament_accounting_credit_receipts c
 JOIN public.union_pnl_transaction_frames b ON b.transaction_id=c.transaction_id
 WHERE (p_tournament IS NULL OR c.tournament_id=p_tournament)
  AND (p_registration IS NULL OR EXISTS(SELECT 1 FROM public.tournament_participant_funding_receipts r
   WHERE r.tournament_id=c.tournament_id AND r.registration_id=p_registration AND r.id=ANY(c.entry_receipt_ids)))
  AND (p_start IS NULL OR b.observed_at>=p_start) AND (p_end IS NULL OR b.observed_at<p_end)
 UNION ALL
 SELECT t.credit_ledger_id,t.tournament_id,t.user_id,t.source_wallet_club_id,t.amount_paid_now,t.transaction_id,ARRAY[r.id]
 FROM public.tournament_refund_tranches t
 JOIN public.tournament_participant_funding_receipts r ON r.entitlement_id=t.entitlement_id
 JOIN public.union_pnl_transaction_frames b ON b.transaction_id=t.transaction_id
 WHERE (p_tournament IS NULL OR t.tournament_id=p_tournament) AND (p_registration IS NULL OR r.registration_id=p_registration)
  AND (p_start IS NULL OR b.observed_at>=p_start) AND (p_end IS NULL OR b.observed_at<p_end)
  AND NOT EXISTS(SELECT 1 FROM public.tournament_accounting_credit_receipts c WHERE c.ledger_id=t.credit_ledger_id);
$$;


ALTER FUNCTION public.fn_union_pnl_tournament_returns(p_tournament uuid, p_registration uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 9211 (class 1255 OID 70642687)
-- Name: fn_union_pnl_week_bbj_stack_awards(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_week_bbj_stack_awards(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(club_id uuid, user_id uuid, amount numeric, payout_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT (pp.p->>'earning_club_id')::uuid, r.user_id, r.amount, r.payout_id
 FROM public.bbj_payout_recipients r
 JOIN public.bbj_payouts b ON b.id=r.payout_id
 JOIN public.union_pnl_cash_outcomes o ON o.table_id=b.table_id AND o.hand_number=b.hand_number
 CROSS JOIN LATERAL (SELECT p FROM jsonb_array_elements(COALESCE(o.evidence->'participants','[]')) p
  WHERE p->>'user_id'=r.user_id::text LIMIT 1) pp
 WHERE r.created_at>=p_start AND r.created_at<p_end AND r.amount>0
  AND o.game_scope->>'game_union_id'=p_union_id::text
  -- a share paid to the wallet of a departed recipient never reached the felt
  AND NOT EXISTS(SELECT 1 FROM public.wallet_credit_idempotency w
   WHERE w.key='bbj:'||r.payout_id::text||':'||r.user_id::text)
$$;


ALTER FUNCTION public.fn_union_pnl_week_bbj_stack_awards(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 4819 (class 1255 OID 69681175)
-- Name: fn_union_pnl_week_hand_lines(uuid, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_week_hand_lines(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_projected boolean) RETURNS TABLE(hand_accepted_rake text, hand_participants jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF p_projected THEN
  RETURN QUERY SELECT h.accepted_rake,
   CASE WHEN h.shaped AND cert.hand_number IS NOT NULL THEN public.fn_union_pnl_posthand_escrow_touch(h) ELSE h.participants END
   FROM public.union_pnl_cash_outcome_touches h
   LEFT JOIN smarter_private.posthand_escrow_certificates cert ON (cert.table_id,cert.hand_number)=(h.table_id,h.hand_number)
   WHERE h.game_union_id=p_union_id::text AND h.recognized_at>=p_start AND h.recognized_at<p_end;
 ELSE
  RETURN QUERY SELECT o.evidence->>'accepted_rake',
   CASE WHEN cert.hand_number IS NOT NULL THEN public.fn_union_pnl_posthand_escrow_participants(o) ELSE o.evidence->'participants' END
   FROM public.union_pnl_cash_outcomes o
   LEFT JOIN smarter_private.posthand_escrow_certificates cert ON (cert.table_id,cert.hand_number)=(o.table_id,o.hand_number)
   WHERE o.game_scope->>'game_union_id'=p_union_id::text AND o.recognized_at>=p_start AND o.recognized_at<p_end;
 END IF;
END $$;


ALTER FUNCTION public.fn_union_pnl_week_hand_lines(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_projected boolean) OWNER TO postgres;

--
-- TOC entry 5866 (class 1255 OID 69681167)
-- Name: fn_union_pnl_week_shaped_hands(uuid, timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_pnl_week_shaped_hands(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_projected boolean) RETURNS SETOF public.union_pnl_cash_outcomes
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF p_projected THEN
  RETURN QUERY WITH candidates AS MATERIALIZED (
   SELECT q.* FROM public.union_pnl_cash_outcomes q
   WHERE q.game_scope->>'game_union_id'=p_union_id::text AND q.recognized_at>=p_start AND q.recognized_at<p_end
    AND (q.evidence->>'status' IS DISTINCT FROM 'ready' OR q.evidence->'basis_certified' IS DISTINCT FROM 'true'::jsonb
     OR q.evidence->'all_players_included' IS DISTINCT FROM 'true'::jsonb OR q.evidence->'game_scope' IS DISTINCT FROM q.game_scope)
  ) SELECT o.* FROM candidates o
   WHERE (SELECT CASE WHEN h.game_union_id=p_union_id::text AND h.recognized_at>=p_start AND h.recognized_at<p_end
    THEN h.shaped ELSE false END FROM public.union_pnl_cash_outcome_touches h
    WHERE h.table_id=o.table_id AND h.hand_number=o.hand_number) IS TRUE;
 ELSE
  RETURN QUERY SELECT o.* FROM public.union_pnl_cash_outcomes o WHERE o.game_scope->>'game_union_id'=p_union_id::text AND o.recognized_at>=p_start AND o.recognized_at<p_end
   AND (o.evidence->>'status' IS DISTINCT FROM 'ready' OR o.evidence->'basis_certified' IS DISTINCT FROM 'true'::jsonb
    OR o.evidence->'all_players_included' IS DISTINCT FROM 'true'::jsonb OR o.evidence->'game_scope' IS DISTINCT FROM o.game_scope);
 END IF;
END $$;


ALTER FUNCTION public.fn_union_pnl_week_shaped_hands(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_projected boolean) OWNER TO postgres;

--
