-- Name: FUNCTION fn_union_rake_basis_windowed(p_union_id uuid, p_start timestamp with time zone, p_through timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_union_rake_basis_windowed(p_union_id uuid, p_start timestamp with time zone, p_through timestamp with time zone) IS 'Open-week rake basis (20261003): the earned plan''s basis detail over p_start..p_through from proved two-hour windows (closed ones kept in union_rake_basis_windows while their input stamp is unchanged), combined as fn_accounting_union_earned_plan_combine; in_progress while windows remain; NULL sends the caller to fn_union_club_rake_basis.';


--
-- TOC entry 9105 (class 1255 OID 15396572)
-- Name: fn_union_rake_by_club(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_rake_by_club(p_union_id uuid, p_days integer DEFAULT 30) RETURNS TABLE(club_id uuid, club_name text, rake numeric, players bigint, player_hands bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT d.club_id,
         COALESCE(c.name, 'Union Tables')::text,
         SUM(d.rake_amount)::numeric,
         COUNT(DISTINCT d.user_id)::bigint,
         SUM(d.hands)::bigint
    FROM club_rake_daily_user d
    JOIN fn_union_club_scope(p_union_id) s ON s.club_id = d.club_id
    LEFT JOIN clubs c ON c.id = d.club_id
   WHERE public.fn_union_report_caller_ok(p_union_id)
     AND d.day >= (CURRENT_DATE - GREATEST(COALESCE(p_days, 30), 1))
   GROUP BY d.club_id, c.name
   ORDER BY 3 DESC;
$$;


ALTER FUNCTION public.fn_union_rake_by_club(p_union_id uuid, p_days integer) OWNER TO postgres;

