-- Name: FUNCTION fn_union_settlement_cascade_due(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_union_settlement_cascade_due() IS 'Settles the union week that has just closed, once. Refuses while the platform is frozen, after :45, and for any period that closed more than three days ago. Safe on any schedule; a missed day heals on the next tick.';


--
-- TOC entry 3787 (class 1255 OID 23733384)
-- Name: fn_union_settlement_conservation_assert(uuid, timestamp with time zone, timestamp with time zone, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_settlement_conservation_assert(p_union_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_r1 jsonb, p_r2 jsonb, p_r3 jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rake     numeric := (p_r1->>'period_rake')::numeric;
  v_paid     numeric := (p_r1->>'total_rakeback')::numeric;
  v_retained numeric := (p_r1->>'union_retained')::numeric;
  v_r2_amt   numeric := (p_r2->>'amount')::numeric;
  v_r3_amt   numeric := (p_r3->>'amount')::numeric;
  v_neg      text;
  v_checked  int := 0; v_totals jsonb;
BEGIN
  IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
  IF p_union_id IS NULL OR p_from IS NULL OR p_to IS NULL OR p_from IS DISTINCT FROM public.fn_union_week_start(p_from)
   OR p_to IS DISTINCT FROM public.fn_union_week_start(p_from+interval '8 days') THEN
   RAISE EXCEPTION 'invalid_conservation_scope' USING ERRCODE='22023'; END IF;
  SELECT c.totals INTO v_totals FROM public.ca_settlements c
   WHERE c.settlement_type='union_rakeback_close' AND c.union_id=p_union_id AND c.state='final'
    AND c.external_ref=p_union_id::text||':'||to_char(p_from AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
     ||'..'||to_char(p_to AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"');
  IF v_totals IS NULL OR v_totals->>'accounting_version' IS DISTINCT FROM '3' THEN
    RAISE EXCEPTION 'CONSERVATION_UNVERIFIED: exact recorded earning close is missing'; END IF;
  IF p_r1->>'error'='already_executed' THEN
    v_rake:=(v_totals->>'period_rake')::numeric;
    v_paid:=(v_totals->>'payout_total')::numeric;
    v_retained:=(v_totals->>'retained')::numeric;
  ELSIF p_r1->>'success' IS DISTINCT FROM 'true'
   OR (v_totals->>'period_rake')::numeric IS DISTINCT FROM v_rake
   OR (v_totals->>'payout_total')::numeric IS DISTINCT FROM v_paid
   OR (v_totals->>'retained')::numeric IS DISTINCT FROM v_retained THEN
    RAISE EXCEPTION 'CONSERVATION_UNVERIFIED: Round 1 response differs from its posted close'; END IF;
  IF EXISTS(SELECT 1 FROM (VALUES(2,p_r2),(3,p_r3)) input(round_no,receipt)
    WHERE input.receipt->>'success' IS DISTINCT FROM 'true'
     OR input.receipt->>'routing_version' IS DISTINCT FROM '3'
     OR input.receipt->>'source_version' IS DISTINCT FROM '2'
     OR input.receipt->'shortfalls' IS DISTINCT FROM '0'::jsonb
     OR NOT EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r WHERE r.scope_kind='union' AND r.scope_id=p_union_id
      AND r.period_start=p_from AND r.period_end=p_to AND r.round_no=input.round_no AND r.result=(input.receipt-'duplicate'))) THEN
    RAISE EXCEPTION 'CONSERVATION_UNVERIFIED: routed payment receipts do not match the exact union week'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.union_wallets w WHERE w.union_id=p_union_id)
   OR EXISTS(SELECT 1 FROM public.fn_accounting_week_clubs(p_union_id,NULL,p_from,p_to) s
    WHERE NOT EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=s.club_id)) THEN
    RAISE EXCEPTION 'CONSERVATION_UNVERIFIED: an accounting wallet is missing'; END IF;
  IF v_rake IS NULL OR v_paid IS NULL OR v_retained IS NULL OR v_r2_amt IS NULL OR v_r3_amt IS NULL THEN
    RAISE EXCEPTION 'CONSERVATION_UNVERIFIED: settlement totals are missing';
  END IF;
  IF EXISTS(SELECT 1 FROM unnest(ARRAY[v_rake,v_paid,v_retained,v_r2_amt,v_r3_amt]) n
    WHERE n::text IN ('NaN','Infinity','-Infinity') OR n<0 OR n<>round(n,2)) THEN
    RAISE EXCEPTION 'CONSERVATION_BREACH: settlement totals must be finite nonnegative whole cents';
  END IF;
  IF v_rake <> v_paid+v_retained THEN
    RAISE EXCEPTION 'CONSERVATION_BREACH round1_arithmetic: rake % <> paid % + retained %',v_rake,v_paid,v_retained;
  END IF;
  IF v_paid>v_rake THEN RAISE EXCEPTION 'CONSERVATION_BREACH round1_overpay'; END IF;
  v_checked := v_checked+2;

  -- 6. Rounds 2 and 3 never move a negative amount.
  IF COALESCE(v_r2_amt, 0) < 0 THEN
    RAISE EXCEPTION 'CONSERVATION_BREACH round2_negative_amount: %', v_r2_amt;
  END IF;
  IF COALESCE(v_r3_amt, 0) < 0 THEN
    RAISE EXCEPTION 'CONSERVATION_BREACH round3_negative_amount: %', v_r3_amt;
  END IF;
  v_checked := v_checked + 2;

  -- 3 + 4 + 5. Nothing this union touches may be negative afterwards.
  SELECT string_agg(x.pool || ' = ' || COALESCE(x.amt::text,'NULL'), '; ') INTO v_neg
    FROM (
      SELECT 'union chip wallet' AS pool, w.chip_balance AS amt
        FROM union_wallets w
       WHERE w.union_id = p_union_id AND (w.chip_balance < 0 OR w.chip_balance IS NULL OR w.chip_balance::text IN('NaN','Infinity','-Infinity') OR w.chip_balance<>round(w.chip_balance,2))
      UNION ALL
      SELECT 'union rake wallet', w.rake_wallet
        FROM union_wallets w
       WHERE w.union_id = p_union_id AND (w.rake_wallet < 0 OR w.rake_wallet IS NULL OR w.rake_wallet::text IN('NaN','Infinity','-Infinity') OR w.rake_wallet<>round(w.rake_wallet,2))
      UNION ALL
      SELECT 'club treasury ' || c.name, c.chip_treasury
        FROM clubs c
        JOIN public.fn_accounting_week_clubs(p_union_id,NULL,p_from,p_to) uc ON uc.club_id = c.id
       WHERE (c.chip_treasury < 0 OR c.chip_treasury IS NULL OR c.chip_treasury::text IN('NaN','Infinity','-Infinity') OR c.chip_treasury<>round(c.chip_treasury,2))
      UNION ALL
      SELECT 'member wallet ' || cm.user_id::text, cm.chip_balance
        FROM club_members cm
        JOIN public.fn_accounting_week_clubs(p_union_id,NULL,p_from,p_to) uc ON uc.club_id = cm.club_id
       WHERE (cm.chip_balance < 0 OR cm.chip_balance IS NULL OR cm.chip_balance::text IN('NaN','Infinity','-Infinity') OR cm.chip_balance<>round(cm.chip_balance,2))
    ) x;

  IF v_neg IS NOT NULL THEN
    RAISE EXCEPTION 'CONSERVATION_BREACH negative_pool after settlement: %', left(v_neg, 400);
  END IF;
  v_checked := v_checked + 3;

  RETURN jsonb_build_object(
    'conservation', 'asserted',
    'checks', v_checked,
    'period_start', p_from, 'period_end', p_to,
    'round1_rake', v_rake, 'round1_paid', v_paid, 'round1_retained', v_retained,
    'round2_amount', v_r2_amt, 'round3_amount', v_r3_amt);
END $$;


ALTER FUNCTION public.fn_union_settlement_conservation_assert(p_union_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_r1 jsonb, p_r2 jsonb, p_r3 jsonb) OWNER TO postgres;

--
-- TOC entry 49532 (class 0 OID 0)
-- Dependencies: 3787
-- Name: FUNCTION fn_union_settlement_conservation_assert(p_union_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_r1 jsonb, p_r2 jsonb, p_r3 jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_union_settlement_conservation_assert(p_union_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_r1 jsonb, p_r2 jsonb, p_r3 jsonb) IS 'Raises CONSERVATION_BREACH if a union settlement does not balance. Called inside fn_union_settlement_cascade before it commits, so a breach rolls the settlement back rather than reporting it afterwards.';


--
-- TOC entry 9614 (class 1255 OID 14523806)
-- Name: fn_union_settlement_preview(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_union_settlement_preview(p_union_id uuid DEFAULT 'fade0000-0000-0000-0000-000000000001'::uuid, p_period_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_period_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_from timestamptz := COALESCE(p_period_start, public.fn_union_prev_week_start(now()));
  v_to   timestamptz := COALESCE(p_period_end,   public.fn_union_week_start(now()));
  v_r1_done boolean;
  v_rake_wallet numeric;
  v_r2_total numeric := 0; v_r2_payees int := 0;
  v_r3_total numeric := 0; v_r3_payees int := 0;
  v_r2_short jsonb := '[]'::jsonb;
  v_r3_short jsonb := '[]'::jsonb;
  v_r2_short_amt numeric := 0; v_r3_short_amt numeric := 0;
BEGIN
  IF NOT public.fn_caller_is_engine()
     AND (auth.uid() IS NULL OR NOT public.fn_is_union_overseer(p_union_id, auth.uid())) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.union_rakeback_log
     WHERE union_id = p_union_id
       AND period_start = v_from AND period_end = v_to)
    INTO v_r1_done;

  SELECT COALESCE(rake_wallet, 0)
    INTO v_rake_wallet
    FROM public.union_wallets
   WHERE union_id = p_union_id;

  -- ROUND 2. One parameterized partial-index scan per active pair, not two
  -- whole-ledger scans and not one paid-period function call per ledger row.
  WITH active_pairs AS MATERIALIZED (
    SELECT uc.club_id, a.user_id
      FROM public.union_clubs uc
      JOIN public.agents a
        ON a.club_id = uc.club_id AND a.status = 'active'
     WHERE uc.union_id = p_union_id
       -- A single settlement row covering this whole preview interval means
       -- every candidate row for the pair is already paid.
       AND NOT EXISTS (
         SELECT 1 FROM public.agent_commission_settlements covered
          WHERE covered.club_id = uc.club_id
            AND covered.user_id = a.user_id
            AND covered.period_start <= v_from
            AND covered.period_end >= v_to)
     GROUP BY uc.club_id, a.user_id
  ),
  owed AS MATERIALIZED (
    SELECT p.club_id, p.user_id, pair_sum.amt
      FROM active_pairs p
      CROSS JOIN LATERAL (
        SELECT SUM(ac.amount) AS amt
          FROM public.agent_commissions ac
         WHERE ac.club_id = p.club_id
           AND ac.user_id = p.user_id
           AND ac.created_at >= v_from
           AND ac.created_at < v_to
           AND ac.settled_at IS NULL
           AND NOT EXISTS (
             SELECT 1 FROM public.agent_commission_settlements s
              WHERE s.club_id = ac.club_id
                AND s.user_id = ac.user_id
                AND ac.created_at >= s.period_start
                AND ac.created_at < s.period_end)
      ) pair_sum
     WHERE pair_sum.amt IS NOT NULL
  ),
  byclub AS MATERIALIZED (
    SELECT o.club_id, SUM(o.amt) AS club_owed,
           COALESCE(c.chip_treasury, 0) AS treasury, c.name
      FROM owed o
      JOIN public.clubs c ON c.id = o.club_id
     GROUP BY o.club_id, c.chip_treasury, c.name
  ),
  short_clubs AS MATERIALIZED (
    SELECT b.club_id,
           jsonb_build_object(
             'club_id', b.club_id, 'club', b.name,
             'owed', b.club_owed, 'treasury', b.treasury,
             'short_by', round(b.club_owed - b.treasury, 2)) AS detail,
           b.club_owed - b.treasury AS short_by
      FROM byclub b
     WHERE b.treasury < b.club_owed
  )
  SELECT COALESCE((SELECT SUM(o.amt) FROM owed o WHERE o.amt > 0), 0),
         COALESCE((SELECT COUNT(*) FROM owed o WHERE o.amt > 0), 0)::int,
         COALESCE((SELECT jsonb_agg(s.detail ORDER BY s.club_id) FROM short_clubs s),
                  '[]'::jsonb),
         COALESCE((SELECT SUM(s.short_by) FROM short_clubs s), 0)
    INTO v_r2_total, v_r2_payees, v_r2_short, v_r2_short_amt;

  -- ROUND 3. The player grouping is the common exact fact set. Positive
  -- player totals feed payees; all player totals feed each paying agent's
  -- shortage, preserving the two preimage aggregates without two base scans.
  WITH owed AS MATERIALIZED (
    SELECT rp.user_id AS player_id, rp.club_id, cm.agent_id AS agent_user,
           SUM(rp.rakeback_amount) AS amt
      FROM public.rakeback_periods rp
      JOIN public.union_clubs uc
        ON uc.club_id = rp.club_id AND uc.union_id = p_union_id
      JOIN public.club_members cm
        ON cm.user_id = rp.user_id AND cm.club_id = rp.club_id
     WHERE rp.status = 'pending'
       AND rp.period_start >= v_from::date
       AND rp.period_start < v_to::date + 1
       AND cm.agent_id IS NOT NULL
     GROUP BY rp.user_id, rp.club_id, cm.agent_id
  ),
  byagent AS MATERIALIZED (
    SELECT o.club_id, o.agent_user, SUM(o.amt) AS agent_owed,
           COALESCE(am.chip_balance, 0) AS agent_balance,
           public.fn_arena_name(pr.alias, pr.username, pr.display_name,
                                pr.first_name, pr.last_name, pr.full_name) AS agent_name
      FROM owed o
      LEFT JOIN public.club_members am
        ON am.user_id = o.agent_user AND am.club_id = o.club_id
      LEFT JOIN public.profiles pr ON pr.id = o.agent_user
     GROUP BY o.club_id, o.agent_user, am.chip_balance,
              pr.alias, pr.username, pr.display_name,
              pr.first_name, pr.last_name, pr.full_name
  ),
  short_agents AS MATERIALIZED (
    SELECT a.club_id, a.agent_user,
           jsonb_build_object(
             'agent_user_id', a.agent_user,
             'agent', a.agent_name,
             'club_id', a.club_id, 'owed', a.agent_owed,
             'agent_balance', a.agent_balance,
             'short_by', round(a.agent_owed - a.agent_balance, 2)) AS detail,
           a.agent_owed - a.agent_balance AS short_by
      FROM byagent a
     WHERE a.agent_balance < a.agent_owed
  )
  SELECT COALESCE((SELECT SUM(o.amt) FROM owed o WHERE o.amt > 0), 0),
         COALESCE((SELECT COUNT(*) FROM owed o WHERE o.amt > 0), 0)::int,
         COALESCE((SELECT jsonb_agg(s.detail ORDER BY s.club_id, s.agent_user)
                     FROM short_agents s), '[]'::jsonb),
         COALESCE((SELECT SUM(s.short_by) FROM short_agents s), 0)
    INTO v_r3_total, v_r3_payees, v_r3_short, v_r3_short_amt;

  RETURN jsonb_build_object(
    'union_id', p_union_id,
    'period_start', v_from, 'period_end', v_to,
    'round1', jsonb_build_object(
      'already_executed', v_r1_done,
      'rake_treasury_available', v_rake_wallet),
    'round2', jsonb_build_object(
      'payees', v_r2_payees, 'amount', round(v_r2_total, 2),
      'clubs_short', jsonb_array_length(v_r2_short),
      'short_by', round(v_r2_short_amt, 2), 'detail', v_r2_short),
    'round3', jsonb_build_object(
      'payees', v_r3_payees, 'amount', round(v_r3_total, 2),
      'agents_short', jsonb_array_length(v_r3_short),
      'short_by', round(v_r3_short_amt, 2), 'detail', v_r3_short),
    'total_to_move', round(v_r2_total + v_r3_total, 2),
    'has_blockers',
      (jsonb_array_length(v_r2_short) + jsonb_array_length(v_r3_short)) > 0);
END
$$;


