-- TOC entry 3462 (class 1255 OID 4792565)
-- Name: fn_update_reel_comment_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_update_reel_comment_count() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Only updates if post_id matches a reel (social_posts trigger handles the other case)
    UPDATE public.social_reels
      SET comment_count = GREATEST(0, COALESCE(comment_count, 0) + 1),
          updated_at = NOW()
      WHERE id = NEW.post_id;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public.social_reels
      SET comment_count = GREATEST(0, COALESCE(comment_count, 0) - 1),
          updated_at = NOW()
      WHERE id = OLD.post_id;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


