-- Name: FUNCTION fn_update_table_bomb_settings(p_table_id uuid, p_settings jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_update_table_bomb_settings(p_table_id uuid, p_settings jsonb) IS 'Role-gated edit of the bomb-pot settings on a LIVE table. Only the columns the engine re-reads on its throttled refresh. Clears bomb live state on every edit. Audited to table_settings_changes.';


