-- Name: COLUMN wheel_bonus_awards.run_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.wheel_bonus_awards.run_id IS 'The open run this award was won inside, or NULL for a single spin. An award from before the run still blocks the next spin.';


--
-- TOC entry 6279 (class 1255 OID 34988458)
-- Name: fn_wheel_bonus_current_result(public.wheel_bonus_awards); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_bonus_current_result(a public.wheel_bonus_awards) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE r public.crash_rounds;c public.diamond_choice_rounds;
BEGIN
 IF a.status<>'redeemed' THEN RETURN NULL; END IF;
 IF a.game='crash' THEN SELECT * INTO r FROM public.crash_rounds WHERE commit_id=a.commit_id; RETURN public.fn_crash_round_result(r);
 ELSIF a.game IN('crossing','mines') THEN SELECT * INTO c FROM public.diamond_choice_rounds WHERE commit_id=a.commit_id; RETURN public.fn_choice_result(c);
 ELSE RETURN a.result; END IF;
END $$;


ALTER FUNCTION public.fn_wheel_bonus_current_result(a public.wheel_bonus_awards) OWNER TO postgres;

--
-- TOC entry 6094 (class 1255 OID 34988440)
-- Name: fn_wheel_bonus_player_debit(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_bonus_player_debit(p_total integer) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE a public.wheel_bonus_awards;
BEGIN a:=public.fn_wheel_starting_award();
 IF a.id IS NULL THEN RETURN p_total; END IF;
 IF p_total NOT IN(a.base_diamonds,a.base_diamonds+a.entry_diamonds) THEN RAISE EXCEPTION 'Invalid Award Budget'; END IF;
 RETURN p_total-a.base_diamonds;
END $$;


ALTER FUNCTION public.fn_wheel_bonus_player_debit(p_total integer) OWNER TO postgres;

--
-- TOC entry 9094 (class 1255 OID 34988463)
-- Name: fn_wheel_bonus_public_award(public.wheel_bonus_awards, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_bonus_public_award(a public.wheel_bonus_awards, p_double boolean) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
 SELECT jsonb_build_object('id',a.id,'game',a.game,'club_id',a.club_id,'entry_diamonds',a.entry_diamonds,'base_diamonds',a.base_diamonds,'boost_multiplier',a.boost_multiplier,
 'bet_diamonds',a.base_diamonds+CASE WHEN p_double THEN a.entry_diamonds ELSE 0 END,'added_diamonds',CASE WHEN p_double THEN a.entry_diamonds ELSE 0 END,
 'cap_cents',floor(a.cap_cents*a.base_diamonds::numeric/(a.base_diamonds+CASE WHEN p_double THEN a.entry_diamonds ELSE 0 END)),
 'original_cap_cents',a.cap_cents,'reserved_chips',a.reserved_chips,'status',a.status,'commit_id',a.commit_id,'result',public.fn_wheel_bonus_current_result(a),'created_at',a.created_at,'won_order',public.fn_wheel_prize_order(a.spin_id))
$$;


ALTER FUNCTION public.fn_wheel_bonus_public_award(a public.wheel_bonus_awards, p_double boolean) OWNER TO postgres;

--
-- TOC entry 9154 (class 1255 OID 34988460)
-- Name: fn_wheel_bonus_start(uuid, uuid, text, boolean, text, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_bonus_start(p_award_id uuid, p_commit_id uuid, p_client_seed text, p_double boolean, p_mode text DEFAULT NULL::text, p_denom integer DEFAULT NULL::integer, p_table_version integer DEFAULT NULL::integer, p_auto_cashout_cents integer DEFAULT NULL::integer, p_max_steps integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE a public.wheel_bonus_awards;e public.diamond_bonus_entries;wanted jsonb;v_result jsonb;total integer;old_context text;v_refusal jsonb;
BEGIN
 IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Sign In To Play'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text,94615));
 IF p_award_id IS NULL OR p_commit_id IS NULL OR p_double IS NULL OR p_client_seed IS NULL OR length(p_client_seed) NOT BETWEEN 1 AND 64 THEN
  RETURN jsonb_build_object('ok',false,'error','Choose Valid Bonus Settings'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_commit_id::text,94613));
 SELECT * INTO a FROM public.wheel_bonus_awards WHERE id=p_award_id AND user_id=auth.uid() FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','This Bonus Award Does Not Belong To You'); END IF;
 wanted:=jsonb_build_object('award',p_award_id,'commit',p_commit_id,'seed',p_client_seed,'double',p_double,'mode',p_mode,'denom',p_denom,'table',p_table_version,'auto',p_auto_cashout_cents,'steps',p_max_steps);
 IF a.status='redeemed' THEN
  IF a.request IS DISTINCT FROM wanted THEN RETURN jsonb_build_object('ok',false,'error','This Award Was Used With Different Bonus Settings'); END IF;
  RETURN public.fn_wheel_bonus_current_result(a)||jsonb_build_object('replayed',true);
 END IF;
 -- DOUBLE DIAMONDS IS RETIRED (Dan 2026-10-16). A redeemed award that took the
 -- add-on replays above; a new start that asks for it is refused here, before
 -- the award is touched, so nothing is charged.
 IF p_double THEN RETURN jsonb_build_object('ok',false,'error','Double Diamonds Is No Longer Offered. Refresh To Play Your Bonus.'); END IF;
 IF public.fn_wheel_next_unplayed(auth.uid(),a.club_id) IS DISTINCT FROM a.id THEN RETURN jsonb_build_object('ok',false,'error','Play The Earlier Prize In Your Queue First'); END IF;
 IF a.status<>'pending' THEN RETURN jsonb_build_object('ok',false,'error','This Bonus Is Already Starting'); END IF;
 -- The award is untouched, so nothing has been charged on this ticket. A
 -- ticket that cannot open a round is refused here, before the entry whose
 -- foreign key would otherwise turn it into an exception the client cannot read.
 v_refusal:=public.fn_diamond_ticket_refusal(a.user_id,a.game,p_commit_id);
 IF v_refusal IS NOT NULL THEN RETURN v_refusal; END IF;
 IF public.fn_platform_frozen() THEN RETURN jsonb_build_object('ok',false,'error','The Platform Is In Its Maintenance Break'); END IF;
 -- Follow the same game-config, pool, host order as ordinary game admission.
 PERFORM 1 FROM public.diamond_game_configs WHERE host_id=a.host_id AND game=a.game FOR UPDATE;
 PERFORM 1 FROM public.diamond_game_pools WHERE host_id=a.host_id AND game=a.game FOR UPDATE;
 PERFORM * FROM public.fn_diamond_game_cover_lock(a.host_id,a.host_kind);
 total:=a.base_diamonds+CASE WHEN p_double THEN a.entry_diamonds ELSE 0 END;
 old_context:=current_setting('diamond.wheel_award',true);
 BEGIN
  UPDATE public.wheel_bonus_awards SET status='starting',commit_id=p_commit_id,request=wanted WHERE id=a.id;
  PERFORM set_config('diamond.wheel_award',a.id::text,true);
  INSERT INTO public.diamond_bonus_entries(user_id,club_id,host_id,host_kind,game,commit_id,base_diamonds,added_diamonds,request,is_fixture,wheel_award_id)
   VALUES(a.user_id,a.club_id,a.host_id,a.host_kind,a.game,p_commit_id,a.base_diamonds,total-a.base_diamonds,wanted,
    public.fn_ca_is_fixture_account(a.user_id) OR public.fn_ca_is_cert_account(a.user_id),a.id) RETURNING * INTO e;
  -- The host row lock makes this transfer of liability indivisible to all other
  -- admissions and withdrawals. Refusal rolls the release and all money back.
  UPDATE public.diamond_game_pools SET reserved_chips=reserved_chips-a.reserved_chips WHERE host_id=a.host_id AND game=a.game;
  IF a.game='plinko' THEN v_result:=public.fn_plinko_bonus_run(a.club_id,p_commit_id,p_client_seed,total,p_denom,p_table_version);
  ELSIF a.game='crash' THEN v_result:=public.fn_crash_start(a.club_id,p_commit_id,p_client_seed,total,p_auto_cashout_cents);
  ELSE v_result:=public.fn_choice_start(a.club_id,a.game,p_mode,total,p_commit_id,p_client_seed,p_max_steps); END IF;
  IF v_result->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION USING ERRCODE='PDB02',MESSAGE=COALESCE(v_result->>'error','The Bonus Could Not Start'); END IF;
  IF COALESCE(v_result->>'commit_id',v_result#>>'{fairness,commit_id}') IS DISTINCT FROM p_commit_id::text OR v_result->>'club_id' IS DISTINCT FROM a.club_id::text OR (v_result->>'bet_diamonds')::integer IS DISTINCT FROM total THEN
   RAISE EXCEPTION USING ERRCODE='PDB02',MESSAGE='Resume Your Existing Round First'; END IF;
  v_result:=v_result||public.fn_wheel_award_receipt(p_commit_id);
  UPDATE public.diamond_bonus_entries SET result=v_result WHERE id=e.id;
  UPDATE public.wheel_bonus_awards SET status='redeemed',result=v_result WHERE id=a.id;
  PERFORM set_config('diamond.wheel_award',COALESCE(old_context,''),true);
  RETURN v_result;
 EXCEPTION WHEN SQLSTATE 'PDB02' THEN
  PERFORM set_config('diamond.wheel_award',COALESCE(old_context,''),true);
  RETURN jsonb_build_object('ok',false,'error',SQLERRM);
 END;
END $$;


ALTER FUNCTION public.fn_wheel_bonus_start(p_award_id uuid, p_commit_id uuid, p_client_seed text, p_double boolean, p_mode text, p_denom integer, p_table_version integer, p_auto_cashout_cents integer, p_max_steps integer) OWNER TO postgres;

--
-- TOC entry 7737 (class 1255 OID 34988464)
-- Name: fn_wheel_bonus_state(uuid, text, boolean, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_bonus_state(p_club_id uuid, p_game text, p_double boolean DEFAULT false, p_mode text DEFAULT NULL::text, p_award_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a public.wheel_bonus_awards;awards jsonb;v_state jsonb;v_award jsonb;total integer;cap integer;rate integer;prizes numeric[];lim integer:=0;k integer;v_paid integer;v_floor numeric;
BEGIN
 IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Sign In To Play'); END IF;
 IF p_game IS NULL OR p_game NOT IN('plinko','crash','crossing','mines') OR p_double IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Choose A Bonus Game'); END IF;
 SELECT * INTO a FROM public.wheel_bonus_awards WHERE user_id=auth.uid() AND club_id=p_club_id AND game=p_game AND (p_award_id IS NULL OR id=p_award_id)
 ORDER BY (status='pending') DESC,created_at DESC LIMIT 1;
 IF p_award_id IS NOT NULL AND a.id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','This Bonus Award Does Not Match This Game'); END IF;
 SELECT COALESCE(jsonb_agg(public.fn_wheel_bonus_public_award(x,p_double) ORDER BY (x.status='pending') DESC,x.created_at DESC),'[]') INTO awards FROM
  (SELECT * FROM public.wheel_bonus_awards WHERE user_id=auth.uid() AND club_id=p_club_id AND game=p_game ORDER BY (status='pending') DESC,created_at DESC LIMIT 50) x;
 IF p_game IN('crossing','mines') THEN v_state:=public.fn_choice_state(p_club_id,p_game,public.fn_choice_mode(p_game),100);
 ELSE v_state:=public.fn_diamond_game_state(p_club_id,p_game); END IF;
 v_state:=v_state||jsonb_build_object('club_id',p_club_id,'game',p_game);
 IF a.id IS NOT NULL THEN
  v_award:=public.fn_wheel_bonus_public_award(a,p_double);total:=(v_award->>'bet_diamonds')::integer;cap:=(v_award->>'cap_cents')::integer;rate:=public.fn_ca_bridge_rate();
  v_state:=v_state||jsonb_build_object('cap_cents',cap,'bet_diamonds',total,'bets',jsonb_build_array(jsonb_build_object('bet_diamonds',total,'bet_chips',total::numeric/rate,'cap_cents',cap,'playable',cap>=101)));
  v_paid:=a.entry_diamonds+(total-a.base_diamonds);
  v_floor:=public.fn_diamond_bonus_floor(total::numeric/rate,a.boost_multiplier,v_paid,rate);
  -- What this award starts with, from the server, so the client can show the guarantee before Start.
  v_state:=v_state||jsonb_build_object('mode',public.fn_choice_mode(p_game),'plinko_table',public.fn_plinko_table_for_floor(total::numeric/rate,v_floor),
   'minimum_payout_chips',v_floor,'guarantee',CASE WHEN a.boost_multiplier=2 THEN 'super' ELSE 'standard' END,
   'payout_version',CASE WHEN p_game='crossing' THEN 7 WHEN p_game IN('mines','crash') THEN 5 ELSE 4 END,'paid_diamonds',v_paid,'cashout_floor_cents',CASE WHEN p_game='crash' THEN 126 ELSE 111 END,'crash_floor_cents',CASE WHEN p_game='crash' THEN 125 ELSE 110 END,
   'crash_return_ppm',CASE WHEN p_game='crash' THEN public.fn_crash_return_ppm_v5(total::numeric/rate,v_floor) END,
   'plinko_denominations',(SELECT COALESCE(jsonb_agg(DISTINCT d ORDER BY d),'[]'::jsonb) FROM unnest(ARRAY[1,2,4,5,10,20,25,50,100,250,500,total]) d WHERE total%d=0 AND total/d BETWEEN 1 AND 100));

  IF p_game IN('crossing','mines') THEN
   prizes:=public.fn_choice_prizes_v7(p_game,public.fn_choice_mode(p_game),total::numeric/rate,v_floor);
   FOR k IN 1..cardinality(prizes) LOOP EXIT WHEN ceil(prizes[k]*100)/100>total::numeric/rate*cap/100;lim:=k;END LOOP;
   v_state:=v_state||jsonb_build_object('max_steps',lim,'prizes',to_jsonb(COALESCE(prizes[1:lim],'{}'::numeric[])));
  ELSIF p_game='plinko' THEN
   v_state:=jsonb_set(v_state,'{tables}',COALESCE((SELECT jsonb_agg(t||jsonb_build_object('available',(t->>'max_multiplier_cents')::integer<=cap)) FROM jsonb_array_elements(v_state->'tables') t),'[]'::jsonb));
  END IF;
 END IF;
 RETURN jsonb_build_object('ok',true,'contract_version',2,'enabled',public.fn_wheel_v2_enabled(),'award',v_award,'awards',awards,'game_state',v_state);
END $$;


ALTER FUNCTION public.fn_wheel_bonus_state(p_club_id uuid, p_game text, p_double boolean, p_mode text, p_award_id uuid) OWNER TO postgres;

--
-- TOC entry 9429 (class 1255 OID 42364651)
-- Name: fn_wheel_bonus_unfinished(public.wheel_bonus_awards); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_bonus_unfinished(a public.wheel_bonus_awards) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
 SELECT a.status IN('pending','starting') OR (a.status='redeemed' AND
   CASE WHEN a.game='crash' THEN EXISTS(SELECT 1 FROM public.crash_rounds r WHERE r.commit_id=a.commit_id AND r.status='open')
   WHEN a.game IN('crossing','mines') THEN EXISTS(SELECT 1 FROM public.diamond_choice_rounds r WHERE r.commit_id=a.commit_id AND r.status='open')
   ELSE false END);
$$;


ALTER FUNCTION public.fn_wheel_bonus_unfinished(a public.wheel_bonus_awards) OWNER TO postgres;

--
-- TOC entry 7873 (class 1255 OID 23962366)
-- Name: fn_wheel_can_operate(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_can_operate(p_host_id uuid, p_host_kind text, p_user uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_user IS NULL THEN RETURN false; END IF;
  IF COALESCE(auth.role(), '') = 'service_role' THEN RETURN true; END IF;
  -- DIAMOND PHASE 11: another host's games are operated by platform staff.
  -- The estate's wider management test also admits every club owner, every
  -- union owner and every incident recipient, which let any of them configure,
  -- fund and read the games of every other host.
  IF public.fn_is_platform_admin() THEN RETURN true; END IF;
  IF p_host_kind = 'union' THEN
    RETURN public.fn_union_can_manage_wallets(p_host_id, p_user);
  END IF;
  RETURN EXISTS (SELECT 1 FROM public.clubs c WHERE c.id = p_host_id AND c.owner_id = p_user)
      OR EXISTS (SELECT 1 FROM public.club_members cm
                  WHERE cm.club_id = p_host_id AND cm.user_id = p_user
                    AND cm.role IN ('owner', 'co_owner', 'admin')
                    AND COALESCE(cm.status, 'active') IN ('active', 'approved'));
END $$;


ALTER FUNCTION public.fn_wheel_can_operate(p_host_id uuid, p_host_kind text, p_user uuid) OWNER TO postgres;

--
-- TOC entry 2809 (class 1259 OID 53130559)
-- Name: wheel_card_awards; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.wheel_card_awards (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    spin_id uuid NOT NULL,
    run_id uuid,
    user_id uuid NOT NULL,
    club_id uuid NOT NULL,
    host_id uuid NOT NULL,
    host_kind text NOT NULL,
    owner_id uuid NOT NULL,
    is_welcome boolean DEFAULT false NOT NULL,
    risk_diamonds integer NOT NULL,
    half_diamonds integer NOT NULL,
    permutation smallint NOT NULL,
    roll numeric(20,0) NOT NULL,
    nonce bigint NOT NULL,
    server_seed text NOT NULL,
    server_seed_hash text NOT NULL,
    client_seed text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    picked_card smallint,
    paid_diamonds integer,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    picked_at timestamp with time zone,
    CONSTRAINT wheel_card_awards_check CHECK (((half_diamonds = (risk_diamonds / 2)) OR (half_diamonds = ((risk_diamonds + 1) / 2)))),
    CONSTRAINT wheel_card_awards_check1 CHECK ((((status = 'pending'::text) AND (picked_card IS NULL) AND (paid_diamonds IS NULL) AND (picked_at IS NULL)) OR ((status = 'picked'::text) AND (picked_card IS NOT NULL) AND (paid_diamonds IS NOT NULL) AND (picked_at IS NOT NULL)))),
    CONSTRAINT wheel_card_awards_half_diamonds_check CHECK ((half_diamonds >= 0)),
    CONSTRAINT wheel_card_awards_host_kind_check CHECK ((host_kind = ANY (ARRAY['club'::text, 'union'::text]))),
    CONSTRAINT wheel_card_awards_paid_diamonds_check CHECK ((paid_diamonds >= 0)),
    CONSTRAINT wheel_card_awards_permutation_check CHECK (((permutation >= 0) AND (permutation <= 5))),
    CONSTRAINT wheel_card_awards_picked_card_check CHECK (((picked_card >= 1) AND (picked_card <= 3))),
    CONSTRAINT wheel_card_awards_risk_diamonds_check CHECK (((risk_diamonds >= 25) AND (risk_diamonds <= 2500))),
    CONSTRAINT wheel_card_awards_roll_check CHECK ((roll >= (0)::numeric)),
    CONSTRAINT wheel_card_awards_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'picked'::text])))
);


