-- Name: wheel_runs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.wheel_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    club_id uuid NOT NULL,
    host_id uuid NOT NULL,
    spins integer NOT NULL,
    spins_done integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    closed_at timestamp with time zone,
    CONSTRAINT wheel_runs_check CHECK ((spins_done <= spins)),
    CONSTRAINT wheel_runs_check1 CHECK ((((status = 'open'::text) AND (closed_at IS NULL)) OR ((status = 'closed'::text) AND (closed_at IS NOT NULL)))),
    CONSTRAINT wheel_runs_spins_check CHECK ((spins = ANY (ARRAY[5, 10, 25]))),
    CONSTRAINT wheel_runs_spins_done_check CHECK ((spins_done >= 0)),
    CONSTRAINT wheel_runs_status_check CHECK ((status = ANY (ARRAY['open'::text, 'closed'::text])))
);


