--
-- TOC entry 8056 (class 1255 OID 53130626)
-- Name: fn_wheel_run_begin(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_run_begin(p_club_id uuid, p_spins integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_user uuid:=auth.uid(); v_host uuid; v_run public.wheel_runs;
BEGIN
 IF v_user IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Sign In To Spin'); END IF;
 IF p_spins IS NULL OR p_spins NOT IN(5,10,25) THEN
  RETURN jsonb_build_object('ok',false,'error','Choose 5, 10 Or 25 Spins'); END IF;
 SELECT h.host_id INTO v_host FROM public.fn_wheel_host(p_club_id) h;
 IF v_host IS NULL THEN RETURN jsonb_build_object('ok',false,'error','That Club Could Not Be Found'); END IF;
 IF NOT public.fn_wheel_v2_enabled() THEN
  RETURN jsonb_build_object('ok',false,'error','The New Wheel Is Not Open Yet'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v_user::text,94615));
 SELECT * INTO v_run FROM public.wheel_runs WHERE user_id=v_user AND status='open' FOR UPDATE;
 IF v_run.id IS NOT NULL THEN
  IF v_run.club_id IS DISTINCT FROM p_club_id OR v_run.spins IS DISTINCT FROM p_spins THEN
   RETURN jsonb_build_object('ok',false,'error','Finish The Run You Already Started'); END IF;
  RETURN jsonb_build_object('ok',true,'run_id',v_run.id,'spins',v_run.spins,'spins_done',v_run.spins_done);
 END IF;
 INSERT INTO public.wheel_runs(user_id,club_id,host_id,spins) VALUES(v_user,p_club_id,v_host,p_spins)
  RETURNING * INTO v_run;
 RETURN jsonb_build_object('ok',true,'run_id',v_run.id,'spins',v_run.spins,'spins_done',v_run.spins_done);
END $$;


ALTER FUNCTION public.fn_wheel_run_begin(p_club_id uuid, p_spins integer) OWNER TO postgres;

--
-- TOC entry 4696 (class 1255 OID 53130628)
-- Name: fn_wheel_run_end(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_run_end(p_run_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_user uuid:=auth.uid(); v_run public.wheel_runs; v_awards jsonb; v_cards jsonb;
BEGIN
 IF v_user IS NULL THEN RETURN jsonb_build_object('ok',false,'error','Sign In To Spin'); END IF;
 IF p_run_id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','That Run Could Not Be Found'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v_user::text,94615));
 SELECT * INTO v_run FROM public.wheel_runs WHERE id=p_run_id FOR UPDATE;
 IF v_run.id IS NULL OR v_run.user_id IS DISTINCT FROM v_user THEN
  RETURN jsonb_build_object('ok',false,'error','That Run Belongs To Another Player'); END IF;
 IF v_run.status='open' THEN
  UPDATE public.wheel_runs SET status='closed',closed_at=transaction_timestamp() WHERE id=p_run_id
   RETURNING * INTO v_run;
 END IF;
 SELECT COALESCE(jsonb_agg(public.fn_wheel_bonus_public_award(a,false) ORDER BY a.created_at),'[]')
   INTO v_awards FROM public.wheel_bonus_awards a
  WHERE a.user_id=v_user AND a.club_id=v_run.club_id AND public.fn_wheel_bonus_unfinished(a);
 SELECT COALESCE(jsonb_agg(public.fn_wheel_card_public(c) ORDER BY c.created_at),'[]')
   INTO v_cards FROM public.wheel_card_awards c
  WHERE c.user_id=v_user AND c.club_id=v_run.club_id AND c.status='pending';
 RETURN jsonb_build_object('ok',true,'run_id',v_run.id,'spins',v_run.spins,'spins_done',v_run.spins_done,
  'pending_awards',v_awards,'pending_cards',v_cards);
END $$;


ALTER FUNCTION public.fn_wheel_run_end(p_run_id uuid) OWNER TO postgres;

--
-- TOC entry 4728 (class 1255 OID 23962354)
-- Name: fn_wheel_segments_audit(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_segments_audit(p_version integer) RETURNS TABLE(weight_total bigint, spec_rtp numeric, chip_share numeric, diamond_share numeric, house_share numeric, sd_chips numeric, hit_rate numeric, segments integer)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rate integer := public.fn_ca_bridge_rate();
  v_price integer;
  v_intake numeric;
BEGIN
  SELECT v.spin_price_diamonds INTO v_price FROM public.wheel_segment_versions v WHERE v.version = p_version;
  IF v_price IS NULL OR v_rate IS NULL THEN RETURN; END IF;
  v_intake := v_price::numeric / v_rate;   -- the spin in chips
  RETURN QUERY
  WITH s AS (
    SELECT g.weight,
           CASE g.kind WHEN 'chips' THEN g.amount WHEN 'diamonds' THEN g.amount / v_rate ELSE 0 END AS value_chips,
           g.kind
      FROM public.wheel_segments g WHERE g.version = p_version
  ), t AS (
    SELECT SUM(weight)::bigint AS w,
           SUM(value_chips * weight) / NULLIF(SUM(weight), 0) AS ev,
           SUM(CASE WHEN kind = 'chips' THEN value_chips * weight ELSE 0 END) / NULLIF(SUM(weight), 0) AS ev_chips,
           SUM(CASE WHEN kind = 'diamonds' THEN value_chips * weight ELSE 0 END) / NULLIF(SUM(weight), 0) AS ev_dia,
           SUM(CASE WHEN kind <> 'nothing' THEN weight ELSE 0 END)::numeric / NULLIF(SUM(weight), 0) AS hit,
           count(*)::integer AS n
      FROM s
  )
  SELECT t.w,
         round(t.ev / v_intake, 6),
         round(t.ev_chips / v_intake, 6),
         round(t.ev_dia / v_intake, 6),
         round(1 - t.ev / v_intake, 6),
         round(sqrt((SELECT SUM(power(s.value_chips - t.ev, 2) * s.weight) FROM s) / t.w), 6),
         round(t.hit, 6),
         t.n
    FROM t;
END $$;


ALTER FUNCTION public.fn_wheel_segments_audit(p_version integer) OWNER TO postgres;

--
-- TOC entry 6926 (class 1255 OID 23962377)
-- Name: fn_wheel_set_config(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_set_config(p_club_id uuid, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_host uuid; v_kind text;
  cfg public.wheel_configs%ROWTYPE;
  v_version integer; v_vprice integer;
  v_seed_delta integer := 0;
  v_float numeric;
  a record;
BEGIN
  IF v_user IS NULL AND COALESCE(auth.role(), '') <> 'service_role' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In First');
  END IF;
  SELECT h.host_id, h.host_kind INTO v_host, v_kind FROM public.fn_wheel_host(p_club_id) h;
  IF v_host IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Club Could Not Be Found');
  END IF;
  IF NOT public.fn_wheel_can_operate(v_host, v_kind, v_user) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Only The Host Owner Or An Admin May Change The Wheel');
  END IF;

  SELECT * INTO cfg FROM public.wheel_configs WHERE host_id = v_host FOR UPDATE;
  IF cfg.host_id IS NULL THEN
    SELECT max(v.version) INTO v_version FROM public.wheel_segment_versions v WHERE v.activated_at IS NOT NULL;
    IF v_version IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'No Prize Table Has Been Activated Yet');
    END IF;
    INSERT INTO public.wheel_configs (host_id, host_kind, segment_version, updated_by)
    VALUES (v_host, v_kind, v_version, v_user) RETURNING * INTO cfg;
    INSERT INTO public.wheel_pools (host_id) VALUES (v_host) ON CONFLICT (host_id) DO NOTHING;
  END IF;

  IF p_patch ? 'segment_version' THEN
    v_version := (p_patch->>'segment_version')::integer;
    IF NOT EXISTS (SELECT 1 FROM public.wheel_segment_versions v WHERE v.version = v_version AND v.activated_at IS NOT NULL) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'That Prize Table Is Not Activated');
    END IF;
    cfg.segment_version := v_version;
  END IF;
  IF p_patch ? 'spin_price_diamonds' THEN cfg.spin_price_diamonds := (p_patch->>'spin_price_diamonds')::integer; END IF;
  IF p_patch ? 'exposure_allowance_chips' THEN cfg.exposure_allowance_chips := round((p_patch->>'exposure_allowance_chips')::numeric, 2); END IF;
  IF p_patch ? 'diamond_seed' THEN
    v_seed_delta := (p_patch->>'diamond_seed')::integer - cfg.diamond_seed;
    cfg.diamond_seed := (p_patch->>'diamond_seed')::integer;
  END IF;
  IF p_patch ? 'purchased_only' THEN cfg.purchased_only := (p_patch->>'purchased_only')::boolean; END IF;
  IF p_patch ? 'allow_fixture_accounts' THEN cfg.allow_fixture_accounts := (p_patch->>'allow_fixture_accounts')::boolean; END IF;
  IF p_patch ? 'max_spins_per_player_per_day' THEN cfg.max_spins_per_player_per_day := (p_patch->>'max_spins_per_player_per_day')::integer; END IF;
  IF p_patch ? 'min_seconds_between_spins' THEN cfg.min_seconds_between_spins := (p_patch->>'min_seconds_between_spins')::integer; END IF;
  IF p_patch ? 'enabled' THEN cfg.enabled := (p_patch->>'enabled')::boolean; END IF;

  IF cfg.diamond_seed < 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'The Diamond Seed Cannot Be Negative');
  END IF;

  -- The spin price must be a whole multiple of the table's price so every prize
  -- scales by an integer and stays on whole cents; the table must still audit.
  SELECT v.spin_price_diamonds INTO v_vprice FROM public.wheel_segment_versions v WHERE v.version = cfg.segment_version;
  IF cfg.spin_price_diamonds % v_vprice <> 0 THEN
    RETURN jsonb_build_object('ok', false,
      'error', format('The Spin Price Must Be A Multiple Of %s Diamonds For This Prize Table', v_vprice));
  END IF;
  SELECT x.* INTO a FROM public.fn_wheel_segments_audit(cfg.segment_version) x;
  IF cfg.enabled AND (a.weight_total IS DISTINCT FROM 100000 OR a.spec_rtp IS DISTINCT FROM 0.800000) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'The Prize Table Fails Its Audit And Cannot Be Enabled');
  END IF;

  -- A seed change moves the float by the delta. It never drives the float
  -- below zero: diamonds already paid against the old seed are paid.
  IF v_seed_delta <> 0 THEN
    SELECT p.diamond_float INTO v_float FROM public.wheel_pools p WHERE p.host_id = v_host FOR UPDATE;
    IF v_float + v_seed_delta < 0 THEN
      RETURN jsonb_build_object('ok', false,
        'error', format('The Seed Can Be Lowered By At Most %s Diamonds Right Now', floor(v_float)));
    END IF;
    UPDATE public.wheel_pools
       SET diamond_float = diamond_float + v_seed_delta,
           diamond_seed = diamond_seed + v_seed_delta,
           updated_at = now()
     WHERE host_id = v_host;
  END IF;

  UPDATE public.wheel_configs
     SET enabled = cfg.enabled, spin_price_diamonds = cfg.spin_price_diamonds, segment_version = cfg.segment_version,
         exposure_allowance_chips = cfg.exposure_allowance_chips, diamond_seed = cfg.diamond_seed,
         purchased_only = cfg.purchased_only,
         allow_fixture_accounts = cfg.allow_fixture_accounts,
         max_spins_per_player_per_day = cfg.max_spins_per_player_per_day,
         min_seconds_between_spins = cfg.min_seconds_between_spins,
         updated_at = now(), updated_by = v_user
   WHERE host_id = v_host
   RETURNING * INTO cfg;
  RETURN jsonb_build_object('ok', true, 'config', to_jsonb(cfg), 'audit', to_jsonb(a));
END $$;


ALTER FUNCTION public.fn_wheel_set_config(p_club_id uuid, p_patch jsonb) OWNER TO postgres;

--
-- TOC entry 7630 (class 1255 OID 27167322)
-- Name: fn_wheel_set_welcome_spin(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_set_welcome_spin(p_club_id uuid, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_host uuid; v_kind text;
  v_enabled boolean; v_budget numeric; v_days integer;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign In First');
  END IF;
  SELECT h.host_id, h.host_kind INTO v_host, v_kind FROM public.fn_wheel_host(p_club_id) h;
  IF v_host IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'That Club Could Not Be Found');
  END IF;
  IF NOT public.fn_wheel_can_operate(v_host, v_kind, v_user) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Only The Host''s Owners And Admins Run The Wheel');
  END IF;
  v_enabled := CASE WHEN p_patch ? 'welcome_spin_enabled' THEN (p_patch->>'welcome_spin_enabled')::boolean END;
  v_days    := CASE WHEN p_patch ? 'welcome_budget_period_days' THEN (p_patch->>'welcome_budget_period_days')::integer END;
  IF v_days IS NOT NULL AND v_days < 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'The Welcome Budget Period Cannot Be Negative');
  END IF;
  v_budget  := CASE WHEN p_patch ? 'welcome_budget_chips' THEN (p_patch->>'welcome_budget_chips')::numeric END;
  IF v_budget IS NOT NULL AND v_budget < 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'The Welcome Budget Must Be Zero Or More Chips');
  END IF;
  UPDATE public.wheel_configs
     SET welcome_spin_enabled = COALESCE(v_enabled, welcome_spin_enabled),
         welcome_budget_period_days = COALESCE(v_days, welcome_budget_period_days),
         welcome_budget_chips = COALESCE(v_budget, welcome_budget_chips),
         updated_by = v_user, updated_at = now()
   WHERE host_id = v_host;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'The Wheel Is Not Configured Here');
  END IF;
  RETURN jsonb_build_object('ok', true);
END $$;


ALTER FUNCTION public.fn_wheel_set_welcome_spin(p_club_id uuid, p_patch jsonb) OWNER TO postgres;

