CREATE FUNCTION public.fn_wheel_v3_segments(p_entry integer, p_rate integer, p_secondary boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
 SELECT jsonb_agg(jsonb_build_object('ord',ord,'label',label,'kind',kind,'game',game,'multiplier',multiplier,
