--

CREATE FUNCTION public.fn_wheel_v3_upgrade_model() RETURNS TABLE(ord smallint, label text, kind text, game text, multiplier numeric, weight integer)
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
