--
-- TOC entry 6844 (class 1255 OID 53130542)
-- Name: fn_wheel_v4_upgrade_weights(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_v4_upgrade_weights(p_prev_game text DEFAULT NULL::text) RETURNS integer[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE w integer[]; hit integer; share integer; rest integer; others integer[]; i integer;
BEGIN
 SELECT array_agg(weight ORDER BY ord) INTO w FROM public.fn_wheel_v3_upgrade_model();
 IF p_prev_game IS NULL THEN RETURN w; END IF;
 SELECT u.ord INTO hit FROM public.fn_wheel_v3_upgrade_model() u WHERE u.game=p_prev_game;
 IF hit IS NULL THEN RAISE EXCEPTION 'The Previous Game Is Invalid'; END IF;
 SELECT array_agg(u.ord ORDER BY u.ord) INTO others FROM public.fn_wheel_v3_upgrade_model() u WHERE u.kind='bonus' AND u.ord<>hit;
 share:=w[hit]/3; rest:=w[hit]%3; w[hit]:=0;
 FOR i IN 1..array_length(others,1) LOOP
  w[others[i]]:=w[others[i]]+share+CASE WHEN i<=rest THEN 1 ELSE 0 END;
 END LOOP;
 RETURN w;
END $$;


ALTER FUNCTION public.fn_wheel_v4_upgrade_weights(p_prev_game text) OWNER TO postgres;

--
-- TOC entry 8066 (class 1255 OID 53130539)
-- Name: fn_wheel_v4_weights(smallint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_v4_weights(p_prev_ord smallint, p_prev_super_game text DEFAULT NULL::text) RETURNS integer[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE w integer[]; hit integer; share integer; rest integer; others integer[]; i integer;
BEGIN
 IF p_prev_ord IS NULL THEN
  SELECT array_agg(weight ORDER BY ord) INTO w FROM public.fn_wheel_v4_model();
  RETURN w;
 END IF;
 IF p_prev_ord NOT BETWEEN 1 AND 12 THEN RAISE EXCEPTION 'The Previous Wheel Outcome Is Invalid'; END IF;
 SELECT array_agg(f.weight ORDER BY f.ord) INTO w FROM public.fn_wheel_v4_follow_model() f WHERE f.prev_ord=p_prev_ord;
 IF p_prev_super_game IS NULL THEN RETURN w; END IF;
 SELECT m.ord INTO hit FROM public.fn_wheel_v4_model() m WHERE m.game=p_prev_super_game;
 IF hit IS NULL THEN RAISE EXCEPTION 'The Previous Super Game Is Invalid'; END IF;
 SELECT array_agg(m.ord ORDER BY m.ord) INTO others FROM public.fn_wheel_v4_model() m WHERE m.kind='bonus' AND m.ord<>hit;
 share:=w[hit]/3; rest:=w[hit]%3; w[hit]:=0;
 FOR i IN 1..array_length(others,1) LOOP
  w[others[i]]:=w[others[i]]+share+CASE WHEN i<=rest THEN 1 ELSE 0 END;
 END LOOP;
 RETURN w;
END $$;


ALTER FUNCTION public.fn_wheel_v4_weights(p_prev_ord smallint, p_prev_super_game text) OWNER TO postgres;

--
-- TOC entry 6871 (class 1255 OID 27187655)
-- Name: fn_wheel_welcome_room(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_welcome_room(p_host uuid, OUT o_spent numeric, OUT o_top numeric, OUT o_open boolean) RETURNS record
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  cfg public.wheel_configs%ROWTYPE;
  v_rate integer := public.fn_ca_bridge_rate();
  v_mult integer := 1;
BEGIN
  o_spent := 0; o_top := 0; o_open := false;
  SELECT * INTO cfg FROM public.wheel_configs WHERE host_id = p_host;
  IF cfg.host_id IS NULL THEN RETURN; END IF;

  -- The VIP multiplier the table is priced at, the same way the core reads it.
  SELECT COALESCE(100 / v.spin_price_diamonds, 1) INTO v_mult
    FROM public.wheel_segment_versions v WHERE v.version = cfg.segment_version;
  v_mult := COALESCE(v_mult, 1);

  -- The biggest prize this table can pay, in chips, whichever kind it is.
  SELECT COALESCE(max(CASE WHEN g.kind = 'chips'    THEN g.amount::numeric * v_mult
                           WHEN g.kind = 'diamonds' THEN round((g.amount * v_mult)::numeric / v_rate, 4)
                           ELSE 0 END), 0)
    INTO o_top
    FROM public.wheel_segments g WHERE g.version = cfg.segment_version;

  o_spent := public.fn_wheel_welcome_spent(p_host, cfg.welcome_budget_period_days);
  -- A budget of zero is unfunded, not open with nothing in it.
  o_open := COALESCE(cfg.welcome_budget_chips, 0) > 0
        AND o_spent + o_top <= cfg.welcome_budget_chips;
END $$;


ALTER FUNCTION public.fn_wheel_welcome_room(p_host uuid, OUT o_spent numeric, OUT o_top numeric, OUT o_open boolean) OWNER TO postgres;

--
-- TOC entry 3459 (class 1255 OID 27167317)
-- Name: fn_wheel_welcome_spent(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_wheel_welcome_spent(p_host uuid, p_days integer) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(sum(s.prize_value_chips), 0)
    FROM public.wheel_spins s
   WHERE s.host_id = p_host
     AND s.is_welcome
     AND (COALESCE(p_days, 0) <= 0 OR s.created_at >= now() - make_interval(days => p_days));
$$;


