--

CREATE FUNCTION public.geeves_increment_missed_count(p_hash text, p_grok_answer text DEFAULT ''::text, p_page text DEFAULT ''::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  UPDATE geeves_missed_questions
     SET asked_count = asked_count + 1,
         grok_answer = COALESCE(NULLIF(p_grok_answer, ''), grok_answer),
         page        = COALESCE(NULLIF(p_page, ''), page),
         last_asked  = now()
   WHERE question_hash = p_hash;
EXCEPTION WHEN undefined_table THEN NULL;
END;
$$;


