--
-- TOC entry 4449 (class 1255 OID 2361576)
-- Name: geeves_upsert_missed_question(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.geeves_upsert_missed_question(p_question text, p_hash text, p_page text DEFAULT ''::text, p_grok_answer text DEFAULT ''::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  INSERT INTO geeves_missed_questions
    (question, question_hash, page, grok_answer, asked_count, first_asked, last_asked, created_at)
  VALUES (p_question, p_hash, p_page, p_grok_answer, 1, now(), now(), now())
  ON CONFLICT (question_hash) DO UPDATE
    SET asked_count = geeves_missed_questions.asked_count + 1,
        grok_answer = COALESCE(NULLIF(EXCLUDED.grok_answer, ''),
                               geeves_missed_questions.grok_answer),
        last_asked  = now();
EXCEPTION WHEN undefined_table THEN NULL;
END;
$$;


