CREATE FUNCTION public.generate_agent_code() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.agent_code IS NULL THEN
    NEW.agent_code := upper(substring(md5(random()::text) from 1 for 6));
  END IF;
  RETURN NEW;
END;
$$;


