--
-- TOC entry 6540 (class 1255 OID 1687675)
-- Name: generate_club_code(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_club_code() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  chars text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  result text := '';
  i integer;
BEGIN
  LOOP
    result := '';
    FOR i IN 1..6 LOOP
      result := result || substr(chars, floor(random() * length(chars) + 1)::int, 1);
    END LOOP;
    IF NOT EXISTS (SELECT 1 FROM clubs WHERE code = result) THEN
      RETURN result;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION public.generate_club_code() OWNER TO postgres;

--
-- TOC entry 3671 (class 1255 OID 124952)
-- Name: generate_club_codes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_club_codes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE new_club_code TEXT; code_exists BOOLEAN;
BEGIN
  IF NEW.invite_code IS NULL THEN
    NEW.invite_code := upper(substr(md5(random()::text), 1, 8));
  END IF;
  IF NEW.club_code IS NULL THEN
    LOOP
      new_club_code := upper(substr(translate(encode(gen_random_bytes(4), 'base64'), '+/=0O1IL', ''), 1, 6));
      SELECT EXISTS(SELECT 1 FROM commander_home_groups WHERE club_code = new_club_code) INTO code_exists;
      EXIT WHEN NOT code_exists;
    END LOOP;
    NEW.club_code := new_club_code;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.generate_club_codes() OWNER TO postgres;

--
-- TOC entry 4787 (class 1255 OID 4632349)
-- Name: generate_home_group_ical(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_home_group_ical(p_group_id uuid, p_days_ahead integer DEFAULT 90) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_ics text := ''; v_game RECORD; v_group RECORD;
    v_dtstamp text := to_char(NOW() AT TIME ZONE 'UTC', 'YYYYMMDD"T"HH24MISS"Z"');
BEGIN
    SELECT * INTO v_group FROM commander_home_groups WHERE id = p_group_id;
    IF NOT FOUND THEN RETURN ''; END IF;
    IF v_group.is_private 
       AND (auth.uid() IS NULL OR (auth.uid() <> v_group.owner_id
            AND NOT EXISTS (SELECT 1 FROM commander_home_members WHERE group_id = p_group_id AND user_id = auth.uid() AND status = 'approved')))
    THEN RETURN ''; END IF;

    v_ics := 'BEGIN:VCALENDAR' || chr(13)||chr(10) ||
             'VERSION:2.0' || chr(13)||chr(10) ||
             'PRODID:-//Smarter.Poker//Home Games//EN' || chr(13)||chr(10) ||
             'CALSCALE:GREGORIAN' || chr(13)||chr(10) ||
             'X-WR-CALNAME:' || replace(v_group.name, ',', '\,') || chr(13)||chr(10);

    FOR v_game IN SELECT * FROM commander_home_games 
         WHERE group_id = p_group_id AND status IN ('scheduled','confirmed','in_progress')
           AND scheduled_date BETWEEN CURRENT_DATE AND CURRENT_DATE + (p_days_ahead || ' days')::interval
         ORDER BY scheduled_date
    LOOP
        v_ics := v_ics 
            || 'BEGIN:VEVENT' || chr(13)||chr(10)
            || 'UID:' || v_game.id::text || '@smarter.poker' || chr(13)||chr(10)
            || 'DTSTAMP:' || v_dtstamp || chr(13)||chr(10)
            || 'DTSTART:' || to_char(v_game.scheduled_date + COALESCE(v_game.start_time, TIME '19:00'), 'YYYYMMDD"T"HH24MISS') || chr(13)||chr(10)
            || 'DTEND:' || to_char(v_game.scheduled_date + COALESCE(v_game.end_time, TIME '23:00') + CASE WHEN v_game.end_time < TIME '06:00' THEN INTERVAL '1 day' ELSE INTERVAL '0' END, 'YYYYMMDD"T"HH24MISS') || chr(13)||chr(10)
            || 'SUMMARY:' || replace(COALESCE(v_game.title, v_group.name), ',', '\,') || chr(13)||chr(10)
            || 'DESCRIPTION:' || replace(COALESCE(v_game.description, 'Home poker game'), ',', '\,') || ' Stakes: ' || COALESCE(v_game.stakes, 'TBD') || chr(13)||chr(10)
            || 'LOCATION:' || replace(COALESCE(v_game.address, v_group.city || ', ' || v_group.state), ',', '\,') || chr(13)||chr(10)
            || 'STATUS:' || CASE v_game.status WHEN 'confirmed' THEN 'CONFIRMED' WHEN 'cancelled' THEN 'CANCELLED' ELSE 'TENTATIVE' END || chr(13)||chr(10)
            || 'END:VEVENT' || chr(13)||chr(10);
    END LOOP;
    v_ics := v_ics || 'END:VCALENDAR' || chr(13)||chr(10);
    RETURN v_ics;
END; $$;


ALTER FUNCTION public.generate_home_group_ical(p_group_id uuid, p_days_ahead integer) OWNER TO postgres;

--
-- TOC entry 4144 (class 1255 OID 2363994)
-- Name: generate_period_commissions(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_period_commissions(p_period_id uuid) RETURNS TABLE(agent_id uuid, period_id uuid, gross_rake numeric, commission_earned numeric, paid_to_downlines numeric, net_payout numeric, status text)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_period record;
BEGIN
  SELECT * INTO v_period FROM public.rakeback_periods WHERE id = p_period_id;
  IF v_period.id IS NULL THEN RETURN; END IF;

  RETURN QUERY
    SELECT
      a.id                                       AS agent_id,
      p_period_id                                AS period_id,
      COALESCE(a.weekly_rake_generated, 0)       AS gross_rake,
      COALESCE(SUM(ac.amount), 0)::numeric        AS commission_earned,
      0::numeric                                  AS paid_to_downlines,
      COALESCE(SUM(ac.amount), 0)::numeric        AS net_payout,
      'pending'::text                             AS status
      FROM public.agents a
      LEFT JOIN public.agent_commissions ac
        ON ac.user_id = a.user_id
       AND ac.created_at::date BETWEEN v_period.period_start AND v_period.period_end
     WHERE a.club_id = v_period.club_id
       AND a.status = 'active'
     GROUP BY a.id, a.weekly_rake_generated;
END $$;


ALTER FUNCTION public.generate_period_commissions(p_period_id uuid) OWNER TO postgres;

