CREATE FUNCTION public.get_club_agents(p_club_id uuid) RETURNS TABLE(id uuid, user_id uuid, club_id uuid, role text, status text, commission_rate numeric, player_rakeback_rate numeric, credit_limit numeric, total_players integer, lifetime_earnings numeric, display_name text, avatar_url text, joined_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        a.id,
        a.user_id,
        a.club_id,
        a.role,
        a.status,
        a.commission_rate,
        a.player_rakeback_rate,
        a.credit_limit,
        a.total_players,
        a.lifetime_earnings,
        COALESCE(p.display_name, p.username, 'Unknown') as display_name,
        p.avatar_url,
        a.created_at as joined_at
    FROM agents a
    LEFT JOIN profiles p ON a.user_id = p.id
    WHERE a.club_id = p_club_id
    ORDER BY a.created_at DESC;
END;
$$;


