-- TOC entry 6651 (class 1255 OID 1688190)
-- Name: get_club_financial_summary(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_club_financial_summary(p_club_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_club RECORD; v_total_member_chips NUMERIC; v_total_agent_balances NUMERIC;
  v_pending_cashouts NUMERIC; v_agent_count INTEGER; v_player_count INTEGER;
BEGIN
  SELECT * INTO v_club FROM clubs WHERE id = p_club_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Club not found'); END IF;
  SELECT COALESCE(SUM(chip_balance), 0) INTO v_total_member_chips FROM club_members WHERE club_id = p_club_id;
  SELECT COALESCE(SUM(business_balance), 0) INTO v_total_agent_balances FROM agents WHERE club_id = p_club_id AND status = 'active';
  SELECT COALESCE(SUM(amount), 0) INTO v_pending_cashouts FROM cashout_requests WHERE club_id = p_club_id AND status IN ('pending', 'approved');
  SELECT COUNT(*) INTO v_agent_count FROM agents WHERE club_id = p_club_id AND status = 'active';
  SELECT COUNT(*) INTO v_player_count FROM club_members WHERE club_id = p_club_id AND role = 'player';
  RETURN jsonb_build_object('success', true, 'treasury', COALESCE(v_club.chip_treasury, 0), 'promo_balance', COALESCE(v_club.promo_balance, 0), 'total_rake', COALESCE(v_club.total_rake, 0), 'total_member_chips', v_total_member_chips, 'total_agent_balances', v_total_agent_balances, 'pending_cashouts', v_pending_cashouts, 'agent_count', v_agent_count, 'player_count', v_player_count, 'chips_in_circulation', v_total_member_chips + v_pending_cashouts);
END;
$$;


