COMMENT ON FUNCTION public.get_club_home(p_club_key text) IS 'Club lobby payload in one round trip (was six). SECURITY INVOKER: RLS applies to every read, so it returns exactly what the caller could fetch itself. 2026-09-02: the member count goes through fn_club_member_count (definer, integer only) because under club_members RLS it cost 2 s per call and 26% of all database time; tables are ordered occupancy-first so the 200-row cap never hides a live game.';


--
-- TOC entry 8701 (class 1255 OID 19004847)
-- Name: get_club_players_playing(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_club_players_playing(p_club_key text) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_club           public.clubs%ROWTYPE;
  v_union_id       uuid;
  v_union_club_ids uuid[];
  v_playing        integer;
BEGIN
  IF p_club_key ~ '^[0-9a-fA-F]{8}-' THEN
    SELECT id, union_id, asset INTO v_club.id, v_club.union_id, v_club.asset FROM public.clubs WHERE id = p_club_key::uuid LIMIT 1;
  ELSIF p_club_key ~ '^[0-9]+$' THEN
    SELECT id, union_id, asset INTO v_club.id, v_club.union_id, v_club.asset FROM public.clubs WHERE club_id = p_club_key::integer LIMIT 1;
  ELSE
    SELECT id, union_id, asset INTO v_club.id, v_club.union_id, v_club.asset FROM public.clubs WHERE slug = p_club_key LIMIT 1;
  END IF;
  IF v_club.id IS NULL THEN
    RETURN NULL;
  END IF;

  -- THE DIAMOND ARENA COUNTS PLAYERS, NOT FIXTURES (migration
  -- 20260929233000): "Fixture accounts are not players; horses are"
  -- (docs/DIAMOND-RULINGS.md). A diamonds club answers from the arena's own
  -- seated rule. A chip club never enters this branch.
  IF v_club.asset = 'diamonds' THEN
    RETURN public.fn_diamond_arena_players_playing(v_club.id);
  END IF;

  SELECT uc.union_id INTO v_union_id
  FROM public.union_clubs uc WHERE uc.club_id = v_club.id LIMIT 1;
  IF v_union_id IS NULL THEN
    v_union_id := v_club.union_id;
  END IF;
  IF v_union_id IS NOT NULL THEN
    SELECT array_agg(uc.club_id) INTO v_union_club_ids
    FROM public.union_clubs uc WHERE uc.union_id = v_union_id;
  END IF;
  v_union_club_ids := COALESCE(v_union_club_ids, ARRAY[]::uuid[]) || v_club.id;

  -- Identical to the players_playing term of get_club_home: distinct users in
  -- a live seat at a table this lobby can see. SECURITY INVOKER, RLS applies.
  SELECT count(DISTINCT ts.user_id)::int INTO v_playing
  FROM public.table_seats ts
  JOIN public.tables tb ON tb.id = ts.table_id
  WHERE ts.left_at IS NULL
    AND tb.status IN ('waiting', 'running')
    AND public.fn_club_home_in_scope(
          tb.club_id, tb.is_private, tb.union_id,
          v_union_id, v_club.id, v_union_club_ids);
  RETURN COALESCE(v_playing, 0);
END;
$_$;


