BEGIN
    SELECT json_build_object('active_tables', (SELECT COUNT(*) FROM tables WHERE club_id = p_club_id AND status = 'running'), 'active_players', (SELECT COUNT(*) FROM table_seats ts JOIN tables t ON ts.table_id = t.id WHERE t.club_id = p_club_id AND ts.left_at IS NULL)) INTO v_result;
