--
-- TOC entry 8689 (class 1255 OID 5803229)
-- Name: get_next_training_question(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_next_training_question(p_user_id uuid, p_level_id integer DEFAULT 1) RETURNS TABLE(id uuid, scenario_text text, hero_hand text, hero_position text, board_cards jsonb, street text, correct_answer text, options jsonb, gto_action text, gto_explanation text, action_breakdown jsonb, gto_frequencies jsonb, difficulty integer, game_type text, stack_depth integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_level integer;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN;
  END IF;
  v_level := GREATEST(1, COALESCE(p_level_id, 1));

  RETURN QUERY
  SELECT tq.id,
         tq.scenario_text,
         tq.hero_hand,
         tq.hero_position,
         tq.board_cards,
         tq.street,
         tq.correct_answer,
         tq.options,
         tq.gto_action,
         tq.gto_explanation,
         tq.action_breakdown,
         tq.gto_frequencies,
         tq.difficulty,
         tq.game_type,
         tq.stack_depth
  FROM public.training_questions tq
  -- Exclude questions the user has already answered CORRECTLY at this level.
  -- (Users repeating wrong answers benefits from re-seeing the same question.)
  -- training_answers.question_id is TEXT but training_questions.id is UUID; cast.
  WHERE tq.difficulty = v_level
    AND NOT EXISTS (
      SELECT 1 FROM public.training_answers ta
      WHERE ta.user_id = p_user_id
        AND ta.is_correct = true
        AND ta.level = v_level
        AND ta.question_id = tq.id::text
    )
  ORDER BY random()
  LIMIT 1;

  -- Fallback: if every question at this level has been answered
  -- correctly, return a random one anyway (loop the user through).
  IF NOT FOUND THEN
    RETURN QUERY
    SELECT tq.id, tq.scenario_text, tq.hero_hand, tq.hero_position,
           tq.board_cards, tq.street, tq.correct_answer, tq.options,
           tq.gto_action, tq.gto_explanation, tq.action_breakdown,
           tq.gto_frequencies, tq.difficulty, tq.game_type, tq.stack_depth
    FROM public.training_questions tq
    WHERE tq.difficulty = v_level
    ORDER BY random()
    LIMIT 1;
  END IF;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'get_next_training_question failed for user % level %: % %', p_user_id, p_level_id, SQLERRM, SQLSTATE;
  RETURN;
END;
$$;


ALTER FUNCTION public.get_next_training_question(p_user_id uuid, p_level_id integer) OWNER TO postgres;

