CREATE FUNCTION public.get_table_sessions(p_table_id uuid) RETURNS TABLE(player_id uuid, seat_index smallint, ip_address inet, latitude double precision, longitude double precision, fingerprint text, seated_at timestamp with time zone)
    LANGUAGE sql STABLE
