-- Name: get_unseen_questions(uuid, text[], integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unseen_questions(p_user uuid, p_categories text[] DEFAULT NULL::text[], p_count integer DEFAULT 20) RETURNS SETOF public.trivia_questions
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT q.*
    FROM public.trivia_questions q
   WHERE (p_categories IS NULL OR array_length(p_categories, 1) IS NULL OR q.category = ANY(p_categories))
     AND NOT EXISTS (
           SELECT 1
             FROM public.user_seen_questions s
            WHERE s.user_id = p_user
              AND s.question_id = q.id::text
         )
   ORDER BY random()
   LIMIT GREATEST(COALESCE(p_count, 20), 0);
$$;


