--
-- TOC entry 7194 (class 1255 OID 4632742)
-- Name: get_user_home_games_calendar(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_home_games_calendar(p_caller_user_id uuid, p_days_ahead integer DEFAULT 60) RETURNS TABLE(game_id uuid, group_id uuid, group_name text, group_slug text, title text, scheduled_date date, start_time time without time zone, end_time time without time zone, stakes text, game_type text, format text, address text, address_visible boolean, notes_for_attendees text, my_response text, my_checked_in_at timestamp with time zone, rsvp_yes integer, rsvp_maybe integer, max_players integer, waitlist_count integer, status text, is_host boolean, cover_photo_url text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;

    RETURN QUERY
    SELECT 
        g.id, g.group_id, grp.name, sp.slug,
        g.title, g.scheduled_date, g.start_time, g.end_time,
        g.stakes, g.game_type, g.format,
        -- Address visibility: show address only if yes-RSVP + member
        CASE 
          WHEN grp.owner_id=p_caller_user_id OR g.host_id=p_caller_user_id THEN g.address
          WHEN g.address_visible_to = 'all' THEN g.address
          WHEN g.address_visible_to = 'approved' 
               AND EXISTS (SELECT 1 FROM commander_home_members m 
                            WHERE m.group_id = g.group_id AND m.user_id = p_caller_user_id 
                              AND m.status='approved') THEN g.address
          WHEN g.address_visible_to = 'rsvp' 
               AND COALESCE(r.response, '') = 'yes' AND EXISTS (SELECT 1 FROM commander_home_members am WHERE am.group_id=g.group_id AND am.user_id=p_caller_user_id AND am.status='approved') THEN g.address
          ELSE NULL 
        END AS address,
        (CASE WHEN grp.owner_id=p_caller_user_id OR g.host_id=p_caller_user_id OR g.address_visible_to = 'all' OR 
                   (g.address_visible_to = 'approved' AND EXISTS (SELECT 1 FROM commander_home_members m WHERE m.group_id = g.group_id AND m.user_id = p_caller_user_id AND m.status='approved')) OR
                   (g.address_visible_to = 'rsvp' AND COALESCE(r.response,'') = 'yes' AND EXISTS (SELECT 1 FROM commander_home_members am WHERE am.group_id=g.group_id AND am.user_id=p_caller_user_id AND am.status='approved')) THEN true ELSE false END) AS address_visible,
        -- notes_for_attendees only if yes-RSVP
        CASE WHEN COALESCE(r.response, '') = 'yes' AND (grp.owner_id=p_caller_user_id OR g.host_id=p_caller_user_id OR EXISTS (SELECT 1 FROM commander_home_members am WHERE am.group_id=g.group_id AND am.user_id=p_caller_user_id AND am.status='approved')) THEN g.notes_for_attendees ELSE NULL END,
        r.response, r.checked_in_at,
        g.rsvp_yes, g.rsvp_maybe, g.max_players, g.waitlist_count,
        g.status,
        g.host_id = p_caller_user_id OR grp.owner_id = p_caller_user_id AS is_host,
        g.cover_photo_url
      FROM commander_home_games g
      JOIN commander_home_groups grp ON grp.id = g.group_id
      LEFT JOIN social_pages sp ON sp.linked_entity_type='home_group' AND sp.linked_entity_id=grp.id::text
      LEFT JOIN commander_home_rsvps r ON r.game_id = g.id AND r.user_id = p_caller_user_id
     WHERE grp.is_active IS TRUE
       AND (grp.owner_id=p_caller_user_id OR NOT EXISTS (SELECT 1 FROM commander_home_members denied WHERE denied.group_id=g.group_id AND denied.user_id=p_caller_user_id AND denied.status IN ('banned','removed')))
       AND g.scheduled_date BETWEEN CURRENT_DATE AND CURRENT_DATE + (p_days_ahead || ' days')::interval
       AND g.status IN ('scheduled','confirmed','in_progress')
       AND (
         -- Member
         EXISTS (SELECT 1 FROM commander_home_members m 
                  WHERE m.group_id = g.group_id AND m.user_id = p_caller_user_id 
                    AND m.status='approved')
         OR grp.owner_id = p_caller_user_id
         OR g.host_id = p_caller_user_id
         -- Or public group with any RSVP
         OR (NOT grp.is_private AND r.user_id IS NOT NULL)
       )
     ORDER BY g.scheduled_date, g.start_time NULLS LAST;
END;
$$;


ALTER FUNCTION public.get_user_home_games_calendar(p_caller_user_id uuid, p_days_ahead integer) OWNER TO postgres;

