--
-- TOC entry 6605 (class 1255 OID 82475056)
-- Name: grant_lifetime_vip_monthly_diamonds(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.grant_lifetime_vip_monthly_diamonds(p_user_id uuid, p_grant_month date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_profile public.profiles%ROWTYPE;
  v_lot public.lifetime_vip_diamond_lots%ROWTYPE;
  v_now timestamptz := now();
  v_current_month date := date_trunc(
    'month', v_now AT TIME ZONE 'America/Chicago'
  )::date;
  v_op_id text;
  v_mint jsonb;
  v_tx uuid;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    RETURN jsonb_build_object('success', false, 'error', 'service_role_required');
  END IF;
  IF p_user_id IS NULL
     OR p_grant_month IS NULL
     OR p_grant_month <> date_trunc('month', p_grant_month::timestamp)::date
     OR p_grant_month <> v_current_month THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_grant_month');
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('lifetime-vip-monthly:' || p_user_id::text || ':' || p_grant_month::text, 0)
  );
  SELECT * INTO v_lot
    FROM public.lifetime_vip_diamond_lots
   WHERE user_id = p_user_id
     AND grant_month = p_grant_month;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'duplicate', true,
      'lot_id', v_lot.id,
      'amount', v_lot.granted_amount,
      'remaining', v_lot.remaining_amount,
      'expires_at', v_lot.expires_at
    );
  END IF;

  SELECT * INTO v_profile
    FROM public.profiles
   WHERE id = p_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'profile_not_found');
  END IF;
  IF COALESCE(v_profile.is_vip, false) IS NOT TRUE
     OR v_profile.vip_tier IS DISTINCT FROM 'lifetime'
     OR v_profile.lifetime_vip_since IS NULL
     OR v_profile.lifetime_vip_since >
       (p_grant_month::timestamp AT TIME ZONE 'America/Chicago') THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_eligible');
  END IF;

  v_op_id := 'lifetime-vip-monthly:' || p_user_id::text || ':' || to_char(p_grant_month, 'YYYY-MM');
  INSERT INTO public.lifetime_vip_diamond_lots(user_id, grant_month, mint_op_id)
  VALUES (p_user_id, p_grant_month, v_op_id)
  RETURNING * INTO v_lot;

  v_mint := public.fn_ca_mint(
    'diamonds', 'player', p_user_id, 2000,
    'Lifetime VIP Monthly Diamond Benefit', v_op_id, 'promotional'
  );
  IF COALESCE((v_mint ->> 'ok')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Lifetime VIP monthly Diamond mint refused: %',
      COALESCE(v_mint ->> 'reason', 'unknown_error');
  END IF;

  SELECT id INTO v_tx
    FROM public.diamond_transactions
   WHERE user_id = p_user_id
     AND reference_id = v_op_id
   LIMIT 1;
  IF v_tx IS NULL THEN
    RAISE EXCEPTION 'Lifetime VIP monthly Diamond mint has no journal receipt';
  END IF;

  UPDATE public.lifetime_vip_diamond_lots
     SET status = 'active',
         issued_at = v_now,
         expires_at = v_now + interval '90 days',
         mint_transaction_id = v_tx,
         updated_at = v_now
   WHERE id = v_lot.id
   RETURNING * INTO v_lot;

  RETURN jsonb_build_object(
    'success', true,
    'duplicate', false,
    'lot_id', v_lot.id,
    'amount', 2000,
    'remaining', 2000,
    'expires_at', v_lot.expires_at,
    'balance_after', v_mint -> 'balance_after'
  );
END;
$$;


ALTER FUNCTION public.grant_lifetime_vip_monthly_diamonds(p_user_id uuid, p_grant_month date) OWNER TO postgres;

--
-- TOC entry 4863 (class 1255 OID 17730971)
-- Name: guard_agent_wallet_direct_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.guard_agent_wallet_direct_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if current_user in ('authenticated','anon') then
    if tg_op='INSERT' and (
      coalesce(new.agent_wallet_balance,0)<>0 or coalesce(new.business_balance,0)<>0 or
      coalesce(new.player_wallet_balance,0)<>0 or coalesce(new.player_balance,0)<>0 or
      coalesce(new.promo_wallet_balance,0)<>0 or coalesce(new.promo_balance,0)<>0 or
      coalesce(new.credit_limit,0)<>0 or coalesce(new.credit_used,0)<>0 or
      coalesce(new.commission_rate,0)<>0 or coalesce(new.player_rakeback_rate,0)<>0
    ) then
      raise exception 'Agent financial accounts may only be created through authorized operations';
    elsif tg_op='UPDATE' and (
      new.agent_wallet_balance is distinct from old.agent_wallet_balance or
      new.business_balance is distinct from old.business_balance or
      new.player_wallet_balance is distinct from old.player_wallet_balance or
      new.player_balance is distinct from old.player_balance or
      new.promo_wallet_balance is distinct from old.promo_wallet_balance or
      new.promo_balance is distinct from old.promo_balance or
      new.credit_limit is distinct from old.credit_limit or
      new.credit_used is distinct from old.credit_used or
      new.commission_rate is distinct from old.commission_rate or
      new.player_rakeback_rate is distinct from old.player_rakeback_rate
    ) then
      raise exception 'Agent financial accounts may only change through authorized operations';
    end if;
  end if;
  return new;
end
$$;


ALTER FUNCTION public.guard_agent_wallet_direct_update() OWNER TO postgres;

--
-- TOC entry 5033 (class 1255 OID 153157890)
-- Name: guard_native_worker_post_fields(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.guard_native_worker_post_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
 IF current_user IN ('anon','authenticated') THEN
   IF TG_OP='INSERT' THEN
     IF NEW.metadata->>'native_reels_worker' IS NOT NULL THEN
       RAISE EXCEPTION 'Native worker ownership is service-owned' USING ERRCODE='42501'; END IF;
     IF NEW.original_media_url IS NOT NULL OR NEW.transcode_status IS NOT NULL OR NEW.transcode_error IS NOT NULL THEN
       RAISE EXCEPTION 'Native processing fields are service-owned' USING ERRCODE='42501'; END IF;
   ELSIF (NEW.metadata->>'native_reels_worker') IS DISTINCT FROM (OLD.metadata->>'native_reels_worker')
     OR NEW.original_media_url IS DISTINCT FROM OLD.original_media_url
     OR NEW.transcode_status IS DISTINCT FROM OLD.transcode_status
     OR NEW.transcode_error IS DISTINCT FROM OLD.transcode_error THEN
     RAISE EXCEPTION 'Native processing fields are service-owned' USING ERRCODE='42501';
   END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.guard_native_worker_post_fields() OWNER TO postgres;

