--
-- TOC entry 8128 (class 1255 OID 12970914)
-- Name: heartbeat_table_leases(text, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.heartbeat_table_leases(p_instance_id text, p_table_ids uuid[]) RETURNS TABLE(table_id uuid)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  UPDATE public.engine_table_leases l
     SET heartbeat_at = clock_timestamp()
   WHERE l.protocol_version < 2
     AND l.instance_id = p_instance_id
     AND l.table_id = ANY(COALESCE(p_table_ids, '{}'::uuid[]))
  RETURNING l.table_id;
$$;


ALTER FUNCTION public.heartbeat_table_leases(p_instance_id text, p_table_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 50084 (class 0 OID 0)
-- Dependencies: 8128
-- Name: FUNCTION heartbeat_table_leases(p_instance_id text, p_table_ids uuid[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.heartbeat_table_leases(p_instance_id text, p_table_ids uuid[]) IS 'Renew this instance''s leases. Returns only the table_ids still owned - anything missing from the result has been lost and must not be dealt.';


--
-- TOC entry 4812 (class 1255 OID 17138061)
-- Name: heartbeat_table_leases_v2(text, uuid[], integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.heartbeat_table_leases_v2(p_instance_id text, p_table_ids uuid[], p_stale_seconds integer DEFAULT 30) RETURNS TABLE(table_id uuid, state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF length(btrim(COALESCE(p_instance_id, ''))) = 0 THEN
    RAISE EXCEPTION 'heartbeat_table_leases_v2 requires a non-empty instance_id'
      USING ERRCODE = '22023';
  END IF;
  IF p_stale_seconds IS DISTINCT FROM public.fn_engine_lease_stale_seconds() THEN
    RAISE EXCEPTION 'heartbeat_table_leases_v2 requires the audited 30 second stale window'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH renewed AS (
    UPDATE public.engine_table_leases l
       SET heartbeat_at = clock_timestamp()
     WHERE l.protocol_version < 2
       AND l.instance_id = p_instance_id
       AND l.table_id = ANY(COALESCE(p_table_ids, '{}'::uuid[]))
    RETURNING l.table_id
  ),
  asked AS (
    SELECT unnest(COALESCE(p_table_ids, '{}'::uuid[])) AS id
  )
  SELECT a.id,
         CASE
           WHEN r.table_id IS NOT NULL THEN 'kept'
           WHEN l.table_id IS NULL THEN 'missing'
           WHEN l.protocol_version >= 2 THEN 'taken'
           WHEN l.heartbeat_at < clock_timestamp() - make_interval(
             secs => public.fn_engine_lease_stale_seconds()
           )
             THEN 'stale'
           ELSE 'taken'
         END
    FROM asked a
    LEFT JOIN renewed r ON r.table_id = a.id
    LEFT JOIN public.engine_table_leases l ON l.table_id = a.id;
END;
$$;


ALTER FUNCTION public.heartbeat_table_leases_v2(p_instance_id text, p_table_ids uuid[], p_stale_seconds integer) OWNER TO postgres;

--
-- TOC entry 50086 (class 0 OID 0)
-- Dependencies: 4812
-- Name: FUNCTION heartbeat_table_leases_v2(p_instance_id text, p_table_ids uuid[], p_stale_seconds integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.heartbeat_table_leases_v2(p_instance_id text, p_table_ids uuid[], p_stale_seconds integer) IS 'Renew this instance''s table leases and report the truth about every id asked for: kept (renewed), taken (a different instance holds a LIVE lease - stop dealing), stale (holder has gone quiet, reclaimable), missing (no lease row at all - reclaim, nobody took it). Replaces the v1 shape, which could only say "kept" and so reported absent rows as takeovers.';


--
-- TOC entry 5154 (class 1255 OID 24465569)
-- Name: heartbeat_table_leases_v3(text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.heartbeat_table_leases_v3(p_instance_id text, p_claims jsonb, p_stale_seconds integer DEFAULT 30) RETURNS TABLE(table_id uuid, state text, lease_generation uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF length(btrim(COALESCE(p_instance_id, ''))) = 0 THEN
    RAISE EXCEPTION 'heartbeat_table_leases_v3 requires a non-empty instance_id'
      USING ERRCODE = '22023';
  END IF;
  IF p_stale_seconds IS DISTINCT FROM public.fn_engine_lease_stale_seconds() THEN
    RAISE EXCEPTION 'heartbeat_table_leases_v3 requires the audited 30 second stale window'
      USING ERRCODE = '22023';
  END IF;
  IF p_claims IS NULL OR jsonb_typeof(p_claims) <> 'array' THEN
    RAISE EXCEPTION 'heartbeat_table_leases_v3 requires a JSON array of claims'
      USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_claims) item
     WHERE jsonb_typeof(item) <> 'object'
        OR length(btrim(COALESCE(item ->> 'table_id', ''))) = 0
        OR length(btrim(COALESCE(item ->> 'lease_generation', ''))) = 0
  ) THEN
    RAISE EXCEPTION
      'heartbeat_table_leases_v3 requires table_id and lease_generation for every claim'
      USING ERRCODE = '22023';
  END IF;

  /* Cast before any UPDATE and reject duplicate table ids for the whole
     request.  A partial heartbeat would falsely make omitted claims look
     current to the engine. */
  IF EXISTS (
    WITH asked AS (
      SELECT (item ->> 'table_id')::uuid AS id
        FROM jsonb_array_elements(p_claims) item
    )
    SELECT 1 FROM asked GROUP BY id HAVING count(*) <> 1
  ) THEN
    RAISE EXCEPTION 'heartbeat_table_leases_v3 refuses duplicate tables'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH asked AS MATERIALIZED (
    SELECT (item ->> 'table_id')::uuid AS id,
           (item ->> 'lease_generation')::uuid AS requested_generation
      FROM jsonb_array_elements(p_claims) item
  ),
  renewed AS (
    UPDATE public.engine_table_leases l
       SET heartbeat_at = clock_timestamp()
      FROM asked a
     WHERE l.table_id = a.id
       AND l.instance_id = p_instance_id
       AND l.protocol_version = 2
       AND l.lease_generation = a.requested_generation
       AND l.heartbeat_at >= clock_timestamp() - make_interval(
         secs => public.fn_engine_lease_stale_seconds()
       )
    RETURNING l.table_id, l.lease_generation
  )
  SELECT a.id,
         CASE
           WHEN r.table_id IS NOT NULL THEN 'kept'
           WHEN l.table_id IS NULL THEN 'missing'
           WHEN l.heartbeat_at < clock_timestamp() - make_interval(
             secs => public.fn_engine_lease_stale_seconds()
           ) THEN 'stale'
           ELSE 'taken'
         END,
         l.lease_generation
    FROM asked a
    LEFT JOIN renewed r ON r.table_id = a.id
    LEFT JOIN public.engine_table_leases l ON l.table_id = a.id;
END;
$$;


