-- TOC entry 6809 (class 1255 OID 9352465)
-- Name: increment_cache_served(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.increment_cache_served(cache_uuid uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if cache_uuid is null then return; end if;
  update geeves_knowledge_cache
     set times_served = coalesce(times_served, 0) + 1,
         last_served_at = now()
   where id = cache_uuid;
end $$;


