--

CREATE FUNCTION public.is_vip(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_is_vip BOOLEAN;
BEGIN
    SELECT EXISTS(
        SELECT 1 FROM vip_subscriptions
        WHERE user_id = p_user_id
        AND status = 'active'
        AND current_period_end > NOW()
    ) INTO v_is_vip;
    
    RETURN COALESCE(v_is_vip, FALSE);
END;
$$;


