--
-- TOC entry 7027 (class 1255 OID 4633100)
-- Name: mark_all_home_notifications_read(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_all_home_notifications_read(p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_updated int;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    UPDATE notifications 
       SET read = true, is_read = true, updated_at = NOW()
     WHERE user_id = p_caller_user_id 
       AND type LIKE 'home_%'
       AND read = false;
    GET DIAGNOSTICS v_updated = ROW_COUNT;
    RETURN jsonb_build_object('success', true, 'marked_read', v_updated);
END; $$;


ALTER FUNCTION public.mark_all_home_notifications_read(p_caller_user_id uuid) OWNER TO postgres;

--
-- TOC entry 3675 (class 1255 OID 2120544)
-- Name: mark_clip_used(uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_clip_used(p_clip_id uuid, p_horse_id integer, p_post_id uuid, p_caption text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    -- Update clip stats
    UPDATE clip_library
    SET used_count = used_count + 1,
        last_used_at = NOW(),
        last_used_by = auth.uid()
    WHERE id = p_clip_id;
    
    -- Log usage
    INSERT INTO clip_usage_log (clip_id, horse_id, post_id, caption_used)
    VALUES (p_clip_id, p_horse_id, p_post_id, p_caption);
END;
$$;


ALTER FUNCTION public.mark_clip_used(p_clip_id uuid, p_horse_id integer, p_post_id uuid, p_caption text) OWNER TO postgres;

--
-- TOC entry 4383 (class 1255 OID 4632648)
-- Name: mark_home_game_seat_away(uuid, integer, boolean, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_home_game_seat_away(p_game_id uuid, p_seat_number integer, p_is_away boolean, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_game RECORD; v_group RECORD;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
      RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;
    SELECT * INTO v_game FROM commander_home_games WHERE id = p_game_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GAME_NOT_FOUND'; END IF;
    SELECT * INTO v_group FROM commander_home_groups WHERE id = v_game.group_id;

    IF v_game.host_id <> p_caller_user_id AND v_group.owner_id <> p_caller_user_id
       AND NOT EXISTS (SELECT 1 FROM commander_home_members
                        WHERE group_id = v_game.group_id AND user_id = p_caller_user_id
                          AND role = 'admin' AND status = 'approved')
    THEN RAISE EXCEPTION 'NOT_AUTHORIZED'; END IF;

    UPDATE commander_home_seats
       SET status = CASE WHEN p_is_away THEN 'away' ELSE 'seated' END,
           away_since = CASE WHEN p_is_away THEN NOW() ELSE NULL END,
           updated_at = NOW()
     WHERE game_id = p_game_id AND seat_number = p_seat_number;

    RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION public.mark_home_game_seat_away(p_game_id uuid, p_seat_number integer, p_is_away boolean, p_caller_user_id uuid) OWNER TO postgres;

--
-- TOC entry 9151 (class 1255 OID 153157911)
-- Name: mark_inserted_native_reel_queue_owner(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_inserted_native_reel_queue_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE object_path text;
BEGIN
 IF NEW.transcode_status IS DISTINCT FROM 'queued' OR NEW.is_deleted IS DISTINCT FROM false
   OR NEW.playback_type IS DISTINCT FROM 'native' OR NEW.rights_status IS DISTINCT FROM 'user_authorized'
   OR NEW.moderation_state='taken_down' OR NEW.taken_down_at IS NOT NULL
   OR NEW.original_media_url IS DISTINCT FROM NEW.media_urls->>0 THEN RETURN NEW; END IF;
 IF NEW.original_media_url NOT LIKE 'https://kuklfnapbkmacvwxktbh.supabase.co/storage/v1/object/public/social-media/%'
   OR NEW.original_media_url ~ '[?%#\\[:cntrl:]]' THEN RETURN NEW; END IF;
 object_path=substring(NEW.original_media_url from length('https://kuklfnapbkmacvwxktbh.supabase.co/storage/v1/object/public/social-media/')+1);
 IF object_path !~ ('^(videos|reels)/'||NEW.author_id::text||'/[^/]+$')
   OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='social-media' AND name=object_path) THEN RETURN NEW; END IF;
 IF object_path LIKE ('reels/'||NEW.author_id::text||'/%') OR EXISTS(SELECT 1 FROM social_reels r
   WHERE r.source_post_id=NEW.id AND r.author_id=NEW.author_id AND r.playback_type='native'
   AND r.rights_status='user_authorized' AND r.is_deleted=false AND r.media_status='ready'
   AND r.moderation_state IS DISTINCT FROM 'taken_down' AND r.taken_down_at IS NULL) THEN
   IF NEW.metadata IS NOT NULL AND jsonb_typeof(NEW.metadata)<>'object' THEN
     RAISE EXCEPTION 'Native queue metadata must be an object' USING ERRCODE='22023'; END IF;
   UPDATE social_posts SET metadata=jsonb_set(COALESCE(metadata,'{}'::jsonb),'{native_reels_worker}',to_jsonb('sp-transcode'::text)) WHERE id=NEW.id;
 END IF;
 RETURN NEW;
END $_$;


