--
-- TOC entry 8780 (class 1255 OID 17703424)
-- Name: pnm_sync_venue_integrity_state_from_row(public.poker_venues); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pnm_sync_venue_integrity_state_from_row(p_row public.poker_venues) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_active boolean;
  v_location_status text;
  v_missing_fields text[];
  v_issue_types text[] := ARRAY[]::text[];
  v_primary_issue text;
  v_last_scraped_at timestamptz;
BEGIN
  v_active := coalesce(p_row.is_active, true) AND NOT coalesce(p_row.is_suppressed, false);
  v_location_status := public.pnm_basic_location_status(p_row);
  v_missing_fields := public.pnm_venue_missing_fields(p_row);
  v_last_scraped_at := coalesce(p_row.last_scraped_at, p_row.last_scraped);
  IF v_active THEN
    IF v_location_status IN ('missing', 'conflict', 'unverified') THEN
      v_issue_types := array_append(v_issue_types, v_location_status);
    END IF;
    IF cardinality(v_missing_fields) > 0 THEN
      v_issue_types := array_append(v_issue_types, 'incomplete');
    END IF;
    IF v_last_scraped_at IS NULL OR v_last_scraped_at < now() - interval '30 days' THEN
      v_issue_types := array_append(v_issue_types, 'stale');
    END IF;
  END IF;
  v_primary_issue := public.pnm_primary_venue_issue(v_issue_types);

  INSERT INTO public.venue_location_integrity_state (
    venue_id, name, venue_type, address, city, state, latitude, longitude,
    revision, active, location_status, location_reason, mappable, issue_types,
    primary_issue, priority, related_ids, missing_fields, completeness_score,
    last_scraped_at, data_quality, scrape_status, assessed_at, updated_at
  ) VALUES (
    p_row.id, p_row.name, p_row.venue_type, p_row.address, p_row.city, p_row.state,
    coalesce(p_row.latitude, p_row.lat)::double precision,
    coalesce(p_row.longitude, p_row.lng)::double precision,
    p_row.location_integrity_revision, v_active, v_location_status,
    CASE v_location_status
      WHEN 'missing' THEN 'coordinates_missing'
      WHEN 'conflict' THEN 'coordinates_invalid'
      WHEN 'approximate' THEN 'privacy_protected'
      ELSE 'initial_assessment_pending'
    END,
    v_location_status IN ('verified', 'border', 'approximate', 'unverified'),
    v_issue_types, v_primary_issue,
    CASE v_primary_issue
      WHEN 'conflict' THEN 0 WHEN 'missing' THEN 1 WHEN 'duplicate' THEN 2
      WHEN 'unverified' THEN 3 WHEN 'incomplete' THEN 4 WHEN 'stale' THEN 5 ELSE 99
    END,
    ARRAY[]::integer[], v_missing_fields,
    greatest(0, 100 - cardinality(v_missing_fields) * 20),
    v_last_scraped_at, p_row.data_quality, p_row.scrape_status, now(), now()
  )
  ON CONFLICT (venue_id) DO UPDATE SET
    name = EXCLUDED.name,
    venue_type = EXCLUDED.venue_type,
    address = EXCLUDED.address,
    city = EXCLUDED.city,
    state = EXCLUDED.state,
    latitude = EXCLUDED.latitude,
    longitude = EXCLUDED.longitude,
    revision = EXCLUDED.revision,
    active = EXCLUDED.active,
    location_status = EXCLUDED.location_status,
    location_reason = EXCLUDED.location_reason,
    mappable = EXCLUDED.mappable,
    issue_types = EXCLUDED.issue_types,
    primary_issue = EXCLUDED.primary_issue,
    priority = EXCLUDED.priority,
    related_ids = EXCLUDED.related_ids,
    missing_fields = EXCLUDED.missing_fields,
    completeness_score = EXCLUDED.completeness_score,
    last_scraped_at = EXCLUDED.last_scraped_at,
    data_quality = EXCLUDED.data_quality,
    scrape_status = EXCLUDED.scrape_status,
    assessed_at = EXCLUDED.assessed_at,
    updated_at = now();
END;
$$;


ALTER FUNCTION public.pnm_sync_venue_integrity_state_from_row(p_row public.poker_venues) OWNER TO postgres;

--
-- TOC entry 7427 (class 1255 OID 147199715)
-- Name: pnm_validate_player_document(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pnm_validate_player_document(p_kind text, p_document jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE v jsonb; k text; n numeric; d1 date; d2 date;
BEGIN
  IF jsonb_typeof(p_document) IS DISTINCT FROM 'object' OR octet_length(p_document::text)>16384
    OR p_document->'schemaVersion' IS DISTINCT FROM '1'::jsonb THEN
    RAISE EXCEPTION 'Invalid player document' USING ERRCODE='22023';
  END IF;
  IF p_kind='search' THEN
    IF p_document-ARRAY['schemaVersion','query','filters','location']<>'{}'::jsonb
      OR NOT p_document ?& ARRAY['query','filters','location']
      OR jsonb_typeof(p_document->'query') IS DISTINCT FROM 'string' OR length(p_document->>'query')>200 OR p_document->>'query' ~ '[[:cntrl:]]'
      OR jsonb_typeof(p_document->'filters') IS DISTINCT FROM 'object'
      OR (p_document->'filters')-ARRAY['state','game','stakes','date','type']<>'{}'::jsonb
      OR NOT (p_document->'filters' ?& ARRAY['state','game','stakes','date','type']) THEN
      RAISE EXCEPTION 'Invalid saved search' USING ERRCODE='22023';
    END IF;
    FOR k,v IN SELECT key,value FROM jsonb_each(p_document->'filters') LOOP
      IF jsonb_typeof(v) IS DISTINCT FROM 'string' OR length(v#>>'{}')>(CASE WHEN k='state' THEN 2 ELSE 40 END) OR v#>>'{}' ~ '[[:cntrl:]]' THEN
        RAISE EXCEPTION 'Invalid saved filter' USING ERRCODE='22023';
      END IF;
    END LOOP;
    IF p_document#>>'{filters,state}' !~ '^([A-Z]{2})?$' THEN RAISE EXCEPTION 'Invalid state' USING ERRCODE='22023'; END IF;
    IF p_document#>>'{filters,type}' NOT IN ('all','venues','live','tournaments','series','tours','home-games') THEN
      RAISE EXCEPTION 'Invalid saved search type' USING ERRCODE='22023';
    END IF;
    IF p_document->'location'<>'null'::jsonb THEN
      IF jsonb_typeof(p_document->'location') IS DISTINCT FROM 'object'
        OR (p_document->'location')-ARRAY['city','state']<>'{}'::jsonb
        OR NOT(p_document->'location' ?& ARRAY['city','state'])
        OR jsonb_typeof(p_document#>'{location,city}') IS DISTINCT FROM 'string'
        OR jsonb_typeof(p_document#>'{location,state}') IS DISTINCT FROM 'string'
        OR length(p_document#>>'{location,city}')>100 OR length(p_document#>>'{location,state}')>2
        OR p_document#>>'{location,city}' ~ '[[:cntrl:]]' OR p_document#>>'{location,state}' !~ '^([A-Z]{2})?$' THEN
        RAISE EXCEPTION 'Invalid coarse search location' USING ERRCODE='22023';
      END IF;
    END IF;
  ELSIF p_kind='trip' THEN
    IF p_document-ARRAY['schemaVersion','origin','destination','waypoints','corridorMi','dateRange','venueIds','seriesIds']<>'{}'::jsonb
      OR NOT p_document ?& ARRAY['origin','destination','waypoints','corridorMi','dateRange']
      OR jsonb_typeof(p_document->'origin') IS DISTINCT FROM 'string'
      OR jsonb_typeof(p_document->'destination') IS DISTINCT FROM 'string'
      OR length(btrim(p_document->>'origin')) NOT BETWEEN 1 AND 160
      OR length(btrim(p_document->>'destination')) NOT BETWEEN 1 AND 160
      OR length(p_document->>'origin')>160 OR length(p_document->>'destination')>160
      OR p_document->>'origin' ~ '[[:cntrl:]]' OR p_document->>'destination' ~ '[[:cntrl:]]'
      OR jsonb_typeof(p_document->'waypoints') IS DISTINCT FROM 'array'
      OR p_document->'corridorMi' NOT IN ('25'::jsonb,'50'::jsonb,'100'::jsonb)
      OR jsonb_typeof(p_document->'dateRange') IS DISTINCT FROM 'object'
      OR (p_document->'dateRange')-ARRAY['start','end']<>'{}'::jsonb
      OR NOT(p_document->'dateRange' ?& ARRAY['start','end']) THEN
      RAISE EXCEPTION 'Invalid trip' USING ERRCODE='22023';
    END IF;
    IF jsonb_array_length(p_document->'waypoints')>8 THEN RAISE EXCEPTION 'Too many waypoints' USING ERRCODE='22023'; END IF;
    FOR v IN SELECT value FROM jsonb_array_elements(p_document->'waypoints') LOOP
      IF jsonb_typeof(v) IS DISTINCT FROM 'string' OR length(btrim(v#>>'{}')) NOT BETWEEN 1 AND 160 OR length(v#>>'{}')>160 OR v#>>'{}' ~ '[[:cntrl:]]' THEN
        RAISE EXCEPTION 'Invalid waypoint' USING ERRCODE='22023';
      END IF;
    END LOOP;
    FOR k,v IN SELECT key,value FROM jsonb_each(p_document->'dateRange') LOOP
      IF jsonb_typeof(v) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'Invalid date' USING ERRCODE='22023'; END IF;
      IF v#>>'{}'<>'' THEN
        IF v#>>'{}' !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'Invalid date' USING ERRCODE='22023'; END IF;
        BEGIN n:=extract(year FROM (v#>>'{}')::date); EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'Invalid date' USING ERRCODE='22023'; END;
      END IF;
    END LOOP;
    IF (p_document#>>'{dateRange,start}'='')<>(p_document#>>'{dateRange,end}'='') THEN RAISE EXCEPTION 'Incomplete dates' USING ERRCODE='22023'; END IF;
    IF p_document#>>'{dateRange,start}'<>'' THEN
      d1:=(p_document#>>'{dateRange,start}')::date;d2:=(p_document#>>'{dateRange,end}')::date;
      IF d1>d2 THEN RAISE EXCEPTION 'Reversed dates' USING ERRCODE='22023'; END IF;
    END IF;
    FOREACH k IN ARRAY ARRAY['venueIds','seriesIds'] LOOP
    IF p_document ? k THEN
      IF jsonb_typeof(p_document->k) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid public references' USING ERRCODE='22023'; END IF;
      IF jsonb_array_length(p_document->k)>50 THEN RAISE EXCEPTION 'Too many public references' USING ERRCODE='22023'; END IF;
      FOR v IN SELECT value FROM jsonb_array_elements(p_document->k) LOOP
        IF jsonb_typeof(v) IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'Invalid venue reference' USING ERRCODE='22023'; END IF;
        n:=(v#>>'{}')::numeric;
        IF n<1 OR n>9007199254740991 OR trunc(n)<>n THEN RAISE EXCEPTION 'Invalid venue reference' USING ERRCODE='22023'; END IF;
      END LOOP;
    END IF;
    END LOOP;
  ELSE RAISE EXCEPTION 'Invalid plan kind' USING ERRCODE='22023'; END IF;
END $_$;


ALTER FUNCTION public.pnm_validate_player_document(p_kind text, p_document jsonb) OWNER TO postgres;

--
-- TOC entry 7806 (class 1255 OID 144406853)
-- Name: pnm_venue_contribution_access(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pnm_venue_contribution_access(p_venue_id integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v public.poker_venues%ROWTYPE; v_claim jsonb; v_legacy jsonb; v_corrections jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
  SELECT * INTO v FROM public.poker_venues WHERE id=p_venue_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'venue not found' USING ERRCODE='P0002'; END IF;
  SELECT to_jsonb(c)-'verification_code'-'admin_notes'-'verified_by' INTO v_claim
    FROM public.venue_claims c WHERE venue_id=p_venue_id AND user_id=auth.uid()
    ORDER BY created_at DESC NULLS LAST,id DESC LIMIT 1;
  SELECT to_jsonb(c) INTO v_legacy FROM public.page_claims c WHERE page_type='venue'
    AND page_id=p_venue_id::text AND user_id=auth.uid() ORDER BY created_at DESC NULLS LAST,id DESC LIMIT 1;
  SELECT coalesce(jsonb_agg(x.item ORDER BY x.created_at DESC,x.id DESC),'[]'::jsonb) INTO v_corrections
    FROM (SELECT to_jsonb(c) item,c.created_at,c.id FROM public.pnm_venue_corrections c
      WHERE venue_id=p_venue_id AND user_id=auth.uid() ORDER BY created_at DESC,id DESC LIMIT 30) x;
  RETURN jsonb_build_object('venue_id',p_venue_id,'is_claimed',coalesce(v.is_claimed,false),
    'revision',v.location_integrity_revision,'claim',v_claim,'legacy_claim',v_legacy,
    'permissions',public.pnm_contribution_permissions(auth.uid(),p_venue_id),'corrections',v_corrections);
END $$;


ALTER FUNCTION public.pnm_venue_contribution_access(p_venue_id integer) OWNER TO postgres;

--
-- TOC entry 3610 (class 1255 OID 17703418)
-- Name: pnm_venue_missing_fields(public.poker_venues); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pnm_venue_missing_fields(p_row public.poker_venues) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT array_remove(ARRAY[
    CASE WHEN nullif(trim(p_row.address), '') IS NULL THEN 'address' END,
    CASE WHEN nullif(trim(p_row.phone), '') IS NULL THEN 'phone' END,
    CASE WHEN nullif(trim(p_row.website), '') IS NULL THEN 'website' END,
    CASE WHEN coalesce(
      nullif(trim(p_row.profile_photo_url), ''),
      nullif(trim(p_row.cover_photo_url), ''),
      nullif(trim(p_row.logo_url), '')
    ) IS NULL THEN 'artwork' END,
    CASE WHEN coalesce(p_row.latitude, p_row.lat) IS NULL
           OR coalesce(p_row.longitude, p_row.lng) IS NULL THEN 'coordinates' END
  ]::text[], NULL);
$$;


