--
-- TOC entry 9391 (class 1255 OID 137497426)
-- Name: publish_horse_news_post(uuid, text, text, text, text, text, text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_horse_news_post(p_author_id uuid, p_content text, p_link_url text, p_link_title text, p_link_description text, p_link_image text, p_link_site_name text, p_news_type text, p_publication_key text, p_asset_key text, p_phrase_norm text, p_semantic_key text, p_brief jsonb) RETURNS TABLE(social_post_id uuid, created boolean, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  v_post_id uuid;
  v_lock text;
  v_field text;
  v_existing public.social_posts%ROWTYPE;
  v_phrase text := btrim(regexp_replace(regexp_replace(regexp_replace(
    lower(split_part(p_content, E'\n', 1)), 'https?://\S+', '', 'g'),
    '[^a-z0-9\s]', '', 'g'), '\s+', ' ', 'g'));
  v_host text;
  v_path text;
  v_hash text := md5(jsonb_build_array(p_author_id,p_content,p_link_url,
    p_link_title,p_link_description,p_link_image,p_link_site_name,p_news_type,
    p_publication_key,p_asset_key,p_phrase_norm,p_semantic_key,p_brief)::text);
BEGIN
  IF coalesce(auth.role()::text,'') <> 'service_role' THEN
    RAISE EXCEPTION 'horse news publication requires service role' USING ERRCODE='42501';
  END IF;
  IF p_author_id IS NULL OR p_news_type IS NULL OR p_news_type NOT IN ('poker','sports')
    OR p_content IS NULL OR char_length(btrim(p_content)) NOT BETWEEN 1 AND 2000
    OR p_link_title IS NULL OR char_length(btrim(p_link_title)) NOT BETWEEN 1 AND 600
    OR p_link_site_name IS NULL OR char_length(btrim(p_link_site_name)) NOT BETWEEN 1 AND 180
    OR p_link_url IS NULL OR length(p_link_url)>4096
    OR p_link_url !~ '^https?://[^/@[:space:]]+(/[^[:space:]]*)?$'
    OR (p_link_image IS NOT NULL AND (length(p_link_image)>4096 OR p_link_image !~ '^https?://[^/@[:space:]]+(/[^[:space:]]*)?$'))
    OR (p_link_description IS NOT NULL AND length(p_link_description)>2000)
    OR p_publication_key IS NULL OR p_publication_key !~ (
      '^fleet:'||p_author_id::text||':[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}$')
    OR p_phrase_norm IS NULL OR p_phrase_norm='' OR p_phrase_norm IS DISTINCT FROM v_phrase
    OR p_semantic_key IS NULL OR length(p_semantic_key) NOT BETWEEN 1 AND 4096
    OR p_semantic_key ~ '[[:cntrl:]]'
    OR jsonb_typeof(p_brief) IS DISTINCT FROM 'object' OR length(p_brief::text)>32768
    OR p_brief->>'kind' IS DISTINCT FROM 'link'
    OR p_brief->>'domain' IS DISTINCT FROM p_news_type
    OR jsonb_typeof(p_brief->'confidence') IS DISTINCT FROM 'number'
    OR jsonb_typeof(p_brief->'isQuestion') IS DISTINCT FROM 'boolean'
    OR nullif(p_brief->>'tone','') IS NULL THEN
    RAISE EXCEPTION 'invalid horse news publication input' USING ERRCODE='22023';
  END IF;
  FOREACH v_field IN ARRAY ARRAY['people','teams','concepts','amounts','builtFrom'] LOOP
    IF jsonb_typeof(p_brief->v_field) IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'invalid horse news brief array' USING ERRCODE='22023';
    END IF;
    IF jsonb_array_length(p_brief->v_field)>100 OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(p_brief->v_field) e
      WHERE jsonb_typeof(e) IS DISTINCT FROM 'string' OR length(e::text)>1000) THEN
      RAISE EXCEPTION 'invalid horse news brief array member' USING ERRCODE='22023';
    END IF;
  END LOOP;
  IF (p_brief->>'confidence')::numeric NOT BETWEEN 0 AND 1 THEN
    RAISE EXCEPTION 'invalid horse news confidence' USING ERRCODE='22023';
  END IF;
  v_host := lower(substring(p_link_url from '^https?://([^/]+)'));
  v_path := regexp_replace(split_part(split_part(regexp_replace(p_link_url,
    '^https?://[^/]+', ''),'?',1),'#',1),'/+$','');
  IF p_asset_key IS DISTINCT FROM 'url:'||v_host||v_path THEN
    RAISE EXCEPTION 'horse news asset does not match link' USING ERRCODE='22023';
  END IF;

  -- Share the existing atomic video author lock: news/video cannot race the
  -- same 20-hour cadence. Exact phrases share its namespace as well.
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'publish-horse-video-author:'||p_author_id::text,0));
  FOR v_lock IN SELECT DISTINCT k FROM unnest(ARRAY[
    'publish-horse-news-slot:'||p_publication_key,
    'publish-horse-video-asset:'||p_asset_key,
    'publish-horse-video-phrase:'||p_phrase_norm,
    'publish-horse-video-phrase:'||p_semantic_key]) k ORDER BY k LOOP
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_lock,0));
  END LOOP;

  -- A lost acknowledgement is resolved by exact durable operation identity,
  -- before cadence/reuse checks. An incomplete or changed retry is never success.
  SELECT * INTO v_existing FROM public.social_posts
  WHERE metadata->>'publication_key'=p_publication_key FOR UPDATE;
  IF FOUND THEN
    IF v_existing.metadata->>'publication_contract'='horse_news_atomic_v1'
       AND v_existing.metadata->>'publication_input_hash'=v_hash THEN
      IF NOT EXISTS(SELECT 1 FROM public.content_asset_use WHERE post_id=v_existing.id
        AND horse_id=p_author_id AND asset_key=p_asset_key)
        OR NOT EXISTS(SELECT 1 FROM public.post_briefs WHERE post_id=v_existing.id)
        OR EXISTS(SELECT 1 FROM unnest(ARRAY[p_phrase_norm,p_semantic_key]) k
          WHERE NOT EXISTS(SELECT 1 FROM public.horse_phrase_ledger l
            WHERE l.post_id=v_existing.id AND l.horse_id=p_author_id AND l.phrase_norm=k)) THEN
        RAISE EXCEPTION 'incomplete horse news publication receipt' USING ERRCODE='23514';
      END IF;
      RETURN QUERY SELECT v_existing.id,false,'already_published'::text; RETURN;
    END IF;
    RETURN QUERY SELECT NULL::uuid,false,'duplicate_slot'::text; RETURN;
  END IF;
  PERFORM 1 FROM public.content_settings FOR SHARE;
  IF (SELECT count(*) FROM public.content_settings)<>1 OR NOT EXISTS (
    SELECT 1 FROM public.content_settings WHERE engine_enabled IS TRUE AND auto_publish IS TRUE) THEN
    RAISE EXCEPTION 'horse news master gate disabled' USING ERRCODE='42501';
  END IF;
  PERFORM 1 FROM public.horse_post_modes WHERE mode=p_news_type||'_news'
    AND enabled IS TRUE AND approved_at IS NOT NULL AND nullif(btrim(approved_by),'') IS NOT NULL FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'horse news mode not approved/enabled' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.profiles p JOIN public.content_authors ca ON ca.profile_id=p.id
    WHERE p.id=p_author_id AND p.is_horse IS TRUE AND p.status='active'
      AND p.horse_status='available' AND ca.is_active IS TRUE FOR SHARE OF p,ca;
  IF NOT FOUND THEN RAISE EXCEPTION 'horse news author inactive' USING ERRCODE='42501'; END IF;
  IF EXISTS(SELECT 1 FROM public.social_posts WHERE author_id=p_author_id
    AND coalesce(is_deleted,false)=false AND created_at>=now()-interval '20 hours') THEN
    RETURN QUERY SELECT NULL::uuid,false,'posted_recently'::text; RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM public.content_asset_use WHERE asset_key=p_asset_key
    AND (horse_id=p_author_id OR used_at>=now()-interval '30 days')) THEN
    RETURN QUERY SELECT NULL::uuid,false,'asset_used'::text; RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM public.horse_phrase_ledger WHERE phrase_norm IN(p_phrase_norm,p_semantic_key)
    AND (used_at>=now()-interval '48 hours' OR (horse_id=p_author_id AND used_at>=now()-interval '90 days'))) THEN
    RETURN QUERY SELECT NULL::uuid,false,'phrase_used'::text; RETURN;
  END IF;
  INSERT INTO public.social_posts(author_id,content,content_type,media_urls,visibility,audience_mode,
    link_url,link_title,link_description,link_image,link_site_name,topic,topics,origin_type,metadata)
  VALUES(p_author_id,p_content,'link','[]'::jsonb,'public','public',p_link_url,p_link_title,
    p_link_description,p_link_image,p_link_site_name,p_news_type,ARRAY[p_news_type,'news'],'horse',
    jsonb_build_object('scheduler','fleet','news_type',p_news_type,'publication_key',p_publication_key,
      'publication_contract','horse_news_atomic_v1','publication_input_hash',v_hash)) RETURNING id INTO v_post_id;
  INSERT INTO public.content_asset_use(asset_key,horse_id,post_id) VALUES(p_asset_key,p_author_id,v_post_id);
  INSERT INTO public.horse_phrase_ledger(phrase_norm,horse_id,post_id)
    SELECT DISTINCT k,p_author_id,v_post_id FROM unnest(ARRAY[p_phrase_norm,p_semantic_key]) k;
  INSERT INTO public.post_briefs(post_id,kind,domain,sport,title,source,people,teams,concepts,amounts,
    topic,tone,is_question,confidence,summary,built_from)
  VALUES(v_post_id,'link',p_news_type,p_brief->>'sport',p_brief->>'title',p_brief->>'source',
    ARRAY(SELECT jsonb_array_elements_text(p_brief->'people')),
    ARRAY(SELECT jsonb_array_elements_text(p_brief->'teams')),
    ARRAY(SELECT jsonb_array_elements_text(p_brief->'concepts')),
    ARRAY(SELECT jsonb_array_elements_text(p_brief->'amounts')),
    p_brief->>'topic',p_brief->>'tone',(p_brief->>'isQuestion')::boolean,
    (p_brief->>'confidence')::numeric,p_brief->>'title',
    ARRAY(SELECT DISTINCT jsonb_array_elements_text(p_brief->'builtFrom')));
  RETURN QUERY SELECT v_post_id,true,'published'::text;
END $_$;


ALTER FUNCTION public.publish_horse_news_post(p_author_id uuid, p_content text, p_link_url text, p_link_title text, p_link_description text, p_link_image text, p_link_site_name text, p_news_type text, p_publication_key text, p_asset_key text, p_phrase_norm text, p_semantic_key text, p_brief jsonb) OWNER TO postgres;

--
-- TOC entry 8531 (class 1255 OID 58356253)
-- Name: publish_horse_video_reel(uuid, text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_horse_video_reel(p_author_id uuid, p_video_url text, p_caption text, p_topic text, p_asset_key text, p_phrase_norm text, p_semantic_key text, p_metadata jsonb) RETURNS TABLE(social_post_id uuid, social_reel_id uuid, created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_author_id uuid := p_author_id;
  v_video_url text := btrim(COALESCE(p_video_url, ''));
  v_caption text := btrim(COALESCE(p_caption, ''));
  v_topic text := lower(btrim(COALESCE(p_topic, '')));
  v_asset_key text := btrim(COALESCE(p_asset_key, ''));
  v_phrase_norm text := btrim(COALESCE(p_phrase_norm, ''));
  v_semantic_key text := NULLIF(btrim(COALESCE(p_semantic_key, '')), '');
  v_metadata jsonb := COALESCE(p_metadata, '{}'::jsonb);
  v_youtube_id text;
  v_canonical_url text;
  v_canonical_key text;
  v_computed_phrase text;
  v_post_id uuid;
  v_reel_id uuid;
  v_post_count integer := 0;
  v_reel_count integer := 0;
  v_mode_enabled boolean;
BEGIN
  IF COALESCE(auth.role()::text, '') <> 'service_role' THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'publish_horse_video_reel requires the service role';
  END IF;

  IF v_author_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'horse video publication requires one active horse author',
      CONSTRAINT = 'horse_video_active_author';
  END IF;

  -- Lock the selected identity rows so an administrative deactivation cannot
  -- commit between this check and publication.
  PERFORM 1
  FROM public.profiles p
  JOIN public.content_authors ca
    ON ca.profile_id = p.id
  WHERE p.id = v_author_id
    AND p.is_horse IS TRUE
    AND p.status = 'active'
    AND ca.is_active IS TRUE
  LIMIT 1
  FOR UPDATE OF p NOWAIT FOR SHARE OF ca NOWAIT;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'horse video publication requires one active horse author',
      CONSTRAINT = 'horse_video_active_author';
  END IF;

  IF v_topic NOT IN ('poker', 'sports') THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'horse video topic must be poker or sports';
  END IF;

  SELECT m.enabled
  INTO v_mode_enabled
  FROM public.horse_post_modes m
  WHERE m.mode = v_topic || '_video'
  FOR SHARE;

  IF v_mode_enabled IS DISTINCT FROM true THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = format('horse post mode %s_video is not enabled', v_topic);
  END IF;

  IF char_length(v_caption) = 0 OR char_length(v_caption) > 2000 THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'horse video caption must contain 1 to 2000 characters';
  END IF;

  IF octet_length(v_video_url) = 0
     OR octet_length(v_video_url) > 4096
     OR v_video_url !~* '^https://'
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'horse video publication requires an HTTPS YouTube URL';
  END IF;

  v_youtube_id := public.fn_extract_youtube_video_id(v_video_url);
  IF v_youtube_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'horse video publication accepts YouTube embeds only';
  END IF;

  IF v_asset_key IS DISTINCT FROM 'yt:' || v_youtube_id THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'horse video asset key does not match the YouTube identity';
  END IF;

  v_canonical_url := 'https://www.youtube.com/watch?v=' || v_youtube_id;
  v_canonical_key := 'youtube:' || v_youtube_id;

  v_computed_phrase := btrim(
    regexp_replace(
      regexp_replace(
        regexp_replace(
          lower(split_part(v_caption, E'\n', 1)),
          'https?://\S+',
          '',
          'gi'
        ),
        '[^a-z0-9\s]',
        '',
        'g'
      ),
      '\s+',
      ' ',
      'g'
    )
  );

  IF v_phrase_norm = ''
     OR v_phrase_norm IS DISTINCT FROM v_computed_phrase
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'horse video phrase key does not match the normalized caption';
  END IF;

  IF v_semantic_key IS NULL
     OR octet_length(v_semantic_key) > 4096
     OR v_semantic_key ~ '[[:cntrl:]]'
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'horse video semantic key is invalid';
  END IF;

  IF jsonb_typeof(v_metadata) IS DISTINCT FROM 'object'
     OR octet_length(v_metadata::text) > 32768
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'horse video metadata must be a bounded JSON object';
  END IF;

  -- One lock owns the cadence for this horse. A second lock owns this asset
  -- platform-wide, so two horses cannot both pass the 30-day check. Phrase
  -- and semantic locks close the equivalent cross-horse check/insert races.
  -- These namespaces serialize this isolated video RPC. The mixed publisher
  -- is globally disabled; Phase 2 must retire or move every remaining legacy
  -- direct horse-post path onto the same protocol before it is re-enabled.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'publish-horse-video-author:' || v_author_id::text,
      0
    )
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'publish-horse-video-asset:' || v_asset_key,
      0
    )
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'publish-horse-video-phrase:' || v_phrase_norm,
      0
    )
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'publish-horse-video-semantic:' || v_semantic_key,
      0
    )
  );

  -- A response can be lost after COMMIT. The canonical author/asset pair is
  -- the operation identity. A retry returns the existing fully-linked object
  -- before cadence or reuse windows can reject the already-completed write.
  SELECT count(*)::integer
  INTO v_post_count
  FROM public.social_posts existing_post
  WHERE existing_post.author_id = v_author_id
    AND existing_post.origin_type = 'horse'
    AND existing_post.content_type = 'video'
    AND COALESCE(existing_post.is_deleted, false) = false
    AND existing_post.canonical_asset_key = v_canonical_key
    AND existing_post.youtube_video_id = v_youtube_id
    AND existing_post.metadata ->> 'publication_contract'
      = 'horse_video_reel_v1';

  IF v_post_count > 1 THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'horse video retry found multiple canonical Social posts';
  END IF;

  SELECT existing_post.id
  INTO v_post_id
  FROM public.social_posts existing_post
  WHERE existing_post.author_id = v_author_id
    AND existing_post.origin_type = 'horse'
    AND existing_post.content_type = 'video'
    AND COALESCE(existing_post.is_deleted, false) = false
    AND existing_post.canonical_asset_key = v_canonical_key
    AND existing_post.youtube_video_id = v_youtube_id
    AND existing_post.metadata ->> 'publication_contract'
      = 'horse_video_reel_v1'
  ORDER BY existing_post.created_at ASC NULLS LAST, existing_post.id ASC
  LIMIT 1
  FOR UPDATE;

  IF v_post_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.social_posts existing_post
      WHERE existing_post.id = v_post_id
        AND existing_post.author_id = v_author_id
        AND existing_post.origin_type = 'horse'
        AND existing_post.content_type = 'video'
        AND existing_post.visibility = 'public'
        AND existing_post.audience_mode = 'public'
        AND existing_post.playback_type = 'youtube_embed'
        AND existing_post.topic = v_topic
        AND existing_post.rights_status = 'embed_only'
        AND existing_post.youtube_video_id = v_youtube_id
        AND existing_post.canonical_asset_key = v_canonical_key
        AND existing_post.metadata ->> 'asset_key' = v_asset_key
        AND NULLIF(existing_post.metadata ->> 'phrase_norm', '') IS NOT NULL
        AND NULLIF(existing_post.metadata ->> 'semantic_key', '') IS NOT NULL
        AND existing_post.metadata ->> 'youtube_video_id' = v_youtube_id
        AND existing_post.metadata ->> 'topic' = v_topic
        AND public.fn_extract_youtube_video_id(
          NULLIF(existing_post.media_urls ->> 0, '')
        ) = v_youtube_id
    ) THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'horse video retry found a conflicting canonical Social post';
    END IF;

    SELECT count(*)::integer,
           (array_agg(
             existing_reel.id
             ORDER BY existing_reel.created_at ASC NULLS LAST,
                      existing_reel.id ASC
           ))[1]
    INTO v_reel_count, v_reel_id
    FROM public.social_reels existing_reel
    WHERE existing_reel.source_post_id = v_post_id;

    IF v_reel_count <> 1
       OR v_reel_id IS NULL
       OR NOT EXISTS (
         SELECT 1
         FROM public.social_reels existing_reel
         WHERE existing_reel.id = v_reel_id
           AND existing_reel.source_post_id = v_post_id
           AND existing_reel.author_id = v_author_id
           AND existing_reel.origin_type = 'horse'
           AND existing_reel.source_type = 'youtube'
           AND existing_reel.playback_type = 'youtube_embed'
           AND existing_reel.topic = v_topic
           AND existing_reel.rights_status = 'embed_only'
           AND existing_reel.youtube_video_id = v_youtube_id
           AND existing_reel.canonical_asset_key = v_canonical_key
           AND existing_reel.video_url = v_canonical_url
           AND existing_reel.original_youtube_url = v_canonical_url
           AND existing_reel.media_status = 'ready'
           AND existing_reel.is_public IS TRUE
           AND COALESCE(existing_reel.is_deleted, false) = false
           AND existing_reel.native_processing_requested IS FALSE
           AND existing_reel.source_asset_id IS NULL
           AND existing_reel.publication_key IS NULL
       )
    THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'horse video retry found no single valid linked Reel';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.content_asset_use asset_ledger
      WHERE asset_ledger.asset_key = v_asset_key
        AND asset_ledger.horse_id = v_author_id
        AND asset_ledger.post_id = v_post_id
    ) OR NOT EXISTS (
      SELECT 1
      FROM public.horse_phrase_ledger phrase_ledger
      WHERE phrase_ledger.horse_id = v_author_id
        AND phrase_ledger.post_id = v_post_id
        AND phrase_ledger.phrase_norm = (
          SELECT existing_post.metadata ->> 'phrase_norm'
          FROM public.social_posts existing_post
          WHERE existing_post.id = v_post_id
        )
    ) OR NOT EXISTS (
      SELECT 1
      FROM public.horse_semantic_ledger semantic_ledger
      WHERE semantic_ledger.horse_id = v_author_id
        AND semantic_ledger.post_id = v_post_id
        AND semantic_ledger.semantic_key = (
          SELECT existing_post.metadata ->> 'semantic_key'
          FROM public.social_posts existing_post
          WHERE existing_post.id = v_post_id
        )
    ) THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'horse video retry found incomplete publication ledgers';
    END IF;

    RETURN QUERY SELECT v_post_id, v_reel_id, false;
    RETURN;
  END IF;

  IF NOT public.fn_has_fresh_public_youtube_verification(v_youtube_id) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'horse video publication requires fresh shared YouTube verification',
      CONSTRAINT = 'horse_video_fresh_youtube_verification';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.social_posts recent_post
    WHERE recent_post.author_id = v_author_id
      AND COALESCE(recent_post.is_deleted, false) = false
      AND recent_post.created_at >= now() - interval '20 hours'
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'horse has already published inside the 20-hour cadence guard',
      CONSTRAINT = 'horse_video_recent_post_guard';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.content_asset_use mine
    WHERE mine.asset_key = v_asset_key
      AND mine.horse_id = v_author_id
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23505',
      MESSAGE = 'horse has already used this video asset';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.content_asset_use recent_asset
    WHERE recent_asset.asset_key = v_asset_key
      AND recent_asset.used_at >= now() - interval '30 days'
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'video asset was already used platform-wide inside 30 days',
      CONSTRAINT = 'horse_video_asset_global_window';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.horse_phrase_ledger recent_phrase
    WHERE recent_phrase.phrase_norm = v_phrase_norm
      AND recent_phrase.used_at >= now() - interval '48 hours'
  ) OR EXISTS (
    SELECT 1
    FROM public.horse_phrase_ledger horse_phrase
    WHERE horse_phrase.phrase_norm = v_phrase_norm
      AND horse_phrase.horse_id = v_author_id
      AND horse_phrase.used_at >= now() - interval '90 days'
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'horse video caption violates the phrase reuse window',
      CONSTRAINT = 'horse_video_phrase_reuse_window';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.horse_semantic_ledger recent_semantic
    WHERE recent_semantic.semantic_key = v_semantic_key
      AND recent_semantic.used_at >= now() - interval '48 hours'
  ) OR EXISTS (
    SELECT 1
    FROM public.horse_semantic_ledger horse_semantic
    WHERE horse_semantic.semantic_key = v_semantic_key
      AND horse_semantic.horse_id = v_author_id
      AND horse_semantic.used_at >= now() - interval '90 days'
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'horse video caption violates the semantic reuse window',
      CONSTRAINT = 'horse_video_semantic_reuse_window';
  END IF;

  INSERT INTO public.social_posts (
    author_id,
    content,
    content_type,
    media_urls,
    visibility,
    audience_mode,
    metadata,
    topics,
    origin_type,
    playback_type,
    topic,
    rights_status,
    youtube_video_id,
    canonical_asset_key
  ) VALUES (
    v_author_id,
    v_caption,
    'video',
    jsonb_build_array(v_canonical_url),
    'public',
    'public',
    v_metadata || jsonb_build_object(
      'publication_contract', 'horse_video_reel_v1',
      'asset_key', v_asset_key,
      'phrase_norm', v_phrase_norm,
      'semantic_key', v_semantic_key,
      'youtube_video_id', v_youtube_id,
      'topic', v_topic,
      'verification_source', 'shared_youtube_registry'
    ),
    ARRAY[v_topic]::text[],
    'horse',
    'youtube_embed',
    v_topic,
    'embed_only',
    v_youtube_id,
    v_canonical_key
  )
  RETURNING id INTO v_post_id;

  -- The maintained AFTER INSERT trigger owns Reel construction. It is legacy
  -- best effort for horse posts, so its output is not trusted until every
  -- required identity, rights and playback field is checked here.
  SELECT count(*)::integer,
         (array_agg(
           mirrored_reel.id
           ORDER BY mirrored_reel.created_at ASC NULLS LAST,
                    mirrored_reel.id ASC
         ))[1]
  INTO v_reel_count, v_reel_id
  FROM public.social_reels mirrored_reel
  WHERE mirrored_reel.source_post_id = v_post_id;

  IF v_reel_count <> 1
     OR v_reel_id IS NULL
     OR NOT EXISTS (
       SELECT 1
       FROM public.social_reels mirrored_reel
       WHERE mirrored_reel.id = v_reel_id
         AND mirrored_reel.source_post_id = v_post_id
         AND mirrored_reel.author_id = v_author_id
         AND mirrored_reel.origin_type = 'horse'
         AND mirrored_reel.source_type = 'youtube'
         AND mirrored_reel.playback_type = 'youtube_embed'
         AND mirrored_reel.topic = v_topic
         AND mirrored_reel.rights_status = 'embed_only'
         AND mirrored_reel.youtube_video_id = v_youtube_id
         AND mirrored_reel.canonical_asset_key = v_canonical_key
         AND mirrored_reel.video_url = v_canonical_url
         AND mirrored_reel.original_youtube_url = v_canonical_url
         AND mirrored_reel.media_status = 'ready'
         AND mirrored_reel.is_public IS TRUE
         AND COALESCE(mirrored_reel.is_deleted, false) = false
         AND mirrored_reel.native_processing_requested IS FALSE
         AND mirrored_reel.source_asset_id IS NULL
         AND mirrored_reel.publication_key IS NULL
     )
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'atomic horse video publication did not create one valid linked Reel',
      CONSTRAINT = 'horse_video_linked_reel_contract';
  END IF;

  UPDATE public.social_posts published_post
  SET link_url = '/hub/reels?id=' || v_reel_id::text
  WHERE published_post.id = v_post_id
    AND published_post.link_url IS DISTINCT FROM
      '/hub/reels?id=' || v_reel_id::text;

  INSERT INTO public.content_asset_use (
    asset_key, horse_id, post_id, used_at
  ) VALUES (v_asset_key, v_author_id, v_post_id, now());

  INSERT INTO public.horse_phrase_ledger (
    phrase_norm, horse_id, post_id, used_at
  ) VALUES (v_phrase_norm, v_author_id, v_post_id, now());

  INSERT INTO public.horse_semantic_ledger (
    semantic_key, horse_id, post_id, used_at
  ) VALUES (v_semantic_key, v_author_id, v_post_id, now());

  RETURN QUERY SELECT v_post_id, v_reel_id, true;
END
$$;


