--
-- TOC entry 7143 (class 1255 OID 22314885)
-- Name: purge_personal_assistant_data(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.purge_personal_assistant_data(p_user_id uuid, p_scope text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_counts jsonb := '{}'::jsonb;
  v_count integer := 0;
  v_leak_ids uuid[] := '{}'::uuid[];
  v_session_ids uuid[] := '{}'::uuid[];
  v_receipt_id uuid;
  v_fingerprint text;
BEGIN
  IF p_user_id IS NULL OR p_scope NOT IN ('coaching', 'analysis', 'sandbox', 'all') THEN
    RAISE EXCEPTION 'invalid personal assistant purge request';
  END IF;

  IF p_scope IN ('coaching', 'all') THEN
    DELETE FROM public.pa_coach_feedback WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('coach_feedback', v_count);
    DELETE FROM public.pa_coaching_goals WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('coaching_goals', v_count);
    DELETE FROM public.pa_coaching_preferences WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('preferences', v_count);
  END IF;

  IF p_scope IN ('analysis', 'all') THEN
    SELECT coalesce(array_agg(id), '{}'::uuid[]) INTO v_leak_ids
    FROM public.user_leaks WHERE user_id = p_user_id;

    DELETE FROM public.leak_hand_examples WHERE leak_id = ANY(v_leak_ids);
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('hand_examples', v_count);
    DELETE FROM public.leak_drill_answers WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('drill_answers', v_count);
    DELETE FROM public.leak_drill_attempts WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('drill_attempts', v_count);
    DELETE FROM public.leak_drill_sessions WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('drill_sessions', v_count);
    DELETE FROM public.leak_review_state WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('review_states', v_count);
    DELETE FROM public.hand_audit_decisions WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('audit_decisions', v_count);
    DELETE FROM public.pa_leak_audit_jobs WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('audit_jobs', v_count);
    DELETE FROM public.user_leaks WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('leaks', v_count);
  END IF;

  IF p_scope IN ('sandbox', 'all') THEN
    SELECT coalesce(array_agg(id), '{}'::uuid[]) INTO v_session_ids
    FROM public.sandbox_sessions WHERE user_id = p_user_id;
    DELETE FROM public.sandbox_coach_results WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_coach_results', v_count);
    DELETE FROM public.sandbox_equity_history WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_equity_history', v_count);
    DELETE FROM public.sandbox_results WHERE session_id = ANY(v_session_ids);
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_results', v_count);
    DELETE FROM public.sandbox_sessions WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_sessions', v_count);
    DELETE FROM public.sandbox_saved_hands WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('saved_hands', v_count);
    DELETE FROM public.sandbox_analytics WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_analytics', v_count);
    DELETE FROM public.sandbox_quiz_results WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_quiz_results', v_count);
    DELETE FROM public.sandbox_bookmarks WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_bookmarks', v_count);
    DELETE FROM public.sandbox_templates WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_templates', v_count);
    DELETE FROM public.sandbox_shared_scenarios WHERE creator_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sandbox_shared_scenarios', v_count);
    DELETE FROM public.solution_bookmarks WHERE user_id = p_user_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('solution_bookmarks', v_count);
  END IF;

  v_fingerprint := md5(p_user_id::text || ':' || p_scope || ':' || v_counts::text || ':' || clock_timestamp()::text || ':' || gen_random_uuid()::text);
  INSERT INTO public.pa_data_lifecycle_receipts (user_id, action, scope, item_counts, receipt_fingerprint)
  VALUES (p_user_id, 'delete', p_scope, v_counts, v_fingerprint)
  RETURNING id INTO v_receipt_id;

  RETURN jsonb_build_object('receipt_id', v_receipt_id, 'fingerprint', v_fingerprint, 'counts', v_counts);
END;
$$;


ALTER FUNCTION public.purge_personal_assistant_data(p_user_id uuid, p_scope text) OWNER TO postgres;

--
-- TOC entry 9072 (class 1255 OID 153005391)
-- Name: queue_owned_native_upload(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.queue_owned_native_upload(p_actor uuid, p_post_id uuid, p_video_url text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE p public.social_posts%ROWTYPE; object_path text;
BEGIN
 SELECT * INTO p FROM public.social_posts WHERE id=p_post_id FOR UPDATE;
 IF NOT FOUND OR p.author_id IS DISTINCT FROM p_actor OR COALESCE(p.is_deleted,false)
   OR p.moderation_state='taken_down' OR p.taken_down_at IS NOT NULL
   OR p.playback_type IS DISTINCT FROM 'native' OR p.rights_status IS DISTINCT FROM 'user_authorized' THEN
   RAISE EXCEPTION 'Native post is not authorized' USING ERRCODE='42501'; END IF;
 IF p_video_url IS NULL OR p_video_url NOT LIKE 'https://kuklfnapbkmacvwxktbh.supabase.co/storage/v1/object/public/social-media/%'
   OR p_video_url ~ '[?%#\\[:cntrl:]]' THEN
   RAISE EXCEPTION 'Native upload URL is not trusted' USING ERRCODE='22023'; END IF;
 object_path := substring(p_video_url from length('https://kuklfnapbkmacvwxktbh.supabase.co/storage/v1/object/public/social-media/')+1);
 IF object_path !~ ('^(videos|reels)/' || p_actor::text || '/[^/]+$')
   OR NOT EXISTS (SELECT 1 FROM storage.objects WHERE bucket_id='social-media' AND name=object_path) THEN
   RAISE EXCEPTION 'Native upload object is not owned or missing' USING ERRCODE='22023'; END IF;
 IF p.metadata IS NOT NULL AND jsonb_typeof(p.metadata)<>'object' THEN
  RAISE EXCEPTION 'Native queue metadata must be an object' USING ERRCODE='22023'; END IF;
 -- Assign the existing consumer only for explicit Reel paths or owned mirrors.
 IF object_path LIKE ('reels/'||p_actor::text||'/%') OR EXISTS(SELECT 1 FROM public.social_reels r
   WHERE r.source_post_id=p.id AND r.author_id=p_actor AND r.playback_type='native'
   AND r.rights_status='user_authorized' AND r.is_deleted=false AND r.media_status='ready'
   AND r.moderation_state IS DISTINCT FROM 'taken_down' AND r.taken_down_at IS NULL) THEN
   UPDATE public.social_posts SET metadata=jsonb_set(COALESCE(metadata,'{}'::jsonb),'{native_reels_worker}',to_jsonb('sp-transcode'::text)) WHERE id=p.id;
 END IF;
 IF p.original_media_url=p_video_url AND p.transcode_status IN ('queued','running','done') THEN
   RETURN jsonb_build_object('jobId','native:'||p.id,'status',p.transcode_status,'reused',true);
 END IF;
 IF p.media_urls->>0 IS DISTINCT FROM p_video_url THEN
   RAISE EXCEPTION 'Native upload does not match primary post media' USING ERRCODE='22023'; END IF;
 IF p.transcode_status IN ('queued','running') THEN
   RAISE EXCEPTION 'Another native source is already processing' USING ERRCODE='55000'; END IF;
 UPDATE public.social_posts SET original_media_url=p_video_url,transcode_status='queued',transcode_error=NULL WHERE id=p.id;
 RETURN jsonb_build_object('jobId','native:'||p.id,'status','queued','reused',false);
END $_$;


ALTER FUNCTION public.queue_owned_native_upload(p_actor uuid, p_post_id uuid, p_video_url text) OWNER TO postgres;

--
-- TOC entry 7837 (class 1255 OID 54599843)
-- Name: reap_dead_engine_leases(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reap_dead_engine_leases(p_stale_seconds integer DEFAULT 3600) RETURNS TABLE(table_leases_deleted integer, tournament_leases_deleted integer, table_leases_retained integer, tournament_leases_retained integer, oldest_retained_seconds integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE cutoff timestamptz; candidate record; event_id uuid; n integer;
 tables_deleted integer:=0; tournaments_deleted integer:=0;
 tables_retained integer:=0; tournaments_retained integer:=0; oldest integer:=0;
BEGIN
 IF coalesce(p_stale_seconds,0)<600 THEN
  RAISE EXCEPTION 'reap_dead_engine_leases refuses a cutoff under 600s (asked for %)',p_stale_seconds;
 END IF;
 cutoff:=now()-make_interval(secs=>p_stale_seconds);
 -- Admission holds KEY SHARE on the same lease. Lock before taking the next
 -- fresh custody snapshot; SKIP LOCKED leaves an admitted writer alone rather
 -- than waiting and then deleting from a snapshot taken before its commit.
 --
 -- A row this loop cannot lock is NOT counted as retained: it is a row this
 -- call could not read, and folding it into "kept for custody" would be the
 -- same conflation this migration exists to remove.
 FOR candidate IN SELECT l.tournament_id,l.heartbeat_at FROM public.engine_tournament_leases l
  WHERE l.heartbeat_at<cutoff
     /* A FINISHED EVENT KEEPS NO DEAD LEASE (2026-10-03). A lease on a
        COMPLETED or CANCELLED event that has missed twelve renewals has no
        live holder; it goes at boot or on the next pass, not in an hour. */
     OR (l.heartbeat_at<now()-interval '60 seconds'
         AND EXISTS (SELECT 1 FROM public.tournaments t
                      WHERE t.id=l.tournament_id AND t.status IN ('COMPLETED','CANCELLED')))
  ORDER BY l.tournament_id FOR UPDATE OF l SKIP LOCKED LOOP
  IF NOT smarter_private.f06_lease_has_pending_custody(candidate.tournament_id,NULL) THEN
   DELETE FROM public.engine_tournament_leases WHERE tournament_id=candidate.tournament_id AND heartbeat_at=candidate.heartbeat_at;
   GET DIAGNOSTICS n=ROW_COUNT; tournaments_deleted:=tournaments_deleted+n;
  ELSE
   tournaments_retained:=tournaments_retained+1;
   oldest:=greatest(oldest,floor(extract(epoch FROM now()-candidate.heartbeat_at))::integer);
  END IF;
 END LOOP;
 FOR candidate IN SELECT l.table_id,l.heartbeat_at FROM public.engine_table_leases l
  WHERE l.heartbeat_at<cutoff ORDER BY l.table_id FOR UPDATE OF l SKIP LOCKED LOOP
  SELECT tournament_id INTO event_id FROM public.tables WHERE id=candidate.table_id;
  -- A converted/table lease can still be the original F06 evidence. Join its
  -- event admission fence without waiting in reverse lease order. A busy event
  -- is retained for the next existing housekeeping call, never retried here.
  BEGIN
   IF event_id IS NOT NULL THEN
    PERFORM 1 FROM public.engine_tournament_leases WHERE tournament_id=event_id FOR UPDATE NOWAIT;
   END IF;
   IF NOT smarter_private.f06_lease_has_pending_custody(event_id,candidate.table_id) THEN
    DELETE FROM public.engine_table_leases WHERE table_id=candidate.table_id AND heartbeat_at<cutoff;
    GET DIAGNOSTICS n=ROW_COUNT; tables_deleted:=tables_deleted+n;
   ELSE
    tables_retained:=tables_retained+1;
    oldest:=greatest(oldest,floor(extract(epoch FROM now()-candidate.heartbeat_at))::integer);
   END IF;
  EXCEPTION WHEN lock_not_available THEN NULL;
  END;
 END LOOP;
 RETURN QUERY SELECT tables_deleted,tournaments_deleted,
                     tables_retained,tournaments_retained,oldest;
END $$;


