    insured_amount numeric(10,2) NOT NULL,
    payout numeric(10,2) DEFAULT 0.00 NOT NULL,
    player_won boolean DEFAULT false NOT NULL,
    net_result numeric(10,2) NOT NULL,
    bank_type character varying(10) NOT NULL,
    bank_entity_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    kind character varying(16) DEFAULT 'insurance'::character varying NOT NULL,
    CONSTRAINT insurance_transactions_bank_type_check CHECK (((bank_type)::text = ANY ((ARRAY['union'::character varying, 'club'::character varying])::text[])))
