COMMENT ON FUNCTION public.redeem_referral_code(p_referee_id uuid, p_code text) IS 'Redeems a referral code and pays DIAMONDS to both sides (never chips - Dan 2026-09-05). Idempotent per side via add_diamonds_to_balance reference_id; a failed credit rolls back the redemption.';


--
-- TOC entry 3447 (class 1255 OID 177808755)
-- Name: redeem_vip_gift_atomic(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.redeem_vip_gift_atomic(p_user uuid, p_gift uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE g public.vip_gifts%ROWTYPE; p public.profiles%ROWTYPE; v_expiry timestamptz; v_tier text;
BEGIN
 SELECT * INTO g FROM public.vip_gifts WHERE id=p_gift FOR UPDATE;
 IF NOT FOUND OR g.recipient_id IS DISTINCT FROM p_user THEN
   RETURN jsonb_build_object('success',false,'error','gift_not_found'); END IF;
 IF g.status='redeemed' THEN RETURN jsonb_build_object('success',true,'duplicate',true); END IF;
 IF g.status<>'available' THEN RETURN jsonb_build_object('success',false,'error','gift_not_available'); END IF;
 SELECT * INTO p FROM public.profiles WHERE id=p_user FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','profile_not_found'); END IF;
 IF p.vip_tier='lifetime' THEN RETURN jsonb_build_object('success',false,'error','already_lifetime'); END IF;
 IF EXISTS(SELECT 1 FROM public.vip_subscription_checkout_claims WHERE user_id=p_user AND
   (state='admitting' OR expires_at>now())) OR
 EXISTS(SELECT 1 FROM public.vip_subscriptions WHERE user_id=p_user AND
   status IN('active','trialing','past_due','unpaid','incomplete','paused') AND
   stripe_subscription_id IS NOT NULL AND left(stripe_subscription_id,8)<>'diamond_') THEN
   RETURN jsonb_build_object('success',false,'error','manage_card_subscription_first');
 END IF;
 v_tier:=CASE WHEN g.plan='monthly' AND p.vip_tier='yearly' AND p.vip_expires_at>now() THEN 'yearly' ELSE g.plan END;
 v_expiry:=CASE WHEN g.plan='lifetime' THEN NULL ELSE greatest(now(),COALESCE(p.vip_expires_at,now()))+
   make_interval(days=>CASE WHEN g.plan='monthly' THEN 30 ELSE 365 END) END;
 UPDATE public.vip_gifts SET status='redeemed',redeemed_at=now(),
   previous_entitlement=jsonb_build_object('is_vip',p.is_vip,'tier',p.vip_tier,'expires_at',p.vip_expires_at),
   granted_entitlement=jsonb_build_object('tier',v_tier,'expires_at',v_expiry) WHERE id=g.id;
 UPDATE public.profiles SET is_vip=true,vip_tier=v_tier,vip_expires_at=v_expiry,vip_gift_id=g.id,updated_at=now() WHERE id=p_user;
 RETURN jsonb_build_object('success',true,'tier',v_tier,'expiresAt',v_expiry);
END $$;


ALTER FUNCTION public.redeem_vip_gift_atomic(p_user uuid, p_gift uuid) OWNER TO postgres;

--
-- TOC entry 4399 (class 1255 OID 2962147)
-- Name: refresh_player_stats(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_player_stats() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
    DECLARE v_count INTEGER := 0;
    BEGIN
      INSERT INTO player_stats (user_id, club_id, hands_played, total_winnings, total_losses)
      SELECT hp.user_id, t.club_id, COUNT(*)::INTEGER as hands_played,
        COALESCE(SUM(hp.chips_won), 0) as total_winnings, COALESCE(SUM(hp.chips_lost), 0) as total_losses
      FROM hand_players hp JOIN hands h ON h.id = hp.hand_id JOIN tables t ON t.id = h.table_id
      WHERE t.club_id IS NOT NULL AND public.fn_ca_launch_accounting_accepts(t.club_id,h.created_at) GROUP BY hp.user_id, t.club_id
      ON CONFLICT (user_id, club_id) DO UPDATE SET
        hands_played = EXCLUDED.hands_played, total_winnings = EXCLUDED.total_winnings,
        total_losses = EXCLUDED.total_losses, updated_at = NOW();
      GET DIAGNOSTICS v_count = ROW_COUNT;
      RETURN v_count;
    END; $$;


ALTER FUNCTION public.refresh_player_stats() OWNER TO postgres;

--
-- TOC entry 7457 (class 1255 OID 17441923)
-- Name: refund_diamond_merch_order_atomic(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refund_diamond_merch_order_atomic(p_order_id uuid, p_actor_id uuid, p_reference_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_order public.merchandise_orders%ROWTYPE;
  v_from_status text;
  v_refund integer;
  v_wallet jsonb;
  v_stock_lines jsonb;
BEGIN
  IF p_reference_id IS NULL OR length(p_reference_id) < 16 OR length(p_reference_id) > 180 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_reference');
  END IF;

  SELECT * INTO v_order
    FROM public.merchandise_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'order_not_found');
  END IF;
  IF v_order.payment_method <> 'diamonds' THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_diamond_order');
  END IF;
  IF v_order.status IN ('shipped', 'delivered') THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_fulfilled');
  END IF;
  IF COALESCE(v_order.metadata ->> 'fulfillment_mode', '') = 'automatic'
     OR NULLIF(v_order.metadata ->> 'printful_order_id', '') IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'provider_cancellation_required'
    );
  END IF;
  v_from_status := v_order.status;

  v_refund := GREATEST(0, v_order.diamonds_spent - v_order.refunded_diamonds);
  IF v_refund = 0 THEN
    RETURN jsonb_build_object(
      'success', true,
      'duplicate', true,
      'order_id', v_order.id,
      'refunded_diamonds', v_order.refunded_diamonds
    );
  END IF;

  PERFORM public.fn_ca_authorize_funded_return('merch',v_order.id,'diamonds',v_order.user_id,v_refund,p_reference_id);
  v_wallet := public.add_diamonds_to_balance(
    v_order.user_id,
    v_refund,
    'refund',
    'Refund - Diamond merchandise order ' || v_order.id::text,
    p_reference_id
  );
  IF COALESCE((v_wallet ->> 'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Diamond merchandise refund wallet credit failed: %',
      COALESCE(v_wallet ->> 'error', 'unknown_error');
  END IF;

  IF NOT v_order.stock_restored THEN
    SELECT jsonb_agg(jsonb_build_object(
      'id', item ->> 'id',
      'variant_id', item ->> 'variantId',
      'qty', (item ->> 'quantity')::integer
    )) INTO v_stock_lines
      FROM jsonb_array_elements(v_order.items) AS item
     WHERE COALESCE((item ->> 'madeToOrder')::boolean, false) IS NOT TRUE;
    IF v_stock_lines IS NOT NULL THEN
      PERFORM public.release_merch_order(v_stock_lines);
    END IF;
  END IF;

  UPDATE public.merchandise_orders
     SET status = 'refunded',
         refunded_diamonds = diamonds_spent,
         refunded_at = now(),
         stock_restored = true,
         fulfillment_version = fulfillment_version + 1,
         metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
           'fulfillment_status', 'refunded',
           'needs_review', false,
           'refunded_by', p_actor_id,
           'refunded_at', now()
         ),
         updated_at = now()
   WHERE id = v_order.id
   RETURNING * INTO v_order;

  INSERT INTO public.merchandise_order_events(
    order_id, actor_id, action, from_status, to_status, details
  ) VALUES (
    v_order.id, p_actor_id, 'refund', v_from_status, 'refunded',
    jsonb_build_object('diamonds', v_refund, 'reference_id', p_reference_id)
  );

  RETURN jsonb_build_object(
    'success', true,
    'duplicate', false,
    'order_id', v_order.id,
    'refunded_diamonds', v_refund,
    'new_balance', v_wallet -> 'new_balance',
    'fulfillment_version', v_order.fulfillment_version
  );
END;
$$;


ALTER FUNCTION public.refund_diamond_merch_order_atomic(p_order_id uuid, p_actor_id uuid, p_reference_id text) OWNER TO postgres;

--
-- TOC entry 3499 (class 1255 OID 22240462)
-- Name: refund_diamond_merch_order_atomic_v2(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refund_diamond_merch_order_atomic_v2(p_order_id uuid, p_actor_id uuid, p_expected_version integer, p_reference_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_order public.merchandise_orders%ROWTYPE;
  v_from_status text;
  v_refund integer;
  v_wallet jsonb;
  v_stock_lines jsonb;
BEGIN
  IF p_expected_version IS NULL OR p_expected_version < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_version');
  END IF;
  IF p_reference_id IS NULL OR length(p_reference_id) < 16 OR length(p_reference_id) > 180 THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_reference');
  END IF;

  SELECT * INTO v_order
    FROM public.merchandise_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'order_not_found');
  END IF;
  IF v_order.payment_method <> 'diamonds' THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_diamond_order');
  END IF;

  v_refund := GREATEST(0, v_order.diamonds_spent - v_order.refunded_diamonds);
  IF v_refund = 0 THEN
    RETURN jsonb_build_object(
      'success', true,
      'duplicate', true,
      'order_id', v_order.id,
      'refunded_diamonds', v_order.refunded_diamonds,
      'fulfillment_version', v_order.fulfillment_version
    );
  END IF;

  IF v_order.fulfillment_version IS DISTINCT FROM p_expected_version THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'version_conflict',
      'fulfillment_version', v_order.fulfillment_version
    );
  END IF;
  IF v_order.status IN ('shipped', 'delivered') THEN
    RETURN jsonb_build_object('success', false, 'error', 'already_fulfilled');
  END IF;
  IF COALESCE(v_order.metadata ->> 'fulfillment_mode', '') = 'automatic'
     OR NULLIF(v_order.metadata ->> 'printful_order_id', '') IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'provider_cancellation_required'
    );
  END IF;
  v_from_status := v_order.status;

  PERFORM public.fn_ca_authorize_funded_return('merch',v_order.id,'diamonds',v_order.user_id,v_refund,p_reference_id);
  v_wallet := public.add_diamonds_to_balance(
    v_order.user_id,
    v_refund,
    'refund',
    'Refund - Diamond merchandise order ' || v_order.id::text,
    p_reference_id
  );
  IF COALESCE((v_wallet ->> 'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Diamond merchandise refund wallet credit failed: %',
      COALESCE(v_wallet ->> 'error', 'unknown_error');
  END IF;

  IF NOT v_order.stock_restored THEN
    SELECT jsonb_agg(jsonb_build_object(
      'id', item ->> 'id',
      'variant_id', item ->> 'variantId',
      'qty', (item ->> 'quantity')::integer
    )) INTO v_stock_lines
      FROM jsonb_array_elements(v_order.items) AS item
     WHERE COALESCE((item ->> 'madeToOrder')::boolean, false) IS NOT TRUE;
    IF v_stock_lines IS NOT NULL THEN
      PERFORM public.release_merch_order(v_stock_lines);
    END IF;
  END IF;

  UPDATE public.merchandise_orders
     SET status = 'refunded',
         refunded_diamonds = diamonds_spent,
         refunded_at = now(),
         stock_restored = true,
         fulfillment_version = fulfillment_version + 1,
         metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
           'fulfillment_status', 'refunded',
           'needs_review', false,
           'refunded_by', p_actor_id,
           'refunded_at', now()
         ),
         updated_at = now()
   WHERE id = v_order.id
   RETURNING * INTO v_order;

  INSERT INTO public.merchandise_order_events(
    order_id, actor_id, action, from_status, to_status, details
  ) VALUES (
    v_order.id, p_actor_id, 'refund', v_from_status, 'refunded',
    jsonb_build_object('diamonds', v_refund, 'reference_id', p_reference_id)
  );

  RETURN jsonb_build_object(
    'success', true,
    'duplicate', false,
    'order_id', v_order.id,
    'refunded_diamonds', v_refund,
    'new_balance', v_wallet -> 'new_balance',
    'fulfillment_version', v_order.fulfillment_version
  );
END;
$$;


