--
-- TOC entry 6512 (class 1255 OID 12632319)
-- Name: release_merch_order(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_merch_order(p_lines jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_line jsonb;
    v_variant_id uuid;
BEGIN
    IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_lines');
    END IF;

    FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
        v_variant_id := NULLIF(v_line ->> 'variant_id', 'null')::uuid;
        IF v_variant_id IS NOT NULL THEN
            UPDATE public.merchandise_item_variants
               SET stock = stock + (v_line ->> 'qty')::int, updated_at = now()
             WHERE id = v_variant_id AND stock IS NOT NULL;
        ELSE
            UPDATE public.merchandise_items
               SET stock = stock + (v_line ->> 'qty')::int, updated_at = now()
             WHERE id = v_line ->> 'id' AND stock IS NOT NULL;
        END IF;
    END LOOP;

    RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION public.release_merch_order(p_lines jsonb) OWNER TO postgres;

--
-- TOC entry 4718 (class 1255 OID 4633069)
-- Name: release_own_home_game_seat(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_own_home_game_seat(p_game_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_existing RECORD;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF;
    SELECT * INTO v_existing FROM commander_home_seats 
     WHERE game_id = p_game_id AND user_id = p_caller_user_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'NOT_SEATED'; END IF;

    UPDATE commander_home_seats 
       SET user_id = NULL, player_name = NULL, status = 'empty', 
           seated_at = NULL, away_since = NULL, note = NULL, updated_at = NOW()
     WHERE id = v_existing.id;

    RETURN jsonb_build_object('success', true, 'seat_number', v_existing.seat_number);
END;
$$;


