CREATE FUNCTION public.release_table_leases(p_instance_id text, p_table_ids uuid[] DEFAULT NULL::uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_deleted integer;
BEGIN
  DELETE FROM public.engine_table_leases l
   WHERE l.protocol_version < 2
     AND l.instance_id = p_instance_id
     AND (p_table_ids IS NULL OR l.table_id = ANY(p_table_ids));
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


