--

COMMENT ON FUNCTION public.settle_caption_model_budget(p_reservation_id uuid, p_idempotency_key text, p_charged_microusd bigint) IS 'Service-only idempotent bounded settlement. Unknown provider outcomes intentionally remain reserved.';


