--
-- TOC entry 5678 (class 1255 OID 24907993)
-- Name: sp_drain_daily_challenge_event_outbox(integer, integer, integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_drain_daily_challenge_event_outbox(IN p_limit integer DEFAULT 5000, IN p_shard integer DEFAULT 0, IN p_shards integer DEFAULT 1)
    LANGUAGE plpgsql
    AS $_$
DECLARE
  c_budget constant interval := interval '45 seconds';
  c_user_batch constant integer := 100;
  v_deadline timestamptz := clock_timestamp() + c_budget;
  v_lock_key bigint;
  v_user_id uuid;
  v_result jsonb;
  v_seen integer := 0;
  v_done integer := 0;
  v_skipped integer := 0;
BEGIN
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 5000 THEN
    RAISE EXCEPTION 'Invalid outbox batch size';
  END IF;
  IF p_shards IS NULL OR p_shards NOT IN (1, 2, 4, 8)
     OR p_shard IS NULL OR p_shard < 0 OR p_shard >= p_shards THEN
    RAISE EXCEPTION 'Invalid outbox shard %/%', p_shard, p_shards;
  END IF;

  v_lock_key := hashtextextended('daily-missions-event-outbox-drain', p_shard);
  IF NOT pg_try_advisory_lock(v_lock_key) THEN
    RETURN;
  END IF;

  WHILE v_seen < p_limit AND clock_timestamp() < v_deadline LOOP
    -- COMMIT below resets transaction-local settings.  Restore the private
    -- lookup path explicitly at the start of every player's transaction.
    PERFORM set_config('search_path', 'pg_catalog, public, pg_temp', true);
    /* ONE PLAYER'S RECEIPT IS NOT WORTH AN FSYNC (2026-10-01). 21% of the
       drain's time was WAL flush at this per-player COMMIT. The event is
       booked and its outbox row deleted in one transaction, so a crash that
       loses an unflushed commit loses both and the event is drained again;
       any later synchronous commit flushes this one first. */
    PERFORM set_config('synchronous_commit', 'off', true);

    EXECUTE format(
      $q$
      SELECT o.user_id
        FROM public.daily_challenge_event_outbox o
       WHERE o.dead_lettered_at IS NULL
         AND (
           o.occurred_at < now() - interval '35 days'
           OR o.next_attempt_at <= now()
         )
         AND (hashtext(o.user_id::text) & 2147483647) %% %s = %s
         /* A DRAIN DRAINS WHAT WAS PENDING (2026-10-03). Events arrive at
            ~7/s, so the only early exit - the picker finding nothing - was
            unreachable and every shard ran its whole 45 s budget chasing
            arrivals: 1.135 cores held for 2.9 s of work, 1.98 events per
            per-player transaction. v_deadline - c_budget is this run's own
            entry instant, so the run finishes the backlog it found and the
            next minute takes the next one. A deferred row is at or before
            every later watermark, so nothing is stranded. */
         AND o.created_at <= $1
       ORDER BY o.user_id, o.created_at, o.event_key
       LIMIT 1
      $q$,
      p_shards,
      p_shard
    ) INTO v_user_id USING (v_deadline - c_budget);

    EXIT WHEN v_user_id IS NULL;

    v_result := public.fn_drain_daily_challenge_event_outbox_user(
      v_user_id,
      LEAST(c_user_batch, p_limit - v_seen)
    );
    v_seen := v_seen + COALESCE((v_result ->> 'seen')::integer, 0);
    v_done := v_done + COALESCE((v_result ->> 'booked')::integer, 0);
    v_skipped := v_skipped + COALESCE((v_result ->> 'skipped')::integer, 0);

    -- This is the repair: release this player's profile/advisory/row locks
    -- before the shard even discovers which player comes next.
    COMMIT AND CHAIN;

    -- A raced-away row must not spin this session forever.
    EXIT WHEN COALESCE((v_result ->> 'seen')::integer, 0) = 0;
  END LOOP;

  PERFORM pg_advisory_unlock(v_lock_key);
  IF v_skipped > 0 THEN
    RAISE NOTICE
      'daily missions outbox shard %/%: booked %, skipped % on lock contention',
      p_shard,
      p_shards,
      v_done,
      v_skipped;
  END IF;
END;
$_$;


ALTER PROCEDURE public.sp_drain_daily_challenge_event_outbox(IN p_limit integer, IN p_shard integer, IN p_shards integer) OWNER TO postgres;

--
-- TOC entry 50513 (class 0 OID 0)
-- Dependencies: 5678
-- Name: PROCEDURE sp_drain_daily_challenge_event_outbox(IN p_limit integer, IN p_shard integer, IN p_shards integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON PROCEDURE public.sp_drain_daily_challenge_event_outbox(IN p_limit integer, IN p_shard integer, IN p_shards integer) IS 'Postgres-only primary Daily Missions outbox consumer. It preserves same-player serial booking and commits after each bounded player group so unrelated table settlements never wait behind accumulated profile locks.';


--
-- TOC entry 4987 (class 1255 OID 17214912)
-- Name: sp_grant_shop_item(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_grant_shop_item(p_user_id uuid, p_item_id uuid, p_unlock_method text DEFAULT 'club_shop_purchase'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_spec    jsonb;
  v_type    text;
  v_qty     integer;
  v_ref     text;
BEGIN
  SELECT grant_spec INTO v_spec FROM public.club_shop_items WHERE id = p_item_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'item_gone');
  END IF;

  v_type := COALESCE(v_spec->>'type', 'none');
  BEGIN
    v_qty := GREATEST(1, LEAST(1000, COALESCE((v_spec->>'qty')::integer, 1)));
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_grant_quantity');
  END;

  IF v_type = 'time_bank' THEN
    INSERT INTO public.feature_purchases
      (user_id, feature, cost, usage_type, uses_remaining, expires_at)
    VALUES (p_user_id, 'time_bank_seconds', 0, 'per_use', v_qty, NULL);
    RETURN jsonb_build_object(
      'success', true, 'type', v_type, 'uses', v_qty, 'seconds', v_qty * 20,
      'permanent', false
    );
  ELSIF v_type = 'throwable' THEN
    INSERT INTO public.feature_purchases
      (user_id, feature, cost, usage_type, uses_remaining, expires_at)
    VALUES (p_user_id, 'throwable', 0, 'per_use', v_qty, NULL);
    RETURN jsonb_build_object(
      'success', true, 'type', v_type, 'uses', v_qty, 'permanent', false
    );
  ELSIF v_type = 'emote_pack' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.feature_purchases
       WHERE user_id = p_user_id AND feature = 'emoji_pack'
         AND (expires_at IS NULL OR expires_at > now())
    ) THEN
      INSERT INTO public.feature_purchases
        (user_id, feature, cost, usage_type, uses_remaining, expires_at)
      VALUES (p_user_id, 'emoji_pack', 0, 'permanent', NULL, NULL);
    END IF;
    RETURN jsonb_build_object('success', true, 'type', v_type, 'permanent', true);
  ELSIF v_type = 'table_skin' THEN
    v_ref := public.sp_resolve_theme_preset(v_spec->>'theme_id');
    IF v_ref IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'invalid_theme_sku');
    END IF;
    PERFORM public.sp_grant_theme_preset(p_user_id, v_ref, p_unlock_method);
    RETURN jsonb_build_object(
      'success', true, 'type', v_type, 'theme_id', v_ref, 'permanent', true
    );
  ELSIF v_type = 'avatar' THEN
    v_ref := public.sp_resolve_avatar_shop_sku(v_spec->>'avatar_id');
    IF v_ref IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'invalid_avatar_sku');
    END IF;
    INSERT INTO public.avatar_unlocks (user_id, avatar_id, unlock_method)
    VALUES (p_user_id, v_ref, p_unlock_method) ON CONFLICT DO NOTHING;
    RETURN jsonb_build_object(
      'success', true, 'type', v_type, 'avatar_id', v_ref, 'permanent', true
    );
  END IF;

  RETURN jsonb_build_object('success', false, 'error', 'unfulfillable_item');
END;
$$;


ALTER FUNCTION public.sp_grant_shop_item(p_user_id uuid, p_item_id uuid, p_unlock_method text) OWNER TO postgres;

--
-- TOC entry 3434 (class 1255 OID 17204240)
-- Name: sp_grant_theme_preset(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_grant_theme_preset(p_user_id uuid, p_theme_id text, p_unlock_method text DEFAULT 'grant'::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_preset public.theme_preset_catalog%ROWTYPE;
BEGIN
  SELECT p.* INTO v_preset
    FROM public.theme_preset_catalog p
   WHERE p.theme_id = public.sp_resolve_theme_preset(p_theme_id);
  IF v_preset.theme_id IS NULL THEN RETURN NULL; END IF;

  INSERT INTO public.theme_asset_unlocks (user_id, category, asset_id, unlock_method)
  VALUES
    (p_user_id, 'theme_id',      v_preset.theme_id,      p_unlock_method),
    (p_user_id, 'table_id',      v_preset.table_id,      p_unlock_method),
    (p_user_id, 'button_id',     v_preset.button_id,     p_unlock_method),
    (p_user_id, 'background_id', v_preset.background_id, p_unlock_method),
    (p_user_id, 'cards_id',      v_preset.cards_id,      p_unlock_method),
    (p_user_id, 'face_deck_id',  v_preset.face_deck_id,  p_unlock_method)
  ON CONFLICT DO NOTHING;

  INSERT INTO public.theme_unlocks (user_id, theme_id, unlock_method)
  VALUES (p_user_id, v_preset.theme_id, p_unlock_method)
  ON CONFLICT (user_id, theme_id) DO NOTHING;

  RETURN v_preset.theme_id;
END;
$$;


ALTER FUNCTION public.sp_grant_theme_preset(p_user_id uuid, p_theme_id text, p_unlock_method text) OWNER TO postgres;

--
-- TOC entry 5412 (class 1255 OID 15851398)
-- Name: sp_guard_avatar_cosmetics(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_guard_avatar_cosmetics() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_owner uuid;
BEGIN
  IF TG_TABLE_NAME = 'profiles' THEN
    v_owner := NEW.id;
  ELSE
    v_owner := NEW.user_id;
  END IF;

  IF NEW.equipped_frame IS DISTINCT FROM (CASE WHEN TG_OP = 'UPDATE' THEN OLD.equipped_frame ELSE NULL END)
     AND NEW.equipped_frame IS NOT NULL THEN
    IF NOT public.sp_cosmetic_is_owned(v_owner, NEW.equipped_frame, 'frame') THEN
      RAISE EXCEPTION
        'equipped_frame % is not owned by % (or is not a known frame)',
        NEW.equipped_frame, v_owner
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.equipped_aura IS DISTINCT FROM (CASE WHEN TG_OP = 'UPDATE' THEN OLD.equipped_aura ELSE NULL END)
     AND NEW.equipped_aura IS NOT NULL THEN
    IF NOT public.sp_cosmetic_is_owned(v_owner, NEW.equipped_aura, 'aura') THEN
      RAISE EXCEPTION
        'equipped_aura % is not owned by % (or is not a known aura)',
        NEW.equipped_aura, v_owner
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


