--
-- TOC entry 4867 (class 1255 OID 125413531)
-- Name: sp_prune_horse_hand_review_receipts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_prune_horse_hand_review_receipts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_n integer;
BEGIN
  -- At most 25,000 per call, oldest first, and only once the receipt's UTC
  -- rollup_day is more than 32 days old AND its review row is gone.
  -- fn_hhr_record_atomic refuses to apply a hand played more than 30 days
  -- ago, so no resend can ever need a receipt removed here.
  DELETE FROM public.horse_hand_review_receipts r
   USING (SELECT c.hand_id, c.horse_user_id
            FROM public.horse_hand_review_receipts c
           WHERE c.rollup_day < (pg_catalog.now() AT TIME ZONE 'UTC')::date - 32
             AND NOT EXISTS (SELECT 1 FROM public.horse_hand_reviews v
                              WHERE v.hand_id = c.hand_id
                                AND v.horse_user_id = c.horse_user_id)
           ORDER BY c.rollup_day
           LIMIT 25000) old
   WHERE r.hand_id = old.hand_id AND r.horse_user_id = old.horse_user_id;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $$;


ALTER FUNCTION public.sp_prune_horse_hand_review_receipts() OWNER TO postgres;

--
-- TOC entry 50532 (class 0 OID 0)
-- Dependencies: 4867
-- Name: FUNCTION sp_prune_horse_hand_review_receipts(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.sp_prune_horse_hand_review_receipts() IS 'Bounded retention for public.horse_hand_review_receipts: deletes at most 25,000 receipts per call, oldest rollup_day first, only where rollup_day is more than 32 UTC days old and the review row is gone. Returns the number deleted. Called by the engine right after sp_prune_horse_hand_reviews, in its own statement. service_role only.';


--
-- TOC entry 3837 (class 1255 OID 16133993)
-- Name: sp_prune_horse_hand_reviews(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_prune_horse_hand_reviews() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n int; m int; k int; j int;
begin
  PERFORM smarter_private.compact_horse_review_raw(ARRAY(SELECT c.hand_id FROM smarter_private.horse_adaptive_disposal_certificates c JOIN public.horse_hand_reviews r ON r.hand_id=c.hand_id WHERE (r.hole_cards IS NOT NULL OR r.board IS NOT NULL OR r.actions IS NOT NULL) AND smarter_private.horse_review_raw_disposable(r.hand_id,r.table_id,r.played_at) ORDER BY c.qualified_at LIMIT 250));
  delete from horse_hand_reviews r where id IN (SELECT h.id FROM smarter_private.horse_adaptive_disposal_certificates c JOIN public.horse_hand_reviews h ON h.hand_id=c.hand_id WHERE h.created_at < now() - interval '30 days' AND smarter_private.horse_review_raw_disposable(h.hand_id,h.table_id,h.played_at) ORDER BY c.qualified_at,h.id LIMIT 250);
  get diagnostics n = row_count;
  delete from horse_daily_nets where day < current_date - 180;
  get diagnostics m = row_count;
  delete from horse_daily_play where day < current_date - 180;
  get diagnostics k = row_count;
  delete from horse_tournament_daily where day < current_date - 180;
  get diagnostics j = row_count;
  return n + m + k + j;
end $$;


ALTER FUNCTION public.sp_prune_horse_hand_reviews() OWNER TO postgres;

