--
-- TOC entry 8594 (class 1255 OID 199299224)
-- Name: tr_hand_history_royal_flush_achievement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tr_hand_history_royal_flush_achievement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
    r record;
BEGIN
    -- An achievement can never fail the hand that earned it: nothing in here
    -- escapes, and each player is settled in a savepoint of their own.
    BEGIN
        IF jsonb_typeof(NEW.daily_mission_events) IS DISTINCT FROM 'array' THEN
            RETURN NULL;
        END IF;
        -- strong_hands is the strongest hand that WON this player a pot
        -- (server/src/engine/dailyMissionEvents.ts): 10 is a Royal Flush.
        -- Every dealt player is in the list, horses included (CLAUDE.md 10.5).
        FOR r IN
            SELECT DISTINCT u #>> '{}' AS user_id
              FROM jsonb_path_query(NEW.daily_mission_events,
                                    '$[*] ? (@.magnitudes.strong_hands == 10).user_id') AS u
        LOOP
            IF r.user_id IS NULL
               OR r.user_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
                CONTINUE;
            END IF;
            BEGIN
                PERFORM public.fn_achievement_unlock_server(
                    r.user_id::uuid, 'royal_flush', 1,
                    jsonb_build_object('hand_id', NEW.id, 'table_id', NEW.table_id,
                                       'hand_number', NEW.hand_number));
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'royal flush achievement for % in hand % not recorded: % (%)',
                    r.user_id, NEW.id, SQLERRM, SQLSTATE;
            END;
        END LOOP;
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'royal flush achievements for hand % not read: % (%)', NEW.id, SQLERRM, SQLSTATE;
    END;
    RETURN NULL;
END
$_$;


ALTER FUNCTION public.tr_hand_history_royal_flush_achievement() OWNER TO postgres;

--
-- TOC entry 3696 (class 1255 OID 201719687)
-- Name: tr_hand_history_straight_flush_quads_achievements(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tr_hand_history_straight_flush_quads_achievements() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
    r record;
BEGIN
    -- An achievement can never fail the hand that earned it: nothing in here
    -- escapes, and each player is settled in a savepoint of their own.
    BEGIN
        IF jsonb_typeof(NEW.daily_mission_events) IS DISTINCT FROM 'array' THEN
            RETURN NULL;
        END IF;
        -- strong_hands is the strongest hand that WON this player a pot
        -- (server/src/engine/dailyMissionEvents.ts): 9 Straight Flush,
        -- 8 Four Of A Kind. 10 (Royal Flush) is the Royal Flush trigger's.
        -- Every dealt player is in the list, horses included (CLAUDE.md 10.5).
        -- A non-numeric value never passes the jsonpath comparison.
        FOR r IN
            SELECT DISTINCT
                   e ->> 'user_id' AS user_id,
                   CASE (e #>> '{magnitudes,strong_hands}')::numeric
                        WHEN 9 THEN 'straight_flush'
                        WHEN 8 THEN 'quads'
                   END AS achievement_id
              FROM jsonb_path_query(NEW.daily_mission_events,
                                    '$[*] ? (@.magnitudes.strong_hands == 9 || @.magnitudes.strong_hands == 8)') AS e
             WHERE jsonb_typeof(e -> 'user_id') = 'string'
        LOOP
            IF r.achievement_id IS NULL
               OR r.user_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
                CONTINUE;
            END IF;
            BEGIN
                PERFORM public.fn_achievement_unlock_server(
                    r.user_id::uuid, r.achievement_id, 1,
                    jsonb_build_object('hand_id', NEW.id, 'table_id', NEW.table_id,
                                       'hand_number', NEW.hand_number));
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING '% achievement for % in hand % not recorded: % (%)',
                    r.achievement_id, r.user_id, NEW.id, SQLERRM, SQLSTATE;
            END;
        END LOOP;
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'straight flush / quads achievements for hand % not read: % (%)', NEW.id, SQLERRM, SQLSTATE;
    END;
    RETURN NULL;
END
$_$;


ALTER FUNCTION public.tr_hand_history_straight_flush_quads_achievements() OWNER TO postgres;

--
-- TOC entry 50602 (class 0 OID 0)
-- Dependencies: 3696
-- Name: FUNCTION tr_hand_history_straight_flush_quads_achievements(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.tr_hand_history_straight_flush_quads_achievements() IS 'AFTER INSERT on hand_history: records straight_flush (strong_hands 9) and quads (8) through fn_achievement_unlock_server for every player whose winning hand the engine recorded, horses included. Zero-reward badges. Royal Flush (10) is tr_hand_history_royal_flush_achievement''s. Never fails the hand. Added 2026-10-20.';


