--
-- TOC entry 7621 (class 1255 OID 26851267)
-- Name: training_solver_worker_row_states_v1(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.training_solver_worker_row_states_v1(p_scenario_hashes text[]) RETURNS TABLE(id uuid, scenario_hash text, game_type text, stack_depth integer, street text, node text, hero_position text, solved_v2_at timestamp with time zone, quality_status text, solver_version text, solver_binary_checksum text, machine_id text, pipeline_commit text, manifest_version text, manifest_checksum text, source_artifact_checksum text, audited_at timestamp with time zone, admitted boolean)
    LANGUAGE sql STABLE SECURITY DEFINER ROWS 150
    SET search_path TO 'pg_catalog'
    AS $$
  WITH requested AS MATERIALIZED (
    SELECT DISTINCT requested_hash.value AS scenario_hash
    FROM unnest(
      CASE
        WHEN cardinality(p_scenario_hashes) BETWEEN 1 AND 75
        THEN p_scenario_hashes
        ELSE ARRAY[]::text[]
      END
    ) AS requested_hash(value)
    WHERE char_length(requested_hash.value) BETWEEN 1 AND 512
  )
  SELECT
    artifact.id,
    artifact.scenario_hash,
    artifact.game_type,
    artifact.stack_depth,
    artifact.street,
    artifact.strategy_matrix_v2 ->> 'node' AS node,
    artifact.strategy_matrix_v2 ->> 'position' AS hero_position,
    artifact.solved_v2_at,
    artifact.quality_status,
    artifact.solver_version,
    artifact.solver_binary_checksum,
    artifact.machine_id,
    artifact.pipeline_commit,
    artifact.manifest_version,
    artifact.manifest_checksum,
    artifact.source_artifact_checksum,
    artifact.audited_at,
    EXISTS (
      SELECT 1
      FROM public.training_solver_artifact_catalog catalog
      JOIN public.training_solver_provenance_authority authority
        ON authority.machine_id = artifact.machine_id
       AND authority.solver_version = artifact.solver_version
       AND authority.solver_binary_checksum = artifact.solver_binary_checksum
       AND authority.pipeline_commit = artifact.pipeline_commit
       AND authority.manifest_version = artifact.manifest_version
       AND authority.manifest_checksum = artifact.manifest_checksum
       AND authority.source_combo_order_sha256 =
         artifact.strategy_matrix_v2 ->> 'source_combo_order_sha256'
       AND authority.training_game_contracts_sha256 =
         artifact.strategy_matrix_v2 ->> 'training_game_contracts_sha256'
       AND authority.retired_at IS NULL
      WHERE catalog.artifact_id = artifact.id
        AND catalog.scenario_hash = artifact.scenario_hash
        AND catalog.game_type = artifact.game_type
        AND catalog.stack_depth = artifact.stack_depth
        AND catalog.street = artifact.street
        AND catalog.hero_position = artifact.strategy_matrix_v2 ->> 'position'
    ) AS admitted
  FROM requested
  JOIN public.solved_spots_gold artifact
    ON artifact.scenario_hash = requested.scenario_hash
  ORDER BY artifact.scenario_hash, artifact.id
  LIMIT 150
$$;


ALTER FUNCTION public.training_solver_worker_row_states_v1(p_scenario_hashes text[]) OWNER TO postgres;

--
-- TOC entry 6770 (class 1255 OID 26851268)
-- Name: training_solver_worker_row_states_v2(text, text, text, text, text, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.training_solver_worker_row_states_v2(p_machine_id text, p_solver_version text, p_solver_binary_checksum text, p_pipeline_commit text, p_manifest_version text, p_manifest_checksum text, p_scenario_hashes text[]) RETURNS TABLE(id uuid, scenario_hash text, game_type text, stack_depth integer, street text, node text, hero_position text, solved_v2_at timestamp with time zone, quality_status text, solver_version text, solver_binary_checksum text, machine_id text, pipeline_commit text, manifest_version text, manifest_checksum text, source_artifact_checksum text, audited_at timestamp with time zone, admitted boolean, admission_mode text, partition_count integer, partition_index integer, canary_target_role text, authorized_node text, authorized_hero_position text, canary_authorized boolean)
    LANGUAGE sql STABLE SECURITY DEFINER ROWS 150
    SET search_path TO 'pg_catalog'
    AS $$
  WITH caller_scope AS MATERIALIZED (
    SELECT scope.*
    FROM public.training_solver_ingest_scopes scope
    JOIN public.training_solver_provenance_authority authority
      ON authority.machine_id = scope.machine_id
     AND authority.solver_version = scope.solver_version
     AND authority.solver_binary_checksum = scope.solver_binary_checksum
     AND authority.pipeline_commit = scope.pipeline_commit
     AND authority.manifest_version = scope.manifest_version
     AND authority.manifest_checksum = scope.manifest_checksum
     AND authority.retired_at IS NULL
    WHERE scope.machine_id = p_machine_id
      AND scope.solver_version = p_solver_version
      AND scope.solver_binary_checksum = p_solver_binary_checksum
      AND scope.pipeline_commit = p_pipeline_commit
      AND scope.manifest_version = p_manifest_version
      AND scope.manifest_checksum = p_manifest_checksum
  ), target_count AS MATERIALIZED (
    SELECT count(*)::integer AS value
    FROM public.training_solver_bounded_canary_targets target
    JOIN caller_scope scope
      ON scope.machine_id = target.machine_id
     AND scope.solver_version = target.solver_version
     AND scope.solver_binary_checksum = target.solver_binary_checksum
     AND scope.pipeline_commit = target.pipeline_commit
     AND scope.manifest_version = target.manifest_version
     AND scope.manifest_checksum = target.manifest_checksum
  ), row_state AS MATERIALIZED (
    SELECT *
    FROM public.training_solver_worker_row_states_v1(p_scenario_hashes)
  )
  SELECT
    row_state.id, row_state.scenario_hash, row_state.game_type,
    row_state.stack_depth, row_state.street, row_state.node,
    row_state.hero_position, row_state.solved_v2_at,
    row_state.quality_status, row_state.solver_version,
    row_state.solver_binary_checksum, row_state.machine_id,
    row_state.pipeline_commit, row_state.manifest_version,
    row_state.manifest_checksum, row_state.source_artifact_checksum,
    row_state.audited_at, row_state.admitted,
    scope.admission_mode, scope.partition_count, scope.partition_index,
    target.target_role, target.node, target.hero_position,
    coalesce(
      scope.admission_mode = 'bounded_canary'
      AND target_count.value = 2
      AND target.target_role IN ('parent', 'child'),
      false
    ) AS canary_authorized
  FROM row_state
  LEFT JOIN caller_scope scope ON true
  LEFT JOIN target_count ON true
  LEFT JOIN public.training_solver_bounded_canary_targets target
    ON target.machine_id = scope.machine_id
   AND target.solver_version = scope.solver_version
   AND target.solver_binary_checksum = scope.solver_binary_checksum
   AND target.pipeline_commit = scope.pipeline_commit
   AND target.manifest_version = scope.manifest_version
   AND target.manifest_checksum = scope.manifest_checksum
   AND target.artifact_id = row_state.id
   AND target.scenario_hash = row_state.scenario_hash
   AND target.street = row_state.street
  ORDER BY row_state.scenario_hash, row_state.id
  LIMIT 150
$$;


ALTER FUNCTION public.training_solver_worker_row_states_v2(p_machine_id text, p_solver_version text, p_solver_binary_checksum text, p_pipeline_commit text, p_manifest_version text, p_manifest_checksum text, p_scenario_hashes text[]) OWNER TO postgres;

--
-- TOC entry 4353 (class 1255 OID 32284448)
-- Name: training_solver_worker_row_states_v3(text, text, text, text, text, text, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.training_solver_worker_row_states_v3(p_machine_id text, p_solver_version text, p_solver_binary_checksum text, p_pipeline_commit text, p_manifest_version text, p_manifest_checksum text, p_expected_admission_mode text, p_scenario_hashes text[]) RETURNS TABLE(id uuid, scenario_hash text, game_type text, stack_depth integer, street text, node text, hero_position text, solved_v2_at timestamp with time zone, quality_status text, solver_version text, solver_binary_checksum text, machine_id text, pipeline_commit text, manifest_version text, manifest_checksum text, source_artifact_checksum text, audited_at timestamp with time zone, admitted boolean, admission_mode text, partition_count integer, partition_index integer, canary_target_role text, authorized_node text, authorized_hero_position text, canary_authorized boolean)
    LANGUAGE plpgsql SECURITY DEFINER ROWS 150
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_requested_hashes text[];
  v_target_hashes text[];
BEGIN
  PERFORM public.fn_training_solver_operation_scope_guard_v1(
    p_machine_id, p_solver_version, p_solver_binary_checksum,
    p_pipeline_commit, p_manifest_version, p_manifest_checksum,
    p_expected_admission_mode
  );

  -- Reject malformed or oversized requests before aggregating or touching the
  -- warehouse. The predecessor RPC bounded its query, but a canary request
  -- must not be able to make this wrapper aggregate an unbounded array first.
  IF p_scenario_hashes IS NULL
     OR cardinality(p_scenario_hashes) NOT BETWEEN 1 AND 75
     OR EXISTS (
       SELECT 1
       FROM unnest(p_scenario_hashes) requested_hash(value)
       WHERE requested_hash.value IS NULL
          OR char_length(requested_hash.value) NOT BETWEEN 1 AND 512
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023', MESSAGE = 'SOLVER_WORKER_ROW_STATES_PAYLOAD_INVALID';
  END IF;

  IF p_expected_admission_mode = 'bounded_canary' THEN
    IF cardinality(p_scenario_hashes) IS DISTINCT FROM 2 THEN
      RAISE EXCEPTION USING
        ERRCODE = '42501', MESSAGE = 'SOLVER_WORKER_CANARY_ROW_STATES_NOT_AUTHORIZED';
    END IF;
    SELECT array_agg(requested.scenario_hash ORDER BY requested.scenario_hash)
    INTO v_requested_hashes
    FROM (
      SELECT DISTINCT requested_hash.value AS scenario_hash
      FROM unnest(p_scenario_hashes) requested_hash(value)
      WHERE requested_hash.value IS NOT NULL
    ) requested;

    SELECT array_agg(locked_target.scenario_hash ORDER BY locked_target.scenario_hash)
    INTO v_target_hashes
    FROM (
      SELECT target.scenario_hash
      FROM public.training_solver_bounded_canary_targets target
      WHERE target.machine_id = p_machine_id
        AND target.solver_version = p_solver_version
        AND target.solver_binary_checksum = p_solver_binary_checksum
        AND target.pipeline_commit = p_pipeline_commit
        AND target.manifest_version = p_manifest_version
        AND target.manifest_checksum = p_manifest_checksum
      ORDER BY target.scenario_hash
      FOR SHARE OF target
    ) locked_target;

    IF cardinality(v_requested_hashes) IS DISTINCT FROM 2
       OR cardinality(v_target_hashes) IS DISTINCT FROM 2
       OR v_requested_hashes IS DISTINCT FROM v_target_hashes THEN
      RAISE EXCEPTION USING
        ERRCODE = '42501', MESSAGE = 'SOLVER_WORKER_CANARY_ROW_STATES_NOT_AUTHORIZED';
    END IF;
  END IF;

  RETURN QUERY
  SELECT state.*
  FROM public.training_solver_worker_row_states_v2(
    p_machine_id, p_solver_version, p_solver_binary_checksum,
    p_pipeline_commit, p_manifest_version, p_manifest_checksum,
    p_scenario_hashes
  ) state;
END;
$$;


ALTER FUNCTION public.training_solver_worker_row_states_v3(p_machine_id text, p_solver_version text, p_solver_binary_checksum text, p_pipeline_commit text, p_manifest_version text, p_manifest_checksum text, p_expected_admission_mode text, p_scenario_hashes text[]) OWNER TO postgres;

--
-- TOC entry 4462 (class 1255 OID 2344908)
-- Name: transfer_club_ownership(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_club_ownership(p_club_id uuid, p_new_owner_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_old UUID;
  v_actor UUID;
  v_club_name text;
BEGIN
  v_actor := auth.uid();

  SELECT owner_id, name INTO v_old, v_club_name FROM clubs WHERE id = p_club_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Club not found';
  END IF;

  -- A JWT caller must BE the current owner. service_role callers (auth.uid()
  -- NULL) are trusted to have authorized upstream.
  IF v_actor IS NOT NULL AND v_actor <> v_old THEN
    RAISE EXCEPTION 'Only the current club owner can transfer ownership';
  END IF;

  IF p_new_owner_id = v_old THEN
    RAISE EXCEPTION 'That user already owns this club';
  END IF;

  -- Recipient must be an active member of this club.
  IF NOT EXISTS (
    SELECT 1 FROM club_members
     WHERE club_id = p_club_id AND user_id = p_new_owner_id
       AND status IN ('active','approved')
  ) THEN
    RAISE EXCEPTION 'New owner must be an active member of this club';
  END IF;

  UPDATE clubs SET owner_id = p_new_owner_id, updated_at = NOW() WHERE id = p_club_id;
  UPDATE club_members SET role = 'admin', updated_at = NOW()
   WHERE club_id = p_club_id AND user_id = v_old;
  UPDATE club_members SET role = 'owner', updated_at = NOW()
   WHERE club_id = p_club_id AND user_id = p_new_owner_id;

  -- THE RECORD. This used to insert a role_changes row with member_id NULL -
  -- the column that says WHO - inside EXCEPTION WHEN OTHERS THEN NULL, so a
  -- failed insert meant a club changed hands leaving no trace. Both rows are
  -- complete now, and neither is swallowed: a handover that cannot be recorded
  -- does not happen.
  INSERT INTO role_changes (member_id, old_role, new_role, changed_by, reason)
  VALUES (p_new_owner_id, 'admin', 'owner', COALESCE(v_actor, v_old),
          'Club ownership transferred');
  INSERT INTO role_changes (member_id, old_role, new_role, changed_by, reason)
  VALUES (v_old, 'owner', 'admin', COALESCE(v_actor, v_old),
          'Club ownership transferred');

  INSERT INTO audit_trail (actor_id, actor_role, action, target_type, target_id,
                           club_id, before_state, after_state, reason)
  VALUES (COALESCE(v_actor, v_old), 'owner', 'transfer_club_ownership',
          'club', p_club_id, p_club_id,
          jsonb_build_object('owner_id', v_old),
          jsonb_build_object('owner_id', p_new_owner_id, 'previous_owner_role', 'admin'),
          'Club ownership transferred');

  -- Both people are told. The outgoing owner is no longer an owner, which is
  -- the kind of thing somebody should hear from the club rather than notice.
  BEGIN
    PERFORM public.fn_raise_notification(
      p_new_owner_id, 'club_ownership_transferred',
      'You Now Own ' || COALESCE(v_club_name, 'A Club'),
      'Ownership Was Transferred To You. You Now Hold Every Permission In This Club.',
      '/clubs/' || p_club_id::text,
      jsonb_build_object('club_id', p_club_id, 'previous_owner', v_old));
    PERFORM public.fn_raise_notification(
      v_old, 'club_ownership_transferred',
      'You Handed Over ' || COALESCE(v_club_name, 'Your Club'),
      'Ownership Has Moved To Another Member. You Are Now An Admin Of This Club.',
      '/clubs/' || p_club_id::text,
      jsonb_build_object('club_id', p_club_id, 'new_owner', p_new_owner_id));
  EXCEPTION WHEN OTHERS THEN
    NULL;  -- the handover is done and recorded; the notice is a courtesy
  END;
END;
$$;


ALTER FUNCTION public.transfer_club_ownership(p_club_id uuid, p_new_owner_id uuid) OWNER TO postgres;

--
-- TOC entry 4147 (class 1255 OID 4631831)
-- Name: transfer_home_group_ownership(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transfer_home_group_ownership(p_group_id uuid, p_new_owner_user_id uuid, p_caller_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_group          RECORD;
    v_target_member  RECORD;
    v_old_owner      uuid;
BEGIN
    IF auth.uid() IS NULL OR (auth.uid() <> p_caller_user_id) THEN
        RAISE EXCEPTION 'UNAUTHORIZED';
    END IF;

    SELECT * INTO v_group FROM commander_home_groups WHERE id = p_group_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'GROUP_NOT_FOUND'; END IF;

    IF v_group.owner_id <> p_caller_user_id THEN
        RAISE EXCEPTION 'OWNER_ONLY_ACTION';
    END IF;
    IF v_group.owner_id = p_new_owner_user_id THEN
        RAISE EXCEPTION 'ALREADY_OWNER';
    END IF;

    SELECT * INTO v_target_member
      FROM commander_home_members
     WHERE group_id = p_group_id AND user_id = p_new_owner_user_id;

    IF NOT FOUND THEN RAISE EXCEPTION 'TARGET_NOT_MEMBER'; END IF;
    IF v_target_member.status <> 'approved' THEN RAISE EXCEPTION 'TARGET_NOT_APPROVED'; END IF;
    IF v_target_member.role <> 'admin' THEN
        RAISE EXCEPTION 'TARGET_NOT_ADMIN'
              USING HINT = 'promote to admin first, then transfer';
    END IF;

    v_old_owner := v_group.owner_id;

    UPDATE commander_home_groups
       SET owner_id = p_new_owner_user_id, updated_at = NOW()
     WHERE id = p_group_id;

    UPDATE commander_home_members
       SET role = 'admin'
     WHERE group_id = p_group_id AND user_id = v_old_owner;

    UPDATE commander_home_members
       SET role = 'owner'
     WHERE group_id = p_group_id AND user_id = p_new_owner_user_id;

    INSERT INTO commander_home_audit_log
      (group_id, actor_id, target_type, target_id, action, metadata)
    VALUES (p_group_id, p_caller_user_id, 'group', p_group_id, 'ownership_transferred',
            jsonb_build_object('from_user', v_old_owner, 'to_user', p_new_owner_user_id));

    -- ★ NEW: notify the new owner
    BEGIN
      PERFORM public.fn_emit_home_notification(
        p_user_id     => p_new_owner_user_id,
        p_type        => 'home_group_ownership_transferred',
        p_title       => 'You''re the new owner',
        p_message     => 'Ownership of ' || COALESCE(v_group.name, 'a group') ||
                         ' was transferred to you.',
        p_link        => '/hub/home-games/group/' || p_group_id::text,
        p_data        => jsonb_build_object(
                           'group_id',        p_group_id,
                           'previous_owner',  v_old_owner),
        p_pref_column => NULL
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'ownership-transfer notify failed: %', SQLERRM;
    END;

    RETURN jsonb_build_object(
        'success', true,
        'group_id', p_group_id,
        'previous_owner', v_old_owner,
        'new_owner', p_new_owner_user_id
    );
END;
$$;


ALTER FUNCTION public.transfer_home_group_ownership(p_group_id uuid, p_new_owner_user_id uuid, p_caller_user_id uuid) OWNER TO postgres;

