-- TOC entry 6523 (class 1255 OID 21365947)
-- Name: trg_ca_club_rake_daily_user_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_ca_club_rake_daily_user_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
