--
-- TOC entry 4784 (class 1255 OID 217933202)
-- Name: trg_ca_notify_tournament_cash(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_ca_notify_tournament_cash() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_t record;
  v_target text;
  v_diamond boolean;
  v_unit text;
  v_amount_text text;
  v_title text;
  v_message text;
BEGIN
  -- Exactly once: the moment the obligation becomes fully paid.
  IF NEW.settled_at IS NULL OR NEW.user_id IS NULL
     OR COALESCE(NEW.amount_paid,0) <= 0
     OR NEW.kind NOT IN ('place','bubble_protection','satellite_remainder','seat') THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.settled_at IS NOT NULL THEN
    RETURN NULL;
  END IF;

  /* A notice can never cost a player their money: it runs in its own
     subtransaction and a failure is a warning, never a rollback of the
     payment that triggered it. */
  BEGIN
    IF EXISTS (SELECT 1 FROM public.notifications n
                WHERE n.user_id = NEW.user_id
                  AND n.type = 'tournament_cash'
                  AND n.data->>'obligation_id' = NEW.id::text) THEN
      RETURN NULL;
    END IF;

    SELECT t.id, t.name, t.satellite_target_id INTO v_t
      FROM public.tournaments t WHERE t.id = NEW.tournament_id;
    IF NOT FOUND THEN
      RETURN NULL;
    END IF;
    v_diamond := public.fn_poker_diamond_tournament(NEW.tournament_id);
    v_unit := CASE WHEN v_diamond THEN 'Diamonds' ELSE 'Chips' END;
    v_amount_text := CASE WHEN v_diamond
      THEN to_char(round(NEW.amount_paid), 'FM999,999,999,990')
      ELSE to_char(NEW.amount_paid, 'FM999,999,999,990.00') END;

    IF NEW.kind = 'seat' THEN
      SELECT x.name INTO v_target FROM public.tournaments x WHERE x.id = v_t.satellite_target_id;
      v_title := 'You Won A Seat';
      v_message := format('You Won A Seat To %s From %s.',
        COALESCE(v_target, 'The Target Event'), COALESCE(v_t.name, 'Your Satellite'));
    ELSIF NEW.kind = 'bubble_protection' THEN
      v_title := 'Bubble Protection Paid';
      v_message := format('Your Buy-In Of %s %s From %s Is Back In Your Wallet.',
        v_amount_text, v_unit, COALESCE(v_t.name, 'Your Tournament'));
    ELSIF NEW.kind = 'satellite_remainder' THEN
      v_title := 'Satellite Cash Paid';
      v_message := format('You Won %s %s In %s. It Is Already In Your Wallet.',
        v_amount_text, v_unit, COALESCE(v_t.name, 'Your Satellite'));
    ELSIF NEW.place = 1 THEN
      v_title := 'You Won The Tournament';
      v_message := format('You Won %s %s For First Place In %s. It Is Already In Your Wallet.',
        v_amount_text, v_unit, COALESCE(v_t.name, 'Your Tournament'));
    ELSE
      v_title := format('You Finished %s', public.fn_ca_ordinal(NEW.place));
      v_message := format('You Won %s %s For %s Place In %s. It Is Already In Your Wallet.',
        v_amount_text, v_unit, public.fn_ca_ordinal(NEW.place), COALESCE(v_t.name, 'Your Tournament'));
    END IF;

    INSERT INTO public.notifications(user_id, type, title, message, data, link)
    VALUES (NEW.user_id, 'tournament_cash', v_title, v_message,
      jsonb_build_object(
        'obligation_id', NEW.id,
        'tournament_id', NEW.tournament_id,
        'kind', NEW.kind,
        'place', NEW.place,
        'amount', NEW.amount_paid,
        'asset', CASE WHEN v_diamond THEN 'diamonds' ELSE 'chips' END),
      '/hub/club-arena/tournaments/' || NEW.tournament_id::text);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'tournament cash notice for obligation % failed: %', NEW.id, SQLERRM;
  END;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.trg_ca_notify_tournament_cash() OWNER TO postgres;

--
-- TOC entry 5945 (class 1255 OID 217357289)
-- Name: trg_ca_pay_tournament_finishers_at_commit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_ca_pay_tournament_finishers_at_commit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tournament_id uuid;
  v_flag text;
  v_result jsonb;
  v_state text;
  v_message text;
  v_attempt integer := 0;
BEGIN
  IF TG_TABLE_NAME = 'tournaments' THEN
    v_tournament_id := NEW.id;
  ELSE
    v_tournament_id := NEW.tournament_id;
  END IF;
  IF v_tournament_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Deferred triggers fire at COMMIT after every row is written, so one call
  -- per tournament per transaction sees the whole batch.
  v_flag := 'ca_instant_pay.t' || replace(v_tournament_id::text, '-', '');
  IF current_setting(v_flag, true) = 'done' THEN
    RETURN NULL;
  END IF;
  PERFORM set_config(v_flag, 'done', true);

  /* A DEADLOCK IS NEVER RETRIED HERE (2026-10-22). Measured at 06:11:38 UTC:
     every retry of a deadlocked payment deadlocked again, four times, 1 s
     each, because the other member of the cycle waits on a lock this
     transaction holds at top level (its tournaments row, or its hand
     settlement's shared tournament lane), which no subtransaction can give
     back. Retrying only held the hand commit four seconds longer. The partner
     proceeds the moment this transaction commits; a partner that is another
     bust's payer reads the committed bust and pays it, and otherwise the next
     bust or the terminal settlement does. A lock timeout or serialization
     failure is not a cycle, so those still retry. */
  LOOP
    v_attempt := v_attempt + 1;
    BEGIN
      v_result := public.fn_ca_pay_tournament_finishers_now(v_tournament_id);
      EXIT;
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      v_result := jsonb_build_object('ok', false, 'sqlstate', v_state,
                                     'error', v_message, 'attempts', v_attempt);
      EXIT WHEN v_state NOT IN ('55P03', '40001') OR v_attempt >= 4;
      PERFORM pg_sleep(0.05 * v_attempt);
    END;
  END LOOP;

  IF COALESCE((v_result->>'ok')::boolean, false) IS NOT TRUE THEN
    -- The bust stays recorded and the terminal settlement still pays the
    -- place; this says, once per event, that it was not paid at the bust.
    INSERT INTO public.financial_alerts(severity, source, message, context)
    SELECT 'warning', 'tournament.real_time_payout_refused',
           'A finisher was not paid at the moment of the bust; the terminal settlement will pay the place.',
           jsonb_build_object('tournament_id', v_tournament_id, 'result', v_result)
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source = 'tournament.real_time_payout_refused'
          AND NOT fa.resolved
          AND fa.context->>'tournament_id' = v_tournament_id::text);
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.trg_ca_pay_tournament_finishers_at_commit() OWNER TO postgres;

--
-- TOC entry 6798 (class 1255 OID 218103509)
-- Name: trg_ca_refresh_provisional_payout_structure(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_ca_refresh_provisional_payout_structure() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    FOR v_id IN SELECT DISTINCT n.tournament_id FROM new_rows n WHERE n.tournament_id IS NOT NULL LOOP
      -- A display refresh can never cost a player their entry.
      BEGIN
        PERFORM public.fn_ca_refresh_provisional_payout_structure(v_id);
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'provisional payout ladder refresh for % failed: %', v_id, SQLERRM;
      END;
    END LOOP;
  ELSE
    FOR v_id IN SELECT DISTINCT o.tournament_id FROM old_rows o WHERE o.tournament_id IS NOT NULL LOOP
      -- A display refresh can never cost a player their entry.
      BEGIN
        PERFORM public.fn_ca_refresh_provisional_payout_structure(v_id);
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'provisional payout ladder refresh for % failed: %', v_id, SQLERRM;
      END;
    END LOOP;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.trg_ca_refresh_provisional_payout_structure() OWNER TO postgres;

--
-- TOC entry 6619 (class 1255 OID 25748075)
-- Name: trg_ca_reporting_follows_a_changed_fact(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_ca_reporting_follows_a_changed_fact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old date;
  v_new date;
BEGIN
  -- A rollup reads who, how much, which way, what kind, which table, which
  -- event and when. An UPDATE that changes none of those (a terminal marker,
  -- a note) has nothing to repair.
  IF TG_OP = 'UPDATE'
     AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id
     AND NEW.amount IS NOT DISTINCT FROM OLD.amount
     AND NEW.type IS NOT DISTINCT FROM OLD.type
     AND NEW.category IS NOT DISTINCT FROM OLD.category
     AND NEW.table_id IS NOT DISTINCT FROM OLD.table_id
     AND NEW.related_entity_id IS NOT DISTINCT FROM OLD.related_entity_id
     AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at THEN
    RETURN NULL;
  END IF;
  v_old := (OLD.created_at AT TIME ZONE 'UTC')::date;
  v_new := CASE WHEN TG_OP = 'UPDATE'
                THEN (NEW.created_at AT TIME ZONE 'UTC')::date ELSE v_old END;
  PERFORM public.ca_refresh_reporting_rollups(LEAST(v_old, v_new), GREATEST(v_old, v_new));
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Club Data changed-ledger repair failed on %: %', TG_TABLE_NAME, SQLERRM;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.trg_ca_reporting_follows_a_changed_fact() OWNER TO postgres;

--
-- TOC entry 6766 (class 1255 OID 17997342)
-- Name: trg_ca_reporting_rake_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_ca_reporting_rake_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_day date; r record; v_fee numeric;
BEGIN
  IF NEW.tournament_id IS NULL AND NOT COALESCE(NEW.is_tournament, false)
     AND NEW.table_id IS NOT NULL AND COALESCE(NEW.rake_amount, 0) > 0 THEN
    /* 2026-10-15: the live writer for cash. SHARED lock, like every other
       reporting trigger; only range rebuilds take it exclusive. */
    PERFORM pg_advisory_xact_lock_shared(918273645);
    PERFORM public.fn_ca_club_table_daily_add_rake(NEW.table_id, NEW.rake_amount, NEW.created_at, NEW.player_contributions);
    RETURN NULL;
  END IF;
  IF NOT NEW.is_tournament OR NEW.tournament_id IS NULL OR NEW.rake_amount=0
    THEN RETURN NULL; END IF;
  /* SHARED, not exclusive - see trg_ca_reporting_wallet_insert and
     20260906152215. */
  PERFORM pg_advisory_xact_lock_shared(918273645);
  v_day:=(NEW.created_at AT TIME ZONE 'UTC')::date;
  IF NEW.metadata ? 'user_id' THEN
    FOR r IN
      /* 20261017204111: the named player's entry club (one club). */
      SELECT x.club_id FROM (
        SELECT public.fn_ca_tournament_reporting_club(NEW.tournament_id,(NEW.metadata->>'user_id')::uuid,NULL,NULL,NULL) AS club_id
         WHERE (NEW.metadata->>'user_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') x
       WHERE x.club_id IS NOT NULL
    LOOP
      v_fee:=public.fn_ca_launch_reporting_fee_credit(r.club_id,NEW.id,NEW.created_at,NEW.metadata,NEW.rake_amount,NEW.rake_amount);
      IF v_fee=0 THEN CONTINUE; END IF;
      INSERT INTO public.ca_club_tournament_daily AS d
        (club_id,tournament_id,stat_date,fee,updated_at)
      VALUES(r.club_id,NEW.tournament_id,v_day,v_fee,now())
      ON CONFLICT(club_id,tournament_id,stat_date) DO UPDATE
       SET fee=d.fee+EXCLUDED.fee,updated_at=now();
    END LOOP;
  ELSE
    FOR r IN
      WITH total AS (SELECT count(*)::numeric n FROM public.tournament_players
                      WHERE tournament_id=NEW.tournament_id), mapped AS (
        /* 20261017204111: each entry under its own club, once. */
        SELECT public.fn_ca_tournament_reporting_club(tp.tournament_id,tp.user_id,NULL,NULL,NULL) AS club_id
          FROM public.tournament_players tp
         WHERE tp.tournament_id=NEW.tournament_id)
      SELECT m.club_id,count(*)::numeric AS club_players,t.n AS total_players
        FROM mapped m CROSS JOIN total t WHERE m.club_id IS NOT NULL GROUP BY m.club_id,t.n
       ORDER BY m.club_id
    LOOP
      v_fee:=public.fn_ca_launch_reporting_fee_credit(r.club_id,NEW.id,NEW.created_at,NEW.metadata,NEW.rake_amount,NEW.rake_amount*r.club_players/NULLIF(r.total_players,0));
      IF v_fee=0 THEN CONTINUE; END IF;
      INSERT INTO public.ca_club_tournament_daily AS d
        (club_id,tournament_id,stat_date,fee,updated_at)
      VALUES(r.club_id,NEW.tournament_id,v_day,
             v_fee,now())
      ON CONFLICT(club_id,tournament_id,stat_date) DO UPDATE
       SET fee=d.fee+EXCLUDED.fee,updated_at=now();
    END LOOP;
  END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Club Data rake rollup failed for row %: %',NEW.id,SQLERRM;
  RETURN NULL;
END;
$_$;


