--
-- TOC entry 4426 (class 1255 OID 17264863)
-- Name: trg_deliver_table_studio_entitlement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_deliver_table_studio_entitlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_category text;
  v_asset_id text;
  v_theme_id text;
BEGIN
  IF NEW.feature NOT LIKE 'studio:%' THEN RETURN NEW; END IF;

  v_category := split_part(NEW.feature, ':', 2);
  v_asset_id := substring(NEW.feature from length('studio:' || v_category || ':') + 1);

  IF v_category NOT IN (
       'theme_id', 'table_id', 'button_id', 'background_id', 'face_deck_id'
     )
     OR v_asset_id IS NULL OR btrim(v_asset_id) = ''
     OR NOT EXISTS (
       SELECT 1 FROM public.cosmetic_catalog c
        WHERE c.category = v_category AND c.asset_id = v_asset_id AND c.tier = 'vip'
     ) THEN
    RAISE EXCEPTION 'Invalid Table Studio entitlement SKU %', NEW.feature
      USING ERRCODE = '23514';
  END IF;

  IF v_category = 'theme_id' THEN
    v_theme_id := public.sp_grant_theme_preset(NEW.user_id, v_asset_id, 'diamond_purchase');
    IF v_theme_id IS NULL THEN
      RAISE EXCEPTION 'Table Studio preset % cannot be delivered', v_asset_id
        USING ERRCODE = '23514';
    END IF;
  ELSE
    INSERT INTO public.theme_asset_unlocks (user_id, category, asset_id, unlock_method)
    VALUES (NEW.user_id, v_category, v_asset_id, 'diamond_purchase')
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_deliver_table_studio_entitlement() OWNER TO postgres;

--
-- TOC entry 5718 (class 1255 OID 24465318)
-- Name: trg_entry_purchase_receipt_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_entry_purchase_receipt_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.response IS NOT NULL OR OLD.completed_at IS NOT NULL THEN
      RAISE EXCEPTION 'ENTRY_PURCHASE_RECEIPT_IMMUTABLE: completed receipts cannot be deleted'
        USING ERRCODE = '55000';
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.key_domain IS DISTINCT FROM NEW.key_domain
     OR OLD.idempotency_key IS DISTINCT FROM NEW.idempotency_key
     OR OLD.request IS DISTINCT FROM NEW.request
     OR OLD.claimed_at IS DISTINCT FROM NEW.claimed_at
     OR OLD.response IS NOT NULL
     OR NEW.response IS NULL
     OR NEW.completed_at IS NULL THEN
    RAISE EXCEPTION 'ENTRY_PURCHASE_RECEIPT_IMMUTABLE: only the first completion is allowed'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_entry_purchase_receipt_is_immutable() OWNER TO postgres;

--
-- TOC entry 8530 (class 1255 OID 16602243)
-- Name: trg_finalize_trivia_session_stats_v3(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_finalize_trivia_session_stats_v3() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    -- Engine v3 sessions record result events, history and mastery from their immutable
    -- snapshot revisions (trivia_p3_finalize_session); the legacy finalizer reads live keys.
    IF NEW.engine_version IS NOT NULL THEN
        RETURN NEW;
    END IF;
    IF NEW.settlement_result IS NOT NULL
       AND OLD.settlement_result IS NULL
       AND NEW.status = 'submitted' THEN
        SELECT public.finalize_trivia_session_stats_v3(NEW.id) INTO v_result;
        IF COALESCE((v_result->>'success')::boolean, false) IS NOT TRUE THEN
            RAISE EXCEPTION 'trivia stats finalization rejected: %',
                COALESCE(v_result->>'error', 'unknown');
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_finalize_trivia_session_stats_v3() OWNER TO postgres;

