--
-- TOC entry 7724 (class 1255 OID 5970224)
-- Name: trg_fn_live_invite_notification(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_fn_live_invite_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_recipient_id uuid;
    v_sender_name text;
BEGIN
    -- Only trigger for [LIVE_INVITE] messages
    IF NEW.content IS NOT NULL AND NEW.content LIKE '[LIVE_INVITE]%' THEN
        -- Find the recipient (the other participant in the direct conversation)
        SELECT user_id INTO v_recipient_id
        FROM public.social_conversation_participants
        WHERE conversation_id = NEW.conversation_id AND user_id != NEW.sender_id
        LIMIT 1;

        -- Get the sender's name
        SELECT COALESCE(full_name, username, 'Someone') INTO v_sender_name
        FROM public.profiles
        WHERE id = NEW.sender_id;

        IF v_recipient_id IS NOT NULL THEN
            -- Insert the notification record
            INSERT INTO public.notifications (
                user_id,
                type,
                title,
                message,
                data,
                read
            ) VALUES (
                v_recipient_id,
                'live_invite',
                'Live Stream Invite',
                v_sender_name || ' invited you to join their live stream as a guest co-host.',
                jsonb_build_object(
                    'conversation_id', NEW.conversation_id,
                    'message_id', NEW.id,
                    'content', NEW.content,
                    'sender_name', v_sender_name
                ),
                false
            );
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.trg_fn_live_invite_notification() OWNER TO postgres;

--
-- TOC entry 6900 (class 1255 OID 4641513)
-- Name: trg_fn_venue_claim_wiring(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_fn_venue_claim_wiring() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_social_page_id uuid;
BEGIN
    IF COALESCE(OLD.is_claimed, false) = false AND COALESCE(NEW.is_claimed, false) = true THEN
        -- 1. Auto-enable Commander
        IF NOT COALESCE(NEW.commander_enabled, false) THEN
            NEW.commander_enabled := true;
            IF NEW.commander_activated_at IS NULL THEN NEW.commander_activated_at := now(); END IF;
        END IF;
        -- 2. Ensure social_page exists (may have owner_id=null because claimed_by isn't committed yet)
        v_social_page_id := public.fn_ensure_social_page_for_venue(NEW.id);
        -- 3. Force-set owner_id to the incoming claimed_by on the social_page
        IF v_social_page_id IS NOT NULL AND NEW.claimed_by IS NOT NULL THEN
            UPDATE social_pages 
               SET owner_id = NEW.claimed_by,
                   metadata = COALESCE(metadata, '{}'::jsonb) 
                              || jsonb_build_object('is_claimed', true, 
                                                    'claim_wired_at', now())
             WHERE id = v_social_page_id;
        END IF;
    END IF;
    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'venue claim wiring failed for venue %: %', NEW.id, SQLERRM;
    RETURN NEW;
END; $$;


