--
-- TOC entry 7976 (class 1255 OID 24465370)
-- Name: trg_tournament_launch_receipt_is_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_tournament_launch_receipt_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'tournament launch receipts cannot be deleted'
      USING ERRCODE = '55000';
  END IF;

  IF NEW.tournament_id IS DISTINCT FROM OLD.tournament_id
     OR NEW.launch_id IS DISTINCT FROM OLD.launch_id
     OR NEW.started_at IS DISTINCT FROM OLD.started_at
     OR NEW.claimed_at IS DISTINCT FROM OLD.claimed_at
     OR NEW.launch_player_ids IS DISTINCT FROM OLD.launch_player_ids THEN
    RAISE EXCEPTION 'tournament launch receipt identity is immutable'
      USING ERRCODE = '55000';
  END IF;

  IF OLD.completed_at IS NOT NULL THEN
    RAISE EXCEPTION 'completed tournament launch receipts are immutable'
      USING ERRCODE = '55000';
  END IF;

  /* Completion may set completed_at once, but cannot change its authority. */
  IF NEW.completed_at IS NOT NULL THEN
    IF NEW.lease_generation IS DISTINCT FROM OLD.lease_generation THEN
      RAISE EXCEPTION 'a tournament launch receipt generation cannot rotate during completion'
        USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;

  /* Takeover adoption may rotate only the generation of an incomplete
     receipt, under the exact transaction-local marker set by begin. */
  IF NEW.lease_generation IS DISTINCT FROM OLD.lease_generation
     AND current_setting('app.atomic_tournament_launch_lease_adoption', true)
         = OLD.tournament_id::text || ':' || OLD.lease_generation::text || ':' || NEW.lease_generation::text THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'an incomplete tournament launch receipt may only rotate its lease generation during adoption'
    USING ERRCODE = '55000';
END;
$$;


ALTER FUNCTION public.trg_tournament_launch_receipt_is_immutable() OWNER TO postgres;

--
-- TOC entry 8072 (class 1255 OID 16459694)
-- Name: trg_tournament_place_collision(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_tournament_place_collision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing uuid;
BEGIN
  IF NEW.position IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.position IS NOT DISTINCT FROM OLD.position THEN
    RETURN NEW;
  END IF;

  SELECT tp.user_id INTO v_existing
    FROM tournament_players tp
   WHERE tp.tournament_id = NEW.tournament_id
     AND tp.position = NEW.position
     AND tp.user_id <> NEW.user_id
   LIMIT 1;

  IF v_existing IS NOT NULL THEN
    -- Keep the forensic row: it is how the next reader learns this happened
    -- and which two players raced. Written before the raise so the INSERT is
    -- in a separate autonomous-ish path? It is not - it rolls back with the
    -- statement. That is acceptable: the RAISE below carries both user ids and
    -- the elimination path reports it as elimination_write_failed, which is a
    -- louder signal than a row in a table nobody queries.
    INSERT INTO tournament_place_collisions
      (tournament_id, place, user_id, existing_user_id, db_role, application)
    VALUES
      (NEW.tournament_id, NEW.position, NEW.user_id, v_existing,
       current_user, current_setting('application_name', true));

    RAISE EXCEPTION
      'finishing place % in tournament % is already held by % - refusing to stamp % on it (a contested place is paid TWICE, the prize idempotency key includes the user id)',
      NEW.position, NEW.tournament_id, v_existing, NEW.user_id
      USING ERRCODE = '23505';
  END IF;

  RETURN NEW;
END;
$$;


