--
-- TOC entry 4212 (class 1255 OID 4835510)
-- Name: trig_sync_like_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trig_sync_like_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE target uuid; reel_count bigint; post_count bigint;
BEGIN
 IF TG_TABLE_SCHEMA <> 'public' OR TG_TABLE_NAME <> 'social_likes' OR TG_OP NOT IN ('INSERT','DELETE') THEN
   RAISE EXCEPTION 'Like counter called outside maintained reaction trigger'; END IF;
 target := CASE WHEN TG_OP='INSERT' THEN NEW.post_id ELSE OLD.post_id END;
 IF target IS NOT NULL THEN
   -- The same order on every legitimate mutation prevents cross-table deadlocks.
   -- Row locks serialize different players before taking a fresh ledger snapshot.
   PERFORM 1 FROM public.social_posts WHERE id=target FOR UPDATE;
   PERFORM 1 FROM public.social_reels WHERE id=target FOR UPDATE;
   SELECT count(*),count(*) FILTER (WHERE reaction_type='like') INTO post_count,reel_count FROM public.social_likes WHERE post_id=target;
   UPDATE public.social_posts SET like_count=post_count WHERE id=target;
   UPDATE public.social_reels SET like_count=reel_count WHERE id=target;
 END IF;
 IF TG_OP='INSERT' THEN RETURN NEW; ELSE RETURN OLD; END IF;
END $$;


ALTER FUNCTION public.trig_sync_like_count() OWNER TO postgres;

--
-- TOC entry 6356 (class 1255 OID 111857128)
-- Name: trivia_achievement_claim_v2(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_achievement_claim_v2(p_user_id uuid, p_achievement_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    d public.trivia_achievement_definitions%ROWTYPE;
    a public.trivia_achievement_awards_v2%ROWTYPE;
    v_current bigint;
    v_target bigint;
    v_key text;
    v_request jsonb;
    v_pre jsonb;
    v_ledger jsonb;
    v_journal_id uuid;
    v_transaction_id uuid;
    v_actor_kind text;
BEGIN
    IF p_user_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'authentication_required'); END IF;
    IF p_achievement_id IS NULL OR p_achievement_id !~ '^[a-z0-9_]{2,64}$' THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_achievement_id');
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended(
        'trivia-achievement-claim:' || p_user_id::text || ':' || p_achievement_id,
        20261005
    ));

    SELECT * INTO d FROM public.trivia_achievement_definitions
     WHERE achievement_id = p_achievement_id AND version = 2 AND authoritative IS TRUE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'achievement_not_found'); END IF;

    SELECT * INTO a FROM public.trivia_achievement_awards_v2
     WHERE user_id = p_user_id AND achievement_id = p_achievement_id AND definition_version = 2;
    IF a.id IS NOT NULL THEN
        RETURN jsonb_build_object(
            'success', true, 'contract', 'trivia-achievements/2', 'version', 2,
            'replayed', true, 'item', public.trivia_achievement_item_v2(p_user_id, p_achievement_id));
    END IF;

    v_current := public.trivia_achievement_progress_value_v2(p_user_id, d.criteria);
    v_target := (d.criteria ->> 'gte')::bigint;
    IF v_current < v_target THEN
        RETURN jsonb_build_object(
            'success', false, 'error', 'not_eligible',
            'item', public.trivia_achievement_item_v2(p_user_id, p_achievement_id));
    END IF;
    IF d.reward_diamonds IS NULL OR d.reward_diamonds <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'award_failed');
    END IF;

    SELECT CASE WHEN COALESCE(profile.is_horse, false) THEN 'horse' ELSE 'human' END
      INTO v_actor_kind FROM public.profiles profile WHERE profile.id = p_user_id;
    IF v_actor_kind IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'award_failed'); END IF;

    v_key := 'trivia_achievement:' || p_user_id::text || ':' || p_achievement_id || ':v2';
    v_request := jsonb_build_object(
        'achievement_id', p_achievement_id,
        'definition_version', 2,
        'user_id', p_user_id,
        'diamonds', d.reward_diamonds
    );

    BEGIN
        v_pre := public.trivia_ledger_begin(v_key, 'payout', v_request);
        IF v_pre IS NOT NULL THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', CASE WHEN v_pre ->> 'error' = 'idempotency_conflict'
                              THEN 'idempotency_conflict' ELSE 'award_receipt_inconsistent' END);
        END IF;

        v_ledger := public.trivia_ledger_post(
            jsonb_build_object(
                'idempotency_key', v_key,
                'operation', 'payout',
                'request', v_request,
                'source_event', 'trivia.achievement.awarded',
                'source_type', 'trivia_achievement',
                'source_id', p_achievement_id || '@2',
                'actor_kind', v_actor_kind,
                'actor_id', p_user_id,
                'funding_source', 'platform_issuance'
            ),
            jsonb_build_array(
                jsonb_build_object(
                    'account', 'issuance:trivia_run',
                    'amount', -d.reward_diamonds,
                    'user_id', p_user_id,
                    'participant_kind', v_actor_kind,
                    'memo', 'achievement issuance: ' || p_achievement_id || '@2'
                ),
                jsonb_build_object(
                    'account', 'wallet:' || p_user_id::text,
                    'amount', d.reward_diamonds,
                    'user_id', p_user_id,
                    'participant_kind', v_actor_kind,
                    'wallet_kind', 'trivia_run',
                    'wallet_reference', v_key,
                    'wallet_description', 'Trivia Achievement - ' || d.title,
                    'mechanism', 'add'
                )
            )
        );
        IF COALESCE((v_ledger ->> 'success')::boolean, false) IS NOT TRUE THEN
            RAISE EXCEPTION 'balanced achievement journal refused';
        END IF;
        v_journal_id := (v_ledger ->> 'journal_id')::uuid;
        SELECT line.diamond_transaction_id INTO v_transaction_id
          FROM public.trivia_ledger_lines line
         WHERE line.journal_id = v_journal_id
           AND line.account_code = 'wallet:' || p_user_id::text
           AND line.wallet_reference = v_key
           AND line.amount = d.reward_diamonds
           AND line.reconciliation_state = 'linked';
        IF v_transaction_id IS NULL THEN RAISE EXCEPTION 'achievement wallet receipt missing'; END IF;

        INSERT INTO public.trivia_achievement_awards_v2
            (user_id, achievement_id, definition_version, settled_diamonds,
             journal_id, diamond_transaction_id, wallet_reference)
        VALUES
            (p_user_id, p_achievement_id, 2, d.reward_diamonds,
             v_journal_id, v_transaction_id, v_key);
    EXCEPTION
        WHEN unique_violation THEN
            SELECT * INTO a FROM public.trivia_achievement_awards_v2
             WHERE user_id = p_user_id AND achievement_id = p_achievement_id AND definition_version = 2;
            IF a.id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'award_failed'); END IF;
        WHEN SQLSTATE 'TL001' THEN
            RETURN jsonb_build_object('success', false, 'error', 'award_failed');
        WHEN OTHERS THEN
            RETURN jsonb_build_object('success', false, 'error', 'award_failed');
    END;

    RETURN jsonb_build_object(
        'success', true,
        'contract', 'trivia-achievements/2',
        'version', 2,
        'replayed', false,
        'item', public.trivia_achievement_item_v2(p_user_id, p_achievement_id)
    );
END
$_$;


ALTER FUNCTION public.trivia_achievement_claim_v2(p_user_id uuid, p_achievement_id text) OWNER TO postgres;

--
-- TOC entry 6484 (class 1255 OID 111857125)
-- Name: trivia_achievement_item_v2(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_achievement_item_v2(p_user_id uuid, p_achievement_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    d public.trivia_achievement_definitions%ROWTYPE;
    a public.trivia_achievement_awards_v2%ROWTYPE;
    v_current bigint;
    v_target bigint;
    v_settled boolean := false;
    v_state text;
BEGIN
    SELECT * INTO d FROM public.trivia_achievement_definitions
     WHERE achievement_id = p_achievement_id AND version = 2 AND authoritative IS TRUE;
    IF NOT FOUND THEN RETURN NULL; END IF;

    v_current := public.trivia_achievement_progress_value_v2(p_user_id, d.criteria);
    v_target := (d.criteria ->> 'gte')::bigint;
    SELECT * INTO a FROM public.trivia_achievement_awards_v2
     WHERE user_id = p_user_id AND achievement_id = d.achievement_id AND definition_version = d.version;

    IF a.id IS NOT NULL THEN
        SELECT EXISTS (
            SELECT 1
              FROM public.trivia_ledger_journals journal
              JOIN public.trivia_ledger_lines line ON line.journal_id = journal.id
             WHERE journal.id = a.journal_id AND journal.operation = 'payout'
               AND line.account_code = 'wallet:' || p_user_id::text
               AND line.amount = a.settled_diamonds
               AND line.reconciliation_state = 'linked'
               AND line.diamond_transaction_id = a.diamond_transaction_id
               AND line.wallet_reference = a.wallet_reference
        ) INTO v_settled;
    END IF;

    v_state := CASE
        WHEN a.id IS NOT NULL AND v_settled THEN 'awarded'
        WHEN a.id IS NOT NULL THEN 'error'
        WHEN v_current >= v_target THEN 'eligible'
        ELSE 'locked'
    END;

    RETURN (
        SELECT jsonb_build_object(
            'id', d.achievement_id,
            'version', d.version,
            'title', d.title,
            'description', d.description,
            'category', d.category,
            'rarity', d.rarity,
            'criteria', d.criteria,
            'state', v_state,
            'progressCurrent', v_current,
            'progressTarget', v_target,
            'awardedAt', CASE WHEN v_state = 'awarded' THEN a.awarded_at ELSE NULL END,
            'settledDiamonds', CASE WHEN settled.journal_id IS NOT NULL THEN a.settled_diamonds ELSE NULL END,
            'receiptId', CASE WHEN v_state = 'awarded' THEN a.id ELSE NULL END,
            'journalId', CASE WHEN v_state = 'awarded' THEN a.journal_id ELSE NULL END,
            'transactionId', CASE WHEN v_state = 'awarded' THEN a.diamond_transaction_id ELSE NULL END,
            'errorCode', CASE WHEN v_state = 'error' THEN 'award_receipt_inconsistent' ELSE NULL END
        )
        FROM (SELECT CASE WHEN v_settled THEN a.journal_id ELSE NULL END AS journal_id) settled
    );
END
$$;


ALTER FUNCTION public.trivia_achievement_item_v2(p_user_id uuid, p_achievement_id text) OWNER TO postgres;

--
-- TOC entry 8724 (class 1255 OID 111857123)
-- Name: trivia_achievement_progress_value_v2(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_achievement_progress_value_v2(p_user_id uuid, p_criteria jsonb) RETURNS bigint
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_metric text := p_criteria ->> 'metric';
    v_mode text := p_criteria ->> 'mode';
    v_under_ms bigint := NULLIF(p_criteria ->> 'under_ms', '')::bigint;
    v_from integer := NULLIF(p_criteria ->> 'from', '')::integer;
    v_to integer := NULLIF(p_criteria ->> 'to', '')::integer;
    v_misses integer := COALESCE(NULLIF(p_criteria ->> 'misses_before_correct', '')::integer, 3);
    v_require_majority boolean := COALESCE((p_criteria ->> 'require_majority')::boolean, false);
    v_current bigint := 0;
BEGIN
    IF p_user_id IS NULL OR jsonb_typeof(p_criteria) IS DISTINCT FROM 'object'
       OR p_criteria ->> 'source' IS DISTINCT FROM 'verified_server_state_v2' THEN
        RAISE EXCEPTION 'invalid achievement progress request';
    END IF;

    CASE v_metric
        WHEN 'answered_total' THEN
            SELECT COALESCE(sum(run.answer_count), 0)::bigint INTO v_current
              FROM (
                    SELECT result_row.answered::bigint AS answer_count
                      FROM public.trivia_session_results result_row
                     WHERE result_row.user_id = p_user_id AND result_row.outcome = 'submitted'
                    UNION ALL
                    SELECT score.total_questions::bigint
                      FROM public.trivia_scores score
                     WHERE score.user_id = p_user_id AND score.server_verified IS TRUE
                       AND (score.session_id IS NULL OR NOT EXISTS (
                            SELECT 1 FROM public.trivia_session_results result_row
                             WHERE result_row.session_id = score.session_id))
              ) run;
        WHEN 'correct_total' THEN
            SELECT COALESCE(sum(run.correct_count), 0)::bigint INTO v_current
              FROM (
                    SELECT result_row.correct::bigint AS correct_count
                      FROM public.trivia_session_results result_row
                     WHERE result_row.user_id = p_user_id AND result_row.outcome = 'submitted'
                    UNION ALL
                    SELECT score.correct_count::bigint
                      FROM public.trivia_scores score
                     WHERE score.user_id = p_user_id AND score.server_verified IS TRUE
                       AND (score.session_id IS NULL OR NOT EXISTS (
                            SELECT 1 FROM public.trivia_session_results result_row
                             WHERE result_row.session_id = score.session_id))
              ) run;
        WHEN 'perfect_runs' THEN
            SELECT count(*)::bigint INTO v_current
              FROM (
                    SELECT result_row.session_id::text AS run_id
                      FROM public.trivia_session_results result_row
                     WHERE result_row.user_id = p_user_id AND result_row.outcome = 'submitted'
                       AND result_row.graded_total > 0 AND result_row.correct = result_row.graded_total
                       AND (v_mode IS NULL OR result_row.mode = v_mode)
                    UNION ALL
                    SELECT 'score:' || score.id::text
                      FROM public.trivia_scores score
                     WHERE score.user_id = p_user_id AND score.server_verified IS TRUE
                       AND score.total_questions > 0 AND score.correct_count = score.total_questions
                       AND (v_mode IS NULL OR score.mode = v_mode)
                       AND (score.session_id IS NULL OR NOT EXISTS (
                            SELECT 1 FROM public.trivia_session_results result_row
                             WHERE result_row.session_id = score.session_id))
              ) run;
        WHEN 'mode_correct' THEN
            IF v_mode IS NULL THEN RAISE EXCEPTION 'mode_correct requires a mode'; END IF;
            SELECT COALESCE(sum(run.correct_count), 0)::bigint INTO v_current
              FROM (
                    SELECT result_row.correct::bigint AS correct_count
                      FROM public.trivia_session_results result_row
                     WHERE result_row.user_id = p_user_id AND result_row.outcome = 'submitted'
                       AND result_row.mode = v_mode
                    UNION ALL
                    SELECT score.correct_count::bigint
                      FROM public.trivia_scores score
                     WHERE score.user_id = p_user_id AND score.server_verified IS TRUE AND score.mode = v_mode
                       AND (score.session_id IS NULL OR NOT EXISTS (
                            SELECT 1 FROM public.trivia_session_results result_row
                             WHERE result_row.session_id = score.session_id))
              ) run;
        WHEN 'best_streak' THEN
            SELECT COALESCE(max(streak.best_streak), 0)::bigint INTO v_current
              FROM public.trivia_streaks streak WHERE streak.user_id = p_user_id;
        WHEN 'fast_correct_answers' THEN
            IF v_under_ms IS NULL OR v_under_ms <= 0 THEN RAISE EXCEPTION 'fast_correct_answers requires under_ms'; END IF;
            SELECT count(*)::bigint INTO v_current
              FROM public.trivia_session_answers answer
              JOIN public.trivia_session_results result_row ON result_row.session_id = answer.session_id
             WHERE result_row.user_id = p_user_id AND result_row.outcome = 'submitted'
               AND answer.outcome = 'correct' AND answer.opened_at IS NOT NULL AND answer.answered_at IS NOT NULL
               AND answer.answered_at >= answer.opened_at
               AND extract(epoch FROM (answer.answered_at - answer.opened_at)) * 1000 < v_under_ms;
        WHEN 'fast_average_runs' THEN
            IF v_under_ms IS NULL OR v_under_ms <= 0 THEN RAISE EXCEPTION 'fast_average_runs requires under_ms'; END IF;
            SELECT count(*)::bigint INTO v_current
              FROM (
                    SELECT result_row.session_id::text AS run_id
                      FROM public.trivia_session_results result_row
                     WHERE result_row.user_id = p_user_id AND result_row.outcome = 'submitted'
                       AND result_row.answered > 0
                       AND result_row.answer_time_ms_total < v_under_ms * result_row.answered
                       AND (NOT v_require_majority OR result_row.correct * 2 > result_row.graded_total)
                    UNION ALL
                    SELECT 'score:' || score.id::text
                      FROM public.trivia_scores score
                     WHERE score.user_id = p_user_id AND score.server_verified IS TRUE
                       AND score.time_spent > 0 AND score.total_questions > 0
                       AND score.time_spent::bigint * 1000 < v_under_ms * score.total_questions
                       AND (NOT v_require_majority OR score.correct_count * 2 > score.total_questions)
                       AND (score.session_id IS NULL OR NOT EXISTS (
                            SELECT 1 FROM public.trivia_session_results result_row
                             WHERE result_row.session_id = score.session_id))
              ) run;
        WHEN 'runs' THEN
            IF v_mode IS NULL THEN RAISE EXCEPTION 'runs requires a mode'; END IF;
            SELECT count(*)::bigint INTO v_current
              FROM (
                    SELECT result_row.session_id::text AS run_id
                      FROM public.trivia_session_results result_row
                     WHERE result_row.user_id = p_user_id AND result_row.outcome = 'submitted' AND result_row.mode = v_mode
                    UNION ALL
                    SELECT 'score:' || score.id::text
                      FROM public.trivia_scores score
                     WHERE score.user_id = p_user_id AND score.server_verified IS TRUE AND score.mode = v_mode
                       AND (score.session_id IS NULL OR NOT EXISTS (
                            SELECT 1 FROM public.trivia_session_results result_row
                             WHERE result_row.session_id = score.session_id))
              ) run;
        WHEN 'diamonds_earned' THEN
            IF v_mode IS NULL THEN RAISE EXCEPTION 'diamonds_earned requires a mode'; END IF;
            SELECT COALESCE(sum(greatest(score.diamonds_earned, 0)), 0)::bigint INTO v_current
              FROM public.trivia_scores score
             WHERE score.user_id = p_user_id AND score.server_verified IS TRUE AND score.mode = v_mode;
        WHEN 'runs_chicago_hour_between' THEN
            IF v_from IS NULL OR v_to IS NULL OR v_from < 0 OR v_to > 23 OR v_from > v_to THEN
                RAISE EXCEPTION 'runs_chicago_hour_between requires a valid hour range';
            END IF;
            SELECT count(*)::bigint INTO v_current
              FROM (
                    SELECT result_row.completed_at AS occurred_at
                      FROM public.trivia_session_results result_row
                     WHERE result_row.user_id = p_user_id AND result_row.outcome = 'submitted'
                    UNION ALL
                    SELECT score.created_at
                      FROM public.trivia_scores score
                     WHERE score.user_id = p_user_id AND score.server_verified IS TRUE
                       AND (score.session_id IS NULL OR NOT EXISTS (
                            SELECT 1 FROM public.trivia_session_results result_row
                             WHERE result_row.session_id = score.session_id))
              ) run
             WHERE extract(hour FROM run.occurred_at AT TIME ZONE 'America/Chicago')::integer BETWEEN v_from AND v_to;
        WHEN 'comeback_runs' THEN
            SELECT count(*)::bigint INTO v_current
              FROM public.trivia_session_results result_row
             WHERE result_row.user_id = p_user_id AND result_row.outcome = 'submitted'
               AND EXISTS (
                    SELECT 1 FROM public.trivia_session_answers winning_answer
                     WHERE winning_answer.session_id = result_row.session_id
                       AND winning_answer.outcome = 'correct'
                       AND (
                            SELECT count(*) FROM public.trivia_session_answers missed_answer
                             WHERE missed_answer.session_id = result_row.session_id
                               AND missed_answer.position < winning_answer.position
                               AND missed_answer.outcome IN ('wrong','skip','late','timeout')
                       ) >= v_misses
               );
        WHEN 'runs_in_chicago_day' THEN
            SELECT COALESCE(max(day_runs.run_count), 0)::bigint INTO v_current
              FROM (
                    SELECT (run.occurred_at AT TIME ZONE 'America/Chicago')::date AS chicago_day,
                           count(*)::bigint AS run_count
                      FROM (
                            SELECT result_row.completed_at AS occurred_at
                              FROM public.trivia_session_results result_row
                             WHERE result_row.user_id = p_user_id AND result_row.outcome = 'submitted'
                            UNION ALL
                            SELECT score.created_at
                              FROM public.trivia_scores score
                             WHERE score.user_id = p_user_id AND score.server_verified IS TRUE
                               AND (score.session_id IS NULL OR NOT EXISTS (
                                    SELECT 1 FROM public.trivia_session_results result_row
                                     WHERE result_row.session_id = score.session_id))
                      ) run
                     GROUP BY 1
              ) day_runs;
        ELSE
            RAISE EXCEPTION 'unknown achievement metric: %', COALESCE(v_metric, '<null>');
    END CASE;

    RETURN greatest(COALESCE(v_current, 0), 0);
END
$$;


ALTER FUNCTION public.trivia_achievement_progress_value_v2(p_user_id uuid, p_criteria jsonb) OWNER TO postgres;

--
-- TOC entry 3442 (class 1255 OID 111857126)
-- Name: trivia_achievements_snapshot_v2(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_achievements_snapshot_v2(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_items jsonb;
BEGIN
    IF p_user_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'authentication_required'); END IF;
    SELECT COALESCE(jsonb_agg(public.trivia_achievement_item_v2(p_user_id, definition.achievement_id)
                             ORDER BY definition.display_order), '[]'::jsonb)
      INTO v_items
      FROM public.trivia_achievement_definitions definition
     WHERE definition.version = 2 AND definition.authoritative IS TRUE;
    RETURN jsonb_build_object(
        'success', true,
        'contract', 'trivia-achievements/2',
        'version', 2,
        'generatedAt', statement_timestamp(),
        'items', v_items
    );
END
$$;


ALTER FUNCTION public.trivia_achievements_snapshot_v2(p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 6259 (class 1255 OID 74744058)
-- Name: trivia_backfill_session_stats_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_backfill_session_stats_v1(p_session_id uuid, p_actor text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE s public.trivia_sessions%ROWTYPE; v_points integer; v_tx_n integer; v_tx_sum bigint; v_entry_n integer;
        v_entry_sum bigint; v_bad_keys integer; v_regradable boolean; v_regrade integer; v_fail text; v_ev jsonb;
BEGIN
    IF btrim(coalesce(p_actor, '')) = '' THEN RETURN jsonb_build_object('success', false, 'error', 'actor_required'); END IF;
    SELECT * INTO s FROM public.trivia_sessions WHERE id = p_session_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'session_not_found'); END IF;
    IF s.status <> 'submitted' OR s.stats_recorded_at IS NOT NULL OR s.engine_version IS NOT NULL
       OR s.settlement_result IS NOT NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_a_backfill_candidate');
    END IF;
    v_points := CASE s.mode WHEN 'arcade' THEN 200 WHEN 'gto' THEN 150 WHEN 'survival' THEN 200 WHEN 'endless' THEN 200
                            WHEN 'tournaments' THEN 200 WHEN 'time-attack' THEN 200 ELSE 100 END;
    SELECT count(*), coalesce(sum(amount), 0) INTO v_tx_n, v_tx_sum FROM public.diamond_transactions
     WHERE reference_id = 'trivia_session_' || s.id::text;
    SELECT count(*), coalesce(sum(amount), 0) INTO v_entry_n, v_entry_sum FROM public.diamond_transactions
     WHERE reference_id = 'trivia_entry_' || s.id::text;
    SELECT count(*) INTO v_bad_keys FROM jsonb_object_keys(s.answers) k WHERE NOT (k::uuid = ANY (s.question_ids));
    v_fail := CASE
        WHEN public.trivia_p3_session_is_held_evidence(s.id) THEN 'quarantined_evidence'
        WHEN coalesce(s.score, -1) <> coalesce(s.correct_count, -1) * v_points THEN 'score_formula_mismatch'
        WHEN s.correct_count < 0 OR s.correct_count > cardinality(s.question_ids) THEN 'correct_out_of_range'
        WHEN v_bad_keys > 0 THEN 'answers_off_roster'
        WHEN v_tx_n > 1 OR v_tx_sum <> coalesce(s.diamonds_awarded, 0) THEN 'reward_reference_mismatch'
        WHEN s.entry_state IN ('legacy','free','vip','ticket','continuation') AND v_entry_n <> 0 THEN 'unexpected_entry_charge'
        WHEN s.entry_state = 'charged' AND (v_entry_n <> 1 OR v_entry_sum <> -s.entry_cost) THEN 'entry_reference_mismatch'
        END;
    v_ev := jsonb_build_object('mode', s.mode, 'entry_state', s.entry_state, 'score', s.score, 'correct', s.correct_count,
        'roster', cardinality(s.question_ids), 'answers', (SELECT count(*) FROM jsonb_object_keys(s.answers)),
        'reward_refs', v_tx_n, 'reward_sum', v_tx_sum, 'diamonds_awarded', s.diamonds_awarded, 'entry_refs', v_entry_n);
    IF v_fail IS NOT NULL THEN
        INSERT INTO public.trivia_session_reconciliations (session_id, action, reason, evidence, actor)
        VALUES (s.id, 'backfill_refused', v_fail, v_ev, p_actor) ON CONFLICT (session_id, action) DO NOTHING;
        RETURN jsonb_build_object('success', false, 'error', 'verification_failed', 'reason', v_fail);
    END IF;
    -- Per-question verdicts are reconstructible only when no roster question changed after grading.
    v_regradable := NOT EXISTS (SELECT 1 FROM public.trivia_questions q WHERE q.id = ANY (s.question_ids)
                                   AND q.updated_at > coalesce(s.submitted_at, s.created_at));
    IF v_regradable THEN
        SELECT count(*) INTO v_regrade FROM unnest(s.question_ids) qid
          JOIN public.trivia_questions q ON q.id = qid
         WHERE (s.answers -> qid::text ->> 'd') ~ '^[0-9]+$'
           AND (s.permutations -> qid::text ->> ((s.answers -> qid::text ->> 'd')::int))::int = q.correct_index;
        IF v_regrade <> s.correct_count THEN
            INSERT INTO public.trivia_session_reconciliations (session_id, action, reason, evidence, actor)
            VALUES (s.id, 'backfill_refused', 'regrade_mismatch', v_ev || jsonb_build_object('regrade', v_regrade), p_actor)
            ON CONFLICT (session_id, action) DO NOTHING;
            RETURN jsonb_build_object('success', false, 'error', 'verification_failed', 'reason', 'regrade_mismatch');
        END IF;
    END IF;
    INSERT INTO public.trivia_question_result_events (user_id, question_id, mode, source_type, source_id,
        display_index, original_index, was_correct, was_skipped, actor_type)
    SELECT s.user_id, q.id, s.mode, 'session', s.id,
           CASE WHEN (s.answers -> q.id::text ->> 'd') ~ '^-?[0-9]+$' THEN (s.answers -> q.id::text ->> 'd')::int END,
           CASE WHEN v_regradable AND (s.answers -> q.id::text ->> 'd') ~ '^[0-9]+$'
                THEN (s.permutations -> q.id::text ->> ((s.answers -> q.id::text ->> 'd')::int))::int END,
           CASE WHEN v_regradable AND (s.answers -> q.id::text ->> 'd') ~ '^[0-9]+$'
                THEN (s.permutations -> q.id::text ->> ((s.answers -> q.id::text ->> 'd')::int))::int = q.correct_index END,
           coalesce((s.answers -> q.id::text ->> 'd') = '-1', false), 'human'
      FROM public.trivia_questions q WHERE q.id = ANY (s.question_ids)
    ON CONFLICT (source_type, source_id, user_id, question_id) DO NOTHING;
    INSERT INTO public.trivia_user_question_history (user_id, question_id, seen_at, was_correct, mode)
    SELECT s.user_id, qid, coalesce(s.created_at, now()), NULL, s.mode FROM unnest(s.question_ids) qid
    ON CONFLICT (user_id, question_id) DO NOTHING;
    UPDATE public.trivia_sessions SET stats_recorded_at = now() WHERE id = s.id;
    INSERT INTO public.trivia_session_reconciliations (session_id, action, reason, evidence, actor)
    VALUES (s.id, 'stats_backfilled', CASE WHEN v_regradable THEN 'verified_regraded' ELSE
            'verified_session_level_only_answer_positions_reshuffled_after_grading' END,
            v_ev || jsonb_build_object('regradable', v_regradable), p_actor)
    ON CONFLICT (session_id, action) DO NOTHING;
    RETURN jsonb_build_object('success', true, 'session_id', s.id, 'regradable', v_regradable);
END $_$;


ALTER FUNCTION public.trivia_backfill_session_stats_v1(p_session_id uuid, p_actor text) OWNER TO postgres;

--
-- TOC entry 8419 (class 1255 OID 110225987)
-- Name: trivia_bind_revision_engine_metadata_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_bind_revision_engine_metadata_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    SELECT coalesce(q.engine_metadata, '{}'::jsonb) INTO NEW.engine_metadata
      FROM public.trivia_questions q WHERE q.id = NEW.question_id;
    NEW.engine_metadata := coalesce(NEW.engine_metadata, '{}'::jsonb);
    RETURN NEW;
END $$;


ALTER FUNCTION public.trivia_bind_revision_engine_metadata_v1() OWNER TO postgres;

--
-- TOC entry 3446 (class 1255 OID 74744028)
-- Name: trivia_build_roster_v1(text, text, text, uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_build_roster_v1(p_scope_kind text, p_scope_id text, p_profile_id text, p_player_ids uuid[] DEFAULT '{}'::uuid[], p_exclude_question_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_s public.trivia_roster_snapshots%ROWTYPE;
    v_p public.trivia_roster_profiles%ROWTYPE;
    v_as_of timestamptz := now();
    v_label text;
    v_excl uuid[];
    v_n integer;
    v_got integer;
BEGIN
    IF p_scope_kind IS NULL OR p_scope_kind NOT IN ('pvp_match','solo_session','daily')
       OR p_scope_id IS NULL OR length(p_scope_id) NOT BETWEEN 1 AND 128 THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_scope');
    END IF;
    SELECT * INTO v_p FROM public.trivia_roster_profiles WHERE profile_id = p_profile_id;
    IF NOT FOUND OR (p_scope_kind = 'pvp_match' AND v_p.mode <> 'pvp')
       OR (p_scope_kind IN ('solo_session','daily') AND v_p.mode IN ('pvp','tournaments')) THEN
        RETURN jsonb_build_object('success', false, 'error', 'unknown_profile');
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('trivia_roster:' || p_scope_kind || ':' || p_scope_id, 0));
    SELECT * INTO v_s FROM public.trivia_roster_snapshots WHERE scope_kind = p_scope_kind AND scope_id = p_scope_id;
    IF FOUND THEN
        IF v_s.profile_id <> p_profile_id THEN
            RETURN jsonb_build_object('success', false, 'error', 'scope_conflict', 'snapshot_id', v_s.id);
        END IF;
        RETURN public.trivia_p3_snapshot_receipt(v_s);
    END IF;
    v_label := p_scope_kind || ':' || p_scope_id;
    v_n := v_p.question_count;
    v_excl := ARRAY(SELECT DISTINCT c.canonical_question_id FROM public.trivia_question_curation c
                     WHERE c.question_id = ANY (coalesce(p_exclude_question_ids, '{}'::uuid[])));
    CREATE TEMP TABLE IF NOT EXISTS trivia_p3_plan (round_no integer, pos integer, question_id uuid, revision_id uuid,
        canonical_question_id uuid, category text, difficulty text, tier smallint) ON COMMIT DROP;
    TRUNCATE pg_temp.trivia_p3_plan;
    INSERT INTO pg_temp.trivia_p3_plan
    SELECT 1, s.pos, s.question_id, s.revision_id, s.canonical_question_id, s.category, s.difficulty, s.tier
      FROM public.trivia_select_core_v1(public.trivia_engine_secret_v1('roster-v1'), v_label, p_profile_id, v_n,
           coalesce(p_player_ids, '{}'::uuid[]), v_excl, v_as_of) s;
    SELECT count(*) INTO v_got FROM pg_temp.trivia_p3_plan;
    IF v_got < v_n THEN
        RETURN jsonb_build_object('success', false, 'error', 'insufficient_eligible_pool', 'required', v_n, 'available', v_got);
    END IF;
    RETURN public.trivia_p3_store_snapshot(p_scope_kind, p_scope_id, p_profile_id, v_label, v_as_of, 1);
END $$;


ALTER FUNCTION public.trivia_build_roster_v1(p_scope_kind text, p_scope_id text, p_profile_id text, p_player_ids uuid[], p_exclude_question_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 5075 (class 1255 OID 110225995)
-- Name: trivia_capture_engine_metadata_revision_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_capture_engine_metadata_revision_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_current public.trivia_question_revisions%ROWTYPE;
    v_hash text;
    v_rev uuid;
    v_revision_no integer;
BEGIN
    IF NEW.engine_metadata IS NOT DISTINCT FROM OLD.engine_metadata THEN RETURN NULL; END IF;
    v_hash := public.trivia_question_content_hash_v1(NEW.question, NEW.options, NEW.correct_index,
        NEW.explanation, NEW.category, NEW.subcategory, NEW.difficulty);
    SELECT r.* INTO v_current
      FROM public.trivia_question_curation c
      JOIN public.trivia_question_revisions r ON r.id = c.current_revision_id
     WHERE c.question_id = NEW.id FOR UPDATE OF c;
    -- A simultaneous content update is captured by the existing content
    -- trigger, whose insert binder writes NEW.engine_metadata.
    IF NOT FOUND OR v_current.content_hash <> v_hash
       OR v_current.engine_metadata IS NOT DISTINCT FROM coalesce(NEW.engine_metadata, '{}'::jsonb) THEN
        RETURN NULL;
    END IF;
    SELECT coalesce(max(revision_no), 0) + 1 INTO v_revision_no
      FROM public.trivia_question_revisions WHERE question_id = NEW.id;
    INSERT INTO public.trivia_question_revisions (question_id, revision_no, content_hash, question, options,
        correct_index, explanation, category, subcategory, difficulty, fingerprint, content_version, source,
        reading_words, min_timer_seconds, structurally_valid, capture_reason, engine_metadata)
    VALUES (v_current.question_id, v_revision_no, v_current.content_hash, v_current.question, v_current.options,
        v_current.correct_index, v_current.explanation, v_current.category, v_current.subcategory,
        v_current.difficulty, v_current.fingerprint, v_current.content_version, v_current.source,
        v_current.reading_words, v_current.min_timer_seconds, v_current.structurally_valid,
        'content_update', coalesce(NEW.engine_metadata, '{}'::jsonb))
    RETURNING id INTO v_rev;
    UPDATE public.trivia_question_curation SET current_revision_id = v_rev, updated_at = now()
     WHERE question_id = NEW.id;
    RETURN NULL;
END $$;


ALTER FUNCTION public.trivia_capture_engine_metadata_revision_v1() OWNER TO postgres;

--
-- TOC entry 9397 (class 1255 OID 74719806)
-- Name: trivia_capture_question_revision_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_capture_question_revision_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_hash text;
    v_metadata jsonb := coalesce(NEW.engine_metadata, '{}'::jsonb);
    v_latest record;
    v_rev uuid;
    v_old_fp text;
    v_canon uuid;
    v_promoted uuid;
BEGIN
    v_hash := public.trivia_question_content_hash_v1(NEW.question, NEW.options, NEW.correct_index,
        NEW.explanation, NEW.category, NEW.subcategory, NEW.difficulty);
    SELECT id, revision_no, content_hash, engine_metadata INTO v_latest
      FROM public.trivia_question_revisions WHERE question_id = NEW.id
     ORDER BY revision_no DESC LIMIT 1;
    IF FOUND AND v_latest.content_hash = v_hash
       AND v_latest.engine_metadata IS NOT DISTINCT FROM v_metadata THEN
        v_rev := v_latest.id;
    ELSE
        SELECT id INTO v_rev FROM public.trivia_question_revisions
         WHERE question_id = NEW.id AND content_hash = v_hash
           AND engine_metadata IS NOT DISTINCT FROM v_metadata
         ORDER BY revision_no DESC LIMIT 1;
        IF v_rev IS NULL THEN
            INSERT INTO public.trivia_question_revisions (question_id, revision_no, content_hash, question,
                options, correct_index, explanation, category, subcategory, difficulty, fingerprint, source,
                reading_words, min_timer_seconds, structurally_valid, capture_reason, engine_metadata)
            VALUES (NEW.id, coalesce(v_latest.revision_no, 0) + 1, v_hash, NEW.question, NEW.options,
                NEW.correct_index, NEW.explanation, NEW.category, NEW.subcategory, NEW.difficulty,
                NEW.question_fingerprint, NEW.source,
                public.trivia_reading_words_v1(NEW.question, NEW.options),
                public.trivia_min_timer_seconds_v1(NEW.question, NEW.options),
                public.trivia_question_structure_ok_v1(NEW.question, NEW.options, NEW.correct_index,
                    NEW.category, NEW.difficulty),
                CASE WHEN TG_OP = 'INSERT' THEN 'insert' ELSE 'content_update' END, v_metadata)
            RETURNING id INTO v_rev;
        END IF;
    END IF;

    SELECT fingerprint INTO v_old_fp FROM public.trivia_question_curation WHERE question_id = NEW.id;
    IF NOT FOUND THEN
        SELECT c.canonical_question_id INTO v_canon FROM public.trivia_question_curation c
         WHERE c.fingerprint = NEW.question_fingerprint AND c.canonical_reason <> 'alias'
         ORDER BY c.created_at, c.question_id LIMIT 1;
        INSERT INTO public.trivia_question_curation (question_id, current_revision_id, fingerprint,
            canonical_question_id, canonical_reason, modes, source, provenance)
        VALUES (NEW.id, v_rev, NEW.question_fingerprint, coalesce(v_canon, NEW.id),
            CASE WHEN v_canon IS NULL THEN 'sole' ELSE 'alias' END,
            public.trivia_default_modes_v1(NEW.category), NEW.source,
            jsonb_build_object('source', NEW.source, 'created_at', NEW.created_at,
                'baseline_quality', NEW.quality_score, 'captured_by', 'trivia_capture_question_revision_v1'));
        IF v_canon IS NOT NULL THEN
            UPDATE public.trivia_question_curation SET canonical_reason = 'group_canonical', updated_at = now()
             WHERE question_id = v_canon AND canonical_reason = 'sole';
        END IF;
        RETURN NULL;
    END IF;

    UPDATE public.trivia_question_curation
       SET current_revision_id = v_rev,
           modes = CASE WHEN TG_OP = 'UPDATE' AND NEW.category IS DISTINCT FROM OLD.category
                        THEN public.trivia_default_modes_v1(NEW.category) ELSE modes END,
           updated_at = now()
     WHERE question_id = NEW.id;

    IF v_old_fp IS DISTINCT FROM NEW.question_fingerprint THEN
        SELECT c.question_id INTO v_promoted
          FROM public.trivia_question_curation c JOIN public.trivia_questions q ON q.id = c.question_id
         WHERE c.fingerprint = v_old_fp AND c.question_id <> NEW.id AND c.canonical_question_id = NEW.id
         ORDER BY (coalesce(q.quality_score, 0) >= 6) DESC,
                  CASE WHEN q.audit_verified IS TRUE THEN 0 WHEN q.audit_verified IS NULL THEN 1 ELSE 2 END,
                  q.quality_score DESC NULLS LAST, q.created_at ASC NULLS LAST, q.id ASC
         LIMIT 1;
        IF v_promoted IS NOT NULL THEN
            UPDATE public.trivia_question_curation
               SET canonical_question_id = v_promoted,
                   canonical_reason = CASE WHEN question_id = v_promoted THEN 'group_canonical' ELSE 'alias' END,
                   updated_at = now()
             WHERE fingerprint = v_old_fp AND question_id <> NEW.id;
            UPDATE public.trivia_question_curation SET canonical_reason = 'sole', updated_at = now()
             WHERE question_id = v_promoted
               AND NOT EXISTS (SELECT 1 FROM public.trivia_question_curation o
                                WHERE o.fingerprint = v_old_fp AND o.question_id <> v_promoted
                                  AND o.question_id <> NEW.id);
        END IF;
        SELECT c.canonical_question_id INTO v_canon FROM public.trivia_question_curation c
         WHERE c.fingerprint = NEW.question_fingerprint AND c.question_id <> NEW.id
           AND c.canonical_reason <> 'alias'
         ORDER BY c.created_at, c.question_id LIMIT 1;
        UPDATE public.trivia_question_curation
           SET fingerprint = NEW.question_fingerprint,
               canonical_question_id = coalesce(v_canon, NEW.id),
               canonical_reason = CASE WHEN v_canon IS NULL THEN 'sole' ELSE 'alias' END,
               updated_at = now()
         WHERE question_id = NEW.id;
        IF v_canon IS NOT NULL THEN
            UPDATE public.trivia_question_curation SET canonical_reason = 'group_canonical', updated_at = now()
             WHERE question_id = v_canon AND canonical_reason = 'sole';
        END IF;
    END IF;
    RETURN NULL;
END $$;


ALTER FUNCTION public.trivia_capture_question_revision_v1() OWNER TO postgres;

--
-- TOC entry 7710 (class 1255 OID 110225981)
-- Name: trivia_claim_gto_render_v1(text, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_claim_gto_render_v1(p_cache_digest text, p_owner_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    v_now timestamptz := clock_timestamp();
    v_seconds integer := greatest(60, least(coalesce(p_lease_seconds, 300), 600));
    v_claim public.trivia_gto_render_claims%ROWTYPE;
    v_retry bigint;
BEGIN
    IF p_cache_digest IS NULL OR p_cache_digest !~ '^[0-9a-f]{64}$' OR p_owner_token IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
    END IF;
    INSERT INTO public.trivia_gto_render_claims AS c
        (cache_digest, owner_token, lease_expires_at, created_at, updated_at)
    VALUES (p_cache_digest, p_owner_token, v_now + make_interval(secs => v_seconds), v_now, v_now)
    ON CONFLICT (cache_digest) DO UPDATE
       SET owner_token = EXCLUDED.owner_token,
           lease_expires_at = EXCLUDED.lease_expires_at,
           updated_at = EXCLUDED.updated_at
     WHERE c.lease_expires_at <= v_now
    RETURNING * INTO v_claim;
    IF FOUND THEN
        RETURN jsonb_build_object('success', true, 'acquired', true,
            'leaseExpiresAt', v_claim.lease_expires_at);
    END IF;
    SELECT * INTO v_claim FROM public.trivia_gto_render_claims
     WHERE cache_digest = p_cache_digest;
    v_retry := greatest(250, least(600000,
        ceil(extract(epoch FROM (coalesce(v_claim.lease_expires_at, v_now) - v_now)) * 1000)::bigint));
    RETURN jsonb_build_object('success', true, 'acquired', false,
        'leaseExpiresAt', v_claim.lease_expires_at, 'retryAfterMs', v_retry);
END $_$;


ALTER FUNCTION public.trivia_claim_gto_render_v1(p_cache_digest text, p_owner_token uuid, p_lease_seconds integer) OWNER TO postgres;

--
-- TOC entry 4660 (class 1255 OID 74719979)
-- Name: trivia_claim_review_batch_v1(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_claim_review_batch_v1(p_reviewer text, p_size integer DEFAULT 25, p_lease_seconds integer DEFAULT 900) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
    v_batch public.trivia_review_batches%ROWTYPE;
    v_size integer := least(greatest(coalesce(p_size, 25), 1), 200);
    v_resumed boolean := false;
    v_n integer;
    v_items jsonb;
BEGIN
    IF p_reviewer IS NULL OR p_reviewer !~ '^[a-z0-9][a-z0-9._/:-]{2,63}$' THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_reviewer');
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('trivia_review_queue_v1', 0));
    UPDATE public.trivia_review_batches SET status = 'expired'
     WHERE status = 'claimed' AND lease_expires_at < now();

    SELECT b.* INTO v_batch FROM public.trivia_review_batches b
     WHERE b.reviewer = p_reviewer AND b.status = 'claimed'
       AND EXISTS (SELECT 1 FROM public.trivia_review_batch_items i WHERE i.batch_id = b.id AND i.review_id IS NULL)
     ORDER BY b.batch_no LIMIT 1;
    IF FOUND THEN
        v_resumed := true;
    ELSE
        SELECT count(*) INTO v_n FROM (
            SELECT 1 FROM public.trivia_review_queue_v1 qv
             WHERE NOT EXISTS (SELECT 1 FROM public.trivia_review_batch_items i
                                 JOIN public.trivia_review_batches b ON b.id = i.batch_id
                                WHERE i.question_id = qv.question_id AND b.status = 'claimed'
                                  AND i.review_id IS NULL)
             LIMIT 1) z;
        IF v_n = 0 THEN
            RETURN jsonb_build_object('success', true, 'empty', true, 'items', '[]'::jsonb);
        END IF;
        INSERT INTO public.trivia_review_batches (queue_version, reviewer, size, status, lease_expires_at)
        VALUES ('trivia-review-queue/1', p_reviewer, 0, 'claimed',
                now() + make_interval(secs => greatest(60, least(coalesce(p_lease_seconds, 900), 3600))))
        RETURNING * INTO v_batch;
        INSERT INTO public.trivia_review_batch_items (batch_id, position, question_id, revision_id)
        SELECT v_batch.id, row_number() OVER (ORDER BY s.priority, s.inconclusive_attempts, s.created_at, s.question_id),
               s.question_id, s.revision_id
          FROM (SELECT qv.* FROM public.trivia_review_queue_v1 qv
                 WHERE NOT EXISTS (SELECT 1 FROM public.trivia_review_batch_items i
                                     JOIN public.trivia_review_batches b ON b.id = i.batch_id
                                    WHERE i.question_id = qv.question_id AND b.status = 'claimed'
                                      AND i.review_id IS NULL)
                 ORDER BY qv.priority, qv.inconclusive_attempts, qv.created_at, qv.question_id
                 LIMIT v_size) s;
        GET DIAGNOSTICS v_n = ROW_COUNT;
        UPDATE public.trivia_review_batches SET size = v_n WHERE id = v_batch.id RETURNING * INTO v_batch;
    END IF;

    SELECT jsonb_agg(jsonb_build_object('position', i.position, 'question_id', i.question_id,
               'revision_id', i.revision_id, 'question', r.question, 'options', r.options,
               'category', r.category, 'difficulty', r.difficulty) ORDER BY i.position)
      INTO v_items
      FROM public.trivia_review_batch_items i
      JOIN public.trivia_question_revisions r ON r.id = i.revision_id
     WHERE i.batch_id = v_batch.id AND i.review_id IS NULL;
    RETURN jsonb_build_object('success', true, 'empty', false, 'resumed', v_resumed,
        'batch_id', v_batch.id, 'batch_no', v_batch.batch_no, 'queue_version', v_batch.queue_version,
        'lease_expires_at', v_batch.lease_expires_at, 'items', coalesce(v_items, '[]'::jsonb));
END $_$;


ALTER FUNCTION public.trivia_claim_review_batch_v1(p_reviewer text, p_size integer, p_lease_seconds integer) OWNER TO postgres;

--
-- TOC entry 8529 (class 1255 OID 74744032)
-- Name: trivia_close_roster_scope_v1(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_close_roster_scope_v1(p_snapshot_id uuid, p_round_no integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE v_n integer;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.trivia_roster_snapshots WHERE id = p_snapshot_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'snapshot_not_found');
    END IF;
    IF p_round_no IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.trivia_roster_snapshot_items
                                               WHERE snapshot_id = p_snapshot_id AND round_no = p_round_no) THEN
        RETURN jsonb_build_object('success', false, 'error', 'round_not_in_snapshot');
    END IF;
    INSERT INTO public.trivia_roster_scope_closures (snapshot_id, round_no)
    VALUES (p_snapshot_id, coalesce(p_round_no, 0)) ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RETURN jsonb_build_object('success', true, 'duplicate', v_n = 0, 'snapshot_id', p_snapshot_id, 'round_no', coalesce(p_round_no, 0));
END $$;


ALTER FUNCTION public.trivia_close_roster_scope_v1(p_snapshot_id uuid, p_round_no integer) OWNER TO postgres;

--
-- TOC entry 4088 (class 1255 OID 111890065)
-- Name: trivia_competitive_bootstrap_authorization_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_competitive_bootstrap_authorization_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF TG_OP IN ('DELETE', 'TRUNCATE') THEN
        RAISE EXCEPTION 'scheduler bootstrap authorization is retained evidence'
            USING ERRCODE = '42501';
    END IF;
    IF OLD.consumed_run_id IS NOT NULL
       OR NEW.authorization_id IS DISTINCT FROM OLD.authorization_id
       OR NEW.job_identity IS DISTINCT FROM OLD.job_identity
       OR NEW.holder_id IS DISTINCT FROM OLD.holder_id
       OR NEW.expected_fencing_token IS DISTINCT FROM OLD.expected_fencing_token
       OR NEW.reason IS DISTINCT FROM OLD.reason
       OR NEW.created_by IS DISTINCT FROM OLD.created_by
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.expires_at IS DISTINCT FROM OLD.expires_at
       OR NEW.consumed_run_id IS NULL
       OR NEW.consumed_at IS NULL THEN
        RAISE EXCEPTION 'scheduler bootstrap authorization is immutable except atomic one-time consumption'
            USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
END
$$;


ALTER FUNCTION public.trivia_competitive_bootstrap_authorization_guard() OWNER TO postgres;

--
-- TOC entry 7586 (class 1255 OID 111890083)
-- Name: trivia_competitive_certificate_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_competitive_certificate_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_previous integer;
    v_not_before timestamptz;
    v_ticket uuid;
    v_paid uuid;
    v_horse uuid;
    v_70 uuid;
    v_100 uuid;
    v_140 uuid;
    v_bootstrap uuid;
    v_run public.trivia_tournament_scheduler_runs%ROWTYPE;
    v_match public.trivia_pvp_matches%ROWTYPE;
BEGIN
    SELECT max(c.certificate_version) INTO v_previous
      FROM public.trivia_competitive_cutover_certificates c
     WHERE c.gate_key = NEW.gate_key;
    IF NEW.certificate_version <> COALESCE(v_previous, 0) + 1 THEN
        RAISE EXCEPTION 'certificate version must append exactly once for gate %', NEW.gate_key
            USING ERRCODE = '23514';
    END IF;
    IF NOT NEW.enabled THEN
        IF NEW.evidence <> '{}'::jsonb THEN
            RAISE EXCEPTION 'disabled certificate evidence must be empty' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    v_not_before := public.trivia_competitive_latest_disabled_at_v1(NEW.gate_key);
    IF v_not_before IS NULL THEN
        RAISE EXCEPTION 'enabled certificate requires a preceding disabled certificate for gate %', NEW.gate_key
            USING ERRCODE = '23514';
    END IF;
    IF NOT public.trivia_competitive_global_ledger_clean_v1() THEN
        RAISE EXCEPTION 'competitive cutover requires a clean reconciled ledger and zero terminal escrow'
            USING ERRCODE = 'P0001';
    END IF;

    IF NEW.gate_key = 'pvp_public' THEN
        -- Phase 5 intentionally supports only 10/25/50/100-Diamond matches.
        -- Its non-money canary is therefore an authoritative joined-then-
        -- cancelled queue ticket (join moves no Diamonds), not a fictional
        -- stake-0 match. The paid match below proves the full money/session path.
        v_ticket := (NEW.evidence ->> 'non_money_pvp_ticket_id')::uuid;
        v_paid := (NEW.evidence ->> 'paid_human_human_match_id')::uuid;
        IF v_ticket IS NULL OR v_paid IS NULL THEN
            RAISE EXCEPTION 'pvp_public requires non-money admission and paid match receipts';
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM public.trivia_pvp_queue q
             WHERE q.id = v_ticket AND q.engine_version = 'pvp-v2'
               AND q.stake_amount IN (10, 25, 50, 100)
               AND q.status IN ('cancelled', 'expired')
               AND q.match_id IS NULL AND q.matched_at IS NULL
               AND q.joined_at > v_not_before
               AND q.ended_at > v_not_before
               AND public.trivia_competitive_test_wallet_active_at_v1(
                       q.user_id, q.joined_at)) THEN
            RAISE EXCEPTION 'non-money PvP admission canary is not terminal, named or unmatched';
        END IF;
        IF NOT EXISTS (
            SELECT 1
              FROM public.trivia_pvp_matches m
              JOIN public.trivia_pvp_settlement_decisions d ON d.match_id = m.id
              JOIN public.trivia_settlements s
                ON s.subject_type = 'pvp_match' AND s.subject_id = m.id
             WHERE m.id = v_paid AND m.engine_version = 'pvp-v2'
               AND m.match_kind = 'human_human' AND m.stake_amount > 0
               AND m.status IN ('complete', 'completed')
               AND m.created_at > v_not_before
               AND m.completed_at > v_not_before
               AND d.decided_at > v_not_before
               AND s.terminal_at > v_not_before)
           OR NOT public.trivia_competitive_pvp_paid_ready_v1(v_paid) THEN
            RAISE EXCEPTION 'paid human PvP canary is not terminal, named or reconciled';
        END IF;
    ELSIF NEW.gate_key = 'pvp_horses' THEN
        IF NOT public.trivia_competitive_latest_enabled_v1('pvp_public') THEN
            RAISE EXCEPTION 'pvp_public must be certified before pvp_horses';
        END IF;
        v_horse := (NEW.evidence ->> 'paid_human_horse_match_id')::uuid;
        SELECT * INTO v_match FROM public.trivia_pvp_matches m WHERE m.id = v_horse;
        IF v_match.id IS NULL OR v_match.engine_version IS DISTINCT FROM 'pvp-v2'
           OR v_match.match_kind IS DISTINCT FROM 'human_horse'
           OR v_match.stake_amount <= 0 OR v_match.status NOT IN ('complete', 'completed')
           OR v_match.created_at <= v_not_before
           OR v_match.completed_at <= v_not_before
           OR NOT public.trivia_competitive_test_wallet_active_at_v1(
                    v_match.player1_id, v_match.created_at)
           OR NOT public.trivia_competitive_pvp_paid_ready_v1(v_horse)
           OR NOT EXISTS (
                SELECT 1
                  FROM public.trivia_pvp_settlement_decisions d
                  JOIN public.trivia_settlements s
                    ON s.subject_type = 'pvp_match' AND s.subject_id = d.match_id
                 WHERE d.match_id = v_horse
                   AND d.decided_at > v_not_before
                   AND s.terminal_at > v_not_before)
           OR NOT EXISTS (
                SELECT 1 FROM public.trivia_settlements s
                JOIN public.trivia_settlement_participants p ON p.settlement_id = s.id
                 WHERE s.subject_type = 'pvp_match' AND s.subject_id = v_horse
                   AND p.funding_source = 'treasury')
           OR public.trivia_competitive_treasury_available_v1() < 250 * 100 THEN
            RAISE EXCEPTION 'paid horse PvP canary or treasury reserve is not qualified';
        END IF;
    ELSIF NEW.gate_key = 'tournament_public' THEN
        v_70 := (NEW.evidence ->> 'zero_70_tournament_id')::uuid;
        v_100 := (NEW.evidence ->> 'zero_100_tournament_id')::uuid;
        v_140 := (NEW.evidence ->> 'zero_140_tournament_id')::uuid;
        v_paid := (NEW.evidence ->> 'paid_treasury_tournament_id')::uuid;
        IF v_70 IS NULL OR v_100 IS NULL OR v_140 IS NULL OR v_paid IS NULL
           OR cardinality(ARRAY[v_70, v_100, v_140, v_paid])
              <> cardinality(ARRAY(SELECT DISTINCT unnest(ARRAY[v_70, v_100, v_140, v_paid])))
           OR NOT public.trivia_competitive_tournament_canary_ready_v1(v_70, 70, false)
           OR NOT public.trivia_competitive_tournament_canary_ready_v1(v_100, 100, false)
           OR NOT public.trivia_competitive_tournament_canary_ready_v1(v_140, 140, false)
           OR NOT public.trivia_competitive_tournament_canary_ready_v1(v_paid, NULL, true)
           OR EXISTS (
                SELECT 1
                  FROM unnest(ARRAY[v_70, v_100, v_140, v_paid]) AS evidence(tournament_id)
                  JOIN public.trivia_tournaments t ON t.id = evidence.tournament_id
                  JOIN public.trivia_settlements s
                    ON s.subject_type = 'tournament' AND s.subject_id = t.id
                 WHERE t.created_at IS NULL OR t.created_at <= v_not_before
                    OR t.settled_at IS NULL OR t.settled_at <= v_not_before
                    OR s.terminal_at IS NULL OR s.terminal_at <= v_not_before
                    OR EXISTS (
                        SELECT 1 FROM public.trivia_tournament_entrants e
                         WHERE e.tournament_id = t.id
                           AND e.entry_state = 'entered'
                           AND e.entered_at <= v_not_before)) THEN
            RAISE EXCEPTION '70/100/140 zero-Diamond and paid treasury tournament canaries are required';
        END IF;
    ELSIF NEW.gate_key = 'tournament_horses' THEN
        IF NOT public.trivia_competitive_latest_enabled_v1('tournament_public') THEN
            RAISE EXCEPTION 'tournament_public must be certified before tournament_horses';
        END IF;
        v_paid := (NEW.evidence ->> 'paid_treasury_tournament_id')::uuid;
        IF NOT public.trivia_competitive_tournament_canary_ready_v1(v_paid, NULL, true)
           OR NOT EXISTS (
                SELECT 1
                  FROM public.trivia_tournaments t
                  JOIN public.trivia_settlements s
                    ON s.subject_type = 'tournament' AND s.subject_id = t.id
                 WHERE t.id = v_paid
                   AND t.created_at IS NOT NULL AND t.created_at > v_not_before
                   AND t.settled_at IS NOT NULL AND t.settled_at > v_not_before
                   AND s.terminal_at IS NOT NULL AND s.terminal_at > v_not_before
                   AND NOT EXISTS (
                        SELECT 1 FROM public.trivia_tournament_entrants e
                         WHERE e.tournament_id = t.id
                           AND e.entry_state = 'entered'
                           AND e.entered_at <= v_not_before))
           OR public.trivia_competitive_treasury_available_v1() < 140 * 10 THEN
            RAISE EXCEPTION 'paid horse tournament canary or treasury reserve is not qualified';
        END IF;
    ELSIF NEW.gate_key = 'tournament_scheduler' THEN
        IF NOT public.trivia_competitive_latest_enabled_v1('tournament_public') THEN
            RAISE EXCEPTION 'tournament_public must be certified before tournament_scheduler';
        END IF;
        v_bootstrap := (NEW.evidence ->> 'scheduler_bootstrap_authorization_id')::uuid;
        SELECT * INTO v_run
          FROM public.trivia_tournament_scheduler_runs r
         WHERE r.run_id = (NEW.evidence ->> 'scheduler_run_id')::uuid;
        IF v_run.run_id IS NULL
           OR v_run.job_identity IS DISTINCT FROM public.trivia_tournament_scheduler_job()
           OR v_run.outcome IS DISTINCT FROM 'owner'
           OR v_run.finished_at IS NULL
           OR v_run.started_at <= v_not_before
           OR v_run.finished_at <= v_not_before
           OR NOT v_run.healthy
           OR v_run.ticks <> 0
           OR v_run.actions <> '{}'::jsonb
           OR v_run.alerts <> '[]'::jsonb
           OR NOT EXISTS (
                SELECT 1
                  FROM public.trivia_p12_scheduler_bootstrap_authorizations a
                 WHERE a.authorization_id = v_bootstrap
                   AND a.job_identity = v_run.job_identity
                   AND a.holder_id = v_run.holder_id
                   AND a.expected_fencing_token = v_run.fencing_token
                   AND a.created_at > v_not_before
                   AND a.consumed_run_id = v_run.run_id
                   AND a.consumed_at > v_not_before)
           OR EXISTS (
                SELECT 1 FROM public.trivia_tournament_scheduler_runs r2
                 WHERE r2.run_id <> v_run.run_id AND r2.outcome = 'owner'
                   AND tstzrange(r2.started_at, COALESCE(r2.finished_at, 'infinity'::timestamptz), '[)')
                       && tstzrange(v_run.started_at, v_run.finished_at, '[)')) THEN
            RAISE EXCEPTION 'canonical non-overlapping healthy scheduler canary run is required';
        END IF;
    END IF;
    RETURN NEW;
END
$$;


ALTER FUNCTION public.trivia_competitive_certificate_guard() OWNER TO postgres;

--
-- TOC entry 7310 (class 1255 OID 111890097)
-- Name: trivia_competitive_cutover_status_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_competitive_cutover_status_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_gates jsonb;
    v_balance bigint;
    v_floor bigint;
    v_recovery jsonb;
BEGIN
    IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'service_role required' USING ERRCODE = '42501';
    END IF;
    SELECT COALESCE(jsonb_object_agg(x.gate_key, jsonb_build_object(
        'version', x.certificate_version,
        'enabled', x.enabled,
        'certificate_id', x.certificate_id,
        'created_at', x.created_at)), '{}'::jsonb)
      INTO v_gates
      FROM (SELECT DISTINCT ON (c.gate_key) c.*
              FROM public.trivia_competitive_cutover_certificates c
             ORDER BY c.gate_key, c.certificate_version DESC) x;
    SELECT COALESCE(a.balance, 0), COALESCE(a.min_balance, 0)
      INTO v_balance, v_floor
      FROM public.trivia_ledger_accounts a
     WHERE a.account_code = 'treasury:trivia';
    SELECT jsonb_build_object(
               'run_id', r.run_id,
               'outcome', r.outcome,
               'started_at', r.started_at,
               'finished_at', r.finished_at,
               'healthy', r.healthy,
               'success', COALESCE((r.result ->> 'success')::boolean, false),
               'tickets_expired', CASE WHEN r.result ->> 'tickets_expired' ~ '^[0-9]+$'
                    THEN (r.result ->> 'tickets_expired')::integer ELSE 0 END,
               'matches_scanned', CASE WHEN r.result ->> 'matches_scanned' ~ '^[0-9]+$'
                    THEN (r.result ->> 'matches_scanned')::integer ELSE 0 END,
               'settled', CASE WHEN r.result ->> 'settled' ~ '^[0-9]+$'
                    THEN (r.result ->> 'settled')::integer ELSE 0 END,
               'pending', CASE WHEN r.result ->> 'pending' ~ '^[0-9]+$'
                    THEN (r.result ->> 'pending')::integer ELSE 0 END,
               'failed', CASE WHEN r.result ->> 'failed' ~ '^[0-9]+$'
                    THEN (r.result ->> 'failed')::integer ELSE 0 END)
      INTO v_recovery
      FROM public.trivia_pvp_recovery_runs r
     -- A standby is informational and must never hide the most recent owner
     -- failure. Prefer the latest owner receipt; only fall back to the latest
     -- standby when recovery has never had an owner.
     ORDER BY (r.outcome = 'owner') DESC, r.started_at DESC, r.run_id DESC
     LIMIT 1;
    RETURN jsonb_build_object(
        'version', 1,
        'gates', v_gates,
        'named_test_wallet_count', (SELECT count(*) FROM public.trivia_competitive_test_wallets w WHERE w.revoked_at IS NULL),
        'ledger_clean', public.trivia_competitive_global_ledger_clean_v1(),
        'recovery_status', v_recovery,
        'treasury', jsonb_build_object('account', 'treasury:trivia',
            'balance', COALESCE(v_balance, 0), 'floor', COALESCE(v_floor, 0),
            'available', public.trivia_competitive_treasury_available_v1()));
END
$_$;


ALTER FUNCTION public.trivia_competitive_cutover_status_v1() OWNER TO postgres;

--
-- TOC entry 5956 (class 1255 OID 111890054)
-- Name: trivia_competitive_global_ledger_clean_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_competitive_global_ledger_clean_v1() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
    SELECT
        COALESCE((SELECT sum(l.amount) FROM public.trivia_ledger_lines l), 0) = 0
        AND NOT EXISTS (
            SELECT 1 FROM public.trivia_ledger_account_balances b WHERE b.drift <> 0)
        AND NOT EXISTS (
            SELECT 1 FROM public.trivia_ledger_recon_reference r
             WHERE r.state NOT IN ('reconciled', 'reconciled_archived', 'legacy_path_switch_off'))
        AND NOT EXISTS (
            SELECT 1 FROM public.trivia_ledger_recon_settlement s
             WHERE NOT (
                       (s.subject_type = 'pvp_match' AND EXISTS (
                            SELECT 1 FROM public.trivia_pvp_matches source_match
                             WHERE source_match.id = s.subject_id))
                       OR
                       (s.subject_type = 'tournament' AND EXISTS (
                            SELECT 1 FROM public.trivia_tournaments source_tournament
                             WHERE source_tournament.id = s.subject_id))
                   )
                OR (s.terminal AND (
                        s.nonzero_terminal_escrow
                        OR s.unexplained_variance <> 0
                   ))
                OR (NOT s.terminal AND (
                        s.unexplained_variance <> 0
                        OR CASE s.subject_type
                            WHEN 'pvp_match' THEN NOT EXISTS (
                                SELECT 1
                                  FROM public.trivia_pvp_matches m
                                 WHERE m.id = s.subject_id
                                   AND m.engine_version = 'pvp-v2'
                                   AND m.status IN ('pending', 'active', 'settling')
                                   AND m.deadline_at > pg_catalog.clock_timestamp()
                            )
                            WHEN 'tournament' THEN NOT EXISTS (
                                SELECT 1
                                  FROM public.trivia_tournaments t
                                 WHERE t.id = s.subject_id
                                   AND t.engine_version IS NOT NULL
                                   AND t.lifecycle_state IN (
                                       'scheduled', 'registration', 'held', 'live', 'settling')
                                   AND (
                                       (t.lifecycle_state IN ('scheduled', 'registration', 'held', 'live')
                                        AND t.end_time > pg_catalog.clock_timestamp())
                                       OR
                                       (t.lifecycle_state = 'settling'
                                        AND t.final_resolved_at IS NOT NULL
                                        AND (t.format_snapshot ->> 'settlement_sla_seconds') ~ '^[0-9]+$'
                                        AND t.final_resolved_at
                                            + pg_catalog.make_interval(secs =>
                                                (t.format_snapshot ->> 'settlement_sla_seconds')::integer)
                                            > pg_catalog.clock_timestamp())
                                   )
                            )
                            ELSE true
                           END
                   )))
        AND NOT EXISTS (
            SELECT 1 FROM public.trivia_ledger_recon_treasury t WHERE t.drift <> 0)
$_$;


ALTER FUNCTION public.trivia_competitive_global_ledger_clean_v1() OWNER TO postgres;

