-- TOC entry 3483 (class 1255 OID 111890110)
-- Name: trivia_competitive_tournament_canary_access_cutover(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_competitive_tournament_canary_access_cutover() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF NOT public.trivia_competitive_test_wallet_active_v1(NEW.user_id) THEN
        RAISE EXCEPTION 'tournament canary access requires an active named test wallet'
            USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
END
$$;


