-- TOC entry 4201 (class 1255 OID 111890050)
-- Name: trivia_competitive_treasury_available_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_competitive_treasury_available_v1() RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT COALESCE((
        SELECT a.balance - COALESCE(a.min_balance, 0)
          FROM public.trivia_ledger_accounts a
         WHERE a.account_code = 'treasury:trivia'
           AND a.kind = 'treasury'
           AND a.state = 'open'
    ), 0)::bigint
$$;


