--

CREATE FUNCTION public.trivia_ledger_switch_at(p_key text, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
