CREATE FUNCTION public.trivia_option_permutation_v1(p_secret bytea, p_session_id uuid, p_question_id uuid, p_n integer) RETURNS integer[]
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public'
