--
-- TOC entry 4366 (class 1255 OID 111881637)
-- Name: trivia_p11_grant_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_p11_grant_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    IF TG_OP IN ('DELETE', 'TRUNCATE') THEN
        RAISE EXCEPTION 'Trivia operator grants cannot be deleted' USING ERRCODE = '42501';
    END IF;
    IF OLD.operator_id IS DISTINCT FROM NEW.operator_id
       OR OLD.role_key IS DISTINCT FROM NEW.role_key
       OR OLD.granted_by IS DISTINCT FROM NEW.granted_by
       OR OLD.grant_reason IS DISTINCT FROM NEW.grant_reason
       OR OLD.granted_at IS DISTINCT FROM NEW.granted_at
       OR OLD.active = false OR NEW.active = true
       OR NEW.revoked_at IS NULL OR NEW.revoked_by IS NULL OR NEW.revoke_reason IS NULL THEN
        RAISE EXCEPTION 'Trivia operator grants can only transition once from active to revoked'
            USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
END
$$;


ALTER FUNCTION public.trivia_p11_grant_guard() OWNER TO postgres;

--
-- TOC entry 3699 (class 1255 OID 115336429)
-- Name: trivia_p11_guard_rake_mutation_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_p11_guard_rake_mutation_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    IF NEW.rake_amount > OLD.rake_amount
       AND (SELECT c.action
              FROM public.trivia_settlement_payout_controls_v1 c
             WHERE c.settlement_id = OLD.id
             ORDER BY c.control_id DESC
             LIMIT 1) = 'hold' THEN
        RAISE EXCEPTION USING
            ERRCODE = 'TL001',
            MESSAGE = 'settlement_payout_held',
            DETAIL = jsonb_build_object(
                'settlement_id', OLD.id,
                'operation', 'rake',
                'cutoverFence', true
            )::text;
    END IF;
    RETURN NEW;
END
$$;


