--
-- TOC entry 2001 (class 1259 OID 10827728)
-- Name: trivia_sessions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.trivia_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    mode text NOT NULL,
    question_ids uuid[] NOT NULL,
    permutations jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    submitted_at timestamp with time zone,
    score integer,
    correct_count integer,
    diamonds_awarded integer,
    status text DEFAULT 'open'::text NOT NULL,
    answers jsonb DEFAULT '{}'::jsonb NOT NULL,
    parent_session_id uuid,
    entry_cost integer DEFAULT 0 NOT NULL,
    entry_state text DEFAULT 'legacy'::text NOT NULL,
    expires_at timestamp with time zone,
    survival_run_id uuid,
    survival_level integer,
    settlement_result jsonb,
    stats_recorded_at timestamp with time zone,
    rules_version_id text,
    rules_sha256 text,
    engine_version text,
    roster_snapshot_id uuid,
    roster_round_no integer,
    roster_profile_id text,
    seat_key text,
    actor_type text,
    session_contract jsonb,
    contract_signature text,
    settlement_request_id uuid,
    question_revision_ids jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT trivia_sessions_engine_v3_binding_check CHECK (((engine_version IS NULL) OR ((engine_version = 'trivia-engine/3'::text) AND (roster_snapshot_id IS NOT NULL) AND (roster_round_no IS NOT NULL) AND (roster_profile_id IS NOT NULL) AND (seat_key IS NOT NULL) AND (actor_type = ANY (ARRAY['human'::text, 'horse'::text])) AND (session_contract IS NOT NULL) AND (contract_signature IS NOT NULL) AND (expires_at IS NOT NULL)))),
    CONSTRAINT trivia_sessions_entry_state_check CHECK ((entry_state = ANY (ARRAY['legacy'::text, 'free'::text, 'vip'::text, 'charged'::text, 'continuation'::text, 'ticket'::text]))),
    CONSTRAINT trivia_sessions_status_check CHECK ((status = ANY (ARRAY['open'::text, 'submitted'::text, 'expired'::text])))
);


