--
-- TOC entry 6741 (class 1255 OID 74744053)
-- Name: trivia_p3_solo_review(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_p3_solo_review(p_session_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
    SELECT coalesce(jsonb_agg(
        CASE WHEN a.server_voided_at IS NOT NULL OR pq ->> 'outcome' = 'void' THEN
            jsonb_build_object(
                'questionId', a.question_id,
                'wasCorrect', false,
                'outcome', 'void',
                'voided', true)
        ELSE
            jsonb_build_object(
                'questionId', a.question_id,
                'wasCorrect', coalesce(a.is_correct, false),
                'correctDisplayIndex', (
                    SELECT (e.ord - 1)::integer
                      FROM jsonb_array_elements_text(s.permutations -> a.question_id::text)
                           WITH ORDINALITY e(value, ord)
                     WHERE e.value::integer = r.correct_index),
                'outcome', pq ->> 'outcome',
                'voided', false)
        END ORDER BY a.position), '[]'::jsonb)
      FROM public.trivia_sessions s
      JOIN public.trivia_session_answers a ON a.session_id = s.id
      JOIN public.trivia_question_revisions r
        ON r.id = a.revision_id AND r.question_id = a.question_id
      LEFT JOIN public.trivia_session_results result_row ON result_row.session_id = s.id
      LEFT JOIN LATERAL (
          SELECT item.value
            FROM jsonb_array_elements(coalesce(result_row.per_question, '[]'::jsonb)) item(value)
           WHERE (item.value ->> 'position')::integer = a.position
      ) result_item(pq) ON true
     WHERE s.id = p_session_id
       AND s.status <> 'open'
       AND s.mode NOT IN ('pvp','tournaments')
$$;


ALTER FUNCTION public.trivia_p3_solo_review(p_session_id uuid) OWNER TO postgres;

--
-- TOC entry 8740 (class 1255 OID 74744026)
-- Name: trivia_p3_store_snapshot(text, text, text, text, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_p3_store_snapshot(p_scope_kind text, p_scope_id text, p_profile_id text, p_label text, p_as_of timestamp with time zone, p_rounds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_id uuid := gen_random_uuid();
    v_p public.trivia_roster_profiles%ROWTYPE;
    v_hash text; v_n integer; v_policy integer; v_contract jsonb; v_secret bytea;
BEGIN
    SELECT * INTO v_p FROM public.trivia_roster_profiles WHERE profile_id = p_profile_id;
    SELECT policy_version INTO v_policy FROM public.trivia_eligibility_policies ORDER BY policy_version DESC LIMIT 1;
    SELECT count(*), public.trivia_sha256_hex_v1(string_agg(round_no || ':' || pos || ':' || question_id || ':' || revision_id,
               ',' ORDER BY round_no, pos))
      INTO v_n, v_hash FROM pg_temp.trivia_p3_plan;
    v_secret := public.trivia_engine_secret_v1('roster-v1');
    v_contract := jsonb_build_object('contract', 'trivia-roster/1', 'snapshot_id', v_id, 'scope_kind', p_scope_kind,
        'scope_id', p_scope_id, 'profile_id', p_profile_id, 'rules_key', v_p.rules_key, 'mode', v_p.mode,
        'rounds', p_rounds, 'question_count', v_n, 'roster_hash', v_hash, 'policy_version', v_policy,
        'engine_version', 'trivia-engine/3', 'selection_version', 'trivia-select/1', 'as_of', p_as_of);
    INSERT INTO public.trivia_roster_snapshots (id, scope_kind, scope_id, profile_id, mode, policy_version,
        seed_commitment, as_of, rounds, question_count, roster_hash, contract, signature)
    VALUES (v_id, p_scope_kind, p_scope_id, p_profile_id, v_p.mode, v_policy,
        encode(extensions.digest(public.trivia_hmac_v1(v_secret, 'trivia-seed/1:' || p_label), 'sha256'), 'hex'),
        p_as_of, p_rounds, v_n, v_hash, v_contract,
        encode(public.trivia_hmac_v1(public.trivia_engine_secret_v1('contract-v1'), v_contract::text), 'hex'));
    INSERT INTO public.trivia_roster_snapshot_items (snapshot_id, round_no, position, question_id, revision_id,
        canonical_question_id, category, difficulty, selection_tier)
    SELECT v_id, round_no, pos, question_id, revision_id, canonical_question_id, category, difficulty, tier
      FROM pg_temp.trivia_p3_plan;
    RETURN jsonb_build_object('success', true, 'duplicate', false, 'snapshot_id', v_id, 'scope_kind', p_scope_kind,
        'scope_id', p_scope_id, 'profile_id', p_profile_id, 'rounds', p_rounds, 'question_count', v_n,
        'roster_hash', v_hash, 'policy_version', v_policy, 'engine_version', 'trivia-engine/3');
END $$;


ALTER FUNCTION public.trivia_p3_store_snapshot(p_scope_kind text, p_scope_id text, p_profile_id text, p_label text, p_as_of timestamp with time zone, p_rounds integer) OWNER TO postgres;

--
-- TOC entry 3385 (class 1255 OID 110226023)
-- Name: trivia_p8_legacy_grade_locked_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_p8_legacy_grade_locked_v1(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    s public.trivia_sessions%ROWTYPE;
    r public.trivia_question_revisions%ROWTYPE;
    v_lock jsonb;
    v_bound record;
    v_total integer;
    v_voided integer := 0;
    v_answered integer := 0;
    v_correct integer := 0;
    v_points integer;
    v_revision_id uuid;
    v_stored jsonb;
    v_perm jsonb;
    v_indexes integer[];
    v_expected integer[];
    v_seen_ordinals integer[] := '{}'::integer[];
    v_answer_ordinal integer;
    v_display integer;
    v_original integer;
    v_correct_display integer;
    v_was_correct boolean;
    v_at timestamptz;
    v_review jsonb := '[]'::jsonb;
BEGIN
    v_lock := public.trivia_p8_lock_and_void_session_questions_v1(p_session_id);
    IF coalesce((v_lock ->> 'success')::boolean, false) IS NOT TRUE THEN RETURN v_lock; END IF;
    SELECT * INTO s FROM public.trivia_sessions WHERE id = p_session_id;
    IF s.engine_version IS NOT NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_legacy_session');
    END IF;
    v_total := coalesce(cardinality(s.question_ids), 0);
    IF jsonb_typeof(s.answers) IS DISTINCT FROM 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
    END IF;
    IF EXISTS (
            SELECT 1 FROM jsonb_object_keys(s.answers) answer_key(key)
             WHERE NOT EXISTS (
                 SELECT 1 FROM unnest(s.question_ids) q(question_id)
                  WHERE q.question_id::text = answer_key.key)) THEN
        RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
    END IF;
    v_points := CASE s.mode
        WHEN 'arcade' THEN 200 WHEN 'survival' THEN 200 WHEN 'endless' THEN 200
        WHEN 'time-attack' THEN 200 WHEN 'tournaments' THEN 200 WHEN 'gto' THEN 150
        ELSE 100 END;

    FOR v_bound IN
        SELECT q.question_id, q.ordinality::integer AS position
          FROM unnest(s.question_ids) WITH ORDINALITY q(question_id, ordinality)
         ORDER BY q.ordinality
    LOOP
        BEGIN
            v_revision_id := (s.question_revision_ids ->> v_bound.question_id::text)::uuid;
        EXCEPTION WHEN invalid_text_representation THEN
            v_revision_id := NULL;
        END;
        SELECT * INTO r FROM public.trivia_question_revisions
         WHERE id = v_revision_id AND question_id = v_bound.question_id;
        IF NOT FOUND THEN
            RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
        END IF;
        IF jsonb_typeof(r.options) IS DISTINCT FROM 'array' OR jsonb_array_length(r.options) < 1 THEN
            RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
        END IF;
        v_perm := s.permutations -> v_bound.question_id::text;
        IF jsonb_typeof(v_perm) IS DISTINCT FROM 'array'
           OR jsonb_array_length(v_perm) <> jsonb_array_length(r.options)
           OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_perm) e(value)
                       WHERE jsonb_typeof(e.value) IS DISTINCT FROM 'number'
                          OR e.value::text !~ '^[0-9]+$') THEN
            RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
        END IF;
        SELECT array_agg(e.value::text::integer ORDER BY e.value::text::integer)
          INTO v_indexes FROM jsonb_array_elements(v_perm) e(value);
        SELECT array_agg(i ORDER BY i) INTO v_expected
          FROM generate_series(0, jsonb_array_length(r.options) - 1) i;
        IF v_indexes IS DISTINCT FROM v_expected
           OR r.correct_index < 0 OR r.correct_index >= jsonb_array_length(r.options) THEN
            RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
        END IF;
        SELECT (e.ordinality - 1)::integer INTO v_correct_display
          FROM jsonb_array_elements(v_perm) WITH ORDINALITY e(value, ordinality)
         WHERE e.value::text::integer = r.correct_index;
        IF v_correct_display IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
        END IF;

        v_stored := s.answers -> v_bound.question_id::text;
        IF v_stored -> 'v' = 'true'::jsonb THEN
            IF jsonb_typeof(v_stored) IS DISTINCT FROM 'object' THEN
                RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
            END IF;
            IF (SELECT count(*) FROM jsonb_object_keys(v_stored)) <> 5
               OR NOT (v_stored ?& ARRAY['d','n','at','v','vr'])
               OR v_stored -> 'v' IS DISTINCT FROM 'true'::jsonb
               OR v_stored ->> 'd' IS DISTINCT FROM '-1'
               OR jsonb_typeof(v_stored -> 'n') IS DISTINCT FROM 'number'
               OR coalesce(v_stored ->> 'n', '') !~ '^[0-9]+$'
               OR (v_stored ->> 'n')::integer <> v_bound.position - 1
               OR jsonb_typeof(v_stored -> 'at') IS DISTINCT FROM 'string'
               OR coalesce(v_stored ->> 'vr', '') NOT IN ('structural','audit','quarantine') THEN
                RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
            END IF;
            BEGIN
                v_at := (v_stored ->> 'at')::timestamptz;
            EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
                RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
            END;
            v_voided := v_voided + 1;
            v_review := v_review || jsonb_build_array(jsonb_build_object(
                'questionId', v_bound.question_id, 'wasCorrect', false,
                'correctDisplayIndex', -1, 'outcome', 'voided', 'voided', true));
            CONTINUE;
        END IF;

        v_was_correct := false;
        IF v_stored IS NOT NULL THEN
            IF jsonb_typeof(v_stored) IS DISTINCT FROM 'object' THEN
                RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
            END IF;
            IF (SELECT count(*) FROM jsonb_object_keys(v_stored)) <> 3
               OR NOT (v_stored ?& ARRAY['d','n','at'])
               OR jsonb_typeof(v_stored -> 'd') IS DISTINCT FROM 'number'
               OR coalesce(v_stored ->> 'd', '') !~ '^-?[0-9]+$'
               OR jsonb_typeof(v_stored -> 'n') IS DISTINCT FROM 'number'
               OR coalesce(v_stored ->> 'n', '') !~ '^[0-9]+$'
               OR jsonb_typeof(v_stored -> 'at') IS DISTINCT FROM 'string' THEN
                RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
            END IF;
            v_display := (v_stored ->> 'd')::integer;
            v_answer_ordinal := (v_stored ->> 'n')::integer;
            IF v_display < -1 OR v_display >= jsonb_array_length(r.options)
               OR v_answer_ordinal < 0 OR v_answer_ordinal >= v_total
               OR v_seen_ordinals @> ARRAY[v_answer_ordinal] THEN
                RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
            END IF;
            BEGIN
                v_at := (v_stored ->> 'at')::timestamptz;
            EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
                RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
            END;
            v_seen_ordinals := array_append(v_seen_ordinals, v_answer_ordinal);
            v_answered := v_answered + 1;
            IF v_display >= 0 THEN
                v_original := (v_perm ->> v_display)::integer;
                v_was_correct := v_original = r.correct_index;
            END IF;
        ELSE
            v_display := -1;
        END IF;
        IF v_was_correct THEN v_correct := v_correct + 1; END IF;
        v_review := v_review || jsonb_build_array(jsonb_build_object(
            'questionId', v_bound.question_id, 'wasCorrect', v_was_correct,
            'correctDisplayIndex', v_correct_display,
            'outcome', CASE WHEN v_was_correct THEN 'correct' ELSE 'wrong' END,
            'voided', false));
    END LOOP;
    RETURN jsonb_build_object(
        'success', true, 'total', v_total, 'graded_total', v_total - v_voided,
        'answered', v_answered, 'completion_answered', v_answered + v_voided,
        'correct', v_correct, 'voided', v_voided, 'score', v_correct * v_points,
        'per_question', v_review);
END $_$;


ALTER FUNCTION public.trivia_p8_legacy_grade_locked_v1(p_session_id uuid) OWNER TO postgres;

--
-- TOC entry 8451 (class 1255 OID 110226002)
-- Name: trivia_p8_lock_and_void_session_questions_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_p8_lock_and_void_session_questions_v1(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    s public.trivia_sessions%ROWTYPE;
    a public.trivia_session_answers%ROWTYPE;
    v_bound record;
    v_total integer;
    v_count integer;
    v_next_sequence integer;
    v_reason text;
    v_revision_id uuid;
    v_answers jsonb;
    v_stored jsonb;
    v_options jsonb;
    v_at timestamptz;
    v_now timestamptz := clock_timestamp();
    v_changed boolean := false;
BEGIN
    SELECT * INTO s FROM public.trivia_sessions WHERE id = p_session_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'session_not_found'); END IF;
    v_total := coalesce(cardinality(s.question_ids), 0);
    IF v_total < 1 OR (SELECT count(DISTINCT qid) FROM unnest(s.question_ids) q(qid)) <> v_total THEN
        RETURN jsonb_build_object('success', false, 'error', 'session_roster_invalid');
    END IF;

    SELECT count(*) INTO v_count FROM (
        SELECT q.id FROM public.trivia_questions q
         WHERE q.id = ANY(s.question_ids) ORDER BY q.id FOR UPDATE
    ) locked_questions;
    IF v_count <> v_total THEN
        RETURN jsonb_build_object('success', false, 'error', 'question_validation_failed');
    END IF;
    PERFORM z.id FROM public.trivia_question_quarantine z
     WHERE z.question_id = ANY(s.question_ids) AND z.released_at IS NULL
     ORDER BY z.question_id, z.id FOR UPDATE;

    IF s.engine_version IS NOT NULL THEN
        SELECT count(*) INTO v_count FROM (
            SELECT x.position FROM public.trivia_session_answers x
             WHERE x.session_id = s.id ORDER BY x.position FOR UPDATE
        ) locked_answers;
        IF v_count <> v_total OR EXISTS (
            SELECT 1
              FROM unnest(s.question_ids) WITH ORDINALITY q(question_id, position)
              LEFT JOIN public.trivia_session_answers x
                ON x.session_id = s.id AND x.position = q.position
               AND x.question_id = q.question_id
             WHERE x.session_id IS NULL) THEN
            RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
        END IF;
        SELECT coalesce(max(sequence), 0) + 1 INTO v_next_sequence
          FROM public.trivia_session_answers WHERE session_id = s.id;
        FOR a IN
            SELECT * FROM public.trivia_session_answers
             WHERE session_id = s.id ORDER BY position
        LOOP
            SELECT CASE
                       WHEN r.structurally_valid IS FALSE THEN 'structural'
                       WHEN q.audit_verified IS FALSE THEN 'audit'
                       WHEN EXISTS (
                           SELECT 1 FROM public.trivia_question_quarantine z
                            WHERE z.question_id = a.question_id AND z.released_at IS NULL)
                           THEN 'quarantine'
                   END
              INTO v_reason
              FROM public.trivia_question_revisions r
              JOIN public.trivia_questions q ON q.id = r.question_id
             WHERE r.id = a.revision_id AND r.question_id = a.question_id;
            IF NOT FOUND THEN
                RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
            END IF;
            IF v_reason IS NOT NULL AND a.server_voided_at IS NULL THEN
                UPDATE public.trivia_session_answers
                   SET answered_at = coalesce(a.answered_at, v_now),
                       display_index = -1, original_index = NULL, is_correct = false,
                       outcome = 'skip',
                       sequence = coalesce(a.sequence, v_next_sequence),
                       server_voided_at = v_now, server_void_reason = v_reason
                 WHERE session_id = s.id AND position = a.position;
                IF a.sequence IS NULL THEN v_next_sequence := v_next_sequence + 1; END IF;
            END IF;
        END LOOP;
        RETURN jsonb_build_object('success', true);
    END IF;

    IF jsonb_typeof(s.question_revision_ids) IS DISTINCT FROM 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
    END IF;
    IF (SELECT count(*) FROM jsonb_object_keys(s.question_revision_ids)) <> v_total
       OR EXISTS (SELECT 1 FROM jsonb_object_keys(s.question_revision_ids) k(key)
                   WHERE NOT EXISTS (
                       SELECT 1 FROM unnest(s.question_ids) q(question_id)
                        WHERE q.question_id::text = k.key)) THEN
        RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
    END IF;
    IF jsonb_typeof(s.answers) IS DISTINCT FROM 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
    END IF;
    v_answers := s.answers;
    FOR v_bound IN
        SELECT q.question_id, q.ordinality::integer AS position
          FROM unnest(s.question_ids) WITH ORDINALITY q(question_id, ordinality)
         ORDER BY q.ordinality
    LOOP
        BEGIN
            v_revision_id := (s.question_revision_ids ->> v_bound.question_id::text)::uuid;
        EXCEPTION WHEN invalid_text_representation THEN
            v_revision_id := NULL;
        END;
        IF v_revision_id IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
        END IF;
        SELECT CASE
                   WHEN r.structurally_valid IS FALSE THEN 'structural'
                   WHEN q.audit_verified IS FALSE THEN 'audit'
                   WHEN EXISTS (
                       SELECT 1 FROM public.trivia_question_quarantine z
                        WHERE z.question_id = v_bound.question_id AND z.released_at IS NULL)
                       THEN 'quarantine'
               END, r.options
          INTO v_reason, v_options
          FROM public.trivia_question_revisions r
          JOIN public.trivia_questions q ON q.id = r.question_id
         WHERE r.id = v_revision_id AND r.question_id = v_bound.question_id;
        IF NOT FOUND THEN
            RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
        END IF;
        IF v_reason IS NOT NULL THEN
            v_stored := v_answers -> v_bound.question_id::text;
            -- Once authority has neutralized a legacy answer, that exact
            -- evidence is immutable even if the current invalidity reason
            -- later changes. Reject a malformed marker rather than repairing
            -- history into a different server claim.
            IF v_stored -> 'v' = 'true'::jsonb THEN
                IF jsonb_typeof(v_stored) IS DISTINCT FROM 'object' THEN
                    RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
                END IF;
                IF (SELECT count(*) FROM jsonb_object_keys(v_stored)) <> 5
                   OR NOT (v_stored ?& ARRAY['d','n','at','v','vr'])
                   OR v_stored -> 'v' IS DISTINCT FROM 'true'::jsonb
                   OR v_stored ->> 'd' IS DISTINCT FROM '-1'
                   OR jsonb_typeof(v_stored -> 'n') IS DISTINCT FROM 'number'
                   OR coalesce(v_stored ->> 'n', '') !~ '^[0-9]+$'
                   OR (v_stored ->> 'n')::integer <> v_bound.position - 1
                   OR jsonb_typeof(v_stored -> 'at') IS DISTINCT FROM 'string'
                   OR coalesce(v_stored ->> 'vr', '') NOT IN ('structural','audit','quarantine') THEN
                    RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
                END IF;
                BEGIN
                    v_at := (v_stored ->> 'at')::timestamptz;
                EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
                    RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
                END;
                CONTINUE;
            END IF;
            IF v_stored IS NOT NULL THEN
                IF jsonb_typeof(v_options) IS DISTINCT FROM 'array' THEN
                    RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
                END IF;
                IF jsonb_array_length(v_options) < 1 THEN
                    RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
                END IF;
                IF jsonb_typeof(v_stored) IS DISTINCT FROM 'object' THEN
                    RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
                END IF;
                IF (SELECT count(*) FROM jsonb_object_keys(v_stored)) <> 3
                   OR NOT (v_stored ?& ARRAY['d','n','at'])
                   OR jsonb_typeof(v_stored -> 'd') IS DISTINCT FROM 'number'
                   OR coalesce(v_stored ->> 'd', '') !~ '^-?[0-9]+$'
                   OR (v_stored ->> 'd')::integer < -1
                   OR (v_stored ->> 'd')::integer >= jsonb_array_length(v_options)
                   OR jsonb_typeof(v_stored -> 'n') IS DISTINCT FROM 'number'
                   OR coalesce(v_stored ->> 'n', '') !~ '^[0-9]+$'
                   OR (v_stored ->> 'n')::integer < 0
                   OR (v_stored ->> 'n')::integer >= v_total
                   OR jsonb_typeof(v_stored -> 'at') IS DISTINCT FROM 'string'
                   OR EXISTS (
                        SELECT 1 FROM jsonb_each(v_answers) other(key, value)
                         WHERE other.key <> v_bound.question_id::text
                           AND other.value -> 'v' IS DISTINCT FROM 'true'::jsonb
                           AND jsonb_typeof(other.value -> 'n') = 'number'
                           AND coalesce(other.value ->> 'n', '') ~ '^[0-9]+$'
                           AND (other.value ->> 'n')::integer = (v_stored ->> 'n')::integer) THEN
                    RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
                END IF;
                BEGIN
                    v_at := (v_stored ->> 'at')::timestamptz;
                EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
                    RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
                END;
            END IF;
            v_at := v_now;
            BEGIN
                IF jsonb_typeof(v_stored -> 'at') = 'string' THEN
                    v_at := (v_stored ->> 'at')::timestamptz;
                END IF;
            EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
                v_at := v_now;
            END;
            v_answers := jsonb_set(v_answers, ARRAY[v_bound.question_id::text],
                jsonb_build_object('d', -1, 'n', v_bound.position - 1, 'at', v_at,
                    'v', true, 'vr', v_reason), true);
            v_changed := true;
        END IF;
    END LOOP;
    IF v_changed AND v_answers IS DISTINCT FROM s.answers THEN
        UPDATE public.trivia_sessions SET answers = v_answers WHERE id = s.id;
    END IF;
    RETURN jsonb_build_object('success', true);
END $_$;


ALTER FUNCTION public.trivia_p8_lock_and_void_session_questions_v1(p_session_id uuid) OWNER TO postgres;

--
-- TOC entry 9501 (class 1255 OID 115338715)
-- Name: trivia_paid_skip_adopt_legacy_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_paid_skip_adopt_legacy_v1(p_session_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    s public.trivia_sessions%ROWTYPE;
    v_receipt_count integer;
    v_candidate_count integer;
    v_ordinal integer;
    v_sequence integer;
    v_answer_order integer;
    v_binding text;
    v_row record;
BEGIN
    SELECT * INTO s FROM public.trivia_sessions WHERE id=p_session_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','session_not_found'); END IF;
    IF s.user_id IS DISTINCT FROM p_user_id THEN
        RETURN jsonb_build_object('success',false,'error','not_your_session');
    END IF;
    IF s.mode NOT IN ('endless','survival') THEN
        RETURN jsonb_build_object('success',true,'adopted',0);
    END IF;

    IF EXISTS (
        SELECT 1
          FROM unnest(s.question_ids) WITH ORDINALITY q(question_id,position)
          JOIN public.diamond_transactions t ON t.user_id=s.user_id
           AND t.reference_id IN (
               'trivia_lifeline:'||s.id::text||':'||q.question_id::text||':skip',
               'spend:'||s.user_id::text||':trivia_lifeline:'||s.id::text||':'||q.question_id::text||':skip')
          LEFT JOIN public.trivia_session_answers a
            ON a.session_id=s.id AND a.question_id=q.question_id
         WHERE t.amount IS DISTINCT FROM -5
            OR coalesce(t.transaction_type,t.type) IS DISTINCT FROM 'trivia_lifeline'
            OR t.counterparty IS DISTINCT FROM 'revenue:trivia_lifeline'
            OR t.issuance_class IS DISTINCT FROM 'spend'
            OR t.balance_after IS NULL OR t.balance_after<0
            OR t.created_at<s.created_at
            OR t.created_at>coalesce(CASE WHEN s.status='submitted' THEN s.submitted_at END,
                                         s.expires_at,clock_timestamp())
            OR (s.engine_version IS NOT NULL AND
                (a.question_id IS NULL OR a.server_voided_at IS NOT NULL OR a.outcome IS NOT NULL AND
                 (a.outcome IS DISTINCT FROM 'skip' OR a.display_index IS DISTINCT FROM -1)))
            OR (s.engine_version IS NULL AND
                (jsonb_typeof(s.answers) IS DISTINCT FROM 'object'
                 OR s.answers?q.question_id::text AND
                    ((s.answers->q.question_id::text)->'v'='true'::jsonb
                     OR (s.answers->q.question_id::text)->>'d' IS DISTINCT FROM '-1')))
    ) THEN
        RETURN jsonb_build_object('success',false,'error','malformed_legacy_paid_skip_evidence');
    END IF;
    IF EXISTS (
        SELECT 1
          FROM unnest(s.question_ids) q(question_id)
          JOIN public.diamond_transactions t ON t.user_id=s.user_id
           AND t.reference_id IN (
               'trivia_lifeline:'||s.id::text||':'||q.question_id::text||':skip',
               'spend:'||s.user_id::text||':trivia_lifeline:'||s.id::text||':'||q.question_id::text||':skip')
         GROUP BY q.question_id HAVING count(*)>1
    ) THEN
        RETURN jsonb_build_object('success',false,'error','ambiguous_paid_skip_debit');
    END IF;

    SELECT count(*)::integer INTO v_receipt_count
      FROM public.trivia_paid_skip_receipts_v1 WHERE session_id=s.id;
    SELECT count(*)::integer INTO v_candidate_count
      FROM unnest(s.question_ids) q(question_id)
      JOIN public.diamond_transactions t ON t.user_id=s.user_id
       AND t.reference_id IN (
           'trivia_lifeline:'||s.id::text||':'||q.question_id::text||':skip',
           'spend:'||s.user_id::text||':trivia_lifeline:'||s.id::text||':'||q.question_id::text||':skip')
     WHERE NOT EXISTS (
         SELECT 1 FROM public.trivia_paid_skip_receipts_v1 r
          WHERE r.session_id=s.id AND r.question_id=q.question_id);
    IF v_receipt_count+v_candidate_count>3 THEN
        RETURN jsonb_build_object('success',false,'error','legacy_paid_skip_cap_exceeded');
    END IF;
    v_ordinal:=v_receipt_count;

    FOR v_row IN
        SELECT q.question_id,q.position::integer,a.outcome,a.client_nonce,
               t.id transaction_id,t.reference_id,t.balance_after,t.created_at
          FROM unnest(s.question_ids) WITH ORDINALITY q(question_id,position)
          LEFT JOIN public.trivia_session_answers a
            ON a.session_id=s.id AND a.question_id=q.question_id
          JOIN public.diamond_transactions t ON t.user_id=s.user_id
           AND t.reference_id IN (
               'trivia_lifeline:'||s.id::text||':'||q.question_id::text||':skip',
               'spend:'||s.user_id::text||':trivia_lifeline:'||s.id::text||':'||q.question_id::text||':skip')
         WHERE NOT EXISTS (
             SELECT 1 FROM public.trivia_paid_skip_receipts_v1 r
              WHERE r.session_id=s.id AND r.question_id=q.question_id)
         ORDER BY t.created_at,q.position
    LOOP
        v_ordinal:=v_ordinal+1;
        v_binding:=CASE WHEN (s.engine_version IS NOT NULL AND v_row.outcome IS NOT NULL)
                              OR (s.engine_version IS NULL AND s.answers?v_row.question_id::text)
                        THEN 'legacy_bound_answer' ELSE 'legacy_ledger_only' END;
        INSERT INTO public.trivia_paid_skip_receipts_v1(
            session_id,user_id,question_id,position,paid_skip_ordinal,
            policy_version,source_binding,policy_unit_cost,policy_session_limit,
            entitlement,diamonds_charged,spend_reference,wallet_transaction_id,
            balance_after,client_nonce,recorded_at)
        VALUES(s.id,s.user_id,v_row.question_id,v_row.position,v_ordinal,
            'paid-skip-legacy@1',v_binding,5,3,'diamonds',5,v_row.reference_id,
            v_row.transaction_id,v_row.balance_after,v_row.client_nonce,v_row.created_at);

        IF s.status='open' AND v_binding='legacy_ledger_only' THEN
            IF s.engine_version IS NOT NULL THEN
                SELECT coalesce(max(sequence),0)+1 INTO v_sequence
                  FROM public.trivia_session_answers WHERE session_id=s.id;
                UPDATE public.trivia_session_answers
                   SET outcome='skip',display_index=-1,original_index=NULL,is_correct=false,
                       sequence=v_sequence,answered_at=v_row.created_at
                 WHERE session_id=s.id AND question_id=v_row.question_id
                   AND outcome IS NULL AND server_voided_at IS NULL;
                IF NOT FOUND THEN
                    RAISE EXCEPTION 'legacy paid-skip answer binding changed concurrently'
                        USING ERRCODE='55000';
                END IF;
            ELSE
                SELECT coalesce(max((e.value->>'n')::integer),-1)+1 INTO v_answer_order
                  FROM jsonb_each(s.answers) e
                 WHERE coalesce(e.value->>'n','')~'^[0-9]+$';
                s.answers:=s.answers||jsonb_build_object(v_row.question_id::text,
                    jsonb_build_object('d',-1,'n',v_answer_order,'at',v_row.created_at));
                UPDATE public.trivia_sessions SET answers=s.answers WHERE id=s.id;
            END IF;
        END IF;
    END LOOP;
    RETURN jsonb_build_object('success',true,'adopted',v_candidate_count,
        'paidSkipCount',v_receipt_count+v_candidate_count);
END;
$_$;


ALTER FUNCTION public.trivia_paid_skip_adopt_legacy_v1(p_session_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 6546 (class 1255 OID 115338733)
-- Name: trivia_paid_skip_status_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_paid_skip_status_v1(p_session_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    s public.trivia_sessions%ROWTYPE;
    v_count integer;
    v_miss_status jsonb;
BEGIN
    IF p_session_id IS NULL OR p_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
    END IF;
    SELECT * INTO s FROM public.trivia_sessions WHERE id = p_session_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'session_not_found'); END IF;
    IF s.user_id IS DISTINCT FROM p_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_your_session');
    END IF;
    IF s.mode NOT IN ('endless','survival') THEN
        RETURN jsonb_build_object('success', false, 'error', 'paid_skip_not_supported');
    END IF;
    v_miss_status := public.trivia_solo_miss_status_v1(s.id, p_user_id);
    IF coalesce((v_miss_status ->> 'success')::boolean, false) IS NOT TRUE THEN
        RETURN v_miss_status;
    END IF;
    -- miss_status adopts any exact pre-cutover ledger evidence under the same
    -- session lock. Count only after that adoption so resume never reports a
    -- stale cap or loses a paid entitlement.
    SELECT count(*)::integer INTO v_count
      FROM public.trivia_paid_skip_receipts_v1 r
     WHERE r.session_id = s.id;
    RETURN jsonb_build_object(
        'success', true,
        'sessionId', s.id,
        'paidSkipCount', v_count,
        'paidSkipLimit', 3,
        'policyVersion', 'paid-skip@1',
        'policyUnitCost', 5,
        'nonPaidMissCount', (v_miss_status ->> 'nonPaidMissCount')::integer,
        'terminalFailureCount', (v_miss_status ->> 'terminalFailureCount')::integer,
        'missLimit', (v_miss_status ->> 'missLimit')::integer,
        'runMissLimitReached', coalesce((v_miss_status ->> 'runMissLimitReached')::boolean, false),
        'overrun', coalesce((v_miss_status ->> 'overrun')::boolean, false),
        'survivalLevel', v_miss_status -> 'survivalLevel',
        'requiredCorrect', v_miss_status -> 'requiredCorrect',
        'maxPossibleCorrect', v_miss_status -> 'maxPossibleCorrect'
    );
END;
$$;


ALTER FUNCTION public.trivia_paid_skip_status_v1(p_session_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 6538 (class 1255 OID 115338734)
-- Name: trivia_paid_skip_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_paid_skip_v1(p_session_id uuid, p_user_id uuid, p_question_id uuid, p_client_nonce uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    s public.trivia_sessions%ROWTYPE;
    a public.trivia_session_answers%ROWTYPE;
    v_existing public.trivia_paid_skip_receipts_v1%ROWTYPE;
    v_profile public.profiles%ROWTYPE;
    v_position integer;
    v_count integer;
    v_is_vip boolean;
    v_current_vip_eligible boolean := false;
    v_reference text;
    v_legacy_reference text;
    v_reference_existed boolean := false;
    v_legacy_debit_adopted boolean := false;
    v_spend jsonb;
    v_answer jsonb;
    v_transaction public.diamond_transactions%ROWTYPE;
    v_canonical_transaction public.diamond_transactions%ROWTYPE;
    v_legacy_transaction public.diamond_transactions%ROWTYPE;
    v_receipt public.trivia_paid_skip_receipts_v1%ROWTYPE;
    v_failure jsonb;
    v_miss_status jsonb;
    v_current_balance integer;
    v_expected_position integer;
    v_prior_question_id uuid;
    v_adoption jsonb;
BEGIN
    IF p_session_id IS NULL OR p_user_id IS NULL OR p_question_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
    END IF;

    -- This lock serializes the cap, first answer, debit and receipt for every
    -- device using the same session.
    SELECT * INTO s FROM public.trivia_sessions WHERE id = p_session_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'session_not_found'); END IF;
    IF s.user_id IS DISTINCT FROM p_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_your_session');
    END IF;
    IF s.mode NOT IN ('endless','survival') THEN
        RETURN jsonb_build_object('success', false, 'error', 'paid_skip_not_supported');
    END IF;

    -- Adopt any exact historical debit before every receipt/cap/answer check.
    -- Otherwise a same-question late debit can look unanswered and a newly
    -- adopted third receipt can collide with a fresh ordinal after charging.
    v_adoption := public.trivia_paid_skip_adopt_legacy_v1(s.id, p_user_id);
    IF coalesce((v_adoption ->> 'success')::boolean, false) IS NOT TRUE THEN
        RETURN v_adoption;
    END IF;
    SELECT * INTO s FROM public.trivia_sessions WHERE id = s.id;

    SELECT * INTO v_existing
      FROM public.trivia_paid_skip_receipts_v1
     WHERE session_id = s.id AND question_id = p_question_id;
    IF FOUND THEN
        SELECT count(*)::integer INTO v_count
          FROM public.trivia_paid_skip_receipts_v1 WHERE session_id = s.id;
        SELECT * INTO v_profile FROM public.profiles WHERE id = p_user_id;
        IF NOT FOUND THEN
            v_current_balance := v_existing.balance_after;
            v_current_vip_eligible := false;
        ELSE
            v_current_balance := v_profile.diamonds;
            v_current_vip_eligible := coalesce(v_profile.is_vip, false)
                AND (coalesce(v_profile.vip_tier, '') = 'lifetime'
                     OR (v_profile.vip_expires_at IS NOT NULL
                         AND v_profile.vip_expires_at > clock_timestamp()));
        END IF;
        v_miss_status := public.trivia_solo_miss_status_v1(s.id, p_user_id);
        v_failure := jsonb_build_object(
            'success', true,
            'receiptId', v_existing.receipt_id,
            'sessionId', s.id,
            'questionId', v_existing.question_id,
            'storedDisplayIndex', -1,
            'outcome', 'skip',
            'paidSkipCount', v_count,
            'paidSkipLimit', 3,
            'diamondsCharged', v_existing.diamonds_charged,
            'newBalance', v_current_balance,
            'chargeBalanceAfter', v_existing.balance_after,
            'vip', v_existing.entitlement = 'vip',
            'entitlementWasVip', v_existing.entitlement = 'vip',
            'currentVipEligible', v_current_vip_eligible,
            'replayed', true,
            'newlyCharged', false
        );
        IF coalesce((v_miss_status ->> 'success')::boolean, false) IS TRUE THEN
            v_failure := v_failure || jsonb_build_object(
                'nonPaidMissCount', (v_miss_status ->> 'nonPaidMissCount')::integer,
                'terminalFailureCount', (v_miss_status ->> 'terminalFailureCount')::integer,
                'missLimit', (v_miss_status ->> 'missLimit')::integer,
                'runMissLimitReached', coalesce((v_miss_status ->> 'runMissLimitReached')::boolean, false));
        END IF;
        RETURN v_failure;
    END IF;

    IF s.status <> 'open' THEN
        RETURN jsonb_build_object('success', false, 'error', 'session_closed');
    END IF;
    IF s.expires_at IS NOT NULL AND clock_timestamp() > s.expires_at THEN
        RETURN jsonb_build_object('success', false, 'error', 'session_expired');
    END IF;
    v_position := array_position(s.question_ids, p_question_id);
    IF v_position IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'question_not_in_session');
    END IF;
    SELECT count(*)::integer INTO v_count
      FROM public.trivia_paid_skip_receipts_v1 WHERE session_id = s.id;
    IF v_count >= 3 THEN
        RETURN jsonb_build_object('success', false, 'error', 'paid_skip_limit_reached',
            'paidSkipCount', v_count, 'paidSkipLimit', 3);
    END IF;

    -- An ordinary -1 answer is not proof of payment: it could be a timeout or
    -- free skip. Only a question with no first answer can enter this authority.
    IF s.engine_version IS NOT NULL THEN
        SELECT * INTO a FROM public.trivia_session_answers
         WHERE session_id = s.id AND question_id = p_question_id FOR UPDATE;
        IF NOT FOUND OR a.position IS DISTINCT FROM v_position THEN
            RETURN jsonb_build_object('success', false, 'error', 'question_not_in_session');
        END IF;
        IF a.outcome IS NOT NULL OR a.server_voided_at IS NOT NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'answer_already_recorded');
        END IF;
        SELECT prior.position, prior.question_id
          INTO v_expected_position, v_prior_question_id
          FROM public.trivia_session_answers prior
         WHERE prior.session_id = s.id
           AND prior.position < a.position
           AND prior.outcome IS NULL
           AND prior.server_voided_at IS NULL
         ORDER BY prior.position
         LIMIT 1;
    ELSIF coalesce(s.answers, '{}'::jsonb) ? p_question_id::text THEN
        RETURN jsonb_build_object('success', false, 'error', 'answer_already_recorded');
    ELSE
        SELECT position, s.question_ids[position]
          INTO v_expected_position, v_prior_question_id
          FROM generate_subscripts(s.question_ids, 1) position
         WHERE position < v_position
           AND NOT (coalesce(s.answers, '{}'::jsonb) ? s.question_ids[position]::text)
         ORDER BY position
         LIMIT 1;
    END IF;
    IF v_expected_position IS NOT NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'position_out_of_order',
            'expectedPosition', v_expected_position,
            'priorQuestionId', v_prior_question_id,
            'paidSkipCount', v_count, 'paidSkipLimit', 3);
    END IF;

    v_miss_status := public.trivia_solo_miss_status_v1(s.id, p_user_id);
    IF coalesce((v_miss_status ->> 'success')::boolean, false) IS NOT TRUE THEN
        RETURN v_miss_status;
    END IF;
    IF coalesce((v_miss_status ->> 'runMissLimitReached')::boolean, false) IS TRUE THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'run_miss_limit_reached',
            'nonPaidMissCount', (v_miss_status ->> 'nonPaidMissCount')::integer,
            'terminalFailureCount', (v_miss_status ->> 'terminalFailureCount')::integer,
            'missLimit', (v_miss_status ->> 'missLimit')::integer,
            'runMissLimitReached', true,
            'paidSkipCount', v_count,
            'paidSkipLimit', 3
        );
    END IF;

    v_reference := 'spend:' || p_user_id::text || ':trivia_lifeline:'
        || s.id::text || ':' || p_question_id::text || ':skip';
    v_legacy_reference := 'trivia_lifeline:' || s.id::text || ':'
        || p_question_id::text || ':skip';
    -- Both possible wallet identities follow the canonical ledger-lock before
    -- profile-lock order. This also serializes adoption against an in-flight
    -- pre-cutover client still spending the historical raw reference.
    IF v_reference < v_legacy_reference THEN
        PERFORM pg_advisory_xact_lock(hashtextextended('trivia_ledger:' || v_reference, 20260929));
        PERFORM pg_advisory_xact_lock(hashtextextended('trivia_ledger:' || v_legacy_reference, 20260929));
    ELSE
        PERFORM pg_advisory_xact_lock(hashtextextended('trivia_ledger:' || v_legacy_reference, 20260929));
        PERFORM pg_advisory_xact_lock(hashtextextended('trivia_ledger:' || v_reference, 20260929));
    END IF;
    SELECT * INTO v_profile FROM public.profiles WHERE id = p_user_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'profile_not_found'); END IF;
    v_current_vip_eligible := coalesce(v_profile.is_vip, false)
        AND (coalesce(v_profile.vip_tier, '') = 'lifetime'
             OR (v_profile.vip_expires_at IS NOT NULL
                 AND v_profile.vip_expires_at > clock_timestamp()));
    v_is_vip := v_current_vip_eligible;
    -- The nested block is a database subtransaction. Any post-debit binding
    -- failure raises PS001, which rolls the debit and answer back together.
    BEGIN
        -- Cutover adoption is entitlement-independent. A player who paid
        -- before deployment and became VIP before retry still receives a
        -- Diamond-backed receipt for that exact debit; current VIP status can
        -- only authorize a request for which no matching debit exists.
        SELECT * INTO v_canonical_transaction
          FROM public.diamond_transactions
         WHERE user_id = p_user_id AND reference_id = v_reference
         FOR SHARE;
        v_reference_existed := FOUND;
        SELECT * INTO v_legacy_transaction
          FROM public.diamond_transactions
         WHERE user_id = p_user_id AND reference_id = v_legacy_reference
         FOR SHARE;
        v_legacy_debit_adopted := FOUND;
        IF v_reference_existed AND v_legacy_debit_adopted THEN
            RETURN jsonb_build_object('success', false,
                'error', 'ambiguous_paid_skip_debit');
        ELSIF v_reference_existed THEN
            v_transaction := v_canonical_transaction;
            v_is_vip := false;
        ELSIF v_legacy_debit_adopted THEN
            v_transaction := v_legacy_transaction;
            v_is_vip := false;
        ELSIF NOT v_is_vip THEN
                PERFORM set_config('trivia.phase9_paid_skip_authority','on',true);
                v_spend := public.trivia_solo_spend_before_phase9_v1(
                    p_user_id,
                    5,
                    'Trivia Paid Skip',
                    'trivia_lifeline',
                    v_reference
                );
                PERFORM set_config('trivia.phase9_paid_skip_authority','',true);
                IF coalesce((v_spend ->> 'success')::boolean, false) IS NOT TRUE THEN
                    RETURN jsonb_build_object(
                        'success', false,
                        'error', CASE
                            WHEN lower(coalesce(v_spend ->> 'error', '')) LIKE '%insufficient%'
                                THEN 'insufficient_diamonds'
                            ELSE coalesce(v_spend ->> 'error', 'paid_skip_charge_failed')
                        END,
                        'paidSkipCount', v_count,
                        'paidSkipLimit', 3,
                        'newBalance', coalesce((v_spend ->> 'balance')::integer, v_profile.diamonds)
                    );
                END IF;
                IF (v_spend ->> 'charged')::integer IS DISTINCT FROM 5
                   OR v_spend ->> 'transaction_type' IS DISTINCT FROM 'trivia_lifeline'
                   OR v_spend ->> 'reference_id' IS DISTINCT FROM v_reference
                   OR v_spend ->> 'counterparty' IS DISTINCT FROM 'revenue:trivia_lifeline'
                   OR v_spend ->> 'issuance_class' IS DISTINCT FROM 'spend' THEN
                    v_failure := jsonb_build_object('success', false, 'error', 'invalid_charge_receipt');
                    RAISE EXCEPTION 'paid skip charge receipt failed validation' USING ERRCODE = 'PS001';
                END IF;
                SELECT * INTO v_transaction
                  FROM public.diamond_transactions
                 WHERE user_id = p_user_id AND reference_id = v_reference
                 FOR SHARE;
        END IF;
        IF NOT v_is_vip THEN
            IF v_transaction.id IS NULL
               OR v_transaction.amount IS DISTINCT FROM -5
               OR coalesce(v_transaction.transaction_type, v_transaction.type)
                    IS DISTINCT FROM 'trivia_lifeline'
               OR v_transaction.counterparty IS DISTINCT FROM 'revenue:trivia_lifeline'
               OR v_transaction.issuance_class IS DISTINCT FROM 'spend'
               OR v_transaction.balance_after IS NULL THEN
                v_failure := jsonb_build_object('success', false, 'error', 'invalid_charge_receipt');
                RAISE EXCEPTION 'paid skip durable charge proof is missing' USING ERRCODE = 'PS001';
            END IF;
        END IF;

        IF s.engine_version IS NOT NULL THEN
            v_answer := public.trivia_session_answer_before_phase9_v4(
                s.id, p_user_id, p_question_id, -1, p_client_nonce);
        ELSE
            v_answer := public.trivia_legacy_session_answer_before_phase9_v1(
                s.id, p_user_id, p_question_id, -1, p_client_nonce);
        END IF;
        IF coalesce((v_answer ->> 'success')::boolean, false) IS NOT TRUE
           OR coalesce((v_answer ->> 'storedDisplayIndex')::integer, 0) <> -1
           OR coalesce((v_answer ->> 'duplicate')::boolean, false)
           OR coalesce((v_answer ->> 'voided')::boolean, false)
           OR v_answer ->> 'outcome' = 'voided' THEN
            v_failure := jsonb_build_object('success', false,
                'error', CASE WHEN coalesce((v_answer ->> 'voided')::boolean, false)
                                   OR v_answer ->> 'outcome' = 'voided'
                              THEN 'question_unavailable'
                              ELSE coalesce(v_answer ->> 'error', 'paid_skip_binding_failed') END,
                'paidSkipCount', v_count,
                'paidSkipLimit', 3);
            RAISE EXCEPTION 'paid skip answer binding failed' USING ERRCODE = 'PS001';
        END IF;

        INSERT INTO public.trivia_paid_skip_receipts_v1 (
            session_id, user_id, question_id, position, paid_skip_ordinal,
            policy_version, policy_unit_cost, policy_session_limit,
            entitlement, diamonds_charged, spend_reference,
            wallet_transaction_id, balance_after, client_nonce
        ) VALUES (
            s.id, p_user_id, p_question_id, v_position, v_count + 1,
            'paid-skip@1', 5, 3,
            CASE WHEN v_is_vip THEN 'vip' ELSE 'diamonds' END,
            CASE WHEN v_is_vip THEN 0 ELSE 5 END,
            CASE WHEN v_is_vip THEN NULL ELSE v_transaction.reference_id END,
            CASE WHEN v_is_vip THEN NULL ELSE v_transaction.id END,
            CASE WHEN v_is_vip THEN coalesce(v_profile.diamonds, 0)
                 ELSE v_transaction.balance_after END,
            p_client_nonce
        )
        RETURNING * INTO v_receipt;

        v_miss_status := public.trivia_solo_miss_status_v1(s.id, p_user_id);
        IF coalesce((v_miss_status ->> 'success')::boolean, false) IS NOT TRUE THEN
            v_failure := v_miss_status;
            RAISE EXCEPTION 'paid skip terminal-state projection failed' USING ERRCODE = 'PS001';
        END IF;
    EXCEPTION WHEN SQLSTATE 'PS001' THEN
        RETURN v_failure;
    END;

    SELECT diamonds INTO v_current_balance FROM public.profiles WHERE id = p_user_id;
    IF NOT FOUND THEN v_current_balance := v_receipt.balance_after; END IF;

    RETURN jsonb_build_object(
        'success', true,
        'receiptId', v_receipt.receipt_id,
        'sessionId', s.id,
        'questionId', p_question_id,
        'storedDisplayIndex', -1,
        'outcome', 'skip',
        'paidSkipCount', v_count + 1,
        'paidSkipLimit', 3,
        'nonPaidMissCount', (v_miss_status ->> 'nonPaidMissCount')::integer,
        'terminalFailureCount', (v_miss_status ->> 'terminalFailureCount')::integer,
        'missLimit', (v_miss_status ->> 'missLimit')::integer,
        'runMissLimitReached', coalesce((v_miss_status ->> 'runMissLimitReached')::boolean, false),
        'diamondsCharged', v_receipt.diamonds_charged,
        'newBalance', v_current_balance,
        'vip', v_is_vip,
        'entitlementWasVip', v_is_vip,
        'currentVipEligible', v_current_vip_eligible,
        'replayed', false,
        'newlyCharged', NOT v_is_vip
            AND NOT v_legacy_debit_adopted
            AND NOT v_reference_existed
            AND coalesce((v_spend ->> 'idempotent')::boolean, false) IS NOT TRUE
    );
END;
$$;


ALTER FUNCTION public.trivia_paid_skip_v1(p_session_id uuid, p_user_id uuid, p_question_id uuid, p_client_nonce uuid) OWNER TO postgres;

--
-- TOC entry 6397 (class 1255 OID 115338701)
-- Name: trivia_phase9_forbid_receipt_mutation_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_phase9_forbid_receipt_mutation_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    RAISE EXCEPTION 'phase9 authority receipts are immutable'
        USING ERRCODE = 'check_violation';
END;
$$;


ALTER FUNCTION public.trivia_phase9_forbid_receipt_mutation_v1() OWNER TO postgres;

--
-- TOC entry 4271 (class 1255 OID 115338288)
-- Name: trivia_phase9_guard_lifeline_ledger_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_phase9_guard_lifeline_ledger_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF coalesce(NEW.transaction_type, NEW.type) = 'trivia_lifeline'
       AND current_setting('trivia.phase9_paid_skip_authority', true)
            IS DISTINCT FROM 'on' THEN
        RAISE EXCEPTION 'paid_skip_requires_session_authority'
            USING ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.trivia_phase9_guard_lifeline_ledger_v1() OWNER TO postgres;

--
-- TOC entry 6655 (class 1255 OID 74744030)
-- Name: trivia_preflight_tournament_v1(uuid, integer, text, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_preflight_tournament_v1(p_tournament_id uuid, p_bracket_size integer, p_profile_id text DEFAULT 'tournament.nightly/roster@1'::text, p_entrant_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_cap jsonb; v_s public.trivia_roster_snapshots%ROWTYPE; v_rounds integer; v_n integer; v_r integer;
    v_as_of timestamptz := now(); v_got integer; v_excl uuid[] := '{}'::uuid[]; v_secret bytea; v_base record;
    f_q uuid[]; f_r uuid[]; f_c text[]; f_d text[]; f_t smallint[];
BEGIN
    IF p_tournament_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_scope'); END IF;
    v_cap := public.trivia_tournament_capacity_v1(p_bracket_size, p_profile_id);
    IF (v_cap ->> 'success')::boolean IS NOT TRUE THEN RETURN v_cap; END IF;
    v_rounds := (v_cap ->> 'rounds')::int;
    v_n := (v_cap ->> 'questions_per_round')::int;
    PERFORM pg_advisory_xact_lock(hashtextextended('trivia_roster:tournament_plan:' || p_tournament_id::text, 0));
    SELECT * INTO v_s FROM public.trivia_roster_snapshots WHERE scope_kind = 'tournament_plan' AND scope_id = p_tournament_id::text;
    IF FOUND THEN
        IF v_s.profile_id <> p_profile_id OR v_s.rounds <> v_rounds THEN
            RETURN jsonb_build_object('success', false, 'error', 'scope_conflict', 'snapshot_id', v_s.id);
        END IF;
        RETURN public.trivia_p3_snapshot_receipt(v_s) || jsonb_build_object('questions_per_round', v_n,
            'required', v_rounds * v_n);
    END IF;
    v_secret := public.trivia_engine_secret_v1('roster-v1');
    v_base := public.trivia_p3_candidates_v1(p_profile_id, coalesce(p_entrant_ids, '{}'::uuid[]), '{}'::uuid[], v_as_of);
    CREATE TEMP TABLE IF NOT EXISTS trivia_p3_plan (round_no integer, pos integer, question_id uuid, revision_id uuid,
        canonical_question_id uuid, category text, difficulty text, tier smallint) ON COMMIT DROP;
    TRUNCATE pg_temp.trivia_p3_plan;
    FOR v_r IN 1 .. v_rounds LOOP
        SELECT coalesce(array_agg(u.qid), '{}'), coalesce(array_agg(u.rid), '{}'), coalesce(array_agg(u.cat), '{}'),
               coalesce(array_agg(u.diff), '{}'), coalesce(array_agg(u.tr), '{}')
          INTO f_q, f_r, f_c, f_d, f_t
          FROM unnest(v_base.qids, v_base.rids, v_base.cats, v_base.diffs, v_base.tiers) AS u(qid, rid, cat, diff, tr)
         WHERE NOT (u.qid = ANY (v_excl));
        INSERT INTO pg_temp.trivia_p3_plan
        SELECT v_r, s.pos, s.question_id, s.revision_id, s.canonical_question_id, s.category, s.difficulty, s.tier
          FROM public.trivia_p3_select_passes_v1(v_secret, 'tournament_plan:' || p_tournament_id::text || ':r' || v_r,
               p_profile_id, v_n, f_q, f_r, f_c, f_d, f_t) s;
        SELECT count(*) INTO v_got FROM pg_temp.trivia_p3_plan WHERE round_no = v_r;
        IF v_got < v_n THEN
            RETURN jsonb_build_object('success', false, 'error', 'insufficient_eligible_pool', 'round', v_r,
                'required', v_rounds * v_n, 'available', (v_cap ->> 'eligible_available')::int);
        END IF;
        v_excl := ARRAY(SELECT canonical_question_id FROM pg_temp.trivia_p3_plan);
    END LOOP;
    RETURN public.trivia_p3_store_snapshot('tournament_plan', p_tournament_id::text, p_profile_id,
        'tournament_plan:' || p_tournament_id::text, v_as_of, v_rounds)
        || jsonb_build_object('questions_per_round', v_n, 'required', v_rounds * v_n);
END $$;


ALTER FUNCTION public.trivia_preflight_tournament_v1(p_tournament_id uuid, p_bracket_size integer, p_profile_id text, p_entrant_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 6999 (class 1255 OID 110226014)
-- Name: trivia_project_engine_metadata_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_project_engine_metadata_v1(p_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    v_metadata jsonb := CASE WHEN jsonb_typeof(p_metadata) = 'object'
                             THEN p_metadata ELSE '{}'::jsonb END;
    v_ev jsonb := v_metadata -> 'ev_data';
    v_provenance jsonb;
    v_artifact_id uuid;
    v_audited_at timestamptz;
BEGIN
    IF jsonb_typeof(v_ev) IS DISTINCT FROM 'object' THEN RETURN v_metadata - 'ev_data'; END IF;
    v_provenance := v_ev -> 'provenance';
    IF jsonb_typeof(v_provenance) IS DISTINCT FROM 'object'
       OR v_ev ->> 'contract' IS DISTINCT FROM 'trivia-solver-ev/1'
       OR v_ev ->> 'unit' IS DISTINCT FROM 'bb'
       OR v_ev ->> 'source' IS DISTINCT FROM 'solved_spots_gold.strategy_matrix_v2.hand_evs_bb'
       OR v_ev ->> 'aggregation' IS DISTINCT FROM 'live_combo_class_mean'
       OR v_provenance ->> 'authority' IS DISTINCT FROM 'training_solver_provenance_authority'
       OR v_provenance ->> 'catalog' IS DISTINCT FROM 'training_solver_artifact_catalog'
       OR v_provenance ->> 'solver' IS DISTINCT FROM 'PioSOLVER'
       OR coalesce(v_provenance ->> 'artifact_id', '')
            !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR coalesce(v_provenance ->> 'solver_binary_checksum', '') !~ '^[0-9a-f]{64}$'
       OR coalesce(v_provenance ->> 'pipeline_commit', '') !~ '^[0-9a-f]{40}$'
       OR coalesce(v_provenance ->> 'manifest_checksum', '') !~ '^[0-9a-f]{64}$'
       OR coalesce(v_provenance ->> 'source_artifact_checksum', '') !~ '^[0-9a-f]{64}$'
       OR coalesce(v_provenance ->> 'source_combo_order_sha256', '') !~ '^[0-9a-f]{64}$'
       OR coalesce(v_provenance ->> 'training_game_contracts_sha256', '') !~ '^[0-9a-f]{64}$' THEN
        RETURN v_metadata - 'ev_data';
    END IF;
    BEGIN
        v_artifact_id := (v_provenance ->> 'artifact_id')::uuid;
        v_audited_at := (v_provenance ->> 'audited_at')::timestamptz;
    EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow THEN
        RETURN v_metadata - 'ev_data';
    END;
    IF NOT EXISTS (
        SELECT 1
          FROM public.training_solver_artifact_catalog catalog
          JOIN public.solved_spots_gold artifact ON artifact.id = catalog.artifact_id
          JOIN public.training_solver_provenance_authority authority
            ON authority.machine_id = artifact.machine_id
           AND authority.solver_version = artifact.solver_version
           AND authority.solver_binary_checksum = artifact.solver_binary_checksum
           AND authority.pipeline_commit = artifact.pipeline_commit
           AND authority.manifest_version = artifact.manifest_version
           AND authority.manifest_checksum = artifact.manifest_checksum
           AND authority.source_combo_order_sha256 = artifact.strategy_matrix_v2 ->> 'source_combo_order_sha256'
           AND authority.training_game_contracts_sha256 = artifact.strategy_matrix_v2 ->> 'training_game_contracts_sha256'
           AND authority.retired_at IS NULL
         WHERE catalog.artifact_id = v_artifact_id
           AND catalog.scenario_hash = v_provenance ->> 'scenario_hash'
           AND catalog.scenario_hash = artifact.scenario_hash
           AND catalog.game_type = artifact.game_type
           AND catalog.stack_depth = artifact.stack_depth
           AND catalog.street = artifact.street
           AND catalog.hero_position = artifact.strategy_matrix_v2 ->> 'position'
           AND artifact.quality_status = 'validated'
           AND artifact.strategy_matrix_v2 ->> 'solver' = 'PioSOLVER'
           AND artifact.solver_version = v_provenance ->> 'solver_version'
           AND artifact.solver_binary_checksum = v_provenance ->> 'solver_binary_checksum'
           AND artifact.pipeline_commit = v_provenance ->> 'pipeline_commit'
           AND artifact.manifest_version = v_provenance ->> 'manifest_version'
           AND artifact.manifest_checksum = v_provenance ->> 'manifest_checksum'
           AND artifact.source_artifact_checksum = v_provenance ->> 'source_artifact_checksum'
           AND artifact.strategy_matrix_v2 ->> 'source_combo_order_sha256'
                = v_provenance ->> 'source_combo_order_sha256'
           AND artifact.strategy_matrix_v2 ->> 'training_game_contracts_sha256'
                = v_provenance ->> 'training_game_contracts_sha256'
           AND artifact.audited_at = v_audited_at) THEN
        RETURN v_metadata - 'ev_data';
    END IF;
    RETURN v_metadata;
END $_$;


ALTER FUNCTION public.trivia_project_engine_metadata_v1(p_metadata jsonb) OWNER TO postgres;

--
-- TOC entry 6375 (class 1255 OID 78785898)
-- Name: trivia_pvp__active_secret(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__active_secret(OUT key_id text, OUT secret bytea) RETURNS record
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    SELECT s.key_id, s.secret INTO key_id, secret
      FROM public.trivia_pvp_engine_secrets AS s
     WHERE s.active;
    IF key_id IS NULL THEN
        RAISE EXCEPTION 'pvp engine secret is missing';
    END IF;
END;
$$;


ALTER FUNCTION public.trivia_pvp__active_secret(OUT key_id text, OUT secret bytea) OWNER TO postgres;

--
-- TOC entry 9153 (class 1255 OID 78786099)
-- Name: trivia_pvp__advance_match(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__advance_match(p_match_id uuid, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_res jsonb;
    v_sqlstate text;
    v_message text;
BEGIN
    BEGIN
        PERFORM public.trivia_pvp__drive_match(p_match_id, p_now);
    EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        PERFORM public.trivia_pvp__log(p_match_id, NULL, NULL, 'system', 'settlement_failed',
            jsonb_build_object('step', 'drive', 'sqlstate', v_sqlstate, 'message', left(v_message, 300)),
            COALESCE(p_now, clock_timestamp()));
    END;
    BEGIN
        v_res := public.trivia_pvp__settle_core(p_match_id, false, p_now);
    EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
        PERFORM set_config('trivia_pvp.v2_authority', '', true);
        PERFORM public.trivia_pvp__log(p_match_id, NULL, NULL, 'system', 'settlement_failed',
            jsonb_build_object('step', 'settle', 'sqlstate', v_sqlstate, 'message', left(v_message, 300)),
            COALESCE(p_now, clock_timestamp()));
        v_res := jsonb_build_object('success', false, 'error', 'settlement_failed', 'sqlstate', v_sqlstate);
    END;
    RETURN v_res;
END;
$$;


ALTER FUNCTION public.trivia_pvp__advance_match(p_match_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 4307 (class 1255 OID 78785996)
-- Name: trivia_pvp__bind_match(uuid, text, uuid, uuid, uuid, uuid, integer, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__bind_match(p_match_id uuid, p_kind text, p_player1 uuid, p_player2 uuid, p_ticket1 uuid, p_ticket2 uuid, p_stake integer, p_rules_version_id text, p_now timestamp with time zone, p_horse jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_rules jsonb;
    v_roster jsonb;
    v_snapshot uuid;
    v_ids uuid[];
    v_deadline timestamptz;
    v_res jsonb;
    v_side smallint;
    v_user uuid;
    v_is_horse boolean;
    v_session uuid;
    v_sessions jsonb := '{}'::jsonb;
    v_items jsonb;
    v_plan jsonb;
    v_persona public.trivia_pvp_horse_personas%ROWTYPE;
    v_horse_session uuid;
BEGIN
    IF current_setting('trivia_pvp.v2_authority', true) IS DISTINCT FROM p_match_id::text THEN
        RAISE EXCEPTION 'pvp v2 binding requires the engine authority';
    END IF;
    v_rules := public.trivia_rules_get(p_rules_version_id);
    IF v_rules IS NULL OR v_rules -> 'rules' IS NULL
       OR NOT ((v_rules -> 'rules' -> 'stakes') @> to_jsonb(p_stake))
       OR COALESCE((v_rules -> 'rules' ->> 'match_window_seconds')::integer, 0) NOT BETWEEN 60 AND 1800 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5004', MESSAGE = 'rules_unavailable', DETAIL = 'rules';
    END IF;
    v_deadline := p_now + make_interval(secs => (v_rules -> 'rules' ->> 'match_window_seconds')::integer);

    -- Roster first: a private, deterministic Phase 3 snapshot scoped to this match.
    v_roster := public.trivia_build_roster_v1('pvp_match', p_match_id::text, 'pvp.standard/roster@1',
                                              ARRAY[p_player1, p_player2], '{}'::uuid[]);
    IF COALESCE((v_roster ->> 'success')::boolean, false) IS NOT TRUE THEN
        RAISE EXCEPTION USING ERRCODE = 'P5003', MESSAGE = 'roster_unavailable',
            DETAIL = COALESCE(v_roster ->> 'error', 'unknown');
    END IF;
    v_snapshot := (v_roster ->> 'snapshot_id')::uuid;
    v_ids := ARRAY(SELECT i.question_id FROM public.trivia_roster_snapshot_items AS i
                    WHERE i.snapshot_id = v_snapshot AND i.round_no = 1 ORDER BY i.position);
    IF cardinality(v_ids) <> COALESCE((v_rules -> 'rules' -> 'questions' ->> 'count')::integer, -1) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5003', MESSAGE = 'roster_unavailable', DETAIL = 'roster_size';
    END IF;

    INSERT INTO public.trivia_pvp_matches (
        id, player1_id, player2_id, stake_amount, questions, status, created_at,
        engine_version, match_kind, rules_version_id, roster_snapshot_id, roster_hash,
        player1_ticket_id, player2_ticket_id, horse_side, deadline_at
    ) VALUES (
        p_match_id, p_player1, p_player2, p_stake, to_jsonb(v_ids), 'pending', p_now,
        'pvp-v2', p_kind, p_rules_version_id, v_snapshot, v_roster ->> 'roster_hash',
        p_ticket1, p_ticket2, CASE WHEN p_kind = 'human_horse' THEN 2 END, v_deadline
    );

    v_res := public.trivia_settlement_open('pvp_match', p_match_id, p_rules_version_id,
                                           jsonb_build_object('engine', 'pvp-v2', 'kind', p_kind));
    IF COALESCE((v_res ->> 'success')::boolean, false) IS NOT TRUE THEN
        RAISE EXCEPTION USING ERRCODE = 'P5004', MESSAGE = 'settlement_open_refused',
            DETAIL = 'settlement_open:' || COALESCE(v_res ->> 'error', 'unknown');
    END IF;

    FOR v_side IN 1..2 LOOP
        v_user := CASE v_side WHEN 1 THEN p_player1 ELSE p_player2 END;
        v_is_horse := p_kind = 'human_horse' AND v_side = 2;
        IF v_is_horse THEN
            v_res := public.trivia_ledger_subsidy(
                'pvp_stake_' || p_match_id::text || '_' || v_user::text, 'pvp_match', p_match_id,
                v_user, p_stake, 'horse_seat',
                jsonb_build_object('engine', 'pvp-v2', 'side', v_side));
            IF COALESCE((v_res ->> 'success')::boolean, false) IS NOT TRUE THEN
                IF COALESCE(v_res ->> 'error', '') LIKE 'treasury%' THEN
                    RAISE EXCEPTION USING ERRCODE = 'P5002', MESSAGE = 'treasury_unavailable',
                        DETAIL = v_res ->> 'error';
                END IF;
                RAISE EXCEPTION USING ERRCODE = 'P5004', MESSAGE = 'subsidy_refused',
                    DETAIL = 'subsidy:' || COALESCE(v_res ->> 'error', 'unknown');
            END IF;
        ELSE
            v_res := public.trivia_ledger_hold(
                'pvp_stake_' || p_match_id::text || '_' || v_user::text, 'pvp_match', p_match_id,
                v_user, p_stake, 'pvp_stake', 'PvP stake - match ' || p_match_id::text, 'human',
                jsonb_build_object('engine', 'pvp-v2', 'side', v_side));
            IF COALESCE((v_res ->> 'success')::boolean, false) IS NOT TRUE THEN
                IF v_res ->> 'error' = 'insufficient_funds' THEN
                    RAISE EXCEPTION USING ERRCODE = 'P5001', MESSAGE = 'insufficient_funds',
                        DETAIL = v_side::text;
                END IF;
                RAISE EXCEPTION USING ERRCODE = 'P5004', MESSAGE = 'hold_refused',
                    DETAIL = 'hold:' || COALESCE(v_res ->> 'error', 'unknown');
            END IF;
        END IF;
    END LOOP;

    v_res := public.trivia_settlement_lock('pvp_match', p_match_id);
    IF COALESCE((v_res ->> 'success')::boolean, false) IS NOT TRUE
       OR (v_res ->> 'gross_pool')::bigint IS DISTINCT FROM (p_stake * 2)::bigint THEN
        RAISE EXCEPTION USING ERRCODE = 'P5004', MESSAGE = 'settlement_lock_refused',
            DETAIL = 'lock:' || COALESCE(v_res ->> 'error', 'gross_pool_mismatch');
    END IF;

    UPDATE public.trivia_pvp_matches SET status = 'active', activated_at = p_now WHERE id = p_match_id;

    FOR v_side IN 1..2 LOOP
        v_user := CASE v_side WHEN 1 THEN p_player1 ELSE p_player2 END;
        v_is_horse := p_kind = 'human_horse' AND v_side = 2;
        v_session := gen_random_uuid();
        v_res := public.trivia_open_session_v3(
            v_session, v_user, v_snapshot, 1, 'pvp:' || p_match_id::text || ':' || v_side::text, v_deadline,
            jsonb_build_object('entry_reference', 'pvp_stake_' || p_match_id::text || '_' || v_user::text,
                               'entry_cost', p_stake,
                               'funding', CASE WHEN v_is_horse THEN 'treasury' ELSE 'player_wallet' END));
        IF COALESCE((v_res ->> 'success')::boolean, false) IS NOT TRUE THEN
            RAISE EXCEPTION USING ERRCODE = 'P5004', MESSAGE = 'session_open_refused',
                DETAIL = 'session:' || COALESCE(v_res ->> 'error', 'unknown');
        END IF;
        INSERT INTO public.trivia_pvp_session_links (match_id, side, user_id, session_id, created_at, engine_version)
        VALUES (p_match_id, v_side, v_user, v_session, clock_timestamp(), 'pvp-v2');
        v_sessions := v_sessions || jsonb_build_object(v_side::text, v_session);
        IF v_is_horse THEN
            v_horse_session := v_session;
        END IF;
    END LOOP;

    IF p_kind = 'human_horse' THEN
        SELECT * INTO v_persona FROM public.trivia_pvp_horse_personas WHERE horse_id = p_player2 FOR UPDATE;
        SELECT jsonb_agg(jsonb_build_object(
                   'question_id', i.question_id, 'category', i.category, 'difficulty', i.difficulty,
                   'option_count', jsonb_array_length(r.options), 'correct_index', r.correct_index)
                 ORDER BY i.position)
          INTO v_items
          FROM public.trivia_roster_snapshot_items AS i
          JOIN public.trivia_question_revisions AS r ON r.id = i.revision_id
         WHERE i.snapshot_id = v_snapshot AND i.round_no = 1;
        v_plan := public.trivia_pvp__build_horse_plan(
            p_match_id, p_player2, 2::smallint, p_horse ->> 'tier', v_persona.category_strengths,
            v_items, 40000, p_now, v_deadline, p_horse ->> 'secret_key_id');
        INSERT INTO public.trivia_pvp_horse_plans (
            match_id, horse_id, side, session_id, plan_version, secret_key_id, model, plan,
            model_hash, plan_hash, question_count, starts_at, finishes_at
        ) VALUES (
            p_match_id, p_player2, 2, v_horse_session, 'pvp-horse-plan/1', p_horse ->> 'secret_key_id',
            v_plan -> 'model', v_plan -> 'plan', v_plan ->> 'model_hash', v_plan ->> 'plan_hash',
            jsonb_array_length(v_plan -> 'plan'), p_now, (v_plan ->> 'finishes_at')::timestamptz
        );
        UPDATE public.trivia_pvp_horse_personas
           SET last_pvp_match_id = p_match_id, last_pvp_matched_at = p_now,
               pvp_appearances = pvp_appearances + 1, updated_at = GREATEST(updated_at, p_now)
         WHERE horse_id = p_player2;
    END IF;

    RETURN jsonb_build_object(
        'match_id', p_match_id, 'snapshot_id', v_snapshot, 'roster_hash', v_roster ->> 'roster_hash',
        'deadline_at', v_deadline, 'sessions', v_sessions,
        'plan_hash', v_plan ->> 'plan_hash', 'model_hash', v_plan ->> 'model_hash',
        'horse_finishes_at', v_plan ->> 'finishes_at');
END;
$$;


ALTER FUNCTION public.trivia_pvp__bind_match(p_match_id uuid, p_kind text, p_player1 uuid, p_player2 uuid, p_ticket1 uuid, p_ticket2 uuid, p_stake integer, p_rules_version_id text, p_now timestamp with time zone, p_horse jsonb) OWNER TO postgres;

--
-- TOC entry 8956 (class 1255 OID 78785895)
-- Name: trivia_pvp__bucket_lock(integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__bucket_lock(p_stake integer, p_rules_version text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
    SELECT pg_advisory_xact_lock(hashtextextended(
        'trivia_pvp:bucket:' || p_stake::text || ':' || COALESCE(p_rules_version, ''), 0));
$$;


ALTER FUNCTION public.trivia_pvp__bucket_lock(p_stake integer, p_rules_version text) OWNER TO postgres;

--
-- TOC entry 7191 (class 1255 OID 78785913)
-- Name: trivia_pvp__build_horse_plan(uuid, uuid, smallint, text, jsonb, jsonb, integer, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__build_horse_plan(p_match_id uuid, p_horse_id uuid, p_side smallint, p_tier text, p_overrides jsonb, p_roster jsonb, p_per_question_ms integer, p_starts_at timestamp with time zone, p_deadline timestamp with time zone, p_secret_key_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_model jsonb := public.trivia_pvp__horse_tier_model(p_tier);
    v_secret bytea := public.trivia_pvp__secret(p_secret_key_id);
    v_key bytea;
    v_item jsonb;
    v_i integer := 0;
    v_n integer;
    v_q uuid;
    v_category text;
    v_difficulty text;
    v_options integer;
    v_correct_index integer;
    v_strength numeric;
    v_strengths jsonb := '{}'::jsonb;
    v_p double precision;
    v_correct boolean;
    v_choice integer;
    v_wrong_rank integer;
    v_rt double precision;
    v_rt_cap double precision;
    v_median double precision;
    v_offset bigint;
    v_deal bigint;
    v_plan jsonb := '[]'::jsonb;
    v_lo double precision := (v_model -> 'accuracy_bounds' ->> 0)::double precision;
    v_hi double precision := (v_model -> 'accuracy_bounds' ->> 1)::double precision;
    v_envelope jsonb;
    v_finishes_at timestamptz;
BEGIN
    IF p_match_id IS NULL OR p_horse_id IS NULL OR p_side NOT IN (1, 2)
       OR jsonb_typeof(p_roster) IS DISTINCT FROM 'array'
       OR jsonb_array_length(p_roster) NOT BETWEEN 1 AND 60
       OR p_per_question_ms IS NULL OR p_per_question_ms < 5000
       OR p_starts_at IS NULL OR p_deadline IS NULL OR p_deadline <= p_starts_at THEN
        RAISE EXCEPTION 'invalid horse plan input';
    END IF;
    v_n := jsonb_array_length(p_roster);
    v_key := extensions.hmac(convert_to(
        'pvp-horse-plan/1:' || p_match_id::text || ':' || p_horse_id::text || ':' || p_side::text,
        'UTF8'), v_secret, 'sha256');

    v_deal := ((v_model -> 'deal_delay_ms' ->> 0)::bigint
        + floor(public.trivia_pvp__u01(v_key, 'deal')
                * ((v_model -> 'deal_delay_ms' ->> 1)::bigint - (v_model -> 'deal_delay_ms' ->> 0)::bigint))::bigint);
    v_offset := v_deal;

    FOR v_item IN SELECT value FROM jsonb_array_elements(p_roster) LOOP
        v_i := v_i + 1;
        v_q := (v_item ->> 'question_id')::uuid;
        v_category := COALESCE(NULLIF(v_item ->> 'category', ''), 'general');
        v_difficulty := COALESCE(NULLIF(v_item ->> 'difficulty', ''), 'medium');
        v_options := (v_item ->> 'option_count')::integer;
        v_correct_index := (v_item ->> 'correct_index')::integer;
        IF v_q IS NULL OR v_options IS NULL OR v_options < 2 OR v_options > 8
           OR v_correct_index IS NULL OR v_correct_index < 0 OR v_correct_index >= v_options THEN
            RAISE EXCEPTION 'invalid horse plan roster item %', v_i;
        END IF;

        v_strength := public.trivia_pvp__horse_category_strength(p_horse_id, v_category, p_overrides);
        v_strengths := v_strengths || jsonb_build_object(v_category, v_strength);

        v_p := (v_model ->> 'base_accuracy')::double precision
             + COALESCE((v_model -> 'difficulty_accuracy' ->> v_difficulty)::double precision, 0)
             + (v_model ->> 'strength_weight')::double precision * v_strength::double precision;
        v_p := GREATEST(v_lo, LEAST(v_hi, v_p));
        v_correct := public.trivia_pvp__u01(v_key, 'c:' || v_i) < v_p;
        IF v_correct THEN
            v_choice := v_correct_index;
        ELSE
            -- uniform among the wrong options, in ascending original index
            v_wrong_rank := LEAST(v_options - 2,
                floor(public.trivia_pvp__u01(v_key, 'w:' || v_i) * (v_options - 1))::integer);
            v_choice := CASE WHEN v_wrong_rank < v_correct_index THEN v_wrong_rank ELSE v_wrong_rank + 1 END;
        END IF;

        v_median := (v_model ->> 'rt_median_ms')::double precision
                  * COALESCE((v_model -> 'difficulty_rt' ->> v_difficulty)::double precision, 1.0);
        v_rt := v_median
              * CASE WHEN v_correct THEN 1.0 ELSE (v_model ->> 'incorrect_rt_factor')::double precision END
              * exp((v_model ->> 'rt_sigma')::double precision * public.trivia_pvp__normal(v_key, 'r:' || v_i));
        v_rt_cap := LEAST((p_per_question_ms - 1500)::double precision,
                          v_median * (v_model ->> 'rt_max_median_multiple')::double precision);
        v_rt := GREATEST((v_model ->> 'rt_min_ms')::double precision, LEAST(v_rt_cap, v_rt));
        v_offset := v_offset + round(v_rt)::bigint;

        v_plan := v_plan || jsonb_build_array(jsonb_build_object(
            'i', v_i, 'q', v_q, 'c', v_correct, 'o', v_choice,
            'rt', round(v_rt)::bigint, 't', v_offset));
    END LOOP;

    v_finishes_at := p_starts_at + make_interval(secs => v_offset / 1000.0);
    IF v_finishes_at >= p_deadline - interval '5 seconds' THEN
        RAISE EXCEPTION 'horse plan exceeds the match deadline';
    END IF;

    v_model := v_model || jsonb_build_object(
        'per_question_ms', p_per_question_ms,
        'deal_delay_ms_drawn', v_deal,
        'secret_key_id', p_secret_key_id,
        'stake_is_input', false,
        'persona', jsonb_build_object('version', 'pvp-horse-persona/1', 'strengths', v_strengths));
    v_envelope := jsonb_build_object(
        'match_id', p_match_id, 'horse_id', p_horse_id, 'side', p_side,
        'starts_at', p_starts_at, 'model', v_model, 'plan', v_plan);
    RETURN jsonb_build_object(
        'model', v_model,
        'plan', v_plan,
        'model_hash', encode(extensions.digest(v_model::text, 'sha256'), 'hex'),
        'plan_hash', encode(extensions.digest(v_envelope::text, 'sha256'), 'hex'),
        'starts_at', p_starts_at,
        'finishes_at', v_finishes_at);
END;
$$;


ALTER FUNCTION public.trivia_pvp__build_horse_plan(p_match_id uuid, p_horse_id uuid, p_side smallint, p_tier text, p_overrides jsonb, p_roster jsonb, p_per_question_ms integer, p_starts_at timestamp with time zone, p_deadline timestamp with time zone, p_secret_key_id text) OWNER TO postgres;

--
-- TOC entry 7505 (class 1255 OID 78785968)
-- Name: trivia_pvp__cancel_core(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__cancel_core(p_user_id uuid, p_ticket_id uuid, p_now timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_t public.trivia_pvp_queue%ROWTYPE;
    v_now timestamptz;
    v_outcome text;
BEGIN
    IF p_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_request');
    END IF;
    PERFORM public.trivia_pvp__user_lock(p_user_id);
    IF p_ticket_id IS NULL THEN
        SELECT * INTO v_t FROM public.trivia_pvp_queue
         WHERE user_id = p_user_id AND engine_version = 'pvp-v2'
         ORDER BY joined_at DESC, id DESC LIMIT 1;
    ELSE
        SELECT * INTO v_t FROM public.trivia_pvp_queue
         WHERE id = p_ticket_id AND user_id = p_user_id AND engine_version = 'pvp-v2';
    END IF;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'ticket_not_found');
    END IF;

    PERFORM public.trivia_pvp__bucket_lock(v_t.stake_amount, v_t.rules_version_id);
    v_now := COALESCE(p_now, clock_timestamp());
    SELECT * INTO v_t FROM public.trivia_pvp_queue WHERE id = v_t.id FOR UPDATE;
    IF v_t.status = 'waiting' THEN
        UPDATE public.trivia_pvp_queue
           SET status = 'cancelled',
               ended_at = GREATEST(v_now, updated_at),
               end_reason = 'cancelled',
               updated_at = GREATEST(v_now, updated_at)
         WHERE id = v_t.id;
        PERFORM public.trivia_pvp__log(NULL, v_t.id, p_user_id, 'human', 'ticket_cancelled', '{}'::jsonb, v_now);
        v_outcome := 'cancelled';
    ELSIF v_t.status = 'matched' THEN
        -- Cancel lost the race to a committed match: the match stands and resumes.
        PERFORM public.trivia_pvp__log(v_t.match_id, v_t.id, p_user_id, 'human',
            'ticket_cancel_lost_race', '{}'::jsonb, v_now);
        v_outcome := 'too_late_matched';
    ELSIF v_t.status = 'cancelled' THEN
        v_outcome := 'already_cancelled';
    ELSE
        v_outcome := 'already_ended';
    END IF;
    RETURN public.trivia_pvp__dto(p_user_id, p_now, false) || jsonb_build_object('cancel', v_outcome);
END;
$$;


ALTER FUNCTION public.trivia_pvp__cancel_core(p_user_id uuid, p_ticket_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 4138 (class 1255 OID 78786007)
-- Name: trivia_pvp__create_horse_match(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__create_horse_match(p_ticket_id uuid, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_t public.trivia_pvp_queue%ROWTYPE;
    v_sel jsonb;
    v_bind jsonb;
    v_match_id uuid;
    v_horse uuid;
    v_attempt integer := 0;
    v_sqlstate text;
    v_message text;
    v_detail text;
    v_constraint text;
BEGIN
    SELECT * INTO v_t FROM public.trivia_pvp_queue WHERE id = p_ticket_id FOR UPDATE;
    IF v_t.id IS NULL OR v_t.status <> 'waiting' OR v_t.lease_expires_at <= p_now
       OR p_now < v_t.horse_eligible_at THEN
        RETURN jsonb_build_object('ok', false, 'error', 'ticket_not_eligible_for_horse');
    END IF;

    LOOP
        v_attempt := v_attempt + 1;
        IF v_attempt > 3 THEN
            RETURN jsonb_build_object('ok', false, 'error', 'horse_contention');
        END IF;
        v_match_id := gen_random_uuid();
        v_sel := public.trivia_pvp__select_horse(
            CASE WHEN v_attempt = 1 THEN v_t.id
                 ELSE extensions.uuid_generate_v5(v_t.id, 'retry:' || v_attempt::text) END,
            v_t.user_id, p_now);
        IF COALESCE((v_sel ->> 'ok')::boolean, false) IS NOT TRUE THEN
            PERFORM public.trivia_pvp__log(NULL, v_t.id, v_t.user_id, 'system', 'horse_unavailable', v_sel, p_now);
            RETURN jsonb_build_object('ok', false, 'error', COALESCE(v_sel ->> 'error', 'no_eligible_horse'));
        END IF;
        v_horse := (v_sel ->> 'horse_id')::uuid;

        BEGIN
            PERFORM set_config('trivia_pvp.v2_authority', v_match_id::text, true);
            v_bind := public.trivia_pvp__bind_match(
                v_match_id, 'human_horse', v_t.user_id, v_horse, v_t.id, NULL,
                v_t.stake_amount, v_t.rules_version_id, p_now, v_sel);
            UPDATE public.trivia_pvp_queue
               SET status = 'matched', match_id = v_match_id, matched_at = p_now, match_kind = 'horse',
                   ended_at = p_now, end_reason = 'matched', updated_at = GREATEST(updated_at, p_now)
             WHERE id = v_t.id;
            PERFORM public.trivia_pvp__log(v_match_id, v_t.id, v_t.user_id, 'system', 'match_created',
                jsonb_build_object('kind', 'human_horse', 'side', 1, 'stake', v_t.stake_amount,
                    'rules_version_id', v_t.rules_version_id,
                    'waited_ms', floor(extract(epoch FROM (p_now - v_t.joined_at)) * 1000)::bigint,
                    'horse_wait_seconds', v_t.horse_wait_seconds,
                    'fallback_late_ms', floor(extract(epoch FROM (p_now - v_t.horse_eligible_at)) * 1000)::bigint,
                    'roster_hash', v_bind ->> 'roster_hash'), p_now);
            PERFORM public.trivia_pvp__log(v_match_id, NULL, v_horse, 'horse', 'horse_selected',
                (v_sel - 'secret_key_id') || jsonb_build_object(
                    'plan_hash', v_bind ->> 'plan_hash', 'model_hash', v_bind ->> 'model_hash',
                    'attempt', v_attempt), p_now);
            PERFORM public.trivia_pvp__log(v_match_id, NULL, NULL, 'system', 'match_active',
                jsonb_build_object('sessions', v_bind -> 'sessions', 'deadline_at', v_bind -> 'deadline_at',
                                   'horse_finishes_at', v_bind -> 'horse_finishes_at'), p_now);
            PERFORM set_config('trivia_pvp.v2_authority', '', true);
            RETURN jsonb_build_object('ok', true, 'match_id', v_match_id, 'horse_id', v_horse);
        EXCEPTION
            WHEN unique_violation THEN
                GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
                IF v_constraint IS DISTINCT FROM 'trivia_pvp_active_seats_one_match_per_user' THEN
                    PERFORM public.trivia_pvp__log(NULL, v_t.id, v_t.user_id, 'system', 'match_create_failed',
                        jsonb_build_object('kind', 'human_horse', 'sqlstate', '23505',
                                           'constraint', v_constraint), p_now);
                    RETURN jsonb_build_object('ok', false, 'error', 'match_create_failed');
                END IF;
                -- The horse was seated concurrently elsewhere: choose again.
            WHEN SQLSTATE 'P5001' THEN
                PERFORM public.trivia_pvp__end_ticket(v_t.id, 'insufficient_funds', p_now);
                PERFORM public.trivia_pvp__log(NULL, v_t.id, v_t.user_id, 'system',
                    'ticket_insufficient_funds', jsonb_build_object('stake', v_t.stake_amount), p_now);
                RETURN jsonb_build_object('ok', false, 'error', 'insufficient_funds');
            WHEN SQLSTATE 'P5002' THEN
                GET STACKED DIAGNOSTICS v_detail = PG_EXCEPTION_DETAIL;
                PERFORM public.trivia_pvp__log(NULL, v_t.id, v_t.user_id, 'system', 'horse_unavailable',
                    jsonb_build_object('error', 'treasury_unavailable', 'ledger_error', v_detail), p_now);
                RETURN jsonb_build_object('ok', false, 'error', 'treasury_unavailable');
            WHEN OTHERS THEN
                GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT,
                                        v_detail = PG_EXCEPTION_DETAIL;
                PERFORM public.trivia_pvp__log(NULL, v_t.id, v_t.user_id, 'system', 'match_create_failed',
                    jsonb_build_object('kind', 'human_horse', 'sqlstate', v_sqlstate,
                                       'message', left(v_message, 200), 'detail', left(v_detail, 200)), p_now);
                RETURN jsonb_build_object('ok', false, 'error', 'match_create_failed', 'sqlstate', v_sqlstate);
        END;
    END LOOP;
END;
$$;


ALTER FUNCTION public.trivia_pvp__create_horse_match(p_ticket_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 7987 (class 1255 OID 78786003)
-- Name: trivia_pvp__create_human_match(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__create_human_match(p_older uuid, p_newer uuid, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_t1 public.trivia_pvp_queue%ROWTYPE;
    v_t2 public.trivia_pvp_queue%ROWTYPE;
    v_failed public.trivia_pvp_queue%ROWTYPE;
    v_match_id uuid := gen_random_uuid();
    v_bind jsonb;
    v_sqlstate text;
    v_detail text;
    v_message text;
BEGIN
    SELECT * INTO v_t1 FROM public.trivia_pvp_queue WHERE id = p_older FOR UPDATE;
    SELECT * INTO v_t2 FROM public.trivia_pvp_queue WHERE id = p_newer FOR UPDATE;
    IF v_t1.id IS NULL OR v_t2.id IS NULL
       OR v_t1.status <> 'waiting' OR v_t2.status <> 'waiting'
       OR v_t1.user_id = v_t2.user_id
       OR v_t1.stake_amount <> v_t2.stake_amount
       OR v_t1.rules_version_id IS DISTINCT FROM v_t2.rules_version_id
       OR v_t1.lease_expires_at <= p_now OR v_t2.lease_expires_at <= p_now THEN
        RETURN jsonb_build_object('ok', false, 'error', 'tickets_not_claimable');
    END IF;

    BEGIN
        PERFORM set_config('trivia_pvp.v2_authority', v_match_id::text, true);
        v_bind := public.trivia_pvp__bind_match(
            v_match_id, 'human_human', v_t1.user_id, v_t2.user_id, v_t1.id, v_t2.id,
            v_t1.stake_amount, v_t1.rules_version_id, p_now, NULL);
        UPDATE public.trivia_pvp_queue
           SET status = 'matched', match_id = v_match_id, matched_at = p_now, match_kind = 'human',
               ended_at = p_now, end_reason = 'matched', updated_at = GREATEST(updated_at, p_now)
         WHERE id IN (v_t1.id, v_t2.id);
        PERFORM public.trivia_pvp__log(v_match_id, t.id, t.user_id, 'system', 'match_created',
                    jsonb_build_object('kind', 'human_human', 'side', t.side, 'stake', t.stake_amount,
                        'rules_version_id', t.rules_version_id,
                        'waited_ms', floor(extract(epoch FROM (p_now - t.joined_at)) * 1000)::bigint,
                        'roster_hash', v_bind ->> 'roster_hash'), p_now)
          FROM (VALUES (1, v_t1.id, v_t1.user_id, v_t1.stake_amount, v_t1.rules_version_id, v_t1.joined_at),
                       (2, v_t2.id, v_t2.user_id, v_t2.stake_amount, v_t2.rules_version_id, v_t2.joined_at))
               AS t(side, id, user_id, stake_amount, rules_version_id, joined_at);
        PERFORM public.trivia_pvp__log(v_match_id, NULL, NULL, 'system', 'match_active',
            jsonb_build_object('sessions', v_bind -> 'sessions', 'deadline_at', v_bind -> 'deadline_at'), p_now);
        PERFORM set_config('trivia_pvp.v2_authority', '', true);
        RETURN jsonb_build_object('ok', true, 'match_id', v_match_id);
    EXCEPTION
        WHEN SQLSTATE 'P5001' THEN
            GET STACKED DIAGNOSTICS v_detail = PG_EXCEPTION_DETAIL;
            v_failed := CASE WHEN v_detail = '1' THEN v_t1 ELSE v_t2 END;
            PERFORM public.trivia_pvp__end_ticket(v_failed.id, 'insufficient_funds', p_now);
            PERFORM public.trivia_pvp__log(NULL, v_failed.id, v_failed.user_id, 'system',
                'ticket_insufficient_funds', jsonb_build_object('stake', v_failed.stake_amount), p_now);
            RETURN jsonb_build_object('ok', false, 'error', 'insufficient_funds', 'failed_ticket_id', v_failed.id);
        WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT,
                                    v_detail = PG_EXCEPTION_DETAIL;
            PERFORM public.trivia_pvp__log(NULL, v_t1.id, v_t1.user_id, 'system', 'match_create_failed',
                jsonb_build_object('kind', 'human_human', 'sqlstate', v_sqlstate,
                                   'message', left(v_message, 200), 'detail', left(v_detail, 200)), p_now);
            RETURN jsonb_build_object('ok', false, 'error', 'match_create_failed', 'sqlstate', v_sqlstate);
    END;
END;
$$;


ALTER FUNCTION public.trivia_pvp__create_human_match(p_older uuid, p_newer uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 5569 (class 1255 OID 78785897)
-- Name: trivia_pvp__draw_wait_seconds(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__draw_wait_seconds() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_bytes bytea;
    v_n bigint;
BEGIN
    LOOP
        v_bytes := extensions.gen_random_bytes(4);
        v_n := (get_byte(v_bytes, 0)::bigint << 24)
             | (get_byte(v_bytes, 1)::bigint << 16)
             | (get_byte(v_bytes, 2)::bigint << 8)
             |  get_byte(v_bytes, 3)::bigint;
        -- 4294967274 = 26 * floor(2^32 / 26): the largest unbiased prefix.
        EXIT WHEN v_n < 4294967274;
    END LOOP;
    RETURN 20 + (v_n % 26)::integer;
END;
$$;


ALTER FUNCTION public.trivia_pvp__draw_wait_seconds() OWNER TO postgres;

--
-- TOC entry 8645 (class 1255 OID 78786094)
-- Name: trivia_pvp__drive_match(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__drive_match(p_match_id uuid, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_m public.trivia_pvp_matches%ROWTYPE;
    v_plan public.trivia_pvp_horse_plans%ROWTYPE;
    v_s public.trivia_sessions%ROWTYPE;
    v_e jsonb;
    v_display integer;
    v_r jsonb;
    v_recorded integer;
    v_seat record;
    v_submitted integer := 0;
    v_now timestamptz := COALESCE(p_now, clock_timestamp());
BEGIN
    SELECT * INTO v_m FROM public.trivia_pvp_matches WHERE id = p_match_id;
    IF v_m.id IS NULL OR v_m.engine_version IS DISTINCT FROM 'pvp-v2' OR v_m.status <> 'active' THEN
        RETURN jsonb_build_object('driven', false);
    END IF;

    IF v_m.horse_side IS NOT NULL THEN
        SELECT * INTO v_plan FROM public.trivia_pvp_horse_plans WHERE match_id = p_match_id FOR UPDATE;
        SELECT * INTO v_s FROM public.trivia_sessions WHERE id = v_plan.session_id;
        v_recorded := v_plan.answers_recorded;
        IF v_s.status = 'open' THEN
            FOR v_e IN
                SELECT value FROM jsonb_array_elements(v_plan.plan)
                 WHERE (value ->> 'i')::integer > v_plan.answers_recorded
                   AND v_plan.starts_at + make_interval(secs => (value ->> 't')::bigint / 1000.0) <= v_now
                 ORDER BY (value ->> 'i')::integer
            LOOP
                SELECT (e.ord - 1)::integer INTO v_display
                  FROM jsonb_array_elements_text(v_s.permutations -> (v_e ->> 'q')) WITH ORDINALITY AS e(v, ord)
                 WHERE e.v::integer = (v_e ->> 'o')::integer;
                v_r := public.trivia_session_answer_v3(v_s.id, v_plan.horse_id, (v_e ->> 'q')::uuid, v_display,
                    extensions.uuid_generate_v5(p_match_id, 'horse-answer:' || (v_e ->> 'i')));
                EXIT WHEN COALESCE((v_r ->> 'recorded')::boolean, false) IS NOT TRUE;
                v_recorded := (v_e ->> 'i')::integer;
            END LOOP;
            IF v_recorded > v_plan.answers_recorded THEN
                UPDATE public.trivia_pvp_horse_plans SET answers_recorded = v_recorded WHERE match_id = p_match_id;
            END IF;
        END IF;
    END IF;

    FOR v_seat IN
        SELECT l.side, l.user_id, s.id AS session_id
          FROM public.trivia_pvp_session_links AS l
          JOIN public.trivia_sessions AS s ON s.id = l.session_id
         WHERE l.match_id = p_match_id AND s.status = 'open'
           AND NOT EXISTS (SELECT 1 FROM public.trivia_session_answers AS a
                            WHERE a.session_id = s.id AND a.outcome IS NULL)
         ORDER BY l.side
    LOOP
        v_r := public.trivia_session_submit_v3(v_seat.session_id, v_seat.user_id,
            extensions.uuid_generate_v5(p_match_id, 'complete:' || v_seat.side::text));
        IF COALESCE((v_r ->> 'success')::boolean, false) THEN
            v_submitted := v_submitted + 1;
            IF v_m.horse_side = v_seat.side THEN
                UPDATE public.trivia_pvp_horse_plans
                   SET submitted_at = COALESCE(submitted_at, (v_r ->> 'completed_at')::timestamptz)
                 WHERE match_id = p_match_id;
                PERFORM public.trivia_pvp__log(p_match_id, NULL, v_seat.user_id, 'horse', 'horse_submitted',
                    jsonb_build_object('answered', v_r -> 'answered'), v_now);
            END IF;
        END IF;
    END LOOP;
    RETURN jsonb_build_object('driven', true, 'horse_answers_recorded', v_recorded, 'submitted', v_submitted);
END;
$$;


ALTER FUNCTION public.trivia_pvp__drive_match(p_match_id uuid, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 6159 (class 1255 OID 78785986)
-- Name: trivia_pvp__dto(uuid, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__dto(p_user_id uuid, p_now timestamp with time zone, p_horses_allowed boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_now timestamptz := COALESCE(p_now, clock_timestamp());
    v_cfg public.trivia_pvp_engine_config%ROWTYPE;
    v_t public.trivia_pvp_queue%ROWTYPE;
    v_has_ticket boolean := false;
    v_m public.trivia_pvp_matches%ROWTYPE;
    v_has_match boolean := false;
    v_side smallint;
    v_opp_side smallint;
    v_opp_id uuid;
    v_opp record;
    v_my_session public.trivia_sessions%ROWTYPE;
    v_opp_session public.trivia_sessions%ROWTYPE;
    v_my_answered integer := 0;
    v_my_total integer := 0;
    v_my_done boolean := false;
    v_opp_answered integer := 0;
    v_opp_done boolean := false;
    v_decision public.trivia_pvp_settlement_decisions%ROWTYPE;
    v_state text := 'idle';
    v_ticket_json jsonb;
    v_match_json jsonb;
    v_result_json jsonb;
    v_poll integer;
    v_my_credit integer := 0;
    v_receipts jsonb := '[]'::jsonb;
    v_outcome text;
BEGIN
    SELECT * INTO v_cfg FROM public.trivia_pvp_engine_config WHERE id = 1;

    SELECT * INTO v_t FROM public.trivia_pvp_queue
     WHERE user_id = p_user_id AND engine_version = 'pvp-v2'
     ORDER BY joined_at DESC, id DESC LIMIT 1;
    v_has_ticket := FOUND;

    SELECT m.* INTO v_m
      FROM public.trivia_pvp_active_seats AS s
      JOIN public.trivia_pvp_matches AS m ON m.id = s.match_id
     WHERE s.user_id = p_user_id AND m.engine_version = 'pvp-v2';
    v_has_match := FOUND;
    IF NOT v_has_match AND v_has_ticket AND v_t.match_id IS NOT NULL THEN
        SELECT * INTO v_m FROM public.trivia_pvp_matches WHERE id = v_t.match_id;
        v_has_match := FOUND;
    END IF;

    IF v_has_ticket THEN
        v_ticket_json := jsonb_build_object(
            'id', v_t.id,
            'status', v_t.status,
            'stake', v_t.stake_amount,
            'rules_version_id', v_t.rules_version_id,
            'joined_at', v_t.joined_at,
            'horse_wait_seconds', v_t.horse_wait_seconds,
            'horse_eligible_at', v_t.horse_eligible_at,
            'seconds_until_horse_eligible',
                GREATEST(0, ceil(extract(epoch FROM (v_t.horse_eligible_at - v_now))))::integer,
            'horse_fallback_enabled', COALESCE(p_horses_allowed, false) AND v_cfg.horses_enabled,
            'lease_expires_at', v_t.lease_expires_at,
            'presence', CASE WHEN v_t.status <> 'waiting' THEN 'ended'
                             WHEN v_t.lease_expires_at > v_now THEN 'live' ELSE 'lapsed' END,
            'search_expires_at', v_t.expires_at,
            'ended_at', v_t.ended_at,
            'end_reason', v_t.end_reason,
            'match_kind', v_t.match_kind);
    END IF;

    IF v_has_match THEN
        v_side := CASE WHEN v_m.player1_id = p_user_id THEN 1
                       WHEN v_m.player2_id = p_user_id THEN 2 END;
        IF v_side IS NULL THEN
            RAISE EXCEPTION 'pvp dto: caller is not a participant';
        END IF;
        v_opp_side := 3 - v_side;
        v_opp_id := CASE WHEN v_side = 1 THEN v_m.player2_id ELSE v_m.player1_id END;
        SELECT p.is_horse IS TRUE AS is_horse,
               COALESCE(NULLIF(btrim(p.display_name), ''), NULLIF(btrim(p.username), ''), 'Player') AS display_name,
               p.avatar_url
          INTO v_opp
          FROM public.profiles AS p WHERE p.id = v_opp_id;

        SELECT s.* INTO v_my_session
          FROM public.trivia_pvp_session_links AS l
          JOIN public.trivia_sessions AS s ON s.id = l.session_id
         WHERE l.match_id = v_m.id AND l.side = v_side;
        IF FOUND THEN
            v_my_answered := (SELECT count(*) FROM public.trivia_session_answers AS a
                               WHERE a.session_id = v_my_session.id AND a.outcome IS NOT NULL);
            v_my_total := COALESCE(cardinality(v_my_session.question_ids), 0);
            v_my_done := v_my_session.status IN ('submitted', 'expired');
        END IF;

        -- Humans and horses report progress from the same place: their own
        -- engine v3 seat session. A horse's answers exist there only once its
        -- input device has actually recorded them.
        SELECT s.* INTO v_opp_session
          FROM public.trivia_pvp_session_links AS l
          JOIN public.trivia_sessions AS s ON s.id = l.session_id
         WHERE l.match_id = v_m.id AND l.side = v_opp_side;
        IF FOUND THEN
            v_opp_answered := (SELECT count(*) FROM public.trivia_session_answers AS a
                                WHERE a.session_id = v_opp_session.id AND a.outcome IS NOT NULL);
            v_opp_done := v_opp_session.status IN ('submitted', 'expired');
        END IF;

        v_match_json := jsonb_build_object(
            'id', v_m.id,
            'kind', v_m.match_kind,
            'status', v_m.status,
            'stake', v_m.stake_amount,
            'rules_version_id', v_m.rules_version_id,
            'question_count', COALESCE(NULLIF(v_my_total, 0), jsonb_array_length(COALESCE(v_m.questions, '[]'::jsonb))),
            'created_at', v_m.created_at,
            'activated_at', v_m.activated_at,
            'deadline_at', v_m.deadline_at,
            'my_side', v_side,
            'my_session_id', v_my_session.id,
            'me', jsonb_build_object('answered', v_my_answered, 'finished', v_my_done),
            'opponent', jsonb_build_object(
                'kind', CASE WHEN COALESCE(v_opp.is_horse, false) THEN 'horse' ELSE 'human' END,
                'is_horse', COALESCE(v_opp.is_horse, false),
                'label', CASE WHEN COALESCE(v_opp.is_horse, false) THEN 'Smarter Horse' ELSE 'Player' END,
                'display_name', COALESCE(v_opp.display_name, 'Player'),
                'avatar_url', v_opp.avatar_url,
                'answered', v_opp_answered,
                'finished', v_opp_done));

        IF v_m.status IN ('complete', 'completed') THEN
            SELECT * INTO v_decision FROM public.trivia_pvp_settlement_decisions WHERE match_id = v_m.id;
            SELECT COALESCE(sum((c.value ->> 'amount')::integer), 0)::integer,
                   COALESCE(jsonb_agg(jsonb_build_object(
                       'reference', c.value ->> 'reference_id',
                       'kind', c.value ->> 'transaction_type',
                       'amount', (c.value ->> 'amount')::integer)), '[]'::jsonb)
              INTO v_my_credit, v_receipts
              FROM jsonb_array_elements(COALESCE(v_decision.credit_plan, '[]'::jsonb)) AS c(value)
             WHERE (c.value ->> 'user_id')::uuid = p_user_id
               AND COALESCE(c.value ->> 'leg', 'player_credit') = 'player_credit';
            v_outcome := CASE
                WHEN v_decision.decision_kind = 'win' AND v_decision.winner_id = p_user_id THEN 'win'
                WHEN v_decision.decision_kind = 'win' THEN 'loss'
                WHEN v_decision.decision_kind = 'tie' THEN 'tie'
                WHEN v_decision.decision_kind = 'refund' AND v_my_credit > 0 THEN 'refund'
                ELSE 'void' END;
            v_result_json := jsonb_build_object(
                'outcome', v_outcome,
                'decision', v_decision.decision_kind,
                'forfeit', v_decision.forfeit,
                'my_correct', CASE WHEN v_side = 1 THEN v_decision.player1_score ELSE v_decision.player2_score END,
                'opponent_correct', CASE WHEN v_side = 1 THEN v_decision.player2_score ELSE v_decision.player1_score END,
                'stake', v_m.stake_amount,
                'pot', v_m.stake_amount * 2,
                'rake', COALESCE((SELECT sum((c.value ->> 'amount')::integer)
                                    FROM jsonb_array_elements(COALESCE(v_decision.credit_plan, '[]'::jsonb)) AS c(value)
                                   WHERE c.value ->> 'leg' = 'rake'), 0),
                'rake_on_win', (public.trivia_rules_pvp_money(v_m.rules_version_id, v_m.stake_amount) ->> 'rake')::integer,
                'payout', v_my_credit,
                'net', v_my_credit - v_m.stake_amount,
                'receipts', v_receipts,
                'stake_reference', 'pvp_stake_' || v_m.id::text || '_' || p_user_id::text,
                'settlement_reference', v_decision.reference_family,
                'settled_at', v_m.completed_at);
        END IF;

        v_state := CASE
            WHEN v_m.status IN ('complete', 'completed') THEN 'result'
            WHEN v_m.status = 'settling' THEN 'settling'
            WHEN v_m.status = 'pending' THEN 'dealing'
            WHEN v_my_done AND v_opp_done THEN 'settling'
            WHEN v_my_done THEN 'waiting'
            WHEN v_my_answered = 0 AND v_now < COALESCE(v_m.activated_at, v_m.created_at)
                                                  + make_interval(secs => v_cfg.dealing_seconds) THEN 'dealing'
            ELSE 'playing' END;
        IF v_state = 'result' AND v_m.completed_at < v_now - make_interval(secs => v_cfg.result_visible_seconds)
           AND (NOT v_has_ticket OR v_t.match_id IS DISTINCT FROM v_m.id) THEN
            v_state := 'idle';
        END IF;
    ELSIF v_has_ticket THEN
        v_state := CASE
            WHEN v_t.status = 'waiting' THEN 'searching'
            WHEN v_t.ended_at > v_now - make_interval(secs => v_cfg.result_visible_seconds) THEN 'search_ended'
            ELSE 'idle' END;
    END IF;

    v_poll := CASE v_state
        WHEN 'searching' THEN GREATEST(250, LEAST(v_cfg.heartbeat_seconds * 1000,
                 CASE WHEN v_t.horse_eligible_at > v_now
                      THEN ceil(extract(epoch FROM (v_t.horse_eligible_at - v_now)) * 1000)::integer + 50
                      ELSE v_cfg.heartbeat_seconds * 1000 END))
        WHEN 'dealing' THEN 1000
        WHEN 'playing' THEN 2000
        WHEN 'waiting' THEN 1500
        WHEN 'settling' THEN 1500
        ELSE NULL END;

    RETURN jsonb_build_object(
        'success', true,
        'engine', 'pvp-v2',
        'server_now', v_now,
        'state', v_state,
        'poll_after_ms', v_poll,
        'heartbeat_seconds', v_cfg.heartbeat_seconds,
        'ticket', v_ticket_json,
        'match', v_match_json,
        'result', v_result_json);
END;
$$;


ALTER FUNCTION public.trivia_pvp__dto(p_user_id uuid, p_now timestamp with time zone, p_horses_allowed boolean) OWNER TO postgres;

--
-- TOC entry 4598 (class 1255 OID 78786002)
-- Name: trivia_pvp__end_ticket(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__end_ticket(p_ticket_id uuid, p_reason text, p_now timestamp with time zone) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
    UPDATE public.trivia_pvp_queue
       SET status = 'expired', ended_at = GREATEST(p_now, updated_at),
           end_reason = p_reason, updated_at = GREATEST(p_now, updated_at)
     WHERE id = p_ticket_id AND status = 'waiting';
$$;


ALTER FUNCTION public.trivia_pvp__end_ticket(p_ticket_id uuid, p_reason text, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 8248 (class 1255 OID 78785921)
-- Name: trivia_pvp__ensure_horse_personas(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__ensure_horse_personas() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_count integer;
BEGIN
    INSERT INTO public.trivia_pvp_horse_personas (horse_id)
    SELECT p.id
      FROM public.profiles AS p
     WHERE p.is_horse IS TRUE
       AND NOT EXISTS (SELECT 1 FROM public.trivia_pvp_horse_personas AS h WHERE h.horse_id = p.id)
    ON CONFLICT (horse_id) DO NOTHING;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


ALTER FUNCTION public.trivia_pvp__ensure_horse_personas() OWNER TO postgres;

--
-- TOC entry 5833 (class 1255 OID 78785951)
-- Name: trivia_pvp__expire_dead(integer, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__expire_dead(p_stake integer, p_rules_version text, p_now timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_cfg public.trivia_pvp_engine_config%ROWTYPE;
    v_row record;
    v_count integer := 0;
BEGIN
    SELECT * INTO v_cfg FROM public.trivia_pvp_engine_config WHERE id = 1;
    FOR v_row IN
        UPDATE public.trivia_pvp_queue AS q
           SET status = 'expired',
               ended_at = GREATEST(p_now, q.updated_at),
               end_reason = CASE WHEN q.expires_at <= p_now THEN 'search_expired' ELSE 'lease_expired' END,
               updated_at = GREATEST(p_now, q.updated_at)
         WHERE q.engine_version = 'pvp-v2'
           AND q.status = 'waiting'
           AND q.stake_amount = p_stake
           AND q.rules_version_id = p_rules_version
           AND (q.expires_at <= p_now
                OR q.lease_expires_at <= p_now - make_interval(secs => v_cfg.dead_ticket_grace_seconds))
        RETURNING q.id, q.user_id, q.end_reason, q.lease_expires_at, q.expires_at
    LOOP
        v_count := v_count + 1;
        PERFORM public.trivia_pvp__log(NULL, v_row.id, v_row.user_id, 'system', 'ticket_expired',
            jsonb_build_object('end_reason', v_row.end_reason,
                               'lease_expires_at', v_row.lease_expires_at,
                               'expires_at', v_row.expires_at), p_now);
    END LOOP;
    RETURN v_count;
END;
$$;


ALTER FUNCTION public.trivia_pvp__expire_dead(p_stake integer, p_rules_version text, p_now timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 4472 (class 1255 OID 78785908)
-- Name: trivia_pvp__horse_category_strength(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__horse_category_strength(p_horse_id uuid, p_category text, p_overrides jsonb) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_raw numeric;
    v_u double precision;
    v_s double precision;
BEGIN
    IF p_overrides IS NOT NULL AND jsonb_typeof(p_overrides) = 'object'
       AND p_overrides ? COALESCE(p_category, 'general')
       AND jsonb_typeof(p_overrides -> COALESCE(p_category, 'general')) = 'number' THEN
        v_raw := (p_overrides ->> COALESCE(p_category, 'general'))::numeric;
        RETURN round(GREATEST(-1, LEAST(1, v_raw)), 3);
    END IF;
    v_u := (('x' || substr(encode(extensions.digest(
                'pvp-horse-persona/1:' || p_horse_id::text || ':' || COALESCE(p_category, 'general'),
                'sha256'), 'hex'), 1, 13))::bit(52)::bigint)::double precision
           / 4503599627370496.0::double precision;
    v_s := 2.0 * v_u - 1.0;
    RETURN round((sign(v_s) * v_s * v_s)::numeric, 3);
END;
$$;


ALTER FUNCTION public.trivia_pvp__horse_category_strength(p_horse_id uuid, p_category text, p_overrides jsonb) OWNER TO postgres;

--
-- TOC entry 5780 (class 1255 OID 78785911)
-- Name: trivia_pvp__horse_tier_model(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__horse_tier_model(p_tier text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
    SELECT jsonb_build_object(
        'version', 'pvp-horse-model/1',
        'tier', t.tier,
        'base_accuracy', t.acc,
        'rt_median_ms', t.rt,
        'rt_sigma', 0.35,
        'incorrect_rt_factor', 1.10,
        'strength_weight', 0.10,
        'accuracy_bounds', jsonb_build_array(0.20, 0.92),
        'rt_min_ms', 1800,
        'rt_max_median_multiple', 3.0,
        'deal_delay_ms', jsonb_build_array(2500, 5000),
        'difficulty_accuracy', jsonb_build_object('easy', 0.12, 'medium', 0.0, 'hard', -0.12),
        'difficulty_rt', jsonb_build_object('easy', 0.85, 'medium', 1.0, 'hard', 1.25)
    )
    FROM (
        SELECT CASE WHEN p_tier IN ('Newcomer', 'Regular', 'Intermediate', 'Grinder', 'Shark')
                    THEN p_tier ELSE 'Newcomer' END AS tier
    ) AS chosen
    CROSS JOIN LATERAL (
        VALUES
            ('Newcomer', 0.55::numeric, 9000),
            ('Regular', 0.62::numeric, 8000),
            ('Intermediate', 0.68::numeric, 7000),
            ('Grinder', 0.74::numeric, 6200),
            ('Shark', 0.80::numeric, 5200)
    ) AS t(tier, acc, rt)
    WHERE t.tier = chosen.tier;
$$;


ALTER FUNCTION public.trivia_pvp__horse_tier_model(p_tier text) OWNER TO postgres;

--
-- TOC entry 5561 (class 1255 OID 78785956)
-- Name: trivia_pvp__join_core(uuid, integer, uuid, boolean, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__join_core(p_user_id uuid, p_stake integer, p_client_nonce uuid, p_horses_allowed boolean, p_now timestamp with time zone DEFAULT NULL::timestamp with time zone, p_wait_seconds integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_cfg public.trivia_pvp_engine_config%ROWTYPE;
    v_ticket public.trivia_pvp_queue%ROWTYPE;
    v_rules jsonb;
    v_rules_version text;
    v_wait integer;
    v_now timestamptz;
    v_available bigint;
BEGIN
    IF p_user_id IS NULL OR p_client_nonce IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_request');
    END IF;
    IF p_stake IS NULL OR p_stake NOT IN (10, 25, 50, 100) THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_stake');
    END IF;
    IF p_wait_seconds IS NOT NULL AND p_wait_seconds NOT BETWEEN 20 AND 45 THEN
        RAISE EXCEPTION 'horse wait must be 20..45 seconds';
    END IF;
    PERFORM public.trivia_pvp__user_lock(p_user_id);

    -- Retry with the same nonce: the same ticket, whatever happened to it.
    SELECT * INTO v_ticket
      FROM public.trivia_pvp_queue
     WHERE user_id = p_user_id AND client_nonce = p_client_nonce;
    IF FOUND THEN
        PERFORM public.trivia_pvp__log(v_ticket.match_id, v_ticket.id, p_user_id, 'human',
            'ticket_join_replayed', jsonb_build_object('status', v_ticket.status),
            COALESCE(p_now, clock_timestamp()));
        RETURN public.trivia_pvp__status_core(p_user_id, v_ticket.id, p_horses_allowed, p_now)
               || jsonb_build_object('join', 'replayed');
    END IF;

    -- One active competitive match per player: resume it, never open another.
    IF EXISTS (SELECT 1 FROM public.trivia_pvp_active_seats WHERE user_id = p_user_id) THEN
        RETURN public.trivia_pvp__status_core(p_user_id, NULL, p_horses_allowed, p_now)
               || jsonb_build_object('join', 'already_in_match');
    END IF;

    -- One waiting ticket per player: a second tab or a lost nonce adopts it.
    SELECT * INTO v_ticket
      FROM public.trivia_pvp_queue
     WHERE user_id = p_user_id AND status = 'waiting';
    IF FOUND THEN
        IF v_ticket.engine_version IS DISTINCT FROM 'pvp-v2' THEN
            RETURN jsonb_build_object('success', false, 'error', 'legacy_ticket_present');
        END IF;
        PERFORM public.trivia_pvp__log(NULL, v_ticket.id, p_user_id, 'human', 'ticket_join_adopted',
            jsonb_build_object('requested_stake', p_stake), COALESCE(p_now, clock_timestamp()));
        RETURN public.trivia_pvp__status_core(p_user_id, v_ticket.id, p_horses_allowed, p_now)
               || jsonb_build_object('join', 'already_searching',
                                     'stake_mismatch', v_ticket.stake_amount <> p_stake);
    END IF;

    SELECT * INTO v_cfg FROM public.trivia_pvp_engine_config WHERE id = 1;
    IF NOT v_cfg.joins_enabled THEN
        RETURN jsonb_build_object('success', false, 'error', 'pvp_joins_paused');
    END IF;

    v_rules := public.trivia_rules_current('pvp.standard');
    v_rules_version := v_rules ->> 'id';
    IF v_rules_version IS NULL OR jsonb_typeof(v_rules -> 'rules' -> 'stakes') IS DISTINCT FROM 'array' THEN
        RETURN jsonb_build_object('success', false, 'error', 'rules_unavailable');
    END IF;
    IF NOT ((v_rules -> 'rules' -> 'stakes') @> to_jsonb(p_stake)) THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_stake');
    END IF;

    -- Pre-check only; no diamonds move until both seats are escrowed at match time.
    SELECT COALESCE(p.diamonds, 0) INTO v_available FROM public.profiles AS p WHERE p.id = p_user_id;
    IF v_available IS NULL OR v_available < p_stake THEN
        RETURN jsonb_build_object('success', false, 'error', 'insufficient_diamonds');
    END IF;

    v_wait := COALESCE(p_wait_seconds, public.trivia_pvp__draw_wait_seconds());

    PERFORM public.trivia_pvp__bucket_lock(p_stake, v_rules_version);
    v_now := COALESCE(p_now, clock_timestamp());
    PERFORM set_config('trivia_pvp.v2_authority', 'ticket:' || p_user_id::text, true);
    INSERT INTO public.trivia_pvp_queue (
        user_id, stake_amount, status, expires_at, created_at,
        engine_version, client_nonce, rules_version_id, joined_at,
        heartbeat_at, lease_expires_at, horse_wait_seconds, horse_eligible_at, updated_at
    ) VALUES (
        p_user_id, p_stake, 'waiting',
        v_now + make_interval(secs => GREATEST(v_cfg.max_search_seconds, v_wait + 30)), v_now,
        'pvp-v2', p_client_nonce, v_rules_version, v_now,
        v_now, v_now + make_interval(secs => v_cfg.lease_seconds), v_wait,
        v_now + make_interval(secs => v_wait), v_now
    ) RETURNING * INTO v_ticket;
    PERFORM set_config('trivia_pvp.v2_authority', '', true);

    PERFORM public.trivia_pvp__log(NULL, v_ticket.id, p_user_id, 'human', 'ticket_joined',
        jsonb_build_object('stake', p_stake, 'rules_version_id', v_rules_version,
                           'horse_wait_seconds', v_wait,
                           'horse_eligible_at', v_ticket.horse_eligible_at), v_now);

    PERFORM public.trivia_pvp__try_match(v_ticket.id, p_horses_allowed, p_now);
    RETURN public.trivia_pvp__dto(p_user_id, p_now, p_horses_allowed)
           || jsonb_build_object('join', 'created');
END;
$$;


ALTER FUNCTION public.trivia_pvp__join_core(p_user_id uuid, p_stake integer, p_client_nonce uuid, p_horses_allowed boolean, p_now timestamp with time zone, p_wait_seconds integer) OWNER TO postgres;

--
-- TOC entry 6870 (class 1255 OID 108013201)
-- Name: trivia_pvp__join_core_v3(uuid, integer, uuid, boolean, text, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__join_core_v3(p_user_id uuid, p_stake integer, p_client_nonce uuid, p_horses_allowed boolean, p_expected_rules_version text, p_now timestamp with time zone DEFAULT NULL::timestamp with time zone, p_wait_seconds integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_cfg public.trivia_pvp_engine_config%ROWTYPE;
    v_ticket public.trivia_pvp_queue%ROWTYPE;
    v_rules jsonb;
    v_rules_version text;
    v_existing_rules_version text;
    v_wait integer;
    v_now timestamptz;
    v_available bigint;
    v_effective_horses boolean;
BEGIN
    IF p_user_id IS NULL OR p_client_nonce IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_request');
    END IF;
    IF p_stake IS NULL OR p_stake NOT IN (10, 25, 50, 100) THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_stake');
    END IF;
    IF p_expected_rules_version IS NULL
       OR p_expected_rules_version !~ '^pvp\.standard@[1-9][0-9]*$' THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_rules_version');
    END IF;
    IF p_wait_seconds IS NOT NULL AND p_wait_seconds NOT BETWEEN 20 AND 45 THEN
        RAISE EXCEPTION 'horse wait must be 20..45 seconds';
    END IF;

    -- Serializes every user join/retry. This advisory lock changes no state.
    PERFORM public.trivia_pvp__user_lock(p_user_id);

    -- A replay is valid only for the exact rules quote already stored on that
    -- ticket. This keeps idempotency across a later global rules activation.
    SELECT *
      INTO v_ticket
      FROM public.trivia_pvp_queue
     WHERE user_id = p_user_id
       AND client_nonce = p_client_nonce;
    IF FOUND THEN
        IF v_ticket.rules_version_id IS DISTINCT FROM p_expected_rules_version THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'rules_quote_stale',
                'quotedRulesVersion', p_expected_rules_version,
                'storedRulesVersion', v_ticket.rules_version_id);
        END IF;
        PERFORM public.trivia_pvp__log(
            v_ticket.match_id, v_ticket.id, p_user_id, 'human',
            'ticket_join_replayed', jsonb_build_object('status', v_ticket.status),
            COALESCE(p_now, clock_timestamp()));
        RETURN public.trivia_pvp__status_core(
            p_user_id, v_ticket.id, p_horses_allowed, p_now)
            || jsonb_build_object('join', 'replayed');
    END IF;

    -- A join request can recover an existing match, but it cannot use a quote
    -- for different rules to drive that match's next state transition.
    SELECT m.rules_version_id
      INTO v_existing_rules_version
      FROM public.trivia_pvp_active_seats AS s
      JOIN public.trivia_pvp_matches AS m ON m.id = s.match_id
     WHERE s.user_id = p_user_id;
    IF FOUND THEN
        IF v_existing_rules_version IS DISTINCT FROM p_expected_rules_version THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'rules_quote_stale',
                'quotedRulesVersion', p_expected_rules_version,
                'storedRulesVersion', v_existing_rules_version);
        END IF;
        RETURN public.trivia_pvp__status_core(p_user_id, NULL, p_horses_allowed, p_now)
            || jsonb_build_object('join', 'already_in_match');
    END IF;

    -- A second tab adopts the one durable waiting ticket only when it presents
    -- that ticket's rules version. It never creates a second entry.
    SELECT *
      INTO v_ticket
      FROM public.trivia_pvp_queue
     WHERE user_id = p_user_id
       AND status = 'waiting';
    IF FOUND THEN
        IF v_ticket.engine_version IS DISTINCT FROM 'pvp-v2' THEN
            RETURN jsonb_build_object('success', false, 'error', 'legacy_ticket_present');
        END IF;
        IF v_ticket.rules_version_id IS DISTINCT FROM p_expected_rules_version THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'rules_quote_stale',
                'quotedRulesVersion', p_expected_rules_version,
                'storedRulesVersion', v_ticket.rules_version_id);
        END IF;
        PERFORM public.trivia_pvp__log(
            NULL, v_ticket.id, p_user_id, 'human', 'ticket_join_adopted',
            jsonb_build_object('requested_stake', p_stake),
            COALESCE(p_now, clock_timestamp()));
        RETURN public.trivia_pvp__status_core(
            p_user_id, v_ticket.id, p_horses_allowed, p_now)
            || jsonb_build_object(
                'join', 'already_searching',
                'stake_mismatch', v_ticket.stake_amount <> p_stake);
    END IF;

    -- Lock both mutable pointers for the rest of this transaction. The rules
    -- document itself is immutable, so the captured id owns all economics
    -- below even if an operator attempts to activate another version.
    SELECT c.rules_version_id
      INTO v_rules_version
      FROM public.trivia_rules_current AS c
     WHERE c.rules_key = 'pvp.standard'
     FOR SHARE OF c;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'rules_unavailable');
    END IF;
    IF v_rules_version IS DISTINCT FROM p_expected_rules_version THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'rules_quote_stale',
            'quotedRulesVersion', p_expected_rules_version,
            'currentRulesVersion', v_rules_version);
    END IF;

    SELECT *
      INTO v_cfg
      FROM public.trivia_pvp_engine_config
     WHERE id = 1
     FOR SHARE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'pvp_configuration_unavailable');
    END IF;
    IF NOT v_cfg.joins_enabled THEN
        RETURN jsonb_build_object('success', false, 'error', 'pvp_joins_paused');
    END IF;

    v_rules := public.trivia_rules_get(v_rules_version);
    IF v_rules ->> 'id' IS DISTINCT FROM v_rules_version
       OR jsonb_typeof(v_rules -> 'rules' -> 'stakes') IS DISTINCT FROM 'array' THEN
        RETURN jsonb_build_object('success', false, 'error', 'rules_unavailable');
    END IF;
    IF NOT ((v_rules -> 'rules' -> 'stakes') @> to_jsonb(p_stake)) THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_stake');
    END IF;

    -- Pre-check only. No Diamonds move until both seats are escrowed by the
    -- match creation authority later in this same transaction.
    SELECT COALESCE(p.diamonds, 0)
      INTO v_available
      FROM public.profiles AS p
     WHERE p.id = p_user_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'profile_not_found');
    END IF;
    IF v_available < p_stake THEN
        RETURN jsonb_build_object('success', false, 'error', 'insufficient_diamonds');
    END IF;

    v_wait := COALESCE(p_wait_seconds, public.trivia_pvp__draw_wait_seconds());
    v_effective_horses := COALESCE(p_horses_allowed, false) AND v_cfg.horses_enabled;
    PERFORM public.trivia_pvp__bucket_lock(p_stake, v_rules_version);
    v_now := COALESCE(p_now, clock_timestamp());
    PERFORM set_config('trivia_pvp.v2_authority', 'ticket:' || p_user_id::text, true);
    INSERT INTO public.trivia_pvp_queue (
        user_id, stake_amount, status, expires_at, created_at,
        engine_version, client_nonce, rules_version_id, joined_at,
        heartbeat_at, lease_expires_at, horse_wait_seconds, horse_eligible_at, updated_at
    ) VALUES (
        p_user_id, p_stake, 'waiting',
        v_now + make_interval(secs => GREATEST(v_cfg.max_search_seconds, v_wait + 30)), v_now,
        'pvp-v2', p_client_nonce, v_rules_version, v_now,
        v_now, v_now + make_interval(secs => v_cfg.lease_seconds), v_wait,
        v_now + make_interval(secs => v_wait), v_now
    ) RETURNING * INTO v_ticket;
    PERFORM set_config('trivia_pvp.v2_authority', '', true);

    PERFORM public.trivia_pvp__log(
        NULL, v_ticket.id, p_user_id, 'human', 'ticket_joined',
        jsonb_build_object(
            'stake', p_stake,
            'rules_version_id', v_rules_version,
            'quoted_rules_version_id', p_expected_rules_version,
            'horse_wait_seconds', v_wait,
            'horse_eligible_at', v_ticket.horse_eligible_at),
        v_now);

    PERFORM public.trivia_pvp__try_match(v_ticket.id, v_effective_horses, p_now);
    RETURN public.trivia_pvp__dto(p_user_id, p_now, v_effective_horses)
        || jsonb_build_object('join', 'created');
END;
$_$;


