--
-- TOC entry 7317 (class 1255 OID 78785907)
-- Name: trivia_pvp__normal(bytea, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp__normal(p_key bytea, p_label text) RETURNS double precision
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
    SELECT sqrt(-2.0 * ln(GREATEST(public.trivia_pvp__u01(p_key, p_label || ':a'), 1e-12)))
           * cos(2.0 * pi() * public.trivia_pvp__u01(p_key, p_label || ':b'));
$$;


