--
-- TOC entry 7858 (class 1255 OID 78785836)
-- Name: trivia_pvp_queue_v2_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp_queue_v2_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.engine_version IS NOT NULL THEN
            RAISE EXCEPTION 'pvp v2 queue tickets are retained evidence';
        END IF;
        RETURN OLD;
    END IF;

    IF TG_OP = 'INSERT' THEN
        IF NEW.engine_version IS NOT NULL AND NEW.status IS DISTINCT FROM 'waiting' THEN
            RAISE EXCEPTION 'a new pvp v2 ticket must start waiting';
        END IF;
        IF NEW.engine_version IS NOT NULL
           AND current_setting('trivia_pvp.v2_authority', true) IS DISTINCT FROM ('ticket:' || NEW.user_id::text) THEN
            RAISE EXCEPTION 'pvp v2 tickets (and their horse deadline) are created only by the join authority';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.engine_version IS DISTINCT FROM OLD.engine_version THEN
        RAISE EXCEPTION 'pvp ticket engine version is immutable';
    END IF;
    IF NEW.engine_version IS NULL THEN
        RETURN NEW;
    END IF;

    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.user_id IS DISTINCT FROM OLD.user_id
       OR NEW.stake_amount IS DISTINCT FROM OLD.stake_amount
       OR NEW.client_nonce IS DISTINCT FROM OLD.client_nonce
       OR NEW.rules_version_id IS DISTINCT FROM OLD.rules_version_id
       OR NEW.joined_at IS DISTINCT FROM OLD.joined_at
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.expires_at IS DISTINCT FROM OLD.expires_at
       OR NEW.horse_wait_seconds IS DISTINCT FROM OLD.horse_wait_seconds
       OR NEW.horse_eligible_at IS DISTINCT FROM OLD.horse_eligible_at THEN
        RAISE EXCEPTION 'pvp v2 ticket identity and horse deadline are immutable';
    END IF;

    IF OLD.status <> 'waiting' THEN
        IF ROW(NEW.*) IS DISTINCT FROM ROW(OLD.*) THEN
            RAISE EXCEPTION 'terminal pvp v2 ticket is immutable';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.heartbeat_at < OLD.heartbeat_at
       OR NEW.lease_expires_at < OLD.lease_expires_at
       OR NEW.updated_at < OLD.updated_at THEN
        RAISE EXCEPTION 'pvp v2 presence cannot move backwards';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.trivia_pvp_queue_v2_guard() OWNER TO postgres;

--
-- TOC entry 6494 (class 1255 OID 107936437)
-- Name: trivia_pvp_quote_v2(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp_quote_v2(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_rules jsonb;
    v_rule_body jsonb;
    v_balance bigint;
    v_stakes jsonb;
BEGIN
    IF p_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_request');
    END IF;

    SELECT COALESCE(p.diamonds, 0)::bigint
      INTO v_balance
      FROM public.profiles AS p
     WHERE p.id = p_user_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'profile_not_found');
    END IF;

    v_rules := public.trivia_rules_current('pvp.standard');
    v_rule_body := v_rules -> 'rules';
    IF v_rules ->> 'id' IS NULL
       OR jsonb_typeof(v_rule_body -> 'stakes') IS DISTINCT FROM 'array' THEN
        RETURN jsonb_build_object('success', false, 'error', 'rules_unavailable');
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'stake', x.stake,
               'pot', (m.money ->> 'pot')::integer,
               'rake', (m.money ->> 'rake')::integer,
               'possibleReturn', (m.money ->> 'winner_payout')::integer,
               'netWin', (m.money ->> 'winner_payout')::integer - x.stake
           ) ORDER BY x.stake), '[]'::jsonb)
      INTO v_stakes
      FROM (
          SELECT value::integer AS stake
            FROM jsonb_array_elements_text(v_rule_body -> 'stakes')
      ) AS x
      CROSS JOIN LATERAL (
          SELECT public.trivia_rules_pvp_money(v_rules ->> 'id', x.stake) AS money
      ) AS m;

    RETURN jsonb_build_object(
        'success', true,
        'engine', 'pvp-v2',
        'serverNow', clock_timestamp(),
        'balance', v_balance,
        'rulesVersion', v_rules ->> 'id',
        'stakes', v_stakes,
        'questionCount', COALESCE((v_rule_body -> 'questions' ->> 'count')::integer, 20),
        'humanFirst', COALESCE((v_rule_body -> 'horse' ->> 'human_first')::boolean, true),
        'horseWaitSeconds', jsonb_build_object(
            'min', COALESCE((v_rule_body -> 'horse' -> 'fallback_wait_seconds' ->> 'min')::integer, 20),
            'max', COALESCE((v_rule_body -> 'horse' -> 'fallback_wait_seconds' ->> 'max')::integer, 45)),
        'horseLabel', COALESCE(v_rule_body -> 'horse' ->> 'disclosure', 'Smarter Horse'),
        'cancellation', 'search_only_before_match',
        'tie', 'stake_refund'
    );
END;
$$;


