--
-- TOC entry 5528 (class 1255 OID 78786014)
-- Name: trivia_pvp_validate_session_link_v2(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_pvp_validate_session_link_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_m public.trivia_pvp_matches%ROWTYPE;
    v_s public.trivia_sessions%ROWTYPE;
    v_p public.trivia_settlement_participants%ROWTYPE;
    v_is_horse boolean;
BEGIN
    SELECT * INTO v_m FROM public.trivia_pvp_matches WHERE id = NEW.match_id;
    IF v_m.id IS NULL OR v_m.engine_version IS DISTINCT FROM NEW.engine_version THEN
        RAISE EXCEPTION 'pvp v2 link: match engine mismatch';
    END IF;
    IF current_setting('trivia_pvp.v2_authority', true) IS DISTINCT FROM NEW.match_id::text THEN
        RAISE EXCEPTION 'pvp v2 link: engine authority required';
    END IF;
    IF v_m.status IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION 'pvp v2 link: match state mismatch';
    END IF;
    IF (NEW.side = 1 AND NEW.user_id IS DISTINCT FROM v_m.player1_id)
       OR (NEW.side = 2 AND NEW.user_id IS DISTINCT FROM v_m.player2_id) THEN
        RAISE EXCEPTION 'pvp v2 link: participant mismatch';
    END IF;
    v_is_horse := v_m.horse_side IS NOT DISTINCT FROM NEW.side;
    SELECT * INTO v_s FROM public.trivia_sessions WHERE id = NEW.session_id;
    IF v_s.id IS NULL
       OR v_s.user_id IS DISTINCT FROM NEW.user_id
       OR v_s.mode IS DISTINCT FROM 'pvp'
       OR v_s.status IS DISTINCT FROM 'open'
       OR v_s.engine_version IS DISTINCT FROM 'trivia-engine/3'
       OR v_s.roster_snapshot_id IS DISTINCT FROM v_m.roster_snapshot_id
       OR v_s.roster_round_no IS DISTINCT FROM 1
       OR v_s.seat_key IS DISTINCT FROM ('pvp:' || NEW.match_id::text || ':' || NEW.side::text)
       OR v_s.actor_type IS DISTINCT FROM (CASE WHEN v_is_horse THEN 'horse' ELSE 'human' END)
       OR v_s.entry_state IS DISTINCT FROM 'charged'
       OR v_s.entry_cost IS DISTINCT FROM v_m.stake_amount
       OR v_s.expires_at IS DISTINCT FROM v_m.deadline_at
       OR to_jsonb(v_s.question_ids) IS DISTINCT FROM v_m.questions THEN
        RAISE EXCEPTION 'pvp v2 link: seat session binding mismatch';
    END IF;
    SELECT p.* INTO v_p
      FROM public.trivia_settlement_participants AS p
      JOIN public.trivia_settlements AS st ON st.id = p.settlement_id
     WHERE st.subject_type = 'pvp_match' AND st.subject_id = NEW.match_id AND p.user_id = NEW.user_id;
    IF v_p.settlement_id IS NULL
       OR v_p.state IS DISTINCT FROM 'held'
       OR v_p.entry_amount IS DISTINCT FROM v_m.stake_amount::bigint
       OR v_p.participant_kind IS DISTINCT FROM (CASE WHEN v_is_horse THEN 'horse' ELSE 'human' END)
       OR v_p.funding_source IS DISTINCT FROM (CASE WHEN v_is_horse THEN 'treasury' ELSE 'player_wallet' END) THEN
        RAISE EXCEPTION 'pvp v2 link: escrow participant mismatch';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.trivia_pvp_validate_session_link_v2() OWNER TO postgres;

--
-- TOC entry 5064 (class 1255 OID 74713925)
-- Name: trivia_quarantine_guard_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_quarantine_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF TG_OP <> 'UPDATE' THEN
        RAISE EXCEPTION 'trivia_question_quarantine records are never deleted' USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.released_at IS NOT NULL OR NEW.released_at IS NULL
       OR (to_jsonb(NEW) - ARRAY['released_at','released_by','release_note'])
          IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['released_at','released_by','release_note']) THEN
        RAISE EXCEPTION 'a quarantine record can only be released once' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION public.trivia_quarantine_guard_v1() OWNER TO postgres;

--
-- TOC entry 5278 (class 1255 OID 74719977)
-- Name: trivia_quarantine_question_v1(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_quarantine_question_v1(p_question_id uuid, p_reason_code text, p_source text, p_actor text, p_detail jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE v_id uuid;
BEGIN
    IF p_question_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.trivia_questions WHERE id = p_question_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'question_not_found');
    END IF;
    IF p_reason_code IS NULL OR p_reason_code !~ '^[a-z0-9_]{3,64}$' OR btrim(coalesce(p_actor, '')) = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
    END IF;
    INSERT INTO public.trivia_question_quarantine (question_id, reason_code, source, detail, created_by)
    VALUES (p_question_id, p_reason_code, p_source, coalesce(p_detail, '{}'::jsonb), p_actor)
    ON CONFLICT (question_id, reason_code) WHERE released_at IS NULL DO NOTHING
    RETURNING id INTO v_id;
    IF v_id IS NULL THEN
        SELECT id INTO v_id FROM public.trivia_question_quarantine
         WHERE question_id = p_question_id AND reason_code = p_reason_code AND released_at IS NULL;
        RETURN jsonb_build_object('success', true, 'duplicate', true, 'quarantine_id', v_id);
    END IF;
    RETURN jsonb_build_object('success', true, 'duplicate', false, 'quarantine_id', v_id);
END $_$;


ALTER FUNCTION public.trivia_quarantine_question_v1(p_question_id uuid, p_reason_code text, p_source text, p_actor text, p_detail jsonb) OWNER TO postgres;

--
-- TOC entry 9384 (class 1255 OID 74713813)
-- Name: trivia_question_content_hash_v1(text, jsonb, integer, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_question_content_hash_v1(p_question text, p_options jsonb, p_correct_index integer, p_explanation text, p_category text, p_subcategory text, p_difficulty text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
    SELECT encode(extensions.digest(jsonb_build_object(
        'v', 'trivia-question/1', 'q', p_question, 'o', p_options, 'k', p_correct_index,
        'e', coalesce(p_explanation, ''), 'c', p_category, 's', coalesce(p_subcategory, ''),
        'd', p_difficulty)::text, 'sha256'), 'hex')
$$;


ALTER FUNCTION public.trivia_question_content_hash_v1(p_question text, p_options jsonb, p_correct_index integer, p_explanation text, p_category text, p_subcategory text, p_difficulty text) OWNER TO postgres;

--
-- TOC entry 4329 (class 1255 OID 74744064)
-- Name: trivia_question_health_v1(boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_question_health_v1(p_record boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    m jsonb; c jsonb := '[]'::jsonb; v_cap256 jsonb; v_cap512 jsonb; v_thin jsonb; v_pool integer; v_by_mode jsonb;
    v_queue integer; v_last_review timestamptz; v_rep_open integer; v_rep_invalid integer; v_rep_oldest numeric;
    v_stale integer; v_held integer; v_nostats integer; v_exp24 integer; v_items integer; v_tier2 integer;
    v_voids integer; v_integrity integer; v_events jsonb := '[]'::jsonb; r record; v_now timestamptz := now();
    v_run uuid;
BEGIN
    v_cap256 := public.trivia_tournament_capacity_v1(256);
    v_cap512 := public.trivia_tournament_capacity_v1(512);
    -- The eligible pool is read once; the count, the thin-profile check and the per-mode
    -- supply are all taken from that one pass.
    WITH pool AS MATERIALIZED (SELECT e.category, e.modes, e.min_timer_seconds FROM public.trivia_eligible_question_pool_v1 e)
    SELECT (SELECT count(*) FROM pool),
           (SELECT coalesce(jsonb_object_agg(p.profile_id, e.n), '{}'::jsonb) FROM public.trivia_roster_profiles p
              CROSS JOIN LATERAL (SELECT count(*) n FROM pool x
                                   WHERE p.mode = ANY (x.modes) AND x.category = ANY (p.categories)
                                     AND (p.per_question_seconds IS NULL OR x.min_timer_seconds <= p.per_question_seconds)) e
             WHERE p.mode NOT IN ('pvp','tournaments') AND e.n < p.question_count * 30),
           (SELECT jsonb_object_agg(z.mode, z.n) FROM (SELECT u.mode, count(*) n FROM pool p, unnest(p.modes) u(mode) GROUP BY 1) z)
      INTO v_pool, v_thin, v_by_mode;
    SELECT count(*) INTO v_queue FROM public.trivia_review_queue_v1;
    SELECT greatest((SELECT max(reviewed_at) FROM public.trivia_question_reviews),
                    (SELECT max(last_audited_at) FROM public.trivia_questions)) INTO v_last_review;
    SELECT count(*) FILTER (WHERE valid), count(*) FILTER (WHERE NOT valid),
           max(extract(epoch FROM (v_now - created_at)) / 3600) FILTER (WHERE valid)
      INTO v_rep_open, v_rep_invalid, v_rep_oldest FROM public.trivia_question_reports WHERE state IN ('open','triaged');
    SELECT count(*) FILTER (WHERE NOT public.trivia_p3_session_is_held_evidence(id)),
           count(*) FILTER (WHERE public.trivia_p3_session_is_held_evidence(id))
      INTO v_stale, v_held FROM public.trivia_sessions
     WHERE status = 'open' AND ((expires_at IS NOT NULL AND expires_at < v_now)
            OR (expires_at IS NULL AND created_at < v_now - interval '6 hours'));
    SELECT count(*) INTO v_nostats FROM public.trivia_sessions
     WHERE status = 'submitted' AND stats_recorded_at IS NULL AND NOT public.trivia_p3_session_is_held_evidence(id);
    SELECT count(*) INTO v_exp24 FROM public.trivia_session_reconciliations WHERE action = 'expired' AND created_at > v_now - interval '24 hours';
    SELECT count(*), count(*) FILTER (WHERE i.selection_tier = 2) INTO v_items, v_tier2
      FROM public.trivia_roster_snapshot_items i JOIN public.trivia_roster_snapshots s ON s.id = i.snapshot_id
     WHERE s.scope_kind IN ('solo_session','pvp_match') AND s.created_at > v_now - interval '7 days';
    SELECT coalesce(sum(voided), 0) INTO v_voids FROM public.trivia_session_results WHERE created_at > v_now - interval '24 hours';
    -- The revision hash is computed inline: the same expression trivia_question_content_hash_v1
    -- wraps (its pinned search_path keeps it from being inlined, which made this check 1.5 s).
    SELECT count(*) INTO v_integrity FROM public.trivia_question_curation cu
      JOIN public.trivia_question_revisions rv ON rv.id = cu.current_revision_id
      JOIN public.trivia_questions q ON q.id = cu.question_id
     WHERE rv.content_hash <> encode(extensions.digest(jsonb_build_object(
               'v', 'trivia-question/1', 'q', q.question, 'o', q.options, 'k', q.correct_index,
               'e', coalesce(q.explanation, ''), 'c', q.category, 's', coalesce(q.subcategory, ''),
               'd', q.difficulty)::text, 'sha256'), 'hex');
    m := jsonb_build_object('eligible_pool', v_pool,
        'pool_by_mode', v_by_mode,
        'rejection_reasons', (SELECT jsonb_object_agg(reason, n) FROM (SELECT u.reason, count(*) n FROM public.trivia_question_eligibility_v1 e,
                         unnest(e.reject_reasons) u(reason) GROUP BY 1) z),
        'tournament_256', v_cap256, 'tournament_512', v_cap512, 'thin_profiles', v_thin,
        'review_queue', v_queue, 'last_review_at', v_last_review,
        'reports_open_valid', v_rep_open, 'reports_open_invalid', v_rep_invalid, 'reports_oldest_valid_hours', round(coalesce(v_rep_oldest, 0), 1),
        'sessions_stale_open', v_stale, 'sessions_held_evidence', v_held, 'sessions_expired_24h', v_exp24,
        'submitted_without_stats', v_nostats, 'roster_items_7d', v_items,
        'repeat_rate_7d', CASE WHEN v_items > 0 THEN round(v_tier2::numeric / v_items, 4) ELSE 0 END,
        'invalid_question_voids_24h', v_voids, 'revision_integrity_mismatches', v_integrity);
    IF (v_cap256 ->> 'supports')::boolean IS NOT TRUE THEN
        c := c || jsonb_build_array(jsonb_build_object('alertname', 'TriviaEligiblePoolBelowNightlyBracket', 'severity', 'critical',
            'summary', format('eligible tournament pool %s < %s questions required for a 256-player bracket',
                               v_cap256 ->> 'eligible_available', v_cap256 ->> 'required')));
    END IF;
    IF v_thin <> '{}'::jsonb THEN
        c := c || jsonb_build_array(jsonb_build_object('alertname', 'TriviaEligiblePoolThin', 'severity', 'warning',
            'summary', 'eligible supply under 30 rosters for: ' || (SELECT string_agg(k, ', ') FROM jsonb_object_keys(v_thin) k)));
    END IF;
    IF v_nostats > 0 THEN
        c := c || jsonb_build_array(jsonb_build_object('alertname', 'TriviaSubmittedWithoutStats', 'severity', 'warning',
            'summary', format('%s submitted sessions have no recorded stats', v_nostats)));
    END IF;
    IF v_stale > 0 THEN
        c := c || jsonb_build_array(jsonb_build_object('alertname', 'TriviaStaleOpenSessions', 'severity', 'warning',
            'summary', format('%s open sessions are past their deadline', v_stale)));
    END IF;
    IF coalesce(v_rep_oldest, 0) > 72 THEN
        c := c || jsonb_build_array(jsonb_build_object('alertname', 'TriviaQuestionReportBacklog', 'severity', 'warning',
            'summary', format('%s valid question reports open; oldest %s h', v_rep_open, round(v_rep_oldest))));
    END IF;
    IF v_queue > 0 AND (v_last_review IS NULL OR v_last_review < v_now - interval '48 hours') THEN
        c := c || jsonb_build_array(jsonb_build_object('alertname', 'TriviaReviewQueueStalled', 'severity', 'warning',
            'summary', format('%s questions await review; no review recorded in 48 h', v_queue)));
    END IF;
    IF v_integrity > 0 THEN
        c := c || jsonb_build_array(jsonb_build_object('alertname', 'TriviaRevisionIntegrity', 'severity', 'critical',
            'summary', format('%s questions differ from their captured revision', v_integrity)));
    END IF;
    IF v_voids > 0 THEN
        c := c || jsonb_build_array(jsonb_build_object('alertname', 'TriviaInvalidQuestionVoids', 'severity', 'warning',
            'summary', format('%s served questions were voided in 24 h', v_voids)));
    END IF;
    IF v_items >= 20 AND v_tier2::numeric / v_items > 0.2 THEN
        c := c || jsonb_build_array(jsonb_build_object('alertname', 'TriviaRosterRepeatRateHigh', 'severity', 'warning',
            'summary', format('%s%% of roster items in 7 days repeated a player''s recent question', round(100.0 * v_tier2 / v_items))));
    END IF;
    IF NOT coalesce(p_record, false) THEN
        RETURN jsonb_build_object('success', true, 'healthy', jsonb_array_length(c) = 0, 'metrics', m, 'conditions', c, 'events', '[]'::jsonb);
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('trivia_question_health_v1', 0));
    -- close episodes whose condition is gone; keep re-sending undelivered recoveries
    FOR r IN SELECT * FROM public.trivia_ops_alert_state s
              WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(c) x WHERE x ->> 'alertname' = s.alertname)
                AND (s.resolved_at IS NULL OR NOT s.resolution_delivered) LOOP
        UPDATE public.trivia_ops_alert_state SET resolved_at = coalesce(resolved_at, v_now) WHERE alertname = r.alertname;
        v_events := v_events || jsonb_build_array(jsonb_build_object('alertname', r.alertname, 'status', 'resolved',
            'severity', r.severity, 'event_key', r.episode_key || ':resolved', 'resolves', r.episode_key,
            'summary', 'recovered: ' || coalesce(r.last_summary, r.alertname), 'firing_since', r.firing_since));
    END LOOP;
    FOR r IN SELECT x ->> 'alertname' AS alertname, x ->> 'severity' AS severity, x ->> 'summary' AS summary
               FROM jsonb_array_elements(c) x LOOP
        INSERT INTO public.trivia_ops_alert_state AS s (alertname, severity, episode_key, firing_since, last_seen_at, last_summary)
        VALUES (r.alertname, r.severity, public.trivia_sha256_hex_v1('trivia-ops/1:' || r.alertname || ':' || v_now::text),
                v_now, v_now, r.summary)
        ON CONFLICT (alertname) DO UPDATE SET
            episode_key = CASE WHEN s.resolved_at IS NOT NULL THEN EXCLUDED.episode_key ELSE s.episode_key END,
            firing_since = CASE WHEN s.resolved_at IS NOT NULL THEN EXCLUDED.firing_since ELSE s.firing_since END,
            resolved_at = NULL, resolution_delivered = false, severity = EXCLUDED.severity,
            last_seen_at = EXCLUDED.last_seen_at, last_summary = EXCLUDED.last_summary;
        v_events := v_events || (SELECT jsonb_build_array(jsonb_build_object('alertname', s.alertname, 'status', 'firing',
            'severity', s.severity, 'event_key', s.episode_key, 'summary', s.last_summary, 'firing_since', s.firing_since))
            FROM public.trivia_ops_alert_state s WHERE s.alertname = r.alertname);
    END LOOP;
    INSERT INTO public.trivia_question_health_runs (healthy, metrics, conditions)
    VALUES (jsonb_array_length(c) = 0, m, c) RETURNING id INTO v_run;
    RETURN jsonb_build_object('success', true, 'run_id', v_run, 'healthy', jsonb_array_length(c) = 0, 'metrics', m,
        'conditions', c, 'events', v_events);
END $$;


ALTER FUNCTION public.trivia_question_health_v1(p_record boolean) OWNER TO postgres;

--
-- TOC entry 5390 (class 1255 OID 74744021)
-- Name: trivia_question_is_eligible_v1(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_question_is_eligible_v1(p_question_id uuid, p_mode text, p_profile_id text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM public.trivia_eligible_question_pool_v1 p
          LEFT JOIN public.trivia_roster_profiles r ON r.profile_id = p_profile_id
         WHERE p.question_id = p_question_id AND p_mode = ANY (p.modes)
           AND (p_profile_id IS NULL OR (r.profile_id IS NOT NULL AND r.mode = p_mode
                AND p.category = ANY (r.categories)
                AND (r.per_question_seconds IS NULL OR p.min_timer_seconds <= r.per_question_seconds))))
$$;


ALTER FUNCTION public.trivia_question_is_eligible_v1(p_question_id uuid, p_mode text, p_profile_id text) OWNER TO postgres;

--
-- TOC entry 9549 (class 1255 OID 74713811)
-- Name: trivia_question_structure_ok_v1(text, jsonb, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_question_structure_ok_v1(p_question text, p_options jsonb, p_correct_index integer, p_category text, p_difficulty text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
    SELECT CASE
        WHEN btrim(coalesce(p_question, '')) = '' THEN false
        WHEN p_options IS NULL OR jsonb_typeof(p_options) <> 'array' THEN false
        WHEN jsonb_array_length(p_options) NOT BETWEEN 2 AND 6 THEN false
        WHEN p_correct_index IS NULL OR p_correct_index < 0
             OR p_correct_index >= jsonb_array_length(p_options) THEN false
        WHEN p_category IS NULL OR p_category <> ALL (ARRAY['poker_history','famous_hands','gto_theory',
             'player_profiles','tournament_facts','rule_knowledge','mtt_situations',
             'cash_game_situations','icm_chip_ev','gto_scenarios']) THEN false
        WHEN p_difficulty IS NULL OR p_difficulty <> ALL (ARRAY['easy','medium','hard']) THEN false
        WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(p_options) e
                      WHERE jsonb_typeof(e) <> 'string' OR btrim(e #>> '{}') = '') THEN false
        ELSE (SELECT count(DISTINCT lower(regexp_replace(btrim(e #>> '{}'), '\s+', ' ', 'g')))
                FROM jsonb_array_elements(p_options) e) = jsonb_array_length(p_options)
    END
$$;


ALTER FUNCTION public.trivia_question_structure_ok_v1(p_question text, p_options jsonb, p_correct_index integer, p_category text, p_difficulty text) OWNER TO postgres;

--
-- TOC entry 3429 (class 1255 OID 74713803)
-- Name: trivia_reading_words_v1(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_reading_words_v1(p_question text, p_options jsonb) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
    SELECT (CASE WHEN btrim(coalesce(p_question, '')) = '' THEN 0
                 ELSE coalesce(array_length(regexp_split_to_array(btrim(p_question), '\s+'), 1), 0) END)
         + coalesce((SELECT sum(CASE WHEN btrim(e #>> '{}') = '' THEN 0
                                     ELSE array_length(regexp_split_to_array(btrim(e #>> '{}'), '\s+'), 1) END)::int
                       FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_options) = 'array'
                                                      THEN p_options ELSE '[]'::jsonb END) e), 0)
$$;


ALTER FUNCTION public.trivia_reading_words_v1(p_question text, p_options jsonb) OWNER TO postgres;

--
-- TOC entry 4306 (class 1255 OID 110226010)
-- Name: trivia_record_invalid_question_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_record_invalid_question_v1(p_session_id uuid, p_user_id uuid, p_question_id uuid, p_client_nonce uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    s public.trivia_sessions%ROWTYPE;
    a public.trivia_session_answers%ROWTYPE;
    r public.trivia_question_revisions%ROWTYPE;
    v_profile public.trivia_roster_profiles%ROWTYPE;
    v_now timestamptz := clock_timestamp();
    v_audit boolean;
    v_structural boolean;
    v_quarantined boolean;
    v_reason text;
    v_seq integer;
    v_key text := p_question_id::text;
    v_stored jsonb;
    v_revision_id uuid;
    v_position integer;
    v_at timestamptz;
BEGIN
    IF p_session_id IS NULL OR p_user_id IS NULL OR p_question_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
    END IF;
    SELECT * INTO s FROM public.trivia_sessions WHERE id = p_session_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'session_not_found'); END IF;
    IF s.user_id IS DISTINCT FROM p_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_your_session');
    END IF;

    IF s.engine_version IS NOT NULL THEN
        SELECT * INTO a FROM public.trivia_session_answers
         WHERE session_id = p_session_id AND question_id = p_question_id FOR UPDATE;
        IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'question_not_in_session'); END IF;
        IF a.position < 1 OR a.position > coalesce(cardinality(s.question_ids), 0)
           OR s.question_ids[a.position] IS DISTINCT FROM a.question_id THEN
            RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
        END IF;
        IF a.server_voided_at IS NOT NULL THEN
            RETURN jsonb_build_object('success', true, 'recorded', true, 'duplicate', true,
                'storedDisplayIndex', -1, 'outcome', 'voided', 'voided', true);
        END IF;
        IF a.outcome IS NOT NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'answer_already_recorded');
        END IF;
        IF s.status <> 'open' THEN RETURN jsonb_build_object('success', false, 'error', 'session_closed'); END IF;
        IF s.expires_at IS NULL OR v_now > s.expires_at THEN
            RETURN jsonb_build_object('success', false, 'error', 'session_expired');
        END IF;
        SELECT * INTO v_profile FROM public.trivia_roster_profiles WHERE profile_id = s.roster_profile_id;
        IF v_profile.per_question_seconds IS NOT NULL AND a.opened_at IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'question_not_open');
        END IF;
        SELECT * INTO r FROM public.trivia_question_revisions
         WHERE id = a.revision_id AND question_id = a.question_id;
        IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'question_validation_failed'); END IF;
        SELECT q.audit_verified INTO v_audit FROM public.trivia_questions q
         WHERE q.id = a.question_id FOR UPDATE;
        IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'question_validation_failed'); END IF;
        PERFORM 1 FROM public.trivia_question_quarantine z
         WHERE z.question_id = a.question_id AND z.released_at IS NULL FOR UPDATE;
        v_quarantined := FOUND;
        v_reason := CASE
            WHEN r.structurally_valid IS FALSE THEN 'structural'
            WHEN v_audit IS FALSE THEN 'audit'
            WHEN v_quarantined THEN 'quarantine'
            ELSE NULL
        END;
        IF v_reason IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'question_still_valid');
        END IF;
        SELECT count(*) + 1 INTO v_seq FROM public.trivia_session_answers
         WHERE session_id = p_session_id AND sequence IS NOT NULL;
        UPDATE public.trivia_session_answers
           SET answered_at = v_now, display_index = -1, original_index = NULL,
               is_correct = false, outcome = 'skip', sequence = v_seq,
               client_nonce = p_client_nonce, server_voided_at = v_now,
               server_void_reason = v_reason
         WHERE session_id = p_session_id AND position = a.position;
        RETURN jsonb_build_object('success', true, 'recorded', true, 'duplicate', false,
            'storedDisplayIndex', -1, 'outcome', 'voided', 'voided', true);
    END IF;

    IF jsonb_typeof(s.answers) IS DISTINCT FROM 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
    END IF;
    v_position := array_position(coalesce(s.question_ids, '{}'::uuid[]), p_question_id);
    IF v_position IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'question_not_in_session');
    END IF;
    v_stored := coalesce(s.answers, '{}'::jsonb) -> v_key;
    IF v_stored -> 'v' = 'true'::jsonb THEN
        IF jsonb_typeof(v_stored) IS DISTINCT FROM 'object' THEN
            RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
        END IF;
        IF (SELECT count(*) FROM jsonb_object_keys(v_stored)) <> 5
           OR NOT (v_stored ?& ARRAY['d','n','at','v','vr'])
           OR v_stored -> 'v' IS DISTINCT FROM 'true'::jsonb
           OR v_stored ->> 'd' IS DISTINCT FROM '-1'
           OR jsonb_typeof(v_stored -> 'n') IS DISTINCT FROM 'number'
           OR coalesce(v_stored ->> 'n', '') !~ '^[0-9]+$'
           OR (v_stored ->> 'n')::integer <> v_position - 1
           OR jsonb_typeof(v_stored -> 'at') IS DISTINCT FROM 'string'
           OR coalesce(v_stored ->> 'vr', '') NOT IN ('structural','audit','quarantine') THEN
            RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
        END IF;
        BEGIN
            v_at := (v_stored ->> 'at')::timestamptz;
        EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
            RETURN jsonb_build_object('success', false, 'error', 'answer_record_invalid');
        END;
        RETURN jsonb_build_object('success', true, 'recorded', true, 'duplicate', true,
            'storedDisplayIndex', -1, 'outcome', 'voided', 'voided', true);
    END IF;
    IF v_stored IS NOT NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'answer_already_recorded');
    END IF;
    IF s.status <> 'open' THEN RETURN jsonb_build_object('success', false, 'error', 'session_closed'); END IF;
    IF s.expires_at IS NOT NULL AND v_now > s.expires_at THEN
        RETURN jsonb_build_object('success', false, 'error', 'session_expired');
    END IF;
    BEGIN
        v_revision_id := (s.question_revision_ids ->> v_key)::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
        v_revision_id := NULL;
    END;
    IF v_revision_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
    END IF;
    SELECT rev.structurally_valid, q.audit_verified
      INTO v_structural, v_audit
      FROM public.trivia_question_revisions rev
      JOIN public.trivia_questions q ON q.id = rev.question_id
     WHERE rev.id = v_revision_id AND rev.question_id = p_question_id
     FOR UPDATE OF q;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'question_validation_failed'); END IF;
    PERFORM 1 FROM public.trivia_question_quarantine z
     WHERE z.question_id = p_question_id AND z.released_at IS NULL FOR UPDATE;
    v_quarantined := FOUND;
    v_reason := CASE
        WHEN v_structural IS FALSE THEN 'structural'
        WHEN v_audit IS FALSE THEN 'audit'
        WHEN v_quarantined THEN 'quarantine'
        ELSE NULL
    END;
    IF v_reason IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'question_still_valid');
    END IF;
    UPDATE public.trivia_sessions
       SET answers = coalesce(answers, '{}'::jsonb) || jsonb_build_object(v_key,
           jsonb_build_object('d', -1, 'n', v_position - 1,
                              'at', v_now, 'v', true, 'vr', v_reason))
     WHERE id = p_session_id;
    RETURN jsonb_build_object('success', true, 'recorded', true, 'duplicate', false,
        'storedDisplayIndex', -1, 'outcome', 'voided', 'voided', true);
END $_$;


ALTER FUNCTION public.trivia_record_invalid_question_v1(p_session_id uuid, p_user_id uuid, p_question_id uuid, p_client_nonce uuid) OWNER TO postgres;

--
-- TOC entry 6592 (class 1255 OID 74719980)
-- Name: trivia_record_question_review_v1(uuid, uuid, uuid, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_record_question_review_v1(p_batch_id uuid, p_question_id uuid, p_revision_id uuid, p_reviewer text, p_reviewer_kind text, p_model text, p_model_version text, p_prompt_version text, p_evidence jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
    v_existing public.trivia_question_reviews%ROWTYPE;
    v_rev public.trivia_question_revisions%ROWTYPE;
    v_current uuid;
    v_verdict text;
    v_conf numeric;
    v_a0 integer; v_a1 integer; v_c0 numeric; v_c1 numeric;
    v_applied boolean := false;
    v_effect text := 'none';
    v_inconclusive integer;
    v_review_id uuid;
    v_q public.trivia_questions%ROWTYPE;
BEGIN
    IF p_question_id IS NULL OR p_revision_id IS NULL OR btrim(coalesce(p_reviewer, '')) = ''
       OR p_reviewer_kind NOT IN ('model','human','system') OR p_evidence IS NULL
       OR p_prompt_version NOT IN ('cold-answer/1','human/1') THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
    END IF;
    IF p_batch_id IS NOT NULL THEN
        SELECT * INTO v_existing FROM public.trivia_question_reviews
         WHERE batch_id = p_batch_id AND question_id = p_question_id;
        IF FOUND THEN
            RETURN jsonb_build_object('success', true, 'duplicate', true, 'review_id', v_existing.id,
                'verdict', v_existing.verdict, 'applied', v_existing.applied, 'effect', v_existing.applied_effect);
        END IF;
        IF NOT EXISTS (SELECT 1 FROM public.trivia_review_batch_items
                        WHERE batch_id = p_batch_id AND question_id = p_question_id AND revision_id = p_revision_id) THEN
            RETURN jsonb_build_object('success', false, 'error', 'not_in_batch');
        END IF;
    END IF;
    SELECT * INTO v_rev FROM public.trivia_question_revisions WHERE id = p_revision_id AND question_id = p_question_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'revision_not_found'); END IF;
    SELECT * INTO v_q FROM public.trivia_questions WHERE id = p_question_id FOR UPDATE;
    SELECT current_revision_id INTO v_current FROM public.trivia_question_curation WHERE question_id = p_question_id;

    IF NOT v_rev.structurally_valid THEN
        v_verdict := 'invalid_structure';
    ELSIF p_prompt_version = 'human/1' THEN
        v_verdict := CASE WHEN p_evidence ->> 'verdict' IN ('verified','failed') THEN p_evidence ->> 'verdict' ELSE 'inconclusive' END;
    ELSE
        IF jsonb_typeof(p_evidence -> 'answers') = 'array' AND jsonb_array_length(p_evidence -> 'answers') = 2
           AND (p_evidence -> 'answers' -> 0 ->> 'index') ~ '^[0-9]+$' AND (p_evidence -> 'answers' -> 1 ->> 'index') ~ '^[0-9]+$' THEN
            v_a0 := (p_evidence -> 'answers' -> 0 ->> 'index')::int;
            v_a1 := (p_evidence -> 'answers' -> 1 ->> 'index')::int;
            v_c0 := CASE WHEN (p_evidence -> 'answers' -> 0 ->> 'confidence') ~ '^[0-9.]+$'
                         THEN least(1, (p_evidence -> 'answers' -> 0 ->> 'confidence')::numeric) END;
            v_c1 := CASE WHEN (p_evidence -> 'answers' -> 1 ->> 'confidence') ~ '^[0-9.]+$'
                         THEN least(1, (p_evidence -> 'answers' -> 1 ->> 'confidence')::numeric) END;
            v_conf := least(v_c0, v_c1);
            IF v_a0 = v_rev.correct_index AND v_a1 = v_rev.correct_index THEN
                v_verdict := 'verified';
            ELSIF v_a0 = v_a1 AND coalesce(v_c0, 0) >= 0.6 AND coalesce(v_c1, 0) >= 0.6 THEN
                v_verdict := 'failed';
            ELSE
                v_verdict := 'inconclusive';
            END IF;
        ELSE
            v_verdict := 'inconclusive';
        END IF;
    END IF;

    IF p_revision_id IS NOT DISTINCT FROM v_current THEN
        IF v_verdict = 'verified' THEN
            UPDATE public.trivia_questions
               SET audit_verified = true, last_audited_at = now(),
                   audit_confidence = coalesce(v_conf, audit_confidence)
             WHERE id = p_question_id;
            v_applied := true; v_effect := 'verified';
        ELSIF v_verdict = 'failed' THEN
            UPDATE public.trivia_questions
               SET audit_verified = false, last_audited_at = now(),
                   quality_score = least(coalesce(quality_score, 4), 4), daily_date = NULL
             WHERE id = p_question_id;
            v_applied := true; v_effect := 'failed_demoted';
        ELSIF v_verdict = 'invalid_structure' THEN
            UPDATE public.trivia_questions
               SET last_audited_at = now(), quality_score = least(coalesce(quality_score, 4), 4), daily_date = NULL
             WHERE id = p_question_id;
            PERFORM public.trivia_quarantine_question_v1(p_question_id, 'invalid_structure', 'structural',
                p_reviewer, jsonb_build_object('revision_id', p_revision_id));
            v_applied := true; v_effect := 'quarantined_structure';
        ELSE
            SELECT count(*) INTO v_inconclusive FROM public.trivia_question_reviews
             WHERE revision_id = p_revision_id AND verdict = 'inconclusive';
            IF v_inconclusive + 1 >= 3 THEN
                UPDATE public.trivia_questions
                   SET last_audited_at = now(), quality_score = least(coalesce(quality_score, 4), 4), daily_date = NULL
                 WHERE id = p_question_id;
                v_applied := true; v_effect := 'inconclusive_limit_demoted';
            ELSE
                v_effect := 'inconclusive_retry';
            END IF;
        END IF;
    ELSE
        v_effect := 'stale_revision_not_applied';
    END IF;

    INSERT INTO public.trivia_question_reviews (question_id, revision_id, batch_id, reviewer, reviewer_kind,
        model, model_version, prompt_version, verdict, confidence, evidence, applied, applied_effect)
    VALUES (p_question_id, p_revision_id, p_batch_id, p_reviewer, p_reviewer_kind, p_model, p_model_version,
        p_prompt_version, v_verdict, v_conf, p_evidence, v_applied, v_effect)
    RETURNING id INTO v_review_id;
    UPDATE public.trivia_question_curation SET last_reviewed_at = now(), last_review_id = v_review_id, updated_at = now()
     WHERE question_id = p_question_id;
    IF p_batch_id IS NOT NULL THEN
        UPDATE public.trivia_review_batch_items SET review_id = v_review_id
         WHERE batch_id = p_batch_id AND question_id = p_question_id;
        UPDATE public.trivia_review_batches SET status = 'completed', completed_at = now()
         WHERE id = p_batch_id AND status IN ('claimed','expired')
           AND NOT EXISTS (SELECT 1 FROM public.trivia_review_batch_items WHERE batch_id = p_batch_id AND review_id IS NULL);
    END IF;
    RETURN jsonb_build_object('success', true, 'duplicate', false, 'review_id', v_review_id,
        'verdict', v_verdict, 'applied', v_applied, 'effect', v_effect);
END $_$;


ALTER FUNCTION public.trivia_record_question_review_v1(p_batch_id uuid, p_question_id uuid, p_revision_id uuid, p_reviewer text, p_reviewer_kind text, p_model text, p_model_version text, p_prompt_version text, p_evidence jsonb) OWNER TO postgres;

--
-- TOC entry 8443 (class 1255 OID 110225982)
-- Name: trivia_release_gto_render_v1(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_release_gto_render_v1(p_cache_digest text, p_owner_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $_$
BEGIN
    IF p_cache_digest IS NULL OR p_cache_digest !~ '^[0-9a-f]{64}$' OR p_owner_token IS NULL THEN
        RETURN false;
    END IF;
    DELETE FROM public.trivia_gto_render_claims
     WHERE cache_digest = p_cache_digest AND owner_token = p_owner_token;
    RETURN FOUND;
END $_$;


ALTER FUNCTION public.trivia_release_gto_render_v1(p_cache_digest text, p_owner_token uuid) OWNER TO postgres;

--
-- TOC entry 7118 (class 1255 OID 74719978)
-- Name: trivia_release_question_quarantine_v1(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_release_question_quarantine_v1(p_quarantine_id uuid, p_actor text, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_row public.trivia_question_quarantine%ROWTYPE;
BEGIN
    IF btrim(coalesce(p_actor, '')) = '' OR btrim(coalesce(p_note, '')) = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'actor_and_note_required');
    END IF;
    SELECT * INTO v_row FROM public.trivia_question_quarantine WHERE id = p_quarantine_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'quarantine_not_found'); END IF;
    IF v_row.released_at IS NOT NULL THEN
        RETURN jsonb_build_object('success', true, 'duplicate', true, 'released_at', v_row.released_at);
    END IF;
    UPDATE public.trivia_question_quarantine
       SET released_at = now(), released_by = p_actor, release_note = p_note
     WHERE id = p_quarantine_id;
    RETURN jsonb_build_object('success', true, 'duplicate', false, 'quarantine_id', p_quarantine_id);
END $$;


ALTER FUNCTION public.trivia_release_question_quarantine_v1(p_quarantine_id uuid, p_actor text, p_note text) OWNER TO postgres;

--
-- TOC entry 5939 (class 1255 OID 74744031)
-- Name: trivia_roster_manifest_v1(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_roster_manifest_v1(p_snapshot_id uuid, p_round_no integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
    SELECT CASE WHEN s.id IS NULL THEN jsonb_build_object('success', false, 'error', 'snapshot_not_found')
    ELSE jsonb_build_object('success', true, 'snapshot_id', s.id, 'scope_kind', s.scope_kind, 'scope_id', s.scope_id,
        'profile_id', s.profile_id, 'roster_hash', s.roster_hash, 'rounds', (
            SELECT coalesce(jsonb_agg(jsonb_build_object('round_no', r.round_no, 'items', r.items) ORDER BY r.round_no), '[]'::jsonb)
              FROM (SELECT i.round_no, jsonb_agg(jsonb_build_object('position', i.position, 'question_id', i.question_id,
                          'revision_id', i.revision_id, 'category', i.category, 'difficulty', i.difficulty) ORDER BY i.position) AS items
                      FROM public.trivia_roster_snapshot_items i
                     WHERE i.snapshot_id = s.id AND (p_round_no IS NULL OR i.round_no = p_round_no)
                     GROUP BY i.round_no) r)) END
      FROM (SELECT p_snapshot_id AS want) w LEFT JOIN public.trivia_roster_snapshots s ON s.id = w.want
$$;


ALTER FUNCTION public.trivia_roster_manifest_v1(p_snapshot_id uuid, p_round_no integer) OWNER TO postgres;

