--
-- TOC entry 3633 (class 1255 OID 74431359)
-- Name: trivia_rules_snapshot_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_rules_snapshot_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_key text; v_id text; v record;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.rules_version_id IS DISTINCT FROM OLD.rules_version_id OR NEW.rules_sha256 IS DISTINCT FROM OLD.rules_sha256 THEN
      RAISE EXCEPTION 'trivia rules snapshot on % is immutable', TG_TABLE_NAME USING ERRCODE = 'TL002';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.rules_version_id IS NULL THEN
    IF TG_TABLE_NAME = 'trivia_sessions' THEN v_key := public.trivia_rules_key_for_mode(NEW.mode);
    ELSIF TG_TABLE_NAME = 'trivia_pvp_matches' THEN v_key := 'pvp.standard';
    ELSE
      NEW.rules_sha256 := NULL;
      RETURN NEW;
    END IF;
    SELECT c.rules_version_id INTO v_id FROM public.trivia_rules_current c WHERE c.rules_key = v_key;
    IF v_id IS NULL THEN
      NEW.rules_sha256 := NULL;
      RETURN NEW;
    END IF;
    NEW.rules_version_id := v_id;
  END IF;
  SELECT rv.rules_sha256, rv.family, rv.mode INTO v FROM public.trivia_rules_versions rv WHERE rv.id = NEW.rules_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'trivia rules snapshot % does not exist', NEW.rules_version_id USING ERRCODE = 'TL002';
  END IF;
  IF TG_TABLE_NAME = 'trivia_sessions' THEN
    IF v.mode IS DISTINCT FROM NEW.mode THEN
      RAISE EXCEPTION 'trivia rules snapshot % does not fit mode %', NEW.rules_version_id, NEW.mode USING ERRCODE = 'TL002';
    END IF;
  ELSIF TG_TABLE_NAME = 'trivia_pvp_matches' THEN
    IF v.family <> 'pvp' THEN
      RAISE EXCEPTION 'trivia rules snapshot % is not a PvP version', NEW.rules_version_id USING ERRCODE = 'TL002';
    END IF;
  ELSIF v.family <> 'tournament' THEN
    RAISE EXCEPTION 'trivia rules snapshot % is not a tournament version', NEW.rules_version_id USING ERRCODE = 'TL002';
  END IF;
  NEW.rules_sha256 := v.rules_sha256;
  RETURN NEW;
END $$;


ALTER FUNCTION public.trivia_rules_snapshot_guard() OWNER TO postgres;

--
-- TOC entry 3545 (class 1255 OID 74431295)
-- Name: trivia_rules_tournament_prizes(text, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_rules_tournament_prizes(p_rules_version_id text, p_prize_pool bigint, p_finishers jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_rules jsonb; t jsonb; v_members jsonb; v_each bigint; v_paid bigint := 0; v_out jsonb := '[]'::jsonb; v_total bigint;
BEGIN
  SELECT rules INTO v_rules FROM public.trivia_rules_versions WHERE id = p_rules_version_id AND family = 'tournament';
  IF v_rules IS NULL THEN RETURN jsonb_build_object('error', 'invalid_rules_version'); END IF;
  v_total := GREATEST(COALESCE(p_prize_pool, 0), 0);
  FOR t IN SELECT value FROM jsonb_array_elements(v_rules -> 'prizes' -> 'tiers') LOOP
    SELECT COALESCE(jsonb_agg(f.value ORDER BY f.ord), '[]'::jsonb) INTO v_members
      FROM (SELECT value, ord FROM jsonb_array_elements(COALESCE(p_finishers, '[]'::jsonb)) WITH ORDINALITY AS e(value, ord)
             WHERE (value ->> 'finish_tier')::integer = (t ->> 'finish_tier')::integer
             ORDER BY ord LIMIT (t ->> 'places')::integer) f;
    IF jsonb_array_length(v_members) > 0 THEN
      v_each := ((v_total * (t ->> 'bp')::bigint) / 10000) / jsonb_array_length(v_members);
      SELECT v_out || COALESCE(jsonb_agg(jsonb_build_object('user_id', m ->> 'user_id', 'finish_tier', (t ->> 'finish_tier')::integer,
                                                            'amount', v_each)), '[]'::jsonb)
        INTO v_out FROM jsonb_array_elements(v_members) m;
      v_paid := v_paid + v_each * jsonb_array_length(v_members);
    END IF;
  END LOOP;
  SELECT COALESCE(jsonb_agg(CASE WHEN e.ord = (SELECT min(o2.ord) FROM jsonb_array_elements(v_out) WITH ORDINALITY o2(value, ord)
                                                 WHERE (o2.value ->> 'finish_tier')::integer = 1)
                                 THEN e.value || jsonb_build_object('amount', (e.value ->> 'amount')::bigint + (v_total - v_paid))
                                 ELSE e.value END ORDER BY e.ord) FILTER (WHERE true), '[]'::jsonb)
    INTO v_out FROM jsonb_array_elements(v_out) WITH ORDINALITY e(value, ord);
  RETURN (SELECT COALESCE(jsonb_agg(value), '[]'::jsonb) FROM jsonb_array_elements(v_out) WHERE (value ->> 'amount')::bigint > 0);
END $$;


ALTER FUNCTION public.trivia_rules_tournament_prizes(p_rules_version_id text, p_prize_pool bigint, p_finishers jsonb) OWNER TO postgres;

--
-- TOC entry 7168 (class 1255 OID 74744022)
-- Name: trivia_select_core_v1(bytea, text, text, integer, uuid[], uuid[], timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_select_core_v1(p_secret bytea, p_label text, p_profile_id text, p_count integer, p_player_ids uuid[], p_exclude_canonical uuid[], p_as_of timestamp with time zone) RETURNS TABLE(pos integer, question_id uuid, revision_id uuid, canonical_question_id uuid, category text, difficulty text, tier smallint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_c record;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.trivia_roster_profiles r WHERE r.profile_id = p_profile_id) THEN
        RAISE EXCEPTION 'unknown_profile %', p_profile_id;
    END IF;
    IF p_secret IS NULL OR p_label IS NULL OR p_as_of IS NULL THEN RAISE EXCEPTION 'select_core_arguments'; END IF;
    v_c := public.trivia_p3_candidates_v1(p_profile_id, p_player_ids, p_exclude_canonical, p_as_of);
    RETURN QUERY SELECT * FROM public.trivia_p3_select_passes_v1(p_secret, p_label, p_profile_id, p_count,
        v_c.qids, v_c.rids, v_c.cats, v_c.diffs, v_c.tiers);
END $$;


ALTER FUNCTION public.trivia_select_core_v1(p_secret bytea, p_label text, p_profile_id text, p_count integer, p_player_ids uuid[], p_exclude_canonical uuid[], p_as_of timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 6330 (class 1255 OID 74744063)
-- Name: trivia_selector_coverage_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_selector_coverage_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE r record; v_out jsonb := '{}'::jsonb; v_legacy integer; v_elig integer; v_built integer;
BEGIN
    FOR r IN SELECT * FROM public.trivia_roster_profiles ORDER BY profile_id LOOP
        SELECT count(*) INTO v_legacy FROM public.trivia_questions q
         WHERE q.category = ANY (r.categories) AND coalesce(q.quality_score, 0) >= 6;
        SELECT count(*) INTO v_elig FROM public.trivia_eligible_question_pool_v1 p
         WHERE r.mode = ANY (p.modes) AND p.category = ANY (r.categories)
           AND (r.per_question_seconds IS NULL OR p.min_timer_seconds <= r.per_question_seconds);
        SELECT count(*) INTO v_built FROM public.trivia_select_core_v1(public.trivia_engine_secret_v1('roster-v1'),
            'coverage:' || r.profile_id, r.profile_id, r.question_count, '{}'::uuid[], '{}'::uuid[], now());
        v_out := v_out || jsonb_build_object(r.profile_id, jsonb_build_object('legacy_pool', v_legacy,
            'eligible_pool', v_elig, 'excluded_by_eligibility', v_legacy - least(v_legacy, v_elig),
            'roster_size', r.question_count, 'v3_roster_built', v_built, 'fills', v_built = r.question_count,
            'days_of_no_repeat_supply', floor(v_elig::numeric / r.question_count)));
    END LOOP;
    RETURN jsonb_build_object('success', true, 'profiles', v_out,
        'tournament_256', public.trivia_tournament_capacity_v1(256), 'tournament_512', public.trivia_tournament_capacity_v1(512));
END $$;


ALTER FUNCTION public.trivia_selector_coverage_v1() OWNER TO postgres;

--
-- TOC entry 4582 (class 1255 OID 110226016)
-- Name: trivia_session_answer_before_phase9_v4(uuid, uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_session_answer_before_phase9_v4(p_session_id uuid, p_user_id uuid, p_question_id uuid, p_display_index integer, p_client_nonce uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE s public.trivia_sessions%ROWTYPE; a public.trivia_session_answers%ROWTYPE;
        v_res jsonb; v_metadata jsonb;
BEGIN
    IF p_session_id IS NULL OR p_user_id IS NULL OR p_question_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
    END IF;
    SELECT * INTO s FROM public.trivia_sessions WHERE id = p_session_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'session_not_found'); END IF;
    IF s.user_id IS DISTINCT FROM p_user_id THEN RETURN jsonb_build_object('success', false, 'error', 'not_your_session'); END IF;
    IF s.engine_version IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_engine_v3'); END IF;
    SELECT * INTO a FROM public.trivia_session_answers
     WHERE session_id = p_session_id AND question_id = p_question_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'question_not_in_session'); END IF;
    IF a.position < 1 OR a.position > coalesce(cardinality(s.question_ids), 0)
       OR s.question_ids[a.position] IS DISTINCT FROM a.question_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
    END IF;
    IF a.server_voided_at IS NOT NULL THEN
        RETURN jsonb_build_object('success', true, 'recorded', true, 'duplicate', true,
            'position', a.position, 'sequence', a.sequence, 'storedDisplayIndex', -1,
            'outcome', 'voided', 'voided', true);
    END IF;
    -- A first normal answer must not rely on the browser to notice invalidity.
    -- The invalid recorder reacquires the same row locks, locks current
    -- question/quarantine authority, and either durably neutralizes the row or
    -- proves it is still valid before V3 grading is allowed to run.
    IF a.outcome IS NULL THEN
        v_res := public.trivia_record_invalid_question_v1(
            p_session_id, p_user_id, p_question_id, p_client_nonce);
        IF coalesce((v_res ->> 'success')::boolean, false) IS TRUE THEN
            RETURN v_res || jsonb_build_object(
                'questionId', p_question_id, 'position', a.position);
        END IF;
        IF v_res ->> 'error' <> 'question_still_valid' THEN RETURN v_res; END IF;
    END IF;
    v_res := public.trivia_session_answer_v3(
        p_session_id, p_user_id, p_question_id, p_display_index, p_client_nonce);
    -- Raw metadata stays inside the service-only RPC. The API projects its
    -- narrow solver contract only after the delegated V3 receipt reveals a
    -- verdict; no metadata crosses a delayed-reveal boundary.
    IF v_res ? 'wasCorrect' THEN
        SELECT public.trivia_project_engine_metadata_v1(r.engine_metadata) INTO v_metadata
          FROM public.trivia_question_revisions r
         WHERE r.id = a.revision_id AND r.question_id = a.question_id;
        v_res := v_res || jsonb_build_object('engineMetadata', coalesce(v_metadata, '{}'::jsonb));
    END IF;
    RETURN v_res;
END $$;


ALTER FUNCTION public.trivia_session_answer_before_phase9_v4(p_session_id uuid, p_user_id uuid, p_question_id uuid, p_display_index integer, p_client_nonce uuid) OWNER TO postgres;

--
-- TOC entry 9536 (class 1255 OID 74743932)
-- Name: trivia_session_answer_guard_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_session_answer_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_reason text;
BEGIN
    IF TG_OP <> 'UPDATE' THEN
        RAISE EXCEPTION 'trivia_session_answers rows are never deleted' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.session_id <> OLD.session_id OR NEW.position <> OLD.position
       OR NEW.question_id <> OLD.question_id OR NEW.revision_id <> OLD.revision_id
       OR NEW.option_count <> OLD.option_count OR NEW.actor_type <> OLD.actor_type
       OR (OLD.opened_at IS NOT NULL AND NEW.opened_at IS DISTINCT FROM OLD.opened_at)
       OR (OLD.opened_at IS NOT NULL AND NEW.deadline_at IS DISTINCT FROM OLD.deadline_at) THEN
        RAISE EXCEPTION 'a recorded answer is immutable' USING ERRCODE = 'check_violation';
    END IF;
    -- Whether the row was unanswered or already answered, the first durable
    -- void transition is accepted only when its complete mutation shape and
    -- live authority evidence agree. This closes the direct-table path that
    -- would otherwise be able to manufacture a server void on an empty row.
    IF OLD.server_voided_at IS NULL AND NEW.server_voided_at IS NOT NULL THEN
        IF NEW.server_void_reason IN ('structural','audit','quarantine')
           AND NEW.outcome = 'skip' AND NEW.display_index = -1
           AND NEW.original_index IS NULL AND NEW.is_correct IS FALSE
           AND NEW.answered_at IS NOT NULL AND NEW.sequence IS NOT NULL
           AND NEW.opened_at IS NOT DISTINCT FROM OLD.opened_at
           AND NEW.deadline_at IS NOT DISTINCT FROM OLD.deadline_at
           AND (OLD.outcome IS NULL OR NEW.client_nonce IS NOT DISTINCT FROM OLD.client_nonce)
           AND (to_jsonb(NEW) - ARRAY['answered_at','display_index','original_index','is_correct',
                    'outcome','sequence','client_nonce','server_voided_at','server_void_reason'])
               IS NOT DISTINCT FROM
               (to_jsonb(OLD) - ARRAY['answered_at','display_index','original_index','is_correct',
                    'outcome','sequence','client_nonce','server_voided_at','server_void_reason']) THEN
            SELECT CASE
                       WHEN r.structurally_valid IS FALSE THEN 'structural'
                       WHEN q.audit_verified IS FALSE THEN 'audit'
                       WHEN EXISTS (
                           SELECT 1 FROM public.trivia_question_quarantine z
                            WHERE z.question_id = q.id AND z.released_at IS NULL)
                           THEN 'quarantine'
                   END
              INTO v_reason
              FROM public.trivia_question_revisions r
              JOIN public.trivia_questions q ON q.id = r.question_id
             WHERE r.id = NEW.revision_id AND q.id = NEW.question_id;
            IF v_reason IS NOT DISTINCT FROM NEW.server_void_reason THEN
                RETURN NEW;
            END IF;
        END IF;
        RAISE EXCEPTION 'a recorded answer is immutable' USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.outcome IS NOT NULL AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) THEN
        RAISE EXCEPTION 'a recorded answer is immutable' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION public.trivia_session_answer_guard_v1() OWNER TO postgres;

--
-- TOC entry 3948 (class 1255 OID 74744040)
-- Name: trivia_session_answer_v3(uuid, uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_session_answer_v3(p_session_id uuid, p_user_id uuid, p_question_id uuid, p_display_index integer, p_client_nonce uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE s public.trivia_sessions%ROWTYPE; v_p public.trivia_roster_profiles%ROWTYPE; a public.trivia_session_answers%ROWTYPE;
        r public.trivia_question_revisions%ROWTYPE; v_now timestamptz := clock_timestamp(); v_perm jsonb;
        v_orig integer; v_correct boolean; v_outcome text; v_seq integer; v_reveal boolean; v_res jsonb;
BEGIN
    IF p_session_id IS NULL OR p_user_id IS NULL OR p_question_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
    END IF;
    SELECT * INTO s FROM public.trivia_sessions WHERE id = p_session_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'session_not_found'); END IF;
    IF s.user_id IS DISTINCT FROM p_user_id THEN RETURN jsonb_build_object('success', false, 'error', 'not_your_session'); END IF;
    IF s.engine_version IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_engine_v3'); END IF;
    SELECT * INTO v_p FROM public.trivia_roster_profiles WHERE profile_id = s.roster_profile_id;
    SELECT * INTO a FROM public.trivia_session_answers WHERE session_id = p_session_id AND question_id = p_question_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'question_not_in_session'); END IF;
    SELECT * INTO r FROM public.trivia_question_revisions WHERE id = a.revision_id;
    v_perm := s.permutations -> p_question_id::text;
    v_reveal := public.trivia_p3_revealed(s, v_p.reveal_policy);
    IF a.outcome IS NOT NULL THEN
        v_res := jsonb_build_object('success', a.outcome <> 'late', 'recorded', true, 'duplicate', true,
            'position', a.position, 'sequence', a.sequence, 'storedDisplayIndex', a.display_index,
            'outcome', CASE WHEN v_reveal THEN a.outcome WHEN a.outcome IN ('late','timeout') THEN a.outcome ELSE 'recorded' END);
        IF a.outcome = 'late' THEN v_res := v_res || jsonb_build_object('error', 'answer_late'); END IF;
        IF v_reveal THEN
            v_res := v_res || jsonb_build_object('wasCorrect', coalesce(a.is_correct, false),
                'correctDisplayIndex', (SELECT (e.ord - 1)::int FROM jsonb_array_elements_text(v_perm) WITH ORDINALITY e(v, ord)
                                         WHERE e.v::int = r.correct_index), 'explanation', r.explanation);
        END IF;
        RETURN v_res;
    END IF;
    IF s.status <> 'open' THEN RETURN jsonb_build_object('success', false, 'error', 'session_closed'); END IF;
    IF v_now > s.expires_at THEN RETURN jsonb_build_object('success', false, 'error', 'session_expired'); END IF;
    IF v_p.per_question_seconds IS NOT NULL THEN
        IF a.opened_at IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'question_not_open'); END IF;
        IF v_now > a.deadline_at + make_interval(secs => v_p.grace_ms / 1000.0) THEN
            UPDATE public.trivia_session_answers
               SET outcome = 'late', is_correct = false, answered_at = v_now, client_nonce = p_client_nonce
             WHERE session_id = p_session_id AND position = a.position;
            RETURN jsonb_build_object('success', false, 'error', 'answer_late', 'recorded', true, 'position', a.position);
        END IF;
    END IF;
    IF p_display_index IS NULL OR p_display_index < -1 OR p_display_index >= a.option_count THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_display_index');
    END IF;
    IF p_display_index >= 0 THEN
        v_orig := (v_perm ->> p_display_index)::int;
        v_correct := v_orig = r.correct_index;
        v_outcome := CASE WHEN v_correct THEN 'correct' ELSE 'wrong' END;
    ELSE
        v_orig := NULL; v_correct := false; v_outcome := 'skip';
    END IF;
    SELECT count(*) + 1 INTO v_seq FROM public.trivia_session_answers
     WHERE session_id = p_session_id AND sequence IS NOT NULL;
    UPDATE public.trivia_session_answers
       SET answered_at = v_now, display_index = p_display_index, original_index = v_orig, is_correct = v_correct,
           outcome = v_outcome, sequence = v_seq, client_nonce = p_client_nonce
     WHERE session_id = p_session_id AND position = a.position;
    v_res := jsonb_build_object('success', true, 'recorded', true, 'duplicate', false, 'position', a.position,
        'sequence', v_seq, 'storedDisplayIndex', p_display_index,
        'outcome', CASE WHEN v_reveal THEN v_outcome ELSE 'recorded' END);
    IF v_reveal THEN
        v_res := v_res || jsonb_build_object('wasCorrect', v_correct,
            'correctDisplayIndex', (SELECT (e.ord - 1)::int FROM jsonb_array_elements_text(v_perm) WITH ORDINALITY e(v, ord)
                                     WHERE e.v::int = r.correct_index), 'explanation', r.explanation);
    END IF;
    RETURN v_res;
END $$;


ALTER FUNCTION public.trivia_session_answer_v3(p_session_id uuid, p_user_id uuid, p_question_id uuid, p_display_index integer, p_client_nonce uuid) OWNER TO postgres;

