-- TOC entry 6273 (class 1255 OID 115338756)
-- Name: trivia_session_settle_solo_v4(uuid, uuid, integer, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_session_settle_solo_v4(p_session_id uuid, p_user_id uuid, p_diamonds integer, p_grade_basis jsonb, p_request_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
    SELECT public.trivia_session_settle_solo_v5(
        p_session_id, p_user_id, p_diamonds, p_grade_basis, p_request_id)
$$;


ALTER FUNCTION public.trivia_session_settle_solo_v4(p_session_id uuid, p_user_id uuid, p_diamonds integer, p_grade_basis jsonb, p_request_id uuid) OWNER TO postgres;

--
-- TOC entry 3331 (class 1255 OID 115338745)
-- Name: trivia_session_settle_solo_v5(uuid, uuid, integer, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_session_settle_solo_v5(p_session_id uuid, p_user_id uuid, p_diamonds integer, p_grade_basis jsonb, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    s public.trivia_sessions%ROWTYPE;
    v_status jsonb;
    v_settlement jsonb;
    v_projection jsonb;
BEGIN
    SELECT * INTO s FROM public.trivia_sessions WHERE id = p_session_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'session_not_found'); END IF;
    IF s.user_id IS DISTINCT FROM p_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_your_session');
    END IF;
    -- A committed settlement is an immutable financial receipt. Replay it
    -- before applying the new admission boundary: historical overrun evidence
    -- is ineligible for the leaderboard, but can never erase or mask the
    -- already-committed wallet result.
    IF s.status = 'submitted' THEN
        v_settlement := public.trivia_session_settle_solo_before_phase9_v4(
            p_session_id, p_user_id, p_diamonds, p_grade_basis, p_request_id);
        IF coalesce((v_settlement ->> 'success')::boolean, false) IS NOT TRUE THEN
            RETURN v_settlement;
        END IF;
        IF s.mode = 'endless' THEN
            v_status := public.trivia_solo_miss_status_v1(s.id, p_user_id);
            IF coalesce((v_status ->> 'success')::boolean, false) IS NOT TRUE THEN
                RETURN v_settlement || jsonb_build_object('highScoreProjection',
                    jsonb_build_object('status', 'pending',
                        'reason', 'boundary_status_unavailable',
                        'highScore', NULL, 'improved', false));
            ELSIF coalesce((v_status ->> 'overrun')::boolean, false) IS TRUE THEN
                RETURN v_settlement || jsonb_build_object('highScoreProjection',
                    jsonb_build_object('status', 'ineligible',
                        'reason', 'historical_run_boundary_overrun',
                        'highScore', NULL, 'improved', false));
            END IF;
            v_projection := public.trivia_endless_high_score_project_v1(s.id, p_user_id);
            IF coalesce((v_projection ->> 'success')::boolean, false) IS NOT TRUE
               OR v_projection ->> 'status' IS DISTINCT FROM 'persisted' THEN
                RETURN v_settlement || jsonb_build_object('highScoreProjection',
                    jsonb_build_object('status', 'pending',
                        'reason', 'projection_unavailable',
                        'highScore', NULL, 'improved', false));
            END IF;
            RETURN v_settlement || jsonb_build_object('highScoreProjection', v_projection);
        END IF;
        RETURN v_settlement;
    END IF;
    IF s.mode IN ('endless','survival') THEN
        v_status := public.trivia_solo_miss_status_v1(s.id, p_user_id);
        IF coalesce((v_status ->> 'success')::boolean, false) IS NOT TRUE THEN RETURN v_status; END IF;
        IF coalesce((v_status ->> 'overrun')::boolean, false) IS TRUE THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'run_miss_limit_reached',
                'nonPaidMissCount', (v_status ->> 'nonPaidMissCount')::integer,
                'terminalFailureCount', (v_status ->> 'terminalFailureCount')::integer,
                'missLimit', (v_status ->> 'missLimit')::integer,
                'runMissLimitReached', true,
                'overrun', true
            );
        END IF;
    END IF;
    BEGIN
        v_settlement := public.trivia_session_settle_solo_before_phase9_v4(
            p_session_id, p_user_id, p_diamonds, p_grade_basis, p_request_id);
        IF coalesce((v_settlement ->> 'success')::boolean, false) IS NOT TRUE THEN
            RETURN v_settlement;
        END IF;
        IF s.mode = 'endless' THEN
            v_projection := public.trivia_endless_high_score_project_v1(s.id, p_user_id);
            IF coalesce((v_projection ->> 'success')::boolean, false) IS NOT TRUE
               OR v_projection ->> 'status' IS DISTINCT FROM 'persisted' THEN
                RAISE EXCEPTION 'atomic Endless projection failed: %',
                    coalesce(v_projection ->> 'error', 'invalid_projection_receipt')
                    USING ERRCODE = 'PS002';
            END IF;
            v_settlement := v_settlement || jsonb_build_object('highScoreProjection', v_projection);
        END IF;
    EXCEPTION WHEN SQLSTATE 'PS002' THEN
        RETURN jsonb_build_object('success', false, 'error', 'high_score_projection_failed',
            'highScoreProjection', jsonb_build_object('status', 'pending'));
    END;
    RETURN v_settlement;
END;
$$;


ALTER FUNCTION public.trivia_session_settle_solo_v5(p_session_id uuid, p_user_id uuid, p_diamonds integer, p_grade_basis jsonb, p_request_id uuid) OWNER TO postgres;

--
-- TOC entry 7355 (class 1255 OID 110225983)
-- Name: trivia_session_settlement_request_guard_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_session_settlement_request_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    IF OLD.settlement_request_id IS NOT NULL THEN
        IF NEW.settlement_request_id IS DISTINCT FROM OLD.settlement_request_id THEN
            RAISE EXCEPTION 'settlement request identity is immutable' USING ERRCODE = 'check_violation';
        END IF;
        IF NEW.settlement_result IS DISTINCT FROM OLD.settlement_result THEN
            RAISE EXCEPTION 'settlement result is immutable after request identity is sealed'
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    IF OLD.settlement_request_id IS NULL AND NEW.settlement_request_id IS NOT NULL THEN
        IF OLD.status <> 'submitted' OR NEW.status <> 'submitted'
           OR NEW.settlement_result IS NULL
           OR (to_jsonb(NEW) - ARRAY['settlement_request_id','settlement_result'])
              IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['settlement_request_id','settlement_result']) THEN
            RAISE EXCEPTION 'settlement request identity can only seal an atomically completed settlement'
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END $$;


ALTER FUNCTION public.trivia_session_settlement_request_guard_v1() OWNER TO postgres;

--
-- TOC entry 9020 (class 1255 OID 74744051)
-- Name: trivia_session_submit_v3(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_session_submit_v3(p_session_id uuid, p_user_id uuid, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE s public.trivia_sessions%ROWTYPE; v_r jsonb;
BEGIN
    SELECT * INTO s FROM public.trivia_sessions WHERE id = p_session_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'session_not_found'); END IF;
    IF s.user_id IS DISTINCT FROM p_user_id THEN RETURN jsonb_build_object('success', false, 'error', 'not_your_session'); END IF;
    IF s.engine_version IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_engine_v3'); END IF;
    IF s.mode NOT IN ('pvp','tournaments') THEN RETURN jsonb_build_object('success', false, 'error', 'use_settle_solo'); END IF;
    IF EXISTS (SELECT 1 FROM public.trivia_session_results WHERE session_id = s.id) THEN
        v_r := public.trivia_p3_finalize_session(s.id, 'submitted', p_request_id);
        RETURN public.trivia_p3_result_receipt(v_r, s.status);
    END IF;
    IF s.status <> 'open' THEN RETURN jsonb_build_object('success', false, 'error', 'session_closed'); END IF;
    IF clock_timestamp() > s.expires_at THEN
        PERFORM public.trivia_p3_expire_session(s.id, 'submit_after_deadline');
        RETURN jsonb_build_object('success', false, 'error', 'session_expired');
    END IF;
    v_r := public.trivia_p3_finalize_session(s.id, 'submitted', p_request_id);
    UPDATE public.trivia_sessions
       SET status = 'submitted', submitted_at = (v_r ->> 'completed_at')::timestamptz,
           score = (v_r ->> 'score')::int, correct_count = (v_r ->> 'correct')::int, diamonds_awarded = 0,
           settlement_result = jsonb_build_object('engine', s.engine_version, 'result_hash', v_r ->> 'result_hash')
     WHERE id = s.id;
    RETURN public.trivia_p3_result_receipt(v_r, 'submitted');
END $$;


ALTER FUNCTION public.trivia_session_submit_v3(p_session_id uuid, p_user_id uuid, p_request_id uuid) OWNER TO postgres;

--
-- TOC entry 8471 (class 1255 OID 74744034)
-- Name: trivia_session_view_v3(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_session_view_v3(p_session_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE s public.trivia_sessions%ROWTYPE; v_p public.trivia_roster_profiles%ROWTYPE; v_q jsonb; v_shot boolean;
BEGIN
    SELECT * INTO s FROM public.trivia_sessions WHERE id = p_session_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'session_not_found'); END IF;
    IF s.user_id IS DISTINCT FROM p_user_id THEN RETURN jsonb_build_object('success', false, 'error', 'not_your_session'); END IF;
    IF s.engine_version IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_engine_v3'); END IF;
    SELECT * INTO v_p FROM public.trivia_roster_profiles WHERE profile_id = s.roster_profile_id;
    v_shot := v_p.per_question_seconds IS NOT NULL;
    SELECT jsonb_agg(CASE WHEN v_shot AND a.opened_at IS NULL AND a.outcome IS NULL
                THEN jsonb_build_object('position', a.position, 'state', 'locked')
                ELSE jsonb_build_object('position', a.position, 'id', a.question_id, 'question', r.question,
                    'options', (SELECT jsonb_agg(r.options -> ((e.value #>> '{}')::int) ORDER BY e.ord)
                                  FROM jsonb_array_elements(s.permutations -> a.question_id::text) WITH ORDINALITY AS e(value, ord)),
                    'category', r.category, 'difficulty', r.difficulty,
                    'state', CASE WHEN a.outcome IN ('correct','wrong','skip') THEN 'answered'
                                  WHEN a.outcome IN ('late','timeout') THEN 'timeout' ELSE 'unanswered' END,
                    'openedAt', CASE WHEN v_shot THEN a.opened_at END,
                    'deadlineAt', CASE WHEN v_shot THEN a.deadline_at END) END ORDER BY a.position)
      INTO v_q
      FROM public.trivia_session_answers a JOIN public.trivia_question_revisions r ON r.id = a.revision_id
     WHERE a.session_id = s.id;
    RETURN jsonb_build_object('success', true, 'sessionId', s.id, 'mode', s.mode, 'engine', s.engine_version,
        'status', s.status, 'resumed', false, 'expiresAt', s.expires_at, 'contract', s.session_contract,
        'contractSignature', s.contract_signature, 'questionCount', jsonb_array_length(coalesce(v_q, '[]'::jsonb)),
        'questions', coalesce(v_q, '[]'::jsonb), 'entryCost', s.entry_cost, 'entryState', s.entry_state);
END $$;


ALTER FUNCTION public.trivia_session_view_v3(p_session_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 8338 (class 1255 OID 74431278)
-- Name: trivia_settlement_lock(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_settlement_lock(p_subject_type text, p_subject_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE s public.trivia_settlements%ROWTYPE; v_gross bigint; v_n integer;
BEGIN
  SELECT * INTO s FROM public.trivia_settlements WHERE subject_type = p_subject_type AND subject_id = p_subject_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'settlement_not_found');
  END IF;
  IF s.state IN ('settled', 'refunded', 'voided') THEN
    RETURN jsonb_build_object('success', false, 'error', 'settlement_terminal', 'state', s.state);
  END IF;
  IF s.state = 'locked' THEN
    v_gross := s.gross_pool;
  ELSE
    v_gross := public.trivia_settlement_lock_row(s);
  END IF;
  SELECT count(*) INTO v_n FROM public.trivia_settlement_participants WHERE settlement_id = s.id AND state = 'held';
  RETURN jsonb_build_object('success', true, 'replayed', s.state = 'locked', 'settlement_id', s.id, 'state', 'locked',
                            'gross_pool', v_gross, 'participant_count', v_n);
END $$;


ALTER FUNCTION public.trivia_settlement_lock(p_subject_type text, p_subject_id uuid) OWNER TO postgres;

--
-- TOC entry 4871 (class 1255 OID 74431277)
-- Name: trivia_settlement_lock_row(public.trivia_settlements); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_settlement_lock_row(s public.trivia_settlements) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_escrow bigint;
BEGIN
  SELECT balance INTO v_escrow FROM public.trivia_ledger_accounts WHERE account_code = s.escrow_account_code FOR UPDATE;
  PERFORM set_config('trivia_ledger.writer', 'on', true);
  UPDATE public.trivia_settlements SET state = 'locked', gross_pool = v_escrow, locked_at = clock_timestamp() WHERE id = s.id;
  INSERT INTO public.trivia_settlement_events (settlement_id, event, from_state, to_state, detail)
  VALUES (s.id, 'lock', 'open', 'locked', jsonb_build_object('gross_pool', v_escrow));
  RETURN v_escrow;
END $$;


ALTER FUNCTION public.trivia_settlement_lock_row(s public.trivia_settlements) OWNER TO postgres;

--
-- TOC entry 4161 (class 1255 OID 74431276)
-- Name: trivia_settlement_open(text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_settlement_open(p_subject_type text, p_subject_id uuid, p_rules_version_id text, p_context jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE s public.trivia_settlements%ROWTYPE; v_family text; v_code text; v_key text; v_detail text;
BEGIN
  BEGIN
    IF p_subject_type NOT IN ('pvp_match', 'tournament') OR p_subject_id IS NULL THEN
      PERFORM public.trivia_ledger_raise('invalid_subject', jsonb_build_object('subject_type', p_subject_type, 'subject_id', p_subject_id));
    END IF;
    SELECT family INTO v_family FROM public.trivia_rules_versions WHERE id = p_rules_version_id;
    IF v_family IS NULL OR v_family <> (CASE p_subject_type WHEN 'pvp_match' THEN 'pvp' ELSE 'tournament' END) THEN
      PERFORM public.trivia_ledger_raise('invalid_rules_version', jsonb_build_object('rules_version_id', p_rules_version_id));
    END IF;
    IF EXISTS (SELECT 1 FROM public.competitive_quarantine q
                WHERE q.entity_type = CASE p_subject_type WHEN 'pvp_match' THEN 'trivia_pvp_match' ELSE 'trivia_tournament' END
                  AND q.entity_id = p_subject_id) THEN
      PERFORM public.trivia_ledger_raise('subject_quarantined');
    END IF;
    IF (p_subject_type = 'pvp_match' AND NOT EXISTS (SELECT 1 FROM public.trivia_pvp_matches WHERE id = p_subject_id))
       OR (p_subject_type = 'tournament' AND NOT EXISTS (SELECT 1 FROM public.trivia_tournaments WHERE id = p_subject_id)) THEN
      PERFORM public.trivia_ledger_raise('subject_not_found');
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('trivia_settlement:' || p_subject_type || ':' || p_subject_id::text, 20260929));
    SELECT * INTO s FROM public.trivia_settlements WHERE subject_type = p_subject_type AND subject_id = p_subject_id;
    IF FOUND THEN
      IF s.rules_version_id <> p_rules_version_id THEN
        PERFORM public.trivia_ledger_raise('settlement_exists_with_other_rules', jsonb_build_object('rules_version_id', s.rules_version_id));
      END IF;
      RETURN jsonb_build_object('success', true, 'replayed', true, 'settlement_id', s.id, 'idempotency_key', s.idempotency_key,
                                'escrow_account', s.escrow_account_code, 'state', s.state, 'rules_version_id', s.rules_version_id);
    END IF;
    v_code := CASE p_subject_type WHEN 'pvp_match' THEN 'escrow:pvp:' ELSE 'escrow:tournament:' END || p_subject_id::text;
    v_key := CASE p_subject_type WHEN 'pvp_match' THEN 'pvp_settlement_' ELSE 'trivia_tourn_settlement_' END || p_subject_id::text;
    PERFORM public.trivia_ledger_ensure_account(v_code);
    INSERT INTO public.trivia_settlements (subject_type, subject_id, idempotency_key, rules_version_id, escrow_account_code, context)
    VALUES (p_subject_type, p_subject_id, v_key, p_rules_version_id, v_code, COALESCE(p_context, '{}'::jsonb))
    RETURNING * INTO s;
    INSERT INTO public.trivia_settlement_events (settlement_id, event, to_state, detail)
    VALUES (s.id, 'open', 'open', jsonb_build_object('rules_version_id', p_rules_version_id));
    RETURN jsonb_build_object('success', true, 'replayed', false, 'settlement_id', s.id, 'idempotency_key', s.idempotency_key,
                              'escrow_account', s.escrow_account_code, 'state', s.state, 'rules_version_id', s.rules_version_id);
  EXCEPTION
    WHEN SQLSTATE 'TL001' THEN
      GET STACKED DIAGNOSTICS v_detail = PG_EXCEPTION_DETAIL;
      RETURN public.trivia_ledger_error(SQLERRM, v_detail, NULL, 'settlement_open');
    WHEN OTHERS THEN
      RETURN public.trivia_ledger_unexpected(SQLSTATE, SQLERRM, NULL, 'settlement_open');
  END;
END $$;


ALTER FUNCTION public.trivia_settlement_open(p_subject_type text, p_subject_id uuid, p_rules_version_id text, p_context jsonb) OWNER TO postgres;

--
-- TOC entry 8743 (class 1255 OID 115336432)
-- Name: trivia_settlement_payout_control_apply_v1(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_settlement_payout_control_apply_v1(p_operator_id uuid, p_receipt_id uuid, p_action text, p_settlement_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_context jsonb;
    v_settlement public.trivia_settlements%ROWTYPE;
    v_previous public.trivia_settlement_payout_controls_v1%ROWTYPE;
    v_action text;
BEGIN
    IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'service_role required' USING ERRCODE = '42501';
    END IF;
    IF p_operator_id IS NULL OR p_receipt_id IS NULL OR p_settlement_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'control_identity_required');
    END IF;
    IF p_action NOT IN ('hold', 'release') THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_control_action');
    END IF;
    IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 8 AND 500 THEN
        RETURN jsonb_build_object('success', false, 'error', 'reason_required');
    END IF;
    v_context := public.trivia_operator_context_core_v1(p_operator_id);
    IF NOT COALESCE((v_context->>'allowed')::boolean, false)
       OR NOT (v_context->'capabilities' ? 'settlement_control') THEN
        RETURN jsonb_build_object('success', false, 'error', 'operator_capability_required');
    END IF;

    -- This is the lock shared with trivia_settlement_settle. Whichever request
    -- owns it first determines the only legal ordering of hold/release/settle.
    SELECT * INTO v_settlement
      FROM public.trivia_settlements
     WHERE id = p_settlement_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'settlement_not_found');
    END IF;

    SELECT * INTO v_previous
      FROM public.trivia_settlement_payout_controls_v1
     WHERE settlement_id = p_settlement_id
     ORDER BY control_id DESC
     LIMIT 1;
    v_action := CASE WHEN p_action = 'hold' THEN 'hold' ELSE 'release' END;

    IF p_action = 'hold' THEN
        IF v_settlement.state IN ('settled', 'refunded', 'voided') THEN
            RETURN jsonb_build_object(
                'success', false, 'error', 'settlement_terminal',
                'settlementId', v_settlement.id, 'settlementState', v_settlement.state
            );
        END IF;
        IF v_previous.action = 'hold' THEN
            RETURN jsonb_build_object(
                'success', false, 'error', 'payout_already_held',
                'settlementId', v_settlement.id, 'payoutControlState', 'held',
                'activeHoldReceiptId', v_previous.receipt_id
            );
        END IF;
    ELSIF v_previous.action IS DISTINCT FROM 'hold' THEN
        RETURN jsonb_build_object(
            'success', false, 'error', 'payout_not_held',
            'settlementId', v_settlement.id, 'payoutControlState', 'released'
        );
    END IF;

    INSERT INTO public.trivia_settlement_payout_controls_v1
        (receipt_id, settlement_id, operator_id, action, reason)
    VALUES
        (p_receipt_id, p_settlement_id, p_operator_id, v_action, btrim(p_reason));

    RETURN jsonb_build_object(
        'success', true,
        'settlementId', v_settlement.id,
        'subjectType', v_settlement.subject_type,
        'subjectId', v_settlement.subject_id,
        'settlementState', v_settlement.state,
        'payoutControlState', CASE WHEN p_action = 'hold' THEN 'held' ELSE 'released' END,
        'controlReceiptId', p_receipt_id
    );
END
$$;


ALTER FUNCTION public.trivia_settlement_payout_control_apply_v1(p_operator_id uuid, p_receipt_id uuid, p_action text, p_settlement_id uuid, p_reason text) OWNER TO postgres;

--
-- TOC entry 4145 (class 1255 OID 115336434)
-- Name: trivia_settlement_payout_control_status_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_settlement_payout_control_status_v1(p_operator_id uuid, p_settlement_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_context jsonb;
    v_result jsonb;
BEGIN
    IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'service_role required' USING ERRCODE = '42501';
    END IF;
    v_context := public.trivia_operator_context_core_v1(p_operator_id);
    IF NOT COALESCE((v_context->>'allowed')::boolean, false)
       OR NOT ((v_context->'capabilities' ? 'settlement_control')
            OR (v_context->'capabilities' ? 'support_lookup')) THEN
        RETURN jsonb_build_object('success', false, 'error', 'operator_capability_required');
    END IF;
    SELECT jsonb_build_object(
        'success', true,
        'kind', 'settlement',
        'targetId', s.id,
        'found', true,
        'subjectType', s.subject_type,
        'subjectId', s.subject_id,
        'settlementState', s.state,
        'payoutControlState', CASE WHEN c.action = 'hold' THEN 'held' ELSE 'released' END,
        'latestControlReceiptId', c.receipt_id,
        'latestControlAction', c.action,
        'latestControlAt', c.created_at
    ) INTO v_result
      FROM public.trivia_settlements s
      LEFT JOIN LATERAL (
          SELECT pc.receipt_id, pc.action, pc.created_at
            FROM public.trivia_settlement_payout_controls_v1 pc
           WHERE pc.settlement_id = s.id
           ORDER BY pc.control_id DESC
           LIMIT 1
      ) c ON true
     WHERE s.id = p_settlement_id;
    RETURN COALESCE(v_result, jsonb_build_object(
        'success', true, 'kind', 'settlement', 'targetId', p_settlement_id, 'found', false
    ));
END
$$;


ALTER FUNCTION public.trivia_settlement_payout_control_status_v1(p_operator_id uuid, p_settlement_id uuid) OWNER TO postgres;

--
-- TOC entry 6503 (class 1255 OID 74431279)
-- Name: trivia_settlement_settle(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_settlement_settle(p_subject_type text, p_subject_id uuid, p_plan jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  s public.trivia_settlements%ROWTYPE; p public.trivia_settlement_participants%ROWTYPE;
  v_hash text; v_outcome text; v_terminal text; v_refusal text; v_rake bigint; v_escrow bigint;
  v_pay bigint := 0; v_ref bigint := 0; v_lines jsonb := '[]'::jsonb; v_post jsonb; v_journal uuid;
  x jsonb; v_user uuid; v_amount bigint; v_kind text; v_seen uuid[] := '{}'; v_refs text[] := '{}';
  v_settled_entries bigint; v_alloc bigint; v_result jsonb; v_owed jsonb := '[]'::jsonb; v_rank integer;
  v_rake_account text;
  v_latest_control public.trivia_settlement_payout_controls_v1%ROWTYPE;
BEGIN
  IF p_subject_type NOT IN ('pvp_match', 'tournament') OR jsonb_typeof(p_plan) IS DISTINCT FROM 'object' THEN
    PERFORM public.trivia_ledger_raise('invalid_plan');
  END IF;
  SELECT * INTO s FROM public.trivia_settlements WHERE subject_type = p_subject_type AND subject_id = p_subject_id FOR UPDATE;
  IF NOT FOUND THEN
    PERFORM public.trivia_ledger_raise('settlement_not_found', jsonb_build_object('subject_type', p_subject_type, 'subject_id', p_subject_id));
  END IF;
  v_hash := public.trivia_ledger_sha256(p_plan::text);
  IF s.state IN ('settled', 'refunded', 'voided') THEN
    IF s.plan_hash = v_hash THEN
      INSERT INTO public.trivia_ledger_idempotency_events (idempotency_key, operation, outcome) VALUES (s.idempotency_key, 'settlement', 'replayed');
      RETURN s.result || jsonb_build_object('replayed', true);
    END IF;
    INSERT INTO public.trivia_ledger_idempotency_events (idempotency_key, operation, outcome) VALUES (s.idempotency_key, 'settlement', 'conflict');
    PERFORM public.trivia_ledger_raise('settlement_already_terminal', jsonb_build_object('state', s.state, 'settlement_id', s.id));
  END IF;
  v_outcome := p_plan ->> 'outcome';
  v_terminal := p_plan ->> 'terminal_state';
  v_refusal := COALESCE(p_plan ->> 'on_wallet_refusal', 'fail');
  v_rake := COALESCE((p_plan ->> 'rake')::bigint, 0);
  IF v_outcome IS NULL OR v_outcome NOT IN ('win', 'tie', 'forfeit', 'refund', 'void', 'prizes', 'cancelled')
     OR v_terminal IS NULL OR v_terminal NOT IN ('settled', 'refunded', 'voided') OR v_refusal NOT IN ('fail', 'liability')
     OR v_rake < 0 OR jsonb_typeof(COALESCE(p_plan -> 'payouts', '[]'::jsonb)) <> 'array'
     OR jsonb_typeof(COALESCE(p_plan -> 'refunds', '[]'::jsonb)) <> 'array' THEN
    PERFORM public.trivia_ledger_raise('invalid_plan', jsonb_build_object('plan', p_plan));
  END IF;
  -- Read the durable payout control while the settlement row selected above is
  -- still locked. The operator transition takes that same row lock, so a hold
  -- cannot land between this decision and the journal transaction.
  SELECT * INTO v_latest_control
    FROM public.trivia_settlement_payout_controls_v1
   WHERE settlement_id = s.id
   ORDER BY control_id DESC
   LIMIT 1;
  IF v_latest_control.action = 'hold'
     AND NOT (
       (v_terminal = 'refunded' AND v_outcome IN ('tie', 'refund', 'cancelled')
        AND jsonb_array_length(COALESCE(p_plan -> 'payouts', '[]'::jsonb)) = 0
        AND v_rake = 0)
       OR
       (v_terminal = 'voided' AND v_outcome = 'void'
        AND jsonb_array_length(COALESCE(p_plan -> 'payouts', '[]'::jsonb)) = 0
        AND v_rake = 0)
     ) THEN
    PERFORM public.trivia_ledger_raise(
      'settlement_payout_held',
      jsonb_build_object(
        'settlement_id', s.id,
        'subject_type', s.subject_type,
        'subject_id', s.subject_id,
        'hold_receipt_id', v_latest_control.receipt_id));
  END IF;
  PERFORM set_config('trivia_ledger.writer', 'on', true);
  IF s.state = 'open' THEN
    PERFORM public.trivia_settlement_lock_row(s);
    SELECT * INTO s FROM public.trivia_settlements WHERE id = s.id;
  END IF;
  SELECT balance INTO v_escrow FROM public.trivia_ledger_accounts WHERE account_code = s.escrow_account_code FOR UPDATE;
  v_rake_account := CASE WHEN p_subject_type = 'pvp_match' THEN 'house:rake:pvp' ELSE 'house:rake:tournament' END;
  -- payouts
  FOR x IN SELECT value FROM jsonb_array_elements(COALESCE(p_plan -> 'payouts', '[]'::jsonb)) LOOP
    v_user := (x ->> 'user_id')::uuid; v_amount := (x ->> 'amount')::bigint; v_kind := x ->> 'wallet_kind';
    SELECT * INTO p FROM public.trivia_settlement_participants WHERE settlement_id = s.id AND user_id = v_user FOR UPDATE;
    IF NOT FOUND OR p.state <> 'held' OR v_user = ANY (v_seen) OR v_amount IS NULL OR v_amount <= 0
       OR v_kind IS DISTINCT FROM (CASE WHEN p_subject_type = 'pvp_match' THEN 'pvp_win' ELSE 'tournament_prize' END)
       OR COALESCE(x ->> 'reference', '') !~ '^[A-Za-z0-9_:.@-]{8,200}$' OR (x ->> 'reference') = ANY (v_refs) THEN
      PERFORM public.trivia_ledger_raise('invalid_plan_payout', jsonb_build_object('payout', x));
    END IF;
    v_seen := v_seen || v_user; v_refs := v_refs || (x ->> 'reference'); v_pay := v_pay + v_amount;
    IF p.funding_source = 'treasury' THEN
      v_lines := v_lines || jsonb_build_array(jsonb_build_object('account', 'treasury:trivia', 'amount', v_amount, 'user_id', v_user,
                   'participant_kind', p.participant_kind, 'memo', 'horse prize to treasury (' || (x ->> 'reference') || ')'));
    ELSE
      v_lines := v_lines || jsonb_build_array(jsonb_build_object('account', 'wallet:' || v_user::text, 'amount', v_amount, 'user_id', v_user,
                   'participant_kind', p.participant_kind, 'wallet_kind', v_kind, 'wallet_reference', x ->> 'reference',
                   'wallet_description', x ->> 'description', 'mechanism', 'add', 'on_refusal', v_refusal));
    END IF;
  END LOOP;
  -- refunds: always the participant's original stored entry
  FOR x IN SELECT value FROM jsonb_array_elements(COALESCE(p_plan -> 'refunds', '[]'::jsonb)) LOOP
    v_user := (x ->> 'user_id')::uuid; v_kind := x ->> 'wallet_kind';
    SELECT * INTO p FROM public.trivia_settlement_participants WHERE settlement_id = s.id AND user_id = v_user FOR UPDATE;
    IF NOT FOUND OR p.state <> 'held' OR v_user = ANY (v_seen)
       OR (x ? 'amount' AND (x ->> 'amount')::bigint IS DISTINCT FROM p.entry_amount)
       OR NOT ((p_subject_type = 'pvp_match' AND v_kind = 'pvp_refund')
               OR (p_subject_type = 'tournament' AND v_kind IN ('tournament_entry_refund', 'tournament_cancel_refund')))
       OR COALESCE(x ->> 'reference', '') !~ '^[A-Za-z0-9_:.@-]{8,200}$' OR (x ->> 'reference') = ANY (v_refs) THEN
      PERFORM public.trivia_ledger_raise('invalid_plan_refund', jsonb_build_object('refund', x));
    END IF;
    v_seen := v_seen || v_user; v_refs := v_refs || (x ->> 'reference'); v_ref := v_ref + p.entry_amount;
    IF p.funding_source = 'treasury' THEN
      v_lines := v_lines || jsonb_build_array(jsonb_build_object('account', 'treasury:trivia', 'amount', p.entry_amount, 'user_id', v_user,
                   'participant_kind', p.participant_kind, 'memo', 'horse entry returned to treasury (' || (x ->> 'reference') || ')'));
    ELSE
      v_lines := v_lines || jsonb_build_array(jsonb_build_object('account', 'wallet:' || v_user::text, 'amount', p.entry_amount, 'user_id', v_user,
                   'participant_kind', p.participant_kind, 'wallet_kind', v_kind, 'wallet_reference', x ->> 'reference',
                   'wallet_description', x ->> 'description', 'mechanism', 'add', 'on_refusal', v_refusal));
    END IF;
  END LOOP;
  IF v_rake > 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account', v_rake_account, 'amount', v_rake, 'memo', 'rake'));
  END IF;
  -- conservation: every diamond in escrow is explained exactly once
  IF v_rake + v_pay + v_ref <> v_escrow THEN
    PERFORM public.trivia_ledger_raise('plan_does_not_conserve_escrow',
      jsonb_build_object('escrow', v_escrow, 'rake', v_rake, 'payouts', v_pay, 'refunds', v_ref));
  END IF;
  IF (v_terminal = 'voided' AND (v_escrow <> 0 OR v_pay <> 0 OR v_ref <> 0 OR v_rake <> 0))
     OR (v_terminal = 'refunded' AND (v_pay <> 0 OR v_rake <> 0))
     OR (v_terminal = 'settled' AND v_pay = 0 AND v_rake = 0) THEN
    PERFORM public.trivia_ledger_raise('terminal_state_inconsistent', jsonb_build_object('terminal_state', v_terminal));
  END IF;
  IF v_escrow > 0 THEN
    v_lines := jsonb_build_array(jsonb_build_object('account', s.escrow_account_code, 'amount', -v_escrow, 'memo', 'escrow settled')) || v_lines;
    v_post := public.trivia_ledger_post(
      jsonb_build_object('idempotency_key', s.idempotency_key, 'operation', 'settlement',
        'request', jsonb_build_object('op', 'settlement', 'subject_type', p_subject_type, 'subject_id', p_subject_id, 'plan_hash', v_hash),
        'source_event', p_subject_type || '.settled', 'source_type', p_subject_type, 'source_id', p_subject_id::text,
        'subject_type', p_subject_type, 'subject_id', p_subject_id, 'settlement_id', s.id, 'rules_version_id', s.rules_version_id,
        'actor_kind', 'system', 'funding_source', 'escrow'),
      v_lines);
    v_journal := (v_post ->> 'journal_id')::uuid;
    SELECT COALESCE(jsonb_agg(l), '[]'::jsonb) INTO v_owed FROM jsonb_array_elements(v_post -> 'lines') l WHERE l ->> 'account' LIKE 'liability:%';
  END IF;
  PERFORM set_config('trivia_ledger.writer', 'on', true);
  -- participants: payout/refund/lost, rank and rake share (largest remainder by entry, ties by user id), ONE update each
  SELECT COALESCE(sum(pp.entry_amount), 0) INTO v_settled_entries
    FROM public.trivia_settlement_participants pp
   WHERE pp.settlement_id = s.id AND pp.state = 'held'
     AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(p_plan -> 'refunds', '[]'::jsonb)) rf
                      WHERE rf.value ->> 'user_id' = pp.user_id::text);
  v_alloc := s.rake_amount + v_rake;
  WITH cls AS (
    SELECT pp.user_id, pp.entry_amount,
           CASE WHEN rf.value IS NOT NULL THEN 'refund' WHEN po.value IS NOT NULL THEN 'payout' ELSE 'lost' END AS kind,
           COALESCE((po.value ->> 'amount')::bigint, 0) AS amount,
           COALESCE((po.value ->> 'rank')::integer, (rs.value ->> 'rank')::integer) AS rank, rs.value AS res
      FROM public.trivia_settlement_participants pp
      LEFT JOIN LATERAL (SELECT value FROM jsonb_array_elements(COALESCE(p_plan -> 'payouts', '[]'::jsonb))
                          WHERE value ->> 'user_id' = pp.user_id::text LIMIT 1) po ON true
      LEFT JOIN LATERAL (SELECT value FROM jsonb_array_elements(COALESCE(p_plan -> 'refunds', '[]'::jsonb))
                          WHERE value ->> 'user_id' = pp.user_id::text LIMIT 1) rf ON true
      LEFT JOIN LATERAL (SELECT value FROM jsonb_array_elements(COALESCE(p_plan -> 'results', '[]'::jsonb))
                          WHERE value ->> 'user_id' = pp.user_id::text LIMIT 1) rs ON true
     WHERE pp.settlement_id = s.id AND pp.state = 'held'),
  shares AS (
    SELECT c.*,
           CASE WHEN c.kind = 'refund' OR v_settled_entries = 0 THEN NULL ELSE (v_alloc * c.entry_amount) / v_settled_entries END AS base_share,
           CASE WHEN c.kind = 'refund' OR v_settled_entries = 0 THEN NULL ELSE (v_alloc * c.entry_amount) % v_settled_entries END AS rem
      FROM cls c),
  ranked AS (
    SELECT sh.*, row_number() OVER (PARTITION BY (sh.kind = 'refund') ORDER BY sh.rem DESC NULLS LAST, sh.user_id) AS rn,
           v_alloc - COALESCE(sum(sh.base_share) OVER (), 0) AS leftover
      FROM shares sh)
  UPDATE public.trivia_settlement_participants tp
     SET state = CASE WHEN rk.kind = 'refund' THEN 'refunded' ELSE 'settled' END,
         payout_amount = rk.amount,
         refund_amount = CASE WHEN rk.kind = 'refund' THEN tp.entry_amount ELSE 0 END,
         rake_share = CASE WHEN rk.base_share IS NULL THEN NULL ELSE rk.base_share + CASE WHEN rk.rn <= rk.leftover THEN 1 ELSE 0 END END,
         net_contribution = CASE WHEN rk.base_share IS NULL THEN NULL
                                 ELSE tp.entry_amount - (rk.base_share + CASE WHEN rk.rn <= rk.leftover THEN 1 ELSE 0 END) END,
         final_rank = rk.rank, result = rk.res, exit_journal_id = v_journal
    FROM ranked rk
   WHERE tp.settlement_id = s.id AND tp.user_id = rk.user_id;
  -- escrow must be exactly zero and is closed for good
  UPDATE public.trivia_ledger_accounts SET state = 'closed', closed_at = clock_timestamp(), closed_by_journal_id = v_journal
   WHERE account_code = s.escrow_account_code AND balance = 0 AND state = 'open';
  IF NOT FOUND THEN
    PERFORM public.trivia_ledger_raise('escrow_not_zero_at_terminal', jsonb_build_object('escrow_account', s.escrow_account_code));
  END IF;
  v_result := jsonb_build_object('success', true, 'replayed', false, 'settlement_id', s.id, 'subject_type', p_subject_type,
    'subject_id', p_subject_id, 'idempotency_key', s.idempotency_key, 'journal_id', v_journal, 'state', v_terminal,
    'outcome', v_outcome, 'gross_pool', s.gross_pool, 'subsidy_total', s.subsidy_total, 'rake', s.rake_amount + v_rake,
    'final_prize_pool', v_pay, 'paid_total', v_pay, 'refunded_total', s.refunded_total + v_ref, 'escrow_balance', 0,
    'owed', v_owed, 'lines', COALESCE(v_post -> 'lines', '[]'::jsonb));
  UPDATE public.trivia_settlements
     SET state = v_terminal, outcome = v_outcome, rake_amount = rake_amount + v_rake, paid_total = v_pay,
         refunded_total = refunded_total + v_ref, final_prize_pool = v_pay, plan = p_plan, plan_hash = v_hash,
         result = v_result, settlement_journal_id = v_journal, terminal_at = clock_timestamp()
   WHERE id = s.id;
  INSERT INTO public.trivia_settlement_events (settlement_id, event, from_state, to_state, detail)
  VALUES (s.id, 'settle', 'locked', v_terminal, jsonb_build_object('outcome', v_outcome, 'journal_id', v_journal,
          'rake', v_rake, 'paid', v_pay, 'refunded', v_ref, 'owed', jsonb_array_length(v_owed)));
  PERFORM set_config('trivia_ledger.writer', '', true);
  RETURN v_result;
END $_$;


ALTER FUNCTION public.trivia_settlement_settle(p_subject_type text, p_subject_id uuid, p_plan jsonb) OWNER TO postgres;

--
-- TOC entry 4401 (class 1255 OID 74431283)
-- Name: trivia_settlement_status(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_settlement_status(p_subject_type text, p_subject_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN s.id IS NULL THEN jsonb_build_object('success', false, 'error', 'settlement_not_found')
         ELSE jsonb_build_object('success', true, 'settlement_id', s.id, 'state', s.state, 'outcome', s.outcome,
           'rules_version_id', s.rules_version_id, 'idempotency_key', s.idempotency_key, 'gross_pool', s.gross_pool,
           'held_total', s.held_total, 'subsidy_total', s.subsidy_total, 'released_total', s.released_total,
           'refunded_total', s.refunded_total, 'rake', s.rake_amount, 'final_prize_pool', s.final_prize_pool,
           'paid_total', s.paid_total, 'escrow_balance', a.balance, 'escrow_state', a.state,
           'opened_at', s.opened_at, 'locked_at', s.locked_at, 'terminal_at', s.terminal_at,
           'participants', (SELECT COALESCE(jsonb_agg(jsonb_build_object('user_id', p.user_id, 'participant_kind', p.participant_kind,
               'funding_source', p.funding_source, 'entry_amount', p.entry_amount, 'state', p.state, 'rake_share', p.rake_share,
               'net_contribution', p.net_contribution, 'payout_amount', p.payout_amount, 'refund_amount', p.refund_amount,
               'final_rank', p.final_rank, 'hold_reference', p.hold_reference) ORDER BY p.created_at, p.user_id), '[]'::jsonb)
             FROM public.trivia_settlement_participants p WHERE p.settlement_id = s.id)) END
    FROM (SELECT 1) one
    LEFT JOIN public.trivia_settlements s ON s.subject_type = p_subject_type AND s.subject_id = p_subject_id
    LEFT JOIN public.trivia_ledger_accounts a ON a.account_code = s.escrow_account_code;
$$;


ALTER FUNCTION public.trivia_settlement_status(p_subject_type text, p_subject_id uuid) OWNER TO postgres;

--
-- TOC entry 6223 (class 1255 OID 74743790)
-- Name: trivia_sha256_hex_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_sha256_hex_v1(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
    SELECT encode(extensions.digest(convert_to(p_text, 'UTF8'), 'sha256'), 'hex')
$$;


ALTER FUNCTION public.trivia_sha256_hex_v1(p_text text) OWNER TO postgres;

--
-- TOC entry 9440 (class 1255 OID 74744062)
-- Name: trivia_shadow_compare_v1(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_shadow_compare_v1(p_user_id uuid, p_mode text, p_legacy_question_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_profile text := 'solo.' || p_mode || '/roster@1'; v_n integer; v_inel integer; v_lseen integer;
        v_v3 integer; v_v3seen integer; v_detail jsonb; v_id uuid;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.trivia_roster_profiles WHERE profile_id = v_profile) THEN
        RETURN jsonb_build_object('success', false, 'error', 'unknown_profile');
    END IF;
    SELECT question_count INTO v_n FROM public.trivia_roster_profiles WHERE profile_id = v_profile;
    SELECT count(*) INTO v_inel FROM unnest(coalesce(p_legacy_question_ids, '{}'::uuid[])) x(id)
     WHERE NOT EXISTS (SELECT 1 FROM public.trivia_eligible_question_pool_v1 p WHERE p.question_id = x.id AND p_mode = ANY (p.modes));
    SELECT count(*) INTO v_lseen FROM unnest(coalesce(p_legacy_question_ids, '{}'::uuid[])) x(id)
      JOIN public.trivia_question_curation c ON c.question_id = x.id
     WHERE EXISTS (SELECT 1 FROM public.trivia_user_question_history h
                     JOIN public.trivia_question_curation hc ON hc.question_id = h.question_id
                    WHERE h.user_id = p_user_id AND hc.canonical_question_id = c.canonical_question_id
                      AND h.seen_at > now() - interval '60 days' AND h.seen_at < now() - interval '2 minutes');
    SELECT count(*), count(*) FILTER (WHERE tier = 2),
           jsonb_build_object('categories', jsonb_object_agg(category, n), 'v3_tiers', jsonb_object_agg('t' || tier, tn))
      INTO v_v3, v_v3seen, v_detail
      FROM (SELECT s.*, count(*) OVER (PARTITION BY s.category) n, count(*) OVER (PARTITION BY s.tier) tn
              FROM public.trivia_select_core_v1(public.trivia_engine_secret_v1('roster-v1'),
                   'shadow:' || gen_random_uuid()::text, v_profile, v_n, ARRAY[p_user_id], '{}'::uuid[], now()) s) z;
    INSERT INTO public.trivia_shadow_selector_runs (mode, legacy_count, legacy_ineligible, legacy_seen, v3_count, v3_seen, v3_ok, detail)
    VALUES (p_mode, coalesce(cardinality(p_legacy_question_ids), 0), v_inel, v_lseen, v_v3, v_v3seen, v_v3 >= v_n, coalesce(v_detail, '{}'))
    RETURNING id INTO v_id;
    RETURN jsonb_build_object('success', true, 'run_id', v_id, 'legacy_ineligible', v_inel, 'legacy_seen', v_lseen,
        'v3_count', v_v3, 'v3_seen', v_v3seen, 'v3_ok', v_v3 >= v_n);
END $$;


ALTER FUNCTION public.trivia_shadow_compare_v1(p_user_id uuid, p_mode text, p_legacy_question_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 8334 (class 1255 OID 74439692)
-- Name: trivia_solo_add_shape(jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_solo_add_shape(p_result jsonb, p_user_id uuid, p_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_after integer; v_now integer; v_receipt jsonb;
BEGIN
  IF COALESCE((p_result ->> 'success')::boolean, false) AND NOT COALESCE((p_result ->> 'replayed')::boolean, false) THEN
    v_receipt := public.trivia_solo_wallet_receipt(p_result);
    IF v_receipt IS NULL OR COALESCE((v_receipt ->> 'success')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'trivia ledger: platform receipt missing for journal %', p_result ->> 'journal_id' USING ERRCODE = 'TL003';
    END IF;
    RETURN v_receipt;
  END IF;
  SELECT balance_after INTO v_after FROM public.diamond_transactions WHERE user_id = p_user_id AND reference_id = p_reference;
  IF COALESCE((p_result ->> 'replayed')::boolean, false)
     OR p_result ->> 'error' IN ('reference_already_used_outside_ledger', 'idempotency_conflict') THEN
    -- exactly what add_diamonds_to_balance answers for a reference it has already seen
    RETURN jsonb_build_object('success', false, 'error', 'duplicate_reference', 'duplicate', true, 'new_balance', v_after);
  END IF;
  SELECT diamonds INTO v_now FROM public.profiles WHERE id = p_user_id;
  IF p_result ->> 'error' = 'insufficient_funds' THEN
    RETURN jsonb_build_object('success', false, 'error', 'insufficient_diamonds', 'new_balance', v_now);
  END IF;
  RETURN jsonb_build_object('success', false, 'error', COALESCE(p_result ->> 'error', 'ledger_error'), 'ledger', p_result);
END $$;


ALTER FUNCTION public.trivia_solo_add_shape(p_result jsonb, p_user_id uuid, p_reference text) OWNER TO postgres;

--
-- TOC entry 5356 (class 1255 OID 115338738)
-- Name: trivia_solo_answer_v1(uuid, uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_solo_answer_v1(p_session_id uuid, p_user_id uuid, p_question_id uuid, p_display_index integer, p_client_nonce uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    s public.trivia_sessions%ROWTYPE;
    a public.trivia_session_answers%ROWTYPE;
    v_status jsonb;
    v_answer jsonb;
    v_position integer;
    v_expected_position integer;
    v_prior_question_id uuid;
BEGIN
    IF p_session_id IS NULL OR p_user_id IS NULL OR p_question_id IS NULL
       OR p_display_index IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
    END IF;
    SELECT * INTO s FROM public.trivia_sessions WHERE id = p_session_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'session_not_found'); END IF;
    IF s.user_id IS DISTINCT FROM p_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_your_session');
    END IF;

    -- Duplicate requests replay before the run boundary. In particular, the
    -- third miss remains retryable while every genuinely new answer is closed.
    IF s.engine_version IS NOT NULL THEN
        SELECT * INTO a FROM public.trivia_session_answers
         WHERE session_id = s.id AND question_id = p_question_id FOR UPDATE;
        IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'question_not_in_session'); END IF;
        IF a.outcome IS NOT NULL OR a.server_voided_at IS NOT NULL THEN
            v_answer := public.trivia_session_answer_before_phase9_v4(
                s.id, p_user_id, p_question_id, p_display_index, p_client_nonce);
            IF s.mode NOT IN ('endless','survival') THEN RETURN v_answer; END IF;
            v_status := public.trivia_solo_miss_status_v1(s.id, p_user_id);
            IF coalesce((v_status ->> 'success')::boolean, false) IS NOT TRUE THEN RETURN v_status; END IF;
            RETURN v_answer || jsonb_build_object(
                'nonPaidMissCount', (v_status ->> 'nonPaidMissCount')::integer,
                'terminalFailureCount', (v_status ->> 'terminalFailureCount')::integer,
                'missLimit', (v_status ->> 'missLimit')::integer,
                'runMissLimitReached', coalesce((v_status ->> 'runMissLimitReached')::boolean, false));
        END IF;
    ELSIF coalesce(s.answers, '{}'::jsonb) ? p_question_id::text THEN
        v_answer := public.trivia_legacy_session_answer_before_phase9_v1(
            s.id, p_user_id, p_question_id, p_display_index, p_client_nonce);
        IF s.mode NOT IN ('endless','survival') THEN RETURN v_answer; END IF;
        v_status := public.trivia_solo_miss_status_v1(s.id, p_user_id);
        IF coalesce((v_status ->> 'success')::boolean, false) IS NOT TRUE THEN RETURN v_status; END IF;
        RETURN v_answer || jsonb_build_object(
            'nonPaidMissCount', (v_status ->> 'nonPaidMissCount')::integer,
            'terminalFailureCount', (v_status ->> 'terminalFailureCount')::integer,
            'missLimit', (v_status ->> 'missLimit')::integer,
            'runMissLimitReached', coalesce((v_status ->> 'runMissLimitReached')::boolean, false));
    END IF;

    -- Untimed Endless/Survival profiles have no authoritative per-question
    -- deadline. Therefore a missing earlier answer cannot honestly be
    -- synthesized as a timeout. Refuse later positions until the exact prior
    -- answer/timeout (-1) is durably bound; this makes lost timeout writes
    -- retryable instead of invisible to settlement authority.
    IF s.mode IN ('endless','survival') THEN
        IF s.engine_version IS NOT NULL THEN
            SELECT prior.position, prior.question_id
              INTO v_expected_position, v_prior_question_id
              FROM public.trivia_session_answers prior
             WHERE prior.session_id = s.id
               AND prior.position < a.position
               AND prior.outcome IS NULL
               AND prior.server_voided_at IS NULL
             ORDER BY prior.position
             LIMIT 1;
        ELSE
            v_position := array_position(s.question_ids, p_question_id);
            IF v_position IS NULL THEN
                RETURN jsonb_build_object('success', false, 'error', 'question_not_in_session');
            END IF;
            SELECT position, s.question_ids[position]
              INTO v_expected_position, v_prior_question_id
              FROM generate_subscripts(s.question_ids, 1) position
             WHERE position < v_position
               AND NOT (coalesce(s.answers, '{}'::jsonb) ? s.question_ids[position]::text)
             ORDER BY position
             LIMIT 1;
        END IF;
        IF v_expected_position IS NOT NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'position_out_of_order',
                'expectedPosition', v_expected_position,
                'priorQuestionId', v_prior_question_id);
        END IF;
    END IF;

    IF s.mode IN ('endless','survival') THEN
        v_status := public.trivia_solo_miss_status_v1(s.id, p_user_id);
        IF coalesce((v_status ->> 'success')::boolean, false) IS NOT TRUE THEN
            RETURN v_status;
        END IF;
        -- The status pass can durably neutralize a newly invalid question.
        -- Replay that neutral result before applying the player-miss boundary.
        IF s.engine_version IS NOT NULL THEN
            SELECT * INTO a FROM public.trivia_session_answers
             WHERE session_id = s.id AND question_id = p_question_id FOR UPDATE;
            IF a.outcome IS NOT NULL OR a.server_voided_at IS NOT NULL THEN
                v_answer := public.trivia_session_answer_before_phase9_v4(
                    s.id, p_user_id, p_question_id, p_display_index, p_client_nonce);
                RETURN v_answer || jsonb_build_object(
                    'nonPaidMissCount', (v_status ->> 'nonPaidMissCount')::integer,
                    'terminalFailureCount', (v_status ->> 'terminalFailureCount')::integer,
                    'missLimit', (v_status ->> 'missLimit')::integer,
                    'runMissLimitReached', coalesce((v_status ->> 'runMissLimitReached')::boolean, false));
            END IF;
        ELSIF (SELECT answers FROM public.trivia_sessions WHERE id = s.id) ? p_question_id::text THEN
            v_answer := public.trivia_legacy_session_answer_before_phase9_v1(
                s.id, p_user_id, p_question_id, p_display_index, p_client_nonce);
            RETURN v_answer || jsonb_build_object(
                'nonPaidMissCount', (v_status ->> 'nonPaidMissCount')::integer,
                'terminalFailureCount', (v_status ->> 'terminalFailureCount')::integer,
                'missLimit', (v_status ->> 'missLimit')::integer,
                'runMissLimitReached', coalesce((v_status ->> 'runMissLimitReached')::boolean, false));
        END IF;
        IF coalesce((v_status ->> 'runMissLimitReached')::boolean, false) IS TRUE THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'run_miss_limit_reached',
                'nonPaidMissCount', (v_status ->> 'nonPaidMissCount')::integer,
                'terminalFailureCount', (v_status ->> 'terminalFailureCount')::integer,
                'missLimit', (v_status ->> 'missLimit')::integer,
                'runMissLimitReached', true
            );
        END IF;
    END IF;

    IF s.engine_version IS NOT NULL THEN
        v_answer := public.trivia_session_answer_before_phase9_v4(
            s.id, p_user_id, p_question_id, p_display_index, p_client_nonce);
    ELSE
        v_answer := public.trivia_legacy_session_answer_before_phase9_v1(
            s.id, p_user_id, p_question_id, p_display_index, p_client_nonce);
    END IF;
    IF s.mode NOT IN ('endless','survival') THEN
        RETURN v_answer;
    END IF;
    IF coalesce((v_answer ->> 'success')::boolean, false) IS NOT TRUE
       AND coalesce((v_answer ->> 'recorded')::boolean, false) IS NOT TRUE THEN
        RETURN v_answer;
    END IF;
    v_status := public.trivia_solo_miss_status_v1(s.id, p_user_id);
    IF coalesce((v_status ->> 'success')::boolean, false) IS NOT TRUE THEN RETURN v_status; END IF;
    RETURN v_answer || jsonb_build_object(
        'nonPaidMissCount', (v_status ->> 'nonPaidMissCount')::integer,
        'terminalFailureCount', (v_status ->> 'terminalFailureCount')::integer,
        'missLimit', (v_status ->> 'missLimit')::integer,
        'runMissLimitReached', coalesce((v_status ->> 'runMissLimitReached')::boolean, false));
END;
$$;


ALTER FUNCTION public.trivia_solo_answer_v1(p_session_id uuid, p_user_id uuid, p_question_id uuid, p_display_index integer, p_client_nonce uuid) OWNER TO postgres;

--
-- TOC entry 9583 (class 1255 OID 74439695)
-- Name: trivia_solo_charge_entry(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_solo_charge_entry(p_session_id uuid, p_user_id uuid, p_mode text, p_cost integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_rules text; v_ref text := 'trivia_entry_' || p_session_id::text;
BEGIN
  IF NOT public.trivia_ledger_switch_enabled('solo_journal') THEN
    RETURN public.add_diamonds_to_balance(p_user_id, -p_cost, 'trivia_entry', 'Trivia entry (' || p_mode || ')', v_ref);
  END IF;
  SELECT rules_version_id INTO v_rules FROM public.trivia_rules_current WHERE rules_key = public.trivia_rules_key_for_mode(p_mode);
  RETURN public.trivia_solo_add_shape(
    public.trivia_ledger_debit(v_ref, p_user_id, p_cost, 'trivia_entry', 'Trivia entry (' || p_mode || ')',
                               'trivia_session', p_session_id::text, v_rules),
    p_user_id, v_ref);
END $$;


