--
-- TOC entry 6835 (class 1255 OID 74744038)
-- Name: trivia_start_solo_session_v3(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_start_solo_session_v3(p_session_id uuid, p_user_id uuid, p_mode text, p_parent_session_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_profile text; s public.trivia_sessions%ROWTYPE; v_snap jsonb; v_snapshot_id uuid; v_kind text; v_scope text;
    v_players uuid[]; v_created jsonb; v_actor text;
BEGIN
    IF p_session_id IS NULL OR p_user_id IS NULL OR p_mode IS NULL OR p_mode NOT IN ('daily','history','rules','pro',
       'arcade','mtt','cash','icm','gto','mixed','survival','endless','time-attack') THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_mode');
    END IF;
    v_profile := 'solo.' || p_mode || '/roster@1';
    PERFORM pg_advisory_xact_lock(hashtextextended('trivia_session:' || p_session_id::text, 0));
    SELECT * INTO s FROM public.trivia_sessions WHERE id = p_session_id;
    IF FOUND THEN
        IF s.user_id = p_user_id AND s.mode = p_mode AND s.engine_version IS NOT NULL THEN
            RETURN public.trivia_session_view_v3(p_session_id, p_user_id)
                || jsonb_build_object('resumed', true, 'duplicate', true);
        END IF;
        RETURN jsonb_build_object('success', false, 'error', 'session_id_conflict');
    END IF;
    SELECT CASE WHEN coalesce(p.is_horse, false) THEN 'horse' ELSE 'human' END INTO v_actor
      FROM public.profiles p WHERE p.id = p_user_id;
    IF v_actor IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'profile_not_found'); END IF;
    IF p_mode = 'daily' THEN
        -- Daily's promise: every player answers the SAME questions that Chicago day.
        v_kind := 'daily'; v_scope := ((now() AT TIME ZONE 'America/Chicago')::date)::text; v_players := '{}'::uuid[];
    ELSE
        v_kind := 'solo_session'; v_scope := p_session_id::text; v_players := ARRAY[p_user_id];
    END IF;
    v_snap := public.trivia_build_roster_v1(v_kind, v_scope, v_profile, v_players, '{}'::uuid[]);
    IF (v_snap ->> 'success')::boolean IS NOT TRUE THEN RETURN v_snap; END IF;
    v_snapshot_id := (v_snap ->> 'snapshot_id')::uuid;
    v_created := public.create_trivia_session_v2(p_session_id, p_user_id, p_mode,
        ARRAY(SELECT question_id FROM public.trivia_roster_snapshot_items WHERE snapshot_id = v_snapshot_id
               AND round_no = 1 ORDER BY position),
        public.trivia_p3_permutations(v_snapshot_id, 1, p_session_id), p_parent_session_id);
    IF coalesce((v_created ->> 'success')::boolean, false) IS NOT TRUE THEN RETURN v_created; END IF;
    IF coalesce((v_created ->> 'duplicate')::boolean, false) THEN
        RETURN jsonb_build_object('success', false, 'error', 'session_id_conflict');
    END IF;
    PERFORM public.trivia_p3_bind_session(p_session_id, v_snapshot_id, 1, v_profile, 'solo:' || p_session_id::text,
        v_actor, jsonb_build_object('entry_cost', v_created -> 'entry_cost', 'entry_state', v_created -> 'entry_state'));
    RETURN public.trivia_session_view_v3(p_session_id, p_user_id)
        || jsonb_build_object('resumed', false, 'duplicate', false, 'newBalance', v_created -> 'new_balance',
                              'survivalLevel', v_created -> 'survival_level');
END $$;


ALTER FUNCTION public.trivia_start_solo_session_v3(p_session_id uuid, p_user_id uuid, p_mode text, p_parent_session_id uuid) OWNER TO postgres;

--
-- TOC entry 4821 (class 1255 OID 74719984)
-- Name: trivia_submit_question_report_v1(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_submit_question_report_v1(p_user_id uuid, p_question_id uuid, p_reason text, p_note text DEFAULT NULL::text, p_session_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    v_existing uuid;
    v_canon uuid;
    v_rev uuid;
    v_established boolean;
    v_served boolean;
    v_valid boolean;
    v_session uuid;
    v_id uuid;
    v_threshold integer;
    v_reporters integer;
    v_quarantined boolean := false;
BEGIN
    IF p_user_id IS NULL OR p_question_id IS NULL
       OR p_reason NOT IN ('wrong_answer','unclear','duplicate','offensive','broken','other') THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
    END IF;
    IF p_note IS NOT NULL AND length(p_note) > 500 THEN
        RETURN jsonb_build_object('success', false, 'error', 'note_too_long');
    END IF;
    SELECT c.canonical_question_id, c.current_revision_id INTO v_canon, v_rev
      FROM public.trivia_question_curation c WHERE c.question_id = p_question_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'question_not_found'); END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('trivia_report:' || p_user_id::text, 0));

    SELECT id INTO v_existing FROM public.trivia_question_reports
     WHERE user_id = p_user_id AND question_id = p_question_id AND state IN ('open','triaged') LIMIT 1;
    IF v_existing IS NOT NULL THEN
        RETURN jsonb_build_object('success', true, 'duplicate', true, 'report_id', v_existing);
    END IF;
    IF (SELECT count(*) FROM public.trivia_question_reports
         WHERE user_id = p_user_id AND created_at > now() - interval '24 hours') >= 10 THEN
        RETURN jsonb_build_object('success', false, 'error', 'daily_report_limit');
    END IF;
    IF (SELECT count(*) FROM public.trivia_question_reports
         WHERE user_id = p_user_id AND state IN ('open','triaged')) >= 25 THEN
        RETURN jsonb_build_object('success', false, 'error', 'open_report_limit');
    END IF;

    SELECT (p.created_at < now() - interval '24 hours') AND coalesce(p.is_horse, false) IS FALSE
      INTO v_established FROM public.profiles p WHERE p.id = p_user_id;
    v_established := coalesce(v_established, false);
    v_served := EXISTS (SELECT 1 FROM public.trivia_user_question_history h
                          JOIN public.trivia_question_curation c ON c.question_id = h.question_id
                         WHERE h.user_id = p_user_id AND c.canonical_question_id = v_canon)
             OR EXISTS (SELECT 1 FROM public.trivia_sessions s
                         WHERE s.user_id = p_user_id AND s.question_ids && ARRAY(
                               SELECT question_id FROM public.trivia_question_curation WHERE canonical_question_id = v_canon));
    v_valid := v_established AND v_served;
    IF p_session_id IS NOT NULL THEN
        SELECT id INTO v_session FROM public.trivia_sessions WHERE id = p_session_id AND user_id = p_user_id;
    END IF;

    INSERT INTO public.trivia_question_reports (question_id, user_id, reason, note, state, valid, session_id,
        revision_id, reporter_established, served_to_reporter)
    VALUES (p_question_id, p_user_id, p_reason, nullif(btrim(coalesce(p_note, '')), ''), 'open', v_valid,
        v_session, v_rev, v_established, v_served)
    RETURNING id INTO v_id;

    IF v_valid THEN
        SELECT report_quarantine_threshold INTO v_threshold FROM public.trivia_eligibility_policies
         ORDER BY policy_version DESC LIMIT 1;
        SELECT count(DISTINCT r.user_id) INTO v_reporters
          FROM public.trivia_question_reports r
          JOIN public.trivia_question_curation c ON c.question_id = r.question_id
         WHERE c.canonical_question_id = v_canon AND r.state IN ('open','triaged') AND r.valid;
        IF v_reporters >= coalesce(v_threshold, 3) THEN
            PERFORM public.trivia_quarantine_question_v1(v_canon, 'reports_threshold', 'report_threshold',
                'trivia_submit_question_report_v1', jsonb_build_object('valid_reporters', v_reporters));
            v_quarantined := true;
        END IF;
    END IF;
    RETURN jsonb_build_object('success', true, 'duplicate', false, 'report_id', v_id, 'valid', v_valid,
        'excluded_from_paid_pools', v_valid, 'quarantined', v_quarantined);
END $$;


ALTER FUNCTION public.trivia_submit_question_report_v1(p_user_id uuid, p_question_id uuid, p_reason text, p_note text, p_session_id uuid) OWNER TO postgres;

--
-- TOC entry 6495 (class 1255 OID 110225997)
-- Name: trivia_submit_question_report_v2(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_submit_question_report_v2(p_user_id uuid, p_question_id uuid, p_reason text, p_note text DEFAULT NULL::text, p_session_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    s public.trivia_sessions%ROWTYPE;
    v_existing uuid;
    v_canon uuid;
    v_rev uuid;
    v_established boolean;
    v_valid boolean;
    v_id uuid;
    v_threshold integer;
    v_reporters integer;
    v_quarantined boolean := false;
BEGIN
    IF p_user_id IS NULL OR p_question_id IS NULL OR p_reason IS NULL
       OR p_reason NOT IN ('wrong_answer','unclear','duplicate','offensive','broken','other') THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
    END IF;
    IF p_note IS NOT NULL AND length(p_note) > 500 THEN
        RETURN jsonb_build_object('success', false, 'error', 'note_too_long');
    END IF;
    IF p_session_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'session_required');
    END IF;
    SELECT * INTO s FROM public.trivia_sessions WHERE id = p_session_id FOR SHARE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'session_not_found'); END IF;
    IF s.user_id IS DISTINCT FROM p_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_your_session');
    END IF;
    IF array_position(s.question_ids, p_question_id) IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'question_not_in_session');
    END IF;

    -- A report is evidence about the exact served question and immutable
    -- revision. Canonical siblings and the mutable current revision are never
    -- accepted as substitutes; canonical identity is used only for threshold
    -- serialization and serving exclusion.
    IF s.engine_version IS NOT NULL THEN
        SELECT a.revision_id INTO v_rev
          FROM public.trivia_session_answers a
         WHERE a.session_id = s.id AND a.question_id = p_question_id;
    ELSE
        BEGIN
            v_rev := (s.question_revision_ids ->> p_question_id::text)::uuid;
        EXCEPTION WHEN invalid_text_representation THEN
            v_rev := NULL;
        END;
    END IF;
    IF v_rev IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.trivia_question_revisions r
         WHERE r.id = v_rev AND r.question_id = p_question_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'revision_provenance_unavailable');
    END IF;
    SELECT c.canonical_question_id INTO v_canon
      FROM public.trivia_question_curation c
     WHERE c.question_id = p_question_id
     FOR SHARE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'question_not_found'); END IF;

    -- One reporter cannot race their limits, and one canonical question cannot
    -- race its quarantine threshold across aliases or simultaneous reporters.
    PERFORM pg_advisory_xact_lock(hashtextextended('trivia_report_user:' || p_user_id::text, 0));
    PERFORM pg_advisory_xact_lock(hashtextextended('trivia_report_canonical:' || v_canon::text, 0));
    SELECT id INTO v_existing FROM public.trivia_question_reports
     WHERE user_id = p_user_id AND question_id = p_question_id AND state IN ('open','triaged') LIMIT 1;
    IF v_existing IS NOT NULL THEN
        RETURN jsonb_build_object('success', true, 'duplicate', true, 'report_id', v_existing);
    END IF;
    IF (SELECT count(*) FROM public.trivia_question_reports
         WHERE user_id = p_user_id AND created_at > now() - interval '24 hours') >= 10 THEN
        RETURN jsonb_build_object('success', false, 'error', 'daily_report_limit');
    END IF;
    IF (SELECT count(*) FROM public.trivia_question_reports
         WHERE user_id = p_user_id AND state IN ('open','triaged')) >= 25 THEN
        RETURN jsonb_build_object('success', false, 'error', 'open_report_limit');
    END IF;

    -- Horses are players: reporter establishment is based on account age, not
    -- actor type. Browser/API authentication remains the gate to this RPC.
    SELECT (p.created_at < now() - interval '24 hours')
      INTO v_established FROM public.profiles p WHERE p.id = p_user_id;
    v_established := coalesce(v_established, false);
    v_valid := v_established;

    INSERT INTO public.trivia_question_reports (question_id, user_id, reason, note, state, valid, session_id,
        revision_id, reporter_established, served_to_reporter)
    VALUES (p_question_id, p_user_id, p_reason, nullif(btrim(coalesce(p_note, '')), ''), 'open', v_valid,
        s.id, v_rev, v_established, true)
    RETURNING id INTO v_id;

    IF v_valid THEN
        SELECT report_quarantine_threshold INTO v_threshold FROM public.trivia_eligibility_policies
         ORDER BY policy_version DESC LIMIT 1;
        SELECT count(DISTINCT r.user_id) INTO v_reporters
          FROM public.trivia_question_reports r
          JOIN public.trivia_question_curation c ON c.question_id = r.question_id
         WHERE c.canonical_question_id = v_canon AND r.state IN ('open','triaged') AND r.valid;
        IF v_reporters >= coalesce(v_threshold, 3) THEN
            PERFORM public.trivia_quarantine_question_v1(v_canon, 'reports_threshold', 'report_threshold',
                'trivia_submit_question_report_v2', jsonb_build_object('valid_reporters', v_reporters));
            v_quarantined := true;
        END IF;
    END IF;
    RETURN jsonb_build_object('success', true, 'duplicate', false, 'report_id', v_id, 'valid', v_valid,
        'excluded_from_paid_pools', v_valid, 'quarantined', v_quarantined);
END $$;


ALTER FUNCTION public.trivia_submit_question_report_v2(p_user_id uuid, p_question_id uuid, p_reason text, p_note text, p_session_id uuid) OWNER TO postgres;

--
-- TOC entry 5004 (class 1255 OID 107657943)
-- Name: trivia_tournament_admit(uuid, uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_tournament_admit(p_tournament_id uuid, p_participant_id uuid, p_kind text, p_client_nonce text, p_fencing_token bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    t public.trivia_tournaments%ROWTYPE;
    e public.trivia_tournament_entrants%ROWTYPE;
    f jsonb;
    v_now timestamptz := public.trivia_tournament_clock();
    v_humans integer;
    v_horses integer;
    v_fee integer;
    v_rake integer;
    v_ref text;
    v_name text;
    v_res jsonb;
    v_journal uuid;
    v_id uuid;
BEGIN
    IF p_kind NOT IN ('human', 'horse') THEN
        RAISE EXCEPTION 'trivia_p6: invalid participant kind %', p_kind;
    END IF;
    SELECT * INTO t FROM public.trivia_tournaments WHERE id = p_tournament_id;
    f := t.format_snapshot;
    SELECT * INTO e FROM public.trivia_tournament_entrants
     WHERE tournament_id = t.id AND participant_id = p_participant_id;
    IF FOUND THEN
        RETURN jsonb_build_object('success', true, 'duplicate', true, 'entrant_id', e.id,
                                  'entry_reference', e.entry_reference, 'entry_state', e.entry_state,
                                  'entry_fee', e.entry_fee);
    END IF;
    SELECT count(*) FILTER (WHERE participant_kind = 'human'),
           count(*) FILTER (WHERE participant_kind = 'horse')
      INTO v_humans, v_horses
      FROM public.trivia_tournament_entrants
     WHERE tournament_id = t.id AND entry_state = 'entered';
    IF p_kind = 'human' THEN
        -- Humans are additive, but never into the horse reserve.
        IF v_humans >= t.bracket_capacity - t.horse_target
           AND COALESCE((f->>'auto_expand_capacity')::boolean, false)
           AND t.bracket_capacity < (f->>'bracket_capacity_max')::integer THEN
            UPDATE public.trivia_tournaments
               SET bracket_capacity = (f->>'bracket_capacity_max')::integer,
                   last_fencing_token = COALESCE(p_fencing_token, last_fencing_token)
             WHERE id = t.id
            RETURNING * INTO t;
            PERFORM public.trivia_tournament_event(t.id, 'capacity_expanded',
                jsonb_build_object('bracket_capacity', t.bracket_capacity, 'humans', v_humans),
                NULL, NULL, NULL, p_fencing_token);
        END IF;
        IF v_humans >= t.bracket_capacity - t.horse_target THEN
            RETURN jsonb_build_object('success', false, 'error', 'tournament_full');
        END IF;
    ELSIF v_horses >= t.horse_target THEN
        RETURN jsonb_build_object('success', false, 'error', 'horse_target_reached');
    END IF;

    v_fee := COALESCE((f->>'entry_fee')::integer, 0);
    v_rake := CASE WHEN v_fee > 0
                   THEN GREATEST((f->>'rake_minimum')::integer,
                                 round(v_fee * (f->>'rake_rate_bp')::integer / 10000.0)::integer)
                   ELSE 0 END;
    v_ref := 'trivia_tourn_entry_' || t.id::text || '_' || p_participant_id::text;
    SELECT left(COALESCE(NULLIF(btrim(p.display_name), ''), NULLIF(btrim(p.username), ''), 'Player'), 80)
      INTO v_name FROM public.profiles AS p WHERE p.id = p_participant_id;
    IF v_name IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'profile_not_found');
    END IF;

    IF v_fee > 0 THEN
        IF p_kind = 'human' THEN
            v_res := public.trivia_ledger_hold(v_ref, 'tournament', t.id, p_participant_id, v_fee,
                'tournament_entry', 'Trivia Nightly entry - ' || t.name, 'human',
                jsonb_build_object('tournament_id', t.id, 'engine', t.engine_version));
        ELSE
            v_res := public.trivia_ledger_subsidy(v_ref, 'tournament', t.id, p_participant_id, v_fee,
                'horse_seat', jsonb_build_object('tournament_id', t.id, 'engine', t.engine_version));
        END IF;
        IF COALESCE((v_res->>'success')::boolean, false) IS NOT TRUE THEN
            RETURN jsonb_build_object('success', false, 'error', COALESCE(v_res->>'error', 'ledger_refused'),
                                      'ledger_detail', v_res->'detail');
        END IF;
        v_journal := NULLIF(v_res->>'journal_id', '')::uuid;
    END IF;

    INSERT INTO public.trivia_tournament_entrants (
        tournament_id, participant_id, participant_kind, display_name, entered_at, entry_reference,
        entry_fee, rake_amount, net_contribution, funding_source, ledger_journal_id, client_nonce, created_by)
    VALUES (t.id, p_participant_id, p_kind, v_name, v_now, v_ref, v_fee, v_rake, v_fee - v_rake,
            CASE WHEN v_fee = 0 THEN 'none' WHEN p_kind = 'human' THEN 'player_wallet' ELSE 'house_treasury' END,
            v_journal, p_client_nonce, CASE WHEN p_kind = 'human' THEN 'player' ELSE 'horse_population' END)
    RETURNING id INTO v_id;
    UPDATE public.trivia_tournaments SET current_players = current_players + 1 WHERE id = t.id;
    PERFORM public.trivia_tournament_event(t.id, 'entrant_admitted',
        jsonb_build_object('participant_kind', p_kind, 'entry_fee', v_fee, 'entry_reference', v_ref),
        v_id, NULL, NULL, p_fencing_token);
    RETURN jsonb_build_object('success', true, 'duplicate', false, 'entrant_id', v_id,
                              'entry_reference', v_ref, 'entry_fee', v_fee, 'journal_id', v_journal);
END;
$$;


ALTER FUNCTION public.trivia_tournament_admit(p_tournament_id uuid, p_participant_id uuid, p_kind text, p_client_nonce text, p_fencing_token bigint) OWNER TO postgres;

