--
-- TOC entry 6352 (class 1255 OID 107657931)
-- Name: trivia_tournament_assert_fence(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_tournament_assert_fence(p_fencing_token bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF p_fencing_token IS NULL THEN
        RAISE EXCEPTION 'stale_fencing_token' USING ERRCODE = 'P0001',
            DETAIL = 'a fencing token is required';
    END IF;
    PERFORM 1
      FROM public.trivia_tournament_scheduler_leases l
     WHERE l.job_identity = public.trivia_tournament_scheduler_job()
       AND l.fencing_token = p_fencing_token
       AND l.released_at IS NULL
       AND l.expires_at > public.trivia_tournament_clock()
       FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'stale_fencing_token' USING ERRCODE = 'P0001',
            DETAIL = 'another scheduler owns the nightly tournament lease';
    END IF;
    PERFORM public.trivia_tournament_engine_begin();
END;
$$;


ALTER FUNCTION public.trivia_tournament_assert_fence(p_fencing_token bigint) OWNER TO postgres;

--
-- TOC entry 6466 (class 1255 OID 107657961)
-- Name: trivia_tournament_bracket_order(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_tournament_bracket_order(p_size integer) RETURNS integer[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
    v integer[] := ARRAY[1];
    v_next integer[];
    v_n integer := 1;
    s integer;
BEGIN
    IF p_size IS NULL OR p_size NOT IN (2, 4, 8, 16, 32, 64, 128, 256, 512) THEN
        RAISE EXCEPTION 'bracket size must be a power of two between 2 and 512';
    END IF;
    WHILE v_n < p_size LOOP
        v_n := v_n * 2;
        v_next := ARRAY[]::integer[];
        FOREACH s IN ARRAY v LOOP
            v_next := v_next || s || (v_n + 1 - s);
        END LOOP;
        v := v_next;
    END LOOP;
    RETURN v;
END;
$$;


ALTER FUNCTION public.trivia_tournament_bracket_order(p_size integer) OWNER TO postgres;

--
-- TOC entry 7614 (class 1255 OID 107658012)
-- Name: trivia_tournament_bracket_v1(uuid, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_tournament_bracket_v1(p_tournament_id uuid, p_round integer DEFAULT 1, p_offset integer DEFAULT 0, p_limit integer DEFAULT 64) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
WITH params AS (
    SELECT GREATEST(COALESCE(p_offset, 0), 0) AS off, LEAST(GREATEST(COALESCE(p_limit, 64), 1), 256) AS lim,
           GREATEST(COALESCE(p_round, 1), 1) AS rnd
)
SELECT jsonb_build_object(
    'success', true,
    'roundNumber', (SELECT rnd FROM params),
    'bracketSize', (SELECT fs.bracket_size FROM public.trivia_tournament_field_snapshots fs WHERE fs.tournament_id = p_tournament_id),
    'roundCount', (SELECT fs.round_count FROM public.trivia_tournament_field_snapshots fs WHERE fs.tournament_id = p_tournament_id),
    'total', (SELECT count(*) FROM public.trivia_tournament_matchups m, params p
               WHERE m.tournament_id = p_tournament_id AND m.round_number = p.rnd),
    'offset', (SELECT off FROM params),
    'limit', (SELECT lim FROM params),
    'items', COALESCE((
        SELECT jsonb_agg(public.trivia_tournament_matchup_dto(x.id) ORDER BY x.slot)
          FROM (SELECT m.id, m.slot FROM public.trivia_tournament_matchups m, params p
                 WHERE m.tournament_id = p_tournament_id AND m.round_number = p.rnd
                 ORDER BY m.slot OFFSET (SELECT off FROM params) LIMIT (SELECT lim FROM params)) x), '[]'::jsonb))
$$;


ALTER FUNCTION public.trivia_tournament_bracket_v1(p_tournament_id uuid, p_round integer, p_offset integer, p_limit integer) OWNER TO postgres;

--
-- TOC entry 6318 (class 1255 OID 107936434)
-- Name: trivia_tournament_bracket_v2(uuid, uuid, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_tournament_bracket_v2(p_tournament_id uuid, p_user_id uuid DEFAULT NULL::uuid, p_round integer DEFAULT 1, p_offset integer DEFAULT 0, p_limit integer DEFAULT 64) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT CASE
        WHEN NOT public.trivia_tournament_visible_v1(p_tournament_id, p_user_id)
            THEN jsonb_build_object('success', false, 'error', 'tournament_not_found')
        ELSE public.trivia_tournament_bracket_v1(
            p_tournament_id, p_round, p_offset, p_limit)
    END
$$;


