--
-- TOC entry 6686 (class 1255 OID 107657987)
-- Name: trivia_tournament_cancel_core(uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_tournament_cancel_core(p_tournament_id uuid, p_reason text, p_fencing_token bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    t public.trivia_tournaments%ROWTYPE;
    v_now timestamptz := public.trivia_tournament_clock();
    v_refunds jsonb;
    v_plan jsonb;
    v_res jsonb;
    x record;
BEGIN
    PERFORM public.trivia_tournament_engine_begin();
    SELECT * INTO t FROM public.trivia_tournaments WHERE id = p_tournament_id FOR UPDATE;
    IF t.lifecycle_state IN ('settled', 'cancelled') THEN
        RETURN jsonb_build_object('cancelled', false, 'reason', 'terminal');
    END IF;
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'user_id', e.participant_id,
               'wallet_kind', 'tournament_cancel_refund',
               'reference', 'trivia_tourn_cancel_' || t.id::text || '_' || e.participant_id::text,
               'description', 'Trivia Nightly cancelled - entry returned') ORDER BY e.entered_at, e.id), '[]'::jsonb)
      INTO v_refunds
      FROM public.trivia_tournament_entrants e
     WHERE e.tournament_id = t.id AND e.entry_state = 'entered' AND e.entry_fee > 0;
    v_plan := jsonb_build_object('outcome', 'cancelled',
        'terminal_state', CASE WHEN jsonb_array_length(v_refunds) > 0 THEN 'refunded' ELSE 'voided' END,
        'rake', 0, 'payouts', '[]'::jsonb, 'refunds', v_refunds, 'on_wallet_refusal', 'liability');
    v_res := public.trivia_settlement_settle('tournament', t.id, v_plan);
    UPDATE public.trivia_tournament_entrants e
       SET entry_state = 'refunded', refunded_at = v_now,
           refund_reference = 'trivia_tourn_cancel_' || t.id::text || '_' || e.participant_id::text
     WHERE e.tournament_id = t.id AND e.entry_state = 'entered' AND e.entry_fee > 0;
    -- Close any live seat sessions (no money in sessions).
    FOR x IN SELECT st.session_id FROM public.trivia_tournament_seats st
              JOIN public.trivia_sessions ss ON ss.id = st.session_id
             WHERE st.tournament_id = t.id AND ss.status = 'open' LOOP
        PERFORM public.trivia_p3_expire_session(x.session_id, 'tournament_cancelled');
    END LOOP;
    UPDATE public.trivia_tournaments
       SET lifecycle_state = 'cancelled', terminal_reason = p_reason, completed_at = v_now,
           last_fencing_token = COALESCE(p_fencing_token, last_fencing_token)
     WHERE id = t.id;
    PERFORM public.trivia_tournament_event(t.id, 'cancelled',
        jsonb_build_object('reason', p_reason, 'refunds', jsonb_array_length(v_refunds),
                           'refunded_total', v_res->'refunded_total', 'journal_id', v_res->'journal_id'),
        NULL, NULL, NULL, p_fencing_token);
    RETURN jsonb_build_object('cancelled', true, 'reason', p_reason, 'refunds', jsonb_array_length(v_refunds),
                              'refunded_total', v_res->'refunded_total');
END;
$$;


ALTER FUNCTION public.trivia_tournament_cancel_core(p_tournament_id uuid, p_reason text, p_fencing_token bigint) OWNER TO postgres;

--
-- TOC entry 4790 (class 1255 OID 74744029)
-- Name: trivia_tournament_capacity_v1(integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_tournament_capacity_v1(p_bracket_size integer, p_profile_id text DEFAULT 'tournament.nightly/roster@1'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE v_p public.trivia_roster_profiles%ROWTYPE; v_rounds integer; v_req integer; v_avail integer; v_cat jsonb; v_diff jsonb;
BEGIN
    SELECT * INTO v_p FROM public.trivia_roster_profiles WHERE profile_id = p_profile_id AND mode = 'tournaments';
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'unknown_profile'); END IF;
    IF p_bracket_size IS NULL OR p_bracket_size < 2 OR p_bracket_size > 4096 THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_bracket_size');
    END IF;
    v_rounds := ceil(ln(p_bracket_size::numeric) / ln(2::numeric) - 1e-9)::int;
    v_req := v_rounds * v_p.question_count;
    WITH p AS MATERIALIZED (
        SELECT e.category, e.difficulty FROM public.trivia_eligible_question_pool_v1 e
         WHERE v_p.mode = ANY (e.modes) AND e.category = ANY (v_p.categories)
           AND (v_p.per_question_seconds IS NULL OR e.min_timer_seconds <= v_p.per_question_seconds))
    SELECT (SELECT count(*) FROM p),
           (SELECT jsonb_object_agg(z.category, z.n) FROM (SELECT p.category, count(*) n FROM p GROUP BY 1) z),
           (SELECT jsonb_object_agg(z.difficulty, z.n) FROM (SELECT p.difficulty, count(*) n FROM p GROUP BY 1) z)
      INTO v_avail, v_cat, v_diff;
    RETURN jsonb_build_object('success', true, 'bracket_size', p_bracket_size, 'rounds', v_rounds,
        'questions_per_round', v_p.question_count, 'required', v_req, 'eligible_available', v_avail,
        'supports', v_avail >= v_req, 'by_category', coalesce(v_cat, '{}'::jsonb), 'by_difficulty', coalesce(v_diff, '{}'::jsonb),
        'profile_id', p_profile_id);
END $$;


ALTER FUNCTION public.trivia_tournament_capacity_v1(p_bracket_size integer, p_profile_id text) OWNER TO postgres;

