--

CREATE FUNCTION public.trivia_tournament_field_v2(p_tournament_id uuid, p_user_id uuid DEFAULT NULL::uuid, p_offset integer DEFAULT 0, p_limit integer DEFAULT 50, p_search text DEFAULT NULL::text, p_kind text DEFAULT NULL::text) RETURNS jsonb
