--
-- TOC entry 6694 (class 1255 OID 107658006)
-- Name: trivia_tournament_instance_dto(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_tournament_instance_dto(p_tournament_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
SELECT jsonb_build_object(
    'tournamentId', t.id,
    'name', t.name,
    'scheduleKind', t.schedule_kind,
    'officialTimezone', t.schedule_timezone,
    'localDate', t.scheduled_local_date,
    'localStartTime', to_char(t.scheduled_local_time, 'HH24:MI'),
    'startsAt', t.start_time,
    'plannedEndAt', t.end_time,
    'registrationOpensAt', t.registration_opens_at,
    'registrationClosesAt', t.registration_closes_at,
    'state', t.lifecycle_state,
    'rulesVersionId', t.rules_version_id,
    'rulesProvisional', COALESCE((SELECT rv.provisional FROM public.trivia_rules_versions rv WHERE rv.id = t.rules_version_id), false),
    'currency', 'diamonds',
    'entryFee', (t.format_snapshot->>'entry_fee')::integer,
    'rakePerEntry', CASE WHEN (t.format_snapshot->>'entry_fee')::integer > 0
        THEN GREATEST((t.format_snapshot->>'rake_minimum')::integer,
                      round((t.format_snapshot->>'entry_fee')::integer * (t.format_snapshot->>'rake_rate_bp')::integer / 10000.0)::integer)
        ELSE 0 END,
    'bracketCapacity', t.bracket_capacity,
    'horseTarget', t.horse_target,
    'horsesEntered', c.horses,
    'humansEntered', c.humans,
    'humanSeatsRemaining', GREATEST(0, t.bracket_capacity - t.horse_target - c.humans),
    'estimatedPrizePool', c.net_pool,
    'format', jsonb_build_object(
        'questionsPerRound', (t.format_snapshot->>'questions_per_round')::integer,
        'shotClockSeconds', (t.format_snapshot->>'shot_clock_seconds')::integer,
        'roundWindowSeconds', (t.format_snapshot->>'round_window_seconds')::integer,
        'transitionSeconds', jsonb_build_array((t.format_snapshot->>'transition_seconds')::integer,
                                               (t.format_snapshot->>'transition_max_seconds')::integer),
        'tieBreak', jsonb_build_array('more_correct', 'lower_total_answer_time', 'earlier_completion', 'better_seed'),
        'horsesDisclosed', true),
    'terminalReason', t.terminal_reason,
    'viewer', CASE WHEN p_user_id IS NULL THEN NULL ELSE (
        SELECT jsonb_build_object('entered', e.id IS NOT NULL, 'entrantId', e.id, 'entryReference', e.entry_reference,
                                  'entryState', e.entry_state)
          FROM (SELECT 1) one
          LEFT JOIN public.trivia_tournament_entrants e
            ON e.tournament_id = t.id AND e.participant_id = p_user_id) END)
  FROM public.trivia_tournaments t
  CROSS JOIN LATERAL (
      SELECT count(*) FILTER (WHERE e.participant_kind = 'horse' AND e.entry_state = 'entered') AS horses,
             count(*) FILTER (WHERE e.participant_kind = 'human' AND e.entry_state = 'entered') AS humans,
             COALESCE(sum(e.net_contribution) FILTER (WHERE e.entry_state = 'entered'), 0) AS net_pool
        FROM public.trivia_tournament_entrants e WHERE e.tournament_id = t.id) c
 WHERE t.id = p_tournament_id AND t.engine_version IS NOT NULL
$$;


ALTER FUNCTION public.trivia_tournament_instance_dto(p_tournament_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- TOC entry 6020 (class 1255 OID 107657899)
-- Name: trivia_tournament_keyed_unit(bytea, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_tournament_keyed_unit(p_key bytea, p_label text) RETURNS double precision
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
SELECT (('x' || lpad(substr(encode(extensions.hmac(convert_to(p_label, 'UTF8'), p_key, 'sha256'), 'hex'), 1, 13), 16, '0'))::bit(64)::bigint)::double precision
       / 4503599627370496.0
$$;


ALTER FUNCTION public.trivia_tournament_keyed_unit(p_key bytea, p_label text) OWNER TO postgres;

--
-- TOC entry 3062 (class 1259 OID 107657762)
-- Name: trivia_tournament_seats; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.trivia_tournament_seats (
    matchup_id uuid NOT NULL,
    seat_no smallint NOT NULL,
    tournament_id uuid NOT NULL,
    round_number integer NOT NULL,
    entrant_id uuid NOT NULL,
    participant_id uuid,
    participant_kind text NOT NULL,
    status text DEFAULT 'waiting'::text NOT NULL,
    session_id uuid,
    session_opened_at timestamp with time zone,
    finished_at timestamp with time zone,
    result_outcome text,
    question_total integer,
    answered_count integer DEFAULT 0 NOT NULL,
    correct_count integer DEFAULT 0 NOT NULL,
    tiebreak_ms bigint DEFAULT 0 NOT NULL,
    completed_at timestamp with time zone,
    result_hash text,
    horse_plan_hash text,
    CONSTRAINT trivia_tournament_seats_answered_count_check CHECK ((answered_count >= 0)),
    CONSTRAINT trivia_tournament_seats_check CHECK ((correct_count <= answered_count)),
    CONSTRAINT trivia_tournament_seats_check1 CHECK (((status = ANY (ARRAY['finished'::text, 'no_show'::text])) = ((result_outcome IS NOT NULL) AND (finished_at IS NOT NULL)))),
    CONSTRAINT trivia_tournament_seats_check2 CHECK (((status <> 'no_show'::text) OR (session_id IS NULL))),
    CONSTRAINT trivia_tournament_seats_check3 CHECK (((participant_kind = 'human'::text) OR (status = ANY (ARRAY['waiting'::text, 'no_show'::text])) OR (horse_plan_hash IS NOT NULL))),
    CONSTRAINT trivia_tournament_seats_correct_count_check CHECK ((correct_count >= 0)),
    CONSTRAINT trivia_tournament_seats_horse_plan_hash_check CHECK (((horse_plan_hash IS NULL) OR (horse_plan_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT trivia_tournament_seats_participant_kind_check CHECK ((participant_kind = ANY (ARRAY['human'::text, 'horse'::text]))),
    CONSTRAINT trivia_tournament_seats_result_outcome_check CHECK (((result_outcome IS NULL) OR (result_outcome = ANY (ARRAY['submitted'::text, 'expired'::text, 'no_show'::text])))),
    CONSTRAINT trivia_tournament_seats_round_number_check CHECK (((round_number >= 1) AND (round_number <= 9))),
    CONSTRAINT trivia_tournament_seats_seat_no_check CHECK ((seat_no = ANY (ARRAY[1, 2]))),
    CONSTRAINT trivia_tournament_seats_status_check CHECK ((status = ANY (ARRAY['waiting'::text, 'playing'::text, 'finished'::text, 'no_show'::text]))),
    CONSTRAINT trivia_tournament_seats_tiebreak_ms_check CHECK ((tiebreak_ms >= 0))
);


ALTER TABLE public.trivia_tournament_seats OWNER TO postgres;

--
-- TOC entry 7659 (class 1255 OID 107657981)
-- Name: trivia_tournament_live_seat(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_tournament_live_seat(p_tournament_id uuid, p_user_id uuid) RETURNS public.trivia_tournament_seats
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_matchup uuid;
    v_seat smallint;
    s public.trivia_tournament_seats%ROWTYPE;
BEGIN
    SELECT st.matchup_id, st.seat_no INTO v_matchup, v_seat
      FROM public.trivia_tournament_seats st
      JOIN public.trivia_tournament_matchups m ON m.id = st.matchup_id
     WHERE st.tournament_id = p_tournament_id AND st.participant_id = p_user_id
       AND st.participant_kind = 'human' AND m.status = 'ready'
     ORDER BY st.round_number DESC LIMIT 1;
    IF v_matchup IS NULL THEN
        RETURN NULL;
    END IF;
    PERFORM 1 FROM public.trivia_tournament_matchups WHERE id = v_matchup FOR UPDATE;
    SELECT * INTO s FROM public.trivia_tournament_seats WHERE matchup_id = v_matchup AND seat_no = v_seat FOR UPDATE;
    RETURN s;
END;
$$;


ALTER FUNCTION public.trivia_tournament_live_seat(p_tournament_id uuid, p_user_id uuid) OWNER TO postgres;

