CREATE FUNCTION public.trivia_tournament_visible_v1(p_tournament_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT EXISTS (
        SELECT 1
          FROM public.trivia_tournaments AS t
         WHERE t.id = p_tournament_id
           AND t.engine_version IS NOT NULL
           AND (
                t.schedule_kind = 'public_nightly'
                OR EXISTS (
                    SELECT 1
                      FROM public.trivia_tournament_canary_access AS a
                     WHERE a.tournament_id = t.id
                       AND a.user_id = p_user_id
                )
           )
    )
$$;


