--
-- TOC entry 9396 (class 1255 OID 74719988)
-- Name: trivia_triage_question_report_v1(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trivia_triage_question_report_v1(p_report_id uuid, p_state text, p_actor text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_r public.trivia_question_reports%ROWTYPE; v_q jsonb;
BEGIN
    IF p_state NOT IN ('triaged','upheld','dismissed','duplicate') OR btrim(coalesce(p_actor, '')) = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_arguments');
    END IF;
    SELECT * INTO v_r FROM public.trivia_question_reports WHERE id = p_report_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'report_not_found'); END IF;
    IF v_r.state = p_state THEN
        RETURN jsonb_build_object('success', true, 'duplicate', true, 'report_id', p_report_id, 'state', v_r.state);
    END IF;
    IF v_r.state NOT IN ('open','triaged') OR (v_r.state = 'triaged' AND p_state = 'triaged') THEN
        RETURN jsonb_build_object('success', false, 'error', 'report_closed', 'state', v_r.state);
    END IF;
    UPDATE public.trivia_question_reports
       SET state = p_state, triaged_at = now(), triaged_by = p_actor,
           triage_note = coalesce(nullif(btrim(coalesce(p_note, '')), ''), triage_note),
           resolved_at = CASE WHEN p_state IN ('upheld','dismissed','duplicate') THEN now() ELSE resolved_at END,
           resolution = CASE WHEN p_state IN ('upheld','dismissed','duplicate') THEN p_state ELSE resolution END
     WHERE id = p_report_id;
    IF p_state = 'upheld' THEN
        v_q := public.trivia_quarantine_question_v1(v_r.question_id, 'report_upheld', 'operations', p_actor,
            jsonb_build_object('report_id', p_report_id));
    END IF;
    RETURN jsonb_build_object('success', true, 'duplicate', false, 'report_id', p_report_id, 'state', p_state,
        'quarantine', v_q);
END $$;


ALTER FUNCTION public.trivia_triage_question_report_v1(p_report_id uuid, p_state text, p_actor text, p_note text) OWNER TO postgres;

--
-- TOC entry 6624 (class 1255 OID 5796522)
-- Name: tup_apply_session(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tup_apply_session() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := NEW.user_id;
  v_qa   integer := COALESCE(NEW.questions_answered, 0);
  v_qc   integer := COALESCE(NEW.questions_correct, 0);
  v_streak integer := COALESCE(NEW.streak, 0);
BEGIN
  INSERT INTO public.training_user_progress AS p (
    user_id, total_sessions, total_questions, total_correct,
    best_streak, current_streak, last_session_at, updated_at
  )
  VALUES (
    v_user, 1, v_qa, v_qc,
    v_streak, v_streak, COALESCE(NEW.session_timestamp, NEW.created_at, now()), now()
  )
  ON CONFLICT (user_id) DO UPDATE SET
    total_sessions   = p.total_sessions  + 1,
    total_questions  = p.total_questions + v_qa,
    total_correct    = p.total_correct   + v_qc,
    best_streak      = GREATEST(p.best_streak, v_streak),
    current_streak   = v_streak,
    last_session_at  = COALESCE(NEW.session_timestamp, NEW.created_at, now()),
    updated_at       = now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.tup_apply_session() OWNER TO postgres;

--
-- TOC entry 7485 (class 1255 OID 5824935)
-- Name: tup_revert_session(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tup_revert_session() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := OLD.user_id;
  v_qa   integer := COALESCE(OLD.questions_answered, 0);
  v_qc   integer := COALESCE(OLD.questions_correct, 0);
BEGIN
  IF v_user IS NULL THEN RETURN OLD; END IF;
  -- Decrement counters; clamp at zero so a partial state never becomes
  -- invalid even if the rollup row was previously zeroed.
  UPDATE public.training_user_progress AS p SET
    total_sessions  = GREATEST(0, p.total_sessions  - 1),
    total_questions = GREATEST(0, p.total_questions - v_qa),
    total_correct   = GREATEST(0, p.total_correct   - v_qc),
    updated_at      = now()
  WHERE p.user_id = v_user;
  RETURN OLD;
END;
$$;


ALTER FUNCTION public.tup_revert_session() OWNER TO postgres;

