--
-- TOC entry 8793 (class 1255 OID 2121050)
-- Name: update_friend_preferences(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_friend_preferences(p_user_id uuid, p_preferences jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF p_preferences IS NULL OR jsonb_typeof(p_preferences) <> 'object' THEN
    RAISE EXCEPTION 'friend preferences must be a JSON object' USING ERRCODE = '22023';
  END IF;
  IF octet_length(p_preferences::text) > 4096 THEN
    RAISE EXCEPTION 'friend preferences are too large' USING ERRCODE = '22023';
  END IF;
  IF auth.uid() IS NOT NULL AND p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'you can only change your own friend preferences' USING ERRCODE = '42501';
  END IF;

  UPDATE public.profiles
     SET friend_preferences = COALESCE(friend_preferences, '{}'::jsonb) || p_preferences
   WHERE id = p_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = 'P0002';
  END IF;

  RETURN p_preferences;
END;
$$;


ALTER FUNCTION public.update_friend_preferences(p_user_id uuid, p_preferences jsonb) OWNER TO postgres;

