    IF OLD.post_type = 'venue' THEN
      UPDATE commander_venue_posts SET comments_count = comments_count - 1 WHERE id = OLD.post_id;
    ELSE
      UPDATE commander_home_posts SET comments_count = comments_count - 1 WHERE id = OLD.post_id;
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


