--
-- TOC entry 9167 (class 1255 OID 2121052)
-- Name: update_store_preferences(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_store_preferences(p_user_id uuid, p_preferences jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF p_preferences IS NULL OR jsonb_typeof(p_preferences) <> 'object' THEN
    RAISE EXCEPTION 'store preferences must be a JSON object' USING ERRCODE = '22023';
  END IF;
  IF octet_length(p_preferences::text) > 4096 THEN
    RAISE EXCEPTION 'store preferences are too large' USING ERRCODE = '22023';
  END IF;
  IF auth.uid() IS NOT NULL AND p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'you can only change your own store preferences' USING ERRCODE = '42501';
  END IF;

  UPDATE public.profiles
     SET store_preferences = COALESCE(store_preferences, '{}'::jsonb) || p_preferences
   WHERE id = p_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile not found' USING ERRCODE = 'P0002';
  END IF;

  RETURN p_preferences;
END;
$$;


ALTER FUNCTION public.update_store_preferences(p_user_id uuid, p_preferences jsonb) OWNER TO postgres;

--
-- TOC entry 6170 (class 1255 OID 9352463)
-- Name: update_table_stats(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_table_stats(p_table_id uuid, p_pot_total numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_table_id is null then return; end if;
  update tables
     set hands_dealt = coalesce(hands_dealt, 0) + 1,
         -- Seed the average on the first hand instead of dragging it up from 0.
         avg_pot = case
           when coalesce(hands_dealt, 0) = 0 then coalesce(p_pot_total, 0)
           else (coalesce(avg_pot, 0) * 0.9) + (coalesce(p_pot_total, 0) * 0.1)
         end,
         updated_at = now()
   where id = p_table_id;
end $$;


ALTER FUNCTION public.update_table_stats(p_table_id uuid, p_pot_total numeric) OWNER TO postgres;

