--
-- TOC entry 5907 (class 1255 OID 111878068)
-- Name: update_trivia_preferences_cas(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_trivia_preferences_cas(p_expected_revision bigint, p_preferences jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_current jsonb;
  v_requested jsonb;
  v_revision bigint;
  v_updated_at timestamptz;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required'
      USING ERRCODE = '42501';
  END IF;

  IF p_expected_revision IS NULL OR p_expected_revision < 0 THEN
    RAISE EXCEPTION 'Expected trivia preference revision is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(p_preferences) IS DISTINCT FROM 'object'
     OR pg_column_size(p_preferences) > 131072
     OR p_preferences ? '_sync' THEN
    RAISE EXCEPTION 'Trivia preferences payload is invalid'
      USING ERRCODE = '22023';
  END IF;

  v_requested := p_preferences;

  SELECT COALESCE(p.trivia_preferences, '{}'::jsonb),
         p.trivia_preferences_revision,
         p.updated_at
    INTO v_current, v_revision, v_updated_at
    FROM public.profiles AS p
   WHERE p.id = v_user_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Profile not found'
      USING ERRCODE = 'P0002';
  END IF;

  -- Response-loss retries are idempotent. A stale token may confirm the same
  -- final document, but can never replace a different document.
  IF (v_current - '_sync') = v_requested THEN
    RETURN jsonb_build_object(
      'contract', 'trivia-preferences-cas/1',
      'version', 1,
      'success', true,
      'conflict', false,
      'changed', false,
      'revision', v_revision,
      'preferences', v_current - '_sync',
      'updatedAt', v_updated_at
    );
  END IF;

  IF v_revision <> p_expected_revision THEN
    RETURN jsonb_build_object(
      'contract', 'trivia-preferences-cas/1',
      'version', 1,
      'success', false,
      'conflict', true,
      'changed', false,
      'revision', v_revision,
      'preferences', v_current - '_sync',
      'updatedAt', v_updated_at
    );
  END IF;

  UPDATE public.profiles
     SET trivia_preferences = v_requested,
         updated_at = clock_timestamp()
   WHERE id = v_user_id
  RETURNING trivia_preferences,
            trivia_preferences_revision,
            updated_at
       INTO v_current, v_revision, v_updated_at;

  RETURN jsonb_build_object(
    'contract', 'trivia-preferences-cas/1',
    'version', 1,
    'success', true,
    'conflict', false,
    'changed', true,
    'revision', v_revision,
    'preferences', v_current,
    'updatedAt', v_updated_at
  );
END
$$;


ALTER FUNCTION public.update_trivia_preferences_cas(p_expected_revision bigint, p_preferences jsonb) OWNER TO postgres;

