-- Name: FUNCTION update_trivia_preferences_cas(p_expected_revision bigint, p_preferences jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.update_trivia_preferences_cas(p_expected_revision bigint, p_preferences jsonb) IS 'Atomically replaces the signed-in account trivia preferences only at the expected server revision; returns the current cloud snapshot on conflict.';


--
-- TOC entry 6664 (class 1255 OID 10827309)
-- Name: update_trivia_streak(uuid, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_trivia_streak(p_user_id uuid, p_score integer, p_correct_count integer, p_xp_earned integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_user       uuid;
    v_last_date  date;
    v_streak     integer;
    v_best       integer;
    v_today      date := CURRENT_DATE;
    v_correct    integer := GREATEST(COALESCE(p_correct_count, 0), 0);
    v_xp         integer := GREATEST(COALESCE(p_xp_earned, 0), 0);
BEGIN
    -- A client may only advance ITS OWN streak. The old signature took an
    -- arbitrary p_user_id and was GRANTed to authenticated.
    IF (SELECT auth.role()) = 'service_role' THEN
        v_user := COALESCE(p_user_id, (SELECT auth.uid()));
    ELSE
        v_user := (SELECT auth.uid());
    END IF;
    IF v_user IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;

    -- Lock the row: two tabs finishing at once used to interleave a
    -- read-modify-write and lose one game's totals.
    SELECT s.last_play_date, s.current_streak, s.best_streak
      INTO v_last_date, v_streak, v_best
      FROM public.trivia_streaks s
     WHERE s.user_id = v_user
       FOR UPDATE;

    IF NOT FOUND THEN
        INSERT INTO public.trivia_streaks (
            user_id, current_streak, best_streak, last_play_date,
            total_games_played, total_correct, updated_at
        )
        VALUES (v_user, 1, 1, v_today, 1, v_correct, now())
        -- Closes the insert race between two simultaneous first games.
        ON CONFLICT (user_id) DO UPDATE SET
            total_games_played = public.trivia_streaks.total_games_played + 1,
            total_correct      = public.trivia_streaks.total_correct + v_correct,
            
            updated_at         = now()
        RETURNING current_streak, best_streak INTO v_streak, v_best;

        RETURN jsonb_build_object(
            'success', true, 'current_streak', COALESCE(v_streak, 1),
            'best_streak', COALESCE(v_best, 1), 'xp_earned', v_xp
        );
    END IF;

    v_streak := COALESCE(v_streak, 0);
    IF v_last_date = v_today - 1 THEN
        v_streak := v_streak + 1;          -- consecutive day
    ELSIF v_last_date IS NULL OR v_last_date < v_today - 1 THEN
        v_streak := 1;                     -- streak broken (or first play)
    END IF;
    -- v_last_date = v_today: already played today, streak unchanged.

    UPDATE public.trivia_streaks SET
        current_streak     = v_streak,
        best_streak        = GREATEST(COALESCE(best_streak, 0), v_streak),
        last_play_date     = v_today,
        total_games_played = COALESCE(total_games_played, 0) + 1,
        total_correct      = COALESCE(total_correct, 0) + v_correct,
        
        updated_at         = now()
    WHERE user_id = v_user
    RETURNING best_streak INTO v_best;

    RETURN jsonb_build_object(
        'success', true, 'current_streak', v_streak,
        'best_streak', v_best, 'xp_earned', v_xp
    );
END;
$$;


ALTER FUNCTION public.update_trivia_streak(p_user_id uuid, p_score integer, p_correct_count integer, p_xp_earned integer) OWNER TO postgres;

--
-- TOC entry 51120 (class 0 OID 0)
-- Dependencies: 6664
-- Name: FUNCTION update_trivia_streak(p_user_id uuid, p_score integer, p_correct_count integer, p_xp_earned integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.update_trivia_streak(p_user_id uuid, p_score integer, p_correct_count integer, p_xp_earned integer) IS 'Phase 80 — the ONLY supported way to advance a trivia streak. Enforces caller identity, locks the row, and closes the first-play insert race. Call from pages/hub/trivia/[mode].js instead of upserting trivia_streaks.';


