--
-- TOC entry 3039 (class 1259 OID 102610331)
-- Name: video_learning_progress; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.video_learning_progress (
    user_id uuid NOT NULL,
    video_id uuid NOT NULL,
    position_seconds numeric(10,3) DEFAULT 0 NOT NULL,
    duration_seconds numeric(10,3),
    percent_complete numeric(6,5) DEFAULT 0 NOT NULL,
    completed_at timestamp with time zone,
    last_chapter_key text,
    last_watched_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT video_learning_progress_check CHECK (((duration_seconds IS NULL) OR (position_seconds <= (duration_seconds + (5)::numeric)))),
    CONSTRAINT video_learning_progress_check1 CHECK (((completed_at IS NULL) OR (percent_complete >= 0.9))),
    CONSTRAINT video_learning_progress_duration_seconds_check CHECK (((duration_seconds IS NULL) OR (duration_seconds > (0)::numeric))),
    CONSTRAINT video_learning_progress_last_chapter_key_check CHECK (((last_chapter_key IS NULL) OR (length(last_chapter_key) <= 160))),
    CONSTRAINT video_learning_progress_percent_complete_check CHECK (((percent_complete >= (0)::numeric) AND (percent_complete <= (1)::numeric))),
    CONSTRAINT video_learning_progress_position_seconds_check CHECK ((position_seconds >= (0)::numeric))
);


ALTER TABLE public.video_learning_progress OWNER TO postgres;

--
-- TOC entry 9326 (class 1255 OID 102610408)
-- Name: upsert_video_learning_progress(uuid, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upsert_video_learning_progress(p_video_id uuid, p_position_seconds numeric, p_duration_seconds numeric, p_chapter_key text DEFAULT NULL::text) RETURNS public.video_learning_progress
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE u uuid:=auth.uid(); r public.video_learning_progress; pct numeric;
BEGIN
  IF u IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
  IF p_position_seconds<0 OR p_duration_seconds<=0 OR p_position_seconds>p_duration_seconds+5 OR NOT public.fn_is_video_library_asset_eligible(p_video_id) THEN RAISE EXCEPTION 'invalid or ineligible progress'; END IF;
  pct:=least(1,p_position_seconds/p_duration_seconds);
  INSERT INTO public.video_learning_progress(user_id,video_id,position_seconds,duration_seconds,percent_complete,completed_at,last_chapter_key,last_watched_at,updated_at)
  VALUES(u,p_video_id,p_position_seconds,p_duration_seconds,pct,CASE WHEN pct>=.9 THEN now() END,left(p_chapter_key,160),now(),now())
  ON CONFLICT(user_id,video_id) DO UPDATE SET
    percent_complete=greatest(video_learning_progress.percent_complete,excluded.percent_complete),
    position_seconds=CASE WHEN excluded.percent_complete>=video_learning_progress.percent_complete THEN excluded.position_seconds ELSE video_learning_progress.position_seconds END,
    duration_seconds=CASE WHEN excluded.percent_complete>=video_learning_progress.percent_complete THEN excluded.duration_seconds ELSE video_learning_progress.duration_seconds END,
    completed_at=CASE WHEN greatest(video_learning_progress.percent_complete,excluded.percent_complete)>=.9 THEN coalesce(video_learning_progress.completed_at,now()) ELSE NULL END,
    last_chapter_key=excluded.last_chapter_key,last_watched_at=now(),updated_at=now() RETURNING * INTO r;
  RETURN r;
END $$;


