--
-- TOC entry 5363 (class 1255 OID 120696176)
-- Name: accepted_hand_roster_build(uuid, bigint, uuid, jsonb, boolean, jsonb, timestamp with time zone); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.accepted_hand_roster_build(p_table_id uuid, p_hand_number bigint, p_hand_id uuid, p_stacks jsonb, p_exact boolean, p_lightning_seats jsonb, p_captured_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  v_reasons text[] := '{}';
  v_actors jsonb;
  v_roster jsonb;
  v_state text;
BEGIN
  BEGIN
    IF jsonb_typeof(p_stacks) IS DISTINCT FROM 'array' THEN
      v_reasons := v_reasons || 'stack_roster_invalid'::text;
    ELSIF jsonb_array_length(p_stacks) < 2 THEN
      v_reasons := v_reasons || 'actor_count_below_two'::text;
    ELSIF jsonb_array_length(p_stacks) > 10 THEN
      v_reasons := v_reasons || 'actor_count_above_ten'::text;
    END IF;
    IF p_exact IS NOT TRUE THEN
      v_reasons := v_reasons || 'legacy_stack_seat_generation'::text;
    END IF;
    IF COALESCE(p_lightning_seats, '{}'::jsonb) <> '{}'::jsonb THEN
      -- Anchor chairs belong to several physical tables; their seat numbers
      -- are not one table's positions, so the capsule cannot state them.
      v_reasons := v_reasons || 'lightning_seat_positions_unbound'::text;
    END IF;
    IF p_hand_number IS NULL OR p_hand_number < 1 OR p_hand_number > 9007199254740991 THEN
      v_reasons := v_reasons || 'hand_number_out_of_range'::text;
    END IF;

    IF cardinality(v_reasons) = 0 THEN
      WITH stack AS (
        SELECT (x->>'user_id')::uuid AS user_id,
               (x->>'seat_id')::uuid AS seat_id,
               x->>'seat_joined_at' AS joined_text,
               (x->>'seat_joined_at')::timestamptz AS joined_at
          FROM jsonb_array_elements(p_stacks) x
      ), joined AS (
        -- The exact generation the stack core proved: same row id, joiner and
        -- joined_at at this table. A lawfully departed seat keeps its row.
        SELECT s.user_id, s.seat_id, s.joined_text, s.joined_at,
               ts.id AS row_id, ts.seat_number,
               p.id AS profile_id, p.is_horse
          FROM stack s
          LEFT JOIN public.table_seats ts
            ON ts.id = s.seat_id AND ts.user_id = s.user_id
           AND ts.joined_at = s.joined_at AND ts.table_id = p_table_id
          LEFT JOIN public.profiles p ON p.id = s.user_id
      )
      SELECT
        jsonb_agg(jsonb_build_object(
          'userId', j.user_id::text,
          'seat', j.seat_number,
          'seatId', j.seat_id::text,
          'seatJoinedAt', j.joined_text,
          'classification', CASE WHEN j.profile_id IS NULL OR j.is_horse IS NULL THEN 'unknown'
                                 WHEN j.is_horse THEN 'horse' ELSE 'human' END,
          'status', CASE WHEN j.profile_id IS NULL THEN 'profile_missing'
                         WHEN j.is_horse IS NULL THEN 'classification_null'
                         ELSE 'canonical_boolean' END)
          ORDER BY j.user_id::text COLLATE "C"),
        array_remove(ARRAY[
          CASE WHEN bool_or(j.row_id IS NULL) THEN 'seat_generation_row_missing' END,
          CASE WHEN NOT bool_or(j.row_id IS NULL)
                AND bool_or(j.seat_number < 1 OR j.seat_number > 10) THEN 'seat_number_out_of_range' END,
          CASE WHEN NOT bool_or(j.row_id IS NULL)
                AND count(DISTINCT j.seat_number) <> count(*) THEN 'duplicate_seat_number' END,
          CASE WHEN count(DISTINCT j.seat_id) <> count(*) THEN 'duplicate_seat_id' END,
          CASE WHEN count(DISTINCT j.user_id) <> count(*) THEN 'duplicate_actor' END,
          CASE WHEN bool_or(j.joined_text !~
                 '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$')
               THEN 'seat_joined_at_format' END,
          CASE WHEN bool_or(j.joined_at > p_captured_at) THEN 'seat_joined_after_capture' END
        ]::text[], NULL)
        INTO v_actors, v_reasons
        FROM joined j;
    END IF;

    IF cardinality(v_reasons) = 0 THEN
      v_roster := jsonb_build_object(
        'version', 1,
        'basis', 'profiles_read_in_acceptance_transaction',
        'tableId', p_table_id::text,
        'handId', p_hand_id::text,
        'handNumber', p_hand_number,
        'capturedAt', to_char(p_captured_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
        'actors', v_actors);
      IF octet_length(v_roster::text) > 16000 THEN
        v_reasons := ARRAY['roster_too_large'];
        v_roster := NULL;
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE;
    v_reasons := ARRAY['roster_producer_error:' || v_state];
    v_roster := NULL;
  END;
  IF cardinality(v_reasons) > 0 THEN v_roster := NULL; END IF;
  RETURN jsonb_build_object(
    'status', CASE WHEN v_roster IS NULL THEN 'unavailable' ELSE 'captured' END,
    'reasons', to_jsonb(v_reasons),
    'roster', v_roster);
END
$_$;


ALTER FUNCTION smarter_private.accepted_hand_roster_build(p_table_id uuid, p_hand_number bigint, p_hand_id uuid, p_stacks jsonb, p_exact boolean, p_lightning_seats jsonb, p_captured_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 3770 (class 1255 OID 120696181)
-- Name: accepted_hand_roster_first(uuid, bigint, uuid, jsonb, boolean, jsonb, text); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.accepted_hand_roster_first(p_table_id uuid, p_hand_number bigint, p_hand_id uuid, p_stacks jsonb, p_exact boolean, p_lightning_seats jsonb, p_payload_hash text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_captured timestamptz := transaction_timestamp();
  v_built jsonb;
  v_status text;
  v_reasons text[];
  v_roster jsonb;
  v_state text;
BEGIN
  v_built := smarter_private.accepted_hand_roster_build(p_table_id, p_hand_number, p_hand_id,
    p_stacks, p_exact, p_lightning_seats, v_captured);
  v_status := v_built->>'status';
  v_roster := NULLIF(v_built->'roster', 'null'::jsonb);
  SELECT COALESCE(array_agg(r ORDER BY o), '{}') INTO v_reasons
    FROM jsonb_array_elements_text(v_built->'reasons') WITH ORDINALITY AS t(r, o);
  BEGIN
    INSERT INTO smarter_private.accepted_hand_rosters
      (table_id, hand_number, hand_id, post_commit_payload_hash, status, reasons,
       roster, producer_version, captured_txid, captured_at)
    VALUES
      (p_table_id, p_hand_number, p_hand_id, p_payload_hash, v_status, v_reasons,
       v_roster, 'accepted_hand_roster_v1', txid_current(), v_captured);
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE;
    v_status := 'unavailable';
    v_reasons := ARRAY['roster_record_error:' || v_state];
    v_roster := NULL;
    BEGIN
      INSERT INTO smarter_private.accepted_hand_rosters
        (table_id, hand_number, hand_id, post_commit_payload_hash, status, reasons,
         roster, producer_version, captured_txid, captured_at)
      VALUES
        (p_table_id, p_hand_number, p_hand_id, p_payload_hash, v_status, v_reasons,
         NULL, 'accepted_hand_roster_v1', txid_current(), v_captured);
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END;
  RETURN jsonb_build_object(
    'version', 1,
    'status', v_status,
    'reasons', to_jsonb(v_reasons),
    'payloadDigest', p_payload_hash,
    'producerVersion', 'accepted_hand_roster_v1',
    'roster', v_roster);
END
$$;


ALTER FUNCTION smarter_private.accepted_hand_roster_first(p_table_id uuid, p_hand_number bigint, p_hand_id uuid, p_stacks jsonb, p_exact boolean, p_lightning_seats jsonb, p_payload_hash text) OWNER TO postgres;

--
-- TOC entry 5058 (class 1255 OID 120696171)
-- Name: accepted_hand_roster_guard(); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.accepted_hand_roster_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'ACCEPTED_ROSTER_IMMUTABLE' USING ERRCODE = '55000';
  END IF;
  IF NEW.captured_txid IS DISTINCT FROM txid_current() THEN
    RAISE EXCEPTION 'ACCEPTED_ROSTER_TRANSACTION_REQUIRED' USING ERRCODE = '55000';
  END IF;
  -- The receipt this row discriminates already carries the final payload hash
  -- in this transaction; the door holds it FOR UPDATE.
  IF NOT EXISTS (
    SELECT 1 FROM public.hand_atomic_commits c
     WHERE c.table_id = NEW.table_id
       AND c.hand_number = NEW.hand_number
       AND c.hand_id = NEW.hand_id
       AND c.post_commit_payload_hash = NEW.post_commit_payload_hash) THEN
    RAISE EXCEPTION 'ACCEPTED_ROSTER_RECEIPT_REQUIRED' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION smarter_private.accepted_hand_roster_guard() OWNER TO postgres;

--
-- TOC entry 9264 (class 1255 OID 120696182)
-- Name: accepted_hand_roster_replay(uuid, bigint, uuid, text); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.accepted_hand_roster_replay(p_table_id uuid, p_hand_number bigint, p_hand_id uuid, p_payload_hash text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE r smarter_private.accepted_hand_rosters;
BEGIN
  SELECT * INTO r FROM smarter_private.accepted_hand_rosters
   WHERE table_id = p_table_id AND hand_number = p_hand_number;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('version', 1, 'status', 'legacy_missing',
      'reasons', jsonb_build_array('accepted_roster_not_recorded'),
      'payloadDigest', p_payload_hash,
      'producerVersion', 'accepted_hand_roster_v1', 'roster', NULL);
  END IF;
  IF r.hand_id IS DISTINCT FROM p_hand_id
     OR r.post_commit_payload_hash IS DISTINCT FROM p_payload_hash THEN
    RETURN jsonb_build_object('version', 1, 'status', 'unavailable',
      'reasons', jsonb_build_array('roster_discriminator_mismatch'),
      'payloadDigest', p_payload_hash,
      'producerVersion', 'accepted_hand_roster_v1', 'roster', NULL);
  END IF;
  RETURN jsonb_build_object('version', 1, 'status', r.status,
    'reasons', to_jsonb(r.reasons), 'payloadDigest', r.post_commit_payload_hash,
    'producerVersion', r.producer_version, 'roster', r.roster);
END
$$;


ALTER FUNCTION smarter_private.accepted_hand_roster_replay(p_table_id uuid, p_hand_number bigint, p_hand_id uuid, p_payload_hash text) OWNER TO postgres;

--
-- TOC entry 4044 (class 1255 OID 37193508)
-- Name: acknowledge_hand_submission(uuid, jsonb); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.acknowledge_hand_submission(p_submission_id uuid, p_result jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE s smarter_private.hand_submissions; completed integer;
BEGIN
 SELECT * INTO STRICT s FROM smarter_private.hand_submissions WHERE submission_id=p_submission_id;
 IF p_result->>'success' IS DISTINCT FROM 'true' OR p_result->>'atomic_hand_commit' IS DISTINCT FROM 'true'
 OR p_result->>'history_id' IS DISTINCT FROM s.submission_id::text
 OR p_result->>'post_commit_obligations' IS DISTINCT FROM 'true'
 OR NOT EXISTS(SELECT 1 FROM public.hand_atomic_commits a WHERE a.table_id=s.table_id AND a.hand_number=s.hand_number
   AND a.hand_id=s.submission_id AND a.payload_hash=p_result->>'commit_hash'
   AND a.post_commit_request_hash=encode(extensions.digest(convert_to((s.request->'p_post_commit_obligations')::text,'UTF8'),'sha256'),'hex')
   AND a.post_commit_payload IS NOT NULL AND a.post_commit_payload_hash=p_result->>'post_commit_payload_hash') THEN
  RAISE EXCEPTION 'HAND_SUBMISSION_ACCEPTANCE_UNPROVEN' USING ERRCODE='55000'; END IF;
 -- 20261006081157: serialised per table with save_hand_state_snapshot.
 PERFORM pg_advisory_xact_lock(hashtextextended('hand-snapshot:' || s.table_id::text, 0));
 UPDATE public.hand_state_snapshots SET is_complete=true,updated_at=clock_timestamp()
 WHERE table_id=s.table_id AND hand_number=s.hand_number AND NOT is_complete;
 GET DIAGNOSTICS completed=ROW_COUNT;
 RETURN p_result||jsonb_build_object('submission_id',s.submission_id,'submission_hash',s.request_hash,
 'snapshot_completed',true,'snapshots_completed',completed);
END $$;


ALTER FUNCTION smarter_private.acknowledge_hand_submission(p_submission_id uuid, p_result jsonb) OWNER TO postgres;

--
-- TOC entry 8963 (class 1255 OID 153542053)
-- Name: adaptive_retained_batch(text); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.adaptive_retained_batch(p_batch text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
 SELECT jsonb_set(p_batch::jsonb,'{7}',COALESCE((SELECT jsonb_agg(v.value ORDER BY v.ordinality)
 FROM jsonb_array_elements(p_batch::jsonb->7) WITH ORDINALITY v
 WHERE NOT EXISTS(SELECT 1 FROM smarter_private.horse_adaptive_disposal_certificates c
 WHERE c.hand_digest=encode(sha256(convert_to((v.value#>>'{}')::jsonb->>2,'UTF8')),'hex') AND c.retired_at IS NOT NULL)
 AND NOT EXISTS(SELECT 1 FROM smarter_private.horse_adaptive_legacy_learning_purges p
 WHERE p.hand_digest=encode(sha256(convert_to((v.value#>>'{}')::jsonb->>2,'UTF8')),'hex'))),'[]'::jsonb))::text
$$;


ALTER FUNCTION smarter_private.adaptive_retained_batch(p_batch text) OWNER TO postgres;

--
-- TOC entry 7162 (class 1255 OID 206064471)
-- Name: admit_cash_atomic_contracts(uuid, jsonb); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.admit_cash_atomic_contracts(p_record uuid, p_expected jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE s record; canonical jsonb; plan jsonb; expectation jsonb; old_rows jsonb;
 bad_ids bigint[]; original_tier_count int; posted int; n int:=0; old_setting text;
 w_from timestamptz;w_to timestamptz;lock_key text;
BEGIN
 IF NOT public.fn_caller_is_engine() OR jsonb_typeof(p_expected) IS DISTINCT FROM 'object'
 THEN RAISE EXCEPTION 'atomic_cash_admission_not_authorised' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('accounting_cash_hand:'||(SELECT hand_id::text FROM public.rake_records WHERE id=p_record),0));
 -- Reuse the original source owner's funding/attribution/earning proof.
 plan:=public.fn_accounting_cash_commission_plan(p_record);
 w_from:=public.fn_union_week_start((plan->>'earned_at')::timestamptz);
 w_to:=public.fn_union_week_start(w_from+interval '8 days');
 FOR lock_key IN SELECT DISTINCT CASE WHEN p->>'coordinator_union_id' IS NOT NULL THEN 'union-accounting:' ELSE 'club-accounting:' END
  ||COALESCE(p->>'coordinator_union_id',p->>'club_id')||':'||extract(epoch FROM w_from)::text||':'||extract(epoch FROM w_to)::text
  FROM jsonb_array_elements(plan->'players')p ORDER BY 1 LOOP
  PERFORM pg_advisory_xact_lock_shared(hashtextextended(lock_key,0));
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_expected)k WHERE NOT EXISTS(
  SELECT 1 FROM public.accounting_cash_rake_sources x WHERE x.rake_record_id=p_record AND x.id::text=k))
 THEN RAISE EXCEPTION 'atomic_cash_admission_foreign_source' USING ERRCODE='23514'; END IF;
 FOR s IN SELECT x.*,x.xmin::text original_xid FROM public.accounting_cash_rake_sources x
  WHERE x.rake_record_id=p_record AND p_expected ? x.id::text ORDER BY x.id LOOP
  expectation:=p_expected->s.id::text;
  IF md5(s.contract::text) IS DISTINCT FROM expectation->>'original_md5'
  THEN RAISE EXCEPTION 'atomic_cash_admission_original_changed' USING ERRCODE='23514'; END IF;
  SELECT a.admitted_contract INTO canonical FROM public.accounting_cash_atomic_contract_admissions a WHERE a.source_id=s.id;
  IF FOUND THEN
   IF md5(canonical::text) IS DISTINCT FROM expectation->>'admitted_md5' THEN RAISE EXCEPTION 'atomic_cash_admission_replay_conflict' USING ERRCODE='23514'; END IF;
   CONTINUE;
  END IF;
  IF EXISTS(SELECT 1 FROM public.agent_commission_settlements a WHERE a.club_id=s.club_id AND a.period_start<=s.earned_at AND a.period_end>s.earned_at)
   OR EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r WHERE r.period_start<=s.earned_at AND r.period_end>s.earned_at
    AND ((r.union_id IS NOT NULL AND r.union_id=s.coordinator_union_id) OR(r.standalone_club_id=s.club_id AND s.coordinator_union_id IS NULL)))
   OR EXISTS(SELECT 1 FROM public.rakeback_periods r WHERE r.club_id=s.club_id AND r.user_id=s.player_id
    AND r.period_start=(w_from AT TIME ZONE 'America/Los_Angeles')::date AND r.status<>'pending')
  THEN RAISE EXCEPTION 'atomic_cash_admission_week_already_paid' USING ERRCODE='23514'; END IF;
  SELECT array_agg(DISTINCT h.id ORDER BY h.id) INTO bad_ids
  FROM (SELECT(s.contract#>>'{membership,history_id}')::bigint id
   UNION ALL SELECT(t#>>'{agreement,history_id}')::bigint FROM jsonb_array_elements(s.contract->'tiers')t
   UNION ALL SELECT(s.contract#>>'{union_agreement,history_id}')::bigint)refs
  JOIN public.accounting_agreement_history h ON h.id=refs.id
  WHERE h.transaction_id::text<>s.original_xid AND EXISTS(
   SELECT 1 FROM public.accounting_agreement_history later WHERE later.transaction_id=h.transaction_id AND later.observed_at>s.earned_at);
  IF bad_ids IS NULL THEN RAISE EXCEPTION 'atomic_cash_admission_no_unfinished_external_history' USING ERRCODE='23514'; END IF;
  SELECT p INTO STRICT canonical FROM jsonb_array_elements(plan->'players')p
   WHERE p->>'player_id'=s.player_id::text AND p->>'club_id'=s.club_id::text;
  IF md5(canonical::text) IS DISTINCT FROM expectation->>'admitted_md5'
   OR canonical=s.contract OR canonical->>'attribution_id' IS DISTINCT FROM s.contract->>'attribution_id'
   OR canonical->>'coordinator_union_id' IS DISTINCT FROM s.coordinator_union_id::text
   OR canonical->>'union_id' IS DISTINCT FROM s.union_id::text
   OR (canonical->>'rake_credit')::numeric IS DISTINCT FROM s.rake_credit
  THEN RAISE EXCEPTION 'atomic_cash_admission_canonical_changed' USING ERRCODE='23514'; END IF;
  PERFORM 1 FROM public.agent_commissions a WHERE a.source_type='cash_rake_accrual' AND a.source_id=s.id FOR UPDATE;
  SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]') INTO old_rows FROM public.agent_commissions a
   WHERE a.source_type='cash_rake_accrual' AND a.source_id=s.id;
  SELECT count(*) INTO original_tier_count FROM jsonb_array_elements(s.contract->'tiers')t WHERE(t->>'amount')::numeric>0;
  IF jsonb_array_length(old_rows)<>original_tier_count OR EXISTS(
   SELECT 1 FROM jsonb_array_elements(old_rows)a WHERE a->>'settled_at' IS NOT NULL OR a->>'club_id' IS DISTINCT FROM s.club_id::text
    OR(a->>'created_at')::timestamptz IS DISTINCT FROM s.earned_at OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s.contract->'tiers')t
     WHERE t->>'user_id'=a->>'user_id' AND(t->>'amount')::numeric=(a->>'amount')::numeric AND(t->>'rate')::numeric=(a->>'commission_rate')::numeric))
  THEN RAISE EXCEPTION 'atomic_cash_admission_original_commissions_changed' USING ERRCODE='23514'; END IF;
  -- An admitted source changes this unpaid book's proof fingerprint. Retained
  -- plan windows/certificates otherwise trust only their age and could reuse
  -- the prior contract. Invalidate their original scoped proof records in this
  -- SAME source transition; boundary certificates and other books stay intact.
  -- The paid-book guard above and original week lock exclude any payer stage.
  DELETE FROM public.accounting_close_partials
   WHERE union_id=COALESCE(s.coordinator_union_id,s.club_id) AND period_start=w_from AND period_end=w_to;
  DELETE FROM public.accounting_close_certificates
   WHERE union_id=COALESCE(s.coordinator_union_id,s.club_id) AND period_start=w_from AND period_end=w_to;
  INSERT INTO public.accounting_cash_atomic_contract_admissions(source_id,original_contract,admitted_contract,original_commissions,invalid_history_ids)
   VALUES(s.id,s.contract,canonical,old_rows,bad_ids);
  old_setting:=current_setting('app.ledger_maintenance',true);
  PERFORM set_config('app.ledger_maintenance','atomic-earning-admission:'||s.id::text,true);
  DELETE FROM public.agent_commissions WHERE source_type='cash_rake_accrual' AND source_id=s.id;
  PERFORM set_config('app.ledger_maintenance',COALESCE(old_setting,''),true);
  -- Reverse only the original source's display contributions, then use its
  -- SAME native posting function. Deleted agent profiles are never recreated.
  UPDATE public.agents a SET lifetime_rake_generated=COALESCE(a.lifetime_rake_generated,0)-s.rake_credit,
   weekly_rake_generated=COALESCE(a.weekly_rake_generated,0)-CASE WHEN public.fn_union_week_start(s.earned_at)=public.fn_union_week_start(now()) THEN s.rake_credit ELSE 0 END
   WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(s.contract->'tiers')t WHERE a.id=(t->>'agent_id')::uuid AND a.user_id=(t->>'user_id')::uuid)
    AND a.club_id=s.club_id;
  posted:=public.fn_post_accounting_commission_source(s.id,'cash_rake_accrual',s.earned_at,canonical);
  IF posted<>(SELECT count(*) FROM jsonb_array_elements(canonical->'tiers')t WHERE(t->>'amount')::numeric>0)
  THEN RAISE EXCEPTION 'atomic_cash_admission_posting_incomplete' USING ERRCODE='23514'; END IF;
  n:=n+1;
  PERFORM pg_advisory_xact_lock(hashtextextended('accounting_rakeback_period:'||s.club_id::text||':'||(w_from AT TIME ZONE 'America/Los_Angeles')::date::text,0));
  INSERT INTO public.accounting_period_recompute_requests(club_id,period_start,period_end)
   VALUES(s.club_id,(w_from AT TIME ZONE 'America/Los_Angeles')::date,(w_to AT TIME ZONE 'America/Los_Angeles')::date-1)
   ON CONFLICT(club_id,period_start,period_end) DO UPDATE SET last_requested_at=clock_timestamp(),status='pending',reason=NULL;
 END LOOP;
 RETURN n;
END $$;


