t":"05e48f16f24f4012f4896be51b634133","expected_plan_text":"[{\"rake\": 43.11000000000000000000, \"amount\": 2.1600000000000000, \"unrounded\": 2.1555000000000000000000, \"payer_kind\": \"club\", \"source_count\": 1947, \"payer_user_id\": null}]"},{"id":7830,"certificate_md5":"165b539c9e475a5769a8f5723c7a092e","club_id":"e14bc9f7-736d-425f-8f2c-e78305ebac1d","player_id":"4ffcc7ec-15a1-4c80-8309-e893ef9db022","period_start":"2026-10-12","period_end":"2026-10-18","source_fingerprint":"81db4aaa720a8b741f85b39c4985d93d","expected_plan_text":"[{\"rake\": 54.20000000000000000000, \"amount\": 2.7100000000000000, \"unrounded\": 2.7100000000000000000000, \"payer_kind\": \"club\", \"source_count\": 2521, \"payer_user_id\": null}]"},{"id":7831,"certificate_md5":"e2323ebc905d86af641d3f4c586abb60","club_id":"e14bc9f7-736d-425f-8f2c-e78305ebac1d","player_id":"6162b471-d011-41f7-ad89-9a8d856c9ffb","period_start":"2026-10-12","period_end":"2026-10-18","source_fingerprint":"28291462ef3afa8edb159750914f6799","expected_plan_text":"[{\"rake\": 32.86000000000000000000, \"amount\": 1.6400000000000000, \"unrounded\": 1.6430000000000000000000, \"payer_kind\": \"club\", \"source_count\": 1920, \"payer_user_id\": null}]"},{"id":7832,"certificate_md5":"608387f2a3bf2ce97a5401077592efa5","club_id":"e14bc9f7-736d-425f-8f2c-e78305ebac1d","player_id":"62f0d4da-b736-4629-ad14-894e432d0f04","period_start":"2026-10-12","period_end":"2026-10-18","source_fingerprint":"a064168848d7464ee666dbbdb1d1a5b9","expected_plan_text":"[{\"rake\": 26.96000000000000000000, \"amount\": 1.3500000000000000, \"unrounded\": 1.3480000000000000000000, \"payer_kind\": \"club\", \"source_count\": 1237, \"payer_user_id\": null}]"},{"id":7833,"certificate_md5":"eba72c5c1c44a0818c188049366528d7","club_id":"e14bc9f7-736d-425f-8f2c-e78305ebac1d","player_id":"697d34f5-fe65-422a-b624-5a4957ef4196","period_start":"2026-10-12","period_end":"2026-10-18","source_fingerprint":"0cc858c283084617a5646504f65e8ac9","expected_plan_text":"[{\"rake\": 26.72000000000000000000, \"amount\": 1.3400000000000000, \"unrounded\": 1.3360000000000000000000, \"payer_kind\": \"club\", \"source_count\": 1438, \"payer_user_id\": null}]"},{"id":7834,"certificate_md5":"f2e914a1f06e09b223dc1cc512f9bdc7","club_id":"e14bc9f7-736d-425f-8f2c-e78305ebac1d","player_id":"6d301010-3315-4694-b55d-812ae56110c5","period_start":"2026-10-12","period_end":"2026-10-18","source_fingerprint":"50efebcf5577f0fb084a29aa0580145a","expected_plan_text":"[{\"rake\": 52.05000000000000000000, \"amount\": 2.6000000000000000, \"unrounded\": 2.6025000000000000000000, \"payer_kind\": \"club\", \"source_count\": 3109, \"payer_user_id\": null}]"},{"id":7835,"certificate_md5":"6509de4a486dbdd0917c07f5cfe07fce","club_id":"e14bc9f7-736d-425f-8f2c-e78305ebac1d","player_id":"778f8033-c9e2-45fa-98ca-935f38e2b8ca","period_start":"2026-10-12","period_end":"2026-10-18","source_fingerprint":"c22d3719b2a09ed2ccc0bb97cdcc4ec5","expected_plan_text":"[{\"rake\": 58.11000000000000000000, \"amount\": 2.9100000000000000, \"unrounded\": 2.9055000000000000000000, \"payer_kind\": \"club\", \"source_count\": 3465, \"payer_user_id\": null}]"},{"id":7836,"certificate_md5":"11eeb9870f0f85610905269674e8b7fe","club_id":"e14bc9f7-736d-425f-8f2c-e78305ebac1d","player_id":"78d65d90-7234-4d43-816e-9c29e81dd33d","period_start":"2026-10-12","period_end":"2026-10-18","source_fingerprint":"2117174da5eea749309eecff7dae13df","expected_plan_text":"[{\"rake\": 50.20000000000000000000, \"amount\": 2.5100000000000000, \"unrounded\": 2.5100000000000000000000, \"payer_kind\": \"club\", \"source_count\": 2386, \"payer_user_id\": null}]"},{"id":7837,"certificate_md5":"7920ea52f2e834f72499182b54edb92a","club_id":"e14bc9f7-736d-425f-8f2c-e78305ebac1d","player_id":"7d1b678f-cea8-41fc-873e-2ec47ea5c318","period_start":"2026-10-12","period_end":"2026-10-18","source_fingerprint":"53ed27caa5291942b076d8a4b6305736","expected_plan_text":"[{\"rake\": 49.56000000000000000000, \"amount\": 2.4800000000000000, \"unrounded\": 2.4780000000000000000000, \"payer_kind\": \"club\", \"source_count\": 2809, \"payer_user_id\": null}]"},{"id":7838,"certificate_md5":"13f6f44dddfc4f131876452214cdcb71","club_id":"e14bc9f7-736d-425f-8f2c-e78305ebac1d","player_id":"7d7a80a2-092c-4338-878a-0416611b249c","period_start":"2026-10-12","period_end":"2026-10-18","source_fingerprint":"520d2235cf2203379d2146f2da60b53a","expected_plan_text":"[{\"rake\": 27.30000000000000000000, \"amount\": 1.3700000000000000, \"unrounded\": 1.3650000000000000000000, \"payer_kind\": \"club\", \"source_count\": 1671, \"payer_user_id\": null}]"},{"id":7839,"certificate_md5":"d3a347ac3eee5062026c42b3a0fab65f","club_id":"e14bc9f7-736d-425f-8f2c-e78305ebac1d","player_id":"82861181-5a96-4e7b-bfa4-b75ca2bd145f","period_start":"2026-10-12","period_end":"2026-10-18","source_fingerprint":"f4cd34ff72c14d2518f9a0ea5f12f542","expected_plan_text":"[{\"rake\": 45.44000000000000000000, \"amount\": 2.2700000000000000, \"unrounded\": 2.2720000000000000000000, \"payer_kind\": \"club\", \"source_count\": 2617, \"payer_user_id\": null}]"},{"id":7840,"certificate_md5":"5855e8c8a6655e8f94865a2479eb826e","club_id":"e14bc9f7-736d-425f-8f2c-e78305ebac1d","player_id":"84385ab0-d3ea-44c1-8e93-6fa6b1d25457","period_start":"2026-10-12","period_end":"2026-10-18","source_fingerprint":"878b2df2b3a46bc2e7f7451f8cf6d4bb","expected_plan_text":"[{\"rake\": 24.99000000000000000000, \"amount\": 1.2500000000000000, \"unrounded\": 1.2495000000000000000000, \"payer_kind\": \"club\", \"source_count\": 1681, \"payer_user_id\": null}]"},{"id":7841,"certificate_md5":"53c904214a830ae2f89565e807e34536","club_id":"e14bc9f7-736d-425f-8f2c-e78305ebac1d","player_id":"86468a23-14cb-4602-92f7-7e270197fc3c","period_start":"2026-10-12","period_end":"2026-10-18","source_fingerprint":"071c3fc73e1b59a8bd0d843965825067","expected_plan_text":"[{\"rake\": 57.86000000000000000000, \"amount\": 2.8900000000000000, \"unrounded\": 2.8930000000000000000000, \"payer_kind\": \"club\", \"source_count\": 3811, \"payer_user_id\": null}]"},{"id":7842,"certificate_md5":"0d12a32d11351b2be1fe2ead07dd8f09","club_id":"e14bc9f7-736d-425f-8f2c-e78305ebac1d","player_id":"8e5a0e02-7832-416d-970f-f6f74e181dcb","period_start":"2026-10-12","period_end":"2026-10-18","source_fingerprint":"15e299fb032035608f06e7696e6c3b56","expected_plan_text":"[{\"rake\": 50.91000000000000000000, \"amount\": 2.5500000000000000, \"unrounded\": 2.5455000000000000000000, \"payer_kind\": \"club\", \"source_count\": 3120, \"payer_user_id\": null}]"},{"id":7843,"certificate_md5":"df4fbab0979566f38546ca3af0fa9007","club_id":"e14bc9f7-736d-425f-8f2c-e78305ebac1d","player_id":"92cd4964-6206-4989-9730-b7959bae6dc5","period_start":"2026-10-12","period_end":"2026-10-18","source_fingerprint":"a331ec9ca2b013fc70e099481eccabfe","expected_plan_text":"[{\"rake\": 51.91000000000000000000, \"amount\": 2.6000000000000000, \"unrounded\": 2.5955000000000000000000, \"payer_kind\": \"club\", \"source_count\": 2646, \"payer_user_id\": null}]"},{"id":7844,"certificate_md5":"9a75d6f61fd43cc65f2ee228b7493f7e","club_id":"e14bc9f7-736d-425f-8f2c-e78305ebac1d","player_id":"a23ca5c9-b748-482f-9b59-9db35f7aa996","period_start":"2026-10-12","period_end":"2026-10-18","source_fingerprint":"7ba7df1c048e924fb7f100d7d65ebcfb","expected_plan_text":"[{\"rake\": 25.81000000000000000000, \"amount\": 1.2900000000000000, \"unrounded\": 1.2905000000000000000000, \"payer_kind\": \"club\", \"source_count\": 1801, \"payer_user_id\": null}]"}]'::jsonb;e jsonb;c public.accounting_rakeback_period_calculations%ROWTYPE;check_result jsonb;club uuid;start_day date;end_day date;players uuid[];digest text:='';admission_id bigint;
BEGIN
 IF public.fn_caller_is_engine()IS DISTINCT FROM true OR public.fn_platform_frozen()IS DISTINCT FROM false THEN RAISE EXCEPTION 'legacy_payer_admission_window_refused';END IF;
 IF p_calculations IS NULL OR cardinality(p_calculations)<1 OR cardinality(p_calculations)>16 OR(SELECT count(DISTINCT x)FROM unnest(p_calculations)x)IS DISTINCT FROM cardinality(p_calculations)::bigint
 OR(SELECT count(*)FROM jsonb_array_elements(expected)allowed_manifest WHERE(allowed_manifest->>'id')::bigint=ANY(p_calculations))IS DISTINCT FROM cardinality(p_calculations)::bigint THEN RAISE EXCEPTION 'legacy_payer_admission_identity_not_qualified';END IF;
 IF md5(pg_get_functiondef('public.fn_rakeback_split_check(uuid,date,date,uuid[])'::regprocedure))IS DISTINCT FROM '4255ae4df6902f370d13dc69632277bb' THEN RAISE EXCEPTION 'legacy_payer_source_validator_changed';END IF;
 FOR e IN SELECT value FROM jsonb_array_elements(expected)WHERE(value->>'id')::bigint=ANY(p_calculations)ORDER BY value->>'player_id'LOOP
 SELECT * INTO STRICT c FROM public.accounting_rakeback_period_calculations WHERE id=(e->>'id')::bigint;
 IF md5(to_jsonb(c)::text)IS DISTINCT FROM e->>'certificate_md5' OR smarter_private.rakeback_payer_plan(c.source_allocations,c.rakeback_amount)IS DISTINCT FROM(e->>'expected_plan_text')::jsonb THEN RAISE EXCEPTION 'legacy_payer_exact_preimage_changed';END IF;
 IF club IS NULL THEN club:=c.club_id;start_day:=c.period_start;end_day:=c.period_end;ELSIF(club,start_day,end_day)IS DISTINCT FROM(c.club_id,c.period_start,c.period_end)THEN RAISE EXCEPTION 'legacy_payer_batch_mixed_scope';END IF;
 players:=array_append(players,c.player_id);digest:=md5(digest||c.player_id::text||':'||c.source_fingerprint);
 END LOOP;
 check_result:=public.fn_rakeback_split_check(club,start_day,end_day,players);
 IF check_result->'players'IS DISTINCT FROM to_jsonb(cardinality(p_calculations)) OR check_result->'same'IS DISTINCT FROM to_jsonb(cardinality(p_calculations)) OR check_result->>'digest'IS DISTINCT FROM digest OR check_result?'reason' THEN RAISE EXCEPTION 'legacy_payer_original_sources_not_verified';END IF;
 FOREACH admission_id IN ARRAY p_calculations LOOP PERFORM smarter_private.ensure_rakeback_payer_contracts(admission_id);END LOOP;
 IF public.fn_platform_frozen()IS DISTINCT FROM false THEN RAISE EXCEPTION 'legacy_payer_admission_window_refused';END IF;
END $$;


ALTER FUNCTION smarter_private.admit_legacy_rakeback_payer_contracts(p_calculations bigint[]) OWNER TO postgres;

--
-- TOC entry 7650 (class 1255 OID 117840263)
-- Name: adopt_retired_cash_original_hand(uuid, text, uuid); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.adopt_retired_cash_original_hand(p_submission uuid, p_instance text, p_generation uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE c smarter_private.retired_cash_hand_qualification;s smarter_private.hand_submissions;
 lease public.engine_table_leases;item jsonb;stack_item jsonb;fr jsonb;move jsonb;m public.cash_hand_participant_manifests;
 funding public.cash_participant_funding_receipts;seat public.table_seats;inventory public.union_pnl_inventory_events;
 restore_key_text text;result jsonb;uid uuid;club uuid;before_amount numeric;ledger uuid;
BEGIN
 SELECT * INTO c FROM smarter_private.retired_cash_hand_qualification WHERE submission_id=p_submission;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT * INTO s FROM smarter_private.hand_submissions WHERE submission_id=p_submission FOR UPDATE;
 SELECT * INTO lease FROM public.engine_table_leases WHERE table_id=c.table_id FOR KEY SHARE;
 IF s.submission_id IS NULL OR s.request_hash IS DISTINCT FROM c.request_hash
 OR (s.table_id,s.hand_number) IS DISTINCT FROM(c.table_id,c.hand_number)
 OR s.lease_generation=p_generation OR lease.instance_id IS DISTINCT FROM p_instance
 OR lease.lease_generation IS DISTINCT FROM p_generation OR lease.protocol_version IS DISTINCT FROM 2
 OR lease.heartbeat_at IS NULL OR lease.heartbeat_at<clock_timestamp()-make_interval(secs=>public.fn_engine_lease_stale_seconds())
 OR public.fn_platform_frozen() OR auth.role() IS DISTINCT FROM 'service_role'
 OR NOT EXISTS(SELECT 1 FROM public.tables t WHERE t.id=c.table_id AND t.tournament_id IS NULL
   AND NOT coalesce(t.is_deleted,false) AND lower(t.status) IN('waiting','running') AND t.lifecycle IN('live','breaking'))
 OR EXISTS(SELECT 1 FROM smarter_private.hand_submission_handoffs h WHERE h.submission_id=p_submission)
 OR EXISTS(SELECT 1 FROM smarter_private.hand_submission_disposals h WHERE h.table_id=c.table_id AND h.hand_number=c.hand_number)
 OR EXISTS(SELECT 1 FROM public.hand_atomic_commits a WHERE a.table_id=c.table_id AND a.hand_number>=c.hand_number)
 OR EXISTS(SELECT 1 FROM public.hand_history h WHERE h.table_id=c.table_id AND h.hand_number>=c.hand_number)
 OR EXISTS(SELECT 1 FROM smarter_private.retired_cash_hand_custody r WHERE r.submission_id=p_submission) THEN
  RAISE EXCEPTION 'RETIRED_CASH_ORIGINAL_AUTHORITY_OR_CONSUMPTION_CHANGED' USING ERRCODE='55000'; END IF;
 -- All unaffected players still own the immutable before-stack. Lock in the
 -- native order before the first restitution; a replacement row is read only.
 FOR stack_item IN SELECT value FROM jsonb_array_elements(s.request->'p_stacks') ORDER BY value->>'seat_id' LOOP
  SELECT * INTO seat FROM public.table_seats WHERE id=(stack_item->>'seat_id')::uuid FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c.expected->'participants')p WHERE p->'stack'=stack_item)
   AND (seat.id IS NULL OR seat.table_id IS DISTINCT FROM c.table_id OR seat.user_id IS DISTINCT FROM(stack_item->>'user_id')::uuid
    OR seat.joined_at IS DISTINCT FROM(stack_item->>'seat_joined_at')::timestamptz OR seat.left_at IS NOT NULL
    OR seat.stack IS DISTINCT FROM(stack_item->>'stack_before')::numeric) THEN
   RAISE EXCEPTION 'RETIRED_CASH_UNQUALIFIED_CUSTODY_CHANGED' USING ERRCODE='55000'; END IF;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(c.expected->'participants') ORDER BY value#>>'{stack,user_id}' LOOP
  uid:=(item#>>'{stack,user_id}')::uuid;club:=(item->>'funding_club_id')::uuid;
  before_amount:=(item#>>'{stack,stack_before}')::numeric;
  restore_key_text:='retired_cash_base:'||p_submission::text||':'||(item#>>'{stack,occupancy_id}');
  SELECT * INTO m FROM public.cash_hand_participant_manifests WHERE id=(item#>>'{stack,funding_manifest_id}')::uuid;
  SELECT * INTO inventory FROM public.union_pnl_inventory_events WHERE event_id=(item->>'inventory_event_id')::bigint;
  SELECT * INTO seat FROM public.table_seats WHERE id=(item#>>'{stack,seat_id}')::uuid;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s.request->'p_stacks')x WHERE x=item->'stack')
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s.request#>'{p_post_commit_obligations,time_banks}')x WHERE x=item->'time_bank')
  OR m.id IS NULL OR (m.table_id,m.hand_number) IS DISTINCT FROM(c.table_id,c.hand_number)
  OR NOT m.funding_provenance_complete OR m.issues IS DISTINCT FROM '[]'::jsonb
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(m.participants)x WHERE x=item->'manifest_participant')
  OR inventory.event_id IS NULL OR inventory.source_name IS DISTINCT FROM 'table_seats'
  OR inventory.row_id::text IS DISTINCT FROM item#>>'{stack,seat_id}'
  OR inventory.operation NOT IN('DELETE','UPDATE')
  OR NOT (inventory.before_row @> (item->'inventory_before'))
  OR (inventory.before_row->>'left_at')::timestamptz NOT BETWEEN '2026-10-06 15:33:00Z' AND '2026-10-06 15:33:10Z'
  OR (inventory.before_row->>'stack')::numeric IS DISTINCT FROM before_amount
  OR (seat.id IS NOT NULL AND seat.occupancy_id=(item#>>'{stack,occupancy_id}')::uuid)
  OR NOT EXISTS(SELECT 1 FROM smarter_private.patterned_identity_retirements r WHERE r.old_id=uid AND r.retired_at IS NOT NULL)
  OR EXISTS(SELECT 1 FROM public.seat_cashout_receipts r WHERE r.occupancy_id=(item#>>'{stack,occupancy_id}')::uuid)
  OR EXISTS(SELECT 1 FROM public.table_cashout_history r WHERE r.user_id=uid AND r.table_id=c.table_id
    AND r.cashed_out_at>=(item#>>'{stack,seat_joined_at}')::timestamptz)
  OR EXISTS(SELECT 1 FROM public.chip_ledger l WHERE l.to_type='player_wallet' AND l.to_entity_id=uid
    AND (l.from_entity_id=c.table_id OR l.table_id=c.table_id) AND l.created_at>=(item#>>'{stack,seat_joined_at}')::timestamptz)
  OR EXISTS(SELECT 1 FROM public.wallet_transactions w WHERE w.user_id=uid AND w.table_id=c.table_id
    AND w.type='credit' AND w.created_at>=(item#>>'{stack,seat_joined_at}')::timestamptz)
  OR EXISTS(SELECT 1 FROM public.wallet_credit_idempotency w WHERE w.key=restore_key_text)
  OR EXISTS(SELECT 1 FROM public.ca_mint_ledger w WHERE w.op_id=restore_key_text)
  OR NOT EXISTS(SELECT 1 FROM public.club_members w WHERE w.user_id=uid AND w.club_id=club
    AND w.is_active AND w.status='approved' AND w.departed_at IS NULL) THEN
   RAISE EXCEPTION 'RETIRED_CASH_IMMUTABLE_CUSTODY_OR_RETURN_CHANGED' USING ERRCODE='55000'; END IF;
  PERFORM 1 FROM public.club_members WHERE user_id=uid AND club_id=club FOR UPDATE;
  IF jsonb_array_length(item#>'{manifest_participant,funding_receipts}')=0 THEN
   RAISE EXCEPTION 'RETIRED_CASH_FUNDING_EMPTY' USING ERRCODE='55000'; END IF;
  FOR fr IN SELECT value FROM jsonb_array_elements(item#>'{manifest_participant,funding_receipts}') LOOP
   SELECT * INTO funding FROM public.cash_participant_funding_receipts WHERE id=(fr->>'id')::uuid;
   IF funding.id IS NULL OR funding.user_id IS DISTINCT FROM uid OR funding.account_type IS DISTINCT FROM 'player_wallet'
   OR funding.account_entity_id IS DISTINCT FROM uid OR funding.funding_club_id IS DISTINCT FROM club
   OR funding.amount<=0 OR funding.asset IS DISTINCT FROM 'chips'
   OR NOT EXISTS(SELECT 1 FROM public.chip_ledger l WHERE l.id=funding.source_ledger_id
    AND l.from_type='player_wallet' AND l.from_entity_id=uid AND l.club_id=club AND l.amount=funding.amount)
   OR NOT EXISTS(SELECT 1 FROM public.wallet_transactions w WHERE w.id=funding.wallet_transaction_id
    AND w.user_id=uid AND w.amount=funding.amount AND w.type='debit') THEN
    RAISE EXCEPTION 'RETIRED_CASH_ORIGINAL_FUNDING_CHANGED' USING ERRCODE='55000'; END IF;
  END LOOP;
  FOR move IN SELECT value FROM jsonb_array_elements(item#>'{manifest_participant,funding_lineage,moves}') LOOP
   IF NOT EXISTS(SELECT 1 FROM public.cash_seat_move_receipts r WHERE r.move_id=(move->>'move_id')::uuid
    AND to_jsonb(r) @> move AND r.player_id=uid AND r.club_id=club) THEN
    RAISE EXCEPTION 'RETIRED_CASH_ORIGINAL_MOVE_LINEAGE_CHANGED' USING ERRCODE='55000'; END IF;
  END LOOP;
 END LOOP;
 -- No arbitrary amount, member club, or wallet can enter this path.
 FOR item IN SELECT value FROM jsonb_array_elements(c.expected->'participants') ORDER BY value#>>'{stack,user_id}' LOOP
  uid:=(item#>>'{stack,user_id}')::uuid;club:=(item->>'funding_club_id')::uuid;
  before_amount:=(item#>>'{stack,stack_before}')::numeric;
  restore_key_text:='retired_cash_base:'||p_submission::text||':'||(item#>>'{stack,occupancy_id}');
  result:=public.fn_ca_restore_erased_seat_credit(restore_key_text,uid,club,before_amount,c.table_id,
   'Current restitution of immutable cash custody erased during patterned-account retirement; original hand '||p_submission::text);
  ledger:=(result->>'chip_ledger_id')::uuid;
  IF result->>'restored' IS DISTINCT FROM 'true' OR result->>'key' IS DISTINCT FROM restore_key_text
   OR (result->>'user_id')::uuid IS DISTINCT FROM uid OR (result->>'club_id')::uuid IS DISTINCT FROM club
   OR (result->>'amount')::numeric IS DISTINCT FROM before_amount
   OR NOT EXISTS(SELECT 1 FROM public.chip_ledger l WHERE l.id=ledger AND l.idempotency_key=restore_key_text
    AND l.category='refund' AND l.from_type='issuance_reserve' AND l.to_type='player_wallet'
    AND l.to_entity_id=uid AND l.club_id=club AND l.amount=before_amount)
   OR NOT EXISTS(SELECT 1 FROM public.ca_mint_ledger l WHERE l.op_id=restore_key_text AND l.action='mint'
    AND l.asset='chips' AND l.holder_type='player' AND l.holder_id=uid AND l.amount=before_amount AND l.chip_ledger_id=ledger) THEN
   RAISE EXCEPTION 'RETIRED_CASH_RESTITUTION_INCOHERENT' USING ERRCODE='55000'; END IF;
  INSERT INTO smarter_private.retired_cash_hand_custody
   (submission_id,user_id,table_id,hand_number,seat_id,occupancy_id,seat_joined_at,stack_before,stack_after,
    funding_club_id,original_left_at,original_inventory_event,request_hash,transaction_id,restore_key,issuance_ledger,original_time_bank,state)
  VALUES(p_submission,uid,c.table_id,c.hand_number,(item#>>'{stack,seat_id}')::uuid,(item#>>'{stack,occupancy_id}')::uuid,
   (item#>>'{stack,seat_joined_at}')::timestamptz,before_amount,(item#>>'{stack,stack}')::numeric,club,
   (item#>>'{inventory_before,left_at}')::timestamptz,(item->>'inventory_event_id')::bigint,c.request_hash,txid_current(),restore_key_text,ledger,item->'time_bank','held');
 END LOOP;
 -- The original native settlement supplies its own ledger declaration.
 PERFORM set_config('app.ledger_category','',true);
 PERFORM set_config('app.ledger_counterparty','',true);
 PERFORM set_config('app.ledger_counterparty_entity','',true);
 PERFORM set_config('app.ledger_counterparty_label','',true);
 PERFORM set_config('app.ledger_settlement','',true);
 PERFORM set_config('app.ledger_idempotency_key','',true);
 RETURN true;
END $$;


ALTER FUNCTION smarter_private.adopt_retired_cash_original_hand(p_submission uuid, p_instance text, p_generation uuid) OWNER TO postgres;

--
-- TOC entry 4218 (class 1255 OID 153587362)
-- Name: archive_pruned_hand_index(uuid[]); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.archive_pruned_hand_index(p_hands uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE n integer; v_days integer; v_window interval;
BEGIN
 SELECT greatest(coalesce(horse_retention_days,8),1) INTO v_days
 FROM public.hand_history_retention_policy LIMIT 1;
 IF v_days IS NULL THEN v_days:=8; END IF;
 v_window:=make_interval(days=>v_days);
 IF p_hands IS NULL OR cardinality(p_hands)>250 THEN RAISE EXCEPTION 'HAND_INDEX_ARCHIVE_BATCH_INVALID' USING ERRCODE='22023'; END IF;
 -- Same history boundary that the owning prune locks before any side effects.
 PERFORM 1 FROM public.hand_history WHERE id=ANY(p_hands) ORDER BY id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.hand_history h WHERE h.id=ANY(p_hands)
  AND (h.has_human IS DISTINCT FROM FALSE OR h.reported IS TRUE OR h.created_at IS NULL
   OR NOT isfinite(h.created_at) OR h.created_at>=now()-v_window))
 OR EXISTS(SELECT 1 FROM public.ca_hand_player_idx i WHERE i.hand_id=ANY(p_hands)
  AND NOT EXISTS(SELECT 1 FROM public.hand_history h WHERE h.id=i.hand_id)) THEN
  RAISE EXCEPTION 'HAND_INDEX_ARCHIVE_RETENTION_BOUNDARY_REQUIRED' USING ERRCODE='55000'; END IF;
 WITH removed AS (
  DELETE FROM public.ca_hand_player_idx WHERE hand_id=ANY(p_hands) RETURNING user_id,asset,created_at
 ), grouped AS (
  SELECT user_id,asset,count(*)::bigint hands,min(created_at) first_hand_at,max(created_at) last_hand_at
  FROM removed GROUP BY user_id,asset
 ), written AS (
  INSERT INTO smarter_private.hand_index_retention_totals(user_id,asset,hands,first_hand_at,last_hand_at)
  SELECT user_id,asset,hands,first_hand_at,last_hand_at FROM grouped ORDER BY user_id,asset
  ON CONFLICT(user_id,asset) DO UPDATE SET hands=hand_index_retention_totals.hands+EXCLUDED.hands,
   first_hand_at=LEAST(hand_index_retention_totals.first_hand_at,EXCLUDED.first_hand_at),
   last_hand_at=GREATEST(hand_index_retention_totals.last_hand_at,EXCLUDED.last_hand_at)
  RETURNING 1
 ) SELECT coalesce(sum(hands),0)::integer INTO n FROM grouped WHERE (SELECT count(*) FROM written)>=0;
 RETURN n;
END $$;


ALTER FUNCTION smarter_private.archive_pruned_hand_index(p_hands uuid[]) OWNER TO postgres;

--
-- TOC entry 4873 (class 1255 OID 37193463)
-- Name: assert_retained_hand_submission(jsonb); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.assert_retained_hand_submission(p_request jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s smarter_private.hand_submissions; consumed integer;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('hand:submission:'||(p_request->>'p_table_id')||':'||(p_request->>'p_hand_number'),0));
 SELECT * INTO s FROM smarter_private.hand_submissions
 WHERE table_id=(p_request->>'p_table_id')::uuid AND hand_number=(p_request->>'p_hand_number')::bigint;
 IF NOT FOUND OR s.request IS NOT DISTINCT FROM p_request THEN RETURN; END IF;
 IF (s.request-'p_instance_id'-'p_lease_generation') IS NOT DISTINCT FROM
    (p_request-'p_instance_id'-'p_lease_generation') THEN
  DELETE FROM smarter_private.hand_submission_dispatch d WHERE d.transaction_id=txid_current()
   AND d.submission_id=s.submission_id AND d.request_hash=s.request_hash
   AND d.instance_id=p_request->>'p_instance_id'
   AND d.lease_generation=(p_request->>'p_lease_generation')::uuid;
  GET DIAGNOSTICS consumed=ROW_COUNT;
  IF consumed=1 THEN RETURN; END IF;
 END IF;
 RAISE EXCEPTION 'HAND_SUBMISSION_ORIGINAL_PAYLOAD_REQUIRED' USING ERRCODE='55000';
END $$;


ALTER FUNCTION smarter_private.assert_retained_hand_submission(p_request jsonb) OWNER TO postgres;

