--
-- TOC entry 9166 (class 1255 OID 153542045)
-- Name: capture_horse_adaptive_disposals(uuid[]); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.capture_horse_adaptive_disposals(p_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE id uuid; n integer:=0;
BEGIN
 IF cardinality(p_ids)>10000 THEN RAISE EXCEPTION 'ADAPTIVE_DISPOSAL_BATCH_TOO_LARGE'; END IF;
 FOR id IN SELECT unnest(p_ids) LOOP
  IF smarter_private.horse_request_payload_disposable(id) AND EXISTS(SELECT 1 FROM smarter_private.hand_submissions WHERE submission_id=id AND request#>'{p_hand_row,has_human}'='false'::jsonb) THEN
   INSERT INTO smarter_private.horse_adaptive_disposal_certificates
   SELECT s.submission_id,encode(sha256(convert_to(s.submission_id::text,'UTF8')),'hex'),s.table_id,s.hand_number,s.request_hash,clock_timestamp(),NULL,
    jsonb_build_object('version','settled-horse-adaptive-disposal-v1','original_horse_only',true,'original_has_human',s.request#>'{p_hand_row,has_human}',
     'retained_at',s.retained_at,'classifier_definition_md5',md5(pg_get_functiondef('smarter_private.horse_request_payload_disposable(uuid)'::regprocedure)),
     'request_hash',s.request_hash,'disposal',d.expected)
   FROM smarter_private.hand_submissions s JOIN smarter_private.hand_submission_disposals d
    ON d.table_id=s.table_id AND d.hand_number=s.hand_number AND d.submission_id=s.submission_id
   WHERE s.submission_id=id ON CONFLICT(hand_id) DO NOTHING;
   n:=n+1;
  END IF;
 END LOOP;
 RETURN n;
END $$;


ALTER FUNCTION smarter_private.capture_horse_adaptive_disposals(p_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 5183 (class 1255 OID 153556056)
-- Name: capture_horse_stats_basis(uuid[]); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.capture_horse_stats_basis(p_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE n integer;
BEGIN
 IF cardinality(p_ids)>10000 THEN RAISE EXCEPTION 'HORSE_STATS_BASIS_BATCH_TOO_LARGE' USING ERRCODE='22023'; END IF;
 INSERT INTO smarter_private.horse_retained_stats_basis(hand_id,table_id,hand_number,request_hash,original_stats_sha256,compact_stats)
 SELECT s.submission_id,s.table_id,s.hand_number,s.request_hash,
 encode(extensions.digest(convert_to(COALESCE(s.request#>'{p_hand_row,_accepted_post_commit_facts,stats_facts}','null'::jsonb)::text,'UTF8'),'sha256'),'hex'),
 smarter_private.horse_compact_stats_basis(s.request#>'{p_hand_row,_accepted_post_commit_facts,stats_facts}')
 FROM smarter_private.hand_submissions s WHERE s.submission_id=ANY(p_ids)
 AND smarter_private.horse_request_payload_disposable(s.submission_id)
 AND NOT EXISTS(SELECT 1 FROM smarter_private.horse_retained_stats_basis b WHERE b.hand_id=s.submission_id);
 GET DIAGNOSTICS n=ROW_COUNT; RETURN n;
END $$;


ALTER FUNCTION smarter_private.capture_horse_stats_basis(p_ids uuid[]) OWNER TO postgres;

