 OR jsonb_typeof(s.request->'p_stacks') IS DISTINCT FROM 'array' OR jsonb_array_length(s.request->'p_stacks')=0
 OR (SELECT count(DISTINCT v->>'seat_id') FROM jsonb_array_elements(s.request->'p_stacks')v) IS DISTINCT FROM jsonb_array_length(s.request->'p_stacks')::bigint
 OR EXISTS(SELECT FROM jsonb_array_elements(s.request->'p_stacks')v WHERE jsonb_typeof(v->'stack') IS DISTINCT FROM 'number' OR jsonb_typeof(v->'stack_before') IS DISTINCT FROM 'number' OR (v->>'stack')::numeric<0 OR (v->>'stack_before')::numeric<0 OR (v->>'stack')::numeric<>trunc((v->>'stack')::numeric) OR (v->>'stack_before')::numeric<>trunc((v->>'stack_before')::numeric))
 OR (SELECT sum((v->>'stack')::numeric-(v->>'stack_before')::numeric) FROM jsonb_array_elements(s.request->'p_stacks')v) IS DISTINCT FROM -((s.request->>'p_rake')::numeric+(s.request->>'p_bbj')::numeric)
 OR EXISTS(SELECT FROM jsonb_array_elements(s.request->'p_stacks')v WHERE (
  SELECT count(*) FROM public.table_seats seat JOIN public.poker_diamond_custody c ON c.seat_id=seat.id AND c.user_id=seat.user_id AND c.seat_joined_at=seat.joined_at AND c.occupancy_id=seat.occupancy_id
  JOIN public.tables t ON t.id=seat.table_id
  WHERE seat.table_id=s.table_id AND seat.id=(v->>'seat_id')::uuid AND seat.user_id=(v->>'user_id')::uuid
   AND seat.joined_at=(v->>'seat_joined_at')::timestamptz AND seat.occupancy_id=(v->>'occupancy_id')::uuid
   AND seat.left_at IS NULL AND seat.stack=(v->>'stack_before')::numeric
   AND c.target_id=s.table_id AND c.arena_id=t.club_id AND c.purpose='cash_seat' AND c.state='active' AND c.balance=(v->>'stack_before')::numeric) IS DISTINCT FROM 1::bigint)
 OR EXISTS(SELECT FROM public.settlement_idempotency_keys c WHERE c.table_id=s.table_id AND c.hand_id=stack_hand)
 OR EXISTS(SELECT FROM public.ca_settlements c WHERE c.settlement_type='hand_stacks' AND c.external_ref=s.table_id::text||':'||stack_hand::text)
 OR EXISTS(SELECT FROM public.hand_atomic_commits c WHERE c.table_id=s.table_id AND c.hand_number>=s.hand_number)
 OR EXISTS(SELECT FROM public.hand_history c WHERE c.table_id=s.table_id AND c.hand_number>=s.hand_number)
 OR EXISTS(SELECT FROM smarter_private.f06_hand_permits c WHERE c.table_id=s.table_id AND c.hand_number>=s.hand_number)
 OR EXISTS(SELECT FROM public.poker_diamond_hand_receipts c WHERE c.table_id=s.table_id AND c.hand_number=s.hand_number)
 OR EXISTS(SELECT FROM public.ca_diamond_rake_accrual c WHERE c.table_id=s.table_id AND c.hand_number=s.hand_number)
 OR EXISTS(SELECT FROM public.poker_diamond_jackpot_ledger c WHERE c.table_id=s.table_id AND c.hand_number=s.hand_number)
 OR EXISTS(SELECT FROM public.hand_projection_outbox c WHERE c.hand_id=s.submission_id)
 OR EXISTS(SELECT FROM public.poker_diamond_jackpot_hits c WHERE c.table_id=s.table_id AND c.hand_number=s.hand_number)
 THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('submission_id',e,'table_id',s.table_id,'hand_number',s.hand_number,'request_hash',s.request_hash,'request_md5',x.request_md5,'handoff_md5',x.handoff_md5,'result_md5',x.result_md5,'original_generation',s.lease_generation,'scope','cash','original_arena_id',x.original_arena_id,'source_cause','backup_residue_constraint','fixed_source_md5','f6e42d6de56f5074f47403621fd46110');
END $$;


ALTER FUNCTION smarter_private.cash_original17_source_correction_proof(e uuid) OWNER TO postgres;

--
-- TOC entry 3466 (class 1255 OID 157041033)
-- Name: certify_original_hand_source_correction(uuid); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.certify_original_hand_source_correction(e uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE proof jsonb;
BEGIN
 IF current_user IS DISTINCT FROM 'postgres' OR session_user IS DISTINCT FROM 'postgres'
 OR NULLIF(current_setting('request.jwt.claims',true),'') IS NOT NULL THEN RAISE EXCEPTION 'HAND_SOURCE_CORRECTION_OPERATOR_ONLY' USING ERRCODE='42501';END IF;
 IF public.fn_platform_frozen() IS DISTINCT FROM false THEN RAISE EXCEPTION 'HAND_SOURCE_CORRECTION_FROZEN' USING ERRCODE='55000';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('hand:submission:'||(SELECT table_id FROM smarter_private.hand_submissions WHERE submission_id=e)::text||':'||(SELECT hand_number FROM smarter_private.hand_submissions WHERE submission_id=e)::text,0));
 proof:=smarter_private.original_hand_source_correction_proof(e);
 IF proof IS NULL THEN RAISE EXCEPTION 'HAND_SOURCE_CORRECTION_PROOF_REFUSED' USING ERRCODE='55000';END IF;
 INSERT INTO smarter_private.hand_submission_source_corrections(submission_id,proof) VALUES(e,proof);
 RETURN jsonb_build_object('certified',true,'submission_id',e,'proof',proof,'financial_payment',false);
END $$;


ALTER FUNCTION smarter_private.certify_original_hand_source_correction(e uuid) OWNER TO postgres;

--
-- TOC entry 8773 (class 1255 OID 155813393)
-- Name: certify_original_inventory_restoration(bigint, timestamp with time zone); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.certify_original_inventory_restoration(p_event_id bigint, p_boundary timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE expected text; family text; witness jsonb; proof jsonb;
BEGIN
 IF session_user IS DISTINCT FROM 'postgres' OR current_user IS DISTINCT FROM 'postgres'
 OR nullif(current_setting('request.jwt.claim.role',true),'') IS NOT NULL THEN
  RAISE EXCEPTION 'original_inventory_certificate_caller_refused' USING ERRCODE='42501';END IF;
 IF p_event_id IS NULL OR p_boundary IS DISTINCT FROM '2026-10-12 07:00:00Z'::timestamptz
 OR public.fn_platform_frozen() IS DISTINCT FROM false
 OR smarter_private.original_inventory_proof_sources_match() IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'original_inventory_certificate_boundary_refused' USING ERRCODE='55000';END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('union-pnl-original-inventory-restoration',0)) THEN
  RAISE EXCEPTION 'original_inventory_certificate_writer_busy' USING ERRCODE='55000';END IF;
 SELECT witness_md5,k.family INTO expected,family FROM smarter_private.original_inventory_restoration_cases k WHERE event_id=p_event_id;
 IF expected IS NULL OR EXISTS(SELECT 1 FROM smarter_private.original_inventory_restoration_certificates
 WHERE event_id=p_event_id AND boundary=p_boundary) THEN
  RAISE EXCEPTION 'original_inventory_certificate_unknown_or_replayed' USING ERRCODE='55000';END IF;
 witness:=smarter_private.original_inventory_finite_witness(p_event_id);
 IF witness IS NULL OR md5(witness::text) IS DISTINCT FROM expected THEN
  RAISE EXCEPTION 'original_inventory_certificate_witness_changed' USING ERRCODE='55000';END IF;
 proof:=smarter_private.original_inventory_finite_family_proof(family,witness,'2026-10-05 07:00:00Z',p_boundary);
 IF proof->>'status' IS DISTINCT FROM 'ready' OR proof->'financial_admission' IS DISTINCT FROM 'false'::jsonb THEN
  RAISE EXCEPTION 'original_inventory_certificate_proof_refused' USING ERRCODE='55000';END IF;
 INSERT INTO smarter_private.original_inventory_restoration_certificates(event_id,boundary,witness_md5,original_witness,proof,proof_md5)
 VALUES(p_event_id,p_boundary,expected,witness,proof,md5(proof::text));
 RETURN jsonb_build_object('original_inventory_certificate',true,'event_id',p_event_id,'boundary',p_boundary,
  'witness_md5',expected,'proof_md5',md5(proof::text),'financial_payment',false);
END $$;


ALTER FUNCTION smarter_private.certify_original_inventory_restoration(p_event_id bigint, p_boundary timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 4211 (class 1255 OID 153383834)
-- Name: compact_horse_cash_play_contents(uuid[]); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.compact_horse_cash_play_contents(p_hands uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE k smarter_private.horse_settlement_key_certificates; p public.cash_hand_provenance_receipts;
 m public.cash_hand_participant_manifests; a public.hand_atomic_commits; h public.hand_history;
 request_after jsonb; atomic_after jsonb; evidence jsonb; n integer:=0; live_present boolean; retained_boundary text;
BEGIN
 IF p_hands IS NULL OR cardinality(p_hands)>250 THEN RAISE EXCEPTION 'HORSE_CASH_PAYLOAD_BATCH_INVALID' USING ERRCODE='22023'; END IF;
 FOR k IN SELECT * FROM smarter_private.horse_settlement_key_certificates WHERE history_hand_id=ANY(p_hands) ORDER BY table_id,hand_number LOOP
  IF k.settled_at>=now()-interval '8 days' OR NOT isfinite(k.settled_at)
  OR EXISTS(SELECT 1 FROM smarter_private.horse_cash_payload_certificates c WHERE c.table_id=k.table_id AND c.hand_number=k.hand_number)
  OR EXISTS(SELECT 1 FROM smarter_private.horse_cash_postprune_certificates c WHERE c.table_id=k.table_id AND c.hand_number=k.hand_number) THEN CONTINUE; END IF;
  SELECT * INTO h FROM public.hand_history WHERE id=k.history_hand_id AND table_id=k.table_id AND hand_number=k.hand_number FOR UPDATE;
  live_present:=FOUND;
  IF live_present THEN
  IF h.has_human IS DISTINCT FROM FALSE OR h.reported IS TRUE OR h.tournament_id IS NOT NULL
  OR h.created_at IS NULL OR NOT isfinite(h.created_at) OR h.created_at>=now()-interval '8 days'
  OR EXISTS(SELECT 1 FROM public.hand_projection_outbox o WHERE o.hand_id=h.id)
  OR EXISTS(SELECT 1 FROM public.bbj_payouts b WHERE b.table_id=h.table_id AND b.hand_number=h.hand_number)
  OR EXISTS(SELECT 1 FROM public.tournament_knockout_candidates t WHERE t.hand_id=h.id AND t.state='pending') THEN CONTINUE; END IF;
  SELECT * INTO a FROM public.hand_atomic_commits WHERE table_id=k.table_id AND hand_number=k.hand_number AND hand_id=k.history_hand_id FOR UPDATE;
  -- This transition belongs before original history deletion. Legacy certificates
  -- without the live completed boundary do not invent later qualification.
  IF NOT FOUND OR a.post_commit_completed_at IS DISTINCT FROM k.settled_at OR a.post_commit_result->>'ok' IS DISTINCT FROM 'true'
  OR smarter_private.f06_hand_cards_unresolved(k.table_id,k.hand_number)
  OR smarter_private.f06_movement_boundary_retained(k.table_id,k.hand_number) THEN CONTINUE; END IF;
  ELSE
   IF EXISTS(SELECT 1 FROM public.hand_atomic_commits original WHERE original.table_id=k.table_id AND original.hand_number=k.hand_number) THEN CONTINUE; END IF;
  END IF;
  SELECT * INTO p FROM public.cash_hand_provenance_receipts WHERE table_id=k.table_id AND hand_number=k.hand_number FOR UPDATE;
  IF NOT FOUND OR p.hand_id IS DISTINCT FROM k.history_hand_id OR p.manifest_id IS DISTINCT FROM k.manifest_id
  OR p.status IS DISTINCT FROM 'captured' OR p.funding_provenance_complete IS NOT TRUE OR p.all_players_included IS NOT TRUE
  OR p.accepted_request#>'{hand_row,has_human}' IS DISTINCT FROM 'false'::jsonb
  OR p.accepted_request#>'{hand_row,tournament_id}' IS DISTINCT FROM 'null'::jsonb
  OR encode(extensions.digest(convert_to(p.accepted_request::text,'UTF8'),'sha256'),'hex') IS DISTINCT FROM p.payload_hash
  OR (live_present AND p.atomic_receipt->'stack_result' IS DISTINCT FROM a.stack_result) THEN CONTINUE; END IF;
  SELECT * INTO m FROM public.cash_hand_participant_manifests WHERE id=p.manifest_id AND table_id=k.table_id AND hand_number=k.hand_number;
  IF NOT FOUND OR m.funding_provenance_complete IS NOT TRUE OR m.issues IS DISTINCT FROM '[]'::jsonb
  OR jsonb_typeof(m.participants) IS DISTINCT FROM 'array' OR jsonb_array_length(m.participants) NOT BETWEEN 2 AND 10
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(m.participants) x WHERE x->'is_horse' IS DISTINCT FROM 'true'::jsonb) THEN CONTINUE; END IF;
  -- Original blocked accounting/link evidence stays whole for its authoritative
  -- repair consumer. Do not convert a fresh direct reader into a historical seal.
  IF NOT EXISTS(SELECT 1 FROM public.union_pnl_cash_outcomes o WHERE o.table_id=k.table_id AND o.hand_number=k.hand_number
   AND o.hand_id=p.hand_id AND o.payload_hash=p.payload_hash AND o.game_scope=p.game_scope
   AND o.evidence->>'status'='ready' AND o.evidence->'basis_certified'='true'::jsonb AND o.evidence->'all_players_included'='true'::jsonb)
  THEN CONTINUE; END IF;
  evidence:=public.fn_pnl_cash_hand_evidence(k.table_id,k.hand_number);
  IF evidence->>'status' IS DISTINCT FROM 'ready' OR evidence->'basis_certified' IS DISTINCT FROM 'true'::jsonb
  OR evidence->'all_players_included' IS DISTINCT FROM 'true'::jsonb
  OR encode(extensions.digest(convert_to(evidence::text,'UTF8'),'sha256'),'hex') IS DISTINCT FROM k.accounting_evidence_sha256 THEN CONTINUE; END IF;
  -- An erased raw request must leave the exact accepted derived basis.
  IF NOT EXISTS(SELECT 1 FROM smarter_private.horse_retained_stats_basis b
   WHERE b.hand_id=p.hand_id AND b.table_id=p.table_id AND b.hand_number=p.hand_number
   AND b.original_stats_sha256=encode(extensions.digest(convert_to(COALESCE(p.accepted_request#>'{hand_row,_accepted_post_commit_facts,stats_facts}','null'::jsonb)::text,'UTF8'),'sha256'),'hex')
   AND b.compact_stats IS NOT DISTINCT FROM smarter_private.horse_compact_stats_basis(p.accepted_request#>'{hand_row,_accepted_post_commit_facts,stats_facts}')
   AND (p.atomic_receipt#>'{post_commit_payload,accepted_hand_facts,stats_facts}' IS NULL OR COALESCE(p.atomic_receipt#>'{post_commit_payload,accepted_hand_facts,stats_facts}','null'::jsonb) IS NOT DISTINCT FROM COALESCE(p.accepted_request#>'{hand_row,_accepted_post_commit_facts,stats_facts}','null'::jsonb))) THEN CONTINUE; END IF;
  IF NOT live_present THEN
   retained_boundary:=smarter_private.horse_cash_retained_boundary_digest(k.table_id,k.hand_number);
   IF retained_boundary IS NULL THEN CONTINUE; END IF;
  END IF;
  request_after:=smarter_private.horse_cash_compact_request(p.accepted_request);
  atomic_after:=smarter_private.horse_cash_compact_atomic(p.atomic_receipt);
  IF request_after IS NOT DISTINCT FROM p.accepted_request AND atomic_after IS NOT DISTINCT FROM p.atomic_receipt THEN CONTINUE; END IF;
  IF live_present THEN
  INSERT INTO smarter_private.horse_cash_payload_certificates(table_id,hand_number,hand_id,manifest_id,original_request_sha256,original_atomic_sha256,
   compact_request_sha256,compact_atomic_sha256,immutable_financial_sha256,live_atomic_sha256,accounting_evidence_sha256,accepted_at,settled_at)
  VALUES(p.table_id,p.hand_number,p.hand_id,p.manifest_id,p.payload_hash,
   encode(extensions.digest(convert_to(p.atomic_receipt::text,'UTF8'),'sha256'),'hex'),
   encode(extensions.digest(convert_to(request_after::text,'UTF8'),'sha256'),'hex'),
   encode(extensions.digest(convert_to(atomic_after::text,'UTF8'),'sha256'),'hex'),
   encode(extensions.digest(convert_to((to_jsonb(p)-ARRAY['accepted_request','atomic_receipt','accepted_at'])::text,'UTF8'),'sha256'),'hex'),
   encode(extensions.digest(convert_to(to_jsonb(a)::text,'UTF8'),'sha256'),'hex'),
   encode(extensions.digest(convert_to(evidence::text,'UTF8'),'sha256'),'hex'),p.accepted_at,k.settled_at);
  ELSE
   INSERT INTO smarter_private.horse_cash_postprune_certificates(table_id,hand_number,hand_id,manifest_id,original_request_sha256,
    original_atomic_sha256,compact_request_sha256,compact_atomic_sha256,immutable_financial_sha256,accounting_evidence_sha256,
    original_boundary_sha256,accepted_at,settled_at)
   VALUES(p.table_id,p.hand_number,p.hand_id,p.manifest_id,p.payload_hash,
    encode(extensions.digest(convert_to(p.atomic_receipt::text,'UTF8'),'sha256'),'hex'),
    encode(extensions.digest(convert_to(request_after::text,'UTF8'),'sha256'),'hex'),
    encode(extensions.digest(convert_to(atomic_after::text,'UTF8'),'sha256'),'hex'),
    encode(extensions.digest(convert_to((to_jsonb(p)-ARRAY['accepted_request','atomic_receipt','accepted_at'])::text,'UTF8'),'sha256'),'hex'),
    k.accounting_evidence_sha256,retained_boundary,p.accepted_at,k.settled_at);
  END IF;
  UPDATE public.cash_hand_provenance_receipts SET accepted_request=request_after,atomic_receipt=atomic_after WHERE table_id=p.table_id AND hand_number=p.hand_number;
  n:=n+1;
 END LOOP;
 RETURN n;
END $$;


ALTER FUNCTION smarter_private.compact_horse_cash_play_contents(p_hands uuid[]) OWNER TO postgres;

--
-- TOC entry 6039 (class 1255 OID 153556064)
-- Name: compact_horse_fact_cards(uuid[]); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.compact_horse_fact_cards(p_hand_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE id uuid; c smarter_private.horse_adaptive_disposal_certificates; n integer; total integer:=0; qualified uuid[]:=ARRAY[]::uuid[];
BEGIN
 IF cardinality(p_hand_ids)>10000 THEN RAISE EXCEPTION 'HORSE_FACT_CARD_BATCH_TOO_LARGE' USING ERRCODE='22023'; END IF;
 FOR id IN SELECT DISTINCT unnest(p_hand_ids) LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended('horse:fact-card-retention:'||id::text,0)) THEN CONTINUE; END IF;
  IF EXISTS(SELECT 1 FROM smarter_private.horse_fact_card_disposals WHERE hand_id=id)
   OR NOT smarter_private.horse_fact_cards_disposable(id) THEN CONTINUE; END IF;
  SELECT * INTO c FROM smarter_private.horse_adaptive_disposal_certificates WHERE hand_id=id;
  INSERT INTO smarter_private.horse_fact_card_disposals(hand_id,table_id,hand_number,request_hash,fact_rows)
   SELECT c.hand_id,c.table_id,c.hand_number,c.request_hash,count(*) FROM public.ca_hand_facts f WHERE f.hand_id=id
   ON CONFLICT(hand_id) DO NOTHING;
  qualified:=array_append(qualified,id);
 END LOOP;
 IF cardinality(qualified)>0 THEN
  UPDATE public.ca_hand_facts f SET hole_cards=NULL WHERE f.hand_id=ANY(qualified) AND f.hole_cards IS NOT NULL;
  GET DIAGNOSTICS total=ROW_COUNT;
 END IF;
 RETURN total;
END $$;


ALTER FUNCTION smarter_private.compact_horse_fact_cards(p_hand_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 7303 (class 1255 OID 153644016)
-- Name: compact_horse_review_raw(uuid[]); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.compact_horse_review_raw(p_hands uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    SET lock_timeout TO '2s'
    AS $$
DECLARE n integer;
BEGIN
 IF cardinality(p_hands)>250 THEN RAISE EXCEPTION 'HORSE_REVIEW_RETENTION_BATCH_TOO_LARGE'; END IF;
 UPDATE public.horse_hand_reviews r SET hole_cards=NULL,board=NULL,actions=NULL
 WHERE r.hand_id=ANY(p_hands) AND (r.hole_cards IS NOT NULL OR r.board IS NOT NULL OR r.actions IS NOT NULL)
 AND smarter_private.horse_review_raw_disposable(r.hand_id,r.table_id,r.played_at);
 GET DIAGNOSTICS n=ROW_COUNT; RETURN n;
END $$;


ALTER FUNCTION smarter_private.compact_horse_review_raw(p_hands uuid[]) OWNER TO postgres;

