COMMENT ON FUNCTION smarter_private.compact_horse_review_raw(p_hands uuid[]) IS 'Eight-day successful original horse-only raw review retention. Removes only hole_cards/board/actions; all net, leak, identity, receipt and diagnostic values remain. At most 250 supplied hand identities.';


--
-- TOC entry 6428 (class 1255 OID 153349825)
-- Name: compact_horse_settlement_keys(uuid[]); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.compact_horse_settlement_keys(p_hands uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE h public.hand_history; a public.hand_atomic_commits; p public.cash_hand_provenance_receipts;
 m public.cash_hand_participant_manifests; k public.settlement_idempotency_keys;
 evidence jsonb; stack_hand uuid; count_compacted integer:=0;
BEGIN
 IF p_hands IS NULL OR cardinality(p_hands)>250 THEN
  RAISE EXCEPTION 'HORSE_SETTLEMENT_COMPACTION_BATCH_INVALID' USING ERRCODE='22023'; END IF;
 FOR h IN SELECT * FROM public.hand_history WHERE id=ANY(p_hands) ORDER BY table_id,hand_number FOR UPDATE LOOP
  -- Cash only. Exactly eight elapsed days for both original history and final
  -- obligations; original manifest classification, never current profiles.
  IF h.table_id IS NULL OR h.tournament_id IS NOT NULL OR h.has_human IS DISTINCT FROM FALSE OR h.reported IS TRUE
  OR h.created_at IS NULL OR NOT isfinite(h.created_at) OR h.created_at>=now()-interval '8 days'
  OR EXISTS(SELECT 1 FROM public.hand_projection_outbox o WHERE o.hand_id=h.id)
  OR EXISTS(SELECT 1 FROM public.bbj_payouts b WHERE b.table_id=h.table_id AND b.hand_number=h.hand_number)
  OR EXISTS(SELECT 1 FROM public.tournament_knockout_candidates t WHERE t.hand_id=h.id AND t.state='pending')
  OR smarter_private.f06_hand_cards_unresolved(h.table_id,h.hand_number::bigint)
  OR smarter_private.f06_movement_boundary_retained(h.table_id,h.hand_number::bigint) THEN CONTINUE; END IF;
  SELECT * INTO a FROM public.hand_atomic_commits WHERE hand_id=h.id AND table_id=h.table_id AND hand_number=h.hand_number FOR UPDATE;
  IF NOT FOUND OR a.post_commit_completed_at IS NULL OR NOT isfinite(a.post_commit_completed_at) OR a.post_commit_completed_at>=now()-interval '8 days'
  OR a.post_commit_result->>'ok' IS DISTINCT FROM 'true' OR a.stack_result->>'success' IS DISTINCT FROM 'true'
  OR a.stack_result->>'conservation_checked' IS DISTINCT FROM 'true'
  OR jsonb_typeof(a.stack_result->'request') IS DISTINCT FROM 'object'
  OR NOT pg_input_is_valid(a.stack_result->>'hand_id','uuid') THEN CONTINUE; END IF;
  stack_hand:=(a.stack_result->>'hand_id')::uuid;
  IF EXISTS(SELECT 1 FROM smarter_private.horse_settlement_key_certificates c WHERE c.table_id=h.table_id AND c.stack_hand_id=stack_hand) THEN CONTINUE; END IF;
  SELECT * INTO p FROM public.cash_hand_provenance_receipts WHERE table_id=h.table_id AND hand_number=h.hand_number;
  IF NOT FOUND OR p.hand_id IS DISTINCT FROM h.id OR p.payload_hash IS DISTINCT FROM a.payload_hash
  OR p.atomic_receipt->'stack_result' IS DISTINCT FROM a.stack_result
  OR p.status IS DISTINCT FROM 'captured' OR p.funding_provenance_complete IS NOT TRUE OR p.all_players_included IS NOT TRUE
  OR p.issues IS DISTINCT FROM '[]'::jsonb THEN CONTINUE; END IF;
  SELECT * INTO m FROM public.cash_hand_participant_manifests WHERE id=p.manifest_id AND table_id=h.table_id AND hand_number=h.hand_number;
  IF NOT FOUND OR m.funding_provenance_complete IS NOT TRUE OR m.issues IS DISTINCT FROM '[]'::jsonb
  OR jsonb_typeof(m.participants) IS DISTINCT FROM 'array' OR jsonb_array_length(m.participants) NOT BETWEEN 2 AND 10
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(m.participants) x WHERE x->'is_horse' IS DISTINCT FROM 'true'::jsonb)
  OR jsonb_typeof(h.players) IS DISTINCT FROM 'array'
  OR jsonb_array_length(h.players) IS DISTINCT FROM jsonb_array_length(m.participants)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(h.players) x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(m.participants) y WHERE y->>'user_id'=x->>'userId'))
  THEN CONTINUE; END IF;
  SELECT * INTO k FROM public.settlement_idempotency_keys WHERE table_id=h.table_id AND hand_id=stack_hand FOR UPDATE;
  IF NOT FOUND OR k.status IS DISTINCT FROM 'succeeded' OR k.completed_at IS NULL OR k.error IS NOT NULL
  OR k.result IS DISTINCT FROM a.stack_result OR NOT k.result ? 'request' THEN CONTINUE; END IF;
  evidence:=public.fn_pnl_cash_hand_evidence(h.table_id,h.hand_number::bigint);
  IF evidence->>'status' IS DISTINCT FROM 'ready' OR evidence->'basis_certified' IS DISTINCT FROM 'true'::jsonb
  OR evidence->'all_players_included' IS DISTINCT FROM 'true'::jsonb THEN CONTINUE; END IF;
  INSERT INTO smarter_private.horse_settlement_key_certificates(table_id,stack_hand_id,hand_number,history_hand_id,manifest_id,
   original_result_sha256,original_request_sha256,compact_result,accounting_evidence_sha256,settled_at)
  VALUES(h.table_id,stack_hand,h.hand_number,h.id,m.id,
   encode(extensions.digest(convert_to(k.result::text,'UTF8'),'sha256'),'hex'),
   encode(extensions.digest(convert_to((k.result->'request')::text,'UTF8'),'sha256'),'hex'),k.result-'request',
   encode(extensions.digest(convert_to(evidence::text,'UTF8'),'sha256'),'hex'),a.post_commit_completed_at);
  UPDATE public.settlement_idempotency_keys SET result=result-'request' WHERE table_id=h.table_id AND hand_id=stack_hand;
  count_compacted:=count_compacted+1;
 END LOOP;
 RETURN count_compacted;
END $$;


ALTER FUNCTION smarter_private.compact_horse_settlement_keys(p_hands uuid[]) OWNER TO postgres;

--
-- TOC entry 5686 (class 1255 OID 153187222)
-- Name: compact_settled_horse_requests(uuid[]); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.compact_settled_horse_requests(p_submission_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE n integer;
BEGIN
 IF cardinality(p_submission_ids)>10000 THEN RAISE EXCEPTION 'HORSE_REQUEST_BATCH_TOO_LARGE' USING ERRCODE='22023'; END IF;
 PERFORM smarter_private.capture_horse_adaptive_disposals(p_submission_ids);
 PERFORM smarter_private.capture_horse_stats_basis(p_submission_ids);
 PERFORM smarter_private.compact_horse_fact_cards(p_submission_ids);
 UPDATE smarter_private.hand_submissions s SET request='{}'::jsonb
 WHERE submission_id=ANY(p_submission_ids) AND smarter_private.horse_request_payload_disposable(s.submission_id);
 GET DIAGNOSTICS n=ROW_COUNT;
 RETURN n;
END $$;


ALTER FUNCTION smarter_private.compact_settled_horse_requests(p_submission_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 7531 (class 1255 OID 118729773)
-- Name: continue_retired_undealt_paid_entry(uuid); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.continue_retired_undealt_paid_entry(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE v jsonb; e jsonb; got jsonb; lease public.engine_tournament_leases;
 spin_before jsonb; spin_after jsonb; gate jsonb; result jsonb; results jsonb:='[]'; restored integer:=0; old_data_actor text; old_data_generation text;
BEGIN
 IF session_user<>'postgres' OR auth.role() IS NOT NULL THEN
  RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_CALLER_REFUSED' USING ERRCODE='42501';
 END IF;
 PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id,NULL);
 SELECT expected INTO v FROM smarter_private.retirement_undealt_paid_entry_qualification
 WHERE tournament_id=p_tournament_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_NOT_QUALIFIED' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM smarter_private.retirement_undealt_paid_entry_restorations WHERE tournament_id=p_tournament_id) THEN
  IF NOT EXISTS(SELECT 1 FROM smarter_private.retirement_undealt_paid_entry_restorations r WHERE r.tournament_id=p_tournament_id AND r.qualification_hash=md5(v::text)) THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_REPLAY_CHANGED' USING ERRCODE='55000';END IF;
  RETURN jsonb_build_object('ok',true,'replayed',true);
 END IF;
 IF public.fn_platform_frozen() THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_FROZEN' USING ERRCODE='55000';END IF;
 -- Canonical seat acquisition order: every cap/mission before launch/event/chair rows.
 PERFORM pg_advisory_xact_lock_shared(530090,1);
 PERFORM public.fn_ca_lock_mtt_admission_contract();
 FOR e IN SELECT value FROM jsonb_array_elements(v->'rows') ORDER BY value->'roster'->>'user_id' LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('table_cap:'||(e->'roster'->>'user_id'),0));
 END LOOP;
 FOR e IN SELECT value FROM jsonb_array_elements(v->'rows') ORDER BY value->'roster'->>'user_id' LOOP
  PERFORM public.fn_lock_daily_mission_user((e->'roster'->>'user_id')::uuid);
 END LOOP;
 gate:=public.fn_ca_lock_tournament_seat_acquisition(p_tournament_id,(v->'table'->>'id')::uuid,NULL);
 IF gate->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_ADMISSION_REFUSED' USING ERRCODE='55000';END IF;
 SELECT * INTO lease FROM public.engine_tournament_leases WHERE tournament_id=p_tournament_id FOR UPDATE;
 IF NOT FOUND OR lease.protocol_version IS DISTINCT FROM 2 OR lease.lease_generation IS NULL OR nullif(lease.instance_id,'') IS NULL OR lease.heartbeat_at IS NULL OR lease.heartbeat_at<clock_timestamp()-interval '30 seconds'
 THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_LEASE_REFUSED' USING ERRCODE='55000';END IF;
 SELECT to_jsonb(t) INTO got FROM public.tournaments t WHERE id=p_tournament_id FOR UPDATE;
 IF (got @> (v->'event')) IS DISTINCT FROM true THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_EVENT_CHANGED' USING ERRCODE='55000';END IF;
 SELECT to_jsonb(t) INTO got FROM public.tables t WHERE id=(v->'table'->>'id')::uuid FOR UPDATE;
 IF (got @> (v->'table')) IS DISTINCT FROM true OR EXISTS(SELECT 1 FROM smarter_private.hand_submissions s WHERE s.table_id=(v->'table'->>'id')::uuid)
 OR EXISTS(SELECT 1 FROM public.hand_history h WHERE h.table_id=(v->'table'->>'id')::uuid)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_hand_permits h WHERE h.table_id=(v->'table'->>'id')::uuid)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_operations o WHERE o.tournament_id=p_tournament_id AND o.state IN ('park_requested','begun'))
 OR EXISTS(SELECT 1 FROM public.tournament_seat_move_receipts r WHERE r.tournament_id=p_tournament_id)
 OR EXISTS(SELECT 1 FROM public.tournament_payouts r WHERE r.tournament_id=p_tournament_id)
 OR EXISTS(SELECT 1 FROM public.tournament_cancellation_receipts r WHERE r.tournament_id=p_tournament_id)
 OR EXISTS(SELECT 1 FROM public.hand_atomic_commits r WHERE r.table_id=(v->'table'->>'id')::uuid)
 OR EXISTS(SELECT 1 FROM public.hand_private_state r WHERE r.table_id=(v->'table'->>'id')::uuid)
 OR EXISTS(SELECT 1 FROM public.table_hole_cards r WHERE r.table_id=(v->'table'->>'id')::uuid)
 OR EXISTS(SELECT 1 FROM public.hand_state_snapshots r WHERE r.table_id=(v->'table'->>'id')::uuid)
 OR (SELECT count(*) FROM public.tournament_players WHERE tournament_id=p_tournament_id)<>3
 OR (SELECT count(*) FROM public.table_seats WHERE table_id=(v->'table'->>'id')::uuid)<>3
 OR (SELECT count(*) FROM public.tournament_participant_funding_receipts WHERE tournament_id=p_tournament_id)<>3
 THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_LATER_OBLIGATION' USING ERRCODE='55000';END IF;
 SELECT jsonb_build_object('reserve',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.id) FROM public.spin_reserve_ledger r WHERE tournament_id=p_tournament_id),'journal',(SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) FROM public.chip_ledger l WHERE tournament_id=p_tournament_id AND category='spin_entry'),'draw',(SELECT jsonb_agg(to_jsonb(d) ORDER BY d.launch_id) FROM public.spin_draw_receipts d WHERE tournament_id=p_tournament_id)) INTO spin_before;
 IF spin_before IS DISTINCT FROM v->'spin' THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_SPIN_RECEIPT_CHANGED' USING ERRCODE='55000';END IF;
 -- Lock and verify the complete original records before the first changed row.
 FOR e IN SELECT value FROM jsonb_array_elements(v->'rows') ORDER BY value->'roster'->>'user_id' LOOP
  SELECT to_jsonb(r)-'username' INTO got FROM public.tournament_players r WHERE id=(e->'roster'->>'id')::uuid FOR UPDATE;
  IF got IS DISTINCT FROM e->'roster' THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_ROSTER_CHANGED' USING ERRCODE='55000';END IF;
  SELECT to_jsonb(s)-'updated_at' INTO got FROM public.table_seats s WHERE id=(e->'seat'->>'id')::uuid FOR UPDATE;
  IF (got @> (e->'seat')) IS DISTINCT FROM true THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_CHAIR_CHANGED' USING ERRCODE='55000';END IF;
  SELECT to_jsonb(f) INTO got FROM public.tournament_participant_funding_receipts f WHERE id=(e->'funding'->>'id')::uuid;
  IF got IS DISTINCT FROM e->'funding' THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_FUNDING_CHANGED' USING ERRCODE='55000';END IF;
  SELECT to_jsonb(l) INTO got FROM public.chip_ledger l WHERE id=(e->'funding'->>'ledger_id')::uuid;
  IF got IS DISTINCT FROM e->'funding'->'ledger_snapshot' THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_LEDGER_CHANGED' USING ERRCODE='55000';END IF;
  SELECT to_jsonb(w) INTO got FROM public.wallet_transactions w WHERE id=(e->'funding'->>'wallet_transaction_id')::uuid;
  IF got IS DISTINCT FROM e->'funding'->'wallet_snapshot' THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_DEBIT_CHANGED' USING ERRCODE='55000';END IF;
  SELECT to_jsonb(x) INTO got FROM public.tournament_refund_entitlements x WHERE id=(e->'funding'->>'entitlement_id')::uuid;
  IF got IS DISTINCT FROM e->'funding'->'entitlement_snapshot'
  OR EXISTS(SELECT 1 FROM public.tournament_refund_tranches x WHERE x.entitlement_id=(e->'funding'->>'entitlement_id')::uuid)
  OR EXISTS(SELECT 1 FROM public.tournament_tickets x WHERE x.source_refund_entitlement_id=(e->'funding'->>'entitlement_id')::uuid)
  THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_ENTITLEMENT_CONSUMED' USING ERRCODE='55000';END IF;
  IF e->'retirement'<>'null'::jsonb THEN
   IF NOT EXISTS(SELECT 1 FROM smarter_private.patterned_identity_retirements r
    JOIN public.profiles p ON p.id=r.old_id
    WHERE r.old_id=(e->'retirement'->>'user_id')::uuid AND r.cohort=e->'retirement'->>'cohort'
     AND r.benched_at=(e->'retirement'->>'benched_at')::timestamptz
     AND r.retired_at=(e->'retirement'->>'retired_at')::timestamptz
     AND r.replacement_horse_id IS NULL
     AND p.horse_status='disabled' AND p.status='deleted') THEN
    RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_RETIREMENT_CHANGED' USING ERRCODE='55000';END IF;
  END IF;
 END LOOP;
 old_data_actor:=current_setting('app.smarter_data_actor',true);
 old_data_generation:=current_setting('app.smarter_data_generation',true);
 PERFORM set_config('app.smarter_data_actor',lease.instance_id,true);
 PERFORM set_config('app.smarter_data_generation',lease.lease_generation::text,true);
 FOR e IN SELECT value FROM jsonb_array_elements(v->'rows') ORDER BY value->'roster'->>'user_id' LOOP
  IF e->'retirement'='null'::jsonb THEN CONTINUE;END IF;
  UPDATE public.tournament_players SET status='playing',eliminated_at=NULL
  WHERE id=(e->'roster'->>'id')::uuid;
  result:=public.fn_assign_tournament_player_seat_atomic(p_tournament_id,(e->'roster'->>'user_id')::uuid,
    (v->'table'->>'id')::uuid,(e->'roster'->>'seat_number')::integer);
  IF result->>'ok' IS DISTINCT FROM 'true' OR (result->>'stack')::numeric<>1000
   OR (result->>'seat_id')::uuid<>(e->'seat'->>'id')::uuid THEN
   RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_NATIVE_ASSIGNMENT_REFUSED: %',result USING ERRCODE='P0404';END IF;
  results:=results||jsonb_build_array(result);restored:=restored+1;
 END LOOP;
 PERFORM set_config('app.smarter_data_actor',coalesce(old_data_actor,''),true);
 PERFORM set_config('app.smarter_data_generation',coalesce(old_data_generation,''),true);
 IF restored<>2 OR (SELECT count(*) FROM public.tournament_players WHERE tournament_id=p_tournament_id AND status='playing' AND chips=1000)<>3
 OR (SELECT count(*) FROM public.table_seats WHERE table_id=(v->'table'->>'id')::uuid AND left_at IS NULL AND stack=1000 AND NOT is_sitting_out)<>3
 THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_FINAL_CUSTODY_REFUSED' USING ERRCODE='55000';END IF;
 SELECT jsonb_build_object('reserve',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.id) FROM public.spin_reserve_ledger r WHERE tournament_id=p_tournament_id),'journal',(SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) FROM public.chip_ledger l WHERE tournament_id=p_tournament_id AND category='spin_entry'),'draw',(SELECT jsonb_agg(to_jsonb(d) ORDER BY d.launch_id) FROM public.spin_draw_receipts d WHERE tournament_id=p_tournament_id)) INTO spin_after;
 IF spin_after IS DISTINCT FROM spin_before THEN RAISE EXCEPTION 'UNDEALT_PAID_ENTRY_SPIN_EFFECT_CHANGED' USING ERRCODE='P0404';END IF;
 INSERT INTO smarter_private.retirement_undealt_paid_entry_restorations
 (tournament_id,qualification_hash,transaction_id,instance_id,lease_generation,native_results)
 VALUES(p_tournament_id,md5(v::text),txid_current(),lease.instance_id,lease.lease_generation,results);
 RETURN jsonb_build_object('ok',true,'restored',restored,'native_results',results);
END;$$;


ALTER FUNCTION smarter_private.continue_retired_undealt_paid_entry(p_tournament_id uuid) OWNER TO postgres;

--
-- TOC entry 7430 (class 1255 OID 180398958)
-- Name: deleted_wallet_published_rakeback_reserve(uuid, uuid); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.deleted_wallet_published_rakeback_reserve(p_club uuid, p_user uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
 r public.rakeback_periods%ROWTYPE;
 c public.accounting_rakeback_period_calculations%ROWTYPE;
 reserved numeric:=0;
 locked_period_ids uuid[];
BEGIN
 IF p_club IS NULL OR p_user IS NULL THEN
  RAISE EXCEPTION 'deleted_wallet_reserve_identity_required' USING ERRCODE='22023';
 END IF;
 -- Publishers lock an existing period FOR UPDATE before adding its certificate.
 -- NOWAIT is essential: caller may already own the member row, while the
 -- ordinary stage owns period rows before member rows. Never wait in reverse.
 SELECT coalesce(array_agg(locked.id ORDER BY locked.id),ARRAY[]::uuid[]) INTO locked_period_ids
 FROM (SELECT rp.id FROM public.rakeback_periods rp
       WHERE rp.club_id=p_club AND rp.status='pending'
       ORDER BY rp.id FOR SHARE NOWAIT) locked;
 -- Visit ONLY the locked admission cohort, not a second fresh pending scan.
 FOR r IN SELECT rp.* FROM public.rakeback_periods rp
          WHERE rp.id=ANY(locked_period_ids) ORDER BY rp.id
 LOOP
  -- Select latest FIRST. An invalid latest certificate must not expose funds
  -- by falling back to an older certificate or disappearing from a filtered sum.
  SELECT pc.* INTO c FROM public.accounting_rakeback_period_calculations pc
  WHERE pc.period_id=r.id ORDER BY pc.id DESC LIMIT 1;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'deleted_wallet_reserve_latest_certificate_required' USING ERRCODE='55000';
  END IF;
  IF r.id IS NULL OR r.club_id IS NULL OR r.club_id IS DISTINCT FROM p_club
   OR r.user_id IS NULL OR r.period_start IS NULL OR r.period_end IS NULL
   OR NOT isfinite(r.period_start) OR NOT isfinite(r.period_end)
   OR r.period_start>r.period_end OR extract(isodow FROM r.period_start)<>1 OR r.period_end<>r.period_start+6
   OR r.rake_generated IS NULL OR r.total_rake_paid IS NULL
   OR r.rakeback_amount IS NULL OR r.rakeback_earned IS NULL OR r.rakeback_rate IS NULL
   OR c.id IS NULL OR c.period_id IS DISTINCT FROM r.id
   OR c.accounting_version IS DISTINCT FROM 2
   OR c.club_id IS DISTINCT FROM r.club_id OR c.player_id IS DISTINCT FROM r.user_id
   OR c.period_start IS DISTINCT FROM r.period_start OR c.period_end IS DISTINCT FROM r.period_end
   OR c.rake_generated IS NULL OR c.rake_generated IS DISTINCT FROM r.rake_generated
   OR c.rake_generated IS DISTINCT FROM r.total_rake_paid
   OR c.rake_generated<0 OR c.rake_generated::text IN ('NaN','Infinity','-Infinity')
   OR c.rakeback_amount IS NULL OR c.rakeback_amount IS DISTINCT FROM r.rakeback_amount
   OR c.rakeback_amount IS DISTINCT FROM r.rakeback_earned
   OR c.rakeback_amount<0 OR c.rakeback_amount>c.rake_generated OR c.rakeback_amount<>round(c.rakeback_amount,2)
   OR c.rakeback_amount::text IN ('NaN','Infinity','-Infinity')
   OR c.display_rate IS NULL OR c.display_rate IS DISTINCT FROM r.rakeback_rate
   OR c.display_rate<0 OR c.display_rate>1 OR c.display_rate<>round(c.display_rate,4)
   OR c.display_rate::text IN ('NaN','Infinity','-Infinity')
   OR c.payer_kind IS NULL OR c.payer_kind NOT IN ('agent','club','split')
   OR (c.payer_kind='agent') IS DISTINCT FROM (c.payer_user_id IS NOT NULL)
   OR c.payer_user_id=r.user_id
   OR c.source_fingerprint IS NULL OR c.source_fingerprint !~ '^[0-9a-f]{32}$'
  THEN
   RAISE EXCEPTION 'deleted_wallet_reserve_certificate_identity_invalid' USING ERRCODE='55000';
  END IF;
  -- The owning R3 stage refuses any existing payout for a pending period.
  -- A pending row plus a paid receipt must never be mistaken for free money.
  IF EXISTS(SELECT 1 FROM public.rakeback_period_payouts pp WHERE pp.rakeback_period_id=r.id) THEN
   RAISE EXCEPTION 'deleted_wallet_reserve_pending_payout_conflict' USING ERRCODE='55000';
  END IF;
  IF c.payer_kind='split' THEN
   -- Same immutable certificate producer; retain all child liabilities before
   -- any deleted account's free net is returned by the existing R2/R3 owner.
   reserved:=reserved+COALESCE((SELECT sum(g.owed) FROM smarter_private.rakeback_certificate_payers(c.id)g WHERE g.payer_kind='agent' AND g.payer_user=p_user),0);
  ELSIF c.payer_kind='agent' AND c.payer_user_id=p_user THEN
   reserved:=reserved+c.rakeback_amount;
  END IF;
 END LOOP;
 RETURN reserved;
END;
$_$;


ALTER FUNCTION smarter_private.deleted_wallet_published_rakeback_reserve(p_club uuid, p_user uuid) OWNER TO postgres;

--
-- TOC entry 8536 (class 1255 OID 153542041)
-- Name: enable_horse_adaptive_retention(text); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.enable_horse_adaptive_retention(p_release text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $_$
BEGIN
 IF p_release IS NULL OR p_release!~'^[a-f0-9]{40}$' THEN RAISE EXCEPTION 'ADAPTIVE_CONSUMER_RELEASE_REQUIRED'; END IF;
 UPDATE smarter_private.horse_adaptive_retention_activation SET enabled=true,consumer_release=p_release WHERE singleton;
END $_$;


ALTER FUNCTION smarter_private.enable_horse_adaptive_retention(p_release text) OWNER TO postgres;

--
-- TOC entry 9500 (class 1255 OID 216819641)
-- Name: ensure_rakeback_payer_contracts(bigint); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.ensure_rakeback_payer_contracts(p_calculation bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE c public.accounting_rakeback_period_calculations%ROWTYPE;r public.rakeback_periods%ROWTYPE;plan jsonb;generated numeric;unrounded numeric;n bigint;distinct_n bigint;
BEGIN
 SELECT * INTO STRICT c FROM public.accounting_rakeback_period_calculations WHERE id=p_calculation;
 SELECT * INTO STRICT r FROM public.rakeback_periods WHERE id=c.period_id FOR UPDATE;
 IF r.status IS DISTINCT FROM 'pending' OR c.id IS DISTINCT FROM(SELECT max(x.id)FROM public.accounting_rakeback_period_calculations x WHERE x.period_id=r.id)
  OR c.accounting_version IS DISTINCT FROM 2 OR(c.club_id,c.player_id,c.period_start,c.period_end)IS DISTINCT FROM(r.club_id,r.user_id,r.period_start,r.period_end)
  OR(c.rake_generated,c.rake_generated,c.rakeback_amount,c.rakeback_amount,c.display_rate)IS DISTINCT FROM(r.rake_generated,r.total_rake_paid,r.rakeback_amount,r.rakeback_earned,r.rakeback_rate)
  OR c.source_fingerprint IS DISTINCT FROM md5(jsonb_build_object('allocations',c.source_allocations,'rake',c.rake_generated,'amount',c.rakeback_amount,'rate',c.display_rate)::text)
 THEN RAISE EXCEPTION 'rakeback_payer_certificate_not_current_pending' USING ERRCODE='23514';END IF;
 SELECT count(*),count(DISTINCT ROW(a->>'source_type',a->>'source_id')),sum((a->>'rake_credit')::numeric),sum((a->>'rake_credit')::numeric*(a->>'rate')::numeric)
 INTO n,distinct_n,generated,unrounded FROM jsonb_array_elements(c.source_allocations)a;
 IF n=0 OR n<>distinct_n OR generated IS DISTINCT FROM c.rake_generated OR round(unrounded,2)IS DISTINCT FROM c.rakeback_amount
  OR c.display_rate IS DISTINCT FROM(CASE WHEN generated>0 THEN round(unrounded/generated,4)ELSE 0 END)
  OR EXISTS(SELECT FROM jsonb_array_elements(c.source_allocations)a WHERE a->>'source_type'IS NULL OR a->>'source_type'NOT IN('cash_rake_accrual','tournament_fee_accrual')OR NULLIF(a->>'source_id','')IS NULL OR NULLIF(a->>'payer_user_id','')::uuid=c.player_id OR NULLIF(a->>'coordinator_union_id','')::uuid IS DISTINCT FROM c.coordinator_union_id)
 THEN RAISE EXCEPTION 'rakeback_payer_certificate_allocations_invalid' USING ERRCODE='23514';END IF;
 plan:=smarter_private.rakeback_payer_plan(c.source_allocations,c.rakeback_amount);
 IF c.payer_kind='split' THEN
  IF c.payer_user_id IS NOT NULL OR jsonb_array_length(plan)<2 THEN RAISE EXCEPTION 'split_rakeback_payers_required' USING ERRCODE='23514';END IF;
 ELSIF jsonb_array_length(plan)<>1 OR plan->0->>'payer_kind'IS DISTINCT FROM c.payer_kind OR NULLIF(plan->0->>'payer_user_id','')::uuid IS DISTINCT FROM c.payer_user_id
 THEN RAISE EXCEPTION 'rakeback_certificate_payer_disagrees' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT FROM public.accounting_rakeback_payer_contracts g LEFT JOIN jsonb_array_elements(plan)p ON g.payer_kind=p->>'payer_kind'AND g.payer_entity_id=COALESCE(NULLIF(p->>'payer_user_id','')::uuid,c.club_id)
 WHERE g.calculation_id=c.id AND(p IS NULL OR g.payer_user_id IS DISTINCT FROM NULLIF(p->>'payer_user_id','')::uuid OR g.amount IS DISTINCT FROM(p->>'amount')::numeric OR g.unrounded IS DISTINCT FROM(p->>'unrounded')::numeric OR g.rake IS DISTINCT FROM(p->>'rake')::numeric OR g.source_count IS DISTINCT FROM(p->>'source_count')::bigint OR g.source_fingerprint IS DISTINCT FROM c.source_fingerprint))
 THEN RAISE EXCEPTION 'existing_rakeback_payer_contract_disagrees' USING ERRCODE='23514';END IF;
 INSERT INTO public.accounting_rakeback_payer_contracts(calculation_id,payer_kind,payer_entity_id,payer_user_id,amount,unrounded,rake,source_count,source_fingerprint)
 SELECT c.id,p->>'payer_kind',COALESCE(NULLIF(p->>'payer_user_id','')::uuid,c.club_id),NULLIF(p->>'payer_user_id','')::uuid,(p->>'amount')::numeric,(p->>'unrounded')::numeric,(p->>'rake')::numeric,(p->>'source_count')::bigint,c.source_fingerprint
 FROM jsonb_array_elements(plan)p WHERE NOT EXISTS(SELECT FROM public.accounting_rakeback_payer_contracts g WHERE g.calculation_id=c.id AND g.payer_kind=p->>'payer_kind'AND g.payer_entity_id=COALESCE(NULLIF(p->>'payer_user_id','')::uuid,c.club_id));
END $$;


ALTER FUNCTION smarter_private.ensure_rakeback_payer_contracts(p_calculation bigint) OWNER TO postgres;

--
-- TOC entry 6281 (class 1255 OID 36211741)
-- Name: f06_abort_receipt_immutable(); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.f06_abort_receipt_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN RAISE EXCEPTION 'F06_ABORT_RECEIPT_IMMUTABLE' USING ERRCODE='55000'; END $$;


ALTER FUNCTION smarter_private.f06_abort_receipt_immutable() OWNER TO postgres;

--
-- TOC entry 5790 (class 1255 OID 36211739)
-- Name: f06_aborted_generation_guard(); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.f06_aborted_generation_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'smarter_private'
    AS $$
BEGIN
 IF smarter_private.f06_generation_aborted(NEW.tournament_id,NEW.lease_generation) THEN
 RAISE EXCEPTION 'F06_ABORTED_GENERATION_FENCED' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION smarter_private.f06_aborted_generation_guard() OWNER TO postgres;

--
-- TOC entry 3346 (class 1255 OID 36211743)
-- Name: f06_aborted_hand_guard(); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.f06_aborted_hand_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE t uuid;
BEGIN
 SELECT tournament_id INTO t FROM smarter_private.f06_hand_permits
 WHERE table_id=NEW.table_id AND hand_number=NEW.hand_number;
 IF FOUND THEN
 -- A direct SQL insert may already own its row. Never wait for an earlier lane.
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('ca:tournament-terminal-settlement:v1',0))
 OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('ca:tournament-terminal-settlement:v1:'||t::text,0)) THEN
 RAISE EXCEPTION 'F06_RETRY_CANONICAL_LANE' USING ERRCODE='55P03'; END IF;
 IF EXISTS(SELECT 1 FROM smarter_private.f06_unsettled_hand_aborts
 WHERE table_id=NEW.table_id AND hand_number=NEW.hand_number)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_generation_abort_hands
 WHERE table_id=NEW.table_id AND hand_number=NEW.hand_number)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_mixed_abort_hands
 WHERE table_id=NEW.table_id AND hand_number=NEW.hand_number) THEN
 RAISE EXCEPTION 'F06_ABORTED_HAND_FENCED' USING ERRCODE='55000'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION smarter_private.f06_aborted_hand_guard() OWNER TO postgres;

