--
-- TOC entry 7687 (class 1255 OID 28810996)
-- Name: f06_accept_hand(); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.f06_accept_hand() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
BEGIN
 IF NEW.post_commit_completed_at IS NOT NULL THEN
 UPDATE smarter_private.f06_hand_permits SET state='accepted',evidence_id=NEW.hand_id
 WHERE table_id=NEW.table_id AND hand_number=NEW.hand_number AND state='reserved';
 DELETE FROM smarter_private.f06_hand_dispatch d USING smarter_private.f06_hand_permits h WHERE h.permit_id=d.permit_id AND h.table_id=NEW.table_id AND h.hand_number=NEW.hand_number;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION smarter_private.f06_accept_hand() OWNER TO postgres;

--
-- TOC entry 6868 (class 1255 OID 28811018)
-- Name: f06_allocate_number_above(bigint); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.f06_allocate_number_above(floor_number bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    SET lock_timeout TO '2s'
    AS $$
DECLARE n bigint; prior bigint; called boolean;
BEGIN
 IF floor_number IS NULL OR floor_number<1000000 OR floor_number>9007199254740991 THEN
 RAISE EXCEPTION 'F06_HAND_NUMBER_UNSAFE' USING ERRCODE='22003'; END IF;
 SELECT last_value,is_called INTO prior,called FROM public.global_hand_number_seq;
 IF prior>=floor_number THEN
   -- Above the floor nextval cannot return below it: setval runs only under
   -- the exclusive lock below and only moves the sequence forward. Shared
   -- holders never wait on one another; the shared lock only excludes setval.
   PERFORM pg_advisory_xact_lock_shared(hashtextextended('f06:global-hand-number-allocation',0));
   IF prior>9007199254740991 OR (prior=9007199254740991 AND called) THEN
   RAISE EXCEPTION 'F06_HAND_NUMBER_UNSAFE' USING ERRCODE='22003'; END IF;
   n:=nextval('public.global_hand_number_seq');
   IF n>9007199254740991 OR n<floor_number THEN
   RAISE EXCEPTION 'F06_HAND_NUMBER_UNSAFE' USING ERRCODE='22003'; END IF;
   RETURN n;
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('f06:global-hand-number-allocation',0));
 SELECT last_value,is_called INTO prior,called FROM public.global_hand_number_seq;
 IF prior<floor_number THEN
   -- Real sequence relation barrier also serializes pre-upgrade no-advisory callers.
   -- CACHE 1 is already preimage-guarded; this changes no sequence policy.
   ALTER SEQUENCE public.global_hand_number_seq CACHE 1;
   SELECT last_value,is_called INTO prior,called FROM public.global_hand_number_seq;
 END IF;
 IF prior>9007199254740991 OR (prior=9007199254740991 AND called) THEN
 RAISE EXCEPTION 'F06_HAND_NUMBER_UNSAFE' USING ERRCODE='22003'; END IF;
 n:=nextval('public.global_hand_number_seq');
 IF n>9007199254740991 THEN RAISE EXCEPTION 'F06_HAND_NUMBER_UNSAFE' USING ERRCODE='22003'; END IF;
 IF n<floor_number THEN n:=setval('public.global_hand_number_seq',floor_number,true); END IF;
 RETURN n;
END $$;


ALTER FUNCTION smarter_private.f06_allocate_number_above(floor_number bigint) OWNER TO postgres;

--
-- TOC entry 3465 (class 1255 OID 37679309)
-- Name: f06_assert_movement(uuid); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.f06_assert_movement(p_break uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE a smarter_private.f06_movement_admissions; o smarter_private.f06_operations;
 r jsonb; actual jsonb; winner jsonb; movement public.tournament_seat_move_receipts; remaining integer:=0; mixed_generation uuid;
 g uuid:=NULLIF(current_setting('app.smarter_tournament_lease_generation',true),'')::uuid;
 -- An add-on the player bought while the park waited (2026-10-02): its chips
 -- are the event's addon_chips, and its registration says add_on.
 addon numeric:=0; credited jsonb; strip text[]:='{current_bounty,bounty_winnings,bounties_collected,mystery_bounty_value}';
BEGIN
 mixed_generation:=smarter_private.f06_mixed_movement_generation(p_break);
 IF NOT EXISTS(SELECT 1 FROM smarter_private.f06_movement_admissions WHERE break_id=p_break) THEN RETURN; END IF;
 SELECT * INTO o FROM smarter_private.f06_operations WHERE break_id=p_break;
 SELECT * INTO a FROM smarter_private.f06_movement_admissions WHERE break_id=p_break AND custody_id=o.custody_id;
 IF NOT FOUND OR o.custody_generation IS DISTINCT FROM a.lease_generation OR o.revision IS DISTINCT FROM a.revision
 OR o.lifecycle IS DISTINCT FROM a.lifecycle OR o.source_table_id IS DISTINCT FROM a.table_id
 OR o.tournament_id IS DISTINCT FROM a.tournament_id OR (g IS DISTINCT FROM a.lease_generation AND g IS DISTINCT FROM mixed_generation)
 OR o.state NOT IN ('park_requested','begun','close_confirmed') THEN
 RAISE EXCEPTION 'F06_MOVEMENT_CUSTODY_CHANGED' USING ERRCODE='55000'; END IF;
 PERFORM smarter_private.f06_authority(a.tournament_id,COALESCE(mixed_generation,a.lease_generation),false);
 -- A never-dealt park's proof (f06_movement_never_dealt_prior) names no hand:
 -- its boundary holds while nothing of any hand exists on the table.
 IF a.proof->'first_hand'='true'::jsonb THEN
 IF a.proof->'atomic' IS DISTINCT FROM 'null'::jsonb OR a.proof->'history' IS DISTINCT FROM 'null'::jsonb
 OR a.proof->'permits' IS DISTINCT FROM '[]'::jsonb
 OR NOT EXISTS(SELECT 1 FROM public.tables WHERE id=a.table_id AND tournament_id=a.tournament_id AND f06_lifecycle=a.lifecycle)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_hand_permits WHERE table_id=a.table_id)
 OR EXISTS(SELECT 1 FROM public.hand_atomic_commits WHERE table_id=a.table_id)
 OR EXISTS(SELECT 1 FROM public.hand_history WHERE table_id=a.table_id)
 OR EXISTS(SELECT 1 FROM public.hand_private_state WHERE table_id=a.table_id)
 OR EXISTS(SELECT 1 FROM public.table_hole_cards WHERE table_id=a.table_id)
 OR EXISTS(SELECT 1 FROM public.hand_state_snapshots WHERE table_id=a.table_id) THEN
 RAISE EXCEPTION 'F06_MOVEMENT_BOUNDARY_CHANGED' USING ERRCODE='55000'; END IF;
 ELSE
 IF NOT EXISTS(SELECT 1 FROM public.tables WHERE id=a.table_id AND tournament_id=a.tournament_id AND f06_lifecycle=a.lifecycle)
 OR smarter_private.f06_movement_permits(a.tournament_id,a.table_id,(a.proof#>>'{atomic,hand_number}')::bigint) IS DISTINCT FROM a.proof->'permits'
 OR EXISTS(SELECT 1 FROM public.hand_state_snapshots WHERE table_id=a.table_id AND NOT is_complete)
 OR EXISTS(SELECT 1 FROM public.hand_private_state WHERE table_id=a.table_id AND hand_number>(a.proof#>>'{atomic,hand_number}')::bigint)
 OR EXISTS(SELECT 1 FROM public.hand_history WHERE table_id=a.table_id AND hand_number>(a.proof#>>'{atomic,hand_number}')::bigint)
 OR EXISTS(SELECT 1 FROM public.hand_atomic_commits WHERE table_id=a.table_id AND (hand_number>(a.proof#>>'{atomic,hand_number}')::bigint OR committed_at>(a.proof#>>'{atomic,committed_at}')::timestamptz))
 OR NOT EXISTS(SELECT 1 FROM public.hand_atomic_commits x WHERE hand_id=(a.proof#>>'{atomic,hand_id}')::uuid AND (SELECT jsonb_object_agg(c.key,c.value) FROM jsonb_each(to_jsonb(x)) c WHERE a.proof->'atomic' ? c.key OR c.value<>'null'::jsonb)=a.proof->'atomic')
 OR NOT EXISTS(SELECT 1 FROM public.hand_history x WHERE id=(a.proof#>>'{history,id}')::uuid AND (SELECT jsonb_object_agg(c.key,c.value) FROM jsonb_each(to_jsonb(x)) c WHERE a.proof->'history' ? c.key OR c.value<>'null'::jsonb)=a.proof->'history') THEN
 RAISE EXCEPTION 'F06_MOVEMENT_BOUNDARY_CHANGED' USING ERRCODE='55000'; END IF;
 END IF;
 SELECT COALESCE(t.addon_chips,0) INTO addon FROM public.tournaments t WHERE t.id=a.tournament_id;
 addon:=COALESCE(addon,0);
 FOR r IN SELECT value FROM jsonb_array_elements(a.proof->'roster') LOOP
 SELECT d.receipt INTO winner FROM smarter_private.f06_attempts d JOIN public.tournament_seat_move_receipts m ON m.request_id=d.request_id
 WHERE d.break_id=p_break AND d.user_id=(r#>>'{seat,user_id}')::uuid AND d.state='winner';
 IF FOUND THEN
 SELECT * INTO movement FROM public.tournament_seat_move_receipts WHERE request_id=(winner->>'request_id')::uuid;
 IF NOT FOUND OR winner-'source_occupancy_id'-'source_lifecycle'-'break_id' IS DISTINCT FROM to_jsonb(movement)
 OR (winner->>'source_table_id')::uuid IS DISTINCT FROM a.table_id OR (winner->>'source_seat_id')::uuid IS DISTINCT FROM (r#>>'{seat,id}')::uuid
 OR (winner->>'source_occupancy_id')::uuid IS DISTINCT FROM (r#>>'{seat,occupancy_id}')::uuid
 OR ((winner->>'stack')::numeric IS DISTINCT FROM (r#>>'{seat,stack}')::numeric
 AND NOT (addon>0 AND r#>'{registration,add_on}'='false'::jsonb
 AND (winner->>'stack')::numeric=(r#>>'{seat,stack}')::numeric+addon
 AND EXISTS(SELECT 1 FROM public.tournament_players p WHERE p.tournament_id=a.tournament_id AND p.user_id=(r#>>'{seat,user_id}')::uuid AND p.add_on IS TRUE)))
 OR (winner->>'break_id')::uuid IS DISTINCT FROM p_break
 OR (winner->>'source_lifecycle')::bigint IS DISTINCT FROM a.lifecycle THEN
 RAISE EXCEPTION 'F06_MOVEMENT_WINNER_CHANGED' USING ERRCODE='55000'; END IF;
 ELSE
 remaining:=remaining+1;
 SELECT jsonb_build_object('seat',to_jsonb(s),'registration',to_jsonb(p)) INTO actual
 FROM public.table_seats s JOIN public.tournament_players p ON p.tournament_id=a.tournament_id AND p.user_id=s.user_id
 WHERE s.id=(r#>>'{seat,id}')::uuid AND s.table_id=a.table_id AND s.left_at IS NULL;
 credited:=CASE WHEN addon>0 AND r#>'{registration,add_on}'='false'::jsonb AND actual#>'{registration,add_on}'='true'::jsonb
 THEN jsonb_set(jsonb_set(jsonb_set(actual,'{seat,stack}',to_jsonb((actual#>>'{seat,stack}')::numeric-addon)),
 '{registration,chips}',to_jsonb((actual#>>'{registration,chips}')::numeric-addon)),'{registration,add_on}','false'::jsonb) END;
 IF jsonb_set(actual,'{registration}',(actual->'registration')-strip) IS DISTINCT FROM jsonb_set(r,'{registration}',(r->'registration')-strip)
 AND (credited IS NULL OR jsonb_set(credited,'{registration}',(credited->'registration')-strip) IS DISTINCT FROM jsonb_set(r,'{registration}',(r->'registration')-strip)) THEN
 RAISE EXCEPTION 'F06_MOVEMENT_ROSTER_CHANGED' USING ERRCODE='55000'; END IF;
 END IF;
 END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(a.proof->'eliminated') LOOP
 SELECT jsonb_build_object('seat',to_jsonb(s),'registration',to_jsonb(p),'accepted',r->'accepted') INTO actual
 FROM public.table_seats s JOIN public.tournament_players p ON p.tournament_id=a.tournament_id AND p.user_id=s.user_id
 WHERE s.id=(r#>>'{seat,id}')::uuid AND s.table_id=a.table_id;
 IF jsonb_set(actual,'{registration}',(actual->'registration')-'{current_bounty,bounty_winnings,bounties_collected,mystery_bounty_value,position,prize,terminal_closed_at}'::text[]) IS DISTINCT FROM jsonb_set(r,'{registration}',(r->'registration')-'{current_bounty,bounty_winnings,bounties_collected,mystery_bounty_value,position,prize,terminal_closed_at}'::text[]) THEN RAISE EXCEPTION 'F06_MOVEMENT_ELIMINATION_CHANGED' USING ERRCODE='55000'; END IF;
 END LOOP;
 IF (SELECT count(*) FROM public.table_seats WHERE table_id=a.table_id AND left_at IS NULL)<>remaining
 OR (SELECT count(*) FROM public.tournament_players WHERE tournament_id=a.tournament_id AND table_id=a.table_id AND status IN ('playing','registered'))<>remaining THEN
 RAISE EXCEPTION 'F06_MOVEMENT_WHOLE_ROSTER_REQUIRED' USING ERRCODE='55000'; END IF;
END $$;


ALTER FUNCTION smarter_private.f06_assert_movement(p_break uuid) OWNER TO postgres;

--
-- TOC entry 6960 (class 1255 OID 28810967)
-- Name: f06_authority(uuid, uuid, boolean); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.f06_authority(t uuid, g uuid, take_lock boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('app.smarter_data_actor',true) IS DISTINCT FROM 'tournament-manager'
 OR NULLIF(current_setting('app.smarter_tournament_id',true),'')::uuid IS DISTINCT FROM t
 OR NULLIF(current_setting('app.smarter_tournament_lease_generation',true),'')::uuid IS DISTINCT FROM g OR t IS NULL OR g IS NULL THEN
 RAISE EXCEPTION 'F06_PROTOCOL2_REQUIRED' USING ERRCODE='42501'; END IF;
 IF take_lock THEN
 PERFORM 1 FROM public.engine_tournament_leases WHERE tournament_id=t AND protocol_version=2 AND lease_generation=g
 AND heartbeat_at>=clock_timestamp()-interval '30 seconds' FOR KEY SHARE;
 ELSE
 PERFORM 1 FROM public.engine_tournament_leases WHERE tournament_id=t AND protocol_version=2 AND lease_generation=g
 AND heartbeat_at>=clock_timestamp()-interval '30 seconds';
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'F06_LEASE_FENCED' USING ERRCODE='42501'; END IF;
END $$;


ALTER FUNCTION smarter_private.f06_authority(t uuid, g uuid, take_lock boolean) OWNER TO postgres;

--
-- TOC entry 8393 (class 1255 OID 36418346)
-- Name: f06_cancelled_preparation_writer_guard(); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.f06_cancelled_preparation_writer_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE t uuid;
BEGIN
 -- Resolve the table even before BEGIN is visible; an absent permit cannot
 -- let an already-started writer cross cancellation's exclusive lane.
 SELECT tournament_id INTO t FROM public.tables WHERE id=NEW.table_id;
 IF t IS NOT NULL THEN
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('ca:tournament-terminal-settlement:v1',0))
 OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('ca:tournament-terminal-settlement:v1:'||t::text,0)) THEN
 RAISE EXCEPTION 'F06_RETRY_CANONICAL_LANE' USING ERRCODE='55P03'; END IF;
 IF EXISTS(SELECT 1 FROM smarter_private.f06_prepared_hand_cancellations
 WHERE table_id=NEW.table_id AND hand_number=NEW.hand_number)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_no_start_continuations
 WHERE table_id=NEW.table_id AND hand_number=NEW.hand_number) THEN
 RAISE EXCEPTION 'F06_CANCELLED_PREPARATION_FENCED' USING ERRCODE='55000'; END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION smarter_private.f06_cancelled_preparation_writer_guard() OWNER TO postgres;

--
-- TOC entry 7901 (class 1255 OID 101271934)
-- Name: f06_dispose_dead_origin(uuid); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.f06_dispose_dead_origin(p_transfer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE
  xfer smarter_private.f06_manager_custody_transfers;
  e jsonb;
  b jsonb;
  pid uuid;
  tab uuid;
  hn bigint;
  custody bigint;
  rel smarter_private.f06_absent_permit_releases;
  released integer := 0;
  v_void jsonb := NULL;
BEGIN
  SELECT * INTO xfer FROM smarter_private.f06_manager_custody_transfers WHERE transfer_id = p_transfer_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'F06_DEAD_ORIGIN_TRANSFER_REQUIRED' USING ERRCODE = '22023';
  END IF;
  -- The event's own lane, taken only when it is free (never queued). It is
  -- the lane fn_f06_begin_hand shares, so no begin of any generation is in
  -- flight while absence is read below.
  PERFORM smarter_private.f06_try_lane(xfer.tournament_id);

  IF EXISTS (SELECT 1 FROM smarter_private.f06_manager_custody_admissions a
              WHERE a.transfer_id = xfer.transfer_id) THEN
    RETURN jsonb_build_object('ok', true, 'transfer_id', xfer.transfer_id,
      'tournament_id', xfer.tournament_id, 'admitted', true, 'absent_released', 0, 'void', NULL);
  END IF;
  -- Nobody but the never-admitted successor may hold the event: the origin
  -- generation is fenced, so nothing it reserved or dealt can reach a commit.
  IF EXISTS (SELECT 1 FROM public.engine_tournament_leases
              WHERE tournament_id = xfer.tournament_id
                AND lease_generation IS DISTINCT FROM xfer.successor_generation) THEN
    RAISE EXCEPTION 'F06_STRANDED_EVENT_OWNED' USING ERRCODE = '55P03';
  END IF;

  -- An original whose permit never reached the database: its begin either
  -- never ran or timed out and rolled back. Record the absence the way
  -- fn_park_stopped_time_bank_custody does, so fn_f06_begin_hand refuses that
  -- permit for ever and the successor's snapshot reads it as the original's
  -- terminal disposition.
  FOR e IN SELECT value FROM jsonb_array_elements(xfer.local_proof->'engines')
            WHERE value->'permit' IS DISTINCT FROM 'null'::jsonb LOOP
    b := e#>'{permit,binding}';
    pid := (b->>'permit_id')::uuid;
    tab := (b->>'table_id')::uuid;
    hn := (b->>'hand_number')::bigint;
    CONTINUE WHEN EXISTS (SELECT 1 FROM smarter_private.f06_hand_permits h WHERE h.permit_id = pid);
    SELECT * INTO rel FROM smarter_private.f06_absent_permit_releases r WHERE r.permit_id = pid;
    IF FOUND THEN
      IF (rel.tournament_id, rel.generation, rel.table_id, rel.hand_number)
         IS DISTINCT FROM (xfer.tournament_id, xfer.origin_generation, tab, hn) THEN
        RAISE EXCEPTION 'F06_DEAD_ORIGIN_ABSENCE_CHANGED' USING ERRCODE = '55000';
      END IF;
      CONTINUE;
    END IF;
    IF pid IS NULL OR tab IS NULL OR hn IS NULL OR hn < 1
       OR b->>'tournament_id' IS DISTINCT FROM xfer.tournament_id::text
       OR b->>'lease_generation' IS DISTINCT FROM xfer.origin_generation::text
       OR NOT EXISTS (SELECT 1 FROM public.tables tb
                       WHERE tb.id = tab AND tb.tournament_id = xfer.tournament_id) THEN
      RAISE EXCEPTION 'F06_DEAD_ORIGIN_BINDING_INVALID' USING ERRCODE = '22023';
    END IF;
    -- No start witness of this hand, or of any later hand, on the table.
    IF EXISTS (SELECT 1 FROM smarter_private.f06_hand_permits h WHERE h.table_id = tab AND h.hand_number >= hn)
       OR EXISTS (SELECT 1 FROM smarter_private.f06_hand_dispatch d WHERE d.permit_id = pid)
       OR EXISTS (SELECT 1 FROM public.hand_atomic_commits h WHERE h.table_id = tab AND h.hand_number >= hn)
       OR EXISTS (SELECT 1 FROM public.hand_history h WHERE h.table_id = tab AND h.hand_number >= hn)
       OR EXISTS (SELECT 1 FROM public.hand_state_snapshots h WHERE h.table_id = tab AND h.hand_number >= hn)
       OR EXISTS (SELECT 1 FROM public.hand_private_state h WHERE h.table_id = tab AND h.hand_number >= hn)
       OR EXISTS (SELECT 1 FROM public.table_hole_cards h WHERE h.table_id = tab AND h.hand_number >= hn) THEN
      RAISE EXCEPTION 'F06_DEAD_ORIGIN_HAND_STARTED' USING ERRCODE = '55000';
    END IF;
    SELECT COALESCE(max(h.hand_number), 0) INTO custody
      FROM public.hand_history h WHERE h.table_id = tab AND h.hand_number < hn;
    INSERT INTO smarter_private.f06_absent_permit_releases
      (permit_id, tournament_id, generation, table_id, hand_number, custody_hand_number)
    VALUES (pid, xfer.tournament_id, xfer.origin_generation, tab, hn, custody);
    released := released + 1;
  END LOOP;

  -- An original the origin reserved and dealt but never committed: the
  -- reviewed stranded void proves every chair holds its pre-deal stack and
  -- disposes the origin generation only. Not asked when nothing is reserved
  -- (an original accepted after the prepare is already terminal).
  IF EXISTS (SELECT 1 FROM smarter_private.f06_hand_permits h
              WHERE h.tournament_id = xfer.tournament_id AND h.state = 'reserved'
                AND h.permit_id::text IN (SELECT x#>>'{permit,binding,permit_id}'
                                            FROM jsonb_array_elements(xfer.local_proof->'engines') x)) THEN
    v_void := public.fn_f06_void_stranded_mixed_original(xfer.tournament_id);
  END IF;

  RETURN jsonb_build_object('ok', true, 'transfer_id', xfer.transfer_id,
    'tournament_id', xfer.tournament_id, 'admitted', false,
    'absent_released', released, 'void', v_void);
END
$$;


ALTER FUNCTION smarter_private.f06_dispose_dead_origin(p_transfer_id uuid) OWNER TO postgres;

--
-- TOC entry 5092 (class 1255 OID 87228266)
-- Name: f06_event_is_finished(uuid); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.f06_event_is_finished(p_tournament_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT COALESCE((
    SELECT upper(t.status) IN ('COMPLETED', 'CANCELLED')
       AND COALESCE(t.prize_pool_finalized, false)
       AND NOT EXISTS (SELECT 1 FROM public.tables tb
                        WHERE tb.tournament_id = t.id
                          AND lower(COALESCE(tb.status, '')) <> 'closed')
       AND NOT EXISTS (SELECT 1 FROM public.tables tb
                         JOIN public.table_seats s ON s.table_id = tb.id
                        WHERE tb.tournament_id = t.id
                          AND (s.player_id IS NOT NULL OR s.left_at IS NULL))
       AND NOT EXISTS (SELECT 1 FROM public.tournament_players tp
                        WHERE tp.tournament_id = t.id
                          AND COALESCE(tp.status, '') NOT IN ('eliminated', 'winner'))
      FROM public.tournaments t
     WHERE t.id = p_tournament_id
  ), false)
$$;


