CREATE FUNCTION smarter_private.f06_mixed_bank_proof(t uuid, engine jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $_$
