--
-- TOC entry 51305 (class 0 OID 0)
-- Dependencies: 4001
-- Name: FUNCTION f06_terminal_operation_states(); Type: COMMENT; Schema: smarter_private; Owner: postgres
--

COMMENT ON FUNCTION smarter_private.f06_terminal_operation_states() IS 'The only definition of a finished F06 table break. Identical to the set public.fn_f06_discover_breaks stops paging. A withdrawal carries an abort receipt, no manifest, no member and no attempt, so nothing is half-moved; an acknowledged operation carries a close receipt. Every other state still holds its lease.';


--
-- TOC entry 8487 (class 1255 OID 28810968)
-- Name: f06_try_lane(uuid); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.f06_try_lane(t uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF t IS NOT NULL AND (NOT pg_try_advisory_xact_lock_shared(hashtextextended('ca:tournament-terminal-settlement:v1',0))
 OR NOT pg_try_advisory_xact_lock(hashtextextended('ca:tournament-terminal-settlement:v1:'||t::text,0))) THEN
 RAISE EXCEPTION 'F06_RETRY_CANONICAL_LANE' USING ERRCODE='55P03'; END IF;
END $$;


