--
-- TOC entry 6802 (class 1255 OID 199530159)
-- Name: f06_wait_table_lane(uuid); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.f06_wait_table_lane(p_table_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '4s'
    AS $$
DECLARE t uuid;
BEGIN
  /* A TOURNAMENT TABLE'S WRITER WAITS FOR ITS SHARED LANE (2026-10-19).
     The F06 hand guards TRY G shared and T(id) shared inside the write and
     refuse on contention. A per-table writer calls this first, before any
     row or advisory lock, so it waits (at most 4 s) for an exclusive
     tournament authority instead of being refused by it; the guard's try
     then finds the locks already held by this transaction. A table without
     a tournament takes no lane, exactly as the guards. */
  IF p_table_id IS NULL THEN
    RETURN;
  END IF;
  SELECT tb.tournament_id INTO t FROM public.tables tb WHERE tb.id = p_table_id;
  IF t IS NULL THEN
    RETURN;
  END IF;
  BEGIN
    PERFORM pg_advisory_xact_lock_shared(
      hashtextextended('ca:tournament-terminal-settlement:v1', 0));
    PERFORM pg_advisory_xact_lock_shared(
      hashtextextended('ca:tournament-terminal-settlement:v1:' || t::text, 0));
  EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION 'F06_RETRY_CANONICAL_LANE' USING ERRCODE = '55P03';
  END;
END
$$;


ALTER FUNCTION smarter_private.f06_wait_table_lane(p_table_id uuid) OWNER TO postgres;

--
-- TOC entry 51310 (class 0 OID 0)
-- Dependencies: 6802
-- Name: FUNCTION f06_wait_table_lane(p_table_id uuid); Type: COMMENT; Schema: smarter_private; Owner: postgres
--

COMMENT ON FUNCTION smarter_private.f06_wait_table_lane(p_table_id uuid) IS 'Per-table writer lane: G and T(id) shared, waiting at most 4 s, taken before any other lock by insert_hole_cards, save_hand_state_snapshot, fn_ca_process_hand_post_commit_obligations and fn_project_hand_side_effects so the F06 hand guards'' try-locks find it held. Raises F06_RETRY_CANONICAL_LANE (55P03) on expiry.';


--
-- TOC entry 5666 (class 1255 OID 48881845)
-- Name: f06_zero_cards_abort_is_inert(uuid, uuid, bigint); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.f06_zero_cards_abort_is_inert(p_tournament_id uuid, p_table_id uuid, p_hand_number bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
  -- TRUE only for ONE reviewed hand - Noon tournament
  -- 5a387a75-754a-416e-8fee-b85b15fc2702, table
  -- 2c621856-e728-4e8b-bf08-4c56746a8649, hand 12942021 - whose hole cards
  -- were destroyed by public.cleanup_old_hole_cards() while its permit was
  -- still reserved, AND only while aborting it is still provably financially
  -- inert. All seven conditions must hold; any one of them failing leaves
  -- F06_RETAINED_CARDS_CHANGED standing. Never widen this, and in particular
  -- never make the identity a parameter, a table lookup or a cohort call: the
  -- same five conditions without the identity pin admit 468 hands across 322
  -- tournaments. Reads only; decides nothing else.
  SELECT
    -- 0. IDENTITY. The exact reviewed tournament, table and hand, hardcoded.
    --    This is the whole blast radius and it is visible here in full.
    p_tournament_id = '5a387a75-754a-416e-8fee-b85b15fc2702'::uuid
    AND p_table_id  = '2c621856-e728-4e8b-bf08-4c56746a8649'::uuid
    AND p_hand_number = 12942021::bigint
    -- 1. EXACTLY zero hole cards for this exact table and hand. A PARTIAL set
    --    means some rows survived and some did not, which is real drift.
    AND NOT EXISTS (SELECT 1 FROM public.table_hole_cards c
                 WHERE c.table_id = p_table_id AND c.hand_number = p_hand_number)
    -- 2. The hand never committed.
    AND NOT EXISTS (SELECT 1 FROM public.hand_atomic_commits a
                     WHERE a.table_id = p_table_id AND a.hand_number = p_hand_number)
    -- 3. No later hand committed at this table, so nothing was settled on top
    --    of the state this abort restores.
    AND NOT EXISTS (SELECT 1 FROM public.hand_atomic_commits a
                     WHERE a.table_id = p_table_id AND a.hand_number > p_hand_number)
    -- 4. The snapshot is incomplete and un-acted: preflop by column and by
    --    state_json, empty actionHistory, and a non-empty player array (an
    --    empty one would make condition 5 vacuously true).
    AND EXISTS (SELECT 1 FROM public.hand_state_snapshots s
                 WHERE s.table_id = p_table_id AND s.hand_number = p_hand_number
                   AND s.is_complete IS FALSE
                   AND s.stage = 'preflop'
                   AND s.state_json->>'stage' = 'preflop'
                   AND s.state_json->'actionHistory' = '[]'::jsonb
                   AND jsonb_typeof(s.state_json->'players') = 'array'
                   AND jsonb_array_length(s.state_json->'players') > 0)
    -- 5. FINANCIAL INERTNESS. For EVERY player in the snapshot the durable
    --    balance ALREADY equals that player's pre-hand total (stack +
    --    totalInvested), in public.tournament_players AND in the live
    --    public.table_seats row. The pot therefore exists only inside
    --    state_json and was never deducted from anything durable, so aborting
    --    the hand as unsettled restores exactly what is already durable: it
    --    awards nothing, takes nothing and decides no winner. Note that for an
    --    un-acted preflop this is close to vacuous - it is the identity pin
    --    above, not this, that bounds the scope - but it is still the thing
    --    that would go false first if chips moved underneath the pinned hand
    --    between this migration and its disposition, so it is kept.
    --    Every term is an EXISTS or a coalesced boolean, so the row test is
    --    never NULL and an unreadable player can only make this false.
    AND NOT EXISTS (
          SELECT 1
            FROM public.hand_state_snapshots s
            CROSS JOIN LATERAL jsonb_array_elements(s.state_json->'players') x
           WHERE s.table_id = p_table_id AND s.hand_number = p_hand_number
             AND NOT (
                   coalesce(pg_input_is_valid(x->>'user_id','uuid'), false)
               AND coalesce(pg_input_is_valid(x->>'stack','numeric'), false)
               AND coalesce(pg_input_is_valid(x->>'totalInvested','numeric'), false)
               AND EXISTS (SELECT 1 FROM public.tournament_players p
                            WHERE p.tournament_id = p_tournament_id
                              AND p.user_id = (x->>'user_id')::uuid
                              AND p.chips::numeric
                                  = (x->>'stack')::numeric + (x->>'totalInvested')::numeric)
               AND EXISTS (SELECT 1 FROM public.table_seats q
                            WHERE q.table_id = p_table_id
                              AND q.user_id = (x->>'user_id')::uuid
                              AND q.left_at IS NULL
                              AND q.stack::numeric
                                  = (x->>'stack')::numeric + (x->>'totalInvested')::numeric)))
    -- 6. EXACTLY ONE snapshot row for this exact (table_id, hand_number), so
    --    conditions 4 and 5 are speaking about the same row. Production has
    --    no UNIQUE (table_id, hand_number); the partial unique index
    --    idx_hand_snapshots_one_active_per_table permits a second row here as
    --    long as it is is_complete = true. This closes that.
    AND (SELECT count(*) FROM public.hand_state_snapshots s
          WHERE s.table_id = p_table_id AND s.hand_number = p_hand_number) = 1;
$$;


ALTER FUNCTION smarter_private.f06_zero_cards_abort_is_inert(p_tournament_id uuid, p_table_id uuid, p_hand_number bigint) OWNER TO postgres;

--
-- TOC entry 51312 (class 0 OID 0)
-- Dependencies: 5666
-- Name: FUNCTION f06_zero_cards_abort_is_inert(p_tournament_id uuid, p_table_id uuid, p_hand_number bigint); Type: COMMENT; Schema: smarter_private; Owner: postgres
--

COMMENT ON FUNCTION smarter_private.f06_zero_cards_abort_is_inert(p_tournament_id uuid, p_table_id uuid, p_hand_number bigint) IS 'True for EXACTLY ONE reviewed hand - tournament 5a387a75-754a-416e-8fee-b85b15fc2702, table 2c621856-e728-4e8b-bf08-4c56746a8649, hand 12942021, all three hardcoded - and only while aborting it as unsettled is provably financially inert: exactly zero surviving hole cards, no atomic commit for that hand or any later hand at that table, exactly one incomplete un-acted preflop snapshot row, and every snapshot player''s durable chips (tournament_players.chips and the live table_seats.stack) already equal stack + totalInvested. Such an abort awards nothing and takes nothing, so its destroyed hole cards cannot affect any outcome. The financial conditions WITHOUT the identity pin admit 468 hands across 322 tournaments, so the pin is what bounds this, not the conditions. A partial card set is drift and is never admitted. Read-only; never widen.';


--
-- TOC entry 7426 (class 1255 OID 78783593)
-- Name: fn_ca_club_rake_daily_apply_at_commit(); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.fn_ca_club_rake_daily_apply_at_commit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Fired at COMMIT, once per cash rake row: the rollup the statement trigger
  -- used to write in the middle of the hand, for this one row, so the club's
  -- day row is locked for the commit and not for the rest of the hand.
  DELETE FROM smarter_private.ca_club_rake_daily_at_commit
   WHERE rake_record_id = NEW.rake_record_id;
  BEGIN
    PERFORM public.fn_ca_club_rake_daily_apply(ARRAY[NEW.rake_record_id]);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'ca_club_rake_daily insert rollup failed: %', SQLERRM;
  END;
  RETURN NULL;
END;
$$;


ALTER FUNCTION smarter_private.fn_ca_club_rake_daily_apply_at_commit() OWNER TO postgres;

--
-- TOC entry 5657 (class 1255 OID 206450863)
-- Name: fn_engine_lightning_fast_fold(uuid, uuid, uuid, text, numeric, jsonb); Type: FUNCTION; Schema: smarter_private; Owner: service_role
--

CREATE FUNCTION smarter_private.fn_engine_lightning_fast_fold(p_hand_id uuid, p_player_id uuid, p_request_id uuid, p_fold_type text, p_committed numeric, p_actor_headers jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE actor text; protocol text; key_count integer;
BEGIN
  IF session_user <> 'engine_lightning_fold' OR current_user <> 'service_role' THEN
    RAISE EXCEPTION 'LIGHTNING_FOLD_SESSION_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  IF current_setting('synchronous_commit') <> 'on' THEN
    RAISE EXCEPTION 'LIGHTNING_FOLD_DURABLE_COMMIT_REQUIRED' USING ERRCODE='22023';
  END IF;
  IF p_actor_headers IS NULL OR jsonb_typeof(p_actor_headers) <> 'object' THEN
    RAISE EXCEPTION 'LIGHTNING_FOLD_ACTOR_INVALID' USING ERRCODE='22023';
  END IF;
  actor := p_actor_headers->>'x-smarter-data-actor';
  protocol := p_actor_headers->>'x-smarter-data-protocol';
  SELECT count(*) INTO key_count FROM jsonb_object_keys(p_actor_headers);
  IF EXISTS (SELECT 1 FROM jsonb_each(p_actor_headers) e
    WHERE e.key NOT IN ('x-smarter-data-actor','x-smarter-data-protocol','x-smarter-tournament-id','x-smarter-tournament-lease-generation')
       OR jsonb_typeof(e.value) <> 'string')
     OR NOT ((actor='service' AND protocol='1' AND key_count=2)
          OR (actor='tournament-manager' AND protocol='2' AND key_count=4
              AND p_actor_headers ? 'x-smarter-tournament-id'
              AND p_actor_headers ? 'x-smarter-tournament-lease-generation'))
     OR actor IS NULL OR protocol IS NULL THEN
    RAISE EXCEPTION 'LIGHTNING_FOLD_ACTOR_INVALID' USING ERRCODE='22023';
  END IF;

  -- Arbitrary custom GUCs are not authority. Only the fixed, session-bound
  -- wrapper establishes service authority; the original hook checks actor
  -- protocol and the exact live manager generation inside this transaction.
  PERFORM set_config('request.jwt.claim.role','service_role',true);
  PERFORM set_config('request.jwt.claim.sub','',true);
  PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
  PERFORM set_config('request.headers',p_actor_headers::text,true);
  PERFORM set_config('request.method','POST',true);
  PERFORM set_config('request.path','rpc/fn_lightning_fast_fold',true);
  PERFORM smarter_private.fn_smarter_data_api_pre_request();
  RETURN public.fn_lightning_fast_fold(p_hand_id,p_player_id,p_request_id,p_fold_type,p_committed);
END $$;


ALTER FUNCTION smarter_private.fn_engine_lightning_fast_fold(p_hand_id uuid, p_player_id uuid, p_request_id uuid, p_fold_type text, p_committed numeric, p_actor_headers jsonb) OWNER TO service_role;

--
-- TOC entry 5234 (class 1255 OID 58129061)
-- Name: fn_fenced_manager_stopped_custody_park(); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.fn_fenced_manager_stopped_custody_park() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_snapshot jsonb;
  v_hand jsonb;
  v_tournament uuid;
  v_generation uuid;
  v_result jsonb;
BEGIN
  /* Every other writer - the service actor, a live manager, legacy-unmarked,
     and fn_park_stopped_time_bank_custody's own insert below - passes
     untouched. */
  IF current_setting('app.smarter_data_actor', true)
       IS DISTINCT FROM 'fenced-manager-stopped-custody' THEN
    RETURN NEW;
  END IF;

  v_snapshot := NEW.time_bank_snapshot;
  v_hand := v_snapshot -> 'handNumber';
  IF right(COALESCE(NEW.engine_instance, ''), 16) IS DISTINCT FROM ':stopped_custody'
     OR jsonb_typeof(v_snapshot) IS DISTINCT FROM 'object'
     OR (v_snapshot -> 'version') IS DISTINCT FROM '1'::jsonb
     OR jsonb_typeof(v_hand) IS DISTINCT FROM 'number'
     OR (v_hand::text)::numeric < 0
     OR (v_hand::text)::numeric <> trunc((v_hand::text)::numeric)
     OR jsonb_typeof(v_snapshot -> 'players') IS DISTINCT FROM 'object'
     OR jsonb_typeof(NEW.disconnect_states) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION
      'TOURNAMENT_MANAGER_FENCED: lease generation is no longer current'
      USING ERRCODE = '42501';
  END IF;

  BEGIN
    v_tournament := NULLIF(current_setting('app.smarter_tournament_id', true), '')::uuid;
    v_generation :=
      NULLIF(current_setting('app.smarter_tournament_lease_generation', true), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    v_tournament := NULL;
  END;
  IF v_tournament IS NULL OR v_generation IS NULL THEN
    RAISE EXCEPTION
      'TOURNAMENT_MANAGER_FENCED: lease generation is no longer current'
      USING ERRCODE = '42501';
  END IF;

  /* The custody is written as the process, by the reviewed refusing write.
     Transaction-local, and restored before anything else can read it. */
  PERFORM set_config('app.smarter_data_actor', 'service', true);
  v_result := public.fn_park_stopped_time_bank_custody(
    NEW.table_id,
    v_tournament,
    v_generation,
    (v_hand::text)::bigint,
    NEW.parked_at::text,
    NEW.disconnect_states,
    v_snapshot -> 'players',
    NEW.engine_instance
  );
  PERFORM set_config('app.smarter_data_actor', 'fenced-manager-stopped-custody', true);

  IF (v_result ->> 'ok') = 'true' THEN
    -- The function wrote the row. Suppress the raw ON CONFLICT DO UPDATE.
    RETURN NULL;
  END IF;
  RAISE EXCEPTION 'STOPPED_CUSTODY_REFUSED: %', COALESCE(v_result ->> 'refused', 'unknown')
    USING ERRCODE = '42501';
END
$$;


ALTER FUNCTION smarter_private.fn_fenced_manager_stopped_custody_park() OWNER TO postgres;

--
-- TOC entry 4770 (class 1255 OID 109448454)
-- Name: fn_horse_presence_tick(); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.fn_horse_presence_tick() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    SET lock_timeout TO '2s'
    SET statement_timeout TO '20s'
    AS $$
DECLARE v_now timestamptz := now(); v_on integer := 0; v_off integer := 0;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('horse-presence-heartbeat')) THEN RETURN -1; END IF;
  WITH zones AS (SELECT name FROM pg_timezone_names),
  horses AS (
    SELECT c.profile_id AS id, coalesce(z.name, 'America/Los_Angeles') AS zone
      FROM public.content_authors c LEFT JOIN zones z ON z.name = c.timezone
     WHERE c.is_active AND c.profile_id IS NOT NULL),
  clock AS (SELECT h.id, (v_now AT TIME ZONE h.zone) AS lt FROM horses h),
  recent AS (
    SELECT author_id AS id FROM public.social_posts WHERE created_at > v_now - interval '10 minutes'
    UNION SELECT author_id FROM public.social_comments WHERE created_at > v_now - interval '10 minutes'
    UNION SELECT user_id FROM public.social_likes WHERE created_at > v_now - interval '10 minutes'),
  want AS (
    SELECT c.id,
      ( EXISTS (SELECT 1 FROM recent r WHERE r.id = c.id)
        OR EXISTS (
          SELECT 1 FROM generate_series(0, 2) AS s(i)
          CROSS JOIN LATERAL (SELECT hashtextextended(c.id::text || ':' || to_char(c.lt, 'YYYY-MM-DD') || ':' || s.i, 0) & 2147483647 AS h) x
          WHERE s.i < (hashtextextended(c.id::text || ':' || to_char(c.lt, 'YYYY-MM-DD'), 0) & 2147483647) % 3
            AND (extract(hour FROM c.lt) * 60 + extract(minute FROM c.lt))::int
                BETWEEN 480 + x.h % 900 AND 480 + x.h % 900 + 3 + (x.h / 900) % 12) ) AS online
    FROM clock c),
  to_stamp AS (
    SELECT pr.id FROM public.profiles pr JOIN want w ON w.id = pr.id
     WHERE w.online
       AND (pr.is_online IS NOT TRUE OR pr.last_seen IS NULL OR pr.last_seen < v_now - interval '45 seconds')
       FOR UPDATE OF pr SKIP LOCKED),
  stamped AS (
    UPDATE public.profiles p SET is_online = true, last_seen = v_now
      FROM to_stamp l WHERE p.id = l.id
    RETURNING p.id),
  to_sign_out AS (
    SELECT pr.id FROM public.profiles pr JOIN want w ON w.id = pr.id
     WHERE NOT w.online AND pr.is_online IS TRUE
       AND pr.last_seen > v_now - interval '2 minutes'
       AND (hashtextextended(pr.id::text || ':' || extract(epoch FROM pr.last_seen)::text, 0) & 2147483647) % 5 = 0
       FOR UPDATE OF pr SKIP LOCKED),
  signed_out AS (
    UPDATE public.profiles p SET is_online = false
      FROM to_sign_out l WHERE p.id = l.id
    RETURNING p.id)
  SELECT (SELECT count(*) FROM stamped), (SELECT count(*) FROM signed_out) INTO v_on, v_off;
  RETURN v_on;
END
$$;


ALTER FUNCTION smarter_private.fn_horse_presence_tick() OWNER TO postgres;

--
-- TOC entry 4231 (class 1255 OID 96273980)
-- Name: fn_renew_postgrest_pool(); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.fn_renew_postgrest_pool() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.ca_ddl_events
     WHERE occurred_at > clock_timestamp() - interval '8 minutes'
       AND triggers_pgrst_reload
  ) THEN
    RETURN 'skipped: a DDL reload renewed the pool within 8 minutes';
  END IF;
  PERFORM pg_notify('pgrst', 'reload schema');
  RETURN 'renewed';
END
$$;


