--
-- TOC entry 6236 (class 1255 OID 118072918)
-- Name: initialize_agent_commission_report_day(uuid, date); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.initialize_agent_commission_report_day(p_club uuid, p_day date) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE v_count bigint;v_today date:=(clock_timestamp() AT TIME ZONE 'UTC')::date;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
   RAISE EXCEPTION 'COMMISSION_REPORT_INITIALIZATION_REQUIRES_FRESH_SNAPSHOT' USING ERRCODE='25001';
 END IF;
 IF p_club IS NULL OR p_day IS NULL OR NOT isfinite(p_day)
    OR p_day>=v_today OR p_day<v_today-7 THEN
   RAISE EXCEPTION 'COMMISSION_REPORT_DAY_OUTSIDE_BOUNDED_CLOSED_WINDOW' USING ERRCODE='22023';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('agent-commission:'||p_club::text,0));
 -- VOLATILE commands obtain fresh snapshots after the existing original writer key.
 DELETE FROM smarter_private.agent_commission_report_daily WHERE club_id=p_club AND day=p_day;
 INSERT INTO smarter_private.agent_commission_report_daily(club_id,day,user_id,amount)
 SELECT p_club,p_day,a.user_id,COALESCE(SUM(a.amount),0)
   FROM public.agent_commissions a
  WHERE a.club_id=p_club AND a.user_id IS NOT NULL
    AND a.created_at>=(p_day::timestamp AT TIME ZONE 'UTC')
    AND a.created_at<((p_day+1)::timestamp AT TIME ZONE 'UTC')
  GROUP BY a.user_id;
 GET DIAGNOSTICS v_count=ROW_COUNT;
 INSERT INTO smarter_private.agent_commission_report_days(club_id,day,complete)
 VALUES(p_club,p_day,true) ON CONFLICT(club_id,day) DO UPDATE SET computed_at=clock_timestamp(),complete=true;
 RETURN v_count;
END;$$;


ALTER FUNCTION smarter_private.initialize_agent_commission_report_day(p_club uuid, p_day date) OWNER TO postgres;

--
-- TOC entry 7377 (class 1255 OID 118072916)
-- Name: initialize_agent_commission_report_frontier(uuid); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.initialize_agent_commission_report_frontier(p_club uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE v_count bigint;v_today date:=(clock_timestamp() AT TIME ZONE 'UTC')::date;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
   RAISE EXCEPTION 'COMMISSION_REPORT_INITIALIZATION_REQUIRES_FRESH_SNAPSHOT' USING ERRCODE='25001';
 END IF;
 IF p_club IS NULL THEN RAISE EXCEPTION 'COMMISSION_REPORT_CLUB_REQUIRED' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('agent-commission:'||p_club::text,0));
 IF EXISTS(SELECT 1 FROM smarter_private.agent_commission_report_frontiers WHERE club_id=p_club) THEN
   RAISE EXCEPTION 'COMMISSION_REPORT_FRONTIER_ALREADY_INITIALIZED' USING ERRCODE='55000';
 END IF;
 -- Capture every existing future-dated source too; there is no assumed empty tail.
 DELETE FROM smarter_private.agent_commission_report_daily WHERE club_id=p_club AND day>=v_today;
 INSERT INTO smarter_private.agent_commission_report_daily(club_id,day,user_id,amount)
 SELECT p_club,(a.created_at AT TIME ZONE 'UTC')::date,a.user_id,COALESCE(SUM(a.amount),0)
 FROM public.agent_commissions a WHERE a.club_id=p_club AND a.user_id IS NOT NULL
 AND a.created_at>=(v_today::timestamp AT TIME ZONE 'UTC')
 GROUP BY (a.created_at AT TIME ZONE 'UTC')::date,a.user_id;
 GET DIAGNOSTICS v_count=ROW_COUNT;
 -- These private markers have just been rebuilt from the locked fresh snapshot.
 DELETE FROM smarter_private.agent_commission_report_days WHERE club_id=p_club AND day>=v_today;
 INSERT INTO smarter_private.agent_commission_report_frontiers(club_id,first_complete_day) VALUES(p_club,v_today);
 RETURN v_count;
END;$$;


ALTER FUNCTION smarter_private.initialize_agent_commission_report_frontier(p_club uuid) OWNER TO postgres;

--
-- TOC entry 8307 (class 1255 OID 118072919)
-- Name: invalidate_agent_commission_report_days(); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.invalidate_agent_commission_report_days() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE c uuid;affected jsonb;
BEGIN
 IF TG_OP='TRUNCATE' THEN
   FOR c IN SELECT club_id FROM smarter_private.agent_commission_report_days UNION SELECT club_id FROM smarter_private.agent_commission_report_frontiers ORDER BY club_id LOOP
     PERFORM pg_advisory_xact_lock(hashtextextended('agent-commission:'||c::text,0));
   END LOOP;
   DELETE FROM smarter_private.agent_commission_report_days;
   DELETE FROM smarter_private.agent_commission_report_frontiers;
   RETURN NULL;
 ELSIF TG_OP='UPDATE' THEN
   SELECT jsonb_agg(DISTINCT jsonb_build_object('club',x.club_id,'day',(x.created_at AT TIME ZONE 'UTC')::date)) INTO affected
   FROM (
     SELECT o.club_id,o.created_at FROM old_rows o FULL JOIN new_rows n USING(id)
      WHERE o.id IS NULL OR n.id IS NULL OR o.amount IS DISTINCT FROM n.amount OR o.user_id IS DISTINCT FROM n.user_id
         OR o.club_id IS DISTINCT FROM n.club_id OR o.created_at IS DISTINCT FROM n.created_at
     UNION ALL
     SELECT n.club_id,n.created_at FROM old_rows o FULL JOIN new_rows n USING(id)
      WHERE o.id IS NULL OR n.id IS NULL OR o.amount IS DISTINCT FROM n.amount OR o.user_id IS DISTINCT FROM n.user_id
         OR o.club_id IS DISTINCT FROM n.club_id OR o.created_at IS DISTINCT FROM n.created_at
   )x WHERE x.club_id IS NOT NULL AND x.created_at IS NOT NULL;
 ELSE
   SELECT jsonb_agg(DISTINCT jsonb_build_object('club',o.club_id,'day',(o.created_at AT TIME ZONE 'UTC')::date))
    INTO affected FROM old_rows o WHERE o.club_id IS NOT NULL AND o.created_at IS NOT NULL;
 END IF;
 FOR c IN SELECT DISTINCT (x->>'club')::uuid FROM jsonb_array_elements(affected)x ORDER BY 1 LOOP
   PERFORM pg_advisory_xact_lock(hashtextextended('agent-commission:'||c::text,0));
 END LOOP;
 INSERT INTO smarter_private.agent_commission_report_days(club_id,day,complete)
 SELECT DISTINCT (x->>'club')::uuid,(x->>'day')::date,false FROM jsonb_array_elements(affected)x
 ON CONFLICT(club_id,day) DO UPDATE SET complete=false,computed_at=clock_timestamp();
 RETURN NULL;
END;$$;


ALTER FUNCTION smarter_private.invalidate_agent_commission_report_days() OWNER TO postgres;

--
-- TOC entry 9625 (class 1255 OID 155814146)
-- Name: inventory_basis_cache_read(text, boolean, text, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.inventory_basis_cache_read(p_generation text, p_problem boolean, p_kind text, p_union uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE v jsonb;
BEGIN
 IF p_generation='original-inventory-245:unqualified' THEN RETURN NULL;END IF;
 IF p_problem IS NULL OR p_kind NOT IN('pnl_boundary','pnl_flows','pnl_touched','pnl_clubs') OR p_kind IS NULL THEN RETURN NULL;END IF;
 IF p_problem THEN v:=public.fn_accounting_close_problem(p_kind,p_union,p_start,p_end);
 ELSE v:=public.fn_accounting_close_certificate(p_kind,p_union,p_start,p_end);END IF;
 IF p_generation IS NULL THEN RETURN v;END IF;
 IF v IS NULL OR v->>'_original_inventory_generation' IS DISTINCT FROM p_generation THEN RETURN NULL;END IF;
 RETURN v-'_original_inventory_generation';
END $$;


ALTER FUNCTION smarter_private.inventory_basis_cache_read(p_generation text, p_problem boolean, p_kind text, p_union uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 7948 (class 1255 OID 155814152)
-- Name: inventory_basis_cache_write(text, text, uuid, timestamp with time zone, timestamp with time zone, jsonb); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.inventory_basis_cache_write(p_generation text, p_kind text, p_union uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_value jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
BEGIN
 IF p_generation='original-inventory-245:unqualified' THEN RETURN;END IF;
 IF p_value IS NULL OR p_kind IS NULL
 OR p_kind NOT IN('pnl_boundary','pnl_flows','pnl_touched','pnl_clubs','pnl_boundary_problem','pnl_flows_problem','pnl_touched_problem','pnl_clubs_problem') THEN RETURN;END IF;
 PERFORM public.fn_accounting_close_certify(p_kind,p_union,p_start,p_end,CASE WHEN p_generation IS NULL THEN p_value ELSE p_value||jsonb_build_object('_original_inventory_generation',p_generation) END);
END $$;


ALTER FUNCTION smarter_private.inventory_basis_cache_write(p_generation text, p_kind text, p_union uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_value jsonb) OWNER TO postgres;

--
-- TOC entry 8943 (class 1255 OID 155813400)
-- Name: inventory_restoration_issue_accepted(jsonb, timestamp with time zone); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.inventory_restoration_issue_accepted(issue jsonb, p_boundary timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE event bigint; witness jsonb; proof jsonb; c record;
BEGIN
 IF jsonb_typeof(issue) IS DISTINCT FROM 'object' OR issue->>'reason' IS DISTINCT FROM 'original_inventory_chain_disagrees'
 OR issue->>'source_name' NOT IN('tournament_players','table_seats') OR issue->>'source_name' IS NULL
 OR issue->>'source_event_id' IS NULL OR issue->>'source_event_id' !~ '^[0-9]+$'
 OR p_boundary IS NULL OR NOT isfinite(p_boundary) OR p_boundary<'2026-10-12 07:00:00Z'::timestamptz THEN RETURN false;END IF;
 IF smarter_private.original_inventory_proof_sources_match() IS DISTINCT FROM true THEN RETURN false;END IF;
 event:=(issue->>'source_event_id')::bigint;
 SELECT r.*,k.source_name,k.row_id,k.family,k.witness_md5 expected_md5 INTO c
 FROM smarter_private.original_inventory_restoration_certificates r
 JOIN smarter_private.original_inventory_restoration_cases k USING(event_id)
 WHERE r.event_id=event AND r.boundary='2026-10-12 07:00:00Z'::timestamptz;
 IF NOT FOUND OR issue->>'row_id' IS DISTINCT FROM c.row_id::text
 OR issue->>'source_name' IS DISTINCT FROM c.source_name OR c.witness_md5 IS DISTINCT FROM c.expected_md5
 OR c.witness_md5 IS DISTINCT FROM md5(c.original_witness::text) OR c.proof_md5 IS DISTINCT FROM md5(c.proof::text) THEN RETURN false;END IF;
 witness:=smarter_private.original_inventory_finite_witness(event);
 IF witness IS NULL OR md5(witness::text) IS DISTINCT FROM c.expected_md5 THEN RETURN false;END IF;
 proof:=smarter_private.original_inventory_finite_family_proof(c.family,witness,'2026-10-05 07:00:00Z','2026-10-12 07:00:00Z');
 RETURN proof->>'status'='ready' AND proof->'financial_admission'='false'::jsonb
  AND proof IS NOT DISTINCT FROM c.proof AND md5(proof::text)=c.proof_md5;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $_$;


ALTER FUNCTION smarter_private.inventory_restoration_issue_accepted(issue jsonb, p_boundary timestamp with time zone) OWNER TO postgres;

