ALTER FUNCTION smarter_private.original_erased_cash_base_expected_hash(e bigint) OWNER TO postgres;

--
-- TOC entry 5659 (class 1255 OID 155813214)
-- Name: original_erased_cash_base_proof(jsonb, timestamp with time zone); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.original_erased_cash_base_proof(f jsonb, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE e jsonb;prior jsonb;s jsonb;mp jsonb;delta numeric;base numeric;fund jsonb;clubs text[];a jsonb;
BEGIN
 IF f IS NULL OR jsonb_typeof(f) IS DISTINCT FROM 'object' OR p_at IS NULL THEN RETURN jsonb_build_object('status','blocked','reason','missing_original');END IF;
 e:=f->'event';prior:=f->'prior';s:=f->'signed';mp:=f->'participant';a:=f->'atomic';
 IF e->>'source_name' IS DISTINCT FROM 'table_seats' OR e->>'operation' IS DISTINCT FROM 'DELETE'
 OR e->'after_row' IS DISTINCT FROM 'null'::jsonb OR jsonb_typeof(e->'before_row') IS DISTINCT FROM 'object'
 OR jsonb_typeof(prior->'after_row') IS DISTINCT FROM 'object'
 OR (e->'before_row')-'left_at' IS DISTINCT FROM (prior->'after_row')-'left_at'
 OR prior#>'{after_row,left_at}' IS DISTINCT FROM 'null'::jsonb
 OR e#>>'{before_row,left_at}' IS NULL
 OR (e#>>'{before_row,left_at}')::timestamptz NOT BETWEEN '2026-10-06 15:33:00Z' AND '2026-10-06 15:33:10Z'
 OR (prior->>'event_id')::bigint >= (e->>'event_id')::bigint
 OR p_at <= (e->>'observed_at')::timestamptz
 THEN RETURN jsonb_build_object('status','blocked','reason','original_transition_or_boundary_refused');END IF;
 IF s->>'seat_id' IS DISTINCT FROM e->>'row_id' OR s->>'seat_id' IS DISTINCT FROM e#>>'{before_row,id}'
 OR s->>'user_id' IS DISTINCT FROM e#>>'{before_row,user_id}'
 OR s->>'occupancy_id' IS DISTINCT FROM e#>>'{before_row,occupancy_id}'
 OR (s->>'seat_joined_at')::timestamptz IS DISTINCT FROM (e#>>'{before_row,joined_at}')::timestamptz
 OR jsonb_typeof(s->'stack_before') IS DISTINCT FROM 'number' OR jsonb_typeof(s->'stack') IS DISTINCT FROM 'number'
 OR jsonb_typeof(e#>'{before_row,stack}') IS DISTINCT FROM 'number'
 OR (s->>'stack_before')::numeric IS DISTINCT FROM (e#>>'{before_row,stack}')::numeric
 OR (s->>'stack_before')::numeric<=0 OR (s->>'stack')::numeric<0
 OR (s->>'stack_before')::numeric*100<>trunc((s->>'stack_before')::numeric*100)
 OR (s->>'stack')::numeric*100<>trunc((s->>'stack')::numeric*100)
 OR mp->>'seat_id' IS DISTINCT FROM s->>'seat_id' OR mp->>'user_id' IS DISTINCT FROM s->>'user_id'
 OR mp->>'occupancy_id' IS DISTINCT FROM s->>'occupancy_id'
 OR (mp->>'stack_before')::numeric IS DISTINCT FROM (s->>'stack_before')::numeric
 OR mp#>'{funding_lineage,issues}' IS DISTINCT FROM '[]'::jsonb
 OR jsonb_typeof(f->'funding') IS DISTINCT FROM 'array' OR jsonb_array_length(f->'funding')=0
 OR jsonb_typeof(mp->'funding_receipts') IS DISTINCT FROM 'array'
 OR jsonb_array_length(mp->'funding_receipts') IS DISTINCT FROM jsonb_array_length(f->'funding')
 OR (SELECT count(DISTINCT x#>>'{receipt,id}') FROM jsonb_array_elements(f->'funding')x) IS DISTINCT FROM jsonb_array_length(f->'funding')
 OR EXISTS(SELECT FROM jsonb_array_elements(mp->'funding_receipts') r WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(f->'funding') x WHERE x#>>'{receipt,id}'=r->>'id'))
 THEN RETURN jsonb_build_object('status','blocked','reason','original_identity_stack_or_funding_refused');END IF;
 base:=(s->>'stack_before')::numeric;delta:=(s->>'stack')::numeric-base;
 IF a->>'table_id' IS DISTINCT FROM e#>>'{before_row,table_id}'
 OR a#>>'{stack_result,success}' IS DISTINCT FROM 'true'
 OR a#>>'{stack_result,conservation_checked}' IS DISTINCT FROM 'true'
 OR a#>>'{post_commit_result,ok}' IS DISTINCT FROM 'true' OR a->>'post_commit_completed_at' IS NULL
 OR (a->>'post_commit_completed_at')::timestamptz >= p_at
 OR NOT EXISTS(SELECT FROM jsonb_array_elements(a#>'{stack_result,departed}') d
 WHERE d->>'seat_id'=s->>'seat_id' AND d->>'user_id'=s->>'user_id' AND (d->>'delta')::numeric=delta)
 OR jsonb_typeof(f->'late_ledger') IS DISTINCT FROM 'object' OR f#>>'{late_ledger,idempotency_key}' IS DISTINCT FROM f->>'late_key'
 OR (f#>>'{late_ledger,amount}')::numeric IS DISTINCT FROM abs(delta)
 OR f#>>'{late_ledger,category}' IS DISTINCT FROM 'settlement'
 OR f->>'late_key' IS DISTINCT FROM 'late_seat_settle:'||(a#>>'{stack_result,hand_id}')||':'||(s->>'user_id')
 OR (CASE WHEN delta>0 THEN f#>>'{late_ledger,from_type}' IS DISTINCT FROM 'table_stack'
 OR f#>>'{late_ledger,from_entity_id}' IS DISTINCT FROM a->>'table_id'
 OR f#>>'{late_ledger,to_type}' IS DISTINCT FROM 'player_wallet' OR f#>>'{late_ledger,to_entity_id}' IS DISTINCT FROM s->>'user_id'
 ELSE f#>>'{late_ledger,from_type}' IS DISTINCT FROM 'player_wallet' OR f#>>'{late_ledger,from_entity_id}' IS DISTINCT FROM s->>'user_id'
 OR f#>>'{late_ledger,to_type}' IS DISTINCT FROM 'table_stack' OR f#>>'{late_ledger,to_entity_id}' IS DISTINCT FROM a->>'table_id' END)
 OR f#>>'{late_idempotency,user_id}' IS DISTINCT FROM s->>'user_id'
 OR (f#>>'{late_idempotency,amount}')::numeric IS DISTINCT FROM delta
 THEN RETURN jsonb_build_object('status','blocked','reason','completed_original_delta_refused');END IF;
 FOR fund IN SELECT value FROM jsonb_array_elements(f->'funding') LOOP
  IF fund#>>'{receipt,asset}' IS DISTINCT FROM 'chips' OR fund#>>'{receipt,account_type}' IS DISTINCT FROM 'player_wallet'
  OR fund#>>'{receipt,user_id}' IS DISTINCT FROM s->>'user_id' OR fund#>>'{receipt,account_entity_id}' IS DISTINCT FROM s->>'user_id'
  OR fund#>>'{receipt,table_id}' IS DISTINCT FROM a->>'table_id' OR fund#>>'{receipt,occupancy_id}' IS DISTINCT FROM s->>'occupancy_id'
  OR fund#>>'{receipt,source_ledger_id}' IS DISTINCT FROM fund#>>'{ledger,id}'
  OR fund#>>'{receipt,wallet_transaction_id}' IS DISTINCT FROM fund#>>'{debit,id}'
  OR fund#>>'{ledger,from_type}' IS DISTINCT FROM 'player_wallet' OR fund#>>'{ledger,from_entity_id}' IS DISTINCT FROM s->>'user_id'
  OR fund#>>'{debit,type}' IS DISTINCT FROM 'debit' OR fund#>>'{debit,user_id}' IS DISTINCT FROM s->>'user_id'
  OR (fund#>>'{receipt,amount}')::numeric IS NULL OR (fund#>>'{receipt,amount}')::numeric<=0
  OR (fund#>>'{receipt,amount}')::numeric IS DISTINCT FROM (fund#>>'{ledger,amount}')::numeric
  OR (fund#>>'{receipt,amount}')::numeric IS DISTINCT FROM (fund#>>'{debit,amount}')::numeric
  OR fund#>>'{receipt,funding_club_id}' IS DISTINCT FROM fund#>>'{ledger,club_id}'
  THEN RETURN jsonb_build_object('status','blocked','reason','original_debit_refused');END IF;
 END LOOP;
 SELECT array_agg(DISTINCT x#>>'{receipt,funding_club_id}') INTO clubs FROM jsonb_array_elements(f->'funding') x;
 IF cardinality(clubs) IS DISTINCT FROM 1 OR clubs[1] IS NULL OR f#>>'{late_ledger,club_id}' IS DISTINCT FROM clubs[1]
 THEN RETURN jsonb_build_object('status','blocked','reason','original_owner_refused');END IF;
 RETURN jsonb_build_object('status','ready','financial_admission',false,'boundary',p_at,'original_base',base,'preserved_played_delta',delta,
 'holding',jsonb_build_object('kind','original_erased_cash_receivable','source_id',s->>'occupancy_id','user_id',s->>'user_id','club_id',clubs[1],'amount',base),
 'raw_issue_event_id',e->'event_id','missing_force_event_invented',false,'current_membership_used',false);
EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR invalid_datetime_format OR numeric_value_out_of_range THEN
 RETURN jsonb_build_object('status','blocked','reason','malformed_original');
END $$;


ALTER FUNCTION smarter_private.original_erased_cash_base_proof(f jsonb, p_at timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 8840 (class 1255 OID 155813493)
-- Name: original_erased_cash_base_request(bigint, text); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.original_erased_cash_base_request(p_event_id bigint, p_expected_hash text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE f jsonb;p jsonb;c record;
BEGIN
 SELECT * INTO c FROM smarter_private.original_inventory_restoration_cases WHERE event_id=p_event_id;
 IF NOT FOUND OR c.family IS DISTINCT FROM 'erased_cash_receivable'
 OR p_expected_hash IS NULL THEN
 RETURN jsonb_build_object('status','blocked','reason','unknown_or_changed_original_cash_request');END IF;
 f:=smarter_private.original_inventory_finite_witness(p_event_id);
 IF f IS NULL THEN
 RETURN jsonb_build_object('status','blocked','reason','original_cash_source_refused');END IF;
 f:=f-'original_table_scope'-'original_manifest_scope';
 IF md5(f::text) IS DISTINCT FROM p_expected_hash THEN
 RETURN jsonb_build_object('status','blocked','reason','original_cash_source_refused');END IF;
 p:=smarter_private.original_erased_cash_base_proof(f,'2026-10-12 07:00:00Z');
 IF p->>'status' IS DISTINCT FROM 'ready' OR p->'financial_admission' IS DISTINCT FROM 'false'::jsonb THEN RETURN p;END IF;
 RETURN jsonb_build_object('status','ready','financial_admission',false,'event_id',p_event_id,
 'case_witness_md5',c.witness_md5,'witness_md5',p_expected_hash,'witness',f,'proof',p,'proof_md5',md5(p::text));
END $$;


ALTER FUNCTION smarter_private.original_erased_cash_base_request(p_event_id bigint, p_expected_hash text) OWNER TO postgres;

--
-- TOC entry 5968 (class 1255 OID 155814139)
-- Name: original_erased_cash_discharge_returns(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.original_erased_cash_discharge_returns(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(ledger_id uuid, club_id uuid, user_id uuid, buyins numeric, cashouts numeric, kind text, valid boolean)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE c record;f jsonb;receipt jsonb;h text;
BEGIN
 IF p_union_id IS DISTINCT FROM 'fade0000-0000-0000-0000-000000000001'::uuid
 OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end) OR p_end<=p_start THEN RETURN;END IF;
 FOR c IN SELECT * FROM smarter_private.original_inventory_restoration_cases WHERE family='erased_cash_receivable' LOOP
 f:=smarter_private.original_inventory_finite_witness(c.event_id);
 IF f IS NULL THEN RAISE EXCEPTION 'original_discharge_flow_source_refused' USING ERRCODE='55000';END IF;
 h:=md5((f-'original_table_scope'-'original_manifest_scope')::text);
 receipt:=smarter_private.original_erased_cash_base_discharge_receipt(c.event_id,h);
 IF receipt->>'status'='pending' THEN CONTINUE;END IF;
 IF receipt->>'status' IS DISTINCT FROM 'discharged'
 OR receipt->>'discharged_at' IS NULL OR NOT isfinite((receipt->>'discharged_at')::timestamptz)
 OR receipt->>'custody' IS DISTINCT FROM 'canonical_deleted_account_bank'
 OR receipt->'final_player_wallet' IS DISTINCT FROM '0'::jsonb
 OR receipt->>'occupancy_id' IS DISTINCT FROM f#>>'{event,before_row,occupancy_id}'
 OR receipt->>'restoration_key' IS DISTINCT FROM ('retired_completed_cash_base:'||(f#>>'{event,before_row,occupancy_id}'))
 OR (receipt->>'discharged_at')::timestamptz<='2026-10-12 07:00:00Z'::timestamptz
 OR EXISTS(SELECT 1 FROM public.union_pnl_original_flows old WHERE old.ledger_id=(receipt->>'issuance_leg_id')::uuid)
 THEN RAISE EXCEPTION 'original_discharge_flow_proof_refused' USING ERRCODE='55000';END IF;
 IF (receipt->>'discharged_at')::timestamptz<p_start OR (receipt->>'discharged_at')::timestamptz>=p_end THEN CONTINUE;END IF;
 ledger_id:=(receipt->>'issuance_leg_id')::uuid;club_id:=(receipt->>'funding_club_id')::uuid;user_id:=(receipt->>'user_id')::uuid;
 buyins:=0;cashouts:=(receipt->>'amount')::numeric;kind:='cash_return';valid:=true;RETURN NEXT;
 END LOOP;
END $$;


ALTER FUNCTION smarter_private.original_erased_cash_discharge_returns(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 6322 (class 1255 OID 155814137)
-- Name: original_erased_cash_receivables(uuid, timestamp with time zone); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.original_erased_cash_receivables(p_union_id uuid, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE c record;f jsonb;p jsonb;held jsonb:='[]';n integer:=0;total numeric:=0;receipt jsonb;h text;owed numeric;
BEGIN
 IF p_union_id IS DISTINCT FROM 'fade0000-0000-0000-0000-000000000001'::uuid
 OR p_at IS NULL OR NOT isfinite(p_at) OR p_at<'2026-10-12 07:00:00Z'::timestamptz THEN
 RETURN jsonb_build_object('status','blocked','reason','finite_receivable_boundary_refused');END IF;
 FOR c IN SELECT k.* FROM smarter_private.original_inventory_restoration_cases k
 JOIN smarter_private.original_inventory_restoration_certificates z USING(event_id)
 WHERE k.family='erased_cash_receivable' AND z.boundary='2026-10-12 07:00:00Z'::timestamptz
 AND z.witness_md5=k.witness_md5 AND z.original_witness=k.original_witness AND z.proof_md5=md5(z.proof::text) LOOP
 f:=smarter_private.original_inventory_finite_witness(c.event_id);
 IF f IS NULL THEN RETURN jsonb_build_object('status','blocked','reason','original_receivable_source_refused');END IF;
 p:=smarter_private.original_erased_cash_base_proof(f,'2026-10-12 07:00:00Z');
 IF p->>'status' IS DISTINCT FROM 'ready' OR p->'financial_admission' IS DISTINCT FROM 'false'::jsonb
 OR f#>>'{original_table_scope,union_id}' IS DISTINCT FROM p_union_id::text
 OR f#>>'{original_manifest_scope,game_union_id}' IS DISTINCT FROM p_union_id::text
 OR f#>>'{original_manifest_scope,asset}' IS DISTINCT FROM 'chips'
 OR f#>'{original_manifest_scope,unit_scale}' IS DISTINCT FROM '2'::jsonb THEN
 RETURN jsonb_build_object('status','blocked','reason','original_receivable_proof_refused');END IF;
 n:=n+1;total:=total+(p->>'original_base')::numeric;
 owed:=(p->>'original_base')::numeric;
 IF p_at>'2026-10-12 07:00:00Z'::timestamptz THEN
  h:=md5((f-'original_table_scope'-'original_manifest_scope')::text);
  receipt:=smarter_private.original_erased_cash_base_discharge_receipt(c.event_id,h);
  IF receipt->>'status'='discharged' THEN
   IF receipt->>'discharged_at' IS NULL OR NOT isfinite((receipt->>'discharged_at')::timestamptz)
   OR receipt->>'custody' IS DISTINCT FROM 'canonical_deleted_account_bank'
   OR (receipt->>'amount')::numeric IS DISTINCT FROM owed
   OR receipt->>'occupancy_id' IS DISTINCT FROM f#>>'{event,before_row,occupancy_id}'
   OR (receipt->>'discharged_at')::timestamptz<='2026-10-12 07:00:00Z'::timestamptz THEN
    RETURN jsonb_build_object('status','blocked','reason','original_receivable_discharge_refused');END IF;
   IF (receipt->>'discharged_at')::timestamptz<p_at THEN owed:=0;END IF;
  ELSIF receipt->>'status' IS DISTINCT FROM 'pending' THEN
   RETURN jsonb_build_object('status','blocked','reason','original_receivable_discharge_unproven');
  END IF;
 END IF;
 IF owed>0 THEN held:=held||jsonb_build_array(jsonb_build_object('club_id',p#>'{holding,club_id}','user_id',p#>'{holding,user_id}',
 'amount',owed,'kind','original_erased_cash_receivable','source_id',f#>'{event,before_row,occupancy_id}',
 'original_event_id',c.event_id,'preserved_played_delta',p->'preserved_played_delta'));END IF;
 END LOOP;
 IF n IS DISTINCT FROM 7 OR total IS DISTINCT FROM 1845.87::numeric THEN
 RETURN jsonb_build_object('status','blocked','reason','finite_receivable_coverage_refused');END IF;
 RETURN jsonb_build_object('status','ready','holdings',held,'original_total',total,'held_total',(SELECT COALESCE(sum((x->>'amount')::numeric),0) FROM jsonb_array_elements(held)x),'financial_payment',false);
END $$;


