-- TOC entry 5776 (class 1255 OID 217129361)
-- Name: preserve_historical_rakeback_wallet(uuid, bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.preserve_historical_rakeback_wallet(p_period uuid, p_certificate bigint, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE admission jsonb; cid uuid; uid uuid; saved text; saved_period text; saved_cert text; saved_start text; saved_end text;
BEGIN
 admission:=smarter_private.historical_rakeback_wallet_admission(p_period,p_certificate,p_start,p_end);
 cid:=(admission->>'club_id')::uuid;uid:=(admission->>'user_id')::uuid;
 IF to_regclass('pg_temp._routed_player_todo') IS NULL OR to_regclass('pg_temp._routed_player_funding') IS NULL THEN RAISE EXCEPTION 'historical_wallet_native_stage_required'; END IF;
 IF NOT EXISTS(SELECT FROM pg_temp._routed_player_todo WHERE period_id=p_period AND certificate_id=p_certificate AND club_id=cid AND user_id=uid AND owed>0)
 OR EXISTS(SELECT FROM pg_temp._routed_player_funding WHERE club_id=cid AND payer_kind='agent' AND payer_user=uid) THEN RAISE EXCEPTION 'historical_wallet_payer_restoration_refused'; END IF;
 PERFORM public.fn_club_membership_lock(uid);
 IF EXISTS(SELECT FROM public.club_members WHERE club_id=cid AND user_id=uid) THEN RETURN; END IF;
 saved:=current_setting('app.club_membership_source',true);saved_period:=current_setting('app.historical_rakeback_period',true);
 saved_cert:=current_setting('app.historical_rakeback_certificate',true);saved_start:=current_setting('app.historical_rakeback_start',true);saved_end:=current_setting('app.historical_rakeback_end',true);
 PERFORM set_config('app.club_membership_source','historical_rakeback_wallet',true);
 PERFORM set_config('app.historical_rakeback_period',p_period::text,true);PERFORM set_config('app.historical_rakeback_certificate',p_certificate::text,true);
 PERFORM set_config('app.historical_rakeback_start',p_start::text,true);PERFORM set_config('app.historical_rakeback_end',p_end::text,true);
 INSERT INTO public.club_members(club_id,user_id,role,status,is_active,membership_lifecycle_status,departed_at,departure_reason,chip_balance,promo_balance,held_chips,locked_chips,credit_limit,credit_used,commission_rate,rakeback_rate,player_rakeback_pct,agent_id,parent_agent_id)
 VALUES(cid,uid,'player','suspended',false,'departed',clock_timestamp(),'historical_rakeback:'||p_period::text||':'||p_certificate::text,0,0,0,0,0,0,0,0,0,NULL,NULL);
 PERFORM set_config('app.club_membership_source',coalesce(saved,''),true);PERFORM set_config('app.historical_rakeback_period',coalesce(saved_period,''),true);
 PERFORM set_config('app.historical_rakeback_certificate',coalesce(saved_cert,''),true);PERFORM set_config('app.historical_rakeback_start',coalesce(saved_start,''),true);PERFORM set_config('app.historical_rakeback_end',coalesce(saved_end,''),true);
 IF NOT EXISTS(SELECT FROM public.club_members WHERE club_id=cid AND user_id=uid AND role='player' AND status='suspended' AND is_active=false AND membership_lifecycle_status='departed'
 AND chip_balance=0 AND promo_balance=0 AND held_chips=0 AND locked_chips=0 AND credit_limit=0 AND credit_used=0 AND agent_id IS NULL AND parent_agent_id IS NULL) THEN RAISE EXCEPTION 'historical_wallet_insert_shape_changed'; END IF;
END $$;


ALTER FUNCTION smarter_private.preserve_historical_rakeback_wallet(p_period uuid, p_certificate bigint, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- TOC entry 9268 (class 1255 OID 170451138)
-- Name: purge_legacy_horse_learning(uuid[]); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.purge_legacy_horse_learning(p_hand_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    SET lock_timeout TO '2s'
    AS $_$
DECLARE v_hand uuid; digest text; s smarter_private.hand_submissions; d smarter_private.hand_submission_disposals;
 b record; v jsonb; raw_count integer; raw_total integer:=0; purged uuid[]:='{}'; protected uuid[]:='{}'; already_purged uuid[]:='{}';
 keys text[]:='{}'; candidate_keys text[]; all_keys text[]; kept jsonb; batches integer:=0;
 deadline timestamptz:=clock_timestamp()+interval '2 seconds'; budget boolean:=false;
 exists_raw boolean; bad boolean; touched integer;
 batch_cache jsonb:='{}'; cache_flags jsonb; cache_tuple jsonb; cache_key text; cache_hand text; cache_bad boolean; requested_hands jsonb; purged_hand_set jsonb;
BEGIN
 IF p_hand_ids IS NULL OR cardinality(p_hand_ids)>250 OR array_position(p_hand_ids,NULL) IS NOT NULL
 THEN RAISE EXCEPTION 'LEGACY_LEARNING_INVALID_IDS'; END IF;
 SELECT COALESCE(jsonb_object_agg(h::text,true),'{}'::jsonb) INTO requested_hands FROM unnest(p_hand_ids) h;
 IF public.fn_platform_frozen() IS DISTINCT FROM false THEN
  RETURN jsonb_build_object('status','unavailable','reason','maintenance_frozen'); END IF;
 IF NOT pg_try_advisory_xact_lock_shared(530090,1) THEN
  RETURN jsonb_build_object('status','unavailable','reason','maintenance_busy'); END IF;
 IF public.fn_platform_frozen() IS DISTINCT FROM false THEN
  RETURN jsonb_build_object('status','unavailable','reason','maintenance_frozen'); END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('horse-adaptive-work-capacity-v1',0)) THEN
  RETURN jsonb_build_object('status','unavailable','reason','capacity_busy'); END IF;
 IF (SELECT horse_retention_days FROM public.hand_history_retention_policy LIMIT 1) IS DISTINCT FROM 8
 OR EXISTS(SELECT 1 FROM public.horse_adaptive_observation_batches WHERE NOT retention_membership_ready LIMIT 1)
 THEN RETURN jsonb_build_object('status','unavailable','reason','retention_not_ready'); END IF;
 FOR v_hand IN SELECT DISTINCT unnest(p_hand_ids) ORDER BY 1 LOOP
  IF clock_timestamp()>=deadline THEN budget:=true; EXIT; END IF;
  IF EXISTS(SELECT 1 FROM smarter_private.horse_adaptive_legacy_learning_purges WHERE hand_id=v_hand) THEN already_purged:=already_purged||v_hand; CONTINUE; END IF;
  digest:=encode(sha256(convert_to(v_hand::text,'UTF8')),'hex');
  SELECT * INTO s FROM smarter_private.hand_submissions WHERE submission_id=v_hand;
  SELECT * INTO d FROM smarter_private.hand_submission_disposals WHERE submission_id=v_hand;
  IF EXISTS(SELECT 1 FROM smarter_private.horse_adaptive_disposal_certificates WHERE hand_id=v_hand)
  OR EXISTS(SELECT 1 FROM public.hand_history WHERE hand_history.id=v_hand)
  OR EXISTS(SELECT 1 FROM public.hand_atomic_commits WHERE hand_id=v_hand)
  OR s.request#>>'{p_hand_row,has_human}'='true'
  OR s.request#>>'{p_hand_row,reported}'='true'
  OR d.expected->>'original_has_human'='true'
  OR EXISTS(SELECT 1 FROM public.cash_hand_provenance_receipts p WHERE p.hand_id=v_hand
   AND (p.accepted_request#>>'{hand_row,has_human}'='true'
    OR p.accepted_request#>>'{hand_row,reported}'='true'))
  OR EXISTS(SELECT 1 FROM public.hand_projection_outbox WHERE hand_id=v_hand)
  OR EXISTS(SELECT 1 FROM public.tournament_knockout_candidates WHERE hand_id=v_hand AND state='pending')
  THEN protected:=protected||v_hand; CONTINUE; END IF;
  IF s.table_id IS NOT NULL AND (
    EXISTS(SELECT 1 FROM public.hand_atomic_commits WHERE table_id=s.table_id AND hand_number=s.hand_number)
    OR smarter_private.f06_hand_cards_unresolved(s.table_id,s.hand_number)
    OR smarter_private.f06_movement_boundary_retained(s.table_id,s.hand_number)
    OR EXISTS(SELECT 1 FROM public.bbj_payouts WHERE table_id=s.table_id AND hand_number=s.hand_number))
  THEN protected:=protected||v_hand; CONTINUE; END IF;
  IF d.table_id IS NOT NULL AND (
    EXISTS(SELECT 1 FROM public.hand_atomic_commits WHERE table_id=d.table_id AND hand_number=d.hand_number)
    OR smarter_private.f06_hand_cards_unresolved(d.table_id,d.hand_number)
    OR smarter_private.f06_movement_boundary_retained(d.table_id,d.hand_number)
    OR EXISTS(SELECT 1 FROM public.bbj_payouts WHERE table_id=d.table_id AND hand_number=d.hand_number))
  THEN protected:=protected||v_hand; CONTINUE; END IF;
  -- The unfinished queue is capped by its original admission at 256 items.
  IF EXISTS(SELECT 1 FROM public.horse_adaptive_journal_work w WHERE w.state<>'completed'
    AND EXISTS(SELECT 1 FROM jsonb_array_elements(w.payload::jsonb->7) v WHERE (v.value#>>'{}')::jsonb->>2=v_hand::text))
  THEN protected:=protected||v_hand; CONTINUE; END IF;
  candidate_keys:=ARRAY(SELECT batch_key FROM smarter_private.horse_adaptive_batch_hand_membership WHERE hand_digest=digest ORDER BY batch_key);
  all_keys:=ARRAY(SELECT DISTINCT unnest(keys||candidate_keys) ORDER BY 1);
  IF (SELECT COALESCE(sum(octet_length(canonical_payload)),0) FROM public.horse_adaptive_observation_batches WHERE batch_key=ANY(all_keys))>16777216
  THEN budget:=true; EXIT; END IF;
  PERFORM 1 FROM public.horse_adaptive_observation_journal j
   WHERE j.observation_id>=v_hand::text||':0' AND j.observation_id<=v_hand::text||':9999' AND j.hand_id=v_hand FOR UPDATE;
  SELECT EXISTS(SELECT 1 FROM public.horse_adaptive_observation_journal j
   WHERE j.observation_id>=v_hand::text||':0' AND j.observation_id<=v_hand::text||':9999' AND j.hand_id=v_hand),
   EXISTS(SELECT 1 FROM public.horse_adaptive_observation_journal j
   WHERE j.observation_id>=v_hand::text||':0' AND j.observation_id<=v_hand::text||':9999' AND j.hand_id=v_hand
   AND (j.observed_at_ms>1791158399999 OR j.payload::jsonb->>2 IS DISTINCT FROM v_hand::text
    OR j.payload::jsonb->>5 IS DISTINCT FROM j.observed_at_ms::text)) INTO exists_raw,bad;
  IF bad THEN protected:=protected||v_hand; CONTINUE; END IF;
  touched:=0;
  -- Each entry is derived only after taking the original batch row lock.
  -- Keep only requested hands' presence/age flags, not raw payload copies.
  FOREACH cache_key IN ARRAY candidate_keys LOOP
   IF EXISTS(SELECT 1 FROM public.horse_adaptive_journal_work WHERE batch_key=cache_key AND state<>'completed') THEN bad:=true; EXIT; END IF;
   IF NOT batch_cache ? cache_key THEN
    SELECT batch_key,canonical_payload INTO b FROM public.horse_adaptive_observation_batches
     WHERE batch_key=cache_key FOR UPDATE;
    cache_flags:='{}'::jsonb;
    IF FOUND AND b.canonical_payload IS NOT NULL THEN
     FOR v IN SELECT value FROM jsonb_array_elements(b.canonical_payload::jsonb->7) LOOP
      cache_tuple:=(v#>>'{}')::jsonb;
      cache_hand:=cache_tuple->>2;
      IF requested_hands ? cache_hand THEN
       cache_bad:=jsonb_typeof(cache_tuple->5) IS DISTINCT FROM 'number'
        OR (cache_tuple->>5)!~'^[0-9]{1,16}$';
       IF NOT cache_bad THEN cache_bad:=(cache_tuple->>5)::bigint>1791158399999; END IF;
       cache_flags:=jsonb_set(cache_flags,ARRAY[cache_hand],to_jsonb(
        COALESCE((cache_flags->>cache_hand)::boolean,false) OR cache_bad));
      END IF;
     END LOOP;
    END IF;
    batch_cache:=jsonb_set(batch_cache,ARRAY[cache_key],cache_flags);
   END IF;
   IF batch_cache->cache_key ? v_hand::text THEN
    exists_raw:=true;
    IF (batch_cache->cache_key->>v_hand::text)::boolean THEN bad:=true; EXIT; END IF;
   END IF;
  END LOOP;
  IF bad OR NOT exists_raw THEN
   -- A refused candidate must not accumulate arbitrarily many disjoint raw
   -- byte windows in the cache. Retain only already-admitted keys, whose union
   -- is bounded by the unchanged original 16 MiB admission check above.
   SELECT COALESCE(jsonb_object_agg(key,value),'{}'::jsonb) INTO batch_cache
    FROM jsonb_each(batch_cache) WHERE key=ANY(keys);
   protected:=protected||v_hand; CONTINUE;
  END IF;
  DELETE FROM public.horse_adaptive_observation_journal j
   WHERE j.observation_id>=v_hand::text||':0' AND j.observation_id<=v_hand::text||':9999' AND j.hand_id=v_hand;
  GET DIAGNOSTICS raw_count=ROW_COUNT;
  INSERT INTO smarter_private.horse_adaptive_legacy_learning_purges VALUES
   (v_hand,digest,1791158399999,'owner-one-time-legacy-test-learning-20261015',clock_timestamp(),raw_count,(SELECT count(*)::integer FROM public.horse_adaptive_observation_batches WHERE batch_key=ANY(candidate_keys) AND canonical_payload IS NOT NULL));
  raw_total:=raw_total+raw_count; purged:=purged||v_hand; keys:=all_keys;
 END LOOP;
 SELECT COALESCE(jsonb_object_agg(h::text,true),'{}'::jsonb) INTO purged_hand_set FROM unnest(purged) h;
 -- Exactly one rewrite of each touched batch in this transaction. Original
 -- receipt, count and digest remain unchanged; only retained raw tuple strings
 -- are removed. Exact original payload recovery already refuses compacted data.
 FOR b IN SELECT batch_key,canonical_payload FROM public.horse_adaptive_observation_batches
  WHERE batch_key=ANY(keys) ORDER BY batch_key FOR UPDATE LOOP
  IF b.canonical_payload IS NOT NULL THEN
   kept:=jsonb_set(b.canonical_payload::jsonb,'{7}',COALESCE((SELECT jsonb_agg(value ORDER BY ordinality)
    FROM jsonb_array_elements(b.canonical_payload::jsonb->7) WITH ORDINALITY
    WHERE NOT COALESCE(purged_hand_set ? ((value#>>'{}')::jsonb->>2),false)),'[]'::jsonb));
   UPDATE public.horse_adaptive_observation_batches SET canonical_payload=kept::text,retention_compacted=true WHERE batch_key=b.batch_key;
   batches:=batches+1;
  END IF;
 END LOOP;
 RETURN jsonb_build_object('status','purged','handsPurged',cardinality(purged),'observationsDeleted',raw_total,
  'batchesCompacted',batches,'purgedHands',purged,'protectedHands',protected,'alreadyPurgedHands',already_purged,'budgetReached',budget);
END $_$;


ALTER FUNCTION smarter_private.purge_legacy_horse_learning(p_hand_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 8125 (class 1255 OID 159650307)
-- Name: qualify_rake_agent_report_day(uuid, date); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.qualify_rake_agent_report_day(p_club uuid, p_day date) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE v_count bigint;v_today date:=(clock_timestamp() AT TIME ZONE 'UTC')::date;
BEGIN
 IF session_user NOT IN ('postgres','supabase_admin') THEN
   RAISE EXCEPTION 'RAKE_REPORT_BASELINE_OPERATOR_ONLY' USING ERRCODE='42501';
 END IF;
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
   RAISE EXCEPTION 'RAKE_REPORT_BASELINE_REQUIRES_FRESH_SNAPSHOT' USING ERRCODE='25001';
 END IF;
 IF p_club IS NULL OR p_day IS NULL OR NOT isfinite(p_day)
    OR p_day>=v_today OR p_day<v_today-731 THEN
   RAISE EXCEPTION 'RAKE_REPORT_BASELINE_OUTSIDE_CLOSED_REPORT_WINDOW' USING ERRCODE='22023';
 END IF;
 -- A single closed day, never a whole reporting period in one writer lock.
 -- This is the exact key taken by original commission INSERT/UPDATE/DELETE.
 PERFORM pg_advisory_xact_lock(hashtextextended('agent-commission:'||p_club::text,0));
 IF EXISTS(SELECT 1 FROM smarter_private.agent_commission_report_days m
            WHERE m.club_id=p_club AND m.day=p_day AND m.complete)
    OR (NOT EXISTS(SELECT 1 FROM smarter_private.agent_commission_report_days m
                     WHERE m.club_id=p_club AND m.day=p_day)
        AND EXISTS(SELECT 1 FROM smarter_private.agent_commission_report_frontiers f
                    WHERE f.club_id=p_club AND p_day>=f.first_complete_day)) THEN
   RAISE EXCEPTION 'RAKE_REPORT_BASELINE_ALREADY_QUALIFIED' USING ERRCODE='55000';
 END IF;
 -- Each VOLATILE statement obtains its snapshot after the original writer key.
 -- Raw journals and balances are never changed; only private reporting metadata.
 DELETE FROM smarter_private.agent_commission_report_daily WHERE club_id=p_club AND day=p_day;
 INSERT INTO smarter_private.agent_commission_report_daily(club_id,day,user_id,amount)
 SELECT p_club,p_day,a.user_id,COALESCE(SUM(a.amount),0)
   FROM public.agent_commissions a
  WHERE a.club_id=p_club AND a.user_id IS NOT NULL
    AND a.created_at>=(p_day::timestamp AT TIME ZONE 'UTC')
    AND a.created_at<((p_day+1)::timestamp AT TIME ZONE 'UTC')
  GROUP BY a.user_id;
 GET DIAGNOSTICS v_count=ROW_COUNT;
 INSERT INTO smarter_private.agent_commission_report_days(club_id,day,complete)
 VALUES(p_club,p_day,true) ON CONFLICT(club_id,day) DO UPDATE SET computed_at=clock_timestamp(),complete=true;
 RETURN v_count;
END;
$$;


ALTER FUNCTION smarter_private.qualify_rake_agent_report_day(p_club uuid, p_day date) OWNER TO postgres;

--
-- TOC entry 8700 (class 1255 OID 206071054)
-- Name: rakeback_certificate_payers(bigint); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.rakeback_certificate_payers(p_calculation bigint) RETURNS TABLE(payer_kind text, payer_user uuid, payer_entity uuid, owed numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE c public.accounting_rakeback_period_calculations%ROWTYPE;plan jsonb;
BEGIN
 SELECT * INTO STRICT c FROM public.accounting_rakeback_period_calculations WHERE id=p_calculation;
 IF c.payer_kind<>'split' THEN
  IF c.payer_kind NOT IN('agent','club') OR(c.payer_kind='agent')IS DISTINCT FROM(c.payer_user_id IS NOT NULL)
  THEN RAISE EXCEPTION 'rakeback_certificate_payer_invalid' USING ERRCODE='23514'; END IF;
  RETURN QUERY SELECT c.payer_kind,c.payer_user_id,COALESCE(c.payer_user_id,c.club_id),c.rakeback_amount;RETURN;
 END IF;
 plan:=smarter_private.rakeback_payer_plan(c.source_allocations,c.rakeback_amount);
 IF jsonb_array_length(plan)<2 OR c.payer_user_id IS NOT NULL
  OR(SELECT count(*)FROM public.accounting_rakeback_payer_contracts g WHERE g.calculation_id=c.id)<>jsonb_array_length(plan)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(plan)p LEFT JOIN public.accounting_rakeback_payer_contracts g
   ON g.calculation_id=c.id AND g.payer_kind=p->>'payer_kind' AND g.payer_entity_id=COALESCE(NULLIF(p->>'payer_user_id','')::uuid,c.club_id)
   WHERE g.calculation_id IS NULL OR g.payer_user_id IS DISTINCT FROM NULLIF(p->>'payer_user_id','')::uuid
    OR g.amount IS DISTINCT FROM(p->>'amount')::numeric OR g.unrounded IS DISTINCT FROM(p->>'unrounded')::numeric
    OR g.rake IS DISTINCT FROM(p->>'rake')::numeric OR g.source_count IS DISTINCT FROM(p->>'source_count')::bigint
    OR g.source_fingerprint IS DISTINCT FROM c.source_fingerprint OR g.payer_user_id=c.player_id)
 THEN RAISE EXCEPTION 'split_rakeback_payer_contracts_disagree' USING ERRCODE='23514'; END IF;
 RETURN QUERY SELECT g.payer_kind,g.payer_user_id,g.payer_entity_id,g.amount FROM public.accounting_rakeback_payer_contracts g
  WHERE g.calculation_id=c.id ORDER BY g.payer_kind,g.payer_entity_id;
END $$;


ALTER FUNCTION smarter_private.rakeback_certificate_payers(p_calculation bigint) OWNER TO postgres;

--
-- TOC entry 7549 (class 1255 OID 206071010)
-- Name: rakeback_payer_plan(jsonb, numeric); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.rakeback_payer_plan(p_allocations jsonb, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE result jsonb;expected numeric;
BEGIN
 IF jsonb_typeof(p_allocations) IS DISTINCT FROM 'array' OR jsonb_array_length(p_allocations)=0
 OR p_amount IS NULL OR p_amount<0 OR p_amount<>round(p_amount,2) OR p_amount::text IN('NaN','Infinity','-Infinity')
 THEN RAISE EXCEPTION 'rakeback_payer_plan_invalid' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_allocations)a
  WHERE a->>'payer_kind' IS NULL OR a->>'payer_kind' NOT IN('club','agent')
   OR (a->>'payer_kind'='agent') IS DISTINCT FROM(NULLIF(a->>'payer_user_id','') IS NOT NULL)
   OR (a->>'rake_credit')::numeric IS NULL OR (a->>'rake_credit')::numeric<0
   OR (a->>'rake_credit')::numeric<>round((a->>'rake_credit')::numeric,2)
   OR (a->>'rate')::numeric IS NULL OR (a->>'rate')::numeric<0 OR (a->>'rate')::numeric>1
   OR (a->>'rake_credit')::numeric::text IN('NaN','Infinity','-Infinity')
   OR (a->>'rate')::numeric::text IN('NaN','Infinity','-Infinity'))
 THEN RAISE EXCEPTION 'rakeback_payer_allocation_invalid' USING ERRCODE='23514'; END IF;
 SELECT round(sum((a->>'rake_credit')::numeric*(a->>'rate')::numeric),2) INTO expected
 FROM jsonb_array_elements(p_allocations)a;
 IF expected IS DISTINCT FROM p_amount THEN RAISE EXCEPTION 'rakeback_payer_total_disagrees' USING ERRCODE='23514'; END IF;
 WITH g AS(
  SELECT a->>'payer_kind' kind,NULLIF(a->>'payer_user_id','')::uuid payer,
   sum((a->>'rake_credit')::numeric) rake,sum((a->>'rake_credit')::numeric*(a->>'rate')::numeric) unrounded,count(*) n
  FROM jsonb_array_elements(p_allocations)a GROUP BY a->>'payer_kind',NULLIF(a->>'payer_user_id','')::uuid
 ), cents AS(
  SELECT g.*,floor(unrounded*100) whole,
   row_number() OVER(ORDER BY unrounded*100-floor(unrounded*100) DESC,kind,payer NULLS FIRST) remainder_rank,
   p_amount*100-sum(floor(unrounded*100)) OVER() extra FROM g
 )SELECT jsonb_agg(jsonb_build_object('payer_kind',kind,'payer_user_id',payer,'rake',rake,
   'unrounded',unrounded,'source_count',n,'amount',(whole+CASE WHEN remainder_rank<=extra THEN 1 ELSE 0 END)/100)
   ORDER BY kind,payer NULLS FIRST) INTO result FROM cents;
 RETURN result;
END $$;


ALTER FUNCTION smarter_private.rakeback_payer_plan(p_allocations jsonb, p_amount numeric) OWNER TO postgres;

