--
-- TOC entry 4662 (class 1255 OID 153542061)
-- Name: register_horse_adaptive_batch_membership(text); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.register_horse_adaptive_batch_membership(p_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $_$
DECLARE b public.horse_adaptive_observation_batches; payload jsonb; hands text[];
BEGIN
 SELECT * INTO b FROM public.horse_adaptive_observation_batches WHERE batch_key=p_key FOR UPDATE;
 IF NOT FOUND OR b.retention_membership_ready THEN RETURN; END IF;
 IF b.canonical_payload IS NOT NULL THEN
  IF octet_length(b.canonical_payload)>16777216 THEN RAISE EXCEPTION 'ADAPTIVE_BATCH_MEMBERSHIP_INVALID'; END IF;
  payload:=b.canonical_payload::jsonb;
  IF jsonb_typeof(payload) IS DISTINCT FROM 'array'
  OR jsonb_array_length(payload)<>8 OR jsonb_typeof(payload->7) IS DISTINCT FROM 'array'
  OR jsonb_array_length(payload->7)>20000 THEN RAISE EXCEPTION 'ADAPTIVE_BATCH_MEMBERSHIP_INVALID'; END IF;
  -- Every original element is parsed and checked before DISTINCT. A malformed
  -- human, unknown or duplicate tuple cannot disappear in the deduplication.
  SELECT array_agg((v.value#>>'{}')::jsonb->>2) INTO hands FROM jsonb_array_elements(payload->7) v;
  IF EXISTS(SELECT 1 FROM unnest(hands) h(hand) WHERE hand IS NULL
   OR hand!~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$')
  THEN RAISE EXCEPTION 'ADAPTIVE_BATCH_MEMBERSHIP_INVALID'; END IF;
  IF cardinality(hands)>0 THEN
   INSERT INTO smarter_private.horse_adaptive_batch_hand_membership(hand_digest,batch_key)
   SELECT encode(sha256(convert_to(hand,'UTF8')),'hex'),p_key FROM (SELECT DISTINCT unnest(hands) hand) h
   ON CONFLICT DO NOTHING;
  END IF;
  -- Most legacy batches contain no retired hand. Preserve their exact original
  -- bytes rather than computing a discarded sanitized representation.
  IF (CASE WHEN b.retention_compacted THEN
   EXISTS(SELECT 1 FROM smarter_private.horse_adaptive_batch_hand_membership m
    JOIN smarter_private.horse_adaptive_disposal_certificates c USING(hand_digest)
    WHERE m.batch_key=p_key AND c.retired_at IS NOT NULL)
   ELSE EXISTS(SELECT 1 FROM
   (SELECT DISTINCT encode(sha256(convert_to(hand,'UTF8')),'hex') hand_digest
    FROM unnest(hands) h(hand)) original
   CROSS JOIN LATERAL (
    SELECT 1 FROM smarter_private.horse_adaptive_disposal_certificates c
    WHERE c.hand_digest=original.hand_digest AND c.retired_at IS NOT NULL
    AND EXISTS(SELECT 1 FROM smarter_private.horse_adaptive_batch_hand_membership m
     WHERE m.hand_digest=original.hand_digest AND m.batch_key=p_key)
    LIMIT 1
   ) retired) END) OR EXISTS(SELECT 1 FROM unnest(hands) h(hand) JOIN smarter_private.horse_adaptive_legacy_learning_purges p ON p.hand_digest=encode(sha256(convert_to(hand,'UTF8')),'hex')) THEN
   UPDATE public.horse_adaptive_observation_batches SET canonical_payload=smarter_private.adaptive_retained_batch(b.canonical_payload),
    retention_compacted=true WHERE batch_key=p_key;
  END IF;
 END IF;
 UPDATE public.horse_adaptive_observation_batches SET retention_membership_ready=true WHERE batch_key=p_key;
END $_$;


ALTER FUNCTION smarter_private.register_horse_adaptive_batch_membership(p_key text) OWNER TO postgres;

--
-- TOC entry 5697 (class 1255 OID 117582111)
-- Name: restore_retired_original_tournament_hand(uuid, text, uuid); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.restore_retired_original_tournament_hand(p_submission_id uuid, p_instance_id text, p_lease_generation uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    AS $$
DECLARE c smarter_private.retirement_original_hand_qualification;
 s smarter_private.hand_submissions; permit smarter_private.f06_hand_permits;
 item jsonb; stack_item jsonb; roster public.tournament_players; seat public.table_seats;
 projected jsonb; lease public.engine_tournament_leases; n integer:=0;
BEGIN
 SELECT * INTO c FROM smarter_private.retirement_original_hand_qualification
 WHERE submission_id=p_submission_id;
 IF NOT FOUND THEN RETURN false; END IF;
 IF auth.role() IS DISTINCT FROM 'service_role' OR p_instance_id IS NULL OR p_lease_generation IS NULL THEN
  RAISE EXCEPTION 'RETIREMENT_ORIGINAL_ENGINE_SUCCESSOR_REQUIRED' USING ERRCODE='42501';
 END IF;
 -- The caller acquires the existing rolling authority before its F06 prefix.
 -- Re-entry here cannot grant an unproven original generation a financial door.
 PERFORM public.fn_ca_lock_settlement_lane_for_tournament(c.tournament_id,c.table_id);
 SELECT * INTO lease FROM public.engine_tournament_leases WHERE tournament_id=c.tournament_id FOR KEY SHARE;
 IF lease.instance_id IS DISTINCT FROM p_instance_id OR lease.lease_generation IS DISTINCT FROM p_lease_generation
 OR lease.protocol_version IS DISTINCT FROM 2 OR lease.heartbeat_at IS NULL
 OR lease.heartbeat_at<clock_timestamp()-make_interval(secs=>public.fn_engine_lease_stale_seconds())
 OR public.fn_platform_frozen() THEN
  RAISE EXCEPTION 'RETIREMENT_ORIGINAL_LEASE_UNPROVEN' USING ERRCODE='55000';
 END IF;
 SELECT * INTO s FROM smarter_private.hand_submissions
 WHERE submission_id=c.submission_id FOR UPDATE;
 IF s.submission_id IS NULL OR s.request_hash IS DISTINCT FROM c.request_hash
 OR (s.table_id,s.hand_number) IS DISTINCT FROM (c.table_id,c.hand_number)
 OR s.lease_generation=p_lease_generation THEN
  RAISE EXCEPTION 'RETIREMENT_ORIGINAL_REQUEST_CHANGED' USING ERRCODE='55000';
 END IF;
 SELECT * INTO permit FROM smarter_private.f06_hand_permits
 WHERE table_id=c.table_id AND hand_number=c.hand_number FOR UPDATE;
 IF permit.permit_id IS NULL OR permit.state IS DISTINCT FROM 'reserved'
 OR permit.tournament_id IS DISTINCT FROM c.tournament_id OR permit.generation IS DISTINCT FROM s.lease_generation
 OR NOT EXISTS(SELECT 1 FROM public.tables t WHERE t.id=c.table_id AND t.tournament_id=c.tournament_id
   AND NOT coalesce(t.is_deleted,false) AND lower(t.status) IN('waiting','running') AND t.lifecycle IS NULL)
 OR NOT EXISTS(SELECT 1 FROM public.tournaments t WHERE t.id=c.tournament_id AND t.status='RUNNING')
 OR EXISTS(SELECT 1 FROM public.hand_atomic_commits a WHERE a.table_id=c.table_id AND a.hand_number>=c.hand_number)
 OR EXISTS(SELECT 1 FROM public.hand_history h WHERE h.table_id=c.table_id AND h.hand_number>=c.hand_number)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_hand_permits p WHERE p.table_id=c.table_id AND p.hand_number>c.hand_number)
 OR EXISTS(SELECT 1 FROM smarter_private.hand_submission_handoffs h WHERE h.submission_id=c.submission_id)
 OR EXISTS(SELECT 1 FROM smarter_private.retirement_original_hand_restorations r WHERE r.submission_id=c.submission_id) THEN
  RAISE EXCEPTION 'RETIREMENT_ORIGINAL_HAND_ALREADY_CONSUMED_OR_SCOPE_CHANGED' USING ERRCODE='55000';
 END IF;
 -- Every dealt player's before-stack and exact seat must still be held.
 -- The 101 unaffected players require ordinary live/playing ownership.
 FOR stack_item IN SELECT value FROM jsonb_array_elements(s.request->'p_stacks') LOOP
  SELECT * INTO roster FROM public.tournament_players
   WHERE tournament_id=c.tournament_id AND user_id=(stack_item->>'user_id')::uuid FOR UPDATE;
  SELECT * INTO seat FROM public.table_seats WHERE id=(stack_item->>'seat_id')::uuid FOR UPDATE;
  IF roster.id IS NULL OR roster.chips::numeric IS DISTINCT FROM (stack_item->>'stack_before')::numeric
  OR seat.id IS NULL OR seat.table_id IS DISTINCT FROM c.table_id
  OR seat.user_id IS DISTINCT FROM (stack_item->>'user_id')::uuid
  OR seat.joined_at IS DISTINCT FROM (stack_item->>'seat_joined_at')::timestamptz
  OR seat.stack IS DISTINCT FROM (stack_item->>'stack_before')::numeric THEN
   RAISE EXCEPTION 'RETIREMENT_ORIGINAL_DEALT_CUSTODY_CHANGED' USING ERRCODE='55000';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c.expected->'rows')x WHERE x->>'user_id'=stack_item->>'user_id')
   AND (roster.status IS DISTINCT FROM 'playing' OR seat.left_at IS NOT NULL) THEN
   RAISE EXCEPTION 'RETIREMENT_ORIGINAL_UNQUALIFIED_PLAYER_CHANGED' USING ERRCODE='55000';
  END IF;
 END LOOP;
 -- Validate ALL qualified post-images before changing the first row.
 FOR item IN SELECT value FROM jsonb_array_elements(c.expected->'rows') ORDER BY value->>'user_id' LOOP
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s.request->'p_stacks')x WHERE x=item->'stack') THEN
   RAISE EXCEPTION 'RETIREMENT_ORIGINAL_PAYLOAD_PLAYER_CHANGED' USING ERRCODE='55000';
  END IF;
  SELECT * INTO roster FROM public.tournament_players WHERE id=(item#>>'{roster,id}')::uuid FOR UPDATE;
  SELECT * INTO seat FROM public.table_seats WHERE id=(item#>>'{seat,id}')::uuid FOR UPDATE;
  SELECT jsonb_object_agg(key,value) INTO projected FROM jsonb_each(to_jsonb(roster))
   WHERE key=ANY(ARRAY['id','user_id','tournament_id','status','chips','position','prize','table_id','seat_number','rebuys','add_on','eliminated_at','current_bounty','bounty_winnings','bounties_collected','rebuy_prompt_until','elimination_sequence']);
  IF projected IS DISTINCT FROM item->'roster' THEN
   RAISE EXCEPTION 'RETIREMENT_ORIGINAL_ROSTER_POSTIMAGE_CHANGED' USING ERRCODE='55000';
  END IF;
  SELECT jsonb_object_agg(key,value) INTO projected FROM jsonb_each(to_jsonb(seat))
   WHERE key=ANY(ARRAY['id','table_id','user_id','club_id','seat_number','joined_at','occupancy_id','stack','left_at','status','is_sitting_out','is_away','leave_pending','active_game_scope','active_parent_key']);
  IF projected IS DISTINCT FROM item->'seat'
  OR roster.status IS DISTINCT FROM 'eliminated' OR roster.chips<=0
  OR roster.position IS NOT NULL OR coalesce(roster.prize,0)<>0
  OR roster.eliminated_at NOT BETWEEN '2026-10-06 15:33:04Z'::timestamptz AND '2026-10-06 15:33:08Z'::timestamptz
  OR seat.left_at NOT BETWEEN '2026-10-06 15:33:04Z'::timestamptz AND '2026-10-06 15:33:08Z'::timestamptz
  OR NOT EXISTS(SELECT 1 FROM smarter_private.patterned_identity_retirements r JOIN public.profiles p ON p.id=r.old_id
    WHERE r.old_id=roster.user_id AND r.cohort='horse' AND r.retired_at IS NOT NULL
      AND r.replacement_horse_id IS NULL AND p.status='deleted' AND p.horse_status='disabled')
  OR EXISTS(SELECT 1 FROM public.tournament_participant_funding_receipts f
    WHERE f.tournament_id=c.tournament_id AND f.user_id=roster.user_id
      AND f.observed_at>=(s.request#>>'{p_hand_row,started_at}')::timestamptz)
  OR EXISTS(SELECT 1 FROM public.tournament_payouts p WHERE p.tournament_id=c.tournament_id AND p.user_id=roster.user_id)
  OR EXISTS(SELECT 1 FROM public.tournament_seat_move_receipts m
    WHERE m.tournament_id=c.tournament_id AND m.user_id=roster.user_id AND m.moved_at>=roster.eliminated_at) THEN
   RAISE EXCEPTION 'RETIREMENT_ORIGINAL_POSTIMAGE_OR_OWNERSHIP_CHANGED' USING ERRCODE='55000';
  END IF;
 END LOOP;
 INSERT INTO smarter_private.retirement_original_hand_restorations
 (submission_id,original_generation,successor_generation,instance_id,request_hash,qualification_hash,transaction_id,restored_players)
 VALUES(c.submission_id,s.lease_generation,p_lease_generation,p_instance_id,c.request_hash,md5(c.expected::text),txid_current(),jsonb_array_length(c.expected->'rows'));
 FOR item IN SELECT value FROM jsonb_array_elements(c.expected->'rows') ORDER BY value->>'user_id' LOOP
  UPDATE public.tournament_players SET status='playing',eliminated_at=NULL
   WHERE id=(item#>>'{roster,id}')::uuid;
  UPDATE public.table_seats SET left_at=NULL,status='active'
   WHERE id=(item#>>'{seat,id}')::uuid;
  n:=n+1;
 END LOOP;

 RETURN true;
END $$;


ALTER FUNCTION smarter_private.restore_retired_original_tournament_hand(p_submission_id uuid, p_instance_id text, p_lease_generation uuid) OWNER TO postgres;

--
-- TOC entry 5415 (class 1255 OID 153542042)
-- Name: retire_horse_adaptive_hand(uuid); Type: FUNCTION; Schema: smarter_private; Owner: postgres
--

CREATE FUNCTION smarter_private.retire_horse_adaptive_hand(p_hand uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'smarter_private'
    SET lock_timeout TO '2s'
    AS $$
DECLARE c smarter_private.horse_adaptive_disposal_certificates; b record; kept jsonb; key text; n integer;
BEGIN
 SELECT * INTO c FROM smarter_private.horse_adaptive_disposal_certificates WHERE hand_id=p_hand FOR UPDATE;
 IF NOT FOUND THEN RETURN 0; END IF;
 IF NOT smarter_private.horse_adaptive_disposal_certificate_matches(c.hand_id,c.table_id,c.hand_number,c.request_hash) THEN RETURN 0; END IF;
 IF c.raw_format_version=2 THEN
  IF EXISTS(SELECT 1 FROM public.horse_adaptive_observation_journal j
   WHERE j.observation_id>=p_hand::text||':0' AND j.observation_id<=p_hand::text||':9999' AND j.hand_id=p_hand)
  THEN RAISE EXCEPTION 'ADAPTIVE_COMPLETED_FORMAT_HAS_RAW'; END IF;
  RETURN 0;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM smarter_private.horse_adaptive_retention_activation WHERE singleton AND enabled)
 OR NOT pg_try_advisory_xact_lock(hashtextextended('horse-adaptive-work-capacity-v1',0)) THEN RETURN 0; END IF;
 -- Qualification was made at the original disposal boundary. Never acquire a
 -- new classification from current player/actor origin or an erased roster.
 IF EXISTS(SELECT 1 FROM public.hand_history WHERE id=p_hand AND (has_human IS true OR reported IS true))
 OR smarter_private.f06_hand_cards_unresolved(c.table_id,c.hand_number)
 OR smarter_private.f06_movement_boundary_retained(c.table_id,c.hand_number)
 OR EXISTS(SELECT 1 FROM public.bbj_payouts WHERE table_id=c.table_id AND hand_number=c.hand_number)
 OR EXISTS(SELECT 1 FROM public.hand_projection_outbox WHERE hand_id=p_hand)
 OR EXISTS(SELECT 1 FROM public.tournament_knockout_candidates WHERE hand_id=p_hand AND state='pending') THEN RETURN 0; END IF;
 IF EXISTS(SELECT 1 FROM public.horse_adaptive_journal_work w
 WHERE w.state<>'completed' AND EXISTS(SELECT 1 FROM jsonb_array_elements(w.payload::jsonb->7) v
 WHERE (v.value#>>'{}')::jsonb->>2=p_hand::text)) THEN RETURN 0; END IF;
 -- Until the bounded existing retention owner has qualified every legacy
 -- batch's exact membership, no hand is declared fully retired. Fresh inserts
 -- register through their original write event, including an old in-flight
 -- writer whose function body predates this migration.
 IF EXISTS(SELECT 1 FROM public.horse_adaptive_observation_batches WHERE NOT retention_membership_ready LIMIT 1) THEN RETURN 0; END IF;
 FOR key IN SELECT batch_key FROM smarter_private.horse_adaptive_batch_hand_membership WHERE hand_digest=c.hand_digest LOOP
  IF EXISTS(SELECT 1 FROM public.horse_adaptive_journal_work WHERE batch_key=key AND state<>'completed') THEN RETURN 0; END IF;
 END LOOP;
 -- Every original fact must remain canonical before aggregation. One malformed
 -- or conflicting hand/session/partition relationship aborts the whole transition.
 IF EXISTS(SELECT 1 FROM public.horse_adaptive_observation_journal j
 WHERE j.observation_id>=p_hand::text||':0' AND j.observation_id<=p_hand::text||':9999' AND j.hand_id=p_hand
 AND (jsonb_typeof(j.payload::jsonb) IS DISTINCT FROM 'array' OR jsonb_array_length(j.payload::jsonb)<>12
 OR j.payload::jsonb->0 IS DISTINCT FROM '1'::jsonb OR j.payload::jsonb->>1 IS DISTINCT FROM j.observation_id OR j.payload::jsonb->>2 IS DISTINCT FROM p_hand::text
 OR j.payload::jsonb->>3 IS DISTINCT FROM j.actor_key OR j.payload::jsonb->>4 IS DISTINCT FROM j.session_key
 OR j.payload::jsonb->>5 IS DISTINCT FROM j.observed_at_ms::text OR j.payload::jsonb->>6 IS DISTINCT FROM j.partition
 OR j.payload::jsonb->>7 IS DISTINCT FROM j.scope_key OR j.payload::jsonb->>11 IS DISTINCT FROM j.origin
 OR jsonb_typeof(j.payload::jsonb->10) IS DISTINCT FROM 'boolean' OR encode(sha256(convert_to(j.payload::jsonb->>8,'UTF8')),'hex') IS DISTINCT FROM j.scope_key OR j.payload::jsonb->>9 NOT IN('fold','check','call','bet','raise'))) THEN RAISE EXCEPTION 'ADAPTIVE_RETENTION_INVALID_FACT'; END IF;
 IF EXISTS(SELECT 1 FROM public.horse_adaptive_observation_journal j
 WHERE j.observation_id>=p_hand::text||':0' AND j.observation_id<=p_hand::text||':9999' AND j.hand_id=p_hand
 GROUP BY actor_key HAVING count(DISTINCT session_key)>1 OR count(DISTINCT partition)>1)
 THEN RAISE EXCEPTION 'ADAPTIVE_RETENTION_PARTITION_CONFLICT'; END IF;
 INSERT INTO smarter_private.horse_adaptive_observation_fences
 SELECT encode(sha256(convert_to(j.observation_id,'UTF8')),'hex'),c.hand_digest,encode(sha256(convert_to(j.payload,'UTF8')),'hex')
 FROM public.horse_adaptive_observation_journal j
 WHERE j.observation_id>=p_hand::text||':0' AND j.observation_id<=p_hand::text||':9999' AND j.hand_id=p_hand;
 INSERT INTO smarter_private.horse_adaptive_statistics
 SELECT c.hand_digest,j.actor_key,j.session_key,j.partition,j.scope_key,j.origin,j.observed_at_ms,j.payload::jsonb->>9,count(*)::integer
 FROM public.horse_adaptive_observation_journal j
 WHERE j.observation_id>=p_hand::text||':0' AND j.observation_id<=p_hand::text||':9999' AND j.hand_id=p_hand
 GROUP BY j.actor_key,j.session_key,j.partition,j.scope_key,j.origin,j.observed_at_ms,j.payload::jsonb->>9;
 -- Retire only eligible tuples within a batch. Human/other-hand tuples stay
 -- byte-identical strings. Originalbatch digest remains the immutable replay fence;
 -- recovery explicitly refuses this partially retired representation.
 FOR b IN SELECT batch_key FROM smarter_private.horse_adaptive_batch_hand_membership WHERE hand_digest=c.hand_digest
 LOOP
  SELECT canonical_payload::jsonb INTO kept FROM public.horse_adaptive_observation_batches WHERE batch_key=b.batch_key FOR UPDATE;
  IF kept IS NOT NULL THEN
   kept:=jsonb_set(kept,'{7}',COALESCE((SELECT jsonb_agg(value ORDER BY ordinality)
    FROM jsonb_array_elements(kept->7) WITH ORDINALITY
    WHERE (value#>>'{}')::jsonb->>2 IS DISTINCT FROM p_hand::text),'[]'::jsonb));
   UPDATE public.horse_adaptive_observation_batches SET canonical_payload=kept::text,retention_compacted=true WHERE batch_key=b.batch_key;
  END IF;
 END LOOP;
 DELETE FROM public.horse_adaptive_observation_journal j
 WHERE j.observation_id>=p_hand::text||':0' AND j.observation_id<=p_hand::text||':9999' AND j.hand_id=p_hand;
 GET DIAGNOSTICS n=ROW_COUNT;
 UPDATE smarter_private.horse_adaptive_disposal_certificates
 SET retired_at=COALESCE(c.retired_at,clock_timestamp()),raw_format_version=2 WHERE hand_id=p_hand;
 RETURN n;
END $$;


ALTER FUNCTION smarter_private.retire_horse_adaptive_hand(p_hand uuid) OWNER TO postgres;

