-- Name: TABLE accounting_cash_accrual_batches; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.accounting_cash_accrual_batches IS 'Append-only, immutable by trigger. One row per cash rake_record. A legacy_unverified row LATCHES that verdict: fn_accrue_cash_hand_commissions returns duplicate=true on the batch lookup BEFORE it reads the cutover, so moving the cutover can never release one. As of 2026-09-20 this table holds 150 such rows, earned 2026-09-17 07:28:33 to 07:34:04, carrying 266.61 of rake across 119 players and 2 clubs, with zero agent_commissions, zero accounting_cash_rake_sources and zero rakeback_stats_applied rows against them. They were orphaned by a cutover armed ahead of the settler cursor and they remain unsettled.';


