-- Name: TABLE accounting_cash_accrual_cutover; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.accounting_cash_accrual_cutover IS 'Singleton. The instant the canonical cash accrual writer takes over from the legacy settler writer. Two invariants are enforced on write: it must fall on a union week boundary (ca_cash_cutover_is_week_aligned) and it must be at or before the rakeback_settler cursor (ca_cash_cutover_not_ahead_of_settler). A cutover that leads the cursor opens a window no writer owns.';


