--

CREATE VIEW public.accounting_effective_cash_rake_sources WITH (security_invoker='true') AS
 SELECT s.id,
    s.rake_record_id,
    s.player_id,
    s.club_id,
    s.union_id,
    s.coordinator_union_id,
    s.earned_at,
    s.rake_credit,
    COALESCE(a.admitted_contract, s.contract) AS contract,
    GREATEST(s.recorded_at, a.admitted_at) AS recorded_at
   FROM (public.accounting_cash_rake_sources s
     LEFT JOIN public.accounting_cash_atomic_contract_admissions a ON ((a.source_id = s.id)));


