    CONSTRAINT ca_cash_failed_run_outcomes_outcome_check CHECK ((outcome = ANY (ARRAY['delivered'::text, 'intake_failed'::text]))),
    CONSTRAINT ca_cash_failed_run_outcomes_receipt_payload_check CHECK (((receipt_payload IS NULL) OR (octet_length((receipt_payload)::text) <= 32768))),
    CONSTRAINT ca_cash_failed_run_outcomes_run_snapshot_check CHECK (((jsonb_typeof(run_snapshot) = 'object'::text) AND (octet_length((run_snapshot)::text) <= 32768))),
    CONSTRAINT ca_cash_failed_run_outcomes_runid_check CHECK ((runid > 0)),
    CONSTRAINT ca_cash_failed_run_outcomes_snapshot_md5_check CHECK ((snapshot_md5 ~ '^[0-9a-f]{32}$'::text))
);


