--
-- TOC entry 2367 (class 1259 OID 19182966)
-- Name: ca_diamond_dead_store_writes; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.ca_diamond_dead_store_writes WITH (security_invoker='true') AS
 SELECT d.store,
    d.dead_column,
    d.holdings_at_2026_09_03,
    COALESCE(s.n_tup_ins, (0)::bigint) AS n_tup_ins,
    COALESCE(s.n_tup_upd, (0)::bigint) AS n_tup_upd,
    COALESCE(s.n_tup_del, (0)::bigint) AS n_tup_del,
    ((COALESCE(s.n_tup_ins, (0)::bigint) + COALESCE(s.n_tup_upd, (0)::bigint)) + COALESCE(s.n_tup_del, (0)::bigint)) AS writes,
    s.last_autoanalyze,
    s.last_autovacuum,
    d.writer_evidence
   FROM (( VALUES ('diamond_ledger'::text,'(the whole table)'::text,'0 rows all time'::text,'One function names it, complete_daily_challenge, which is EXECUTE-granted to postgres and service_role only. The live daily-challenge path is claim_daily_challenge(s), which journals to diamond_transactions.'::text), ('user_progress'::text,'diamonds'::text,'107 rows, 10,700 diamonds'::text,'create_user_progress_on_signup is the only writer and is attached to NO trigger (pg_trigger scan, 2026-09-03). A fossil of the pre-profiles balance.'::text), ('bot_profiles'::text,'diamonds'::text,'100 rows, 26,541 diamonds'::text,'No function in the database inserts, updates or deletes this relation.'::text), ('club_members'::text,'diamonds'::text,'0 diamonds across 1,935 rows'::text,'No function writes club_members.diamonds. Two bodies match a naive club_members-near-set-diamonds scan (fn_atomic_buyin, fn_union_send_to_member_zd3core) and BOTH write profiles.diamonds; the column is a false positive. club_members.chip_balance is written constantly and is not this column.'::text), ('club_memberships'::text,'diamonds'::text,'0 diamonds'::text,'No function in the database names this relation at all.'::text), ('club_diamond_wallets'::text,'balance'::text,'2 rows, 0.00'::text,'One function names it (ca_promo_vault_buy). Both rows have held 0.00 since creation.'::text)) d(store, dead_column, holdings_at_2026_09_03, writer_evidence)
     LEFT JOIN pg_stat_user_tables s ON (((s.schemaname = 'public'::name) AND (s.relname = d.store))));


ALTER VIEW public.ca_diamond_dead_store_writes OWNER TO postgres;

--
-- TOC entry 51923 (class 0 OID 0)
-- Dependencies: 2367
-- Name: VIEW ca_diamond_dead_store_writes; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.ca_diamond_dead_store_writes IS 'DR10 delete-list evidence for standard section 5 Lane G. Nothing is dropped: the delete list is gated on seven days of zero writes and this view is the gate. writes > 0 on any row means that store is NOT dead and the row must be re-investigated before anyone drops anything. Read it beside the dead_stores row of fn_ca_diamond_trial_balance.';


--
-- TOC entry 3075 (class 1259 OID 109364737)
-- Name: ca_diamond_economics; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ca_diamond_economics (
    id bigint NOT NULL,
    name text NOT NULL,
    scope text DEFAULT 'all'::text NOT NULL,
    value numeric,
    value_text text,
    units text NOT NULL,
    approved_quote text NOT NULL,
    basis text NOT NULL,
    approved_on date NOT NULL,
    recorded_by text NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ca_diamond_economics_basis_not_empty CHECK ((btrim(basis) <> ''::text)),
    CONSTRAINT ca_diamond_economics_boolean_shape CHECK (((units <> 'boolean'::text) OR (value_text = ANY (ARRAY['yes'::text, 'no'::text])))),
    CONSTRAINT ca_diamond_economics_choice_is_an_option CHECK (((units <> 'choice'::text) OR
CASE name
    WHEN 'guarantee_covers'::text THEN (value_text = ANY (ARRAY['prize_pool_only'::text, 'prize_pool_and_bounties'::text]))
    WHEN 'guarantee_funding_moment'::text THEN (value_text = ANY (ARRAY['set_aside_at_creation'::text, 'checked_at_creation_paid_at_close'::text]))
    WHEN 'freeroll_rebuy_cost'::text THEN (value_text = ANY (ARRAY['none_offered'::text, 'one_diamond_to_the_prize_pool'::text, 'one_hundred_diamonds_to_the_prize_pool'::text]))
    WHEN 'freeroll_addon_cost'::text THEN (value_text = ANY (ARRAY['none_offered'::text, 'one_diamond_to_the_prize_pool'::text, 'one_hundred_diamonds_to_the_prize_pool'::text]))
    WHEN 'promo_entry_refund_destination'::text THEN (value_text = ANY (ARRAY['funding_account'::text, 'unused_promotional_entry'::text, 'player_wallet'::text]))
    WHEN 'horse_entry_funding'::text THEN (value_text = ANY (ARRAY['own_balance'::text, 'funding_account'::text]))
    WHEN 'cash_rake_rounding'::text THEN (value_text = ANY (ARRAY['down'::text, 'nearest'::text, 'up'::text]))
    ELSE false
END)),
    CONSTRAINT ca_diamond_economics_has_exactly_one_value CHECK (((value IS NULL) <> (value_text IS NULL))),
    CONSTRAINT ca_diamond_economics_quote_and_basis_are_stated CHECK (((length(btrim(approved_quote)) > 0) AND (length(btrim(basis)) > 0))),
    CONSTRAINT ca_diamond_economics_quote_not_empty CHECK ((btrim(approved_quote) <> ''::text)),
    CONSTRAINT ca_diamond_economics_recorder_not_empty CHECK ((btrim(recorded_by) <> ''::text)),
    CONSTRAINT ca_diamond_economics_role_is_real CHECK (((units <> 'role'::text) OR (value_text = ANY (ARRAY['platform_admin'::text, 'owner_only'::text])))),
    CONSTRAINT ca_diamond_economics_scope_is_stated CHECK (((length(btrim(scope)) > 0) AND (scope = lower(scope)))),
    CONSTRAINT ca_diamond_economics_value_is_sane CHECK (((value IS NULL) OR ((value >= (0)::numeric) AND ((units = 'percent'::text) OR (value = trunc(value))) AND ((units <> 'percent'::text) OR (value <= (100)::numeric)))))
);


ALTER TABLE public.ca_diamond_economics OWNER TO postgres;

--
-- TOC entry 51925 (class 0 OID 0)
-- Dependencies: 3075
-- Name: TABLE ca_diamond_economics; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ca_diamond_economics IS 'Every number, switch, account and choice the Diamond economy runs on, one append-only row each, with the owner words that authorise it and the derivation that produced it. Section 3.2 of docs/DIAMOND-DESTINATIONS-DESIGN-2026-09-21.md. The current value of a name is its LATEST row for a scope; a changed answer is a new row, never an edit. Read only through fn_ca_diamond_economic and fn_ca_diamond_economic_text, which refuse by name when a value is unset. Shared by every Phase 9 lane: guarantees and promotional entries (A rows), cash rake and BBJ (B rows), the chip-leg refusals (C rows).';


