--
-- TOC entry 3226 (class 1259 OID 159428402)
-- Name: ca_launch_bbj_reporting_contributions; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.ca_launch_bbj_reporting_contributions WITH (security_invoker='true') AS
 WITH starts AS (
         SELECT r.row_key,
            max(o.captured_at) AS s
           FROM (public.ca_launch_reset_operations o
             JOIN public.ca_launch_reset_rows r ON ((r.operation_id = o.operation_id)))
          WHERE ((o.state = 'executed'::text) AND (r.relation_name = 'bbj_pools'::text))
          GROUP BY r.row_key
        )
 SELECT c.id,
    c.pool_id,
    c.club_id,
    c.table_id,
    c.hand_number,
    c.amount,
    c.big_blind,
    c.stakes_tier,
    c.created_at,
    c.main_portion,
    c.backup_portion,
    c.promo_portion,
    c.hand_id
   FROM (public.bbj_contributions c
     LEFT JOIN starts st ON ((st.row_key = jsonb_build_object('id', c.pool_id))))
  WHERE (c.created_at >= COALESCE(st.s, '-infinity'::timestamp with time zone));


ALTER VIEW public.ca_launch_bbj_reporting_contributions OWNER TO postgres;

--
-- TOC entry 3227 (class 1259 OID 159428411)
-- Name: ca_launch_bbj_reporting_winners; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.ca_launch_bbj_reporting_winners WITH (security_invoker='true') AS
 WITH starts AS (
         SELECT r.row_key,
            max(o.captured_at) AS s
           FROM (public.ca_launch_reset_operations o
             JOIN public.ca_launch_reset_rows r ON ((r.operation_id = o.operation_id)))
          WHERE ((o.state = 'executed'::text) AND (r.relation_name = 'bbj_pools'::text))
          GROUP BY r.row_key
        )
 SELECT w.id,
    w.club_id,
    w.pool_id,
    w.loser_id,
    w.winner_id,
    w.loser_hand,
    w.winner_hand,
    w.loser_payout,
    w.winner_payout,
    w.table_share_payout,
    w.total_payout,
    w.pool_amount_at_hit,
    w.stakes_tier,
    w.table_id,
    w.hand_number,
    w.awarded_at,
    w.winner_display_name,
    w.loser_display_name,
    w.kind
   FROM (public.bbj_winners w
     LEFT JOIN starts st ON ((st.row_key = jsonb_build_object('id', w.pool_id))))
  WHERE (w.awarded_at >= COALESCE(st.s, '-infinity'::timestamp with time zone));


ALTER VIEW public.ca_launch_bbj_reporting_winners OWNER TO postgres;

