-- Name: cash_cluster_conversion; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.cash_cluster_conversion (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    cluster_id uuid NOT NULL,
    conversion_request_id uuid NOT NULL,
    from_mode text NOT NULL,
    to_mode text NOT NULL,
    trigger_population integer NOT NULL,
    on_threshold integer NOT NULL,
    off_threshold integer NOT NULL,
    epoch_before integer NOT NULL,
    epoch_after integer,
    status text DEFAULT 'pending'::text NOT NULL,
    abort_reason text,
    opened_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    closed_at timestamp with time zone,
    chips_at_begin numeric(14,2),
    chips_at_commit numeric(14,2),
    CONSTRAINT cash_cluster_conversion_close_is_complete CHECK ((((status = 'pending'::text) AND (closed_at IS NULL) AND (epoch_after IS NULL) AND (abort_reason IS NULL)) OR ((status = 'committed'::text) AND (closed_at IS NOT NULL) AND (epoch_after IS NOT NULL) AND (abort_reason IS NULL)) OR ((status = 'aborted'::text) AND (closed_at IS NOT NULL) AND (epoch_after IS NULL) AND (abort_reason IS NOT NULL)))),
    CONSTRAINT cash_cluster_conversion_epoch_goes_forward CHECK (((epoch_after IS NULL) OR (epoch_after > epoch_before))),
    CONSTRAINT cash_cluster_conversion_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'committed'::text, 'aborted'::text]))),
    CONSTRAINT cash_cluster_conversion_thresholds_are_hysteretic CHECK (((on_threshold > off_threshold) AND (off_threshold >= 2)))
);


ALTER TABLE public.cash_cluster_conversion OWNER TO postgres;

--
-- TOC entry 52265 (class 0 OID 0)
-- Dependencies: 2808
-- Name: TABLE cash_cluster_conversion; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.cash_cluster_conversion IS 'One row per attempted Cluster mode conversion, carrying the nine things the specification requires a conversion to record. The partial unique index on (cluster_id) WHERE status = pending is F13''s answer - two simultaneous converters cannot both open one - and the unique conversion_request_id makes a retry of the same request idempotent and answerable with what already happened rather than merely refused.';


--
-- TOC entry 52266 (class 0 OID 0)
-- Dependencies: 2808
-- Name: COLUMN cash_cluster_conversion.chips_at_begin; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.cash_cluster_conversion.chips_at_begin IS 'Forensics: the sum of table_seats.stack over the Cluster''s seated rows at fn_cash_cluster_begin_pending_on, the instant its tables were halted.';


--
-- TOC entry 52267 (class 0 OID 0)
-- Dependencies: 2808
-- Name: COLUMN cash_cluster_conversion.chips_at_commit; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.cash_cluster_conversion.chips_at_commit IS 'Forensics: the same sum at fn_cash_cluster_commit_lightning, which asserts it did not change during its own transaction. A difference from chips_at_begin is money that moved while the Cluster was PENDING_ON: hands finishing, buy-ins and cash-outs, each of which is legal.';


--
