    CONSTRAINT cash_cluster_epoch_nonneg CHECK ((epoch >= 0))
);


ALTER TABLE public.cash_cluster_epoch OWNER TO postgres;

--
-- TOC entry 52269 (class 0 OID 0)
-- Dependencies: 2807
-- Name: TABLE cash_cluster_epoch; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.cash_cluster_epoch IS 'Append-only history of a Cluster''s seating regimes: one row per (cluster, epoch), the mode it ran under, when it started and when it ended. cash_games.cluster_epoch is the pointer to the current one; this is what it points at. Rows are never deleted and never renumbered, which is what makes them safe to reference from Lightning history.';


--
