-- TOC entry 1876 (class 1259 OID 5002132)
-- Name: home_game_groups; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.home_game_groups WITH (security_invoker='true') AS
 SELECT g.id,
    g.name,
    COALESCE(sp.slug, (g.id)::text) AS slug,
    g.city,
    g.state,
    g.profile_photo_url,
    g.default_game_type,
    g.default_stakes,
    g.owner_id,
    g.is_private,
    g.is_21_plus,
    g.is_active,
    g.member_count,
    g.created_at,
    g.tagline,
    g.club_code,
    g.invite_code
   FROM (public.commander_home_groups g
     LEFT JOIN public.social_pages sp ON (((sp.linked_entity_type = 'home_group'::text) AND (sp.linked_entity_id = (g.id)::text))));


ALTER VIEW public.home_game_groups OWNER TO postgres;

--
-- TOC entry 1877 (class 1259 OID 5035994)
-- Name: home_game_members; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.home_game_members WITH (security_invoker='true') AS
 SELECT m.id,
    m.group_id,
    m.user_id,
        CASE
            WHEN (m.role = 'owner'::text) THEN 'host'::text
            ELSE m.role
        END AS role,
        CASE
            WHEN (m.status = 'approved'::text) THEN 'active'::text
            ELSE m.status
        END AS status,
    m.joined_at
   FROM (public.commander_home_members m
     JOIN public.commander_home_groups g ON ((g.id = m.group_id)))
  WHERE (((g.is_private = false) AND (g.is_active = true) AND (m.status = 'approved'::text)) OR ((auth.uid() IS NOT NULL) AND (m.user_id = auth.uid())) OR ((auth.uid() IS NOT NULL) AND public.fn_home_is_group_staff(auth.uid(), m.group_id)));


ALTER VIEW public.home_game_members OWNER TO postgres;

