-- Name: COLUMN lightning_hand.blind_algorithm_version; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.lightning_hand.blind_algorithm_version IS 'Specification 2140. ''fn_lightning_blind_order:'' plus the md5 of that function''s installed source at formation, so an edit to the P2 key cannot leave later hands claiming the old one. Immutable from birth.';


--
