-- Dependencies: 2805
-- Name: COLUMN lightning_hand.lightning_version; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.lightning_hand.lightning_version IS 'Specification 2141. ''fn_lightning_form_hand:'' plus the md5 of the barrier''s installed source at formation: exactly the code that formed the hand. Immutable from birth.';


--
