--
-- TOC entry 2855 (class 1259 OID 59858794)
-- Name: mv_active_poker_locations; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.mv_active_poker_locations WITH (security_invoker='true', security_barrier='true') AS
 SELECT source,
    entity_id,
    name,
    slug,
    venue_type,
    city,
    state,
    country,
    lat,
    lng,
    location_geog,
    photo_url,
    tagline,
    activity_score,
    has_tournaments,
    is_verified,
    poker_tables,
    stakes_cash,
    games_offered,
    member_count,
    games_hosted,
    is_private,
    refreshed_at
   FROM discovery_private.mv_active_poker_locations cache
  WHERE ((source = 'venue'::text) OR ((source = 'home_group'::text) AND (EXISTS ( SELECT 1
           FROM public.commander_home_groups current_group
          WHERE ((current_group.id =
                CASE
                    WHEN (cache.source = 'home_group'::text) THEN (cache.entity_id)::uuid
                    ELSE NULL::uuid
                END) AND (current_group.is_active IS TRUE) AND (current_group.is_private IS FALSE) AND (current_group.profile_photo_url IS NOT NULL) AND (current_group.last_activity_at > (now() - '45 days'::interval)) AND (current_group.location_geog IS NOT NULL))))));


ALTER VIEW public.mv_active_poker_locations OWNER TO postgres;

