--
-- TOC entry 53465 (class 0 OID 0)
-- Dependencies: 2884
-- Name: TABLE poker_diamond_spin_contracts; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.poker_diamond_spin_contracts IS 'DIAMOND SPIN CONTRACT (Phase 9). The multiplier table a Diamond Spin was created with, validated by fn_poker_diamond_spin_contract at its buy-in and pinned by sha256. The draw rolls over this table and nothing else; the engine''s compiled manifest cannot change it. worst_excess is the most the source can pay into the pool above the three entries; required_cover is what the source must hold for every tier to be drawable (the pool above the entries, and a tier''s reserve threshold times its pool - the chip reserve gate, with the event''s own buy-in as its stake).';


