    projected_high_score integer,
    action text NOT NULL,
    evidence_session_id uuid,
    evidence_kind text,
    reconciled_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT trivia_endless_high_score_reconcilia_projected_high_score_check CHECK ((projected_high_score >= 0)),
    CONSTRAINT trivia_endless_high_score_reconciliat_previous_high_score_check CHECK ((previous_high_score >= 0)),
    CONSTRAINT trivia_endless_high_score_reconciliati_trusted_high_score_check CHECK ((trusted_high_score >= 0)),
    CONSTRAINT trivia_endless_high_score_reconciliation_shape_ck CHECK ((((action = 'deleted'::text) AND (previous_high_score IS NOT NULL) AND (trusted_high_score IS NULL) AND (projected_high_score IS NULL) AND (evidence_session_id IS NULL) AND (evidence_kind IS NULL)) OR ((action = 'inserted'::text) AND (previous_high_score IS NULL) AND (trusted_high_score IS NOT NULL) AND (projected_high_score = trusted_high_score) AND (evidence_session_id IS NOT NULL) AND (evidence_kind IS NOT NULL)) OR ((action = ANY (ARRAY['preserved'::text, 'lowered'::text, 'raised'::text])) AND (previous_high_score IS NOT NULL) AND (trusted_high_score IS NOT NULL) AND (projected_high_score = trusted_high_score) AND (evidence_session_id IS NOT NULL) AND (evidence_kind IS NOT NULL)))),
    CONSTRAINT trivia_endless_high_score_reconciliations_v1_action_check CHECK ((action = ANY (ARRAY['preserved'::text, 'lowered'::text, 'raised'::text, 'inserted'::text, 'deleted'::text]))),
    CONSTRAINT trivia_endless_high_score_reconciliations_v1_variant_check CHECK ((variant = 'random'::text)),
    CONSTRAINT trivia_endless_high_score_reconciliations_v_evidence_kind_check CHECK ((evidence_kind = ANY (ARRAY['engine_v3'::text, 'legacy'::text])))
);


