CREATE VIEW public.trivia_free_fallback_questions_v1 WITH (security_invoker='true') AS
 SELECT q.id,
    q.category,
    q.subcategory,
    q.difficulty,
    q.question,
    q.options,
    q.quality_score,
    q.theme,
    q.daily_date,
    q.order_index,
    q.last_used_at,
    e.modes
   FROM (public.trivia_question_eligibility_v1 e
     JOIN public.trivia_questions q ON ((q.id = e.question_id)))
  WHERE (e.structurally_valid AND e.is_canonical AND (NOT e.quarantined) AND (e.open_valid_reports = 0) AND (COALESCE(q.quality_score, 0) >= 6) AND (q.audit_verified IS DISTINCT FROM false));


ALTER VIEW public.trivia_free_fallback_questions_v1 OWNER TO postgres;

