--
-- TOC entry 1943 (class 1259 OID 6952794)
-- Name: trivia_question_player_stats; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.trivia_question_player_stats WITH (security_invoker='true') AS
 SELECT id,
    category,
    difficulty,
    times_shown,
    times_correct,
    skipped_count,
        CASE
            WHEN (times_shown >= 30) THEN round((((times_correct)::numeric / (times_shown)::numeric) * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS success_rate_pct,
        CASE
            WHEN ((times_shown >= 30) AND (difficulty = 'easy'::text) AND (((times_correct)::numeric / (times_shown)::numeric) < 0.40)) THEN 'too-hard-or-wrong'::text
            WHEN ((times_shown >= 30) AND (difficulty = 'hard'::text) AND (((times_correct)::numeric / (times_shown)::numeric) > 0.95)) THEN 'mislabeled-easy'::text
            WHEN ((times_shown >= 30) AND (difficulty = 'medium'::text) AND (((times_correct)::numeric / (times_shown)::numeric) < 0.30)) THEN 'suspect-bad'::text
            WHEN ((times_shown >= 30) AND (((skipped_count)::numeric / (times_shown)::numeric) > 0.20)) THEN 'high-skip'::text
            ELSE 'ok'::text
        END AS player_signal,
    quality_score
   FROM public.trivia_questions;


ALTER VIEW public.trivia_question_player_stats OWNER TO postgres;

--
-- TOC entry 1514 (class 1259 OID 188338)
-- Name: trivia_question_pool_stats; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.trivia_question_pool_stats WITH (security_invoker='true') AS
 SELECT category,
    count(*) AS total_count,
    count(*) FILTER (WHERE (difficulty = 'easy'::text)) AS easy_count,
    count(*) FILTER (WHERE (difficulty = 'medium'::text)) AS medium_count,
    count(*) FILTER (WHERE (difficulty = 'hard'::text)) AS hard_count,
    count(*) FILTER (WHERE (last_used_at IS NULL)) AS never_used,
    count(*) FILTER (WHERE (last_used_at > (now() - '60 days'::interval))) AS used_recently,
    count(*) FILTER (WHERE ((last_used_at IS NULL) OR (last_used_at <= (now() - '60 days'::interval)))) AS available_now
   FROM public.trivia_questions
  GROUP BY category
  ORDER BY category;


ALTER VIEW public.trivia_question_pool_stats OWNER TO postgres;

--
-- TOC entry 2937 (class 1259 OID 74719967)
-- Name: trivia_question_report_queue_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.trivia_question_report_queue_v1 WITH (security_invoker='true') AS
 SELECT r.id AS report_id,
    r.question_id,
    r.state,
    r.valid,
    r.reason,
    r.note,
    r.created_at,
    r.reporter_established,
    r.served_to_reporter,
    r.session_id,
    r.revision_id,
    r.triaged_at,
    r.triaged_by,
    r.triage_note,
    (floor((EXTRACT(epoch FROM (now() - r.created_at)) / (3600)::numeric)))::integer AS age_hours,
    ( SELECT (count(*))::integer AS count
           FROM public.trivia_question_reports o
          WHERE ((o.question_id = r.question_id) AND (o.state = ANY (ARRAY['open'::text, 'triaged'::text])) AND o.valid)) AS open_valid_for_question,
    e.reject_reasons,
    q.category,
    q.difficulty
   FROM ((public.trivia_question_reports r
     JOIN public.trivia_questions q ON ((q.id = r.question_id)))
     LEFT JOIN public.trivia_question_eligibility_v1 e ON ((e.question_id = r.question_id)))
  WHERE (r.state = ANY (ARRAY['open'::text, 'triaged'::text]));


