CREATE VIEW public.trivia_question_review_history_v1 WITH (security_invoker='true') AS
 SELECT rv.question_id,
    rv.reviewed_at,
    rv.reviewer,
    rv.reviewer_kind,
    rv.model,
    rv.model_version,
    rv.prompt_version,
    rv.verdict,
