--

CREATE VIEW public.union_pnl_inventory_published_issues WITH (security_invoker='true') AS
 SELECT union_pnl_inventory_checkpoint_issues.boundary,
    union_pnl_inventory_checkpoint_issues.source_name,
    union_pnl_inventory_checkpoint_issues.row_id,
    union_pnl_inventory_checkpoint_issues.event_id
   FROM public.union_pnl_inventory_checkpoint_issues
UNION ALL
 SELECT r.boundary,
    r.source_name,
    r.row_id,
    r.event_id
   FROM ((public.union_pnl_inventory_seal_build_issues r
     JOIN public.union_pnl_inventory_checkpoints c ON ((c.boundary = r.boundary)))
     JOIN public.union_pnl_inventory_seal_builds b ON (((b.boundary = r.boundary) AND b.ready)));


