-- TOC entry 3200 (class 1259 OID 154605422)
-- Name: union_pnl_inventory_published_rows; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.union_pnl_inventory_published_rows WITH (security_invoker='true') AS
 SELECT union_pnl_inventory_checkpoint_rows.boundary,
    union_pnl_inventory_checkpoint_rows.source_name,
    union_pnl_inventory_checkpoint_rows.row_id,
    union_pnl_inventory_checkpoint_rows.latest_event_id,
    union_pnl_inventory_checkpoint_rows.first_operation,
    union_pnl_inventory_checkpoint_rows.after_row
   FROM public.union_pnl_inventory_checkpoint_rows
UNION ALL
 SELECT r.boundary,
    r.source_name,
    r.row_id,
    r.latest_event_id,
    r.first_operation,
    r.after_row
   FROM ((public.union_pnl_inventory_seal_build_rows r
     JOIN public.union_pnl_inventory_checkpoints c ON ((c.boundary = r.boundary)))
     JOIN public.union_pnl_inventory_seal_builds b ON (((b.boundary = r.boundary) AND b.ready)));


ALTER VIEW public.union_pnl_inventory_published_rows OWNER TO postgres;

