--
-- TOC entry 1945 (class 1259 OID 6952803)
-- Name: v_yt_jobs_health; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_yt_jobs_health WITH (security_invoker='true') AS
 SELECT status,
    worker_id,
    count(*) AS job_count,
    min(created_at) AS oldest_created_at,
    max(completed_at) AS latest_completed_at
   FROM public.video_transcode_jobs
  WHERE (source_type = 'youtube'::text)
  GROUP BY status, worker_id
  ORDER BY status, worker_id NULLS FIRST;


