--
-- TOC entry 54487 (class 0 OID 0)
-- Dependencies: 2870
-- Name: TABLE time_bank_consume_unconfirmed; Type: COMMENT; Schema: smarter_private; Owner: postgres
--

COMMENT ON TABLE smarter_private.time_bank_consume_unconfirmed IS 'One row per fn_consume_time_bank debit whose reply the engine never got. The engine chooses attempt_id BEFORE it sends the debit, so recording it later is exactly-once and a replay charges nobody twice. Written only by fn_record_unconfirmed_time_bank_consume, as the process, never under a tournament lease. Append-only but for one settlement stamp. It records that seconds are owed and unverified; it debits nothing. 2026-09-28.';


