-- Name: collusion_tracking collusion_admin_update; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY collusion_admin_update ON public.collusion_tracking FOR UPDATE USING (((( SELECT auth.role() AS role) = 'service_role'::text) OR (EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND (profiles.role = ANY (ARRAY['admin'::text, 'owner'::text, 'super_agent'::text])))))));


